```rust
// src/main.rs
use std::path::{Path, PathBuf};
use anyhow::{Context, Result};
use clap::{Parser, Subcommand};
use sha2::{Digest, Sha256};
use tokio::fs::File;
use tokio::io::AsyncReadExt;

/// CLI asynchrone pour calculer et valider des empreintes SHA-256 de fichiers locaux.
#[derive(Parser, Debug)]
#[command(name = "sha256-cli", version, about, long_about = None)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Calcule l'empreinte SHA-256 d'un ou plusieurs fichiers
    Compute {
        /// Chemins des fichiers à analyser
        #[arg(required = true, value_name = "FICHIERS")]
        files: Vec<PathBuf>,
    },
    /// Vérifie si l'empreinte d'un fichier correspond au hash SHA-256 attendu
    Validate {
        /// Chemin du fichier à vérifier
        #[arg(value_name = "FICHIER")]
        file: PathBuf,

        /// Empreinte SHA-256 hexadécimale attendue (insensible à la casse)
        #[arg(value_name = "HASH_ATTENDU")]
        expected_hash: String,
    },
    /// Vérifie un fichier de checksums au format sha256sum (`<hash>  <fichier>`)
    Check {
        /// Chemin vers le fichier contenant les checksums
        #[arg(value_name = "CHECKSUM_FILE")]
        checksum_file: PathBuf,
    },
}

/// Calcule de manière asynchrone le hash SHA-256 d'un fichier par flux (chunks).
async fn compute_sha256(path: &Path) -> Result<String> {
    let mut file = File::open(path)
        .await
        .with_context(|| format!("Impossible d'ouvrir le fichier '{}'", path.display()))?;

    let mut hasher = Sha256::new();
    let mut buffer = [0u8; 64 * 1024]; // Buffer de 64 Ko pour la lecture par flux

    loop {
        let bytes_read = file
            .read(&mut buffer)
            .await
            .with_context(|| format!("Erreur de lecture sur le fichier '{}'", path.display()))?;

        if bytes_read == 0 {
            break;
        }

        hasher.update(&buffer[..bytes_read]);
    }

    let result = hasher.finalize();
    Ok(hex::encode(result))
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Compute { files } => {
            let mut has_error = false;
            for path in files {
                match compute_sha256(&path).await {
                    Ok(digest) => {
                        println!("{}  {}", digest, path.display());
                    }
                    Err(err) => {
                        eprintln!("Erreur pour '{}': {:#}", path.display(), err);
                        has_error = true;
                    }
                }
            }
            if has_error {
                std::process::exit(1);
            }
        }
        Commands::Validate {
            file,
            expected_hash,
        } => {
            let normalized_expected = expected_hash.trim().to_lowercase();
            // Validation de base de la chaîne hexadécimale attendue
            if normalized_expected.len() != 64 || !normalized_expected.chars().all(|c| c.is_ascii_hexdigit()) {
                anyhow::bail!(
                    "Le hash attendu '{}' n'est pas un condensat SHA-256 hexadécimal valide (64 caractères hexadécimaux requis).",
                    expected_hash
                );
            }

            let computed = compute_sha256(&file).await?;

            if computed == normalized_expected {
                println!("OK: '{}' correspond au hash SHA-256 attendu.", file.display());
            } else {
                eprintln!(
                    "ÉCHEC: '{}'\n  Attendu: {}\n  Calculé: {}",
                    file.display(),
                    normalized_expected,
                    computed
                );
                std::process::exit(1);
            }
        }
        Commands::Check { checksum_file } => {
            let content = tokio::fs::read_to_string(&checksum_file)
                .await
                .with_context(|| {
                    format!(
                        "Impossible de lire le fichier de checksums '{}'",
                        checksum_file.display()
                    )
                })?;

            let base_dir = checksum_file.parent().unwrap_or_else(|| Path::new("."));
            let mut total = 0usize;
            let mut failed = 0usize;

            for (line_num, raw_line) in content.lines().enumerate() {
                let line = raw_line.trim();
                if line.is_empty() || line.starts_with('#') {
                    continue;
                }

                // Format attendu: "<hash>  <fichier>" ou "<hash> *<fichier>"
                let mut parts = line.split_whitespace();
                let expected = match parts.next() {
                    Some(val) => val.to_lowercase(),
                    None => continue,
                };
                let relative_file_path = match parts.next() {
                    Some(val) => val.trim_start_matches('*'),
                    None => {
                        eprintln!(
                            "Avertissement: ligne {} ignorée car mal formatée ('{}')",
                            line_num + 1,
                            line
                        );
                        continue;
                    }
                };

                total += 1;
                let target_path = base_dir.join(relative_file_path);

                match compute_sha256(&target_path).await {
                    Ok(computed) => {
                        if computed == expected {
                            println!("{}: OK", relative_file_path);
                        } else {
                            eprintln!(
                                "{}: ÉCHEC (Attendu: {}, Calculé: {})",
                                relative_file_path, expected, computed
                            );
                            failed += 1;
                        }
                    }
                    Err(err) => {
                        eprintln!("{}: ERREUR ({:#})", relative_file_path, err);
                        failed += 1;
                    }
                }
            }

            if total == 0 {
                eprintln!("Avertissement: Aucune entrée valide trouvée dans le fichier de checksums.");
            } else if failed > 0 {
                eprintln!(
                    "\nVérification terminée: {} échec(s) sur {} fichier(s).",
                    failed, total
                );
                std::process::exit(1);
            } else {
                println!("\nTous les fichiers ({} au total) ont été validés avec succès.", total);
            }
        }
    }

    Ok(())
}

