```rust
// src/main.rs
use std::collections::HashMap;
use std::net::SocketAddr;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use axum::{
    extract::State,
    http::StatusCode,
    response::IntoResponse,
    routing::{get, post},
    Json, Router,
};
use clap::{Args, Parser, Subcommand};
use hex::ToHex;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use tokio::fs::File;
use tokio::io::AsyncReadExt;
use tokio::sync::{mpsc, RwLock, Semaphore};

const CHUNK_SIZE: usize = 64 * 1024; // 64 KiB buffer

#[derive(Parser, Debug)]
#[command(
    name = "sha256-async-cli",
    version,
    about = "Calculateur et validateur asynchrone d'empreintes SHA-256 avec Tokio et Axum"
)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Calcule l'empreinte SHA-256 d'un ou plusieurs fichiers locaux
    Compute(ComputeArgs),
    /// Valide l'empreinte SHA-256 de fichiers par rapport aux valeurs attendues
    Verify(VerifyArgs),
    /// Lance un serveur API HTTP Axum pour le calcul et la validation à distance
    Serve(ServeArgs),
}

#[derive(Args, Debug)]
struct ComputeArgs {
    /// Chemins des fichiers locaux à hacher
    #[arg(required = true)]
    files: Vec<PathBuf>,

    /// Niveau maximal de concurrence lors du traitement des fichiers
    #[arg(short, long, default_value_t = 4)]
    concurrency: usize,

    /// Sortie au format JSON au lieu du format sha256sum standard
    #[arg(long)]
    json: bool,
}

#[derive(Args, Debug)]
struct VerifyArgs {
    /// Chemin du fichier de manifeste contenant les empreintes (format: "<hash>  <fichier>" ou JSON)
    #[arg(short, long)]
    manifest: PathBuf,

    /// Niveau maximal de concurrence lors de la vérification
    #[arg(short, long, default_value_t = 4)]
    concurrency: usize,
}

#[derive(Args, Debug)]
struct ServeArgs {
    /// Adresse d'écoute TCP pour le serveur Axum
    #[arg(short, long, default_value = "127.0.0.1:3000")]
    bind: SocketAddr,

    /// Limite du nombre de hachages concurrents autorisés par le serveur
    #[arg(short, long, default_value_t = 8)]
    max_concurrent_jobs: usize,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct HashResult {
    pub path: String,
    pub sha256: Option<String>,
    pub error: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct VerificationResult {
    pub path: String,
    pub expected: String,
    pub actual: Option<String>,
    pub is_valid: bool,
    pub error: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ApiComputeRequest {
    pub file_path: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ApiVerifyRequest {
    pub file_path: String,
    pub expected_sha256: String,
}

#[derive(Debug, Default, Clone, Serialize, Deserialize)]
pub struct AppStats {
    pub total_hashes_computed: u64,
    pub total_hashes_verified: u64,
    pub total_errors: u64,
}

#[derive(Clone)]
struct ServerState {
    semaphore: Arc<Semaphore>,
    stats: Arc<RwLock<AppStats>>,
    log_tx: mpsc::Sender<String>,
}

/// Calcule l'empreinte SHA-256 d'un fichier de façon asynchrone par lecture en continu
async fn compute_sha256(path: &Path) -> Result<String, std::io::Error> {
    let mut file = File::open(path).await?;
    let mut hasher = Sha256::new();
    let mut buffer = vec![0u8; CHUNK_SIZE];

    loop {
        let bytes_read = file.read(&mut buffer).await?;
        if bytes_read == 0 {
            break;
        }
        hasher.update(&buffer[..bytes_read]);
    }

    let result = hasher.finalize();
    Ok(result.encode_hex::<String>())
}

/// Traite une collection de fichiers avec concurrence bornée par un Sémaphore Tokio
async fn process_files_compute(files: Vec<PathBuf>, concurrency: usize) -> Vec<HashResult> {
    let semaphore = Arc::new(Semaphore::new(concurrency));
    let mut tasks = Vec::with_capacity(files.len());

    for file_path in files {
        let sem = Arc::clone(&semaphore);
        let task = tokio::spawn(async move {
            let permit = match sem.acquire_owned().await {
                Ok(p) => p,
                Err(e) => {
                    return HashResult {
                        path: file_path.display().to_string(),
                        sha256: None,
                        error: Some(format!("Erreur d'acquisition de permis sémaphore: {e}")),
                    };
                }
            };

            let res = compute_sha256(&file_path).await;
            drop(permit);

            match res {
                Ok(hash) => HashResult {
                    path: file_path.display().to_string(),
                    sha256: Some(hash),
                    error: None,
                },
                Err(err) => HashResult {
                    path: file_path.display().to_string(),
                    sha256: None,
                    error: Some(err.to_string()),
                },
            }
        });
        tasks.push(task);
    }

    let mut results = Vec::with_capacity(tasks.len());
    for task in tasks {
        match task.await {
            Ok(item) => results.push(item),
            Err(join_err) => results.push(HashResult {
                path: "<tâche annulée>".to_string(),
                sha256: None,
                error: Some(format!("Erreur JoinHandle: {join_err}")),
            }),
        }
    }

    results
}

/// Analyse un fichier de manifeste soit au format JSON, soit au format sha256sum ("<hash>  <fichier>")
async fn parse_manifest(manifest_path: &Path) -> Result<HashMap<String, String>, String> {
    let content = tokio::fs::read_to_string(manifest_path)
        .await
        .map_err(|e| format!("Impossible de lire le manifeste {}: {e}", manifest_path.display()))?;

    // Tenter d'abord le parsing JSON
    if let Ok(entries) = serde_json::from_str::<HashMap<String, String>>(&content) {
        return Ok(entries);
    }

    // Sinon, parsing ligne par ligne format standard sha256sum
    let mut entries = HashMap::new();
    for (line_num, line) in content.lines().enumerate() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        let parts: Vec<&str> = trimmed.split_whitespace().collect();
        if parts.len() < 2 {
            return Err(format!(
                "Ligne {} invalide dans le manifeste: '{}'",
                line_num + 1,
                trimmed
            ));
        }

        let hash = parts[0].to_lowercase();
        let file_path = parts[1..].join(" ");
        entries.insert(file_path, hash);
    }

    if entries.is_empty() {
        return Err("Aucune entrée d'empreinte valide trouvée dans le manifeste".to_string());
    }

    Ok(entries)
}

/// Exécute la vérification concurrente d'un manifeste
async fn process_manifest_verification(
    manifest_entries: HashMap<String, String>,
    concurrency: usize,
) -> Vec<VerificationResult> {
    let semaphore = Arc::new(Semaphore::new(concurrency));
    let mut tasks = Vec::with_capacity(manifest_entries.len());

    for (file_str, expected_hash) in manifest_entries {
        let sem = Arc::clone(&semaphore);
        let task = tokio::spawn(async move {
            let permit = match sem.acquire_owned().await {
                Ok(p) => p,
                Err(e) => {
                    return VerificationResult {
                        path: file_str,
                        expected: expected_hash,
                        actual: None,
                        is_valid: false,
                        error: Some(format!("Erreur sémaphore: {e}")),
                    };
                }
            };

            let path = PathBuf::from(&file_str);
            let result = compute_sha256(&path).await;
            drop(permit);

            match result {
                Ok(actual_hash) => {
                    let is_valid = actual_hash.eq_ignore_ascii_case(&expected_hash);
                    VerificationResult {
                        path: file_str,
                        expected: expected_hash,
                        actual: Some(actual_hash),
                        is_valid,
                        error: None,
                    }
                }
                Err(err) => VerificationResult {
                    path: file_str,
                    expected: expected_hash,
                    actual: None,
                    is_valid: false,
                    error: Some(err.to_string()),
                },
            }
        });

        tasks.push(task);
    }

    let mut results = Vec::with_capacity(tasks.len());
    for task in tasks {
        match task.await {
            Ok(item) => results.push(item),
            Err(e) => results.push(VerificationResult {
                path: "<inconnue>".to_string(),
                expected: String::new(),
                actual: None,
                is_valid: false,
                error: Some(format!("Erreur d'exécution de la tâche: {e}")),
            }),
        }
    }

    results
}

// Handlers Axum

async fn health_check() -> impl IntoResponse {
    (StatusCode::OK, Json(serde_json::json!({ "status": "ok" })))
}

async fn get_stats(State(state): State<ServerState>) -> impl IntoResponse {
    let stats = state.stats.read().await;
    Json(stats.clone())
}

async fn api_compute_hash(
    State(state): State<ServerState>,
    Json(payload): Json<ApiComputeRequest>,
) -> impl IntoResponse {
    let permit = match state.semaphore.clone().acquire_owned().await {
        Ok(p) => p,
        Err(e) => {
            let mut stats = state.stats.write().await;
            stats.total_errors += 1;
            return (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(HashResult {
                    path: payload.file_path,
                    sha256: None,
                    error: Some(format!("Erreur acquisition concurrence: {e}")),
                }),
            );
        }
    };

    let path = PathBuf::from(&payload.file_path);
    let computation = compute_sha256(&path).await;
    drop(permit);

    let mut stats = state.stats.write().await;
    match computation {
        Ok(hash) => {
            stats.total_hashes_computed += 1;
            let _ = state
                .log_tx
                .send(format!("Hachage réussi pour {}", payload.file_path))
                .await;
            (
                StatusCode::OK,
                Json(HashResult {
                    path: payload.file_path,
                    sha256: Some(hash),
                    error: None,
                }),
            )
        }
        Err(err) => {
            stats.total_errors += 1;
            let _ = state
                .log_tx
                .send(format!(
                    "Échec de hachage pour {}: {}",
                    payload.file_path, err
                ))
                .await;
            (
                StatusCode::BAD_REQUEST,
                Json(HashResult {
                    path: payload.file_path,
                    sha256: None,
                    error: Some(err.to_string()),
                }),
            )
        }
    }
}

async fn api_verify_hash(
    State(state): State<ServerState>,
    Json(payload): Json<ApiVerifyRequest>,
) -> impl IntoResponse {
    let permit = match state.semaphore.clone().acquire_owned().await {
        Ok(p) => p,
        Err(e) => {
            let mut stats = state.stats.write().await;
            stats.total_errors += 1;
            return (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(VerificationResult {
                    path: payload.file_path,
                    expected: payload.expected_sha256,
                    actual: None,
                    is_valid: false,
                    error: Some(format!("Erreur d'acquisition de permis: {e}")),
                }),
            );
        }
    };

    let path = PathBuf::from(&payload.file_path);
    let result = compute_sha256(&path).await;
    drop(permit);

    let mut stats = state.stats.write().await;
    match result {
        Ok(actual_hash) => {
            let is_valid = actual_hash.eq_ignore_ascii_case(&payload.expected_sha256);
            stats.total_hashes_verified += 1;
            let _ = state
                .log_tx
                .send(format!(
                    "Vérification pour {}: valide = {}",
                    payload.file_path, is_valid
                ))
                .await;

            (
                StatusCode::OK,
                Json(VerificationResult {
                    path: payload.file_path,
                    expected: payload.expected_sha256,
                    actual: Some(actual_hash),
                    is_valid,
                    error: None,
                }),
            )
        }
        Err(err) => {
            stats.total_errors += 1;
            let _ = state
                .log_tx
                .send(format!(
                    "Erreur lors de la vérification de {}: {}",
                    payload.file_path, err
                ))
                .await;

            (
                StatusCode::BAD_REQUEST,
                Json(VerificationResult {
                    path: payload.file_path,
                    expected: payload.expected_sha256,
                    actual: None,
                    is_valid: false,
                    error: Some(err.to_string()),
                }),
            )
        }
    }
}

