                        (_, Some(err)) => {
                            eprintln!("ERREUR: {} -> {}", res.path, err);
                            has_error = true;
                        }
                        (None, None) => {}
                    }
                }
                if has_error {
                    std::process::exit(1);
                }
            }
        }

        Commands::Verify(args) => {
            if args.concurrency == 0 {
                eprintln!("Erreur: Le niveau de concurrence doit être supérieur à 0.");
                std::process::exit(1);
            }

            let entries = match parse_manifest(&args.manifest).await {
                Ok(entries) => entries,
                Err(err) => {
                    eprintln!("Erreur lors de la lecture du manifeste: {err}");
                    std::process::exit(1);
                }
            };

            let results = process_manifest_verification(entries, args.concurrency).await;

            let mut all_valid = true;
            for res in &results {
                if let Some(err) = &res.error {
                    eprintln!("{}: ÉCHEC ({})", res.path, err);
                    all_valid = false;
                } else if res.is_valid {
                    println!("{}: OK", res.path);
                } else {
                    let actual = res.actual.as_deref().unwrap_or("<inconnu>");
                    eprintln!(
                        "{}: ÉCHEC (attendu: {}, calculé: {})",
                        res.path, res.expected, actual
                    );
                    all_valid = false;
                }
            }

            if !all_valid {
                std::process::exit(1);
            }
        }

        Commands::Serve(args) => {
            let (log_tx, mut log_rx) = mpsc::channel::<String>(100);

            // Tâche de fond pour consommer les logs asynchrones via mpsc
            tokio::spawn(async move {
                while let Some(msg) = log_rx.recv().await {
                    tracing::info!("[ASYNC LOG] {msg}");
                }
            });

            let state = ServerState {
                semaphore: Arc::new(Semaphore::new(args.max_concurrent_jobs)),
