/// Calcule l'empreinte SHA-256 d'un fichier de façon asynchrone par lecture en continu
async fn compute_sha256(path: &Path) -> Result<String, std::io::Error> {
    let mut file = File::open(path).await?;
    let mut hasher = Sha256::new();
    let mut buffer = vec![0u8; CHUNK_SIZE];

    loop {
        let bytes_read = file.read(&mut buffer).await?;
        if bytes_read == 0 {
            break;
        }
        hasher.update(&buffer[..bytes_read]);
    }

    let result = hasher.finalize();
    Ok(result.encode_hex::<String>())
}

/// Traite une collection de fichiers avec concurrence bornée par un Sémaphore Tokio
async fn process_files_compute(files: Vec<PathBuf>, concurrency: usize) -> Vec<HashResult> {
    let semaphore = Arc::new(Semaphore::new(concurrency));
    let mut tasks = Vec::with_capacity(files.len());

    for file_path in files {
        let sem = Arc::clone(&semaphore);
        let task = tokio::spawn(async move {
            let permit = match sem.acquire_owned().await {
                Ok(p) => p,
                Err(e) => {
                    return HashResult {
                        path: file_path.display().to_string(),
                        sha256: None,
                        error: Some(format!("Erreur d'acquisition de permis sémaphore: {e}")),
                    };
                }
            };

            let res = compute_sha256(&file_path).await;
            drop(permit);

            match res {
                Ok(hash) => HashResult {
                    path: file_path.display().to_string(),
                    sha256: Some(hash),
                    error: None,
                },
                Err(err) => HashResult {
                    path: file_path.display().to_string(),
                    sha256: None,
                    error: Some(err.to_string()),
                },
            }
        });
        tasks.push(task);
    }

    let mut results = Vec::with_capacity(tasks.len());
    for task in tasks {
        match task.await {
            Ok(item) => results.push(item),
            Err(join_err) => results.push(HashResult {
                path: "<tâche annulée>".to_string(),
                sha256: None,
                error: Some(format!("Erreur JoinHandle: {join_err}")),
            }),
        }
    }

    results
}

/// Analyse un fichier de manifeste soit au format JSON, soit au format sha256sum ("<hash>  <fichier>")
async fn parse_manifest(manifest_path: &Path) -> Result<HashMap<String, String>, String> {
    let content = tokio::fs::read_to_string(manifest_path)
        .await
        .map_err(|e| format!("Impossible de lire le manifeste {}: {e}", manifest_path.display()))?;

    // Tenter d'abord le parsing JSON
    if let Ok(entries) = serde_json::from_str::<HashMap<String, String>>(&content) {
        return Ok(entries);
    }

    // Sinon, parsing ligne par ligne format standard sha256sum
    let mut entries = HashMap::new();
    for (line_num, line) in content.lines().enumerate() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        let parts: Vec<&str> = trimmed.split_whitespace().collect();
        if parts.len() < 2 {
            return Err(format!(
                "Ligne {} invalide dans le manifeste: '{}'",
                line_num + 1,
                trimmed
            ));
        }

        let hash = parts[0].to_lowercase();
        let file_path = parts[1..].join(" ");
        entries.insert(file_path, hash);
    }

    if entries.is_empty() {
        return Err("Aucune entrée d'empreinte valide trouvée dans le manifeste".to_string());
    }

    Ok(entries)
}

/// Exécute la vérification concurrente d'un manifeste
async fn process_manifest_verification(
    manifest_entries: HashMap<String, String>,
    concurrency: usize,
) -> Vec<VerificationResult> {
    let semaphore = Arc::new(Semaphore::new(concurrency));
    let mut tasks = Vec::with_capacity(manifest_entries.len());

    for (file_str, expected_hash) in manifest_entries {
        let sem = Arc::clone(&semaphore);
        let task = tokio::spawn(async move {
            let permit = match sem.acquire_owned().await {
                Ok(p) => p,
                Err(e) => {
                    return VerificationResult {
                        path: file_str,
                        expected: expected_hash,
                        actual: None,
                        is_valid: false,
                        error: Some(format!("Erreur sémaphore: {e}")),
                    };
                }
            };

            let path = PathBuf::from(&file_str);
            let result = compute_sha256(&path).await;
            drop(permit);

            match result {
                Ok(actual_hash) => {
                    let is_valid = actual_hash.eq_ignore_ascii_case(&expected_hash);
                    VerificationResult {
                        path: file_str,
                        expected: expected_hash,
                        actual: Some(actual_hash),
                        is_valid,
                        error: None,
                    }
                }
                Err(err) => VerificationResult {
                    path: file_str,
                    expected: expected_hash,
                    actual: None,
                    is_valid: false,
                    error: Some(err.to_string()),
                },
            }
        });

        tasks.push(task);
    }

    let mut results = Vec::with_capacity(tasks.len());
    for task in tasks {
        match task.await {
            Ok(item) => results.push(item),
            Err(e) => results.push(VerificationResult {
                path: "<inconnue>".to_string(),
                expected: String::new(),
                actual: None,
                is_valid: false,
                error: Some(format!("Erreur d'exécution de la tâche: {e}")),
            }),
        }
    }

    results
}

