        }

        let expected_hash = parts[0];
        let file_subpath = parts[1].trim_start_matches('*');
        let full_path = base_dir.join(file_subpath);

        match compute_sha256_stream(&full_path, |_, _| {}).await {
            Ok(computed) => {
                if computed.eq_ignore_ascii_case(expected_hash) {
                    println!("{}: OK", full_path.display());
                } else {
                    eprintln!("{}: ÉCHEC (empreinte différente)", full_path.display());
                    all_valid = false;
                }
            }
            Err(e) => {
                eprintln!("{}: ÉCHEC (erreur: {:#})", full_path.display(), e);
                all_valid = false;
            }
        }
    }

    Ok(all_valid)
}

/// Exécute l'application en mode TUI
async fn run_tui_app(files: Vec<PathBuf>, concurrency: usize) -> Result<()> {
    enable_raw_mode().context("Activation du raw mode terminal impossible")?;
    let mut stdout_handle = stdout();
    execute!(stdout_handle, EnterAlternateScreen).context("Passage sur alternate screen impossible")?;
    let backend = CrosstermBackend::new(stdout_handle);
    let mut terminal = Terminal::new(backend).context("Initialisation du terminal Ratatui impossible")?;

    let res = tui_event_loop(&mut terminal, files, concurrency).await;

    // Restauration garantie du terminal
    let _ = disable_raw_mode();
    let _ = execute!(terminal.backend_mut(), LeaveAlternateScreen);
    let _ = terminal.show_cursor();

    res
}

async fn tui_event_loop<B: ratatui::backend::Backend>(
    terminal: &mut Terminal<B>,
    files: Vec<PathBuf>,
    concurrency: usize,
) -> Result<()> {
    let mut tasks: Vec<FileTask> = files
        .into_iter()
        .map(|path| FileTask {
            path,
            status: TaskStatus::Pending,
        })
        .collect();

    let (tx, mut rx) = mpsc::channel::<WorkerMessage>(100);
    let semaphore = Arc::new(Semaphore::new(concurrency.max(1)));

    // Lancement des workers asynchrones tokio
    for (index, task) in tasks.iter().enumerate() {
        let task_path = task.path.clone();
        let task_tx = tx.clone();
        let sem = semaphore.clone();

        tokio::spawn(async move {
            let _permit = match sem.acquire().await {
                Ok(p) => p,
                Err(_) => return,
            };

            let tx_clone = task_tx.clone();
            let compute_res = compute_sha256_stream(&task_path, move |proc, tot| {
                let _ = tx_clone.try_send(WorkerMessage::Progress {
                    index,
                    bytes_processed: proc,
                    total_bytes: tot,
                });
            })
            .await;

            match compute_res {
                Ok(hash) => {
                    let _ = task_tx.send(WorkerMessage::Done { index, hash }).await;
                }
                Err(e) => {
                    let _ = task_tx.send(WorkerMessage::Error {
                        index,
                        error: e.to_string(),
                    }).await;
                }
            }
        });
    }

    drop(tx); // Fermeture du sender racine pour que rx se termine quand tous les workers ont fini

    let mut event_stream = crossterm::event::EventStream::new();
    let mut list_state = ListState::default();
    if !tasks.is_empty() {
        list_state.select(Some(0));
    }

    let mut ticker = tokio::time::interval(Duration::from_millis(50));

    loop {
        terminal.draw(|f| {
            render_ui(f, &tasks, &mut list_state);
        })?;

        tokio::select! {
            _ = ticker.tick() => {
                // Rafraîchissement périodique pour la fluidité
            }
            worker_msg = rx.recv() => {
                if let Some(msg) = worker_msg {
                    match msg {
                        WorkerMessage::Progress { index, bytes_processed, total_bytes } => {
                            if let Some(task) = tasks.get_mut(index) {
                                task.status = TaskStatus::Hashing { bytes_processed, total_bytes };
                            }
                        }
                        WorkerMessage::Done { index, hash } => {
                            if let Some(task) = tasks.get_mut(index) {
                                task.status = TaskStatus::Completed { hash };
                            }
                        }
                        WorkerMessage::Error { index, error } => {
                            if let Some(task) = tasks.get_mut(index) {
                                task.status = TaskStatus::Failed { error };
                            }
                        }
                    }
                }
            }
            maybe_event = event_stream.next() => {
                if let Some(Ok(event)) = maybe_event {
                    if let Event::Key(key) = event {
                        if key.kind == KeyEventKind::Press {
                            match key.code {
                                KeyCode::Char('q') | KeyCode::Esc => break,
                                KeyCode::Up | KeyCode::Char('k') => {
                                    if !tasks.is_empty() {
                                        let current = list_state.selected().unwrap_or(0);
                                        let next = if current == 0 { tasks.len() - 1 } else { current - 1 };
                                        list_state.select(Some(next));
                                    }
                                }
                                KeyCode::Down | KeyCode::Char('j') => {
                                    if !tasks.is_empty() {
                                        let current = list_state.selected().unwrap_or(0);
                                        let next = if current + 1 >= tasks.len() { 0 } else { current + 1 };
                                        list_state.select(Some(next));
                                    }
                                }
                                _ => {}
                            }
                        }
                    }
                }
            }
        }
    }

    Ok(())
}

fn render_ui(frame: &mut ratatui::Frame, tasks: &[FileTask], list_state: &mut ListState) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // Header & gauge globale
            Constraint::Min(6),    // Liste des fichiers
            Constraint::Length(5), // Détails du fichier sélectionné
            Constraint::Length(2), // Barre d'aide / raccourcis
        ])
        .split(frame.area());

    // Calcul de la progression globale
    let total_tasks = tasks.len();
    let completed_or_failed = tasks
        .iter()
        .filter(|t| matches!(t.status, TaskStatus::Completed { .. } | TaskStatus::Failed { .. }))
        .count();
    let progress_ratio = if total_tasks == 0 {
        1.0
    } else {
        completed_or_failed as f64 / total_tasks as f64
    };

    let global_gauge = Gauge::default()
        .block(
            Block::default()
                .borders(Borders::ALL)
                .title(" Progression Globale (Fichiers traités) "),
        )
        .gauge_style(
            Style::default()
                .fg(Color::Cyan)
                .bg(Color::DarkGray)
                .add_modifier(Modifier::BOLD),
        )
        .ratio(progress_ratio)
        .label(format!("{}/{} terminés", completed_or_failed, total_tasks));

    frame.render_widget(global_gauge, chunks[0]);

    // Liste des fichiers
    let items: Vec<ListItem> = tasks
        .iter()
        .map(|task| {
            let filename = task
                .path
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or_else(|| task.path.to_str().unwrap_or("Inconnu"));

            let (status_badge, status_style) = match &task.status {
                TaskStatus::Pending => (
                    Span::styled("[EN ATTENTE]", Style::default().fg(Color::Yellow)),
                    Style::default(),
                ),
                TaskStatus::Hashing {
                    bytes_processed,
                    total_bytes,
                } => {
                    let percent = if *total_bytes > 0 {
                        (*bytes_processed as f64 / *total_bytes as f64 * 100.0) as u32
                    } else {
                        100
                    };
                    (
                        Span::styled(
                            format!("[EN COURS {}%]", percent),
                            Style::default().fg(Color::Blue).add_modifier(Modifier::BOLD),
                        ),
                        Style::default(),
                    )
                }
                TaskStatus::Completed { .. } => (
                    Span::styled("[TERMINÉ]", Style::default().fg(Color::Green).add_modifier(Modifier::BOLD)),
                    Style::default(),
                ),
                TaskStatus::Failed { .. } => (
                    Span::styled("[ERREUR]", Style::default().fg(Color::Red).add_modifier(Modifier::BOLD)),
                    Style::default(),
                ),
            };

            let line = Line::from(vec![
                status_badge,
                Span::raw(" "),
                Span::styled(filename, Style::default().add_modifier(Modifier::BOLD)),
                Span::raw(" ("),
                Span::styled(task.path.display().to_string(), Style::default().fg(Color::DarkGray)),
                Span::raw(")"),
            ]);

            ListItem::new(line).style(status_style)
        })
        .collect();

    let list_widget = List::new(items)
        .block(Block::default().borders(Borders::ALL).title(" Fichiers à traiter "))
        .highlight_style(
            Style::default()
                .bg(Color::Indexed(238))
                .fg(Color::White)
                .add_modifier(Modifier::BOLD),
        )
        .highlight_symbol("▶ ");

    frame.render_stateful_widget(list_widget, chunks[1], list_state);

    // Panneau de détails
    let selected_index = list_state.selected().unwrap_or(0);
    let details_content = if let Some(selected_task) = tasks.get(selected_index) {
        match &selected_task.status {
            TaskStatus::Pending => vec![
                Line::from(vec![Span::raw("Fichier: "), Span::styled(selected_task.path.display().to_string(), Style::default().fg(Color::Cyan))]),
                Line::from(vec![Span::raw("Statut : "), Span::styled("En attente de disponibilité d'un worker", Style::default().fg(Color::Yellow))]),
            ],
            TaskStatus::Hashing { bytes_processed, total_bytes } => vec![
                Line::from(vec![Span::raw("Fichier: "), Span::styled(selected_task.path.display().to_string(), Style::default().fg(Color::Cyan))]),
                Line::from(vec![Span::raw("Statut : "), Span::styled(format!("Traitement: {} / {} octets", bytes_processed, total_bytes), Style::default().fg(Color::Blue))]),
            ],
            TaskStatus::Completed { hash } => vec![
                Line::from(vec![Span::raw("Fichier: "), Span::styled(selected_task.path.display().to_string(), Style::default().fg(Color::Cyan))]),
                Line::from(vec![Span::raw("SHA-256: "), Span::styled(hash.clone(), Style::default().fg(Color::Green).add_modifier(Modifier::BOLD))]),
            ],
            TaskStatus::Failed { error } => vec![
                Line::from(vec![Span::raw("Fichier: "), Span::styled(selected_task.path.display().to_string(), Style::default().fg(Color::Cyan))]),
                Line::from(vec![Span::raw("Erreur : "), Span::styled(error.clone(), Style::default().fg(Color::Red))]),
            ],
        }
    } else {
        vec![Line::from(Span::raw("Aucun élément sélectionné"))]
    };

    let details_widget = Paragraph::new(details_content)
        .block(Block::default().borders(Borders::ALL).title(" Détails de la sélection "));
    frame.render_widget(details_widget, chunks[2]);

    // Barre d'aide
    let help_bar = Paragraph::new(" [q/Esc] Quitter | [↑/k] Élément précédent | [↓/j] Élément suivant")
        .style(Style::default().fg(Color::Black).bg(Color::White));
    frame.render_widget(help_bar, chunks[3]);
}

