```rust
// src/main.rs
use std::path::{Path, PathBuf};
use std::sync::Arc;

use anyhow::{bail, Context, Result};
use arrow_array::{ArrayRef, Int64Array, RecordBatch, StringArray};
use arrow_schema::{DataType, Field, Schema};
use clap::{Args, Parser, Subcommand, ValueEnum};
use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;
use parquet::arrow::AsyncArrowWriter;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use tokio::fs::File;
use tokio::io::AsyncReadExt;
use tokio::sync::Semaphore;
use walkdir::WalkDir;

#[derive(Parser, Debug)]
#[command(
    name = "sha256-inspector",
    author,
    version,
    about = "Outil CLI asynchrone pour calculer, exporter et valider les empreintes SHA-256 (JSON / Parquet)",
    long_about = None
)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Calcule les empreintes SHA-256 de fichiers ou répertoires et les exporte
    Compute(ComputeArgs),
    /// Valide l'intégrité des fichiers locaux à partir d'un fichier manifeste (JSON ou Parquet)
    Verify(VerifyArgs),
}

#[derive(Copy, Clone, Debug, PartialEq, Eq, ValueEnum)]
enum ExportFormat {
    Json,
    Parquet,
}

#[derive(Args, Debug)]
struct ComputeArgs {
    /// Chemins des fichiers ou dossiers à analyser
    #[arg(required = true)]
    paths: Vec<PathBuf>,

    /// Fichier de sortie (manifeste)
    #[arg(short, long)]
    output: Option<PathBuf>,

    /// Format de sortie si --output est spécifié
    #[arg(short, long, value_enum, default_value_t = ExportFormat::Json)]
    format: ExportFormat,

    /// Nombre maximum de tâches asynchrones parallèles
    #[arg(short = 'j', long, default_value_t = 8)]
    concurrency: usize,
}

#[derive(Args, Debug)]
struct VerifyArgs {
    /// Chemin du manifeste de référence (.json ou .parquet)
    #[arg(short, long)]
    manifest: PathBuf,

    /// Format du manifeste (détecté par extension si omis)
    #[arg(short, long, value_enum)]
    format: Option<ExportFormat>,

    /// Nombre de tâches asynchrones parallèles pour la vérification
    #[arg(short = 'j', long, default_value_t = 8)]
    concurrency: usize,
}

#[derive(Serialize, Deserialize, Debug, Clone, PartialEq, Eq)]
struct FileDigest {
    path: String,
    sha256: String,
    size_bytes: u64,
}

/// Calcule le SHA-256 d'un fichier de façon asynchrone par chunks
async fn compute_sha256(path: &Path) -> Result<FileDigest> {
    let mut file = File::open(path)
        .await
        .with_context(|| format!("Impossible d'ouvrir le fichier {}", path.display()))?;

    let metadata = file
        .metadata()
        .await
        .with_context(|| format!("Impossible de lire les métadonnées de {}", path.display()))?;

    let mut hasher = Sha256::new();
    let mut buffer = [0u8; 64 * 1024]; // Buffer de 64 KiB

    loop {
        let bytes_read = file
            .read(&mut buffer)
            .await
            .with_context(|| format!("Erreur lors de la lecture de {}", path.display()))?;
        if bytes_read == 0 {
            break;
        }
        hasher.update(&buffer[..bytes_read]);
    }

    let hash_result = hasher.finalize();
    let hex_hash = hex::encode(hash_result);

    Ok(FileDigest {
        path: path.to_string_lossy().to_string(),
        sha256: hex_hash,
        size_bytes: metadata.len(),
    })
}

/// Parcourt les chemins fournis et rassemble la liste de tous les fichiers existants
fn collect_files(paths: &[PathBuf]) -> Vec<PathBuf> {
    let mut file_list = Vec::new();
    for target in paths {
        if target.is_file() {
            file_list.push(target.clone());
        } else if target.is_dir() {
            for entry in WalkDir::new(target).into_iter().filter_map(|e| e.ok()) {
                if entry.file_type().is_file() {
                    file_list.push(entry.into_path());
                }
            }
        }
    }
    file_list.sort();
    file_list.dedup();
    file_list
}

/// Calcule les hashs de manière concurrente avec contrôle par sémaphore
async fn process_files_concurrently(
    files: Vec<PathBuf>,
    concurrency: usize,
) -> Vec<Result<FileDigest>> {
    let semaphore = Arc::new(Semaphore::new(concurrency.max(1)));
    let mut handles = Vec::with_capacity(files.len());

    for file_path in files {
        let permit = Arc::clone(&semaphore);
        let handle = tokio::spawn(async move {
            let _guard = match permit.acquire().await {
                Ok(g) => g,
                Err(e) => bail!("Erreur de sémaphore tokio: {e}"),
            };
            compute_sha256(&file_path).await
        });
        handles.push(handle);
    }

    let mut results = Vec::with_capacity(handles.len());
    for handle in handles {
        match handle.await {
            Ok(res) => results.push(res),
            Err(join_err) => results.push(Err(anyhow::anyhow!("Erreur de tâche tokio: {join_err}"))),
        }
    }

    results
}

/// Écrit la liste des empreintes au format Parquet
async fn export_to_parquet(digests: &[FileDigest], output_path: &Path) -> Result<()> {
    let schema = Arc::new(Schema::new(vec![
        Field::new("path", DataType::Utf8, false),
        Field::new("sha256", DataType::Utf8, false),
        Field::new("size_bytes", DataType::Int64, false),
    ]));

    let paths_array = StringArray::from(
        digests
            .iter()
            .map(|d| d.path.as_str())
            .collect::<Vec<&str>>(),
    );
    let hashes_array = StringArray::from(
        digests
            .iter()
            .map(|d| d.sha256.as_str())
            .collect::<Vec<&str>>(),
    );
    let sizes_array = Int64Array::from(
        digests
            .iter()
            .map(|d| d.size_bytes as i64)
            .collect::<Vec<i64>>(),
    );

    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![
            Arc::new(paths_array) as ArrayRef,
            Arc::new(hashes_array) as ArrayRef,
            Arc::new(sizes_array) as ArrayRef,
        ],
    )?;

    let file = File::create(output_path)
        .await
        .with_context(|| format!("Impossible de créer {}", output_path.display()))?;

    let mut writer = AsyncArrowWriter::try_new(file, schema, None)?;
    writer.write(&batch).await?;
    writer.close().await?;

    Ok(())
}

/// Lit la liste des empreintes depuis un fichier Parquet
fn read_from_parquet(path: &Path) -> Result<Vec<FileDigest>> {
    let file = std::fs::File::open(path)
        .with_context(|| format!("Impossible d'ouvrir {}", path.display()))?;

    let builder = ParquetRecordBatchReaderBuilder::try_new(file)?;
    let mut reader = builder.build()?;
    let mut digests = Vec::new();

    while let Some(batch_result) = reader.next() {
        let batch = batch_result?;
        let path_col = batch
            .column(0)
            .as_any()
            .downcast_ref::<StringArray>()
            .context("Format invalide pour la colonne 'path'")?;
        let hash_col = batch
            .column(1)
            .as_any()
            .downcast_ref::<StringArray>()
            .context("Format invalide pour la colonne 'sha256'")?;
        let size_col = batch
            .column(2)
            .as_any()
            .downcast_ref::<Int64Array>()
            .context("Format invalide pour la colonne 'size_bytes'")?;

        for i in 0..batch.num_rows() {
            digests.push(FileDigest {
                path: path_col.value(i).to_string(),
                sha256: hash_col.value(i).to_string(),
                size_bytes: size_col.value(i) as u64,
            });
        }
    }

    Ok(digests)
}

/// Lit la liste des empreintes depuis un fichier JSON
async fn read_from_json(path: &Path) -> Result<Vec<FileDigest>> {
    let content = tokio::fs::read_to_string(path)
        .await
        .with_context(|| format!("Impossible de lire le fichier {}", path.display()))?;
    let digests: Vec<FileDigest> = serde_json::from_str(&content)
        .with_context(|| "Erreur lors de la désérialisation du JSON")?;
    Ok(digests)
}

/// Traitement de la commande `compute`
async fn handle_compute(args: ComputeArgs) -> Result<()> {
    let files = collect_files(&args.paths);
    if files.is_empty() {
        println!("Aucun fichier trouvé dans les chemins spécifiés.");
        return Ok(());
    }

    println!(
        "Calcul des empreintes SHA-256 pour {} fichier(s) (concurrence max: {})...",
        files.len(),
        args.concurrency
    );

    let raw_results = process_files_concurrently(files, args.concurrency).await;

    let mut successful_digests = Vec::new();
    let mut error_count = 0usize;

    for res in raw_results {
        match res {
            Ok(digest) => successful_digests.push(digest),
            Err(e) => {
                eprintln!("Erreur lors du hachage : {e:#}");
                error_count += 1;
            }
        }
    }

    if let Some(out_path) = args.output {
        match args.format {
            ExportFormat::Json => {
                let json_data = serde_json::to_string_pretty(&successful_digests)
                    .context("Échec de la sérialisation en JSON")?;
                tokio::fs::write(&out_path, json_data)
                    .await
                    .with_context(|| format!("Échec d'écriture de {}", out_path.display()))?;
                println!("Résultats exportés en JSON dans {}", out_path.display());
            }
            ExportFormat::Parquet => {
                export_to_parquet(&successful_digests, &out_path).await?;
                println!("Résultats exportés en Parquet dans {}", out_path.display());
            }
        }
    } else {
        let json_stdout = serde_json::to_string_pretty(&successful_digests)?;
        println!("{json_stdout}");
    }

    if error_count > 0 {
        bail!("{error_count} erreur(s) rencontrée(s) pendant le calcul.");
    }

    Ok(())
}

/// Traitement de la commande `verify`
async fn handle_verify(args: VerifyArgs) -> Result<()> {
    let format = match args.format {
        Some(fmt) => fmt,
        None => {
            let ext = args
                .manifest
                .extension()
                .and_then(|s| s.to_str())
                .unwrap_or("")
                .to_lowercase();
            if ext == "parquet" {
                ExportFormat::Parquet
            } else {
                ExportFormat::Json
            }
        }
    };

    println!(
        "Chargement du manifeste [{:?}] : {}...",
        format,
        args.manifest.display()
    );

    let expected_digests = match format {
        ExportFormat::Json => read_from_json(&args.manifest).await?,
        ExportFormat::Parquet => read_from_parquet(&args.manifest)?,
    };

    println!(
        "Validation de {} fichier(s) (concurrence max: {})...",
        expected_digests.len(),
        args.concurrency
    );

    let semaphore = Arc::new(Semaphore::new(args.concurrency.max(1)));
    let mut tasks = Vec::with_capacity(expected_digests.len());

    for expected in expected_digests {
        let sem = Arc::clone(&semaphore);
        let task = tokio::spawn(async move {
            let _guard = match sem.acquire().await {
                Ok(g) => g,
                Err(e) => return Err(anyhow::anyhow!("Erreur de sémaphore tokio: {e}")),
            };

            let path = PathBuf::from(&expected.path);
            if !path.exists() {
                return Ok((expected, Err(anyhow::anyhow!("Fichier introuvable"))));
            }

            match compute_sha256(&path).await {
                Ok(current) => {
                    if current.sha256.to_lowercase() == expected.sha256.to_lowercase() {
                        Ok((expected, Ok(())))
                    } else {
                        let err_msg = format!(
                            "Empreinte corrompue (attendu: {}, calculé: {})",
                            expected.sha256,
                            current.sha256
                        );
                        Ok((expected, Err(anyhow::anyhow!(err_msg))))
                    }
                }
                Err(e) => Ok((expected, Err(e))),
            }
        });
        tasks.push(task);
    }

    let mut passed = 0usize;
    let mut failed = 0usize;

    for task in tasks {
        match task.await {
            Ok(Ok((item, Ok(())))) => {
                println!(" [OK] {}", item.path);
                passed += 1;
            }
            Ok(Ok((item, Err(err)))) => {
                eprintln!(" [ÉCHEC] {} : {:#}", item.path, err);
                failed += 1;
            }
            Ok(Err(task_err)) => {
                eprintln!(" [ERREUR SYSTÈME] {:#}", task_err);
                failed += 1;
            }
            Err(join_err) => {
                eprintln!(" [ERREUR WORKER] {:#}", join_err);
                failed += 1;
            }
        }
    }

    println!("\nBilan de validation : {passed} validé(s), {failed} échec(s).");

    if failed > 0 {
        bail!("La validation a échoué pour {failed} fichier(s).");
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Compute(args) => handle_compute(args).await?,
        Commands::Verify(args) => handle_verify(args).await?,
    }

    Ok(())
}

