}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FileHashContext {
    pub path: String,
    pub size_bytes: u64,
    pub sha256: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct VerificationContext {
    pub path: String,
    pub expected_sha256: String,
    pub actual_sha256: String,
    pub matches: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ReportContext {
    pub report_title: String,
    pub items: Vec<FileHashContext>,
}

struct AppState {
    tera: tera::Tera,
    report: ReportContext,
}

/// Calcule de manière asynchrone par streaming l'empreinte SHA-256 d'un fichier.
async fn compute_sha256(path: &Path) -> Result<FileHashContext> {
    let mut file = File::open(path)
        .await
        .with_context(|| format!("Impossible d'ouvrir le fichier '{}'", path.display()))?;

    let metadata = file
        .metadata()
        .await
        .with_context(|| format!("Impossible de lire les métadonnées de '{}'", path.display()))?;

    let mut hasher = Sha256::new();
    let mut buffer = vec![0u8; BUFFER_SIZE];

    loop {
        let bytes_read = file
            .read(&mut buffer)
            .await
            .with_context(|| format!("Erreur lors de la lecture du fichier '{}'", path.display()))?;

        if bytes_read == 0 {
            break;
        }

        hasher.update(&buffer[..bytes_read]);
    }

    let hash_result = hasher.finalize();
    let hash_hex = hex::encode(hash_result);

    Ok(FileHashContext {
        path: path.display().to_string(),
        size_bytes: metadata.len(),
        sha256: hash_hex,
    })
}

async fn handle_hash(args: HashArgs) -> Result<()> {
    let mut results = Vec::new();

    for file_path in &args.files {
        match compute_sha256(file_path).await {
            Ok(context) => {
                if !args.json {
                    println!("{}  {}", context.sha256, context.path);
                }
                results.push(context);
            }
            Err(err) => {
                error!("Erreur pour '{}': {:#}", file_path.display(), err);
                return Err(err);
            }
        }
    }

    if args.json {
        let json_output = serde_json::to_string_pretty(&results)
            .context("Échec de la sérialisation JSON des empreintes")?;
        println!("{}", json_output);
    }

    Ok(())
}

async fn handle_verify(args: VerifyArgs) -> Result<()> {
    let context = compute_sha256(&args.file).await?;
    let normalized_expected = args.expected_hash.trim().to_lowercase();
    let is_valid = context.sha256.eq_ignore_ascii_case(&normalized_expected);

    let verify_context = VerificationContext {
        path: context.path.clone(),
        expected_sha256: normalized_expected,
        actual_sha256: context.sha256,
        matches: is_valid,
    };

    if args.json {
        let json_output = serde_json::to_string_pretty(&verify_context)
