```rust
// src/main.rs
use std::fs::File;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::SystemTime;

use anyhow::{bail, Context, Result};
use arrow::array::{ArrayRef, Int64Array, RecordBatch, StringArray};
use arrow::datatypes::{DataType, Field, Schema};
use clap::{Args, Parser, Subcommand};
use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;
use parquet::arrow::ArrowWriter;
use parquet::basic::Compression;
use parquet::file::properties::WriterProperties;
use sha2::{Digest, Sha256};
use tokio::fs::File as TokioFile;
use tokio::io::{AsyncReadExt, BufReader};
use tokio::sync::Semaphore;

const BUFFER_CAPACITY: usize = 64 * 1024; // Buffer de lecture 64 Ko

/// Représentation en mémoire d'un fichier et de son empreinte calculée
#[derive(Debug, Clone)]
pub struct FileChecksumRecord {
    pub path: String,
    pub sha256: String,
    pub file_size: i64,
    pub timestamp: i64,
}

#[derive(Parser, Debug)]
#[command(
    name = "sha256-parquet-validator",
    version,
    about = "Outil asynchrone CLI pour calculer et valider des empreintes SHA-256 avec stockage Parquet",
    long_about = None
)]
pub struct Cli {
    #[command(subcommand)]
    pub command: Commands,
}

#[derive(Subcommand, Debug)]
pub enum Commands {
    /// Calcule les empreintes SHA-256 de fichiers locaux et les enregistre optionnellement dans un fichier Parquet
    Compute(ComputeArgs),
    /// Valide l'intégrité des fichiers locaux à partir d'un fichier Parquet existant
    Validate(ValidateArgs),
}

#[derive(Args, Debug)]
pub struct ComputeArgs {
    /// Liste des chemins de fichiers ou répertoires à analyser
    #[arg(required = true)]
    pub paths: Vec<PathBuf>,

    /// Fichier de sortie Parquet où sauvegarder les empreintes (optionnel)
    #[arg(short, long)]
    pub output: Option<PathBuf>,

    /// Analyse récursive des dossiers spécifiés
    #[arg(short, long, default_value_t = false)]
    pub recursive: bool,

    /// Nombre maximum de fichiers traités simultanément
    #[arg(short, long, default_value_t = num_cpus())]
    pub concurrency: usize,
}

#[derive(Args, Debug)]
pub struct ValidateArgs {
    /// Chemin vers le fichier Parquet contenant les empreintes de référence
    #[arg(short, long, required = true)]
    pub input: PathBuf,

    /// Nombre maximum de validations simultanées
    #[arg(short, long, default_value_t = num_cpus())]
    pub concurrency: usize,
}

fn num_cpus() -> usize {
    std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(4)
}

/// Calcule l'empreinte SHA-256 d'un fichier de manière asynchrone et bufferisée
pub async fn compute_sha256(path: &Path) -> Result<(String, i64)> {
    let file = TokioFile::open(path)
        .await
        .with_context(|| format!("Impossible d'ouvrir le fichier '{}'", path.display()))?;

    let metadata = file
        .metadata()
        .await
        .with_context(|| format!("Impossible de lire les métadonnées de '{}'", path.display()))?;

    let file_size = metadata.len() as i64;

    let mut reader = BufReader::with_capacity(BUFFER_CAPACITY, file);
    let mut hasher = Sha256::new();
    let mut buffer = vec![0u8; BUFFER_CAPACITY];

    loop {
        let bytes_read = reader
            .read(&mut buffer)
            .await
            .with_context(|| format!("Erreur de lecture sur '{}'", path.display()))?;

        if bytes_read == 0 {
            break;
        }

        hasher.update(&buffer[..bytes_read]);
    }

    let hash_result = hasher.finalize();
    Ok((hex::encode(hash_result), file_size))
}

/// Collecte les chemins de fichiers à analyser
pub fn collect_files(paths: &[PathBuf], recursive: bool) -> Result<Vec<PathBuf>> {
    let mut files = Vec::new();

    for path in paths {
        if !path.exists() {
            eprintln!("Avertissement: Le chemin '{}' n'existe pas.", path.display());
            continue;
        }

        if path.is_file() {
            files.push(path.clone());
        } else if path.is_dir() {
            collect_dir_files(path, recursive, &mut files)?;
        }
    }

    Ok(files)
}

fn collect_dir_files(dir: &Path, recursive: bool, files: &mut Vec<PathBuf>) -> Result<()> {
    for entry in std::fs::read_dir(dir).with_context(|| format!("Erreur lors de la lecture du dossier '{}'", dir.display()))? {
        let entry = entry?;
        let entry_path = entry.path();
        if entry_path.is_file() {
            files.push(entry_path);
        } else if recursive && entry_path.is_dir() {
            collect_dir_files(&entry_path, recursive, files)?;
        }
    }
    Ok(())
}

/// Génère le schéma Apache Arrow pour le stockage des empreintes
pub fn create_arrow_schema() -> Arc<Schema> {
    Arc::new(Schema::new(vec![
        Field::new("path", DataType::Utf8, false),
        Field::new("sha256", DataType::Utf8, false),
        Field::new("file_size", DataType::Int64, false),
        Field::new("timestamp", DataType::Int64, false),
    ]))
}

/// Écrit les enregistrements d'empreintes dans un fichier Apache Parquet
pub fn write_to_parquet(records: &[FileChecksumRecord], output_path: &Path) -> Result<()> {
    let schema = create_arrow_schema();

    let paths: Vec<&str> = records.iter().map(|r| r.path.as_str()).collect();
    let hashes: Vec<&str> = records.iter().map(|r| r.sha256.as_str()).collect();
    let sizes: Vec<i64> = records.iter().map(|r| r.file_size).collect();
    let timestamps: Vec<i64> = records.iter().map(|r| r.timestamp).collect();

    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![
            Arc::new(StringArray::from(paths)) as ArrayRef,
            Arc::new(StringArray::from(hashes)) as ArrayRef,
            Arc::new(Int64Array::from(sizes)) as ArrayRef,
            Arc::new(Int64Array::from(timestamps)) as ArrayRef,
        ],
    ).context("Échec de création du RecordBatch Arrow")?;

    let file = File::create(output_path)
        .with_context(|| format!("Impossible de créer le fichier de sortie '{}'", output_path.display()))?;

    let props = WriterProperties::builder()
        .set_compression(Compression::SNAPPY)
        .build();

    let mut writer = ArrowWriter::try_new(file, schema, Some(props))
        .context("Échec d'initialisation du rédacteur Parquet")?;

    writer.write(&batch).context("Échec d'écriture du RecordBatch dans Parquet")?;
    writer.close().context("Échec de finalisation du fichier Parquet")?;

    Ok(())
}

/// Lit les enregistrements d'empreintes depuis un fichier Apache Parquet
pub fn read_from_parquet(input_path: &Path) -> Result<Vec<FileChecksumRecord>> {
    let file = File::open(input_path)
        .with_context(|| format!("Impossible d'ouvrir le fichier Parquet '{}'", input_path.display()))?;

    let builder = ParquetRecordBatchReaderBuilder::try_new(file)
        .context("Échec de création du lecteur Parquet")?;

    let mut reader = builder.build().context("Échec d'initialisation du lecteur de RecordBatch")?;
    let mut records = Vec::new();

    while let Some(batch_result) = reader.next() {
        let batch = batch_result.context("Erreur lors de la lecture d'un RecordBatch Parquet")?;

        let paths = batch
            .column(0)
            .as_any()
            .downcast_ref::<StringArray>()
            .context("Colonne 0 (path) invalide ou absente")?;
        let hashes = batch
            .column(1)
            .as_any()
            .downcast_ref::<StringArray>()
            .context("Colonne 1 (sha256) invalide ou absente")?;
        let sizes = batch
            .column(2)
            .as_any()
            .downcast_ref::<Int64Array>()
            .context("Colonne 2 (file_size) invalide ou absente")?;
        let timestamps = batch
            .column(3)
            .as_any()
            .downcast_ref::<Int64Array>()
            .context("Colonne 3 (timestamp) invalide ou absente")?;

        for i in 0..batch.num_rows() {
            records.push(FileChecksumRecord {
                path: paths.value(i).to_string(),
                sha256: hashes.value(i).to_string(),
                file_size: sizes.value(i),
                timestamp: timestamps.value(i),
            });
        }
    }

    Ok(records)
}

/// Traite la sous-commande `compute`
async fn handle_compute(args: ComputeArgs) -> Result<()> {
    let files = collect_files(&args.paths, args.recursive)?;

    if files.is_empty() {
        println!("Aucun fichier trouvé pour le calcul d'empreinte.");
        return Ok(());
    }

    println!("Analyse de {} fichier(s) avec une concurrence de {}...", files.len(), args.concurrency);

    let semaphore = Arc::new(Semaphore::new(args.concurrency));
    let now = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs() as i64;

    let mut tasks = Vec::new();

    for path in files {
        let sem = semaphore.clone();
        let task = tokio::spawn(async move {
            let _permit = sem.acquire().await.expect("Sémaphore fermé inopinément");
            match compute_sha256(&path).await {
                Ok((sha256, file_size)) => {
                    let display_path = path.to_string_lossy().to_string();
                    println!("OK: {} -> {}", display_path, sha256);
                    Some(FileChecksumRecord {
                        path: display_path,
                        sha256,
                        file_size,
                        timestamp: now,
                    })
                }
                Err(err) => {
                    eprintln!("ERREUR sur '{}': {:#}", path.display(), err);
                    None
                }
            }
        });
        tasks.push(task);
    }

    let mut records = Vec::new();
    for task in tasks {
        if let Ok(Some(record)) = task.await {
            records.push(record);
        }
    }

    if let Some(out_path) = args.output {
        println!("Écriture de {} empreinte(s) dans le fichier Parquet '{}'...", records.len(), out_path.display());
        write_to_parquet(&records, &out_path)?;
        println!("Enregistrement terminé avec succès.");
    }

    Ok(())
}

/// Traite la sous-commande `validate`
async fn handle_validate(args: ValidateArgs) -> Result<()> {
    println!("Chargement du manifeste Parquet '{}'...", args.input.display());
    let records = read_from_parquet(&args.input)?;

    if records.is_empty() {
        println!("Le fichier Parquet ne contient aucun enregistrement.");
        return Ok(());
    }

    println!("Validation de {} fichier(s) avec une concurrence de {}...", records.len(), args.concurrency);

    let semaphore = Arc::new(Semaphore::new(args.concurrency));
    let mut tasks = Vec::new();

    for record in records {
        let sem = semaphore.clone();
        let task = tokio::spawn(async move {
            let _permit = sem.acquire().await.expect("Sémaphore fermé inopinément");
            let path = PathBuf::from(&record.path);

            if !path.exists() {
                eprintln!("[DISPARU] '{}' n'existe plus sur le disque.", record.path);
                return false;
            }

            match compute_sha256(&path).await {
                Ok((computed_sha256, _)) => {
                    if computed_sha256.eq_ignore_ascii_case(&record.sha256) {
                        println!("[VALIDE] '{}'", record.path);
                        true
                    } else {
                        eprintln!(
                            "[CORROMPU] '{}'\n  Attendu : {}\n  Obtenu  : {}",
                            record.path, record.sha256, computed_sha256
                        );
                        false
                    }
                }
                Err(err) => {
                    eprintln!("[ERREUR I/O] '{}': {:#}", record.path, err);
                    false
                }
            }
        });
        tasks.push(task);
    }

    let mut all_valid = true;
    let mut valid_count = 0;
    let total = tasks.len();

    for task in tasks {
        match task.await {
            Ok(true) => valid_count += 1,
            _ => all_valid = false,
        }
    }

    println!("\nRésultat de la validation : {}/{} fichier(s) intègre(s).", valid_count, total);

    if !all_valid {
        bail!("La validation a échoué pour au moins un fichier.");
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Compute(args) => handle_compute(args).await,
        Commands::Validate(args) => handle_validate(args).await,
    }
}

