async fn run_worker(cmd: Commands, concurrency: usize, tx: mpsc::Sender<WorkerEvent>) {
    let semaphore = Arc::new(Semaphore::new(concurrency));
    let mut items: Vec<WorkItem> = Vec::new();

    match cmd {
        Commands::Compute { paths, output } => {
            for p in paths {
                if p.is_dir() {
                    for entry in WalkDir::new(p).into_iter().filter_map(|e| e.ok()) {
                        if entry.file_type().is_file() {
                            items.push(WorkItem {
                                path: entry.into_path(),
                                kind: TaskKind::Compute,
                            });
                        }
                    }
                } else if p.is_file() {
                    items.push(WorkItem {
                        path: p,
                        kind: TaskKind::Compute,
                    });
                }
            }

            let _ = tx.send(WorkerEvent::DiscoveredTotal(items.len())).await;

            let mut tasks = Vec::new();
            for item in items {
                let sem_clone = Arc::clone(&semaphore);
                let tx_clone = tx.clone();
                let task = tokio::spawn(async move {
                    let _permit = match sem_clone.acquire().await {
                        Ok(p) => p,
                        Err(_) => return None,
                    };
                    let _ = tx_clone.send(WorkerEvent::Started(item.path.clone())).await;

                    let res = hash_file(&item.path).await;
                    let result = match &res {
                        Ok(hash) => TaskResult {
                            path: item.path.clone(),
                            status: TaskStatus::Success { hash: hash.clone() },
                        },
                        Err(e) => TaskResult {
                            path: item.path.clone(),
                            status: TaskStatus::Failed {
                                error: e.to_string(),
                            },
                        },
                    };
                    let _ = tx_clone.send(WorkerEvent::Finished(result)).await;

                    if let Ok(hash) = &res {
                        Some(format!("{}  {}\n", hash, item.path.display()))
                    } else {
                        None
                    }
                });
                tasks.push(task);
            }

            let mut computed_lines: Vec<String> = Vec::new();
            for t in tasks {
                if let Ok(Some(line)) = t.await {
                    computed_lines.push(line);
                }
            }

            if let Some(out_path) = output {
                if let Ok(mut f) = tokio::fs::File::create(&out_path).await {
                    use tokio::io::AsyncWriteExt;
                    for line in computed_lines {
                        let _ = f.write_all(line.as_bytes()).await;
                    }
                }
            }
        }
        Commands::Verify { checksum_file } => {
            match tokio::fs::read_to_string(&checksum_file).await {
                Ok(content) => {
                    for line in content.lines() {
                        let line = line.trim();
                        if line.is_empty() || line.starts_with('#') {
                            continue;
                        }
                        // Format standard sha256sum: "<hash>  <path>" ou "<hash> *<path>"
                        let mut parts = line.split_whitespace();
                        if let (Some(hash), Some(file_str)) = (parts.next(), parts.next()) {
                            let path = PathBuf::from(file_str.trim_start_matches('*'));
                            items.push(WorkItem {
                                path,
                                kind: TaskKind::Verify {
                                    expected_hash: hash.to_lowercase(),
                                },
                            });
                        }
                    }

                    let _ = tx.send(WorkerEvent::DiscoveredTotal(items.len())).await;

                    let mut tasks = Vec::new();
                    for item in items {
                        let sem_clone = Arc::clone(&semaphore);
                        let tx_clone = tx.clone();
                        let task = tokio::spawn(async move {
                            let _permit = match sem_clone.acquire().await {
                                Ok(p) => p,
                                Err(_) => return,
                            };
                            let _ = tx_clone.send(WorkerEvent::Started(item.path.clone())).await;

                            let res = hash_file(&item.path).await;
                            let status = match res {
                                Ok(computed_hash) => {
                                    if let TaskKind::Verify { expected_hash } = item.kind {
                                        let matches =
                                            computed_hash.eq_ignore_ascii_case(&expected_hash);
                                        TaskStatus::Verified {
                                            hash: computed_hash,
                                            matches,
                                        }
                                    } else {
                                        TaskStatus::Success {
                                            hash: computed_hash,
                                        }
                                    }
                                }
                                Err(e) => TaskStatus::Failed {
                                    error: e.to_string(),
                                },
                            };
                            let _ = tx_clone
                                .send(WorkerEvent::Finished(TaskResult {
                                    path: item.path,
                                    status,
                                }))
                                .await;
                        });
                        tasks.push(task);
                    }

                    for t in tasks {
                        let _ = t.await;
                    }
                }
                Err(e) => {
                    let _ = tx.send(WorkerEvent::DiscoveredTotal(0)).await;
                    let _ = tx
                        .send(WorkerEvent::Finished(TaskResult {
                            path: checksum_file,
                            status: TaskStatus::Failed {
                                error: format!("Impossible de lire le fichier de checksums: {}", e),
                            },
                        }))
                        .await;
                }
            }
        }
    }

    let _ = tx.send(WorkerEvent::Done).await;
}

async fn hash_file(path: &Path) -> Result<String> {
    let mut file = tokio::fs::File::open(path)
        .await
        .with_context(|| format!("Impossible d'ouvrir '{}'", path.display()))?;

    let mut hasher = Sha256::new();
    let mut buffer = [0u8; BUFFER_SIZE];

    loop {
        let bytes_read = file
            .read(&mut buffer)
            .await
            .with_context(|| format!("Erreur lors de la lecture de '{}'", path.display()))?;
        if bytes_read == 0 {
            break;
        }
        hasher.update(&buffer[..bytes_read]);
    }

    let result = hasher.finalize();
    Ok(hex::encode(result))
}

async fn run_plain_cli(mut rx: mpsc::Receiver<WorkerEvent>) -> Result<()> {
    let mut total = 0;
    let mut processed = 0;

    while let Some(event) = rx.recv().await {
        match event {
            WorkerEvent::DiscoveredTotal(t) => {
                total = t;
                println!("Fichiers à traiter : {}", total);
            }
            WorkerEvent::Started(path) => {
                println!("[EN COURS] {}", path.display());
            }
            WorkerEvent::Finished(res) => {
                processed += 1;
                match res.status {
                    TaskStatus::Success { hash } => {
                        println!("{}  {}", hash, res.path.display());
                    }
                    TaskStatus::Verified { matches, hash } => {
                        if matches {
                            println!("[OK] {} ({})", res.path.display(), hash);
                        } else {
                            eprintln!("[ÉCHEC DE CORRESPONDANCE] {}", res.path.display());
                        }
                    }
                    TaskStatus::Failed { error } => {
                        eprintln!("[ERREUR] {}: {}", res.path.display(), error);
                    }
                }
            }
            WorkerEvent::Done => {
                println!("Terminé : {}/{} fichiers traités.", processed, total);
                break;
            }
        }
    }
    Ok(())
}

async fn run_tui(mut rx: mpsc::Receiver<WorkerEvent>) -> Result<()> {
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut total_files = 0;
    let mut finished_files = 0;
    let mut is_completed = false;
    let mut current_tasks: Vec<String> = Vec::new();
    let mut history: Vec<(String, Color)> = Vec::new();

    loop {
        // Traiter les événements reçus du worker
        while let Ok(event) = rx.try_recv() {
            match event {
                WorkerEvent::DiscoveredTotal(t) => {
                    total_files = t;
                }
                WorkerEvent::Started(p) => {
                    current_tasks.push(p.display().to_string());
                }
                WorkerEvent::Finished(res) => {
                    finished_files += 1;
                    let path_str = res.path.display().to_string();
                    current_tasks.retain(|x| x != &path_str);

                    match res.status {
                        TaskStatus::Success { hash } => {
                            history.push((
                                format!("{}  {}", &hash[..8.min(hash.len())], path_str),
                                Color::Green,
                            ));
                        }
                        TaskStatus::Verified { matches, .. } => {
                            if matches {
                                history.push((format!("OK: {}", path_str), Color::Green));
                            } else {
                                history.push((format!("MISMATCH: {}", path_str), Color::Red));
                            }
                        }
                        TaskStatus::Failed { error } => {
                            history.push((format!("ERR: {} ({})", path_str, error), Color::Yellow));
                        }
                    }
                }
                WorkerEvent::Done => {
                    is_completed = true;
                }
            }
        }

        // Rendu TUI
        terminal.draw(|f| {
            let chunks = Layout::default()
                .direction(Direction::Vertical)
                .constraints([
                    Constraint::Length(3),
                    Constraint::Length(3),
                    Constraint::Min(6),
                    Constraint::Length(3),
                ])
                .split(f.area());

            // 1. Titre & Status
            let title_text = if is_completed {
                " SHA-256 Hasher & Validator (Terminé - Appuyez sur 'q' pour quitter) "
            } else {
                " SHA-256 Hasher & Validator (En cours...) "
            };
            let title = Paragraph::new(title_text)
                .style(
                    Style::default()
                        .fg(Color::Cyan)
                        .add_modifier(Modifier::BOLD),
                )
                .block(Block::default().borders(Borders::ALL));
            f.render_widget(title, chunks[0]);

            // 2. Jauge de progression
            let progress = if total_files > 0 {
                (finished_files as f64 / total_files as f64).clamp(0.0, 1.0)
            } else if is_completed {
                1.0
            } else {
                0.0
            };
            let gauge = Gauge::default()
                .block(
                    Block::default()
                        .borders(Borders::ALL)
                        .title(format!(" Progression: {}/{} ", finished_files, total_files)),
                )
                .gauge_style(
                    Style::default()
                        .fg(Color::LightGreen)
                        .bg(Color::DarkGray)
                        .add_modifier(Modifier::ITALIC),
                )
                .ratio(progress);
            f.render_widget(gauge, chunks[1]);

            // 3. Liste des logs & résultats
            let list_items: Vec<ListItem> = history
                .iter()
                .rev()
                .take(chunks[2].height as usize)
                .map(|(text, color)| {
                    ListItem::new(Line::from(vec![Span::styled(
                        text,
                        Style::default().fg(*color),
                    )]))
                })
                .collect();

            let history_list = List::new(list_items).block(
                Block::default()
                    .borders(Borders::ALL)
                    .title(" Historique des Résultats "),
            );
            f.render_widget(history_list, chunks[2]);

            // 4. Pied de page
            let active_desc = if current_tasks.is_empty() {
                if is_completed {
                    "Toutes les tâches sont terminées.".to_string()
                } else {
                    "En attente...".to_string()
                }
            } else {
                format!("Tâches en cours ({}): {}", current_tasks.len(), current_tasks.join(", "))
            };
            let footer = Paragraph::new(active_desc)
                .style(Style::default().fg(Color::Gray))
                .block(Block::default().borders(Borders::ALL).title(" Statut "));
            f.render_widget(footer, chunks[3]);
        })?;

        // Lecture des touches
        if event::poll(Duration::from_millis(50))? {
            if let Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press {
                    if key.code == KeyCode::Char('q') || key.code == KeyCode::Esc {
                        break;
                    }
                }
            }
        }

        if is_completed && !event::poll(Duration::from_millis(50))? {
            // Une fois terminé, on attend une action utilisateur ou on continue
        }
    }

    // Nettoyage terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    Ok(())
}

