    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut total_files = 0;
    let mut finished_files = 0;
    let mut is_completed = false;
    let mut current_tasks: Vec<String> = Vec::new();
    let mut history: Vec<(String, Color)> = Vec::new();

    loop {
        // Traiter les événements reçus du worker
        while let Ok(event) = rx.try_recv() {
            match event {
                WorkerEvent::DiscoveredTotal(t) => {
                    total_files = t;
                }
                WorkerEvent::Started(p) => {
                    current_tasks.push(p.display().to_string());
                }
                WorkerEvent::Finished(res) => {
                    finished_files += 1;
                    let path_str = res.path.display().to_string();
                    current_tasks.retain(|x| x != &path_str);

                    match res.status {
                        TaskStatus::Success { hash } => {
                            history.push((
                                format!("{}  {}", &hash[..8.min(hash.len())], path_str),
                                Color::Green,
                            ));
                        }
                        TaskStatus::Verified { matches, .. } => {
                            if matches {
                                history.push((format!("OK: {}", path_str), Color::Green));
                            } else {
                                history.push((format!("MISMATCH: {}", path_str), Color::Red));
                            }
                        }
                        TaskStatus::Failed { error } => {
                            history.push((format!("ERR: {} ({})", path_str, error), Color::Yellow));
                        }
                    }
                }
                WorkerEvent::Done => {
                    is_completed = true;
                }
            }
        }

        // Rendu TUI
        terminal.draw(|f| {
            let chunks = Layout::default()
                .direction(Direction::Vertical)
                .constraints([
                    Constraint::Length(3),
                    Constraint::Length(3),
                    Constraint::Min(6),
                    Constraint::Length(3),
                ])
                .split(f.area());

            // 1. Titre & Status
            let title_text = if is_completed {
                " SHA-256 Hasher & Validator (Terminé - Appuyez sur 'q' pour quitter) "
            } else {
                " SHA-256 Hasher & Validator (En cours...) "
            };
            let title = Paragraph::new(title_text)
                .style(
                    Style::default()
                        .fg(Color::Cyan)
                        .add_modifier(Modifier::BOLD),
                )
                .block(Block::default().borders(Borders::ALL));
            f.render_widget(title, chunks[0]);

            // 2. Jauge de progression
            let progress = if total_files > 0 {
                (finished_files as f64 / total_files as f64).clamp(0.0, 1.0)
            } else if is_completed {
                1.0
            } else {
                0.0
            };
            let gauge = Gauge::default()
                .block(
                    Block::default()
                        .borders(Borders::ALL)
                        .title(format!(" Progression: {}/{} ", finished_files, total_files)),
                )
                .gauge_style(
                    Style::default()
                        .fg(Color::LightGreen)
                        .bg(Color::DarkGray)
                        .add_modifier(Modifier::ITALIC),
                )
                .ratio(progress);
            f.render_widget(gauge, chunks[1]);

            // 3. Liste des logs & résultats
            let list_items: Vec<ListItem> = history
                .iter()
                .rev()
                .take(chunks[2].height as usize)
                .map(|(text, color)| {
                    ListItem::new(Line::from(vec![Span::styled(
                        text,
                        Style::default().fg(*color),
                    )]))
                })
                .collect();

            let history_list = List::new(list_items).block(
                Block::default()
                    .borders(Borders::ALL)
                    .title(" Historique des Résultats "),
            );
            f.render_widget(history_list, chunks[2]);

            // 4. Pied de page
            let active_desc = if current_tasks.is_empty() {
                if is_completed {
                    "Toutes les tâches sont terminées.".to_string()
                } else {
                    "En attente...".to_string()
                }
            } else {
                format!("Tâches en cours ({}): {}", current_tasks.len(), current_tasks.join(", "))
            };
            let footer = Paragraph::new(active_desc)
                .style(Style::default().fg(Color::Gray))
                .block(Block::default().borders(Borders::ALL).title(" Statut "));
            f.render_widget(footer, chunks[3]);
        })?;

        // Lecture des touches
        if event::poll(Duration::from_millis(50))? {
            if let Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press {
                    if key.code == KeyCode::Char('q') || key.code == KeyCode::Esc {
                        break;
                    }
                }
            }
        }

        if is_completed && !event::poll(Duration::from_millis(50))? {
            // Une fois terminé, on attend une action utilisateur ou on continue
        }
    }

    // Nettoyage terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    Ok(())
}

