#[derive(Parser, Debug)]
#[command(name = "dystil-hasher", version, about = "CLI asynchrone pour hachage SHA-256 et HMAC avec interface Web")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Calcule l'empreinte SHA-256 d'un fichier local
    Hash(HashArgs),
    /// Valide l'empreinte SHA-256 d'un fichier par rapport à une valeur attendue
    Verify(VerifyArgs),
    /// Calcule ou valide l'empreinte HMAC-SHA-256 d'un fichier avec une clé secrète
    Hmac(HmacArgs),
    /// Démarre un serveur Web interactif Axum + Tera
    Serve(ServeArgs),
}

#[derive(Args, Debug)]
struct HashArgs {
    /// Chemin du fichier à analyser
    #[arg(short, long)]
    file: PathBuf,
}

#[derive(Args, Debug)]
struct VerifyArgs {
    /// Chemin du fichier à analyser
    #[arg(short, long)]
    file: PathBuf,

    /// Empreinte SHA-256 hexadécimale attendue
    #[arg(short, long)]
    expected: String,
}

#[derive(Args, Debug)]
struct HmacArgs {
    /// Chemin du fichier à analyser
    #[arg(short, long)]
    file: PathBuf,

    /// Clé secrète HMAC
    #[arg(short, long, env = "HMAC_SECRET")]
    secret: String,

    /// Empreinte HMAC attendue pour validation (optionnel)
    #[arg(long)]
    expected: Option<String>,
}

#[derive(Args, Debug)]
struct ServeArgs {
    /// Adresse d'écoute (ex: 127.0.0.1)
    #[arg(short, long, default_value = "127.0.0.1")]
    address: String,

    /// Port d'écoute
    #[arg(short, long, default_value_t = 3000)]
    port: u16,
}

struct AppState {
    tera: Tera,
}

#[derive(Deserialize)]
struct InspectQuery {
    path: Option<String>,
}

/// Calcule l'empreinte SHA-256 en flux asynchrone par blocs de 64 Ko
async fn compute_sha256(path: &Path) -> Result<String> {
    let mut file = tokio::fs::File::open(path)
        .await
        .with_context(|| format!("Impossible d'ouvrir le fichier '{}'", path.display()))?;

    let mut hasher = Sha256::new();
    let mut buffer = [0u8; 65536];

    loop {
        let bytes_read = file
            .read(&mut buffer)
            .await
            .with_context(|| format!("Erreur de lecture sur '{}'", path.display()))?;

        if bytes_read == 0 {
            break;
        }

        hasher.update(&buffer[..bytes_read]);
    }

    Ok(hex::encode(hasher.finalize()))
}

/// Calcule l'empreinte HMAC-SHA-256 en flux asynchrone
async fn compute_hmac_sha256(path: &Path, secret: &[u8]) -> Result<String> {
    let mut file = tokio::fs::File::open(path)
        .await
        .with_context(|| format!("Impossible d'ouvrir le fichier '{}'", path.display()))?;

    let mut mac = HmacSha256::new_from_slice(secret)
        .map_err(|e| anyhow::anyhow!("Erreur lors de l'initialisation de HMAC : {}", e))?;

    let mut buffer = [0u8; 65536];

    loop {
        let bytes_read = file
            .read(&mut buffer)
            .await
            .with_context(|| format!("Erreur de lecture sur '{}'", path.display()))?;

        if bytes_read == 0 {
            break;
        }

        mac.update(&buffer[..bytes_read]);
    }

    Ok(hex::encode(mac.finalize().into_bytes()))
}

/// Page principale servie par Axum avec template Tera
async fn handle_index(
    State(state): State<Arc<AppState>>,
    Query(query): Query<InspectQuery>,
) -> Result<Html<String>, (axum::http::StatusCode, String)> {
    let mut context = tera::Context::new();

    if let Some(ref path_str) = query.path {
        context.insert("file_path", path_str);
        let path = Path::new(path_str);
        match compute_sha256(path).await {
            Ok(hash) => {
                context.insert("hash_result", &hash);
            }
            Err(err) => {
                context.insert("error", &format!("{:#}", err));
            }
        }
    }

    let rendered = state
        .tera
        .render("index.html", &context)
        .map_err(|e| (axum::http::StatusCode::INTERNAL_SERVER_ERROR, e.to_string()))?;

    Ok(Html(rendered))
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt::init();

    let cli = Cli::parse();

    match cli.command {
        Commands::Hash(args) => {
            let digest = compute_sha256(&args.file).await?;
            println!("{}", digest);
        }
        Commands::Verify(args) => {
            let digest = compute_sha256(&args.file).await?;
            let normalized_expected = args.expected.trim().to_lowercase();
            if digest.eq_ignore_ascii_case(&normalized_expected) {
                println!("OK: L'empreinte SHA-256 correspond.");
            } else {
                eprintln!("ERREUR: L'empreinte ne correspond pas !");
                eprintln!("  Calculée : {}", digest);
                eprintln!("  Attendue : {}", normalized_expected);
                std::process::exit(1);
            }
        }
        Commands::Hmac(args) => {
            let digest = compute_hmac_sha256(&args.file, args.secret.as_bytes()).await?;
            if let Some(expected) = args.expected {
                let normalized_expected = expected.trim().to_lowercase();
                if digest.eq_ignore_ascii_case(&normalized_expected) {
                    println!("OK: L'empreinte HMAC-SHA-256 est valide.");
                } else {
                    eprintln!("ERREUR: Empreinte HMAC invalide !");
                    eprintln!("  Calculée : {}", digest);
                    eprintln!("  Attendue : {}", normalized_expected);
                    std::process::exit(1);
                }
            } else {
                println!("{}", digest);
            }
        }
        Commands::Serve(args) => {
            let mut tera = Tera::default();
            tera.add_raw_template("index.html", INDEX_TEMPLATE)
                .context("Erreur d'initialisation du template Tera")?;

            let app_state = Arc::new(AppState { tera });
            let app = Router::new()
                .route("/", get(handle_index))
                .with_state(app_state);

            let addr: SocketAddr = format!("{}:{}", args.address, args.port)
                .parse()
                .with_context(|| format!("Adresse d'écoute invalide: {}:{}", args.address, args.port))?;

            tracing::info!("Serveur démarré sur http://{}", addr);
            println!("Serveur Web démarré sur http://{}", addr);

            let listener = tokio::net::TcpListener::bind(addr).await?;
            axum::serve(listener, app).await?;
        }
    }

    Ok(())
}

