                    std::process::exit(1);
                }
            } else {
                println!("{}", digest);
            }
        }
        Commands::Serve(args) => {
            let mut tera = Tera::default();
            tera.add_raw_template("index.html", INDEX_TEMPLATE)
                .context("Erreur d'initialisation du template Tera")?;

            let app_state = Arc::new(AppState { tera });
            let app = Router::new()
                .route("/", get(handle_index))
                .with_state(app_state);

            let addr: SocketAddr = format!("{}:{}", args.address, args.port)
                .parse()
                .with_context(|| format!("Adresse d'écoute invalide: {}:{}", args.address, args.port))?;

            tracing::info!("Serveur démarré sur http://{}", addr);
            println!("Serveur Web démarré sur http://{}", addr);

            let listener = tokio::net::TcpListener::bind(addr).await?;
            axum::serve(listener, app).await?;
