// src/main.rs
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::process::ExitCode;

use anyhow::{bail, Context, Result};
use clap::{Args, Parser, Subcommand};
use futures::stream::{self, StreamExt};
use sha2::{Digest, Sha256};
use tokio::fs::File;
use tokio::io::{AsyncBufReadExt, AsyncReadExt, BufReader};
use tokio::sync::Semaphore;

/// Taille du tampon de lecture (64 KiB) pour un streaming optimal de tokio::fs vers sha2
const BUFFER_SIZE: usize = 64 * 1024;

#[derive(Parser, Debug)]
#[command(
    name = "sha256-async-cli",
    version,
    about = "Outil CLI asynchrone et multithreadé pour calculer et valider des empreintes SHA-256",
    long_about = "Cet outil tire parti de clap pour l'interface en ligne de commande, de tokio::fs pour les I/O asynchrones non-bloquantes, et d'un hachage SHA-256 distribué sur un pool de threads d'exécution."
)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Calcule les empreintes SHA-256 d'un ou plusieurs fichiers locaux
    Hash(HashArgs),
    /// Valide l'intégrité de fichiers à partir d'un fichier de sommes de contrôle (format sha256sum)
    Check(CheckArgs),
}

#[derive(Args, Debug)]
struct HashArgs {
    /// Fichiers locaux à analyser
    #[arg(required = true, value_name = "FICHIER")]
    files: Vec<PathBuf>,

    /// Nombre maximal de fichiers traités simultanément (défaut : nombre de cœurs logiques)
    #[arg(short = 'c', long = "concurrency")]
    concurrency: Option<usize>,

    /// Écrit les sommes de contrôle dans un fichier cible au lieu de la sortie standard
    #[arg(short = 'o', long = "output", value_name = "DESTINATION")]
    output: Option<PathBuf>,

    /// Produit un affichage au format BSD (SHA256 (fichier) = hash)
    #[arg(long = "tag")]
    tag: bool,
}

#[derive(Args, Debug)]
struct CheckArgs {
    /// Chemin vers le fichier contenant les empreintes de contrôle
    #[arg(value_name = "FICHIER_CHECKSUM")]
    checksum_file: PathBuf,

    /// Nombre maximal de fichiers validés simultanément
    #[arg(short = 'c', long = "concurrency")]
    concurrency: Option<usize>,

    /// N'affiche pas les fichiers dont l'intégrité est confirmée (affiche uniquement les échecs)
    #[arg(short = 'q', long = "quiet")]
    quiet: bool,

    /// N'affiche aucun résultat, seul le code de sortie indique le succès (0) ou l'échec (1)
    #[arg(long = "status")]
    status: bool,
}

/// Résultat du calcul de l'empreinte pour un fichier donné
#[derive(Debug)]
struct HashResult {
    path: PathBuf,
    digest: Result<String>,
}

/// Statut de vérification d'un fichier
#[derive(Debug, PartialEq, Eq)]
enum VerificationStatus {
    Ok,
    Failed,
    IoError(String),
}

/// Calcule l'empreinte SHA-256 d'un fichier de façon asynchrone par morceaux
async fn compute_sha256(path: &Path) -> Result<String> {
    let file = File::open(path)
        .await
        .with_context(|| format!("Impossible d'ouvrir le fichier : {}", path.display()))?;

    let mut reader = BufReader::with_capacity(BUFFER_SIZE, file);
    let mut hasher = Sha256::new();
    let mut buffer = vec![0u8; BUFFER_SIZE];

    loop {
        let bytes_read = reader
            .read(&mut buffer)
            .await
            .with_context(|| format!("Erreur de lecture sur le fichier : {}", path.display()))?;

        if bytes_read == 0 {
            break;
        }

        // Le calcul SHA-256 par bloc est appliqué sur la tranche lue
        hasher.update(&buffer[..bytes_read]);
    }

    let result = hasher.finalize();
    Ok(hex::encode(result))
