/// Détermine la concurrence effective (par défaut : nombre de threads disponibles)
fn get_default_concurrency(requested: Option<usize>) -> usize {
    requested
        .filter(|&c| c > 0)
        .unwrap_or_else(|| {
            std::thread::available_parallelism()
                .map(|p| p.get())
                .unwrap_or(4)
        })
}

/// Exécute la sous-commande `hash`
async fn run_hash(args: HashArgs) -> Result<ExitCode> {
    let concurrency = get_default_concurrency(args.concurrency);
    let semaphore = Arc::new(Semaphore::new(concurrency));
    let mut had_error = false;
    let mut output_lines = Vec::with_capacity(args.files.len());

    let tasks = stream::iter(args.files.into_iter().map(|path| {
        let sem = Arc::clone(&semaphore);
        async move {
            let _permit = sem
                .acquire()
                .await
                .expect("Sémaphore fermé de manière inattendue");

            let digest = compute_sha256(&path).await;
            HashResult { path, digest }
        }
    }))
    .buffer_unordered(concurrency);

    let mut results = tasks.collect::<Vec<_>>().await;
    // Tri pour garantir un ordre de restitution stable et déterministe
    results.sort_by(|a, b| a.path.cmp(&b.path));

    for res in results {
        match res.digest {
            Ok(hash) => {
                let formatted_line = if args.tag {
                    format!("SHA256 ({}) = {}", res.path.display(), hash)
                } else {
                    format!("{}  {}", hash, res.path.display())
                };

                if args.output.is_none() {
                    println!("{}", formatted_line);
                }
                output_lines.push(formatted_line);
            }
            Err(err) => {
                eprintln!("{}: {}", res.path.display(), err);
                had_error = true;
            }
        }
    }

    if let Some(dest_path) = args.output {
        let content = output_lines.join("\n") + if output_lines.is_empty() { "" } else { "\n" };
        tokio::fs::write(&dest_path, content)
            .await
            .with_context(|| format!("Échec d'écriture dans le fichier {}", dest_path.display()))?;
    }

    if had_error {
        Ok(ExitCode::FAILURE)
    } else {
