async fn parse_checksum_file(path: &Path) -> Result<Vec<ChecksumEntry>> {
    let file = File::open(path)
        .await
        .with_context(|| format!("Impossible d'ouvrir le fichier de contrôle : {}", path.display()))?;

    let base_dir = path.parent().unwrap_or_else(|| Path::new("."));
    let mut reader = BufReader::new(file).lines();
    let mut entries = Vec::new();
    let mut line_number = 0usize;

    while let Some(line) = reader.next_line().await.context("Erreur de lecture du fichier de contrôle")? {
        line_number += 1;
        let trimmed = line.trim();

        // Ignorer les commentaires et lignes vides
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        // Support du format BSD: SHA256 (fichier) = hash
        if trimmed.starts_with("SHA256 (") {
            if let Some(open_paren) = trimmed.find('(') {
                if let Some(close_paren) = trimmed.rfind(") = ") {
                    let file_part = &trimmed[open_paren + 1..close_paren];
                    let hash_part = trimmed[close_paren + 4..].trim();
                    let file_path = base_dir.join(file_part);
                    entries.push(ChecksumEntry {
                        expected_hash: hash_part.to_lowercase(),
                        path: file_path,
                    });
                    continue;
                }
            }
        }

        // Format standard sha256sum: "<hash> <flag><path>" (mode texte ' ' ou binaire '*')
        let parts: Vec<&str> = trimmed.splitn(2, |c: char| c.is_whitespace()).collect();
