            bail!(
                "Format invalide à la ligne {} dans {} : '{}'",
                line_number,
                path.display(),
                trimmed
            );
        }

        let hash_part = parts[0].trim();
        let mut path_part = parts[1].trim();

        // Prise en charge du marqueur binaire/texte ('*' ou ' ')
        if path_part.starts_with('*') || path_part.starts_with(' ') {
            path_part = path_part[1..].trim_start();
        }

        let file_path = base_dir.join(path_part);
        entries.push(ChecksumEntry {
            expected_hash: hash_part.to_lowercase(),
            path: file_path,
        });
    }

    Ok(entries)
}

/// Exécute la sous-commande `check`
async fn run_check(args: CheckArgs) -> Result<ExitCode> {
    let entries = parse_checksum_file(&args.checksum_file).await?;
    if entries.is_empty() {
        if !args.status {
            eprintln!(
                "{}: aucune somme de contrôle trouvée",
                args.checksum_file.display()
            );
        }
        return Ok(ExitCode::FAILURE);
    }

    let concurrency = get_default_concurrency(args.concurrency);
    let semaphore = Arc::new(Semaphore::new(concurrency));

    let stream = stream::iter(entries.into_iter().map(|entry| {
        let sem = Arc::clone(&semaphore);
        async move {
            let _permit = sem
                .acquire()
                .await
                .expect("Sémaphore fermé de manière inattendue");

            let status = match compute_sha256(&entry.path).await {
                Ok(actual_hash) => {
                    if actual_hash.eq_ignore_ascii_case(&entry.expected_hash) {
                        VerificationStatus::Ok
                    } else {
                        VerificationStatus::Failed
                    }
                }
                Err(err) => VerificationStatus::IoError(err.to_string()),
            };

            (entry, status)
        }
    }))
    .buffer_unordered(concurrency);

    let mut results = stream.collect::<Vec<_>>().await;
    results.sort_by(|a, b| a.0.path.cmp(&b.0.path));

    let mut total_failed = 0usize;
    let mut total_io_errors = 0usize;

    for (entry, status) in results {
        match status {
            VerificationStatus::Ok => {
                if !args.quiet && !args.status {
                    println!("{}: RÉUSSI", entry.path.display());
                }
            }
            VerificationStatus::Failed => {
                total_failed += 1;
                if !args.status {
                    println!("{}: ÉCHEC", entry.path.display());
                }
            }
            VerificationStatus::IoError(err_msg) => {
                total_io_errors += 1;
                if !args.status {
                    eprintln!("{}: ERREUR ({})", entry.path.display(), err_msg);
                }
            }
        }
    }

    let has_failure = total_failed > 0 || total_io_errors > 0;

    if !args.status && has_failure {
        let mut summaries = Vec::new();
        if total_failed > 0 {
            summaries.push(format!("{} somme(s) de contrôle incorrecte(s)", total_failed));
        }
        if total_io_errors > 0 {
            summaries.push(format!("{} fichier(s) illisible(s)", total_io_errors));
        }
        eprintln!("ATTENTION : {}", summaries.join(", "));
    }

    if has_failure {
        Ok(ExitCode::FAILURE)
    } else {
        Ok(ExitCode::SUCCESS)
    }
}

#[tokio::main]
async fn main() -> ExitCode {
    let cli = Cli::parse();

    let result = match cli.command {
        Commands::Hash(args) => run_hash(args).await,
        Commands::Check(args) => run_check(args).await,
    };

    match result {
        Ok(code) => code,
        Err(err) => {
            eprintln!("Erreur fatale : {:#}", err);
            ExitCode::FAILURE
        }
    }
}

