use tokio::io::AsyncReadExt;
use tracing::{error, info};
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt};

/// Taille du buffer tampon pour le hachage asynchrone en continu (64 Ko)
const HASH_BUFFER_SIZE: usize = 65_536;

#[derive(Parser, Debug)]
#[command(
    name = "sha256-parquet-cli",
    version,
    about = "Calculateur et vérificateur asynchrone de SHA-256 avec export Parquet et serveur Axum"
