    /// Vérifie qu'un fichier correspond à une empreinte SHA-256 donnée
    Verify(VerifyArgs),
    /// Lance le serveur HTTP asynchrone Axum
    Serve(ServeArgs),
}

#[derive(Args, Debug)]
