    /// Fichiers cibles à analyser
    #[arg(required = true)]
    files: Vec<PathBuf>,

    /// Chemin du fichier de destination Parquet pour stocker les résultats
    #[arg(short, long)]
    output_parquet: Option<PathBuf>,
}

#[derive(Args, Debug)]
struct VerifyArgs {
    /// Chemin du fichier à vérifier
    #[arg(required = true)]
    file: PathBuf,

    /// Empreinte SHA-256 attendue (format hexadécimal)
    #[arg(required = true)]
    expected_sha256: String,
}

#[derive(Args, Debug)]
struct ServeArgs {
    /// Adresse d'écoute pour l'API HTTP
    #[arg(short, long, default_value = "127.0.0.1:3000")]
    bind: SocketAddr,
}

/// Enregistrement représentant le résultat du traitement d'un fichier
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FileChecksumRecord {
    pub file_path: String,
    pub size_bytes: u64,
    pub sha256: String,
    pub is_valid: bool,
}

/// Calcule l'empreinte SHA-256 d'un fichier de façon asynchrone par streaming
pub async fn compute_sha256(path: &Path) -> Result<(String, u64)> {
    let mut file = tokio::fs::File::open(path)
        .await
        .with_context(|| format!("Impossible d'ouvrir le fichier {:?}", path))?;

    let metadata = file
        .metadata()
        .await
        .with_context(|| format!("Impossible de lire les métadonnées de {:?}", path))?;
    let file_size = metadata.len();

    let mut hasher = Sha256::new();
    let mut buffer = vec![0u8; HASH_BUFFER_SIZE];

    loop {
        let bytes_read = file
            .read(&mut buffer)
            .await
            .with_context(|| format!("Erreur de lecture sur le fichier {:?}", path))?;

        if bytes_read == 0 {
            break;
        }

        hasher.update(&buffer[..bytes_read]);
    }

    let hash_result = hasher.finalize();
    Ok((hex::encode(hash_result), file_size))
}

/// Écrit les enregistrements dans un fichier Parquet colonnaire avec compression Snappy
pub fn write_records_to_parquet(
    records: &[FileChecksumRecord],
    output_path: &Path,
) -> Result<()> {
    let schema = Arc::new(Schema::new(vec![
        Field::new("file_path", DataType::Utf8, false),
        Field::new("size_bytes", DataType::UInt64, false),
        Field::new("sha256", DataType::Utf8, false),
        Field::new("is_valid", DataType::Boolean, false),
    ]));

    let file_paths: Vec<&str> = records.iter().map(|r| r.file_path.as_str()).collect();
    let sizes: Vec<u64> = records.iter().map(|r| r.size_bytes).collect();
    let hashes: Vec<&str> = records.iter().map(|r| r.sha256.as_str()).collect();
    let valid_flags: Vec<bool> = records.iter().map(|r| r.is_valid).collect();

    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![
            Arc::new(StringArray::from(file_paths)),
            Arc::new(UInt64Array::from(sizes)),
            Arc::new(StringArray::from(hashes)),
            Arc::new(BooleanArray::from(valid_flags)),
        ],
    )
    .context("Échec de création du RecordBatch Arrow")?;

    let output_file = StdFile::create(output_path)
        .with_context(|| format!("Impossible de créer le fichier Parquet {:?}", output_path))?;

    let props = WriterProperties::builder()
        .set_compression(Compression::SNAPPY)
        .build();

    let mut writer = ArrowWriter::try_new(output_file, schema, Some(props))
        .context("Échec d'initialisation de l'écrivain Parquet")?;

    writer
        .write(&batch)
        .context("Échec de l'écriture du RecordBatch dans Parquet")?;

    writer
        .close()
        .context("Échec de clôture de l'archive Parquet")?;

    Ok(())
}

