    }))
}

async fn api_hash_handler(
    Json(payload): Json<ApiHashRequest>,
) -> Result<Json<ApiHashResponse>, AppError> {
    let path = PathBuf::from(&payload.path);
    if !path.exists() {
        return Err(AppError::NotFound(format!(
            "Fichier introuvable: {}",
            payload.path
        )));
    }

    let (hash, size) = compute_sha256(&path).await?;
    Ok(Json(ApiHashResponse {
        path: payload.path,
