}

async fn api_verify_handler(
    Json(payload): Json<ApiVerifyRequest>,
) -> Result<Json<ApiVerifyResponse>, AppError> {
    let path = PathBuf::from(&payload.path);
    if !path.exists() {
        return Err(AppError::NotFound(format!(
            "Fichier introuvable: {}",
            payload.path
        )));
    }

    let (actual_hash, _) = compute_sha256(&path).await?;
    let is_valid = actual_hash.eq_ignore_ascii_case(&payload.expected_sha256);

    Ok(Json(ApiVerifyResponse {
        path: payload.path,
        actual_sha256: actual_hash,
        expected_sha256: payload.expected_sha256,
