    Router::new()
        .route("/health", get(health_check))
        .route("/api/v1/hash", post(api_hash_handler))
        .route("/api/v1/verify", post(api_verify_handler))
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::registry()
        .with(tracing_subscriber::EnvFilter::try_from_default_env().unwrap_or_else(|_| {
            "sha256_parquet_cli=info,tower_http=debug,axum=info".into()
        }))
        .with(tracing_subscriber::fmt::layer())
        .init();

    let cli = Cli::parse();

    match cli.command {
        Commands::Hash(args) => {
            let mut records = Vec::new();

            for path in &args.files {
                match compute_sha256(path).await {
                    Ok((hash, size)) => {
                        println!("{}\t{} ({} octets)", hash, path.display(), size);
                        records.push(FileChecksumRecord {
                            file_path: path.to_string_lossy().to_string(),
                            size_bytes: size,
                            sha256: hash,
                            is_valid: true,
                        });
                    }
                    Err(err) => {
                        eprintln!("Erreur pour {:?}: {:#}", path, err);
                    }
                }
            }

            if let Some(parquet_path) = args.output_parquet {
                write_records_to_parquet(&records, &parquet_path)?;
                println!(
                    "Succès : {} enregistrement(s) écrit(s) dans le fichier Parquet {:?}",
                    records.len(),
                    parquet_path
                );
            }
        }
        Commands::Verify(args) => {
            let (computed_hash, size) = compute_sha256(&args.file).await?;
            let normalized_expected = args.expected_sha256.trim().to_lowercase();
            let matches = computed_hash.to_lowercase() == normalized_expected;

            println!("Fichier         : {}", args.file.display());
            println!("Taille          : {} octets", size);
            println!("Calculé         : {}", computed_hash);
            println!("Attendu         : {}", normalized_expected);

            if matches {
                println!("Résultat        : [VALIDE] Les empreintes correspondent.");
            } else {
                eprintln!("Résultat        : [INVALIDE] Les empreintes ne correspondent pas.");
                std::process::exit(1);
            }
        }
        Commands::Serve(args) => {
            let app = create_app_router();
            info!("Démarrage du serveur Axum sur http://{}", args.bind);

            let listener = tokio::net::TcpListener::bind(args.bind)
                .await
                .with_context(|| format!("Impossible de lier l'adresse {}", args.bind))?;

            axum::serve(listener, app)
                .await
                .context("Erreur d'exécution du serveur Axum")?;
        }
    }

    Ok(())
}

