/// Calcule l'empreinte SHA-256 d'un fichier de façon asynchrone par morceaux de 64 Ko
async fn compute_sha256(path: &Path) -> Result<String> {
    let mut file = File::open(path)
        .await
        .with_context(|| format!("Impossible d'ouvrir le fichier '{}'", path.display()))?;

    let mut hasher = Sha256::new();
    let mut buffer = [0u8; 65536]; // 64 Ko buffer

    loop {
        let bytes_read = file
            .read(&mut buffer)
            .await
            .with_context(|| format!("Erreur de lecture sur '{}'", path.display()))?;
        if bytes_read == 0 {
            break;
        }
        hasher.update(&buffer[..bytes_read]);
    }

    let result = hasher.finalize();
    Ok(hex::encode(result))
}

/// Extrait le premier hash hexadécimal de 64 caractères trouvé dans une chaîne
fn extract_expected_hash(raw: &str) -> Result<String> {
    let cleaned = raw.trim();
    for token in cleaned.split_whitespace() {
        let token_clean = token.trim().to_lowercase();
        if token_clean.len() == 64 && token_clean.chars().all(|c| c.is_ascii_hexdigit()) {
            return Ok(token_clean);
        }
    }
    bail!("Aucun hash SHA-256 valide (64 caractères hexadécimaux) n'a été trouvé.")
}

/// Traite la commande de vérification
