/// État de l'interface TUI pour l'inspection de fichier
struct HexViewerApp {
    file_path: PathBuf,
    file_size: u64,
    current_offset: u64,
    bytes_per_row: usize,
    sha256_result: Option<Result<String, String>>,
    quit: bool,
}

impl HexViewerApp {
    async fn new(file_path: PathBuf) -> Result<Self> {
        let meta = tokio::fs::metadata(&file_path)
            .await
            .with_context(|| format!("Fichier introuvable ou inaccessible : '{}'", file_path.display()))?;

        Ok(Self {
            file_path,
            file_size: meta.len(),
            current_offset: 0,
            bytes_per_row: 16,
            sha256_result: None,
            quit: false,
        })
    }

    /// Charge un bloc de données à partir de l'offset courant
    async fn read_chunk(&self, offset: u64, size: usize) -> Result<Vec<u8>> {
        let mut file = File::open(&self.file_path).await?;
        file.seek(SeekFrom::Start(offset)).await?;
        let mut buffer = vec![0u8; size];
        let bytes_read = file.read(&mut buffer).await?;
        buffer.truncate(bytes_read);
        Ok(buffer)
    }

    fn scroll_down(&mut self, lines: u64) {
        let step = lines * (self.bytes_per_row as u64);
        if self.current_offset + step < self.file_size {
            self.current_offset += step;
        } else if self.file_size > 0 {
            // Se positionner sur la dernière ligne possible
            let remainder = self.file_size % (self.bytes_per_row as u64);
            let last_line_offset = if remainder == 0 {
                self.file_size.saturating_sub(self.bytes_per_row as u64)
            } else {
                self.file_size.saturating_sub(remainder)
            };
            self.current_offset = last_line_offset;
        }
    }

    fn scroll_up(&mut self, lines: u64) {
        let step = lines * (self.bytes_per_row as u64);
        self.current_offset = self.current_offset.saturating_sub(step);
    }
}

/// Formate une tranche d'octets sous forme de ligne hexdump standard
fn format_hexdump_line(offset: u64, chunk: &[u8]) -> Line<'static> {
    let mut spans = Vec::new();

    // 1. Colonne Offset
    spans.push(Span::styled(
        format!("{:08x}  ", offset),
        Style::default().fg(Color::Yellow),
    ));

    // 2. Colonne Hexadécimale (16 octets séparés en 2 groupes de 8)
    for i in 0..16 {
        if i == 8 {
            spans.push(Span::raw(" "));
        }
        if i < chunk.len() {
            spans.push(Span::styled(
                format!("{:02x} ", chunk[i]),
                Style::default().fg(Color::Cyan),
            ));
        } else {
            spans.push(Span::raw("   "));
        }
    }

    spans.push(Span::raw(" |"));

    // 3. Colonne ASCII
    for &byte in chunk {
        if byte.is_ascii_graphic() || byte == b' ' {
            spans.push(Span::styled(
                (byte as char).to_string(),
                Style::default().fg(Color::Green),
            ));
        } else {
            spans.push(Span::styled(
                ".",
                Style::default().fg(Color::DarkGray),
            ));
        }
    }
    spans.push(Span::raw("|"));

    Line::from(spans)
}

/// Lance la vue TUI interactive avec Ratatui
async fn run_inspector(file_path: PathBuf) -> Result<()> {
    let mut app = HexViewerApp::new(file_path.clone()).await?;

    // Démarrage de la tâche de hachage asynchrone en tâche de fond
    let path_clone = file_path.clone();
    let (tx_hash, mut rx_hash) = tokio::sync::mpsc::channel(1);
    tokio::spawn(async move {
        let res = compute_sha256(&path_clone)
            .await
            .map_err(|e| format!("{:#}", e));
        let _ = tx_hash.send(res).await;
    });

    let _guard = TerminalGuard::new()?;
    let mut terminal = Terminal::new(CrosstermBackend::new(stdout()))?;
    terminal.clear()?;

    let mut event_tick = tokio::time::interval(Duration::from_millis(50));

    while !app.quit {
        // Vérifier si le calcul du hash est complété
        if let Ok(res) = rx_hash.try_recv() {
            app.sha256_result = Some(res);
        }

        // Récupérer la hauteur disponible pour l'affichage hexdump
        let term_size = terminal.size()?;
        let visible_lines = term_size.height.saturating_sub(8) as usize;
        let visible_bytes = visible_lines * app.bytes_per_row;

        let chunk = app.read_chunk(app.current_offset, visible_bytes).await?;

        terminal.draw(|f| {
            let chunks = Layout::default()
                .direction(Direction::Vertical)
                .constraints([
                    Constraint::Length(5),  // En-tête / Métadonnées
                    Constraint::Min(5),     // Dump Hexadécimal
                    Constraint::Length(3),  // Barre d'état / Aide
                ])
                .split(f.area());

            // 1. En-tête
            let sha_info = match &app.sha256_result {
                None => Span::styled("Calcul en cours (Tokio background)...", Style::default().fg(Color::Yellow)),
                Some(Ok(hash)) => Span::styled(hash.clone(), Style::default().fg(Color::LightGreen).add_modifier(Modifier::BOLD)),
                Some(Err(err)) => Span::styled(format!("Erreur: {}", err), Style::default().fg(Color::Red)),
            };

            let percent = if app.file_size == 0 {
                100.0
            } else {
                ((app.current_offset as f64) / (app.file_size as f64) * 100.0).min(100.0)
            };

            let header_text = vec![
                Line::from(vec![
                    Span::styled(" Fichier : ", Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
                    Span::styled(app.file_path.display().to_string(), Style::default().fg(Color::Cyan)),
                    Span::raw(format!(" | Taille : {} octets ({:.1}%)", app.file_size, percent)),
                ]),
                Line::from(vec![
                    Span::styled(" SHA-256 : ", Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
                    sha_info,
                ]),
            ];

            let header_block = Paragraph::new(header_text)
                .block(Block::default().borders(Borders::ALL).title(" sha256-hexviewer - Inspection "));
            f.render_widget(header_block, chunks[0]);

            // 2. Dump Hexadécimal
            let mut hexdump_lines = Vec::new();
            for (idx, line_chunk) in chunk.chunks(app.bytes_per_row).enumerate() {
                let line_offset = app.current_offset + (idx * app.bytes_per_row) as u64;
                hexdump_lines.push(format_hexdump_line(line_offset, line_chunk));
            }

            if hexdump_lines.is_empty() {
                hexdump_lines.push(Line::from(Span::styled(" (Fichier vide ou fin de fichier)", Style::default().fg(Color::DarkGray))));
            }

            let hex_block = Paragraph::new(hexdump_lines)
                .block(Block::default().borders(Borders::ALL).title(format!(
                    " Hex Dump (Offset 0x{:08x} / 0x{:08x}) ",
                    app.current_offset, app.file_size
                )))
                .wrap(Wrap { trim: false });
            f.render_widget(hex_block, chunks[1]);

            // 3. Barre d'aide / Statut
            let help_text = Line::from(vec![
                Span::styled(" [q / Esc] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
                Span::raw("Quitter  "),
                Span::styled(" [▲/▼ / j/k] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
                Span::raw("Défiler ligne  "),
                Span::styled(" [PgUp/PgDn] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
                Span::raw("Défiler page  "),
                Span::styled(" [Home/End] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
                Span::raw("Début / Fin"),
            ]);
            let help_block = Paragraph::new(help_text)
                .block(Block::default().borders(Borders::ALL).title(" Commandes "));
            f.render_widget(help_block, chunks[2]);
        })?;

        // Gestion asynchrone des événements de touches
        tokio::select! {
            _ = event_tick.tick() => {}
            _ = async {
                if event::poll(Duration::from_millis(30)).unwrap_or(false) {
                    if let Ok(Event::Key(key)) = event::read() {
                        if key.kind == KeyEventKind::Press {
                            match key.code {
                                KeyCode::Char('q') | KeyCode::Esc => app.quit = true,
                                KeyCode::Char('j') | KeyCode::Down => app.scroll_down(1),
                                KeyCode::Char('k') | KeyCode::Up => app.scroll_up(1),
                                KeyCode::PageDown => app.scroll_down(visible_lines.max(1) as u64),
                                KeyCode::PageUp => app.scroll_up(visible_lines.max(1) as u64),
                                KeyCode::Home => app.current_offset = 0,
                                KeyCode::End => {
                                    if app.file_size > 0 {
                                        let remainder = app.file_size % (app.bytes_per_row as u64);
                                        app.current_offset = if remainder == 0 {
                                            app.file_size.saturating_sub(app.bytes_per_row as u64)
                                        } else {
                                            app.file_size.saturating_sub(remainder)
                                        };
                                    }
                                }
                                _ => {}
                            }
                        }
                    }
                }
            } => {}
        }
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Hash { files } => {
            for file in files {
                match compute_sha256(&file).await {
                    Ok(hash) => {
                        println!("{}  {}", hash, file.display());
                    }
                    Err(err) => {
                        eprintln!("Erreur lors du traitement de '{}': {:#}", file.display(), err);
                    }
                }
            }
        }
        Commands::Check {
            file,
            expected,
            check_file,
        } => {
            handle_check(file, expected, check_file).await?;
        }
        Commands::Inspect { file } => {
            run_inspector(file).await?;
        }
    }

    Ok(())
}

