    valid: bool,
    error: Option<String>,
}

#[derive(Debug, Serialize)]
struct HashSummary {
    results: Vec<HashResult>,
    total_files: usize,
}

#[derive(Debug, Serialize)]
struct ValidationSummary {
    results: Vec<ValidationResult>,
    total_files: usize,
    valid_count: usize,
    invalid_count: usize,
}

/// Lit de manière asynchrone le fichier par blocs et calcule le hash SHA-256.
async fn compute_sha256(path: &Path) -> Result<(String, u64)> {
    let mut file = File::open(path)
        .await
        .with_context(|| format!("Impossible d'ouvrir le fichier '{}'", path.display()))?;

    let mut hasher = Sha256::new();
    let mut buffer = [0u8; 64 * 1024]; // Buffer 64 KiB
    let mut total_bytes = 0u64;

    loop {
        let bytes_read = file
            .read(&mut buffer)
            .await
            .with_context(|| format!("Erreur lors de la lecture du fichier '{}'", path.display()))?;

        if bytes_read == 0 {
            break;
        }

        hasher.update(&buffer[..bytes_read]);
        total_bytes += bytes_read as u64;
    }

    let result = hasher.finalize();
    Ok((hex::encode(result), total_bytes))
}

/// Traite la commande de calcul de hachage
async fn handle_hash(args: HashArgs) -> Result<()> {
    let mut tasks = Vec::new();

    for path in args.files {
        tasks.push(tokio::spawn(async move {
            let res = compute_sha256(&path).await;
            (path, res)
        }));
    }

    let mut results = Vec::new();
    for task in tasks {
        let (path, hash_result) = task.await.context("Erreur d'exécution de la tâche asynchrone")?;
        let (hash, bytes_read) = hash_result?;
        results.push(HashResult {
            path: path.to_string_lossy().to_string(),
            hash,
            bytes_read,
        });
    }

    let summary = HashSummary {
        total_files: results.len(),
        results,
    };

    match args.format {
        OutputFormat::Text => {
            for item in &summary.results {
                println!("{}  {} ({} octets)", item.hash, item.path, item.bytes_read);
            }
        }
        OutputFormat::Json => {
            let json_str = serde_json::to_string_pretty(&summary)
                .context("Erreur lors de la sérialisation JSON")?;
            println!("{}", json_str);
        }
        OutputFormat::Template => {
            let template_str = if let Some(path) = args.template_file {
                tokio::fs::read_to_string(&path)
                    .await
                    .with_context(|| format!("Impossible de lire le template Tera '{}'", path.display()))?
            } else {
                args.template.unwrap_or_else(|| {
                    r#"=== Rapport SHA-256 ===
Total analysé : {{ total_files }} fichier(s)
{% for item in results %}
- {{ item.path }}: {{ item.hash }} ({{ item.bytes_read }} octets)
{% endfor %}
"#.to_string()
                })
            };

            let mut tera = Tera::default();
            tera.add_raw_template("output", &template_str)
                .context("Erreur de syntaxe dans le template Tera")?;

            let mut context = TeraContext::new();
            context.insert("results", &summary.results);
            context.insert("total_files", &summary.total_files);

            let rendered = tera
                .render("output", &context)
                .context("Erreur lors de l'application du template Tera")?;
            print!("{}", rendered);
        }
    }

    Ok(())
}

/// Parse un fichier de checksums au format classique `<hash>  <filename>` ou `<hash> *<filename>`
fn parse_checksum_file(content: &str) -> Vec<(PathBuf, String)> {
    let mut entries = Vec::new();
    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        let parts: Vec<&str> = trimmed.split_whitespace().collect();
        if parts.len() >= 2 {
            let hash = parts[0].to_ascii_lowercase();
            // Le chemin peut être précédé d'une étoile en mode binaire
            let file_part = parts[1..].join(" ");
            let file_path = file_part.trim_start_matches('*');
            entries.push((PathBuf::from(file_path), hash));
        }
    }
    entries
}

/// Traite la commande de validation de checksums
async fn handle_check(args: CheckArgs) -> Result<()> {
    let mut check_targets: Vec<(PathBuf, String)> = Vec::new();

    if let (Some(file), Some(expected)) = (args.file, args.expected) {
        check_targets.push((file, expected.trim().to_ascii_lowercase()));
    } else if let Some(checksum_path) = args.checksum_file {
        let content = tokio::fs::read_to_string(&checksum_path)
            .await
            .with_context(|| format!("Impossible de lire le fichier de checksums '{}'", checksum_path.display()))?;
        check_targets = parse_checksum_file(&content);
    } else {
        anyhow::bail!(
            "Paramètres invalides : spécifiez soit (--file et --expected), soit (--checksum-file)."
        );
    }

    if check_targets.is_empty() {
        anyhow::bail!("Aucun fichier ou empreinte à valider.");
    }

    let mut tasks = Vec::new();
    for (path, expected) in check_targets {
        tasks.push(tokio::spawn(async move {
            match compute_sha256(&path).await {
                Ok((actual, _bytes)) => {
                    let valid = actual.eq_ignore_ascii_case(&expected);
                    ValidationResult {
                        path: path.to_string_lossy().to_string(),
                        expected_hash: expected,
                        actual_hash: Some(actual),
                        valid,
                        error: None,
                    }
                }
                Err(err) => ValidationResult {
                    path: path.to_string_lossy().to_string(),
                    expected_hash: expected,
                    actual_hash: None,
                    valid: false,
                    error: Some(format!("{:#}", err)),
                },
            }
        }));
    }

    let mut results = Vec::new();
    let mut valid_count = 0;
    let mut invalid_count = 0;

    for task in tasks {
        let res = task.await.context("Erreur de jointure de tâche de validation")?;
        if res.valid {
            valid_count += 1;
        } else {
            invalid_count += 1;
        }
        results.push(res);
    }

    let summary = ValidationSummary {
        total_files: results.len(),
        valid_count,
        invalid_count,
        results,
    };

    match args.format {
        OutputFormat::Text => {
            for item in &summary.results {
                if item.valid {
                    println!("[OK]      {}", item.path);
                } else if let Some(err) = &item.error {
                    eprintln!("[ERREUR]  {} : {}", item.path, err);
                } else {
                    let actual = item.actual_hash.as_deref().unwrap_or("inconnu");
                    eprintln!(
                        "[ÉCHEC]   {} : attendu {}, obtenu {}",
                        item.path, item.expected_hash, actual
                    );
                }
            }
            println!(
                "\nBilan : {} valide(s), {} invalide(s) sur {} fichier(s).",
                summary.valid_count, summary.invalid_count, summary.total_files
            );
        }
        OutputFormat::Json => {
            let json_str = serde_json::to_string_pretty(&summary)
                .context("Erreur lors de la sérialisation JSON")?;
            println!("{}", json_str);
        }
        OutputFormat::Template => {
            let template_str = args.template.unwrap_or_else(|| {
                r#"=== Résultat de la validation ===
Fichiers valides   : {{ valid_count }}/{{ total_files }}
Fichiers invalides : {{ invalid_count }}/{{ total_files }}
{% for item in results %}
{% if item.valid %}[OK]     {{ item.path }}
{% else %}[ECHEC]  {{ item.path }} (attendu: {{ item.expected_hash }}, obtenu: {{ item.actual_hash | default(value="erreur") }})
{% endif %}{% endfor %}
"#.to_string()
            });

            let mut tera = Tera::default();
            tera.add_raw_template("validation", &template_str)
                .context("Erreur de template Tera")?;

            let mut context = TeraContext::new();
            context.insert("results", &summary.results);
            context.insert("total_files", &summary.total_files);
            context.insert("valid_count", &summary.valid_count);
            context.insert("invalid_count", &summary.invalid_count);

            let rendered = tera
                .render("validation", &context)
                .context("Erreur lors de l'application du template Tera")?;
            print!("{}", rendered);
        }
    }

    if summary.invalid_count > 0 {
        anyhow::bail!(
            "La vérification a échoué pour {} fichier(s).",
            summary.invalid_count
        );
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Hash(args) => handle_hash(args).await?,
        Commands::Check(args) => handle_check(args).await?,
    }

    Ok(())
}

