// src/main.rs
use std::path::{Path, PathBuf};
use anyhow::{Context, Result};
use clap::{Parser, Subcommand};
use ratatui::{
    backend::CrosstermBackend,
    layout::{Constraint, Rect},
    style::{Color, Modifier, Style},
    widgets::{Block, Borders, Cell, Row, Table},
    Terminal,
};
use sha2::{Digest, Sha256};
use tokio::fs::File;
use tokio::io::AsyncReadExt;
use tokio::task::JoinSet;

const BUFFER_SIZE: usize = 64 * 1024; // 64 Ko par lecture

#[derive(Parser, Debug)]
#[command(name = "sha256-validator")]
#[command(author, version, about = "Calcul et validation asynchrone d'empreintes SHA-256")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Calcule l'empreinte SHA-256 d'un ou plusieurs fichiers
    Compute {
        /// Liste des fichiers à analyser
        #[arg(required = true)]
        files: Vec<PathBuf>,
    },
    /// Valide l'empreinte SHA-256 d'un fichier donné par rapport à une valeur attendue
    Verify {
        /// Chemin du fichier
        file: PathBuf,
        /// Empreinte SHA-256 hexadécimale attendue
        expected_hash: String,
    },
    /// Valide une liste de fichiers à partir d'un fichier checksums (format: `<hash>  <fichier>`)
    CheckFile {
        /// Fichier contenant les paires hash/fichier
        checksum_file: PathBuf,
    },
}

#[derive(Debug, Clone)]
enum HashStatus {
    Ok,
    Mismatch { expected: String },
    Error(String),
}

#[derive(Debug, Clone)]
struct FileResult {
    file_path: String,
    calculated_hash: String,
    status: HashStatus,
}

async fn compute_sha256(path: &Path) -> std::result::Result<String, String> {
    let mut file = match File::open(path).await {
        Ok(f) => f,
        Err(e) => return Err(format!("Échec ouverture: {}", e)),
    };

    let mut hasher = Sha256::new();
    let mut buffer = vec![0u8; BUFFER_SIZE];

    loop {
        match file.read(&mut buffer).await {
            Ok(0) => break,
            Ok(bytes_read) => {
                hasher.update(&buffer[..bytes_read]);
            }
            Err(e) => return Err(format!("Échec lecture: {}", e)),
        }
    }

    let digest = hasher.finalize();
    Ok(hex::encode(digest))
}

fn render_results_table(results: &[FileResult]) -> Result<()> {
    let stdout = std::io::stdout();
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let term_size = terminal.size()?;
    let required_rows = (results.len() as u16).saturating_add(4);
    let width = term_size.width.max(100);
    let height = required_rows.max(5);

    let rows: Vec<Row> = results
        .iter()
        .map(|res| {
            let (status_text, status_style) = match &res.status {
                HashStatus::Ok => ("OK", Style::default().fg(Color::Green).add_modifier(Modifier::BOLD)),
                HashStatus::Mismatch { .. } => (
                    "MISMATCH",
                    Style::default().fg(Color::Red).add_modifier(Modifier::BOLD),
                ),
                HashStatus::Error(_) => ("ERROR", Style::default().fg(Color::Yellow)),
            };

            let hash_cell = match &res.status {
                HashStatus::Error(err) => Cell::from(format!("Erreur: {}", err)),
                HashStatus::Mismatch { expected } => {
                    Cell::from(format!("Calculé: {}\nAttendu: {}", res.calculated_hash, expected))
                }
                HashStatus::Ok => Cell::from(res.calculated_hash.clone()),
            };

            Row::new(vec![
                Cell::from(res.file_path.clone()),
                hash_cell,
                Cell::from(status_text).style(status_style),
            ])
        })
        .collect();

    let header = Row::new(vec![
        Cell::from("Fichier").style(Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
        Cell::from("Empreinte SHA-256").style(Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
        Cell::from("Statut").style(Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
    ])
    .bottom_margin(1);

    let table = Table::new(
        rows,
        [
            Constraint::Percentage(30),
            Constraint::Percentage(55),
            Constraint::Percentage(15),
        ],
    )
    .header(header)
    .block(
        Block::default()
            .borders(Borders::ALL)
            .title(" Résultat de validation SHA-256 ")
            .style(Style::default().fg(Color::White)),
    );

    terminal.draw(|f| {
        let area = Rect::new(0, 0, width.min(f.area().width), height.min(f.area().height));
        f.render_widget(table, area);
    })?;

    println!();
    Ok(())
}

async fn handle_compute(files: Vec<PathBuf>) -> Result<()> {
    let mut join_set = JoinSet::new();

    for path in files {
        join_set.spawn(async move {
            let path_str = path.display().to_string();
            match compute_sha256(&path).await {
                Ok(hash) => FileResult {
                    file_path: path_str,
                    calculated_hash: hash,
                    status: HashStatus::Ok,
                },
                Err(err) => FileResult {
                    file_path: path_str,
                    calculated_hash: String::from("-"),
                    status: HashStatus::Error(err),
                },
            }
        });
    }

    let mut results = Vec::new();
    while let Some(res) = join_set.join_next().await {
        match res {
            Ok(item) => results.push(item),
            Err(e) => eprintln!("Erreur d'exécution de tâche: {}", e),
        }
    }

    results.sort_by(|a, b| a.file_path.cmp(&b.file_path));
    render_results_table(&results)?;
    Ok(())
}

async fn handle_verify(file: PathBuf, expected_hash: String) -> Result<()> {
    let expected_clean = expected_hash.trim().to_ascii_lowercase();
    let path_str = file.display().to_string();

    let result = match compute_sha256(&file).await {
        Ok(calc) => {
            let status = if calc.eq_ignore_ascii_case(&expected_clean) {
                HashStatus::Ok
            } else {
                HashStatus::Mismatch {
                    expected: expected_clean,
                }
            };
            FileResult {
                file_path: path_str,
                calculated_hash: calc,
                status,
            }
        }
        Err(err) => FileResult {
            file_path: path_str,
            calculated_hash: String::from("-"),
            status: HashStatus::Error(err),
        },
    };

    render_results_table(&[result])?;
    Ok(())
}

async fn handle_check_file(checksum_file: PathBuf) -> Result<()> {
    let content = tokio::fs::read_to_string(&checksum_file)
        .await
        .with_context(|| format!("Impossible de lire le fichier {}", checksum_file.display()))?;

    let base_dir = checksum_file
        .parent()
        .map(|p| p.to_path_buf())
        .unwrap_or_else(|| PathBuf::from("."));

    let mut join_set = JoinSet::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }

        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() < 2 {
            continue;
        }

        let expected_hash = parts[0].to_ascii_lowercase();
        let relative_path = parts[1..].join(" ");
        let full_path = base_dir.join(&relative_path);

        join_set.spawn(async move {
            let path_str = relative_path;
            match compute_sha256(&full_path).await {
                Ok(calc) => {
                    let status = if calc.eq_ignore_ascii_case(&expected_hash) {
                        HashStatus::Ok
                    } else {
                        HashStatus::Mismatch {
                            expected: expected_hash,
                        }
                    };
                    FileResult {
                        file_path: path_str,
                        calculated_hash: calc,
                        status,
                    }
                }
                Err(err) => FileResult {
                    file_path: path_str,
                    calculated_hash: String::from("-"),
                    status: HashStatus::Error(err),
                },
            }
        });
    }

    let mut results = Vec::new();
    while let Some(res) = join_set.join_next().await {
        match res {
            Ok(item) => results.push(item),
            Err(e) => eprintln!("Erreur d'exécution de tâche: {}", e),
        }
    }

    results.sort_by(|a, b| a.file_path.cmp(&b.file_path));
    render_results_table(&results)?;
    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Compute { files } => handle_compute(files).await?,
        Commands::Verify {
            file,
            expected_hash,
        } => handle_verify(file, expected_hash).await?,
        Commands::CheckFile { checksum_file } => handle_check_file(checksum_file).await?,
    }

    Ok(())
}

