        /// Adresse d'écoute (ex: 127.0.0.1:3000)
        #[arg(short, long, default_value = "127.0.0.1:3000")]
        bind: SocketAddr,

        /// Fichier de sortie Parquet où accumuler les logs
        #[arg(short, long, default_value = "logs_output.parquet")]
        output: PathBuf,

        /// Capacité du tampon en mémoire avant écriture
        #[arg(short, long, default_value_t = 100)]
        buffer_size: usize,
    },
}

/// Définition du schéma Arrow correspondant aux logs traités
fn build_arrow_schema() -> Arc<Schema> {
    Arc::new(Schema::new(vec![
        Field::new("timestamp_ms", DataType::Int64, false),
        Field::new("level", DataType::Utf8, false),
        Field::new("service", DataType::Utf8, false),
        Field::new("message", DataType::Utf8, false),
        Field::new("trace_id", DataType::Utf8, false),
    ]))
}

/// Convertit un vecteur de ProcessedLogRecord en RecordBatch Arrow
fn build_record_batch(records: &[ProcessedLogRecord], schema: Arc<Schema>) -> Result<RecordBatch> {
    let mut timestamps = Vec::with_capacity(records.len());
    let mut level_builder = StringBuilder::with_capacity(records.len(), records.len() * 8);
    let mut service_builder = StringBuilder::with_capacity(records.len(), records.len() * 16);
    let mut message_builder = StringBuilder::with_capacity(records.len(), records.len() * 64);
    let mut trace_id_builder = StringBuilder::with_capacity(records.len(), records.len() * 32);

    for r in records {
        timestamps.push(r.timestamp_ms);
        level_builder.append_value(&r.level);
        service_builder.append_value(&r.service);
        message_builder.append_value(&r.message);
        trace_id_builder.append_value(&r.trace_id);
    }

    let timestamp_arr: ArrayRef = Arc::new(Int64Array::from(timestamps));
    let level_arr: ArrayRef = Arc::new(level_builder.finish());
    let service_arr: ArrayRef = Arc::new(service_builder.finish());
    let message_arr: ArrayRef = Arc::new(message_builder.finish());
    let trace_id_arr: ArrayRef = Arc::new(trace_id_builder.finish());

    RecordBatch::try_new(
        schema,
        vec![
            timestamp_arr,
            level_arr,
            service_arr,
            message_arr,
            trace_id_arr,
        ],
    )
    .context("Échec de la construction du RecordBatch Arrow")
}

/// Tâche d'arrière-plan gérant l'écriture asynchrone dans le fichier Parquet
async fn parquet_writer_task(
    mut rx: mpsc::Receiver<WriterMessage>,
    output_path: PathBuf,
) -> Result<()> {
    let schema = build_arrow_schema();
    let file = OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .open(&output_path)
        .await
        .with_context(|| format!("Impossible d'ouvrir le fichier {:?}", output_path))?;

    let props = WriterProperties::builder()
        .set_compression(Compression::SNAPPY)
        .build();

    let mut writer = AsyncArrowWriter::try_new(file, schema.clone(), Some(props))
        .context("Initialisation du AsyncArrowWriter Parquet échouée")?;

    info!(path = ?output_path, "Writer Parquet initialisé avec succès");

    while let Some(msg) = rx.recv().await {
        match msg {
            WriterMessage::WriteBatch(records) => {
                if records.is_empty() {
                    continue;
                }
                match build_record_batch(&records, schema.clone()) {
                    Ok(batch) => {
                        if let Err(e) = writer.write(&batch).await {
                            error!("Erreur lors de l'écriture du RecordBatch : {e}");
                        }
                    }
                    Err(e) => {
                        error!("Erreur lors de la conversion en RecordBatch : {e}");
                    }
                }
            }
            WriterMessage::Flush(responder) => {
                let res = writer.flush().await.context("Erreur lors du flush Parquet");
                let _ = responder.send(res);
            }
        }
    }

    writer
        .close()
        .await
        .context("Erreur lors de la fermeture du AsyncArrowWriter")?;

    info!(path = ?output_path, "Fichier Parquet finalisé et fermé");
    Ok(())
}

/// Gestion de la commande 'convert' : lecture streaming d'un ndjson vers Parquet
async fn run_convert(input_path: &Path, output_path: &Path, batch_size: usize) -> Result<()> {
    info!(input = ?input_path, output = ?output_path, batch_size, "Démarrage de la conversion");

    let file = File::open(input_path)
        .await
        .with_context(|| format!("Fichier introuvable : {:?}", input_path))?;

    let (tx, rx) = mpsc::channel::<WriterMessage>(32);
    let writer_handle = tokio::spawn(parquet_writer_task(rx, output_path.to_path_buf()));

    let reader = BufReader::new(file);
    let mut lines = reader.lines();
    let mut current_batch = Vec::with_capacity(batch_size);
    let mut line_counter: u64 = 0;
    let mut error_counter: u64 = 0;

    while let Some(line) = lines.next_line().await.context("Lecture de ligne échouée")? {
        line_counter += 1;
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }

        match serde_json::from_str::<RawLogRecord>(trimmed) {
            Ok(raw) => {
                current_batch.push(ProcessedLogRecord::normalize(raw));
                if current_batch.len() >= batch_size {
                    let to_send = std::mem::replace(&mut current_batch, Vec::with_capacity(batch_size));
                    if let Err(e) = tx.send(WriterMessage::WriteBatch(to_send)).await {
                        warn!("Writer channel fermé prématurément : {e}");
                        break;
                    }
                }
            }
            Err(e) => {
                error_counter += 1;
                warn!(line_number = line_counter, error = ?e, "Ligne JSON invalide ignorée");
            }
        }
    }

    if !current_batch.is_empty() {
        let _ = tx.send(WriterMessage::WriteBatch(current_batch)).await;
    }

    // Fermer le canal d'envoi pour permettre au writer de terminer et fermer le fichier
    drop(tx);

    match writer_handle.await {
        Ok(res) => res.context("Erreur pendant l'exécution du parquet writer")?,
        Err(e) => anyhow::bail!("La tâche du Parquet writer a paniqué : {e}"),
    }

    info!(
        lignes_traitees = line_counter,
        erreurs = error_counter,
        "Conversion terminée avec succès"
    );
    Ok(())
}

/// État partagé du serveur HTTP axum
#[derive(Clone)]
struct AppState {
    tx: mpsc::Sender<WriterMessage>,
}

/// Handler santé / statut
async fn health_check() -> impl IntoResponse {
    (StatusCode::OK, "Service opérationnel")
}

/// Handler d'ingestion d'un log unitaire
async fn ingest_single_log(
    State(state): State<AppState>,
    Json(payload): Json<RawLogRecord>,
) -> impl IntoResponse {
    let processed = ProcessedLogRecord::normalize(payload);
    if let Err(e) = state.tx.send(WriterMessage::WriteBatch(vec![processed])).await {
        error!("Impossible d'envoyer le log au canal : {e}");
        return (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(serde_json::json!({ "status": "error", "message": "Queue pleine ou fermée" })),
        );
    }

    (
        StatusCode::ACCEPTED,
        Json(serde_json::json!({ "status": "queued" })),
    )
}

/// Handler d'ingestion de logs par batch
async fn ingest_batch_logs(
    State(state): State<AppState>,
    Json(payload): Json<Vec<RawLogRecord>>,
) -> impl IntoResponse {
    let count = payload.len();
    let processed: Vec<ProcessedLogRecord> = payload
        .into_iter()
        .map(ProcessedLogRecord::normalize)
        .collect();

    if let Err(e) = state.tx.send(WriterMessage::WriteBatch(processed)).await {
        error!("Impossible d'envoyer le batch au canal : {e}");
        return (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(serde_json::json!({ "status": "error", "message": "Queue pleine ou fermée" })),
        );
    }

    (
        StatusCode::ACCEPTED,
        Json(serde_json::json!({ "status": "queued", "count": count })),
    )
}

/// Handler de flush synchrone pour forcer l'écriture immédiate sur disque
async fn flush_logs(
    State(state): State<AppState>,
) -> impl IntoResponse {
    let (tx_resp, rx_resp) = oneshot::channel();
    if let Err(e) = state.tx.send(WriterMessage::Flush(tx_resp)).await {
        error!("Impossible d'envoyer la demande de flush : {e}");
        return (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(serde_json::json!({ "status": "error", "message": "Queue inaccessible" })),
        );
    }

    match rx_resp.await {
        Ok(Ok(())) => (
            StatusCode::OK,
            Json(serde_json::json!({ "status": "flushed" })),
        ),
        Ok(Err(e)) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(serde_json::json!({ "status": "error", "message": e.to_string() })),
        ),
        Err(_) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(serde_json::json!({ "status": "error", "message": "Répondeur de flush annulé" })),
        ),
    }
}

/// Démarrage du serveur Axum avec arrêt gracieux (Graceful Shutdown)
async fn run_serve(bind_addr: SocketAddr, output_path: PathBuf, buffer_size: usize) -> Result<()> {
    info!(bind = ?bind_addr, output = ?output_path, "Démarrage du serveur d'ingestion de logs");

    let (tx, rx) = mpsc::channel::<WriterMessage>(buffer_size);
    let writer_handle = tokio::spawn(parquet_writer_task(rx, output_path));

    let state = AppState { tx };

    let app = Router::new()
        .route("/health", get(health_check))
        .route("/flush", post(flush_logs))
        .route("/logs", post(ingest_single_log))
        .route("/logs/batch", post(ingest_batch_logs))
        .with_state(state);

    let listener = tokio::net::TcpListener::bind(bind_addr)
        .await
        .with_context(|| format!("Impossible de lier l'adresse {}", bind_addr))?;

    info!("Serveur à l'écoute sur http://{}", bind_addr);

    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await
        .context("Erreur pendant l'exécution du serveur HTTP")?;

    // Attente de la clôture du Parquet Writer après arrêt du serveur
    match writer_handle.await {
        Ok(res) => res.context("Erreur à la fermeture du Parquet writer")?,
        Err(e) => anyhow::bail!("La tâche Parquet writer a échoué : {e}"),
    }

    info!("Arrêt propre du service terminé");
    Ok(())
}

/// Signal d'arrêt (Ctrl+C ou SIGTERM)
async fn shutdown_signal() {
    let ctrl_c = async {
        tokio::signal::ctrl_c()
            .await
            .expect("Échec d'écoute du signal Ctrl+C");
    };

    #[cfg(unix)]
    let terminate = async {
        tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())
            .expect("Échec d'écoute du signal SIGTERM")
            .recv()
            .await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {
            info!("Signal Ctrl+C intercepté, arrêt gracieux en cours...");
        },
        _ = terminate => {
            info!("Signal SIGTERM intercepté, arrêt gracieux en cours...");
        },
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    // Initialisation du logging avec filtre d'environnement (RUST_LOG=info par défaut)
    tracing_subscriber::registry()
        .with(EnvFilter::try_from_default_env().unwrap_or_else(|_| "info,log2parquet=debug".into()))
        .with(tracing_subscriber::fmt::layer())
        .init();

    let cli = Cli::parse();

    match cli.command {
        Commands::Convert {
            input,
            output,
            batch_size,
        } => {
            run_convert(&input, &output, batch_size).await?;
        }
        Commands::Serve {
            bind,
            output,
            buffer_size,
        } => {
            run_serve(bind, output, buffer_size).await?;
        }
    }

    Ok(())
}

