/// Format de compression Parquet supporté en CLI
#[derive(Debug, Clone, Copy, ValueEnum)]
enum CliCompression {
    Uncompressed,
    Snappy,
    Gzip,
    Zstd,
    Lz4,
}

impl From<CliCompression> for Compression {
    fn from(c: CliCompression) -> Self {
        match c {
            CliCompression::Uncompressed => Compression::UNCOMPRESSED,
            CliCompression::Snappy => Compression::SNAPPY,
            CliCompression::Gzip => Compression::GZIP(Default::default()),
            CliCompression::Zstd => Compression::ZSTD(Default::default()),
            CliCompression::Lz4 => Compression::LZ4,
        }
    }
}

/// CLI asynchrone pour parser, transformer et exporter des logs JSON vers le format Parquet
#[derive(Parser, Debug)]
#[command(name = "json-log-to-parquet", version, about, long_about = None)]
struct Cli {
    /// Chemin du fichier d'entrée contenant les logs JSON (un objet JSON par ligne / JSON Lines)
    #[arg(short, long, value_name = "INPUT_FILE")]
    input: PathBuf,

    /// Chemin du fichier de sortie Parquet (.parquet)
    #[arg(short, long, value_name = "OUTPUT_FILE")]
    output: PathBuf,

    /// Taille du lot (batch size) pour la constitution des RecordBatches Arrow
    #[arg(short, long, default_value_t = 8192)]
    batch_size: usize,

    /// Algorithme de compression pour le fichier Parquet
    #[arg(short, long, value_enum, default_value_t = CliCompression::Snappy)]
    compression: CliCompression,

    /// Niveau de log minimal optionnel pour filtrer les entrées (ex: INFO, WARN, ERROR)
    #[arg(long)]
    filter_level: Option<String>,
}

/// Structure représentant un log JSON d'entrée
#[derive(Debug, Clone, Deserialize, Serialize)]
struct RawLogEntry {
    /// Horodatage RFC3339 ou format date-heure standard (ex: 2026-09-27T12:00:00Z)
    pub timestamp: String,
    /// Niveau de sévérité du log (ex: INFO, WARN, ERROR)
    pub level: String,
    /// Service ou composant émetteur
    pub service: String,
    /// Message principal du log
    pub message: String,
    /// Code HTTP de statut éventuel
    pub status_code: Option<i32>,
    /// Métadonnées contextuelles sous forme de chaîne JSON brute
    pub details: Option<serde_json::Value>,
}

/// Structure de log transformée et normalisée
#[derive(Debug, Clone)]
struct NormalizedLog {
    pub timestamp_ms: i64,
    pub level: String,
    pub service: String,
    pub message: String,
    pub status_code: Option<i32>,
    pub details_json: Option<String>,
}

impl RawLogEntry {
    /// Valide, normalise et transforme l'entrée brute
    fn transform(self) -> Result<NormalizedLog> {
        let parsed_time = chrono::DateTime::parse_from_rfc3339(&self.timestamp)
            .or_else(|_| {
                chrono::NaiveDateTime::parse_from_str(&self.timestamp, "%Y-%m-%d %H:%M:%S")
                    .map(|ndt| ndt.and_utc().fixed_offset())
            })
            .with_context(|| format!("Format d'horodatage invalide: '{}'", self.timestamp))?;

        let timestamp_ms = parsed_time.timestamp_millis();
        let level = self.level.to_ascii_uppercase();
        let details_json = self.details.map(|d| d.to_string());

        Ok(NormalizedLog {
            timestamp_ms,
            level,
            service: self.service,
            message: self.message,
            status_code: self.status_code,
            details_json,
        })
    }
}

/// Définition du schéma Arrow correspondant aux logs Parquet cibles
fn build_arrow_schema() -> Arc<Schema> {
    Arc::new(Schema::new(vec![
        Field::new(
            "timestamp",
            DataType::Timestamp(TimeUnit::Millisecond, Some("UTC".into())),
            false,
        ),
        Field::new("level", DataType::Utf8, false),
        Field::new("service", DataType::Utf8, false),
        Field::new("message", DataType::Utf8, false),
        Field::new("status_code", DataType::Int32, true),
        Field::new("details", DataType::Utf8, true),
    ]))
}

/// Construit un `RecordBatch` Arrow à partir d'un ensemble de logs normalisés
fn build_record_batch(schema: &Arc<Schema>, logs: &[NormalizedLog]) -> Result<RecordBatch> {
    let mut timestamps = Vec::with_capacity(logs.len());
    let mut levels = Vec::with_capacity(logs.len());
    let mut services = Vec::with_capacity(logs.len());
    let mut messages = Vec::with_capacity(logs.len());
    let mut status_codes: Vec<Option<i32>> = Vec::with_capacity(logs.len());
    let mut details: Vec<Option<&str>> = Vec::with_capacity(logs.len());

    for item in logs {
        timestamps.push(item.timestamp_ms);
        levels.push(item.level.as_str());
        services.push(item.service.as_str());
        messages.push(item.message.as_str());
        status_codes.push(item.status_code);
        details.push(item.details_json.as_deref());
    }

    let timestamp_array: ArrayRef = Arc::new(
        TimestampMillisecondArray::from(timestamps).with_timezone("UTC"),
    );
    let level_array: ArrayRef = Arc::new(StringArray::from(levels));
    let service_array: ArrayRef = Arc::new(StringArray::from(services));
    let message_array: ArrayRef = Arc::new(StringArray::from(messages));
    let status_code_array: ArrayRef = Arc::new(Int32Array::from(status_codes));
    let details_array: ArrayRef = Arc::new(StringArray::from(details));

    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![
            timestamp_array,
            level_array,
            service_array,
            message_array,
            status_code_array,
            details_array,
        ],
    )
    .context("Échec de la construction du RecordBatch Arrow")?;

    Ok(batch)
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    let args = Cli::parse();

    info!(
        input = %args.input.display(),
        output = %args.output.display(),
        batch_size = args.batch_size,
        compression = ?args.compression,
        "Démarrage de la conversion JSON vers Parquet"
    );

    let input_file = File::open(&args.input)
        .await
        .with_context(|| format!("Impossible d'ouvrir le fichier d'entrée: {:?}", args.input))?;

    let output_file = File::create(&args.output)
        .await
        .with_context(|| format!("Impossible de créer le fichier de sortie: {:?}", args.output))?;

    let schema = build_arrow_schema();

    let writer_properties = WriterProperties::builder()
        .set_compression(args.compression.into())
        .build();

    let mut parquet_writer = AsyncArrowWriter::try_new(
        output_file,
        schema.clone(),
        Some(writer_properties),
    )
    .context("Initialisation de l'AsyncArrowWriter Parquet échouée")?;

    let mut reader = BufReader::new(input_file).lines();
    let mut current_batch: Vec<NormalizedLog> = Vec::with_capacity(args.batch_size);

    let filter_level = args.filter_level.as_ref().map(|s| s.to_ascii_uppercase());
    let mut total_lines = 0usize;
    let mut processed_lines = 0usize;
    let mut skipped_lines = 0usize;
    let mut batches_written = 0usize;

    while let Some(line) = reader.next_line().await.context("Erreur de lecture asynchrone du flux d'entrée")? {
        total_lines += 1;
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }

        let raw_entry: RawLogEntry = match serde_json::from_str(trimmed) {
            Ok(entry) => entry,
            Err(err) => {
                warn!(line_number = total_lines, error = %err, "Ligne JSON malformée, ligne ignorée");
                skipped_lines += 1;
                continue;
            }
        };

        let normalized = match raw_entry.transform() {
            Ok(entry) => entry,
            Err(err) => {
                warn!(line_number = total_lines, error = %err, "Transformation du log impossible, ligne ignorée");
                skipped_lines += 1;
                continue;
            }
        };

        if let Some(ref required_level) = filter_level {
            if normalized.level != *required_level {
                continue;
            }
        }

        current_batch.push(normalized);
        processed_lines += 1;

        if current_batch.len() >= args.batch_size {
            let record_batch = build_record_batch(&schema, &current_batch)?;
            parquet_writer
                .write(&record_batch)
                .await
                .context("Erreur lors de l'écriture asynchrone du RecordBatch dans Parquet")?;
            batches_written += 1;
            current_batch.clear();
        }
    }

    if !current_batch.is_empty() {
        let record_batch = build_record_batch(&schema, &current_batch)?;
        parquet_writer
            .write(&record_batch)
            .await
            .context("Erreur lors de l'écriture du dernier RecordBatch dans Parquet")?;
        batches_written += 1;
        current_batch.clear();
    }

    parquet_writer
        .close()
        .await
        .context("Erreur lors de la finalisation du fichier Parquet")?;

    info!(
        total_lines = total_lines,
        processed_lines = processed_lines,
        skipped_lines = skipped_lines,
        batches_written = batches_written,
        "Conversion terminée avec succès."
    );

    Ok(())
}

