// src/main.rs
use std::fs::File;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use anyhow::{Context, Result};
use arrow::array::{ArrayRef, Int64Array, StringArray};
use arrow::datatypes::{DataType, Field, Schema};
use arrow::record_batch::RecordBatch;
use clap::Parser;
use parquet::arrow::ArrowWriter;
use parquet::basic::Compression;
use parquet::file::properties::WriterProperties;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use tokio::io::{AsyncBufReadExt, BufReader};
use tracing::{error, info, warn};

/// CLI asynchrone pour parser, enrichir et convertir des flux de logs JSON (NDJSON) vers Parquet.
#[derive(Parser, Debug)]
#[command(name = "log2parquet", author, version, about, long_about = None)]
struct Args {
    /// Chemin du fichier d'entrée contenant les logs JSON (un objet par ligne - NDJSON)
    #[arg(short, long)]
    input: PathBuf,

    /// Chemin du fichier Parquet de sortie
    #[arg(short, long)]
    output: PathBuf,

    /// Taille maximale du lot (batch) de lignes en mémoire avant écriture Parquet
    #[arg(short, long, default_value_t = 10_000)]
    batch_size: usize,

    /// Algorithme de compression pour Parquet (snappy, zstd, gzip, uncompressed)
    #[arg(short, long, default_value = "snappy")]
    compression: String,
}

/// Structure d'entrée brute désérialisée depuis le log JSON.
#[derive(Debug, Deserialize, Serialize)]
struct RawLogEntry {
    #[serde(default)]
    timestamp: Option<String>,
    #[serde(default)]
    level: Option<String>,
    #[serde(default)]
    service: Option<String>,
    #[serde(default)]
    message: Option<String>,
    #[serde(default)]
    raw_payload: Option<serde_json::Value>,
}

/// Structure normalisée et enrichie avec empreinte SHA-256.
#[derive(Debug)]
struct ProcessedLogRecord {
    timestamp: String,
    level: String,
    service: String,
    message: String,
    payload_json: String,
    sha256_hash: String,
    byte_size: i64,
}

fn compute_sha256_hex(input: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(input);
    let digest = hasher.finalize();
    hex::encode(digest)
}

fn build_parquet_schema() -> Arc<Schema> {
    Arc::new(Schema::new(vec![
        Field::new("timestamp", DataType::Utf8, false),
        Field::new("level", DataType::Utf8, false),
        Field::new("service", DataType::Utf8, false),
        Field::new("message", DataType::Utf8, false),
        Field::new("payload_json", DataType::Utf8, false),
        Field::new("sha256_hash", DataType::Utf8, false),
        Field::new("byte_size", DataType::Int64, false),
    ]))
}

fn records_to_record_batch(
    records: &[ProcessedLogRecord],
    schema: &Arc<Schema>,
) -> Result<RecordBatch> {
    let timestamps: Vec<&str> = records.iter().map(|r| r.timestamp.as_str()).collect();
    let levels: Vec<&str> = records.iter().map(|r| r.level.as_str()).collect();
    let services: Vec<&str> = records.iter().map(|r| r.service.as_str()).collect();
    let messages: Vec<&str> = records.iter().map(|r| r.message.as_str()).collect();
    let payloads: Vec<&str> = records.iter().map(|r| r.payload_json.as_str()).collect();
    let hashes: Vec<&str> = records.iter().map(|r| r.sha256_hash.as_str()).collect();
    let byte_sizes: Vec<i64> = records.iter().map(|r| r.byte_size).collect();

    let columns: Vec<ArrayRef> = vec![
        Arc::new(StringArray::from(timestamps)),
        Arc::new(StringArray::from(levels)),
        Arc::new(StringArray::from(services)),
        Arc::new(StringArray::from(messages)),
        Arc::new(StringArray::from(payloads)),
        Arc::new(StringArray::from(hashes)),
        Arc::new(Int64Array::from(byte_sizes)),
    ];

    RecordBatch::try_new(Arc::clone(schema), columns)
        .context("Échec de création du RecordBatch Arrow")
}

fn resolve_compression(compression_str: &str) -> Compression {
    match compression_str.to_ascii_lowercase().as_str() {
        "snappy" => Compression::SNAPPY,
        "zstd" => Compression::ZSTD(Default::default()),
        "gzip" => Compression::GZIP(Default::default()),
        "uncompressed" => Compression::UNCOMPRESSED,
        other => {
            warn!(
                "Algorithme de compression inconnu '{}', repli sur Snappy",
                other
            );
            Compression::SNAPPY
        }
    }
}

async fn process_logs<P: AsRef<Path>>(
    input_path: P,
    output_path: P,
    batch_size: usize,
    compression: Compression,
) -> Result<()> {
    let file = tokio::fs::File::open(input_path.as_ref())
        .await
        .with_context(|| {
            format!(
                "Impossible d'ouvrir le fichier d'entrée : {:?}",
                input_path.as_ref()
            )
        })?;

    // Flux bufferisé asynchrone avec tokio::io::BufReader
    let mut reader = BufReader::with_capacity(64 * 1024, file);
    let mut line_buffer = String::new();

    let schema = build_parquet_schema();

    let output_file = File::create(output_path.as_ref()).with_context(|| {
        format!(
            "Impossible de créer le fichier de sortie Parquet : {:?}",
            output_path.as_ref()
        )
    })?;

    let props = WriterProperties::builder()
        .set_compression(compression)
        .build();

    let mut writer = ArrowWriter::try_new(output_file, Arc::clone(&schema), Some(props))
        .context("Initialisation du writer Parquet Arrow impossible")?;

    let mut batch: Vec<ProcessedLogRecord> = Vec::with_capacity(batch_size);
    let mut total_lines: usize = 0;
    let mut processed_lines: usize = 0;
    let mut malformed_lines: usize = 0;

    loop {
        line_buffer.clear();
        let bytes_read = reader
            .read_line(&mut line_buffer)
            .await
            .context("Erreur lors de la lecture asynchrone d'une ligne")?;

        if bytes_read == 0 {
            break;
        }

        total_lines += 1;
        let trimmed = line_buffer.trim();
        if trimmed.is_empty() {
            continue;
        }

        // Parse JSON
        match serde_json::from_str::<RawLogEntry>(trimmed) {
            Ok(entry) => {
                let sha256_hash = compute_sha256_hex(trimmed.as_bytes());
                let payload_json = entry
                    .raw_payload
                    .as_ref()
                    .map(|v| v.to_string())
                    .unwrap_or_else(|| "{}".to_string());

                let record = ProcessedLogRecord {
                    timestamp: entry
                        .timestamp
                        .unwrap_or_else(|| chrono::Utc::now().to_rfc3339()),
                    level: entry.level.unwrap_or_else(|| "INFO".to_string()),
                    service: entry.service.unwrap_or_else(|| "unknown".to_string()),
                    message: entry.message.unwrap_or_default(),
                    payload_json,
                    sha256_hash,
                    byte_size: trimmed.len() as i64,
                };

                batch.push(record);
                processed_lines += 1;

                if batch.len() >= batch_size {
                    let record_batch = records_to_record_batch(&batch, &schema)?;
                    writer
                        .write(&record_batch)
                        .context("Erreur lors de l'écriture d'un batch dans le fichier Parquet")?;
                    batch.clear();
                }
            }
            Err(e) => {
                malformed_lines += 1;
                warn!(
                    line_number = total_lines,
                    error = %e,
                    "Ligne JSON ignorée car non parseable"
                );
            }
        }
    }

    if !batch.is_empty() {
        let record_batch = records_to_record_batch(&batch, &schema)?;
        writer
            .write(&record_batch)
            .context("Erreur lors de l'écriture du batch résiduel")?;
        batch.clear();
    }

    writer
        .close()
        .context("Erreur lors de la finalisation du fichier Parquet")?;

    info!(
        total_lines = total_lines,
        processed_lines = processed_lines,
        malformed_lines = malformed_lines,
        "Traitement terminé avec succès. Fichier Parquet produit : {:?}",
        output_path.as_ref()
    );

    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    let args = Args::parse();
    let compression = resolve_compression(&args.compression);

    info!(
        input = ?args.input,
        output = ?args.output,
        batch_size = args.batch_size,
        compression = ?args.compression,
        "Démarrage de la conversion log JSON -> Parquet"
    );

    if let Err(err) = process_logs(&args.input, &args.output, args.batch_size, compression).await {
        error!(error = ?err, "Échec de l'exécution de la CLI");
        return Err(err);
    }

    Ok(())
}

