    let mut service_builder = StringBuilder::with_capacity(capacity, capacity * 16);
    let mut message_builder = StringBuilder::with_capacity(capacity, capacity * 64);
    let mut metadata_builder = StringBuilder::with_capacity(capacity, capacity * 64);
    let mut hash_builder = StringBuilder::with_capacity(capacity, capacity * 64);

    for entry in entries {
        timestamp_builder.append_value(&entry.timestamp);
        level_builder.append_value(&entry.level);
        service_builder.append_value(&entry.service);
        message_builder.append_value(&entry.message);

        match &entry.metadata {
            Some(meta) => metadata_builder.append_value(meta),
            None => metadata_builder.append_null(),
        }

        hash_builder.append_value(&entry.sha256_hash);
    }

    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![
            Arc::new(timestamp_builder.finish()),
            Arc::new(level_builder.finish()),
            Arc::new(service_builder.finish()),
            Arc::new(message_builder.finish()),
            Arc::new(metadata_builder.finish()),
            Arc::new(hash_builder.finish()),
        ],
    ).context("Échec de création du RecordBatch Arrow")?;

    Ok(batch)
}

/// Traite un lot de lignes brutes en parallèle avec Rayon pour désérialiser et hacher avec SHA-256
fn process_batch_multithreaded(raw_lines: Vec<String>) -> Vec<ProcessedLogEntry> {
    raw_lines
        .into_par_iter()
        .filter_map(|line| {
            let trimmed = line.trim();
            if trimmed.is_empty() {
                return None;
            }

            match serde_json::from_str::<RawLogEntry>(trimmed) {
                Ok(raw_entry) => Some(raw_entry.into_processed(trimmed)),
                Err(err) => {
                    warn!(error = %err, line = %trimmed, "Ligne JSON invalide ignorée");
                    None
                }
            }
        })
        .collect()
}

#[tokio::main]
async fn main() -> Result<()> {
    let args = Args::parse();

    // Initialisation du logging
    let filter = if args.verbose {
        EnvFilter::new("json_to_parquet=debug,info")
    } else {
        EnvFilter::new("json_to_parquet=info,warn,error")
    };
    tracing_subscriber::fmt()
        .with_env_filter(filter)
        .with_target(false)
        .init();

    // Configuration du pool global de threads Rayon si demandé
    if let Some(thread_count) = args.threads {
        rayon::ThreadPoolBuilder::new()
            .num_threads(thread_count)
            .build_global()
            .context("Échec d'initialisation du pool de threads Rayon")?;
        info!(threads = thread_count, "Pool de threads Rayon configuré");
    } else {
        info!(
            threads = rayon::current_num_threads(),
            "Pool de threads Rayon initialisé par défaut"
        );
    }

    info!(
        input = %args.input.display(),
        output = %args.output.display(),
        batch_size = args.batch_size,
        compression = ?args.compression,
        "Démarrage du traitement"
    );

    // Vérification et ouverture du fichier source en asynchrone avec tokio::fs
    let input_file = tokio::fs::File::open(&args.input)
        .await
        .with_context(|| format!("Impossible d'ouvrir le fichier d'entrée '{}'", args.input.display()))?;
    let mut reader = BufReader::new(input_file).lines();

    // Préparation de l'écriture Parquet
    let schema = build_arrow_schema();
    let props = WriterProperties::builder()
        .set_compression(args.compression.into())
        .build();

    let output_file = File::create(&args.output)
        .with_context(|| format!("Impossible de créer le fichier de sortie '{}'", args.output.display()))?;

    let mut writer = ArrowWriter::try_new(output_file, schema.clone(), Some(props))
        .context("Échec d'initialisation du ArrowWriter Parquet")?;

    let mut raw_batch: Vec<String> = Vec::with_capacity(args.batch_size);
    let mut total_processed: usize = 0;
    let mut batch_index: usize = 0;

    // Lecture par flux asynchrone ligne par ligne
    while let Some(line) = reader.next_line().await.context("Erreur lors de la lecture du flux JSON")? {
        raw_batch.push(line);

        if raw_batch.len() >= args.batch_size {
            let current_batch = std::mem::replace(&mut raw_batch, Vec::with_capacity(args.batch_size));
            batch_index += 1;

            debug!(batch = batch_index, size = current_batch.len(), "Traitement du lot");

            // Exécution du parsing et du hachage multithreadé sans bloquer le runtime Tokio
            let processed_entries = tokio::task::spawn_blocking(move || {
                process_batch_multithreaded(current_batch)
            })
            .await
            .context("Erreur de jointure de tâche de hachage multithreadé")?;

            let count = processed_entries.len();
            if !processed_entries.is_empty() {
                let record_batch = build_record_batch(&schema, &processed_entries)?;
                writer.write(&record_batch).context("Erreur lors de l'écriture du RecordBatch dans Parquet")?;
                total_processed += count;
            }
        }
    }

    // Traitement du dernier lot restant
    if !raw_batch.is_empty() {
        batch_index += 1;
        debug!(batch = batch_index, size = raw_batch.len(), "Traitement du dernier lot");

        let processed_entries = tokio::task::spawn_blocking(move || {
            process_batch_multithreaded(raw_batch)
        })
        .await
        .context("Erreur de jointure de tâche de hachage final")?;

        let count = processed_entries.len();
        if !processed_entries.is_empty() {
            let record_batch = build_record_batch(&schema, &processed_entries)?;
            writer.write(&record_batch).context("Erreur lors de l'écriture du dernier RecordBatch")?;
            total_processed += count;
        }
    }

    // Clôture du fichier Parquet (écriture des métadonnées de bas de page)
    writer.close().context("Erreur lors de la finalisation du fichier Parquet")?;

    info!(
        total_logs = total_processed,
        batches = batch_index,
        output = %args.output.display(),
        "Export Parquet terminé avec succès"
    );

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;

    #[test]
    fn test_raw_log_entry_hashing() {
        let json_line = r#"{"timestamp":"2026-09-27T10:00:00Z","level":"INFO","service":"auth","message":"Login ok"}"#;
        let raw: RawLogEntry = serde_json::from_str(json_line).expect("JSON parsing should succeed");
        let processed = raw.into_processed(json_line);

        assert_eq!(processed.level, "INFO");
        assert_eq!(processed.service, "auth");
        assert_eq!(processed.message, "Login ok");
        assert_eq!(processed.timestamp, "2026-09-27T10:00:00Z");

        // Verify SHA-256 manually
        let mut hasher = Sha256::new();
        hasher.update(json_line.as_bytes());
        let expected_hash = hex::encode(hasher.finalize());
        assert_eq!(processed.sha256_hash, expected_hash);
    }

    #[test]
    fn test_process_batch_multithreaded() {
        let lines = vec![
            r#"{"timestamp":"2026-09-27T10:00:00Z","level":"INFO","service":"web","message":"req 1"}"#.to_string(),
            "".to_string(), // empty line
            r#"{"level":"ERROR","message":"something failed"}"#.to_string(),
            "INVALID_JSON_LINE".to_string(),
        ];

        let results = process_batch_multithreaded(lines);
        assert_eq!(results.len(), 2);
        assert_eq!(results[0].service, "web");
        assert_eq!(results[1].level, "ERROR");
        assert_eq!(results[1].service, "default"); // fallback
    }

    #[test]
    fn test_arrow_record_batch_and_parquet_roundtrip() -> Result<()> {
        let entries = vec![
            ProcessedLogEntry {
                timestamp: "2026-09-27T12:00:00Z".to_string(),
                level: "INFO".to_string(),
                service: "test-service".to_string(),
                message: "test message".to_string(),
                metadata: Some(r#"{"env":"staging"}"#.to_string()),
                sha256_hash: "abcdef0123456789".to_string(),
            },
        ];

        let schema = build_arrow_schema();
        let record_batch = build_record_batch(&schema, &entries)?;
        assert_eq!(record_batch.num_rows(), 1);
        assert_eq!(record_batch.num_columns(), 6);

        // In-memory parquet write
        let mut buffer = Vec::new();
        let props = WriterProperties::builder().build();
        let mut writer = ArrowWriter::try_new(&mut buffer, schema.clone(), Some(props))?;
        writer.write(&record_batch)?;
        writer.close()?;

        // Read back
        let cursor = bytes::Bytes::from(buffer);
        let builder = ParquetRecordBatchReaderBuilder::try_new(cursor)?;
        let mut reader = builder.build()?;
        let read_batch = reader.next().expect("Batch should exist")?;

        assert_eq!(read_batch.num_rows(), 1);
        assert_eq!(read_batch.num_columns(), 6);
        Ok(())
    }
}


