        #[arg(short, long, value_enum, default_value_t = CompressionCodec::Zstd)]
        compression: CompressionCodec,

        /// Capacité du tampon en mémoire avant flush automatique
        #[arg(short, long, default_value_t = 1_000)]
        buffer_size: usize,

