pub fn get_arrow_schema() -> Arc<Schema> {
    Arc::new(Schema::new(vec![
        Field::new(
            "timestamp",
            DataType::Timestamp(TimeUnit::Millisecond, Some("UTC".into())),
            false,
        ),
        Field::new("level", DataType::Utf8, false),
        Field::new("target", DataType::Utf8, false),
        Field::new("message", DataType::Utf8, false),
        Field::new("fields", DataType::Utf8, true),
    ]))
}

pub fn logs_to_record_batch(
    schema: &Arc<Schema>,
    logs: &[LogEntry],
) -> Result<RecordBatch, AppError> {
    let mut timestamps = TimestampMillisecondArray::builder(logs.len());
    let mut levels = StringBuilder::with_capacity(logs.len(), logs.len() * 8);
    let mut targets = StringBuilder::with_capacity(logs.len(), logs.len() * 16);
    let mut messages = StringBuilder::with_capacity(logs.len(), logs.len() * 64);
    let mut fields = StringBuilder::with_capacity(logs.len(), logs.len() * 64);

    for log in logs {
        timestamps.append_value(log.timestamp.timestamp_millis());
        levels.append_value(&log.level);
        targets.append_value(&log.target);
        messages.append_value(&log.message);

        match &log.fields {
            Some(value) => {
                let serialized = serde_json::to_string(value)?;
                fields.append_value(&serialized);
            }
            None => {
                fields.append_null();
            }
        }
    }

    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![
            Arc::new(timestamps.finish().with_timezone("UTC")),
            Arc::new(levels.finish()),
            Arc::new(targets.finish()),
            Arc::new(messages.finish()),
            Arc::new(fields.finish()),
        ],
    )?;

    Ok(batch)
}

pub async fn create_parquet_writer(
    path: &Path,
    schema: Arc<Schema>,
    codec: CompressionCodec,
) -> Result<AsyncArrowWriter<File>, AppError> {
    if let Some(parent) = path.parent() {
        if !parent.as_os_str().is_empty() {
            tokio::fs::create_dir_all(parent).await?;
        }
    }

    let file = OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .open(path)
        .await?;

    let props = WriterProperties::builder()
        .set_compression(codec.into())
        .build();

    let writer = AsyncArrowWriter::try_new(file, schema, Some(props))?;
    Ok(writer)
}

pub async fn parse_line_or_array(line: &str) -> Result<Vec<LogEntry>, AppError> {
    let trimmed = line.trim();
    if trimmed.is_empty() {
        return Ok(Vec::new());
    }

    if trimmed.starts_with('[') {
        let entries: Vec<LogEntry> = serde_json::from_str(trimmed)?;
        Ok(entries)
    } else {
        let entry: LogEntry = serde_json::from_str(trimmed)?;
        Ok(vec![entry])
    }
}

async fn handle_convert(
    input: PathBuf,
    output: PathBuf,
    compression: CompressionCodec,
    batch_size: usize,
) -> Result<(), AppError> {
    info!(
        "Début de conversion : {:?} -> {:?} (compression: {:?}, batch_size: {})",
        input, output, compression, batch_size
    );

    let file = File::open(&input).await?;
    let reader = BufReader::new(file);
    let mut lines = reader.lines();

    let schema = get_arrow_schema();
    let mut writer = create_parquet_writer(&output, schema.clone(), compression).await?;

    let mut buffer: Vec<LogEntry> = Vec::with_capacity(batch_size);
    let mut total_records: u64 = 0;

    while let Some(line) = lines.next_line().await? {
        match parse_line_or_array(&line).await {
            Ok(entries) => {
                for entry in entries {
                    buffer.push(entry);
                    if buffer.len() >= batch_size {
                        let batch = logs_to_record_batch(&schema, &buffer)?;
                        writer.write(&batch).await?;
                        total_records += buffer.len() as u64;
                        buffer.clear();
                    }
                }
            }
            Err(err) => {
                warn!("Ligne ignorée (erreur de parsing JSON): {}", err);
            }
        }
    }

    if !buffer.is_empty() {
        let batch = logs_to_record_batch(&schema, &buffer)?;
        writer.write(&batch).await?;
        total_records += buffer.len() as u64;
        buffer.clear();
    }

    writer.close().await?;
    info!(
        "Conversion terminée avec succès : {} enregistrements écrits dans {:?}",
        total_records, output
    );
    Ok(())
}

async fn handle_stream(
    output: PathBuf,
    compression: CompressionCodec,
    batch_size: usize,
) -> Result<(), AppError> {
    info!(
        "Écoute du flux stdin -> {:?} (compression: {:?}, batch_size: {})",
        output, compression, batch_size
    );

    let stdin = tokio::io::stdin();
    let reader = BufReader::new(stdin);
    let mut lines = reader.lines();

    let schema = get_arrow_schema();
    let mut writer = create_parquet_writer(&output, schema.clone(), compression).await?;

    let mut buffer: Vec<LogEntry> = Vec::with_capacity(batch_size);
    let mut total_records: u64 = 0;

    while let Some(line) = lines.next_line().await? {
        match parse_line_or_array(&line).await {
            Ok(entries) => {
                for entry in entries {
                    buffer.push(entry);
                    if buffer.len() >= batch_size {
                        let batch = logs_to_record_batch(&schema, &buffer)?;
                        writer.write(&batch).await?;
                        total_records += buffer.len() as u64;
                        buffer.clear();
                    }
                }
            }
            Err(err) => {
                warn!("Format invalide dans le flux: {}", err);
            }
        }
    }

    if !buffer.is_empty() {
        let batch = logs_to_record_batch(&schema, &buffer)?;
        writer.write(&batch).await?;
        total_records += buffer.len() as u64;
        buffer.clear();
    }

    writer.close().await?;
    info!(
        "Flux terminé : {} enregistrements sauvegardés dans {:?}",
        total_records, output
    );
    Ok(())
}

#[derive(Clone)]
struct AppState {
    writer: Arc<Mutex<Option<AsyncArrowWriter<File>>>>,
    schema: Arc<Schema>,
    buffer: Arc<Mutex<Vec<LogEntry>>>,
    buffer_capacity: usize,
    received_count: Arc<AtomicU64>,
    persisted_count: Arc<AtomicU64>,
}

#[derive(Serialize)]
struct MetricsResponse {
    received_logs: u64,
    persisted_logs: u64,
    buffered_logs: usize,
    status: &'static str,
}

#[derive(Deserialize)]
#[serde(untagged)]
enum IngestPayload {
    Single(LogEntry),
    Batch(Vec<LogEntry>),
}

async fn health_handler() -> &'static str {
    "OK"
}

async fn metrics_handler(State(state): State<AppState>) -> Json<MetricsResponse> {
    let buffered = state.buffer.lock().await.len();
    Json(MetricsResponse {
        received_logs: state.received_count.load(Ordering::Relaxed),
        persisted_logs: state.persisted_count.load(Ordering::Relaxed),
        buffered_logs: buffered,
        status: "running",
    })
}

async fn flush_internal(state: &AppState) -> Result<usize, AppError> {
    let mut buffer = state.buffer.lock().await;
    if buffer.is_empty() {
        return Ok(0);
    }

    let batch = logs_to_record_batch(&state.schema, &buffer)?;
    let count = buffer.len();

    let mut writer_guard = state.writer.lock().await;
    if let Some(writer) = writer_guard.as_mut() {
        writer.write(&batch).await?;
        state.persisted_count.fetch_add(count as u64, Ordering::Relaxed);
        buffer.clear();
        Ok(count)
    } else {
        Err(AppError::Execution("Le writer Parquet n'est pas initialisé ou est déjà fermé".into()))
    }
}

async fn flush_handler(State(state): State<AppState>) -> Result<Json<serde_json::Value>, AppError> {
    let flushed = flush_internal(&state).await?;
    info!("Flush forcé exécuté : {} logs persistés", flushed);
    Ok(Json(serde_json::json!({
        "status": "flushed",
        "flushed_count": flushed
    })))
}

async fn ingest_handler(
    State(state): State<AppState>,
    Json(payload): Json<IngestPayload>,
) -> Result<(StatusCode, Json<serde_json::Value>), AppError> {
    let entries = match payload {
        IngestPayload::Single(entry) => vec![entry],
        IngestPayload::Batch(entries) => entries,
    };

    let count = entries.len();
    state.received_count.fetch_add(count as u64, Ordering::Relaxed);

    let should_flush = {
        let mut buffer = state.buffer.lock().await;
        buffer.extend(entries);
        buffer.len() >= state.buffer_capacity
    };

    if should_flush {
        flush_internal(&state).await?;
    }

    Ok((
        StatusCode::ACCEPTED,
        Json(serde_json::json!({
            "status": "accepted",
            "ingested_count": count
        })),
    ))
}

async fn handle_serve(
    addr: SocketAddr,
    output: PathBuf,
    compression: CompressionCodec,
    buffer_size: usize,
    flush_interval_secs: u64,
) -> Result<(), AppError> {
    info!(
        "Démarrage du serveur axum sur http://{} (fichier Parquet: {:?}, compression: {:?})",
        addr, output, compression
    );

    let schema = get_arrow_schema();
    let writer = create_parquet_writer(&output, schema.clone(), compression).await?;

    let state = AppState {
        writer: Arc::new(Mutex::new(Some(writer))),
        schema: schema.clone(),
        buffer: Arc::new(Mutex::new(Vec::with_capacity(buffer_size))),
        buffer_capacity: buffer_size,
        received_count: Arc::new(AtomicU64::new(0)),
        persisted_count: Arc::new(AtomicU64::new(0)),
    };

    // Tâche d'arrière-plan pour le vidage périodique (timer)
    let ticker_state = state.clone();
    let flush_interval = Duration::from_secs(flush_interval_secs);
    let ticker_handle = tokio::spawn(async move {
        let mut interval = tokio::time::interval(flush_interval);
        loop {
            interval.tick().await;
            if let Err(err) = flush_internal(&ticker_state).await {
                error!("Erreur lors du flush périodique automatique: {}", err);
            }
        }
    });

    let app = Router::new()
        .route("/health", get(health_handler))
        .route("/metrics", get(metrics_handler))
        .route("/ingest", post(ingest_handler))
        .route("/flush", post(flush_handler))
        .with_state(state.clone());

    let listener = tokio::net::TcpListener::bind(addr).await?;
    info!("Serveur en écoute sur {}", addr);

    // Attente d'un signal d'arrêt (Ctrl+C)
    axum::serve(listener, app)
        .with_graceful_shutdown(async move {
            if let Err(err) = tokio::signal::ctrl_c().await {
                error!("Erreur d'écoute du signal d'interruption: {}", err);
            }
            info!("Signal d'arrêt reçu, fermeture du serveur...");
        })
        .await
        .map_err(|e| AppError::Execution(e.to_string()))?;

    // Arrêt de la tâche d'arrière-plan
    ticker_handle.abort();

    // Vidage final et clôture propre du fichier Parquet
    info!("Flush des derniers éléments en mémoire...");
    let _ = flush_internal(&state).await;

    let mut writer_guard = state.writer.lock().await;
    if let Some(writer) = writer_guard.take() {
        info!("Finalisation et fermeture du fichier Parquet...");
        writer.close().await?;
    }

    info!("Serveur éteint proprement.");
    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), AppError> {
    // Initialisation du logging tracing structuré
    tracing_subscriber::registry()
        .with(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "log2parquet=info,tower_http=info".into()),
        )
        .with(tracing_subscriber::fmt::layer())
        .init();

    let cli = Cli::parse();

    match cli.command {
        Commands::Convert {
            input,
            output,
            compression,
            batch_size,
        } => {
            handle_convert(input, output, compression, batch_size).await?;
        }
        Commands::Stream {
            output,
            compression,
            batch_size,
        } => {
            handle_stream(output, compression, batch_size).await?;
        }
        Commands::Serve {
            addr,
            output,
            compression,
            buffer_size,
            flush_interval_secs,
        } => {
            handle_serve(addr, output, compression, buffer_size, flush_interval_secs).await?;
        }
    }

    Ok(())
}

