#[derive(Subcommand, Debug)]
enum Commands {
    /// Convertit les logs JSON avec dump hexadécimal vers un fichier Parquet
    Convert {
        /// Fichier source de logs JSON Lines (ou JSON structuré)
        #[arg(short, long)]
