}

/// Analyse le dump hexadécimal et extrait métadonnées et contenu décodé
fn analyze_hex_payload(raw_hex_opt: &Option<String>) -> (Option<Vec<u8>>, bool, u64, bool, Option<String>, f64) {
    let raw_hex = match raw_hex_opt {
        Some(s) if !s.trim().is_empty() => s.trim(),
        _ => return (None, false, 0, false, None, 0.0),
    };

    // Nettoyage des éventuels préfixes 0x ou séparateurs espaces
    let sanitized: String = raw_hex
        .chars()
        .filter(|c| c.is_ascii_hexdigit())
        .collect();

    if sanitized.is_empty() || sanitized.len() % 2 != 0 {
        return (None, false, 0, false, None, 0.0);
    }

    match hex::decode(&sanitized) {
        Ok(bytes) => {
            let byte_len = bytes.len() as u64;
            let entropy = calculate_entropy(&bytes);
            let (is_utf8, utf8_preview) = match std::str::from_utf8(&bytes) {
                Ok(s) => {
                    let printable = s.chars().all(|c| !c.is_control() || c == '\n' || c == '\t' || c == '\r');
                    (printable, Some(s.to_string()))
                }
                Err(_) => {
                    // Alternative: aperçu tronqué ASCII lisible
                    let preview: String = bytes
                        .iter()
                        .take(64)
                        .map(|&b| if (32..=126).contains(&b) { b as char } else { '.' })
                        .collect();
                    (false, Some(preview))
                }
            };
            (Some(bytes), true, byte_len, is_utf8, utf8_preview, entropy)
        }
        Err(_) => (None, false, 0, false, None, 0.0),
    }
}

/// Définit le schéma Arrow strict pour l'export Parquet
fn create_arrow_schema() -> Arc<Schema> {
    Arc::new(Schema::new(vec![
        Field::new("timestamp", DataType::Utf8, false),
        Field::new("level", DataType::Utf8, false),
        Field::new("source", DataType::Utf8, false),
        Field::new("message", DataType::Utf8, false),
        Field::new("raw_hex", DataType::Utf8, true),
        Field::new("payload_binary", DataType::Binary, true),
        Field::new("is_valid_hex", DataType::Boolean, false),
        Field::new("payload_len_bytes", DataType::UInt64, false),
        Field::new("is_utf8_printable", DataType::Boolean, false),
        Field::new("utf8_preview", DataType::Utf8, true),
        Field::new("entropy_scaled_int", DataType::Int64, false), // Entropy * 1000 pour typage déterministe
    ]))
}

/// Convertit un vecteur d'enregistrements en RecordBatch Arrow
fn build_record_batch(records: &[ParsedLogRecord], schema: Arc<Schema>) -> Result<RecordBatch> {
    let mut timestamps = Vec::with_capacity(records.len());
    let mut levels = Vec::with_capacity(records.len());
    let mut sources = Vec::with_capacity(records.len());
    let mut messages = Vec::with_capacity(records.len());
    let mut raw_hexes = Vec::with_capacity(records.len());
    let mut payload_binaries = Vec::with_capacity(records.len());
    let mut is_valid_hexes = Vec::with_capacity(records.len());
    let mut payload_lens = Vec::with_capacity(records.len());
    let mut is_utf8_printables = Vec::with_capacity(records.len());
    let mut utf8_previews = Vec::with_capacity(records.len());
    let mut entropies = Vec::with_capacity(records.len());

    for r in records {
        timestamps.push(r.timestamp.as_str());
        levels.push(r.level.as_str());
        sources.push(r.source.as_str());
        messages.push(r.message.as_str());
        raw_hexes.push(r.raw_hex.as_deref());
        payload_binaries.push(r.decoded_bytes.as_deref());
        is_valid_hexes.push(r.is_valid_hex);
        payload_lens.push(r.byte_length);
        is_utf8_printables.push(r.is_utf8_printable);
        utf8_previews.push(r.utf8_preview.as_deref());
        entropies.push((r.entropy * 1000.0).round() as i64);
    }

    let columns: Vec<ArrayRef> = vec![
        Arc::new(StringArray::from(timestamps)),
        Arc::new(StringArray::from(levels)),
        Arc::new(StringArray::from(sources)),
        Arc::new(StringArray::from(messages)),
        Arc::new(StringArray::from(raw_hexes)),
        Arc::new(BinaryArray::from_opt_vec(payload_binaries)),
        Arc::new(BooleanArray::from(is_valid_hexes)),
        Arc::new(UInt64Array::from(payload_lens)),
        Arc::new(BooleanArray::from(is_utf8_printables)),
        Arc::new(StringArray::from(utf8_previews)),
        Arc::new(Int64Array::from(entropies)),
    ];

    RecordBatch::try_new(schema, columns).context("Échec de la génération du RecordBatch Arrow")
}

#[derive(Default, Clone)]
struct ProgressState {
    pub total_processed: usize,
    pub valid_hex_count: usize,
    pub total_bytes_hex: u64,
    pub status: String,
    pub is_done: bool,
}

fn draw_ui(terminal: &mut Terminal<CrosstermBackend<Stdout>>, state: &ProgressState) -> Result<()> {
    terminal.draw(|f| {
        let size = f.area();
        let chunks = Layout::default()
            .direction(Direction::Vertical)
            .margin(1)
            .constraints([
                Constraint::Length(3),
                Constraint::Length(3),
                Constraint::Min(6),
            ])
            .split(size);

        let title_p = Paragraph::new(Line::from(vec![
            Span::styled("LOG -> PARQUET CONVERTER (ASYNC + RATATUI)", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
        ]))
        .block(Block::default().borders(Borders::ALL).title("Pipeline Status"));
        f.render_widget(title_p, chunks[0]);

        let progress_ratio = if state.is_done { 1.0 } else { 0.5 };
        let gauge = Gauge::default()
            .block(Block::default().borders(Borders::ALL).title("Progression"))
            .gauge_style(Style::default().fg(if state.is_done { Color::Green } else { Color::Yellow }))
            .percent(if state.is_done { 100 } else { 50 })
            .label(if state.is_done { "Terminé" } else { "Traitement en cours..." });
        let _ = progress_ratio;
        f.render_widget(gauge, chunks[1]);

        let stats_lines = vec![
            Line::from(vec![
                Span::raw("Lignes analysées : "),
                Span::styled(format!("{}", state.total_processed), Style::default().fg(Color::Yellow)),
            ]),
            Line::from(vec![
                Span::raw("Payloads hex valides : "),
                Span::styled(format!("{}", state.valid_hex_count), Style::default().fg(Color::Green)),
            ]),
            Line::from(vec![
                Span::raw("Octets binaires décodés : "),
                Span::styled(format!("{} octets", state.total_bytes_hex), Style::default().fg(Color::Blue)),
            ]),
            Line::from(vec![
                Span::raw("Statut actuel : "),
                Span::styled(&state.status, Style::default().fg(Color::Magenta)),
            ]),
            Line::from(vec![
                Span::styled(
                    if state.is_done { "Appuyez sur 'q' ou 'Entrée' pour quitter." } else { "Traitement asynchrone en arrière-plan..." },
                    Style::default().fg(Color::DarkGray),
                ),
            ]),
        ];

        let stats_widget = Paragraph::new(stats_lines)
            .block(Block::default().borders(Borders::ALL).title("Métriques d'extraction"));
        f.render_widget(stats_widget, chunks[2]);
    })?;
    Ok(())
}

async fn run_conversion(
    input_path: &Path,
    output_path: &Path,
    enable_tui: bool,
    batch_size: usize,
) -> Result<()> {
    let file = tokio::fs::File::open(input_path)
        .await
        .with_context(|| format!("Impossible d'ouvrir le fichier d'entrée {:?}", input_path))?;
    let mut reader = BufReader::new(file).lines();

    let file_out = File::create(output_path)
        .with_context(|| format!("Impossible de créer le fichier Parquet {:?}", output_path))?;

    let schema = create_arrow_schema();
    let props = WriterProperties::builder()
        .set_compression(Compression::SNAPPY)
        .build();

    let mut writer = ArrowWriter::try_new(file_out, Arc::clone(&schema), Some(props))
        .context("Impossible d'initialiser le ArrowWriter Parquet")?;

    let mut state = ProgressState {
        status: "Démarrage du traitement...".to_string(),
        ..Default::default()
    };

    let mut terminal_opt = if enable_tui {
        enable_raw_mode()?;
        let mut stdout = std::io::stdout();
        execute!(stdout, EnterAlternateScreen)?;
        let backend = CrosstermBackend::new(stdout);
        let mut term = Terminal::new(backend)?;
        term.clear()?;
        Some(term)
    } else {
        None
    };

    let mut event_stream = EventStream::new();
    let mut record_buffer = Vec::with_capacity(batch_size);

    loop {
        tokio::select! {
            line_result = reader.next_line() => {
                match line_result {
                    Ok(Some(line)) => {
                        let line_str = line.trim();
                        if line_str.is_empty() {
                            continue;
                        }

                        let entry: Result<InputLogEntry, _> = serde_json::from_str(line_str);
                        match entry {
                            Ok(log) => {
                                let (decoded_bytes, is_valid_hex, byte_length, is_utf8_printable, utf8_preview, entropy) =
                                    analyze_hex_payload(&log.hex_payload);

                                if is_valid_hex {
                                    state.valid_hex_count += 1;
                                    state.total_bytes_hex += byte_length;
                                }
                                state.total_processed += 1;

                                let parsed = ParsedLogRecord {
                                    timestamp: log.timestamp,
                                    level: log.level,
                                    source: log.source,
                                    message: log.message,
                                    raw_hex: log.hex_payload,
                                    decoded_bytes,
                                    is_valid_hex,
                                    byte_length,
                                    is_utf8_printable,
                                    utf8_preview,
                                    entropy,
                                };

                                record_buffer.push(parsed);

                                if record_buffer.len() >= batch_size {
                                    let batch = build_record_batch(&record_buffer, Arc::clone(&schema))?;
                                    writer.write(&batch).context("Écriture du batch Parquet impossible")?;
                                    record_buffer.clear();
                                    state.status = format!("Écrit batch dans {:?}", output_path);
                                }
                            }
                            Err(e) => {
                                state.status = format!("Avertissement: ligne invalide ignorée ({})", e);
                            }
                        }
                    }
                    Ok(None) => {
                        // Fin de fichier atteinte
                        if !record_buffer.is_empty() {
                            let batch = build_record_batch(&record_buffer, Arc::clone(&schema))?;
                            writer.write(&batch).context("Écriture du dernier batch Parquet impossible")?;
                            record_buffer.clear();
                        }
                        writer.close().context("Fermeture du fichier Parquet impossible")?;
                        state.status = "Export Parquet achevé avec succès !".to_string();
                        state.is_done = true;
                        break;
                    }
                    Err(e) => {
                        return Err(anyhow::anyhow!("Erreur lors de la lecture asynchrone des lignes: {}", e));
                    }
                }
            }
            maybe_event = event_stream.next(), if enable_tui => {
                if let Some(Ok(Event::Key(key_event))) = maybe_event {
                    if key_event.code == KeyCode::Char('q') || key_event.code == KeyCode::Esc {
                        state.status = "Interrompu par l'utilisateur".to_string();
                        break;
                    }
                }
            }
            _ = tokio::time::sleep(Duration::from_millis(50)), if enable_tui => {
                if let Some(ref mut term) = terminal_opt {
                    draw_ui(term, &state)?;
                }
            }
        }
    }

    if let Some(ref mut term) = terminal_opt {
        draw_ui(term, &state)?;
        if state.is_done {
            while let Some(Ok(event)) = event_stream.next().await {
                if let Event::Key(key) = event {
                    if key.code == KeyCode::Char('q') || key.code == KeyCode::Enter || key.code == KeyCode::Esc {
                        break;
                    }
                }
            }
        }
        disable_raw_mode()?;
        execute!(term.backend_mut(), LeaveAlternateScreen)?;
        term.show_cursor()?;
    } else {
        println!("Traitement terminé avec succès !");
        println!("Total lignes traitées : {}", state.total_processed);
        println!("Payloads hex valides  : {}", state.valid_hex_count);
        println!("Volume binaire extrait: {} octets", state.total_bytes_hex);
        println!("Fichier généré        : {:?}", output_path);
    }

    Ok(())
}

fn inspect_hex_command(raw: &str) -> Result<()> {
    let sanitized: String = raw.chars().filter(|c| c.is_ascii_hexdigit()).collect();
    if sanitized.is_empty() {
        println!("Erreur: Aucun caractère hexadécimal valide trouvé.");
        return Ok(());
    }
    if sanitized.len() % 2 != 0 {
        println!("Erreur: Longueur hexadécimale impaire ({} caractères).", sanitized.len());
        return Ok(());
    }

    let bytes = hex::decode(&sanitized).context("Erreur de décodage hexadécimal")?;
    let entropy = calculate_entropy(&bytes);
    let (is_utf8, utf8_preview) = match std::str::from_utf8(&bytes) {
        Ok(s) => (true, s.to_string()),
        Err(_) => {
            let p: String = bytes
                .iter()
                .map(|&b| if (32..=126).contains(&b) { b as char } else { '.' })
                .collect();
            (false, p)
        }
    };

    println!("=== ANALYSE DU DUMP HEXADÉCIMAL ===");
    println!("Entrée brute        : {}", raw);
    println!("Hex normalisé       : {}", sanitized);
    println!("Taille décodée      : {} octets", bytes.len());
    println!("Entropie (Shannon)  : {:.4} bits/octet", entropy);
    println!("Est UTF-8 valide    : {}", is_utf8);
    println!("Aperçu textuel      : {}", utf8_preview);
    println!("------------------------------------");
    print!("Dump formaté        :\n");

    for (i, chunk) in bytes.chunks(16).enumerate() {
        let hex_part: Vec<String> = chunk.iter().map(|b| format!("{:02X}", b)).collect();
        let ascii_part: String = chunk
            .iter()
            .map(|&b| if (32..=126).contains(&b) { b as char } else { '.' })
            .collect();
        println!("{:08X}  {:48}  |{}|", i * 16, hex_part.join(" "), ascii_part);
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Convert {
            input,
            output,
            tui,
            batch_size,
        } => {
            run_conversion(&input, &output, tui, batch_size).await?;
        }
        Commands::InspectHex { raw } => {
            inspect_hex_command(&raw)?;
        }
    }

    Ok(())
}

