            let logs = parse_json_lines(&input).await?;
            if logs.is_empty() {
                warn!("Le fichier source ne contient aucun log valide.");
            }

            info!(count = logs.len(), "Logs JSON parsés avec succès");

            let transformed = transform_logs(logs, &template)?;
            info!(count = transformed.len(), "Logs transformés avec Tera");

            let batch = build_record_batch(&transformed)?;
            write_parquet_file(&batch, &output)?;

            info!(
                output_file = %output.display(),
                records = batch.num_rows(),
                "Exportation Parquet terminée avec succès"
            );
        }
        Commands::Sample { output, count } => {
            generate_sample(&output, count).await?;
            info!(
                output_file = %output.display(),
                count = count,
