// src/main.rs
use std::fs::File;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use anyhow::{Context, Result};
use arrow::array::{Int64Array, RecordBatch, StringArray};
use arrow::datatypes::{DataType, Field, Schema};
use clap::{Parser, Subcommand};
use parquet::arrow::ArrowWriter;
use parquet::file::properties::WriterProperties;
use serde::{Deserialize, Serialize};
use tera::{Context as TeraContext, Tera};
use thiserror::Error;
use tokio::fs as tokio_fs;
use tokio::io::{AsyncBufReadExt, BufReader};
use tracing::{info, warn};

/// Erreurs métier typées de traitement de logs
#[derive(Debug, Error)]
pub enum ProcessingError {
    #[error("Erreur de parsing de log à la ligne {line_number}: {source}")]
    JsonParsing {
        line_number: usize,
        #[source]
        source: serde_json::Error,
    },
    #[error("Erreur d'application du template Tera sur le log id '{id}': {source}")]
    TemplateRendering {
        id: String,
        #[source]
        source: tera::Error,
    },
    #[error("Erreur d'écriture du fichier Parquet: {0}")]
    ParquetWrite(#[from] parquet::errors::ParquetError),
    #[error("Erreur de manipulation du batch Arrow: {0}")]
    ArrowBatch(#[from] arrow::error::ArrowError),
}

/// Modèle d'entrée d'un log au format JSON
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct InputLog {
    pub id: String,
    pub timestamp: i64,
    pub level: String,
    pub service: String,
    pub message: String,
    #[serde(default)]
    pub details: Option<serde_json::Value>,
}

/// Modèle de log transformé après passage par le moteur de template
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TransformedLog {
    pub id: String,
    pub timestamp: i64,
    pub level: String,
    pub service: String,
    pub message: String,
    pub formatted_output: String,
}

/// CLI asynchrone de conversion et d'enrichissement de logs JSON vers Apache Parquet
#[derive(Parser, Debug)]
#[command(
    name = "log-to-parquet",
    author,
    version,
    about = "Parse des flux de logs JSON, les transforme via Tera et les exporte en Parquet",
    long_about = None
)]
pub struct Cli {
    #[command(subcommand)]
    pub command: Commands,
}

#[derive(Subcommand, Debug)]
pub enum Commands {
    /// Convertit un fichier JSON Lines vers un fichier Parquet en appliquant un template Tera
    Convert {
        /// Chemin du fichier d'entrée contenant des logs JSON (1 log par ligne)
        #[arg(short, long)]
        input: PathBuf,

        /// Chemin du fichier Parquet de destination
        #[arg(short, long)]
        output: PathBuf,

        /// Template Tera inline pour formater un champ de synthèse (optionnel)
        #[arg(
            short,
            long,
            default_value = "[{{ level | upper }}] {{ service }}: {{ message }}"
        )]
        template: String,
    },
    /// Génère un fichier d'exemple au format JSON Lines
    Sample {
        /// Chemin du fichier d'exemple à générer
        #[arg(short, long, default_value = "sample_logs.jsonl")]
        output: PathBuf,

        /// Nombre de logs à générer
        #[arg(short, long, default_value_t = 5)]
        count: usize,
    },
}

/// Lecture et parsing asynchrones des logs JSON ligne par ligne
pub async fn parse_json_lines(path: &Path) -> Result<Vec<InputLog>> {
    let file = tokio_fs::File::open(path)
        .await
        .with_context(|| format!("Impossible d'ouvrir le fichier source '{}'", path.display()))?;

    let reader = BufReader::new(file);
    let mut lines = reader.lines();
    let mut logs = Vec::new();
    let mut line_number = 0usize;

    while let Some(line) = lines.next_line().await.context("Erreur de lecture I/O de ligne")? {
        line_number += 1;
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }

        match serde_json::from_str::<InputLog>(trimmed) {
            Ok(log) => logs.push(log),
            Err(source) => {
                return Err(ProcessingError::JsonParsing {
                    line_number,
                    source,
                }
                .into());
            }
        }
    }

    Ok(logs)
}

/// Transformation et enrichissement via Tera
pub fn transform_logs(logs: Vec<InputLog>, template_str: &str) -> Result<Vec<TransformedLog>> {
    let mut tera = Tera::default();
    tera.add_raw_template("summary", template_str)
        .context("Syntaxe de template Tera invalide")?;

    let mut transformed = Vec::with_capacity(logs.len());

    for log in logs {
        let mut context = TeraContext::new();
        context.insert("id", &log.id);
        context.insert("timestamp", &log.timestamp);
        context.insert("level", &log.level);
        context.insert("service", &log.service);
        context.insert("message", &log.message);
        if let Some(details) = &log.details {
            context.insert("details", details);
        }

        let formatted_output = match tera.render("summary", &context) {
            Ok(rendered) => rendered,
            Err(source) => {
                return Err(ProcessingError::TemplateRendering {
                    id: log.id.clone(),
                    source,
                }
                .into());
            }
        };

        transformed.push(TransformedLog {
            id: log.id,
            timestamp: log.timestamp,
            level: log.level,
            service: log.service,
            message: log.message,
            formatted_output,
        });
    }

    Ok(transformed)
}

/// Convertit la liste de logs transformés en RecordBatch Apache Arrow
pub fn build_record_batch(logs: &[TransformedLog]) -> Result<RecordBatch> {
    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Utf8, false),
        Field::new("timestamp", DataType::Int64, false),
        Field::new("level", DataType::Utf8, false),
        Field::new("service", DataType::Utf8, false),
        Field::new("message", DataType::Utf8, false),
        Field::new("formatted_output", DataType::Utf8, false),
    ]));

    let ids: Vec<&str> = logs.iter().map(|l| l.id.as_str()).collect();
    let timestamps: Vec<i64> = logs.iter().map(|l| l.timestamp).collect();
    let levels: Vec<&str> = logs.iter().map(|l| l.level.as_str()).collect();
    let services: Vec<&str> = logs.iter().map(|l| l.service.as_str()).collect();
    let messages: Vec<&str> = logs.iter().map(|l| l.message.as_str()).collect();
    let formatted: Vec<&str> = logs.iter().map(|l| l.formatted_output.as_str()).collect();

    let batch = RecordBatch::try_new(
        schema,
        vec![
            Arc::new(StringArray::from(ids)),
            Arc::new(Int64Array::from(timestamps)),
            Arc::new(StringArray::from(levels)),
            Arc::new(StringArray::from(services)),
            Arc::new(StringArray::from(messages)),
            Arc::new(StringArray::from(formatted)),
        ],
    )
    .map_err(ProcessingError::ArrowBatch)?;

    Ok(batch)
}

/// Écriture du RecordBatch vers un fichier Apache Parquet
pub fn write_parquet_file(batch: &RecordBatch, destination: &Path) -> Result<()> {
    if let Some(parent) = destination.parent() {
        if !parent.as_os_str().is_empty() {
            std::fs::create_dir_all(parent).with_context(|| {
                format!(
                    "Impossible de créer les répertoires parents '{}'",
                    parent.display()
                )
            })?;
        }
    }

    let file = File::create(destination).with_context(|| {
        format!(
            "Impossible de créer le fichier de destination '{}'",
            destination.display()
        )
    })?;

    let props = WriterProperties::builder().build();
    let mut writer = ArrowWriter::try_new(file, batch.schema(), Some(props))
        .map_err(ProcessingError::ParquetWrite)?;

    writer.write(batch).map_err(ProcessingError::ParquetWrite)?;
    writer.close().map_err(ProcessingError::ParquetWrite)?;

    Ok(())
}

/// Génération d'un fichier d'exemple JSONL
pub async fn generate_sample(destination: &Path, count: usize) -> Result<()> {
    use tokio::io::AsyncWriteExt;

    let mut file = tokio_fs::File::create(destination).await.with_context(|| {
        format!(
            "Impossible d'initialiser le fichier d'exemple '{}'",
            destination.display()
        )
    })?;

    let levels = ["INFO", "WARN", "ERROR", "DEBUG"];
    let services = ["auth-service", "payment-gateway", "api-router", "worker-queue"];

    for i in 1..=count {
        let sample = InputLog {
            id: format!("log-{:05}", i),
            timestamp: 1717000000 + (i as i64 * 60),
            level: levels[i % levels.len()].to_string(),
            service: services[i % services.len()].to_string(),
            message: format!("Opération exécutée pour l'itération {}", i),
            details: Some(serde_json::json!({
                "iteration": i,
                "status_code": 200 + (i % 5) * 50
            })),
        };

        let serialized = serde_json::to_string(&sample).context("Erreur de sérialisation JSON")?;
        file.write_all(serialized.as_bytes())
            .await
            .context("Erreur d'écriture dans le fichier d'exemple")?;
        file.write_all(b"\n")
            .await
            .context("Erreur d'écriture du saut de ligne")?;
    }

    file.flush()
        .await
        .context("Erreur de synchronisation du fichier d'exemple")?;
    Ok(())
}

