async fn health_check(State(state): State<AppState>) -> Json<ApiResponse<HealthStatus>> {
    let buffered = state.logs.lock().await.len();
    Json(ApiResponse {
        success: true,
        message: "Service en ligne".into(),
        data: Some(HealthStatus {
            status: "healthy",
            buffered_logs: buffered,
            uptime_version: env!("CARGO_PKG_VERSION"),
        }),
    })
}

async fn ingest_logs(
    State(state): State<AppState>,
    Json(payload): Json<IngestPayload>,
) -> (StatusCode, Json<ApiResponse<IngestResult>>) {
    let transformed: Vec<TransformedLogEntry> = payload
        .logs
        .into_iter()
        .map(TransformedLogEntry::from_raw)
        .collect();

    let accepted = transformed.len();
    let mut buffer = state.logs.lock().await;
    buffer.extend(transformed);
    let total = buffer.len();

    (
        StatusCode::CREATED,
        Json(ApiResponse {
            success: true,
            message: format!("{} log(s) ingéré(s) avec succès", accepted),
            data: Some(IngestResult {
                accepted_count: accepted,
                total_in_memory: total,
            }),
        }),
    )
}

async fn export_to_parquet(
    State(state): State<AppState>,
    Json(request): Json<ExportRequest>,
) -> (StatusCode, Json<ApiResponse<ExportResult>>) {
    let records = {
        let buffer = state.logs.lock().await;
        buffer.clone()
    };

    if records.is_empty() {
        return (
            StatusCode::BAD_REQUEST,
            Json(ApiResponse {
                success: false,
                message: "Aucun log en mémoire à exporter".into(),
                data: None,
            }),
        );
    }

    let out_path = request
        .output_path
        .map(PathBuf::from)
        .unwrap_or_else(|| state.default_output.clone());

    let path_clone = out_path.clone();

    let write_res = tokio::task::spawn_blocking(move || write_parquet_file(&records, &path_clone))
        .await;

    match write_res {
        Ok(Ok(written)) => (
            StatusCode::OK,
            Json(ApiResponse {
                success: true,
                message: "Logs exportés avec succès au format Parquet".into(),
                data: Some(ExportResult {
                    exported_count: written,
                    output_file: out_path.to_string_lossy().into_owned(),
                }),
            }),
        ),
        Ok(Err(err)) => {
            error!(error = %err, "Erreur lors de l'écriture Parquet");
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(ApiResponse {
                    success: false,
                    message: format!("Erreur d'écriture Parquet : {err}"),
                    data: None,
                }),
            )
        }
        Err(join_err) => {
            error!(error = %join_err, "Erreur du task d'écriture");
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(ApiResponse {
                    success: false,
                    message: format!("Erreur interne : {join_err}"),
                    data: None,
                }),
            )
        }
    }
}

