// src/main.rs
use std::fs::File;
use std::net::SocketAddr;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use anyhow::{Context, Result};
use arrow::array::{
    ArrayRef, Int64Array, RecordBatch, StringArray, TimestampMillisecondArray,
};
use arrow::datatypes::{DataType, Field, Schema, TimeUnit};
use axum::{
    extract::State,
    http::StatusCode,
    response::{IntoResponse, Json},
    routing::{get, post},
    Router,
};
use chrono::{DateTime, Utc};
use clap::{Args, Parser, Subcommand};
use parquet::arrow::arrow_writer::ArrowWriter;
use parquet::file::properties::WriterProperties;
use serde::{Deserialize, Serialize};
use tokio::io::{AsyncBufReadExt, BufReader};
use tokio::sync::Mutex;
use tracing::{error, info, warn};

/// Modèle d'entrée représentant une ligne de log brute au format JSON.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RawLogEntry {
    pub id: Option<String>,
    pub timestamp: Option<String>,
    pub level: Option<String>,
    pub service: Option<String>,
    pub message: Option<String>,
    pub status_code: Option<i64>,
}

/// Modèle structuré et validé après transformation.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TransformedLogEntry {
    pub id: String,
    pub timestamp_ms: i64,
    pub level: String,
    pub service: String,
    pub message: String,
    pub status_code: i64,
}

impl TransformedLogEntry {
    /// Valide, normalise et transforme un log brut.
    pub fn from_raw(raw: RawLogEntry) -> Self {
        let id = raw
            .id
            .filter(|s| !s.trim().is_empty())
            .unwrap_or_else(|| uuid::Uuid::new_v4().to_string());

        let timestamp_ms = raw
            .timestamp
            .as_deref()
            .and_then(|ts| {
                DateTime::parse_from_rfc3339(ts)
                    .map(|dt| dt.with_timezone(&Utc).timestamp_millis())
                    .or_else(|_| ts.parse::<i64>())
                    .ok()
            })
            .unwrap_or_else(|| Utc::now().timestamp_millis());

        let level = raw
            .level
            .map(|lvl| lvl.to_uppercase())
            .filter(|lvl| !lvl.trim().is_empty())
            .unwrap_or_else(|| "INFO".to_string());

        let service = raw
            .service
            .filter(|s| !s.trim().is_empty())
            .unwrap_or_else(|| "unknown-service".to_string());

        let message = raw.message.unwrap_or_default();
        let status_code = raw.status_code.unwrap_or(0);

        Self {
            id,
            timestamp_ms,
            level,
            service,
            message,
            status_code,
        }
    }
}

