    #[arg(short, long, default_value = "logs_export.parquet")]
    pub default_output: PathBuf,
}

/// Définit le schéma Arrow partagé pour l'écriture Parquet
fn arrow_log_schema() -> Schema {
    Schema::new(vec![
        Field::new("id", DataType::Utf8, false),
        Field::new(
            "timestamp",
            DataType::Timestamp(TimeUnit::Millisecond, Some("UTC".into())),
            false,
        ),
        Field::new("level", DataType::Utf8, false),
        Field::new("service", DataType::Utf8, false),
        Field::new("message", DataType::Utf8, false),
        Field::new("status_code", DataType::Int64, false),
    ])
}

/// Écrit un slice de `TransformedLogEntry` dans un fichier Parquet en utilisant Arrow RecordBatches
pub fn write_parquet_file(records: &[TransformedLogEntry], output_path: &Path) -> Result<usize> {
    let ids: Vec<&str> = records.iter().map(|r| r.id.as_str()).collect();
    let timestamps: Vec<i64> = records.iter().map(|r| r.timestamp_ms).collect();
    let levels: Vec<&str> = records.iter().map(|r| r.level.as_str()).collect();
    let services: Vec<&str> = records.iter().map(|r| r.service.as_str()).collect();
    let messages: Vec<&str> = records.iter().map(|r| r.message.as_str()).collect();
    let status_codes: Vec<i64> = records.iter().map(|r| r.status_code).collect();

    let id_array = Arc::new(StringArray::from(ids)) as ArrayRef;
    let ts_array = Arc::new(TimestampMillisecondArray::from(timestamps).with_timezone("UTC")) as ArrayRef;
    let level_array = Arc::new(StringArray::from(levels)) as ArrayRef;
    let service_array = Arc::new(StringArray::from(services)) as ArrayRef;
    let message_array = Arc::new(StringArray::from(messages)) as ArrayRef;
    let status_array = Arc::new(Int64Array::from(status_codes)) as ArrayRef;

    let schema = Arc::new(arrow_log_schema());
    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![
            id_array,
            ts_array,
            level_array,
            service_array,
            message_array,
            status_array,
        ],
    )
    .context("Échec de création du RecordBatch Arrow")?;

    if let Some(parent) = output_path.parent() {
        if !parent.as_os_str().is_empty() {
            std::fs::create_dir_all(parent)
                .with_context(|| format!("Impossible de créer le répertoire {}", parent.display()))?;
        }
    }

    let file = File::create(output_path)
        .with_context(|| format!("Impossible de créer le fichier {}", output_path.display()))?;

    let props = WriterProperties::builder().build();
    let mut writer = ArrowWriter::try_new(file, schema, Some(props))
        .context("Échec d'initialisation de ArrowWriter Parquet")?;

    writer
        .write(&batch)
        .context("Échec de l'écriture du RecordBatch dans Parquet")?;

    writer
        .close()
        .context("Échec de la fermeture/finalisation du fichier Parquet")?;

    Ok(records.len())
}

/// Lit et convertit un fichier de logs JSON Lines de manière asynchrone
async fn process_convert_command(args: ConvertArgs) -> Result<()> {
    info!(
        input = %args.input.display(),
        output = %args.output.display(),
        "Démarrage de la conversion"
    );

    let file = tokio::fs::File::open(&args.input)
        .await
        .with_context(|| format!("Impossible d'ouvrir le fichier {}", args.input.display()))?;

    let reader = BufReader::new(file);
    let mut lines = reader.lines();
    let mut records = Vec::new();
    let mut line_number = 0usize;

    while let Some(line) = lines.next_line().await.context("Erreur de lecture de ligne")? {
        line_number += 1;
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }

        match serde_json::from_str::<RawLogEntry>(trimmed) {
            Ok(raw) => {
                records.push(TransformedLogEntry::from_raw(raw));
            }
            Err(err) => {
                warn!(
                    line = line_number,
                    error = %err,
                    "Ligne JSON invalide ignorée"
                );
            }
        }

        if let Some(limit) = args.limit {
            if records.len() >= limit {
                info!(limit = limit, "Limite atteinte, arrêt du parsing");
                break;
            }
        }
    }

    let total = records.len();
    info!(parsed_records = total, "Parsing terminé, début de l'écriture Parquet");

    let output_path = args.output.clone();
    tokio::task::spawn_blocking(move || write_parquet_file(&records, &output_path))
        .await
        .context("Échec d'exécution du thread d'écriture Parquet")??;

    info!(
        output = %args.output.display(),
        records_written = total,
        "Conversion terminée avec succès"
    );

    Ok(())
}

