// src/main.rs
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use anyhow::{bail, Context, Result};
use chrono::{DateTime, Utc};
use clap::{Args, Parser, Subcommand, ValueEnum};
use hex;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use tokio::fs;
use tokio::io::{self, AsyncReadExt, AsyncWriteExt};

/// Niveau de criticité pour les enregistrements
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, ValueEnum)]
#[serde(rename_all = "snake_case")]
pub enum SeverityLevel {
    Info,
    Warning,
    Critical,
}

/// Métadonnées détaillées associées à un jeu de données
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct DatasetMetadata {
    pub author: String,
    pub created_at: DateTime<Utc>,
    pub tags: Vec<String>,
    pub attributes: BTreeMap<String, String>,
}

/// Enregistrement unitaire d'un événement ou d'une métrique
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct TelemetryRecord {
    pub record_id: u64,
    pub source: String,
    pub severity: SeverityLevel,
    pub metrics: BTreeMap<String, f64>,
    pub payload: serde_json::Value,
}

/// Corps des données sans le condensat d'intégrité
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct DatasetPayload {
    pub dataset_id: String,
    pub title: String,
    pub metadata: DatasetMetadata,
    pub records: Vec<TelemetryRecord>,
}

/// Enveloppe sécurisée contenant le jeu de données et son empreinte cryptographique SHA-256
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct SignedDatasetEnvelope {
    pub payload: DatasetPayload,
    pub algorithm: String,
    pub sha256_hex: String,
}

impl SignedDatasetEnvelope {
    /// Construit l'enveloppe signée en calculant de façon déterministe l'empreinte SHA-256 en hexadécimal
    pub fn new(payload: DatasetPayload) -> Result<Self> {
        let canonical_bytes = serde_json::to_vec(&payload)
            .context("Échec de la sérialisation canonique du payload pour le hachage")?;

        let hash_digest = Sha256::digest(&canonical_bytes);
        let sha256_hex = hex::encode(hash_digest);

        Ok(Self {
            payload,
            algorithm: "SHA-256".to_string(),
            sha256_hex,
        })
    }

    /// Vérifie la cohérence du condensat stocké par rapport au payload contenu
    pub fn verify_integrity(&self) -> Result<()> {
        let canonical_bytes = serde_json::to_vec(&self.payload)
            .context("Échec de sérialisation du payload lors de la vérification d'intégrité")?;

        let expected_digest = Sha256::digest(&canonical_bytes);
        let expected_hex = hex::encode(expected_digest);

        if self.sha256_hex.eq_ignore_ascii_case(&expected_hex) {
            Ok(())
        } else {
            bail!(
                "Altération des données détectée ! Condensat attendu : {}, condensat actuel : {}",
                expected_hex,
                self.sha256_hex
            );
        }
    }
}

/// CLI asynchrone pour la génération, sérialisation et vérification d'intégrité de structures JSON
#[derive(Parser, Debug)]
#[command(
    name = "dystil-async-cli",
    version,
    about = "Outil en ligne de commande asynchrone pour la sérialisation serde_json et le contrôle d'intégrité SHA-256",
    long_about = None
)]
pub struct Cli {
    #[command(subcommand)]
    pub command: Commands,
}

#[derive(Subcommand, Debug)]
pub enum Commands {
    /// Génère une structure de données complexe, calcule son empreinte SHA-256 et la sérialise
    Generate(GenerateArgs),
    /// Calcule l'empreinte SHA-256 hexadécimale d'un fichier JSON ou de l'entrée standard
    Hash(HashArgs),
    /// Vérifie l'intégrité d'une enveloppe JSON sérialisée
    Verify(VerifyArgs),
}

#[derive(Args, Debug)]
pub struct GenerateArgs {
    /// Titre du jeu de données
    #[arg(short, long, default_value = "Jeu de télémétrie asynchrone")]
    pub title: String,

    /// Auteur associé aux métadonnées
    #[arg(short, long, default_value = "agent@dystil.local")]
    pub author: String,

    /// Nombre d'enregistrements complexes à générer
    #[arg(short = 'n', long, default_value_t = 3)]
    pub count: usize,

    /// Étiquettes associées (séparées par une virgule)
    #[arg(long, value_delimiter = ',', default_value = "tokio,clap,serde")]
    pub tags: Vec<String>,

    /// Niveau de sévérité par défaut pour les enregistrements
    #[arg(long, value_enum, default_value_t = SeverityLevel::Info)]
    pub severity: SeverityLevel,

    /// Active le formatage JSON indenté (pretty-print)
    #[arg(short, long)]
    pub pretty: bool,

    /// Fichier de sortie optionnel (par défaut : sortie standard)
    #[arg(short, long)]
    pub output: Option<PathBuf>,
}

#[derive(Args, Debug)]
pub struct HashArgs {
    /// Chemin du fichier à hacher (si absent, lit depuis stdin)
    #[arg(short, long)]
    pub file: Option<PathBuf>,
}

#[derive(Args, Debug)]
pub struct VerifyArgs {
    /// Fichier contenant le jeu de données JSON enveloppé à vérifier
    #[arg(short, long)]
    pub file: PathBuf,
}

/// Écrit de façon asynchrone les octets fournis vers un fichier ou la sortie standard
async fn write_output(bytes: &[u8], output: Option<&Path>) -> Result<()> {
    match output {
        Some(path) => {
            if let Some(parent) = path.parent() {
                if !parent.as_os_str().is_empty() {
                    fs::create_dir_all(parent).await.with_context(|| {
                        format!(
                            "Impossible de créer le répertoire parent : {}",
                            parent.display()
                        )
                    })?;
                }
            }
            fs::write(path, bytes)
                .await
                .with_context(|| format!("Échec de l'écriture dans le fichier {}", path.display()))?;
        }
        None => {
            let mut stdout = io::stdout();
            stdout
                .write_all(bytes)
                .await
                .context("Erreur lors de l'écriture sur stdout")?;
            stdout
                .flush()
                .await
                .context("Erreur lors du flush de stdout")?;
            // Ajoute un retour chariot terminal si non présent
            if !bytes.ends_with(b"\n") {
                stdout.write_all(b"\n").await.context("Erreur d'écriture newline")?;
                stdout.flush().await.context("Erreur flush newline")?;
            }
        }
    }
    Ok(())
}

/// Lit de façon asynchrone le contenu d'un fichier ou de stdin
async fn read_input(file: Option<&Path>) -> Result<Vec<u8>> {
    match file {
        Some(path) => fs::read(path)
            .await
            .with_context(|| format!("Impossible de lire le fichier {}", path.display())),
        None => {
            let mut stdin = io::stdin();
            let mut buffer = Vec::new();
            stdin
                .read_to_end(&mut buffer)
                .await
                .context("Échec de la lecture depuis stdin")?;
            Ok(buffer)
        }
    }
}

/// Exécute la sous-commande `generate`
async fn handle_generate(args: GenerateArgs) -> Result<()> {
    let now = Utc::now();
    let mut attributes = BTreeMap::new();
    attributes.insert("runtime".to_string(), "tokio-async".to_string());
    attributes.insert("serializer".to_string(), "serde_json".to_string());
    attributes.insert("integrity_provider".to_string(), "sha2+hex".to_string());

    let mut records = Vec::with_capacity(args.count);
    for idx in 0..args.count {
        let mut metrics = BTreeMap::new();
        metrics.insert("cpu_usage_pct".to_string(), 12.5 * (idx as f64 + 1.0));
        metrics.insert("memory_mb".to_string(), 256.0 * (idx as f64 + 1.0));

        let payload_json = serde_json::json!({
            "sequence": idx,
            "status": "active",
            "flags": ["initialized", "async_ready"]
        });

        records.push(TelemetryRecord {
            record_id: (idx as u64) + 1000,
            source: format!("node-{:03}", idx + 1),
            severity: args.severity.clone(),
            metrics,
            payload: payload_json,
        });
    }

    let payload = DatasetPayload {
        dataset_id: format!("ds-{}", now.timestamp_millis()),
        title: args.title,
        metadata: DatasetMetadata {
            author: args.author,
            created_at: now,
            tags: args.tags,
            attributes,
        },
        records,
    };

    let envelope = SignedDatasetEnvelope::new(payload)
        .context("Échec lors de la création de l'enveloppe signée")?;

    let serialized_bytes = if args.pretty {
        serde_json::to_vec_pretty(&envelope)
            .context("Erreur lors de la sérialisation JSON indentée (pretty)")?
    } else {
        serde_json::to_vec(&envelope).context("Erreur lors de la sérialisation JSON compacte")?
    };

    write_output(&serialized_bytes, args.output.as_deref()).await?;

    if let Some(path) = &args.output {
        eprintln!(
            "Succès : Jeu de données généré dans {} avec l'empreinte SHA-256 : {}",
            path.display(),
            envelope.sha256_hex
        );
    }

    Ok(())
}

/// Exécute la sous-commande `hash`
async fn handle_hash(args: HashArgs) -> Result<()> {
    let input_bytes = read_input(args.file.as_deref()).await?;
    let digest = Sha256::digest(&input_bytes);
    let hex_hash = hex::encode(digest);

    let output_msg = format!("{}\n", hex_hash);
    let mut stdout = io::stdout();
    stdout
        .write_all(output_msg.as_bytes())
        .await
        .context("Échec d'écriture du hachage sur stdout")?;
    stdout.flush().await.context("Échec du flush de stdout")?;

    Ok(())
}

/// Exécute la sous-commande `verify`
async fn handle_verify(args: VerifyArgs) -> Result<()> {
    let data = fs::read(&args.file)
        .await
        .with_context(|| format!("Impossible de charger le fichier {}", args.file.display()))?;

    let envelope: SignedDatasetEnvelope = serde_json::from_slice(&data).with_context(|| {
        format!(
            "Le fichier {} ne correspond pas au format attendu de SignedDatasetEnvelope",
            args.file.display()
        )
    })?;

    envelope
        .verify_integrity()
        .with_context(|| format!("Échec de vérification pour {}", args.file.display()))?;

    eprintln!(
        "Intégrité VALIDÉE avec succès pour {} (SHA-256 : {})",
        args.file.display(),
        envelope.sha256_hex
    );

    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Generate(args) => handle_generate(args).await,
        Commands::Hash(args) => handle_hash(args).await,
        Commands::Verify(args) => handle_verify(args).await,
    }
}

