        let envelope = SignedDatasetEnvelope::new(payload).expect("Création de l'enveloppe");
        assert_eq!(envelope.algorithm, "SHA-256");
        assert_eq!(envelope.sha256_hex.len(), 64);
        assert!(envelope.verify_integrity().is_ok());
    }

