        let payload = DatasetPayload {
            dataset_id: "ds-tamper".to_string(),
            title: "Tamper Test".to_string(),
            metadata: DatasetMetadata {
                author: "tester".to_string(),
                created_at: Utc::now(),
                tags: vec![],
                attributes: BTreeMap::new(),
            },
            records: vec![],
        };

        let mut envelope = SignedDatasetEnvelope::new(payload).expect("Création de l'enveloppe");
        // Altération d'un champ
        envelope.payload.title = "Altéré".to_string();

        let verification_result = envelope.verify_integrity();
        assert!(verification_result.is_err());
        assert!(verification_result
            .unwrap_err()
            .to_string()
            .contains("Altération des données détectée"));
    }

