        let parsed_hash = Cli::try_parse_from(["dystil-async-cli", "hash", "--file", "data.json"]);
        assert!(parsed_hash.is_ok());

        let parsed_verify = Cli::try_parse_from(["dystil-async-cli", "verify", "--file", "data.json"]);
        assert!(parsed_verify.is_ok());
    }
}


