    if let Some(path) = &args.output {
        eprintln!(
            "Succès : Jeu de données généré dans {} avec l'empreinte SHA-256 : {}",
            path.display(),
            envelope.sha256_hex
        );
    }

    Ok(())
}

/// Exécute la sous-commande `hash`
async fn handle_hash(args: HashArgs) -> Result<()> {
    let input_bytes = read_input(args.file.as_deref()).await?;
    let digest = Sha256::digest(&input_bytes);
    let hex_hash = hex::encode(digest);

    let output_msg = format!("{}\n", hex_hash);
    let mut stdout = io::stdout();
    stdout
        .write_all(output_msg.as_bytes())
        .await
        .context("Échec d'écriture du hachage sur stdout")?;
    stdout.flush().await.context("Échec du flush de stdout")?;

    Ok(())
}

/// Exécute la sous-commande `verify`
async fn handle_verify(args: VerifyArgs) -> Result<()> {
    let data = fs::read(&args.file)
        .await
        .with_context(|| format!("Impossible de charger le fichier {}", args.file.display()))?;

    let envelope: SignedDatasetEnvelope = serde_json::from_slice(&data).with_context(|| {
        format!(
            "Le fichier {} ne correspond pas au format attendu de SignedDatasetEnvelope",
            args.file.display()
        )
    })?;

    envelope
        .verify_integrity()
        .with_context(|| format!("Échec de vérification pour {}", args.file.display()))?;

    eprintln!(
        "Intégrité VALIDÉE avec succès pour {} (SHA-256 : {})",
        args.file.display(),
        envelope.sha256_hex
    );

    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Generate(args) => handle_generate(args).await,
        Commands::Hash(args) => handle_hash(args).await,
        Commands::Verify(args) => handle_verify(args).await,
    }
}

