#[derive(Parser, Debug)]
#[command(name = "async-json-cli")]
#[command(author = "Damien")]
#[command(version = "0.1.0")]
#[command(about = "CLI asynchrone pour la manipulation et la sérialisation de structures complexes")]
pub struct Cli {
