async fn handle_generate(args: GenerateArgs) -> Result<(), Box<dyn std::error::Error>> {
    let sample = ComplexRecord::sample();

    let serialized = match args.format {
        OutputFormat::Json => serde_json::to_string(&sample)?,
        OutputFormat::PrettyJson => serde_json::to_string_pretty(&sample)?,
    };

    if let Some(path) = args.output {
        tokio::fs::write(&path, &serialized).await?;
        println!("Fichier écrit avec succès dans {}", path.display());
    } else {
        println!("{}", serialized);
