    println!("Nombre d'événements: {}", record.events.len());
    println!("Nombre de métriques: {}", record.metadata.metrics.len());

    Ok(())
}

async fn handle_pipeline(args: PipelineArgs) -> Result<(), Box<dyn std::error::Error>> {
    println!(
        "Démarrage du pipeline asynchrone (tokio::sync::mpsc) avec {} éléments...",
        args.count
    );

    // Canal mpsc borné pour le flux de traitement
    let (tx, mut rx) = mpsc::channel::<ComplexRecord>(10);

    // Tâche productrice asynchrone
    let producer = tokio::spawn(async move {
        for i in 1..=args.count {
            let mut record = ComplexRecord::sample();
            record.title = format!("Tâche de flux #{}", i);
            if let Err(e) = tx.send(record).await {
                eprintln!("Erreur lors de l'envoi de la tâche: {}", e);
                break;
            }
            tokio::time::sleep(tokio::time::Duration::from_millis(100)).await;
        }
    });

    // Tâche consommatrice asynchrone sérialisant les données à la réception
    let consumer = tokio::spawn(async move {
        let mut processed = 0;
        while let Some(record) = rx.recv().await {
            match serde_json::to_string(&record) {
                Ok(json) => {
                    println!(
                        "[Consommateur] Traité & sérialisé id={} (taille JSON: {} octets)",
                        record.id,
                        json.len()
                    );
                }
                Err(err) => eprintln!("Erreur de sérialisation: {}", err),
            }
            processed += 1;
        }
        processed
    });

    let (_, processed) = tokio::join!(producer, consumer);
    let count = processed.unwrap_or(0);
    println!("Pipeline terminé avec succès. Total traités: {}", count);

    Ok(())
}

async fn handle_serve(args: ServeArgs) -> Result<(), Box<dyn std::error::Error>> {
    let (tx, _) = broadcast::channel(100);
    let state = AppState {
        store: Arc::new(RwLock::new(HashMap::new())),
        event_sender: tx,
    };

    // Pré-remplissage du store avec un enregistrement de démonstration
    {
        let mut store = state.store.write().await;
        let sample = ComplexRecord::sample();
        store.insert(sample.id, sample);
    }

    let app = Router::new()
        .route("/health", get(health_check))
        .route("/records", get(list_records).post(create_record))
        .route("/records/:id", get(get_record))
        .with_state(state);

    let addr: SocketAddr = format!("{}:{}", args.host, args.port).parse()?;
    println!("Serveur Axum en écoute sur http://{}", addr);
    println!("Routes disponibles :");
    println!("  GET  /health");
    println!("  GET  /records");
    println!("  POST /records");
    println!("  GET  /records/:id");

    let listener = tokio::net::TcpListener::bind(addr).await?;
    axum::serve(listener, app).await?;

    Ok(())
}

async fn health_check() -> impl IntoResponse {
    (StatusCode::OK, Json(serde_json::json!({ "status": "ok" })))
}

async fn list_records(State(state): State<AppState>) -> impl IntoResponse {
    let store = state.store.read().await;
    let records: Vec<ComplexRecord> = store.values().cloned().collect();
    (StatusCode::OK, Json(records))
}

async fn create_record(
    State(state): State<AppState>,
    Json(mut payload): Json<ComplexRecord>,
) -> impl IntoResponse {
    // Si l'ID est nul ou déjà existant, on en génère un nouveau
    if payload.id.is_nil() {
        payload.id = Uuid::new_v4();
    }

    let mut store = state.store.write().await;
    store.insert(payload.id, payload.clone());

    // Diffusion de l'événement via broadcast tokio::sync
    let _ = state.event_sender.send(payload.clone());

    (StatusCode::CREATED, Json(payload))
}

async fn get_record(
    State(state): State<AppState>,
    axum::extract::Path(id): axum::extract::Path<Uuid>,
) -> impl IntoResponse {
    let store = state.store.read().await;
    if let Some(record) = store.get(&id) {
        (StatusCode::OK, Json(serde_json::to_value(record).unwrap_or_default())).into_response()
    } else {
        (
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({ "error": "Enregistrement non trouvé" })),
        )
            .into_response()
    }
}

