/// --- 2. CONFIGURATION EN LIGNE DE COMMANDE (CLAP) ---

#[derive(Parser, Debug)]
#[command(
    name = "async-tui-serializer",
    version = "0.1.0",
    about = "CLI asynchrone clap & tokio avec sérialisation serde_json et TUI ratatui/crossterm"
)]
pub struct Cli {
    #[arg(short, long, default_value_t = 3, help = "Nombre de workers asynchrones tokio")]
    pub workers: usize,

    #[arg(short, long, default_value_t = 1000, help = "Intervalle de génération par worker en ms")]
    pub interval_ms: u64,

    #[command(subcommand)]
    pub command: Option<Commands>,
}

#[derive(Subcommand, Debug)]
pub enum Commands {
    /// Lance l'interface interactive TUI (Ratatui & Crossterm)
    Tui,
    /// Mode batch : sérialise N rapports de manière asynchrone et les sauvegarde
    Batch {
        #[arg(short, long, default_value_t = 10, help = "Nombre de rapports à générer")]
        count: usize,
        #[arg(short, long, help = "Fichier de sortie JSON optionnel")]
        output: Option<PathBuf>,
    },
}

/// Événements transmis depuis les tâches d'arrière-plan Tokio vers l'interface TUI
pub enum AppEvent {
    ReportGenerated {
        worker_id: usize,
        serialized_json: String,
        raw_size_bytes: usize,
        report: SystemTelemetryReport,
    },
    WorkerHeartbeat {
        worker_id: usize,
        processed_count: u64,
    },
}

/// État interne de l'application TUI
pub struct AppState {
    pub workers_count: usize,
    pub recent_reports: Vec<(DateTime<Utc>, String, usize, SystemTelemetryReport)>,
    pub total_serialized_bytes: usize,
    pub total_reports: usize,
    pub logs: Vec<String>,
    pub selected_index: usize,
    pub is_paused: bool,
}

impl AppState {
    pub fn new(workers_count: usize) -> Self {
        Self {
            workers_count,
            recent_reports: Vec::new(),
            total_serialized_bytes: 0,
            total_reports: 0,
            logs: vec!["Application démarrée. En attente d'événements...".to_string()],
            selected_index: 0,
            is_paused: false,
        }
    }

    pub fn add_report(&mut self, worker_id: usize, json_str: String, size: usize, report: SystemTelemetryReport) {
        self.total_reports += 1;
        self.total_serialized_bytes += size;

        let log_entry = format!(
            "[{}] Worker #{} a sérialisé le rapport {} ({} octets)",
            report.timestamp.format("%H:%M:%S"),
            worker_id,
            report.report_id,
            size
        );
        self.logs.push(log_entry);
        if self.logs.len() > 100 {
            self.logs.remove(0);
        }

        self.recent_reports.insert(0, (report.timestamp, json_str, size, report));
        if self.recent_reports.len() > 50 {
            self.recent_reports.pop();
        }
    }
}

/// --- 3. GÉNÉRATEURS DE DONNÉES & SÉRIALISATION ASYNCHRONE ---

pub fn generate_sample_report(worker_id: usize, sequence: u64) -> SystemTelemetryReport {
    let mut config = HashMap::new();
    config.insert("pipeline_mode".to_string(), serde_json::json!("continuous_streaming"));
    config.insert("buffer_capacity".to_string(), serde_json::json!(8192));
    config.insert("active_features".to_string(), serde_json::json!(["tokio", "ratatui", "serde_json"]));
    config.insert("worker_attributes".to_string(), serde_json::json!({
        "id": worker_id,
        "affinity": "balanced",
        "nested_layer": { "deep_level": 4, "validated": true }
    }));

    let host = HostMetrics {
        hostname: format!("worker-node-{:02}.cluster.local", worker_id),
        cpu_load: ((sequence as f32 * 13.7) % 100.0).abs(),
        memory_used_mb: 4096 + (sequence * 128 % 8192),
        memory_total_mb: 16384,
        disks: vec![
            DiskPartition {
                mount_point: "/".to_string(),
                total_gb: 512.0,
                used_gb: 210.5,
            },
            DiskPartition {
                mount_point: "/mnt/storage".to_string(),
                total_gb: 2048.0,
                used_gb: 875.2,
            },
        ],
        networks: vec![
            NetworkInterface {
                interface_name: "eth0".to_string(),
                rx_bytes: 1024 * sequence * 45,
                tx_bytes: 1024 * sequence * 32,
                is_up: true,
            },
            NetworkInterface {
                interface_name: "docker0".to_string(),
                rx_bytes: 512 * sequence,
                tx_bytes: 256 * sequence,
                is_up: true,
            },
        ],
    };

    let status = match sequence % 5 {
        0 => ServiceStatus::Critical {
            error_code: 503,
            alert: "Pression mémoire élevée détectée".to_string(),
        },
        1 => ServiceStatus::Degraded {
            reason: "Latence réseau anormale".to_string(),
        },
        _ => ServiceStatus::Healthy,
    };

    let mut task_meta = HashMap::new();
    task_meta.insert("execution_context".to_string(), serde_json::json!("async_runtime"));
    task_meta.insert("retry_attempts".to_string(), serde_json::json!(sequence % 3));

    let active_tasks = vec![
        TaskExecution {
            task_id: Uuid::new_v4(),
            name: "telemetry_harvester".to_string(),
            duration_ms: (sequence * 47) % 500 + 10,
            status: status.clone(),
            metadata: task_meta.clone(),
        },
        TaskExecution {
            task_id: Uuid::new_v4(),
            name: "json_serializer_pipeline".to_string(),
            duration_ms: 12,
            status: ServiceStatus::Healthy,
            metadata: task_meta,
        },
    ];

    SystemTelemetryReport {
        report_id: Uuid::new_v4(),
        timestamp: Utc::now(),
        cluster_region: "eu-west-3".to_string(),
        host,
        active_tasks,
        arbitrary_config: config,
    }
}

/// Tâche d'arrière-plan Tokio sérialisant périodiquement des données complexes
async fn spawn_worker_task(
    worker_id: usize,
    interval_duration: Duration,
    tx: mpsc::Sender<AppEvent>,
) {
    let mut ticker = tokio::time::interval(interval_duration);
    let mut sequence: u64 = 0;

    loop {
        ticker.tick().await;
        sequence += 1;

        let report = generate_sample_report(worker_id, sequence);

        // Sérialisation serde_json asynchrone / calcul lourd déporté via spawn_blocking si nécessaire,
        // ou directement dans la boucle tokio
        match serde_json::to_string_pretty(&report) {
            Ok(json_str) => {
                let size = json_str.len();
                let event = AppEvent::ReportGenerated {
                    worker_id,
                    serialized_json: json_str,
                    raw_size_bytes: size,
                    report,
                };
                if tx.send(event).await.is_err() {
                    // Récepteur fermé, arrêt du worker
                    break;
                }
            }
            Err(e) => {
                eprintln!("Erreur de sérialisation pour le worker {}: {}", worker_id, e);
            }
        }

        if sequence % 5 == 0 {
            let _ = tx
                .send(AppEvent::WorkerHeartbeat {
                    worker_id,
                    processed_count: sequence,
                })
                .await;
        }
    }
}

/// --- 4. EXÉCUTION EN MODE BATCH (LIGNE DE COMMANDE PUR SANS TUI) ---

async fn run_batch_mode(workers_count: usize, count: usize, output_path: Option<PathBuf>) -> Result<()> {
    println!(
        "Démarrage de la sérialisation en mode Batch ({} rapports cibles, {} workers)...",
        count, workers_count
    );

    let (tx, mut rx) = mpsc::channel::<SystemTelemetryReport>(100);
    let reports_per_worker = (count + workers_count - 1) / workers_count;

    for worker_id in 0..workers_count {
        let task_tx = tx.clone();
        tokio::spawn(async move {
            for seq in 0..reports_per_worker {
                let report = generate_sample_report(worker_id, seq as u64);
                if task_tx.send(report).await.is_err() {
                    break;
                }
            }
        });
    }
    drop(tx); // Ferme l'émetteur principal pour clore le stream rx une fois fini

    let mut collected = Vec::with_capacity(count);
    let start = std::time::Instant::now();

    while let Some(report) = rx.recv().await {
        collected.push(report);
        if collected.len() >= count {
            break;
        }
    }

    println!("Génération terminée en {:.2?}.", start.elapsed());
    let serialize_start = std::time::Instant::now();
    let json_output = serde_json::to_string_pretty(&collected)
        .context("Échec lors de la sérialisation serde_json des données collectées")?;
    let serialize_elapsed = serialize_start.elapsed();

    println!(
        "Sérialisation serde_json de {} enregistrements achevée en {:.2?} (Taille totale: {} Ko).",
        collected.len(),
        serialize_elapsed,
        json_output.len() / 1024
    );

    if let Some(path) = output_path {
        tokio::fs::write(&path, json_output.as_bytes())
            .await
            .with_context(|| format!("Impossible d'écrire le fichier de sortie: {:?}", path))?;
        println!("Résultats sauvegardés avec succès dans: {:?}", path);
    } else {
        println!("Aperçu JSON (premiers 500 caractères) :");
        println!("{}", &json_output[..json_output.len().min(500)]);
        if json_output.len() > 500 {
            println!("...");
        }
    }

    Ok(())
}

/// --- 5. INTERFACE TUI RATATUI & CROSSTERM AVEC TÂCHES TOKIO ---

async fn run_tui_mode(workers_count: usize, interval_ms: u64) -> Result<()> {
    enable_raw_mode().context("Impossible d'activer le raw mode crossterm")?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen).context("Impossible de passer en alternate screen")?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend).context("Impossible d'initialiser le terminal ratatui")?;

    let res = tui_main_loop(&mut terminal, workers_count, interval_ms).await;

    // Restauration du terminal garantie même après erreur
    disable_raw_mode().ok();
    execute!(terminal.backend_mut(), LeaveAlternateScreen).ok();
    terminal.show_cursor().ok();

    res
}

async fn tui_main_loop(
    terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
    workers_count: usize,
    interval_ms: u64,
) -> Result<()> {
    let (event_tx, mut event_rx) = mpsc::channel::<AppEvent>(200);

    // Démarrage des workers asynchrones tokio
    let interval = Duration::from_millis(interval_ms);
    for worker_id in 0..workers_count {
        let tx = event_tx.clone();
        tokio::spawn(async move {
            spawn_worker_task(worker_id, interval, tx).await;
        });
    }

    let mut state = AppState::new(workers_count);
    let mut event_stream = crossterm::event::EventStream::new();

    loop {
        terminal.draw(|f| render_ui(f, &state))?;

        tokio::select! {
            // Événement d'entrée utilisateur (clavier crossterm)
            maybe_event = event_stream.next() => {
                match maybe_event {
                    Some(Ok(Event::Key(key_event))) => {
                        if key_event.kind == KeyEventKind::Press {
                            match key_event.code {
                                KeyCode::Char('q') | KeyCode::Esc => {
                                    break;
                                }
                                KeyCode::Char(' ') => {
                                    state.is_paused = !state.is_paused;
                                    let status_str = if state.is_paused { "Pause" } else { "Reprise" };
                                    state.logs.push(format!("[Contrôle] Flux basculé en: {}", status_str));
                                }
                                KeyCode::Down | KeyCode::Char('j') => {
                                    if !state.recent_reports.is_empty() && state.selected_index + 1 < state.recent_reports.len() {
                                        state.selected_index += 1;
                                    }
                                }
                                KeyCode::Up | KeyCode::Char('k') => {
                                    if state.selected_index > 0 {
                                        state.selected_index -= 1;
                                    }
                                }
                                KeyCode::Char('c') => {
                                    state.logs.clear();
                                    state.logs.push("[Info] Journal nettoyé".to_string());
                                }
                                _ => {}
                            }
                        }
                    }
                    Some(Ok(_)) => {}
                    Some(Err(e)) => {
                        eprintln!("Erreur lors de la lecture d'un événement crossterm: {}", e);
                    }
                    None => break,
                }
            }

            // Événements asynchrones reçus des workers tokio
            maybe_app_event = event_rx.recv() => {
                if let Some(event) = maybe_app_event {
                    match event {
                        AppEvent::ReportGenerated { worker_id, serialized_json, raw_size_bytes, report } => {
                            if !state.is_paused {
                                state.add_report(worker_id, serialized_json, raw_size_bytes, report);
                            }
                        }
                        AppEvent::WorkerHeartbeat { worker_id, processed_count } => {
                            if !state.is_paused {
                                state.logs.push(format!("[Heartbeat] Worker #{} : {} cycles", worker_id, processed_count));
                            }
                        }
                    }
                } else {
                    break;
                }
            }
        }
    }

    Ok(())
}

fn render_ui(f: &mut Frame, state: &AppState) {
    let main_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // En-tête / Statistiques
            Constraint::Min(10),   // Zone principale (2 colonnes)
            Constraint::Length(7), // Logs en bas
            Constraint::Length(2), // Barre d'aide / Commandes
        ])
        .split(f.area());

    // 1. En-tête
    let total_kb = state.total_serialized_bytes as f64 / 1024.0;
    let header_text = vec![Line::from(vec![
        Span::styled(" ASYNC SERIALIZER & TUI ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw(format!(
            "| Workers Tokio: {} | Objets sérialisés: {} | Débit JSON: {:.2} Ko | Statut: ",
            state.workers_count, state.total_reports, total_kb
        )),
        if state.is_paused {
            Span::styled("EN PAUSE", Style::default().fg(Color::Red).add_modifier(Modifier::BOLD))
        } else {
            Span::styled("ACTIF", Style::default().fg(Color::Green).add_modifier(Modifier::BOLD))
        },
    ])];
    let header = Paragraph::new(header_text).block(Block::default().borders(Borders::ALL).title("Statistiques Runtime"));
    f.render_widget(header, main_chunks[0]);

    // 2. Zone principale divisée horizontalement
    let body_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(40), Constraint::Percentage(60)])
        .split(main_chunks[1]);

    // Liste des rapports reçus
    let items: Vec<ListItem> = state
        .recent_reports
        .iter()
        .enumerate()
        .map(|(idx, (ts, _, size, rep))| {
            let is_selected = idx == state.selected_index;
            let status_indicator = match rep.active_tasks.first().map(|t| &t.status) {
                Some(ServiceStatus::Healthy) => Span::styled(" [OK] ", Style::default().fg(Color::Green)),
                Some(ServiceStatus::Degraded { .. }) => Span::styled(" [WARN] ", Style::default().fg(Color::Yellow)),
                Some(ServiceStatus::Critical { .. }) => Span::styled(" [ERR] ", Style::default().fg(Color::Red)),
                None => Span::raw(" [?] "),
            };

            let line_style = if is_selected {
                Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)
            } else {
                Style::default().fg(Color::White)
            };

            let text = Line::from(vec![
                Span::raw(if is_selected { "▶ " } else { "  " }),
                status_indicator,
                Span::styled(format!("{} - {} ({} B)", ts.format("%H:%M:%S"), &rep.report_id.to_string()[..8], size), line_style),
            ]);
            ListItem::new(text)
        })
        .collect();

    let list_title = format!("Flux de Rapports Reçus ({})", state.recent_reports.len());
    let list_widget = List::new(items).block(Block::default().borders(Borders::ALL).title(list_title));
    f.render_widget(list_widget, body_chunks[0]);

    // Panneau de visualisation JSON du rapport sélectionné
    let json_preview = if let Some((_, json_str, _, rep)) = state.recent_reports.get(state.selected_index) {
        let cpu = rep.host.cpu_load.min(100.0).max(0.0) as u16;
        let details_block = Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Length(3), Constraint::Min(5)])
            .split(body_chunks[1]);

        let gauge = Gauge::default()
            .block(Block::default().borders(Borders::ALL).title("Charge CPU Hôte Télémesure"))
            .gauge_style(Style::default().fg(if cpu > 80 { Color::Red } else { Color::Green }))
            .percent(cpu);
        f.render_widget(gauge, details_block[0]);

        Paragraph::new(json_str.clone())
            .block(Block::default().borders(Borders::ALL).title(format!("Payload serde_json :: {}", rep.report_id)))
            .wrap(Wrap { trim: false })
    } else {
        Paragraph::new("Aucune donnée disponible pour le moment...")
            .block(Block::default().borders(Borders::ALL).title("Visualiseur serde_json"))
    };
    f.render_widget(json_preview, if state.recent_reports.is_empty() { body_chunks[1] } else {
        Layout::default().direction(Direction::Vertical).constraints([Constraint::Length(3), Constraint::Min(5)]).split(body_chunks[1])[1]
    });

    // 3. Journal des événements
    let log_items: Vec<ListItem> = state
        .logs
        .iter()
        .rev()
        .take(5)
        .map(|log| ListItem::new(Line::from(vec![Span::styled(log, Style::default().fg(Color::DarkGray))])))
        .collect();
    let logs_widget = List::new(log_items).block(Block::default().borders(Borders::ALL).title("Journal des tâches asynchrones"));
    f.render_widget(logs_widget, main_chunks[2]);

    // 4. Barre d'aide
    let help_line = Line::from(vec![
        Span::styled("[q / Esc]", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw(" Quitter  | "),
        Span::styled("[Espace]", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw(" Mettre en pause/reprendre  | "),
        Span::styled("[↑ / k, ↓ / j]", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw(" Naviguer dans les payloads  | "),
        Span::styled("[c]", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw(" Effacer logs"),
    ]);
    let help_widget = Paragraph::new(help_line);
    f.render_widget(help_widget, main_chunks[3]);
}

/// --- 6. POINT D'ENTRÉE ASYNCHRONE TOKIO ---

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Some(Commands::Batch { count, output }) => {
            run_batch_mode(cli.workers, count, output).await?;
        }
        Some(Commands::Tui) | None => {
            run_tui_mode(cli.workers, cli.interval_ms).await?;
        }
    }

    Ok(())
}

