}

#[derive(Subcommand, Debug)]
pub enum Commands {
    /// Génère un jeu de données exemple et le sauvegarde au format spécifié
    Generate {
        /// Nombre d'enregistrements à générer
        #[arg(short, long, default_value_t = 10)]
        count: usize,

