        .map(|i| ComplexRecord {
            id: format!("rec-{:05}", i + 1),
            name: format!("Item-{}", i + 1),
            tags: vec![
                format!("env:{}", if i % 2 == 0 { "prod" } else { "staging" }),
                format!("tier:{}", (i % 3) + 1),
