/// Écrit de manière asynchrone des enregistrements au format JSON
async fn write_records_to_json(records: &[ComplexRecord], path: &Path) -> Result<()> {
    let json_bytes = serde_json::to_vec_pretty(records)
        .context("Échec de la sérialisation en JSON indenté")?;
    let mut file = File::create(path)
        .await
        .with_context(|| format!("Impossible de créer le fichier: {:?}", path))?;
    file.write_all(&json_bytes)
        .await
        .with_context(|| format!("Erreur lors de l'écriture dans le fichier: {:?}", path))?;
    file.flush()
        .await
        .with_context(|| format!("Erreur lors du flush du fichier: {:?}", path))?;
    Ok(())
}

/// Lit de manière asynchrone des enregistrements depuis un fichier JSON
async fn read_records_from_json(path: &Path) -> Result<Vec<ComplexRecord>> {
    let mut file = File::open(path)
        .await
        .with_context(|| format!("Impossible d'ouvrir le fichier JSON: {:?}", path))?;
    let mut buffer = Vec::new();
    file.read_to_end(&mut buffer)
        .await
        .with_context(|| format!("Erreur lors de la lecture du fichier JSON: {:?}", path))?;
    let records: Vec<ComplexRecord> = serde_json::from_slice(&buffer)
        .with_context(|| format!("Erreur lors du parsing JSON depuis: {:?}", path))?;
    Ok(records)
}

/// Construit le schéma Arrow correspondant à notre structure ComplexRecord
fn build_arrow_schema() -> Schema {
    Schema::new(vec![
        Field::new("id", DataType::Utf8, false),
        Field::new("name", DataType::Utf8, false),
        Field::new(
            "tags",
            DataType::List(Arc::new(Field::new("item", DataType::Utf8, true))),
            false,
        ),
        Field::new("status", DataType::Utf8, false),
        Field::new("score", DataType::Float64, false),
        Field::new("is_verified", DataType::Boolean, false),
        Field::new("metrics_json", DataType::Utf8, false),
    ])
}

/// Convertit une tranche de ComplexRecord en RecordBatch Arrow
fn records_to_record_batch(records: &[ComplexRecord]) -> Result<RecordBatch> {
    let schema = Arc::new(build_arrow_schema());

    let mut id_builder = StringBuilder::new();
    let mut name_builder = StringBuilder::new();
    let mut status_builder = StringBuilder::new();
    let mut tags_builder = ListBuilder::new(StringBuilder::new());
    let mut metrics_builder = StringBuilder::new();

    let mut scores = Vec::with_capacity(records.len());
    let mut is_verified_flags = Vec::with_capacity(records.len());

    for record in records {
        id_builder.append_value(&record.id);
        name_builder.append_value(&record.name);

        let status_str = match record.status {
            RecordStatus::Pending => "pending",
            RecordStatus::Active => "active",
            RecordStatus::Archived => "archived",
        };
        status_builder.append_value(status_str);

        let values = tags_builder.values();
        for tag in &record.tags {
            values.append_value(tag);
        }
        tags_builder.append(true);

        scores.push(record.score);
        is_verified_flags.push(Some(record.is_verified));

        let metrics_json = serde_json::to_string(&record.metrics)
            .context("Erreur de sérialisation JSON pour le champ metrics")?;
        metrics_builder.append_value(&metrics_json);
    }

    let id_array = Arc::new(id_builder.finish()) as ArrayRef;
    let name_array = Arc::new(name_builder.finish()) as ArrayRef;
    let tags_array = Arc::new(tags_builder.finish()) as ArrayRef;
    let status_array = Arc::new(status_builder.finish()) as ArrayRef;
    let score_array = Arc::new(Float64Array::from(scores)) as ArrayRef;
    let is_verified_array = Arc::new(BooleanArray::from(is_verified_flags)) as ArrayRef;
    let metrics_array = Arc::new(metrics_builder.finish()) as ArrayRef;

    let batch = RecordBatch::try_new(
        schema,
        vec![
            id_array,
            name_array,
            tags_array,
            status_array,
            score_array,
            is_verified_array,
            metrics_array,
        ],
    )
    .context("Échec de la construction du RecordBatch Arrow")?;

    Ok(batch)
}

/// Écrit de manière asynchrone des enregistrements au format Parquet via tokio::fs::File et AsyncArrowWriter
async fn write_records_to_parquet(records: &[ComplexRecord], path: &Path) -> Result<()> {
    let file = File::create(path)
        .await
        .with_context(|| format!("Impossible de créer le fichier Parquet: {:?}", path))?;

    let batch = records_to_record_batch(records)?;
    let schema = batch.schema();

    let mut writer = AsyncArrowWriter::try_new(file, schema, None)
        .context("Échec de l'initialisation de AsyncArrowWriter")?;

    writer
        .write(&batch)
        .await
        .context("Échec de l'écriture asynchrone du RecordBatch dans Parquet")?;

    writer
        .close()
        .await
        .context("Échec de la clôture et du flush du fichier Parquet")?;

    Ok(())
}

/// Inspecte et affiche le contenu d'un fichier Parquet
async fn inspect_parquet_file(path: &Path) -> Result<()> {
    let file = File::open(path)
        .await
        .with_context(|| format!("Impossible d'ouvrir le fichier Parquet: {:?}", path))?;

    let builder = ParquetRecordBatchStreamBuilder::new(file)
        .await
        .context("Échec de création du stream builder asynchrone pour Parquet")?;

    let mut stream = builder
        .build()
        .context("Échec de construction du flux RecordBatch Parquet")?;

    println!("=== Inspection Parquet: {:?} ===", path);
    use arrow::util::pretty::pretty_format_batches;

    let mut batches = Vec::new();
    while let Some(batch) = stream
        .try_next()
        .await
        .context("Erreur lors de la lecture du batch Parquet")?
    {
        batches.push(batch);
    }

    let formatted = pretty_format_batches(&batches)
        .context("Erreur lors du formatage d'affichage des RecordBatches")?;
    println!("{}", formatted);
    println!("Total de lots (batches) : {}", batches.len());
    let total_rows: usize = batches.iter().map(|b| b.num_rows()).sum();
    println!("Total de lignes : {}", total_rows);

    Ok(())
}

/// Détermine le format selon l'extension si non spécifié explicitement
fn infer_format(path: &Path, explicit_format: Option<OutputFormat>) -> Result<OutputFormat> {
    if let Some(format) = explicit_format {
        return Ok(format);
    }
    match path.extension().and_then(|ext| ext.to_str()) {
        Some("json") => Ok(OutputFormat::Json),
        Some("parquet") | Some("pq") => Ok(OutputFormat::Parquet),
        _ => anyhow::bail!(
            "Impossible de déduire le format pour '{:?}'. Spécifiez explicitement --format.",
            path
        ),
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Generate {
            count,
            format,
            output,
        } => {
            println!(
                "Génération de {} enregistrements complexes vers {:?}",
                count, output
            );
            let records = generate_sample_records(count);
            match format {
                OutputFormat::Json => {
                    write_records_to_json(&records, &output).await?;
                    println!("Succès : données sérialisées en JSON dans {:?}", output);
                }
                OutputFormat::Parquet => {
                    write_records_to_parquet(&records, &output).await?;
                    println!("Succès : données sérialisées en Parquet dans {:?}", output);
                }
            }
        }
        Commands::JsonToParquet { input, output } => {
            println!(
                "Conversion de {:?} (JSON) vers {:?} (Parquet)...",
                input, output
            );
            let records = read_records_from_json(&input).await?;
            println!("{} enregistrements lus depuis {:?}", records.len(), input);
            write_records_to_parquet(&records, &output).await?;
            println!("Conversion terminée avec succès !");
        }
        Commands::Inspect { input, format } => {
            let detected_format = infer_format(&input, format)?;
            match detected_format {
                OutputFormat::Json => {
                    println!("Lecture et inspection du fichier JSON {:?}", input);
                    let records = read_records_from_json(&input).await?;
                    println!("Nombre d'enregistrements : {}", records.len());
                    for (idx, record) in records.iter().take(5).enumerate() {
                        println!(
                            "[{}] ID={} Nom={} Statut={:?} Tags={:?} Score={} Métriques={}",
                            idx + 1,
                            record.id,
                            record.name,
                            record.status,
                            record.tags,
                            record.score,
                            record.metrics.len()
                        );
                    }
                    if records.len() > 5 {
                        println!("... et {} autres enregistrements.", records.len() - 5);
                    }
                }
                OutputFormat::Parquet => {
                    inspect_parquet_file(&input).await?;
                }
            }
        }
    }

    Ok(())
}

