#[derive(Error, Debug)]
pub enum AppError {
    #[error("Erreur I/O: {0}")]
    Io(#[from] std::io::Error),

    #[error("Erreur de sérialisation/désérialisation JSON: {0}")]
    Json(#[from] serde_json::Error),

    #[error("Erreur du moteur de template Tera: {0}")]
    Template(#[from] tera::Error),

    #[error("Erreur serveur réseau: {0}")]
    Server(String),
}

impl IntoResponse for AppError {
    fn into_response(self) -> Response {
        let (status, error_message) = match &self {
            AppError::Json(err) => (StatusCode::BAD_REQUEST, err.to_string()),
            AppError::Template(err) => (StatusCode::INTERNAL_SERVER_ERROR, err.to_string()),
            AppError::Io(err) => (StatusCode::INTERNAL_SERVER_ERROR, err.to_string()),
            AppError::Server(err) => (StatusCode::INTERNAL_SERVER_ERROR, err.clone()),
        };

        let body = Json(serde_json::json!({
            "success": false,
            "error": error_message
        }));

        (status, body).into_response()
    }
}

