pub struct ProjectReport {
    pub id: Uuid,
    pub title: String,
    pub timestamp: DateTime<Utc>,
    pub status: ReportStatus,
    pub author: Author,
    pub metadata: HashMap<String, String>,
    pub metrics: Vec<Metric>,
}

impl ProjectReport {
