pub fn initialize_tera(custom_template: Option<&PathBuf>) -> Result<Tera, AppError> {
    let mut tera = Tera::default();
    tera.add_raw_template(DEFAULT_TEMPLATE_NAME, DEFAULT_TEMPLATE_CONTENT)?;

    if let Some(path) = custom_template {
        let content = std::fs::read_to_string(path)?;
        let name = path
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("custom_template.html");
        tera.add_raw_template(name, &content)?;
    }

    Ok(tera)
}

