// Serveur Web axum & Handlers
// ============================================================================

#[derive(Clone)]
pub struct AppState {
    pub tera: Arc<Tera>,
}

async fn health_handler() -> &'static str {
    "OK"
}

/// Ingestion et validation sérialisée d'un rapport
async fn serialize_report_handler(
    Json(payload): Json<ProjectReport>,
) -> Result<Json<serde_json::Value>, AppError> {
    info!(
        report_id = %payload.id,
        title = %payload.title,
        "Validation et sérialisation du rapport reçue"
    );

    let serialized = serde_json::to_value(&payload)?;
    Ok(Json(serde_json::json!({
        "success": true,
        "item_count": payload.metrics.len(),
        "data": serialized
    })))
}

/// Rendu dynamique du template Tera à partir du payload JSON
async fn render_report_handler(
    State(state): State<AppState>,
    Json(payload): Json<ProjectReport>,
) -> Result<Html<String>, AppError> {
    let context_data = ReportTemplateContext::from_report(payload);
    let tera_context = tera::Context::from_serialize(&context_data)?;

    let rendered = state.tera.render(DEFAULT_TEMPLATE_NAME, &tera_context)?;
    Ok(Html(rendered))
}

pub fn create_router(state: AppState) -> Router {
    Router::new()
        .route("/health", get(health_handler))
        .route("/api/reports/serialize", post(serialize_report_handler))
        .route("/api/reports/render", post(render_report_handler))
        .with_state(state)
}

// ============================================================================
// Logique des Sous-Commandes CLI
// ============================================================================

async fn handle_generate(args: GenerateArgs) -> Result<(), AppError> {
    let report = ProjectReport::sample();

    let json_output = if args.pretty {
        serde_json::to_string_pretty(&report)?
    } else {
        serde_json::to_string(&report)?
    };

    if let Some(output_path) = args.output {
        tokio::fs::write(&output_path, json_output.as_bytes()).await?;
        println!("Rapport sérialisé avec succès dans : {}", output_path.display());
    } else {
        println!("{}", json_output);
    }

    Ok(())
}

async fn handle_render(args: RenderArgs) -> Result<(), AppError> {
    let report = if let Some(input_path) = &args.input {
        let content = tokio::fs::read_to_string(input_path).await?;
        serde_json::from_str::<ProjectReport>(&content)?
    } else {
        ProjectReport::sample()
    };

    let tera = initialize_tera(args.template.as_ref())?;
    let template_name = if let Some(path) = &args.template {
        path.file_name()
            .and_then(|n| n.to_str())
            .unwrap_or(DEFAULT_TEMPLATE_NAME)
    } else {
        DEFAULT_TEMPLATE_NAME
    };

    let context = ReportTemplateContext::from_report(report);
    let tera_context = tera::Context::from_serialize(&context)?;
    let rendered = tera.render(template_name, &tera_context)?;

    if let Some(output_path) = args.output {
        tokio::fs::write(&output_path, rendered.as_bytes()).await?;
        println!("Fichier rendu sauvegardé avec succès dans : {}", output_path.display());
    } else {
        println!("{}", rendered);
    }

    Ok(())
}

async fn handle_serve(args: ServeArgs) -> Result<(), AppError> {
    let tera = initialize_tera(None)?;
    let state = AppState {
        tera: Arc::new(tera),
    };

    let app = create_router(state);
    let addr: SocketAddr = format!("{}:{}", args.host, args.port)
        .parse()
        .map_err(|e| AppError::Server(format!("Adresse invalide: {}", e)))?;

    info!("Démarrage du serveur axum sur http://{}", addr);
    println!("Serveur HTTP actif sur http://{}", addr);
    println!("Routes disponibles :");
    println!("  - GET  /health");
    println!("  - POST /api/reports/serialize");
    println!("  - POST /api/reports/render");

    let listener = tokio::net::TcpListener::bind(addr).await?;
    axum::serve(listener, app)
        .await
        .map_err(|e| AppError::Server(e.to_string()))?;

    Ok(())
}

// ============================================================================
// Point d'entrée principal (tokio runtime)
// ============================================================================

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialisation du logging avec tracing
    tracing_subscriber::registry()
        .with(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info,dystil_cli=debug".into()),
        )
        .with(tracing_subscriber::fmt::layer())
        .init();

    let cli = Cli::parse();

    let result = match cli.command {
        Commands::Generate(args) => handle_generate(args).await,
        Commands::Render(args) => handle_render(args).await,
        Commands::Serve(args) => handle_serve(args).await,
    };

    if let Err(err) = result {
        error!("Erreur d'exécution : {}", err);
        eprintln!("Erreur : {}", err);
        std::process::exit(1);
    }

    Ok(())
}

