```rust
// src/main.rs
use std::io::{self, Read, Write};
use std::net::{TcpListener, TcpStream};
use std::sync::{mpsc, Arc, Mutex};
use std::thread;

/// Type alias représentant une tâche exécutable par le pool de workers.
type Job = Box<dyn FnOnce() + Send + 'static>;

/// Message transmis aux workers via le canal `mpsc`.
enum Message {
    NewJob(Job),
    Terminate,
}

/// Worker individuel consommant les tâches depuis le récepteur partagé.
struct Worker {
    id: usize,
    thread: Option<thread::JoinHandle<()>>,
}

impl Worker {
    fn new(id: usize, receiver: Arc<Mutex<mpsc::Receiver<Message>>>) -> Worker {
        let thread = thread::Builder::new()
            .name(format!("worker-{}", id))
            .spawn(move || loop {
                let message = {
                    let lock = receiver.lock().expect("Impossible de verrouiller le mutex du récepteur");
                    lock.recv()
                };

                match message {
                    Ok(Message::NewJob(job)) => {
                        job();
                    }
                    Ok(Message::Terminate) => {
                        break;
                    }
                    Err(_) => {
                        // Canal fermé (émetteur détruit), arrêt propre du worker.
                        break;
                    }
                }
            })
            .expect("Échec de la création du thread worker");

        Worker {
            id,
            thread: Some(thread),
        }
    }
}

/// Pool de threads gérant un ensemble fixe de workers alimentés par un canal `mpsc`.
pub struct ThreadPool {
    workers: Vec<Worker>,
    sender: Option<mpsc::Sender<Message>>,
}

impl ThreadPool {
    /// Crée un nouveau `ThreadPool` avec le nombre spécifié de threads.
    ///
    /// # Panics
    /// Panique si `size` est égal à 0.
    pub fn new(size: usize) -> ThreadPool {
        assert!(size > 0, "La taille du ThreadPool doit être supérieure à zéro");

        let (sender, receiver) = mpsc::channel();
        let receiver = Arc::new(Mutex::new(receiver));

        let mut workers = Vec::with_capacity(size);
        for id in 0..size {
            workers.push(Worker::new(id, Arc::clone(&receiver)));
        }

        ThreadPool {
            workers,
            sender: Some(sender),
        }
    }

    /// Soumet une nouvelle tâche au pool d'exécution.
    pub fn execute<F>(&self, f: F)
    where
        F: FnOnce() + Send + 'static,
    {
        let job = Box::new(f);
        if let Some(ref sender) = self.sender {
            if let Err(err) = sender.send(Message::NewJob(job)) {
                eprintln!("Erreur lors de l'envoi de la tâche au pool: {err}");
            }
        }
    }
}

impl Drop for ThreadPool {
    fn drop(&mut self) {
        if let Some(sender) = self.sender.take() {
            // Envoyer un signal d'arrêt à chaque worker
            for _ in &self.workers {
                let _ = sender.send(Message::Terminate);
            }
        }

        // Attendre la fin de l'exécution de chaque worker (graceful shutdown)
        for worker in &mut self.workers {
            if let Some(thread) = worker.thread.take() {
                if let Err(err) = thread.join() {
                    eprintln!("Erreur lors de la terminaison du worker {}: {:?}", worker.id, err);
                }
            }
        }
    }
}

/// Traite une connexion TCP cliente en effectuant un écho bidirectionnel.
fn handle_client(mut stream: TcpStream) {
    let peer_addr = match stream.peer_addr() {
        Ok(addr) => addr,
        Err(err) => {
            eprintln!("Impossible de déterminer l'adresse du client: {err}");
            return;
        }
    };

    println!("[+] Client connecté: {peer_addr}");

    let mut buffer = [0u8; 1024];
    loop {
        match stream.read(&mut buffer) {
            Ok(0) => {
                // Déconnexion propre par le client (EOF)
                println!("[-] Client déconnecté: {peer_addr}");
                break;
            }
            Ok(bytes_read) => {
                // Renvoi des octets reçus (écho)
                if let Err(err) = stream.write_all(&buffer[..bytes_read]) {
                    eprintln!("Erreur d'écriture vers {peer_addr}: {err}");
                    break;
                }
                if let Err(err) = stream.flush() {
                    eprintln!("Erreur de flush vers {peer_addr}: {err}");
                    break;
                }
            }
            Err(ref err) if err.kind() == io::ErrorKind::Interrupted => {
                continue;
            }
            Err(err) => {
                eprintln!("Erreur de lecture sur {peer_addr}: {err}");
                break;
            }
        }
    }
}

fn main() -> io::Result<()> {
    let bind_addr = "127.0.0.1:7878";
    let listener = TcpListener::bind(bind_addr)?;
    println!("=== Serveur écho TCP démarré sur http://{bind_addr} ===");
    println!("Appuyez sur Ctrl+C pour arrêter le serveur.");

    let pool = ThreadPool::new(4);

    for stream in listener.incoming() {
        match stream {
            Ok(stream) => {
                pool.execute(move || {
                    handle_client(stream);
                });
            }
            Err(err) => {
                eprintln!("Échec de l'acceptation d'une connexion: {err}");
            }
        }
    }

    Ok(())
}

