                eprintln!("Erreur de lecture sur {peer_addr}: {err}");
                break;
            }
        }
    }
}

fn main() -> io::Result<()> {
    let bind_addr = "127.0.0.1:7878";
    let listener = TcpListener::bind(bind_addr)?;
    println!("=== Serveur écho TCP démarré sur http://{bind_addr} ===");
    println!("Appuyez sur Ctrl+C pour arrêter le serveur.");

    let pool = ThreadPool::new(4);

    for stream in listener.incoming() {
        match stream {
            Ok(stream) => {
                pool.execute(move || {
                    handle_client(stream);
                });
            }
            Err(err) => {
                eprintln!("Échec de l'acceptation d'une connexion: {err}");
            }
        }
    }

    Ok(())
}

