// src/main.rs
//! Implémentation générique en mémoire d'un arbre B-Tree en Rust.
//!
//! Fournit les traits [`Iterator`], [`IntoIterator`], [`Extend`], [`FromIterator`],
//! ainsi que la recherche, insertion et mise à jour sans code `unsafe`.

use std::borrow::Borrow;
use std::fmt;

/// Degré minimal par défaut pour l'arbre B-Tree.
/// Un nœud non-racine possède entre `B - 1` et `2*B - 1` clés.
pub const DEFAULT_B: usize = 3;

/// Un nœud dans le B-Tree.
#[derive(Clone, Debug)]
struct Node<K, V> {
    keys: Vec<K>,
    values: Vec<V>,
    children: Vec<Node<K, V>>,
}

impl<K, V> Node<K, V> {
    fn new_leaf() -> Self {
        Self {
            keys: Vec::new(),
            values: Vec::new(),
            children: Vec::new(),
        }
    }

    #[inline]
    fn is_leaf(&self) -> bool {
        self.children.is_empty()
    }
}

/// Arbre B-Tree associatif générique en mémoire.
///
/// Le paramètre `B` représente le degré minimal de l'arbre (`B >= 2`).
/// - Tout nœud interne sauf la racine a au moins `B` enfants et `B - 1` clés.
/// - Tout nœud a au plus `2*B` enfants et `2*B - 1` clés.
#[derive(Clone)]
pub struct BTreeMap<K, V, const B: usize = DEFAULT_B> {
    root: Option<Node<K, V>>,
    len: usize,
}

impl<K, V, const B: usize> BTreeMap<K, V, B> {
    /// Crée un nouvel arbre B-Tree vide.
    ///
    /// # Panics
    /// Panique si `B < 2`, car le degré minimum d'un B-Tree doit être supérieur ou égal à 2.
    #[must_use]
    pub const fn new() -> Self {
        assert!(B >= 2, "Le degré minimal B d'un B-Tree doit être >= 2");
        Self { root: None, len: 0 }
    }

    /// Retourne le nombre d'éléments contenus dans l'arbre.
    #[inline]
    #[must_use]
    pub const fn len(&self) -> usize {
        self.len
    }

    /// Indique si l'arbre est vide.
    #[inline]
    #[must_use]
    pub const fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Vide l'arbre de tous ses éléments.
    pub fn clear(&mut self) {
        self.root = None;
        self.len = 0;
    }

    /// Recherche une référence immuable vers la valeur associée à la clé donnée.
    pub fn get<Q>(&self, key: &Q) -> Option<&V>
    where
        K: Borrow<Q> + Ord,
        Q: Ord + ?Sized,
    {
        let mut current = self.root.as_ref()?;
        loop {
            match current.keys.binary_search_by(|k| k.borrow().cmp(key)) {
                Ok(idx) => return current.values.get(idx),
                Err(idx) => {
                    if current.is_leaf() {
                        return None;
                    }
                    current = current.children.get(idx)?;
                }
            }
        }
    }

    /// Recherche une référence mutable vers la valeur associée à la clé donnée.
    pub fn get_mut<Q>(&mut self, key: &Q) -> Option<&mut V>
    where
        K: Borrow<Q> + Ord,
        Q: Ord + ?Sized,
    {
        let mut current = self.root.as_mut()?;
        loop {
            match current.keys.binary_search_by(|k| k.borrow().cmp(key)) {
                Ok(idx) => return current.values.get_mut(idx),
                Err(idx) => {
                    if current.is_leaf() {
                        return None;
                    }
                    current = match current.children.get_mut(idx) {
                        Some(child) => child,
                        None => return None,
                    };
                }
            }
        }
    }

    /// Vérifie si l'arbre contient la clé spécifiée.
    #[inline]
    pub fn contains_key<Q>(&self, key: &Q) -> bool
    where
        K: Borrow<Q> + Ord,
        Q: Ord + ?Sized,
    {
        self.get(key).is_some()
    }

    /// Insère une paire clé/valeur dans l'arbre.
    ///
    /// Si la clé existait déjà, remplace sa valeur et retourne l'ancienne valeur.
    /// Sinon, insère la nouvelle paire et retourne `None`.
    pub fn insert(&mut self, key: K, value: V) -> Option<V>
    where
        K: Ord,
    {
        let max_keys = 2 * B - 1;

        if let Some(ref root) = self.root {
            if root.keys.len() == max_keys {
                let mut new_root = Node {
                    keys: Vec::with_capacity(max_keys),
                    values: Vec::with_capacity(max_keys),
                    children: Vec::with_capacity(2 * B),
                };
                let old_root = self.root.take().unwrap_or_else(Node::new_leaf);
                new_root.children.push(old_root);
                Self::split_child(&mut new_root, 0);
                self.root = Some(new_root);
            }
        } else {
            let mut root = Node::new_leaf();
            root.keys.push(key);
            root.values.push(value);
            self.root = Some(root);
            self.len += 1;
            return None;
        }

        if let Some(ref mut root) = self.root {
            let res = Self::insert_non_full(root, key, value);
            if res.is_none() {
                self.len += 1;
            }
            res
        } else {
            None
        }
    }

    fn split_child(parent: &mut Node<K, V>, child_index: usize) {
        let child = match parent.children.get_mut(child_index) {
            Some(c) => c,
            None => return,
        };

        let mid_idx = B - 1;
        let right_keys = child.keys.split_off(mid_idx + 1);
        let right_values = child.values.split_off(mid_idx + 1);

        let right_children = if child.is_leaf() {
            Vec::new()
        } else {
            child.children.split_off(mid_idx + 1)
        };

        let median_key = child.keys.pop().expect("Le nœud plein doit avoir une clé médiane");
        let median_val = child.values.pop().expect("Le nœud plein doit avoir une valeur médiane");

        let right_node = Node {
            keys: right_keys,
            values: right_values,
            children: right_children,
        };

        parent.keys.insert(child_index, median_key);
        parent.values.insert(child_index, median_val);
        parent.children.insert(child_index + 1, right_node);
    }

    fn insert_non_full(node: &mut Node<K, V>, key: K, value: V) -> Option<V>
    where
        K: Ord,
    {
        match node.keys.binary_search(&key) {
            Ok(idx) => {
                let old = std::mem::replace(&mut node.values[idx], value);
                Some(old)
            }
            Err(idx) => {
                if node.is_leaf() {
                    node.keys.insert(idx, key);
                    node.values.insert(idx, value);
                    None
                } else {
                    let max_keys = 2 * B - 1;
                    if node.children[idx].keys.len() == max_keys {
                        Self::split_child(node, idx);
                        if key > node.keys[idx] {
                            Self::insert_non_full(&mut node.children[idx + 1], key, value)
                        } else if key < node.keys[idx] {
                            Self::insert_non_full(&mut node.children[idx], key, value)
                        } else {
                            let old = std::mem::replace(&mut node.values[idx], value);
                            Some(old)
                        }
                    } else {
                        Self::insert_non_full(&mut node.children[idx], key, value)
                    }
                }
            }
        }
    }

    /// Retourne un itérateur par référence immuable sur les paires `(&K, &V)`.
    #[must_use]
    pub fn iter(&self) -> Iter<'_, K, V> {
        Iter::new(self)
    }

    /// Retourne un itérateur par référence mutable sur les paires `(&K, &mut V)`.
    #[must_use]
    pub fn iter_mut(&mut self) -> IterMut<'_, K, V> {
        IterMut::new(self)
    }
}

impl<K, V, const B: usize> Default for BTreeMap<K, V, B> {
    fn default() -> Self {
        Self::new()
    }
}

impl<K: fmt::Debug, V: fmt::Debug, const B: usize> fmt::Debug for BTreeMap<K, V, B> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_map().entries(self.iter()).finish()
    }
}

impl<K: PartialEq, V: PartialEq, const B: usize> PartialEq for BTreeMap<K, V, B> {
    fn eq(&self, other: &Self) -> bool {
        if self.len() != other.len() {
            return false;
        }
        self.iter().zip(other.iter()).all(|((k1, v1), (k2, v2))| k1 == k2 && v1 == v2)
    }
}

impl<K: Eq, V: Eq, const B: usize> Eq for BTreeMap<K, V, B> {}

// ============================================================================
// Itérateur par référence immuable : Iter<'a, K, V>
// ============================================================================

struct IterFrame<'a, K, V> {
    node: &'a Node<K, V>,
    index: usize,
}

/// Itérateur empruntant immuablement les paires clé-valeur d'un [`BTreeMap`].
pub struct Iter<'a, K, V> {
    stack: Vec<IterFrame<'a, K, V>>,
    remaining: usize,
}

impl<'a, K, V> Iter<'a, K, V> {
    fn new<const B: usize>(tree: &'a BTreeMap<K, V, B>) -> Self {
        let mut iter = Self {
            stack: Vec::new(),
            remaining: tree.len(),
        };
        if let Some(ref root) = tree.root {
            iter.push_left_edge(root);
        }
        iter
    }

    fn push_left_edge(&mut self, mut node: &'a Node<K, V>) {
        loop {
            self.stack.push(IterFrame { node, index: 0 });
            if let Some(first_child) = node.children.first() {
                node = first_child;
            } else {
                break;
            }
        }
    }
}

impl<'a, K, V> Iterator for Iter<'a, K, V> {
    type Item = (&'a K, &'a V);

    fn next(&mut self) -> Option<Self::Item> {
        while let Some(frame) = self.stack.last_mut() {
            let idx = frame.index;
            if idx < frame.node.keys.len() {
                let key = &frame.node.keys[idx];
                let val = &frame.node.values[idx];
                frame.index += 1;

                if !frame.node.is_leaf() {
                    let next_child = &frame.node.children[idx + 1];
                    self.push_left_edge(next_child);
                }

                if self.remaining > 0 {
                    self.remaining -= 1;
                }
                return Some((key, val));
            }
            self.stack.pop();
        }
        None
    }

    #[inline]
    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}

impl<K, V> ExactSizeIterator for Iter<'_, K, V> {
    #[inline]
    fn len(&self) -> usize {
        self.remaining
    }
}

impl<'a, K, V, const B: usize> IntoIterator for &'a BTreeMap<K, V, B> {
    type Item = (&'a K, &'a V);
    type IntoIter = Iter<'a, K, V>;

    #[inline]
    fn into_iter(self) -> Self::IntoIter {
        self.iter()
    }
}

// ============================================================================
// Itérateur par référence mutable : IterMut<'a, K, V>
// ============================================================================

/// Itérateur empruntant de façon mutable les valeurs d'un [`BTreeMap`].
pub struct IterMut<'a, K, V> {
    items: std::vec::IntoIter<(&'a K, &'a mut V)>,
}

impl<'a, K, V> IterMut<'a, K, V> {
    fn new<const B: usize>(tree: &'a mut BTreeMap<K, V, B>) -> Self {
        let mut list = Vec::with_capacity(tree.len());
        if let Some(ref mut root) = tree.root {
            Self::collect_in_order(root, &mut list);
        }
        Self {
            items: list.into_iter(),
        }
    }

    fn collect_in_order(node: &'a mut Node<K, V>, list: &mut Vec<(&'a K, &'a mut V)>) {
        if node.is_leaf() {
            let Node { keys, values, .. } = node;
            for (k, v) in keys.iter().zip(values.iter_mut()) {
                list.push((k, v));
            }
        } else {
            let Node {
                keys,
                values,
                children,
            } = node;

            let mut child_iter = children.iter_mut();
            let mut key_iter = keys.iter();
            let mut val_iter = values.iter_mut();

            if let Some(first_child) = child_iter.next() {
                Self::collect_in_order(first_child, list);
            }

            while let (Some(k), Some(v)) = (key_iter.next(), val_iter.next()) {
                list.push((k, v));
                if let Some(child) = child_iter.next() {
                    Self::collect_in_order(child, list);
                }
            }
        }
    }
}

impl<'a, K, V> Iterator for IterMut<'a, K, V> {
    type Item = (&'a K, &'a mut V);

    #[inline]
    fn next(&mut self) -> Option<Self::Item> {
        self.items.next()
    }

    #[inline]
    fn size_hint(&self) -> (usize, Option<usize>) {
        self.items.size_hint()
    }
}

impl<K, V> ExactSizeIterator for IterMut<'_, K, V> {
    #[inline]
    fn len(&self) -> usize {
        self.items.len()
    }
}

impl<'a, K, V, const B: usize> IntoIterator for &'a mut BTreeMap<K, V, B> {
    type Item = (&'a K, &'a mut V);
    type IntoIter = IterMut<'a, K, V>;

    #[inline]
    fn into_iter(self) -> Self::IntoIter {
        self.iter_mut()
    }
}

// ============================================================================
// Itérateur par valeur : IntoIter<K, V>
// ============================================================================

enum IntoIterStep<K, V> {
    VisitNode(Node<K, V>),
    Yield(K, V),
}

/// Itérateur consommant un [`BTreeMap`] pour en extraire ses paires clé-valeur.
pub struct IntoIter<K, V> {
    stack: Vec<IntoIterStep<K, V>>,
    remaining: usize,
}

impl<K, V> IntoIter<K, V> {
    fn new<const B: usize>(mut tree: BTreeMap<K, V, B>) -> Self {
        let remaining = tree.len();
        let mut stack = Vec::new();
        if let Some(root) = tree.root.take() {
            stack.push(IntoIterStep::VisitNode(root));
        }
        Self { stack, remaining }
    }
}

impl<K, V> Iterator for IntoIter<K, V> {
    type Item = (K, V);

    fn next(&mut self) -> Option<Self::Item> {
        while let Some(step) = self.stack.pop() {
            match step {
                IntoIterStep::Yield(k, v) => {
                    if self.remaining > 0 {
                        self.remaining -= 1;
                    }
                    return Some((k, v));
                }
                IntoIterStep::VisitNode(mut node) => {
                    if node.is_leaf() {
                        while let (Some(k), Some(v)) = (node.keys.pop(), node.values.pop()) {
                            self.stack.push(IntoIterStep::Yield(k, v));
                        }
                    } else {
                        if let Some(last_child) = node.children.pop() {
                            self.stack.push(IntoIterStep::VisitNode(last_child));
                        }
                        while let (Some(k), Some(v)) = (node.keys.pop(), node.values.pop()) {
                            self.stack.push(IntoIterStep::Yield(k, v));
                            if let Some(child) = node.children.pop() {
                                self.stack.push(IntoIterStep::VisitNode(child));
                            }
                        }
                    }
                }
            }
        }
        None
    }

    #[inline]
    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}

impl<K, V> ExactSizeIterator for IntoIter<K, V> {
    #[inline]
    fn len(&self) -> usize {
        self.remaining
    }
}

impl<K, V, const B: usize> IntoIterator for BTreeMap<K, V, B> {
    type Item = (K, V);
    type IntoIter = IntoIter<K, V>;

    #[inline]
    fn into_iter(self) -> Self::IntoIter {
        IntoIter::new(self)
    }
}

// ============================================================================
// FromIterator et Extend
// ============================================================================

impl<K: Ord, V, const B: usize> FromIterator<(K, V)> for BTreeMap<K, V, B> {
    fn from_iter<T: IntoIterator<Item = (K, V)>>(iter: T) -> Self {
        let mut map = Self::new();
        map.extend(iter);
        map
    }
}

impl<K: Ord, V, const B: usize> Extend<(K, V)> for BTreeMap<K, V, B> {
    fn extend<T: IntoIterator<Item = (K, V)>>(&mut self, iter: T) {
        for (k, v) in iter {
            self.insert(k, v);
        }
    }
}

// ============================================================================
// Programme principal et démonstrations
// ============================================================================

fn main() {
    println!("=== Initialisation du B-Tree en mémoire (B = 3) ===");
    let mut tree: BTreeMap<i32, String> = BTreeMap::new();

    // Insertion d'un jeu de données non trié pour tester les éclatements de nœuds
    let sample = [
        (42, "quarante-deux"),
        (10, "dix"),
        (7, "sept"),
        (100, "cent"),
        (25, "vingt-cinq"),
        (3, "trois"),
        (50, "cinquante"),
        (1, "un"),
        (80, "quatre-vingts"),
        (90, "quatre-vingt-dix"),
        (15, "quinze"),
    ];

    for (k, v) in sample {
        tree.insert(k, v.to_string());
    }

    println!("Nombre d'éléments : {}", tree.len());
    println!("Contient la clé 25 : {}", tree.contains_key(&25));
    if let Some(val) = tree.get(&42) {
        println!("Valeur pour la clé 42 : {val}");
    }

    // 1. Parcours via IntoIterator (&BTreeMap)
    println!("\n--- 1. Parcours par référence immuable (&tree) ---");
    for (k, v) in &tree {
        print!("({k}: {v}) ");
    }
    println!();

    // 2. Modification in-place via IntoIterator (&mut BTreeMap)
    println!("\n--- 2. Modification par référence mutable (&mut tree) ---");
    for (k, v) in &mut tree {
        if *k % 2 == 0 {
            v.push_str(" [pair]");
        }
    }

    for (k, v) in tree.iter() {
        print!("({k}: {v}) ");
    }
    println!();

    // 3. Collecte via FromIterator
    println!("\n--- 3. Création par FromIterator (collect) ---");
    let pairs = vec![(5, "cinq"), (2, "deux"), (8, "huit"), (1, "premier")];
    let collected_tree: BTreeMap<i32, &str> = pairs.into_iter().collect();
    for (k, v) in &collected_tree {
        print!("({k}: {v}) ");
    }
    println!();

    // 4. Consommation via IntoIterator (par valeur)
    println!("\n--- 4. Consommation complète par valeur (into_iter) ---");
    let total_elements = tree.len();
    let mut count = 0;
    for (k, v) in tree {
        count += 1;
        print!("({k}: {v}) ");
    }
    println!("\nÉléments consommés : {count} / {total_elements}");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_insertion_and_ordering() {
        let mut map: BTreeMap<i32, i32, 2> = BTreeMap::new();
        let data = [15, 3, 8, 22, 1, 9, 10, 4, 12, 17, 2, 5];
        for &x in &data {
            map.insert(x, x * 10);
        }

        assert_eq!(map.len(), data.len());

        let keys: Vec<i32> = map.iter().map(|(&k, _)| k).collect();
        let mut sorted_data = data;
        sorted_data.sort_unstable();
        assert_eq!(keys, sorted_data);

        for &x in &data {
            assert_eq!(map.get(&x), Some(&(x * 10)));
        }
        assert_eq!(map.get(&999), None);
    }

