        assert_eq!(map.insert(1, "un"), None);
        assert_eq!(map.len(), 1);

        assert_eq!(map.insert(1, "premier"), Some("un"));
        assert_eq!(map.len(), 1);
        assert_eq!(map.get(&1), Some(&"premier"));
    }

