        let mut map: BTreeMap<i32, i32> = (0..20).map(|i| (i, i)).collect();
        for (_k, v) in &mut map {
            *v += 100;
        }

        for (k, v) in &map {
            assert_eq!(*v, *k + 100);
        }
    }
