// src/main.rs
//! Serveur UDP de synchronisation d'horloge NTP simplifié en Rust natif.
//!
//! Conforme aux principes de base de SNTP (RFC 4330 / RFC 5905).
//! N'utilise que la bibliothèque standard Rust : `std::net::UdpSocket` et `std::time::SystemTime`.

use std::env;
use std::io;
use std::net::UdpSocket;
use std::time::{SystemTime, UNIX_EPOCH};

/// Taille standard d'un paquet NTPv4 minimal en octets.
pub const NTP_PACKET_SIZE: usize = 48;

/// Nombre de secondes entre l'époque NTP (1er janvier 1900) et l'époque Unix (1er janvier 1970).
/// 70 ans (dont 17 années bissextiles) = (70 * 365 + 17) * 86400 = 2 208 988 800 secondes.
pub const NTP_TO_UNIX_SECONDS: u64 = 2_208_988_800;

/// Représentation d'un timestamp NTP (64 bits : 32 bits secondes + 32 bits fraction).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct NtpTimestamp {
    pub seconds: u32,
    pub fraction: u32,
}

impl NtpTimestamp {
    /// Convertit un [`SystemTime`] en [`NtpTimestamp`].
    pub fn from_system_time(time: SystemTime) -> Self {
        match time.duration_since(UNIX_EPOCH) {
            Ok(duration) => {
                let ntp_secs = duration.as_secs().saturating_add(NTP_TO_UNIX_SECONDS);
                let seconds = (ntp_secs & 0xFFFF_FFFF) as u32;
                // Fraction 32-bit : subsecondes / 1 seconde * 2^32
                // as_nanos() * 2^32 / 1_000_000_000
                let nanos = duration.subsec_nanos() as u64;
                let fraction = ((nanos << 32) / 1_000_000_000) as u32;
                Self { seconds, fraction }
            }
            Err(_) => {
                // Si l'heure système est antérieure à 1970, renvoyer zéro
                Self {
                    seconds: 0,
                    fraction: 0,
                }
            }
        }
    }

    /// Écrit le timestamp dans un buffer binaire (8 octets, big-endian).
    pub fn write_to(&self, buf: &mut [u8; 8]) {
        buf[0..4].copy_from_slice(&self.seconds.to_be_bytes());
        buf[4..8].copy_from_slice(&self.fraction.to_be_bytes());
    }

    /// Lit un timestamp à partir d'une tranche de 8 octets big-endian.
    pub fn read_from(slice: &[u8]) -> Self {
        if slice.len() < 8 {
            return Self::default();
        }
        let mut s_bytes = [0u8; 4];
        let mut f_bytes = [0u8; 4];
        s_bytes.copy_from_slice(&slice[0..4]);
        f_bytes.copy_from_slice(&slice[4..8]);
        Self {
            seconds: u32::from_be_bytes(s_bytes),
            fraction: u32::from_be_bytes(f_bytes),
        }
    }
}

/// Structure d'un en-tête de paquet NTPv4 standard (48 octets).
#[derive(Debug, Clone)]
pub struct NtpPacket {
    pub leap_indicator: u8,
    pub version: u8,
    pub mode: u8,
    pub stratum: u8,
    pub poll: i8,
    pub precision: i8,
    pub root_delay: u32,
    pub root_dispersion: u32,
    pub reference_id: [u8; 4],
    pub reference_timestamp: NtpTimestamp,
    pub origin_timestamp: NtpTimestamp,
    pub receive_timestamp: NtpTimestamp,
    pub transmit_timestamp: NtpTimestamp,
}

impl NtpPacket {
    /// Analyse un paquet brut de 48 octets.
    pub fn parse(buf: &[u8]) -> Result<Self, &'static str> {
        if buf.len() < NTP_PACKET_SIZE {
            return Err("Taille du paquet insuffisante pour un en-tête NTP");
        }

        let first_byte = buf[0];
        let leap_indicator = (first_byte >> 6) & 0x03;
        let version = (first_byte >> 3) & 0x07;
        let mode = first_byte & 0x07;

        let stratum = buf[1];
        let poll = buf[2] as i8;
        let precision = buf[3] as i8;

        let mut root_delay_bytes = [0u8; 4];
        root_delay_bytes.copy_from_slice(&buf[4..8]);
        let root_delay = u32::from_be_bytes(root_delay_bytes);

        let mut root_dispersion_bytes = [0u8; 4];
        root_dispersion_bytes.copy_from_slice(&buf[8..12]);
        let root_dispersion = u32::from_be_bytes(root_dispersion_bytes);

        let mut reference_id = [0u8; 4];
        reference_id.copy_from_slice(&buf[12..16]);

        let reference_timestamp = NtpTimestamp::read_from(&buf[16..24]);
        let origin_timestamp = NtpTimestamp::read_from(&buf[24..32]);
        let receive_timestamp = NtpTimestamp::read_from(&buf[32..40]);
        let transmit_timestamp = NtpTimestamp::read_from(&buf[40..48]);

        Ok(Self {
            leap_indicator,
            version,
            mode,
            stratum,
            poll,
            precision,
            root_delay,
            root_dispersion,
            reference_id,
            reference_timestamp,
            origin_timestamp,
            receive_timestamp,
            transmit_timestamp,
        })
    }

    /// Sérialise le paquet en un buffer de 48 octets.
    pub fn serialize(&self) -> [u8; NTP_PACKET_SIZE] {
        let mut buf = [0u8; NTP_PACKET_SIZE];

        // Premier octet : LI (2b) | VN (3b) | Mode (3b)
        buf[0] = ((self.leap_indicator & 0x03) << 6)
            | ((self.version & 0x07) << 3)
            | (self.mode & 0x07);

        buf[1] = self.stratum;
        buf[2] = self.poll as u8;
        buf[3] = self.precision as u8;

        buf[4..8].copy_from_slice(&self.root_delay.to_be_bytes());
        buf[8..12].copy_from_slice(&self.root_dispersion.to_be_bytes());
        buf[12..16].copy_from_slice(&self.reference_id);

        let mut ts_buf = [0u8; 8];
        self.reference_timestamp.write_to(&mut ts_buf);
        buf[16..24].copy_from_slice(&ts_buf);

        self.origin_timestamp.write_to(&mut ts_buf);
        buf[24..32].copy_from_slice(&ts_buf);

        self.receive_timestamp.write_to(&mut ts_buf);
        buf[32..40].copy_from_slice(&ts_buf);

        self.transmit_timestamp.write_to(&mut ts_buf);
        buf[40..48].copy_from_slice(&ts_buf);

        buf
    }

    /// Construit une réponse SNTP (Mode 4 = Serveur) à partir d'une requête client (Mode 3).
    pub fn build_response(
        client_packet: &Self,
        recv_time: SystemTime,
        transmit_time: SystemTime,
    ) -> Self {
        // En SNTP :
        // LI = 0 (pas de saut), VN = version du client (ou 4), Mode = 4 (serveur)
        let version = if client_packet.version >= 3 && client_packet.version <= 4 {
            client_packet.version
        } else {
            4
        };

        let recv_ts = NtpTimestamp::from_system_time(recv_time);
        let transmit_ts = NtpTimestamp::from_system_time(transmit_time);

        Self {
            leap_indicator: 0,
            version,
            mode: 4, // Serveur
            stratum: 1, // Serveur primaire / local clock
            poll: client_packet.poll,
            precision: -20, // ~1 microseconde (2^-20 s)
            root_delay: 0,
            root_dispersion: 100, // Déviation minime nominale
            reference_id: *b"LOCL", // Uncalibrated local clock
            reference_timestamp: recv_ts,
            // Origin timestamp dans la réponse doit être égal au Transmit Timestamp de la requête client
            origin_timestamp: client_packet.transmit_timestamp,
            receive_timestamp: recv_ts,
            transmit_timestamp: transmit_ts,
        }
    }
}

/// Démarre le serveur NTP sur l'adresse spécifiée.
pub fn run_server(bind_addr: &str) -> io::Result<()> {
    let socket = UdpSocket::bind(bind_addr)?;
    println!("[INFO] Serveur NTP actif et à l'écoute sur {}", bind_addr);

    let mut buf = [0u8; 1024];

    loop {
        let (bytes_received, src_addr) = match socket.recv_from(&mut buf) {
            Ok(res) => res,
            Err(e) => {
                eprintln!("[WARN] Échec lors de la réception d'un paquet : {}", e);
                continue;
            }
        };

        // Capture immédiate du Receive Timestamp (T2)
        let recv_time = SystemTime::now();

        if bytes_received < NTP_PACKET_SIZE {
            eprintln!(
                "[WARN] Paquet reçu de {} ignoré : taille invalide ({} octets < {})",
                src_addr, bytes_received, NTP_PACKET_SIZE
            );
            continue;
        }

        match NtpPacket::parse(&buf[..bytes_received]) {
            Ok(client_req) => {
                // On ne répond qu'aux requêtes en mode Client (Mode 3)
                if client_req.mode != 3 {
                    eprintln!(
                        "[DEBUG] Paquet de {} ignoré : mode {} != 3 (Client)",
                        src_addr, client_req.mode
                    );
                    continue;
                }

                // Capture du Transmit Timestamp (T3) juste avant sérialisation et envoi
                let transmit_time = SystemTime::now();
                let response = NtpPacket::build_response(&client_req, recv_time, transmit_time);
                let response_bytes = response.serialize();

                if let Err(e) = socket.send_to(&response_bytes, src_addr) {
                    eprintln!("[ERROR] Impossible d'envoyer la réponse à {} : {}", src_addr, e);
                } else {
                    println!(
                        "[INFO] Réponse NTP envoyée à {} (v{}, T3 sec: {})",
                        src_addr, response.version, response.transmit_timestamp.seconds
                    );
                }
            }
            Err(err) => {
                eprintln!("[WARN] Erreur de parsing du paquet de {} : {}", src_addr, err);
            }
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    // Par défaut sur le port 1123 pour exécution sans droits root, ou 123 si spécifié
    let bind_addr = if args.len() > 1 {
        args[1].as_str()
    } else {
        "0.0.0.0:1123"
    };

