use std::env;
use std::io;
use std::net::UdpSocket;
use std::time::{SystemTime, UNIX_EPOCH};

/// Taille standard d'un paquet NTPv4 minimal en octets.
pub const NTP_PACKET_SIZE: usize = 48;

/// Nombre de secondes entre l'époque NTP (1er janvier 1900) et l'époque Unix (1er janvier 1970).
/// 70 ans (dont 17 années bissextiles) = (70 * 365 + 17) * 86400 = 2 208 988 800 secondes.
pub const NTP_TO_UNIX_SECONDS: u64 = 2_208_988_800;

/// Représentation d'un timestamp NTP (64 bits : 32 bits secondes + 32 bits fraction).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct NtpTimestamp {
    pub seconds: u32,
    pub fraction: u32,
}

impl NtpTimestamp {
    /// Convertit un [`SystemTime`] en [`NtpTimestamp`].
    pub fn from_system_time(time: SystemTime) -> Self {
        match time.duration_since(UNIX_EPOCH) {
            Ok(duration) => {
                let ntp_secs = duration.as_secs().saturating_add(NTP_TO_UNIX_SECONDS);
                let seconds = (ntp_secs & 0xFFFF_FFFF) as u32;
                // Fraction 32-bit : subsecondes / 1 seconde * 2^32
                // as_nanos() * 2^32 / 1_000_000_000
                let nanos = duration.subsec_nanos() as u64;
                let fraction = ((nanos << 32) / 1_000_000_000) as u32;
                Self { seconds, fraction }
            }
            Err(_) => {
                // Si l'heure système est antérieure à 1970, renvoyer zéro
                Self {
                    seconds: 0,
                    fraction: 0,
                }
            }
        }
    }

    /// Écrit le timestamp dans un buffer binaire (8 octets, big-endian).
    pub fn write_to(&self, buf: &mut [u8; 8]) {
        buf[0..4].copy_from_slice(&self.seconds.to_be_bytes());
        buf[4..8].copy_from_slice(&self.fraction.to_be_bytes());
    }

    /// Lit un timestamp à partir d'une tranche de 8 octets big-endian.
    pub fn read_from(slice: &[u8]) -> Self {
        if slice.len() < 8 {
            return Self::default();
        }
        let mut s_bytes = [0u8; 4];
        let mut f_bytes = [0u8; 4];
        s_bytes.copy_from_slice(&slice[0..4]);
        f_bytes.copy_from_slice(&slice[4..8]);
        Self {
            seconds: u32::from_be_bytes(s_bytes),
            fraction: u32::from_be_bytes(f_bytes),
        }
    }
}

