// src/main.rs
//! Client HTTP/1.1 minimaliste sans dépendance externe.
//! Conçu avec `std::net::TcpStream` et `std::io::BufReader`.

use std::collections::HashMap;
use std::error::Error;
use std::fmt;
use std::io::{self, BufRead, BufReader, Read, Write};
use std::net::{TcpListener, TcpStream, ToSocketAddrs};
use std::thread;
use std::time::Duration;

/// Erreurs spécifiques au client HTTP.
#[derive(Debug)]
pub enum HttpError {
    Io(io::Error),
    InvalidUrl(String),
    UnsupportedScheme(String),
    HostResolutionFailed(String),
    InvalidStatusLine(String),
    InvalidHeader(String),
    InvalidChunkSize(String),
    Utf8Error(std::string::FromUtf8Error),
    ParseIntError(std::num::ParseIntError),
}

impl fmt::Display for HttpError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            HttpError::Io(err) => write!(f, "Erreur d'E/S réseau : {err}"),
            HttpError::InvalidUrl(msg) => write!(f, "URL invalide : {msg}"),
            HttpError::UnsupportedScheme(scheme) => {
                write!(f, "Protocole non supporté '{scheme}'. Seul http:// est supporté sans dépendance TLS")
            }
            HttpError::HostResolutionFailed(host) => write!(f, "Impossible de résoudre l'hôte : {host}"),
            HttpError::InvalidStatusLine(line) => write!(f, "Ligne de statut HTTP invalide : {line}"),
            HttpError::InvalidHeader(header) => write!(f, "En-tête HTTP invalide : {header}"),
            HttpError::InvalidChunkSize(size) => write!(f, "Taille de chunk hexadécimale invalide : {size}"),
            HttpError::Utf8Error(err) => write!(f, "Erreur de décodage UTF-8 : {err}"),
            HttpError::ParseIntError(err) => write!(f, "Erreur de conversion numérique : {err}"),
        }
    }
}

impl Error for HttpError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            HttpError::Io(err) => Some(err),
            HttpError::Utf8Error(err) => Some(err),
            HttpError::ParseIntError(err) => Some(err),
            _ => None,
        }
    }
}

impl From<io::Error> for HttpError {
    fn from(err: io::Error) -> Self {
        HttpError::Io(err)
    }
}

impl From<std::string::FromUtf8Error> for HttpError {
    fn from(err: std::string::FromUtf8Error) -> Self {
        HttpError::Utf8Error(err)
    }
}

impl From<std::num::ParseIntError> for HttpError {
    fn from(err: std::num::ParseIntError) -> Self {
        HttpError::ParseIntError(err)
    }
}

/// Méthodes HTTP supportées.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum HttpMethod {
    Get,
    Post,
    Put,
    Delete,
    Head,
    Custom(String),
}

impl HttpMethod {
    pub fn as_str(&self) -> &str {
        match self {
            HttpMethod::Get => "GET",
            HttpMethod::Post => "POST",
            HttpMethod::Put => "PUT",
            HttpMethod::Delete => "DELETE",
            HttpMethod::Head => "HEAD",
            HttpMethod::Custom(s) => s.as_str(),
        }
    }
}

/// Structure représentant une URL découpée.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParsedUrl {
    pub host: String,
    pub port: u16,
    pub path_and_query: String,
}

impl ParsedUrl {
    /// Analyse une URL HTTP simple (ex: `http://example.com:8080/index.html?a=1`).
    pub fn parse(raw_url: &str) -> Result<Self, HttpError> {
        let after_scheme = if let Some(stripped) = raw_url.strip_prefix("http://") {
            stripped
        } else if raw_url.starts_with("https://") {
            return Err(HttpError::UnsupportedScheme("https".to_string()));
        } else {
            return Err(HttpError::InvalidUrl("L'URL doit commencer par 'http://'".to_string()));
        };

        if after_scheme.is_empty() {
            return Err(HttpError::InvalidUrl("Hôte manquant".to_string()));
        }

        let (authority, path_and_query) = match after_scheme.find('/') {
            Some(idx) => (&after_scheme[..idx], &after_scheme[idx..]),
            None => (after_scheme, "/"),
        };

        if authority.is_empty() {
            return Err(HttpError::InvalidUrl("Hôte vide".to_string()));
        }

        let (host, port) = match authority.find(':') {
            Some(colon_idx) => {
                let h = &authority[..colon_idx];
                let p_str = &authority[colon_idx + 1..];
                let p: u16 = p_str
                    .parse()
                    .map_err(|_| HttpError::InvalidUrl(format!("Port invalide '{p_str}'")))?;
                (h.to_string(), p)
            }
            None => (authority.to_string(), 80),
        };

        let path_and_query = if path_and_query.is_empty() {
            "/".to_string()
        } else {
            path_and_query.to_string()
        };

        Ok(ParsedUrl {
            host,
            port,
            path_and_query,
        })
    }
}

/// Représentation d'une requête HTTP.
#[derive(Debug, Clone)]
pub struct HttpRequest {
    pub method: HttpMethod,
    pub url: String,
    pub headers: HashMap<String, String>,
    pub body: Option<Vec<u8>>,
    pub timeout: Option<Duration>,
}

impl HttpRequest {
    pub fn new(method: HttpMethod, url: &str) -> Self {
        Self {
            method,
            url: url.to_string(),
            headers: HashMap::new(),
            body: None,
            timeout: Some(Duration::from_secs(10)),
        }
    }

    pub fn header(mut self, key: &str, value: &str) -> Self {
        self.headers.insert(key.to_string(), value.to_string());
        self
    }

    pub fn body(mut self, body: Vec<u8>) -> Self {
        self.body = Some(body);
        self
    }

    pub fn timeout(mut self, timeout: Duration) -> Self {
        self.timeout = Some(timeout);
        self
    }
}

/// Représentation d'une réponse HTTP.
#[derive(Debug, Clone)]
pub struct HttpResponse {
    pub status_code: u16,
    pub reason_phrase: String,
    pub headers: HashMap<String, String>,
    pub body: Vec<u8>,
}

impl HttpResponse {
    /// Retourne la valeur d'un en-tête de manière insensible à la casse.
    pub fn header(&self, name: &str) -> Option<&str> {
        let search_key = name.to_ascii_lowercase();
        self.headers.get(&search_key).map(String::as_str)
    }

    /// Tente de convertir le corps de réponse en chaîne UTF-8.
    pub fn text(&self) -> Result<String, HttpError> {
        String::from_utf8(self.body.clone()).map_err(HttpError::Utf8Error)
    }
}

/// Client HTTP/1.1 minimaliste et réutilisable.
#[derive(Debug, Default)]
pub struct HttpClient {
    default_timeout: Option<Duration>,
}

impl HttpClient {
    pub fn new() -> Self {
        Self {
            default_timeout: Some(Duration::from_secs(10)),
        }
    }

    /// Effectue une requête HTTP GET vers l'URL indiquée.
    pub fn get(&self, url: &str) -> Result<HttpResponse, HttpError> {
        let req = HttpRequest::new(HttpMethod::Get, url);
        self.send(&req)
    }

    /// Effectue une requête HTTP POST avec un corps et un type MIME.
    pub fn post(&self, url: &str, body: Vec<u8>, content_type: &str) -> Result<HttpResponse, HttpError> {
        let req = HttpRequest::new(HttpMethod::Post, url)
            .header("Content-Type", content_type)
            .body(body);
        self.send(&req)
    }

    /// Envoie une requête HTTP et analyse la réponse retournée.
    pub fn send(&self, request: &HttpRequest) -> Result<HttpResponse, HttpError> {
        let parsed_url = ParsedUrl::parse(&request.url)?;
        let timeout = request.timeout.or(self.default_timeout);

        let address_str = format!("{}:{}", parsed_url.host, parsed_url.port);
        let socket_addrs = address_str
            .to_socket_addrs()
            .map_err(|_| HttpError::HostResolutionFailed(parsed_url.host.clone()))?;

        // Tentative de connexion avec timeout optionnel
        let mut stream = match timeout {
            Some(t) => {
                let mut connected_stream = None;
                for addr in socket_addrs {
                    if let Ok(s) = TcpStream::connect_timeout(&addr, t) {
                        connected_stream = Some(s);
                        break;
                    }
                }
                connected_stream.ok_or_else(|| {
                    io::Error::new(io::ErrorKind::ConnectionRefused, "Échec de connexion aux adresses résolues")
                })?
            }
            None => TcpStream::connect(&address_str)?,
        };

        if let Some(t) = timeout {
            let _ = stream.set_read_timeout(Some(t));
            let _ = stream.set_write_timeout(Some(t));
        }

        // 1. Émission de la requête HTTP
        let mut request_bytes = Vec::new();

        // Ligne de commande : METHOD <target> HTTP/1.1
        request_bytes.extend_from_slice(
            format!(
                "{} {} HTTP/1.1\r\n",
                request.method.as_str(),
                parsed_url.path_and_query
            )
            .as_bytes(),
        );

        // Host obligatoire en HTTP/1.1
        let host_header_val = if parsed_url.port == 80 {
            parsed_url.host.clone()
        } else {
            format!("{}:{}", parsed_url.host, parsed_url.port)
        };
        request_bytes.extend_from_slice(format!("Host: {host_header_val}\r\n").as_bytes());

        // Connection: close par défaut pour faciliter la gestion du cycle de vie
        let mut has_connection = false;
        let mut has_content_length = false;

        for (k, v) in &request.headers {
            if k.eq_ignore_ascii_case("connection") {
                has_connection = true;
            }
            if k.eq_ignore_ascii_case("content-length") {
                has_content_length = true;
            }
            request_bytes.extend_from_slice(format!("{k}: {v}\r\n").as_bytes());
        }

        if !has_connection {
            request_bytes.extend_from_slice(b"Connection: close\r\n");
        }

        if let Some(body) = &request.body {
            if !has_content_length {
                request_bytes.extend_from_slice(format!("Content-Length: {}\r\n", body.len()).as_bytes());
            }
        } else if request.method == HttpMethod::Post || request.method == HttpMethod::Put {
            if !has_content_length {
                request_bytes.extend_from_slice(b"Content-Length: 0\r\n");
            }
        }

        request_bytes.extend_from_slice(b"User-Agent: MinimalRustHttpClient/1.0\r\n\r\n");

        if let Some(body) = &request.body {
            request_bytes.extend_from_slice(body);
        }

        stream.write_all(&request_bytes)?;
        stream.flush()?;

        // 2. Réception et analyse de la réponse avec BufReader
        let mut reader = BufReader::new(stream);

        // Lecture de la ligne de statut
        let mut status_line = String::new();
        reader.read_line(&mut status_line)?;
        let trimmed_status = status_line.trim_end_matches(['\r', '\n']);
        if trimmed_status.is_empty() {
            return Err(HttpError::InvalidStatusLine(
                "Réponse vide ou connexion prématurément fermée par le serveur".to_string(),
            ));
        }

        let mut parts = trimmed_status.splitn(3, ' ');
        let _http_version = parts
            .next()
            .ok_or_else(|| HttpError::InvalidStatusLine(trimmed_status.to_string()))?;
        let status_code_str = parts
            .next()
            .ok_or_else(|| HttpError::InvalidStatusLine(trimmed_status.to_string()))?;
        let reason_phrase = parts.next().unwrap_or("").to_string();

        let status_code: u16 = status_code_str
            .parse()
            .map_err(|_| HttpError::InvalidStatusLine(format!("Code statut non numérique: '{status_code_str}'")))?;

        // Lecture des en-têtes
        let mut headers = HashMap::new();
        loop {
            let mut line = String::new();
            let bytes_read = reader.read_line(&mut line)?;
            if bytes_read == 0 {
                break;
            }
            let trimmed = line.trim_end_matches(['\r', '\n']);
            if trimmed.is_empty() {
                // Fin des en-têtes (ligne vide \r\n)
                break;
            }

            if let Some((name, val)) = trimmed.split_once(':') {
                headers.insert(name.trim().to_ascii_lowercase(), val.trim().to_string());
            } else {
                return Err(HttpError::InvalidHeader(trimmed.to_string()));
            }
        }

        // Lecture du corps selon les spécifications HTTP
        let mut body = Vec::new();
        let is_chunked = headers
            .get("transfer-encoding")
            .map(|v| v.to_ascii_lowercase().contains("chunked"))
            .unwrap_or(false);

        if is_chunked {
            Self::read_chunked_body(&mut reader, &mut body)?;
        } else if let Some(content_length_str) = headers.get("content-length") {
            let content_length: usize = content_length_str.parse().map_err(HttpError::ParseIntError)?;
            body.resize(content_length, 0);
            reader.read_exact(&mut body)?;
        } else {
            // Pas de Content-Length ni de chunked : lecture jusqu'à fermeture de la connexion (EOF)
            reader.read_to_end(&mut body)?;
        }

        Ok(HttpResponse {
            status_code,
            reason_phrase,
            headers,
            body,
        })
    }

    /// Décode le corps au format Transfer-Encoding: chunked.
    fn read_chunked_body<R: BufRead>(reader: &mut R, body: &mut Vec<u8>) -> Result<(), HttpError> {
        loop {
            let mut size_line = String::new();
            let bytes_read = reader.read_line(&mut size_line)?;
            if bytes_read == 0 {
                break;
            }
            let trimmed = size_line.trim_end_matches(['\r', '\n']).trim();
            if trimmed.is_empty() {
                continue;
            }

            // Gestion d'éventuelles extensions de chunks (séparateur ';')
            let hex_size = match trimmed.split_once(';') {
                Some((clean_hex, _)) => clean_hex.trim(),
                None => trimmed,
            };

            let chunk_size = usize::from_str_radix(hex_size, 16)
                .map_err(|_| HttpError::InvalidChunkSize(hex_size.to_string()))?;

            if chunk_size == 0 {
                // Chunk terminal (0\r\n). On ignore les trailers éventuels jusqu'à la ligne vide finale.
                let mut trailer_line = String::new();
                loop {
                    trailer_line.clear();
                    let n = reader.read_line(&mut trailer_line)?;
                    if n == 0 || trailer_line.trim_end_matches(['\r', '\n']).is_empty() {
                        break;
                    }
                }
                break;
            }

            let start = body.len();
            body.resize(start + chunk_size, 0);
            reader.read_exact(&mut body[start..])?;

            // Consommer le délimiteur \r\n obligatoire après chaque chunk
            let mut crlf = [0u8; 2];
            reader.read_exact(&mut crlf)?;
        }
        Ok(())
    }
}

fn main() {
    println!("=== Client HTTP/1.1 Minimaliste en Rust (Standard Library) ===");

    // Analyse des arguments en ligne de commande éventuels
    let args: Vec<String> = std::env::args().collect();
    let client = HttpClient::new();

    if args.len() > 1 {
