                     Content-Type: application/json; charset=utf-8\r\n\
                     Content-Length: {}\r\n\
                     Connection: close\r\n\
                     Server: DemoServer/1.0\r\n\
                     \r\n\
                     {}",
                    response_body.len(),
                    response_body
                );
                let _ = reader.get_mut().write_all(response.as_bytes());
                let _ = reader.get_mut().flush();
            }
        });

        let test_url = format!("http://{local_addr}/api/demo");
        println!("Envoi d'une requête GET vers : {test_url}");

        match client.get(&test_url) {
            Ok(response) => {
                println!("\n[RÉPONSE REÇUE]");
                println!("Statut : {} {}", response.status_code, response.reason_phrase);
                println!("En-têtes :");
                for (k, v) in &response.headers {
