                }
            }
            Err(e) => {
                eprintln!("Erreur du client : {e}");
            }
        }

        let _ = server_handle.join();
        println!("\nDémonstration terminée avec succès !");
        println!("Astuce : Vous pouvez aussi lancer le binaire avec une URL personnalisée :");
        println!("  cargo run -- http://httpbin.org/get");
    }
