// src/main.rs
use std::collections::VecDeque;
use std::fmt;
use std::sync::{Arc, Condvar, Mutex};
use std::thread::{self, JoinHandle};

/// Type alias pour une unité de travail envoyée au pool.
type Task = Box<dyn FnOnce() + Send + 'static>;

/// Erreurs possibles lors de la manipulation du ThreadPool.
#[derive(Debug, PartialEq, Eq, Clone, Copy)]
pub enum ThreadPoolError {
    /// Le nombre de threads doit être strictement positif.
    ZeroThreads,
}

impl fmt::Display for ThreadPoolError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ThreadPoolError::ZeroThreads => {
                write!(f, "Le nombre de threads doit être strictement supérieur à zéro.")
            }
        }
    }
}

impl std::error::Error for ThreadPoolError {}

/// État interne partagé protégé par le `Mutex`.
struct State {
    queue: VecDeque<Task>,
    is_shutdown: bool,
}

/// Structure de coordination partagée entre le pool et les workers.
struct Shared {
    state: Mutex<State>,
    condvar: Condvar,
}

/// Représente un worker dédié à l'exécution des tâches.
struct Worker {
    _id: usize,
    handle: Option<JoinHandle<()>>,
}

impl Worker {
    fn new(id: usize, shared: Arc<Shared>) -> Self {
        let handle = thread::Builder::new()
            .name(format!("worker-{}", id))
            .spawn(move || {
                loop {
                    let task = {
                        // Acquérir le verrou sur l'état interne
                        let mut state = shared.state.lock().unwrap_or_else(|poisoned| poisoned.into_inner());

                        // Attendre tant qu'il n'y a pas de tâche et que le pool n'est pas arrêté
                        while state.queue.is_empty() && !state.is_shutdown {
                            state = shared.condvar.wait(state).unwrap_or_else(|poisoned| poisoned.into_inner());
                        }

                        // Si le pool est arrêté et qu'il n'y a plus aucune tâche, terminer le worker
                        if state.is_shutdown && state.queue.is_empty() {
                            break;
                        }

                        // Récupérer la prochaine tâche FIFO
                        state.queue.pop_front()
                    };

                    // Exécution de la tâche en dehors du verrou pour libérer les autres workers
                    if let Some(task) = task {
                        task();
                    }
                }
            })
            .expect("Échec du démarrage du thread worker");

        Self {
            _id: id,
            handle: Some(handle),
        }
    }
}

/// Pool de threads thread-safe générique.
/// Implémente `Send` et `Sync`.
pub struct ThreadPool {
    workers: Vec<Worker>,
    shared: Arc<Shared>,
}

// Vérifications explicites des contrats de concurrence de haut niveau
unsafe impl Send for ThreadPool {}
unsafe impl Sync for ThreadPool {}

impl ThreadPool {
    /// Crée un nouveau pool de threads avec le nombre de workers spécifié.
    ///
    /// # Erreurs
    /// Retourne [`ThreadPoolError::ZeroThreads`] si `num_threads == 0`.
    pub fn new(num_threads: usize) -> Result<Self, ThreadPoolError> {
        if num_threads == 0 {
            return Err(ThreadPoolError::ZeroThreads);
        }

        let shared = Arc::new(Shared {
            state: Mutex::new(State {
                queue: VecDeque::new(),
                is_shutdown: false,
            }),
            condvar: Condvar::new(),
        });

        let mut workers = Vec::with_capacity(num_threads);
        for id in 0..num_threads {
            workers.push(Worker::new(id, Arc::clone(&shared)));
        }

        Ok(Self { workers, shared })
    }

    /// Envoie une tâche à exécuter de manière asynchrone par un worker du pool.
    pub fn execute<F>(&self, task: F)
    where
        F: FnOnce() + Send + 'static,
    {
        let mut state = self
            .shared
            .state
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());

        if state.is_shutdown {
            return;
        }

        state.queue.push_back(Box::new(task));
        self.shared.condvar.notify_one();
    }
}

impl Drop for ThreadPool {
    fn drop(&mut self) {
        // Signaler l'arrêt
        {
            let mut state = self
                .shared
                .state
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            state.is_shutdown = true;
            // Réveiller tous les workers pour qu'ils traitent le reliquat ou s'arrêtent
            self.shared.condvar.notify_all();
        }

        // Attendre que chaque thread se termine
        for worker in &mut self.workers {
            if let Some(handle) = worker.handle.take() {
                let _ = handle.join();
            }
        }
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("=== Initialisation du ThreadPool ===");
    let pool_size = 4;
    let pool = ThreadPool::new(pool_size)?;

    let total_tasks = 20;
    let counter = Arc::new(Mutex::new(0usize));

    println!("Soumission de {} tâches à exécuter...", total_tasks);
    for i in 0..total_tasks {
        let counter_clone = Arc::clone(&counter);
        pool.execute(move || {
            let current_thread = thread::current();
            let thread_name = current_thread.name().unwrap_or("inconnu");

            // Simulation d'un court travail
            thread::sleep(std::time::Duration::from_millis(10));

            let mut val = counter_clone.lock().unwrap_or_else(|p| p.into_inner());
            *val += 1;
            println!(
                "[{}] Tâche #{:02} terminée (Total traité : {})",
                thread_name, i, *val
            );
        });
    }

    // Démonstration du partage thread-safe (&ThreadPool / Sync)
    let pool_ref = Arc::new(pool);
    let mut producer_handles = Vec::new();

    for producer_id in 0..2 {
        let pool_shared = Arc::clone(&pool_ref);
        let counter_clone = Arc::clone(&counter);

        let handle = thread::spawn(move || {
            for j in 0..5 {
                let cnt = Arc::clone(&counter_clone);
                pool_shared.execute(move || {
                    let mut val = cnt.lock().unwrap_or_else(|p| p.into_inner());
                    *val += 1;
                    println!(
                        "Producteur #{} - sous-tâche #{} exécutée (Total traité : {})",
                        producer_id, j, *val
                    );
                });
            }
        });
        producer_handles.push(handle);
    }

    for h in producer_handles {
        let _ = h.join();
    }

    // Le drop explicite du pool garantit la terminaison de toutes les tâches
    drop(pool_ref);

    let final_count = *counter.lock().unwrap_or_else(|p| p.into_inner());
    println!("=== Toutes les tâches ont été complétées avec succès ===");
    println!("Total final comptabilisé : {} / 30", final_count);
    assert_eq!(final_count, 30);

    Ok(())
}

