        match self {
            Operator::Add => Ok(left + right),
            Operator::Sub => Ok(left - right),
            Operator::Mul => Ok(left * right),
            Operator::Div => {
                if right == 0.0 {
                    Err(ParseError::DivisionByZero)
                } else {
                    Ok(left / right)
                }
            }
            Operator::Pow => Ok(left.powf(right)),
        }
    }
