#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    Number(f64),
    Op(Operator),
    LParen,
    RParen,
}

#[derive(Debug, Clone, PartialEq)]
pub enum ParseError {
    InvalidCharacter(char),
    InvalidNumber(String),
    MismatchedParentheses,
    InsufficientOperands,
    RemainingOperands,
    EmptyExpression,
    DivisionByZero,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::InvalidCharacter(c) => write!(f, "Caractère invalide dans l'expression : '{c}'"),
            ParseError::InvalidNumber(s) => write!(f, "Format de nombre invalide : \"{s}\""),
            ParseError::MismatchedParentheses => write!(f, "Parenthèses non équilibrées"),
            ParseError::InsufficientOperands => write!(f, "Opérandes insuffisants pour l'opérateur"),
            ParseError::RemainingOperands => write!(f, "Opérandes surnuméraires dans l'expression"),
            ParseError::EmptyExpression => write!(f, "L'expression est vide"),
