impl std::error::Error for ParseError {}

pub fn tokenize(input: &str) -> Result<Vec<Token>, ParseError> {
    let mut tokens = Vec::new();
    let mut chars = input.chars().peekable();
    let mut expect_unary = true;

    while let Some(&c) = chars.peek() {
        match c {
            ' ' | '\t' | '\r' | '\n' => {
                chars.next();
            }
            '0'..='9' | '.' => {
                let mut num_str = String::new();
                let mut dot_seen = false;

                while let Some(&nc) = chars.peek() {
                    if nc.is_ascii_digit() {
                        num_str.push(nc);
                        chars.next();
                    } else if nc == '.' {
                        if dot_seen {
                            return Err(ParseError::InvalidNumber(format!("{num_str}.")));
                        }
                        dot_seen = true;
                        num_str.push(nc);
                        chars.next();
                    } else {
                        break;
                    }
                }

                let num: f64 = num_str
                    .parse()
                    .map_err(|_| ParseError::InvalidNumber(num_str))?;
                tokens.push(Token::Number(num));
                expect_unary = false;
            }
            '+' => {
                chars.next();
                if !expect_unary {
                    tokens.push(Token::Op(Operator::Add));
                    expect_unary = true;
                }
            }
            '-' => {
                chars.next();
                if expect_unary {
                    // Gestion d'un nombre négatif unaire immédiat si suivi d'un chiffre
                    while let Some(&nc) = chars.peek() {
                        if nc.is_whitespace() {
                            chars.next();
                        } else {
                            break;
                        }
                    }
                    if let Some(&nc) = chars.peek() {
                        if nc.is_ascii_digit() || nc == '.' {
                            let mut num_str = String::from("-");
                            let mut dot_seen = false;
                            while let Some(&digit) = chars.peek() {
                                if digit.is_ascii_digit() {
                                    num_str.push(digit);
                                    chars.next();
                                } else if digit == '.' {
                                    if dot_seen {
                                        return Err(ParseError::InvalidNumber(format!("{num_str}.")));
                                    }
                                    dot_seen = true;
                                    num_str.push(digit);
                                    chars.next();
                                } else {
                                    break;
                                }
                            }
                            let num: f64 = num_str
                                .parse()
                                .map_err(|_| ParseError::InvalidNumber(num_str))?;
                            tokens.push(Token::Number(num));
                            expect_unary = false;
                            continue;
                        }
                    }
                    // Moins unaire équivalent à 0 - <terme>
                    tokens.push(Token::Number(0.0));
                    tokens.push(Token::Op(Operator::Sub));
                } else {
                    tokens.push(Token::Op(Operator::Sub));
                    expect_unary = true;
                }
            }
            '*' => {
                chars.next();
                tokens.push(Token::Op(Operator::Mul));
                expect_unary = true;
            }
            '/' => {
                chars.next();
                tokens.push(Token::Op(Operator::Div));
                expect_unary = true;
            }
            '^' => {
                chars.next();
                tokens.push(Token::Op(Operator::Pow));
                expect_unary = true;
            }
            '(' => {
                chars.next();
                tokens.push(Token::LParen);
                expect_unary = true;
            }
            ')' => {
                chars.next();
                tokens.push(Token::RParen);
                expect_unary = false;
            }
            other => return Err(ParseError::InvalidCharacter(other)),
        }
    }

    Ok(tokens)
}

/// Convertit des tokens en notation postfixe (RPN) via Shunting-yard.
/// Utilise explicitement std::collections::VecDeque comme file de sortie FIFO.
pub fn shunting_yard(tokens: &[Token]) -> Result<VecDeque<Token>, ParseError> {
    if tokens.is_empty() {
        return Err(ParseError::EmptyExpression);
    }

    let mut output_queue: VecDeque<Token> = VecDeque::new();
    let mut operator_stack: Vec<Token> = Vec::new();

    for token in tokens {
        match token {
            Token::Number(_) => {
                output_queue.push_back(token.clone());
            }
            Token::Op(op1) => {
                while let Some(top) = operator_stack.last() {
                    match top {
                        Token::Op(op2) => {
                            let higher_precedence = op2.precedence() > op1.precedence();
                            let same_precedence_left_assoc = op2.precedence() == op1.precedence()
                                && op1.associativity() == Associativity::Left;

                            if higher_precedence || same_precedence_left_assoc {
                                if let Some(popped) = operator_stack.pop() {
                                    output_queue.push_back(popped);
                                }
                            } else {
                                break;
                            }
                        }
                        _ => break,
                    }
                }
                operator_stack.push(token.clone());
            }
            Token::LParen => {
                operator_stack.push(token.clone());
            }
            Token::RParen => {
                let mut found_lparen = false;
                while let Some(top) = operator_stack.pop() {
                    if top == Token::LParen {
                        found_lparen = true;
                        break;
                    }
                    output_queue.push_back(top);
                }
                if !found_lparen {
                    return Err(ParseError::MismatchedParentheses);
                }
            }
        }
    }

    while let Some(op) = operator_stack.pop() {
        if op == Token::LParen || op == Token::RParen {
            return Err(ParseError::MismatchedParentheses);
        }
        output_queue.push_back(op);
    }

    Ok(output_queue)
}

/// Évalue une file de tokens en notation polonaise inverse (RPN).
pub fn evaluate_rpn(mut rpn_queue: VecDeque<Token>) -> Result<f64, ParseError> {
    let mut eval_stack: Vec<f64> = Vec::new();

    while let Some(token) = rpn_queue.pop_front() {
        match token {
            Token::Number(val) => {
                eval_stack.push(val);
            }
            Token::Op(op) => {
                let right = eval_stack.pop().ok_or(ParseError::InsufficientOperands)?;
                let left = eval_stack.pop().ok_or(ParseError::InsufficientOperands)?;
                let result = op.apply(left, right)?;
                eval_stack.push(result);
            }
            Token::LParen | Token::RParen => return Err(ParseError::MismatchedParentheses),
        }
    }

    if eval_stack.len() == 1 {
        eval_stack.pop().ok_or(ParseError::InsufficientOperands)
    } else if eval_stack.is_empty() {
        Err(ParseError::EmptyExpression)
    } else {
        Err(ParseError::RemainingOperands)
    }
}

/// Évalue une chaîne d'expression arithmétique de bout en bout.
pub fn evaluate(input: &str) -> Result<f64, ParseError> {
    let tokens = tokenize(input)?;
    let rpn = shunting_yard(&tokens)?;
    evaluate_rpn(rpn)
}

fn main() {
    println!("=== Interpréteur Shunting-Yard (VecDeque) ===");
    println!("Entrez une expression arithmétique (ou 'exit' pour quitter) :");

    // Exemples d'illustrations prédéfinis
    let examples = [
        "3 + 4 * 2 / ( 1 - 5 ) ^ 2 ^ 3",
        "2 ^ 3 ^ 2",
        "-5 + 3 * (2 - 8)",
        "10 / (2 + 3)",
    ];

    println!("\n--- Démonstrations automatiques ---");
    for expr in examples {
        match evaluate(expr) {
            Ok(result) => println!("{expr} = {result}"),
            Err(err) => println!("{expr} -> Erreur : {err}"),
        }
    }
    println!("------------------------------------\n");

    let stdin = io::stdin();
    loop {
        print!("> ");
        if io::stdout().flush().is_err() {
            eprintln!("Erreur lors du flush de stdout");
            break;
        }

        let mut line = String::new();
        match stdin.read_line(&mut line) {
            Ok(0) => break, // EOF
            Ok(_) => {
                let trimmed = line.trim();
                if trimmed.is_empty() {
                    continue;
                }
                if trimmed.eq_ignore_ascii_case("exit") || trimmed.eq_ignore_ascii_case("quit") {
                    println!("Au revoir !");
                    break;
                }
                match evaluate(trimmed) {
                    Ok(result) => println!("Résultat = {result}"),
                    Err(e) => eprintln!("Erreur d'évaluation : {e}"),
                }
            }
            Err(e) => {
                eprintln!("Erreur de lecture : {e}");
                break;
            }
        }
    }
}

