// src/main.rs
use std::borrow::Borrow;
use std::collections::{HashMap, VecDeque};
use std::hash::Hash;
use std::sync::Arc;

/// Erreurs possibles lors de l'initialisation du cache LRU.
#[derive(Debug, PartialEq, Eq)]
pub enum LruCacheError {
    InvalidCapacity,
}

impl std::fmt::Display for LruCacheError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::InvalidCapacity => write!(f, "La capacité du cache doit être strictement supérieure à zéro"),
        }
    }
}

impl std::error::Error for LruCacheError {}

/// Cache LRU (Least Recently Used) générique.
///
/// Associe une clé `K` à une valeur partagée `Arc<V>`.
/// L'ordre d'accès est suivi via un `VecDeque<K>` (tête = LRU, queue = MRU).
#[derive(Debug, Clone)]
pub struct LruCache<K, V> {
    capacity: usize,
    map: HashMap<K, Arc<V>>,
    order: VecDeque<K>,
}

impl<K, V> LruCache<K, V>
where
    K: Eq + Hash + Clone,
{
    /// Crée un nouveau cache LRU avec la capacité maximale spécifiée.
    ///
    /// Retourne une erreur si la capacité est égale à 0.
    pub fn new(capacity: usize) -> Result<Self, LruCacheError> {
        if capacity == 0 {
            return Err(LruCacheError::InvalidCapacity);
        }

        Ok(Self {
            capacity,
            map: HashMap::with_capacity(capacity),
            order: VecDeque::with_capacity(capacity),
        })
    }

    /// Retourne la capacité maximale du cache.
    pub fn capacity(&self) -> usize {
        self.capacity
    }

    /// Retourne le nombre d'éléments actuellement présents dans le cache.
    pub fn len(&self) -> usize {
        self.map.len()
    }

    /// Indique si le cache est vide.
    pub fn is_empty(&self) -> bool {
        self.map.is_empty()
    }

    /// Déplace la clé donnée à la fin de la file (position MRU).
    fn mark_as_mru(&mut self, key: &K) {
        if let Some(pos) = self.order.iter().position(|k| k == key) {
            self.order.remove(pos);
            self.order.push_back(key.clone());
        }
    }

    /// Récupère une référence partagée `Arc<V>` associée à la clé et rafraîchit sa récence.
    pub fn get<Q>(&mut self, key: &Q) -> Option<Arc<V>>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let (found_key, value) = match self.map.get_key_value(key) {
            Some((k, v)) => (k.clone(), Arc::clone(v)),
            None => return None,
        };

        self.mark_as_mru(&found_key);
        Some(value)
    }

    /// Récupère la valeur sans modifier l'ordre de récence dans le cache.
    pub fn peek<Q>(&self, key: &Q) -> Option<Arc<V>>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.map.get(key).map(Arc::clone)
    }

    /// Insère ou met à jour une paire clé/valeur.
    ///
    /// Retourne l'ancienne valeur si la clé existait déjà, sinon `None`.
    /// Si la capacité est atteinte et qu'une nouvelle clé est insérée,
    /// l'élément le moins récemment utilisé est évincé.
    pub fn put(&mut self, key: K, value: V) -> Option<Arc<V>> {
        let arc_value = Arc::new(value);

        if let Some(existing_entry) = self.map.get_mut(&key) {
            let previous = std::mem::replace(existing_entry, arc_value);
            self.mark_as_mru(&key);
            return Some(previous);
        }

        if self.len() >= self.capacity {
            self.evict_lru();
        }

        self.order.push_back(key.clone());
        self.map.insert(key, arc_value);
        None
    }

    /// Supprime et retourne la valeur associée à la clé, si elle existe.
    pub fn remove<Q>(&mut self, key: &Q) -> Option<Arc<V>>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        if let Some((removed_key, removed_value)) = self.map.remove_entry(key) {
            if let Some(pos) = self.order.iter().position(|k| k == &removed_key) {
                self.order.remove(pos);
            }
            return Some(removed_value);
        }
        None
    }

    /// Supprime l'élément le moins récemment utilisé (tête de `order`).
    fn evict_lru(&mut self) -> Option<(K, Arc<V>)> {
        while let Some(lru_key) = self.order.pop_front() {
            if let Some(val) = self.map.remove(&lru_key) {
                return Some((lru_key, val));
            }
        }
        None
    }

    /// Vide l'intégralité du cache.
    pub fn clear(&mut self) {
        self.map.clear();
        self.order.clear();
    }
}

fn main() {
    println!("=== Initialisation du Cache LRU ===");

    let mut cache = match LruCache::new(3) {
        Ok(c) => c,
        Err(err) => {
            eprintln!("Erreur lors de la création du cache: {err}");
            return;
        }
    };

    println!("Insertion des entrées 1, 2, 3...");
    cache.put(1, "Donnée A".to_string());
    cache.put(2, "Donnée B".to_string());
    cache.put(3, "Donnée C".to_string());

    println!("Taille actuelle du cache : {}", cache.len());

    // Accès à la clé 1 -> la rend la plus récemment utilisée
    if let Some(val) = cache.get(&1) {
        println!("Lecture clé 1 (rafraîchie) : {val} (références Arc: {})", Arc::strong_count(&val));
    }

    // Insertion d'une 4ème clé -> éviction du LRU (clé 2)
    println!("Insertion de la clé 4 (provoque l'éviction de 2)...");
    cache.put(4, "Donnée D".to_string());

    assert!(cache.get(&2).is_none(), "La clé 2 aurait dû être évincée");
    assert!(cache.get(&1).is_some(), "La clé 1 devrait être présente");
    assert!(cache.get(&3).is_some(), "La clé 3 devrait être présente");
    assert!(cache.get(&4).is_some(), "La clé 4 devrait être présente");

    // Démonstration du partage avec Arc
    println!("\nDémonstration du partage sans copie (Arc) :");
    let val_ref_1 = cache.get(&1);
    let val_ref_2 = cache.peek(&1);

    if let (Some(r1), Some(r2)) = (val_ref_1, val_ref_2) {
        println!("Valeur r1: {r1}, Valeur r2: {r2}");
        println!("Nombre de propriétaires Arc pour clé 1: {}", Arc::strong_count(&r1));
        assert_eq!(Arc::strong_count(&r1), 3); // Dans le cache + r1 + r2
    }

    println!("\nCache LRU exécuté et validé avec succès !");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_zero_capacity_rejected() {
        let res: Result<LruCache<i32, String>, _> = LruCache::new(0);
        assert!(matches!(res, Err(LruCacheError::InvalidCapacity)));
    }

    #[test]
    fn test_basic_put_and_get() {
        let mut cache = LruCache::new(2).expect("capacité valide");
        assert!(cache.is_empty());

        assert!(cache.put(1, "un").is_none());
        assert_eq!(cache.len(), 1);

        let retrieved = cache.get(&1).expect("clé 1 trouvée");
        assert_eq!(*retrieved, "un");
    }

    #[test]
    fn test_eviction_order() {
        let mut cache = LruCache::new(2).expect("capacité valide");

        cache.put(1, 100);
        cache.put(2, 200);

        // Lecture de 1 -> 1 devient MRU, 2 devient LRU
        assert!(cache.get(&1).is_some());

        // Insertion de 3 -> 2 doit être évincé
        cache.put(3, 300);

        assert!(cache.get(&2).is_none());
        assert_eq!(*cache.get(&1).expect("1 présent"), 100);
        assert_eq!(*cache.get(&3).expect("3 présent"), 300);
    }

    #[test]
    fn test_put_update_existing_key() {
        let mut cache = LruCache::new(2).expect("capacité valide");

        cache.put("a", 1);
        let old = cache.put("a", 2);

        assert_eq!(old.map(|v| *v), Some(1));
        assert_eq!(*cache.get(&"a").expect("a présent"), 2);
        assert_eq!(cache.len(), 1);
    }

    #[test]
    fn test_peek_does_not_refresh_lru() {
        let mut cache = LruCache::new(2).expect("capacité valide");

        cache.put(1, "A");
        cache.put(2, "B");

        // peek sur 1 ne doit PAS rafraîchir son rang
        assert_eq!(*cache.peek(&1).expect("1 présent"), "A");

        // Insertion de 3 -> 1 doit être évincé car 2 est plus récent
        cache.put(3, "C");

        assert!(cache.get(&1).is_none());
        assert!(cache.get(&2).is_some());
        assert!(cache.get(&3).is_some());
    }

    #[test]
    fn test_remove() {
        let mut cache = LruCache::new(3).expect("capacité valide");
        cache.put(10, 1000);
        assert_eq!(cache.remove(&10).map(|v| *v), Some(1000));
        assert!(cache.get(&10).is_none());
        assert_eq!(cache.len(), 0);
    }
}

