    }

    // Insertion d'une 4ème clé -> éviction du LRU (clé 2)
    println!("Insertion de la clé 4 (provoque l'éviction de 2)...");
    cache.put(4, "Donnée D".to_string());

    assert!(cache.get(&2).is_none(), "La clé 2 aurait dû être évincée");
    assert!(cache.get(&1).is_some(), "La clé 1 devrait être présente");
    assert!(cache.get(&3).is_some(), "La clé 3 devrait être présente");
    assert!(cache.get(&4).is_some(), "La clé 4 devrait être présente");

    // Démonstration du partage avec Arc
    println!("\nDémonstration du partage sans copie (Arc) :");
    let val_ref_1 = cache.get(&1);
    let val_ref_2 = cache.peek(&1);

    if let (Some(r1), Some(r2)) = (val_ref_1, val_ref_2) {
        println!("Valeur r1: {r1}, Valeur r2: {r2}");
        println!("Nombre de propriétaires Arc pour clé 1: {}", Arc::strong_count(&r1));
        assert_eq!(Arc::strong_count(&r1), 3); // Dans le cache + r1 + r2
    }

    println!("\nCache LRU exécuté et validé avec succès !");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_zero_capacity_rejected() {
        let res: Result<LruCache<i32, String>, _> = LruCache::new(0);
        assert!(matches!(res, Err(LruCacheError::InvalidCapacity)));
    }

    #[test]
    fn test_basic_put_and_get() {
        let mut cache = LruCache::new(2).expect("capacité valide");
        assert!(cache.is_empty());

        assert!(cache.put(1, "un").is_none());
        assert_eq!(cache.len(), 1);

        let retrieved = cache.get(&1).expect("clé 1 trouvée");
        assert_eq!(*retrieved, "un");
    }

    #[test]
    fn test_eviction_order() {
        let mut cache = LruCache::new(2).expect("capacité valide");

        cache.put(1, 100);
        cache.put(2, 200);

        // Lecture de 1 -> 1 devient MRU, 2 devient LRU
        assert!(cache.get(&1).is_some());

        // Insertion de 3 -> 2 doit être évincé
        cache.put(3, 300);

        assert!(cache.get(&2).is_none());
        assert_eq!(*cache.get(&1).expect("1 présent"), 100);
        assert_eq!(*cache.get(&3).expect("3 présent"), 300);
    }

    #[test]
    fn test_put_update_existing_key() {
        let mut cache = LruCache::new(2).expect("capacité valide");

        cache.put("a", 1);
        let old = cache.put("a", 2);

        assert_eq!(old.map(|v| *v), Some(1));
        assert_eq!(*cache.get(&"a").expect("a présent"), 2);
        assert_eq!(cache.len(), 1);
    }

    #[test]
    fn test_peek_does_not_refresh_lru() {
        let mut cache = LruCache::new(2).expect("capacité valide");

        cache.put(1, "A");
        cache.put(2, "B");

        // peek sur 1 ne doit PAS rafraîchir son rang
        assert_eq!(*cache.peek(&1).expect("1 présent"), "A");

        // Insertion de 3 -> 1 doit être évincé car 2 est plus récent
        cache.put(3, "C");

        assert!(cache.get(&1).is_none());
        assert!(cache.get(&2).is_some());
        assert!(cache.get(&3).is_some());
    }

    #[test]
    fn test_remove() {
        let mut cache = LruCache::new(3).expect("capacité valide");
        cache.put(10, 1000);
        assert_eq!(cache.remove(&10).map(|v| *v), Some(1000));
        assert!(cache.get(&10).is_none());
        assert_eq!(cache.len(), 0);
    }
}

