/// Représentation en mémoire d'un document INI.
#[derive(Debug, Default, Clone, PartialEq, Eq)]
pub struct IniDocument {
    /// Section globale par défaut (sans nom de section).
    pub global: HashMap<String, String>,
    /// Sections nommées contenant leurs paires clé-valeur respectives.
    pub sections: HashMap<String, HashMap<String, String>>,
}

impl IniDocument {
    /// Crée un nouveau document vide.
    pub fn new() -> Self {
        Self::default()
    }

    /// Récupère une valeur d'une section spécifique (ou de la section globale si section est vide).
    pub fn get(&self, section: &str, key: &str) -> Option<&str> {
        if section.is_empty() {
            self.global.get(key).map(|s| s.as_str())
        } else {
            self.sections
                .get(section)
                .and_then(|sec| sec.get(key).map(|s| s.as_str()))
        }
    }

    /// Récupère toutes les paires d'une section donnée.
    pub fn get_section(&self, section: &str) -> Option<&HashMap<String, String>> {
        self.sections.get(section)
    }

    /// Insère une paire clé/valeur dans une section donnée (ou globale si `None`).
    pub fn insert(&mut self, section: Option<&str>, key: String, value: String) {
        match section {
            Some(sec_name) if !sec_name.is_empty() => {
                self.sections
                    .entry(sec_name.to_string())
                    .or_default()
                    .insert(key, value);
            }
            _ => {
                self.global.insert(key, value);
            }
        }
    }

    /// Parse une source implémentant `BufRead` en utilisant son itérateur `Lines`.
    pub fn from_reader<R: BufRead>(reader: R) -> Result<Self, IniError> {
        let mut doc = IniDocument::new();
        let mut state = ParserState::GlobalScope;

        // Parcours via l'itérateur standard std::io::Lines
        for (line_index, line_result) in reader.lines().enumerate() {
            let line_num = line_index + 1;
            let line = line_result?;

            let trimmed = line.trim();

            match &state {
                ParserState::AwaitingContinuation {
                    section,
                    key,
                    accumulated,
                } => {
                    let token = Self::classify_continuation_line(trimmed);
                    match token {
                        LineToken::ContinuationPiece {
                            text,
                            has_continuation,
                        } => {
                            let mut new_accumulated = accumulated.clone();
                            if !new_accumulated.is_empty() {
                                new_accumulated.push(' ');
                            }
                            new_accumulated.push_str(text);

                            if has_continuation {
                                state = ParserState::AwaitingContinuation {
                                    section: section.clone(),
                                    key: key.clone(),
                                    accumulated: new_accumulated,
                                };
                            } else {
                                let final_val = Self::unquote(new_accumulated.trim());
                                doc.insert(section.as_deref(), key.clone(), final_val);
                                state = match section {
                                    Some(name) => ParserState::SectionScope(name.clone()),
                                    None => ParserState::GlobalScope,
                                };
                            }
                        }
                        _ => {
                            return Err(IniError::DanglingContinuation { line: line_num });
                        }
                    }
                }
                ParserState::GlobalScope | ParserState::SectionScope(_) => {
                    let current_section = match &state {
                        ParserState::SectionScope(name) => Some(name.clone()),
                        _ => None,
                    };

                    let token = Self::classify_standard_line(trimmed);
                    match token {
                        LineToken::BlankOrComment => {
                            // Ne modifie pas l'état
                        }
                        LineToken::Section(header) => {
                            if header.is_empty() {
                                return Err(IniError::InvalidSectionHeader {
                                    line: line_num,
                                    content: line,
                                });
                            }
                            state = ParserState::SectionScope(header.to_string());
                        }
                        LineToken::KeyValuePair {
                            key,
                            value,
                            has_continuation,
                        } => {
                            if has_continuation {
                                state = ParserState::AwaitingContinuation {
                                    section: current_section,
                                    key: key.to_string(),
                                    accumulated: value.to_string(),
                                };
                            } else {
                                let sanitized_val = Self::unquote(value);
                                doc.insert(
                                    current_section.as_deref(),
                                    key.to_string(),
                                    sanitized_val,
                                );
                            }
                        }
                        LineToken::Invalid(_) | LineToken::ContinuationPiece { .. } => {
                            return Err(IniError::InvalidKeyValue {
                                line: line_num,
                                content: line,
                            });
                        }
                    }
                }
            }
        }

        // Vérifier si le fichier s'est arrêté en plein milieu d'une ligne de continuation
        if let ParserState::AwaitingContinuation { .. } = state {
            return Err(IniError::DanglingContinuation { line: usize::MAX });
        }

        Ok(doc)
    }

    /// Parse depuis une chaîne de caractères en mémoire.
    pub fn from_str(content: &str) -> Result<Self, IniError> {
        Self::from_reader(content.as_bytes())
    }

    /// Supprime les commentaires inline (`#` ou `;`) s'ils ne sont pas entre guillemets.
    fn strip_inline_comments(input: &str) -> &str {
        let mut in_quote = false;
        let mut quote_char = ' ';

        for (idx, ch) in input.char_indices() {
            match ch {
                '"' | '\'' => {
                    if !in_quote {
                        in_quote = true;
                        quote_char = ch;
                    } else if quote_char == ch {
                        in_quote = false;
                    }
                }
                ';' | '#' if !in_quote => {
                    return &input[..idx];
                }
                _ => {}
            }
        }
        input
    }

    /// Supprime les guillemets englobants d'une valeur textuelle si présents.
    fn unquote(value: &str) -> String {
        let v = value.trim();
        if (v.starts_with('"') && v.ends_with('"') && v.len() >= 2)
            || (v.starts_with('\'') && v.ends_with('\'') && v.len() >= 2)
        {
            v[1..v.len() - 1].to_string()
        } else {
            v.to_string()
        }
    }

    /// Détermine le type de token pour une ligne standard.
    fn classify_standard_line(line: &str) -> LineToken<'_> {
        if line.is_empty() || line.starts_with(';') || line.starts_with('#') {
            return LineToken::BlankOrComment;
        }

        if line.starts_with('[') {
            if let Some(closing_idx) = line.find(']') {
                let inside = &line[1..closing_idx].trim();
                let remaining = line[closing_idx + 1..].trim();
                // S'il y a du contenu après ']', cela doit être un commentaire ou du vide
                if remaining.is_empty() || remaining.starts_with(';') || remaining.starts_with('#')
                {
                    return LineToken::Section(inside);
                }
            }
            return LineToken::Invalid(line);
        }

        let clean_line = Self::strip_inline_comments(line).trim();
        if clean_line.is_empty() {
            return LineToken::BlankOrComment;
        }

        // Séparateur '=' ou ':'
        let sep_pos = clean_line.find('=').or_else(|| clean_line.find(':'));
        if let Some(idx) = sep_pos {
            let key = clean_line[..idx].trim();
            let mut val = clean_line[idx + 1..].trim();
            if key.is_empty() {
                return LineToken::Invalid(line);
            }

            let mut has_continuation = false;
            if val.ends_with('\\') {
                has_continuation = true;
                val = val[..val.len() - 1].trim_end();
            }

            LineToken::KeyValuePair {
                key,
                value: val,
                has_continuation,
            }
        } else {
            LineToken::Invalid(line)
        }
    }

    /// Détermine le type de token pour une ligne attendue en continuation de valeur.
    fn classify_continuation_line(line: &str) -> LineToken<'_> {
        let clean_line = Self::strip_inline_comments(line).trim();
        if clean_line.is_empty() {
            return LineToken::BlankOrComment;
        }

        let mut has_continuation = false;
        let mut text = clean_line;
        if text.ends_with('\\') {
            has_continuation = true;
            text = text[..text.len() - 1].trim_end();
        }

        LineToken::ContinuationPiece {
            text,
            has_continuation,
        }
    }
}

impl fmt::Display for IniDocument {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        // Impression des paramètres globaux en premier
        for (k, v) in &self.global {
            writeln!(f, "{k} = {v}")?;
        }

        if !self.global.is_empty() && !self.sections.is_empty() {
            writeln!(f)?;
        }

        // Impression des sections
        for (sec_idx, (section_name, values)) in self.sections.iter().enumerate() {
            if sec_idx > 0 {
                writeln!(f)?;
            }
            writeln!(f, "[{section_name}]")?;
            for (k, v) in values {
                writeln!(f, "{k} = {v}")?;
            }
        }

        Ok(())
    }
}

