// src/main.rs
//! CLI de manipulation de graphes orientés avec détection de cycles de Tarjan.

#![forbid(unsafe_code)]

use std::collections::{BTreeSet, HashMap, HashSet};
use std::fs::File;
use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};

use anyhow::{Context, Result};
use clap::{Parser, Subcommand};
use serde::{Deserialize, Serialize};

/// Représentation d'un graphe orienté utilisant std::collections::HashSet.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct DirectedGraph {
    /// Ensemble des identifiants uniques de sommets.
    pub nodes: HashSet<String>,
    /// Liste d'adjacence : source -> ensemble des destinations.
    pub edges: HashMap<String, HashSet<String>>,
}

impl DirectedGraph {
    /// Crée un nouveau graphe orienté vide.
    pub fn new() -> Self {
        Self::default()
    }

    /// Ajoute un sommet dans le graphe.
    pub fn add_node(&mut self, node: impl Into<String>) -> bool {
        self.nodes.insert(node.into())
    }

    /// Ajoute un arc orienté de `from` vers `to`.
    /// Ajoute automatiquement les sommets s'ils n'existent pas encore.
    pub fn add_edge(&mut self, from: impl Into<String>, to: impl Into<String>) -> bool {
        let u = from.into();
        let v = to.into();

        self.nodes.insert(u.clone());
        self.nodes.insert(v.clone());

        self.edges.entry(u).or_default().insert(v)
    }

    /// Indique si le graphe contient une boucle sur un sommet donné (`u -> u`).
    pub fn has_self_loop(&self, node: &str) -> bool {
        self.edges
            .get(node)
            .map(|neighbors| neighbors.contains(node))
            .unwrap_or(false)
    }

    /// Retourne le nombre total d'arcs orientés.
    pub fn edge_count(&self) -> usize {
        self.edges.values().map(HashSet::len).sum()
    }

    /// Recherche les composantes fortement connexes (SCC) via l'algorithme de Tarjan.
    /// Retourne la liste des composantes (chacune étant un ensemble ordonné de sommets).
    pub fn tarjan_scc(&self) -> Vec<BTreeSet<String>> {
        let mut index = 0usize;
        let mut indices: HashMap<String, usize> = HashMap::new();
        let mut lowlink: HashMap<String, usize> = HashMap::new();
        let mut stack: Vec<String> = Vec::new();
        let mut on_stack: HashSet<String> = HashSet::new();
        let mut sccs: Vec<BTreeSet<String>> = Vec::new();

        // Trier les sommets pour assurer un parcours déterministe
        let mut sorted_nodes: Vec<&String> = self.nodes.iter().collect();
        sorted_nodes.sort();

        for &node in &sorted_nodes {
            if !indices.contains_key(node) {
                self.strongconnect(
                    node,
                    &mut index,
                    &mut indices,
                    &mut lowlink,
                    &mut stack,
                    &mut on_stack,
                    &mut sccs,
                );
            }
        }

        sccs
    }

    fn strongconnect(
        &self,
        node: &str,
        index: &mut usize,
        indices: &mut HashMap<String, usize>,
        lowlink: &mut HashMap<String, usize>,
        stack: &mut Vec<String>,
        on_stack: &mut HashSet<String>,
        sccs: &mut Vec<BTreeSet<String>>,
    ) {
        indices.insert(node.to_string(), *index);
        lowlink.insert(node.to_string(), *index);
        *index += 1;

        stack.push(node.to_string());
        on_stack.insert(node.to_string());

        // Parcourt les voisins de manière déterministe
        if let Some(neighbors) = self.edges.get(node) {
            let mut sorted_neighbors: Vec<&String> = neighbors.iter().collect();
            sorted_neighbors.sort();

            for neighbor in sorted_neighbors {
                if !indices.contains_key(neighbor.as_str()) {
                    self.strongconnect(
                        neighbor,
                        index,
                        indices,
                        lowlink,
                        stack,
                        on_stack,
                        sccs,
                    );
                    let neighbor_low = lowlink.get(neighbor.as_str()).copied().unwrap_or(usize::MAX);
                    if let Some(node_low) = lowlink.get_mut(node) {
                        *node_low = (*node_low).min(neighbor_low);
                    }
                } else if on_stack.contains(neighbor.as_str()) {
                    let neighbor_idx = indices.get(neighbor.as_str()).copied().unwrap_or(usize::MAX);
                    if let Some(node_low) = lowlink.get_mut(node) {
                        *node_low = (*node_low).min(neighbor_idx);
                    }
                }
            }
        }

        // Si le sommet courant est une racine de SCC, dépile tous les éléments de la composante
        if indices.get(node) == lowlink.get(node) {
            let mut scc = BTreeSet::new();
            while let Some(w) = stack.pop() {
                on_stack.remove(&w);
                scc.insert(w.clone());
                if w == node {
                    break;
                }
            }
            sccs.push(scc);
        }
    }

    /// Détecte s'il existe au moins un cycle dans le graphe orienté.
    /// Une composante fortement connexe est un cycle si :
    /// - Elle comporte plus d'un sommet.
    /// - Ou elle comporte un seul sommet ayant une boucle réflexive (self-loop).
    pub fn detect_cycles(&self) -> Vec<BTreeSet<String>> {
        self.tarjan_scc()
            .into_iter()
            .filter(|scc| {
                if scc.len() > 1 {
                    true
                } else if scc.len() == 1 {
                    let single = scc.iter().next().map(String::as_str).unwrap_or_default();
                    self.has_self_loop(single)
                } else {
                    false
                }
            })
            .collect()
    }

    /// Exporte au format Graphviz DOT.
    pub fn to_dot(&self) -> String {
        let mut dot = String::from("digraph G {\n");
        let mut sorted_nodes: Vec<&String> = self.nodes.iter().collect();
        sorted_nodes.sort();

        for node in &sorted_nodes {
            dot.push_str(&format!("  \"{}\";\n", node));
        }

        let mut sorted_edges: Vec<(&String, &String)> = Vec::new();
        for (u, targets) in &self.edges {
            for v in targets {
                sorted_edges.push((u, v));
            }
        }
        sorted_edges.sort();

        for (u, v) in sorted_edges {
            dot.push_str(&format!("  \"{}\" -> \"{}\";\n", u, v));
        }

        dot.push_str("}\n");
        dot
    }

    /// Charge un graphe depuis un fichier texte (format 'from -> to' ou 'from to').
    pub fn from_edge_file(path: &Path) -> Result<Self> {
        let file = File::open(path)
            .with_context(|| format!("Impossible d'ouvrir le fichier '{}'", path.display()))?;
        let reader = BufReader::new(file);
        let mut graph = Self::new();

        for (line_num, line_res) in reader.lines().enumerate() {
            let line = line_res.with_context(|| {
                format!(
                    "Erreur de lecture de la ligne {} dans '{}'",
                    line_num + 1,
                    path.display()
                )
            })?;
            let trimmed = line.trim();

            if trimmed.is_empty() || trimmed.starts_with('#') {
                continue;
            }

            let parts: Vec<&str> = if trimmed.contains("->") {
                trimmed.split("->").collect()
            } else {
                trimmed.split_whitespace().collect()
            };

            if parts.len() == 1 {
                graph.add_node(parts[0].trim());
            } else if parts.len() >= 2 {
                let u = parts[0].trim();
                let v = parts[1].trim();
                if !u.is_empty() && !v.is_empty() {
                    graph.add_edge(u, v);
                }
            }
        }

        Ok(graph)
    }

    /// Sauvegarde le graphe au format JSON.
    pub fn save_json(&self, path: &Path) -> Result<()> {
        let file = File::create(path)
            .with_context(|| format!("Impossible de créer le fichier '{}'", path.display()))?;
        serde_json::to_writer_pretty(file, self)
            .with_context(|| "Erreur lors de la sérialisation JSON du graphe")?;
        Ok(())
    }

    /// Charge le graphe depuis un format JSON.
    pub fn from_json_file(path: &Path) -> Result<Self> {
        let file = File::open(path)
            .with_context(|| format!("Impossible d'ouvrir le fichier '{}'", path.display()))?;
        let reader = BufReader::new(file);
        let graph = serde_json::from_reader(reader)
            .with_context(|| "Erreur lors de la désérialisation JSON du graphe")?;
        Ok(graph)
    }
}

/// Structure de parsing des arguments de la ligne de commande.
#[derive(Parser, Debug)]
#[command(
    name = "graph-cycle-cli",
    version,
    about = "CLI pour analyser des graphes orientés et détecter les cycles (Tarjan SCC)",
    long_about = None
)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Inspecte les propriétés d'un graphe orienté
    Inspect {
        /// Chemin du fichier graphe (.txt ou .json)
        #[arg(short, long)]
        file: PathBuf,
    },
    /// Détecte les composantes fortement connexes et les cycles via Tarjan
    Cycles {
        /// Chemin du fichier graphe (.txt ou .json)
        #[arg(short, long)]
        file: PathBuf,
    },
    /// Exporte le graphe au format Graphviz (.dot)
    Dot {
        /// Chemin du fichier graphe d'entrée (.txt ou .json)
        #[arg(short, long)]
        file: PathBuf,
        /// Fichier de sortie optionnel (par défaut: stdout)
        #[arg(short, long)]
        out: Option<PathBuf>,
    },
    /// Exécute une démonstration avec un graphe orienté contenant des cycles
    Demo,
}

fn load_graph(path: &Path) -> Result<DirectedGraph> {
    if let Some(ext) = path.extension().and_then(|s| s.to_str()) {
        if ext.eq_ignore_ascii_case("json") {
            return DirectedGraph::from_json_file(path);
        }
    }
    DirectedGraph::from_edge_file(path)
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Inspect { file } => {
            let graph = load_graph(&file)?;
            println!("=== Analyse du graphe ===");
            println!("Fichier : {}", file.display());
            println!("Sommets (total : {}) :", graph.nodes.len());
            let mut nodes: Vec<&String> = graph.nodes.iter().collect();
            nodes.sort();
            for node in nodes {
                let neighbors = graph.edges.get(node);
                let count = neighbors.map(HashSet::len).unwrap_or(0);
                println!("  - Sommet '{}' -> {} arc(s) sortant(s)", node, count);
            }
            println!("Nombre total d'arcs : {}", graph.edge_count());
        }
        Commands::Cycles { file } => {
            let graph = load_graph(&file)?;
            println!("=== Détection de cycles (Algorithme de Tarjan) ===");
            println!("Fichier analysé : {}", file.display());

            let sccs = graph.tarjan_scc();
            println!("\nNombre total de SCC identifiées : {}", sccs.len());
            for (idx, scc) in sccs.iter().enumerate() {
                let nodes_repr: Vec<String> = scc.iter().cloned().collect();
                println!("  SCC #{}: [{}]", idx + 1, nodes_repr.join(", "));
            }

            let cycles = graph.detect_cycles();
            println!("\n--- Diagnostic des cycles ---");
            if cycles.is_empty() {
                println!("Le graphe est un Graphe Orienté Acyclique (DAG). Aucun cycle détecté.");
            } else {
                println!("Attention : {} sous-ensemble(s) cyclique(s) détecté(s) !", cycles.len());
                for (i, cycle) in cycles.iter().enumerate() {
                    let nodes_str: Vec<String> = cycle.iter().cloned().collect();
                    println!("  Cycle #{}: [{}]", i + 1, nodes_str.join(", "));
                }
            }
        }
        Commands::Dot { file, out } => {
            let graph = load_graph(&file)?;
            let dot_output = graph.to_dot();

            if let Some(dest) = out {
                let mut out_file = File::create(&dest)
                    .with_context(|| format!("Impossible d'écrire dans '{}'", dest.display()))?;
                out_file.write_all(dot_output.as_bytes())?;
                println!("Export Graphviz DOT généré avec succès dans '{}'", dest.display());
            } else {
                print!("{}", dot_output);
            }
        }
        Commands::Demo => {
            println!("=== Démonstration de détection de cycles avec Tarjan ===");
            let mut graph = DirectedGraph::new();

            // Création de 2 cycles :
            // Cycle 1 : A -> B -> C -> A
            graph.add_edge("A", "B");
            graph.add_edge("B", "C");
            graph.add_edge("C", "A");

            // Connexion vers un second cycle : C -> D
            // Cycle 2 : D -> E -> D
            graph.add_edge("C", "D");
            graph.add_edge("D", "E");
            graph.add_edge("E", "D");

            // Sommet puits sans cycle : E -> F
            graph.add_edge("E", "F");

            // Sommet isolé avec self-loop : G -> G
            graph.add_edge("G", "G");

            println!("Sommets : {}", graph.nodes.len());
            println!("Arcs    : {}", graph.edge_count());

            let sccs = graph.tarjan_scc();
            println!("\nComposantes fortement connexes (SCC) trouvées :");
            for (idx, scc) in sccs.iter().enumerate() {
                let elements: Vec<String> = scc.iter().cloned().collect();
                println!("  #{} : {{{}}}", idx + 1, elements.join(", "));
            }

            let cycles = graph.detect_cycles();
            println!("\nCycles extraits :");
            for (idx, cycle) in cycles.iter().enumerate() {
                let elements: Vec<String> = cycle.iter().cloned().collect();
                println!("  Cycle #{} : {{{}}}", idx + 1, elements.join(", "));
            }
        }
    }

    Ok(())
}

