```rust
// src/main.rs
use std::io::{self, BufReader, BufWriter, Read, Write};

/// Compresse un flux binaire `reader` vers `writer` selon l'algorithme RLE.
/// Chaque bloc est encodé sous forme de paire `(count: u8, byte: u8)`.
/// Retourne le nombre total d'octets écrits dans `writer`.
pub fn encode_rle<R: Read, W: Write>(reader: &mut R, writer: &mut W) -> io::Result<u64> {
    let mut reader = BufReader::new(reader);
    let mut writer = BufWriter::new(writer);

    let mut buf = [0u8; 8192];
    let mut current_byte: Option<u8> = None;
    let mut current_count: u8 = 0;
    let mut total_written: u64 = 0;

    loop {
        let bytes_read = reader.read(&mut buf)?;
        if bytes_read == 0 {
            break;
        }

        for &b in &buf[..bytes_read] {
            match current_byte {
                Some(prev) if prev == b => {
                    if current_count == u8::MAX {
                        writer.write_all(&[current_count, prev])?;
                        total_written += 2;
                        current_count = 1;
                    } else {
                        current_count += 1;
                    }
                }
                Some(prev) => {
                    writer.write_all(&[current_count, prev])?;
                    total_written += 2;
                    current_byte = Some(b);
                    current_count = 1;
                }
                None => {
                    current_byte = Some(b);
                    current_count = 1;
                }
            }
        }
    }

    if let Some(prev) = current_byte {
        writer.write_all(&[current_count, prev])?;
        total_written += 2;
    }

    writer.flush()?;
    Ok(total_written)
}

/// Décompresse un flux binaire `reader` vers `writer` encodé en RLE.
/// Attend des paires de 2 octets `(count: u8, byte: u8)`.
/// Retourne le nombre total d'octets décompressés écrits dans `writer`.
pub fn decode_rle<R: Read, W: Write>(reader: &mut R, writer: &mut W) -> io::Result<u64> {
    let mut reader = BufReader::new(reader);
    let mut writer = BufWriter::new(writer);

    let mut pair = [0u8; 2];
    let mut total_decompressed: u64 = 0;
    let chunk_buffer = [0u8; 255];

    loop {
        match reader.read_exact(&mut pair) {
            Ok(()) => {
                let count = pair[0];
                let byte = pair[1];

                if count == 0 {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "Format RLE invalide : compte de répétition nul (count = 0)",
                    ));
                }

                // Optimisation d'écriture par bloc
                let mut remaining = count as usize;
                let mut slice = chunk_buffer;
                slice.fill(byte);

                while remaining > 0 {
                    let to_write = remaining.min(slice.len());
                    writer.write_all(&slice[..to_write])?;
                    remaining -= to_write;
                }

                total_decompressed += count as u64;
            }
            Err(e) if e.kind() == io::ErrorKind::UnexpectedEof => {
                // Vérifier si le flux était complètement aligné ou tronqué à 1 octet
                // Note : read_exact renvoie UnexpectedEof si 0 octet a été lu OU si moins de 2 octets ont été lus.
                // On tente de lire 1 octet pour savoir si c'était EOF propre ou tronqué :
                // Mais read_exact a déjà consommé d'éventuels octets.
                // Pour distinguer proprement EOF propre d'un flux tronqué, inspectons via read() de 2 octets ci-dessous :
                break;
            }
            Err(e) => return Err(e),
        }
    }

    writer.flush()?;
    Ok(total_decompressed)
}

/// Décompresseur robuste avec gestion stricte des fins de flux impaires / tronquées.
pub fn decode_rle_strict<R: Read, W: Write>(reader: &mut R, writer: &mut W) -> io::Result<u64> {
    let mut reader = BufReader::new(reader);
    let mut writer = BufWriter::new(writer);

    let mut total_decompressed: u64 = 0;
    let mut pair = [0u8; 2];
    let chunk_buffer = [0u8; 255];

    loop {
        let mut read_bytes = 0;
        while read_bytes < 2 {
            let n = reader.read(&mut pair[read_bytes..2])?;
            if n == 0 {
                break;
            }
            read_bytes += n;
        }

        if read_bytes == 0 {
            // EOF naturel sur une frontière de bloc de 2 octets
            break;
        } else if read_bytes == 1 {
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "Flux RLE corrompu : nombre impair d'octets (bloc incomplet)",
            ));
        }

        let count = pair[0];
        let byte = pair[1];

        if count == 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "Format RLE invalide : compte de répétition nul (count = 0)",
            ));
        }

        let mut remaining = count as usize;
        let mut slice = chunk_buffer;
        slice.fill(byte);

        while remaining > 0 {
            let to_write = remaining.min(slice.len());
            writer.write_all(&slice[..to_write])?;
            remaining -= to_write;
        }

        total_decompressed += count as u64;
    }

    writer.flush()?;
    Ok(total_decompressed)
}

/// Wrapper `Write` permettant d'encoder à la volée vers un flux sous-jacent.
pub struct RleEncoder<W: Write> {
    writer: W,
    current_byte: Option<u8>,
    current_count: u8,
    bytes_written: u64,
}

impl<W: Write> RleEncoder<W> {
    pub fn new(writer: W) -> Self {
        Self {
            writer,
            current_byte: None,
            current_count: 0,
            bytes_written: 0,
        }
    }

    /// Nombre d'octets encodés écrits dans le writer sous-jacent.
    pub fn bytes_written(&self) -> u64 {
        self.bytes_written
    }

    /// Termine l'encodage en vidant le tampon résiduel et retourne le writer sous-jacent.
    pub fn finish(mut self) -> io::Result<W> {
        self.flush_current_run()?;
        self.writer.flush()?;
        Ok(self.writer)
    }

    fn flush_current_run(&mut self) -> io::Result<()> {
        if let Some(byte) = self.current_byte.take() {
            self.writer.write_all(&[self.current_count, byte])?;
            self.bytes_written += 2;
            self.current_count = 0;
        }
        Ok(())
    }
}

impl<W: Write> Write for RleEncoder<W> {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        for &b in buf {
            match self.current_byte {
                Some(prev) if prev == b => {
                    if self.current_count == u8::MAX {
                        self.writer.write_all(&[self.current_count, prev])?;
                        self.bytes_written += 2;
                        self.current_count = 1;
                    } else {
                        self.current_count += 1;
                    }
                }
                Some(prev) => {
                    self.writer.write_all(&[self.current_count, prev])?;
                    self.bytes_written += 2;
                    self.current_byte = Some(b);
                    self.current_count = 1;
                }
                None => {
                    self.current_byte = Some(b);
                    self.current_count = 1;
                }
            }
        }
        Ok(buf.len())
    }

    fn flush(&mut self) -> io::Result<()> {
        self.writer.flush()
    }
}

/// Wrapper `Read` permettant de décompresser un flux RLE à la volée.
pub struct RleDecoder<R: Read> {
    reader: R,
    current_byte: u8,
    remaining_count: u8,
}

impl<R: Read> RleDecoder<R> {
    pub fn new(reader: R) -> Self {
        Self {
            reader,
            current_byte: 0,
            remaining_count: 0,
        }
    }
}

impl<R: Read> Read for RleDecoder<R> {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if buf.is_empty() {
            return Ok(0);
        }

        let mut written = 0;

        while written < buf.len() {
            if self.remaining_count > 0 {
                let to_copy = (self.remaining_count as usize).min(buf.len() - written);
                buf[written..written + to_copy].fill(self.current_byte);
                self.remaining_count -= to_copy as u8;
                written += to_copy;
            } else {
                let mut pair = [0u8; 2];
                let mut read_bytes = 0;
                while read_bytes < 2 {
                    let n = self.reader.read(&mut pair[read_bytes..2])?;
                    if n == 0 {
                        break;
                    }
                    read_bytes += n;
                }

                if read_bytes == 0 {
                    // Fin naturelle du flux
                    break;
                } else if read_bytes == 1 {
                    return Err(io::Error::new(
                        io::ErrorKind::UnexpectedEof,
                        "Flux RLE tronqué : demi-paire lue",
                    ));
                }

                let count = pair[0];
                let byte = pair[1];

                if count == 0 {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "Format RLE invalide : répétition nulle",
                    ));
                }

                self.current_byte = byte;
                self.remaining_count = count;
            }
        }

        Ok(written)
    }
}

