    println!("=== Démonstration RLE sur flux binaires natifs ===");

    // Données de démonstration avec plusieurs motifs
    let raw_sample = b"AAAAABBBBBBBCCCCCDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDEEEEEFFFFFF";
    println!("1. Données d'origine : {} octets", raw_sample.len());

