    );
    println!("   Format hexadécimal : {:02X?}", compressed_output);

    // 2. Décompression par fonction directe
    let mut decompressed_output = Vec::new();
    let bytes_decoded = decode_rle_strict(&mut &compressed_output[..], &mut decompressed_output)?;
    println!(
        "3. Données décompressées : {} octets (décodés: {})",
        decompressed_output.len(),
        bytes_decoded
    );

    assert_eq!(&raw_sample[..], &decompressed_output[..]);
    println!("-> Intégrité vérifiée avec succès !\n");

    // 3. Démonstration avec les wrappers de streaming RleEncoder et RleDecoder
    println!("=== Démonstration Streaming RleEncoder / RleDecoder ===");
    let mut streaming_compressed = Vec::new();
    {
