```rust
// src/main.rs
use std::fs::File;
use std::io::{BufRead, BufReader, Read, Write};
use std::net::{TcpListener, TcpStream};
use std::path::{Component, Path, PathBuf};

const BIND_ADDR: &str = "127.0.0.1:8080";
const ROOT_DIR: &str = "./public";

fn main() -> std::io::Result<()> {
    let listener = TcpListener::bind(BIND_ADDR)?;
    println!("Serveur HTTP démarré sur http://{BIND_ADDR}");
    println!("Dossier servi : '{ROOT_DIR}'");

    for stream_res in listener.incoming() {
        match stream_res {
            Ok(stream) => {
                if let Err(e) = handle_client(stream) {
                    eprintln!("Erreur lors du traitement de la requête : {e}");
                }
            }
            Err(e) => {
                eprintln!("Erreur d'acceptation de connexion : {e}");
            }
        }
    }

    Ok(())
}

fn handle_client(mut stream: TcpStream) -> std::io::Result<()> {
    let mut reader = BufReader::new(&stream);
    let mut request_line = String::new();

    if reader.read_line(&mut request_line)? == 0 {
        return Ok(());
    }

    let mut parts = request_line.split_whitespace();
    let method = parts.next().unwrap_or("");
    let raw_path = parts.next().unwrap_or("");

    // Drainer le reste des en-têtes HTTP
    let mut header_line = String::new();
    loop {
        header_line.clear();
        let bytes_read = reader.read_line(&mut header_line)?;
        if bytes_read == 0 || header_line == "\r\n" || header_line == "\n" {
            break;
        }
    }

    // Support des méthodes GET et HEAD uniquement
    if method != "GET" && method != "HEAD" {
        return send_response(
            &mut stream,
            "405 Method Not Allowed",
            "text/plain; charset=utf-8",
            b"405 Method Not Allowed",
            method == "HEAD",
        );
    }

    // Résolution sécurisée du chemin pour éviter les traversées de répertoire
    let target_path = match sanitize_path(ROOT_DIR, raw_path) {
        Some(path) => path,
        None => {
            return send_response(
                &mut stream,
                "403 Forbidden",
                "text/plain; charset=utf-8",
                b"403 Forbidden: Invalid path",
                method == "HEAD",
            );
        }
    };

    // Gestion du cas où la cible est un dossier : chercher index.html
    let final_path = if target_path.is_dir() {
        target_path.join("index.html")
    } else {
        target_path
    };

    if !final_path.exists() {
        return send_response(
            &mut stream,
            "404 Not Found",
            "text/plain; charset=utf-8",
            b"404 Not Found",
            method == "HEAD",
        );
    }

    let mut file = match File::open(&final_path) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("Impossible d'ouvrir le fichier {:?}: {}", final_path, e);
            return send_response(
                &mut stream,
                "500 Internal Server Error",
                "text/plain; charset=utf-8",
                b"500 Internal Server Error",
                method == "HEAD",
            );
        }
    };

    let metadata = match file.metadata() {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Erreur lecture metadata {:?}: {}", final_path, e);
            return send_response(
                &mut stream,
                "500 Internal Server Error",
                "text/plain; charset=utf-8",
                b"500 Internal Server Error",
                method == "HEAD",
            );
        }
    };

    let content_len = metadata.len();
    let mime_type = mime_guess::from_path(&final_path)
        .first_or_octet_stream()
        .to_string();

    let response_headers = format!(
        "HTTP/1.1 200 OK\r\n\
         Content-Type: {mime_type}\r\n\
         Content-Length: {content_len}\r\n\
         Connection: close\r\n\r\n"
    );

    stream.write_all(response_headers.as_bytes())?;

    if method == "GET" {
        let mut buffer = [0u8; 8192];
        loop {
            let n = file.read(&mut buffer)?;
            if n == 0 {
                break;
            }
            stream.write_all(&buffer[..n])?;
        }
    }

    stream.flush()?;
    Ok(())
}

fn sanitize_path(base_dir: &str, raw_path: &str) -> Option<PathBuf> {
    // Découper d'éventuels paramètres d'URL (?foo=bar ou ancre #)
    let clean_path = raw_path
        .split('?')
        .next()?
        .split('#')
        .next()?;

    let mut resolved = PathBuf::from(base_dir);

    // Parcourir chaque composant normalisé pour contrer le Path Traversal
    for component in Path::new(clean_path).components() {
        match component {
            Component::Normal(segment) => resolved.push(segment),
            Component::RootDir => {} // Évite de réinitialiser le chemin relatif
            Component::CurDir => {}
            Component::ParentDir | Component::Prefix(_) => return None,
        }
    }

    Some(resolved)
}

fn send_response(
    stream: &mut TcpStream,
    status: &str,
    content_type: &str,
    body: &[u8],
    head_only: bool,
) -> std::io::Result<()> {
    let headers = format!(
        "HTTP/1.1 {status}\r\n\
         Content-Type: {content_type}\r\n\
         Content-Length: {}\r\n\
         Connection: close\r\n\r\n",
        body.len()
    );

    stream.write_all(headers.as_bytes())?;
    if !head_only {
        stream.write_all(body)?;
    }
    stream.flush()?;
    Ok(())
}

