```rust
// src/main.rs
use std::any::{Any, TypeId};
use std::collections::HashMap;
use std::fmt;
use std::sync::mpsc::{self, Receiver, SendError, SyncSender};
use std::sync::atomic::{AtomicU64, Ordering};

/// Identifiant unique d'un abonnement.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct SubscriptionId(u64);

impl fmt::Display for SubscriptionId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Sub#{}", self.0)
    }
}

/// Erreurs possibles du système Pub/Sub.
#[derive(Debug, PartialEq, Eq)]
pub enum PubSubError {
    /// L'abonnement spécifié n'existe pas ou a déjà été retiré.
    SubscriptionNotFound(SubscriptionId),
}

impl fmt::Display for PubSubError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            PubSubError::SubscriptionNotFound(id) => {
                write!(f, "Abonnement non trouvé : {}", id)
            }
        }
    }
}

impl std::error::Error for PubSubError {}

/// Trait d'événement requis : tout type émis doit être Clone, Send et 'static.
pub trait Event: Any + Clone + Send + 'static {}
impl<T: Any + Clone + Send + 'static> Event for T {}

/// Trait dynamique pour dispatcher les événements sans connaître statiquement le type à l'enregistrement.
trait DynSubscriber: Send + 'static {
    /// Tente de délivrer l'événement sous forme de référence dynamique.
    /// Renvoie `Ok(())` si envoyé, ou `Err(())` si le canal est déconnecté/plein.
    fn dispatch(&self, event: &dyn Any) -> Result<(), ()>;
    /// Identifiant unique de cet abonné.
    fn id(&self) -> SubscriptionId;
}

/// Abonné typé reposant sur un canal `std::sync::mpsc::SyncSender`.
struct ChannelSubscriber<E: Event> {
    id: SubscriptionId,
    sender: SyncSender<E>,
}

impl<E: Event> DynSubscriber for ChannelSubscriber<E> {
    fn dispatch(&self, event: &dyn Any) -> Result<(), ()> {
        if let Some(concrete_event) = event.downcast_ref::<E>() {
            self.sender.send(concrete_event.clone()).map_err(|SendError(_)| ())
        } else {
            // Le type ne correspond pas à ce canal
            Ok(())
        }
    }

    fn id(&self) -> SubscriptionId {
        self.id
    }
}

/// Poignée d'abonnement retournée à l'utilisateur.
pub struct Subscription<E: Event> {
    pub id: SubscriptionId,
    pub receiver: Receiver<E>,
}

/// Gestionnaire d'événements Pub/Sub synchrone en mémoire.
pub struct EventBus {
    next_id: AtomicU64,
    subscribers: HashMap<TypeId, Vec<Box<dyn DynSubscriber>>>,
}

impl EventBus {
    /// Crée un nouveau bus d'événements.
    pub fn new() -> Self {
        Self {
            next_id: AtomicU64::new(1),
            subscribers: HashMap::new(),
        }
    }

    fn next_subscription_id(&self) -> SubscriptionId {
        SubscriptionId(self.next_id.fetch_add(1, Ordering::Relaxed))
    }

    /// Abonne un récepteur à un type d'événement `E`.
    /// `buffer_size` spécifie la capacité du tampon synchrone (`SyncSender`).
    pub fn subscribe<E: Event>(&mut self, buffer_size: usize) -> Subscription<E> {
        let id = self.next_subscription_id();
        let (sender, receiver) = mpsc::sync_channel::<E>(buffer_size);

        let subscriber = ChannelSubscriber { id, sender };
        let type_id = TypeId::of::<E>();

        self.subscribers
            .entry(type_id)
            .or_default()
            .push(Box::new(subscriber));

        Subscription { id, receiver }
    }

    /// Publie un événement à tous les abonnés enregistrés pour le type `E`.
    /// Nettoie automatiquement les abonnés dont les récepteurs ont été fermés.
    pub fn publish<E: Event>(&mut self, event: E) -> usize {
        let type_id = TypeId::of::<E>();
        let mut delivered_count = 0;

        if let Some(subs) = self.subscribers.get_mut(&type_id) {
            let any_event: &dyn Any = &event;
            // On conserve uniquement les abonnés toujours actifs (canal ouvert)
            subs.retain(|sub| {
                match sub.dispatch(any_event) {
                    Ok(()) => {
                        delivered_count += 1;
                        true
                    }
                    Err(()) => {
                        // Récepteur détruit ou canal fermé : supprimer l'abonné
                        false
                    }
                }
            });
        }

        delivered_count
    }

    /// Désabonne un abonné via son identifiant `SubscriptionId`.
    pub fn unsubscribe(&mut self, id: SubscriptionId) -> Result<(), PubSubError> {
        let mut found = false;

        for subs in self.subscribers.values_mut() {
            let initial_len = subs.len();
            subs.retain(|sub| sub.id() != id);
            if subs.len() < initial_len {
                found = true;
                break;
            }
        }

        if found {
            Ok(())
        } else {
            Err(PubSubError::SubscriptionNotFound(id))
        }
    }

    /// Retourne le nombre total d'abonnés actifs pour tous types confondus.
    pub fn total_subscribers(&self) -> usize {
        self.subscribers.values().map(|v| v.len()).sum()
    }
}

impl Default for EventBus {
    fn default() -> Self {
        Self::new()
    }
}

// ==========================================
// Types d'événements pour la démonstration
// ==========================================

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct UserRegistered {
    pub user_id: u32,
    pub username: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OrderPlaced {
    pub order_id: u64,
    pub amount_cents: u32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NotificationAlert {
    pub severity: String,
    pub message: String,
}

fn main() {
    println!("=== Démarrage du gestionnaire Pub/Sub Synchrone ===");

    let mut bus = EventBus::new();

    // 1. Souscriptions
    let sub_user_1 = bus.subscribe::<UserRegistered>(10);
    let sub_user_2 = bus.subscribe::<UserRegistered>(10);
    let sub_order = bus.subscribe::<OrderPlaced>(5);

    println!(
        "Abonnés initialement enregistrés : {} abonnements actifs.",
        bus.total_subscribers()
    );

    // 2. Publication d'un premier événement UserRegistered
    let event1 = UserRegistered {
        user_id: 42,
        username: "Alice".to_string(),
    };
    println!("\n[Publication] {:?}", event1);
    let delivered = bus.publish(event1);
    println!("-> Délivré à {} abonné(s)", delivered);

    // Consommation synchrone via les récepteurs
    if let Ok(msg) = sub_user_1.receiver.try_recv() {
        println!("Service Audit a reçu : [User #{}: {}]", msg.user_id, msg.username);
    }
    if let Ok(msg) = sub_user_2.receiver.try_recv() {
        println!("Service Bienvenue a reçu : [User #{}: {}]", msg.user_id, msg.username);
    }

    // 3. Publication d'un événement OrderPlaced
    let event_order = OrderPlaced {
        order_id: 1001,
        amount_cents: 4999,
    };
    println!("\n[Publication] {:?}", event_order);
    bus.publish(event_order);

    if let Ok(order) = sub_order.receiver.try_recv() {
        println!(
            "Service Facturation a reçu la commande #{} pour {} €",
            order.order_id,
            order.amount_cents as f64 / 100.0
        );
    }

    // 4. Test du nettoyage automatique lors de la fermeture d'un récepteur
    println!("\n[Test de déconnexion automatique]");
    let sub_id_to_drop = sub_user_1.id;
    drop(sub_user_1); // Ferme le canal de sub_user_1
    println!("Abonnement {} abandonné (récepteur dropped).", sub_id_to_drop);

    let event2 = UserRegistered {
        user_id: 84,
        username: "Bob".to_string(),
    };
    println!("[Publication] {:?}", event2);
    let delivered = bus.publish(event2);
    println!(
        "-> Délivré à {} abonné(s) (l'abonné déconnecté a été automatiquement purgé).",
        delivered
    );

    if let Ok(msg) = sub_user_2.receiver.try_recv() {
        println!("Service Bienvenue a bien reçu : [User #{}: {}]", msg.user_id, msg.username);
    }

    // 5. Test de désabonnement explicite
    println!("\n[Test de désabonnement explicite]");
    match bus.unsubscribe(sub_user_2.id) {
        Ok(()) => println!("Désabonnement réussi pour {}", sub_user_2.id),
        Err(e) => eprintln!("Erreur lors du désabonnement : {}", e),
    }

    println!(
        "Total d'abonnés restant dans le bus : {}",
        bus.total_subscribers()
    );

    println!("\n=== Démonstration terminée avec succès ===");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_pub_sub_single_subscriber() {
        let mut bus = EventBus::new();
        let sub = bus.subscribe::<UserRegistered>(2);

        let event = UserRegistered {
            user_id: 1,
            username: "Charlie".to_string(),
        };

        let delivered = bus.publish(event.clone());
        assert_eq!(delivered, 1);

        let received = sub.receiver.try_recv().expect("Message attendu");
        assert_eq!(received, event);
    }

    #[test]
    fn test_multiple_subscribers_same_event() {
        let mut bus = EventBus::new();
        let sub1 = bus.subscribe::<OrderPlaced>(5);
        let sub2 = bus.subscribe::<OrderPlaced>(5);

        let event = OrderPlaced {
            order_id: 99,
            amount_cents: 1200,
        };

        let count = bus.publish(event.clone());
        assert_eq!(count, 2);

        assert_eq!(sub1.receiver.try_recv().unwrap(), event);
        assert_eq!(sub2.receiver.try_recv().unwrap(), event);
    }

    #[test]
    fn test_heterogeneous_event_types() {
        let mut bus = EventBus::new();
        let sub_user = bus.subscribe::<UserRegistered>(2);
        let sub_alert = bus.subscribe::<NotificationAlert>(2);

        bus.publish(NotificationAlert {
            severity: "WARN".to_string(),
            message: "Disque presque plein".to_string(),
        });

        // L'abonné UserRegistered ne doit rien recevoir
        assert!(sub_user.receiver.try_recv().is_err());

        // L'abonné NotificationAlert doit recevoir
        let alert = sub_alert.receiver.try_recv().expect("Alerte attendue");
        assert_eq!(alert.severity, "WARN");
    }

    #[test]
    fn test_auto_cleanup_on_drop() {
        let mut bus = EventBus::new();
        let sub1 = bus.subscribe::<OrderPlaced>(2);
        let sub2 = bus.subscribe::<OrderPlaced>(2);

        assert_eq!(bus.total_subscribers(), 2);
        drop(sub1);

        let delivered = bus.publish(OrderPlaced {
            order_id: 1,
            amount_cents: 10,
        });

        assert_eq!(delivered, 1);
        assert_eq!(bus.total_subscribers(), 1);
        assert_eq!(sub2.receiver.try_recv().unwrap().order_id, 1);
    }

    #[test]
    fn test_explicit_unsubscribe() {
        let mut bus = EventBus::new();
        let sub = bus.subscribe::<UserRegistered>(2);
        let sub_id = sub.id;

        assert_eq!(bus.total_subscribers(), 1);
        assert!(bus.unsubscribe(sub_id).is_ok());
        assert_eq!(bus.total_subscribers(), 0);

        // Tentative de ré-annulation
        assert_eq!(
            bus.unsubscribe(sub_id),
            Err(PubSubError::SubscriptionNotFound(sub_id))
        );
    }
}

