// src/main.rs
//! Générateur et vérificateur de sommes de contrôle CRC32 (IEEE 802.3).
//! Calcul bit-à-bit (bitwise) sans table de précalcul ni crate tierce,
//! exploitant `std::io::Read` pour traiter des flux de données arbitrairement grands.

use std::error::Error;
use std::fmt;
use std::fs::File;
use std::io::{self, BufRead, BufReader, Read};
use std::path::{Path, PathBuf};
use std::process::ExitCode;

/// Polynôme standard IEEE 802.3 en représentation inversée (LSB-first / reflected).
pub const CRC32_POLYNOMIAL_REFLECTED: u32 = 0xEDB8_8320;

/// Valeur d'initialisation du registre CRC-32.
pub const CRC32_INITIAL: u32 = 0xFFFF_FFFF;

/// Valeur de XOR final appliquée au registre.
pub const CRC32_FINAL_XOR: u32 = 0xFFFF_FFFF;

/// Structure de calcul CRC32 bitwise (bit-à-bit).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Crc32 {
    state: u32,
}

impl Default for Crc32 {
    fn default() -> Self {
        Self::new()
    }
}

impl Crc32 {
    /// Crée un nouvel accumulateur CRC32 initialisé.
    #[must_use]
    pub const fn new() -> Self {
        Self {
            state: CRC32_INITIAL,
        }
    }

    /// Réinitialise l'accumulateur à sa valeur de départ.
    pub fn reset(&mut self) {
        self.state = CRC32_INITIAL;
    }

    /// Met à jour la somme avec un octet individuel par décalages de bits stricts.
    pub fn update_byte(&mut self, byte: u8) {
        self.state ^= u32::from(byte);
        for _ in 0..8 {
            if (self.state & 1) != 0 {
                self.state = (self.state >> 1) ^ CRC32_POLYNOMIAL_REFLECTED;
            } else {
                self.state >>= 1;
            }
        }
    }

    /// Met à jour la somme avec une tranche d'octets.
    pub fn update(&mut self, data: &[u8]) {
        for &byte in data {
            self.update_byte(byte);
        }
    }

    /// Consomme un flux implémentant `std::io::Read` par blocs tampons de 8 Ko.
    ///
    /// Renvoie le nombre total d'octets lus ou une erreur d'E/S.
    pub fn update_from_reader<R: Read>(&mut self, mut reader: R) -> io::Result<u64> {
        let mut buffer = [0u8; 8192];
        let mut total_bytes = 0u64;

        loop {
            match reader.read(&mut buffer) {
                Ok(0) => break,
                Ok(read_bytes) => {
                    self.update(&buffer[..read_bytes]);
                    total_bytes += read_bytes as u64;
                }
                Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
                Err(e) => return Err(e),
            }
        }

        Ok(total_bytes)
    }

    /// Finalise le calcul et renvoie le CRC32 sous forme de `u32`.
    #[must_use]
    pub const fn finalize(&self) -> u32 {
        self.state ^ CRC32_FINAL_XOR
    }

    /// Calcule directement la somme CRC32 d'un lecteur `std::io::Read`.
    pub fn digest_reader<R: Read>(reader: R) -> io::Result<u32> {
        let mut crc = Self::new();
        crc.update_from_reader(reader)?;
        Ok(crc.finalize())
    }

    /// Calcule directement la somme CRC32 d'une tranche d'octets en mémoire.
    #[must_use]
    pub fn digest_slice(data: &[u8]) -> u32 {
        let mut crc = Self::new();
        crc.update(data);
        crc.finalize()
    }
}

/// Gestion des erreurs applicatives.
#[derive(Debug)]
pub enum CliError {
    Io(io::Error),
    InvalidHexChecksum(String),
    MalformedCheckLine(String),
    MissingArgument(String),
    ChecksumMismatch {
        file: String,
        expected: u32,
        actual: u32,
    },
}

impl fmt::Display for CliError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Io(err) => write!(f, "Erreur E/S: {err}"),
            Self::InvalidHexChecksum(s) => {
                write!(f, "Somme de contrôle hexadécimale invalide: '{s}'")
            }
            Self::MalformedCheckLine(line) => {
                write!(f, "Ligne de fichier de vérification non valide: '{line}'")
            }
            Self::MissingArgument(arg) => write!(f, "Argument requis manquant: {arg}"),
            Self::ChecksumMismatch {
                file,
                expected,
                actual,
            } => {
                write!(
                    f,
                    "Échec de concordance pour '{file}': attendu {expected:08x}, calculé {actual:08x}"
                )
            }
        }
    }
}

impl Error for CliError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Io(err) => Some(err),
            _ => None,
        }
    }
}

impl From<io::Error> for CliError {
    fn from(err: io::Error) -> Self {
        Self::Io(err)
    }
}

/// Modes d'exécution du programme.
enum Mode {
    Generate(Vec<PathBuf>),
    VerifySingle { expected: u32, path: PathBuf },
    CheckFile(PathBuf),
    Help,
}

fn parse_hex_crc(input: &str) -> Result<u32, CliError> {
    let clean = input.trim().trim_start_matches("0x").trim_start_matches("0X");
    u32::from_str_radix(clean, 16).map_err(|_| CliError::InvalidHexChecksum(input.to_string()))
}

fn parse_args() -> Result<Mode, CliError> {
    let mut args: Vec<String> = std::env::args().skip(1).collect();

    if args.is_empty() {
        // Par défaut sans argument : lecture sur stdin
        return Ok(Mode::Generate(vec![PathBuf::from("-")]));
    }

    match args[0].as_str() {
        "-h" | "--help" | "help" => Ok(Mode::Help),
        "-c" | "--check" => {
            if args.len() < 2 {
                return Err(CliError::MissingArgument(
                    "chemin vers le fichier de vérification pour --check".to_string(),
                ));
            }
            Ok(Mode::CheckFile(PathBuf::from(&args[1])))
        }
        "-v" | "--verify" => {
            if args.len() < 3 {
                return Err(CliError::MissingArgument(
                    "usage: --verify <SOMME_HEX> <FICHIER>".to_string(),
                ));
            }
            let expected = parse_hex_crc(&args[1])?;
            let path = PathBuf::from(&args[2]);
            Ok(Mode::VerifySingle { expected, path })
        }
        _ => {
            let paths = args.drain(..).map(PathBuf::from).collect();
            Ok(Mode::Generate(paths))
        }
    }
}

fn print_help(program_name: &str) {
    println!("Générateur et vérificateur de sommes de contrôle CRC32 bitwise (sans crate externe)");
    println!();
    println!("USAGE:");
    println!("    {program_name} [OPTIONS] [FICHIERS...]");
    println!();
    println!("OPTIONS:");
    println!("    -h, --help                     Affiche cette aide");
    println!("    -c, --check <FICHIER_SOMMES>   Vérifie les sommes depuis un fichier de hachages");
    println!("    -v, --verify <HEX> <FICHIER>   Vérifie directement un fichier contre une somme attendue");
    println!();
    println!("EXEMPLES:");
    println!("    {program_name} fichier.iso");
    println!("    {program_name} file1.bin file2.bin > checksums.crc32");
    println!("    {program_name} -c checksums.crc32");
    println!("    {program_name} -v cbf43926 test.txt");
    println!("    echo -n '123456789' | {program_name} -");
}

fn compute_path_crc(path: &Path) -> Result<u32, CliError> {
    if path == Path::new("-") {
        let stdin = io::stdin();
        let handle = stdin.lock();
        Ok(Crc32::digest_reader(handle)?)
    } else {
        let file = File::open(path)?;
        let reader = BufReader::new(file);
        Ok(Crc32::digest_reader(reader)?)
    }
}

fn run_generate(paths: &[PathBuf]) -> Result<bool, CliError> {
    let mut all_ok = true;
    for path in paths {
        let display_name = path.to_string_lossy();
        match compute_path_crc(path) {
            Ok(crc) => {
                println!("{crc:08x}  {display_name}");
            }
            Err(e) => {
                eprintln!("{display_name}: {e}");
                all_ok = false;
            }
        }
    }
    Ok(all_ok)
}

fn run_verify_single(expected: u32, path: &Path) -> Result<bool, CliError> {
    let display_name = path.to_string_lossy();
    let actual = compute_path_crc(path)?;
    if actual == expected {
        println!("{display_name}: OK");
        Ok(true)
    } else {
        eprintln!("{display_name}: ÉCHEC (attendu: {expected:08x}, obtenu: {actual:08x})");
        Ok(false)
    }
}

fn run_check_file(check_file_path: &Path) -> Result<bool, CliError> {
    let file = File::open(check_file_path)?;
    let reader = BufReader::new(file);
    let mut total = 0usize;
    let mut successes = 0usize;
    let mut failures = 0usize;

    for (line_idx, line_res) in reader.lines().enumerate() {
        let line = line_res?;
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        total += 1;
        // Format attendu standard : "<crc_hex>  <chemin>" ou "<crc_hex> *<chemin>"
        let parts: Vec<&str> = trimmed.split_whitespace().collect();
        if parts.len() < 2 {
            eprintln!(
                "{}:{}: ligne mal formée",
                check_file_path.display(),
                line_idx + 1
            );
            failures += 1;
            continue;
        }

        let expected = match parse_hex_crc(parts[0]) {
            Ok(v) => v,
            Err(_) => {
                eprintln!(
                    "{}:{}: somme CRC non hexadécimale '{}'",
                    check_file_path.display(),
                    line_idx + 1,
                    parts[0]
                );
                failures += 1;
                continue;
            }
        };

        // Gérer les chemins contenant potentiellement des espaces si split_whitespace a découpé
        let target_str = trimmed[parts[0].len()..].trim();
        let cleaned_target = target_str.strip_prefix('*').unwrap_or(target_str).trim();
        let target_path = PathBuf::from(cleaned_target);

        match compute_path_crc(&target_path) {
            Ok(actual) => {
                if actual == expected {
                    println!("{cleaned_target}: OK");
                    successes += 1;
                } else {
                    println!("{cleaned_target}: ÉCHEC");
                    failures += 1;
                }
            }
            Err(e) => {
                eprintln!("{cleaned_target}: IMPOSSIBLE D'OUVRIR OU LIRE ({e})");
                failures += 1;
            }
        }
    }

    if failures > 0 {
        eprintln!(
            "AVERTISSEMENT: {failures} somme(s) de contrôle sur {total} ne concordent pas."
        );
        Ok(false)
    } else {
        println!("{successes} fichier(s) vérifié(s) avec succès.");
        Ok(true)
    }
}

fn main() -> ExitCode {
    let mode = match parse_args() {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Erreur de syntaxe: {e}");
            eprintln!("Utilisez --help pour voir les options disponibles.");
            return ExitCode::from(2);
        }
    };

    let result = match mode {
        Mode::Help => {
            let prog_name = std::env::args()
                .next()
                .unwrap_or_else(|| "crc32_bitwise".to_string());
            print_help(&prog_name);
            Ok(true)
        }
        Mode::Generate(paths) => run_generate(&paths),
        Mode::VerifySingle { expected, path } => run_verify_single(expected, &path),
        Mode::CheckFile(path) => run_check_file(&path),
    };

    match result {
        Ok(true) => ExitCode::SUCCESS,
        Ok(false) => ExitCode::from(1),
        Err(e) => {
            eprintln!("Erreur: {e}");
            ExitCode::from(2)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Cursor;

    #[test]
    fn test_crc32_standard_empty() {
        let crc = Crc32::digest_slice(b"");
        assert_eq!(crc, 0x0000_0000);
    }

    #[test]
    fn test_crc32_standard_vector_123456789() {
        // Vecteur de test standard IEEE 802.3
        let input = b"123456789";
        let crc = Crc32::digest_slice(input);
        assert_eq!(crc, 0xCBF4_3926);
    }

    #[test]
    fn test_crc32_quick_brown_fox() {
        let input = b"The quick brown fox jumps over the lazy dog";
        let crc = Crc32::digest_slice(input);
        assert_eq!(crc, 0x414F_A339);
    }

    #[test]
    fn test_crc32_reader_streaming() {
        let data = b"123456789".repeat(1000); // 9000 octets pour dépasser le buffer de 8Ko
        let direct_crc = Crc32::digest_slice(&data);

        let cursor = Cursor::new(&data);
        let stream_crc = Crc32::digest_reader(cursor).expect("Lecture flux cursor");

        assert_eq!(direct_crc, stream_crc);
    }

    #[test]
    fn test_crc32_reset() {
        let mut crc = Crc32::new();
        crc.update(b"test data");
        crc.reset();
        crc.update(b"123456789");
        assert_eq!(crc.finalize(), 0xCBF4_3926);
