// src/main.rs
use std::cmp::Ordering;
use std::fmt::{self, Display, Formatter};

/// Niveaux de priorité discrets pour les tâches système.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum PriorityLevel {
    Low = 0,
    Normal = 1,
    High = 2,
    Critical = 3,
}

impl Display for PriorityLevel {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        let label = match self {
            PriorityLevel::Low => "BASSE",
            PriorityLevel::Normal => "NORMALE",
            PriorityLevel::High => "HAUTE",
            PriorityLevel::Critical => "CRITIQUE",
        };
        write!(f, "{label}")
    }
}

/// Tâche gérée par le simulateur.
/// Le tri personnalisé est délégué à l'implémentation explicite de [`Ord`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SystemTask {
    pub id: u64,
    pub priority: PriorityLevel,
    /// Échéance cible (tick ou timestamp). Plus petit = plus urgent.
    pub deadline: u64,
    /// Durée de traitement estimée. Plus court = prioritaire à échéance égale.
    pub cost: u32,
    pub description: String,
    pub arrival_time: u64,
}

impl SystemTask {
    pub fn new(
        id: u64,
        priority: PriorityLevel,
        deadline: u64,
        cost: u32,
        description: impl Into<String>,
        arrival_time: u64,
    ) -> Self {
        Self {
            id,
            priority,
            deadline,
            cost,
            description: description.into(),
            arrival_time,
        }
    }
}

/// Implémentation personnalisée du trait [`Ord`] pour [`SystemTask`].
///
/// Logique de comparaison (Ordre Max-Heap : la tâche considérée comme `Greater` sera extraite en premier) :
/// 1. Priorité intrinsèque : `Critical` > `High` > `Normal` > `Low`
/// 2. Échéance (Earliest Deadline First) : échéance la plus petite prioritaire (d'où l'inversion `other.deadline.cmp(&self.deadline)`)
/// 3. Coût (Shortest Job First) : coût le plus court prioritaire (inversion `other.cost.cmp(&self.cost)`)
/// 4. Identifiant : déterminisme absolu (inversion `other.id.cmp(&self.id)`)
impl Ord for SystemTask {
    fn cmp(&self, other: &Self) -> Ordering {
        self.priority
            .cmp(&other.priority)
            .then_with(|| other.deadline.cmp(&self.deadline))
            .then_with(|| other.cost.cmp(&self.cost))
            .then_with(|| other.id.cmp(&self.id))
    }
}

impl PartialOrd for SystemTask {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Display for SystemTask {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "[Tâche #{:<2} | {:^8} | Échéance: t={:<3} | Coût: {:<2} | Arrivée: t={:<2}] {}",
            self.id, self.priority, self.deadline, self.cost, self.arrival_time, self.description
        )
    }
}

/// Implémentation générique d'un tas binaire (Binary Max-Heap).
#[derive(Debug, Clone, Default)]
pub struct BinaryHeapQueue<T: Ord> {
    data: Vec<T>,
}

impl<T: Ord> BinaryHeapQueue<T> {
    /// Crée un nouveau tas binaire vide.
    pub fn new() -> Self {
        Self { data: Vec::new() }
    }

    /// Crée un tas binaire avec une capacité préallouée.
    pub fn with_capacity(capacity: usize) -> Self {
        Self {
            data: Vec::with_capacity(capacity),
        }
    }

    /// Nombre d'éléments présents dans la file.
    pub fn len(&self) -> usize {
        self.data.len()
    }

    /// Indique si la file est vide.
    pub fn is_empty(&self) -> bool {
        self.data.is_empty()
    }

    /// Référence vers l'élément le plus prioritaire sans l'extraire.
    pub fn peek(&self) -> Option<&T> {
        self.data.first()
    }

    /// Insère un élément dans le tas en $O(\log n)$.
    pub fn push(&mut self, item: T) {
        self.data.push(item);
        let last_index = self.data.len().saturating_sub(1);
        self.sift_up(last_index);
    }

    /// Extrait l'élément ayant la plus haute priorité en $O(\log n)$.
    pub fn pop(&mut self) -> Option<T> {
        if self.data.is_empty() {
            return None;
        }

        let last_index = self.data.len() - 1;
        self.data.swap(0, last_index);
        let root = self.data.pop();

        if !self.data.is_empty() {
            self.sift_down(0);
        }

        root
    }

    /// Rétablit l'invariant de tas vers le haut.
    fn sift_up(&mut self, mut index: usize) {
        while index > 0 {
            let parent = (index - 1) / 2;
            if self.data[index] > self.data[parent] {
                self.data.swap(index, parent);
                index = parent;
            } else {
                break;
            }
        }
    }

    /// Rétablit l'invariant de tas vers le bas.
    fn sift_down(&mut self, mut index: usize) {
        let len = self.data.len();
        loop {
            let left_child = 2 * index + 1;
            let right_child = 2 * index + 2;
            let mut largest = index;

            if left_child < len && self.data[left_child] > self.data[largest] {
                largest = left_child;
            }

            if right_child < len && self.data[right_child] > self.data[largest] {
                largest = right_child;
            }

            if largest != index {
                self.data.swap(index, largest);
                index = largest;
            } else {
                break;
            }
        }
    }
}

/// Simulateur de planification de tâches.
pub struct TaskSchedulerSimulator {
    queue: BinaryHeapQueue<SystemTask>,
    current_tick: u64,
    completed_tasks: Vec<(SystemTask, u64)>, // (Tâche, tick de fin)
}

impl TaskSchedulerSimulator {
    pub fn new() -> Self {
        Self {
            queue: BinaryHeapQueue::new(),
            current_tick: 0,
            completed_tasks: Vec::new(),
        }
    }

    /// Charge une tâche dans le planificateur.
    pub fn schedule(&mut self, task: SystemTask) {
        println!("  📥 [t={}] Enregistrement : {}", self.current_tick, task);
        self.queue.push(task);
    }

    /// Exécute toutes les tâches en file jusqu'à épuisement.
    pub fn run_simulation(&mut self) {
        println!("\n=== DÉBUT DE LA SIMULATION DU TAS BINAIRE ===");

        while let Some(task) = self.queue.pop() {
            if self.current_tick < task.arrival_time {
                self.current_tick = task.arrival_time;
            }

            let wait_time = self.current_tick.saturating_sub(task.arrival_time);
            println!(
                "  ⚙️ [t={}] Exécution : ID #{} ('{}') | Attente: {} ticks | Coût: {} ticks",
                self.current_tick, task.id, task.description, wait_time, task.cost
            );

            self.current_tick += task.cost as u64;
            let finish_time = self.current_tick;
            let respected = finish_time <= task.deadline;

            let deadline_status = if respected {
                "✅ Échéance respectée".to_string()
            } else {
                let delay = finish_time.saturating_sub(task.deadline);
                format!("⚠️ Échéance dépassée (+{delay} ticks)")
            };

            println!(
                "  🏁 [t={}] Terminée  : ID #{} | Statut: {}",
                finish_time, task.id, deadline_status
            );

            self.completed_tasks.push((task, finish_time));
        }

        println!("=== FIN DE LA SIMULATION ===\n");
    }

    /// Génère un bilan chiffré de la simulation.
    pub fn print_report(&self) {
        let total = self.completed_tasks.len();
        if total == 0 {
            println!("Aucune tâche n'a été traitée.");
            return;
        }

        let mut total_turnaround: u64 = 0;
        let mut total_waiting: u64 = 0;
        let mut met_deadlines: usize = 0;

        for (task, finish_time) in &self.completed_tasks {
            let turnaround = finish_time.saturating_sub(task.arrival_time);
            let wait = turnaround.saturating_sub(task.cost as u64);
            total_turnaround += turnaround;
            total_waiting += wait;
            if *finish_time <= task.deadline {
                met_deadlines += 1;
            }
        }

        let avg_waiting = total_waiting as f64 / total as f64;
        let avg_turnaround = total_turnaround as f64 / total as f64;
        let deadline_rate = (met_deadlines as f64 / total as f64) * 100.0;

        println!("╔════════════════════════════════════════════════════════╗");
        println!("║                 RAPPORT DE PERFORMANCE                 ║");
        println!("╠════════════════════════════════════════════════════════╣");
