// src/main.rs
use std::fs;
use std::path::PathBuf;
use std::process::ExitCode;

use clap::Parser;
use colored::*;
use thiserror::Error;

#[derive(Error, Debug)]
pub enum InspectError {
    #[error("Erreur d'accès I/O au fichier '{path}': {source}")]
    Io {
        path: PathBuf,
        #[source]
        source: std::io::Error,
    },
    #[error("Le fichier est trop petit ({size} octets) pour être un exécutable valide")]
    FileTooSmall { size: usize },
    #[error("Signature magique non reconnue: ni ELF ni PE/MZ")]
    UnknownFormat,
    #[error("Données tronquées à l'offset {offset:#x}: {field} manquant")]
    Truncated { offset: usize, field: &'static str },
    #[error("Format invalide pour {format}: {reason}")]
    InvalidFormat {
        format: &'static str,
        reason: String,
    },
}

#[derive(Parser, Debug)]
#[command(
    name = "bin-inspect",
    author = "Damien",
    version = "0.1.0",
    about = "Inspecteur d'en-têtes de binaires ELF et PE (lecture sécurisée de slices d'octets)"
)]
struct Cli {
    /// Chemin du fichier binaire à inspecter
    #[arg(value_name = "FICHIER")]
    file: PathBuf,

    /// Afficher la table détaillée des sections
    #[arg(short = 's', long = "sections")]
    show_sections: bool,

    /// Dump hexadécimal des N premiers octets d'une section spécifique
    #[arg(long = "dump-section", value_name = "SECTION_NAME")]
    dump_section: Option<String>,
}

/// Helper pour lire un slice de taille fixe avec vérification des bornes
fn read_bytes<'a>(data: &'a [u8], offset: usize, len: usize, field: &'static str) -> Result<&'a [u8], InspectError> {
    data.get(offset..offset + len)
        .ok_or(InspectError::Truncated { offset, field })
}

fn read_u16(data: &[u8], offset: usize, le: bool, field: &'static str) -> Result<u16, InspectError> {
    let slice = read_bytes(data, offset, 2, field)?;
    let arr: [u8; 2] = [slice[0], slice[1]];
    Ok(if le { u16::from_le_bytes(arr) } else { u16::from_be_bytes(arr) })
}

fn read_u32(data: &[u8], offset: usize, le: bool, field: &'static str) -> Result<u32, InspectError> {
    let slice = read_bytes(data, offset, 4, field)?;
    let arr: [u8; 4] = [slice[0], slice[1], slice[2], slice[3]];
    Ok(if le { u32::from_le_bytes(arr) } else { u32::from_be_bytes(arr) })
}

fn read_u64(data: &[u8], offset: usize, le: bool, field: &'static str) -> Result<u64, InspectError> {
    let slice = read_bytes(data, offset, 8, field)?;
    let mut arr = [0u8; 8];
    arr.copy_from_slice(slice);
    Ok(if le { u64::from_le_bytes(arr) } else { u64::from_be_bytes(arr) })
}

fn read_cstring(data: &[u8], offset: usize, max_len: usize) -> String {
    let mut end = offset;
    let limit = std::cmp::min(data.len(), offset + max_len);
    while end < limit && data[end] != 0 {
        end += 1;
    }
    String::from_utf8_lossy(&data[offset..end]).into_owned()
}

