#[derive(Debug)]
struct ElfHeader {
    is_64: bool,
    is_le: bool,
    version: u8,
    os_abi: u8,
    elf_type: u16,
    machine: u16,
    entry: u64,
    ph_off: u64,
    sh_off: u64,
    ph_num: u16,
    sh_num: u16,
    sh_strndx: u16,
}

#[derive(Debug)]
struct ElfSection {
    name: String,
    sec_type: u32,
    flags: u64,
    addr: u64,
    offset: u64,
    size: u64,
}

fn inspect_elf(data: &[u8], cli: &Cli) -> Result<(), InspectError> {
    println!("{}", "=== Format détecté: ELF (Executable and Linkable Format) ===".bold().green());

    let ident = read_bytes(data, 0, 16, "e_ident")?;
    let is_64 = match ident[4] {
        1 => false,
        2 => true,
        other => {
            return Err(InspectError::InvalidFormat {
                format: "ELF",
                reason: format!("Classe ELF inconnue: {other}"),
            })
        }
    };

    let is_le = match ident[5] {
        1 => true,
        2 => false,
        other => {
            return Err(InspectError::InvalidFormat {
                format: "ELF",
                reason: format!("Endianness inconnue: {other}"),
            })
        }
    };

    let version = ident[6];
    let os_abi = ident[7];

    let (elf_type, machine, entry, ph_off, sh_off, ph_num, sh_num, sh_strndx) = if is_64 {
        let elf_type = read_u16(data, 16, is_le, "e_type")?;
        let machine = read_u16(data, 18, is_le, "e_machine")?;
        let entry = read_u64(data, 24, is_le, "e_entry")?;
        let ph_off = read_u64(data, 32, is_le, "e_phoff")?;
        let sh_off = read_u64(data, 40, is_le, "e_shoff")?;
        let ph_num = read_u16(data, 56, is_le, "e_phnum")?;
        let sh_num = read_u16(data, 60, is_le, "e_shnum")?;
        let sh_strndx = read_u16(data, 62, is_le, "e_shstrndx")?;
        (elf_type, machine, entry, ph_off, sh_off, ph_num, sh_num, sh_strndx)
    } else {
        let elf_type = read_u16(data, 16, is_le, "e_type")?;
        let machine = read_u16(data, 18, is_le, "e_machine")?;
        let entry = read_u32(data, 24, is_le, "e_entry")? as u64;
        let ph_off = read_u32(data, 28, is_le, "e_phoff")? as u64;
        let sh_off = read_u32(data, 32, is_le, "e_shoff")? as u64;
        let ph_num = read_u16(data, 44, is_le, "e_phnum")?;
        let sh_num = read_u16(data, 48, is_le, "e_shnum")?;
        let sh_strndx = read_u16(data, 50, is_le, "e_shstrndx")?;
        (elf_type, machine, entry, ph_off, sh_off, ph_num, sh_num, sh_strndx)
    };

    let hdr = ElfHeader {
        is_64,
        is_le,
        version,
        os_abi,
        elf_type,
        machine,
        entry,
        ph_off,
        sh_off,
        ph_num,
        sh_num,
        sh_strndx,
    };

    println!("{:<24}: {}", "Classe", if hdr.is_64 { "ELF64 (64 bits)" } else { "ELF32 (32 bits)" });
    println!("{:<24}: {}", "Codage", if hdr.is_le { "Little-Endian (LSB)" } else { "Big-Endian (MSB)" });
    println!("{:<24}: {}", "Version", hdr.version);
    println!("{:<24}: {}", "OS/ABI", elf_os_abi_string(hdr.os_abi));
    println!("{:<24}: {} ({:#06x})", "Type de fichier", elf_type_string(hdr.elf_type), hdr.elf_type);
    println!("{:<24}: {} ({:#06x})", "Architecture machine", elf_machine_string(hdr.machine), hdr.machine);
    println!("{:<24}: {:#018x}", "Adresse du point d'entrée", hdr.entry);
    println!("{:<24}: {:#x} ({} entrées)", "Program Headers Offset", hdr.ph_off, hdr.ph_num);
    println!("{:<24}: {:#x} ({} entrées)", "Section Headers Offset", hdr.sh_off, hdr.sh_num);

    let sections = parse_elf_sections(data, &hdr)?;

    if cli.show_sections {
        println!("\n{}", "--- Table des Sections ELF ---".cyan().bold());
        println!(
            "{:<4} {:<24} {:<14} {:<18} {:<10} {:<10} {:<6}",
            "Idx", "Nom", "Type", "Adresse Virtuelle", "Offset", "Taille", "Flags"
        );
        for (idx, sec) in sections.iter().enumerate() {
            println!(
                "[{:02}] {:<24} {:<14} {:#018x} {:#010x} {:#010x} {:<6}",
                idx,
                sec.name,
                elf_section_type_string(sec.sec_type),
                sec.addr,
                sec.offset,
                sec.size,
                elf_flags_string(sec.flags)
            );
        }
    }

    if let Some(ref target_sec) = cli.dump_section {
        dump_section_content(data, target_sec, &sections)?;
    }

    Ok(())
}

fn parse_elf_sections(data: &[u8], hdr: &ElfHeader) -> Result<Vec<ElfSection>, InspectError> {
    let mut raw_sections = Vec::with_capacity(hdr.sh_num as usize);
    let entry_size = if hdr.is_64 { 64 } else { 40 };

    for i in 0..hdr.sh_num {
        let sec_offset = (hdr.sh_off as usize) + (i as usize * entry_size);
        if hdr.is_64 {
            let sh_name = read_u32(data, sec_offset, hdr.is_le, "sh_name")?;
            let sh_type = read_u32(data, sec_offset + 4, hdr.is_le, "sh_type")?;
            let sh_flags = read_u64(data, sec_offset + 8, hdr.is_le, "sh_flags")?;
            let sh_addr = read_u64(data, sec_offset + 16, hdr.is_le, "sh_addr")?;
            let sh_offset = read_u64(data, sec_offset + 24, hdr.is_le, "sh_offset")?;
            let sh_size = read_u64(data, sec_offset + 32, hdr.is_le, "sh_size")?;
            raw_sections.push((sh_name, sh_type, sh_flags, sh_addr, sh_offset, sh_size));
        } else {
            let sh_name = read_u32(data, sec_offset, hdr.is_le, "sh_name")?;
            let sh_type = read_u32(data, sec_offset + 4, hdr.is_le, "sh_type")?;
            let sh_flags = read_u32(data, sec_offset + 8, hdr.is_le, "sh_flags")? as u64;
            let sh_addr = read_u32(data, sec_offset + 12, hdr.is_le, "sh_addr")? as u64;
            let sh_offset = read_u32(data, sec_offset + 16, hdr.is_le, "sh_offset")? as u64;
            let sh_size = read_u32(data, sec_offset + 20, hdr.is_le, "sh_size")? as u64;
            raw_sections.push((sh_name, sh_type, sh_flags, sh_addr, sh_offset, sh_size));
        }
    }

    // Récupération de la table des chaînes de noms de section (.shstrtab)
    let shstrtab_offset = if (hdr.sh_strndx as usize) < raw_sections.len() {
        raw_sections[hdr.sh_strndx as usize].4 as usize
    } else {
        0
    };

    let mut parsed_sections = Vec::with_capacity(raw_sections.len());
    for (sh_name, sh_type, sh_flags, sh_addr, sh_offset, sh_size) in raw_sections {
        let name = if shstrtab_offset > 0 {
            read_cstring(data, shstrtab_offset + sh_name as usize, 128)
        } else {
            String::new()
        };
        parsed_sections.push(ElfSection {
            name,
            sec_type: sh_type,
            flags: sh_flags,
            addr: sh_addr,
            offset: sh_offset,
            size: sh_size,
        });
    }

    Ok(parsed_sections)
}

fn dump_section_content(data: &[u8], section_name: &str, sections: &[ElfSection]) -> Result<(), InspectError> {
    println!("\n{}", format!("--- Hex Dump Section : '{}' ---", section_name).yellow().bold());
    let sec = sections
        .iter()
        .find(|s| s.name == section_name)
        .ok_or_else(|| InspectError::InvalidFormat {
            format: "ELF",
            reason: format!("Section introuvable: '{section_name}'"),
        })?;

    let start = sec.offset as usize;
    let max_dump = std::cmp::min(sec.size as usize, 128); // 128 premiers octets
    let slice = read_bytes(data, start, max_dump, "section_data")?;

    for chunk in slice.chunks(16) {
        let hex: Vec<String> = chunk.iter().map(|b| format!("{:02x}", b)).collect();
        let ascii: String = chunk
            .iter()
            .map(|&b| if b.is_ascii_graphic() || b == b' ' { b as char } else { '.' })
            .collect();
        println!("{:<48} | {}", hex.join(" "), ascii);
    }
    if sec.size as usize > max_dump {
        println!("... ({} octets restants)", sec.size as usize - max_dump);
    }
    Ok(())
}

fn elf_os_abi_string(abi: u8) -> &'static str {
    match abi {
        0x00 => "System V / Default",
        0x01 => "HP-UX",
        0x02 => "NetBSD",
        0x03 => "Linux",
        0x04 => "GNU Hurd",
        0x06 => "Solaris",
        0x07 => "AIX",
        0x08 => "IRIX",
        0x09 => "FreeBSD",
        0x0C => "OpenBSD",
        0x0D => "OpenVMS",
        _ => "Autre / Inconnu",
    }
}

fn elf_type_string(t: u16) -> &'static str {
    match t {
        0x00 => "ET_NONE (Aucun)",
        0x01 => "ET_REL (Fichier repositionnable)",
        0x02 => "ET_EXEC (Exécutable standard)",
        0x03 => "ET_DYN (Bibliothèque partagée / Binaire PIE)",
        0x04 => "ET_CORE (Fichier Core dump)",
        _ => "ET_AUTRE",
    }
}

fn elf_machine_string(m: u16) -> &'static str {
    match m {
        0x03 => "x86 (Intel 80386)",
        0x28 => "ARM",
        0x3E => "x86-64 (AMD64 / Intel 64)",
        0xB7 => "AArch64 (ARM 64-bit)",
        0xF3 => "RISC-V",
        _ => "Autre architecture",
    }
}

fn elf_section_type_string(st: u32) -> &'static str {
    match st {
        0 => "NULL",
        1 => "PROGBITS",
        2 => "SYMTAB",
        3 => "STRTAB",
        4 => "RELA",
        5 => "HASH",
        6 => "DYNAMIC",
        7 => "NOTE",
        8 => "NOBITS",
        9 => "REL",
        11 => "DYNSYM",
        _ => "AUTRE",
    }
}

fn elf_flags_string(f: u64) -> String {
    let mut flags = String::new();
    if f & 0x1 != 0 {
        flags.push('W'); // Writable
    }
    if f & 0x2 != 0 {
        flags.push('A'); // Allocated in memory
    }
    if f & 0x4 != 0 {
        flags.push('X'); // Executable
    }
    if flags.is_empty() {
        "-".to_string()
    } else {
        flags
    }
}

// -----------------------------------------------------------------------------
// ANALYSE PE (Portable Executable)
// -----------------------------------------------------------------------------

#[derive(Debug)]
struct PeSection {
    name: String,
    virtual_size: u32,
    virtual_address: u32,
    raw_data_size: u32,
    raw_data_ptr: u32,
    characteristics: u32,
}

fn inspect_pe(data: &[u8], cli: &Cli) -> Result<(), InspectError> {
    println!("{}", "=== Format détecté: PE (Portable Executable Windows) ===".bold().blue());

    // Vérification de la signature MZ au début
    if data[0] != b'M' || data[1] != b'Z' {
        return Err(InspectError::InvalidFormat {
            format: "PE",
            reason: "En-tête DOS manquant ('MZ')".to_string(),
        });
    }

    // Offset vers le header PE (e_lfanew situé à l'offset 0x3C dans le DOS Header)
    let pe_offset = read_u32(data, 0x3C, true, "e_lfanew")? as usize;
    println!("{:<28}: {:#x}", "Offset de l'en-tête PE", pe_offset);

    // Signature PE : "PE\0\0"
    let pe_sig = read_bytes(data, pe_offset, 4, "PE Signature")?;
    if pe_sig != b"PE\0\0" {
        return Err(InspectError::InvalidFormat {
            format: "PE",
            reason: format!("Signature PE invalide: {:?}", pe_sig),
        });
    }

    // COFF Header (20 octets juste après "PE\0\0")
    let coff_offset = pe_offset + 4;
    let machine = read_u16(data, coff_offset, true, "Machine")?;
    let num_sections = read_u16(data, coff_offset + 2, true, "NumberOfSections")?;
    let timestamp = read_u32(data, coff_offset + 4, true, "TimeDateStamp")?;
    let opt_hdr_size = read_u16(data, coff_offset + 16, true, "SizeOfOptionalHeader")?;
    let characteristics = read_u16(data, coff_offset + 18, true, "Characteristics")?;

    println!("{:<28}: {} ({:#06x})", "Architecture Machine", pe_machine_string(machine), machine);
    println!("{:<28}: {}", "Nombre de sections", num_sections);
    println!("{:<28}: {:#010x}", "Timestamp (TimeDateStamp)", timestamp);
    println!("{:<28}: {:#06x}", "Caractéristiques COFF", characteristics);

    // Optional Header
    let opt_offset = coff_offset + 20;

    if opt_hdr_size >= 2 {
        let magic = read_u16(data, opt_offset, true, "OptionalHeader Magic")?;
        let is_pe32_plus = magic == 0x20B;
        let is_pe32 = magic == 0x10B;

        let magic_str = if is_pe32_plus {
            "PE32+ (64-bit)"
        } else if is_pe32 {
            "PE32 (32-bit)"
        } else {
            "Format inconnu"
        };
        println!("{:<28}: {} ({:#06x})", "Type Optional Header", magic_str, magic);

        if is_pe32_plus || is_pe32 {
            let entry_point = read_u32(data, opt_offset + 16, true, "AddressOfEntryPoint")?;
            println!("{:<28}: {:#010x}", "RVA du point d'entrée", entry_point);

            let (image_base_str, subsystem) = if is_pe32_plus {
                let img_base = read_u64(data, opt_offset + 24, true, "ImageBase")?;
                let sub = read_u16(data, opt_offset + 68, true, "Subsystem")?;
                (format!("{:#018x}", img_base), sub)
            } else {
                let img_base = read_u32(data, opt_offset + 28, true, "ImageBase")?;
                let sub = read_u16(data, opt_offset + 68, true, "Subsystem")?;
                (format!("{:#010x}", img_base), sub)
            };
            println!("{:<28}: {}", "Image Base", image_base_str);
            println!("{:<28}: {} ({})", "Sous-système", pe_subsystem_string(subsystem), subsystem);
        }
    }

    // Parsing des sections PE
    let sec_table_offset = opt_offset + opt_hdr_size as usize;
    let mut sections = Vec::with_capacity(num_sections as usize);

    for i in 0..num_sections {
        let s_offset = sec_table_offset + (i as usize * 40);
        let name_raw = read_bytes(data, s_offset, 8, "Section Name")?;
        let name = String::from_utf8_lossy(name_raw)
            .trim_matches('\0')
            .to_string();
        let virtual_size = read_u32(data, s_offset + 8, true, "VirtualSize")?;
        let virtual_address = read_u32(data, s_offset + 12, true, "VirtualAddress")?;
        let raw_data_size = read_u32(data, s_offset + 16, true, "SizeOfRawData")?;
        let raw_data_ptr = read_u32(data, s_offset + 20, true, "PointerToRawData")?;
        let characts = read_u32(data, s_offset + 36, true, "Characteristics")?;

        sections.push(PeSection {
            name,
            virtual_size,
            virtual_address,
            raw_data_size,
            raw_data_ptr,
            characteristics: characts,
        });
    }

    if cli.show_sections {
        println!("\n{}", "--- Table des Sections PE ---".cyan().bold());
        println!(
            "{:<4} {:<10} {:<14} {:<14} {:<14} {:<14} {:<10}",
            "Idx", "Nom", "Taille Virt.", "RVA", "Taille Brute", "Offset Brut", "Flags"
        );
        for (idx, sec) in sections.iter().enumerate() {
            println!(
                "[{:02}] {:<10} {:#010x}    {:#010x}    {:#010x}    {:#010x}    {:<10}",
                idx,
                sec.name,
                sec.virtual_size,
                sec.virtual_address,
                sec.raw_data_size,
                sec.raw_data_ptr,
                pe_characteristics_string(sec.characteristics)
            );
        }
    }

    if let Some(ref target_sec) = cli.dump_section {
        println!("\n{}", format!("--- Hex Dump Section : '{}' ---", target_sec).yellow().bold());
        let sec = sections
            .iter()
            .find(|s| s.name == *target_sec)
            .ok_or_else(|| InspectError::InvalidFormat {
                format: "PE",
                reason: format!("Section introuvable: '{target_sec}'"),
            })?;

        let start = sec.raw_data_ptr as usize;
        let max_dump = std::cmp::min(sec.raw_data_size as usize, 128);
        let slice = read_bytes(data, start, max_dump, "pe_section_data")?;

        for chunk in slice.chunks(16) {
            let hex: Vec<String> = chunk.iter().map(|b| format!("{:02x}", b)).collect();
            let ascii: String = chunk
                .iter()
                .map(|&b| if b.is_ascii_graphic() || b == b' ' { b as char } else { '.' })
                .collect();
            println!("{:<48} | {}", hex.join(" "), ascii);
        }
        if sec.raw_data_size as usize > max_dump {
            println!("... ({} octets restants)", sec.raw_data_size as usize - max_dump);
        }
    }

    Ok(())
}

fn pe_machine_string(m: u16) -> &'static str {
    match m {
        0x014C => "i386 (Intel 386 ou ultérieur)",
        0x8664 => "AMD64 (K8 / x86-64)",
        0x01C0 => "ARM little endian",
        0xAA64 => "ARM64 little endian",
        _ => "Autre architecture",
    }
}

fn pe_subsystem_string(sub: u16) -> &'static str {
    match sub {
        1 => "Native",
        2 => "Windows GUI",
        3 => "Windows CUI (Console)",
        7 => "POSIX CUI",
        9 => "Windows CE GUI",
        10 => "EFI Application",
        _ => "Inconnu",
    }
}

fn pe_characteristics_string(c: u32) -> String {
    let mut flags = String::new();
    if c & 0x00000020 != 0 {
        flags.push('C'); // Code
    }
    if c & 0x00000040 != 0 {
        flags.push('I'); // Initialized data
    }
    if c & 0x20000000 != 0 {
        flags.push('X'); // Executable
    }
    if c & 0x40000000 != 0 {
        flags.push('R'); // Readable
    }
    if c & 0x80000000 != 0 {
        flags.push('W'); // Writable
    }
    if flags.is_empty() {
        "-".to_string()
    } else {
        flags
    }
}

// -----------------------------------------------------------------------------
// POINT D'ENTRÉE PRINCIPAL
// -----------------------------------------------------------------------------

fn run() -> Result<(), InspectError> {
    let cli = Cli::parse();

    let bytes = fs::read(&cli.file).map_err(|e| InspectError::Io {
        path: cli.file.clone(),
        source: e,
    })?;

    if bytes.len() < 4 {
        return Err(InspectError::FileTooSmall { size: bytes.len() });
    }

    println!("{} : {}", "Fichier inspecté".bold(), cli.file.display());
    println!("{} : {} octets\n", "Taille totale".bold(), bytes.len());

    // Détection de signature
    if bytes.starts_with(b"\x7FELF") {
        inspect_elf(&bytes, &cli)
    } else if bytes.starts_with(b"MZ") {
        inspect_pe(&bytes, &cli)
    } else {
        Err(InspectError::UnknownFormat)
    }
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("{} {}", "Erreur:".red().bold(), err);
            ExitCode::FAILURE
        }
    }
}

