```rust
// src/main.rs
//! # Trie Autocomplete
//!
//! Implémentation idiomatique d'un arbre de préfixes (Trie) optimisé pour
//! l'autocomplétion textuelle, s'appuyant sur [`Box`], [`Option`] et [`std::collections::BTreeMap`].

use std::collections::BTreeMap;

/// Nœud interne du Trie.
///
/// Chaque nœud stocke :
/// - `children` : Une table associative ordonnée (`BTreeMap`) mappant chaque caractère (`char`)
///   vers un sous-nœud alloué sur le tas via `Box<TrieNode>`.
/// - `word` : Un `Option<String>` valant `Some(word)` si le nœud marque la fin d'un mot valide,
///   ou `None` s'il s'agit uniquement d'un préfixe intermédiaire.
#[derive(Debug, Clone, Default)]
pub struct TrieNode {
    children: BTreeMap<char, Box<TrieNode>>,
    word: Option<String>,
}

impl TrieNode {
    /// Crée un nouveau nœud vide.
    #[must_use]
    pub fn new() -> Self {
        Self {
            children: BTreeMap::new(),
            word: None,
        }
    }
}

/// Arbre de préfixes optimisé pour l'autocomplétion et la recherche textuelle.
#[derive(Debug, Clone, Default)]
pub struct Trie {
    root: TrieNode,
    word_count: usize,
}

impl Trie {
    /// Instancie un nouveau `Trie` vide.
    #[must_use]
    pub fn new() -> Self {
        Self {
            root: TrieNode::new(),
            word_count: 0,
        }
    }

    /// Retourne le nombre total de mots distincts indexés dans l'arbre.
    #[must_use]
    pub fn len(&self) -> usize {
        self.word_count
    }

    /// Indique si l'arbre ne contient aucun mot.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.word_count == 0
    }

    /// Insère un mot dans le Trie.
    ///
    /// Retourne `true` si le mot a été nouvellement ajouté,
    /// ou `false` s'il était déjà présent dans l'arbre.
    pub fn insert(&mut self, word: &str) -> bool {
        let mut current = &mut self.root;

        for ch in word.chars() {
            current = current
                .children
                .entry(ch)
                .or_insert_with(|| Box::new(TrieNode::new()));
        }

        if current.word.is_some() {
            false
        } else {
            current.word = Some(word.to_string());
            self.word_count += 1;
            true
        }
    }

    /// Vérifie si le mot exact est présent dans le Trie.
    #[must_use]
    pub fn contains(&self, word: &str) -> bool {
        self.find_node(word)
            .and_then(|node| node.word.as_deref())
            .is_some()
    }

    /// Vérifie si au moins un mot commence par le préfixe spécifié.
    #[must_use]
    pub fn starts_with(&self, prefix: &str) -> bool {
        self.find_node(prefix).is_some()
    }

    /// Recherche et retourne toutes les suggestions d'autocomplétion pour un préfixe donné,
    /// triées par ordre lexicographique naturel grâce à `BTreeMap`.
    ///
    /// Un paramètre optionnel `limit` permet de restreindre le nombre maximum de résultats.
    #[must_use]
    pub fn autocomplete(&self, prefix: &str, limit: Option<usize>) -> Vec<String> {
        let mut results = Vec::new();

        if let Some(limit_val) = limit {
            if limit_val == 0 {
                return results;
            }
        }

        if let Some(start_node) = self.find_node(prefix) {
            Self::collect_words(start_node, &mut results, limit);
        }

        results
    }

    /// Navigue jusqu'au nœud correspondant à la séquence de caractères fournie.
    fn find_node(&self, prefix: &str) -> Option<&TrieNode> {
        let mut current = &self.root;
        for ch in prefix.chars() {
            match current.children.get(&ch) {
                Some(next_box) => current = next_box.as_ref(),
                None => return None,
            }
        }
        Some(current)
    }

    /// Parcours récursif en profondeur (DFS) ordonné pour collecter les mots.
    fn collect_words(node: &TrieNode, results: &mut Vec<String>, limit: Option<usize>) {
        if let Some(max) = limit {
            if results.len() >= max {
                return;
            }
        }

        if let Some(ref word) = node.word {
            results.push(word.clone());
        }

        for next_node in node.children.values() {
            if let Some(max) = limit {
                if results.len() >= max {
                    break;
                }
            }
            Self::collect_words(next_node.as_ref(), results, limit);
        }
    }
}

fn main() {
    println!("=== Initialisation du Trie d'Autocomplétion ===");

    let mut trie = Trie::new();
    let sample_words = [
        "arbre",
        "arborescence",
        "arbreux",
        "arbitre",
        "arbitrage",
        "arc",
        "arceau",
        "argent",
        "argenterie",
        "artisan",
        "artiste",
        "automobile",
        "automate",
        "autonomie",
        "bateau",
        "bataille",
        "éclair",
        "école",
        "écran",
        "écureuil",
    ];

    for word in sample_words {
        trie.insert(word);
    }

    println!("Total de mots indexés : {}", trie.len());
    println!("Contient 'arborescence' ? {}", trie.contains("arborescence"));
    println!("Contient 'arbuste' ? {}", trie.contains("arbuste"));
    println!("Commence par 'arb' ? {}", trie.starts_with("arb"));
    println!("Commence par 'xyz' ? {}", trie.starts_with("xyz"));

    println!("\n--- Autocomplétion pour 'arb' (sans limite) ---");
    let suggestions_arb = trie.autocomplete("arb", None);
    for (i, word) in suggestions_arb.iter().enumerate() {
        println!("  {}. {}", i + 1, word);
    }

    println!("\n--- Autocomplétion pour 'auto' (limitée à 2 résultats) ---");
    let suggestions_auto = trie.autocomplete("auto", Some(2));
    for (i, word) in suggestions_auto.iter().enumerate() {
