                let insert_cost = table[i * cols + (j - 1)] + 1;
                let substitution_cost = table[(i - 1) * cols + (j - 1)] + cost_sub;

                // Utilisation explicite et idiomatique de std::cmp::min
                let best_cost = min(delete_cost, min(insert_cost, substitution_cost));
                table[i * cols + j] = best_cost;
            }
        }

        Self {
            source: source_chars,
            target: target_chars,
            rows,
            cols,
            table,
        }
    }

    /// Retourne la valeur mémoïsée pour les préfixes de longueurs respectives `i` et `j`.
    #[inline]
    pub fn get(&self, i: usize, j: usize) -> Option<usize> {
        if i < self.rows && j < self.cols {
            Some(self.table[i * self.cols + j])
        } else {
            None
        }
    }

    /// Retourne la distance d'édition finale de Levenshtein.
    #[inline]
    pub fn distance(&self) -> usize {
        self.table[(self.rows - 1) * self.cols + (self.cols - 1)]
    }

    /// Reconstitue la séquence d'opérations optimales par backtracking dans la matrice mémoïsée.
    pub fn backtrace_operations(&self) -> Vec<EditOperation> {
        let mut ops = Vec::new();
        let mut i = self.rows - 1;
        let mut j = self.cols - 1;

        while i > 0 || j > 0 {
            let current_cost = self.table[i * self.cols + j];

            if i > 0 && j > 0 {
                let s_char = self.source[i - 1];
                let t_char = self.target[j - 1];
                let cost_sub = if s_char == t_char { 0 } else { 1 };
                let diag_cost = self.table[(i - 1) * self.cols + (j - 1)];

                if current_cost == diag_cost + cost_sub {
                    if cost_sub == 0 {
                        ops.push(EditOperation::Keep(s_char));
                    } else {
                        ops.push(EditOperation::Substitute {
                            from: s_char,
                            to: t_char,
                        });
                    }
                    i -= 1;
                    j -= 1;
                    continue;
                }
            }

            if i > 0 {
                let up_cost = self.table[(i - 1) * self.cols + j];
                if current_cost == up_cost + 1 {
                    ops.push(EditOperation::Delete(self.source[i - 1]));
                    i -= 1;
                    continue;
                }
            }

            if j > 0 {
                let left_cost = self.table[i * self.cols + (j - 1)];
                if current_cost == left_cost + 1 {
                    ops.push(EditOperation::Insert(self.target[j - 1]));
                    j -= 1;
                    continue;
                }
            }
        }

        ops.reverse();
        ops
    }

    /// Affiche la matrice sous forme de grille formatée.
    pub fn print_matrix(&self) {
        print!("        ε");
        for ch in &self.target {
            print!("{:>4}", ch);
        }
        println!();

        for i in 0..self.rows {
            let row_header = if i == 0 {
                'ε'
            } else {
                self.source[i - 1]
            };
            print!("{:>4} ", row_header);
            for j in 0..self.cols {
                print!("{:>4}", self.table[i * self.cols + j]);
            }
            println!();
        }
    }
}

/// Calcule directement la distance de Levenshtein entre deux chaînes.
pub fn levenshtein_distance(source: &str, target: &str) -> usize {
    LevenshteinMatrix::new(source, target).distance()
}

fn main() {
    println!("=== Calculateur de Distance d'Édition Levenshtein ===");

    let pairs = [
        ("niche", "chiens"),
        ("kitten", "sitting"),
        ("algorithme", "logarithme"),
        ("café", "cacao"),
        ("", "rust"),
        ("rust", "rust"),
    ];

    for (src, tgt) in pairs {
        let matrix = LevenshteinMatrix::new(src, tgt);
        let dist = matrix.distance();
        println!("\n--------------------------------------------------");
        println!("Source : \"{}\"", src);
        println!("Cible  : \"{}\"", tgt);
        println!("Distance de Levenshtein : {}", dist);

        let ops = matrix.backtrace_operations();
        println!("Opérations optimales ({}) :", ops.len());
        for (step, op) in ops.iter().enumerate() {
            println!("  {:>2}. {}", step + 1, op);
        }
    }

    println!("\nMatrice de mémoïsation détaillée pour ('niche', 'chiens') :");
    let sample = LevenshteinMatrix::new("niche", "chiens");
    sample.print_matrix();
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_identical_strings() {
        assert_eq!(levenshtein_distance("chat", "chat"), 0);
        assert_eq!(levenshtein_distance("", ""), 0);
    }

    #[test]
    fn test_empty_source_or_target() {
        assert_eq!(levenshtein_distance("", "test"), 4);
        assert_eq!(levenshtein_distance("bonjour", ""), 7);
    }

    #[test]
    fn test_classic_examples() {
        assert_eq!(levenshtein_distance("kitten", "sitting"), 3);
        assert_eq!(levenshtein_distance("rosettacode", "raisethysword"), 8);
        assert_eq!(levenshtein_distance("niche", "chiens"), 5);
        assert_eq!(levenshtein_distance("algorithme", "logarithme"), 3);
    }

    #[test]
    fn test_unicode_accents() {
        assert_eq!(levenshtein_distance("café", "cafe"), 1);
        assert_eq!(levenshtein_distance("éléphant", "elephant"), 2);
    }

    #[test]
    fn test_backtrace_reconstruction() {
        let src = "niche";
        let tgt = "chiens";
        let matrix = LevenshteinMatrix::new(src, tgt);
        let ops = matrix.backtrace_operations();

        let simulated: Vec<char> = src.chars().collect();
        let mut sim_cursor = 0;
        let mut result = Vec::new();

        for op in ops {
            match op {
                EditOperation::Keep(c) => {
                    assert_eq!(simulated[sim_cursor], c);
                    result.push(c);
                    sim_cursor += 1;
                }
                EditOperation::Substitute { from, to } => {
                    assert_eq!(simulated[sim_cursor], from);
                    result.push(to);
                    sim_cursor += 1;
                }
                EditOperation::Insert(c) => {
                    result.push(c);
                }
                EditOperation::Delete(c) => {
                    assert_eq!(simulated[sim_cursor], c);
                    sim_cursor += 1;
                }
            }
        }

        let final_str: String = result.into_iter().collect();
        assert_eq!(final_str, tgt);
    }
}

