                if trimmed == "/quit" {
                    break;
                } else if trimmed == "/list" {
                    let _ = tx.send(ServerEvent::ListRequest { id: client_id });
                } else if !trimmed.is_empty() {
                    let _ = tx.send(ServerEvent::ClientMessage {
                        id: client_id,
                        text: trimmed.to_string(),
                    });
                }
            }
            Err(err) => {
                eprintln!("[Client #{}] Erreur de lecture : {}", client_id, err);
                break;
            }
        }
    }

    // Retrait du client et notification
    {
        let mut map = clients.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
        map.remove(&client_id);
    }
    let _ = tx.send(ServerEvent::ClientDisconnected { id: client_id });

    Ok(())
}

fn handle_broadcast(
    rx: Receiver<ServerEvent>,
    clients: Arc<Mutex<HashMap<usize, (String, UnixStream)>>>,
) {
    while let Ok(event) = rx.recv() {
        let mut disconnected_ids = Vec::new();
        let mut map = clients.lock().unwrap_or_else(|poisoned| poisoned.into_inner());

        match event {
            ServerEvent::ClientJoined { id, username } => {
                println!("[+] {} (id: {}) a rejoint le salon.", username, id);
                let message = format!(">>> [+] {} a rejoint le chat !\n", username);
                broadcast_message(&mut map, &mut disconnected_ids, &message, None);
            }
            ServerEvent::ClientMessage { id, text } => {
                let sender_name = map
                    .get(&id)
                    .map(|(name, _)| name.clone())
                    .unwrap_or_else(|| format!("Client#{}", id));

                println!("[{}] {}", sender_name, text);
                let message = format!("[{}] {}\n", sender_name, text);
                broadcast_message(&mut map, &mut disconnected_ids, &message, Some(id));
            }
            ServerEvent::ClientDisconnected { id } => {
                println!("[-] Client #{} déconnecté.", id);
                let message = format!(">>> [-] Client #{} a quitté le chat.\n", id);
                broadcast_message(&mut map, &mut disconnected_ids, &message, None);
            }
            ServerEvent::ListRequest { id } => {
                let mut list_msg = String::from(">>> Utilisateurs connectés :\n");
                for (client_id, (name, _)) in map.iter() {
                    let marker = if *client_id == id { " (vous)" } else { "" };
                    list_msg.push_str(&format!("  * {}{}\n", name, marker));
                }
                if let Some((_, stream)) = map.get_mut(&id) {
                    if let Err(err) = stream.write_all(list_msg.as_bytes()) {
                        eprintln!("Erreur lors de l'envoi de la commande /list : {}", err);
                        disconnected_ids.push(id);
                    }
                }
            }
        }

        for dead_id in disconnected_ids {
            map.remove(&dead_id);
        }
    }
}

fn broadcast_message(
    clients: &mut HashMap<usize, (String, UnixStream)>,
    disconnected_ids: &mut Vec<usize>,
    message: &str,
    skip_id: Option<usize>,
) {
    for (&id, (_, stream)) in clients.iter_mut() {
        if Some(id) == skip_id {
            continue;
        }

        if let Err(err) = stream.write_all(message.as_bytes()) {
            eprintln!("Erreur d'écriture vers le client #{} : {}", id, err);
            disconnected_ids.push(id);
        } else {
            let _ = stream.flush();
        }
    }
}

fn run_client(username: &str, socket_path: &Path) -> io::Result<()> {
    if !socket_path.exists() {
        return Err(io::Error::new(
            io::ErrorKind::NotFound,
            format!(
                "Le socket '{}' n'existe pas. Le serveur est-il lancé ?",
                socket_path.display()
            ),
        ));
    }

    println!(">>> Connexion au serveur de chat sur : {}", socket_path.display());
    let mut write_stream = UnixStream::connect(socket_path)?;
    let read_stream = write_stream.try_clone()?;

    // Envoi initial du pseudonyme
    writeln!(write_stream, "{}", username)?;
    write_stream.flush()?;

    println!(">>> Connecté en tant que '{}' !", username);
    println!(">>> Tapez vos messages ci-dessous. Commandes disponibles : /list, /quit");

    let running = Arc::new(AtomicBool::new(true));
    let running_reader = Arc::clone(&running);

    // Thread de réception des messages du serveur
    let recv_handle = thread::spawn(move || {
        let mut reader = BufReader::new(read_stream);
        let mut line = String::new();

        while running_reader.load(Ordering::Relaxed) {
            line.clear();
            match reader.read_line(&mut line) {
                Ok(0) => {
                    println!("\n>>> Déconnecté du serveur.");
                    running_reader.store(false, Ordering::Relaxed);
                    break;
                }
                Ok(_) => {
                    print!("{}", line);
                    let _ = io::stdout().flush();
                }
                Err(err) => {
                    if running_reader.load(Ordering::Relaxed) {
                        eprintln!("\n>>> Erreur de réception : {}", err);
                        running_reader.store(false, Ordering::Relaxed);
                    }
                    break;
                }
            }
        }
    });

    // Boucle de saisie utilisateur
    let stdin = io::stdin();
    let mut stdin_reader = BufReader::new(stdin);
    let mut input = String::new();

    while running.load(Ordering::Relaxed) {
        input.clear();
        match stdin_reader.read_line(&mut input) {
            Ok(0) => break,
            Ok(_) => {
                let trimmed = input.trim();
                if trimmed.is_empty() {
                    continue;
                }

                if let Err(err) = writeln!(write_stream, "{}", trimmed) {
                    eprintln!("Erreur lors de l'envoi du message : {}", err);
                    break;
                }
                let _ = write_stream.flush();

                if trimmed == "/quit" {
                    running.store(false, Ordering::Relaxed);
                    break;
                }
            }
            Err(err) => {
                eprintln!("Erreur lors de la lecture sur stdin : {}", err);
                break;
            }
        }
    }

    running.store(false, Ordering::Relaxed);
    // Fermeture du flux pour débloquer le reader
    let _ = write_stream.shutdown(std::net::Shutdown::Both);
    let _ = recv_handle.join();

    println!(">>> Déconnexion effectuée. À bientôt !");
    Ok(())
}

