// src/main.rs
use std::fmt;
use std::fs::{self, File, OpenOptions};
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::sync::Mutex;
use chrono::Utc;
use thiserror::Error;

/// Erreurs possibles émises par le système de journalisation.
#[derive(Debug, Error)]
pub enum LogError {
    #[error("Erreur d'entrée/sortie : {0}")]
    Io(#[from] io::Error),

    #[error("Impossible de verrouiller le mutex du logger")]
    LockError,

    #[error("Chemin invalide pour le fichier de log : {0}")]
    InvalidPath(String),
}

/// Niveaux de journalisation ordonnés par sévérité croissante.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum LogLevel {
    Trace = 0,
    Debug = 1,
    Info = 2,
    Warn = 3,
    Error = 4,
}

impl fmt::Display for LogLevel {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let label = match self {
            LogLevel::Trace => "TRACE",
            LogLevel::Debug => "DEBUG",
            LogLevel::Info => "INFO",
            LogLevel::Warn => "WARN",
            LogLevel::Error => "ERROR",
        };
        write!(f, "{:<5}", label)
    }
}

/// Configuration des règles de rotation de fichiers.
#[derive(Debug, Clone)]
pub struct RotationConfig {
    /// Taille maximale en octets avant déclenchement d'une rotation.
    pub max_bytes: u64,
    /// Nombre maximal de fichiers d'archive conservés.
    pub max_backup_files: usize,
}

impl Default for RotationConfig {
    fn default() -> Self {
        Self {
            max_bytes: 10 * 1024 * 1024, // 10 Mo par défaut
            max_backup_files: 5,
        }
    }
}

/// Configuration globale du logger.
#[derive(Debug, Clone)]
pub struct LoggerConfig {
    pub log_dir: PathBuf,
    pub base_name: String,
    pub min_level: LogLevel,
    pub rotation: RotationConfig,
}

/// Structure interne gérant le fichier ouvert et la taille courante.
struct LoggerInner {
    file: File,
    current_size: u64,
    log_dir: PathBuf,
    base_name: String,
    rotation: RotationConfig,
}

impl LoggerInner {
    /// Ouvre le fichier actif avec `OpenOptions` de manière synchrone.
    fn open_active_file(path: &Path) -> Result<(File, u64), LogError> {
        let file = OpenOptions::new()
            .create(true)
            .append(true)
            .open(path)?;

        let initial_size = file.metadata()?.len();
        Ok((file, initial_size))
    }

    /// Construit le chemin complet du fichier actif `<log_dir>/<base_name>.log`.
    fn active_file_path(log_dir: &Path, base_name: &str) -> PathBuf {
        log_dir.join(format!("{}.log", base_name))
    }

    /// Construit le chemin d'un fichier d'archive `<log_dir>/<base_name>.<index>.log`.
    fn backup_file_path(log_dir: &Path, base_name: &str, index: usize) -> PathBuf {
        log_dir.join(format!("{}.{}.log", base_name, index))
    }

    /// Effectue la rotation circulaire des fichiers sur le disque.
    fn rotate(&mut self) -> Result<(), LogError> {
        // 1. Vidage forcé des buffers du fichier en cours d'écriture
        self.file.flush()?;

        let active_path = Self::active_file_path(&self.log_dir, &self.base_name);

        // 2. Décalage des archives existantes en partant du plus vieil indice
        for i in (1..=self.rotation.max_backup_files).rev() {
            let src = Self::backup_file_path(&self.log_dir, &self.base_name, i);
            if i >= self.rotation.max_backup_files {
                if src.exists() {
                    fs::remove_file(&src)?;
                }
            } else if src.exists() {
                let dest = Self::backup_file_path(&self.log_dir, &self.base_name, i + 1);
                fs::rename(&src, &dest)?;
            }
        }

        // 3. Déplacement du fichier actif vers la première archive .1.log
        if active_path.exists() {
            let first_backup = Self::backup_file_path(&self.log_dir, &self.base_name, 1);
            fs::rename(&active_path, &first_backup)?;
        }

        // 4. Réouverture synchrone d'un nouveau fichier actif via OpenOptions
        let (new_file, new_size) = Self::open_active_file(&active_path)?;
        self.file = new_file;
        self.current_size = new_size;

        Ok(())
    }

    /// Écrit un message dans le fichier et force la synchronisation disque (`flush`).
    fn write_entry(&mut self, payload: &[u8]) -> Result<(), LogError> {
        let payload_len = payload.len() as u64;

        // Déclencher la rotation si le message dépasse le quota restant
        if self.current_size + payload_len > self.rotation.max_bytes {
            self.rotate()?;
        }

        self.file.write_all(payload)?;
        self.file.flush()?;
        self.current_size += payload_len;

        Ok(())
    }
}

/// Logger synchrone thread-safe avec rotation par taille.
pub struct RollingFileLogger {
    min_level: LogLevel,
    inner: Mutex<LoggerInner>,
}

impl RollingFileLogger {
    /// Initialise une nouvelle instance du logger selon la configuration fournie.
    pub fn new(config: LoggerConfig) -> Result<Self, LogError> {
        if !config.log_dir.exists() {
            fs::create_dir_all(&config.log_dir)?;
        }

        let active_path = LoggerInner::active_file_path(&config.log_dir, &config.base_name);
        let (file, current_size) = LoggerInner::open_active_file(&active_path)?;

        let inner = LoggerInner {
            file,
            current_size,
            log_dir: config.log_dir,
            base_name: config.base_name,
            rotation: config.rotation,
        };

        Ok(Self {
            min_level: config.min_level,
            inner: Mutex::new(inner),
        })
    }

    /// Écrit une ligne de log de manière synchrone si le niveau requis est atteint.
    pub fn log(&self, level: LogLevel, target: &str, message: &str) -> Result<(), LogError> {
        // Filtrage multi-niveaux précoce pour minimiser le coût processeur
        if level < self.min_level {
            return Ok(());
        }

        let now = Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Millis, true);
        let formatted = format!("[{}] [{}] [{}] {}\n", now, level, target, message);

        let mut inner = self.inner.lock().map_err(|_| LogError::LockError)?;
        inner.write_entry(formatted.as_bytes())
    }

    /// Log de niveau TRACE
    pub fn trace(&self, target: &str, message: &str) -> Result<(), LogError> {
        self.log(LogLevel::Trace, target, message)
    }

    /// Log de niveau DEBUG
    pub fn debug(&self, target: &str, message: &str) -> Result<(), LogError> {
        self.log(LogLevel::Debug, target, message)
    }

    /// Log de niveau INFO
    pub fn info(&self, target: &str, message: &str) -> Result<(), LogError> {
        self.log(LogLevel::Info, target, message)
    }

    /// Log de niveau WARN
    pub fn warn(&self, target: &str, message: &str) -> Result<(), LogError> {
        self.log(LogLevel::Warn, target, message)
    }

    /// Log de niveau ERROR
    pub fn error(&self, target: &str, message: &str) -> Result<(), LogError> {
        self.log(LogLevel::Error, target, message)
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("=== Initialisation du Logger Synchrone Multi-Niveaux ===");

    let log_directory = PathBuf::from("./target/demo_logs");

    // Nettoyage préalable pour la démonstration
    if log_directory.exists() {
        fs::remove_dir_all(&log_directory)?;
    }

    let config = LoggerConfig {
        log_dir: log_directory.clone(),
        base_name: "app".to_string(),
        min_level: LogLevel::Debug, // Filtre TRACE
        rotation: RotationConfig {
            max_bytes: 400,         // Seuil très bas pour provoquer plusieurs rotations
            max_backup_files: 3,    // Conserver app.1.log, app.2.log, app.3.log
        },
    };

    let logger = RollingFileLogger::new(config)?;

    println!("1. Test du filtrage multi-niveaux :");
    // Ce message sera ignoré car TRACE < DEBUG
    logger.trace("main::init", "Ce message TRACE ne sera PAS consigné dans le fichier.")?;
    println!("   -> TRACE soumis (ignoré selon le seuil minimal DEBUG)");

    // Messages acceptés
    logger.debug("main::auth", "Démarrage du processus d'authentification utilisateur")?;
    logger.info("main::auth", "L'utilisateur 'alice' s'est connecté avec succès.")?;
    logger.warn("main::disk", "Espace disque temporaire inférieur à 15%")?;
    logger.error("main::db", "Délai de connexion dépassé sur la base de données principale")?;
    println!("   -> DEBUG, INFO, WARN, ERROR consignés avec succès.");

    println!("\n2. Déclenchement de la rotation par taille :");
    // Émission d'une série de messages calibrés pour saturer la limite de 400 octets
    for i in 1..=12 {
        let msg = format!("Transaction #{:04} traitée pour le client (charge utile de test)", i);
        logger.info("main::billing", &msg)?;
    }
    println!("   -> 12 transactions écrites de façon synchrone.");

    println!("\n3. État des fichiers générés sur le disque ({}) :", log_directory.display());
    let mut files: Vec<_> = fs::read_dir(&log_directory)?
        .filter_map(|entry| entry.ok())
        .collect();
    files.sort_by_key(|e| e.path());

    for entry in files {
        let meta = entry.metadata()?;
        println!("   - {:<18} : {:>4} octets", entry.file_name().to_string_lossy(), meta.len());
    }

    // Affichage d'un extrait du fichier actif
    let active_log = log_directory.join("app.log");
    if active_log.exists() {
        let content = fs::read_to_string(&active_log)?;
        println!("\n4. Extrait du fichier actif (app.log) :");
        for line in content.lines().take(4) {
            println!("   {}", line);
        }
    }

    println!("\n=== Démonstration terminée avec succès ===");
    Ok(())
}

