```rust
// src/main.rs
use clap::{Parser, ValueEnum};
use rand::rngs::StdRng;
use rand::seq::SliceRandom;
use rand::{Rng, SeedableRng};
use std::io::{self, BufWriter, Write};

#[derive(Debug, Copy, Clone, PartialEq, Eq, ValueEnum)]
enum Algorithm {
    Kruskal,
    Dfs,
}

#[derive(Parser, Debug)]
#[command(
    name = "maze_generator",
    about = "Générateur de labyrinthes en ASCII (Kruskal & DFS)",
    version = "0.1.0"
)]
struct Cli {
    #[arg(short = 'w', long, default_value_t = 20, help = "Largeur du labyrinthe en cellules")]
    width: usize,

    #[arg(short = 'H', long, default_value_t = 10, help = "Hauteur du labyrinthe en cellules")]
    height: usize,

    #[arg(short = 'a', long, value_enum, default_value_t = Algorithm::Kruskal, help = "Algorithme de génération")]
    algorithm: Algorithm,

    #[arg(short = 's', long, help = "Graine aléatoire optionnelle (u64)")]
    seed: Option<u64>,

    #[arg(long, default_value_t = false, help = "Ouvrir l'entrée (haut-gauche) et la sortie (bas-droite)")]
    open_ends: bool,
}

#[derive(Clone, Copy)]
struct Cell {
    wall_east: bool,
    wall_south: bool,
}

impl Default for Cell {
    fn default() -> Self {
        Self {
            wall_east: true,
            wall_south: true,
        }
    }
}

struct Maze {
    width: usize,
    height: usize,
    cells: Vec<Cell>,
    open_ends: bool,
}

impl Maze {
    fn new(width: usize, height: usize, open_ends: bool) -> Result<Self, &'static str> {
        if width == 0 || height == 0 {
            return Err("La largeur et la hauteur doivent être strictement supérieures à 0");
        }
        let total = width
            .checked_mul(height)
            .ok_or("Dimensions trop grandes (dépassement arithmétique)")?;
        Ok(Self {
            width,
            height,
            cells: vec![Cell::default(); total],
            open_ends,
        })
    }

    #[inline]
    fn idx(&self, x: usize, y: usize) -> usize {
        y * self.width + x
    }

    fn cell(&self, x: usize, y: usize) -> &Cell {
        &self.cells[self.idx(x, y)]
    }

    fn cell_mut(&mut self, x: usize, y: usize) -> &mut Cell {
        let i = self.idx(x, y);
        &mut self.cells[i]
    }

    fn remove_wall_between(&mut self, (x1, y1): (usize, usize), (x2, y2): (usize, usize)) {
        if x1 == x2 {
            if y1 + 1 == y2 {
                self.cell_mut(x1, y1).wall_south = false;
            } else if y2 + 1 == y1 {
                self.cell_mut(x2, y2).wall_south = false;
            }
        } else if y1 == y2 {
            if x1 + 1 == x2 {
                self.cell_mut(x1, y1).wall_east = false;
            } else if x2 + 1 == x1 {
                self.cell_mut(x2, y2).wall_east = false;
            }
        }
    }

    fn render<W: Write>(&self, out: &mut W) -> io::Result<()> {
        let mut writer = BufWriter::new(out);

        // Mur supérieur
        for x in 0..self.width {
            if self.open_ends && x == 0 {
                writer.write_all(b"+   ")?;
            } else {
                writer.write_all(b"+---")?;
            }
        }
        writer.write_all(b"+\n")?;

        for y in 0..self.height {
            // Murs verticaux & intérieurs de cellules
            writer.write_all(b"|")?;
            for x in 0..self.width {
                writer.write_all(b"   ")?;
                if self.cell(x, y).wall_east {
                    writer.write_all(b"|")?;
                } else {
                    writer.write_all(b" ")?;
                }
            }
            writer.write_all(b"\n")?;

            // Murs horizontaux & coins
            writer.write_all(b"+")?;
            for x in 0..self.width {
                let is_bottom_exit = self.open_ends && x == self.width - 1 && y == self.height - 1;
                if self.cell(x, y).wall_south && !is_bottom_exit {
                    writer.write_all(b"---")?;
                } else {
                    writer.write_all(b"   ")?;
                }
                writer.write_all(b"+")?;
            }
            writer.write_all(b"\n")?;
        }

        writer.flush()
    }
}

// Disjoint-Set Union (Union-Find) pour l'algorithme de Kruskal
struct DisjointSet {
    parent: Vec<usize>,
    rank: Vec<usize>,
}

impl DisjointSet {
    fn new(size: usize) -> Self {
        Self {
            parent: (0..size).collect(),
            rank: vec![0; size],
        }
    }

    fn find(&mut self, mut x: usize) -> usize {
        let mut root = x;
        while self.parent[root] != root {
            root = self.parent[root];
        }
        // Compression de chemin
        while self.parent[x] != root {
            let next = self.parent[x];
            self.parent[x] = root;
            x = next;
        }
        root
    }

    fn union(&mut self, a: usize, b: usize) -> bool {
        let root_a = self.find(a);
        let root_b = self.find(b);

        if root_a == root_b {
            return false;
        }

        if self.rank[root_a] < self.rank[root_b] {
            self.parent[root_a] = root_b;
        } else if self.rank[root_a] > self.rank[root_b] {
            self.parent[root_b] = root_a;
        } else {
            self.parent[root_b] = root_a;
            self.rank[root_a] += 1;
        }

        true
    }
}

#[derive(Clone, Copy)]
enum WallOrientation {
    Horizontal,
    Vertical,
}

#[derive(Clone, Copy)]
struct Wall {
    x: usize,
    y: usize,
    orientation: WallOrientation,
}

fn generate_kruskal<R: Rng>(maze: &mut Maze, rng: &mut R) {
    let mut walls = Vec::with_capacity(maze.width * (maze.height - 1) + (maze.width - 1) * maze.height);

    for y in 0..maze.height {
        for x in 0..maze.width {
            if x + 1 < maze.width {
                walls.push(Wall {
                    x,
                    y,
                    orientation: WallOrientation::Vertical,
                });
            }
            if y + 1 < maze.height {
                walls.push(Wall {
                    x,
                    y,
                    orientation: WallOrientation::Horizontal,
                });
            }
        }
    }

    walls.shuffle(rng);

    let mut dsu = DisjointSet::new(maze.width * maze.height);
    let mut edges_added = 0;
    let target_edges = maze.width * maze.height - 1;

    for wall in walls {
        let (u, v, neighbor) = match wall.orientation {
            WallOrientation::Vertical => {
                let u = maze.idx(wall.x, wall.y);
                let v = maze.idx(wall.x + 1, wall.y);
                (u, v, (wall.x + 1, wall.y))
            }
            WallOrientation::Horizontal => {
                let u = maze.idx(wall.x, wall.y);
                let v = maze.idx(wall.x, wall.y + 1);
                (u, v, (wall.x, wall.y + 1))
            }
        };

        if dsu.union(u, v) {
            maze.remove_wall_between((wall.x, wall.y), neighbor);
            edges_added += 1;
            if edges_added == target_edges {
                break;
            }
        }
    }
}

fn generate_dfs<R: Rng>(maze: &mut Maze, rng: &mut R) {
    let mut visited = vec![false; maze.width * maze.height];
    let mut stack = Vec::with_capacity(maze.width * maze.height);

    let start_x = 0;
    let start_y = 0;
    visited[maze.idx(start_x, start_y)] = true;
    stack.push((start_x, start_y));

    let mut neighbors = Vec::with_capacity(4);

    while let Some(&(cx, cy)) = stack.last() {
        neighbors.clear();

        if cx > 0 && !visited[maze.idx(cx - 1, cy)] {
            neighbors.push((cx - 1, cy));
        }
        if cx + 1 < maze.width && !visited[maze.idx(cx + 1, cy)] {
            neighbors.push((cx + 1, cy));
        }
        if cy > 0 && !visited[maze.idx(cx, cy - 1)] {
            neighbors.push((cx, cy - 1));
        }
        if cy + 1 < maze.height && !visited[maze.idx(cx, cy + 1)] {
            neighbors.push((cx, cy + 1));
        }

        if let Some(&next) = neighbors.choose(rng) {
            visited[maze.idx(next.0, next.1)] = true;
            maze.remove_wall_between((cx, cy), next);
            stack.push(next);
        } else {
            stack.pop();
        }
    }
}

fn run_generator<R: Rng>(algorithm: Algorithm, maze: &mut Maze, rng: &mut R) {
    match algorithm {
        Algorithm::Kruskal => generate_kruskal(maze, rng),
        Algorithm::Dfs => generate_dfs(maze, rng),
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let cli = Cli::parse();

    let mut maze = Maze::new(cli.width, cli.height, cli.open_ends)
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidInput, e))?;

    match cli.seed {
        Some(seed) => {
            let mut rng = StdRng::seed_from_u64(seed);
            run_generator(cli.algorithm, &mut maze, &mut rng);
        }
        None => {
            let mut rng = rand::thread_rng();
            run_generator(cli.algorithm, &mut maze, &mut rng);
        }
    }

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    maze.render(&mut handle)?;

    Ok(())
}

