            maze.remove_wall_between((wall.x, wall.y), neighbor);
            edges_added += 1;
            if edges_added == target_edges {
                break;
            }
        }
    }
}

fn generate_dfs<R: Rng>(maze: &mut Maze, rng: &mut R) {
    let mut visited = vec![false; maze.width * maze.height];
    let mut stack = Vec::with_capacity(maze.width * maze.height);

    let start_x = 0;
    let start_y = 0;
    visited[maze.idx(start_x, start_y)] = true;
    stack.push((start_x, start_y));

    let mut neighbors = Vec::with_capacity(4);

    while let Some(&(cx, cy)) = stack.last() {
        neighbors.clear();

        if cx > 0 && !visited[maze.idx(cx - 1, cy)] {
            neighbors.push((cx - 1, cy));
        }
        if cx + 1 < maze.width && !visited[maze.idx(cx + 1, cy)] {
            neighbors.push((cx + 1, cy));
        }
        if cy > 0 && !visited[maze.idx(cx, cy - 1)] {
            neighbors.push((cx, cy - 1));
        }
        if cy + 1 < maze.height && !visited[maze.idx(cx, cy + 1)] {
            neighbors.push((cx, cy + 1));
        }

        if let Some(&next) = neighbors.choose(rng) {
            visited[maze.idx(next.0, next.1)] = true;
            maze.remove_wall_between((cx, cy), next);
            stack.push(next);
        } else {
            stack.pop();
        }
    }
}

fn run_generator<R: Rng>(algorithm: Algorithm, maze: &mut Maze, rng: &mut R) {
    match algorithm {
        Algorithm::Kruskal => generate_kruskal(maze, rng),
        Algorithm::Dfs => generate_dfs(maze, rng),
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let cli = Cli::parse();

    let mut maze = Maze::new(cli.width, cli.height, cli.open_ends)
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidInput, e))?;

    match cli.seed {
        Some(seed) => {
            let mut rng = StdRng::seed_from_u64(seed);
            run_generator(cli.algorithm, &mut maze, &mut rng);
        }
        None => {
            let mut rng = rand::thread_rng();
            run_generator(cli.algorithm, &mut maze, &mut rng);
        }
    }

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    maze.render(&mut handle)?;

    Ok(())
}

