// src/main.rs
use std::borrow::Borrow;
use std::collections::hash_map::RandomState;
use std::fmt;
use std::hash::{BuildHasher, Hash, Hasher};
use std::ops::Index;

const DEFAULT_INITIAL_CAPACITY: usize = 8;
const MAX_LOAD_FACTOR_PERCENT: usize = 70;

/// Représente l'état d'une case dans la table à adressage ouvert.
#[derive(Clone, Debug, PartialEq, Eq)]
enum Bucket<K, V> {
    Empty,
    Tombstone,
    Occupied { key: K, value: V },
}

/// Table de hachage personnalisée avec sondage linéaire et redimensionnement dynamique.
#[derive(Clone)]
pub struct LinearHashMap<K, V, S = RandomState> {
    buckets: Vec<Bucket<K, V>>,
    len: usize,
    tombstones: usize,
    build_hasher: S,
}

impl<K, V> LinearHashMap<K, V, RandomState> {
    /// Crée une nouvelle table de hachage vide avec une capacité par défaut.
    #[must_use]
    pub fn new() -> Self {
        Self::with_capacity_and_hasher(DEFAULT_INITIAL_CAPACITY, RandomState::new())
    }

    /// Crée une table avec une capacité minimale garantie.
    #[must_use]
    pub fn with_capacity(capacity: usize) -> Self {
        Self::with_capacity_and_hasher(capacity, RandomState::new())
    }
}

impl<K, V, S> LinearHashMap<K, V, S> {
    /// Crée une table avec une capacité initiale et un constructeur de hash personnalisé.
    pub fn with_capacity_and_hasher(capacity: usize, build_hasher: S) -> Self {
        let cap = capacity.max(DEFAULT_INITIAL_CAPACITY).next_power_of_two();
        let mut buckets = Vec::with_capacity(cap);
        for _ in 0..cap {
            buckets.push(Bucket::Empty);
        }
        Self {
            buckets,
            len: 0,
            tombstones: 0,
            build_hasher,
        }
    }

    /// Retourne le nombre d'éléments actuellement présents dans la table.
    #[inline]
    pub fn len(&self) -> usize {
        self.len
    }

    /// Indique si la table est vide.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Retourne la capacité actuelle de la table (nombre d'alvéoles).
    #[inline]
    pub fn capacity(&self) -> usize {
        self.buckets.len()
    }
}

impl<K, V, S> LinearHashMap<K, V, S>
where
    K: Eq + Hash,
    S: BuildHasher,
{
    #[inline]
    fn make_hash<Q>(&self, key: &Q) -> u64
    where
        Q: ?Sized + Hash,
    {
        let mut hasher = self.build_hasher.build_hasher();
        key.hash(&mut hasher);
        hasher.finish()
    }

    /// Insère une paire clé-valeur. Si la clé était déjà présente, sa valeur est mise à jour
    /// et l'ancienne valeur est renvoyée.
    pub fn insert(&mut self, key: K, value: V) -> Option<V> {
        if self.should_grow() {
            self.resize(self.buckets.len() * 2);
        }

        let mask = self.buckets.len() - 1;
        let hash = self.make_hash(&key);
        let mut idx = (hash as usize) & mask;
        let mut first_tombstone = None;

        loop {
            match &mut self.buckets[idx] {
                Bucket::Empty => {
                    let insert_idx = first_tombstone.unwrap_or(idx);
                    if first_tombstone.is_some() {
                        self.tombstones -= 1;
                    }
                    self.buckets[insert_idx] = Bucket::Occupied { key, value };
                    self.len += 1;
                    return None;
                }
                Bucket::Tombstone => {
                    if first_tombstone.is_none() {
                        first_tombstone = Some(idx);
                    }
                }
                Bucket::Occupied {
                    key: existing_key,
                    value: existing_val,
                } => {
                    if existing_key == &key {
                        return Some(std::mem::replace(existing_val, value));
                    }
                }
            }

            idx = (idx + 1) & mask;
        }
    }

    /// Trouve l'index d'une clé donnée par sondage linéaire.
    fn find_index<Q>(&self, key: &Q) -> Option<usize>
    where
        K: Borrow<Q>,
        Q: ?Sized + Eq + Hash,
    {
        if self.buckets.is_empty() {
            return None;
        }

        let mask = self.buckets.len() - 1;
        let hash = self.make_hash(key);
        let mut idx = (hash as usize) & mask;

        loop {
            match &self.buckets[idx] {
                Bucket::Empty => return None,
                Bucket::Occupied {
                    key: existing_key, ..
                } if existing_key.borrow() == key => return Some(idx),
                _ => {}
            }
            idx = (idx + 1) & mask;
        }
    }

    /// Obtient une référence vers la valeur associée à la clé.
    pub fn get<Q>(&self, key: &Q) -> Option<&V>
    where
        K: Borrow<Q>,
        Q: ?Sized + Eq + Hash,
    {
        self.find_index(key).and_then(|idx| match &self.buckets[idx] {
            Bucket::Occupied { value, .. } => Some(value),
            _ => None,
        })
    }

    /// Obtient une référence mutable vers la valeur associée à la clé.
    pub fn get_mut<Q>(&mut self, key: &Q) -> Option<&mut V>
    where
        K: Borrow<Q>,
        Q: ?Sized + Eq + Hash,
    {
        match self.find_index(key) {
            Some(idx) => match &mut self.buckets[idx] {
                Bucket::Occupied { value, .. } => Some(value),
                _ => None,
            },
            None => None,
        }
    }

    /// Supprime la clé et renvoie son ancienne valeur, si présente.
    pub fn remove<Q>(&mut self, key: &Q) -> Option<V>
    where
        K: Borrow<Q>,
        Q: ?Sized + Eq + Hash,
    {
        let idx = self.find_index(key)?;
        let old_bucket = std::mem::replace(&mut self.buckets[idx], Bucket::Tombstone);
        self.len -= 1;
        self.tombstones += 1;

        match old_bucket {
            Bucket::Occupied { value, .. } => Some(value),
            _ => None,
        }
    }

    /// Vérifie si la clé est présente dans la table.
    pub fn contains_key<Q>(&self, key: &Q) -> bool
    where
        K: Borrow<Q>,
        Q: ?Sized + Eq + Hash,
    {
        self.find_index(key).is_some()
    }

    #[inline]
    fn should_grow(&self) -> bool {
        (self.len + self.tombstones + 1) * 100 >= self.buckets.len() * MAX_LOAD_FACTOR_PERCENT
    }

    /// Réalloue les alvéoles avec une nouvelle capacité et réinsère tous les éléments.
    fn resize(&mut self, new_capacity: usize) {
        let actual_new_cap = new_capacity.max(DEFAULT_INITIAL_CAPACITY).next_power_of_two();
        let old_buckets = std::mem::replace(&mut self.buckets, {
            let mut b = Vec::with_capacity(actual_new_cap);
            for _ in 0..actual_new_cap {
                b.push(Bucket::Empty);
            }
            b
        });

        self.len = 0;
        self.tombstones = 0;

        for bucket in old_buckets {
            if let Bucket::Occupied { key, value } = bucket {
                self.insert(key, value);
            }
        }
    }
}

impl<K, V> Default for LinearHashMap<K, V, RandomState> {
    fn default() -> Self {
        Self::new()
    }
}

/// Implémentation du trait `std::ops::Index` pour l'accès direct par référence de clé `map[&key]`.
impl<K, V, Q, S> Index<&Q> for LinearHashMap<K, V, S>
where
    K: Eq + Hash + Borrow<Q>,
    Q: ?Sized + Eq + Hash,
    S: BuildHasher,
{
    type Output = V;

    #[inline]
    fn index(&self, key: &Q) -> &Self::Output {
        match self.get(key) {
            Some(val) => val,
            None => panic!("LinearHashMap: clé introuvable lors de l'accès indexé"),
        }
    }
}

impl<K, V, S> fmt::Debug for LinearHashMap<K, V, S>
where
    K: fmt::Debug,
    V: fmt::Debug,
{
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut map = f.debug_map();
        for bucket in &self.buckets {
            if let Bucket::Occupied { key, value } = bucket {
                map.entry(key, value);
            }
        }
        map.finish()
    }
}

fn main() {
    println!("=== Démonstration de LinearHashMap ===");

    let mut map: LinearHashMap<String, i32> = LinearHashMap::new();

    // Insertion
    map.insert("Alice".to_string(), 42);
    map.insert("Bob".to_string(), 84);
    map.insert("Charlie".to_string(), 126);

    println!("Taille actuelle : {}", map.len());
    println!("Capacité initiale : {}", map.capacity());

    // Accès indexé via std::ops::Index (&str via Borrow)
    println!("Note d'Alice (via index) : {}", map["Alice"]);
    println!("Note de Bob (via index) : {}", map["Bob"]);

    // Test de mise à jour
    let old_value = map.insert("Alice".to_string(), 99);
    println!("Ancienne valeur d'Alice : {:?}", old_value);
    println!("Nouvelle valeur d'Alice : {}", map["Alice"]);

    // Suppression
    let removed = map.remove("Bob");
    println!("Élément supprimé (Bob) : {:?}", removed);
    println!("Contient Bob après suppression ? {}", map.contains_key("Bob"));

    // Redimensionnement dynamique
    println!("\nInsertion de 20 éléments pour déclencher le redimensionnement...");
    for i in 0..20 {
        map.insert(format!("user_{}", i), i * 10);
    }

    println!("Taille après ajouts : {}", map.len());
    println!("Nouvelle capacité : {}", map.capacity());
    println!("Accès indexé à 'user_15' : {}", map["user_15"]);
    println!("Affichage Debug de la table :\n{:?}", map);
}

