mod tests {
    use super::*;

    #[test]
    fn test_insert_and_get() {
        let mut map = LinearHashMap::new();
        assert_eq!(map.insert("a", 1), None);
        assert_eq!(map.insert("b", 2), None);
        assert_eq!(map.get("a"), Some(&1));
        assert_eq!(map.get("b"), Some(&2));
        assert_eq!(map.get("c"), None);
        assert_eq!(map.len(), 2);
    }

    #[test]
    fn test_overwrite() {
        let mut map = LinearHashMap::new();
        assert_eq!(map.insert("key", 10), None);
        assert_eq!(map.insert("key", 20), Some(10));
        assert_eq!(map.get("key"), Some(&20));
        assert_eq!(map.len(), 1);
    }

    #[test]
    fn test_index_trait() {
        let mut map = LinearHashMap::new();
        map.insert("x".to_string(), 100);
        map.insert("y".to_string(), 200);

        assert_eq!(map["x"], 100);
        assert_eq!(map["y"], 200);
    }

    #[test]
    #[should_panic(expected = "LinearHashMap: clé introuvable")]
    fn test_index_panic_on_missing_key() {
        let map: LinearHashMap<&str, i32> = LinearHashMap::new();
        let _ = map["absent"];
    }

    #[test]
    fn test_remove_with_tombstone() {
        let mut map = LinearHashMap::new();
        map.insert("k1", 1);
        map.insert("k2", 2);
        map.insert("k3", 3);

        assert_eq!(map.remove("k2"), Some(2));
        assert_eq!(map.get("k2"), None);
        assert_eq!(map.get("k3"), Some(&3));
        assert_eq!(map.len(), 2);

        // Réinsertion sur tombstone
        map.insert("k2", 20);
        assert_eq!(map.get("k2"), Some(&20));
    }

    #[test]
    fn test_dynamic_resizing() {
        let mut map = LinearHashMap::new();
        let initial_cap = map.capacity();

        for i in 0..100 {
            map.insert(i, i * 2);
        }

        assert!(map.capacity() > initial_cap);
        assert_eq!(map.len(), 100);

        for i in 0..100 {
            assert_eq!(map[&i], i * 2);
        }
    }
}

