// src/main.rs
use std::cell::UnsafeCell;
use std::mem::MaybeUninit;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread;

/// Tampon circulaire à capacité fixe, lock-free pour architecture SPSC
/// (Single-Producer Single-Consumer).
pub struct AtomicRingBuffer<T, const CAP: usize> {
    buffer: [UnsafeCell<MaybeUninit<T>>; CAP],
    tail: AtomicUsize, // Indice d'écriture (géré par le producteur)
    head: AtomicUsize, // Indice de lecture (géré par le consommateur)
}

// Sécurité pour le partage entre threads : T doit être Send pour transiter d'un thread à l'autre.
unsafe impl<T: Send, const CAP: usize> Sync for AtomicRingBuffer<T, CAP> {}
unsafe impl<T: Send, const CAP: usize> Send for AtomicRingBuffer<T, CAP> {}

impl<T, const CAP: usize> AtomicRingBuffer<T, CAP> {
    /// Crée un nouveau tampon circulaire.
    ///
    /// # Panics
    /// Panique si `CAP == 0`.
    pub fn new() -> Self {
        assert!(CAP > 0, "La capacité du tampon doit être strictement supérieure à 0.");

        // Initialisation du tableau de slots non initialisés en évitant toute copie
        let buffer = unsafe {
            let mut arr: MaybeUninit<[UnsafeCell<MaybeUninit<T>>; CAP]> = MaybeUninit::uninit();
            let ptr = arr.as_mut_ptr() as *mut UnsafeCell<MaybeUninit<T>>;
            for i in 0..CAP {
                ptr.add(i).write(UnsafeCell::new(MaybeUninit::uninit()));
            }
            arr.assume_init()
        };

        Self {
            buffer,
            tail: AtomicUsize::new(0),
            head: AtomicUsize::new(0),
        }
    }

    /// Capacité maximale du tampon.
    #[inline]
    pub const fn capacity(&self) -> usize {
        CAP
    }

    /// Nombre d'éléments actuellement présents dans le tampon.
    pub fn len(&self) -> usize {
        let head = self.head.load(Ordering::Acquire);
        let tail = self.tail.load(Ordering::Acquire);
        tail.wrapping_sub(head)
    }

    /// Vérifie si le tampon est vide.
    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// Vérifie si le tampon est plein.
    pub fn is_full(&self) -> bool {
        self.len() >= CAP
    }

    /// Tente d'insérer un élément dans le tampon (côté producteur).
    ///
    /// Retourne `Err(item)` si le tampon est plein.
    pub fn push(&self, item: T) -> Result<(), T> {
        let tail = self.tail.load(Ordering::Relaxed);
        let head = self.head.load(Ordering::Acquire);

        // Si le tampon est plein
        if tail.wrapping_sub(head) >= CAP {
            return Err(item);
        }

        let slot_idx = tail % CAP;
        unsafe {
            let cell = self.buffer[slot_idx].get();
            (*cell).write(item);
        }

        // Publie le nouvel indice d'écriture avec sémantique Release
        self.tail.store(tail.wrapping_add(1), Ordering::Release);
        Ok(())
    }

    /// Tente d'extraire un élément du tampon (côté consommateur).
    ///
    /// Retourne `None` si le tampon est vide.
    pub fn pop(&self) -> Option<T> {
        let head = self.head.load(Ordering::Relaxed);
        let tail = self.tail.load(Ordering::Acquire);

        // Si le tampon est vide
        if tail == head {
            return None;
        }

        let slot_idx = head % CAP;
        let item = unsafe {
            let cell = self.buffer[slot_idx].get();
            (*cell).assume_init_read()
        };

        // Met à jour l'indice de lecture avec sémantique Release
        self.head.store(head.wrapping_add(1), Ordering::Release);
        Some(item)
    }
}

impl<T, const CAP: usize> Default for AtomicRingBuffer<T, CAP> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T, const CAP: usize> Drop for AtomicRingBuffer<T, CAP> {
    fn drop(&mut self) {
        // En accédant avec `&mut self`, aucun autre thread ne lit ou n'écrit
        let mut head = self.head.load(Ordering::Relaxed);
        let tail = self.tail.load(Ordering::Relaxed);

        while head != tail {
            let slot_idx = head % CAP;
            unsafe {
                let cell = self.buffer[slot_idx].get();
                (*cell).assume_init_drop();
            }
            head = head.wrapping_add(1);
        }
    }
}

fn main() {
    println!("=== Démonstration du Ring Buffer Atomique SPSC ===");

    const CAPACITY: usize = 8;
    const NUM_ITEMS: usize = 100_000;

    let ring_buffer = Arc::new(AtomicRingBuffer::<usize, CAPACITY>::new());

    println!("Capacité du tampon : {}", ring_buffer.capacity());

    let producer_buf = Arc::clone(&ring_buffer);
    let producer_handle = thread::spawn(move || {
        for i in 0..NUM_ITEMS {
            let mut item = i;
            while let Err(unsent) = producer_buf.push(item) {
                item = unsent;
                thread::yield_now();
            }
        }
        println!("Producteur : {} éléments insérés.", NUM_ITEMS);
    });

    let consumer_buf = Arc::clone(&ring_buffer);
    let consumer_handle = thread::spawn(move || {
        let mut received_count = 0;
        let mut expected_val = 0;

        while received_count < NUM_ITEMS {
            match consumer_buf.pop() {
                Some(val) => {
                    if val != expected_val {
                        eprintln!("Erreur d'ordre : attendu {}, reçu {}", expected_val, val);
                        return false;
                    }
                    expected_val += 1;
                    received_count += 1;
                }
                None => {
                    thread::yield_now();
                }
            }
        }
        println!("Consommateur : {} éléments vérifiés avec succès.", received_count);
        true
    });

    match producer_handle.join() {
        Ok(_) => (),
        Err(e) => eprintln!("Erreur lors de l'attente du producteur : {:?}", e),
    }

    match consumer_handle.join() {
        Ok(success) => {
            if success {
                println!("Démonstration multithread terminée sans aucune erreur !");
            } else {
                eprintln!("Échec de validation lors de la consommation.");
            }
        }
        Err(e) => eprintln!("Erreur lors de l'attente du consommateur : {:?}", e),
    }

    // Démonstration simple monothread
    println!("\n--- Démonstration monothread ---");
    let local_buf = AtomicRingBuffer::<String, 3>::new();
    println!("Push 'Alpha': {:?}", local_buf.push("Alpha".to_string()));
    println!("Push 'Beta': {:?}", local_buf.push("Beta".to_string()));
    println!("Push 'Gamma': {:?}", local_buf.push("Gamma".to_string()));
    println!("Push 'Delta' (plein attendu): {:?}", local_buf.push("Delta".to_string()));

    println!("Pop 1: {:?}", local_buf.pop());
    println!("Push 'Epsilon': {:?}", local_buf.push("Epsilon".to_string()));

    while let Some(msg) = local_buf.pop() {
        println!("Pop restant : {}", msg);
    }
    println!("Le tampon est vide : {}", local_buf.is_empty());
}

