    fn test_push_pop_basic() {
        let buffer = AtomicRingBuffer::<i32, 4>::new();
        assert!(buffer.is_empty());
        assert_eq!(buffer.len(), 0);

        assert!(buffer.push(10).is_ok());
        assert!(buffer.push(20).is_ok());
        assert_eq!(buffer.len(), 2);

        assert_eq!(buffer.pop(), Some(10));
        assert_eq!(buffer.pop(), Some(20));
        assert_eq!(buffer.pop(), None);
        assert!(buffer.is_empty());
    }

    #[test]
    fn test_capacity_saturation() {
        let buffer = AtomicRingBuffer::<i32, 2>::new();
        assert!(buffer.push(1).is_ok());
        assert!(buffer.push(2).is_ok());
        assert!(buffer.is_full());

        let err = buffer.push(3);
        assert_eq!(err, Err(3));

        assert_eq!(buffer.pop(), Some(1));
        assert!(buffer.push(4).is_ok());
        assert_eq!(buffer.pop(), Some(2));
        assert_eq!(buffer.pop(), Some(4));
        assert_eq!(buffer.pop(), None);
    }

    struct DropDetector<'a>(&'a AtomicBool);
    impl<'a> Drop for DropDetector<'a> {
        fn drop(&mut self) {
            self.0.store(true, Ordering::SeqCst);
        }
    }

    #[test]
    fn test_drop_cleanup() {
        let dropped = AtomicBool::new(false);
        {
            let buffer = AtomicRingBuffer::<DropDetector, 4>::new();
            assert!(buffer.push(DropDetector(&dropped)).is_ok());
        }
        assert!(dropped.load(Ordering::SeqCst));
    }
}

