// src/main.rs
//! Moteur de recherche de texte par Automate Fini Non Déterministe (NFA)
//! Implémentation complète de l'algorithme de construction de Thompson et de simulation
//! sans dépendance externe.

use std::collections::{BTreeSet, HashSet};
use std::fmt;

// ============================================================================
// 1. GESTION DES ERREURS
// ============================================================================

#[derive(Debug, PartialEq, Eq, Clone)]
pub enum EngineError {
    UnexpectedEndOfString,
    UnexpectedChar(char, usize),
    UnmatchedParenthesis(usize),
    TrailingEscape(usize),
    InvalidCharClass(usize),
    EmptyExpression,
}

impl fmt::Display for EngineError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            EngineError::UnexpectedEndOfString => write!(f, "Fin inattendue de l'expression"),
            EngineError::UnexpectedChar(c, pos) => {
                write!(f, "Caractère inattendu '{}' à l'index {}", c, pos)
            }
            EngineError::UnmatchedParenthesis(pos) => {
                write!(f, "Parenthèse non appariée à l'index {}", pos)
            }
            EngineError::TrailingEscape(pos) => {
                write!(f, "Caractère d'échappement '\\' pendant à l'index {}", pos)
            }
            EngineError::InvalidCharClass(pos) => {
                write!(f, "Classe de caractères invalide ou non fermée à l'index {}", pos)
            }
            EngineError::EmptyExpression => write!(f, "Expression régulière vide"),
        }
    }
}

impl std::error::Error for EngineError {}

// ============================================================================
// 2. PARSER & ARBRE DE SYNTAXE ABSTRAITE (AST)
// ============================================================================

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CharClassItem {
    Single(char),
    Range(char, char),
}

impl CharClassItem {
    pub fn matches(&self, c: char) -> bool {
        match self {
            CharClassItem::Single(target) => *target == c,
            CharClassItem::Range(start, end) => c >= *start && c <= *end,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AstNode {
    Literal(char),
    AnyChar, // '.'
    CharClass {
        negated: bool,
        items: Vec<CharClassItem>,
    },
    Concat(Vec<AstNode>),
    Alternation(Vec<AstNode>),
    ZeroOrMore(Box<AstNode>), // '*'
    OneOrMore(Box<AstNode>),  // '+'
    Optional(Box<AstNode>),   // '?'
    StartAnchor,              // '^'
    EndAnchor,                // '$'
}

struct Parser {
    chars: Vec<(usize, char)>,
    pos: usize,
}

impl Parser {
    fn new(input: &str) -> Self {
        Self {
            chars: input.char_indices().collect(),
            pos: 0,
        }
    }

    fn peek(&self) -> Option<(usize, char)> {
        self.chars.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<(usize, char)> {
        let item = self.peek();
        if item.is_some() {
            self.pos += 1;
        }
        item
    }

    fn parse(&mut self) -> Result<AstNode, EngineError> {
        if self.chars.is_empty() {
            return Err(EngineError::EmptyExpression);
        }
        let node = self.parse_alternation()?;
        if let Some((idx, c)) = self.peek() {
            return Err(EngineError::UnexpectedChar(c, idx));
        }
        Ok(node)
    }

    fn parse_alternation(&mut self) -> Result<AstNode, EngineError> {
        let mut branches = Vec::new();
        branches.push(self.parse_concat()?);

        while let Some((_, '|')) = self.peek() {
            self.next();
            branches.push(self.parse_concat()?);
        }

        if branches.len() == 1 {
            Ok(branches.remove(0))
        } else {
            Ok(AstNode::Alternation(branches))
        }
    }

    fn parse_concat(&mut self) -> Result<AstNode, EngineError> {
        let mut sequence = Vec::new();

        while let Some((_, c)) = self.peek() {
            if c == '|' || c == ')' {
                break;
            }
            let atom = self.parse_repeat()?;
            sequence.push(atom);
        }

        if sequence.is_empty() {
            Ok(AstNode::Concat(Vec::new()))
        } else if sequence.len() == 1 {
            Ok(sequence.remove(0))
        } else {
            Ok(AstNode::Concat(sequence))
        }
    }

    fn parse_repeat(&mut self) -> Result<AstNode, EngineError> {
        let mut node = self.parse_atom()?;

        while let Some((idx, c)) = self.peek() {
            match c {
                '*' => {
                    self.next();
                    node = AstNode::ZeroOrMore(Box::new(node));
                }
                '+' => {
                    self.next();
                    node = AstNode::OneOrMore(Box::new(node));
                }
                '?' => {
                    self.next();
                    node = AstNode::Optional(Box::new(node));
                }
                _ => break,
            }
            let _ = idx;
        }

        Ok(node)
    }

    fn parse_atom(&mut self) -> Result<AstNode, EngineError> {
        match self.next() {
            Some((idx, '(')) => {
                let inner = self.parse_alternation()?;
                match self.next() {
                    Some((_, ')')) => Ok(inner),
                    _ => Err(EngineError::UnmatchedParenthesis(idx)),
                }
            }
            Some((idx, '[')) => self.parse_char_class(idx),
            Some((idx, '\\')) => match self.next() {
                Some((_, escaped)) => Ok(AstNode::Literal(escaped)),
                None => Err(EngineError::TrailingEscape(idx)),
            },
            Some((_, '.')) => Ok(AstNode::AnyChar),
            Some((_, '^')) => Ok(AstNode::StartAnchor),
            Some((_, '$')) => Ok(AstNode::EndAnchor),
            Some((idx, c)) if c == '*' || c == '+' || c == '?' || c == ')' || c == '|' => {
                Err(EngineError::UnexpectedChar(c, idx))
            }
            Some((_, c)) => Ok(AstNode::Literal(c)),
            None => Err(EngineError::UnexpectedEndOfString),
        }
    }

    fn parse_char_class(&mut self, start_idx: usize) -> Result<AstNode, EngineError> {
        let mut negated = false;
        let mut items = Vec::new();

        if let Some((_, '^')) = self.peek() {
            self.next();
            negated = true;
        }

        let mut class_chars: Vec<char> = Vec::new();
        let mut closed = false;

        while let Some((idx, c)) = self.next() {
            if c == ']' && (!class_chars.is_empty() || negated) {
                closed = true;
                break;
            } else if c == '\\' {
                if let Some((_, escaped)) = self.next() {
                    class_chars.push(escaped);
                } else {
                    return Err(EngineError::TrailingEscape(idx));
                }
            } else {
                class_chars.push(c);
            }
        }

        if !closed {
            return Err(EngineError::InvalidCharClass(start_idx));
        }

        let mut i = 0;
        while i < class_chars.len() {
            if i + 2 < class_chars.len() && class_chars[i + 1] == '-' {
                let start = class_chars[i];
                let end = class_chars[i + 2];
                if start > end {
                    return Err(EngineError::InvalidCharClass(start_idx));
                }
                items.push(CharClassItem::Range(start, end));
                i += 3;
            } else {
                items.push(CharClassItem::Single(class_chars[i]));
                i += 1;
            }
        }

        Ok(AstNode::CharClass { negated, items })
    }
}

// ============================================================================
// 3. CONSTRUCTION DU NFA (ALGORITHME DE THOMPSON)
// ============================================================================

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Transition {
    Epsilon(usize),
    Char(char, usize),
    AnyChar(usize),
    CharClass {
        negated: bool,
        items: Vec<CharClassItem>,
        target: usize,
    },
    StartAnchor(usize),
    EndAnchor(usize),
}

#[derive(Debug, Clone)]
pub struct NfaState {
    pub transitions: Vec<Transition>,
    pub is_match: bool,
}

#[derive(Debug, Clone)]
pub struct Nfa {
    pub states: Vec<NfaState>,
    pub start_state: usize,
}

struct Fragment {
    start: usize,
    outs: Vec<usize>,
}

impl Nfa {
    pub fn compile(pattern: &str) -> Result<Self, EngineError> {
        let mut parser = Parser::new(pattern);
        let ast = parser.parse()?;

        let mut states: Vec<NfaState> = Vec::new();
        let frag = Self::build_fragment(&ast, &mut states);

        let match_state = states.len();
        states.push(NfaState {
            transitions: Vec::new(),
            is_match: true,
        });

        for out in frag.outs {
            states[out].transitions.push(Transition::Epsilon(match_state));
        }

        Ok(Self {
            states,
            start_state: frag.start,
        })
    }

    fn new_state(states: &mut Vec<NfaState>) -> usize {
        let id = states.len();
        states.push(NfaState {
            transitions: Vec::new(),
            is_match: false,
        });
        id
    }

    fn build_fragment(ast: &AstNode, states: &mut Vec<NfaState>) -> Fragment {
        match ast {
            AstNode::Literal(c) => {
                let start = Self::new_state(states);
                let target = Self::new_state(states);
                states[start].transitions.push(Transition::Char(*c, target));
                Fragment {
                    start,
                    outs: vec![target],
                }
            }
            AstNode::AnyChar => {
                let start = Self::new_state(states);
                let target = Self::new_state(states);
                states[start].transitions.push(Transition::AnyChar(target));
                Fragment {
                    start,
                    outs: vec![target],
                }
            }
            AstNode::CharClass { negated, items } => {
                let start = Self::new_state(states);
                let target = Self::new_state(states);
                states[start].transitions.push(Transition::CharClass {
                    negated: *negated,
                    items: items.clone(),
                    target,
                });
                Fragment {
                    start,
                    outs: vec![target],
                }
            }
            AstNode::StartAnchor => {
                let start = Self::new_state(states);
                let target = Self::new_state(states);
                states[start].transitions.push(Transition::StartAnchor(target));
                Fragment {
                    start,
                    outs: vec![target],
                }
            }
            AstNode::EndAnchor => {
                let start = Self::new_state(states);
                let target = Self::new_state(states);
                states[start].transitions.push(Transition::EndAnchor(target));
                Fragment {
                    start,
                    outs: vec![target],
                }
            }
            AstNode::Concat(nodes) => {
                if nodes.is_empty() {
                    let s = Self::new_state(states);
                    return Fragment {
                        start: s,
                        outs: vec![s],
                    };
                }
                let mut iter = nodes.iter();
                let first = match iter.next() {
                    Some(first_node) => Self::build_fragment(first_node, states),
                    None => {
                        let s = Self::new_state(states);
                        return Fragment {
                            start: s,
                            outs: vec![s],
                        };
                    }
                };
                let mut current_outs = first.outs;
                let start_state = first.start;

                for node in iter {
                    let next_frag = Self::build_fragment(node, states);
                    for out in current_outs {
                        states[out]
                            .transitions
                            .push(Transition::Epsilon(next_frag.start));
                    }
                    current_outs = next_frag.outs;
                }

                Fragment {
                    start: start_state,
                    outs: current_outs,
                }
            }
            AstNode::Alternation(branches) => {
                let start = Self::new_state(states);
                let mut outs = Vec::new();

                for branch in branches {
                    let branch_frag = Self::build_fragment(branch, states);
                    states[start]
                        .transitions
                        .push(Transition::Epsilon(branch_frag.start));
                    outs.extend(branch_frag.outs);
                }

                Fragment { start, outs }
            }
            AstNode::ZeroOrMore(inner) => {
                let start = Self::new_state(states);
                let inner_frag = Self::build_fragment(inner, states);

                states[start]
                    .transitions
                    .push(Transition::Epsilon(inner_frag.start));
                for out in inner_frag.outs {
                    states[out]
                        .transitions
                        .push(Transition::Epsilon(inner_frag.start));
                    states[out].transitions.push(Transition::Epsilon(start));
                }

                Fragment {
                    start,
                    outs: vec![start],
                }
            }
            AstNode::OneOrMore(inner) => {
                let inner_frag = Self::build_fragment(inner, states);
                let loop_state = Self::new_state(states);

                for out in inner_frag.outs {
                    states[out]
                        .transitions
                        .push(Transition::Epsilon(loop_state));
                }
                states[loop_state]
                    .transitions
                    .push(Transition::Epsilon(inner_frag.start));

                Fragment {
                    start: inner_frag.start,
                    outs: vec![loop_state],
                }
            }
            AstNode::Optional(inner) => {
                let start = Self::new_state(states);
                let inner_frag = Self::build_fragment(inner, states);

                states[start]
                    .transitions
                    .push(Transition::Epsilon(inner_frag.start));
                let mut outs = inner_frag.outs;
                outs.push(start);

                Fragment { start, outs }
            }
        }
    }
}

// ============================================================================
// 4. MOTEUR D'EXÉCUTION (SIMULATION DU NFA)
// ============================================================================

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MatchResult {
    pub start: usize,
    pub end: usize,
}

pub struct SearchEngine {
    nfa: Nfa,
}

impl SearchEngine {
    pub fn new(pattern: &str) -> Result<Self, EngineError> {
        let nfa = Nfa::compile(pattern)?;
        Ok(Self { nfa })
    }

    /// Calcule la fermeture epsilon pour un ensemble d'états
    fn epsilon_closure(
        &self,
        initial_states: &BTreeSet<usize>,
        is_start_of_text: bool,
        is_end_of_text: bool,
    ) -> BTreeSet<usize> {
        let mut closure = initial_states.clone();
        let mut stack: Vec<usize> = initial_states.iter().copied().collect();
        let mut visited = HashSet::new();

        for &st in initial_states {
            visited.insert(st);
        }

        while let Some(state_idx) = stack.pop() {
            if let Some(state) = self.nfa.states.get(state_idx) {
                for trans in &state.transitions {
                    let target_opt = match trans {
                        Transition::Epsilon(target) => Some(*target),
                        Transition::StartAnchor(target) if is_start_of_text => Some(*target),
                        Transition::EndAnchor(target) if is_end_of_text => Some(*target),
                        _ => None,
                    };

                    if let Some(target) = target_opt {
                        if visited.insert(target) {
                            closure.insert(target);
                            stack.push(target);
                        }
                    }
                }
            }
        }

        closure
    }

    /// Avance dans le NFA avec un caractère donné
    fn step(&self, current_states: &BTreeSet<usize>, c: char) -> BTreeSet<usize> {
        let mut next_states = BTreeSet::new();

        for &state_idx in current_states {
            if let Some(state) = self.nfa.states.get(state_idx) {
                for trans in &state.transitions {
                    match trans {
                        Transition::Char(expected, target) if *expected == c => {
                            next_states.insert(*target);
                        }
                        Transition::AnyChar(target) if c != '\n' => {
                            next_states.insert(*target);
                        }
                        Transition::CharClass {
                            negated,
                            items,
                            target,
                        } => {
                            let matches_any = items.iter().any(|item| item.matches(c));
                            let is_match = if *negated {
                                !matches_any && c != '\n'
                            } else {
                                matches_any
                            };
                            if is_match {
                                next_states.insert(*target);
                            }
                        }
                        _ => {}
                    }
                }
            }
        }

        next_states
    }

    /// Vérifie si l'un des états actuels est un état d'acceptation
    fn contains_match(&self, states: &BTreeSet<usize>) -> bool {
        states.iter().any(|&st| {
            self.nfa
                .states
                .get(st)
                .map(|s| s.is_match)
                .unwrap_or(false)
        })
    }

    /// Teste si le motif correspond au texte (n'importe où ou ancré)
    pub fn is_match(&self, text: &str) -> bool {
        self.find(text).is_some()
    }

    /// Trouve la première correspondance dans le texte
    pub fn find(&self, text: &str) -> Option<MatchResult> {
        let char_indices: Vec<(usize, char)> = text.char_indices().collect();
        let total_chars = char_indices.len();

        for i in 0..=total_chars {
            let start_byte = if i < total_chars {
                char_indices[i].0
            } else {
                text.len()
            };

            let mut initial = BTreeSet::new();
            initial.insert(self.nfa.start_state);

            let is_start = i == 0;
            let is_end = i == total_chars;
            let mut current = self.epsilon_closure(&initial, is_start, is_end);

            let mut best_match: Option<MatchResult> = None;

            if self.contains_match(&current) {
                best_match = Some(MatchResult {
                    start: start_byte,
                    end: start_byte,
                });
            }

            for j in i..total_chars {
                let (_, c) = char_indices[j];
                let next_char_end_byte = if j + 1 < total_chars {
                    char_indices[j + 1].0
                } else {
                    text.len()
                };

                let step_states = self.step(&current, c);
                if step_states.is_empty() {
                    break;
                }

                let is_step_end = j + 1 == total_chars;
                current = self.epsilon_closure(&step_states, false, is_step_end);

                if self.contains_match(&current) {
                    best_match = Some(MatchResult {
                        start: start_byte,
                        end: next_char_end_byte,
                    });
                }
            }

            if let Some(m) = best_match {
                return Some(m);
            }
        }

        None
    }

    /// Trouve toutes les correspondances non recouvrantes dans le texte
    pub fn find_all(&self, text: &str) -> Vec<MatchResult> {
        let mut results = Vec::new();
        let mut byte_offset = 0;

        while byte_offset <= text.len() {
            let slice = &text[byte_offset..];
            if let Some(m) = self.find(slice) {
                let global_start = byte_offset + m.start;
                let global_end = byte_offset + m.end;

                results.push(MatchResult {
                    start: global_start,
                    end: global_end,
                });

                if m.end == 0 {
                    // Correspondance de longueur nulle (ex: pattern optionnel ou ancres)
                    if let Some((next_char_len, _)) = slice.chars().next().map(|c| (c.len_utf8(), c))
                    {
                        byte_offset += next_char_len;
                    } else {
                        break;
                    }
                } else {
                    byte_offset += m.end;
                }
            } else {
                break;
            }
        }

        results
    }
}

