use std::error::Error;
use std::fmt;

/// Erreurs possibles lors du décodage Base64
#[derive(Debug, PartialEq, Eq, Clone)]
pub enum Base64Error {
    /// La longueur de la chaîne d'entrée n'est pas un multiple de 4
    InvalidLength,
    /// Caractère invalide rencontré à une position spécifique
    InvalidCharacter(char, usize),
    /// Emplacement ou format de padding incorrect
    InvalidPadding,
    /// Bits de padding résiduels non nuls (rejet RFC 4648 §3.5)
    NonZeroPaddingBits,
}

impl fmt::Display for Base64Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidLength => write!(f, "Longueur d'entrée invalide : doit être un multiple de 4"),
            Self::InvalidCharacter(c, pos) => {
                write!(f, "Caractère invalide '{c}' à la position {pos}")
            }
            Self::InvalidPadding => write!(f, "Format ou position de padding '=' invalide"),
            Self::NonZeroPaddingBits => {
                write!(f, "Bits de padding résiduels non nuls (non canonique)")
            }
        }
    }
}

impl Error for Base64Error {}

/// Table de correspondance binaire RFC 4648 vers octet ASCII
const ENCODE_TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

/// Encode un slice d'octets en chaîne Base64 conforme RFC 4648.
///
/// Utilise des opérations binaires bit-shift pour extraire chaque groupe de 6 bits.
pub fn encode(input: &[u8]) -> String {
    let mut output = String::with_capacity(((input.len() + 2) / 3) * 4);
    let chunks = input.chunks_exact(3);
    let remainder = chunks.remainder();

    for chunk in chunks {
        let b0 = chunk[0];
        let b1 = chunk[1];
        let b2 = chunk[2];

        // Décomposition bitwise 3 octets (24 bits) -> 4 sextets (4 x 6 bits)
        let s0 = (b0 >> 2) & 0x3F;
        let s1 = ((b0 << 4) | (b1 >> 4)) & 0x3F;
        let s2 = ((b1 << 2) | (b2 >> 6)) & 0x3F;
        let s3 = b2 & 0x3F;

        output.push(ENCODE_TABLE[s0 as usize] as char);
        output.push(ENCODE_TABLE[s1 as usize] as char);
        output.push(ENCODE_TABLE[s2 as usize] as char);
        output.push(ENCODE_TABLE[s3 as usize] as char);
    }

    match remainder.len() {
        1 => {
            let b0 = remainder[0];
            let s0 = (b0 >> 2) & 0x3F;
            let s1 = (b0 << 4) & 0x3F;

            output.push(ENCODE_TABLE[s0 as usize] as char);
            output.push(ENCODE_TABLE[s1 as usize] as char);
            output.push('=');
            output.push('=');
        }
        2 => {
            let b0 = remainder[0];
            let b1 = remainder[1];
            let s0 = (b0 >> 2) & 0x3F;
            let s1 = ((b0 << 4) | (b1 >> 4)) & 0x3F;
            let s2 = (b1 << 2) & 0x3F;

            output.push(ENCODE_TABLE[s0 as usize] as char);
            output.push(ENCODE_TABLE[s1 as usize] as char);
            output.push(ENCODE_TABLE[s2 as usize] as char);
            output.push('=');
        }
        _ => {}
    }

    output
}

/// Convertit un caractère ASCII Base64 en valeur numérique 6 bits (0-63).
#[inline]
fn decode_char(c: u8, pos: usize) -> Result<u32, Base64Error> {
    match c {
        b'A'..=b'Z' => Ok((c - b'A') as u32),
        b'a'..=b'z' => Ok((c - b'a' + 26) as u32),
        b'0'..=b'9' => Ok((c - b'0' + 52) as u32),
        b'+' => Ok(62),
        b'/' => Ok(63),
        _ => Err(Base64Error::InvalidCharacter(c as char, pos)),
    }
}

/// Décode une chaîne Base64 en octets bruts selon la RFC 4648.
///
/// Effectue la reconstruction de mots de 24 bits par bit-shift
/// et valide rigoureusement le padding ainsi que les bits canoniques.
pub fn decode(input: &str) -> Result<Vec<u8>, Base64Error> {
