// src/main.rs
use clap::{Parser, Subcommand};
use num_traits::{Float, FromPrimitive, Signed};
use std::fmt;
use std::ops::{Add, AddAssign, Index, IndexMut, Mul};
use std::str::FromStr;
use thiserror::Error;

/// Erreurs liées aux opérations et représentations matricielles
#[derive(Debug, Error, PartialEq)]
pub enum MatrixError {
    #[error("Erreur de parsing de la matrice : {0}")]
    ParseError(String),

    #[error("Dimensions invalides : les dimensions doivent être strictement positives")]
    EmptyMatrix,

    #[error("Nombre d'éléments incohérent : attendu {expected}, reçu {actual}")]
    ElementCountMismatch { expected: usize, actual: usize },

    #[error("Incompatibilité de dimensions pour la multiplication : A est ({rows_a}x{cols_a}) mais B est ({rows_b}x{cols_b})")]
    DimensionMismatchMultiply {
        rows_a: usize,
        cols_a: usize,
        rows_b: usize,
        cols_b: usize,
    },

    #[error("La matrice doit être carrée pour calculer le déterminant : reçue ({rows}x{cols})")]
    NotSquare { rows: usize, cols: usize },
}

/// Structure générique de matrice 2D stockée à plat en mémoire contiguë (row-major).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Matrix<T> {
    rows: usize,
    cols: usize,
    data: Vec<T>,
}

impl<T> Matrix<T> {
    /// Crée une nouvelle matrice à partir d'un vecteur de données et de ses dimensions.
    pub fn new(rows: usize, cols: usize, data: Vec<T>) -> Result<Self, MatrixError> {
        if rows == 0 || cols == 0 {
            return Err(MatrixError::EmptyMatrix);
        }
        if data.len() != rows * cols {
            return Err(MatrixError::ElementCountMismatch {
                expected: rows * cols,
                actual: data.len(),
            });
        }
        Ok(Self { rows, cols, data })
    }

    /// Nombre de lignes.
    #[inline]
    pub fn rows(&self) -> usize {
        self.rows
    }

    /// Nombre de colonnes.
    #[inline]
    pub fn cols(&self) -> usize {
        self.cols
    }

    /// Récupère une référence vers l'élément à la ligne `r` et colonne `c`.
    #[inline]
    pub fn get(&self, r: usize, c: usize) -> Option<&T> {
        if r < self.rows && c < self.cols {
            Some(&self.data[r * self.cols + c])
        } else {
            None
        }
    }

    /// Récupère une référence mutable vers l'élément à la ligne `r` et colonne `c`.
    #[inline]
    pub fn get_mut(&mut self, r: usize, c: usize) -> Option<&mut T> {
        if r < self.rows && c < self.cols {
            Some(&mut self.data[r * self.cols + c])
        } else {
            None
        }
    }

    /// Échange deux lignes en place.
    pub fn swap_rows(&mut self, row_a: usize, row_b: usize) {
        if row_a == row_b || row_a >= self.rows || row_b >= self.rows {
            return;
        }
        for c in 0..self.cols {
            let idx_a = row_a * self.cols + c;
            let idx_b = row_b * self.cols + c;
            self.data.swap(idx_a, idx_b);
        }
    }
}

impl<T: Clone> Matrix<T> {
    /// Crée une matrice remplie d'une valeur par défaut.
    pub fn from_element(rows: usize, cols: usize, elem: T) -> Result<Self, MatrixError> {
        if rows == 0 || cols == 0 {
            return Err(MatrixError::EmptyMatrix);
        }
        Ok(Self {
            rows,
            cols,
            data: vec![elem; rows * cols],
        })
    }

    /// Calcule la transposée de la matrice.
    pub fn transpose(&self) -> Matrix<T> {
        let mut transposed_data = Vec::with_capacity(self.rows * self.cols);
        for c in 0..self.cols {
            for r in 0..self.rows {
                transposed_data.push(self[(r, c)].clone());
            }
        }
        Matrix {
            rows: self.cols,
            cols: self.rows,
            data: transposed_data,
        }
    }
}

impl<T> Index<(usize, usize)> for Matrix<T> {
    type Output = T;

    #[inline]
    fn index(&self, index: (usize, usize)) -> &Self::Output {
        let (r, c) = index;
        assert!(
            r < self.rows && c < self.cols,
            "Index hors limites : ({}, {}) pour matrice de taille ({}, {})",
            r,
            c,
            self.rows,
            self.cols
        );
        &self.data[r * self.cols + c]
    }
}

impl<T> IndexMut<(usize, usize)> for Matrix<T> {
    #[inline]
    fn index_mut(&mut self, index: (usize, usize)) -> &mut Self::Output {
        let (r, c) = index;
        assert!(
            r < self.rows && c < self.cols,
            "Index hors limites : ({}, {}) pour matrice de taille ({}, {})",
            r,
            c,
            self.rows,
            self.cols
        );
        &mut self.data[r * self.cols + c]
    }
}

impl<T> Matrix<T>
where
    T: Copy + Default + Add<Output = T> + Mul<Output = T> + AddAssign,
{
    /// Multiplie la matrice actuelle par une autre matrice B (A * B).
    pub fn multiply(&self, other: &Matrix<T>) -> Result<Matrix<T>, MatrixError> {
        if self.cols != other.rows {
            return Err(MatrixError::DimensionMismatchMultiply {
                rows_a: self.rows,
                cols_a: self.cols,
                rows_b: other.rows,
                cols_b: other.cols,
            });
        }

        let mut result_data = vec![T::default(); self.rows * other.cols];

        for i in 0..self.rows {
            for k in 0..self.cols {
                let a_ik = self[(i, k)];
                for j in 0..other.cols {
                    result_data[i * other.cols + j] += a_ik * other[(k, j)];
                }
            }
        }

        Ok(Matrix {
            rows: self.rows,
            cols: other.cols,
            data: result_data,
        })
    }
}

impl<T> Matrix<T>
where
    T: Float + FromPrimitive + Signed,
{
    /// Calcule le déterminant de la matrice carrée via élimination gaussienne avec pivot partiel.
    pub fn determinant(&self) -> Result<T, MatrixError> {
        if self.rows != self.cols {
            return Err(MatrixError::NotSquare {
                rows: self.rows,
                cols: self.cols,
            });
        }

        let n = self.rows;
        let mut a = self.clone();
        let mut det = T::one();
        let mut sign = T::one();

        for i in 0..n {
            // Recherche du pivot partiel
            let mut max_row = i;
            let mut max_val = a[(i, i)].abs();

            for k in (i + 1)..n {
                let val = a[(k, i)].abs();
                if val > max_val {
                    max_val = val;
                    max_row = k;
                }
            }

            // Si le pivot est nul (ou infinitésimalement proche), le déterminant est 0
            if max_val <= T::epsilon() * T::from_f64(10.0).unwrap_or(T::one()) {
                return Ok(T::zero());
            }

            // Échange de lignes si nécessaire
            if max_row != i {
                a.swap_rows(i, max_row);
                sign = -sign;
            }

            let pivot = a[(i, i)];
            det = det * pivot;

            // Élimination des lignes sous le pivot
            for k in (i + 1)..n {
                let factor = a[(k, i)] / pivot;
                for j in (i + 1)..n {
                    let sub = factor * a[(i, j)];
                    a[(k, j)] = a[(k, j)] - sub;
                }
            }
        }

        Ok(det * sign)
    }
}

