/// Parsing d'une chaîne en matrice. Format supporté : "1,2,3;4,5,6" ou "1 2 3; 4 5 6".
impl<T> FromStr for Matrix<T>
where
    T: FromStr,
    T::Err: fmt::Display,
{
    type Err = MatrixError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let trimmed = s.trim();
        if trimmed.is_empty() {
            return Err(MatrixError::EmptyMatrix);
        }

        let row_chunks: Vec<&str> = trimmed
            .split(';')
            .map(|r| r.trim())
            .filter(|r| !r.is_empty())
            .collect();

        if row_chunks.is_empty() {
            return Err(MatrixError::EmptyMatrix);
        }

        let mut data = Vec::new();
        let mut expected_cols = None;

        for (row_idx, row_str) in row_chunks.iter().enumerate() {
            let elements: Vec<&str> = row_str
                .split(|c: char| c == ',' || c.is_whitespace())
                .map(|token| token.trim())
                .filter(|token| !token.is_empty())
                .collect();

            if elements.is_empty() {
                return Err(MatrixError::ParseError(format!(
                    "La ligne {} est vide.",
                    row_idx + 1
                )));
            }

            match expected_cols {
                None => expected_cols = Some(elements.len()),
                Some(cols) if cols != elements.len() => {
                    return Err(MatrixError::ParseError(format!(
                        "Incohérence du nombre de colonnes : attendu {} mais ligne {} a {} éléments.",
                        cols,
                        row_idx + 1,
                        elements.len()
                    )));
                }
                _ => {}
            }

            for token in elements {
                let val = token.parse::<T>().map_err(|e| {
                    MatrixError::ParseError(format!(
                        "Impossible de convertir '{}' : {}",
                        token, e
                    ))
                })?;
                data.push(val);
            }
        }

        let cols = expected_cols.unwrap_or(0);
        let rows = row_chunks.len();

        Matrix::new(rows, cols, data)
    }
}

