        let t = m.transpose();
        assert_eq!(t.rows(), 3);
        assert_eq!(t.cols(), 2);
        assert_eq!(t[(0, 0)], 1);
        assert_eq!(t[(0, 1)], 4);
        assert_eq!(t[(1, 0)], 2);
        assert_eq!(t[(1, 1)], 5);
        assert_eq!(t[(2, 0)], 3);
        assert_eq!(t[(2, 1)], 6);
    }

    #[test]
    fn test_multiply() {
        // A (2x3) * B (3x2) = C (2x2)
        let a = Matrix::new(2, 3, vec![1, 2, 3, 4, 5, 6]).expect("A valide");
        let b = Matrix::new(3, 2, vec![7, 8, 9, 1, 2, 3]).expect("B valide");
        let c = a.multiply(&b).expect("Multiplication valide");

        assert_eq!(c.rows(), 2);
        assert_eq!(c.cols(), 2);
        // (1*7 + 2*9 + 3*2) = 7 + 18 + 6 = 31
        // (1*8 + 2*1 + 3*3) = 8 + 2 + 9 = 19
        // (4*7 + 5*9 + 6*2) = 28 + 45 + 12 = 85
        // (4*8 + 5*1 + 6*3) = 32 + 5 + 18 = 55
        assert_eq!(c[(0, 0)], 31);
        assert_eq!(c[(0, 1)], 19);
        assert_eq!(c[(1, 0)], 85);
        assert_eq!(c[(1, 1)], 55);
    }

    #[test]
    fn test_multiply_incompatible_dimensions() {
        let a = Matrix::new(2, 2, vec![1, 2, 3, 4]).unwrap();
        let b = Matrix::new(3, 2, vec![1, 2, 3, 4, 5, 6]).unwrap();
        let err = a.multiply(&b).unwrap_err();
        match err {
            MatrixError::DimensionMismatchMultiply { rows_a, cols_a, rows_b, cols_b } => {
                assert_eq!((rows_a, cols_a, rows_b, cols_b), (2, 2, 3, 2));
            }
            _ => panic!("Type d'erreur inattendu"),
        }
    }

