    fn test_determinant_2x2() {
        let m = Matrix::new(2, 2, vec![4.0, 7.0, 2.0, 6.0]).unwrap();
        // det = 4*6 - 7*2 = 24 - 14 = 10
        let det = m.determinant().unwrap();
        assert!((det - 10.0).abs() < 1e-9);
    }

    #[test]
    fn test_determinant_3x3() {
        let m = Matrix::new(
