        )
        .unwrap();
        // det = 1*(0 - 24) - 2*(0 - 20) + 3*(0 - 5) = -24 + 40 - 15 = 1
        let det = m.determinant().unwrap();
        assert!((det - 1.0).abs() < 1e-9);
    }

