```rust
// src/main.rs
use std::cmp::Ordering;
use std::collections::BinaryHeap;
use std::thread;
use std::time::{Duration, Instant};

/// Identifiant unique pour une tâche planifiée.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct TaskId(pub usize);

/// Représentation d'une tâche à exécuter.
struct ScheduledTask {
    id: TaskId,
    name: String,
    scheduled_at: Instant,
    period: Option<Duration>,
    action: Box<dyn FnMut()>,
}

impl PartialEq for ScheduledTask {
    fn eq(&self, other: &Self) -> bool {
        self.scheduled_at == other.scheduled_at && self.id == other.id
    }
}

impl Eq for ScheduledTask {}

// Tri inverse par date d'exécution afin que BinaryHeap agisse comme un Min-Heap (la plus proche échéance au sommet).
impl PartialOrd for ScheduledTask {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for ScheduledTask {
    fn cmp(&self, other: &Self) -> Ordering {
        // Inverse la comparaison pour obtenir l'échéance la plus proche en premier
        other
            .scheduled_at
            .cmp(&self.scheduled_at)
            .then_with(|| other.id.cmp(&self.id))
    }
}

/// Ordonnanceur synchrone basé sur une file de priorité et `std::thread::sleep`.
pub struct SyncScheduler {
    tasks: BinaryHeap<ScheduledTask>,
    next_id: usize,
}

impl SyncScheduler {
    /// Crée une nouvelle instance de l'ordonnanceur vide.
    pub fn new() -> Self {
        Self {
            tasks: BinaryHeap::new(),
            next_id: 1,
        }
    }

    /// Planifie une tâche ponctuelle à exécuter après un délai donné.
    pub fn schedule_once<F>(&mut self, name: impl Into<String>, delay: Duration, action: F) -> TaskId
    where
        F: FnMut() + 'static,
    {
        let id = TaskId(self.next_id);
        self.next_id += 1;
        self.tasks.push(ScheduledTask {
            id,
            name: name.into(),
            scheduled_at: Instant::now() + delay,
            period: None,
            action: Box::new(action),
        });
        id
    }

    /// Planifie une tâche récurrente avec un délai initial et un intervalle périodique.
    pub fn schedule_recurring<F>(
        &mut self,
        name: impl Into<String>,
        initial_delay: Duration,
        interval: Duration,
        action: F,
    ) -> TaskId
    where
        F: FnMut() + 'static,
    {
        let id = TaskId(self.next_id);
        self.next_id += 1;
        self.tasks.push(ScheduledTask {
            id,
            name: name.into(),
            scheduled_at: Instant::now() + initial_delay,
            period: Some(interval),
            action: Box::new(action),
        });
        id
    }

    /// Exécute les tâches jusqu'à ce que la file soit vide ou qu'une durée maximale soit atteinte.
    pub fn run_for(&mut self, max_duration: Duration) {
        let start_time = Instant::now();

        while let Some(task) = self.tasks.pop() {
            let now = Instant::now();

            // Vérification de la limite de temps globale
            if now.duration_since(start_time) >= max_duration {
                // Remettre la tâche pour ne pas la perdre
                self.tasks.push(task);
                println!("[SCHEDULER] Durée d'exécution maximale atteinte ({:?}). Arrêt.", max_duration);
                break;
            }

            // Attente jusqu'à l'heure d'exécution prévue
            if task.scheduled_at > now {
                let wait_duration = task.scheduled_at - now;
                let remaining = max_duration.saturating_sub(now.duration_since(start_time));
                let sleep_duration = wait_duration.min(remaining);

                if sleep_duration > Duration::ZERO {
                    thread::sleep(sleep_duration);
                }

                // Si l'attente a atteint la limite de temps globale
                if Instant::now().duration_since(start_time) >= max_duration {
                    self.tasks.push(task);
                    println!("[SCHEDULER] Durée d'exécution maximale atteinte pendant l'attente. Arrêt.");
                    break;
                }
            }

            // Exécution de la tâche
            let mut current_task = task;
            println!(
                "[{:>6}ms] Exécution de : '{}' (ID: {:?})",
                Instant::now().duration_since(start_time).as_millis(),
                current_task.name,
                current_task.id
            );
            (current_task.action)();

            // Re-planification pour les tâches périodiques (compensation de la dérive)
            if let Some(period) = current_task.period {
                let mut next_scheduled = current_task.scheduled_at + period;
                let current_time = Instant::now();

                // Si la tâche a pris plus de temps que l'intervalle, avance à la prochaine échéance future
                while next_scheduled <= current_time {
                    next_scheduled += period;
                }

                current_task.scheduled_at = next_scheduled;
                self.tasks.push(current_task);
            }
        }
    }
}

impl Default for SyncScheduler {
    fn default() -> Self {
        Self::new()
    }
}

fn main() {
    println!("Démarrage de l'ordonnanceur synchrone...");

    let mut scheduler = SyncScheduler::new();

    // 1. Tâche périodique rapide (toutes les 200ms)
    let mut tick_count = 0usize;
    scheduler.schedule_recurring("Tick rapide", Duration::from_millis(100), Duration::from_millis(200), move || {
        tick_count += 1;
        println!("  -> [Tick rapide] Coucou #{tick_count}");
    });

    // 2. Tâche périodique moyenne (toutes les 500ms)
    let mut heart_beat = 0usize;
    scheduler.schedule_recurring("Heartbeat", Duration::from_millis(250), Duration::from_millis(500), move || {
        heart_beat += 1;
        println!("  -> [Heartbeat] Battement de coeur #{heart_beat}");
    });

    // 3. Tâche unique différée (à 600ms)
    scheduler.schedule_once("Alerte One-Shot", Duration::from_millis(600), || {
        println!("  -> [Alerte One-Shot] Exécution unique déclenchée !");
    });

    // 4. Exécution de la boucle synchrone pendant 1,6 seconde
    scheduler.run_for(Duration::from_millis(1600));

    println!("Fin normale du programme.");
}

