        Ok(())
    }

    #[test]
    fn test_relative_paths_and_navigation() -> VfsResult<()> {
        let mut fs = Vfs::new();
        fs.mkdir_p("/a/b/c")?;
        fs.change_dir("/a/b")?;

        fs.write_file("file.txt", b"test")?;
        assert_eq!(fs.read_to_string("/a/b/file.txt")?, "test");

        fs.change_dir("../..")?;
        assert_eq!(fs.cwd().to_string(), "/");

        Ok(())
    }

    #[test]
    fn test_directory_errors() -> VfsResult<()> {
        let mut fs = Vfs::new();
        fs.mkdir("/test")?;
        fs.write_file("/test/file.txt", b"data")?;

        // Cannot remove non-empty dir
        let err = fs.remove_dir("/test");
        assert!(matches!(err, Err(VfsError::DirectoryNotEmpty(_))));

        // Cannot treat file as dir
        let err = fs.mkdir("/test/file.txt/sub");
        assert!(matches!(err, Err(VfsError::NotADirectory(_))));

        Ok(())
    }

