    fn test_append_file() -> VfsResult<()> {
        let mut fs = Vfs::new();
        fs.write_file("/log.txt", b"Line 1\n")?;
        fs.append_file("/log.txt", b"Line 2\n")?;

        let res = fs.read_to_string("/log.txt")?;
        assert_eq!(res, "Line 1\nLine 2\n");
