```rust
// src/main.rs
//! Système de fichiers virtuel en mémoire (MemVFS)
//! Arborescence récursive, typage fort, gestion d'erreurs exhaustive.

use chrono::{DateTime, Utc};
use std::collections::BTreeMap;
use std::fmt;
use std::str::FromStr;
use thiserror::Error;

/// Erreurs possibles lors des opérations sur le VFS.
#[derive(Debug, Error, PartialEq, Eq)]
pub enum VfsError {
    #[error("Chemin introuvable: {0}")]
    NotFound(String),

    #[error("L'élément existe déjà: {0}")]
    AlreadyExists(String),

    #[error("L'élément n'est pas un répertoire: {0}")]
    NotADirectory(String),

    #[error("L'élément est un répertoire: {0}")]
    IsADirectory(String),

    #[error("Le répertoire n'est pas vide: {0}")]
    DirectoryNotEmpty(String),

    #[error("Chemin invalide: {0}")]
    InvalidPath(String),

    #[error("Données non UTF-8 valides: {0}")]
    InvalidUtf8(String),
}

/// Résultat standard pour les opérations VFS.
pub type VfsResult<T> = Result<T, VfsError>;

/// Chemin absolu normalisé dans le VFS.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct VfsPath {
    segments: Vec<String>,
}

impl VfsPath {
    /// Chemin racine `/`
    pub fn root() -> Self {
        Self {
            segments: Vec::new(),
        }
    }

    /// Résout un chemin (relatif ou absolu) par rapport au répertoire de travail actuel (`cwd`).
    pub fn resolve(cwd: &VfsPath, path_str: &str) -> VfsResult<Self> {
        let is_absolute = path_str.starts_with('/');
        let mut segments = if is_absolute {
            Vec::new()
        } else {
            cwd.segments.clone()
        };

        for part in path_str.split('/') {
            match part {
                "" | "." => {
                    // Ignorer les segments vides ou le dossier courant
                }
                ".." => {
                    segments.pop();
                }
                segment => {
                    if segment.contains('\0') {
                        return Err(VfsError::InvalidPath("Caractère nul interdit".into()));
                    }
                    segments.push(segment.to_string());
                }
            }
        }

        Ok(Self { segments })
    }

    /// Segments constituant le chemin.
    pub fn segments(&self) -> &[String] {
        &self.segments
    }

    /// Nom de l'entrée finale (fichier ou dossier), ou None si racine.
    pub fn file_name(&self) -> Option<&str> {
        self.segments.last().map(|s| s.as_str())
    }

    /// Renvoie le chemin parent, s'il existe.
    pub fn parent(&self) -> Option<Self> {
        if self.segments.is_empty() {
            None
        } else {
            let mut parent_segments = self.segments.clone();
            parent_segments.pop();
            Some(Self {
                segments: parent_segments,
            })
        }
    }
}

impl fmt::Display for VfsPath {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.segments.is_empty() {
            write!(f, "/")
        } else {
            for segment in &self.segments {
                write!(f, "/{}", segment)?;
            }
            Ok(())
        }
    }
}

impl FromStr for VfsPath {
    type Err = VfsError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        Self::resolve(&Self::root(), s)
    }
}

/// Métadonnées d'un nœud du VFS.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Metadata {
    pub is_dir: bool,
    pub size: usize,
    pub created_at: DateTime<Utc>,
    pub modified_at: DateTime<Utc>,
}

/// Fichier standard stocké en mémoire.
#[derive(Debug, Clone)]
pub struct RegularFile {
    pub content: Vec<u8>,
    pub created_at: DateTime<Utc>,
    pub modified_at: DateTime<Utc>,
}

impl RegularFile {
    pub fn new(content: Vec<u8>) -> Self {
        let now = Utc::now();
        Self {
            content,
            created_at: now,
            modified_at: now,
        }
    }

    pub fn update_content(&mut self, content: Vec<u8>) {
        self.content = content;
        self.modified_at = Utc::now();
    }

    pub fn append_content(&mut self, data: &[u8]) {
        self.content.extend_from_slice(data);
        self.modified_at = Utc::now();
    }

    pub fn metadata(&self) -> Metadata {
        Metadata {
            is_dir: false,
            size: self.content.len(),
            created_at: self.created_at,
            modified_at: self.modified_at,
        }
    }
}

/// Répertoire pouvant contenir d'autres nœuds.
#[derive(Debug, Clone)]
pub struct Directory {
    pub entries: BTreeMap<String, VNode>,
    pub created_at: DateTime<Utc>,
    pub modified_at: DateTime<Utc>,
}

impl Directory {
    pub fn new() -> Self {
        let now = Utc::now();
        Self {
            entries: BTreeMap::new(),
            created_at: now,
            modified_at: now,
        }
    }

    pub fn metadata(&self) -> Metadata {
        Metadata {
            is_dir: true,
            size: self.entries.len(),
            created_at: self.created_at,
            modified_at: self.modified_at,
        }
    }

    pub fn touch_modified(&mut self) {
        self.modified_at = Utc::now();
    }
}

impl Default for Directory {
    fn default() -> Self {
        Self::new()
    }
}

/// Nœud de l'arbre VFS.
#[derive(Debug, Clone)]
pub enum VNode {
    File(RegularFile),
    Dir(Directory),
}

impl VNode {
    pub fn is_dir(&self) -> bool {
        matches!(self, VNode::Dir(_))
    }

    pub fn is_file(&self) -> bool {
        matches!(self, VNode::File(_))
    }

    pub fn as_dir(&self) -> Option<&Directory> {
        match self {
            VNode::Dir(d) => Some(d),
            _ => None,
        }
    }

    pub fn as_dir_mut(&mut self) -> Option<&mut Directory> {
        match self {
            VNode::Dir(d) => Some(d),
            _ => None,
        }
    }

    pub fn as_file(&self) -> Option<&RegularFile> {
        match self {
            VNode::File(f) => Some(f),
            _ => None,
        }
    }

    pub fn as_file_mut(&mut self) -> Option<&mut RegularFile> {
        match self {
            VNode::File(f) => Some(f),
            _ => None,
        }
    }

    pub fn metadata(&self) -> Metadata {
        match self {
            VNode::File(f) => f.metadata(),
            VNode::Dir(d) => d.metadata(),
        }
    }
}

/// Système de fichiers virtuel principal.
#[derive(Debug, Clone)]
pub struct Vfs {
    root: Directory,
    cwd: VfsPath,
}

impl Default for Vfs {
    fn default() -> Self {
        Self::new()
    }
}

impl Vfs {
    /// Crée un nouveau VFS avec une racine vide et `cwd = /`.
    pub fn new() -> Self {
        Self {
            root: Directory::new(),
            cwd: VfsPath::root(),
        }
    }

    /// Récupère le répertoire de travail actuel.
    pub fn cwd(&self) -> &VfsPath {
        &self.cwd
    }

    /// Change de répertoire courant (`cd`).
    pub fn change_dir(&mut self, path: &str) -> VfsResult<()> {
        let target_path = self.resolve_path(path)?;
        if target_path.segments().is_empty() {
            self.cwd = target_path;
            return Ok(());
        }
        let node = self.get_node(&target_path)?;
        if !node.is_dir() {
            return Err(VfsError::NotADirectory(target_path.to_string()));
        }
        self.cwd = target_path;
        Ok(())
    }

    /// Résout un chemin relatif ou absolu selon le répertoire courant.
    pub fn resolve_path(&self, path: &str) -> VfsResult<VfsPath> {
        VfsPath::resolve(&self.cwd, path)
    }

    /// Récupère une référence immuable vers un nœud.
    pub fn get_node(&self, path: &VfsPath) -> VfsResult<&VNode> {
        if path.segments().is_empty() {
            // Emprunt virtuel du root sous forme de nœud
            // On utilise une méthode interne dédiée
            return Err(VfsError::InvalidPath(
                "Impossible d'accéder au root en tant que VNode direct".into(),
            ));
        }

        let mut current_dir = &self.root;
        let segments = path.segments();
        let (parents, target) = segments.split_at(segments.len() - 1);

        for segment in parents {
            match current_dir.entries.get(segment) {
                Some(VNode::Dir(dir)) => current_dir = dir,
                Some(VNode::File(_)) => {
                    return Err(VfsError::NotADirectory(segment.clone()));
                }
                None => return Err(VfsError::NotFound(segment.clone())),
            }
        }

        let target_name = &target[0];
        current_dir
            .entries
            .get(target_name)
            .ok_or_else(|| VfsError::NotFound(path.to_string()))
    }

    /// Récupère une référence mutable vers un nœud.
    pub fn get_node_mut(&mut self, path: &VfsPath) -> VfsResult<&mut VNode> {
        if path.segments().is_empty() {
            return Err(VfsError::InvalidPath("Racine non accessible via get_node_mut".into()));
        }

        let mut current_dir = &mut self.root;
        let segments = path.segments();
        let (parents, target) = segments.split_at(segments.len() - 1);

        for segment in parents {
            match current_dir.entries.get_mut(segment) {
                Some(VNode::Dir(dir)) => current_dir = dir,
                Some(VNode::File(_)) => {
                    return Err(VfsError::NotADirectory(segment.clone()));
                }
                None => return Err(VfsError::NotFound(segment.clone())),
            }
        }

        let target_name = &target[0];
        current_dir
            .entries
            .get_mut(target_name)
            .ok_or_else(|| VfsError::NotFound(path.to_string()))
    }

    /// Récupère une référence mutable au dossier parent spécifié par le chemin.
    fn get_dir_mut(&mut self, segments: &[String]) -> VfsResult<&mut Directory> {
        let mut current = &mut self.root;
        for seg in segments {
            match current.entries.get_mut(seg) {
                Some(VNode::Dir(d)) => current = d,
                Some(VNode::File(_)) => return Err(VfsError::NotADirectory(seg.clone())),
                None => return Err(VfsError::NotFound(seg.clone())),
            }
        }
        Ok(current)
    }

    /// Récupère une référence immuable au dossier spécifié par les segments.
    fn get_dir(&self, segments: &[String]) -> VfsResult<&Directory> {
        let mut current = &self.root;
        for seg in segments {
            match current.entries.get(seg) {
                Some(VNode::Dir(d)) => current = d,
                Some(VNode::File(_)) => return Err(VfsError::NotADirectory(seg.clone())),
                None => return Err(VfsError::NotFound(seg.clone())),
            }
        }
        Ok(current)
    }

    /// Crée un répertoire simple (`mkdir`).
    pub fn mkdir(&mut self, path: &str) -> VfsResult<()> {
        let target = self.resolve_path(path)?;
        if target.segments().is_empty() {
            return Err(VfsError::AlreadyExists("/".into()));
        }

        let file_name = target.file_name().unwrap_or_default().to_string();
        let parent_segments = &target.segments()[..target.segments().len() - 1];

        let parent_dir = self.get_dir_mut(parent_segments)?;
        if parent_dir.entries.contains_key(&file_name) {
            return Err(VfsError::AlreadyExists(target.to_string()));
        }

        parent_dir
            .entries
            .insert(file_name, VNode::Dir(Directory::new()));
        parent_dir.touch_modified();
        Ok(())
    }

    /// Crée un répertoire et tous ses parents intermédiaires manquants (`mkdir -p`).
    pub fn mkdir_p(&mut self, path: &str) -> VfsResult<()> {
        let target = self.resolve_path(path)?;
        let mut current = &mut self.root;

        for seg in target.segments() {
            if !current.entries.contains_key(seg) {
                current
                    .entries
                    .insert(seg.clone(), VNode::Dir(Directory::new()));
                current.touch_modified();
            }

            match current.entries.get_mut(seg) {
                Some(VNode::Dir(next_dir)) => {
                    current = next_dir;
                }
                Some(VNode::File(_)) => {
                    return Err(VfsError::NotADirectory(seg.clone()));
                }
                None => unreachable!(),
            }
        }
        Ok(())
    }

    /// Écrit ou remplace un fichier avec le contenu fourni.
    pub fn write_file(&mut self, path: &str, content: &[u8]) -> VfsResult<()> {
        let target = self.resolve_path(path)?;
        if target.segments().is_empty() {
            return Err(VfsError::IsADirectory("/".into()));
        }

        let file_name = target.file_name().unwrap_or_default().to_string();
        let parent_segments = &target.segments()[..target.segments().len() - 1];

        let parent_dir = self.get_dir_mut(parent_segments)?;

        if let Some(existing) = parent_dir.entries.get_mut(&file_name) {
            match existing {
                VNode::File(f) => {
                    f.update_content(content.to_vec());
                    parent_dir.touch_modified();
                    return Ok(());
                }
                VNode::Dir(_) => {
                    return Err(VfsError::IsADirectory(target.to_string()));
                }
            }
        }

        parent_dir
            .entries
            .insert(file_name, VNode::File(RegularFile::new(content.to_vec())));
        parent_dir.touch_modified();
        Ok(())
    }

    /// Concatène des données à la fin d'un fichier existant ou le crée.
    pub fn append_file(&mut self, path: &str, content: &[u8]) -> VfsResult<()> {
        let target = self.resolve_path(path)?;
        if target.segments().is_empty() {
            return Err(VfsError::IsADirectory("/".into()));
        }

        let file_name = target.file_name().unwrap_or_default().to_string();
        let parent_segments = &target.segments()[..target.segments().len() - 1];

        let parent_dir = self.get_dir_mut(parent_segments)?;

        if let Some(existing) = parent_dir.entries.get_mut(&file_name) {
            match existing {
                VNode::File(f) => {
                    f.append_content(content);
                    parent_dir.touch_modified();
                    return Ok(());
                }
                VNode::Dir(_) => {
                    return Err(VfsError::IsADirectory(target.to_string()));
                }
            }
        }

        parent_dir
            .entries
            .insert(file_name, VNode::File(RegularFile::new(content.to_vec())));
        parent_dir.touch_modified();
        Ok(())
    }

    /// Lit le contenu brut d'un fichier.
    pub fn read_file(&self, path: &str) -> VfsResult<Vec<u8>> {
        let target = self.resolve_path(path)?;
        if target.segments().is_empty() {
            return Err(VfsError::IsADirectory("/".into()));
        }

        let node = self.get_node(&target)?;
        match node {
            VNode::File(f) => Ok(f.content.clone()),
            VNode::Dir(_) => Err(VfsError::IsADirectory(target.to_string())),
        }
    }

    /// Lit le contenu d'un fichier décodé en UTF-8.
    pub fn read_to_string(&self, path: &str) -> VfsResult<String> {
        let bytes = self.read_file(path)?;
        String::from_utf8(bytes).map_err(|e| VfsError::InvalidUtf8(e.to_string()))
    }

    /// Liste les entrées d'un dossier avec leur nom et leurs métadonnées.
    pub fn read_dir(&self, path: &str) -> VfsResult<Vec<(String, Metadata)>> {
        let target = self.resolve_path(path)?;
        let dir = self.get_dir(target.segments())?;

        let list = dir
            .entries
            .iter()
            .map(|(name, node)| (name.clone(), node.metadata()))
            .collect();
        Ok(list)
    }

    /// Récupère les métadonnées d'un nœud (fichier ou répertoire).
    pub fn metadata(&self, path: &str) -> VfsResult<Metadata> {
        let target = self.resolve_path(path)?;
        if target.segments().is_empty() {
            return Ok(self.root.metadata());
        }

        let node = self.get_node(&target)?;
        Ok(node.metadata())
    }

    /// Supprime un fichier.
    pub fn remove_file(&mut self, path: &str) -> VfsResult<()> {
        let target = self.resolve_path(path)?;
        if target.segments().is_empty() {
            return Err(VfsError::IsADirectory("/".into()));
        }

        let file_name = target.file_name().unwrap_or_default().to_string();
        let parent_segments = &target.segments()[..target.segments().len() - 1];

        let parent_dir = self.get_dir_mut(parent_segments)?;
        match parent_dir.entries.get(&file_name) {
            Some(VNode::File(_)) => {
                parent_dir.entries.remove(&file_name);
                parent_dir.touch_modified();
                Ok(())
            }
            Some(VNode::Dir(_)) => Err(VfsError::IsADirectory(target.to_string())),
            None => Err(VfsError::NotFound(target.to_string())),
        }
    }

    /// Supprime un répertoire vide.
    pub fn remove_dir(&mut self, path: &str) -> VfsResult<()> {
        let target = self.resolve_path(path)?;
        if target.segments().is_empty() {
            return Err(VfsError::InvalidPath(
                "Impossible de supprimer le répertoire racine".into(),
            ));
        }

        let file_name = target.file_name().unwrap_or_default().to_string();
        let parent_segments = &target.segments()[..target.segments().len() - 1];

        let parent_dir = self.get_dir_mut(parent_segments)?;
        match parent_dir.entries.get(&file_name) {
            Some(VNode::Dir(dir)) => {
                if !dir.entries.is_empty() {
                    return Err(VfsError::DirectoryNotEmpty(target.to_string()));
                }
                parent_dir.entries.remove(&file_name);
                parent_dir.touch_modified();
                Ok(())
            }
            Some(VNode::File(_)) => Err(VfsError::NotADirectory(target.to_string())),
            None => Err(VfsError::NotFound(target.to_string())),
        }
    }

    /// Supprime un répertoire et tout son contenu récursivement (`rm -rf`).
    pub fn remove_dir_all(&mut self, path: &str) -> VfsResult<()> {
        let target = self.resolve_path(path)?;
        if target.segments().is_empty() {
            return Err(VfsError::InvalidPath(
                "Impossible de supprimer le répertoire racine".into(),
            ));
        }

        let file_name = target.file_name().unwrap_or_default().to_string();
        let parent_segments = &target.segments()[..target.segments().len() - 1];

        let parent_dir = self.get_dir_mut(parent_segments)?;
        match parent_dir.entries.get(&file_name) {
            Some(VNode::Dir(_)) => {
                parent_dir.entries.remove(&file_name);
                parent_dir.touch_modified();
                Ok(())
            }
            Some(VNode::File(_)) => Err(VfsError::NotADirectory(target.to_string())),
            None => Err(VfsError::NotFound(target.to_string())),
        }
    }

    /// Affiche une arborescence textuelle (style commande `tree`).
    pub fn print_tree(&self, path: &str) -> VfsResult<String> {
        let target = self.resolve_path(path)?;
        let mut output = String::new();

        if target.segments().is_empty() {
            output.push_str("/\n");
            self.format_tree_recursive(&self.root, "", &mut output);
        } else {
            let node = self.get_node(&target)?;
            match node {
                VNode::Dir(dir) => {
                    let display_name = target.file_name().unwrap_or("/");
                    output.push_str(&format!("{}/\n", display_name));
                    self.format_tree_recursive(dir, "", &mut output);
                }
                VNode::File(f) => {
                    let display_name = target.file_name().unwrap_or("/");
                    output.push_str(&format!("{} ({} octets)\n", display_name, f.content.len()));
                }
            }
        }

        Ok(output)
    }

    fn format_tree_recursive(&self, dir: &Directory, prefix: &str, out: &mut String) {
        let total = dir.entries.len();
        for (i, (name, child)) in dir.entries.iter().enumerate() {
            let is_last = i == total - 1;
            let branch = if is_last { "└── " } else { "├── " };
            let next_prefix = if is_last {
                format!("{}    ", prefix)
            } else {
                format!("{}│   ", prefix)
            };

            match child {
                VNode::Dir(d) => {
                    out.push_str(&format!("{}{}{}/\n", prefix, branch, name));
                    self.format_tree_recursive(d, &next_prefix, out);
                }
                VNode::File(f) => {
                    out.push_str(&format!(
                        "{}{}{} ({} o)\n",
                        prefix,
                        branch,
                        name,
                        f.content.len()
                    ));
                }
            }
        }
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("=== Initialisation du Système de Fichiers Virtuel (MemVFS) ===\n");

    let mut fs = Vfs::new();

    // 1. Création de dossiers récursifs
    println!("> Création de l'arborescence /etc, /var/log, /home/user/docs...");
    fs.mkdir_p("/etc")?;
    fs.mkdir_p("/var/log")?;
    fs.mkdir_p("/home/user/docs")?;

    // 2. Écriture de fichiers
    println!("> Écriture de fichiers dans le VFS...");
    fs.write_file(
        "/etc/config.json",
        br#"{"app_name": "MemVFS", "version": "1.0"}"#,
    )?;
    fs.write_file(
        "/home/user/docs/notes.txt",
        b"Premiere note dans le systeme virtuel.",
    )?;
    fs.write_file("/var/log/system.log", b"[INFO] Demarrage du noyau virtuel.\n")?;

    // 3. Concaténation (append)
    println!("> Ajout d'une ligne de log...");
    fs.append_file(
        "/var/log/system.log",
        b"[INFO] Verification des modules effectuee avec succes.\n",
    )?;

    // 4. Navigation relative et cd
    println!("> Navigation vers /home/user...");
    fs.change_dir("/home/user")?;
    println!("  CWD actuel : {}", fs.cwd());

    // Création via chemin relatif
    fs.write_file("profile.md", b"# Profil utilisateur\nStatut: Actif")?;
    println!("> Fichier 'profile.md' cree via chemin relatif.");

    // Remontée via `..`
    fs.change_dir("../..")?;
    println!("  CWD apres 'cd ../..' : {}", fs.cwd());

    // 5. Lecture de contenu
    println!("\n> Lecture de /var/log/system.log :");
    let log_content = fs.read_to_string("/var/log/system.log")?;
    for line in log_content.lines() {
        println!("  | {}", line);
    }

    // 6. Listage de dossier
    println!("\n> Contenu de /home/user (read_dir) :");
    let entries = fs.read_dir("/home/user")?;
    for (name, meta) in entries {
        let type_str = if meta.is_dir { "DIR " } else { "FILE" };
        println!(
            "  [{}] {:<12} taille: {:<4} octets | modifie: {}",
            type_str,
            name,
            meta.size,
            meta.modified_at.format("%Y-%m-%d %H:%M:%S")
        );
    }

    // 7. Affichage arborescence complète
    println!("\n> Arborescence complète du VFS :");
    let tree_view = fs.print_tree("/")?;
    print!("{}", tree_view);

    // 8. Gestion des suppressions et contrôles d'erreurs
    println!("> Test suppression fichier /etc/config.json...");
    fs.remove_file("/etc/config.json")?;
    println!("  Fichier supprime.");

    println!("> Tentative de suppression d'un dossier non vide (/var)...");
    match fs.remove_dir("/var") {
        Ok(_) => println!("  Succès inattendu!"),
        Err(e) => println!("  Erreur interceptee avec succes: {}", e),
    }

    println!("> Suppression récursive de /var (remove_dir_all)...");
    fs.remove_dir_all("/var")?;
    println!("  /var supprime avec succes.");

    // Arborescence finale
    println!("\n> Arborescence après suppressions :");
    print!("{}", fs.print_tree("/")?);

    println!("=== Fin de la démonstration avec succès ===");
    Ok(())
}

