        fs.mkdir_p("/nested/folder/tree")?;
        fs.write_file("/nested/folder/tree/leaf.txt", b"leaf")?;

        fs.remove_dir_all("/nested")?;
        assert!(matches!(fs.get_node(&VfsPath::resolve(&VfsPath::root(), "/nested")?), Err(VfsError::NotFound(_))));
        Ok(())
    }
