/// Représente les compteurs de temps CPU d'un cœur ou du CPU global.
#[derive(Debug, Clone, Copy, Default)]
#[allow(dead_code)]
struct CpuTimes {
    user: u64,
    nice: u64,
    system: u64,
    idle: u64,
    iowait: u64,
    irq: u64,
    softirq: u64,
    steal: u64,
    guest: u64,
    guest_nice: u64,
}

impl CpuTimes {
    /// Temps passé en état d'inactivité (idle + iowait).
    fn idle_total(&self) -> u64 {
        self.idle.saturating_add(self.iowait)
    }

    /// Temps passé en travail effectif (hors idle/iowait).
    fn active_total(&self) -> u64 {
        self.user
            .saturating_add(self.nice)
            .saturating_add(self.system)
            .saturating_add(self.irq)
            .saturating_add(self.softirq)
            .saturating_add(self.steal)
    }

    /// Temps total cumulé.
    fn total(&self) -> u64 {
        self.idle_total().saturating_add(self.active_total())
    }

    /// Calcule le pourcentage d'utilisation entre deux mesures instantanées.
    fn calculate_usage(previous: &Self, current: &Self) -> f64 {
        let prev_total = previous.total();
        let curr_total = current.total();

        let delta_total = curr_total.saturating_sub(prev_total);
        if delta_total == 0 {
            return 0.0;
        }

        let prev_idle = previous.idle_total();
        let curr_idle = current.idle_total();
        let delta_idle = curr_idle.saturating_sub(prev_idle);

        let delta_active = delta_total.saturating_sub(delta_idle);
        (delta_active as f64 / delta_total as f64) * 100.0
    }
}

