```rust
// src/main.rs
use std::env;
use std::fmt;
use std::io::{self, Write};
use std::path::PathBuf;
use std::process::{Command, Stdio};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

#[derive(Debug)]
enum ShellError {
    Io(io::Error),
    Parse(shell_words::ParseError),
    DirectoryNotFound(PathBuf),
    HomeNotSet,
}

impl fmt::Display for ShellError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ShellError::Io(err) => write!(f, "Erreur E/S: {}", err),
            ShellError::Parse(err) => write!(f, "Erreur de syntaxe: {}", err),
            ShellError::DirectoryNotFound(p) => {
                write!(f, "Répertoire introuvable: {}", p.display())
            }
            ShellError::HomeNotSet => write!(f, "Variable d'environnement HOME non définie"),
        }
    }
}

impl std::error::Error for ShellError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            ShellError::Io(err) => Some(err),
            ShellError::Parse(err) => Some(err),
            ShellError::DirectoryNotFound(_) | ShellError::HomeNotSet => None,
        }
    }
}

impl From<io::Error> for ShellError {
    fn from(err: io::Error) -> Self {
        ShellError::Io(err)
    }
}

impl From<shell_words::ParseError> for ShellError {
    fn from(err: shell_words::ParseError) -> Self {
        ShellError::Parse(err)
    }
}

enum BuiltinResult {
    Handled,
    Exit(i32),
    NotBuiltin,
}

/// Développe le préfixe `~` en chemin absolu vers le répertoire personnel (`$HOME`).
fn expand_tilde(path: &str) -> PathBuf {
    if path == "~" {
        if let Ok(home) = env::var("HOME") {
            return PathBuf::from(home);
        }
    } else if let Some(stripped) = path.strip_prefix("~/") {
        if let Ok(home) = env::var("HOME") {
            return PathBuf::from(home).join(stripped);
        }
    }
    PathBuf::from(path)
}

/// Affiche l'invite de commande avec le répertoire courant.
fn print_prompt() {
    let current_dir = env::current_dir().unwrap_or_else(|_| PathBuf::from("?"));
    let display_path = current_dir.display();
    print!("mini-sh [{}]> ", display_path);
    let _ = io::stdout().flush();
}

/// Gère l'exécution des commandes internes (built-ins).
fn handle_builtin(args: &[String]) -> Result<BuiltinResult, ShellError> {
    if args.is_empty() {
        return Ok(BuiltinResult::Handled);
    }

    match args[0].as_str() {
        "exit" | "quit" => {
            let code = if args.len() > 1 {
                args[1].parse::<i32>().unwrap_or(0)
            } else {
                0
            };
            Ok(BuiltinResult::Exit(code))
        }
        "cd" => {
            let target_path = if args.len() > 1 {
                expand_tilde(&args[1])
            } else {
                let home = env::var("HOME").map_err(|_| ShellError::HomeNotSet)?;
                PathBuf::from(home)
            };

            if let Err(err) = env::set_current_dir(&target_path) {
                if err.kind() == io::ErrorKind::NotFound {
                    return Err(ShellError::DirectoryNotFound(target_path));
                }
                return Err(ShellError::Io(err));
            }
            Ok(BuiltinResult::Handled)
        }
        "pwd" => {
            match env::current_dir() {
                Ok(dir) => println!("{}", dir.display()),
                Err(err) => return Err(ShellError::Io(err)),
            }
            Ok(BuiltinResult::Handled)
        }
        "help" => {
            println!("--- Mini Shell Interactif Rust ---");
            println!("Commandes internes :");
            println!("  cd [répertoire]  : Change le répertoire de travail actuel");
            println!("  pwd              : Affiche le répertoire courant");
            println!("  help             : Affiche cette aide");
            println!("  exit / quit [code]: Quitte le mini shell");
            println!("\nToutes les autres commandes sont exécutées via le PATH système.");
            println!("Appuyez sur Ctrl+C pour interrompre une commande en cours.");
            println!("Appuyez sur Ctrl+D pour quitter le shell.");
            Ok(BuiltinResult::Handled)
        }
        _ => Ok(BuiltinResult::NotBuiltin),
    }
}

/// Exécute une commande externe en créant un processus système.
fn execute_external(cmd: &str, args: &[String]) -> Result<(), ShellError> {
    let mut command = Command::new(cmd);
    command
        .args(args)
        .stdin(Stdio::inherit())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit());

    match command.status() {
        Ok(status) => {
            if let Some(code) = status.code() {
                if code != 0 {
                    // Code de sortie non nul : affiché seulement à titre d'information si besoin
                }
            } else {
                #[cfg(unix)]
                {
                    use std::os::unix::process::ExitStatusExt;
                    if let Some(signal) = status.signal() {
                        eprintln!("Processus interrompu par le signal {}", signal);
                    }
                }
            }
            Ok(())
        }
        Err(err) => {
            if err.kind() == io::ErrorKind::NotFound {
                eprintln!("{}: commande introuvable", cmd);
                Ok(())
            } else {
                Err(ShellError::Io(err))
            }
        }
    }
}

fn main() {
    let interrupted = Arc::new(AtomicBool::new(false));
    let interrupted_ctrlc = Arc::clone(&interrupted);

    // Configuration de la gestion du signal Ctrl+C (SIGINT)
    if let Err(err) = ctrlc::set_handler(move || {
        interrupted_ctrlc.store(true, Ordering::SeqCst);
        eprintln!(); // Retour à la ligne pour laisser un prompt propre
        print_prompt();
    }) {
        eprintln!("Avertissement: Impossible d'installer le gestionnaire de signaux : {}", err);
    }

    println!("Bienvenue dans le Mini Shell Rust (tapez 'help' pour la liste des commandes)");

    let stdin = io::stdin();
    let mut input = String::new();

    loop {
        interrupted.store(false, Ordering::SeqCst);
        print_prompt();

        input.clear();
        match stdin.read_line(&mut input) {
            Ok(0) => {
                // EOF rencontré (Ctrl+D)
                println!("\nAu revoir !");
                break;
            }
            Ok(_) => {
                let trimmed = input.trim();
                if trimmed.is_empty() {
                    continue;
                }

                // Découpage avec gestion des guillemets
                let words = match shell_words::split(trimmed) {
                    Ok(w) => w,
                    Err(err) => {
                        eprintln!("Erreur de syntaxe : {}", err);
                        continue;
                    }
                };

                if words.is_empty() {
                    continue;
                }

                // Vérification des commandes internes
                match handle_builtin(&words) {
                    Ok(BuiltinResult::Exit(code)) => {
                        std::process::exit(code);
                    }
                    Ok(BuiltinResult::Handled) => {
                        continue;
                    }
                    Ok(BuiltinResult::NotBuiltin) => {
                        let cmd = &words[0];
                        let args = &words[1..];
                        if let Err(err) = execute_external(cmd, args) {
                            eprintln!("Erreur lors de l'exécution de '{}' : {}", cmd, err);
                        }
                    }
                    Err(err) => {
                        eprintln!("Erreur : {}", err);
                    }
                }
            }
            Err(err) => {
                if err.kind() == io::ErrorKind::Interrupted {
                    // Lecture interrompue par un signal (ex: SIGINT)
                    continue;
                }
                eprintln!("Erreur lors de la lecture de l'entrée standard : {}", err);
                break;
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_expand_tilde() {
        if let Ok(home) = env::var("HOME") {
            assert_eq!(expand_tilde("~"), PathBuf::from(&home));
            assert_eq!(expand_tilde("~/documents"), PathBuf::from(&home).join("documents"));
        }
        assert_eq!(expand_tilde("/tmp/test"), PathBuf::from("/tmp/test"));
    }

    #[test]
    fn test_builtin_help() {
        let args = vec!["help".to_string()];
        let res = handle_builtin(&args).expect("builtin help failed");
        matches!(res, BuiltinResult::Handled);
    }

    #[test]
    fn test_builtin_exit() {
        let args = vec!["exit".to_string(), "42".to_string()];
        let res = handle_builtin(&args).expect("builtin exit failed");
        match res {
            BuiltinResult::Exit(code) => assert_eq!(code, 42),
            _ => panic!("Expected Exit(42)"),
        }
    }

    #[test]
    fn test_builtin_not_builtin() {
        let args = vec!["ls".to_string(), "-la".to_string()];
        let res = handle_builtin(&args).expect("builtin check failed");
        matches!(res, BuiltinResult::NotBuiltin);
    }
}

