        } else {
            (self.hits as f64 / self.total_accesses as f64) * 100.0
        }
    }

    pub fn fault_rate(&self) -> f64 {
        if self.total_accesses == 0 {
            0.0
        } else {
            (self.page_faults as f64 / self.total_accesses as f64) * 100.0
        }
    }
}

/// Système de mémoire virtuelle paginée (MMU + RAM + Swap).
pub struct VirtualMemorySystem {
    page_size: usize,
    num_virtual_pages: usize,
    num_physical_frames: usize,
    policy: ReplacementPolicy,

    /// Horloge logique incrémentée à chaque accès mémoire
    clock: u64,

    /// Table des pages : VPN -> PageTableEntry
    page_table: Vec<PageTableEntry>,

    /// Cadres physiques en RAM : `[frame_idx][offset]`
    physical_memory: Vec<Vec<u8>>,

    /// Mappage inverse : PFN -> VPN
    frame_to_page: Vec<Option<usize>>,

    /// Fichier de swap (mémoire secondaire persistée pour chaque page virtuelle)
    swap_storage: HashMap<usize, Vec<u8>>,

    /// File ordonnée des cadres alloués (utilisée pour l'éviction FIFO)
    fifo_queue: VecDeque<usize>,

    /// Statistiques cumulées
    stats: Statistics,
}

impl VirtualMemorySystem {
    /// Initialise le système de mémoire virtuelle.
    pub fn new(
        page_size: usize,
        num_virtual_pages: usize,
        num_physical_frames: usize,
        policy: ReplacementPolicy,
    ) -> Self {
        assert!(page_size > 0, "La taille d'une page doit être > 0");
        assert!(num_virtual_pages > 0, "Le nombre de pages virtuelles doit être > 0");
        assert!(num_physical_frames > 0, "Le nombre de cadres physiques doit être > 0");

        let page_table = vec![PageTableEntry::new(); num_virtual_pages];
        let physical_memory = vec![vec![0u8; page_size]; num_physical_frames];
        let frame_to_page = vec![None; num_physical_frames];

        Self {
            page_size,
            num_virtual_pages,
            num_physical_frames,
            policy,
            clock: 0,
            page_table,
            physical_memory,
            frame_to_page,
            swap_storage: HashMap::new(),
            fifo_queue: VecDeque::new(),
            stats: Statistics::default(),
        }
    }

    pub fn statistics(&self) -> &Statistics {
        &self.stats
    }

    pub fn page_size(&self) -> usize {
        self.page_size
    }

    pub fn total_virtual_size(&self) -> usize {
        self.num_virtual_pages * self.page_size
    }

    pub fn num_physical_frames(&self) -> usize {
        self.num_physical_frames
    }

    /// Décompose une adresse virtuelle en `(numéro_de_page, offset)`.
    fn translate_virtual_address(&self, vaddr: usize) -> Result<(usize, usize), MemoryError> {
        let max_addr = self.total_virtual_size();
        if vaddr >= max_addr {
            return Err(MemoryError::AddressOutOfBounds {
                address: vaddr,
                max_address: max_addr.saturating_sub(1),
            });
        }
        let vpn = vaddr / self.page_size;
        let offset = vaddr % self.page_size;
        Ok((vpn, offset))
    }

    /// Lit un octet à l'adresse virtuelle indiquée.
    pub fn read(&mut self, vaddr: usize) -> Result<u8, MemoryError> {
        let (vpn, offset) = self.translate_virtual_address(vaddr)?;
        self.clock = self.clock.wrapping_add(1);
        self.stats.total_accesses += 1;

        let frame_idx = self.ensure_page_in_ram(vpn)?;

        // Enregistre l'accès pour la politique LRU
        if let Some(entry) = self.page_table.get_mut(vpn) {
            entry.last_accessed_at = self.clock;
        }

        Ok(self.physical_memory[frame_idx][offset])
    }

    /// Écrit un octet à l'adresse virtuelle indiquée.
    pub fn write(&mut self, vaddr: usize, byte: u8) -> Result<(), MemoryError> {
        let (vpn, offset) = self.translate_virtual_address(vaddr)?;
        self.clock = self.clock.wrapping_add(1);
        self.stats.total_accesses += 1;

        let frame_idx = self.ensure_page_in_ram(vpn)?;

        // Met à jour la mémoire physique
        self.physical_memory[frame_idx][offset] = byte;

        // Met à jour l'entrée de page : bit dirty et timestamp
        if let Some(entry) = self.page_table.get_mut(vpn) {
            entry.dirty = true;
            entry.last_accessed_at = self.clock;
        }

        Ok(())
    }

    /// S'assure que la page virtuelle `vpn` est présente en RAM, provoquant un page fault si nécessaire.
    fn ensure_page_in_ram(&mut self, vpn: usize) -> Result<usize, MemoryError> {
        if vpn >= self.num_virtual_pages {
            return Err(MemoryError::InvalidPageNumber(vpn));
        }

        if let Some(pfn) = self.page_table[vpn].frame_number {
            if self.page_table[vpn].present {
                self.stats.hits += 1;
                return Ok(pfn);
            }
        }

        // Défaut de page (Page fault)
        self.stats.page_faults += 1;
        let target_frame = self.allocate_or_evict_frame()?;
        self.load_page_into_frame(vpn, target_frame);

        Ok(target_frame)
    }

    /// Trouve un cadre libre ou sélectionne un cadre à évincer selon la politique choisie.
    fn allocate_or_evict_frame(&mut self) -> Result<usize, MemoryError> {
        // 1. Chercher un cadre libre
        for (idx, slot) in self.frame_to_page.iter().enumerate() {
            if slot.is_none() {
                return Ok(idx);
            }
        }

        // 2. Aucun cadre libre : éviction nécessaire
        self.stats.evictions += 1;
        let victim_frame = match self.policy {
            ReplacementPolicy::Fifo => self.choose_victim_fifo(),
            ReplacementPolicy::Lru => self.choose_victim_lru(),
        };

        let victim_vpn = self.frame_to_page[victim_frame]
            .ok_or(MemoryError::InvalidPageNumber(victim_frame))?;

        // Si la page a été modifiée, la recopier dans le swap (write-back)
        if self.page_table[victim_vpn].dirty {
            self.stats.write_backs += 1;
            let page_data = self.physical_memory[victim_frame].clone();
            self.swap_storage.insert(victim_vpn, page_data);
        }

        // Invalider l'entrée dans la page table
        let victim_entry = &mut self.page_table[victim_vpn];
        victim_entry.present = false;
        victim_entry.frame_number = None;
        victim_entry.dirty = false;

        self.frame_to_page[victim_frame] = None;
        Ok(victim_frame)
    }

    /// Sélectionne la victime selon la politique FIFO.
    fn choose_victim_fifo(&mut self) -> usize {
        // Récupère le premier cadre de la file FIFO
        self.fifo_queue
            .pop_front()
            .unwrap_or(0)
    }

    /// Sélectionne la victime selon la politique LRU.
    fn choose_victim_lru(&self) -> usize {
        let mut oldest_time = u64::MAX;
        let mut victim_frame = 0;

        for (frame_idx, vpn_opt) in self.frame_to_page.iter().enumerate() {
            if let Some(vpn) = *vpn_opt {
                let last_access = self.page_table[vpn].last_accessed_at;
                if last_access < oldest_time {
                    oldest_time = last_access;
                    victim_frame = frame_idx;
                }
            }
        }

        victim_frame
    }

    /// Charge le contenu d'une page virtuelle dans un cadre physique spécifique.
    fn load_page_into_frame(&mut self, vpn: usize, frame_idx: usize) {
        // Restaurer depuis le swap si déjà existant, sinon initialiser avec des zéros
        if let Some(saved_data) = self.swap_storage.get(&vpn) {
            self.physical_memory[frame_idx].copy_from_slice(saved_data);
        } else {
            self.physical_memory[frame_idx].fill(0);
        }

        self.frame_to_page[frame_idx] = Some(vpn);

        let entry = &mut self.page_table[vpn];
        entry.present = true;
        entry.frame_number = Some(frame_idx);
        entry.dirty = false;
        entry.loaded_at = self.clock;
        entry.last_accessed_at = self.clock;

        if self.policy == ReplacementPolicy::Fifo {
            self.fifo_queue.push_back(frame_idx);
        }
    }
}

fn main() {
    println!("=== Simulateur de Mémoire Virtuelle avec Pagination ===");

    let page_size = 256; // 256 octets par page
    let num_virtual_pages = 8; // Espace d'adressage virtuel : 8 * 256 = 2048 octets
    let num_physical_frames = 3; // Mémoire physique restreinte à 3 cadres (768 octets)

    for policy in [ReplacementPolicy::Fifo, ReplacementPolicy::Lru] {
        println!("\n--- Test avec politique : {:?} ---", policy);
        let mut vmm = VirtualMemorySystem::new(
            page_size,
            num_virtual_pages,
            num_physical_frames,
            policy,
        );

        // Scénario de lecture/écriture simulant des accès variés
        let access_sequence = [
            (0 * page_size + 10, 0xAA), // Page 0 - Write
            (1 * page_size + 20, 0xBB), // Page 1 - Write
            (2 * page_size + 30, 0xCC), // Page 2 - Write
            (0 * page_size + 10, 0),    // Page 0 - Read (Hit)
            (3 * page_size + 40, 0xDD), // Page 3 - Write (Page Fault, éviction nécessaire)
            (1 * page_size + 20, 0),    // Page 1 - Read
            (4 * page_size + 50, 0xEE), // Page 4 - Write
        ];

        for (addr, val) in access_sequence {
            if val != 0 {
                if let Err(e) = vmm.write(addr, val) {
                    eprintln!("Erreur d'écriture à l'adresse {:#X} : {}", addr, e);
                } else {
                    println!("Écrit 0x{:02X} à l'adresse {:#X} (Page {})", val, addr, addr / page_size);
                }
            } else {
                match vmm.read(addr) {
                    Ok(read_val) => println!(
                        "Lu 0x{:02X} à l'adresse {:#X} (Page {})",
                        read_val, addr, addr / page_size
                    ),
                    Err(e) => eprintln!("Erreur de lecture à l'adresse {:#X} : {}", addr, e),
                }
            }
        }

        let stats = vmm.statistics();
        println!("\nRésultats pour {:?} :", policy);
        println!("  - Accès totaux       : {}", stats.total_accesses);
        println!("  - Hits               : {}", stats.hits);
        println!("  - Défauts de page    : {}", stats.page_faults);
        println!("  - Évictions          : {}", stats.evictions);
        println!("  - Écritures en swap  : {}", stats.write_backs);
        println!("  - Taux de hit        : {:.2}%", stats.hit_rate());
        println!("  - Taux de fautes     : {:.2}%", stats.fault_rate());
    }
}

