mod tests {
    use super::*;

    #[test]
    fn test_read_write_single_page() {
        let mut vmm = VirtualMemorySystem::new(64, 4, 2, ReplacementPolicy::Fifo);
        vmm.write(10, 42).expect("Write success");
        let val = vmm.read(10).expect("Read success");
        assert_eq!(val, 42);
        assert_eq!(vmm.statistics().hits, 1);
        assert_eq!(vmm.statistics().page_faults, 1);
    }

    #[test]
    fn test_address_out_of_bounds() {
        let mut vmm = VirtualMemorySystem::new(64, 2, 2, ReplacementPolicy::Fifo);
        // Total size = 128
        let res = vmm.read(130);
        assert!(matches!(res, Err(MemoryError::AddressOutOfBounds { .. })));
    }

    #[test]
    fn test_fifo_eviction() {
        let page_size = 100;
        let mut vmm = VirtualMemorySystem::new(page_size, 4, 2, ReplacementPolicy::Fifo);

        // Remplir 2 cadres : Page 0 et Page 1
        vmm.write(0 * page_size, 10).expect("write"); // frame 0
        vmm.write(1 * page_size, 20).expect("write"); // frame 1

        // Accéder à la page 0 (ne change pas l'ordre FIFO)
        let _ = vmm.read(0 * page_size).expect("read");

        // Charger la page 2 -> doit évincer la page 0 (FIFO)
        vmm.write(2 * page_size, 30).expect("write");

        assert_eq!(vmm.statistics().evictions, 1);
        assert!(!vmm.page_table[0].present);
        assert!(vmm.page_table[1].present);
        assert!(vmm.page_table[2].present);
    }

    #[test]
    fn test_lru_eviction() {
        let page_size = 100;
        let mut vmm = VirtualMemorySystem::new(page_size, 4, 2, ReplacementPolicy::Lru);

        // Charger Page 0 et Page 1
        vmm.write(0 * page_size, 10).expect("write");
        vmm.write(1 * page_size, 20).expect("write");

        // Réaccéder à Page 0 -> Page 0 devient la plus récemment utilisée, Page 1 la moins récente
        let _ = vmm.read(0 * page_size).expect("read");

        // Charger Page 2 -> doit évincer Page 1 car moins récemment utilisée que Page 0
        vmm.write(2 * page_size, 30).expect("write");

        assert_eq!(vmm.statistics().evictions, 1);
        assert!(vmm.page_table[0].present);
        assert!(!vmm.page_table[1].present);
        assert!(vmm.page_table[2].present);

        // Vérifier la persistance des données via le swap pour la page 1
        let val = vmm.read(1 * page_size).expect("read swapped page");
        assert_eq!(val, 20);
    }
}

