// Inversion de l'ordre pour transformer le Max-Heap de Rust en Min-Heap
impl<V: Eq, W: Ord> Ord for State<V, W> {
    fn cmp(&self, other: &Self) -> Ordering {
        other
            .cost
            .cmp(&self.cost)
            .then_with(|| Ordering::Equal)
    }
}

impl<V: Eq, W: Ord> PartialOrd for State<V, W> {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl<V, W> Graph<V, W>
where
    V: Eq + Hash + Clone + Ord,
    W: Copy + Default + Ord + std::ops::Add<Output = W>,
{
    /// Exécute l'algorithme de Dijkstra pour trouver le plus court chemin entre `start` et `goal`.
    /// Retourne `Some(ShortestPath)` si un chemin existe, ou `None` si le sommet n'est pas joignable.
    pub fn dijkstra(&self, start: &V, goal: &V) -> Option<ShortestPath<V, W>> {
        if !self.adjacency_list.contains_key(start) || !self.adjacency_list.contains_key(goal) {
            return None;
        }

        let mut distances: HashMap<V, W> = HashMap::new();
        let mut predecessors: HashMap<V, V> = HashMap::new();
        let mut heap: BinaryHeap<State<V, W>> = BinaryHeap::new();

        let zero_cost = W::default();
        distances.insert(start.clone(), zero_cost);
        heap.push(State {
            cost: zero_cost,
            node: start.clone(),
        });

        while let Some(State { cost, node }) = heap.pop() {
            if &node == goal {
                // Reconstruction du chemin optimal à partir des prédécesseurs
                let mut path = vec![goal.clone()];
                let mut current = goal.clone();
                while let Some(pred) = predecessors.get(&current) {
                    path.push(pred.clone());
                    current = pred.clone();
                    if &current == start {
                        break;
                    }
                }
                path.reverse();
                return Some(ShortestPath {
                    total_cost: cost,
                    path,
                });
            }

            // Si on a déjà trouvé un chemin plus court vers ce sommet, on ignore cette entrée périmée
            if let Some(&best_distance) = distances.get(&node) {
                if cost > best_distance {
                    continue;
                }
            }

            if let Some(neighbors) = self.adjacency_list.get(&node) {
                for edge in neighbors {
                    let next_cost = cost + edge.weight;
                    let is_shorter = match distances.get(&edge.target) {
                        Some(&current_best) => next_cost < current_best,
                        None => true,
                    };

                    if is_shorter {
                        distances.insert(edge.target.clone(), next_cost);
                        predecessors.insert(edge.target.clone(), node.clone());
                        heap.push(State {
                            cost: next_cost,
                            node: edge.target.clone(),
                        });
                    }
                }
            }
        }

        None
    }
}

fn print_route<V: Display, W: Display>(result: &Option<ShortestPath<V, W>>, from: &V, to: &V) {
    match result {
        Some(sp) => {
            let path_str: Vec<String> = sp.path.iter().map(|n| n.to_string()).collect();
            println!(
                "✓ Chemin le plus court entre {} et {} : {} (Coût total: {})",
                from,
                to,
                path_str.join(" -> "),
                sp.total_cost
            );
        }
        None => {
            println!("✗ Aucun chemin trouvé entre {} et {}.", from, to);
        }
    }
}

fn main() {
    println!("=== Simulation d'un réseau de routage (Dijkstra) ===");

    let mut network = Graph::<&str, u32>::new();

    // Construction d'une topologie réseau
    network.add_edge("Routeur_A", "Routeur_B", 4);
    network.add_edge("Routeur_A", "Routeur_C", 2);
    network.add_edge("Routeur_B", "Routeur_C", 5);
    network.add_edge("Routeur_B", "Routeur_D", 10);
    network.add_edge("Routeur_C", "Routeur_E", 3);
    network.add_edge("Routeur_E", "Routeur_D", 4);
    network.add_edge("Routeur_D", "Routeur_F", 11);
    network.add_edge("Routeur_E", "Routeur_F", 8);

    // Nœud isolé pour tester l'absence de chemin
    network.add_node("Routeur_Isole");

    let source = "Routeur_A";
    let destination = "Routeur_D";
    let route = network.dijkstra(&source, &destination);
    print_route(&route, &source, &destination);

    let destination_f = "Routeur_F";
    let route_f = network.dijkstra(&source, &destination_f);
    print_route(&route_f, &source, &destination_f);

    let destination_isole = "Routeur_Isole";
    let route_isole = network.dijkstra(&source, &destination_isole);
    print_route(&route_isole, &source, &destination_isole);
}

