/// Tokens propres au format JSON (RFC 8259).
#[derive(Debug, Clone, PartialEq)]
pub enum JsonTokenKind {
    BraceOpen,         // {
    BraceClose,        // }
    BracketOpen,       // [
    BracketClose,      // ]
    Colon,             // :
    Comma,             // ,
    String(String),    // "..."
    Number(f64),       // 123, -4.56, 1e10
    Boolean(bool),     // true, false
    Null,              // null
    Eof,               // Fin de flux
}

/// Analyseur lexical pour le format JSON.
pub struct JsonLexer<'a> {
    source: &'a str,
    cursor: usize,
    line: usize,
    column: usize,
}

impl<'a> JsonLexer<'a> {
    pub fn new(source: &'a str) -> Self {
        Self {
            source,
            cursor: 0,
            line: 1,
            column: 1,
        }
    }

    fn peek_char(&self) -> Option<char> {
        self.source[self.cursor..].chars().next()
    }

    fn bump_char(&mut self) -> Option<char> {
        let ch = self.peek_char()?;
        self.cursor += ch.len_utf8();
        if ch == '\n' {
            self.line += 1;
            self.column = 1;
        } else {
            self.column += 1;
        }
        Some(ch)
    }

    fn skip_whitespace(&mut self) {
        while let Some(ch) = self.peek_char() {
            if ch.is_whitespace() {
                self.bump_char();
            } else {
                break;
            }
        }
    }

    fn read_string(&mut self, start_pos: usize, start_line: usize, start_col: usize) -> Result<Token<JsonTokenKind>, LexerError> {
        self.bump_char(); // Consommer le guillemet initial "
        let mut buffer = String::new();

        while let Some(ch) = self.peek_char() {
            match ch {
                '"' => {
                    self.bump_char(); // Consommer le guillemet fermant
                    let span = Span::new(start_pos, self.cursor, start_line, start_col);
                    return Ok(Token::new(JsonTokenKind::String(buffer), span));
                }
                '\\' => {
                    let esc_start = self.cursor;
                    self.bump_char(); // Consommer l'antislash
                    match self.bump_char() {
                        Some('"') => buffer.push('"'),
                        Some('\\') => buffer.push('\\'),
                        Some('/') => buffer.push('/'),
                        Some('b') => buffer.push('\x08'),
                        Some('f') => buffer.push('\x0c'),
                        Some('n') => buffer.push('\n'),
                        Some('r') => buffer.push('\r'),
                        Some('t') => buffer.push('\t'),
                        Some('u') => {
                            let mut hex = String::with_capacity(4);
                            for _ in 0..4 {
                                if let Some(h) = self.bump_char() {
                                    if h.is_ascii_hexdigit() {
                                        hex.push(h);
                                    } else {
                                        let span = Span::new(esc_start, self.cursor, start_line, start_col);
                                        return Err(LexerError::InvalidEscapeSequence {
                                            seq: format!("\\u{hex}{h}"),
                                            span,
                                        });
                                    }
                                } else {
                                    let span = Span::new(esc_start, self.cursor, start_line, start_col);
                                    return Err(LexerError::UnterminatedString { span });
                                }
                            }
                            if let Ok(code) = u32::from_str_radix(&hex, 16) {
                                if let Some(scalar) = char::from_u32(code) {
                                    buffer.push(scalar);
                                } else {
                                    let span = Span::new(esc_start, self.cursor, start_line, start_col);
                                    return Err(LexerError::InvalidEscapeSequence {
                                        seq: format!("\\u{hex}"),
                                        span,
                                    });
                                }
                            }
                        }
                        Some(other) => {
                            let span = Span::new(esc_start, self.cursor, start_line, start_col);
                            return Err(LexerError::InvalidEscapeSequence {
                                seq: format!("\\{other}"),
                                span,
                            });
                        }
                        None => {
                            let span = Span::new(start_pos, self.cursor, start_line, start_col);
                            return Err(LexerError::UnterminatedString { span });
                        }
                    }
                }
                '\n' | '\r' => {
                    let span = Span::new(start_pos, self.cursor, start_line, start_col);
                    return Err(LexerError::UnterminatedString { span });
                }
                c => {
                    buffer.push(c);
                    self.bump_char();
                }
            }
        }

        let span = Span::new(start_pos, self.cursor, start_line, start_col);
        Err(LexerError::UnterminatedString { span })
    }

    fn read_number(&mut self, start_pos: usize, start_line: usize, start_col: usize) -> Result<Token<JsonTokenKind>, LexerError> {
        let mut raw = String::new();
        if let Some('-') = self.peek_char() {
            raw.push('-');
            self.bump_char();
        }

        let mut has_digits = false;
        while let Some(ch) = self.peek_char() {
            if ch.is_ascii_digit() {
                has_digits = true;
                raw.push(ch);
                self.bump_char();
            } else {
                break;
            }
        }

        if !has_digits {
            let span = Span::new(start_pos, self.cursor, start_line, start_col);
            return Err(LexerError::InvalidNumericLiteral {
                raw,
                reason: "Chiffres attendus après le signe moins".into(),
                span,
            });
        }

        if let Some('.') = self.peek_char() {
            raw.push('.');
            self.bump_char();
            let mut fractional_digits = false;
            while let Some(ch) = self.peek_char() {
                if ch.is_ascii_digit() {
                    fractional_digits = true;
                    raw.push(ch);
                    self.bump_char();
                } else {
                    break;
                }
            }
            if !fractional_digits {
                let span = Span::new(start_pos, self.cursor, start_line, start_col);
                return Err(LexerError::InvalidNumericLiteral {
                    raw,
                    reason: "Chiffres attendus après le point décimal".into(),
                    span,
                });
            }
        }

        if let Some('e' | 'E') = self.peek_char() {
            let exp_char = self.bump_char().unwrap_or('e');
            raw.push(exp_char);
            if let Some('+' | '-') = self.peek_char() {
                raw.push(self.bump_char().unwrap_or('+'));
            }
            let mut exp_digits = false;
            while let Some(ch) = self.peek_char() {
                if ch.is_ascii_digit() {
                    exp_digits = true;
                    raw.push(ch);
                    self.bump_char();
                } else {
                    break;
                }
            }
            if !exp_digits {
                let span = Span::new(start_pos, self.cursor, start_line, start_col);
                return Err(LexerError::InvalidNumericLiteral {
                    raw,
                    reason: "Exposant incomplet".into(),
                    span,
                });
            }
        }

        let span = Span::new(start_pos, self.cursor, start_line, start_col);
        match raw.parse::<f64>() {
            Ok(val) => Ok(Token::new(JsonTokenKind::Number(val), span)),
            Err(e) => Err(LexerError::InvalidNumericLiteral {
                raw,
                reason: e.to_string(),
                span,
            }),
        }
    }

    fn read_ident_or_keyword(&mut self, start_pos: usize, start_line: usize, start_col: usize) -> Result<Token<JsonTokenKind>, LexerError> {
        let mut word = String::new();
        while let Some(ch) = self.peek_char() {
            if ch.is_ascii_alphabetic() {
                word.push(ch);
                self.bump_char();
            } else {
                break;
            }
        }

        let span = Span::new(start_pos, self.cursor, start_line, start_col);
        match word.as_str() {
            "true" => Ok(Token::new(JsonTokenKind::Boolean(true), span)),
            "false" => Ok(Token::new(JsonTokenKind::Boolean(false), span)),
            "null" => Ok(Token::new(JsonTokenKind::Null, span)),
            _ => Err(LexerError::UnexpectedChar {
                ch: word.chars().next().unwrap_or('?'),
                span,
            }),
        }
    }

    /// Découpe le flux complet de tokens.
    pub fn tokenize(&mut self) -> Result<Vec<Token<JsonTokenKind>>, LexerError> {
        let mut tokens = Vec::new();
        loop {
            let tok = self.next_token()?;
            let is_eof = tok.kind == JsonTokenKind::Eof;
            tokens.push(tok);
            if is_eof {
                break;
            }
        }
        Ok(tokens)
    }

    /// Extrait le token suivant.
    pub fn next_token(&mut self) -> Result<Token<JsonTokenKind>, LexerError> {
        self.skip_whitespace();
        let start_pos = self.cursor;
        let start_line = self.line;
        let start_col = self.column;

        let ch = match self.peek_char() {
            Some(c) => c,
            None => {
                let span = Span::new(start_pos, start_pos, start_line, start_col);
                return Ok(Token::new(JsonTokenKind::Eof, span));
            }
        };

        match ch {
            '{' => {
                self.bump_char();
                Ok(Token::new(JsonTokenKind::BraceOpen, Span::new(start_pos, self.cursor, start_line, start_col)))
            }
            '}' => {
                self.bump_char();
                Ok(Token::new(JsonTokenKind::BraceClose, Span::new(start_pos, self.cursor, start_line, start_col)))
            }
            '[' => {
                self.bump_char();
                Ok(Token::new(JsonTokenKind::BracketOpen, Span::new(start_pos, self.cursor, start_line, start_col)))
            }
            ']' => {
                self.bump_char();
                Ok(Token::new(JsonTokenKind::BracketClose, Span::new(start_pos, self.cursor, start_line, start_col)))
            }
            ':' => {
                self.bump_char();
                Ok(Token::new(JsonTokenKind::Colon, Span::new(start_pos, self.cursor, start_line, start_col)))
            }
            ',' => {
                self.bump_char();
                Ok(Token::new(JsonTokenKind::Comma, Span::new(start_pos, self.cursor, start_line, start_col)))
            }
            '"' => self.read_string(start_pos, start_line, start_col),
            '-' | '0'..='9' => self.read_number(start_pos, start_line, start_col),
            'a'..='z' | 'A'..='Z' => self.read_ident_or_keyword(start_pos, start_line, start_col),
            other => {
                self.bump_char();
                Err(LexerError::UnexpectedChar {
                    ch: other,
                    span: Span::new(start_pos, self.cursor, start_line, start_col),
                })
            }
        }
    }
}

