/// Tokens pour un sous-ensemble représentatif du langage Rust (Mini-Rust).
#[derive(Debug, Clone, PartialEq)]
pub enum RustTokenKind {
    // Mots-clés
    Fn,
    Let,
    Mut,
    Struct,
    Enum,
    If,
    Else,
    Match,
    Return,
    Pub,
    Impl,
    Use,
    True,
    False,

    // Identifiant & Littéraux
    Ident(String),
    IntLiteral(i128),
    FloatLiteral(f64),
    StringLiteral(String),

    // Délimiteurs & Ponctuation
    ParenOpen,    // (
    ParenClose,   // )
    BraceOpen,    // {
    BraceClose,   // }
    BracketOpen,  // [
    BracketClose, // ]
    Semicolon,    // ;
    Colon,        // :
    DoubleColon,  // ::
    Comma,        // ,
    Dot,          // .
    DotDot,       // ..
    Arrow,        // ->
    FatArrow,     // =>

    // Opérateurs
    Eq,           // =
    EqEq,         // ==
    NotEq,        // !=
    Lt,           // <
    LtEq,         // <=
    Gt,           // >
    GtEq,         // >=
    Plus,         // +
    Minus,        // -
    Star,         // *
    Slash,        // /
    Percent,      // %
    Amp,          // &
    AmpAmp,       // &&
    Pipe,         // |
    PipePipe,     // ||
    Bang,         // !

    // Fin de flux
    Eof,
}

/// Analyseur lexical pour le sous-ensemble Rust.
pub struct RustLexer<'a> {
    source: &'a str,
    cursor: usize,
    line: usize,
    column: usize,
}

impl<'a> RustLexer<'a> {
    pub fn new(source: &'a str) -> Self {
        Self {
            source,
            cursor: 0,
            line: 1,
            column: 1,
        }
    }

    fn peek_char(&self) -> Option<char> {
        self.source[self.cursor..].chars().next()
    }

    fn peek_second_char(&self) -> Option<char> {
        let mut it = self.source[self.cursor..].chars();
        it.next()?;
        it.next()
    }

    fn bump_char(&mut self) -> Option<char> {
        let ch = self.peek_char()?;
        self.cursor += ch.len_utf8();
        if ch == '\n' {
            self.line += 1;
            self.column = 1;
        } else {
            self.column += 1;
        }
        Some(ch)
    }

    fn skip_whitespace_and_comments(&mut self) -> Result<(), LexerError> {
        loop {
            // Passer les blancs
            while let Some(ch) = self.peek_char() {
                if ch.is_whitespace() {
                    self.bump_char();
                } else {
                    break;
                }
            }

            // Gestion des commentaires // et /* ... */
            if self.peek_char() == Some('/') {
                if self.peek_second_char() == Some('/') {
                    // Commentaire de ligne : ignorer jusqu'à fin de ligne
                    self.bump_char();
                    self.bump_char();
                    while let Some(c) = self.peek_char() {
                        if c == '\n' {
                            self.bump_char();
                            break;
                        }
                        self.bump_char();
                    }
                    continue;
                } else if self.peek_second_char() == Some('*') {
                    // Commentaire bloc
                    let start_pos = self.cursor;
                    let start_line = self.line;
                    let start_col = self.column;

                    self.bump_char();
                    self.bump_char();
                    let mut closed = false;

                    while let Some(c) = self.peek_char() {
                        if c == '*' && self.peek_second_char() == Some('/') {
                            self.bump_char();
                            self.bump_char();
                            closed = true;
                            break;
                        }
                        self.bump_char();
                    }

                    if !closed {
                        return Err(LexerError::UnterminatedBlockComment {
                            span: Span::new(start_pos, self.cursor, start_line, start_col),
                        });
                    }
                    continue;
                }
            }

            break;
        }
        Ok(())
    }

    fn read_ident_or_keyword(&mut self, start_pos: usize, start_line: usize, start_col: usize) -> Token<RustTokenKind> {
        let mut ident = String::new();
        while let Some(ch) = self.peek_char() {
            if ch.is_alphanumeric() || ch == '_' {
                ident.push(ch);
                self.bump_char();
            } else {
                break;
            }
        }

        let span = Span::new(start_pos, self.cursor, start_line, start_col);
        let kind = match ident.as_str() {
            "fn" => RustTokenKind::Fn,
            "let" => RustTokenKind::Let,
            "mut" => RustTokenKind::Mut,
            "struct" => RustTokenKind::Struct,
            "enum" => RustTokenKind::Enum,
            "if" => RustTokenKind::If,
            "else" => RustTokenKind::Else,
            "match" => RustTokenKind::Match,
            "return" => RustTokenKind::Return,
            "pub" => RustTokenKind::Pub,
            "impl" => RustTokenKind::Impl,
            "use" => RustTokenKind::Use,
            "true" => RustTokenKind::True,
            "false" => RustTokenKind::False,
            _ => RustTokenKind::Ident(ident),
        };

        Token::new(kind, span)
    }

    fn read_number(&mut self, start_pos: usize, start_line: usize, start_col: usize) -> Result<Token<RustTokenKind>, LexerError> {
        let mut raw = String::new();

        // Gestion base 0x (hex) ou 0b (binaire)
        if self.peek_char() == Some('0') {
            if let Some(prefix) = self.peek_second_char() {
                if prefix == 'x' || prefix == 'X' {
                    self.bump_char(); // '0'
                    self.bump_char(); // 'x'
                    let mut hex_digits = String::new();
                    while let Some(ch) = self.peek_char() {
                        if ch.is_ascii_hexdigit() {
                            hex_digits.push(ch);
                            self.bump_char();
                        } else if ch == '_' {
                            self.bump_char();
                        } else {
                            break;
                        }
                    }
                    let span = Span::new(start_pos, self.cursor, start_line, start_col);
                    if hex_digits.is_empty() {
                        return Err(LexerError::InvalidNumericLiteral {
                            raw: "0x".into(),
                            reason: "Chiffres hexadécimaux manquants".into(),
                            span,
                        });
                    }
                    return match i128::from_str_radix(&hex_digits, 16) {
                        Ok(v) => Ok(Token::new(RustTokenKind::IntLiteral(v), span)),
                        Err(e) => Err(LexerError::InvalidNumericLiteral {
                            raw: format!("0x{hex_digits}"),
                            reason: e.to_string(),
                            span,
                        }),
                    };
                } else if prefix == 'b' || prefix == 'B' {
                    self.bump_char(); // '0'
                    self.bump_char(); // 'b'
                    let mut bin_digits = String::new();
                    while let Some(ch) = self.peek_char() {
                        if ch == '0' || ch == '1' {
                            bin_digits.push(ch);
                            self.bump_char();
                        } else if ch == '_' {
                            self.bump_char();
                        } else {
                            break;
                        }
                    }
                    let span = Span::new(start_pos, self.cursor, start_line, start_col);
                    if bin_digits.is_empty() {
                        return Err(LexerError::InvalidNumericLiteral {
                            raw: "0b".into(),
                            reason: "Chiffres binaires manquants".into(),
                            span,
                        });
                    }
                    return match i128::from_str_radix(&bin_digits, 2) {
                        Ok(v) => Ok(Token::new(RustTokenKind::IntLiteral(v), span)),
                        Err(e) => Err(LexerError::InvalidNumericLiteral {
                            raw: format!("0b{bin_digits}"),
                            reason: e.to_string(),
                            span,
                        }),
                    };
                }
            }
        }

        let mut is_float = false;
        while let Some(ch) = self.peek_char() {
            if ch.is_ascii_digit() {
                raw.push(ch);
                self.bump_char();
            } else if ch == '_' {
                self.bump_char();
            } else if ch == '.' && self.peek_second_char().map_or(false, |next| next.is_ascii_digit()) {
                is_float = true;
                raw.push('.');
                self.bump_char(); // consomme '.'
            } else {
                break;
            }
        }

        let span = Span::new(start_pos, self.cursor, start_line, start_col);
        if is_float {
            match raw.parse::<f64>() {
                Ok(val) => Ok(Token::new(RustTokenKind::FloatLiteral(val), span)),
                Err(e) => Err(LexerError::InvalidNumericLiteral {
                    raw,
                    reason: e.to_string(),
                    span,
                }),
            }
        } else {
            match raw.parse::<i128>() {
                Ok(val) => Ok(Token::new(RustTokenKind::IntLiteral(val), span)),
                Err(e) => Err(LexerError::InvalidNumericLiteral {
                    raw,
                    reason: e.to_string(),
                    span,
                }),
            }
        }
    }

    fn read_string(&mut self, start_pos: usize, start_line: usize, start_col: usize) -> Result<Token<RustTokenKind>, LexerError> {
        self.bump_char(); // "
        let mut buffer = String::new();

        while let Some(ch) = self.peek_char() {
            match ch {
                '"' => {
                    self.bump_char();
                    let span = Span::new(start_pos, self.cursor, start_line, start_col);
                    return Ok(Token::new(RustTokenKind::StringLiteral(buffer), span));
                }
                '\\' => {
                    self.bump_char();
                    match self.bump_char() {
                        Some('n') => buffer.push('\n'),
                        Some('t') => buffer.push('\t'),
                        Some('r') => buffer.push('\r'),
                        Some('\\') => buffer.push('\\'),
                        Some('"') => buffer.push('"'),
                        Some('0') => buffer.push('\0'),
                        Some(c) => {
                            let span = Span::new(start_pos, self.cursor, start_line, start_col);
                            return Err(LexerError::InvalidEscapeSequence {
                                seq: format!("\\{c}"),
                                span,
                            });
                        }
                        None => {
                            let span = Span::new(start_pos, self.cursor, start_line, start_col);
                            return Err(LexerError::UnterminatedString { span });
                        }
                    }
                }
                c => {
                    buffer.push(c);
                    self.bump_char();
                }
            }
        }

        let span = Span::new(start_pos, self.cursor, start_line, start_col);
        Err(LexerError::UnterminatedString { span })
    }

    /// Découpe le flux complet de tokens Rust.
    pub fn tokenize(&mut self) -> Result<Vec<Token<RustTokenKind>>, LexerError> {
        let mut tokens = Vec::new();
        loop {
            let tok = self.next_token()?;
            let is_eof = tok.kind == RustTokenKind::Eof;
            tokens.push(tok);
            if is_eof {
                break;
            }
        }
        Ok(tokens)
    }

    /// Extrait le prochain token Rust.
    pub fn next_token(&mut self) -> Result<Token<RustTokenKind>, LexerError> {
        self.skip_whitespace_and_comments()?;
        let start_pos = self.cursor;
        let start_line = self.line;
        let start_col = self.column;

        let ch = match self.peek_char() {
            Some(c) => c,
            None => {
                let span = Span::new(start_pos, start_pos, start_line, start_col);
                return Ok(Token::new(RustTokenKind::Eof, span));
            }
        };

        match ch {
            // Délimiteurs simples
            '(' => {
                self.bump_char();
                Ok(Token::new(RustTokenKind::ParenOpen, Span::new(start_pos, self.cursor, start_line, start_col)))
            }
            ')' => {
                self.bump_char();
                Ok(Token::new(RustTokenKind::ParenClose, Span::new(start_pos, self.cursor, start_line, start_col)))
            }
            '{' => {
                self.bump_char();
                Ok(Token::new(RustTokenKind::BraceOpen, Span::new(start_pos, self.cursor, start_line, start_col)))
            }
            '}' => {
                self.bump_char();
                Ok(Token::new(RustTokenKind::BraceClose, Span::new(start_pos, self.cursor, start_line, start_col)))
            }
            '[' => {
                self.bump_char();
                Ok(Token::new(RustTokenKind::BracketOpen, Span::new(start_pos, self.cursor, start_line, start_col)))
            }
            ']' => {
                self.bump_char();
                Ok(Token::new(RustTokenKind::BracketClose, Span::new(start_pos, self.cursor, start_line, start_col)))
            }
            ';' => {
                self.bump_char();
                Ok(Token::new(RustTokenKind::Semicolon, Span::new(start_pos, self.cursor, start_line, start_col)))
            }
            ',' => {
                self.bump_char();
                Ok(Token::new(RustTokenKind::Comma, Span::new(start_pos, self.cursor, start_line, start_col)))
            }
            '+' => {
                self.bump_char();
                Ok(Token::new(RustTokenKind::Plus, Span::new(start_pos, self.cursor, start_line, start_col)))
            }
            '*' => {
                self.bump_char();
                Ok(Token::new(RustTokenKind::Star, Span::new(start_pos, self.cursor, start_line, start_col)))
            }
            '/' => {
                self.bump_char();
                Ok(Token::new(RustTokenKind::Slash, Span::new(start_pos, self.cursor, start_line, start_col)))
            }
            '%' => {
                self.bump_char();
                Ok(Token::new(RustTokenKind::Percent, Span::new(start_pos, self.cursor, start_line, start_col)))
            }

            // Opérateurs composés
            '-' => {
                self.bump_char();
                if self.peek_char() == Some('>') {
                    self.bump_char();
                    Ok(Token::new(RustTokenKind::Arrow, Span::new(start_pos, self.cursor, start_line, start_col)))
                } else {
                    Ok(Token::new(RustTokenKind::Minus, Span::new(start_pos, self.cursor, start_line, start_col)))
                }
            }
            '=' => {
                self.bump_char();
                if self.peek_char() == Some('>') {
                    self.bump_char();
                    Ok(Token::new(RustTokenKind::FatArrow, Span::new(start_pos, self.cursor, start_line, start_col)))
                } else if self.peek_char() == Some('=') {
                    self.bump_char();
                    Ok(Token::new(RustTokenKind::EqEq, Span::new(start_pos, self.cursor, start_line, start_col)))
                } else {
                    Ok(Token::new(RustTokenKind::Eq, Span::new(start_pos, self.cursor, start_line, start_col)))
                }
            }
            '!' => {
                self.bump_char();
                if self.peek_char() == Some('=') {
                    self.bump_char();
                    Ok(Token::new(RustTokenKind::NotEq, Span::new(start_pos, self.cursor, start_line, start_col)))
                } else {
                    Ok(Token::new(RustTokenKind::Bang, Span::new(start_pos, self.cursor, start_line, start_col)))
                }
            }
            '<' => {
                self.bump_char();
                if self.peek_char() == Some('=') {
                    self.bump_char();
                    Ok(Token::new(RustTokenKind::LtEq, Span::new(start_pos, self.cursor, start_line, start_col)))
                } else {
                    Ok(Token::new(RustTokenKind::Lt, Span::new(start_pos, self.cursor, start_line, start_col)))
                }
            }
            '>' => {
                self.bump_char();
                if self.peek_char() == Some('=') {
                    self.bump_char();
                    Ok(Token::new(RustTokenKind::GtEq, Span::new(start_pos, self.cursor, start_line, start_col)))
                } else {
                    Ok(Token::new(RustTokenKind::Gt, Span::new(start_pos, self.cursor, start_line, start_col)))
                }
            }
            ':' => {
                self.bump_char();
                if self.peek_char() == Some(':') {
                    self.bump_char();
                    Ok(Token::new(RustTokenKind::DoubleColon, Span::new(start_pos, self.cursor, start_line, start_col)))
                } else {
                    Ok(Token::new(RustTokenKind::Colon, Span::new(start_pos, self.cursor, start_line, start_col)))
                }
            }
            '.' => {
                self.bump_char();
                if self.peek_char() == Some('.') {
                    self.bump_char();
                    Ok(Token::new(RustTokenKind::DotDot, Span::new(start_pos, self.cursor, start_line, start_col)))
                } else {
                    Ok(Token::new(RustTokenKind::Dot, Span::new(start_pos, self.cursor, start_line, start_col)))
                }
            }
            '&' => {
                self.bump_char();
                if self.peek_char() == Some('&') {
                    self.bump_char();
                    Ok(Token::new(RustTokenKind::AmpAmp, Span::new(start_pos, self.cursor, start_line, start_col)))
                } else {
                    Ok(Token::new(RustTokenKind::Amp, Span::new(start_pos, self.cursor, start_line, start_col)))
                }
            }
            '|' => {
                self.bump_char();
                if self.peek_char() == Some('|') {
                    self.bump_char();
                    Ok(Token::new(RustTokenKind::PipePipe, Span::new(start_pos, self.cursor, start_line, start_col)))
                } else {
                    Ok(Token::new(RustTokenKind::Pipe, Span::new(start_pos, self.cursor, start_line, start_col)))
                }
            }

            // Chaînes
            '"' => self.read_string(start_pos, start_line, start_col),

            // Nombres
            '0'..='9' => self.read_number(start_pos, start_line, start_col),

            // Identifiants & Mots-clés
            'a'..='z' | 'A'..='Z' | '_' => Ok(self.read_ident_or_keyword(start_pos, start_line, start_col)),

            other => {
                self.bump_char();
                Err(LexerError::UnexpectedChar {
                    ch: other,
                    span: Span::new(start_pos, self.cursor, start_line, start_col),
                })
            }
        }
    }
}

