// src/main.rs
use std::fmt;
use thiserror::Error;

/// Position et étendue d'un token dans le code source d'origine.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Span {
    pub start: usize,
    pub end: usize,
    pub line: usize,
    pub column: usize,
}

impl Span {
    pub const fn new(start: usize, end: usize, line: usize, column: usize) -> Self {
        Self {
            start,
            end,
            line,
            column,
        }
    }
}

impl fmt::Display for Span {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}:{}-{}:{}", self.line, self.column, self.end, self.column + (self.end - self.start))
    }
}

/// Token générique englobant une catégorie typée et sa position (Span).
#[derive(Debug, Clone, PartialEq)]
pub struct Token<K> {
    pub kind: K,
    pub span: Span,
}

impl<K> Token<K> {
    pub const fn new(kind: K, span: Span) -> Self {
        Self { kind, span }
    }
}

/// Erreurs possibles lors de l'analyse lexicale.
#[derive(Error, Debug, Clone, PartialEq)]
pub enum LexerError {
    #[error("Caractère inattendu '{ch}' à la position {span}")]
    UnexpectedChar { ch: char, span: Span },

    #[error("Littéral chaîne non fermé débutant à {span}")]
    UnterminatedString { span: Span },

    #[error("Séquence d'échappement invalide '{seq}' à {span}")]
    InvalidEscapeSequence { seq: String, span: Span },

    #[error("Littéral numérique invalide '{raw}' à {span}: {reason}")]
    InvalidNumericLiteral {
        raw: String,
        reason: String,
        span: Span,
    },

    #[error("Commentaire bloc non fermé débutant à {span}")]
    UnterminatedBlockComment { span: Span },
}

