```rust
// src/main.rs
use anyhow::{Context, Result};
use clap::{Parser, ValueEnum};
use std::collections::BTreeMap;
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::PathBuf;
use unicode_segmentation::UnicodeSegmentation;

#[derive(Debug, Copy, Clone, PartialEq, Eq, ValueEnum)]
enum SortOrder {
    /// Tri alphabétique (naturel avec BTreeMap)
    Alphabetical,
    /// Tri par fréquence décroissante
    Frequency,
}

#[derive(Parser, Debug)]
#[command(
    name = "text-stat",
    about = "Analyse statistique de texte (fréquences de mots, n-grammes)",
    version
)]
struct Cli {
    /// Fichier texte à analyser (si omis, lecture sur stdin)
    #[arg(short, long, value_name = "FILE")]
    input: Option<PathBuf>,

    /// Taille des n-grammes (ex: 1 pour mots seuls, 2 pour bigrammes, etc.)
    #[arg(short = 'n', long = "ngram", default_value_t = 1)]
    ngram_size: usize,

    /// Sensibilité à la casse
    #[arg(short = 'c', long = "case-sensitive", default_value_t = false)]
    case_sensitive: bool,

    /// Nombre maximum d'entrées à afficher (0 = illimité)
    #[arg(short = 't', long = "top", default_value_t = 0)]
    top: usize,

    /// Critère de tri des résultats
    #[arg(short = 's', long = "sort", value_enum, default_value_t = SortOrder::Alphabetical)]
    sort: SortOrder,

    /// Seuil minimal d'occurrences pour afficher une entrée
    #[arg(short = 'm', long = "min-count", default_value_t = 1)]
    min_count: usize,
}

/// Tokenise une ligne en mots en utilisant la segmentation Unicode standard.
fn extract_words(line: &str, case_sensitive: bool) -> Vec<String> {
    line.unicode_words()
        .map(|w| {
            if case_sensitive {
                w.to_string()
            } else {
                w.to_lowercase()
            }
        })
        .collect()
}

/// Calcule les fréquences de n-grammes stockées dans un `BTreeMap` garantissant l'ordre alphabétique.
fn count_ngrams<R: BufRead>(
    reader: R,
    n: usize,
    case_sensitive: bool,
) -> Result<(BTreeMap<String, usize>, usize)> {
    let mut map: BTreeMap<String, usize> = BTreeMap::new();
    let mut total_count = 0usize;

    if n == 0 {
        anyhow::bail!("La taille du n-gramme doit être supérieure ou égale à 1");
    }

    for line_result in reader.lines() {
        let line = line_result.context("Erreur de lecture de ligne")?;
        let words = extract_words(&line, case_sensitive);

        if words.len() < n {
            continue;
        }

        for window in words.windows(n) {
            let ngram = window.join(" ");
            *map.entry(ngram).or_insert(0) += 1;
            total_count += 1;
        }
    }

    Ok((map, total_count))
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    if cli.ngram_size == 0 {
        eprintln!("Erreur : --ngram doit être d'au moins 1.");
        std::process::exit(1);
    }

    // Sélection de la source d'entrée (fichier ou stdin)
    let reader: Box<dyn BufRead> = match &cli.input {
        Some(path) => {
            let file = File::open(path)
                .with_context(|| format!("Impossible d'ouvrir le fichier '{}'", path.display()))?;
            Box::new(BufReader::new(file))
        }
        None => Box::new(BufReader::new(io::stdin())),
    };

    let (freq_map, total_tokens) = count_ngrams(reader, cli.ngram_size, cli.case_sensitive)?;

    // Filtrage par seuil minimal
    let filtered: Vec<(&String, &usize)> = freq_map
        .iter()
        .filter(|(_, &count)| count >= cli.min_count)
        .collect();

    // Tri selon l'option choisie
    let mut results = filtered;
    match cli.sort {
        SortOrder::Alphabetical => {
            // Le BTreeMap garantit déjà l'ordre lexicographique par clé
        }
        SortOrder::Frequency => {
            // Tri par fréquence décroissante, puis par ordre alphabétique en cas d'égalité
            results.sort_by(|(key_a, count_a), (key_b, count_b)| {
                count_b.cmp(count_a).then_with(|| key_a.cmp(key_b))
            });
        }
    }

    // Limitation du nombre d'affichages
    let display_limit = if cli.top > 0 {
        cli.top.min(results.len())
    } else {
        results.len()
    };

    println!(
        "Total de {}-grammes répertoriés : {} (uniques : {}, affichés : {})",
        cli.ngram_size,
        total_tokens,
        freq_map.len(),
        display_limit
    );
    println!("{:-<60}", "");
    println!("{:<45} | {:>10}", "N-GRAMME", "FRÉQUENCE");
    println!("{:-<60}", "");

    for (item, count) in results.into_iter().take(display_limit) {
        println!("{:<45} | {:>10}", item, count);
    }

    Ok(())
}

