mod tests {
    use super::*;
    use std::io::Cursor;

    #[test]
    fn test_word_frequencies_case_insensitive() {
        // "Le chat et le chien. Le chat dort." -> 8 mots au total
        let text = "Le chat et le chien. Le chat dort.";
        let reader = Cursor::new(text);
        let (stats, total) = count_ngrams(reader, 1, false).expect("Erreur de calcul");

        assert_eq!(total, 8);
        assert_eq!(stats.get("le"), Some(&3));
        assert_eq!(stats.get("chat"), Some(&2));
        assert_eq!(stats.get("et"), Some(&1));
        assert_eq!(stats.get("chien"), Some(&1));
        assert_eq!(stats.get("dort"), Some(&1));

        // Vérification du tri lexicographique naturel de BTreeMap
        let keys: Vec<&String> = stats.keys().collect();
        assert_eq!(keys, vec!["chat", "chien", "dort", "et", "le"]);
    }

    #[test]
    fn test_bigrams() {
        let text = "pomme poire pomme poire pomme";
        let reader = Cursor::new(text);
        let (stats, total) = count_ngrams(reader, 2, false).expect("Erreur de calcul");

        assert_eq!(total, 4);
        assert_eq!(stats.get("pomme poire"), Some(&2));
        assert_eq!(stats.get("poire pomme"), Some(&2));
    }
}

