// src/main.rs
use std::fs::File;
use std::io::{self, Read, Write};
use std::net::{SocketAddr, ToSocketAddrs, UdpSocket};
use std::path::{Path, PathBuf};
use std::time::Duration;

use clap::{Parser, Subcommand, ValueEnum};
use thiserror::Error;

/// Taille maximale du bloc de données TFTP (RFC 1350)
pub const BLOCK_SIZE: usize = 512;
/// Taille maximale standard d'un paquet TFTP (Opcode + Block + 512 octets de données)
pub const MAX_PACKET_SIZE: usize = 4 + BLOCK_SIZE;

/// Codes d'opérations TFTP (RFC 1350)
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u16)]
pub enum Opcode {
    Rrq = 1,
    Wrq = 2,
    Data = 3,
    Ack = 4,
    Error = 5,
}

impl TryFrom<u16> for Opcode {
    type Error = TftpError;

    fn try_from(value: u16) -> Result<Self, TftpError> {
        match value {
            1 => Ok(Opcode::Rrq),
            2 => Ok(Opcode::Wrq),
            3 => Ok(Opcode::Data),
            4 => Ok(Opcode::Ack),
            5 => Ok(Opcode::Error),
            other => Err(TftpError::InvalidOpcode(other)),
        }
    }
}

/// Codes d'erreurs standard TFTP (RFC 1350)
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u16)]
pub enum ErrorCode {
    NotDefined = 0,
    FileNotFound = 1,
    AccessViolation = 2,
    DiskFull = 3,
    IllegalOperation = 4,
    UnknownTransferId = 5,
    FileAlreadyExists = 6,
    NoSuchUser = 7,
}

impl From<u16> for ErrorCode {
    fn from(val: u16) -> Self {
        match val {
            1 => ErrorCode::FileNotFound,
            2 => ErrorCode::AccessViolation,
            3 => ErrorCode::DiskFull,
            4 => ErrorCode::IllegalOperation,
            5 => ErrorCode::UnknownTransferId,
            6 => ErrorCode::FileAlreadyExists,
            7 => ErrorCode::NoSuchUser,
            _ => ErrorCode::NotDefined,
        }
    }
}

/// Mode de transfert supporté par TFTP
#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
pub enum TransferMode {
    #[value(name = "octet")]
    Octet,
    #[value(name = "netascii")]
    Netascii,
}

impl TransferMode {
    pub fn as_str(&self) -> &'static str {
        match self {
            TransferMode::Octet => "octet",
            TransferMode::Netascii => "netascii",
        }
    }
}

/// Représentation des paquets TFTP
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Packet {
    Rrq {
        filename: String,
        mode: TransferMode,
    },
    Wrq {
        filename: String,
        mode: TransferMode,
    },
    Data {
        block: u16,
        data: Vec<u8>,
    },
    Ack {
        block: u16,
    },
    Error {
        code: ErrorCode,
        message: String,
    },
}

impl Packet {
    /// Sérialise le paquet TFTP en octets conformément à la RFC 1350
    pub fn serialize(&self) -> Vec<u8> {
        let mut buf = Vec::new();
        match self {
            Packet::Rrq { filename, mode } => {
                buf.extend_from_slice(&(Opcode::Rrq as u16).to_be_bytes());
                buf.extend_from_slice(filename.as_bytes());
                buf.push(0);
                buf.extend_from_slice(mode.as_str().as_bytes());
                buf.push(0);
            }
            Packet::Wrq { filename, mode } => {
                buf.extend_from_slice(&(Opcode::Wrq as u16).to_be_bytes());
                buf.extend_from_slice(filename.as_bytes());
                buf.push(0);
                buf.extend_from_slice(mode.as_str().as_bytes());
                buf.push(0);
            }
            Packet::Data { block, data } => {
                buf.extend_from_slice(&(Opcode::Data as u16).to_be_bytes());
                buf.extend_from_slice(&block.to_be_bytes());
                buf.extend_from_slice(data);
            }
            Packet::Ack { block } => {
                buf.extend_from_slice(&(Opcode::Ack as u16).to_be_bytes());
                buf.extend_from_slice(&block.to_be_bytes());
            }
            Packet::Error { code, message } => {
                buf.extend_from_slice(&(Opcode::Error as u16).to_be_bytes());
                buf.extend_from_slice(&(*code as u16).to_be_bytes());
                buf.extend_from_slice(message.as_bytes());
                buf.push(0);
            }
        }
        buf
    }

    /// Désérialise un paquet TFTP depuis un buffer d'octets brut
    pub fn deserialize(buf: &[u8]) -> Result<Self, TftpError> {
        if buf.len() < 4 {
            return Err(TftpError::PacketTooShort(buf.len()));
        }

        let opcode_val = u16::from_be_bytes([buf[0], buf[1]]);
        let opcode = Opcode::try_from(opcode_val)?;

        match opcode {
            Opcode::Rrq | Opcode::Wrq => {
                let rest = &buf[2..];
                let mut parts = rest.splitn(3, |&b| b == 0);

                let filename_bytes = parts.next().ok_or(TftpError::MalformedPacket)?;
                let mode_bytes = parts.next().ok_or(TftpError::MalformedPacket)?;

                let filename = String::from_utf8(filename_bytes.to_vec())
                    .map_err(|_| TftpError::InvalidString)?;
                let mode_str = String::from_utf8(mode_bytes.to_vec())
                    .map_err(|_| TftpError::InvalidString)?
                    .to_lowercase();

                let mode = match mode_str.as_str() {
                    "octet" | "binary" => TransferMode::Octet,
                    "netascii" => TransferMode::Netascii,
                    _ => return Err(TftpError::UnsupportedMode(mode_str)),
                };

                if opcode == Opcode::Rrq {
                    Ok(Packet::Rrq { filename, mode })
                } else {
                    Ok(Packet::Wrq { filename, mode })
                }
            }
            Opcode::Data => {
                let block = u16::from_be_bytes([buf[2], buf[3]]);
                let data = buf[4..].to_vec();
                if data.len() > BLOCK_SIZE {
                    return Err(TftpError::DataBlockTooLarge(data.len()));
                }
                Ok(Packet::Data { block, data })
            }
            Opcode::Ack => {
                let block = u16::from_be_bytes([buf[2], buf[3]]);
                Ok(Packet::Ack { block })
            }
            Opcode::Error => {
                let error_code_val = u16::from_be_bytes([buf[2], buf[3]]);
                let code = ErrorCode::from(error_code_val);

                let mut err_msg_bytes = &buf[4..];
                if let Some(pos) = err_msg_bytes.iter().position(|&b| b == 0) {
                    err_msg_bytes = &err_msg_bytes[..pos];
                }
                let message = String::from_utf8_lossy(err_msg_bytes).to_string();

                Ok(Packet::Error { code, message })
            }
        }
    }
}

/// Ensemble des erreurs rencontrées par le client TFTP
#[derive(Error, Debug)]
pub enum TftpError {
    #[error("Erreur I/O : {0}")]
    Io(#[from] io::Error),

    #[error("Opcode TFTP invalide : {0}")]
    InvalidOpcode(u16),

    #[error("Paquet trop court pour être valide : {0} octets")]
    PacketTooShort(usize),

    #[error("Paquet TFTP malformé")]
    MalformedPacket,

    #[error("Chaîne UTF-8 invalide dans le paquet")]
    InvalidString,

    #[error("Mode de transfert non supporté : '{0}'")]
    UnsupportedMode(String),

    #[error("Bloc de données trop grand : {0} octets (maximum 512)")]
    DataBlockTooLarge(usize),

    #[error("Erreur reçue du serveur TFTP [code {code:?}]: {message}")]
    ServerError { code: ErrorCode, message: String },

    #[error("Délai d'attente réseau expiré après {0} tentatives")]
    Timeout(usize),

    #[error("Numéro de bloc inattendu (attendu: {expected}, reçu: {actual})")]
    UnexpectedBlock { expected: u16, actual: u16 },

    #[error("Opcode inattendu dans ce contexte")]
    UnexpectedPacket,

    #[error("Impossible de résoudre l'adresse : {0}")]
    ResolutionFailed(String),
}

/// Configuration du client TFTP
#[derive(Debug, Clone)]
pub struct TftpConfig {
    pub server_addr: String,
    pub timeout: Duration,
    pub max_retries: usize,
    pub mode: TransferMode,
}

impl Default for TftpConfig {
    fn default() -> Self {
        Self {
            server_addr: "127.0.0.1:69".to_string(),
            timeout: Duration::from_secs(3),
            max_retries: 5,
            mode: TransferMode::Octet,
        }
    }
}

/// Client TFTP interactif
pub struct TftpClient {
    socket: UdpSocket,
    config: TftpConfig,
}

impl TftpClient {
    /// Crée et initialise un nouveau client TFTP
    pub fn new(config: TftpConfig) -> Result<Self, TftpError> {
        let socket = UdpSocket::bind("0.0.0.0:0")?;
        socket.set_read_timeout(Some(config.timeout))?;
        Ok(Self { socket, config })
    }

    /// Résout l'adresse cible en ajoutant le port 69 par défaut si nécessaire
    fn resolve_target_addr(&self) -> Result<SocketAddr, TftpError> {
        let target = if self.config.server_addr.contains(':') {
            self.config.server_addr.clone()
        } else {
            format!("{}:69", self.config.server_addr)
        };

        target
            .to_socket_addrs()
            .map_err(|_| TftpError::ResolutionFailed(target.clone()))?
            .next()
            .ok_or_else(|| TftpError::ResolutionFailed(target))
    }

    /// Télécharge un fichier distant (`RRQ`) et l'écrit localement
    pub fn get(&self, remote_file: &str, local_file: &Path) -> Result<usize, TftpError> {
        let initial_addr = self.resolve_target_addr()?;
        let mut server_tid: Option<SocketAddr> = None;

        let rrq_packet = Packet::Rrq {
            filename: remote_file.to_string(),
            mode: self.config.mode,
        };
        let rrq_raw = rrq_packet.serialize();

        let mut expected_block: u16 = 1;
        let mut total_bytes_received: usize = 0;
        let mut output_file = File::create(local_file)?;
        let mut rx_buf = [0u8; MAX_PACKET_SIZE];

        // Envoi initial de la RRQ
        self.socket.send_to(&rrq_raw, initial_addr)?;

        'transfer: loop {
            let mut retries = 0;
            let packet = loop {
                match self.socket.recv_from(&mut rx_buf) {
                    Ok((n, src)) => {
                        // Gestion du TID (RFC 1350)
                        if let Some(tid) = server_tid {
                            if src != tid {
                                // Paquet d'une source inconnue : renvoi d'une erreur 5
                                let err_pkt = Packet::Error {
                                    code: ErrorCode::UnknownTransferId,
                                    message: "Unknown transfer ID".to_string(),
                                };
                                let _ = self.socket.send_to(&err_pkt.serialize(), src);
                                continue;
                            }
                        } else {
                            // Enregistrement du TID serveur
                            server_tid = Some(src);
                        }

                        match Packet::deserialize(&rx_buf[..n]) {
                            Ok(pkt) => break pkt,
                            Err(e) => {
                                eprintln!("Paquet ignoré car malformé : {e}");
                                continue;
                            }
                        }
                    }
                    Err(ref e) if e.kind() == io::ErrorKind::WouldBlock || e.kind() == io::ErrorKind::TimedOut => {
                        retries += 1;
                        if retries >= self.config.max_retries {
                            return Err(TftpError::Timeout(self.config.max_retries));
                        }

                        // Réémission selon l'état d'avancement
                        if expected_block == 1 {
                            self.socket.send_to(&rrq_raw, initial_addr)?;
                        } else if let Some(tid) = server_tid {
                            let last_ack = Packet::Ack {
                                block: expected_block.wrapping_sub(1),
                            };
                            self.socket.send_to(&last_ack.serialize(), tid)?;
                        }
                    }
                    Err(e) => return Err(TftpError::Io(e)),
                }
            };

            match packet {
                Packet::Data { block, data } => {
                    if block == expected_block {
                        output_file.write_all(&data)?;
                        total_bytes_received += data.len();

                        // Envoi de l'ACK correspondant
                        let ack_pkt = Packet::Ack { block };
                        let tid = server_tid.ok_or(TftpError::UnexpectedPacket)?;
                        self.socket.send_to(&ack_pkt.serialize(), tid)?;

                        let is_last_block = data.len() < BLOCK_SIZE;
                        expected_block = expected_block.wrapping_add(1);

                        if is_last_block {
                            break 'transfer;
                        }
                    } else if block == expected_block.wrapping_sub(1) {
                        // Acquittement perdu : réacquitter le bloc précédent
                        let ack_pkt = Packet::Ack { block };
                        if let Some(tid) = server_tid {
                            self.socket.send_to(&ack_pkt.serialize(), tid)?;
                        }
                    }
                }
                Packet::Error { code, message } => {
                    return Err(TftpError::ServerError { code, message });
                }
                _ => return Err(TftpError::UnexpectedPacket),
            }
        }

        output_file.flush()?;
        Ok(total_bytes_received)
    }

    /// Téléverse un fichier local (`WRQ`) vers le serveur distant
    pub fn put(&self, local_file: &Path, remote_file: &str) -> Result<usize, TftpError> {
        let initial_addr = self.resolve_target_addr()?;

        let wrq_packet = Packet::Wrq {
            filename: remote_file.to_string(),
            mode: self.config.mode,
        };
        let wrq_raw = wrq_packet.serialize();

        let mut file = File::open(local_file)?;
        let mut file_buf = Vec::new();
        file.read_to_end(&mut file_buf)?;

        let total_bytes = file_buf.len();
        let chunks: Vec<&[u8]> = file_buf.chunks(BLOCK_SIZE).collect();
        let total_blocks = chunks.len();

        let mut rx_buf = [0u8; MAX_PACKET_SIZE];

        // 1. Initialisation WRQ et attente de l'ACK 0
        let mut retries = 0;
        self.socket.send_to(&wrq_raw, initial_addr)?;

        let tid = loop {
            match self.socket.recv_from(&mut rx_buf) {
                Ok((n, src)) => {
                    match Packet::deserialize(&rx_buf[..n]) {
                        Ok(Packet::Ack { block: 0 }) => {
                            break src;
                        }
                        Ok(Packet::Error { code, message }) => {
                            return Err(TftpError::ServerError { code, message });
                        }
                        Ok(_) => continue,
                        Err(e) => {
                            eprintln!("Paquet malformé ignoré : {e}");
                            continue;
                        }
                    }
                }
                Err(ref e) if e.kind() == io::ErrorKind::WouldBlock || e.kind() == io::ErrorKind::TimedOut => {
                    retries += 1;
                    if retries >= self.config.max_retries {
                        return Err(TftpError::Timeout(self.config.max_retries));
                    }
                    self.socket.send_to(&wrq_raw, initial_addr)?;
                }
                Err(e) => return Err(TftpError::Io(e)),
            }
        };

        // 2. Envoi séquentiel des blocs de données
        let mut block_num: u16 = 1;
        let mut chunk_idx = 0;

        loop {
            let data_slice = if chunk_idx < total_blocks {
                chunks[chunk_idx]
            } else {
                &[] // Bloc vide final si la taille du fichier est un multiple exact de 512
            };

            let data_pkt = Packet::Data {
                block: block_num,
                data: data_slice.to_vec(),
            };
            let raw_data = data_pkt.serialize();

            let mut chunk_retries = 0;
            self.socket.send_to(&raw_data, tid)?;

            // Attente de l'ACK pour le bloc courant
            loop {
                match self.socket.recv_from(&mut rx_buf) {
                    Ok((n, src)) => {
                        if src != tid {
                            let err_pkt = Packet::Error {
                                code: ErrorCode::UnknownTransferId,
                                message: "Unknown transfer ID".to_string(),
                            };
                            let _ = self.socket.send_to(&err_pkt.serialize(), src);
                            continue;
                        }

                        match Packet::deserialize(&rx_buf[..n]) {
                            Ok(Packet::Ack { block }) => {
                                if block == block_num {
                                    break;
                                }
                            }
                            Ok(Packet::Error { code, message }) => {
                                return Err(TftpError::ServerError { code, message });
                            }
                            _ => {}
                        }
                    }
                    Err(ref e) if e.kind() == io::ErrorKind::WouldBlock || e.kind() == io::ErrorKind::TimedOut => {
                        chunk_retries += 1;
                        if chunk_retries >= self.config.max_retries {
                            return Err(TftpError::Timeout(self.config.max_retries));
                        }
                        self.socket.send_to(&raw_data, tid)?;
                    }
                    Err(e) => return Err(TftpError::Io(e)),
                }
            }

            let was_last = data_slice.len() < BLOCK_SIZE;
            chunk_idx += 1;
            block_num = block_num.wrapping_add(1);

            if was_last {
                break;
            }
        }

        Ok(total_bytes)
    }
}

/// Interface CLI pour le client TFTP
#[derive(Parser, Debug)]
#[command(name = "tftp-client", version, about = "Client TFTP (RFC 1350) complet en UDP", long_about = None)]
struct Cli {
    /// Adresse du serveur TFTP (ex: 127.0.0.1 ou 192.168.1.1:69)
    #[arg(short = 's', long = "server", default_value = "127.0.0.1:69")]
    server: String,

    /// Délai d'attente (timeout) en secondes par paquet
    #[arg(short = 't', long = "timeout", default_value_t = 3)]
    timeout_secs: u64,

    /// Nombre maximal de tentatives de réémission
    #[arg(short = 'r', long = "retries", default_value_t = 5)]
    retries: usize,

    /// Mode de transfert ('octet' pour binaire ou 'netascii')
    #[arg(short = 'm', long = "mode", value_enum, default_value_t = TransferMode::Octet)]
    mode: TransferMode,

    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Récupérer un fichier distant (RRQ)
    Get {
        /// Nom du fichier distant à télécharger
        remote: String,

        /// Chemin de destination local (optionnel, nom du fichier par défaut)
        local: Option<PathBuf>,
    },
    /// Téléverser un fichier local (WRQ)
    Put {
        /// Chemin du fichier local à téléverser
        local: PathBuf,

        /// Nom du fichier cible sur le serveur (optionnel, nom d'origine par défaut)
        remote: Option<String>,
    },
}

fn main() {
    let args = Cli::parse();

    let config = TftpConfig {
        server_addr: args.server,
        timeout: Duration::from_secs(args.timeout_secs),
        max_retries: args.retries,
        mode: args.mode,
    };

    let client = match TftpClient::new(config) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Erreur lors de l'initialisation du socket UDP : {e}");
            std::process::exit(1);
        }
    };

    match args.command {
        Commands::Get { remote, local } => {
            let local_path = local.unwrap_or_else(|| PathBuf::from(&remote));
            println!("Téléchargement de '{remote}' vers '{}'...", local_path.display());

            match client.get(&remote, &local_path) {
                Ok(bytes) => {
                    println!("Téléchargement réussi : {bytes} octets reçus.");
                }
                Err(e) => {
                    eprintln!("Échec du téléchargement : {e}");
                    std::process::exit(1);
                }
            }
        }
        Commands::Put { local, remote } => {
            if !local.exists() {
                eprintln!("Erreur : Le fichier local '{}' n'existe pas.", local.display());
                std::process::exit(1);
            }

            let remote_name = remote.unwrap_or_else(|| {
                local
                    .file_name()
                    .and_then(|n| n.to_str())
                    .unwrap_or("file.dat")
                    .to_string()
            });

            println!("Téléversement de '{}' vers '{remote_name}'...", local.display());

            match client.put(&local, &remote_name) {
                Ok(bytes) => {
                    println!("Téléversement réussi : {bytes} octets envoyés.");
                }
                Err(e) => {
                    eprintln!("Échec du téléversement : {e}");
                    std::process::exit(1);
                }
            }
        }
    }
}

