```rust
// src/main.rs
use std::fmt;
use std::iter::FromIterator;
use std::mem::MaybeUninit;
use std::ops::{Deref, DerefMut};
use std::ptr;

/// Données internes du `SmallVec`.
enum SmallVecData<T, const N: usize> {
    /// Stockage inline alloué sur la pile dans un tableau de mémoire non-initialisée.
    Inline {
        buffer: [MaybeUninit<T>; N],
        len: usize,
    },
    /// Stockage alloué dynamiquement sur le tas une fois la capacité $N$ dépassée.
    Heap(Vec<T>),
}

/// Conteneur vectoriel optimisé allouant sur la pile jusqu'à `N` éléments,
/// puis basculant de façon transparente sur le tas (`Vec<T>`).
pub struct SmallVec<T, const N: usize> {
    data: SmallVecData<T, N>,
}

impl<T, const N: usize> SmallVec<T, N> {
    /// Crée un nouveau `SmallVec` vide alloué sur la pile.
    #[inline]
    #[must_use]
    pub const fn new() -> Self {
        // Sécurisé : MaybeUninit::uninit_array() n'est pas encore stabilisé partout,
        // l'équivalent idiomatique garanti est un `MaybeUninit::uninit().assume_init()`.
        let buffer: [MaybeUninit<T>; N] = unsafe { MaybeUninit::uninit().assume_init() };
        Self {
            data: SmallVecData::Inline { buffer, len: 0 },
        }
    }

    /// Crée un `SmallVec` avec une capacité prédéterminée.
    /// Si `capacity <= N`, aucun débordement sur le tas n'a lieu.
    #[must_use]
    pub fn with_capacity(capacity: usize) -> Self {
        if capacity <= N {
            Self::new()
        } else {
            Self {
                data: SmallVecData::Heap(Vec::with_capacity(capacity)),
            }
        }
    }

    /// Retourne le nombre d'éléments contenus dans la structure.
    #[inline]
    pub fn len(&self) -> usize {
        match &self.data {
            SmallVecData::Inline { len, .. } => *len,
            SmallVecData::Heap(vec) => vec.len(),
        }
    }

    /// Indique si la collection est vide.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// Retourne la capacité actuelle sans réallocation.
    #[inline]
    pub fn capacity(&self) -> usize {
        match &self.data {
            SmallVecData::Inline { .. } => N,
            SmallVecData::Heap(vec) => vec.capacity(),
        }
    }

    /// Indique si la collection a basculé sur le tas (spilled).
    #[inline]
    pub fn is_spilled(&self) -> bool {
        matches!(self.data, SmallVecData::Heap(_))
    }

    /// Fait basculer la structure du mode inline vers le mode heap avec une capacité minimale demandée.
    fn spill_to_heap(&mut self, target_capacity: usize) {
        if let SmallVecData::Inline { buffer, len } = &mut self.data {
            let current_len = *len;
            let new_cap = target_capacity.max(current_len * 2).max(1);
            let mut new_vec = Vec::with_capacity(new_cap);

            // Déplace de manière sécurisée les éléments initialisés de la pile vers le heap
            unsafe {
                let src = buffer.as_mut_ptr() as *mut T;
                let dst = new_vec.as_mut_ptr();
                ptr::copy_nonoverlapping(src, dst, current_len);
                new_vec.set_len(current_len);
                // On met à 0 pour éviter tout risque de drop résiduel
                *len = 0;
            }

            self.data = SmallVecData::Heap(new_vec);
        }
    }

    /// Ajoute un élément à la fin du conteneur.
    pub fn push(&mut self, value: T) {
        match &mut self.data {
            SmallVecData::Inline { buffer, len } => {
                if *len < N {
                    unsafe {
                        buffer[*len].as_mut_ptr().write(value);
                    }
                    *len += 1;
                } else {
                    self.spill_to_heap(N + 1);
                    if let SmallVecData::Heap(vec) = &mut self.data {
                        vec.push(value);
                    }
                }
            }
            SmallVecData::Heap(vec) => {
                vec.push(value);
            }
        }
    }

    /// Retire et renvoie le dernier élément s'il existe.
    pub fn pop(&mut self) -> Option<T> {
        match &mut self.data {
            SmallVecData::Inline { buffer, len } => {
                if *len == 0 {
                    None
                } else {
                    *len -= 1;
                    let val = unsafe { buffer[*len].as_ptr().read() };
                    Some(val)
                }
            }
            SmallVecData::Heap(vec) => vec.pop(),
        }
    }

    /// Insère un élément à la position `index`.
    ///
    /// # Panics
    /// Panique si `index > len`.
    pub fn insert(&mut self, index: usize, value: T) {
