                }
            }
            // Empêche le drop interne de SmallVec de tenter un re-drop
            *len = 0;
        }
    }
}

impl<T, const N: usize> IntoIterator for SmallVec<T, N> {
    type Item = T;
    type IntoIter = IntoIter<T, N>;

    #[inline]
    fn into_iter(self) -> Self::IntoIter {
        IntoIter {
            inner: self,
            index: 0,
        }
    }
}

impl<'a, T, const N: usize> IntoIterator for &'a SmallVec<T, N> {
    type Item = &'a T;
    type IntoIter = std::slice::Iter<'a, T>;

    #[inline]
    fn into_iter(self) -> Self::IntoIter {
        self.iter()
    }
}

impl<'a, T, const N: usize> IntoIterator for &'a mut SmallVec<T, N> {
    type Item = &'a mut T;
    type IntoIter = std::slice::IterMut<'a, T>;

    #[inline]
    fn into_iter(self) -> Self::IntoIter {
        self.iter_mut()
    }
}

fn main() {
    println!("=== Démonstration du conteneur SmallVec<T, N> ===\n");

    // Capacité inline de 4 éléments
    let mut vec: SmallVec<String, 4> = SmallVec::new();
    println!("Initialisation : len = {}, cap = {}, is_spilled = {}", vec.len(), vec.capacity(), vec.is_spilled());

    // Remplissage pile (<= 4)
    for i in 1..=4 {
        vec.push(format!("Elément #{i}"));
        println!("+ Push '{}' -> len = {}, cap = {}, is_spilled = {}", vec[vec.len() - 1], vec.len(), vec.capacity(), vec.is_spilled());
    }

    assert!(!vec.is_spilled(), "Le vecteur ne doit pas encore avoir basculé sur le tas");

    // Débordement sur le tas (> 4)
    println!("\nInsertion provoquant le basculement sur le tas...");
    vec.push(String::from("Elément #5 (Heap)"));
    println!("Après débordement -> len = {}, cap = {}, is_spilled = {}", vec.len(), vec.capacity(), vec.is_spilled());
    assert!(vec.is_spilled(), "Le vecteur doit désormais être alloué sur le tas");

    // Opérations d'insertion et suppression
    println!("\nInsertion à l'index 2...");
    vec.insert(2, String::from("Elément Intermédiaire"));
    println!("Contenu actuel : {:?}", vec);

    println!("\nSuppression à l'index 0...");
    let removed = vec.remove(0);
    println!("Retiré : '{}' | Reste : {:?}", removed, vec);

    // Manipulation via Deref de tranche ([T])
    println!("\nTranches et itération par référence :");
    for (idx, val) in vec.iter().enumerate() {
        println!("  [{idx}] => {val}");
    }

    // Dépilement
    println!("\nDépilement (pop) :");
    while let Some(item) = vec.pop() {
        println!("  Popped: {item} (éléments restants: {})", vec.len());
    }

    // Test avec Drop personnalisé pour vérifier l'absence de fuite ou double-free
    println!("\nValidation du Drop personnalisé :");
    {
        use std::sync::atomic::{AtomicUsize, Ordering};
        static DROP_COUNTER: AtomicUsize = AtomicUsize::new(0);

        struct Tracker<'a>(&'a str);
        impl<'a> Drop for Tracker<'a> {
            fn drop(&mut self) {
                DROP_COUNTER.fetch_add(1, Ordering::SeqCst);
                println!("  Drop tracker : {}", self.0);
            }
        }

        {
            let mut stack_sv: SmallVec<Tracker, 3> = SmallVec::new();
            stack_sv.push(Tracker("Alpha"));
            stack_sv.push(Tracker("Beta"));
            println!("  Fin du scope local de 2 éléments inline...");
        }
        println!("  Trackers libérés : {}", DROP_COUNTER.load(Ordering::SeqCst));
    }

    println!("\nExécution terminée avec succès !");
}

