// src/main.rs
//! Serveur proxy inverse TCP transparent.
//!
//! Redirige les flux d'octets bidirectionnellement entre des clients
//! entrants et un serveur cible distant à l'aide de `std::io::copy`.

use clap::Parser;
use log::{error, info, warn};
use std::io;
use std::net::{Shutdown, SocketAddr, TcpListener, TcpStream, ToSocketAddrs};
use std::sync::Arc;
use std::thread;

/// Configuration du proxy inverse TCP via les arguments CLI.
#[derive(Parser, Debug)]
#[command(
    name = "tcp-reverse-proxy",
    about = "Serveur proxy inverse TCP transparent avec std::io::copy bidirectionnel",
    version
)]
pub struct Config {
    /// Adresse locale d'écoute du proxy (ex: 0.0.0.0:8080 ou 127.0.0.1:8080)
    #[arg(
        short = 'b',
        long = "bind",
        default_value = "127.0.0.1:8080",
        env = "PROXY_BIND_ADDR"
    )]
    pub bind_addr: String,

    /// Adresse de destination cible vers laquelle relayer le trafic (ex: 127.0.0.1:9000 ou example.com:80)
    #[arg(
        short = 't',
        long = "target",
        default_value = "127.0.0.1:9000",
        env = "PROXY_TARGET_ADDR"
    )]
    pub target_addr: String,
}

/// Résout une adresse cible en `SocketAddr`.
fn resolve_target_addr(target: &str) -> io::Result<SocketAddr> {
    target
        .to_socket_addrs()?
        .next()
        .ok_or_else(|| io::Error::new(io::ErrorKind::NotFound, "Impossible de résoudre l'adresse cible"))
}

/// Relaye le flux d'octets de `reader` vers `writer`, puis envoie un signal `Shutdown::Write` à la cible.
fn copy_and_shutdown(
    mut reader: TcpStream,
    mut writer: TcpStream,
    direction: &'static str,
) -> io::Result<u64> {
    let bytes_copied = io::copy(&mut reader, &mut writer)?;
    // Envoi propre de EOF sur le canal d'écriture
    if let Err(e) = writer.shutdown(Shutdown::Write) {
        // Ignorer l'erreur si la socket est déjà fermée ou déconnectée
        if e.kind() != io::ErrorKind::NotConnected {
            warn!("Erreur lors du shutdown(Write) pour {}: {}", direction, e);
        }
    }
    Ok(bytes_copied)
}

/// Gère le cycle de vie d'une connexion client en la relayant vers la cible distante.
fn handle_connection(client_stream: TcpStream, client_addr: SocketAddr, target: Arc<String>) {
    let target_socket = match resolve_target_addr(&target) {
        Ok(addr) => addr,
        Err(e) => {
            error!(
                "[{}] Impossible de résoudre l'adresse cible '{}': {}",
                client_addr, target, e
            );
            return;
        }
    };

    info!(
        "[{}] Connexion vers la cible distante {}...",
        client_addr, target_socket
    );

    let target_stream = match TcpStream::connect(target_socket) {
        Ok(stream) => stream,
        Err(e) => {
            error!(
                "[{}] Échec de connexion vers la cible {}: {}",
                client_addr, target_socket, e
            );
            return;
        }
    };

    // Configuration des sockets (NoDelay pour réduire la latence sur flux interactifs)
    let _ = client_stream.set_nodelay(true);
    let _ = target_stream.set_nodelay(true);

    // Duplication des descripteurs pour permettre les lectures/écritures concurrentes
    let client_reader = match client_stream.try_clone() {
        Ok(s) => s,
        Err(e) => {
            error!("[{}] Échec de clonage de la socket client: {}", client_addr, e);
            return;
        }
    };
    let client_writer = client_stream;

    let target_reader = match target_stream.try_clone() {
        Ok(s) => s,
        Err(e) => {
            error!("[{}] Échec de clonage de la socket cible: {}", client_addr, e);
            return;
        }
    };
    let target_writer = target_stream;

    // Thread 1: Client -> Cible
    let client_to_target_handle = thread::spawn(move || {
        copy_and_shutdown(client_reader, target_writer, "Client -> Cible")
    });

    // Thread 2 (actuel) : Cible -> Client
    let target_to_client_res = copy_and_shutdown(target_reader, client_writer, "Cible -> Client");

    let client_to_target_res = match client_to_target_handle.join() {
        Ok(res) => res,
        Err(_) => Err(io::Error::new(
            io::ErrorKind::Other,
            "Le thread Client -> Cible a paniqué",
        )),
    };

    match (client_to_target_res, target_to_client_res) {
        (Ok(up), Ok(down)) => {
            info!(
                "[{}] Connexion terminée proprement. Transféré : {} octets envoyés, {} octets reçus.",
                client_addr, up, down
            );
        }
        (Err(e_up), Ok(down)) => {
            warn!(
                "[{}] Fin avec erreur montante ({}) - Reçus : {} octets.",
                client_addr, e_up, down
            );
        }
        (Ok(up), Err(e_down)) => {
            warn!(
                "[{}] Fin avec erreur descendante ({}) - Envoyés : {} octets.",
                client_addr, e_down, up
            );
        }
        (Err(e_up), Err(e_down)) => {
            warn!(
                "[{}] Fin avec erreurs bidirectionnelles (up: {}, down: {}).",
                client_addr, e_up, e_down
            );
        }
    }
}

fn main() -> io::Result<()> {
    // Initialisation du logger avec niveau INFO par défaut
    env_logger::Builder::from_env(env_logger::Env::default().default_filter_or("info")).init();

    let config = Config::parse();
    let bind_addr = config.bind_addr;
    let target_addr = Arc::new(config.target_addr);

    let listener = TcpListener::bind(&bind_addr).map_err(|e| {
        error!("Impossible de lier le listener TCP sur {}: {}", bind_addr, e);
        e
    })?;

    info!(
        "Serveur proxy inverse démarré sur {} -> relai vers {}",
        bind_addr, target_addr
    );

    for incoming in listener.incoming() {
        match incoming {
            Ok(client_stream) => match client_stream.peer_addr() {
                Ok(client_addr) => {
                    info!("[{}] Nouvelle connexion entrante acceptée.", client_addr);
                    let target = Arc::clone(&target_addr);
                    thread::spawn(move || {
                        handle_connection(client_stream, client_addr, target);
                    });
                }
                Err(e) => {
                    warn!("Impossible d'obtenir l'adresse du pair client: {}", e);
                }
            },
            Err(e) => {
                warn!("Échec lors de l'acceptation d'une connexion: {}", e);
            }
        }
    }

    Ok(())
}

