                let mut buf = [0u8; 1024];
                while let Ok(n) = stream.read(&mut buf) {
                    if n == 0 {
                        break;
                    }
                    if stream.write_all(&buf[..n]).is_err() {
                        break;
                    }
                }
            }
        });

        // 2. Démarrer le proxy sur un port éphémère
        let proxy_listener = TcpListener::bind("127.0.0.1:0").expect("bind proxy listener");
        let proxy_addr = proxy_listener.local_addr().expect("proxy addr");
        let target_addr_str = Arc::new(target_addr.to_string());

        thread::spawn(move || {
            if let Ok((client_stream, client_addr)) = proxy_listener.accept() {
                handle_connection(client_stream, client_addr, target_addr_str);
            }
        });

        // 3. Connecter un client au proxy et échanger des données
        let mut client = TcpStream::connect(proxy_addr).expect("connect to proxy");
        client
            .set_read_timeout(Some(Duration::from_secs(3)))
            .expect("set read timeout");

        let msg = b"ping transparent reverse proxy";
        client.write_all(msg).expect("write to proxy");

        let mut reply = vec![0u8; msg.len()];
        client.read_exact(&mut reply).expect("read from proxy");
        assert_eq!(&reply[..], &msg[..]);

        // Vérifier la fermeture propre
        drop(client);
    }
}


