// src/main.rs
use clap::Parser;
use colored::*;
use std::fs::{self, DirEntry, Metadata};
use std::io;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};

#[derive(Parser, Debug)]
#[command(
    name = "tree-rs",
    author,
    version,
    about = "CLI d'affichage de l'arborescence façon tree avec métadonnées Unix"
)]
struct Cli {
    /// Chemin du répertoire racine
    #[arg(default_value = ".")]
    path: PathBuf,

    /// Profondeur maximale d'exploration
    #[arg(short = 'L', long = "max-depth")]
    max_depth: Option<usize>,

    /// Afficher tous les fichiers, y compris les fichiers cachés
    #[arg(short = 'a', long = "all")]
    all: bool,

    /// Afficher uniquement les répertoires
    #[arg(short = 'd', long = "dirs-only")]
    dirs_only: bool,

    /// Ne pas afficher les métadonnées de permissions
    #[arg(long = "no-perms")]
    no_perms: bool,

    /// Désactiver les couleurs dans la sortie
    #[arg(long = "no-color")]
    no_color: bool,
}

#[derive(Default)]
struct Stats {
    dirs: usize,
    files: usize,
}

/// Convertit le mode Unix (32-bit uint) et le type de fichier en chaîne de type standard "drwxr-xr-x"
fn format_permissions(mode: u32, file_type: fs::FileType) -> String {
    let type_char = if file_type.is_dir() {
        'd'
    } else if file_type.is_symlink() {
        'l'
    } else {
        // Détection de socket, pipe FIFO, bloc, char device via les bits de mode
        let s_fmt = mode & 0o170000;
        match s_fmt {
            0o010000 => 'p', // FIFO
            0o020000 => 'c', // Character device
            0o060000 => 'b', // Block device
            0o140000 => 's', // Socket
            _ => '-',        // Regular file
        }
    };

    let user_r = if mode & 0o400 != 0 { 'r' } else { '-' };
    let user_w = if mode & 0o200 != 0 { 'w' } else { '-' };
    let user_x = match (mode & 0o100 != 0, mode & 0o4000 != 0) {
        (true, true) => 's',
        (false, true) => 'S',
        (true, false) => 'x',
        (false, false) => '-',
    };

    let group_r = if mode & 0o040 != 0 { 'r' } else { '-' };
    let group_w = if mode & 0o020 != 0 { 'w' } else { '-' };
    let group_x = match (mode & 0o010 != 0, mode & 0o2000 != 0) {
        (true, true) => 's',
        (false, true) => 'S',
        (true, false) => 'x',
        (false, false) => '-',
    };

    let other_r = if mode & 0o004 != 0 { 'r' } else { '-' };
    let other_w = if mode & 0o002 != 0 { 'w' } else { '-' };
    let other_x = match (mode & 0o001 != 0, mode & 0o1000 != 0) {
        (true, true) => 't',
        (false, true) => 'T',
        (true, false) => 'x',
        (false, false) => '-',
    };

    format!(
        "{}{}{}{}{}{}{}{}{}{}",
        type_char, user_r, user_w, user_x, group_r, group_w, group_x, other_r, other_w, other_x
    )
}

/// Formate la taille en octets de façon lisible
fn format_size(size: u64) -> String {
    const UNITS: [&str; 5] = ["B", "K", "M", "G", "T"];
    let mut s = size as f64;
    let mut unit_idx = 0;

    while s >= 1024.0 && unit_idx < UNITS.len() - 1 {
        s /= 1024.0;
        unit_idx += 1;
    }

    if unit_idx == 0 {
        format!("{:>4}B", size)
    } else {
        format!("{:>4.1}{}", s, UNITS[unit_idx])
    }
}

/// Extrait et formate les informations de métadonnées Unix
fn format_metadata(meta: &Metadata) -> String {
    let mode = meta.mode();
    let file_type = meta.file_type();
    let perms_str = format_permissions(mode, file_type);
    let uid = meta.uid();
    let gid = meta.gid();
    let size_str = format_size(meta.size());

    format!("[{} {:>4}:{:>4} {}]", perms_str, uid, gid, size_str)
}

fn print_entry(
    name: &str,
    prefix: &str,
    is_last: bool,
    metadata: Option<&Metadata>,
    symlink_target: Option<&Path>,
    is_dir: bool,
    show_perms: bool,
) {
    let branch = if is_last {
        "└── "
    } else {
        "├── "
    };

    let meta_display = if show_perms {
        if let Some(m) = metadata {
            let meta_formatted = format_metadata(m);
            format!("{} ", meta_formatted.dimmed())
        } else {
            "[??????????] ".dimmed().to_string()
        }
    } else {
        String::new()
    };

    let name_colored = if is_dir {
        name.blue().bold()
    } else if let Some(target) = symlink_target {
        let arrow = "->".cyan();
        let target_str = target.to_string_lossy();
        return println!(
            "{}{}{}{} {} {}",
            meta_display,
            prefix,
            branch,
            name.cyan().bold(),
            arrow,
            target_str.italic()
        );
    } else if let Some(m) = metadata {
        if m.mode() & 0o111 != 0 {
            name.green().bold()
        } else {
            name.normal()
        }
    } else {
        name.normal()
    };

    println!("{}{}{}{}", meta_display, prefix, branch, name_colored);
}

fn visit_dir(
    dir: &Path,
    prefix: &str,
    current_depth: usize,
    cli: &Cli,
    stats: &mut Stats,
) -> io::Result<()> {
    if let Some(max) = cli.max_depth {
        if current_depth > max {
            return Ok(());
        }
    }

    let read_dir = match fs::read_dir(dir) {
        Ok(rd) => rd,
        Err(e) => {
            eprintln!("{}[Permission refusée: {}]", prefix, e);
            return Ok(());
        }
    };

    let mut entries: Vec<DirEntry> = Vec::new();
    for entry in read_dir {
        match entry {
            Ok(e) => {
                let file_name = e.file_name();
                let name = file_name.to_string_lossy();

                if !cli.all && name.starts_with('.') {
                    continue;
                }

                if cli.dirs_only {
                    if let Ok(ft) = e.file_type() {
                        if !ft.is_dir() {
                            continue;
                        }
                    }
                }

                entries.push(e);
            }
            Err(e) => {
                eprintln!("{}[Erreur de lecture d'entrée: {}]", prefix, e);
            }
        }
    }

    // Tri alphabétique insensible à la casse
    entries.sort_by(|a, b| {
        a.file_name()
            .to_string_lossy()
            .to_lowercase()
            .cmp(&b.file_name().to_string_lossy().to_lowercase())
    });

    let total = entries.len();
    for (i, entry) in entries.iter().enumerate() {
        let is_last = i == total - 1;
        let file_name = entry.file_name();
        let name = file_name.to_string_lossy();
        let path = entry.path();

        // Obtient les métadonnées (symlink_metadata pour ne pas déréférencer les liens)
        let metadata = entry.metadata().ok();
        let symlink_metadata = fs::symlink_metadata(&path).ok();
        let meta_for_display = symlink_metadata.as_ref().or(metadata.as_ref());

        let file_type = entry.file_type().ok();
        let is_dir = file_type.as_ref().map_or(false, |ft| ft.is_dir());
        let is_symlink = file_type.as_ref().map_or(false, |ft| ft.is_symlink());

        let symlink_target = if is_symlink {
            fs::read_link(&path).ok()
        } else {
            None
        };

        if is_dir {
            stats.dirs += 1;
        } else {
            stats.files += 1;
        }

        print_entry(
            &name,
            prefix,
            is_last,
            meta_for_display,
            symlink_target.as_deref(),
            is_dir,
            !cli.no_perms,
        );

        if is_dir {
            let next_prefix = if is_last {
                format!("{}    ", prefix)
            } else {
                format!("{}│   ", prefix)
            };

            let _ = visit_dir(&path, &next_prefix, current_depth + 1, cli, stats);
        }
    }

    Ok(())
}

fn main() {
    let cli = Cli::parse();

    if cli.no_color {
        colored::control::set_override(false);
    }

    let root_path = &cli.path;
    let root_meta = fs::symlink_metadata(root_path).ok();

    if !cli.no_perms {
        if let Some(ref m) = root_meta {
            print!("{} ", format_metadata(m).dimmed());
        }
    }
    println!("{}", root_path.display().to_string().bold());

    let mut stats = Stats::default();

    if let Err(e) = visit_dir(root_path, "", 1, &cli, &mut stats) {
        eprintln!("Erreur lors du parcours: {}", e);
        std::process::exit(1);
    }

    println!();
    if cli.dirs_only {
        println!(
            "{}",
            format!(
                "{} répertoire{}",
                stats.dirs,
                if stats.dirs > 1 { "s" } else { "" }
            )
            .bold()
        );
    } else {
        println!(
            "{}",
            format!(
                "{} répertoire{}, {} fichier{}",
                stats.dirs,
                if stats.dirs > 1 { "s" } else { "" },
                stats.files,
                if stats.files > 1 { "s" } else { "" }
            )
            .bold()
        );
    }
}

