// src/main.rs
use bigint_lib::{BigInt, ParseBigIntError};
use std::env;
use std::process;

fn print_usage(program_name: &str) {
    eprintln!("Usage: {program_name} <operande_1> <opérateur (+|*)> <operande_2>");
    eprintln!("Exemples :");
    eprintln!("  {program_name} 99999999999999999999 + 1");
    eprintln!("  {program_name} 123456789 '*' 987654321");
    eprintln!("  {program_name} demo");
}

fn run_demo() {
    println!("=== Démonstration de la bibliothèque BigInt ===");

    let str_a = "9876543210987654321098765432109876543210";
    let str_b = "1234567890123456789012345678901234567890";

    println!("Nombre A : {str_a}");
    println!("Nombre B : {str_b}");

    match (str_a.parse::<BigInt>(), str_b.parse::<BigInt>()) {
        (Ok(a), Ok(b)) => {
            let sum = &a + &b;
            let diff = &a - &b;
            let prod = &a * &b;

            println!("\nA + B =\n{sum}");
            println!("\nA - B =\n{diff}");
            println!("\nA * B =\n{prod}");
        }
        (Err(e), _) | (_, Err(e)) => {
            eprintln!("Erreur lors du parsing : {e}");
        }
    }

    println!("\n=== Calcul direct sur chaînes de caractères (add_str / mul_str) ===");
    match BigInt::add_str("999999999999999999999999999999", "1") {
        Ok(res) => println!("\"999...99\" + \"1\" = {res}"),
        Err(e) => eprintln!("Erreur : {e}"),
    }

    match BigInt::mul_str("-123456789", "987654321") {
        Ok(res) => println!("\"-123456789\" * \"987654321\" = {res}"),
        Err(e) => eprintln!("Erreur : {e}"),
    }
}

fn compute(s1: &str, op: &str, s2: &str) -> Result<String, ParseBigIntError> {
    let a: BigInt = s1.parse()?;
    let b: BigInt = s2.parse()?;

    match op {
        "+" => Ok((a + b).to_string()),
        "-" => Ok((a - b).to_string()),
        "*" | "x" | "X" => Ok((a * b).to_string()),
        other => {
            eprintln!("Opérateur non reconnu : '{other}'. Utilisez '+', '-' ou '*'.");
            process::exit(1);
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() == 2 && args[1] == "demo" {
        run_demo();
        return;
    }

    if args.len() != 4 {
        if args.len() == 1 {
            // Sans arguments, lancer la démonstration pour une exécution immédiate
            run_demo();
            return;
        }
        print_usage(&args[0]);
        process::exit(1);
    }

    let op1 = &args[1];
    let operator = &args[2];
    let op2 = &args[3];

    match compute(op1, operator, op2) {
        Ok(result) => {
            println!("{result}");
        }
