    /// Crée une nouvelle image avec un buffer pré-alloué initialisé à zéro
    pub fn new(width: usize, height: usize, max_val: u8) -> Self {
        let total_bytes = width.saturating_mul(height).saturating_mul(3);
        Self {
            width,
            height,
            max_val,
            data: vec![0u8; total_bytes],
        }
    }

    /// Charge une image PPM (P6 ou P3) depuis un fichier
    pub fn read_from_file<P: AsRef<Path>>(path: P) -> Result<Self, PpmError> {
        let file = File::open(path)?;
        let mut reader = BufReader::new(file);
        Self::read_from_reader(&mut reader)
    }

    /// Parse une image PPM depuis n'importe quel flux implémentant `BufRead + Read`
    pub fn read_from_reader<R: BufRead + Read>(reader: &mut R) -> Result<Self, PpmError> {
        let magic = read_next_token(reader)?
            .ok_or_else(|| PpmError::MalformedHeader("Fichier vide ou sans en-tête".into()))?;

        let is_p6 = match magic.as_str() {
            "P6" => true,
            "P3" => false,
            other => return Err(PpmError::UnsupportedFormat(other.to_string())),
        };

        let width_token = read_next_token(reader)?
            .ok_or_else(|| PpmError::MalformedHeader("Largeur manquante".into()))?;
        let width: usize = width_token
            .parse()
            .map_err(|_| PpmError::MalformedHeader(format!("Largeur invalide: {width_token}")))?;

        let height_token = read_next_token(reader)?
            .ok_or_else(|| PpmError::MalformedHeader("Hauteur manquante".into()))?;
        let height: usize = height_token
            .parse()
            .map_err(|_| PpmError::MalformedHeader(format!("Hauteur invalide: {height_token}")))?;

        let max_val_token = read_next_token(reader)?
            .ok_or_else(|| PpmError::MalformedHeader("Valeur max manquante".into()))?;
        let max_val_raw: u32 = max_val_token
            .parse()
            .map_err(|_| PpmError::MalformedHeader(format!("Valeur max invalide: {max_val_token}")))?;

        if max_val_raw != 255 {
            return Err(PpmError::UnsupportedMaxVal(max_val_raw));
        }
        let max_val = max_val_raw as u8;

        let expected_bytes = width
            .checked_mul(height)
            .and_then(|pixels| pixels.checked_mul(3))
            .ok_or_else(|| PpmError::MalformedHeader("Dimensions d'image trop grandes".into()))?;

        let mut data = Vec::with_capacity(expected_bytes);

        if is_p6 {
            // Dans le format P6, un unique caractère d'espacement (généralement \n) sépare l'en-tête des octets bruts
            // `read_next_token` a déjà consommé les délimiteurs blancs précédant max_val.
            // On doit maintenant consommer exactement un whitespace après max_val.
            let mut byte = [0u8; 1];
            reader.read_exact(&mut byte)?;
            if !byte[0].is_ascii_whitespace() {
                return Err(PpmError::MalformedHeader(
                    "Délimiteur d'espacement manquant après la valeur maximale".into(),
                ));
            }

            data.resize(expected_bytes, 0);
            reader.read_exact(&mut data).map_err(|e| {
                if e.kind() == io::ErrorKind::UnexpectedEof {
                    PpmError::UnexpectedEof
                } else {
                    PpmError::Io(e)
                }
            })?;
        } else {
            // Format P3 (ASCII)
            for _ in 0..expected_bytes {
                let token = read_next_token(reader)?
                    .ok_or(PpmError::UnexpectedEof)?;
                let sample: u8 = token.parse().map_err(|_| {
                    PpmError::MalformedHeader(format!("Échantillon de couleur invalide: {token}"))
                })?;
                data.push(sample);
            }
        }

        if data.len() != expected_bytes {
            return Err(PpmError::InvalidPixelData {
                expected: expected_bytes,
                actual: data.len(),
            });
        }

        Ok(Self {
            width,
            height,
            max_val,
            data,
        })
    }

    /// Écrit l'image courante au format PPM P6 (binaire compact)
    pub fn write_to_file<P: AsRef<Path>>(&self, path: P) -> Result<(), PpmError> {
        let file = File::create(path)?;
        let mut writer = BufWriter::new(file);
        self.write_to_writer(&mut writer)
    }

    /// Écrit l'image dans un flux d'écriture
    pub fn write_to_writer<W: Write>(&self, writer: &mut W) -> Result<(), PpmError> {
        // En-tête standard P6
        write!(writer, "P6\n{} {}\n{}\n", self.width, self.height, self.max_val)?;
        writer.write_all(&self.data)?;
        writer.flush()?;
        Ok(())
    }

    /// Convertit l'image en nuances de gris (norme ITU-R BT.601)
    pub fn to_grayscale(&mut self) {
        let (pixels, _) = self.data.as_chunks_mut::<3>();
        for pixel in pixels {
            let r = pixel[0] as f32;
            let g = pixel[1] as f32;
            let b = pixel[2] as f32;

            // Formule standard de luminance
            let gray = (0.299 * r + 0.587 * g + 0.114 * b).round().clamp(0.0, 255.0) as u8;
            pixel[0] = gray;
            pixel[1] = gray;
            pixel[2] = gray;
        }
    }

    /// Inverse toutes les composantes de couleur (négatif)
    pub fn invert(&mut self) {
        for byte in &mut self.data {
            *byte = 255 - *byte;
        }
    }

    /// Applique un flou de boîte 2D séparable (Box Blur) avec un rayon donné
    pub fn blur(&mut self, radius: usize) {
        if radius == 0 || self.width == 0 || self.height == 0 {
            return;
        }

        let mut temp = self.data.clone();

        // 1. Passe horizontale
        for y in 0..self.height {
            for x in 0..self.width {
                let mut sum_r = 0usize;
                let mut sum_g = 0usize;
                let mut sum_b = 0usize;
                let mut count = 0usize;

                let min_x = x.saturating_sub(radius);
                let max_x = (x + radius).min(self.width - 1);

                for ix in min_x..=max_x {
                    let idx = (y * self.width + ix) * 3;
                    sum_r += self.data[idx] as usize;
                    sum_g += self.data[idx + 1] as usize;
                    sum_b += self.data[idx + 2] as usize;
                    count += 1;
                }

                let out_idx = (y * self.width + x) * 3;
                temp[out_idx] = (sum_r / count) as u8;
                temp[out_idx + 1] = (sum_g / count) as u8;
                temp[out_idx + 2] = (sum_b / count) as u8;
            }
        }

        // 2. Passe verticale
        for y in 0..self.height {
            for x in 0..self.width {
                let mut sum_r = 0usize;
                let mut sum_g = 0usize;
                let mut sum_b = 0usize;
                let mut count = 0usize;

                let min_y = y.saturating_sub(radius);
                let max_y = (y + radius).min(self.height - 1);

                for iy in min_y..=max_y {
                    let idx = (iy * self.width + x) * 3;
                    sum_r += temp[idx] as usize;
                    sum_g += temp[idx + 1] as usize;
                    sum_b += temp[idx + 2] as usize;
                    count += 1;
                }

                let out_idx = (y * self.width + x) * 3;
                self.data[out_idx] = (sum_r / count) as u8;
                self.data[out_idx + 1] = (sum_g / count) as u8;
                self.data[out_idx + 2] = (sum_b / count) as u8;
            }
        }
    }

    /// Tourne l'image selon l'angle spécifié (90, 180 ou 270 degrés dans le sens horaire)
    pub fn rotate(&mut self, degrees: u32) -> Result<(), PpmError> {
        match degrees {
            90 => self.rotate_90_cw(),
            180 => self.rotate_180(),
            270 => self.rotate_270_cw(),
            deg => return Err(PpmError::InvalidRotationAngle(deg)),
        }
        Ok(())
    }

    fn rotate_90_cw(&mut self) {
        let new_width = self.height;
        let new_height = self.width;
        let mut new_data = vec![0u8; self.data.len()];

        for y in 0..self.height {
            for x in 0..self.width {
                let src_idx = (y * self.width + x) * 3;
                // Nouvelle position (x', y') = (height - 1 - y, x)
                let dst_x = self.height - 1 - y;
                let dst_y = x;
                let dst_idx = (dst_y * new_width + dst_x) * 3;

                new_data[dst_idx] = self.data[src_idx];
                new_data[dst_idx + 1] = self.data[src_idx + 1];
                new_data[dst_idx + 2] = self.data[src_idx + 2];
            }
        }

        self.width = new_width;
        self.height = new_height;
        self.data = new_data;
    }

    fn rotate_180(&mut self) {
        let total_pixels = self.width * self.height;
        let half_pixels = total_pixels / 2;

        for i in 0..half_pixels {
            let j = total_pixels - 1 - i;
            let idx_i = i * 3;
            let idx_j = j * 3;

            for c in 0..3 {
                self.data.swap(idx_i + c, idx_j + c);
            }
        }
    }

    fn rotate_270_cw(&mut self) {
        let new_width = self.height;
        let new_height = self.width;
        let mut new_data = vec![0u8; self.data.len()];

        for y in 0..self.height {
            for x in 0..self.width {
                let src_idx = (y * self.width + x) * 3;
                // Nouvelle position (x', y') = (y, width - 1 - x)
                let dst_x = y;
                let dst_y = self.width - 1 - x;
                let dst_idx = (dst_y * new_width + dst_x) * 3;

                new_data[dst_idx] = self.data[src_idx];
                new_data[dst_idx + 1] = self.data[src_idx + 1];
                new_data[dst_idx + 2] = self.data[src_idx + 2];
            }
        }

        self.width = new_width;
        self.height = new_height;
        self.data = new_data;
    }
}

/// Lit le prochain token textuel en ignorant les espaces blancs et les commentaires (# ...)
/// Ne consomme que les octets appartenant au token et les délimiteurs le précédant.
fn read_next_token<R: BufRead>(reader: &mut R) -> Result<Option<String>, PpmError> {
    let mut token = String::new();
    let mut in_comment = false;

    loop {
        let (consumed, should_break, found_token) = {
            let available = reader.fill_buf().map_err(PpmError::Io)?;
            if available.is_empty() {
                // EOF
                if token.is_empty() {
                    return Ok(None);
                } else {
                    return Ok(Some(token));
                }
            }

            let mut count = 0;
            let mut done = false;
            for &b in available {
                count += 1;
                if in_comment {
                    if b == b'\n' || b == b'\r' {
                        in_comment = false;
                    }
                    continue;
                }

                if b == b'#' {
                    in_comment = true;
                    continue;
                }

                if b.is_ascii_whitespace() {
                    if !token.is_empty() {
                        // On s'arrête ici sans consommer ce blanc pour le moment (ou le caller s'en charge)
                        // Note : on ne consomme PAS ce whitespace maintenant si on a déjà un token !
                        count -= 1;
                        done = true;
                        break;
                    }
                } else {
                    token.push(b as char);
                }
            }
            (count, done, !token.is_empty())
        };

        reader.consume(consumed);

        if should_break && found_token {
            return Ok(Some(token));
        }
    }
}

/// Arguments de ligne de commande pour le pipeline de traitement PPM
#[derive(Parser, Debug)]
#[command(author, version, about = "Pipeline de traitement d'images PPM (P3 et P6)", long_about = None)]
struct Args {
    /// Chemin du fichier PPM d'entrée
    #[arg(short, long)]
    input: PathBuf,

    /// Chemin du fichier PPM de sortie
    #[arg(short, long)]
    output: PathBuf,

    /// Convertit l'image en nuances de gris
    #[arg(long, default_value_t = false)]
    grayscale: bool,

    /// Inverse les couleurs de l'image
    #[arg(long, default_value_t = false)]
    invert: bool,

    /// Rayon du filtre de flou de boîte (ex: 1, 2, 5...)
    #[arg(long)]
    blur: Option<usize>,

    /// Angle de rotation en degrés horaire (90, 180, 270)
    #[arg(long)]
    rotate: Option<u32>,
}

fn main() -> anyhow::Result<()> {
    let args = Args::parse();

    println!("Chargement de l'image : {}", args.input.display());
    let mut image = PpmImage::read_from_file(&args.input)?;
    println!(
        "Dimensions : {}x{}, Échantillon max : {}",
        image.width, image.height, image.max_val
    );

    if args.grayscale {
        println!("Application du filtre nuances de gris...");
        image.to_grayscale();
    }

    if args.invert {
        println!("Application du filtre d'inversion des couleurs...");
        image.invert();
    }

    if let Some(radius) = args.blur {
        println!("Application du filtre de flou (rayon = {})...", radius);
        image.blur(radius);
    }

    if let Some(angle) = args.rotate {
        println!("Application de la rotation de {}°...", angle);
        image.rotate(angle)?;
    }

    println!("Sauvegarde du résultat dans : {}", args.output.display());
    image.write_to_file(&args.output)?;
    println!("Traitement terminé avec succès !");

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Cursor;

    #[test]
    fn test_ppm_p6_roundtrip() {
        let original = PpmImage {
            width: 2,
            height: 2,
            max_val: 255,
            data: vec![
                255, 0, 0,   0, 255, 0,
                0, 0, 255,   255, 255, 0,
            ],
        };

        let mut buffer = Vec::new();
        original.write_to_writer(&mut buffer).expect("Écriture échouée");

        let mut cursor = Cursor::new(buffer);
        let parsed = PpmImage::read_from_reader(&mut cursor).expect("Lecture échouée");

        assert_eq!(original, parsed);
    }

    #[test]
    fn test_ppm_p3_parsing_and_grayscale() {
        let p3_content = b"P3\n# Commentaire test\n2 1\n255\n255 0 0\n0 255 0\n";
        let mut cursor = Cursor::new(p3_content);
        let mut image = PpmImage::read_from_reader(&mut cursor).expect("Parsing P3 échoué");

        assert_eq!(image.width, 2);
        assert_eq!(image.height, 1);
        assert_eq!(image.data, vec![255, 0, 0, 0, 255, 0]);

        image.to_grayscale();
        // 0.299 * 255 = 76.245 -> 76
        // 0.587 * 255 = 149.685 -> 150
        assert_eq!(image.data[0..3], [76, 76, 76]);
        assert_eq!(image.data[3..6], [150, 150, 150]);
    }

    #[test]
    fn test_rotation_90() {
        // Image 2x3 :
        // [1, 2]
        // [3, 4]
        // [5, 6]
        let mut image = PpmImage {
            width: 2,
            height: 3,
            max_val: 255,
            data: vec![
                1, 1, 1,  2, 2, 2,
                3, 3, 3,  4, 4, 4,
                5, 5, 5,  6, 6, 6,
            ],
        };

        image.rotate(90).expect("Rotation 90 valide");
        assert_eq!(image.width, 3);
        assert_eq!(image.height, 2);

        // Après rotation 90° horaire :
        // [5, 3, 1]
        // [6, 4, 2]
        let expected = vec![
            5, 5, 5,  3, 3, 3,  1, 1, 1,
            6, 6, 6,  4, 4, 4,  2, 2, 2,
        ];
        assert_eq!(image.data, expected);
    }

    #[test]
    fn test_invert() {
        let mut image = PpmImage {
            width: 1,
            height: 1,
            max_val: 255,
            data: vec![10, 200, 255],
        };

        image.invert();
        assert_eq!(image.data, vec![245, 55, 0]);
    }
}

