// src/main.rs
use std::env;
use std::fmt;
use std::net::{Ipv4Addr, Ipv6Addr, SocketAddr, UdpSocket};
use std::time::Duration;

// ============================================================================
// Codes d'erreur et types de données DNS
// ============================================================================

#[derive(Debug)]
pub enum DnsError {
    EndOfBuffer,
    InvalidLabelJump,
    LabelLengthLimitExceeded,
    InvalidOpcode,
    IoError(std::io::Error),
    NetworkError(String),
    MaxRecursionDepthReached,
    ResolutionFailed,
}

impl fmt::Display for DnsError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            DnsError::EndOfBuffer => write!(f, "Fin inattendue du tampon DNS"),
            DnsError::InvalidLabelJump => write!(f, "Boucle ou saut de pointeur DNS invalide"),
            DnsError::LabelLengthLimitExceeded => write!(f, "Longueur de label DNS dépassée (>63 octets)"),
            DnsError::InvalidOpcode => write!(f, "Opcode ou format de trame DNS invalide"),
            DnsError::IoError(e) => write!(f, "Erreur d'E/S: {}", e),
            DnsError::NetworkError(msg) => write!(f, "Erreur réseau: {}", msg),
            DnsError::MaxRecursionDepthReached => write!(f, "Profondeur maximale de récursion atteinte"),
            DnsError::ResolutionFailed => write!(f, "Échec de résolution récursive DNS"),
        }
    }
}

impl std::error::Error for DnsError {}

impl From<std::io::Error> for DnsError {
    fn from(err: std::io::Error) -> Self {
        DnsError::IoError(err)
    }
}

#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub enum ResultCode {
    NOERROR = 0,
    FORMERR = 1,
    SERVFAIL = 2,
    NXDOMAIN = 3,
    NOTIMP = 4,
    REFUSED = 5,
}

impl ResultCode {
    pub fn from_num(num: u8) -> ResultCode {
        match num {
            1 => ResultCode::FORMERR,
            2 => ResultCode::SERVFAIL,
            3 => ResultCode::NXDOMAIN,
            4 => ResultCode::NOTIMP,
            5 => ResultCode::REFUSED,
            0 | _ => ResultCode::NOERROR,
        }
    }
}

#[derive(Copy, Clone, Debug, PartialEq, Eq, Hash)]
pub enum QueryType {
    UNKNOWN(u16),
    A,     // 1
    NS,    // 2
    CNAME, // 5
    MX,    // 15
    AAAA,  // 28
}

impl QueryType {
    pub fn to_num(self) -> u16 {
        match self {
            QueryType::UNKNOWN(x) => x,
            QueryType::A => 1,
            QueryType::NS => 2,
            QueryType::CNAME => 5,
            QueryType::MX => 15,
            QueryType::AAAA => 28,
        }
    }

    pub fn from_num(num: u16) -> QueryType {
        match num {
            1 => QueryType::A,
            2 => QueryType::NS,
            5 => QueryType::CNAME,
            15 => QueryType::MX,
            28 => QueryType::AAAA,
            _ => QueryType::UNKNOWN(num),
        }
    }
}

// ============================================================================
// Tampon d'octets avec gestion de pointeurs et parsing manuel
// ============================================================================

pub struct BytePacketBuffer {
    pub buf: [u8; 512],
    pub pos: usize,
}

impl BytePacketBuffer {
    pub fn new() -> BytePacketBuffer {
        BytePacketBuffer {
            buf: [0; 512],
            pos: 0,
        }
    }

    pub fn pos(&self) -> usize {
        self.pos
    }

    pub fn step(&mut self, steps: usize) -> Result<(), DnsError> {
        self.pos += steps;
        Ok(())
    }

    pub fn seek(&mut self, pos: usize) -> Result<(), DnsError> {
        self.pos = pos;
        Ok(())
    }

    pub fn read(&mut self) -> Result<u8, DnsError> {
        if self.pos >= 512 {
            return Err(DnsError::EndOfBuffer);
        }
        let res = self.buf[self.pos];
        self.pos += 1;
        Ok(res)
    }

    pub fn get(&self, pos: usize) -> Result<u8, DnsError> {
        if pos >= 512 {
            return Err(DnsError::EndOfBuffer);
        }
        Ok(self.buf[pos])
    }

    pub fn get_range(&self, start: usize, len: usize) -> Result<&[u8], DnsError> {
        if start + len > 512 {
            return Err(DnsError::EndOfBuffer);
        }
        Ok(&self.buf[start..start + len])
    }

    pub fn read_u16(&mut self) -> Result<u16, DnsError> {
        let b1 = self.read()? as u16;
        let b2 = self.read()? as u16;
        Ok((b1 << 8) | b2)
    }

    pub fn read_u32(&mut self) -> Result<u32, DnsError> {
        let b1 = self.read()? as u32;
        let b2 = self.read()? as u32;
        let b3 = self.read()? as u32;
        let b4 = self.read()? as u32;
        Ok((b1 << 24) | (b2 << 16) | (b3 << 8) | b4)
    }

    pub fn read_qname(&mut self, outstr: &mut String) -> Result<(), DnsError> {
        let mut pos = self.pos;
        let mut jumped = false;
        let mut max_jumps = 5;
        let mut delim = "";

        loop {
            if max_jumps == 0 {
                return Err(DnsError::InvalidLabelJump);
            }

            let len = self.get(pos)?;

            // Vérification si c'est un pointeur de compression (les 2 bits de poids fort sont à 1 : 0xC0)
            if (len & 0xC0) == 0xC0 {
                if !jumped {
                    self.seek(pos + 2)?;
                }

                let b2 = self.get(pos + 1)? as u16;
                let offset = (((len as u16) ^ 0xC0) << 8) | b2;
                pos = offset as usize;

                jumped = true;
                max_jumps -= 1;
                continue;
            }

            pos += 1;

            if len == 0 {
                break;
            }

            outstr.push_str(delim);
            let str_buffer = self.get_range(pos, len as usize)?;
            outstr.push_str(&String::from_utf8_lossy(str_buffer).to_lowercase());

            delim = ".";
            pos += len as usize;
        }

        if !jumped {
            self.seek(pos)?;
        }

        Ok(())
    }

    pub fn write(&mut self, val: u8) -> Result<(), DnsError> {
        if self.pos >= 512 {
            return Err(DnsError::EndOfBuffer);
        }
        self.buf[self.pos] = val;
        self.pos += 1;
        Ok(())
    }

    pub fn write_u8(&mut self, val: u8) -> Result<(), DnsError> {
        self.write(val)
    }

    pub fn write_u16(&mut self, val: u16) -> Result<(), DnsError> {
        self.write((val >> 8) as u8)?;
        self.write((val & 0xFF) as u8)?;
        Ok(())
    }

    pub fn write_u32(&mut self, val: u32) -> Result<(), DnsError> {
        self.write(((val >> 24) & 0xFF) as u8)?;
        self.write(((val >> 16) & 0xFF) as u8)?;
        self.write(((val >> 8) & 0xFF) as u8)?;
        self.write((val & 0xFF) as u8)?;
        Ok(())
    }

    pub fn write_qname(&mut self, qname: &str) -> Result<(), DnsError> {
        for label in qname.split('.') {
            let len = label.len();
            if len > 63 {
                return Err(DnsError::LabelLengthLimitExceeded);
            }

            self.write_u8(len as u8)?;
            for b in label.as_bytes() {
                self.write_u8(*b)?;
            }
        }
        self.write_u8(0)?;
        Ok(())
    }

    pub fn set(&mut self, pos: usize, val: u8) -> Result<(), DnsError> {
        if pos >= 512 {
            return Err(DnsError::EndOfBuffer);
        }
        self.buf[pos] = val;
        Ok(())
    }

    pub fn set_u16(&mut self, pos: usize, val: u16) -> Result<(), DnsError> {
        self.set(pos, (val >> 8) as u8)?;
        self.set(pos + 1, (val & 0xFF) as u8)?;
        Ok(())
    }
}

// ============================================================================
// En-tête DNS (RFC 1035 §4.1.1)
// ============================================================================

#[derive(Clone, Debug)]
pub struct DnsHeader {
    pub id: u16,
    pub recursion_desired: bool,
    pub truncated_message: bool,
    pub authoritative_answer: bool,
    pub opcode: u8,
    pub response: bool,
    pub rescode: ResultCode,
    pub checking_disabled: bool,
    pub authed_data: bool,
    pub z: bool,
    pub recursion_available: bool,
    pub questions: u16,
    pub answers: u16,
    pub authoritative_entries: u16,
    pub resource_entries: u16,
}

impl DnsHeader {
    pub fn new() -> DnsHeader {
        DnsHeader {
            id: 0,
            recursion_desired: false,
            truncated_message: false,
            authoritative_answer: false,
            opcode: 0,
            response: false,
            rescode: ResultCode::NOERROR,
            checking_disabled: false,
            authed_data: false,
            z: false,
            recursion_available: false,
            questions: 0,
            answers: 0,
            authoritative_entries: 0,
            resource_entries: 0,
        }
    }

    pub fn read(&mut self, buffer: &mut BytePacketBuffer) -> Result<(), DnsError> {
        self.id = buffer.read_u16()?;

        let flags = buffer.read_u16()?;
        let a = (flags >> 8) as u8;
        let b = (flags & 0xFF) as u8;

        self.response = (a & (1 << 7)) > 0;
        self.opcode = (a >> 3) & 0x0F;
        self.authoritative_answer = (a & (1 << 2)) > 0;
        self.truncated_message = (a & (1 << 1)) > 0;
        self.recursion_desired = (a & (1 << 0)) > 0;

        self.recursion_available = (b & (1 << 7)) > 0;
        self.z = (b & (1 << 6)) > 0;
        self.authed_data = (b & (1 << 5)) > 0;
        self.checking_disabled = (b & (1 << 4)) > 0;
        self.rescode = ResultCode::from_num(b & 0x0F);

        self.questions = buffer.read_u16()?;
        self.answers = buffer.read_u16()?;
        self.authoritative_entries = buffer.read_u16()?;
        self.resource_entries = buffer.read_u16()?;

        Ok(())
    }

    pub fn write(&self, buffer: &mut BytePacketBuffer) -> Result<(), DnsError> {
        buffer.write_u16(self.id)?;

        let mut a: u8 = 0;
        if self.response {
            a |= 1 << 7;
        }
        a |= (self.opcode & 0x0F) << 3;
        if self.authoritative_answer {
            a |= 1 << 2;
        }
        if self.truncated_message {
            a |= 1 << 1;
        }
        if self.recursion_desired {
            a |= 1 << 0;
        }

        let mut b: u8 = 0;
        if self.recursion_available {
            b |= 1 << 7;
        }
        if self.z {
            b |= 1 << 6;
        }
        if self.authed_data {
            b |= 1 << 5;
        }
        if self.checking_disabled {
            b |= 1 << 4;
        }
        b |= (self.rescode as u8) & 0x0F;

        buffer.write_u8(a)?;
        buffer.write_u8(b)?;
        buffer.write_u16(self.questions)?;
        buffer.write_u16(self.answers)?;
        buffer.write_u16(self.authoritative_entries)?;
        buffer.write_u16(self.resource_entries)?;

        Ok(())
    }
}

// ============================================================================
// Question DNS (RFC 1035 §4.1.2)
// ============================================================================

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DnsQuestion {
    pub name: String,
    pub qtype: QueryType,
}

impl DnsQuestion {
    pub fn new(name: String, qtype: QueryType) -> DnsQuestion {
        DnsQuestion { name, qtype }
    }

    pub fn read(&mut self, buffer: &mut BytePacketBuffer) -> Result<(), DnsError> {
        buffer.read_qname(&mut self.name)?;
        self.qtype = QueryType::from_num(buffer.read_u16()?);
        let _qclass = buffer.read_u16()?; // 1 = IN (Internet)
        Ok(())
    }

    pub fn write(&self, buffer: &mut BytePacketBuffer) -> Result<(), DnsError> {
        buffer.write_qname(&self.name)?;
        buffer.write_u16(self.qtype.to_num())?;
        buffer.write_u16(1)?; // Internet class
        Ok(())
    }
}

// ============================================================================
// Resource Records (RFC 1035 §4.1.3)
// ============================================================================

#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum DnsRecord {
    UNKNOWN {
        domain: String,
        qtype: u16,
        data_len: u16,
        ttl: u32,
    },
    A {
        domain: String,
        addr: Ipv4Addr,
        ttl: u32,
    },
    NS {
        domain: String,
        host: String,
        ttl: u32,
    },
    CNAME {
        domain: String,
        host: String,
        ttl: u32,
    },
    MX {
        domain: String,
        priority: u16,
        host: String,
        ttl: u32,
    },
    AAAA {
        domain: String,
        addr: Ipv6Addr,
        ttl: u32,
    },
}

impl DnsRecord {
    pub fn read(buffer: &mut BytePacketBuffer) -> Result<DnsRecord, DnsError> {
        let mut domain = String::new();
        buffer.read_qname(&mut domain)?;

        let qtype_num = buffer.read_u16()?;
        let qtype = QueryType::from_num(qtype_num);
        let _class = buffer.read_u16()?;
        let ttl = buffer.read_u32()?;
        let data_len = buffer.read_u16()?;

        match qtype {
            QueryType::A => {
                let raw_addr = buffer.read_u32()?;
                let addr = Ipv4Addr::new(
                    ((raw_addr >> 24) & 0xFF) as u8,
                    ((raw_addr >> 16) & 0xFF) as u8,
                    ((raw_addr >> 8) & 0xFF) as u8,
                    (raw_addr & 0xFF) as u8,
                );
                Ok(DnsRecord::A { domain, addr, ttl })
            }
            QueryType::AAAA => {
                let raw_addr1 = buffer.read_u32()?;
                let raw_addr2 = buffer.read_u32()?;
                let raw_addr3 = buffer.read_u32()?;
                let raw_addr4 = buffer.read_u32()?;
                let addr = Ipv6Addr::new(
                    ((raw_addr1 >> 16) & 0xFFFF) as u16,
                    (raw_addr1 & 0xFFFF) as u16,
                    ((raw_addr2 >> 16) & 0xFFFF) as u16,
                    (raw_addr2 & 0xFFFF) as u16,
                    ((raw_addr3 >> 16) & 0xFFFF) as u16,
                    (raw_addr3 & 0xFFFF) as u16,
                    ((raw_addr4 >> 16) & 0xFFFF) as u16,
                    (raw_addr4 & 0xFFFF) as u16,
                );
                Ok(DnsRecord::AAAA { domain, addr, ttl })
            }
            QueryType::NS => {
                let mut ns = String::new();
                buffer.read_qname(&mut ns)?;
                Ok(DnsRecord::NS { domain, host: ns, ttl })
            }
            QueryType::CNAME => {
                let mut cname = String::new();
                buffer.read_qname(&mut cname)?;
                Ok(DnsRecord::CNAME { domain, host: cname, ttl })
            }
            QueryType::MX => {
                let priority = buffer.read_u16()?;
                let mut mx = String::new();
                buffer.read_qname(&mut mx)?;
                Ok(DnsRecord::MX { domain, priority, host: mx, ttl })
            }
            QueryType::UNKNOWN(_) => {
                buffer.step(data_len as usize)?;
                Ok(DnsRecord::UNKNOWN {
                    domain,
                    qtype: qtype_num,
                    data_len,
                    ttl,
                })
            }
        }
    }

    pub fn write(&self, buffer: &mut BytePacketBuffer) -> Result<usize, DnsError> {
        let start_pos = buffer.pos();

        match self {
            DnsRecord::A { domain, addr, ttl } => {
                buffer.write_qname(domain)?;
                buffer.write_u16(QueryType::A.to_num())?;
                buffer.write_u16(1)?;
                buffer.write_u32(*ttl)?;
                buffer.write_u16(4)?;

                for octet in &addr.octets() {
                    buffer.write_u8(*octet)?;
                }
            }
            DnsRecord::AAAA { domain, addr, ttl } => {
                buffer.write_qname(domain)?;
                buffer.write_u16(QueryType::AAAA.to_num())?;
                buffer.write_u16(1)?;
                buffer.write_u32(*ttl)?;
                buffer.write_u16(16)?;

                for octet in &addr.octets() {
                    buffer.write_u8(*octet)?;
                }
            }
            DnsRecord::NS { domain, host, ttl } => {
                buffer.write_qname(domain)?;
                buffer.write_u16(QueryType::NS.to_num())?;
                buffer.write_u16(1)?;
                buffer.write_u32(*ttl)?;

                let pos = buffer.pos();
                buffer.write_u16(0)?;
                buffer.write_qname(host)?;

                let size = buffer.pos() - (pos + 2);
                buffer.set_u16(pos, size as u16)?;
            }
            DnsRecord::CNAME { domain, host, ttl } => {
                buffer.write_qname(domain)?;
                buffer.write_u16(QueryType::CNAME.to_num())?;
                buffer.write_u16(1)?;
                buffer.write_u32(*ttl)?;

                let pos = buffer.pos();
                buffer.write_u16(0)?;
                buffer.write_qname(host)?;

                let size = buffer.pos() - (pos + 2);
                buffer.set_u16(pos, size as u16)?;
            }
            DnsRecord::MX { domain, priority, host, ttl } => {
                buffer.write_qname(domain)?;
                buffer.write_u16(QueryType::MX.to_num())?;
                buffer.write_u16(1)?;
                buffer.write_u32(*ttl)?;

                let pos = buffer.pos();
                buffer.write_u16(0)?;
                buffer.write_u16(*priority)?;
                buffer.write_qname(host)?;

                let size = buffer.pos() - (pos + 2);
                buffer.set_u16(pos, size as u16)?;
            }
            DnsRecord::UNKNOWN { .. } => {
                log::warn!("Ignoré: Tentative d'écriture d'un enregistrement UNKNOWN");
            }
        }

        Ok(buffer.pos() - start_pos)
    }
}

// ============================================================================
// Paquet DNS complet
// ============================================================================

#[derive(Clone, Debug)]
pub struct DnsPacket {
    pub header: DnsHeader,
    pub questions: Vec<DnsQuestion>,
    pub answers: Vec<DnsRecord>,
    pub authorities: Vec<DnsRecord>,
    pub resources: Vec<DnsRecord>,
}

impl DnsPacket {
    pub fn new() -> DnsPacket {
        DnsPacket {
            header: DnsHeader::new(),
            questions: Vec::new(),
            answers: Vec::new(),
            authorities: Vec::new(),
            resources: Vec::new(),
        }
    }

    pub fn from_buffer(buffer: &mut BytePacketBuffer) -> Result<DnsPacket, DnsError> {
        let mut result = DnsPacket::new();
        result.header.read(buffer)?;

        for _ in 0..result.header.questions {
            let mut question = DnsQuestion::new("".to_string(), QueryType::UNKNOWN(0));
            question.read(buffer)?;
            result.questions.push(question);
        }

        for _ in 0..result.header.answers {
            let rec = DnsRecord::read(buffer)?;
            result.answers.push(rec);
        }

        for _ in 0..result.header.authoritative_entries {
            let rec = DnsRecord::read(buffer)?;
            result.authorities.push(rec);
        }

        for _ in 0..result.header.resource_entries {
            let rec = DnsRecord::read(buffer)?;
            result.resources.push(rec);
        }

        Ok(result)
    }

    pub fn write(&mut self, buffer: &mut BytePacketBuffer) -> Result<(), DnsError> {
        self.header.questions = self.questions.len() as u16;
        self.header.answers = self.answers.len() as u16;
        self.header.authoritative_entries = self.authorities.len() as u16;
        self.header.resource_entries = self.resources.len() as u16;

        self.header.write(buffer)?;

        for q in &self.questions {
            q.write(buffer)?;
        }
        for rec in &self.answers {
            rec.write(buffer)?;
        }
        for rec in &self.authorities {
            rec.write(buffer)?;
        }
        for rec in &self.resources {
            rec.write(buffer)?;
        }

        Ok(())
    }

    /// Récupère une adresse IPv4 aléatoire parmi les enregistrements résolus (A)
    pub fn get_resolved_a(&self, domain: &str) -> Option<Ipv4Addr> {
        self.answers
            .iter()
            .filter_map(|record| match record {
                DnsRecord::A { domain: d, addr, .. } if d.eq_ignore_ascii_case(domain) => Some(*addr),
                _ => None,
            })
            .next()
    }

    /// Récupère un serveur de noms (NS) pour un domaine donné
    pub fn get_ns<'a, 'b>(&'a self, domain: &'b str) -> impl Iterator<Item = (&'a str, &'a str)> + 'b
    where
        'a: 'b,
    {
        self.authorities
            .iter()
            .filter_map(move |record| match record {
                DnsRecord::NS { domain: d, host, .. } if domain.ends_with(d) => {
                    Some((d.as_str(), host.as_str()))
                }
                _ => None,
            })
    }
}

// ============================================================================
// Résolveur DNS récursif
// ============================================================================

/// Effectue une requête DNS vers un serveur particulier
fn lookup(qname: &str, qtype: QueryType, server: (Ipv4Addr, u16)) -> Result<DnsPacket, DnsError> {
    let socket = UdpSocket::bind("0.0.0.0:0")?;
    socket.set_read_timeout(Some(Duration::from_secs(3)))?;

    let mut packet = DnsPacket::new();
    packet.header.id = 6666;
    packet.header.questions = 1;
    packet.header.recursion_desired = true; // Demande de récursion facultative, standard pour les tests
    packet.questions.push(DnsQuestion::new(qname.to_string(), qtype));

    let mut req_buffer = BytePacketBuffer::new();
    packet.write(&mut req_buffer)?;

    let target = SocketAddr::from((server.0, server.1));
    socket.send_to(&req_buffer.buf[0..req_buffer.pos], target)?;

    let mut res_buffer = BytePacketBuffer::new();
    let (amt, _) = socket.recv_from(&mut res_buffer.buf)?;
    if amt == 0 {
        return Err(DnsError::NetworkError("Réponse vide du serveur amont".into()));
    }

    DnsPacket::from_buffer(&mut res_buffer)
}

/// Résolution DNS récursive complète depuis les Root DNS
pub fn recursive_lookup(qname: &str, qtype: QueryType) -> Result<DnsPacket, DnsError> {
    // Serveurs Root DNS mondiaux (a.root-servers.net, b.root-servers.net, etc.)
    let mut ns: Ipv4Addr = "198.41.0.4".parse().unwrap_or(Ipv4Addr::new(198, 41, 0, 4));
    let mut current_name = qname.to_string();
    let mut depth = 0;

    loop {
        depth += 1;
        if depth > 20 {
            return Err(DnsError::MaxRecursionDepthReached);
        }

        log::info!("Tentative d'interrogation de {} pour {} sur {}:53", current_name, ns, 53);
        let response = match lookup(&current_name, qtype, (ns, 53)) {
            Ok(p) => p,
            Err(e) => {
                log::warn!("Échec de communication avec {}: {}. Abandon du chemin.", ns, e);
                return Err(e);
            }
        };

        // 1. Si nous avons obtenu une réponse directe dans la section Answers
        if !response.answers.is_empty() && response.header.rescode == ResultCode::NOERROR {
            // Vérifier s'il y a un alias CNAME
            let cname_target = response.answers.iter().find_map(|rec| match rec {
                DnsRecord::CNAME { host, .. } => Some(host.clone()),
                _ => None,
            });

            if let Some(target) = cname_target {
                // Si l'utilisateur a explicitement demandé le CNAME, retourner la réponse
                if qtype == QueryType::CNAME {
                    return Ok(response);
                }
                log::info!("Résolution d'alias CNAME: {} -> {}", current_name, target);
                current_name = target;
                ns = "198.41.0.4".parse().unwrap_or(Ipv4Addr::new(198, 41, 0, 4));
                continue;
            }

            return Ok(response);
        }

        // 2. Si le nom n'existe pas (NXDOMAIN)
        if response.header.rescode == ResultCode::NXDOMAIN {
            return Ok(response);
        }

        // 3. Recherche dans les serveurs de noms additionnels (Glue Records)
        let glue_ns = response.resources.iter().find_map(|rec| match rec {
            DnsRecord::A { domain: _, addr, .. } => Some(*addr),
            _ => None,
        });

        if let Some(new_ns) = glue_ns {
            ns = new_ns;
            continue;
        }

        // 4. Si nous avons un serveur NS désigné dans Authority mais sans adresse glue directe
        let ns_host = response
            .get_ns(&current_name)
            .map(|(_, host)| host.to_string())
            .next();

        if let Some(host) = ns_host {
            log::info!("Résolution récursive de l'adresse du serveur NS: {}", host);
            let ns_resolve = recursive_lookup(&host, QueryType::A)?;
            if let Some(resolved_addr) = ns_resolve.get_resolved_a(&host) {
                ns = resolved_addr;
                continue;
            }
        }

        // Si aucun chemin n'a été trouvé
        return Err(DnsError::ResolutionFailed);
    }
}

// ============================================================================
// Serveur d'écoute UDP
// ============================================================================

fn handle_query(socket: &UdpSocket) -> Result<(), DnsError> {
    let mut req_buffer = BytePacketBuffer::new();
    let (_, src) = socket.recv_from(&mut req_buffer.buf)?;

    let mut request = match DnsPacket::from_buffer(&mut req_buffer) {
        Ok(packet) => packet,
        Err(err) => {
            log::error!("Impossible de décoder la trame reçue de {}: {}", src, err);
            return Err(err);
        }
    };

    let mut response = DnsPacket::new();
    response.header.id = request.header.id;
    response.header.recursion_desired = request.header.recursion_desired;
    response.header.recursion_available = true;
    response.header.response = true;

    if let Some(question) = request.questions.pop() {
        log::info!("Requête DNS reçue de {} pour: {:?} {:?}", src, question.name, question.qtype);

        match recursive_lookup(&question.name, question.qtype) {
            Ok(result) => {
                response.questions.push(question);
                response.header.rescode = result.header.rescode;
                response.answers = result.answers;
                response.authorities = result.authorities;
                response.resources = result.resources;
            }
            Err(err) => {
                log::error!("Erreur lors de la résolution de {}: {}", question.name, err);
                response.questions.push(question);
                response.header.rescode = ResultCode::SERVFAIL;
            }
        }
    } else {
        response.header.rescode = ResultCode::FORMERR;
    }

    let mut res_buffer = BytePacketBuffer::new();
    response.write(&mut res_buffer)?;

    let len = res_buffer.pos();
    socket.send_to(&res_buffer.buf[0..len], src)?;
    log::info!("Réponse transmise avec succès à {} ({} octets)", src, len);

    Ok(())
}

fn main() {
    if env::var("RUST_LOG").is_err() {
        env::set_var("RUST_LOG", "info");
    }
    env_logger::init();

    let port: u16 = env::args()
        .nth(1)
        .and_then(|p| p.parse().ok())
        .unwrap_or(53);

    let bind_addr = format!("0.0.0.0:{}", port);
    let socket = match UdpSocket::bind(&bind_addr) {
        Ok(s) => {
            log::info!("Serveur DNS récursif démarré avec succès sur {}", bind_addr);
            s
        }
        Err(err) => {
            log::error!(
                "Échec de liaison UDP sur {}: {}. Note: Le port 53 requiert des privilèges élevés (ex: sudo) ou un port alternatif (>1024).",
                bind_addr,
                err
            );
            std::process::exit(1);
        }
    };

    loop {
        if let Err(e) = handle_query(&socket) {
            log::warn!("Erreur lors du traitement d'une requête: {}", e);
        }
    }
}

