    fn test_byte_buffer_write_and_read_qname() {
        let mut buffer = BytePacketBuffer::new();
        let domain = "google.com";
        assert!(buffer.write_qname(domain).is_ok());

        buffer.seek(0).unwrap();
        let mut parsed_domain = String::new();
        assert!(buffer.read_qname(&mut parsed_domain).is_ok());
        assert_eq!(domain, parsed_domain);
    }

    #[test]
    fn test_header_encode_decode() {
        let mut header = DnsHeader::new();
        header.id = 0x1234;
        header.response = true;
        header.recursion_desired = true;
        header.recursion_available = true;
        header.questions = 1;
        header.answers = 2;

        let mut buffer = BytePacketBuffer::new();
        assert!(header.write(&mut buffer).is_ok());

        buffer.seek(0).unwrap();
        let mut decoded = DnsHeader::new();
        assert!(decoded.read(&mut buffer).is_ok());

        assert_eq!(decoded.id, 0x1234);
        assert!(decoded.response);
        assert!(decoded.recursion_desired);
        assert!(decoded.recursion_available);
        assert_eq!(decoded.questions, 1);
        assert_eq!(decoded.answers, 2);
    }

    #[test]
    fn test_packet_encode_decode() {
        let mut packet = DnsPacket::new();
        packet.header.id = 42;
        packet.questions.push(DnsQuestion::new("example.com".to_string(), QueryType::A));
        packet.answers.push(DnsRecord::A {
            domain: "example.com".to_string(),
            addr: Ipv4Addr::new(93, 184, 216, 34),
            ttl: 300,
        });

        let mut buffer = BytePacketBuffer::new();
        assert!(packet.write(&mut buffer).is_ok());

        buffer.seek(0).unwrap();
        let decoded = DnsPacket::from_buffer(&mut buffer).expect("Le décodage du paquet a échoué");

        assert_eq!(decoded.header.id, 42);
        assert_eq!(decoded.questions.len(), 1);
        assert_eq!(decoded.questions[0].name, "example.com");
        assert_eq!(decoded.questions[0].qtype, QueryType::A);
        assert_eq!(decoded.answers.len(), 1);

        match &decoded.answers[0] {
            DnsRecord::A { domain, addr, ttl } => {
                assert_eq!(domain, "example.com");
                assert_eq!(*addr, Ipv4Addr::new(93, 184, 216, 34));
                assert_eq!(*ttl, 300);
            }
            _ => panic!("Type d'enregistrement inattendu"),
        }
    }
}

