// src/main.rs
//! Implémentation complète et idiomatique d'un arbre AVL en Rust
//! avec auto-équilibrage (rotations simples et doubles) et validation d'invariants.

use std::cmp::{max, Ordering};
use std::fmt::{self, Debug, Display};

/// Représentation d'une erreur lors de la validation des invariants structurels de l'arbre.
#[derive(Debug, PartialEq, Eq)]
pub enum ValidationError {
    /// La propriété d'ordre de l'arbre binaire de recherche a été violée.
    BstOrderViolation(String),
    /// La hauteur en cache dans le nœud ne correspond pas à la hauteur réelle calculée.
    HeightMismatch {
        expected: usize,
        actual: usize,
    },
    /// Le facteur d'équilibrage dépasse la plage admise [-1, 1].
    UnbalancedNode {
        balance_factor: isize,
    },
    /// Le nombre réel d'éléments ne correspond pas au compteur `len`.
    SizeMismatch {
        recorded_size: usize,
        actual_size: usize,
    },
}

impl Display for ValidationError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::BstOrderViolation(msg) => write!(f, "Violation d'ordre BST : {msg}"),
            Self::HeightMismatch { expected, actual } => {
                write!(f, "Hauteur incorrecte : calculée={expected}, stockée={actual}")
            }
            Self::UnbalancedNode { balance_factor } => {
                write!(f, "Déséquilibre détecté : facteur={balance_factor} hors [-1, 1]")
            }
            Self::SizeMismatch {
                recorded_size,
                actual_size,
            } => {
                write!(
                    f,
                    "Taille incohérente : enregistrée={recorded_size}, réelle={actual_size}"
                )
            }
        }
    }
}

impl std::error::Error for ValidationError {}

/// Nœud interne de l'arbre AVL.
#[derive(Debug, Clone)]
struct AVLNode<K, V> {
    key: K,
    value: V,
    height: usize,
    left: Option<Box<AVLNode<K, V>>>,
    right: Option<Box<AVLNode<K, V>>>,
}

impl<K, V> AVLNode<K, V> {
    fn new(key: K, value: V) -> Self {
        Self {
            key,
            value,
            height: 1,
            left: None,
            right: None,
        }
    }

    #[inline]
    fn node_height(node: &Option<Box<Self>>) -> usize {
        node.as_ref().map_or(0, |n| n.height)
    }

    #[inline]
    fn update_height(&mut self) {
        let left_h = Self::node_height(&self.left);
        let right_h = Self::node_height(&self.right);
        self.height = 1 + max(left_h, right_h);
    }

    #[inline]
    fn balance_factor(&self) -> isize {
        let left_h = Self::node_height(&self.left) as isize;
        let right_h = Self::node_height(&self.right) as isize;
        left_h - right_h
    }

    /// Rotation simple à droite.
    ///
    /// ```text
    ///       Y                 X
    ///      / \               / \
    ///     X   C    ===>     A   Y
    ///    / \                   / \
    ///   A   B                 B   C
    /// ```
    fn rotate_right(mut self: Box<Self>) -> Box<Self> {
        let mut new_root = match self.left.take() {
            Some(node) => node,
            None => return self,
        };

        self.left = new_root.right.take();
        self.update_height();

        new_root.right = Some(self);
        new_root.update_height();

        new_root
    }

    /// Rotation simple à gauche.
    ///
    /// ```text
    ///     X                     Y
    ///    / \                   / \
    ///   A   Y        ===>     X   C
    ///      / \               / \
    ///     B   C             A   B
    /// ```
    fn rotate_left(mut self: Box<Self>) -> Box<Self> {
        let mut new_root = match self.right.take() {
            Some(node) => node,
            None => return self,
        };

        self.right = new_root.left.take();
        self.update_height();

        new_root.left = Some(self);
        new_root.update_height();

        new_root
    }

    /// Rétablit l'équilibre AVL du sous-arbre enraciné en `self`.
    fn rebalance(mut self: Box<Self>) -> Box<Self> {
        self.update_height();
        let balance = self.balance_factor();

        // Cas Gauche-Gauche ou Gauche-Droite
        if balance > 1 {
            if let Some(left) = self.left.as_mut() {
                if left.balance_factor() < 0 {
                    // Double rotation : Gauche-Droite (Left-Right)
                    let left_node = self.left.take().unwrap();
                    self.left = Some(left_node.rotate_left());
                }
            }
            return self.rotate_right();
        }

        // Cas Droite-Droite ou Droite-Gauche
        if balance < -1 {
            if let Some(right) = self.right.as_mut() {
                if right.balance_factor() > 0 {
                    // Double rotation : Droite-Gauche (Right-Left)
                    let right_node = self.right.take().unwrap();
                    self.right = Some(right_node.rotate_right());
                }
            }
            return self.rotate_left();
        }

        self
    }
}

/// Arbre de recherche binaire auto-équilibré AVL.
#[derive(Debug, Clone, Default)]
pub struct AVLTree<K, V> {
    root: Option<Box<AVLNode<K, V>>>,
    len: usize,
}

impl<K, V> AVLTree<K, V>
where
    K: Ord,
{
    /// Crée un nouvel arbre AVL vide.
    #[must_use]
    pub const fn new() -> Self {
        Self { root: None, len: 0 }
    }

    /// Renvoie le nombre d'éléments dans l'arbre.
    #[inline]
    #[must_use]
    pub const fn len(&self) -> usize {
        self.len
    }

    /// Indique si l'arbre est vide.
    #[inline]
    #[must_use]
    pub const fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Renvoie la hauteur de l'arbre (0 pour un arbre vide).
    #[inline]
    #[must_use]
    pub fn height(&self) -> usize {
        AVLNode::node_height(&self.root)
    }

    /// Recherche une référence vers la valeur associée à la clé.
    pub fn get(&self, key: &K) -> Option<&V> {
        let mut current = self.root.as_ref();
        while let Some(node) = current {
            match key.cmp(&node.key) {
                Ordering::Less => current = node.left.as_ref(),
                Ordering::Greater => current = node.right.as_ref(),
                Ordering::Equal => return Some(&node.value),
            }
        }
        None
    }

    /// Recherche une référence mutable vers la valeur associée à la clé.
    pub fn get_mut(&mut self, key: &K) -> Option<&mut V> {
        let mut current = self.root.as_mut();
        while let Some(node) = current {
            match key.cmp(&node.key) {
                Ordering::Less => current = node.left.as_mut(),
                Ordering::Greater => current = node.right.as_mut(),
                Ordering::Equal => return Some(&mut node.value),
            }
        }
        None
    }

    /// Indique si la clé est présente dans l'arbre.
    #[must_use]
    pub fn contains_key(&self, key: &K) -> bool {
        self.get(key).is_some()
    }

    /// Insère une paire clé-valeur dans l'arbre AVL.
    ///
    /// Si la clé existait déjà, remplace l'ancienne valeur et la retourne.
    /// Sinon, insère la nouvelle feuille, rééquilibre l'arbre et retourne `None`.
    pub fn insert(&mut self, key: K, value: V) -> Option<V> {
        let mut old_value = None;
        let mut inserted = false;
        let root = self.root.take();
        self.root = Self::insert_rec(root, key, value, &mut old_value, &mut inserted);
        if inserted {
            self.len += 1;
        }
        old_value
    }

    fn insert_rec(
        node: Option<Box<AVLNode<K, V>>>,
        key: K,
        value: V,
        old_value: &mut Option<V>,
        inserted: &mut bool,
    ) -> Option<Box<AVLNode<K, V>>> {
        let mut current = match node {
            Some(n) => n,
            None => {
                *inserted = true;
                return Some(Box::new(AVLNode::new(key, value)));
            }
        };

        match key.cmp(&current.key) {
            Ordering::Less => {
                current.left =
                    Self::insert_rec(current.left.take(), key, value, old_value, inserted);
            }
            Ordering::Greater => {
                current.right =
                    Self::insert_rec(current.right.take(), key, value, old_value, inserted);
            }
            Ordering::Equal => {
                *old_value = Some(std::mem::replace(&mut current.value, value));
                return Some(current);
            }
        }

        Some(current.rebalance())
    }

    /// Supprime la clé et sa valeur associée de l'arbre.
    ///
    /// Retourne la valeur si trouvée, sinon `None`.
    pub fn remove(&mut self, key: &K) -> Option<V> {
        let mut removed_value = None;
        let root = self.root.take();
        self.root = Self::remove_rec(root, key, &mut removed_value);
        if removed_value.is_some() {
            self.len -= 1;
        }
        removed_value
    }

    fn remove_rec(
        node: Option<Box<AVLNode<K, V>>>,
        key: &K,
        removed_value: &mut Option<V>,
    ) -> Option<Box<AVLNode<K, V>>> {
        let mut current = match node {
            Some(n) => n,
            None => return None,
        };

        match key.cmp(&current.key) {
            Ordering::Less => {
                current.left = Self::remove_rec(current.left.take(), key, removed_value);
                Some(current.rebalance())
            }
            Ordering::Greater => {
                current.right = Self::remove_rec(current.right.take(), key, removed_value);
                Some(current.rebalance())
            }
            Ordering::Equal => {
                *removed_value = Some(current.value);
                match (current.left.take(), current.right.take()) {
                    (None, None) => None,
                    (Some(left), None) => Some(left),
                    (None, Some(right)) => Some(right),
                    (Some(left), Some(right)) => {
                        let (successor, new_right) = Self::extract_min(right);
                        let mut new_root = successor;
                        new_root.left = Some(left);
                        new_root.right = new_right;
                        Some(new_root.rebalance())
                    }
                }
            }
        }
    }

    /// Extrait le nœud minimum d'un sous-arbre pour la substitution de suppression.
    fn extract_min(
        mut node: Box<AVLNode<K, V>>,
    ) -> (Box<AVLNode<K, V>>, Option<Box<AVLNode<K, V>>>) {
        if let Some(left) = node.left.take() {
            let (min_node, new_left) = Self::extract_min(left);
            node.left = new_left;
            (min_node, Some(node.rebalance()))
        } else {
            let right = node.right.take();
            (node, right)
        }
    }

    /// Parcourt l'arbre dans l'ordre croissant (in-order) et produit les paires (&K, &V).
    pub fn iter(&self) -> InOrderIter<'_, K, V> {
        let mut iter = InOrderIter { stack: Vec::new() };
        iter.push_left_path(self.root.as_deref());
        iter
    }

    /// Valide l'ensemble des invariants d'un arbre AVL :
    /// 1. Propriété d'ordre de recherche binaire stricte (BST).
    /// 2. Exactitude des hauteurs mémorisées dans chaque nœud.
    /// 3. Facteur d'équilibrage dans [-1, 1].
    /// 4. Cohérence du nombre d'éléments enregistrés (`len`).
    pub fn validate_invariants(&self) -> Result<(), ValidationError>
    where
        K: Debug,
    {
        let (actual_size, actual_height) =
            Self::validate_node_recursive(self.root.as_deref(), None, None)?;

        if actual_size != self.len {
            return Err(ValidationError::SizeMismatch {
                recorded_size: self.len,
                actual_size,
            });
        }

        if actual_height != self.height() {
            return Err(ValidationError::HeightMismatch {
                expected: actual_height,
                actual: self.height(),
            });
        }

        Ok(())
    }

    fn validate_node_recursive<'a>(
        node: Option<&'a AVLNode<K, V>>,
        min_bound: Option<&'a K>,
        max_bound: Option<&'a K>,
    ) -> Result<(usize, usize), ValidationError>
    where
        K: Debug,
    {
        let current = match node {
            Some(n) => n,
            None => return Ok((0, 0)),
        };

        // 1. Validation de l'ordre BST
        if let Some(min) = min_bound {
            if current.key <= *min {
                return Err(ValidationError::BstOrderViolation(format!(
                    "Clé {:?} <= borne minimale {:?}",
                    current.key, min
                )));
            }
        }
        if let Some(max) = max_bound {
            if current.key >= *max {
                return Err(ValidationError::BstOrderViolation(format!(
                    "Clé {:?} >= borne maximale {:?}",
                    current.key, max
                )));
            }
        }

        // Vérification récursive sous-arbres gauche et droit
        let (left_size, left_height) =
            Self::validate_node_recursive(current.left.as_deref(), min_bound, Some(&current.key))?;
        let (right_size, right_height) = Self::validate_node_recursive(
            current.right.as_deref(),
            Some(&current.key),
            max_bound,
        )?;

        // 2. Vérification de la hauteur
        let expected_height = 1 + max(left_height, right_height);
        if current.height != expected_height {
            return Err(ValidationError::HeightMismatch {
                expected: expected_height,
                actual: current.height,
            });
        }

        // 3. Vérification du facteur d'équilibrage
        let bf = (left_height as isize) - (right_height as isize);
        if !(-1..=1).contains(&bf) {
            return Err(ValidationError::UnbalancedNode { balance_factor: bf });
        }

        let total_size = 1 + left_size + right_size;
        Ok((total_size, expected_height))
    }
}

/// Itérateur in-order garantissant un parcours trié en $\mathcal{O}(n)$.
pub struct InOrderIter<'a, K, V> {
    stack: Vec<&'a AVLNode<K, V>>,
}

impl<'a, K, V> InOrderIter<'a, K, V> {
    fn push_left_path(&mut self, mut current: Option<&'a AVLNode<K, V>>) {
        while let Some(node) = current {
            self.stack.push(node);
            current = node.left.as_deref();
        }
    }
}

impl<'a, K, V> Iterator for InOrderIter<'a, K, V> {
    type Item = (&'a K, &'a V);

    fn next(&mut self) -> Option<Self::Item> {
        let node = self.stack.pop()?;
        self.push_left_path(node.right.as_deref());
        Some((&node.key, &node.value))
    }
}

impl<'a, K: Ord, V> IntoIterator for &'a AVLTree<K, V> {
    type Item = (&'a K, &'a V);
    type IntoIter = InOrderIter<'a, K, V>;

    fn into_iter(self) -> Self::IntoIter {
        self.iter()
    }
}

