/// ChaCha20 Constants: "expand 32-byte k" en Little-Endian u32
const CONSTANTS: [u32; 4] = [0x6170_7865, 0x3320_646e, 0x7962_2d32, 0x6b20_6574];
const BLOCK_SIZE: usize = 64;

/// Structure de base du chiffrement par flot ChaCha20
#[derive(Debug, Clone)]
pub struct ChaCha20 {
    state: [u32; 16],
}

impl ChaCha20 {
    /// Initialise le bloc d'état ChaCha20 conformément à la RFC 8439 Section 2.3
    /// - `key`: Clé secrète de 32 octets (256 bits)
    /// - `counter`: Compteur de bloc de 32 bits (généralement 1 ou 0)
    /// - `nonce`: Nonce de 12 octets (96 bits)
    pub fn new(key: &[u8; 32], counter: u32, nonce: &[u8; 12]) -> Self {
        let mut state = [0u32; 16];

        // Constantes (mots 0..3)
        state[0] = CONSTANTS[0];
        state[1] = CONSTANTS[1];
        state[2] = CONSTANTS[2];
        state[3] = CONSTANTS[3];

        // Clé 256 bits (mots 4..11)
        for i in 0..8 {
            let offset = i * 4;
            state[4 + i] = u32::from_le_bytes([
                key[offset],
                key[offset + 1],
                key[offset + 2],
                key[offset + 3],
            ]);
        }

        // Compteur de bloc (mot 12)
        state[12] = counter;

        // Nonce 96 bits (mots 13..15)
        for i in 0..3 {
            let offset = i * 4;
            state[13 + i] = u32::from_le_bytes([
                nonce[offset],
                nonce[offset + 1],
                nonce[offset + 2],
                nonce[offset + 3],
            ]);
        }

        Self { state }
    }

    /// Applique l'opération élémentaire Quart de Round (ARX) sur 4 indices de l'état
    #[inline(always)]
    fn quarter_round(state: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize) {
        state[a] = state[a].wrapping_add(state[b]);
        state[d] = (state[d] ^ state[a]).rotate_left(16);

        state[c] = state[c].wrapping_add(state[d]);
        state[b] = (state[b] ^ state[c]).rotate_left(12);

        state[a] = state[a].wrapping_add(state[b]);
        state[d] = (state[d] ^ state[a]).rotate_left(8);

        state[c] = state[c].wrapping_add(state[d]);
        state[b] = (state[b] ^ state[c]).rotate_left(7);
    }

    /// Génère un bloc de 64 octets de keystream à partir de l'état actuel
    pub fn generate_block(&self) -> [u8; BLOCK_SIZE] {
        let mut working_state = self.state;

        // 10 doubles rounds = 20 rounds au total
        for _ in 0..10 {
            // Rounds de colonnes
            Self::quarter_round(&mut working_state, 0, 4, 8, 12);
            Self::quarter_round(&mut working_state, 1, 5, 9, 13);
            Self::quarter_round(&mut working_state, 2, 6, 10, 14);
            Self::quarter_round(&mut working_state, 3, 7, 11, 15);

            // Rounds de diagonales
            Self::quarter_round(&mut working_state, 0, 5, 10, 15);
            Self::quarter_round(&mut working_state, 1, 6, 11, 12);
            Self::quarter_round(&mut working_state, 2, 7, 8, 13);
            Self::quarter_round(&mut working_state, 3, 4, 9, 14);
        }

        // Addition terme à terme avec l'état initial
        let mut output = [0u8; BLOCK_SIZE];
        for i in 0..16 {
            let sum = working_state[i].wrapping_add(self.state[i]);
            let bytes = sum.to_le_bytes();
            output[i * 4..(i + 1) * 4].copy_from_slice(&bytes);
        }

        output
    }

    /// Incrémente le compteur de bloc
    pub fn increment_counter(&mut self) {
        self.state[12] = self.state[12].wrapping_add(1);
    }

    /// Obtient une vue de l'état actuel de 16 mots de 32 bits
    pub fn state(&self) -> &[u32; 16] {
        &self.state
    }

    /// Chiffre ou déchiffre un flux d'octets quelconque en utilisant le keystream généré
    pub fn process(&mut self, data: &[u8]) -> Vec<u8> {
        let mut result = Vec::with_capacity(data.len());
        let mut chunks = data.chunks(BLOCK_SIZE);

        for chunk in chunks.by_ref() {
            let keystream_block = self.generate_block();
            for (&byte, &key_byte) in chunk.iter().zip(keystream_block.iter()) {
                result.push(byte ^ key_byte);
            }
            self.increment_counter();
        }

        result
    }
}

/// CLI pour l'étude et la manipulation du chiffrement ChaCha20
