        /// Nonce en hexadécimal (24 caractères hex = 12 octets)
        #[arg(short, long)]
        nonce: String,

        /// Compteur initial (défaut: 1, standard IETF pour les messages chiffrés)
        #[arg(short, long, default_value_t = 1)]
        counter: u32,

        /// Texte clair en chaîne de caractères
        #[arg(short, long, conflicts_with = "input_file")]
        text: Option<String>,

        /// Chemin vers un fichier d'entrée
        #[arg(long, conflicts_with = "text")]
        input_file: Option<PathBuf>,

        /// Chemin vers un fichier de sortie pour les données chiffrées (binaire)
        #[arg(long)]
        output_file: Option<PathBuf>,
    },

    /// Déchiffre une chaîne hexadécimale ou un fichier chiffré
    Decrypt {
        /// Clé de déchiffrement en hexadécimal (64 caractères hex = 32 octets)
        #[arg(short, long)]
        key: String,

        /// Nonce en hexadécimal (24 caractères hex = 12 octets)
        #[arg(short, long)]
        nonce: String,

        /// Compteur initial (doit correspondre à celui utilisé lors du chiffrement)
        #[arg(short, long, default_value_t = 1)]
        counter: u32,

        /// Texte chiffré en hexadécimal
        #[arg(short = 'd', long, conflicts_with = "input_file")]
        hex_data: Option<String>,

        /// Fichier binaire chiffré
        #[arg(long, conflicts_with = "hex_data")]
        input_file: Option<PathBuf>,

        /// Fichier de sortie déchiffré
        #[arg(long)]
        output_file: Option<PathBuf>,
    },

    /// Affiche les détails internes du premier bloc de keystream (analyse cryptographique)
    InspectKeystream {
        /// Clé en hexadécimal (64 hex)
        #[arg(short, long)]
        key: String,

        /// Nonce en hexadécimal (24 hex)
        #[arg(short, long)]
        nonce: String,

        /// Valeur du compteur (défaut: 0)
        #[arg(short, long, default_value_t = 0)]
        counter: u32,
    },

    /// Génère une clé pseudo-aléatoire (256 bits) et un nonce (96 bits)
    GenerateKey,

    /// Exécute la vérification des vecteurs de test officiels RFC 8439
    TestVector,
}

fn parse_hex_key(hex_str: &str) -> Result<[u8; 32]> {
    let bytes = hex::decode(hex_str).context("Impossible de décoder la clé hexadécimale")?;
    if bytes.len() != 32 {
        bail!(
            "La clé doit faire exactement 32 octets (64 caractères hexadécimaux), reçu {} octets",
            bytes.len()
        );
    }
    let mut key = [0u8; 32];
    key.copy_from_slice(&bytes);
    Ok(key)
}

fn parse_hex_nonce(hex_str: &str) -> Result<[u8; 12]> {
    let bytes = hex::decode(hex_str).context("Impossible de décoder le nonce hexadécimal")?;
    if bytes.len() != 12 {
        bail!(
            "Le nonce doit faire exactement 12 octets (24 caractères hexadécimaux), reçu {} octets",
            bytes.len()
        );
    }
    let mut nonce = [0u8; 12];
    nonce.copy_from_slice(&bytes);
    Ok(nonce)
}

/// Générateur simple de pseudo-entropie pour la commande pédagogique generate-key
fn pseudo_random_bytes(len: usize) -> Vec<u8> {
    let mut buf = Vec::with_capacity(len);
    let mut seed = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(42);

    for i in 0..len {
        // Linear Congruential Generator simple avec mixage
        seed = seed
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407 + i as u128);
        buf.push(((seed >> 32) ^ (seed >> 16)) as u8);
    }
    buf
}

fn print_matrix_u32(matrix: &[u32; 16]) {
    for row in 0..4 {
        print!("  [");
        for col in 0..4 {
            print!(" 0x{:08x}", matrix[row * 4 + col]);
        }
        println!(" ]");
    }
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::GenerateKey => {
            let key = pseudo_random_bytes(32);
            let nonce = pseudo_random_bytes(12);

            println!("=== Paramètres générés pour ChaCha20 ===");
            println!("Clé (256 bits) : {}", hex::encode(&key));
            println!("Nonce (96 bits): {}", hex::encode(&nonce));
            println!("Exemple d'usage :");
            println!(
                "  cargo run -- encrypt --key {} --nonce {} --text \"Message secret\"",
                hex::encode(&key),
                hex::encode(&nonce)
            );
        }

        Commands::InspectKeystream {
            key,
            nonce,
            counter,
        } => {
            let key_bytes = parse_hex_key(&key)?;
            let nonce_bytes = parse_hex_nonce(&nonce)?;

            let cipher = ChaCha20::new(&key_bytes, counter, &nonce_bytes);
            let block = cipher.generate_block();

            println!("=== Analyse d'état ChaCha20 (RFC 8439) ===");
            println!("Compteur de bloc: {}", counter);
            println!("\n1. État initial (16 mots u32):");
            print_matrix_u32(cipher.state());

            println!("\n2. Bloc de flux de clé généré (64 octets / 512 bits):");
            println!("{}", hex::encode(block));

            println!("\n3. Visualisation hexadécimale formatée par bloc de 16 octets :");
            for (idx, line) in block.chunks(16).enumerate() {
                print!("  {:02x}..{:02x}: ", idx * 16, idx * 16 + 15);
                for b in line {
                    print!("{:02x} ", b);
                }
                println!();
            }
        }

        Commands::Encrypt {
            key,
            nonce,
            counter,
            text,
            input_file,
            output_file,
        } => {
            let key_bytes = parse_hex_key(&key)?;
            let nonce_bytes = parse_hex_nonce(&nonce)?;

            let raw_data = match (text, input_file) {
                (Some(txt), None) => txt.into_bytes(),
                (None, Some(path)) => fs::read(&path)
                    .with_context(|| format!("Lecture échouée du fichier {:?}", path))?,
                _ => bail!("Veuillez spécifier soit --text soit --input-file"),
            };

            let mut cipher = ChaCha20::new(&key_bytes, counter, &nonce_bytes);
            let encrypted = cipher.process(&raw_data);

            if let Some(out_path) = output_file {
                fs::write(&out_path, &encrypted)
                    .with_context(|| format!("Écriture échouée dans {:?}", out_path))?;
                println!("Données chiffrées avec succès écrites dans {:?}", out_path);
            } else {
                println!("=== Données chiffrées (Hex) ===");
                println!("{}", hex::encode(&encrypted));
            }
        }

        Commands::Decrypt {
            key,
            nonce,
            counter,
            hex_data,
            input_file,
            output_file,
        } => {
            let key_bytes = parse_hex_key(&key)?;
            let nonce_bytes = parse_hex_nonce(&nonce)?;

            let encrypted_data = match (hex_data, input_file) {
                (Some(hex_str), None) => hex::decode(hex_str.trim())
                    .context("Décodage des données hexadécimales échoué")?,
                (None, Some(path)) => fs::read(&path)
                    .with_context(|| format!("Lecture échouée du fichier {:?}", path))?,
                _ => bail!("Veuillez spécifier soit --hex-data soit --input-file"),
            };

            let mut cipher = ChaCha20::new(&key_bytes, counter, &nonce_bytes);
            let decrypted = cipher.process(&encrypted_data);

            if let Some(out_path) = output_file {
                fs::write(&out_path, &decrypted)
                    .with_context(|| format!("Écriture échouée dans {:?}", out_path))?;
                println!(
                    "Données déchiffrées avec succès écrites dans {:?}",
                    out_path
                );
            } else {
                match String::from_utf8(decrypted.clone()) {
                    Ok(txt) => {
                        println!("=== Données déchiffrées (UTF-8) ===");
                        println!("{}", txt);
                    }
                    Err(_) => {
                        println!("=== Données déchiffrées (Données binaires non UTF-8, Hex) ===");
                        println!("{}", hex::encode(&decrypted));
                    }
                }
            }
        }

        Commands::TestVector => {
            println!("Exécution de la validation par rapport aux vecteurs officiels RFC 8439...");
            run_rfc_test_vectors()?;
            println!("✓ Tous les vecteurs de test de référence ont validé l'implémentation.");
        }
    }

    Ok(())
}

fn run_rfc_test_vectors() -> Result<()> {
    // RFC 8439 Section 2.3.2 : Test Vector for the ChaCha20 Block Function
    let key_bytes = [
        0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e,
        0x0f, 0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, 0x18, 0x19, 0x1a, 0x1b, 0x1c, 0x1d,
        0x1e, 0x1f,
    ];
    let nonce_block = [
        0x00, 0x00, 0x00, 0x09, 0x00, 0x00, 0x00, 0x4a, 0x00, 0x00, 0x00, 0x00,
    ];
    let counter_block = 1u32;

    let cipher = ChaCha20::new(&key_bytes, counter_block, &nonce_block);
    let block = cipher.generate_block();

    let expected_block_hex = concat!(
        "10f1e7e4d13b5915500fdd1fa32071c4c7d1f4c733c068030422aa9ac3d46c4e",
        "d2826446079faa0914c2d705d98b02a2b5129cd1de164eb9cbd083e8a2503c4e"
    );

    let generated_hex = hex::encode(block);
    if generated_hex != expected_block_hex {
        bail!(
            "Échec du test de bloc RFC 8439 Section 2.3.2.\nAttendu : {}\nObtenu  : {}",
            expected_block_hex,
            generated_hex
        );
    }
    println!("  [OK] Section 2.3.2 : Génération de bloc ChaCha20 valide.");

    // RFC 8439 Section 2.4.2 : Test Vector for ChaCha20 Encryption
    let nonce_cipher = [
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x4a, 0x00, 0x00, 0x00, 0x00,
    ];
    let counter_cipher = 1u32;
    let plaintext = b"Ladies and Gentlemen of the class of '99: If I could offer you only one tip for the future, sunscreen would be it.";
    let mut encrypter = ChaCha20::new(&key_bytes, counter_cipher, &nonce_cipher);
    let ciphertext = encrypter.process(plaintext);

    let expected_cipher_hex = concat!(
        "6e2e359a2568f98041ba0728dd0d6981e97e7aec1d4360c20a27afccfd9fae0b",
        "f91b65c5524733ab8f593dabcd62b3571639d624e65152ab8f530c359f0861d8",
        "07ca0dbf500d6a6156a38e088a22b65e52bc514d16ccf806818ce91ab7793736",
        "5af90bbf74a35be6b40b8eedf2785e42874d"
    );

    let generated_cipher_hex = hex::encode(&ciphertext);
    if generated_cipher_hex != expected_cipher_hex {
        bail!(
            "Échec du test de chiffrement RFC 8439 Section 2.4.2.\nAttendu : {}\nObtenu  : {}",
            expected_cipher_hex,
            generated_cipher_hex
        );
    }
    println!("  [OK] Section 2.4.2 : Chiffrement du message de test valide.");

    // Test de réversibilité (Déchiffrement)
    let mut decrypter = ChaCha20::new(&key_bytes, counter_cipher, &nonce_cipher);
    let decrypted = decrypter.process(&ciphertext);
    if decrypted != plaintext {
        bail!("Échec de réversibilité symétrique : les données déchiffrées diffèrent du texte en clair.");
    }
    println!("  [OK] Réversibilité symétrique (Déchiffrement) validée.");

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_quarter_round_vector() {
        // RFC 8439 Section 2.1.1
        let mut state = [0u32; 16];
        state[0] = 0x11111111;
        state[1] = 0x01020304;
        state[2] = 0x9b8d6f43;
        state[3] = 0x01234567;

        ChaCha20::quarter_round(&mut state, 0, 1, 2, 3);

        assert_eq!(state[0], 0xea2a92f4);
        assert_eq!(state[1], 0xcb1cf8ce);
        assert_eq!(state[2], 0x4581472e);
        assert_eq!(state[3], 0x5881c4bb);
    }

    #[test]
    fn test_rfc_compliance() {
        assert!(run_rfc_test_vectors().is_ok());
    }

    #[test]
    fn test_multi_block_encryption_decryption() {
        let key = [42u8; 32];
        let nonce = [7u8; 12];
        let counter = 1;

        // Message plus grand qu'un bloc de 64 octets (150 octets)
        let message = vec![0xAB; 150];

        let mut enc = ChaCha20::new(&key, counter, &nonce);
        let cipher = enc.process(&message);
        assert_ne!(cipher, message);

        let mut dec = ChaCha20::new(&key, counter, &nonce);
        let roundtrip = dec.process(&cipher);
        assert_eq!(roundtrip, message);
    }
}

