// src/main.rs
use std::sync::mpsc::{channel, Receiver, SendError, Sender};
use std::thread::{self, JoinHandle};
use thiserror::Error;

/// Erreurs possibles lors de l'interaction avec les acteurs.
#[derive(Debug, Error)]
pub enum ActorError {
    #[error("Échec d'envoi du message : le récepteur de l'acteur a été détruit")]
    MailboxClosed,
    #[error("Échec de réception de la réponse : l'acteur n'a pas répondu")]
    ResponseDropped,
    #[error("Le thread de l'acteur a paniqué lors de son exécution")]
    ThreadPanicked,
}

impl<T> From<SendError<T>> for ActorError {
    fn from(_: SendError<T>) -> Self {
        ActorError::MailboxClosed
    }
}

/// Directive de cycle de vie renvoyée après le traitement de chaque message.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Directive {
    /// Poursuivre la boucle d'événements.
    Continue,
    /// Terminer proprement le thread de l'acteur.
    Stop,
}

/// Trait définissant le comportement d'un acteur.
pub trait Actor: Send + 'static {
    type Message: Send + 'static;

    /// Traite un message reçu et renvoie une directive pour le cycle de vie de l'acteur.
    fn handle(&mut self, msg: Self::Message) -> Directive;

    /// Méthode exécutée avant de démarrer la boucle d'événements.
    fn started(&mut self) {}

    /// Méthode exécutée avant l'arrêt final du thread.
    fn stopped(&mut self) {}
}

/// Référence clonable et partageable (`Send + Sync`) vers la boîte aux lettres d'un acteur.
pub struct ActorRef<M> {
    sender: Sender<M>,
}

impl<M> Clone for ActorRef<M> {
    fn clone(&self) -> Self {
        Self {
            sender: self.sender.clone(),
        }
    }
}

impl<M> ActorRef<M> {
    pub fn new(sender: Sender<M>) -> Self {
        Self { sender }
    }

    /// Envoie asynchrone ("tell" ou "fire-and-forget").
    pub fn tell(&self, msg: M) -> Result<(), ActorError> {
        self.sender.send(msg).map_err(|_| ActorError::MailboxClosed)
    }

    /// Envoie synchrone ("call" / request-response) vers un acteur.
    ///
    /// Cette méthode crée un canal de retour éphémère (`oneshot`) et attend
    /// de manière bloquante la réponse de l'acteur.
    pub fn call<R: Send + 'static, F>(&self, make_msg: F) -> Result<R, ActorError>
    where
        F: FnOnce(Sender<R>) -> M,
    {
        let (reply_tx, reply_rx) = channel();
        let msg = make_msg(reply_tx);
        self.tell(msg)?;
        reply_rx.recv().map_err(|_| ActorError::ResponseDropped)
    }
}

/// Contrôleur du cycle de vie d'un acteur gérant son thread dédié.
pub struct ActorHandle<M> {
    actor_ref: ActorRef<M>,
    join_handle: Option<JoinHandle<()>>,
}

impl<M> ActorHandle<M> {
    pub fn actor_ref(&self) -> ActorRef<M> {
        self.actor_ref.clone()
    }

    /// Attend l'arrêt du thread de l'acteur.
    pub fn join(mut self) -> Result<(), ActorError> {
        if let Some(handle) = self.join_handle.take() {
            handle.join().map_err(|_| ActorError::ThreadPanicked)
        } else {
            Ok(())
        }
    }
}

/// Système et superviseur d'acteurs gérant l'instanciation et l'arrêt propre.
pub struct ActorSystem {
    shutdown_hooks: Vec<Box<dyn FnOnce() -> Result<(), ActorError>>>,
}

impl ActorSystem {
    pub fn new() -> Self {
        Self {
            shutdown_hooks: Vec::new(),
        }
    }

    /// Fait spawner un acteur dans son propre thread système avec un canal mpsc dédié.
    pub fn spawn<A>(&mut self, mut actor: A, thread_name: Option<String>) -> (ActorRef<A::Message>, ActorHandle<A::Message>)
    where
        A: Actor,
    {
        let (tx, rx): (Sender<A::Message>, Receiver<A::Message>) = channel();
        let actor_ref = ActorRef::new(tx);
        let actor_ref_clone = actor_ref.clone();

        let mut builder = thread::Builder::new();
        if let Some(name) = thread_name {
            builder = builder.name(name);
        }

        let join_handle = builder
            .spawn(move || {
                actor.started();
                while let Ok(msg) = rx.recv() {
                    match actor.handle(msg) {
                        Directive::Continue => {}
                        Directive::Stop => break,
                    }
                }
                actor.stopped();
            })
            .expect("Impossible d'allouer un thread pour l'acteur");

        let handle = ActorHandle {
            actor_ref: actor_ref_clone,
            join_handle: Some(join_handle),
        };

        (actor_ref, handle)
    }

    /// Enregistre une poignée d'acteur pour un arrêt automatique lors du shutdown du système.
    pub fn manage<M: 'static>(&mut self, handle: ActorHandle<M>) {
        self.shutdown_hooks.push(Box::new(move || handle.join()));
    }

    /// Attend l'arrêt de tous les acteurs enregistrés.
    pub fn shutdown(self) -> Result<(), ActorError> {
        for hook in self.shutdown_hooks {
            hook()?;
        }
        Ok(())
    }
}

// -----------------------------------------------------------------------------
// EXEMPLE D'APPLICATION : Compte Bancaire et Audit
// -----------------------------------------------------------------------------

/// Messages supportés par l'acteur de compte bancaire.
pub enum AccountMessage {
    Deposit(u64),
    Withdraw {
        amount: u64,
        reply_to: Sender<Result<u64, String>>,
    },
    GetBalance(Sender<u64>),
    Stop,
}

/// Acteur maintenant le solde d'un compte.
pub struct BankAccountActor {
    account_id: String,
    balance: u64,
}

impl BankAccountActor {
    pub fn new(account_id: impl Into<String>, initial_balance: u64) -> Self {
        Self {
            account_id: account_id.into(),
            balance: initial_balance,
        }
    }
}

impl Actor for BankAccountActor {
    type Message = AccountMessage;

    fn started(&mut self) {
        println!(
            "[{}] Compte activé avec un solde initial de {} €.",
            self.account_id, self.balance
        );
    }

    fn handle(&mut self, msg: Self::Message) -> Directive {
        match msg {
            AccountMessage::Deposit(amount) => {
                self.balance += amount;
                println!(
                    "[{}] Dépôt de {} €. Nouveau solde : {} €",
                    self.account_id, amount, self.balance
                );
                Directive::Continue
            }
            AccountMessage::Withdraw { amount, reply_to } => {
                if self.balance >= amount {
                    self.balance -= amount;
                    let _ = reply_to.send(Ok(self.balance));
                } else {
                    let _ = reply_to.send(Err(format!(
                        "Fonds insuffisants : solde de {} € pour un retrait de {} €",
                        self.balance, amount
                    )));
                }
                Directive::Continue
            }
            AccountMessage::GetBalance(reply_to) => {
                let _ = reply_to.send(self.balance);
                Directive::Continue
            }
            AccountMessage::Stop => {
                println!("[{}] Demande d'arrêt reçue.", self.account_id);
                Directive::Stop
            }
        }
    }

    fn stopped(&mut self) {
        println!(
            "[{}] Compte clôturé. Solde final : {} €.",
            self.account_id, self.balance
        );
    }
}

/// Messages pour l'acteur d'audit / journalisation.
pub enum AuditMessage {
    Log(String),
    Stop,
}

pub struct AuditActor;

impl Actor for AuditActor {
    type Message = AuditMessage;

    fn handle(&mut self, msg: Self::Message) -> Directive {
        match msg {
            AuditMessage::Log(entry) => {
                println!("[AUDIT] {}", entry);
                Directive::Continue
            }
            AuditMessage::Stop => Directive::Stop,
        }
    }
}

fn main() -> Result<(), ActorError> {
    println!("=== Démarrage du système d'acteurs synchrones ===");

    let mut system = ActorSystem::new();

    // 1. Spawning de l'acteur d'audit
    let (audit_ref, audit_handle) =
        system.spawn(AuditActor, Some("audit-worker".to_string()));
    system.manage(audit_handle);

    // 2. Spawning de deux acteurs de compte bancaire
    let (acc1_ref, acc1_handle) =
        system.spawn(BankAccountActor::new("FR76-0001", 100), Some("acc-1".to_string()));
    let (acc2_ref, acc2_handle) =
        system.spawn(BankAccountActor::new("FR76-0002", 50), Some("acc-2".to_string()));

    system.manage(acc1_handle);
    system.manage(acc2_handle);

    // Communication asynchrone (tell)
    audit_ref.tell(AuditMessage::Log("Initialisation des comptes effectuée".into()))?;
    acc1_ref.tell(AccountMessage::Deposit(50))?;

    // Communication synchrone (call) : Vérification de solde
    let balance_1: u64 = acc1_ref.call(AccountMessage::GetBalance)?;
    println!("-> Appel synchrone : Solde de acc1 = {} €", balance_1);

    // Communication synchrone (call) : Retrait valide
    let withdraw_res = acc1_ref.call(|reply_to| AccountMessage::Withdraw {
        amount: 30,
        reply_to,
    })?;
    match withdraw_res {
        Ok(new_balance) => println!("-> Retrait réussi de 30 € sur acc1. Reste : {} €", new_balance),
        Err(e) => println!("-> Retrait échoué : {}", e),
    }

    // Communication synchrone (call) : Retrait invalide
    let withdraw_invalid = acc2_ref.call(|reply_to| AccountMessage::Withdraw {
        amount: 200,
        reply_to,
    })?;
    match withdraw_invalid {
        Ok(new_balance) => println!("-> Retrait réussi : {} €", new_balance),
        Err(e) => println!("-> Erreur attendue sur acc2 : {}", e),
    }

    // Arrêt gracieux des acteurs
    println!("\n=== Envoi des signaux d'arrêt ===");
    acc1_ref.tell(AccountMessage::Stop)?;
    acc2_ref.tell(AccountMessage::Stop)?;
    audit_ref.tell(AuditMessage::Stop)?;

    // Attente et synchronisation complète de tous les threads
    system.shutdown()?;
    println!("=== Système d'acteurs arrêté avec succès ===");

    Ok(())
}

