    /// Largeur de l'image générée en pixels (ou caractères)
    #[arg(short = 'W', long)]
    width: Option<usize>,

    /// Hauteur de l'image générée en pixels (ou lignes)
    #[arg(short = 'H', long)]
    height: Option<usize>,

    /// Nombre maximal d'itérations pour le calcul d'échappement
    #[arg(short = 'i', long, default_value_t = 500)]
    max_iter: u32,

    /// Chemin du fichier de sortie
    #[arg(short, long)]
    output: Option<PathBuf>,

    /// Borne inférieure sur l'axe réel (X min)
    #[arg(long, default_value_t = -2.0)]
    x_min: f64,

    /// Borne supérieure sur l'axe réel (X max)
    #[arg(long, default_value_t = 0.47)]
    x_max: f64,

    /// Borne inférieure sur l'axe imaginaire (Y min)
    #[arg(long, default_value_t = -1.12)]
    y_min: f64,

    /// Borne supérieure sur l'axe imaginaire (Y max)
    #[arg(long, default_value_t = 1.12)]
    y_max: f64,
}

/// Structure représentant un pixel en couleur RVB (8 bits par canal)
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Rgb {
    r: u8,
    g: u8,
    b: u8,
}

/// Calcule le nombre d'itérations avant divergence pour le point complexe c = (c_re + i * c_im)
/// Retourne `None` si le point appartient à l'ensemble (n'a pas divergé).
fn mandelbrot_divergence(c_re: f64, c_im: f64, max_iter: u32) -> Option<u32> {
    // Optimisation rapide : vérification de l'appartenance à la cardioïde principale
    let c_im2 = c_im * c_im;
    let q = (c_re - 0.25).powi(2) + c_im2;
    if q * (q + (c_re - 0.25)) <= 0.25 * c_im2 {
        return None;
    }

    // Optimisation rapide : vérification du bulbe de période 2
    if (c_re + 1.0).powi(2) + c_im2 <= 0.0625 {
        return None;
    }

    let mut z_re = 0.0;
    let mut z_im = 0.0;
    let mut z_re2 = 0.0;
    let mut z_im2 = 0.0;

    for i in 0..max_iter {
        z_im = 2.0 * z_re * z_im + c_im;
        z_re = z_re2 - z_im2 + c_re;
        z_re2 = z_re * z_re;
        z_im2 = z_im * z_im;

        if z_re2 + z_im2 > 4.0 {
            return Some(i);
        }
    }

    None
}

/// Convertit un nombre d'itérations en couleur RVB lissée via une palette cosinus
fn iteration_to_rgb(iteration: Option<u32>, max_iter: u32) -> Rgb {
    match iteration {
        None => Rgb { r: 0, g: 0, b: 0 }, // Intérieur de l'ensemble de Mandelbrot : noir
        Some(i) => {
            let t = i as f64 / max_iter as f64;
            // Palette basée sur des fonctions trigonométriques pour un dégradé continu
            let tau = std::f64::consts::TAU;
            let r = ((0.5 + 0.5 * (tau * (1.0 * t + 0.0)).cos()) * 255.0) as u8;
            let g = ((0.5 + 0.5 * (tau * (1.0 * t + 0.33)).cos()) * 255.0) as u8;
            let b = ((0.5 + 0.5 * (tau * (1.0 * t + 0.67)).cos()) * 255.0) as u8;
            Rgb { r, g, b }
        }
    }
}

/// Convertit un nombre d'itérations en caractère ASCII proportionnel
fn iteration_to_ascii(iteration: Option<u32>, max_iter: u32) -> char {
    const CHARSET: &[u8] = b" .:-=+*#%@";
    match iteration {
        None => '@', // Intérieur
        Some(i) => {
            let idx = ((i as f64 / max_iter as f64) * (CHARSET.len() - 1) as f64).round() as usize;
            CHARSET[idx.min(CHARSET.len() - 1)] as char
        }
    }
}

/// Écrit une image Bitmap 24-bit (non compressée) sur disque via `std::fs::File`
fn write_bmp(path: &Path, width: usize, height: usize, pixels: &[Rgb]) -> io::Result<()> {
    if pixels.len() != width * height {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "La taille du tampon de pixels ne correspond pas aux dimensions de l'image",
        ));
    }

    let file = File::create(path)?;
    let mut writer = BufWriter::new(file);

    let row_raw_len = width * 3;
    let padding_len = (4 - (row_raw_len % 4)) % 4;
    let row_stride = row_raw_len + padding_len;
    let image_data_size = (row_stride * height) as u32;
    let file_size = 14 + 40 + image_data_size;

    // --- BITMAPFILEHEADER (14 octets) ---
    writer.write_all(b"BM")?; // Signature
    writer.write_all(&file_size.to_le_bytes())?; // Taille totale du fichier
    writer.write_all(&0u16.to_le_bytes())?; // Réservé 1
    writer.write_all(&0u16.to_le_bytes())?; // Réservé 2
    writer.write_all(&54u32.to_le_bytes())?; // Offset des données de pixels (14 + 40)

    // --- BITMAPINFOHEADER (40 octets) ---
    writer.write_all(&40u32.to_le_bytes())?; // Taille de ce header
    writer.write_all(&(width as i32).to_le_bytes())?; // Largeur en pixels
    writer.write_all(&(height as i32).to_le_bytes())?; // Hauteur positive = ordre bas vers haut
    writer.write_all(&1u16.to_le_bytes())?; // Nombre de plans
    writer.write_all(&24u16.to_le_bytes())?; // 24 bits par pixel (RGB)
    writer.write_all(&0u32.to_le_bytes())?; // Compression (0 = BI_RGB)
    writer.write_all(&image_data_size.to_le_bytes())?; // Taille des données graphiques
    writer.write_all(&2835i32.to_le_bytes())?; // Résolution horizontale (~72 DPI)
    writer.write_all(&2835i32.to_le_bytes())?; // Résolution verticale (~72 DPI)
    writer.write_all(&0u32.to_le_bytes())?; // Couleurs utilisées (0 = toutes)
    writer.write_all(&0u32.to_le_bytes())?; // Couleurs importantes

    // --- Données de pixels (ordre BMP standard : de bas en haut, canaux BGR) ---
    let padding = [0u8; 3];
    for y in (0..height).rev() {
        let row_start = y * width;
        for x in 0..width {
            let pixel = pixels[row_start + x];
            // Format BGR
            writer.write_all(&[pixel.b, pixel.g, pixel.r])?;
        }
        if padding_len > 0 {
            writer.write_all(&padding[..padding_len])?;
        }
    }

    writer.flush()?;
    Ok(())
}

/// Génère et exporte le rendu Bitmap
fn generate_bmp(cli: &Cli, width: usize, height: usize, output_path: &Path) -> io::Result<()> {
    let mut pixels = Vec::with_capacity(width * height);

    let dx = (cli.x_max - cli.x_min) / (width as f64);
    let dy = (cli.y_max - cli.y_min) / (height as f64);

    for py in 0..height {
        let c_im = cli.y_min + (py as f64) * dy;
        for px in 0..width {
            let c_re = cli.x_min + (px as f64) * dx;
            let iter = mandelbrot_divergence(c_re, c_im, cli.max_iter);
            pixels.push(iteration_to_rgb(iter, cli.max_iter));
        }
    }

    write_bmp(output_path, width, height, &pixels)?;
    println!(
        "Fractale Bitmap générée avec succès : {} ({}x{} pixels, max_iter = {})",
        output_path.display(),
        width,
        height,
        cli.max_iter
    );

    Ok(())
}

/// Génère et affiche/enregistre le rendu ASCII
fn generate_ascii(
    cli: &Cli,
    width: usize,
    height: usize,
    output_path: Option<&Path>,
) -> io::Result<()> {
    let mut buffer = String::with_capacity((width + 1) * height);

    let dx = (cli.x_max - cli.x_min) / (width as f64);
    let dy = (cli.y_max - cli.y_min) / (height as f64);

    for py in 0..height {
        let c_im = cli.y_min + (py as f64) * dy;
        for px in 0..width {
            let c_re = cli.x_min + (px as f64) * dx;
            let iter = mandelbrot_divergence(c_re, c_im, cli.max_iter);
            buffer.push(iteration_to_ascii(iter, cli.max_iter));
        }
        buffer.push('\n');
    }

    if let Some(path) = output_path {
        let file = File::create(path)?;
        let mut writer = BufWriter::new(file);
        writer.write_all(buffer.as_bytes())?;
        writer.flush()?;
        println!(
            "Fractale ASCII enregistrée dans le fichier : {} ({}x{})",
            path.display(),
            width,
            height
        );
    } else {
        print!("{buffer}");
    }

    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let cli = Cli::parse();

    // Validation des bornes
    if cli.x_min >= cli.x_max || cli.y_min >= cli.y_max {
        eprintln!("Erreur : les bornes du plan complexe sont invalides (min doit être inférieur à max).");
        std::process::exit(1);
    }

    match cli.mode {
        Mode::Bmp => {
            let width = cli.width.unwrap_or(1200);
            let height = cli.height.unwrap_or(900);
            let default_path = PathBuf::from("mandelbrot.bmp");
            let output_path = cli.output.as_ref().unwrap_or(&default_path);

            generate_bmp(&cli, width, height, output_path)?;
        }
        Mode::Ascii => {
            let width = cli.width.unwrap_or(80);
            let height = cli.height.unwrap_or(40);
            generate_ascii(&cli, width, height, cli.output.as_deref())?;
        }
    }

    Ok(())
}

