// src/main.rs
use std::fmt;

/// Erreur renvoyée lorsqu'un index fourni est en dehors des bornes du gestionnaire.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct OutOfBoundsError {
    pub index: usize,
    pub bound: usize,
}

impl fmt::Display for OutOfBoundsError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "Index {} hors limites (taille totale : {})",
            self.index, self.bound
        )
    }
}

impl std::error::Error for OutOfBoundsError {}

/// Structure de données Union-Find (Disjoint-Set Union).
///
/// Implémente la compression de chemin lors de `find` et la fusion par rang lors de `union`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct UnionFind {
    parent: Vec<usize>,
    rank: Vec<usize>,
    component_size: Vec<usize>,
    num_sets: usize,
}

impl UnionFind {
    /// Crée une nouvelle structure `UnionFind` avec `n` éléments distincts (de 0 à n - 1).
    pub fn new(n: usize) -> Self {
        let parent: Vec<usize> = (0..n).collect();
        let rank = vec![0; n];
        let component_size = vec![1; n];

        Self {
            parent,
            rank,
            component_size,
            num_sets: n,
        }
    }

    /// Nombre total d'éléments gérés.
    #[inline]
    pub fn len(&self) -> usize {
        self.parent.len()
    }

    /// Indique si la structure ne contient aucun élément.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.parent.is_empty()
    }

    /// Nombre d'ensembles disjoints actuellement présents.
    #[inline]
    pub fn set_count(&self) -> usize {
        self.num_sets
    }

    /// Recherche le représentant canonique de l'élément `x` avec compression de chemin.
    ///
    /// Retourne `None` si `x` est hors limites.
    pub fn find(&mut self, mut x: usize) -> Option<usize> {
        if x >= self.parent.len() {
            return None;
        }

        // Trouver la racine du composant
        let mut root = x;
        while root != self.parent[root] {
            root = self.parent[root];
        }

        // Compression de chemin : rattacher tous les ancêtres directement à la racine
        while x != root {
            let next = self.parent[x];
            self.parent[x] = root;
            x = next;
        }

        Some(root)
    }

    /// Fusionne les ensembles contenant `x` et `y` selon leur rang.
    ///
    /// - Retourne `Ok(true)` si une nouvelle fusion a eu lieu.
    /// - Retourne `Ok(false)` si `x` et `y` appartenaient déjà au même ensemble.
    /// - Retourne `Err(OutOfBoundsError)` si l'un des indices est invalide.
    pub fn union(&mut self, x: usize, y: usize) -> Result<bool, OutOfBoundsError> {
        let root_x = self.find(x).ok_or(OutOfBoundsError {
            index: x,
            bound: self.len(),
        })?;
        let root_y = self.find(y).ok_or(OutOfBoundsError {
            index: y,
            bound: self.len(),
        })?;

        if root_x == root_y {
            return Ok(false);
        }

        // Union par rang : la racine de plus petit rang devient enfant de la racine de plus grand rang
        if self.rank[root_x] < self.rank[root_y] {
            self.parent[root_x] = root_y;
            self.component_size[root_y] += self.component_size[root_x];
        } else if self.rank[root_x] > self.rank[root_y] {
            self.parent[root_y] = root_x;
            self.component_size[root_x] += self.component_size[root_y];
        } else {
            self.parent[root_y] = root_x;
            self.component_size[root_x] += self.component_size[root_y];
            self.rank[root_x] += 1;
        }

        self.num_sets -= 1;
        Ok(true)
    }

    /// Vérifie si deux éléments `x` et `y` appartiennent au même ensemble.
    pub fn connected(&mut self, x: usize, y: usize) -> Result<bool, OutOfBoundsError> {
        let root_x = self.find(x).ok_or(OutOfBoundsError {
            index: x,
            bound: self.len(),
        })?;
        let root_y = self.find(y).ok_or(OutOfBoundsError {
            index: y,
            bound: self.len(),
        })?;

        Ok(root_x == root_y)
    }

    /// Retourne la taille de l'ensemble contenant `x`.
    ///
    /// Retourne `None` si `x` est hors limites.
    pub fn component_size(&mut self, x: usize) -> Option<usize> {
        let root = self.find(x)?;
        Some(self.component_size[root])
    }
}

fn main() {
    println!("=== Démonstration du Gestionnaire d'Ensembles Disjoints (Union-Find) ===");

    let n = 8;
    let mut uf = UnionFind::new(n);
    println!("Initialisation avec {} éléments disjoints.", n);
    println!("Nombre d'ensembles : {}", uf.set_count());

    // Fusion de quelques arêtes (graphe non orienté)
    let connections = [(0, 1), (1, 2), (3, 4), (5, 6), (6, 7), (2, 7)];

    for &(u, v) in &connections {
        match uf.union(u, v) {
            Ok(merged) => {
                if merged {
                    println!("Fusion effectuée entre {} et {}.", u, v);
                } else {
                    println!("{} et {} appartenaient déjà au même ensemble.", u, v);
                }
            }
            Err(e) => eprintln!("Erreur lors de la fusion ({}, {}) : {}", u, v, e),
        }
    }

    println!("\nNombre d'ensembles restants : {}", uf.set_count());

    // Tests de connectivité
    let pairs_to_test = [(0, 5), (3, 5), (0, 7), (2, 6)];
    println!("\nVérification des composantes connexes :");
    for &(u, v) in &pairs_to_test {
        match uf.connected(u, v) {
            Ok(is_conn) => {
                println!(
                    "- {} et {} sont connectés ? {}",
                    u,
                    v,
                    if is_conn { "Oui" } else { "Non" }
                );
            }
            Err(e) => eprintln!("Erreur : {}", e),
        }
    }

    // Affichage des tailles de composantes
    println!("\nTailles des composantes pour quelques éléments :");
    for x in [0, 3, 5] {
        if let Some(sz) = uf.component_size(x) {
            let root = uf.find(x).unwrap_or(x);
            println!("- Élément {} (racine : {}) -> taille : {}", x, root, sz);
        }
    }

    // Gestion propre des erreurs hors limites
    let invalid_idx = 15;
    println!("\nTest avec un élément hors limites ({}) :", invalid_idx);
    match uf.find(invalid_idx) {
        Some(r) => println!("Racine : {}", r),
        None => println!("Élément {} introuvable (hors bornes).", invalid_idx),
    }

    if let Err(e) = uf.union(0, invalid_idx) {
        println!("Gestion d'erreur réussie lors de l'union : {}", e);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_initial_state() {
        let mut uf = UnionFind::new(5);
        assert_eq!(uf.len(), 5);
        assert_eq!(uf.set_count(), 5);
        assert!(!uf.is_empty());

        for i in 0..5 {
            assert_eq!(uf.find(i), Some(i));
            assert_eq!(uf.component_size(i), Some(1));
        }
    }

