    fn test_union_and_connectivity() {
        let mut uf = UnionFind::new(6);

        assert_eq!(uf.union(0, 1), Ok(true));
        assert_eq!(uf.union(1, 2), Ok(true));
        assert_eq!(uf.union(0, 2), Ok(false)); // déjà connectés

        assert_eq!(uf.connected(0, 2), Ok(true));
        assert_eq!(uf.connected(0, 3), Ok(false));
        assert_eq!(uf.set_count(), 4);
        assert_eq!(uf.component_size(0), Some(3));
        assert_eq!(uf.component_size(1), Some(3));
        assert_eq!(uf.component_size(2), Some(3));
    }

