        assert_eq!(root_1, root_3);
    }

    #[test]
    fn test_bounds_errors() {
        let mut uf = UnionFind::new(3);

        assert_eq!(uf.find(10), None);
        assert_eq!(uf.component_size(10), None);

        let err = uf.union(1, 10).unwrap_err();
        assert_eq!(
            err,
            OutOfBoundsError {
                index: 10,
                bound: 3
            }
        );

        let err2 = uf.connected(10, 1).unwrap_err();
        assert_eq!(
            err2,
            OutOfBoundsError {
                index: 10,
                bound: 3
            }
        );
    }

    #[test]
    fn test_empty_union_find() {
        let mut uf = UnionFind::new(0);
        assert_eq!(uf.len(), 0);
        assert!(uf.is_empty());
        assert_eq!(uf.set_count(), 0);
        assert_eq!(uf.find(0), None);
    }
}

