```rust
// src/main.rs
use clap::Parser;
use serde::Serialize;
use std::net::{SocketAddr, TcpStream, ToSocketAddrs};
use std::thread::sleep;
use std::time::{Duration, Instant};

#[derive(Parser, Debug)]
#[command(
    name = "netbench-cli",
    version,
    about = "Benchmark de latence pour résolutions DNS et connexions TCP",
    long_about = "Mesure avec std::time::Instant la latence de résolution DNS et d'établissement TCP vers un hôte donné."
)]
struct Cli {
    /// Cible réseau (nom d'hôte ou FQDN, ex: google.com, cloudflare.com)
    #[arg(short = 'H', long = "host", default_value = "google.com")]
    host: String,

    /// Port TCP cible
    #[arg(short = 'p', long = "port", default_value_t = 80)]
    port: u16,

    /// Nombre d'itérations
    #[arg(short = 'c', long = "count", default_value_t = 10)]
    count: usize,

    /// Délai d'attente (timeout) en millisecondes pour la connexion TCP
    #[arg(short = 't', long = "timeout-ms", default_value_t = 3000)]
    timeout_ms: u64,

    /// Intervalle d'attente en millisecondes entre les itérations
    #[arg(short = 'i', long = "interval-ms", default_value_t = 200)]
    interval_ms: u64,

    /// Sortie au format JSON pour intégration automatisée
    #[arg(long = "json")]
    json: bool,
}

#[derive(Debug, Clone, Serialize)]
struct ProbeSample {
    iteration: usize,
    dns_resolved_ip: Option<String>,
    dns_duration_ms: Option<f64>,
    tcp_duration_ms: Option<f64>,
    total_duration_ms: Option<f64>,
    error: Option<String>,
}

#[derive(Debug, Serialize)]
struct MetricSummary {
    min_ms: f64,
    max_ms: f64,
    mean_ms: f64,
    median_ms: f64,
    p95_ms: f64,
    std_dev_ms: f64,
}

#[derive(Debug, Serialize)]
struct BenchmarkReport {
    target_host: String,
    target_port: u16,
    total_samples: usize,
    successful_samples: usize,
    packet_loss_percent: f64,
    dns_metrics: Option<MetricSummary>,
    tcp_metrics: Option<MetricSummary>,
    total_metrics: Option<MetricSummary>,
    samples: Vec<ProbeSample>,
}

fn compute_summary(mut values: Vec<f64>) -> Option<MetricSummary> {
    if values.is_empty() {
        return None;
    }

    values.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let n = values.len();
    let min_ms = values[0];
    let max_ms = values[n - 1];
    let sum: f64 = values.iter().copied().sum();
    let mean_ms = sum / n as f64;

    let median_ms = if n % 2 == 1 {
        values[n / 2]
    } else {
        (values[(n / 2) - 1] + values[n / 2]) / 2.0
    };

    let p95_index = (((n as f64) * 0.95).ceil() as usize).saturating_sub(1).min(n - 1);
    let p95_ms = values[p95_index];

    let variance = values
        .iter()
        .map(|v| {
            let diff = v - mean_ms;
            diff * diff
        })
        .sum::<f64>()
        / n as f64;
    let std_dev_ms = variance.sqrt();

    Some(MetricSummary {
        min_ms,
        max_ms,
        mean_ms,
        median_ms,
        p95_ms,
        std_dev_ms,
    })
}

fn run_probe(host: &str, port: u16, timeout: Duration, iteration: usize) -> ProbeSample {
    let host_port = format!("{}:{}", host, port);

    // 1. Mesure de la résolution DNS avec std::time::Instant
    let dns_start = Instant::now();
    let resolve_result = host_port.to_socket_addrs();
    let dns_duration = dns_start.elapsed();
    let dns_duration_ms = dns_duration.as_secs_f64() * 1000.0;

    let mut addrs = match resolve_result {
        Ok(iter) => iter,
        Err(err) => {
            return ProbeSample {
                iteration,
                dns_resolved_ip: None,
                dns_duration_ms: Some(dns_duration_ms),
                tcp_duration_ms: None,
                total_duration_ms: None,
                error: Some(format!("Échec DNS: {}", err)),
            };
        }
    };

    let target_addr: SocketAddr = match addrs.next() {
        Some(addr) => addr,
        None => {
            return ProbeSample {
                iteration,
                dns_resolved_ip: None,
                dns_duration_ms: Some(dns_duration_ms),
                tcp_duration_ms: None,
                total_duration_ms: None,
                error: Some("Aucune adresse IP résolue".to_string()),
            };
        }
    };

    // 2. Mesure de la connexion TCP avec std::time::Instant
    let tcp_start = Instant::now();
    let connect_result = TcpStream::connect_timeout(&target_addr, timeout);
    let tcp_duration = tcp_start.elapsed();
    let tcp_duration_ms = tcp_duration.as_secs_f64() * 1000.0;

    match connect_result {
        Ok(stream) => {
            // Fermeture propre du flux TCP
            drop(stream);
            let total_ms = dns_duration_ms + tcp_duration_ms;
            ProbeSample {
                iteration,
                dns_resolved_ip: Some(target_addr.to_string()),
                dns_duration_ms: Some(dns_duration_ms),
                tcp_duration_ms: Some(tcp_duration_ms),
                total_duration_ms: Some(total_ms),
                error: None,
            }
        }
        Err(err) => ProbeSample {
            iteration,
            dns_resolved_ip: Some(target_addr.to_string()),
            dns_duration_ms: Some(dns_duration_ms),
            tcp_duration_ms: Some(tcp_duration_ms),
            total_duration_ms: None,
            error: Some(format!("Échec TCP ({}): {}", target_addr, err)),
        },
    }
}

fn print_summary_table(title: &str, summary: &Option<MetricSummary>) {
    match summary {
        Some(s) => {
            println!(
                "  {:<12} | Min: {:>7.2} ms | Moy: {:>7.2} ms | Méd: {:>7.2} ms | P95: {:>7.2} ms | Max: {:>7.2} ms | Écart-type: {:>6.2} ms",
                title, s.min_ms, s.mean_ms, s.median_ms, s.p95_ms, s.max_ms, s.std_dev_ms
            );
        }
        None => {
            println!("  {:<12} | Aucune donnée exploitable", title);
        }
    }
}

fn main() {
    let args = Cli::parse();

    if args.count == 0 {
        eprintln!("Erreur : Le nombre d'itérations (--count) doit être supérieur à 0.");
        std::process::exit(1);
    }

    let timeout = Duration::from_millis(args.timeout_ms);
    let interval = Duration::from_millis(args.interval_ms);

    if !args.json {
        println!("============================================================");
        println!(" Démarrage du Benchmark DNS & TCP");
        println!(" Cible      : {}:{}", args.host, args.port);
        println!(" Échantillons: {}", args.count);
        println!(" Timeout TCP: {:?} | Intervalle: {:?}", timeout, interval);
        println!("============================================================");
    }

    let mut samples: Vec<ProbeSample> = Vec::with_capacity(args.count);

    for i in 1..=args.count {
        let sample = run_probe(&args.host, args.port, timeout, i);

        if !args.json {
            match &sample.error {
                Some(err) => {
                    eprintln!("[#{:02}] ERREUR : {}", sample.iteration, err);
                }
                None => {
                    println!(
                        "[#{:02}] IP: {:<21} | DNS: {:>7.2} ms | TCP: {:>7.2} ms | Total: {:>7.2} ms",
                        sample.iteration,
                        sample.dns_resolved_ip.as_deref().unwrap_or("-"),
                        sample.dns_duration_ms.unwrap_or(0.0),
                        sample.tcp_duration_ms.unwrap_or(0.0),
                        sample.total_duration_ms.unwrap_or(0.0)
                    );
                }
            }
        }

        samples.push(sample);

        if i < args.count && !interval.is_zero() {
            sleep(interval);
        }
    }

    let successful_samples = samples.iter().filter(|s| s.error.is_none()).count();
    let packet_loss_percent = ((args.count - successful_samples) as f64 / args.count as f64) * 100.0;

    let dns_values: Vec<f64> = samples
        .iter()
        .filter_map(|s| s.dns_duration_ms)
        .collect();

    let tcp_values: Vec<f64> = samples
        .iter()
        .filter(|s| s.error.is_none())
        .filter_map(|s| s.tcp_duration_ms)
        .collect();

    let total_values: Vec<f64> = samples
        .iter()
        .filter(|s| s.error.is_none())
        .filter_map(|s| s.total_duration_ms)
        .collect();

    let dns_metrics = compute_summary(dns_values);
    let tcp_metrics = compute_summary(tcp_values);
    let total_metrics = compute_summary(total_values);

    let report = BenchmarkReport {
        target_host: args.host,
        target_port: args.port,
        total_samples: args.count,
        successful_samples,
        packet_loss_percent,
        dns_metrics,
        tcp_metrics,
        total_metrics,
        samples,
    };

    if args.json {
        match serde_json::to_string_pretty(&report) {
            Ok(json_output) => println!("{}", json_output),
            Err(e) => {
                eprintln!("Erreur lors de la sérialisation JSON: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        println!("\n------------------ SYNTHÈSE STATISTIQUE ------------------");
        println!(
            "Succès : {}/{} ({:.1}% d'échec)",
            successful_samples, args.count, packet_loss_percent
        );
        print_summary_table("DNS", &report.dns_metrics);
        print_summary_table("TCP Handshake", &report.tcp_metrics);
        print_summary_table("Total", &report.total_metrics);
        println!("----------------------------------------------------------\n");
    }
}

