// src/main.rs
use std::io::{BufRead, BufReader, Write};
use std::net::{TcpListener, TcpStream};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

const HOST: &str = "127.0.0.1";
const PORT: u16 = 8080;
const TICK_INTERVAL: Duration = Duration::from_secs(1);

const DEMO_HTML: &str = r#"<!DOCTYPE html>
<html lang="fr">
<head>
    <meta charset="UTF-8">
    <title>Rust Sync SSE Server</title>
    <style>
        body { font-family: monospace; padding: 2rem; background: #1e1e1e; color: #f0f0f0; }
        h1 { color: #4ec9b0; }
        #logs { background: #252526; border: 1px solid #3c3c3c; border-radius: 4px; padding: 1rem; height: 320px; overflow-y: auto; }
        .log-entry { margin-bottom: 0.4rem; padding: 0.2rem 0.4rem; border-left: 3px solid #007acc; }
    </style>
</head>
<body>
    <h1>Démo SSE Synchrone (Rust std::net)</h1>
    <p>Écoute sur le flux <code>/events</code> :</p>
    <div id="logs"></div>
    <script>
        const logs = document.getElementById('logs');
        const evtSource = new EventSource('/events');
        evtSource.onmessage = function(event) {
            const row = document.createElement('div');
            row.className = 'log-entry';
            row.textContent = `[ID: ${event.lastEventId || '-'}] ${event.data}`;
            logs.appendChild(row);
            logs.scrollTop = logs.scrollHeight;
        };
        evtSource.onerror = function() {
            const row = document.createElement('div');
            row.className = 'log-entry';
            row.style.borderLeftColor = '#f44747';
            row.textContent = 'Connexion interrompue ou en cours de reconnexion...';
            logs.appendChild(row);
        };
    </script>
</body>
</html>"#;

fn main() -> std::io::Result<()> {
    let address = format!("{}:{}", HOST, PORT);
    let listener = TcpListener::bind(&address)?;
    println!("Serveur HTTP synchrone démarré sur http://{}", address);
    println!("  -> UI Web    : http://{}/", address);
    println!("  -> Route SSE : http://{}/events", address);

    let running = Arc::new(AtomicBool::new(true));
    let r = running.clone();

    // Gestion propre de SIGINT / Ctrl+C si supporté par std
    #[cfg(unix)]
    {
        // Optionnel : on peut configurer un timeout pour pouvoir vérifier périodiquement
        let _ = listener.set_nonblocking(false);
    }

    for stream_res in listener.incoming() {
        if !r.load(Ordering::Relaxed) {
            break;
        }

        match stream_res {
            Ok(stream) => {
                thread::spawn(move || {
                    if let Err(err) = handle_connection(stream) {
                        // Un client qui se déconnecte abruptement génère souvent BrokenPipe ou ConnectionReset
                        if err.kind() != std::io::ErrorKind::BrokenPipe
                            && err.kind() != std::io::ErrorKind::ConnectionReset
                        {
                            eprintln!("Erreur lors du traitement de la connexion: {}", err);
                        }
                    }
                });
            }
            Err(err) => {
                eprintln!("Erreur d'acceptation de socket: {}", err);
            }
        }
    }

    Ok(())
}

fn handle_connection(mut stream: TcpStream) -> std::io::Result<()> {
    let peer_addr = stream.peer_addr()?;
    // Active TCP_NODELAY pour éviter l'algorithme de Nagle et envoyer chaque chunk immédiatement
    let _ = stream.set_nodelay(true);

    let mut reader = BufReader::new(stream.try_clone()?);
    let mut request_line = String::new();

    if reader.read_line(&mut request_line)? == 0 {
        return Ok(()); // Connexion fermée prématurément par le client
    }

    // Analyse succincte de la ligne de requête HTTP : "METHOD PATH HTTP/VERSION"
    let mut parts = request_line.split_whitespace();
    let method = parts.next().unwrap_or("");
    let path = parts.next().unwrap_or("");

    // Lecture des en-têtes restants pour vider le buffer HTTP
    let mut line = String::new();
    loop {
        line.clear();
        let bytes_read = reader.read_line(&mut line)?;
        if bytes_read == 0 || line == "\r\n" || line == "\n" {
            break;
        }
    }

    match (method, path) {
        ("GET", "/") => serve_html(&mut stream),
        ("GET", "/events") => serve_sse(stream, peer_addr),
        _ => serve_404(&mut stream),
    }
}

fn serve_html(stream: &mut TcpStream) -> std::io::Result<()> {
    let response = format!(
        "HTTP/1.1 200 OK\r\n\
        Content-Type: text/html; charset=utf-8\r\n\
        Content-Length: {}\r\n\
        Connection: close\r\n\
        \r\n\
        {}",
        DEMO_HTML.len(),
        DEMO_HTML
    );
    stream.write_all(response.as_bytes())?;
    stream.flush()
}

fn serve_404(stream: &mut TcpStream) -> std::io::Result<()> {
    let body = "404 Not Found";
    let response = format!(
        "HTTP/1.1 404 Not Found\r\n\
        Content-Type: text/plain; charset=utf-8\r\n\
        Content-Length: {}\r\n\
        Connection: close\r\n\
        \r\n\
        {}",
        body.len(),
        body
    );
    stream.write_all(response.as_bytes())?;
    stream.flush()
}

fn serve_sse(mut stream: TcpStream, peer_addr: std::net::SocketAddr) -> std::io::Result<()> {
    println!("[SSE] Nouveau client connecté: {}", peer_addr);

    // En-têtes HTTP requis pour Server-Sent Events selon la spécification
    let headers = "HTTP/1.1 200 OK\r\n\
Content-Type: text/event-stream\r\n\
Cache-Control: no-cache\r\n\
Connection: keep-alive\r\n\
Access-Control-Allow-Origin: *\r\n\
\r\n";

    stream.write_all(headers.as_bytes())?;
    stream.flush()?;

    let mut event_id: u64 = 1;
    let start_time = Instant::now();

    loop {
        let timestamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs();

        let elapsed = start_time.elapsed().as_secs();

        // Format d'événement SSE standard :
        // id: <id>\n
        // data: <payload>\n\n
        let sse_payload = format!(
            "id: {}\ndata: {{\"timestamp\": {}, \"uptime_seconds\": {}, \"message\": \"Ping SSE standard synchrone\"}}\n\n",
            event_id, timestamp, elapsed
        );

        // Écriture du payload sur le socket
        match stream.write_all(sse_payload.as_bytes()) {
            Ok(_) => (),
            Err(e) => {
                println!("[SSE] Client déconnecté (write_all): {} ({})", peer_addr, e);
                return Ok(());
            }
        }

        // Flush immédiat et périodique pour garantir la transmission synchrone au client
        match stream.flush() {
            Ok(_) => (),
            Err(e) => {
                println!("[SSE] Client déconnecté (flush): {} ({})", peer_addr, e);
                return Ok(());
            }
        }

        event_id += 1;
        thread::sleep(TICK_INTERVAL);
    }
}

