    print!("    Hex : ");
    for b in &encoded_bytes {
        print!("{:02X} ", b);
    }
    println!();

    // Décodage du conteneur parent
    let parent_records = TlvDecoder::decode_raw_records(&encoded_bytes)?;
    if let Some((tag, child_payload)) = parent_records.first() {
        if *tag == TAG_PROFILE_CONTAINER {
            let restored_profile = UserProfile::from_raw_bytes(child_payload)?;
            println!("\n[3] Désérialisation réussie :");
            println!("    {:#?}", restored_profile);

            assert_eq!(original_profile, restored_profile);
