// src/main.rs
//! Système de sérialisation binaire TLV (Type-Length-Value) compact sans dépendance externe.

use std::error::Error;
use std::fmt;
use std::io::{self, Cursor, Read, Write};

/// Type d'identifiant de champ (Tag).
pub type Tag = u32;

/// Erreurs possibles lors de la manipulation TLV.
#[derive(Debug, PartialEq)]
pub enum TlvError {
    /// Fin inattendue des données lors de la lecture.
    UnexpectedEof,
    /// Débordement de capacité lors du décodage d'un entier à longueur variable.
    VarintOverflow,
    /// Chaîne de caractères non encodée en UTF-8 valide.
    InvalidUtf8,
    /// Longueur de champ incohérente ou dépassée.
    InvalidLength { expected: usize, found: usize },
    /// Valeur booléenne invalide (doit être 0 ou 1).
    InvalidBoolean(u8),
    /// Erreur d'entrée/sortie sous-jacente.
    Io(String),
}

impl fmt::Display for TlvError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            TlvError::UnexpectedEof => write!(f, "Fin inattendue du flux d'octets"),
            TlvError::VarintOverflow => write!(f, "Débordement lors du décodage du varint"),
            TlvError::InvalidUtf8 => write!(f, "Séquence UTF-8 invalide"),
            TlvError::InvalidLength { expected, found } => {
                write!(f, "Taille invalide: attendu {}, reçu {}", expected, found)
            }
            TlvError::InvalidBoolean(b) => write!(f, "Valeur booléenne invalide: {}", b),
            TlvError::Io(err) => write!(f, "Erreur I/O: {}", err),
        }
    }
}

impl Error for TlvError {}

impl From<io::Error> for TlvError {
    fn from(err: io::Error) -> Self {
        if err.kind() == io::ErrorKind::UnexpectedEof {
            TlvError::UnexpectedEof
        } else {
            TlvError::Io(err.to_string())
        }
    }
}

/// Encodage et décodage d'entiers à longueur variable (LEB128 non signé).
pub mod varint {
    use super::*;

    /// Encode un entier `u64` en LEB128 dans le buffer fourni.
    pub fn encode_u64<W: Write>(writer: &mut W, mut val: u64) -> Result<usize, TlvError> {
        let mut written = 0;
        loop {
            let mut byte = (val & 0x7F) as u8;
            val >>= 7;
            if val != 0 {
                byte |= 0x80;
            }
            writer.write_all(&[byte])?;
            written += 1;
            if val == 0 {
                break;
            }
        }
        Ok(written)
    }

    /// Décode un entier `u64` depuis un lecteur d'octets.
    pub fn decode_u64<R: Read>(reader: &mut R) -> Result<u64, TlvError> {
        let mut result: u64 = 0;
        let mut shift = 0;
        let mut buf = [0u8; 1];

        loop {
            reader.read_exact(&mut buf)?;
            let byte = buf[0];
            let value = (byte & 0x7F) as u64;

            if shift >= 64 || (shift == 63 && value > 1) {
                return Err(TlvError::VarintOverflow);
            }

            result |= value << shift;
            shift += 7;

            if (byte & 0x80) == 0 {
                break;
            }
        }

        Ok(result)
    }

    /// Décode un `u32` depuis un lecteur d'octets.
    pub fn decode_u32<R: Read>(reader: &mut R) -> Result<u32, TlvError> {
        let val = decode_u64(reader)?;
        if val > u32::MAX as u64 {
            return Err(TlvError::VarintOverflow);
        }
        Ok(val as u32)
    }
}

/// Valeur stockée dans un enregistrement TLV.
#[derive(Debug, Clone, PartialEq)]
pub enum TlvValue {
    Boolean(bool),
    Varint(u64),
    Int32(i32),
    Int64(i64),
    Float32(f32),
    Float64(f64),
    Bytes(Vec<u8>),
    String(String),
    Nested(Vec<TlvRecord>),
}

/// Enregistrement complet Type-Length-Value.
#[derive(Debug, Clone, PartialEq)]
pub struct TlvRecord {
    pub tag: Tag,
    pub value: TlvValue,
}

impl TlvRecord {
    pub fn new(tag: Tag, value: TlvValue) -> Self {
        Self { tag, value }
    }
}

/// Encodeur TLV compact.
pub struct TlvEncoder;

impl TlvEncoder {
    /// Encode une liste d'enregistrements TLV dans un `Vec<u8>`.
    pub fn encode_records(records: &[TlvRecord]) -> Result<Vec<u8>, TlvError> {
        let mut buffer = Vec::new();
        for record in records {
            Self::encode_record(&mut buffer, record)?;
        }
        Ok(buffer)
    }

    /// Encode un enregistrement TLV unique dans un flux écrivable.
    pub fn encode_record<W: Write>(writer: &mut W, record: &TlvRecord) -> Result<(), TlvError> {
        // Encodage du Tag (varint u32)
        varint::encode_u64(writer, record.tag as u64)?;

        // Sérialisation du payload en mémoire tampon pour déterminer la taille exacte
        let payload = match &record.value {
            TlvValue::Boolean(b) => vec![if *b { 1u8 } else { 0u8 }],
            TlvValue::Varint(v) => {
                let mut p = Vec::new();
                varint::encode_u64(&mut p, *v)?;
                p
            }
            TlvValue::Int32(i) => i.to_le_bytes().to_vec(),
            TlvValue::Int64(i) => i.to_le_bytes().to_vec(),
            TlvValue::Float32(f) => f.to_le_bytes().to_vec(),
            TlvValue::Float64(f) => f.to_le_bytes().to_vec(),
            TlvValue::Bytes(b) => b.clone(),
            TlvValue::String(s) => s.as_bytes().to_vec(),
            TlvValue::Nested(children) => Self::encode_records(children)?,
        };

        // Encodage de la Longueur (varint u32)
        varint::encode_u64(writer, payload.len() as u64)?;

        // Encodage de la Valeur
        writer.write_all(&payload)?;
        Ok(())
    }
}

/// Décodeur TLV compact.
pub struct TlvDecoder;

impl TlvDecoder {
    /// Décode une séquence complète d'enregistrements bruts (tag et charge utile en octets).
    pub fn decode_raw_records(data: &[u8]) -> Result<Vec<(Tag, Vec<u8>)>, TlvError> {
        let mut cursor = Cursor::new(data);
        let mut records = Vec::new();

        while (cursor.position() as usize) < data.len() {
            let tag = varint::decode_u32(&mut cursor)?;
            let length = varint::decode_u32(&mut cursor)? as usize;

            let remaining = data.len().saturating_sub(cursor.position() as usize);
            if remaining < length {
                return Err(TlvError::UnexpectedEof);
            }

            let mut value_buf = vec![0u8; length];
            cursor.read_exact(&mut value_buf)?;
            records.push((tag, value_buf));
        }

        Ok(records)
    }

    /// Décode un booléen depuis un buffer.
    pub fn parse_bool(buf: &[u8]) -> Result<bool, TlvError> {
        if buf.len() != 1 {
            return Err(TlvError::InvalidLength {
                expected: 1,
                found: buf.len(),
            });
        }
        match buf[0] {
            0 => Ok(false),
            1 => Ok(true),
            other => Err(TlvError::InvalidBoolean(other)),
        }
    }

    /// Décode un entier varint depuis un buffer.
    pub fn parse_varint(buf: &[u8]) -> Result<u64, TlvError> {
        let mut cursor = Cursor::new(buf);
        let val = varint::decode_u64(&mut cursor)?;
        if cursor.position() as usize != buf.len() {
            return Err(TlvError::InvalidLength {
                expected: cursor.position() as usize,
                found: buf.len(),
            });
        }
        Ok(val)
    }

    /// Décode un entier `i32` Little-Endian.
    pub fn parse_i32(buf: &[u8]) -> Result<i32, TlvError> {
        if buf.len() != 4 {
            return Err(TlvError::InvalidLength {
                expected: 4,
                found: buf.len(),
            });
        }
        let mut arr = [0u8; 4];
        arr.copy_from_slice(buf);
        Ok(i32::from_le_bytes(arr))
    }

    /// Décode un entier `i64` Little-Endian.
    pub fn parse_i64(buf: &[u8]) -> Result<i64, TlvError> {
        if buf.len() != 8 {
            return Err(TlvError::InvalidLength {
                expected: 8,
                found: buf.len(),
            });
        }
        let mut arr = [0u8; 8];
        arr.copy_from_slice(buf);
        Ok(i64::from_le_bytes(arr))
    }

    /// Décode un flottant `f64` Little-Endian.
    pub fn parse_f64(buf: &[u8]) -> Result<f64, TlvError> {
        if buf.len() != 8 {
            return Err(TlvError::InvalidLength {
                expected: 8,
                found: buf.len(),
            });
        }
        let mut arr = [0u8; 8];
        arr.copy_from_slice(buf);
        Ok(f64::from_le_bytes(arr))
    }

    /// Décode une chaîne de caractères UTF-8.
    pub fn parse_string(buf: &[u8]) -> Result<String, TlvError> {
        String::from_utf8(buf.to_vec()).map_err(|_| TlvError::InvalidUtf8)
    }
}

/// Exemple de structure applicative métier utilisant TLV.
#[derive(Debug, PartialEq, Clone)]
pub struct UserProfile {
    pub id: u64,
    pub username: String,
    pub is_active: bool,
    pub score: f64,
    pub payload: Vec<u8>,
}

// Définition des balises (Tags) pour UserProfile
const TAG_USER_ID: Tag = 1;
const TAG_USER_NAME: Tag = 2;
const TAG_USER_ACTIVE: Tag = 3;
const TAG_USER_SCORE: Tag = 4;
const TAG_USER_PAYLOAD: Tag = 5;
const TAG_PROFILE_CONTAINER: Tag = 10;

impl UserProfile {
    pub fn to_tlv(&self) -> TlvRecord {
        let fields = vec![
            TlvRecord::new(TAG_USER_ID, TlvValue::Varint(self.id)),
            TlvRecord::new(TAG_USER_NAME, TlvValue::String(self.username.clone())),
            TlvRecord::new(TAG_USER_ACTIVE, TlvValue::Boolean(self.is_active)),
            TlvRecord::new(TAG_USER_SCORE, TlvValue::Float64(self.score)),
            TlvRecord::new(TAG_USER_PAYLOAD, TlvValue::Bytes(self.payload.clone())),
        ];
        TlvRecord::new(TAG_PROFILE_CONTAINER, TlvValue::Nested(fields))
    }

    pub fn from_raw_bytes(data: &[u8]) -> Result<Self, TlvError> {
        let records = TlvDecoder::decode_raw_records(data)?;
        let mut id = None;
        let mut username = None;
        let mut is_active = None;
        let mut score = None;
        let mut payload = None;

        for (tag, value_bytes) in records {
            match tag {
                TAG_USER_ID => id = Some(TlvDecoder::parse_varint(&value_bytes)?),
                TAG_USER_NAME => username = Some(TlvDecoder::parse_string(&value_bytes)?),
                TAG_USER_ACTIVE => is_active = Some(TlvDecoder::parse_bool(&value_bytes)?),
                TAG_USER_SCORE => score = Some(TlvDecoder::parse_f64(&value_bytes)?),
                TAG_USER_PAYLOAD => payload = Some(value_bytes),
                _ => {} // Tolérance aux tags inconnus (extensibilité descendante/ascendante)
            }
        }

        Ok(UserProfile {
            id: id.ok_or(TlvError::InvalidLength {
                expected: 1,
                found: 0,
            })?,
            username: username.unwrap_or_default(),
            is_active: is_active.unwrap_or(false),
            score: score.unwrap_or(0.0),
            payload: payload.unwrap_or_default(),
        })
    }
}

