    }

    #[test]
    fn test_truncated_data_fails_gracefully() {
        let record = TlvRecord::new(1, TlvValue::Int32(12345));
        let mut encoded = TlvEncoder::encode_records(&[record]).expect("Encoding failed");
        // Tronquer le dernier octet
        encoded.pop();
        let result = TlvDecoder::decode_raw_records(&encoded);
        assert_eq!(result, Err(TlvError::UnexpectedEof));
    }
}

