// src/main.rs
//! Moteur de machine virtuelle à pile (Stack Machine)
//!
//! Ce module implémente une machine virtuelle complète, idiomatique et sécurisée,
//! capable d'exécuter un jeu d'instructions de bytecode arithmétique et de manipulation de pile.

use std::fmt;
use thiserror::Error;

/// Représente les valeurs manipulables par la machine virtuelle.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Value {
    /// Entier 64-bit signé.
    Int(i64),
    /// Flottant 64-bit double précision.
    Float(f64),
}

impl Value {
    /// Vérifie si la valeur est considérée comme nulle (pour les sauts conditionnels).
    #[must_use]
    pub fn is_zero(&self) -> bool {
        match *self {
            Value::Int(v) => v == 0,
            Value::Float(v) => v == 0.0,
        }
    }
}

impl fmt::Display for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Value::Int(v) => write!(f, "{v}"),
            Value::Float(v) => write!(f, "{v}"),
        }
    }
}

impl From<i64> for Value {
    fn from(val: i64) -> Self {
        Value::Int(val)
    }
}

impl From<f64> for Value {
    fn from(val: f64) -> Self {
        Value::Float(val)
    }
}

/// Ensemble des erreurs pouvant survenir lors de l'exécution d'un bytecode.
#[derive(Error, Debug, PartialEq)]
pub enum VmError {
    #[error("Erreur de sous-dépassement de pile (stack underflow) : requis {required}, disponible {available}")]
    StackUnderflow { required: usize, available: usize },

    #[error("Erreur de débordement de pile (stack overflow) : capacité maximale de {max_size} atteinte")]
    StackOverflow { max_size: usize },

    #[error("Division ou modulo par zéro")]
    DivisionByZero,

    #[error("Pointeur d'instruction invalide : {target} (taille du programme : {program_size})")]
    InvalidInstructionPointer {
        target: usize,
        program_size: usize,
    },
}

/// Jeu d'instructions supporté par la machine virtuelle.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Instruction {
    /// Empile une constante sur la pile.
    Push(Value),
    /// Dépile et supprime la valeur au sommet.
    Pop,
    /// Duplique la valeur au sommet de la pile.
    Dup,
    /// Échange les deux valeurs au sommet de la pile.
    Swap,
    /// Additionne les deux valeurs au sommet (`a + b`).
    Add,
    /// Soustrait la valeur au sommet de celle du dessous (`a - b`).
    Sub,
    /// Multiplie les deux valeurs au sommet (`a * b`).
    Mul,
    /// Divise la valeur du dessous par celle au sommet (`a / b`).
    Div,
    /// Reste de la division entière / modulo flottant (`a % b`).
    Mod,
    /// Inverse le signe de la valeur au sommet (`-x`).
    Neg,
    /// Affiche la valeur au sommet de la pile sans la dépiler.
    Print,
    /// Saut inconditionnel vers l'indice d'instruction spécifié.
    Jmp(usize),
    /// Saut conditionnel si la valeur au sommet est zéro (consomme la valeur).
    JmpIfZero(usize),
    /// Arrête l'exécution du programme.
    Halt,
}

/// Machine virtuelle à pile.
#[derive(Debug)]
pub struct Vm {
    /// Pile de valeurs d'exécution.
    stack: Vec<Value>,
    /// Pointeur d'instruction (index courant dans le programme).
    ip: usize,
    /// Capacité maximale autorisée pour la pile.
    max_stack_size: usize,
}

impl Default for Vm {
    fn default() -> Self {
        Self::new(1024)
    }
}

impl Vm {
    /// Crée une nouvelle instance de machine virtuelle avec une limite de taille de pile.
    #[must_use]
    pub fn new(max_stack_size: usize) -> Self {
        Self {
            stack: Vec::with_capacity(32),
            ip: 0,
            max_stack_size,
        }
    }

    /// Réinitialise l'état de la machine virtuelle.
    pub fn reset(&mut self) {
        self.stack.clear();
        self.ip = 0;
    }

    /// Retourne une référence vers la pile actuelle.
    #[must_use]
    pub fn stack(&self) -> &[Value] {
        &self.stack
    }

    /// Retourne la valeur au sommet de la pile sans la retirer, si elle existe.
    #[must_use]
    pub fn peek(&self) -> Option<Value> {
        self.stack.last().copied()
    }

    /// Empile une valeur sur la pile en vérifiant la capacité maximale.
    fn push(&mut self, val: Value) -> Result<(), VmError> {
        if self.stack.len() >= self.max_stack_size {
            return Err(VmError::StackOverflow {
                max_size: self.max_stack_size,
            });
        }
        self.stack.push(val);
        Ok(())
    }

    /// Dépile une valeur de la pile.
    fn pop(&mut self) -> Result<Value, VmError> {
        self.stack.pop().ok_or(VmError::StackUnderflow {
            required: 1,
            available: 0,
        })
    }

    /// Dépile deux opérandes binaires : `(a, b)` correspondant à l'expression `a OP b`.
    fn pop_binary_operands(&mut self) -> Result<(Value, Value), VmError> {
        if self.stack.len() < 2 {
            return Err(VmError::StackUnderflow {
                required: 2,
                available: self.stack.len(),
            });
        }
        // L'ordre sur la pile est [..., a, b] où b est au sommet (sommet = pop)
        let b = self.stack.pop().expect("longueur vérifiée préalablement");
        let a = self.stack.pop().expect("longueur vérifiée préalablement");
        Ok((a, b))
    }

    /// Exécute une opération binaire arithmétique.
    fn execute_binary_op<FInt, FFloat>(
        &mut self,
        int_op: FInt,
        float_op: FFloat,
    ) -> Result<(), VmError>
    where
        FInt: FnOnce(i64, i64) -> Result<i64, VmError>,
        FFloat: FnOnce(f64, f64) -> Result<f64, VmError>,
    {
        let (lhs, rhs) = self.pop_binary_operands()?;
        let res = match (lhs, rhs) {
            (Value::Int(a), Value::Int(b)) => Value::Int(int_op(a, b)?),
            (Value::Float(a), Value::Float(b)) => Value::Float(float_op(a, b)?),
            (Value::Int(a), Value::Float(b)) => Value::Float(float_op(a as f64, b)?),
            (Value::Float(a), Value::Int(b)) => Value::Float(float_op(a, b as f64)?),
        };
        self.push(res)
    }

    /// Exécute une unique instruction du programme.
    /// Renvoie `Ok(true)` si l'exécution doit continuer, ou `Ok(false)` si la machine s'est arrêtée (`Halt`).
    pub fn step(&mut self, program: &[Instruction]) -> Result<bool, VmError> {
        if self.ip >= program.len() {
            return Ok(false);
        }

        let instruction = program[self.ip];
        self.ip += 1;

        match instruction {
            Instruction::Push(value) => {
                self.push(value)?;
            }
            Instruction::Pop => {
                self.pop()?;
            }
            Instruction::Dup => {
                let top = self.peek().ok_or(VmError::StackUnderflow {
                    required: 1,
                    available: 0,
                })?;
                self.push(top)?;
            }
            Instruction::Swap => {
                let len = self.stack.len();
                if len < 2 {
                    return Err(VmError::StackUnderflow {
                        required: 2,
                        available: len,
                    });
                }
                self.stack.swap(len - 1, len - 2);
            }
            Instruction::Add => {
                self.execute_binary_op(|a, b| Ok(a.wrapping_add(b)), |a, b| Ok(a + b))?;
            }
            Instruction::Sub => {
                self.execute_binary_op(|a, b| Ok(a.wrapping_sub(b)), |a, b| Ok(a - b))?;
            }
            Instruction::Mul => {
                self.execute_binary_op(|a, b| Ok(a.wrapping_mul(b)), |a, b| Ok(a * b))?;
            }
            Instruction::Div => {
                self.execute_binary_op(
                    |a, b| {
                        if b == 0 {
                            Err(VmError::DivisionByZero)
                        } else {
                            Ok(a.wrapping_div(b))
                        }
                    },
                    |a, b| {
                        if b == 0.0 {
                            Err(VmError::DivisionByZero)
                        } else {
                            Ok(a / b)
                        }
                    },
                )?;
            }
            Instruction::Mod => {
                self.execute_binary_op(
                    |a, b| {
                        if b == 0 {
                            Err(VmError::DivisionByZero)
                        } else {
                            Ok(a.wrapping_rem(b))
                        }
                    },
                    |a, b| {
                        if b == 0.0 {
                            Err(VmError::DivisionByZero)
                        } else {
                            Ok(a % b)
                        }
                    },
                )?;
            }
            Instruction::Neg => {
                let val = self.pop()?;
                let res = match val {
                    Value::Int(v) => Value::Int(v.wrapping_neg()),
                    Value::Float(v) => Value::Float(-v),
                };
                self.push(res)?;
            }
            Instruction::Print => {
                let top = self.peek().ok_or(VmError::StackUnderflow {
                    required: 1,
                    available: 0,
                })?;
                println!("[STK OUTPUT] {top}");
            }
            Instruction::Jmp(target) => {
                if target > program.len() {
                    return Err(VmError::InvalidInstructionPointer {
                        target,
                        program_size: program.len(),
                    });
                }
                self.ip = target;
            }
            Instruction::JmpIfZero(target) => {
                if target > program.len() {
                    return Err(VmError::InvalidInstructionPointer {
                        target,
                        program_size: program.len(),
                    });
                }
                let condition = self.pop()?;
                if condition.is_zero() {
                    self.ip = target;
                }
            }
            Instruction::Halt => {
                return Ok(false);
            }
        }

        Ok(true)
    }

    /// Exécute l'intégralité du programme jusqu'à `Halt` ou épuisement des instructions.
    pub fn run(&mut self, program: &[Instruction]) -> Result<(), VmError> {
        while self.step(program)? {}
        Ok(())
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("=== Machine Virtuelle à Pile (Stack Machine) ===");

    // Démonstration 1 : Calcul arithmétique complexe
    // Expression : (15 + 25) * 2 - 10 / 2
    // En notation postfixe (RPN) : 15 25 + 2 * 10 2 / -
    let arithmetic_program = vec![
        Instruction::Push(Value::Int(15)),
        Instruction::Push(Value::Int(25)),
        Instruction::Add,                 // 15 + 25 = 40
        Instruction::Push(Value::Int(2)),
        Instruction::Mul,                 // 40 * 2 = 80
        Instruction::Push(Value::Int(10)),
        Instruction::Push(Value::Int(2)),
        Instruction::Div,                 // 10 / 2 = 5
        Instruction::Sub,                 // 80 - 5 = 75
        Instruction::Print,               // Affiche 75
        Instruction::Halt,
    ];

    println!("\n[1] Exécution du calcul arithmétique : (15 + 25) * 2 - 10 / 2");
    let mut vm = Vm::new(256);
    vm.run(&arithmetic_program)?;
    if let Some(res) = vm.peek() {
        println!("Résultat final sur la pile : {res}");
    }

    // Démonstration 2 : Arithmétique à virgule flottante et promotion de types
    // Calcul : (5.5 + 4.5) * 3 = 30.0
    let float_program = vec![
        Instruction::Push(Value::Float(5.5)),
        Instruction::Push(Value::Float(4.5)),
        Instruction::Add,
        Instruction::Push(Value::Int(3)), // Promotion automatique f64 + i64
        Instruction::Mul,
        Instruction::Print,
        Instruction::Halt,
    ];

    println!("\n[2] Exécution arithmétique mixte (flottant + entier) : (5.5 + 4.5) * 3");
    vm.reset();
    vm.run(&float_program)?;
    if let Some(res) = vm.peek() {
        println!("Résultat final sur la pile : {res}");
    }

    // Démonstration 3 : Gestion d'erreur (Division par zéro)
    let error_program = vec![
        Instruction::Push(Value::Int(42)),
        Instruction::Push(Value::Int(0)),
        Instruction::Div,
        Instruction::Halt,
    ];

    println!("\n[3] Test de sécurité : capture d'une division par zéro");
    vm.reset();
    match vm.run(&error_program) {
        Ok(_) => println!("Exécution terminée de manière inattendue."),
        Err(err) => println!("Succès de la détection de l'erreur : {err}"),
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_push_pop() {
        let mut vm = Vm::new(10);
        let prog = vec![
            Instruction::Push(Value::Int(10)),
            Instruction::Push(Value::Int(20)),
            Instruction::Pop,
            Instruction::Halt,
        ];
        assert!(vm.run(&prog).is_ok());
        assert_eq!(vm.stack(), &[Value::Int(10)]);
    }

    #[test]
    fn test_arithmetic_operations() {
        let mut vm = Vm::new(10);
        // Test addition & soustraction
        let prog = vec![
            Instruction::Push(Value::Int(50)),
            Instruction::Push(Value::Int(20)),
            Instruction::Sub, // 50 - 20 = 30
            Instruction::Push(Value::Int(12)),
            Instruction::Add, // 30 + 12 = 42
            Instruction::Halt,
        ];
        assert!(vm.run(&prog).is_ok());
        assert_eq!(vm.peek(), Some(Value::Int(42)));
    }

    #[test]
    fn test_mul_div_mod() {
        let mut vm = Vm::new(10);
        let prog = vec![
            Instruction::Push(Value::Int(20)),
            Instruction::Push(Value::Int(3)),
            Instruction::Mod, // 20 % 3 = 2
            Instruction::Push(Value::Int(5)),
            Instruction::Mul, // 2 * 5 = 10
            Instruction::Push(Value::Int(2)),
            Instruction::Div, // 10 / 2 = 5
            Instruction::Halt,
        ];
        assert!(vm.run(&prog).is_ok());
        assert_eq!(vm.peek(), Some(Value::Int(5)));
    }

    #[test]
    fn test_division_by_zero() {
        let mut vm = Vm::new(10);
        let prog = vec![
            Instruction::Push(Value::Int(10)),
            Instruction::Push(Value::Int(0)),
            Instruction::Div,
            Instruction::Halt,
        ];
        let res = vm.run(&prog);
        assert_eq!(res, Err(VmError::DivisionByZero));
    }

    #[test]
    fn test_stack_underflow() {
        let mut vm = Vm::new(10);
        let prog = vec![Instruction::Add];
        let res = vm.run(&prog);
        assert_eq!(
            res,
            Err(VmError::StackUnderflow {
                required: 2,
                available: 0
            })
        );
    }

    #[test]
    fn test_stack_overflow() {
        let mut vm = Vm::new(2);
        let prog = vec![
            Instruction::Push(Value::Int(1)),
            Instruction::Push(Value::Int(2)),
            Instruction::Push(Value::Int(3)),
        ];
        let res = vm.run(&prog);
        assert_eq!(res, Err(VmError::StackOverflow { max_size: 2 }));
    }

    #[test]
    fn test_dup_and_swap() {
        let mut vm = Vm::new(10);
        let prog = vec![
            Instruction::Push(Value::Int(10)),
            Instruction::Push(Value::Int(20)),
            Instruction::Swap, // [20, 10]
            Instruction::Dup,  // [20, 10, 10]
            Instruction::Halt,
        ];
        assert!(vm.run(&prog).is_ok());
        assert_eq!(
            vm.stack(),
            &[Value::Int(20), Value::Int(10), Value::Int(10)]
        );
    }

    #[test]
    fn test_neg() {
        let mut vm = Vm::new(10);
        let prog = vec![Instruction::Push(Value::Int(42)), Instruction::Neg, Instruction::Halt];
        assert!(vm.run(&prog).is_ok());
        assert_eq!(vm.peek(), Some(Value::Int(-42)));
    }

    #[test]
    fn test_jump_condition() {
        let mut vm = Vm::new(10);
        // if 0 == 0 jump to index 4 (push 99), skip push 42
        let prog = vec![
            Instruction::Push(Value::Int(0)),
            Instruction::JmpIfZero(4),
            Instruction::Push(Value::Int(42)),
            Instruction::Halt,
            Instruction::Push(Value::Int(99)),
            Instruction::Halt,
        ];
        assert!(vm.run(&prog).is_ok());
        assert_eq!(vm.peek(), Some(Value::Int(99)));
    }
