        let res = match (lhs, rhs) {
            (Value::Int(a), Value::Int(b)) => Value::Int(int_op(a, b)?),
            (Value::Float(a), Value::Float(b)) => Value::Float(float_op(a, b)?),
            (Value::Int(a), Value::Float(b)) => Value::Float(float_op(a as f64, b)?),
            (Value::Float(a), Value::Int(b)) => Value::Float(float_op(a, b as f64)?),
        };
        self.push(res)
    }

    /// Exécute une unique instruction du programme.
    /// Renvoie `Ok(true)` si l'exécution doit continuer, ou `Ok(false)` si la machine s'est arrêtée (`Halt`).
    pub fn step(&mut self, program: &[Instruction]) -> Result<bool, VmError> {
        if self.ip >= program.len() {
            return Ok(false);
        }

        let instruction = program[self.ip];
        self.ip += 1;

        match instruction {
            Instruction::Push(value) => {
                self.push(value)?;
            }
            Instruction::Pop => {
                self.pop()?;
            }
            Instruction::Dup => {
                let top = self.peek().ok_or(VmError::StackUnderflow {
                    required: 1,
                    available: 0,
                })?;
                self.push(top)?;
            }
            Instruction::Swap => {
                let len = self.stack.len();
                if len < 2 {
                    return Err(VmError::StackUnderflow {
                        required: 2,
                        available: len,
                    });
                }
                self.stack.swap(len - 1, len - 2);
            }
            Instruction::Add => {
                self.execute_binary_op(|a, b| Ok(a.wrapping_add(b)), |a, b| Ok(a + b))?;
            }
            Instruction::Sub => {
                self.execute_binary_op(|a, b| Ok(a.wrapping_sub(b)), |a, b| Ok(a - b))?;
            }
            Instruction::Mul => {
                self.execute_binary_op(|a, b| Ok(a.wrapping_mul(b)), |a, b| Ok(a * b))?;
            }
            Instruction::Div => {
                self.execute_binary_op(
                    |a, b| {
                        if b == 0 {
                            Err(VmError::DivisionByZero)
                        } else {
                            Ok(a.wrapping_div(b))
                        }
                    },
                    |a, b| {
                        if b == 0.0 {
                            Err(VmError::DivisionByZero)
                        } else {
                            Ok(a / b)
                        }
                    },
                )?;
            }
            Instruction::Mod => {
                self.execute_binary_op(
                    |a, b| {
                        if b == 0 {
                            Err(VmError::DivisionByZero)
                        } else {
                            Ok(a.wrapping_rem(b))
                        }
                    },
                    |a, b| {
                        if b == 0.0 {
                            Err(VmError::DivisionByZero)
                        } else {
                            Ok(a % b)
                        }
                    },
                )?;
            }
            Instruction::Neg => {
                let val = self.pop()?;
                let res = match val {
                    Value::Int(v) => Value::Int(v.wrapping_neg()),
                    Value::Float(v) => Value::Float(-v),
                };
                self.push(res)?;
            }
            Instruction::Print => {
                let top = self.peek().ok_or(VmError::StackUnderflow {
                    required: 1,
                    available: 0,
                })?;
                println!("[STK OUTPUT] {top}");
            }
            Instruction::Jmp(target) => {
                if target > program.len() {
                    return Err(VmError::InvalidInstructionPointer {
                        target,
                        program_size: program.len(),
                    });
                }
                self.ip = target;
            }
            Instruction::JmpIfZero(target) => {
                if target > program.len() {
                    return Err(VmError::InvalidInstructionPointer {
                        target,
                        program_size: program.len(),
                    });
                }
                let condition = self.pop()?;
                if condition.is_zero() {
                    self.ip = target;
                }
            }
            Instruction::Halt => {
                return Ok(false);
            }
        }

        Ok(true)
    }

    /// Exécute l'intégralité du programme jusqu'à `Halt` ou épuisement des instructions.
    pub fn run(&mut self, program: &[Instruction]) -> Result<(), VmError> {
        while self.step(program)? {}
        Ok(())
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("=== Machine Virtuelle à Pile (Stack Machine) ===");

    // Démonstration 1 : Calcul arithmétique complexe
    // Expression : (15 + 25) * 2 - 10 / 2
    // En notation postfixe (RPN) : 15 25 + 2 * 10 2 / -
    let arithmetic_program = vec![
        Instruction::Push(Value::Int(15)),
        Instruction::Push(Value::Int(25)),
        Instruction::Add,                 // 15 + 25 = 40
        Instruction::Push(Value::Int(2)),
        Instruction::Mul,                 // 40 * 2 = 80
        Instruction::Push(Value::Int(10)),
        Instruction::Push(Value::Int(2)),
        Instruction::Div,                 // 10 / 2 = 5
        Instruction::Sub,                 // 80 - 5 = 75
        Instruction::Print,               // Affiche 75
        Instruction::Halt,
    ];

    println!("\n[1] Exécution du calcul arithmétique : (15 + 25) * 2 - 10 / 2");
    let mut vm = Vm::new(256);
    vm.run(&arithmetic_program)?;
    if let Some(res) = vm.peek() {
        println!("Résultat final sur la pile : {res}");
    }

    // Démonstration 2 : Arithmétique à virgule flottante et promotion de types
    // Calcul : (5.5 + 4.5) * 3 = 30.0
    let float_program = vec![
        Instruction::Push(Value::Float(5.5)),
        Instruction::Push(Value::Float(4.5)),
        Instruction::Add,
        Instruction::Push(Value::Int(3)), // Promotion automatique f64 + i64
        Instruction::Mul,
        Instruction::Print,
        Instruction::Halt,
    ];

    println!("\n[2] Exécution arithmétique mixte (flottant + entier) : (5.5 + 4.5) * 3");
    vm.reset();
    vm.run(&float_program)?;
    if let Some(res) = vm.peek() {
        println!("Résultat final sur la pile : {res}");
    }

    // Démonstration 3 : Gestion d'erreur (Division par zéro)
    let error_program = vec![
        Instruction::Push(Value::Int(42)),
        Instruction::Push(Value::Int(0)),
        Instruction::Div,
        Instruction::Halt,
    ];

    println!("\n[3] Test de sécurité : capture d'une division par zéro");
    vm.reset();
    match vm.run(&error_program) {
        Ok(_) => println!("Exécution terminée de manière inattendue."),
        Err(err) => println!("Succès de la détection de l'erreur : {err}"),
    }

    Ok(())
}

