        let mut vm = Vm::new(10);
        let prog = vec![Instruction::Add];
        let res = vm.run(&prog);
        assert_eq!(
            res,
            Err(VmError::StackUnderflow {
                required: 2,
                available: 0
            })
        );
    }

    #[test]
    fn test_stack_overflow() {
        let mut vm = Vm::new(2);
        let prog = vec![
            Instruction::Push(Value::Int(1)),
            Instruction::Push(Value::Int(2)),
            Instruction::Push(Value::Int(3)),
        ];
        let res = vm.run(&prog);
        assert_eq!(res, Err(VmError::StackOverflow { max_size: 2 }));
    }

    #[test]
    fn test_dup_and_swap() {
        let mut vm = Vm::new(10);
        let prog = vec![
            Instruction::Push(Value::Int(10)),
            Instruction::Push(Value::Int(20)),
            Instruction::Swap, // [20, 10]
            Instruction::Dup,  // [20, 10, 10]
            Instruction::Halt,
        ];
        assert!(vm.run(&prog).is_ok());
        assert_eq!(
            vm.stack(),
            &[Value::Int(20), Value::Int(10), Value::Int(10)]
        );
    }

    #[test]
    fn test_neg() {
        let mut vm = Vm::new(10);
        let prog = vec![Instruction::Push(Value::Int(42)), Instruction::Neg, Instruction::Halt];
        assert!(vm.run(&prog).is_ok());
        assert_eq!(vm.peek(), Some(Value::Int(-42)));
    }

    #[test]
    fn test_jump_condition() {
        let mut vm = Vm::new(10);
        // if 0 == 0 jump to index 4 (push 99), skip push 42
        let prog = vec![
            Instruction::Push(Value::Int(0)),
            Instruction::JmpIfZero(4),
            Instruction::Push(Value::Int(42)),
            Instruction::Halt,
            Instruction::Push(Value::Int(99)),
            Instruction::Halt,
        ];
        assert!(vm.run(&prog).is_ok());
        assert_eq!(vm.peek(), Some(Value::Int(99)));
    }
