```rust
// src/main.rs
use rand::Rng;
use std::collections::HashMap;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::mpsc::{channel, Receiver, RecvTimeoutError, Sender};
use std::sync::{Arc, Mutex};
use std::thread::{self, JoinHandle};
use std::time::{Duration, Instant};

/// Rôles possibles pour un nœud Raft.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NodeRole {
    Follower,
    Candidate,
    Leader,
}

/// Contenu des charges utiles des messages Raft.
#[derive(Debug, Clone)]
pub enum MessagePayload {
    RequestVoteArgs {
        term: usize,
        candidate_id: usize,
    },
    RequestVoteReply {
        term: usize,
        vote_granted: bool,
    },
    AppendEntriesArgs {
        term: usize,
        leader_id: usize,
    },
    AppendEntriesReply {
        term: usize,
        success: bool,
    },
}

/// Enveloppe réseau reliant l'expéditeur, le destinataire et la charge utile.
#[derive(Debug, Clone)]
pub struct NetworkMessage {
    pub from: usize,
    pub to: usize,
    pub payload: MessagePayload,
}

/// Commande de contrôle externe envoyée à un nœud (pour scénarios de test).
#[derive(Debug, Clone)]
pub enum NodeCommand {
    Disconnect,
    Reconnect,
    Stop,
}

/// Entrée reçue par un nœud (message réseau ou commande de contrôle).
#[derive(Debug, Clone)]
pub enum NodeEvent {
    Network(NetworkMessage),
    Control(NodeCommand),
}

/// Routeur réseau simulant un maillage de nœuds interconnectés.
pub struct NetworkRouter {
    senders: HashMap<usize, Sender<NodeEvent>>,
}

impl NetworkRouter {
    pub fn new() -> Self {
        Self {
            senders: HashMap::new(),
        }
    }

    pub fn register(&mut self, id: usize, sender: Sender<NodeEvent>) {
        self.senders.insert(id, sender);
    }

    pub fn send(&self, msg: NetworkMessage) {
        if let Some(target) = self.senders.get(&msg.to) {
            let _ = target.send(NodeEvent::Network(msg));
        }
    }

    pub fn send_command(&self, node_id: usize, cmd: NodeCommand) {
        if let Some(target) = self.senders.get(&node_id) {
            let _ = target.send(NodeEvent::Control(cmd));
        }
    }

    pub fn broadcast(&self, from: usize, payload: MessagePayload) {
        for (&dest_id, sender) in &self.senders {
            if dest_id != from {
                let msg = NetworkMessage {
                    from,
                    to: dest_id,
                    payload: payload.clone(),
                };
                let _ = sender.send(NodeEvent::Network(msg));
            }
        }
    }
}

/// Nœud participant au protocole Raft.
pub struct RaftNode {
    pub id: usize,
    pub cluster_size: usize,
    pub current_term: usize,
    pub voted_for: Option<usize>,
    pub role: NodeRole,
    pub votes_received: usize,
    pub is_connected: bool,
    pub election_timeout: Duration,
    pub last_heartbeat_or_vote: Instant,
    pub heartbeat_interval: Duration,
    pub last_heartbeat_sent: Instant,
    pub router: Arc<Mutex<NetworkRouter>>,
    pub receiver: Receiver<NodeEvent>,
    pub running: Arc<AtomicBool>,
}

impl RaftNode {
    pub fn new(
        id: usize,
        cluster_size: usize,
        router: Arc<Mutex<NetworkRouter>>,
        receiver: Receiver<NodeEvent>,
        running: Arc<AtomicBool>,
    ) -> Self {
        let mut node = Self {
            id,
            cluster_size,
            current_term: 0,
            voted_for: None,
            role: NodeRole::Follower,
            votes_received: 0,
            is_connected: true,
            election_timeout: Duration::from_millis(300),
            last_heartbeat_or_vote: Instant::now(),
            heartbeat_interval: Duration::from_millis(70),
            last_heartbeat_sent: Instant::now(),
            router,
            receiver,
            running,
        };
        node.reset_election_timeout();
        node
    }

    /// Réinitialise le délai d'élection de façon aléatoire entre 200ms et 400ms pour éviter le split-vote.
    fn reset_election_timeout(&mut self) {
        let mut rng = rand::thread_rng();
        let millis = rng.gen_range(200..400);
        self.election_timeout = Duration::from_millis(millis);
        self.last_heartbeat_or_vote = Instant::now();
    }

    /// Démarre la boucle principale d'événements du nœud.
    pub fn run(&mut self) {
        while self.running.load(Ordering::Relaxed) {
            let wait_duration = match self.role {
                NodeRole::Leader => {
                    let elapsed = self.last_heartbeat_sent.elapsed();
                    if elapsed >= self.heartbeat_interval {
                        Duration::from_millis(0)
                    } else {
                        self.heartbeat_interval - elapsed
                    }
                }
                NodeRole::Follower | NodeRole::Candidate => {
                    let elapsed = self.last_heartbeat_or_vote.elapsed();
                    if elapsed >= self.election_timeout {
                        Duration::from_millis(0)
                    } else {
                        self.election_timeout - elapsed
                    }
                }
            };

            match self.receiver.recv_timeout(wait_duration) {
                Ok(event) => self.handle_event(event),
                Err(RecvTimeoutError::Timeout) => self.handle_timeout(),
                Err(RecvTimeoutError::Disconnected) => break,
            }
        }
    }

    fn handle_event(&mut self, event: NodeEvent) {
        match event {
            NodeEvent::Control(cmd) => match cmd {
                NodeCommand::Disconnect => {
                    self.is_connected = false;
                    println!("[Nœud {}] Réseau coupé (déconnecté).", self.id);
                }
                NodeCommand::Reconnect => {
                    self.is_connected = true;
                    self.reset_election_timeout();
                    println!("[Nœud {}] Réseau rétabli (reconnecté).", self.id);
                }
                NodeCommand::Stop => {
                    self.running.store(false, Ordering::Relaxed);
                }
            },
            NodeEvent::Network(msg) => {
                if !self.is_connected {
                    // Les messages entrants sont ignorés lorsque le nœud subit une panne de communication
                    return;
                }
                self.handle_network_message(msg);
            }
        }
    }

    fn handle_network_message(&mut self, msg: NetworkMessage) {
        let from = msg.from;
        match msg.payload {
            MessagePayload::RequestVoteArgs { term, candidate_id } => {
                self.on_request_vote_args(from, term, candidate_id);
            }
            MessagePayload::RequestVoteReply { term, vote_granted } => {
                self.on_request_vote_reply(from, term, vote_granted);
            }
            MessagePayload::AppendEntriesArgs { term, leader_id } => {
                self.on_append_entries_args(from, term, leader_id);
            }
            MessagePayload::AppendEntriesReply { term, success } => {
                self.on_append_entries_reply(from, term, success);
            }
        }
    }

    fn on_request_vote_args(&mut self, from: usize, term: usize, candidate_id: usize) {
        if term > self.current_term {
            self.current_term = term;
            self.role = NodeRole::Follower;
            self.voted_for = None;
        }

        let mut vote_granted = false;
        if term == self.current_term
            && (self.voted_for.is_none() || self.voted_for == Some(candidate_id))
        {
            vote_granted = true;
            self.voted_for = Some(candidate_id);
            self.reset_election_timeout();
            println!(
                "[Nœud {}] Accorde son vote au candidat {} pour le terme {}.",
                self.id, candidate_id, term
            );
        }

        self.send_network(
            from,
            MessagePayload::RequestVoteReply {
                term: self.current_term,
                vote_granted,
            },
        );
    }

    fn on_request_vote_reply(&mut self, from: usize, term: usize, vote_granted: bool) {
        if term > self.current_term {
            self.current_term = term;
            self.role = NodeRole::Follower;
            self.voted_for = None;
            self.reset_election_timeout();
            return;
        }

        if self.role == NodeRole::Candidate && term == self.current_term && vote_granted {
            self.votes_received += 1;
            let majority = (self.cluster_size / 2) + 1;
            println!(
                "[Nœud {}] Vote reçu de {} (Total: {}/{}) pour terme {}.",
                self.id, from, self.votes_received, majority, self.current_term
            );
            if self.votes_received >= majority {
                self.role = NodeRole::Leader;
                println!(
                    "🏆 [Nœud {}] ÉLU LEADER pour le terme {} !",
                    self.id, self.current_term
                );
                self.send_heartbeats();
            }
        }
    }

    fn on_append_entries_args(&mut self, from: usize, term: usize, leader_id: usize) {
        if term > self.current_term {
            self.current_term = term;
            self.role = NodeRole::Follower;
            self.voted_for = None;
        }

        let mut success = false;
        if term == self.current_term {
            if self.role == NodeRole::Candidate {
                self.role = NodeRole::Follower;
            }
            self.reset_election_timeout();
            success = true;
        }

        self.send_network(
            from,
            MessagePayload::AppendEntriesReply {
                term: self.current_term,
                success,
            },
        );
        let _ = leader_id;
    }

    fn on_append_entries_reply(&mut self, _from: usize, term: usize, _success: bool) {
        if term > self.current_term {
            println!(
                "[Nœud {}] Terme obsolète détecté ({}) < ({}). Rétrogradation en Follower.",
                self.id, self.current_term, term
            );
            self.current_term = term;
            self.role = NodeRole::Follower;
            self.voted_for = None;
            self.reset_election_timeout();
        }
    }

    fn handle_timeout(&mut self) {
        match self.role {
            NodeRole::Leader => {
                if self.is_connected {
                    self.send_heartbeats();
                }
            }
            NodeRole::Follower | NodeRole::Candidate => {
                if self.is_connected {
                    self.start_election();
                } else {
                    self.reset_election_timeout();
                }
            }
        }
    }

    fn start_election(&mut self) {
        self.role = NodeRole::Candidate;
        self.current_term += 1;
        self.voted_for = Some(self.id);
        self.votes_received = 1; // Vote pour soi-même
        self.reset_election_timeout();

        println!(
            "🗳️  [Nœud {}] Timeout expiré : démarre une élection pour le terme {}.",
            self.id, self.current_term
        );

        let majority = (self.cluster_size / 2) + 1;
        if self.votes_received >= majority {
            self.role = NodeRole::Leader;
            println!(
                "🏆 [Nœud {}] ÉLU LEADER pour le terme {} (seul dans le cluster) !",
                self.id, self.current_term
            );
            self.send_heartbeats();
            return;
        }

        let payload = MessagePayload::RequestVoteArgs {
            term: self.current_term,
            candidate_id: self.id,
        };

        if let Ok(router) = self.router.lock() {
            router.broadcast(self.id, payload);
        }
    }

    fn send_heartbeats(&mut self) {
        self.last_heartbeat_sent = Instant::now();
        let payload = MessagePayload::AppendEntriesArgs {
            term: self.current_term,
            leader_id: self.id,
        };

        if let Ok(router) = self.router.lock() {
            router.broadcast(self.id, payload);
        }
    }

    fn send_network(&self, to: usize, payload: MessagePayload) {
        if !self.is_connected {
            return;
        }
        let msg = NetworkMessage {
            from: self.id,
            to,
            payload,
        };
        if let Ok(router) = self.router.lock() {
            router.send(msg);
        }
    }
}

fn main() {
    println!("=== Simulateur de Consensus Raft (Élection & Terme Logique) ===");
    let cluster_size = 5;
    let running = Arc::new(AtomicBool::new(true));
    let router = Arc::new(Mutex::new(NetworkRouter::new()));

    let mut node_handles: Vec<JoinHandle<()>> = Vec::new();

    // 1. Initialisation des nœuds et des canaux de communication
    for id in 0..cluster_size {
        let (tx, rx) = channel::<NodeEvent>();
        if let Ok(mut r) = router.lock() {
            r.register(id, tx);
        }

        let node_router = Arc::clone(&router);
        let node_running = Arc::clone(&running);

        let handle = thread::Builder::new()
            .name(format!("raft-node-{}", id))
            .spawn(move || {
                let mut node =
                    RaftNode::new(id, cluster_size, node_router, rx, node_running);
                node.run();
            })
            .expect("Échec lors du spawn du thread Raft");

        node_handles.push(handle);
    }

    println!("Cluster de {} nœuds démarré. Attente de la première élection...", cluster_size);

    // 2. Observer l'élection initiale et la stabilisation
    thread::sleep(Duration::from_millis(1500));

    // 3. Provoquer la déconnexion d'un nœud (le nœud 0 par exemple) pour observer la réaction du cluster
    println!("\n--- [Simulation] Déconnexion forcée du Nœud 0 ---");
    if let Ok(r) = router.lock() {
        r.send_command(0, NodeCommand::Disconnect);
    }

    // Laisser le temps à un nouveau leader d'être élu ou au cluster de maintenir son fonctionnement
    thread::sleep(Duration::from_millis(2000));

    // 4. Reconnexion du Nœud 0
    println!("\n--- [Simulation] Reconnexion du Nœud 0 ---");
    if let Ok(r) = router.lock() {
        r.send_command(0, NodeCommand::Reconnect);
    }

    thread::sleep(Duration::from_millis(1500));

    // 5. Arrêt propre de tous les nœuds
    println!("\n--- [Arrêt] Envoi du signal d'arrêt à tous les nœuds ---");
    running.store(false, Ordering::Relaxed);
    for id in 0..cluster_size {
        if let Ok(r) = router.lock() {
            r.send_command(id, NodeCommand::Stop);
        }
    }

    for handle in node_handles {
        let _ = handle.join();
    }

    println!("Simulation Raft terminée avec succès sans panique ni deadlock.");
}

