```rust
// src/main.rs
use std::fs::{self, File};
use std::io::{BufReader, BufWriter, Read, Write};
use std::path::{Path, PathBuf};

use anyhow::{bail, Context, Result};
use clap::{Parser, Subcommand};
use indicatif::{ProgressBar, ProgressStyle};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

/// CLI de découpage de fichiers binaires en blocs et contrôle d'intégrité
#[derive(Parser, Debug)]
#[command(name = "binsplit", version, about, long_about = None)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Découpe un fichier binaire en blocs avec manifeste de contrôle
    Split {
        /// Chemin du fichier source à découper
        #[arg(short, long)]
        input: PathBuf,

        /// Répertoire de sortie (créé s'il n'existe pas)
        #[arg(short, long, default_value = "chunks_out")]
        output_dir: PathBuf,

        /// Taille de chaque bloc (ex: 64K, 10M, 1G ou nombre d'octets)
        #[arg(short, long, default_value = "10M")]
        chunk_size: String,

        /// Nom du fichier manifeste JSON
        #[arg(short, long, default_value = "manifest.json")]
        manifest_name: String,
    },

    /// Vérifie l'intégrité des blocs par rapport à un manifeste
    Verify {
        /// Chemin vers le fichier manifeste (manifest.json)
        #[arg(short, long)]
        manifest: PathBuf,
    },

    /// Reconstitue le fichier original à partir d'un manifeste et de ses blocs
    Join {
        /// Chemin vers le fichier manifeste (manifest.json)
        #[arg(short, long)]
        manifest: PathBuf,

        /// Chemin du fichier restauré en sortie (par défaut : nom d'origine dans le répertoire courant)
        #[arg(short, long)]
        output: Option<PathBuf>,
    },
}

/// Métadonnées d'un bloc individuel
#[derive(Serialize, Deserialize, Debug, Clone, PartialEq, Eq)]
pub struct ChunkInfo {
    pub index: usize,
    pub filename: String,
    pub size_bytes: u64,
    pub sha256: String,
}

/// Manifeste de contrôle d'intégrité
#[derive(Serialize, Deserialize, Debug, Clone, PartialEq, Eq)]
pub struct Manifest {
    pub source_filename: String,
    pub source_size_bytes: u64,
    pub source_sha256: String,
    pub chunk_size_bytes: u64,
    pub total_chunks: usize,
    pub chunks: Vec<ChunkInfo>,
}

fn parse_size(size_str: &str) -> Result<u64> {
    let s = size_str.trim();
    if s.is_empty() {
        bail!("La taille ne peut pas être vide");
    }

    let (num_part, multiplier) = if s.ends_with(|c: char| c.is_alphabetic()) {
        let last_char = match s.chars().last() {
            Some(c) => c.to_ascii_uppercase(),
            None => bail!("Chaîne vide inattendue"),
        };
        let num_part = s[..s.len() - 1].trim();
        let factor = match last_char {
            'B' => 1u64,
            'K' => 1024u64,
            'M' => 1024u64 * 1024,
            'G' => 1024u64 * 1024 * 1024,
            'T' => 1024u64 * 1024 * 1024 * 1024,
            _ => bail!("Unité non supportée: '{}'. Utilisez B, K, M, G ou T", last_char),
        };
        (num_part, factor)
    } else {
        (s, 1u64)
    };

    let base_val: u64 = num_part
        .parse()
        .with_context(|| format!("Impossible de convertir '{}' en nombre entier", num_part))?;

    if base_val == 0 {
        bail!("La taille d'un bloc doit être strictement supérieure à 0 octet");
    }

    base_val
        .checked_mul(multiplier)
        .context("Dépassement arithmétique lors du calcul de la taille de bloc")
}

fn split_file(
    input_path: &Path,
    output_dir: &Path,
    chunk_size_bytes: u64,
    manifest_name: &str,
) -> Result<()> {
    if !input_path.is_file() {
        bail!("Le fichier source n'existe pas ou n'est pas un fichier standard : {:?}", input_path);
    }

    let source_filename = input_path
        .file_name()
        .context("Nom de fichier source introuvable")?
        .to_string_lossy()
        .to_string();

    fs::create_dir_all(output_dir)
        .with_context(|| format!("Échec de création du dossier {:?}", output_dir))?;

    let file = File::open(input_path)
        .with_context(|| format!("Échec d'ouverture du fichier {:?}", input_path))?;
    let total_size = file.metadata()?.len();

    let mut reader = BufReader::with_capacity(1024 * 1024, file);
    let mut total_hasher = Sha256::new();

    let pb = ProgressBar::new(total_size);
    pb.set_style(
        ProgressStyle::default_bar()
            .template("{spinner:.green} [{elapsed_precise}] [{bar:40.cyan/blue}] {bytes}/{total_bytes} ({eta})")
            .unwrap_or_else(|_| ProgressStyle::default_bar())
            .progress_chars("#>-"),
    );

    let mut chunks: Vec<ChunkInfo> = Vec::new();
    let mut chunk_index: usize = 0;
    let mut total_bytes_read: u64 = 0;

    let internal_buf_size = (chunk_size_bytes.min(1024 * 1024 * 8)) as usize;
    let mut buffer = vec![0u8; internal_buf_size.max(4096)];

    while total_bytes_read < total_size || total_size == 0 {
        let chunk_filename = format!("{}.part{:04}", source_filename, chunk_index);
        let chunk_path = output_dir.join(&chunk_filename);

        let chunk_file = File::create(&chunk_path)
            .with_context(|| format!("Impossible de créer le bloc {:?}", chunk_path))?;
        let mut chunk_writer = BufWriter::with_capacity(1024 * 1024, chunk_file);

        let mut chunk_hasher = Sha256::new();
        let mut chunk_bytes_written: u64 = 0;

        while chunk_bytes_written < chunk_size_bytes {
            let max_read = (chunk_size_bytes - chunk_bytes_written).min(buffer.len() as u64) as usize;
            let bytes_read = reader.read(&mut buffer[..max_read])?;
            if bytes_read == 0 {
                break;
            }

            let slice = &buffer[..bytes_read];
            chunk_writer.write_all(slice)?;
            chunk_hasher.update(slice);
            total_hasher.update(slice);

            chunk_bytes_written += bytes_read as u64;
            total_bytes_read += bytes_read as u64;
            pb.inc(bytes_read as u64);
        }

        chunk_writer.flush()?;

        let chunk_hash = hex::encode(chunk_hasher.finalize());
        chunks.push(ChunkInfo {
            index: chunk_index,
            filename: chunk_filename,
            size_bytes: chunk_bytes_written,
            sha256: chunk_hash,
        });

        chunk_index += 1;

        if bytes_read_finished(total_bytes_read, total_size) {
            break;
        }
    }

    pb.finish_with_message("Découpage terminé");

    let source_sha256 = hex::encode(total_hasher.finalize());
    let manifest = Manifest {
        source_filename,
        source_size_bytes: total_size,
        source_sha256,
        chunk_size_bytes,
        total_chunks: chunks.len(),
        chunks,
    };

    let manifest_path = output_dir.join(manifest_name);
    let manifest_file = File::create(&manifest_path)
        .with_context(|| format!("Impossible de créer le fichier manifeste {:?}", manifest_path))?;
    serde_json::to_writer_pretty(manifest_file, &manifest)
        .context("Échec de sérialisation du manifeste")?;

    println!("Découpage réussi !");
    println!("  Fichier source : {} octets", total_size);
    println!("  Blocs générés  : {}", manifest.total_chunks);
    println!("  SHA-256 source : {}", manifest.source_sha256);
    println!("  Manifeste      : {:?}", manifest_path);

    Ok(())
}

fn bytes_read_finished(total_read: u64, total_size: u64) -> bool {
    total_size == 0 || total_read >= total_size
}

fn load_manifest(manifest_path: &Path) -> Result<Manifest> {
    let file = File::open(manifest_path)
        .with_context(|| format!("Impossible d'ouvrir le manifeste {:?}", manifest_path))?;
    let reader = BufReader::new(file);
    let manifest: Manifest = serde_json::from_reader(reader)
        .with_context(|| format!("Format de manifeste invalide dans {:?}", manifest_path))?;
    Ok(manifest)
}

fn verify_manifest(manifest_path: &Path) -> Result<()> {
    let manifest = load_manifest(manifest_path)?;
    let base_dir = manifest_path.parent().unwrap_or_else(|| Path::new("."));

    println!("Vérification du manifeste : {:?}", manifest_path);
    println!("Fichier cible : {} ({} blocs)", manifest.source_filename, manifest.total_chunks);

    let mut global_hasher = Sha256::new();
    let mut total_recomputed_bytes: u64 = 0;
    let mut errors: Vec<String> = Vec::new();

    let mut buffer = vec![0u8; 1024 * 1024];

    for chunk in &manifest.chunks {
        let chunk_path = base_dir.join(&chunk.filename);
        if !chunk_path.is_file() {
