            continue;
        }

        let file = match File::open(&chunk_path) {
            Ok(f) => f,
            Err(e) => {
                errors.push(format!("Impossible d'ouvrir {:?} : {}", chunk_path, e));
                continue;
            }
        };

        let metadata = file.metadata()?;
        if metadata.len() != chunk.size_bytes {
            errors.push(format!(
                "Taille incorrecte pour {:?} : attendu {} octets, trouvé {} octets",
                chunk.filename, chunk.size_bytes, metadata.len()
            ));
        }

        let mut reader = BufReader::new(file);
        let mut hasher = Sha256::new();

        loop {
            let n = reader.read(&mut buffer)?;
            if n == 0 {
                break;
            }
            hasher.update(&buffer[..n]);
            global_hasher.update(&buffer[..n]);
            total_recomputed_bytes += n as u64;
        }

        let computed_chunk_hash = hex::encode(hasher.finalize());
        if computed_chunk_hash != chunk.sha256 {
            errors.push(format!(
                "Checksum non concordant pour {:?} : attendu {}, calculé {}",
                chunk.filename, chunk.sha256, computed_chunk_hash
            ));
        } else {
            println!("  [OK] Bloc {} ({} octets)", chunk.filename, chunk.size_bytes);
        }
    }

    let computed_global_hash = hex::encode(global_hasher.finalize());

    if total_recomputed_bytes != manifest.source_size_bytes {
        errors.push(format!(
            "Taille totale non conforme : attendu {} octets, calculé {}",
            manifest.source_size_bytes, total_recomputed_bytes
        ));
    }

    if computed_global_hash != manifest.source_sha256 {
        errors.push(format!(
            "Empreinte globale recalculée non conforme : attendu {}, recalculé {}",
            manifest.source_sha256, computed_global_hash
        ));
    }

    if !errors.is_empty() {
        eprintln!("\nÉCHEC DE L'INTÉGRITÉ ({} erreurs détectées) :", errors.len());
        for err in &errors {
            eprintln!("  - {}", err);
        }
        bail!("Vérification d'intégrité échouée");
    }

    println!("\nTous les blocs sont valides et intègres !");
    println!("SHA-256 validé : {}", computed_global_hash);
    Ok(())
}

fn join_file(manifest_path: &Path, output_path: Option<PathBuf>) -> Result<()> {
    let manifest = load_manifest(manifest_path)?;
    let base_dir = manifest_path.parent().unwrap_or_else(|| Path::new("."));

    let target_out = output_path.unwrap_or_else(|| PathBuf::from(&manifest.source_filename));

    println!("Reconstitution vers : {:?}", target_out);

    let out_file = File::create(&target_out)
        .with_context(|| format!("Impossible de créer le fichier de sortie {:?}", target_out))?;
    let mut writer = BufWriter::with_capacity(1024 * 1024, out_file);
