    let final_hash = hex::encode(global_hasher.finalize());
    if final_hash != manifest.source_sha256 {
        bail!(
            "Erreur d'intégrité globale : attendu {}, calculé {}",
            manifest.source_sha256, final_hash
        );
    }

    println!("Reconstitution terminée avec succès !");
    println!("Empreinte SHA-256 certifiée : {}", final_hash);
    Ok(())
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Split {
            input,
            output_dir,
            chunk_size,
            manifest_name,
        } => {
            let chunk_size_bytes = parse_size(&chunk_size)?;
            split_file(&input, &output_dir, chunk_size_bytes, &manifest_name)?;
