```rust
// src/main.rs
use std::fs::{File, OpenOptions};
use std::io::{self, Read, Seek, SeekFrom, Write};
use std::ops::{Deref, DerefMut};
use std::os::unix::io::AsRawFd;
use std::path::Path;
use std::sync::Arc;
use std::thread;
use std::time::Duration;
use thiserror::Error;

/// Erreurs possibles lors des opérations de verrouillage de fichiers Unix.
#[derive(Debug, Error)]
pub enum LockError {
    #[error("Le verrou n'a pas pu être acquis car la ressource est occupée (non-bloquant)")]
    WouldBlock,

    #[error("Erreur système d'entrée/sortie : {0}")]
    Io(#[from] io::Error),

    #[error("Opération interrompue par un signal")]
    Interrupted,
}

/// Mode de verrouillage demandé.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LockMode {
    /// Verrou partagé (lecture concurrente autorisée)
    Shared,
    /// Verrou exclusif (accès exclusif en écriture)
    Exclusive,
}

impl LockMode {
    fn to_flock_flags(self, non_blocking: bool) -> libc::c_int {
        let mut flags = match self {
            LockMode::Shared => libc::LOCK_SH,
            LockMode::Exclusive => libc::LOCK_EX,
        };
        if non_blocking {
            flags |= libc::LOCK_NB;
        }
        flags
    }
}

/// Gardien RAII pour un verrou de fichier Unix.
///
/// Libère automatiquement le verrou à la destruction (`Drop`)
/// et permet d'accéder au fichier sous-jacent par déréférencement (`Deref` / `DerefMut`).
pub struct FileLock<F: AsRawFd> {
    file: Option<F>,
    mode: LockMode,
}

impl<F: AsRawFd> FileLock<F> {
    /// Acquiert un verrou (bloquant).
    pub fn lock(file: F, mode: LockMode) -> Result<Self, LockError> {
        Self::apply_flock(&file, mode, false)?;
        Ok(Self {
            file: Some(file),
            mode,
        })
    }

    /// Tente d'acquérir un verrou immédiatement (non-bloquant).
    pub fn try_lock(file: F, mode: LockMode) -> Result<Self, LockError> {
        Self::apply_flock(&file, mode, true)?;
        Ok(Self {
            file: Some(file),
            mode,
        })
    }

    /// Mode actuel du verrou.
    pub fn mode(&self) -> LockMode {
        self.mode
    }

    /// Libère explicitement le verrou et restitue le descripteur / fichier sous-jacent.
    pub fn unlock(mut self) -> Result<F, (F, LockError)> {
        if let Some(file) = self.file.take() {
            if let Err(err) = Self::release_flock(&file) {
                return Err((file, err));
            }
            Ok(file)
        } else {
            unreachable!("FileLock ne peut pas être vide avant sa libération");
        }
    }

    fn apply_flock(file: &F, mode: LockMode, non_blocking: bool) -> Result<(), LockError> {
        let fd = file.as_raw_fd();
        let flags = mode.to_flock_flags(non_blocking);

        loop {
            let res = unsafe { libc::flock(fd, flags) };
            if res == 0 {
                return Ok(());
            }

            let err = io::Error::last_os_error();
            match err.raw_os_error() {
                Some(libc::EWOULDBLOCK) => return Err(LockError::WouldBlock),
                Some(libc::EINTR) => continue, // Recommencer si interrompu par un signal
                _ => return Err(LockError::Io(err)),
            }
        }
    }

    fn release_flock(file: &F) -> Result<(), LockError> {
        let fd = file.as_raw_fd();
        loop {
            let res = unsafe { libc::flock(fd, libc::LOCK_UN) };
            if res == 0 {
                return Ok(());
            }

            let err = io::Error::last_os_error();
            match err.raw_os_error() {
                Some(libc::EINTR) => continue,
                _ => return Err(LockError::Io(err)),
            }
        }
    }
}

impl<F: AsRawFd> Deref for FileLock<F> {
    type Target = F;

    fn deref(&self) -> &Self::Target {
        self.file
            .as_ref()
            .expect("Le fichier est toujours présent pendant la durée de vie de FileLock")
    }
}

impl<F: AsRawFd> DerefMut for FileLock<F> {
    fn deref_mut(&mut self) -> &mut Self::Target {
        self.file
            .as_mut()
            .expect("Le fichier est toujours présent pendant la durée de vie de FileLock")
    }
}

impl<F: AsRawFd> Drop for FileLock<F> {
    fn drop(&mut self) {
        if let Some(file) = self.file.take() {
            let _ = Self::release_flock(&file);
        }
    }
}

