```rust
// src/main.rs
use std::fmt;
use thiserror::Error;

// ============================================================================
// 1. Structure Abstraite Typée (AST - Abstract Syntax Tree)
// ============================================================================

/// Représente une requête SQL `SELECT` analysée.
#[derive(Debug, Clone, PartialEq)]
pub struct SelectStatement {
    pub projections: Vec<SelectItem>,
    pub from: TableReference,
    pub where_clause: Option<Expression>,
}

/// Un élément de projection dans la clause `SELECT`.
#[derive(Debug, Clone, PartialEq)]
pub enum SelectItem {
    /// Sélection de toutes les colonnes (`*`)
    Wildcard,
    /// Colonne ou expression nommée avec alias optionnel (`col AS alias` ou `col alias`)
    Column {
        name: String,
        alias: Option<String>,
    },
}

/// Référence de table dans la clause `FROM`.
#[derive(Debug, Clone, PartialEq)]
pub struct TableReference {
    pub name: String,
    pub alias: Option<String>,
}

/// Représente une expression ou condition dans la clause `WHERE`.
#[derive(Debug, Clone, PartialEq)]
pub enum Expression {
    /// Référence à un identifiant (nom de colonne)
    Column(String),
    /// Valeur littérale
    Literal(Literal),
    /// Expression binaire (ex: `age >= 18`, `status = 'active' AND role = 'admin'`)
    BinaryOp {
        left: Box<Expression>,
        op: BinaryOperator,
        right: Box<Expression>,
    },
    /// Test de nullité `IS NULL` ou `IS NOT NULL`
    IsNull {
        expr: Box<Expression>,
        negated: bool,
    },
    /// Test d'appartenance `IN (...)` ou `NOT IN (...)`
    InList {
        expr: Box<Expression>,
        list: Vec<Expression>,
        negated: bool,
    },
}

/// Opérateurs binaires supportés.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BinaryOperator {
    Eq,        // =
    NotEq,     // != ou <>
    Lt,        // <
    LtEq,      // <=
    Gt,        // >
    GtEq,      // >=
    And,       // AND
    Or,        // OR
    Like,      // LIKE
}

/// Littéraux supportés dans les expressions.
#[derive(Debug, Clone, PartialEq)]
pub enum Literal {
    Number(f64),
    String(String),
    Boolean(bool),
    Null,
}

impl fmt::Display for BinaryOperator {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let op_str = match self {
            Self::Eq => "=",
            Self::NotEq => "!=",
            Self::Lt => "<",
            Self::LtEq => "<=",
            Self::Gt => ">",
            Self::GtEq => ">=",
            Self::And => "AND",
            Self::Or => "OR",
            Self::Like => "LIKE",
        };
        write!(f, "{op_str}")
    }
}

impl fmt::Display for Literal {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Number(n) => write!(f, "{n}"),
            Self::String(s) => write!(f, "'{s}'"),
            Self::Boolean(b) => write!(f, "{}", if *b { "TRUE" } else { "FALSE" }),
            Self::Null => write!(f, "NULL"),
        }
    }
}

impl fmt::Display for SelectItem {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Wildcard => write!(f, "*"),
            Self::Column { name, alias } => match alias {
                Some(al) => write!(f, "{name} AS {al}"),
                None => write!(f, "{name}"),
            },
        }
    }
}

impl fmt::Display for Expression {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Column(name) => write!(f, "{name}"),
            Self::Literal(lit) => write!(f, "{lit}"),
            Self::BinaryOp { left, op, right } => {
                write!(f, "({left} {op} {right})")
            }
            Self::IsNull { expr, negated } => {
                if *negated {
                    write!(f, "{expr} IS NOT NULL")
                } else {
                    write!(f, "{expr} IS NULL")
                }
            }
            Self::InList { expr, list, negated } => {
                let items: Vec<String> = list.iter().map(|e| e.to_string()).collect();
                let op = if *negated { "NOT IN" } else { "IN" };
                write!(f, "{expr} {op} ({})", items.join(", "))
            }
        }
    }
}

impl fmt::Display for SelectStatement {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let cols: Vec<String> = self.projections.iter().map(|p| p.to_string()).collect();
        write!(f, "SELECT {}", cols.join(", "))?;
        write!(f, " FROM {}", self.from.name)?;
        if let Some(alias) = &self.from.alias {
            write!(f, " AS {alias}")?;
        }
        if let Some(cond) = &self.where_clause {
            write!(f, " WHERE {cond}")?;
        }
        Ok(())
    }
}

// ============================================================================
// 2. Lexer / Tokenizer
// ============================================================================

#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    // Mots-clés
    Select,
    From,
    Where,
    As,
    And,
    Or,
    Like,
    Is,
    Not,
    In,
    Null,
    True,
    False,

    // Ponctuation / Symboles
    Asterisk,
    Comma,
    OpenParen,
    CloseParen,
    Eq,
    NotEq,
    Lt,
    LtEq,
    Gt,
    GtEq,

    // Valeurs & Identifiants
    Identifier(String),
    Number(f64),
    StringLiteral(String),

    Eof,
}

#[derive(Error, Debug, PartialEq)]
pub enum LexError {
    #[error("Chaîne non terminée commençant à l'indice {0}")]
    UnterminatedString(usize),
    #[error("Nombre invalide '{0}' à l'indice {1}")]
    InvalidNumber(String, usize),
    #[error("Caractère inattendu '{0}' à l'indice {1}")]
    UnexpectedCharacter(char, usize),
}

pub struct Lexer<'a> {
    chars: Vec<(usize, char)>,
    cursor: usize,
    _source: &'a str,
}

impl<'a> Lexer<'a> {
    pub fn new(source: &'a str) -> Self {
        Self {
            chars: source.char_indices().collect(),
            cursor: 0,
            _source: source,
        }
    }

    fn peek(&self) -> Option<(usize, char)> {
        self.chars.get(self.cursor).copied()
    }

    fn peek_next(&self) -> Option<(usize, char)> {
        self.chars.get(self.cursor + 1).copied()
    }

    fn advance(&mut self) -> Option<(usize, char)> {
        let ch = self.peek();
        if ch.is_some() {
            self.cursor += 1;
        }
        ch
    }

    pub fn tokenize(&mut self) -> Result<Vec<Token>, LexError> {
        let mut tokens = Vec::new();

        while let Some((pos, ch)) = self.peek() {
            if ch.is_whitespace() {
                self.advance();
                continue;
            }

            match ch {
                ',' => {
                    self.advance();
                    tokens.push(Token::Comma);
                }
                '*' => {
                    self.advance();
                    tokens.push(Token::Asterisk);
                }
                '(' => {
                    self.advance();
                    tokens.push(Token::OpenParen);
                }
                ')' => {
                    self.advance();
                    tokens.push(Token::CloseParen);
                }
                '=' => {
                    self.advance();
                    tokens.push(Token::Eq);
                }
                '!' => {
                    self.advance();
                    if let Some((_, '=')) = self.peek() {
                        self.advance();
                        tokens.push(Token::NotEq);
                    } else {
                        return Err(LexError::UnexpectedCharacter('!', pos));
                    }
                }
                '<' => {
                    self.advance();
                    if let Some((_, '=')) = self.peek() {
                        self.advance();
                        tokens.push(Token::LtEq);
                    } else if let Some((_, '>')) = self.peek() {
                        self.advance();
                        tokens.push(Token::NotEq);
                    } else {
                        tokens.push(Token::Lt);
                    }
                }
                '>' => {
                    self.advance();
                    if let Some((_, '=')) = self.peek() {
                        self.advance();
                        tokens.push(Token::GtEq);
                    } else {
                        tokens.push(Token::Gt);
                    }
                }
                '\'' => {
                    tokens.push(self.tokenize_string(pos)?);
                }
                c if c.is_ascii_digit() => {
                    tokens.push(self.tokenize_number(pos)?);
                }
                c if c.is_alphabetic() || c == '_' => {
                    tokens.push(self.tokenize_identifier());
                }
                c => {
                    return Err(LexError::UnexpectedCharacter(c, pos));
                }
            }
        }

        tokens.push(Token::Eof);
        Ok(tokens)
    }

    fn tokenize_string(&mut self, start_pos: usize) -> Result<Token, LexError> {
        self.advance(); // Consomme l'apostrophe initiale
        let mut text = String::new();

        loop {
            match self.advance() {
                Some((_, '\'')) => {
                    // Gestion de l'échappement par double-quote SQL: ''
                    if let Some((_, '\'')) = self.peek() {
                        self.advance();
                        text.push('\'');
                    } else {
                        break;
                    }
                }
                Some((_, ch)) => text.push(ch),
                None => return Err(LexError::UnterminatedString(start_pos)),
            }
        }

        Ok(Token::StringLiteral(text))
    }

    fn tokenize_number(&mut self, start_pos: usize) -> Result<Token, LexError> {
        let mut num_str = String::new();
        let mut seen_dot = false;

        while let Some((_, ch)) = self.peek() {
            if ch.is_ascii_digit() {
                num_str.push(ch);
                self.advance();
            } else if ch == '.' && !seen_dot {
                if let Some((_, next_ch)) = self.peek_next() {
                    if next_ch.is_ascii_digit() {
                        seen_dot = true;
                        num_str.push(ch);
                        self.advance();
                        continue;
                    }
                }
                break;
            } else {
                break;
            }
        }

        let val: f64 = num_str
            .parse()
            .map_err(|_| LexError::InvalidNumber(num_str, start_pos))?;

        Ok(Token::Number(val))
    }

    fn tokenize_identifier(&mut self) -> Token {
        let mut ident = String::new();

        while let Some((_, ch)) = self.peek() {
            if ch.is_alphanumeric() || ch == '_' || ch == '.' {
                ident.push(ch);
                self.advance();
            } else {
                break;
            }
        }

        match ident.to_ascii_uppercase().as_str() {
            "SELECT" => Token::Select,
            "FROM" => Token::From,
            "WHERE" => Token::Where,
            "AS" => Token::As,
            "AND" => Token::And,
            "OR" => Token::Or,
            "LIKE" => Token::Like,
            "IS" => Token::Is,
            "NOT" => Token::Not,
            "IN" => Token::In,
            "NULL" => Token::Null,
            "TRUE" => Token::True,
            "FALSE" => Token::False,
            _ => Token::Identifier(ident),
        }
    }
}

// ============================================================================
// 3. Parser Syntaxique
// ============================================================================

#[derive(Error, Debug, PartialEq)]
pub enum ParseError {
    #[error("Erreur lexicale: {0}")]
    Lex(#[from] LexError),
    #[error("Fin de requête inattendue")]
    UnexpectedEof,
    #[error("Jeton inattendu: attendu {expected}, trouvé {found:?}")]
    UnexpectedToken {
        expected: &'static str,
        found: Token,
    },
    #[error("Clause WHERE invalide ou incomplète")]
    InvalidWhereClause,
    #[error("Expression invalide")]
    InvalidExpression,
}

pub struct Parser {
    tokens: Vec<Token>,
    cursor: usize,
}

impl Parser {
    pub fn new(tokens: Vec<Token>) -> Self {
        Self { tokens, cursor: 0 }
    }

    pub fn parse_sql(sql: &str) -> Result<SelectStatement, ParseError> {
        let mut lexer = Lexer::new(sql);
        let tokens = lexer.tokenize()?;
        let mut parser = Parser::new(tokens);
        parser.parse_select_statement()
    }

    fn peek(&self) -> &Token {
        self.tokens.get(self.cursor).unwrap_or(&Token::Eof)
    }

    fn advance(&mut self) -> Token {
        let tok = self.peek().clone();
        if self.cursor < self.tokens.len() {
            self.cursor += 1;
        }
        tok
    }

    fn expect(&mut self, expected: Token, description: &'static str) -> Result<(), ParseError> {
        let current = self.peek();
        if *current == expected {
            self.advance();
            Ok(())
        } else {
            Err(ParseError::UnexpectedToken {
                expected: description,
                found: current.clone(),
            })
        }
    }

    /// Point d'entrée pour parser une requête `SELECT ... FROM ... [WHERE ...]`
    pub fn parse_select_statement(&mut self) -> Result<SelectStatement, ParseError> {
        self.expect(Token::Select, "'SELECT'")?;
        let projections = self.parse_projections()?;

        self.expect(Token::From, "'FROM'")?;
        let from = self.parse_table_reference()?;

        let where_clause = if *self.peek() == Token::Where {
            self.advance();
            Some(self.parse_expression(0)?)
        } else {
            None
        };

        if *self.peek() != Token::Eof {
            return Err(ParseError::UnexpectedToken {
                expected: "fin de requête ou mot-clé valide",
                found: self.peek().clone(),
            });
        }

        Ok(SelectStatement {
            projections,
            from,
            where_clause,
        })
    }

    fn parse_projections(&mut self) -> Result<Vec<SelectItem>, ParseError> {
        let mut items = Vec::new();

        loop {
            match self.peek() {
                Token::Asterisk => {
                    self.advance();
                    items.push(SelectItem::Wildcard);
                }
                Token::Identifier(_) => {
                    let col_name = match self.advance() {
                        Token::Identifier(s) => s,
                        _ => unreachable!(),
                    };

                    let alias = if *self.peek() == Token::As {
                        self.advance();
                        match self.advance() {
                            Token::Identifier(al) => Some(al),
                            other => {
                                return Err(ParseError::UnexpectedToken {
                                    expected: "identifiant après AS",
                                    found: other,
                                });
                            }
                        }
                    } else if let Token::Identifier(_) = self.peek() {
                        match self.advance() {
                            Token::Identifier(al) => Some(al),
                            _ => unreachable!(),
                        }
                    } else {
                        None
                    };

                    items.push(SelectItem::Column {
                        name: col_name,
                        alias,
                    });
                }
                other => {
                    return Err(ParseError::UnexpectedToken {
                        expected: "nom de colonne ou '*'",
                        found: other.clone(),
                    });
                }
            }

            if *self.peek() == Token::Comma {
                self.advance();
            } else {
                break;
            }
        }

        if items.is_empty() {
            return Err(ParseError::UnexpectedToken {
                expected: "au moins une colonne ou '*'",
                found: self.peek().clone(),
            });
        }

        Ok(items)
    }

    fn parse_table_reference(&mut self) -> Result<TableReference, ParseError> {
        let name = match self.advance() {
            Token::Identifier(tbl) => tbl,
            other => {
                return Err(ParseError::UnexpectedToken {
                    expected: "nom de table après 'FROM'",
                    found: other,
                });
            }
        };

        let alias = if *self.peek() == Token::As {
            self.advance();
            match self.advance() {
                Token::Identifier(al) => Some(al),
                other => {
                    return Err(ParseError::UnexpectedToken {
                        expected: "alias de table après AS",
                        found: other,
                    });
                }
            }
        } else if let Token::Identifier(_) = self.peek() {
            match self.advance() {
                Token::Identifier(al) => Some(al),
                _ => unreachable!(),
            }
        } else {
            None
        };

        Ok(TableReference { name, alias })
    }

    /// Précédence des opérateurs pour l'algorithme de Pratt
    fn get_precedence(op: &BinaryOperator) -> u8 {
        match op {
            BinaryOperator::Or => 1,
            BinaryOperator::And => 2,
            BinaryOperator::Eq
            | BinaryOperator::NotEq
            | BinaryOperator::Lt
            | BinaryOperator::LtEq
            | BinaryOperator::Gt
            | BinaryOperator::GtEq
            | BinaryOperator::Like => 3,
        }
    }

    fn parse_expression(&mut self, min_precedence: u8) -> Result<Expression, ParseError> {
        let mut left = self.parse_primary()?;

        loop {
            // Gestion des suffixes unaires ou ensembles : IS [NOT] NULL, [NOT] IN (...)
            if *self.peek() == Token::Is {
                self.advance();
                let negated = if *self.peek() == Token::Not {
                    self.advance();
                    true
                } else {
                    false
                };
                self.expect(Token::Null, "'NULL'")?;
                left = Expression::IsNull {
                    expr: Box::new(left),
                    negated,
                };
                continue;
            }

            if *self.peek() == Token::In || (*self.peek() == Token::Not && self.is_next_in()) {
                let negated = if *self.peek() == Token::Not {
                    self.advance(); // consume NOT
                    self.advance(); // consume IN
                    true
                } else {
                    self.advance(); // consume IN
                    false
                };

                self.expect(Token::OpenParen, "'(' après IN")?;
                let mut list = Vec::new();
                if *self.peek() != Token::CloseParen {
                    loop {
                        list.push(self.parse_expression(0)?);
                        if *self.peek() == Token::Comma {
                            self.advance();
                        } else {
                            break;
                        }
                    }
                }
                self.expect(Token::CloseParen, "')' fermante pour IN")?;

                left = Expression::InList {
                    expr: Box::new(left),
                    list,
                    negated,
                };
                continue;
            }

            let op = match self.peek() {
                Token::Eq => BinaryOperator::Eq,
                Token::NotEq => BinaryOperator::NotEq,
                Token::Lt => BinaryOperator::Lt,
                Token::LtEq => BinaryOperator::LtEq,
                Token::Gt => BinaryOperator::Gt,
                Token::GtEq => BinaryOperator::GtEq,
                Token::And => BinaryOperator::And,
                Token::Or => BinaryOperator::Or,
                Token::Like => BinaryOperator::Like,
                _ => break,
            };

            let precedence = Self::get_precedence(&op);
            if precedence < min_precedence {
                break;
            }

            self.advance();
            let right = self.parse_expression(precedence + 1)?;
            left = Expression::BinaryOp {
                left: Box::new(left),
                op,
                right: Box::new(right),
            };
        }

        Ok(left)
    }

    fn is_next_in(&self) -> bool {
        self.tokens.get(self.cursor + 1) == Some(&Token::In)
    }

    fn parse_primary(&mut self) -> Result<Expression, ParseError> {
        match self.advance() {
            Token::Identifier(name) => Ok(Expression::Column(name)),
            Token::Number(val) => Ok(Expression::Literal(Literal::Number(val))),
            Token::StringLiteral(val) => Ok(Expression::Literal(Literal::String(val))),
            Token::True => Ok(Expression::Literal(Literal::Boolean(true))),
            Token::False => Ok(Expression::Literal(Literal::Boolean(false))),
            Token::Null => Ok(Expression::Literal(Literal::Null)),
            Token::OpenParen => {
                let inner = self.parse_expression(0)?;
                self.expect(Token::CloseParen, "')'")?;
                Ok(inner)
            }
            other => Err(ParseError::UnexpectedToken {
                expected: "valeur, identifiant ou parenthèse ouvrante",
                found: other,
            }),
        }
    }
}

// ============================================================================
// 4. Fonction Principale & Démonstration
// ============================================================================

fn main() {
    let queries = [
        "SELECT * FROM users",
        "SELECT id, name AS full_name, email FROM clients c",
        "SELECT id, salary FROM employees WHERE salary >= 50000 AND (dept = 'Tech' OR dept = 'Research')",
        "SELECT title, author FROM books WHERE published_at IS NOT NULL AND status IN ('active', 'review')",
        "SELECT product_id FROM inventory WHERE name LIKE 'Rust%' AND stock > 0",
    ];

    println!("=== DÉMONSTRATION DU PARSER SQL MINIMALISTE ===");

    for (idx, sql) in queries.iter().enumerate() {
        println!("\n--- Requête #{} ---", idx + 1);
        println!("Input: {sql}");
        match Parser::parse_sql(sql) {
            Ok(statement) => {
                println!("Succès du parsing !");
                println!("Structure AST (Debug) :");
                println!("{statement:#?}");
                println!("Formatage standardisé : {statement}");
            }
            Err(err) => {
                eprintln!("Erreur de parsing : {err}");
            }
        }
    }

    // Démonstration de détection d'erreurs
    println!("\n=== TESTS DE CAS D'ERREURS SYNTAXIQUES ===");
    let invalid_queries = [
        "SELECT FROM users",
        "SELECT id, name FROM",
        "SELECT id FROM users WHERE (age > 20",
    ];

    for bad_sql in invalid_queries {
        println!("\nTest erreur: {bad_sql}");
        match Parser::parse_sql(bad_sql) {
            Ok(_) => println!("Échec : requête censée être invalide a été acceptée"),
            Err(e) => println!("Erreur détectée avec succès : {e}"),
        }
    }
}

