#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_select_wildcard() {
        let sql = "SELECT * FROM users";
        let parsed = Parser::parse_sql(sql).expect("devrait parser");
        assert_eq!(parsed.projections, vec![SelectItem::Wildcard]);
        assert_eq!(
            parsed.from,
            TableReference {
                name: "users".to_string(),
                alias: None,
            }
        );
        assert_eq!(parsed.where_clause, None);
    }

    #[test]
    fn test_select_columns_and_aliases() {
        let sql = "SELECT id, name AS user_name, u.email FROM users AS u";
        let parsed = Parser::parse_sql(sql).expect("devrait parser");
        assert_eq!(
            parsed.projections,
            vec![
                SelectItem::Column {
                    name: "id".to_string(),
                    alias: None,
                },
                SelectItem::Column {
                    name: "name".to_string(),
                    alias: Some("user_name".to_string()),
                },
                SelectItem::Column {
                    name: "u.email".to_string(),
                    alias: None,
                },
            ]
        );
        assert_eq!(
            parsed.from,
            TableReference {
                name: "users".to_string(),
                alias: Some("u".to_string()),
            }
        );
    }

    #[test]
    fn test_where_binary_and_or_precedence() {
        let sql = "SELECT * FROM items WHERE a = 1 OR b = 2 AND c = 3";
        let parsed = Parser::parse_sql(sql).expect("devrait parser");
        // AND a une précédence supérieure à OR -> (a = 1) OR (b = 2 AND c = 3)
        let expected_where = Expression::BinaryOp {
            left: Box::new(Expression::BinaryOp {
                left: Box::new(Expression::Column("a".to_string())),
                op: BinaryOperator::Eq,
                right: Box::new(Expression::Literal(Literal::Number(1.0))),
            }),
            op: BinaryOperator::Or,
            right: Box::new(Expression::BinaryOp {
                left: Box::new(Expression::BinaryOp {
                    left: Box::new(Expression::Column("b".to_string())),
                    op: BinaryOperator::Eq,
                    right: Box::new(Expression::Literal(Literal::Number(2.0))),
                }),
                op: BinaryOperator::And,
                right: Box::new(Expression::BinaryOp {
                    left: Box::new(Expression::Column("c".to_string())),
                    op: BinaryOperator::Eq,
                    right: Box::new(Expression::Literal(Literal::Number(3.0))),
                }),
            }),
        };

        assert_eq!(parsed.where_clause, Some(expected_where));
    }

    #[test]
    fn test_where_parentheses() {
        let sql = "SELECT * FROM items WHERE (a = 1 OR b = 2) AND c = 3";
        let parsed = Parser::parse_sql(sql).expect("devrait parser");
        let expected_where = Expression::BinaryOp {
            left: Box::new(Expression::BinaryOp {
                left: Box::new(Expression::BinaryOp {
                    left: Box::new(Expression::Column("a".to_string())),
                    op: BinaryOperator::Eq,
                    right: Box::new(Expression::Literal(Literal::Number(1.0))),
                }),
                op: BinaryOperator::Or,
                right: Box::new(Expression::BinaryOp {
                    left: Box::new(Expression::Column("b".to_string())),
                    op: BinaryOperator::Eq,
                    right: Box::new(Expression::Literal(Literal::Number(2.0))),
                }),
            }),
            op: BinaryOperator::And,
            right: Box::new(Expression::BinaryOp {
                left: Box::new(Expression::Column("c".to_string())),
                op: BinaryOperator::Eq,
                right: Box::new(Expression::Literal(Literal::Number(3.0))),
            }),
        };

        assert_eq!(parsed.where_clause, Some(expected_where));
    }

    #[test]
    fn test_is_null_and_in_list() {
        let sql = "SELECT * FROM users WHERE status IS NOT NULL AND role IN ('admin', 'mod')";
        let parsed = Parser::parse_sql(sql).expect("devrait parser");

        let expected_where = Expression::BinaryOp {
            left: Box::new(Expression::IsNull {
                expr: Box::new(Expression::Column("status".to_string())),
                negated: true,
            }),
            op: BinaryOperator::And,
            right: Box::new(Expression::InList {
                expr: Box::new(Expression::Column("role".to_string())),
                list: vec![
                    Expression::Literal(Literal::String("admin".to_string())),
                    Expression::Literal(Literal::String("mod".to_string())),
                ],
                negated: false,
            }),
        };

        assert_eq!(parsed.where_clause, Some(expected_where));
    }

    #[test]
    fn test_syntax_errors() {
        assert!(Parser::parse_sql("SELECT FROM table").is_err());
        assert!(Parser::parse_sql("SELECT col FROM").is_err());
        assert!(Parser::parse_sql("SELECT col FROM tbl WHERE (col = 1").is_err());
        assert!(Parser::parse_sql("SELECT col FROM tbl WHERE col LIKE").is_err());
    }
}

