// src/main.rs
use anyhow::{Context, Result};
use clap::{Parser, ValueEnum};
use std::fs::File;
use std::io::{self, BufRead, BufReader, BufWriter, Write};
use std::path::PathBuf;
use unicode_width::UnicodeWidthStr;

/// Formats de sortie disponibles pour l'affichage de la table.
#[derive(Debug, Clone, Copy, ValueEnum)]
pub enum OutputFormat {
    /// Format Markdown standard (compatible GitHub/GitLab).
    Markdown,
    /// Format ASCII traditionnel avec bordures (+---+).
    Ascii,
    /// Format grille avec bordures Unicode box-drawing (┌───┬───┐).
    Grid,
}

/// Alignement du contenu dans les colonnes.
#[derive(Debug, Clone, Copy, ValueEnum)]
pub enum Alignment {
    Left,
    Center,
    Right,
}

#[derive(Parser, Debug)]
#[command(
    name = "csv-table-converter",
    author,
    version,
    about = "Convertit un fichier CSV en table Markdown ou ASCII avec dimensionnement automatique.",
    long_about = None
)]
struct Cli {
    /// Chemin du fichier CSV d'entrée (si non renseigné, lit sur stdin).
    #[arg(value_name = "INPUT_FILE")]
    input: Option<PathBuf>,

    /// Chemin du fichier de sortie (si non renseigné, écrit sur stdout).
    #[arg(short, long, value_name = "OUTPUT_FILE")]
    output: Option<PathBuf>,

    /// Format de sortie désiré.
    #[arg(short, long, value_enum, default_value_t = OutputFormat::Markdown)]
    format: OutputFormat,

    /// Délimiteur CSV (ex: ',' ou ';' ou '\t').
    #[arg(short, long, default_value = ",")]
    delimiter: String,

    /// Indique que le CSV ne contient pas de ligne d'en-tête.
    #[arg(long)]
    no_header: bool,

    /// Alignement des colonnes.
    #[arg(short, long, value_enum, default_value_t = Alignment::Left)]
    align: Alignment,
}

/// Représentation en mémoire d'une table avec ses dimensions.
#[derive(Debug, Clone)]
pub struct TableData {
    pub headers: Option<Vec<String>>,
    pub rows: Vec<Vec<String>>,
    pub column_widths: Vec<usize>,
}

impl TableData {
    /// Crée une TableData en calculant automatiquement la largeur optimale de chaque colonne.
    pub fn new(headers: Option<Vec<String>>, rows: Vec<Vec<String>>) -> Self {
        let col_count = headers
            .as_ref()
            .map(|h| h.len())
            .unwrap_or(0)
            .max(rows.iter().map(|r| r.len()).max().unwrap_or(0));

        let mut column_widths = vec![0usize; col_count];

        if let Some(ref h_row) = headers {
            for (idx, cell) in h_row.iter().enumerate() {
                column_widths[idx] = column_widths[idx].max(UnicodeWidthStr::width(cell.as_str()));
            }
        }

        for row in &rows {
            for (idx, cell) in row.iter().enumerate() {
                column_widths[idx] = column_widths[idx].max(UnicodeWidthStr::width(cell.as_str()));
            }
        }

        // Assure une largeur minimale de 1 pour chaque colonne pour éviter les colonnes vides illisibles
        for w in &mut column_widths {
            if *w == 0 {
                *w = 1;
            }
        }

        TableData {
            headers,
            rows,
            column_widths,
        }
    }
}

/// Aligne une chaîne de caractères selon une largeur cible et une règle d'alignement.
fn pad_cell(text: &str, target_width: usize, align: Alignment) -> String {
    let text_width = UnicodeWidthStr::width(text);
    if text_width >= target_width {
        return text.to_string();
    }
    let diff = target_width - text_width;

    match align {
        Alignment::Left => format!("{}{}", text, " ".repeat(diff)),
        Alignment::Right => format!("{}{}", " ".repeat(diff), text),
        Alignment::Center => {
            let left_pad = diff / 2;
            let right_pad = diff - left_pad;
            format!("{}{}{}", " ".repeat(left_pad), text, " ".repeat(right_pad))
        }
    }
}

/// Formate une rangée avec un délimiteur de début, intermédiaire, fin et marge intérieure.
fn format_row(
    cells: &[String],
    col_widths: &[usize],
    align: Alignment,
    left_border: &str,
    col_sep: &str,
    right_border: &str,
) -> String {
    let formatted_cells: Vec<String> = col_widths
        .iter()
        .enumerate()
        .map(|(i, &width)| {
            let content = cells.get(i).map(String::as_str).unwrap_or("");
            format!(" {} ", pad_cell(content, width, align))
        })
        .collect();

    format!(
        "{}{}{}",
        left_border,
        formatted_cells.join(col_sep),
        right_border
    )
}

/// Générateur pour le format Markdown.
pub fn render_markdown(table: &TableData, align: Alignment) -> String {
    let mut out = String::new();

    let empty_row = vec![String::new(); table.column_widths.len()];
    let headers = table.headers.as_ref().unwrap_or(&empty_row);

    // En-tête
    out.push_str(&format_row(
        headers,
        &table.column_widths,
        align,
        "|",
        "|",
        "|\n",
    ));

    // Ligne de séparation
    let sep_cells: Vec<String> = table
        .column_widths
        .iter()
        .map(|&w| match align {
            Alignment::Left => format!(":{}", "-".repeat(w.max(2) + 1)),
            Alignment::Right => format!("{}:", "-".repeat(w.max(2) + 1)),
            Alignment::Center => format!(":{}:", "-".repeat(w.max(2))),
        })
        .collect();

    out.push_str(&format!("|{}|\n", sep_cells.join("|")));

    // Lignes de données
    for row in &table.rows {
        out.push_str(&format_row(
            row,
            &table.column_widths,
            align,
            "|",
            "|",
            "|\n",
        ));
    }

    out
}

/// Générateur pour le format ASCII traditionnel.
pub fn render_ascii(table: &TableData, align: Alignment) -> String {
    let mut out = String::new();

    let build_horizontal_line = |left: &str, mid: &str, right: &str| -> String {
        let segments: Vec<String> = table
            .column_widths
            .iter()
            .map(|&w| "-".repeat(w + 2))
            .collect();
        format!("{}{}{}\n", left, segments.join(mid), right)
    };

    let border = build_horizontal_line("+", "+", "+");

    out.push_str(&border);

    if let Some(ref headers) = table.headers {
        out.push_str(&format_row(
            headers,
            &table.column_widths,
            align,
            "|",
            "|",
            "|\n",
        ));
        out.push_str(&border);
    }

    for row in &table.rows {
        out.push_str(&format_row(
            row,
            &table.column_widths,
            align,
            "|",
            "|",
            "|\n",
        ));
    }

    out.push_str(&border);
    out
}

/// Générateur pour le format Grid Unicode.
pub fn render_grid(table: &TableData, align: Alignment) -> String {
    let mut out = String::new();

    let build_line = |left: &str, mid: &str, right: &str, fill: &str| -> String {
        let segments: Vec<String> = table
            .column_widths
            .iter()
            .map(|&w| fill.repeat(w + 2))
            .collect();
        format!("{}{}{}\n", left, segments.join(mid), right)
    };

    let top_border = build_line("┌", "┬", "┐", "─");
    let mid_border = build_line("├", "┼", "┤", "─");
    let bot_border = build_line("└", "┴", "┘", "─");

    out.push_str(&top_border);

    if let Some(ref headers) = table.headers {
        out.push_str(&format_row(
            headers,
            &table.column_widths,
            align,
            "│",
            "│",
            "│\n",
        ));
        out.push_str(&mid_border);
    }

    for (i, row) in table.rows.iter().enumerate() {
        out.push_str(&format_row(
            row,
            &table.column_widths,
            align,
            "│",
            "│",
            "│\n",
        ));
        if table.headers.is_none() && i + 1 < table.rows.len() {
            out.push_str(&mid_border);
        }
    }

    out.push_str(&bot_border);
    out
}

/// Lit et analyse le CSV depuis un reader.
fn parse_csv<R: BufRead>(
    reader: R,
    delimiter_byte: u8,
    has_header: bool,
) -> Result<TableData> {
    let mut csv_reader = csv::ReaderBuilder::new()
        .delimiter(delimiter_byte)
        .has_headers(has_header)
        .flexible(true)
        .from_reader(reader);

    let headers = if has_header {
        let header_record = csv_reader
            .headers()
            .context("Échec de la lecture de la ligne d'en-tête CSV")?;
        Some(header_record.iter().map(|s| s.to_string()).collect())
    } else {
        None
    };

    let mut rows = Vec::new();
    for (line_idx, result) in csv_reader.records().enumerate() {
        let record = result.with_context(|| {
            format!("Erreur lors de la lecture de l'enregistrement CSV #{}", line_idx + 1)
        })?;
        rows.push(record.iter().map(|s| s.to_string()).collect());
    }

    Ok(TableData::new(headers, rows))
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    let delimiter_byte = match cli.delimiter.as_bytes() {
        [b] => *b,
        b"\\t" => b'\t',
        _ => {
            anyhow::bail!(
                "Le délimiteur doit être un caractère unique (ex: ',' ou ';') ou '\\t'."
            );
        }
    };

    // Configuration de la source d'entrée (Fichier ou stdin)
    let reader: Box<dyn BufRead> = match cli.input.as_deref() {
        Some(path) => {
            let file = File::open(path)
                .with_context(|| format!("Impossible d'ouvrir le fichier d'entrée: {}", path.display()))?;
            Box::new(BufReader::new(file))
        }
        None => Box::new(BufReader::new(io::stdin())),
    };

    let table_data = parse_csv(reader, delimiter_byte, !cli.no_header)?;

    // Rendu selon le format spécifié
    let rendered = match cli.format {
        OutputFormat::Markdown => render_markdown(&table_data, cli.align),
        OutputFormat::Ascii => render_ascii(&table_data, cli.align),
        OutputFormat::Grid => render_grid(&table_data, cli.align),
    };

    // Écriture du résultat (Fichier ou stdout)
    match cli.output.as_deref() {
        Some(path) => {
            let file = File::create(path)
                .with_context(|| format!("Impossible de créer le fichier de sortie: {}", path.display()))?;
            let mut writer = BufWriter::new(file);
            writer
                .write_all(rendered.as_bytes())
                .with_context(|| format!("Erreur d'écriture dans {}", path.display()))?;
            writer.flush()?;
        }
        None => {
            let mut stdout = io::stdout().lock();
            stdout
                .write_all(rendered.as_bytes())
                .context("Erreur lors de l'écriture sur la sortie standard")?;
            stdout.flush()?;
        }
    }

    Ok(())
}

