/// Représentation en mémoire d'une table avec ses dimensions.
#[derive(Debug, Clone)]
pub struct TableData {
    pub headers: Option<Vec<String>>,
    pub rows: Vec<Vec<String>>,
    pub column_widths: Vec<usize>,
}

impl TableData {
    /// Crée une TableData en calculant automatiquement la largeur optimale de chaque colonne.
    pub fn new(headers: Option<Vec<String>>, rows: Vec<Vec<String>>) -> Self {
        let col_count = headers
            .as_ref()
            .map(|h| h.len())
            .unwrap_or(0)
            .max(rows.iter().map(|r| r.len()).max().unwrap_or(0));

        let mut column_widths = vec![0usize; col_count];

        if let Some(ref h_row) = headers {
            for (idx, cell) in h_row.iter().enumerate() {
                column_widths[idx] = column_widths[idx].max(UnicodeWidthStr::width(cell.as_str()));
            }
        }

        for row in &rows {
            for (idx, cell) in row.iter().enumerate() {
                column_widths[idx] = column_widths[idx].max(UnicodeWidthStr::width(cell.as_str()));
            }
        }

        // Assure une largeur minimale de 1 pour chaque colonne pour éviter les colonnes vides illisibles
        for w in &mut column_widths {
            if *w == 0 {
                *w = 1;
            }
        }

        TableData {
            headers,
            rows,
            column_widths,
        }
    }
}

/// Aligne une chaîne de caractères selon une largeur cible et une règle d'alignement.
fn pad_cell(text: &str, target_width: usize, align: Alignment) -> String {
    let text_width = UnicodeWidthStr::width(text);
    if text_width >= target_width {
        return text.to_string();
    }
    let diff = target_width - text_width;

    match align {
        Alignment::Left => format!("{}{}", text, " ".repeat(diff)),
        Alignment::Right => format!("{}{}", " ".repeat(diff), text),
        Alignment::Center => {
            let left_pad = diff / 2;
            let right_pad = diff - left_pad;
            format!("{}{}{}", " ".repeat(left_pad), text, " ".repeat(right_pad))
        }
    }
}

/// Formate une rangée avec un délimiteur de début, intermédiaire, fin et marge intérieure.
fn format_row(
    cells: &[String],
    col_widths: &[usize],
    align: Alignment,
    left_border: &str,
    col_sep: &str,
    right_border: &str,
) -> String {
    let formatted_cells: Vec<String> = col_widths
        .iter()
        .enumerate()
        .map(|(i, &width)| {
            let content = cells.get(i).map(String::as_str).unwrap_or("");
            format!(" {} ", pad_cell(content, width, align))
        })
        .collect();

    format!(
        "{}{}{}",
        left_border,
        formatted_cells.join(col_sep),
        right_border
    )
}

