/// Convertit une quantité de kilo-octets en chaîne formatée adaptée (KiB, MiB, GiB).
pub fn format_kbytes(kb: u64) -> String {
    const KIB: f64 = 1.0;
    const MIB: f64 = 1024.0 * KIB;
    const GIB: f64 = 1024.0 * MIB;

    let kb_f = kb as f64;
    if kb_f >= GIB {
        format!("{:.2} GiB ({} kB)", kb_f / GIB, kb)
    } else if kb_f >= MIB {
        format!("{:.2} MiB ({} kB)", kb_f / MIB, kb)
    } else {
        format!("{} kB", kb)
    }
}

/// Lecteur et analyseur du pseudo-fichier `/proc/[pid]/status`.
pub struct StatusMonitor {
    path: PathBuf,
}

impl Default for StatusMonitor {
    fn default() -> Self {
        Self::self_process()
    }
}

impl StatusMonitor {
    /// Crée un moniteur ciblant le processus courant (`/proc/self/status`).
    pub fn self_process() -> Self {
        Self {
            path: PathBuf::from("/proc/self/status"),
        }
    }

    /// Crée un moniteur ciblant un PID spécifique (`/proc/<pid>/status`).
    pub fn for_pid(pid: u32) -> Self {
        Self {
            path: PathBuf::from(format!("/proc/{}/status", pid)),
        }
    }

    /// Crée un moniteur ciblant un chemin de fichier arbitraire (utile pour les tests unitaires).
    pub fn from_path<P: AsRef<Path>>(path: P) -> Self {
        Self {
            path: path.as_ref().to_path_buf(),
        }
    }

    /// Lit et extrait les métriques actuelles du fichier `/proc/.../status`.
    pub fn snapshot(&self) -> Result<MemoryMetrics, MonitorError> {
        if !self.path.exists() && cfg!(not(target_os = "linux")) {
            return Err(MonitorError::UnsupportedPlatform);
        }

        let file = File::open(&self.path).map_err(|source| MonitorError::Io {
            path: self.path.clone(),
            source,
        })?;

        let reader = BufReader::new(file);
        let mut metrics = MemoryMetrics::default();

        for line_res in reader.lines() {
            let line = line_res.map_err(|source| MonitorError::Io {
                path: self.path.clone(),
                source,
            })?;

            // Les lignes de /proc/self/status sont sous la forme "Clé:\tValeur kB"
            if let Some((key, rest)) = line.split_once(':') {
                let trimmed_val = rest.trim();
                let parse_val = || -> Result<u64, MonitorError> {
                    let num_str = trimmed_val
                        .split_whitespace()
                        .next()
                        .unwrap_or("0");
                    num_str.parse::<u64>().map_err(|source| MonitorError::ParseInt {
                        line: line.clone(),
                        source,
                    })
                };

                match key.trim() {
                    "VmPeak" => metrics.vm_peak_kb = parse_val()?,
                    "VmSize" => metrics.vm_size_kb = parse_val()?,
                    "VmLck" => metrics.vm_lock_kb = parse_val()?,
                    "VmHWM" => metrics.vm_hwm_kb = parse_val()?,
                    "VmRSS" => metrics.vm_rss_kb = parse_val()?,
                    "RssAnon" => metrics.rss_anon_kb = parse_val()?,
                    "RssFile" => metrics.rss_file_kb = parse_val()?,
                    "RssShmem" => metrics.rss_shmem_kb = parse_val()?,
                    "VmData" => metrics.vm_data_kb = parse_val()?,
                    "VmStk" => metrics.vm_stack_kb = parse_val()?,
                    "VmExe" => metrics.vm_exe_kb = parse_val()?,
                    "VmLib" => metrics.vm_lib_kb = parse_val()?,
                    "VmPTE" => metrics.vm_pte_kb = parse_val()?,
                    "VmSwap" => metrics.vm_swap_kb = parse_val()?,
                    _ => {}
                }
            }
        }

        Ok(metrics)
    }
}

/// Fonction simulant une allocation dynamique avec écriture réelle pour valider
/// l'allocation physique de mémoire vive (page fault) par le noyau.
fn allocate_and_touch_memory(megabytes: usize) -> Vec<u8> {
    let bytes_to_alloc = megabytes * 1024 * 1024;
    let mut buffer = Vec::with_capacity(bytes_to_alloc);

    // Initialisation active pour forcer l'allocation des frames mémoires physiques
    // (évite la paresse du mécanisme copy-on-write / zero-page du noyau Linux).
    for i in 0..bytes_to_alloc {
        buffer.push((i % 256) as u8);
    }

    buffer
}

fn main() -> Result<(), MonitorError> {
    println!("=== Démarrage du moniteur de mémoire /proc/self/status ===\n");

    let monitor = StatusMonitor::self_process();

    // 1. Empreinte mémoire initiale
    let initial = monitor.snapshot()?;
    println!("[Étape 1] Instantané initial (au repos) :");
    println!("{}\n", initial);

    // 2. Simulation d'une première allocation de 50 Mo
    println!("[Étape 2] Allocation de 50 MiB de mémoire active...");
    let mut block1 = allocate_and_touch_memory(50);
    // Empêcher l'optimiseur de supprimer la mémoire allouée
    std::hint::black_box(&mut block1);

    let after_alloc_50 = monitor.snapshot()?;
    let diff = after_alloc_50.diff_rss_kb(&initial);
    println!("Consommation après allocation de 50 MiB :");
    println!("{}\n", after_alloc_50);
    println!("=> Variation VmRSS constatée : +{} kB (~{:.2} MiB)\n", diff, diff as f64 / 1024.0);

    // Pause courte
    thread::sleep(Duration::from_millis(500));

    // 3. Simulation d'une allocation supplémentaire de 100 Mo
    println!("[Étape 3] Allocation supplémentaire de 100 MiB (Total cumulé ~150 MiB)...");
    let mut block2 = allocate_and_touch_memory(100);
    std::hint::black_box(&mut block2);

    let after_alloc_150 = monitor.snapshot()?;
    println!("Consommation après allocation cumulée :");
    println!("{}\n", after_alloc_150);
    println!(
        "=> VmHWM (Pic historique) : {} | VmRSS : {}\n",
        format_kbytes(after_alloc_150.vm_hwm_kb),
        format_kbytes(after_alloc_150.vm_rss_kb)
    );

    // 4. Libération de mémoire
    println!("[Étape 4] Libération du bloc de 100 MiB...");
    drop(block2);

    let after_drop = monitor.snapshot()?;
    println!("Consommation après drop(block2) :");
    println!("{}\n", after_drop);
    println!(
        "=> Notez que VmHWM ({}) reste au niveau du pic atteint, tandis que VmRSS s'adapte.\n",
        format_kbytes(after_drop.vm_hwm_kb)
    );

    // Libération finale
    drop(block1);
    let final_metrics = monitor.snapshot()?;
    println!("[Étape 5] Après libération totale :");
    println!("{}\n", final_metrics);

    println!("=== Fin de la démonstration du moniteur de mémoire ===");
    Ok(())
}

