/// Erreurs possibles lors de la lecture ou de l'analyse des métriques mémoire.
#[derive(Debug, Error)]
pub enum MonitorError {
    #[error("Erreur d'entrée/sortie lors de l'accès à '{path}': {source}")]
    Io {
        path: PathBuf,
        #[source]
        source: io::Error,
    },

    #[error("Erreur de parsing de la valeur numérique à la ligne '{line}': {source}")]
    ParseInt {
        line: String,
        #[source]
        source: std::num::ParseIntError,
    },

    #[error("Système d'exploitation non supporté ou pseudo-système /proc introuvable")]
    UnsupportedPlatform,
}

/// Instantané des métriques de consommation mémoire extraites de /proc/[pid]/status.
/// Toutes les valeurs sont exprimées en kilo-octets (kB / KiB).
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct MemoryMetrics {
    /// Pic de taille de l'espace d'adressage virtuel (VmPeak)
    pub vm_peak_kb: u64,
    /// Taille actuelle de l'espace d'adressage virtuel (VmSize)
    pub vm_size_kb: u64,
    /// Mémoire verrouillée en RAM avec mlock (VmLck)
    pub vm_lock_kb: u64,
    /// Pic de mémoire physique résidente atteinte - High Water Mark (VmHWM)
    pub vm_hwm_kb: u64,
    /// Mémoire physique résidente actuelle (VmRSS)
    pub vm_rss_kb: u64,
    /// Mémoire résidente anonyme : heap/tas, allocations dynamiques (RssAnon)
    pub rss_anon_kb: u64,
    /// Mémoire résidente adossée à des fichiers : binaires, libc, mappings mmap (RssFile)
    pub rss_file_kb: u64,
    /// Mémoire résidente partagée (RssShmem)
    pub rss_shmem_kb: u64,
    /// Segment de données / heap (VmData)
    pub vm_data_kb: u64,
    /// Taille de la pile du thread principal (VmStk)
    pub vm_stack_kb: u64,
    /// Taille du segment de code texte exécutable (VmExe)
    pub vm_exe_kb: u64,
    /// Code des bibliothèques partagées (VmLib)
    pub vm_lib_kb: u64,
    /// Taille des entrées de table de pages (VmPTE)
    pub vm_pte_kb: u64,
    /// Mémoire résidente évincée vers le swap (VmSwap)
    pub vm_swap_kb: u64,
}

