#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HierarchyAccessResult {
    /// Succès immédiat dans le cache L1.
    HitL1,
    /// Échec en L1, succès dans le cache L2 (chargement en L1).
    HitL2,
    /// Échec en L1 et L2, accès à la mémoire principale (RAM).
    MissL2MainMemory,
}

/// Configuration géométrique et temporelle d'un niveau de cache.
#[derive(Debug, Clone)]
pub struct CacheConfig {
    pub name: String,
    pub line_size_bytes: usize,
    pub num_sets: usize,
    pub associativity: usize,
    pub latency_cycles: u64,
    pub policy: ReplacementPolicy,
}

impl CacheConfig {
    pub fn new(
        name: impl Into<String>,
        line_size_bytes: usize,
        num_sets: usize,
        associativity: usize,
        latency_cycles: u64,
        policy: ReplacementPolicy,
    ) -> Result<Self, String> {
        if !line_size_bytes.is_power_of_two() || line_size_bytes == 0 {
            return Err("line_size_bytes doit être une puissance de deux positive".to_string());
        }
        if !num_sets.is_power_of_two() || num_sets == 0 {
            return Err("num_sets doit être une puissance de deux positive".to_string());
        }
        if associativity == 0 {
            return Err("associativity doit être supérieure à 0".to_string());
        }

        Ok(Self {
            name: name.into(),
            line_size_bytes,
            num_sets,
            associativity,
            latency_cycles,
            policy,
        })
    }

    #[inline]
    pub fn offset_bits(&self) -> usize {
        self.line_size_bytes.trailing_zeros() as usize
    }

    #[inline]
    pub fn index_bits(&self) -> usize {
        self.num_sets.trailing_zeros() as usize
    }

    /// Décompose une adresse physique en (tag, set_index, offset).
    #[inline]
    pub fn decode_address(&self, address: u64) -> (u64, usize, usize) {
        let b = self.offset_bits();
        let s = self.index_bits();

        let offset_mask = (1u64 << b) - 1;
        let set_mask = (1u64 << s) - 1;

        let offset = (address & offset_mask) as usize;
        let set_index = ((address >> b) & set_mask) as usize;
        let tag = address >> (b + s);

        (tag, set_index, offset)
    }

    /// Reconstruit l'adresse de base du bloc à partir du tag et de l'index du set.
    #[inline]
    pub fn block_address(&self, tag: u64, set_index: usize) -> u64 {
        let b = self.offset_bits();
        let s = self.index_bits();
        (tag << (b + s)) | ((set_index as u64) << b)
    }
}

/// Une ligne individuelle dans un ensemble de cache.
#[derive(Debug, Clone)]
pub struct CacheLine {
    pub tag: u64,
    pub valid: bool,
    pub dirty: bool,
    pub last_access_timestamp: u64,
    pub insertion_timestamp: u64,
}

impl CacheLine {
    pub fn empty() -> Self {
        Self {
            tag: 0,
            valid: false,
            dirty: false,
            last_access_timestamp: 0,
            insertion_timestamp: 0,
        }
    }
}

/// Un ensemble associatif regroupant plusieurs lignes (N-way set associative).
#[derive(Debug, Clone)]
pub struct CacheSet {
    pub lines: Vec<CacheLine>,
}

impl CacheSet {
    pub fn new(associativity: usize) -> Self {
        Self {
            lines: vec![CacheLine::empty(); associativity],
        }
    }

    /// Cherche un hit correspondant au tag spécifié.
    pub fn find_hit(&mut self, tag: u64, current_timestamp: u64) -> Option<usize> {
        for (idx, line) in self.lines.iter_mut().enumerate() {
            if line.valid && line.tag == tag {
                line.last_access_timestamp = current_timestamp;
                return Some(idx);
            }
        }
        None
    }

    /// Sélectionne la voie à remplacer en cas de miss selon la politique configurée.
    pub fn select_victim(&self, policy: ReplacementPolicy) -> usize {
        // Priorité 1 : une ligne libre (invalide)
        for (idx, line) in self.lines.iter().enumerate() {
            if !line.valid {
                return idx;
            }
        }

        // Priorité 2 : selon la politique LRU ou FIFO
        match policy {
            ReplacementPolicy::Lru => {
                let mut victim_idx = 0;
                let mut oldest_timestamp = u64::MAX;
                for (idx, line) in self.lines.iter().enumerate() {
                    if line.last_access_timestamp < oldest_timestamp {
                        oldest_timestamp = line.last_access_timestamp;
                        victim_idx = idx;
                    }
                }
                victim_idx
            }
            ReplacementPolicy::Fifo => {
                let mut victim_idx = 0;
                let mut oldest_timestamp = u64::MAX;
                for (idx, line) in self.lines.iter().enumerate() {
                    if line.insertion_timestamp < oldest_timestamp {
                        oldest_timestamp = line.insertion_timestamp;
                        victim_idx = idx;
                    }
                }
                victim_idx
            }
        }
    }
}

/// Statistiques de performance d'un niveau de cache.
#[derive(Debug, Default, Clone)]
pub struct CacheStats {
    pub reads: u64,
    pub writes: u64,
    pub read_hits: u64,
    pub write_hits: u64,
    pub read_misses: u64,
    pub write_misses: u64,
    pub evictions: u64,
    pub write_backs: u64,
}

impl CacheStats {
    pub fn total_accesses(&self) -> u64 {
        self.reads + self.writes
    }

    pub fn total_hits(&self) -> u64 {
        self.read_hits + self.write_hits
    }

    pub fn total_misses(&self) -> u64 {
        self.read_misses + self.write_misses
    }

    pub fn hit_rate(&self) -> f64 {
        let total = self.total_accesses();
        if total == 0 {
            0.0
        } else {
            (self.total_hits() as f64 / total as f64) * 100.0
        }
    }

    pub fn miss_rate(&self) -> f64 {
        100.0 - self.hit_rate()
    }
}

/// Modélisation d'un niveau de cache matériel complet.
#[derive(Debug)]
pub struct CacheLevel {
    pub config: CacheConfig,
    pub sets: Vec<CacheSet>,
    pub stats: CacheStats,
}

/// Résultat d'éviction lors d'une insertion.
pub struct EvictionInfo {
    pub evicted_tag: u64,
    pub was_dirty: bool,
    pub block_address: u64,
}

impl CacheLevel {
    pub fn new(config: CacheConfig) -> Self {
        let sets = (0..config.num_sets)
            .map(|_| CacheSet::new(config.associativity))
            .collect();
        Self {
            config,
            sets,
            stats: CacheStats::default(),
        }
    }

    /// Vérifie si l'adresse est un hit et met à jour les métadonnées LRU.
    pub fn probe_hit(&mut self, address: u64, access_type: AccessType, timestamp: u64) -> bool {
        let (tag, set_idx, _) = self.config.decode_address(address);
        match access_type {
            AccessType::Read => self.stats.reads += 1,
            AccessType::Write => self.stats.writes += 1,
        }

        if let Some(way) = self.sets[set_idx].find_hit(tag, timestamp) {
            match access_type {
                AccessType::Read => self.stats.read_hits += 1,
                AccessType::Write => {
                    self.stats.write_hits += 1;
                    // En politique Write-Back, la ligne devient dirty
                    self.sets[set_idx].lines[way].dirty = true;
                }
            }
            true
        } else {
            match access_type {
                AccessType::Read => self.stats.read_misses += 1,
                AccessType::Write => self.stats.write_misses += 1,
            }
            false
        }
    }

    /// Insère un bloc dans le cache, retournant les informations d'éviction si applicable.
    pub fn insert_block(
        &mut self,
        address: u64,
        dirty: bool,
        timestamp: u64,
    ) -> Option<EvictionInfo> {
        let (tag, set_idx, _) = self.config.decode_address(address);
        let victim_way = self.sets[set_idx].select_victim(self.config.policy);
        let old_line = &self.sets[set_idx].lines[victim_way];

        let eviction = if old_line.valid {
            self.stats.evictions += 1;
            if old_line.dirty {
                self.stats.write_backs += 1;
            }
            Some(EvictionInfo {
                evicted_tag: old_line.tag,
                was_dirty: old_line.dirty,
                block_address: self.config.block_address(old_line.tag, set_idx),
            })
        } else {
            None
        };

        // Remplacement de la ligne
        self.sets[set_idx].lines[victim_way] = CacheLine {
            tag,
            valid: true,
            dirty,
            last_access_timestamp: timestamp,
            insertion_timestamp: timestamp,
        };

        eviction
    }
}

/// Simulateur de hiérarchie mémoire complète : L1 -> L2 -> RAM.
pub struct MemoryHierarchy {
    pub l1: CacheLevel,
    pub l2: CacheLevel,
    pub ram_latency_cycles: u64,
    pub current_timestamp: u64,
    pub total_cycles_spent: u64,
    pub total_requests: u64,
}

impl MemoryHierarchy {
    pub fn new(l1_config: CacheConfig, l2_config: CacheConfig, ram_latency_cycles: u64) -> Self {
        Self {
            l1: CacheLevel::new(l1_config),
            l2: CacheLevel::new(l2_config),
            ram_latency_cycles,
            current_timestamp: 0,
            total_cycles_spent: 0,
            total_requests: 0,
        }
    }

    /// Traite un accès mémoire (Lecture ou Écriture) avec gestion Write-Allocate / Write-Back.
    pub fn access(&mut self, address: u64, access_type: AccessType) -> HierarchyAccessResult {
        self.current_timestamp += 1;
        self.total_requests += 1;

        // 1. Consultation de L1
        let l1_latency = self.l1.config.latency_cycles;
        self.total_cycles_spent += l1_latency;

        if self.l1.probe_hit(address, access_type, self.current_timestamp) {
            return HierarchyAccessResult::HitL1;
        }

        // 2. L1 Miss -> Consultation de L2
        let l2_latency = self.l2.config.latency_cycles;
        self.total_cycles_spent += l2_latency;

        let is_l2_hit = self.l2.probe_hit(address, AccessType::Read, self.current_timestamp);

        let final_result = if is_l2_hit {
            HierarchyAccessResult::HitL2
        } else {
            // 3. L2 Miss -> Accès RAM
            self.total_cycles_spent += self.ram_latency_cycles;
            HierarchyAccessResult::MissL2MainMemory
        };

        // Remplissage hiérarchique :
        // Si L2 a miss, le bloc est alloué en L2 depuis la RAM.
        if !is_l2_hit {
            if let Some(eviction) = self.l2.insert_block(address, false, self.current_timestamp) {
                if eviction.was_dirty {
                    // Écriture différée du bloc L2 évincé vers la RAM
                    self.total_cycles_spent += self.ram_latency_cycles;
                }
            }
        }

        // Ensuite, le bloc est transféré / alloué dans le cache L1.
        let l1_dirty = access_type == AccessType::Write;
        if let Some(eviction) = self.l1.insert_block(address, l1_dirty, self.current_timestamp) {
            if eviction.was_dirty {
                // Le bloc évincé de L1 était sale : mise à jour en L2 (write-back)
                let l2_evict = self.l2.insert_block(eviction.block_address, true, self.current_timestamp);
                if let Some(evicted_from_l2) = l2_evict {
                    if evicted_from_l2.was_dirty {
                        self.total_cycles_spent += self.ram_latency_cycles;
                    }
                }
            }
        }

        final_result
    }

    /// Temps moyen d'accès mémoire (AMAT) en cycles.
    pub fn amat(&self) -> f64 {
        if self.total_requests == 0 {
            0.0
        } else {
            self.total_cycles_spent as f64 / self.total_requests as f64
        }
    }

    /// Affiche un bilan détaillé et soigné de la simulation.
    pub fn print_summary(&self) {
        println!("{:=^75}", " BILAN DE SIMULATION DU CACHE MULTI-NIVEAUX ");
        println!("Nombre total de requêtes : {}", self.total_requests);
        println!("Cycles totaux écoulés    : {}", self.total_cycles_spent);
        println!("AMAT (Temps moyen/accès) : {:.2} cycles", self.amat());
        println!("{:-^75}", " NIVEAU L1 ");
        self.print_cache_level_stats(&self.l1);
        println!("{:-^75}", " NIVEAU L2 ");
        self.print_cache_level_stats(&self.l2);
        println!("{:=^75}\n", "");
    }

    fn print_cache_level_stats(&self, level: &CacheLevel) {
        let s = &level.stats;
        let c = &level.config;
        println!(
            "Configuration : {} lignes/set ({} voies), {} ensembles, ligne de {} octets",
            c.associativity, c.associativity, c.num_sets, c.line_size_bytes
        );
        println!("Capacité      : {} Ko", (c.num_sets * c.associativity * c.line_size_bytes) / 1024);
        println!("Latence       : {} cycle(s)", c.latency_cycles);
        println!("Politique     : {:?}", c.policy);
        println!("---");
        println!("Accès totaux  : {} (Reads: {}, Writes: {})", s.total_accesses(), s.reads, s.writes);
        println!("Hits          : {} (Taux de Hit  : {:6.2}%)", s.total_hits(), s.hit_rate());
        println!("Misses        : {} (Taux de Miss : {:6.2}%)", s.total_misses(), s.miss_rate());
        println!("Évictions     : {} | Écritures différées (Write-backs) : {}", s.evictions, s.write_backs);
    }
}

impl fmt::Display for HierarchyAccessResult {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::HitL1 => write!(f, "\x1b[32m[HIT  L1]\x1b[0m"),
            Self::HitL2 => write!(f, "\x1b[33m[HIT  L2]\x1b[0m (Miss L1)"),
            Self::MissL2MainMemory => write!(f, "\x1b[31m[MISS L2]\x1b[0m -> Accès RAM"),
        }
    }
}

fn main() -> Result<(), String> {
    println!("Démarrage du simulateur de cache matériel multi-niveaux...\n");

    // Configuration réaliste :
    // L1 : 32 Ko, 64B de ligne, 8-way (64 sets), 1 cycle de latence, LRU
    let l1_cfg = CacheConfig::new("L1_Data", 64, 64, 8, 1, ReplacementPolicy::Lru)?;

    // L2 : 256 Ko, 64B de ligne, 8-way (512 sets), 12 cycles de latence, LRU
    let l2_cfg = CacheConfig::new("L2_Unified", 64, 512, 8, 12, ReplacementPolicy::Lru)?;

    // RAM : 150 cycles de pénalité de miss
    let mut hierarchy = MemoryHierarchy::new(l1_cfg, l2_cfg, 150);

    println!("--- Scénario 1 : Démonstration de Localité Temporelle ---");
    let test_addr = 0x1000;
    for i in 0..4 {
        let res = hierarchy.access(test_addr, AccessType::Read);
        println!("Accès #{}: Read 0x{:08X} => {}", i + 1, test_addr, res);
    }

    println!("\n--- Scénario 2 : Démonstration de Localité Spatiale (Balayage séquentiel) ---");
    // Lecture de mots adjacents au sein d'une même ligne de 64 octets puis débordement
    let base_addr = 0x2000;
    for offset in [0, 4, 8, 16, 32, 60, 64, 68, 128] {
        let addr = base_addr + offset;
        let res = hierarchy.access(addr, AccessType::Read);
        println!("Read 0x{:08X} (offset +{:2}) => {}", addr, offset, res);
    }

    println!("\n--- Scénario 3 : Écritures & Gestion du Dirty bit / Write-Back ---");
    let write_addr = 0x3000;
    let res = hierarchy.access(write_addr, AccessType::Write);
    println!("Write 0x{:08X} => {}", write_addr, res);
    let res = hierarchy.access(write_addr, AccessType::Read);
    println!("Read  0x{:08X} => {}", write_addr, res);

    println!("\n--- Scénario 4 : Boucle de calcul matriciel / Conflits d'adresses multiples ---");
    // Balayage avec stride pour créer des hits et des misses
    for i in 0..1000 {
        let addr = (i * 32) % 0x10000;
        let op = if i % 5 == 0 { AccessType::Write } else { AccessType::Read };
        hierarchy.access(addr, op);
    }
    println!("Exécution de 1000 accès aléatoires/stridés terminée.");

    println!("\n");
    hierarchy.print_summary();

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_address_decoding() {
        // Ligne de 64 octets (6 bits offset), 64 ensembles (6 bits index), reste en tag
        let cfg = CacheConfig::new("Test", 64, 64, 4, 1, ReplacementPolicy::Lru).unwrap();
        assert_eq!(cfg.offset_bits(), 6);
        assert_eq!(cfg.index_bits(), 6);

        let address = 0b1011_000010_010100;
        let (tag, set_idx, offset) = cfg.decode_address(address);
        assert_eq!(offset, 0b010100);
        assert_eq!(set_idx, 0b000010);
        assert_eq!(tag, 0b1011);
    }

    #[test]
    fn test_temporal_locality_hit() {
        let l1 = CacheConfig::new("L1", 64, 8, 2, 1, ReplacementPolicy::Lru).unwrap();
        let l2 = CacheConfig::new("L2", 64, 16, 4, 5, ReplacementPolicy::Lru).unwrap();
        let mut sim = MemoryHierarchy::new(l1, l2, 50);

        let res1 = sim.access(0x1000, AccessType::Read);
        assert_eq!(res1, HierarchyAccessResult::MissL2MainMemory);

        let res2 = sim.access(0x1000, AccessType::Read);
        assert_eq!(res2, HierarchyAccessResult::HitL1);
    }

    #[test]
    fn test_spatial_locality_same_cache_line() {
        let l1 = CacheConfig::new("L1", 64, 8, 2, 1, ReplacementPolicy::Lru).unwrap();
        let l2 = CacheConfig::new("L2", 64, 16, 4, 5, ReplacementPolicy::Lru).unwrap();
        let mut sim = MemoryHierarchy::new(l1, l2, 50);

        // Premier accès dans la ligne de 64 octets
        let res1 = sim.access(0x2000, AccessType::Read);
        assert_eq!(res1, HierarchyAccessResult::MissL2MainMemory);

        // Deuxième accès 16 octets plus loin dans la même ligne
        let res2 = sim.access(0x2010, AccessType::Read);
        assert_eq!(res2, HierarchyAccessResult::HitL1);
    }

    #[test]
    fn test_lru_eviction() {
        // Cache avec 1 seul set et associativité de 2
        let cfg = CacheConfig::new("L1", 64, 1, 2, 1, ReplacementPolicy::Lru).unwrap();
        let mut cache = CacheLevel::new(cfg);

        // Remplir les 2 voies
        cache.insert_block(0x00, false, 1);
        cache.insert_block(0x40, false, 2);

        // Accéder à 0x00 pour rafraîchir son LRU
        let hit = cache.probe_hit(0x00, AccessType::Read, 3);
        assert!(hit);

        // Insérer une 3ème adresse -> la victime doit être 0x40 (timestamp 2 < timestamp 3)
        let evict = cache.insert_block(0x80, false, 4).unwrap();
        assert_eq!(evict.block_address, 0x40);
    }
}

