```rust
// src/main.rs
use std::collections::HashMap;
use std::io::{BufRead, BufReader, ErrorKind, Write};
use std::net::{SocketAddr, TcpListener, TcpStream};
use std::sync::mpsc::{channel, Receiver, Sender, TryRecvError};
use std::thread;
use std::time::Duration;

/// Événements transitant vers le répartiteur central (Broadcaster).
#[derive(Debug)]
enum Event {
    /// Nouveau client connecté
    NewClient {
        addr: SocketAddr,
        tx_outbound: Sender<String>,
    },
    /// Message reçu depuis un client
    Message {
        from: SocketAddr,
        content: String,
    },
    /// Déconnexion d'un client
    ClientDisconnected {
        addr: SocketAddr,
    },
}

/// Gère l'écoute du socket d'un client dans un thread dédié.
/// Lit les lignes envoyées et les transmet au bus central via `mpsc::Sender<Event>`.
fn handle_client_incoming(stream: TcpStream, addr: SocketAddr, event_tx: Sender<Event>) {
    let reader = BufReader::new(stream);
    for line_result in reader.lines() {
        match line_result {
            Ok(line) => {
                let trimmed = line.trim().to_string();
                if trimmed.is_empty() {
                    continue;
                }
                if event_tx.send(Event::Message { from: addr, content: trimmed }).is_err() {
                    eprintln!("[Thread-{}] Canal d'événements fermé, arrêt du lecteur.", addr);
                    break;
                }
            }
            Err(e) => {
                eprintln!("[Thread-{}] Fin de lecture ou déconnexion: {}", addr, e);
                break;
            }
        }
    }

    let _ = event_tx.send(Event::ClientDisconnected { addr });
    eprintln!("[Thread-{}] Lecteur terminé.", addr);
}

/// Gère l'écriture vers le socket d'un client dans un thread dédié.
/// Reçoit les messages via un canal non bloquant (`mpsc::Receiver::try_recv`)
/// et les écrit sur le stream TCP.
fn handle_client_outgoing(
    mut stream: TcpStream,
    addr: SocketAddr,
    rx_outbound: Receiver<String>,
) {
    loop {
        match rx_outbound.try_recv() {
            Ok(msg) => {
                if let Err(e) = writeln!(stream, "{}", msg) {
                    eprintln!("[Thread-{}] Échec d'écriture client: {}", addr, e);
                    break;
                }
                if let Err(e) = stream.flush() {
                    eprintln!("[Thread-{}] Échec de flush: {}", addr, e);
                    break;
                }
            }
            Err(TryRecvError::Empty) => {
                // Canal vide : temporisation brève pour éviter la famine CPU
                thread::sleep(Duration::from_millis(5));
            }
            Err(TryRecvError::Disconnected) => {
                // Le dispatcher a coupé la communication avec ce client
                eprintln!("[Thread-{}] Émetteur déconnecté, arrêt de l'écriture.", addr);
                break;
            }
        }
    }
}

/// Thread central de diffusion (Broadcaster / Dispatcher).
/// Traite les événements de manière non bloquante via `try_recv()`.
fn run_broadcaster(rx_events: Receiver<Event>) {
    let mut clients: HashMap<SocketAddr, Sender<String>> = HashMap::new();

    loop {
        match rx_events.try_recv() {
            Ok(event) => match event {
                Event::NewClient { addr, tx_outbound } => {
                    println!("[Broadcaster] Connexion acceptée: {}", addr);
                    let welcome = format!("*** Bienvenue sur le serveur de chat ! Vous êtes {}. ***", addr);
                    let _ = tx_outbound.send(welcome);

                    let announce = format!("*** [{}] a rejoint le salon. ***", addr);
                    for (&_client_addr, client_tx) in &clients {
                        let _ = client_tx.send(announce.clone());
                    }

                    clients.insert(addr, tx_outbound);
                }
                Event::Message { from, content } => {
                    println!("[Chat] [{}] {}", from, content);
                    let broadcast_msg = format!("[{}]: {}", from, content);

                    // Diffusion à tous les clients sauf l'émetteur
                    let mut disconnected = Vec::new();
                    for (&addr, tx) in &clients {
                        if addr != from {
                            if tx.send(broadcast_msg.clone()).is_err() {
                                disconnected.push(addr);
                            }
                        }
                    }

                    for addr in disconnected {
                        clients.remove(&addr);
                    }
                }
                Event::ClientDisconnected { addr } => {
                    if clients.remove(&addr).is_some() {
                        println!("[Broadcaster] Déconnexion confirmée: {}", addr);
                        let announce = format!("*** [{}] a quitté le salon. ***", addr);
                        let mut disconnected = Vec::new();
                        for (&client_addr, client_tx) in &clients {
                            if client_tx.send(announce.clone()).is_err() {
                                disconnected.push(client_addr);
                            }
                        }
                        for d_addr in disconnected {
                            clients.remove(&d_addr);
                        }
                    }
                }
            },
            Err(TryRecvError::Empty) => {
                // Évite une boucle active saturant le CPU
                thread::sleep(Duration::from_millis(5));
            }
            Err(TryRecvError::Disconnected) => {
                println!("[Broadcaster] Canal de distribution fermé. Arrêt du dispatcher.");
                break;
            }
        }
