        self.0.to_radians()
    }
}

/// Point GPS constitué d'une latitude et d'une longitude strictement validées.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct GpsPoint {
    latitude: Latitude,
    longitude: Longitude,
}

impl GpsPoint {
    pub fn new(latitude: Latitude, longitude: Longitude) -> Self {
        Self {
            latitude,
            longitude,
        }
    }

    pub fn from_f64(lat: f64, lon: f64) -> Result<Self, GeoError> {
        let latitude = Latitude::new(lat)?;
        let longitude = Longitude::new(lon)?;
        Ok(Self::new(latitude, longitude))
    }

    #[inline]
    pub fn latitude(self) -> Latitude {
        self.latitude
    }

    #[inline]
    pub fn longitude(self) -> Longitude {
        self.longitude
    }

    /// Calcule la distance géodésique du grand cercle vers un autre point avec la formule de Haversine.
    /// Retourne la distance en mètres.
    pub fn haversine_distance_meters(self, other: Self) -> f64 {
        let phi1 = self.latitude.to_radians();
        let phi2 = other.latitude.to_radians();
        let delta_phi = (other.latitude.get() - self.latitude.get()).to_radians();
        let delta_lambda = (other.longitude.get() - self.longitude.get()).to_radians();

        let sin_half_dphi = (delta_phi / 2.0).sin();
        let sin_half_dlambda = (delta_lambda / 2.0).sin();

        let a = sin_half_dphi * sin_half_dphi
            + phi1.cos() * phi2.cos() * sin_half_dlambda * sin_half_dlambda;

        // Limiter numériquement 'a' pour éviter tout débordement lié aux erreurs d'arrondi f64
        let a_clamped = a.clamp(0.0, 1.0);
        let c = 2.0 * a_clamped.sqrt().atan2((1.0 - a_clamped).sqrt());

        EARTH_MEAN_RADIUS_METERS * c
    }
}

/// Unités de distance supportées pour l'affichage.
#[derive(Debug, Clone, Copy, Default, ValueEnum)]
pub enum Unit {
    #[default]
    Km,
    M,
    Mi,
    Nm,
}

impl Unit {
    pub fn convert_from_meters(self, meters: f64) -> f64 {
        match self {
            Self::M => meters,
            Self::Km => meters / 1_000.0,
            Self::Mi => meters / 1_609.344,
            Self::Nm => meters / 1_852.0,
        }
    }

    pub fn symbol(self) -> &'static str {
        match self {
            Self::M => "m",
            Self::Km => "km",
            Self::Mi => "mi",
            Self::Nm => "NM",
        }
    }
}

impl fmt::Display for Unit {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.symbol())
    }
}

/// CLI de calcul de distance géodésique (formule de Haversine).
#[derive(Parser, Debug)]
#[command(author, version, about, long_about = None)]
struct Cli {
    /// Latitude du premier point (-90.0 à 90.0)
    #[arg(long = "lat1", allow_hyphen_values = true)]
    lat1: f64,

    /// Longitude du premier point (-180.0 à 180.0)
    #[arg(long = "lon1", allow_hyphen_values = true)]
    lon1: f64,

    /// Latitude du second point (-90.0 à 90.0)
    #[arg(long = "lat2", allow_hyphen_values = true)]
    lat2: f64,

    /// Longitude du second point (-180.0 à 180.0)
    #[arg(long = "lon2", allow_hyphen_values = true)]
    lon2: f64,

    /// Unité de mesure pour le résultat
    #[arg(short, long, value_enum, default_value_t = Unit::Km)]
    unit: Unit,

    /// Afficher le résultat au format JSON
    #[arg(long)]
    json: bool,
}

fn run(cli: Cli) -> Result<(), GeoError> {
    let p1 = GpsPoint::from_f64(cli.lat1, cli.lon1)?;
    let p2 = GpsPoint::from_f64(cli.lat2, cli.lon2)?;

    let distance_meters = p1.haversine_distance_meters(p2);
    let converted_distance = cli.unit.convert_from_meters(distance_meters);

    if cli.json {
        println!(
            "{{\"point1\":{{\"latitude\":{:.6},\"longitude\":{:.6}}},\"point2\":{{\"latitude\":{:.6},\"longitude\":{:.6}}},\"distance\":{:.4},\"unit\":\"{}\"}}",
            p1.latitude().get(),
            p1.longitude().get(),
            p2.latitude().get(),
            p2.longitude().get(),
            converted_distance,
            cli.unit.symbol()
        );
    } else {
        println!(
            "Point 1 : ({:.6}°, {:.6}°)",
            p1.latitude().get(),
            p1.longitude().get()
        );
        println!(
            "Point 2 : ({:.6}°, {:.6}°)",
            p2.latitude().get(),
            p2.longitude().get()
        );
        println!("Distance: {:.4} {}", converted_distance, cli.unit);
    }

    Ok(())
}

fn main() -> ExitCode {
    let cli = Cli::parse();
    match run(cli) {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("Erreur de calcul de coordonnées : {err}");
            ExitCode::FAILURE
        }
    }
}

