mod tests {
    use super::*;

    const EPSILON: f64 = 1.0; // tolérance de 1 mètre pour les tests comparatifs

    #[test]
    fn test_valid_coordinates() {
        let lat = Latitude::new(48.8566);
        let lon = Longitude::new(2.3522);
        assert!(lat.is_ok());
        assert!(lon.is_ok());
    }

    #[test]
    fn test_invalid_coordinates() {
        assert_eq!(Latitude::new(95.0), Err(GeoError::InvalidLatitude(95.0)));
        assert_eq!(Latitude::new(-91.0), Err(GeoError::InvalidLatitude(-91.0)));
        assert_eq!(
            Longitude::new(181.0),
            Err(GeoError::InvalidLongitude(181.0))
        );
        assert_eq!(
            Longitude::new(-180.5),
            Err(GeoError::InvalidLongitude(-180.5))
        );
        assert_eq!(Latitude::new(f64::NAN), Err(GeoError::NonFiniteCoordinate));
        assert_eq!(
            Longitude::new(f64::INFINITY),
            Err(GeoError::NonFiniteCoordinate)
        );
    }

    #[test]
    fn test_identical_points() {
        let p = GpsPoint::from_f64(45.0, 5.0).expect("Coordonnées valides");
        let dist = p.haversine_distance_meters(p);
        assert!(dist.abs() < 1e-9);
    }

    #[test]
    fn test_paris_to_london() {
        // Paris : 48.8566° N, 2.3522° E
        // Londres : 51.5074° N, 0.1278° W (-0.1278°)
        // Distance orthodromique attendue ~ 343.5 km (343_500 m environ)
        let paris = GpsPoint::from_f64(48.8566, 2.3522).expect("Paris valide");
        let london = GpsPoint::from_f64(51.5074, -0.1278).expect("Londres valide");

        let distance_meters = paris.haversine_distance_meters(london);
        let distance_km = Unit::Km.convert_from_meters(distance_meters);

        assert!((distance_km - 343.55).abs() < EPSILON);
    }

    #[test]
    fn test_antipodal_points() {
        // Deux pôles Nord et Sud
        let north_pole = GpsPoint::from_f64(90.0, 0.0).expect("Nord valide");
        let south_pole = GpsPoint::from_f64(-90.0, 0.0).expect("Sud valide");

        let dist = north_pole.haversine_distance_meters(south_pole);
        let expected = std::f64::consts::PI * EARTH_MEAN_RADIUS_METERS;

        assert!((dist - expected).abs() < 1e-4);
    }
}

