    use http_body_util::BodyExt;
    use tower::ServiceExt;

    #[tokio::test]
    async fn test_create_and_get_user() {
        let app = app_router(AppState::new());

        // Création
        let create_payload = serde_json::json!({
            "name": "Alice Dupont",
            "email": "alice@example.com"
        });

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/users")
                    .header("Content-Type", "application/json")
                    .body(Body::from(serde_json::to_vec(&create_payload).unwrap()))
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::CREATED);

        let body = response.into_body().collect().await.unwrap().to_bytes();
        let created_user: User = serde_json::from_slice(&body).unwrap();
        assert_eq!(created_user.name, "Alice Dupont");

        // Récupération
        let response = app
            .oneshot(
                Request::builder()
                    .method("GET")
                    .uri(format!("/users/{}", created_user.id))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        let fetched_user: User = serde_json::from_slice(&body).unwrap();
        assert_eq!(fetched_user.id, created_user.id);
        assert_eq!(fetched_user.email, "alice@example.com");
    }
}

