// src/main.rs
use std::{
    net::SocketAddr,
    sync::{Arc, RwLock},
};

use axum::{
    extract::{Path, Query, State},
    http::StatusCode,
    response::{IntoResponse, Response},
    routing::get,
    Json, Router,
};
use chrono::{DateTime, Utc};
use once_cell::sync::Lazy;
use regex::Regex;
use serde::{Deserialize, Serialize};
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt};
use uuid::Uuid;
use validator::Validate;

// ============================================================================
// Domain Models & DTOs
// ============================================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ProductTag {
    pub name: String,
    pub priority: u32,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ProductDimensions {
    pub width: f64,
    pub height: f64,
    pub depth: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Product {
    pub id: Uuid,
    pub name: String,
    pub sku: String,
    pub price_cents: u64,
    pub stock: u32,
    pub dimensions: Option<ProductDimensions>,
    pub tags: Vec<ProductTag>,
    pub created_at: DateTime<Utc>,
}

#[derive(Debug, Clone, Serialize, Deserialize, Validate)]
pub struct DimensionsPayload {
    #[validate(range(min = 0.1, message = "La largeur doit être supérieure ou égale à 0.1"))]
    pub width: f64,
    #[validate(range(min = 0.1, message = "La hauteur doit être supérieure ou égale à 0.1"))]
    pub height: f64,
    #[validate(range(min = 0.1, message = "La profondeur doit être supérieure ou égale à 0.1"))]
    pub depth: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize, Validate)]
pub struct TagPayload {
    #[validate(length(min = 2, max = 30, message = "Le nom du tag doit comporter entre 2 et 30 caractères"))]
    pub name: String,
    #[validate(range(min = 1, max = 5, message = "La priorité doit être comprise entre 1 et 5"))]
    pub priority: u32,
}

static SKU_REGEX: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"^SKU-[A-Z0-9]{4,10}$").expect("Regex SKU invalide")
});

#[derive(Debug, Clone, Serialize, Deserialize, Validate)]
pub struct CreateProductPayload {
    #[validate(length(min = 3, max = 100, message = "Le nom doit comporter entre 3 et 100 caractères"))]
    pub name: String,

    #[validate(regex(
        path = *SKU_REGEX,
        message = "Le SKU doit respecter le format SKU-[A-Z0-9]{4,10}"
    ))]
    pub sku: String,

    #[validate(range(min = 1, message = "Le prix doit être strictement positif"))]
    pub price_cents: u64,

    #[validate(range(min = 0, message = "Le stock ne peut pas être négatif"))]
    pub stock: u32,

    #[validate(nested)]
    pub dimensions: Option<DimensionsPayload>,

    #[validate(nested)]
    #[validate(length(max = 10, message = "Au maximum 10 tags autorisés"))]
    pub tags: Vec<TagPayload>,
}

// ============================================================================
// Query Params (Pagination & Sorting)
// ============================================================================

#[derive(Debug, Clone, Copy, Deserialize, Default)]
#[serde(rename_all = "lowercase")]
pub enum SortDirection {
    #[default]
    Asc,
    Desc,
}

#[derive(Debug, Clone, Copy, Deserialize, Default)]
#[serde(rename_all = "snake_case")]
pub enum ProductSortColumn {
    #[default]
    Name,
    Sku,
    PriceCents,
    Stock,
    CreatedAt,
}

#[derive(Debug, Deserialize)]
pub struct ProductFilterQuery {
    pub page: Option<usize>,
    pub per_page: Option<usize>,
    pub sort_by: Option<ProductSortColumn>,
    pub order: Option<SortDirection>,
    pub search: Option<String>,
}

#[derive(Debug, Serialize)]
pub struct PaginationMeta {
    pub current_page: usize,
    pub per_page: usize,
    pub total_items: usize,
    pub total_pages: usize,
}

#[derive(Debug, Serialize)]
pub struct PaginatedResponse<T> {
    pub data: Vec<T>,
    pub pagination: PaginationMeta,
}

// ============================================================================
// App State
// ============================================================================

#[derive(Clone, Default)]
pub struct AppState {
    pub products: Arc<RwLock<Vec<Product>>>,
}

// ============================================================================
// Error Handling
// ============================================================================

#[derive(Debug, Serialize)]
pub struct ApiErrorResponse {
    pub error: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub details: Option<serde_json::Value>,
}

pub enum AppError {
    Validation(validator::ValidationErrors),
    NotFound(String),
    Conflict(String),
    Internal(String),
}

impl IntoResponse for AppError {
    fn into_response(self) -> Response {
        let (status, err_msg, details) = match self {
            AppError::Validation(validation_errors) => (
                StatusCode::UNPROCESSABLE_ENTITY,
                "Erreur de validation de payload".to_string(),
                Some(serde_json::to_value(&validation_errors).unwrap_or_default()),
            ),
            AppError::NotFound(message) => (StatusCode::NOT_FOUND, message, None),
            AppError::Conflict(message) => (StatusCode::CONFLICT, message, None),
            AppError::Internal(message) => {
                tracing::error!("Erreur interne du serveur: {message}");
                (
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "Une erreur interne est survenue".to_string(),
                    None,
                )
            }
        };

        let body = Json(ApiErrorResponse {
            error: err_msg,
            details,
        });

        (status, body).into_response()
    }
}

// ============================================================================
// Handlers
// ============================================================================

async fn health_check() -> impl IntoResponse {
    (StatusCode::OK, Json(serde_json::json!({ "status": "ok" })))
}

async fn list_products(
    State(state): State<AppState>,
    Query(query): Query<ProductFilterQuery>,
) -> Result<Json<PaginatedResponse<Product>>, AppError> {
    let page = query.page.unwrap_or(1).max(1);
    let per_page = query.per_page.unwrap_or(10).clamp(1, 100);
    let sort_col = query.sort_by.unwrap_or_default();
    let sort_dir = query.order.unwrap_or_default();

    let storage = state
        .products
        .read()
        .map_err(|e| AppError::Internal(format!("RwLock read poisoned: {e}")))?;

    let mut filtered_products: Vec<Product> = storage
        .iter()
        .filter(|p| {
            if let Some(ref term) = query.search {
                let term_lower = term.to_lowercase();
                p.name.to_lowercase().contains(&term_lower)
                    || p.sku.to_lowercase().contains(&term_lower)
            } else {
                true
            }
        })
        .cloned()
        .collect();

    filtered_products.sort_by(|a, b| {
        let ordering = match sort_col {
            ProductSortColumn::Name => a.name.to_lowercase().cmp(&b.name.to_lowercase()),
            ProductSortColumn::Sku => a.sku.cmp(&b.sku),
            ProductSortColumn::PriceCents => a.price_cents.cmp(&b.price_cents),
            ProductSortColumn::Stock => a.stock.cmp(&b.stock),
            ProductSortColumn::CreatedAt => a.created_at.cmp(&b.created_at),
        };

        match sort_dir {
            SortDirection::Asc => ordering,
            SortDirection::Desc => ordering.reverse(),
        }
    });

    let total_items = filtered_products.len();
    let total_pages = if total_items == 0 {
        1
    } else {
        (total_items + per_page - 1) / per_page
    };

    let start_idx = (page - 1) * per_page;
    let paginated_slice = if start_idx >= total_items {
        Vec::new()
    } else {
        let end_idx = (start_idx + per_page).min(total_items);
        filtered_products[start_idx..end_idx].to_vec()
    };

    Ok(Json(PaginatedResponse {
        data: paginated_slice,
        pagination: PaginationMeta {
            current_page: page,
            per_page,
            total_items,
            total_pages,
        },
    }))
}

async fn get_product_by_id(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
) -> Result<Json<Product>, AppError> {
    let storage = state
        .products
        .read()
        .map_err(|e| AppError::Internal(format!("RwLock read poisoned: {e}")))?;

    storage
        .iter()
        .find(|p| p.id == id)
        .cloned()
        .map(Json)
        .ok_or_else(|| AppError::NotFound(format!("Produit avec l'identifiant '{id}' introuvable")))
}

async fn create_product(
    State(state): State<AppState>,
    Json(payload): Json<CreateProductPayload>,
) -> Result<(StatusCode, Json<Product>), AppError> {
    payload.validate().map_err(AppError::Validation)?;

    let mut storage = state
        .products
        .write()
        .map_err(|e| AppError::Internal(format!("RwLock write poisoned: {e}")))?;

    if storage.iter().any(|p| p.sku.eq_ignore_ascii_case(&payload.sku)) {
        return Err(AppError::Conflict(format!(
            "Un produit avec le SKU '{}' existe déjà",
            payload.sku
        )));
    }

    let new_product = Product {
        id: Uuid::new_v4(),
        name: payload.name,
        sku: payload.sku,
        price_cents: payload.price_cents,
        stock: payload.stock,
        dimensions: payload.dimensions.map(|d| ProductDimensions {
            width: d.width,
            height: d.height,
            depth: d.depth,
        }),
        tags: payload
            .tags
            .into_iter()
            .map(|t| ProductTag {
                name: t.name,
                priority: t.priority,
            })
            .collect(),
        created_at: Utc::now(),
    };

    storage.push(new_product.clone());

    Ok((StatusCode::CREATED, Json(new_product)))
}

