```rust
// src/main.rs
use std::collections::HashMap;
use std::net::SocketAddr;
use std::sync::Arc;
use std::time::{SystemTime, UNIX_EPOCH};

use futures_util::{SinkExt, StreamExt};
use serde::{Deserialize, Serialize};
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::{mpsc, RwLock};
use tokio_tungstenite::tungstenite::Message;
use tracing::{error, info, warn};

#[derive(Debug, Deserialize)]
#[serde(tag = "action", rename_all = "snake_case")]
enum ClientCommand {
    Join { room: String, username: String },
    Send { content: String },
    Leave,
}

#[derive(Debug, Clone, Serialize)]
#[serde(tag = "type", rename_all = "snake_case")]
enum ServerNotification {
    Info {
        message: String,
    },
    Error {
        message: String,
    },
    Message {
        room: String,
        sender: String,
        content: String,
        timestamp: u64,
    },
    UserJoined {
        room: String,
        username: String,
    },
    UserLeft {
        room: String,
        username: String,
    },
}

#[derive(Debug)]
struct Peer {
    username: String,
    tx: mpsc::UnboundedSender<ServerNotification>,
}

#[derive(Default)]
struct Hub {
    // room_name -> (peer_addr -> Peer)
    rooms: HashMap<String, HashMap<SocketAddr, Peer>>,
}

type SharedHub = Arc<RwLock<Hub>>;

impl Hub {
    fn leave_room(
        &mut self,
        addr: &SocketAddr,
    ) -> Option<(String, String)> {
        let mut found_room = None;
        for (room_name, peers) in self.rooms.iter_mut() {
            if let Some(peer) = peers.remove(addr) {
                found_room = Some((room_name.clone(), peer.username));
                break;
            }
        }

        if let Some((ref room_name, _)) = found_room {
            if let Some(peers) = self.rooms.get(room_name) {
                if peers.is_empty() {
                    self.rooms.remove(room_name);
                }
            }
        }

        found_room
    }

    fn broadcast(
        &self,
        room_name: &str,
        notification: &ServerNotification,
        exclude_addr: Option<&SocketAddr>,
    ) {
        if let Some(peers) = self.rooms.get(room_name) {
            for (addr, peer) in peers.iter() {
                if let Some(exclude) = exclude_addr {
                    if addr == exclude {
                        continue;
                    }
                }
                let _ = peer.tx.send(notification.clone());
            }
        }
    }
}

fn current_timestamp() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

async fn handle_connection(
    hub: SharedHub,
    raw_stream: TcpStream,
    addr: SocketAddr,
) {
    let ws_stream = match tokio_tungstenite::accept_async(raw_stream).await {
        Ok(ws) => ws,
        Err(err) => {
            warn!(%addr, "Échec du handshake WebSocket: {err}");
            return;
        }
    };

    info!(%addr, "Nouvelle connexion WebSocket établie");

    let (mut ws_sink, mut ws_reader) = ws_stream.split();
    let (tx, mut rx) = mpsc::unbounded_channel::<ServerNotification>();

    // Initial greeting
    let welcome = ServerNotification::Info {
        message: "Bienvenue sur le serveur WebSocket. Envoyez un message JSON {'action': 'join', 'room': '...', 'username': '...'} pour rejoindre un salon.".to_string(),
    };
    let _ = tx.send(welcome);

    let mut current_room: Option<String> = None;
    let mut current_username: Option<String> = None;

    loop {
        tokio::select! {
            Some(notification) = rx.recv() => {
                match serde_json::to_string(&notification) {
                    Ok(json_str) => {
                        if let Err(err) = ws_sink.send(Message::Text(json_str.into())).await {
                            warn!(%addr, "Erreur d'envoi WebSocket: {err}");
                            break;
                        }
                    }
                    Err(err) => {
                        error!("Erreur de sérialisation JSON: {err}");
                    }
                }
            }
            msg = ws_reader.next() => {
                match msg {
                    Some(Ok(Message::Text(text))) => {
                        match serde_json::from_str::<ClientCommand>(text.as_ref()) {
                            Ok(ClientCommand::Join { room, username }) => {
                                let trimmed_room = room.trim().to_string();
                                let trimmed_user = username.trim().to_string();

                                if trimmed_room.is_empty() || trimmed_user.is_empty() {
                                    let _ = tx.send(ServerNotification::Error {
                                        message: "Le nom du salon et le nom d'utilisateur ne peuvent pas être vides.".to_string(),
                                    });
                                    continue;
                                }

                                // Si déjà dans un salon, on le quitte proprement
                                {
                                    let mut hub_guard = hub.write().await;
                                    if let Some((prev_room, prev_user)) = hub_guard.leave_room(&addr) {
                                        let leave_notif = ServerNotification::UserLeft {
                                            room: prev_room.clone(),
                                            username: prev_user,
                                        };
                                        hub_guard.broadcast(&prev_room, &leave_notif, Some(&addr));
                                    }

                                    // Ajout au nouveau salon
                                    let peer = Peer {
                                        username: trimmed_user.clone(),
                                        tx: tx.clone(),
                                    };

                                    hub_guard
                                        .rooms
                                        .entry(trimmed_room.clone())
                                        .or_default()
                                        .insert(addr, peer);

                                    let join_notif = ServerNotification::UserJoined {
                                        room: trimmed_room.clone(),
                                        username: trimmed_user.clone(),
                                    };
                                    hub_guard.broadcast(&trimmed_room, &join_notif, Some(&addr));
                                }

                                current_room = Some(trimmed_room.clone());
                                current_username = Some(trimmed_user.clone());

                                let _ = tx.send(ServerNotification::Info {
                                    message: format!("Vous avez rejoint le salon '{trimmed_room}' sous le pseudo '{trimmed_user}'."),
                                });
                            }
                            Ok(ClientCommand::Send { content }) => {
                                let trimmed_content = content.trim().to_string();
                                if trimmed_content.is_empty() {
                                    continue;
                                }

                                match (&current_room, &current_username) {
                                    (Some(room), Some(username)) => {
                                        let notification = ServerNotification::Message {
                                            room: room.clone(),
                                            sender: username.clone(),
                                            content: trimmed_content,
                                            timestamp: current_timestamp(),
                                        };
                                        let hub_guard = hub.read().await;
                                        hub_guard.broadcast(room, &notification, None);
                                    }
                                    _ => {
                                        let _ = tx.send(ServerNotification::Error {
                                            message: "Vous devez rejoindre un salon avant d'envoyer un message.".to_string(),
                                        });
                                    }
                                }
                            }
                            Ok(ClientCommand::Leave) => {
                                let mut hub_guard = hub.write().await;
                                if let Some((prev_room, prev_user)) = hub_guard.leave_room(&addr) {
                                    let leave_notif = ServerNotification::UserLeft {
                                        room: prev_room.clone(),
                                        username: prev_user,
                                    };
                                    hub_guard.broadcast(&prev_room, &leave_notif, Some(&addr));
                                    let _ = tx.send(ServerNotification::Info {
                                        message: format!("Vous avez quitté le salon '{prev_room}'."),
                                    });
                                }
                                current_room = None;
                                current_username = None;
                            }
                            Err(err) => {
                                let _ = tx.send(ServerNotification::Error {
                                    message: format!("Message JSON invalide: {err}"),
                                });
                            }
                        }
                    }
                    Some(Ok(Message::Ping(data))) => {
                        if let Err(err) = ws_sink.send(Message::Pong(data)).await {
                            warn!(%addr, "Erreur lors de la réponse Pong: {err}");
                            break;
                        }
                    }
                    Some(Ok(Message::Close(_))) => {
                        info!(%addr, "Fermeture demandée par le client");
                        break;
                    }
                    Some(Ok(_)) => {
                        // Ignore binary ou pong
                    }
                    Some(Err(err)) => {
                        warn!(%addr, "Erreur sur le flux WebSocket: {err}");
                        break;
                    }
                    None => {
                        break;
                    }
                }
            }
        }
    }

    // Déconnexion et nettoyage
    {
        let mut hub_guard = hub.write().await;
        if let Some((room, username)) = hub_guard.leave_room(&addr) {
            let leave_notif = ServerNotification::UserLeft {
                room: room.clone(),
                username,
            };
            hub_guard.broadcast(&room, &leave_notif, Some(&addr));
        }
    }

    info!(%addr, "Client déconnecté et retiré des salons");
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "websocket_rooms=info,tokio=warn".into()),
        )
        .init();

    let bind_addr = std::env::var("BIND_ADDR").unwrap_or_else(|_| "127.0.0.1:8080".to_string());
    let listener = TcpListener::bind(&bind_addr).await?;
    info!("Serveur WebSocket en écoute sur ws://{bind_addr}");

    let hub = Arc::new(RwLock::new(Hub::default()));

    while let Ok((stream, addr)) = listener.accept().await {
        let hub_clone = Arc::clone(&hub);
        tokio::spawn(async move {
            handle_connection(hub_clone, stream, addr).await;
        });
    }

    Ok(())
}

