```rust
// src/main.rs
use std::convert::Infallible;
use std::net::SocketAddr;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::time::Instant;

use http_body_util::combinators::BoxBody;
use http_body_util::{BodyExt, Empty, Full};
use hyper::body::{Bytes, Incoming};
use hyper::header::{HeaderMap, HeaderName, HeaderValue, HOST};
use hyper::service::service_fn;
use hyper::{Request, Response, StatusCode, Uri};
use hyper_util::client::legacy::connect::HttpConnector;
use hyper_util::client::legacy::Client;
use hyper_util::rt::{TokioExecutor, TokioIo};
use hyper_util::server::conn::auto;
use tokio::net::TcpListener;
use tokio::signal;
use tracing::{error, info, warn};

/// Type alias pour le client HTTP Hyper legacy utilisant le connecteur TCP Tokio
type HttpClient = Client<HttpConnector, Incoming>;

/// Structure représentant le cluster de backends avec politique Round-Robin
#[derive(Debug)]
pub struct Cluster {
    backends: Vec<Uri>,
    current_index: AtomicUsize,
}

impl Cluster {
    /// Crée un nouveau cluster à partir d'une liste d'URIs de backends
    pub fn new(backends: Vec<Uri>) -> Result<Self, &'static str> {
        if backends.is_empty() {
            return Err("Le cluster de backends ne peut pas être vide");
        }
        Ok(Self {
            backends,
            current_index: AtomicUsize::new(0),
        })
    }

    /// Sélectionne le prochain backend selon l'algorithme Round-Robin
    pub fn next_backend(&self) -> &Uri {
        let index = self.current_index.fetch_add(1, Ordering::Relaxed);
        &self.backends[index % self.backends.len()]
    }
}

/// État partagé entre les workers du reverse proxy
pub struct ProxyState {
    pub cluster: Cluster,
    pub http_client: HttpClient,
}

/// Liste des en-têtes Hop-by-Hop à retirer selon les spécifications RFC 7230 / RFC 2616
const HOP_BY_HOP_HEADERS: &[&str] = &[
    "connection",
    "keep-alive",
    "proxy-authenticate",
    "proxy-authorization",
    "te",
    "trailers",
    "transfer-encoding",
    "upgrade",
];

/// Supprime les en-têtes hop-by-hop d'une table d'en-têtes HTTP
fn remove_hop_by_hop_headers(headers: &mut HeaderMap) {
    for header in HOP_BY_HOP_HEADERS {
        if let Ok(name) = HeaderName::from_bytes(header.as_bytes()) {
            headers.remove(name);
        }
    }
}

/// Construit la nouvelle URI vers le backend cible en préservant le chemin et les query params
fn build_target_uri(backend: &Uri, req_uri: &Uri) -> Result<Uri, hyper::http::uri::InvalidUriParts> {
    let mut parts = backend.clone().into_parts();

    let path_and_query = req_uri
        .path_and_query()
        .cloned()
        .unwrap_or_else(|| hyper::http::uri::PathAndQuery::from_static("/"));

    parts.path_and_query = Some(path_and_query);

    Uri::from_parts(parts)
}

/// Enrichit les en-têtes de la requête pour le backend (X-Forwarded-*, Host)
fn forward_headers(headers: &mut HeaderMap, client_addr: SocketAddr, backend: &Uri) {
    // Retrait des headers de saut intermédiaire (hop-by-hop)
    remove_hop_by_hop_headers(headers);

    // X-Forwarded-For
    let client_ip = client_addr.ip().to_string();
    match headers.get_mut("x-forwarded-for") {
        Some(existing) => {
            if let Ok(existing_str) = existing.to_str() {
                let updated = format!("{}, {}", existing_str, client_ip);
                if let Ok(val) = HeaderValue::from_str(&updated) {
                    *existing = val;
                }
            }
        }
        None => {
            if let Ok(val) = HeaderValue::from_str(&client_ip) {
                headers.insert(HeaderName::from_static("x-forwarded-for"), val);
            }
        }
    }

    // X-Forwarded-Proto
    headers
        .entry(HeaderName::from_static("x-forwarded-proto"))
        .or_insert_with(|| HeaderValue::from_static("http"));

    // Sauvegarde du Host d'origine dans X-Forwarded-Host
    if let Some(original_host) = headers.get(HOST).cloned() {
        headers
            .entry(HeaderName::from_static("x-forwarded-host"))
            .or_insert(original_host);
    }

    // Mise à jour de l'en-tête Host avec l'autorité du backend cible
    if let Some(authority) = backend.authority() {
        if let Ok(host_val) = HeaderValue::from_str(authority.as_str()) {
            headers.insert(HOST, host_val);
        }
    }
}

/// Helper pour produire une réponse HTTP d'erreur avec un corps texte
fn error_response(status: StatusCode, message: &'static str) -> Response<BoxBody<Bytes, hyper::Error>> {
    let body = Full::new(Bytes::from(message))
        .map_err(|e| match e {})
        .boxed();

    Response::builder()
        .status(status)
        .header(hyper::header::CONTENT_TYPE, "text/plain; charset=utf-8")
        .body(body)
        .unwrap_or_else(|_| {
            Response::new(
                Empty::new()
                    .map_err(|e| match e {})
                    .boxed(),
            )
        })
}

/// Gestionnaire principal de requête de proxy
async fn handle_proxy_request(
    mut req: Request<Incoming>,
    client_addr: SocketAddr,
    state: Arc<ProxyState>,
) -> Result<Response<BoxBody<Bytes, hyper::Error>>, Infallible> {
    let start_time = Instant::now();
    let original_path = req.uri().path_and_query().map(|pq| pq.as_str()).unwrap_or("/").to_string();
    let method = req.method().clone();

    // Sélection du backend via Round-Robin
    let backend_uri = state.cluster.next_backend();

    // Construction de l'URI de destination
    let target_uri = match build_target_uri(backend_uri, req.uri()) {
        Ok(uri) => uri,
        Err(err) => {
            error!(error = %err, "Échec de construction de l'URI cible");
            return Ok(error_response(
                StatusCode::BAD_REQUEST,
                "400 Bad Request: URI invalide",
            ));
        }
    };

    // Mise à jour de l'URI et des headers de la requête
    *req.uri_mut() = target_uri.clone();
    forward_headers(req.headers_mut(), client_addr, backend_uri);

    info!(
        method = %method,
        client = %client_addr,
        path = %original_path,
        target = %target_uri,
        "Redirection de la requête vers le cluster"
    );

    // Envoi de la requête au backend
    match state.http_client.request(req).await {
        Ok(backend_resp) => {
            let status = backend_resp.status();
            let duration = start_time.elapsed();

            info!(
                status = %status.as_u16(),
                duration_ms = duration.as_millis(),
                target = %target_uri,
                "Réponse reçue du backend avec succès"
            );

            let (mut parts, body) = backend_resp.into_parts();

            // Nettoyage des headers hop-by-hop de la réponse du backend
            remove_hop_by_hop_headers(&mut parts.headers);

            let boxed_body = body.boxed();
            Ok(Response::from_parts(parts, boxed_body))
        }
        Err(err) => {
            let duration = start_time.elapsed();
            warn!(
                error = %err,
                target = %target_uri,
                duration_ms = duration.as_millis(),
                "Échec de la communication avec le backend (502 Bad Gateway)"
            );

            Ok(error_response(
                StatusCode::BAD_GATEWAY,
                "502 Bad Gateway: Le serveur backend est injoignable ou en erreur.",
            ))
        }
    }
}

/// Point d'entrée principal de l'application
#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    // Initialisation du logging structuré
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    // Configuration des adresses
    let listen_addr: SocketAddr = std::env::var("PROXY_LISTEN_ADDR")
        .unwrap_or_else(|_| "127.0.0.1:8080".to_string())
        .parse()?;

    let backend_addrs = std::env::var("PROXY_BACKENDS")
        .unwrap_or_else(|_| {
            "http://127.0.0.1:8081,http://127.0.0.1:8082,http://127.0.0.1:8083".to_string()
        });

    let backends: Vec<Uri> = backend_addrs
        .split(',')
        .map(|s| s.trim().parse::<Uri>())
        .collect::<Result<Vec<Uri>, _>>()?;

    let cluster = Cluster::new(backends).map_err(|e| format!("Erreur cluster: {}", e))?;

    info!(
        listen = %listen_addr,
        backends = ?cluster.backends,
        "Démarrage du Reverse Proxy HTTP Hyper/Tokio"
    );

    // Initialisation du client HTTP Hyper réutilisable pour le pool de connexions
    let http_connector = HttpConnector::new();
    let http_client = Client::builder(TokioExecutor::new()).build(http_connector);

    let state = Arc::new(ProxyState {
        cluster,
        http_client,
    });

    // Liaison du serveur TCP
    let listener = TcpListener::bind(listen_addr).await?;
    info!("Reverse Proxy en écoute sur http://{}", listen_addr);

    // Serveur HTTP multi-protocole (HTTP/1 et HTTP/2 auto)
    let auto_server = auto::Builder::new(TokioExecutor::new());

    // Boucle d'acceptation des connexions avec gestion d'arrêt propre (graceful shutdown)
    loop {
        tokio::select! {
            accept_result = listener.accept() => {
                match accept_result {
                    Ok((tcp_stream, client_addr)) => {
                        let state = Arc::clone(&state);
                        let auto_server = auto_server.clone();

                        tokio::spawn(async move {
                            let io = TokioIo::new(tcp_stream);
                            let service = service_fn(move |req| {
                                let state = Arc::clone(&state);
                                async move {
                                    handle_proxy_request(req, client_addr, state).await
                                }
                            });

                            if let Err(err) = auto_server.serve_connection(io, service).await {
                                // Les déconnexions client inopinées sont courantes en HTTP, loguées en debug/warn
                                warn!(client = %client_addr, error = %err, "Erreur lors du traitement de la connexion client");
                            }
                        });
                    }
                    Err(err) => {
                        error!(error = %err, "Erreur lors de l'acceptation d'une connexion TCP");
                    }
                }
            }
            _ = signal::ctrl_c() => {
                info!("Signal d'arrêt reçu (Ctrl+C). Arrêt propre du reverse proxy.");
                break;
            }
        }
    }

    Ok(())
}

