```rust
// src/main.rs
use anyhow::{Context, Result};
use reqwest::Client;
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use std::time::{Duration, Instant};
use tokio::sync::Semaphore;
use tokio::task::JoinSet;

/// Représentation typée de la réponse JSON de l'API.
#[derive(Debug, Serialize, Deserialize)]
pub struct Post {
    pub id: u64,
    #[serde(rename = "userId")]
    pub user_id: u64,
    pub title: String,
    pub body: String,
}

/// Résultat d'une tâche de récupération HTTP.
#[derive(Debug)]
pub struct FetchResult {
    pub id: u64,
    pub post: Option<Post>,
    pub elapsed: Duration,
    pub error: Option<String>,
}

/// Télécharge un article avec contrôle de concurrence via sémaphore.
async fn fetch_post(
    id: u64,
    client: Client,
    semaphore: Arc<Semaphore>,
) -> FetchResult {
    let start_time = Instant::now();

    // Acquisition asynchrone d'un permis du sémaphore
    let permit = match semaphore.acquire_owned().await {
        Ok(permit) => permit,
        Err(err) => {
            return FetchResult {
                id,
                post: None,
                elapsed: start_time.elapsed(),
                error: Some(format!("Échec d'acquisition du sémaphore: {err}")),
            };
        }
    };

    println!("[ID {:02}] Permis acquis. Requête en cours...", id);

    let url = format!("https://jsonplaceholder.typicode.com/posts/{id}");
    let response = client
        .get(&url)
        .header("User-Agent", "reqwest-tokio-semaphore-demo/1.0")
        .send()
        .await;

    let result = match response {
        Ok(resp) => match resp.error_for_status() {
            Ok(valid_resp) => match valid_resp.json::<Post>().await {
                Ok(post) => FetchResult {
                    id,
                    post: Some(post),
                    elapsed: start_time.elapsed(),
                    error: None,
                },
                Err(err) => FetchResult {
                    id,
                    post: None,
                    elapsed: start_time.elapsed(),
                    error: Some(format!("Échec de désérialisation JSON: {err}")),
                },
            },
            Err(status_err) => FetchResult {
                id,
                post: None,
                elapsed: start_time.elapsed(),
                error: Some(format!("Statut HTTP non valide: {status_err}")),
            },
        },
        Err(req_err) => FetchResult {
            id,
            post: None,
            elapsed: start_time.elapsed(),
            error: Some(format!("Échec réseau: {req_err}")),
        },
    };

    // Libération explicite du permis (drop automatique de `permit` ici)
    drop(permit);
    println!("[ID {:02}] Terminé en {:.2?}.", id, result.elapsed);

    result
}

#[tokio::main]
async fn main() -> Result<()> {
    println!("=== Client HTTP Reqwest avec Sémaphore Tokio ===\n");

    const MAX_CONCURRENT_REQUESTS: usize = 3;
    const TOTAL_REQUESTS: u64 = 10;
    const REQUEST_TIMEOUT_SECS: u64 = 10;

    // Construction d'un client HTTP réutilisable avec pool de connexions et timeout
    let client = Client::builder()
        .timeout(Duration::from_secs(REQUEST_TIMEOUT_SECS))
        .pool_max_idle_per_host(MAX_CONCURRENT_REQUESTS)
        .build()
        .context("Impossible d'initialiser le client HTTP Reqwest")?;

    // Sémaphore limitant la concurrence à MAX_CONCURRENT_REQUESTS requêtes simultanées
    let semaphore = Arc::new(Semaphore::new(MAX_CONCURRENT_REQUESTS));
    let mut join_set = JoinSet::new();

    println!(
        "Lancement de {TOTAL_REQUESTS} requêtes avec une limite de {MAX_CONCURRENT_REQUESTS} requêtes concurrentes...\n"
    );

    let global_start = Instant::now();

    // Planification des tâches dans le JoinSet
    for id in 1..=TOTAL_REQUESTS {
        let client_clone = client.clone();
        let semaphore_clone = Arc::clone(&semaphore);

        join_set.spawn(fetch_post(id, client_clone, semaphore_clone));
    }

    // Réception et traitement des résultats au fur et à mesure de leur complétion
    let mut successes = 0;
    let mut failures = 0;

    while let Some(res) = join_set.join_next().await {
        match res {
            Ok(fetch_result) => {
                if let Some(post) = &fetch_result.post {
                    successes += 1;
                    println!(
                        "✓ Succès [ID {:02}] (durée: {:.2?}): \"{}\"",
                        fetch_result.id,
                        fetch_result.elapsed,
                        post.title.chars().take(30).collect::<String>()
                    );
                } else if let Some(err) = &fetch_result.error {
                    failures += 1;
                    eprintln!(
                        "✗ Échec [ID {:02}] (durée: {:.2?}): {err}",
                        fetch_result.id, fetch_result.elapsed
                    );
                }
            }
            Err(join_err) => {
                failures += 1;
                eprintln!("✗ Erreur d'exécution de la tâche Tokio: {join_err}");
            }
        }
    }

    let total_duration = global_start.elapsed();

    println!("\n=== Bilan de l'exécution ===");
    println!("Total requêtes : {TOTAL_REQUESTS}");
    println!("Succès         : {successes}");
    println!("Échecs         : {failures}");
    println!("Durée totale   : {:.2?}", total_duration);

    Ok(())
}

