    const REQUEST_TIMEOUT_SECS: u64 = 10;

    // Construction d'un client HTTP réutilisable avec pool de connexions et timeout
    let client = Client::builder()
        .timeout(Duration::from_secs(REQUEST_TIMEOUT_SECS))
        .pool_max_idle_per_host(MAX_CONCURRENT_REQUESTS)
        .build()
        .context("Impossible d'initialiser le client HTTP Reqwest")?;

    // Sémaphore limitant la concurrence à MAX_CONCURRENT_REQUESTS requêtes simultanées
    let semaphore = Arc::new(Semaphore::new(MAX_CONCURRENT_REQUESTS));
    let mut join_set = JoinSet::new();

    println!(
        "Lancement de {TOTAL_REQUESTS} requêtes avec une limite de {MAX_CONCURRENT_REQUESTS} requêtes concurrentes...\n"
    );

    let global_start = Instant::now();

    // Planification des tâches dans le JoinSet
    for id in 1..=TOTAL_REQUESTS {
        let client_clone = client.clone();
        let semaphore_clone = Arc::clone(&semaphore);

        join_set.spawn(fetch_post(id, client_clone, semaphore_clone));
    }

    // Réception et traitement des résultats au fur et à mesure de leur complétion
    let mut successes = 0;
    let mut failures = 0;

    while let Some(res) = join_set.join_next().await {
        match res {
            Ok(fetch_result) => {
                if let Some(post) = &fetch_result.post {
                    successes += 1;
                    println!(
                        "✓ Succès [ID {:02}] (durée: {:.2?}): \"{}\"",
                        fetch_result.id,
                        fetch_result.elapsed,
                        post.title.chars().take(30).collect::<String>()
                    );
                } else if let Some(err) = &fetch_result.error {
                    failures += 1;
                    eprintln!(
                        "✗ Échec [ID {:02}] (durée: {:.2?}): {err}",
                        fetch_result.id, fetch_result.elapsed
                    );
                }
            }
            Err(join_err) => {
                failures += 1;
                eprintln!("✗ Erreur d'exécution de la tâche Tokio: {join_err}");
            }
        }
    }

    let total_duration = global_start.elapsed();

    println!("\n=== Bilan de l'exécution ===");
    println!("Total requêtes : {TOTAL_REQUESTS}");
    println!("Succès         : {successes}");
    println!("Échecs         : {failures}");
    println!("Durée totale   : {:.2?}", total_duration);

    Ok(())
}

