```rust
// src/main.rs
use std::{
    net::SocketAddr,
    sync::Arc,
    time::Duration,
};

use axum::{
    extract::{MatchedPath, Request, State},
    http::{header, HeaderValue, StatusCode},
    middleware::{self, Next},
    response::{IntoResponse, Response},
    routing::{get, post},
    Json, Router,
};
use prometheus::{
    opts, Encoder, IntCounter, IntCounterVec, IntGauge, Opts, Registry, TextEncoder,
};
use tracing::{error, info};
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt};

/// Métriques Prometheus de l'application
#[derive(Clone)]
pub struct AppMetrics {
    registry: Registry,
    http_requests_total: IntCounterVec,
    active_requests: IntGauge,
    simulated_queue_depth: IntGauge,
    completed_tasks_total: IntCounter,
}

impl AppMetrics {
    /// Initialise le registre Prometheus et les collecteurs de métriques.
    pub fn new() -> Result<Self, prometheus::Error> {
        let registry = Registry::new();

        // 1. Compteur vectoriel avec labels pour les requêtes HTTP
        let http_requests_total = IntCounterVec::new(
            Opts::new(
                "http_requests_total",
                "Nombre total de requêtes HTTP traitées par le service",
            ),
            &["method", "path", "status"],
        )?;
        registry.register(Box::new(http_requests_total.clone()))?;

        // 2. Jauge pour surveiller le nombre de requêtes HTTP en cours
        let active_requests = IntGauge::with_opts(opts!(
            "http_active_requests",
            "Nombre de requêtes HTTP actuellement en cours de traitement"
        ))?;
        registry.register(Box::new(active_requests.clone()))?;

        // 3. Jauge métier pour surveiller la profondeur d'une file de tâches
        let simulated_queue_depth = IntGauge::with_opts(opts!(
            "task_queue_depth",
            "Nombre actuel d'éléments en attente dans la file de tâches"
        ))?;
        registry.register(Box::new(simulated_queue_depth.clone()))?;

        // 4. Compteur métier simple pour le nombre de tâches accomplies
        let completed_tasks_total = IntCounter::with_opts(opts!(
            "completed_tasks_total",
            "Nombre total de tâches métier accomplies avec succès"
        ))?;
        registry.register(Box::new(completed_tasks_total.clone()))?;

        Ok(Self {
            registry,
            http_requests_total,
            active_requests,
            simulated_queue_depth,
            completed_tasks_total,
        })
    }

    /// Exporte l'ensemble des métriques collectées au format texte Prometheus standard.
    pub fn export_metrics(&self) -> Result<String, String> {
        let encoder = TextEncoder::new();
        let metric_families = self.registry.gather();
        let mut buffer = Vec::new();

        encoder
            .encode(&metric_families, &mut buffer)
            .map_err(|e| format!("Erreur lors de l'encodage Prometheus: {e}"))?;

        String::from_utf8(buffer)
            .map_err(|e| format!("Erreur de conversion UTF-8 des métriques: {e}"))
    }
}

/// État partagé de l'application Axum
#[derive(Clone)]
pub struct AppState {
    pub metrics: Arc<AppMetrics>,
}

/// Gardien RAII garantissant la décrémentation de la jauge active_requests
struct InFlightGuard(IntGauge);

impl InFlightGuard {
    fn new(gauge: IntGauge) -> Self {
        gauge.inc();
        Self(gauge)
    }
}

impl Drop for InFlightGuard {
    fn drop(&mut self) {
        self.0.dec();
    }
}

/// Middleware comptabilisant les requêtes actives (jauge) et le volume total (compteur).
async fn track_metrics_middleware(
    State(state): State<AppState>,
    req: Request,
    next: Next,
) -> Response {
    let _guard = InFlightGuard::new(state.metrics.active_requests.clone());

    let method = req.method().to_string();
    let path = req
        .extensions()
        .get::<MatchedPath>()
        .map_or_else(|| req.uri().path().to_string(), |mp| mp.as_str().to_string());

    let response = next.run(req).await;
    let status = response.status().as_u16().to_string();

    state
        .metrics
        .http_requests_total
        .with_label_values(&[&method, &path, &status])
        .inc();

    response
}

/// Point d'accès `/metrics` exposant le format texte standard Prometheus (v0.0.4)
async fn metrics_handler(State(state): State<AppState>) -> impl IntoResponse {
    match state.metrics.export_metrics() {
        Ok(metrics_text) => (
            StatusCode::OK,
            [(
                header::CONTENT_TYPE,
                HeaderValue::from_static(prometheus::TEXT_FORMAT),
            )],
            metrics_text,
        )
            .into_response(),
        Err(err) => {
            error!(error = %err, "Échec de génération des métriques Prometheus");
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                [(
                    header::CONTENT_TYPE,
                    HeaderValue::from_static("text/plain; charset=utf-8"),
                )],
                format!("Internal Server Error: {err}"),
            )
                .into_response()
        }
    }
}

/// Endpoint racine
async fn root_handler() -> &'static str {
    "Microservice Axum avec métriques Prometheus opérationnel."
}

/// Endpoint de santé pour orchestrateurs (Kubernetes/Docker)
async fn health_handler() -> Json<serde_json::Value> {
    Json(serde_json::json!({
        "status": "UP",
        "service": "axum-prometheus-service"
    }))
}

/// Simule l'ajout d'une tâche (incrémente la jauge de file d'attente)
async fn task_enqueue_handler(State(state): State<AppState>) -> impl IntoResponse {
    state.metrics.simulated_queue_depth.inc();
    let current_depth = state.metrics.simulated_queue_depth.get();
    Json(serde_json::json!({
        "message": "Tâche ajoutée à la file",
        "current_queue_depth": current_depth
    }))
}

/// Simule le traitement d'une tâche (décrémente la jauge et incrémente le compteur de complétion)
async fn task_process_handler(State(state): State<AppState>) -> impl IntoResponse {
    // Décrémenter seulement si la profondeur est positive
    if state.metrics.simulated_queue_depth.get() > 0 {
        state.metrics.simulated_queue_depth.dec();
    }
    state.metrics.completed_tasks_total.inc();

    let current_depth = state.metrics.simulated_queue_depth.get();
    let total_completed = state.metrics.completed_tasks_total.get();

    Json(serde_json::json!({
        "message": "Tâche traitée avec succès",
        "current_queue_depth": current_depth,
        "completed_tasks_total": total_completed
    }))
}

/// Simule un traitement asynchrone pour observer la jauge de requêtes actives
async fn slow_work_handler() -> impl IntoResponse {
    tokio::time::sleep(Duration::from_millis(500)).await;
    "Traitement asynchrone terminé avec succès."
}

/// Construction du routeur de l'application
pub fn create_router(state: AppState) -> Router {
    Router::new()
        .route("/", get(root_handler))
        .route("/health", get(health_handler))
        .route("/api/slow", get(slow_work_handler))
        .route("/api/tasks/enqueue", post(task_enqueue_handler))
        .route("/api/tasks/process", post(task_process_handler))
        .route("/metrics", get(metrics_handler))
        .layer(middleware::from_fn_with_state(
            state.clone(),
            track_metrics_middleware,
        ))
        .with_state(state)
}

/// Gestion de l'arrêt propre (Graceful Shutdown)
async fn shutdown_signal() {
    let ctrl_c = async {
        if let Err(err) = tokio::signal::ctrl_c().await {
            error!(error = %err, "Erreur lors de l'écoute du signal Ctrl+C");
        }
    };

    #[cfg(unix)]
    let terminate = async {
        match tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate()) {
            Ok(mut signal) => {
                signal.recv().await;
            }
            Err(err) => {
                error!(error = %err, "Erreur lors de l'enregistrement du signal SIGTERM");
            }
        }
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }

    info!("Signal d'arrêt reçu, fermeture propre en cours...");
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialisation des logs
    tracing_subscriber::registry()
        .with(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "axum_prometheus_service=info,tower_http=info".into()),
        )
        .with(tracing_subscriber::fmt::layer())
        .init();

    // Initialisation des métriques
    let metrics = Arc::new(AppMetrics::new().map_err(|e| {
        error!(error = %e, "Impossible d'initialiser les métriques Prometheus");
        Box::new(e) as Box<dyn std::error::Error>
    })?);

    let app_state = AppState { metrics };
    let app = create_router(app_state);

    let host = [0, 0, 0, 0];
    let port: u16 = std::env::var("PORT")
        .ok()
        .and_then(|p| p.parse().ok())
        .unwrap_or(3000);
    let addr = SocketAddr::from((host, port));

    let listener = tokio::net::TcpListener::bind(addr).await.map_err(|e| {
        error!(error = %e, address = %addr, "Impossible de lier le serveur au port");
        Box::new(e) as Box<dyn std::error::Error>
    })?;

    info!(address = %addr, "Démarrage du microservice Axum");
    info!("Endpoint métriques disponible sur http://{}/metrics", addr);

    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await
        .map_err(|e| {
            error!(error = %e, "Erreur du serveur HTTP");
            Box::new(e) as Box<dyn std::error::Error>
        })?;

    info!("Microservice arrêté avec succès");
    Ok(())
}

