    tokio::time::sleep(Duration::from_millis(500)).await;
    "Traitement asynchrone terminé avec succès."
}

/// Construction du routeur de l'application
pub fn create_router(state: AppState) -> Router {
    Router::new()
        .route("/", get(root_handler))
        .route("/health", get(health_handler))
        .route("/api/slow", get(slow_work_handler))
        .route("/api/tasks/enqueue", post(task_enqueue_handler))
        .route("/api/tasks/process", post(task_process_handler))
        .route("/metrics", get(metrics_handler))
        .layer(middleware::from_fn_with_state(
            state.clone(),
            track_metrics_middleware,
        ))
        .with_state(state)
}

/// Gestion de l'arrêt propre (Graceful Shutdown)
async fn shutdown_signal() {
    let ctrl_c = async {
        if let Err(err) = tokio::signal::ctrl_c().await {
            error!(error = %err, "Erreur lors de l'écoute du signal Ctrl+C");
        }
    };

    #[cfg(unix)]
    let terminate = async {
        match tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate()) {
            Ok(mut signal) => {
                signal.recv().await;
            }
            Err(err) => {
                error!(error = %err, "Erreur lors de l'enregistrement du signal SIGTERM");
            }
        }
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }

    info!("Signal d'arrêt reçu, fermeture propre en cours...");
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialisation des logs
    tracing_subscriber::registry()
        .with(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "axum_prometheus_service=info,tower_http=info".into()),
        )
        .with(tracing_subscriber::fmt::layer())
        .init();

    // Initialisation des métriques
    let metrics = Arc::new(AppMetrics::new().map_err(|e| {
        error!(error = %e, "Impossible d'initialiser les métriques Prometheus");
        Box::new(e) as Box<dyn std::error::Error>
    })?);

    let app_state = AppState { metrics };
    let app = create_router(app_state);

    let host = [0, 0, 0, 0];
    let port: u16 = std::env::var("PORT")
        .ok()
        .and_then(|p| p.parse().ok())
        .unwrap_or(3000);
    let addr = SocketAddr::from((host, port));

    let listener = tokio::net::TcpListener::bind(addr).await.map_err(|e| {
        error!(error = %e, address = %addr, "Impossible de lier le serveur au port");
        Box::new(e) as Box<dyn std::error::Error>
    })?;

    info!(address = %addr, "Démarrage du microservice Axum");
    info!("Endpoint métriques disponible sur http://{}/metrics", addr);

    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await
        .map_err(|e| {
            error!(error = %e, "Erreur du serveur HTTP");
            Box::new(e) as Box<dyn std::error::Error>
        })?;

    info!("Microservice arrêté avec succès");
    Ok(())
}

