// src/main.rs
use axum::{
    extract::{DefaultBodyLimit, Multipart},
    http::StatusCode,
    response::{IntoResponse, Json},
    routing::{get, post},
    Router,
};
use futures_util::TryStreamExt;
use serde::Serialize;
use std::{net::SocketAddr, path::PathBuf};
use tokio::fs::{self, File};
use tokio::io::BufWriter;
use tokio_util::io::StreamReader;
use tracing::info;
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt};
use uuid::Uuid;

const UPLOADS_DIR: &str = "./uploads";
const BUFFER_CAPACITY: usize = 256 * 1024; // 256 Ko bufferisé par fichier

#[derive(Serialize)]
struct UploadedFileInfo {
    field_name: String,
    original_file_name: Option<String>,
    saved_file_name: String,
    bytes_written: u64,
}

#[derive(Serialize)]
struct UploadResponse {
    message: String,
    files: Vec<UploadedFileInfo>,
}

#[derive(Serialize)]
struct HealthResponse {
    status: &'static str,
}

enum AppError {
    Multipart(String),
    Io(String),
}

impl IntoResponse for AppError {
    fn into_response(self) -> axum::response::Response {
        let (status, message) = match self {
            AppError::Multipart(msg) => (StatusCode::BAD_REQUEST, msg),
            AppError::Io(msg) => (StatusCode::INTERNAL_SERVER_ERROR, msg),
        };

        (
            status,
            Json(serde_json::json!({
                "error": message
            })),
        )
            .into_response()
    }
}

impl From<axum::extract::multipart::MultipartError> for AppError {
    fn from(err: axum::extract::multipart::MultipartError) -> Self {
        AppError::Multipart(err.to_string())
    }
}

impl From<std::io::Error> for AppError {
    fn from(err: std::io::Error) -> Self {
        AppError::Io(err.to_string())
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    tracing_subscriber::registry()
        .with(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "axum_streaming_upload=debug,tower_http=debug,info".into()),
        )
        .with(tracing_subscriber::fmt::layer())
        .init();

    // S'assure que le répertoire d'upload existe
    fs::create_dir_all(UPLOADS_DIR).await?;

    let app = Router::new()
        .route("/health", get(health_handler))
        .route("/upload", post(upload_handler))
        // Désactive la limite par défaut du corps HTTP pour permettre l'envoi de fichiers volumineux
        .layer(DefaultBodyLimit::disable());

    let addr = SocketAddr::from(([0, 0, 0, 0], 3000));
    info!("Serveur démarré sur http://{}", addr);

    let listener = tokio::net::TcpListener::bind(addr).await?;
    axum::serve(listener, app).await?;

    Ok(())
}

async fn health_handler() -> Json<HealthResponse> {
    Json(HealthResponse { status: "ok" })
}

async fn upload_handler(mut multipart: Multipart) -> Result<Json<UploadResponse>, AppError> {
    let mut uploaded_files = Vec::new();

    while let Some(field) = multipart.next_field().await? {
        let field_name = field.name().unwrap_or("unknown").to_string();
        let file_name = field.file_name().map(|s| s.to_string());

        // Assainissement du nom de fichier pour éviter les failles de traversée de chemin
        let safe_file_name = file_name.as_deref().map(sanitize_filename::sanitize);

        // Nom unique de sauvegarde sur disque
        let saved_file_name = match &safe_file_name {
            Some(name) if !name.trim().is_empty() => format!("{}_{}", Uuid::new_v4(), name),
            _ => format!("{}.bin", Uuid::new_v4()),
        };

        let file_path = PathBuf::from(UPLOADS_DIR).join(&saved_file_name);

        info!(
            field = %field_name,
            original_name = ?file_name,
            destination = ?file_path,
            "Début du streaming du fichier vers le disque"
        );

        // Ouverture du fichier cible
        let destination_file = File::create(&file_path).await?;
        let mut buffered_writer = BufWriter::with_capacity(BUFFER_CAPACITY, destination_file);

        // Conversion du flux Multipart de morceaux `Bytes` vers un AsyncRead tokio compatible
        let body_stream = field.map_err(|err| std::io::Error::new(std::io::ErrorKind::Other, err));
        let mut stream_reader = StreamReader::new(body_stream);

        // Copie directe en streaming du réseau vers le disque sans stocker le fichier complet en RAM
        let bytes_written = tokio::io::copy(&mut stream_reader, &mut buffered_writer).await?;

        info!(
            saved_file = %saved_file_name,
            bytes = bytes_written,
            "Fichier enregistré avec succès"
        );

        uploaded_files.push(UploadedFileInfo {
            field_name,
            original_file_name: file_name,
            saved_file_name,
            bytes_written,
        });
    }

    Ok(Json(UploadResponse {
        message: format!("Téléversement réussi pour {} fichier(s).", uploaded_files.len()),
        files: uploaded_files,
    }))
}

