/// Paramètres de configuration pour les réessais exponentiels.
#[derive(Debug, Clone)]
pub struct RetryConfig {
    pub initial_backoff: Duration,
    pub multiplier: f64,
    pub max_backoff: Duration,
    pub max_jitter_ms: u64,
}

impl Default for RetryConfig {
    fn default() -> Self {
        Self {
            initial_backoff: Duration::from_secs(1),
            multiplier: 2.0,
            max_backoff: Duration::from_secs(60),
            max_jitter_ms: 500,
        }
    }
}

impl RetryConfig {
    /// Calcule la durée d'attente avec exponential backoff et jitter.
    pub fn calculate_delay(&self, attempt: u32) -> Duration {
        let exponent = attempt.saturating_sub(1);
        let factor = self.multiplier.powi(exponent as i32);
        let base_delay = self.initial_backoff.mul_f64(factor);
        let capped_delay = base_delay.min(self.max_backoff);

        let jitter_ms = rand::thread_rng().gen_range(0..=self.max_jitter_ms);
        capped_delay + Duration::from_millis(jitter_ms)
    }
}

