/// Service de gestion et d'envoi des webhooks.
pub struct WebhookService {
    http_client: reqwest::Client,
    retry_config: RetryConfig,
    tx: mpsc::Sender<WebhookTask>,
    semaphore: Arc<Semaphore>,
}

impl WebhookService {
    pub fn new(
        tx: mpsc::Sender<WebhookTask>,
        max_concurrent_requests: usize,
        retry_config: RetryConfig,
    ) -> Arc<Self> {
        let http_client = reqwest::Client::builder()
            .timeout(Duration::from_secs(10))
            .pool_idle_timeout(Duration::from_secs(90))
            .build()
            .unwrap_or_else(|e| {
                error!("Erreur lors de l'initialisation du client HTTP: {e}");
                reqwest::Client::new()
            });

        Arc::new(Self {
            http_client,
            retry_config,
            tx,
            semaphore: Arc::new(Semaphore::new(max_concurrent_requests)),
        })
    }

    /// Tente d'envoyer la requête HTTP du webhook.
    pub async fn send_webhook(&self, task: &WebhookTask) -> Result<(), String> {
        let mut header_map = HeaderMap::new();
        header_map.insert("Content-Type", HeaderValue::from_static("application/json"));

        for (key, val) in &task.headers {
            if let (Ok(h_name), Ok(h_val)) = (
                HeaderName::from_bytes(key.as_bytes()),
                HeaderValue::from_str(val),
            ) {
                header_map.insert(h_name, h_val);
            } else {
                warn!(
                    task_id = %task.id,
                    "En-tête invalide ignoré: {key} = {val}"
                );
            }
        }

        let response = self
            .http_client
            .post(&task.url)
            .headers(header_map)
            .json(&task.payload)
            .send()
            .await
            .map_err(|e| e.to_string())?;

        let status = response.status();
        if status.is_success() {
            Ok(())
        } else {
            Err(format!("Statut HTTP non succès reçu: {status}"))
        }
    }

    /// Exécute une tentative de livraison pour une tâche donnée.
    pub async fn process_task(self: Arc<Self>, mut task: WebhookTask) {
        task.attempts += 1;
        info!(
            task_id = %task.id,
            attempt = task.attempts,
            url = %task.url,
            "Tentative d'envoi du webhook"
        );

        let _permit = match self.semaphore.acquire().await {
            Ok(permit) => permit,
            Err(e) => {
                error!(task_id = %task.id, "Échec d'acquisition du sémaphore: {e}");
                return;
            }
        };

        match self.send_webhook(&task).await {
            Ok(()) => {
                info!(
                    task_id = %task.id,
                    attempt = task.attempts,
                    "Webhook délivré avec succès"
                );
            }
            Err(err_msg) => {
                warn!(
                    task_id = %task.id,
                    attempt = task.attempts,
                    error = %err_msg,
                    "Échec d'envoi du webhook"
                );

                if task.attempts < task.max_attempts {
                    let delay = self.retry_config.calculate_delay(task.attempts);
                    info!(
                        task_id = %task.id,
                        next_attempt = task.attempts + 1,
                        delay_secs = delay.as_secs_f64(),
                        "Planification du prochain réessai"
                    );

                    let tx_clone = self.tx.clone();
                    tokio::spawn(async move {
                        tokio::time::sleep(delay).await;
                        if let Err(e) = tx_clone.send(task).await {
                            error!("Erreur lors de la réinjection dans la file: {e}");
                        }
                    });
                } else {
                    error!(
                        task_id = %task.id,
                        attempts = task.attempts,
                        "Nombre maximum de tentatives atteint. Webhook abandonné."
                    );
                }
            }
        }
    }
}

