    /// Tente de consommer un jeton. Retourne `true` si un jeton a pu être consommé.
    pub fn try_consume(&mut self, now: Instant) -> bool {
        let elapsed = now.duration_since(self.last_update).as_secs_f64();
        self.last_update = now;

        // Régénération des jetons basée sur le temps écoulé
        self.tokens = (self.tokens + elapsed * self.refill_rate_per_sec).min(self.capacity);

        if self.tokens >= 1.0 {
            self.tokens -= 1.0;
            true
        } else {
            false
        }
    }
}

/// Gestionnaire de limitation de débit en mémoire.
#[derive(Debug, Clone)]
pub struct RateLimiterState {
    buckets: Arc<Mutex<HashMap<IpAddr, TokenBucket>>>,
    capacity: f64,
    refill_rate_per_sec: f64,
}

impl RateLimiterState {
    pub fn new(capacity: f64, refill_rate_per_sec: f64) -> Self {
        Self {
            buckets: Arc::new(Mutex::new(HashMap::new())),
            capacity,
            refill_rate_per_sec,
        }
    }

    /// Vérifie et consomme un jeton pour l'adresse IP fournie.
    pub fn check_rate_limit(&self, ip: IpAddr) -> bool {
        let mut buckets = match self.buckets.lock() {
            Ok(guard) => guard,
            Err(poisoned) => poisoned.into_inner(),
        };

        let bucket = buckets
            .entry(ip)
            .or_insert_with(|| TokenBucket::new(self.capacity, self.refill_rate_per_sec));

        bucket.try_consume(Instant::now())
    }

    /// Nettoie les seaux inactifs pour éviter les fuites de mémoire.
    pub fn cleanup_inactive(&self, max_idle_secs: f64) {
        let mut buckets = match self.buckets.lock() {
            Ok(guard) => guard,
            Err(poisoned) => poisoned.into_inner(),
        };

        let now = Instant::now();
        buckets.retain(|_, bucket| {
            now.duration_since(bucket.last_update).as_secs_f64() < max_idle_secs
        });
    }
}

/// Extrait l'IP client depuis `X-Forwarded-For`, `X-Real-IP`, ou la socket de connexion.
fn extract_client_ip(headers: &HeaderMap, peer_addr: Option<SocketAddr>) -> Option<IpAddr> {
    if let Some(forwarded_for) = headers.get("x-forwarded-for").and_then(|v| v.to_str().ok()) {
        if let Some(first_ip_str) = forwarded_for.split(',').next() {
            if let Ok(ip) = first_ip_str.trim().parse::<IpAddr>() {
                return Some(ip);
            }
        }
    }

    if let Some(real_ip) = headers.get("x-real-ip").and_then(|v| v.to_str().ok()) {
        if let Ok(ip) = real_ip.trim().parse::<IpAddr>() {
            return Some(ip);
        }
    }

    peer_addr.map(|addr| addr.ip())
}

/// Middleware de limitation de débit.
async fn rate_limit_middleware(
    State(limiter): State<RateLimiterState>,
    ConnectInfo(peer_addr): ConnectInfo<SocketAddr>,
    req: Request,
    next: Next,
) -> Response {
    let client_ip = extract_client_ip(req.headers(), Some(peer_addr)).unwrap_or_else(|| peer_addr.ip());

    if !limiter.check_rate_limit(client_ip) {
        warn!(%client_ip, "Taux de requêtes dépassé (429 Too Many Requests)");
        return (
            StatusCode::TOO_MANY_REQUESTS,
            Json(json!({
                "status": "error",
                "message": "Too Many Requests: Rate limit exceeded. Please try again later."
            })),
        )
            .into_response();
    }

    next.run(req).await
}

async fn health_handler() -> impl IntoResponse {
    Json(json!({ "status": "ok" }))
}

async fn hello_handler() -> impl IntoResponse {
    Json(json!({ "message": "Bonjour ! Requête acceptée sous le quota autorisé." }))
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "axum_rate_limiter=info,tower_http=info".into()),
        )
        .init();

    // Configuration : Capacité de 5 requêtes, régénération de 1 jeton / seconde
    let limiter_state = RateLimiterState::new(5.0, 1.0);

    // Tâche de nettoyage périodique en tâche de fond (purge des IPs inactives > 5 minutes)
    let cleaner_limiter = limiter_state.clone();
    tokio::spawn(async move {
        let mut interval = tokio::time::interval(tokio::time::Duration::from_secs(60));
        loop {
            interval.tick().await;
            cleaner_limiter.cleanup_inactive(300.0);
        }
    });

    let app = Router::new()
        .route("/", get(hello_handler))
        .route("/health", get(health_handler))
        .layer(middleware::from_fn_with_state(
            limiter_state.clone(),
            rate_limit_middleware,
        ))
        .with_state(limiter_state);

    let bind_addr = SocketAddr::from(([127, 0, 0, 1], 3000));
    info!("Démarrage du serveur sur http://{}", bind_addr);

    let listener = tokio::net::TcpListener::bind(bind_addr).await?;
    axum::serve(
        listener,
        app.into_make_service_with_connect_info::<SocketAddr>(),
    )
    .await?;

    Ok(())
}

