// src/main.rs
use axum::{
    extract::{Request, State},
    http::{HeaderMap, StatusCode},
    middleware::{self, Next},
    response::{IntoResponse, Response},
    routing::get,
    Router,
};
use hmac::{Hmac, Mac};
use sha2::Sha256;
use subtle::ConstantTimeEq;
use std::sync::Arc;
use std::time::Duration;
use tracing::{error, info, warn};

type HmacSha256 = Hmac<Sha256>;

const SIGNATURE_HEADER: &str = "x-signature-sha256";
const TIMESTAMP_HEADER: &str = "x-timestamp";
const DEFAULT_SECRET: &str = "super-secret-hmac-key";
const MAX_TIME_SKEW_SECS: u64 = 300; // 5 minutes anti-rejeu

#[derive(Clone)]
pub struct AppConfig {
    pub hmac_secret: Vec<u8>,
    pub upstream_url: String,
    pub max_skew_secs: u64,
}

#[derive(Clone)]
pub struct AppState {
    pub config: Arc<AppConfig>,
    pub client: reqwest::Client,
}

#[derive(Debug)]
pub enum GatewayError {
    MissingHeader(&'static str),
    InvalidHeaderFormat(&'static str),
    ExpiredTimestamp,
    InvalidSignature,
    UpstreamError(String),
}

impl IntoResponse for GatewayError {
    fn into_response(self) -> Response {
        let (status, msg) = match self {
            GatewayError::MissingHeader(h) => {
                (StatusCode::UNAUTHORIZED, format!("Missing required header: {h}"))
            }
            GatewayError::InvalidHeaderFormat(h) => {
                (StatusCode::BAD_REQUEST, format!("Invalid header format: {h}"))
            }
            GatewayError::ExpiredTimestamp => {
                (StatusCode::UNAUTHORIZED, "Timestamp expired or out of allowed window".to_string())
            }
            GatewayError::InvalidSignature => {
                (StatusCode::UNAUTHORIZED, "Invalid HMAC-SHA256 signature".to_string())
            }
            GatewayError::UpstreamError(err) => {
                (StatusCode::BAD_GATEWAY, format!("Upstream service error: {err}"))
            }
        };

        (status, msg).into_response()
    }
}

/// Middleware de validation de signature HMAC-SHA256
async fn hmac_auth_middleware(
    State(state): State<AppState>,
    headers: HeaderMap,
    request: Request,
    next: Next,
) -> Result<Response, GatewayError> {
    // 1. Extraction de la signature
    let signature_raw = headers
        .get(SIGNATURE_HEADER)
        .ok_or(GatewayError::MissingHeader(SIGNATURE_HEADER))?
        .to_str()
        .map_err(|_| GatewayError::InvalidHeaderFormat(SIGNATURE_HEADER))?;

    // Format attendu: chaîne hexadécimale, optionnellement préfixée par "sha256="
    let signature_hex = signature_raw
        .strip_prefix("sha256=")
        .unwrap_or(signature_raw);

    let expected_sig_bytes = hex::decode(signature_hex)
        .map_err(|_| GatewayError::InvalidHeaderFormat(SIGNATURE_HEADER))?;

    // 2. Extraction et validation de l'horodatage (protection anti-rejeu)
    let timestamp_str = headers
        .get(TIMESTAMP_HEADER)
        .ok_or(GatewayError::MissingHeader(TIMESTAMP_HEADER))?
        .to_str()
        .map_err(|_| GatewayError::InvalidHeaderFormat(TIMESTAMP_HEADER))?;

    let req_timestamp: u64 = timestamp_str
        .parse()
        .map_err(|_| GatewayError::InvalidHeaderFormat(TIMESTAMP_HEADER))?;

    let current_timestamp = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or(Duration::ZERO)
        .as_secs();

    let diff = if req_timestamp > current_timestamp {
        req_timestamp - current_timestamp
    } else {
        current_timestamp - req_timestamp
    };

    if diff > state.config.max_skew_secs {
        warn!(diff, req_timestamp, current_timestamp, "Horodatage expiré");
        return Err(GatewayError::ExpiredTimestamp);
    }

    // 3. Extraction du corps de requête (buffering)
    let (parts, body) = request.into_parts();
    let body_bytes = axum::body::to_bytes(body, 10 * 1024 * 1024)
        .await
        .map_err(|e| GatewayError::UpstreamError(format!("Échec lecture du body: {e}")))?;

    // 4. Calcul HMAC-SHA256 sur timestamp + body
    let mut mac = match HmacSha256::new_from_slice(&state.config.hmac_secret) {
        Ok(m) => m,
        Err(e) => {
            error!("Clé HMAC non valide: {e}");
            return Err(GatewayError::UpstreamError("Configuration HMAC invalide".to_string()));
        }
    };

    // Charge signée : `{timestamp}.{payload}`
    mac.update(timestamp_str.as_bytes());
    mac.update(b".");
    mac.update(&body_bytes);
    let computed_sig = mac.finalize().into_bytes();

    // Comparaison en temps constant pour prévenir les attaques temporelles (timing attacks)
    if computed_sig.as_slice().ct_eq(&expected_sig_bytes).into() {
        // Reconstitution de la requête pour la suite du pipeline
        let reconstructed_request = Request::from_parts(parts, axum::body::Body::from(body_bytes));
        Ok(next.run(reconstructed_request).await)
    } else {
        warn!("Signature HMAC incorrecte");
        Err(GatewayError::InvalidSignature)
    }
}

/// Handler de proxy/routage vers le service upstream
async fn proxy_handler(
    State(state): State<AppState>,
    request: Request,
) -> Result<Response, GatewayError> {
    let method = request.method().clone();
    let uri = request.uri().clone();
    let path_and_query = uri.path_and_query().map(|pq| pq.as_str()).unwrap_or("");
    let target_url = format!("{}{}", state.config.upstream_url.trim_end_matches('/'), path_and_query);

    let (parts, body) = request.into_parts();
    let body_bytes = axum::body::to_bytes(body, 10 * 1024 * 1024)
        .await
        .map_err(|e| GatewayError::UpstreamError(format!("Erreur transfert body: {e}")))?;

    let mut upstream_req = state
        .client
        .request(method, &target_url)
        .body(body_bytes);

    for (key, value) in parts.headers.iter() {
        // Ne pas relayer l'en-tête Host d'origine pour éviter les conflits d'hôte upstream
        if key != axum::http::header::HOST {
            upstream_req = upstream_req.header(key.as_str(), value.as_bytes());
        }
    }

    info!(target = %target_url, "Routage vers le service upstream");

    let upstream_resp = upstream_req
        .send()
        .await
        .map_err(|e| GatewayError::UpstreamError(e.to_string()))?;

    let status = StatusCode::from_u16(upstream_resp.status().as_u16())
        .unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);

    let mut response_builder = Response::builder().status(status);

    for (k, v) in upstream_resp.headers() {
        response_builder = response_builder.header(k.as_str(), v.as_bytes());
    }

    let resp_bytes = upstream_resp
        .bytes()
        .await
        .map_err(|e| GatewayError::UpstreamError(e.to_string()))?;

    response_builder
        .body(axum::body::Body::from(resp_bytes))
        .map_err(|e| GatewayError::UpstreamError(format!("Erreur construction réponse: {e}")))
}

/// Route de sonde de vivacité
async fn health_check() -> impl IntoResponse {
    (StatusCode::OK, "Passerelle HMAC opérationnelle")
}

pub fn create_app(state: AppState) -> Router {
    // Routes protégées avec le middleware HMAC
    let protected_routes = Router::new()
        .fallback(proxy_handler)
        .layer(middleware::from_fn_with_state(state.clone(), hmac_auth_middleware));

    // Router global
    Router::new()
        .route("/health", get(health_check))
        .merge(protected_routes)
        .with_state(state)
}

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "axum_hmac_gateway=info,tower_http=debug".into()),
        )
        .init();

    let secret = std::env::var("HMAC_SECRET")
        .unwrap_or_else(|_| DEFAULT_SECRET.to_string());
    let upstream_url = std::env::var("UPSTREAM_URL")
        .unwrap_or_else(|_| "https://httpbin.org".to_string());
    let bind_addr = std::env::var("BIND_ADDR")
        .unwrap_or_else(|_| "0.0.0.0:3000".to_string());

    let config = Arc::new(AppConfig {
        hmac_secret: secret.into_bytes(),
        upstream_url,
        max_skew_secs: MAX_TIME_SKEW_SECS,
    });

    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(30))
        .build()
        .unwrap_or_else(|err| {
            error!("Erreur d'initialisation du client HTTP: {err}");
            std::process::exit(1);
        });

    let state = AppState { config, client };
    let app = create_app(state);

    let listener = match tokio::net::TcpListener::bind(&bind_addr).await {
        Ok(l) => l,
        Err(err) => {
            error!("Impossible d'écouter sur {bind_addr}: {err}");
            std::process::exit(1);
        }
    };

    info!("Passerelle API démarrée sur http://{}", listener.local_addr().unwrap_or_else(|_| "0.0.0.0:3000".parse().unwrap()));
    if let Err(err) = axum::serve(listener, app).await {
        error!("Erreur d'exécution du serveur: {err}");
    }
}

