    fn get_test_state() -> AppState {
        AppState {
            config: Arc::new(AppConfig {
                hmac_secret: b"test-secret".to_vec(),
                upstream_url: "https://httpbin.org".to_string(),
                max_skew_secs: 300,
            }),
            client: reqwest::Client::new(),
        }
    }

    fn generate_signature(secret: &[u8], timestamp: u64, payload: &[u8]) -> String {
        let mut mac = HmacSha256::new_from_slice(secret).expect("HMAC init failed");
        mac.update(timestamp.to_string().as_bytes());
        mac.update(b".");
        mac.update(payload);
        hex::encode(mac.finalize().into_bytes())
    }

    #[tokio::test]
    async fn test_health_check() {
        let app = create_app(get_test_state());
        let response = app
            .oneshot(
                Request::builder()
                    .uri("/health")
                    .body(axum::body::Body::empty())
                    .expect("Failed to build request"),
            )
            .await
            .expect("Failed to execute request");

        assert_eq!(response.status(), StatusCode::OK);
    }

    #[tokio::test]
    async fn test_missing_signature_rejected() {
        let app = create_app(get_test_state());
        let response = app
            .oneshot(
                Request::builder()
                    .uri("/api/data")
                    .method("POST")
                    .body(axum::body::Body::from("payload"))
                    .expect("Failed to build request"),
            )
            .await
            .expect("Failed to execute request");

        assert_eq!(response.status(), StatusCode::UNAUTHORIZED);
    }

    #[tokio::test]
    async fn test_invalid_signature_rejected() {
        let app = create_app(get_test_state());
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();

        let response = app
            .oneshot(
                Request::builder()
                    .uri("/api/data")
                    .method("POST")
                    .header(TIMESTAMP_HEADER, now.to_string())
                    .header(SIGNATURE_HEADER, "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef")
                    .body(axum::body::Body::from("payload"))
                    .expect("Failed to build request"),
            )
            .await
            .expect("Failed to execute request");

        assert_eq!(response.status(), StatusCode::UNAUTHORIZED);
    }

    #[tokio::test]
    async fn test_expired_timestamp_rejected() {
        let app = create_app(get_test_state());
        let old_time = 1000u64; // Très vieux timestamp
        let payload = b"payload";
        let sig = generate_signature(b"test-secret", old_time, payload);

        let response = app
            .oneshot(
                Request::builder()
                    .uri("/api/data")
                    .method("POST")
                    .header(TIMESTAMP_HEADER, old_time.to_string())
                    .header(SIGNATURE_HEADER, sig)
                    .body(axum::body::Body::from(&payload[..]))
                    .expect("Failed to build request"),
            )
            .await
            .expect("Failed to execute request");

        assert_eq!(response.status(), StatusCode::UNAUTHORIZED);
    }
