/// Handler de proxy/routage vers le service upstream
async fn proxy_handler(
    State(state): State<AppState>,
    request: Request,
) -> Result<Response, GatewayError> {
    let method = request.method().clone();
    let uri = request.uri().clone();
    let path_and_query = uri.path_and_query().map(|pq| pq.as_str()).unwrap_or("");
    let target_url = format!("{}{}", state.config.upstream_url.trim_end_matches('/'), path_and_query);

    let (parts, body) = request.into_parts();
    let body_bytes = axum::body::to_bytes(body, 10 * 1024 * 1024)
        .await
        .map_err(|e| GatewayError::UpstreamError(format!("Erreur transfert body: {e}")))?;

    let mut upstream_req = state
        .client
        .request(method, &target_url)
        .body(body_bytes);

    for (key, value) in parts.headers.iter() {
        // Ne pas relayer l'en-tête Host d'origine pour éviter les conflits d'hôte upstream
        if key != axum::http::header::HOST {
            upstream_req = upstream_req.header(key.as_str(), value.as_bytes());
        }
    }

    info!(target = %target_url, "Routage vers le service upstream");

    let upstream_resp = upstream_req
        .send()
        .await
        .map_err(|e| GatewayError::UpstreamError(e.to_string()))?;

    let status = StatusCode::from_u16(upstream_resp.status().as_u16())
        .unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);

    let mut response_builder = Response::builder().status(status);

    for (k, v) in upstream_resp.headers() {
        response_builder = response_builder.header(k.as_str(), v.as_bytes());
    }

    let resp_bytes = upstream_resp
        .bytes()
        .await
        .map_err(|e| GatewayError::UpstreamError(e.to_string()))?;

    response_builder
        .body(axum::body::Body::from(resp_bytes))
        .map_err(|e| GatewayError::UpstreamError(format!("Erreur construction réponse: {e}")))
}

/// Route de sonde de vivacité
async fn health_check() -> impl IntoResponse {
    (StatusCode::OK, "Passerelle HMAC opérationnelle")
}

pub fn create_app(state: AppState) -> Router {
    // Routes protégées avec le middleware HMAC
    let protected_routes = Router::new()
        .fallback(proxy_handler)
        .layer(middleware::from_fn_with_state(state.clone(), hmac_auth_middleware));

    // Router global
    Router::new()
        .route("/health", get(health_check))
        .merge(protected_routes)
        .with_state(state)
}

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "axum_hmac_gateway=info,tower_http=debug".into()),
        )
        .init();

    let secret = std::env::var("HMAC_SECRET")
        .unwrap_or_else(|_| DEFAULT_SECRET.to_string());
    let upstream_url = std::env::var("UPSTREAM_URL")
        .unwrap_or_else(|_| "https://httpbin.org".to_string());
    let bind_addr = std::env::var("BIND_ADDR")
        .unwrap_or_else(|_| "0.0.0.0:3000".to_string());

    let config = Arc::new(AppConfig {
        hmac_secret: secret.into_bytes(),
        upstream_url,
        max_skew_secs: MAX_TIME_SKEW_SECS,
    });

    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(30))
        .build()
        .unwrap_or_else(|err| {
            error!("Erreur d'initialisation du client HTTP: {err}");
            std::process::exit(1);
        });

    let state = AppState { config, client };
    let app = create_app(state);

    let listener = match tokio::net::TcpListener::bind(&bind_addr).await {
        Ok(l) => l,
        Err(err) => {
            error!("Impossible d'écouter sur {bind_addr}: {err}");
            std::process::exit(1);
        }
    };

    info!("Passerelle API démarrée sur http://{}", listener.local_addr().unwrap_or_else(|_| "0.0.0.0:3000".parse().unwrap()));
    if let Err(err) = axum::serve(listener, app).await {
        error!("Erreur d'exécution du serveur: {err}");
    }
}

