/// Génère un flux de données simulées par chunks périodiques.
///
/// Axum utilise automatiquement le transfert 'chunked' (`Transfer-Encoding: chunked`)
/// en HTTP/1.1 lorsqu'un `axum::body::Body` est créé à partir d'un `Stream`
/// sans en-tête `Content-Length`.
fn create_simulated_stream(
    media_label: &'static str,
    chunk_size: usize,
    interval: Duration,
    total_chunks: Option<u64>,
) -> Pin<Box<dyn Stream<Item = Result<Bytes, Infallible>> + Send>> {
    let tick_stream = tokio_stream::wrappers::IntervalStream::new(tokio::time::interval(interval));

    let stream = StreamExt::enumerate(tick_stream).map(move |(index, _)| {
        let seq = index as u64;
        let mut buffer = Vec::with_capacity(chunk_size);

        let header_text = format!("[{} chunk #{:04}] ", media_label, seq);
        buffer.extend_from_slice(header_text.as_bytes());

        // Remplissage avec des octets simulés (motif cyclique)
        let fill_byte = ((seq % 26) as u8) + b'A';
        if buffer.len() < chunk_size {
            let padding = chunk_size - buffer.len();
            buffer.resize(buffer.len() + padding, fill_byte);
        }

        // Saut de ligne pour lisibilité si inspecté avec curl
        if let Some(last) = buffer.last_mut() {
            *last = b'\n';
        }

        info!(
            chunk = seq,
            media = media_label,
            size = buffer.len(),
            "Envoi d'un chunk de données"
        );
        Ok::<Bytes, Infallible>(Bytes::from(buffer))
    });

    if let Some(limit) = total_chunks {
        Box::pin(stream.take(limit as usize))
    } else {
        Box::pin(stream)
    }
}

/// Endpoint simulant un flux audio en direct (ex: PCM brut / radio)
/// Débit simulé : ~4 Ko par tranche de 250ms (~16 Ko/s)
async fn stream_audio_handler() -> Response {
    let chunk_size = 4096;
    let interval = Duration::from_millis(250);
    let stream = create_simulated_stream("AUDIO", chunk_size, interval, None);

    let mut headers = HeaderMap::new();
    headers.insert(header::CONTENT_TYPE, HeaderValue::from_static("audio/raw"));
    headers.insert(
        header::CACHE_CONTROL,
        HeaderValue::from_static("no-cache, no-store, must-revalidate"),
    );
    headers.insert(header::CONNECTION, HeaderValue::from_static("keep-alive"));

    (headers, Body::from_stream(stream)).into_response()
}

/// Endpoint simulant un flux vidéo (ex: fragments MPEG / transport stream)
/// Débit simulé : ~64 Ko toutes les 100ms (~640 Ko/s)
async fn stream_video_handler(Query(params): Query<StreamParams>) -> Response {
    let chunk_size = 65536;
    let interval = Duration::from_millis(100);

    // Calcul du nombre de chunks si un paramètre ?seconds=N est spécifié
    let total_chunks = params.seconds.map(|sec| (sec * 1000) / 100);
    let stream = create_simulated_stream("VIDEO", chunk_size, interval, total_chunks);

    let mut headers = HeaderMap::new();
    headers.insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("video/mp2t"),
    );
    headers.insert(
        header::CACHE_CONTROL,
        HeaderValue::from_static("no-cache, no-store, must-revalidate"),
    );
    headers.insert(header::CONNECTION, HeaderValue::from_static("keep-alive"));

    (headers, Body::from_stream(stream)).into_response()
}

