// src/main.rs
use futures::{SinkExt, StreamExt};
use std::collections::HashMap;
use std::sync::Arc;
use thiserror::Error;
use tokio::net::{TcpListener, TcpStream, ToSocketAddrs};
use tokio::sync::Mutex;
use tokio_util::codec::{LinesCodec, LinesCodecError, Framed};
use tracing::{error, info, level_filters::LevelFilter};
use tracing_subscriber::EnvFilter;

/// Erreurs possibles émises par le client.
#[derive(Debug, Error)]
pub enum ClientError {
    #[error("Erreur réseau I/O : {0}")]
    Io(#[from] std::io::Error),

    #[error("Erreur de décodage de flux : {0}")]
    Codec(#[from] LinesCodecError),

    #[error("Connexion interrompue par le serveur")]
    ConnectionClosed,

    #[error("Erreur renvoyée par le serveur : {0}")]
    Server(String),

    #[error("Erreur de protocole ou réponse inattendue : {0}")]
    Protocol(String),
}

/// Réponses possibles du protocole textuel.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RedisResponse {
    Ok(String),
    Bulk(Option<String>),
}

/// Client TCP asynchrone implémentant les commandes de type Redis.
pub struct RedisClient {
    framed: Framed<TcpStream, LinesCodec>,
}

impl RedisClient {
    /// Établit une connexion TCP vers l'adresse donnée et configure le framing de lignes.
    pub async fn connect<A: ToSocketAddrs>(addr: A) -> Result<Self, ClientError> {
        let stream = TcpStream::connect(addr).await?;
        let framed = Framed::new(stream, LinesCodec::new());
        Ok(Self { framed })
    }

    /// Envoie une commande brute sur une ligne et attend la réponse unique.
    pub async fn send_command(&mut self, command: &str) -> Result<RedisResponse, ClientError> {
        self.framed.send(command).await?;

        let response = match self.framed.next().await {
            Some(line) => line?,
            None => return Err(ClientError::ConnectionClosed),
        };

        if let Some(err_msg) = response.strip_prefix('-') {
            return Err(ClientError::Server(err_msg.to_string()));
        }

        if let Some(ok_msg) = response.strip_prefix('+') {
            return Ok(RedisResponse::Ok(ok_msg.to_string()));
        }

        if response == "$-1" || response == "(nil)" {
            return Ok(RedisResponse::Bulk(None));
        }

        if let Some(val) = response.strip_prefix('$') {
            return Ok(RedisResponse::Bulk(Some(val.to_string())));
        }

        Ok(RedisResponse::Ok(response))
    }

    /// Commande PING avec message optionnel.
    pub async fn ping(&mut self, message: Option<&str>) -> Result<String, ClientError> {
        let cmd = match message {
            Some(msg) => format!("PING {}", msg),
            None => "PING".to_string(),
        };

        match self.send_command(&cmd).await? {
            RedisResponse::Ok(val) => Ok(val),
            RedisResponse::Bulk(Some(val)) => Ok(val),
            RedisResponse::Bulk(None) => Err(ClientError::Protocol("Réponse inattendue pour PING".into())),
        }
    }

    /// Commande SET pour affecter une valeur à une clé.
    pub async fn set(&mut self, key: &str, value: &str) -> Result<(), ClientError> {
        let cmd = format!("SET {} {}", key, value);
        match self.send_command(&cmd).await? {
            RedisResponse::Ok(_) => Ok(()),
            RedisResponse::Bulk(_) => Err(ClientError::Protocol("Format inattendu pour la confirmation SET".into())),
        }
    }

    /// Commande GET pour récupérer la valeur associée à une clé.
    pub async fn get(&mut self, key: &str) -> Result<Option<String>, ClientError> {
        let cmd = format!("GET {}", key);
        match self.send_command(&cmd).await? {
            RedisResponse::Bulk(val) => Ok(val),
            RedisResponse::Ok(val) => Ok(Some(val)),
        }
    }
}

/// Serveur TCP de démonstration répondant aux commandes du protocole Redis simplifié.
async fn run_mock_server(listener: TcpListener) {
    let db = Arc::new(Mutex::new(HashMap::<String, String>::new()));

    loop {
        let (stream, _) = match listener.accept().await {
            Ok(res) => res,
            Err(e) => {
                error!("Erreur lors de l'acceptation de connexion : {}", e);
                break;
            }
        };

        let db = Arc::clone(&db);
        tokio::spawn(async move {
            let mut framed = Framed::new(stream, LinesCodec::new());

            while let Some(Ok(line)) = framed.next().await {
                let parts: Vec<&str> = line.split_whitespace().collect();
                if parts.is_empty() {
                    let _ = framed.send("-ERR empty command").await;
                    continue;
                }

                let command = parts[0].to_uppercase();
                match command.as_str() {
                    "PING" => {
                        let response = if parts.len() > 1 {
                            format!("+{}", parts[1..].join(" "))
                        } else {
                            "+PONG".to_string()
                        };
                        if framed.send(&response).await.is_err() {
                            break;
                        }
                    }
                    "SET" => {
                        if parts.len() < 3 {
                            let _ = framed.send("-ERR wrong number of arguments for 'set' command").await;
                            continue;
                        }
                        let key = parts[1].to_string();
                        let value = parts[2..].join(" ");
                        {
                            let mut map = db.lock().await;
                            map.insert(key, value);
                        }
                        if framed.send("+OK").await.is_err() {
                            break;
                        }
                    }
                    "GET" => {
                        if parts.len() != 2 {
                            let _ = framed.send("-ERR wrong number of arguments for 'get' command").await;
                            continue;
                        }
                        let key = parts[1];
                        let map = db.lock().await;
                        let reply = match map.get(key) {
                            Some(val) => format!("${}", val),
                            None => "$-1".to_string(),
                        };
                        if framed.send(&reply).await.is_err() {
                            break;
                        }
                    }
                    _ => {
                        if framed.send(format!("-ERR unknown command '{}'", command)).await.is_err() {
                            break;
                        }
                    }
                }
            }
        });
    }
}

