    #[prost(string, tag = "1")]
    pub reply: String,
    #[prost(uint64, tag = "2")]
    pub server_timestamp: u64,
    #[prost(uint64, tag = "3")]
    pub received_original_timestamp: u64,
}

// ==============================================================================
// 2. Gestion du cadrage binaire gRPC (gRPC Framing Wire Format)
//
// Un frame gRPC comprend :
// - 1 octet : Drapeau de compression (0 = non compressé)
// - 4 octets (Big-Endian) : Longueur du message sérialisé
// - N octets : Payload Protobuf sérialisé
// ==============================================================================

pub fn encode_grpc_frame<M: Message>(msg: &M) -> Result<Bytes, Box<dyn Error + Send + Sync>> {
    let mut payload = BytesMut::new();
    msg.encode(&mut payload)?;

    let mut frame = BytesMut::with_capacity(5 + payload.len());
    frame.put_u8(0); // 0 = sans compression
    frame.put_u32(payload.len() as u32);
    frame.put(payload);

    Ok(frame.freeze())
}

pub fn decode_grpc_frame<M: Message + Default>(mut buf: Bytes) -> Result<M, Box<dyn Error + Send + Sync>> {
    if buf.len() < 5 {
        return Err("Payload gRPC trop court pour contenir l'en-tête de cadrage (5 octets requis)".into());
    }

    let is_compressed = buf.get_u8();
    if is_compressed != 0 {
        return Err("La compression gRPC n'est pas supportée dans cette implémentation minimale".into());
    }

    let length = buf.get_u32() as usize;
    if buf.remaining() < length {
        return Err("Payload incomplet par rapport à la taille indiquée dans l'en-tête gRPC".into());
    }

    let message_bytes = buf.copy_to_bytes(length);
    let message = M::decode(message_bytes)?;
    Ok(message)
}

// ==============================================================================
// 3. Serveur gRPC simulé en pur HTTP/2
// ==============================================================================

pub async fn run_server(listener: TcpListener) -> Result<(), Box<dyn Error + Send + Sync>> {
    loop {
        let (tcp_stream, remote_addr) = match listener.accept().await {
            Ok(res) => res,
            Err(e) => {
                error!("Erreur lors de l'acceptation de la connexion TCP: {:?}", e);
                continue;
            }
        };

        tokio::spawn(async move {
            if let Err(e) = handle_connection(tcp_stream, remote_addr).await {
                warn!("Connexion fermée avec erreur pour {}: {:?}", remote_addr, e);
            }
        });
    }
}

async fn handle_connection(
    tcp_stream: TcpStream,
    remote_addr: SocketAddr,
) -> Result<(), Box<dyn Error + Send + Sync>> {
    let mut h2_server = h2::server::handshake(tcp_stream).await?;
    info!("Handshake HTTP/2 réussi avec {}", remote_addr);

    while let Some(result) = h2_server.accept().await {
        let (request, respond) = match result {
            Ok(pair) => pair,
            Err(e) => {
                warn!("Erreur lors de l'acceptation d'un stream HTTP/2: {:?}", e);
                break;
            }
        };

        tokio::spawn(async move {
            if let Err(e) = handle_grpc_stream(request, respond).await {
                error!("Erreur lors du traitement du stream gRPC: {:?}", e);
            }
        });
    }

    Ok(())
}

async fn handle_grpc_stream(
    request: Request<h2::RecvStream>,
    mut respond: h2::server::SendResponse<Bytes>,
) -> Result<(), Box<dyn Error + Send + Sync>> {
    let path = request.uri().path().to_string();
    info!("Requête gRPC reçue: Path = {}", path);

    let mut body = request.into_body();
    let mut accumulated_bytes = BytesMut::new();

    while let Some(chunk) = body.data().await {
        let data = chunk?;
        accumulated_bytes.put(data);
        body.flow_control().release_capacity(accumulated_bytes.len())?;
    }

    // Routage du service
    match path.as_str() {
        "/echo.EchoService/Echo" => {
            let echo_req: EchoRequest = match decode_grpc_frame(accumulated_bytes.freeze()) {
                Ok(req) => req,
                Err(e) => {
                    warn!("Échec du décodage gRPC: {:?}", e);
                    send_grpc_error(&mut respond, 3, "Payload Protobuf invalide").await?;
                    return Ok(());
                }
            };

            info!(
                "Message Echo reçu: \"{}\" (timestamp: {})",
                echo_req.message, echo_req.timestamp
            );

            let now = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .map(|d| d.as_secs())
                .unwrap_or(0);

            let echo_resp = EchoResponse {
                reply: format!("Écho simulé: {}", echo_req.message),
                server_timestamp: now,
                received_original_timestamp: echo_req.timestamp,
            };

            let response_frame = encode_grpc_frame(&echo_resp)?;

            // Construction de la réponse HTTP/2
            let response = Response::builder()
                .status(StatusCode::OK)
                .header(http::header::CONTENT_TYPE, "application/grpc")
                .body(())?;

            let mut send_stream = respond.send_response(response, false)?;
            send_stream.send_data(response_frame, false)?;

            // Envoi des trailers gRPC indiquant le succès
            let mut trailers = HeaderMap::new();
            trailers.insert("grpc-status", HeaderValue::from_static("0"));
            trailers.insert("grpc-message", HeaderValue::from_static("OK"));
            send_stream.send_trailers(trailers)?;
        }
        _ => {
            warn!("Méthode inconnue demandée: {}", path);
            send_grpc_error(&mut respond, 12, "Service non implémenté").await?;
        }
    }

    Ok(())
}

async fn send_grpc_error(
    respond: &mut h2::server::SendResponse<Bytes>,
    grpc_status: i32,
    grpc_message: &str,
) -> Result<(), Box<dyn Error + Send + Sync>> {
    let response = Response::builder()
        .status(StatusCode::OK)
        .header(http::header::CONTENT_TYPE, "application/grpc")
        .body(())?;

    let mut send_stream = respond.send_response(response, false)?;
    let mut trailers = HeaderMap::new();
    trailers.insert("grpc-status", HeaderValue::from_str(&grpc_status.to_string())?);
    trailers.insert("grpc-message", HeaderValue::from_str(grpc_message)?);
    send_stream.send_trailers(trailers)?;
    Ok(())
}

// ==============================================================================
// 4. Client gRPC HTTP/2 de démonstration
// ==============================================================================

async fn run_demo_client(addr: SocketAddr) -> Result<(), Box<dyn Error + Send + Sync>> {
    tokio::time::sleep(tokio::time::Duration::from_millis(50)).await;

    let tcp_stream = TcpStream::connect(addr).await?;
    let (mut client, h2_conn) = h2::client::handshake(tcp_stream).await?;

    tokio::spawn(async move {
        if let Err(e) = h2_conn.await {
            error!("Erreur dans la boucle de connexion client HTTP/2: {:?}", e);
        }
    });

    let uri = format!("http://{}/echo.EchoService/Echo", addr);
    let request = Request::builder()
        .method(http::Method::POST)
        .uri(uri)
        .header(http::header::CONTENT_TYPE, "application/grpc")
        .header(http::header::TE, "trailers")
        .body(())?;

    let echo_req = EchoRequest {
        message: "Bonjour depuis Tokio et HTTP/2 pur !".to_string(),
        timestamp: SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0),
    };

    let encoded_req = encode_grpc_frame(&echo_req)?;
    let (response_future, mut send_stream) = client.send_request(request, false)?;

    send_stream.send_data(encoded_req, true)?;

    let response = response_future.await?;
    info!("Client: Statut HTTP reçu: {}", response.status());

    let mut resp_body = response.into_body();
    let mut resp_bytes = BytesMut::new();

    while let Some(chunk) = resp_body.data().await {
        let data = chunk?;
        resp_bytes.put(data);
    }

    if let Some(trailers) = resp_body.trailers().await? {
        if let Some(status) = trailers.get("grpc-status") {
            info!("Client: Trailer grpc-status = {:?}", status.to_str()?);
        }
    }

    let decoded_resp: EchoResponse = decode_grpc_frame(resp_bytes.freeze())?;
    info!("Client: Réponse reçue avec succès : {:#?}", decoded_resp);

    Ok(())
}

// ==============================================================================
// 5. Point d'entrée principal (Main)
// ==============================================================================

#[tokio::main]
async fn main() -> Result<(), Box<dyn Error + Send + Sync>> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
        .init();

    // Port 0 pour allouer automatiquement un port libre
    let listener = TcpListener::bind("127.0.0.1:0").await?;
    let local_addr = listener.local_addr()?;
    info!("Serveur gRPC HTTP/2 démarré sur : {}", local_addr);

    // Démarrage du serveur en tâche d'arrière-plan
    let server_task = tokio::spawn(async move {
        if let Err(e) = run_server(listener).await {
            error!("Erreur critique serveur : {:?}", e);
        }
    });

    // Exécution d'un appel client pour valider le fonctionnement bout-en-bout
    info!("Démarrage du client de test...");
    run_demo_client(local_addr).await?;

    info!("Validation bout-en-bout réussie ! Arrêt du serveur de test.");
    server_task.abort();

    Ok(())
}

