pub fn create_router() -> Router {
    // Configuration de la couche de compression tower-http
    // Active dynamiquement la compression gzip et zstd selon l'en-tête `Accept-Encoding`.
    let compression_layer = CompressionLayer::new()
        .gzip(true)
        .zstd(true);

    Router::new()
        .route("/health", get(health_handler))
        .route("/data", get(data_handler))
        .route("/echo", get(echo_handler))
        .route("/text", get(text_handler))
        .layer(compression_layer)
        .layer(TraceLayer::new_for_http())
}

async fn health_handler() -> impl IntoResponse {
    let payload = HealthStatus {
        status: "ok",
        service: "axum-dynamic-compression",
        supported_encodings: &["gzip", "zstd", "identity"],
    };
    (StatusCode::OK, Json(payload))
}

async fn data_handler() -> impl IntoResponse {
    // Génère un large ensemble de données structurées JSON pour démontrer le ratio de compression
    let items: Vec<serde_json::Value> = (1..=200)
        .map(|id| {
            serde_json::json!({
                "id": id,
                "uuid": format!("550e8400-e29b-41d4-a716-{:012x}", id),
                "title": format!("Élément volumineux de test n°{}", id),
                "description": "Ce contenu textuel répétitif et représentatif sert à démontrer l'efficacité des algorithmes gzip et zstd.",
                "tags": ["axum", "compression", "gzip", "zstd", "rust", "performance"],
                "active": id % 2 == 0
            })
        })
        .collect();

    (
        StatusCode::OK,
        [(header::CACHE_CONTROL, "no-transform")],
        Json(serde_json::json!({ "total": items.len(), "items": items })),
    )
}

async fn echo_handler(Query(params): Query<EchoQuery>) -> impl IntoResponse {
