            .get(header::CONTENT_ENCODING)
            .expect("Expected Content-Encoding header");
        assert_eq!(encoding, "zstd");

        let body_bytes = response
            .into_body()
            .collect()
            .await
            .expect("Failed to collect body")
            .to_bytes();

        let decompressed =
            zstd::decode_all(&body_bytes[..]).expect("Failed to decompress zstd stream");
        let decompressed_str =
            String::from_utf8(decompressed).expect("Invalid utf8 after decompression");

        assert!(decompressed_str.contains("Rust Axum microservice"));
    }
}

