// Implémentation de IntoResponse pour convertir AppError en RFC 7807
// ============================================================================
impl IntoResponse for AppError {
    fn into_response(self) -> Response {
        let (status, problem) = match self {
            AppError::NotFound(resource) => {
                let status = StatusCode::NOT_FOUND;
                let problem = ProblemDetails::new(status, "Resource Not Found", "https://api.example.com/errors/not-found")
                    .with_detail(format!("La ressource demandée n'existe pas : {resource}"));
                (status, problem)
            }
            AppError::ValidationError(violations) => {
                let status = StatusCode::UNPROCESSABLE_ENTITY;
                let problem = ProblemDetails::new(status, "Validation Failed", "https://api.example.com/errors/validation-failed")
                    .with_detail("Un ou plusieurs champs du corps de la requête sont invalides.")
                    .with_invalid_params(violations);
                (status, problem)
            }
            AppError::Internal(err) => {
                // Journalisation serveur de l'erreur brute pour l'audit et le débogage
                tracing::error!(error = %err, "Erreur interne non interceptée");

                let status = StatusCode::INTERNAL_SERVER_ERROR;
                let problem = ProblemDetails::new(status, "Internal Server Error", "https://api.example.com/errors/internal-error")
                    .with_detail("Une erreur interne inattendue s'est produite.");
                (status, problem)
            }
        };

        let body = match serde_json::to_string(&problem) {
            Ok(json) => json,
            Err(e) => {
                tracing::error!(error = %e, "Échec de sérialisation du ProblemDetails");
                r#"{"type":"about:blank","title":"Internal Server Error","status":500}"#.to_string()
            }
        };

        (
            status,
            [(header::CONTENT_TYPE, "application/problem+json")],
            body,
        )
            .into_response()
    }
}

