```rust
// src/main.rs
use anyhow::{Context, Result};
use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use socket2::{Domain, Protocol, Socket, Type};
use std::collections::HashMap;
use std::net::{Ipv4Addr, SocketAddr, SocketAddrV4};
use std::sync::Arc;
use std::time::Duration;
use tokio::net::UdpSocket;
use tokio::sync::{broadcast, RwLock};
use tokio::time::{interval, Instant};
use tracing::{error, info, warn};
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt};
use uuid::Uuid;

const DEFAULT_MULTICAST_ADDR: Ipv4Addr = Ipv4Addr::new(239, 255, 42, 99);
const DEFAULT_MULTICAST_PORT: u16 = 7654;
const HEARTBEAT_INTERVAL: Duration = Duration::from_secs(3);
const PEER_TIMEOUT: Duration = Duration::from_secs(9);
const CLEANUP_INTERVAL: Duration = Duration::from_secs(3);

/// Format des messages échangés sur le canal multicast.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", content = "payload")]
pub enum DiscoveryMessage {
    /// Annonce de présence émise au lancement et périodiquement en heartbeat.
    Announce {
        node_id: Uuid,
        service_name: String,
        service_port: u16,
        metadata: HashMap<String, String>,
        timestamp: DateTime<Utc>,
    },
    /// Requête invitant tous les pairs du réseau à renvoyer immédiatement une annonce.
    Query {
        node_id: Uuid,
    },
    /// Notification de déconnexion propre.
    Goodbye {
        node_id: Uuid,
    },
}

/// Informations sur un pair enregistré.
#[derive(Debug, Clone)]
pub struct PeerEntry {
    pub node_id: Uuid,
    pub service_name: String,
    pub service_port: u16,
    pub ip: Ipv4Addr,
    pub metadata: HashMap<String, String>,
    pub last_seen: Instant,
}

/// Registre partagé des pairs découverts.
#[derive(Clone, Default)]
pub struct PeerRegistry {
    peers: Arc<RwLock<HashMap<Uuid, PeerEntry>>>,
}

impl PeerRegistry {
    pub fn new() -> Self {
        Self {
            peers: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    pub async fn upsert(&self, entry: PeerEntry) {
        let mut map = self.peers.write().await;
        let is_new = !map.contains_key(&entry.node_id);
        if is_new {
            info!(
                node_id = %entry.node_id,
                service = %entry.service_name,
                endpoint = format!("{}:{}", entry.ip, entry.service_port),
                "Nouveau pair découvert !"
            );
        }
        map.insert(entry.node_id, entry);
    }

    pub async fn remove(&self, node_id: &Uuid) {
        let mut map = self.peers.write().await;
        if let Some(removed) = map.remove(node_id) {
            info!(
                node_id = %removed.node_id,
                service = %removed.service_name,
                "Pair déconnecté proprement (Goodbye reçu)."
            );
        }
    }

    pub async fn cleanup_stale(&self, timeout: Duration) {
        let mut map = self.peers.write().await;
        let now = Instant::now();
        map.retain(|id, peer| {
            let is_alive = now.duration_since(peer.last_seen) < timeout;
            if !is_alive {
                warn!(
                    node_id = %id,
                    service = %peer.service_name,
                    "Pair expiré (heartbeat manquant) retiré du registre."
                );
            }
            is_alive
        });
    }

    pub async fn active_peers(&self) -> Vec<PeerEntry> {
        let map = self.peers.read().await;
        map.values().cloned().collect()
    }
}

/// Crée et configure un socket UDP capable de recevoir des paquets multicast
/// même si plusieurs instances s'exécutent sur la même machine.
fn create_multicast_receiver(addr: Ipv4Addr, port: u16) -> Result<UdpSocket> {
    let socket = Socket::new(Domain::IPV4, Type::DGRAM, Some(Protocol::UDP))
        .context("Échec de création du socket UDP")?;

    socket
        .set_reuse_address(true)
        .context("Échec de set_reuse_address")?;

    #[cfg(unix)]
    {
        socket
            .set_reuse_port(true)
            .context("Échec de set_reuse_port")?;
    }

    socket.set_nonblocking(true)?;

    let bind_addr = SocketAddrV4::new(Ipv4Addr::UNSPECIFIED, port);
    socket
        .bind(&bind_addr.into())
        .context("Échec de bind sur le port multicast")?;

    socket
        .join_multicast_v4(&addr, &Ipv4Addr::UNSPECIFIED)
        .context("Impossible d'adhérer au groupe multicast")?;

    let std_socket: std::net::UdpSocket = socket.into();
    let tokio_socket = UdpSocket::from_std(std_socket)?;
    Ok(tokio_socket)
}

/// Service principal de découverte réseau UDP multicast.
pub struct DiscoveryService {
    node_id: Uuid,
    service_name: String,
    service_port: u16,
    multicast_addr: SocketAddrV4,
    registry: PeerRegistry,
    metadata: HashMap<String, String>,
}

impl DiscoveryService {
    pub fn new(
        service_name: impl Into<String>,
        service_port: u16,
        multicast_ip: Ipv4Addr,
        multicast_port: u16,
    ) -> Self {
        Self {
            node_id: Uuid::new_v4(),
            service_name: service_name.into(),
            service_port,
            multicast_addr: SocketAddrV4::new(multicast_ip, multicast_port),
            registry: PeerRegistry::new(),
            metadata: HashMap::new(),
        }
    }

    pub fn with_metadata(mut self, key: impl Into<String>, val: impl Into<String>) -> Self {
        self.metadata.insert(key.into(), val.into());
        self
    }

    pub fn node_id(&self) -> Uuid {
        self.node_id
    }

    pub fn registry(&self) -> PeerRegistry {
        self.registry.clone()
    }

    fn build_announce_message(&self) -> DiscoveryMessage {
        DiscoveryMessage::Announce {
            node_id: self.node_id,
            service_name: self.service_name.clone(),
            service_port: self.service_port,
            metadata: self.metadata.clone(),
            timestamp: Utc::now(),
        }
    }

    pub async fn run(self, mut shutdown_rx: broadcast::Receiver<()>) -> Result<()> {
        let target_addr = SocketAddr::V4(self.multicast_addr);

        // Socket dédié à l'écoute des paquets multicast
        let recv_socket = Arc::new(create_multicast_receiver(
            *self.multicast_addr.ip(),
            self.multicast_addr.port(),
        )?);

        // Socket dédié à l'envoi de datagrammes
        let send_socket = Arc::new(
            UdpSocket::bind("0.0.0.0:0")
                .await
                .context("Impossible de lier le socket d'envoi UDP")?,
        );

        info!(
            node_id = %self.node_id,
            service = %self.service_name,
            multicast_group = %self.multicast_addr,
            "Démarrage du service de découverte local"
        );

        // Émission initiale d'une Query pour interroger les pairs existants
        let query_msg = DiscoveryMessage::Query {
            node_id: self.node_id,
        };
        if let Ok(bytes) = serde_json::to_vec(&query_msg) {
            let _ = send_socket.send_to(&bytes, target_addr).await;
        }

        // Première annonce
        let announce_msg = self.build_announce_message();
        if let Ok(bytes) = serde_json::to_vec(&announce_msg) {
            let _ = send_socket.send_to(&bytes, target_addr).await;
        }

        let mut heartbeat_ticker = interval(HEARTBEAT_INTERVAL);
        let mut cleanup_ticker = interval(CLEANUP_INTERVAL);

        let mut buf = vec![0u8; 65535];

        loop {
            tokio::select! {
                // Réception des paquets multicast
                recv_res = recv_socket.recv_from(&mut buf) => {
                    match recv_res {
                        Ok((size, remote_addr)) => {
                            if let Ok(msg) = serde_json::from_slice::<DiscoveryMessage>(&buf[..size]) {
                                self.handle_message(msg, remote_addr, &send_socket, target_addr).await;
                            }
                        }
                        Err(e) => {
                            error!("Erreur lors de la réception UDP : {:?}", e);
                        }
                    }
                }

                // Tâche d'émission périodique de l'annonce (Heartbeat)
                _ = heartbeat_ticker.tick() => {
                    let msg = self.build_announce_message();
                    match serde_json::to_vec(&msg) {
                        Ok(bytes) => {
                            if let Err(e) = send_socket.send_to(&bytes, target_addr).await {
                                warn!("Impossible d'envoyer le heartbeat multicast : {:?}", e);
                            }
                        }
                        Err(e) => error!("Erreur de sérialisation heartbeat : {:?}", e),
                    }
                }

                // Tâche de nettoyage des pairs obsolètes
                _ = cleanup_ticker.tick() => {
                    self.registry.cleanup_stale(PEER_TIMEOUT).await;
                }

                // Signal d'arrêt (Graceful Shutdown)
                _ = shutdown_rx.recv() => {
                    info!("Arrêt demandé. Diffusion du message Goodbye...");
                    let goodbye_msg = DiscoveryMessage::Goodbye { node_id: self.node_id };
                    if let Ok(bytes) = serde_json::to_vec(&goodbye_msg) {
                        let _ = send_socket.send_to(&bytes, target_addr).await;
                    }
                    info!("Arrêt du service terminé proprement.");
                    break;
                }
            }
        }

        Ok(())
    }

    async fn handle_message(
        &self,
        msg: DiscoveryMessage,
        remote_addr: SocketAddr,
        send_socket: &UdpSocket,
        target_addr: SocketAddr,
    ) {
        match msg {
            DiscoveryMessage::Announce {
                node_id,
                service_name,
                service_port,
                metadata,
                ..
            } => {
                // Ignorer nos propres annonces
                if node_id == self.node_id {
                    return;
                }

                let peer_ip = match remote_addr {
                    SocketAddr::V4(ipv4) => *ipv4.ip(),
                    SocketAddr::V6(_) => Ipv4Addr::UNSPECIFIED,
                };

                let entry = PeerEntry {
                    node_id,
                    service_name,
                    service_port,
                    ip: peer_ip,
                    metadata,
                    last_seen: Instant::now(),
                };

                self.registry.upsert(entry).await;
            }

            DiscoveryMessage::Query { node_id } => {
                // Si un autre pair demande qui est en ligne, on lui répond
                if node_id != self.node_id {
                    let response = self.build_announce_message();
                    if let Ok(bytes) = serde_json::to_vec(&response) {
                        let _ = send_socket.send_to(&bytes, target_addr).await;
                    }
                }
            }

            DiscoveryMessage::Goodbye { node_id } => {
                if node_id != self.node_id {
                    self.registry.remove(&node_id).await;
                }
            }
        }
    }
}

