/// Erreurs métier et techniques du worker.
#[derive(Debug, Error)]
pub enum WorkerError {
    #[error("Erreur de requête HTTP: {0}")]
    Http(#[from] reqwest::Error),

    #[error("Erreur lors de la désérialisation du payload: {0}")]
    Json(#[from] serde_json::Error),

    #[error("Réponse de l'API avec statut d'erreur: {0}")]
    ApiStatus(reqwest::StatusCode),
}

/// Structure modèle des données consommées depuis l'API distante.
#[derive(Debug, Clone, Deserialize)]
pub struct ApiResponseItem {
    pub id: u64,
    pub title: String,
    pub completed: bool,
}

/// Configuration du worker périodique.
#[derive(Debug, Clone)]
pub struct WorkerConfig {
    pub endpoint_url: String,
    pub poll_interval: Duration,
    pub request_timeout: Duration,
}

impl Default for WorkerConfig {
    fn default() -> Self {
        Self {
            endpoint_url: "https://jsonplaceholder.typicode.com/todos/1".to_string(),
            poll_interval: Duration::from_secs(5),
            request_timeout: Duration::from_secs(10),
        }
    }
}

