    /// Crée une nouvelle instance de `PeriodicWorker`.
    pub fn new(
        config: WorkerConfig,
        shutdown_rx: watch::Receiver<bool>,
    ) -> Result<Self, WorkerError> {
        let client = reqwest::Client::builder()
            .timeout(config.request_timeout)
            .connect_timeout(Duration::from_secs(5))
            .build()?;

        Ok(Self {
            config,
            client,
            shutdown_rx,
        })
    }

    /// Lance la boucle de traitement asynchrone jusqu'à réception du signal d'arrêt.
    pub async fn run(mut self) {
        info!(
            endpoint = %self.config.endpoint_url,
            interval_secs = self.config.poll_interval.as_secs(),
            "Démarrage de la boucle de sondage périodique"
        );

        let mut ticker = interval(self.config.poll_interval);
        // Évite de déclencher des rafales de requêtes si une requête a pris du retard
        ticker.set_missed_tick_behavior(MissedTickBehavior::Delay);

        loop {
            tokio::select! {
                biased;

                // Vérification prioritaire du signal d'arrêt gracieux
                change_res = self.shutdown_rx.changed() => {
                    match change_res {
                        Ok(()) => {
                            if *self.shutdown_rx.borrow() {
                                info!("Signal d'arrêt détecté par le worker. Arrêt gracieux en cours...");
                                break;
                            }
                        }
                        Err(_) => {
                            // Le sender a été libéré, on arrête le worker
                            warn!("Canal de notification d'arrêt fermé. Arrêt du worker.");
                            break;
                        }
                    }
                }

                // Déclenchement périodique
                _ = ticker.tick() => {
                    info!("Tick d'intervalle atteint : interrogation du service distant...");
                    if let Err(err) = self.poll_and_process().await {
                        error!(error = %err, "Échec lors de l'exécution de la tâche périodique");
                    }
                }
            }
        }

        // Nettoyage et fin gracieuse
        self.cleanup().await;
        info!("Worker arrêté avec succès.");
    }

    /// Exécute la requête HTTP distante et applique le traitement métier.
    async fn poll_and_process(&self) -> Result<(), WorkerError> {
        let response = self.client.get(&self.config.endpoint_url).send().await?;

        let status = response.status();
        if !status.is_success() {
            return Err(WorkerError::ApiStatus(status));
        }

        let item: ApiResponseItem = response.json().await?;
        info!(
            id = item.id,
            title = %item.title,
            completed = item.completed,
            "Données reçues et traitées avec succès"
        );

        Ok(())
    }

    /// Effectue les opérations de nettoyage nécessaires lors de l'arrêt du worker.
    async fn cleanup(&self) {
        info!("Clôture des connexions résiduelles et libération des ressources...");
        // Simulation d'une libération de ressources asynchrone (ex: flush buffer, commit offset, etc.)
        tokio::time::sleep(Duration::from_millis(200)).await;
        info!("Nettoyage terminé.");
    }
}

/// Écoute les signaux d'arrêt du système d'exploitation (SIGINT / SIGTERM).
async fn wait_for_shutdown_signal() {
    let ctrl_c = async {
        if let Err(err) = signal::ctrl_c().await {
            error!(error = %err, "Erreur lors de l'écoute du signal Ctrl+C");
        }
    };

    #[cfg(unix)]
    let terminate = async {
        match signal::unix::signal(signal::unix::SignalKind::terminate()) {
            Ok(mut sig) => {
                sig.recv().await;
            }
            Err(err) => {
                error!(error = %err, "Erreur lors de l'écoute du signal SIGTERM");
            }
        }
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {
            info!("Signal d'interruption (Ctrl+C / SIGINT) reçu.");
        }
        _ = terminate => {
            info!("Signal de terminaison (SIGTERM) reçu.");
        }
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialisation du système de logs structurés
    tracing_subscriber::registry()
        .with(EnvFilter::try_from_default_env().unwrap_or_else(|_| "info".into()))
        .with(tracing_subscriber::fmt::layer())
        .init();

    info!("Initialisation de l'application Worker");

    // Canal de notification d'arrêt (watch)
    let (shutdown_tx, shutdown_rx) = watch::channel(false);

    // Initialisation du worker
    let config = WorkerConfig::default();
    let worker = match PeriodicWorker::new(config, shutdown_rx) {
        Ok(w) => w,
        Err(err) => {
            error!(error = %err, "Impossible d'instancier le worker");
            return Err(err.into());
        }
    };

    // Lancement du worker dans une tâche asynchrone dédiée
    let worker_handle = tokio::spawn(async move {
        worker.run().await;
    });

    // Attente d'un signal système dans la tâche principale
    wait_for_shutdown_signal().await;

    info!("Propagation de la demande d'arrêt gracieux...");
    let _ = shutdown_tx.send(true);

    // Attente de la fin de l'exécution du worker avec un timeout de sécurité
    let shutdown_timeout = Duration::from_secs(15);
    match tokio::time::timeout(shutdown_timeout, worker_handle).await {
        Ok(join_res) => {
            if let Err(join_err) = join_res {
                error!(error = %join_err, "La tâche worker a paniqué ou s'est terminée prématurément");
            } else {
                info!("Tâche worker terminée proprement.");
            }
        }
        Err(_) => {
            warn!(
                timeout_secs = shutdown_timeout.as_secs(),
                "Le délai imparti pour l'arrêt gracieux est dépassé, arrêt forcé."
            );
        }
    }

    info!("Arrêt complet de l'application.");
    Ok(())
}

