// src/main.rs
use axum::{
    body::{to_bytes, Body},
    extract::{Path as AxumPath, State},
    http::{HeaderMap, HeaderName, HeaderValue, Method, StatusCode, Uri},
    response::{IntoResponse, Response},
    routing::{get, post},
    Json, Router,
};
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    net::SocketAddr,
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
    time::Duration,
};
use tokio::sync::RwLock;
use tower_http::trace::TraceLayer;
use tracing::{info, warn};
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt};

// ============================================================================
// Types & Modèles de Données
// ============================================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RequestMatcher {
    /// Méthode HTTP attendue (GET, POST, etc.) ou None pour n'importe quelle méthode.
    #[serde(default)]
    pub method: Option<String>,
    /// Chemin attendu (supporte égalité exacte ou joker '*' en fin de chemin).
    pub path: String,
    /// En-têtes HTTP obligatoires pour matcher.
    #[serde(default)]
    pub headers: Option<HashMap<String, String>>,
    /// Paramètres de requête (query string) obligatoires pour matcher.
    #[serde(default)]
    pub query_params: Option<HashMap<String, String>>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ResponseDefinition {
    /// Code HTTP renvoyé (ex: 200, 201, 404, 500). Valeur par défaut : 200.
    #[serde(default = "default_status")]
    pub status: u16,
    /// En-têtes HTTP à renvoyer dans la réponse mockée.
    #[serde(default)]
    pub headers: Option<HashMap<String, String>>,
    /// Corps de la réponse (peut être un objet JSON, tableau, chaîne ou null).
    #[serde(default = "default_body")]
    pub body: serde_json::Value,
    /// Délai artificiel en millisecondes pour simuler la latence réseau.
    #[serde(default)]
    pub delay_ms: Option<u64>,
}

fn default_status() -> u16 {
    200
}

fn default_body() -> serde_json::Value {
    serde_json::json!({})
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MockRule {
    /// Identifiant unique du mock (généré automatiquement si absent).
    pub id: String,
    /// Nom ou description optionnelle pour faciliter l'identification.
    #[serde(default)]
    pub name: Option<String>,
    /// Priorité d'évaluation (les règles à priorité plus élevée sont testées en premier).
    #[serde(default)]
    pub priority: i32,
    /// Critères de correspondance de la requête.
    pub request: RequestMatcher,
    /// Définition de la réponse simulée.
    pub response: ResponseDefinition,
    /// Nombre de fois où ce mock a été exécuté.
    #[serde(default)]
    pub hit_count: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RecordedRequest {
    pub id: String,
    pub timestamp: String,
    pub method: String,
    pub uri: String,
    pub path: String,
    pub headers: HashMap<String, String>,
    pub body: Option<String>,
    pub matched_mock_id: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ServerConfig {
    /// URL du serveur amont optionnel pour le mode enregistrement / proxy.
    #[serde(default)]
    pub upstream_url: Option<String>,
    /// Si vrai et qu'un serveur amont est configuré, enregistre les réponses inconnues comme nouveaux mocks.
    #[serde(default = "default_record_unmatched")]
    pub record_unmatched: bool,
}

fn default_record_unmatched() -> bool {
    true
}

impl Default for ServerConfig {
    fn default() -> Self {
        Self {
            upstream_url: None,
            record_unmatched: true,
        }
    }
}

pub struct AppState {
    pub mocks: RwLock<Vec<MockRule>>,
    pub history: RwLock<Vec<RecordedRequest>>,
    pub config: RwLock<ServerConfig>,
    pub client: reqwest::Client,
    pub request_counter: AtomicU64,
}

// ============================================================================
// Gestion des Erreurs
// ============================================================================

#[derive(Debug)]
pub enum AppError {
    NotFound(String),
    BadRequest(String),
    Internal(String),
    UpstreamError(String),
}

impl IntoResponse for AppError {
    fn into_response(self) -> Response {
        let (status, msg) = match self {
            AppError::NotFound(m) => (StatusCode::NOT_FOUND, m),
            AppError::BadRequest(m) => (StatusCode::BAD_REQUEST, m),
            AppError::Internal(m) => (StatusCode::INTERNAL_SERVER_ERROR, m),
            AppError::UpstreamError(m) => (StatusCode::BAD_GATEWAY, m),
        };

        let body = Json(serde_json::json!({
            "error": true,
            "message": msg
        }));

        (status, body).into_response()
    }
}

// ============================================================================
// Logique de Matching
// ============================================================================

impl MockRule {
    pub fn matches(&self, method: &str, path: &str, query: &HashMap<String, String>, headers: &HeaderMap) -> bool {
        // 1. Vérification méthode HTTP
        if let Some(ref expected_method) = self.request.method {
            if !expected_method.eq_ignore_ascii_case(method) {
                return false;
            }
        }

        // 2. Vérification chemin (path exact ou wildcard à la fin)
        let expected_path = &self.request.path;
        if expected_path.ends_with('*') {
            let prefix = &expected_path[..expected_path.len() - 1];
            if !path.starts_with(prefix) {
                return false;
            }
        } else if expected_path != path {
            return false;
        }

        // 3. Vérification des paramètres query
        if let Some(ref required_query) = self.request.query_params {
            for (k, v) in required_query {
                match query.get(k) {
                    Some(actual_v) if actual_v == v => continue,
                    _ => return false,
                }
            }
        }

        // 4. Vérification des en-têtes
        if let Some(ref required_headers) = self.request.headers {
            for (k, v) in required_headers {
                match headers.get(k) {
                    Some(header_val) => {
                        if let Ok(str_val) = header_val.to_str() {
                            if !str_val.eq_ignore_ascii_case(v) {
                                return false;
                            }
                        } else {
                            return false;
                        }
                    }
                    None => return false,
                }
            }
        }

        true
    }
}

// ============================================================================
// Handlers d'Administration (/__admin/...)
// ============================================================================

async fn admin_health(State(state): State<Arc<AppState>>) -> impl IntoResponse {
    let mocks = state.mocks.read().await;
    let history = state.history.read().await;
    let config = state.config.read().await;

    Json(serde_json::json!({
        "status": "ok",
        "total_mocks": mocks.len(),
        "total_recorded_requests": history.len(),
        "upstream_url": config.upstream_url,
        "record_unmatched": config.record_unmatched,
    }))
}

async fn admin_list_mocks(State(state): State<Arc<AppState>>) -> impl IntoResponse {
    let mocks = state.mocks.read().await;
    Json(mocks.clone())
}

#[derive(Deserialize)]
#[serde(untagged)]
enum MockInput {
    Single(MockRuleInput),
    Multiple(Vec<MockRuleInput>),
}

#[derive(Deserialize)]
struct MockRuleInput {
    pub id: Option<String>,
    pub name: Option<String>,
    pub priority: Option<i32>,
    pub request: RequestMatcher,
    pub response: ResponseDefinition,
}

async fn admin_create_mocks(
    State(state): State<Arc<AppState>>,
    Json(payload): Json<MockInput>,
) -> Result<impl IntoResponse, AppError> {
    let mut mocks = state.mocks.write().await;
    let mut created_ids = Vec::new();

    let items = match payload {
        MockInput::Single(rule) => vec![rule],
        MockInput::Multiple(rules) => rules,
    };

    for item in items {
        let id = item.id.unwrap_or_else(|| {
            let counter = state.request_counter.fetch_add(1, Ordering::SeqCst);
            format!("mock_{}_{}", std::process::id(), counter)
        });

        // Supprime une ancienne règle de même ID si elle existe déjà
        mocks.retain(|m| m.id != id);

        let rule = MockRule {
            id: id.clone(),
            name: item.name,
            priority: item.priority.unwrap_or(0),
            request: item.request,
            response: item.response,
            hit_count: 0,
        };

        mocks.push(rule);
        created_ids.push(id);
    }

    // Réordonne par priorité décroissante
    mocks.sort_by(|a, b| b.priority.cmp(&a.priority));

    Ok((
        StatusCode::CREATED,
        Json(serde_json::json!({
            "message": "Mock(s) enregistré(s) avec succès",
            "registered_ids": created_ids
        })),
    ))
}

async fn admin_get_mock(
    State(state): State<Arc<AppState>>,
    AxumPath(id): AxumPath<String>,
) -> Result<impl IntoResponse, AppError> {
    let mocks = state.mocks.read().await;
    mocks
        .iter()
        .find(|m| m.id == id)
        .cloned()
        .map(Json)
        .ok_or_else(|| AppError::NotFound(format!("Mock '{}' non trouvé", id)))
}

async fn admin_delete_mock(
    State(state): State<Arc<AppState>>,
    AxumPath(id): AxumPath<String>,
) -> Result<impl IntoResponse, AppError> {
    let mut mocks = state.mocks.write().await;
    let initial_len = mocks.len();
    mocks.retain(|m| m.id != id);

    if mocks.len() < initial_len {
        Ok(Json(serde_json::json!({
            "message": format!("Mock '{}' supprimé", id)
        })))
    } else {
        Err(AppError::NotFound(format!("Mock '{}' introuvable", id)))
    }
}

async fn admin_clear_mocks(State(state): State<Arc<AppState>>) -> impl IntoResponse {
    let mut mocks = state.mocks.write().await;
    let count = mocks.len();
    mocks.clear();
    Json(serde_json::json!({
        "message": format!("{} règle(s) de mock supprimée(s)", count)
    }))
}

async fn admin_get_history(State(state): State<Arc<AppState>>) -> impl IntoResponse {
    let history = state.history.read().await;
    Json(history.clone())
}

async fn admin_clear_history(State(state): State<Arc<AppState>>) -> impl IntoResponse {
    let mut history = state.history.write().await;
    let count = history.len();
    history.clear();
    Json(serde_json::json!({
        "message": format!("Historique de {} requête(s) vidé", count)
    }))
}

#[derive(Deserialize)]
struct FilePersistenceRequest {
    pub file_path: String,
}

async fn admin_export_to_file(
    State(state): State<Arc<AppState>>,
    Json(payload): Json<FilePersistenceRequest>,
) -> Result<impl IntoResponse, AppError> {
    let mocks = state.mocks.read().await;
    let serialized = serde_json::to_string_pretty(&*mocks)
        .map_err(|e| AppError::Internal(format!("Erreur de sérialisation JSON: {}", e)))?;

    tokio::fs::write(&payload.file_path, serialized)
        .await
        .map_err(|e| AppError::Internal(format!("Impossible d'écrire le fichier '{}': {}", payload.file_path, e)))?;

    Ok(Json(serde_json::json!({
        "message": format!("Mocks exportés avec succès dans '{}'", payload.file_path),
        "count": mocks.len()
    })))
}

async fn admin_import_from_file(
    State(state): State<Arc<AppState>>,
    Json(payload): Json<FilePersistenceRequest>,
) -> Result<impl IntoResponse, AppError> {
    let content = tokio::fs::read_to_string(&payload.file_path)
        .await
        .map_err(|e| AppError::BadRequest(format!("Impossible de lire le fichier '{}': {}", payload.file_path, e)))?;

    let imported_mocks: Vec<MockRule> = serde_json::from_str(&content)
        .map_err(|e| AppError::BadRequest(format!("Format JSON invalide dans le fichier : {}", e)))?;

    let mut mocks = state.mocks.write().await;
    for new_mock in imported_mocks {
        mocks.retain(|m| m.id != new_mock.id);
        mocks.push(new_mock);
    }
    mocks.sort_by(|a, b| b.priority.cmp(&a.priority));

    Ok(Json(serde_json::json!({
        "message": format!("Mocks importés avec succès depuis '{}'", payload.file_path),
        "total_active_mocks": mocks.len()
    })))
}

async fn admin_update_config(
    State(state): State<Arc<AppState>>,
    Json(new_config): Json<ServerConfig>,
) -> impl IntoResponse {
    let mut config = state.config.write().await;
    *config = new_config.clone();
    Json(serde_json::json!({
        "message": "Configuration mise à jour",
        "current_config": *config
    }))
}

// ============================================================================
// Handler Principal (Dispatch des Mocks & Proxy Enregistreur)
// ============================================================================

async fn handle_mock_dispatch(
    State(state): State<Arc<AppState>>,
    method: Method,
    uri: Uri,
    headers: HeaderMap,
    body: Body,
) -> Result<Response, AppError> {
    let req_counter = state.request_counter.fetch_add(1, Ordering::SeqCst);
    let req_id = format!("req_{}_{}", std::process::id(), req_counter);
    let path = uri.path().to_string();
    let query_string = uri.query().unwrap_or("").to_string();

    // Analyse de la chaîne de requête (query string)
    let query_map: HashMap<String, String> = form_urlencoded::parse(query_string.as_bytes())
        .into_owned()
        .collect();

    // Lecture du corps de la requête (limité à 10 Mo par sécurité)
    let bytes = to_bytes(body, 10 * 1024 * 1024)
        .await
        .map_err(|e| AppError::BadRequest(format!("Impossible de lire le corps de la requête : {}", e)))?;
    let body_str = String::from_utf8(bytes.to_vec()).ok();

    // Extraction des en-têtes sous forme de dictionnaire lisible
    let mut header_map = HashMap::new();
    for (name, val) in &headers {
        if let Ok(v) = val.to_str() {
            header_map.insert(name.as_str().to_string(), v.to_string());
        }
    }

    let mut matched_mock_response: Option<(ResponseDefinition, String)> = None;

    // Recherche d'un mock correspondant
    {
        let mut mocks = state.mocks.write().await;
        for mock in mocks.iter_mut() {
            if mock.matches(method.as_str(), &path, &query_map, &headers) {
                mock.hit_count += 1;
                matched_mock_response = Some((mock.response.clone(), mock.id.clone()));
                break;
            }
        }
    }

    let (response_def, matched_id) = match matched_mock_response {
        Some((resp, id)) => (Some(resp), Some(id)),
        None => (None, None),
    };

    // Enregistrement dans l'historique des requêtes
    let record = RecordedRequest {
        id: req_id,
        timestamp: chrono_now_string(),
        method: method.to_string(),
        uri: uri.to_string(),
        path: path.clone(),
        headers: header_map,
        body: body_str.clone(),
        matched_mock_id: matched_id.clone(),
    };

    {
        let mut history = state.history.write().await;
        // Conserve les 500 dernières requêtes pour éviter la surcharge mémoire
        if history.len() >= 500 {
            history.remove(0);
        }
        history.push(record);
    }

    // Cas 1 : Un mock a été trouvé -> Rejouer la réponse
    if let Some(resp) = response_def {
        info!(
            method = %method,
            path = %path,
            mock_id = ?matched_id,
            status = resp.status,
            "Mock trouvé et rejoué"
        );

        if let Some(delay) = resp.delay_ms {
            if delay > 0 {
                tokio::time::sleep(Duration::from_millis(delay)).await;
            }
        }

        let mut res = Response::builder();
        if let Ok(status) = StatusCode::from_u16(resp.status) {
            res = res.status(status);
        } else {
            res = res.status(StatusCode::OK);
        }

        // Injection des en-têtes configurés
        let mut has_content_type = false;
        if let Some(resp_headers) = resp.headers {
            for (k, v) in resp_headers {
                if k.eq_ignore_ascii_case("content-type") {
                    has_content_type = true;
                }
                if let (Ok(h_name), Ok(h_val)) = (
                    HeaderName::try_from(k.as_str()),
                    HeaderValue::try_from(v.as_str()),
                ) {
                    res = res.header(h_name, h_val);
                }
            }
        }

        // Si le body est un objet JSON et qu'aucun Content-Type n'est explicité, on ajoute application/json
        if !has_content_type {
            res = res.header(
                HeaderName::from_static("content-type"),
                HeaderValue::from_static("application/json"),
            );
        }

        let body_payload = match &resp.body {
            serde_json::Value::String(s) => s.clone(),
            other => other.to_string(),
        };

        return res
            .body(Body::from(body_payload))
            .map_err(|e| AppError::Internal(format!("Erreur de construction de réponse : {}", e)));
    }

    // Cas 2 : Aucun mock ne correspond -> Tentative de relais amont (Upstream proxy / record)
    let upstream_opt = { state.config.read().await.upstream_url.clone() };

    if let Some(upstream_base) = upstream_opt {
        info!(
            method = %method,
            path = %path,
            upstream = %upstream_base,
            "Aucun mock direct: relais vers le serveur amont"
        );

        let target_url = format!(
            "{}{}{}{}",
            upstream_base.trim_end_matches('/'),
            path,
            if query_string.is_empty() { "" } else { "?" },
            query_string
        );

        let reqwest_method = reqwest::Method::from_bytes(method.as_str().as_bytes())
            .map_err(|e| AppError::BadRequest(format!("Méthode HTTP invalide : {}", e)))?;

        let mut upstream_req = state.client.request(reqwest_method, &target_url);

        // Transmission des headers (hors hôte)
        for (h_key, h_val) in &headers {
            if !h_key.as_str().eq_ignore_ascii_case("host") {
                upstream_req = upstream_req.header(h_key.as_str(), h_val.as_bytes());
            }
        }

        if !bytes.is_empty() {
            upstream_req = upstream_req.body(bytes.to_vec());
        }

        let upstream_res = upstream_req
            .send()
            .await
            .map_err(|e| AppError::UpstreamError(format!("Échec de communication avec l'amont : {}", e)))?;

        let status_u16 = upstream_res.status().as_u16();
        let upstream_headers = upstream_res.headers().clone();
        let body_bytes = upstream_res
            .bytes()
            .await
            .map_err(|e| AppError::UpstreamError(format!("Erreur lors de la lecture du corps amont : {}", e)))?;

        // Analyse du corps reçu pour tenter une désérialisation JSON
        let body_value = serde_json::from_slice::<serde_json::Value>(&body_bytes).unwrap_or_else(|_| {
            let text = String::from_utf8_lossy(&body_bytes).to_string();
            serde_json::Value::String(text)
        });

        // Enregistrement automatique en tant que règle de mock si l'option est activée
        let should_record = { state.config.read().await.record_unmatched };
        if should_record {
            let auto_mock_id = format!("recorded_{}_{}", std::process::id(), state.request_counter.fetch_add(1, Ordering::SeqCst));
            let mut recorded_headers = HashMap::new();
            if let Some(ct) = upstream_headers.get("content-type") {
                if let Ok(ct_str) = ct.to_str() {
                    recorded_headers.insert("content-type".to_string(), ct_str.to_string());
                }
            }

            let new_rule = MockRule {
                id: auto_mock_id.clone(),
                name: Some(format!("Auto-recorded for {} {}", method, path)),
                priority: 0,
                request: RequestMatcher {
                    method: Some(method.to_string()),
                    path: path.clone(),
                    headers: None,
                    query_params: if query_map.is_empty() { None } else { Some(query_map) },
                },
                response: ResponseDefinition {
                    status: status_u16,
                    headers: Some(recorded_headers),
                    body: body_value,
                    delay_ms: None,
                },
                hit_count: 1,
            };

            info!(mock_id = %auto_mock_id, path = %path, "Nouvelle réponse amont enregistrée comme mock");
            let mut mocks = state.mocks.write().await;
            mocks.push(new_rule);
        }

        // Renvoi de la réponse amont au client
        let mut client_res = Response::builder();
        if let Ok(st) = StatusCode::from_u16(status_u16) {
            client_res = client_res.status(st);
        }

        for (h_name, h_val) in upstream_headers {
            if let Some(name) = h_name {
                client_res = client_res.header(name, h_val);
            }
        }

        return client_res
            .body(Body::from(body_bytes))
            .map_err(|e| AppError::Internal(format!("Erreur lors du retour de la réponse amont : {}", e)));
    }

    // Cas 3 : Ni mock ni amont configuré -> HTTP 404 informatif
    warn!(method = %method, path = %path, "Aucun mock trouvé et aucun serveur amont configuré");
    let available_mocks_count = state.mocks.read().await.len();

    let err_json = serde_json::json!({
        "error": "Not Found",
        "message": "Aucun mock ne correspond à cette requête et aucun relais amont n'est configuré.",
        "request": {
            "method": method.to_string(),
            "path": path,
            "query": query_string,
        },
        "help": {
            "active_mock_rules_count": available_mocks_count,
            "register_mock_url": "POST /__admin/mocks",
            "documentation": "Consulter CAHIER_DES_CHARGES.md pour les exemples de payload."
        }
    });

    Ok((StatusCode::NOT_FOUND, Json(err_json)).into_response())
}

fn chrono_now_string() -> String {
    // Horodatage simplifié sans dépendance lourde supplémentaire
    use std::time::{SystemTime, UNIX_EPOCH};
    let duration = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default();
    format!("{}.{:03}Z", duration.as_secs(), duration.subsec_millis())
}

// ============================================================================
// Initialisation & Point d'entrée
// ============================================================================

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialisation du traçage / logs
    tracing_subscriber::registry()
        .with(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "axum_mock_server=debug,tower_http=info".into()),
        )
        .with(tracing_subscriber::fmt::layer())
        .init();

    // Configuration par variables d'environnement
    let host = std::env::var("HOST").unwrap_or_else(|_| "0.0.0.0".to_string());
    let port: u16 = std::env::var("PORT")
        .ok()
        .and_then(|p| p.parse().ok())
        .unwrap_or(8080);
    let upstream_env = std::env::var("UPSTREAM_URL").ok();
    let initial_mocks_path = std::env::var("MOCKS_FILE").ok();

    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(30))
        .build()?;

    let mut initial_mocks = Vec::new();

    // Chargement initial optionnel depuis un fichier JSON
    if let Some(ref path) = initial_mocks_path {
        info!("Chargement des règles initiales depuis le fichier : {}", path);
        match tokio::fs::read_to_string(path).await {
            Ok(content) => match serde_json::from_str::<Vec<MockRule>>(&content) {
                Ok(rules) => {
                    info!("{} règle(s) chargée(s) avec succès.", rules.len());
                    initial_mocks = rules;
                }
                Err(e) => {
                    warn!("Échec de désérialisation du fichier '{}': {}", path, e);
                }
            },
            Err(e) => {
                warn!("Impossible d'ouvrir le fichier '{}': {}", path, e);
            }
        }
    }

    // Ajout d'un mock d'exemple si la liste est vide
    if initial_mocks.is_empty() {
        initial_mocks.push(MockRule {
            id: "sample_greeting".to_string(),
            name: Some("Exemple de mock de bienvenue".to_string()),
            priority: 0,
            request: RequestMatcher {
                method: Some("GET".to_string()),
                path: "/api/hello".to_string(),
                headers: None,
                query_params: None,
            },
            response: ResponseDefinition {
                status: 200,
                headers: Some(HashMap::from([(
                    "X-Mock-Engine".to_string(),
                    "Axum-Mock-Server".to_string(),
                )])),
                body: serde_json::json!({
                    "status": "success",
                    "message": "Bienvenue sur le serveur de mock HTTP Axum !",
                    "timestamp": chrono_now_string()
                }),
                delay_ms: Some(10),
            },
            hit_count: 0,
        });
    }

    let shared_state = Arc::new(AppState {
        mocks: RwLock::new(initial_mocks),
        history: RwLock::new(Vec::new()),
        config: RwLock::new(ServerConfig {
            upstream_url: upstream_env,
            record_unmatched: true,
        }),
        client,
        request_counter: AtomicU64::new(1),
    });

    let app = create_app(shared_state);

    let bind_addr: SocketAddr = format!("{}:{}", host, port).parse()?;
    info!("Démarrage du serveur de mock Axum sur http://{}", bind_addr);
    info!("Interface d'administration accessible sur http://{}/__admin/health", bind_addr);

    let listener = tokio::net::TcpListener::bind(bind_addr).await?;
    axum::serve(listener, app).await?;

    Ok(())
}

pub fn create_app(shared_state: Arc<AppState>) -> Router {
    let admin_router = Router::new()
        .route("/health", get(admin_health))
        .route("/mocks", get(admin_list_mocks).post(admin_create_mocks).delete(admin_clear_mocks))
        .route("/mocks/{id}", get(admin_get_mock).delete(admin_delete_mock))
        .route("/history", get(admin_get_history).delete(admin_clear_history))
        .route("/export", post(admin_export_to_file))
        .route("/import", post(admin_import_from_file))
        .route("/config", post(admin_update_config));

    Router::new()
        .nest("/__admin", admin_router)
        .fallback(handle_mock_dispatch)
        .layer(TraceLayer::new_for_http())
        .with_state(shared_state)
}

