            id: "1".into(),
            name: None,
            priority: 0,
            request: RequestMatcher {
                method: Some("POST".into()),
                path: "/users".into(),
                headers: Some(HashMap::from([("authorization".into(), "bearer token".into())])),
                query_params: Some(HashMap::from([("role".into(), "admin".into())])),
            },
            response: ResponseDefinition {
                status: 201,
                headers: None,
                body: serde_json::json!({}),
                delay_ms: None,
            },
            hit_count: 0,
        };

        let mut headers = HeaderMap::new();
        headers.insert("authorization", "bearer token".parse().unwrap());
        let mut query = HashMap::new();
        query.insert("role".into(), "admin".into());

        assert!(rule.matches("POST", "/users", &query, &headers));
        assert!(!rule.matches("GET", "/users", &query, &headers));
