#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RequestMatcher {
    /// Méthode HTTP attendue (GET, POST, etc.) ou None pour n'importe quelle méthode.
    #[serde(default)]
    pub method: Option<String>,
    /// Chemin attendu (supporte égalité exacte ou joker '*' en fin de chemin).
    pub path: String,
    /// En-têtes HTTP obligatoires pour matcher.
    #[serde(default)]
    pub headers: Option<HashMap<String, String>>,
    /// Paramètres de requête (query string) obligatoires pour matcher.
    #[serde(default)]
    pub query_params: Option<HashMap<String, String>>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ResponseDefinition {
    /// Code HTTP renvoyé (ex: 200, 201, 404, 500). Valeur par défaut : 200.
    #[serde(default = "default_status")]
    pub status: u16,
    /// En-têtes HTTP à renvoyer dans la réponse mockée.
    #[serde(default)]
    pub headers: Option<HashMap<String, String>>,
    /// Corps de la réponse (peut être un objet JSON, tableau, chaîne ou null).
    #[serde(default = "default_body")]
    pub body: serde_json::Value,
    /// Délai artificiel en millisecondes pour simuler la latence réseau.
    #[serde(default)]
    pub delay_ms: Option<u64>,
}

fn default_status() -> u16 {
    200
}

fn default_body() -> serde_json::Value {
    serde_json::json!({})
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MockRule {
    /// Identifiant unique du mock (généré automatiquement si absent).
    pub id: String,
    /// Nom ou description optionnelle pour faciliter l'identification.
    #[serde(default)]
    pub name: Option<String>,
    /// Priorité d'évaluation (les règles à priorité plus élevée sont testées en premier).
    #[serde(default)]
    pub priority: i32,
    /// Critères de correspondance de la requête.
    pub request: RequestMatcher,
    /// Définition de la réponse simulée.
    pub response: ResponseDefinition,
    /// Nombre de fois où ce mock a été exécuté.
    #[serde(default)]
    pub hit_count: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RecordedRequest {
    pub id: String,
    pub timestamp: String,
    pub method: String,
    pub uri: String,
    pub path: String,
    pub headers: HashMap<String, String>,
    pub body: Option<String>,
    pub matched_mock_id: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ServerConfig {
    /// URL du serveur amont optionnel pour le mode enregistrement / proxy.
    #[serde(default)]
    pub upstream_url: Option<String>,
    /// Si vrai et qu'un serveur amont est configuré, enregistre les réponses inconnues comme nouveaux mocks.
    #[serde(default = "default_record_unmatched")]
    pub record_unmatched: bool,
}

fn default_record_unmatched() -> bool {
    true
}

impl Default for ServerConfig {
    fn default() -> Self {
        Self {
            upstream_url: None,
            record_unmatched: true,
        }
    }
}

pub struct AppState {
    pub mocks: RwLock<Vec<MockRule>>,
    pub history: RwLock<Vec<RecordedRequest>>,
    pub config: RwLock<ServerConfig>,
    pub client: reqwest::Client,
    pub request_counter: AtomicU64,
}

// ============================================================================
// Gestion des Erreurs
// ============================================================================

#[derive(Debug)]
pub enum AppError {
    NotFound(String),
    BadRequest(String),
    Internal(String),
    UpstreamError(String),
}

impl IntoResponse for AppError {
    fn into_response(self) -> Response {
        let (status, msg) = match self {
            AppError::NotFound(m) => (StatusCode::NOT_FOUND, m),
            AppError::BadRequest(m) => (StatusCode::BAD_REQUEST, m),
            AppError::Internal(m) => (StatusCode::INTERNAL_SERVER_ERROR, m),
            AppError::UpstreamError(m) => (StatusCode::BAD_GATEWAY, m),
        };

        let body = Json(serde_json::json!({
            "error": true,
            "message": msg
        }));

        (status, body).into_response()
    }
}

// ============================================================================
// Logique de Matching
// ============================================================================

impl MockRule {
    pub fn matches(&self, method: &str, path: &str, query: &HashMap<String, String>, headers: &HeaderMap) -> bool {
        // 1. Vérification méthode HTTP
        if let Some(ref expected_method) = self.request.method {
            if !expected_method.eq_ignore_ascii_case(method) {
                return false;
            }
        }

        // 2. Vérification chemin (path exact ou wildcard à la fin)
        let expected_path = &self.request.path;
        if expected_path.ends_with('*') {
            let prefix = &expected_path[..expected_path.len() - 1];
            if !path.starts_with(prefix) {
                return false;
            }
        } else if expected_path != path {
            return false;
        }

        // 3. Vérification des paramètres query
        if let Some(ref required_query) = self.request.query_params {
            for (k, v) in required_query {
                match query.get(k) {
                    Some(actual_v) if actual_v == v => continue,
                    _ => return false,
                }
            }
        }

        // 4. Vérification des en-têtes
        if let Some(ref required_headers) = self.request.headers {
            for (k, v) in required_headers {
                match headers.get(k) {
                    Some(header_val) => {
                        if let Ok(str_val) = header_val.to_str() {
                            if !str_val.eq_ignore_ascii_case(v) {
                                return false;
                            }
                        } else {
                            return false;
                        }
                    }
                    None => return false,
                }
            }
        }

        true
    }
}

