// src/main.rs
use axum::{
    extract::{Query, State},
    http::StatusCode,
    response::{IntoResponse, Response},
    routing::get,
    Json, Router,
};
use geojson::{Feature, FeatureCollection, GeoJson, Geometry, Value};
use serde::{Deserialize, Serialize};
use std::{net::SocketAddr, sync::Arc};
use tower_http::trace::TraceLayer;
use tracing::{error, info};
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt};

/// Représente les paramètres de requête de filtrage spatial par Bounding Box.
/// Format attendu : ?bbox=min_lon,min_lat,max_lon,max_lat ou via paramètres individuels.
#[derive(Debug, Deserialize)]
pub struct BboxParams {
    pub bbox: Option<String>,
    pub min_lon: Option<f64>,
    pub min_lat: Option<f64>,
    pub max_lon: Option<f64>,
    pub max_lat: Option<f64>,
}

/// Boîte englobante structurée (WGS84).
#[derive(Debug, Clone, Copy)]
pub struct BoundingBox {
    pub min_lon: f64,
    pub min_lat: f64,
    pub max_lon: f64,
    pub max_lat: f64,
}

impl BoundingBox {
    pub fn new(min_lon: f64, min_lat: f64, max_lon: f64, max_lat: f64) -> Result<Self, ApiError> {
        if min_lon > max_lon {
            return Err(ApiError::InvalidBoundingBox(
                "min_lon ne peut pas être supérieur à max_lon".to_string(),
            ));
        }
        if min_lat > max_lat {
            return Err(ApiError::InvalidBoundingBox(
                "min_lat ne peut pas être supérieur à max_lat".to_string(),
            ));
        }
        if !(-180.0..=180.0).contains(&min_lon) || !(-180.0..=180.0).contains(&max_lon) {
            return Err(ApiError::InvalidBoundingBox(
                "La longitude doit être comprise entre -180.0 et 180.0".to_string(),
            ));
        }
        if !(-90.0..=90.0).contains(&min_lat) || !(-90.0..=90.0).contains(&max_lat) {
            return Err(ApiError::InvalidBoundingBox(
                "La latitude doit être comprise entre -90.0 et 90.0".to_string(),
            ));
        }

        Ok(Self {
            min_lon,
            min_lat,
            max_lon,
            max_lat,
        })
    }

    /// Vérifie l'intersection avec la Bounding Box d'une géométrie.
    pub fn intersects(&self, other: &BoundingBox) -> bool {
        self.min_lon <= other.max_lon
            && self.max_lon >= other.min_lon
            && self.min_lat <= other.max_lat
            && self.max_lat >= other.min_lat
    }
}

/// Erreurs standardisées de l'API.
#[derive(Debug)]
pub enum ApiError {
    InvalidBoundingBox(String),
}

#[derive(Serialize)]
struct ErrorResponse {
    error: String,
    code: u16,
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let (status, message) = match self {
            ApiError::InvalidBoundingBox(msg) => (StatusCode::BAD_REQUEST, msg),
        };

        let body = Json(ErrorResponse {
            error: message,
            code: status.as_u16(),
        });

        (status, body).into_response()
    }
}

/// État partagé de l'application contenant les données en mémoire.
#[derive(Clone)]
pub struct AppState {
