// src/main.rs
use axum::{
    extract::{Query, State},
    http::StatusCode,
    response::{IntoResponse, Response},
    routing::get,
    Json, Router,
};
use geojson::{Feature, FeatureCollection, GeoJson, Geometry, Value};
use serde::{Deserialize, Serialize};
use std::{net::SocketAddr, sync::Arc};
use tower_http::trace::TraceLayer;
use tracing::{error, info};
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt};

/// Représente les paramètres de requête de filtrage spatial par Bounding Box.
/// Format attendu : ?bbox=min_lon,min_lat,max_lon,max_lat ou via paramètres individuels.
#[derive(Debug, Deserialize)]
pub struct BboxParams {
    pub bbox: Option<String>,
    pub min_lon: Option<f64>,
    pub min_lat: Option<f64>,
    pub max_lon: Option<f64>,
    pub max_lat: Option<f64>,
}

/// Boîte englobante structurée (WGS84).
#[derive(Debug, Clone, Copy)]
pub struct BoundingBox {
    pub min_lon: f64,
    pub min_lat: f64,
    pub max_lon: f64,
    pub max_lat: f64,
}

impl BoundingBox {
    pub fn new(min_lon: f64, min_lat: f64, max_lon: f64, max_lat: f64) -> Result<Self, ApiError> {
        if min_lon > max_lon {
            return Err(ApiError::InvalidBoundingBox(
                "min_lon ne peut pas être supérieur à max_lon".to_string(),
            ));
        }
        if min_lat > max_lat {
            return Err(ApiError::InvalidBoundingBox(
                "min_lat ne peut pas être supérieur à max_lat".to_string(),
            ));
        }
        if !(-180.0..=180.0).contains(&min_lon) || !(-180.0..=180.0).contains(&max_lon) {
            return Err(ApiError::InvalidBoundingBox(
                "La longitude doit être comprise entre -180.0 et 180.0".to_string(),
            ));
        }
        if !(-90.0..=90.0).contains(&min_lat) || !(-90.0..=90.0).contains(&max_lat) {
            return Err(ApiError::InvalidBoundingBox(
                "La latitude doit être comprise entre -90.0 et 90.0".to_string(),
            ));
        }

        Ok(Self {
            min_lon,
            min_lat,
            max_lon,
            max_lat,
        })
    }

    /// Vérifie l'intersection avec la Bounding Box d'une géométrie.
    pub fn intersects(&self, other: &BoundingBox) -> bool {
        self.min_lon <= other.max_lon
            && self.max_lon >= other.min_lon
            && self.min_lat <= other.max_lat
            && self.max_lat >= other.min_lat
    }
}

/// Erreurs standardisées de l'API.
#[derive(Debug)]
pub enum ApiError {
    InvalidBoundingBox(String),
}

#[derive(Serialize)]
struct ErrorResponse {
    error: String,
    code: u16,
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let (status, message) = match self {
            ApiError::InvalidBoundingBox(msg) => (StatusCode::BAD_REQUEST, msg),
        };

        let body = Json(ErrorResponse {
            error: message,
            code: status.as_u16(),
        });

        (status, body).into_response()
    }
}

/// État partagé de l'application contenant les données en mémoire.
#[derive(Clone)]
pub struct AppState {
    pub features: Arc<Vec<Feature>>,
}

#[tokio::main]
async fn main() {
    tracing_subscriber::registry()
        .with(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "geojson_bbox_api=debug,tower_http=debug".into()),
        )
        .with(tracing_subscriber::fmt::layer())
        .init();

    let state = AppState {
        features: Arc::new(generate_sample_dataset()),
    };

    let app = create_router(state);

    let addr = SocketAddr::from(([0, 0, 0, 0], 3000));
    info!("Serveur GeoJSON démarré sur http://{}", addr);

    let listener = match tokio::net::TcpListener::bind(addr).await {
        Ok(l) => l,
        Err(err) => {
            error!("Échec de liaison du port {}: {:?}", addr, err);
            return;
        }
    };

    if let Err(err) = axum::serve(listener, app).await {
        error!("Erreur d'exécution du serveur HTTP: {:?}", err);
    }
}

/// Construction du routeur Axum (séparé pour faciliter les tests).
pub fn create_router(state: AppState) -> Router {
    Router::new()
        .route("/health", get(health_check))
        .route("/api/features", get(get_features))
        .layer(TraceLayer::new_for_http())
        .with_state(state)
}

/// Endpoint de vérification de santé.
async fn health_check() -> impl IntoResponse {
    Json(serde_json::json!({
        "status": "healthy",
        "service": "geojson-bbox-api"
    }))
}

/// Endpoint principal : récupération des features GeoJSON filtrées par bbox.
async fn get_features(
    State(state): State<AppState>,
    Query(params): Query<BboxParams>,
) -> Result<Json<GeoJson>, ApiError> {
    let bbox_filter = parse_bbox_params(&params)?;

    let matching_features: Vec<Feature> = state
        .features
        .iter()
        .filter(|feature| match &bbox_filter {
            Some(filter) => match extract_feature_bbox(feature) {
                Some(feat_bbox) => filter.intersects(&feat_bbox),
                None => false,
            },
            None => true,
        })
        .cloned()
        .collect();

    let collection_bbox = bbox_filter.map(|b| vec![b.min_lon, b.min_lat, b.max_lon, b.max_lat]);

    let feature_collection = FeatureCollection {
        bbox: collection_bbox,
        features: matching_features,
        foreign_members: None,
    };

    Ok(Json(GeoJson::FeatureCollection(feature_collection)))
}

/// Analyse et valide les paramètres de boîte englobante.
fn parse_bbox_params(params: &BboxParams) -> Result<Option<BoundingBox>, ApiError> {
    if let Some(ref bbox_str) = params.bbox {
        let parts: Vec<&str> = bbox_str.split(',').map(|s| s.trim()).collect();
        if parts.len() != 4 {
            return Err(ApiError::InvalidBoundingBox(
                "Le paramètre 'bbox' doit être sous le format: min_lon,min_lat,max_lon,max_lat"
                    .to_string(),
            ));
        }

        let min_lon = parts[0].parse::<f64>().map_err(|_| {
            ApiError::InvalidBoundingBox("min_lon n'est pas un nombre flottant valide".to_string())
        })?;
        let min_lat = parts[1].parse::<f64>().map_err(|_| {
            ApiError::InvalidBoundingBox("min_lat n'est pas un nombre flottant valide".to_string())
        })?;
        let max_lon = parts[2].parse::<f64>().map_err(|_| {
            ApiError::InvalidBoundingBox("max_lon n'est pas un nombre flottant valide".to_string())
        })?;
        let max_lat = parts[3].parse::<f64>().map_err(|_| {
            ApiError::InvalidBoundingBox("max_lat n'est pas un nombre flottant valide".to_string())
        })?;

        return BoundingBox::new(min_lon, min_lat, max_lon, max_lat).map(Some);
    }

    match (params.min_lon, params.min_lat, params.max_lon, params.max_lat) {
        (Some(min_lon), Some(min_lat), Some(max_lon), Some(max_lat)) => {
            BoundingBox::new(min_lon, min_lat, max_lon, max_lat).map(Some)
        }
        (None, None, None, None) => Ok(None),
        _ => Err(ApiError::InvalidBoundingBox(
            "Tous les paramètres min_lon, min_lat, max_lon, max_lat doivent être fournis conjointement"
                .to_string(),
        )),
    }
}

/// Calcule ou extrait la BoundingBox d'une Feature.
fn extract_feature_bbox(feature: &Feature) -> Option<BoundingBox> {
    // Si la feature possède déjà un bbox explicite
    if let Some(ref bbox) = feature.bbox {
        if bbox.len() >= 4 {
            return BoundingBox::new(bbox[0], bbox[1], bbox[2], bbox[3]).ok();
        }
    }

    // Sinon, calcule l'emprise depuis la géométrie
    let geometry = feature.geometry.as_ref()?;
    compute_geometry_bbox(&geometry.value)
}

/// Calcul récursif / itératif de l'emprise selon le type de géométrie GeoJSON.
fn compute_geometry_bbox(value: &Value) -> Option<BoundingBox> {
    match value {
        Value::Point(coords) => {
            if coords.len() >= 2 {
                BoundingBox::new(coords[0], coords[1], coords[0], coords[1]).ok()
            } else {
                None
            }
        }
        Value::MultiPoint(coords) => compute_points_bbox(coords),
        Value::LineString(coords) => compute_points_bbox(coords),
        Value::MultiLineString(lines) => {
            let points: Vec<Vec<f64>> = lines.iter().flatten().cloned().collect();
            compute_points_bbox(&points)
        }
        Value::Polygon(rings) => {
            let points: Vec<Vec<f64>> = rings.iter().flatten().cloned().collect();
            compute_points_bbox(&points)
        }
        Value::MultiPolygon(polys) => {
            let points: Vec<Vec<f64>> = polys.iter().flatten().flatten().cloned().collect();
            compute_points_bbox(&points)
        }
        Value::GeometryCollection(geometries) => {
            let bboxes: Vec<BoundingBox> = geometries
                .iter()
                .filter_map(|g| compute_geometry_bbox(&g.value))
                .collect();

            if bboxes.is_empty() {
                return None;
            }

            let min_lon = bboxes.iter().map(|b| b.min_lon).fold(f64::INFINITY, f64::min);
            let min_lat = bboxes.iter().map(|b| b.min_lat).fold(f64::INFINITY, f64::min);
            let max_lon = bboxes.iter().map(|b| b.max_lon).fold(f64::NEG_INFINITY, f64::max);
            let max_lat = bboxes.iter().map(|b| b.max_lat).fold(f64::NEG_INFINITY, f64::max);

            BoundingBox::new(min_lon, min_lat, max_lon, max_lat).ok()
        }
    }
}

fn compute_points_bbox(points: &[Vec<f64>]) -> Option<BoundingBox> {
    if points.is_empty() {
        return None;
    }

    let mut min_lon = f64::INFINITY;
    let mut min_lat = f64::INFINITY;
    let mut max_lon = f64::NEG_INFINITY;
    let mut max_lat = f64::NEG_INFINITY;

    for pt in points {
        if pt.len() >= 2 {
            let lon = pt[0];
            let lat = pt[1];
            if lon < min_lon { min_lon = lon; }
            if lon > max_lon { max_lon = lon; }
            if lat < min_lat { min_lat = lat; }
            if lat > max_lat { max_lat = lat; }
        }
    }

    if min_lon.is_infinite() || min_lat.is_infinite() {
        None
    } else {
        BoundingBox::new(min_lon, min_lat, max_lon, max_lat).ok()
    }
}

/// Génère un jeu d'exemples géographiques (points et polygones).
fn generate_sample_dataset() -> Vec<Feature> {
    vec![
        // Paris (Tour Eiffel)
        create_point_feature(
