}

fn create_point_feature(
    id: &str,
    name: &str,
    category: &str,
    lon: f64,
    lat: f64,
) -> Feature {
    Feature {
        bbox: Some(vec![lon, lat, lon, lat]),
        geometry: Some(Geometry::new(Value::Point(vec![lon, lat]))),
        id: Some(geojson::feature::Id::String(id.to_string())),
        properties: Some(
            serde_json::json!({
                "name": name,
                "category": category,
            })
            .as_object()
            .cloned()
            .unwrap_or_default(),
        ),
        foreign_members: None,
    }
}

