// src/main.rs
use std::{
    collections::HashMap,
    net::SocketAddr,
    sync::Arc,
    time::{Duration, Instant},
};

use axum::{
    extract::{Path, State},
    http::StatusCode,
    response::{Html, IntoResponse, Response},
    routing::{get, post},
    Router,
};
use serde::Serialize;
use tokio::sync::RwLock;
use tower_http::trace::TraceLayer;
use tracing::{error, info};

// --- Modèles de données ---

#[derive(Debug, Clone, Serialize)]
pub struct Article {
    pub id: u32,
    pub title: String,
    pub content: String,
    pub author: String,
}

// --- Entrée de Cache Thread-Safe ---

#[derive(Clone)]
pub struct CachedPage {
    pub content: Html<String>,
    pub created_at: Instant,
    pub ttl: Duration,
}

impl CachedPage {
    pub fn is_expired(&self) -> bool {
        self.created_at.elapsed() > self.ttl
    }
}

// --- Cache Thread-Safe ---

#[derive(Default)]
pub struct ResponseCache {
    entries: RwLock<HashMap<String, CachedPage>>,
}

impl ResponseCache {
    pub fn new() -> Self {
        Self {
            entries: RwLock::new(HashMap::new()),
        }
    }

    pub async fn get(&self, key: &str) -> Option<Html<String>> {
        let read_guard = self.entries.read().await;
        if let Some(entry) = read_guard.get(key) {
            if !entry.is_expired() {
                return Some(entry.content.clone());
            }
        }
        None
    }

    pub async fn set(&self, key: String, content: Html<String>, ttl: Duration) {
        let mut write_guard = self.entries.write().await;
        write_guard.insert(
            key,
            CachedPage {
                content,
                created_at: Instant::now(),
                ttl,
            },
        );
    }

    pub async fn clear(&self) {
        let mut write_guard = self.entries.write().await;
        write_guard.clear();
    }
}

// --- État de l'Application ---

#[derive(Clone)]
pub struct AppState {
    pub tera: Arc<tera::Tera>,
    pub cache: Arc<ResponseCache>,
    pub articles: Arc<Vec<Article>>,
}

// --- Gestion des Erreurs ---

#[derive(Debug)]
pub enum AppError {
    Tera(tera::Error),
    NotFound(String),
}

impl From<tera::Error> for AppError {
    fn from(err: tera::Error) -> Self {
        AppError::Tera(err)
    }
}

impl IntoResponse for AppError {
    fn into_response(self) -> Response {
        match self {
            AppError::Tera(err) => {
                error!("Erreur de rendu de template: {:?}", err);
                (
                    StatusCode::INTERNAL_SERVER_ERROR,
                    Html("<h1>500 - Erreur interne du serveur</h1>".to_string()),
                )
                    .into_response()
            }
            AppError::NotFound(msg) => (
                StatusCode::NOT_FOUND,
                Html(format!("<h1>404 - Ressource non trouvée</h1><p>{}</p>", msg)),
            )
                .into_response(),
        }
    }
}

// --- Initialisation des Templates Tera ---

fn init_templates() -> Result<tera::Tera, tera::Error> {
    let mut tera = tera::Tera::default();

    tera.add_raw_templates(vec![
        (
            "index.html",
            r#"<!DOCTYPE html>
<html lang="fr">
<head>
    <meta charset="UTF-8">
