        body { font-family: sans-serif; margin: 2rem; background: #fdfdfd; color: #222; }
        .card { border: 1px solid #ddd; padding: 1rem; margin-bottom: 1rem; border-radius: 8px; }
        .meta { color: #666; font-size: 0.9rem; }
