// --- Contrôleurs (Handlers) ---

async fn handle_index(State(state): State<AppState>) -> Result<Html<String>, AppError> {
    let cache_key = "index_page".to_string();

    // Consultation du cache
    if let Some(cached_html) = state.cache.get(&cache_key).await {
        info!("Cache HIT: {}", cache_key);
        return Ok(cached_html);
    }

    info!("Cache MISS: {}", cache_key);

    let mut ctx = tera::Context::new();
    ctx.insert("title", "Portail Microservice Axum SSR");
    ctx.insert("articles", &*state.articles);

    let rendered = state.tera.render("index.html", &ctx)?;
    let html_response = Html(rendered);

    // Mise en cache pour 30 secondes
    state
        .cache
        .set(cache_key, html_response.clone(), Duration::from_secs(30))
        .await;

    Ok(html_response)
}

async fn handle_article(
    State(state): State<AppState>,
    Path(id): Path<u32>,
) -> Result<Html<String>, AppError> {
    let cache_key = format!("article_{}", id);

    // Consultation du cache
    if let Some(cached_html) = state.cache.get(&cache_key).await {
        info!("Cache HIT: {}", cache_key);
        return Ok(cached_html);
    }

    info!("Cache MISS: {}", cache_key);

    let article = state
        .articles
        .iter()
        .find(|a| a.id == id)
        .ok_or_else(|| AppError::NotFound(format!("L'article avec l'id {} est introuvable.", id)))?;

    let mut ctx = tera::Context::new();
    ctx.insert("article", article);

    let rendered = state.tera.render("article.html", &ctx)?;
    let html_response = Html(rendered);

    // Mise en cache pour 60 secondes
    state
        .cache
        .set(cache_key, html_response.clone(), Duration::from_secs(60))
        .await;

    Ok(html_response)
}

