// --- Entrée de Cache Thread-Safe ---

#[derive(Clone)]
pub struct CachedPage {
    pub content: Html<String>,
    pub created_at: Instant,
    pub ttl: Duration,
}

impl CachedPage {
    pub fn is_expired(&self) -> bool {
        self.created_at.elapsed() > self.ttl
    }
}

// --- Cache Thread-Safe ---

#[derive(Default)]
pub struct ResponseCache {
    entries: RwLock<HashMap<String, CachedPage>>,
}

impl ResponseCache {
    pub fn new() -> Self {
        Self {
            entries: RwLock::new(HashMap::new()),
        }
    }

    pub async fn get(&self, key: &str) -> Option<Html<String>> {
        let read_guard = self.entries.read().await;
        if let Some(entry) = read_guard.get(key) {
            if !entry.is_expired() {
                return Some(entry.content.clone());
            }
        }
        None
    }

    pub async fn set(&self, key: String, content: Html<String>, ttl: Duration) {
        let mut write_guard = self.entries.write().await;
        write_guard.insert(
            key,
            CachedPage {
                content,
                created_at: Instant::now(),
                ttl,
            },
        );
    }

    pub async fn clear(&self) {
        let mut write_guard = self.entries.write().await;
        write_guard.clear();
    }
}

