```rust
// src/main.rs
use futures_util::{SinkExt, StreamExt};
use std::collections::HashMap;
use std::net::SocketAddr;
use std::sync::Arc;
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::{mpsc, Mutex};
use tokio_util::codec::{Framed, LinesCodec};
use tracing::{error, info, warn};

/// Représente les commandes slash supportées par la machine de chat.
#[derive(Debug, PartialEq, Eq)]
enum Command {
    Join(String),
    PrivateMessage { target: String, content: String },
    Nick(String),
    Quit,
    Help,
    ListRooms,
    ListUsers,
    ChatMessage(String),
}

impl Command {
    /// Analyse une ligne de texte saisie par le client pour en extraire une commande ou un message de chat.
    fn parse(input: &str) -> Self {
        let trimmed = input.trim();
        if !trimmed.starts_with('/') {
            return Command::ChatMessage(trimmed.to_string());
        }

        let mut parts = trimmed.splitn(3, ' ');
        let command_str = parts.next().unwrap_or("");

        match command_str {
            "/join" => {
                if let Some(room) = parts.next() {
                    let room = room.trim();
                    if !room.is_empty() {
                        Command::Join(room.to_string())
                    } else {
                        Command::Help
                    }
                } else {
                    Command::Help
                }
            }
            "/msg" => {
                let target = parts.next().unwrap_or("").trim();
                let content = parts.next().unwrap_or("").trim();
                if target.is_empty() || content.is_empty() {
                    Command::Help
                } else {
                    Command::PrivateMessage {
                        target: target.to_string(),
                        content: content.to_string(),
                    }
                }
            }
            "/nick" => {
                if let Some(nick) = parts.next() {
                    let nick = nick.trim();
                    if !nick.is_empty() {
                        Command::Nick(nick.to_string())
                    } else {
                        Command::Help
                    }
                } else {
                    Command::Help
                }
            }
            "/quit" => Command::Quit,
            "/help" => Command::Help,
            "/rooms" => Command::ListRooms,
            "/users" => Command::ListUsers,
            _ => Command::Help,
        }
    }
}

/// Informations associées à un pair connecté.
struct Peer {
    #[allow(dead_code)]
    addr: SocketAddr,
    nickname: String,
    room: Option<String>,
    sender: mpsc::Sender<String>,
}

/// État partagé du serveur de chat protégé par un Mutex asynchrone.
struct ChatState {
    peers: HashMap<usize, Peer>,
    next_id: usize,
}

impl ChatState {
    fn new() -> Self {
        Self {
            peers: HashMap::new(),
            next_id: 1,
        }
    }

    /// Enregistre un nouveau client et lui attribue un identifiant unique ainsi qu'un pseudo par défaut.
    fn register_peer(
        &mut self,
        addr: SocketAddr,
        sender: mpsc::Sender<String>,
    ) -> (usize, String) {
        let id = self.next_id;
        self.next_id = self.next_id.wrapping_add(1);

        let default_nick = format!("guest_{}", id);
        let default_room = "general".to_string();

        let peer = Peer {
            addr,
            nickname: default_nick.clone(),
            room: Some(default_room),
            sender,
        };

        self.peers.insert(id, peer);
        (id, default_nick)
    }

    /// Supprime un client et retourne son pseudo et son salon pour les notifications de départ.
    fn unregister_peer(&mut self, id: usize) -> Option<(String, Option<String>)> {
        self.peers.remove(&id).map(|p| (p.nickname, p.room))
    }

    /// Diffuse un message à tous les utilisateurs d'un salon, optionnellement en excluant un ID (l'émetteur).
    async fn broadcast_room(&self, room: &str, message: &str, exclude_id: Option<usize>) {
        for (id, peer) in &self.peers {
            if Some(*id) == exclude_id {
                continue;
            }
            if let Some(r) = &peer.room {
                if r == room {
                    let _ = peer.sender.send(message.to_string()).await;
                }
            }
        }
    }

    /// Envoie un message direct à un utilisateur cible.
    async fn send_private_message(
        &self,
        sender_id: usize,
        target_nick: &str,
        content: &str,
    ) -> Result<(), &'static str> {
        let sender_nick = match self.peers.get(&sender_id) {
            Some(p) => p.nickname.clone(),
            None => return Err("Client émetteur introuvable."),
        };

        let target_peer = self
            .peers
            .values()
            .find(|p| p.nickname.eq_ignore_ascii_case(target_nick));

        match target_peer {
            Some(target) => {
                let formatted = format!("[MP de {}]: {}", sender_nick, content);
                let _ = target.sender.send(formatted).await;
                Ok(())
            }
            None => Err("Destinataire introuvable."),
        }
    }

    /// Change le salon d'un client.
    async fn join_room(&mut self, client_id: usize, new_room: String) -> Option<String> {
        let (old_room, nick) = {
            let peer = self.peers.get_mut(&client_id)?;
            let old = peer.room.replace(new_room.clone());
            (old, peer.nickname.clone())
        };

        if let Some(old) = &old_room {
            if old != &new_room {
                self.broadcast_room(
                    old,
                    &format!("* {} a quitté le salon #{} *", nick, old),
                    Some(client_id),
                )
                .await;
            }
        }

        self.broadcast_room(
            &new_room,
            &format!("* {} a rejoint le salon #{} *", nick, new_room),
            Some(client_id),
        )
        .await;

        old_room
    }

    /// Modifie le pseudonyme d'un client.
    async fn change_nick(
        &mut self,
        client_id: usize,
        new_nick: String,
    ) -> Result<String, &'static str> {
        let exists = self
            .peers
            .values()
            .any(|p| p.nickname.eq_ignore_ascii_case(&new_nick));

        if exists {
            return Err("Ce pseudonyme est déjà utilisé.");
        }

        let (old_nick, room) = {
            let peer = match self.peers.get_mut(&client_id) {
                Some(p) => p,
                None => return Err("Client introuvable."),
            };
            let old = std::mem::replace(&mut peer.nickname, new_nick.clone());
            (old, peer.room.clone())
        };

        if let Some(r) = room {
            self.broadcast_room(
                &r,
                &format!("* {} s'appelle désormais {} *", old_nick, new_nick),
                None,
            )
            .await;
        }

        Ok(old_nick)
    }

    /// Liste des utilisateurs d'un salon.
    fn list_users_in_room(&self, room: &str) -> Vec<String> {
        self.peers
            .values()
            .filter(|p| p.room.as_deref() == Some(room))
            .map(|p| p.nickname.clone())
            .collect()
    }
}

type SharedChatState = Arc<Mutex<ChatState>>;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    let addr = "127.0.0.1:8080";
    let listener = TcpListener::bind(addr).await?;
    info!("Serveur de chat TCP démarré sur {}", addr);

    let state = Arc::new(Mutex::new(ChatState::new()));

    loop {
        match listener.accept().await {
            Ok((stream, peer_addr)) => {
                info!("Nouvelle connexion acceptée : {}", peer_addr);
                let state_clone = Arc::clone(&state);
                tokio::spawn(async move {
                    if let Err(err) = handle_client(state_clone, stream, peer_addr).await {
                        error!("Erreur lors du traitement du client {}: {}", peer_addr, err);
                    }
                });
            }
            Err(err) => {
                warn!("Échec de l'acceptation d'une connexion TCP : {}", err);
            }
        }
    }
}

/// Gère le cycle de vie complet d'un client TCP connecté.
async fn handle_client(
    state: SharedChatState,
    stream: TcpStream,
    peer_addr: SocketAddr,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let mut framed = Framed::new(stream, LinesCodec::new());

    // Canal mpsc pour envoyer des messages asynchrones au client TCP.
    let (tx, mut rx) = mpsc::channel::<String>(32);

    let (client_id, initial_nick) = {
        let mut state_guard = state.lock().await;
        state_guard.register_peer(peer_addr, tx.clone())
    };

    // Message d'accueil et instructions.
    let welcome = format!(
        "=========================================\n\
         Bienvenue sur le serveur de chat Tokio !\n\
         Votre pseudo temporaire est : {}\n\
         Salon par défaut : #general\n\n\
         Commandes disponibles :\n\
           /join <salon>         - Rejoindre ou créer un salon\n\
           /msg <user> <texte>   - Envoyer un message privé\n\
           /nick <pseudo>        - Changer de pseudonyme\n\
           /users                - Voir les utilisateurs du salon actuel\n\
           /help                 - Afficher cette aide\n\
           /quit                 - Se déconnecter\n\
         =========================================",
        initial_nick
    );

    framed.send(welcome).await?;

    // Annonce d'arrivée dans le salon général.
    {
        let state_guard = state.lock().await;
        state_guard
            .broadcast_room(
                "general",
                &format!("* {} a rejoint le chat (salon #general) *", initial_nick),
                Some(client_id),
            )
            .await;
    }

    let mut should_terminate = false;

    while !should_terminate {
        tokio::select! {
            // Réception d'un message sortant destiné à ce client via le canal mpsc
            Some(msg) = rx.recv() => {
                if let Err(e) = framed.send(msg).await {
                    warn!("Impossible d'envoyer la ligne au client {} : {}", peer_addr, e);
                    break;
                }
            }
            // Réception d'une ligne envoyée par le client sur le flux TCP
            incoming = framed.next() => {
                match incoming {
                    Some(Ok(line)) => {
                        let cmd = Command::parse(&line);
                        match cmd {
                            Command::ChatMessage(content) => {
                                if content.is_empty() {
                                    continue;
                                }
                                let state_guard = state.lock().await;
                                if let Some(peer) = state_guard.peers.get(&client_id) {
                                    if let Some(room) = &peer.room {
                                        let broadcast_line = format!("[#{}] <{}> {}", room, peer.nickname, content);
                                        state_guard.broadcast_room(room, &broadcast_line, None).await;
                                    } else {
                                        let _ = tx.send("Vous n'êtes dans aucun salon. Utilisez /join <salon>.".to_string()).await;
                                    }
                                }
                            }
                            Command::Join(new_room) => {
                                let mut state_guard = state.lock().await;
                                state_guard.join_room(client_id, new_room.clone()).await;
                                let _ = tx.send(format!("* Vous avez rejoint le salon #{} *", new_room)).await;
                            }
                            Command::PrivateMessage { target, content } => {
                                let state_guard = state.lock().await;
                                match state_guard.send_private_message(client_id, &target, &content).await {
                                    Ok(()) => {
                                        let _ = tx.send(format!("[MP à {}]: {}", target, content)).await;
                                    }
                                    Err(err_msg) => {
                                        let _ = tx.send(format!("Erreur : {}", err_msg)).await;
                                    }
                                }
                            }
                            Command::Nick(new_nick) => {
                                let mut state_guard = state.lock().await;
                                match state_guard.change_nick(client_id, new_nick.clone()).await {
                                    Ok(_) => {
                                        let _ = tx.send(format!("* Votre pseudonyme est désormais {} *", new_nick)).await;
                                    }
                                    Err(err_msg) => {
                                        let _ = tx.send(format!("Erreur : {}", err_msg)).await;
                                    }
                                }
                            }
                            Command::ListUsers => {
                                let state_guard = state.lock().await;
                                if let Some(peer) = state_guard.peers.get(&client_id) {
                                    if let Some(room) = &peer.room {
                                        let users = state_guard.list_users_in_room(room);
                                        let _ = tx.send(format!("Utilisateurs dans #{}: {}", room, users.join(", "))).await;
                                    } else {
                                        let _ = tx.send("Vous n'êtes actuellement dans aucun salon.".to_string()).await;
                                    }
                                }
                            }
                            Command::ListRooms => {
                                let state_guard = state.lock().await;
                                let mut rooms: Vec<String> = state_guard
                                    .peers
                                    .values()
                                    .filter_map(|p| p.room.clone())
                                    .collect();
                                rooms.sort();
                                rooms.dedup();
                                let _ = tx.send(format!("Salons actifs : {}", rooms.join(", "))).await;
                            }
                            Command::Help => {
                                let help_text = "\nCommandes supportées :\n\
                                                 /join <salon>        - Rejoindre ou basculer vers un salon\n\
                                                 /msg <user> <texte>  - Envoyer un message privé direct\n\
                                                 /nick <pseudo>       - Renommer votre compte\n\
                                                 /users               - Lister les utilisateurs du salon actif\n\
                                                 /rooms               - Lister les salons actifs\n\
                                                 /quit                - Quitter le serveur de chat\n\
                                                 /help                - Afficher cette aide";
                                let _ = tx.send(help_text.to_string()).await;
                            }
                            Command::Quit => {
                                let _ = tx.send("Déconnexion en cours... Au revoir !".to_string()).await;
                                should_terminate = true;
                            }
                        }
                    }
                    Some(Err(err)) => {
                        warn!("Erreur de décodage pour le client {} : {}", peer_addr, err);
                        break;
                    }
                    None => {
                        // Fermeture normale du flux côté client
                        break;
                    }
                }
            }
        }
    }

    // Nettoyage lors de la déconnexion
    let departure_info = {
        let mut state_guard = state.lock().await;
        state_guard.unregister_peer(client_id)
    };

    if let Some((nick, Some(room))) = departure_info {
        let state_guard = state.lock().await;
        state_guard
            .broadcast_room(
                &room,
                &format!("* {} s'est déconnecté *", nick),
                None,
            )
            .await;
    }

    info!("Client déconnecté : {}", peer_addr);
    Ok(())
}

