```rust
// src/main.rs
use std::fmt::Display;
use std::net::SocketAddr;
use std::str::FromStr;

use axum::{
    extract::Request,
    http::{header, HeaderMap, StatusCode},
    response::{IntoResponse, Response},
    routing::get,
    Router,
};
use serde::{Deserialize, Serialize};

use tracing::info;
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SupportedFormat {
    Json,
    MessagePack,
    PlainText,
}

impl SupportedFormat {
    fn content_type(&self) -> &'static str {
        match self {
            Self::Json => "application/json",
            Self::MessagePack => "application/msgpack",
            Self::PlainText => "text/plain; charset=utf-8",
        }
    }
}

/// Détermine le format attendu d'après l'en-tête `Accept`.
/// Gère la négociation de contenu standard avec les poids de qualité (ex: `q=0.9`).
fn negotiate_format(headers: &HeaderMap) -> Result<SupportedFormat, StatusCode> {
    let accept_header = match headers.get(header::ACCEPT) {
        Some(val) => match val.to_str() {
            Ok(v) => v,
            Err(_) => return Err(StatusCode::BAD_REQUEST),
        },
        None => return Ok(SupportedFormat::Json), // Format par défaut
    };

    if accept_header.trim().is_empty() {
        return Ok(SupportedFormat::Json);
    }

    struct Candidate {
        format: SupportedFormat,
        quality: f32,
    }

    let mut candidates: Vec<Candidate> = Vec::new();

    for item in accept_header.split(',') {
        let mut parts = item.split(';');
        let mime_part = match parts.next() {
            Some(p) => p.trim(),
            None => continue,
        };

        if mime_part.is_empty() {
            continue;
        }

        let mut quality = 1.0f32;
        for param in parts {
            let param = param.trim();
            if let Some(stripped) = param.strip_prefix("q=") {
                if let Ok(q) = stripped.parse::<f32>() {
                    quality = q.clamp(0.0, 1.0);
                }
            }
        }

        if quality <= 0.0 {
            continue;
        }

        if let Ok(mime) = mime::Mime::from_str(mime_part) {
            let type_str = mime.type_().as_str();
            let subtype_str = mime.subtype().as_str();

            if (type_str == "*" && subtype_str == "*")
                || (type_str == "application" && (subtype_str == "json" || subtype_str.ends_with("+json")))
            {
                candidates.push(Candidate {
                    format: SupportedFormat::Json,
                    quality,
                });
            } else if type_str == "application"

                && (subtype_str == "msgpack"
                    || subtype_str == "x-msgpack"
                    || subtype_str == "vnd.msgpack")
            {
                candidates.push(Candidate {
                    format: SupportedFormat::MessagePack,
                    quality,
                });
            } else if type_str == "text" && (subtype_str == "plain" || subtype_str == "*") {
                candidates.push(Candidate {
                    format: SupportedFormat::PlainText,
                    quality,
                });
            }
        }
    }

    if candidates.is_empty() {
        return Err(StatusCode::NOT_ACCEPTABLE);
    }

    // Sélectionne le candidat ayant la qualité la plus élevée
    candidates.sort_by(|a, b| b.quality.partial_cmp(&a.quality).unwrap_or(std::cmp::Ordering::Equal));
    Ok(candidates[0].format)
}

/// Type générique encapsulant une valeur sérialisable et son rendu texte brut.
pub struct Negotiated<T>(pub T);

impl<T> IntoResponse for Negotiated<T>
where
    T: Serialize + Display,
{
    fn into_response(self) -> Response {
        // Fallback sans requête : renvoie du JSON
        match serde_json::to_vec(&self.0) {
            Ok(body) => (
                StatusCode::OK,
                [(header::CONTENT_TYPE, SupportedFormat::Json.content_type())],
                body,
            )
                .into_response(),
            Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
        }
    }
}

/// Sérialise et applique les en-têtes selon le format négocié.
fn respond_negotiated<T>(value: &T, format: SupportedFormat) -> Response
where
    T: Serialize + Display,
{
    match format {
        SupportedFormat::Json => match serde_json::to_vec(value) {
            Ok(bytes) => (
                StatusCode::OK,
                [(header::CONTENT_TYPE, format.content_type())],
                bytes,
            )
                .into_response(),
            Err(err) => {
                tracing::error!("Erreur de sérialisation JSON: {err}");
                StatusCode::INTERNAL_SERVER_ERROR.into_response()
            }
        },
        SupportedFormat::MessagePack => match rmp_serde::to_vec(value) {
            Ok(bytes) => (
                StatusCode::OK,
                [(header::CONTENT_TYPE, format.content_type())],
                bytes,
            )
                .into_response(),
            Err(err) => {
                tracing::error!("Erreur de sérialisation MessagePack: {err}");
                StatusCode::INTERNAL_SERVER_ERROR.into_response()
            }
        },
        SupportedFormat::PlainText => (
            StatusCode::OK,
            [(header::CONTENT_TYPE, format.content_type())],
            value.to_string(),
        )
            .into_response(),
    }
}

