// src/main.rs
use chrono::{DateTime, Duration as ChronoDuration, Utc};
use reqwest::{Client, Method, RequestBuilder, Response, StatusCode};
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use std::time::Duration;
use thiserror::Error;
use tokio::sync::RwLock;
use tracing::{debug, error, info, warn};
use wiremock::matchers::{header, method, path};
use wiremock::{Mock, MockServer, ResponseTemplate};

/// Erreurs spécifiques au client OAuth2.
#[derive(Debug, Error)]
pub enum OAuth2Error {
    #[error("Erreur réseau ou HTTP Reqwest : {0}")]
    Reqwest(#[from] reqwest::Error),

    #[error("Échec du rafraîchissement OAuth2 (statut {status}) : {body}")]
    RefreshFailed {
        status: StatusCode,
        body: String,
    },

    #[error("Aucun Refresh Token disponible pour rafraîchir la session")]
    MissingRefreshToken,

    #[error("Requête non autorisée (401) persistante même après rafraîchissement du jeton")]
    UnauthorizedAfterRefresh,

    #[error("Erreur de sérialisation JSON : {0}")]
    Serialization(#[from] serde_json::Error),
}

/// Modèle d'un jeton OAuth2 détenu en mémoire.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OAuth2Token {
    pub access_token: String,
    pub refresh_token: Option<String>,
    pub expires_at: Option<DateTime<Utc>>,
    pub token_type: String,
}

impl OAuth2Token {
    /// Crée un nouveau jeton avec une durée de validité en secondes optionnelle.
    pub fn new(
        access_token: String,
        refresh_token: Option<String>,
        expires_in_secs: Option<i64>,
        token_type: Option<String>,
    ) -> Self {
