    pub client_id: String,
    pub client_secret: Option<String>,
}

/// Client HTTP enveloppant Reqwest avec rafraîchissement transparent de jeton OAuth2.
#[derive(Clone)]
pub struct AuthenticatedClient {
    http_client: Client,
    token_state: Arc<RwLock<OAuth2Token>>,
    config: OAuth2Config,
    safety_margin: ChronoDuration,
}

impl AuthenticatedClient {
    /// Initialise un nouveau client OAuth2.
    pub fn new(
        http_client: Client,
        initial_token: OAuth2Token,
        config: OAuth2Config,
    ) -> Self {
        Self {
            http_client,
            token_state: Arc::new(RwLock::new(initial_token)),
            config,
            safety_margin: ChronoDuration::seconds(30),
        }
    }

    /// Renvoie le jeton d'accès actuel, en le rafraîchissant proactivement s'il est expiré.
    pub async fn ensure_valid_token(&self) -> Result<String, OAuth2Error> {
        // Lecture optimiste du jeton
        {
            let token = self.token_state.read().await;
            if !token.is_expired(self.safety_margin) {
                return Ok(token.access_token.clone());
            }
            debug!("Le jeton d'accès actuel est expiré ou sur le point d'expirer.");
        }

        // Rafraîchissement sous verrou exclusif
        self.refresh_token_internal().await
    }

    /// Exécute l'appel de rafraîchissement forcé vers le serveur OAuth2 (par ex. suite à un 401).
    pub async fn force_refresh_token(&self) -> Result<String, OAuth2Error> {
        let mut token_guard = self.token_state.write().await;
        self.do_refresh(&mut token_guard).await
    }

    /// Exécute l'appel de rafraîchissement vers le serveur OAuth2 avec double vérification.
    async fn refresh_token_internal(&self) -> Result<String, OAuth2Error> {
        let mut token_guard = self.token_state.write().await;

        // Double vérification au cas où un autre thread aurait déjà rafraîchi le jeton
        if !token_guard.is_expired(self.safety_margin) {
            return Ok(token_guard.access_token.clone());
        }

        self.do_refresh(&mut token_guard).await
    }

    async fn do_refresh(&self, token_guard: &mut tokio::sync::RwLockWriteGuard<'_, OAuth2Token>) -> Result<String, OAuth2Error> {
        let refresh_token = token_guard
            .refresh_token
            .as_ref()
            .ok_or(OAuth2Error::MissingRefreshToken)?;

        info!("Rafraîchissement du jeton OAuth2 en cours...");

        let mut form_params = vec![
            ("grant_type", "refresh_token"),
            ("refresh_token", refresh_token.as_str()),
            ("client_id", self.config.client_id.as_str()),
        ];

        let secret_str;
        if let Some(ref secret) = self.config.client_secret {
            secret_str = secret.clone();
            form_params.push(("client_secret", secret_str.as_str()));
        }

        let response = self
            .http_client
            .post(&self.config.token_url)
            .form(&form_params)
            .send()
            .await?;

        let status = response.status();
        if !status.is_success() {
            let error_body = response
                .text()
                .await
                .unwrap_or_else(|_| "<impossible de lire le corps d'erreur>".to_string());
            error!(
                "Échec du rafraîchissement OAuth2 (HTTP {}) : {}",
                status, error_body
            );
            return Err(OAuth2Error::RefreshFailed {
                status,
                body: error_body,
            });
        }

        let payload: TokenResponsePayload = response.json().await?;

        // Mise à jour de l'état
        let new_refresh_token = payload
            .refresh_token
            .or_else(|| token_guard.refresh_token.clone());

        let new_token = OAuth2Token::new(
            payload.access_token.clone(),
            new_refresh_token,
            payload.expires_in,
            payload.token_type,
        );

        **token_guard = new_token;
        info!("Jeton OAuth2 rafraîchi avec succès.");

        Ok(payload.access_token)
    }

    /// Prépare une requête HTTP authentifiée.
    pub async fn request<U: reqwest::IntoUrl>(
        &self,
        method: Method,
        url: U,
    ) -> Result<RequestBuilder, OAuth2Error> {
        let token = self.ensure_valid_token().await?;
        Ok(self
            .http_client
            .request(method, url)
            .bearer_auth(token))
    }

    /// Envoie une requête avec gestion automatique du code 401 Unauthorized.
    ///
    /// Si un 401 survient, le jeton est immédiatement renouvelé et la requête
    /// est exécutée une seconde fois.
    pub async fn execute_with_auto_refresh<F>(
        &self,
        request_factory: F,
    ) -> Result<Response, OAuth2Error>
    where
        F: Fn(&str) -> RequestBuilder,
    {
        // 1. Première tentative avec jeton garanti valide (proactif)
        let token = self.ensure_valid_token().await?;
        let request = request_factory(&token);
