// src/main.rs
use std::{
    net::SocketAddr,
    sync::{
        atomic::{AtomicBool, Ordering},
        Arc,
    },
    time::Instant,
};

use axum::{
    extract::State,
    http::StatusCode,
    response::IntoResponse,
    routing::{get, post},
    Json, Router,
};
use serde::{Deserialize, Serialize};
use tower_http::trace::TraceLayer;
use tracing::{error, info, warn};

/// État partagé du microservice
#[derive(Clone)]
pub struct AppState {
    started_at: Instant,
    is_ready: Arc<AtomicBool>,
    db_connected: Arc<AtomicBool>,
}

impl AppState {
    pub fn new() -> Self {
        Self {
            started_at: Instant::now(),
            is_ready: Arc::new(AtomicBool::new(true)),
            db_connected: Arc::new(AtomicBool::new(true)),
        }
    }
}

impl Default for AppState {
    fn default() -> Self {
        Self::new()
    }
}

/// Statut de santé générique
#[derive(Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "UPPERCASE")]
pub enum HealthStatus {
    Up,
    Down,
}

/// Réponse pour la sonde de Liveness
#[derive(Debug, Serialize)]
pub struct LivenessResponse {
    pub status: HealthStatus,
    pub uptime_seconds: u64,
}

/// Détail d'une vérification individuelle de composant pour la Readiness
#[derive(Debug, Serialize)]
pub struct ComponentCheck {
    pub status: HealthStatus,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub message: Option<String>,
}

/// Réponse pour la sonde de Readiness
#[derive(Debug, Serialize)]
pub struct ReadinessResponse {
    pub status: HealthStatus,
    pub components: ReadinessComponents,
}

#[derive(Debug, Serialize)]
pub struct ReadinessComponents {
    pub app_lifecycle: ComponentCheck,
    pub database: ComponentCheck,
}

/// Payload pour modifier dynamiquement l'état (simulation opérationnelle)
#[derive(Debug, Deserialize)]
pub struct ToggleStatePayload {
    pub ready: Option<bool>,
    pub db_connected: Option<bool>,
}

/// Handler Liveness (`/livez` ou `/healthz`)
/// Conforme Kubernetes : retourne 200 OK si le processus est opérationnel.
async fn liveness_handler(State(state): State<AppState>) -> impl IntoResponse {
    let uptime = state.started_at.elapsed().as_secs();
    (
        StatusCode::OK,
        Json(LivenessResponse {
            status: HealthStatus::Up,
            uptime_seconds: uptime,
        }),
    )
}

/// Handler Readiness (`/readyz`)
/// Conforme Kubernetes : retourne 200 OK si apte au trafic, 503 SERVICE_UNAVAILABLE sinon.
async fn readiness_handler(State(state): State<AppState>) -> impl IntoResponse {
    let app_ready = state.is_ready.load(Ordering::Acquire);
    let db_ok = state.db_connected.load(Ordering::Acquire);

    let app_check = ComponentCheck {
        status: if app_ready {
            HealthStatus::Up
        } else {
            HealthStatus::Down
        },
        message: if app_ready {
            None
        } else {
            Some("Service is draining or not accepting traffic".to_string())
        },
    };

    let db_check = ComponentCheck {
        status: if db_ok {
            HealthStatus::Up
        } else {
            HealthStatus::Down
        },
        message: if db_ok {
            None
        } else {
            Some("Database connection pool unreachable".to_string())
        },
    };

    let is_overall_ready = app_ready && db_ok;
    let status_code = if is_overall_ready {
        StatusCode::OK
    } else {
        StatusCode::SERVICE_UNAVAILABLE
    };

    let response = ReadinessResponse {
        status: if is_overall_ready {
            HealthStatus::Up
        } else {
            HealthStatus::Down
        },
        components: ReadinessComponents {
            app_lifecycle: app_check,
            database: db_check,
        },
    };

    (status_code, Json(response))
}

/// Endpoint administratif permettant de simuler des pannes ou un passage hors-ligne
async fn admin_toggle_handler(
    State(state): State<AppState>,
    Json(payload): Json<ToggleStatePayload>,
) -> impl IntoResponse {
    if let Some(ready) = payload.ready {
        state.is_ready.store(ready, Ordering::Release);
        info!(new_status = ready, "État de readiness applicatif modifié");
    }

    if let Some(db_ok) = payload.db_connected {
        state.db_connected.store(db_ok, Ordering::Release);
        info!(new_status = db_ok, "État de connectivité base de données modifié");
    }

    (StatusCode::OK, Json(serde_json::json!({ "message": "State updated" })))
}

/// Gestion de l'arrêt propre (Graceful Shutdown)
/// Compatible avec le signal SIGTERM de Kubernetes
async fn shutdown_signal(state: AppState) {
    let ctrl_c = async {
        if let Err(err) = tokio::signal::ctrl_c().await {
            error!(error = %err, "Échec d'écoute de CTRL+C");
        }
    };

    #[cfg(unix)]
    let terminate = async {
        match tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate()) {
            Ok(mut signal) => {
                signal.recv().await;
            }
            Err(err) => {
                error!(error = %err, "Échec d'initialisation du gestionnaire SIGTERM");
            }
        }
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {
            warn!("Signal d'interruption reçu (Ctrl+C). Démarrage de l'arrêt gracieux...");
        },
        _ = terminate => {
            warn!("Signal SIGTERM reçu de Kubernetes. Démarrage de l'arrêt gracieux...");
        },
    }

    // Bascule immédiate de la readiness à faux pour avertir Kubernetes
    state.is_ready.store(false, Ordering::Release);
    info!("Readiness passée à DOWN. En attente de l'arrêt du serveur...");
}

pub fn create_app(state: AppState) -> Router {
    Router::new()
        // Endpoints conformes aux standards Kubernetes
        .route("/livez", get(liveness_handler))
        .route("/healthz", get(liveness_handler))
        .route("/readyz", get(readiness_handler))
        // Endpoint administratif de contrôle / test d'orchestration
        .route("/admin/state", post(admin_toggle_handler))
        .layer(TraceLayer::new_for_http())
        .with_state(state)
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "k8s_healthcheck_service=info,tower_http=info".into()),
        )
        .init();

    let state = AppState::new();
    let app = create_app(state.clone());

    let addr = SocketAddr::from(([0, 0, 0, 0], 8080));
    info!(%addr, "Démarrage du microservice de healthcheck...");

    let listener = match tokio::net::TcpListener::bind(addr).await {
        Ok(l) => l,
        Err(err) => {
            error!(error = %err, %addr, "Impossible de lier le socket TCP");
            return Err(err.into());
        }
    };

    if let Err(err) = axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal(state))
        .await
    {
        error!(error = %err, "Erreur lors de l'exécution du serveur Axum");
        return Err(err.into());
    }

    info!("Microservice arrêté proprement.");
    Ok(())
}

