use std::net::SocketAddr;
use axum::{
    extract::Request,
    http::{HeaderName, HeaderValue, StatusCode},
    response::{IntoResponse, Response},
    routing::get,
    Json, Router,
};
use serde_json::json;
use tower::ServiceBuilder;
use tower_http::{
    request_id::{MakeRequestId, PropagateRequestIdLayer, RequestId, SetRequestIdLayer},
    trace::{DefaultOnFailure, DefaultOnRequest, DefaultOnResponse, TraceLayer},
    LatencyUnit,
};
use tracing::{info, Level};
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt};
use uuid::Uuid;

static X_REQUEST_ID: HeaderName = HeaderName::from_static("x-request-id");

#[derive(Clone, Copy)]
struct MakeRequestUuid;

impl MakeRequestId for MakeRequestUuid {
    fn make_request_id<B>(&mut self, _request: &http::Request<B>) -> Option<RequestId> {
        let request_id = Uuid::new_v4().to_string();
        match HeaderValue::from_str(&request_id) {
            Ok(header_val) => Some(RequestId::new(header_val)),
            Err(_) => None,
        }
    }
}

async fn health_check() -> impl IntoResponse {
    info!("Endpoint de santé sollicité");
    (StatusCode::OK, Json(json!({ "status": "ok" })))
}

async fn echo_id(req: Request) -> Response {
    let req_id = req
        .headers()
        .get(&X_REQUEST_ID)
        .and_then(|val| val.to_str().ok())
        .unwrap_or("inconnu");

    info!(request_id = %req_id, "Traitement dans le handler echo");

    (
        StatusCode::OK,
        Json(json!({
            "message": "Identifiant de corrélation reçu avec succès",
            "request_id": req_id
        })),
    )
        .into_response()
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    tracing_subscriber::registry()
        .with(
            tracing_subscriber::EnvFilter::try_from_default_env().unwrap_or_else(|_| {
                "axum_request_id_tracing=debug,tower_http=debug,tower_http::trace=debug".into()
            }),
        )
        .with(tracing_subscriber::fmt::layer())
        .init();

    let middleware_stack = ServiceBuilder::new()
        // 1. Définit ou conserve un X-Request-ID si déjà présent, sinon génère un UUID v4
        .layer(SetRequestIdLayer::new(
            X_REQUEST_ID.clone(),
            MakeRequestUuid,
        ))
        // 2. Traçage structuré avec injection du request_id dans le Span tracing
        .layer(
            TraceLayer::new_for_http()
                .make_span_with(|request: &Request<_>| {
                    let request_id = request
                        .headers()
                        .get(&X_REQUEST_ID)
                        .and_then(|v| v.to_str().ok())
                        .unwrap_or("unknown");

                    tracing::info_span!(
                        "http_request",
                        method = %request.method(),
                        uri = %request.uri(),
                        version = ?request.version(),
                        request_id = %request_id,
                    )
                })
                .on_request(DefaultOnRequest::new().level(Level::INFO))
                .on_response(
                    DefaultOnResponse::new()
                        .level(Level::INFO)
                        .latency_unit(LatencyUnit::Millis),
                )
                .on_failure(
                    DefaultOnFailure::new()
                        .level(Level::ERROR)
                        .latency_unit(LatencyUnit::Millis),
                ),
        )
        // 3. Propage le X-Request-ID dans les en-têtes de la réponse HTTP sortante
        .layer(PropagateRequestIdLayer::new(X_REQUEST_ID.clone()));

    let app = Router::new()
        .route("/health", get(health_check))
        .route("/api/echo", get(echo_id))
        .layer(middleware_stack);

    let addr = SocketAddr::from(([0, 0, 0, 0], 3000));
    let listener = tokio::net::TcpListener::bind(addr).await?;
    info!("Serveur Axum démarré sur http://{}", addr);

    axum::serve(listener, app).await?;

    Ok(())
}

