// src/main.rs
use axum::{
    extract::{rejection::JsonRejection, FromRequest, Request},
    http::StatusCode,
    response::{IntoResponse, Response},
    routing::{get, post},
    Json, Router,
};
use serde::{Deserialize, Serialize};
use std::net::SocketAddr;
use validator::Validate;

/// Custom extractor qui désérialise le JSON et exécute automatiquement
/// la validation déclarative définie via les attributs `validator`.
#[derive(Debug, Clone, Copy, Default)]
pub struct ValidatedJson<T>(pub T);

/// Structure standardisée pour formater les erreurs d'API en JSON.
#[derive(Debug, Serialize)]
pub struct ApiErrorResponse {
    pub error: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub details: Option<serde_json::Value>,
}

pub enum AppError {
    JsonRejection(JsonRejection),
    ValidationError(validator::ValidationErrors),
}

impl IntoResponse for AppError {
    fn into_response(self) -> Response {
        match self {
            AppError::JsonRejection(rejection) => {
                let status = StatusCode::BAD_REQUEST;
                let body = Json(ApiErrorResponse {
                    error: format!("Erreur de payload JSON: {rejection}"),
                    details: None,
                });
                (status, body).into_response()
            }
            AppError::ValidationError(errors) => {
                let status = StatusCode::UNPROCESSABLE_ENTITY;
                let details = serde_json::to_value(&errors).ok();
                let body = Json(ApiErrorResponse {
                    error: "Validation des champs en échec".to_string(),
                    details,
                });
                (status, body).into_response()
            }
        }
    }
}

impl<S, T> FromRequest<S> for ValidatedJson<T>
where
    T: DeserializeOwned + Validate,
    S: Send + Sync,
{
    type Rejection = AppError;

    async fn from_request(req: Request, state: &S) -> Result<Self, Self::Rejection> {
        let Json(value) = Json::<T>::from_request(req, state)
            .await
            .map_err(AppError::JsonRejection)?;

        value.validate().map_err(AppError::ValidationError)?;

        Ok(ValidatedJson(value))
    }
}

