      }

      m.cpus_usage.forEach((val, idx) => {
        const vEl = document.getElementById(`core-val-${idx}`);
        const bEl = document.getElementById(`core-bar-${idx}`);
        if (vEl && bEl) {
          vEl.textContent = `${val.toFixed(0)}%`;
          bEl.style.width = `${Math.min(val, 100)}%`;
        }
      });
    }

    connectSSE();
  </script>
