// src/main.rs
use std::{
    convert::Infallible,
    net::SocketAddr,
    time::Duration,
};

use axum::{
    extract::State,
    response::{
        sse::{Event, KeepAlive, Sse},
        Html, IntoResponse,
    },
    routing::get,
    Router,
};
use serde::Serialize;
use sysinfo::{CpuRefreshKind, Disks, MemoryRefreshKind, RefreshKind, System};
use tokio::sync::broadcast;
use tokio_stream::{wrappers::BroadcastStream, StreamExt};
use tower_http::{
    cors::{Any, CorsLayer},
    trace::TraceLayer,
};
use tracing::{error, info, warn};
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt};

/// Métriques système diffusées aux clients SSE.
#[derive(Debug, Clone, Serialize)]
pub struct SystemMetrics {
    pub timestamp_epoch_ms: u128,
    pub hostname: String,
    pub os_name: String,
    pub os_version: String,
    pub uptime_seconds: u64,
    pub cpu_count: usize,
    pub global_cpu_usage: f32,
    pub cpus_usage: Vec<f32>,
    pub total_memory_bytes: u64,
    pub used_memory_bytes: u64,
    pub memory_usage_percent: f32,
    pub total_swap_bytes: u64,
    pub used_swap_bytes: u64,
    pub swap_usage_percent: f32,
    pub disk_total_bytes: u64,
    pub disk_available_bytes: u64,
    pub disk_usage_percent: f32,
}

/// État partagé de l'application Axum.
#[derive(Clone)]
pub struct AppState {
    pub tx: broadcast::Sender<SystemMetrics>,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialisation du logging avec tracing
    tracing_subscriber::registry()
        .with(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info,tower_http=info".into()),
        )
        .with(tracing_subscriber::fmt::layer())
        .init();

    // Canal de diffusion (broadcast) pour les métriques
    let (tx, _rx) = broadcast::channel::<SystemMetrics>(128);
    let app_state = AppState { tx: tx.clone() };

    // Tâche d'arrière-plan pour la collecte continue des métriques
    let metrics_tx = tx.clone();
    tokio::spawn(async move {
        collect_metrics_loop(metrics_tx, Duration::from_millis(1000)).await;
    });

    // Configuration des permissions CORS pour l'accès navigateur
    let cors = CorsLayer::new()
        .allow_origin(Any)
        .allow_methods(Any)
        .allow_headers(Any);

    // Définition des routes de l'API et de la page Web
    let app = Router::new()
        .route("/", get(index_handler))
        .route("/api/metrics/sse", get(sse_metrics_handler))
        .layer(cors)
        .layer(TraceLayer::new_for_http())
        .with_state(app_state);

    let host = [0, 0, 0, 0];
    let port = 3000;
    let addr = SocketAddr::from((host, port));
    let listener = tokio::net::TcpListener::bind(addr).await?;

    info!("Serveur SSE démarré sur http://127.0.0.1:{}", port);
    info!("Endpoint de streaming SSE : http://127.0.0.1:{}/api/metrics/sse", port);
    info!("Dashboard de monitoring : http://127.0.0.1:{}", port);

    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await?;

    info!("Arrêt propre du serveur terminé.");
    Ok(())
}

/// Boucle de collecte périodique des métriques avec `sysinfo`.
async fn collect_metrics_loop(tx: broadcast::Sender<SystemMetrics>, sample_interval: Duration) {
    let mut system = System::new_with_specifics(
        RefreshKind::nothing()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory(MemoryRefreshKind::everything()),
    );

    // Initialisation du calcul CPU (nécessite deux rafraîchissements distincts)
    system.refresh_cpu_usage();
    tokio::time::sleep(Duration::from_millis(300)).await;

    let hostname = System::host_name().unwrap_or_else(|| "inconnu".to_string());
    let os_name = System::name().unwrap_or_else(|| "Système d'exploitation inconnu".to_string());
    let os_version = System::os_version().unwrap_or_else(|| "Version inconnue".to_string());

    let mut interval = tokio::time::interval(sample_interval);

    loop {
        interval.tick().await;

        system.refresh_cpu_usage();
        system.refresh_memory();

        let disks = Disks::new_with_refreshed_list();
        let (disk_total, disk_avail) = disks.iter().fold((0u64, 0u64), |(total, avail), disk| {
            (total + disk.total_space(), avail + disk.available_space())
        });
        let disk_usage_pct = if disk_total > 0 {
            let used = disk_total.saturating_sub(disk_avail);
            (used as f64 / disk_total as f64 * 100.0) as f32
        } else {
            0.0
        };

        let total_mem = system.total_memory();
        let used_mem = system.used_memory();
        let mem_pct = if total_mem > 0 {
            (used_mem as f64 / total_mem as f64 * 100.0) as f32
        } else {
            0.0
        };

        let total_swap = system.total_swap();
        let used_swap = system.used_swap();
        let swap_pct = if total_swap > 0 {
            (used_swap as f64 / total_swap as f64 * 100.0) as f32
        } else {
            0.0
        };

        let cpus = system.cpus();
        let cpus_usage: Vec<f32> = cpus.iter().map(|c| c.cpu_usage()).collect();
        let global_cpu_usage = system.global_cpu_usage();
        let uptime_seconds = System::uptime();

        let now_ms = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_millis())
            .unwrap_or(0);

        let metrics = SystemMetrics {
            timestamp_epoch_ms: now_ms,
            hostname: hostname.clone(),
            os_name: os_name.clone(),
            os_version: os_version.clone(),
            uptime_seconds,
            cpu_count: cpus.len(),
            global_cpu_usage,
            cpus_usage,
            total_memory_bytes: total_mem,
            used_memory_bytes: used_mem,
            memory_usage_percent: mem_pct,
            total_swap_bytes: total_swap,
            used_swap_bytes: used_swap,
            swap_usage_percent: swap_pct,
            disk_total_bytes: disk_total,
            disk_available_bytes: disk_avail,
            disk_usage_percent: disk_usage_pct,
        };

        // Diffusion : s'il n'y a aucun abonné, `send` renvoie une erreur normale ignorée
        if let Err(_err) = tx.send(metrics) {
            // Aucun client à l'écoute pour l'instant
        }
    }
}

/// Handler SSE pour la diffusion des métriques système aux navigateurs.
async fn sse_metrics_handler(
    State(state): State<AppState>,
) -> Sse<impl tokio_stream::Stream<Item = Result<Event, Infallible>>> {
    let rx = state.tx.subscribe();

    let stream = BroadcastStream::new(rx).filter_map(|msg| match msg {
        Ok(metrics) => match serde_json::to_string(&metrics) {
            Ok(json_payload) => {
                let event = Event::default().event("metrics").data(json_payload);
                Some(Ok(event))
            }
            Err(e) => {
                error!("Erreur de sérialisation JSON des métriques : {}", e);
                None
            }
        },
        Err(tokio_stream::wrappers::errors::BroadcastStreamRecvError::Lagged(missed)) => {
            warn!("Le client SSE a manqué {} messages de métriques", missed);
            None
        }
    });

    Sse::new(stream).keep_alive(
        KeepAlive::new()
            .interval(Duration::from_secs(15))
            .text("keep-alive-ping"),
    )
}

/// Handler pour le tableau de bord HTML/JavaScript connecté en temps réel via EventSource.
async fn index_handler() -> impl IntoResponse {
    Html(DASHBOARD_HTML)
}

/// Attente du signal SIGINT ou SIGTERM pour un arrêt sans interruption brutale.
async fn shutdown_signal() {
    let ctrl_c = async {
        if let Err(err) = tokio::signal::ctrl_c().await {
            error!("Impossible d'écouter l'événement Ctrl+C : {}", err);
        }
    };

    #[cfg(unix)]
    let terminate = async {
        match tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate()) {
            Ok(mut stream) => {
                stream.recv().await;
            }
            Err(err) => {
                error!("Impossible d'écouter le signal SIGTERM : {}", err);
            }
        }
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {
            info!("Signal d'interruption (Ctrl+C) reçu.");
        },
        _ = terminate => {
            info!("Signal de terminaison (SIGTERM) reçu.");
        },
    }
}

