      const evtSource = new EventSource('/api/metrics/sse');

      evtSource.onopen = () => {
        statusDot.classList.add('connected');
        statusText.textContent = 'En ligne (SSE actif)';
      };

      evtSource.addEventListener('metrics', (e) => {
        try {
          const data = JSON.parse(e.data);
          updateUI(data);
          rawJson.textContent = JSON.stringify(data, null, 2);
          lastUpdate.textContent = new Date().toLocaleTimeString();
        } catch (err) {
          console.error("Erreur de décodage SSE JSON:", err);
        }
      });

      evtSource.onerror = (err) => {
        statusDot.classList.remove('connected');
        statusText.textContent = 'Reconnexion...';
        console.warn('Erreur EventSource ou déconnexion temporaire :', err);
      };
    }

    function updateUI(m) {
      sysInfo.textContent = `${m.hostname} (${m.os_name} ${m.os_version}) — En marche depuis : ${formatUptime(m.uptime_seconds)}`;

      // CPU
      const cpuP = m.global_cpu_usage.toFixed(1);
      cpuVal.textContent = `${cpuP}%`;
      cpuBar.style.width = `${Math.min(m.global_cpu_usage, 100)}%`;
      cpuCoresCount.textContent = `${m.cpu_count} cœurs`;

      // RAM
      const ramP = m.memory_usage_percent.toFixed(1);
      ramVal.textContent = `${ramP}%`;
      ramBar.style.width = `${Math.min(m.memory_usage_percent, 100)}%`;
      ramUsed.textContent = formatBytes(m.used_memory_bytes);
      ramTotal.textContent = `/ ${formatBytes(m.total_memory_bytes)}`;

      // Disque
      const diskP = m.disk_usage_percent.toFixed(1);
      diskVal.textContent = `${diskP}%`;
      diskBar.style.width = `${Math.min(m.disk_usage_percent, 100)}%`;
      diskAvail.textContent = `${formatBytes(m.disk_available_bytes)} libres`;
      diskTotal.textContent = `/ ${formatBytes(m.disk_total_bytes)}`;

      // Swap
      const swapP = m.swap_usage_percent.toFixed(1);
      swapVal.textContent = `${swapP}%`;
      swapBar.style.width = `${Math.min(m.swap_usage_percent, 100)}%`;
      swapUsed.textContent = formatBytes(m.used_swap_bytes);
      swapTotal.textContent = `/ ${formatBytes(m.total_swap_bytes)}`;

      // Cores
      if (coresContainer.children.length !== m.cpus_usage.length) {
        coresContainer.innerHTML = '';
        m.cpus_usage.forEach((_, idx) => {
          const box = document.createElement('div');
          box.className = 'core-box';
          box.innerHTML = `
            <div class="core-label">
              <span>Cœur #${idx}</span>
              <span id="core-val-${idx}">0%</span>
            </div>
            <div class="core-bar-bg">
              <div id="core-bar-${idx}" class="core-bar-fill"></div>
            </div>
          `;
          coresContainer.appendChild(box);
        });
      }

      m.cpus_usage.forEach((val, idx) => {
        const vEl = document.getElementById(`core-val-${idx}`);
        const bEl = document.getElementById(`core-bar-${idx}`);
        if (vEl && bEl) {
          vEl.textContent = `${val.toFixed(0)}%`;
          bEl.style.width = `${Math.min(val, 100)}%`;
        }
      });
    }

    connectSSE();
  </script>
</body>
</html>
"#;

