// src/main.rs
use std::time::Duration;
use futures_util::{SinkExt, StreamExt};
use rand::Rng;
use tokio::sync::{mpsc, watch};
use tokio::time::{interval, sleep, MissedTickBehavior};
use tokio_tungstenite::{
    connect_async,
    tungstenite::{protocol::CloseFrame, Message},
};
use tracing::{debug, error, info, warn};
use url::Url;

/// Configuration du client WebSocket à reconnexion automatique.
#[derive(Debug, Clone)]
pub struct ReconnectConfig {
    /// Délai initial avant une tentative de reconnexion.
    pub initial_delay: Duration,
    /// Plafond maximal du délai de reconnexion.
    pub max_delay: Duration,
    /// Facteur d'amplification exponentielle.
    pub factor: f64,
    /// Fraction de gigue aléatoire (ex: 0.25 pour ±25%).
    pub jitter: f64,
    /// Intervalle d'envoi des trames Ping pour maintenir et tester la vivacité de la connexion.
    pub ping_interval: Duration,
}

impl Default for ReconnectConfig {
    fn default() -> Self {
        Self {
            initial_delay: Duration::from_secs(1),
            max_delay: Duration::from_secs(30),
            factor: 1.5,
            jitter: 0.2,
            ping_interval: Duration::from_secs(20),
        }
    }
}

/// Calcul du délai de reconnexion avec backoff exponentiel et gigue.
fn calculate_backoff(attempt: u32, config: &ReconnectConfig) -> Duration {
    let base_secs = config.initial_delay.as_secs_f64() * config.factor.powi(attempt as i32);
    let capped_secs = base_secs.min(config.max_delay.as_secs_f64());

    let mut rng = rand::thread_rng();
    let jitter_factor = 1.0 + rng.gen_range(-config.jitter..config.jitter);
    let final_secs = (capped_secs * jitter_factor).max(config.initial_delay.as_secs_f64());

    Duration::from_secs_f64(final_secs)
}

/// Contrôleur du client WebSocket exposé au reste de l'application.
pub struct ReconnectingWsClient {
    tx_outbound: mpsc::Sender<Message>,
    shutdown_tx: watch::Sender<bool>,
}

impl ReconnectingWsClient {
    /// Démarre le client WebSocket en tâche de fond.
    ///
    /// Retourne un couple `(client, rx_inbound)` où `rx_inbound` fournit les messages reçus du serveur.
    pub fn spawn(
        url: Url,
        config: ReconnectConfig,
        channel_capacity: usize,
    ) -> (Self, mpsc::Receiver<Message>) {
        let (tx_outbound, rx_outbound) = mpsc::channel(channel_capacity);
        let (tx_inbound, rx_inbound) = mpsc::channel(channel_capacity);
        let (shutdown_tx, shutdown_rx) = watch::channel(false);

        let runner = ConnectionRunner {
            url,
            config,
            tx_inbound,
            rx_outbound,
            shutdown_rx,
        };

        tokio::spawn(runner.run());

        (
            Self {
                tx_outbound,
                shutdown_tx,
            },
            rx_inbound,
        )
    }

    /// Envoie un message texte de manière asynchrone dans la file d'émission.
    pub async fn send_text(&self, text: impl Into<String>) -> Result<(), mpsc::error::SendError<Message>> {
        self.tx_outbound.send(Message::Text(text.into())).await
    }

    /// Envoie un message brut (Text, Binary, Ping, etc.) dans la file d'émission.
    pub async fn send_message(&self, message: Message) -> Result<(), mpsc::error::SendError<Message>> {
        self.tx_outbound.send(message).await
    }

