    pub fn shutdown(&self) {
        let _ = self.shutdown_tx.send(true);
    }
}

/// Gestionnaire interne supervisant les cycles de vie de la connexion.
struct ConnectionRunner {
    url: Url,
    config: ReconnectConfig,
    tx_inbound: mpsc::Sender<Message>,
    rx_outbound: mpsc::Receiver<Message>,
    shutdown_rx: watch::Receiver<bool>,
}

impl ConnectionRunner {
    async fn run(mut self) {
        let mut attempt: u32 = 0;

        loop {
            if *self.shutdown_rx.borrow() {
                info!("Signal d'arrêt détecté avant tentative de connexion. Terminaison de la boucle.");
                break;
            }

            info!(
                url = %self.url,
                attempt = attempt,
                "Tentative de connexion WebSocket..."
            );

            match connect_async(self.url.as_str()).await {
                Ok((ws_stream, response)) => {
                    info!(
                        status = %response.status(),
                        "Connexion WebSocket établie avec succès."
                    );
                    attempt = 0;

                    let disconnected = self.handle_session(ws_stream).await;
                    if !disconnected {
                        // Arrêt ordonné demandé par shutdown
                        break;
                    }
                }
                Err(err) => {
                    warn!(
                        error = %err,
                        attempt = attempt,
                        "Échec de l'établissement de la connexion WebSocket."
                    );
                }
            }

            if *self.shutdown_rx.borrow() {
                info!("Arrêt demandé. Fin de la gestion de reconnexion.");
                break;
            }

            let delay = calculate_backoff(attempt, &self.config);
            warn!(
                duration_ms = delay.as_millis(),
                "Attente avant prochaine tentative de reconnexion..."
            );

            tokio::select! {
                _ = sleep(delay) => {
                    attempt = attempt.saturating_add(1);
                }
                _ = self.shutdown_rx.changed() => {
                    if *self.shutdown_rx.borrow() {
                        info!("Interruption de l'attente de reconnexion par signal d'arrêt.");
                        break;
                    }
                }
            }
        }

        info!("Boucle principale du client WebSocket terminée.");
    }

    /// Traite une session active. Retourne `true` si déconnecté de manière inattendue (reconnexion requise),
    /// ou `false` si l'arrêt global a été requis.
    async fn handle_session<S>(&mut self, ws_stream: S) -> bool
    where
        S: StreamExt<Item = Result<Message, tokio_tungstenite::tungstenite::Error>>
            + SinkExt<Message, Error = tokio_tungstenite::tungstenite::Error>
            + Unpin,
    {
        let (mut ws_sink, mut ws_stream) = ws_stream.split();

        let mut ping_timer = interval(self.config.ping_interval);
        ping_timer.set_missed_tick_behavior(MissedTickBehavior::Delay);
        // Consomme le premier tick immédiat de l'interval
        ping_timer.tick().await;

        loop {
            tokio::select! {
                // Vérification d'un signal d'arrêt utilisateur
                _ = self.shutdown_rx.changed() => {
                    if *self.shutdown_rx.borrow() {
                        info!("Signal d'arrêt reçu : fermeture ordonnée de la socket WebSocket.");
                        let close_frame = CloseFrame {
                            code: tokio_tungstenite::tungstenite::protocol::frame::coding::CloseCode::Normal,
                            reason: "Client shutdown".into(),
                        };
                        let _ = ws_sink.send(Message::Close(Some(close_frame))).await;
                        let _ = ws_sink.flush().await;
                        return false;
                    }
                }

                // Tique de heartbeat (Ping)
                _ = ping_timer.tick() => {
                    debug!("Envoi de la trame de heartbeat (Ping)...");
                    if let Err(err) = ws_sink.send(Message::Ping(Vec::new())).await {
                        warn!(error = %err, "Échec d'envoi du Ping. Rupture de la socket présumée.");
                        return true;
                    }
                }

                // Émission d'un message vers le serveur
                maybe_outbound = self.rx_outbound.recv() => {
                    match maybe_outbound {
                        Some(msg) => {
                            debug!(msg_type = ?msg, "Envoi d'un message vers le serveur WebSocket.");
                            if let Err(err) = ws_sink.send(msg).await {
                                error!(error = %err, "Erreur d'écriture sur la socket WebSocket.");
                                return true;
                            }
                        }
                        None => {
                            info!("Canal d'émission fermé (tous les émetteurs ont été libérés). Fermeture.");
                            let _ = ws_sink.send(Message::Close(None)).await;
                            return false;
                        }
                    }
                }

                // Réception d'un message provenant du serveur
                maybe_inbound = ws_stream.next() => {
                    match maybe_inbound {
                        Some(Ok(msg)) => {
                            match &msg {
                                Message::Ping(payload) => {
                                    debug!("Ping reçu du serveur, réponse automatique en Pong.");
                                    if let Err(e) = ws_sink.send(Message::Pong(payload.clone())).await {
                                        warn!(error = %e, "Échec de réponse Pong au serveur.");
                                        return true;
                                    }
                                }
                                Message::Pong(_) => {
                                    debug!("Pong reçu en réponse au heartbeat.");
                                }
                                Message::Close(frame) => {
                                    info!(frame = ?frame, "Trame de fermeture reçue du serveur.");
                                    return true;
                                }
                                Message::Text(_) | Message::Binary(_) => {
                                    if let Err(err) = self.tx_inbound.send(msg).await {
                                        warn!(error = %err, "Canal de réception applicatif fermé.");
                                        return false;
                                    }
                                }
                                Message::Frame(_) => {}
                            }
                        }
                        Some(Err(err)) => {
                            warn!(error = %err, "Erreur réseau de flux WebSocket.");
                            return true;
                        }
                        None => {
                            warn!("Flux WebSocket clos par le pair distant (EOF).");
                            return true;
                        }
                    }
                }
            }
        }
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialisation du logging structuré
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info,ws_reconnecting_client=debug")),
        )
        .init();

    info!("Démarrage de l'application de démonstration WebSocket avec reconnexion.");

    // Serveur WebSocket public d'écho pour les tests (ou remplaçable par ws://127.0.0.1:9001)
    let ws_url = Url::parse("wss://echo.websocket.org")?;

    let config = ReconnectConfig {
        initial_delay: Duration::from_millis(500),
        max_delay: Duration::from_secs(10),
        factor: 1.5,
        jitter: 0.2,
        ping_interval: Duration::from_secs(15),
    };

    let (client, mut inbound_rx) = ReconnectingWsClient::spawn(ws_url, config, 64);

    // Tâche applicative dédiée au traitement des messages entrants
    let receiver_task = tokio::spawn(async move {
        while let Some(msg) = inbound_rx.recv().await {
            match msg {
                Message::Text(txt) => {
                    info!(contenu = %txt, "[App Réception] Message texte reçu.");
                }
                Message::Binary(bin) => {
                    info!(taille = bin.len(), "[App Réception] Message binaire reçu.");
                }
                _ => {}
            }
        }
        info!("[App Réception] Fin de traitement des messages entrants.");
    });

    // Tâche applicative émettant périodiquement des messages de test
    let client_sender = client.tx_outbound.clone();
    let sender_task = tokio::spawn(async move {
        for counter in 1..=5 {
            sleep(Duration::from_secs(2)).await;
            let payload = format!("Ping-test message #{counter} depuis client Rust");
            info!(message = %payload, "[App Envoi] Publication d'un message...");
            if let Err(err) = client_sender.send(Message::Text(payload)).await {
                warn!(error = %err, "[App Envoi] Impossible de déposer le message dans le canal.");
                break;
            }
        }
    });

    // Attente du signal de terminaison (Ctrl+C) ou fin de démonstration
    tokio::select! {
        _ = tokio::signal::ctrl_c() => {
            info!("Signal d'interruption système (SIGINT / Ctrl+C) intercepté.");
        }
        _ = sender_task => {
            info!("Série d'envois applicatifs terminée. Maintien actif temporaire...");
            sleep(Duration::from_secs(5)).await;
        }
    }

    info!("Arrêt en cours du client WebSocket...");
    client.shutdown();

    // Attente brève pour permettre le flush et l'envoi de la trame Close
    sleep(Duration::from_millis(500)).await;
    let _ = receiver_task.await;

    info!("Application clôturée proprement.");
    Ok(())
}

