```rust
// src/main.rs
use std::io;
use std::net::{Ipv4Addr, Ipv6Addr, SocketAddr, SocketAddrV4, SocketAddrV6};
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::{TcpListener, TcpStream};
use tracing::{debug, error, info, warn};

// Constantes RFC 1928 (Protocole SOCKS Version 5)
const SOCKS_VERSION: u8 = 0x05;
const AUTH_NO_AUTHENTICATION_REQUIRED: u8 = 0x00;
const AUTH_NO_ACCEPTABLE_METHODS: u8 = 0xFF;

const CMD_CONNECT: u8 = 0x01;

const ATYP_IPV4: u8 = 0x01;
const ATYP_DOMAIN: u8 = 0x03;
const ATYP_IPV6: u8 = 0x04;

const REP_SUCCESS: u8 = 0x00;
const REP_GENERAL_FAILURE: u8 = 0x01;
const REP_HOST_UNREACHABLE: u8 = 0x04;
const REP_CONNECTION_REFUSED: u8 = 0x05;
const REP_COMMAND_NOT_SUPPORTED: u8 = 0x07;
const REP_ADDRESS_TYPE_NOT_SUPPORTED: u8 = 0x08;

#[derive(Debug)]
enum TargetAddress {
    Socket(SocketAddr),
    Domain(String, u16),
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "socks5_proxy=info".into()),
        )
        .init();

    let listen_addr = std::env::var("SOCKS5_BIND").unwrap_or_else(|_| "127.0.0.1:1080".to_string());
    let listener = TcpListener::bind(&listen_addr).await?;
    info!("Serveur SOCKS5 démarré sur {}", listen_addr);

    loop {
        match listener.accept().await {
            Ok((stream, client_addr)) => {
                debug!("Nouvelle connexion entrante depuis {}", client_addr);
                tokio::spawn(async move {
                    if let Err(err) = handle_client(stream, client_addr).await {
                        debug!("Fin de connexion pour {} : {}", client_addr, err);
                    }
                });
            }
            Err(err) => {
                error!("Erreur lors de l'acceptation d'une connexion TCP : {}", err);
            }
        }
    }
}

async fn handle_client(mut stream: TcpStream, client_addr: SocketAddr) -> io::Result<()> {
    // 1. Négociation des méthodes d'authentification
    negotiate_auth(&mut stream).await?;

    // 2. Traitement de la requête client
    let target = match parse_request(&mut stream).await {
        Ok(addr) => addr,
        Err(err) => {
            warn!("Requête invalide de {} : {}", client_addr, err);
            return Err(err);
        }
    };

    info!("Connexion demandée par {} vers {:?}", client_addr, target);

    // 3. Établissement de la connexion vers la cible
    let mut outbound = match connect_target(&target).await {
        Ok(outbound) => {
            let local_addr = outbound.local_addr().ok();
            send_reply(&mut stream, REP_SUCCESS, local_addr).await?;
            outbound
        }
        Err(err) => {
            let rep_code = match err.kind() {
                io::ErrorKind::ConnectionRefused => REP_CONNECTION_REFUSED,
                io::ErrorKind::AddrNotAvailable | io::ErrorKind::TimedOut => REP_HOST_UNREACHABLE,
                _ => REP_GENERAL_FAILURE,
            };
            let _ = send_reply(&mut stream, rep_code, None).await;
            return Err(err);
        }
    };

    // 4. Relais bidirectionnel asynchrone des flux TCP
    match tokio::io::copy_bidirectional(&mut stream, &mut outbound).await {
        Ok((from_client, from_target)) => {
            debug!(
                "Connexion terminée pour {} : {} octets envoyés, {} octets reçus",
                client_addr, from_client, from_target
            );
        }
        Err(err) => {
            debug!("Interruption du transfert pour {} : {}", client_addr, err);
        }
    }

    debug!("Connexion terminée pour {}", client_addr);
    Ok(())
}

async fn negotiate_auth(stream: &mut TcpStream) -> io::Result<()> {
    let mut header = [0u8; 2];
    stream.read_exact(&mut header).await?;

    let version = header[0];
    let nmethods = header[1] as usize;

    if version != SOCKS_VERSION {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("Version non supportée : 0x{:02X}", version),
        ));
    }

    let mut methods = vec![0u8; nmethods];
    stream.read_exact(&mut methods).await?;

    if methods.contains(&AUTH_NO_AUTHENTICATION_REQUIRED) {
        stream.write_all(&[SOCKS_VERSION, AUTH_NO_AUTHENTICATION_REQUIRED]).await?;
        stream.flush().await?;
        Ok(())
    } else {
        stream.write_all(&[SOCKS_VERSION, AUTH_NO_ACCEPTABLE_METHODS]).await?;
        stream.flush().await?;
        Err(io::Error::new(
            io::ErrorKind::PermissionDenied,
            "Aucune méthode d'authentification commune (seul NO_AUTH est supporté)",
        ))
    }
}

async fn parse_request(stream: &mut TcpStream) -> io::Result<TargetAddress> {
    let mut header = [0u8; 4];
    stream.read_exact(&mut header).await?;

    let version = header[0];
    let command = header[1];
    let _reserved = header[2];
    let address_type = header[3];

    if version != SOCKS_VERSION {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "Version non supportée dans la requête",
        ));
    }

    if command != CMD_CONNECT {
        let _ = send_reply(stream, REP_COMMAND_NOT_SUPPORTED, None).await;
        return Err(io::Error::new(
            io::ErrorKind::Unsupported,
            format!("Commande 0x{:02X} non supportée (seul CONNECT est géré)", command),
        ));
    }

    let target = match address_type {
        ATYP_IPV4 => {
            let mut octets = [0u8; 4];
            stream.read_exact(&mut octets).await?;
            let port = stream.read_u16().await?;
            let ip = Ipv4Addr::from(octets);
            TargetAddress::Socket(SocketAddr::V4(SocketAddrV4::new(ip, port)))
        }
        ATYP_IPV6 => {
            let mut octets = [0u8; 16];
            stream.read_exact(&mut octets).await?;
            let port = stream.read_u16().await?;
            let ip = Ipv6Addr::from(octets);
            TargetAddress::Socket(SocketAddr::V6(SocketAddrV6::new(ip, port, 0, 0)))
        }
        ATYP_DOMAIN => {
            let domain_len = stream.read_u8().await? as usize;
            let mut domain_buf = vec![0u8; domain_len];
            stream.read_exact(&mut domain_buf).await?;
            let port = stream.read_u16().await?;

            let domain = String::from_utf8(domain_buf).map_err(|e| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("Nom de domaine non UTF-8 : {}", e),
                )
            })?;
            TargetAddress::Domain(domain, port)
        }
        _ => {
            let _ = send_reply(stream, REP_ADDRESS_TYPE_NOT_SUPPORTED, None).await;
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("Type d'adresse 0x{:02X} non supporté", address_type),
            ));
        }
    };

    Ok(target)
}

async fn connect_target(target: &TargetAddress) -> io::Result<TcpStream> {
    match target {
        TargetAddress::Socket(addr) => TcpStream::connect(addr).await,
        TargetAddress::Domain(domain, port) => TcpStream::connect((domain.as_str(), *port)).await,
    }
}

async fn send_reply(
    stream: &mut TcpStream,
    reply_code: u8,
    bind_addr: Option<SocketAddr>,
) -> io::Result<()> {
    let mut response = Vec::with_capacity(22);
    response.push(SOCKS_VERSION);
    response.push(reply_code);
    response.push(0x00); // Reserved

    match bind_addr {
        Some(SocketAddr::V4(addr)) => {
            response.push(ATYP_IPV4);
            response.extend_from_slice(&addr.ip().octets());
            response.extend_from_slice(&addr.port().to_be_bytes());
        }
        Some(SocketAddr::V6(addr)) => {
            response.push(ATYP_IPV6);
            response.extend_from_slice(&addr.ip().octets());
            response.extend_from_slice(&addr.port().to_be_bytes());
        }
        None => {
            // Adresse liée par défaut (0.0.0.0:0) en cas d'erreur ou d'adresse indisponible
            response.push(ATYP_IPV4);
            response.extend_from_slice(&[0, 0, 0, 0]);
            response.extend_from_slice(&[0, 0]);
        }
    }

    stream.write_all(&response).await?;
    stream.flush().await?;
    Ok(())
}

