#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LogEntry {
    pub id: u64,
    pub timestamp: DateTime<Utc>,
    pub level: String,
    pub source: String,
    pub message: String,
}

#[derive(Clone)]
pub struct AppState {
    pub logs: Arc<RwLock<Vec<LogEntry>>>,
}

#[derive(Debug, Deserialize)]
pub struct LogQueryParams {
    #[serde(default = "default_page")]
    pub page: usize,
    #[serde(default = "default_limit")]
    pub limit: usize,
    pub filter: Option<String>,
    pub level: Option<String>,
}

fn default_page() -> usize {
    1
}

fn default_limit() -> usize {
    50
}

#[derive(Debug, Serialize)]
pub struct PaginatedResponse<T> {
    pub items: Vec<T>,
    pub page: usize,
    pub limit: usize,
    pub total_items: usize,
    pub total_pages: usize,
}

#[derive(Debug)]
pub enum AppError {
    InvalidRegex(String),
    TaskJoinError(String),
}

impl IntoResponse for AppError {
    fn into_response(self) -> Response {
        let (status, error_message) = match self {
            AppError::InvalidRegex(err) => (
                StatusCode::BAD_REQUEST,
                format!("Erreur dans l'expression régulière : {}", err),
            ),
            AppError::TaskJoinError(err) => (
                StatusCode::INTERNAL_SERVER_ERROR,
                format!("Erreur lors de l'exécution asynchrone : {}", err),
            ),
        };

        let body = Json(serde_json::json!({
            "error": error_message
        }));

        (status, body).into_response()
    }
}

async fn health_check() -> impl IntoResponse {
    Json(serde_json::json!({
        "status": "ok",
        "service": "axum-log-stream"
    }))
}

async fn get_logs(
    State(state): State<AppState>,
    Query(params): Query<LogQueryParams>,
) -> Result<Json<PaginatedResponse<LogEntry>>, AppError> {
    let page = params.page.max(1);
    let limit = params.limit.clamp(1, 1000);

    // Snapshot des logs pour éviter de bloquer le RwLock pendant le traitement CPU
    let logs_snapshot = {
        let read_guard = state.logs.read().await;
        read_guard.clone()
    };

    let filter_pattern = params.filter;
    let level_filter = params.level;

    // Déportation du calcul de filtrage regex sur un thread bloquant Tokio dédié
    let filtered_logs = tokio::task::spawn_blocking(move || -> Result<Vec<LogEntry>, AppError> {
        let compiled_regex = match filter_pattern {
            Some(ref pattern) => match Regex::new(pattern) {
                Ok(re) => Some(re),
                Err(err) => return Err(AppError::InvalidRegex(err.to_string())),
            },
            None => None,
        };

        let iter = logs_snapshot.into_iter().filter(|entry| {
            if let Some(ref lvl) = level_filter {
                if !entry.level.eq_ignore_ascii_case(lvl) {
                    return false;
                }
            }

            if let Some(ref re) = compiled_regex {
                re.is_match(&entry.message) || re.is_match(&entry.source)
            } else {
                true
            }
        });

        Ok(iter.collect())
    })
    .await
    .map_err(|join_err| AppError::TaskJoinError(join_err.to_string()))??;

    let total_items = filtered_logs.len();
    let total_pages = if total_items == 0 {
        1
    } else {
        (total_items + limit - 1) / limit
    };

    let start = (page - 1) * limit;
    let paginated_items = if start >= total_items {
        Vec::new()
    } else {
        let end = (start + limit).min(total_items);
        filtered_logs[start..end].to_vec()
    };

    Ok(Json(PaginatedResponse {
        items: paginated_items,
        page,
        limit,
        total_items,
        total_pages,
    }))
}

fn generate_mock_logs(count: usize) -> Vec<LogEntry> {
    let levels = ["INFO", "WARN", "ERROR", "DEBUG"];
    let sources = ["auth-service", "payment-gateway", "api-gateway", "database"];
    let messages = [
        "User authentication succeeded",
        "Connection timeout to upstream provider",
        "Failed database transaction retry exhausted",
        "Query executed in 4.2ms",
        "Payload signature verification failed",
        "Cache hit for user session token",
        "Rate limit quota exceeded for IP 192.168.1.42",
        "Background maintenance task completed successfully",
    ];

    let base_time = Utc::now();

    (0..count)
        .map(|i| {
            let offset_secs = (count - i) as i64 * 3;
            LogEntry {
                id: (i + 1) as u64,
                timestamp: base_time - chrono::Duration::seconds(offset_secs),
                level: levels[i % levels.len()].to_string(),
                source: sources[i % sources.len()].to_string(),
                message: format!("{} [trace_id: #{:06x}]", messages[i % messages.len()], i * 37),
            }
        })
        .collect()
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "axum_log_stream=debug,tower_http=info".into()),
        )
        .init();

    info!("Initialisation du jeu de logs de démonstration...");
    let initial_logs = generate_mock_logs(2000);
    let app_state = AppState {
        logs: Arc::new(RwLock::new(initial_logs)),
    };

    let app = Router::new()
        .route("/health", get(health_check))
        .route("/api/logs", get(get_logs))
        .layer(TraceLayer::new_for_http())
        .with_state(app_state);

    let addr = SocketAddr::from(([127, 0, 0, 1], 3000));
    info!("Serveur à l'écoute sur http://{}", addr);

    let listener = tokio::net::TcpListener::bind(&addr).await?;
    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await?;

    Ok(())
}

async fn shutdown_signal() {
    let ctrl_c = async {
        if let Err(err) = tokio::signal::ctrl_c().await {
            error!("Erreur lors de la capture du signal Ctrl+C : {}", err);
        }
    };

    #[cfg(unix)]
    let terminate = async {
        match tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate()) {
            Ok(mut stream) => {
                stream.recv().await;
            }
            Err(err) => {
                error!("Erreur lors de l'enregistrement du signal SIGTERM : {}", err);
            }
        }
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {
            info!("Signal d'arrêt (Ctrl+C) reçu, fermeture propre...");
        },
        _ = terminate => {
            info!("Signal SIGTERM reçu, fermeture propre...");
        },
    }
}

