```rust
// src/main.rs
use std::collections::HashMap;
use std::sync::Arc;
use std::time::Duration;
use thiserror::Error;
use tokio::sync::{mpsc, Mutex, RwLock, Semaphore};
use tokio::time::{sleep, Instant};
use tracing::{error, info, warn};
use url::Url;

#[derive(Debug, Error)]
pub enum ScraperError {
    #[error("URL parsing error: {0}")]
    UrlParse(#[from] url::ParseError),

    #[error("No valid host could be extracted from: {0}")]
    MissingHost(String),

    #[error("HTTP request failed: {0}")]
    Reqwest(#[from] reqwest::Error),
}

/// Résultat d'une tâche de scraping
#[derive(Debug)]
pub struct ScrapeResult {
    pub url: String,
    pub status: u16,
    pub bytes_len: usize,
    pub elapsed: Duration,
}

/// Gestionnaire de politesse par domaine.
/// Maintient pour chaque domaine l'instant avant lequel aucune nouvelle requête ne doit être initiée.
#[derive(Clone)]
pub struct DomainPolitenessManager {
    delay_per_domain: Duration,
    // Verrou fin par domaine : RwLock protège la table des domaines,
    // Mutex<Instant> protège le prochain instant disponible pour un domaine donné.
    domain_locks: Arc<RwLock<HashMap<String, Arc<Mutex<Instant>>>>>,
}

impl DomainPolitenessManager {
    pub fn new(delay_per_domain: Duration) -> Self {
        Self {
            delay_per_domain,
            domain_locks: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    /// Extrait le domaine/hôte d'une URL
    fn extract_domain(raw_url: &str) -> Result<String, ScraperError> {
        let parsed = Url::parse(raw_url)?;
        parsed
            .host_str()
            .map(|h| h.to_ascii_lowercase())
            .ok_or_else(|| ScraperError::MissingHost(raw_url.to_string()))
    }

    /// Récupère ou instancie le verrou de politesse pour un domaine
    async fn get_domain_lock(&self, domain: &str) -> Arc<Mutex<Instant>> {
        // Lecture rapide pour vérifier si le domaine existe déjà
        {
            let map_read = self.domain_locks.read().await;
            if let Some(lock) = map_read.get(domain) {
                return Arc::clone(lock);
            }
        }

        // Sinon écriture pour insérer le nouveau domaine
        let mut map_write = self.domain_locks.write().await;
        Arc::clone(
            map_write
                .entry(domain.to_string())
                .or_insert_with(|| Arc::new(Mutex::new(Instant::now()))),
        )
    }

    /// Attend le respect du délai de politesse pour le domaine spécifié.
    /// Met à jour l'horodatage réservé pour la prochaine requête sur ce même domaine.
    pub async fn wait_turn(&self, raw_url: &str) -> Result<String, ScraperError> {
        let domain = Self::extract_domain(raw_url)?;
        let domain_mutex = self.get_domain_lock(&domain).await;

        // On acquiert le mutex propre au domaine : les autres domaines continuent en parallèle !
        let mut next_available_at = domain_mutex.lock().await;
        let now = Instant::now();

        if *next_available_at > now {
            let wait_duration = *next_available_at - now;
            sleep(wait_duration).await;
        }

        // On réserve le prochain créneau pour ce domaine
        *next_available_at = Instant::now() + self.delay_per_domain;

        Ok(domain)
    }
}

/// Client HTTP de scraping poli
#[derive(Clone)]
pub struct PoliteScraper {
    client: reqwest::Client,
    politeness: DomainPolitenessManager,
}

impl PoliteScraper {
    pub fn new(politeness_delay: Duration, request_timeout: Duration) -> Result<Self, ScraperError> {
        let client = reqwest::Client::builder()
            .user_agent("PoliteScraperBot/1.0 (+https://example.com/bot)")
            .timeout(request_timeout)
            .build()?;

        Ok(Self {
            client,
            politeness: DomainPolitenessManager::new(politeness_delay),
        })
    }

    pub async fn fetch(&self, raw_url: &str) -> Result<ScrapeResult, ScraperError> {
        let start_time = Instant::now();

        // 1. Attente active de notre tour pour ce domaine
        let domain = self.politeness.wait_turn(raw_url).await?;
        info!(domain = %domain, url = %raw_url, "Exécution de la requête HTTP autorisée");

        // 2. Exécution de la requête HTTP
        let response = self.client.get(raw_url).send().await?;
        let status = response.status().as_u16();
        let bytes = response.bytes().await?;

        Ok(ScrapeResult {
            url: raw_url.to_string(),
            status,
            bytes_len: bytes.len(),
            elapsed: start_time.elapsed(),
        })
    }
}

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    info!("Démarrage du worker de scraping concurrent...");

    let politeness_delay = Duration::from_millis(1500);
    let request_timeout = Duration::from_secs(10);
    let max_concurrency = 8;

    let scraper = match PoliteScraper::new(politeness_delay, request_timeout) {
        Ok(s) => s,
        Err(err) => {
            error!(error = %err, "Impossible d'initialiser le PoliteScraper");
            return;
        }
    };

    // Liste d'URLs de test réparties sur plusieurs domaines pour démontrer la concurrence multi-domaine
    // et le respect du délai de politesse intra-domaine.
    let urls_to_scrape = vec![
        "https://httpbin.org/delay/0",
        "https://httpbin.org/get",
        "https://httpbin.org/headers",
        "https://example.com/",
        "https://example.com/index.html",
        "https://www.rust-lang.org/",
        "https://www.rust-lang.org/learn",
        "https://crates.io/",
    ];

    let (tx, mut rx) = mpsc::channel::<ScrapeResult>(32);
    let semaphore = Arc::new(Semaphore::new(max_concurrency));

    let mut handles = Vec::new();

    for url in urls_to_scrape {
        let scraper = scraper.clone();
        let tx = tx.clone();
        let sem = Arc::clone(&semaphore);
        let url_owned = url.to_string();

        let handle = tokio::spawn(async move {
            let _permit = match sem.acquire().await {
                Ok(p) => p,
                Err(e) => {
                    error!(error = %e, "Erreur d'acquisition du sémaphore");
                    return;
                }
            };

            match scraper.fetch(&url_owned).await {
                Ok(result) => {
                    if let Err(e) = tx.send(result).await {
                        warn!(error = %e, "Échec d'envoi du résultat sur le channel");
                    }
                }
                Err(err) => {
                    warn!(url = %url_owned, error = %err, "Échec du scraping pour l'URL");
                }
            }
        });

        handles.push(handle);
    }

    // Fermeture du canal émetteur principal pour que le récepteur puisse terminer après les workers
    drop(tx);

    // Tâche d'affichage / traitement des résultats
    let collector = tokio::spawn(async move {
        let mut count = 0;
        while let Some(res) = rx.recv().await {
            count += 1;
            info!(
                index = count,
                status = res.status,
                bytes = res.bytes_len,
                elapsed_ms = res.elapsed.as_millis(),
                url = %res.url,
                "Résultat collecté avec succès"
            );
        }
        count
    });

    // Attente de toutes les tâches de scraping
    for handle in handles {
        if let Err(e) = handle.await {
            error!(error = %e, "Une tâche de scraping s'est terminée avec une erreur de join");
        }
    }

    let total_scraped = match collector.await {
        Ok(count) => count,
        Err(e) => {
            error!(error = %e, "Erreur lors de l'attente du collector");
            0
        }
    };

    info!(total = total_scraped, "Session de scraping terminée avec succès");
}

