// src/main.rs
use std::net::SocketAddr;
use axum::{
    extract::Json,
    http::StatusCode,
    response::{IntoResponse, Response},
    routing::{get, post},
    Router,
};
use scraper::{Html, Selector};
use serde::{Deserialize, Serialize};
use tower_http::trace::TraceLayer;
use tracing::{error, info};

const DEFAULT_LINE_WIDTH: usize = 80;
const MIN_LINE_WIDTH: usize = 20;
const MAX_LINE_WIDTH: usize = 300;

#[derive(Debug, Deserialize)]
pub struct ConvertRequest {
    pub html: String,
    pub line_width: Option<usize>,
}

#[derive(Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct ExtractedLink {
    pub url: String,
    pub text: String,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct ConvertResponse {
    pub plain_text: String,
    pub links: Vec<ExtractedLink>,
    pub link_count: usize,
}

#[derive(Debug, Serialize)]
pub struct ErrorResponse {
    pub error: String,
}

pub enum AppError {
    InvalidInput(String),
}

impl IntoResponse for AppError {
    fn into_response(self) -> Response {
        let (status, message) = match self {
            AppError::InvalidInput(msg) => (StatusCode::BAD_REQUEST, msg),
        };
        (status, Json(ErrorResponse { error: message })).into_response()
    }
}

/// Extrait tous les liens `<a href="...">...</a>` d'un document HTML.
pub fn extract_links(html: &str) -> Vec<ExtractedLink> {
    let document = Html::parse_document(html);
    let selector = match Selector::parse("a[href]") {
        Ok(s) => s,
        Err(err) => {
            error!("Erreur de compilation du sélecteur CSS: {:?}", err);
            return Vec::new();
        }
    };

    let mut links = Vec::new();
    for element in document.select(&selector) {
        if let Some(href) = element.value().attr("href") {
            let trimmed_href = href.trim();
            if !trimmed_href.is_empty() {
                let text: String = element
                    .text()
                    .collect::<Vec<_>>()
                    .join(" ")
                    .split_whitespace()
                    .collect::<Vec<_>>()
                    .join(" ");

                links.push(ExtractedLink {
                    url: trimmed_href.to_string(),
                    text,
                });
            }
        }
    }
    links
}

/// Convertit le contenu HTML en texte brut formaté.
pub fn clean_and_convert_html(html: &str, line_width: usize) -> String {
    let text = html2text::from_read(html.as_bytes(), line_width);
    text.trim().to_string()
}

pub async fn health_check() -> Json<serde_json::Value> {
    Json(serde_json::json!({
        "status": "ok"
    }))
}

pub async fn convert_html_handler(
    Json(payload): Json<ConvertRequest>,
) -> Result<Json<ConvertResponse>, AppError> {
    let line_width = payload.line_width.unwrap_or(DEFAULT_LINE_WIDTH);

    if !(MIN_LINE_WIDTH..=MAX_LINE_WIDTH).contains(&line_width) {
        return Err(AppError::InvalidInput(format!(
            "line_width doit être compris entre {} et {}.",
            MIN_LINE_WIDTH, MAX_LINE_WIDTH
        )));
    }

    let links = extract_links(&payload.html);
    let plain_text = clean_and_convert_html(&payload.html, line_width);
    let link_count = links.len();

    Ok(Json(ConvertResponse {
        plain_text,
        links,
        link_count,
    }))
}

pub fn create_router() -> Router {
    Router::new()
        .route("/health", get(health_check))
        .route("/api/convert", post(convert_html_handler))
        .layer(TraceLayer::new_for_http())
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "html_text_extractor=debug,tower_http=debug".into()),
        )
        .init();

    let app = create_router();
    let addr = SocketAddr::from(([127, 0, 0, 1], 3000));
    info!("Démarrage du service d'extraction sur http://{}", addr);

    let listener = tokio::net::TcpListener::bind(addr).await?;
    axum::serve(listener, app).await?;

    Ok(())
}

#[cfg(test)]
