        let html = r#"
            <div>
                <h1>Bienvenue</h1>
                <p>Visitez notre <a href="https://rust-lang.org">site officiel</a>.</p>
                <p><a href="/contact">   Nous contacter   </a></p>
                <p><a>Lien sans href</a></p>
            </div>
        "#;

        let links = extract_links(html);
        assert_eq!(links.len(), 2);
        assert_eq!(
            links[0],
            ExtractedLink {
                url: "https://rust-lang.org".to_string(),
                text: "site officiel".to_string(),
            }
        );
        assert_eq!(
            links[1],
            ExtractedLink {
                url: "/contact".to_string(),
                text: "Nous contacter".to_string(),
            }
        );
    }

    #[test]
    fn test_clean_and_convert_html() {
        let html = "<h1>Titre</h1><p>Paragraphe avec <strong>mise en gras</strong>.</p>";
        let text = clean_and_convert_html(html, 80);
        assert!(text.contains("Titre"));
        assert!(text.contains("mise en gras"));
    }

    #[tokio::test]
    async fn test_convert_endpoint() {
        use axum::body::Body;
        use axum::http::Request;
        use tower::ServiceExt;

        let app = create_router();
        let payload = serde_json::json!({
            "html": "<h2>Section</h2><p>Voir <a href=\"https://example.com\">ce lien</a>.</p>",
            "line_width": 60
        });

        let request = Request::builder()
            .method("POST")
            .uri("/api/convert")
            .header("Content-Type", "application/json")
            .body(Body::from(serde_json::to_vec(&payload).unwrap()))
            .unwrap();

        let response = app.oneshot(request).await.unwrap();
        assert_eq!(response.status(), StatusCode::OK);

        let body_bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        let convert_res: ConvertResponse = serde_json::from_slice(&body_bytes).unwrap();

        assert_eq!(convert_res.link_count, 1);
        assert_eq!(convert_res.links[0].url, "https://example.com");
        assert_eq!(convert_res.links[0].text, "ce lien");
        assert!(convert_res.plain_text.contains("Section"));
    }
}

