// src/main.rs
use std::sync::Arc;
use std::time::Duration;

use futures::stream::{self, StreamExt};
use serde::{Deserialize, Serialize};
use thiserror::Error;
use tokio::sync::mpsc;
use tokio::time::{interval, Instant};
use tracing::{error, info, warn};
use uuid::Uuid;
use wiremock::matchers::{method, path};
use wiremock::{Mock, MockServer, ResponseTemplate};

/// Erreurs spécifiques à la passerelle de notification push.
#[derive(Debug, Error)]
pub enum GatewayError {
    #[error("Erreur réseau HTTP : {0}")]
    Network(#[from] reqwest::Error),

    #[error("Échec de transmission vers le serveur mock/push : code statut {status}")]
    DeliveryFailed { status: reqwest::StatusCode },

    #[error("Erreur d'envoi dans le canal interne de notification")]
    ChannelSendError,
}

/// Modèle d'une notification push.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PushNotification {
    pub id: Uuid,
    pub recipient_token: String,
    pub title: String,
    pub body: String,
    pub priority: NotificationPriority,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum NotificationPriority {
    High,
    Normal,
    Low,
}

/// Résultat de l'expédition d'une notification.
#[derive(Debug, Serialize, Deserialize)]
pub struct PushDeliveryReport {
    pub notification_id: Uuid,
    pub success: bool,
    pub status_code: u16,
}

/// Configuration du processeur de lot (batching).
#[derive(Debug, Clone)]
pub struct BatchConfig {
    pub max_batch_size: usize,
    pub flush_interval: Duration,
    pub max_concurrent_requests: usize,
}

impl Default for BatchConfig {
    fn default() -> Self {
        Self {
            max_batch_size: 5,
            flush_interval: Duration::from_millis(150),
            max_concurrent_requests: 4,
        }
    }
}

/// Client d'envoi HTTP asynchrone des notifications.
#[derive(Clone)]
pub struct PushHttpClient {
    client: reqwest::Client,
    endpoint_url: Arc<String>,
}

impl PushHttpClient {
    pub fn new(endpoint_url: String) -> Self {
        let client = reqwest::Client::builder()
            .timeout(Duration::from_secs(5))
            .pool_max_idle_per_host(10)
            .build()
            .unwrap_or_else(|_| reqwest::Client::new());

        Self {
            client,
            endpoint_url: Arc::new(endpoint_url),
        }
    }

    /// Envoie une notification unique de manière asynchrone.
    pub async fn send_single(&self, notification: PushNotification) -> Result<PushDeliveryReport, GatewayError> {
        let response = self
            .client
            .post(self.endpoint_url.as_str())
            .json(&notification)
            .send()
            .await?;

        let status = response.status();
        if status.is_success() {
            Ok(PushDeliveryReport {
                notification_id: notification.id,
                success: true,
                status_code: status.as_u16(),
            })
        } else {
            Err(GatewayError::DeliveryFailed { status })
        }
    }

    /// Traite un lot entier de notifications avec contrôle de concurrence sous Tokio.
    pub async fn send_batch(
        &self,
        batch: Vec<PushNotification>,
        concurrency_limit: usize,
    ) -> Vec<PushDeliveryReport> {
        let count = batch.len();
        let start_time = Instant::now();

        info!(batch_size = count, "Début de l'expédition du lot de notifications");

        let reports = stream::iter(batch)
            .map(|notif| {
                let client = self.clone();
                let notif_id = notif.id;
                async move {
                    match client.send_single(notif).await {
                        Ok(report) => report,
                        Err(err) => {
                            warn!(
                                notification_id = %notif_id,
                                error = %err,
                                "Échec d'envoi de notification dans le lot"
                            );
                            PushDeliveryReport {
                                notification_id: notif_id,
                                success: false,
                                status_code: match err {
                                    GatewayError::DeliveryFailed { status } => status.as_u16(),
                                    _ => 0,
                                },
                            }
                        }
                    }
                }
            })
            .buffer_unordered(concurrency_limit)
            .collect::<Vec<_>>()
            .await;

        let elapsed = start_time.elapsed();
        info!(
            batch_size = count,
            duration_ms = elapsed.as_millis(),
            "Lot de notifications traité avec succès"
        );

        reports
    }
}

/// Démarrage de la tâche d'arrière-plan Tokio assurant l'accumulation par lot et le vidage temporel.
pub fn start_batch_dispatcher(
    mut receiver: mpsc::Receiver<PushNotification>,
    client: PushHttpClient,
    config: BatchConfig,
) -> tokio::task::JoinHandle<()> {
    tokio::spawn(async move {
        let mut buffer: Vec<PushNotification> = Vec::with_capacity(config.max_batch_size);
        let mut ticker = interval(config.flush_interval);

        loop {
            tokio::select! {
                // Branche 1 : Réception d'un élément
                maybe_item = receiver.recv() => {
                    match maybe_item {
                        Some(notification) => {
                            buffer.push(notification);
                            if buffer.len() >= config.max_batch_size {
                                let current_batch = std::mem::take(&mut buffer);
                                client.send_batch(current_batch, config.max_concurrent_requests).await;
                            }
                        }
                        None => {
                            // Le canal d'ingestion a été fermé, on vide le reste avant arrêt.
                            if !buffer.is_empty() {
                                let current_batch = std::mem::take(&mut buffer);
                                client.send_batch(current_batch, config.max_concurrent_requests).await;
                            }
                            info!("Canal de notification fermé, arrêt du dispatcher de batch");
                            break;
                        }
                    }
                }

                // Branche 2 : Vidage régulier par expiration du timer d'intervalle
                _ = ticker.tick() => {
                    if !buffer.is_empty() {
                        let current_batch = std::mem::take(&mut buffer);
                        info!("Déclenchement du batch suite à l'expiration de l'intervalle de flush");
                        client.send_batch(current_batch, config.max_concurrent_requests).await;
                    }
                }
            }
        }
    })
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialisation du logging structuré
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    info!("Initialisation de la passerelle de notification push simulée...");

    // 1. Démarrage d'un serveur HTTP Mock local avec wiremock
    let mock_server = MockServer::start().await;
    Mock::given(method("POST"))
        .and(path("/v1/push/send"))
        .respond_with(ResponseTemplate::new(200).set_delay(Duration::from_millis(50)))
        .mount(&mock_server)
        .await;

    let target_endpoint = format!("{}/v1/push/send", mock_server.uri());
    info!(target_endpoint = %target_endpoint, "Serveur Mock démarré");

    // 2. Configuration du pipeline
    let batch_config = BatchConfig {
        max_batch_size: 5,
        flush_interval: Duration::from_millis(200),
        max_concurrent_requests: 3,
    };

    let (sender, receiver) = mpsc::channel::<PushNotification>(100);
    let http_client = PushHttpClient::new(target_endpoint);

    // 3. Lancement de la tâche d'arrière-plan Tokio
    let dispatcher_handle = start_batch_dispatcher(receiver, http_client, batch_config);

    // 4. Émission concurrente simulée de notifications (rafale)
    let total_notifications = 14;
    info!(total = total_notifications, "Génération d'une vague de notifications push...");

    for i in 1..=total_notifications {
        let notification = PushNotification {
            id: Uuid::new_v4(),
            recipient_token: format!("device-fcm-token-{:04}", i),
            title: format!("Alerte de service #{}", i),
            body: format!("Ceci est le contenu de la notification asynchrone #{}.", i),
            priority: if i % 3 == 0 {
                NotificationPriority::High
            } else {
                NotificationPriority::Normal
            },
        };

        if let Err(e) = sender.send(notification).await {
            error!(error = %e, "Impossible d'insérer la notification dans le buffer");
            return Err(GatewayError::ChannelSendError.into());
        }

        // Simuler un léger décalage temporel aléatoire ou périodique
        if i == 6 {
            tokio::time::sleep(Duration::from_millis(300)).await;
        }
    }

    // Fermeture propre du canal pour signaler l'arrêt au dispatcher
    drop(sender);

    // Attente de la fin de l'acheminement de tous les lots
    dispatcher_handle.await?;

    info!("Toutes les notifications ont été traitées et expédiées avec succès en batch.");
    Ok(())
}

