    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Convertit un fichier CSV volumineux en partition Parquet (ex: date=YYYY-MM-DD/)
    CsvToParquet {
        /// Chemin du fichier CSV source
        #[arg(short, long)]
        input: PathBuf,

        /// Répertoire racine de destination pour les partitions Parquet
        #[arg(short, long)]
        output_dir: PathBuf,

        /// Nom de la colonne contenant la date de partitionnement
        #[arg(short, long)]
        date_column: String,

        /// Taille de chaque batch de lecture CSV
        #[arg(short, long, default_value_t = 65536)]
        batch_size: usize,

        /// Algorithme de compression pour les fichiers Parquet
        #[arg(short, long, value_enum, default_value_t = CompressionOption::Snappy)]
        compression: CompressionOption,
    },

    /// Reconstitue un fichier CSV à partir d'un répertoire Parquet partitionné
    ParquetToCsv {
        /// Répertoire racine des partitions Parquet
        #[arg(short, long)]
        input_dir: PathBuf,

        /// Chemin du fichier CSV de sortie
        #[arg(short, long)]
        output: PathBuf,

        /// Taille de batch de lecture
        #[arg(short, long, default_value_t = 65536)]
        batch_size: usize,
    },
}

#[derive(ValueEnum, Clone, Copy, Debug)]
enum CompressionOption {
    Uncompressed,
    Snappy,
    Gzip,
    Zstd,
}

impl From<CompressionOption> for Compression {
    fn from(opt: CompressionOption) -> Self {
        match opt {
            CompressionOption::Uncompressed => Compression::UNCOMPRESSED,
            CompressionOption::Snappy => Compression::SNAPPY,
            CompressionOption::Gzip => Compression::GZIP(parquet::basic::GzipLevel::default()),
            CompressionOption::Zstd => Compression::ZSTD(parquet::basic::ZstdLevel::default()),
        }
    }
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::CsvToParquet {
            input,
            output_dir,
            date_column,
            batch_size,
            compression,
        } => convert_csv_to_parquet(
            &input,
            &output_dir,
            &date_column,
            batch_size,
            compression.into(),
        )
        .context("Échec lors de la conversion CSV vers Parquet partitionné"),

        Commands::ParquetToCsv {
            input_dir,
            output,
            batch_size,
        } => convert_parquet_to_csv(&input_dir, &output, batch_size)
            .context("Échec lors de la conversion Parquet vers CSV"),
    }
