/// Extrait la valeur textuelle canonique de la date pour une ligne donnée
fn extract_date_string(array: &Arc<dyn Array>, row_idx: usize) -> Result<String> {
    if array.is_null(row_idx) {
        return Ok("unknown".to_string());
    }

    match array.data_type() {
        DataType::Utf8 => {
            let str_array = array.as_string::<i32>();
            let s = str_array.value(row_idx);
            normalize_date_str(s)
        }
        DataType::LargeUtf8 => {
            let str_array = array.as_string::<i64>();
            let s = str_array.value(row_idx);
            normalize_date_str(s)
        }
        DataType::Date32 => {
            let date_array = array.as_primitive::<Date32Type>();
            let days = date_array.value(row_idx);
            let epoch = chrono::NaiveDate::from_ymd_opt(1970, 1, 1)
                .context("Date epoch 1970-01-01 invalide")?;
            let date = epoch + chrono::Duration::days(days as i64);
            Ok(date.format("%Y-%m-%d").to_string())
        }
        DataType::Date64 => {
            let date_array = array.as_primitive::<Date64Type>();
            let millis = date_array.value(row_idx);
            let dt = chrono::DateTime::from_timestamp_millis(millis)
                .context("Timestamp millisecondes invalide")?;
            Ok(dt.format("%Y-%m-%d").to_string())
        }
        DataType::Timestamp(unit, _) => {
            let millis = match unit {
                TimeUnit::Second => array.as_primitive::<TimestampSecondType>().value(row_idx) * 1000,
                TimeUnit::Millisecond => array.as_primitive::<TimestampMillisecondType>().value(row_idx),
                TimeUnit::Microsecond => array.as_primitive::<TimestampMicrosecondType>().value(row_idx) / 1000,
                TimeUnit::Nanosecond => array.as_primitive::<TimestampNanosecondType>().value(row_idx) / 1_000_000,
            };
            let dt = chrono::DateTime::from_timestamp_millis(millis)
                .context("Timestamp invalide")?;
            Ok(dt.format("%Y-%m-%d").to_string())
        }
        other => {
            bail!("Le type {:?} n'est pas supporté pour le partitionnement par date", other);
        }
    }
}

/// Tente de standardiser une chaîne de date sous le format YYYY-MM-DD
fn normalize_date_str(s: &str) -> Result<String> {
    let trimmed = s.trim();
    if trimmed.is_empty() {
        return Ok("unknown".to_string());
    }

    if let Ok(d) = chrono::NaiveDate::parse_from_str(trimmed, "%Y-%m-%d") {
        return Ok(d.format("%Y-%m-%d").to_string());
    }
    if let Ok(dt) = chrono::DateTime::parse_from_rfc3339(trimmed) {
        return Ok(dt.format("%Y-%m-%d").to_string());
    }
    if let Ok(dt) = chrono::NaiveDateTime::parse_from_str(trimmed, "%Y-%m-%d %H:%M:%S") {
        return Ok(dt.format("%Y-%m-%d").to_string());
    }
    if let Ok(d) = chrono::NaiveDate::parse_from_str(trimmed, "%d/%m/%Y") {
        return Ok(d.format("%Y-%m-%d").to_string());
    }

    // Si le préfixe a la taille d'une date ISO standard YYYY-MM-DD
    if trimmed.len() >= 10 {
        let prefix = &trimmed[..10];
        if let Ok(d) = chrono::NaiveDate::parse_from_str(prefix, "%Y-%m-%d") {
            return Ok(d.format("%Y-%m-%d").to_string());
        }
    }

    Ok(trimmed.replace('/', "-"))
}

/// Convertit un fichier CSV volumineux en ensemble de partitions Parquet
fn convert_csv_to_parquet(
    input_file: &Path,
    output_dir: &Path,
    date_column: &str,
    batch_size: usize,
    compression: Compression,
) -> Result<()> {
    if !input_file.exists() {
        bail!("Fichier CSV d'entrée inexistant : {}", input_file.display());
    }

    fs::create_dir_all(output_dir)
        .with_context(|| format!("Impossible de créer le répertoire {}", output_dir.display()))?;

    // Inférence automatique du schéma CSV
    let file = File::open(input_file)
        .with_context(|| format!("Impossible d'ouvrir {}", input_file.display()))?;
    let (schema, _) = CsvFormat::default()
        .with_header(true)
        .with_delimiter(b',')
        .infer_schema(file, Some(1000))
        .context("Échec de l'inférence du schéma CSV")?;

    let schema_ref = Arc::new(schema);
    let date_col_idx = schema_ref
        .index_of(date_column)
        .with_context(|| format!("La colonne de date '{}' n'a pas été trouvée dans le CSV", date_column))?;

    // Instanciation du lecteur CSV par streaming
    let file = File::open(input_file)?;
    let csv_reader = CsvReaderBuilder::new(schema_ref.clone())
        .with_batch_size(batch_size)
        .with_header(true)
        .build(file)
        .context("Erreur lors de l'initialisation du lecteur CSV Arrow")?;

    let pb = ProgressBar::new_spinner();
    pb.set_style(
        ProgressStyle::default_spinner()
            .template("{spinner:.green} [{elapsed_precise}] {msg} ({pos} batches)")
            .context("Erreur de configuration de la barre de progression")?,
    );
    pb.set_message("Lecture et partitionnement du CSV en cours...");

    // Map des writers par partition : date -> ArrowWriter
    let mut writers: HashMap<String, ArrowWriter<BufWriter<File>>> = HashMap::new();
    let mut part_counters: HashMap<String, usize> = HashMap::new();

    let writer_props = WriterProperties::builder()
        .set_compression(compression)
        .build();

    let mut total_rows = 0usize;

    for (batch_idx, batch_res) in csv_reader.enumerate() {
        let batch = batch_res.with_context(|| format!("Erreur de lecture du batch CSV #{}", batch_idx))?;
        let num_rows = batch.num_rows();
        if num_rows == 0 {
            continue;
        }
        total_rows += num_rows;

        let date_col_array = batch.column(date_col_idx);

        // Partitionnement des lignes du RecordBatch actuel par valeur de date
        let mut row_indices_by_date: HashMap<String, Vec<usize>> = HashMap::new();
        for row in 0..num_rows {
            let partition_key = extract_date_string(date_col_array, row)?;
            row_indices_by_date.entry(partition_key).or_default().push(row);
        }

        // Pour chaque partition distincte dans ce lot, filtrer et écrire
        for (date_val, rows) in row_indices_by_date {
            let mut filter_builder = BooleanBuilder::with_capacity(num_rows);
            let mut row_set = vec![false; num_rows];
            for r in rows {
                row_set[r] = true;
            }
            for is_set in row_set {
                filter_builder.append_value(is_set);
            }
            let filter_mask = filter_builder.finish();

            let sub_batch = filter_record_batch(&batch, &filter_mask)
                .with_context(|| format!("Erreur de filtrage du batch pour la date {}", date_val))?;

            if !writers.contains_key(&date_val) {
                let partition_dir = output_dir.join(format!("date={}", date_val));
                fs::create_dir_all(&partition_dir)?;

                let part_idx = part_counters.entry(date_val.clone()).or_insert(0);
                *part_idx += 1;
                let parquet_path = partition_dir.join(format!("part-{:05}.parquet", part_idx));
                let file = File::create(&parquet_path)
                    .with_context(|| format!("Impossible de créer le fichier {}", parquet_path.display()))?;
                let buf_writer = BufWriter::new(file);

                let writer = ArrowWriter::try_new(buf_writer, schema_ref.clone(), Some(writer_props.clone()))
                    .with_context(|| format!("Erreur à la création de l'ArrowWriter pour {}", parquet_path.display()))?;
                writers.insert(date_val.clone(), writer);
            }

            let writer = writers
                .get_mut(&date_val)
                .expect("Le writer pour la partition doit exister");
            writer
                .write(&sub_batch)
                .with_context(|| format!("Erreur d'écriture du RecordBatch Parquet pour {}", date_val))?;
        }

        pb.inc(1);
    }

    // Clôture propre de tous les writers Parquet ouverts
    for (date_val, writer) in writers {
        writer
            .close()
            .with_context(|| format!("Erreur lors de la fermeture du fichier Parquet pour {}", date_val))?;
    }

    pb.finish_with_message(format!(
        "Conversion CSV -> Parquet terminée avec succès ({} lignes traitées) !",
        total_rows
    ));
    println!("Partitions créées sous : {}", output_dir.display());

    Ok(())
}

/// Reconstitue un fichier CSV à partir de partitions Parquet
fn convert_parquet_to_csv(input_dir: &Path, output_file: &Path, batch_size: usize) -> Result<()> {
    if !input_dir.exists() {
        bail!("Le répertoire source {} n'existe pas", input_dir.display());
    }

    // Récupération de tous les fichiers Parquet dans le dossier (récursif pour gérer les partitions hive)
    let mut parquet_files: Vec<PathBuf> = WalkDir::new(input_dir)
        .into_iter()
        .filter_map(|e| e.ok())
        .filter(|e| {
            e.file_type().is_file()
                && e.path()
                    .extension()
                    .map(|ext| ext == "parquet")
                    .unwrap_or(false)
        })
        .map(|e| e.into_path())
        .collect();

    parquet_files.sort();

    if parquet_files.is_empty() {
        bail!("Aucun fichier Parquet trouvé dans le répertoire {}", input_dir.display());
    }

    if let Some(parent) = output_file.parent() {
        if !parent.as_os_str().is_empty() {
            fs::create_dir_all(parent)?;
        }
    }

    let out_file = File::create(output_file)
        .with_context(|| format!("Impossible de créer le fichier CSV de sortie {}", output_file.display()))?;
    let out_buf = BufWriter::new(out_file);

    let pb = ProgressBar::new(parquet_files.len() as u64);
    pb.set_style(
        ProgressStyle::default_bar()
            .template("{spinner:.green} [{elapsed_precise}] [{bar:40.cyan/blue}] {pos}/{len} fichiers ({msg})")
            .context("Erreur de style de progress bar")?,
    );
    pb.set_message("Lecture des partitions Parquet");

    let first_file = File::open(&parquet_files[0])
        .with_context(|| format!("Impossible d'ouvrir le premier fichier {}", parquet_files[0].display()))?;
    let first_builder = ParquetRecordBatchReaderBuilder::try_new(first_file)
        .with_context(|| format!("Erreur lors de la lecture du schéma de {}", parquet_files[0].display()))?;
    let schema = first_builder.schema().clone();

    let mut csv_writer = CsvWriterBuilder::new()
        .with_header(true)
        .build(out_buf);

    let mut total_rows = 0usize;

    for file_path in &parquet_files {
        let file = File::open(file_path)
            .with_context(|| format!("Impossible d'ouvrir le fichier Parquet {}", file_path.display()))?;

        let builder = ParquetRecordBatchReaderBuilder::try_new(file)
            .with_context(|| format!("Erreur lors de l'analyse du fichier Parquet {}", file_path.display()))?;

        if builder.schema().fields() != schema.fields() {
            eprintln!(
                "Avertissement : Le fichier {} a un schéma différent du premier fichier",
                file_path.display()
            );
        }

        let reader = builder
            .with_batch_size(batch_size)
            .build()
            .with_context(|| format!("Erreur à la construction de l'itérateur de batchs Parquet pour {}", file_path.display()))?;

        for batch_res in reader {
            let batch = batch_res.with_context(|| {
                format!(
                    "Erreur de lecture d'un RecordBatch dans {}",
                    file_path.display()
                )
            })?;
            total_rows += batch.num_rows();

            csv_writer
                .write(&batch)
                .with_context(|| format!("Erreur lors de l'écriture CSV du batch issu de {}", file_path.display()))?;
        }

        pb.inc(1);
    }

    pb.finish_with_message(format!(
        "Conversion Parquet -> CSV terminée ({} fichiers lus, {} lignes au total) !",
        parquet_files.len(),
        total_rows
    ));
    println!("Fichier CSV généré avec succès : {}", output_file.display());

    Ok(())
}

