    },
}

#[derive(ValueEnum, Clone, Copy, Debug)]
enum CompressionOption {
    Uncompressed,
    Snappy,
    Gzip,
    Zstd,
}

impl From<CompressionOption> for Compression {
    fn from(opt: CompressionOption) -> Self {
        match opt {
            CompressionOption::Uncompressed => Compression::UNCOMPRESSED,
            CompressionOption::Snappy => Compression::SNAPPY,
            CompressionOption::Gzip => Compression::GZIP(parquet::basic::GzipLevel::default()),
            CompressionOption::Zstd => Compression::ZSTD(parquet::basic::ZstdLevel::default()),
        }
    }
}

fn main() -> Result<()> {
