                .with_context(|| format!("Erreur lors de l'écriture CSV du batch issu de {}", file_path.display()))?;
        }

        pb.inc(1);
    }

    pb.finish_with_message(format!(
        "Conversion Parquet -> CSV terminée ({} fichiers lus, {} lignes au total) !",
        parquet_files.len(),
        total_rows
    ));
    println!("Fichier CSV généré avec succès : {}", output_file.display());

    Ok(())
}

