// src/main.rs
use std::collections::{HashMap, HashSet};
use std::fs::File;
use std::io::{BufReader, BufWriter};
use std::path::Path;

use serde::{Deserialize, Serialize};
use thiserror::Error;

/// Type d'identifiant unique d'un document.
pub type DocId = u64;

/// Erreurs potentielles du moteur d'indexation.
#[derive(Debug, Error)]
pub enum IndexError {
    #[error("Erreur d'entrée/sortie : {0}")]
    Io(#[from] std::io::Error),

    #[error("Erreur de sérialisation Bincode : {0}")]
    Bincode(#[from] bincode::Error),

    #[error("Erreur de sérialisation JSON : {0}")]
    Json(#[from] serde_json::Error),

