/// Métadonnées et contenu résumé d'un document.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct DocumentRecord {
    pub id: DocId,
    pub title: String,
    pub content: String,
    pub total_terms: usize,
}

/// Entrée individuelle d'une liste d'occurrences (posting list).
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
pub struct Posting {
    pub doc_id: DocId,
    pub term_frequency: u32,
}

/// Structure centrale de l'index inversé en mémoire.
#[derive(Debug, Default, Clone, Serialize, Deserialize, PartialEq)]
pub struct InvertedIndex {
    /// Documents indexés indexés par leur identifiant unique.
    documents: HashMap<DocId, DocumentRecord>,
    /// Table de correspondance terme -> liste ordonnée des postings (par DocId).
    postings: HashMap<String, Vec<Posting>>,
}

/// Résultat d'une recherche avec score de pertinence.
#[derive(Debug, Clone, PartialEq)]
pub struct SearchHit {
    pub doc_id: DocId,
    pub title: String,
    pub score: f64,
}

impl InvertedIndex {
    /// Crée un nouvel index vide.
    pub fn new() -> Self {
        Self {
            documents: HashMap::new(),
            postings: HashMap::new(),
        }
    }

    /// Découpe et normalise un texte en jetons (tokens).
    pub fn tokenize(text: &str) -> Vec<String> {
        text.split(|c: char| !c.is_alphanumeric())
            .filter_map(|raw_token| {
                let trimmed = raw_token.trim().to_lowercase();
                if trimmed.is_empty() {
                    None
                } else {
                    Some(trimmed)
                }
            })
            .collect()
    }

    /// Ajoute un document à l'index inversé.
    pub fn add_document(
        &mut self,
        id: DocId,
        title: impl Into<String>,
        content: impl Into<String>,
    ) -> Result<(), IndexError> {
        if self.documents.contains_key(&id) {
            return Err(IndexError::DuplicateDocument(id));
        }

        let title = title.into();
        let content = content.into();
        let tokens = Self::tokenize(&content);
        let total_terms = tokens.len();

        let mut term_counts: HashMap<String, u32> = HashMap::new();
        for token in tokens {
            *term_counts.entry(token).or_insert(0) += 1;
        }

        for (term, count) in term_counts {
            let list = self.postings.entry(term).or_default();
            list.push(Posting {
                doc_id: id,
                term_frequency: count,
            });
            list.sort_unstable_by_key(|p| p.doc_id);
        }

        let record = DocumentRecord {
            id,
            title,
            content,
            total_terms,
        };
        self.documents.insert(id, record);

        Ok(())
    }

    /// Supprime un document de l'index.
    pub fn remove_document(&mut self, id: DocId) -> Result<DocumentRecord, IndexError> {
        let removed_doc = self
            .documents
            .remove(&id)
            .ok_or(IndexError::DocumentNotFound(id))?;

        let tokens = Self::tokenize(&removed_doc.content);
        let unique_terms: HashSet<String> = tokens.into_iter().collect();

        for term in unique_terms {
            if let Some(list) = self.postings.get_mut(&term) {
                list.retain(|p| p.doc_id != id);
            }
        }

        // Nettoyage des termes orphelins
        self.postings.retain(|_, list| !list.is_empty());

        Ok(removed_doc)
    }

    /// Nombre total de documents indexés.
    pub fn len(&self) -> usize {
        self.documents.len()
    }

    /// Vérifie si l'index est vide.
    pub fn is_empty(&self) -> bool {
        self.documents.is_empty()
    }

    /// Recherche les documents contenant tous les termes spécifiés (AND logique) avec scoring TF-IDF.
    pub fn search_and(&self, query: &str) -> Vec<SearchHit> {
        let query_tokens = Self::tokenize(query);
        if query_tokens.is_empty() || self.documents.is_empty() {
            return Vec::new();
        }

        let total_docs = self.documents.len() as f64;
        let mut matching_doc_ids: Option<HashSet<DocId>> = None;
        let mut term_postings: Vec<(&String, &Vec<Posting>)> = Vec::new();

        for token in &query_tokens {
            if let Some(postings) = self.postings.get(token) {
                let current_docs: HashSet<DocId> = postings.iter().map(|p| p.doc_id).collect();
                matching_doc_ids = match matching_doc_ids {
                    Some(accum) => Some(accum.intersection(&current_docs).copied().collect()),
                    None => Some(current_docs),
                };
                term_postings.push((token, postings));
            } else {
                return Vec::new();
            }
        }

        let candidate_ids = match matching_doc_ids {
            Some(ids) if !ids.is_empty() => ids,
            _ => return Vec::new(),
        };

        let mut scores: HashMap<DocId, f64> = HashMap::new();
        for (_, postings) in term_postings {
            let doc_count_with_term = postings.len() as f64;
            let idf = ((total_docs + 1.0) / (doc_count_with_term + 1.0)).ln() + 1.0;

            for posting in postings {
                if candidate_ids.contains(&posting.doc_id) {
                    let total_doc_len = self
                        .documents
                        .get(&posting.doc_id)
                        .map(|d| d.total_terms)
                        .unwrap_or(1)
                        .max(1) as f64;

                    let tf = (posting.term_frequency as f64) / total_doc_len;
                    *scores.entry(posting.doc_id).or_insert(0.0) += tf * idf;
                }
            }
        }

        self.build_hits(scores)
    }

    /// Recherche les documents contenant au moins l'un des termes spécifiés (OR logique) avec scoring TF-IDF.
    pub fn search_or(&self, query: &str) -> Vec<SearchHit> {
        let query_tokens = Self::tokenize(query);
        if query_tokens.is_empty() || self.documents.is_empty() {
            return Vec::new();
        }

        let total_docs = self.documents.len() as f64;
        let mut scores: HashMap<DocId, f64> = HashMap::new();

        for token in &query_tokens {
            if let Some(postings) = self.postings.get(token) {
                let doc_count_with_term = postings.len() as f64;
                let idf = ((total_docs + 1.0) / (doc_count_with_term + 1.0)).ln() + 1.0;

                for posting in postings {
                    let total_doc_len = self
                        .documents
                        .get(&posting.doc_id)
                        .map(|d| d.total_terms)
                        .unwrap_or(1)
                        .max(1) as f64;

                    let tf = (posting.term_frequency as f64) / total_doc_len;
                    *scores.entry(posting.doc_id).or_insert(0.0) += tf * idf;
                }
            }
        }

        self.build_hits(scores)
    }

    fn build_hits(&self, scores: HashMap<DocId, f64>) -> Vec<SearchHit> {
        let mut hits: Vec<SearchHit> = scores
            .into_iter()
            .filter_map(|(id, score)| {
                self.documents.get(&id).map(|doc| SearchHit {
                    doc_id: id,
                    title: doc.title.clone(),
                    score,
                })
            })
            .collect();

        hits.sort_by(|a, b| {
            b.score
                .partial_cmp(&a.score)
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        hits
    }

    /// Persiste l'index au format binaire optimisé (bincode).
    pub fn save_to_bincode<P: AsRef<Path>>(&self, path: P) -> Result<(), IndexError> {
        let file = File::create(path)?;
        let writer = BufWriter::new(file);
        bincode::serialize_into(writer, self)?;
        Ok(())
    }

    /// Charge un index depuis un fichier binaire (bincode).
    pub fn load_from_bincode<P: AsRef<Path>>(path: P) -> Result<Self, IndexError> {
        let file = File::open(path)?;
        let reader = BufReader::new(file);
        let index = bincode::deserialize_from(reader)?;
        Ok(index)
    }

    /// Persiste l'index au format lisible JSON.
    pub fn save_to_json<P: AsRef<Path>>(&self, path: P) -> Result<(), IndexError> {
        let file = File::create(path)?;
        let writer = BufWriter::new(file);
        serde_json::to_writer_pretty(writer, self)?;
        Ok(())
    }

    /// Charge un index depuis un fichier JSON.
    pub fn load_from_json<P: AsRef<Path>>(path: P) -> Result<Self, IndexError> {
        let file = File::open(path)?;
        let reader = BufReader::new(file);
        let index = serde_json::from_reader(reader)?;
        Ok(index)
    }
