        "Memory management in modern languages uses automatic garbage collection or strict ownership semantics like Rust.",
    )?;

    index.add_document(
        3,
        "Serialization with Serde",
        "Serde is a framework for serializing and deserializing Rust data structures efficiently and generically.",
    )?;

    index.add_document(
        4,
        "Bincode Serialization",
        "Bincode is an extremely fast binary encoder for Rust using Serde to serialize structures directly to bytes.",
    )?;

    println!("Total de documents indexés en mémoire : {}", index.len());

    // 2. Démonstration de requêtes de recherche
    println!("\n--- Test 1 : Recherche conjonctive (AND) pour 'rust memory' ---");
    let hits_and = index.search_and("rust memory");
    for hit in &hits_and {
        println!("  [Doc #{}] {} - Score : {:.4}", hit.doc_id, hit.title, hit.score);
    }

    println!("\n--- Test 2 : Recherche disjonctive (OR) pour 'serde bincode' ---");
    let hits_or = index.search_or("serde bincode");
    for hit in &hits_or {
        println!("  [Doc #{}] {} - Score : {:.4}", hit.doc_id, hit.title, hit.score);
    }

    // 3. Persistance sur disque via Bincode
    let bin_path = "index_storage.bin";
    println!("\n--- Persistance : Sauvegarde Bincode vers '{}' ---", bin_path);
    index.save_to_bincode(bin_path)?;

    // 4. Persistance sur disque via JSON (lisible)
    let json_path = "index_storage.json";
    println!("--- Persistance : Sauvegarde JSON vers '{}' ---", json_path);
    index.save_to_json(json_path)?;

    // 5. Restauration depuis le disque et validation de l'état
    println!("\n--- Restauration depuis le fichier binaire Bincode ---");
    let restored_index = InvertedIndex::load_from_bincode(bin_path)?;
    println!(
        "Index restauré avec succès avec {} documents.",
        restored_index.len()
    );

    let restored_hits = restored_index.search_and("rust memory");
    println!(
        "Vérification de recherche après restauration ('rust memory') : {} résultats trouvés.",
        restored_hits.len()
    );
    for hit in &restored_hits {
