    }

    // 6. Nettoyage des artefacts de démonstration
    let _ = std::fs::remove_file(bin_path);
    let _ = std::fs::remove_file(json_path);

    println!("\n=== Démonstration terminée avec succès ===");
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_indexing_and_search() {
        let mut index = InvertedIndex::new();
        assert!(index.add_document(1, "Doc 1", "Hello world this is Rust").is_ok());
        assert!(index.add_document(2, "Doc 2", "World of programming with Rust").is_ok());

        let hits = index.search_and("world rust");
        assert_eq!(hits.len(), 2);

        let hits_single = index.search_and("programming");
        assert_eq!(hits_single.len(), 1);
        assert_eq!(hits_single[0].doc_id, 2);
    }

    #[test]
    fn test_remove_document() {
        let mut index = InvertedIndex::new();
        index.add_document(1, "Doc 1", "Alpha beta").unwrap();
        index.add_document(2, "Doc 2", "Beta gamma").unwrap();

        assert_eq!(index.len(), 2);
        let removed = index.remove_document(1);
        assert!(removed.is_ok());
        assert_eq!(index.len(), 1);

        let hits = index.search_and("alpha");
        assert!(hits.is_empty());

        let hits_beta = index.search_and("beta");
        assert_eq!(hits_beta.len(), 1);
        assert_eq!(hits_beta[0].doc_id, 2);
    }

    #[test]
    fn test_duplicate_document_error() {
        let mut index = InvertedIndex::new();
        assert!(index.add_document(1, "Doc 1", "Content").is_ok());
        assert!(index.add_document(1, "Doc 1 Duplicate", "Other Content").is_err());
    }

    #[test]
    fn test_serde_bincode_and_json_roundtrip() {
        let mut original = InvertedIndex::new();
        original.add_document(10, "Title A", "Fast search engine written in Rust").unwrap();
        original.add_document(20, "Title B", "Index textual data on disk").unwrap();

        let tmp_bin = "test_roundtrip.bin";
        let tmp_json = "test_roundtrip.json";

        original.save_to_bincode(tmp_bin).unwrap();
        let loaded_bin = InvertedIndex::load_from_bincode(tmp_bin).unwrap();
        assert_eq!(original, loaded_bin);

        original.save_to_json(tmp_json).unwrap();
        let loaded_json = InvertedIndex::load_from_json(tmp_json).unwrap();
        assert_eq!(original, loaded_json);

        let _ = std::fs::remove_file(tmp_bin);
        let _ = std::fs::remove_file(tmp_json);
    }
