    /// Persiste l'index au format binaire optimisé (bincode).
    pub fn save_to_bincode<P: AsRef<Path>>(&self, path: P) -> Result<(), IndexError> {
        let file = File::create(path)?;
        let writer = BufWriter::new(file);
        bincode::serialize_into(writer, self)?;
        Ok(())
    }

    /// Charge un index depuis un fichier binaire (bincode).
    pub fn load_from_bincode<P: AsRef<Path>>(path: P) -> Result<Self, IndexError> {
        let file = File::open(path)?;
        let reader = BufReader::new(file);
        let index = bincode::deserialize_from(reader)?;
        Ok(index)
    }

    /// Persiste l'index au format lisible JSON.
    pub fn save_to_json<P: AsRef<Path>>(&self, path: P) -> Result<(), IndexError> {
        let file = File::create(path)?;
        let writer = BufWriter::new(file);
        serde_json::to_writer_pretty(writer, self)?;
        Ok(())
    }

    /// Charge un index depuis un fichier JSON.
    pub fn load_from_json<P: AsRef<Path>>(path: P) -> Result<Self, IndexError> {
        let file = File::open(path)?;
        let reader = BufReader::new(file);
        let index = serde_json::from_reader(reader)?;
        Ok(index)
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("=== Initialisation du moteur d'indexation inversé ===");

    let mut index = InvertedIndex::new();

    // 1. Indexation d'un corpus de documents de démonstration
    index.add_document(
        1,
        "Rust Language",
        "Rust is a systems programming language that runs blazingly fast, prevents segfaults, and guarantees thread safety.",
    )?;

    index.add_document(
        2,
        "Modern Memory Management",
        "Memory management in modern languages uses automatic garbage collection or strict ownership semantics like Rust.",
    )?;

    index.add_document(
        3,
        "Serialization with Serde",
        "Serde is a framework for serializing and deserializing Rust data structures efficiently and generically.",
    )?;

    index.add_document(
        4,
        "Bincode Serialization",
        "Bincode is an extremely fast binary encoder for Rust using Serde to serialize structures directly to bytes.",
    )?;

    println!("Total de documents indexés en mémoire : {}", index.len());

    // 2. Démonstration de requêtes de recherche
    println!("\n--- Test 1 : Recherche conjonctive (AND) pour 'rust memory' ---");
    let hits_and = index.search_and("rust memory");
    for hit in &hits_and {
        println!("  [Doc #{}] {} - Score : {:.4}", hit.doc_id, hit.title, hit.score);
    }

    println!("\n--- Test 2 : Recherche disjonctive (OR) pour 'serde bincode' ---");
    let hits_or = index.search_or("serde bincode");
    for hit in &hits_or {
        println!("  [Doc #{}] {} - Score : {:.4}", hit.doc_id, hit.title, hit.score);
    }

    // 3. Persistance sur disque via Bincode
