    println!("--- Persistance : Sauvegarde JSON vers '{}' ---", json_path);
    index.save_to_json(json_path)?;

    // 5. Restauration depuis le disque et validation de l'état
    println!("\n--- Restauration depuis le fichier binaire Bincode ---");
    let restored_index = InvertedIndex::load_from_bincode(bin_path)?;
    println!(
        "Index restauré avec succès avec {} documents.",
        restored_index.len()
    );

    let restored_hits = restored_index.search_and("rust memory");
    println!(
        "Vérification de recherche après restauration ('rust memory') : {} résultats trouvés.",
        restored_hits.len()
    );
    for hit in &restored_hits {
        println!("  [Doc #{}] {} - Score : {:.4}", hit.doc_id, hit.title, hit.score);
    }

