// src/main.rs
use std::fs::File;
use std::path::PathBuf;
use std::str::FromStr;

use anyhow::{bail, Context, Result};
use arrow::array::{
    Array, BooleanArray, Float32Array, Float64Array, Int16Array, Int32Array, Int64Array, Int8Array,
    UInt16Array, UInt32Array, UInt64Array, UInt8Array,
};
use arrow::compute::filter_record_batch;
use arrow::datatypes::DataType;
use arrow::record_batch::RecordBatch;
use arrow::util::pretty::pretty_format_batches;
use clap::Parser;
use parquet::arrow::arrow_reader::{ParquetRecordBatchReader, ParquetRecordBatchReaderBuilder};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Operator {
    Eq,
    Neq,
    Lt,
    Lte,
    Gt,
    Gte,
}

impl FromStr for Operator {
    type Err = anyhow::Error;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "=" | "==" => Ok(Self::Eq),
            "!=" => Ok(Self::Neq),
            "<" => Ok(Self::Lt),
            "<=" => Ok(Self::Lte),
            ">" => Ok(Self::Gt),
            ">=" => Ok(Self::Gte),
            _ => bail!(
                "Opérateur non supporté: '{}'. Utilisez '=', '==', '!=', '<', '<=', '>', '>='",
                s
            ),
        }
    }
}

impl Operator {
    pub fn evaluate(&self, lhs: f64, rhs: f64) -> bool {
        match self {
            Self::Eq => (lhs - rhs).abs() < f64::EPSILON,
            Self::Neq => (lhs - rhs).abs() >= f64::EPSILON,
            Self::Lt => lhs < rhs,
            Self::Lte => lhs <= rhs,
            Self::Gt => lhs > rhs,
            Self::Gte => lhs >= rhs,
        }
    }
}

#[derive(Debug, Clone)]
pub struct NumericPredicate {
    pub column: String,
    pub operator: Operator,
    pub value: f64,
}

impl FromStr for NumericPredicate {
    type Err = anyhow::Error;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let operators = ["<=", ">=", "==", "!=", "<", ">", "="];
        for op_sym in operators {
            if let Some(pos) = s.find(op_sym) {
                let column = s[..pos].trim();
                let val_str = s[pos + op_sym.len()..].trim();

                if column.is_empty() {
                    bail!("Nom de colonne manquant dans le prédicat: '{}'", s);
                }
                if val_str.is_empty() {
                    bail!("Valeur numérique manquante dans le prédicat: '{}'", s);
                }

                let operator = Operator::from_str(op_sym)?;
                let value = val_str.parse::<f64>().with_context(|| {
                    format!(
                        "La valeur '{}' n'est pas un nombre flottant/entier valide",
                        val_str
                    )
                })?;

                return Ok(NumericPredicate {
                    column: column.to_string(),
                    operator,
                    value,
                });
            }
        }

        bail!(
            "Format de prédicat invalide: '{}'. Format attendu : '<colonne><op><valeur>' (ex: 'age>=18' ou 'montant < 100.5')",
            s
        );
    }
}

#[derive(Parser, Debug)]
#[command(
    name = "parquet-query",
    author,
    version,
    about = "Interroge un fichier Parquet en streaming sans charger la totalité en mémoire RAM"
)]
struct Args {
    /// Chemin du fichier Parquet à analyser
    #[arg(short, long)]
    file: PathBuf,

    /// Prédicat numérique de filtrage (ex: "id>100", "prix<=50.0")
    #[arg(short = 'F', long)]
    filter: Option<NumericPredicate>,

    /// Nombre de lignes lues par batch de streaming
    #[arg(short, long, default_value_t = 8192)]
    batch_size: usize,

    /// Limite maximale du nombre de lignes affichées au total
    #[arg(short, long)]
    limit: Option<usize>,

    /// Afficher uniquement les métadonnées (nombre de colonnes, schéma) sans les données
    #[arg(long)]
    schema_only: bool,
}

fn build_predicate_mask(
    batch: &RecordBatch,
    predicate: &NumericPredicate,
) -> Result<BooleanArray> {
    let schema = batch.schema();
    let col_idx = match schema.index_of(&predicate.column) {
        Ok(idx) => idx,
        Err(_) => bail!(
            "La colonne '{}' n'existe pas dans le schéma Parquet",
            predicate.column
        ),
    };

    let col_array = batch.column(col_idx);
    let num_rows = batch.num_rows();

    macro_rules! evaluate_primitive_array {
        ($array_type:ty) => {{
            let typed_arr = col_array
                .as_any()
                .downcast_ref::<$array_type>()
                .context("Erreur de transtypage interne de la colonne")?;

            let mut builder = BooleanArray::builder(num_rows);
            for i in 0..num_rows {
                if typed_arr.is_null(i) {
                    builder.append_value(false);
                } else {
                    let val = typed_arr.value(i) as f64;
                    builder.append_value(predicate.operator.evaluate(val, predicate.value));
                }
            }
            builder.finish()
        }};
    }

    let mask = match col_array.data_type() {
        DataType::Int8 => evaluate_primitive_array!(Int8Array),
        DataType::Int16 => evaluate_primitive_array!(Int16Array),
        DataType::Int32 => evaluate_primitive_array!(Int32Array),
        DataType::Int64 => evaluate_primitive_array!(Int64Array),
        DataType::UInt8 => evaluate_primitive_array!(UInt8Array),
        DataType::UInt16 => evaluate_primitive_array!(UInt16Array),
        DataType::UInt32 => evaluate_primitive_array!(UInt32Array),
        DataType::UInt64 => evaluate_primitive_array!(UInt64Array),
        DataType::Float32 => evaluate_primitive_array!(Float32Array),
        DataType::Float64 => evaluate_primitive_array!(Float64Array),
        dt => bail!(
            "La colonne '{}' est de type non numérique ({:?}). Le filtrage numérique n'est pas applicable.",
            predicate.column,
            dt
        ),
    };

    Ok(mask)
}

fn main() -> Result<()> {
    let args = Args::parse();

    let file = File::open(&args.file)
        .with_context(|| format!("Impossible d'ouvrir le fichier {:?}", args.file))?;

    let builder = ParquetRecordBatchReaderBuilder::try_new(file)
        .with_context(|| format!("Fichier Parquet invalide ou corrompu: {:?}", args.file))?
        .with_batch_size(args.batch_size);

    let schema = builder.schema().clone();

    if args.schema_only {
        println!("Schéma Parquet pour {:?} :", args.file);
        for field in schema.fields() {
            println!(" - {}: {:?}", field.name(), field.data_type());
        }
        return Ok(());
    }

    let reader: ParquetRecordBatchReader = builder.build().context("Échec de création du lecteur Parquet")?;

    let mut total_matched_rows = 0usize;
    let mut total_read_rows = 0usize;
    let mut displayed_batches = Vec::new();

    for batch_result in reader {
        let batch = batch_result.context("Erreur lors de la lecture d'un RecordBatch en flux")?;
        let rows_in_batch = batch.num_rows();
        total_read_rows += rows_in_batch;

        let filtered_batch = if let Some(pred) = &args.filter {
            let mask = build_predicate_mask(&batch, pred)?;
            filter_record_batch(&batch, &mask).context("Échec de l'application du filtre sur le RecordBatch")?
        } else {
            batch
        };

        let matched_count = filtered_batch.num_rows();
        if matched_count > 0 {
            let remaining_limit = args.limit.map(|lim| lim.saturating_sub(total_matched_rows));

            if let Some(remaining) = remaining_limit {
                if remaining == 0 {
                    break;
                }
                if matched_count > remaining {
                    let sliced = filtered_batch.slice(0, remaining);
                    total_matched_rows += remaining;
                    displayed_batches.push(sliced);
                    break;
                }
            }

            total_matched_rows += matched_count;
            displayed_batches.push(filtered_batch);
        }
    }

    if displayed_batches.is_empty() {
        println!("Aucun enregistrement ne correspond aux critères spécifiés.");
    } else {
        let formatted = pretty_format_batches(&displayed_batches)
            .context("Erreur lors du formatage des résultats pour affichage")?;
        println!("{}", formatted);
    }

    eprintln!(
        "\nStatistiques : {} lignes lues au total, {} lignes retenues.",
        total_read_rows, total_matched_rows
    );

    Ok(())
}

