// src/main.rs
use std::collections::{HashMap, HashSet};
use std::path::Path;
use std::sync::Arc;

use parking_lot::RwLock;
use serde::{Deserialize, Serialize};
use thiserror::Error;

/// Erreurs potentielles du gestionnaire de base de données.
#[derive(Debug, Error)]
pub enum StorageError {
    #[error("Erreur Sled sous-jacente : {0}")]
    Sled(#[from] sled::Error),

    #[error("Erreur de sérialisation/désérialisation Bincode : {0}")]
    Serialization(#[from] bincode::Error),

    #[error("Conflit d'index unique sur le champ '{field}' avec la valeur '{value}'")]
    UniqueIndexViolation { field: String, value: String },

    #[error("Entité non trouvée pour l'identifiant : {0}")]
    NotFound(String),
}

/// Structure représentant une entité utilisateur stockée.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct UserRecord {
    pub id: String,
    pub username: String,
    pub email: String,
    pub role: String,
    pub age: u32,
}

/// Index secondaires maintenus en mémoire vive.
#[derive(Default, Debug)]
struct SecondaryIndexes {
    /// Index unique : email -> id
    by_email: HashMap<String, String>,
    /// Index non-unique (1-à-N) : role -> Ensemble d'IDs
    by_role: HashMap<String, HashSet<String>>,
    /// Index secondaire non-unique : tranche d'âge ou valeur exacte -> Ensemble d'IDs
    by_username: HashMap<String, String>,
}

impl SecondaryIndexes {
    fn new() -> Self {
        Self::default()
    }

    fn clear(&mut self) {
        self.by_email.clear();
        self.by_role.clear();
        self.by_username.clear();
    }

    /// Enregistre ou met à jour les entrées d'index pour un enregistrement.
    fn index_record(&mut self, record: &UserRecord) {
        self.by_email.insert(record.email.clone(), record.id.clone());
        self.by_username.insert(record.username.clone(), record.id.clone());
        self.by_role
            .entry(record.role.clone())
            .or_default()
            .insert(record.id.clone());
    }

    /// Retire les entrées d'index associées à un enregistrement.
    fn unindex_record(&mut self, record: &UserRecord) {
        self.by_email.remove(&record.email);
        self.by_username.remove(&record.username);
        if let Some(ids) = self.by_role.get_mut(&record.role) {
            ids.remove(&record.id);
            if ids.is_empty() {
                self.by_role.remove(&record.role);
            }
        }
    }
}

/// Gestionnaire de base de données combinant persistance disque (Sled)
/// et indexation secondaire rapide en mémoire.
#[derive(Clone)]
pub struct DatabaseManager {
    db: sled::Db,
    indexes: Arc<RwLock<SecondaryIndexes>>,
}

impl DatabaseManager {
    /// Ouvre ou crée une base de données au chemin spécifié et charge les index en mémoire.
    pub fn open<P: AsRef<Path>>(path: P) -> Result<Self, StorageError> {
        let db = sled::open(path)?;
        let manager = Self {
            db,
            indexes: Arc::new(RwLock::new(SecondaryIndexes::new())),
        };

        manager.rebuild_indexes()?;
        Ok(manager)
    }

    /// Reconstruit intégralement les index mémoires à partir des données présentes dans Sled.
    pub fn rebuild_indexes(&self) -> Result<usize, StorageError> {
        let mut idx_lock = self.indexes.write();
        idx_lock.clear();

        let mut count = 0;
        for item in self.db.iter() {
            let (_key, val) = item?;
            let record: UserRecord = bincode::deserialize(&val)?;
            idx_lock.index_record(&record);
            count += 1;
        }

        Ok(count)
    }

    /// Insère ou met à jour un enregistrement en garantissant la cohérence des index uniques.
    pub fn upsert(&self, record: UserRecord) -> Result<(), StorageError> {
        let mut idx_lock = self.indexes.write();

        // 1. Vérification de l'unicité de l'email
        if let Some(existing_id) = idx_lock.by_email.get(&record.email) {
            if existing_id != &record.id {
                return Err(StorageError::UniqueIndexViolation {
                    field: "email".to_string(),
                    value: record.email.clone(),
                });
            }
        }

        // 2. Vérification si un ancien enregistrement existe déjà avec cette clé primaire
        if let Some(old_bytes) = self.db.get(record.id.as_bytes())? {
            let old_record: UserRecord = bincode::deserialize(&old_bytes)?;
            idx_lock.unindex_record(&old_record);
        }

        // 3. Persistance dans Sled
        let serialized = bincode::serialize(&record)?;
        self.db.insert(record.id.as_bytes(), serialized)?;

        // 4. Mise à jour de l'index mémoire
        idx_lock.index_record(&record);

        Ok(())
    }

    /// Récupère un enregistrement via sa clé primaire (recherche directe dans Sled).
    pub fn get_by_id(&self, id: &str) -> Result<Option<UserRecord>, StorageError> {
        match self.db.get(id.as_bytes())? {
            Some(ivec) => {
                let record: UserRecord = bincode::deserialize(&ivec)?;
                Ok(Some(record))
            }
            None => Ok(None),
        }
    }

    /// Recherche rapide par email grâce à l'index secondaire unique en mémoire.
    pub fn find_by_email(&self, email: &str) -> Result<Option<UserRecord>, StorageError> {
        let primary_id = {
            let idx_lock = self.indexes.read();
            idx_lock.by_email.get(email).cloned()
        };

        match primary_id {
            Some(id) => self.get_by_id(&id),
            None => Ok(None),
        }
    }

    /// Recherche par nom d'utilisateur via l'index secondaire unique.
    pub fn find_by_username(&self, username: &str) -> Result<Option<UserRecord>, StorageError> {
        let primary_id = {
            let idx_lock = self.indexes.read();
            idx_lock.by_username.get(username).cloned()
        };

        match primary_id {
            Some(id) => self.get_by_id(&id),
            None => Ok(None),
        }
    }

    /// Recherche multi-valeurs par rôle via l'index secondaire non-unique (1-à-N).
    pub fn find_by_role(&self, role: &str) -> Result<Vec<UserRecord>, StorageError> {
        let candidate_ids = {
            let idx_lock = self.indexes.read();
            idx_lock.by_role.get(role).cloned()
        };

        let mut results = Vec::new();
        if let Some(ids) = candidate_ids {
            for id in ids {
                if let Some(record) = self.get_by_id(&id)? {
                    results.push(record);
                }
            }
        }

        Ok(results)
    }

    /// Supprime un enregistrement par identifiant et nettoie les index secondaires associés.
    pub fn delete(&self, id: &str) -> Result<bool, StorageError> {
        let mut idx_lock = self.indexes.write();

        if let Some(old_bytes) = self.db.remove(id.as_bytes())? {
            let old_record: UserRecord = bincode::deserialize(&old_bytes)?;
            idx_lock.unindex_record(&old_record);
            Ok(true)
        } else {
            Ok(false)
        }
    }

    /// Force l'écriture des modifications sur disque.
    pub fn flush(&self) -> Result<usize, StorageError> {
        Ok(self.db.flush()?)
    }

    /// Retourne le nombre total d'enregistrements persistés.
    pub fn len(&self) -> usize {
        self.db.len()
    }

    /// Indique si la base de données est vide.
    pub fn is_empty(&self) -> bool {
        self.db.is_empty()
    }
}

fn main() -> Result<(), StorageError> {
    println!("=== Démarrage du gestionnaire clé-valeur Sled avec indexation en mémoire ===");

    // Utilisation d'un répertoire temporaire pour la démonstration
    let temp_dir = tempfile::tempdir().map_err(|e| {
        std::io::Error::new(
            e.kind(),
            format!("Erreur lors de la création du répertoire temporaire: {e}"),
        )
    });
    let temp_dir = match temp_dir {
        Ok(dir) => dir,
        Err(e) => {
            eprintln!("Erreur I/O: {e}");
            return Ok(());
        }
    };

    let db_path = temp_dir.path().join("demo_sled_db");
    println!("Emplacement de la base : {:?}", db_path);

    let db_manager = DatabaseManager::open(&db_path)?;

    // 1. Insertion de données initiales
    println!("\n1. Insertion des utilisateurs...");
    let users = vec![
        UserRecord {
            id: "usr_1".into(),
            username: "alice".into(),
            email: "alice@example.com".into(),
            role: "Admin".into(),
            age: 32,
        },
        UserRecord {
            id: "usr_2".into(),
            username: "bob".into(),
            email: "bob@example.com".into(),
            role: "Developer".into(),
            age: 28,
        },
        UserRecord {
            id: "usr_3".into(),
            username: "charlie".into(),
            email: "charlie@example.com".into(),
            role: "Developer".into(),
            age: 35,
        },
    ];

    for user in users {
        println!(" -> Insertion de '{}' ({})", user.username, user.email);
        db_manager.upsert(user)?;
    }

    // 2. Recherche par clé primaire
    println!("\n2. Recherche par Clé Primaire (ID = 'usr_2') :");
    if let Some(user) = db_manager.get_by_id("usr_2")? {
        println!("    Trouvé : {} [{}]", user.username, user.role);
    }

    // 3. Recherche via Index Secondaire Unique (email)
    println!("\n3. Recherche via Index Secondaire Unique (email = 'alice@example.com') :");
    if let Some(user) = db_manager.find_by_email("alice@example.com")? {
        println!("    Trouvé avec succès via index mémoire : {:?}", user);
    }

    // 4. Recherche via Index Secondaire Multi-valeurs (role)
    println!("\n4. Recherche via Index Secondaire Multi-valeurs (role = 'Developer') :");
    let devs = db_manager.find_by_role("Developer")?;
    for dev in &devs {
        println!("    Membre de l'équipe Dev : {} (ID: {})", dev.username, dev.id);
    }

    // 5. Test de violation d'unicité
    println!("\n5. Test de contrainte d'unicité (tentative de collision email)...");
    let duplicate_email_user = UserRecord {
        id: "usr_4".into(),
        username: "alice_clone".into(),
        email: "alice@example.com".into(), // Déjà pris par usr_1
        role: "Guest".into(),
        age: 22,
    };

    match db_manager.upsert(duplicate_email_user) {
        Ok(_) => println!("    [Alerte] L'insertion aurait dû échouer !"),
        Err(err) => println!("    Validation réussie ! Erreur interceptée : {err}"),
    }

    // 6. Suppression et vérification de la désindexation
    println!("\n6. Suppression d'un utilisateur ('usr_2') et mise à jour des index...");
    let deleted = db_manager.delete("usr_2")?;
    println!("    Suppression confirmée : {deleted}");

    let devs_after_deletion = db_manager.find_by_role("Developer")?;
    println!(
        "    Développeurs restants (attendu: 1) : {}",
        devs_after_deletion.len()
    );

    let bob_lookup = db_manager.find_by_email("bob@example.com")?;
    println!("    Recherche email Bob après suppression : {:?}", bob_lookup);

    // 7. Test de persistance et reconstruction de l'index
    println!("\n7. Test de réouverture et reconstruction automatique de l'index...");
    db_manager.flush()?;
    drop(db_manager); // Fermeture propre de la base

    let reopened_db = DatabaseManager::open(&db_path)?;
    println!(
        "    Base réouverte avec succès. Nombre d'enregistrements : {}",
        reopened_db.len()
    );
    let alice_reopened = reopened_db.find_by_email("alice@example.com")?;
    println!(
        "    Index mémoire restauré avec succès : {:?}",
        alice_reopened.map(|u| u.username)
    );

    println!("\n=== Toutes les opérations se sont terminées avec succès ===");
    Ok(())
}

