            id: "usr_3".into(),
            username: "charlie".into(),
            email: "charlie@example.com".into(),
            role: "Developer".into(),
            age: 35,
        },
    ];

    for user in users {
        println!(" -> Insertion de '{}' ({})", user.username, user.email);
        db_manager.upsert(user)?;
    }

    // 2. Recherche par clé primaire
    println!("\n2. Recherche par Clé Primaire (ID = 'usr_2') :");
    if let Some(user) = db_manager.get_by_id("usr_2")? {
        println!("    Trouvé : {} [{}]", user.username, user.role);
    }

    // 3. Recherche via Index Secondaire Unique (email)
    println!("\n3. Recherche via Index Secondaire Unique (email = 'alice@example.com') :");
    if let Some(user) = db_manager.find_by_email("alice@example.com")? {
        println!("    Trouvé avec succès via index mémoire : {:?}", user);
    }

    // 4. Recherche via Index Secondaire Multi-valeurs (role)
    println!("\n4. Recherche via Index Secondaire Multi-valeurs (role = 'Developer') :");
    let devs = db_manager.find_by_role("Developer")?;
    for dev in &devs {
        println!("    Membre de l'équipe Dev : {} (ID: {})", dev.username, dev.id);
    }

    // 5. Test de violation d'unicité
    println!("\n5. Test de contrainte d'unicité (tentative de collision email)...");
    let duplicate_email_user = UserRecord {
        id: "usr_4".into(),
        username: "alice_clone".into(),
        email: "alice@example.com".into(), // Déjà pris par usr_1
        role: "Guest".into(),
        age: 22,
    };

    match db_manager.upsert(duplicate_email_user) {
        Ok(_) => println!("    [Alerte] L'insertion aurait dû échouer !"),
        Err(err) => println!("    Validation réussie ! Erreur interceptée : {err}"),
    }

    // 6. Suppression et vérification de la désindexation
    println!("\n6. Suppression d'un utilisateur ('usr_2') et mise à jour des index...");
    let deleted = db_manager.delete("usr_2")?;
    println!("    Suppression confirmée : {deleted}");

    let devs_after_deletion = db_manager.find_by_role("Developer")?;
    println!(
        "    Développeurs restants (attendu: 1) : {}",
        devs_after_deletion.len()
    );

    let bob_lookup = db_manager.find_by_email("bob@example.com")?;
    println!("    Recherche email Bob après suppression : {:?}", bob_lookup);

    // 7. Test de persistance et reconstruction de l'index
    println!("\n7. Test de réouverture et reconstruction automatique de l'index...");
    db_manager.flush()?;
    drop(db_manager); // Fermeture propre de la base

    let reopened_db = DatabaseManager::open(&db_path)?;
    println!(
        "    Base réouverte avec succès. Nombre d'enregistrements : {}",
        reopened_db.len()
    );
    let alice_reopened = reopened_db.find_by_email("alice@example.com")?;
    println!(
        "    Index mémoire restauré avec succès : {:?}",
        alice_reopened.map(|u| u.username)
    );

    println!("\n=== Toutes les opérations se sont terminées avec succès ===");
    Ok(())
}

