// src/main.rs
use anyhow::{Context, Result};
use clap::{Parser, Subcommand, ValueEnum};
use indicatif::{ProgressBar, ProgressStyle};
use rusqlite::types::{Value, ValueRef};
use rusqlite::{params_from_iter, Connection};
use serde_json::{Map, Value as JsonValue};
use std::fs::File;
use std::io::{BufReader, BufWriter, Write};
use std::path::{Path, PathBuf};

/// Stratégie de gestion des conflits ou d'insertion lors de l'import JSON vers SQLite.
#[derive(Copy, Clone, PartialEq, Eq, PartialOrd, Ord, ValueEnum, Debug)]
pub enum ImportMode {
    /// Insère uniquement (échoue ou lève une erreur en cas de conflit sur clé primaire/unique)
    Insert,
    /// Remplace la ligne en cas de conflit (INSERT OR REPLACE)
    Replace,
    /// Ignore l'insertion en cas de conflit (INSERT OR IGNORE)
    Ignore,
}

#[derive(Parser, Debug)]
#[command(
    name = "sqlite-json-migrator",
    about = "Outil CLI de migration et synchronisation bidirectionnelle entre SQLite et fichiers JSON plats",
    version
)]
pub struct Cli {
    #[command(subcommand)]
    pub command: Commands,
}

#[derive(Subcommand, Debug)]
pub enum Commands {
    /// Exporte les données d'une table SQLite vers un fichier plat JSON
    Export {
        /// Chemin vers la base de données SQLite
        #[arg(short, long, value_name = "DB_PATH")]
        db: PathBuf,

        /// Nom de la table source
        #[arg(short, long, value_name = "TABLE_NAME")]
        table: String,

        /// Chemin du fichier JSON de sortie
        #[arg(short, long, value_name = "OUTPUT_FILE")]
        output: PathBuf,

        /// Met en forme le JSON avec indentation
        #[arg(long, default_value_t = false)]
        pretty: bool,
    },

    /// Importe des enregistrements JSON vers une table SQLite existante ou nouvelle
    Import {
        /// Chemin vers la base de données SQLite
        #[arg(short, long, value_name = "DB_PATH")]
        db: PathBuf,

        /// Chemin du fichier JSON source (tableau d'objets ou JSON Lines)
        #[arg(short, long, value_name = "INPUT_FILE")]
        input: PathBuf,

        /// Nom de la table de destination
        #[arg(short, long, value_name = "TABLE_NAME")]
        table: String,

        /// Stratégie d'insertion
        #[arg(value_enum, short, long, default_value_t = ImportMode::Insert)]
        mode: ImportMode,

        /// Crée automatiquement la table si elle n'existe pas (inférence dynamique des types)
        #[arg(long, default_value_t = false)]
        create_table: bool,

        /// Spécifie la colonne servant de clé primaire lors de la création automatique
        #[arg(long, value_name = "COL_NAME")]
        primary_key: Option<String>,

        /// Taille de chaque lot transactionnel
        #[arg(long, default_value_t = 1000)]
        batch_size: usize,
    },

    /// Affiche le schéma d'une table SQLite
    Inspect {
        /// Chemin vers la base de données SQLite
        #[arg(short, long, value_name = "DB_PATH")]
        db: PathBuf,

        /// Nom de la table à inspecter
        #[arg(short, long, value_name = "TABLE_NAME")]
        table: String,
    },
}

/// Convertit une valeur Rusqlite (`ValueRef`) en `serde_json::Value`.
fn sqlite_value_to_json(val: ValueRef<'_>) -> JsonValue {
    match val {
        ValueRef::Null => JsonValue::Null,
        ValueRef::Integer(i) => JsonValue::from(i),
        ValueRef::Real(r) => serde_json::Number::from_f64(r)
            .map(JsonValue::Number)
            .unwrap_or(JsonValue::Null),
        ValueRef::Text(t) => {
            let s = String::from_utf8_lossy(t);
            JsonValue::String(s.into_owned())
        }
        ValueRef::Blob(b) => {
            // Encode les BLOBs en tableau d'entiers JSON ou hexadécimal
            let numbers: Vec<JsonValue> = b.iter().map(|&byte| JsonValue::from(byte)).collect();
            JsonValue::Array(numbers)
        }
    }
}

/// Convertit un `serde_json::Value` en valeur dynamique SQLite `rusqlite::types::Value`.
fn json_value_to_sqlite(val: &JsonValue) -> Value {
    match val {
        JsonValue::Null => Value::Null,
        JsonValue::Bool(b) => Value::Integer(if *b { 1 } else { 0 }),
        JsonValue::Number(n) => {
            if let Some(i) = n.as_i64() {
                Value::Integer(i)
            } else if let Some(f) = n.as_f64() {
                Value::Real(f)
            } else {
                Value::Text(n.to_string())
            }
        }
        JsonValue::String(s) => Value::Text(s.clone()),
        JsonValue::Array(_) | JsonValue::Object(_) => Value::Text(val.to_string()),
    }
}

/// Échappe un identifiant SQL (table ou colonne) avec des guillemets doubles.
fn quote_identifier(ident: &str) -> String {
    format!("\"{}\"", ident.replace('"', "\"\""))
}

/// Exporte les enregistrements d'une table SQLite vers un fichier plat JSON.
fn run_export(db_path: &Path, table: &str, output_path: &Path, pretty: bool) -> Result<()> {
    let conn = Connection::open(db_path)
        .with_context(|| format!("Impossible d'ouvrir la base SQLite {:?}", db_path))?;

    // Récupération des informations sur la table
    let count_query = format!("SELECT COUNT(*) FROM {}", quote_identifier(table));
    let total_rows: u64 = conn
        .query_row(&count_query, [], |row| row.get(0))
        .with_context(|| format!("Échec du décompte des lignes dans la table '{}'", table))?;

    let select_query = format!("SELECT * FROM {}", quote_identifier(table));
    let mut stmt = conn
        .prepare(&select_query)
        .with_context(|| format!("Impossible de préparer la requête SELECT pour '{}'", table))?;

    let column_names: Vec<String> = stmt
        .column_names()
        .into_iter()
        .map(|s| s.to_string())
        .collect();

    let pb = ProgressBar::new(total_rows);
    pb.set_style(
        ProgressStyle::default_bar()
            .template("{spinner:.green} [{elapsed_precise}] [{bar:40.cyan/blue}] {pos}/{len} ({eta}) {msg}")
            .context("Format de barre de progression invalide")?
            .progress_chars("#>-"),
    );
    pb.set_message("Exportation...");

    let mut rows = stmt
        .query([])
        .with_context(|| format!("Échec d'exécution de la requête SELECT sur '{}'", table))?;

    let mut exported_records: Vec<Map<String, JsonValue>> = Vec::with_capacity(total_rows as usize);

    while let Some(row) = rows.next().context("Erreur lors de la lecture d'une ligne")? {
        let mut obj = Map::with_capacity(column_names.len());
        for (i, col_name) in column_names.iter().enumerate() {
            let val_ref = row.get_ref(i).context("Lecture colonne invalide")?;
            obj.insert(col_name.clone(), sqlite_value_to_json(val_ref));
        }
        exported_records.push(obj);
        pb.inc(1);
    }

    pb.finish_with_message("Export terminé.");

    let file = File::create(output_path)
        .with_context(|| format!("Impossible de créer le fichier {:?}", output_path))?;
    let mut writer = BufWriter::new(file);

    if pretty {
        serde_json::to_writer_pretty(&mut writer, &exported_records)
            .context("Échec d'écriture du fichier JSON (pretty)")?;
    } else {
        serde_json::to_writer(&mut writer, &exported_records)
            .context("Échec d'écriture du fichier JSON")?;
    }
    writer.flush().context("Échec de synchronisation du fichier")?;

    println!(
        "Succès : {} lignes exportées avec succès vers {:?}",
        exported_records.len(),
        output_path
    );
    Ok(())
}

/// Infère le type SQL SQLite à partir d'une valeur JSON.
fn infer_sqlite_type(val: &JsonValue) -> &'static str {
    match val {
        JsonValue::Null => "TEXT",
        JsonValue::Bool(_) => "INTEGER",
        JsonValue::Number(n) => {
            if n.is_i64() {
                "INTEGER"
            } else {
                "REAL"
            }
        }
        JsonValue::String(_) => "TEXT",
        JsonValue::Array(_) | JsonValue::Object(_) => "TEXT",
    }
}

/// Crée la table dans SQLite basée sur les clés du premier enregistrement disponible.
fn ensure_table_created(
    conn: &Connection,
    table: &str,
    first_record: &Map<String, JsonValue>,
    primary_key: Option<&str>,
) -> Result<()> {
    let mut col_defs = Vec::new();

    for (key, val) in first_record {
        let sql_type = infer_sqlite_type(val);
        let is_pk = primary_key.map(|pk| pk.eq_ignore_ascii_case(key)).unwrap_or(false);
        if is_pk {
            col_defs.push(format!("{} {} PRIMARY KEY", quote_identifier(key), sql_type));
        } else {
            col_defs.push(format!("{} {}", quote_identifier(key), sql_type));
        }
    }

    if col_defs.is_empty() {
        anyhow::bail!("Impossible de déduire le schéma : l'objet JSON ne comporte aucune clé.");
    }

    let ddl = format!(
        "CREATE TABLE IF NOT EXISTS {} ({})",
        quote_identifier(table),
        col_defs.join(", ")
    );

    conn.execute(&ddl, [])
        .with_context(|| format!("Échec de création automatique de la table '{}'", table))?;

    Ok(())
}

/// Lit un fichier JSON plat (soit un tableau JSON global `[...]`, soit des lignes JSONLines).
fn load_json_records(input_path: &Path) -> Result<Vec<Map<String, JsonValue>>> {
    let file = File::open(input_path)
        .with_context(|| format!("Impossible d'ouvrir le fichier {:?}", input_path))?;
    let reader = BufReader::new(file);

    // Tentative 1 : Lecture sous forme de Value JSON standard
    let parsed: Result<JsonValue, _> = serde_json::from_reader(reader);
    match parsed {
        Ok(JsonValue::Array(items)) => {
            let mut list = Vec::with_capacity(items.len());
            for item in items {
                match item {
                    JsonValue::Object(map) => list.push(map),
                    _ => anyhow::bail!("Format JSON invalide : chaque élément du tableau doit être un objet."),
                }
            }
            Ok(list)
        }
        Ok(JsonValue::Object(single)) => Ok(vec![single]),
        Ok(_) => anyhow::bail!("Le fichier JSON doit contenir un tableau d'objets ou un objet racine."),
        Err(_) => {
            // Tentative 2 : Parsing JSON Lines
            let file = File::open(input_path)?;
            let reader = BufReader::new(file);
            use std::io::BufRead;

            let mut list = Vec::new();
            for (line_num, line) in reader.lines().enumerate() {
                let line_str = line.with_context(|| format!("Erreur de lecture à la ligne {}", line_num + 1))?;
                let trimmed = line_str.trim();
                if trimmed.is_empty() {
                    continue;
                }
                let val: JsonValue = serde_json::from_str(trimmed)
                    .with_context(|| format!("Erreur JSON à la ligne {}", line_num + 1))?;
                match val {
                    JsonValue::Object(map) => list.push(map),
                    _ => anyhow::bail!("Ligne {} : chaque ligne JSONL doit être un objet JSON", line_num + 1),
                }
            }
            Ok(list)
        }
    }
}

/// Importe les enregistrements JSON vers la table SQLite désignée.
fn run_import(
    db_path: &Path,
    input_path: &Path,
    table: &str,
    mode: ImportMode,
    create_table: bool,
    primary_key: Option<&str>,
    batch_size: usize,
) -> Result<()> {
    let records = load_json_records(input_path)?;
    if records.is_empty() {
        println!("Avertissement : Le fichier JSON ne contient aucun enregistrement à importer.");
        return Ok(());
    }

    let mut conn = Connection::open(db_path)
        .with_context(|| format!("Impossible d'ouvrir la base SQLite {:?}", db_path))?;

    if create_table {
        ensure_table_created(&conn, table, &records[0], primary_key)?;
    }

    // Récupérer la liste ordonnée des colonnes cibles
    let table_columns: Vec<String> = {
        let mut table_info_stmt = conn
            .prepare(&format!("PRAGMA table_info({})", quote_identifier(table)))
            .with_context(|| format!("Impossible de lire la structure de la table '{}'", table))?;

        let mapped = table_info_stmt
            .query_map([], |row| row.get::<_, String>(1))
            .with_context(|| format!("Erreur lors de la lecture des colonnes de '{}'", table))?;

        let cols: Result<Vec<String>, _> = mapped.collect();
        cols.with_context(|| "Erreur lors de la résolution des noms de colonnes")?
    };

    if table_columns.is_empty() {
        anyhow::bail!(
            "La table '{}' n'existe pas ou ne contient aucune colonne. Utilisez --create-table si nécessaire.",
            table
        );
    }

    let verb = match mode {
        ImportMode::Insert => "INSERT INTO",
        ImportMode::Replace => "INSERT OR REPLACE INTO",
        ImportMode::Ignore => "INSERT OR IGNORE INTO",
    };

    let col_names_quoted: Vec<String> = table_columns.iter().map(|c| quote_identifier(c)).collect();
    let placeholders: Vec<String> = (0..table_columns.len()).map(|_| "?".to_string()).collect();

    let insert_sql = format!(
        "{} {} ({}) VALUES ({})",
        verb,
        quote_identifier(table),
        col_names_quoted.join(", "),
        placeholders.join(", ")
    );

    let pb = ProgressBar::new(records.len() as u64);
    pb.set_style(
        ProgressStyle::default_bar()
            .template("{spinner:.green} [{elapsed_precise}] [{bar:40.cyan/blue}] {pos}/{len} ({eta}) {msg}")
            .context("Format de barre de progression invalide")?
            .progress_chars("#>-"),
    );
    pb.set_message("Insertion des données...");

    let mut total_inserted = 0;

    for chunk in records.chunks(batch_size) {
        let tx = conn
            .transaction()
            .context("Impossible d'initier une transaction SQLite")?;
        {
            let mut stmt = tx
                .prepare(&insert_sql)
                .context("Erreur de préparation du statement d'insertion")?;

            for record in chunk {
                let mut params: Vec<Value> = Vec::with_capacity(table_columns.len());
                for col in &table_columns {
                    if let Some(val) = record.get(col) {
                        params.push(json_value_to_sqlite(val));
                    } else {
                        params.push(Value::Null);
                    }
                }
                stmt.execute(params_from_iter(params))
                    .context("Échec lors de l'exécution de la ligne")?;
                total_inserted += 1;
                pb.inc(1);
            }
        }
        tx.commit().context("Échec lors du commit du lot")?;
    }

    pb.finish_with_message("Import terminé.");
    println!(
        "Succès : {} enregistrements insérés dans la table '{}'.",
        total_inserted, table
    );

    Ok(())
}

/// Inspecte la structure et le nombre de lignes d'une table SQLite.
fn run_inspect(db_path: &Path, table: &str) -> Result<()> {
    let conn = Connection::open(db_path)
        .with_context(|| format!("Impossible d'ouvrir la base SQLite {:?}", db_path))?;

    let count_query = format!("SELECT COUNT(*) FROM {}", quote_identifier(table));
    let total_rows: u64 = conn
        .query_row(&count_query, [], |row| row.get(0))
        .with_context(|| format!("Impossible de compter les lignes de '{}'", table))?;

    let mut pragma_stmt = conn
        .prepare(&format!("PRAGMA table_info({})", quote_identifier(table)))
        .with_context(|| format!("Impossible d'obtenir les métadonnées de '{}'", table))?;

    struct ColInfo {
        cid: i64,
        name: String,
        col_type: String,
        not_null: bool,
        pk: bool,
    }

    let cols = pragma_stmt
        .query_map([], |row| {
            Ok(ColInfo {
                cid: row.get(0)?,
                name: row.get(1)?,
                col_type: row.get(2)?,
                not_null: row.get::<_, i64>(3)? == 1,
                pk: row.get::<_, i64>(5)? == 1,
            })
        })?
        .collect::<Result<Vec<ColInfo>, _>>()?;

    println!("============================================================");
    println!(" Table : {}", table);
    println!(" Lignes : {}", total_rows);
    println!("------------------------------------------------------------");
    println!("{:<6} {:<20} {:<15} {:<10} {:<6}", "CID", "Nom", "Type", "NOT NULL", "PK");
    println!("------------------------------------------------------------");
    for col in cols {
        println!(
            "{:<6} {:<20} {:<15} {:<10} {:<6}",
            col.cid,
            col.name,
            col.col_type,
            if col.not_null { "OUI" } else { "NON" },
            if col.pk { "OUI" } else { "NON" }
        );
    }
    println!("============================================================");

    Ok(())
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Export {
            db,
            table,
            output,
            pretty,
        } => {
            run_export(&db, &table, &output, pretty)?;
        }
        Commands::Import {
            db,
            input,
            table,
            mode,
            create_table,
            primary_key,
            batch_size,
        } => {
            run_import(
                &db,
                &input,
                &table,
                mode,
                create_table,
                primary_key.as_deref(),
                batch_size,
            )?;
        }
        Commands::Inspect { db, table } => {
            run_inspect(&db, &table)?;
        }
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;

    #[test]
    fn test_export_import_roundtrip() -> Result<()> {
        let temp_dir = std::env::temp_dir().join("sqlite_json_test");
        let _ = fs::remove_dir_all(&temp_dir);
        fs::create_dir_all(&temp_dir)?;

        let db_path = temp_dir.join("test.db");
        let json_path = temp_dir.join("users.json");
        let table = "users";

        // Initialisation SQLite
        {
            let conn = Connection::open(&db_path)?;
            conn.execute(
