            conn.execute(
                "INSERT INTO users (id, name, score, active) VALUES (1, 'Alice', 95.5, 1), (2, 'Bob', 82.0, 0)",
                [],
            )?;
        }

        // Test Export
        run_export(&db_path, table, &json_path, true)?;
        assert!(json_path.exists());

        // Test Import dans une nouvelle table
        let target_table = "users_imported";
        run_import(
            &db_path,
            &json_path,
            target_table,
            ImportMode::Insert,
