// src/main.rs
use std::fs::File;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::Instant;

use anyhow::{bail, Context, Result};
use arrow::array::{
    ArrayRef, BooleanBuilder, Float32Builder, Float64Builder, Int32Builder, Int64Builder,
    StringBuilder, TimestampMicrosecondBuilder, TimestampMillisecondBuilder,
};
use arrow::datatypes::{DataType, Field, Schema as ArrowSchema, TimeUnit};
use arrow::record_batch::RecordBatch;
use clap::{Parser, ValueEnum};
use parquet::arrow::ArrowWriter;
use parquet::basic::Compression;
use parquet::file::properties::WriterProperties;
use rand::rngs::StdRng;
use rand::{Rng, SeedableRng};
use serde::{Deserialize, Serialize};

#[derive(Parser, Debug)]
#[command(
    name = "mock-parquet-gen",
    author = "Damien",
    version = "0.1.0",
    about = "Générateur de fausses données de test (mock data) sérialisées en Parquet avec schémas personnalisables"
)]
struct Cli {
    /// Chemin du fichier de schéma (JSON ou YAML). Si omis, un schéma e-commerce par défaut est utilisé.
    #[arg(short, long)]
    schema: Option<PathBuf>,

    /// Fichier Parquet de sortie
    #[arg(short, long, default_value = "mock_data.parquet")]
    output: PathBuf,

    /// Nombre total de lignes à générer
    #[arg(short = 'n', long, default_value_t = 100_000)]
    count: usize,

    /// Nombre de lignes par lot (RecordBatch en mémoire)
    #[arg(short = 'b', long, default_value_t = 10_000)]
    batch_size: usize,

    /// Algorithme de compression pour le fichier Parquet
    #[arg(short = 'c', long, value_enum, default_value_t = CompressionArg::Snappy)]
    compression: CompressionArg,

    /// Graine (seed) pour le générateur pseudo-aléatoire (reproductibilité des données)
    #[arg(long)]
    seed: Option<u64>,

    /// Affiche le schéma par défaut au format YAML et quitte
    #[arg(long)]
    dump_default_schema: bool,
}

#[derive(ValueEnum, Clone, Copy, Debug, PartialEq, Eq)]
enum CompressionArg {
    Uncompressed,
    Snappy,
    Gzip,
    Zstd,
}

impl From<CompressionArg> for Compression {
    fn from(arg: CompressionArg) -> Self {
        match arg {
            CompressionArg::Uncompressed => Compression::UNCOMPRESSED,
            CompressionArg::Snappy => Compression::SNAPPY,
            CompressionArg::Gzip => Compression::GZIP(parquet::basic::GzipLevel::default()),
            CompressionArg::Zstd => Compression::ZSTD(parquet::basic::ZstdLevel::default()),
        }
    }
}

/// Définition globale du schéma configurable
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SchemaDefinition {
    pub columns: Vec<ColumnDefinition>,
}

/// Définition d'une colonne individuelle
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ColumnDefinition {
    pub name: String,
    #[serde(rename = "type")]
    pub data_type: FieldType,
    #[serde(default)]
    pub null_ratio: f64,
    pub generator: GeneratorConfig,
}

/// Types de données Arrow supportés
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum FieldType {
    Int32,
    Int64,
    Float32,
    Float64,
    Utf8,
    Boolean,
    TimestampMillis,
    TimestampMicros,
}

impl FieldType {
    pub fn to_arrow_datatype(&self) -> DataType {
        match self {
            FieldType::Int32 => DataType::Int32,
            FieldType::Int64 => DataType::Int64,
            FieldType::Float32 => DataType::Float32,
            FieldType::Float64 => DataType::Float64,
            FieldType::Utf8 => DataType::Utf8,
            FieldType::Boolean => DataType::Boolean,
            FieldType::TimestampMillis => DataType::Timestamp(TimeUnit::Millisecond, None),
            FieldType::TimestampMicros => DataType::Timestamp(TimeUnit::Microsecond, None),
        }
    }
}

/// Types de générateurs de données mock
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum GeneratorConfig {
    Uuid,
    RangeInt {
        min: i64,
        max: i64,
    },
    RangeFloat {
        min: f64,
        max: f64,
    },
    Choice(Vec<String>),
    Boolean {
        #[serde(default = "default_true_prob")]
        true_probability: f64,
    },
    TimestampRange {
        /// Format RFC3339 (ex: "2024-01-01T00:00:00Z")
        start: String,
        /// Format RFC3339 (ex: "2024-12-31T23:59:59Z")
        end: String,
    },
    ProfileName,
    ProfileEmail,
    City,
    /// Variante pour supporter le format `{ range_int: { min: 1, max: 10 } }` ou `{ choice: [...] }`
    #[serde(untagged)]
    Nested(Box<NestedGeneratorConfig>),
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum NestedGeneratorConfig {
    RangeInt {
        min: i64,
        max: i64,
    },
    RangeFloat {
        min: f64,
        max: f64,
    },
    Choice(Vec<String>),
    Boolean {
        #[serde(default = "default_true_prob")]
        true_probability: f64,
    },
    TimestampRange {
        start: String,
        end: String,
    },
}

fn default_true_prob() -> f64 {
    0.5
}

/// Représentation compilée d'une colonne pour génération rapide en boucle
struct CompiledColumn {
    name: String,
    field_type: FieldType,
    null_ratio: f64,
    generator: CompiledGenerator,
}

enum CompiledGenerator {
    Uuid,
    RangeInt { min: i64, max: i64 },
    RangeFloat { min: f64, max: f64 },
    Choice(Vec<String>),
    Boolean { true_probability: f64 },
    TimestampRange { start_ms: i64, end_ms: i64 },
    ProfileName,
    ProfileEmail,
    City,
}

impl ColumnDefinition {
    fn compile(&self) -> Result<CompiledColumn> {
        let compiled_gen = match &self.generator {
            GeneratorConfig::Uuid => CompiledGenerator::Uuid,
            GeneratorConfig::RangeInt { min, max } => {
                if min > max {
                    bail!(
                        "La colonne '{}': min ({}) > max ({}) dans range_int",
                        self.name,
                        min,
                        max
                    );
                }
                CompiledGenerator::RangeInt {
                    min: *min,
                    max: *max,
                }
            }
            GeneratorConfig::RangeFloat { min, max } => {
                if min > max {
                    bail!(
                        "La colonne '{}': min ({}) > max ({}) dans range_float",
                        self.name,
                        min,
                        max
                    );
                }
                CompiledGenerator::RangeFloat {
                    min: *min,
                    max: *max,
                }
            }
            GeneratorConfig::Choice(choices) => {
                if choices.is_empty() {
                    bail!(
                        "La colonne '{}': la liste choice ne peut pas être vide",
                        self.name
                    );
                }
                CompiledGenerator::Choice(choices.clone())
            }
            GeneratorConfig::Boolean { true_probability } => {
                let prob = true_probability.clamp(0.0, 1.0);
                CompiledGenerator::Boolean {
                    true_probability: prob,
                }
            }
            GeneratorConfig::TimestampRange { start, end } => {
                let start_dt = chrono::DateTime::parse_from_rfc3339(start)
                    .with_context(|| format!("Date de début invalide pour '{}': {}", self.name, start))?;
                let end_dt = chrono::DateTime::parse_from_rfc3339(end)
                    .with_context(|| format!("Date de fin invalide pour '{}': {}", self.name, end))?;
                let start_ms = start_dt.timestamp_millis();
                let end_ms = end_dt.timestamp_millis();
                if start_ms > end_ms {
                    bail!(
                        "La colonne '{}': start ({}) > end ({})",
                        self.name,
                        start,
                        end
                    );
                }
                CompiledGenerator::TimestampRange { start_ms, end_ms }
            }
            GeneratorConfig::ProfileName => CompiledGenerator::ProfileName,
            GeneratorConfig::ProfileEmail => CompiledGenerator::ProfileEmail,
            GeneratorConfig::City => CompiledGenerator::City,
            GeneratorConfig::Nested(nested) => match nested.as_ref() {
                NestedGeneratorConfig::RangeInt { min, max } => {
                    if min > max {
                        bail!(
                            "La colonne '{}': min ({}) > max ({}) dans range_int",
                            self.name,
                            min,
                            max
                        );
                    }
                    CompiledGenerator::RangeInt {
                        min: *min,
                        max: *max,
                    }
                }
                NestedGeneratorConfig::RangeFloat { min, max } => {
                    if min > max {
                        bail!(
                            "La colonne '{}': min ({}) > max ({}) dans range_float",
                            self.name,
                            min,
                            max
                        );
                    }
                    CompiledGenerator::RangeFloat {
                        min: *min,
                        max: *max,
                    }
                }
                NestedGeneratorConfig::Choice(choices) => {
                    if choices.is_empty() {
                        bail!(
                            "La colonne '{}': la liste choice ne peut pas être vide",
                            self.name
                        );
                    }
                    CompiledGenerator::Choice(choices.clone())
                }
                NestedGeneratorConfig::Boolean { true_probability } => {
                    let prob = true_probability.clamp(0.0, 1.0);
                    CompiledGenerator::Boolean {
                        true_probability: prob,
                    }
                }
                NestedGeneratorConfig::TimestampRange { start, end } => {
                    let start_dt = chrono::DateTime::parse_from_rfc3339(start)
                        .with_context(|| format!("Date de début invalide pour '{}': {}", self.name, start))?;
                    let end_dt = chrono::DateTime::parse_from_rfc3339(end)
                        .with_context(|| format!("Date de fin invalide pour '{}': {}", self.name, end))?;
                    let start_ms = start_dt.timestamp_millis();
                    let end_ms = end_dt.timestamp_millis();
                    if start_ms > end_ms {
                        bail!(
                            "La colonne '{}': start ({}) > end ({})",
                            self.name,
                            start,
                            end
                        );
                    }
                    CompiledGenerator::TimestampRange { start_ms, end_ms }
                }
            },
        };

        Ok(CompiledColumn {
            name: self.name.clone(),
            field_type: self.data_type,
            null_ratio: self.null_ratio.clamp(0.0, 1.0),
            generator: compiled_gen,
        })
    }
}

