fn load_schema(path: &Path) -> Result<SchemaDefinition> {
    let content = std::fs::read_to_string(path)
        .with_context(|| format!("Impossible de lire le fichier de schéma : {:?}", path))?;

    let is_json = path
        .extension()
        .and_then(|ext| ext.to_str())
        .map(|s| s.eq_ignore_ascii_case("json"))
        .unwrap_or(false);

    if is_json {
        serde_json::from_str(&content)
            .with_context(|| "Échec du parsing JSON du fichier de schéma")
    } else {
        serde_yaml::from_str(&content)
            .with_context(|| "Échec du parsing YAML du fichier de schéma")
    }
}

fn build_arrow_schema(columns: &[CompiledColumn]) -> Arc<ArrowSchema> {
    let fields: Vec<Field> = columns
        .iter()
        .map(|col| {
            let nullable = col.null_ratio > 0.0;
            Field::new(&col.name, col.field_type.to_arrow_datatype(), nullable)
        })
        .collect();
    Arc::new(ArrowSchema::new(fields))
}

fn generate_column_array(
    col: &CompiledColumn,
    batch_size: usize,
    rng: &mut StdRng,
) -> Result<ArrayRef> {
    let check_null = |rng: &mut StdRng| -> bool {
        if col.null_ratio <= 0.0 {
            false
        } else {
            rng.gen_bool(col.null_ratio)
        }
    };

    let array: ArrayRef = match col.field_type {
        FieldType::Int32 => {
            let mut builder = Int32Builder::with_capacity(batch_size);
            for _ in 0..batch_size {
                if check_null(rng) {
                    builder.append_null();
                } else {
                    let val = match &col.generator {
                        CompiledGenerator::RangeInt { min, max } => {
                            rng.gen_range(*min..=*max) as i32
                        }
                        _ => rng.gen::<i32>(),
                    };
                    builder.append_value(val);
                }
            }
            Arc::new(builder.finish())
        }
        FieldType::Int64 => {
            let mut builder = Int64Builder::with_capacity(batch_size);
            for _ in 0..batch_size {
                if check_null(rng) {
                    builder.append_null();
                } else {
                    let val = match &col.generator {
                        CompiledGenerator::RangeInt { min, max } => rng.gen_range(*min..=*max),
                        _ => rng.gen::<i64>(),
                    };
                    builder.append_value(val);
                }
            }
            Arc::new(builder.finish())
        }
        FieldType::Float32 => {
            let mut builder = Float32Builder::with_capacity(batch_size);
            for _ in 0..batch_size {
                if check_null(rng) {
                    builder.append_null();
                } else {
                    let val = match &col.generator {
                        CompiledGenerator::RangeFloat { min, max } => {
                            rng.gen_range(*min..=*max) as f32
                        }
                        _ => rng.gen::<f32>(),
                    };
                    builder.append_value(val);
                }
            }
            Arc::new(builder.finish())
        }
        FieldType::Float64 => {
            let mut builder = Float64Builder::with_capacity(batch_size);
            for _ in 0..batch_size {
                if check_null(rng) {
                    builder.append_null();
                } else {
                    let val = match &col.generator {
                        CompiledGenerator::RangeFloat { min, max } => rng.gen_range(*min..=*max),
                        _ => rng.gen::<f64>(),
                    };
                    builder.append_value(val);
                }
            }
            Arc::new(builder.finish())
        }
        FieldType::Boolean => {
            let mut builder = BooleanBuilder::with_capacity(batch_size);
            for _ in 0..batch_size {
                if check_null(rng) {
                    builder.append_null();
                } else {
                    let val = match &col.generator {
                        CompiledGenerator::Boolean { true_probability } => {
                            rng.gen_bool(*true_probability)
                        }
                        _ => rng.gen_bool(0.5),
                    };
                    builder.append_value(val);
                }
            }
            Arc::new(builder.finish())
        }
        FieldType::Utf8 => {
            let mut builder = StringBuilder::with_capacity(batch_size, batch_size * 32);
            for _ in 0..batch_size {
                if check_null(rng) {
                    builder.append_null();
                } else {
                    match &col.generator {
                        CompiledGenerator::Uuid => {
                            let id = uuid::Uuid::new_v4();
                            builder.append_value(id.to_string());
                        }
                        CompiledGenerator::Choice(choices) => {
                            let idx = rng.gen_range(0..choices.len());
                            builder.append_value(&choices[idx]);
                        }
                        CompiledGenerator::ProfileName => {
                            let first = FIRST_NAMES[rng.gen_range(0..FIRST_NAMES.len())];
                            let last = LAST_NAMES[rng.gen_range(0..LAST_NAMES.len())];
                            builder.append_value(format!("{} {}", first, last));
                        }
                        CompiledGenerator::ProfileEmail => {
                            let first = FIRST_NAMES[rng.gen_range(0..FIRST_NAMES.len())];
                            let last = LAST_NAMES[rng.gen_range(0..LAST_NAMES.len())];
                            let domain = DOMAINS[rng.gen_range(0..DOMAINS.len())];
                            let num: u16 = rng.gen_range(1..999);
                            let email = format!(
                                "{}.{}{:02}@{}",
                                first.to_lowercase(),
                                last.to_lowercase(),
                                num,
                                domain
                            );
                            builder.append_value(email);
                        }
                        CompiledGenerator::City => {
                            let city = CITIES[rng.gen_range(0..CITIES.len())];
                            builder.append_value(city);
                        }
                        _ => {
                            let val = rng.gen_range(1000..9999).to_string();
                            builder.append_value(val);
                        }
                    }
                }
            }
            Arc::new(builder.finish())
        }
        FieldType::TimestampMillis => {
            let mut builder = TimestampMillisecondBuilder::with_capacity(batch_size);
            for _ in 0..batch_size {
                if check_null(rng) {
                    builder.append_null();
                } else {
                    let val = match &col.generator {
                        CompiledGenerator::TimestampRange { start_ms, end_ms } => {
                            rng.gen_range(*start_ms..=*end_ms)
                        }
                        _ => 0,
                    };
                    builder.append_value(val);
                }
            }
            Arc::new(builder.finish())
        }
        FieldType::TimestampMicros => {
            let mut builder = TimestampMicrosecondBuilder::with_capacity(batch_size);
            for _ in 0..batch_size {
                if check_null(rng) {
                    builder.append_null();
                } else {
                    let val = match &col.generator {
                        CompiledGenerator::TimestampRange { start_ms, end_ms } => {
                            let ms = rng.gen_range(*start_ms..=*end_ms);
                            ms * 1000
                        }
                        _ => 0,
                    };
                    builder.append_value(val);
                }
            }
            Arc::new(builder.finish())
        }
    };

    Ok(array)
}

fn generate_record_batch(
    schema: &Arc<ArrowSchema>,
    compiled_columns: &[CompiledColumn],
    batch_size: usize,
    rng: &mut StdRng,
) -> Result<RecordBatch> {
    let mut arrays: Vec<ArrayRef> = Vec::with_capacity(compiled_columns.len());
    for col in compiled_columns {
        let array = generate_column_array(col, batch_size, rng)
            .with_context(|| format!("Erreur lors de la génération de la colonne '{}'", col.name))?;
        arrays.push(array);
    }
    RecordBatch::try_new(Arc::clone(schema), arrays)
        .context("Échec de création du RecordBatch Arrow")
}

fn main() -> Result<()> {
    let args = Cli::parse();

    if args.dump_default_schema {
        let def = default_schema();
        let yaml_str = serde_yaml::to_string(&def)
            .context("Échec de sérialisation du schéma par défaut en YAML")?;
        println!("{}", yaml_str);
        return Ok(());
    }

    let schema_def = match &args.schema {
        Some(path) => {
            println!("Chargement du schéma personnalisé depuis {:?}", path);
            load_schema(path)?
        }
        None => {
            println!("Utilisation du schéma e-commerce par défaut");
            default_schema()
        }
    };

    if schema_def.columns.is_empty() {
        bail!("Le schéma doit comporter au moins une colonne");
    }

    let compiled_columns: Vec<CompiledColumn> = schema_def
        .columns
        .iter()
        .map(|c| c.compile())
        .collect::<Result<Vec<_>>>()?;

    let arrow_schema = build_arrow_schema(&compiled_columns);

    let mut rng = match args.seed {
        Some(seed) => {
            println!("Initialisation du RNG avec la graine (seed) : {}", seed);
            StdRng::seed_from_u64(seed)
        }
        None => StdRng::from_entropy(),
    };

    let file = File::create(&args.output)
        .with_context(|| format!("Impossible de créer le fichier de sortie {:?}", args.output))?;

    let props = WriterProperties::builder()
        .set_compression(args.compression.into())
        .build();

    let mut writer = ArrowWriter::try_new(file, Arc::clone(&arrow_schema), Some(props))
        .context("Échec de l'initialisation du Parquet ArrowWriter")?;

    let total_rows = args.count;
    let batch_size = args.batch_size.max(1);
    let mut remaining = total_rows;
    let mut generated_batches = 0usize;

    println!(
        "Génération de {} lignes (lots de {}, compression : {:?}) vers {:?}...",
        total_rows, batch_size, args.compression, args.output
    );

    let start_time = Instant::now();

    while remaining > 0 {
        let current_batch_size = remaining.min(batch_size);
        let batch = generate_record_batch(&arrow_schema, &compiled_columns, current_batch_size, &mut rng)?;
        writer
            .write(&batch)
            .context("Erreur lors de l'écriture d'un RecordBatch dans Parquet")?;
        remaining -= current_batch_size;
        generated_batches += 1;
    }

    let file_metadata = writer
        .close()
        .context("Erreur lors de la finalisation du fichier Parquet")?;

    let duration = start_time.elapsed();
    let speed = if duration.as_secs_f64() > 0.0 {
        (total_rows as f64) / duration.as_secs_f64()
    } else {
        total_rows as f64
    };

    let file_size = std::fs::metadata(&args.output)
        .map(|m| m.len())
        .unwrap_or(0);
    let file_size_mb = file_size as f64 / (1024.0 * 1024.0);

    println!("Génération terminée avec succès !");
    println!("  - Lignes écrites       : {}", file_metadata.num_rows);
    println!("  - Nombre de lots       : {}", generated_batches);
    println!("  - Taille du fichier    : {:.2} Mo ({} octets)", file_size_mb, file_size);
    println!("  - Durée                : {:.2?}", duration);
    println!("  - Débit moyen          : {:.0} lignes/sec", speed);

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_default_schema_compilation_and_generation() -> Result<()> {
        let schema_def = default_schema();
        let compiled: Vec<CompiledColumn> = schema_def
            .columns
            .iter()
            .map(|c| c.compile())
            .collect::<Result<Vec<_>>>()?;
        assert_eq!(compiled.len(), schema_def.columns.len());

        let arrow_schema = build_arrow_schema(&compiled);
        let mut rng = StdRng::seed_from_u64(42);
        let batch = generate_record_batch(&arrow_schema, &compiled, 50, &mut rng)?;

        assert_eq!(batch.num_rows(), 50);
        assert_eq!(batch.num_columns(), schema_def.columns.len());
        Ok(())
    }

    #[test]
    fn test_yaml_sensor_schema_parsing() -> Result<()> {
        let yaml_str = r#"
columns:
  - name: id
    type: utf8
    generator: uuid
  - name: temp
    type: float64
    generator:
      range_float:
        min: 10.0
        max: 30.0
  - name: code
    type: utf8
    generator:
      choice: ["A", "B", "C"]
"#;
        let schema_def: SchemaDefinition = serde_yaml::from_str(yaml_str)?;
        let compiled: Vec<CompiledColumn> = schema_def
            .columns
            .iter()
            .map(|c| c.compile())
            .collect::<Result<Vec<_>>>()?;
        assert_eq!(compiled.len(), 3);

        let arrow_schema = build_arrow_schema(&compiled);
        let mut rng = StdRng::seed_from_u64(12345);
        let batch = generate_record_batch(&arrow_schema, &compiled, 10, &mut rng)?;
        assert_eq!(batch.num_rows(), 10);
        assert_eq!(batch.num_columns(), 3);
        Ok(())
    }

    #[test]
    fn test_invalid_range_detection() {
        let col = ColumnDefinition {
            name: "bad_range".to_string(),
            data_type: FieldType::Int64,
            null_ratio: 0.0,
            generator: GeneratorConfig::RangeInt { min: 100, max: 10 },
        };
        assert!(col.compile().is_err());
    }
}


