/// Représentation compilée d'une colonne pour génération rapide en boucle
struct CompiledColumn {
    name: String,
    field_type: FieldType,
    null_ratio: f64,
    generator: CompiledGenerator,
}

enum CompiledGenerator {
    Uuid,
    RangeInt { min: i64, max: i64 },
    RangeFloat { min: f64, max: f64 },
    Choice(Vec<String>),
    Boolean { true_probability: f64 },
    TimestampRange { start_ms: i64, end_ms: i64 },
    ProfileName,
    ProfileEmail,
    City,
}

impl ColumnDefinition {
    fn compile(&self) -> Result<CompiledColumn> {
        let compiled_gen = match &self.generator {
            GeneratorConfig::Uuid => CompiledGenerator::Uuid,
            GeneratorConfig::RangeInt { min, max } => {
                if min > max {
                    bail!(
                        "La colonne '{}': min ({}) > max ({}) dans range_int",
                        self.name,
                        min,
                        max
                    );
                }
                CompiledGenerator::RangeInt {
                    min: *min,
                    max: *max,
                }
            }
            GeneratorConfig::RangeFloat { min, max } => {
                if min > max {
                    bail!(
                        "La colonne '{}': min ({}) > max ({}) dans range_float",
                        self.name,
                        min,
                        max
                    );
                }
                CompiledGenerator::RangeFloat {
                    min: *min,
                    max: *max,
                }
            }
            GeneratorConfig::Choice(choices) => {
                if choices.is_empty() {
                    bail!(
                        "La colonne '{}': la liste choice ne peut pas être vide",
                        self.name
                    );
                }
                CompiledGenerator::Choice(choices.clone())
            }
            GeneratorConfig::Boolean { true_probability } => {
                let prob = true_probability.clamp(0.0, 1.0);
                CompiledGenerator::Boolean {
                    true_probability: prob,
                }
            }
            GeneratorConfig::TimestampRange { start, end } => {
                let start_dt = chrono::DateTime::parse_from_rfc3339(start)
                    .with_context(|| format!("Date de début invalide pour '{}': {}", self.name, start))?;
                let end_dt = chrono::DateTime::parse_from_rfc3339(end)
                    .with_context(|| format!("Date de fin invalide pour '{}': {}", self.name, end))?;
                let start_ms = start_dt.timestamp_millis();
                let end_ms = end_dt.timestamp_millis();
                if start_ms > end_ms {
                    bail!(
                        "La colonne '{}': start ({}) > end ({})",
                        self.name,
                        start,
                        end
                    );
                }
                CompiledGenerator::TimestampRange { start_ms, end_ms }
            }
            GeneratorConfig::ProfileName => CompiledGenerator::ProfileName,
            GeneratorConfig::ProfileEmail => CompiledGenerator::ProfileEmail,
            GeneratorConfig::City => CompiledGenerator::City,
            GeneratorConfig::Nested(nested) => match nested.as_ref() {
                NestedGeneratorConfig::RangeInt { min, max } => {
                    if min > max {
                        bail!(
                            "La colonne '{}': min ({}) > max ({}) dans range_int",
                            self.name,
                            min,
                            max
                        );
                    }
                    CompiledGenerator::RangeInt {
                        min: *min,
                        max: *max,
                    }
                }
                NestedGeneratorConfig::RangeFloat { min, max } => {
                    if min > max {
                        bail!(
                            "La colonne '{}': min ({}) > max ({}) dans range_float",
                            self.name,
                            min,
                            max
                        );
                    }
                    CompiledGenerator::RangeFloat {
                        min: *min,
                        max: *max,
                    }
                }
                NestedGeneratorConfig::Choice(choices) => {
                    if choices.is_empty() {
                        bail!(
                            "La colonne '{}': la liste choice ne peut pas être vide",
                            self.name
                        );
                    }
                    CompiledGenerator::Choice(choices.clone())
                }
                NestedGeneratorConfig::Boolean { true_probability } => {
                    let prob = true_probability.clamp(0.0, 1.0);
                    CompiledGenerator::Boolean {
                        true_probability: prob,
                    }
                }
                NestedGeneratorConfig::TimestampRange { start, end } => {
                    let start_dt = chrono::DateTime::parse_from_rfc3339(start)
                        .with_context(|| format!("Date de début invalide pour '{}': {}", self.name, start))?;
                    let end_dt = chrono::DateTime::parse_from_rfc3339(end)
                        .with_context(|| format!("Date de fin invalide pour '{}': {}", self.name, end))?;
                    let start_ms = start_dt.timestamp_millis();
                    let end_ms = end_dt.timestamp_millis();
                    if start_ms > end_ms {
                        bail!(
                            "La colonne '{}': start ({}) > end ({})",
                            self.name,
                            start,
                            end
                        );
                    }
                    CompiledGenerator::TimestampRange { start_ms, end_ms }
                }
            },
        };

        Ok(CompiledColumn {
            name: self.name.clone(),
            field_type: self.data_type,
            null_ratio: self.null_ratio.clamp(0.0, 1.0),
            generator: compiled_gen,
        })
    }
}

