// src/main.rs
use std::fs::{File, OpenOptions};
use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::Duration;

use arrow::array::{Int64Array, RecordBatch, StringArray};
use arrow::datatypes::{DataType, Field, Schema};
use chrono::{DateTime, Utc};
use parquet::arrow::ArrowWriter;
use parquet::basic::Compression;
use parquet::file::properties::WriterProperties;
use serde::{Deserialize, Serialize};
use thiserror::Error;
use tokio::sync::{mpsc, oneshot};

#[derive(Error, Debug)]
pub enum AppError {
    #[error("Erreur I/O: {0}")]
    Io(#[from] std::io::Error),
    #[error("Erreur de sérialisation JSON: {0}")]
    Json(#[from] serde_json::Error),
    #[error("Erreur Arrow: {0}")]
    Arrow(#[from] arrow::error::ArrowError),
    #[error("Erreur Parquet: {0}")]
    Parquet(#[from] parquet::errors::ParquetError),
    #[error("Canal de communication fermé")]
    ChannelClosed,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Event {
    pub id: String,
    pub timestamp: DateTime<Utc>,
    pub level: String,
    pub source: String,
    pub message: String,
}

impl Event {
    pub fn new(level: impl Into<String>, source: impl Into<String>, message: impl Into<String>) -> Self {
        Self {
            id: uuid::Uuid::new_v4().to_string(),
            timestamp: Utc::now(),
            level: level.into(),
            source: source.into(),
            message: message.into(),
        }
    }
}

pub struct AppendOnlyLog {
    path: PathBuf,
}

impl AppendOnlyLog {
    pub fn new(path: impl Into<PathBuf>) -> Result<Self, AppError> {
        let path = path.into();
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        Ok(Self { path })
    }

    pub fn append(&self, event: &Event) -> Result<(), AppError> {
        let mut file = OpenOptions::new()
            .create(true)
            .append(true)
            .open(&self.path)?;
        let serialized = serde_json::to_string(event)?;
        writeln!(file, "{}", serialized)?;
        file.flush()?;
        Ok(())
    }

    pub fn read_all(&self) -> Result<Vec<Event>, AppError> {
        if !self.path.exists() {
            return Ok(Vec::new());
        }
        let file = File::open(&self.path)?;
        let reader = BufReader::new(file);
        let mut events = Vec::new();
        for line in reader.lines() {
            let line = line?;
            if line.trim().is_empty() {
                continue;
            }
            let event: Event = serde_json::from_str(&line)?;
            events.push(event);
        }
        Ok(events)
    }

    pub fn path(&self) -> &Path {
        &self.path
    }
}

pub struct ParquetCompactor {
    output_dir: PathBuf,
    schema: Arc<Schema>,
}

impl ParquetCompactor {
    pub fn new(output_dir: impl Into<PathBuf>) -> Result<Self, AppError> {
        let output_dir = output_dir.into();
        std::fs::create_dir_all(&output_dir)?;

        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Utf8, false),
            Field::new("timestamp_micros", DataType::Int64, false),
            Field::new("level", DataType::Utf8, false),
            Field::new("source", DataType::Utf8, false),
            Field::new("message", DataType::Utf8, false),
        ]));

        Ok(Self { output_dir, schema })
    }

    pub fn compact_events(&self, events: &[Event]) -> Result<Option<PathBuf>, AppError> {
        if events.is_empty() {
            return Ok(None);
        }

        let ids: Vec<String> = events.iter().map(|e| e.id.clone()).collect();
        let timestamps: Vec<i64> = events.iter().map(|e| e.timestamp.timestamp_micros()).collect();
        let levels: Vec<String> = events.iter().map(|e| e.level.clone()).collect();
        let sources: Vec<String> = events.iter().map(|e| e.source.clone()).collect();
        let messages: Vec<String> = events.iter().map(|e| e.message.clone()).collect();

        let id_array = StringArray::from(ids);
        let ts_array = Int64Array::from(timestamps);
        let level_array = StringArray::from(levels);
        let source_array = StringArray::from(sources);
        let message_array = StringArray::from(messages);

        let batch = RecordBatch::try_new(
            self.schema.clone(),
            vec![
                Arc::new(id_array),
                Arc::new(ts_array),
                Arc::new(level_array),
                Arc::new(source_array),
                Arc::new(message_array),
            ],
        )?;

        let timestamp_str = Utc::now().format("%Y%m%d_%H%M%S_%f");
        let filename = format!("events_compacted_{}.parquet", timestamp_str);
        let target_path = self.output_dir.join(filename);

        let file = File::create(&target_path)?;
        let props = WriterProperties::builder()
            .set_compression(Compression::SNAPPY)
            .build();

        let mut writer = ArrowWriter::try_new(file, self.schema.clone(), Some(props))?;
        writer.write(&batch)?;
        writer.close()?;

        Ok(Some(target_path))
    }
}

pub enum CompactionCommand {
    TriggerNow(oneshot::Sender<Result<Option<PathBuf>, AppError>>),
    Stop,
}

#[derive(Clone)]
pub struct EventLoggerHandle {
    wal: Arc<AppendOnlyLog>,
    cmd_tx: mpsc::Sender<CompactionCommand>,
}

impl EventLoggerHandle {
    pub fn log(&self, level: &str, source: &str, message: &str) -> Result<Event, AppError> {
        let event = Event::new(level, source, message);
        self.wal.append(&event)?;
        Ok(event)
    }

    pub async fn trigger_compaction(&self) -> Result<Option<PathBuf>, AppError> {
        let (resp_tx, resp_rx) = oneshot::channel();
        self.cmd_tx
            .send(CompactionCommand::TriggerNow(resp_tx))
            .await
            .map_err(|_| AppError::ChannelClosed)?;

        resp_rx.await.map_err(|_| AppError::ChannelClosed)?
    }

    pub async fn shutdown(&self) -> Result<(), AppError> {
        self.cmd_tx
            .send(CompactionCommand::Stop)
            .await
            .map_err(|_| AppError::ChannelClosed)
    }
}

pub struct LogManager;

impl LogManager {
    pub fn start(
        wal_path: impl Into<PathBuf>,
        parquet_dir: impl Into<PathBuf>,
        interval: Duration,
    ) -> Result<(EventLoggerHandle, tokio::task::JoinHandle<Result<(), AppError>>), AppError> {
        let wal = Arc::new(AppendOnlyLog::new(wal_path)?);
        let compactor = ParquetCompactor::new(parquet_dir)?;
        let (cmd_tx, mut cmd_rx) = mpsc::channel::<CompactionCommand>(32);

        let wal_clone = Arc::clone(&wal);
        let handle = EventLoggerHandle {
            wal: Arc::clone(&wal),
            cmd_tx,
        };

        let worker_handle = tokio::spawn(async move {
            let mut ticker = tokio::time::interval(interval);
            ticker.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);

            let perform_compaction = |wal: &AppendOnlyLog, compactor: &ParquetCompactor| -> Result<Option<PathBuf>, AppError> {
                let events = wal.read_all()?;
                if events.is_empty() {
                    return Ok(None);
                }

                let parquet_file = compactor.compact_events(&events)?;

                // Rotation WAL : si compacté avec succès, vider le fichier WAL
                if parquet_file.is_some() {
                    let file = OpenOptions::new()
                        .write(true)
                        .truncate(true)
                        .open(wal.path())?;
                    drop(file);
                }
                Ok(parquet_file)
            };

            loop {
                tokio::select! {
                    _ = ticker.tick() => {
                        match perform_compaction(&wal_clone, &compactor) {
                            Ok(Some(path)) => {
                                println!("[Compactor Worker] Compactage périodique réussi : {:?}", path);
                            }
                            Ok(None) => {}
                            Err(err) => {
                                eprintln!("[Compactor Worker] Échec du compactage périodique : {:?}", err);
                            }
                        }
                    }
                    cmd = cmd_rx.recv() => {
                        match cmd {
                            Some(CompactionCommand::TriggerNow(resp_tx)) => {
                                let res = perform_compaction(&wal_clone, &compactor);
                                let _ = resp_tx.send(res);
                            }
                            Some(CompactionCommand::Stop) | None => {
                                println!("[Compactor Worker] Arrêt du worker et compactage final...");
                                if let Err(err) = perform_compaction(&wal_clone, &compactor) {
                                    eprintln!("[Compactor Worker] Échec du compactage final : {:?}", err);
                                }
                                break;
                            }
                        }
                    }
                }
            }
            Ok(())
        });

        Ok((handle, worker_handle))
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("=== Démarrage du système de journalisation append-only avec compacteur Parquet ===");

    let base_dir = std::env::current_dir()?.join("data");
    let wal_path = base_dir.join("active_wal.log");
    let parquet_dir = base_dir.join("parquet_storage");

    let (logger, worker) = LogManager::start(
        wal_path.clone(),
        parquet_dir.clone(),
        Duration::from_millis(500),
    )?;

    println!("1. Émission d'événements initiaux dans le WAL...");
    for i in 1..=5 {
        let evt = logger.log(
            "INFO",
            "auth_service",
            &format!("Utilisateur user_{} authentifié avec succès", i),
        )?;
        println!("   [LOG WAL] ID: {} | {}", evt.id, evt.message);
    }

    println!("\n2. Compactage manuel déclenché...");
    let compacted_file = logger.trigger_compaction().await?;
    match compacted_file {
        Some(path) => println!("   -> Fichier Parquet produit : {}", path.display()),
        None => println!("   -> Aucun événement à compacter."),
    }

    println!("\n3. Émission d'événements continus pour déclencher le compactage périodique...");
    for i in 6..=10 {
        logger.log(
            "WARN",
            "payment_gateway",
            &format!("Tentative de débit pour la transaction tx_{} différée", i),
        )?;
    }

    // Pause pour laisser le timer périodique s'activer
    println!("   Attente du cycle de compactage automatique (700ms)...");
    tokio::time::sleep(Duration::from_millis(700)).await;

    println!("\n4. Émission d'événements de clôture...");
    logger.log("INFO", "system", "Arrêt ordonné du service demandé")?;

    println!("\n5. Arrêt du système et compactage résiduel...");
    logger.shutdown().await?;
    worker.await??;

    println!("\n=== Vérification des fichiers Parquet générés ===");
    let mut entries = std::fs::read_dir(&parquet_dir)?
        .filter_map(|e| e.ok())
        .collect::<Vec<_>>();
    entries.sort_by_key(|e| e.path());

    for entry in entries {
        let metadata = entry.metadata()?;
        println!(" - {} ({} octets)", entry.file_name().to_string_lossy(), metadata.len());
    }

    println!("\nSystème terminé avec succès.");
    Ok(())
}

