        assert_eq!(record.method, "GET");
        assert_eq!(record.path, "/apache_pb.gif");
        assert_eq!(record.protocol, "HTTP/1.0");
        assert_eq!(record.status, 200);
        assert_eq!(record.body_bytes_sent, 2326);
        assert_eq!(record.http_referer, Some("http://example.com/start".to_string()));
        assert_eq!(record.http_user_agent, Some("Mozilla/4.08 [en]".to_string()));
    }

    #[test]
    fn test_parse_common_log_format_without_referer_and_agent() {
        let line = r#"127.0.0.1 - - [10/Oct/2026:13:55:36 +0000] "POST /submit HTTP/1.1" 201 100"#;
        let record = WebLogRecord::parse_line(line).expect("Le parsing CLF doit réussir");

        assert_eq!(record.remote_addr, "127.0.0.1");
        assert_eq!(record.remote_user, None);
        assert_eq!(record.method, "POST");
        assert_eq!(record.path, "/submit");
        assert_eq!(record.status, 201);
        assert_eq!(record.body_bytes_sent, 100);
        assert_eq!(record.http_referer, None);
        assert_eq!(record.http_user_agent, None);
    }

    #[test]
    fn test_records_to_arrow_and_parquet() {
        let line = r#"127.0.0.1 - - [10/Oct/2026:13:55:36 +0000] "GET /index.html HTTP/1.1" 200 2326 "-" "-""#;
        let record = WebLogRecord::parse_line(line).expect("Parsing valide");
        let batch = records_to_record_batch(&[record]).expect("Conversion en RecordBatch");
        assert_eq!(batch.num_rows(), 1);
        assert_eq!(batch.num_columns(), 10);

        let mut buffer = Vec::new();
        let pipeline = LogToParquetPipeline::new(10);
        let metrics = pipeline
            .process_reader(Cursor::new(line.as_bytes()), &mut buffer)
            .expect("Pipeline en mémoire valide");

        assert_eq!(metrics.records_written, 1);
        assert_eq!(metrics.errors_skipped, 0);
        assert!(!buffer.is_empty());
    }
