        let time_raw = captures.name("time").map_or("", |m| m.as_str());
        // Exemple de format standard Apache/Nginx : "10/Oct/2000:13:55:36 -0700"
        let parsed_time = chrono::DateTime::parse_from_str(time_raw, "%d/%b/%Y:%H:%M:%S %z")
            .map_err(|e| LogParseError::DateParseError(time_raw.to_string(), e))?;
        let timestamp_ms = parsed_time.timestamp_millis();

        let request_str = captures.name("request").map_or("", |m| m.as_str());
        let mut req_parts = request_str.split_whitespace();
        let method = req_parts.next().unwrap_or("-").to_string();
        let path = req_parts.next().unwrap_or("-").to_string();
        let protocol = req_parts.next().unwrap_or("-").to_string();

        let status_raw = captures.name("status").map_or("0", |m| m.as_str());
        let status: u16 = status_raw
            .parse()
            .map_err(|e| LogParseError::StatusParseError(status_raw.to_string(), e))?;

        let bytes_raw = captures.name("bytes").map_or("0", |m| m.as_str());
        let body_bytes_sent: u64 = if bytes_raw == "-" {
            0
        } else {
            bytes_raw
                .parse()
                .map_err(|e| LogParseError::BytesParseError(bytes_raw.to_string(), e))?
        };

        let http_referer = captures
            .name("referer")
            .map(|m| m.as_str())
            .filter(|&s| s != "-")
            .map(|s| s.to_string());

        let http_user_agent = captures
            .name("agent")
            .map(|m| m.as_str())
            .filter(|&s| s != "-")
            .map(|s| s.to_string());

        Ok(Self {
            remote_addr: ip,
            remote_user: user,
            timestamp_ms,
            method,
            path,
            protocol,
            status,
            body_bytes_sent,
            http_referer,
            http_user_agent,
        })
    }
}

/// Définition du schéma Arrow typé correspondant aux colonnes Parquet cibles
pub fn build_arrow_schema() -> Arc<Schema> {
    Arc::new(Schema::new(vec![
        Field::new("remote_addr", DataType::Utf8, false),
        Field::new("remote_user", DataType::Utf8, true),
        Field::new(
            "timestamp",
            DataType::Timestamp(TimeUnit::Millisecond, Some("+00:00".into())),
            false,
        ),
        Field::new("method", DataType::Utf8, false),
        Field::new("path", DataType::Utf8, false),
        Field::new("protocol", DataType::Utf8, false),
        Field::new("status", DataType::UInt16, false),
        Field::new("body_bytes_sent", DataType::UInt64, false),
        Field::new("http_referer", DataType::Utf8, true),
        Field::new("http_user_agent", DataType::Utf8, true),
    ]))
}

/// Convertit un lot (`batch`) de structures `WebLogRecord` en un `RecordBatch` Arrow colonnaire
pub fn records_to_record_batch(records: &[WebLogRecord]) -> Result<RecordBatch> {
    let schema = build_arrow_schema();
    let capacity = records.len();

    let mut remote_addr_builder = StringBuilder::with_capacity(capacity, capacity * 16);
    let mut remote_user_builder = StringBuilder::with_capacity(capacity, capacity * 10);
    let mut timestamp_builder =
        TimestampMillisecondBuilder::with_capacity(capacity).with_timezone("+00:00");
    let mut method_builder = StringBuilder::with_capacity(capacity, capacity * 6);
    let mut path_builder = StringBuilder::with_capacity(capacity, capacity * 32);
    let mut protocol_builder = StringBuilder::with_capacity(capacity, capacity * 8);
    let mut status_builder = UInt16Builder::with_capacity(capacity);
    let mut body_bytes_builder = UInt64Builder::with_capacity(capacity);
    let mut referer_builder = StringBuilder::with_capacity(capacity, capacity * 32);
    let mut user_agent_builder = StringBuilder::with_capacity(capacity, capacity * 64);

    for record in records {
        remote_addr_builder.append_value(&record.remote_addr);

        match &record.remote_user {
            Some(user) => remote_user_builder.append_value(user),
            None => remote_user_builder.append_null(),
        }

        timestamp_builder.append_value(record.timestamp_ms);
        method_builder.append_value(&record.method);
        path_builder.append_value(&record.path);
        protocol_builder.append_value(&record.protocol);
        status_builder.append_value(record.status);
        body_bytes_builder.append_value(record.body_bytes_sent);

        match &record.http_referer {
            Some(ref_url) => referer_builder.append_value(ref_url),
            None => referer_builder.append_null(),
        }

        match &record.http_user_agent {
            Some(ua) => user_agent_builder.append_value(ua),
            None => user_agent_builder.append_null(),
        }
    }

    let columns: Vec<ArrayRef> = vec![
        Arc::new(remote_addr_builder.finish()),
        Arc::new(remote_user_builder.finish()),
        Arc::new(timestamp_builder.finish()),
        Arc::new(method_builder.finish()),
        Arc::new(path_builder.finish()),
        Arc::new(protocol_builder.finish()),
        Arc::new(status_builder.finish()),
        Arc::new(body_bytes_builder.finish()),
        Arc::new(referer_builder.finish()),
        Arc::new(user_agent_builder.finish()),
    ];

    RecordBatch::try_new(schema, columns).context("Échec de création du RecordBatch Arrow")
}

/// Pipeline de traitement : lecture flux en streaming -> lots -> écriture Parquet
pub struct LogToParquetPipeline {
    batch_size: usize,
    compression: Compression,
}

impl Default for LogToParquetPipeline {
    fn default() -> Self {
        Self {
            batch_size: 10_000,
            compression: Compression::SNAPPY,
        }
    }
}

impl LogToParquetPipeline {
    pub fn new(batch_size: usize) -> Self {
        Self {
            batch_size,
            compression: Compression::SNAPPY,
        }
    }

    /// Exécute l'extraction et l'écriture directe vers le fichier cible
    pub fn process_reader<R: BufRead, W: Write + Send>(
        &self,
        reader: R,
        writer_target: W,
    ) -> Result<PipelineMetrics> {
        let schema = build_arrow_schema();
        let props = WriterProperties::builder()
            .set_compression(self.compression)
            .build();

        let mut arrow_writer =
            ArrowWriter::try_new(writer_target, schema, Some(props))
                .context("Erreur lors de l'initialisation d'ArrowWriter")?;

        let mut current_batch = Vec::with_capacity(self.batch_size);
        let mut total_lines = 0usize;
        let mut parsed_records = 0usize;
        let mut skipped_errors = 0usize;

        for (idx, line_res) in reader.lines().enumerate() {
            let line = line_res.with_context(|| format!("Erreur de lecture I/O ligne {}", idx + 1))?;
            total_lines += 1;

            let trimmed = line.trim();
            if trimmed.is_empty() || trimmed.starts_with('#') {
                continue;
            }

            match WebLogRecord::parse_line(trimmed) {
                Ok(rec) => {
                    current_batch.push(rec);
                    parsed_records += 1;

                    if current_batch.len() >= self.batch_size {
                        let record_batch = records_to_record_batch(&current_batch)?;
                        arrow_writer
                            .write(&record_batch)
                            .context("Erreur lors de l'écriture du RecordBatch Parquet")?;
                        current_batch.clear();
                    }
                }
                Err(err) => {
                    tracing::warn!("Ligne {} ignorée : {}", idx + 1, err);
                    skipped_errors += 1;
                }
            }
        }

        // Vider le reliquat du dernier batch
        if !current_batch.is_empty() {
            let record_batch = records_to_record_batch(&current_batch)?;
            arrow_writer
                .write(&record_batch)
                .context("Erreur lors de l'écriture du dernier RecordBatch")?;
        }

        arrow_writer
            .close()
            .context("Erreur lors de la clôture du writer Parquet")?;

        Ok(PipelineMetrics {
            total_lines_read: total_lines,
            records_written: parsed_records,
            errors_skipped: skipped_errors,
        })
    }
}

#[derive(Debug, Clone, Copy)]
pub struct PipelineMetrics {
    pub total_lines_read: usize,
    pub records_written: usize,
    pub errors_skipped: usize,
}

#[derive(Parser, Debug)]
#[command(author, version, about = "Pipeline d'extraction de logs Web vers Parquet typé")]
struct CliArgs {
    /// Fichier source de logs (Apache ou Nginx). Si absent, un flux d'exemple sera utilisé.
    #[arg(short, long)]
    input: Option<PathBuf>,

    /// Fichier Parquet de sortie
    #[arg(short, long, default_value = "access_logs.parquet")]
    output: PathBuf,

    /// Taille des lots (batch size) pour la conversion Arrow/Parquet
    #[arg(short, long, default_value_t = 5000)]
    batch_size: usize,
}

const SAMPLE_LOGS: &str = r#"127.0.0.1 - - [10/Oct/2026:13:55:36 +0000] "GET /index.html HTTP/1.1" 200 2326 "-" "Mozilla/5.0 (X11; Linux x86_64)"
192.168.1.42 - alice [10/Oct/2026:13:55:37 +0000] "POST /api/v1/login HTTP/1.1" 200 512 "https://example.com/login" "curl/7.88.1"
10.0.0.15 - - [10/Oct/2026:13:55:38 +0000] "GET /assets/style.css HTTP/2.0" 304 0 "https://example.com/index.html" "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"
172.16.0.8 - - [10/Oct/2026:13:55:39 +0000] "GET /private/secret HTTP/1.1" 403 145 "-" "Python-urllib/3.10"
198.51.100.2 - - [10/Oct/2026:13:55:40 +0000] "GET /non-existent HTTP/1.1" 404 280 "https://google.com" "Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7)"
# Ligne de commentaire ignorée
203.0.113.195 - bob [10/Oct/2026:13:55:41 +0000] "PUT /api/v1/user/settings HTTP/1.1" 204 0 "https://example.com/settings" "PostmanRuntime/7.32.3"
"#;

fn run_pipeline(input_path: Option<&Path>, output_path: &Path, batch_size: usize) -> Result<PipelineMetrics> {
    let pipeline = LogToParquetPipeline::new(batch_size);

    let output_file = File::create(output_path)
        .with_context(|| format!("Impossible de créer le fichier Parquet '{}'", output_path.display()))?;

    let metrics = match input_path {
        Some(path) => {
            let file = File::open(path)
                .with_context(|| format!("Impossible d'ouvrir le fichier de log '{}'", path.display()))?;
            let reader = BufReader::new(file);
            pipeline.process_reader(reader, output_file)?
        }
        None => {
            tracing::info!("Aucun fichier d'entrée fourni. Traitement de logs synthétiques de démonstration...");
            let cursor = Cursor::new(SAMPLE_LOGS.as_bytes());
            pipeline.process_reader(cursor, output_file)?
        }
    };

    Ok(metrics)
}

fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    let args = CliArgs::parse();

    tracing::info!("Démarrage du pipeline de logs vers Parquet...");
    let metrics = run_pipeline(args.input.as_deref(), &args.output, args.batch_size)?;

    tracing::info!("--- Traitement terminé avec succès ---");
    tracing::info!("Lignes lues total : {}", metrics.total_lines_read);
    tracing::info!("Enregistrements écrits : {}", metrics.records_written);
    tracing::info!("Lignes en erreur ignorées : {}", metrics.errors_skipped);
    tracing::info!("Fichier Parquet généré : {}", args.output.display());

    Ok(())
}

