        assert_eq!(record.http_referer, None);
        assert_eq!(record.http_user_agent, None);
    }

    #[test]
    fn test_records_to_arrow_and_parquet() {
        let line = r#"127.0.0.1 - - [10/Oct/2026:13:55:36 +0000] "GET /index.html HTTP/1.1" 200 2326 "-" "-""#;
        let record = WebLogRecord::parse_line(line).expect("Parsing valide");
        let batch = records_to_record_batch(&[record]).expect("Conversion en RecordBatch");
        assert_eq!(batch.num_rows(), 1);
        assert_eq!(batch.num_columns(), 10);

        let mut buffer = Vec::new();
        let pipeline = LogToParquetPipeline::new(10);
        let metrics = pipeline
            .process_reader(Cursor::new(line.as_bytes()), &mut buffer)
            .expect("Pipeline en mémoire valide");

        assert_eq!(metrics.records_written, 1);
        assert_eq!(metrics.errors_skipped, 0);
        assert!(!buffer.is_empty());
    }
