// src/main.rs
use std::collections::BTreeSet;
use std::fs::File;
use std::io::BufReader;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use anyhow::{Context, Result};
use clap::{Parser, Subcommand};
use colored::*;
use serde_json::Value;

#[derive(Parser, Debug)]
#[command(
    name = "json-schema-cli",
    about = "CLI de validation de schémas JSON et comparaison de conformité structurelle",
    version
)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Valide un fichier JSON contre un JSON Schema
    Validate {
        /// Chemin vers le fichier JSON Schema
        #[arg(short, long)]
        schema: PathBuf,

        /// Chemin vers le fichier JSON à valider
        target: PathBuf,
    },

    /// Compare la structure et le contenu de deux fichiers JSON
    Diff {
        /// Premier fichier JSON (source / référence)
        source: PathBuf,

        /// Second fichier JSON (cible)
        target: PathBuf,

        /// Compare uniquement les types et la structure en ignorant le contenu des valeurs primitives
        #[arg(short = 's', long)]
        structure_only: bool,
    },

    /// Vérifie la conformité structurelle d'une cible par rapport à un gabarit de référence
    Conform {
        /// Document JSON de référence (gabarit attendu)
        #[arg(short, long)]
        reference: PathBuf,

        /// Document JSON à contrôler
        target: PathBuf,

        /// Interdire les clés supplémentaires dans la cible (mode strict)
        #[arg(long)]
        strict: bool,
    },
}

#[derive(Debug, PartialEq, Eq)]
enum DifferenceKind {
    MissingKey(String),
    ExtraKey(String),
    TypeMismatch {
        expected: &'static str,
        found: &'static str,
    },
    ValueMismatch {
        source: String,
        target: String,
    },
    ArrayLengthMismatch {
        source_len: usize,
        target_len: usize,
    },
}

#[derive(Debug)]
struct DiffEntry {
    path: String,
    kind: DifferenceKind,
}

fn type_name(val: &Value) -> &'static str {
    match val {
        Value::Null => "null",
        Value::Bool(_) => "boolean",
        Value::Number(_) => "number",
        Value::String(_) => "string",
        Value::Array(_) => "array",
        Value::Object(_) => "object",
    }
}

fn read_json_file(path: &Path) -> Result<Value> {
    let file = File::open(path)
        .with_context(|| format!("Impossible d'ouvrir le fichier '{}'", path.display()))?;
    let reader = BufReader::new(file);
    let val: Value = serde_json::from_reader(reader)
        .with_context(|| format!("Échec du parsing JSON du fichier '{}'", path.display()))?;
    Ok(val)
}

fn compare_values(
    path: &str,
    source: &Value,
    target: &Value,
    structure_only: bool,
    diffs: &mut Vec<DiffEntry>,
) {
    let source_type = type_name(source);
    let target_type = type_name(target);

    if source_type != target_type {
        diffs.push(DiffEntry {
            path: if path.is_empty() { "$".to_string() } else { path.to_string() },
            kind: DifferenceKind::TypeMismatch {
                expected: source_type,
                found: target_type,
            },
        });
        return;
    }

    match (source, target) {
        (Value::Object(map_src), Value::Object(map_tgt)) => {
            let mut all_keys: BTreeSet<&String> = BTreeSet::new();
            all_keys.extend(map_src.keys());
            all_keys.extend(map_tgt.keys());

            for key in all_keys {
                let current_path = if path.is_empty() {
                    format!("$.{key}")
                } else {
                    format!("{path}.{key}")
                };

                match (map_src.get(key), map_tgt.get(key)) {
                    (Some(src_val), Some(tgt_val)) => {
                        compare_values(&current_path, src_val, tgt_val, structure_only, diffs);
                    }
                    (Some(_), None) => {
                        diffs.push(DiffEntry {
                            path: current_path,
                            kind: DifferenceKind::MissingKey(key.clone()),
                        });
                    }
                    (None, Some(_)) => {
                        diffs.push(DiffEntry {
                            path: current_path,
                            kind: DifferenceKind::ExtraKey(key.clone()),
                        });
                    }
                    (None, None) => unreachable!(),
                }
            }
        }
        (Value::Array(arr_src), Value::Array(arr_tgt)) => {
            if arr_src.len() != arr_tgt.len() && !structure_only {
                diffs.push(DiffEntry {
                    path: if path.is_empty() { "$".to_string() } else { path.to_string() },
                    kind: DifferenceKind::ArrayLengthMismatch {
                        source_len: arr_src.len(),
                        target_len: arr_tgt.len(),
                    },
                });
            }

            let common_len = arr_src.len().min(arr_tgt.len());
            for idx in 0..common_len {
                let current_path = format!("{path}[{idx}]");
                compare_values(
                    &current_path,
                    &arr_src[idx],
                    &arr_tgt[idx],
                    structure_only,
                    diffs,
                );
            }
            if arr_src.len() > arr_tgt.len() {
                for idx in common_len..arr_src.len() {
                    diffs.push(DiffEntry {
                        path: format!("{path}[{idx}]"),
                        kind: DifferenceKind::MissingKey(format!("[{idx}]")),
                    });
                }
            } else if arr_tgt.len() > arr_src.len() {
                for idx in common_len..arr_tgt.len() {
                    diffs.push(DiffEntry {
                        path: format!("{path}[{idx}]"),
                        kind: DifferenceKind::ExtraKey(format!("[{idx}]")),
                    });
                }
            }
        }
        (val_src, val_tgt) => {
            if !structure_only && val_src != val_tgt {
                diffs.push(DiffEntry {
                    path: if path.is_empty() { "$".to_string() } else { path.to_string() },
                    kind: DifferenceKind::ValueMismatch {
                        source: val_src.to_string(),
                        target: val_tgt.to_string(),
                    },
                });
            }
        }
    }
}

fn check_conformance(
    path: &str,
    reference: &Value,
    target: &Value,
    strict: bool,
    errors: &mut Vec<String>,
) {
    let ref_type = type_name(reference);
    let tgt_type = type_name(target);

    if ref_type != tgt_type {
        let location = if path.is_empty() { "$" } else { path };
        errors.push(format!(
            "{} Type incompatible : attendu '{}', trouvé '{}'",
            location.yellow(),
            ref_type.cyan(),
            tgt_type.red()
        ));
        return;
    }

    match (reference, target) {
        (Value::Object(ref_map), Value::Object(tgt_map)) => {
            for (key, ref_val) in ref_map {
                let current_path = if path.is_empty() {
                    format!("$.{key}")
                } else {
                    format!("{path}.{key}")
                };

                match tgt_map.get(key) {
                    Some(tgt_val) => {
                        check_conformance(&current_path, ref_val, tgt_val, strict, errors);
                    }
                    None => {
                        errors.push(format!(
                            "{} Clé requise absente : '{}'",
                            current_path.yellow(),
                            key.red()
                        ));
                    }
                }
            }

            if strict {
                for key in tgt_map.keys() {
                    if !ref_map.contains_key(key) {
                        let current_path = if path.is_empty() {
                            format!("$.{key}")
                        } else {
                            format!("{path}.{key}")
                        };
                        errors.push(format!(
                            "{} Clé superflue interdite en mode strict : '{}'",
                            current_path.yellow(),
                            key.red()
                        ));
                    }
                }
            }
        }
        (Value::Array(ref_arr), Value::Array(tgt_arr)) => {
            if let Some(ref_sample) = ref_arr.first() {
                for (idx, item) in tgt_arr.iter().enumerate() {
                    let current_path = format!("{path}[{idx}]");
                    check_conformance(&current_path, ref_sample, item, strict, errors);
                }
            }
        }
        _ => {}
    }
}

fn run_validate(schema_path: &Path, target_path: &Path) -> Result<bool> {
    let schema_json = read_json_file(schema_path)?;
    let target_json = read_json_file(target_path)?;

    println!(
        "{} Validation de '{}' avec le schéma '{}'...",
        "⚙".blue().bold(),
        target_path.display().to_string().cyan(),
        schema_path.display().to_string().cyan()
    );

    let validator = jsonschema::validator_for(&schema_json)
        .map_err(|e| anyhow::anyhow!("Erreur lors de la compilation du schéma JSON: {}", e))?;

    let errors: Vec<_> = validator.iter_errors(&target_json).collect();

    if errors.is_empty() {
        println!(
            "{} Le document est parfaitement valide vis-à-vis du schéma.",
            "✔".green().bold()
        );
        Ok(true)
    } else {
        println!(
            "{} Le document présente {} erreur(s) de validation :",
            "✖".red().bold(),
            errors.len()
        );
        for (i, err) in errors.iter().enumerate() {
            println!(
                "  [{}] Chemin: {} | Message: {}",
                i + 1,
                err.instance_path.to_string().yellow(),
                err.to_string().red()
            );
        }
        Ok(false)
    }
}

fn run_diff(source_path: &Path, target_path: &Path, structure_only: bool) -> Result<bool> {
    let source_json = read_json_file(source_path)?;
    let target_json = read_json_file(target_path)?;

    println!(
        "{} Comparaison de '{}' (source) avec '{}' (cible) [mode: {}]...",
        "🔍".blue().bold(),
        source_path.display().to_string().cyan(),
        target_path.display().to_string().cyan(),
        if structure_only { "structure seule" } else { "complet" }.bold()
    );

    let mut diffs = Vec::new();
    compare_values("", &source_json, &target_json, structure_only, &mut diffs);

    if diffs.is_empty() {
        println!(
            "{} Aucune différence constatée. Les deux documents sont identiques.",
            "✔".green().bold()
        );
        Ok(true)
    } else {
        println!(
            "{} {} différence(s) détectée(s) :",
            "✖".yellow().bold(),
            diffs.len()
        );
        for d in &diffs {
            match &d.kind {
                DifferenceKind::MissingKey(k) => {
                    println!(
                        "  {} [-] Clé manquante dans la cible : '{}'",
                        d.path.yellow(),
                        k.red()
                    );
                }
                DifferenceKind::ExtraKey(k) => {
                    println!(
                        "  {} [+] Clé superflue dans la cible : '{}'",
                        d.path.yellow(),
                        k.green()
                    );
                }
                DifferenceKind::TypeMismatch { expected, found } => {
                    println!(
                        "  {} [~] Type divergent : attendu '{}', trouvé '{}'",
                        d.path.yellow(),
                        expected.cyan(),
                        found.red()
                    );
                }
                DifferenceKind::ValueMismatch { source, target } => {
                    println!(
                        "  {} [≠] Valeur modifiée : '{}' -> '{}'",
                        d.path.yellow(),
                        source.cyan(),
                        target.magenta()
                    );
                }
                DifferenceKind::ArrayLengthMismatch { source_len, target_len } => {
                    println!(
                        "  {} [≠] Taille de tableau différente : {} vs {}",
                        d.path.yellow(),
                        source_len,
                        target_len
                    );
                }
            }
        }
        Ok(false)
    }
}

fn run_conform(reference_path: &Path, target_path: &Path, strict: bool) -> Result<bool> {
    let ref_json = read_json_file(reference_path)?;
    let target_json = read_json_file(target_path)?;

    println!(
        "{} Vérification de conformité de '{}' selon le gabarit '{}' [strict: {}]...",
        "📐".blue().bold(),
