```rust
// src/main.rs
//! Module et CLI de fusion optimisée de fichiers Parquet.

use std::fs::File;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use anyhow::{bail, Context, Result};
use arrow::datatypes::SchemaRef;
use arrow::record_batch::RecordBatch;
use clap::Parser;
use indicatif::{ProgressBar, ProgressStyle};
use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;
use parquet::arrow::ArrowWriter;
use parquet::basic::Compression;
use parquet::file::properties::WriterProperties;
use tracing::info;

/// Paramètres de la ligne de commande pour fusionner des fichiers Parquet
#[derive(Parser, Debug)]
#[command(
    name = "parquet-merge",
    version,
    about = "Fusionne plusieurs fichiers Parquet partageant un même schéma en un fichier unique optimisé."
)]
pub struct CliArgs {
    /// Chemins des fichiers Parquet en entrée
    #[arg(short = 'i', long = "input", num_args = 1.., required_unless_present = "run_demo")]
    pub inputs: Vec<PathBuf>,

    /// Chemin du fichier Parquet de sortie
    #[arg(short = 'o', long = "output", required = true)]
    pub output: PathBuf,

    /// Algorithme de compression pour le fichier fusionné
    #[arg(short = 'c', long = "compression", default_value = "zstd")]
    pub compression: String,

    /// Taille maximale en octets d'un row group avant découpe (défaut : 128 Mo)
    #[arg(long = "max-row-group-size", default_value_t = 128 * 1024 * 1024)]
    pub max_row_group_size: usize,

    /// Taille des RecordBatches lus par itération (nombre de lignes)
    #[arg(long = "batch-size", default_value_t = 8192)]
    pub batch_size: usize,

    /// Écrase le fichier de sortie s'il existe déjà
    #[arg(short = 'f', long = "force", default_value_t = false)]
    pub force: bool,

    /// Mode démo automatique : génère des fichiers de test et les fusionne
    #[arg(long = "run-demo", default_value_t = false)]
    pub run_demo: bool,
}

/// Convertit une chaîne de caractères en enum de compression Parquet
pub fn parse_compression(comp: &str) -> Result<Compression> {
    match comp.to_ascii_lowercase().as_str() {
        "uncompressed" | "none" => Ok(Compression::UNCOMPRESSED),
        "snappy" => Ok(Compression::SNAPPY),
        "zstd" => Ok(Compression::ZSTD(parquet::basic::ZstdLevel::default())),
        "lz4" | "lz4_raw" => Ok(Compression::LZ4_RAW),
        "gzip" => Ok(Compression::GZIP(parquet::basic::GzipLevel::default())),
        other => bail!(
            "Algorithme de compression non supporté : '{}'. Options valides : uncompressed, snappy, zstd, lz4_raw, gzip.",
            other
        ),
    }
}

/// Structure orchestrant la fusion de fichiers Parquet
pub struct ParquetMerger {
    inputs: Vec<PathBuf>,
    output: PathBuf,
    compression: Compression,
    max_row_group_size: usize,
    batch_size: usize,
    force: bool,
}

impl ParquetMerger {
    pub fn new(
        inputs: Vec<PathBuf>,
        output: PathBuf,
        compression: Compression,
        max_row_group_size: usize,
        batch_size: usize,
        force: bool,
    ) -> Self {
        Self {
            inputs,
            output,
            compression,
            max_row_group_size,
            batch_size,
            force,
        }
    }

    /// Exécute la validation et la fusion en streaming
    pub fn execute(&self) -> Result<()> {
        if self.inputs.is_empty() {
            bail!("Aucun fichier d'entrée fourni.");
        }

        if self.output.exists() && !self.force {
            bail!(
                "Le fichier de sortie '{:?}' existe déjà. Utilisez --force (-f) pour écraser.",
                self.output
            );
        }

        // Valider l'existence de chaque fichier
        for path in &self.inputs {
            if !path.is_file() {
                bail!("Le fichier d'entrée '{:?}' n'existe pas ou n'est pas un fichier régulier.", path);
            }
        }

        info!("Étape 1/2 : Validation et extraction du schéma de référence...");
        let reference_schema = self.read_and_validate_schemas()?;

        info!("Schéma validé avec succès. Champs détectés : {}", reference_schema.fields().len());

        info!("Étape 2/2 : Fusion en streaming des RecordBatches...");
        self.stream_merge(reference_schema)?;

        info!("Fusion terminée avec succès : {:?}", self.output);
        Ok(())
    }

    /// Lit le schéma de chaque fichier Parquet et s'assure qu'ils sont strictement identiques
    fn read_and_validate_schemas(&self) -> Result<SchemaRef> {
        let first_path = &self.inputs[0];
        let first_file = File::open(first_path)
            .with_context(|| format!("Impossible d'ouvrir le premier fichier {:?}", first_path))?;
        let first_reader = ParquetRecordBatchReaderBuilder::try_new(first_file)
            .with_context(|| format!("Impossible d'analyser les métadonnées Parquet de {:?}", first_path))?;
        let reference_schema = first_reader.schema().clone();

        for path in self.inputs.iter().skip(1) {
            let file = File::open(path)
                .with_context(|| format!("Impossible d'ouvrir le fichier {:?}", path))?;
            let reader = ParquetRecordBatchReaderBuilder::try_new(file)
                .with_context(|| format!("Impossible d'analyser les métadonnées de {:?}", path))?;
            let current_schema = reader.schema();

            if reference_schema.fields() != current_schema.fields() {
                bail!(
                    "Incompatibilité de schéma détectée dans '{:?}'.\nAttendu :\n{:#?}\nObtenu :\n{:#?}",
                    path,
                    reference_schema,
                    current_schema
                );
            }
        }

        Ok(reference_schema)
    }

    /// Effectue la fusion par flux sans charger l'intégralité des données en mémoire vive
    fn stream_merge(&self, schema: SchemaRef) -> Result<()> {
        let output_file = File::create(&self.output)
            .with_context(|| format!("Impossible de créer le fichier de sortie {:?}", self.output))?;

        let props = WriterProperties::builder()
            .set_compression(self.compression)
            .set_max_row_group_size(self.max_row_group_size)
            .build();

        let mut writer = ArrowWriter::try_new(output_file, schema, Some(props))
            .context("Échec de l'initialisation du ArrowWriter Parquet")?;

        let pb = ProgressBar::new(self.inputs.len() as u64);
        pb.set_style(
            ProgressStyle::default_bar()
                .template("[{elapsed_precise}] {bar:40.cyan/blue} {pos}/{len} fichiers ({msg})")
                .context("Erreur de gabarit pour la barre de progression")?
                .progress_chars("#>-"),
        );

        let mut total_rows = 0usize;
        let mut total_batches = 0usize;

        for input_path in &self.inputs {
            let file_name = input_path
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or("fichier");
            pb.set_message(file_name.to_string());

            let file = File::open(input_path)
                .with_context(|| format!("Impossible d'ouvrir le fichier {:?}", input_path))?;

            let builder = ParquetRecordBatchReaderBuilder::try_new(file)
                .with_context(|| format!("Échec du builder Parquet pour {:?}", input_path))?
                .with_batch_size(self.batch_size);

            let reader = builder
                .build()
                .with_context(|| format!("Échec de l'initialisation du lecteur Parquet pour {:?}", input_path))?;

            for batch_result in reader {
                let batch: RecordBatch = batch_result
                    .with_context(|| format!("Erreur lors de la lecture d'un RecordBatch dans {:?}", input_path))?;
                total_rows += batch.num_rows();
                total_batches += 1;
                writer.write(&batch).with_context(|| {
                    format!("Erreur lors de l'écriture du batch dans {:?}", self.output)
                })?;
            }

            pb.inc(1);
        }

        pb.finish_with_message("Terminé");

        let file_metadata = writer
            .close()
            .context("Erreur lors de la finalisation et fermeture de l'ArrowWriter")?;

        info!(
            "Synthèse : {} lignes au total réparties dans {} batch(es) et {} RowGroup(s) écrit(s).",
            total_rows,
            total_batches,
            file_metadata.row_groups.len()
        );

        Ok(())
    }
}

/// Génère des fichiers Parquet d'exemple pour valider la procédure de fusion
pub fn generate_sample_data(output_dir: &Path) -> Result<Vec<PathBuf>> {
    use arrow::array::{Int64Array, StringArray};
    use arrow::datatypes::{DataType, Field, Schema};

    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int64, false),
        Field::new("nom", DataType::Utf8, false),
        Field::new("score", DataType::Int64, true),
    ]));

    let mut generated_paths = Vec::new();

    for i in 1..=3 {
        let path = output_dir.join(format!("chunk_{}.parquet", i));
        let file = File::create(&path)
            .with_context(|| format!("Échec de création du fichier d'exemple {:?}", path))?;

        let id_offset = (i - 1) * 1000;
        let ids: Vec<i64> = (1..=1000).map(|x| id_offset + x).collect();
        let names: Vec<String> = ids.iter().map(|id| format!("Entité_{}", id)).collect();
        let scores: Vec<Option<i64>> = ids.iter().map(|id| Some(id % 100)).collect();

        let batch = RecordBatch::try_new(
            schema.clone(),
            vec![
                Arc::new(Int64Array::from(ids)),
                Arc::new(StringArray::from_iter_values(names.iter().map(|s| s.as_str()))),
                Arc::new(Int64Array::from(scores)),
            ],
        )
        .context("Création du RecordBatch de test échouée")?;

        let props = WriterProperties::builder()
            .set_compression(Compression::SNAPPY)
            .build();

        let mut writer = ArrowWriter::try_new(file, schema.clone(), Some(props))
            .context("Initialisation du ArrowWriter de test échouée")?;

        writer.write(&batch).context("Écriture du batch de test")?;
        writer.close().context("Fermeture du fichier test")?;

        generated_paths.push(path);
    }

    Ok(generated_paths)
}

fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
