    ]));

    let mut generated_paths = Vec::new();

    for i in 1..=3 {
        let path = output_dir.join(format!("chunk_{}.parquet", i));
        let file = File::create(&path)
            .with_context(|| format!("Échec de création du fichier d'exemple {:?}", path))?;

        let id_offset = (i - 1) * 1000;
        let ids: Vec<i64> = (1..=1000).map(|x| id_offset + x).collect();
        let names: Vec<String> = ids.iter().map(|id| format!("Entité_{}", id)).collect();
        let scores: Vec<Option<i64>> = ids.iter().map(|id| Some(id % 100)).collect();

        let batch = RecordBatch::try_new(
            schema.clone(),
            vec![
                Arc::new(Int64Array::from(ids)),
                Arc::new(StringArray::from_iter_values(names.iter().map(|s| s.as_str()))),
                Arc::new(Int64Array::from(scores)),
            ],
        )
        .context("Création du RecordBatch de test échouée")?;

        let props = WriterProperties::builder()
            .set_compression(Compression::SNAPPY)
            .build();

        let mut writer = ArrowWriter::try_new(file, schema.clone(), Some(props))
            .context("Initialisation du ArrowWriter de test échouée")?;

        writer.write(&batch).context("Écriture du batch de test")?;
        writer.close().context("Fermeture du fichier test")?;

        generated_paths.push(path);
    }

    Ok(generated_paths)
}

fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    let args = CliArgs::parse();

    if args.run_demo {
        info!("--- Lancement du mode démonstration ---");
        let temp_dir = tempfile::tempdir().context("Échec de création du dossier temporaire")?;
        let demo_inputs = generate_sample_data(temp_dir.path())?;
        info!("Fichiers de test générés :");
