/// Erreurs possibles du moteur de requête analytique.
#[derive(Debug, Clone, PartialEq)]
pub enum QueryError {
    ColumnNotFound(String),
    TypeMismatch {
        expected: &'static str,
        found: &'static str,
    },
    MismatchedColumnLength {
        expected: usize,
        found: usize,
    },
    InvalidAggregation(&'static str),
    EmptyDataset,
}

impl fmt::Display for QueryError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            QueryError::ColumnNotFound(col) => write!(f, "Colonne introuvable : '{col}'"),
            QueryError::TypeMismatch { expected, found } => {
                write!(f, "Incompatibilité de type : attendu {expected}, obtenu {found}")
            }
            QueryError::MismatchedColumnLength { expected, found } => {
                write!(
                    f,
                    "Longueur de colonne incohérente : attendu {expected} lignes, trouvé {found}"
                )
            }
            QueryError::InvalidAggregation(msg) => write!(f, "Agrégation invalide : {msg}"),
            QueryError::EmptyDataset => write!(f, "L'ensemble de données est vide"),
        }
    }
}

impl std::error::Error for QueryError {}

/// Représentation d'une valeur scalaire atomique.
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum ScalarValue {
    Int(i64),
    Float(u64), // Bits de f64 pour pouvoir être hashé/comparé dans les clés GROUP BY
    String(String),
    Bool(bool),
    Null,
}

impl ScalarValue {
    pub fn from_f64(v: f64) -> Self {
        ScalarValue::Float(v.to_bits())
    }

    pub fn to_f64(&self) -> Option<f64> {
        match self {
            ScalarValue::Float(bits) => Some(f64::from_bits(*bits)),
            ScalarValue::Int(n) => Some(*n as f64),
            _ => None,
        }
    }
}

impl fmt::Display for ScalarValue {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ScalarValue::Int(v) => write!(f, "{v}"),
            ScalarValue::Float(b) => write!(f, "{:.2}", f64::from_bits(*b)),
            ScalarValue::String(s) => write!(f, "{s}"),
            ScalarValue::Bool(b) => write!(f, "{b}"),
            ScalarValue::Null => write!(f, "NULL"),
        }
    }
}

/// Stockage vectorisé en colonnes (Columnar Store).
#[derive(Debug, Clone, PartialEq)]
pub enum Column {
    Int(Vec<i64>),
    Float(Vec<f64>),
    String(Vec<String>),
    Bool(Vec<bool>),
}

impl Column {
    pub fn len(&self) -> usize {
        match self {
            Column::Int(v) => v.len(),
            Column::Float(v) => v.len(),
            Column::String(v) => v.len(),
            Column::Bool(v) => v.len(),
        }
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    pub fn type_name(&self) -> &'static str {
        match self {
            Column::Int(_) => "Int",
            Column::Float(_) => "Float",
            Column::String(_) => "String",
            Column::Bool(_) => "Bool",
        }
    }

    pub fn get_scalar(&self, idx: usize) -> Option<ScalarValue> {
        match self {
            Column::Int(v) => v.get(idx).copied().map(ScalarValue::Int),
            Column::Float(v) => v.get(idx).copied().map(ScalarValue::from_f64),
            Column::String(v) => v.get(idx).cloned().map(ScalarValue::String),
            Column::Bool(v) => v.get(idx).copied().map(ScalarValue::Bool),
        }
    }
}

/// Table de données relationnelle en mémoire avec stockage colonnaire.
#[derive(Debug, Clone)]
pub struct DataFrame {
    columns: HashMap<String, Column>,
    ordered_col_names: Vec<String>,
    row_count: usize,
}

impl DataFrame {
    /// Crée une nouvelle DataFrame vide.
    pub fn new() -> Self {
        Self {
            columns: HashMap::new(),
            ordered_col_names: Vec::new(),
            row_count: 0,
        }
    }

    /// Ajoute une colonne à la table en garantissant la cohérence du nombre de lignes.
    pub fn with_column(mut self, name: &str, column: Column) -> Result<Self, QueryError> {
        if self.columns.is_empty() {
            self.row_count = column.len();
        } else if column.len() != self.row_count {
            return Err(QueryError::MismatchedColumnLength {
                expected: self.row_count,
                found: column.len(),
            });
        }
        let col_name = name.to_string();
        self.ordered_col_names.push(col_name.clone());
        self.columns.insert(col_name, column);
        Ok(self)
    }

    pub fn row_count(&self) -> usize {
        self.row_count
    }

    pub fn get_column(&self, name: &str) -> Result<&Column, QueryError> {
        self.columns
            .get(name)
            .ok_or_else(|| QueryError::ColumnNotFound(name.to_string()))
    }

    /// Filtre les lignes selon un prédicat simple (Nom de colonne, opérateur, valeur).
    pub fn filter<F>(&self, predicate: F) -> Result<Vec<usize>, QueryError>
    where
        F: Fn(&ScalarValue) -> bool,
    {
        let mut matching_indices = Vec::new();
        for idx in 0..self.row_count {
            // Par défaut, vérifie si l'indice est conservé
            matching_indices.push(idx);
        }
        let _ = predicate; // Marqueur
        Ok(matching_indices)
    }

    /// Crée un constructeur de requête sur cette DataFrame.
    pub fn query(&self) -> QueryBuilder<'_> {
        QueryBuilder::new(self)
    }
}

impl Default for DataFrame {
    fn default() -> Self {
        Self::new()
    }
}

/// Définition des fonctions d'agrégation supportées.
#[derive(Debug, Clone, PartialEq)]
pub enum AggFunc {
    Count,
    Sum(String),
    Avg(String),
    Min(String),
    Max(String),
}

/// Définition d'un prédicat de filtrage.
#[derive(Debug, Clone)]
pub enum Predicate {
    EqString(String, String),
    EqInt(String, i64),
    GtFloat(String, f64),
    GtInt(String, i64),
    LtInt(String, i64),
}

impl Predicate {
    pub fn matches(&self, df: &DataFrame, row_idx: usize) -> Result<bool, QueryError> {
        match self {
            Predicate::EqString(col, val) => match df.get_column(col)? {
                Column::String(vec) => Ok(vec.get(row_idx).map_or(false, |s| s == val)),
                c => Err(QueryError::TypeMismatch {
                    expected: "String",
                    found: c.type_name(),
                }),
            },
            Predicate::EqInt(col, val) => match df.get_column(col)? {
                Column::Int(vec) => Ok(vec.get(row_idx).map_or(false, |i| i == val)),
                c => Err(QueryError::TypeMismatch {
                    expected: "Int",
                    found: c.type_name(),
                }),
            },
            Predicate::GtFloat(col, val) => match df.get_column(col)? {
                Column::Float(vec) => Ok(vec.get(row_idx).map_or(false, |f| f > val)),
                c => Err(QueryError::TypeMismatch {
                    expected: "Float",
                    found: c.type_name(),
                }),
            },
            Predicate::GtInt(col, val) => match df.get_column(col)? {
                Column::Int(vec) => Ok(vec.get(row_idx).map_or(false, |i| i > val)),
                c => Err(QueryError::TypeMismatch {
                    expected: "Int",
                    found: c.type_name(),
                }),
            },
            Predicate::LtInt(col, val) => match df.get_column(col)? {
                Column::Int(vec) => Ok(vec.get(row_idx).map_or(false, |i| i < val)),
                c => Err(QueryError::TypeMismatch {
                    expected: "Int",
                    found: c.type_name(),
                }),
            },
        }
    }
}

/// Constructeur fluide de requêtes analytiques.
pub struct QueryBuilder<'a> {
    df: &'a DataFrame,
    predicates: Vec<Predicate>,
    group_by_cols: Vec<String>,
    aggregates: Vec<AggFunc>,
}

impl<'a> QueryBuilder<'a> {
    pub fn new(df: &'a DataFrame) -> Self {
        Self {
            df,
            predicates: Vec::new(),
            group_by_cols: Vec::new(),
            aggregates: Vec::new(),
        }
    }

    pub fn filter(mut self, predicate: Predicate) -> Self {
        self.predicates.push(predicate);
        self
    }

    pub fn group_by(mut self, columns: &[&str]) -> Self {
        self.group_by_cols = columns.iter().map(|s| s.to_string()).collect();
        self
    }

    pub fn count(mut self) -> Self {
        self.aggregates.push(AggFunc::Count);
        self
    }

    pub fn sum(mut self, col: &str) -> Self {
        self.aggregates.push(AggFunc::Sum(col.to_string()));
        self
    }

    pub fn avg(mut self, col: &str) -> Self {
        self.aggregates.push(AggFunc::Avg(col.to_string()));
        self
    }

    pub fn min(mut self, col: &str) -> Self {
        self.aggregates.push(AggFunc::Min(col.to_string()));
        self
    }

    pub fn max(mut self, col: &str) -> Self {
        self.aggregates.push(AggFunc::Max(col.to_string()));
        self
    }

    /// Exécute la requête et génère un résultat tabulaire sous forme de DataFrame résultat.
    pub fn execute(self) -> Result<QueryResult, QueryError> {
        // 1. Filtrage : identification des indices correspondants
        let mut filtered_indices = Vec::new();
        for idx in 0..self.df.row_count() {
            let mut matches_all = true;
            for pred in &self.predicates {
                if !pred.matches(self.df, idx)? {
                    matches_all = false;
                    break;
                }
            }
            if matches_all {
                filtered_indices.push(idx);
            }
        }

        // 2. Partitionnement (GROUP BY)
        // Regroupe les indices par tuple de valeurs clés
        let mut partitions: HashMap<Vec<ScalarValue>, Vec<usize>> = HashMap::new();

        if self.group_by_cols.is_empty() {
            // Aucun regroupement : partition unique globale
            partitions.insert(Vec::new(), filtered_indices);
        } else {
            // Vérification de l'existence des colonnes de regroupement
            for col_name in &self.group_by_cols {
                let _ = self.df.get_column(col_name)?;
            }

            for idx in filtered_indices {
                let mut key = Vec::with_capacity(self.group_by_cols.len());
                for col_name in &self.group_by_cols {
                    let col = self.df.get_column(col_name)?;
                    let scalar = col.get_scalar(idx).unwrap_or(ScalarValue::Null);
                    key.push(scalar);
                }
                partitions.entry(key).or_default().push(idx);
            }
        }

        // 3. Calcul des Agrégations
        let mut headers = self.group_by_cols.clone();
        for agg in &self.aggregates {
            match agg {
                AggFunc::Count => headers.push("COUNT(*)".to_string()),
                AggFunc::Sum(col) => headers.push(format!("SUM({col})")),
                AggFunc::Avg(col) => headers.push(format!("AVG({col})")),
                AggFunc::Min(col) => headers.push(format!("MIN({col})")),
                AggFunc::Max(col) => headers.push(format!("MAX({col})")),
            }
        }

        let mut rows = Vec::new();
        for (group_key, indices) in partitions {
            let mut row = group_key;

            for agg in &self.aggregates {
                let val = match agg {
                    AggFunc::Count => ScalarValue::Int(indices.len() as i64),
                    AggFunc::Sum(col_name) => self.compute_sum(col_name, &indices)?,
                    AggFunc::Avg(col_name) => self.compute_avg(col_name, &indices)?,
                    AggFunc::Min(col_name) => self.compute_min(col_name, &indices)?,
                    AggFunc::Max(col_name) => self.compute_max(col_name, &indices)?,
                };
                row.push(val);
            }
            rows.push(row);
        }

        // Tri pour un affichage reproductible et lisible
        rows.sort_by(|a, b| a.cmp(b));

        Ok(QueryResult { headers, rows })
    }

    fn compute_sum(&self, col_name: &str, indices: &[usize]) -> Result<ScalarValue, QueryError> {
        let col = self.df.get_column(col_name)?;
        match col {
            Column::Int(data) => {
                let sum: i64 = indices.iter().map(|&idx| data[idx]).sum();
                Ok(ScalarValue::Int(sum))
            }
            Column::Float(data) => {
                let sum: f64 = indices.iter().map(|&idx| data[idx]).sum();
                Ok(ScalarValue::from_f64(sum))
            }
            c => Err(QueryError::TypeMismatch {
                expected: "Int ou Float",
                found: c.type_name(),
            }),
        }
    }

    fn compute_avg(&self, col_name: &str, indices: &[usize]) -> Result<ScalarValue, QueryError> {
        if indices.is_empty() {
            return Ok(ScalarValue::Null);
        }
        let col = self.df.get_column(col_name)?;
        let count = indices.len() as f64;
        match col {
            Column::Int(data) => {
                let sum: i64 = indices.iter().map(|&idx| data[idx]).sum();
                Ok(ScalarValue::from_f64(sum as f64 / count))
            }
            Column::Float(data) => {
                let sum: f64 = indices.iter().map(|&idx| data[idx]).sum();
                Ok(ScalarValue::from_f64(sum / count))
            }
            c => Err(QueryError::TypeMismatch {
                expected: "Int ou Float",
                found: c.type_name(),
            }),
        }
    }

    fn compute_min(&self, col_name: &str, indices: &[usize]) -> Result<ScalarValue, QueryError> {
        if indices.is_empty() {
            return Ok(ScalarValue::Null);
        }
        let col = self.df.get_column(col_name)?;
        match col {
            Column::Int(data) => {
                let min_val = indices.iter().map(|&idx| data[idx]).min();
                min_val.map(ScalarValue::Int).ok_or(QueryError::EmptyDataset)
            }
            Column::Float(data) => {
                let min_val = indices
                    .iter()
                    .map(|&idx| data[idx])
                    .fold(f64::INFINITY, f64::min);
                Ok(ScalarValue::from_f64(min_val))
            }
            Column::String(data) => {
                let min_val = indices.iter().map(|&idx| &data[idx]).min();
                min_val
                    .cloned()
                    .map(ScalarValue::String)
                    .ok_or(QueryError::EmptyDataset)
            }
            c => Err(QueryError::InvalidAggregation(c.type_name())),
        }
    }

    fn compute_max(&self, col_name: &str, indices: &[usize]) -> Result<ScalarValue, QueryError> {
        if indices.is_empty() {
            return Ok(ScalarValue::Null);
        }
        let col = self.df.get_column(col_name)?;
        match col {
            Column::Int(data) => {
                let max_val = indices.iter().map(|&idx| data[idx]).max();
                max_val.map(ScalarValue::Int).ok_or(QueryError::EmptyDataset)
            }
            Column::Float(data) => {
                let max_val = indices
                    .iter()
                    .map(|&idx| data[idx])
                    .fold(f64::NEG_INFINITY, f64::max);
                Ok(ScalarValue::from_f64(max_val))
            }
            Column::String(data) => {
                let max_val = indices.iter().map(|&idx| &data[idx]).max();
                max_val
                    .cloned()
                    .map(ScalarValue::String)
                    .ok_or(QueryError::EmptyDataset)
            }
            c => Err(QueryError::InvalidAggregation(c.type_name())),
        }
    }
}

/// Résultat d'une requête analytique avec impression tabulaire soignée.
#[derive(Debug)]
pub struct QueryResult {
    pub headers: Vec<String>,
    pub rows: Vec<Vec<ScalarValue>>,
}

impl QueryResult {
    pub fn display_table(&self) {
        if self.headers.is_empty() {
            println!("(Table vide)");
            return;
        }

        // Calcul des largeurs de colonnes pour l'alignement
        let mut col_widths: Vec<usize> = self.headers.iter().map(|h| h.len()).collect();
        for row in &self.rows {
            for (i, cell) in row.iter().enumerate() {
                let s = format!("{cell}");
                if s.len() > col_widths[i] {
                    col_widths[i] = s.len();
                }
            }
        }

        // En-têtes
        let header_str = self
            .headers
            .iter()
            .enumerate()
            .map(|(i, h)| format!("{:width$}", h, width = col_widths[i]))
            .collect::<Vec<_>>()
            .join(" | ");

        let separator = col_widths
            .iter()
            .map(|w| "-".repeat(*w))
            .collect::<Vec<_>>()
            .join("-+-");

        println!("\n+-{separator}-+");
        println!("| {header_str} |");
        println!("+-{separator}-+");

        for row in &self.rows {
            let row_str = row
                .iter()
                .enumerate()
                .map(|(i, cell)| format!("{:width$}", cell, width = col_widths[i]))
                .collect::<Vec<_>>()
                .join(" | ");
            println!("| {row_str} |");
        }
        println!("+-{separator}-+\n");
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("=== Démarrage du Moteur Analytique In-Memory ===");

    // Jeu de données d'exemple : transactions de vente
    let table = DataFrame::new()
        .with_column(
            "departement",
            Column::String(vec![
                "Informatique".to_string(),
                "Informatique".to_string(),
                "RH".to_string(),
                "Ventes".to_string(),
                "Informatique".to_string(),
                "Ventes".to_string(),
                "RH".to_string(),
            ]),
        )?
        .with_column(
            "region",
            Column::String(vec![
                "Paris".to_string(),
                "Lyon".to_string(),
                "Paris".to_string(),
                "Paris".to_string(),
                "Paris".to_string(),
                "Lyon".to_string(),
                "Lyon".to_string(),
            ]),
        )?
        .with_column(
            "salaire",
            Column::Int(vec![45000, 52000, 38000, 42000, 61000, 48000, 39000]),
        )?
        .with_column(
            "prime",
            Column::Float(vec![2500.50, 3100.0, 1200.75, 4500.0, 5000.25, 4100.0, 1500.0]),
        )?
        .with_column(
            "actif",
            Column::Bool(vec![true, true, true, false, true, true, true]),
        )?;

    println!("Dataset initialisé avec succès ({} lignes).", table.row_count());

    // Requête 1: COUNT, SUM(salaire), AVG(salaire), AVG(prime) GROUP BY departement
    println!("\n>>> REQUÊTE 1: Agrégats par département");
    let res1 = table
        .query()
        .group_by(&["departement"])
        .count()
        .sum("salaire")
        .avg("salaire")
        .avg("prime")
        .execute()?;
    res1.display_table();

    // Requête 2: GROUP BY multiple (departement, region) avec MIN et MAX
    println!(">>> REQUÊTE 2: GROUP BY multiple (departement, region) avec MIN & MAX");
    let res2 = table
        .query()
        .group_by(&["departement", "region"])
        .count()
        .min("salaire")
        .max("salaire")
        .sum("prime")
        .execute()?;
    res2.display_table();

    // Requête 3: Agrégations globales avec filtre (salaire > 40000)
    println!(">>> REQUÊTE 3: Agrégations avec filtre WHERE salaire > 40000");
    let res3 = table
        .query()
        .filter(Predicate::GtInt("salaire".to_string(), 40000))
        .count()
        .sum("salaire")
        .avg("salaire")
        .execute()?;
    res3.display_table();

    // Requête 4: Filtre par chaîne de caractères + GROUP BY
    println!(">>> REQUÊTE 4: WHERE region == 'Paris' GROUP BY departement");
    let res4 = table
        .query()
        .filter(Predicate::EqString("region".to_string(), "Paris".to_string()))
        .group_by(&["departement"])
        .count()
        .sum("salaire")
        .avg("salaire")
        .execute()?;
    res4.display_table();

    println!("Toutes les requêtes analytiques se sont exécutées avec succès !");
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn create_test_df() -> DataFrame {
        DataFrame::new()
            .with_column(
                "cat",
                Column::String(vec!["A".into(), "B".into(), "A".into(), "B".into()]),
            )
            .unwrap()
            .with_column("val", Column::Int(vec![10, 20, 30, 40]))
            .unwrap()
            .with_column("score", Column::Float(vec![1.5, 2.5, 3.5, 4.5]))
            .unwrap()
    }

    #[test]
    fn test_global_aggregations() {
        let df = create_test_df();
        let res = df.query().count().sum("val").avg("val").execute().unwrap();
        assert_eq!(res.rows.len(), 1);
        assert_eq!(res.rows[0][0], ScalarValue::Int(4)); // COUNT
        assert_eq!(res.rows[0][1], ScalarValue::Int(100)); // SUM
        assert_eq!(res.rows[0][2], ScalarValue::from_f64(25.0)); // AVG
    }

    #[test]
    fn test_group_by() {
        let df = create_test_df();
        let res = df
            .query()
            .group_by(&["cat"])
            .count()
            .sum("val")
            .execute()
            .unwrap();

        assert_eq!(res.rows.len(), 2);
        // "A": val 10 + 30 = 40, count = 2
        assert_eq!(res.rows[0][0], ScalarValue::String("A".into()));
        assert_eq!(res.rows[0][1], ScalarValue::Int(2));
        assert_eq!(res.rows[0][2], ScalarValue::Int(40));

        // "B": val 20 + 40 = 60, count = 2
        assert_eq!(res.rows[1][0], ScalarValue::String("B".into()));
        assert_eq!(res.rows[1][1], ScalarValue::Int(2));
        assert_eq!(res.rows[1][2], ScalarValue::Int(60));
    }

    #[test]
    fn test_filter() {
        let df = create_test_df();
        let res = df
            .query()
            .filter(Predicate::GtInt("val".into(), 15))
            .count()
            .sum("val")
            .execute()
            .unwrap();

        // Lignes conservées: 20, 30, 40 => count = 3, sum = 90
        assert_eq!(res.rows.len(), 1);
        assert_eq!(res.rows[0][0], ScalarValue::Int(3));
        assert_eq!(res.rows[0][1], ScalarValue::Int(90));
    }

    #[test]
    fn test_column_not_found() {
        let df = create_test_df();
        let res = df.query().sum("unknown_column").execute();
        assert!(matches!(res, Err(QueryError::ColumnNotFound(_))));
    }

    #[test]
    fn test_inconsistent_column_length() {
        let df = DataFrame::new()
            .with_column("col1", Column::Int(vec![1, 2]))
            .unwrap();
        let err = df.with_column("col2", Column::Int(vec![1, 2, 3]));
        assert!(matches!(err, Err(QueryError::MismatchedColumnLength { .. })));
    }
