/// Service de sérialisation Bincode et compression LZ4
pub struct ContactStorage;

impl ContactStorage {
    /// Sérialise en Bincode puis compresse avec LZ4
    pub fn serialize_and_compress(contacts: &[Contact]) -> Result<Vec<u8>, ContactError> {
        let serialized_bytes = bincode::serialize(contacts)?;

        let mut encoder = lz4_flex::frame::FrameEncoder::new(Vec::new());
        encoder.write_all(&serialized_bytes)?;
        let compressed_bytes = encoder.finish()?;

        Ok(compressed_bytes)
    }

    /// Décompresse le flux LZ4 puis désérialise avec Bincode
    pub fn decompress_and_deserialize(compressed_data: &[u8]) -> Result<Vec<Contact>, ContactError> {
        let mut decoder = lz4_flex::frame::FrameDecoder::new(compressed_data);
        let mut decompressed_bytes = Vec::new();
        decoder.read_to_end(&mut decompressed_bytes)?;

        let contacts: Vec<Contact> = bincode::deserialize(&decompressed_bytes)?;
        Ok(contacts)
    }

    /// Sauvegarde les contacts dans un fichier compressé
    pub fn save_to_file<P: AsRef<Path>>(path: P, contacts: &[Contact]) -> Result<(), ContactError> {
        let data = Self::serialize_and_compress(contacts)?;
        let mut file = File::create(path)?;
        file.write_all(&data)?;
        file.flush()?;
        Ok(())
    }

    /// Charge et décompresse les contacts depuis un fichier
    pub fn load_from_file<P: AsRef<Path>>(path: P) -> Result<Vec<Contact>, ContactError> {
        let mut file = File::open(path)?;
        let mut buffer = Vec::new();
        file.read_to_end(&mut buffer)?;
        Self::decompress_and_deserialize(&buffer)
    }
}

