    println!("=== Démarrage du système d'importation et déduplication ===");

    let mut registry = ContactRegistry::new();
    let now = Utc::now();

    // 1. Jeu de contacts entrants avec doublons intentionnels
    let c1 = Contact::new(
        "Jean",
        "Dupont",
        Some("jean.dupont@example.com".to_string()),
        Some("+33 6 12 34 56 78".to_string()),
        Some("Acme Corp".to_string()),
        now - chrono::Duration::hours(2),
    )?;

    // Doublon sur l'email avec casse différente et mise à jour plus récente
    let c2 = Contact::new(
        "Jean",
        "Dupont",
        Some("JEAN.DUPONT@example.com ".to_string()),
        None, // Téléphone absent, doit conserver celui de c1
        Some("Acme Global".to_string()), // Entreprise actualisée
        now - chrono::Duration::hours(1),
    )?;

    // Doublon sur le téléphone (format différent)
    let c3 = Contact::new(
        "J.",
        "Dupont",
        None,
        Some("+33612345678".to_string()),
        None,
        now,
    )?;

    // Contact distinct
    let c4 = Contact::new(
        "Marie",
        "Curie",
        Some("marie.curie@radium.org".to_string()),
        Some("+33 7 98 76 54 32".to_string()),
        Some("Institut Curie".to_string()),
        now,
    )?;

    let dataset = vec![c1, c2, c3, c4];
    println!("Nombre de fiches à importer : {}", dataset.len());

    // 2. Déduplication
    registry.import_batch(dataset);
    println!("Nombre de fiches uniques après déduplication : {}", registry.len());

    let unique_contacts: Vec<Contact> = registry.values().cloned().collect();

    // 3. Sérialisation Bincode + Compression LZ4
    let compressed_payload = ContactStorage::serialize_and_compress(&unique_contacts)?;
    let raw_bincode = bincode::serialize(&unique_contacts)?;

    println!(
        "Taille Bincode brut : {} octets | Taille LZ4 compressé : {} octets (Ratio : {:.2}%)",
        raw_bincode.len(),
        compressed_payload.len(),
