```rust
// src/main.rs
use std::collections::BTreeMap;
use std::fs::{File, OpenOptions};
use std::io::{self, BufReader, BufWriter, Read, Seek, SeekFrom, Write};
use std::path::{Path, PathBuf};

use byteorder::{LittleEndian, ReadBytesExt, WriteBytesExt};
use clap::{Args, Parser, Subcommand};
use colored::*;
use serde::{Deserialize, Serialize};
use thiserror::Error;

const MAGIC_BYTES: &[u8; 4] = b"CBAR"; // Custom Binary ARchive
const CURRENT_VERSION: u16 = 1;
const HEADER_SIZE: u64 = 32;

#[derive(Error, Debug)]
pub enum ArchiveError {
    #[error("Erreur I/O: {0}")]
    Io(#[from] io::Error),

    #[error("Nombre magique invalide: attendu 'CBAR', trouvé {0:02X?}")]
    InvalidMagic([u8; 4]),

    #[error("Version non supportée: {0} (version supportée: {1})")]
    UnsupportedVersion(u16, u16),

    #[error("Entrée UTF-8 corrompue: {0}")]
    InvalidUtf8(#[from] std::string::FromUtf8Error),

    #[error("Clé de métadonnée non trouvée: '{0}'")]
    MetaKeyNotFound(String),

    #[error("Segment introuvable: '{0}'")]
    SegmentNotFound(String),

    #[error("Format d'archive corrompu: {0}")]
    CorruptedArchive(String),
}

type Result<T> = std::result::Result<T, ArchiveError>;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ArchiveHeader {
    pub magic: [u8; 4],
    pub version: u16,
    pub entry_count: u16,
    pub metadata_size: u32,
    pub segment_count: u32,
    pub segment_table_offset: u64,
    pub payload_offset: u64,
}

impl ArchiveHeader {
    pub fn read_from<R: Read>(reader: &mut R) -> Result<Self> {
        let mut magic = [0u8; 4];
        reader.read_exact(&mut magic)?;
        if &magic != MAGIC_BYTES {
            return Err(ArchiveError::InvalidMagic(magic));
        }

        let version = reader.read_u16::<LittleEndian>()?;
        if version != CURRENT_VERSION {
            return Err(ArchiveError::UnsupportedVersion(version, CURRENT_VERSION));
        }

        let entry_count = reader.read_u16::<LittleEndian>()?;
        let metadata_size = reader.read_u32::<LittleEndian>()?;
        let segment_count = reader.read_u32::<LittleEndian>()?;
        let segment_table_offset = reader.read_u64::<LittleEndian>()?;
        let payload_offset = reader.read_u64::<LittleEndian>()?;

        Ok(Self {
            magic,
            version,
            entry_count,
            metadata_size,
            segment_count,
            segment_table_offset,
            payload_offset,
        })
    }

    pub fn write_to<W: Write>(&self, writer: &mut W) -> Result<()> {
        writer.write_all(&self.magic)?;
        writer.write_u16::<LittleEndian>(self.version)?;
        writer.write_u16::<LittleEndian>(self.entry_count)?;
        writer.write_u32::<LittleEndian>(self.metadata_size)?;
        writer.write_u32::<LittleEndian>(self.segment_count)?;
        writer.write_u64::<LittleEndian>(self.segment_table_offset)?;
        writer.write_u64::<LittleEndian>(self.payload_offset)?;
        Ok(())
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SegmentEntry {
    pub name: String,
    pub offset: u64,
    pub size: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Archive {
    pub header: ArchiveHeader,
    pub metadata: BTreeMap<String, String>,
    pub segments: Vec<SegmentEntry>,
}

impl Archive {
    pub fn open<P: AsRef<Path>>(path: P) -> Result<(Self, File)> {
        let file = OpenOptions::new().read(true).write(true).open(path)?;
        let mut reader = BufReader::new(&file);

        let header = ArchiveHeader::read_from(&mut reader)?;

        // Lecture des métadonnées
        let mut metadata = BTreeMap::new();
        for _ in 0..header.entry_count {
            let k_len = reader.read_u16::<LittleEndian>()? as usize;
            let mut k_buf = vec![0u8; k_len];
            reader.read_exact(&mut k_buf)?;
            let key = String::from_utf8(k_buf)?;

            let v_len = reader.read_u32::<LittleEndian>()? as usize;
            let mut v_buf = vec![0u8; v_len];
            reader.read_exact(&mut v_buf)?;
            let val = String::from_utf8(v_buf)?;

            metadata.insert(key, val);
        }

        // Lecture de la table des segments
        reader.seek(SeekFrom::Start(header.segment_table_offset))?;
        let mut segments = Vec::with_capacity(header.segment_count as usize);
        for _ in 0..header.segment_count {
            let name_len = reader.read_u16::<LittleEndian>()? as usize;
            let mut name_buf = vec![0u8; name_len];
            reader.read_exact(&mut name_buf)?;
            let name = String::from_utf8(name_buf)?;

            let offset = reader.read_u64::<LittleEndian>()?;
            let size = reader.read_u64::<LittleEndian>()?;
            segments.push(SegmentEntry { name, offset, size });
        }

        Ok((Archive { header, metadata, segments }, file))
    }

    pub fn create_from_files<P: AsRef<Path>>(
        output_path: P,
        metadata: BTreeMap<String, String>,
        files: &[(String, PathBuf)],
    ) -> Result<()> {
        let file = File::create(output_path)?;
        let mut writer = BufWriter::new(file);

        // Réserve la place pour l'en-tête (32 octets)
        writer.write_all(&[0u8; HEADER_SIZE as usize])?;

        // Écriture du dictionnaire de métadonnées
        let meta_start = writer.stream_position()?;
        for (k, v) in &metadata {
            let k_bytes = k.as_bytes();
            let v_bytes = v.as_bytes();
            writer.write_u16::<LittleEndian>(k_bytes.len() as u16)?;
            writer.write_all(k_bytes)?;
            writer.write_u32::<LittleEndian>(v_bytes.len() as u32)?;
            writer.write_all(v_bytes)?;
        }
        let meta_end = writer.stream_position()?;
        let metadata_size = (meta_end - meta_start) as u32;

        // Préparation et écriture de la table des segments (avec offsets absolus calculés)
        let segment_table_offset = meta_end;
        let mut table_size: u64 = 0;
        for (name, _) in files {
            table_size += 2 + name.as_bytes().len() as u64 + 8 + 8;
        }

        let payload_offset = segment_table_offset + table_size;
        let mut current_payload_offset = payload_offset;

        let mut segment_entries = Vec::new();
        for (name, path) in files {
            let metadata_file = std::fs::metadata(path)?;
            let size = metadata_file.len();
            segment_entries.push(SegmentEntry {
                name: name.clone(),
                offset: current_payload_offset,
                size,
            });
            current_payload_offset += size;
        }

        // Écriture de la table des segments
        for seg in &segment_entries {
            let name_bytes = seg.name.as_bytes();
            writer.write_u16::<LittleEndian>(name_bytes.len() as u16)?;
            writer.write_all(name_bytes)?;
            writer.write_u64::<LittleEndian>(seg.offset)?;
            writer.write_u64::<LittleEndian>(seg.size)?;
        }

        // Écriture des données brutes
        for (_, path) in files {
            let mut f = File::open(path)?;
            io::copy(&mut f, &mut writer)?;
        }

        writer.flush()?;

        // Mise à jour de l'en-tête final
        let header = ArchiveHeader {
            magic: *MAGIC_BYTES,
            version: CURRENT_VERSION,
            entry_count: metadata.len() as u16,
            metadata_size,
            segment_count: segment_entries.len() as u32,
            segment_table_offset,
            payload_offset,
        };

        let mut file = writer.into_inner().map_err(|e| e.into_error())?;
        file.seek(SeekFrom::Start(0))?;
        header.write_to(&mut file)?;
        file.flush()?;

        Ok(())
    }

    pub fn save_metadata_in_place<P: AsRef<Path>>(&mut self, path: P) -> Result<()> {
        // Pour modifier en toute sécurité les métadonnées (qui peuvent changer de taille),
        // on reconstruit l'archive dans un fichier temporaire puis on atomise le renommage.
        let (old_archive, mut old_file) = Archive::open(&path)?;

        let temp_path = path.as_ref().with_extension("cba.tmp");
        {
            let temp_file = File::create(&temp_path)?;
            let mut writer = BufWriter::new(temp_file);

            // Placeholder d'en-tête
            writer.write_all(&[0u8; HEADER_SIZE as usize])?;

            // Écriture du nouveau dictionnaire
            let meta_start = writer.stream_position()?;
            for (k, v) in &self.metadata {
                let k_bytes = k.as_bytes();
                let v_bytes = v.as_bytes();
                writer.write_u16::<LittleEndian>(k_bytes.len() as u16)?;
                writer.write_all(k_bytes)?;
                writer.write_u32::<LittleEndian>(v_bytes.len() as u32)?;
                writer.write_all(v_bytes)?;
            }
            let meta_end = writer.stream_position()?;
            let new_meta_size = (meta_end - meta_start) as u32;

            let new_segment_table_offset = meta_end;
            let mut table_size: u64 = 0;
            for seg in &old_archive.segments {
                table_size += 2 + seg.name.as_bytes().len() as u64 + 8 + 8;
            }
            let new_payload_offset = new_segment_table_offset + table_size;

            // Recalcul des offsets de segments
            let mut updated_segments = Vec::new();
            let mut curr_payload = new_payload_offset;
            for seg in &old_archive.segments {
                updated_segments.push(SegmentEntry {
                    name: seg.name.clone(),
                    offset: curr_payload,
                    size: seg.size,
                });
                curr_payload += seg.size;
            }

            // Écriture de la table des segments
            for seg in &updated_segments {
                let name_bytes = seg.name.as_bytes();
                writer.write_u16::<LittleEndian>(name_bytes.len() as u16)?;
                writer.write_all(name_bytes)?;
                writer.write_u64::<LittleEndian>(seg.offset)?;
                writer.write_u64::<LittleEndian>(seg.size)?;
            }

            // Copie des charges utiles depuis l'ancien fichier
            for seg in &old_archive.segments {
                old_file.seek(SeekFrom::Start(seg.offset))?;
                let mut take_reader = (&mut old_file).take(seg.size);
                io::copy(&mut take_reader, &mut writer)?;
            }

            writer.flush()?;

            // Écriture de l'en-tête
            let header = ArchiveHeader {
                magic: *MAGIC_BYTES,
                version: CURRENT_VERSION,
                entry_count: self.metadata.len() as u16,
                metadata_size: new_meta_size,
                segment_count: updated_segments.len() as u32,
                segment_table_offset: new_segment_table_offset,
                payload_offset: new_payload_offset,
            };

            let mut final_file = writer.into_inner().map_err(|e| e.into_error())?;
            final_file.seek(SeekFrom::Start(0))?;
            header.write_to(&mut final_file)?;
            final_file.flush()?;

            self.header = header;
            self.segments = updated_segments;
        }

        std::fs::rename(temp_path, path)?;
        Ok(())
    }
}

// ---------------------------------------------------------------------------
// Outil Hexdump
// ---------------------------------------------------------------------------

#[derive(Args, Debug)]
pub struct HexDumpArgs {
    /// Fichier archive ou binaire cible
    #[arg(value_name = "FICHIER")]
    pub file: PathBuf,

    /// Offset de départ en octets (supporte décimal ou hexadécimal ex: 0x20)
    #[arg(short, long, default_value = "0", value_parser = parse_offset)]
    pub offset: u64,

    /// Nombre d'octets à afficher (optionnel, tout le fichier par défaut)
    #[arg(short, long)]
    pub length: Option<u64>,

    /// Nombre de colonnes (octets par ligne)
    #[arg(short, long, default_value_t = 16)]
    pub columns: usize,

    /// Mettre en évidence les sections de l'archive (si format .cba valide)
    #[arg(short, long)]
    pub annotate: bool,
}

fn parse_offset(src: &str) -> std::result::Result<u64, String> {
    if let Some(stripped) = src.strip_prefix("0x").or_else(|| src.strip_prefix("0X")) {
        u64::from_str_radix(stripped, 16).map_err(|e| e.to_string())
    } else {
        src.parse::<u64>().map_err(|e| e.to_string())
    }
}

pub fn run_hexdump(args: &HexDumpArgs) -> Result<()> {
    let mut file = File::open(&args.file)?;
    let total_size = file.metadata()?.len();

    let start_offset = args.offset;
    if start_offset >= total_size {
        println!("{}", "Offset au-delà de la fin du fichier.".yellow());
        return Ok(());
    }

    file.seek(SeekFrom::Start(start_offset))?;

    let max_read = match args.length {
        Some(len) => len.min(total_size - start_offset),
        None => total_size - start_offset,
    };

    let mut reader = (&mut file).take(max_read);
    let mut current_offset = start_offset;
    let mut buffer = vec![0u8; args.columns];

    println!(
        "{:<8}  {}",
        "OFFSET".cyan(),
        format!("{:<width$}", "HEXADECIMAL", width = args.columns * 3)
            .cyan()
            .bold()
    );
    println!("{}", "-".repeat(args.columns * 4 + 12).bright_black());

    loop {
        let bytes_read = reader.read(&mut buffer)?;
        if bytes_read == 0 {
            break;
        }

        let slice = &buffer[..bytes_read];

        // Format offset
        print!("{}: ", format!("{:08x}", current_offset).cyan());

        // Hex bytes
        for i in 0..args.columns {
            if i < bytes_read {
                let b = slice[i];
                let hex_str = format!("{:02x}", b);
                if b == 0 {
                    print!("{} ", hex_str.bright_black());
                } else if b.is_ascii_graphic() {
                    print!("{} ", hex_str.green());
                } else {
                    print!("{} ", hex_str.blue());
                }
            } else {
                print!("   ");
            }
            if i + 1 == args.columns / 2 {
                print!(" ");
            }
        }

        // ASCII representation
        print!(" |");
        for &b in slice {
            if b.is_ascii_graphic() || b == b' ' {
                print!("{}", (b as char).to_string().yellow());
            } else {
                print!("{}", ".".bright_black());
            }
        }
        println!("|");

        current_offset += bytes_read as u64;
    }

    Ok(())
}

// ---------------------------------------------------------------------------
// CLI Definition & Subcommands
// ---------------------------------------------------------------------------

#[derive(Parser, Debug)]
#[command(name = "binmeta")]
#[command(about = "CLI d'inspection hexadécimale et dictionnaire de métadonnées pour archives binaires", long_about = None)]
#[command(version)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Crée une nouvelle archive binaire personnalisée (.cba)
    Create {
        /// Fichier archive de destination
        #[arg(short, long)]
        output: PathBuf,

        /// Métadonnées initiales sous format cle=valeur (peut être répété)
        #[arg(short, long = "meta", value_parser = parse_key_val)]
        meta: Vec<(String, String)>,

        /// Fichiers à inclure dans l'archive sous forme nom=chemin (ex: payload.bin=/tmp/data.bin)
        #[arg(value_name = "NOM=CHEMIN", value_parser = parse_key_val)]
        files: Vec<(String, String)>,
    },

    /// Inspecte l'en-tête et les segments d'une archive
    Inspect {
        /// Fichier archive à analyser
        archive: PathBuf,

        /// Sortie au format JSON structuré
        #[arg(short, long)]
        json: bool,
    },

    /// Manipule le dictionnaire de métadonnées
    Meta {
        /// Fichier archive cible
        #[arg(short, long)]
        archive: PathBuf,

        #[command(subcommand)]
        action: MetaAction,
    },

    /// Extrait un ou tous les segments de données
    Extract {
        /// Fichier archive source
        archive: PathBuf,

        /// Nom du segment spécifique à extraire (si omis, extrait tout)
        #[arg(short, long)]
        segment: Option<String>,

        /// Répertoire de destination
        #[arg(short, long, default_value = ".")]
        outdir: PathBuf,
    },

    /// Visionneuse de dump hexadécimal interactif
    Hexdump(HexDumpArgs),
}

#[derive(Subcommand, Debug)]
enum MetaAction {
    /// Liste l'intégralité des métadonnées
    List {
        /// Afficher au format JSON
        #[arg(short, long)]
        json: bool,
    },
    /// Récupère la valeur d'une clé
    Get {
        /// Nom de la clé
        key: String,
    },
    /// Ajoute ou modifie une paire clé/valeur
    Set {
        /// Nom de la clé
        key: String,
        /// Valeur associée
        value: String,
    },
    /// Supprime une métadonnée
    Remove {
        /// Nom de la clé
        key: String,
    },
}

fn parse_key_val(s: &str) -> std::result::Result<(String, String), String> {
    s.split_once('=')
        .map(|(k, v)| (k.trim().to_string(), v.trim().to_string()))
        .ok_or_else(|| format!("Format invalide pour '{}'. Attendu: CLE=VALEUR", s))
}

// ---------------------------------------------------------------------------
// Main & Command Handlers
// ---------------------------------------------------------------------------

fn main() -> anyhow::Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Create { output, meta, files } => {
            let mut metadata_map = BTreeMap::new();
            for (k, v) in meta {
                metadata_map.insert(k, v);
            }

            let mut files_to_add = Vec::new();
            for (name, path_str) in files {
                let p = PathBuf::from(path_str);
                if !p.exists() {
                    eprintln!("{} Le fichier source '{}' n'existe pas.", "Erreur:".red().bold(), p.display());
                    std::process::exit(1);
                }
                files_to_add.push((name, p));
            }

            Archive::create_from_files(&output, metadata_map, &files_to_add)?;
            println!("{} Archive créée avec succès : {}", "✔".green().bold(), output.display());
        }

        Commands::Inspect { archive, json } => {
            let (arch, _) = Archive::open(&archive)?;

            if json {
                let out = serde_json::to_string_pretty(&arch)?;
                println!("{}", out);
            } else {
                println!("{}", "=== EN-TÊTE D'ARCHIVE BINAIRE ===".bold().cyan());
                println!("  Signature Magique      : {}", String::from_utf8_lossy(&arch.header.magic).green());
                println!("  Version                : {}", arch.header.version);
                println!("  Nombre de métadonnées  : {}", arch.header.entry_count);
                println!("  Taille métadonnées     : {} octets", arch.header.metadata_size);
                println!("  Nombre de segments     : {}", arch.header.segment_count);
                println!("  Offset table segments  : 0x{:08X}", arch.header.segment_table_offset);
                println!("  Offset charges utiles  : 0x{:08X}", arch.header.payload_offset);

                println!("\n{}", "=== SEGMENTS DE DONNÉES ===".bold().cyan());
                if arch.segments.is_empty() {
                    println!("  (aucun segment)");
                } else {
                    for (idx, seg) in arch.segments.iter().enumerate() {
                        println!(
                            "  [{}] {:<20} Offset: 0x{:08X} | Taille: {} octets",
                            idx,
                            seg.name.yellow().bold(),
                            seg.offset,
                            seg.size
                        );
                    }
                }

                println!("\n{}", "=== DICTIONNAIRE DE MÉTADONNÉES ===".bold().cyan());
                if arch.metadata.is_empty() {
                    println!("  (aucun élément)");
                } else {
                    for (k, v) in &arch.metadata {
                        println!("  {}: {}", k.magenta().bold(), v);
                    }
                }
            }
        }

        Commands::Meta { archive, action } => {
            let (mut arch, _) = Archive::open(&archive)?;

            match action {
                MetaAction::List { json } => {
                    if json {
                        println!("{}", serde_json::to_string_pretty(&arch.metadata)?);
                    } else {
                        println!("{} ({})", "Dictionnaire de Métadonnées".bold().cyan(), archive.display());
                        for (k, v) in &arch.metadata {
                            println!("  {} = {}", k.magenta().bold(), v);
                        }
                    }
                }
                MetaAction::Get { key } => {
                    match arch.metadata.get(&key) {
                        Some(val) => println!("{}", val),
                        None => {
                            eprintln!("{} Clé '{}' non trouvée.", "Erreur:".red().bold(), key);
                            std::process::exit(1);
                        }
                    }
                }
                MetaAction::Set { key, value } => {
                    arch.metadata.insert(key.clone(), value.clone());
                    arch.save_metadata_in_place(&archive)?;
                    println!("{} Métadonnée '{}' mise à jour.", "✔".green().bold(), key);
                }
                MetaAction::Remove { key } => {
                    if arch.metadata.remove(&key).is_some() {
                        arch.save_metadata_in_place(&archive)?;
                        println!("{} Métadonnée '{}' supprimée.", "✔".green().bold(), key);
                    } else {
                        eprintln!("{} Clé '{}' non trouvée.", "Erreur:".red().bold(), key);
                        std::process::exit(1);
                    }
                }
            }
        }

        Commands::Extract { archive, segment, outdir } => {
            let (arch, mut file) = Archive::open(&archive)?;
            std::fs::create_dir_all(&outdir)?;

            let targets: Vec<&SegmentEntry> = match &segment {
                Some(name) => {
                    let s = arch.segments.iter().find(|s| &s.name == name)
                        .ok_or_else(|| ArchiveError::SegmentNotFound(name.clone()))?;
                    vec![s]
                }
                None => arch.segments.iter().collect(),
            };

            for seg in targets {
                let target_file_path = outdir.join(&seg.name);
                file.seek(SeekFrom::Start(seg.offset))?;
                let mut reader = (&mut file).take(seg.size);
                let mut out = File::create(&target_file_path)?;
                io::copy(&mut reader, &mut out)?;
                println!(
                    "{} Segment '{}' ({} octets) extrait vers {}",
                    "✔".green().bold(),
                    seg.name,
                    seg.size,
                    target_file_path.display()
                );
            }
        }

        Commands::Hexdump(args) => {
            run_hexdump(&args)?;
        }
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::NamedTempFile;

    #[test]
    fn test_create_and_read_archive() {
        let temp_archive = NamedTempFile::new().unwrap();
        let archive_path = temp_archive.path().to_path_buf();

        let mut sample_file = NamedTempFile::new().unwrap();
        sample_file.write_all(b"Hello Custom Binary Archive!").unwrap();

        let mut meta = BTreeMap::new();
        meta.insert("author".to_string(), "Damien".to_string());
        meta.insert("app".to_string(), "binmeta".to_string());

        let files = vec![("greeting.txt".to_string(), sample_file.path().to_path_buf())];

        Archive::create_from_files(&archive_path, meta, &files).unwrap();

        let (arch, _) = Archive::open(&archive_path).unwrap();
        assert_eq!(&arch.header.magic, MAGIC_BYTES);
        assert_eq!(arch.metadata.get("author").map(|s| s.as_str()), Some("Damien"));
        assert_eq!(arch.segments.len(), 1);
        assert_eq!(arch.segments[0].name, "greeting.txt");
        assert_eq!(arch.segments[0].size, 28);
    }
}

