// src/main.rs
use std::collections::BTreeMap;
use std::fs::File;
use std::io::BufReader;
use std::path::{Path, PathBuf};

use clap::Parser;
use id3::TagLike;
use serde::{Deserialize, Serialize};

/// Type de média extrait
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum MediaType {
    AudioId3,
    ImageExif,
}

/// Métadonnées normalisées extraites d'un fichier audio (ID3)
#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq, Eq)]
pub struct AudioMetadata {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub artist: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub album: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub year: Option<i32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub track: Option<u32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub genre: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub duration_seconds: Option<u32>,
    #[serde(skip_serializing_if = "BTreeMap::is_empty")]
    pub extra_tags: BTreeMap<String, String>,
}

/// Métadonnées normalisées extraites d'une image (EXIF)
#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq, Eq)]
pub struct ImageMetadata {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub camera_make: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub camera_model: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub date_time: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub exposure_time: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub f_number: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub iso: Option<u32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub focal_length: Option<String>,
    #[serde(skip_serializing_if = "BTreeMap::is_empty")]
    pub extra_exif: BTreeMap<String, String>,
}

/// Données spécifiques selon le type
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(untagged)]
pub enum SpecificMetadata {
    Audio(AudioMetadata),
    Image(ImageMetadata),
}

/// Enregistrement complet représentant un fichier analysé
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct FileMetadataReport {
    pub file_path: String,
    pub file_name: String,
    pub file_size_bytes: u64,
    pub media_type: MediaType,
    pub metadata: SpecificMetadata,
}

/// Erreurs possibles du domaine d'extraction
#[derive(thiserror::Error, Debug)]
pub enum ExtractionError {
    #[error("Erreur I/O pour le fichier '{0}': {1}")]
    Io(PathBuf, #[source] std::io::Error),

    #[error("Erreur de parsing ID3 pour '{0}': {1}")]
    Id3(PathBuf, #[source] id3::Error),

    #[error("Erreur de parsing EXIF pour '{0}': {1}")]
    Exif(PathBuf, String),

