/// Extrait les métadonnées d'un fichier audio MP3 / ID3
pub fn extract_id3_metadata(path: &Path) -> Result<FileMetadataReport, ExtractionError> {
    let file_metadata = std::fs::metadata(path)
        .map_err(|err| ExtractionError::Io(path.to_path_buf(), err))?;

    let tag = id3::Tag::read_from_path(path)
        .map_err(|err| ExtractionError::Id3(path.to_path_buf(), err))?;

    let mut extra_tags = BTreeMap::new();
    for frame in tag.frames() {
        let id = frame.id();
        // Ignore les tags déjà extraits dans les champs dédiés
        if !["TIT2", "TPE1", "TALB", "TYER", "TDRC", "TRCK", "TCON", "TLEN"].contains(&id) {
            let content_display = frame.content().to_string();
            if !content_display.is_empty() {
                extra_tags.insert(id.to_string(), content_display);
            }
        }
    }

    let audio_info = AudioMetadata {
        title: tag.title().map(String::from),
        artist: tag.artist().map(String::from),
        album: tag.album().map(String::from),
        year: tag.year().or_else(|| tag.date_recorded().map(|d| d.year)),
        track: tag.track(),
        genre: tag.genre().map(String::from),
        duration_seconds: tag.duration().map(|ms| ms / 1000),
        extra_tags,
    };

    Ok(FileMetadataReport {
        file_path: path.to_string_lossy().into_owned(),
        file_name: path
            .file_name()
            .map(|n| n.to_string_lossy().into_owned())
            .unwrap_or_else(|| "inconnu".to_string()),
