}

/// Extrait les métadonnées EXIF d'une image (JPEG, TIFF, WebP, etc.)
pub fn extract_exif_metadata(path: &Path) -> Result<FileMetadataReport, ExtractionError> {
    let file = File::open(path).map_err(|err| ExtractionError::Io(path.to_path_buf(), err))?;
    let file_metadata = file
        .metadata()
        .map_err(|err| ExtractionError::Io(path.to_path_buf(), err))?;

    let mut buf_reader = BufReader::new(file);
    let exif_reader = exif::Reader::new();
    let exif = exif_reader
        .read_from_container(&mut buf_reader)
        .map_err(|err| ExtractionError::Exif(path.to_path_buf(), err.to_string()))?;

    let mut camera_make = None;
    let mut camera_model = None;
    let mut date_time = None;
    let mut exposure_time = None;
    let mut f_number = None;
    let mut iso = None;
    let mut focal_length = None;
    let mut extra_exif = BTreeMap::new();

    for field in exif.fields() {
        let tag_name = field.tag.to_string();
        let display_val = field.display_value().to_string();

        match field.tag {
            exif::Tag::Make => camera_make = Some(display_val),
