/// Analyse un fichier selon son extension
pub fn extract_file_metadata(path: &Path) -> Result<FileMetadataReport, ExtractionError> {
    let extension = path
        .extension()
        .and_then(|ext| ext.to_str())
        .map(|ext| ext.to_ascii_lowercase())
        .ok_or_else(|| ExtractionError::MissingExtension(path.to_path_buf()))?;

    match extension.as_str() {
        "mp3" | "aiff" | "wav" => extract_id3_metadata(path),
        "jpg" | "jpeg" | "tiff" | "tif" | "png" | "webp" => extract_exif_metadata(path),
        other => Err(ExtractionError::UnsupportedFormat(other.to_string())),
    }
}

