            Err(ExtractionError::MissingExtension(_)) => {}
            Err(err) => {
                errors.push(format!("{}: {}", file_path.display(), err));
            }
        }
    }

    (reports, errors)
}

fn main() -> anyhow::Result<()> {
    let args = Cli::parse();

    let input_path = &args.input;
    if !input_path.exists() {
