    } else {
        serde_json::to_string(&reports)?
    };

    if let Some(ref out_path) = args.output {
        std::fs::write(out_path, &json_output)?;
        eprintln!(
            "Succès: {} enregistrement(s) exporté(s) vers '{}'.",
            reports.len(),
