```rust
// src/main.rs
use anyhow::{Context, Result};
use clap::Parser;
use colored::*;
use serde_json::Value;
use std::collections::BTreeSet;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

#[derive(Parser, Debug)]
#[command(
    name = "json-diff",
    about = "CLI de comparaison différentielle entre deux fichiers JSON",
    version
)]
struct Args {
    /// Fichier JSON d'origine (source/left)
    #[arg(value_name = "SOURCE_FILE")]
    source: PathBuf,

    /// Fichier JSON cible à comparer (target/right)
    #[arg(value_name = "TARGET_FILE")]
    target: PathBuf,

    /// Désactiver la colorisation dans la sortie
    #[arg(long, default_value_t = false)]
    no_color: bool,
}

#[derive(Debug, PartialEq, Eq)]
enum Difference {
    Added {
        path: String,
        value: Value,
    },
    Removed {
        path: String,
        value: Value,
    },
    Modified {
        path: String,
        old_value: Value,
        new_value: Value,
    },
}

impl Difference {
    fn print(&self, no_color: bool) {
        if no_color {
            match self {
                Difference::Added { path, value } => {
                    println!("+ {}: {}", path, value);
                }
                Difference::Removed { path, value } => {
                    println!("- {}: {}", path, value);
                }
                Difference::Modified {
                    path,
                    old_value,
                    new_value,
                } => {
                    println!("~ {}: {} => {}", path, old_value, new_value);
                }
            }
        } else {
            match self {
                Difference::Added { path, value } => {
                    let symbol = "+".green().bold();
                    let path_str = path.bold();
                    let val_str = value.to_string().green();
                    println!("{} {}: {}", symbol, path_str, val_str);
                }
                Difference::Removed { path, value } => {
                    let symbol = "-".red().bold();
                    let path_str = path.bold();
                    let val_str = value.to_string().red();
                    println!("{} {}: {}", symbol, path_str, val_str);
                }
                Difference::Modified {
                    path,
                    old_value,
                    new_value,
                } => {
                    let symbol = "~".yellow().bold();
                    let path_str = path.bold();
                    let old_str = old_value.to_string().red();
                    let arrow = "=>".bright_black();
                    let new_str = new_value.to_string().green();
                    println!("{} {}: {} {} {}", symbol, path_str, old_str, arrow, new_str);
                }
            }
        }
    }
}

fn load_json(path: &Path) -> Result<Value> {
    let content = fs::read_to_string(path)
        .with_context(|| format!("Impossible de lire le fichier '{}'", path.display()))?;

    serde_json::from_str(&content)
        .with_context(|| format!("Erreur d'analyse JSON du fichier '{}'", path.display()))
}

fn append_path_segment(base: &str, segment: &str) -> String {
    if base.is_empty() {
        format!("/{}", segment)
    } else {
        format!("{}/{}", base, segment)
    }
}

fn compute_diff(source: &Value, target: &Value, path: &str, acc: &mut Vec<Difference>) {
    match (source, target) {
        (Value::Object(map_a), Value::Object(map_b)) => {
            let mut all_keys: BTreeSet<&String> = BTreeSet::new();
            all_keys.extend(map_a.keys());
            all_keys.extend(map_b.keys());

            for key in all_keys {
                let sub_path = append_path_segment(path, key);
                match (map_a.get(key), map_b.get(key)) {
                    (Some(val_a), Some(val_b)) => {
                        compute_diff(val_a, val_b, &sub_path, acc);
                    }
                    (Some(val_a), None) => {
                        acc.push(Difference::Removed {
                            path: sub_path,
                            value: val_a.clone(),
                        });
                    }
                    (None, Some(val_b)) => {
                        acc.push(Difference::Added {
                            path: sub_path,
                            value: val_b.clone(),
                        });
                    }
                    (None, None) => unreachable!(),
                }
            }
        }
        (Value::Array(arr_a), Value::Array(arr_b)) => {
            let min_len = arr_a.len().min(arr_b.len());
            for idx in 0..min_len {
                let sub_path = append_path_segment(path, &idx.to_string());
                compute_diff(&arr_a[idx], &arr_b[idx], &sub_path, acc);
            }

            if arr_a.len() > min_len {
                for (idx, val) in arr_a.iter().enumerate().skip(min_len) {
                    let sub_path = append_path_segment(path, &idx.to_string());
                    acc.push(Difference::Removed {
                        path: sub_path,
                        value: val.clone(),
                    });
                }
            } else if arr_b.len() > min_len {
                for (idx, val) in arr_b.iter().enumerate().skip(min_len) {
                    let sub_path = append_path_segment(path, &idx.to_string());
                    acc.push(Difference::Added {
                        path: sub_path,
                        value: val.clone(),
                    });
                }
            }
        }
        (val_a, val_b) => {
            if val_a != val_b {
                let formatted_path = if path.is_empty() {
                    "/".to_string()
                } else {
                    path.to_string()
                };
                acc.push(Difference::Modified {
                    path: formatted_path,
                    old_value: val_a.clone(),
                    new_value: val_b.clone(),
                });
            }
        }
    }
}

fn run(args: Args) -> Result<bool> {
    let source_json = load_json(&args.source)?;
    let target_json = load_json(&args.target)?;

    let mut differences = Vec::new();
    compute_diff(&source_json, &target_json, "", &mut differences);

    if differences.is_empty() {
        if !args.no_color {
            println!("{}", "Les fichiers JSON sont identiques.".green());
        } else {
            println!("Les fichiers JSON sont identiques.");
        }
        Ok(true)
    } else {
        for diff in &differences {
            diff.print(args.no_color);
        }
        Ok(false)
    }
}

fn main() -> ExitCode {
    let args = Args::parse();
    match run(args) {
        Ok(true) => ExitCode::SUCCESS,
        Ok(false) => ExitCode::from(1),
        Err(err) => {
            eprintln!("{}: {:?}", "Erreur".red().bold(), err);
            ExitCode::from(2)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn test_identical_values() {
        let a = json!({"name": "Alice", "age": 30});
        let b = json!({"name": "Alice", "age": 30});
        let mut diffs = Vec::new();
        compute_diff(&a, &b, "", &mut diffs);
        assert!(diffs.is_empty());
    }

    #[test]
    fn test_added_removed_modified() {
        let a = json!({
            "name": "Alice",
            "age": 30,
            "roles": ["user"]
        });
        let b = json!({
            "name": "Alice",
            "age": 31,
            "roles": ["user", "admin"],
            "city": "Paris"
        });

        let mut diffs = Vec::new();
        compute_diff(&a, &b, "", &mut diffs);

        assert_eq!(
            diffs,
            vec![
                Difference::Modified {
                    path: "/age".to_string(),
                    old_value: json!(30),
                    new_value: json!(31),
                },
                Difference::Added {
                    path: "/city".to_string(),
                    value: json!("Paris"),
                },
                Difference::Added {
                    path: "/roles/1".to_string(),
                    value: json!("admin"),
                },
            ]
        );
    }
}

