```rust
// src/main.rs
use byteorder::{BigEndian, ReadBytesExt, WriteBytesExt};
use crc32fast::Hasher;
use std::collections::HashMap;
use std::fs::{File, OpenOptions};
use std::io::{self, BufReader, BufWriter, Read, Seek, SeekFrom, Write};
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};
use thiserror::Error;

/// Constantes pour les fichiers de données et d'index
const INDEX_MAGIC: &[u8; 4] = b"HSEX";
const INDEX_VERSION: u16 = 1;

const FLAG_VALIDE: u8 = 0x00;
const FLAG_TOMBSTONE: u8 = 0x01;

/// En-tête fixe d'enregistrement de données :
/// CRC32 (4) + Timestamp (8) + KeyLen (4) + ValLen (4) + Flags (1) = 21 octets
const DATA_HEADER_SIZE: usize = 21;

#[derive(Error, Debug)]
pub enum StorageError {
    #[error("Erreur d'entrée/sortie : {0}")]
    Io(#[from] io::Error),

    #[error("Corruption détectée : CRC32 invalide (calculé={computed}, attendu={expected})")]
    CrcMismatch { computed: u32, expected: u32 },

    #[error("Fichier d'index corrompu ou format invalide")]
    InvalidIndexFormat,

    #[error("Données tronquées ou fin de fichier inattendue")]
    UnexpectedEof,
}

pub type Result<T> = std::result::Result<T, StorageError>;

/// Entrée d'index pointant vers l'emplacement physique dans le fichier de données
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct IndexEntry {
    pub offset: u64,
    pub total_size: u64,
    pub timestamp: u64,
}

/// Moteur de stockage clé-valeur
pub struct StorageEngine {
    data_path: PathBuf,
    index_path: PathBuf,
    data_file: File,
    index: HashMap<Vec<u8>, IndexEntry>,
}

impl StorageEngine {
    /// Ouvre ou crée le moteur de stockage dans le dossier spécifié
    pub fn open<P: AsRef<Path>>(dir: P) -> Result<Self> {
        let dir = dir.as_ref();
        std::fs::create_dir_all(dir)?;

        let data_path = dir.join("data.db");
        let index_path = dir.join("index.idx");

        let data_file = OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .truncate(false)
            .open(&data_path)?;

        let mut engine = Self {
            data_path,
            index_path,
            data_file,
            index: HashMap::new(),
        };

        // Tenter de charger l'index persistant, sinon reconstruire depuis data.db
        if engine.index_path.exists() {
            if let Err(e) = engine.load_persisted_index() {
                eprintln!(
                    "Avertissement : échec de lecture de l'index persistant ({}), reconstruction intégrale...",
                    e
                );
                engine.rebuild_index_from_data()?;
                engine.persist_index()?;
            }
        } else {
            engine.rebuild_index_from_data()?;
            engine.persist_index()?;
        }

        Ok(engine)
    }

    /// Récupère une valeur associée à une clé
    pub fn get(&mut self, key: &[u8]) -> Result<Option<Vec<u8>>> {
        let entry = match self.index.get(key) {
            Some(e) => e.clone(),
            None => return Ok(None),
        };

        self.data_file.seek(SeekFrom::Start(entry.offset))?;
        let mut reader = BufReader::new(&mut self.data_file);

        let crc_expected = reader.read_u32::<BigEndian>()?;
        let timestamp = reader.read_u64::<BigEndian>()?;
        let key_len = reader.read_u32::<BigEndian>()? as usize;
        let val_len = reader.read_u32::<BigEndian>()? as usize;
        let flags = reader.read_u8()?;

        let mut read_key = vec![0u8; key_len];
        reader.read_exact(&mut read_key)?;

        let mut read_val = vec![0u8; val_len];
        reader.read_exact(&mut read_val)?;

        // Validation CRC32
        let mut hasher = Hasher::new();
        hasher.update(&timestamp.to_be_bytes());
        hasher.update(&(key_len as u32).to_be_bytes());
        hasher.update(&(val_len as u32).to_be_bytes());
        hasher.update(&[flags]);
        hasher.update(&read_key);
        hasher.update(&read_val);
        let crc_computed = hasher.finalize();

        if crc_computed != crc_expected {
            return Err(StorageError::CrcMismatch {
                computed: crc_computed,
                expected: crc_expected,
            });
        }

        if flags == FLAG_TOMBSTONE {
            return Ok(None);
        }

        Ok(Some(read_val))
    }

    /// Insère ou met à jour une paire clé/valeur
    pub fn put(&mut self, key: &[u8], value: &[u8]) -> Result<()> {
        let timestamp = current_time_micros();
        let offset = self.data_file.seek(SeekFrom::End(0))?;

        let mut hasher = Hasher::new();
        hasher.update(&timestamp.to_be_bytes());
        hasher.update(&(key.len() as u32).to_be_bytes());
        hasher.update(&(value.len() as u32).to_be_bytes());
        hasher.update(&[FLAG_VALIDE]);
        hasher.update(key);
        hasher.update(value);
        let crc = hasher.finalize();

        {
            let mut writer = BufWriter::new(&mut self.data_file);
            writer.write_u32::<BigEndian>(crc)?;
            writer.write_u64::<BigEndian>(timestamp)?;
            writer.write_u32::<BigEndian>(key.len() as u32)?;
            writer.write_u32::<BigEndian>(value.len() as u32)?;
            writer.write_u8(FLAG_VALIDE)?;
            writer.write_all(key)?;
            writer.write_all(value)?;
            writer.flush()?;
        }

        let total_size = (DATA_HEADER_SIZE + key.len() + value.len()) as u64;

        let entry = IndexEntry {
            offset,
            total_size,
            timestamp,
        };

        self.index.insert(key.to_vec(), entry);
        self.persist_index()?;

        Ok(())
    }

    /// Supprime une clé (insertion d'un enregistrement tombstone)
    pub fn delete(&mut self, key: &[u8]) -> Result<bool> {
        if !self.index.contains_key(key) {
            return Ok(false);
        }

        let timestamp = current_time_micros();
        let _offset = self.data_file.seek(SeekFrom::End(0))?;

        let mut hasher = Hasher::new();
        hasher.update(&timestamp.to_be_bytes());
        hasher.update(&(key.len() as u32).to_be_bytes());
        hasher.update(&0u32.to_be_bytes()); // ValLen = 0
        hasher.update(&[FLAG_TOMBSTONE]);
        hasher.update(key);
        let crc = hasher.finalize();

        {
            let mut writer = BufWriter::new(&mut self.data_file);
            writer.write_u32::<BigEndian>(crc)?;
            writer.write_u64::<BigEndian>(timestamp)?;
            writer.write_u32::<BigEndian>(key.len() as u32)?;
            writer.write_u32::<BigEndian>(0)?;
            writer.write_u8(FLAG_TOMBSTONE)?;
            writer.write_all(key)?;
            writer.flush()?;
        }

        self.index.remove(key);
        self.persist_index()?;

        Ok(true)
    }

    /// Nombre de clés actives stockées
    pub fn len(&self) -> usize {
        self.index.len()
    }

    /// Indique si la table est vide
    pub fn is_empty(&self) -> bool {
        self.index.is_empty()
    }

    /// Compaction des données (Garbage Collection)
    /// Réécrit uniquement les entrées actives dans un nouveau fichier de données compacté
    pub fn compact(&mut self) -> Result<()> {
        let parent_dir = self
            .data_path
            .parent()
            .map(Path::to_path_buf)
            .unwrap_or_else(|| PathBuf::from("."));

        let compact_data_path = parent_dir.join("data.compact.tmp");
        let mut compact_file = OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .truncate(true)
            .open(&compact_data_path)?;

        let mut new_index = HashMap::new();
        let mut new_offset = 0u64;

        // Récupérer et copier chaque entrée active
        for (key, entry) in &self.index {
            self.data_file.seek(SeekFrom::Start(entry.offset))?;
            let mut buffer = vec![0u8; entry.total_size as usize];
            self.data_file.read_exact(&mut buffer)?;

            compact_file.write_all(&buffer)?;

            new_index.insert(
                key.clone(),
                IndexEntry {
                    offset: new_offset,
                    total_size: entry.total_size,
                    timestamp: entry.timestamp,
                },
            );

            new_offset += entry.total_size;
        }

        compact_file.flush()?;

        // Remplacement atomique du fichier de données
        std::fs::rename(&compact_data_path, &self.data_path)?;

        // Réouverture du descripteur de fichier principal
        self.data_file = OpenOptions::new()
            .read(true)
            .write(true)
            .open(&self.data_path)?;

        self.index = new_index;
        self.persist_index()?;

        Ok(())
    }

    /// Sérialise et sauvegarde la table d'index sur disque
    pub fn persist_index(&self) -> Result<()> {
        let temp_index_path = self.index_path.with_extension("tmp");
        {
            let file = OpenOptions::new()
                .write(true)
                .create(true)
                .truncate(true)
                .open(&temp_index_path)?;
            let mut writer = BufWriter::new(file);

            // En-tête : Magic + Version
            writer.write_all(INDEX_MAGIC)?;
            writer.write_u16::<BigEndian>(INDEX_VERSION)?;

            // Nombre d'entrées
            writer.write_u64::<BigEndian>(self.index.len() as u64)?;

            for (key, entry) in &self.index {
                writer.write_u32::<BigEndian>(key.len() as u32)?;
                writer.write_u64::<BigEndian>(entry.offset)?;
                writer.write_u64::<BigEndian>(entry.total_size)?;
                writer.write_u64::<BigEndian>(entry.timestamp)?;
                writer.write_all(key)?;
            }

            writer.flush()?;
        }

        // Remplacement atomique
        std::fs::rename(&temp_index_path, &self.index_path)?;
        Ok(())
    }

    /// Charge la table d'index depuis le fichier persistant
    fn load_persisted_index(&mut self) -> Result<()> {
        let file = File::open(&self.index_path)?;
        let mut reader = BufReader::new(file);

        let mut magic = [0u8; 4];
        reader.read_exact(&mut magic)?;
        if &magic != INDEX_MAGIC {
            return Err(StorageError::InvalidIndexFormat);
        }

        let version = reader.read_u16::<BigEndian>()?;
        if version != INDEX_VERSION {
            return Err(StorageError::InvalidIndexFormat);
        }

        let entry_count = reader.read_u64::<BigEndian>()?;
        let mut new_index = HashMap::with_capacity(entry_count as usize);

        for _ in 0..entry_count {
            let key_len = reader.read_u32::<BigEndian>()? as usize;
            let offset = reader.read_u64::<BigEndian>()?;
            let total_size = reader.read_u64::<BigEndian>()?;
            let timestamp = reader.read_u64::<BigEndian>()?;

            let mut key = vec![0u8; key_len];
            reader.read_exact(&mut key)?;

            new_index.insert(
                key,
                IndexEntry {
                    offset,
                    total_size,
                    timestamp,
                },
            );
        }

        self.index = new_index;
        Ok(())
    }

    /// Reconstruit la table d'index en parcourant intégralement le fichier de données
    fn rebuild_index_from_data(&mut self) -> Result<()> {
        let total_file_len = self.data_file.seek(SeekFrom::End(0))?;
        if total_file_len == 0 {
            self.index.clear();
            return Ok(());
        }

        self.data_file.seek(SeekFrom::Start(0))?;
        let mut reader = BufReader::new(&mut self.data_file);
        let mut current_offset = 0u64;
        let mut new_index = HashMap::new();

        while current_offset < total_file_len {
            let crc_expected = match reader.read_u32::<BigEndian>() {
                Ok(v) => v,
                Err(e) if e.kind() == io::ErrorKind::UnexpectedEof => break,
                Err(e) => return Err(StorageError::Io(e)),
            };

            let timestamp = reader.read_u64::<BigEndian>()?;
            let key_len = reader.read_u32::<BigEndian>()? as usize;
            let val_len = reader.read_u32::<BigEndian>()? as usize;
            let flags = reader.read_u8()?;

            let mut key = vec![0u8; key_len];
            reader.read_exact(&mut key)?;

            let mut val = vec![0u8; val_len];
            reader.read_exact(&mut val)?;

            // Validation CRC
            let mut hasher = Hasher::new();
            hasher.update(&timestamp.to_be_bytes());
            hasher.update(&(key_len as u32).to_be_bytes());
            hasher.update(&(val_len as u32).to_be_bytes());
            hasher.update(&[flags]);
            hasher.update(&key);
            hasher.update(&val);
            let crc_computed = hasher.finalize();

            if crc_computed != crc_expected {
                return Err(StorageError::CrcMismatch {
                    computed: crc_computed,
                    expected: crc_expected,
                });
            }

            let entry_size = (DATA_HEADER_SIZE + key_len + val_len) as u64;

            if flags == FLAG_TOMBSTONE {
                new_index.remove(&key);
            } else {
                new_index.insert(
                    key,
                    IndexEntry {
                        offset: current_offset,
                        total_size: entry_size,
                        timestamp,
                    },
                );
            }

            current_offset += entry_size;
        }

        self.index = new_index;
        Ok(())
    }
}

fn current_time_micros() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_micros() as u64
}

fn main() -> Result<()> {
    println!("=== Démarrage du Moteur de Stockage Clé-Valeur Persistant ===");

    let db_dir = tempfile::tempdir()?;
    let db_path = db_dir.path();
    println!("Emplacement du stockage temporaire : {:?}", db_path);

    {
        println!("\n1. Initialisation et insertions initiales...");
        let mut engine = StorageEngine::open(db_path)?;

        engine.put(b"user:1001", b"Alice, Ing\xc3\xa9nieure Syst\xc3\xa8mes")?;
        engine.put(b"user:1002", b"Bob, DevOps Architect")?;
        engine.put(b"config:cache_size", b"1048576")?;
        engine.put(b"session:abc", b"token_987654321")?;

        println!("-> 4 clés insérées avec succès. Nombre de clés : {}", engine.len());

        // Lecture
        if let Some(val) = engine.get(b"user:1001")? {
            println!("-> Récupération 'user:1001' : {}", String::from_utf8_lossy(&val));
        }

        // Mise à jour (append-only)
        println!("\n2. Mise à jour de 'user:1001'...");
        engine.put(b"user:1001", b"Alice, Directrice Technique")?;
        if let Some(val) = engine.get(b"user:1001")? {
            println!("-> Nouvelle valeur pour 'user:1001' : {}", String::from_utf8_lossy(&val));
        }

        // Suppression (Tombstone)
        println!("\n3. Suppression de 'session:abc'...");
        let deleted = engine.delete(b"session:abc")?;
        println!("-> Suppression effectuée : {}", deleted);
        let check_session = engine.get(b"session:abc")?;
        println!("-> Vérification get('session:abc') : {:?}", check_session);
        println!("-> Nombre de clés actives : {}", engine.len());
    }

    {
        println!("\n4. Réouverture du moteur (validation du rechargement de l'index persistant)...");
        let mut engine = StorageEngine::open(db_path)?;
        println!("-> Index chargé depuis disque avec succès. Clés actives : {}", engine.len());

        if let Some(val) = engine.get(b"user:1001")? {
            println!("-> 'user:1001' lu après redémarrage : {}", String::from_utf8_lossy(&val));
        }
        if let Some(val) = engine.get(b"user:1002")? {
            println!("-> 'user:1002' lu après redémarrage : {}", String::from_utf8_lossy(&val));
        }

        // Test de compaction
        println!("\n5. Exécution de la compaction (Garbage Collection)...");
        engine.compact()?;
        println!("-> Compaction terminée. Clés actives conservées : {}", engine.len());

        if let Some(val) = engine.get(b"user:1001")? {
            println!("-> 'user:1001' après compaction : {}", String::from_utf8_lossy(&val));
        }
    }

    println!("\n=== Tous les tests d'intégrité et de persistance ont réussi ===");
    Ok(())
}

