```rust
// src/main.rs
use std::fs;
use std::io::{self, Read, Write};
use std::path::PathBuf;

use anyhow::{Context, Result};
use clap::{Parser, ValueEnum};
use indexmap::IndexMap;
use serde_yaml::Value;

#[derive(Debug, Clone, Copy, ValueEnum)]
enum OutputFormat {
    /// Format JSON (avec indentation)
    Json,
    /// Format TOML
    Toml,
}

#[derive(Parser, Debug)]
#[command(
    name = "yaml-converter",
    about = "Convertit des fichiers YAML vers JSON ou TOML en conservant l'ordre des clés.",
    version
)]
struct Cli {
    /// Fichier YAML en entrée (lit stdin si non spécifié ou si '-')
    #[arg(short, long, value_name = "INPUT")]
    input: Option<PathBuf>,

    /// Fichier de sortie (écrit sur stdout si non spécifié)
    #[arg(short, long, value_name = "OUTPUT")]
    output: Option<PathBuf>,

    /// Format cible souhaité
    #[arg(short, long, value_enum, default_value_t = OutputFormat::Json)]
    format: OutputFormat,

    /// Écrire du JSON compact (sans indentation) lorsque le format est JSON
    #[arg(long, default_value_t = false)]
    compact: bool,
}

fn read_input(input_path: Option<&PathBuf>) -> Result<String> {
    match input_path {
        Some(path) if path.to_str() != Some("-") => {
            fs::read_to_string(path).with_context(|| format!("Impossible de lire le fichier: {}", path.display()))
        }
        _ => {
            let mut buffer = String::new();
            io::stdin()
                .read_to_string(&mut buffer)
                .context("Impossible de lire depuis l'entrée standard (stdin)")?;
            Ok(buffer)
        }
    }
}

fn write_output(output_path: Option<&PathBuf>, content: &str) -> Result<()> {
    match output_path {
        Some(path) => {
            fs::write(path, content).with_context(|| format!("Impossible d'écrire dans le fichier: {}", path.display()))
        }
        None => {
            let stdout = io::stdout();
            let mut handle = stdout.lock();
            handle
                .write_all(content.as_bytes())
                .context("Erreur lors de l'écriture sur la sortie standard (stdout)")?;
            if !content.ends_with('\n') {
                handle.write_all(b"\n").context("Erreur lors de l'écriture du saut de ligne final")?;
            }
            Ok(())
        }
    }
}

fn convert_yaml(yaml_content: &str, format: OutputFormat, compact: bool) -> Result<String> {
    // Désérialisation avec serde_yaml::Value qui utilise IndexMap en interne
    let value: Value = serde_yaml::from_str(yaml_content).context("Échec du parsing du YAML en entrée")?;

    match format {
        OutputFormat::Json => {
            if compact {
                serde_json::to_string(&value).context("Erreur lors de la sérialisation en JSON compact")
            } else {
                serde_json::to_string_pretty(&value).context("Erreur lors de la sérialisation en JSON indenté")
            }
        }
        OutputFormat::Toml => {
            // TOML requiert une table (Map) à la racine.
            // On vérifie si la racine est bien un Mapping pour fournir une erreur claire.
            match value {
                Value::Mapping(_) => {
                    // Désérialise directement vers une structure ordonnée compatible TOML
                    let map: IndexMap<String, Value> = serde_yaml::from_value(value)
                        .context("Impossible d'adapter la structure pour le format TOML")?;
                    toml::to_string_pretty(&map).context("Erreur lors de la sérialisation en TOML")
                }
                _ => anyhow::bail!("La conversion vers TOML requiert un document YAML de type objet/dictionnaire à la racine"),
            }
        }
    }
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    let yaml_data = read_input(cli.input.as_ref())?;
    let converted = convert_yaml(&yaml_data, cli.format, cli.compact)?;
    write_output(cli.output.as_ref(), &converted)?;

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_yaml_to_json_preserves_order() {
        let yaml = r#"
z_key: 1
a_key: 2
m_key:
  sub_z: "val1"
  sub_a: "val2"
"#;
        let json = convert_yaml(yaml, OutputFormat::Json, true).expect("Conversion JSON réussie");
        // Vérifie que les sous-chaînes apparaissent dans le bon ordre
        let idx_z = json.find("\"z_key\"").unwrap();
        let idx_a = json.find("\"a_key\"").unwrap();
        let idx_m = json.find("\"m_key\"").unwrap();
        assert!(idx_z < idx_a);
        assert!(idx_a < idx_m);

        let idx_sub_z = json.find("\"sub_z\"").unwrap();
        let idx_sub_a = json.find("\"sub_a\"").unwrap();
        assert!(idx_sub_z < idx_sub_a);
    }

    #[test]
    fn test_yaml_to_toml_preserves_order() {
        let yaml = r#"
z_first: 10
a_second: 20
b_third: 30
"#;
        let toml = convert_yaml(yaml, OutputFormat::Toml, false).expect("Conversion TOML réussie");
        let idx_z = toml.find("z_first").unwrap();
        let idx_a = toml.find("a_second").unwrap();
        let idx_b = toml.find("b_third").unwrap();
        assert!(idx_z < idx_a);
        assert!(idx_a < idx_b);
    }

    #[test]
    fn test_yaml_to_toml_invalid_root() {
        let yaml = r#"
- item1
- item2
"#;
        let result = convert_yaml(yaml, OutputFormat::Toml, false);
        assert!(result.is_err());
    }
}

