// src/main.rs
use std::collections::{HashMap, VecDeque};
use std::hash::{DefaultHasher, Hash, Hasher};
use std::path::{Path, PathBuf};
use std::sync::Arc;

use parking_lot::RwLock;
use serde::{de::DeserializeOwned, Serialize};
use thiserror::Error;
use tokio::fs;
use tokio::sync::{mpsc, oneshot};
use tokio::task::JoinHandle;
use tracing::{debug, error, info};

/// Erreurs spécifiques au cache hybride.
#[derive(Debug, Error)]
pub enum CacheError {
    #[error("Erreur I/O : {0}")]
    Io(#[from] std::io::Error),

    #[error("Erreur de sérialisation/désérialisation Bincode : {0}")]
    Serialization(#[from] bincode::Error),

    #[error("Le canal d'arrière-plan est fermé")]
    ChannelClosed,

    #[error("La tâche d'arrière-plan a échoué")]
    TaskJoin(#[from] tokio::task::JoinError),
}

/// Événements transmis à la tâche d'arrière-plan via Tokio mpsc.
enum CacheCommand<K, V> {
    Write {
        key: K,
        value: V,
    },
    Delete {
        key: K,
    },
    Flush {
        responder: oneshot::Sender<Result<(), CacheError>>,
    },
}

/// Cache L1 en mémoire avec politique d'éviction LRU basée sur VecDeque.
struct MemoryCache<K, V> {
    capacity: usize,
    entries: HashMap<K, V>,
    order: VecDeque<K>,
}

impl<K: Eq + Hash + Clone, V: Clone> MemoryCache<K, V> {
    fn new(capacity: usize) -> Self {
        Self {
            capacity,
            entries: HashMap::with_capacity(capacity),
            order: VecDeque::with_capacity(capacity),
        }
    }

    fn get(&mut self, key: &K) -> Option<V> {
        if let Some(val) = self.entries.get(key) {
            let val = val.clone();
            if let Some(pos) = self.order.iter().position(|k| k == key) {
                self.order.remove(pos);
            }
            self.order.push_back(key.clone());
            Some(val)
        } else {
            None
        }
    }

    fn insert(&mut self, key: K, value: V) -> Option<K> {
        let mut evicted = None;

        if self.entries.contains_key(&key) {
            if let Some(pos) = self.order.iter().position(|k| k == &key) {
                self.order.remove(pos);
            }
        } else if self.entries.len() >= self.capacity && self.capacity > 0 {
            if let Some(oldest_key) = self.order.pop_front() {
                self.entries.remove(&oldest_key);
                evicted = Some(oldest_key);
            }
        }

        self.order.push_back(key.clone());
        self.entries.insert(key, value);
        evicted
    }

    fn remove(&mut self, key: &K) -> Option<V> {
        if let Some(pos) = self.order.iter().position(|k| k == key) {
            self.order.remove(pos);
        }
        self.entries.remove(key)
    }

    fn len(&self) -> usize {
        self.entries.len()
    }
}

