/// Cache Hybride Mémoire-Disque avec sérialisation asynchrone en tâche de fond.
pub struct HybridCache<K, V> {
    memory: Arc<RwLock<MemoryCache<K, V>>>,
    disk: DiskStore,
    sender: mpsc::Sender<CacheCommand<K, V>>,
    worker_handle: Option<JoinHandle<()>>,
}

impl<K, V> HybridCache<K, V>
where
    K: Eq + Hash + Clone + Serialize + DeserializeOwned + Send + Sync + 'static,
    V: Clone + Serialize + DeserializeOwned + Send + Sync + 'static,
{
    pub async fn new<P: AsRef<Path>>(
        disk_path: P,
        memory_capacity: usize,
        queue_capacity: usize,
    ) -> Result<Self, CacheError> {
        let disk = DiskStore::new(disk_path).await?;
        let memory = Arc::new(RwLock::new(MemoryCache::new(memory_capacity)));
        let (sender, mut receiver) = mpsc::channel::<CacheCommand<K, V>>(queue_capacity);

        let disk_worker = disk.clone();
        let worker_handle = tokio::spawn(async move {
            debug!("Démarrage du worker de sérialisation disque en arrière-plan");
            while let Some(command) = receiver.recv().await {
                match command {
                    CacheCommand::Write { key, value } => {
                        if let Err(e) = disk_worker.write(&key, &value).await {
                            error!("Erreur lors de l'écriture disque asynchrone : {}", e);
                        }
                    }
                    CacheCommand::Delete { key } => {
                        if let Err(e) = disk_worker.delete(&key).await {
                            error!("Erreur lors de la suppression disque asynchrone : {}", e);
                        }
                    }
                    CacheCommand::Flush { responder } => {
                        let _ = responder.send(Ok(()));
                    }
                }
            }
            debug!("Arrêt du worker de sérialisation d'arrière-plan");
        });

        Ok(Self {
            memory,
            disk,
            sender,
            worker_handle: Some(worker_handle),
        })
    }

    /// Récupère une valeur : priorité L1 (RAM), sinon fallback asynchrone sur L2 (Disque).
    pub async fn get(&self, key: &K) -> Result<Option<V>, CacheError> {
        // 1. Tenter L1
        {
            let mut mem = self.memory.write();
            if let Some(val) = mem.get(key) {
                return Ok(Some(val));
            }
        }

        // 2. Tenter L2 (Disque)
        let disk_val: Option<V> = self.disk.read(key).await?;
        if let Some(val) = disk_val {
            // Promotion L1
            let mut mem = self.memory.write();
            mem.insert(key.clone(), val.clone());
            return Ok(Some(val));
        }

        Ok(None)
    }

    /// Insère une valeur dans L1 et délègue l'écriture L2 au worker sans bloquer.
    pub async fn insert(&self, key: K, value: V) -> Result<(), CacheError> {
        // Insertion L1 synchrone
        {
            let mut mem = self.memory.write();
            mem.insert(key.clone(), value.clone());
        }

        // Émission asynchrone vers le worker L2
        self.sender
            .send(CacheCommand::Write { key, value })
            .await
            .map_err(|_| CacheError::ChannelClosed)?;

        Ok(())
    }

    /// Supprime un élément de L1 et de L2.
    pub async fn remove(&self, key: &K) -> Result<Option<V>, CacheError> {
        let mem_val = {
            let mut mem = self.memory.write();
            mem.remove(key)
        };

        self.sender
            .send(CacheCommand::Delete { key: key.clone() })
            .await
            .map_err(|_| CacheError::ChannelClosed)?;

        Ok(mem_val)
    }

    /// Attend que toutes les opérations en attente dans la file aient été traitées.
    pub async fn flush(&self) -> Result<(), CacheError> {
        let (resp_tx, resp_rx) = oneshot::channel();
        self.sender
            .send(CacheCommand::Flush { responder: resp_tx })
            .await
            .map_err(|_| CacheError::ChannelClosed)?;

        resp_rx.await.map_err(|_| CacheError::ChannelClosed)?
    }

    /// Nombre d'éléments actuellement présents en mémoire vive (L1).
    pub fn memory_len(&self) -> usize {
        self.memory.read().len()
    }

    /// Arrêt propre du cache : attend le traitement complet et stoppe la tâche de fond.
    pub async fn shutdown(mut self) -> Result<(), CacheError> {
        self.flush().await?;
        drop(self.sender);
        if let Some(handle) = self.worker_handle.take() {
            handle.await?;
        }
        Ok(())
    }
}

