// src/main.rs
use std::fs::File;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use anyhow::{bail, Context, Result};
use arrow::array::{
    Array, Float64Array, Float64Builder, RecordBatch, TimestampNanosecondArray,
    TimestampNanosecondBuilder,
};
use arrow::datatypes::{DataType, Field, Schema, TimeUnit};
use chrono::{DateTime, Duration, TimeZone, Utc};
use clap::Parser;
use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;
use parquet::arrow::ArrowWriter;
use parquet::file::properties::WriterProperties;

#[derive(Parser, Debug)]
#[command(
    name = "financial_parquet_analyzer",
    author = "Financial Analytics Team",
    version = "0.1.0",
    about = "Analyseur de séries temporelles financières stockées en Parquet calculant moyennes mobiles et volatilité."
)]
struct Args {
    /// Chemin du fichier Parquet source (ex: dataset.parquet).
    #[arg(short, long)]
    input: Option<PathBuf>,

    /// Chemin du fichier Parquet de sortie contenant les métriques calculées.
    #[arg(short, long)]
    output: Option<PathBuf>,

    /// Fenêtre courte pour le calcul de la SMA/EMA (en nombre de bougies).
    #[arg(long, default_value_t = 20)]
    short_window: usize,

    /// Fenêtre longue pour le calcul de la SMA/EMA (en nombre de bougies).
    #[arg(long, default_value_t = 50)]
    long_window: usize,

    /// Fenêtre glissante pour la volatilité réalisée annualisée (ex: 20 jours).
    #[arg(long, default_value_t = 20)]
    volatility_window: usize,

    /// Périodes de trading annuelles pour l'annualisation de la volatilité (ex: 252 pour actions, 365 pour crypto).
    #[arg(long, default_value_t = 252.0)]
    annualization_factor: f64,

    /// Génère un jeu de données synthétique pour démonstration si le fichier d'entrée n'existe pas.
    #[arg(long, default_value_t = false)]
    generate_demo: bool,

    /// Nombre de lignes à générer en mode démo.
    #[arg(long, default_value_t = 250)]
    demo_records: usize,
}

#[derive(Debug, Clone)]
pub struct Candle {
    pub timestamp_ns: i64,
    pub open: f64,
    pub high: f64,
    pub low: f64,
    pub close: f64,
    pub volume: f64,
}

#[derive(Debug, Clone)]
pub struct AnalysisResults {
    pub timestamps: Vec<i64>,
    pub closes: Vec<f64>,
    pub log_returns: Vec<Option<f64>>,
    pub sma_short: Vec<Option<f64>>,
    pub sma_long: Vec<Option<f64>>,
    pub ema_short: Vec<Option<f64>>,
    pub ema_long: Vec<Option<f64>>,
    pub realized_volatility: Vec<Option<f64>>,
}

fn main() -> Result<()> {
    let args = Args::parse();

    if args.short_window == 0 || args.long_window == 0 || args.volatility_window == 0 {
        bail!("Toutes les fenêtres d'analyse doivent être strictement positives (> 0).");
    }

    if args.short_window > args.long_window {
        bail!("La fenêtre courte ({}) ne peut pas être supérieure à la fenêtre longue ({}).", 
            args.short_window, args.long_window);
    }

    let input_path = match args.input.as_ref() {
        Some(path) => path.clone(),
        None => {
            let default_path = PathBuf::from("data_demo.parquet");
            if !default_path.exists() || args.generate_demo {
                println!("[INFO] Aucun fichier d'entrée spécifié. Génération du fichier de démonstration : {}", default_path.display());
                generate_sample_parquet(&default_path, args.demo_records)?;
            }
            default_path
        }
    };

    if !input_path.exists() {
        if args.generate_demo {
            println!("[INFO] Création du jeu de données synthétique sur demande : {}", input_path.display());
            generate_sample_parquet(&input_path, args.demo_records)?;
        } else {
            bail!("Le fichier spécifié n'existe pas : {}. Utilisez --generate-demo pour créer un fichier modèle.", input_path.display());
        }
    }

    println!("===============================================================================");
    println!("  Analyseur Financier Parquet - Moyennes Mobiles & Volatilité");
    println!("===============================================================================");
    println!("Fichier source         : {}", input_path.display());
    println!("Fenêtre SMA/EMA Courte : {} périodes", args.short_window);
    println!("Fenêtre SMA/EMA Longue : {} périodes", args.long_window);
    println!("Fenêtre Volatilité     : {} périodes (Annualisation: x{:.1})", args.volatility_window, args.annualization_factor);
    println!("-------------------------------------------------------------------------------");

    let candles = load_candles_from_parquet(&input_path)?;
    println!("[OK] Chargement de {} bougies temporelles réussi.", candles.len());

    if candles.is_empty() {
        bail!("Le fichier Parquet ne contient aucun enregistrement.");
    }

    let results = compute_financial_metrics(
        &candles,
        args.short_window,
        args.long_window,
        args.volatility_window,
        args.annualization_factor,
    );

    print_summary_table(&results, 15);

    if let Some(out_path) = args.output.as_ref() {
        write_results_to_parquet(out_path, &results)?;
        println!("[OK] Résultats exportés vers : {}", out_path.display());
    }

    println!("===============================================================================");
    println!("Traitement terminé avec succès.");
    Ok(())
}

/// Lit et désérialise les séries temporelles financières depuis un fichier Apache Parquet.
fn load_candles_from_parquet(path: &Path) -> Result<Vec<Candle>> {
    let file = File::open(path)
        .with_context(|| format!("Impossible d'ouvrir le fichier Parquet: {}", path.display()))?;

    let builder = ParquetRecordBatchReaderBuilder::try_new(file)
        .with_context(|| "Échec de l'initialisation du lecteur Parquet")?;
    let mut reader = builder.build()
        .with_context(|| "Échec de construction du lecteur de RecordBatches")?;

    let mut candles = Vec::new();

    while let Some(batch_res) = reader.next() {
        let batch = batch_res.with_context(|| "Erreur lors de la lecture d'un RecordBatch")?;
        let schema = batch.schema();

        let ts_idx = schema.index_of("timestamp").or_else(|_| schema.index_of("time"))
            .with_context(|| "Colonne temporelle ('timestamp' ou 'time') introuvable")?;
        let open_idx = schema.index_of("open").with_context(|| "Colonne 'open' manquante")?;
        let high_idx = schema.index_of("high").with_context(|| "Colonne 'high' manquante")?;
        let low_idx = schema.index_of("low").with_context(|| "Colonne 'low' manquante")?;
        let close_idx = schema.index_of("close").with_context(|| "Colonne 'close' manquante")?;
        let vol_idx = schema.index_of("volume").unwrap_or_else(|_| close_idx);

        let row_count = batch.num_rows();

        for row in 0..row_count {
            let timestamp_ns = extract_timestamp_ns(batch.column(ts_idx), row)?;
            let open = extract_f64(batch.column(open_idx), row)?;
            let high = extract_f64(batch.column(high_idx), row)?;
            let low = extract_f64(batch.column(low_idx), row)?;
            let close = extract_f64(batch.column(close_idx), row)?;
            let volume = if vol_idx != close_idx {
                extract_f64(batch.column(vol_idx), row).unwrap_or(0.0)
            } else {
                0.0
            };

            candles.push(Candle {
                timestamp_ns,
                open,
                high,
                low,
                close,
                volume,
            });
        }
    }

    candles.sort_by_key(|c| c.timestamp_ns);
    Ok(candles)
}

/// Convertit un champ d'une ligne Arrow en f64 quel que soit son encodage flottant / entier compatible.
fn extract_f64(column: &Arc<dyn Array>, row: usize) -> Result<f64> {
    if column.is_null(row) {
        return Ok(0.0);
    }

    match column.data_type() {
        DataType::Float64 => {
            let arr = column.as_any().downcast_ref::<Float64Array>()
                .context("Downcast Float64Array échoué")?;
            Ok(arr.value(row))
        }
        DataType::Float32 => {
            let arr = column.as_any().downcast_ref::<arrow::array::Float32Array>()
                .context("Downcast Float32Array échoué")?;
            Ok(arr.value(row) as f64)
        }
        DataType::Int64 => {
            let arr = column.as_any().downcast_ref::<arrow::array::Int64Array>()
                .context("Downcast Int64Array échoué")?;
            Ok(arr.value(row) as f64)
        }
        DataType::Int32 => {
            let arr = column.as_any().downcast_ref::<arrow::array::Int32Array>()
                .context("Downcast Int32Array échoué")?;
            Ok(arr.value(row) as f64)
        }
        other => bail!("Type non supporté pour valeur financière : {:?}", other),
    }
}

/// Convertit une colonne de timestamps Arrow en nanosecondes Unix.
fn extract_timestamp_ns(column: &Arc<dyn Array>, row: usize) -> Result<i64> {
    if column.is_null(row) {
        bail!("Timestamp nul rencontré à la ligne {}", row);
    }

    match column.data_type() {
        DataType::Timestamp(unit, _) => {
            let factor = match unit {
                TimeUnit::Second => 1_000_000_000,
                TimeUnit::Millisecond => 1_000_000,
                TimeUnit::Microsecond => 1_000,
                TimeUnit::Nanosecond => 1,
            };
            let arr = column.as_any().downcast_ref::<TimestampNanosecondArray>();
            if let Some(ns_arr) = arr {
                Ok(ns_arr.value(row))
            } else {
                let int_arr = column.as_any().downcast_ref::<arrow::array::Int64Array>()
                    .context("Échec d'accès à la colonne timestamp en Int64")?;
                Ok(int_arr.value(row) * factor)
            }
        }
        DataType::Int64 => {
            let arr = column.as_any().downcast_ref::<arrow::array::Int64Array>()
                .context("Downcast Int64Array pour timestamp échoué")?;
            let val = arr.value(row);
            if val < 10_000_000_000 {
                Ok(val * 1_000_000_000)
            } else if val < 10_000_000_000_000 {
                Ok(val * 1_000_000)
            } else {
                Ok(val)
            }
        }
        other => bail!("Type de colonne temporelle non pris en charge : {:?}", other),
    }
}

/// Calcule les métriques financières quantitatives sur la série des cours de clôture.
pub fn compute_financial_metrics(
    candles: &[Candle],
    short_window: usize,
    long_window: usize,
    vol_window: usize,
    annualization_factor: f64,
) -> AnalysisResults {
    let n = candles.len();
    let mut timestamps = Vec::with_capacity(n);
    let mut closes = Vec::with_capacity(n);

    for c in candles {
        timestamps.push(c.timestamp_ns);
        closes.push(c.close);
    }

    let mut log_returns = vec![None; n];
    for i in 1..n {
        let prev = closes[i - 1];
        let curr = closes[i];
        if prev > 0.0 && curr > 0.0 {
            log_returns[i] = Some((curr / prev).ln());
        }
    }

    let sma_short = calculate_sma(&closes, short_window);
    let sma_long = calculate_sma(&closes, long_window);
    let ema_short = calculate_ema(&closes, short_window);
    let ema_long = calculate_ema(&closes, long_window);
    let realized_volatility = calculate_realized_volatility(&log_returns, vol_window, annualization_factor);

    AnalysisResults {
        timestamps,
        closes,
        log_returns,
        sma_short,
        sma_long,
        ema_short,
        ema_long,
        realized_volatility,
    }
}

/// Moyenne Mobile Simple (SMA) sur fenêtre glissante.
fn calculate_sma(data: &[f64], window: usize) -> Vec<Option<f64>> {
    let n = data.len();
    let mut result = vec![None; n];
    if window == 0 || n < window {
        return result;
    }

    let mut sum: f64 = data[..window].iter().sum();
    result[window - 1] = Some(sum / window as f64);

    for i in window..n {
        sum += data[i] - data[i - window];
        result[i] = Some(sum / window as f64);
    }

    result
}

/// Moyenne Mobile Exponentielle (EMA) avec facteur de lissage alpha = 2 / (N + 1).
fn calculate_ema(data: &[f64], window: usize) -> Vec<Option<f64>> {
    let n = data.len();
    let mut result = vec![None; n];
    if window == 0 || n < window {
        return result;
    }

    let alpha = 2.0 / (window as f64 + 1.0);
    let seed_sum: f64 = data[..window].iter().sum();
    let mut current_ema = seed_sum / window as f64;
    result[window - 1] = Some(current_ema);

    for i in window..n {
        current_ema = alpha * data[i] + (1.0 - alpha) * current_ema;
        result[i] = Some(current_ema);
    }

    result
}

/// Volatilité réalisée annualisée basée sur l'écart-type d'échantillon des rendements log.
fn calculate_realized_volatility(
    returns: &[Option<f64>],
    window: usize,
    annualization_factor: f64,
) -> Vec<Option<f64>> {
    let n = returns.len();
    let mut result = vec![None; n];
    if window < 2 || n < window {
        return result;
    }

    for i in (window - 1)..n {
        let slice = &returns[(i + 1 - window)..=i];
        let valid_returns: Vec<f64> = slice.iter().filter_map(|&r| r).collect();

        if valid_returns.len() == window {
            let mean = valid_returns.iter().sum::<f64>() / window as f64;
            let variance = valid_returns
                .iter()
                .map(|r| (r - mean).powi(2))
                .sum::<f64>()
                / (window as f64 - 1.0);

            let annualized_vol = variance.sqrt() * annualization_factor.sqrt();
            result[i] = Some(annualized_vol);
        }
    }

    result
}

/// Affiche un résumé sous forme de tableau formaté pour les dernières périodes.
fn print_summary_table(res: &AnalysisResults, rows_to_display: usize) {
    let count = res.timestamps.len();
    let start_idx = count.saturating_sub(rows_to_display);

    println!("\n{:<22} | {:>10} | {:>9} | {:>9} | {:>9} | {:>9} | {:>10}",
        "Date / Heure (UTC)", "Close", "SMA(Crt)", "SMA(Lng)", "EMA(Crt)", "EMA(Lng)", "Volatilité");
    println!("{:-<22}-+-{:-<10}-+-{:-<9}-+-{:-<9}-+-{:-<9}-+-{:-<9}-+-{:-<10}",
        "", "", "", "", "", "", "");

    for i in start_idx..count {
        let ts_sec = res.timestamps[i] / 1_000_000_000;
        let ts_subsec_ns = (res.timestamps[i] % 1_000_000_000) as u32;
        let dt = Utc.timestamp_opt(ts_sec, ts_subsec_ns)
            .single()
            .unwrap_or_else(|| DateTime::from_timestamp(0, 0).unwrap_or_default());

        let format_opt = |val: Option<f64>, decimals: usize| match val {
            Some(v) => format!("{:>width$.dec$}", v, width = 9, dec = decimals),
            None => format!("{:>9}", "N/A"),
        };

        let format_pct = |val: Option<f64>| match val {
            Some(v) => format!("{:>9.2}%", v * 100.0),
            None => format!("{:>10}", "N/A"),
        };

        println!("{:<22} | {:>10.2} | {} | {} | {} | {} | {}",
            dt.format("%Y-%m-%d %H:%M:%S"),
            res.closes[i],
            format_opt(res.sma_short[i], 2),
            format_opt(res.sma_long[i], 2),
            format_opt(res.ema_short[i], 2),
            format_opt(res.ema_long[i], 2),
            format_pct(res.realized_volatility[i]),
        );
    }
    println!();
}

/// Écrit les résultats de l'analyse dans un nouveau fichier Parquet avec schéma Arrow.
fn write_results_to_parquet(path: &Path, res: &AnalysisResults) -> Result<()> {
    let schema = Arc::new(Schema::new(vec![
        Field::new("timestamp", DataType::Timestamp(TimeUnit::Nanosecond, Some("UTC".into())), false),
        Field::new("close", DataType::Float64, false),
        Field::new("log_return", DataType::Float64, true),
        Field::new("sma_short", DataType::Float64, true),
        Field::new("sma_long", DataType::Float64, true),
        Field::new("ema_short", DataType::Float64, true),
        Field::new("ema_long", DataType::Float64, true),
        Field::new("realized_volatility", DataType::Float64, true),
    ]));

    let mut ts_builder = TimestampNanosecondBuilder::new().with_data_type(DataType::Timestamp(TimeUnit::Nanosecond, Some("UTC".into())));
    for &ts in &res.timestamps {
        ts_builder.append_value(ts);
    }

    let mut close_builder = Float64Builder::new();
    for &c in &res.closes {
        close_builder.append_value(c);
    }

    let build_opt_col = |vec: &[Option<f64>]| {
        let mut b = Float64Builder::new();
        for &opt in vec {
            match opt {
                Some(v) => b.append_value(v),
                None => b.append_null(),
            }
        }
        Arc::new(b.finish()) as Arc<dyn Array>
    };

    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![
            Arc::new(ts_builder.finish()),
            Arc::new(close_builder.finish()),
            build_opt_col(&res.log_returns),
            build_opt_col(&res.sma_short),
            build_opt_col(&res.sma_long),
            build_opt_col(&res.ema_short),
            build_opt_col(&res.ema_long),
            build_opt_col(&res.realized_volatility),
        ],
    ).with_context(|| "Impossible de composer le RecordBatch pour l'export Parquet")?;

    let file = File::create(path)
        .with_context(|| format!("Création du fichier de destination échouée: {}", path.display()))?;

    let props = WriterProperties::builder().build();
    let mut writer = ArrowWriter::try_new(file, schema, Some(props))
        .with_context(|| "Initialisation du writer Parquet échouée")?;

    writer.write(&batch).with_context(|| "Échec de l'écriture du batch de données")?;
    writer.close().with_context(|| "Échec de fermeture du fichier Parquet")?;

    Ok(())
}

/// Génère un fichier Parquet d'exemple avec des cotations réalistes basées sur un modèle GBM.
pub fn generate_sample_parquet(path: &Path, count: usize) -> Result<()> {
    let schema = Arc::new(Schema::new(vec![
        Field::new("timestamp", DataType::Timestamp(TimeUnit::Nanosecond, Some("UTC".into())), false),
        Field::new("open", DataType::Float64, false),
        Field::new("high", DataType::Float64, false),
        Field::new("low", DataType::Float64, false),
        Field::new("close", DataType::Float64, false),
        Field::new("volume", DataType::Float64, false),
    ]));

    let mut start_time = Utc::now() - Duration::days(count as i64);
    let mut current_price = 100.0_f64;

    let mut ts_builder = TimestampNanosecondBuilder::new().with_data_type(DataType::Timestamp(TimeUnit::Nanosecond, Some("UTC".into())));
    let mut open_builder = Float64Builder::new();
    let mut high_builder = Float64Builder::new();
    let mut low_builder = Float64Builder::new();
    let mut close_builder = Float64Builder::new();
    let mut vol_builder = Float64Builder::new();

    // Pseudo-générateur déterministe simple (LCG) pour éviter les dépendances lourdes
    let mut seed = 42u64;
    let mut next_random = || -> f64 {
        seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1);
        let x = (seed >> 32) as u32;
        (x as f64) / (u32::MAX as f64)
    };

    for _ in 0..count {
        let ts_ns = match start_time.timestamp_nanos_opt() {
            Some(ns) => ns,
            None => start_time.timestamp() * 1_000_000_000,
        };
        start_time = start_time + Duration::days(1);

        let delta_pct = (next_random() - 0.49) * 0.04; // Volatilité journalière d'environ 2%
        let open = current_price;
        let close = (open * (1.0 + delta_pct)).max(1.0);
        let spread1 = open * (next_random() * 0.015);
        let spread2 = close * (next_random() * 0.015);
        let high = open.max(close) + spread1;
        let low = (open.min(close) - spread2).max(0.5);
        let volume = 10_000.0 + next_random() * 90_000.0;

        current_price = close;

        ts_builder.append_value(ts_ns);
        open_builder.append_value(open);
        high_builder.append_value(high);
        low_builder.append_value(low);
        close_builder.append_value(close);
        vol_builder.append_value(volume);
    }

    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![
            Arc::new(ts_builder.finish()),
            Arc::new(open_builder.finish()),
            Arc::new(high_builder.finish()),
            Arc::new(low_builder.finish()),
            Arc::new(close_builder.finish()),
            Arc::new(vol_builder.finish()),
        ],
    ).with_context(|| "Erreur lors de la construction du RecordBatch démo")?;

    let file = File::create(path)
        .with_context(|| format!("Création du fichier d'exemple démo échouée: {}", path.display()))?;

    let props = WriterProperties::builder().build();
    let mut writer = ArrowWriter::try_new(file, schema, Some(props))
        .with_context(|| "Initialisation du writer Parquet démo échouée")?;

    writer.write(&batch).with_context(|| "Écriture de l'échantillon démo échouée")?;
    writer.close().with_context(|| "Fermeture du writer démo échouée")?;

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_sma_calculation() {
        let prices = vec![10.0, 20.0, 30.0, 40.0, 50.0];
        let sma3 = calculate_sma(&prices, 3);
        assert_eq!(sma3[0], None);
        assert_eq!(sma3[1], None);
        assert!((sma3[2].unwrap() - 20.0).abs() < 1e-6);
        assert!((sma3[3].unwrap() - 30.0).abs() < 1e-6);
        assert!((sma3[4].unwrap() - 40.0).abs() < 1e-6);
    }

    #[test]
    fn test_ema_calculation() {
        let prices = vec![10.0, 10.0, 10.0, 10.0];
        let ema2 = calculate_ema(&prices, 2);
        assert_eq!(ema2[0], None);
        assert!((ema2[1].unwrap() - 10.0).abs() < 1e-6);
        assert!((ema2[2].unwrap() - 10.0).abs() < 1e-6);
        assert!((ema2[3].unwrap() - 10.0).abs() < 1e-6);
    }

    #[test]
    fn test_volatility_zero_for_constant_prices() {
        let prices: Vec<f64> = vec![100.0; 10];
        let mut returns: Vec<Option<f64>> = vec![None];
        for i in 1..prices.len() {
            let r: f64 = (prices[i] / prices[i - 1]).ln();
            returns.push(Some(r));
        }
        let vol = calculate_realized_volatility(&returns, 5, 252.0);
        if let Some(v) = vol[5] {
            assert!(v.abs() < 1e-9);
        }
    }
}

