/// Affiche un séparateur visuel dans la console.
fn print_separator(title: &str) {
    println!("\n{}", "=".repeat(75));
    println!("  {title}");
    println!("{}", "=".repeat(75));
}

/// Affiche les statistiques de compression sous forme de tableau formaté.
fn print_scenario_results(name: &str, stats: &ColumnCompressionStats) {
    println!("[Scénario] : {name}");
    println!("  |- Lignes totales : {} (valeurs nulles : {})", stats.total_rows, stats.null_count);
    println!("  |- Cardinalité (valeurs uniques) : {}", stats.unique_cardinality);
    println!("  |- Largeur binaire d'index : {} bits", stats.bit_width);
    println!("  |- Taille brute non compressée : {} octets", stats.uncompressed_bytes);
    println!("  |- Page de dictionnaire (PLAIN) : {} octets", stats.dictionary_page_bytes);
    println!("  |- Page de données (RLE/Bit-Packed) : {} octets", stats.data_page_bytes);
    println!("  |- Taille totale compressée : {} octets", stats.total_compressed_bytes);
    println!("  |- Taux de compression : {:.2}x", stats.compression_ratio);
    println!("  |- Économie d'espace : {:.2}%", stats.space_savings_percent);
    println!(
        "  |- Répartition encodage : {} blocs RLE ({} valeurs) | {} groupes Bit-Packed ({} valeurs)",
        stats.rle_stats.rle_runs,
        stats.rle_stats.rle_values_count,
        stats.rle_stats.bitpacked_groups,
        stats.rle_stats.bitpacked_values_count
    );
}

/// Valide de manière stricte l'intégrité après aller-retour (roundtrip).
fn verify_roundtrip(original: &[&str], compressed: &CompressedParquetColumn) -> Result<(), Box<dyn Error>> {
    let decompressed = ParquetTextColumnDecoder::decode(compressed)?;
    if original.len() != decompressed.len() {
        return Err(format!(
            "Incohérence de taille : attendu {}, obtenu {}",
            original.len(),
            decompressed.len()
        )
        .into());
    }

    for (idx, (orig, dec)) in original.iter().zip(decompressed.iter()).enumerate() {
        if *orig != dec.as_str() {
            return Err(format!(
                "Incohérence à la ligne {} : attendu '{}', obtenu '{}'",
                idx, orig, dec
            )
            .into());
        }
    }
    println!("  -> Validation d'intégrité : 100% conforme (aucune altération).");
    Ok(())
}

/// Valide de manière stricte l'intégrité d'une colonne optionnelle après aller-retour.
fn verify_nullable_roundtrip(
    original: &[Option<&str>],
    compressed: &CompressedParquetColumn,
) -> Result<(), Box<dyn Error>> {
    let decompressed = ParquetTextColumnDecoder::decode_nullable(compressed)?;
    if original.len() != decompressed.len() {
        return Err(format!(
            "Incohérence de taille : attendu {}, obtenu {}",
            original.len(),
            decompressed.len()
        )
        .into());
    }

    for (idx, (orig, dec)) in original.iter().zip(decompressed.iter()).enumerate() {
        let matches = match (orig, dec) {
            (None, None) => true,
            (Some(o), Some(d)) => *o == d.as_str(),
            _ => false,
        };
        if !matches {
            return Err(format!(
                "Incohérence à la ligne {} : attendu '{:?}', obtenu '{:?}'",
                idx, orig, dec
            )
            .into());
        }
    }
    println!("  -> Validation d'intégrité nullable : 100% conforme (niveaux de définition préservés).");
    Ok(())
}

