// src/main.rs
use std::fs::File;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use anyhow::{bail, Context, Result};
use arrow::array::{
    Array, ArrayRef, Int64Array, RecordBatch, StringArray, StringBuilder,
};
use arrow::datatypes::{DataType, Field, Schema};
use clap::{Parser, Subcommand, ValueEnum};
use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;
use parquet::arrow::ArrowWriter;
use parquet::file::properties::WriterProperties;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use tracing::{info, warn};

#[derive(Parser, Debug)]
#[command(name = "gdpr-parquet-auditor")]
#[command(about = "Audit de conformité RGPD et anonymisation/hachage de fichiers Parquet")]
#[command(version = "0.1.0")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Analyse un fichier Parquet et liste les colonnes à risque RGPD identifiées
    Audit {
        /// Chemin du fichier Parquet à auditer
        #[arg(short, long)]
        input: PathBuf,
    },
    /// Traite un fichier Parquet pour anonymiser ou hacher les colonnes sensibles
    Process {
        /// Fichier Parquet source
        #[arg(short, long)]
        input: PathBuf,

        /// Fichier Parquet de destination
        #[arg(short, long)]
        output: PathBuf,

        /// Chemin optionnel du rapport d'audit JSON en sortie
        #[arg(short, long, default_value = "audit_report.json")]
        report: PathBuf,

        /// Sel cryptographique pour le hachage SHA-256 (ou via GDPR_HASH_SALT)
        #[arg(long, env = "GDPR_HASH_SALT", default_value = "default_secret_salt_2026")]
        salt: String,

        /// Action appliquée par défaut aux colonnes sensibles détectées
        #[arg(long, value_enum, default_value_t = DefaultAction::Hash)]
        action: DefaultAction,
    },
    /// Génère un fichier Parquet de démonstration contenant des données sensibles fictives
    GenerateSample {
        /// Chemin où sauvegarder le fichier Parquet généré
        #[arg(short, long, default_value = "sample_users.parquet")]
        output: PathBuf,

        /// Nombre de lignes à générer
        #[arg(short, long, default_value_t = 100)]
        rows: usize,
    },
}

#[derive(ValueEnum, Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
enum DefaultAction {
    Hash,
    Mask,
    Redact,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ColumnRule {
    name: String,
    data_type: String,
    risk_category: String,
    action: DefaultAction,
}

#[derive(Debug, Serialize, Deserialize)]
struct AuditReport {
    timestamp: chrono::DateTime<chrono::Utc>,
    input_file: String,
    output_file: Option<String>,
    total_rows_processed: usize,
    columns_audited: usize,
    sensitive_columns_found: Vec<ColumnRule>,
    status: String,
}

/// Détecte le niveau de risque RGPD d'une colonne selon son nom
fn detect_risk_category(col_name: &str) -> Option<(&'static str, DefaultAction)> {
    let lower = col_name.to_lowercase();
    if lower.contains("email") || lower.contains("mail") {
        Some(("Identifiant Personnel (Email)", DefaultAction::Hash))
    } else if lower.contains("ip_address") || lower.contains("ip") {
        Some(("Identifiant Réseau (Adresse IP)", DefaultAction::Mask))
    } else if lower.contains("ssn")
        || lower.contains("nir")
        || lower.contains("social_security")
        || lower.contains("iban")
        || lower.contains("card")
    {
        Some(("Donnée Hautement Sensible", DefaultAction::Redact))
    } else if lower.contains("phone") || lower.contains("tel") {
        Some(("Coordonnées (Téléphone)", DefaultAction::Mask))
    } else if lower.contains("firstname")
        || lower.contains("lastname")
        || lower.contains("nom")
        || lower.contains("prenom")
        || lower.contains("full_name")
        || lower.contains("name")
    {
        Some(("Identité Civile (Nom/Prénom)", DefaultAction::Hash))
    } else {
        None
    }
}

/// Hachage salé SHA-256
fn hash_value(value: &str, salt: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(salt.as_bytes());
    hasher.update(b":");
    hasher.update(value.as_bytes());
    hex::encode(hasher.finalize())
}

/// Masquage partiel
fn mask_value(value: &str) -> String {
    if value.is_empty() {
        return String::new();
    }
    if value.contains('@') {
        let parts: Vec<&str> = value.split('@').collect();
        if parts.len() == 2 {
            let user = parts[0];
            let domain = parts[1];
            let masked_user = if user.len() <= 2 {
                "**".to_string()
            } else {
                format!("{}***", &user[..2])
            };
            return format!("{}@{}", masked_user, domain);
        }
    }
    if value.len() <= 4 {
        "****".to_string()
    } else {
        let visible_prefix = &value[..2];
        let visible_suffix = &value[value.len() - 2..];
        format!("{}***{}", visible_prefix, visible_suffix)
    }
}

/// Transformation d'une colonne de type Utf8
fn transform_utf8_array(
    array: &StringArray,
    action: DefaultAction,
    salt: &str,
) -> ArrayRef {
    let mut builder = StringBuilder::with_capacity(array.len(), array.len() * 32);

    for i in 0..array.len() {
        if array.is_null(i) {
            builder.append_null();
            continue;
        }

        let original = array.value(i);
        match action {
            DefaultAction::Hash => {
                let hashed = hash_value(original, salt);
                builder.append_value(hashed);
            }
            DefaultAction::Mask => {
                let masked = mask_value(original);
                builder.append_value(masked);
            }
            DefaultAction::Redact => {
                builder.append_value("[ANONYMIZED]");
            }
        }
    }

    Arc::new(builder.finish())
}

/// Audit des colonnes sensibles d'un fichier Parquet
fn audit_parquet_file(input_path: &Path) -> Result<Vec<ColumnRule>> {
    let file = File::open(input_path)
        .with_context(|| format!("Impossible d'ouvrir le fichier {}", input_path.display()))?;

    let builder = ParquetRecordBatchReaderBuilder::try_new(file)
        .with_context(|| "Échec de l'initialisation du lecteur Parquet")?;

    let schema = builder.schema();
    let mut sensitive_rules = Vec::new();

    for field in schema.fields() {
        if let Some((risk, default_action)) = detect_risk_category(field.name()) {
            sensitive_rules.push(ColumnRule {
                name: field.name().clone(),
                data_type: field.data_type().to_string(),
                risk_category: risk.to_string(),
                action: default_action,
            });
        }
    }

    Ok(sensitive_rules)
}

/// Traitement et anonymisation/hachage d'un fichier Parquet
fn process_parquet_file(
    input_path: &Path,
    output_path: &Path,
    report_path: &Path,
    salt: &str,
    global_action_override: Option<DefaultAction>,
) -> Result<()> {
    info!("Début du traitement de {}", input_path.display());
    let file = File::open(input_path)
        .with_context(|| format!("Impossible d'ouvrir le fichier {}", input_path.display()))?;

    let reader_builder = ParquetRecordBatchReaderBuilder::try_new(file)
        .with_context(|| "Échec de construction du lecteur Parquet")?;

    let schema = reader_builder.schema().clone();
    let mut sensitive_rules = Vec::new();

    for field in schema.fields() {
        if let Some((risk, default_act)) = detect_risk_category(field.name()) {
            let chosen_action = global_action_override.unwrap_or(default_act);
            sensitive_rules.push(ColumnRule {
                name: field.name().clone(),
                data_type: field.data_type().to_string(),
                risk_category: risk.to_string(),
                action: chosen_action,
            });
        }
    }

    info!(
        "Nombre de colonnes sensibles identifiées : {}",
        sensitive_rules.len()
    );

    let mut reader = reader_builder.build().with_context(|| "Impossible de lire les batches")?;

    let out_file = File::create(output_path)
        .with_context(|| format!("Impossible de créer le fichier {}", output_path.display()))?;

    let props = WriterProperties::builder().build();
    let mut writer = ArrowWriter::try_new(out_file, schema.clone(), Some(props))
        .with_context(|| "Échec lors de l'initialisation de l'écrivain Parquet")?;

    let mut total_rows = 0;

    while let Some(batch_result) = reader.next() {
        let batch = batch_result.with_context(|| "Erreur lors de la lecture d'un RecordBatch")?;
        let batch_rows = batch.num_rows();
        total_rows += batch_rows;

        let mut transformed_columns: Vec<ArrayRef> = Vec::with_capacity(batch.num_columns());

        for (col_idx, field) in schema.fields().iter().enumerate() {
            let column_array = batch.column(col_idx);

            if let Some(rule) = sensitive_rules.iter().find(|r| r.name == *field.name()) {
                if let DataType::Utf8 = field.data_type() {
                    let string_array = column_array
                        .as_any()
                        .downcast_ref::<StringArray>()
                        .context("Échec du downcast vers StringArray")?;
                    let new_array = transform_utf8_array(string_array, rule.action, salt);
                    transformed_columns.push(new_array);
                } else {
                    warn!(
                        "La colonne '{}' est de type '{}', seule l'anonymisation Utf8 est implémentée pour l'instant. Valeur conservée.",
                        field.name(),
                        field.data_type()
                    );
                    transformed_columns.push(Arc::clone(column_array));
                }
            } else {
                transformed_columns.push(Arc::clone(column_array));
            }
        }

        let new_batch = RecordBatch::try_new(schema.clone(), transformed_columns)
            .with_context(|| "Échec lors de la réassemblage du RecordBatch anonymisé")?;

        writer
            .write(&new_batch)
            .with_context(|| "Échec lors de l'écriture du batch")?;
    }

    writer
        .close()
        .with_context(|| "Échec lors de la finalisation du fichier Parquet")?;

    info!("Écriture terminée. Total lignes traitées: {}", total_rows);

    let audit_report = AuditReport {
        timestamp: chrono::Utc::now(),
        input_file: input_path.to_string_lossy().to_string(),
        output_file: Some(output_path.to_string_lossy().to_string()),
        total_rows_processed: total_rows,
        columns_audited: schema.fields().len(),
        sensitive_columns_found: sensitive_rules,
        status: "SUCCESS".to_string(),
    };

    let report_file = File::create(report_path)
        .with_context(|| format!("Impossible de créer le rapport {}", report_path.display()))?;
    serde_json::to_writer_pretty(report_file, &audit_report)
        .with_context(|| "Échec de sérialisation du rapport JSON")?;

    info!("Rapport d'audit généré dans {}", report_path.display());
    Ok(())
}

