// src/main.rs
use std::fs::File;
use std::io::{self, BufReader, BufWriter, Read, Write};
use std::path::PathBuf;

use anyhow::{Context, Result};
use chrono::{NaiveDate, NaiveDateTime};
use clap::Parser;
use serde_json::{Map, Value};

/// CLI pour nettoyer et convertir des données tabulaires sales en JSON propre.
#[derive(Parser, Debug)]
#[command(
    name = "data-cleaner",
    author = "Damien",
    version = "0.1.0",
    about = "Parse et nettoie les données sales (formats de date, valeurs manquantes, types) vers un format JSON propre."
)]
struct Args {
    /// Chemin du fichier CSV d'entrée (ou stdin si non spécifié)
    #[arg(short, long)]
    input: Option<PathBuf>,

    /// Chemin du fichier JSON de sortie (ou stdout si non spécifié)
    #[arg(short, long)]
    output: Option<PathBuf>,

    /// Délimiteur CSV (par défaut: détection automatique ou virgule ',')
    #[arg(short, long)]
    delimiter: Option<char>,

    /// Formater le JSON de sortie de manière indentée
    #[arg(short = 'p', long, default_value_t = false)]
    pretty: bool,

    /// Émettre en JSON Lines (NDJSON) plutôt qu'en tableau JSON
    #[arg(long, default_value_t = false)]
    ndjson: bool,
}

/// Marqueurs textuels représentatifs de valeurs absentes ou nulles.
const MISSING_MARKERS: &[&str] = &[
    "", "na", "n/a", "null", "none", "nil", "-", "?", "undefined", "#n/a", "missing",
];

/// Formats de date/heure testés pour la normalisation.
const DATE_FORMATS: &[&str] = &[
    "%Y-%m-%d",
    "%d/%m/%Y",
    "%m/%d/%Y",
    "%Y/%m/%d",
    "%d-%m-%Y",
    "%m-%d-%Y",
    "%d.%m.%Y",
    "%Y.%m.%d",
];

const DATETIME_FORMATS: &[&str] = &[
    "%Y-%m-%d %H:%M:%S",
    "%Y-%m-%dT%H:%M:%S",
    "%Y-%m-%dT%H:%M:%SZ",
    "%d/%m/%Y %H:%M:%S",
    "%m/%d/%Y %H:%M:%S",
];

/// Tente de nettoyer une valeur brute et d'inférer son type réel.
fn clean_and_infer_value(raw: &str) -> Value {
    let trimmed = raw.trim();

    // 1. Détection de valeur manquante
    let lower = trimmed.to_lowercase();
    if MISSING_MARKERS.contains(&lower.as_str()) {
        return Value::Null;
    }

    // 2. Détection booléenne
    match lower.as_str() {
        "true" | "vrai" | "oui" | "yes" => return Value::Bool(true),
        "false" | "faux" | "non" | "no" => return Value::Bool(false),
        _ => {}
    }

    // 3. Détection de date ou date-heure
    if let Some(parsed_dt) = try_parse_datetime(trimmed) {
        return Value::String(parsed_dt.format("%Y-%m-%dT%H:%M:%SZ").to_string());
    }
    if let Some(parsed_d) = try_parse_date(trimmed) {
        return Value::String(parsed_d.format("%Y-%m-%d").to_string());
    }

    // 4. Détection numérique entière
    if let Ok(int_val) = trimmed.parse::<i64>() {
        return Value::from(int_val);
    }

    // 5. Détection numérique décimale (supporte point '.' et virgule ',')
    let normalized_num = trimmed.replace(',', ".");
    if let Ok(float_val) = normalized_num.parse::<f64>() {
        if float_val.is_finite() {
            if let Some(num) = serde_json::Number::from_f64(float_val) {
                return Value::Number(num);
            }
        }
    }

    // 6. Valeur textuelle épurée par défaut
    Value::String(trimmed.to_string())
}

/// Tente de parser une date selon divers formats répandus.
fn try_parse_date(raw: &str) -> Option<NaiveDate> {
    for fmt in DATE_FORMATS {
        if let Ok(d) = NaiveDate::parse_from_str(raw, fmt) {
            return Some(d);
        }
    }
    None
}

/// Tente de parser un timestamp selon divers formats répandus.
fn try_parse_datetime(raw: &str) -> Option<NaiveDateTime> {
    for fmt in DATETIME_FORMATS {
        if let Ok(dt) = NaiveDateTime::parse_from_str(raw, fmt) {
            return Some(dt);
        }
    }
    None
}

/// Statistiques de nettoyage.
#[derive(Default, Debug)]
struct CleaningStats {
    total_rows: usize,
    null_values: usize,
    normalized_dates: usize,
    numeric_values: usize,
}

fn main() -> Result<()> {
    let args = Args::parse();

    // Configuration de la source d'entrée (fichier ou stdin)
    let reader: Box<dyn Read> = match &args.input {
        Some(path) => {
            let file = File::open(path)
                .with_context(|| format!("Impossible d'ouvrir le fichier source {:?}", path))?;
            Box::new(BufReader::new(file))
        }
        None => Box::new(BufReader::new(io::stdin())),
    };

    // Configuration de la destination de sortie (fichier ou stdout)
    let writer: Box<dyn Write> = match &args.output {
        Some(path) => {
            let file = File::create(path)
                .with_context(|| format!("Impossible de créer le fichier cible {:?}", path))?;
            Box::new(BufWriter::new(file))
        }
        None => Box::new(BufWriter::new(io::stdout())),
    };

    let delimiter = args.delimiter.map(|c| c as u8).unwrap_or(b',');

    let mut csv_reader = csv::ReaderBuilder::new()
        .delimiter(delimiter)
        .flexible(true)
        .trim(csv::Trim::All)
        .from_reader(reader);

    let headers = csv_reader
        .headers()
        .context("Échec de lecture des en-têtes CSV")?
        .clone();

    let clean_headers: Vec<String> = headers
        .iter()
        .enumerate()
        .map(|(i, h)| {
            let name = h.trim();
            if name.is_empty() {
                format!("column_{}", i + 1)
            } else {
                name.to_string()
            }
        })
        .collect();

    let mut stats = CleaningStats::default();
    let mut cleaned_records: Vec<Map<String, Value>> = Vec::new();
    let mut out_writer = writer;

    if args.ndjson {
        // En mode NDJSON, streaming ligne par ligne
        for (row_idx, result) in csv_reader.records().enumerate() {
            let record = result.with_context(|| format!("Erreur de lecture CSV à la ligne {}", row_idx + 2))?;
            stats.total_rows += 1;

            let mut obj = Map::new();
            for (i, field) in record.iter().enumerate() {
                let key = clean_headers
                    .get(i)
                    .cloned()
                    .unwrap_or_else(|| format!("column_{}", i + 1));
                let value = clean_and_infer_value(field);

                update_stats(&value, &mut stats);
                obj.insert(key, value);
            }

            let json_line = serde_json::to_string(&obj)
                .context("Erreur de sérialisation NDJSON d'une ligne")?;
            writeln!(out_writer, "{}", json_line)
                .context("Erreur lors de l'écriture sur la sortie")?;
        }
    } else {
        // En mode JSON classique (tableau d'objets)
        for (row_idx, result) in csv_reader.records().enumerate() {
            let record = result.with_context(|| format!("Erreur de lecture CSV à la ligne {}", row_idx + 2))?;
            stats.total_rows += 1;

            let mut obj = Map::new();
            for (i, field) in record.iter().enumerate() {
                let key = clean_headers
                    .get(i)
                    .cloned()
                    .unwrap_or_else(|| format!("column_{}", i + 1));
                let value = clean_and_infer_value(field);

                update_stats(&value, &mut stats);
                obj.insert(key, value);
            }

            cleaned_records.push(obj);
        }

        let output_value = Value::Array(cleaned_records.into_iter().map(Value::Object).collect());

        if args.pretty {
            serde_json::to_writer_pretty(&mut out_writer, &output_value)
                .context("Erreur d'écriture JSON indenté")?;
        } else {
            serde_json::to_writer(&mut out_writer, &output_value)
                .context("Erreur d'écriture JSON compact")?;
        }
        writeln!(out_writer).context("Erreur lors de l'écriture finale du flux")?;
    }

    out_writer.flush().context("Erreur lors du flush de sortie")?;

    // Journalisation du rapport sur stderr pour ne pas altérer stdout si redirigé
    eprintln!(
        "[Rapport] {} ligne(s) traitée(s) | {} valeur(s) nulles | {} date(s) normalisée(s) | {} valeur(s) numériques.",
        stats.total_rows, stats.null_values, stats.normalized_dates, stats.numeric_values
    );

    Ok(())
}

fn update_stats(value: &Value, stats: &mut CleaningStats) {
    match value {
        Value::Null => stats.null_values += 1,
        Value::Number(_) => stats.numeric_values += 1,
        Value::String(s) => {
            // Détection si c'est une date normalisée YYYY-MM-DD ou RFC3339
            if (s.len() == 10 && s.chars().nth(4) == Some('-') && s.chars().nth(7) == Some('-'))
                || s.ends_with('Z')
            {
                stats.normalized_dates += 1;
            }
        }
        _ => {}
    }
}

