        assert_eq!(clean_and_infer_value(""), Value::Null);
        assert_eq!(clean_and_infer_value("  NA  "), Value::Null);
        assert_eq!(clean_and_infer_value("N/A"), Value::Null);
        assert_eq!(clean_and_infer_value("NULL"), Value::Null);
        assert_eq!(clean_and_infer_value("?"), Value::Null);
        assert_eq!(clean_and_infer_value("-"), Value::Null);
    }

    #[test]
    fn test_date_cleaning() {
        assert_eq!(
            clean_and_infer_value("25/12/2023"),
            Value::String("2023-12-25".to_string())
        );
        assert_eq!(
            clean_and_infer_value("2023-01-15"),
            Value::String("2023-01-15".to_string())
        );
        assert_eq!(
            clean_and_infer_value("10-31-2022"),
            Value::String("2022-10-31".to_string())
        );
        assert_eq!(
            clean_and_infer_value("2023-12-25 15:30:00"),
            Value::String("2023-12-25T15:30:00Z".to_string())
        );
    }

    #[test]
    fn test_numeric_cleaning() {
        assert_eq!(clean_and_infer_value("42"), Value::from(42));
        assert_eq!(
            clean_and_infer_value("12,50"),
            Value::Number(serde_json::Number::from_f64(12.5).unwrap())
        );
        assert_eq!(
            clean_and_infer_value(" -3.14 "),
            Value::Number(serde_json::Number::from_f64(-3.14).unwrap())
        );
    }

    #[test]
    fn test_boolean_and_string() {
        assert_eq!(clean_and_infer_value("OUI"), Value::Bool(true));
        assert_eq!(clean_and_infer_value("false"), Value::Bool(false));
        assert_eq!(
            clean_and_infer_value("  Produit A  "),
            Value::String("Produit A".to_string())
        );
    }
