/// Erreurs possibles du système de pagination et de stockage.
#[derive(Debug, Error)]
pub enum PaginationError {
    #[error("Erreur I/O : {0}")]
    Io(#[from] io::Error),

    #[error("Erreur de désérialisation binaire : {0}")]
    Bincode(#[from] bincode::Error),

    #[error("Curseur invalide : décodage base64 échoué : {0}")]
    InvalidBase64(#[from] base64::DecodeError),

    #[error("Curseur invalide : données corrompues ou format inconnu : {0}")]
    InvalidCursorPayload(#[from] serde_json::Error),

    #[error("Curseur invalide : somme de contrôle incohérente")]
    CursorIntegrityError,

    #[error("Position du curseur introuvable ou en dehors des limites du fichier")]
    CursorOutOfRange,

    #[error("Taille de page demandée invalide (doit être >= 1)")]
    InvalidPageSize,
}

/// Clé composite ordonnée garantissant un ordre total strict.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
pub struct RecordKey {
    pub timestamp_ms: i64,
    pub id: u64,
}

/// Enregistrement de données volumineux stocké sur disque.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Record {
    pub key: RecordKey,
    pub title: String,
    pub payload: Vec<u8>,
}

impl Record {
    pub fn new(timestamp_ms: i64, id: u64, title: String, payload_size: usize) -> Self {
        Self {
            key: RecordKey { timestamp_ms, id },
            title,
            payload: vec![0xAA; payload_size],
        }
    }
}

/// Représentation interne d'un curseur opaque.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CursorPayload {
    pub key: RecordKey,
    pub byte_offset: u64,
    pub checksum: u64,
}

impl CursorPayload {
    pub fn new(key: RecordKey, byte_offset: u64) -> Self {
        let checksum = Self::compute_checksum(&key, byte_offset);
        Self {
            key,
            byte_offset,
            checksum,
        }
    }

    fn compute_checksum(key: &RecordKey, byte_offset: u64) -> u64 {
        // Hachage simple rapide (FNV-1a 64-bit) pour vérifier l'intégrité du curseur
        let mut hash: u64 = 0xcbf29ce484222325;
        for byte in key.timestamp_ms.to_le_bytes() {
            hash ^= byte as u64;
            hash = hash.wrapping_mul(0x100000001b3);
        }
        for byte in key.id.to_le_bytes() {
            hash ^= byte as u64;
            hash = hash.wrapping_mul(0x100000001b3);
        }
        for byte in byte_offset.to_le_bytes() {
            hash ^= byte as u64;
            hash = hash.wrapping_mul(0x100000001b3);
        }
        hash
    }

    pub fn is_valid(&self) -> bool {
        self.checksum == Self::compute_checksum(&self.key, self.byte_offset)
    }

    pub fn encode(&self) -> Result<String, PaginationError> {
        let json_bytes = serde_json::to_vec(self)?;
        Ok(URL_SAFE_NO_PAD.encode(json_bytes))
    }

    pub fn decode(encoded: &str) -> Result<Self, PaginationError> {
        let decoded_bytes = URL_SAFE_NO_PAD.decode(encoded)?;
        let payload: Self = serde_json::from_slice(&decoded_bytes)?;
        if !payload.is_valid() {
            return Err(PaginationError::CursorIntegrityError);
        }
        Ok(payload)
    }
}

/// Direction de pagination.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PaginationDirection {
    Forward,
    Backward,
}

/// Requête de pagination.
#[derive(Debug, Clone)]
pub struct PageRequest {
    pub cursor: Option<String>,
    pub limit: usize,
    pub direction: PaginationDirection,
}

impl PageRequest {
    pub fn forward(limit: usize, cursor: Option<String>) -> Self {
        Self {
            cursor,
            limit,
            direction: PaginationDirection::Forward,
        }
    }

    pub fn backward(limit: usize, cursor: Option<String>) -> Self {
        Self {
            cursor,
            limit,
            direction: PaginationDirection::Backward,
        }
    }
}

/// Résultat d'une page de données.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Page<T> {
    pub items: Vec<T>,
    pub start_cursor: Option<String>,
    pub end_cursor: Option<String>,
    pub has_next_page: bool,
    pub has_previous_page: bool,
    pub page_size: usize,
}

/// Index dense en mémoire des positions pour accès séquentiel ou bisection.
#[derive(Debug, Clone)]
struct IndexEntry {
    key: RecordKey,
    offset: u64,
}

/// Moteur de stockage sérialisé binaire avec gestion de curseurs et index d'accès direct.
pub struct SerializedStorage {
    data_file_path: PathBuf,
    index: Vec<IndexEntry>,
}

impl SerializedStorage {
    /// Crée ou réinitialise un stockage à partir du chemin de fichier donné.
    pub fn open_or_create(path: impl AsRef<Path>) -> Result<Self, PaginationError> {
        let path_buf = path.as_ref().to_path_buf();
        let mut storage = Self {
            data_file_path: path_buf,
            index: Vec::new(),
        };

        if storage.data_file_path.exists() {
            storage.rebuild_index()?;
        }

        Ok(storage)
    }

    /// Reconstruit l'index à partir du fichier binaire existant.
    fn rebuild_index(&mut self) -> Result<(), PaginationError> {
        let mut file = BufReader::new(File::open(&self.data_file_path)?);
        self.index.clear();

        let mut current_offset = 0u64;
        let file_len = file.get_ref().metadata()?.len();

        while current_offset < file_len {
            file.seek(SeekFrom::Start(current_offset))?;
            let record_len: u32 = match bincode::deserialize_from(&mut file) {
                Ok(len) => len,
                Err(e) => {
                    if current_offset == file_len {
                        break;
                    }
                    return Err(PaginationError::Bincode(e));
                }
            };

            let prefix_size = std::mem::size_of::<u32>() as u64;
            let record: Record = bincode::deserialize_from(&mut file)?;
            self.index.push(IndexEntry {
                key: record.key,
                offset: current_offset,
            });

            current_offset += prefix_size + record_len as u64;
        }

        // Tri explicite pour s'assurer d'un ordre strict constant
        self.index.sort_by(|a, b| a.key.cmp(&b.key));
        Ok(())
    }

    /// Ajoute une série d'enregistrements dans le fichier sérialisé et met à jour l'index.
    pub fn append_batch(&mut self, records: &[Record]) -> Result<(), PaginationError> {
        let file = OpenOptions::new()
            .create(true)
            .append(true)
            .open(&self.data_file_path)?;
        let mut writer = BufWriter::new(file);

        let mut current_offset = writer.get_ref().metadata()?.len();

        for record in records {
            let serialized = bincode::serialize(record)?;
            let length = serialized.len() as u32;

            writer.write_all(&length.to_le_bytes())?;
            writer.write_all(&serialized)?;

            self.index.push(IndexEntry {
                key: record.key.clone(),
                offset: current_offset,
            });

            current_offset += (std::mem::size_of::<u32>() + serialized.len()) as u64;
        }

        writer.flush()?;
        self.index.sort_by(|a, b| a.key.cmp(&b.key));
        Ok(())
    }

    /// Nombre total d'enregistrements indexés.
    pub fn total_count(&self) -> usize {
        self.index.len()
    }

    /// Lit un enregistrement unique par son offset dans le fichier sans charger le reste.
    fn read_record_at(&self, offset: u64) -> Result<Record, PaginationError> {
        let mut file = File::open(&self.data_file_path)?;
        file.seek(SeekFrom::Start(offset))?;

        let mut len_bytes = [0u8; 4];
        file.read_exact(&mut len_bytes)?;
        let _record_len = u32::from_le_bytes(len_bytes);

        let record: Record = bincode::deserialize_from(&mut file)?;
        Ok(record)
    }

    /// Exécute une requête de pagination par curseur opaque.
    pub fn paginate(&self, request: &PageRequest) -> Result<Page<Record>, PaginationError> {
        if request.limit == 0 {
            return Err(PaginationError::InvalidPageSize);
        }

        if self.index.is_empty() {
            return Ok(Page {
                items: Vec::new(),
                start_cursor: None,
                end_cursor: None,
                has_next_page: false,
                has_previous_page: false,
                page_size: 0,
            });
        }

        match request.direction {
            PaginationDirection::Forward => self.paginate_forward(request),
            PaginationDirection::Backward => self.paginate_backward(request),
        }
    }

    fn paginate_forward(&self, request: &PageRequest) -> Result<Page<Record>, PaginationError> {
        let (start_idx, has_previous_page) = match &request.cursor {
            None => (0usize, false),
            Some(cursor_str) => {
                let cursor = CursorPayload::decode(cursor_str)?;
                // Recherche par dichotomie sur la clé ordonnée
                let search_result = self.index.binary_search_by(|entry| {
                    entry.key.cmp(&cursor.key)
                });

                match search_result {
                    Ok(exact_idx) => {
                        // Le curseur pointe vers le dernier élément vu ; on commence au suivant
                        (exact_idx + 1, true)
                    }
                    Err(insert_idx) => {
                        // Si le curseur n'est plus présent (suppression), on prend l'élément immédiatement supérieur
                        (insert_idx, insert_idx > 0)
                    }
                }
            }
        };

        if start_idx >= self.index.len() {
            return Ok(Page {
                items: Vec::new(),
                start_cursor: None,
                end_cursor: None,
                has_next_page: false,
                has_previous_page,
                page_size: 0,
            });
        }

        // On interroge (limit + 1) éléments pour déterminer s'il y a une page suivante sans requête supplémentaire
        let end_idx = (start_idx + request.limit).min(self.index.len());
        let has_next_page = (start_idx + request.limit) < self.index.len();

        let mut items = Vec::with_capacity(end_idx - start_idx);
        for entry in &self.index[start_idx..end_idx] {
            let record = self.read_record_at(entry.offset)?;
            items.push(record);
        }

        let start_cursor = items.first().map(|rec| {
            let offset = self.find_offset_for_key(&rec.key).unwrap_or(0);
            CursorPayload::new(rec.key.clone(), offset).encode()
        }).transpose()?;

        let end_cursor = items.last().map(|rec| {
            let offset = self.find_offset_for_key(&rec.key).unwrap_or(0);
            CursorPayload::new(rec.key.clone(), offset).encode()
        }).transpose()?;

        let page_size = items.len();

        Ok(Page {
            items,
            start_cursor,
            end_cursor,
            has_next_page,
            has_previous_page,
            page_size,
        })
    }

    fn paginate_backward(&self, request: &PageRequest) -> Result<Page<Record>, PaginationError> {
        let (end_idx, has_next_page) = match &request.cursor {
            None => (self.index.len(), false),
            Some(cursor_str) => {
                let cursor = CursorPayload::decode(cursor_str)?;
                let search_result = self.index.binary_search_by(|entry| {
                    entry.key.cmp(&cursor.key)
                });

                match search_result {
                    Ok(exact_idx) => {
                        // Le curseur pointe vers le premier élément vu ; on termine au précédent
                        (exact_idx, exact_idx < self.index.len())
                    }
                    Err(insert_idx) => {
                        (insert_idx, insert_idx < self.index.len())
                    }
                }
            }
        };

        if end_idx == 0 {
            return Ok(Page {
                items: Vec::new(),
                start_cursor: None,
                end_cursor: None,
                has_next_page,
                has_previous_page: false,
                page_size: 0,
            });
        }

        let start_idx = end_idx.saturating_sub(request.limit);
        let has_previous_page = start_idx > 0;

        let mut items = Vec::with_capacity(end_idx - start_idx);
        for entry in &self.index[start_idx..end_idx] {
            let record = self.read_record_at(entry.offset)?;
            items.push(record);
        }

        let start_cursor = items.first().map(|rec| {
            let offset = self.find_offset_for_key(&rec.key).unwrap_or(0);
            CursorPayload::new(rec.key.clone(), offset).encode()
        }).transpose()?;

        let end_cursor = items.last().map(|rec| {
            let offset = self.find_offset_for_key(&rec.key).unwrap_or(0);
            CursorPayload::new(rec.key.clone(), offset).encode()
        }).transpose()?;

        let page_size = items.len();

        Ok(Page {
            items,
            start_cursor,
            end_cursor,
            has_next_page,
            has_previous_page,
            page_size,
        })
    }

    fn find_offset_for_key(&self, key: &RecordKey) -> Option<u64> {
        self.index
            .binary_search_by(|e| e.key.cmp(key))
            .ok()
            .map(|idx| self.index[idx].offset)
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("===============================================================");
    println!("  Système de Pagination par Curseur sur Fichiers Sérialisés    ");
    println!("===============================================================\n");

    let temp_dir = tempfile::tempdir()?;
    let db_path = temp_dir.path().join("dataset.bin");

    println!("[1/4] Initialisation du stockage sérialisé : {:?}", db_path);
    let mut storage = SerializedStorage::open_or_create(&db_path)?;

    let total_records = 250;
    println!("[2/4] Génération et sérialisation binaire de {} enregistrements...", total_records);

    let base_time = Utc::now().timestamp_millis();
    let mut batch = Vec::with_capacity(total_records);

    for i in 1..=total_records {
        let timestamp_ms = base_time + (i as i64 * 100);
        let title = format!("Événement télémétrique #{:05}", i);
        let payload_size = 64; // Charge utile représentative
        batch.push(Record::new(timestamp_ms, i as u64, title, payload_size));
    }

    storage.append_batch(&batch)?;
    println!("      -> Écriture terminée. Total indexé : {} enregistrements.\n", storage.total_count());

    let page_size = 5;
    println!("[3/4] Parcours AVANT (Forward) avec pagination par curseur (page_size = {}) :", page_size);

    let mut current_cursor: Option<String> = None;
    let mut page_number = 1;

    // Navigation sur 4 pages consécutives vers l'avant
    while page_number <= 4 {
        let req = PageRequest::forward(page_size, current_cursor.clone());
        let page = storage.paginate(&req)?;

        println!(
            "  --- Page {} (Nb éléments: {}, has_prev: {}, has_next: {}) ---",
            page_number, page.page_size, page.has_previous_page, page.has_next_page
        );

        for item in &page.items {
            let dt = DateTime::from_timestamp_millis(item.key.timestamp_ms)
                .map(|t| t.format("%Y-%m-%d %H:%M:%S%.3f").to_string())
                .unwrap_or_else(|| "N/A".to_string());

            println!(
                "      [ID {:03}] Key(ts={}, id={}) | {} | Payload len: {}B",
                item.key.id, dt, item.key.id, item.title, item.payload.len()
            );
        }

        if let Some(ref end_c) = page.end_cursor {
            println!("      -> Curseur de fin (opaque Base64) : {}", end_c);
            current_cursor = Some(end_c.clone());
        }

        if !page.has_next_page {
            break;
        }

        page_number += 1;
        println!();
    }

    println!("\n[4/4] Parcours ARRIÈRE (Backward) depuis le curseur actuel :");
    if let Some(cursor) = current_cursor {
        let req = PageRequest::backward(page_size, Some(cursor));
        let prev_page = storage.paginate(&req)?;

        println!(
            "  --- Page précédente (Nb éléments: {}, has_prev: {}, has_next: {}) ---",
            prev_page.page_size, prev_page.has_previous_page, prev_page.has_next_page
        );

        for item in &prev_page.items {
            let dt = DateTime::from_timestamp_millis(item.key.timestamp_ms)
                .map(|t| t.format("%Y-%m-%d %H:%M:%S%.3f").to_string())
                .unwrap_or_else(|| "N/A".to_string());

            println!(
                "      [ID {:03}] Key(ts={}, id={}) | {}",
                item.key.id, dt, item.key.id, item.title
            );
        }
    }

    println!("\n[Test de validation de l'intégrité du curseur]");
    let tampered_cursor = "eyJmb28iOiJiYXIifQ";
    match CursorPayload::decode(tampered_cursor) {
        Ok(_) => println!("Erreur: le curseur corrompu a été accepté par erreur !"),
        Err(e) => println!("Protection active : Curseur invalide rejeté avec succès -> {}", e),
    }

    println!("\nSystème exécuté avec succès et sans panique.");
    Ok(())
}

