    Verify(VerifyArgs),

    /// Calcule l'empreinte combinée de tous les fichiers d'un répertoire
    Directory(DirectoryArgs),
}

#[derive(ValueEnum, Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
enum HashAlgorithm {
    Blake3,
    Sha256,
}

impl Default for HashAlgorithm {
    fn default() -> Self {
        HashAlgorithm::Blake3
    }
}

#[derive(Parser, Debug, Clone)]
struct ComputeArgs {
    /// Chemin du fichier de dataset (CSV, TSV, texte plat)
    #[arg(short, long)]
    path: PathBuf,

    /// Algorithme de hachage à utiliser
    #[arg(short, long, value_enum, default_value_t = HashAlgorithm::Blake3)]
    algo: HashAlgorithm,

    /// Séparateur de colonnes (ex: ',', ';', '\t', '|')
    #[arg(short, long, default_value = ",")]
    delimiter: String,

    /// Traiter la première ligne comme un en-tête inclus dans l'empreinte
    #[arg(long, default_value_t = true)]
    has_header: bool,

    /// Rogner les espaces superflus (trim) au début et à la fin de chaque cellule
    #[arg(long, default_value_t = false)]
    trim_cells: bool,

    /// Activer la barre de progression pour les gros fichiers
    #[arg(long, default_value_t = false)]
    progress: bool,

    /// Sortie structurée au format JSON
    #[arg(long, default_value_t = false)]
    json: bool,

    /// Sauvegarder le résultat dans un fichier manifeste JSON
    #[arg(short, long)]
