}

#[derive(Parser, Debug)]
struct VerifyArgs {
    /// Chemin du dataset à vérifier
    #[arg(short, long)]
    path: PathBuf,

    /// Empreinte hexadécimale attendue
    #[arg(short = 'e', long)]
    expected_hash: Option<String>,

    /// Fichier manifeste JSON contenant l'empreinte attendue et la configuration
    #[arg(short, long)]
    manifest: Option<PathBuf>,

    /// Algorithme si spécifié manuellement sans manifeste
    #[arg(short, long, value_enum, default_value_t = HashAlgorithm::Blake3)]
    algo: HashAlgorithm,

    /// Séparateur de colonnes si spécifié manuellement sans manifeste
    #[arg(short, long, default_value = ",")]
    delimiter: String,

    /// Prise en compte du header
    #[arg(long, default_value_t = true)]
