// src/main.rs
use std::fs::File;
use std::io::{BufReader, Read};
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use anyhow::{bail, Context, Result};
use clap::{Parser, Subcommand, ValueEnum};
use console::style;
use indicatif::{ProgressBar, ProgressStyle};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use walkdir::WalkDir;

#[derive(Parser, Debug)]
#[command(
    name = "dataset-fingerprint",
    author = "Damien",
    version,
    about = "Calculateur d'empreintes globales de datasets pour détecter toute altération au niveau cellule/ligne",
    long_about = "Outil haute performance et déterministe pour générer et vérifier les empreintes cryptographiques de jeux de données tabulaires (CSV/TSV) ou répertoires complets."
)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Calcule l'empreinte globale d'un dataset (fichier CSV/TSV ou fichier plat)
    Compute(ComputeArgs),

    /// Vérifie l'intégrité d'un dataset par rapport à une empreinte attendue ou un manifeste
    Verify(VerifyArgs),

    /// Calcule l'empreinte combinée de tous les fichiers d'un répertoire
    Directory(DirectoryArgs),
}

#[derive(ValueEnum, Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
enum HashAlgorithm {
    Blake3,
    Sha256,
}

impl Default for HashAlgorithm {
    fn default() -> Self {
        HashAlgorithm::Blake3
    }
}

#[derive(Parser, Debug, Clone)]
struct ComputeArgs {
    /// Chemin du fichier de dataset (CSV, TSV, texte plat)
    #[arg(short, long)]
    path: PathBuf,

    /// Algorithme de hachage à utiliser
    #[arg(short, long, value_enum, default_value_t = HashAlgorithm::Blake3)]
    algo: HashAlgorithm,

    /// Séparateur de colonnes (ex: ',', ';', '\t', '|')
    #[arg(short, long, default_value = ",")]
    delimiter: String,

    /// Traiter la première ligne comme un en-tête inclus dans l'empreinte
    #[arg(long, default_value_t = true)]
    has_header: bool,

    /// Rogner les espaces superflus (trim) au début et à la fin de chaque cellule
    #[arg(long, default_value_t = false)]
    trim_cells: bool,

    /// Activer la barre de progression pour les gros fichiers
    #[arg(long, default_value_t = false)]
    progress: bool,

    /// Sortie structurée au format JSON
    #[arg(long, default_value_t = false)]
    json: bool,

    /// Sauvegarder le résultat dans un fichier manifeste JSON
    #[arg(short, long)]
    output: Option<PathBuf>,
}

#[derive(Parser, Debug)]
struct VerifyArgs {
    /// Chemin du dataset à vérifier
    #[arg(short, long)]
    path: PathBuf,

    /// Empreinte hexadécimale attendue
    #[arg(short = 'e', long)]
    expected_hash: Option<String>,

    /// Fichier manifeste JSON contenant l'empreinte attendue et la configuration
    #[arg(short, long)]
    manifest: Option<PathBuf>,

    /// Algorithme si spécifié manuellement sans manifeste
    #[arg(short, long, value_enum, default_value_t = HashAlgorithm::Blake3)]
    algo: HashAlgorithm,

    /// Séparateur de colonnes si spécifié manuellement sans manifeste
    #[arg(short, long, default_value = ",")]
    delimiter: String,

    /// Prise en compte du header
    #[arg(long, default_value_t = true)]
    has_header: bool,

    /// Rogner les cellules
    #[arg(long, default_value_t = false)]
    trim_cells: bool,
}

#[derive(Parser, Debug)]
struct DirectoryArgs {
    /// Chemin du répertoire à scanner
    #[arg(short, long)]
    path: PathBuf,

    /// Algorithme de hachage
    #[arg(short, long, value_enum, default_value_t = HashAlgorithm::Blake3)]
    algo: HashAlgorithm,

    /// Sortie au format JSON
    #[arg(long, default_value_t = false)]
    json: bool,
}

/// Manifeste sérialisable représentant le bilan de l'empreinte d'un dataset
#[derive(Debug, Clone, Serialize, Deserialize)]
struct FingerprintManifest {
    version: String,
    target_path: String,
    file_size_bytes: u64,
    algorithm: HashAlgorithm,
    total_rows: u64,
    columns_count: usize,
    has_header: bool,
    header_hash: Option<String>,
    global_fingerprint: String,
}

/// Abstraction unifiée pour les moteurs de hachage
enum HasherEngine {
    Blake3(blake3::Hasher),
    Sha256(Sha256),
}

impl HasherEngine {
    fn new(algo: HashAlgorithm) -> Self {
        match algo {
            HashAlgorithm::Blake3 => Self::Blake3(blake3::Hasher::new()),
            HashAlgorithm::Sha256 => Self::Sha256(Sha256::new()),
        }
    }

    fn update(&mut self, data: &[u8]) {
        match self {
            Self::Blake3(h) => {
                h.update(data);
            }
            Self::Sha256(h) => {
                h.update(data);
            }
        }
    }

    fn finalize_hex(self) -> String {
        match self {
            Self::Blake3(h) => h.finalize().to_hex().to_string(),
            Self::Sha256(h) => hex::encode(h.finalize()),
        }
    }
}

/// Hache de manière canonique une cellule : longueur (u32 big-endian) + octets bruts
fn hash_cell_into(hasher: &mut HasherEngine, cell: &[u8]) {
    let len = cell.len() as u32;
    hasher.update(&len.to_be_bytes());
    hasher.update(cell);
}

/// Hache une ligne entière de manière canonique et déterministe
fn hash_row(fields: &[&[u8]], algo: HashAlgorithm) -> String {
    let mut hasher = HasherEngine::new(algo);
    let col_count = fields.len() as u32;
    hasher.update(&col_count.to_be_bytes());
    for field in fields {
        hash_cell_into(&mut hasher, field);
    }
    hasher.finalize_hex()
}

/// Parse le délimiteur spécifié en octet ASCII
fn parse_delimiter(delim_str: &str) -> Result<u8> {
    if delim_str == "\\t" || delim_str == "\t" {
        return Ok(b'\t');
    }
    let bytes = delim_str.as_bytes();
    if bytes.len() != 1 {
        bail!(
            "Le délimiteur doit être un caractère unique (ex: ',', ';', '\\t', '|'). Fourni: '{}'",
            delim_str
        );
    }
    Ok(bytes[0])
}

/// Calcule l'empreinte globale du dataset tabulaire
fn compute_dataset_fingerprint(args: &ComputeArgs) -> Result<FingerprintManifest> {
    let path = &args.path;
    let file = File::open(path)
        .with_context(|| format!("Impossible d'ouvrir le fichier '{}'", path.display()))?;
    let metadata = file
        .metadata()
        .with_context(|| format!("Impossible de lire les métadonnées de '{}'", path.display()))?;
    let file_size = metadata.len();

    let delim_byte = parse_delimiter(&args.delimiter)?;

    let pb = if args.progress {
        let bar = ProgressBar::new(file_size);
        bar.set_style(
            ProgressStyle::default_bar()
                .template("[{elapsed_precise}] [{bar:40.cyan/blue}] {bytes}/{total_bytes} ({eta})")
                .unwrap_or_else(|_| ProgressStyle::default_bar())
                .progress_chars("#>-"),
        );
        Some(bar)
    } else {
        None
    };

    let buf_reader = BufReader::new(file);
    let mut csv_reader = csv::ReaderBuilder::new()
        .delimiter(delim_byte)
        .has_headers(args.has_header)
        .flexible(true)
        .from_reader(buf_reader);

    let mut global_hasher = HasherEngine::new(args.algo);
    let mut header_hash: Option<String> = None;
    let mut columns_count = 0;

    // Prise en compte de l'en-tête s'il existe
    if args.has_header {
        let headers = csv_reader
            .headers()
            .with_context(|| "Erreur lors de la lecture des en-têtes CSV")?;
        columns_count = headers.len();

        let header_fields: Vec<Vec<u8>> = headers
            .iter()
            .map(|col| {
                if args.trim_cells {
                    col.trim().as_bytes().to_vec()
                } else {
                    col.as_bytes().to_vec()
                }
            })
            .collect();

        let header_slices: Vec<&[u8]> = header_fields.iter().map(|v| v.as_slice()).collect();
        let h_hash = hash_row(&header_slices, args.algo);
        header_hash = Some(h_hash.clone());

        // L'empreinte globale intègre explicitement l'en-tête
        global_hasher.update(b"HEADER:");
        global_hasher.update(h_hash.as_bytes());
        global_hasher.update(b"\n");
    }

    let mut record = csv::ByteRecord::new();
    let mut row_count = 0u64;

    while csv_reader
        .read_byte_record(&mut record)
        .with_context(|| format!("Erreur de lecture à la ligne {}", row_count + 1))?
    {
        row_count += 1;
        if columns_count == 0 {
            columns_count = record.len();
        }

        let fields: Vec<Vec<u8>> = record
            .iter()
            .map(|f| {
                if args.trim_cells {
                    let s = match std::str::from_utf8(f) {
                        Ok(text) => text.trim().as_bytes().to_vec(),
                        Err(_) => f.to_vec(),
                    };
                    s
                } else {
                    f.to_vec()
                }
            })
            .collect();

        let field_slices: Vec<&[u8]> = fields.iter().map(|f| f.as_slice()).collect();
        let row_fingerprint = hash_row(&field_slices, args.algo);

        // Chaînage cryptographique déterministe
        global_hasher.update(row_fingerprint.as_bytes());
        global_hasher.update(b"\n");

        if let Some(ref bar) = pb {
            bar.inc(record.as_slice().len() as u64);
        }
    }

    if let Some(ref bar) = pb {
        bar.finish_with_message("Calcul terminé");
    }

    // Intégration du nombre total de lignes comme facteur terminal
    global_hasher.update(b"TOTAL_ROWS:");
    global_hasher.update(row_count.to_string().as_bytes());

    let global_fingerprint = global_hasher.finalize_hex();

    Ok(FingerprintManifest {
        version: env!("CARGO_PKG_VERSION").to_string(),
        target_path: path.to_string_lossy().to_string(),
        file_size_bytes: file_size,
        algorithm: args.algo,
        total_rows: row_count,
        columns_count,
        has_header: args.has_header,
        header_hash,
        global_fingerprint,
    })
}

/// Calcule l'empreinte combinée d'une arborescence de fichiers
fn compute_directory_fingerprint(
    dir_path: &Path,
    algo: HashAlgorithm,
) -> Result<(String, usize, u64)> {
    let mut file_entries = Vec::new();

    for entry in WalkDir::new(dir_path).sort_by_file_name() {
        let entry = entry.with_context(|| "Erreur lors du parcours du répertoire")?;
        if entry.file_type().is_file() {
            file_entries.push(entry.into_path());
        }
    }

    file_entries.sort();

    let mut global_hasher = HasherEngine::new(algo);
    let mut total_bytes = 0u64;

    for path in &file_entries {
        let rel_path = path
            .strip_prefix(dir_path)
            .unwrap_or(path)
            .to_string_lossy();

        global_hasher.update(b"PATH:");
        global_hasher.update(rel_path.as_bytes());
        global_hasher.update(b"\n");

        let mut file = File::open(path)
            .with_context(|| format!("Impossible d'ouvrir le fichier '{}'", path.display()))?;
        let mut buffer = [0u8; 64 * 1024];
        let mut file_hasher = HasherEngine::new(algo);

        loop {
            let n = file
                .read(&mut buffer)
                .with_context(|| format!("Erreur lors de la lecture de '{}'", path.display()))?;
            if n == 0 {
                break;
            }
            total_bytes += n as u64;
            file_hasher.update(&buffer[..n]);
        }

        let file_hash = file_hasher.finalize_hex();
        global_hasher.update(file_hash.as_bytes());
        global_hasher.update(b"\n");
    }

    let files_count = file_entries.len();
    Ok((global_hasher.finalize_hex(), files_count, total_bytes))
}

fn run() -> Result<bool> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Compute(args) => {
            let manifest = compute_dataset_fingerprint(&args)?;

            if let Some(ref out_path) = args.output {
