                        args.trim_cells,
                    )
                } else {
                    bail!("Vous devez fournir soit --expected-hash (-e), soit un fichier --manifest (-m).");
                };

            let compute_args = ComputeArgs {
                path: args.path.clone(),
                algo,
                delimiter,
                has_header,
                trim_cells,
                progress: false,
                json: false,
                output: None,
