// src/main.rs
use std::fs::File;
use std::hash::Hasher;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::Instant;

use anyhow::{bail, Context, Result};
use arrow::array::{Array, RecordBatch, StringArray};
use arrow::datatypes::{DataType, Field, Schema};
use clap::{Parser, Subcommand};
use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;
use parquet::arrow::ArrowWriter;
use parquet::file::properties::WriterProperties;
use rayon::prelude::*;
use serde::{Deserialize, Serialize};
use twox_hash::XxHash64;
use walkdir::WalkDir;

/// Configuration et structure du Filtre de Bloom pour l'élagage préliminaire.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BloomFilter {
    bit_vec: Vec<u64>,
    num_bits: usize,
    num_hashes: usize,
}

impl BloomFilter {
    /// Initialise un filtre de Bloom dimensionné pour un nombre d'éléments estimé
    /// et un taux de faux positifs cible.
    pub fn new(expected_elements: usize, target_fp_rate: f64) -> Self {
        let expected = expected_elements.max(1) as f64;
        let fp = target_fp_rate.clamp(0.00001, 0.5);

        // Formules optimales standard :
        // m = - (n * ln(p)) / (ln(2)^2)
        // k = (m / n) * ln(2)
        let ln2 = std::f64::consts::LN_2;
        let m = (-(expected * fp.ln()) / (ln2 * ln2)).ceil() as usize;
        let num_bits = m.max(64);
        let num_u64s = (num_bits + 63) / 64;
        let total_bits = num_u64s * 64;

        let k = ((total_bits as f64 / expected) * ln2).round() as usize;
        let num_hashes = k.clamp(1, 30);

        Self {
            bit_vec: vec![0u64; num_u64s],
            num_bits: total_bits,
            num_hashes,
        }
    }

    /// Double-hashing basé sur xxHash64 pour dériver k positions de bits.
    fn get_hash_indices(&self, item: &str) -> Vec<usize> {
        let h1 = {
            let mut hasher = XxHash64::with_seed(0);
            hasher.write(item.as_bytes());
            hasher.finish()
        };
        let h2 = {
            let mut hasher = XxHash64::with_seed(0x9e3779b97f4a7c15);
            hasher.write(item.as_bytes());
            hasher.finish()
        };

        let mut indices = Vec::with_capacity(self.num_hashes);
        for i in 0..self.num_hashes {
            let combined = h1.wrapping_add((i as u64).wrapping_mul(h2));
            indices.push((combined as usize) % self.num_bits);
        }
        indices
    }

    /// Insère un token dans le filtre.
    pub fn insert(&mut self, item: &str) {
        for bit_index in self.get_hash_indices(item) {
            let word_index = bit_index / 64;
            let bit_offset = bit_index % 64;
            self.bit_vec[word_index] |= 1u64 << bit_offset;
        }
    }

    /// Teste si un token est potentiellement présent.
    /// Retourne `false` si le token est définitivement absent (zero faux négatif).
    pub fn contains(&self, item: &str) -> bool {
        for bit_index in self.get_hash_indices(item) {
            let word_index = bit_index / 64;
            let bit_offset = bit_index % 64;
            if (self.bit_vec[word_index] & (1u64 << bit_offset)) == 0 {
                return false;
            }
        }
        true
    }
}

/// Tokeniseur simple et rapide extrayant les termes alphanumériques minuscules.
fn tokenize(text: &str) -> impl Iterator<Item = String> + '_ {
    text.split(|c: char| !c.is_alphanumeric())
        .filter(|t| !t.is_empty())
        .map(|t| t.to_lowercase())
}

/// Entrée d'index associant un fichier Parquet à son filtre de Bloom préliminaire.
#[derive(Debug, Serialize, Deserialize)]
pub struct FileBloomIndex {
    pub file_path: PathBuf,
    pub bloom_filter: BloomFilter,
    pub row_count: usize,
}

/// Index complet regroupant plusieurs fichiers Parquet.
#[derive(Debug, Serialize, Deserialize)]
pub struct CorpusBloomIndex {
    pub entries: Vec<FileBloomIndex>,
}

impl CorpusBloomIndex {
    pub fn save_to_file(&self, path: &Path) -> Result<()> {
        let file = File::create(path)
            .with_context(|| format!("Impossible de créer le fichier d'index {:?}", path))?;
        bincode::serialize_into(file, self)
            .with_context(|| "Erreur lors de la sérialisation de l'index")?;
        Ok(())
    }

    pub fn load_from_file(path: &Path) -> Result<Self> {
        let file = File::open(path)
            .with_context(|| format!("Impossible d'ouvrir le fichier d'index {:?}", path))?;
        let index: Self = bincode::deserialize_from(file)
            .with_context(|| "Erreur lors de la désérialisation de l'index")?;
        Ok(index)
    }
}

/// Analyse un fichier Parquet donné et construit son filtre de Bloom sur les colonnes textuelles.
pub fn build_bloom_for_parquet(path: &Path, target_column: Option<&str>) -> Result<FileBloomIndex> {
    let file = File::open(path)
        .with_context(|| format!("Impossible d'ouvrir le fichier Parquet: {:?}", path))?;
    let builder = ParquetRecordBatchReaderBuilder::try_new(file)?;
    let schema = builder.schema().clone();

    // Détection des colonnes textuelles (Utf8 / LargeUtf8)
    let text_col_indices: Vec<usize> = schema
        .fields()
        .iter()
        .enumerate()
        .filter_map(|(idx, field)| match field.data_type() {
            DataType::Utf8 | DataType::LargeUtf8 => {
                if let Some(col_name) = target_column {
                    if field.name() == col_name {
                        Some(idx)
                    } else {
                        None
                    }
                } else {
                    Some(idx)
                }
            }
            _ => None,
        })
        .collect();

    if text_col_indices.is_empty() {
        bail!(
            "Aucune colonne textuelle trouvée dans {:?} (colonne demandée: {:?})",
            path,
            target_column
        );
    }

    let mut reader = builder.build()?;
    let mut tokens = Vec::new();
    let mut total_rows = 0;

    while let Some(batch_result) = reader.next() {
        let batch: RecordBatch = batch_result?;
        total_rows += batch.num_rows();

        for &col_idx in &text_col_indices {
            let col = batch.column(col_idx);
            if let Some(string_array) = col.as_any().downcast_ref::<StringArray>() {
                for i in 0..string_array.len() {
                    if !string_array.is_null(i) {
                        let text = string_array.value(i);
                        for tok in tokenize(text) {
                            tokens.push(tok);
                        }
                    }
                }
            }
        }
    }

    tokens.sort_unstable();
    tokens.dedup();

    let mut bloom = BloomFilter::new(tokens.len(), 0.01);
    for t in tokens {
        bloom.insert(&t);
    }

    Ok(FileBloomIndex {
        file_path: path.to_path_buf(),
        bloom_filter: bloom,
        row_count: total_rows,
    })
}

/// Résultat d'une correspondance exacte dans un fichier Parquet.
#[derive(Debug)]
pub struct MatchRecord {
    pub file: PathBuf,
    pub row_index: usize,
    pub column: String,
    pub snippet: String,
}

/// Scanne exactement le fichier Parquet pour localiser les occurrences du mot-clé.
pub fn scan_parquet_exact(
    path: &Path,
    keyword: &str,
    target_column: Option<&str>,
) -> Result<Vec<MatchRecord>> {
    let file = File::open(path)
        .with_context(|| format!("Impossible d'ouvrir le fichier Parquet: {:?}", path))?;
    let builder = ParquetRecordBatchReaderBuilder::try_new(file)?;
    let schema = builder.schema().clone();

    let text_cols: Vec<(usize, String)> = schema
        .fields()
        .iter()
        .enumerate()
        .filter_map(|(idx, field)| match field.data_type() {
            DataType::Utf8 | DataType::LargeUtf8 => {
                if let Some(col_name) = target_column {
                    if field.name() == col_name {
                        Some((idx, field.name().clone()))
                    } else {
                        None
                    }
                } else {
                    Some((idx, field.name().clone()))
                }
            }
            _ => None,
        })
        .collect();

    let mut reader = builder.build()?;
    let mut matches = Vec::new();
    let mut current_row_offset = 0;
    let kw_lower = keyword.to_lowercase();

    while let Some(batch_result) = reader.next() {
        let batch: RecordBatch = batch_result?;
        let batch_rows = batch.num_rows();

        for &(col_idx, ref col_name) in &text_cols {
            let col = batch.column(col_idx);
            if let Some(string_array) = col.as_any().downcast_ref::<StringArray>() {
                for i in 0..string_array.len() {
                    if !string_array.is_null(i) {
                        let text = string_array.value(i);
                        let has_token = tokenize(text).any(|t| t == kw_lower);
                        if has_token {
                            let snippet = if text.len() > 120 {
                                format!("{}...", &text[..120])
                            } else {
                                text.to_string()
                            };

                            matches.push(MatchRecord {
                                file: path.to_path_buf(),
                                row_index: current_row_offset + i,
                                column: col_name.clone(),
                                snippet,
                            });
                        }
                    }
                }
            }
        }

        current_row_offset += batch_rows;
    }

    Ok(matches)
}

/// Génère des fichiers Parquet d'exemple pour tester les performances de recherche et le filtrage Bloom.
pub fn generate_sample_data(output_dir: &Path, count: usize) -> Result<()> {
    std::fs::create_dir_all(output_dir)?;

    let schema = Arc::new(Schema::new(vec![
        Field::new("id", DataType::Int64, false),
        Field::new("title", DataType::Utf8, false),
        Field::new("body", DataType::Utf8, false),
    ]));

    let sample_corpus = [
        ("Architecture distribuée", "Les filtres de Bloom permettent d'éviter les lectures Parquet inutiles sur disque."),
        ("Bases de données analytiques", "Apache Arrow et Parquet offrent une compression en colonnes très efficace."),
        ("Langage Rust", "La sécurité mémoire sans ramasse-miettes garantit d'excellentes performances concurrentes."),
        ("Algorithmes probabilistes", "Un filtre de Bloom a une probabilité paramétrable de faux positifs mais aucun faux négatif."),
        ("Moteur d'indexation", "L'indexation inverse et les sketches de hachage optimisent la recherche fulltext massive."),
    ];

    for file_idx in 0..count {
        let file_path = output_dir.join(format!("dataset_part_{:03}.parquet", file_idx));
        let file = File::create(&file_path)?;

        let props = WriterProperties::builder().build();
        let mut writer = ArrowWriter::try_new(file, schema.clone(), Some(props))?;

        let mut ids = Vec::new();
        let mut titles = Vec::new();
        let mut bodies = Vec::new();

        for i in 0..100 {
            let row_id = (file_idx * 100 + i) as i64;
            let (title, base_body) = sample_corpus[(file_idx + i) % sample_corpus.len()];
            ids.push(row_id);
            titles.push(format!("{} (doc #{})", title, row_id));
            bodies.push(format!("{} [tag: doc_{}]", base_body, row_id));
        }

        let id_array = Arc::new(arrow::array::Int64Array::from(ids)) as Arc<dyn Array>;
        let title_array = Arc::new(arrow::array::StringArray::from(titles)) as Arc<dyn Array>;
        let body_array = Arc::new(arrow::array::StringArray::from(bodies)) as Arc<dyn Array>;

        let batch = RecordBatch::try_new(
            schema.clone(),
            vec![id_array, title_array, body_array],
        )?;

        writer.write(&batch)?;
        writer.close()?;
        println!("Fichier d'exemple généré : {:?}", file_path);
    }

    Ok(())
}

