// OUTIL DE SÉRIALISATION RAPIDE (pour démonstration & tests)
// -------------------------------------------------------------

pub struct ProtoEncoder;

impl ProtoEncoder {
    pub fn write_varint(buf: &mut Vec<u8>, mut val: u64) {
        while val >= 0x80 {
            buf.push(((val & 0x7F) as u8) | 0x80);
            val >>= 7;
        }
        buf.push((val & 0x7F) as u8);
    }

    pub fn write_tag(buf: &mut Vec<u8>, tag: u32, wire_type: WireType) {
        let key = ((tag as u64) << 3) | (wire_type as u64);
        Self::write_varint(buf, key);
    }

    pub fn encode_uint64(buf: &mut Vec<u8>, tag: u32, val: u64) {
        Self::write_tag(buf, tag, WireType::Varint);
        Self::write_varint(buf, val);
    }

    pub fn encode_bool(buf: &mut Vec<u8>, tag: u32, val: bool) {
        Self::write_tag(buf, tag, WireType::Varint);
        Self::write_varint(buf, if val { 1 } else { 0 });
    }

    pub fn encode_string(buf: &mut Vec<u8>, tag: u32, val: &str) {
        Self::write_tag(buf, tag, WireType::LengthDelimited);
        Self::write_varint(buf, val.len() as u64);
        buf.extend_from_slice(val.as_bytes());
    }

    pub fn encode_bytes(buf: &mut Vec<u8>, tag: u32, bytes: &[u8]) {
        Self::write_tag(buf, tag, WireType::LengthDelimited);
        Self::write_varint(buf, bytes.len() as u64);
        buf.extend_from_slice(bytes);
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("=== Convertisseur Protobuf vers JSON sans générateur de code ===\n");

    // 1. Définition du schéma .proto
    let proto_schema_str = r#"
        syntax = "proto3";

        message Address {
            string street = 1;
            string city = 2;
        }

        message UserProfile {
            int64 id = 1;
            string name = 2;
            bool is_active = 3;
            Address address = 4;
            repeated string roles = 5;
        }
    "#;

    println!("1. Parsing du schéma .proto dynamique...");
    let schema = ProtoSchema::parse(proto_schema_str)?;
    println!("   Messages analysés : {:?}\n", schema.messages.keys().collect::<Vec<_>>());

    // 2. Création d'un payload binaire protobuf (simulant des données reçues via réseau)
    let mut address_buf = Vec::new();
    ProtoEncoder::encode_string(&mut address_buf, 1, "10 rue de la Paix");
    ProtoEncoder::encode_string(&mut address_buf, 2, "Paris");

    let mut user_buf = Vec::new();
    ProtoEncoder::encode_uint64(&mut user_buf, 1, 42);
    ProtoEncoder::encode_string(&mut user_buf, 2, "Alice Bob");
    ProtoEncoder::encode_bool(&mut user_buf, 3, true);
    ProtoEncoder::encode_bytes(&mut user_buf, 4, &address_buf);
    ProtoEncoder::encode_string(&mut user_buf, 5, "ADMIN");
    ProtoEncoder::encode_string(&mut user_buf, 5, "DEVELOPER");

    println!("2. Payload binaire généré : {} octets", user_buf.len());
    println!("   Hex : {:02x?}\n", user_buf);

    // 3. Décodage Schema-Aware
    println!("3. Conversion Schema-Aware vers JSON pour 'UserProfile' :");
    let json_schema_aware = schema.decode_message("UserProfile", &user_buf)?;
    println!("{}", serde_json::to_string_pretty(&json_schema_aware)?);

    // 4. Décodage Schema-less (Raw)
    println!("\n4. Conversion Schema-Less (Brute sans schéma) :");
    let json_schemaless = decode_raw_message(&user_buf)?;
    println!("{}", serde_json::to_string_pretty(&json_schemaless)?);

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_varint_encode_decode() {
        let mut buf = Vec::new();
        ProtoEncoder::write_varint(&mut buf, 300);
        let mut cursor = 0;
        let decoded = read_varint(&buf, &mut cursor).expect("Décodage varint échoué");
        assert_eq!(decoded, 300);
        assert_eq!(cursor, buf.len());
    }

    #[test]
    fn test_nested_message_decoding() {
        let proto_def = r#"
            message Item {
                int64 id = 1;
                string label = 2;
            }
            message Order {
                int64 order_id = 1;
                Item item = 2;
            }
        "#;

        let schema = ProtoSchema::parse(proto_def).expect("Parse schema");

        let mut item_buf = Vec::new();
        ProtoEncoder::encode_uint64(&mut item_buf, 1, 999);
        ProtoEncoder::encode_string(&mut item_buf, 2, "Clavier Rust");

        let mut order_buf = Vec::new();
        ProtoEncoder::encode_uint64(&mut order_buf, 1, 12345);
        ProtoEncoder::encode_bytes(&mut order_buf, 2, &item_buf);

        let json = schema.decode_message("Order", &order_buf).expect("Decode order");
        assert_eq!(json["order_id"], 12345);
        assert_eq!(json["item"]["id"], 999);
        assert_eq!(json["item"]["label"], "Clavier Rust");
    }

    #[test]
    fn test_repeated_fields() {
        let proto_def = r#"
            message Batch {
                repeated string tags = 1;
            }
        "#;
        let schema = ProtoSchema::parse(proto_def).expect("Parse schema");

        let mut buf = Vec::new();
        ProtoEncoder::encode_string(&mut buf, 1, "tagA");
        ProtoEncoder::encode_string(&mut buf, 1, "tagB");
        ProtoEncoder::encode_string(&mut buf, 1, "tagC");

        let json = schema.decode_message("Batch", &buf).expect("Decode batch");
        let array = json["tags"].as_array().expect("Array attendu");
        assert_eq!(array.len(), 3);
        assert_eq!(array[0], "tagA");
        assert_eq!(array[1], "tagB");
        assert_eq!(array[2], "tagC");
    }
}

