```rust
// src/main.rs
use std::collections::HashMap;
use thiserror::Error;

#[derive(Error, Debug)]
pub enum ProtoError {
    #[error("Erreur de décodage binaire : {0}")]
    WireDecodeError(String),
    #[error("Erreur d'analyse de schéma : {0}")]
    SchemaParseError(String),
    #[error("Fin de flux inattendue")]
    UnexpectedEof,
    #[error("Varint trop long (> 10 octets)")]
    VarintOverflow,
    #[error("Wire type inconnu : {0}")]
    UnknownWireType(u8),
    #[error("Erreur de conversion de type : {0}")]
    TypeConversionError(String),
}

/// Types de wire natifs Protobuf
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WireType {
    Varint = 0,
    Fixed64 = 1,
    LengthDelimited = 2,
    StartGroup = 3,
    EndGroup = 4,
    Fixed32 = 5,
}

impl WireType {
    pub fn from_u8(value: u8) -> Result<Self, ProtoError> {
        match value {
            0 => Ok(WireType::Varint),
            1 => Ok(WireType::Fixed64),
            2 => Ok(WireType::LengthDelimited),
            3 => Ok(WireType::StartGroup),
            4 => Ok(WireType::EndGroup),
            5 => Ok(WireType::Fixed32),
            other => Err(ProtoError::UnknownWireType(other)),
        }
    }
}

/// Valeur brute décodée selon le wire format
#[derive(Debug, Clone, PartialEq)]
pub enum RawFieldValue {
    Varint(u64),
    Fixed64(u64),
    LengthDelimited(Vec<u8>),
    Fixed32(u32),
}

/// Décode un Varint (LEB128) depuis un curseur d'octets
pub fn read_varint(data: &[u8], cursor: &mut usize) -> Result<u64, ProtoError> {
    let mut result: u64 = 0;
    let mut shift = 0;

    while *cursor < data.len() {
        let byte = data[*cursor];
        *cursor += 1;

        result |= ((byte & 0x7F) as u64) << shift;

        if (byte & 0x80) == 0 {
            return Ok(result);
        }

        shift += 7;
        if shift >= 64 {
            return Err(ProtoError::VarintOverflow);
        }
    }

    Err(ProtoError::UnexpectedEof)
}

/// Lit la clé de champ (tag + wire type)
pub fn read_tag_and_wire(data: &[u8], cursor: &mut usize) -> Result<(u32, WireType), ProtoError> {
    let key = read_varint(data, cursor)?;
    let tag = (key >> 3) as u32;
    let wire_type = WireType::from_u8((key & 0x07) as u8)?;
    Ok((tag, wire_type))
}

/// Décode un champ brut
pub fn read_raw_field(data: &[u8], cursor: &mut usize, wire_type: WireType) -> Result<RawFieldValue, ProtoError> {
    match wire_type {
        WireType::Varint => {
            let val = read_varint(data, cursor)?;
            Ok(RawFieldValue::Varint(val))
        }
        WireType::Fixed64 => {
            if *cursor + 8 > data.len() {
                return Err(ProtoError::UnexpectedEof);
            }
            let slice: [u8; 8] = match data[*cursor..*cursor + 8].try_into() {
                Ok(arr) => arr,
                Err(_) => return Err(ProtoError::WireDecodeError("Taille invalide pour Fixed64".to_string())),
            };
            *cursor += 8;
            Ok(RawFieldValue::Fixed64(u64::from_le_bytes(slice)))
        }
        WireType::LengthDelimited => {
            let length = read_varint(data, cursor)? as usize;
            if *cursor + length > data.len() {
                return Err(ProtoError::UnexpectedEof);
            }
            let bytes = data[*cursor..*cursor + length].to_vec();
            *cursor += length;
            Ok(RawFieldValue::LengthDelimited(bytes))
        }
        WireType::Fixed32 => {
            if *cursor + 4 > data.len() {
                return Err(ProtoError::UnexpectedEof);
            }
            let slice: [u8; 4] = match data[*cursor..*cursor + 4].try_into() {
                Ok(arr) => arr,
                Err(_) => return Err(ProtoError::WireDecodeError("Taille invalide pour Fixed32".to_string())),
            };
            *cursor += 4;
            Ok(RawFieldValue::Fixed32(u32::from_le_bytes(slice)))
        }
        WireType::StartGroup | WireType::EndGroup => {
            Err(ProtoError::WireDecodeError("Groupes dépréciés non supportés".to_string()))
        }
    }
}

/// Décodage brut de l'ensemble d'un message sans schéma
pub fn decode_raw_message(data: &[u8]) -> Result<serde_json::Value, ProtoError> {
    let mut cursor = 0;
    let mut fields: HashMap<String, Vec<serde_json::Value>> = HashMap::new();

    while cursor < data.len() {
        let (tag, wire_type) = read_tag_and_wire(data, &mut cursor)?;
        let raw_val = read_raw_field(data, &mut cursor, wire_type)?;

        let json_val = match raw_val {
            RawFieldValue::Varint(v) => serde_json::Value::from(v),
            RawFieldValue::Fixed64(v) => serde_json::Value::from(v),
            RawFieldValue::Fixed32(v) => serde_json::Value::from(v),
            RawFieldValue::LengthDelimited(bytes) => {
                // Si la séquence est une chaîne UTF-8 valide et lisible, on la traite comme string
                if let Ok(s) = std::str::from_utf8(&bytes) {
                    if s.chars().all(|c| !c.is_control() || c == '\n' || c == '\r' || c == '\t') {
                        serde_json::Value::from(s)
                    } else if let Ok(nested_json) = decode_raw_message(&bytes) {
                        nested_json
                    } else {
                        serde_json::Value::from(bytes)
                    }
                } else if let Ok(nested_json) = decode_raw_message(&bytes) {
                    nested_json
                } else {
                    serde_json::Value::from(bytes)
                }
            }
        };

        let field_key = format!("field_{}", tag);
        fields.entry(field_key).or_default().push(json_val);
    }

    let mut map = serde_json::Map::new();
    for (k, mut vals) in fields {
        if vals.len() == 1 {
            map.insert(k, vals.remove(0));
        } else {
            map.insert(k, serde_json::Value::Array(vals));
        }
    }

    Ok(serde_json::Value::Object(map))
}

// -------------------------------------------------------------
// ANALYSEUR ET REPRÉSENTATION DU SCHÉMA SIMPLIFIÉ (.proto)
// -------------------------------------------------------------

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FieldType {
    Int32,
    Int64,
    Uint32,
    Uint64,
    Sint32,
    Sint64,
    Bool,
    String,
    Bytes,
    Float,
    Double,
    Message(String),
}

impl FieldType {
    pub fn parse(s: &str) -> Self {
        match s {
            "int32" => FieldType::Int32,
            "int64" => FieldType::Int64,
            "uint32" => FieldType::Uint32,
            "uint64" => FieldType::Uint64,
            "sint32" => FieldType::Sint32,
            "sint64" => FieldType::Sint64,
            "bool" => FieldType::Bool,
            "string" => FieldType::String,
            "bytes" => FieldType::Bytes,
            "float" => FieldType::Float,
            "double" => FieldType::Double,
            custom => FieldType::Message(custom.to_string()),
        }
    }
}

#[derive(Debug, Clone)]
pub struct FieldDef {
    pub name: String,
    pub tag: u32,
    pub field_type: FieldType,
    pub repeated: bool,
}

#[derive(Debug, Default, Clone)]
pub struct MessageDef {
    pub name: String,
    pub fields_by_tag: HashMap<u32, FieldDef>,
}

#[derive(Debug, Default, Clone)]
pub struct ProtoSchema {
    pub messages: HashMap<String, MessageDef>,
}

impl ProtoSchema {
    /// Analyseur simpliste de schéma .proto
    pub fn parse(proto_text: &str) -> Result<Self, ProtoError> {
        let mut schema = ProtoSchema::default();
        let mut current_message: Option<MessageDef> = None;

        for line in proto_text.lines() {
            let line = line.trim();
            // Retrait des commentaires simples
            let line = if let Some(idx) = line.find("//") {
                line[..idx].trim()
            } else {
                line
            };

            if line.is_empty() || line.starts_with("syntax") || line.starts_with("package") {
                continue;
            }

            if line.starts_with("message ") {
                let parts: Vec<&str> = line.split_whitespace().collect();
                if parts.len() >= 2 {
                    let msg_name = parts[1].trim_end_matches('{').trim().to_string();
                    current_message = Some(MessageDef {
                        name: msg_name,
                        fields_by_tag: HashMap::new(),
                    });
                }
            } else if line == "}" {
                if let Some(msg) = current_message.take() {
                    schema.messages.insert(msg.name.clone(), msg);
                }
            } else if let Some(ref mut msg) = current_message {
                // Définition de champ: [repeated|optional] <type> <name> = <tag>;
                let line = line.trim_end_matches(';').trim();
                let tokens: Vec<&str> = line.split_whitespace().collect();
                if tokens.len() >= 4 && tokens.contains(&"=") {
                    let mut idx = 0;
                    let repeated = if tokens[idx] == "repeated" {
                        idx += 1;
                        true
                    } else {
                        if tokens[idx] == "optional" {
                            idx += 1;
                        }
                        false
                    };

                    let type_str = tokens[idx];
                    let field_name = tokens[idx + 1];
                    let tag_str = tokens[tokens.len() - 1];

                    let tag: u32 = tag_str.parse().map_err(|_| {
                        ProtoError::SchemaParseError(format!(
                            "Tag invalide '{}' pour le champ '{}'",
                            tag_str, field_name
                        ))
                    })?;

                    let field_def = FieldDef {
                        name: field_name.to_string(),
                        tag,
                        field_type: FieldType::parse(type_str),
                        repeated,
                    };

                    msg.fields_by_tag.insert(tag, field_def);
                }
            }
        }

        if let Some(msg) = current_message {
            schema.messages.insert(msg.name.clone(), msg);
        }

        Ok(schema)
    }

    /// Décode un flux binaire selon un message de ce schéma
    pub fn decode_message(&self, message_name: &str, data: &[u8]) -> Result<serde_json::Value, ProtoError> {
        let msg_def = self.messages.get(message_name).ok_or_else(|| {
            ProtoError::SchemaParseError(format!("Message '{}' introuvable dans le schéma", message_name))
        })?;

        let mut cursor = 0;
        let mut fields: HashMap<String, (bool, Vec<serde_json::Value>)> = HashMap::new();

        while cursor < data.len() {
            let (tag, wire_type) = read_tag_and_wire(data, &mut cursor)?;
            let raw_val = read_raw_field(data, &mut cursor, wire_type)?;

            if let Some(field_def) = msg_def.fields_by_tag.get(&tag) {
                let json_val = self.convert_field_value(&raw_val, &field_def.field_type)?;
                let entry = fields
                    .entry(field_def.name.clone())
                    .or_insert_with(|| (field_def.repeated, Vec::new()));
                entry.1.push(json_val);
            } else {
                // Champ inconnu dans le schéma -> fallback dynamique
                let fallback_name = format!("field_{}", tag);
                let json_val = match raw_val {
                    RawFieldValue::Varint(v) => serde_json::Value::from(v),
                    RawFieldValue::Fixed64(v) => serde_json::Value::from(v),
                    RawFieldValue::Fixed32(v) => serde_json::Value::from(v),
                    RawFieldValue::LengthDelimited(b) => {
                        if let Ok(s) = std::str::from_utf8(&b) {
                            serde_json::Value::from(s)
                        } else {
                            serde_json::Value::from(b)
                        }
                    }
                };
                let entry = fields.entry(fallback_name).or_insert_with(|| (false, Vec::new()));
                entry.1.push(json_val);
            }
        }

        let mut obj = serde_json::Map::new();
        for (field_name, (is_repeated, vals)) in fields {
            if is_repeated {
                obj.insert(field_name, serde_json::Value::Array(vals));
            } else if let Some(last) = vals.into_iter().last() {
                obj.insert(field_name, last);
            }
        }

        Ok(serde_json::Value::Object(obj))
    }

    fn convert_field_value(
        &self,
        raw: &RawFieldValue,
        target_type: &FieldType,
    ) -> Result<serde_json::Value, ProtoError> {
        match (raw, target_type) {
            (RawFieldValue::Varint(v), FieldType::Bool) => Ok(serde_json::Value::Bool(*v != 0)),
            (RawFieldValue::Varint(v), FieldType::Int32 | FieldType::Int64) => {
                Ok(serde_json::Value::from(*v as i64))
            }
            (RawFieldValue::Varint(v), FieldType::Uint32 | FieldType::Uint64) => {
                Ok(serde_json::Value::from(*v))
            }
            (RawFieldValue::Varint(v), FieldType::Sint32) => {
                // Zigzag decode
                let decoded = ((v >> 1) as i32) ^ (-((v & 1) as i32));
                Ok(serde_json::Value::from(decoded))
            }
            (RawFieldValue::Varint(v), FieldType::Sint64) => {
                // Zigzag decode
                let decoded = ((v >> 1) as i64) ^ (-((v & 1) as i64));
                Ok(serde_json::Value::from(decoded))
            }
            (RawFieldValue::Fixed32(v), FieldType::Float) => {
                let float_val = f32::from_bits(*v);
                serde_json::Number::from_f64(float_val as f64)
                    .map(serde_json::Value::Number)
                    .ok_or_else(|| ProtoError::TypeConversionError("Valeur flottante float invalide/NaN".to_string()))
            }
            (RawFieldValue::Fixed64(v), FieldType::Double) => {
                let double_val = f64::from_bits(*v);
                serde_json::Number::from_f64(double_val)
                    .map(serde_json::Value::Number)
                    .ok_or_else(|| ProtoError::TypeConversionError("Valeur flottante double invalide/NaN".to_string()))
            }
            (RawFieldValue::LengthDelimited(bytes), FieldType::String) => {
                let s = std::str::from_utf8(bytes).map_err(|e| {
                    ProtoError::TypeConversionError(format!("Erreur encodage UTF-8: {}", e))
                })?;
                Ok(serde_json::Value::String(s.to_string()))
            }
            (RawFieldValue::LengthDelimited(bytes), FieldType::Bytes) => {
                let hex_str: String = bytes.iter().map(|b| format!("{:02x}", b)).collect();
                Ok(serde_json::Value::String(format!("0x{}", hex_str)))
            }
            (RawFieldValue::LengthDelimited(bytes), FieldType::Message(nested_msg_name)) => {
                self.decode_message(nested_msg_name, bytes)
            }
            _ => Err(ProtoError::TypeConversionError(format!(
                "Incompatibilité entre la valeur wire {:?} et le type attendu {:?}",
                raw, target_type
            ))),
        }
    }
}

