```rust
// src/main.rs
use std::fs::{self, File};
use std::io::{BufRead, BufReader};
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::{Duration, SystemTime};

use arrow::array::{ArrayRef, BinaryArray, RecordBatch, StringArray, UInt64Array};
use arrow::datatypes::{DataType, Field, Schema};
use clap::{Parser, ValueEnum};
use parquet::basic::Compression;
use parquet::file::properties::WriterProperties;
use parquet::arrow::ArrowWriter;
use thiserror::Error;
use tracing::{debug, error, info, warn};
use walkdir::WalkDir;

/// Type d'encodage selon le format du fichier source
#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
pub enum FileFormatMode {
    /// Détection automatique basée sur l'extension du fichier
    Auto,
    /// Archivage ligne par ligne (idéal pour .log, .txt)
    TextLines,
    /// Archivage brut en binaire (stocke les métadonnées et le blob complet)
    RawBinary,
}

/// Algorithme de compression Parquet supporté
#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
pub enum CompressionCodec {
    Zstd,
    Snappy,
    Gzip,
    Uncompressed,
}

impl From<CompressionCodec> for Compression {
    fn from(codec: CompressionCodec) -> Self {
        match codec {
            CompressionCodec::Zstd => Compression::ZSTD(Default::default()),
            CompressionCodec::Snappy => Compression::SNAPPY,
            CompressionCodec::Gzip => Compression::GZIP(Default::default()),
            CompressionCodec::Uncompressed => Compression::UNCOMPRESSED,
        }
    }
}

/// Service d'archivage automatique compressant les fichiers anciens en Parquet et purgeant les originaux.
#[derive(Parser, Debug)]
#[command(
    name = "parquet-archiver",
    about = "Archive automatiquement les fichiers anciens au format Parquet et purge les sources",
    version
)]
pub struct CliArgs {
    /// Répertoire source contenant les fichiers à archiver
    #[arg(short = 's', long, default_value = "./data/incoming")]
    pub source_dir: PathBuf,

    /// Répertoire de destination pour les fichiers Parquet compressés
    #[arg(short = 'd', long, default_value = "./data/archive")]
    pub archive_dir: PathBuf,

    /// Âge minimal d'inactivité avant archivage (ex: '24h', '7d', '30m', '10s')
    #[arg(short = 'a', long, default_value = "7d", value_parser = humantime::parse_duration)]
    pub older_than: Duration,

    /// Algorithme de compression pour les colonnes Parquet
    #[arg(long, value_enum, default_value = "zstd")]
    pub compression: CompressionCodec,

    /// Mode d'encodage pour l'archivage
    #[arg(long, value_enum, default_value = "auto")]
    pub format_mode: FileFormatMode,

    /// Exécute en mode démon avec surveillance périodique
    #[arg(long)]
    pub daemon: bool,

    /// Intervalle de scrutation en mode démon (ex: '60s', '5m', '1h')
    #[arg(long, default_value = "60s", value_parser = humantime::parse_duration)]
    pub interval: Duration,

    /// Simulation sans modification ni suppression de fichiers
    #[arg(long)]
    pub dry_run: bool,

    /// Parcours récursif des sous-répertoires
    #[arg(long, default_value_t = true)]
    pub recursive: bool,

    /// Extensions autorisées à l'archivage, séparées par des virgules (ex: 'log,txt,json,csv')
    #[arg(long, value_delimiter = ',')]
    pub allowed_extensions: Option<Vec<String>>,
}

#[derive(Debug, Error)]
pub enum ArchiverError {
    #[error("Erreur d'accès E/S : {0}")]
    Io(#[from] std::io::Error),

    #[error("Erreur de conversion Arrow : {0}")]
    Arrow(#[from] arrow::error::ArrowError),

    #[error("Erreur Parquet : {0}")]
    Parquet(#[from] parquet::errors::ParquetError),

    #[error("Répertoire invalide : {0}")]
    InvalidDirectory(String),

    #[error("Fichier corrompu ou inaccessible : {0}")]
    CorruptedFile(String),
}

/// Résumé des opérations d'un cycle d'archivage
#[derive(Debug, Default)]
pub struct ArchivalMetrics {
    pub files_scanned: usize,
    pub files_archived: usize,
    pub original_bytes_purged: u64,
    pub compressed_bytes_written: u64,
    pub errors_encountered: usize,
}

impl ArchivalMetrics {
    pub fn display_summary(&self) {
        let savings_ratio = if self.original_bytes_purged > 0 {
            let saved = self.original_bytes_purged.saturating_sub(self.compressed_bytes_written);
            (saved as f64 / self.original_bytes_purged as f64) * 100.0
        } else {
            0.0
        };

        info!(
            "Bilan d'archivage : Fichiers inspectés={}, Archivés={}, Erreurs={}, Poids original={} o, Poids compressé={} o (Gain d'espace: {:.2}%)",
            self.files_scanned,
            self.files_archived,
            self.errors_encountered,
            self.original_bytes_purged,
            self.compressed_bytes_written,
            savings_ratio
        );
    }
}

/// Moteur principal d'archivage
pub struct ArchiverEngine {
    config: CliArgs,
}

impl ArchiverEngine {
    pub fn new(config: CliArgs) -> Self {
        Self { config }
    }

    /// Prépare les répertoires nécessaires
    pub fn init_directories(&self) -> Result<(), ArchiverError> {
        if !self.config.source_dir.exists() {
            info!("Création du répertoire source : {:?}", self.config.source_dir);
            fs::create_dir_all(&self.config.source_dir)?;
        }
        if !self.config.archive_dir.exists() {
            info!("Création du répertoire d'archivage : {:?}", self.config.archive_dir);
            fs::create_dir_all(&self.config.archive_dir)?;
        }
        Ok(())
    }

    /// Filtre d'éligibilité d'un fichier à l'archivage
    pub fn is_file_eligible(&self, path: &Path, now: SystemTime) -> Result<bool, ArchiverError> {
        if !path.is_file() {
            return Ok(false);
        }

        // Ignorer les fichiers temporaires et les archives existantes
        if let Some(ext) = path.extension().and_then(|e| e.to_str()) {
            if ext.eq_ignore_ascii_case("parquet")
                || ext.eq_ignore_ascii_case("tmp")
                || ext.eq_ignore_ascii_case("part")
                || ext.eq_ignore_ascii_case("lock")
            {
                return Ok(false);
            }

            if let Some(allowed) = &self.config.allowed_extensions {
                let matches = allowed.iter().any(|allowed_ext| ext.eq_ignore_ascii_case(allowed_ext));
                if !matches {
                    return Ok(false);
                }
            }
        } else if self.config.allowed_extensions.is_some() {
            // Pas d'extension et une liste blanche d'extensions est configurée
            return Ok(false);
        }

        let metadata = match fs::metadata(path) {
            Ok(m) => m,
            Err(e) => {
                debug!("Impossible de lire les métadonnées de {:?}: {}", path, e);
                return Ok(false);
            }
        };

        // Ignorer les fichiers vides (évite les fichiers en cours d'allocation ou orphelins)
        if metadata.len() == 0 {
            return Ok(false);
        }

        let modified_time = metadata.modified().unwrap_or(SystemTime::UNIX_EPOCH);
        match now.duration_since(modified_time) {
            Ok(age) => Ok(age >= self.config.older_than),
            Err(_) => {
                // Fichier daté dans le futur, ne pas archiver
                Ok(false)
            }
        }
    }

    /// Exécute un cycle complet de scrutation, compression et purge
    pub fn run_cycle(&self) -> Result<ArchivalMetrics, ArchiverError> {
        let mut metrics = ArchivalMetrics::default();
        let now = SystemTime::now();

        let walker = WalkDir::new(&self.config.source_dir)
            .max_depth(if self.config.recursive { usize::MAX } else { 1 })
            .into_iter();

        for entry_res in walker {
            let entry = match entry_res {
                Ok(e) => e,
                Err(err) => {
                    warn!("Erreur lors du parcours du répertoire : {}", err);
                    metrics.errors_encountered += 1;
                    continue;
                }
            };

            let path = entry.path();
            if path.is_dir() {
                continue;
            }

            metrics.files_scanned += 1;

            match self.is_file_eligible(path, now) {
                Ok(true) => {
                    info!("Fichier éligible à l'archivage : {:?}", path);
                    if self.config.dry_run {
                        let original_size = fs::metadata(path).map(|m| m.len()).unwrap_or(0);
                        metrics.files_archived += 1;
                        metrics.original_bytes_purged += original_size;
                        info!("[DRY-RUN] Le fichier {:?} ({} octets) serait compressé en Parquet et purgé.", path, original_size);
                        continue;
                    }

                    match self.archive_and_purge_file(path) {
                        Ok((original_size, compressed_size)) => {
                            metrics.files_archived += 1;
                            metrics.original_bytes_purged += original_size;
                            metrics.compressed_bytes_written += compressed_size;
                            info!(
                                "Fichier archivé et purgé avec succès : {:?} (Original: {} o -> Parquet: {} o)",
                                path, original_size, compressed_size
                            );
                        }
                        Err(err) => {
                            error!("Échec d'archivage pour {:?} : {}", path, err);
                            metrics.errors_encountered += 1;
                        }
                    }
                }
                Ok(false) => {
                    debug!("Fichier ignoré (critères non remplis) : {:?}", path);
                }
                Err(err) => {
                    warn!("Erreur d'analyse pour le fichier {:?} : {}", path, err);
                    metrics.errors_encountered += 1;
                }
            }
        }

        Ok(metrics)
    }

    /// Compresse un fichier source en Parquet de façon atomique puis purge l'original
    fn archive_and_purge_file(&self, source_path: &Path) -> Result<(u64, u64), ArchiverError> {
        let metadata = fs::metadata(source_path)?;
        let original_size = metadata.len();

        // Construction du chemin de destination pour l'archive Parquet
        let relative_path = source_path
            .strip_prefix(&self.config.source_dir)
            .unwrap_or(source_path);

        let mut target_parquet_path = self.config.archive_dir.join(relative_path);
        // Ajout de l'extension .parquet
        let new_filename = format!(
            "{}.parquet",
            target_parquet_path
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or("archive")
        );
        target_parquet_path.set_file_name(new_filename);

        // Assurer l'existence du sous-répertoire d'archive
        if let Some(parent) = target_parquet_path.parent() {
            fs::create_dir_all(parent)?;
        }

        // Fichier temporaire pour écriture atomique
        let temp_parquet_path = target_parquet_path.with_extension("parquet.tmp");

        // Écriture du fichier Parquet
        let mode = match self.config.format_mode {
            FileFormatMode::Auto => {
                let ext = source_path.extension().and_then(|e| e.to_str()).unwrap_or("");
                if matches!(ext, "log" | "txt" | "csv" | "tsv" | "jsonl" | "ndjson") {
                    FileFormatMode::TextLines
                } else {
                    FileFormatMode::RawBinary
                }
            }
            explicit_mode => explicit_mode,
        };

        let compression = self.config.compression.into();
        let writer_props = WriterProperties::builder()
            .set_compression(compression)
            .build();

        let write_result = match mode {
            FileFormatMode::TextLines => {
                Self::write_text_lines_to_parquet(source_path, &temp_parquet_path, writer_props)
            }
            FileFormatMode::RawBinary | FileFormatMode::Auto => {
                Self::write_raw_binary_to_parquet(source_path, &temp_parquet_path, writer_props)
            }
        };

        if let Err(e) = write_result {
            // Nettoyage du temporaire en cas d'erreur
            let _ = fs::remove_file(&temp_parquet_path);
            return Err(e);
        }

        // Vérification de l'intégrité du fichier généré
        let compressed_metadata = match fs::metadata(&temp_parquet_path) {
            Ok(m) if m.len() > 0 => m,
            Ok(_) => {
                let _ = fs::remove_file(&temp_parquet_path);
                return Err(ArchiverError::CorruptedFile(format!(
                    "Le fichier Parquet temporaire est vide : {:?}",
                    temp_parquet_path
                )));
            }
            Err(e) => {
                let _ = fs::remove_file(&temp_parquet_path);
                return Err(ArchiverError::Io(e));
            }
        };

        let compressed_size = compressed_metadata.len();

        // Remplacement atomique vers le nom définitif
        fs::rename(&temp_parquet_path, &target_parquet_path)?;

        // ÉTAPE CRITIQUE DE SÉCURITÉ :
        // Purge de l'original UNIQUEMENT après validation complète de l'archive
        fs::remove_file(source_path)?;

        Ok((original_size, compressed_size))
    }

    /// Encode un fichier texte ligne par ligne dans un RecordBatch Arrow et écrit en Parquet
    fn write_text_lines_to_parquet(
        source_path: &Path,
        dest_parquet_path: &Path,
        props: WriterProperties,
    ) -> Result<(), ArchiverError> {
        let schema = Arc::new(Schema::new(vec![
            Field::new("line_number", DataType::UInt64, false),
            Field::new("content", DataType::Utf8, false),
            Field::new("file_name", DataType::Utf8, false),
        ]));

        let output_file = File::create(dest_parquet_path)?;
        let mut writer = ArrowWriter::try_new(output_file, schema.clone(), Some(props))?;

        let input_file = File::open(source_path)?;
        let reader = BufReader::new(input_file);
        let file_name_str = source_path
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("unknown");

        const BATCH_SIZE: usize = 10_000;
        let mut line_numbers = Vec::with_capacity(BATCH_SIZE);
        let mut contents = Vec::with_capacity(BATCH_SIZE);
        let mut file_names = Vec::with_capacity(BATCH_SIZE);

        let mut current_line: u64 = 0;

        for line_res in reader.lines() {
            let line = line_res?;
            current_line += 1;

            line_numbers.push(current_line);
            contents.push(line);
            file_names.push(file_name_str.to_string());

            if line_numbers.len() >= BATCH_SIZE {
                let batch = RecordBatch::try_new(
                    schema.clone(),
                    vec![
                        Arc::new(UInt64Array::from(line_numbers.clone())) as ArrayRef,
                        Arc::new(StringArray::from(contents.clone())) as ArrayRef,
                        Arc::new(StringArray::from(file_names.clone())) as ArrayRef,
                    ],
                )?;

                writer.write(&batch)?;
                line_numbers.clear();
                contents.clear();
                file_names.clear();
            }
        }

        // Écrire les lignes restantes
        if !line_numbers.is_empty() {
            let batch = RecordBatch::try_new(
                schema.clone(),
                vec![
                    Arc::new(UInt64Array::from(line_numbers)) as ArrayRef,
                    Arc::new(StringArray::from(contents)) as ArrayRef,
                    Arc::new(StringArray::from(file_names)) as ArrayRef,
                ],
            )?;

            writer.write(&batch)?;
        }

        writer.close()?;
        Ok(())
    }

    /// Encode un fichier brut (binaire ou autre) avec métadonnées dans un RecordBatch Arrow et Parquet
    fn write_raw_binary_to_parquet(
        source_path: &Path,
        dest_parquet_path: &Path,
        props: WriterProperties,
    ) -> Result<(), ArchiverError> {
        let schema = Arc::new(Schema::new(vec![
            Field::new("file_name", DataType::Utf8, false),
            Field::new("payload", DataType::Binary, false),
            Field::new("original_size", DataType::UInt64, false),
        ]));

        let output_file = File::create(dest_parquet_path)?;
        let mut writer = ArrowWriter::try_new(output_file, schema.clone(), Some(props))?;

        let file_name_str = source_path
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("unknown");

        let bytes = fs::read(source_path)?;
        let size = bytes.len() as u64;

        let batch = RecordBatch::try_new(
            schema.clone(),
            vec![
                Arc::new(StringArray::from(vec![file_name_str])) as ArrayRef,
                Arc::new(BinaryArray::from_vec(vec![bytes.as_slice()])) as ArrayRef,
                Arc::new(UInt64Array::from(vec![size])) as ArrayRef,
            ],
        )?;

        writer.write(&batch)?;
        writer.close()?;
        Ok(())
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    let args = CliArgs::parse();
    info!("Démarrage du service d'archivage automatique Parquet");
    info!(
        "Configuration: Source={:?}, Archive={:?}, Retention={:?}, Compression={:?}, Daemon={}",
        args.source_dir, args.archive_dir, args.older_than, args.compression, args.daemon
    );

    let engine = ArchiverEngine::new(args);
    engine.init_directories()?;

    if !engine.config.daemon {
        info!("Exécution en mode ponctuel (one-shot)...");
        let metrics = engine.run_cycle()?;
        metrics.display_summary();
        return Ok(());
    }

    info!(
        "Passage en mode démon avec un intervalle de récurrence de {:?}",
        engine.config.interval
    );

    let running = Arc::new(AtomicBool::new(true));
    let r = running.clone();

    // Gestion propre de l'arrêt (SIGINT / CTRL+C)
    tokio::spawn(async move {
        if let Err(e) = tokio::signal::ctrl_c().await {
            error!("Erreur lors de la capture du signal d'interruption : {}", e);
        }
        info!("Signal d'arrêt reçu, arrêt gracieux du démon...");
        r.store(false, Ordering::SeqCst);
    });

    let mut interval_timer = tokio::time::interval(engine.config.interval);

    while running.load(Ordering::SeqCst) {
        interval_timer.tick().await;

        if !running.load(Ordering::SeqCst) {
            break;
        }

        info!("Lancement d'un cycle périodique d'archivage...");
        match engine.run_cycle() {
            Ok(metrics) => {
                metrics.display_summary();
            }
            Err(e) => {
                error!("Erreur lors de l'exécution du cycle d'archivage : {}", e);
            }
        }
    }

    info!("Service d'archivage arrêté avec succès.");
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;
    use std::io::Write;
    use tempfile::tempdir;

    #[test]
    fn test_is_file_eligible_rules() {
        let temp_dir = tempdir().expect("temp dir creation");
        let base_path = temp_dir.path();

        let engine = ArchiverEngine::new(CliArgs {
            source_dir: base_path.to_path_buf(),
            archive_dir: base_path.join("archive"),
            older_than: Duration::from_secs(60),
            compression: CompressionCodec::Zstd,
            format_mode: FileFormatMode::Auto,
            daemon: false,
            interval: Duration::from_secs(60),
            dry_run: false,
            recursive: true,
            allowed_extensions: Some(vec!["log".to_string(), "txt".to_string()]),
        });

        // 1. Fichier avec extension non autorisée (.json)
        let json_file = base_path.join("data.json");
        fs::write(&json_file, "{\"key\":\"val\"}").expect("write json");
        assert!(!engine.is_file_eligible(&json_file, SystemTime::now()).unwrap());

        // 2. Fichier d'extension .parquet (doit être ignoré pour éviter les ré-archivages)
        let parquet_file = base_path.join("existing.parquet");
        fs::write(&parquet_file, "parquet_bytes").expect("write parquet");
        assert!(!engine.is_file_eligible(&parquet_file, SystemTime::now()).unwrap());

        // 3. Fichier vide (doit être ignoré)
        let empty_log = base_path.join("empty.log");
        File::create(&empty_log).expect("create empty file");
        assert!(!engine.is_file_eligible(&empty_log, SystemTime::now()).unwrap());

        // 4. Fichier récent (âge < older_than 60s)
        let recent_log = base_path.join("recent.log");
        fs::write(&recent_log, "recent content").expect("write recent");
        assert!(!engine.is_file_eligible(&recent_log, SystemTime::now()).unwrap());

        // 5. Fichier ancien (simulé en passant un 'now' futur)
        let future_time = SystemTime::now() + Duration::from_secs(3600);
        assert!(engine.is_file_eligible(&recent_log, future_time).unwrap());
    }

    #[test]
    fn test_full_text_archival_and_purge_cycle() {
        let temp = tempdir().expect("temp dir");
        let source_dir = temp.path().join("source");
        let archive_dir = temp.path().join("archive");

        fs::create_dir_all(&source_dir).expect("create source");
        fs::create_dir_all(&archive_dir).expect("create archive");

        // Fichier log source avec 3 lignes
        let log_file = source_dir.join("application.log");
        {
            let mut f = File::create(&log_file).expect("create log file");
            writeln!(f, "2026-09-27 21:00:00 INFO Starting worker").unwrap();
            writeln!(f, "2026-09-27 21:00:01 WARN High memory usage").unwrap();
            writeln!(f, "2026-09-27 21:00:02 INFO Completed task").unwrap();
            f.flush().unwrap();
        }

        let engine = ArchiverEngine::new(CliArgs {
            source_dir: source_dir.clone(),
            archive_dir: archive_dir.clone(),
            older_than: Duration::from_secs(0), // Tout fichier éligible immédiatement
            compression: CompressionCodec::Snappy,
            format_mode: FileFormatMode::TextLines,
            daemon: false,
            interval: Duration::from_secs(10),
            dry_run: false,
            recursive: true,
            allowed_extensions: None,
        });

        let metrics = engine.run_cycle().expect("run cycle");
        assert_eq!(metrics.files_scanned, 1);
        assert_eq!(metrics.files_archived, 1);
        assert_eq!(metrics.errors_encountered, 0);

        // Vérifier que le fichier source original a bien été purgé
        assert!(!log_file.exists(), "Le fichier original doit avoir été purgé");

        // Vérifier que l'archive Parquet correspondante a été générée
        let expected_parquet = archive_dir.join("application.log.parquet");
        assert!(expected_parquet.exists(), "L'archive Parquet doit exister");
