    #[test]
    fn test_raw_binary_archival_and_purge() {
        let temp = tempdir().expect("temp dir");
        let source_dir = temp.path().join("source_bin");
        let archive_dir = temp.path().join("archive_bin");

        fs::create_dir_all(&source_dir).expect("create source");
        fs::create_dir_all(&archive_dir).expect("create archive");

        let bin_file = source_dir.join("payload.dat");
