        });

        let metrics = engine.run_cycle().expect("run cycle");
        assert_eq!(metrics.files_archived, 1);
        assert!(!bin_file.exists(), "Original binaire doit être purgé");

        let parquet_path = archive_dir.join("payload.dat.parquet");
        assert!(parquet_path.exists());

        let file = File::open(&parquet_path).expect("open parquet");
        let builder = ParquetRecordBatchReaderBuilder::try_new(file).expect("builder");
        let mut reader = builder.build().expect("reader");
        let batch = reader.next().expect("batch").expect("read batch");
        assert_eq!(batch.num_rows(), 1);
    }

    #[test]
    fn test_dry_run_does_not_modify_filesystem() {
        let temp = tempdir().expect("temp dir");
        let source_dir = temp.path().join("source_dry");
        let archive_dir = temp.path().join("archive_dry");

        fs::create_dir_all(&source_dir).expect("create source");
        fs::create_dir_all(&archive_dir).expect("create archive");

        let file_path = source_dir.join("important.log");
        fs::write(&file_path, "important data").expect("write file");

        let engine = ArchiverEngine::new(CliArgs {
            source_dir: source_dir.clone(),
            archive_dir: archive_dir.clone(),
            older_than: Duration::from_secs(0),
            compression: CompressionCodec::Zstd,
            format_mode: FileFormatMode::Auto,
            daemon: false,
            interval: Duration::from_secs(10),
            dry_run: true,
            recursive: true,
            allowed_extensions: None,
        });

        let metrics = engine.run_cycle().expect("dry run cycle");
        assert_eq!(metrics.files_archived, 1);
        assert_eq!(metrics.compressed_bytes_written, 0);

        // L'original ne doit PAS être supprimé en dry-run
        assert!(file_path.exists());
        // L'archive ne doit PAS être créée en dry-run
        let archive_file = archive_dir.join("important.log.parquet");
        assert!(!archive_file.exists());
    }
