// src/main.rs
use std::fs::File;
use std::hash::Hasher;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::Instant;

use anyhow::{bail, Context, Result};
use arrow::array::*;
use arrow::datatypes::DataType;
use clap::Parser;
use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;
use twox_hash::XxHash64;

/// Implémentation autonome et idiomatique de l'algorithme HyperLogLog 64-bit.
#[derive(Clone, Debug)]
pub struct HyperLogLog {
    /// Nombre de bits de registre (p entre 4 et 18)
    precision: u8,
    /// Nombre de registres m = 2^p
    num_registers: usize,
    /// Table des registres contenant le maximum de zéros de tête observé
    registers: Vec<u8>,
}

impl HyperLogLog {
    /// Crée une nouvelle instance de HyperLogLog avec une précision `precision` (4 à 18 bits).
    pub fn new(precision: u8) -> Result<Self> {
        if !(4..=18).contains(&precision) {
            bail!("La précision HLL doit être comprise entre 4 et 18 (fournie: {})", precision);
        }
        let num_registers = 1usize << precision;
        Ok(Self {
            precision,
            num_registers,
            registers: vec![0; num_registers],
        })
    }

    /// Calcule le coefficient alpha_m pour la normalisation harmonique.
    fn alpha_m(m: usize) -> f64 {
        match m {
            16 => 0.673,
            32 => 0.697,
            64 => 0.709,
            _ => 0.7213 / (1.0 + 1.079 / (m as f64)),
        }
    }

    /// Ajoute une valeur hachée (64 bits) dans le HyperLogLog.
    pub fn add_hash(&mut self, hash: u64) {
        let p = self.precision;
        // On extrait l'index de registre à partir des p bits supérieurs
        let index = (hash >> (64 - p)) as usize;
        // La séquence restante sur 64 - p bits sert à compter les zéros de tête (+ 1)
        let w = (hash << p) | (1u64 << (p - 1)); // assure au moins un bit à 1 pour borner
        let leading_zeros = w.leading_zeros() as u8 + 1;

        if leading_zeros > self.registers[index] {
            self.registers[index] = leading_zeros;
        }
    }

    /// Hache une tranche d'octets avec XxHash64 et l'insère dans l'estimateur.
    pub fn add_bytes(&mut self, bytes: &[u8]) {
        let mut hasher = XxHash64::with_seed(0);
        hasher.write(bytes);
        self.add_hash(hasher.finish());
    }

    /// Estime la cardinalité actuelle.
    pub fn estimate(&self) -> u64 {
        let m = self.num_registers as f64;
        let alpha = Self::alpha_m(self.num_registers);

        let mut sum = 0.0;
        let mut zero_registers = 0;

        for &val in &self.registers {
            sum += 2.0f64.powi(-(val as i32));
            if val == 0 {
                zero_registers += 1;
            }
        }

        let raw_estimate = alpha * m * m / sum;

        // Correction pour petits ensembles (LinearCounting)
        if raw_estimate <= 2.5 * m {
            if zero_registers > 0 {
                let v = zero_registers as f64;
                (m * (m / v).ln()).round() as u64
            } else {
                raw_estimate.round() as u64
            }
        } else if raw_estimate <= (1.0 / 30.0) * (u64::MAX as f64) {
            raw_estimate.round() as u64
        } else {
            // Correction pour très grands ensembles
            let two_pow_64 = (u64::MAX as f64) + 1.0;
            (-two_pow_64 * (1.0 - raw_estimate / two_pow_64).ln_1p()).round() as u64
        }
    }

    /// Fusionne un autre HLL de même précision dans celui-ci.
    pub fn merge(&mut self, other: &Self) -> Result<()> {
        if self.precision != other.precision {
            bail!(
                "Impossible de fusionner des HLL de précisions distinctes ({} vs {})",
                self.precision,
                other.precision
            );
        }
        for (r_self, &r_other) in self.registers.iter_mut().zip(&other.registers) {
            if r_other > *r_self {
                *r_self = r_other;
            }
        }
        Ok(())
    }
}

/// Arguments de ligne de commande pour l'outil d'évaluation Parquet.
#[derive(Parser, Debug)]
#[command(
    name = "parquet-hll",
    version,
    about = "Évalue la cardinalité distincte de colonnes de fichiers Parquet via HyperLogLog",
    long_about = None
)]
struct Args {
    /// Chemin du fichier Parquet à analyser
    #[arg(short = 'p', long = "path", value_name = "FILE")]
    path: PathBuf,

    /// Colonnes à analyser (séparées par une virgule ou répétées). Si non spécifié, toutes les colonnes supportées sont évaluées.
    #[arg(short = 'c', long = "columns", value_delimiter = ',')]
    columns: Vec<String>,

    /// Précision HyperLogLog (nombre de bits de registres, entre 4 et 18, défaut 12)
    #[arg(short = 'b', long = "precision", default_value_t = 12)]
    precision: u8,

    /// Taille des batchs de lecture Arrow
    #[arg(long = "batch-size", default_value_t = 8192)]
    batch_size: usize,

    /// Afficher des statistiques détaillées (nulls, types, temps de calcul)
    #[arg(short = 'v', long = "verbose")]
    verbose: bool,
}

/// Métadonnées et accumulateur pour chaque colonne analysée
struct ColumnAccumulator {
    name: String,
    data_type: DataType,
    hll: HyperLogLog,
    total_rows: u64,
    null_count: u64,
}

impl ColumnAccumulator {
    fn new(name: String, data_type: DataType, precision: u8) -> Result<Self> {
        Ok(Self {
            name,
            data_type,
            hll: HyperLogLog::new(precision)?,
            total_rows: 0,
            null_count: 0,
        })
    }

    /// Incorpore un Arrow Array dans le HLL de la colonne
    fn process_array(&mut self, array: &Arc<dyn Array>) -> Result<()> {
        let len = array.len() as u64;
        self.total_rows += len;
        self.null_count += array.null_count() as u64;

        if array.null_count() == array.len() {
            return Ok(());
        }

        macro_rules! process_primitive {
            ($arr_type:ty) => {{
                let typed_arr = array.as_any().downcast_ref::<$arr_type>().context("Downcast échoué")?;
                for i in 0..typed_arr.len() {
                    if typed_arr.is_valid(i) {
                        let val = typed_arr.value(i);
                        self.hll.add_bytes(&val.to_ne_bytes());
                    }
                }
            }};
        }

        match array.data_type() {
            DataType::Int8 => process_primitive!(Int8Array),
            DataType::Int16 => process_primitive!(Int16Array),
            DataType::Int32 => process_primitive!(Int32Array),
            DataType::Int64 => process_primitive!(Int64Array),
            DataType::UInt8 => process_primitive!(UInt8Array),
            DataType::UInt16 => process_primitive!(UInt16Array),
            DataType::UInt32 => process_primitive!(UInt32Array),
            DataType::UInt64 => process_primitive!(UInt64Array),
            DataType::Float32 => {
                let typed_arr = array.as_any().downcast_ref::<Float32Array>().context("Downcast Float32 échoué")?;
                for i in 0..typed_arr.len() {
                    if typed_arr.is_valid(i) {
                        let val = typed_arr.value(i);
                        // Normalise NaN pour regrouper tous les NaN sous une même signature
                        let bits = if val.is_nan() { f32::NAN.to_bits() } else { val.to_bits() };
                        self.hll.add_bytes(&bits.to_ne_bytes());
                    }
                }
            }
            DataType::Float64 => {
                let typed_arr = array.as_any().downcast_ref::<Float64Array>().context("Downcast Float64 échoué")?;
                for i in 0..typed_arr.len() {
                    if typed_arr.is_valid(i) {
                        let val = typed_arr.value(i);
                        let bits = if val.is_nan() { f64::NAN.to_bits() } else { val.to_bits() };
                        self.hll.add_bytes(&bits.to_ne_bytes());
                    }
                }
            }
            DataType::Boolean => {
                let typed_arr = array.as_any().downcast_ref::<BooleanArray>().context("Downcast Boolean échoué")?;
                for i in 0..typed_arr.len() {
                    if typed_arr.is_valid(i) {
                        let val = typed_arr.value(i);
                        self.hll.add_bytes(&[if val { 1u8 } else { 0u8 }]);
                    }
                }
            }
            DataType::Utf8 => {
                let typed_arr = array.as_any().downcast_ref::<StringArray>().context("Downcast Utf8 échoué")?;
                for i in 0..typed_arr.len() {
                    if typed_arr.is_valid(i) {
                        self.hll.add_bytes(typed_arr.value(i).as_bytes());
                    }
                }
            }
            DataType::LargeUtf8 => {
                let typed_arr = array.as_any().downcast_ref::<LargeStringArray>().context("Downcast LargeUtf8 échoué")?;
                for i in 0..typed_arr.len() {
                    if typed_arr.is_valid(i) {
                        self.hll.add_bytes(typed_arr.value(i).as_bytes());
                    }
                }
            }
            DataType::Binary => {
                let typed_arr = array.as_any().downcast_ref::<BinaryArray>().context("Downcast Binary échoué")?;
                for i in 0..typed_arr.len() {
                    if typed_arr.is_valid(i) {
                        self.hll.add_bytes(typed_arr.value(i));
                    }
                }
            }
            DataType::LargeBinary => {
                let typed_arr = array.as_any().downcast_ref::<LargeBinaryArray>().context("Downcast LargeBinary échoué")?;
                for i in 0..typed_arr.len() {
                    if typed_arr.is_valid(i) {
                        self.hll.add_bytes(typed_arr.value(i));
                    }
                }
            }
            DataType::Date32 => process_primitive!(Date32Array),
            DataType::Date64 => process_primitive!(Date64Array),
            DataType::Timestamp(arrow::datatypes::TimeUnit::Nanosecond, _) => {
                process_primitive!(TimestampNanosecondArray);
            }
            DataType::Timestamp(arrow::datatypes::TimeUnit::Microsecond, _) => {
                process_primitive!(TimestampMicrosecondArray);
            }
            DataType::Timestamp(arrow::datatypes::TimeUnit::Millisecond, _) => {
                process_primitive!(TimestampMillisecondArray);
            }
            DataType::Timestamp(arrow::datatypes::TimeUnit::Second, _) => {
                process_primitive!(TimestampSecondArray);
            }
            other => {
                // Fallback générique utilisant l'affichage standard Arrow
                for i in 0..array.len() {
                    if array.is_valid(i) {
                        let text = arrow::util::display::array_value_to_string(array, i)
                            .unwrap_or_else(|_| format!("{:?}", other));
                        self.hll.add_bytes(text.as_bytes());
                    }
                }
            }
        }

        Ok(())
    }
}

/// Analyse un fichier Parquet donné et produit une estimation de cardinalité par colonne.
fn analyze_parquet_file(
    file_path: &Path,
    selected_columns: &[String],
    precision: u8,
    batch_size: usize,
) -> Result<Vec<ColumnAccumulator>> {
    let file = File::open(file_path)
        .with_context(|| format!("Impossible d'ouvrir le fichier : {}", file_path.display()))?;

    let builder = ParquetRecordBatchReaderBuilder::try_new(file)
        .with_context(|| "Échec de l'initialisation du lecteur Parquet")?
        .with_batch_size(batch_size);

    let arrow_schema = builder.schema().clone();
    let fields = arrow_schema.fields();

    let mut target_indices = Vec::new();
    let mut accumulators = Vec::new();

    if selected_columns.is_empty() {
        for (idx, field) in fields.iter().enumerate() {
            target_indices.push(idx);
            accumulators.push(ColumnAccumulator::new(
                field.name().clone(),
                field.data_type().clone(),
                precision,
            )?);
        }
    } else {
        for col_name in selected_columns {
            if let Some((idx, field)) = fields.iter().enumerate().find(|(_, f)| f.name() == col_name) {
                target_indices.push(idx);
                accumulators.push(ColumnAccumulator::new(
                    field.name().clone(),
                    field.data_type().clone(),
                    precision,
                )?);
            } else {
                bail!(
                    "La colonne '{}' est introuvable dans le schéma du fichier Parquet.",
                    col_name
                );
            }
        }
    }

    if accumulators.is_empty() {
        bail!("Aucune colonne sélectionnée ou disponible dans le schéma.");
    }

    let mut reader = builder.build().context("Échec de la construction du lecteur de batchs")?;

    while let Some(batch_res) = reader.next() {
        let batch = batch_res.context("Erreur lors de la lecture d'un RecordBatch")?;
        for (col_pos, &schema_idx) in target_indices.iter().enumerate() {
            let column_array = batch.column(schema_idx);
            accumulators[col_pos].process_array(column_array)?;
        }
    }

    Ok(accumulators)
}

fn main() -> Result<()> {
    let start_time = Instant::now();
    let args = Args::parse();

    if !args.path.exists() {
        bail!("Le chemin spécifié n'existe pas : {}", args.path.display());
    }

    let standard_error = 1.04 / ((1usize << args.precision as usize) as f64).sqrt();

    println!("============================================================");
    println!("  Évaluation de cardinalité Parquet via HyperLogLog (HLL)  ");
    println!("============================================================");
    println!("Fichier      : {}", args.path.display());
    println!("Précision    : {} bits (m = {} registres, err ~ {:.2}%)", 
        args.precision, 
        1usize << args.precision,
        standard_error * 100.0
    );
    println!("Batch size   : {}", args.batch_size);
    println!("------------------------------------------------------------");

    let results = analyze_parquet_file(
        &args.path,
        &args.columns,
        args.precision,
        args.batch_size,
    )?;

    println!("{:<25} {:<15} {:<15} {:<12} {:<12}", "Colonne", "Type", "Cardinalité", "Lignes", "Nulls");
    println!("{:-<25} {:-<15} {:-<15} {:-<12} {:-<12}", "", "", "", "", "");

    for acc in &results {
        let cardinality = acc.hll.estimate();
        let type_str = format!("{:?}", acc.data_type);
        let truncated_type = if type_str.len() > 14 {
            format!("{}…", &type_str[..13])
        } else {
            type_str
        };

        println!(
            "{:<25} {:<15} {:<15} {:<12} {:<12}",
            acc.name,
            truncated_type,
            cardinality,
            acc.total_rows,
            acc.null_count
        );

        if args.verbose {
            let null_pct = if acc.total_rows > 0 {
                (acc.null_count as f64 / acc.total_rows as f64) * 100.0
            } else {
                0.0
            };
            let distinct_pct = if acc.total_rows > 0 {
                (cardinality as f64 / acc.total_rows as f64) * 100.0
            } else {
                0.0
            };
            println!(
                "   └─ Ratio distincts: {:.2}% | Ratio nulls: {:.2}%",
                distinct_pct, null_pct
            );
        }
    }

    let elapsed = start_time.elapsed();
    println!("------------------------------------------------------------");
    println!("Traitement terminé avec succès en {:.3} s", elapsed.as_secs_f64());
    println!("============================================================");

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_hll_basic_estimation() -> Result<()> {
        let mut hll = HyperLogLog::new(12)?;
        for i in 0..10_000 {
            hll.add_bytes(format!("valeur_{}", i).as_bytes());
        }

        let est = hll.estimate();
        // Pour p=12, l'erreur type est de ~1.6%
        let error = ((est as f64 - 10000.0).abs() / 10000.0) * 100.0;
        assert!(error < 5.0, "Estimation attendue proche de 10000, obtenue: {} (erreur: {:.2}%)", est, error);
        Ok(())
    }

    #[test]
    fn test_hll_merge() -> Result<()> {
        let mut hll1 = HyperLogLog::new(12)?;
        let mut hll2 = HyperLogLog::new(12)?;

        for i in 0..5_000 {
            hll1.add_bytes(format!("element_{}", i).as_bytes());
        }
        for i in 5_000..10_000 {
            hll2.add_bytes(format!("element_{}", i).as_bytes());
        }

        hll1.merge(&hll2)?;
        let est = hll1.estimate();
        let error = ((est as f64 - 10000.0).abs() / 10000.0) * 100.0;
        assert!(error < 5.0, "Estimation fusionnée: {} (erreur: {:.2}%)", est, error);
        Ok(())
    }

    #[test]
    fn test_precision_bounds() {
        assert!(HyperLogLog::new(3).is_err());
        assert!(HyperLogLog::new(19).is_err());
        assert!(HyperLogLog::new(12).is_ok());
    }
}

