// src/main.rs
use std::fs::File;
use std::hash::Hasher;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::Instant;

use anyhow::{bail, Context, Result};
use arrow::array::*;
use arrow::datatypes::DataType;
use clap::Parser;
use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;
use twox_hash::XxHash64;

/// Implémentation autonome et idiomatique de l'algorithme HyperLogLog 64-bit.
#[derive(Clone, Debug)]
pub struct HyperLogLog {
    /// Nombre de bits de registre (p entre 4 et 18)
    precision: u8,
    /// Nombre de registres m = 2^p
    num_registers: usize,
    /// Table des registres contenant le maximum de zéros de tête observé
    registers: Vec<u8>,
}

impl HyperLogLog {
    /// Crée une nouvelle instance de HyperLogLog avec une précision `precision` (4 à 18 bits).
    pub fn new(precision: u8) -> Result<Self> {
        if !(4..=18).contains(&precision) {
            bail!("La précision HLL doit être comprise entre 4 et 18 (fournie: {})", precision);
        }
        let num_registers = 1usize << precision;
        Ok(Self {
            precision,
            num_registers,
            registers: vec![0; num_registers],
        })
    }

    /// Calcule le coefficient alpha_m pour la normalisation harmonique.
    fn alpha_m(m: usize) -> f64 {
        match m {
            16 => 0.673,
            32 => 0.697,
            64 => 0.709,
            _ => 0.7213 / (1.0 + 1.079 / (m as f64)),
        }
    }

    /// Ajoute une valeur hachée (64 bits) dans le HyperLogLog.
    pub fn add_hash(&mut self, hash: u64) {
        let p = self.precision;
        // On extrait l'index de registre à partir des p bits supérieurs
        let index = (hash >> (64 - p)) as usize;
        // La séquence restante sur 64 - p bits sert à compter les zéros de tête (+ 1)
        let w = (hash << p) | (1u64 << (p - 1)); // assure au moins un bit à 1 pour borner
        let leading_zeros = w.leading_zeros() as u8 + 1;

        if leading_zeros > self.registers[index] {
            self.registers[index] = leading_zeros;
        }
    }

    /// Hache une tranche d'octets avec XxHash64 et l'insère dans l'estimateur.
    pub fn add_bytes(&mut self, bytes: &[u8]) {
        let mut hasher = XxHash64::with_seed(0);
        hasher.write(bytes);
        self.add_hash(hasher.finish());
    }

    /// Estime la cardinalité actuelle.
    pub fn estimate(&self) -> u64 {
        let m = self.num_registers as f64;
        let alpha = Self::alpha_m(self.num_registers);

        let mut sum = 0.0;
        let mut zero_registers = 0;

        for &val in &self.registers {
            sum += 2.0f64.powi(-(val as i32));
            if val == 0 {
                zero_registers += 1;
            }
        }

        let raw_estimate = alpha * m * m / sum;

        // Correction pour petits ensembles (LinearCounting)
        if raw_estimate <= 2.5 * m {
            if zero_registers > 0 {
                let v = zero_registers as f64;
                (m * (m / v).ln()).round() as u64
            } else {
                raw_estimate.round() as u64
            }
        } else if raw_estimate <= (1.0 / 30.0) * (u64::MAX as f64) {
            raw_estimate.round() as u64
        } else {
            // Correction pour très grands ensembles
            let two_pow_64 = (u64::MAX as f64) + 1.0;
            (-two_pow_64 * (1.0 - raw_estimate / two_pow_64).ln_1p()).round() as u64
        }
    }

    /// Fusionne un autre HLL de même précision dans celui-ci.
    pub fn merge(&mut self, other: &Self) -> Result<()> {
        if self.precision != other.precision {
            bail!(
                "Impossible de fusionner des HLL de précisions distinctes ({} vs {})",
                self.precision,
                other.precision
            );
        }
        for (r_self, &r_other) in self.registers.iter_mut().zip(&other.registers) {
            if r_other > *r_self {
                *r_self = r_other;
            }
        }
        Ok(())
    }
}

