// src/main.rs
use std::fs::File;
use std::io::{self, BufRead, BufReader, BufWriter, Read, Write};
use std::path::{Path, PathBuf};

use clap::{Parser, ValueEnum};
use serde::{Deserialize, Serialize};
use thiserror::Error;

/// Erreurs possibles lors du traitement et de la conversion des matrices.
#[derive(Debug, Error)]
pub enum AppError {
    #[error("Erreur d'entrée/sortie : {0}")]
    Io(#[from] io::Error),

    #[error("Erreur de désérialisation/sérialisation JSON : {0}")]
    Json(#[from] serde_json::Error),

    #[error("En-tête Matrix Market invalide : {0}")]
    InvalidMatrixMarketHeader(String),

    #[error("Ligne de données Matrix Market malformée : '{0}'")]
    MalformedDataLine(String),

    #[error("Dimensions de matrice invalides : {rows}x{cols}")]
    InvalidDimensions { rows: usize, cols: usize },

    #[error("Coordonnées hors limites : ({row}, {col}) pour une matrice de taille {rows}x{cols}")]
    IndexOutOfBounds {
        row: usize,
        col: usize,
        rows: usize,
        cols: usize,
    },

    #[error("Incohérence CSR : indptr de taille {indptr_len} incompatible avec rows={rows}")]
    InvalidCsrIndptr { indptr_len: usize, rows: usize },

    #[error("Incohérence CSR : indices ({indices_len}) et data ({data_len}) doivent avoir la même taille")]
    CsrLengthMismatch {
        indices_len: usize,
        data_len: usize,
    },

    #[error("Limite mémoire dépassée : {requested} cellules demandées, maximum autorisé fixé à {max_allowed}")]
    MemoryLimitExceeded {
        requested: usize,
        max_allowed: usize,
    },

    #[error("Dépassement de capacité arithmétique lors du calcul des dimensions ({rows} * {cols})")]
    DimensionOverflow { rows: usize, cols: usize },

    #[error("Format d'entrée impossible à détecter automatiquement pour '{0}'")]
    UnknownInputFormat(String),
}

/// Format d'entrée pour la matrice creuse.
#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
pub enum SparseInputFormat {
    /// Détection automatique basée sur l'extension ou le contenu
    Auto,
    /// Format Matrix Market (.mtx) en coordonnées
    MatrixMarket,
    /// Format JSON COO (liste de triplets [ligne, colonne, valeur])
    CooJson,
    /// Format JSON CSR (indptr, indices, data)
    CsrJson,
}

/// Format de sérialisation JSON dense souhaité.
#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
pub enum DenseOutputLayout {
    /// Tableau 2D imbriqué : [[a, b], [c, d]]
    Grid,
    /// Tableau 1D aplati par lignes (Row-major) avec métadonnées
    FlatRowMajor,
    /// Tableau 1D aplati par colonnes (Column-major) avec métadonnées
    FlatColMajor,
}

/// CLI pour l'extraction et la conversion de matrices creuses vers des formats denses JSON.
#[derive(Parser, Debug)]
#[command(
    name = "sparse2dense",
    author,
    version,
    about = "Extrait et convertit des matrices creuses vers des formats denses sérialisés en JSON.",
    long_about = None
)]
pub struct Cli {
    /// Chemin du fichier de matrice creuse en entrée (laisser vide ou '-' pour stdin)
    #[arg(short, long, value_name = "FILE")]
    pub input: Option<PathBuf>,

    /// Chemin du fichier JSON de sortie (laisser vide ou '-' pour stdout)
    #[arg(short, long, value_name = "FILE")]
    pub output: Option<PathBuf>,

    /// Format de la matrice d'entrée
    #[arg(short = 'f', long, value_enum, default_value_t = SparseInputFormat::Auto)]
    pub format: SparseInputFormat,

    /// Disposition dense pour la sortie JSON
    #[arg(short = 'd', long, value_enum, default_value_t = DenseOutputLayout::Grid)]
    pub dense_layout: DenseOutputLayout,

    /// Activer le formatage indenté (pretty-print) pour le JSON de sortie
    #[arg(short, long)]
    pub pretty: bool,

    /// Nombre maximal d'éléments denses autorisés pour prévenir la surconsommation mémoire
    #[arg(long, default_value_t = 10_000_000)]
    pub max_cells: usize,
}

/// Triplet (row, col, value) représentant une entrée non nulle.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct MatrixEntry {
    pub row: usize,
    pub col: usize,
    pub value: f64,
}

/// Représentation intermédiaire universelle d'une matrice creuse en coordonnées (COO).
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct CooMatrix {
    pub rows: usize,
    pub cols: usize,
    pub entries: Vec<MatrixEntry>,
}

/// Format JSON alternatif pour le format CSR (Compressed Sparse Row).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CsrMatrixJson {
    pub rows: usize,
    pub cols: usize,
    pub indptr: Vec<usize>,
    pub indices: Vec<usize>,
    pub data: Vec<f64>,
}

/// Matrice dense stockée en mémoire.
#[derive(Debug, Clone, PartialEq)]
pub struct DenseMatrix {
    pub rows: usize,
    pub cols: usize,
    pub data: Vec<f64>,
}

/// Représentation JSON aplatie avec ordre de stockage pour la sérialisation.
#[derive(Debug, Serialize)]
pub struct FlatDenseMatrixJson<'a> {
    pub rows: usize,
    pub cols: usize,
    pub layout: &'static str,
    pub data: &'a [f64],
}

impl CooMatrix {
    /// Valide les bornes des indices et les dimensions.
    pub fn validate(&self) -> Result<(), AppError> {
        if self.rows == 0 || self.cols == 0 {
            return Err(AppError::InvalidDimensions {
                rows: self.rows,
                cols: self.cols,
            });
        }

        for entry in &self.entries {
            if entry.row >= self.rows || entry.col >= self.cols {
                return Err(AppError::IndexOutOfBounds {
                    row: entry.row,
                    col: entry.col,
                    rows: self.rows,
                    cols: self.cols,
                });
            }
        }
        Ok(())
    }

    /// Convertit la matrice creuse vers une matrice dense en mémoire en validant la limite mémoire.
    pub fn to_dense(&self, max_cells: usize) -> Result<DenseMatrix, AppError> {
        self.validate()?;

        let total_cells = self
            .rows
            .checked_mul(self.cols)
            .ok_or(AppError::DimensionOverflow {
                rows: self.rows,
                cols: self.cols,
            })?;

        if total_cells > max_cells {
            return Err(AppError::MemoryLimitExceeded {
                requested: total_cells,
                max_allowed: max_cells,
            });
        }

        let mut data = vec![0.0f64; total_cells];

        for entry in &self.entries {
            let idx = entry.row * self.cols + entry.col;
            // Somme en cas de doublons (comportement standard COO / Matrix Market)
            data[idx] += entry.value;
        }

        Ok(DenseMatrix {
            rows: self.rows,
            cols: self.cols,
            data,
        })
    }
}

impl DenseMatrix {
    /// Convertit la représentation interne row-major en grille 2D.
    pub fn to_grid(&self) -> Vec<Vec<f64>> {
        let mut grid = Vec::with_capacity(self.rows);
        for r in 0..self.rows {
            let start = r * self.cols;
            let end = start + self.cols;
            grid.push(self.data[start..end].to_vec());
        }
        grid
    }

    /// Réorganise les données en column-major.
    pub fn to_column_major_data(&self) -> Vec<f64> {
        let mut col_major = vec![0.0f64; self.rows * self.cols];
        for r in 0..self.rows {
            for c in 0..self.cols {
                let row_idx = r * self.cols + c;
                let col_idx = c * self.rows + r;
                col_major[col_idx] = self.data[row_idx];
            }
        }
        col_major
    }

    /// Sérialise la matrice dense selon la disposition choisie.
    pub fn serialize_json<W: Write>(
        &self,
        writer: W,
        layout: DenseOutputLayout,
        pretty: bool,
    ) -> Result<(), AppError> {
        match layout {
            DenseOutputLayout::Grid => {
                let grid = self.to_grid();
                if pretty {
                    serde_json::to_writer_pretty(writer, &grid)?;
                } else {
                    serde_json::to_writer(writer, &grid)?;
                }
            }
            DenseOutputLayout::FlatRowMajor => {
                let envelope = FlatDenseMatrixJson {
                    rows: self.rows,
                    cols: self.cols,
                    layout: "row-major",
                    data: &self.data,
                };
                if pretty {
                    serde_json::to_writer_pretty(writer, &envelope)?;
                } else {
                    serde_json::to_writer(writer, &envelope)?;
                }
            }
            DenseOutputLayout::FlatColMajor => {
                let col_data = self.to_column_major_data();
                let envelope = FlatDenseMatrixJson {
                    rows: self.rows,
                    cols: self.cols,
                    layout: "column-major",
                    data: &col_data,
                };
                if pretty {
                    serde_json::to_writer_pretty(writer, &envelope)?;
                } else {
                    serde_json::to_writer(writer, &envelope)?;
                }
            }
        }
        Ok(())
    }
}

/// Analyseur pour le format Matrix Market (.mtx).
pub struct MatrixMarketParser;

impl MatrixMarketParser {
    pub fn parse<R: Read>(reader: R) -> Result<CooMatrix, AppError> {
        let mut buf_reader = BufReader::new(reader);
        let mut first_line = String::new();

        buf_reader.read_line(&mut first_line)?;
        let trimmed_header = first_line.trim();

        if !trimmed_header.starts_with("%%MatrixMarket") {
            return Err(AppError::InvalidMatrixMarketHeader(
                "Le fichier ne commence pas par l'en-tête '%%MatrixMarket'".to_string(),
            ));
        }

        let tokens: Vec<&str> = trimmed_header.split_whitespace().collect();
        if tokens.len() < 5 {
            return Err(AppError::InvalidMatrixMarketHeader(
                "En-tête MatrixMarket incomplet".to_string(),
            ));
        }

        let object = tokens[1].to_ascii_lowercase();
        let format = tokens[2].to_ascii_lowercase();
        let qualifier = tokens[4].to_ascii_lowercase();

        if object != "matrix" || format != "coordinate" {
            return Err(AppError::InvalidMatrixMarketHeader(format!(
                "Seules les matrices de type 'coordinate' sont supportées (reçu: object='{}', format='{}')",
                object, format
            )));
        }

        let is_symmetric = qualifier == "symmetric";
        let is_skew_symmetric = qualifier == "skew-symmetric";

        // Recherche de la ligne de dimensions
        let mut line = String::new();
        let mut rows = 0;
        let mut cols = 0;
        let mut declared_entries = 0;

        while buf_reader.read_line(&mut line)? > 0 {
            let trimmed = line.trim();
            if trimmed.is_empty() || trimmed.starts_with('%') {
                line.clear();
                continue;
            }

            let parts: Vec<&str> = trimmed.split_whitespace().collect();
            if parts.len() < 3 {
                return Err(AppError::MalformedDataLine(line));
            }

            rows = parts[0].parse::<usize>().map_err(|_| {
                AppError::MalformedDataLine(format!("Nombre de lignes invalide : {}", parts[0]))
            })?;
            cols = parts[1].parse::<usize>().map_err(|_| {
                AppError::MalformedDataLine(format!("Nombre de colonnes invalide : {}", parts[1]))
            })?;
            declared_entries = parts[2].parse::<usize>().map_err(|_| {
                AppError::MalformedDataLine(format!("Nombre d'entrées invalide : {}", parts[2]))
            })?;
            break;
        }

        if rows == 0 || cols == 0 {
            return Err(AppError::InvalidDimensions { rows, cols });
        }

        let mut entries = Vec::with_capacity(declared_entries);
        line.clear();

        while buf_reader.read_line(&mut line)? > 0 {
            let trimmed = line.trim();
            if trimmed.is_empty() || trimmed.starts_with('%') {
                line.clear();
                continue;
            }

            let parts: Vec<&str> = trimmed.split_whitespace().collect();
            if parts.len() < 3 {
                return Err(AppError::MalformedDataLine(line));
            }

            // Les indices Matrix Market sont indexés à 1
            let one_based_row = parts[0].parse::<usize>().map_err(|_| {
                AppError::MalformedDataLine(format!("Ligne invalide : {}", parts[0]))
            })?;
            let one_based_col = parts[1].parse::<usize>().map_err(|_| {
                AppError::MalformedDataLine(format!("Colonne invalide : {}", parts[1]))
            })?;
            let value = parts[2].parse::<f64>().map_err(|_| {
                AppError::MalformedDataLine(format!("Valeur numérique invalide : {}", parts[2]))
            })?;

            if one_based_row == 0 || one_based_col == 0 {
                return Err(AppError::MalformedDataLine(
                    "Les coordonnées Matrix Market doivent être >= 1".to_string(),
                ));
            }

            let row = one_based_row - 1;
            let col = one_based_col - 1;

            if row >= rows || col >= cols {
                return Err(AppError::IndexOutOfBounds {
                    row,
                    col,
                    rows,
                    cols,
                });
            }

            entries.push(MatrixEntry { row, col, value });

            if row != col {
                if is_symmetric {
                    entries.push(MatrixEntry {
                        row: col,
                        col: row,
                        value,
                    });
                } else if is_skew_symmetric {
                    entries.push(MatrixEntry {
                        row: col,
                        col: row,
                        value: -value,
                    });
                }
            }

            line.clear();
        }

        let matrix = CooMatrix {
            rows,
            cols,
            entries,
        };
        matrix.validate()?;
        Ok(matrix)
    }
}

/// Convertisseur pour le format CSR JSON vers COO.
pub fn csr_to_coo(csr: CsrMatrixJson) -> Result<CooMatrix, AppError> {
    if csr.rows == 0 || csr.cols == 0 {
        return Err(AppError::InvalidDimensions {
            rows: csr.rows,
            cols: csr.cols,
        });
    }

    if csr.indptr.len() != csr.rows + 1 {
        return Err(AppError::InvalidCsrIndptr {
            indptr_len: csr.indptr.len(),
            rows: csr.rows,
        });
    }

    if csr.indices.len() != csr.data.len() {
        return Err(AppError::CsrLengthMismatch {
            indices_len: csr.indices.len(),
            data_len: csr.data.len(),
        });
    }

    let mut entries = Vec::with_capacity(csr.data.len());

    for r in 0..csr.rows {
        let start = csr.indptr[r];
        let end = csr.indptr[r + 1];

        if start > end || end > csr.indices.len() {
            return Err(AppError::InvalidCsrIndptr {
                indptr_len: csr.indptr.len(),
                rows: csr.rows,
            });
        }

        for i in start..end {
            let col = csr.indices[i];
            let value = csr.data[i];

            if col >= csr.cols {
                return Err(AppError::IndexOutOfBounds {
                    row: r,
                    col,
                    rows: csr.rows,
                    cols: csr.cols,
                });
            }

            entries.push(MatrixEntry { row: r, col, value });
        }
    }

    let coo = CooMatrix {
        rows: csr.rows,
        cols: csr.cols,
        entries,
    };
    coo.validate()?;
    Ok(coo)
}

/// Détecte le format de la matrice selon son chemin ou ses premiers octets.
pub fn detect_format(path: Option<&Path>, sample: &[u8]) -> Result<SparseInputFormat, AppError> {
    if let Some(p) = path {
        if let Some(ext) = p.extension().and_then(|s| s.to_str()) {
            match ext.to_ascii_lowercase().as_str() {
                "mtx" => return Ok(SparseInputFormat::MatrixMarket),
                "json" => {
                    // Raffinement possible avec le sample
                    if let Ok(text) = std::str::from_utf8(sample) {
                        if text.contains("\"indptr\"") {
                            return Ok(SparseInputFormat::CsrJson);
                        }
                        if text.contains("\"entries\"") {
                            return Ok(SparseInputFormat::CooJson);
                        }
                    }
                    return Ok(SparseInputFormat::CooJson);
                }
                _ => {}
            }
        }
    }

    // Détection par inspection du flux d'octets
    if sample.starts_with(b"%%MatrixMarket") {
        return Ok(SparseInputFormat::MatrixMarket);
    }

    if let Ok(text) = std::str::from_utf8(sample) {
        let trimmed = text.trim_start();
        if trimmed.starts_with('{') {
            if trimmed.contains("\"indptr\"") {
                return Ok(SparseInputFormat::CsrJson);
            }
            if trimmed.contains("\"entries\"") {
                return Ok(SparseInputFormat::CooJson);
            }
        }
    }

    Err(AppError::UnknownInputFormat(
        path.map_or_else(|| "flux stdin".to_string(), |p| p.display().to_string()),
    ))
}

/// Lit et convertit la matrice creuse depuis n'importe quelle source implémentant `Read`.
pub fn load_sparse_matrix<R: Read>(
    mut reader: R,
    format: SparseInputFormat,
    path_hint: Option<&Path>,
) -> Result<CooMatrix, AppError> {
    let mut buffer = Vec::new();
    reader.read_to_end(&mut buffer)?;

    let resolved_format = match format {
        SparseInputFormat::Auto => {
            let sample_len = buffer.len().min(1024);
            detect_format(path_hint, &buffer[..sample_len])?
        }
        explicit => explicit,
    };

    match resolved_format {
        SparseInputFormat::MatrixMarket => MatrixMarketParser::parse(&buffer[..]),
        SparseInputFormat::CooJson => {
            let coo: CooMatrix = serde_json::from_slice(&buffer)?;
            coo.validate()?;
            Ok(coo)
        }
        SparseInputFormat::CsrJson => {
            let csr: CsrMatrixJson = serde_json::from_slice(&buffer)?;
            csr_to_coo(csr)
        }
        SparseInputFormat::Auto => unreachable!(),
    }
}

/// Point d'entrée principal.
fn main() -> Result<(), AppError> {
    let cli = Cli::parse();

    let path_hint = match &cli.input {
        Some(p) if p != Path::new("-") => Some(p.as_path()),
        _ => None,
    };

    let coo_matrix = match path_hint {
        Some(path) => {
            let file = File::open(path)?;
            load_sparse_matrix(file, cli.format, Some(path))?
        }
        None => {
            let stdin = io::stdin();
            load_sparse_matrix(stdin.lock(), cli.format, None)?
        }
    };

    let dense_matrix = coo_matrix.to_dense(cli.max_cells)?;

    match &cli.output {
        Some(path) if path != Path::new("-") => {
            let file = File::create(path)?;
            let mut writer = BufWriter::new(file);
            dense_matrix.serialize_json(&mut writer, cli.dense_layout, cli.pretty)?;
            writer.flush()?;
        }
        _ => {
            let stdout = io::stdout();
            let mut writer = BufWriter::new(stdout.lock());
            dense_matrix.serialize_json(&mut writer, cli.dense_layout, cli.pretty)?;
            writer.flush()?;
        }
    }

    Ok(())
}

