use sysinfo::Networks;

const SPARKLINE_HISTORY_LEN: usize = 120;
const TICK_RATE_MS: u64 = 1000;

/// Représente les statistiques d'une interface réseau pour une période donnée.
#[derive(Debug, Clone, Default)]
struct InterfaceStats {
    name: String,
    rx_bytes: u64,
    tx_bytes: u64,
    rx_packets: u64,
    tx_packets: u64,
    rx_errors: u64,
    tx_errors: u64,
    rx_rate_bps: u64,
    tx_rate_bps: u64,
}

/// État de l'application
struct App {
    networks: Networks,
    interfaces: Vec<InterfaceStats>,
    selected_index: usize,
    table_state: TableState,
    rx_history: VecDeque<u64>,
    tx_history: VecDeque<u64>,
    total_rx_rate: u64,
    total_tx_rate: u64,
    peak_rx_rate: u64,
    peak_tx_rate: u64,
    cumulative_rx: u64,
    cumulative_tx: u64,
}

impl App {
    fn new() -> Self {
        let mut networks = Networks::new_with_refreshed_list();
        networks.refresh(true);

        let mut app = Self {
            networks,
            interfaces: Vec::new(),
            selected_index: 0,
            table_state: TableState::default(),
            rx_history: VecDeque::from(vec![0; SPARKLINE_HISTORY_LEN]),
            tx_history: VecDeque::from(vec![0; SPARKLINE_HISTORY_LEN]),
            total_rx_rate: 0,
            total_tx_rate: 0,
            peak_rx_rate: 0,
            peak_tx_rate: 0,
            cumulative_rx: 0,
            cumulative_tx: 0,
        };
        app.update_metrics();
        if !app.interfaces.is_empty() {
            app.table_state.select(Some(0));
        }
        app
    }

    fn update_metrics(&mut self) {
        self.networks.refresh(true);

        let mut current_interfaces = Vec::new();
        let mut sum_rx_rate = 0u64;
        let mut sum_tx_rate = 0u64;

        for (name, data) in &self.networks {
            let rx_bytes = data.received();
            let tx_bytes = data.transmitted();
            let rx_packets = data.packets_received();
            let tx_packets = data.packets_transmitted();
            let rx_errors = data.errors_on_received();
            let tx_errors = data.errors_on_transmitted();

            // Trouver l'échantillon précédent pour calculer le delta / sec
            let prev = self.interfaces.iter().find(|i| i.name == *name);
            let rx_rate = prev
                .map(|p| rx_bytes.saturating_sub(p.rx_bytes))
                .unwrap_or(0);
            let tx_rate = prev
                .map(|p| tx_bytes.saturating_sub(p.tx_bytes))
                .unwrap_or(0);

            sum_rx_rate = sum_rx_rate.saturating_add(rx_rate);
            sum_tx_rate = sum_tx_rate.saturating_add(tx_rate);

            current_interfaces.push(InterfaceStats {
                name: name.clone(),
                rx_bytes,
                tx_bytes,
                rx_packets,
                tx_packets,
                rx_errors,
                tx_errors,
                rx_rate_bps: rx_rate,
                tx_rate_bps: tx_rate,
            });
        }

        current_interfaces.sort_by(|a, b| a.name.cmp(&b.name));
        self.interfaces = current_interfaces;

        self.total_rx_rate = sum_rx_rate;
        self.total_tx_rate = sum_tx_rate;

        if sum_rx_rate > self.peak_rx_rate {
            self.peak_rx_rate = sum_rx_rate;
        }
        if sum_tx_rate > self.peak_tx_rate {
            self.peak_tx_rate = sum_tx_rate;
        }

        self.cumulative_rx = self.cumulative_rx.saturating_add(sum_rx_rate);
        self.cumulative_tx = self.cumulative_tx.saturating_add(sum_tx_rate);

        self.rx_history.pop_front();
        self.rx_history.push_back(sum_rx_rate);

        self.tx_history.pop_front();
        self.tx_history.push_back(sum_tx_rate);

        if self.selected_index >= self.interfaces.len() && !self.interfaces.is_empty() {
            self.selected_index = self.interfaces.len() - 1;
        }
        if !self.interfaces.is_empty() {
            self.table_state.select(Some(self.selected_index));
        } else {
            self.table_state.select(None);
        }
    }

    fn next_interface(&mut self) {
        if self.interfaces.is_empty() {
            return;
        }
        self.selected_index = (self.selected_index + 1) % self.interfaces.len();
        self.table_state.select(Some(self.selected_index));
    }

    fn previous_interface(&mut self) {
        if self.interfaces.is_empty() {
            return;
        }
        if self.selected_index == 0 {
            self.selected_index = self.interfaces.len() - 1;
        } else {
            self.selected_index -= 1;
        }
        self.table_state.select(Some(self.selected_index));
    }

    fn reset_counters(&mut self) {
        self.rx_history = VecDeque::from(vec![0; SPARKLINE_HISTORY_LEN]);
        self.tx_history = VecDeque::from(vec![0; SPARKLINE_HISTORY_LEN]);
        self.peak_rx_rate = 0;
        self.peak_tx_rate = 0;
        self.cumulative_rx = 0;
        self.cumulative_tx = 0;
    }
}

fn format_bytes(bytes: u64) -> String {
    const KIB: u64 = 1024;
    const MIB: u64 = 1024 * 1024;
    const GIB: u64 = 1024 * 1024 * 1024;

    if bytes >= GIB {
        format!("{:.2} GiB", bytes as f64 / GIB as f64)
    } else if bytes >= MIB {
        format!("{:.2} MiB", bytes as f64 / MIB as f64)
    } else if bytes >= KIB {
        format!("{:.2} KiB", bytes as f64 / KIB as f64)
    } else {
        format!("{bytes} B")
    }
}

fn format_rate(bytes_per_sec: u64) -> String {
    format!("{}/s", format_bytes(bytes_per_sec))
}

fn render_ui(frame: &mut Frame, app: &mut App) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // Titre & Barres de statut globales
            Constraint::Length(8), // Sparklines Débit entrant / sortant
            Constraint::Min(8),    // Table détaillée des interfaces
            Constraint::Length(1), // Footer / Raccourcis
