    );
    frame.render_widget(header_widget, area);
}

fn render_sparklines(frame: &mut Frame, app: &App, area: Rect) {
    let sparkline_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
        .split(area);

    let rx_data: Vec<u64> = app.rx_history.iter().copied().collect();
    let tx_data: Vec<u64> = app.tx_history.iter().copied().collect();

    let rx_title = format!(
        " ⬇ Download (RX) : {} (Total: {}) ",
        format_rate(app.total_rx_rate),
        format_bytes(app.cumulative_rx)
    );
    let rx_sparkline = Sparkline::default()
        .block(
            Block::default()
                .borders(Borders::ALL)
                .title(rx_title)
                .style(Style::default().fg(Color::Cyan)),
        )
        .data(&rx_data)
        .style(Style::default().fg(Color::Cyan));
    frame.render_widget(rx_sparkline, sparkline_chunks[0]);

    let tx_title = format!(
        " ⬆ Upload (TX) : {} (Total: {}) ",
        format_rate(app.total_tx_rate),
        format_bytes(app.cumulative_tx)
    );
    let tx_sparkline = Sparkline::default()
        .block(
            Block::default()
                .borders(Borders::ALL)
                .title(tx_title)
                .style(Style::default().fg(Color::LightMagenta)),
        )
        .data(&tx_data)
        .style(Style::default().fg(Color::LightMagenta));
    frame.render_widget(tx_sparkline, sparkline_chunks[1]);
}

fn render_interfaces_table(frame: &mut Frame, app: &mut App, area: Rect) {
    let selected_style = Style::default()
        .bg(Color::DarkGray)
        .fg(Color::Yellow)
        .add_modifier(Modifier::BOLD);

    let header_cells = [
        "Interface",
        "Débit RX",
        "Débit TX",
        "Total RX",
        "Total TX",
        "Paquets RX",
        "Paquets TX",
        "Erreurs RX/TX",
    ]
    .into_iter()
    .map(|h| {
        Cell::from(h).style(
            Style::default()
                .fg(Color::Yellow)
                .add_modifier(Modifier::BOLD),
        )
    });
    let header = Row::new(header_cells).height(1).bottom_margin(1);

    let rows = app.interfaces.iter().map(|item| {
        let cells = vec![
            Cell::from(item.name.clone()),
            Cell::from(format_rate(item.rx_rate_bps)).style(Style::default().fg(Color::Cyan)),
            Cell::from(format_rate(item.tx_rate_bps)).style(Style::default().fg(Color::LightMagenta)),
            Cell::from(format_bytes(item.rx_bytes)),
            Cell::from(format_bytes(item.tx_bytes)),
            Cell::from(item.rx_packets.to_string()),
            Cell::from(item.tx_packets.to_string()),
            Cell::from(format!("{}/{}", item.rx_errors, item.tx_errors)).style(
                if item.rx_errors > 0 || item.tx_errors > 0 {
                    Style::default().fg(Color::Red).add_modifier(Modifier::BOLD)
                } else {
                    Style::default().fg(Color::Green)
                },
            ),
        ];
        Row::new(cells).height(1)
    });

    let widths = [
        Constraint::Percentage(16),
        Constraint::Percentage(12),
        Constraint::Percentage(12),
        Constraint::Percentage(12),
        Constraint::Percentage(12),
        Constraint::Percentage(12),
        Constraint::Percentage(12),
        Constraint::Percentage(12),
    ];

    let table = Table::new(rows, widths)
        .header(header)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .title(" Interfaces Réseau Détectées "),
        )
        .row_highlight_style(selected_style)
        .highlight_symbol("▶ ");

    frame.render_stateful_widget(table, area, &mut app.table_state);
}

fn render_footer(frame: &mut Frame, area: Rect) {
    let footer_text = Line::from(vec![
        Span::styled(" [q / Esc] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw("Quitter  "),
        Span::styled(" [Tab / ↑ / ↓] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw("Sélectionner Interface  "),
        Span::styled(" [r] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw("Réinitialiser Graphiques  "),
    ]);

    let footer = Paragraph::new(footer_text);
    frame.render_widget(footer, area);
}

/// Nettoyage du terminal pour restaurer son état en toute circonstance
fn restore_terminal() -> Result<(), io::Error> {
    disable_raw_mode()?;
    execute!(io::stdout(), LeaveAlternateScreen)?;
    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Configuration du terminal
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let res = run_app(&mut terminal).await;

    // Restauration garantie du terminal
    if let Err(err) = restore_terminal() {
        eprintln!("Erreur lors de la restauration du terminal : {err}");
    }

    if let Err(err) = res {
        eprintln!("Erreur d'exécution de l'application : {err}");
    }

    Ok(())
}

async fn run_app(
    terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
) -> Result<(), Box<dyn std::error::Error>> {
    let mut app = App::new();
    let mut event_stream = EventStream::new();
    let mut interval = tokio::time::interval(Duration::from_millis(TICK_RATE_MS));

    loop {
        terminal.draw(|f| render_ui(f, &mut app))?;

        tokio::select! {
            _ = interval.tick() => {
                app.update_metrics();
            }
            maybe_event = event_stream.next() => {
                match maybe_event {
                    Some(Ok(event)) => {
                        if let Event::Key(key_event) = event {
                            if key_event.kind == KeyEventKind::Press {
                                match key_event.code {
                                    KeyCode::Char('q') | KeyCode::Esc => return Ok(()),
                                    KeyCode::Char('r') => app.reset_counters(),
                                    KeyCode::Tab | KeyCode::Down | KeyCode::Char('j') => app.next_interface(),
                                    KeyCode::BackTab | KeyCode::Up | KeyCode::Char('k') => app.previous_interface(),
                                    _ => {}
                                }
                            }
                        }
                    }
                    Some(Err(e)) => return Err(Box::new(e)),
                    None => break,
                }
            }
        }
    }

    Ok(())
}

