```rust
// src/main.rs
use anyhow::{Context, Result};
use crossterm::{
    event::{self, DisableMouseCapture, EnableMouseCapture, Event, KeyCode, KeyEventKind},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::{Backend, CrosstermBackend},
    layout::{Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, List, ListItem, ListState, Paragraph, Wrap},
    Frame, Terminal,
};
use std::{
    fs::{self, File},
    io::{self, Read},
    path::PathBuf,
    time::SystemTime,
};

/// Représente une entrée de fichier ou dossier dans la vue arborescente.
#[derive(Clone, Debug)]
struct FileItem {
    name: String,
    path: PathBuf,
    is_dir: bool,
    size: u64,
    modified: Option<SystemTime>,
    readonly: bool,
}

/// Contenu de l'aperçu du panneau droit.
#[derive(Clone, Debug)]
enum PreviewContent {
    Empty,
    DirectorySummary {
        total_items: usize,
        dir_count: usize,
        file_count: usize,
        entries_sample: Vec<String>,
    },
    TextFile {
        lines: Vec<String>,
        truncated: bool,
    },
    BinaryFile {
        size: u64,
    },
    Error(String),
}

/// État global de l'application.
struct App {
    current_dir: PathBuf,
    items: Vec<FileItem>,
    list_state: ListState,
    preview: PreviewContent,
    show_hidden: bool,
    status_message: Option<String>,
}

impl App {
    fn new(start_path: PathBuf) -> Result<Self> {
        let canonical = fs::canonicalize(&start_path)
            .unwrap_or(start_path);

        let mut app = Self {
            current_dir: canonical,
            items: Vec::new(),
            list_state: ListState::default(),
            preview: PreviewContent::Empty,
            show_hidden: false,
            status_message: None,
        };

        app.refresh_directory()?;
        Ok(app)
    }

    /// Recharge la liste des éléments du répertoire courant.
    fn refresh_directory(&mut self) -> Result<()> {
        let read_dir = match fs::read_dir(&self.current_dir) {
            Ok(rd) => rd,
            Err(e) => {
                self.status_message = Some(format!("Erreur d'accès au dossier : {e}"));
                self.items.clear();
                self.list_state.select(None);
                self.preview = PreviewContent::Error(e.to_string());
                return Ok(());
            }
        };

        let mut items = Vec::new();

        for entry_res in read_dir {
            if let Ok(entry) = entry_res {
                let name = entry.file_name().to_string_lossy().to_string();
                if !self.show_hidden && name.starts_with('.') {
                    continue;
                }

                let path = entry.path();
                let metadata = entry.metadata().ok();
                let is_dir = metadata.as_ref().map(|m| m.is_dir()).unwrap_or(false);
                let size = metadata.as_ref().map(|m| m.len()).unwrap_or(0);
                let modified = metadata.as_ref().and_then(|m| m.modified().ok());
                let readonly = metadata.as_ref().map(|m| m.permissions().readonly()).unwrap_or(false);

                items.push(FileItem {
                    name,
                    path,
                    is_dir,
                    size,
                    modified,
                    readonly,
                });
            }
        }

        // Tri : dossiers en premier, puis ordre alphabétique insensible à la casse
        items.sort_by(|a, b| {
            b.is_dir
                .cmp(&a.is_dir)
                .then_with(|| a.name.to_lowercase().cmp(&b.name.to_lowercase()))
        });

        self.items = items;

        if self.items.is_empty() {
            self.list_state.select(None);
            self.preview = PreviewContent::Empty;
        } else {
            let current_idx = self.list_state.selected().unwrap_or(0);
            let next_idx = current_idx.min(self.items.len().saturating_sub(1));
            self.list_state.select(Some(next_idx));
            self.update_preview();
        }

        self.status_message = None;
        Ok(())
    }

    /// Met à jour l'aperçu du fichier ou dossier actuellement sélectionné.
    fn update_preview(&mut self) {
        let Some(idx) = self.list_state.selected() else {
            self.preview = PreviewContent::Empty;
            return;
        };

        let Some(item) = self.items.get(idx) else {
            self.preview = PreviewContent::Empty;
            return;
        };

        if item.is_dir {
            match fs::read_dir(&item.path) {
                Ok(read_dir) => {
                    let mut dir_count = 0;
                    let mut file_count = 0;
                    let mut sample = Vec::new();

                    for child in read_dir.flatten() {
                        let is_d = child.metadata().map(|m| m.is_dir()).unwrap_or(false);
                        if is_d {
                            dir_count += 1;
                        } else {
                            file_count += 1;
                        }

                        if sample.len() < 15 {
                            let prefix = if is_d { "📁 " } else { "📄 " };
                            sample.push(format!("{}{}", prefix, child.file_name().to_string_lossy()));
                        }
                    }

                    self.preview = PreviewContent::DirectorySummary {
                        total_items: dir_count + file_count,
                        dir_count,
                        file_count,
                        entries_sample: sample,
                    };
                }
                Err(e) => {
                    self.preview = PreviewContent::Error(format!("Accès refusé au répertoire : {e}"));
                }
            }
        } else {
            // Lecture du fichier (avec limite de taille de 128 Ko pour la sécurité en mémoire)
            const MAX_READ_BYTES: u64 = 128 * 1024;
            let mut file = match File::open(&item.path) {
                Ok(f) => f,
                Err(e) => {
                    self.preview = PreviewContent::Error(format!("Impossible d'ouvrir le fichier : {e}"));
                    return;
                }
            };

            let mut buffer = Vec::new();
            let mut handle = (&mut file).take(MAX_READ_BYTES);
            if let Err(e) = handle.read_to_end(&mut buffer) {
                self.preview = PreviewContent::Error(format!("Erreur lors de la lecture : {e}"));
                return;
            }

            // Vérification binaire simple : présence d'octets nuls
            if buffer.contains(&0) {
                self.preview = PreviewContent::BinaryFile { size: item.size };
            } else {
                match String::from_utf8(buffer) {
                    Ok(text) => {
                        let lines: Vec<String> = text.lines().take(120).map(|s| s.to_string()).collect();
                        let truncated = item.size > MAX_READ_BYTES;
                        self.preview = PreviewContent::TextFile { lines, truncated };
                    }
                    Err(_) => {
                        self.preview = PreviewContent::BinaryFile { size: item.size };
                    }
                }
            }
        }
    }

    /// Déplacement du curseur vers le bas.
    fn next_item(&mut self) {
        if self.items.is_empty() {
            return;
        }
        let i = match self.list_state.selected() {
            Some(i) => {
                if i >= self.items.len().saturating_sub(1) {
                    0
                } else {
                    i + 1
                }
            }
            None => 0,
        };
        self.list_state.select(Some(i));
        self.update_preview();
    }

    /// Déplacement du curseur vers le haut.
    fn previous_item(&mut self) {
        if self.items.is_empty() {
            return;
        }
        let i = match self.list_state.selected() {
            Some(i) => {
                if i == 0 {
                    self.items.len().saturating_sub(1)
                } else {
                    i - 1
                }
            }
            None => 0,
        };
        self.list_state.select(Some(i));
        self.update_preview();
    }

    /// Entrer dans le dossier sélectionné.
    fn enter_directory(&mut self) -> Result<()> {
        if let Some(idx) = self.list_state.selected() {
            if let Some(item) = self.items.get(idx) {
                if item.is_dir {
                    let target_path = item.path.clone();
                    self.current_dir = target_path;
                    self.list_state.select(Some(0));
                    self.refresh_directory()?;
                }
            }
        }
        Ok(())
    }

    /// Remonter dans le dossier parent.
    fn parent_directory(&mut self) -> Result<()> {
        if let Some(parent) = self.current_dir.parent() {
            let parent_buf = parent.to_path_buf();
            self.current_dir = parent_buf;
            self.list_state.select(Some(0));
            self.refresh_directory()?;
        }
        Ok(())
    }

    /// Basculer l'affichage des fichiers cachés.
    fn toggle_hidden(&mut self) -> Result<()> {
        self.show_hidden = !self.show_hidden;
        self.refresh_directory()?;
        Ok(())
    }

    /// Formatage lisible de la taille en octets.
    fn format_size(bytes: u64) -> String {
        const KB: u64 = 1024;
        const MB: u64 = KB * 1024;
        const GB: u64 = MB * 1024;

        if bytes >= GB {
            format!("{:.2} Go", bytes as f64 / GB as f64)
        } else if bytes >= MB {
            format!("{:.2} Mo", bytes as f64 / MB as f64)
        } else if bytes >= KB {
            format!("{:.2} Ko", bytes as f64 / KB as f64)
        } else {
            format!("{bytes} B")
        }
    }
}

fn main() -> Result<()> {
    // Configuration du terminal
    enable_raw_mode().context("Activation du raw mode impossible")?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen, EnableMouseCapture)
        .context("Initialisation du terminal alternatif échouée")?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let current_dir = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let mut app = App::new(current_dir)?;

    let run_res = run_app(&mut terminal, &mut app);

    // Restauration garantie du terminal
    disable_raw_mode().ok();
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen,
        DisableMouseCapture
    ).ok();
    terminal.show_cursor().ok();

    if let Err(err) = run_res {
        eprintln!("Erreur lors de l'exécution : {err:?}");
    }

    Ok(())
}

fn run_app<B: Backend>(terminal: &mut Terminal<B>, app: &mut App) -> Result<()> {
    loop {
        terminal.draw(|f| ui(f, app))?;

        if let Event::Key(key) = event::read()? {
            if key.kind != KeyEventKind::Press {
                continue;
            }

            match key.code {
                KeyCode::Char('q') | KeyCode::Esc => return Ok(()),
                KeyCode::Down | KeyCode::Char('j') => app.next_item(),
                KeyCode::Up | KeyCode::Char('k') => app.previous_item(),
                KeyCode::Enter | KeyCode::Right | KeyCode::Char('l') => {
                    app.enter_directory()?;
                }
                KeyCode::Backspace | KeyCode::Left | KeyCode::Char('h') => {
                    app.parent_directory()?;
                }
                KeyCode::Char('.') => {
                    app.toggle_hidden()?;
                }
                KeyCode::Char('r') => {
                    app.refresh_directory()?;
                }
                _ => {}
            }
        }
    }
}

fn ui(f: &mut Frame, app: &App) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // Header
            Constraint::Min(5),    // Corps principal (Arbre + Aperçu)
            Constraint::Length(3), // Status bar / footer
        ])
        .split(f.area());

    render_header(f, app, chunks[0]);
    render_main_panel(f, app, chunks[1]);
    render_footer(f, app, chunks[2]);
}

fn render_header(f: &mut Frame, app: &App, area: Rect) {
    let dir_display = app.current_dir.display().to_string();
    let hidden_status = if app.show_hidden { "[Cachés: VISIBLE]" } else { "[Cachés: MASQUÉ]" };

    let header_text = vec![
        Line::from(vec![
            Span::styled(" Explorateur TUI ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
            Span::styled(format!(" {hidden_status} "), Style::default().fg(Color::Yellow)),
            Span::raw(" - Chemin : "),
            Span::styled(dir_display, Style::default().fg(Color::Green).add_modifier(Modifier::UNDERLINED)),
        ]),
        Line::from(vec![
            Span::styled(" [↑/k, ↓/j] ", Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
            Span::raw("Naviguer | "),
            Span::styled("[Enter/→/l] ", Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
            Span::raw("Ouvrir | "),
            Span::styled("[Backspace/←/h] ", Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
            Span::raw("Parent | "),
            Span::styled("[.] ", Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
            Span::raw("Cachés | "),
            Span::styled("[r] ", Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
            Span::raw("Rafraîchir | "),
            Span::styled("[q/Esc] ", Style::default().fg(Color::Red).add_modifier(Modifier::BOLD)),
            Span::raw("Quitter"),
        ]),
    ];

    let header_widget = Paragraph::new(header_text)
        .block(Block::default().borders(Borders::ALL).border_style(Style::default().fg(Color::DarkGray)));
    f.render_widget(header_widget, area);
}

fn render_main_panel(f: &mut Frame, app: &App, area: Rect) {
    let main_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
        .split(area);

    // Volet Gauche : Arborescence / Liste des entrées
    let items: Vec<ListItem> = app
        .items
        .iter()
        .map(|item| {
            let (icon, color) = if item.is_dir {
                ("📁 ", Color::Blue)
            } else {
                ("📄 ", Color::White)
            };

            let suffix = if item.readonly { " [RO]" } else { "" };
            let content = format!("{icon}{}{suffix}", item.name);

            ListItem::new(content).style(Style::default().fg(color))
        })
        .collect();

    let list_title = format!(" Entrées ({}) ", app.items.len());
    let list_widget = List::new(items)
        .block(
            Block::default()
                .title(list_title)
                .borders(Borders::ALL)
                .border_style(Style::default().fg(Color::Cyan)),
        )
        .highlight_style(
            Style::default()
                .bg(Color::Rgb(40, 70, 110))
                .fg(Color::Yellow)
                .add_modifier(Modifier::BOLD),
        )
        .highlight_symbol("▶ ");

    let mut state = app.list_state.clone();
    f.render_stateful_widget(list_widget, main_chunks[0], &mut state);

    // Volet Droit : Aperçu
    render_preview_panel(f, app, main_chunks[1]);
}

fn render_preview_panel(f: &mut Frame, app: &App, area: Rect) {
    let selected_name = app
        .list_state
        .selected()
        .and_then(|idx| app.items.get(idx))
        .map(|item| item.name.as_str())
        .unwrap_or("Aucune sélection");

    let title = format!(" Aperçu : {selected_name} ");
    let block = Block::default()
        .title(title)
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::Magenta));

    match &app.preview {
        PreviewContent::Empty => {
            let p = Paragraph::new("Aucun élément sélectionné ou dossier vide.")
                .style(Style::default().fg(Color::DarkGray))
                .block(block);
            f.render_widget(p, area);
        }
        PreviewContent::DirectorySummary {
            total_items,
            dir_count,
            file_count,
            entries_sample,
        } => {
            let mut text = vec![
                Line::from(vec![
                    Span::styled("Dossier contenant : ", Style::default().add_modifier(Modifier::BOLD)),
                    Span::styled(format!("{total_items} élément(s)"), Style::default().fg(Color::Cyan)),
                ]),
                Line::from(format!("• {dir_count} dossier(s)")),
                Line::from(format!("• {file_count} fichier(s)")),
                Line::from(""),
                Line::from(Span::styled("Éléments inclus (extrait) :", Style::default().fg(Color::Yellow))),
            ];

            if entries_sample.is_empty() {
                text.push(Line::from(Span::styled(" (Dossier vide)", Style::default().fg(Color::DarkGray))));
            } else {
                for sample in entries_sample {
                    text.push(Line::from(format!("   {sample}")));
                }
            }

            let p = Paragraph::new(text).block(block).wrap(Wrap { trim: false });
            f.render_widget(p, area);
        }
        PreviewContent::TextFile { lines, truncated } => {
            let mut display_lines = Vec::new();
            for (idx, line) in lines.iter().enumerate() {
                let num_span = Span::styled(
                    format!("{:4} │ ", idx + 1),
                    Style::default().fg(Color::DarkGray),
                );
                let line_span = Span::raw(line);
                display_lines.push(Line::from(vec![num_span, line_span]));
            }

            if *truncated {
                display_lines.push(Line::from(""));
                display_lines.push(Line::from(Span::styled(
                    "--- [Aperçu tronqué : taille maximale de lecture atteinte] ---",
                    Style::default().fg(Color::Yellow).add_modifier(Modifier::ITALIC),
                )));
            }

            let p = Paragraph::new(display_lines).block(block);
            f.render_widget(p, area);
        }
        PreviewContent::BinaryFile { size } => {
            let text = vec![
                Line::from(Span::styled("Fichier binaire détecté", Style::default().fg(Color::Red).add_modifier(Modifier::BOLD))),
                Line::from(""),
                Line::from(format!("Taille : {}", App::format_size(*size))),
                Line::from(""),
                Line::from(Span::styled("L'aperçu textuel n'est pas disponible pour ce type de fichier.", Style::default().fg(Color::DarkGray))),
            ];
            let p = Paragraph::new(text).block(block);
            f.render_widget(p, area);
        }
        PreviewContent::Error(err_msg) => {
            let text = vec![
                Line::from(Span::styled("Erreur lors de l'accès à l'élément :", Style::default().fg(Color::Red).add_modifier(Modifier::BOLD))),
                Line::from(""),
                Line::from(Span::styled(err_msg, Style::default().fg(Color::LightRed))),
            ];
            let p = Paragraph::new(text).block(block).wrap(Wrap { trim: true });
            f.render_widget(p, area);
        }
    }
}

fn render_footer(f: &mut Frame, app: &App, area: Rect) {
    let footer_content = if let Some(err) = &app.status_message {
        Line::from(vec![
            Span::styled(" ALERTE : ", Style::default().bg(Color::Red).fg(Color::White).add_modifier(Modifier::BOLD)),
            Span::raw(" "),
            Span::styled(err, Style::default().fg(Color::Red)),
        ])
    } else if let Some(idx) = app.list_state.selected() {
        if let Some(item) = app.items.get(idx) {
            let kind = if item.is_dir { "Dossier" } else { "Fichier" };
            let size_str = App::format_size(item.size);
            let time_str = item
                .modified
                .and_then(|t| t.elapsed().ok())
                .map(|dur| {
                    let secs = dur.as_secs();
                    if secs < 60 {
                        format!("il y a {secs}s")
                    } else if secs < 3600 {
                        format!("il y a {}m", secs / 60)
                    } else if secs < 86400 {
                        format!("il y a {}h", secs / 3600)
                    } else {
                        format!("il y a {}j", secs / 86400)
                    }
                })
                .unwrap_or_else(|| "N/A".to_string());

            Line::from(vec![
                Span::styled(format!(" [{kind}] "), Style::default().fg(Color::Green).add_modifier(Modifier::BOLD)),
                Span::raw("Nom : "),
                Span::styled(&item.name, Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
                Span::raw(" | Taille : "),
                Span::styled(size_str, Style::default().fg(Color::Cyan)),
                Span::raw(" | Modifié : "),
                Span::styled(time_str, Style::default().fg(Color::Yellow)),
                Span::raw(" | Droits : "),
                Span::styled(if item.readonly { "Lecture seule" } else { "Lecture/Écriture" }, Style::default().fg(Color::Magenta)),
            ])
        } else {
            Line::from(Span::raw("Aucun élément sélectionné."))
        }
    } else {
        Line::from(Span::raw("Répertoire vide."))
    };

    let footer_widget = Paragraph::new(footer_content)
        .block(Block::default().borders(Borders::ALL).border_style(Style::default().fg(Color::DarkGray)));
    f.render_widget(footer_widget, area);
}

