    fn indicator(self) -> &'static str {
        match self {
            Self::Ascending => "▲",
            Self::Descending => "▼",
        }
    }
}

#[derive(Debug, Clone)]
struct ProcessItem {
    pid: u32,
    name: String,
    cpu_usage: f32,
    mem_bytes: u64,
    mem_percent: f32,
    status: String,
}

struct App {
    system: System,
    processes: Vec<ProcessItem>,
    sort_column: SortColumn,
    sort_direction: SortDirection,
    table_state: TableState,
    should_quit: bool,
    last_refresh: Instant,
    refresh_interval: Duration,
}

impl App {
    fn new() -> Self {
        let refresh_kind = RefreshKind::nothing()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory(MemoryRefreshKind::everything())
            .with_processes(ProcessRefreshKind::everything());

        let mut system = System::new_with_specifics(refresh_kind);
        // Premier rafraîchissement pour initialiser les valeurs de CPU
        system.refresh_cpu_all();
        system.refresh_memory();
        system.refresh_processes(sysinfo::ProcessesToUpdate::All, true);

        let mut app = Self {
            system,
            processes: Vec::new(),
            sort_column: SortColumn::Cpu,
            sort_direction: SortDirection::Descending,
            table_state: TableState::default(),
            should_quit: false,
            last_refresh: Instant::now(),
            refresh_interval: Duration::from_millis(1000),
        };

        app.update_process_list();
        if !app.processes.is_empty() {
            app.table_state.select(Some(0));
        }

        app
    }

    fn refresh_metrics(&mut self) {
        self.system.refresh_cpu_all();
        self.system.refresh_memory();
        self.system.refresh_processes(sysinfo::ProcessesToUpdate::All, true);
        self.update_process_list();
        self.last_refresh = Instant::now();
    }

    fn update_process_list(&mut self) {
        let total_memory = self.system.total_memory() as f32;

        let mut list: Vec<ProcessItem> = self
            .system
            .processes()
            .iter()
            .map(|(pid, proc_info)| {
                let pid_u32 = pid.as_u32();
                let name = proc_info.name().to_string_lossy().into_owned();
                let cpu_usage = proc_info.cpu_usage();
                let mem_bytes = proc_info.memory();
                let mem_percent = if total_memory > 0.0 {
                    (mem_bytes as f32 / total_memory) * 100.0
                } else {
                    0.0
                };
                let status = format!("{:?}", proc_info.status());

                ProcessItem {
                    pid: pid_u32,
                    name,
                    cpu_usage,
                    mem_bytes,
                    mem_percent,
                    status,
                }
            })
            .collect();

        Self::sort_items_slice(self.sort_column, self.sort_direction, &mut list);
        self.processes = list;

        // Ajuster l'index sélectionné si la taille a changé
        if let Some(selected) = self.table_state.selected() {
            if self.processes.is_empty() {
                self.table_state.select(None);
            } else if selected >= self.processes.len() {
                self.table_state.select(Some(self.processes.len() - 1));
            }
        } else if !self.processes.is_empty() {
            self.table_state.select(Some(0));
        }
    }

    fn sort_items_slice(column: SortColumn, direction: SortDirection, list: &mut [ProcessItem]) {
        list.sort_by(|a, b| {
            let ordering = match column {
                SortColumn::Cpu => a
                    .cpu_usage
                    .partial_cmp(&b.cpu_usage)
                    .unwrap_or(Ordering::Equal),
                SortColumn::Memory => a.mem_bytes.cmp(&b.mem_bytes),
                SortColumn::Pid => a.pid.cmp(&b.pid),
                SortColumn::Name => a.name.to_lowercase().cmp(&b.name.to_lowercase()),
            };

            match direction {
                SortDirection::Ascending => ordering,
                SortDirection::Descending => ordering.reverse(),
            }
        });
    }

    fn sort_processes(&mut self) {
        Self::sort_items_slice(self.sort_column, self.sort_direction, &mut self.processes);
    }

    fn set_sort(&mut self, column: SortColumn) {
        if self.sort_column == column {
            self.sort_direction = self.sort_direction.toggle();
        } else {
            self.sort_column = column;
            self.sort_direction = match column {
                SortColumn::Cpu | SortColumn::Memory => SortDirection::Descending,
                SortColumn::Pid | SortColumn::Name => SortDirection::Ascending,
            };
        }
        self.sort_processes();
    }

    fn next_process(&mut self) {
        if self.processes.is_empty() {
            return;
        }
        let i = match self.table_state.selected() {
            Some(i) => {
                if i + 1 >= self.processes.len() {
                    0
                } else {
                    i + 1
                }
            }
            None => 0,
        };
        self.table_state.select(Some(i));
    }

    fn previous_process(&mut self) {
        if self.processes.is_empty() {
            return;
        }
        let i = match self.table_state.selected() {
            Some(i) => {
                if i == 0 {
                    self.processes.len() - 1
                } else {
                    i - 1
                }
            }
            None => 0,
        };
        self.table_state.select(Some(i));
    }
}

fn main() -> Result<()> {
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut app = App::new();
    let res = run_app(&mut terminal, &mut app);

    // Restauration propre du terminal dans tous les cas
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    if let Err(err) = res {
        eprintln!("Erreur lors de l'exécution: {err}");
    }

    Ok(())
}

fn run_app<B: Backend>(terminal: &mut Terminal<B>, app: &mut App) -> Result<()> {
    loop {
        terminal.draw(|f| ui(f, app))?;

        let timeout = app
            .refresh_interval
            .saturating_sub(app.last_refresh.elapsed());

        if event::poll(timeout)? {
            if let Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press {
                    match key.code {
                        KeyCode::Char('q') | KeyCode::Esc => {
                            app.should_quit = true;
                        }
                        KeyCode::Down | KeyCode::Char('j') => {
                            app.next_process();
                        }
                        KeyCode::Up | KeyCode::Char('k') => {
                            app.previous_process();
                        }
                        KeyCode::Char('c') | KeyCode::Char('1') => {
                            app.set_sort(SortColumn::Cpu);
                        }
                        KeyCode::Char('m') | KeyCode::Char('2') => {
                            app.set_sort(SortColumn::Memory);
                        }
                        KeyCode::Char('p') | KeyCode::Char('3') => {
                            app.set_sort(SortColumn::Pid);
                        }
                        KeyCode::Char('n') | KeyCode::Char('4') => {
                            app.set_sort(SortColumn::Name);
                        }
                        KeyCode::Tab | KeyCode::Char('r') => {
                            app.sort_direction = app.sort_direction.toggle();
                            app.sort_processes();
                        }
                        _ => {}
                    }
                }
            }
        }

        if app.last_refresh.elapsed() >= app.refresh_interval {
            app.refresh_metrics();
        }

        if app.should_quit {
            return Ok(());
        }
    }
}

fn ui(f: &mut Frame, app: &mut App) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(5), // Section Métriques globales (CPU / RAM)
            Constraint::Min(5),    // Table des processus
            Constraint::Length(3), // Barre d'aide / raccourcis
        ])
        .split(f.area());

    draw_header(f, app, chunks[0]);
    draw_process_table(f, app, chunks[1]);
    draw_footer(f, chunks[2]);
}

fn draw_header(f: &mut Frame, app: &App, area: Rect) {
    let sub_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
        .split(area);

    // CPU Global
    let global_cpu = app.system.global_cpu_usage();
    let cpu_gauge = Gauge::default()
        .block(
            Block::default()
                .title(" CPU Global ")
                .borders(Borders::ALL)
                .border_style(Style::default().fg(Color::Cyan)),
        )
        .gauge_style(
            Style::default()
                .fg(if global_cpu > 80.0 {
                    Color::Red
                } else if global_cpu > 50.0 {
                    Color::Yellow
                } else {
                    Color::Green
                })
                .add_modifier(Modifier::BOLD),
        )
        .percent(global_cpu.clamp(0.0, 100.0) as u16)
        .label(format!("{:.1}%", global_cpu));

    f.render_widget(cpu_gauge, sub_chunks[0]);

    // Mémoire RAM
    let used_mem_mb = app.system.used_memory() as f64 / 1024.0 / 1024.0;
    let total_mem_mb = app.system.total_memory() as f64 / 1024.0 / 1024.0;
    let mem_percent = if total_mem_mb > 0.0 {
        ((used_mem_mb / total_mem_mb) * 100.0).clamp(0.0, 100.0)
    } else {
        0.0
    };

    let mem_gauge = Gauge::default()
        .block(
            Block::default()
                .title(" Mémoire (RAM) ")
                .borders(Borders::ALL)
                .border_style(Style::default().fg(Color::Magenta)),
        )
        .gauge_style(
            Style::default()
                .fg(if mem_percent > 85.0 {
                    Color::Red
                } else if mem_percent > 65.0 {
                    Color::Yellow
                } else {
                    Color::Blue
                })
                .add_modifier(Modifier::BOLD),
        )
        .percent(mem_percent as u16)
        .label(format!("{:.0} Mo / {:.0} Mo ({:.1}%)", used_mem_mb, total_mem_mb, mem_percent));

    f.render_widget(mem_gauge, sub_chunks[1]);
}

fn draw_process_table(f: &mut Frame, app: &mut App, area: Rect) {
    let header_titles = [
        format!(
            "PID {}",
            if app.sort_column == SortColumn::Pid {
                app.sort_direction.indicator()
            } else {
                ""
            }
        ),
        format!(
            "Nom {}",
            if app.sort_column == SortColumn::Name {
                app.sort_direction.indicator()
            } else {
                ""
            }
        ),
        format!(
            "CPU % {}",
            if app.sort_column == SortColumn::Cpu {
                app.sort_direction.indicator()
            } else {
                ""
            }
        ),
        format!(
            "Mémoire % {}",
            if app.sort_column == SortColumn::Memory {
                app.sort_direction.indicator()
            } else {
                ""
            }
        ),
        "Mémoire (Mo)".to_string(),
        "Statut".to_string(),
    ];

    let header = Row::new(header_titles)
        .style(
            Style::default()
                .fg(Color::Yellow)
                .add_modifier(Modifier::BOLD),
        )
        .bottom_margin(1);

    let rows: Vec<Row> = app
        .processes
        .iter()
        .map(|proc_item| {
            let mem_mb = proc_item.mem_bytes as f64 / 1024.0 / 1024.0;
            let cpu_color = if proc_item.cpu_usage > 50.0 {
                Color::Red
            } else if proc_item.cpu_usage > 15.0 {
                Color::Yellow
            } else {
                Color::White
            };

            Row::new(vec![
                proc_item.pid.to_string(),
                proc_item.name.clone(),
                format!("{:.1}%", proc_item.cpu_usage),
                format!("{:.1}%", proc_item.mem_percent),
                format!("{:.1}", mem_mb),
                proc_item.status.clone(),
            ])
            .style(Style::default().fg(cpu_color))
        })
        .collect();

    let title = format!(" Processus ({}) ", app.processes.len());
    let table = Table::new(
        rows,
        [
            Constraint::Length(8),  // PID
            Constraint::Percentage(35), // Nom
            Constraint::Length(10), // CPU %
            Constraint::Length(12), // MEM %
            Constraint::Length(14), // MEM (Mo)
            Constraint::Length(12), // Statut
        ],
    )
    .header(header)
    .block(
        Block::default()
            .title(title)
            .borders(Borders::ALL)
            .border_style(Style::default().fg(Color::White)),
    )
    .row_highlight_style(
        Style::default()
            .bg(Color::DarkGray)
            .fg(Color::Cyan)
            .add_modifier(Modifier::BOLD),
    )
    .highlight_symbol(">> ");

    f.render_stateful_widget(table, area, &mut app.table_state);
}

fn draw_footer(f: &mut Frame, area: Rect) {
    let help_text = " [q/Esc]: Quitter | [↑/↓ ou k/j]: Naviguer | [c]: Tri CPU | [m]: Tri RAM | [p]: Tri PID | [n]: Tri Nom | [r/Tab]: Inverser tri";
    let footer = Paragraph::new(help_text).block(
        Block::default()
            .borders(Borders::ALL)
            .title(" Raccourcis ")
            .border_style(Style::default().fg(Color::DarkGray)),
    );
    f.render_widget(footer, area);
}

