/// État global de l'application
pub struct App {
    pub entries: Vec<LogEntry>,
    pub filtered_indices: Vec<usize>,
    pub search_query: String,
    pub scroll_offset: usize,
    pub selected_index: usize,
    pub auto_follow: bool,
    pub mode: AppMode,
    pub should_quit: bool,
    pub source_name: String,
    pub search_regex: Option<Regex>,
    pub last_tick: Instant,
    pub simulated_traffic: bool,
    pub demo_counter: usize,
}

impl App {
    pub fn new(entries: Vec<LogEntry>, source_name: String, simulated_traffic: bool) -> Self {
        let mut app = Self {
            entries,
            filtered_indices: Vec::new(),
            search_query: String::new(),
            scroll_offset: 0,
            selected_index: 0,
            auto_follow: true,
            mode: AppMode::Normal,
            should_quit: false,
            source_name,
            search_regex: None,
            last_tick: Instant::now(),
            simulated_traffic,
            demo_counter: 1,
        };
        app.update_filter();
        if !app.filtered_indices.is_empty() {
            app.selected_index = app.filtered_indices.len().saturating_sub(1);
        }
        app
    }

    pub fn update_filter(&mut self) {
        if self.search_query.is_empty() {
            self.search_regex = None;
            self.filtered_indices = (0..self.entries.len()).collect();
        } else {
            // Tente de compiler en Regex insensible à la casse, sinon repli sur simple sous-chaîne
            let pattern = format!("(?i){}", regex::escape(&self.search_query));
            self.search_regex = Regex::new(&pattern).ok();

            let query_lower = self.search_query.to_lowercase();
            self.filtered_indices = self
                .entries
                .iter()
                .enumerate()
                .filter(|(_, entry)| {
                    if let Some(ref re) = self.search_regex {
                        re.is_match(&entry.raw)
                    } else {
                        entry.raw.to_lowercase().contains(&query_lower)
                    }
                })
                .map(|(idx, _)| idx)
                .collect();
        }

        if self.auto_follow {
            self.scroll_to_end();
        } else {
            self.clamp_selection();
        }
    }

    pub fn scroll_to_end(&mut self) {
        if !self.filtered_indices.is_empty() {
            self.selected_index = self.filtered_indices.len().saturating_sub(1);
        } else {
            self.selected_index = 0;
        }
    }

    pub fn clamp_selection(&mut self) {
        if self.filtered_indices.is_empty() {
            self.selected_index = 0;
            self.scroll_offset = 0;
        } else if self.selected_index >= self.filtered_indices.len() {
            self.selected_index = self.filtered_indices.len().saturating_sub(1);
        }
    }

    pub fn add_log_line(&mut self, line: String) {
        let entry = LogEntry::parse(line);
        let entry_idx = self.entries.len();
        let matches = if self.search_query.is_empty() {
            true
        } else if let Some(ref re) = self.search_regex {
            re.is_match(&entry.raw)
        } else {
            entry.raw.to_lowercase().contains(&self.search_query.to_lowercase())
        };

        self.entries.push(entry);

        if matches {
            self.filtered_indices.push(entry_idx);
            if self.auto_follow {
                self.scroll_to_end();
            }
        }
    }

    pub fn stats(&self) -> (usize, usize, usize, usize, usize, usize) {
        let mut fatal = 0;
        let mut error = 0;
        let mut warn = 0;
        let mut info = 0;
        let mut debug = 0;
        let mut trace = 0;

        for &idx in &self.filtered_indices {
            if let Some(item) = self.entries.get(idx) {
                match item.level {
                    LogLevel::Fatal => fatal += 1,
                    LogLevel::Error => error += 1,
                    LogLevel::Warn => warn += 1,
                    LogLevel::Info => info += 1,
                    LogLevel::Debug => debug += 1,
                    LogLevel::Trace => trace += 1,
                    LogLevel::Unknown => {}
                }
            }
        }
        (fatal, error, warn, info, debug, trace)
    }

    pub fn inject_demo_event(&mut self) {
        let now = chrono::Local::now().format("%Y-%m-%dT%H:%M:%S%.3f").to_string();
        let demo_entries = [
            (LogLevel::Info, "server::http", "Handshake established with 192.168.1.104:443 TLSv1.3"),
            (LogLevel::Debug, "auth::jwt", "Verifying token claims: user_id=9843 session_exp=3600s"),
            (LogLevel::Warn, "db::pool", "Database connection pool saturated (38/40 active connections)"),
            (LogLevel::Info, "metrics::collector", "Exporting Prometheus metrics payload: 42 KB sent"),
            (LogLevel::Error, "storage::s3", "Timeout while uploading blob payload to bucket: s3-backups-eu"),
            (LogLevel::Trace, "kernel::net", "TCP frame received: seq=40319 ack=290 len=1420"),
            (LogLevel::Fatal, "cluster::raft", "Consensus lost: quorum degraded below threshold"),
        ];

        let (level_repr, target, msg) = demo_entries[self.demo_counter % demo_entries.len()];
        let level_name = match level_repr {
            LogLevel::Fatal => "FATAL",
            LogLevel::Error => "ERROR",
            LogLevel::Warn => "WARN ",
            LogLevel::Info => "INFO ",
            LogLevel::Debug => "DEBUG",
            LogLevel::Trace => "TRACE",
            LogLevel::Unknown => "LOG  ",
        };

        let formatted = format!("[{now}] {level_name} [{target}] {msg} (req_id={})", self.demo_counter);
        self.demo_counter += 1;
        self.add_log_line(formatted);
    }
}

/// Helper pour restaurer le terminal à la sortie
struct TerminalGuard;

impl Drop for TerminalGuard {
    fn drop(&mut self) {
        let _ = disable_raw_mode();
        let _ = execute!(stdout(), LeaveAlternateScreen);
    }
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();
    let (entries, source_name, simulated) = if args.len() > 1 {
        let path = &args[1];
        match File::open(path) {
            Ok(file) => {
                let reader = BufReader::new(file);
                let logs: Vec<LogEntry> = reader
                    .lines()
                    .map_while(Result::ok)
                    .map(LogEntry::parse)
                    .collect();
                (logs, path.clone(), false)
            }
            Err(e) => {
                eprintln!("Erreur lors de l'ouverture du fichier {}: {}", path, e);
                return Err(e);
            }
        }
    } else {
        // Jeu de logs de démarrage
        let mut initial_logs = Vec::new();
        let demo_samples = vec![
            "[2026-09-27T20:15:00.120] INFO  [system::init] Booting asynchronous kernel runtime v2.4.0",
            "[2026-09-27T20:15:00.345] DEBUG [memory::alloc] Pre-allocating virtual arena (capacity=512MB)",
            "[2026-09-27T20:15:01.012] INFO  [network::bind] Listening on TCP 0.0.0.0:8080 (IPv4)",
            "[2026-09-27T20:15:01.210] TRACE [network::route] Subnet routing table initialized with 6 entries",
            "[2026-09-27T20:15:02.890] WARN  [config::loader] Fallback configuration active: certificate expires in 3 days",
            "[2026-09-27T20:15:03.111] INFO  [worker::pool] Spawned 8 worker threads across 4 core complexes",
            "[2026-09-27T20:15:04.550] ERROR [redis::client] Connection refused: tcp://127.0.0.1:6379",
            "[2026-09-27T20:15:05.102] WARN  [redis::client] Retrying Redis connection (attempt 1 of 5)...",
            "[2026-09-27T20:15:06.001] INFO  [redis::client] Reconnected successfully to fallback sentinel node",
            "[2026-09-27T20:15:07.412] DEBUG [auth::session] Session cache warm: 120 tokens loaded",
            "[2026-09-27T20:15:09.123] ERROR [api::v1::checkout] Payment gateway 504 Gateway Timeout for order #8849",
            "[2026-09-27T20:15:10.054] FATAL [kernel::panic] Critical disk latency detected on /dev/nvme0n1p3",
        ];
        for sample in demo_samples {
            initial_logs.push(LogEntry::parse(sample.to_string()));
        }
        (initial_logs, "Flux démo direct".to_string(), true)
    };

    // Configuration du terminal
    enable_raw_mode()?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let _guard = TerminalGuard;

    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut app = App::new(entries, source_name, simulated);

    // Boucle d'événements
    run_app(&mut terminal, &mut app)?;

    Ok(())
}

fn run_app(terminal: &mut Terminal<CrosstermBackend<Stdout>>, app: &mut App) -> io::Result<()> {
    let tick_rate = Duration::from_millis(50);
    let mut demo_timer = Instant::now();

    while !app.should_quit {
        terminal.draw(|f| ui(f, app))?;

        let timeout = tick_rate
            .checked_sub(app.last_tick.elapsed())
            .unwrap_or_else(|| Duration::from_secs(0));

        if event::poll(timeout)? {
            if let Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press {
                    handle_key_event(app, key.code, key.modifiers);
                }
            }
        }

        if app.last_tick.elapsed() >= tick_rate {
            app.last_tick = Instant::now();
        }

        // Si en mode démo, injecter un nouvel événement toutes les 2.5 secondes
        if app.simulated_traffic && demo_timer.elapsed() >= Duration::from_millis(2500) {
            demo_timer = Instant::now();
            app.inject_demo_event();
        }
    }

    Ok(())
}

fn handle_key_event(app: &mut App, code: KeyCode, modifiers: KeyModifiers) {
    // Interception globale de sortie
    if modifiers.contains(KeyModifiers::CONTROL) && code == KeyCode::Char('c') {
        app.should_quit = true;
        return;
    }

    match app.mode {
        AppMode::Normal => match code {
            KeyCode::Char('q') | KeyCode::Esc => app.should_quit = true,
            KeyCode::Char('/') => {
                app.mode = AppMode::Search;
            }
            KeyCode::Char('?') | KeyCode::Char('h') => {
                app.mode = AppMode::Help;
            }
            KeyCode::Char('f') => {
                app.auto_follow = !app.auto_follow;
                if app.auto_follow {
                    app.scroll_to_end();
                }
            }
            KeyCode::Char('c') => {
                app.search_query.clear();
                app.update_filter();
            }
            KeyCode::Char('j') | KeyCode::Down => {
                app.auto_follow = false;
                if !app.filtered_indices.is_empty()
                    && app.selected_index + 1 < app.filtered_indices.len()
                {
                    app.selected_index += 1;
                }
            }
            KeyCode::Char('k') | KeyCode::Up => {
                app.auto_follow = false;
                if app.selected_index > 0 {
                    app.selected_index -= 1;
                }
            }
            KeyCode::PageDown => {
                app.auto_follow = false;
                if !app.filtered_indices.is_empty() {
                    app.selected_index = (app.selected_index + 10).min(app.filtered_indices.len() - 1);
                }
            }
            KeyCode::PageUp => {
                app.auto_follow = false;
                app.selected_index = app.selected_index.saturating_sub(10);
            }
            KeyCode::Char('g') | KeyCode::Home => {
                app.auto_follow = false;
                app.selected_index = 0;
            }
            KeyCode::Char('G') | KeyCode::End => {
                app.scroll_to_end();
            }
            _ => {}
        },
        AppMode::Search => match code {
            KeyCode::Enter | KeyCode::Esc => {
                app.mode = AppMode::Normal;
            }
            KeyCode::Backspace => {
                app.search_query.pop();
                app.update_filter();
            }
            KeyCode::Char(c) => {
                app.search_query.push(c);
                app.update_filter();
            }
            _ => {}
        },
        AppMode::Help => match code {
            KeyCode::Esc | KeyCode::Char('q') | KeyCode::Char('?') | KeyCode::Char('h') | KeyCode::Enter => {
                app.mode = AppMode::Normal;
            }
            _ => {}
        },
    }
}

/// Rendu complet de l'interface utilisateur
fn ui(f: &mut Frame, app: &mut App) {
    let size = f.area();

    // Découpage vertical : En-tête (3) + Zone principale (Min) + Barre de recherche (3) + Barre d'état (1)
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3),
            Constraint::Min(5),
            Constraint::Length(3),
            Constraint::Length(1),
        ])
        .split(size);

    render_header(f, app, chunks[0]);
    render_log_viewer(f, app, chunks[1]);
    render_search_bar(f, app, chunks[2]);
    render_status_bar(f, app, chunks[3]);

    if app.mode == AppMode::Help {
        render_help_modal(f, size);
    }
}

/// En-tête applicatif
fn render_header(f: &mut Frame, app: &App, area: Rect) {
    let follow_label = if app.auto_follow {
        Span::styled(" [AUTO-FOLLOW ON] ", Style::default().fg(Color::Black).bg(Color::Green).add_modifier(Modifier::BOLD))
    } else {
        Span::styled(" [MANUEL] ", Style::default().fg(Color::DarkGray).bg(Color::White))
    };

    let title_line = Line::from(vec![
        Span::styled(" 🔍 Ratatui Log Viewer ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
        Span::styled(format!("— Source: {} ", app.source_name), Style::default().fg(Color::Gray)),
        follow_label,
    ]);

    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(Style::default().fg(Color::Blue));

    let paragraph = Paragraph::new(title_line).block(block);
    f.render_widget(paragraph, area);
}

/// Zone centrale de visualisation des logs
fn render_log_viewer(f: &mut Frame, app: &mut App, area: Rect) {
    let inner_height = area.height.saturating_sub(2) as usize; // Déduit les bordures
    let total_items = app.filtered_indices.len();

    // Calcul de la fenêtre glissante pour l'affichage (scroll dynamique)
    if total_items == 0 {
        app.scroll_offset = 0;
    } else {
        if app.selected_index < app.scroll_offset {
            app.scroll_offset = app.selected_index;
        } else if app.selected_index >= app.scroll_offset + inner_height {
            app.scroll_offset = app.selected_index + 1 - inner_height;
        }
    }

    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(Style::default().fg(Color::White))
        .title(format!(
            " Journaux (Visibles: {}/{} | Index: {}) ",
            app.filtered_indices.len(),
            app.entries.len(),
            if total_items > 0 { app.selected_index + 1 } else { 0 }
        ));

    f.render_widget(block.clone(), area);
    let inner_area = block.inner(area);

    if total_items == 0 {
        let empty_msg = Paragraph::new("Aucun événement ne correspond au filtre.")
            .style(Style::default().fg(Color::DarkGray).add_modifier(Modifier::ITALIC))
            .alignment(Alignment::Center);
        f.render_widget(empty_msg, inner_area);
        return;
    }

    let end_index = (app.scroll_offset + inner_height).min(total_items);
    let visible_indices = &app.filtered_indices[app.scroll_offset..end_index];

    let mut lines = Vec::with_capacity(visible_indices.len());
    for (i, &log_idx) in visible_indices.iter().enumerate() {
        let is_selected = (app.scroll_offset + i) == app.selected_index;
        let entry = &app.entries[log_idx];
        let line_spans = highlight_log_syntax(&entry.raw, entry.level, &app.search_query, is_selected);
        lines.push(Line::from(line_spans));
    }

    let logs_paragraph = Paragraph::new(lines).wrap(Wrap { trim: false });
    f.render_widget(logs_paragraph, inner_area);

    // Barre de défilement verticale
    let mut scrollbar_state = ScrollbarState::default()
        .content_length(total_items)
        .position(app.selected_index);

    let scrollbar = Scrollbar::default()
        .orientation(ScrollbarOrientation::VerticalRight)
        .begin_symbol(Some("▲"))
        .end_symbol(Some("▼"));

    f.render_stateful_widget(scrollbar, area, &mut scrollbar_state);
}

/// Découpe et met en valeur la syntaxe du log (horodatage, niveau, cible, recherche)
fn highlight_log_syntax<'a>(
    raw: &'a str,
    level: LogLevel,
    search_query: &str,
    is_selected: bool,
) -> Vec<Span<'a>> {
    let prefix = if is_selected { "▶ " } else { "  " };
    let base_style = if is_selected {
        Style::default().bg(Color::Rgb(30, 45, 65))
    } else {
        Style::default()
    };

    let mut spans = Vec::new();
    spans.push(Span::styled(
        prefix,
        if is_selected {
            Style::default().fg(Color::Yellow).bg(Color::Rgb(30, 45, 65)).add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(Color::DarkGray)
        },
    ));

    // Découpage en jetons basiques : Horodatage, Niveau, Module, Reste
    // Exemple type : "[2026-09-27T20:15:00.120] INFO [module] Message"
    let mut rest = raw;

    // Détection de l'horodatage initial [YYYY-MM-DD...]
    if rest.starts_with('[') {
        if let Some(end_bracket) = rest.find(']') {
            let timestamp_str = &rest[0..=end_bracket];
            spans.push(Span::styled(
                timestamp_str,
                base_style.fg(Color::Cyan).add_modifier(Modifier::DIM),
            ));
            rest = &rest[end_bracket + 1..];
        }
    }

    // Coloration du niveau de sévérité
    let level_str = match level {
        LogLevel::Fatal => "FATAL",
        LogLevel::Error => "ERROR",
        LogLevel::Warn => "WARN",
        LogLevel::Info => "INFO",
        LogLevel::Debug => "DEBUG",
        LogLevel::Trace => "TRACE",
        LogLevel::Unknown => "",
    };

    if !level_str.is_empty() {
        if let Some(pos) = rest.find(level_str) {
            let before = &rest[..pos];
            if !before.is_empty() {
                spans.push(Span::styled(before, base_style.fg(Color::Reset)));
            }
            let lvl_text = &rest[pos..pos + level_str.len()];
            spans.push(Span::styled(lvl_text, level.to_style()));
            rest = &rest[pos + level_str.len()..];
        }
    }

    // Coloration du reste de la ligne avec surlignage de la recherche en direct
    if search_query.is_empty() {
        spans.push(Span::styled(rest, base_style.fg(Color::Reset)));
    } else {
        let query_lower = search_query.to_lowercase();
        let mut curr = rest;

        while let Some(match_idx) = curr.to_lowercase().find(&query_lower) {
            let before = &curr[..match_idx];
            if !before.is_empty() {
                spans.push(Span::styled(before, base_style.fg(Color::Reset)));
            }

            let matched = &curr[match_idx..match_idx + search_query.len()];
            spans.push(Span::styled(
                matched,
                base_style
                    .fg(Color::Black)
                    .bg(Color::Yellow)
                    .add_modifier(Modifier::BOLD | Modifier::UNDERLINED),
            ));

            curr = &curr[match_idx + search_query.len()..];
        }

        if !curr.is_empty() {
            spans.push(Span::styled(curr, base_style.fg(Color::Reset)));
        }
    }

    spans
}

/// Barre de saisie de recherche en direct
fn render_search_bar(f: &mut Frame, app: &App, area: Rect) {
    let (border_color, mode_badge) = match app.mode {
        AppMode::Search => (Color::Yellow, " 📝 ÉDITION (Entrée/Échap pour valider) "),
        _ => (Color::DarkGray, " 🔍 Filtrer (Appuyez sur '/' pour éditer) "),
    };

    let search_text = if app.search_query.is_empty() && app.mode != AppMode::Search {
        Line::from(vec![
            Span::styled("Tapez ", Style::default().fg(Color::DarkGray)),
            Span::styled("/", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
            Span::styled(" pour filtrer en temps réel (ex: ERROR, timeout, worker)...", Style::default().fg(Color::DarkGray)),
        ])
    } else {
        let cursor = if app.mode == AppMode::Search { "█" } else { "" };
        Line::from(vec![
            Span::styled("Filtre: ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
            Span::styled(&app.search_query, Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
            Span::styled(cursor, Style::default().fg(Color::Yellow)),
