/// Définition et état en temps réel d'un microservice
#[derive(Debug, Clone)]
pub struct ServiceTarget {
    pub name: String,
    pub url: String,
    pub check_interval: Duration,
    pub timeout: Duration,
    pub status: HealthStatus,
    pub last_status_code: Option<u16>,
    pub last_latency_ms: Option<u128>,
    pub total_pings: u64,
    pub successful_pings: u64,
    pub last_checked: Option<chrono::DateTime<Local>>,
}

impl ServiceTarget {
    pub fn new(name: &str, url: &str, interval_secs: u64, timeout_secs: u64) -> Self {
        Self {
            name: name.to_string(),
            url: url.to_string(),
            check_interval: Duration::from_secs(interval_secs),
            timeout: Duration::from_secs(timeout_secs),
            status: HealthStatus::Unknown,
            last_status_code: None,
            last_latency_ms: None,
            total_pings: 0,
            successful_pings: 0,
            last_checked: None,
        }
    }

    pub fn availability_ratio(&self) -> f64 {
        if self.total_pings == 0 {
            0.0
        } else {
            (self.successful_pings as f64) / (self.total_pings as f64)
        }
    }

    pub fn availability_percent(&self) -> u16 {
        (self.availability_ratio() * 100.0).round().clamp(0.0, 100.0) as u16
    }
}

/// Événement de mise à jour provenant des sondes asynchrones
#[derive(Debug)]
pub enum ProbeEvent {
    CheckCompleted {
        index: usize,
        status: HealthStatus,
        status_code: Option<u16>,
        latency_ms: u128,
        success: bool,
        error_message: Option<String>,
    },
    LogMessage(String),
}

/// État global de l'application
pub struct AppState {
    pub services: Vec<ServiceTarget>,
    pub logs: Vec<String>,
    pub table_state: TableState,
}

impl AppState {
    pub fn new(services: Vec<ServiceTarget>) -> Self {
        let mut table_state = TableState::default();
        if !services.is_empty() {
            table_state.select(Some(0));
        }
        Self {
            services,
            logs: vec![format!(
                "[{}] Tableau de bord de surveillance initialisé.",
                Local::now().format("%H:%M:%S")
            )],
            table_state,
        }
    }

    pub fn next_service(&mut self) {
        if self.services.is_empty() {
            return;
        }
        let i = match self.table_state.selected() {
            Some(i) => {
                if i >= self.services.len().saturating_sub(1) {
                    0
                } else {
                    i + 1
                }
            }
            None => 0,
        };
        self.table_state.select(Some(i));
    }

    pub fn previous_service(&mut self) {
        if self.services.is_empty() {
            return;
        }
        let i = match self.table_state.selected() {
            Some(i) => {
                if i == 0 {
                    self.services.len().saturating_sub(1)
                } else {
                    i - 1
                }
            }
            None => 0,
        };
        self.table_state.select(Some(i));
    }

    pub fn global_availability_percent(&self) -> u16 {
        let total_pings: u64 = self.services.iter().map(|s| s.total_pings).sum();
        let total_success: u64 = self.services.iter().map(|s| s.successful_pings).sum();

        if total_pings == 0 {
            0
        } else {
            ((total_success as f64 / total_pings as f64) * 100.0)
                .round()
                .clamp(0.0, 100.0) as u16
        }
    }
}

/// Effectue une sonde HTTP unitaire
async fn probe_service(
    client: &Client,
    service: &ServiceTarget,
    index: usize,
    tx: &mpsc::Sender<ProbeEvent>,
) {
    let start = Instant::now();
    let result = client
        .get(&service.url)
        .timeout(service.timeout)
        .send()
        .await;

    let latency_ms = start.elapsed().as_millis();
    let timestamp = Local::now().format("%H:%M:%S");

    let event = match result {
        Ok(response) => {
            let status_code = response.status().as_u16();
            let is_success = response.status().is_success();

            let (health, err_msg) = if is_success {
                if latency_ms > 1200 {
                    (
                        HealthStatus::Degraded,
                        Some(format!("Latence élevée : {}ms", latency_ms)),
                    )
                } else {
                    (HealthStatus::Healthy, None)
                }
            } else {
                (
                    HealthStatus::Degraded,
                    Some(format!("Code HTTP d'alerte : {}", status_code)),
                )
            };

            let log_msg = format!(
                "[{}] {} -> HTTP {} ({} ms)",
                timestamp, service.name, status_code, latency_ms
            );
            let _ = tx.send(ProbeEvent::LogMessage(log_msg)).await;

            ProbeEvent::CheckCompleted {
                index,
                status: health,
                status_code: Some(status_code),
                latency_ms,
                success: is_success,
                error_message: err_msg,
            }
        }
        Err(err) => {
            let err_description = if err.is_timeout() {
                "Délai d'attente dépassé (Timeout)".to_string()
            } else if err.is_connect() {
                "Échec de connexion réseau".to_string()
            } else {
                err.to_string()
            };

            let log_msg = format!(
                "[{}] {} ÉCHEC : {}",
                timestamp, service.name, err_description
            );
            let _ = tx.send(ProbeEvent::LogMessage(log_msg)).await;

            ProbeEvent::CheckCompleted {
                index,
                status: HealthStatus::Down,
                status_code: None,
                latency_ms,
                success: false,
                error_message: Some(err_description),
            }
        }
    };

    let _ = tx.send(event).await;
}

/// Tâche d'arrière-plan orchestrant les pings périodiques
fn spawn_probe_worker(
    services: Vec<ServiceTarget>,
    tx: mpsc::Sender<ProbeEvent>,
    mut manual_trigger_rx: mpsc::Receiver<()>,
) {
    tokio::spawn(async move {
        let client = Client::builder()
            .user_agent("Microservice-Monitor/1.0")
            .build()
            .unwrap_or_else(|_| Client::new());

        let mut next_checks: Vec<Instant> = vec![Instant::now(); services.len()];

        loop {
            tokio::select! {
                _ = manual_trigger_rx.recv() => {
                    let _ = tx.send(ProbeEvent::LogMessage(format!(
                        "[{}] Forçage manuel du ping de tous les microservices...",
                        Local::now().format("%H:%M:%S")
                    ))).await;
                    for (i, service) in services.iter().enumerate() {
                        let client_clone = client.clone();
                        let service_clone = service.clone();
                        let tx_clone = tx.clone();
                        tokio::spawn(async move {
                            probe_service(&client_clone, &service_clone, i, &tx_clone).await;
                        });
                        next_checks[i] = Instant::now() + service.check_interval;
                    }
                }
                _ = tokio::time::sleep(Duration::from_millis(250)) => {
                    let now = Instant::now();
                    for (i, service) in services.iter().enumerate() {
                        if now >= next_checks[i] {
                            let client_clone = client.clone();
                            let service_clone = service.clone();
                            let tx_clone = tx.clone();
                            tokio::spawn(async move {
                                probe_service(&client_clone, &service_clone, i, &tx_clone).await;
                            });
                            next_checks[i] = now + service.check_interval;
                        }
                    }
                }
            }
        }
    });
}

#[tokio::main]
async fn main() -> Result<()> {
    // Liste initiale des services à surveiller
    let default_services = vec![
        ServiceTarget::new("API Gateway", "https://httpbin.org/status/200", 5, 3),
        ServiceTarget::new("Auth Service", "https://httpbin.org/status/200", 6, 3),
        ServiceTarget::new("Billing Service", "https://httpbin.org/delay/1", 8, 4),
        ServiceTarget::new("User Profile API", "https://httpbin.org/status/503", 7, 3),
        ServiceTarget::new("Inventory DB Mock", "https://127.0.0.1:65530", 5, 2),
    ];

    let app_state = Arc::new(RwLock::new(AppState::new(default_services.clone())));
    let (event_tx, mut event_rx) = mpsc::channel::<ProbeEvent>(100);
    let (manual_trigger_tx, manual_trigger_rx) = mpsc::channel::<()>(5);

    // Démarrage des sondes en arrière-plan
    spawn_probe_worker(default_services, event_tx, manual_trigger_rx);

    // Initialisation du terminal TUI
    enable_raw_mode().context("Impossible d'activer le raw mode du terminal")?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen).context("Échec EnterAlternateScreen")?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend).context("Échec création Terminal")?;

    // Boucle principale d'interaction et de rendu
    let loop_result = run_app_loop(&mut terminal, Arc::clone(&app_state), &mut event_rx, manual_trigger_tx).await;

    // Nettoyage et restauration du terminal
    disable_raw_mode().ok();
    execute!(terminal.backend_mut(), LeaveAlternateScreen).ok();
    terminal.show_cursor().ok();

    loop_result
}

async fn run_app_loop(
    terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
    app_state: Arc<RwLock<AppState>>,
    event_rx: &mut mpsc::Receiver<ProbeEvent>,
    manual_trigger_tx: mpsc::Sender<()>,
) -> Result<()> {
    let mut tick_interval = tokio::time::interval(Duration::from_millis(100));

    loop {
        // Traitement des événements de sondage en attente
        while let Ok(event) = event_rx.try_recv() {
            let mut state = app_state.write().await;
            match event {
                ProbeEvent::CheckCompleted {
                    index,
                    status,
                    status_code,
                    latency_ms,
                    success,
                    error_message: _,
                } => {
                    if let Some(target) = state.services.get_mut(index) {
                        target.status = status;
                        target.last_status_code = status_code;
                        target.last_latency_ms = Some(latency_ms);
                        target.total_pings = target.total_pings.saturating_add(1);
                        if success {
                            target.successful_pings = target.successful_pings.saturating_add(1);
                        }
                        target.last_checked = Some(Local::now());
                    }
                }
                ProbeEvent::LogMessage(msg) => {
                    state.logs.push(msg);
                    if state.logs.len() > 100 {
                        state.logs.remove(0);
                    }
                }
            }
        }

        // Rendu de l'interface
        {
            let mut state = app_state.write().await;
            terminal.draw(|f| render_ui(f, &mut state))?;
        }

        // Gestion asynchrone des entrées utilisateur crossterm & timer
        tokio::select! {
            _ = tick_interval.tick() => {
                // simple rafraîchissement d'affichage
            }
            poll_res = tokio::task::spawn_blocking(|| {
                if event::poll(Duration::from_millis(20)).unwrap_or(false) {
                    event::read().ok()
                } else {
                    None
                }
            }) => {
                if let Ok(Some(CEvent::Key(key))) = poll_res {
                    if key.kind == KeyEventKind::Press {
                        match key.code {
                            KeyCode::Char('q') | KeyCode::Esc => return Ok(()),
                            KeyCode::Down | KeyCode::Char('j') => {
                                let mut state = app_state.write().await;
                                state.next_service();
                            }
                            KeyCode::Up | KeyCode::Char('k') => {
                                let mut state = app_state.write().await;
                                state.previous_service();
                            }
                            KeyCode::Char('r') => {
                                let _ = manual_trigger_tx.send(()).await;
                            }
                            _ => {}
                        }
                    }
                }
            }
        }
    }
}

/// Affiche l'ensemble de l'interface graphique
fn render_ui(frame: &mut Frame, state: &mut AppState) {
    let size = frame.area();

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // En-tête / Titre
            Constraint::Length(3), // Jauge de disponibilité globale
            Constraint::Min(8),    // Table des services
            Constraint::Length(8), // Journal d'événements
            Constraint::Length(3), // Barre d'aide / Footer
        ])
        .split(size);

    render_header(frame, chunks[0]);
    render_global_gauge(frame, chunks[1], state);
    render_services_table(frame, chunks[2], state);
    render_logs(frame, chunks[3], state);
    render_footer(frame, chunks[4]);
}

fn render_header(frame: &mut Frame, area: Rect) {
    let current_time = Local::now().format("%Y-%m-%d %H:%M:%S").to_string();
    let header_text = vec![Line::from(vec![
        Span::styled(
            " ⚡ CLUSTER HEALTH MONITOR ",
            Style::default()
                .fg(Color::Cyan)
                .add_modifier(Modifier::BOLD),
        ),
        Span::raw(" | Surveillance temps réel des microservices | Horodatage : "),
        Span::styled(
            current_time,
            Style::default()
                .fg(Color::Yellow)
                .add_modifier(Modifier::BOLD),
        ),
    ])];

    let header_widget = Paragraph::new(header_text)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .border_style(Style::default().fg(Color::Cyan)),
        )
        .alignment(Alignment::Center);

    frame.render_widget(header_widget, area);
}

fn render_global_gauge(frame: &mut Frame, area: Rect, state: &AppState) {
    let global_percent = state.global_availability_percent();
    let color = match global_percent {
        90..=100 => Color::Green,
        70..=89 => Color::Yellow,
        _ => Color::Red,
    };

    let gauge = Gauge::default()
        .block(
            Block::default()
                .title(" Jauge de Disponibilité Globale du Système (Uptime) ")
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded),
        )
        .gauge_style(
            Style::default()
                .fg(color)
                .bg(Color::DarkGray)
                .add_modifier(Modifier::BOLD),
        )
        .percent(global_percent)
        .label(format!("Disponibilité moyenne du Cluster : {}%", global_percent));

    frame.render_widget(gauge, area);
}

fn render_services_table(frame: &mut Frame, area: Rect, state: &mut AppState) {
    let header_cells = [
        "Nom Microservice",
        "Endpoint HTTP",
        "Statut",
        "Code",
        "Latence",
        "Succès / Total",
        "Disponibilité",
    ]
    .into_iter()
    .map(|h| {
        ratatui::widgets::Cell::from(h).style(
            Style::default()
                .fg(Color::Yellow)
                .add_modifier(Modifier::BOLD),
        )
    });
    let header = Row::new(header_cells).height(1).bottom_margin(1);

    let rows: Vec<Row> = state
        .services
        .iter()
        .map(|service| {
            let status_span = Span::styled(
                format!("● {}", service.status.label()),
                Style::default()
                    .fg(service.status.color())
                    .add_modifier(Modifier::BOLD),
            );

            let status_code_str = match service.last_status_code {
                Some(code) => code.to_string(),
                None => "-".to_string(),
            };

            let latency_str = match service.last_latency_ms {
                Some(ms) => format!("{} ms", ms),
                None => "-".to_string(),
            };

            let pings_str = format!("{}/{}", service.successful_pings, service.total_pings);
            let uptime_pct = service.availability_percent();

            // Rendu visuel d'une jauge en caractères ASCII/Unicode
            let bar_len = 10;
            let filled = ((uptime_pct as usize) * bar_len) / 100;
            let bar: String = format!(
                "[{}{}] {:>3}%",
                "■".repeat(filled),
                " ".repeat(bar_len - filled),
                uptime_pct
            );

            let bar_color = match uptime_pct {
                90..=100 => Color::Green,
                70..=89 => Color::Yellow,
                _ => Color::Red,
            };

            Row::new(vec![
                ratatui::widgets::Cell::from(service.name.clone()),
                ratatui::widgets::Cell::from(service.url.clone()),
                ratatui::widgets::Cell::from(status_span),
                ratatui::widgets::Cell::from(status_code_str),
                ratatui::widgets::Cell::from(latency_str),
                ratatui::widgets::Cell::from(pings_str),
                ratatui::widgets::Cell::from(Span::styled(
                    bar,
                    Style::default().fg(bar_color).add_modifier(Modifier::BOLD),
                )),
            ])
            .height(1)
        })
        .collect();

    let table = Table::new(
        rows,
        [
            Constraint::Percentage(20),
            Constraint::Percentage(30),
            Constraint::Percentage(15),
            Constraint::Percentage(7),
            Constraint::Percentage(10),
            Constraint::Percentage(10),
            Constraint::Percentage(18),
        ],
    )
    .header(header)
    .block(
        Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .title(" État des Microservices Surveillés "),
    )
    .highlight_style(
        Style::default()
            .bg(Color::Rgb(30, 45, 75))
            .add_modifier(Modifier::BOLD),
    )
    .highlight_symbol("▶ ");

    frame.render_stateful_widget(table, area, &mut state.table_state);
}

fn render_logs(frame: &mut Frame, area: Rect, state: &AppState) {
    let recent_logs: Vec<ListItem> = state
        .logs
        .iter()
        .rev()
        .take(10)
        .rev()
        .map(|msg| {
            let color = if msg.contains("ÉCHEC") || msg.contains("INDISPONIBLE") {
                Color::Red
            } else if msg.contains("alerte") || msg.contains("DÉGRADÉ") {
                Color::Yellow
            } else {
                Color::LightGreen
            };
            ListItem::new(Span::styled(msg, Style::default().fg(color)))
        })
        .collect();

    let logs_list = List::new(recent_logs).block(
        Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .title(" Journal des Événements et Anomalies "),
    );

    frame.render_widget(logs_list, area);
}

fn render_footer(frame: &mut Frame, area: Rect) {
