```rust
// src/main.rs
use crossterm::{
    cursor::{Hide, MoveTo, Show},
    event::{self, Event, KeyCode, KeyEvent, KeyEventKind, KeyModifiers},
    execute,
    style::{Color, Colors, ResetColor, SetColors},
    terminal::{
        disable_raw_mode, enable_raw_mode, size, EnterAlternateScreen, LeaveAlternateScreen,
    },
};
use std::cmp::{max, min};
use std::env;
use std::fs;
use std::io::{self, stdout, Stdout, Write};
use std::path::{Path, PathBuf};

/// Représente une position logique (ligne, colonne) dans le buffer de texte.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Position {
    pub row: usize,
    pub col: usize,
}

/// Garde RAII pour garantir la restauration de l'état du terminal.
struct TerminalCleanGuard;

impl Drop for TerminalCleanGuard {
    fn drop(&mut self) {
        let _ = disable_raw_mode();
        let mut out = stdout();
        let _ = execute!(out, Show, LeaveAlternateScreen);
    }
}

/// Éditeur de texte complet.
pub struct Editor {
    lines: Vec<String>,
    cursor: Position,
    selection_start: Option<Position>,
    row_offset: usize,
    col_offset: usize,
    screen_rows: usize,
    screen_cols: usize,
    file_path: Option<PathBuf>,
    is_modified: bool,
    status_message: String,
    should_quit: bool,
}

impl Editor {
    /// Initialise un nouvel éditeur, chargeant éventuellement un fichier.
    pub fn new(path: Option<PathBuf>) -> io::Result<Self> {
        let (cols, rows) = size()?;
        let (lines, status_message) = if let Some(ref p) = path {
            if p.exists() {
                let content = fs::read_to_string(p)?;
                let mut lines: Vec<String> = content.lines().map(|s| s.to_string()).collect();
                if lines.is_empty() {
                    lines.push(String::new());
                }
                (lines, format!("Fichier ouvert : {}", p.display()))
            } else {
                (
                    vec![String::new()],
                    format!("Nouveau fichier : {}", p.display()),
                )
            }
        } else {
            (
                vec![String::new()],
                "Nouveau document (Ctrl+Q: Quitter | Ctrl+S: Sauvegarder)".to_string(),
            )
        };

        // On réserve 2 lignes en bas : 1 barre de statut + 1 barre de message
        let text_rows = if rows > 2 { (rows - 2) as usize } else { 1 };

        Ok(Self {
            lines,
            cursor: Position { row: 0, col: 0 },
            selection_start: None,
            row_offset: 0,
            col_offset: 0,
            screen_rows: text_rows,
            screen_cols: cols as usize,
            file_path: path,
            is_modified: false,
            status_message,
            should_quit: false,
        })
    }

    /// Boucle principale de l'éditeur.
    pub fn run(&mut self) -> io::Result<()> {
        let _guard = TerminalCleanGuard;
        enable_raw_mode()?;
        let mut stdout_handle = stdout();
        execute!(stdout_handle, EnterAlternateScreen)?;

        while !self.should_quit {
            self.update_dimensions()?;
            self.scroll();
            self.render(&mut stdout_handle)?;
            self.handle_event()?;
        }

        Ok(())
    }

    /// Met à jour les dimensions de la fenêtre en cas de redimensionnement.
    fn update_dimensions(&mut self) -> io::Result<()> {
        let (cols, rows) = size()?;
        self.screen_cols = cols as usize;
        self.screen_rows = if rows > 2 { (rows - 2) as usize } else { 1 };
        Ok(())
    }

    /// Largeur réservée pour la marge des numéros de lignes (gutter).
    fn gutter_width(&self) -> usize {
        let max_line = max(1, self.lines.len());
        // Ex: ligne 100 -> 3 chiffres + 2 espaces de séparation
        format!("{}", max_line).len() + 2
    }

    /// Largeur effective disponible pour le contenu texte.
    fn text_viewport_cols(&self) -> usize {
        let gutter = self.gutter_width();
        if self.screen_cols > gutter {
            self.screen_cols - gutter
        } else {
            1
        }
    }

    /// Ajuste le défilement vertical et horizontal selon le curseur.
    fn scroll(&mut self) {
        // Défilement vertical
        if self.cursor.row < self.row_offset {
            self.row_offset = self.cursor.row;
        }
        if self.cursor.row >= self.row_offset + self.screen_rows {
            self.row_offset = self.cursor.row - self.screen_rows + 1;
        }

        // Défilement horizontal
        let viewport_cols = self.text_viewport_cols();
        if self.cursor.col < self.col_offset {
            self.col_offset = self.cursor.col;
        }
        if self.cursor.col >= self.col_offset + viewport_cols {
            self.col_offset = self.cursor.col - viewport_cols + 1;
        }
    }

    /// Évalue si une position donnée est dans l'intervalle de sélection active.
    fn is_selected(&self, pos: Position) -> bool {
        if let Some(start) = self.selection_start {
            let (from, to) = if start <= self.cursor {
                (start, self.cursor)
            } else {
                (self.cursor, start)
            };
            pos >= from && pos < to
        } else {
            false
        }
    }

    /// Affiche l'ensemble de l'écran.
    fn render(&self, out: &mut Stdout) -> io::Result<()> {
        execute!(out, Hide, MoveTo(0, 0))?;

        let gutter_w = self.gutter_width();
        let viewport_cols = self.text_viewport_cols();

        // 1. Zone de texte
        for screen_row in 0..self.screen_rows {
            let file_row = self.row_offset + screen_row;
            execute!(out, MoveTo(0, screen_row as u16))?;

            if file_row < self.lines.len() {
                // Numéro de ligne
                let line_num_str = format!("{:>width$} ", file_row + 1, width = gutter_w - 1);
                execute!(
                    out,
                    SetColors(Colors::new(Color::DarkGrey, Color::Reset)),
                    crossterm::style::Print(&line_num_str),
                    ResetColor
                )?;

                // Caractères de la ligne
                let line = &self.lines[file_row];
                let chars: Vec<char> = line.chars().collect();
                let line_len = chars.len();

                for screen_col in 0..viewport_cols {
                    let file_col = self.col_offset + screen_col;
                    let pos = Position {
                        row: file_row,
                        col: file_col,
                    };
                    let selected = self.is_selected(pos);

                    if selected {
                        execute!(
                            out,
                            SetColors(Colors::new(Color::Black, Color::White))
                        )?;
                    } else {
                        execute!(out, ResetColor)?;
                    }

                    if file_col < line_len {
                        let ch = chars[file_col];
                        let display_ch = if ch == '\t' { ' ' } else { ch };
                        write!(out, "{}", display_ch)?;
                    } else if selected && file_col == line_len {
                        // Affiche un espace sélectionné en bout de ligne pour visualiser le saut
                        write!(out, " ")?;
                    } else {
                        write!(out, " ")?;
                    }
                }
                execute!(out, ResetColor)?;
            } else {
                // Lignes au-delà du document
                execute!(
                    out,
                    SetColors(Colors::new(Color::DarkBlue, Color::Reset)),
                    crossterm::style::Print("~"),
                    ResetColor
                )?;
                let remaining = self.screen_cols.saturating_sub(1);
                write!(out, "{:width$}", "", width = remaining)?;
            }
        }

        // 2. Barre d'état
        self.render_status_bar(out)?;

        // 3. Barre de message
        self.render_message_bar(out)?;

        // Repositionne le curseur du terminal à l'endroit calculé
        let screen_cursor_row = (self.cursor.row - self.row_offset) as u16;
        let screen_cursor_col = (gutter_w + self.cursor.col - self.col_offset) as u16;
        execute!(out, MoveTo(screen_cursor_col, screen_cursor_row), Show)?;
        out.flush()?;
        Ok(())
    }

    /// Affiche la barre d'état.
    fn render_status_bar(&self, out: &mut Stdout) -> io::Result<()> {
        let status_row = self.screen_rows as u16;
        execute!(
            out,
            MoveTo(0, status_row),
            SetColors(Colors::new(Color::Black, Color::DarkCyan))
        )?;

        let filename = match &self.file_path {
            Some(p) => p.file_name().unwrap_or(p.as_os_str()).to_string_lossy().to_string(),
            None => "[Sans titre]".to_string(),
        };
        let modif_marker = if self.is_modified { " [+]" } else { "" };
        let sel_marker = if self.selection_start.is_some() {
            " [SEL]"
        } else {
            ""
        };
        let left_info = format!(" {} {}{}{}", filename, modif_marker, sel_marker, " ");
        let right_info = format!("Ln {}, Col {} ", self.cursor.row + 1, self.cursor.col + 1);

        let total_len = left_info.len() + right_info.len();
        let fill_space = if self.screen_cols > total_len {
            self.screen_cols - total_len
        } else {
            0
        };

        write!(out, "{}{:fill$}{}", left_info, "", right_info, fill = fill_space)?;
        execute!(out, ResetColor)?;
        Ok(())
    }

    /// Affiche la barre de notification/aide.
    fn render_message_bar(&self, out: &mut Stdout) -> io::Result<()> {
        let msg_row = (self.screen_rows + 1) as u16;
        execute!(
            out,
            MoveTo(0, msg_row),
            SetColors(Colors::new(Color::White, Color::DarkGrey))
        )?;

        let msg = if self.status_message.len() > self.screen_cols {
            &self.status_message[..self.screen_cols]
        } else {
            &self.status_message
        };
        let padding = self.screen_cols.saturating_sub(msg.len());
        write!(out, "{}{:fill$}", msg, "", fill = padding)?;
        execute!(out, ResetColor)?;
        Ok(())
    }

    /// Traitement d'un événement utilisateur.
    fn handle_event(&mut self) -> io::Result<()> {
        if let Event::Key(key_event) = event::read()? {
            if key_event.kind == KeyEventKind::Press {
                self.handle_key_event(key_event);
            }
        }
        Ok(())
    }

    /// Gestion des frappes clavier.
    fn handle_key_event(&mut self, key: KeyEvent) {
        let is_shift = key.modifiers.contains(KeyModifiers::SHIFT);
        let is_ctrl = key.modifiers.contains(KeyModifiers::CONTROL);

        // Raccourcis de contrôle
        if is_ctrl {
            match key.code {
                KeyCode::Char('q') | KeyCode::Char('Q') => {
                    self.should_quit = true;
                    return;
                }
                KeyCode::Char('s') | KeyCode::Char('S') => {
                    self.save();
                    return;
                }
                _ => {}
            }
        }

        // Navigation avec ou sans Shift (sélection)
        match key.code {
            KeyCode::Left | KeyCode::Right | KeyCode::Up | KeyCode::Down | KeyCode::Home | KeyCode::End | KeyCode::PageUp | KeyCode::PageDown => {
                if is_shift {
                    if self.selection_start.is_none() {
                        self.selection_start = Some(self.cursor);
                    }
                } else {
                    self.selection_start = None;
                }
                self.move_cursor(key.code);
                return;
            }
            _ => {}
        }

        // Modifications de texte
        match key.code {
            KeyCode::Char(c) => {
                if self.has_selection() {
                    self.delete_selection();
                }
                self.insert_char(c);
            }
            KeyCode::Tab => {
                if self.has_selection() {
                    self.delete_selection();
                }
                for _ in 0..4 {
                    self.insert_char(' ');
                }
            }
            KeyCode::Enter => {
                if self.has_selection() {
                    self.delete_selection();
                }
                self.insert_newline();
            }
            KeyCode::Backspace => {
                if self.has_selection() {
                    self.delete_selection();
                } else {
                    self.backspace();
                }
            }
            KeyCode::Delete => {
                if self.has_selection() {
                    self.delete_selection();
                } else {
                    self.delete();
                }
            }
            KeyCode::Esc => {
                self.selection_start = None;
                self.status_message = "Sélection annulée.".to_string();
            }
            _ => {}
        }
    }

    /// Indique si une sélection est actuellement non vide.
    fn has_selection(&self) -> bool {
        self.selection_start.is_some() && self.selection_start != Some(self.cursor)
    }

    /// Déplace le curseur dans le texte en respectant les limites de lignes.
    fn move_cursor(&mut self, key: KeyCode) {
        match key {
            KeyCode::Left => {
                if self.cursor.col > 0 {
                    self.cursor.col -= 1;
                } else if self.cursor.row > 0 {
                    self.cursor.row -= 1;
                    self.cursor.col = self.lines[self.cursor.row].chars().count();
                }
            }
            KeyCode::Right => {
                let current_len = self.lines[self.cursor.row].chars().count();
                if self.cursor.col < current_len {
                    self.cursor.col += 1;
                } else if self.cursor.row + 1 < self.lines.len() {
                    self.cursor.row += 1;
                    self.cursor.col = 0;
                }
            }
            KeyCode::Up => {
                if self.cursor.row > 0 {
                    self.cursor.row -= 1;
                    self.clamp_cursor_col();
                }
            }
            KeyCode::Down => {
                if self.cursor.row + 1 < self.lines.len() {
                    self.cursor.row += 1;
                    self.clamp_cursor_col();
                }
            }
            KeyCode::Home => {
                self.cursor.col = 0;
            }
            KeyCode::End => {
                self.cursor.col = self.lines[self.cursor.row].chars().count();
            }
            KeyCode::PageUp => {
                self.cursor.row = self.cursor.row.saturating_sub(self.screen_rows);
                self.clamp_cursor_col();
            }
            KeyCode::PageDown => {
                self.cursor.row = min(
                    self.lines.len().saturating_sub(1),
                    self.cursor.row + self.screen_rows,
                );
                self.clamp_cursor_col();
            }
            _ => {}
        }
    }

    /// Réajuste la colonne du curseur à la fin de ligne si nécessaire.
    fn clamp_cursor_col(&mut self) {
        let max_col = self.lines[self.cursor.row].chars().count();
        if self.cursor.col > max_col {
            self.cursor.col = max_col;
        }
    }

    /// Insère un caractère à la position du curseur.
    fn insert_char(&mut self, c: char) {
        let line = &mut self.lines[self.cursor.row];
        let byte_idx = line
            .char_indices()
            .map(|(idx, _)| idx)
            .nth(self.cursor.col)
            .unwrap_or(line.len());
        line.insert(byte_idx, c);
        self.cursor.col += 1;
        self.is_modified = true;
    }

    /// Insère un retour à la ligne à la position du curseur.
    fn insert_newline(&mut self) {
        let line = &mut self.lines[self.cursor.row];
        let byte_idx = line
            .char_indices()
            .map(|(idx, _)| idx)
            .nth(self.cursor.col)
            .unwrap_or(line.len());
        let remainder = line.split_off(byte_idx);

        self.cursor.row += 1;
        self.cursor.col = 0;
        self.lines.insert(self.cursor.row, remainder);
        self.is_modified = true;
    }

    /// Efface le caractère précédant le curseur (Backspace).
    fn backspace(&mut self) {
        if self.cursor.col > 0 {
            let line = &mut self.lines[self.cursor.row];
            let prev_col = self.cursor.col - 1;
            let byte_idx = line
                .char_indices()
                .map(|(idx, _)| idx)
                .nth(prev_col)
                .unwrap_or(0);
            line.remove(byte_idx);
            self.cursor.col -= 1;
            self.is_modified = true;
        } else if self.cursor.row > 0 {
            let current_line = self.lines.remove(self.cursor.row);
            self.cursor.row -= 1;
            let prev_line = &mut self.lines[self.cursor.row];
            self.cursor.col = prev_line.chars().count();
            prev_line.push_str(&current_line);
            self.is_modified = true;
        }
    }

    /// Efface le caractère suivant le curseur (Delete).
    fn delete(&mut self) {
        let line_len = self.lines[self.cursor.row].chars().count();
        if self.cursor.col < line_len {
            let line = &mut self.lines[self.cursor.row];
            let byte_idx = line
                .char_indices()
                .map(|(idx, _)| idx)
                .nth(self.cursor.col)
                .unwrap_or(line.len());
            line.remove(byte_idx);
            self.is_modified = true;
        } else if self.cursor.row + 1 < self.lines.len() {
            let next_line = self.lines.remove(self.cursor.row + 1);
            self.lines[self.cursor.row].push_str(&next_line);
            self.is_modified = true;
        }
    }

    /// Supprime la plage de texte sélectionnée.
    fn delete_selection(&mut self) {
        let start = match self.selection_start {
            Some(pos) => pos,
            None => return,
        };

        let (from, to) = if start <= self.cursor {
            (start, self.cursor)
        } else {
            (self.cursor, start)
        };

        if from == to {
            self.selection_start = None;
            return;
        }

        if from.row == to.row {
            let line = &mut self.lines[from.row];
            let start_byte = line
                .char_indices()
                .map(|(idx, _)| idx)
                .nth(from.col)
                .unwrap_or(line.len());
            let end_byte = line
                .char_indices()
                .map(|(idx, _)| idx)
                .nth(to.col)
                .unwrap_or(line.len());
            line.drain(start_byte..end_byte);
        } else {
            // Première ligne : conserve avant from.col
            let start_byte = {
                let first = &self.lines[from.row];
                first
                    .char_indices()
                    .map(|(idx, _)| idx)
                    .nth(from.col)
                    .unwrap_or(first.len())
            };
            // Dernière ligne : conserve après to.col
            let end_remainder = {
                let last = &self.lines[to.row];
                let end_byte = last
                    .char_indices()
                    .map(|(idx, _)| idx)
                    .nth(to.col)
                    .unwrap_or(last.len());
                last[end_byte..].to_string()
            };

            // Troncature première ligne et concaténation avec reste de la dernière ligne
            self.lines[from.row].truncate(start_byte);
            self.lines[from.row].push_str(&end_remainder);

            // Suppression des lignes intermédiaires et de la dernière
            self.lines.drain((from.row + 1)..=to.row);
        }

        self.cursor = from;
        self.selection_start = None;
        self.is_modified = true;
        self.clamp_cursor_col();
    }

    /// Sauvegarde le contenu sur le disque.
    fn save(&mut self) {
        let path = match &self.file_path {
            Some(p) => p.clone(),
            None => {
                let default_path = PathBuf::from("document.txt");
                self.file_path = Some(default_path.clone());
                default_path
            }
        };

        let content = self.lines.join("\n");
        match fs::write(&path, content) {
            Ok(_) => {
                self.is_modified = false;
                self.status_message = format!("Sauvegardé dans {}", path.display());
            }
            Err(e) => {
                self.status_message = format!("Erreur lors de la sauvegarde : {}", e);
            }
        }
    }
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();
    let file_path = if args.len() > 1 {
        Some(Path::new(&args[1]).to_path_buf())
    } else {
        None
    };

    let mut editor = Editor::new(file_path)?;
    editor.run()
}

