// src/main.rs
use anyhow::{Context, Result};
use crossterm::{
    event::{self, Event, KeyCode, KeyEventKind, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::CrosstermBackend,
    layout::{Constraint, Direction, Layout},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, Paragraph, Wrap},
    Frame, Terminal,
};
use serde_json::Value;
use std::{
    env,
    fs::File,
    io::{self, Stdout},
};

/// Représente un nœud dans l'arborescence JSON.
#[derive(Debug, Clone)]
pub struct JsonTreeNode {
    pub id: usize,
    pub key: Option<String>,
    pub value: Value,
    pub is_expanded: bool,
    pub children: Vec<JsonTreeNode>,
}

impl JsonTreeNode {
    /// Construit récursivement l'arbre à partir d'une `serde_json::Value`.
    pub fn build(value: Value, key: Option<String>, id_gen: &mut usize) -> Self {
        let current_id = *id_gen;
        *id_gen += 1;

        let mut children = Vec::new();
        match &value {
            Value::Object(map) => {
                for (k, v) in map {
                    children.push(Self::build(v.clone(), Some(k.clone()), id_gen));
                }
            }
            Value::Array(arr) => {
                for (index, v) in arr.iter().enumerate() {
                    children.push(Self::build(v.clone(), Some(format!("[{index}]")), id_gen));
                }
            }
            _ => {}
        }

        Self {
            id: current_id,
            key,
            value,
            // Les nœuds racines et de premier niveau peuvent commencer dépliés
            is_expanded: true,
            children,
        }
    }

    pub fn is_container(&self) -> bool {
        matches!(self.value, Value::Object(_) | Value::Array(_))
    }

    pub fn set_all_expanded(&mut self, expanded: bool) {
        if self.is_container() {
            self.is_expanded = expanded;
            for child in &mut self.children {
                child.set_all_expanded(expanded);
            }
        }
    }

    pub fn toggle_by_id(&mut self, target_id: usize) -> bool {
        if self.id == target_id {
            if self.is_container() {
                self.is_expanded = !self.is_expanded;
            }
            return true;
        }
        for child in &mut self.children {
            if child.toggle_by_id(target_id) {
                return true;
            }
        }
        false
    }

    pub fn set_expanded_by_id(&mut self, target_id: usize, expanded: bool) -> bool {
        if self.id == target_id {
            if self.is_container() {
                self.is_expanded = expanded;
            }
            return true;
        }
        for child in &mut self.children {
            if child.set_expanded_by_id(target_id, expanded) {
                return true;
            }
        }
        false
    }
}

/// Éléments aplatis pour l'affichage et la navigation.
#[derive(Debug, Clone)]
pub struct VisibleItem {
    pub node_id: usize,
    pub depth: usize,
    pub is_container: bool,
    pub is_expanded: bool,
    pub key: Option<String>,
    pub value_repr: ValuePreview,
}

#[derive(Debug, Clone)]
pub enum ValuePreview {
    Object { count: usize },
    Array { count: usize },
    String(String),
    Number(String),
    Bool(bool),
    Null,
}

impl VisibleItem {
    fn from_node(node: &JsonTreeNode, depth: usize) -> Self {
        let value_repr = match &node.value {
            Value::Object(map) => ValuePreview::Object { count: map.len() },
            Value::Array(arr) => ValuePreview::Array { count: arr.len() },
            Value::String(s) => ValuePreview::String(s.clone()),
            Value::Number(n) => ValuePreview::Number(n.to_string()),
            Value::Bool(b) => ValuePreview::Bool(*b),
            Value::Null => ValuePreview::Null,
        };

        Self {
            node_id: node.id,
            depth,
            is_container: node.is_container(),
            is_expanded: node.is_expanded,
            key: node.key.clone(),
            value_repr,
        }
    }
}

/// État de l'application TUI.
pub struct App {
    pub root: JsonTreeNode,
    pub selected_index: usize,
    pub scroll_offset: usize,
    pub visible_items: Vec<VisibleItem>,
    pub should_quit: bool,
}

impl App {
    pub fn new(root_value: Value) -> Self {
        let mut id_gen = 0;
        let root = JsonTreeNode::build(root_value, Some("root".to_string()), &mut id_gen);
        let mut app = Self {
            root,
            selected_index: 0,
            scroll_offset: 0,
            visible_items: Vec::new(),
            should_quit: false,
        };
        app.rebuild_visible();
        app
    }

    pub fn rebuild_visible(&mut self) {
        let mut items = Vec::new();
        Self::collect_visible(&self.root, 0, &mut items);
        self.visible_items = items;

        if self.visible_items.is_empty() {
            self.selected_index = 0;
        } else if self.selected_index >= self.visible_items.len() {
            self.selected_index = self.visible_items.len().saturating_sub(1);
        }
    }

    fn collect_visible(node: &JsonTreeNode, depth: usize, out: &mut Vec<VisibleItem>) {
        out.push(VisibleItem::from_node(node, depth));
        if node.is_container() && node.is_expanded {
            for child in &node.children {
                Self::collect_visible(child, depth + 1, out);
            }
        }
    }

    pub fn move_up(&mut self) {
        if self.selected_index > 0 {
            self.selected_index -= 1;
        }
    }

    pub fn move_down(&mut self) {
        if !self.visible_items.is_empty() && self.selected_index + 1 < self.visible_items.len() {
            self.selected_index += 1;
        }
    }

    pub fn toggle_selected(&mut self) {
        if let Some(item) = self.visible_items.get(self.selected_index) {
            let id = item.node_id;
            self.root.toggle_by_id(id);
            self.rebuild_visible();
        }
    }

    pub fn expand_selected(&mut self) {
        if let Some(item) = self.visible_items.get(self.selected_index) {
            if item.is_container {
                if !item.is_expanded {
                    self.root.set_expanded_by_id(item.node_id, true);
                    self.rebuild_visible();
                } else if self.selected_index + 1 < self.visible_items.len() {
                    self.selected_index += 1;
                }
            }
        }
    }

    pub fn collapse_selected(&mut self) {
        if let Some(item) = self.visible_items.get(self.selected_index) {
