fn ui(f: &mut Frame, app: &mut App) {
    let size = f.area();

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // En-tête / Titre
            Constraint::Min(5),    // Arbre
            Constraint::Length(3), // Barre d'aide / Statut
        ])
        .split(size);

    // Titre
    let title_block = Block::default()
        .borders(Borders::ALL)
        .style(Style::default().fg(Color::Cyan));
    let title = Paragraph::new(Line::from(vec![
        Span::styled(
            " 🌲 Visualiseur de structures JSON arborescentes ",
            Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD),
        ),
        Span::styled(
            "(Ratatui + Crossterm)",
            Style::default().fg(Color::DarkGray),
        ),
    ]))
    .block(title_block);
    f.render_widget(title, chunks[0]);

    // Arbre principal
    let tree_area = chunks[1];
    let content_height = tree_area.height.saturating_sub(2) as usize;
    app.adjust_scroll(content_height);

    let start = app.scroll_offset;
    let end = (start + content_height).min(app.visible_items.len());

    let mut lines = Vec::new();
    for (index, item) in app.visible_items.iter().enumerate().skip(start).take(end - start) {
        let is_selected = index == app.selected_index;
        let indent = "  ".repeat(item.depth);

        let icon = if item.is_container {
            if item.is_expanded {
                "▼ "
            } else {
                "▶ "
            }
        } else {
            "• "
        };

        let mut spans = Vec::new();

        // Indicateur de sélection
        if is_selected {
            spans.push(Span::styled("❯ ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
        } else {
            spans.push(Span::raw("  "));
        }

        // Indentation + Icône
        spans.push(Span::raw(indent));
        let icon_style = if item.is_container {
            Style::default().fg(Color::Magenta).add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(Color::DarkGray)
        };
        spans.push(Span::styled(icon, icon_style));

        // Clé du nœud si présente
        if let Some(ref k) = item.key {
            spans.push(Span::styled(
                format!("\"{k}\""),
                Style::default().fg(Color::LightCyan).add_modifier(Modifier::BOLD),
            ));
            spans.push(Span::raw(": "));
        }

        // Valeur selon le type
        match &item.value_repr {
            ValuePreview::Object { count } => {
                if item.is_expanded {
                    spans.push(Span::styled("{", Style::default().fg(Color::White)));
                } else {
                    spans.push(Span::styled(
                        format!("{{ {count} entrées }} ..."),
                        Style::default().fg(Color::DarkGray).add_modifier(Modifier::ITALIC),
                    ));
                }
            }
            ValuePreview::Array { count } => {
                if item.is_expanded {
                    spans.push(Span::styled("[", Style::default().fg(Color::White)));
                } else {
                    spans.push(Span::styled(
                        format!("[ {count} éléments ] ..."),
                        Style::default().fg(Color::DarkGray).add_modifier(Modifier::ITALIC),
                    ));
                }
            }
            ValuePreview::String(s) => {
                spans.push(Span::styled(
                    format!("\"{s}\""),
                    Style::default().fg(Color::LightGreen),
                ));
            }
            ValuePreview::Number(n) => {
                spans.push(Span::styled(
                    n.clone(),
                    Style::default().fg(Color::LightYellow),
                ));
            }
            ValuePreview::Bool(b) => {
                spans.push(Span::styled(
                    b.to_string(),
                    Style::default().fg(Color::LightMagenta).add_modifier(Modifier::BOLD),
                ));
            }
            ValuePreview::Null => {
                spans.push(Span::styled(
                    "null",
                    Style::default().fg(Color::Red).add_modifier(Modifier::DIM),
                ));
            }
        }

        let line_style = if is_selected {
            Style::default().bg(Color::Rgb(35, 45, 60))
        } else {
            Style::default()
        };

        lines.push(Line::from(spans).style(line_style));
    }

    let tree_block = Block::default()
        .borders(Borders::ALL)
        .title(format!(
            " Arbre JSON [Nœud {}/{}] ",
            if app.visible_items.is_empty() { 0 } else { app.selected_index + 1 },
            app.visible_items.len()
        ))
        .style(Style::default().fg(Color::White));

