            ValuePreview::Object { count } => {
                if item.is_expanded {
                    spans.push(Span::styled("{", Style::default().fg(Color::White)));
                } else {
                    spans.push(Span::styled(
                        format!("{{ {count} entrées }} ..."),
                        Style::default().fg(Color::DarkGray).add_modifier(Modifier::ITALIC),
                    ));
                }
            }
            ValuePreview::Array { count } => {
                if item.is_expanded {
                    spans.push(Span::styled("[", Style::default().fg(Color::White)));
                } else {
                    spans.push(Span::styled(
                        format!("[ {count} éléments ] ..."),
                        Style::default().fg(Color::DarkGray).add_modifier(Modifier::ITALIC),
                    ));
                }
            }
            ValuePreview::String(s) => {
                spans.push(Span::styled(
                    format!("\"{s}\""),
                    Style::default().fg(Color::LightGreen),
                ));
            }
            ValuePreview::Number(n) => {
                spans.push(Span::styled(
                    n.clone(),
                    Style::default().fg(Color::LightYellow),
                ));
            }
            ValuePreview::Bool(b) => {
                spans.push(Span::styled(
                    b.to_string(),
                    Style::default().fg(Color::LightMagenta).add_modifier(Modifier::BOLD),
                ));
            }
            ValuePreview::Null => {
                spans.push(Span::styled(
                    "null",
                    Style::default().fg(Color::Red).add_modifier(Modifier::DIM),
                ));
            }
        }

        let line_style = if is_selected {
            Style::default().bg(Color::Rgb(35, 45, 60))
        } else {
            Style::default()
        };

        lines.push(Line::from(spans).style(line_style));
    }

    let tree_block = Block::default()
        .borders(Borders::ALL)
        .title(format!(
            " Arbre JSON [Nœud {}/{}] ",
            if app.visible_items.is_empty() { 0 } else { app.selected_index + 1 },
            app.visible_items.len()
        ))
        .style(Style::default().fg(Color::White));

    let tree_paragraph = Paragraph::new(lines).block(tree_block);
    f.render_widget(tree_paragraph, tree_area);

    // Barre d'aide
    let help_block = Block::default()
        .borders(Borders::ALL)
        .style(Style::default().fg(Color::DarkGray));

    let help_line = Line::from(vec![
        Span::styled(" [↑/↓/j/k]", Style::default().fg(Color::Yellow)),
        Span::raw(" Naviguer | "),
        Span::styled("[Entrée/Espace]", Style::default().fg(Color::Yellow)),
        Span::raw(" Plier/Déplier | "),
        Span::styled("[←/→/h/l]", Style::default().fg(Color::Yellow)),
        Span::raw(" Fermer/Ouvrir | "),
        Span::styled("[E]", Style::default().fg(Color::Yellow)),
        Span::raw(" Tout déplier | "),
        Span::styled("[C]", Style::default().fg(Color::Yellow)),
        Span::raw(" Tout replier | "),
        Span::styled("[q/Esc]", Style::default().fg(Color::Red)),
        Span::raw(" Quitter"),
    ]);

    let help_paragraph = Paragraph::new(help_line)
        .block(help_block)
        .wrap(Wrap { trim: true });
    f.render_widget(help_paragraph, chunks[2]);
}

fn main() -> Result<()> {
    // Chargement du JSON à partir des arguments ou exemple intégré
    let json_data = load_input_json()?;

    // Initialisation du terminal
    enable_raw_mode().context("Impossible d'activer le mode Raw")?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen).context("Impossible de passer en AlternateScreen")?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend).context("Impossible de créer le terminal Ratatui")?;

    // Instanciation de l'état
    let app = App::new(json_data);

    // Boucle d'exécution principale avec garantie de nettoyage
    let app_result = run_app(&mut terminal, app);

    // Restauration du terminal
    disable_raw_mode().context("Impossible de désactiver le mode Raw")?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)
        .context("Impossible de quitter AlternateScreen")?;
    terminal.show_cursor().context("Impossible de réafficher le curseur")?;

    app_result
}

