```rust
// src/main.rs
use std::{
    error::Error,
    io::{self, stdout, Stdout},
    time::{Duration, Instant},
};

use crossterm::{
    event::{self, Event, KeyCode, KeyEventKind},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::CrosstermBackend,
    layout::{Alignment, Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{
        Bar, BarChart, BarGroup, Block, BorderType, Borders, Paragraph, Tabs,
    },
    Frame, Terminal,
};
use sysinfo::System;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ViewMode {
    System,
    Financial,
    Combined,
}

impl ViewMode {
    fn next(self) -> Self {
        match self {
            Self::System => Self::Financial,
            Self::Financial => Self::Combined,
            Self::Combined => Self::System,
        }
    }

    fn prev(self) -> Self {
        match self {
            Self::System => Self::Combined,
            Self::Financial => Self::System,
            Self::Combined => Self::Financial,
        }
    }

    fn as_index(self) -> usize {
        match self {
            Self::System => 0,
            Self::Financial => 1,
            Self::Combined => 2,
        }
    }
}

struct App {
    system: System,
    view_mode: ViewMode,
    running: bool,
    // Métriques système (%)
    cpu_usage: u64,
    memory_usage: u64,
    swap_usage: u64,
    // Métriques financières (€k ou index normalisé)
    fin_revenue: u64,
    fin_expenses: u64,
    fin_ebitda: u64,
    fin_net_income: u64,
    // Simuler l'évolution financière au fil du temps
    tick_count: u64,
}

impl App {
    fn new() -> Self {
        let mut sys = System::new_all();
        sys.refresh_all();

        Self {
            system: sys,
            view_mode: ViewMode::System,
            running: true,
            cpu_usage: 0,
            memory_usage: 0,
            swap_usage: 0,
            fin_revenue: 120,
            fin_expenses: 75,
            fin_ebitda: 45,
            fin_net_income: 32,
            tick_count: 0,
        }
    }

    fn update_metrics(&mut self) {
        self.system.refresh_cpu_usage();
        self.system.refresh_memory();

        let global_cpu = self.system.global_cpu_usage() as u64;
        self.cpu_usage = global_cpu.min(100);

        let total_mem = self.system.total_memory();
        let used_mem = self.system.used_memory();
        self.memory_usage = if total_mem > 0 {
            (used_mem * 100 / total_mem).min(100)
        } else {
            0
        };

        let total_swap = self.system.total_swap();
        let used_swap = self.system.used_swap();
        self.swap_usage = if total_swap > 0 {
            (used_swap * 100 / total_swap).min(100)
        } else {
            0
        };

        // Variation dynamique légère des indicateurs financiers pour la démo interactive
        self.tick_count = self.tick_count.wrapping_add(1);
        let cycle = (self.tick_count % 10) as i64 - 5;
        self.fin_revenue = ((125 + cycle) as u64).max(50);
        self.fin_expenses = ((78 + cycle / 2) as u64).max(30);
        self.fin_ebitda = self.fin_revenue.saturating_sub(self.fin_expenses);
        self.fin_net_income = (self.fin_ebitda * 7) / 10;
    }

    fn on_key(&mut self, key: KeyCode) {
        match key {
            KeyCode::Char('q') | KeyCode::Esc => self.running = false,
            KeyCode::Tab | KeyCode::Right | KeyCode::Char('l') => self.view_mode = self.view_mode.next(),
            KeyCode::BackTab | KeyCode::Left | KeyCode::Char('h') => self.view_mode = self.view_mode.prev(),
            KeyCode::Char('1') => self.view_mode = ViewMode::System,
            KeyCode::Char('2') => self.view_mode = ViewMode::Financial,
            KeyCode::Char('3') => self.view_mode = ViewMode::Combined,
            _ => {}
        }
    }
}

fn main() -> Result<(), Box<dyn Error>> {
    enable_raw_mode()?;
    let mut out = stdout();
    execute!(out, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(out);
    let mut terminal = Terminal::new(backend)?;

    let app = App::new();
    let res = run_app(&mut terminal, app);

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    if let Err(err) = res {
        eprintln!("Erreur lors de l'exécution de l'application: {err:?}");
    }

    Ok(())
}

fn run_app(
    terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    mut app: App,
) -> io::Result<()> {
    let tick_rate = Duration::from_millis(1000);
    let mut last_tick = Instant::now();

    app.update_metrics();

    while app.running {
        terminal.draw(|f| ui(f, &app))?;

        let timeout = tick_rate.saturating_sub(last_tick.elapsed());
        if event::poll(timeout)? {
            if let Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press {
                    app.on_key(key.code);
                }
            }
        }

        if last_tick.elapsed() >= tick_rate {
            app.update_metrics();
            last_tick = Instant::now();
        }
    }

    Ok(())
}

fn ui(f: &mut Frame, app: &App) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3),
            Constraint::Min(10),
            Constraint::Length(3),
        ])
        .split(f.area());

    render_header(f, app, chunks[0]);
    render_charts(f, app, chunks[1]);
    render_footer(f, chunks[2]);
}

fn render_header(f: &mut Frame, app: &App, area: Rect) {
    let titles = vec![
        Line::from(" [1] Métriques Système "),
        Line::from(" [2] Métriques Financières "),
        Line::from(" [3] Comparaison Combinée "),
    ];

    let tabs = Tabs::new(titles)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .title(" Tableau de bord analytique - SysFin Monitor ")
                .title_alignment(Alignment::Center),
        )
        .select(app.view_mode.as_index())
        .style(Style::default().fg(Color::DarkGray))
        .highlight_style(
            Style::default()
                .fg(Color::Cyan)
                .add_modifier(Modifier::BOLD),
        );

    f.render_widget(tabs, area);
}

fn render_charts(f: &mut Frame, app: &App, area: Rect) {
    match app.view_mode {
        ViewMode::System => render_system_barchart(f, app, area),
        ViewMode::Financial => render_financial_barchart(f, app, area),
        ViewMode::Combined => render_combined_barchart(f, app, area),
    }
}

fn render_system_barchart(f: &mut Frame, app: &App, area: Rect) {
    let cpu_color = if app.cpu_usage > 85 {
        Color::Red
    } else if app.cpu_usage > 60 {
        Color::Yellow
    } else {
        Color::Green
    };

    let mem_color = if app.memory_usage > 85 {
        Color::Red
    } else if app.memory_usage > 70 {
        Color::Yellow
    } else {
        Color::Blue
    };

    let swap_color = if app.swap_usage > 50 {
        Color::Magenta
    } else {
        Color::Cyan
    };

    let bars = vec![
        Bar::default()
            .label(Line::from("CPU"))
            .value(app.cpu_usage)
            .text_value(format!("{}%", app.cpu_usage))
            .style(Style::default().fg(cpu_color)),
        Bar::default()
            .label(Line::from("RAM"))
            .value(app.memory_usage)
            .text_value(format!("{}%", app.memory_usage))
            .style(Style::default().fg(mem_color)),
        Bar::default()
            .label(Line::from("SWAP"))
            .value(app.swap_usage)
            .text_value(format!("{}%", app.swap_usage))
            .style(Style::default().fg(swap_color)),
    ];

    let group = BarGroup::default().bars(&bars);

    let barchart = BarChart::default()
        .block(
            Block::default()
                .title(" Utilisation Système (%) ")
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .border_style(Style::default().fg(Color::Cyan)),
        )
        .data(group)
        .bar_width(9)
        .bar_gap(4)
        .max(100);

    f.render_widget(barchart, area);
}

fn render_financial_barchart(f: &mut Frame, app: &App, area: Rect) {
    let bars = vec![
        Bar::default()
            .label(Line::from("Revenus"))
            .value(app.fin_revenue)
            .text_value(format!("{} k€", app.fin_revenue))
            .style(Style::default().fg(Color::Green)),
        Bar::default()
            .label(Line::from("Dépenses"))
            .value(app.fin_expenses)
            .text_value(format!("{} k€", app.fin_expenses))
            .style(Style::default().fg(Color::Red)),
        Bar::default()
            .label(Line::from("EBITDA"))
            .value(app.fin_ebitda)
            .text_value(format!("{} k€", app.fin_ebitda))
            .style(Style::default().fg(Color::Yellow)),
        Bar::default()
            .label(Line::from("Résultat Net"))
            .value(app.fin_net_income)
            .text_value(format!("{} k€", app.fin_net_income))
            .style(Style::default().fg(Color::Cyan)),
    ];

    let group = BarGroup::default().bars(&bars);

    let barchart = BarChart::default()
        .block(
            Block::default()
                .title(" Indicateurs Financiers (Trimestre en cours - k€) ")
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .border_style(Style::default().fg(Color::Yellow)),
        )
        .data(group)
        .bar_width(12)
        .bar_gap(3)
        .max(160);

    f.render_widget(barchart, area);
}

fn render_combined_barchart(f: &mut Frame, app: &App, area: Rect) {
    let chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
        .split(area);

    render_system_barchart(f, app, chunks[0]);
    render_financial_barchart(f, app, chunks[1]);
}

fn render_footer(f: &mut Frame, area: Rect) {
    let instructions = Line::from(vec![
        Span::styled(" [Tab / ← →] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw("Changer d'onglet  | "),
        Span::styled(" [1/2/3] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw("Accès direct  | "),
        Span::styled(" [q / Échap] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw("Quitter"),
    ]);

    let footer = Paragraph::new(instructions)
        .alignment(Alignment::Center)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded),
        );

    f.render_widget(footer, area);
}

