```rust
// src/main.rs
use std::io::{stdout, Stdout};
use std::time::Duration;

use chrono::Local;
use crossterm::{
    event::{Event, EventStream, KeyCode, KeyEvent, KeyEventKind, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use futures_util::StreamExt;
use ratatui::{
    backend::CrosstermBackend,
    layout::{Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, List, ListItem, Paragraph, Wrap},
    Frame, Terminal,
};
use tokio::sync::mpsc;

#[derive(Clone, Debug)]
struct ChatMessage {
    timestamp: String,
    sender: String,
    content: String,
    is_self: bool,
    color: Color,
}

#[derive(Clone, Debug)]
struct User {
    name: String,
    status: UserStatus,
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum UserStatus {
    Online,
    Idle,
}

enum AppEvent {
    Input(KeyEvent),
    MessageReceived(ChatMessage),
    UserJoined(String),
}

struct App {
    messages: Vec<ChatMessage>,
    users: Vec<User>,
    input: String,
    cursor_position: usize,
    scroll_offset: u16,
    auto_scroll: bool,
    current_username: String,
}

impl App {
    fn new(username: String) -> Self {
        Self {
            messages: vec![ChatMessage {
                timestamp: Local::now().format("%H:%M:%S").to_string(),
                sender: "Système".to_string(),
                content: "Bienvenue dans le salon de discussion !".to_string(),
                is_self: false,
                color: Color::Yellow,
            }],
            users: vec![
                User {
                    name: username.clone(),
                    status: UserStatus::Online,
                },
                User {
                    name: "Alice".to_string(),
                    status: UserStatus::Online,
                },
                User {
                    name: "Bob".to_string(),
                    status: UserStatus::Idle,
                },
                User {
                    name: "Charlie".to_string(),
                    status: UserStatus::Online,
                },
            ],
            input: String::new(),
            cursor_position: 0,
            scroll_offset: 0,
            auto_scroll: true,
            current_username: username,
        }
    }

    fn send_current_message(&mut self) -> Option<ChatMessage> {
        let trimmed = self.input.trim();
        if trimmed.is_empty() {
            return None;
        }

        let new_msg = ChatMessage {
            timestamp: Local::now().format("%H:%M:%S").to_string(),
            sender: self.current_username.clone(),
            content: trimmed.to_string(),
            is_self: true,
            color: Color::Cyan,
        };

        self.messages.push(new_msg.clone());
        self.input.clear();
        self.cursor_position = 0;
        if self.auto_scroll {
            self.scroll_offset = 0;
        }
        Some(new_msg)
    }

    fn insert_char(&mut self, ch: char) {
        self.input.insert(self.cursor_position, ch);
        self.cursor_position += 1;
    }

    fn delete_char(&mut self) {
        if self.cursor_position > 0 && !self.input.is_empty() {
            let prev_index = self.cursor_position - 1;
            self.input.remove(prev_index);
            self.cursor_position = prev_index;
        }
    }

    fn move_cursor_left(&mut self) {
        if self.cursor_position > 0 {
            self.cursor_position -= 1;
        }
    }

    fn move_cursor_right(&mut self) {
        if self.cursor_position < self.input.len() {
            self.cursor_position += 1;
        }
    }

    fn scroll_up(&mut self) {
        self.auto_scroll = false;
        self.scroll_offset = self.scroll_offset.saturating_add(1);
    }

    fn scroll_down(&mut self) {
        if self.scroll_offset > 0 {
            self.scroll_offset -= 1;
            if self.scroll_offset == 0 {
                self.auto_scroll = true;
            }
        }
    }

    fn reset_scroll(&mut self) {
        self.scroll_offset = 0;
        self.auto_scroll = true;
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialisation du terminal
    enable_raw_mode()?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let app = App::new("Moi".to_string());

    let (tx, mut rx) = mpsc::channel::<AppEvent>(100);

    // Tâche d'arrière-plan simulant l'arrivée de messages et d'utilisateurs
    let sim_tx = tx.clone();
    tokio::spawn(async move {
        let simulated_events = vec![
            (
                Duration::from_secs(3),
                AppEvent::MessageReceived(ChatMessage {
                    timestamp: Local::now().format("%H:%M:%S").to_string(),
                    sender: "Alice".to_string(),
                    content: "Salut tout le monde ! Comment ça va ?".to_string(),
                    is_self: false,
                    color: Color::Magenta,
                }),
            ),
            (
                Duration::from_secs(7),
                AppEvent::UserJoined("David".to_string()),
            ),
            (
                Duration::from_secs(9),
                AppEvent::MessageReceived(ChatMessage {
                    timestamp: Local::now().format("%H:%M:%S").to_string(),
                    sender: "David".to_string(),
                    content: "Hello ! Ravi de rejoindre ce salon de discussion.".to_string(),
                    is_self: false,
                    color: Color::Green,
                }),
            ),
            (
                Duration::from_secs(15),
                AppEvent::MessageReceived(ChatMessage {
                    timestamp: Local::now().format("%H:%M:%S").to_string(),
                    sender: "Bob".to_string(),
                    content: "Des nouvelles de la prochaine release ?".to_string(),
                    is_self: false,
                    color: Color::Blue,
                }),
            ),
        ];

        for (delay, evt) in simulated_events {
            tokio::time::sleep(delay).await;
            if sim_tx.send(evt).await.is_err() {
                break;
            }
        }
    });

    let result = run_app(&mut terminal, app, tx, &mut rx).await;

    // Nettoyage et restauration du terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    result
}

async fn run_app(
    terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    mut app: App,
    tx: mpsc::Sender<AppEvent>,
    rx: &mut mpsc::Receiver<AppEvent>,
) -> Result<(), Box<dyn std::error::Error>> {
    let mut reader = EventStream::new();

    loop {
        terminal.draw(|f| ui(f, &mut app))?;

        tokio::select! {
            maybe_event = reader.next() => {
                match maybe_event {
                    Some(Ok(Event::Key(key))) => {
                        // Traiter uniquement les événements de type Press
                        if key.kind == KeyEventKind::Press {
                            if tx.send(AppEvent::Input(key)).await.is_err() {
                                break;
                            }
                        }
                    }
                    Some(Err(_)) => break,
                    None => break,
                    _ => {}
                }
            }
            Some(app_event) = rx.recv() => {
                match app_event {
                    AppEvent::Input(key) => {
                        match key.code {
                            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                return Ok(());
                            }
                            KeyCode::Esc => {
                                return Ok(());
                            }
                            KeyCode::Enter => {
                                app.send_current_message();
                            }
                            KeyCode::Char(c) => {
                                app.insert_char(c);
                            }
                            KeyCode::Backspace => {
                                app.delete_char();
                            }
                            KeyCode::Left => {
                                app.move_cursor_left();
                            }
                            KeyCode::Right => {
                                app.move_cursor_right();
                            }
                            KeyCode::PageUp | KeyCode::Up => {
                                app.scroll_up();
                            }
                            KeyCode::PageDown | KeyCode::Down => {
                                app.scroll_down();
                            }
                            KeyCode::End => {
                                app.reset_scroll();
                            }
                            _ => {}
                        }
                    }
                    AppEvent::MessageReceived(msg) => {
                        app.messages.push(msg);
                        if app.auto_scroll {
                            app.scroll_offset = 0;
                        }
                    }
                    AppEvent::UserJoined(new_user) => {
                        app.users.push(User {
                            name: new_user.clone(),
                            status: UserStatus::Online,
                        });
                        app.messages.push(ChatMessage {
                            timestamp: Local::now().format("%H:%M:%S").to_string(),
                            sender: "Système".to_string(),
                            content: format!("{} a rejoint le salon.", new_user),
                            is_self: false,
                            color: Color::Yellow,
                        });
                        if app.auto_scroll {
                            app.scroll_offset = 0;
                        }
                    }
                }
            }
        }
    }

    Ok(())
}

fn ui(f: &mut Frame, app: &mut App) {
    let main_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Min(5),
            Constraint::Length(1), // Barre d'aide
        ])
        .split(f.area());

    let content_layout = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(75), // Chat
            Constraint::Percentage(25), // Utilisateurs
        ])
        .split(main_layout[0]);

    let chat_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Min(3),    // Historique
            Constraint::Length(3), // Zone de saisie
        ])
        .split(content_layout[0]);

    render_chat_history(f, app, chat_layout[0]);
    render_input_box(f, app, chat_layout[1]);
    render_user_list(f, app, content_layout[1]);
    render_status_bar(f, app, main_layout[1]);
}

fn render_chat_history(f: &mut Frame, app: &App, area: Rect) {
    let message_lines: Vec<Line> = app
        .messages
        .iter()
        .map(|msg| {
            let sender_label = if msg.is_self {
                format!("{} (vous): ", msg.sender)
            } else {
                format!("{}: ", msg.sender)
            };

            Line::from(vec![
                Span::styled(
                    format!("[{}] ", msg.timestamp),
                    Style::default().fg(Color::DarkGray),
                ),
                Span::styled(
                    sender_label,
                    Style::default()
                        .fg(msg.color)
                        .add_modifier(Modifier::BOLD),
                ),
                Span::styled(&msg.content, Style::default().fg(Color::White)),
            ])
        })
        .collect();

    let total_lines = message_lines.len() as u16;
    let visible_height = area.height.saturating_sub(2); // Retirer les bordures

    // Calcul du scroll vertical
    let scroll_y = if app.auto_scroll {
        total_lines.saturating_sub(visible_height)
    } else {
        total_lines
            .saturating_sub(visible_height)
            .saturating_sub(app.scroll_offset)
    };

    let title = if app.auto_scroll {
        " Messages (Défilement auto activé) "
    } else {
        " Messages (Défilement manuel - Appuyez sur Fin pour reprendre) "
    };

    let messages_widget = Paragraph::new(message_lines)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .title(title)
                .border_style(Style::default().fg(Color::Cyan)),
        )
        .wrap(Wrap { trim: false })
        .scroll((scroll_y, 0));

    f.render_widget(messages_widget, area);
}

fn render_input_box(f: &mut Frame, app: &App, area: Rect) {
    let input_widget = Paragraph::new(app.input.as_str()).block(
        Block::default()
            .borders(Borders::ALL)
            .title(" Votre message (Entrée pour envoyer) ")
            .border_style(Style::default().fg(Color::Green)),
    );

    f.render_widget(input_widget, area);

    // Définir la position visible du curseur dans la zone de texte
    f.set_cursor_position((
        area.x + (app.cursor_position as u16).min(area.width.saturating_sub(3)) + 1,
        area.y + 1,
    ));
}

fn render_user_list(f: &mut Frame, app: &App, area: Rect) {
    let user_items: Vec<ListItem> = app
        .users
        .iter()
        .map(|u| {
            let (status_icon, status_color) = match u.status {
                UserStatus::Online => ("●", Color::Green),
                UserStatus::Idle => ("○", Color::Yellow),
            };

            ListItem::new(Line::from(vec![
                Span::styled(format!("{} ", status_icon), Style::default().fg(status_color)),
                Span::styled(
                    if u.name == app.current_username {
                        format!("{} (vous)", u.name)
                    } else {
                        u.name.clone()
                    },
                    Style::default().fg(Color::White),
                ),
            ]))
        })
        .collect();

    let user_count = app.users.len();
    let users_widget = List::new(user_items).block(
        Block::default()
            .borders(Borders::ALL)
            .title(format!(" En ligne ({}) ", user_count))
            .border_style(Style::default().fg(Color::LightBlue)),
    );

    f.render_widget(users_widget, area);
}

fn render_status_bar(f: &mut Frame, _app: &App, area: Rect) {
    let help_text = Line::from(vec![
        Span::styled(" [Esc/Ctrl+C] ", Style::default().fg(Color::DarkGray)),
        Span::raw("Quitter  "),
        Span::styled(" [Entrée] ", Style::default().fg(Color::DarkGray)),
        Span::raw("Envoyer  "),
        Span::styled(" [↑/↓/PgUp/PgDn] ", Style::default().fg(Color::DarkGray)),
        Span::raw("Défiler  "),
        Span::styled(" [Fin] ", Style::default().fg(Color::DarkGray)),
        Span::raw("Bas du chat"),
    ]);

    let help_widget = Paragraph::new(help_text);
    f.render_widget(help_widget, area);
}

