fn setup_terminal() -> io::Result<Terminal<CrosstermBackend<io::Stdout>>> {
    enable_raw_mode()?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    Terminal::new(backend)
}

fn restore_terminal(terminal: &mut Terminal<CrosstermBackend<io::Stdout>>) -> io::Result<()> {
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;
    Ok(())
}

fn install_panic_hook() {
    let original_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |panic_info| {
        let _ = disable_raw_mode();
        let _ = execute!(stdout(), LeaveAlternateScreen);
        original_hook(panic_info);
    }));
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    install_panic_hook();

    let mut terminal = setup_terminal()?;
    let mut app = App::new();

    let run_result = run_app(&mut terminal, &mut app);

    // Restaurer le terminal avant toute sortie finale
    restore_terminal(&mut terminal)?;

    if let Err(err) = run_result {
        eprintln!("Erreur lors de l'exécution de l'application : {}", err);
    } else {
        // Sauvegarde finale à la sortie
        if let Err(e) = app.save_tasks() {
            eprintln!("Avertissement : échec de la sauvegarde finale : {}", e);
        } else {
            println!("Tâches sauvegardées avec succès dans {}.", DATA_FILE);
        }
        println!("Kanban fermé avec succès. À bientôt !");
    }

    Ok(())
}

fn run_app(
    terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
    app: &mut App,
) -> io::Result<()> {
    loop {
        terminal.draw(|f| ui(f, app))?;

        if app.should_quit {
            return Ok(());
        }

        if event::poll(Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                app.handle_key(key);
            }
        }
    }
}

