```rust
// src/main.rs
use crossterm::{
    event::{self, Event, KeyCode, KeyEventKind, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::CrosstermBackend,
    layout::{Alignment, Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{
        Block, BorderType, Borders, Clear, List, ListItem, ListState, Paragraph, Wrap,
    },
    Frame, Terminal,
};
use serde::{Deserialize, Serialize};
use std::{
    fs::File,
    io::{self, stdout, BufReader, BufWriter},
    path::Path,
    time::Duration,
};

const DATA_FILE: &str = "tasks.json";

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
enum Status {
    Todo,
    InProgress,
    Done,
}

impl Status {
    const ALL: [Status; 3] = [Status::Todo, Status::InProgress, Status::Done];

    fn title(&self) -> &'static str {
        match self {
            Status::Todo => "📋 À faire",
            Status::InProgress => "⚡ En cours",
            Status::Done => "✅ Terminé",
        }
    }

    fn color(&self) -> Color {
        match self {
            Status::Todo => Color::LightYellow,
            Status::InProgress => Color::LightCyan,
            Status::Done => Color::LightGreen,
        }
    }

    fn next(&self) -> Status {
        match self {
            Status::Todo => Status::InProgress,
            Status::InProgress => Status::Done,
            Status::Done => Status::Done,
        }
    }

    fn prev(&self) -> Status {
        match self {
            Status::Todo => Status::Todo,
            Status::InProgress => Status::Todo,
            Status::Done => Status::InProgress,
        }
    }

    fn cycle_right(&self) -> Status {
        match self {
            Status::Todo => Status::InProgress,
            Status::InProgress => Status::Done,
            Status::Done => Status::Todo,
        }
    }

    fn cycle_left(&self) -> Status {
        match self {
            Status::Todo => Status::Done,
            Status::InProgress => Status::Todo,
            Status::Done => Status::InProgress,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Task {
    id: usize,
    title: String,
    description: String,
    status: Status,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum ModalMode {
    None,
    NewTaskTitle,
    NewTaskDesc { title: String },
    EditTaskTitle { task_id: usize },
    DeleteConfirm { task_id: usize, title: String },
    Help,
}

struct App {
    tasks: Vec<Task>,
    active_column: Status,
    selected_indices: [usize; 3],
    modal: ModalMode,
    input_buffer: String,
    status_message: String,
    next_id: usize,
    should_quit: bool,
}

impl App {
    fn new() -> Self {
        let mut app = Self {
            tasks: Vec::new(),
            active_column: Status::Todo,
            selected_indices: [0, 0, 0],
            modal: ModalMode::None,
            input_buffer: String::new(),
            status_message: String::from("Bienvenue dans votre Kanban ! Appuyez sur '?' pour l'aide."),
            next_id: 1,
            should_quit: false,
        };

        if let Err(e) = app.load_tasks() {
            app.status_message = format!("Fichier de données initialisé ({})", e);
            app.seed_default_tasks();
        }

        app.refresh_next_id();
        app
    }

    fn seed_default_tasks(&mut self) {
        self.tasks = vec![
            Task {
                id: 1,
                title: "Configurer l'environnement Rust".to_string(),
                description: "Vérifier rustc, cargo et les dépendances TUI.".to_string(),
                status: Status::Done,
            },
            Task {
                id: 2,
                title: "Développer le tableau Kanban Ratatui".to_string(),
                description: "Gérer l'affichage multi-colonnes et la navigation interactive.".to_string(),
                status: Status::InProgress,
            },
            Task {
                id: 3,
                title: "Ajouter la persistance JSON".to_string(),
                description: "Sauvegarder et restaurer automatiquement les tâches depuis tasks.json.".to_string(),
                status: Status::Todo,
            },
            Task {
                id: 4,
                title: "Rédiger la documentation & tests".to_string(),
                description: "Vérifier la robustesse et la clarté des raccourcis.".to_string(),
                status: Status::Todo,
            },
        ];
        self.refresh_next_id();
    }

    fn refresh_next_id(&mut self) {
        let max_id = self.tasks.iter().map(|t| t.id).max().unwrap_or(0);
        self.next_id = max_id + 1;
    }

    fn column_index(status: Status) -> usize {
        match status {
            Status::Todo => 0,
            Status::InProgress => 1,
            Status::Done => 2,
        }
    }

    fn tasks_for_column(&self, status: Status) -> Vec<&Task> {
        self.tasks.iter().filter(|t| t.status == status).collect()
    }

    fn selected_task(&self) -> Option<&Task> {
        let col_tasks = self.tasks_for_column(self.active_column);
        if col_tasks.is_empty() {
            None
        } else {
            let idx = self.selected_indices[Self::column_index(self.active_column)];
            col_tasks.get(idx).copied()
        }
    }

    fn clamp_selected_index(&mut self, status: Status) {
        let count = self.tasks_for_column(status).len();
        let idx = &mut self.selected_indices[Self::column_index(status)];
        if count == 0 {
            *idx = 0;
        } else if *idx >= count {
            *idx = count - 1;
        }
    }

    fn move_selection_down(&mut self) {
        let count = self.tasks_for_column(self.active_column).len();
        if count > 0 {
            let col_idx = Self::column_index(self.active_column);
            if self.selected_indices[col_idx] + 1 < count {
                self.selected_indices[col_idx] += 1;
            }
        }
    }

    fn move_selection_up(&mut self) {
        let col_idx = Self::column_index(self.active_column);
        if self.selected_indices[col_idx] > 0 {
            self.selected_indices[col_idx] -= 1;
        }
    }

    fn move_task_left(&mut self) {
        if let Some(task) = self.selected_task() {
            let task_id = task.id;
            let current_status = task.status;
            let target_status = current_status.prev();

            if target_status != current_status {
                if let Some(t) = self.tasks.iter_mut().find(|item| item.id == task_id) {
                    t.status = target_status;
                }
                self.clamp_selected_index(current_status);
                self.clamp_selected_index(target_status);
                self.status_message = format!("Tâche déplacée vers '{}'", target_status.title());
            }
        }
    }

    fn move_task_right(&mut self) {
        if let Some(task) = self.selected_task() {
            let task_id = task.id;
            let current_status = task.status;
            let target_status = current_status.next();

            if target_status != current_status {
                if let Some(t) = self.tasks.iter_mut().find(|item| item.id == task_id) {
                    t.status = target_status;
                }
                self.clamp_selected_index(current_status);
                self.clamp_selected_index(target_status);
                self.status_message = format!("Tâche déplacée vers '{}'", target_status.title());
            }
        }
    }

    fn delete_current_task(&mut self) {
        if let Some(task) = self.selected_task() {
            self.modal = ModalMode::DeleteConfirm {
                task_id: task.id,
                title: task.title.clone(),
            };
        } else {
            self.status_message = "Aucune tâche sélectionnée à supprimer.".to_string();
        }
    }

    fn execute_delete(&mut self, task_id: usize) {
        let col = self.active_column;
        self.tasks.retain(|t| t.id != task_id);
        self.clamp_selected_index(col);
        self.status_message = format!("Tâche #{} supprimée.", task_id);
    }

    fn open_add_modal(&mut self) {
        self.input_buffer.clear();
        self.modal = ModalMode::NewTaskTitle;
    }

    fn open_edit_modal(&mut self) {
        if let Some(task) = self.selected_task() {
            let task_id = task.id;
            let task_title = task.title.clone();
            self.input_buffer = task_title;
            self.modal = ModalMode::EditTaskTitle { task_id };
        } else {
            self.status_message = "Aucune tâche sélectionnée à modifier.".to_string();
        }
    }

    fn save_tasks(&mut self) -> io::Result<()> {
        let file = File::create(DATA_FILE)?;
        let writer = BufWriter::new(file);
        serde_json::to_writer_pretty(writer, &self.tasks)?;
        self.status_message = format!("Tâches sauvegardées dans '{}'.", DATA_FILE);
        Ok(())
    }

    fn load_tasks(&mut self) -> io::Result<()> {
        if !Path::new(DATA_FILE).exists() {
            return Err(io::Error::new(
                io::ErrorKind::NotFound,
                "Fichier tasks.json absent",
            ));
        }

        let file = File::open(DATA_FILE)?;
        let reader = BufReader::new(file);
        let tasks: Vec<Task> = serde_json::from_reader(reader)?;
        self.tasks = tasks;
        self.clamp_selected_index(Status::Todo);
        self.clamp_selected_index(Status::InProgress);
        self.clamp_selected_index(Status::Done);
        Ok(())
    }

    fn handle_key(&mut self, key: event::KeyEvent) {
        if key.kind != KeyEventKind::Press {
            return;
        }

        let current_modal = std::mem::replace(&mut self.modal, ModalMode::None);
        match current_modal {
            ModalMode::None => self.handle_normal_mode_key(key),
            ModalMode::Help => {
                if key.code == KeyCode::Esc || key.code == KeyCode::Char('?') || key.code == KeyCode::Char('q') || key.code == KeyCode::Enter {
                    self.modal = ModalMode::None;
                } else {
                    self.modal = ModalMode::Help;
                }
            }
            ModalMode::DeleteConfirm { task_id, title } => {
                match key.code {
                    KeyCode::Char('o') | KeyCode::Char('O') | KeyCode::Char('y') | KeyCode::Char('Y') | KeyCode::Enter => {
                        self.execute_delete(task_id);
                        self.modal = ModalMode::None;
                    }
                    KeyCode::Char('n') | KeyCode::Char('N') | KeyCode::Esc => {
                        self.modal = ModalMode::None;
                        self.status_message = "Suppression annulée.".to_string();
                    }
                    _ => {
                        self.modal = ModalMode::DeleteConfirm { task_id, title };
                    }
                }
            }
            ModalMode::NewTaskTitle => match key.code {
                KeyCode::Enter => {
                    let title = self.input_buffer.trim().to_string();
                    if !title.is_empty() {
                        self.input_buffer.clear();
                        self.modal = ModalMode::NewTaskDesc { title };
                    } else {
                        self.modal = ModalMode::NewTaskTitle;
                    }
                }
                KeyCode::Esc => {
                    self.input_buffer.clear();
                    self.modal = ModalMode::None;
                    self.status_message = "Ajout de tâche annulé.".to_string();
                }
                KeyCode::Backspace => {
                    self.input_buffer.pop();
                    self.modal = ModalMode::NewTaskTitle;
                }
                KeyCode::Char(c) => {
                    self.input_buffer.push(c);
                    self.modal = ModalMode::NewTaskTitle;
                }
                _ => {
                    self.modal = ModalMode::NewTaskTitle;
                }
            },
            ModalMode::NewTaskDesc { title } => match key.code {
                KeyCode::Enter => {
                    let desc = self.input_buffer.trim().to_string();
                    let new_task = Task {
                        id: self.next_id,
                        title: title.clone(),
                        description: desc,
                        status: self.active_column,
                    };
                    self.next_id += 1;
                    self.tasks.push(new_task);
                    self.input_buffer.clear();
                    self.clamp_selected_index(self.active_column);
                    let target_col = self.active_column;
                    let count = self.tasks_for_column(target_col).len();
                    self.selected_indices[Self::column_index(target_col)] = count.saturating_sub(1);
                    self.modal = ModalMode::None;
                    self.status_message = format!("Tâche '{}' ajoutée.", title);
                }
                KeyCode::Esc => {
                    self.input_buffer.clear();
                    self.modal = ModalMode::None;
                    self.status_message = "Ajout de tâche annulé.".to_string();
                }
                KeyCode::Backspace => {
                    self.input_buffer.pop();
                    self.modal = ModalMode::NewTaskDesc { title };
                }
                KeyCode::Char(c) => {
                    self.input_buffer.push(c);
                    self.modal = ModalMode::NewTaskDesc { title };
                }
                _ => {
                    self.modal = ModalMode::NewTaskDesc { title };
                }
            },
            ModalMode::EditTaskTitle { task_id } => match key.code {
                KeyCode::Enter => {
                    let new_title = self.input_buffer.trim().to_string();
                    if !new_title.is_empty() {
                        if let Some(task) = self.tasks.iter_mut().find(|t| t.id == task_id) {
                            task.title = new_title;
                            self.status_message = format!("Tâche #{} renommée.", task_id);
                        }
                    }
                    self.input_buffer.clear();
                    self.modal = ModalMode::None;
                }
                KeyCode::Esc => {
                    self.input_buffer.clear();
                    self.modal = ModalMode::None;
                    self.status_message = "Modification annulée.".to_string();
                }
                KeyCode::Backspace => {
                    self.input_buffer.pop();
                    self.modal = ModalMode::EditTaskTitle { task_id };
                }
                KeyCode::Char(c) => {
                    self.input_buffer.push(c);
                    self.modal = ModalMode::EditTaskTitle { task_id };
                }
                _ => {
                    self.modal = ModalMode::EditTaskTitle { task_id };
                }
            },
        }
    }

    fn handle_normal_mode_key(&mut self, key: event::KeyEvent) {
        match key.code {
            KeyCode::Char('q') => self.should_quit = true,
            KeyCode::Char('?') => self.modal = ModalMode::Help,
            KeyCode::Char('h') | KeyCode::Left => {
                if key.modifiers.contains(KeyModifiers::SHIFT) {
                    self.move_task_left();
                } else {
                    self.active_column = self.active_column.cycle_left();
                }
            }
            KeyCode::Char('l') | KeyCode::Right => {
                if key.modifiers.contains(KeyModifiers::SHIFT) {
                    self.move_task_right();
                } else {
                    self.active_column = self.active_column.cycle_right();
                }
            }
            KeyCode::Char('H') => self.move_task_left(),
            KeyCode::Char('L') => self.move_task_right(),
            KeyCode::Char('j') | KeyCode::Down => self.move_selection_down(),
            KeyCode::Char('k') | KeyCode::Up => self.move_selection_up(),
            KeyCode::Char('a') => self.open_add_modal(),
            KeyCode::Char('e') => self.open_edit_modal(),
            KeyCode::Char('d') | KeyCode::Delete => self.delete_current_task(),
            KeyCode::Char('s') => {
                if let Err(e) = self.save_tasks() {
                    self.status_message = format!("Erreur lors de la sauvegarde : {}", e);
                }
            }
            _ => {}
        }
    }
}

fn ui(f: &mut Frame, app: &mut App) {
    let size = f.area();

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // En-tête
            Constraint::Min(8),    // 3 Colonnes Kanban
            Constraint::Length(6), // Détails de la tâche sélectionnée
            Constraint::Length(3), // Barre de statut & raccourcis
        ])
        .split(size);

    // 1. En-tête
    let header = Paragraph::new(Line::from(vec![
        Span::styled(
            " 🦀 RUST KANBAN BOARD ",
            Style::default()
                .fg(Color::Black)
                .bg(Color::Cyan)
                .add_modifier(Modifier::BOLD),
        ),
        Span::styled(
            "  [h/l: Colonnes] [j/k: Sélection] [a: Ajouter] [H/L: Déplacer] [d: Suppr] [?: Aide] [q: Quitter]",
            Style::default().fg(Color::DarkGray),
        ),
    ]))
    .block(
        Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .border_style(Style::default().fg(Color::Cyan)),
    )
    .alignment(Alignment::Left);
    f.render_widget(header, chunks[0]);

    // 2. Colonnes Kanban
    let columns_layout = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(33),
            Constraint::Percentage(34),
            Constraint::Percentage(33),
        ])
        .split(chunks[1]);

    for (status_idx, status) in Status::ALL.iter().enumerate() {
        let is_active_col = *status == app.active_column;
        let border_color = if is_active_col {
            status.color()
        } else {
            Color::DarkGray
        };

        let tasks_in_col = app.tasks_for_column(*status);
        let items: Vec<ListItem> = tasks_in_col
            .iter()
            .enumerate()
            .map(|(item_idx, t)| {
                let is_selected = is_active_col && app.selected_indices[status_idx] == item_idx;
                let prefix = if is_selected { " ▶ " } else { "   " };
                let content = format!("{}{}. {}", prefix, t.id, t.title);

                let line_style = if is_selected {
                    Style::default()
                        .fg(Color::Black)
                        .bg(status.color())
                        .add_modifier(Modifier::BOLD)
                } else {
                    Style::default().fg(Color::White)
                };

                ListItem::new(Line::from(Span::styled(content, line_style)))
            })
            .collect();

        let title_style = if is_active_col {
            Style::default()
                .fg(status.color())
                .add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(Color::Gray)
        };

        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(if is_active_col {
                BorderType::Thick
            } else {
                BorderType::Rounded
            })
            .border_style(Style::default().fg(border_color))
            .title(Span::styled(
                format!(" {} ({}) ", status.title(), tasks_in_col.len()),
                title_style,
            ));

        let mut list_state = ListState::default();
        if is_active_col && !tasks_in_col.is_empty() {
            list_state.select(Some(app.selected_indices[status_idx]));
        }

        let list_widget = List::new(items).block(block);
        f.render_stateful_widget(list_widget, columns_layout[status_idx], &mut list_state);
    }

    // 3. Panneau de détails de la tâche active
    let detail_block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(Style::default().fg(Color::Blue))
        .title(Span::styled(
            " 🔍 Détails de la tâche sélectionnée ",
            Style::default().fg(Color::LightBlue).add_modifier(Modifier::BOLD),
        ));

    let details_text = if let Some(task) = app.selected_task() {
        vec![
            Line::from(vec![
                Span::styled("Identifiant : ", Style::default().fg(Color::DarkGray)),
                Span::styled(format!("#{}", task.id), Style::default().fg(Color::Yellow)),
                Span::raw("  |  "),
                Span::styled("Statut : ", Style::default().fg(Color::DarkGray)),
                Span::styled(
                    task.status.title(),
                    Style::default()
                        .fg(task.status.color())
                        .add_modifier(Modifier::BOLD),
                ),
            ]),
            Line::from(vec![
                Span::styled("Titre : ", Style::default().fg(Color::DarkGray)),
                Span::styled(
                    &task.title,
                    Style::default().fg(Color::White).add_modifier(Modifier::BOLD),
                ),
            ]),
            Line::from(vec![
                Span::styled("Description : ", Style::default().fg(Color::DarkGray)),
                Span::styled(
                    if task.description.is_empty() {
                        "(Aucune description)"
                    } else {
                        &task.description
                    },
                    Style::default().fg(Color::Gray),
                ),
            ]),
        ]
    } else {
        vec![Line::from(Span::styled(
            "Aucune tâche sélectionnée dans cette colonne. Appuyez sur 'a' pour en créer une.",
            Style::default().fg(Color::DarkGray),
        ))]
    };

    let details_p = Paragraph::new(details_text)
        .block(detail_block)
        .wrap(Wrap { trim: true });
    f.render_widget(details_p, chunks[2]);

    // 4. Barre d'état inférieure
    let status_bar = Paragraph::new(Line::from(vec![
        Span::styled(" [Statut] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::styled(&app.status_message, Style::default().fg(Color::White)),
    ]))
    .block(
        Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .border_style(Style::default().fg(Color::DarkGray)),
    );
    f.render_widget(status_bar, chunks[3]);

    // Rendu des fenêtres modales
    render_modals(f, app);
}

fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);

    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(popup_layout[1])[1]
}

