// src/main.rs
use std::{
    io,
    time::{Duration, Instant},
};

use anyhow::{Context, Result};
use crossterm::{
    event::{self, Event, KeyCode, KeyEventKind},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::CrosstermBackend,
    layout::{Alignment, Constraint, Direction, Layout},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{
        Block, BorderType, Borders, Gauge, List, ListItem, ListState, Paragraph,
    },
    Frame, Terminal,
};
use sysinfo::Disks;

/// Représentation simplifiée et formatée d'une partition / point de montage
#[derive(Clone, Debug)]
pub struct PartitionInfo {
    pub name: String,
    pub mount_point: String,
    pub fs_type: String,
    pub total_bytes: u64,
    pub available_bytes: u64,
    pub used_bytes: u64,
    pub usage_ratio: f64,
    pub is_removable: bool,
}

impl PartitionInfo {
    pub fn used_percentage(&self) -> u16 {
        (self.usage_ratio * 100.0).clamp(0.0, 100.0).round() as u16
    }
}

/// État global de l'application interactive
pub struct App {
    pub partitions: Vec<PartitionInfo>,
    pub list_state: ListState,
    pub should_quit: bool,
    pub last_refresh: Instant,
    pub disks: Disks,
}

impl App {
    pub fn new() -> Self {
        let disks = Disks::new_with_refreshed_list();
        let mut app = Self {
            partitions: Vec::new(),
            list_state: ListState::default(),
            should_quit: false,
            last_refresh: Instant::now(),
            disks,
        };
        app.refresh_disks();
        if !app.partitions.is_empty() {
            app.list_state.select(Some(0));
        }
        app
    }

    pub fn refresh_disks(&mut self) {
        self.disks.refresh(true);
        let mut list: Vec<PartitionInfo> = self
            .disks
            .iter()
            .map(|disk| {
                let total = disk.total_space();
                let available = disk.available_space();
                let used = total.saturating_sub(available);
                let usage_ratio = if total > 0 {
                    used as f64 / total as f64
                } else {
                    0.0
                };

                PartitionInfo {
                    name: disk.name().to_string_lossy().into_owned(),
                    mount_point: disk.mount_point().to_string_lossy().into_owned(),
                    fs_type: disk.file_system().to_string_lossy().into_owned(),
                    total_bytes: total,
                    available_bytes: available,
                    used_bytes: used,
                    usage_ratio,
                    is_removable: disk.is_removable(),
                }
            })
            .collect();

        // Trier par point de montage
        list.sort_by(|a, b| a.mount_point.cmp(&b.mount_point));
        self.partitions = list;
        self.last_refresh = Instant::now();

        // Réajuster l'index sélectionné si besoin
        if let Some(selected) = self.list_state.selected() {
            if self.partitions.is_empty() {
                self.list_state.select(None);
            } else if selected >= self.partitions.len() {
                self.list_state.select(Some(self.partitions.len() - 1));
            }
        } else if !self.partitions.is_empty() {
            self.list_state.select(Some(0));
        }
    }

    pub fn next(&mut self) {
        if self.partitions.is_empty() {
            return;
        }
        let i = match self.list_state.selected() {
            Some(i) => {
                if i >= self.partitions.len() - 1 {
                    0
                } else {
                    i + 1
                }
            }
            None => 0,
        };
        self.list_state.select(Some(i));
    }

    pub fn previous(&mut self) {
        if self.partitions.is_empty() {
            return;
        }
        let i = match self.list_state.selected() {
            Some(i) => {
                if i == 0 {
                    self.partitions.len() - 1
                } else {
                    i - 1
                }
            }
            None => 0,
        };
        self.list_state.select(Some(i));
    }
}

fn format_bytes(bytes: u64) -> String {
    const KIB: f64 = 1024.0;
    const MIB: f64 = KIB * 1024.0;
    const GIB: f64 = MIB * 1024.0;
    const TIB: f64 = GIB * 1024.0;

    let b = bytes as f64;
    if b >= TIB {
        format!("{:.2} TiB", b / TIB)
    } else if b >= GIB {
        format!("{:.2} GiB", b / GIB)
    } else if b >= MIB {
        format!("{:.2} MiB", b / MIB)
    } else if b >= KIB {
        format!("{:.2} KiB", b / KIB)
    } else {
        format!("{} B", bytes)
    }
}

fn get_gauge_color(percentage: u16) -> Color {
    if percentage >= 90 {
        Color::Red
    } else if percentage >= 75 {
        Color::Yellow
    } else {
        Color::Green
    }
}

