            Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .style(Style::default().fg(Color::DarkGray)),
        );
    frame.render_widget(footer, chunks[2]);
}

fn run_app<B: ratatui::backend::Backend>(
    terminal: &mut Terminal<B>,
    mut app: App,
    tick_rate: Duration,
) -> Result<()> {
    let mut last_tick = Instant::now();

    loop {
        terminal
            .draw(|f| render_ui(f, &mut app))
            .context("Échec du rendu du terminal")?;

        let timeout = tick_rate
            .checked_sub(last_tick.elapsed())
            .unwrap_or_else(|| Duration::from_secs(0));

        if crossterm::event::poll(timeout).context("Échec de la détection d'événement")? {
            if let Event::Key(key) = event::read().context("Échec de la lecture de l'événement")? {
                if key.kind == KeyEventKind::Press {
                    match key.code {
                        KeyCode::Char('q') | KeyCode::Esc => app.should_quit = true,
                        KeyCode::Down | KeyCode::Char('j') => app.next(),
                        KeyCode::Up | KeyCode::Char('k') => app.previous(),
                        KeyCode::Char('r') | KeyCode::Char('R') => app.refresh_disks(),
                        _ => {}
                    }
                }
            }
        }

        if last_tick.elapsed() >= tick_rate {
            // Auto-rafraîchissement périodique des disques
            app.refresh_disks();
            last_tick = Instant::now();
        }

        if app.should_quit {
            break;
        }
    }

    Ok(())
}

fn main() -> Result<()> {
    // Initialisation du terminal
    enable_raw_mode().context("Impossible d'activer le raw mode du terminal")?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen).context("Impossible d'entrer dans AlternateScreen")?;

    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend).context("Impossible d'initialiser le Terminal Ratatui")?;

    let app = App::new();
    let tick_rate = Duration::from_secs(3);

    // Boucle d'exécution avec gestion sécurisée de la restauration du terminal
    let res = run_app(&mut terminal, app, tick_rate);

    // Restauration du terminal
    disable_raw_mode().context("Impossible de désactiver le raw mode")?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)
        .context("Impossible de quitter AlternateScreen")?;
    terminal.show_cursor().context("Impossible d'afficher le curseur")?;

    if let Err(err) = res {
        eprintln!("Erreur lors de l'exécution de l'application: {err:?}");
    }

    Ok(())
}

