                .timeout(Duration::from_secs(30))
                .build()
                .unwrap_or_else(|_| reqwest::Client::new()),
            event_tx,
            event_rx,
        }
    }

    fn current_method(&self) -> Method {
        HTTP_METHODS[self.method_index].clone()
    }

    fn cycle_method(&mut self, forward: bool) {
        if forward {
            self.method_index = (self.method_index + 1) % HTTP_METHODS.len();
        } else if self.method_index == 0 {
            self.method_index = HTTP_METHODS.len() - 1;
        } else {
            self.method_index -= 1;
        }
    }

    fn trigger_request(&mut self) {
        if self.is_loading {
            return;
        }

        let url_str = self.url.trim().to_string();
        if url_str.is_empty() {
            self.status_message = "Erreur: L'URL ne peut pas être vide.".to_string();
            return;
        }

        let method = self.current_method();
        let headers_raw = self.headers_input.clone();
        let body_raw = self.body_input.clone();
        let client = self.client.clone();
        let tx = self.event_tx.clone();

        self.is_loading = true;
        self.status_message = format!("Envoi de la requête {} {}...", method, url_str);
        self.response_scroll = 0;

        let _ = tx.send(AppEvent::RequestStarted);

        tokio::spawn(async move {
            let start = Instant::now();
            let mut req = client.request(method.clone(), &url_str);

            for line in headers_raw.lines() {
                let line = line.trim();
                if line.is_empty() || line.starts_with('#') {
                    continue;
                }
                if let Some((k, v)) = line.split_once(':') {
                    let k = k.trim();
                    let v = v.trim();
                    if let Ok(name) = HeaderName::from_str(k) {
                        if let Ok(val) = reqwest::header::HeaderValue::from_str(v) {
                            req = req.header(name, val);
                        }
                    }
                }
            }

            if method != Method::GET && method != Method::HEAD && !body_raw.is_empty() {
                req = req.body(body_raw);
            }

            let result = match req.send().await {
                Ok(resp) => {
                    let elapsed_ms = start.elapsed().as_millis();
                    let status = resp.status().as_u16();
                    let status_text = resp
                        .status()
                        .canonical_reason()
                        .unwrap_or("Unknown")
                        .to_string();

                    let headers = resp
                        .headers()
                        .iter()
                        .map(|(k, v)| {
                            (
                                k.as_str().to_string(),
                                v.to_str().unwrap_or("<binaire>").to_string(),
                            )
                        })
                        .collect();

                    let text = resp.text().await.unwrap_or_else(|e| format!("<Erreur lecture body: {e}>"));
                    // Tente de formater en pretty JSON si possible
                    let formatted_body = match serde_json::from_str::<serde_json::Value>(&text) {
                        Ok(json) => serde_json::to_string_pretty(&json).unwrap_or(text),
                        Err(_) => text,
                    };

                    Ok(HttpResponseData {
                        status,
                        status_text,
                        elapsed_ms,
                        headers,
                        body: formatted_body,
                    })
                }
                Err(err) => Err(err.to_string()),
            };

            let _ = tx.send(AppEvent::RequestFinished(result));
        });
    }

    fn handle_key(&mut self, code: KeyCode, modifiers: KeyModifiers) {
        // Raccourcis globaux
        if code == KeyCode::Esc {
            self.should_quit = true;
            return;
        }

        if code == KeyCode::F(5) || (modifiers.contains(KeyModifiers::CONTROL) && code == KeyCode::Char('r')) {
            self.trigger_request();
            return;
        }

        if code == KeyCode::BackTab {
            self.focus = self.focus.prev();
            return;
        }

        if code == KeyCode::Tab {
            self.focus = self.focus.next();
            return;
        }

        // Actions dépendantes du focus
        match self.focus {
            FocusField::Method => match code {
                KeyCode::Left | KeyCode::Up => self.cycle_method(false),
                KeyCode::Right | KeyCode::Down | KeyCode::Char(' ') => self.cycle_method(true),
                KeyCode::Enter => self.trigger_request(),
                _ => {}
            },
            FocusField::Url => match code {
                KeyCode::Char(c) => self.url.push(c),
                KeyCode::Backspace => {
                    self.url.pop();
                }
                KeyCode::Enter => self.trigger_request(),
                _ => {}
            },
            FocusField::Headers => match code {
                KeyCode::Char(c) => self.headers_input.push(c),
                KeyCode::Backspace => {
                    self.headers_input.pop();
                }
                KeyCode::Enter => self.headers_input.push('\n'),
                _ => {}
            },
            FocusField::Body => match code {
                KeyCode::Char(c) => self.body_input.push(c),
                KeyCode::Backspace => {
                    self.body_input.pop();
                }
                KeyCode::Enter => self.body_input.push('\n'),
                _ => {}
            },
            FocusField::Response => match code {
                KeyCode::Down | KeyCode::Char('j') => {
                    self.response_scroll = self.response_scroll.saturating_add(1);
                }
                KeyCode::Up | KeyCode::Char('k') => {
                    self.response_scroll = self.response_scroll.saturating_sub(1);
                }
                KeyCode::PageDown => {
                    self.response_scroll = self.response_scroll.saturating_add(10);
                }
                KeyCode::PageUp => {
                    self.response_scroll = self.response_scroll.saturating_sub(10);
                }
                KeyCode::Home => {
                    self.response_scroll = 0;
                }
                _ => {}
            },
        }
    }

    fn check_events(&mut self) {
        while let Ok(event) = self.event_rx.try_recv() {
            match event {
                AppEvent::RequestStarted => {
                    self.is_loading = true;
                }
                AppEvent::RequestFinished(result) => {
                    self.is_loading = false;
                    match result {
                        Ok(data) => {
                            self.status_message = format!(
                                "Succès: {} {} ({} ms)",
                                data.status, data.status_text, data.elapsed_ms
                            );
                            self.response_data = Some(data);
                        }
                        Err(err) => {
                            self.status_message = format!("Erreur réseau: {err}");
                        }
                    }
                }
            }
        }
    }
}

fn draw_ui(f: &mut Frame, app: &App) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // Barre supérieure (Méthode + URL)
            Constraint::Length(7), // Headers
            Constraint::Length(8), // Body
            Constraint::Min(6),    // Réponse
            Constraint::Length(2), // Barre d'état & aide
        ])
        .split(f.area());

    // 1. Barre Méthode + URL
    let top_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Length(14), Constraint::Min(20)])
        .split(chunks[0]);

    // Panneau Méthode
    let method_block = Block::default()
        .title(" [1] Méthode ")
        .borders(Borders::ALL)
        .border_style(if app.focus == FocusField::Method {
            Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(Color::DarkGray)
        });
    let current_method_text = format!("◀ {} ▶", app.current_method().as_str());
    let method_paragraph = Paragraph::new(current_method_text)
        .block(method_block)
        .alignment(Alignment::Center)
        .style(
            Style::default()
                .fg(Color::Cyan)
                .add_modifier(Modifier::BOLD),
        );
    f.render_widget(method_paragraph, top_chunks[0]);

    // Panneau URL
    let url_block = Block::default()
        .title(" [2] URL ")
        .borders(Borders::ALL)
        .border_style(if app.focus == FocusField::Url {
            Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(Color::DarkGray)
        });
    let url_display = if app.focus == FocusField::Url {
        format!("{}█", app.url)
    } else {
        app.url.clone()
    };
    let url_paragraph = Paragraph::new(url_display)
        .block(url_block)
        .style(Style::default().fg(Color::White));
    f.render_widget(url_paragraph, top_chunks[1]);

    // 2. Panneau En-têtes (Headers)
    let headers_block = Block::default()
        .title(" [3] Headers HTTP (Format: Clé: Valeur) ")
        .borders(Borders::ALL)
        .border_style(if app.focus == FocusField::Headers {
            Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(Color::DarkGray)
        });
    let headers_display = if app.focus == FocusField::Headers {
        format!("{}█", app.headers_input)
    } else {
        app.headers_input.clone()
    };
    let headers_paragraph = Paragraph::new(headers_display)
        .block(headers_block)
        .wrap(Wrap { trim: false })
        .style(Style::default().fg(Color::LightCyan));
    f.render_widget(headers_paragraph, chunks[1]);

    // 3. Panneau Corps (Body)
    let body_block = Block::default()
        .title(" [4] Body (JSON / Raw) ")
        .borders(Borders::ALL)
        .border_style(if app.focus == FocusField::Body {
            Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(Color::DarkGray)
        });
    let body_display = if app.focus == FocusField::Body {
        format!("{}█", app.body_input)
    } else {
        app.body_input.clone()
    };
    let body_paragraph = Paragraph::new(body_display)
        .block(body_block)
        .wrap(Wrap { trim: false })
        .style(Style::default().fg(Color::LightGreen));
    f.render_widget(body_paragraph, chunks[2]);

    // 4. Panneau Réponse (Response)
    let response_block = Block::default()
        .title(" [5] Réponse HTTP ")
        .borders(Borders::ALL)
        .border_style(if app.focus == FocusField::Response {
            Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(Color::DarkGray)
        });

    let response_lines = if app.is_loading {
        vec![Line::from(Span::styled(
            "⏳ Requête en cours...",
            Style::default().fg(Color::Yellow).add_modifier(Modifier::ITALIC),
        ))]
    } else if let Some(resp) = &app.response_data {
        let status_color = if resp.status < 300 {
            Color::Green
        } else if resp.status < 400 {
            Color::Blue
        } else if resp.status < 500 {
            Color::Yellow
        } else {
            Color::Red
        };

        let mut lines = Vec::new();
        lines.push(Line::from(vec![
            Span::styled("Status: ", Style::default().add_modifier(Modifier::BOLD)),
            Span::styled(
                format!("{} {}", resp.status, resp.status_text),
                Style::default().fg(status_color).add_modifier(Modifier::BOLD),
            ),
            Span::raw(" | "),
            Span::styled("Temps: ", Style::default().add_modifier(Modifier::BOLD)),
            Span::styled(format!("{} ms", resp.elapsed_ms), Style::default().fg(Color::Cyan)),
        ]));
        lines.push(Line::from(""));
        lines.push(Line::from(Span::styled(
            "--- En-têtes de Réponse ---",
            Style::default().fg(Color::DarkGray),
        )));
        for (k, v) in &resp.headers {
            lines.push(Line::from(vec![
                Span::styled(format!("{}: ", k), Style::default().fg(Color::LightBlue)),
                Span::raw(v),
            ]));
        }
        lines.push(Line::from(""));
        lines.push(Line::from(Span::styled(
            "--- Corps de Réponse ---",
            Style::default().fg(Color::DarkGray),
        )));
        for line in resp.body.lines() {
            lines.push(Line::from(line));
        }
        lines
    } else {
        vec![Line::from(Span::styled(
            "Aucune réponse pour le moment. Configurez l'URL et appuyez sur [F5] ou [Ctrl+R].",
            Style::default().fg(Color::DarkGray),
        ))]
    };

    let response_paragraph = Paragraph::new(response_lines)
        .block(response_block)
        .scroll((app.response_scroll, 0))
        .wrap(Wrap { trim: false });
    f.render_widget(response_paragraph, chunks[3]);

    // 5. Barre de statut & Aide
    let status_line = Line::from(vec![
        Span::styled(" [TAB] ", Style::default().bg(Color::DarkGray).fg(Color::White)),
        Span::raw(" Naviguer | "),
        Span::styled(" [F5 / Ctrl+R] ", Style::default().bg(Color::DarkGray).fg(Color::White)),
        Span::raw(" Envoyer | "),
        Span::styled(" [Échap] ", Style::default().bg(Color::DarkGray).fg(Color::White)),
        Span::raw(" Quitter | "),
        Span::styled(&app.status_message, Style::default().fg(Color::Magenta)),
    ]);
    let status_paragraph = Paragraph::new(status_line);
    f.render_widget(status_paragraph, chunks[4]);
}

fn setup_terminal() -> Result<Terminal<CrosstermBackend<Stdout>>> {
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let terminal = Terminal::new(backend)?;
    Ok(terminal)
}

fn restore_terminal(mut terminal: Terminal<CrosstermBackend<Stdout>>) -> Result<()> {
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;
    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    let mut terminal = setup_terminal()?;
    let mut app = App::new();

    let res = run_app(&mut terminal, &mut app).await;

    restore_terminal(terminal)?;

    if let Err(err) = res {
        eprintln!("Erreur lors de l'exécution: {err:?}");
    }

    Ok(())
}

async fn run_app(
    terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    app: &mut App,
) -> Result<()> {
    while !app.should_quit {
        app.check_events();

        terminal.draw(|f| draw_ui(f, app))?;

        if event::poll(Duration::from_millis(50))? {
            if let Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press {
                    app.handle_key(key.code, key.modifiers);
                }
            }
        }
    }
    Ok(())
}

