/// État global de l'application
struct App {
    tables: Vec<TableData>,
    current_table_idx: usize,
    table_state: TableState,
    horizontal_offset: usize,
    should_quit: bool,
}

impl App {
    fn new(tables: Vec<TableData>, initial_table: Option<&str>) -> Self {
        let current_table_idx = if let Some(target) = initial_table {
            tables.iter().position(|t| t.name == target).unwrap_or(0)
        } else {
            0
        };

        let mut table_state = TableState::default();
        if !tables.is_empty() && !tables[current_table_idx].rows.is_empty() {
            table_state.select(Some(0));
        }

        Self {
            tables,
            current_table_idx,
            table_state,
            horizontal_offset: 0,
            should_quit: false,
        }
    }

    fn current_table(&self) -> Option<&TableData> {
        self.tables.get(self.current_table_idx)
    }

    fn next_row(&mut self, step: usize) {
        if let Some(table) = self.current_table() {
            if table.rows.is_empty() {
                return;
            }
            let i = match self.table_state.selected() {
                Some(i) => min(i.saturating_add(step), table.rows.len() - 1),
                None => 0,
            };
            self.table_state.select(Some(i));
        }
    }

    fn previous_row(&mut self, step: usize) {
        if let Some(table) = self.current_table() {
            if table.rows.is_empty() {
                return;
            }
            let i = match self.table_state.selected() {
                Some(i) => i.saturating_sub(step),
                None => 0,
            };
            self.table_state.select(Some(i));
        }
    }

    fn first_row(&mut self) {
        if let Some(table) = self.current_table() {
            if !table.rows.is_empty() {
                self.table_state.select(Some(0));
            }
        }
    }

    fn last_row(&mut self) {
        if let Some(table) = self.current_table() {
            if !table.rows.is_empty() {
                self.table_state.select(Some(table.rows.len() - 1));
            }
        }
    }

    fn scroll_right(&mut self) {
        if let Some(table) = self.current_table() {
            if self.horizontal_offset + 1 < table.headers.len() {
                self.horizontal_offset += 1;
            }
        }
    }

    fn scroll_left(&mut self) {
        if self.horizontal_offset > 0 {
            self.horizontal_offset -= 1;
        }
    }

    fn next_table(&mut self) {
        if self.tables.is_empty() {
            return;
        }
        self.current_table_idx = (self.current_table_idx + 1) % self.tables.len();
        self.horizontal_offset = 0;
        self.table_state = TableState::default();
        if let Some(t) = self.current_table() {
            if !t.rows.is_empty() {
                self.table_state.select(Some(0));
            }
        }
    }

    fn previous_table(&mut self) {
        if self.tables.is_empty() {
            return;
        }
        if self.current_table_idx == 0 {
            self.current_table_idx = self.tables.len() - 1;
        } else {
            self.current_table_idx -= 1;
        }
        self.horizontal_offset = 0;
        self.table_state = TableState::default();
        if let Some(t) = self.current_table() {
            if !t.rows.is_empty() {
                self.table_state.select(Some(0));
            }
        }
    }
}

