fn load_tables(conn: &Connection) -> Result<Vec<TableData>> {
    let mut stmt = conn.prepare(
        "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name ASC",
    )?;

    let table_names = stmt
        .query_map([], |row| row.get::<_, String>(0))?
        .collect::<Result<Vec<String>, _>>()
        .context("Échec de la récupération des noms de tables")?;

    let mut tables = Vec::new();

    for table_name in table_names {
        let query = format!("SELECT * FROM \"{}\"", table_name.replace('"', "\"\""));
        let mut query_stmt = match conn.prepare(&query) {
            Ok(s) => s,
            Err(_) => continue,
        };

        let headers: Vec<String> = query_stmt
            .column_names()
            .iter()
            .map(|s| s.to_string())
            .collect();

        let num_cols = headers.len();
        let mut rows = Vec::new();

        let mut row_iter = query_stmt.query([])?;
        while let Some(row) = row_iter.next()? {
            let mut current_row = Vec::with_capacity(num_cols);
            for col_idx in 0..num_cols {
                let cell_val = match row.get_ref(col_idx)? {
                    ValueRef::Null => "NULL".to_string(),
                    ValueRef::Integer(v) => v.to_string(),
                    ValueRef::Real(v) => format!("{:.2}", v),
                    ValueRef::Text(v) => String::from_utf8_lossy(v).to_string(),
                    ValueRef::Blob(v) => format!("<BLOB {}o>", v.len()),
                };
                current_row.push(cell_val);
            }
            rows.push(current_row);
        }

        tables.push(TableData {
            name: table_name,
            headers,
            rows,
        });
    }

    Ok(tables)
}

/// Calcule les contraintes de colonnes proportionnellement au contenu visible
fn calculate_column_constraints(
    table: &TableData,
    visible_start: usize,
    max_table_width: u16,
) -> (Vec<Constraint>, usize) {
    if table.headers.is_empty() {
        return (Vec::new(), 0);
    }

    let col_count = table.headers.len();
    let mut widths = Vec::new();

    for col_idx in visible_start..col_count {
        let mut max_w = UnicodeWidthStr::width(table.headers[col_idx].as_str());

        // Analyse les largeurs de texte des lignes disponibles
        for row in &table.rows {
            if let Some(cell) = row.get(col_idx) {
                let w = UnicodeWidthStr::width(cell.as_str());
                if w > max_w {
                    max_w = w;
                }
            }
        }

        // Garde-fous : minimum 6 caractères, maximum 40 pour éviter les écrasements
        let clamped = max(6, min(max_w + 2, 40));
        widths.push((col_idx, clamped as u16));
    }

    let mut constraints = Vec::new();
    let mut used_width: u16 = 0;
    let mut visible_cols_count = 0;

    for (_, w) in &widths {
        if used_width + *w + 1 > max_table_width && visible_cols_count > 0 {
            break;
        }
        constraints.push(Constraint::Length(*w));
        used_width += *w + 1;
        visible_cols_count += 1;
    }

    if constraints.is_empty() && !widths.is_empty() {
        constraints.push(Constraint::Length(widths[0].1));
        visible_cols_count = 1;
    }

    (constraints, visible_cols_count)
}

fn render_ui(f: &mut Frame, app: &mut App) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // En-tête / Onglets
            Constraint::Min(5),    // Corps de la table
            Constraint::Length(3), // Barre d'état & aide
        ])
        .split(f.area());

    // 1. Zone Titre & Onglets
    let current_table = app.current_table();
    let table_name = current_table
        .map(|t| t.name.as_str())
        .unwrap_or("Aucune table");

    let tabs_spans: Vec<Span> = app
        .tables
        .iter()
        .enumerate()
        .map(|(idx, t)| {
            if idx == app.current_table_idx {
                Span::styled(
                    format!(" [{}] ", t.name),
                    Style::default()
                        .fg(Color::Yellow)
                        .add_modifier(Modifier::BOLD),
                )
            } else {
                Span::styled(format!("  {}  ", t.name), Style::default().fg(Color::DarkGray))
            }
        })
        .collect();

    let header_widget = Paragraph::new(Line::from(tabs_spans)).block(
        Block::default()
            .borders(Borders::ALL)
            .title(format!(" Visualiseur SQL | Table active : [{}] ", table_name))
            .border_style(Style::default().fg(Color::Cyan)),
    );
    f.render_widget(header_widget, chunks[0]);

    // 2. Zone Tableau avec pagination et ajustement
    if let Some(table_data) = app.tables.get(app.current_table_idx) {
        let (constraints, visible_cols_count) =
            calculate_column_constraints(table_data, app.horizontal_offset, chunks[1].width);

        let end_col = min(
            app.horizontal_offset + visible_cols_count,
            table_data.headers.len(),
        );

        let header_cells: Vec<Cell> = table_data.headers[app.horizontal_offset..end_col]
            .iter()
            .map(|h| {
                Cell::from(h.as_str()).style(
                    Style::default()
                        .fg(Color::Yellow)
                        .add_modifier(Modifier::BOLD),
                )
            })
            .collect();

        let header_row = Row::new(header_cells)
            .style(Style::default().bg(Color::Rgb(30, 30, 46)))
            .height(1);

        let rows: Vec<Row> = table_data
            .rows
            .iter()
            .enumerate()
            .map(|(i, r)| {
                let cells: Vec<Cell> = r[app.horizontal_offset..end_col]
                    .iter()
                    .map(|c| {
                        let text = if c == "NULL" {
                            Span::styled(c, Style::default().fg(Color::DarkGray))
                        } else {
                            Span::raw(c)
                        };
                        Cell::from(text)
                    })
                    .collect();

                let bg_color = if i % 2 == 0 {
                    Color::Rgb(24, 24, 37)
                } else {
                    Color::Rgb(17, 17, 27)
                };

                Row::new(cells)
                    .style(Style::default().bg(bg_color))
                    .height(1)
            })
            .collect();

        let col_info = if table_data.headers.is_empty() {
            "Colonnes: 0".to_string()
        } else {
            format!(
                "Colonnes {} à {} sur {}",
                app.horizontal_offset + 1,
                end_col,
                table_data.headers.len()
            )
        };

        let table_widget = Table::new(rows, constraints)
            .header(header_row)
            .block(
                Block::default()
                    .borders(Borders::ALL)
                    .title(format!(" Contenu ({}) ", col_info))
                    .border_style(Style::default().fg(Color::White)),
            )
            .highlight_style(
                Style::default()
                    .bg(Color::Rgb(49, 50, 68))
                    .fg(Color::White)
                    .add_modifier(Modifier::BOLD),
            )
            .highlight_symbol("▶ ");

        let table_state = &mut app.table_state;
        f.render_stateful_widget(table_widget, chunks[1], table_state);
    } else {
        let empty_msg = Paragraph::new("Aucune donnée disponible dans cette table.")
            .block(Block::default().borders(Borders::ALL));
        f.render_widget(empty_msg, chunks[1]);
    }

    // 3. Pied de page & barre d'aide
    render_footer(f, chunks[2], app);
}

fn render_footer(f: &mut Frame, area: Rect, app: &App) {
    let (total_rows, selected_str) = match app.current_table() {
        Some(t) => {
            let total = t.rows.len();
            let sel = app
                .table_state
                .selected()
                .map(|s| format!("Ligne: {}/{}", s + 1, total))
                .unwrap_or_else(|| "0/0".to_string());
            (total, sel)
        }
        None => (0, "0/0".to_string()),
    };

    let help_line = Line::from(vec![
        Span::styled(" [q/Esc] ", Style::default().fg(Color::Red)),
        Span::raw("Quitter "),
        Span::styled(" [↑/↓ ou j/k] ", Style::default().fg(Color::Cyan)),
        Span::raw("Naviguer "),
        Span::styled(" [PgUp/PgDn] ", Style::default().fg(Color::Cyan)),
        Span::raw("Page "),
        Span::styled(" [←/→ ou h/l] ", Style::default().fg(Color::Cyan)),
        Span::raw("Cols "),
        Span::styled(" [Tab] ", Style::default().fg(Color::Green)),
        Span::raw("Table "),
        Span::styled(format!(" | {} ", selected_str), Style::default().fg(Color::Yellow)),
    ]);

    let footer = Paragraph::new(help_line).block(
        Block::default()
            .borders(Borders::ALL)
            .title(format!(" Informations (Total: {} entrées) ", total_rows))
            .border_style(Style::default().fg(Color::Gray)),
    );

    f.render_widget(footer, area);
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    let conn = if let Some(ref path) = cli.database {
        Connection::open(path)
            .with_context(|| format!("Impossible d'ouvrir le fichier SQL: {:?}", path))?
    } else {
        create_sample_database()?
    };

    let tables = load_tables(&conn).context("Erreur lors de la lecture des tables SQL")?;
    if tables.is_empty() {
        println!("Aucune table trouvée dans la base de données.");
        return Ok(());
    }

    // Initialisation du terminal en Raw Mode
    enable_raw_mode().context("Impossible d'activer le mode Raw du terminal")?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen).context("Échec d'entrée dans le Alternate Screen")?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal =
        Terminal::new(backend).context("Échec de création du terminal Ratatui")?;

    let mut app = App::new(tables, cli.table.as_deref());

    // Boucle d'événements principale
    let run_res = run_app(&mut terminal, &mut app);

    // Restauration du terminal garantie même après une erreur
    let _ = disable_raw_mode();
    let _ = execute!(terminal.backend_mut(), LeaveAlternateScreen);
    let _ = terminal.show_cursor();

    run_res
}

fn run_app(terminal: &mut Terminal<CrosstermBackend<io::Stdout>>, app: &mut App) -> Result<()> {
    while !app.should_quit {
        terminal.draw(|f| render_ui(f, app))?;

        if event::poll(Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press {
                    match key.code {
                        KeyCode::Char('q') | KeyCode::Esc => {
                            app.should_quit = true;
                        }
                        KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                            app.should_quit = true;
                        }
                        KeyCode::Down | KeyCode::Char('j') => {
                            app.next_row(1);
                        }
                        KeyCode::Up | KeyCode::Char('k') => {
                            app.previous_row(1);
                        }
                        KeyCode::PageDown | KeyCode::Char(' ') => {
                            app.next_row(15);
                        }
                        KeyCode::PageUp | KeyCode::Char('b') => {
                            app.previous_row(15);
                        }
                        KeyCode::Home | KeyCode::Char('g') => {
                            app.first_row();
                        }
                        KeyCode::End | KeyCode::Char('G') => {
                            app.last_row();
                        }
                        KeyCode::Right | KeyCode::Char('l') => {
                            app.scroll_right();
                        }
                        KeyCode::Left | KeyCode::Char('h') => {
                            app.scroll_left();
                        }
                        KeyCode::Tab => {
                            if key.modifiers.contains(KeyModifiers::SHIFT) {
                                app.previous_table();
                            } else {
                                app.next_table();
                            }
                        }
                        KeyCode::BackTab => {
                            app.previous_table();
                        }
                        _ => {}
                    }
                }
            }
        }
    }

    Ok(())
}

