// src/main.rs
use std::collections::VecDeque;
use std::io;
use std::time::Duration;

use chrono::Local;
use crossterm::{
    event::{Event, EventStream, KeyCode, KeyEventKind, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use futures::StreamExt;
use rand::Rng;
use ratatui::{
    backend::CrosstermBackend,
    layout::{Alignment, Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    symbols,
    text::{Line, Span},
    widgets::{
        Axis, Block, Borders, Cell, Chart, Dataset, GraphType, Paragraph, Row, Table,
        TableState, Wrap,
    },
    Frame, Terminal,
};
use tokio::sync::mpsc;

/// Nombre maximum de points conservés pour l'historique d'un instrument
const HISTORY_CAPACITY: usize = 60;
/// Nombre maximum de lignes dans le journal de flux
const FEED_LOG_CAPACITY: usize = 30;

/// Modèle représentant un instrument financier
#[derive(Debug, Clone)]
pub struct Stock {
    pub symbol: String,
    pub name: String,
    pub price: f64,
    pub open_price: f64,
    pub high: f64,
    pub low: f64,
    pub volume: u64,
    pub volatility: f64,
    pub history: VecDeque<f64>,
}

impl Stock {
    pub fn new(symbol: &str, name: &str, initial_price: f64, volatility: f64) -> Self {
        let mut history = VecDeque::with_capacity(HISTORY_CAPACITY);
        history.push_back(initial_price);
        Self {
            symbol: symbol.to_string(),
            name: name.to_string(),
            price: initial_price,
            open_price: initial_price,
            high: initial_price,
            low: initial_price,
            volume: 0,
            volatility,
            history,
        }
    }

    /// Met à jour le cours de l'action selon une variation stochastique
    pub fn apply_tick(&mut self, price_change_pct: f64, volume_delta: u64) {
        let new_price = (self.price * (1.0 + price_change_pct)).max(0.01);
        self.price = (new_price * 100.0).round() / 100.0;
        self.volume = self.volume.saturating_add(volume_delta);

        if self.price > self.high {
            self.high = self.price;
        }
        if self.price < self.low {
            self.low = self.price;
        }

        if self.history.len() >= HISTORY_CAPACITY {
            self.history.pop_front();
        }
        self.history.push_back(self.price);
    }

    pub fn change(&self) -> f64 {
        self.price - self.open_price
    }

    pub fn change_pct(&self) -> f64 {
        if self.open_price == 0.0 {
            0.0
        } else {
            (self.change() / self.open_price) * 100.0
        }
    }
}

/// Message émis par la tâche de marché asynchrone
#[derive(Debug, Clone)]
pub struct MarketTick {
    pub symbol: String,
    pub price_delta_pct: f64,
    pub volume: u64,
    pub timestamp: chrono::DateTime<Local>,
}

/// État global de l'application TUI
pub struct AppState {
    pub stocks: Vec<Stock>,
    pub table_state: TableState,
    pub logs: VecDeque<String>,
    pub is_paused: bool,
    pub should_quit: bool,
    pub tick_counter: u64,
}

impl Default for AppState {
    fn default() -> Self {
        Self::new()
    }
}

impl AppState {
    pub fn new() -> Self {
        let stocks = vec![
            Stock::new("AAPL", "Apple Inc.", 228.50, 0.0035),
            Stock::new("MSFT", "Microsoft Corp.", 442.20, 0.0030),
            Stock::new("GOOGL", "Alphabet Inc.", 182.10, 0.0040),
            Stock::new("NVDA", "Nvidia Corp.", 124.80, 0.0065),
            Stock::new("TSLA", "Tesla Inc.", 248.90, 0.0070),
            Stock::new("BTC-USD", "Bitcoin Spot", 64320.00, 0.0055),
            Stock::new("EUR-USD", "Euro / US Dollar", 1.0850, 0.0012),
        ];

        let mut table_state = TableState::default();
        table_state.select(Some(0));

        let mut logs = VecDeque::with_capacity(FEED_LOG_CAPACITY);
        logs.push_back(format!(
            "[{}] Initialisation du simulateur de terminal boursier.",
            Local::now().format("%H:%M:%S")
        ));
        logs.push_back(format!(
            "[{}] Connexion au flux temps réel établie.",
            Local::now().format("%H:%M:%S")
        ));

        Self {
            stocks,
            table_state,
            logs,
            is_paused: false,
            should_quit: false,
            tick_counter: 0,
        }
    }

    pub fn selected_stock(&self) -> Option<&Stock> {
        let index = self.table_state.selected()?;
        self.stocks.get(index)
    }

    pub fn next_stock(&mut self) {
        if self.stocks.is_empty() {
            return;
        }
        let next = match self.table_state.selected() {
            Some(i) => (i + 1) % self.stocks.len(),
            None => 0,
        };
        self.table_state.select(Some(next));
    }

    pub fn previous_stock(&mut self) {
        if self.stocks.is_empty() {
            return;
        }
        let prev = match self.table_state.selected() {
            Some(i) => {
                if i == 0 {
                    self.stocks.len() - 1
                } else {
                    i - 1
                }
            }
            None => 0,
        };
        self.table_state.select(Some(prev));
    }

    pub fn add_log(&mut self, message: String) {
        if self.logs.len() >= FEED_LOG_CAPACITY {
            self.logs.pop_front();
        }
        self.logs.push_back(message);
    }

    pub fn update_stock(&mut self, tick: MarketTick) {
        if let Some(stock) = self.stocks.iter_mut().find(|s| s.symbol == tick.symbol) {
            let old_price = stock.price;
            stock.apply_tick(tick.price_delta_pct, tick.volume);
            self.tick_counter += 1;

            let diff = stock.price - old_price;
            let arrow = if diff >= 0.0 { "▲" } else { "▼" };
            let sign = if diff >= 0.0 { "+" } else { "" };

            let log_msg = format!(
                "[{}] TICK {} : {:.2} ({} {:.2}) | Vol: {}",
                tick.timestamp.format("%H:%M:%S"),
                tick.symbol,
                stock.price,
                arrow,
                sign.to_string() + &format!("{:.2}", diff),
                tick.volume
            );
            self.add_log(log_msg);
        }
    }
}

/// Tâche de fond simulant les fluctuations de marché avec Tokio
async fn market_feed_task(tx: mpsc::Sender<MarketTick>) {
    let symbols = [
        ("AAPL", 0.0035),
        ("MSFT", 0.0030),
        ("GOOGL", 0.0040),
        ("NVDA", 0.0065),
        ("TSLA", 0.0070),
        ("BTC-USD", 0.0055),
        ("EUR-USD", 0.0012),
    ];

    let mut interval = tokio::time::interval(Duration::from_millis(250));

    loop {
        interval.tick().await;

        let tick = {
            let mut rng = rand::thread_rng();

            // Choix d'un actif aléatoire à mettre à jour
            let (symbol, base_volatility) = symbols[rng.gen_range(0..symbols.len())];

            // Variation aléatoire centrée proche de 0 avec légère dérive
            let drift: f64 = rng.gen_range(-0.0005..0.0007);
            let noise: f64 = rng.gen_range(-base_volatility..base_volatility);
            let price_delta_pct = drift + noise;

            let volume = match symbol {
                "BTC-USD" => rng.gen_range(1..20),
                "EUR-USD" => rng.gen_range(1_000..50_000),
                _ => rng.gen_range(50..2_500),
            };

            MarketTick {
                symbol: symbol.to_string(),
                price_delta_pct,
                volume,
                timestamp: Local::now(),
            }
        };

        if tx.send(tick).await.is_err() {
            // Le récepteur a été détruit, la tâche peut s'arrêter proprement
            break;
        }
    }
}

/// Gardien RAII garantissant la restauration du terminal à la sortie
struct TerminalGuard {
    terminal: Terminal<CrosstermBackend<io::Stdout>>,
}

impl TerminalGuard {
    fn new() -> io::Result<Self> {
        enable_raw_mode()?;
        let mut stdout = io::stdout();
        execute!(stdout, EnterAlternateScreen)?;
        let backend = CrosstermBackend::new(stdout);
        let terminal = Terminal::new(backend)?;
        Ok(Self { terminal })
    }
}

impl Drop for TerminalGuard {
    fn drop(&mut self) {
        let _ = disable_raw_mode();
        let _ = execute!(self.terminal.backend_mut(), LeaveAlternateScreen);
        let _ = self.terminal.show_cursor();
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut guard = TerminalGuard::new()?;
    let (tx, mut rx) = mpsc::channel::<MarketTick>(100);

    // Démarrage de la tâche asynchrone de marché
    tokio::spawn(market_feed_task(tx));

    let mut app = AppState::new();
    let mut event_stream = EventStream::new();
    let mut render_interval = tokio::time::interval(Duration::from_millis(50));

    while !app.should_quit {
        tokio::select! {
            // Rendu périodique à l'écran
            _ = render_interval.tick() => {
                guard.terminal.draw(|frame| render_ui(frame, &mut app))?;
            }

            // Réception asynchrone des cotations boursières
            Some(tick) = rx.recv() => {
                if !app.is_paused {
                    app.update_stock(tick);
                }
            }

            // Gestion réactive des entrées clavier
            Some(Ok(event)) = event_stream.next() => {
                if let Event::Key(key) = event {
                    if key.kind == KeyEventKind::Press {
                        match key.code {
                            KeyCode::Char('q') | KeyCode::Esc => {
                                app.should_quit = true;
                            }
                            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                app.should_quit = true;
                            }
                            KeyCode::Char(' ') => {
                                app.is_paused = !app.is_paused;
                                let status_msg = if app.is_paused {
                                    "Flux mis EN PAUSE par l'utilisateur."
                                } else {
                                    "Reprise du flux en direct."
                                };
                                app.add_log(format!("[{}] {}", Local::now().format("%H:%M:%S"), status_msg));
                            }
                            KeyCode::Up | KeyCode::Char('k') => {
                                app.previous_stock();
                            }
                            KeyCode::Down | KeyCode::Char('j') => {
                                app.next_stock();
                            }
                            _ => {}
                        }
                    }
                }
            }
        }
    }

    Ok(())
}

/// Dessine l'interface utilisateur complète
fn render_ui(frame: &mut Frame, app: &mut AppState) {
    let size = frame.area();

    // Découpage principal : En-tête, Zone de travail, Pied de page
    let main_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // En-tête
            Constraint::Min(12),   // Contenu principal
            Constraint::Length(3), // Footer raccourcis
        ])
        .split(size);

    render_header(frame, app, main_chunks[0]);
    render_body(frame, app, main_chunks[1]);
    render_footer(frame, app, main_chunks[2]);
}

/// Rend le bandeau d'en-tête supérieur
fn render_header(frame: &mut Frame, app: &AppState, area: Rect) {
    let status_style = if app.is_paused {
        Style::default()
            .fg(Color::Yellow)
            .add_modifier(Modifier::BOLD)
    } else {
        Style::default()
            .fg(Color::Green)
            .add_modifier(Modifier::BOLD)
    };

    let status_text = if app.is_paused {
        "⏸ PAUSE"
    } else {
        "● DIRECT"
    };

    let title = Line::from(vec![
        Span::styled(
            " 📈 TOKIO MARKET TERMINAL ",
            Style::default()
                .fg(Color::Cyan)
                .add_modifier(Modifier::BOLD),
        ),
        Span::raw(" | Statut: "),
        Span::styled(status_text, status_style),
        Span::raw(format!(
            " | Heure: {} | Ticks traités: {}",
            Local::now().format("%H:%M:%S"),
            app.tick_counter
        )),
    ]);

    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::DarkGray));

    let paragraph = Paragraph::new(title)
        .block(block)
        .alignment(Alignment::Left);
    frame.render_widget(paragraph, area);
}

/// Rend le corps principal (tableau des cotations à gauche, graphique + flux à droite)
fn render_body(frame: &mut Frame, app: &mut AppState, area: Rect) {
    let body_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(55), // Tableau des cours
            Constraint::Percentage(45), // Détails & Graphiques
        ])
        .split(area);

    render_table(frame, app, body_chunks[0]);
    render_details(frame, app, body_chunks[1]);
}

/// Rend le tableau des actions avec coloration des variations
fn render_table(frame: &mut Frame, app: &mut AppState, area: Rect) {
    let header_cells = [
        "Ticker", "Nom", "Cours", "Var (€)", "Var (%)", "Min", "Max", "Volume",
    ]
    .iter()
    .map(|&h| {
        Cell::from(h).style(
            Style::default()
                .fg(Color::Cyan)
                .add_modifier(Modifier::BOLD),
        )
    });
    let header = Row::new(header_cells)
        .style(Style::default().bg(Color::Rgb(20, 25, 35)))
        .height(1)
        .bottom_margin(1);

    let rows = app.stocks.iter().map(|stock| {
        let change = stock.change();
        let change_pct = stock.change_pct();

        let (color, icon) = if change > 0.0 {
            (Color::Green, "▲")
        } else if change < 0.0 {
            (Color::Red, "▼")
        } else {
            (Color::Gray, "■")
        };

        let style_val = Style::default().fg(color);

        let cells = vec![
            Cell::from(stock.symbol.as_str()).style(Style::default().add_modifier(Modifier::BOLD)),
            Cell::from(stock.name.as_str()).style(Style::default().fg(Color::White)),
            Cell::from(format!("{:.2}", stock.price))
                .style(Style::default().add_modifier(Modifier::BOLD)),
            Cell::from(format!("{} {:.2}", icon, change)).style(style_val),
            Cell::from(format!("{:+5.2}%", change_pct)).style(style_val),
            Cell::from(format!("{:.2}", stock.low)).style(Style::default().fg(Color::DarkGray)),
            Cell::from(format!("{:.2}", stock.high)).style(Style::default().fg(Color::DarkGray)),
            Cell::from(format!("{}", stock.volume)).style(Style::default().fg(Color::Yellow)),
        ];

        Row::new(cells).height(1)
    });

    let table = Table::new(
        rows,
        [
            Constraint::Length(8),
            Constraint::Length(16),
            Constraint::Length(10),
            Constraint::Length(10),
            Constraint::Length(10),
            Constraint::Length(9),
            Constraint::Length(9),
            Constraint::Min(8),
        ],
    )
    .header(header)
    .block(
        Block::default()
            .borders(Borders::ALL)
            .border_style(Style::default().fg(Color::DarkGray))
            .title(" Watchlist en Direct "),
    )
    .highlight_style(
        Style::default()
            .bg(Color::Rgb(40, 50, 70))
            .add_modifier(Modifier::BOLD),
    )
    .highlight_symbol(">> ");

    frame.render_stateful_widget(table, area, &mut app.table_state);
}

/// Rend la colonne droite : Graphique sparkline/courbe et journal des événements
fn render_details(frame: &mut Frame, app: &AppState, area: Rect) {
    let right_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage(55), // Graphique / Sparkline
            Constraint::Percentage(45), // Flux de marché
        ])
        .split(area);

    let selected = app.selected_stock();

    if let Some(stock) = selected {
        // Préparation des données pour le Chart
        let points: Vec<(f64, f64)> = stock
            .history
            .iter()
            .enumerate()
            .map(|(i, &price)| (i as f64, price))
            .collect();

        let min_p = stock
            .history
            .iter()
            .cloned()
            .fold(f64::INFINITY, f64::min);
        let max_p = stock
            .history
            .iter()
            .cloned()
            .fold(f64::NEG_INFINITY, f64::max);

        let y_margin = if (max_p - min_p).abs() < 0.001 {
            1.0
        } else {
            (max_p - min_p) * 0.1
        };
        let y_min = (min_p - y_margin).max(0.0);
        let y_max = max_p + y_margin;

        let line_color = if stock.change() >= 0.0 {
            Color::Green
        } else {
            Color::Red
        };

        let datasets = vec![Dataset::default()
            .name(format!("{} ({:.2})", stock.symbol, stock.price))
            .marker(symbols::Marker::Braille)
            .graph_type(GraphType::Line)
            .style(Style::default().fg(line_color))
            .data(&points)];

        let x_max = HISTORY_CAPACITY as f64;
        let chart = Chart::new(datasets)
            .block(
                Block::default()
                    .title(format!(" Graphique en direct : {} ", stock.name))
                    .borders(Borders::ALL)
                    .border_style(Style::default().fg(Color::DarkGray)),
            )
            .x_axis(
                Axis::default()
                    .title("Temps (ticks)")
                    .style(Style::default().fg(Color::Gray))
                    .bounds([0.0, x_max]),
            )
            .y_axis(
                Axis::default()
                    .title("Cours")
                    .style(Style::default().fg(Color::Gray))
                    .bounds([y_min, y_max])
                    .labels(vec![
                        Span::raw(format!("{:.2}", y_min)),
                        Span::raw(format!("{:.2}", (y_min + y_max) / 2.0)),
                        Span::raw(format!("{:.2}", y_max)),
                    ]),
            );

        frame.render_widget(chart, right_chunks[0]);
    } else {
        let empty_block = Block::default()
            .title(" Graphique ")
            .borders(Borders::ALL)
            .border_style(Style::default().fg(Color::DarkGray));
        frame.render_widget(empty_block, right_chunks[0]);
    }

    // Journal des événements (Feed Logs)
    let log_lines: Vec<Line> = app
        .logs
        .iter()
        .rev()
        .map(|entry| {
            let color = if entry.contains('▲') {
                Color::Green
            } else if entry.contains('▼') {
                Color::Red
            } else if entry.contains("PAUSE") {
                Color::Yellow
            } else {
                Color::Gray
            };
            Line::from(Span::styled(entry.as_str(), Style::default().fg(color)))
        })
        .collect();

    let logs_widget = Paragraph::new(log_lines)
        .block(
            Block::default()
                .title(" Journal des Flux de Marché ")
                .borders(Borders::ALL)
                .border_style(Style::default().fg(Color::DarkGray)),
        )
