/// Statut d'un téléchargement individuel.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DownloadStatus {
    EnCours,
    EnPause,
    Termine,
    Annule,
    Echoue,
}

/// Message émis par un worker de téléchargement vers le contrôleur principal.
#[derive(Debug)]
pub enum DownloadEvent {
    Progression {
        id: usize,
        octets_actuels: u64,
        vitesse_b_s: f64,
    },
    Termine {
        id: usize,
    },
    Erreur {
        id: usize,
        message: String,
    },
}

/// Modèle de données pour une tâche de téléchargement.
#[derive(Debug, Clone)]
pub struct DownloadTask {
    pub id: usize,
    pub nom: String,
    pub total_octets: u64,
    pub octets_telecharges: u64,
    pub vitesse_b_s: f64,
    pub statut: DownloadStatus,
    pub message_erreur: Option<String>,
    pub date_debut: Instant,
    pub pause_sender: watch::Sender<bool>,
    pub cancel_sender: watch::Sender<bool>,
}

impl DownloadTask {
    pub fn pourcentage(&self) -> u16 {
        if self.total_octets == 0 {
            0
        } else {
            let p = (self.octets_telecharges as f64 / self.total_octets as f64) * 100.0;
            p.clamp(0.0, 100.0) as u16
        }
    }

    pub fn eta_secondes(&self) -> Option<u64> {
        if self.statut != DownloadStatus::EnCours || self.vitesse_b_s <= 1.0 {
            None
        } else {
            let octets_restants = self.total_octets.saturating_sub(self.octets_telecharges);
            Some((octets_restants as f64 / self.vitesse_b_s) as u64)
        }
    }
}

/// Formate un volume d'octets en chaîne lisible (Ko, Mo, Go).
pub fn formater_taille(octets: u64) -> String {
    const KO: f64 = 1024.0;
    const MO: f64 = KO * 1024.0;
    const GO: f64 = MO * 1024.0;

    let v = octets as f64;
    if v >= GO {
        format!("{:.2} Go", v / GO)
    } else if v >= MO {
        format!("{:.1} Mo", v / MO)
    } else if v >= KO {
        format!("{:.1} Ko", v / KO)
    } else {
        format!("{} o", octets)
    }
}

/// Formate une durée d'ETA en mm:ss.
pub fn formater_duree(sec: u64) -> String {
    let minutes = sec / 60;
    let secondes = sec % 60;
    format!("{:02}:{:02}", minutes, secondes)
}

/// État global de l'application TUI.
pub struct AppState {
    pub taches: Vec<DownloadTask>,
    pub index_selectionne: usize,
    pub prochain_id: usize,
    pub tx_events: mpsc::Sender<DownloadEvent>,
}

impl AppState {
    pub fn new(tx_events: mpsc::Sender<DownloadEvent>) -> Self {
        Self {
            taches: Vec::new(),
            index_selectionne: 0,
            prochain_id: 1,
            tx_events,
        }
    }

    pub fn ajouter_tache(&mut self, nom: &str, total_octets: u64) {
        let id = self.prochain_id;
        self.prochain_id += 1;

        let (pause_tx, pause_rx) = watch::channel(false);
        let (cancel_tx, cancel_rx) = watch::channel(false);

        let task = DownloadTask {
            id,
            nom: nom.to_string(),
            total_octets,
            octets_telecharges: 0,
            vitesse_b_s: 0.0,
            statut: DownloadStatus::EnCours,
            message_erreur: None,
            date_debut: Instant::now(),
            pause_sender: pause_tx,
            cancel_sender: cancel_tx,
        };

        self.taches.push(task);

        // Lancer la tâche asynchrone de simulation
        let tx = self.tx_events.clone();
        tokio::spawn(async move {
            simuler_telechargement(id, total_octets, tx, pause_rx, cancel_rx).await;
        });
    }

    pub fn basculer_pause_selection(&mut self) {
        if let Some(tache) = self.taches.get_mut(self.index_selectionne) {
            match tache.statut {
                DownloadStatus::EnCours => {
                    tache.statut = DownloadStatus::EnPause;
                    tache.vitesse_b_s = 0.0;
                    let _ = tache.pause_sender.send(true);
                }
                DownloadStatus::EnPause => {
                    tache.statut = DownloadStatus::EnCours;
                    let _ = tache.pause_sender.send(false);
                }
                _ => {}
            }
        }
    }

    pub fn annuler_selection(&mut self) {
        if let Some(tache) = self.taches.get_mut(self.index_selectionne) {
            if tache.statut == DownloadStatus::EnCours || tache.statut == DownloadStatus::EnPause {
                tache.statut = DownloadStatus::Annule;
                tache.vitesse_b_s = 0.0;
                let _ = tache.cancel_sender.send(true);
            }
        }
    }

    pub fn selectionner_suivant(&mut self) {
        if !self.taches.is_empty() {
            self.index_selectionne = (self.index_selectionne + 1).min(self.taches.len() - 1);
        }
    }

    pub fn selectionner_precedent(&mut self) {
        if self.index_selectionne > 0 {
            self.index_selectionne -= 1;
        }
    }
}

/// Simule un téléchargement de fichier avec débit dynamique, gestion de la pause et annulation.
async fn simuler_telechargement(
    id: usize,
    total_octets: u64,
    tx: mpsc::Sender<DownloadEvent>,
    pause_rx: watch::Receiver<bool>,
    cancel_rx: watch::Receiver<bool>,
) {
    let mut octets_courants = 0u64;

    // Débit moyen simulé entre 1.5 Mo/s et 8 Mo/s
    let base_rate = {
        let mut rng = rand::thread_rng();
        rng.gen_range(1_500_000..8_000_000) as f64
    };
    let chunk_duration = Duration::from_millis(100);

    while octets_courants < total_octets {
        tokio::time::sleep(chunk_duration).await;

        // Vérifier annulation
        if *cancel_rx.borrow() {
            return;
        }

        // Vérifier pause
        if *pause_rx.borrow() {
            let _ = tx
                .send(DownloadEvent::Progression {
                    id,
                    octets_actuels: octets_courants,
                    vitesse_b_s: 0.0,
                })
                .await;

            // Attendre la reprise ou l'annulation
            while *pause_rx.borrow() {
                tokio::time::sleep(Duration::from_millis(150)).await;
                if *cancel_rx.borrow() {
                    return;
                }
            }
        }

        // Variation aléatoire de la vitesse (+/- 30%) - le Rng est limité à un bloc local
        let jitter = {
            let mut rng = rand::thread_rng();
            rng.gen_range(0.70..1.30)
        };
        let vitesse_actuelle = base_rate * jitter;
        let delta_octets = (vitesse_actuelle * 0.10) as u64;

        octets_courants = (octets_courants + delta_octets).min(total_octets);

        if tx
            .send(DownloadEvent::Progression {
                id,
                octets_actuels: octets_courants,
                vitesse_b_s: vitesse_actuelle,
            })
            .await
            .is_err()
        {
            // Canal fermé (application en cours d'arrêt)
            return;
        }
    }

    let _ = tx.send(DownloadEvent::Termine { id }).await;
}

/// Rendu complet de l'interface utilisateur.
fn dessiner_interface(frame: &mut Frame, state: &AppState) {
    let zone = frame.area();

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // En-tête / Résumé global
            Constraint::Min(5),    // Liste des barres de téléchargement
            Constraint::Length(3), // Barre d'aide raccourcis
        ])
        .split(zone);

    // 1. En-tête avec métriques globales
    let vitesse_totale: f64 = state
        .taches
        .iter()
        .filter(|t| t.statut == DownloadStatus::EnCours)
        .map(|t| t.vitesse_b_s)
        .sum();

    let octets_telecharges_totaux: u64 = state.taches.iter().map(|t| t.octets_telecharges).sum();
    let total_attendu: u64 = state.taches.iter().map(|t| t.total_octets).sum();

    let en_cours_count = state
        .taches
        .iter()
        .filter(|t| t.statut == DownloadStatus::EnCours)
        .count();
    let termines_count = state
        .taches
        .iter()
        .filter(|t| t.statut == DownloadStatus::Termine)
        .count();

    let entete_texte = vec![Line::from(vec![
        Span::styled(" Tâches actives : ", Style::default().fg(Color::DarkGray)),
        Span::styled(
            format!("{}/{}", en_cours_count, state.taches.len()),
            Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD),
        ),
        Span::styled(" | Terminés : ", Style::default().fg(Color::DarkGray)),
        Span::styled(
            termines_count.to_string(),
            Style::default().fg(Color::Green).add_modifier(Modifier::BOLD),
        ),
        Span::styled(" | Vitesse globale : ", Style::default().fg(Color::DarkGray)),
        Span::styled(
            format!("{}/s", formater_taille(vitesse_totale as u64)),
            Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD),
        ),
        Span::styled(" | Transféré : ", Style::default().fg(Color::DarkGray)),
        Span::styled(
            format!(
                "{} / {}",
                formater_taille(octets_telecharges_totaux),
                formater_taille(total_attendu)
            ),
            Style::default().fg(Color::White),
        ),
    ])];

    let entete_widget = Paragraph::new(entete_texte).block(
        Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .title(" 🚀 Moniteur de Téléchargements ")
            .title_alignment(Alignment::Center)
            .style(Style::default().fg(Color::Cyan)),
    );
    frame.render_widget(entete_widget, chunks[0]);

    // 2. Liste des barres de progression
    let zone_liste = chunks[1];
    let bloc_liste = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .title(" Téléchargements en cours & terminés ")
        .style(Style::default().fg(Color::White));

    let interieur_liste = bloc_liste.inner(zone_liste);
    frame.render_widget(bloc_liste, zone_liste);

    if state.taches.is_empty() {
        let msg_vide = Paragraph::new("Aucun téléchargement. Appuyez sur [A] pour en démarrer un.")
            .alignment(Alignment::Center)
            .style(Style::default().fg(Color::DarkGray));
        frame.render_widget(msg_vide, interieur_liste);
    } else {
        // Chaque élément prend 3 lignes (titre + jauge + espacement)
        let hauteur_par_element = 3;
        let elements_visibles = (interieur_liste.height as usize / hauteur_par_element).max(1);

        // Défilement dynamique pour conserver l'élément sélectionné visible
        let premier_index = if state.index_selectionne >= elements_visibles {
            state.index_selectionne - elements_visibles + 1
        } else {
            0
        };
        let dernier_index = (premier_index + elements_visibles).min(state.taches.len());

        let contraintes: Vec<Constraint> = (premier_index..dernier_index)
            .map(|_| Constraint::Length(hauteur_par_element as u16))
            .collect();

        let emplacements = Layout::default()
            .direction(Direction::Vertical)
            .constraints(contraintes)
            .split(interieur_liste);

        for (idx_relatif, idx_tache) in (premier_index..dernier_index).enumerate() {
            if idx_relatif >= emplacements.len() {
                break;
            }
            let tache = &state.taches[idx_tache];
            let emplacement = emplacements[idx_relatif];
            let est_selectionne = idx_tache == state.index_selectionne;

            dessiner_tache(frame, tache, emplacement, est_selectionne);
        }
    }

    // 3. Pied de page / Raccourcis
    let raccourcis = Line::from(vec![
        Span::styled(" [A] ", Style::default().fg(Color::Green).add_modifier(Modifier::BOLD)),
        Span::raw("Ajouter  "),
        Span::styled(" [Espace] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw("Pause/Reprise  "),
        Span::styled(" [C] ", Style::default().fg(Color::Red).add_modifier(Modifier::BOLD)),
        Span::raw("Annuler  "),
        Span::styled(" [↑/↓ ou j/k] ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
        Span::raw("Naviguer  "),
        Span::styled(" [Q/Échap] ", Style::default().fg(Color::Magenta).add_modifier(Modifier::BOLD)),
        Span::raw("Quitter"),
    ]);

    let pied_page = Paragraph::new(raccourcis)
        .alignment(Alignment::Center)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .style(Style::default().fg(Color::DarkGray)),
        );
    frame.render_widget(pied_page, chunks[2]);
}

/// Rendu d'une tâche de téléchargement individuelle (titre avec détails + jauge de progression).
fn dessiner_tache(frame: &mut Frame, tache: &DownloadTask, zone: Rect, est_selectionne: bool) {
    let decoupage = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Length(1), Constraint::Length(1)])
        .split(zone);

    let prefixe = if est_selectionne { "▶ " } else { "  " };

    let (statut_texte, couleur_statut) = match tache.statut {
        DownloadStatus::EnCours => ("TÉLÉCHARGEMENT", Color::Cyan),
        DownloadStatus::EnPause => ("EN PAUSE", Color::Yellow),
        DownloadStatus::Termine => ("TERMINÉ", Color::Green),
        DownloadStatus::Annule => ("ANNULÉ", Color::Red),
        DownloadStatus::Echoue => ("ÉCHEC", Color::Red),
    };

    let eta_str = tache
        .eta_secondes()
        .map(|s| format!(" | ETA: {}", formater_duree(s)))
        .unwrap_or_default();

    let vitesse_str = if tache.statut == DownloadStatus::EnCours {
        format!(" | {}/s", formater_taille(tache.vitesse_b_s as u64))
    } else {
        String::new()
    };

    let style_selection = if est_selectionne {
        Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)
    } else {
        Style::default().fg(Color::White)
    };

    let ligne_details = Line::from(vec![
        Span::styled(prefixe, style_selection),
        Span::styled(format!("#{} {}", tache.id, tache.nom), style_selection),
        Span::raw("  "),
        Span::styled(
            format!("[{}]", statut_texte),
            Style::default().fg(couleur_statut).add_modifier(Modifier::BOLD),
        ),
        Span::styled(vitesse_str, Style::default().fg(Color::LightBlue)),
        Span::styled(eta_str, Style::default().fg(Color::LightYellow)),
        Span::styled(
            format!(
                " | {} / {}",
                formater_taille(tache.octets_telecharges),
                formater_taille(tache.total_octets)
            ),
            Style::default().fg(Color::DarkGray),
        ),
    ]);

    frame.render_widget(Paragraph::new(ligne_details), decoupage[0]);

    // Barre de progression (Gauge)
    let gauge_color = match tache.statut {
        DownloadStatus::EnCours => Color::Cyan,
        DownloadStatus::EnPause => Color::Yellow,
        DownloadStatus::Termine => Color::Green,
        DownloadStatus::Annule => Color::DarkGray,
        DownloadStatus::Echoue => Color::Red,
    };

    let pourcentage = tache.pourcentage();
    let label = format!("{}%", pourcentage);

    let gauge = Gauge::default()
        .gauge_style(
            Style::default()
                .fg(gauge_color)
                .bg(Color::Rgb(40, 40, 40))
                .add_modifier(Modifier::BOLD),
        )
        .percent(pourcentage)
        .label(label);

    frame.render_widget(gauge, decoupage[1]);
}

/// Configure et initialise le terminal en mode brut et écran alternatif.
fn initialiser_terminal() -> Result<Terminal<CrosstermBackend<Stdout>>> {
    enable_raw_mode().context("Impossible d'activer le mode brut du terminal")?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen).context("Impossible de passer en écran alternatif")?;
    let backend = CrosstermBackend::new(stdout);
    Terminal::new(backend).context("Impossible d'initialiser le terminal Ratatui")
}

/// Restaure l'état d'origine du terminal proprement.
fn restaurer_terminal(terminal: &mut Terminal<CrosstermBackend<Stdout>>) -> Result<()> {
    disable_raw_mode().context("Impossible de désactiver le mode brut")?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)
        .context("Impossible de quitter l'écran alternatif")?;
    terminal.show_cursor().context("Impossible de restaurer le curseur")?;
    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    // Protection anti-panique : restaure le terminal en cas de panic inattendu
    let standard_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |panic_info| {
        let _ = disable_raw_mode();
        let _ = execute!(stdout(), LeaveAlternateScreen);
        standard_hook(panic_info);
    }));

    let mut terminal = initialiser_terminal()?;

    // Canaux de communication pour les événements de téléchargement
    let (tx_events, mut rx_events) = mpsc::channel::<DownloadEvent>(100);

    let state = Arc::new(Mutex::new(AppState::new(tx_events)));

    // Pré-remplissage avec des téléchargements initiaux variés
    {
        let mut app = state.lock().await;
        app.ajouter_tache("linux-kernel-6.10.tar.xz", 145 * 1024 * 1024);
        app.ajouter_tache("rust-toolchain-nightly.tar.gz", 280 * 1024 * 1024);
        app.ajouter_tache("ubuntu-24.04-desktop-amd64.iso", 4_800 * 1024 * 1024);
        app.ajouter_tache("assets_dataset_open_ai_dump.zip", 750 * 1024 * 1024);
    }

    let mut reader = EventStream::new();
    let mut intervalle_rendu = tokio::time::interval(Duration::from_millis(16)); // ~60 FPS

    let pool_fichiers_noms = [
        "archlinux-x86_64.iso",
        "deepseek-coder-7b.gguf",
        "fedora-workstation-40.iso",
        "game_textures_pack_hd.tar",
        "video_render_final_4k.mp4",
        "backup_database_prod.dump",
        "chromium-source-code.zip",
    ];

    let mut quitter = false;

    while !quitter {
        tokio::select! {
            // Événement d'actualisation de la boucle graphique
            _ = intervalle_rendu.tick() => {
                let app = state.lock().await;
                terminal.draw(|f| dessiner_interface(f, &app))?;
            }

            // Événements émis par les workers asynchrones
            Some(event) = rx_events.recv() => {
                let mut app = state.lock().await;
                match event {
                    DownloadEvent::Progression { id, octets_actuels, vitesse_b_s } => {
                        if let Some(tache) = app.taches.iter_mut().find(|t| t.id == id) {
                            tache.octets_telecharges = octets_actuels;
                            tache.vitesse_b_s = vitesse_b_s;
                        }
                    }
                    DownloadEvent::Termine { id } => {
                        if let Some(tache) = app.taches.iter_mut().find(|t| t.id == id) {
                            tache.statut = DownloadStatus::Termine;
                            tache.octets_telecharges = tache.total_octets;
                            tache.vitesse_b_s = 0.0;
                        }
                    }
                    DownloadEvent::Erreur { id, message } => {
                        if let Some(tache) = app.taches.iter_mut().find(|t| t.id == id) {
                            tache.statut = DownloadStatus::Echoue;
                            tache.message_erreur = Some(message);
                            tache.vitesse_b_s = 0.0;
                        }
                    }
                }
            }

            // Événements d'entrées utilisateur (clavier / redimensionnement)
            Some(maybe_event) = reader.next() => {
                match maybe_event {
                    Ok(Event::Key(key)) if key.kind == KeyEventKind::Press => {
                        let mut app = state.lock().await;
                        match key.code {
                            KeyCode::Char('q') | KeyCode::Esc => {
                                quitter = true;
                            }
                            KeyCode::Down | KeyCode::Char('j') => {
                                app.selectionner_suivant();
                            }
                            KeyCode::Up | KeyCode::Char('k') => {
                                app.selectionner_precedent();
                            }
                            KeyCode::Char(' ') => {
                                app.basculer_pause_selection();
                            }
                            KeyCode::Char('c') => {
                                app.annuler_selection();
                            }
                            KeyCode::Char('a') => {
                                let mut rng = rand::thread_rng();
                                let nom_idx = rng.gen_range(0..pool_fichiers_noms.len());
                                let taille = rng.gen_range(50 * 1024 * 1024..2_000 * 1024 * 1024);
                                app.ajouter_tache(pool_fichiers_noms[nom_idx], taille);
                            }
                            _ => {}
                        }
                    }
                    Ok(Event::Resize(_, _)) => {
                        let app = state.lock().await;
                        terminal.draw(|f| dessiner_interface(f, &app))?;
                    }
                    _ => {}
                }
            }
        }
    }

    // Restauration garantie du terminal avant de quitter
    restaurer_terminal(&mut terminal)?;
    println!("Session TUI fermée avec succès.");

    Ok(())
}

