struct CliArgs {
    /// URL de connexion Redis
    #[arg(short, long, default_value = "redis://127.0.0.1:6379", env = "REDIS_URL")]
    url: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum KeyType {
    String,
    List,
    Set,
    ZSet,
    Hash,
    Stream,
    Other(String),
}

impl KeyType {
    fn from_redis_str(s: &str) -> Self {
        match s.to_lowercase().as_str() {
            "string" => Self::String,
            "list" => Self::List,
            "set" => Self::Set,
            "zset" => Self::ZSet,
            "hash" => Self::Hash,
            "stream" => Self::Stream,
            other => Self::Other(other.to_string()),
        }
    }

    fn as_str(&self) -> &str {
        match self {
            Self::String => "string",
            Self::List => "list",
            Self::Set => "set",
            Self::ZSet => "zset",
            Self::Hash => "hash",
            Self::Stream => "stream",
            Self::Other(s) => s.as_str(),
        }
    }

    fn color(&self) -> Color {
        match self {
            Self::String => Color::Green,
            Self::List => Color::Cyan,
            Self::Set => Color::LightYellow,
            Self::ZSet => Color::Yellow,
            Self::Hash => Color::Magenta,
            Self::Stream => Color::LightRed,
            Self::Other(_) => Color::DarkGray,
        }
    }
}

#[derive(Debug, Clone)]
struct KeySummary {
    name: String,
    key_type: KeyType,
}

#[derive(Debug, Clone)]
enum KeyValueDetail {
    String(String),
    List(Vec<String>),
    Set(Vec<String>),
    ZSet(Vec<(String, f64)>),
    Hash(BTreeMap<String, String>),
    Other(String),
}

#[derive(Debug, Clone)]
struct KeyDetails {
    key_type: KeyType,
    ttl: i64,
    value: KeyValueDetail,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum InputMode {
    Normal,
    Searching,
}

struct App {
    pattern_input: String,
    current_pattern: String,
    keys: Vec<KeySummary>,
    list_state: ListState,
    selected_details: Option<KeyDetails>,
    detail_scroll: u16,
    input_mode: InputMode,
    status_message: String,
    status_is_error: bool,
    should_quit: bool,
}

impl App {
    fn new() -> Self {
        Self {
            pattern_input: "*".to_string(),
            current_pattern: "*".to_string(),
            keys: Vec::new(),
            list_state: ListState::default(),
            selected_details: None,
            detail_scroll: 0,
            input_mode: InputMode::Normal,
            status_message: "Prêt. Appuyez sur '/' pour rechercher, 'r' pour recharger, 'q' pour quitter.".to_string(),
            status_is_error: false,
            should_quit: false,
        }
    }

    fn set_status(&mut self, msg: impl Into<String>, is_error: bool) {
        self.status_message = msg.into();
        self.status_is_error = is_error;
    }

    fn next_key(&mut self) {
        if self.keys.is_empty() {
            self.list_state.select(None);
            return;
        }
        let i = match self.list_state.selected() {
            Some(i) => {
                if i >= self.keys.len().saturating_sub(1) {
                    0
                } else {
                    i + 1
                }
            }
            None => 0,
        };
        self.list_state.select(Some(i));
        self.detail_scroll = 0;
    }

    fn previous_key(&mut self) {
        if self.keys.is_empty() {
            self.list_state.select(None);
            return;
        }
        let i = match self.list_state.selected() {
            Some(i) => {
                if i == 0 {
                    self.keys.len().saturating_sub(1)
                } else {
                    i - 1
                }
            }
            None => 0,
        };
        self.list_state.select(Some(i));
        self.detail_scroll = 0;
    }

    fn select_first(&mut self) {
        if !self.keys.is_empty() {
            self.list_state.select(Some(0));
            self.detail_scroll = 0;
        }
    }

    fn select_last(&mut self) {
        if !self.keys.is_empty() {
            self.list_state.select(Some(self.keys.len() - 1));
            self.detail_scroll = 0;
        }
    }

    fn selected_key_name(&self) -> Option<&str> {
        self.list_state
            .selected()
            .and_then(|idx| self.keys.get(idx))
            .map(|k| k.name.as_str())
    }
}

async fn scan_keys(conn: &mut MultiplexedConnection, pattern: &str) -> Result<Vec<KeySummary>> {
    let mut cursor: u64 = 0;
    let mut raw_keys = Vec::new();

    loop {
        let (next_cursor, keys): (u64, Vec<String>) = redis::cmd("SCAN")
            .arg(cursor)
            .arg("MATCH")
            .arg(pattern)
            .arg("COUNT")
            .arg(100)
            .query_async(conn)
            .await
            .context("Erreur lors de l'exécution de SCAN")?;

        raw_keys.extend(keys);
        cursor = next_cursor;

        if cursor == 0 || raw_keys.len() >= 1000 {
            break;
        }
    }

    raw_keys.sort();
    raw_keys.dedup();

    let mut summaries = Vec::with_capacity(raw_keys.len());
    for key in raw_keys {
        let key_type_str: String = redis::cmd("TYPE")
            .arg(&key)
            .query_async(conn)
            .await
            .unwrap_or_else(|_| "unknown".to_string());

        summaries.push(KeySummary {
            name: key,
            key_type: KeyType::from_redis_str(&key_type_str),
        });
    }

    Ok(summaries)
}

async fn fetch_key_details(
    conn: &mut MultiplexedConnection,
    key: &str,
    key_type: &KeyType,
) -> Result<KeyDetails> {
    let ttl: i64 = redis::cmd("TTL")
        .arg(key)
        .query_async(conn)
        .await
        .unwrap_or(-1);

    let value = match key_type {
        KeyType::String => {
            let val: Option<String> = conn.get(key).await.ok();
            KeyValueDetail::String(val.unwrap_or_else(|| "<valeur introuvable ou binaire>".to_string()))
        }
        KeyType::List => {
            let items: Vec<String> = conn.lrange(key, 0, 99).await.unwrap_or_default();
            KeyValueDetail::List(items)
        }
        KeyType::Set => {
            let mut items: Vec<String> = conn.smembers(key).await.unwrap_or_default();
            items.sort();
            KeyValueDetail::Set(items)
        }
        KeyType::ZSet => {
            let items: Vec<(String, f64)> = redis::cmd("ZRANGE")
                .arg(key)
                .arg(0)
                .arg(99)
                .arg("WITHSCORES")
                .query_async(conn)
                .await
                .unwrap_or_default();
            KeyValueDetail::ZSet(items)
        }
        KeyType::Hash => {
            let map: BTreeMap<String, String> = conn.hgetall(key).await.unwrap_or_default();
            KeyValueDetail::Hash(map)
        }
        KeyType::Stream => KeyValueDetail::Other("Visualisation de flux Stream non détaillée".to_string()),
        KeyType::Other(s) => KeyValueDetail::Other(format!("Type non pris en charge : {s}")),
    };

    Ok(KeyDetails {
        key_type: key_type.clone(),
        ttl,
        value,
    })
}

#[tokio::main]
async fn main() -> Result<()> {
    let args = CliArgs::parse();

    let client = redis::Client::open(args.url.as_str())
        .with_context(|| format!("URL Redis invalide : {}", args.url))?;

    let mut conn = client
        .get_multiplexed_async_connection()
        .await
        .with_context(|| format!("Impossible de se connecter au serveur Redis sur {}", args.url))?;

    enable_raw_mode().context("Activation du mode raw du terminal échouée")?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen).context("Initialisation de l'AlternateScreen échouée")?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend).context("Création du terminal Ratatui échouée")?;

    let mut app = App::new();

    match scan_keys(&mut conn, &app.current_pattern).await {
        Ok(keys) => {
            let count = keys.len();
            app.keys = keys;
            if !app.keys.is_empty() {
                app.list_state.select(Some(0));
            }
            app.set_status(format!("Connecté à {} - {} clé(s) trouvée(s)", args.url, count), false);
        }
        Err(err) => {
            app.set_status(format!("Erreur scan initial: {err}"), true);
        }
    }

    if let Some(first_key) = app.selected_key_name().map(|s| s.to_string()) {
        if let Some(summary) = app.keys.first() {
            if let Ok(details) = fetch_key_details(&mut conn, &first_key, &summary.key_type).await {
                app.selected_details = Some(details);
            }
        }
    }

    let mut previous_selected_key: Option<String> = app.selected_key_name().map(|s| s.to_string());

    while !app.should_quit {
        terminal.draw(|f| ui(f, &mut app))?;

        if event::poll(Duration::from_millis(50))? {
            if let Event::Key(key_event) = event::read()? {
                if key_event.kind == KeyEventKind::Press {
                    match app.input_mode {
                        InputMode::Normal => match key_event.code {
                            KeyCode::Char('q') => app.should_quit = true,
                            KeyCode::Char('c') if key_event.modifiers.contains(KeyModifiers::CONTROL) => {
                                app.should_quit = true;
                            }
                            KeyCode::Char('/') => {
                                app.input_mode = InputMode::Searching;
                            }
                            KeyCode::Char('j') | KeyCode::Down => {
                                app.next_key();
                            }
                            KeyCode::Char('k') | KeyCode::Up => {
                                app.previous_key();
                            }
                            KeyCode::Home => {
                                app.select_first();
                            }
                            KeyCode::End => {
                                app.select_last();
                            }
                            KeyCode::PageDown => {
                                for _ in 0..10 {
                                    app.next_key();
                                }
                            }
                            KeyCode::PageUp => {
                                for _ in 0..10 {
                                    app.previous_key();
                                }
                            }
                            KeyCode::Char('d') => {
                                app.detail_scroll = app.detail_scroll.saturating_add(3);
                            }
                            KeyCode::Char('u') => {
                                app.detail_scroll = app.detail_scroll.saturating_sub(3);
                            }
                            KeyCode::Char('r') => {
                                match scan_keys(&mut conn, &app.current_pattern).await {
                                    Ok(keys) => {
                                        let count = keys.len();
                                        app.keys = keys;
                                        app.list_state.select(if app.keys.is_empty() { None } else { Some(0) });
                                        app.selected_details = None;
                                        app.set_status(format!("Rechargé: {count} clé(s) trouvée(s) pour pattern '{}'", app.current_pattern), false);
                                    }
                                    Err(err) => {
                                        app.set_status(format!("Erreur lors du scan: {err}"), true);
                                    }
                                }
                            }
                            _ => {}
                        },
                        InputMode::Searching => match key_event.code {
                            KeyCode::Enter => {
                                app.current_pattern = if app.pattern_input.trim().is_empty() {
                                    "*".to_string()
                                } else {
                                    app.pattern_input.trim().to_string()
                                };
                                app.input_mode = InputMode::Normal;
                                match scan_keys(&mut conn, &app.current_pattern).await {
                                    Ok(keys) => {
                                        let count = keys.len();
                                        app.keys = keys;
                                        app.list_state.select(if app.keys.is_empty() { None } else { Some(0) });
                                        app.selected_details = None;
                                        app.set_status(format!("Filtre appliqué: '{}' ({} clé(s))", app.current_pattern, count), false);
                                    }
                                    Err(err) => {
                                        app.set_status(format!("Erreur recherche: {err}"), true);
                                    }
                                }
                            }
                            KeyCode::Esc => {
                                app.input_mode = InputMode::Normal;
                                app.pattern_input = app.current_pattern.clone();
                            }
                            KeyCode::Backspace => {
                                app.pattern_input.pop();
                            }
                            KeyCode::Char(c) => {
                                app.pattern_input.push(c);
                            }
                            _ => {}
                        },
                    }
                }
            }
        }

        let current_selected_key = app.selected_key_name().map(|s| s.to_string());
        if current_selected_key != previous_selected_key {
            previous_selected_key = current_selected_key.clone();
            if let Some(idx) = app.list_state.selected() {
                if let Some(summary) = app.keys.get(idx) {
                    match fetch_key_details(&mut conn, &summary.name, &summary.key_type).await {
                        Ok(details) => {
                            app.selected_details = Some(details);
                        }
                        Err(err) => {
                            app.selected_details = None;
                            app.set_status(format!("Erreur chargement détails: {err}"), true);
                        }
                    }
                }
            } else {
                app.selected_details = None;
            }
        }
    }

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    Ok(())
}

fn ui(f: &mut Frame, app: &mut App) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // Barre de recherche
            Constraint::Min(5),    // Contenu principal (liste + détails)
            Constraint::Length(1), // Barre de statut
        ])
        .split(f.area());

    render_search_bar(f, app, chunks[0]);
    render_main_content(f, app, chunks[1]);
    render_status_bar(f, app, chunks[2]);
}

fn render_search_bar(f: &mut Frame, app: &App, area: Rect) {
    let (border_color, title_suffix) = match app.input_mode {
        InputMode::Searching => (Color::Yellow, " [Mode Édition - Entrée pour valider, Échap pour annuler]"),
        InputMode::Normal => (Color::Cyan, " [Appuyez sur '/' pour chercher, 'r' pour rafraîchir]"),
    };

    let title = format!(" Recherche par Pattern Redis (SCAN) {}", title_suffix);

    let search_paragraph = Paragraph::new(app.pattern_input.as_str())
        .style(match app.input_mode {
            InputMode::Searching => Style::default().fg(Color::White).add_modifier(Modifier::BOLD),
            InputMode::Normal => Style::default().fg(Color::Gray),
        })
        .block(
            Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .border_style(Style::default().fg(border_color))
                .title(Span::styled(title, Style::default().fg(border_color).add_modifier(Modifier::BOLD))),
        );

    f.render_widget(search_paragraph, area);

    if app.input_mode == InputMode::Searching {
        f.set_cursor_position((
            area.x + (app.pattern_input.chars().count() as u16).min(area.width.saturating_sub(2)) + 1,
            area.y + 1,
        ));
    }
}

fn render_main_content(f: &mut Frame, app: &mut App, area: Rect) {
    let main_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(40), // Clés
            Constraint::Percentage(60), // Valeur & Métadonnées
        ])
        .split(area);

    render_keys_list(f, app, main_chunks[0]);
    render_key_details(f, app, main_chunks[1]);
}

fn render_keys_list(f: &mut Frame, app: &mut App, area: Rect) {
    let items: Vec<ListItem> = app
        .keys
        .iter()
        .map(|k| {
            let badge = format!(" {:<6} ", k.key_type.as_str());
            let line = Line::from(vec![
                Span::styled(
                    badge,
                    Style::default()
                        .fg(Color::Black)
                        .bg(k.key_type.color())
                        .add_modifier(Modifier::BOLD),
                ),
                Span::raw(" "),
                Span::raw(&k.name),
            ]);
            ListItem::new(line)
        })
        .collect();

    let title = format!(" Clés ({}) ", app.keys.len());
    let list_widget = List::new(items)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .border_style(Style::default().fg(Color::Blue))
                .title(Span::styled(title, Style::default().fg(Color::Blue).add_modifier(Modifier::BOLD))),
        )
        .highlight_style(
            Style::default()
                .bg(Color::DarkGray)
                .fg(Color::White)
                .add_modifier(Modifier::BOLD),
        )
        .highlight_symbol("▶ ");

    f.render_stateful_widget(list_widget, area, &mut app.list_state);
}

fn render_key_details(f: &mut Frame, app: &App, area: Rect) {
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(Style::default().fg(Color::Magenta))
        .title(Span::styled(
            " Visualisation de la Valeur & Métadonnées ",
            Style::default().fg(Color::Magenta).add_modifier(Modifier::BOLD),
        ));

    let Some(selected_name) = app.selected_key_name() else {
        let empty_msg = Paragraph::new("Aucune clé sélectionnée")
            .style(Style::default().fg(Color::DarkGray))
            .alignment(Alignment::Center)
            .block(block);
        f.render_widget(empty_msg, area);
        return;
    };

    let mut lines = Vec::new();

    lines.push(Line::from(vec![
        Span::styled("Clé : ", Style::default().fg(Color::LightCyan).add_modifier(Modifier::BOLD)),
        Span::styled(selected_name, Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
    ]));

    if let Some(details) = &app.selected_details {
        let ttl_text = match details.ttl {
            -1 => "Infini (aucun TTL)".to_string(),
            -2 => "Expirée / Inexistante".to_string(),
            sec => format!("{sec} secondes"),
        };

        lines.push(Line::from(vec![
            Span::styled("Type : ", Style::default().fg(Color::LightCyan).add_modifier(Modifier::BOLD)),
            Span::styled(
                details.key_type.as_str().to_uppercase(),
                Style::default().fg(details.key_type.color()).add_modifier(Modifier::BOLD),
            ),
            Span::raw("  |  "),
            Span::styled("TTL : ", Style::default().fg(Color::LightCyan).add_modifier(Modifier::BOLD)),
            Span::styled(ttl_text, Style::default().fg(Color::Yellow)),
        ]));

        lines.push(Line::from("─".repeat(area.width.saturating_sub(2) as usize)));

        match &details.value {
            KeyValueDetail::String(s) => {
                lines.push(Line::from(Span::styled("Contenu :", Style::default().fg(Color::Gray))));
                for row in s.lines() {
                    lines.push(Line::from(Span::raw(row)));
                }
            }
            KeyValueDetail::List(items) => {
                lines.push(Line::from(Span::styled(
                    format!("Liste ({} éléments affichés) :", items.len()),
                    Style::default().fg(Color::Gray),
                )));
                for (i, item) in items.iter().enumerate() {
                    lines.push(Line::from(vec![
                        Span::styled(format!("[{:>3}] ", i), Style::default().fg(Color::Cyan)),
                        Span::raw(item),
                    ]));
                }
            }
            KeyValueDetail::Set(items) => {
                lines.push(Line::from(Span::styled(
                    format!("Set ({} éléments) :", items.len()),
                    Style::default().fg(Color::Gray),
                )));
                for (i, item) in items.iter().enumerate() {
                    lines.push(Line::from(vec![
                        Span::styled(format!("({:>3}) ", i + 1), Style::default().fg(Color::LightYellow)),
                        Span::raw(item),
                    ]));
                }
            }
            KeyValueDetail::ZSet(items) => {
                lines.push(Line::from(Span::styled(
                    format!("Sorted Set ({} éléments) :", items.len()),
                    Style::default().fg(Color::Gray),
                )));
                for (member, score) in items {
                    lines.push(Line::from(vec![
                        Span::styled(format!("[Score: {:>8.2}] ", score), Style::default().fg(Color::Yellow)),
                        Span::raw(member),
                    ]));
                }
            }
            KeyValueDetail::Hash(map) => {
                lines.push(Line::from(Span::styled(
                    format!("Table de hachage ({} champ(s)) :", map.len()),
                    Style::default().fg(Color::Gray),
                )));
                for (field, val) in map {
                    lines.push(Line::from(vec![
                        Span::styled(format!("{}: ", field), Style::default().fg(Color::LightMagenta).add_modifier(Modifier::BOLD)),
                        Span::raw(val),
                    ]));
                }
            }
            KeyValueDetail::Other(msg) => {
                lines.push(Line::from(Span::styled(msg.as_str(), Style::default().fg(Color::DarkGray))));
            }
        }
    } else {
        lines.push(Line::from(Span::styled("Chargement des détails...", Style::default().fg(Color::Yellow))));
    }

    let total_lines = lines.len() as u16;
    let paragraph = Paragraph::new(lines)
        .block(block)
        .scroll((app.detail_scroll, 0))
        .wrap(Wrap { trim: false });

    f.render_widget(paragraph, area);

    if total_lines > area.height.saturating_sub(2) {
        let mut scrollbar_state = ScrollbarState::default()
            .content_length(total_lines as usize)
            .position(app.detail_scroll as usize);

        let scrollbar = Scrollbar::new(ScrollbarOrientation::VerticalRight)
            .begin_symbol(Some("▲"))
            .end_symbol(Some("▼"));

        f.render_stateful_widget(scrollbar, area, &mut scrollbar_state);
    }
}

fn render_status_bar(f: &mut Frame, app: &App, area: Rect) {
    let status_style = if app.status_is_error {
        Style::default().fg(Color::Red).add_modifier(Modifier::BOLD)
    } else {
        Style::default().fg(Color::DarkGray)
    };

    let controls = " Navigation: [j/k/↑/↓] | Défilement valeur: [d/u] | Pattern: [/] | Actualiser: [r] | Quitter: [q] ";
    let status_line = Line::from(vec![
        Span::styled(&app.status_message, status_style),
        Span::raw(" "),
        Span::styled(controls, Style::default().fg(Color::Cyan)),
    ]);

    let status_paragraph = Paragraph::new(status_line);
    f.render_widget(status_paragraph, area);
}

