/// Informations relatives à une batterie détectée sur le système.
#[derive(Debug, Clone)]
struct BatteryInfo {
    name: String,
    status: String,
    capacity: u16,
    power_watts: Option<f64>,
    voltage_volts: Option<f64>,
    model: Option<String>,
}

/// Informations relatives à un capteur de température Linux (sysfs).
#[derive(Debug, Clone)]
struct ThermalZone {
    name: String,
    zone_type: String,
    temp_celsius: f64,
}

/// État global de l'application.
struct AppState {
    batteries: Vec<BatteryInfo>,
    thermals: Vec<ThermalZone>,
    last_update: Instant,
    update_interval: Duration,
    should_quit: bool,
}

impl AppState {
    fn new() -> Self {
        let mut state = Self {
            batteries: Vec::new(),
            thermals: Vec::new(),
            last_update: Instant::now(),
            update_interval: Duration::from_secs(1),
            should_quit: false,
        };
        state.refresh();
        state
    }

    /// Rafraîchit les données des périphériques depuis sysfs.
    fn refresh(&mut self) {
        self.batteries = scan_batteries();
        self.thermals = scan_thermals();
        self.last_update = Instant::now();
    }
}

/// Lit une ligne de chaîne nettoyée d'un fichier sysfs.
fn read_sysfs_string<P: AsRef<Path>>(path: P) -> Option<String> {
    fs::read_to_string(path)
        .ok()
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
}

/// Lit et parse un entier depuis un fichier sysfs.
fn read_sysfs_i64<P: AsRef<Path>>(path: P) -> Option<i64> {
    read_sysfs_string(path).and_then(|s| s.parse::<i64>().ok())
}

/// Détecte et extrait les informations de toutes les batteries de la machine.
fn scan_batteries() -> Vec<BatteryInfo> {
    let power_path = Path::new("/sys/class/power_supply");
    let mut results = Vec::new();

    let entries = match fs::read_dir(power_path) {
        Ok(iter) => iter,
        Err(_) => return results,
    };

    for entry in entries.flatten() {
        let path = entry.path();
        let p_type = read_sysfs_string(path.join("type")).unwrap_or_default();
        if p_type.to_lowercase() != "battery" {
            continue;
        }

        let name = entry.file_name().to_string_lossy().into_owned();
        let status = read_sysfs_string(path.join("status")).unwrap_or_else(|| "Unknown".to_string());
        let capacity = read_sysfs_i64(path.join("capacity"))
            .map(|c| c.clamp(0, 100) as u16)
            .unwrap_or(0);

        // Puissance consommée instantanée (calculée à partir de power_now ou current_now * voltage_now)
        let power_watts = if let Some(power_uw) = read_sysfs_i64(path.join("power_now")) {
            Some(power_uw as f64 / 1_000_000.0)
        } else if let (Some(current_ua), Some(voltage_uv)) = (
            read_sysfs_i64(path.join("current_now")),
            read_sysfs_i64(path.join("voltage_now")),
        ) {
            Some((current_ua as f64 / 1_000_000.0) * (voltage_uv as f64 / 1_000_000.0))
        } else {
            None
        };

        // Tension de la batterie
        let voltage_volts = read_sysfs_i64(path.join("voltage_now"))
            .map(|uv| uv as f64 / 1_000_000.0);

        let model = read_sysfs_string(path.join("model_name"));

        results.push(BatteryInfo {
            name,
            status,
            capacity,
            power_watts,
            voltage_volts,
            model,
        });
    }

    results.sort_by(|a, b| a.name.cmp(&b.name));
    results
}

/// Parcourt les zones thermiques déclarées sous Linux.
fn scan_thermals() -> Vec<ThermalZone> {
    let thermal_path = Path::new("/sys/class/thermal");
    let mut results = Vec::new();

    let entries = match fs::read_dir(thermal_path) {
        Ok(iter) => iter,
        Err(_) => return results,
    };

    let mut zone_paths: Vec<PathBuf> = Vec::new();
    for entry in entries.flatten() {
        let name = entry.file_name().to_string_lossy().into_owned();
        if name.starts_with("thermal_zone") {
            zone_paths.push(entry.path());
        }
    }

    zone_paths.sort();

    for path in zone_paths {
        let zone_name = path
            .file_name()
            .map(|n| n.to_string_lossy().into_owned())
            .unwrap_or_else(|| "zone".to_string());

        let zone_type = read_sysfs_string(path.join("type"))
            .unwrap_or_else(|| "inconnu".to_string());

        if let Some(millidegrees) = read_sysfs_i64(path.join("temp")) {
            let temp_celsius = millidegrees as f64 / 1000.0;
            // On filtre les valeurs erratiques souvent émises lors de sondes inactives (-273 ou > 200)
            if (-20.0..=150.0).contains(&temp_celsius) {
                results.push(ThermalZone {
                    name: zone_name,
                    zone_type,
                    temp_celsius,
                });
            }
        }
    }

    results
}

