    if batteries.is_empty() {
        let empty_msg = Paragraph::new("Aucune batterie détectée (Alimentation secteur ou conteneur)")
            .style(Style::default().fg(Color::DarkGray))
            .alignment(Alignment::Center)
            .block(block);
        f.render_widget(empty_msg, area);
        return;
    }

    let inner_area = block.inner(area);
    f.render_widget(block, area);

    // Divise l'espace intérieur en fonction du nombre de batteries
    let constraints: Vec<Constraint> = (0..batteries.len())
        .map(|_| Constraint::Ratio(1, batteries.len() as u32))
        .collect();

    let chunks = Layout::default()
        .direction(Direction::Horizontal)
        .margin(1)
        .constraints(constraints)
        .split(inner_area);

    for (i, bat) in batteries.iter().enumerate() {
        if i >= chunks.len() {
            break;
        }

        let bat_layout = Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Length(1), Constraint::Length(2)])
            .split(chunks[i]);

        let mut details = format!("{} [Statut: {}]", bat.name, bat.status);
        if let Some(ref m) = bat.model {
            details.push_str(&format!(" ({})", m));
        }
        if let Some(p) = bat.power_watts {
            details.push_str(&format!(" | {:.2} W", p));
        }
        if let Some(v) = bat.voltage_volts {
            details.push_str(&format!(" | {:.2} V", v));
        }

        let label_p = Paragraph::new(details).style(
            Style::default()
                .fg(Color::White)
                .add_modifier(Modifier::BOLD),
        );
        f.render_widget(label_p, bat_layout[0]);

        let color = battery_color(bat.capacity, &bat.status);
        let gauge = Gauge::default()
            .block(Block::default())
            .gauge_style(Style::default().fg(color).bg(Color::Rgb(40, 40, 40)))
            .percent(bat.capacity)
            .label(format!("{}%", bat.capacity));

        f.render_widget(gauge, bat_layout[1]);
    }
}

/// Rendu sous forme d'histogramme (BarChart) et détails des capteurs thermiques.
fn render_thermals(f: &mut Frame<'_>, area: Rect, thermals: &[ThermalZone]) {
    let block = Block::default()
        .title(" 🌡 Capteurs Thermiques (°C) ")
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(Style::default().fg(Color::Yellow));

    if thermals.is_empty() {
        let msg = Paragraph::new("Aucun capteur thermique accessible dans /sys/class/thermal")
            .style(Style::default().fg(Color::DarkGray))
            .alignment(Alignment::Center)
            .block(block);
        f.render_widget(msg, area);
        return;
    }

    let inner_area = block.inner(area);
    f.render_widget(block, area);

    // Découpage : À gauche le BarChart, à droite le tableau récapitulatif
    let cols = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(60), Constraint::Percentage(40)])
        .margin(1)
        .split(inner_area);

    // Construction des barres pour le BarChart
    let bars: Vec<Bar> = thermals
        .iter()
        .map(|t| {
            let label = if t.zone_type.len() > 10 {
                t.zone_type[..10].to_string()
            } else {
                t.zone_type.clone()
            };

            let color = temp_color(t.temp_celsius);
            let val = t.temp_celsius.max(0.0).round() as u64;

            Bar::default()
                .value(val)
                .label(Line::from(label))
                .style(Style::default().fg(color))
                .value_style(Style::default().fg(Color::White).add_modifier(Modifier::BOLD))
                .text_value(format!("{:.1}°C", t.temp_celsius))
        })
        .collect();

    let bar_group = BarGroup::default().bars(&bars);
    let bar_chart = BarChart::default()
        .block(
            Block::default()
                .title(" Graphique des Températures ")
                .borders(Borders::NONE),
        )
        .data(bar_group)
        .bar_width(8)
        .bar_gap(2)
        .max(105);

    f.render_widget(bar_chart, cols[0]);

    // Liste détaillée à droite
    let mut lines = Vec::new();
    lines.push(Line::from(vec![
        Span::styled("Zone      Type            Température", Style::default().add_modifier(Modifier::UNDERLINED)),
    ]));

    for t in thermals {
        let color = temp_color(t.temp_celsius);
        lines.push(Line::from(vec![
            Span::raw(format!("{:<9} ", t.name)),
            Span::styled(format!("{:<15} ", truncate_str(&t.zone_type, 15)), Style::default().fg(Color::Cyan)),
            Span::styled(format!("{:>5.1} °C", t.temp_celsius), Style::default().fg(color).add_modifier(Modifier::BOLD)),
        ]));
    }

    let detail_p = Paragraph::new(lines).block(
        Block::default()
            .title(" Relevés Détaillés ")
            .borders(Borders::LEFT)
            .border_style(Style::default().fg(Color::DarkGray)),
    );

    f.render_widget(detail_p, cols[1]);
}

/// Tronque une chaîne si elle dépasse la longueur donnée.
fn truncate_str(s: &str, max_len: usize) -> String {
    if s.chars().count() > max_len {
        format!("{}…", s.chars().take(max_len.saturating_sub(1)).collect::<String>())
    } else {
        s.to_string()
    }
}

/// Pied de page avec contrôles et statut d'actualisation.
fn render_footer(f: &mut Frame<'_>, area: Rect, state: &AppState) {
    let elapsed = state.last_update.elapsed().as_secs();
    let footer_text = vec![Line::from(vec![
        Span::styled(" [q / Esc] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw("Quitter   "),
        Span::styled(" [r] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw("Rafraîchir   |   Dernière m.à.j: "),
        Span::styled(
            format!("il y a {}s", elapsed),
            Style::default().fg(Color::Green),
        ),
        Span::raw(" (intervalle auto: 1s)"),
    ])];

    let footer_widget = Paragraph::new(footer_text)
        .alignment(Alignment::Center)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .border_style(Style::default().fg(Color::DarkGray)),
        );

    f.render_widget(footer_widget, area);
}

/// Boucle principale de l'application TUI.
fn run_app<B: Backend>(terminal: &mut Terminal<B>, mut state: AppState) -> Result<()> {
    while !state.should_quit {
        terminal.draw(|f| ui(f, &state))?;

        let timeout = state
            .update_interval
            .saturating_sub(state.last_update.elapsed());

        if event::poll(timeout)? {
            if let Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press {
                    match key.code {
                        KeyCode::Char('q') | KeyCode::Char('Q') | KeyCode::Esc => {
                            state.should_quit = true;
                        }
                        KeyCode::Char('r') | KeyCode::Char('R') => {
                            state.refresh();
                        }
                        _ => {}
                    }
                }
            }
        }

        // Rafraîchissement périodique si l'intervalle est dépassé
        if state.last_update.elapsed() >= state.update_interval {
            state.refresh();
        }
    }

    Ok(())
}

fn main() -> Result<()> {
    // Initialisation du terminal en mode brut
    enable_raw_mode().context("Impossible d'activer le raw mode du terminal")?;
    let mut out = stdout();
    execute!(out, EnterAlternateScreen).context("Impossible de basculer vers l'écran alternatif")?;

    let backend = CrosstermBackend::new(out);
    let mut terminal = Terminal::new(backend).context("Impossible d'initialiser le terminal Ratatui")?;

    let state = AppState::new();
    let res = run_app(&mut terminal, state);

    // Nettoyage et restauration systématique du terminal
    disable_raw_mode().ok();
    execute!(terminal.backend_mut(), LeaveAlternateScreen).ok();
    terminal.show_cursor().ok();

    if let Err(err) = res {
        eprintln!("Erreur lors de l'exécution de l'application : {:#}", err);
    }

    Ok(())
}

