```rust
// src/main.rs
use std::collections::VecDeque;
use std::io::{self, stdout, Stdout, Write};
use std::time::{Duration, Instant};

use crossterm::{
    cursor::{Hide, MoveTo, Show},
    event::{self, Event, KeyCode, KeyEvent, KeyEventKind},
    execute,
    style::{Color, Print, ResetColor, SetBackgroundColor, SetForegroundColor},
    terminal::{
        disable_raw_mode, enable_raw_mode, Clear, ClearType, EnterAlternateScreen,
        LeaveAlternateScreen,
    },
};
use rand::Rng;

const WIDTH: u16 = 20;
const HEIGHT: u16 = 20;

const TICK_RATE: Duration = Duration::from_millis(120);

#[derive(Clone, Copy, PartialEq, Eq)]
enum Direction {
    Up,
    Down,
    Left,
    Right,
}

impl Direction {
    fn is_opposite(self, other: Direction) -> bool {
        matches!(
            (self, other),
            (Direction::Up, Direction::Down)
                | (Direction::Down, Direction::Up)
                | (Direction::Left, Direction::Right)
                | (Direction::Right, Direction::Left)
        )
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
struct Position {
    x: u16,
    y: u16,
}

enum GameState {
    Playing,
    GameOver,
    Quit,
}

struct SnakeGame {
    snake: VecDeque<Position>,
    direction: Direction,
    pending_direction: Direction,
    food: Position,
    score: u32,
    state: GameState,
}

impl SnakeGame {
    fn new() -> Self {
        let mut initial_snake = VecDeque::new();
        initial_snake.push_back(Position {
            x: WIDTH / 2,
            y: HEIGHT / 2,
        });
        initial_snake.push_back(Position {
            x: WIDTH / 2,
            y: HEIGHT / 2 + 1,
        });
        initial_snake.push_back(Position {
            x: WIDTH / 2,
            y: HEIGHT / 2 + 2,
        });

        let mut game = Self {
            snake: initial_snake,
            direction: Direction::Up,
            pending_direction: Direction::Up,
            food: Position { x: 0, y: 0 },
            score: 0,
            state: GameState::Playing,
        };
        game.spawn_food();
        game
    }

    fn reset(&mut self) {
        *self = Self::new();
    }

    fn spawn_food(&mut self) {
        let mut rng = rand::thread_rng();
        let total_cells = (WIDTH * HEIGHT) as usize;
        if self.snake.len() >= total_cells {
            return;
        }

        loop {
            let candidate = Position {
                x: rng.gen_range(0..WIDTH),
                y: rng.gen_range(0..HEIGHT),
            };

            if !self.snake.iter().any(|segment| *segment == candidate) {
                self.food = candidate;
                break;
            }
        }
    }

    fn handle_key(&mut self, key: KeyCode) {
        match self.state {
            GameState::Playing => match key {
                KeyCode::Up | KeyCode::Char('z') | KeyCode::Char('w') => {
                    self.set_direction(Direction::Up);
                }
                KeyCode::Down | KeyCode::Char('s') => {
                    self.set_direction(Direction::Down);
                }
                KeyCode::Left | KeyCode::Char('q') | KeyCode::Char('a') => {
                    self.set_direction(Direction::Left);
                }
                KeyCode::Right | KeyCode::Char('d') => {
                    self.set_direction(Direction::Right);
                }
                KeyCode::Esc => {
                    self.state = GameState::Quit;
                }
                _ => {}
            },
            GameState::GameOver => match key {
                KeyCode::Char('r') | KeyCode::Char('R') => {
                    self.reset();
                }
                KeyCode::Esc | KeyCode::Char('q') | KeyCode::Char('Q') => {
                    self.state = GameState::Quit;
                }
                _ => {}
            },
            GameState::Quit => {}
        }
    }

    fn set_direction(&mut self, new_dir: Direction) {
        if !self.direction.is_opposite(new_dir) {
            self.pending_direction = new_dir;
        }
    }

    fn tick(&mut self) {
        if !matches!(self.state, GameState::Playing) {
            return;
        }

        self.direction = self.pending_direction;
        let head = match self.snake.front() {
            Some(h) => *h,
            None => return,
        };

        let next_head = match self.direction {
            Direction::Up => {
                if head.y == 0 {
                    self.state = GameState::GameOver;
                    return;
                }
                Position {
                    x: head.x,
                    y: head.y - 1,
                }
            }
            Direction::Down => {
                if head.y + 1 >= HEIGHT {
                    self.state = GameState::GameOver;
                    return;
                }
                Position {
                    x: head.x,
                    y: head.y + 1,
                }
            }
            Direction::Left => {
                if head.x == 0 {
                    self.state = GameState::GameOver;
                    return;
                }
                Position {
                    x: head.x - 1,
                    y: head.y,
                }
            }
            Direction::Right => {
                if head.x + 1 >= WIDTH {
                    self.state = GameState::GameOver;
                    return;
                }
                Position {
                    x: head.x + 1,
                    y: head.y,
                }
            }
        };

        let will_grow = next_head == self.food;
        let body_to_check = if will_grow {
            self.snake.iter().copied().collect::<Vec<_>>()
        } else {
            let mut body: Vec<_> = self.snake.iter().copied().collect();
            body.pop();
            body
        };

        if body_to_check.contains(&next_head) {
            self.state = GameState::GameOver;
            return;
        }

        self.snake.push_front(next_head);

        if will_grow {
            self.score += 10;
            self.spawn_food();
        } else {
            self.snake.pop_back();
        }
    }
}

/// Gestionnaire RAII pour restaurer l'état du terminal en toutes circonstances.
struct TerminalSession;

impl TerminalSession {
    fn enter() -> io::Result<Self> {
        enable_raw_mode()?;
        let mut out = stdout();
        execute!(out, EnterAlternateScreen, Hide, Clear(ClearType::All))?;
        Ok(Self)
    }
}

impl Drop for TerminalSession {
    fn drop(&mut self) {
        let mut out = stdout();
        let _ = execute!(out, Show, ResetColor, LeaveAlternateScreen);
        let _ = disable_raw_mode();
    }
}

fn render(stdout: &mut Stdout, game: &SnakeGame) -> io::Result<()> {
    execute!(stdout, MoveTo(0, 0))?;

    let offset_x = 2;
    let offset_y = 1;

    // Titre et Score
    execute!(
        stdout,
        MoveTo(offset_x, offset_y),
        SetForegroundColor(Color::Cyan),
        Print("=== RUST SNAKE CONSOLE (Crossterm) ==="),
        MoveTo(offset_x, offset_y + 1),
        SetForegroundColor(Color::Yellow),
        Print(format!("Score: {}  |  Taille: {}", game.score, game.snake.len())),
        ResetColor
    )?;

    let board_top = offset_y + 3;

    // Bordure supérieure
    execute!(
        stdout,
        MoveTo(offset_x, board_top),
        SetForegroundColor(Color::DarkGrey),
        Print("+"),
        Print("-".repeat((WIDTH * 2) as usize)),
        Print("+"),
        ResetColor
    )?;

    // Cellules de jeu
    for y in 0..HEIGHT {
        execute!(
            stdout,
            MoveTo(offset_x, board_top + 1 + y),
            SetForegroundColor(Color::DarkGrey),
            Print("|"),
            ResetColor
        )?;

        for x in 0..WIDTH {
            let pos = Position { x, y };

            if game.snake.front() == Some(&pos) {
                execute!(
                    stdout,
                    SetForegroundColor(Color::Black),
                    SetBackgroundColor(Color::Green),
                    Print("<>"),
                    ResetColor
                )?;
            } else if game.snake.contains(&pos) {
                execute!(
                    stdout,
                    SetForegroundColor(Color::Black),
                    SetBackgroundColor(Color::DarkGreen),
                    Print("[]"),
                    ResetColor
                )?;
            } else if game.food == pos {
                execute!(
                    stdout,
                    SetForegroundColor(Color::Red),
                    Print("()"),
                    ResetColor
                )?;
            } else {
                execute!(stdout, Print("  "))?;
            }
        }

        execute!(
            stdout,
            SetForegroundColor(Color::DarkGrey),
            Print("|"),
            ResetColor
        )?;
    }

    // Bordure inférieure
    let board_bottom = board_top + 1 + HEIGHT;
    execute!(
        stdout,
        MoveTo(offset_x, board_bottom),
        SetForegroundColor(Color::DarkGrey),
        Print("+"),
        Print("-".repeat((WIDTH * 2) as usize)),
        Print("+"),
        ResetColor
    )?;

    // Instructions et État
    let info_y = board_bottom + 1;
    execute!(
        stdout,
        MoveTo(offset_x, info_y),
        SetForegroundColor(Color::White),
        Print("Contrôles : Flèches / ZQSD / WASD | Quitter : Échap / Q"),
        ResetColor
    )?;

    if matches!(game.state, GameState::GameOver) {
        execute!(
            stdout,
            MoveTo(offset_x, info_y + 1),
            SetForegroundColor(Color::Red),
            Print("GAME OVER ! Appuyez sur [R] pour rejouer ou [Échap/Q] pour quitter."),
            ResetColor
        )?;
    } else {
        execute!(
            stdout,
            MoveTo(offset_x, info_y + 1),
            Clear(ClearType::CurrentLine)
        )?;
    }

    stdout.flush()?;
    Ok(())
}

fn run_game_loop(stdout: &mut Stdout) -> io::Result<()> {
    let mut game = SnakeGame::new();
    let mut last_tick = Instant::now();

    render(stdout, &game)?;

    while !matches!(game.state, GameState::Quit) {
        let timeout = TICK_RATE
            .checked_sub(last_tick.elapsed())
            .unwrap_or(Duration::from_millis(0));

        // Gestion non bloquante des événements clavier avec timeout
        if event::poll(timeout)? {
            if let Event::Key(KeyEvent {
                code,
                kind: KeyEventKind::Press,
                ..
            }) = event::read()?
            {
                game.handle_key(code);
            }
        }

        if last_tick.elapsed() >= TICK_RATE {
            game.tick();
            last_tick = Instant::now();
        }

        render(stdout, &game)?;
    }

    Ok(())
}

fn main() -> io::Result<()> {
    let _session = TerminalSession::enter()?;
    let mut stdout = stdout();

    run_game_loop(&mut stdout)
}

