#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ContainerStatus {
    Running,
    Paused,
    Restarting,
    Exited,
}

impl ContainerStatus {
    fn label(&self) -> &'static str {
        match self {
            ContainerStatus::Running => "Up (Running)",
            ContainerStatus::Paused => "Paused",
            ContainerStatus::Restarting => "Restarting...",
            ContainerStatus::Exited => "Exited (0)",
        }
    }

    fn color(&self) -> Color {
        match self {
            ContainerStatus::Running => Color::Green,
            ContainerStatus::Paused => Color::Yellow,
            ContainerStatus::Restarting => Color::Cyan,
            ContainerStatus::Exited => Color::Red,
        }
    }
}

#[derive(Debug, Clone)]
struct Container {
    id: String,
    name: String,
    image: String,
    ports: String,
    status: ContainerStatus,
    cpu_percent: f64,
    mem_mb: f64,
    mem_limit_mb: f64,
    uptime_secs: u64,
    restart_countdown: u8,
}

impl Container {
    fn new(id: &str, name: &str, image: &str, ports: &str, status: ContainerStatus) -> Self {
        let (cpu, mem, uptime) = if status == ContainerStatus::Running {
            (1.5, 45.0, 3600)
        } else {
            (0.0, 0.0, 0)
        };

        Self {
            id: id.to_string(),
            name: name.to_string(),
            image: image.to_string(),
            ports: ports.to_string(),
            status,
            cpu_percent: cpu,
            mem_mb: mem,
            mem_limit_mb: 512.0,
            uptime_secs: uptime,
            restart_countdown: 0,
        }
    }

    fn update_metrics(&mut self, rng: &mut ThreadRng) {
        match self.status {
            ContainerStatus::Running => {
                self.uptime_secs = self.uptime_secs.saturating_add(1);
                let cpu_delta = rng.gen_range(-1.2..1.3);
                self.cpu_percent = (self.cpu_percent + cpu_delta).clamp(0.2, 98.5);

                let mem_delta = rng.gen_range(-3.0..3.5);
                self.mem_mb = (self.mem_mb + mem_delta).clamp(12.0, self.mem_limit_mb - 5.0);
            }
            ContainerStatus::Restarting => {
                self.cpu_percent = rng.gen_range(2.0..8.0);
                self.mem_mb = 20.0;
                if self.restart_countdown > 0 {
                    self.restart_countdown -= 1;
                } else {
                    self.status = ContainerStatus::Running;
                    self.uptime_secs = 0;
                }
            }
            ContainerStatus::Paused => {
                self.cpu_percent = 0.0;
            }
            ContainerStatus::Exited => {
                self.cpu_percent = 0.0;
                self.mem_mb = 0.0;
            }
        }
    }

    fn formatted_uptime(&self) -> String {
        match self.status {
            ContainerStatus::Exited => "-".to_string(),
            ContainerStatus::Restarting => "restarting".to_string(),
            _ => {
                let secs = self.uptime_secs;
                if secs < 60 {
                    format!("{}s", secs)
                } else if secs < 3600 {
                    format!("{}m {}s", secs / 60, secs % 60)
                } else {
                    format!("{}h {}m", secs / 3600, (secs % 3600) / 60)
                }
            }
        }
    }
}

#[derive(Debug, Clone)]
struct LogEntry {
    timestamp: String,
    message: String,
    level: Color,
}

struct App {
    containers: Vec<Container>,
    table_state: TableState,
    logs: Vec<LogEntry>,
    should_quit: bool,
    rng: ThreadRng,
}

impl App {
    fn new() -> Self {
        let mut table_state = TableState::default();
        table_state.select(Some(0));

        let initial_containers = vec![
            Container::new(
                "d4a8e1b0c123",
                "api-gateway",
                "traefik:v2.10",
                "0.0.0.0:80->80/tcp",
                ContainerStatus::Running,
            ),
            Container::new(
                "3b7f1981ec45",
                "auth-service",
                "auth-svc:latest",
                "8080/tcp",
                ContainerStatus::Running,
            ),
            Container::new(
                "c092a341e89b",
                "postgres-db",
                "postgres:15-alpine",
                "0.0.0.0:5432->5432/tcp",
                ContainerStatus::Running,
            ),
            Container::new(
                "892ef01a7421",
                "redis-cache",
                "redis:7.0-alpine",
                "6379/tcp",
                ContainerStatus::Running,
            ),
            Container::new(
                "1f2a3c4d5e6f",
                "payment-worker",
                "worker-billing:v1.3",
                "-",
                ContainerStatus::Paused,
            ),
            Container::new(
                "77b6c5d4e3f2",
                "legacy-sync",
                "legacy-sync:0.4.1",
                "-",
                ContainerStatus::Exited,
            ),
        ];

        let mut app = Self {
            containers: initial_containers,
            table_state,
            logs: Vec::new(),
            should_quit: false,
            rng: rand::thread_rng(),
        };

        app.add_log("Docker daemon initialisé. Surveillance active.", Color::Cyan);
        app.add_log("Chargement de la topologie initiale des conteneurs terminée.", Color::Green);
        app
    }

    fn add_log(&mut self, msg: impl Into<String>, color: Color) {
        let now = Local::now().format("%H:%M:%S").to_string();
        self.logs.push(LogEntry {
            timestamp: now,
            message: msg.into(),
            level: color,
        });

        if self.logs.len() > 100 {
            self.logs.remove(0);
        }
    }

    fn next_container(&mut self) {
        if self.containers.is_empty() {
            self.table_state.select(None);
            return;
        }

        let i = match self.table_state.selected() {
            Some(i) => {
                if i + 1 >= self.containers.len() {
                    0
                } else {
                    i + 1
                }
            }
            None => 0,
        };
        self.table_state.select(Some(i));
    }

    fn previous_container(&mut self) {
        if self.containers.is_empty() {
            self.table_state.select(None);
            return;
        }

        let i = match self.table_state.selected() {
            Some(i) => {
                if i == 0 {
                    self.containers.len().saturating_sub(1)
                } else {
                    i - 1
                }
            }
            None => 0,
        };
        self.table_state.select(Some(i));
    }

    fn start_selected(&mut self) {
        if let Some(i) = self.table_state.selected() {
            if let Some(c) = self.containers.get_mut(i) {
                if c.status == ContainerStatus::Running {
                    let msg = format!("Le conteneur '{}' est déjà actif.", c.name);
                    self.add_log(msg, Color::Yellow);
                } else {
                    c.status = ContainerStatus::Running;
                    c.uptime_secs = 0;
                    c.cpu_percent = 2.0;
                    c.mem_mb = 35.0;
                    let msg = format!("Conteneur '{}' ({}) démarré.", c.name, &c.id[..8]);
                    self.add_log(msg, Color::Green);
                }
            }
        }
    }

    fn stop_selected(&mut self) {
        if let Some(i) = self.table_state.selected() {
            if let Some(c) = self.containers.get_mut(i) {
                if c.status == ContainerStatus::Exited {
                    let msg = format!("Le conteneur '{}' est déjà arrêté.", c.name);
                    self.add_log(msg, Color::Yellow);
                } else {
                    c.status = ContainerStatus::Exited;
                    c.cpu_percent = 0.0;
                    c.mem_mb = 0.0;
                    let msg = format!("Signal SIGTERM/SIGKILL envoyé à '{}'. Arrêté.", c.name);
                    self.add_log(msg, Color::Red);
                }
            }
        }
    }

    fn restart_selected(&mut self) {
        if let Some(i) = self.table_state.selected() {
            if let Some(c) = self.containers.get_mut(i) {
                c.status = ContainerStatus::Restarting;
                c.restart_countdown = 4;
                c.uptime_secs = 0;
                let msg = format!("Redémarrage en cours pour '{}'...", c.name);
                self.add_log(msg, Color::Cyan);
            }
        }
    }

    fn toggle_pause_selected(&mut self) {
        if let Some(i) = self.table_state.selected() {
            if let Some(c) = self.containers.get_mut(i) {
                match c.status {
                    ContainerStatus::Running => {
                        c.status = ContainerStatus::Paused;
                        c.cpu_percent = 0.0;
                        let msg = format!("Conteneur '{}' suspendu (Paused).", c.name);
                        self.add_log(msg, Color::Yellow);
                    }
                    ContainerStatus::Paused => {
                        c.status = ContainerStatus::Running;
                        let msg = format!("Conteneur '{}' réactivé (Unpaused).", c.name);
                        self.add_log(msg, Color::Green);
                    }
                    _ => {
                        let msg = format!("Impossible de changer la pause pour '{}' (non actif).", c.name);
                        self.add_log(msg, Color::DarkGray);
                    }
                }
            }
        }
    }

    fn spawn_new_container(&mut self) {
        let count = self.containers.len() + 1;
        let hex_chars: String = (0..12)
            .map(|_| {
                let idx = self.rng.gen_range(0..16);
                b"0123456789abcdef"[idx] as char
            })
            .collect();

        let name = format!("service-worker-{}", count);
        let port = format!("0.0.0.0:{}->8080/tcp", 8080 + count);
        let container = Container::new(&hex_chars, &name, "custom/microservice:alpine", &port, ContainerStatus::Running);

        let msg = format!("Nouveau conteneur instancié: {} ({})", name, &hex_chars[..8]);
        self.add_log(msg, Color::LightCyan);
        self.containers.push(container);
    }

    fn remove_selected(&mut self) {
        if let Some(i) = self.table_state.selected() {
            if i < self.containers.len() {
                if self.containers[i].status == ContainerStatus::Running {
                    let msg = format!("Impossible de supprimer '{}': conteneur en cours d'exécution.", self.containers[i].name);
                    self.add_log(msg, Color::Red);
                    return;
                }
                let removed = self.containers.remove(i);
                let msg = format!("Conteneur '{}' ({}) supprimé définitivement.", removed.name, &removed.id[..8]);
                self.add_log(msg, Color::Magenta);

                if self.containers.is_empty() {
                    self.table_state.select(None);
                } else if i >= self.containers.len() {
                    self.table_state.select(Some(self.containers.len() - 1));
                }
            }
        }
    }

    fn tick(&mut self) {
        for c in &mut self.containers {
            c.update_metrics(&mut self.rng);
        }
    }
}

fn main() -> io::Result<()> {
    enable_raw_mode()?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut app = App::new();
    let tick_rate = Duration::from_millis(250);
    let mut last_tick = Instant::now();

    let res = run_loop(&mut terminal, &mut app, tick_rate, &mut last_tick);

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    if let Err(err) = res {
        eprintln!("Erreur d'exécution de l'application TUI: {}", err);
    }

    Ok(())
}

fn run_loop(
    terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    app: &mut App,
    tick_rate: Duration,
    last_tick: &mut Instant,
) -> io::Result<()> {
    loop {
        terminal.draw(|f| ui(f, app))?;

        let timeout = tick_rate
            .checked_sub(last_tick.elapsed())
            .unwrap_or(Duration::from_millis(0));

        if event::poll(timeout)? {
            if let Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press {
                    match key.code {
                        KeyCode::Char('q') | KeyCode::Esc => {
                            app.should_quit = true;
                        }
                        KeyCode::Down | KeyCode::Char('j') => {
                            app.next_container();
                        }
                        KeyCode::Up | KeyCode::Char('k') => {
                            app.previous_container();
                        }
                        KeyCode::Char('s') | KeyCode::Enter => {
                            app.start_selected();
                        }
                        KeyCode::Char('x') => {
                            app.stop_selected();
                        }
                        KeyCode::Char('r') => {
                            app.restart_selected();
                        }
                        KeyCode::Char('p') => {
                            app.toggle_pause_selected();
                        }
                        KeyCode::Char('n') => {
                            app.spawn_new_container();
                        }
                        KeyCode::Char('d') | KeyCode::Delete => {
                            app.remove_selected();
                        }
                        _ => {}
                    }
                }
            }
        }

        if last_tick.elapsed() >= tick_rate {
            app.tick();
            *last_tick = Instant::now();
        }

        if app.should_quit {
            break;
        }
    }

    Ok(())
}

fn ui(f: &mut Frame, app: &mut App) {
    let size = f.area();

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .margin(1)
        .constraints([
            Constraint::Length(3),
            Constraint::Length(4),
            Constraint::Min(8),
            Constraint::Length(8),
            Constraint::Length(3),
        ])
        .split(size);

    render_header(f, chunks[0]);
    render_summary(f, chunks[1], app);
    render_container_table(f, chunks[2], app);
    render_logs_and_details(f, chunks[3], app);
    render_help_footer(f, chunks[4]);
}

fn render_header(f: &mut Frame, area: Rect) {
    let header_text = vec![
        Span::styled(" 🐳 DOCKER MONITORING DASHBOARD (SIMULÉ) ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
        Span::raw(" | "),
        Span::styled("v0.1.0-alpha", Style::default().fg(Color::DarkGray)),
        Span::raw(" | "),
        Span::styled(Local::now().format("%Y-%m-%d %H:%M:%S").to_string(), Style::default().fg(Color::White)),
    ];
    let header = Paragraph::new(Line::from(header_text))
        .block(
            Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .border_style(Style::default().fg(Color::Blue)),
        );
    f.render_widget(header, area);
}

fn render_summary(f: &mut Frame, area: Rect, app: &App) {
    let total = app.containers.len();
    let running = app.containers.iter().filter(|c| c.status == ContainerStatus::Running).count();
    let paused = app.containers.iter().filter(|c| c.status == ContainerStatus::Paused).count();
    let stopped = app.containers.iter().filter(|c| c.status == ContainerStatus::Exited).count();

    let total_cpu: f64 = app.containers.iter().map(|c| c.cpu_percent).sum();
    let total_mem: f64 = app.containers.iter().map(|c| c.mem_mb).sum();
    let max_mem = (app.containers.len() as f64) * 512.0;

    let sub_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(35),
            Constraint::Percentage(32),
            Constraint::Percentage(33),
        ])
        .split(area);

    let stats_text = vec![
        Line::from(vec![
            Span::raw("Total Conteneurs : "),
            Span::styled(format!("{}", total), Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
            Span::raw(" | "),
            Span::styled(format!("{} Actifs", running), Style::default().fg(Color::Green)),
            Span::raw(" | "),
            Span::styled(format!("{} Paused", paused), Style::default().fg(Color::Yellow)),
            Span::raw(" | "),
            Span::styled(format!("{} Arrêtés", stopped), Style::default().fg(Color::Red)),
        ]),
        Line::from(vec![
            Span::raw("Docker Host: "),
            Span::styled("daemon-local (unix:///var/run/docker.sock)", Style::default().fg(Color::DarkGray)),
        ]),
    ];
    let stats_widget = Paragraph::new(stats_text).block(
        Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .title(" Statut Hôte ")
            .border_style(Style::default().fg(Color::Cyan)),
    );
    f.render_widget(stats_widget, sub_chunks[0]);

    let cpu_gauge_percent = ((total_cpu / (total.max(1) as f64 * 100.0)) * 100.0).clamp(0.0, 100.0) as u16;
    let cpu_gauge = Gauge::default()
        .block(
            Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .title(format!(" Charge CPU Globale ({:.1}%) ", total_cpu))
                .border_style(Style::default().fg(Color::Cyan)),
        )
        .gauge_style(Style::default().fg(if cpu_gauge_percent > 70 { Color::Red } else { Color::Green }))
        .percent(cpu_gauge_percent);
    f.render_widget(cpu_gauge, sub_chunks[1]);

    let mem_gauge_percent = if max_mem > 0.0 {
        ((total_mem / max_mem) * 100.0).clamp(0.0, 100.0) as u16
    } else {
        0
    };
    let mem_gauge = Gauge::default()
        .block(
            Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .title(format!(" Mémoire RAM Allouée ({:.0} Mo / {:.0} Mo) ", total_mem, max_mem))
                .border_style(Style::default().fg(Color::Cyan)),
        )
        .gauge_style(Style::default().fg(Color::Blue))
        .percent(mem_gauge_percent);
    f.render_widget(mem_gauge, sub_chunks[2]);
}

fn render_container_table(f: &mut Frame, area: Rect, app: &mut App) {
    let rows: Vec<Row> = app
        .containers
        .iter()
        .map(|c| {
            let status_cell = Cell::from(Span::styled(
                c.status.label(),
                Style::default().fg(c.status.color()).add_modifier(Modifier::BOLD),
            ));
            let cpu_str = if c.status == ContainerStatus::Running {
                format!("{:>5.1} %", c.cpu_percent)
            } else {
                "-".to_string()
            };
            let mem_str = if c.status == ContainerStatus::Running || c.status == ContainerStatus::Paused {
                format!("{:>5.1} / {:.0} Mo", c.mem_mb, c.mem_limit_mb)
            } else {
                "-".to_string()
            };

            Row::new(vec![
                Cell::from(c.id[..8].to_string()),
                Cell::from(c.name.clone()),
                Cell::from(c.image.clone()),
                status_cell,
                Cell::from(c.ports.clone()),
                Cell::from(cpu_str),
                Cell::from(mem_str),
                Cell::from(c.formatted_uptime()),
            ])
        })
        .collect();

    let header_cells = ["ID", "Nom", "Image", "État", "Ports", "CPU", "Mémoire", "Uptime"]
        .iter()
        .map(|h| Cell::from(*h).style(Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
    let header = Row::new(header_cells).height(1).bottom_margin(1);

    let widths = [
        Constraint::Length(10),
        Constraint::Length(18),
        Constraint::Length(24),
        Constraint::Length(16),
        Constraint::Length(24),
        Constraint::Length(10),
        Constraint::Length(18),
        Constraint::Min(10),
    ];

    let table = Table::new(rows, widths)
        .header(header)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .title(" Liste des Conteneurs Docker ")
                .border_style(Style::default().fg(Color::Cyan)),
        )
        .highlight_style(
            Style::default()
                .bg(Color::DarkGray)
                .fg(Color::White)
                .add_modifier(Modifier::BOLD),
        )
        .highlight_symbol("▶ ");

    f.render_stateful_widget(table, area, &mut app.table_state);
}

fn render_logs_and_details(f: &mut Frame, area: Rect, app: &App) {
    let chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(55), Constraint::Percentage(45)])
        .split(area);

    let log_items: Vec<ListItem> = app
        .logs
        .iter()
        .rev()
        .take(15)
        .map(|entry| {
            let line = Line::from(vec![
                Span::styled(format!("[{}] ", entry.timestamp), Style::default().fg(Color::DarkGray)),
                Span::styled(entry.message.clone(), Style::default().fg(entry.level)),
            ]);
            ListItem::new(line)
        })
        .collect();

    let logs_list = List::new(log_items).block(
        Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .title(" Journal d'Événements Docker (Live Logs) ")
            .border_style(Style::default().fg(Color::Cyan)),
    );
    f.render_widget(logs_list, chunks[0]);

    let selected_index = app.table_state.selected();
    let details_paragraph = if let Some(i) = selected_index.and_then(|idx| app.containers.get(idx)) {
        let details_text = vec![
            Line::from(vec![
                Span::styled("Identifiant : ", Style::default().fg(Color::Yellow)),
                Span::raw(&i.id),
            ]),
            Line::from(vec![
                Span::styled("Nom : ", Style::default().fg(Color::Yellow)),
                Span::styled(&i.name, Style::default().add_modifier(Modifier::BOLD)),
                Span::raw(" | "),
                Span::styled("Image : ", Style::default().fg(Color::Yellow)),
                Span::raw(&i.image),
            ]),
            Line::from(vec![
                Span::styled("Statut actuel : ", Style::default().fg(Color::Yellow)),
                Span::styled(i.status.label(), Style::default().fg(i.status.color())),
            ]),
            Line::from(vec![
                Span::styled("Mapping Réseau : ", Style::default().fg(Color::Yellow)),
                Span::raw(&i.ports),
            ]),
            Line::from(vec![
                Span::styled("CPU / Mémoire : ", Style::default().fg(Color::Yellow)),
                Span::raw(format!("{:.2}% - {:.1} Mo / {:.0} Mo", i.cpu_percent, i.mem_mb, i.mem_limit_mb)),
            ]),
        ];
        Paragraph::new(details_text)
    } else {
        Paragraph::new("Aucun conteneur sélectionné.")
    }
    .block(
        Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .title(" Inspection du Conteneur ")
            .border_style(Style::default().fg(Color::Cyan)),
    );
    f.render_widget(details_paragraph, chunks[1]);
}

