// ============================================================================
// COLLECTEUR D'INFORMATIONS SYSTÈME & RÉSEAU
// ============================================================================

pub struct NetworkCollector;

impl NetworkCollector {
    /// Récupère l'ensemble des interfaces réseau actives et inactives de la machine
    pub fn fetch_interfaces() -> Vec<InterfaceData> {
        let raw_interfaces = match NetworkInterface::show() {
            Ok(list) => list,
            Err(_) => Vec::new(),
        };

        let mut results = Vec::new();

        for iface in raw_interfaces {
            let sys_path = format!("/sys/class/net/{}", iface.name);
            let p = Path::new(&sys_path);

            let operstate = fs::read_to_string(p.join("operstate"))
                .map(|s| s.trim().to_uppercase())
                .unwrap_or_else(|_| "UNKNOWN".to_string());

            let mtu = fs::read_to_string(p.join("mtu"))
                .ok()
                .and_then(|s| s.trim().parse::<u32>().ok());

            let speed_mbps = fs::read_to_string(p.join("speed"))
                .ok()
                .and_then(|s| s.trim().parse::<i64>().ok())
                .filter(|&s| s > 0);

            let duplex = fs::read_to_string(p.join("duplex"))
                .ok()
                .map(|s| s.trim().to_string());

            let stats = Self::read_statistics(p);

            let mut ipv4_list = Vec::new();
            let mut ipv6_list = Vec::new();

            for addr in iface.addr {
                match addr {
                    Addr::V4(v4) => {
                        let netmask = v4.netmask;
                        let prefix = netmask.map(Self::netmask_v4_to_prefix).unwrap_or(32);
                        ipv4_list.push(Ipv4Info {
                            ip: v4.ip,
                            netmask,
                            prefix,
                            broadcast: v4.broadcast,
                        });
                    }
                    Addr::V6(v6) => {
                        let prefix = v6.netmask.map(Self::netmask_v6_to_prefix).unwrap_or(128);
                        ipv6_list.push(Ipv6Info { ip: v6.ip, prefix });
                    }
                }
            }

            // Trier les adresses de façon prédictible
            ipv4_list.sort_by_key(|a| a.ip);
            ipv6_list.sort_by_key(|a| a.ip);

            results.push(InterfaceData {
                name: iface.name,
                index: iface.index,
                mac: iface.mac_addr,
                is_loopback: iface.internal,
                operstate,
                mtu,
                speed_mbps,
                duplex,
                ipv4_list,
                ipv6_list,
                stats,
            });
        }

        // Tri par index d'interface
        results.sort_by_key(|i| i.index);
        results
    }

    fn read_statistics(base_path: &Path) -> Option<InterfaceStats> {
        let stats_path = base_path.join("statistics");
        if !stats_path.exists() {
            return None;
        }

        let read_num = |file: &str| -> u64 {
            fs::read_to_string(stats_path.join(file))
                .ok()
                .and_then(|s| s.trim().parse::<u64>().ok())
                .unwrap_or(0)
        };

        Some(InterfaceStats {
            rx_bytes: read_num("rx_bytes"),
            tx_bytes: read_num("tx_bytes"),
            rx_packets: read_num("rx_packets"),
            tx_packets: read_num("tx_packets"),
            rx_errors: read_num("rx_errors"),
            tx_errors: read_num("tx_errors"),
        })
    }

    /// Convertit un masque de sous-réseau IPv4 en préfixe CIDR (/24, /16...)
    pub fn netmask_v4_to_prefix(mask: Ipv4Addr) -> u8 {
        mask.octets().iter().map(|b| b.count_ones() as u8).sum()
    }

    /// Convertit un masque IPv6 en préfixe CIDR
    pub fn netmask_v6_to_prefix(mask: Ipv6Addr) -> u8 {
        mask.octets().iter().map(|b| b.count_ones() as u8).sum()
    }

    /// Analyse `/proc/net/route` pour récupérer la table de routage IPv4
    pub fn fetch_routes_v4() -> Vec<RouteV4> {
        let content = match fs::read_to_string("/proc/net/route") {
            Ok(c) => c,
            Err(_) => return Vec::new(),
        };

        let mut routes = Vec::new();

        for line in content.lines().skip(1) {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() < 8 {
                continue;
            }

            let iface = parts[0].to_string();
            let dest_hex = parts[1];
            let gateway_hex = parts[2];
            let flags_hex = parts[3];
            let metric_str = parts[6];
            let mask_hex = parts[7];

            let dest_ip = Self::parse_hex_ipv4(dest_hex);
            let gateway_ip = Self::parse_hex_ipv4(gateway_hex);
            let mask_ip = Self::parse_hex_ipv4(mask_hex);
            let prefix = Self::netmask_v4_to_prefix(mask_ip);
            let metric = metric_str.parse::<u32>().unwrap_or(0);

            let flags_val = u32::from_str_radix(flags_hex, 16).unwrap_or(0);
            let mut flags_str = String::new();
            if flags_val & 0x0001 != 0 {
                flags_str.push('U'); // Up
            }
            if flags_val & 0x0002 != 0 {
                flags_str.push('G'); // Gateway
            }
            if flags_val & 0x0004 != 0 {
                flags_str.push('H'); // Host
            }
            if flags_val & 0x0008 != 0 {
                flags_str.push('R'); // Reinstate
            }
            if flags_val & 0x0010 != 0 {
                flags_str.push('D'); // Dynamic
            }
            if flags_val & 0x0020 != 0 {
                flags_str.push('M'); // Modified
            }

            let is_default = dest_ip == Ipv4Addr::new(0, 0, 0, 0) && mask_ip == Ipv4Addr::new(0, 0, 0, 0);

            routes.push(RouteV4 {
                iface,
                destination: dest_ip,
                gateway: gateway_ip,
                mask: mask_ip,
                prefix,
                metric,
                flags: flags_str,
                is_default,
            });
        }

        // Tri : routes par défaut en premier, puis par métrique
        routes.sort_by(|a, b| {
            b.is_default
                .cmp(&a.is_default)
                .then_with(|| a.metric.cmp(&b.metric))
                .then_with(|| a.iface.cmp(&b.iface))
        });

        routes
    }

    /// Analyse `/proc/net/ipv6_route` pour récupérer la table de routage IPv6
    pub fn fetch_routes_v6() -> Vec<RouteV6> {
        let content = match fs::read_to_string("/proc/net/ipv6_route") {
            Ok(c) => c,
            Err(_) => return Vec::new(),
        };

        let mut routes = Vec::new();

        for line in content.lines() {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() < 10 {
                continue;
            }

            let dest_hex = parts[0];
            let prefix_hex = parts[1];
            let next_hop_hex = parts[4];
            let metric_hex = parts[5];
            let flags_hex = parts[8];
            let iface = parts[9].to_string();

            let dest_ip = Self::parse_hex_ipv6(dest_hex);
            let prefix = u8::from_str_radix(prefix_hex, 16).unwrap_or(0);
            let next_hop = Self::parse_hex_ipv6(next_hop_hex);
            let metric = u32::from_str_radix(metric_hex, 16).unwrap_or(0);
            let flags_val = u32::from_str_radix(flags_hex, 16).unwrap_or(0);

            let mut flags_str = String::new();
            if flags_val & 0x00000001 != 0 {
                flags_str.push('U');
            }
            if flags_val & 0x00000002 != 0 {
                flags_str.push('G');
            }

            let is_default = dest_ip == Ipv6Addr::UNSPECIFIED && prefix == 0;

            routes.push(RouteV6 {
                iface,
                destination: dest_ip,
                prefix,
                next_hop,
                metric,
                flags: flags_str,
                is_default,
            });
        }

        routes.sort_by(|a, b| {
            b.is_default
                .cmp(&a.is_default)
                .then_with(|| a.metric.cmp(&b.metric))
                .then_with(|| a.iface.cmp(&b.iface))
        });

        routes
    }

    /// Convertit une adresse IPv4 encodée en hexadécimal (little-endian) dans /proc/net/route
    fn parse_hex_ipv4(hex_str: &str) -> Ipv4Addr {
        if let Ok(num) = u32::from_str_radix(hex_str, 16) {
            let b = num.to_le_bytes();
            Ipv4Addr::new(b[0], b[1], b[2], b[3])
        } else {
            Ipv4Addr::new(0, 0, 0, 0)
        }
    }

    /// Convertit une chaîne de 32 caractères hexadécimaux en IPv6
    fn parse_hex_ipv6(hex_str: &str) -> Ipv6Addr {
        if hex_str.len() != 32 {
            return Ipv6Addr::UNSPECIFIED;
        }

        let mut octets = [0u8; 16];
        for i in 0..16 {
            let slice = &hex_str[i * 2..i * 2 + 2];
            octets[i] = u8::from_str_radix(slice, 16).unwrap_or(0);
        }

        Ipv6Addr::from(octets)
    }

    /// Lit les serveurs DNS configurés dans `/etc/resolv.conf`
    pub fn fetch_dns_servers() -> Vec<String> {
        let content = match fs::read_to_string("/etc/resolv.conf") {
            Ok(c) => c,
            Err(_) => return Vec::new(),
        };

        content
            .lines()
            .filter_map(|line| {
                let trimmed = line.trim();
                if trimmed.starts_with("nameserver") {
                    trimmed.split_whitespace().nth(1).map(|s| s.to_string())
                } else {
                    None
                }
            })
            .collect()
    }

    /// Lit le nom d'hôte de la machine locale
    pub fn fetch_hostname() -> String {
        fs::read_to_string("/proc/sys/kernel/hostname")
            .map(|s| s.trim().to_string())
            .unwrap_or_else(|_| "localhost".to_string())
    }
}

// ============================================================================
// ÉTAT DE L'APPLICATION (APP STATE)
// ============================================================================

pub struct App {
    pub current_tab: ActiveTab,
    pub interfaces: Vec<InterfaceData>,
    pub routes_v4: Vec<RouteV4>,
    pub routes_v6: Vec<RouteV6>,
    pub dns_servers: Vec<String>,
    pub hostname: String,
    pub interface_table_state: TableState,
    pub route_table_state: TableState,
    pub route_v6_table_state: TableState,
    pub show_ipv6_routes: bool,
    pub filter_query: String,
    pub is_filtering: bool,
    pub last_refresh: Instant,
    pub notification: Option<(String, Instant)>,
    pub selected_tool_idx: usize,
    pub generated_command: Option<String>,
}

impl App {
    pub fn new() -> Self {
        let mut app = Self {
            current_tab: ActiveTab::Interfaces,
            interfaces: Vec::new(),
            routes_v4: Vec::new(),
            routes_v6: Vec::new(),
            dns_servers: Vec::new(),
            hostname: String::new(),
            interface_table_state: TableState::default(),
            route_table_state: TableState::default(),
            route_v6_table_state: TableState::default(),
            show_ipv6_routes: false,
            filter_query: String::new(),
            is_filtering: false,
            last_refresh: Instant::now(),
            notification: Some(("Bienvenue sur Net-TUI".to_string(), Instant::now())),
            selected_tool_idx: 0,
            generated_command: None,
        };

        app.refresh_all();
        if !app.interfaces.is_empty() {
            app.interface_table_state.select(Some(0));
        }
        if !app.routes_v4.is_empty() {
            app.route_table_state.select(Some(0));
        }
        if !app.routes_v6.is_empty() {
            app.route_v6_table_state.select(Some(0));
        }

        app
    }

    pub fn refresh_all(&mut self) {
        self.interfaces = NetworkCollector::fetch_interfaces();
        self.routes_v4 = NetworkCollector::fetch_routes_v4();
        self.routes_v6 = NetworkCollector::fetch_routes_v6();
        self.dns_servers = NetworkCollector::fetch_dns_servers();
        self.hostname = NetworkCollector::fetch_hostname();
        self.last_refresh = Instant::now();

        // Réajuster les sélections si hors limites
        let iface_count = self.filtered_interfaces().len();
        if iface_count == 0 {
            self.interface_table_state.select(None);
        } else if let Some(sel) = self.interface_table_state.selected() {
            if sel >= iface_count {
                self.interface_table_state.select(Some(iface_count - 1));
            }
        } else {
            self.interface_table_state.select(Some(0));
        }

        let r4_count = self.filtered_routes_v4().len();
        if r4_count == 0 {
            self.route_table_state.select(None);
        } else if let Some(sel) = self.route_table_state.selected() {
            if sel >= r4_count {
                self.route_table_state.select(Some(r4_count - 1));
            }
        }

        self.update_generated_command();
    }

    pub fn set_notification(&mut self, msg: impl Into<String>) {
        self.notification = Some((msg.into(), Instant::now()));
    }

    pub fn filtered_interfaces(&self) -> Vec<&InterfaceData> {
        if self.filter_query.is_empty() {
            self.interfaces.iter().collect()
        } else {
            let q = self.filter_query.to_lowercase();
            self.interfaces
                .iter()
                .filter(|iface| {
                    iface.name.to_lowercase().contains(&q)
                        || iface
                            .mac
                            .as_deref()
                            .map(|m| m.to_lowercase().contains(&q))
                            .unwrap_or(false)
                        || iface
                            .ipv4_list
                            .iter()
                            .any(|ip| ip.ip.to_string().contains(&q))
                        || iface
                            .ipv6_list
                            .iter()
                            .any(|ip| ip.ip.to_string().contains(&q))
                })
                .collect()
        }
    }

    pub fn filtered_routes_v4(&self) -> Vec<&RouteV4> {
        if self.filter_query.is_empty() {
            self.routes_v4.iter().collect()
        } else {
            let q = self.filter_query.to_lowercase();
            self.routes_v4
                .iter()
                .filter(|r| {
                    r.iface.to_lowercase().contains(&q)
                        || r.destination.to_string().contains(&q)
                        || r.gateway.to_string().contains(&q)
                })
                .collect()
        }
    }

    pub fn filtered_routes_v6(&self) -> Vec<&RouteV6> {
        if self.filter_query.is_empty() {
            self.routes_v6.iter().collect()
        } else {
            let q = self.filter_query.to_lowercase();
            self.routes_v6
                .iter()
                .filter(|r| {
                    r.iface.to_lowercase().contains(&q)
                        || r.destination.to_string().contains(&q)
                        || r.next_hop.to_string().contains(&q)
                })
                .collect()
        }
    }

    pub fn selected_interface(&self) -> Option<&InterfaceData> {
        let list = self.filtered_interfaces();
        let idx = self.interface_table_state.selected()?;
        list.get(idx).copied()
    }

    pub fn next_item(&mut self) {
        match self.current_tab {
            ActiveTab::Interfaces => {
                let len = self.filtered_interfaces().len();
                if len > 0 {
                    let next = match self.interface_table_state.selected() {
                        Some(i) => (i + 1) % len,
                        None => 0,
                    };
                    self.interface_table_state.select(Some(next));
                    self.update_generated_command();
                }
            }
            ActiveTab::Routes => {
                if !self.show_ipv6_routes {
                    let len = self.filtered_routes_v4().len();
                    if len > 0 {
                        let next = match self.route_table_state.selected() {
                            Some(i) => (i + 1) % len,
                            None => 0,
                        };
                        self.route_table_state.select(Some(next));
                    }
                } else {
                    let len = self.filtered_routes_v6().len();
                    if len > 0 {
                        let next = match self.route_v6_table_state.selected() {
                            Some(i) => (i + 1) % len,
                            None => 0,
                        };
                        self.route_v6_table_state.select(Some(next));
                    }
                }
            }
            ActiveTab::ConfigTools => {
                self.selected_tool_idx = (self.selected_tool_idx + 1) % 6;
                self.update_generated_command();
            }
            ActiveTab::Help => {}
        }
    }

    pub fn previous_item(&mut self) {
        match self.current_tab {
            ActiveTab::Interfaces => {
                let len = self.filtered_interfaces().len();
                if len > 0 {
                    let prev = match self.interface_table_state.selected() {
                        Some(0) | None => len - 1,
                        Some(i) => i - 1,
                    };
                    self.interface_table_state.select(Some(prev));
                    self.update_generated_command();
                }
            }
            ActiveTab::Routes => {
                if !self.show_ipv6_routes {
                    let len = self.filtered_routes_v4().len();
                    if len > 0 {
                        let prev = match self.route_table_state.selected() {
                            Some(0) | None => len - 1,
                            Some(i) => i - 1,
                        };
                        self.route_table_state.select(Some(prev));
                    }
                } else {
                    let len = self.filtered_routes_v6().len();
                    if len > 0 {
                        let prev = match self.route_v6_table_state.selected() {
                            Some(0) | None => len - 1,
                            Some(i) => i - 1,
                        };
                        self.route_v6_table_state.select(Some(prev));
                    }
                }
            }
            ActiveTab::ConfigTools => {
                self.selected_tool_idx = if self.selected_tool_idx == 0 {
                    5
                } else {
                    self.selected_tool_idx - 1
                };
                self.update_generated_command();
            }
            ActiveTab::Help => {}
        }
    }

    pub fn update_generated_command(&mut self) {
        let iface_name = self
            .selected_interface()
            .map(|i| i.name.as_str())
            .unwrap_or("eth0");

        let cmd = match self.selected_tool_idx {
            0 => format!("sudo ip link set dev {} up", iface_name),
            1 => format!("sudo ip link set dev {} down", iface_name),
            2 => format!("sudo ip addr add 192.168.1.100/24 dev {}", iface_name),
            3 => format!("sudo ip addr flush dev {}", iface_name),
            4 => format!("ip route show dev {}", iface_name),
            5 => format!("ip neigh show dev {}", iface_name),
            _ => format!("ip addr show dev {}", iface_name),
        };

        self.generated_command = Some(cmd);
    }
}

// ============================================================================
// FORMATTEURS UTILITAIRES
// ============================================================================

pub fn format_bytes(bytes: u64) -> String {
    const KB: f64 = 1024.0;
    const MB: f64 = KB * 1024.0;
    const GB: f64 = MB * 1024.0;

    let b = bytes as f64;
    if b >= GB {
        format!("{:.2} Go", b / GB)
    } else if b >= MB {
        format!("{:.2} Mo", b / MB)
    } else if b >= KB {
        format!("{:.2} Ko", b / KB)
    } else {
        format!("{} o", bytes)
    }
}

pub fn format_packets(count: u64) -> String {
    if count >= 1_000_000 {
        format!("{:.2}M pkts", count as f64 / 1_000_000.0)
    } else if count >= 1_000 {
        format!("{:.1}k pkts", count as f64 / 1_000.0)
    } else {
        format!("{} pkts", count)
    }
}

// ============================================================================
// GESTION DU RENDU TUI (INTERFACE UTILISATEUR)
// ============================================================================

pub fn render_ui(frame: &mut Frame, app: &mut App) {
    let size = frame.area();

    // Disposition principale : En-tête, Barre d'onglets, Contenu, Pied de page
    let main_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // En-tête avec métriques globales
            Constraint::Length(3), // Onglets
            Constraint::Min(10),   // Zone de travail active
            Constraint::Length(3), // Barre de notification & raccourcis
        ])
        .split(size);

    render_header(frame, app, main_chunks[0]);
    render_tabs(frame, app, main_chunks[1]);

    match app.current_tab {
        ActiveTab::Interfaces => render_interfaces_tab(frame, app, main_chunks[2]),
        ActiveTab::Routes => render_routes_tab(frame, app, main_chunks[2]),
        ActiveTab::ConfigTools => render_config_tools_tab(frame, app, main_chunks[2]),
        ActiveTab::Help => render_help_tab(frame, main_chunks[2]),
    }

    render_footer(frame, app, main_chunks[3]);

    if app.is_filtering {
        render_filter_popup(frame, app);
    }
}

fn render_header(frame: &mut Frame, app: &App, area: Rect) {
    let total_ifaces = app.interfaces.len();
    let up_ifaces = app
        .interfaces
        .iter()
        .filter(|i| i.operstate == "UP")
        .count();

    let default_v4 = app
        .routes_v4
        .iter()
        .find(|r| r.is_default)
        .map(|r| format!("{} ({})", r.gateway, r.iface))
        .unwrap_or_else(|| "Aucune".to_string());

    let header_text = vec![
        Line::from(vec![
            Span::styled(
                " 🌐 NET-TUI ",
                Style::default()
                    .fg(Color::Black)
                    .bg(Color::Cyan)
                    .add_modifier(Modifier::BOLD),
            ),
            Span::styled(
                format!(" Hôte: "),
                Style::default()
                    .fg(Color::DarkGray)
                    .add_modifier(Modifier::BOLD),
            ),
            Span::styled(
                &app.hostname,
                Style::default()
                    .fg(Color::Yellow)
                    .add_modifier(Modifier::BOLD),
            ),
            Span::raw(" | "),
            Span::styled(
                format!("Interfaces: {} totales ({} UP)", total_ifaces, up_ifaces),
                Style::default().fg(Color::White),
            ),
            Span::raw(" | "),
            Span::styled(
                format!("Passerelle par défaut: {}", default_v4),
                Style::default().fg(Color::Green),
            ),
            Span::raw(" | "),
            Span::styled(
                format!("DNS: {}", app.dns_servers.join(", ")),
                Style::default().fg(Color::LightCyan),
            ),
        ]),
    ];

    let header = Paragraph::new(header_text)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .border_style(Style::default().fg(Color::Cyan)),
        )
        .alignment(Alignment::Left);

    frame.render_widget(header, area);
}

fn render_tabs(frame: &mut Frame, app: &App, area: Rect) {
    let titles = ActiveTab::titles();
    let tab_items: Vec<Line> = titles
        .into_iter()
        .map(|t| Line::from(Span::raw(t)))
        .collect();

    let tabs = Tabs::new(tab_items)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .title(" Navigation (1-4 ou Tab) "),
        )
        .select(app.current_tab as usize)
        .style(Style::default().fg(Color::Gray))
        .highlight_style(
            Style::default()
                .fg(Color::Black)
                .bg(Color::LightGreen)
                .add_modifier(Modifier::BOLD),
        );

    frame.render_widget(tabs, area);
}

fn render_interfaces_tab(frame: &mut Frame, app: &mut App, area: Rect) {
    let chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(45), Constraint::Percentage(55)])
        .split(area);

    let selected_idx = app.interface_table_state.selected();
    let selected_iface = app.selected_interface().cloned();
    let filter_query = app.filter_query.clone();

    let (rows, filtered_count): (Vec<Row>, usize) = {
        let list = app.filtered_interfaces();
        let count = list.len();
        let rows = list
            .iter()
            .enumerate()
            .map(|(idx, iface)| {
                let is_sel = selected_idx == Some(idx);
                let state_style = match iface.operstate.as_str() {
                    "UP" => Style::default().fg(Color::Green).add_modifier(Modifier::BOLD),
                    "DOWN" => Style::default().fg(Color::Red),
                    _ => Style::default().fg(Color::Yellow),
                };

                let primary_ip = iface
                    .ipv4_list
                    .first()
                    .map(|ip| format!("{}/{}", ip.ip, ip.prefix))
                    .unwrap_or_else(|| {
                        iface
                            .ipv6_list
                            .first()
                            .map(|ip| format!("{}/{}", ip.ip, ip.prefix))
                            .unwrap_or_else(|| "-".to_string())
                    });

                let mac = iface.mac.as_deref().unwrap_or("-").to_string();

                let row_style = if is_sel {
                    Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)
                } else {
                    Style::default().fg(Color::White)
                };

                Row::new(vec![
                    Span::styled(format!("#{}", iface.index), row_style),
                    Span::styled(iface.name.clone(), row_style),
                    Span::styled(iface.operstate.clone(), state_style),
                    Span::styled(mac, row_style),
                    Span::styled(primary_ip, row_style),
                ])
            })
            .collect();
        (rows, count)
    };

    let title = if filter_query.is_empty() {
        format!(" Interfaces Réseau ({}) ", filtered_count)
    } else {
        format!(" Interfaces [Filtre: \"{}\"] ({}) ", filter_query, filtered_count)
    };

    let table = Table::new(
        rows,
        [
            Constraint::Length(5),
            Constraint::Length(12),
            Constraint::Length(8),
            Constraint::Length(18),
            Constraint::Min(16),
        ],
    )
    .header(
        Row::new(vec!["Idx", "Nom", "État", "Adresse MAC", "IP Principale"]).style(
            Style::default()
                .fg(Color::Cyan)
                .add_modifier(Modifier::BOLD | Modifier::UNDERLINED),
        ),
    )
    .block(
        Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .title(title),
    )
    .row_highlight_style(
        Style::default()
            .bg(Color::DarkGray)
            .add_modifier(Modifier::BOLD),
    )
    .highlight_symbol("▶ ");

    frame.render_stateful_widget(table, chunks[0], &mut app.interface_table_state);

    // Panneau droit : Détail complet de l'interface sélectionnée
    render_interface_details(frame, selected_iface.as_ref(), chunks[1]);
}

fn render_interface_details(frame: &mut Frame, iface_opt: Option<&InterfaceData>, area: Rect) {
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .title(" Détails & Télémétrie de l'Interface ");

    let iface = match iface_opt {
        Some(i) => i,
        None => {
            let p = Paragraph::new("Aucune interface sélectionnée.")
                .block(block)
                .alignment(Alignment::Center);
            frame.render_widget(p, area);
            return;
        }
    };

    let sub_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(4), // Propriétés matérielles & d'état
            Constraint::Length(6), // Adresses IP (IPv4 & IPv6)
            Constraint::Min(6),    // Statistiques RX/TX
        ])
        .split(block.inner(area));

    frame.render_widget(block, area);

    // 1. Matériel & État
    let state_badge = match iface.operstate.as_str() {
        "UP" => Span::styled(" ● EN LIGNE (UP) ", Style::default().fg(Color::Black).bg(Color::Green)),
        "DOWN" => Span::styled(" ○ HORS LIGNE (DOWN) ", Style::default().fg(Color::White).bg(Color::Red)),
        _ => Span::styled(format!(" ? {} ", iface.operstate), Style::default().fg(Color::Black).bg(Color::Yellow)),
    };

    let speed_str = iface
        .speed_mbps
        .map(|s| format!("{} Mb/s", s))
        .unwrap_or_else(|| "N/A".to_string());
    let duplex_str = iface.duplex.as_deref().unwrap_or("N/A");
    let mtu_str = iface.mtu.map(|m| m.to_string()).unwrap_or_else(|| "N/A".to_string());
    let loopback_str = if iface.is_loopback { "Oui (Loopback)" } else { "Non (Physique/Virtuelle)" };

    let info_lines = vec![
        Line::from(vec![
            Span::styled("Interface : ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
            Span::styled(&iface.name, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
            Span::raw("   "),
            state_badge,
            Span::raw("   "),
            Span::styled(format!("Index: #{}", iface.index), Style::default().fg(Color::Gray)),
        ]),
        Line::from(vec![
            Span::styled("MAC: ", Style::default().fg(Color::Cyan)),
            Span::raw(iface.mac.as_deref().unwrap_or("00:00:00:00:00:00")),
            Span::raw(" | "),
            Span::styled("MTU: ", Style::default().fg(Color::Cyan)),
            Span::raw(mtu_str),
            Span::raw(" | "),
            Span::styled("Débit: ", Style::default().fg(Color::Cyan)),
            Span::raw(speed_str),
            Span::raw(" | "),
            Span::styled("Duplex: ", Style::default().fg(Color::Cyan)),
            Span::raw(duplex_str),
            Span::raw(" | "),
            Span::styled("Bouclage: ", Style::default().fg(Color::Cyan)),
            Span::raw(loopback_str),
        ]),
    ];

    let p_info = Paragraph::new(info_lines);
    frame.render_widget(p_info, sub_chunks[0]);

    // 2. Adresses IP
    let mut ip_lines = vec![Line::from(Span::styled(
        "--- Configuration IP Assignée ---",
        Style::default().fg(Color::DarkGray),
    ))];

    if iface.ipv4_list.is_empty() && iface.ipv6_list.is_empty() {
        ip_lines.push(Line::from(Span::styled(
            "  (Aucune adresse IP assignée à cette interface)",
            Style::default().fg(Color::DarkGray),
        )));
    } else {
        for v4 in &iface.ipv4_list {
            let bcast_str = v4
                .broadcast
                .map(|b| format!(" | Broadcast: {}", b))
                .unwrap_or_default();
            let mask_str = v4
                .netmask
                .map(|m| format!(" | Masque: {}", m))
                .unwrap_or_default();
            ip_lines.push(Line::from(vec![
                Span::styled("  IPv4: ", Style::default().fg(Color::LightGreen).add_modifier(Modifier::BOLD)),
                Span::styled(format!("{}/{}", v4.ip, v4.prefix), Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
                Span::styled(format!("{}{}", mask_str, bcast_str), Style::default().fg(Color::Gray)),
            ]));
        }

        for v6 in &iface.ipv6_list {
            ip_lines.push(Line::from(vec![
                Span::styled("  IPv6: ", Style::default().fg(Color::LightBlue).add_modifier(Modifier::BOLD)),
                Span::styled(format!("{}/{}", v6.ip, v6.prefix), Style::default().fg(Color::White)),
            ]));
        }
    }

    let p_ip = Paragraph::new(ip_lines).wrap(Wrap { trim: true });
    frame.render_widget(p_ip, sub_chunks[1]);

    // 3. Statistiques & Trafic
    if let Some(stats) = &iface.stats {
        let stats_layout = Layout::default()
            .direction(Direction::Vertical)
            .constraints([
                Constraint::Length(1),
                Constraint::Length(1),
                Constraint::Length(1),
                Constraint::Length(1),
                Constraint::Min(1),
            ])
            .split(sub_chunks[2]);

        let title_line = Line::from(Span::styled(
            "--- Métriques de Trafic Réseau (/sys/class/net) ---",
            Style::default().fg(Color::DarkGray),
        ));
        frame.render_widget(Paragraph::new(title_line), stats_layout[0]);

        let rx_line = Line::from(vec![
            Span::styled("  ↓ Réception (RX) : ", Style::default().fg(Color::Green).add_modifier(Modifier::BOLD)),
            Span::styled(format_bytes(stats.rx_bytes), Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
            Span::raw(format!("  ({})", format_packets(stats.rx_packets))),
            Span::styled(
                format!("  | Erreurs: {}", stats.rx_errors),
                if stats.rx_errors > 0 { Style::default().fg(Color::Red) } else { Style::default().fg(Color::DarkGray) },
            ),
        ]);
        frame.render_widget(Paragraph::new(rx_line), stats_layout[1]);

        let tx_line = Line::from(vec![
            Span::styled("  ↑ Émission (TX)  : ", Style::default().fg(Color::Magenta).add_modifier(Modifier::BOLD)),
            Span::styled(format_bytes(stats.tx_bytes), Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
            Span::raw(format!("  ({})", format_packets(stats.tx_packets))),
            Span::styled(
                format!("  | Erreurs: {}", stats.tx_errors),
                if stats.tx_errors > 0 { Style::default().fg(Color::Red) } else { Style::default().fg(Color::DarkGray) },
            ),
        ]);
        frame.render_widget(Paragraph::new(tx_line), stats_layout[2]);

        // Jauges visuelles comparatives RX vs TX
        let total_bytes = stats.rx_bytes + stats.tx_bytes;
        let rx_ratio = if total_bytes > 0 {
            (stats.rx_bytes as f64 / total_bytes as f64).clamp(0.0, 1.0)
        } else {
            0.5
        };

        let gauge = Gauge::default()
            .block(Block::default().title(" Répartition du Volume RX (Vert) vs TX (Magenta) ").borders(Borders::NONE))
            .gauge_style(Style::default().fg(Color::Green).bg(Color::Magenta))
            .ratio(rx_ratio)
            .label(format!("RX: {:.1}% | TX: {:.1}%", rx_ratio * 100.0, (1.0 - rx_ratio) * 100.0));

        frame.render_widget(gauge, stats_layout[3]);
    } else {
        let p_no_stats = Paragraph::new("Statistiques de trafic non disponibles pour cette interface.")
            .style(Style::default().fg(Color::DarkGray));
        frame.render_widget(p_no_stats, sub_chunks[2]);
    }
}

fn render_routes_tab(frame: &mut Frame, app: &mut App, area: Rect) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // Bascule IPv4 / IPv6
            Constraint::Min(8),    // Table de routage
            Constraint::Length(4), // Légende / Détails de la route sélectionnée
        ])
        .split(area);

    // Barre de bascule IPv4 vs IPv6
    let mode_line = Line::from(vec![
        Span::raw("Protocole de routage actif : "),
        if !app.show_ipv6_routes {
            Span::styled(
                " [● IPv4 FIB (/proc/net/route)] ",
                Style::default().fg(Color::Black).bg(Color::LightGreen).add_modifier(Modifier::BOLD),
            )
        } else {
            Span::styled(
                "  ○ IPv4 FIB  ",
                Style::default().fg(Color::Gray),
            )
        },
        Span::raw("   "),
        if app.show_ipv6_routes {
            Span::styled(
                " [● IPv6 FIB (/proc/net/ipv6_route)] ",
                Style::default().fg(Color::Black).bg(Color::LightBlue).add_modifier(Modifier::BOLD),
            )
        } else {
            Span::styled(
                "  ○ IPv6 FIB  ",
                Style::default().fg(Color::Gray),
            )
        },
        Span::styled("   (Appuyez sur [Espace] ou [v] pour basculer)", Style::default().fg(Color::Yellow)),
    ]);

    let p_toggle = Paragraph::new(mode_line).block(
        Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .title(" Sélecteur de Protocole "),
    );
    frame.render_widget(p_toggle, chunks[0]);

    if !app.show_ipv6_routes {
        // Table IPv4
        let selected_idx = app.route_table_state.selected();
        let selected_route = selected_idx.and_then(|i| app.filtered_routes_v4().get(i).copied().cloned());

        let (rows, route_count): (Vec<Row>, usize) = {
            let list = app.filtered_routes_v4();
            let count = list.len();
            let rows = list
                .iter()
                .enumerate()
                .map(|(idx, r)| {
                    let is_sel = selected_idx == Some(idx);
                    let dest_str = if r.is_default {
                        "0.0.0.0 (default)".to_string()
                    } else {
                        format!("{}/{}", r.destination, r.prefix)
                    };

                    let gw_str = if r.gateway == Ipv4Addr::new(0, 0, 0, 0) {
                        "* (Direct)".to_string()
                    } else {
                        r.gateway.to_string()
                    };

                    let badge = if r.is_default { "★ DÉFAUT" } else { "" };

                    let row_style = if is_sel {
                        Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)
                    } else if r.is_default {
                        Style::default().fg(Color::Green)
                    } else {
                        Style::default().fg(Color::White)
                    };

                    Row::new(vec![
                        Span::styled(dest_str, row_style),
