// ============================================================================
// CYCLE DE VIE ET BOUCLE D'ÉVÉNEMENTS PRINCIPALE
// ============================================================================

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Configuration du hook de panique pour restaurer impérativement le terminal
    let default_panic = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        let _ = disable_raw_mode();
        let _ = execute!(stdout(), LeaveAlternateScreen, crossterm::cursor::Show);
        default_panic(info);
    }));

    // Initialisation du terminal en mode brut et écran alternatif
    enable_raw_mode()?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen, crossterm::cursor::Hide)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    // Instance de l'état applicatif
    let mut app = App::new();

    // Boucle d'événements
    let res = run_app(&mut terminal, &mut app);

    // Restauration garantie du terminal
    disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen,
        crossterm::cursor::Show
    )?;
    terminal.show_cursor()?;

    if let Err(err) = res {
        eprintln!("Erreur lors de l'exécution de l'application: {}", err);
    }

    Ok(())
}

fn run_app(
    terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    app: &mut App,
) -> Result<(), io::Error> {
    let tick_rate = Duration::from_millis(250);
    let auto_refresh_interval = Duration::from_secs(3);
    let mut last_tick = Instant::now();

    loop {
        terminal.draw(|f| render_ui(f, app))?;

        let timeout = tick_rate
            .checked_sub(last_tick.elapsed())
            .unwrap_or_else(|| Duration::from_millis(0));

        if event::poll(timeout)? {
            if let Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press {
                    if app.is_filtering {
                        match key.code {
                            KeyCode::Enter | KeyCode::Esc => {
                                app.is_filtering = false;
                            }
                            KeyCode::Backspace => {
                                app.filter_query.pop();
                                app.refresh_all();
                            }
                            KeyCode::Char(c) => {
                                app.filter_query.push(c);
                                app.refresh_all();
                            }
                            _ => {}
                        }
                    } else {
                        match key.code {
                            KeyCode::Char('q') => return Ok(()),
                            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                return Ok(());
                            }
                            KeyCode::Char('c') => {
                                app.filter_query.clear();
                                app.refresh_all();
                                app.set_notification("Filtre effacé");
                            }
                            KeyCode::Char('r') => {
                                app.refresh_all();
                                app.set_notification("Métriques et tables rafraîchies");
                            }
                            KeyCode::Char('/') => {
                                app.is_filtering = true;
                            }
                            KeyCode::Tab => {
                                let next_tab = ((app.current_tab as usize) + 1) % 4;
                                app.current_tab = ActiveTab::from_index(next_tab);
                            }
                            KeyCode::BackTab => {
                                let prev_tab = if (app.current_tab as usize) == 0 {
                                    3
                                } else {
                                    (app.current_tab as usize) - 1
                                };
                                app.current_tab = ActiveTab::from_index(prev_tab);
                            }
                            KeyCode::Char('1') => app.current_tab = ActiveTab::Interfaces,
                            KeyCode::Char('2') => app.current_tab = ActiveTab::Routes,
                            KeyCode::Char('3') => app.current_tab = ActiveTab::ConfigTools,
                            KeyCode::Char('4') => app.current_tab = ActiveTab::Help,
                            KeyCode::Char(' ') | KeyCode::Char('v') => {
                                if app.current_tab == ActiveTab::Routes {
                                    app.show_ipv6_routes = !app.show_ipv6_routes;
                                }
                            }
                            KeyCode::Down | KeyCode::Char('j') => {
                                app.next_item();
                            }
                            KeyCode::Up | KeyCode::Char('k') => {
                                app.previous_item();
                            }
                            _ => {}
                        }
                    }
                }
            }
        }

        if last_tick.elapsed() >= tick_rate {
            last_tick = Instant::now();
        }

        // Rafraîchissement automatique des métriques toutes les 3 secondes
        if app.last_refresh.elapsed() >= auto_refresh_interval && !app.is_filtering {
            app.refresh_all();
        }
    }
}

