    fn test_netmask_v4_to_prefix() {
        assert_eq!(NetworkCollector::netmask_v4_to_prefix(Ipv4Addr::new(255, 255, 255, 0)), 24);
        assert_eq!(NetworkCollector::netmask_v4_to_prefix(Ipv4Addr::new(255, 255, 0, 0)), 16);
        assert_eq!(NetworkCollector::netmask_v4_to_prefix(Ipv4Addr::new(255, 0, 0, 0)), 8);
        assert_eq!(NetworkCollector::netmask_v4_to_prefix(Ipv4Addr::new(255, 255, 255, 255)), 32);
        assert_eq!(NetworkCollector::netmask_v4_to_prefix(Ipv4Addr::new(0, 0, 0, 0)), 0);
    }

    #[test]
    fn test_parse_hex_ipv4() {
        // 0101A8C0 -> 192.168.1.1 en little-endian
        let ip = NetworkCollector::parse_hex_ipv4("0101A8C0");
        assert_eq!(ip, Ipv4Addr::new(192, 168, 1, 1));

        // 00000000 -> 0.0.0.0
        let ip_zero = NetworkCollector::parse_hex_ipv4("00000000");
        assert_eq!(ip_zero, Ipv4Addr::new(0, 0, 0, 0));
    }

    #[test]
    fn test_parse_hex_ipv6() {
        // "00000000000000000000000000000001" -> ::1
        let ip = NetworkCollector::parse_hex_ipv6("00000000000000000000000000000001");
        assert_eq!(ip, Ipv6Addr::new(0, 0, 0, 0, 0, 0, 0, 1));
    }

    #[test]
    fn test_format_bytes() {
        assert_eq!(format_bytes(500), "500 o");
        assert_eq!(format_bytes(1024), "1.00 Ko");
        assert_eq!(format_bytes(1024 * 1024), "1.00 Mo");
        assert_eq!(format_bytes(1024 * 1024 * 1024), "1.00 Go");
    }

    #[test]
    fn test_active_tabs() {
        assert_eq!(ActiveTab::from_index(0), ActiveTab::Interfaces);
        assert_eq!(ActiveTab::from_index(1), ActiveTab::Routes);
        assert_eq!(ActiveTab::from_index(2), ActiveTab::ConfigTools);
        assert_eq!(ActiveTab::from_index(3), ActiveTab::Help);
    }
