    pub rx_bytes: u64,
    pub tx_bytes: u64,
    pub rx_packets: u64,
    pub tx_packets: u64,
    pub rx_errors: u64,
    pub tx_errors: u64,
}

#[derive(Debug, Clone)]
pub struct InterfaceData {
    pub name: String,
    pub index: u32,
    pub mac: Option<String>,
    pub is_loopback: bool,
    pub operstate: String,
    pub mtu: Option<u32>,
    pub speed_mbps: Option<i64>,
    pub duplex: Option<String>,
    pub ipv4_list: Vec<Ipv4Info>,
    pub ipv6_list: Vec<Ipv6Info>,
    pub stats: Option<InterfaceStats>,
}

#[derive(Debug, Clone)]
pub struct RouteV4 {
