    }

    #[test]
    fn test_parse_hex_ipv4() {
        // 0101A8C0 -> 192.168.1.1 en little-endian
        let ip = NetworkCollector::parse_hex_ipv4("0101A8C0");
        assert_eq!(ip, Ipv4Addr::new(192, 168, 1, 1));

        // 00000000 -> 0.0.0.0
        let ip_zero = NetworkCollector::parse_hex_ipv4("00000000");
        assert_eq!(ip_zero, Ipv4Addr::new(0, 0, 0, 0));
    }

    #[test]
    fn test_parse_hex_ipv6() {
        // "00000000000000000000000000000001" -> ::1
        let ip = NetworkCollector::parse_hex_ipv6("00000000000000000000000000000001");
        assert_eq!(ip, Ipv6Addr::new(0, 0, 0, 0, 0, 0, 0, 1));
    }

