```rust
// src/main.rs
use anyhow::{Context, Result};
use chrono::{DateTime, Local, TimeZone};
use crossterm::{
    event::{self, Event, KeyCode, KeyEventKind, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use git2::{Delta, DiffOptions, Oid, Repository, Sort};
use ratatui::{
    backend::{Backend, CrosstermBackend},
    layout::{Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, Clear, List, ListItem, ListState, Paragraph, Wrap},
    Frame, Terminal,
};
use std::{collections::HashMap, io, path::PathBuf};

/// Représentation d'une référence Git (branche, tag, HEAD).
#[derive(Clone, Debug)]
pub enum RefKind {
    Head,
    LocalBranch(String),
    RemoteBranch(String),
    Tag(String),
}

/// Informations d'un fichier modifié dans un commit.
#[derive(Clone, Debug)]
pub struct CommitFileDiff {
    pub path: String,
    pub status: Delta,
}

/// Métadonnées d'un commit Git avec informations de tracé.
#[derive(Clone, Debug)]
pub struct CommitNode {
    pub oid: Oid,
    pub short_id: String,
    pub author_name: String,
    pub author_email: String,
    pub time: DateTime<Local>,
    pub summary: String,
    pub message: String,
    pub parents: Vec<Oid>,
    pub refs: Vec<RefKind>,
    pub graph_prefix: String,
}

/// Contexte de chargement et d'analyse de l'historique Git.
pub struct GitContext {
    repo: Repository,
}

impl GitContext {
    pub fn open(path: Option<PathBuf>) -> Result<Self> {
        let repo = match path {
            Some(p) => Repository::discover(p)?,
            None => Repository::discover(".")?,
        };
        Ok(Self { repo })
    }

    /// Charge tous les commits avec leurs relations et génère les préfixes de graphe.
    pub fn load_commits(&self) -> Result<Vec<CommitNode>> {
        let mut revwalk = self.repo.revwalk().context("Échec de création du revwalk")?;
        revwalk.set_sorting(Sort::TOPOLOGICAL | Sort::TIME)?;

        let mut ref_map: HashMap<Oid, Vec<RefKind>> = HashMap::new();
        self.collect_references(&mut ref_map)?;

        // Pousse toutes les références et HEAD dans le revwalk
        let mut has_revisions = false;
        if let Ok(head) = self.repo.head() {
            if let Some(target) = head.target() {
                let _ = revwalk.push(target);
                has_revisions = true;
            }
        }

        if let Ok(references) = self.repo.references() {
            for reference in references.flatten() {
                if let Some(target) = reference.target() {
                    let _ = revwalk.push(target);
                    has_revisions = true;
                }
            }
        }

        if !has_revisions {
            return Ok(Vec::new());
        }

        let mut raw_nodes = Vec::new();

        for oid_res in revwalk {
            let oid = match oid_res {
                Ok(id) => id,
                Err(_) => continue,
            };

            let commit = match self.repo.find_commit(oid) {
                Ok(c) => c,
                Err(_) => continue,
            };

            let short_id = commit.as_object().short_id()
                .map(|buf| buf.as_str().unwrap_or("???????").to_string())
                .unwrap_or_else(|_| oid.to_string()[..7].to_string());

            let author = commit.author();
            let author_name = author.name().unwrap_or("Inconnu").to_string();
            let author_email = author.email().unwrap_or("").to_string();
            let timestamp = commit.time().seconds();
            let date = Local.timestamp_opt(timestamp, 0)
                .single()
                .unwrap_or_else(|| Local::now());

            let summary = commit.summary().unwrap_or("<Message vide>").to_string();
            let message = commit.message().unwrap_or("").to_string();
            let parents: Vec<Oid> = commit.parent_ids().collect();
            let refs = ref_map.remove(&oid).unwrap_or_default();

            raw_nodes.push(CommitNode {
                oid,
                short_id,
                author_name,
                author_email,
                time: date,
                summary,
                message,
                parents,
                refs,
                graph_prefix: String::new(),
            });
        }

        generate_graph_lines(&mut raw_nodes);

        Ok(raw_nodes)
    }

    /// Récupère la liste des fichiers modifiés pour un commit donné par diff avec ses parents.
    pub fn get_diff_files(&self, oid: Oid) -> Result<Vec<CommitFileDiff>> {
        let commit = self.repo.find_commit(oid)?;
        let tree = commit.tree()?;

        let mut diff_opts = DiffOptions::new();
        let parent_tree = match commit.parent(0) {
            Ok(parent) => Some(parent.tree()?),
            Err(_) => None,
        };

        let diff = self.repo.diff_tree_to_tree(
            parent_tree.as_ref(),
            Some(&tree),
            Some(&mut diff_opts),
        )?;

        let mut files = Vec::new();
        for delta in diff.deltas() {
            let path = delta.new_file().path()
                .or_else(|| delta.old_file().path())
                .map(|p| p.to_string_lossy().to_string())
                .unwrap_or_else(|| "fichier inconnu".to_string());

            files.push(CommitFileDiff {
                path,
                status: delta.status(),
            });
        }

        Ok(files)
    }

    fn collect_references(&self, ref_map: &mut HashMap<Oid, Vec<RefKind>>) -> Result<()> {
        let head_target = self.repo.head().ok().and_then(|h| h.target());

        if let Ok(references) = self.repo.references() {
            for reference in references.flatten() {
                if let Some(target) = reference.target() {
                    let name = reference.shorthand().unwrap_or("").to_string();
                    if reference.is_tag() {
                        ref_map.entry(target).or_default().push(RefKind::Tag(name));
                    } else if reference.is_remote() {
                        ref_map.entry(target).or_default().push(RefKind::RemoteBranch(name));
                    } else if reference.is_branch() {
                        ref_map.entry(target).or_default().push(RefKind::LocalBranch(name));
                    }
                }
            }
        }

        if let Some(head_oid) = head_target {
            ref_map.entry(head_oid).or_default().insert(0, RefKind::Head);
        }

        Ok(())
    }
}

/// Calcule un tracé ASCII élégant pour représenter l'arbre des branches Git.
fn generate_graph_lines(commits: &mut [CommitNode]) {
    let mut columns: Vec<Oid> = Vec::new();

    for commit in commits.iter_mut() {
        let mut col_index = columns.iter().position(|&id| id == commit.oid);

        if col_index.is_none() {
            columns.push(commit.oid);
            col_index = Some(columns.len() - 1);
        }

        let curr_col = col_index.unwrap_or(0);

        // Construit le préfixe visuel pour la ligne actuelle
        let mut prefix = String::new();
        for i in 0..columns.len() {
            if i == curr_col {
                prefix.push_str("● ");
            } else {
                prefix.push_str("│ ");
            }
        }

        // Met à jour les colonnes pour les commits suivants
        if commit.parents.is_empty() {
            columns.remove(curr_col);
        } else {
            columns[curr_col] = commit.parents[0];
            for parent in &commit.parents[1..] {
                if !columns.contains(parent) {
                    columns.insert(curr_col + 1, *parent);
                }
            }
        }

        commit.graph_prefix = prefix;
    }
}

/// Mode de focus utilisateur dans l'interface.
#[derive(PartialEq, Eq)]
pub enum FocusedPanel {
    CommitList,
    Details,
}

/// État principal de l'application TUI.
pub struct App {
    commits: Vec<CommitNode>,
    filtered_indices: Vec<usize>,
    list_state: ListState,
    focused_panel: FocusedPanel,
    diff_cache: HashMap<Oid, Vec<CommitFileDiff>>,
    search_query: String,
    is_searching: bool,
    details_scroll: u16,
    should_quit: bool,
}

impl App {
    pub fn new(commits: Vec<CommitNode>) -> Self {
        let total = commits.len();
        let mut list_state = ListState::default();
        if total > 0 {
            list_state.select(Some(0));
        }

        let filtered_indices = (0..total).collect();

        Self {
            commits,
            filtered_indices,
            list_state,
            focused_panel: FocusedPanel::CommitList,
            diff_cache: HashMap::new(),
            search_query: String::new(),
            is_searching: false,
            details_scroll: 0,
            should_quit: false,
        }
    }

    pub fn selected_commit(&self) -> Option<&CommitNode> {
        let sel = self.list_state.selected()?;
        let original_index = *self.filtered_indices.get(sel)?;
        self.commits.get(original_index)
    }

    pub fn apply_filter(&mut self) {
        let query = self.search_query.to_lowercase();
        if query.is_empty() {
            self.filtered_indices = (0..self.commits.len()).collect();
        } else {
            self.filtered_indices = self.commits
                .iter()
                .enumerate()
                .filter(|(_, c)| {
                    c.summary.to_lowercase().contains(&query)
                        || c.short_id.to_lowercase().contains(&query)
                        || c.author_name.to_lowercase().contains(&query)
                })
                .map(|(i, _)| i)
                .collect();
        }

        if self.filtered_indices.is_empty() {
            self.list_state.select(None);
        } else {
            self.list_state.select(Some(0));
        }
        self.details_scroll = 0;
    }

    pub fn next_commit(&mut self) {
        if self.filtered_indices.is_empty() {
            return;
        }
        let current = self.list_state.selected().unwrap_or(0);
        let next = (current + 1).min(self.filtered_indices.len().saturating_sub(1));
        self.list_state.select(Some(next));
        self.details_scroll = 0;
    }

    pub fn previous_commit(&mut self) {
        if self.filtered_indices.is_empty() {
            return;
        }
        let current = self.list_state.selected().unwrap_or(0);
        let prev = current.saturating_sub(1);
        self.list_state.select(Some(prev));
        self.details_scroll = 0;
    }

    pub fn jump_to_start(&mut self) {
        if !self.filtered_indices.is_empty() {
            self.list_state.select(Some(0));
            self.details_scroll = 0;
        }
    }

    pub fn jump_to_end(&mut self) {
        if !self.filtered_indices.is_empty() {
            self.list_state.select(Some(self.filtered_indices.len() - 1));
            self.details_scroll = 0;
        }
    }

    pub fn scroll_details_down(&mut self) {
        self.details_scroll = self.details_scroll.saturating_add(2);
    }

    pub fn scroll_details_up(&mut self) {
        self.details_scroll = self.details_scroll.saturating_sub(2);
    }

    pub fn toggle_focus(&mut self) {
        self.focused_panel = match self.focused_panel {
            FocusedPanel::CommitList => FocusedPanel::Details,
            FocusedPanel::Details => FocusedPanel::CommitList,
        };
    }
}

/// Dessine l'interface utilisateur complète avec Ratatui.
fn render_ui(frame: &mut Frame, app: &mut App, git_ctx: &GitContext) {
    let size = frame.area();

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3),      // En-tête / Barre de titre
            Constraint::Min(8),         // Zone principale (Arbre + Détails)
            Constraint::Length(1),      // Barre d'état / Raccourcis
        ])
        .split(size);

    // 1. Barre de titre & recherche
    render_header(frame, chunks[0], app);

    // 2. Zone principale scindée horizontalement
    let main_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(58), // Volet gauche: Arbre des commits
            Constraint::Percentage(42), // Volet droit: Détails et modifications
        ])
        .split(chunks[1]);

    render_commit_tree(frame, main_chunks[0], app);
    render_commit_details(frame, main_chunks[1], app, git_ctx);

    // 3. Barre de statut
    render_footer(frame, chunks[2], app);

    // Fenêtre popup si la recherche est active
    if app.is_searching {
        render_search_modal(frame, app);
    }
}

fn render_header(frame: &mut Frame, area: Rect, app: &App) {
    let filter_text = if app.search_query.is_empty() {
        "aucun".to_string()
    } else {
        format!("\"{}\" ({} résultats)", app.search_query, app.filtered_indices.len())
    };

    let title = Line::from(vec![
        Span::styled(" Git Tree TUI ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
        Span::raw("│ Total commits: "),
        Span::styled(format!("{}", app.commits.len()), Style::default().fg(Color::Yellow)),
        Span::raw(" │ Filtre actif: "),
        Span::styled(filter_text, Style::default().fg(Color::Green)),
    ]);

    let block = Block::default()
        .borders(Borders::ALL)
        .title(title)
        .style(Style::default().bg(Color::Reset));

    frame.render_widget(block, area);
}

fn render_commit_tree(frame: &mut Frame, area: Rect, app: &mut App) {
    let is_focused = app.focused_panel == FocusedPanel::CommitList;
    let border_color = if is_focused { Color::Cyan } else { Color::DarkGray };

    let items: Vec<ListItem> = app.filtered_indices
        .iter()
        .filter_map(|&idx| app.commits.get(idx))
        .map(|node| {
            let mut spans = Vec::new();

            // Tracé du graphe de branches
            spans.push(Span::styled(&node.graph_prefix, Style::default().fg(Color::Magenta).add_modifier(Modifier::BOLD)));

            // Hash court
            spans.push(Span::styled(format!("{} ", node.short_id), Style::default().fg(Color::Yellow)));

            // Badges de références (branches, tags, HEAD)
            for r in &node.refs {
                match r {
                    RefKind::Head => {
                        spans.push(Span::styled("[HEAD] ", Style::default().fg(Color::Black).bg(Color::Cyan).add_modifier(Modifier::BOLD)));
                    }
                    RefKind::LocalBranch(name) => {
                        spans.push(Span::styled(format!("[{}] ", name), Style::default().fg(Color::Green).add_modifier(Modifier::BOLD)));
                    }
                    RefKind::RemoteBranch(name) => {
                        spans.push(Span::styled(format!("[{}] ", name), Style::default().fg(Color::Red)));
                    }
                    RefKind::Tag(name) => {
                        spans.push(Span::styled(format!("[tag:{}] ", name), Style::default().fg(Color::LightYellow)));
                    }
                }
            }

            // Message court du commit
            spans.push(Span::styled(&node.summary, Style::default().fg(Color::White)));

            // Date relative / courte
            let date_str = node.time.format(" (%d/%m/%Y)").to_string();
            spans.push(Span::styled(date_str, Style::default().fg(Color::DarkGray)));

            ListItem::new(Line::from(spans))
        })
        .collect();

    let list = List::new(items)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .title(" Arbre Git & Historique ")
                .border_style(Style::default().fg(border_color)),
        )
        .highlight_style(
            Style::default()
                .bg(Color::Rgb(40, 50, 75))
                .fg(Color::White)
                .add_modifier(Modifier::BOLD),
        )
        .highlight_symbol("▶ ");

    frame.render_stateful_widget(list, area, &mut app.list_state);
}

fn render_commit_details(frame: &mut Frame, area: Rect, app: &mut App, git_ctx: &GitContext) {
    let is_focused = app.focused_panel == FocusedPanel::Details;
    let border_color = if is_focused { Color::Cyan } else { Color::DarkGray };

    let selected_commit = app.selected_commit().cloned();

    let mut lines = Vec::new();

    if let Some(commit) = selected_commit {
        lines.push(Line::from(vec![
            Span::styled("Commit: ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
            Span::styled(commit.oid.to_string(), Style::default().fg(Color::Yellow)),
        ]));

        lines.push(Line::from(vec![
            Span::styled("Auteur: ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
            Span::raw(format!("{} <{}>", commit.author_name, commit.author_email)),
        ]));

        lines.push(Line::from(vec![
            Span::styled("Date:   ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
            Span::raw(commit.time.format("%Y-%m-%d %H:%M:%S %z").to_string()),
        ]));

        if !commit.parents.is_empty() {
            let parents_str = commit.parents.iter().map(|p| p.to_string()[..7].to_string()).collect::<Vec<_>>().join(", ");
            lines.push(Line::from(vec![
                Span::styled("Parents:", Style::default().fg(Color::DarkGray).add_modifier(Modifier::BOLD)),
                Span::raw(format!(" {}", parents_str)),
            ]));
        }

        lines.push(Line::default());
        lines.push(Line::from(Span::styled("Message:", Style::default().fg(Color::White).add_modifier(Modifier::UNDERLINED))));

        for msg_line in commit.message.lines() {
            lines.push(Line::from(format!("  {}", msg_line)));
        }

        lines.push(Line::default());
        lines.push(Line::from(Span::styled("Fichiers impactés:", Style::default().fg(Color::White).add_modifier(Modifier::UNDERLINED))));

        // Charge le diff des fichiers (avec cache pour performance)
        let files = app.diff_cache.entry(commit.oid).or_insert_with(|| {
            git_ctx.get_diff_files(commit.oid).unwrap_or_default()
        });

        if files.is_empty() {
            lines.push(Line::from(Span::styled("  (aucun fichier modifié ou commit initial)", Style::default().fg(Color::DarkGray))));
        } else {
            for f in files {
                let (symbol, color) = match f.status {
                    Delta::Added => ("+ [A]", Color::Green),
                    Delta::Deleted => ("- [D]", Color::Red),
                    Delta::Modified => ("~ [M]", Color::Yellow),
                    Delta::Renamed => ("→ [R]", Color::Blue),
                    _ => ("* [?]", Color::White),
                };
                lines.push(Line::from(vec![
                    Span::styled(format!("  {} ", symbol), Style::default().fg(color).add_modifier(Modifier::BOLD)),
                    Span::raw(&f.path),
                ]));
            }
        }
    } else {
        lines.push(Line::from(Span::styled("Aucun commit sélectionné.", Style::default().fg(Color::DarkGray))));
    }

    let paragraph = Paragraph::new(lines)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .title(" Détails du Commit ")
                .border_style(Style::default().fg(border_color)),
        )
        .wrap(Wrap { trim: false })
        .scroll((app.details_scroll, 0));

    frame.render_widget(paragraph, area);
}

fn render_footer(frame: &mut Frame, area: Rect, _app: &App) {
    let help_line = Line::from(vec![
        Span::styled(" [j/↓, k/↑] ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
        Span::raw("Naviguer "),
        Span::styled(" [Tab] ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
        Span::raw("Changer Focus "),
        Span::styled(" [/] ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
        Span::raw("Recherche "),
        Span::styled(" [g/G] ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
        Span::raw("Début/Fin "),
        Span::styled(" [q/Esc] ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
        Span::raw("Quitter"),
    ]);

    let footer = Paragraph::new(help_line).style(Style::default().bg(Color::Reset));
    frame.render_widget(footer, area);
}

fn render_search_modal(frame: &mut Frame, app: &App) {
    let area = centered_rect(60, 20, frame.area());
    frame.render_widget(Clear, area);

    let text = Line::from(vec![
        Span::styled("Mot-clé: ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::styled(&app.search_query, Style::default().fg(Color::White)),
        Span::styled("█", Style::default().fg(Color::Cyan)),
    ]);

    let block = Block::default()
        .borders(Borders::ALL)
        .title(" Recherche de commits (Entrée valider / Esc annuler) ")
        .border_style(Style::default().fg(Color::Cyan));

    let p = Paragraph::new(vec![Line::default(), text])
        .block(block);

    frame.render_widget(p, area);
}

fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);

    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(popup_layout[1])[1]
}

/// Garde RAII pour restaurer systématiquement le terminal.
struct TerminalGuard;

impl Drop for TerminalGuard {
    fn drop(&mut self) {
        let _ = disable_raw_mode();
        let _ = execute!(io::stdout(), LeaveAlternateScreen);
    }
}

fn run_app<B: Backend>(
    terminal: &mut Terminal<B>,
    mut app: App,
    git_ctx: &GitContext,
) -> Result<()> {
    loop {
        terminal.draw(|f| render_ui(f, &mut app, git_ctx))?;

        if event::poll(std::time::Duration::from_millis(50))? {
            if let Event::Key(key) = event::read()? {
                if key.kind != KeyEventKind::Press {
                    continue;
                }

                if app.is_searching {
                    match key.code {
                        KeyCode::Enter => {
                            app.is_searching = false;
                        }
                        KeyCode::Esc => {
                            app.is_searching = false;
                            app.search_query.clear();
                            app.apply_filter();
                        }
                        KeyCode::Backspace => {
                            app.search_query.pop();
                            app.apply_filter();
                        }
                        KeyCode::Char(c) => {
                            app.search_query.push(c);
                            app.apply_filter();
                        }
                        _ => {}
                    }
                    continue;
                }

                match key.code {
                    KeyCode::Char('q') => {
                        app.should_quit = true;
                    }
                    KeyCode::Esc => {
                        if !app.search_query.is_empty() {
                            app.search_query.clear();
                            app.apply_filter();
                        } else {
                            app.should_quit = true;
                        }
                    }
                    KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        app.should_quit = true;
                    }
                    KeyCode::Char('/') => {
                        app.is_searching = true;
                    }
                    KeyCode::Tab => {
                        app.toggle_focus();
                    }
                    KeyCode::Down | KeyCode::Char('j') => {
                        match app.focused_panel {
                            FocusedPanel::CommitList => app.next_commit(),
                            FocusedPanel::Details => app.scroll_details_down(),
                        }
                    }
                    KeyCode::Up | KeyCode::Char('k') => {
                        match app.focused_panel {
                            FocusedPanel::CommitList => app.previous_commit(),
                            FocusedPanel::Details => app.scroll_details_up(),
                        }
                    }
                    KeyCode::PageDown => {
                        for _ in 0..10 {
                            app.next_commit();
                        }
                    }
                    KeyCode::PageUp => {
                        for _ in 0..10 {
                            app.previous_commit();
                        }
                    }
                    KeyCode::Char('g') | KeyCode::Home => {
                        app.jump_to_start();
                    }
                    KeyCode::Char('G') | KeyCode::End => {
                        app.jump_to_end();
                    }
                    _ => {}
                }
            }
        }

        if app.should_quit {
            break;
        }
    }

    Ok(())
}

fn main() -> Result<()> {
    // 1. Initialisation du dépôt Git
    let git_ctx = match GitContext::open(None) {
        Ok(ctx) => ctx,
        Err(err) => {
            eprintln!("Erreur : Impossible d'ouvrir un dépôt Git valide ici.");
            eprintln!("Détail : {:#}", err);
            std::process::exit(1);
        }
    };

    let commits = git_ctx.load_commits().context("Erreur lors de la lecture des commits Git")?;
    if commits.is_empty() {
        eprintln!("Le dépôt Git est vide ou ne contient aucun commit sur les branches actives.");
        return Ok(());
    }

    // 2. Configuration du terminal Crossterm & Ratatui
    enable_raw_mode().context("Impossible d'activer le raw mode")?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen).context("Impossible de basculer en écran alternatif")?;

    let _guard = TerminalGuard;

    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend).context("Échec d'initialisation du terminal Ratatui")?;
    terminal.clear()?;

    // 3. Boucle d'exécution
    let app = App::new(commits);
    let res = run_app(&mut terminal, app, &git_ctx);

    // RAII via _guard assure la sortie propre du terminal
    res
}

