// ============================================================================
// POINT D'ENTRÉE PRINCIPAL & BOUCLE D'ÉVÉNEMENTS
// ============================================================================

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = env::args().collect();

    // Chargement soit d'un fichier PCAP passé en argument, soit de l'échantillon intégré
    let (raw_packets, source_name) = if args.len() > 1 {
        let pcap_path = &args[1];
        if !Path::new(pcap_path).exists() {
            eprintln!("Erreur : Le fichier '{}' est introuvable.", pcap_path);
            std::process::exit(1);
        }
        let file = File::open(pcap_path)?;
        match PcapParser::parse(file) {
            Ok(pkts) => (pkts, format!("Fichier PCAP [{}]", pcap_path)),
            Err(e) => {
                eprintln!("Erreur lors de l'analyse du fichier PCAP : {}", e);
                std::process::exit(1);
            }
        }
    } else {
        (
            SamplePackets::generate(),
            "Capture de Démonstration (ARP/DNS/TCP/HTTP/ICMP)".to_string(),
        )
    };

    // Décodage des trames
    let decoded_packets: Vec<DecodedPacket> = raw_packets
        .into_iter()
        .map(PacketDecoder::decode)
        .collect();

    let mut app = App::new(decoded_packets, source_name);

    // Initialisation du terminal sécurisée par TerminalGuard
    let _guard = TerminalGuard;
    let mut terminal = TerminalGuard::init()?;

    // Boucle d'événements
    loop {
        terminal.draw(|f| ui(f, &mut app))?;

        if let Event::Key(key) = event::read()? {
            if key.kind != KeyEventKind::Press {
                continue;
            }

            // Gestion de la modale d'aide
            if app.show_help {
                if key.code == KeyCode::Esc || key.code == KeyCode::Char('?') || key.code == KeyCode::Char('q') {
                    app.show_help = false;
                }
                continue;
            }

            // Gestion de la saisie de filtre
            if app.is_entering_filter {
                match key.code {
                    KeyCode::Enter => {
                        app.is_entering_filter = false;
                        app.apply_filter();
                    }
                    KeyCode::Esc => {
                        app.is_entering_filter = false;
                        app.filter_query.clear();
                        app.apply_filter();
                    }
                    KeyCode::Backspace => {
                        app.filter_query.pop();
                    }
                    KeyCode::Char(c) => {
                        app.filter_query.push(c);
                    }
                    _ => {}
                }
                continue;
            }

            // Contrôles généraux
            match key.code {
                KeyCode::Char('q') => break,
                KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => break,
                KeyCode::Char('?') | KeyCode::F(1) => {
                    app.show_help = true;
                }
                KeyCode::Char('/') => {
                    app.is_entering_filter = true;
                    app.filter_query.clear();
                }
                KeyCode::Esc => {
                    if !app.filter_query.is_empty() {
                        app.filter_query.clear();
                        app.apply_filter();
                    }
                }
                KeyCode::Tab => {
                    app.cycle_pane(true);
                }
                KeyCode::BackTab => {
                    app.cycle_pane(false);
                }
                KeyCode::Char('1') => app.active_pane = ActivePane::PacketList,
                KeyCode::Char('2') => app.active_pane = ActivePane::ProtocolTree,
                KeyCode::Char('3') => app.active_pane = ActivePane::HexDump,

                // Contrôles spécifiques au panneau actif
                KeyCode::Up | KeyCode::Char('k') => match app.active_pane {
                    ActivePane::PacketList => app.prev_packet(),
                    ActivePane::ProtocolTree => app.prev_tree_item(),
                    ActivePane::HexDump => app.move_hex_cursor(-16),
                },
                KeyCode::Down | KeyCode::Char('j') => match app.active_pane {
                    ActivePane::PacketList => app.next_packet(),
                    ActivePane::ProtocolTree => app.next_tree_item(),
                    ActivePane::HexDump => app.move_hex_cursor(16),
                },
                KeyCode::Left | KeyCode::Char('h') => {
                    if app.active_pane == ActivePane::HexDump {
                        app.move_hex_cursor(-1);
                    }
                }
                KeyCode::Right | KeyCode::Char('l') => {
                    if app.active_pane == ActivePane::HexDump {
                        app.move_hex_cursor(1);
                    }
                }
                KeyCode::PageUp => {
                    for _ in 0..10 {
                        match app.active_pane {
                            ActivePane::PacketList => app.prev_packet(),
                            ActivePane::ProtocolTree => app.prev_tree_item(),
                            ActivePane::HexDump => app.move_hex_cursor(-80),
                        }
                    }
                }
                KeyCode::PageDown => {
                    for _ in 0..10 {
                        match app.active_pane {
                            ActivePane::PacketList => app.next_packet(),
                            ActivePane::ProtocolTree => app.next_tree_item(),
                            ActivePane::HexDump => app.move_hex_cursor(80),
                        }
                    }
                }
                KeyCode::Home => match app.active_pane {
                    ActivePane::PacketList => {
                        app.selected_packet_index = 0;
                        app.table_state.select(Some(0));
                    }
                    ActivePane::ProtocolTree => app.selected_tree_index = 0,
                    ActivePane::HexDump => {
                        app.hex_cursor_byte = 0;
                        app.hex_scroll_row = 0;
                    }
                },
                KeyCode::End => match app.active_pane {
                    ActivePane::PacketList => {
                        if !app.filtered_indices.is_empty() {
                            app.selected_packet_index = app.filtered_indices.len() - 1;
                            app.table_state.select(Some(app.selected_packet_index));
                        }
                    }
                    ActivePane::ProtocolTree => {
                        let total = app.flattened_tree_items().len();
                        if total > 0 {
                            app.selected_tree_index = total - 1;
                        }
                    }
                    ActivePane::HexDump => {
                        if let Some(pkt) = app.current_packet() {
                            if !pkt.raw.data.is_empty() {
                                app.hex_cursor_byte = pkt.raw.data.len() - 1;
                                app.adjust_hex_scroll();
                            }
                        }
                    }
                },
                _ => {}
            }
        }
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_sample_packets_generation_and_decoding() {
        let samples = SamplePackets::generate();
        assert_eq!(samples.len(), 10);

        for raw in samples {
            let decoded = PacketDecoder::decode(raw);
            assert!(!decoded.layers.is_empty());
            assert!(!decoded.protocol.is_empty());
        }
    }

    #[test]
    fn test_arp_packet_decoding() {
        let samples = SamplePackets::generate();
        let arp_pkt = &samples[0];
        let decoded = PacketDecoder::decode(arp_pkt.clone());

        assert_eq!(decoded.protocol, "ARP");
        assert!(decoded.summary.contains("Who has 192.168.1.1?"));
        assert_eq!(decoded.layers.len(), 2); // Ethernet II + ARP
    }

    #[test]
    fn test_tcp_http_packet_decoding() {
        let samples = SamplePackets::generate();
        let http_req = &samples[7];
        let decoded = PacketDecoder::decode(http_req.clone());

        assert_eq!(decoded.protocol, "HTTP");
        assert!(decoded.summary.contains("GET /index.html"));
    }

    #[test]
    fn test_pcap_parser_with_synthesized_bytes() {
        let samples = SamplePackets::generate();
        // Synthesise a standard PCAP file in memory
        let mut pcap_bytes = Vec::new();
        // Global header (24 bytes)
        pcap_bytes.extend_from_slice(&0xa1b2c3d4u32.to_le_bytes()); // magic LE
        pcap_bytes.extend_from_slice(&2u16.to_le_bytes()); // major
        pcap_bytes.extend_from_slice(&4u16.to_le_bytes()); // minor
        pcap_bytes.extend_from_slice(&0i32.to_le_bytes()); // thiszone
        pcap_bytes.extend_from_slice(&0u32.to_le_bytes()); // sigfigs
        pcap_bytes.extend_from_slice(&65535u32.to_le_bytes()); // snaplen
        pcap_bytes.extend_from_slice(&1u32.to_le_bytes()); // linktype Ethernet

        // 1 Packet header (16 bytes)
        let data = &samples[0].data;
        pcap_bytes.extend_from_slice(&1000u32.to_le_bytes()); // sec
        pcap_bytes.extend_from_slice(&500u32.to_le_bytes()); // usec
        pcap_bytes.extend_from_slice(&(data.len() as u32).to_le_bytes()); // incl_len
        pcap_bytes.extend_from_slice(&(data.len() as u32).to_le_bytes()); // orig_len
        pcap_bytes.extend_from_slice(data);

        let parsed = PcapParser::parse(&pcap_bytes[..]);
        assert!(parsed.is_ok());
        let pkts = parsed.expect("Le PCAP synthétisé doit être analysé sans erreur");
        assert_eq!(pkts.len(), 1);
        assert_eq!(pkts[0].data, *data);
    }
}

