```rust
// src/main.rs
//! net-tui-hex
//! Outil TUI d'inspection de trames réseau capturées avec découpage hexadécimal et interprétation ASCII.

use crossterm::{
    event::{self, DisableMouseCapture, EnableMouseCapture, Event, KeyCode, KeyEventKind, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::CrosstermBackend,
    layout::{Alignment, Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{
        Block, BorderType, Borders, Clear, Paragraph, Row, Table, TableState,
    },
    Frame, Terminal,
};
use std::env;
use std::fs::File;
use std::io::{self, Read, Stdout};
use std::ops::Range;
use std::path::Path;

// ============================================================================
// MODÈLE DE DONNÉES & STRUCTURES
// ============================================================================

#[derive(Debug, Clone)]
pub struct RawPacket {
    pub index: usize,
    pub timestamp_secs: f64,
    pub original_len: usize,
    pub data: Vec<u8>,
}

#[derive(Debug, Clone)]
pub struct FieldInfo {
    pub name: String,
    pub value: String,
    pub byte_range: Option<Range<usize>>,
}

#[derive(Debug, Clone)]
pub struct LayerInfo {
    pub name: String,
    pub byte_range: Range<usize>,
    pub fields: Vec<FieldInfo>,
}

#[derive(Debug, Clone)]
pub struct DecodedPacket {
    pub raw: RawPacket,
    pub source: String,
    pub destination: String,
    pub protocol: String,
    pub summary: String,
    pub layers: Vec<LayerInfo>,
}

// ============================================================================
// ANALYSEUR PCAP NATIF (Sans dépendance C externe)
// ============================================================================

pub struct PcapParser;

impl PcapParser {
    pub fn parse<R: Read>(mut reader: R) -> Result<Vec<RawPacket>, String> {
        let mut global_hdr = [0u8; 24];
        if reader.read_exact(&mut global_hdr).is_err() {
            return Err("Impossible de lire l'en-tête global PCAP (fichier trop court ou invalide).".to_string());
        }

        let magic = u32::from_ne_bytes([global_hdr[0], global_hdr[1], global_hdr[2], global_hdr[3]]);
        let (is_little_endian, is_nanosec) = match magic {
            0xa1b2c3d4 => (cfg!(target_endian = "little"), false),
            0xd4c3b2a1 => (cfg!(target_endian = "big"), false),
            0xa1b23c4d => (cfg!(target_endian = "little"), true),
            0x4d3cb2a1 => (cfg!(target_endian = "big"), true),
            _ => {
                // Test explicite des octets bruts pour endianness indépendante de l'hôte
                if global_hdr[0] == 0xd4 && global_hdr[1] == 0xc3 && global_hdr[2] == 0xb2 && global_hdr[3] == 0xa1 {
                    (true, false)
                } else if global_hdr[0] == 0xa1 && global_hdr[1] == 0xb2 && global_hdr[2] == 0xc3 && global_hdr[3] == 0xd4 {
                    (false, false)
                } else if global_hdr[0] == 0x4d && global_hdr[1] == 0x3c && global_hdr[2] == 0xb2 && global_hdr[3] == 0xa1 {
                    (true, true)
                } else if global_hdr[0] == 0xa1 && global_hdr[1] == 0xb2 && global_hdr[2] == 0x3c && global_hdr[3] == 0x4d {
                    (false, true)
                } else {
                    return Err(format!("Magic number PCAP non reconnu : {:02x}{:02x}{:02x}{:02x}",
                        global_hdr[0], global_hdr[1], global_hdr[2], global_hdr[3]));
                }
            }
        };

        let read_u32 = |b: &[u8]| -> u32 {
            if is_little_endian {
                u32::from_le_bytes([b[0], b[1], b[2], b[3]])
            } else {
                u32::from_be_bytes([b[0], b[1], b[2], b[3]])
            }
        };

        let mut packets = Vec::new();
        let mut idx = 1;
        let mut first_ts: Option<f64> = None;

        let mut pkt_hdr = [0u8; 16];
        while reader.read_exact(&mut pkt_hdr).is_ok() {
            let ts_sec = read_u32(&pkt_hdr[0..4]) as f64;
            let ts_sub = read_u32(&pkt_hdr[4..8]) as f64;
            let incl_len = read_u32(&pkt_hdr[8..12]) as usize;
            let orig_len = read_u32(&pkt_hdr[12..16]) as usize;

            let ts_fraction = if is_nanosec { ts_sub / 1_000_000_000.0 } else { ts_sub / 1_000_000.0 };
            let current_ts = ts_sec + ts_fraction;
            let rel_ts = match first_ts {
                Some(base) => current_ts - base,
                None => {
                    first_ts = Some(current_ts);
                    0.0
                }
            };

            // Protection anti-allocation excessive si fichier corrompu
            if incl_len > 65535 * 4 {
                return Err(format!("Longueur de paquet excessive ({incl_len} octets) à l'index {idx}."));
            }

            let mut packet_data = vec![0u8; incl_len];
            if reader.read_exact(&mut packet_data).is_err() {
                break; // Fin prématurée du fichier
            }

            packets.push(RawPacket {
                index: idx,
                timestamp_secs: (rel_ts * 1000.0).round() / 1000.0,
                original_len: orig_len,
                data: packet_data,
            });

            idx += 1;
        }

        if packets.is_empty() {
            Err("Le fichier PCAP ne contient aucun paquet lisible.".to_string())
        } else {
            Ok(packets)
        }
    }
}

// ============================================================================
// DÉCODEUR DE TRAMES RÉSEAU AVEC TRAÇABILITÉ DES OFFSETS
// ============================================================================

pub struct PacketDecoder;

impl PacketDecoder {
    pub fn decode(raw: RawPacket) -> DecodedPacket {
        let data = &raw.data;
        let mut layers = Vec::new();
        let mut source = "Inconnu".to_string();
        let mut destination = "Inconnu".to_string();
        let mut protocol = "RAW".to_string();
        let mut summary = format!("Trame brute ({} octets)", data.len());

        // Analyse Ethernet II si au moins 14 octets
        if data.len() >= 14 {
            let dst_mac = Self::format_mac(&data[0..6]);
            let src_mac = Self::format_mac(&data[6..12]);
            let ethertype = u16::from_be_bytes([data[12], data[13]]);

            source = src_mac.clone();
            destination = dst_mac.clone();

            let ethertype_str = match ethertype {
                0x0800 => "IPv4 (0x0800)",
                0x0806 => "ARP (0x0806)",
                0x86DD => "IPv6 (0x86DD)",
                0x8100 => "802.1Q VLAN (0x8100)",
                _other => "Protocole inconnu",
            };

            layers.push(LayerInfo {
                name: "Ethernet II".to_string(),
                byte_range: 0..14,
                fields: vec![
                    FieldInfo {
                        name: "Destination MAC".to_string(),
                        value: dst_mac,
                        byte_range: Some(0..6),
                    },
                    FieldInfo {
                        name: "Source MAC".to_string(),
                        value: src_mac,
                        byte_range: Some(6..12),
                    },
                    FieldInfo {
                        name: "Type / EtherType".to_string(),
                        value: format!("0x{:04x} ({})", ethertype, ethertype_str),
                        byte_range: Some(12..14),
                    },
                ],
            });

            match ethertype {
                0x0800 => {
                    // IPv4
                    Self::decode_ipv4(data, 14, &mut layers, &mut source, &mut destination, &mut protocol, &mut summary);
                }
                0x0806 => {
                    // ARP
                    Self::decode_arp(data, 14, &mut layers, &mut source, &mut destination, &mut protocol, &mut summary);
                }
                0x86DD => {
                    // IPv6
                    Self::decode_ipv6(data, 14, &mut layers, &mut source, &mut destination, &mut protocol, &mut summary);
                }
                _ => {
                    protocol = format!("0x{:04X}", ethertype);
                    summary = format!("Trame Ethernet non décodée (EtherType 0x{:04X})", ethertype);
                    if data.len() > 14 {
                        layers.push(LayerInfo {
                            name: "Payload Ethernet".to_string(),
                            byte_range: 14..data.len(),
                            fields: vec![FieldInfo {
                                name: "Données brutes".to_string(),
                                value: format!("{} octets", data.len() - 14),
                                byte_range: Some(14..data.len()),
                            }],
                        });
                    }
                }
            }
        } else {
            layers.push(LayerInfo {
                name: "Trame incomplète".to_string(),
                byte_range: 0..data.len(),
                fields: vec![FieldInfo {
                    name: "Données".to_string(),
                    value: format!("{} octets tronqués", data.len()),
                    byte_range: Some(0..data.len()),
                }],
            });
        }

        DecodedPacket {
            raw,
            source,
            destination,
            protocol,
            summary,
            layers,
        }
    }

    fn format_mac(bytes: &[u8]) -> String {
        format!(
            "{:02x}:{:02x}:{:02x}:{:02x}:{:02x}:{:02x}",
            bytes[0], bytes[1], bytes[2], bytes[3], bytes[4], bytes[5]
        )
    }

    fn decode_arp(
        data: &[u8],
        offset: usize,
        layers: &mut Vec<LayerInfo>,
        source: &mut String,
        destination: &mut String,
        protocol: &mut String,
        summary: &mut String,
    ) {
        *protocol = "ARP".to_string();
        if data.len() < offset + 28 {
            layers.push(LayerInfo {
                name: "ARP (Incomplet)".to_string(),
                byte_range: offset..data.len(),
                fields: vec![],
            });
            *summary = "Paquet ARP incomplet".to_string();
            return;
        }

        let htype = u16::from_be_bytes([data[offset], data[offset + 1]]);
        let ptype = u16::from_be_bytes([data[offset + 2], data[offset + 3]]);
        let hlen = data[offset + 4];
        let plen = data[offset + 5];
        let opcode = u16::from_be_bytes([data[offset + 6], data[offset + 7]]);

        let sender_mac = Self::format_mac(&data[offset + 8..offset + 14]);
        let sender_ip = format!("{}.{}.{}.{}", data[offset + 14], data[offset + 15], data[offset + 16], data[offset + 17]);
        let target_mac = Self::format_mac(&data[offset + 18..offset + 24]);
        let target_ip = format!("{}.{}.{}.{}", data[offset + 24], data[offset + 25], data[offset + 26], data[offset + 27]);

        let op_str = match opcode {
            1 => "Requête (who-has)",
            2 => "Réponse (is-at)",
            _ => "Opcode inconnu",
        };

        *source = sender_ip.clone();
        *destination = target_ip.clone();

        if opcode == 1 {
            *summary = format!("Who has {}? Tell {}", target_ip, sender_ip);
        } else if opcode == 2 {
            *summary = format!("{} is at {}", sender_ip, sender_mac);
        } else {
            *summary = format!("ARP opcode {}", opcode);
        }

        layers.push(LayerInfo {
            name: "Address Resolution Protocol (ARP)".to_string(),
            byte_range: offset..offset + 28,
            fields: vec![
                FieldInfo {
                    name: "Hardware Type".to_string(),
                    value: format!("0x{:04x} (Ethernet)", htype),
                    byte_range: Some(offset..offset + 2),
                },
                FieldInfo {
                    name: "Protocol Type".to_string(),
                    value: format!("0x{:04x} (IPv4)", ptype),
                    byte_range: Some(offset + 2..offset + 4),
                },
                FieldInfo {
                    name: "Hardware / Protocol Size".to_string(),
                    value: format!("MAC: {}, IP: {}", hlen, plen),
                    byte_range: Some(offset + 4..offset + 6),
                },
                FieldInfo {
                    name: "Opcode".to_string(),
                    value: format!("{} ({})", opcode, op_str),
                    byte_range: Some(offset + 6..offset + 8),
                },
                FieldInfo {
                    name: "Sender MAC / IP".to_string(),
                    value: format!("{} / {}", sender_mac, sender_ip),
                    byte_range: Some(offset + 8..offset + 18),
                },
                FieldInfo {
                    name: "Target MAC / IP".to_string(),
                    value: format!("{} / {}", target_mac, target_ip),
                    byte_range: Some(offset + 18..offset + 28),
                },
            ],
        });
    }

    fn decode_ipv4(
        data: &[u8],
        offset: usize,
        layers: &mut Vec<LayerInfo>,
        source: &mut String,
        destination: &mut String,
        protocol: &mut String,
        summary: &mut String,
    ) {
        if data.len() < offset + 20 {
            layers.push(LayerInfo {
                name: "IPv4 (Incomplet)".to_string(),
                byte_range: offset..data.len(),
                fields: vec![],
            });
            *protocol = "IPv4".to_string();
            *summary = "En-tête IPv4 incomplet".to_string();
            return;
        }

        let ver_ihl = data[offset];
        let version = ver_ihl >> 4;
        let ihl = (ver_ihl & 0x0f) as usize * 4;
        let dscp_ecn = data[offset + 1];
        let total_length = u16::from_be_bytes([data[offset + 2], data[offset + 3]]) as usize;
        let identification = u16::from_be_bytes([data[offset + 4], data[offset + 5]]);
        let flags_frag = u16::from_be_bytes([data[offset + 6], data[offset + 7]]);
        let df = (flags_frag & 0x4000) != 0;
        let mf = (flags_frag & 0x2000) != 0;
        let frag_offset = (flags_frag & 0x1fff) * 8;
        let ttl = data[offset + 8];
        let next_proto = data[offset + 9];
        let checksum = u16::from_be_bytes([data[offset + 10], data[offset + 11]]);

        let src_ip = format!("{}.{}.{}.{}", data[offset + 12], data[offset + 13], data[offset + 14], data[offset + 15]);
        let dst_ip = format!("{}.{}.{}.{}", data[offset + 16], data[offset + 17], data[offset + 18], data[offset + 19]);

        *source = src_ip.clone();
        *destination = dst_ip.clone();

        let proto_name = match next_proto {
            1 => "ICMP",
            6 => "TCP",
            17 => "UDP",
            _ => "IPv4-Other",
        };
        *protocol = proto_name.to_string();

        let header_end = offset + ihl.min(data.len() - offset);
        layers.push(LayerInfo {
            name: format!("Internet Protocol Version 4 (Src: {}, Dst: {})", src_ip, dst_ip),
            byte_range: offset..header_end,
            fields: vec![
                FieldInfo {
                    name: "Version / IHL".to_string(),
                    value: format!("IPv{}, Longueur en-tête: {} octets", version, ihl),
                    byte_range: Some(offset..offset + 1),
                },
                FieldInfo {
                    name: "DSCP / ECN".to_string(),
                    value: format!("0x{:02x}", dscp_ecn),
                    byte_range: Some(offset + 1..offset + 2),
                },
                FieldInfo {
                    name: "Longueur Totale".to_string(),
                    value: format!("{} octets", total_length),
                    byte_range: Some(offset + 2..offset + 4),
                },
                FieldInfo {
                    name: "Identification".to_string(),
                    value: format!("0x{:04x} ({})", identification, identification),
                    byte_range: Some(offset + 4..offset + 6),
                },
                FieldInfo {
                    name: "Flags & Fragment Offset".to_string(),
                    value: format!("DF: {}, MF: {}, Offset: {}", df, mf, frag_offset),
                    byte_range: Some(offset + 6..offset + 8),
                },
                FieldInfo {
                    name: "Time To Live (TTL)".to_string(),
                    value: format!("{}", ttl),
                    byte_range: Some(offset + 8..offset + 9),
                },
                FieldInfo {
                    name: "Protocole supérieur".to_string(),
                    value: format!("{} ({})", proto_name, next_proto),
                    byte_range: Some(offset + 9..offset + 10),
                },
                FieldInfo {
                    name: "Header Checksum".to_string(),
                    value: format!("0x{:04x}", checksum),
                    byte_range: Some(offset + 10..offset + 12),
                },
                FieldInfo {
                    name: "Source IP".to_string(),
                    value: src_ip,
                    byte_range: Some(offset + 12..offset + 16),
                },
                FieldInfo {
                    name: "Destination IP".to_string(),
                    value: dst_ip,
                    byte_range: Some(offset + 16..offset + 20),
                },
            ],
        });

        match next_proto {
            1 => Self::decode_icmp(data, header_end, layers, summary),
            6 => Self::decode_tcp(data, header_end, layers, source, destination, protocol, summary),
            17 => Self::decode_udp(data, header_end, layers, source, destination, protocol, summary),
            _ => {
                *summary = format!("IPv4 Protocole {}", next_proto);
            }
        }
    }

    fn decode_ipv6(
        data: &[u8],
        offset: usize,
        layers: &mut Vec<LayerInfo>,
        source: &mut String,
        destination: &mut String,
        protocol: &mut String,
        summary: &mut String,
    ) {
        if data.len() < offset + 40 {
            layers.push(LayerInfo {
                name: "IPv6 (Incomplet)".to_string(),
                byte_range: offset..data.len(),
                fields: vec![],
            });
            *protocol = "IPv6".to_string();
            *summary = "En-tête IPv6 incomplet".to_string();
            return;
        }

        let first_4 = u32::from_be_bytes([data[offset], data[offset + 1], data[offset + 2], data[offset + 3]]);
        let version = first_4 >> 28;
        let traffic_class = (first_4 >> 20) & 0xff;
        let flow_label = first_4 & 0xfffff;
        let payload_len = u16::from_be_bytes([data[offset + 4], data[offset + 5]]) as usize;
        let next_header = data[offset + 6];
        let hop_limit = data[offset + 7];

        let src_ip = Self::format_ipv6(&data[offset + 8..offset + 24]);
        let dst_ip = Self::format_ipv6(&data[offset + 24..offset + 40]);

        *source = src_ip.clone();
        *destination = dst_ip.clone();

        let proto_name = match next_header {
            6 => "TCP",
            17 => "UDP",
            58 => "ICMPv6",
            _ => "IPv6-Other",
        };
        *protocol = proto_name.to_string();

        let header_end = offset + 40;
        layers.push(LayerInfo {
            name: format!("Internet Protocol Version 6 (Src: {}, Dst: {})", src_ip, dst_ip),
            byte_range: offset..header_end,
            fields: vec![
                FieldInfo {
                    name: "Version / Traffic Class".to_string(),
                    value: format!("IPv{}, Classe: 0x{:02x}, Flow: 0x{:05x}", version, traffic_class, flow_label),
                    byte_range: Some(offset..offset + 4),
                },
                FieldInfo {
                    name: "Payload Length".to_string(),
                    value: format!("{} octets", payload_len),
                    byte_range: Some(offset + 4..offset + 6),
                },
                FieldInfo {
                    name: "Next Header".to_string(),
                    value: format!("{} ({})", proto_name, next_header),
                    byte_range: Some(offset + 6..offset + 7),
                },
                FieldInfo {
                    name: "Hop Limit".to_string(),
                    value: format!("{}", hop_limit),
                    byte_range: Some(offset + 7..offset + 8),
                },
                FieldInfo {
                    name: "Source IPv6".to_string(),
                    value: src_ip,
                    byte_range: Some(offset + 8..offset + 24),
                },
                FieldInfo {
                    name: "Destination IPv6".to_string(),
                    value: dst_ip,
                    byte_range: Some(offset + 24..offset + 40),
                },
            ],
        });

        match next_header {
            6 => Self::decode_tcp(data, header_end, layers, source, destination, protocol, summary),
            17 => Self::decode_udp(data, header_end, layers, source, destination, protocol, summary),
            58 => {
                *summary = "ICMPv6 Message".to_string();
                if data.len() >= header_end + 4 {
                    let icmp_type = data[header_end];
                    let icmp_code = data[header_end + 1];
                    let type_name = match icmp_type {
                        128 => "Echo Request",
                        129 => "Echo Reply",
                        133 => "Router Solicitation",
                        134 => "Router Advertisement",
                        135 => "Neighbor Solicitation",
                        136 => "Neighbor Advertisement",
                        _ => "ICMPv6 Type",
                    };
                    *summary = format!("ICMPv6 {} (Code {})", type_name, icmp_code);
                    layers.push(LayerInfo {
                        name: "ICMPv6".to_string(),
                        byte_range: header_end..data.len(),
                        fields: vec![
                            FieldInfo {
                                name: "Type".to_string(),
                                value: format!("{} ({})", icmp_type, type_name),
                                byte_range: Some(header_end..header_end + 1),
                            },
                            FieldInfo {
                                name: "Code".to_string(),
                                value: format!("{}", icmp_code),
                                byte_range: Some(header_end + 1..header_end + 2),
                            },
                        ],
                    });
                }
            }
            _ => {
                *summary = format!("IPv6 En-tête suivant: {}", next_header);
            }
        }
    }

    fn format_ipv6(b: &[u8]) -> String {
        format!(
            "{:02x}{:02x}:{:02x}{:02x}:{:02x}{:02x}:{:02x}{:02x}:{:02x}{:02x}:{:02x}{:02x}:{:02x}{:02x}:{:02x}{:02x}",
            b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7], b[8], b[9], b[10], b[11], b[12], b[13], b[14], b[15]
        )
    }

    fn decode_tcp(
        data: &[u8],
        offset: usize,
        layers: &mut Vec<LayerInfo>,
        source: &mut String,
        destination: &mut String,
        protocol: &mut String,
        summary: &mut String,
    ) {
        *protocol = "TCP".to_string();
        if data.len() < offset + 20 {
            layers.push(LayerInfo {
                name: "TCP (Incomplet)".to_string(),
                byte_range: offset..data.len(),
                fields: vec![],
            });
            *summary = "En-tête TCP incomplet".to_string();
            return;
        }

        let src_port = u16::from_be_bytes([data[offset], data[offset + 1]]);
        let dst_port = u16::from_be_bytes([data[offset + 2], data[offset + 3]]);
        let seq_num = u32::from_be_bytes([data[offset + 4], data[offset + 5], data[offset + 6], data[offset + 7]]);
        let ack_num = u32::from_be_bytes([data[offset + 8], data[offset + 9], data[offset + 10], data[offset + 11]]);
        let data_offset_byte = data[offset + 12];
        let tcp_header_len = ((data_offset_byte >> 4) as usize) * 4;
        let flags_byte = data[offset + 13];

        let fin = (flags_byte & 0x01) != 0;
        let syn = (flags_byte & 0x02) != 0;
        let rst = (flags_byte & 0x04) != 0;
        let psh = (flags_byte & 0x08) != 0;
        let ack = (flags_byte & 0x10) != 0;
        let urg = (flags_byte & 0x20) != 0;

        let window_size = u16::from_be_bytes([data[offset + 14], data[offset + 15]]);
        let checksum = u16::from_be_bytes([data[offset + 16], data[offset + 17]]);
        let urgent_ptr = u16::from_be_bytes([data[offset + 18], data[offset + 19]]);

        let mut flags_desc = Vec::new();
        if syn { flags_desc.push("SYN"); }
        if ack { flags_desc.push("ACK"); }
        if fin { flags_desc.push("FIN"); }
        if rst { flags_desc.push("RST"); }
        if psh { flags_desc.push("PSH"); }
        if urg { flags_desc.push("URG"); }
        let flags_str = if flags_desc.is_empty() { "NONE".to_string() } else { flags_desc.join(",") };

        *source = format!("{}:{}", source, src_port);
        *destination = format!("{}:{}", destination, dst_port);

        let tcp_end = (offset + tcp_header_len).min(data.len());
        layers.push(LayerInfo {
            name: format!("Transmission Control Protocol (Src Port: {}, Dst Port: {})", src_port, dst_port),
            byte_range: offset..tcp_end,
            fields: vec![
                FieldInfo {
                    name: "Source Port".to_string(),
                    value: format!("{}", src_port),
                    byte_range: Some(offset..offset + 2),
                },
                FieldInfo {
                    name: "Destination Port".to_string(),
                    value: format!("{}", dst_port),
                    byte_range: Some(offset + 2..offset + 4),
                },
                FieldInfo {
                    name: "Sequence Number".to_string(),
                    value: format!("{}", seq_num),
                    byte_range: Some(offset + 4..offset + 8),
                },
                FieldInfo {
                    name: "Acknowledgment Number".to_string(),
                    value: format!("{}", ack_num),
                    byte_range: Some(offset + 8..offset + 12),
                },
                FieldInfo {
                    name: "Header Length".to_string(),
                    value: format!("{} octets", tcp_header_len),
                    byte_range: Some(offset + 12..offset + 13),
                },
                FieldInfo {
                    name: "Flags".to_string(),
                    value: format!("0x{:02x} [{}]", flags_byte, flags_str),
                    byte_range: Some(offset + 13..offset + 14),
                },
                FieldInfo {
                    name: "Window Size".to_string(),
                    value: format!("{}", window_size),
                    byte_range: Some(offset + 14..offset + 16),
                },
                FieldInfo {
                    name: "Checksum / Urgent Pointer".to_string(),
                    value: format!("Checksum: 0x{:04x}, UrgPtr: {}", checksum, urgent_ptr),
                    byte_range: Some(offset + 16..offset + 20),
                },
            ],
        });

        let payload_len = data.len().saturating_sub(tcp_end);
        *summary = format!("{} -> {} [{}] Seq={} Ack={} Win={} Len={}",
            src_port, dst_port, flags_str, seq_num, ack_num, window_size, payload_len);

        if payload_len > 0 {
            Self::decode_payload(data, tcp_end, src_port, dst_port, layers, protocol, summary);
        }
    }

    fn decode_udp(
        data: &[u8],
        offset: usize,
        layers: &mut Vec<LayerInfo>,
        source: &mut String,
        destination: &mut String,
        protocol: &mut String,
        summary: &mut String,
    ) {
        *protocol = "UDP".to_string();
        if data.len() < offset + 8 {
            layers.push(LayerInfo {
                name: "UDP (Incomplet)".to_string(),
                byte_range: offset..data.len(),
                fields: vec![],
            });
            *summary = "En-tête UDP incomplet".to_string();
            return;
        }

        let src_port = u16::from_be_bytes([data[offset], data[offset + 1]]);
        let dst_port = u16::from_be_bytes([data[offset + 2], data[offset + 3]]);
        let length = u16::from_be_bytes([data[offset + 4], data[offset + 5]]) as usize;
        let checksum = u16::from_be_bytes([data[offset + 6], data[offset + 7]]);

        *source = format!("{}:{}", source, src_port);
        *destination = format!("{}:{}", destination, dst_port);

        let udp_end = offset + 8;
        layers.push(LayerInfo {
            name: format!("User Datagram Protocol (Src Port: {}, Dst Port: {})", src_port, dst_port),
            byte_range: offset..udp_end,
            fields: vec![
                FieldInfo {
                    name: "Source Port".to_string(),
                    value: format!("{}", src_port),
                    byte_range: Some(offset..offset + 2),
                },
                FieldInfo {
                    name: "Destination Port".to_string(),
                    value: format!("{}", dst_port),
                    byte_range: Some(offset + 2..offset + 4),
                },
                FieldInfo {
                    name: "Length".to_string(),
                    value: format!("{} octets", length),
                    byte_range: Some(offset + 4..offset + 6),
                },
                FieldInfo {
                    name: "Checksum".to_string(),
                    value: format!("0x{:04x}", checksum),
                    byte_range: Some(offset + 6..offset + 8),
                },
            ],
        });

        let payload_len = data.len().saturating_sub(udp_end);
        *summary = format!("{} -> {} Len={}", src_port, dst_port, payload_len);

        if payload_len > 0 {
            Self::decode_payload(data, udp_end, src_port, dst_port, layers, protocol, summary);
        }
    }

    fn decode_icmp(
        data: &[u8],
        offset: usize,
        layers: &mut Vec<LayerInfo>,
        summary: &mut String,
    ) {
        if data.len() < offset + 4 {
            layers.push(LayerInfo {
                name: "ICMP (Incomplet)".to_string(),
                byte_range: offset..data.len(),
                fields: vec![],
            });
            *summary = "Paquet ICMP incomplet".to_string();
            return;
        }

        let icmp_type = data[offset];
        let icmp_code = data[offset + 1];
        let checksum = u16::from_be_bytes([data[offset + 2], data[offset + 3]]);

        let (type_desc, details) = match icmp_type {
            0 => ("Echo (ping) Reply", if data.len() >= offset + 8 {
                let id = u16::from_be_bytes([data[offset + 4], data[offset + 5]]);
                let seq = u16::from_be_bytes([data[offset + 6], data[offset + 7]]);
                format!("id=0x{:04x}, seq={}", id, seq)
            } else { String::new() }),
            8 => ("Echo (ping) Request", if data.len() >= offset + 8 {
                let id = u16::from_be_bytes([data[offset + 4], data[offset + 5]]);
                let seq = u16::from_be_bytes([data[offset + 6], data[offset + 7]]);
                format!("id=0x{:04x}, seq={}", id, seq)
            } else { String::new() }),
            3 => ("Destination Unreachable", format!("Code: {}", icmp_code)),
            11 => ("Time-to-Live Exceeded", format!("Code: {}", icmp_code)),
            _ => ("ICMP Message", format!("Type: {}, Code: {}", icmp_type, icmp_code)),
        };

        *summary = if details.is_empty() {
            type_desc.to_string()
        } else {
            format!("{} ({})", type_desc, details)
        };

        let mut fields = vec![
            FieldInfo {
                name: "Type".to_string(),
                value: format!("{} ({})", icmp_type, type_desc),
                byte_range: Some(offset..offset + 1),
            },
            FieldInfo {
                name: "Code".to_string(),
                value: format!("{}", icmp_code),
                byte_range: Some(offset + 1..offset + 2),
            },
            FieldInfo {
                name: "Checksum".to_string(),
                value: format!("0x{:04x}", checksum),
                byte_range: Some(offset + 2..offset + 4),
            },
        ];

        if data.len() >= offset + 8 && (icmp_type == 0 || icmp_type == 8) {
            let id = u16::from_be_bytes([data[offset + 4], data[offset + 5]]);
            let seq = u16::from_be_bytes([data[offset + 6], data[offset + 7]]);
            fields.push(FieldInfo {
                name: "Identifier".to_string(),
                value: format!("0x{:04x} ({})", id, id),
                byte_range: Some(offset + 4..offset + 6),
            });
            fields.push(FieldInfo {
                name: "Sequence Number".to_string(),
                value: format!("{}", seq),
                byte_range: Some(offset + 6..offset + 8),
            });
        }

        layers.push(LayerInfo {
            name: "Internet Control Message Protocol (ICMP)".to_string(),
            byte_range: offset..data.len(),
            fields,
        });
    }

    fn decode_payload(
        data: &[u8],
        offset: usize,
        src_port: u16,
        dst_port: u16,
        layers: &mut Vec<LayerInfo>,
        protocol: &mut String,
        summary: &mut String,
    ) {
        let payload = &data[offset..];
        if payload.is_empty() {
            return;
        }

        // Test DNS (Port 53)
        if (src_port == 53 || dst_port == 53) && payload.len() >= 12 {
            let tx_id = u16::from_be_bytes([payload[0], payload[1]]);
            let flags = u16::from_be_bytes([payload[2], payload[3]]);
            let qdcount = u16::from_be_bytes([payload[4], payload[5]]);
            let ancount = u16::from_be_bytes([payload[6], payload[7]]);
            let is_response = (flags & 0x8000) != 0;

            *protocol = "DNS".to_string();
            let qr_str = if is_response { "Standard query response" } else { "Standard query" };
            *summary = format!("DNS {} (ID 0x{:04x}, Q: {}, Ans: {})", qr_str, tx_id, qdcount, ancount);

            layers.push(LayerInfo {
                name: "Domain Name System (DNS)".to_string(),
                byte_range: offset..data.len(),
                fields: vec![
                    FieldInfo {
                        name: "Transaction ID".to_string(),
                        value: format!("0x{:04x}", tx_id),
                        byte_range: Some(offset..offset + 2),
                    },
                    FieldInfo {
                        name: "Flags".to_string(),
                        value: format!("0x{:04x} (Response: {})", flags, is_response),
                        byte_range: Some(offset + 2..offset + 4),
                    },
                    FieldInfo {
                        name: "Questions / Answers".to_string(),
                        value: format!("Questions: {}, Réponses: {}", qdcount, ancount),
                        byte_range: Some(offset + 4..offset + 8),
                    },
                ],
            });
            return;
        }

        // Test HTTP (Ports 80, 8080, 8000 ou texte clair)
        let as_str = String::from_utf8_lossy(payload);
        let first_line = as_str.lines().next().unwrap_or("").trim();
        if first_line.starts_with("GET ")
            || first_line.starts_with("POST ")
            || first_line.starts_with("HTTP/1.0 ")
            || first_line.starts_with("HTTP/1.1 ")
        {
            *protocol = "HTTP".to_string();
            *summary = first_line.to_string();

            let header_len = payload.windows(4).position(|w| w == b"\r\n\r\n").map(|p| p + 4).unwrap_or(payload.len());

            layers.push(LayerInfo {
                name: "Hypertext Transfer Protocol (HTTP)".to_string(),
                byte_range: offset..offset + header_len,
                fields: vec![
                    FieldInfo {
                        name: "Ligne de statut / Requête".to_string(),
                        value: first_line.to_string(),
                        byte_range: Some(offset..offset + first_line.len().min(payload.len())),
                    },
                    FieldInfo {
                        name: "Taille des en-têtes".to_string(),
                        value: format!("{} octets", header_len),
                        byte_range: Some(offset..offset + header_len),
                    },
                ],
            });

            if header_len < payload.len() {
                layers.push(LayerInfo {
                    name: "Charge utile HTTP (Data / Body)".to_string(),
                    byte_range: (offset + header_len)..data.len(),
                    fields: vec![FieldInfo {
                        name: "Taille du corps".to_string(),
                        value: format!("{} octets", payload.len() - header_len),
                        byte_range: Some((offset + header_len)..data.len()),
                    }],
                });
            }
            return;
        }

        // Payload générique
        layers.push(LayerInfo {
            name: "Payload (Données applicatives)".to_string(),
            byte_range: offset..data.len(),
            fields: vec![FieldInfo {
                name: "Longueur des données".to_string(),
                value: format!("{} octets", payload.len()),
                byte_range: Some(offset..data.len()),
            }],
        });
    }
}

