pub struct SamplePackets;

impl SamplePackets {
    pub fn generate() -> Vec<RawPacket> {
        let mut packets = Vec::new();

        // 1. ARP Request
        let mut p1 = Vec::new();
        p1.extend_from_slice(&[0xff, 0xff, 0xff, 0xff, 0xff, 0xff]); // Dst Broadcast
        p1.extend_from_slice(&[0x00, 0x1a, 0x2b, 0x3c, 0x4d, 0x5e]); // Src MAC
        p1.extend_from_slice(&[0x08, 0x06]); // EtherType ARP
        p1.extend_from_slice(&[0x00, 0x01, 0x08, 0x00, 0x06, 0x04, 0x00, 0x01]); // ARP header
        p1.extend_from_slice(&[0x00, 0x1a, 0x2b, 0x3c, 0x4d, 0x5e]); // Sender MAC
        p1.extend_from_slice(&[192, 168, 1, 105]); // Sender IP
        p1.extend_from_slice(&[0x00, 0x00, 0x00, 0x00, 0x00, 0x00]); // Target MAC
        p1.extend_from_slice(&[192, 168, 1, 1]); // Target IP
        packets.push(RawPacket {
            index: 1,
            timestamp_secs: 0.000,
            original_len: p1.len(),
            data: p1,
        });

        // 2. ARP Reply
        let mut p2 = Vec::new();
        p2.extend_from_slice(&[0x00, 0x1a, 0x2b, 0x3c, 0x4d, 0x5e]); // Dst
        p2.extend_from_slice(&[0x00, 0x50, 0x56, 0xc0, 0x00, 0x08]); // Src Gateway MAC
        p2.extend_from_slice(&[0x08, 0x06]);
        p2.extend_from_slice(&[0x00, 0x01, 0x08, 0x00, 0x06, 0x04, 0x00, 0x02]); // Reply
        p2.extend_from_slice(&[0x00, 0x50, 0x56, 0xc0, 0x00, 0x08]);
        p2.extend_from_slice(&[192, 168, 1, 1]);
        p2.extend_from_slice(&[0x00, 0x1a, 0x2b, 0x3c, 0x4d, 0x5e]);
        p2.extend_from_slice(&[192, 168, 1, 105]);
        packets.push(RawPacket {
            index: 2,
            timestamp_secs: 0.001,
            original_len: p2.len(),
            data: p2,
        });

        // 3. DNS Query (UDP 53)
        let mut p3 = Vec::new();
        p3.extend_from_slice(&[0x00, 0x50, 0x56, 0xc0, 0x00, 0x08]);
        p3.extend_from_slice(&[0x00, 0x1a, 0x2b, 0x3c, 0x4d, 0x5e]);
        p3.extend_from_slice(&[0x08, 0x00]); // IPv4
        // IPv4 Header
        p3.extend_from_slice(&[0x45, 0x00, 0x00, 0x37]); // Total Len 55
        p3.extend_from_slice(&[0xa1, 0x23, 0x00, 0x00]); // ID, Flags
        p3.extend_from_slice(&[0x40, 17, 0x00, 0x00]); // TTL 64, UDP, Checksum
        p3.extend_from_slice(&[192, 168, 1, 105]);
        p3.extend_from_slice(&[1, 1, 1, 1]);
        // UDP Header
        p3.extend_from_slice(&[0xc4, 0x12]); // Port src: 50194
        p3.extend_from_slice(&[0x00, 0x35]); // Port dst: 53
        p3.extend_from_slice(&[0x00, 0x23]); // Len: 35
        p3.extend_from_slice(&[0x00, 0x00]); // Checksum
        // DNS Payload: Query example.org
        p3.extend_from_slice(&[0x1a, 0x4f, 0x01, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00]);
        p3.extend_from_slice(&[0x07, b'e', b'x', b'a', b'm', b'p', b'l', b'e', 0x03, b'o', b'r', b'g', 0x00]);
        p3.extend_from_slice(&[0x00, 0x01, 0x00, 0x01]); // Type A, Class IN
        packets.push(RawPacket {
            index: 3,
            timestamp_secs: 0.015,
            original_len: p3.len(),
            data: p3,
        });

        // 4. DNS Response (UDP 53)
        let mut p4 = Vec::new();
        p4.extend_from_slice(&[0x00, 0x1a, 0x2b, 0x3c, 0x4d, 0x5e]);
        p4.extend_from_slice(&[0x00, 0x50, 0x56, 0xc0, 0x00, 0x08]);
        p4.extend_from_slice(&[0x08, 0x00]);
        p4.extend_from_slice(&[0x45, 0x00, 0x00, 0x47]); // Len 71
        p4.extend_from_slice(&[0x00, 0x00, 0x00, 0x00]);
        p4.extend_from_slice(&[0x37, 17, 0x00, 0x00]); // TTL 55, UDP
        p4.extend_from_slice(&[1, 1, 1, 1]);
        p4.extend_from_slice(&[192, 168, 1, 105]);
        p4.extend_from_slice(&[0x00, 0x35]);
        p4.extend_from_slice(&[0xc4, 0x12]);
        p4.extend_from_slice(&[0x00, 0x33]);
        p4.extend_from_slice(&[0x00, 0x00]);
        // DNS Response Payload (Answers: 1)
        p4.extend_from_slice(&[0x1a, 0x4f, 0x81, 0x80, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00]);
        p4.extend_from_slice(&[0x07, b'e', b'x', b'a', b'm', b'p', b'l', b'e', 0x03, b'o', b'r', b'g', 0x00]);
        p4.extend_from_slice(&[0x00, 0x01, 0x00, 0x01]);
        p4.extend_from_slice(&[0xc0, 0x0c, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x0e, 0x10, 0x00, 0x04]);
        p4.extend_from_slice(&[93, 184, 216, 34]); // 93.184.216.34
        packets.push(RawPacket {
            index: 4,
            timestamp_secs: 0.032,
            original_len: p4.len(),
            data: p4,
        });

        // 5. TCP SYN (Port 49152 -> 80)
        let mut p5 = Vec::new();
        p5.extend_from_slice(&[0x00, 0x50, 0x56, 0xc0, 0x00, 0x08]);
        p5.extend_from_slice(&[0x00, 0x1a, 0x2b, 0x3c, 0x4d, 0x5e]);
        p5.extend_from_slice(&[0x08, 0x00]);
        p5.extend_from_slice(&[0x45, 0x00, 0x00, 0x34]); // Len 52
        p5.extend_from_slice(&[0x2a, 0x4c, 0x40, 0x00]); // DF
        p5.extend_from_slice(&[0x40, 6, 0x00, 0x00]); // TTL 64, TCP
        p5.extend_from_slice(&[192, 168, 1, 105]);
        p5.extend_from_slice(&[93, 184, 216, 34]);
        // TCP
        p5.extend_from_slice(&[0xc0, 0x00]); // Src Port: 49152
        p5.extend_from_slice(&[0x00, 0x50]); // Dst Port: 80
        p5.extend_from_slice(&[0x12, 0x34, 0x56, 0x78]); // Seq: 305419896
        p5.extend_from_slice(&[0x00, 0x00, 0x00, 0x00]); // Ack: 0
        p5.extend_from_slice(&[0x50, 0x02]); // Offset 20 bytes (0x50), SYN (0x02)
        p5.extend_from_slice(&[0xfa, 0xf0]); // Window: 64240
        p5.extend_from_slice(&[0x00, 0x00, 0x00, 0x00]); // Checksum, Urg
        packets.push(RawPacket {
            index: 5,
            timestamp_secs: 0.045,
            original_len: p5.len(),
            data: p5,
        });

        // 6. TCP SYN, ACK (Port 80 -> 49152)
        let mut p6 = Vec::new();
        p6.extend_from_slice(&[0x00, 0x1a, 0x2b, 0x3c, 0x4d, 0x5e]);
        p6.extend_from_slice(&[0x00, 0x50, 0x56, 0xc0, 0x00, 0x08]);
        p6.extend_from_slice(&[0x08, 0x00]);
        p6.extend_from_slice(&[0x45, 0x00, 0x00, 0x34]);
        p6.extend_from_slice(&[0x00, 0x00, 0x40, 0x00]);
        p6.extend_from_slice(&[0x36, 6, 0x00, 0x00]); // TTL 54, TCP
        p6.extend_from_slice(&[93, 184, 216, 34]);
        p6.extend_from_slice(&[192, 168, 1, 105]);
        p6.extend_from_slice(&[0x00, 0x50]);
        p6.extend_from_slice(&[0xc0, 0x00]);
        p6.extend_from_slice(&[0x87, 0x65, 0x43, 0x21]); // Seq: 2271560481
        p6.extend_from_slice(&[0x12, 0x34, 0x56, 0x79]); // Ack: 305419897
        p6.extend_from_slice(&[0x50, 0x12]); // SYN, ACK (0x12)
        p6.extend_from_slice(&[0x72, 0x10]); // Win: 29200
        p6.extend_from_slice(&[0x00, 0x00, 0x00, 0x00]);
        packets.push(RawPacket {
            index: 6,
            timestamp_secs: 0.062,
            original_len: p6.len(),
            data: p6,
        });

        // 7. TCP ACK (Handshake complete)
        let mut p7 = Vec::new();
        p7.extend_from_slice(&[0x00, 0x50, 0x56, 0xc0, 0x00, 0x08]);
        p7.extend_from_slice(&[0x00, 0x1a, 0x2b, 0x3c, 0x4d, 0x5e]);
        p7.extend_from_slice(&[0x08, 0x00]);
        p7.extend_from_slice(&[0x45, 0x00, 0x00, 0x28]); // Len 40
        p7.extend_from_slice(&[0x2a, 0x4d, 0x40, 0x00]);
        p7.extend_from_slice(&[0x40, 6, 0x00, 0x00]);
        p7.extend_from_slice(&[192, 168, 1, 105]);
        p7.extend_from_slice(&[93, 184, 216, 34]);
        p7.extend_from_slice(&[0xc0, 0x00]);
        p7.extend_from_slice(&[0x00, 0x50]);
        p7.extend_from_slice(&[0x12, 0x34, 0x56, 0x79]);
        p7.extend_from_slice(&[0x87, 0x65, 0x43, 0x22]);
        p7.extend_from_slice(&[0x50, 0x10]); // ACK (0x10)
        p7.extend_from_slice(&[0x01, 0xf5]); // Win
        p7.extend_from_slice(&[0x00, 0x00, 0x00, 0x00]);
        packets.push(RawPacket {
            index: 7,
            timestamp_secs: 0.063,
            original_len: p7.len(),
            data: p7,
        });

        // 8. HTTP GET Request
        let mut p8 = Vec::new();
        p8.extend_from_slice(&[0x00, 0x50, 0x56, 0xc0, 0x00, 0x08]);
        p8.extend_from_slice(&[0x00, 0x1a, 0x2b, 0x3c, 0x4d, 0x5e]);
        p8.extend_from_slice(&[0x08, 0x00]);
        let http_req = b"GET /index.html HTTP/1.1\r\nHost: example.org\r\nUser-Agent: NetTuiHex/1.0\r\nAccept: */*\r\n\r\n";
        let ip_total = 40 + http_req.len();
        p8.extend_from_slice(&[0x45, 0x00, (ip_total >> 8) as u8, (ip_total & 0xff) as u8]);
        p8.extend_from_slice(&[0x2a, 0x4e, 0x40, 0x00]);
        p8.extend_from_slice(&[0x40, 6, 0x00, 0x00]);
        p8.extend_from_slice(&[192, 168, 1, 105]);
        p8.extend_from_slice(&[93, 184, 216, 34]);
        p8.extend_from_slice(&[0xc0, 0x00]);
        p8.extend_from_slice(&[0x00, 0x50]);
        p8.extend_from_slice(&[0x12, 0x34, 0x56, 0x79]);
        p8.extend_from_slice(&[0x87, 0x65, 0x43, 0x22]);
        p8.extend_from_slice(&[0x50, 0x18]); // PSH, ACK
        p8.extend_from_slice(&[0x01, 0xf5]);
        p8.extend_from_slice(&[0x00, 0x00, 0x00, 0x00]);
        p8.extend_from_slice(http_req);
        packets.push(RawPacket {
            index: 8,
            timestamp_secs: 0.068,
            original_len: p8.len(),
            data: p8,
        });

        // 9. HTTP 200 OK Response
        let mut p9 = Vec::new();
        p9.extend_from_slice(&[0x00, 0x1a, 0x2b, 0x3c, 0x4d, 0x5e]);
        p9.extend_from_slice(&[0x00, 0x50, 0x56, 0xc0, 0x00, 0x08]);
        p9.extend_from_slice(&[0x08, 0x00]);
        let http_resp = b"HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=UTF-8\r\nContent-Length: 48\r\nConnection: close\r\n\r\n<!DOCTYPE html><html><body><h1>Hello NetTuiHex!</h1></body></html>";
        let resp_ip_total = 40 + http_resp.len();
        p9.extend_from_slice(&[0x45, 0x00, (resp_ip_total >> 8) as u8, (resp_ip_total & 0xff) as u8]);
        p9.extend_from_slice(&[0x10, 0x20, 0x40, 0x00]);
        p9.extend_from_slice(&[0x36, 6, 0x00, 0x00]);
        p9.extend_from_slice(&[93, 184, 216, 34]);
        p9.extend_from_slice(&[192, 168, 1, 105]);
        p9.extend_from_slice(&[0x00, 0x50]);
        p9.extend_from_slice(&[0xc0, 0x00]);
        p9.extend_from_slice(&[0x87, 0x65, 0x43, 0x22]);
        p9.extend_from_slice(&[0x12, 0x34, 0x56, 0xd0]);
        p9.extend_from_slice(&[0x50, 0x18]); // PSH, ACK
        p9.extend_from_slice(&[0x01, 0xf5]);
        p9.extend_from_slice(&[0x00, 0x00, 0x00, 0x00]);
        p9.extend_from_slice(http_resp);
        packets.push(RawPacket {
            index: 9,
            timestamp_secs: 0.089,
            original_len: p9.len(),
            data: p9,
        });

        // 10. ICMP Echo Request
        let mut p10 = Vec::new();
        p10.extend_from_slice(&[0x00, 0x50, 0x56, 0xc0, 0x00, 0x08]);
        p10.extend_from_slice(&[0x00, 0x1a, 0x2b, 0x3c, 0x4d, 0x5e]);
        p10.extend_from_slice(&[0x08, 0x00]);
        p10.extend_from_slice(&[0x45, 0x00, 0x00, 0x54]); // Len 84
        p10.extend_from_slice(&[0x71, 0x92, 0x00, 0x00]);
        p10.extend_from_slice(&[0x40, 1, 0x00, 0x00]); // TTL 64, ICMP
        p10.extend_from_slice(&[192, 168, 1, 105]);
        p10.extend_from_slice(&[8, 8, 8, 8]);
        // ICMP Echo
        p10.extend_from_slice(&[0x08, 0x00, 0x4d, 0x5a]); // Type 8, Code 0, Checksum
        p10.extend_from_slice(&[0x1a, 0x01, 0x00, 0x01]); // ID 0x1a01, Seq 1
        p10.extend_from_slice(b"abcdefghijklmnopqrstuvwabcdefghi"); // 32 bytes ping payload
        packets.push(RawPacket {
            index: 10,
            timestamp_secs: 0.120,
            original_len: p10.len(),
            data: p10,
        });

        packets
    }
}

// ============================================================================
// ÉTAT DE L'APPLICATION ET GESTIONNAIRE D'ÉCRAN TUI
// ============================================================================

#[derive(Debug, PartialEq, Eq, Copy, Clone)]
pub enum ActivePane {
    PacketList,
    ProtocolTree,
    HexDump,
}

pub struct App {
    pub packets: Vec<DecodedPacket>,
    pub filtered_indices: Vec<usize>,
    pub selected_packet_index: usize,
    pub selected_tree_index: usize,
    pub hex_cursor_byte: usize,
    pub hex_scroll_row: usize,
    pub active_pane: ActivePane,
    pub filter_query: String,
    pub is_entering_filter: bool,
    pub show_help: bool,
    pub status_message: Option<(String, Color)>,
    pub capture_source_name: String,
    pub table_state: TableState,
}

impl App {
    pub fn new(packets: Vec<DecodedPacket>, source_name: String) -> Self {
        let count = packets.len();
        let filtered_indices: Vec<usize> = (0..count).collect();
        let mut table_state = TableState::default();
        if !filtered_indices.is_empty() {
            table_state.select(Some(0));
        }

        Self {
            packets,
            filtered_indices,
            selected_packet_index: 0,
            selected_tree_index: 0,
            hex_cursor_byte: 0,
            hex_scroll_row: 0,
            active_pane: ActivePane::PacketList,
            filter_query: String::new(),
            is_entering_filter: false,
            show_help: false,
            status_message: None,
            capture_source_name: source_name,
            table_state,
        }
    }

    pub fn current_packet(&self) -> Option<&DecodedPacket> {
        if self.filtered_indices.is_empty() {
            return None;
        }
        let real_idx = self.filtered_indices[self.selected_packet_index];
        self.packets.get(real_idx)
    }

    pub fn apply_filter(&mut self) {
        let query = self.filter_query.trim().to_lowercase();
        if query.is_empty() {
            self.filtered_indices = (0..self.packets.len()).collect();
        } else {
            self.filtered_indices = self
                .packets
                .iter()
                .enumerate()
                .filter(|(_, pkt)| {
                    pkt.protocol.to_lowercase().contains(&query)
                        || pkt.source.to_lowercase().contains(&query)
                        || pkt.destination.to_lowercase().contains(&query)
                        || pkt.summary.to_lowercase().contains(&query)
                        || pkt.raw.index.to_string() == query
                })
                .map(|(idx, _)| idx)
                .collect();
        }

        self.selected_packet_index = 0;
        self.selected_tree_index = 0;
        self.hex_cursor_byte = 0;
        self.hex_scroll_row = 0;

        if !self.filtered_indices.is_empty() {
            self.table_state.select(Some(0));
            self.status_message = Some((
                format!("Filtre appliqué : {} trames trouvées", self.filtered_indices.len()),
                Color::Green,
            ));
        } else {
            self.table_state.select(None);
            self.status_message = Some(("Aucune trame ne correspond au filtre".to_string(), Color::Yellow));
        }
    }

    pub fn flattened_tree_items(&self) -> Vec<(&str, String, Option<Range<usize>>, bool)> {
        // (Label/Nom, Valeur, Range, is_header)
        let mut items = Vec::new();
        if let Some(pkt) = self.current_packet() {
            for layer in &pkt.layers {
                items.push((layer.name.as_str(), String::new(), Some(layer.byte_range.clone()), true));
                for field in &layer.fields {
                    items.push((field.name.as_str(), field.value.clone(), field.byte_range.clone(), false));
                }
            }
        }
        items
    }

    pub fn get_active_byte_highlight_range(&self) -> Option<Range<usize>> {
        let items = self.flattened_tree_items();
        if let Some(item) = items.get(self.selected_tree_index) {
            item.2.clone()
        } else {
            None
        }
    }

    pub fn next_packet(&mut self) {
        if self.filtered_indices.is_empty() {
            return;
        }
        if self.selected_packet_index + 1 < self.filtered_indices.len() {
            self.selected_packet_index += 1;
            self.table_state.select(Some(self.selected_packet_index));
            self.selected_tree_index = 0;
            self.hex_cursor_byte = 0;
            self.hex_scroll_row = 0;
        }
    }

    pub fn prev_packet(&mut self) {
        if self.filtered_indices.is_empty() {
            return;
        }
        if self.selected_packet_index > 0 {
            self.selected_packet_index -= 1;
            self.table_state.select(Some(self.selected_packet_index));
            self.selected_tree_index = 0;
            self.hex_cursor_byte = 0;
            self.hex_scroll_row = 0;
        }
    }

    pub fn next_tree_item(&mut self) {
        let count = self.flattened_tree_items().len();
        if count == 0 {
            return;
        }
        if self.selected_tree_index + 1 < count {
            self.selected_tree_index += 1;
            // Aligner le curseur hexadécimal sur le premier octet de la sélection
            if let Some(range) = self.get_active_byte_highlight_range() {
                self.hex_cursor_byte = range.start;
                self.adjust_hex_scroll();
            }
        }
    }

    pub fn prev_tree_item(&mut self) {
        let count = self.flattened_tree_items().len();
        if count == 0 {
            return;
        }
        if self.selected_tree_index > 0 {
            self.selected_tree_index -= 1;
            if let Some(range) = self.get_active_byte_highlight_range() {
                self.hex_cursor_byte = range.start;
                self.adjust_hex_scroll();
            }
        }
    }

    pub fn move_hex_cursor(&mut self, delta: isize) {
        if let Some(pkt) = self.current_packet() {
            let max_len = pkt.raw.data.len();
            if max_len == 0 {
                return;
            }
            let new_pos = (self.hex_cursor_byte as isize + delta).clamp(0, (max_len - 1) as isize) as usize;
            self.hex_cursor_byte = new_pos;
            self.adjust_hex_scroll();
        }
    }

    fn adjust_hex_scroll(&mut self) {
        let target_row = self.hex_cursor_byte / 16;
        if target_row < self.hex_scroll_row {
            self.hex_scroll_row = target_row;
        } else if target_row >= self.hex_scroll_row + 12 {
            self.hex_scroll_row = target_row.saturating_sub(11);
        }
    }

    pub fn cycle_pane(&mut self, forward: bool) {
        self.active_pane = match (self.active_pane, forward) {
            (ActivePane::PacketList, true) => ActivePane::ProtocolTree,
            (ActivePane::ProtocolTree, true) => ActivePane::HexDump,
            (ActivePane::HexDump, true) => ActivePane::PacketList,
            (ActivePane::PacketList, false) => ActivePane::HexDump,
            (ActivePane::ProtocolTree, false) => ActivePane::PacketList,
            (ActivePane::HexDump, false) => ActivePane::ProtocolTree,
        };
    }
}

// ============================================================================
// GESTION DU TERMINAL AVEC NETTOYAGE FIABLE
// ============================================================================

struct TerminalGuard;

impl TerminalGuard {
    pub fn init() -> Result<Terminal<CrosstermBackend<Stdout>>, io::Error> {
        enable_raw_mode()?;
        let mut stdout = io::stdout();
        execute!(stdout, EnterAlternateScreen, EnableMouseCapture)?;
        let backend = CrosstermBackend::new(stdout);
        Terminal::new(backend)
    }
}

impl Drop for TerminalGuard {
    fn drop(&mut self) {
        let _ = disable_raw_mode();
        let _ = execute!(io::stdout(), LeaveAlternateScreen, DisableMouseCapture);
    }
}

// ============================================================================
// RENDU DE L'INTERFACE TUI (RATATUI)
// ============================================================================

fn ui(f: &mut Frame, app: &mut App) {
    let size = f.area();

    // Disposition verticale globale
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // Header
            Constraint::Percentage(45), // Liste des paquets
            Constraint::Percentage(45), // Arbre protocolaire + HexDump
            Constraint::Length(3), // Footer / Status
        ])
        .split(size);

    // 1. HEADER
    let total_pkts = app.packets.len();
    let shown_pkts = app.filtered_indices.len();
    let header_text = vec![
        Line::from(vec![
            Span::styled(" NET-TUI-HEX ", Style::default().fg(Color::Black).bg(Color::Cyan).add_modifier(Modifier::BOLD)),
            Span::raw(" │ Source: "),
            Span::styled(&app.capture_source_name, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
            Span::raw(format!(" │ Trames: {}/{}", shown_pkts, total_pkts)),
            Span::raw(" │ Onglet actif: "),
            Span::styled(
                match app.active_pane {
                    ActivePane::PacketList => "[1] Liste des Trames",
                    ActivePane::ProtocolTree => "[2] Arbre Protocolaire",
                    ActivePane::HexDump => "[3] Hex & ASCII",
                },
                Style::default().fg(Color::Green).add_modifier(Modifier::BOLD),
            ),
        ]),
        Line::from(vec![
            Span::styled(" [Tab] Changer de vue │ [/] Filtrer │ [?] Aide │ [q] Quitter", Style::default().fg(Color::DarkGray)),
        ]),
    ];
    let header_widget = Paragraph::new(header_text)
        .block(Block::default().borders(Borders::ALL).border_type(BorderType::Rounded).title(" Inspection Réseau "));
    f.render_widget(header_widget, chunks[0]);

    // 2. LISTE DES TRAMES (TABLE)
    let selected_border_style = |pane: ActivePane| -> Style {
        if app.active_pane == pane {
            Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(Color::DarkGray)
        }
    };

    let table_rows: Vec<Row> = app
        .filtered_indices
        .iter()
        .enumerate()
        .map(|(display_idx, &real_idx)| {
            let pkt = &app.packets[real_idx];
            let proto_color = match pkt.protocol.as_str() {
                "TCP" => Color::Green,
                "UDP" => Color::Blue,
                "ICMP" | "ICMPv6" => Color::Magenta,
                "DNS" => Color::LightBlue,
                "HTTP" => Color::LightGreen,
                "ARP" => Color::Yellow,
                _ => Color::White,
            };

            Row::new(vec![
                pkt.raw.index.to_string(),
                format!("{:.3}", pkt.raw.timestamp_secs),
                pkt.source.clone(),
                pkt.destination.clone(),
                pkt.protocol.clone(),
                pkt.raw.original_len.to_string(),
                pkt.summary.clone(),
            ])
            .style(if display_idx == app.selected_packet_index {
                Style::default().fg(Color::White).bg(Color::Rgb(40, 60, 90)).add_modifier(Modifier::BOLD)
            } else {
                Style::default().fg(proto_color)
            })
        })
        .collect();

    let table_header = Row::new(vec!["N°", "Temps (s)", "Source", "Destination", "Proto", "Taille", "Résumé Info"])
        .style(Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))
        .bottom_margin(0);

    let table_block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(selected_border_style(ActivePane::PacketList))
        .title(" [1] Trames Capturées ");

    let table = Table::new(
        table_rows,
        [
            Constraint::Length(6),
            Constraint::Length(10),
            Constraint::Length(22),
            Constraint::Length(22),
            Constraint::Length(8),
            Constraint::Length(8),
            Constraint::Min(20),
        ],
    )
    .header(table_header)
    .block(table_block)
    .row_highlight_style(Style::default().add_modifier(Modifier::REVERSED));

    f.render_stateful_widget(table, chunks[1], &mut app.table_state);

    // 3. PANNEAU INFÉRIEUR : DÉCOUPE HORIZONTALE (Détails protocolaires | HexDump)
    let bottom_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(45), Constraint::Percentage(55)])
        .split(chunks[2]);

    // 3.1. ARBRE PROTOCOLAIRE
    let tree_items = app.flattened_tree_items();
    let mut tree_lines = Vec::new();

    if tree_items.is_empty() {
        tree_lines.push(Line::from(Span::styled("Aucune trame sélectionnée", Style::default().fg(Color::DarkGray))));
    } else {
        for (i, (name, val, range, is_header)) in tree_items.iter().enumerate() {
            let is_selected = i == app.selected_tree_index;
            let offset_tag = if let Some(r) = range {
                format!("[{:04x}..{:04x}] ", r.start, r.end)
            } else {
                "             ".to_string()
            };

            let line = if *is_header {
                let prefix = if is_selected { "▶ ▼ " } else { "  ▼ " };
                Line::from(vec![
                    Span::styled(prefix, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
                    Span::styled(format!("{} ", name), Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
                    Span::styled(offset_tag, Style::default().fg(Color::DarkGray)),
                ])
            } else {
                let prefix = if is_selected { "  → " } else { "    • " };
                Line::from(vec![
                    Span::styled(prefix, Style::default().fg(Color::LightCyan)),
                    Span::styled(format!("{}: ", name), Style::default().fg(Color::White)),
                    Span::styled(format!("{} ", val), Style::default().fg(Color::LightYellow)),
                    Span::styled(offset_tag, Style::default().fg(Color::DarkGray)),
                ])
            };

            if is_selected {
                tree_lines.push(Line::from(vec![
                    Span::styled("▌", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
                    Span::styled(format!(" {}", line.spans.iter().map(|s| s.content.as_ref()).collect::<String>()),
                        Style::default().bg(Color::Rgb(30, 45, 65)).fg(Color::White).add_modifier(Modifier::BOLD)),
                ]));
            } else {
                tree_lines.push(line);
            }
        }
    }

    let tree_block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(selected_border_style(ActivePane::ProtocolTree))
        .title(" [2] Décomposition Protocolaire & Champs ");
    let tree_widget = Paragraph::new(tree_lines).block(tree_block);
    f.render_widget(tree_widget, bottom_chunks[0]);

    // 3.2. DÉCOUPAGE HEXADÉCIMAL & INTERPRÉTATION ASCII
    render_hex_dump(f, app, bottom_chunks[1], selected_border_style(ActivePane::HexDump));

    // 4. FOOTER / STATUS BAR
    render_footer(f, app, chunks[3]);

    // 5. MODALE D'AIDE (SI ACTIVÉE)
    if app.show_help {
        render_help_modal(f, size);
    }
}

fn render_hex_dump(f: &mut Frame, app: &App, area: Rect, border_style: Style) {
    let current_pkt = app.current_packet();
    let data = current_pkt.map(|p| p.raw.data.as_slice()).unwrap_or(&[]);
    let highlight_range = app.get_active_byte_highlight_range();
    let cursor_byte = app.hex_cursor_byte;

    let mut hex_lines = Vec::new();

    // Ligne d'en-tête de colonnes pour les offsets 0 à 15
    hex_lines.push(Line::from(vec![
        Span::styled("  Offset   ", Style::default().fg(Color::DarkGray)),
        Span::styled("00 01 02 03 04 05 06 07  08 09 0a 0b 0c 0d 0e 0f", Style::default().fg(Color::Yellow)),
        Span::styled("  ASCII", Style::default().fg(Color::Yellow)),
    ]));

    if data.is_empty() {
        hex_lines.push(Line::from(Span::styled("  Aucune donnée disponible", Style::default().fg(Color::DarkGray))));
    } else {
        let total_rows = data.len().div_ceil(16);
        let visible_rows = (area.height as usize).saturating_sub(4);
        let start_row = app.hex_scroll_row.min(total_rows.saturating_sub(1));
        let end_row = (start_row + visible_rows).min(total_rows);

        for row in start_row..end_row {
            let row_offset = row * 16;
            let mut line_spans = Vec::new();

            // 1. Colonne Offset mémoire (ex: 00000010: )
            line_spans.push(Span::styled(
                format!("  {:08x}: ", row_offset),
                Style::default().fg(Color::DarkGray),
            ));

            // 2. Colonne Hexadécimale (16 octets séparés en 2 blocs de 8)
            let mut ascii_spans = Vec::new();

            for col in 0..16 {
                let byte_idx = row_offset + col;
                if col == 8 {
                    line_spans.push(Span::raw(" "));
                }

                if byte_idx < data.len() {
                    let b = data[byte_idx];
                    let is_cursor = byte_idx == cursor_byte;
                    let is_in_range = highlight_range.as_ref().is_some_and(|r| r.contains(&byte_idx));

                    // Style pour octet hex
                    let hex_style = if is_cursor {
                        Style::default().fg(Color::Black).bg(Color::Cyan).add_modifier(Modifier::BOLD)
                    } else if is_in_range {
                        Style::default().fg(Color::Black).bg(Color::LightYellow).add_modifier(Modifier::BOLD)
                    } else {
                        Style::default().fg(Color::White)
                    };

                    line_spans.push(Span::styled(format!("{:02x} ", b), hex_style));

                    // Style pour caractère ASCII
                    let ascii_char = if b.is_ascii_graphic() || b == b' ' {
                        b as char
                    } else {
                        '.'
                    };

                    let ascii_style = if is_cursor {
                        Style::default().fg(Color::Black).bg(Color::Cyan).add_modifier(Modifier::BOLD)
                    } else if is_in_range {
                        Style::default().fg(Color::Black).bg(Color::LightYellow).add_modifier(Modifier::BOLD)
                    } else if b.is_ascii_graphic() {
                        Style::default().fg(Color::Green)
                    } else {
                        Style::default().fg(Color::DarkGray)
                    };

                    ascii_spans.push(Span::styled(ascii_char.to_string(), ascii_style));
                } else {
                    line_spans.push(Span::raw("   "));
                    ascii_spans.push(Span::raw(" "));
                }
            }

            line_spans.push(Span::raw(" │ "));
            line_spans.extend(ascii_spans);

            hex_lines.push(Line::from(line_spans));
        }
    }

    // Inspecteur d'octet sélectionné
    let cursor_info = if !data.is_empty() && cursor_byte < data.len() {
        let b = data[cursor_byte];
        let char_repr = if b.is_ascii_graphic() || b == b' ' {
            format!("'{}'", b as char)
        } else {
            "Non-imprimable".to_string()
        };
        format!(
            " Octet 0x{:04x} ({}) │ Hex: 0x{:02x} │ Déc: {:3} │ Bin: {:08b} │ ASCII: {} ",
            cursor_byte, cursor_byte, b, b, b, char_repr
        )
    } else {
        " Curseur hors trame ".to_string()
    };

    let hex_block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(border_style)
        .title(" [3] Découpage Hexadécimal & Interprétation ASCII ")
        .title_bottom(Line::from(Span::styled(cursor_info, Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD))));

    let hex_widget = Paragraph::new(hex_lines).block(hex_block);
    f.render_widget(hex_widget, area);
}

fn render_footer(f: &mut Frame, app: &App, area: Rect) {
    if app.is_entering_filter {
        let filter_line = Line::from(vec![
