        let arp_pkt = &samples[0];
        let decoded = PacketDecoder::decode(arp_pkt.clone());

        assert_eq!(decoded.protocol, "ARP");
        assert!(decoded.summary.contains("Who has 192.168.1.1?"));
        assert_eq!(decoded.layers.len(), 2); // Ethernet II + ARP
    }

    #[test]
    fn test_tcp_http_packet_decoding() {
        let samples = SamplePackets::generate();
        let http_req = &samples[7];
        let decoded = PacketDecoder::decode(http_req.clone());

        assert_eq!(decoded.protocol, "HTTP");
        assert!(decoded.summary.contains("GET /index.html"));
    }

    #[test]
    fn test_pcap_parser_with_synthesized_bytes() {
        let samples = SamplePackets::generate();
        // Synthesise a standard PCAP file in memory
        let mut pcap_bytes = Vec::new();
        // Global header (24 bytes)
        pcap_bytes.extend_from_slice(&0xa1b2c3d4u32.to_le_bytes()); // magic LE
        pcap_bytes.extend_from_slice(&2u16.to_le_bytes()); // major
        pcap_bytes.extend_from_slice(&4u16.to_le_bytes()); // minor
        pcap_bytes.extend_from_slice(&0i32.to_le_bytes()); // thiszone
        pcap_bytes.extend_from_slice(&0u32.to_le_bytes()); // sigfigs
        pcap_bytes.extend_from_slice(&65535u32.to_le_bytes()); // snaplen
        pcap_bytes.extend_from_slice(&1u32.to_le_bytes()); // linktype Ethernet

        // 1 Packet header (16 bytes)
        let data = &samples[0].data;
        pcap_bytes.extend_from_slice(&1000u32.to_le_bytes()); // sec
        pcap_bytes.extend_from_slice(&500u32.to_le_bytes()); // usec
        pcap_bytes.extend_from_slice(&(data.len() as u32).to_le_bytes()); // incl_len
        pcap_bytes.extend_from_slice(&(data.len() as u32).to_le_bytes()); // orig_len
        pcap_bytes.extend_from_slice(data);

        let parsed = PcapParser::parse(&pcap_bytes[..]);
        assert!(parsed.is_ok());
        let pkts = parsed.expect("Le PCAP synthétisé doit être analysé sans erreur");
        assert_eq!(pkts.len(), 1);
        assert_eq!(pkts[0].data, *data);
    }
}

