#[derive(Debug, Clone)]
pub struct TextField {
    pub label: String,
    pub value: String,
    pub cursor_pos: usize,
    pub placeholder: String,
}

impl TextField {
    pub fn new(label: impl Into<String>, placeholder: impl Into<String>) -> Self {
        Self {
            label: label.into(),
            value: String::new(),
            cursor_pos: 0,
            placeholder: placeholder.into(),
        }
    }

    pub fn insert_char(&mut self, c: char) {
        if self.cursor_pos <= self.value.len() {
            self.value.insert(self.cursor_pos, c);
            self.cursor_pos += c.len_utf8();
        }
    }

    pub fn delete_prev_char(&mut self) {
        if self.cursor_pos > 0 && !self.value.is_empty() {
            let mut prev_char_idx = 0;
            for (idx, _) in self.value.char_indices() {
                if idx >= self.cursor_pos {
                    break;
                }
                prev_char_idx = idx;
            }
            self.value.remove(prev_char_idx);
            self.cursor_pos = prev_char_idx;
        }
    }

    pub fn move_cursor_left(&mut self) {
        if self.cursor_pos > 0 {
            let mut prev = 0;
            for (idx, _) in self.value.char_indices() {
                if idx >= self.cursor_pos {
                    break;
                }
                prev = idx;
            }
            self.cursor_pos = prev;
        }
    }

    pub fn move_cursor_right(&mut self) {
        for (idx, _) in self.value.char_indices() {
            if idx > self.cursor_pos {
                self.cursor_pos = idx;
                return;
            }
        }
        self.cursor_pos = self.value.len();
    }
}

#[derive(Debug, Clone)]
pub struct CheckboxField {
    pub label: String,
    pub checked: bool,
}

impl CheckboxField {
    pub fn new(label: impl Into<String>, default: bool) -> Self {
        Self {
            label: label.into(),
            checked: default,
        }
    }

    pub fn toggle(&mut self) {
        self.checked = !self.checked;
    }
}

#[derive(Debug, Clone)]
pub struct SelectField {
    pub label: String,
    pub options: Vec<String>,
    pub selected_index: usize,
    pub is_open: bool,
}

impl SelectField {
    pub fn new(label: impl Into<String>, options: Vec<String>, default_idx: usize) -> Self {
        let selected_index = if default_idx < options.len() {
            default_idx
        } else {
            0
        };
        Self {
            label: label.into(),
            options,
            selected_index,
            is_open: false,
        }
    }

    pub fn selected_value(&self) -> &str {
        self.options
            .get(self.selected_index)
            .map(|s| s.as_str())
            .unwrap_or("")
    }

    pub fn select_next(&mut self) {
        if !self.options.is_empty() {
            self.selected_index = (self.selected_index + 1) % self.options.len();
        }
    }

    pub fn select_prev(&mut self) {
        if !self.options.is_empty() {
            if self.selected_index == 0 {
                self.selected_index = self.options.len().saturating_sub(1);
            } else {
                self.selected_index -= 1;
            }
        }
    }
}

#[derive(Debug, Clone)]
pub enum FormField {
    Text(TextField),
    Checkbox(CheckboxField),
    Select(SelectField),
}

pub struct App {
    pub fields: Vec<FormField>,
    pub active_index: usize,
    pub submitted_data: Option<String>,
    pub error_message: Option<String>,
    pub should_quit: bool,
}

impl App {
    pub fn new() -> Self {
        let fields = vec![
            FormField::Text(TextField::new("Nom complet", "Ex: Jean Dupont")),
            FormField::Text(TextField::new("Email", "Ex: jean.dupont@example.com")),
            FormField::Select(SelectField::new(
                "Rôle",
                vec![
                    "Développeur Rust".into(),
                    "Architecte Logiciel".into(),
                    "DevOps / SRE".into(),
                    "Chef de Projet".into(),
                ],
                0,
            )),
            FormField::Checkbox(CheckboxField::new("Accepter les conditions d'utilisation", false)),
            FormField::Checkbox(CheckboxField::new("Recevoir la newsletter technique", true)),
        ];

        Self {
            fields,
            active_index: 0,
            submitted_data: None,
            error_message: None,
            should_quit: false,
        }
    }

    pub fn total_nav_targets(&self) -> usize {
        // champs + bouton de soumission
        self.fields.len() + 1
    }

    pub fn submit_button_index(&self) -> usize {
        self.fields.len()
    }

    pub fn next_field(&mut self) {
        let total = self.total_nav_targets();
        self.active_index = (self.active_index + 1) % total;
    }

    pub fn prev_field(&mut self) {
        let total = self.total_nav_targets();
        if self.active_index == 0 {
            self.active_index = total.saturating_sub(1);
        } else {
            self.active_index -= 1;
        }
    }

    pub fn submit(&mut self) {
        // Validation simple
        let mut name = String::new();
        let mut email = String::new();
        let mut role = String::new();
        let mut cgu_accepted = false;
        let mut newsletter = false;

        for field in &self.fields {
            match field {
                FormField::Text(tf) if tf.label == "Nom complet" => name = tf.value.trim().to_string(),
                FormField::Text(tf) if tf.label == "Email" => email = tf.value.trim().to_string(),
                FormField::Select(sf) => role = sf.selected_value().to_string(),
                FormField::Checkbox(cb) if cb.label.contains("conditions") => cgu_accepted = cb.checked,
                FormField::Checkbox(cb) if cb.label.contains("newsletter") => newsletter = cb.checked,
                _ => {}
            }
        }

        if name.is_empty() {
            self.error_message = Some("Le champ 'Nom complet' est requis.".to_string());
            self.submitted_data = None;
            return;
        }

        if email.is_empty() || !email.contains('@') {
            self.error_message = Some("Veuillez saisir une adresse email valide.".to_string());
            self.submitted_data = None;
            return;
        }

        if !cgu_accepted {
            self.error_message = Some("Vous devez accepter les conditions d'utilisation.".to_string());
            self.submitted_data = None;
            return;
        }

        self.error_message = None;
        self.submitted_data = Some(format!(
            "Nom: {}\nEmail: {}\nRôle: {}\nCGU: Oui\nNewsletter: {}",
            name,
            email,
            role,
            if newsletter { "Oui" } else { "Non" }
        ));
    }
}

fn handle_key_events(app: &mut App, key_code: KeyCode, modifiers: KeyModifiers) {
    // Si une liste déroulante est ouverte, elle capture la navigation
    if let Some(FormField::Select(select_field)) = app.fields.get_mut(app.active_index) {
        if select_field.is_open {
            match key_code {
                KeyCode::Up => select_field.select_prev(),
                KeyCode::Down => select_field.select_next(),
                KeyCode::Enter | KeyCode::Char(' ') | KeyCode::Esc => {
                    select_field.is_open = false;
                }
                _ => {}
            }
            return;
        }
    }

    match (key_code, modifiers) {
        (KeyCode::Esc, _) => app.should_quit = true,
        (KeyCode::Char('c'), KeyModifiers::CONTROL) => app.should_quit = true,
        (KeyCode::Tab, _) | (KeyCode::Down, _) => app.next_field(),
        (KeyCode::BackTab, _) | (KeyCode::Up, _) => app.prev_field(),
        _ => {
            if app.active_index == app.submit_button_index() {
                if key_code == KeyCode::Enter || key_code == KeyCode::Char(' ') {
                    app.submit();
                }
            } else if let Some(field) = app.fields.get_mut(app.active_index) {
                match field {
                    FormField::Text(tf) => match key_code {
                        KeyCode::Char(c) => tf.insert_char(c),
                        KeyCode::Backspace => tf.delete_prev_char(),
                        KeyCode::Left => tf.move_cursor_left(),
                        KeyCode::Right => tf.move_cursor_right(),
                        _ => {}
                    },
                    FormField::Checkbox(cb) => {
                        if key_code == KeyCode::Char(' ') || key_code == KeyCode::Enter {
                            cb.toggle();
                        }
                    }
                    FormField::Select(sf) => match key_code {
                        KeyCode::Enter | KeyCode::Char(' ') => sf.is_open = true,
                        KeyCode::Left => sf.select_prev(),
                        KeyCode::Right => sf.select_next(),
                        _ => {}
                    },
                }
            }
        }
    }
}

fn ui(f: &mut Frame, app: &mut App) {
