        .title(" Formulaire Multi-Champs Ratatui ")
        .title_alignment(Alignment::Center)
        .style(Style::default().fg(Color::Cyan));
    f.render_widget(main_block, size);

    let inner_area = Rect {
        x: size.x.saturating_add(2),
        y: size.y.saturating_add(1),
        width: size.width.saturating_sub(4),
        height: size.height.saturating_sub(2),
    };

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(1), // Titre ou info
            Constraint::Min(12),  // Zone du formulaire
            Constraint::Length(6), // Zone de résultat ou notification
            Constraint::Length(1), // Aide raccourcis
        ])
        .split(inner_area);

    // Titre / instructions
    let instructions = Paragraph::new("Naviguez avec Tab / Shift+Tab ou Flèches Haut/Bas. Espace/Entrée pour interagir.")
        .style(Style::default().fg(Color::DarkGray))
        .alignment(Alignment::Center);
    f.render_widget(instructions, chunks[0]);

    // Layout des champs de formulaire
    let form_constraints = vec![
        Constraint::Length(3), // Nom
        Constraint::Length(3), // Email
        Constraint::Length(3), // Rôle (Select)
        Constraint::Length(2), // Checkbox CGU
        Constraint::Length(2), // Checkbox Newsletter
        Constraint::Length(3), // Bouton Soumettre
    ];

    let form_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints(form_constraints)
        .split(chunks[1]);

    let mut select_popup_rect: Option<Rect> = None;
    let mut open_select_info: Option<(Vec<String>, usize)> = None;

    for (i, field) in app.fields.iter().enumerate() {
        let is_active = app.active_index == i;
        let border_color = if is_active { Color::Yellow } else { Color::White };
        let label_style = if is_active {
            Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(Color::White)
        };

        match field {
            FormField::Text(tf) => {
                let display_text = if tf.value.is_empty() {
                    Span::styled(&tf.placeholder, Style::default().fg(Color::DarkGray))
                } else {
                    Span::raw(&tf.value)
                };

                let p = Paragraph::new(display_text).block(
                    Block::default()
                        .borders(Borders::ALL)
                        .border_type(if is_active { BorderType::Thick } else { BorderType::Plain })
                        .border_style(Style::default().fg(border_color))
                        .title(Span::styled(format!(" {} ", tf.label), label_style)),
                );
                f.render_widget(p, form_chunks[i]);

                if is_active {
                    let cursor_x = form_chunks[i].x + 1 + tf.cursor_pos as u16;
                    let cursor_y = form_chunks[i].y + 1;
                    if cursor_x < form_chunks[i].x + form_chunks[i].width.saturating_sub(1) {
                        f.set_cursor_position((cursor_x, cursor_y));
                    }
                }
            }
            FormField::Checkbox(cb) => {
                let symbol = if cb.checked { "[X]" } else { "[ ]" };
                let symbol_style = if cb.checked {
                    Style::default().fg(Color::Green).add_modifier(Modifier::BOLD)
                } else {
                    Style::default().fg(Color::Gray)
                };

                let active_marker = if is_active { "► " } else { "  " };

                let content = Line::from(vec![
                    Span::styled(active_marker, Style::default().fg(Color::Yellow)),
                    Span::styled(symbol, symbol_style),
                    Span::raw(" "),
                    Span::styled(&cb.label, label_style),
                ]);

                let p = Paragraph::new(content);
                f.render_widget(p, form_chunks[i]);
            }
            FormField::Select(sf) => {
                let value_display = format!(" ▼ {} ", sf.selected_value());
                let p = Paragraph::new(value_display).block(
                    Block::default()
                        .borders(Borders::ALL)
                        .border_type(if is_active { BorderType::Thick } else { BorderType::Plain })
                        .border_style(Style::default().fg(border_color))
                        .title(Span::styled(format!(" {} ", sf.label), label_style)),
                );
                f.render_widget(p, form_chunks[i]);

                if sf.is_open {
                    select_popup_rect = Some(form_chunks[i]);
                    open_select_info = Some((sf.options.clone(), sf.selected_index));
                }
            }
        }
    }

    // Bouton de soumission
    let submit_idx = app.submit_button_index();
    let is_submit_active = app.active_index == submit_idx;
    let submit_style = if is_submit_active {
        Style::default()
            .fg(Color::Black)
            .bg(Color::Green)
            .add_modifier(Modifier::BOLD)
    } else {
        Style::default()
            .fg(Color::Green)
            .add_modifier(Modifier::BOLD)
    };

    let submit_btn = Paragraph::new(" [ SOUMETTRE LE FORMULAIRE ] ")
        .alignment(Alignment::Center)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .border_type(if is_submit_active { BorderType::Double } else { BorderType::Rounded })
                .border_style(Style::default().fg(if is_submit_active { Color::Green } else { Color::DarkGray })),
        )
        .style(submit_style);
    f.render_widget(submit_btn, form_chunks[submit_idx]);

    // Zone de retour (Erreur ou Succès)
    if let Some(err) = &app.error_message {
        let err_block = Paragraph::new(format!(" Erreur: {}", err))
            .style(Style::default().fg(Color::Red).add_modifier(Modifier::BOLD))
            .block(
                Block::default()
                    .borders(Borders::ALL)
                    .border_type(BorderType::Rounded)
                    .border_style(Style::default().fg(Color::Red))
                    .title(" Validation "),
            );
        f.render_widget(err_block, chunks[2]);
    } else if let Some(success) = &app.submitted_data {
        let success_block = Paragraph::new(format!(" Données soumises avec succès :\n{}", success))
            .style(Style::default().fg(Color::LightGreen))
            .block(
                Block::default()
                    .borders(Borders::ALL)
                    .border_type(BorderType::Rounded)
                    .border_style(Style::default().fg(Color::Green))
                    .title(" Succès "),
            );
        f.render_widget(success_block, chunks[2]);
    } else {
        let empty_feedback = Paragraph::new("Remplissez le formulaire et validez.")
            .style(Style::default().fg(Color::DarkGray))
            .alignment(Alignment::Center);
        f.render_widget(empty_feedback, chunks[2]);
    }

    // Bas de page / Raccourcis
    let help = Paragraph::new(" [Tab / Maj+Tab] Déplacer le focus  |  [Espace / Entrée] Sélectionner  |  [Échap] Quitter ")
        .style(Style::default().fg(Color::Gray))
        .alignment(Alignment::Center);
    f.render_widget(help, chunks[3]);

    // Rendu popup liste déroulante au premier plan si ouverte
    if let (Some(rect), Some((options, selected_idx))) = (select_popup_rect, open_select_info) {
        let popup_height = (options.len() as u16).saturating_add(2);
        let popup_area = Rect {
            x: rect.x + 2,
            y: rect.y + rect.height,
            width: rect.width.saturating_sub(4),
            height: popup_height.min(size.height.saturating_sub(rect.y + rect.height)),
        };

        f.render_widget(Clear, popup_area);

        let items: Vec<ListItem> = options
            .iter()
            .enumerate()
            .map(|(idx, opt)| {
                let style = if idx == selected_idx {
                    Style::default().fg(Color::Black).bg(Color::Yellow).add_modifier(Modifier::BOLD)
                } else {
                    Style::default().fg(Color::White)
                };
                ListItem::new(format!("  {}  ", opt)).style(style)
            })
            .collect();

        let list_widget = List::new(items).block(
            Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .border_style(Style::default().fg(Color::Yellow))
                .title(" Options "),
        );

        let mut list_state = ListState::default();
        list_state.select(Some(selected_idx));
        f.render_stateful_widget(list_widget, popup_area, &mut list_state);
    }
}

fn run_app(terminal: &mut Terminal<CrosstermBackend<Stdout>>, mut app: App) -> io::Result<()> {
    loop {
        terminal.draw(|f| ui(f, &mut app))?;

        if app.should_quit {
            break;
        }

        if event::poll(std::time::Duration::from_millis(50))? {
            if let Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press {
                    handle_key_events(&mut app, key.code, key.modifiers);
                }
            }
        }
    }
    Ok(())
}

fn main() -> io::Result<()> {
    enable_raw_mode()?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let app = App::new();
    let res = run_app(&mut terminal, app);

    // Restauration propre du terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    if let Err(err) = res {
        eprintln!("Erreur lors de l'exécution de l'application : {:?}", err);
    }

    Ok(())
}

