    // Rendu popup liste déroulante au premier plan si ouverte
    if let (Some(rect), Some((options, selected_idx))) = (select_popup_rect, open_select_info) {
        let popup_height = (options.len() as u16).saturating_add(2);
        let popup_area = Rect {
            x: rect.x + 2,
            y: rect.y + rect.height,
            width: rect.width.saturating_sub(4),
            height: popup_height.min(size.height.saturating_sub(rect.y + rect.height)),
        };

        f.render_widget(Clear, popup_area);

        let items: Vec<ListItem> = options
            .iter()
            .enumerate()
            .map(|(idx, opt)| {
                let style = if idx == selected_idx {
                    Style::default().fg(Color::Black).bg(Color::Yellow).add_modifier(Modifier::BOLD)
                } else {
                    Style::default().fg(Color::White)
                };
                ListItem::new(format!("  {}  ", opt)).style(style)
            })
            .collect();

        let list_widget = List::new(items).block(
            Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .border_style(Style::default().fg(Color::Yellow))
                .title(" Options "),
        );

        let mut list_state = ListState::default();
        list_state.select(Some(selected_idx));
        f.render_stateful_widget(list_widget, popup_area, &mut list_state);
    }
}

fn run_app(terminal: &mut Terminal<CrosstermBackend<Stdout>>, mut app: App) -> io::Result<()> {
    loop {
        terminal.draw(|f| ui(f, &mut app))?;

        if app.should_quit {
            break;
        }

        if event::poll(std::time::Duration::from_millis(50))? {
            if let Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press {
                    handle_key_events(&mut app, key.code, key.modifiers);
                }
            }
        }
    }
    Ok(())
}

fn main() -> io::Result<()> {
    enable_raw_mode()?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let app = App::new();
    let res = run_app(&mut terminal, app);

    // Restauration propre du terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    if let Err(err) = res {
        eprintln!("Erreur lors de l'exécution de l'application : {:?}", err);
    }

    Ok(())
}

