// src/main.rs
use std::collections::VecDeque;
use std::io;
use std::time::{Duration, Instant};

use chrono::Local;
use crossterm::{
    event::{Event, EventStream, KeyCode, KeyEventKind},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use futures::StreamExt;
use rand::Rng;
use ratatui::{
    backend::CrosstermBackend,
    layout::{Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, Gauge, List, ListItem, Paragraph},
    Frame, Terminal,
};
use tokio::sync::mpsc;

const MAX_LOGS: usize = 30;

#[derive(Debug, Clone)]
pub struct MessageTask {
    pub id: u64,
    pub task_type: &'static str,
    pub created_at: String,
}

#[derive(Debug)]
pub enum WorkerEvent {
    Incoming(MessageTask),
    Processed {
        id: u64,
        task_type: &'static str,
        duration_ms: u64,
        worker_id: usize,
    },
    Failed {
        id: u64,
        task_type: &'static str,
        reason: String,
        worker_id: usize,
    },
}

struct AppState {
    incoming_list: VecDeque<String>,
    processed_list: VecDeque<String>,
    error_list: VecDeque<String>,
    total_received: u64,
    total_processed: u64,
    total_failed: u64,
    is_paused: bool,
    start_time: Instant,
}

impl AppState {
    fn new() -> Self {
        Self {
            incoming_list: VecDeque::with_capacity(MAX_LOGS),
            processed_list: VecDeque::with_capacity(MAX_LOGS),
            error_list: VecDeque::with_capacity(MAX_LOGS),
            total_received: 0,
            total_processed: 0,
            total_failed: 0,
            is_paused: false,
            start_time: Instant::now(),
        }
    }

    fn push_bounded(deque: &mut VecDeque<String>, item: String) {
        if deque.len() >= MAX_LOGS {
            deque.pop_front();
        }
        deque.push_back(item);
    }

    fn record_incoming(&mut self, task: MessageTask) {
        self.total_received += 1;
        let line = format!("[{}] #{:04} - Type: {}", task.created_at, task.id, task.task_type);
        Self::push_bounded(&mut self.incoming_list, line);
    }

    fn record_processed(&mut self, id: u64, task_type: &'static str, duration_ms: u64, worker_id: usize) {
        self.total_processed += 1;
        let time = Local::now().format("%H:%M:%S").to_string();
        let line = format!(
            "[{}] #{:04} [{}] par Worker-{} en {}ms",
            time, id, task_type, worker_id, duration_ms
        );
        Self::push_bounded(&mut self.processed_list, line);
    }

    fn record_failure(&mut self, id: u64, task_type: &'static str, reason: String, worker_id: usize) {
        self.total_failed += 1;
        let time = Local::now().format("%H:%M:%S").to_string();
        let line = format!(
            "[{}] #{:04} [{}] Worker-{} -> {}",
            time, id, task_type, worker_id, reason
        );
        Self::push_bounded(&mut self.error_list, line);
    }

    fn clear_errors(&mut self) {
        self.error_list.clear();
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // 1. Initialisation des canaux de communication
    // Canal de distribution des tâches vers les workers
    let (task_tx, task_rx) = mpsc::channel::<MessageTask>(100);
    // Canal d'agrégation d'événements vers la boucle TUI
    let (event_tx, mut event_rx) = mpsc::channel::<WorkerEvent>(200);

    // 2. Lancement du producteur de tâches asynchrone
    let prod_event_tx = event_tx.clone();
    tokio::spawn(run_producer(task_tx, prod_event_tx));

    // 3. Lancement des workers asynchrones
    let shared_task_rx = std::sync::Arc::new(tokio::sync::Mutex::new(task_rx));
    const NUM_WORKERS: usize = 3;
    for worker_id in 1..=NUM_WORKERS {
        let rx = std::sync::Arc::clone(&shared_task_rx);
        let tx = event_tx.clone();
        tokio::spawn(run_worker(worker_id, rx, tx));
    }

    // 4. Initialisation du terminal TUI
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    // 5. Exécution sécurisée de l'application
    let app_result = run_app(&mut terminal, &mut event_rx).await;

    // 6. Nettoyage et restauration impérative du terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    if let Err(err) = app_result {
        eprintln!("Erreur lors de l'exécution : {err}");
    }

    Ok(())
}

async fn run_producer(
    task_tx: mpsc::Sender<MessageTask>,
    event_tx: mpsc::Sender<WorkerEvent>,
) {
    let mut task_id = 0u64;
    let task_types = ["DataSync", "ImageResize", "SendEmail", "PaymentAuth", "CleanupDB"];

    loop {
        let delay_ms = {
            let mut rng = rand::thread_rng();
            rng.gen_range(300..1200)
        };
        tokio::time::sleep(Duration::from_millis(delay_ms)).await;

        task_id += 1;
        let task_type = {
            let mut rng = rand::thread_rng();
            let idx = rng.gen_range(0..task_types.len());
            task_types[idx]
        };

        let task = MessageTask {
            id: task_id,
            task_type,
            created_at: Local::now().format("%H:%M:%S").to_string(),
        };

        let _ = event_tx.send(WorkerEvent::Incoming(task.clone())).await;

        if task_tx.send(task).await.is_err() {
            break;
        }
    }
}

async fn run_worker(
    worker_id: usize,
    task_rx: std::sync::Arc<tokio::sync::Mutex<mpsc::Receiver<MessageTask>>>,
    event_tx: mpsc::Sender<WorkerEvent>,
) {
    loop {
        let task = {
            let mut lock = task_rx.lock().await;
            lock.recv().await
        };

        match task {
            Some(t) => {
                let (duration_ms, is_error) = {
                    let mut rng = rand::thread_rng();
                    let dur = rng.gen_range(400..1800);
                    let err = rng.gen_bool(0.20);
                    (dur, err)
                };

                tokio::time::sleep(Duration::from_millis(duration_ms)).await;

                if is_error {
                    let reasons = [
                        "Timeout réseau",
                        "Connexion refusée",
                        "Charge CPU saturée",
                        "Format de payload invalide",
                    ];
                    let reason = {
                        let mut rng = rand::thread_rng();
                        let r_idx = rng.gen_range(0..reasons.len());
                        reasons[r_idx].to_string()
                    };

                    let _ = event_tx
                        .send(WorkerEvent::Failed {
                            id: t.id,
                            task_type: t.task_type,
                            reason,
                            worker_id,
                        })
                        .await;
                } else {
                    let _ = event_tx
                        .send(WorkerEvent::Processed {
                            id: t.id,
                            task_type: t.task_type,
                            duration_ms,
                            worker_id,
                        })
                        .await;
                }
            }
            None => break,
        }
    }
}

async fn run_app(
    terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
    event_rx: &mut mpsc::Receiver<WorkerEvent>,
) -> Result<(), Box<dyn std::error::Error>> {
    let mut state = AppState::new();
    let mut reader = EventStream::new();
    let mut tick_interval = tokio::time::interval(Duration::from_millis(100));

    loop {
        terminal.draw(|f| draw_ui(f, &state))?;

        tokio::select! {
            _ = tick_interval.tick() => {
                // Rafraîchissement régulier pour la dynamique du terminal
            }
            Some(event) = event_rx.recv() => {
                if !state.is_paused {
                    match event {
                        WorkerEvent::Incoming(task) => state.record_incoming(task),
                        WorkerEvent::Processed { id, task_type, duration_ms, worker_id } => {
                            state.record_processed(id, task_type, duration_ms, worker_id);
                        }
                        WorkerEvent::Failed { id, task_type, reason, worker_id } => {
                            state.record_failure(id, task_type, reason, worker_id);
                        }
                    }
                }
            }
            Some(crossterm_event) = reader.next() => {
                if let Ok(Event::Key(key)) = crossterm_event {
                    if key.kind == KeyEventKind::Press {
                        match key.code {
                            KeyCode::Char('q') | KeyCode::Esc => return Ok(()),
                            KeyCode::Char('p') => state.is_paused = !state.is_paused,
                            KeyCode::Char('c') => state.clear_errors(),
                            _ => {}
                        }
                    }
                }
            }
        }
    }
}

fn draw_ui(frame: &mut Frame, state: &AppState) {
    let main_chunks = Layout::default()
        .direction(Direction::Vertical)
        .margin(1)
        .constraints([
            Constraint::Length(3), // Titre & stats rapides
            Constraint::Length(3), // Barre de progression
            Constraint::Min(8),    // 3 Panneaux en colonnes
            Constraint::Length(3), // Footer raccourcis
        ])
        .split(frame.size());

    // 1. En-tête
    let elapsed = state.start_time.elapsed().as_secs();
    let status_str = if state.is_paused { "EN PAUSE" } else { "ACTIF" };
    let status_color = if state.is_paused { Color::Yellow } else { Color::Green };

    let header_text = vec![Line::from(vec![
        Span::styled("MONITEUR DE FILES ASYNCHRONES (Tokio + Ratatui)", Style::default().add_modifier(Modifier::BOLD)),
        Span::raw(" | État: "),
        Span::styled(status_str, Style::default().fg(status_color).add_modifier(Modifier::BOLD)),
        Span::raw(format!(" | Uptime: {}s | Total Entrants: {} | Succès: {} | Échecs: {}",
            elapsed, state.total_received, state.total_processed, state.total_failed)),
    ])];
    let header_widget = Paragraph::new(header_text).block(Block::default().borders(Borders::ALL).title(" Supervision "));
    frame.render_widget(header_widget, main_chunks[0]);

    // 2. Jauge de succès
    let total_handled = state.total_processed + state.total_failed;
    let ratio = if total_handled > 0 {
        state.total_processed as f64 / total_handled as f64
    } else {
        1.0
    };
    let success_percent = (ratio * 100.0) as u16;
    let gauge = Gauge::default()
        .block(Block::default().borders(Borders::ALL).title(" Taux de Succès des Traitements "))
        .gauge_style(Style::default().fg(Color::Cyan).bg(Color::DarkGray))
        .percent(success_percent)
        .label(format!("{}% traités avec succès ({} total terminés)", success_percent, total_handled));
    frame.render_widget(gauge, main_chunks[1]);

    // 3. Colonnes (Entrants, Traités, Erreurs)
    let column_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(33),
            Constraint::Percentage(34),
            Constraint::Percentage(33),
        ])
        .split(main_chunks[2]);

    render_incoming_panel(frame, state, column_chunks[0]);
    render_processed_panel(frame, state, column_chunks[1]);
    render_error_panel(frame, state, column_chunks[2]);

    // 4. Pied de page / Raccourcis
    let help_spans = Line::from(vec![
        Span::styled(" [q/Esc] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw("Quitter  "),
        Span::styled(" [p] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw("Pause/Reprise  "),
        Span::styled(" [c] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw("Effacer erreurs"),
    ]);
    let footer = Paragraph::new(help_spans).block(Block::default().borders(Borders::ALL).title(" Contrôles "));
    frame.render_widget(footer, main_chunks[3]);
}

fn render_incoming_panel(frame: &mut Frame, state: &AppState, area: Rect) {
    let items: Vec<ListItem> = state
        .incoming_list
        .iter()
        .rev()
        .map(|entry| ListItem::new(Span::styled(entry.as_str(), Style::default().fg(Color::Blue))))
        .collect();

    let list = List::new(items).block(
        Block::default()
            .borders(Borders::ALL)
            .title(format!(" Messages Entrants ({}) ", state.incoming_list.len())),
    );
    frame.render_widget(list, area);
}

fn render_processed_panel(frame: &mut Frame, state: &AppState, area: Rect) {
    let items: Vec<ListItem> = state
        .processed_list
        .iter()
        .rev()
        .map(|entry| ListItem::new(Span::styled(entry.as_str(), Style::default().fg(Color::Green))))
        .collect();

    let list = List::new(items).block(
        Block::default()
            .borders(Borders::ALL)
            .title(format!(" Traitements Réussis ({}) ", state.processed_list.len())),
    );
    frame.render_widget(list, area);
}

fn render_error_panel(frame: &mut Frame, state: &AppState, area: Rect) {
    let items: Vec<ListItem> = state
        .error_list
        .iter()
        .rev()
        .map(|entry| ListItem::new(Span::styled(entry.as_str(), Style::default().fg(Color::Red))))
        .collect();

    let list = List::new(items).block(
        Block::default()
            .borders(Borders::ALL)
            .title(format!(" Erreurs / Rejets ({}) ", state.error_list.len())),
    );
    frame.render_widget(list, area);
}

