                        .send(WorkerEvent::Failed {
                            id: t.id,
                            task_type: t.task_type,
                            reason,
                            worker_id,
                        })
                        .await;
                } else {
                    let _ = event_tx
                        .send(WorkerEvent::Processed {
                            id: t.id,
                            task_type: t.task_type,
                            duration_ms,
                            worker_id,
                        })
                        .await;
                }
            }
            None => break,
        }
    }
}

async fn run_app(
    terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
    event_rx: &mut mpsc::Receiver<WorkerEvent>,
) -> Result<(), Box<dyn std::error::Error>> {
    let mut state = AppState::new();
    let mut reader = EventStream::new();
    let mut tick_interval = tokio::time::interval(Duration::from_millis(100));

    loop {
        terminal.draw(|f| draw_ui(f, &state))?;

        tokio::select! {
            _ = tick_interval.tick() => {
                // Rafraîchissement régulier pour la dynamique du terminal
            }
            Some(event) = event_rx.recv() => {
                if !state.is_paused {
                    match event {
                        WorkerEvent::Incoming(task) => state.record_incoming(task),
                        WorkerEvent::Processed { id, task_type, duration_ms, worker_id } => {
                            state.record_processed(id, task_type, duration_ms, worker_id);
                        }
                        WorkerEvent::Failed { id, task_type, reason, worker_id } => {
                            state.record_failure(id, task_type, reason, worker_id);
                        }
                    }
                }
            }
            Some(crossterm_event) = reader.next() => {
                if let Ok(Event::Key(key)) = crossterm_event {
                    if key.kind == KeyEventKind::Press {
                        match key.code {
                            KeyCode::Char('q') | KeyCode::Esc => return Ok(()),
                            KeyCode::Char('p') => state.is_paused = !state.is_paused,
                            KeyCode::Char('c') => state.clear_errors(),
                            _ => {}
                        }
                    }
                }
            }
        }
    }
}

fn draw_ui(frame: &mut Frame, state: &AppState) {
    let main_chunks = Layout::default()
        .direction(Direction::Vertical)
        .margin(1)
        .constraints([
            Constraint::Length(3), // Titre & stats rapides
            Constraint::Length(3), // Barre de progression
            Constraint::Min(8),    // 3 Panneaux en colonnes
            Constraint::Length(3), // Footer raccourcis
        ])
        .split(frame.size());

    // 1. En-tête
    let elapsed = state.start_time.elapsed().as_secs();
    let status_str = if state.is_paused { "EN PAUSE" } else { "ACTIF" };
    let status_color = if state.is_paused { Color::Yellow } else { Color::Green };

    let header_text = vec![Line::from(vec![
        Span::styled("MONITEUR DE FILES ASYNCHRONES (Tokio + Ratatui)", Style::default().add_modifier(Modifier::BOLD)),
        Span::raw(" | État: "),
        Span::styled(status_str, Style::default().fg(status_color).add_modifier(Modifier::BOLD)),
        Span::raw(format!(" | Uptime: {}s | Total Entrants: {} | Succès: {} | Échecs: {}",
            elapsed, state.total_received, state.total_processed, state.total_failed)),
    ])];
    let header_widget = Paragraph::new(header_text).block(Block::default().borders(Borders::ALL).title(" Supervision "));
    frame.render_widget(header_widget, main_chunks[0]);

    // 2. Jauge de succès
    let total_handled = state.total_processed + state.total_failed;
    let ratio = if total_handled > 0 {
        state.total_processed as f64 / total_handled as f64
    } else {
        1.0
    };
    let success_percent = (ratio * 100.0) as u16;
    let gauge = Gauge::default()
        .block(Block::default().borders(Borders::ALL).title(" Taux de Succès des Traitements "))
        .gauge_style(Style::default().fg(Color::Cyan).bg(Color::DarkGray))
        .percent(success_percent)
        .label(format!("{}% traités avec succès ({} total terminés)", success_percent, total_handled));
    frame.render_widget(gauge, main_chunks[1]);

    // 3. Colonnes (Entrants, Traités, Erreurs)
    let column_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(33),
            Constraint::Percentage(34),
            Constraint::Percentage(33),
        ])
        .split(main_chunks[2]);

    render_incoming_panel(frame, state, column_chunks[0]);
    render_processed_panel(frame, state, column_chunks[1]);
    render_error_panel(frame, state, column_chunks[2]);

    // 4. Pied de page / Raccourcis
    let help_spans = Line::from(vec![
        Span::styled(" [q/Esc] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw("Quitter  "),
        Span::styled(" [p] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw("Pause/Reprise  "),
        Span::styled(" [c] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw("Effacer erreurs"),
    ]);
    let footer = Paragraph::new(help_spans).block(Block::default().borders(Borders::ALL).title(" Contrôles "));
    frame.render_widget(footer, main_chunks[3]);
}

fn render_incoming_panel(frame: &mut Frame, state: &AppState, area: Rect) {
    let items: Vec<ListItem> = state
        .incoming_list
        .iter()
        .rev()
        .map(|entry| ListItem::new(Span::styled(entry.as_str(), Style::default().fg(Color::Blue))))
        .collect();

    let list = List::new(items).block(
        Block::default()
            .borders(Borders::ALL)
            .title(format!(" Messages Entrants ({}) ", state.incoming_list.len())),
    );
    frame.render_widget(list, area);
}

fn render_processed_panel(frame: &mut Frame, state: &AppState, area: Rect) {
    let items: Vec<ListItem> = state
        .processed_list
        .iter()
        .rev()
        .map(|entry| ListItem::new(Span::styled(entry.as_str(), Style::default().fg(Color::Green))))
        .collect();

    let list = List::new(items).block(
        Block::default()
            .borders(Borders::ALL)
            .title(format!(" Traitements Réussis ({}) ", state.processed_list.len())),
    );
    frame.render_widget(list, area);
}

fn render_error_panel(frame: &mut Frame, state: &AppState, area: Rect) {
    let items: Vec<ListItem> = state
        .error_list
        .iter()
        .rev()
        .map(|entry| ListItem::new(Span::styled(entry.as_str(), Style::default().fg(Color::Red))))
        .collect();

    let list = List::new(items).block(
        Block::default()
            .borders(Borders::ALL)
            .title(format!(" Erreurs / Rejets ({}) ", state.error_list.len())),
    );
    frame.render_widget(list, area);
}

