fn ui(f: &mut Frame, app: &App) {
    let total_area = f.area();

    let main_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // Titre & Barre supérieure
            Constraint::Min(10),   // Contenu principal
            Constraint::Length(3), // Footer d'aide et raccourcis
        ])
        .split(total_area);

    // 1. Barre d'en-tête
    render_header(f, app, main_chunks[0]);

    // 2. Division horizontale : Colonne des Villes + Panneau Météo
    let content_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Length(28), // Liste des villes
            Constraint::Min(40),    // Météo Actuelle + Prévisions
        ])
        .split(main_chunks[1]);

    render_city_list(f, app, content_chunks[0]);
    render_weather_panel(f, app, content_chunks[1]);

    // 3. Pied de page
    render_footer(f, main_chunks[2]);
}

fn render_header(f: &mut Frame, app: &App, area: Rect) {
    let status_badge = match &app.status {
        FetchStatus::Loading => Span::styled(" [⟳ Synchronisation...] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        FetchStatus::Success(_) => Span::styled(" [✓ Connecté à Open-Meteo] ", Style::default().fg(Color::Green)),
        FetchStatus::Error(_) => Span::styled(" [✕ Hors ligne / Erreur] ", Style::default().fg(Color::Red).add_modifier(Modifier::BOLD)),
        FetchStatus::Idle => Span::styled(" [Attente] ", Style::default().fg(Color::DarkGray)),
    };

    let title_line = Line::from(vec![
        Span::styled(" ⛅ TABLEAU DE BORD MÉTÉO ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
        Span::raw("─ "),
        Span::styled(format!("{} ({})", app.selected_city().name, app.selected_city().country), Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
        Span::raw(" "),
        status_badge,
    ]);

    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(Style::default().fg(Color::Blue));

    let paragraph = Paragraph::new(title_line)
        .alignment(Alignment::Left)
        .block(block);

    f.render_widget(paragraph, area);
}

fn render_city_list(f: &mut Frame, app: &App, area: Rect) {
    let block = Block::default()
        .title(" 📍 Villes (↑/↓) ")
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(Style::default().fg(Color::White));

    let mut rows = Vec::new();
    for (i, city) in app.cities.iter().enumerate() {
        let is_selected = i == app.selected_city_idx;
        let style = if is_selected {
            Style::default()
                .fg(Color::Black)
                .bg(Color::Cyan)
                .add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(Color::Gray)
        };

        let pointer = if is_selected { "▶ " } else { "  " };
        let city_label = format!("{}{:<14}", pointer, city.name);
        rows.push(Row::new(vec![
            Cell::from(city_label),
            Cell::from(city.country),
        ]).style(style));
    }

    let widths = [Constraint::Percentage(60), Constraint::Percentage(40)];
    let table = Table::new(rows, widths)
        .block(block)
        .column_spacing(1);

    f.render_widget(table, area);
}

fn render_weather_panel(f: &mut Frame, app: &App, area: Rect) {
    let weather_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(12), // Conditions Actuelles & Art ASCII
            Constraint::Min(8),     // Prévisions à 7 jours & Histogramme
        ])
        .split(area);

    match &app.status {
        FetchStatus::Loading => {
            let block = Block::default()
                .title(" Conditions Météo ")
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded);
            let loading_text = Paragraph::new("\n\n Chargement des données météorologiques en cours...")
                .alignment(Alignment::Center)
                .style(Style::default().fg(Color::Yellow))
                .block(block);
            f.render_widget(loading_text, area);
        }
        FetchStatus::Error(err_msg) => {
            let block = Block::default()
                .title(" Erreur ")
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .border_style(Style::default().fg(Color::Red));
            let error_text = Paragraph::new(format!(
                "\n\n Impossible de contacter le service météo :\n {}\n\n Appuyez sur [R] pour relancer la requête.",
                err_msg
            ))
            .alignment(Alignment::Center)
            .style(Style::default().fg(Color::LightRed))
            .wrap(Wrap { trim: true })
            .block(block);
            f.render_widget(error_text, area);
        }
        FetchStatus::Success(data) => {
            render_current_weather(f, data, weather_chunks[0]);
            render_forecast(f, data, weather_chunks[1]);
        }
        FetchStatus::Idle => {
            let block = Block::default().borders(Borders::ALL).border_type(BorderType::Rounded);
            let empty_text = Paragraph::new("Aucune donnée disponible. Appuyez sur [R] pour actualiser.")
                .alignment(Alignment::Center)
                .block(block);
            f.render_widget(empty_text, area);
        }
    }
}

fn render_current_weather(f: &mut Frame, data: &WeatherApiResponse, area: Rect) {
    let current_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Length(22), // Icône ASCII
            Constraint::Min(20),    // Indicateurs météo chiffrés
        ])
        .split(area);

    let art = get_weather_art(data.current.weather_code);

    // Bloc Icône ASCII
    let mut ascii_lines = Vec::new();
    ascii_lines.push(Line::raw(""));
    for line in art.ascii {
        ascii_lines.push(Line::from(Span::styled(
            *line,
            Style::default().fg(art.color).add_modifier(Modifier::BOLD),
        )));
    }

    let ascii_block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(Style::default().fg(art.color))
        .title(" Illustration ");
    let ascii_paragraph = Paragraph::new(ascii_lines)
        .alignment(Alignment::Center)
        .block(ascii_block);
    f.render_widget(ascii_paragraph, current_chunks[0]);

    // Bloc Métriques Actuelles
    let metrics_block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(Style::default().fg(Color::Cyan))
        .title(" Conditions Actuelles ");

    let temp_str = format!("{:.1}{}", data.current.temperature_2m, data.current_units.temperature_2m);
    let humidity_str = format!("{}{}", data.current.relative_humidity_2m, data.current_units.relative_humidity_2m);
    let wind_str = format!("{:.1} {}", data.current.wind_speed_10m, data.current_units.wind_speed_10m);

    let text = vec![
        Line::from(vec![
            Span::styled(" État du ciel    : ", Style::default().fg(Color::DarkGray)),
            Span::styled(art.condition, Style::default().fg(art.color).add_modifier(Modifier::BOLD)),
        ]),
        Line::from(vec![
            Span::styled(" Température     : ", Style::default().fg(Color::DarkGray)),
            Span::styled(temp_str, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        ]),
        Line::from(vec![
            Span::styled(" Humidité de l'air: ", Style::default().fg(Color::DarkGray)),
            Span::styled(humidity_str, Style::default().fg(Color::LightBlue)),
        ]),
        Line::from(vec![
            Span::styled(" Vitesse du vent : ", Style::default().fg(Color::DarkGray)),
            Span::styled(wind_str, Style::default().fg(Color::Green)),
        ]),
        Line::from(vec![
            Span::styled(" Relevé à        : ", Style::default().fg(Color::DarkGray)),
            Span::styled(&data.current.time, Style::default().fg(Color::White)),
        ]),
    ];

    let metrics_paragraph = Paragraph::new(text)
        .block(metrics_block)
        .wrap(Wrap { trim: false });
    f.render_widget(metrics_paragraph, current_chunks[1]);
}

fn render_forecast(f: &mut Frame, data: &WeatherApiResponse, area: Rect) {
    let forecast_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(55), // Tableau des prévisions
            Constraint::Percentage(45), // Histogramme des températures max
        ])
        .split(area);

    // Tableau des prévisions journalières
    let table_block = Block::default()
        .title(" Prévisions à 7 Jours ")
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(Style::default().fg(Color::White));

    let header_cells = ["Jour", "Météo", "Min", "Max", "Pluie"]
        .iter()
        .map(|h| Cell::from(*h).style(Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)));
    let header = Row::new(header_cells).height(1).bottom_margin(1);

    let mut rows = Vec::new();
    let count = data.daily.time.len().min(7);
    for i in 0..count {
        let date_str = &data.daily.time[i];
        let short_date = if date_str.len() >= 5 {
            &date_str[5..]
        } else {
            date_str.as_str()
        };

        let wcode = data.daily.weather_code.get(i).copied().unwrap_or(0);
        let art = get_weather_art(wcode);
        let tmin = data.daily.temperature_2m_min.get(i).copied().unwrap_or(0.0);
        let tmax = data.daily.temperature_2m_max.get(i).copied().unwrap_or(0.0);
        let precip = data
            .daily
            .precipitation_probability_max
            .as_ref()
            .and_then(|p| p.get(i))
            .copied()
            .unwrap_or(0);

        let row = Row::new(vec![
            Cell::from(short_date),
            Cell::from(art.icon_compact).style(Style::default().fg(art.color)),
            Cell::from(format!("{:.1}°C", tmin)).style(Style::default().fg(Color::Blue)),
            Cell::from(format!("{:.1}°C", tmax)).style(Style::default().fg(Color::Red)),
            Cell::from(format!("{}%", precip)).style(Style::default().fg(Color::Cyan)),
        ]);
        rows.push(row);
    }

    let widths = [
        Constraint::Length(7),
        Constraint::Length(16),
        Constraint::Length(9),
        Constraint::Length(9),
        Constraint::Length(7),
    ];
    let table = Table::new(rows, widths)
        .header(header)
        .block(table_block)
        .column_spacing(1);

    f.render_widget(table, forecast_chunks[0]);

    // Graphique BarChart des températures maximales
    let chart_block = Block::default()
        .title(" Températures Maximales (°C) ")
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(Style::default().fg(Color::White));

    let mut bars = Vec::new();
    for i in 0..count {
        let date_str = &data.daily.time[i];
        let label = if date_str.len() >= 5 {
            &date_str[5..]
        } else {
            date_str.as_str()
        };
        let tmax = data.daily.temperature_2m_max.get(i).copied().unwrap_or(0.0);
        // BarChart attend des valeurs positives u64
        let value = (tmax.max(0.0)).round() as u64;

        bars.push(
            Bar::default()
                .value(value)
                .label(Line::from(label))
                .text_value(format!("{}°", value))
                .style(Style::default().fg(if value >= 25 {
                    Color::Red
                } else if value >= 15 {
                    Color::Yellow
                } else {
                    Color::Cyan
                })),
        );
    }

    let barchart = BarChart::default()
        .block(chart_block)
        .data(BarGroup::default().bars(&bars))
        .bar_width(5)
        .bar_gap(1)
        .bar_style(Style::default().fg(Color::Green))
        .value_style(Style::default().fg(Color::White).add_modifier(Modifier::BOLD));

    f.render_widget(barchart, forecast_chunks[1]);
}

fn render_footer(f: &mut Frame, area: Rect) {
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(Style::default().fg(Color::DarkGray));

    let shortcuts = Line::from(vec![
        Span::styled(" [↑/↓] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
        Span::raw("Changer de ville  "),
        Span::styled(" [Entrée / R] ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
        Span::raw("Rafraîchir les données  "),
        Span::styled(" [Q / Esc] ", Style::default().fg(Color::Red).add_modifier(Modifier::BOLD)),
        Span::raw("Quitter"),
    ]);

    let paragraph = Paragraph::new(shortcuts)
        .alignment(Alignment::Center)
        .block(block);

    f.render_widget(paragraph, area);
}

// ============================================================================
// BOUCLE PRINCIPALE & INITIALISATION DU TERMINAL
// ============================================================================

enum AppEvent {
    Input(event::KeyEvent),
    WeatherLoaded(Result<WeatherApiResponse, String>),
    Tick,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Configuration du terminal en mode brut
    enable_raw_mode()?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    // Mise en place du canal d'événements
    let (tx, mut rx) = mpsc::channel::<AppEvent>(32);

    // Tâche d'écoute des entrées clavier
    let tx_keys = tx.clone();
    tokio::spawn(async move {
        loop {
            // Lecture non-bloquante avec timeout court
            if event::poll(Duration::from_millis(50)).unwrap_or(false) {
                if let Ok(Event::Key(key)) = event::read() {
                    if key.kind == KeyEventKind::Press {
                        if tx_keys.send(AppEvent::Input(key)).await.is_err() {
                            break;
                        }
                    }
                }
            } else {
                if tx_keys.send(AppEvent::Tick).await.is_err() {
                    break;
                }
            }
        }
    });

    let mut app = App::new();

    // Première requête de chargement au lancement
    app.status = FetchStatus::Loading;
    let initial_city = app.selected_city().clone();
    let tx_fetch = tx.clone();
    tokio::spawn(async move {
        let res = fetch_weather(&initial_city).await.map_err(|e| e.to_string());
        let _ = tx_fetch.send(AppEvent::WeatherLoaded(res)).await;
    });

    // Boucle de rendu et traitement des événements
    let run_result = run_app(&mut terminal, &mut app, &mut rx, tx.clone()).await;

    // Restauration garantie de l'état du terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    if let Err(err) = run_result {
        eprintln!("Erreur lors de l'exécution de l'application : {:?}", err);
    }

    Ok(())
}

async fn run_app<B: Backend>(
    terminal: &mut Terminal<B>,
    app: &mut App,
    rx: &mut mpsc::Receiver<AppEvent>,
    tx: mpsc::Sender<AppEvent>,
) -> io::Result<()> {
    while !app.should_quit {
        terminal.draw(|f| ui(f, app))?;

        if let Some(event) = rx.recv().await {
            match event {
                AppEvent::Input(key) => match key.code {
                    KeyCode::Char('q') | KeyCode::Char('Q') | KeyCode::Esc => {
                        app.should_quit = true;
                    }
                    KeyCode::Up => {
                        app.previous_city();
                        trigger_fetch(app, tx.clone());
                    }
                    KeyCode::Down => {
                        app.next_city();
                        trigger_fetch(app, tx.clone());
                    }
                    KeyCode::Enter | KeyCode::Char('r') | KeyCode::Char('R') => {
                        trigger_fetch(app, tx.clone());
                    }
                    _ => {}
                },
                AppEvent::WeatherLoaded(res) => {
                    app.status = match res {
                        Ok(data) => FetchStatus::Success(data),
                        Err(err) => FetchStatus::Error(err),
                    };
                }
                AppEvent::Tick => {
                    // Tick de rafraîchissement d'affichage
                }
            }
        }
    }

    Ok(())
}

fn trigger_fetch(app: &mut App, tx: mpsc::Sender<AppEvent>) {
    app.status = FetchStatus::Loading;
    let city = app.selected_city().clone();
    tokio::spawn(async move {
        let res = fetch_weather(&city).await.map_err(|e| e.to_string());
        let _ = tx.send(AppEvent::WeatherLoaded(res)).await;
    });
}

