pub enum FetchStatus {
    Idle,
    Loading,
    Success(WeatherApiResponse),
    Error(String),
}

pub struct App {
    pub cities: Vec<City>,
    pub selected_city_idx: usize,
    pub status: FetchStatus,
    pub should_quit: bool,
}

impl App {
    pub fn new() -> Self {
        Self {
            cities: CITIES.to_vec(),
            selected_city_idx: 0,
            status: FetchStatus::Idle,
            should_quit: false,
        }
    }

    pub fn selected_city(&self) -> &City {
        &self.cities[self.selected_city_idx]
    }

    pub fn next_city(&mut self) {
        if self.selected_city_idx + 1 < self.cities.len() {
            self.selected_city_idx += 1;
        } else {
            self.selected_city_idx = 0;
        }
    }

    pub fn previous_city(&mut self) {
        if self.selected_city_idx > 0 {
            self.selected_city_idx -= 1;
        } else {
            self.selected_city_idx = self.cities.len().saturating_sub(1);
        }
    }
}

