pub async fn fetch_weather(city: &City) -> Result<WeatherApiResponse, AppError> {
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(8))
        .build()?;

    let url = format!(
        "https://api.open-meteo.com/v1/forecast?latitude={}&longitude={}&current=temperature_2m,relative_humidity_2m,weather_code,wind_speed_10m&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max&timezone=auto",
        city.latitude, city.longitude
    );

    let res = client
        .get(&url)
        .header("User-Agent", "RatatuiWeatherApp/0.1.0")
        .send()
        .await?
        .error_for_status()?
        .json::<WeatherApiResponse>()
        .await?;

    Ok(res)
}

