// ============================================================================
// BOUCLE PRINCIPALE & INITIALISATION DU TERMINAL
// ============================================================================

enum AppEvent {
    Input(event::KeyEvent),
    WeatherLoaded(Result<WeatherApiResponse, String>),
    Tick,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Configuration du terminal en mode brut
    enable_raw_mode()?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    // Mise en place du canal d'événements
    let (tx, mut rx) = mpsc::channel::<AppEvent>(32);

    // Tâche d'écoute des entrées clavier
    let tx_keys = tx.clone();
    tokio::spawn(async move {
        loop {
            // Lecture non-bloquante avec timeout court
            if event::poll(Duration::from_millis(50)).unwrap_or(false) {
                if let Ok(Event::Key(key)) = event::read() {
                    if key.kind == KeyEventKind::Press {
                        if tx_keys.send(AppEvent::Input(key)).await.is_err() {
                            break;
                        }
                    }
                }
            } else {
                if tx_keys.send(AppEvent::Tick).await.is_err() {
                    break;
                }
            }
        }
    });

    let mut app = App::new();

    // Première requête de chargement au lancement
    app.status = FetchStatus::Loading;
    let initial_city = app.selected_city().clone();
    let tx_fetch = tx.clone();
    tokio::spawn(async move {
        let res = fetch_weather(&initial_city).await.map_err(|e| e.to_string());
        let _ = tx_fetch.send(AppEvent::WeatherLoaded(res)).await;
    });

    // Boucle de rendu et traitement des événements
    let run_result = run_app(&mut terminal, &mut app, &mut rx, tx.clone()).await;

    // Restauration garantie de l'état du terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    if let Err(err) = run_result {
        eprintln!("Erreur lors de l'exécution de l'application : {:?}", err);
    }

    Ok(())
}

async fn run_app<B: Backend>(
    terminal: &mut Terminal<B>,
    app: &mut App,
    rx: &mut mpsc::Receiver<AppEvent>,
    tx: mpsc::Sender<AppEvent>,
) -> io::Result<()> {
    while !app.should_quit {
        terminal.draw(|f| ui(f, app))?;

        if let Some(event) = rx.recv().await {
            match event {
                AppEvent::Input(key) => match key.code {
                    KeyCode::Char('q') | KeyCode::Char('Q') | KeyCode::Esc => {
                        app.should_quit = true;
                    }
                    KeyCode::Up => {
                        app.previous_city();
                        trigger_fetch(app, tx.clone());
                    }
                    KeyCode::Down => {
                        app.next_city();
                        trigger_fetch(app, tx.clone());
                    }
                    KeyCode::Enter | KeyCode::Char('r') | KeyCode::Char('R') => {
                        trigger_fetch(app, tx.clone());
                    }
                    _ => {}
                },
                AppEvent::WeatherLoaded(res) => {
                    app.status = match res {
                        Ok(data) => FetchStatus::Success(data),
                        Err(err) => FetchStatus::Error(err),
                    };
                }
                AppEvent::Tick => {
                    // Tick de rafraîchissement d'affichage
                }
            }
        }
    }

    Ok(())
}

fn trigger_fetch(app: &mut App, tx: mpsc::Sender<AppEvent>) {
    app.status = FetchStatus::Loading;
    let city = app.selected_city().clone();
    tokio::spawn(async move {
        let res = fetch_weather(&city).await.map_err(|e| e.to_string());
        let _ = tx.send(AppEvent::WeatherLoaded(res)).await;
    });
}

