/// Interface CLI avec Clap
#[derive(Parser, Debug)]
#[command(name = "gantt-terminal")]
#[command(author = "Damien")]
#[command(version = "0.1.0")]
#[command(about = "Visualiseur de diagrammes de Gantt interactif et exportable dans le terminal", long_about = None)]
struct Cli {
    /// Chemin optionnel vers le fichier de projet JSON
    #[arg(short, long, value_name = "FILE")]
    file: Option<PathBuf>,

    #[command(subcommand)]
    command: Option<Commands>,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Affiche le diagramme directement en format texte ASCII sur stdout
    Print {
        #[arg(short, long, default_value_t = 60)]
        width: usize,
    },
    /// Génère un exemple de projet JSON complet
    Init {
        #[arg(short, long, default_value = "project.json")]
        output: PathBuf,
    },
}

/// État de l'interface utilisateur interactive
struct AppState {
    project: Project,
    selected_task_index: usize,
    scroll_day_offset: i64,
    cell_width: u16,
    show_details: bool,
    critical_path: HashSet<String>,
}

impl AppState {
    fn new(project: Project) -> Self {
        let critical_path = project.compute_critical_path();
        Self {
            project,
            selected_task_index: 0,
            scroll_day_offset: 0,
            cell_width: 3,
            show_details: true,
            critical_path,
        }
    }

    fn select_previous(&mut self) {
        if self.selected_task_index > 0 {
            self.selected_task_index -= 1;
        }
    }

    fn select_next(&mut self) {
        if !self.project.tasks.is_empty()
            && self.selected_task_index + 1 < self.project.tasks.len()
        {
            self.selected_task_index += 1;
        }
    }

    fn scroll_left(&mut self) {
        self.scroll_day_offset -= 2;
    }

    fn scroll_right(&mut self) {
        self.scroll_day_offset += 2;
    }

    fn reset_scroll(&mut self) {
        self.scroll_day_offset = 0;
    }

    fn zoom_in(&mut self) {
        if self.cell_width < 6 {
            self.cell_width += 1;
        }
    }

    fn zoom_out(&mut self) {
        if self.cell_width > 2 {
            self.cell_width -= 1;
        }
    }

    fn toggle_details(&mut self) {
        self.show_details = !self.show_details;
    }
}

fn load_or_create_project(file_opt: Option<&Path>) -> Result<Project> {
    if let Some(path) = file_opt {
        if path.exists() {
            let file = File::open(path)
                .with_context(|| format!("Impossible d'ouvrir le fichier {}", path.display()))?;
            let reader = BufReader::new(file);
            let project: Project = serde_json::from_reader(reader)
                .with_context(|| format!("Format JSON invalide dans {}", path.display()))?;
            return Ok(project);
        }
    }
    Ok(Project::demo())
}

/// Affichage ASCII en sortie standard pour scripts et documentation
fn render_ascii_print(project: &Project, width: usize) {
    println!("\n=== DIAGRAMME DE GANTT : {} ===", project.name);
    let min_d = project.min_date();
    let max_d = project.max_date();
    let total_span = (max_d - min_d).num_days().max(1);

    let max_name_len = project
        .tasks
        .iter()
        .map(|t| t.name.len())
        .max()
        .unwrap_or(15)
        .min(25);

    let timeline_width = width.saturating_sub(max_name_len + 25).max(20);

    println!(
        "{:<max_name_len$} | {:^8} | {:^8} | {:^4} | Timeline",
        "Tâche", "Début", "Fin", "Prog"
    );
    println!("{}-+-{}-+-{}-+-{}-+-{}",
        "-".repeat(max_name_len),
        "-".repeat(8),
        "-".repeat(8),
        "-".repeat(4),
        "-".repeat(timeline_width)
    );

    for task in &project.tasks {
        let offset = (task.start - min_d).num_days().max(0);
        let duration = (task.end - task.start).num_days().max(0) + 1;

        let col_start = ((offset as f64 / total_span as f64) * timeline_width as f64).round() as usize;
        let col_span = (((duration as f64 / total_span as f64) * timeline_width as f64).round() as usize).max(1);

        let mut bar = vec![' '; timeline_width];
        for i in 0..col_span {
            let idx = col_start + i;
            if idx < timeline_width {
                let progress_idx = (col_span as f64 * (task.progress as f64 / 100.0)).round() as usize;
                bar[idx] = if i < progress_idx { '█' } else { '░' };
            }
        }

        let bar_str: String = bar.into_iter().collect();
        let truncated_name = if task.name.len() > max_name_len {
            format!("{}…", &task.name[..max_name_len.saturating_sub(1)])
        } else {
            task.name.clone()
        };

        println!(
            "{:<max_name_len$} | {} | {} | {:>3}% | |{}|",
            truncated_name,
            task.start.format("%d/%m"),
            task.end.format("%d/%m"),
            task.progress,
            bar_str
        );
    }
    println!("\nPériode : {} -> {} ({} jours totaux)\n", min_d, max_d, total_span + 1);
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match &cli.command {
        Some(Commands::Init { output }) => {
            let demo_proj = Project::demo();
            let file = File::create(output)
                .with_context(|| format!("Impossible de créer le fichier {}", output.display()))?;
            serde_json::to_writer_pretty(file, &demo_proj)
                .with_context(|| "Erreur lors de la sérialisation du projet")?;
            println!("Projet d'exemple initialisé avec succès : {}", output.display());
            return Ok(());
        }
        Some(Commands::Print { width }) => {
            let project = load_or_create_project(cli.file.as_deref())?;
            render_ascii_print(&project, *width);
            return Ok(());
        }
        None => {}
    }

    let project = load_or_create_project(cli.file.as_deref())?;
    run_tui(project)
}

fn run_tui(project: Project) -> Result<()> {
    enable_raw_mode().context("Impossible d'activer le mode brut du terminal")?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen).context("Impossible de passer en écran alternatif")?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend).context("Impossible d'initialiser le terminal")?;

    let mut state = AppState::new(project);
    let res = main_loop(&mut terminal, &mut state);

    // Nettoyage terminal
    disable_raw_mode().ok();
    execute!(terminal.backend_mut(), LeaveAlternateScreen).ok();
    terminal.show_cursor().ok();

    res
}

fn main_loop<B: ratatui::backend::Backend>(
    terminal: &mut Terminal<B>,
    state: &mut AppState,
) -> Result<()> {
    loop {
        terminal.draw(|f| ui_draw(f, state))?;

        if event::poll(Duration::from_millis(150))? {
            if let Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press {
                    match key.code {
                        KeyCode::Char('q') | KeyCode::Esc => return Ok(()),
                        KeyCode::Up | KeyCode::Char('k') => state.select_previous(),
                        KeyCode::Down | KeyCode::Char('j') => state.select_next(),
                        KeyCode::Left | KeyCode::Char('h') => state.scroll_left(),
                        KeyCode::Right | KeyCode::Char('l') => state.scroll_right(),
                        KeyCode::Char('+') | KeyCode::Char('=') => state.zoom_in(),
                        KeyCode::Char('-') => state.zoom_out(),
                        KeyCode::Char('t') => state.reset_scroll(),
                        KeyCode::Tab => state.toggle_details(),
                        _ => {}
                    }
                }
            }
        }
    }
}

fn category_color(cat: Option<&str>) -> Color {
    match cat {
        Some("Design") => Color::Cyan,
        Some("Backend") => Color::LightBlue,
        Some("Frontend") => Color::Green,
        Some("QA") => Color::Yellow,
        Some("DevOps") => Color::Magenta,
        _ => Color::White,
    }
}

fn ui_draw(f: &mut Frame, state: &AppState) {
    let size = f.area();

    // Fond principal
    let main_block = Block::default()
        .borders(Borders::ALL)
        .title(format!(" Diagramme de Gantt - {} (q: Quitter, +/-: Zoom, h/j/k/l: Navigation, Tab: Détails) ", state.project.name))
        .border_style(Style::default().fg(Color::DarkGray));
    f.render_widget(main_block, size);

    let inner_area = Rect {
        x: size.x.saturating_add(1),
        y: size.y.saturating_add(1),
        width: size.width.saturating_sub(2),
        height: size.height.saturating_sub(2),
    };

    if inner_area.height < 4 || inner_area.width < 20 {
        return;
    }

    // Découpage horizontal : Liste & Grille Gantt / Panneau de détails en bas si actif
    let chunks = if state.show_details && inner_area.height >= 14 {
        Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Min(8), Constraint::Length(6)])
            .split(inner_area)
    } else {
        Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Min(8)])
            .split(inner_area)
    };

    let gantt_area = chunks[0];

    // Découpage vertical de la zone Gantt : Tâches (Noms/Statut) à gauche, Frise chronologique à droite
    let left_width = 30.min(gantt_area.width / 3);
    let right_width = gantt_area.width.saturating_sub(left_width);

    let list_area = Rect {
        x: gantt_area.x,
        y: gantt_area.y,
        width: left_width,
        height: gantt_area.height,
    };

    let timeline_area = Rect {
        x: gantt_area.x + left_width,
        y: gantt_area.y,
        width: right_width,
        height: gantt_area.height,
    };

    // 1. Rendu de la colonne des tâches
    render_task_list(f, list_area, state);

    // 2. Rendu de la timeline Gantt
    render_gantt_timeline(f, timeline_area, state);

    // 3. Rendu du panneau d'information détaillé
    if state.show_details && chunks.len() > 1 {
        render_details_panel(f, chunks[1], state);
    }
}

fn render_task_list(f: &mut Frame, area: Rect, state: &AppState) {
    let block = Block::default()
        .borders(Borders::RIGHT)
        .border_style(Style::default().fg(Color::DarkGray));
    f.render_widget(block, area);

    let mut lines = Vec::new();
    // En-tête
    lines.push(Line::from(vec![
        Span::styled(" Tâches", Style::default().add_modifier(Modifier::BOLD).fg(Color::Yellow)),
        Span::styled(format!(" ({})", state.project.tasks.len()), Style::default().fg(Color::DarkGray)),
    ]));
    lines.push(Line::from(Span::styled("─".repeat(area.width.saturating_sub(1) as usize), Style::default().fg(Color::DarkGray))));

    for (idx, task) in state.project.tasks.iter().enumerate() {
        let is_selected = idx == state.selected_task_index;
        let is_critical = state.critical_path.contains(&task.id);

        let selector = if is_selected { "▶ " } else { "  " };
        let crit_marker = if is_critical { "!" } else { " " };

        let name_max_w = (area.width as usize).saturating_sub(10);
        let truncated_name = if task.name.len() > name_max_w {
            format!("{}…", &task.name[..name_max_w.saturating_sub(1)])
        } else {
            task.name.clone()
        };

        let row_style = if is_selected {
            Style::default().bg(Color::Rgb(40, 44, 52)).fg(Color::White).add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(Color::Gray)
        };

        let prog_style = if task.progress == 100 {
            Style::default().fg(Color::Green)
        } else if task.progress > 0 {
            Style::default().fg(Color::Yellow)
        } else {
            Style::default().fg(Color::DarkGray)
        };

        let cat_color = category_color(task.category.as_deref());

        lines.push(Line::from(vec![
            Span::styled(selector, Style::default().fg(Color::Cyan)),
            Span::styled("▌", Style::default().fg(cat_color)),
            Span::styled(format!("{crit_marker} "), Style::default().fg(if is_critical { Color::Red } else { Color::DarkGray })),
            Span::styled(format!("{:<width$} ", truncated_name, width = name_max_w), row_style),
            Span::styled(format!("{:>3}%", task.progress), prog_style),
        ]));
    }

    let p = Paragraph::new(lines);
    f.render_widget(p, area);
}

fn render_gantt_timeline(f: &mut Frame, area: Rect, state: &AppState) {
    if area.width < 5 || area.height < 3 {
        return;
    }

    let min_date = state.project.min_date();
    let start_date = match min_date.checked_add_days(Days::new(state.scroll_day_offset.max(0) as u64)) {
        Some(d) => d,
        None => min_date,
    };
    let start_date = if state.scroll_day_offset < 0 {
        match min_date.checked_sub_days(Days::new((-state.scroll_day_offset) as u64)) {
            Some(d) => d,
            None => min_date,
        }
    } else {
        start_date
    };

    let cell_w = state.cell_width as usize;
    let num_days = (area.width as usize) / cell_w;
    let today = Local::now().date_naive();

    let mut header_month = String::new();
    let mut header_days = String::new();
    let mut header_dividers = String::new();

    let mut prev_month = None;

    for d in 0..num_days {
        let current_date = match start_date.checked_add_days(Days::new(d as u64)) {
            Some(date) => date,
            None => break,
        };

        let month_str = current_date.format("%b").to_string();
        if prev_month != Some(current_date.month()) {
            prev_month = Some(current_date.month());
            let m_label = format!("{month_str:<cell_w$}");
            header_month.push_str(&m_label);
        } else {
            header_month.push_str(&" ".repeat(cell_w));
        }

        let is_weekend = current_date.weekday().number_from_monday() >= 6;
        let day_label = format!("{:>2}", current_date.day());
        header_days.push_str(&format!("{:<cell_w$}", day_label));

        let is_today = current_date == today;
        let div_char = if is_today { "▼" } else if is_weekend { "░" } else { "·" };
        header_dividers.push_str(&format!("{:<cell_w$}", div_char));
    }

    let mut lines = Vec::new();
    lines.push(Line::from(Span::styled(header_days, Style::default().fg(Color::Cyan))));
    lines.push(Line::from(Span::styled(header_dividers, Style::default().fg(Color::DarkGray))));

    for (idx, task) in state.project.tasks.iter().enumerate() {
        let is_selected = idx == state.selected_task_index;
        let is_critical = state.critical_path.contains(&task.id);
        let mut row_spans = Vec::new();

        for d in 0..num_days {
            let current_date = match start_date.checked_add_days(Days::new(d as u64)) {
                Some(date) => date,
                None => break,
            };

            let is_today = current_date == today;
            let in_task_span = current_date >= task.start && current_date <= task.end;

            if in_task_span {
                let total_days = (task.end - task.start).num_days().max(0) + 1;
                let days_elapsed = (current_date - task.start).num_days().max(0) + 1;
                let progress_day = (total_days as f64 * (task.progress as f64 / 100.0)).ceil() as i64;
                let is_completed_part = days_elapsed <= progress_day;

                let char_fill = if is_completed_part { '█' } else { '▓' };
                let cell_str: String = std::iter::repeat(char_fill).take(cell_w).collect();

                let bar_color = if is_critical {
                    if is_completed_part { Color::LightRed } else { Color::Red }
                } else {
                    let cat_col = category_color(task.category.as_deref());
                    if is_completed_part { cat_col } else { Color::DarkGray }
                };

                let style = if is_selected {
                    Style::default().fg(bar_color).add_modifier(Modifier::BOLD)
                } else {
                    Style::default().fg(bar_color)
                };

                row_spans.push(Span::styled(cell_str, style));
            } else {
                let empty_char = if is_today { '|' } else { ' ' };
                let empty_str: String = std::iter::repeat(empty_char).take(cell_w).collect();
                let style = if is_today {
                    Style::default().fg(Color::Yellow)
                } else {
                    Style::default().fg(Color::DarkGray)
                };
                row_spans.push(Span::styled(empty_str, style));
            }
        }
        lines.push(Line::from(row_spans));
    }

    let p = Paragraph::new(lines);
    f.render_widget(p, area);
}

fn render_details_panel(f: &mut Frame, area: Rect, state: &AppState) {
    let block = Block::default()
        .borders(Borders::ALL)
        .title(" Fiche Détails Tâche ")
        .border_style(Style::default().fg(Color::Cyan));

    if let Some(task) = state.project.tasks.get(state.selected_task_index) {
        let is_critical = state.critical_path.contains(&task.id);
        let crit_badge = if is_critical { " [CRITIQUE]" } else { "" };
        let assignee = task.assignee.as_deref().unwrap_or("Non assigné");
        let category = task.category.as_deref().unwrap_or("Général");
        let deps = if task.dependencies.is_empty() {
            "Aucune".to_string()
        } else {
            task.dependencies.join(", ")
        };

        let lines = vec![
            Line::from(vec![
                Span::styled(format!("ID: [{}] ", task.id), Style::default().fg(Color::Yellow)),
                Span::styled(&task.name, Style::default().add_modifier(Modifier::BOLD).fg(Color::White)),
                Span::styled(crit_badge, Style::default().fg(Color::Red).add_modifier(Modifier::BOLD)),
            ]),
            Line::from(vec![
                Span::raw(format!("Période: {} au {} ({} jours)  |  ", task.start, task.end, task.duration_days())),
                Span::raw(format!("Avancement: {}%  |  ", task.progress)),
                Span::raw(format!("Assigné à: {}  |  ", assignee)),
                Span::raw(format!("Catégorie: {}", category)),
            ]),
            Line::from(vec![
                Span::raw("Dépendances requises: "),
                Span::styled(deps, Style::default().fg(Color::LightBlue)),
            ]),
        ];

        let p = Paragraph::new(lines).block(block);
        f.render_widget(p, area);
    } else {
        let p = Paragraph::new("Aucune tâche sélectionnée").block(block);
        f.render_widget(p, area);
    }
}

