/// Modèle d'un projet complet
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Project {
    pub name: String,
    pub tasks: Vec<Task>,
}

impl Project {
    pub fn min_date(&self) -> NaiveDate {
        self.tasks
            .iter()
            .map(|t| t.start)
            .min()
            .unwrap_or_else(|| Local::now().date_naive())
    }

    pub fn max_date(&self) -> NaiveDate {
        self.tasks
            .iter()
            .map(|t| t.end)
            .max()
            .unwrap_or_else(|| Local::now().date_naive())
    }

    /// Détecte les tâches appartenant au chemin critique simplifié
    pub fn compute_critical_path(&self) -> HashSet<String> {
        let mut critical = HashSet::new();
        if self.tasks.is_empty() {
            return critical;
        }

        // Tâches se terminant à la date max du projet
        let max_d = self.max_date();
        let mut current_ends: Vec<&Task> = self.tasks.iter().filter(|t| t.end == max_d).collect();

        while let Some(task) = current_ends.pop() {
            if critical.insert(task.id.clone()) {
                for dep_id in &task.dependencies {
                    if let Some(dep_task) = self.tasks.iter().find(|t| &t.id == dep_id) {
                        current_ends.push(dep_task);
                    }
                }
            }
        }
        critical
    }

