fn render_barchart(frame: &mut Frame, app: &App, area: Rect) {
    if app.results.is_empty() {
        let placeholder = Paragraph::new(
            "Aucun benchmark effectué.\nSélectionnez vos algorithmes et appuyez sur [Entrée] pour lancer le test.",
        )
        .alignment(Alignment::Center)
        .block(
            Block::default()
                .title(" Débit Comparatif (Mo/s) ")
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .border_style(Style::default().fg(Color::Gray)),
        );
        frame.render_widget(placeholder, area);
        return;
    }

    let bars: Vec<Bar> = app
        .results
        .iter()
        .map(|res| {
            let bar_color = match res.category {
                CryptoCategory::Hash => Color::Rgb(80, 180, 240),
                CryptoCategory::Aead => Color::Rgb(220, 100, 180),
            };
            Bar::default()
                .value(res.throughput_mbs as u64)
                .label(Line::from(res.name))
                .text_value(format!("{:.0} Mo/s", res.throughput_mbs))
                .style(Style::default().fg(bar_color))
        })
        .collect();

    let max_val = app
        .results
        .iter()
        .map(|r| r.throughput_mbs as u64)
        .max()
        .unwrap_or(100);

    let group = BarGroup::default().bars(&bars);

    let chart = BarChart::default()
        .block(
            Block::default()
                .title(" Débit Comparatif de Vitesse (Mo/s - Valeur plus élevée = Meilleure) ")
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .border_style(Style::default().fg(Color::Green)),
        )
        .data(group)
        .bar_width(11)
        .bar_gap(1)
        .max(max_val.saturating_add(max_val / 8).max(10));

    frame.render_widget(chart, area);
}

fn render_table(frame: &mut Frame, app: &App, area: Rect) {
    let header_cells = ["Algorithme", "Catégorie", "Débit (Mo/s)", "Débit (Gio/s)", "Moy. (µs)", "Itérations"]
        .into_iter()
        .map(|h| {
            Cell::from(h).style(
                Style::default()
                    .fg(Color::Yellow)
                    .add_modifier(Modifier::BOLD),
            )
        });
    let header = Row::new(header_cells).height(1).bottom_margin(1);

    let rows = app.results.iter().map(|res| {
        let (cat_text, cat_color) = match res.category {
            CryptoCategory::Hash => ("Hash", Color::Green),
            CryptoCategory::Aead => ("AEAD", Color::Magenta),
        };
        let gib_s = res.throughput_mbs / 1024.0;
        let cells = vec![
            Cell::from(res.name).style(Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
            Cell::from(cat_text).style(Style::default().fg(cat_color)),
            Cell::from(format!("{:.2}", res.throughput_mbs)).style(Style::default().fg(Color::Cyan)),
            Cell::from(format!("{:.3}", gib_s)).style(Style::default().fg(Color::LightBlue)),
            Cell::from(format!("{:.2}", res.avg_time_us)),
            Cell::from(res.iterations.to_string()),
        ];
        Row::new(cells)
    });

    let widths = [
        Constraint::Length(18),
        Constraint::Length(12),
        Constraint::Length(16),
        Constraint::Length(16),
        Constraint::Length(14),
        Constraint::Length(14),
    ];

    let table = Table::new(rows, widths)
        .header(header)
        .block(
            Block::default()
                .title(" Détail des Métriques ")
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .border_style(Style::default().fg(Color::LightCyan)),
        );

    frame.render_widget(table, area);
}

fn main() -> Result<()> {
    enable_raw_mode()?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut app = App::new();

    let res = run_app(&mut terminal, &mut app);

    // Rétablissement propre du terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    if let Err(err) = res {
        eprintln!("Erreur lors de l'exécution: {err:?}");
    }

    Ok(())
}

fn run_app<B: ratatui::backend::Backend>(terminal: &mut Terminal<B>, app: &mut App) -> Result<()> {
    loop {
        terminal.draw(|f| ui(f, app))?;

        if event::poll(Duration::from_millis(50))? {
            if let Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press {
                    match key.code {
                        KeyCode::Char('q') | KeyCode::Esc => {
                            app.should_quit = true;
                        }
                        KeyCode::Down | KeyCode::Char('j') => {
                            app.next_item();
                        }
                        KeyCode::Up | KeyCode::Char('k') => {
                            app.previous_item();
                        }
                        KeyCode::Char(' ') => {
                            app.toggle_selection();
                        }
                        KeyCode::Char('a') => {
                            app.toggle_all();
                        }
                        KeyCode::Char('+') | KeyCode::Char('=') => {
                            app.increase_buffer_size();
                        }
                        KeyCode::Char('-') => {
                            app.decrease_buffer_size();
                        }
                        KeyCode::Enter | KeyCode::Char('r') => {
                            app.status_msg = String::from("Benchmark en cours d'exécution...");
                            terminal.draw(|f| ui(f, app))?;
                            app.run_benchmark();
                        }
                        KeyCode::Char('c') => {
                            app.results.clear();
                            app.status_msg = String::from("Résultats effacés.");
                        }
                        _ => {}
                    }
                }
            }
        }

        if app.should_quit {
            break;
        }
    }

    Ok(())
}

