#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CryptoCategory {
    Hash,
    Aead,
}

#[derive(Debug, Clone)]
pub struct CryptoItem {
    pub id: &'static str,
    pub name: &'static str,
    pub category: CryptoCategory,
    pub selected: bool,
}

#[derive(Debug, Clone)]
pub struct BenchResult {
    pub name: &'static str,
    pub category: CryptoCategory,
    pub throughput_mbs: f64,
    pub avg_time_us: f64,
    pub iterations: u64,
}

pub struct App {
    pub items: Vec<CryptoItem>,
    pub list_state: ListState,
    pub results: Vec<BenchResult>,
    pub buffer_sizes: Vec<usize>,
    pub buffer_size_idx: usize,
    pub status_msg: String,
    pub is_benchmarking: bool,
    pub should_quit: bool,
}

impl App {
    pub fn new() -> Self {
        let items = vec![
            CryptoItem {
                id: "md5",
                name: "MD5",
                category: CryptoCategory::Hash,
                selected: true,
            },
            CryptoItem {
                id: "sha256",
                name: "SHA-256",
                category: CryptoCategory::Hash,
                selected: true,
            },
            CryptoItem {
                id: "sha512",
                name: "SHA-512",
                category: CryptoCategory::Hash,
                selected: true,
            },
            CryptoItem {
                id: "sha3_256",
                name: "SHA3-256",
                category: CryptoCategory::Hash,
                selected: true,
            },
            CryptoItem {
                id: "sha3_512",
                name: "SHA3-512",
                category: CryptoCategory::Hash,
                selected: true,
            },
            CryptoItem {
                id: "blake3",
                name: "BLAKE3",
                category: CryptoCategory::Hash,
                selected: true,
            },
            CryptoItem {
                id: "aes128_gcm",
                name: "AES-128-GCM",
                category: CryptoCategory::Aead,
                selected: true,
            },
            CryptoItem {
                id: "aes256_gcm",
                name: "AES-256-GCM",
                category: CryptoCategory::Aead,
                selected: true,
            },
            CryptoItem {
                id: "chacha20poly1305",
                name: "ChaCha20-Poly1305",
                category: CryptoCategory::Aead,
                selected: true,
            },
        ];

        let mut list_state = ListState::default();
        list_state.select(Some(0));

        Self {
            items,
            list_state,
            results: Vec::new(),
            buffer_sizes: vec![
                1024,             // 1 Ko
                4 * 1024,         // 4 Ko
                16 * 1024,        // 16 Ko
                64 * 1024,        // 64 Ko
                256 * 1024,       // 256 Ko
                1024 * 1024,      // 1 Mo
                4 * 1024 * 1024,  // 4 Mo
            ],
            buffer_size_idx: 3, // Défaut : 64 Ko
            status_msg: String::from("Prêt. Appuyez sur [Entrée] pour exécuter le benchmark."),
            is_benchmarking: false,
            should_quit: false,
        }
    }

    pub fn selected_buffer_size(&self) -> usize {
        self.buffer_sizes[self.buffer_size_idx]
    }

    pub fn buffer_size_label(&self) -> String {
        let bytes = self.selected_buffer_size();
        if bytes >= 1024 * 1024 {
            format!("{} Mo", bytes / (1024 * 1024))
        } else {
            format!("{} Ko", bytes / 1024)
        }
    }

    pub fn next_item(&mut self) {
        let i = match self.list_state.selected() {
            Some(i) => {
                if i >= self.items.len().saturating_sub(1) {
                    0
                } else {
                    i + 1
                }
            }
            None => 0,
        };
        self.list_state.select(Some(i));
    }

    pub fn previous_item(&mut self) {
        let i = match self.list_state.selected() {
            Some(i) => {
                if i == 0 {
                    self.items.len().saturating_sub(1)
                } else {
                    i - 1
                }
            }
            None => 0,
        };
        self.list_state.select(Some(i));
    }

    pub fn toggle_selection(&mut self) {
        if let Some(i) = self.list_state.selected() {
            if let Some(item) = self.items.get_mut(i) {
                item.selected = !item.selected;
            }
        }
    }

    pub fn toggle_all(&mut self) {
        let all_selected = self.items.iter().all(|it| it.selected);
        for item in &mut self.items {
            item.selected = !all_selected;
        }
    }

    pub fn increase_buffer_size(&mut self) {
        if self.buffer_size_idx + 1 < self.buffer_sizes.len() {
            self.buffer_size_idx += 1;
        }
    }

    pub fn decrease_buffer_size(&mut self) {
        if self.buffer_size_idx > 0 {
            self.buffer_size_idx -= 1;
        }
    }

    pub fn run_benchmark(&mut self) {
        let target_duration = Duration::from_millis(250);
        let chunk_size = self.selected_buffer_size();

        let mut data = vec![0u8; chunk_size];
        rand::thread_rng().fill_bytes(&mut data);

        self.results.clear();

        for item in &self.items {
            if !item.selected {
                continue;
            }

            let res = benchmark_algorithm(item.id, item.name, item.category, &data, target_duration);
            self.results.push(res);
        }

        self.results
            .sort_by(|a, b| b.throughput_mbs.partial_cmp(&a.throughput_mbs).unwrap_or(std::cmp::Ordering::Equal));

        self.status_msg = format!(
            "Benchmark terminé avec succès pour {} algorithme(s) [Bloc: {}].",
            self.results.len(),
            self.buffer_size_label()
        );
    }
}

fn benchmark_algorithm(
    id: &str,
    name: &'static str,
    category: CryptoCategory,
    data: &[u8],
    min_duration: Duration,
) -> BenchResult {
    let mut iterations: u64 = 0;
    let data_len = data.len();

    let start = Instant::now();

    match id {
        "md5" => {
            while start.elapsed() < min_duration {
                let mut hasher = Md5::new();
                hasher.update(data);
                let _out = hasher.finalize();
                iterations += 1;
            }
        }
        "sha256" => {
            while start.elapsed() < min_duration {
                let mut hasher = Sha256::new();
                hasher.update(data);
                let _out = hasher.finalize();
                iterations += 1;
            }
        }
        "sha512" => {
            while start.elapsed() < min_duration {
                let mut hasher = Sha512::new();
                hasher.update(data);
                let _out = hasher.finalize();
                iterations += 1;
            }
        }
        "sha3_256" => {
            while start.elapsed() < min_duration {
                let mut hasher = Sha3_256::new();
                hasher.update(data);
                let _out = hasher.finalize();
                iterations += 1;
            }
        }
        "sha3_512" => {
            while start.elapsed() < min_duration {
                let mut hasher = Sha3_512::new();
                hasher.update(data);
                let _out = hasher.finalize();
                iterations += 1;
            }
        }
        "blake3" => {
            while start.elapsed() < min_duration {
                let mut hasher = blake3::Hasher::new();
                hasher.update(data);
                let _out = hasher.finalize();
                iterations += 1;
            }
        }
        "aes128_gcm" => {
            let key = [0x42u8; 16];
            let nonce = AesNonce::from_slice(&[0x11u8; 12]);
            let cipher = Aes128Gcm::new_from_slice(&key).expect("Clé AES-128 valide");
            while start.elapsed() < min_duration {
                let _ct = cipher.encrypt(nonce, data).expect("Chiffrement AES-128");
                iterations += 1;
            }
        }
        "aes256_gcm" => {
            let key = [0x55u8; 32];
            let nonce = AesNonce::from_slice(&[0x22u8; 12]);
            let cipher = Aes256Gcm::new_from_slice(&key).expect("Clé AES-256 valide");
            while start.elapsed() < min_duration {
                let _ct = cipher.encrypt(nonce, data).expect("Chiffrement AES-256");
                iterations += 1;
            }
        }
        "chacha20poly1305" => {
            let key = [0x77u8; 32];
            let nonce = ChaChaNonce::from_slice(&[0x33u8; 12]);
            let cipher = ChaCha20Poly1305::new_from_slice(&key).expect("Clé ChaCha20 valide");
            while start.elapsed() < min_duration {
                let _ct = cipher.encrypt(nonce, data).expect("Chiffrement ChaCha20Poly1305");
                iterations += 1;
            }
        }
        _ => {}
    }

    let elapsed = start.elapsed();
    let elapsed_secs = elapsed.as_secs_f64().max(0.000_001);
    let total_bytes = (iterations as f64) * (data_len as f64);
    let throughput_mbs = (total_bytes / (1024.0 * 1024.0)) / elapsed_secs;
    let avg_time_us = if iterations > 0 {
        (elapsed.as_micros() as f64) / (iterations as f64)
    } else {
        0.0
    };

    BenchResult {
        name,
        category,
        throughput_mbs,
        avg_time_us,
        iterations,
    }
}

