```rust
// src/main.rs
use std::collections::HashMap;
use std::io;
use std::time::{Duration, Instant};

use chrono::Local;
use clap::Parser;
use crossterm::{
    event::{Event, KeyCode},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use dns_parser::{Packet as DnsPacket, QueryType, ResponseCode};
use etherparse::{SlicedPacket, TransportSlice};
use ratatui::{
    backend::CrosstermBackend,
    layout::{Alignment, Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, Cell, Clear, Paragraph, Row, Table, TableState},
    Frame, Terminal,
};
use tokio::sync::mpsc;
use tokio_stream::StreamExt;

#[derive(Parser, Debug)]
#[command(
    name = "dns-sniffer-tui",
    author = "Damien",
    version = "0.1.0",
    about = "Moniteur de requêtes DNS locales affichant domaines sollicités, latences et codes de retour"
)]
struct Args {
    /// Nom de l'interface réseau à écouter (ex: eth0, wlan0). Par défaut: première interface active.
    #[arg(short, long)]
    interface: Option<String>,

    /// Lire depuis un fichier de capture pcap au lieu d'une interface en direct
    #[arg(short, long)]
    file: Option<String>,

    /// Mode démo avec génération de trafic DNS synthétique pour tester l'interface
    #[arg(short, long)]
    demo: bool,
}

#[derive(Debug, Clone)]
enum DnsStatus {
    Pending,
    Resolved(ResponseCode),
}

impl DnsStatus {
    fn label(&self) -> String {
        match self {
            Self::Pending => "EN ATTENTE".to_string(),
            Self::Resolved(rc) => match rc {
                ResponseCode::NoError => "NOERROR".to_string(),
                ResponseCode::FormatError => "FORMERR".to_string(),
                ResponseCode::ServerFailure => "SERVFAIL".to_string(),
                ResponseCode::NameError => "NXDOMAIN".to_string(),
                ResponseCode::NotImplemented => "NOTIMP".to_string(),
                ResponseCode::Refused => "REFUSED".to_string(),
                _ => format!("{:?}", rc),
            },
        }
    }

    fn color(&self) -> Color {
        match self {
            Self::Pending => Color::Yellow,
            Self::Resolved(rc) => match rc {
                ResponseCode::NoError => Color::Green,
                ResponseCode::NameError => Color::LightRed,
                _ => Color::Red,
            },
        }
    }
}

#[derive(Debug, Clone)]
struct DnsRecord {
    id: u16,
    timestamp: String,
    domain: String,
    qtype: String,
    status: DnsStatus,
    latency_ms: Option<f64>,
}

#[derive(Debug, Default)]
struct DnsStats {
    total_queries: u64,
    total_responses: u64,
    noerror_count: u64,
    nxdomain_count: u64,
    error_count: u64,
    total_latency_ms: f64,
    latency_sample_count: u64,
}

impl DnsStats {
    fn avg_latency(&self) -> f64 {
        if self.latency_sample_count > 0 {
            self.total_latency_ms / self.latency_sample_count as f64
        } else {
            0.0
        }
    }
}

enum AppEvent {
    Record(DnsRecord),
    Error(String),
}

struct App {
    records: Vec<DnsRecord>,
    table_state: TableState,
    stats: DnsStats,
    filter_input: String,
    search_mode: bool,
    error_banner: Option<String>,
}

impl App {
    fn new() -> Self {
        let mut table_state = TableState::default();
        table_state.select(Some(0));
        Self {
            records: Vec::new(),
            table_state,
            stats: DnsStats::default(),
            filter_input: String::new(),
            search_mode: false,
            error_banner: None,
        }
    }

    fn add_record(&mut self, record: DnsRecord) {
        if let Some(existing) = self
            .records
            .iter_mut()
            .rfind(|r| r.id == record.id && r.domain == record.domain)
        {
            if matches!(existing.status, DnsStatus::Pending) {
                if let DnsStatus::Resolved(rc) = record.status {
                    existing.status = DnsStatus::Resolved(rc);
                    existing.latency_ms = record.latency_ms;
                    self.stats.total_responses += 1;
                    if let Some(lat) = record.latency_ms {
                        self.stats.total_latency_ms += lat;
                        self.stats.latency_sample_count += 1;
                    }
                    match rc {
                        ResponseCode::NoError => self.stats.noerror_count += 1,
                        ResponseCode::NameError => self.stats.nxdomain_count += 1,
                        _ => self.stats.error_count += 1,
                    }
                    return;
                }
            }
        }

        self.stats.total_queries += 1;
        if let DnsStatus::Resolved(rc) = record.status {
            self.stats.total_responses += 1;
            if let Some(lat) = record.latency_ms {
                self.stats.total_latency_ms += lat;
                self.stats.latency_sample_count += 1;
            }
            match rc {
                ResponseCode::NoError => self.stats.noerror_count += 1,
                ResponseCode::NameError => self.stats.nxdomain_count += 1,
                _ => self.stats.error_count += 1,
            }
        }

        self.records.push(record);

        if self.records.len() > 3000 {
            self.records.remove(0);
        }
    }

    fn filtered_records(&self) -> Vec<(usize, &DnsRecord)> {
        if self.filter_input.is_empty() {
            self.records.iter().enumerate().collect()
        } else {
            let filter = self.filter_input.to_lowercase();
            self.records
                .iter()
                .enumerate()
                .filter(|(_, r)| {
                    r.domain.to_lowercase().contains(&filter)
                        || r.qtype.to_lowercase().contains(&filter)
                        || r.status.label().to_lowercase().contains(&filter)
                })
                .collect()
        }
    }

    fn next_item(&mut self) {
        let count = self.filtered_records().len();
        if count == 0 {
            self.table_state.select(None);
            return;
        }
        let i = match self.table_state.selected() {
            Some(i) => {
                if i + 1 >= count {
                    0
                } else {
                    i + 1
                }
            }
            None => 0,
        };
        self.table_state.select(Some(i));
    }

    fn previous_item(&mut self) {
        let count = self.filtered_records().len();
        if count == 0 {
            self.table_state.select(None);
            return;
        }
        let i = match self.table_state.selected() {
            Some(i) => {
                if i == 0 {
                    count - 1
                } else {
                    i - 1
                }
            }
            None => 0,
        };
        self.table_state.select(Some(i));
    }

    fn clear_records(&mut self) {
        self.records.clear();
        self.table_state.select(None);
        self.stats = DnsStats::default();
    }
}

fn qtype_to_str(qtype: QueryType) -> &'static str {
    match qtype {
        QueryType::A => "A",
        QueryType::AAAA => "AAAA",
        QueryType::CNAME => "CNAME",
        QueryType::MX => "MX",
        QueryType::NS => "NS",
        QueryType::PTR => "PTR",
        QueryType::SOA => "SOA",
        QueryType::SRV => "SRV",
        QueryType::TXT => "TXT",
        QueryType::All => "ANY",
        _ => "OTHER",
    }
}

fn process_dns_payload(
    payload: &[u8],
    pending_queries: &mut HashMap<u16, (Instant, String, String)>,
) -> Option<DnsRecord> {
    let packet = match DnsPacket::parse(payload) {
        Ok(p) => p,
        Err(_) => return None,
    };

    let id = packet.header.id;
    let now = Instant::now();
    let now_str = Local::now().format("%H:%M:%S%.3f").to_string();

    if packet.header.query {
        // C'est une requête DNS (query == true)
        let question = packet.questions.first()?;
        let domain = question.qname.to_string();
        let qtype = qtype_to_str(question.qtype).to_string();

        pending_queries.insert(id, (now, domain.clone(), qtype.clone()));

        if pending_queries.len() > 10_000 {
            pending_queries.retain(|_, (t, _, _)| now.duration_since(*t).as_secs() < 30);
        }

        Some(DnsRecord {
            id,
            timestamp: now_str,
            domain,
            qtype,
            status: DnsStatus::Pending,
            latency_ms: None,
        })
    } else {
        // C'est une réponse DNS (query == false)
        let rcode = packet.header.response_code;
        let mut domain = String::from("-");
        let mut qtype = String::from("-");
        let mut latency_ms = None;

        if let Some((start_time, p_domain, p_qtype)) = pending_queries.remove(&id) {
            domain = p_domain;
            qtype = p_qtype;
            let elapsed = now.duration_since(start_time);
            latency_ms = Some(elapsed.as_secs_f64() * 1000.0);
        } else if let Some(question) = packet.questions.first() {
            domain = question.qname.to_string();
            qtype = qtype_to_str(question.qtype).to_string();
        }

        Some(DnsRecord {
            id,
            timestamp: now_str,
            domain,
            qtype,
            status: DnsStatus::Resolved(rcode),
            latency_ms,
        })
    }
}

fn handle_raw_packet(
    data: &[u8],
    pending_queries: &mut HashMap<u16, (Instant, String, String)>,
) -> Option<DnsRecord> {
    let sliced = SlicedPacket::from_ethernet(data)
        .or_else(|_| SlicedPacket::from_ip(data))
        .ok();

    if let Some(sliced_pkt) = sliced {
        if let Some(TransportSlice::Udp(udp)) = sliced_pkt.transport {
            return process_dns_payload(udp.payload(), pending_queries);
        }
    }

    // Essayer directement comme payload DNS (utile si interface raw IP / loopback)
    process_dns_payload(data, pending_queries)
}

fn capture_loop<T: pcap::Activated>(
    mut cap: pcap::Capture<T>,
    tx: &mpsc::Sender<AppEvent>,
    pending_queries: &mut HashMap<u16, (Instant, String, String)>,
) {
    loop {
        match cap.next_packet() {
            Ok(packet) => {
                if let Some(record) = handle_raw_packet(packet.data, pending_queries) {
                    if tx.blocking_send(AppEvent::Record(record)).is_err() {
                        break;
                    }
                }
            }
            Err(pcap::Error::TimeoutExpired) => continue,
            Err(pcap::Error::NoMorePackets) => break,
            Err(_) => continue,
        }
    }
}

fn capture_worker(
    interface_opt: Option<String>,
    file_opt: Option<String>,
    tx: mpsc::Sender<AppEvent>,
) {
    let mut pending_queries: HashMap<u16, (Instant, String, String)> = HashMap::new();

    if let Some(path) = file_opt {
        match pcap::Capture::from_file(&path) {
            Ok(cap) => {
                capture_loop(cap, &tx, &mut pending_queries);
            }
            Err(e) => {
                let _ = tx.blocking_send(AppEvent::Error(format!(
                    "Échec lecture pcap '{}': {}",
                    path, e
                )));
            }
        }
    } else {
        let device = match interface_opt {
            Some(name) => match pcap::Device::list() {
                Ok(devices) => devices.into_iter().find(|d| d.name == name),
                Err(e) => {
                    let _ = tx.blocking_send(AppEvent::Error(format!(
                        "Erreur énumération interfaces: {}",
                        e
                    )));
                    return;
                }
            },
            None => match pcap::Device::lookup() {
                Ok(d) => d,
                Err(e) => {
                    let _ = tx.blocking_send(AppEvent::Error(format!(
                        "Erreur recherche interface par défaut: {}. Exécutez avec sudo ou spécifiez -i <interface>",
                        e
                    )));
                    return;
                }
            },
        };

        let dev = match device {
            Some(d) => d,
            None => {
                let _ = tx.blocking_send(AppEvent::Error(
                    "Aucune interface réseau active trouvée.".to_string(),
                ));
                return;
            }
        };

        let cap_builder = match pcap::Capture::from_device(dev) {
            Ok(b) => b.promisc(true).snaplen(65535).timeout(200),
            Err(e) => {
                let _ = tx.blocking_send(AppEvent::Error(format!(
                    "Erreur initialisation interface: {}. Nécessite probablement sudo ou cap_net_raw.",
                    e
                )));
                return;
            }
        };

        match cap_builder.open() {
            Ok(mut cap) => {
                if let Err(e) = cap.filter("udp port 53", true) {
                    let _ = tx.blocking_send(AppEvent::Error(format!(
                        "Avertissement BPF filtre: {}",
                        e
                    )));
                }
                capture_loop(cap, &tx, &mut pending_queries);
            }
            Err(e) => {
                let _ = tx.blocking_send(AppEvent::Error(format!(
                    "Échec ouverture capture: {}. Exécutez avec sudo ou utilisez --demo.",
                    e
                )));
            }
        }
    }
}

async fn demo_worker(tx: mpsc::Sender<AppEvent>) {
    let mock_domains: [(&str, &str, ResponseCode, f64); 10] = [
        ("github.com", "A", ResponseCode::NoError, 12.4),
        ("google.com", "AAAA", ResponseCode::NoError, 8.2),
        ("crates.io", "A", ResponseCode::NoError, 24.1),
        ("nx-domain-test.local", "A", ResponseCode::NameError, 35.8),
        ("cloudflare.com", "HTTPS", ResponseCode::NoError, 15.0),
        ("adservice.google.com", "A", ResponseCode::NoError, 9.6),
        ("broken-dns-server.internal", "A", ResponseCode::ServerFailure, 142.3),
        ("api.openai.com", "A", ResponseCode::NoError, 45.7),
        ("matrix.org", "SRV", ResponseCode::NoError, 31.0),
        ("rust-lang.org", "A", ResponseCode::NoError, 18.9),
    ];

    let mut counter: u16 = 100;
    let mut idx = 0;

    loop {
        counter = counter.wrapping_add(1);
        let (domain, qtype, rcode, lat) = mock_domains[idx % mock_domains.len()];
        idx += 1;

        let now_str = Local::now().format("%H:%M:%S%.3f").to_string();

        let req = DnsRecord {
            id: counter,
            timestamp: now_str.clone(),
            domain: domain.to_string(),
            qtype: qtype.to_string(),
            status: DnsStatus::Pending,
            latency_ms: None,
        };

        if tx.send(AppEvent::Record(req)).await.is_err() {
            break;
        }

        tokio::time::sleep(Duration::from_millis((lat.min(100.0) * 10.0) as u64)).await;

        let res = DnsRecord {
            id: counter,
            timestamp: now_str,
            domain: domain.to_string(),
            qtype: qtype.to_string(),
            status: DnsStatus::Resolved(rcode),
            latency_ms: Some(lat),
        };

        if tx.send(AppEvent::Record(res)).await.is_err() {
            break;
        }

        tokio::time::sleep(Duration::from_millis(600)).await;
    }
}

