                .add_modifier(Modifier::BOLD),
        ),
        Span::styled("│ Erreurs: ", Style::default().fg(Color::DarkGray)),
        Span::styled(
            format!("{} ", app.stats.error_count),
            Style::default().fg(Color::Red).add_modifier(Modifier::BOLD),
        ),
        Span::styled("│ Latence Moy.: ", Style::default().fg(Color::DarkGray)),
        Span::styled(
            format!("{:.2} ms", avg_lat),
            Style::default()
                .fg(if avg_lat < 30.0 {
                    Color::Green
                } else if avg_lat < 100.0 {
                    Color::Yellow
                } else {
                    Color::Red
                })
                .add_modifier(Modifier::BOLD),
        ),
    ]);

    let stats_widget = Paragraph::new(stats_text)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .title(" Statistiques globales ")
                .border_style(Style::default().fg(Color::Blue)),
        )
        .alignment(Alignment::Left);
    f.render_widget(stats_widget, chunks[1]);

    // 3. Table des requêtes DNS
    let header_cells = [
        "Horodatage",
        "ID",
        "Type",
        "Domaine Sollicité",
        "Code Retour",
        "Latence",
    ]
    .into_iter()
    .map(|h| {
        Cell::from(h).style(
            Style::default()
                .fg(Color::Yellow)
                .add_modifier(Modifier::BOLD),
        )
    });
    let header_row = Row::new(header_cells).height(1).bottom_margin(1);

    let filtered = app.filtered_records();
    let rows: Vec<Row> = filtered
        .iter()
        .map(|(_, record)| {
            let latency_display = match record.latency_ms {
                Some(lat) => {
                    let style = if lat < 20.0 {
                        Style::default().fg(Color::Green)
                    } else if lat < 80.0 {
                        Style::default().fg(Color::Yellow)
                    } else {
                        Style::default().fg(Color::Red)
                    };
                    Cell::from(format!("{:.2} ms", lat)).style(style)
                }
                None => Cell::from("-").style(Style::default().fg(Color::DarkGray)),
            };

            let status_cell = Cell::from(record.status.label())
                .style(Style::default().fg(record.status.color()));

            let cells = vec![
                Cell::from(record.timestamp.clone())
                    .style(Style::default().fg(Color::DarkGray)),
                Cell::from(format!("0x{:04x}", record.id))
                    .style(Style::default().fg(Color::Blue)),
                Cell::from(record.qtype.clone()).style(
                    Style::default()
                        .fg(Color::Magenta)
                        .add_modifier(Modifier::BOLD),
                ),
                Cell::from(record.domain.clone()).style(Style::default().fg(Color::White)),
                status_cell,
                latency_display,
            ];
            Row::new(cells).height(1)
        })
        .collect();

    let widths = [
        Constraint::Length(14),
        Constraint::Length(8),
        Constraint::Length(8),
        Constraint::Percentage(45),
        Constraint::Length(16),
        Constraint::Length(12),
    ];

    let title_table = format!(" Requêtes DNS interceptées ({}) ", filtered.len());
    let table = Table::new(rows, widths)
        .header(header_row)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .title(title_table)
                .border_style(Style::default().fg(Color::Gray)),
        )
        .row_highlight_style(
            Style::default()
                .bg(Color::Rgb(35, 45, 65))
                .add_modifier(Modifier::BOLD),
        )
        .highlight_symbol("▶ ");

    f.render_stateful_widget(table, chunks[2], &mut app.table_state);

    // 4. Barre de filtre
    let filter_text = if app.search_mode {
        format!("Recherche (QNAME / Type / RCODE): {}█", app.filter_input)
    } else if app.filter_input.is_empty() {
        "Filtre inactif. Appuyez sur '/' pour filtrer les domaines...".to_string()
    } else {
        format!(
            "Filtre actif : '{}' (Appuyez sur 'Esc' pour réinitialiser)",
            app.filter_input
        )
    };

    let filter_style = if app.search_mode {
        Style::default().fg(Color::Yellow)
    } else if !app.filter_input.is_empty() {
        Style::default().fg(Color::Cyan)
    } else {
        Style::default().fg(Color::DarkGray)
    };

    let filter_widget = Paragraph::new(filter_text).block(
        Block::default()
            .borders(Borders::ALL)
            .title(" Recherche & Filtre ")
            .border_style(filter_style),
    );
    f.render_widget(filter_widget, chunks[3]);

    // 5. Footer d'aide
    let help_text = Line::from(vec![
        Span::styled(
            " [↑/↓] ",
            Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD),
        ),
        Span::raw("Naviguer  "),
        Span::styled(
            " [/] ",
            Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD),
        ),
        Span::raw("Filtrer  "),
        Span::styled(
            " [c] ",
            Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD),
        ),
        Span::raw("Effacer  "),
        Span::styled(
            " [q/Esc] ",
            Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD),
        ),
        Span::raw("Quitter"),
    ]);
    f.render_widget(Paragraph::new(help_text), chunks[4]);

    // Bannière d'erreur modale si présente
    if let Some(err_msg) = &app.error_banner {
        let area = centered_rect(60, 25, f.area());
        f.render_widget(Clear, area);
        let error_block = Paragraph::new(format!(
            "\n⚠️  Avertissement Capture Réseau :\n\n{}\n\n(Appuyez sur 'c' ou 'Esc' pour masquer)",
            err_msg
        ))
        .alignment(Alignment::Center)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .title(" Notification ")
                .border_style(Style::default().fg(Color::LightRed)),
        );
        f.render_widget(error_block, area);
    }
}

fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);

    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(popup_layout[1])[1]
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();

    let (tx, mut rx) = mpsc::channel::<AppEvent>(500);

    if args.demo {
        tokio::spawn(async move {
            demo_worker(tx).await;
        });
    } else {
        let iface = args.interface.clone();
        let file = args.file.clone();
        let worker_tx = tx.clone();
        std::thread::spawn(move || {
            capture_worker(iface, file, worker_tx);
        });
    }

    // Initialisation terminal crossterm
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut app = App::new();

    let tick_rate = Duration::from_millis(100);
    let mut last_tick = Instant::now();
    let mut event_reader = crossterm::event::EventStream::new();

    loop {
        terminal.draw(|f| draw_ui(f, &mut app))?;

        let timeout = tick_rate
            .checked_sub(last_tick.elapsed())
            .unwrap_or_else(|| Duration::from_secs(0));

        tokio::select! {
            Some(app_event) = rx.recv() => {
                match app_event {
                    AppEvent::Record(record) => {
                        app.add_record(record);
                    }
                    AppEvent::Error(err) => {
                        app.error_banner = Some(err);
                    }
                }
            }
            crossterm_event = event_reader.next() => {
                if let Some(Ok(Event::Key(key))) = crossterm_event {
                    if app.search_mode {
                        match key.code {
                            KeyCode::Esc | KeyCode::Enter => {
                                app.search_mode = false;
                            }
                            KeyCode::Backspace => {
                                app.filter_input.pop();
                            }
                            KeyCode::Char(c) => {
                                app.filter_input.push(c);
                            }
                            _ => {}
                        }
                    } else {
                        match key.code {
                            KeyCode::Char('q') | KeyCode::Esc => {
                                if app.error_banner.is_some() {
                                    app.error_banner = None;
                                } else {
                                    break;
                                }
                            }
                            KeyCode::Char('c') => {
                                if app.error_banner.is_some() {
                                    app.error_banner = None;
                                } else {
                                    app.clear_records();
                                }
                            }
                            KeyCode::Char('/') => {
                                app.search_mode = true;
                            }
                            KeyCode::Down | KeyCode::Char('j') => {
                                app.next_item();
                            }
                            KeyCode::Up | KeyCode::Char('k') => {
                                app.previous_item();
                            }
                            KeyCode::PageDown => {
                                for _ in 0..10 {
                                    app.next_item();
                                }
                            }
                            KeyCode::PageUp => {
                                for _ in 0..10 {
                                    app.previous_item();
                                }
                            }
                            _ => {}
                        }
                    }
                }
            }
            _ = tokio::time::sleep(timeout) => {
                last_tick = Instant::now();
            }
        }
    }

    // Restauration propre du terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    Ok(())
}

