    }
}

fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);

    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(popup_layout[1])[1]
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();

    let (tx, mut rx) = mpsc::channel::<AppEvent>(500);

    if args.demo {
        tokio::spawn(async move {
            demo_worker(tx).await;
        });
    } else {
        let iface = args.interface.clone();
        let file = args.file.clone();
        let worker_tx = tx.clone();
        std::thread::spawn(move || {
            capture_worker(iface, file, worker_tx);
        });
    }

    // Initialisation terminal crossterm
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut app = App::new();

    let tick_rate = Duration::from_millis(100);
    let mut last_tick = Instant::now();
    let mut event_reader = crossterm::event::EventStream::new();

    loop {
        terminal.draw(|f| draw_ui(f, &mut app))?;

        let timeout = tick_rate
            .checked_sub(last_tick.elapsed())
            .unwrap_or_else(|| Duration::from_secs(0));

        tokio::select! {
            Some(app_event) = rx.recv() => {
                match app_event {
                    AppEvent::Record(record) => {
                        app.add_record(record);
                    }
                    AppEvent::Error(err) => {
                        app.error_banner = Some(err);
                    }
                }
            }
            crossterm_event = event_reader.next() => {
                if let Some(Ok(Event::Key(key))) = crossterm_event {
                    if app.search_mode {
                        match key.code {
                            KeyCode::Esc | KeyCode::Enter => {
                                app.search_mode = false;
                            }
                            KeyCode::Backspace => {
                                app.filter_input.pop();
                            }
                            KeyCode::Char(c) => {
                                app.filter_input.push(c);
                            }
                            _ => {}
                        }
                    } else {
                        match key.code {
                            KeyCode::Char('q') | KeyCode::Esc => {
                                if app.error_banner.is_some() {
                                    app.error_banner = None;
                                } else {
                                    break;
                                }
                            }
                            KeyCode::Char('c') => {
                                if app.error_banner.is_some() {
                                    app.error_banner = None;
                                } else {
                                    app.clear_records();
                                }
                            }
                            KeyCode::Char('/') => {
                                app.search_mode = true;
                            }
                            KeyCode::Down | KeyCode::Char('j') => {
                                app.next_item();
                            }
                            KeyCode::Up | KeyCode::Char('k') => {
                                app.previous_item();
                            }
                            KeyCode::PageDown => {
                                for _ in 0..10 {
                                    app.next_item();
                                }
                            }
                            KeyCode::PageUp => {
                                for _ in 0..10 {
                                    app.previous_item();
                                }
                            }
                            _ => {}
                        }
                    }
                }
            }
            _ = tokio::time::sleep(timeout) => {
                last_tick = Instant::now();
            }
        }
    }

    // Restauration propre du terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    Ok(())
}

