        let raw = "<p>Bonjour &amp; bienvenue sur <b>Rust</b> !<br>Découvrez le terminal.</p>";
        let cleaned = clean_html(raw);
        assert!(cleaned.contains("Bonjour & bienvenue sur Rust !"));
        assert!(cleaned.contains("Découvrez le terminal."));
        assert!(!cleaned.contains("<p>"));
        assert!(!cleaned.contains("<b>"));
    }

    #[test]
    fn test_app_navigation_and_state() {
        let (mut app, _) = App::new();
        assert_eq!(app.focused_pane, FocusedPane::Articles);
        assert_eq!(app.feeds_state.selected(), Some(0));

        app.switch_pane_next();
        assert_eq!(app.focused_pane, FocusedPane::Preview);

        app.switch_pane_next();
        assert_eq!(app.focused_pane, FocusedPane::Feeds);

        app.next_feed();
        assert_eq!(app.feeds_state.selected(), Some(1));

        app.previous_feed();
        assert_eq!(app.feeds_state.selected(), Some(0));
    }

    #[test]
    fn test_add_and_remove_feed() {
        let (mut app, _) = App::new();
        let initial_count = app.feeds.len();

        app.add_feed("https://example.com/custom_feed.xml".to_string());
        assert_eq!(app.feeds.len(), initial_count + 1);
        assert_eq!(app.feeds.last().map(|f| f.name.as_str()), Some("example.com"));

        app.remove_current_feed();
        assert_eq!(app.feeds.len(), initial_count);
    }
