```rust
// src/main.rs
use std::{
    collections::HashMap,
    io::{self, stdout, Stdout},
    process::Command,
    sync::mpsc::{self, Receiver, Sender},
    thread,
    time::{Duration, Instant},
};

use chrono::{DateTime, Utc};
use crossterm::{
    event::{self, Event, KeyCode, KeyEventKind, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::CrosstermBackend,
    layout::{Alignment, Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span, Text},
    widgets::{
        Block, BorderType, Borders, Clear, List, ListItem, ListState, Paragraph, Wrap,
    },
    Frame, Terminal,
};

/// Représentation d'une source de flux RSS/Atom.
#[derive(Clone, Debug)]
pub struct FeedSource {
    pub name: String,
    pub url: String,
}

/// Représentation d'un article extrait d'un flux.
#[derive(Clone, Debug)]
pub struct Article {
    pub title: String,
    pub link: Option<String>,
    pub published: Option<DateTime<Utc>>,
    pub authors: Vec<String>,
    pub summary: String,
}

/// Message envoyé par le thread réseau d'arrière-plan vers le thread principal de l'UI.
pub enum NetworkMessage {
    FeedLoading(String),
    FeedLoaded {
        url: String,
        articles: Vec<Article>,
    },
    FeedError {
        url: String,
        error: String,
    },
}

/// Panneau actif recevant les entrées utilisateur.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub enum FocusedPane {
    Feeds,
    Articles,
    Preview,
}

/// État de saisie pour l'ajout d'un flux.
#[derive(Clone, Debug, Default)]
pub struct AddFeedModal {
    pub is_active: bool,
    pub input_url: String,
}

/// État global de l'application TUI.
pub struct App {
    pub feeds: Vec<FeedSource>,
    pub feeds_state: ListState,
    pub articles_by_url: HashMap<String, Vec<Article>>,
    pub articles_state: ListState,
    pub focused_pane: FocusedPane,
    pub preview_scroll: u16,
    pub status_message: String,
    pub status_is_error: bool,
    pub is_loading: bool,
    pub show_help: bool,
    pub add_modal: AddFeedModal,
    pub should_quit: bool,
    network_tx: Sender<NetworkMessage>,
    network_rx: Receiver<NetworkMessage>,
}

impl App {
    pub fn new() -> (Self, Sender<NetworkMessage>) {
        let (tx, rx) = mpsc::channel();
        let default_feeds = vec![
            FeedSource {
                name: "Rust Blog".to_string(),
                url: "https://blog.rust-lang.org/feed.xml".to_string(),
            },
            FeedSource {
                name: "This Week in Rust".to_string(),
                url: "https://this-week-in-rust.org/rss.xml".to_string(),
            },
            FeedSource {
                name: "Ars Technica".to_string(),
                url: "https://feeds.arstechnica.com/arstechnica/index".to_string(),
            },
        ];

        let mut feeds_state = ListState::default();
        if !default_feeds.is_empty() {
            feeds_state.select(Some(0));
        }

        let app = Self {
            feeds: default_feeds,
            feeds_state,
            articles_by_url: HashMap::new(),
            articles_state: ListState::default(),
            focused_pane: FocusedPane::Articles,
            preview_scroll: 0,
            status_message: "Prêt. Appuyez sur [h] pour l'aide, [r] pour actualiser.".to_string(),
            status_is_error: false,
            is_loading: false,
            show_help: false,
            add_modal: AddFeedModal::default(),
            should_quit: false,
            network_tx: tx.clone(),
            network_rx: rx,
        };

        (app, tx)
    }

    /// Déclenche le téléchargement asynchrone d'un flux sans bloquer l'UI.
    pub fn trigger_fetch_feed(&mut self, url: String) {
        self.is_loading = true;
        self.status_is_error = false;
        self.status_message = format!("Chargement du flux {}...", url);

        let tx = self.network_tx.clone();
        let fetch_url = url.clone();

        thread::spawn(move || {
            let _ = tx.send(NetworkMessage::FeedLoading(fetch_url.clone()));
            match fetch_rss_feed(&fetch_url) {
                Ok(articles) => {
                    let _ = tx.send(NetworkMessage::FeedLoaded {
                        url: fetch_url,
                        articles,
                    });
                }
                Err(err) => {
                    let _ = tx.send(NetworkMessage::FeedError {
                        url: fetch_url,
                        error: err.to_string(),
                    });
                }
            }
        });
    }

    /// Dépouille la file d'attente des messages réseau.
    pub fn process_network_messages(&mut self) {
        while let Ok(msg) = self.network_rx.try_recv() {
            match msg {
                NetworkMessage::FeedLoading(url) => {
                    self.is_loading = true;
                    self.status_message = format!("Récupération de {}...", url);
                }
                NetworkMessage::FeedLoaded { url, articles } => {
                    self.is_loading = false;
                    self.status_is_error = false;
                    let count = articles.len();
                    self.articles_by_url.insert(url.clone(), articles);

                    if let Some(selected_feed) = self.selected_feed()
                        && selected_feed.url == url
                            && self.articles_state.selected().is_none() && count > 0 {
                                self.articles_state.select(Some(0));
                            }
                    self.status_message = format!("Flux actualisé : {} articles chargés.", count);
                }
                NetworkMessage::FeedError { url, error } => {
                    self.is_loading = false;
                    self.status_is_error = true;
                    self.status_message = format!("Erreur sur {} : {}", url, error);
                }
            }
        }
    }

    pub fn selected_feed(&self) -> Option<&FeedSource> {
        self.feeds_state
            .selected()
            .and_then(|idx| self.feeds.get(idx))
    }

    pub fn current_articles(&self) -> &[Article] {
        if let Some(feed) = self.selected_feed()
            && let Some(articles) = self.articles_by_url.get(&feed.url) {
                return articles.as_slice();
            }
        &[]
    }

    pub fn selected_article(&self) -> Option<&Article> {
        let articles = self.current_articles();
        self.articles_state
            .selected()
            .and_then(|idx| articles.get(idx))
    }

    pub fn next_feed(&mut self) {
        if self.feeds.is_empty() {
            return;
        }
        let i = match self.feeds_state.selected() {
            Some(i) => (i + 1) % self.feeds.len(),
            None => 0,
        };
        self.feeds_state.select(Some(i));
        self.articles_state.select(None);
        self.preview_scroll = 0;
        if let Some(feed) = self.selected_feed() {
            let url = feed.url.clone();
            if !self.articles_by_url.contains_key(&url) {
                self.trigger_fetch_feed(url);
            } else if !self.current_articles().is_empty() {
                self.articles_state.select(Some(0));
            }
        }
    }

    pub fn previous_feed(&mut self) {
        if self.feeds.is_empty() {
            return;
        }
        let i = match self.feeds_state.selected() {
            Some(i) => {
                if i == 0 {
                    self.feeds.len().saturating_sub(1)
                } else {
                    i - 1
                }
            }
            None => 0,
        };
        self.feeds_state.select(Some(i));
        self.articles_state.select(None);
        self.preview_scroll = 0;
        if let Some(feed) = self.selected_feed() {
            let url = feed.url.clone();
            if !self.articles_by_url.contains_key(&url) {
                self.trigger_fetch_feed(url);
            } else if !self.current_articles().is_empty() {
                self.articles_state.select(Some(0));
            }
        }
    }

    pub fn next_article(&mut self) {
        let count = self.current_articles().len();
        if count == 0 {
            return;
        }
        let i = match self.articles_state.selected() {
            Some(i) => (i + 1) % count,
            None => 0,
        };
        self.articles_state.select(Some(i));
        self.preview_scroll = 0;
    }

    pub fn previous_article(&mut self) {
        let count = self.current_articles().len();
        if count == 0 {
            return;
        }
        let i = match self.articles_state.selected() {
            Some(i) => {
                if i == 0 {
                    count.saturating_sub(1)
                } else {
                    i - 1
                }
            }
            None => 0,
        };
        self.articles_state.select(Some(i));
        self.preview_scroll = 0;
    }

    pub fn scroll_preview_down(&mut self, amount: u16) {
        self.preview_scroll = self.preview_scroll.saturating_add(amount);
    }

    pub fn scroll_preview_up(&mut self, amount: u16) {
        self.preview_scroll = self.preview_scroll.saturating_sub(amount);
    }

    pub fn switch_pane_next(&mut self) {
        self.focused_pane = match self.focused_pane {
            FocusedPane::Feeds => FocusedPane::Articles,
            FocusedPane::Articles => FocusedPane::Preview,
            FocusedPane::Preview => FocusedPane::Feeds,
        };
    }

    pub fn switch_pane_prev(&mut self) {
        self.focused_pane = match self.focused_pane {
            FocusedPane::Feeds => FocusedPane::Preview,
            FocusedPane::Articles => FocusedPane::Feeds,
            FocusedPane::Preview => FocusedPane::Articles,
        };
    }

    pub fn refresh_current_feed(&mut self) {
        if let Some(feed) = self.selected_feed() {
            let url = feed.url.clone();
            self.trigger_fetch_feed(url);
        }
    }

    pub fn open_selected_in_browser(&mut self) {
        let link_opt = self.selected_article().and_then(|a| a.link.clone());
        if let Some(link) = link_opt {
            let opener = if cfg!(target_os = "macos") {
                "open"
            } else if cfg!(target_os = "windows") {
                "start"
            } else {
                "xdg-open"
            };

            match Command::new(opener).arg(&link).spawn() {
                Ok(_) => {
                    self.status_is_error = false;
                    self.status_message = format!("Ouverture dans le navigateur : {}", link);
                }
                Err(err) => {
                    self.status_is_error = true;
                    self.status_message = format!("Échec du lancement du navigateur : {}", err);
                }
            }
        } else {
            self.status_is_error = true;
            self.status_message = "L'article sélectionné n'a pas d'URL valide.".to_string();
        }
    }

    pub fn remove_current_feed(&mut self) {
        if let Some(selected_idx) = self.feeds_state.selected()
            && selected_idx < self.feeds.len() {
                let removed = self.feeds.remove(selected_idx);
                self.articles_by_url.remove(&removed.url);

                if self.feeds.is_empty() {
                    self.feeds_state.select(None);
                    self.articles_state.select(None);
                } else {
                    let new_idx = selected_idx.min(self.feeds.len().saturating_sub(1));
                    self.feeds_state.select(Some(new_idx));
                    self.articles_state.select(None);
                }
                self.status_is_error = false;
                self.status_message = format!("Flux '{}' supprimé.", removed.name);
            }
    }

    pub fn add_feed(&mut self, url: String) {
        let trimmed = url.trim().to_string();
        if trimmed.is_empty() {
            return;
        }

        let name = trimmed
            .strip_prefix("https://")
            .or_else(|| trimmed.strip_prefix("http://"))
            .unwrap_or(&trimmed)
            .split('/')
            .next()
            .unwrap_or("Nouveau flux")
            .to_string();

        let new_feed = FeedSource {
            name,
            url: trimmed.clone(),
        };

        self.feeds.push(new_feed);
        let new_index = self.feeds.len() - 1;
        self.feeds_state.select(Some(new_index));
        self.articles_state.select(None);
        self.trigger_fetch_feed(trimmed);
        self.status_is_error = false;
        self.status_message = "Nouveau flux ajouté.".to_string();
    }
}

/// Télécharge et extrait les articles d'un flux RSS/Atom.
fn fetch_rss_feed(url: &str) -> Result<Vec<Article>, String> {
    let client = reqwest::blocking::Client::builder()
        .user_agent("Dystil-Terminal-RSS/1.0")
        .timeout(Duration::from_secs(12))
        .build()
        .map_err(|e| format!("Client HTTP indisponible : {}", e))?;

    let response = client
        .get(url)
        .send()
        .map_err(|e| format!("Erreur réseau : {}", e))?;

    if !response.status().is_success() {
        return Err(format!("Statut HTTP {}", response.status()));
    }

    let bytes = response
        .bytes()
        .map_err(|e| format!("Lecture du flux échouée : {}", e))?;

    let feed = feed_rs::parser::parse(&bytes[..])
        .map_err(|e| format!("Flux XML/RSS invalide : {}", e))?;

    let mut articles = Vec::new();
    for entry in feed.entries {
        let title = entry
            .title
            .map(|t| clean_html(&t.content))
            .filter(|s| !s.trim().is_empty())
            .unwrap_or_else(|| "Sans titre".to_string());

        let link = entry.links.into_iter().next().map(|l| l.href);
        let published = entry.published.or(entry.updated);

        let authors = entry
            .authors
            .into_iter()
            .filter_map(|p| p.name)
            .filter(|n| !n.trim().is_empty())
            .collect();

        let summary = if let Some(content) = entry.content.and_then(|c| c.body) {
            clean_html(&content)
        } else if let Some(summary) = entry.summary {
            clean_html(&summary.content)
        } else {
            "Aucun contenu disponible pour cet article.".to_string()
        };

        articles.push(Article {
            title,
            link,
            published,
            authors,
            summary,
        });
    }

    Ok(articles)
}

/// Nettoie les balises HTML basiques et décode les entités XML/HTML pour affichage terminal.
fn clean_html(input: &str) -> String {
    let unescaped = html_escape::decode_html_entities(input).to_string();
    let mut result = String::with_capacity(unescaped.len());
    let mut in_tag = false;

    // Normalisation basique des balises de saut de ligne
    let text = unescaped
        .replace("<br>", "\n")
        .replace("<br/>", "\n")
        .replace("<br />", "\n")
        .replace("</p>", "\n\n")
        .replace("</li>", "\n")
        .replace("<li>", "• ");

    for ch in text.chars() {
        match ch {
            '<' => in_tag = true,
            '>' => in_tag = false,
            _ if !in_tag => result.push(ch),
            _ => {}
        }
    }

    // Réduction des lignes vides multiples
    let lines: Vec<&str> = result.lines().collect();
    let mut cleaned_lines = Vec::new();
    let mut prev_was_empty = false;

    for line in lines {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            if !prev_was_empty {
                cleaned_lines.push("");
                prev_was_empty = true;
            }
        } else {
            cleaned_lines.push(trimmed);
            prev_was_empty = false;
        }
    }

    cleaned_lines.join("\n")
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialisation du terminal en mode brut (raw mode)
    enable_raw_mode()?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let (mut app, _) = App::new();

    // Déclenche le premier chargement du premier flux
    if let Some(feed) = app.selected_feed() {
        let url = feed.url.clone();
        app.trigger_fetch_feed(url);
    }

    let run_res = run_app(&mut terminal, &mut app);

    // Restauration garantie de l'état du terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    if let Err(err) = run_res {
        eprintln!("Erreur lors de l'exécution de l'application : {}", err);
    }

    Ok(())
}

fn run_app(
    terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    app: &mut App,
) -> io::Result<()> {
    let tick_rate = Duration::from_millis(150);
    let mut last_tick = Instant::now();

    while !app.should_quit {
        app.process_network_messages();
        terminal.draw(|f| ui(f, app))?;

        let timeout = tick_rate.saturating_sub(last_tick.elapsed());
        if event::poll(timeout)?
            && let Event::Key(key) = event::read()?
                && key.kind == KeyEventKind::Press {
                    handle_key_event(app, key.code, key.modifiers);
                }

        if last_tick.elapsed() >= tick_rate {
            last_tick = Instant::now();
        }
    }

    Ok(())
}

fn handle_key_event(app: &mut App, key: KeyCode, modifiers: KeyModifiers) {
    // Gestion de la modale d'aide
    if app.show_help {
        if matches!(key, KeyCode::Esc | KeyCode::Char('?') | KeyCode::Char('h') | KeyCode::Char('q') | KeyCode::Enter) {
            app.show_help = false;
        }
        return;
    }

    // Gestion de la modale d'ajout de flux
    if app.add_modal.is_active {
        match key {
            KeyCode::Esc => {
                app.add_modal.is_active = false;
                app.add_modal.input_url.clear();
            }
            KeyCode::Enter => {
                let url = std::mem::take(&mut app.add_modal.input_url);
                app.add_modal.is_active = false;
                app.add_feed(url);
            }
            KeyCode::Backspace => {
                app.add_modal.input_url.pop();
            }
            KeyCode::Char(c) => {
                app.add_modal.input_url.push(c);
            }
            _ => {}
        }
        return;
    }

    // Raccourcis globaux
    match key {
        KeyCode::Char('c') if modifiers.contains(KeyModifiers::CONTROL) => {
            app.should_quit = true;
            return;
        }
        KeyCode::Char('q') => {
            app.should_quit = true;
            return;
        }
        KeyCode::Char('?') | KeyCode::Char('h') => {
            app.show_help = true;
            return;
        }
        KeyCode::Char('r') => {
            app.refresh_current_feed();
            return;
        }
        KeyCode::Char('o') => {
            app.open_selected_in_browser();
            return;
        }
        KeyCode::Char('a') => {
            app.add_modal.is_active = true;
            app.add_modal.input_url.clear();
            return;
        }
        KeyCode::Char('d') => {
            if app.focused_pane == FocusedPane::Feeds {
                app.remove_current_feed();
            }
            return;
        }
        KeyCode::Tab => {
            app.switch_pane_next();
            return;
        }
        KeyCode::BackTab => {
            app.switch_pane_prev();
            return;
        }
        KeyCode::Left => {
            app.switch_pane_prev();
            return;
        }
        KeyCode::Right => {
            app.switch_pane_next();
            return;
        }
        _ => {}
    }

    // Actions spécifiques au panneau actif
    match app.focused_pane {
        FocusedPane::Feeds => match key {
            KeyCode::Up | KeyCode::Char('k') => app.previous_feed(),
            KeyCode::Down | KeyCode::Char('j') => app.next_feed(),
            KeyCode::Enter => app.refresh_current_feed(),
            _ => {}
        },
        FocusedPane::Articles => match key {
            KeyCode::Up | KeyCode::Char('k') => app.previous_article(),
            KeyCode::Down | KeyCode::Char('j') => app.next_article(),
            KeyCode::Enter => app.focused_pane = FocusedPane::Preview,
            _ => {}
        },
        FocusedPane::Preview => match key {
            KeyCode::Up | KeyCode::Char('k') => app.scroll_preview_up(1),
            KeyCode::Down | KeyCode::Char('j') => app.scroll_preview_down(1),
            KeyCode::PageUp => app.scroll_preview_up(8),
            KeyCode::PageDown => app.scroll_preview_down(8),
            KeyCode::Home => app.preview_scroll = 0,
            _ => {}
        },
    }
}

fn ui(f: &mut Frame, app: &mut App) {
    let size = f.area();

    // Découpage vertical : En-tête (3), Corps principal (Min 0), Pied de page (3)
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3),
            Constraint::Min(8),
            Constraint::Length(3),
        ])
        .split(size);

    render_header(f, app, chunks[0]);
    render_main_panes(f, app, chunks[1]);
    render_footer(f, app, chunks[2]);

    if app.add_modal.is_active {
        render_add_modal(f, app, size);
    } else if app.show_help {
        render_help_modal(f, size);
    }
}

fn render_header(f: &mut Frame, app: &App, area: Rect) {
    let status_style = if app.status_is_error {
        Style::default().fg(Color::Red).add_modifier(Modifier::BOLD)
    } else if app.is_loading {
        Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)
    } else {
        Style::default().fg(Color::Green)
    };

    let title_line = Line::from(vec![
        Span::styled(" RSS TERMINAL READER ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
        Span::raw("│ "),
        Span::styled(
            if app.is_loading { "⟳ CHARGEMENT " } else { "● EN LIGNE " },
            status_style,
        ),
        Span::raw("│ "),
        Span::styled(&app.status_message, Style::default().fg(Color::White)),
    ]);

    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(Style::default().fg(Color::DarkGray));

    let header_p = Paragraph::new(title_line).block(block);
    f.render_widget(header_p, area);
}

fn render_main_panes(f: &mut Frame, app: &mut App, area: Rect) {
    // Découpage horizontal : Flux (20%), Articles (35%), Aperçu (45%)
    let horizontal_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(22),
            Constraint::Percentage(38),
            Constraint::Percentage(40),
        ])
        .split(area);

    render_feeds_pane(f, app, horizontal_chunks[0]);
    render_articles_pane(f, app, horizontal_chunks[1]);
    render_preview_pane(f, app, horizontal_chunks[2]);
}

fn render_feeds_pane(f: &mut Frame, app: &mut App, area: Rect) {
    let is_focused = app.focused_pane == FocusedPane::Feeds;
    let border_color = if is_focused { Color::Cyan } else { Color::DarkGray };

    let items: Vec<ListItem> = {
        let sel = app.feeds_state.selected();
        app.feeds
            .iter()
            .enumerate()
            .map(|(i, feed)| {
                let prefix = if sel == Some(i) { "▶ " } else { "  " };
                let count_hint = app
                    .articles_by_url
                    .get(&feed.url)
                    .map(|a| format!(" ({})", a.len()))
                    .unwrap_or_default();

                let line = Line::from(vec![
                    Span::styled(prefix, Style::default().fg(Color::Cyan)),
                    Span::styled(feed.name.clone(), Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
                    Span::styled(count_hint, Style::default().fg(Color::DarkGray)),
                ]);
                ListItem::new(line)
            })
