fn render_details(f: &mut Frame, app: &App, area: Rect) {
    let dev_opt = app.selected_device();
    let title = match dev_opt {
        Some(dev) => format!(" Activité historique pour [{}] (dernières 60 secondes) ", dev),
        None => " Historique (aucun périphérique sélectionné) ".to_string(),
    };

    let block = Block::default()
        .borders(Borders::ALL)
        .title(title)
        .title_style(Style::default().fg(Color::Cyan));

    let inner = block.inner(area);
    f.render_widget(block, area);

    if let Some(dev) = dev_opt {
        let history = app.histories.get(dev);
        let read_data: Vec<u64> = history.map(|h| h.read_mb.iter().copied().collect()).unwrap_or_default();
        let write_data: Vec<u64> = history.map(|h| h.write_mb.iter().copied().collect()).unwrap_or_default();

        let sub_chunks = Layout::default()
            .direction(Direction::Vertical)
            .constraints([
                Constraint::Length(1), // Libellé lecture
                Constraint::Length(2), // Sparkline lecture
                Constraint::Length(1), // Libellé écriture
                Constraint::Length(2), // Sparkline écriture
            ])
            .split(inner);

        let curr_rate = app.rates.get(dev).copied().unwrap_or_default();

        // 1. Sparkline Lecture
        let read_label = format!("Débit Lecture: {:.2} Mo/s (Max historique: {:.2} Mo/s)",
            curr_rate.read_mb_per_sec,
            read_data.iter().max().copied().unwrap_or(0) as f64 / 1024.0
        );
        f.render_widget(
            Paragraph::new(read_label).style(Style::default().fg(Color::Cyan)),
            sub_chunks[0],
        );

        let read_sparkline = Sparkline::default()
            .data(&read_data)
            .style(Style::default().fg(Color::Cyan))
            .bar_set(symbols::bar::NINE_LEVELS);
        f.render_widget(read_sparkline, sub_chunks[1]);

        // 2. Sparkline Écriture
        let write_label = format!("Débit Écriture: {:.2} Mo/s (Max historique: {:.2} Mo/s)",
            curr_rate.write_mb_per_sec,
            write_data.iter().max().copied().unwrap_or(0) as f64 / 1024.0
        );
        f.render_widget(
            Paragraph::new(write_label).style(Style::default().fg(Color::Magenta)),
            sub_chunks[2],
        );

        let write_sparkline = Sparkline::default()
            .data(&write_data)
            .style(Style::default().fg(Color::Magenta))
            .bar_set(symbols::bar::NINE_LEVELS);
        f.render_widget(write_sparkline, sub_chunks[3]);
    } else {
        let msg = Paragraph::new("Sélectionnez un périphérique dans le tableau ci-dessus.");
        f.render_widget(msg, inner);
    }
