/// Données brutes lues depuis /proc/diskstats pour un périphérique.
#[derive(Debug, Clone, Copy, Default)]
struct RawDiskStat {
    reads_completed: u64,
    sectors_read: u64,
    writes_completed: u64,
    sectors_written: u64,
}

/// Taux calculés sur un intervalle de temps (débits et IOPS).
#[derive(Debug, Clone, Copy, Default)]
struct DiskRate {
    read_iops: f64,
    write_iops: f64,
    read_mb_per_sec: f64,
    write_mb_per_sec: f64,
}

impl DiskRate {
    fn total_iops(&self) -> f64 {
        self.read_iops + self.write_iops
    }

    fn total_mb_per_sec(&self) -> f64 {
        self.read_mb_per_sec + self.write_mb_per_sec
    }
}

/// Historique des taux récents pour un périphérique spécifique (pour le sparkline).
#[derive(Default)]
struct DeviceHistory {
    read_mb: VecDeque<u64>,
    write_mb: VecDeque<u64>,
}

impl DeviceHistory {
    const CAPACITY: usize = 60;

    fn push(&mut self, read_mb: f64, write_mb: f64) {
        if self.read_mb.len() >= Self::CAPACITY {
            self.read_mb.pop_front();
        }
        if self.write_mb.len() >= Self::CAPACITY {
            self.write_mb.pop_front();
        }
        // Conversion en Ko/s pour garder une précision entière exploitable par le Sparkline
        self.read_mb.push_back((read_mb * 1024.0) as u64);
        self.write_mb.push_back((write_mb * 1024.0) as u64);
    }
}

/// État global de l'application TUI.
struct App {
    diskstats_reader: BufReader<File>,
    last_raw_stats: HashMap<String, RawDiskStat>,
    last_sample_time: Instant,
    rates: HashMap<String, DiskRate>,
    histories: HashMap<String, DeviceHistory>,
    table_state: TableState,
    filter_loops: bool,
    disks_list: Vec<String>,
}

impl App {
    fn new() -> Result<Self> {
        let file = File::open("/proc/diskstats")
            .context("Impossible d'ouvrir /proc/diskstats (système non Linux ou droits insuffisants)")?;
        let reader = BufReader::new(file);

        let mut app = Self {
            diskstats_reader: reader,
            last_raw_stats: HashMap::new(),
            last_sample_time: Instant::now(),
            rates: HashMap::new(),
            histories: HashMap::new(),
            table_state: TableState::default(),
            filter_loops: true,
            disks_list: Vec::new(),
        };

        // Échantillonnage initial
        app.update_stats()?;
        if !app.disks_list.is_empty() {
            app.table_state.select(Some(0));
        }

        Ok(app)
    }

    fn parse_diskstats(&mut self) -> Result<HashMap<String, RawDiskStat>> {
        self.diskstats_reader.seek(SeekFrom::Start(0))?;
        let mut raw_map = HashMap::new();
        let mut line_buffer = String::with_capacity(256);

        loop {
            line_buffer.clear();
            let bytes_read = self.diskstats_reader.read_line(&mut line_buffer)?;
            if bytes_read == 0 {
                break;
            }

            // /proc/diskstats colonnes :
            // 0: major, 1: minor, 2: name, 3: reads_completed, 4: reads_merged, 5: sectors_read,
            // 6: read_ms, 7: writes_completed, 8: writes_merged, 9: sectors_written
            let mut parts = line_buffer.split_whitespace();
            let _major = parts.next();
            let _minor = parts.next();
            let name = match parts.next() {
                Some(n) => n.to_string(),
                None => continue,
            };

            let reads_completed: u64 = parts.next().and_then(|v| v.parse().ok()).unwrap_or(0);
            let _reads_merged = parts.next();
            let sectors_read: u64 = parts.next().and_then(|v| v.parse().ok()).unwrap_or(0);
            let _read_ms = parts.next();
            let writes_completed: u64 = parts.next().and_then(|v| v.parse().ok()).unwrap_or(0);
            let _writes_merged = parts.next();
            let sectors_written: u64 = parts.next().and_then(|v| v.parse().ok()).unwrap_or(0);

            raw_map.insert(
                name,
                RawDiskStat {
                    reads_completed,
                    sectors_read,
                    writes_completed,
                    sectors_written,
                },
            );
        }

        Ok(raw_map)
    }

    fn update_stats(&mut self) -> Result<()> {
        let current_raw = self.parse_diskstats()?;
        let now = Instant::now();
        let elapsed = now.duration_since(self.last_sample_time).as_secs_f64();

        if elapsed > 0.0 && !self.last_raw_stats.is_empty() {
            let mut new_rates = HashMap::new();

            for (dev, curr) in &current_raw {
                if let Some(prev) = self.last_raw_stats.get(dev) {
                    let d_reads = curr.reads_completed.saturating_sub(prev.reads_completed) as f64;
                    let d_writes = curr.writes_completed.saturating_sub(prev.writes_completed) as f64;
                    let d_sec_read = curr.sectors_read.saturating_sub(prev.sectors_read) as f64;
                    let d_sec_write = curr.sectors_written.saturating_sub(prev.sectors_written) as f64;

                    // Un secteur sous Linux = 512 octets
                    let read_mb = (d_sec_read * 512.0) / (1024.0 * 1024.0 * elapsed);
                    let write_mb = (d_sec_write * 512.0) / (1024.0 * 1024.0 * elapsed);

                    let rate = DiskRate {
                        read_iops: d_reads / elapsed,
                        write_iops: d_writes / elapsed,
                        read_mb_per_sec: read_mb,
                        write_mb_per_sec: write_mb,
                    };

                    self.histories
                        .entry(dev.clone())
                        .or_default()
                        .push(rate.read_mb_per_sec, rate.write_mb_per_sec);

                    new_rates.insert(dev.clone(), rate);
                }
            }
            self.rates = new_rates;
        }

        self.last_raw_stats = current_raw;
        self.last_sample_time = now;
        self.refresh_disk_list();

        Ok(())
    }

    fn refresh_disk_list(&mut self) {
        let mut list: Vec<String> = self
            .last_raw_stats
            .keys()
            .filter(|name| {
                if self.filter_loops {
                    !name.starts_with("loop") && !name.starts_with("ram")
                } else {
                    true
                }
            })
            .cloned()
            .collect();

        // Trier les disques : les périphériques actifs en premier, sinon ordre alphabétique
        list.sort_by(|a, b| {
            let rate_a = self.rates.get(a).map(|r| r.total_mb_per_sec()).unwrap_or(0.0);
            let rate_b = self.rates.get(b).map(|r| r.total_mb_per_sec()).unwrap_or(0.0);

            rate_b
                .partial_cmp(&rate_a)
                .unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| a.cmp(b))
        });

        self.disks_list = list;

        // Ajuster l'index sélectionné si nécessaire
        if let Some(selected) = self.table_state.selected() {
            if self.disks_list.is_empty() {
                self.table_state.select(None);
            } else if selected >= self.disks_list.len() {
                self.table_state.select(Some(self.disks_list.len() - 1));
            }
        } else if !self.disks_list.is_empty() {
            self.table_state.select(Some(0));
        }
    }

    fn next_disk(&mut self) {
        if self.disks_list.is_empty() {
            return;
        }
        let i = match self.table_state.selected() {
            Some(i) => (i + 1) % self.disks_list.len(),
            None => 0,
        };
        self.table_state.select(Some(i));
    }

    fn previous_disk(&mut self) {
        if self.disks_list.is_empty() {
            return;
        }
        let i = match self.table_state.selected() {
            Some(i) => {
                if i == 0 {
                    self.disks_list.len() - 1
                } else {
                    i - 1
                }
            }
            None => 0,
        };
        self.table_state.select(Some(i));
    }

    fn toggle_filter(&mut self) {
        self.filter_loops = !self.filter_loops;
        self.refresh_disk_list();
    }

    fn selected_device(&self) -> Option<&String> {
        self.table_state
            .selected()
            .and_then(|idx| self.disks_list.get(idx))
    }
}

/// RAII Guard pour rétablir proprement l'état du terminal en cas de sortie ou de panique.
struct TerminalCleanup;

impl Drop for TerminalCleanup {
    fn drop(&mut self) {
        let _ = disable_raw_mode();
        let _ = execute!(io::stdout(), LeaveAlternateScreen);
    }
}

fn setup_terminal() -> Result<Terminal<CrosstermBackend<io::Stdout>>> {
    enable_raw_mode().context("Erreur lors de l'activation du raw mode")?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)
        .context("Erreur lors du passage sur l'Alternate Screen")?;
    let backend = CrosstermBackend::new(stdout);
    Terminal::new(backend).context("Initialisation du terminal ratatui impossible")
}

fn setup_panic_hook() {
    let original_hook = panic::take_hook();
    panic::set_hook(Box::new(move |panic_info| {
        let _ = disable_raw_mode();
        let _ = execute!(io::stdout(), LeaveAlternateScreen);
        original_hook(panic_info);
    }));
}

fn main() -> Result<()> {
    setup_panic_hook();
    let _cleanup_guard = TerminalCleanup;
    let mut terminal = setup_terminal()?;

    let mut app = App::new()?;
    let tick_rate = Duration::from_millis(1000);
    let mut last_tick = Instant::now();

    loop {
        terminal.draw(|f| ui(f, &mut app))?;

        let timeout = tick_rate.saturating_sub(last_tick.elapsed());
        if event::poll(timeout)? {
            if let Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press {
                    match key.code {
                        KeyCode::Char('q') | KeyCode::Esc => break,
                        KeyCode::Down | KeyCode::Char('j') => app.next_disk(),
                        KeyCode::Up | KeyCode::Char('k') => app.previous_disk(),
                        KeyCode::Tab => app.toggle_filter(),
                        KeyCode::Char('r') => {
                            app.histories.clear();
                        }
                        _ => {}
                    }
                }
            }
        }

        if last_tick.elapsed() >= tick_rate {
            app.update_stats()?;
            last_tick = Instant::now();
        }
    }

    Ok(())
}

