```rust
// src/main.rs
use anyhow::{Context, Result};
use crossterm::{
    event::{self, DisableMouseCapture, EnableMouseCapture, Event, KeyCode, KeyEventKind, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::CrosstermBackend,
    layout::{Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, Cell, Clear, Paragraph, Row, Table},
    Frame, Terminal,
};
use std::{
    env,
    fs::File,
    io::{stdout, Stdout},
    path::PathBuf,
};
use unicode_width::UnicodeWidthStr;

#[derive(Debug, PartialEq, Eq)]
enum AppMode {
    Normal,
    EditingCell,
    AddingColumn,
}

struct App {
    file_path: PathBuf,
    headers: Vec<String>,
    rows: Vec<Vec<String>>,
    selected_row: usize,
    selected_col: usize,
    mode: AppMode,
    input_buffer: String,
    cursor_char_idx: usize,
    status_message: String,
    dirty: bool,
}

impl App {
    fn new(file_path: PathBuf) -> Self {
        let mut app = Self {
            file_path: file_path.clone(),
            headers: Vec::new(),
            rows: Vec::new(),
            selected_row: 0,
            selected_col: 0,
            mode: AppMode::Normal,
            input_buffer: String::new(),
            cursor_char_idx: 0,
            status_message: String::from("Prêt. Utilisez les flèches pour naviguer, Entrée pour éditer."),
            dirty: false,
        };

        if file_path.exists() {
            if let Err(err) = app.load_csv() {
                app.status_message = format!("Erreur de lecture: {err}");
                app.init_sample_data();
            }
        } else {
            app.init_sample_data();
            app.status_message = format!("Nouveau fichier CSV: {}", file_path.display());
        }

        app
    }

    fn init_sample_data(&mut self) {
        self.headers = vec![
            "ID".to_string(),
            "Nom".to_string(),
            "Rôle".to_string(),
            "Statut".to_string(),
        ];
        self.rows = vec![
            vec!["1".into(), "Alice".into(), "Architecte Rust".into(), "Actif".into()],
            vec!["2".into(), "Bob".into(), "Dev Frontend".into(), "En pause".into()],
            vec!["3".into(), "Charlie".into(), "DevOps".into(), "Actif".into()],
        ];
        self.dirty = true;
    }

    fn load_csv(&mut self) -> Result<()> {
        let file = File::open(&self.file_path)
            .with_context(|| format!("Impossible d'ouvrir le fichier {}", self.file_path.display()))?;
        let mut rdr = csv::ReaderBuilder::new()
            .has_headers(true)
            .flexible(true)
            .from_reader(file);

        let headers = rdr.headers()?.iter().map(String::from).collect::<Vec<_>>();
        let mut rows = Vec::new();

        for result in rdr.records() {
            let record = result?;
            rows.push(record.iter().map(String::from).collect());
        }

        if headers.is_empty() {
            self.headers = vec!["Col 1".into(), "Col 2".into()];
        } else {
            self.headers = headers;
        }

        if rows.is_empty() {
            self.rows = vec![vec![String::new(); self.headers.len()]];
        } else {
            self.rows = rows;
            // Aligner le nombre de colonnes par ligne avec les headers
            for row in &mut self.rows {
                if row.len() < self.headers.len() {
                    row.resize(self.headers.len(), String::new());
                }
            }
        }

        self.selected_row = 0;
        self.selected_col = 0;
        self.status_message = format!("Fichier chargé: {}", self.file_path.display());
        self.dirty = false;
        Ok(())
    }

    fn save_csv(&mut self) -> Result<()> {
        let file = File::create(&self.file_path)
            .with_context(|| format!("Impossible d'écrire dans {}", self.file_path.display()))?;
        let mut wtr = csv::WriterBuilder::new().from_writer(file);

        wtr.write_record(&self.headers)?;
        for row in &self.rows {
            wtr.write_record(row)?;
        }
        wtr.flush()?;
        self.dirty = false;
        self.status_message = format!("Fichier enregistré: {}", self.file_path.display());
        Ok(())
    }

    fn current_cell_value(&self) -> &str {
        if let Some(row) = self.rows.get(self.selected_row) {
            if let Some(cell) = row.get(self.selected_col) {
                return cell.as_str();
            }
        }
        ""
    }

    fn set_current_cell_value(&mut self, value: String) {
        if self.selected_row >= self.rows.len() {
            self.rows.resize(self.selected_row + 1, vec![String::new(); self.headers.len()]);
        }
        let row = &mut self.rows[self.selected_row];
        if self.selected_col >= row.len() {
            row.resize(self.selected_col + 1, String::new());
        }
        row[self.selected_col] = value;
        self.dirty = true;
    }

    fn start_cell_editing(&mut self) {
        self.input_buffer = self.current_cell_value().to_string();
        self.cursor_char_idx = self.input_buffer.chars().count();
        self.mode = AppMode::EditingCell;
        self.status_message = "Mode Édition: Tapez pour modifier, Entrée pour valider, Échap pour annuler.".into();
    }

    fn insert_char(&mut self, c: char) {
        let byte_pos = self
            .input_buffer
            .char_indices()
            .map(|(idx, _)| idx)
            .nth(self.cursor_char_idx)
            .unwrap_or(self.input_buffer.len());

        self.input_buffer.insert(byte_pos, c);
        self.cursor_char_idx += 1;
    }

    fn delete_char_before(&mut self) {
        if self.cursor_char_idx > 0 {
            self.cursor_char_idx -= 1;
            let byte_pos = self
                .input_buffer
                .char_indices()
                .map(|(idx, _)| idx)
                .nth(self.cursor_char_idx)
                .unwrap_or(0);

            self.input_buffer.remove(byte_pos);
        }
    }

    fn delete_char_at(&mut self) {
        if self.cursor_char_idx < self.input_buffer.chars().count() {
            let byte_pos = self
                .input_buffer
                .char_indices()
                .map(|(idx, _)| idx)
                .nth(self.cursor_char_idx)
                .unwrap_or(self.input_buffer.len());

            self.input_buffer.remove(byte_pos);
        }
    }

    fn add_row(&mut self) {
        let col_count = self.headers.len();
        let new_row = vec![String::new(); col_count];
        if self.rows.is_empty() {
            self.rows.push(new_row);
            self.selected_row = 0;
        } else {
            self.selected_row = (self.selected_row + 1).min(self.rows.len());
            self.rows.insert(self.selected_row, new_row);
        }
        self.dirty = true;
        self.status_message = format!("Ligne {} ajoutée.", self.selected_row + 1);
    }

    fn delete_row(&mut self) {
        if self.rows.is_empty() {
            return;
        }
        self.rows.remove(self.selected_row);
        if self.rows.is_empty() {
            self.rows.push(vec![String::new(); self.headers.len()]);
            self.selected_row = 0;
        } else if self.selected_row >= self.rows.len() {
            self.selected_row = self.rows.len() - 1;
        }
        self.dirty = true;
        self.status_message = "Ligne supprimée.".into();
    }

    fn add_column(&mut self, name: String) {
        let col_name = if name.trim().is_empty() {
            format!("Col {}", self.headers.len() + 1)
        } else {
            name.trim().to_string()
        };

        self.headers.push(col_name);
        for row in &mut self.rows {
            row.push(String::new());
        }
        self.selected_col = self.headers.len() - 1;
        self.dirty = true;
        self.status_message = format!("Colonne '{}' ajoutée.", self.headers.last().unwrap_or(&String::new()));
    }

    fn delete_column(&mut self) {
        if self.headers.len() <= 1 {
            self.status_message = "Impossible de supprimer la dernière colonne.".into();
            return;
        }

        self.headers.remove(self.selected_col);
        for row in &mut self.rows {
            if self.selected_col < row.len() {
                row.remove(self.selected_col);
            }
        }

        if self.selected_col >= self.headers.len() {
            self.selected_col = self.headers.len() - 1;
        }
        self.dirty = true;
        self.status_message = "Colonne supprimée.".into();
    }
}

fn main() -> Result<()> {
    let args: Vec<String> = env::args().collect();
    let file_path = if args.len() > 1 {
        PathBuf::from(&args[1])
    } else {
        PathBuf::from("donnees.csv")
    };

    // Initialisation du terminal
    enable_raw_mode()?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen, EnableMouseCapture)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut app = App::new(file_path);
    let run_res = run_app(&mut terminal, &mut app);

    // Restauration du terminal
    disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen,
        DisableMouseCapture
    )?;
    terminal.show_cursor()?;

    if let Err(err) = run_res {
        eprintln!("Erreur lors de l'exécution: {err:?}");
    }

    Ok(())
}

fn run_app(terminal: &mut Terminal<CrosstermBackend<Stdout>>, app: &mut App) -> Result<()> {
    loop {
        terminal.draw(|f| ui(f, app))?;

        if let Event::Key(key) = event::read()? {
            if key.kind != KeyEventKind::Press {
                continue;
            }

            match app.mode {
                AppMode::Normal => match (key.modifiers, key.code) {
                    (KeyModifiers::CONTROL, KeyCode::Char('c')) | (_, KeyCode::Char('q')) => {
                        return Ok(());
                    }
                    (KeyModifiers::CONTROL, KeyCode::Char('s')) | (_, KeyCode::Char('s')) => {
                        if let Err(e) = app.save_csv() {
                            app.status_message = format!("Erreur lors de la sauvegarde: {e}");
                        }
                    }
                    (_, KeyCode::Up | KeyCode::Char('k')) => {
                        if app.selected_row > 0 {
                            app.selected_row -= 1;
                        }
                    }
                    (_, KeyCode::Down | KeyCode::Char('j')) => {
                        if !app.rows.is_empty() && app.selected_row + 1 < app.rows.len() {
                            app.selected_row += 1;
                        }
                    }
                    (_, KeyCode::Left | KeyCode::Char('h')) => {
                        if app.selected_col > 0 {
                            app.selected_col -= 1;
                        }
                    }
                    (_, KeyCode::Right | KeyCode::Char('l')) => {
                        if !app.headers.is_empty() && app.selected_col + 1 < app.headers.len() {
                            app.selected_col += 1;
                        }
                    }
                    (_, KeyCode::Enter | KeyCode::Char('e')) => {
                        app.start_cell_editing();
                    }
                    (_, KeyCode::Char('a')) => {
                        app.add_row();
                    }
                    (_, KeyCode::Char('d')) => {
                        app.delete_row();
                    }
                    (_, KeyCode::Char('c')) => {
                        app.mode = AppMode::AddingColumn;
                        app.input_buffer.clear();
                        app.cursor_char_idx = 0;
                        app.status_message = "Nouvelle colonne: Entrez le nom puis appuyez sur Entrée.".into();
                    }
                    (_, KeyCode::Char('x')) => {
                        app.delete_column();
                    }
                    _ => {}
                },
                AppMode::EditingCell => match key.code {
                    KeyCode::Enter => {
                        let new_val = app.input_buffer.clone();
                        app.set_current_cell_value(new_val);
                        app.mode = AppMode::Normal;
                        app.status_message = "Cellule modifiée.".into();
                    }
                    KeyCode::Esc => {
                        app.mode = AppMode::Normal;
                        app.status_message = "Édition annulée.".into();
                    }
                    KeyCode::Left => {
                        if app.cursor_char_idx > 0 {
                            app.cursor_char_idx -= 1;
                        }
                    }
                    KeyCode::Right => {
                        if app.cursor_char_idx < app.input_buffer.chars().count() {
                            app.cursor_char_idx += 1;
                        }
                    }
                    KeyCode::Home => {
                        app.cursor_char_idx = 0;
                    }
                    KeyCode::End => {
                        app.cursor_char_idx = app.input_buffer.chars().count();
                    }
                    KeyCode::Backspace => {
                        app.delete_char_before();
                    }
                    KeyCode::Delete => {
                        app.delete_char_at();
                    }
                    KeyCode::Char(c) => {
                        app.insert_char(c);
                    }
                    _ => {}
                },
                AppMode::AddingColumn => match key.code {
                    KeyCode::Enter => {
                        let col_name = app.input_buffer.clone();
                        app.add_column(col_name);
                        app.mode = AppMode::Normal;
                    }
                    KeyCode::Esc => {
                        app.mode = AppMode::Normal;
                        app.status_message = "Ajout de colonne annulé.".into();
                    }
                    KeyCode::Left => {
                        if app.cursor_char_idx > 0 {
                            app.cursor_char_idx -= 1;
                        }
                    }
                    KeyCode::Right => {
                        if app.cursor_char_idx < app.input_buffer.chars().count() {
                            app.cursor_char_idx += 1;
                        }
                    }
                    KeyCode::Backspace => {
                        app.delete_char_before();
                    }
                    KeyCode::Delete => {
                        app.delete_char_at();
                    }
                    KeyCode::Char(c) => {
                        app.insert_char(c);
                    }
                    _ => {}
                },
            }
        }
    }
}

fn ui(f: &mut Frame, app: &App) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // Titre & Fichier
            Constraint::Min(5),    // Table CSV
            Constraint::Length(3), // Barre de statut
            Constraint::Length(1), // Aide / Raccourcis
        ])
        .split(f.area());

    // Titre
    let title_text = format!(
        " CSV TUI EDITOR — Fichier: {} {}",
        app.file_path.display(),
        if app.dirty { "[Modifié*]" } else { "" }
    );
    let title = Paragraph::new(title_text)
        .style(Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD))
        .block(Block::default().borders(Borders::ALL).title("Tableur"));
    f.render_widget(title, chunks[0]);

    // Calcul des largeurs optimales des colonnes
    let mut col_widths: Vec<u16> = app
        .headers
        .iter()
        .map(|h| (UnicodeWidthStr::width(h.as_str()) as u16).max(8))
        .collect();

    for row in &app.rows {
        for (i, cell) in row.iter().enumerate() {
            if i < col_widths.len() {
                let cell_len = UnicodeWidthStr::width(cell.as_str()) as u16;
                col_widths[i] = col_widths[i].max(cell_len + 2);
            }
        }
    }

    // Ajout d'une colonne initiale pour le numéro de ligne "#"
    let mut header_cells = vec![Cell::from("#").style(
        Style::default()
            .fg(Color::DarkGray)
            .add_modifier(Modifier::BOLD),
    )];
    for (i, header) in app.headers.iter().enumerate() {
        let style = if i == app.selected_col {
            Style::default()
                .fg(Color::Yellow)
                .add_modifier(Modifier::BOLD | Modifier::UNDERLINED)
        } else {
            Style::default().fg(Color::White).add_modifier(Modifier::BOLD)
        };
        header_cells.push(Cell::from(header.as_str()).style(style));
    }
    let header_row = Row::new(header_cells).height(1).bottom_margin(1);

    // Détermination de la fenêtre de lignes visibles pour le scrolling vertical
    let visible_height = (chunks[1].height.saturating_sub(4)) as usize;
    let visible_height = visible_height.max(1);
    let start_row = if app.selected_row >= visible_height {
        app.selected_row.saturating_sub(visible_height - 1)
    } else {
        0
    };
    let end_row = (start_row + visible_height).min(app.rows.len());

    let mut rows_to_display = Vec::new();
    for (row_idx, row_data) in app.rows.iter().enumerate().skip(start_row).take(end_row - start_row) {
        let mut cells = vec![Cell::from(format!("{}", row_idx + 1)).style(Style::default().fg(Color::DarkGray))];

        for (col_idx, val) in row_data.iter().enumerate() {
            let is_selected = row_idx == app.selected_row && col_idx == app.selected_col;
            let cell_style = match (is_selected, &app.mode) {
                (true, AppMode::EditingCell) => Style::default()
                    .bg(Color::Blue)
                    .fg(Color::White)
                    .add_modifier(Modifier::BOLD),
                (true, _) => Style::default()
                    .bg(Color::Cyan)
                    .fg(Color::Black)
                    .add_modifier(Modifier::BOLD),
                (false, _) => Style::default().fg(Color::White),
            };

            let cell_content = if is_selected && app.mode == AppMode::EditingCell {
                format!("{}_", app.input_buffer)
            } else {
                val.clone()
            };

            cells.push(Cell::from(cell_content).style(cell_style));
        }

        let row_style = if row_idx == app.selected_row {
            Style::default().bg(Color::Rgb(30, 30, 40))
        } else {
            Style::default()
        };

        rows_to_display.push(Row::new(cells).style(row_style).height(1));
    }

    let mut constraints = vec![Constraint::Length(5)]; // Largeur pour la colonne d'index "#"
    for width in &col_widths {
        constraints.push(Constraint::Length(width.max(&12) + 2));
    }

    let table = Table::new(rows_to_display, constraints)
        .header(header_row)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .title(format!(" Données [Ligne: {}/{}, Col: {}/{}] ", 
                    if app.rows.is_empty() { 0 } else { app.selected_row + 1 },
                    app.rows.len(),
                    if app.headers.is_empty() { 0 } else { app.selected_col + 1 },
                    app.headers.len()
                )),
        );

    f.render_widget(table, chunks[1]);

    // Barre d'état
    let mode_str = match app.mode {
        AppMode::Normal => Span::styled(" [MODE: NORMAL] ", Style::default().bg(Color::Green).fg(Color::Black).add_modifier(Modifier::BOLD)),
        AppMode::EditingCell => Span::styled(" [MODE: ÉDITION] ", Style::default().bg(Color::Blue).fg(Color::White).add_modifier(Modifier::BOLD)),
        AppMode::AddingColumn => Span::styled(" [NOUVELLE COLONNE] ", Style::default().bg(Color::Magenta).fg(Color::White).add_modifier(Modifier::BOLD)),
    };

    let status_line = Line::from(vec![
        mode_str,
        Span::raw(" "),
        Span::styled(&app.status_message, Style::default().fg(Color::White)),
    ]);
    let status_widget = Paragraph::new(status_line).block(Block::default().borders(Borders::ALL));
    f.render_widget(status_widget, chunks[2]);

    // Barre d'aide / raccourcis
    let help_line = Line::from(vec![
        Span::styled(" [↑↓←→ / hjkl]", Style::default().fg(Color::Yellow)),
        Span::raw(" Naviguer  "),
        Span::styled("[Entrée/e]", Style::default().fg(Color::Yellow)),
        Span::raw(" Éditer  "),
        Span::styled("[a]", Style::default().fg(Color::Yellow)),
        Span::raw(" +Ligne  "),
        Span::styled("[d]", Style::default().fg(Color::Yellow)),
        Span::raw(" -Ligne  "),
        Span::styled("[c]", Style::default().fg(Color::Yellow)),
        Span::raw(" +Col  "),
        Span::styled("[x]", Style::default().fg(Color::Yellow)),
        Span::raw(" -Col  "),
        Span::styled("[s / Ctrl+S]", Style::default().fg(Color::Yellow)),
        Span::raw(" Sauvegarder  "),
        Span::styled("[q]", Style::default().fg(Color::Yellow)),
        Span::raw(" Quitter"),
    ]);
    let help_widget = Paragraph::new(help_line).style(Style::default().fg(Color::DarkGray));
    f.render_widget(help_widget, chunks[3]);

    // Popup modal en cas d'ajout de colonne
    if app.mode == AppMode::AddingColumn {
        let area = centered_rect(50, 20, f.area());
        f.render_widget(Clear, area);

        let input_widget = Paragraph::new(format!("{}_", app.input_buffer))
            .style(Style::default().fg(Color::Yellow))
            .block(
                Block::default()
                    .borders(Borders::ALL)
                    .title(" Nom de la nouvelle colonne (Entrée pour valider, Échap pour annuler) ")
                    .border_style(Style::default().fg(Color::Magenta)),
            );
        f.render_widget(input_widget, area);
    }
}

fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);

    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(popup_layout[1])[1]
}

