```rust
// src/main.rs
//! # quotamon - Moniteur de quotas d'espace utilisateur sous Linux
//!
//! Outil CLI de surveillance proactive des quotas et de l'espace disque utilisateur
//! avec alertes visuelles colorées en cas de saturation ou dépassement de seuil.

use anyhow::{bail, Context, Result};
use clap::{Parser, ValueEnum};
use colored::*;
use nix::sys::statvfs::statvfs;
use nix::unistd::{getuid, Uid, User};
use serde::{Deserialize, Serialize};
use std::ffi::CString;
use std::fs::File;
use std::io::{self, BufRead, BufReader, Write};
use std::path::{Path, PathBuf};
use std::process::ExitCode;
use std::thread::sleep;
use std::time::Duration;

/// Commande de quota Linux (sys/quota.h)
const USRQUOTA: i32 = 0;
const Q_GETQUOTA: i32 = 0x800007;

/// Macro QCMD équivalente en C: ((cmd) << 8) | ((type) & 0x00ff)
#[inline]
fn qcmd(cmd: i32, quota_type: i32) -> i32 {
    (cmd << 8) | (quota_type & 0x00ff)
}

/// Niveaux d'alerte pour l'état d'un quota
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize, ValueEnum)]
#[serde(rename_all = "UPPERCASE")]
pub enum AlertLevel {
    Ok,
    Warning,
    Critical,
}

impl AlertLevel {
    pub fn as_str(&self) -> &'static str {
        match self {
            AlertLevel::Ok => "NORMAL",
            AlertLevel::Warning => "AVERTISSEMENT",
            AlertLevel::Critical => "SATURATION",
        }
    }

    pub fn styled_badge(&self, no_color: bool) -> String {
        if no_color {
            return format!("[{}]", self.as_str());
        }
        match self {
            AlertLevel::Ok => format!("[{}]", self.as_str()).green().bold().to_string(),
            AlertLevel::Warning => format!("[{}]", self.as_str()).yellow().bold().to_string(),
            AlertLevel::Critical => format!("[{}]", self.as_str()).on_red().white().bold().to_string(),
        }
    }
}

/// Type de source pour les quotas mesurés
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum QuotaSource {
    /// Quota utilisateur noyau Linux (via quotactl)
    KernelQuota,
    /// Quota virtuel / espace du système de fichiers (via statvfs)
    FilesystemStat,
}

impl std::fmt::Display for QuotaSource {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            QuotaSource::KernelQuota => write!(f, "Quota noyau Linux (quotactl)"),
            QuotaSource::FilesystemStat => write!(f, "Système de fichiers (statvfs)"),
        }
    }
}

/// Entrée de point de montage extraite de /proc/mounts
#[derive(Debug, Clone)]
pub struct MountEntry {
    pub device: String,
    pub mount_point: PathBuf,
    pub fs_type: String,
    pub options: Vec<String>,
}

/// Représentation des statistiques de quotas d'espace et d'inodes
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct QuotaReport {
    pub timestamp: u64,
    pub target_path: String,
    pub user_name: String,
    pub uid: u32,
    pub device: String,
    pub fs_type: String,
    pub source: QuotaSource,
    // Espace disque
    pub used_bytes: u64,
    pub soft_limit_bytes: Option<u64>,
    pub hard_limit_bytes: Option<u64>,
    pub total_bytes: u64,
    pub space_usage_percent: f64,
    pub space_status: AlertLevel,
    pub space_grace_seconds: Option<u64>,
    // Inodes (fichiers)
    pub used_inodes: u64,
    pub soft_limit_inodes: Option<u64>,
    pub hard_limit_inodes: Option<u64>,
    pub total_inodes: Option<u64>,
    pub inode_usage_percent: Option<f64>,
    pub inode_status: AlertLevel,
    pub inode_grace_seconds: Option<u64>,
    // Statut global
    pub overall_status: AlertLevel,
}

/// Arguments de la ligne de commande
#[derive(Parser, Debug)]
#[command(
    name = "quotamon",
    author = "Damien",
    version = "0.1.0",
    about = "Moniteur de quotas d'espace utilisateur sous Linux avec alertes colorées en cas de saturation",
    long_about = "Surveille les quotas de disques et d'inodes d'un utilisateur sous Linux.\n\
                  Interroge les quotas du noyau Linux (quotactl) avec bascule automatique\n\
                  sur les capacités du système de fichiers (statvfs) ou une limite personnalisée.\n\
                  Affiche des alertes visuelles claires et des jauges colorées."
)]
pub struct CliArgs {
    /// Chemin du répertoire ou point de montage à surveiller (par défaut : répertoire HOME de l'utilisateur)
    #[arg(short = 'p', long = "path", value_name = "PATH")]
    pub path: Option<PathBuf>,

    /// Utilisateur cible à inspecter (nom d'utilisateur ou UID, défaut: utilisateur courant)
    #[arg(short = 'u', long = "user", value_name = "USER")]
    pub user: Option<String>,

    /// Quota d'espace personnalisé si les quotas noyau ne sont pas activés (ex: '50GB', '500M', '2T')
    #[arg(short = 'q', long = "quota", value_name = "SIZE")]
    pub custom_quota: Option<String>,

    /// Seuil d'avertissement 'soft limit' en pourcentage (défaut : 80.0%)
    #[arg(long = "soft", default_value_t = 80.0, value_name = "PERCENT")]
    pub soft_threshold: f64,

    /// Seuil de saturation critique 'hard limit' en pourcentage (défaut : 90.0%)
    #[arg(long = "hard", default_value_t = 90.0, value_name = "PERCENT")]
    pub hard_threshold: f64,

    /// Mode surveillance continue (actualisation toutes les N secondes)
    #[arg(short = 'w', long = "watch", value_name = "SECONDS")]
    pub watch_interval: Option<u64>,

    /// Format de sortie JSON pour intégration dans des scripts d'alerte / métriques
    #[arg(long = "json")]
    pub json: bool,

    /// Désactive les couleurs dans le terminal
    #[arg(long = "no-color", env = "NO_COLOR")]
    pub no_color: bool,

    /// Mode strict : code de retour basé sur le statut (0=OK, 1=Avertissement, 2=Saturation)
    #[arg(short = 's', long = "strict")]
    pub strict: bool,
}

/// Convertit une chaîne de taille humaine en octets (ex: 50G, 500MB, 2TiB)
pub fn parse_size_to_bytes(input: &str) -> Result<u64> {
    let s = input.trim();
    if s.is_empty() {
        bail!("La taille spécifiée est vide");
    }

    let end_of_digits = s
        .find(|c: char| !c.is_ascii_digit() && c != '.')
        .unwrap_or(s.len());

    let (val_str, unit_str) = s.split_at(end_of_digits);
    let val: f64 = val_str
        .parse()
        .with_context(|| format!("Valeur numérique invalide dans la taille: '{val_str}'"))?;

    let unit = unit_str.trim().to_uppercase();
    let multiplier: u64 = match unit.as_str() {
        "" | "B" => 1,
        "K" | "KB" | "KIB" => 1024,
        "M" | "MB" | "MIB" => 1024 * 1024,
        "G" | "GB" | "GIB" => 1024 * 1024 * 1024,
        "T" | "TB" | "TIB" => 1024 * 1024 * 1024 * 1024,
        "P" | "PB" | "PIB" => 1024 * 1024 * 1024 * 1024 * 1024,
        _ => bail!("Unité inconnue: '{unit}'. Utilisez B, K, M, G, T."),
    };

    Ok((val * (multiplier as f64)).round() as u64)
}

/// Formate un nombre d'octets en chaîne lisible (B, KiB, MiB, GiB, TiB)
pub fn format_bytes(bytes: u64) -> String {
    const KIB: u64 = 1024;
    const MIB: u64 = 1024 * 1024;
    const GIB: u64 = 1024 * 1024 * 1024;
    const TIB: u64 = 1024 * 1024 * 1024 * 1024;

    if bytes >= TIB {
        format!("{:.2} TiB", bytes as f64 / TIB as f64)
    } else if bytes >= GIB {
        format!("{:.2} GiB", bytes as f64 / GIB as f64)
    } else if bytes >= MIB {
        format!("{:.2} MiB", bytes as f64 / MIB as f64)
    } else if bytes >= KIB {
        format!("{:.2} KiB", bytes as f64 / KIB as f64)
    } else {
        format!("{bytes} B")
    }
}

/// Formate un nombre d'inodes pour un affichage clair
pub fn format_inodes(count: u64) -> String {
    if count >= 1_000_000 {
        format!("{:.2}M", count as f64 / 1_000_000.0)
    } else if count >= 1_000 {
        format!("{:.1}k", count as f64 / 1_000.0)
    } else {
        count.to_string()
    }
}

/// Résout l'utilisateur cible (nom et UID)
pub fn resolve_user(user_arg: Option<&str>) -> Result<(String, u32)> {
    match user_arg {
        Some(name_or_uid) => {
            // Vérifie si c'est un UID numérique
            if let Ok(uid_num) = name_or_uid.parse::<u32>() {
                if let Ok(Some(u)) = User::from_uid(Uid::from_raw(uid_num)) {
                    return Ok((u.name, uid_num));
                }
                return Ok((format!("uid-{uid_num}"), uid_num));
            }
            // Recherche par nom
            if let Ok(Some(u)) = User::from_name(name_or_uid) {
                return Ok((u.name, u.uid.as_raw()));
            }
            bail!("Utilisateur introuvable sur le système : '{name_or_uid}'");
        }
        None => {
            let uid = getuid();
            let name = match User::from_uid(uid) {
                Ok(Some(u)) => u.name,
                _ => format!("uid-{}", uid.as_raw()),
            };
            Ok((name, uid.as_raw()))
        }
    }
}

/// Analyse /proc/mounts pour trouver tous les points de montage
pub fn parse_mounts() -> Result<Vec<MountEntry>> {
    let file = File::open("/proc/mounts").context("Impossible de lire /proc/mounts")?;
    let reader = BufReader::new(file);
    let mut mounts = Vec::new();

    for line in reader.lines() {
        let line = line?;
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() >= 4 {
            let device = parts[0].to_string();
            let mount_point = PathBuf::from(parts[1]);
            let fs_type = parts[2].to_string();
            let options = parts[3].split(',').map(|s| s.to_string()).collect();

            mounts.push(MountEntry {
                device,
                mount_point,
                fs_type,
                options,
            });
        }
    }
    Ok(mounts)
}

/// Trouve le point de montage correspondant à un chemin donné
pub fn find_mount_for_path<'a>(path: &Path, mounts: &'a [MountEntry]) -> Result<&'a MountEntry> {
    let canonical = path
        .canonicalize()
        .unwrap_or_else(|_| path.to_path_buf());

    let mut best_match: Option<&'a MountEntry> = None;
    let mut best_len = 0;

    for m in mounts {
        if canonical.starts_with(&m.mount_point) {
            let len = m.mount_point.as_os_str().len();
            if len >= best_len {
                best_len = len;
                best_match = Some(m);
            }
        }
    }

    best_match.ok_or_else(|| anyhow::anyhow!("Aucun point de montage trouvé pour le chemin {:?}", path))
}

/// Interroge le quota noyau Linux pour un UID sur un périphérique donné
pub fn query_kernel_quota(device: &str, uid: u32) -> Result<Option<libc::dqblk>> {
    let dev_cstr = match CString::new(device) {
        Ok(c) => c,
        Err(_) => return Ok(None),
    };

    let mut dq: libc::dqblk = unsafe { std::mem::zeroed() };
    let cmd = qcmd(Q_GETQUOTA, USRQUOTA);

    let res = unsafe {
        libc::quotactl(
            cmd,
            dev_cstr.as_ptr(),
            uid as libc::c_int,
            &mut dq as *mut _ as *mut libc::c_char,
        )
    };

    if res == 0 {
        // Succès : les quotas noyau sont actifs et retournent des données
        Ok(Some(dq))
    } else {
        // -1 : quotas non activés, permission refusée ou type FS non pris en charge
        Ok(None)
    }
}

/// Génère une barre de progression graphique avec palette de couleurs
pub fn render_progress_bar(
    percent: f64,
    width: usize,
    status: AlertLevel,
    no_color: bool,
) -> String {
    let clamped = percent.clamp(0.0, 100.0);
    let filled_len = ((clamped / 100.0) * (width as f64)).round() as usize;
    let empty_len = width.saturating_sub(filled_len);

    let bar = format!(
        "{}{}",
        "█".repeat(filled_len),
        "░".repeat(empty_len)
    );

    if no_color {
        return format!("[{bar}] {percent:>5.1}%");
    }

    let colored_bar = match status {
        AlertLevel::Ok => bar.green(),
        AlertLevel::Warning => bar.yellow(),
        AlertLevel::Critical => bar.red().bold(),
    };

    format!("[{colored_bar}] {percent:>5.1}%")
}

/// Calcule le niveau d'alerte en fonction du pourcentage et des limites
pub fn compute_status(
    used: u64,
    soft_limit: Option<u64>,
    hard_limit: Option<u64>,
    soft_percent: f64,
    hard_percent: f64,
    total: u64,
) -> (f64, AlertLevel) {
    if total == 0 {
        return (0.0, AlertLevel::Ok);
    }

    let percent = (used as f64 / total as f64) * 100.0;

    // Si des limites strictes (octets/inodes) sont fournies
    if let Some(hard) = hard_limit {
        if hard > 0 && used >= hard {
            return (percent, AlertLevel::Critical);
        }
    }
    if let Some(soft) = soft_limit {
        if soft > 0 && used >= soft {
            return (percent, AlertLevel::Warning);
        }
    }

    // Sinon basée sur les pourcentages configurés
    if percent >= hard_percent {
        (percent, AlertLevel::Critical)
    } else if percent >= soft_percent {
        (percent, AlertLevel::Warning)
    } else {
        (percent, AlertLevel::Ok)
    }
}

/// Inspecte les quotas et collecte le rapport complet
pub fn inspect_quota(args: &CliArgs) -> Result<QuotaReport> {
    let (user_name, uid) = resolve_user(args.user.as_deref())?;

    // Détermination du chemin cible (défaut : répertoire $HOME de l'utilisateur ou courant)
    let target_path = match &args.path {
        Some(p) => p.clone(),
        None => {
            if let Ok(Some(u)) = User::from_uid(Uid::from_raw(uid)) {
                u.dir
            } else if let Ok(home) = std::env::var("HOME") {
                PathBuf::from(home)
            } else {
                std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
            }
        }
    };

    let mounts = parse_mounts().unwrap_or_default();
    let mount_info = find_mount_for_path(&target_path, &mounts).ok();

    let device_name = mount_info
        .map(|m| m.device.clone())
        .unwrap_or_else(|| "inconnu".to_string());
    let fs_type = mount_info
        .map(|m| m.fs_type.clone())
        .unwrap_or_else(|| "inconnu".to_string());

    // Tentative 1 : Interrogation directe des quotas noyau Linux
    let kernel_quota = query_kernel_quota(&device_name, uid)?;

    let now_ts = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);

    if let Some(dq) = kernel_quota {
        // En Linux, dqb_curspace est en octets, les limites de blocs sont en blocs de 1 Ko (1024 octets)
        let used_bytes = dq.dqb_curspace;
        let soft_limit_bytes = if dq.dqb_bsoftlimit > 0 {
            Some(dq.dqb_bsoftlimit * 1024)
        } else {
            None
        };
        let hard_limit_bytes = if dq.dqb_bhardlimit > 0 {
            Some(dq.dqb_bhardlimit * 1024)
        } else {
            None
        };

        let total_bytes = hard_limit_bytes
            .or(soft_limit_bytes)
            .unwrap_or_else(|| {
                // Si aucune limite fixée dans le quota noyau, on utilise la taille du FS
                statvfs(target_path.as_path())
                    .map(|st| (st.blocks() as u64) * (st.fragment_size() as u64))
                    .unwrap_or(used_bytes.max(1))
            });

        let (space_percent, space_status) = compute_status(
            used_bytes,
            soft_limit_bytes,
            hard_limit_bytes,
            args.soft_threshold,
            args.hard_threshold,
            total_bytes,
        );

        let space_grace = if dq.dqb_btime > 0 && dq.dqb_btime > now_ts {
            Some(dq.dqb_btime - now_ts)
        } else {
            None
        };

        // Inodes
        let used_inodes = dq.dqb_curinodes;
        let soft_inodes = if dq.dqb_isoftlimit > 0 {
            Some(dq.dqb_isoftlimit)
        } else {
            None
        };
        let hard_inodes = if dq.dqb_ihardlimit > 0 {
            Some(dq.dqb_ihardlimit)
        } else {
            None
        };

        let total_inodes = hard_inodes.or(soft_inodes);
        let (inode_percent, inode_status) = if let Some(tot_ino) = total_inodes {
            let (pct, st) = compute_status(
                used_inodes,
                soft_inodes,
                hard_inodes,
                args.soft_threshold,
                args.hard_threshold,
                tot_ino,
            );
            (Some(pct), st)
        } else {
            (None, AlertLevel::Ok)
        };

        let inode_grace = if dq.dqb_itime > 0 && dq.dqb_itime > now_ts {
            Some(dq.dqb_itime - now_ts)
        } else {
            None
        };

        let overall = std::cmp::max(space_status, inode_status);

        return Ok(QuotaReport {
            timestamp: now_ts,
            target_path: target_path.to_string_lossy().to_string(),
            user_name,
            uid,
            device: device_name,
            fs_type,
            source: QuotaSource::KernelQuota,
            used_bytes,
            soft_limit_bytes,
            hard_limit_bytes,
            total_bytes,
            space_usage_percent: space_percent,
            space_status,
            space_grace_seconds: space_grace,
            used_inodes,
            soft_limit_inodes: soft_inodes,
            hard_limit_inodes: hard_inodes,
            total_inodes,
            inode_usage_percent: inode_percent,
            inode_status,
            inode_grace_seconds: inode_grace,
            overall_status: overall,
        });
    }

    // Tentative 2 : Fallback sur le système de fichiers (statvfs)
    let stat = statvfs(target_path.as_path())
        .with_context(|| format!("Impossible d'obtenir statvfs pour le chemin {:?}", target_path))?;

    let fragment_size = stat.fragment_size() as u64;
    let fs_total_bytes = (stat.blocks() as u64) * fragment_size;
    let fs_free_bytes = (stat.blocks_available() as u64) * fragment_size;
    let fs_used_bytes = fs_total_bytes.saturating_sub(fs_free_bytes);

    // Si l'utilisateur a spécifié un quota manuel (ex: --quota 50G)
    let (total_bytes, soft_limit_bytes, hard_limit_bytes) = match &args.custom_quota {
        Some(q_str) => {
            let custom_hard = parse_size_to_bytes(q_str)?;
            let custom_soft = ((custom_hard as f64) * (args.soft_threshold / 100.0)).round() as u64;
            (custom_hard, Some(custom_soft), Some(custom_hard))
        }
        None => {
            let soft_b = ((fs_total_bytes as f64) * (args.soft_threshold / 100.0)).round() as u64;
            let hard_b = ((fs_total_bytes as f64) * (args.hard_threshold / 100.0)).round() as u64;
            (fs_total_bytes, Some(soft_b), Some(hard_b))
        }
    };

    let (space_percent, space_status) = compute_status(
        fs_used_bytes,
        soft_limit_bytes,
        hard_limit_bytes,
        args.soft_threshold,
        args.hard_threshold,
        total_bytes,
    );

    // Inodes du système de fichiers
    let total_inodes = stat.files() as u64;
    let free_inodes = stat.files_free() as u64;
    let used_inodes = total_inodes.saturating_sub(free_inodes);
    let soft_inodes = ((total_inodes as f64) * (args.soft_threshold / 100.0)).round() as u64;
    let hard_inodes = ((total_inodes as f64) * (args.hard_threshold / 100.0)).round() as u64;

    let (inode_percent, inode_status) = compute_status(
        used_inodes,
        Some(soft_inodes),
        Some(hard_inodes),
        args.soft_threshold,
        args.hard_threshold,
        total_inodes,
    );

    let overall = std::cmp::max(space_status, inode_status);

    Ok(QuotaReport {
        timestamp: now_ts,
        target_path: target_path.to_string_lossy().to_string(),
        user_name,
        uid,
        device: device_name,
        fs_type,
        source: QuotaSource::FilesystemStat,
        used_bytes: fs_used_bytes,
        soft_limit_bytes,
        hard_limit_bytes,
        total_bytes,
        space_usage_percent: space_percent,
        space_status,
        space_grace_seconds: None,
        used_inodes,
        soft_limit_inodes: Some(soft_inodes),
        hard_limit_inodes: Some(hard_inodes),
        total_inodes: Some(total_inodes),
        inode_usage_percent: Some(inode_percent),
        inode_status,
        inode_grace_seconds: None,
        overall_status: overall,
    })
}

/// Affiche le rapport de quota formaté dans la console avec alertes et couleurs
pub fn print_report(report: &QuotaReport, args: &CliArgs) {
    let no_color = args.no_color;

    // Titre / En-tête
    let banner = "================================================================================";
    let title = "          MONITEUR DE QUOTAS D'ESPACE UTILISATEUR (LINUX)";
    if no_color {
        println!("{banner}");
        println!("{title}");
        println!("{banner}");
    } else {
        println!("{}", banner.cyan());
        println!("{}", title.cyan().bold());
        println!("{}", banner.cyan());
    }

    // Informations contextuelles
    println!(
        " Utilisateur  : {} (UID: {})",
        report.user_name.bold(),
        report.uid
    );
    println!(" Cible        : {}", report.target_path);
    println!(
        " Périphérique : {} [{}]",
        report.device,
        report.fs_type.to_uppercase()
    );
    println!(" Méthode      : {}", report.source);
    println!();

    // Section 1 : Espace Disque
    let sec1_title = "--- [1] ESPACE DISQUE ET VOLUMÉTRIE ---";
    if no_color {
        println!("{sec1_title}");
    } else {
        println!("{}", sec1_title.bold().underline());
    }

    println!(
        "  Utilisé     : {:>12} / {}",
        format_bytes(report.used_bytes),
        format_bytes(report.total_bytes)
    );

    if let Some(soft) = report.soft_limit_bytes {
        println!("  Limite Soft : {:>12}", format_bytes(soft));
    }
    if let Some(hard) = report.hard_limit_bytes {
        println!("  Limite Hard : {:>12}", format_bytes(hard));
    }

    let space_bar = render_progress_bar(
        report.space_usage_percent,
        30,
        report.space_status,
        no_color,
    );
    println!("  Progression : {space_bar}  {}", report.space_status.styled_badge(no_color));

    if let Some(grace) = report.space_grace_seconds {
        let grace_msg = format!("  Période de grâce restante : {} secondes !", grace);
        if no_color {
            println!("{grace_msg}");
        } else {
            println!("{}", grace_msg.yellow().bold());
        }
    }
    println!();

    // Section 2 : Inodes (Nombre de fichiers)
    let sec2_title = "--- [2] INODES (NOMBRE DE FICHIERS) ---";
    if no_color {
        println!("{sec2_title}");
    } else {
        println!("{}", sec2_title.bold().underline());
    }

    if let Some(total_ino) = report.total_inodes {
        println!(
            "  Utilisés    : {:>12} / {}",
            format_inodes(report.used_inodes),
            format_inodes(total_ino)
        );

        if let Some(pct) = report.inode_usage_percent {
            let inode_bar = render_progress_bar(pct, 30, report.inode_status, no_color);
            println!("  Progression : {inode_bar}  {}", report.inode_status.styled_badge(no_color));
        }
    } else {
        println!("  Utilisés    : {:>12} (aucune limite configurée)", format_inodes(report.used_inodes));
    }

    if let Some(grace) = report.inode_grace_seconds {
        let grace_msg = format!("  Période de grâce inodes restante : {} secondes !", grace);
        if no_color {
            println!("{grace_msg}");
        } else {
            println!("{}", grace_msg.yellow().bold());
        }
    }
    println!();

    // Section 3 : Synthèse et Alerte Globale
    let separator = "--------------------------------------------------------------------------------";
    if no_color {
        println!("{separator}");
    } else {
        println!("{}", separator.dimmed());
    }

    match report.overall_status {
        AlertLevel::Ok => {
            let msg = " ✔ STATUT : Consommation nominale. Espace et inodes disponibles.";
            if no_color {
                println!("{msg}");
            } else {
                println!("{}", msg.green().bold());
            }
        }
        AlertLevel::Warning => {
            let msg = " ⚠ ALERTE [AVERTISSEMENT] : Seuil d'alerte (soft limit) dépassé !";
            let advice = " -> Action recommandée : Nettoyez vos caches, fichiers temporaires ou archives.";
            if no_color {
                println!("{msg}\n{advice}");
            } else {
                println!("{}", msg.yellow().bold());
                println!("{}", advice.yellow());
            }
        }
        AlertLevel::Critical => {
            let msg = " ⛔ ALERTE CRITIQUE [SATURATION] : Quota saturé ou limite hard atteinte !";
            let advice = " -> BLOCAGE IMMINENT D'ÉCRITURE : Libérez immédiatement de l'espace.";
            if no_color {
                println!("{msg}\n{advice}");
            } else {
                println!("{}", msg.on_red().white().bold());
                println!("{}", advice.red().bold());
            }
        }
    }

    if no_color {
        println!("{separator}\n");
    } else {
        println!("{}\n", separator.dimmed());
    }
}

/// Point d'entrée principal
fn main() -> ExitCode {
    let args = CliArgs::parse();

    // Mode boucle d'observation continue (--watch N)
    if let Some(interval) = args.watch_interval {
        let interval_sec = interval.max(1);
        loop {
            // Effacement d'écran pour rafraîchissement propre du terminal
            if !args.json && !args.no_color {
                print!("\x1B[2J\x1B[1;1H");
                let _ = io::stdout().flush();
            }

            match inspect_quota(&args) {
                Ok(report) => {
                    if args.json {
                        if let Ok(json_str) = serde_json::to_string_pretty(&report) {
                            println!("{json_str}");
                        }
                    } else {
                        print_report(&report, &args);
                    }
                }
                Err(err) => {
                    eprintln!("Erreur lors de l'inspection des quotas : {err:#}");
                }
            }

            sleep(Duration::from_secs(interval_sec));
        }
    }

    // Exécution ponctuelle
    match inspect_quota(&args) {
        Ok(report) => {
            if args.json {
                match serde_json::to_string_pretty(&report) {
                    Ok(json_str) => {
                        println!("{json_str}");
                    }
                    Err(e) => {
                        eprintln!("Erreur de sérialisation JSON : {e}");
                        return ExitCode::FAILURE;
                    }
                }
            } else {
                print_report(&report, &args);
            }

            // Code de sortie en mode strict
            if args.strict {
                match report.overall_status {
                    AlertLevel::Ok => ExitCode::SUCCESS,
                    AlertLevel::Warning => ExitCode::from(1),
                    AlertLevel::Critical => ExitCode::from(2),
                }
            } else {
                ExitCode::SUCCESS
            }
        }
        Err(err) => {
            eprintln!("Erreur : {err:#}");
            ExitCode::FAILURE
        }
    }
}

