#[derive(Clone, Debug)]
pub struct Transaction {
    pub id: String,
    pub sender: String,
    pub recipient: String,
    pub amount: f64,
    pub fee: f64,
    pub timestamp: DateTime<Utc>,
}

impl Transaction {
    pub fn new(sender: String, recipient: String, amount: f64, fee: f64) -> Self {
        let timestamp = Utc::now();
        let payload = format!("{}:{}:{}:{}:{}", sender, recipient, amount, fee, timestamp.timestamp_nanos_opt().unwrap_or(0));
        let mut hasher = Sha256::new();
        hasher.update(payload.as_bytes());
        let hash = format!("{:x}", hasher.finalize());
        let id = hash[..16].to_string();

        Self {
            id,
            sender,
            recipient,
            amount,
            fee,
            timestamp,
        }
    }

    pub fn coinbase(miner: &str, reward: f64) -> Self {
        Self::new("System/Coinbase".to_string(), miner.to_string(), reward, 0.0)
    }
}

#[derive(Clone, Debug)]
pub struct BlockchainBlock {
    pub index: u64,
    pub previous_hash: String,
    pub hash: String,
    pub nonce: u64,
    pub timestamp: DateTime<Utc>,
    pub miner: String,
    pub transactions: Vec<Transaction>,
    pub total_fees: f64,
    pub difficulty: usize,
}

impl BlockchainBlock {
    pub fn genesis() -> Self {
        let timestamp = Utc::now();
        let genesis_tx = Transaction::coinbase("Satoshi", 50.0);
        let mut block = Self {
            index: 0,
            previous_hash: "00000000000000000000000000000000".to_string(),
            hash: String::new(),
            nonce: 0,
            timestamp,
            miner: "Satoshi".to_string(),
            transactions: vec![genesis_tx],
            total_fees: 0.0,
            difficulty: 2,
        };
        block.hash = block.compute_hash();
        block
    }

    pub fn compute_hash(&self) -> String {
        let mut hasher = Sha256::new();
        let summary = format!(
            "{}:{}:{}:{}:{}",
            self.index,
            self.previous_hash,
            self.timestamp.timestamp_millis(),
            self.nonce,
            self.transactions.len()
        );
        hasher.update(summary.as_bytes());
        format!("{:x}", hasher.finalize())
    }

    pub fn mine(
        index: u64,
        previous_hash: String,
        miner: String,
        mut transactions: Vec<Transaction>,
        difficulty: usize,
    ) -> Self {
        let reward = 12.5;
        let total_fees: f64 = transactions.iter().map(|tx| tx.fee).sum();
        let coinbase_tx = Transaction::coinbase(&miner, reward + total_fees);
        transactions.insert(0, coinbase_tx);

        let mut block = Self {
            index,
            previous_hash,
            hash: String::new(),
            nonce: 0,
            timestamp: Utc::now(),
            miner,
            transactions,
            total_fees,
            difficulty,
        };

        let prefix = "0".repeat(difficulty);
        let mut nonce = 0u64;
        loop {
            block.nonce = nonce;
            let current_hash = block.compute_hash();
            if current_hash.starts_with(&prefix) {
                block.hash = current_hash;
                break;
            }
            nonce = nonce.wrapping_add(1);
        }

        block
    }
}

pub struct BlockchainState {
    pub blocks: Vec<BlockchainBlock>,
    pub mempool: VecDeque<Transaction>,
