    pub logs: VecDeque<String>,
    pub is_paused: bool,
    pub mining_progress: f64,
}

impl BlockchainState {
    pub fn new() -> Self {
        let genesis = BlockchainBlock::genesis();
        let mut logs = VecDeque::new();
        logs.push_back(format!(
