        ));

        Self {
            blocks: vec![genesis],
            mempool: VecDeque::new(),
            recent_transactions: VecDeque::new(),
            total_volume: 50.0,
            total_transactions_count: 1,
            logs,
            is_paused: false,
            mining_progress: 0.0,
        }
    }

    pub fn add_log(&mut self, message: String) {
        if self.logs.len() >= MAX_LOGS {
            self.logs.pop_front();
        }
        self.logs.push_back(format!(
            "[{}] {}",
            Utc::now().format("%H:%M:%S"),
            message
        ));
    }
}

#[derive(PartialEq, Eq, Clone, Copy)]
pub enum ActivePanel {
    Blocks,
    Mempool,
    Details,
}

pub struct App {
    pub blocks_table_state: TableState,
    pub mempool_list_state: ListState,
    pub active_panel: ActivePanel,
    pub should_quit: bool,
}

impl App {
    pub fn new() -> Self {
        let mut blocks_table_state = TableState::default();
        blocks_table_state.select(Some(0));

        let mut mempool_list_state = ListState::default();
        mempool_list_state.select(Some(0));

        Self {
            blocks_table_state,
            mempool_list_state,
            active_panel: ActivePanel::Blocks,
            should_quit: false,
        }
    }

    pub fn next_selection(&mut self, len: usize) {
        if len == 0 {
            return;
        }
        match self.active_panel {
            ActivePanel::Blocks => {
                let i = match self.blocks_table_state.selected() {
                    Some(i) => {
                        if i + 1 >= len {
                            0
                        } else {
                            i + 1
                        }
                    }
                    None => 0,
                };
                self.blocks_table_state.select(Some(i));
            }
            ActivePanel::Mempool => {
                let i = match self.mempool_list_state.selected() {
                    Some(i) => {
                        if i + 1 >= len {
                            0
                        } else {
                            i + 1
                        }
                    }
                    None => 0,
                };
                self.mempool_list_state.select(Some(i));
            }
            ActivePanel::Details => {}
        }
    }

    pub fn previous_selection(&mut self, len: usize) {
        if len == 0 {
            return;
        }
        match self.active_panel {
            ActivePanel::Blocks => {
                let i = match self.blocks_table_state.selected() {
                    Some(i) => {
                        if i == 0 {
                            len - 1
                        } else {
                            i - 1
                        }
                    }
                    None => 0,
                };
                self.blocks_table_state.select(Some(i));
            }
            ActivePanel::Mempool => {
                let i = match self.mempool_list_state.selected() {
                    Some(i) => {
                        if i == 0 {
                            len - 1
                        } else {
                            i - 1
                        }
                    }
                    None => 0,
                };
                self.mempool_list_state.select(Some(i));
            }
            ActivePanel::Details => {}
        }
    }

    pub fn cycle_panel(&mut self) {
        self.active_panel = match self.active_panel {
            ActivePanel::Blocks => ActivePanel::Mempool,
            ActivePanel::Mempool => ActivePanel::Details,
            ActivePanel::Details => ActivePanel::Blocks,
        };
    }
}

static PEERS: &[&str] = &[
    "Alice", "Bob", "Charlie", "David", "Eve", "Frank", "Grace", "Heidi", "Miner_1", "Miner_2",
];

async fn run_simulation(state: Arc<Mutex<BlockchainState>>) {
    let mut last_mine_tick = Instant::now();
    let mut tx_timer = tokio::time::interval(Duration::from_millis(600));

    loop {
        tx_timer.tick().await;

        let mut st = state.lock().await;
        if st.is_paused {
            continue;
        }

        // 1. Simuler l'arrivée de nouvelles transactions aléatoires
        let mut rng = rand::thread_rng();
        if st.mempool.len() < MAX_MEMPOOL_SIZE && rng.gen_bool(0.7) {
            let sender = (*PEERS.choose(&mut rng).unwrap_or(&"Alice")).to_string();
            let mut recipient = (*PEERS.choose(&mut rng).unwrap_or(&"Bob")).to_string();
            while recipient == sender {
                recipient = (*PEERS.choose(&mut rng).unwrap_or(&"Charlie")).to_string();
            }

            let amount = (rng.gen_range(0.01..15.0) * 100.0_f64).round() / 100.0;
            let fee = (rng.gen_range(0.0005..0.02) * 10000.0_f64).round() / 10000.0;
            let tx = Transaction::new(sender, recipient, amount, fee);
            st.mempool.push_back(tx);
        }

        // 2. Progression visuelle du minage (toutes les 4 secondes environ)
        let elapsed = last_mine_tick.elapsed().as_secs_f64();
        let target_duration = 3.5;
        st.mining_progress = (elapsed / target_duration).min(1.0);

        if elapsed >= target_duration {
            last_mine_tick = Instant::now();
            st.mining_progress = 0.0;

            // Sélection des transactions dans la mempool (jusqu'à 8 tx par bloc)
            let tx_count_to_take = st.mempool.len().min(8);
            let mut block_txs = Vec::with_capacity(tx_count_to_take);
            for _ in 0..tx_count_to_take {
                if let Some(tx) = st.mempool.pop_front() {
                    block_txs.push(tx);
                }
            }

            let next_index = st.blocks.len() as u64;
            let previous_hash = st
                .blocks
                .last()
                .map(|b| b.hash.clone())
                .unwrap_or_else(|| "0".repeat(32));

            let miner = (*PEERS.choose(&mut rng).unwrap_or(&"Miner_1")).to_string();
            let difficulty = 2; // Léger pour une simulation fluide sans saturer le CPU

            let new_block =
                BlockchainBlock::mine(next_index, previous_hash, miner.clone(), block_txs.clone(), difficulty);

            let added_volume: f64 = new_block.transactions.iter().map(|t| t.amount).sum();
            st.total_volume += added_volume;
            st.total_transactions_count += new_block.transactions.len() as u64;

            let log_msg = format!(
                "Bloc #{} validé par {} | {} txs | Hash: {}... | Frais: {:.4} BTC",
                new_block.index,
                miner,
                new_block.transactions.len(),
                &new_block.hash[..8],
                new_block.total_fees
            );
            st.add_log(log_msg);

            for tx in new_block.transactions.iter() {
                if st.recent_transactions.len() >= MAX_RECENT_TXS {
                    st.recent_transactions.pop_front();
                }
                st.recent_transactions.push_back(tx.clone());
            }

            st.blocks.push(new_block);
            if st.blocks.len() > MAX_BLOCKS_STORED {
                st.blocks.remove(0);
            }
        }
    }
}

#[tokio::main]
async fn main() -> IoResult<()> {
    enable_raw_mode()?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let state = Arc::new(Mutex::new(BlockchainState::new()));
    let sim_state = Arc::clone(&state);

    // Démarrage du générateur de transactions et mineur asynchrone
    tokio::spawn(async move {
        run_simulation(sim_state).await;
    });

    let mut app = App::new();
    let mut render_interval = tokio::time::interval(Duration::from_millis(100));

    loop {
        tokio::select! {
            _ = render_interval.tick() => {
                let st = state.lock().await;
                terminal.draw(|f| {
                    ui(f, &mut app, &st);
                })?;
            }
            poll_res = tokio::task::spawn_blocking(|| {
                if event::poll(Duration::from_millis(50)).unwrap_or(false) {
                    event::read().ok()
                } else {
                    None
                }
            }) => {
                if let Ok(Some(CEvent::Key(key))) = poll_res {
                    if key.kind == KeyEventKind::Press {
                        match key.code {
                            KeyCode::Char('q') | KeyCode::Esc => {
                                app.should_quit = true;
                            }
                            KeyCode::Char('c') if key.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
                                app.should_quit = true;
                            }
                            KeyCode::Tab => {
                                app.cycle_panel();
                            }
                            KeyCode::Down | KeyCode::Char('j') => {
                                let count = {
                                    let st = state.lock().await;
                                    match app.active_panel {
                                        ActivePanel::Blocks => st.blocks.len(),
                                        ActivePanel::Mempool => st.mempool.len(),
                                        ActivePanel::Details => 0,
                                    }
                                };
                                app.next_selection(count);
                            }
                            KeyCode::Up | KeyCode::Char('k') => {
                                let count = {
                                    let st = state.lock().await;
                                    match app.active_panel {
                                        ActivePanel::Blocks => st.blocks.len(),
                                        ActivePanel::Mempool => st.mempool.len(),
                                        ActivePanel::Details => 0,
                                    }
                                };
                                app.previous_selection(count);
                            }
                            KeyCode::Char('p') => {
                                let mut st = state.lock().await;
                                st.is_paused = !st.is_paused;
                                let status = if st.is_paused { "Pause" } else { "Reprise" };
                                st.add_log(format!("Simulation mise en {}", status));
                            }
                            _ => {}
                        }
                    }
                }
            }
        }

        if app.should_quit {
            break;
        }
    }

    // Restauration propre du terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    Ok(())
}

fn ui(f: &mut Frame, app: &mut App, state: &BlockchainState) {
    let size = f.area();

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3), // Titre et métriques globales
            Constraint::Length(3), // Jauge de progression du minage
            Constraint::Min(10),   // Panneaux centraux (Blocs + Mempool/Détails)
            Constraint::Length(8), // Journal des logs / événements
            Constraint::Length(1), // Barre d'aide / touches
        ])
        .split(size);

    render_header(f, chunks[0], state);
    render_mining_bar(f, chunks[1], state);

    let middle_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(55), Constraint::Percentage(45)])
        .split(chunks[2]);

    render_blocks_table(f, middle_chunks[0], app, state);

    let right_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
        .split(middle_chunks[1]);

    render_mempool(f, right_chunks[0], app, state);
    render_details(f, right_chunks[1], app, state);
    render_logs(f, chunks[3], state);
    render_footer(f, chunks[4], app, state);
}

fn render_header(f: &mut Frame, area: Rect, state: &BlockchainState) {
    let last_block = state.blocks.last();
    let current_height = last_block.map(|b| b.index).unwrap_or(0);
    let paused_status = if state.is_paused {
        Span::styled(" [PAUSE] ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))
    } else {
        Span::styled(" [ACTIF] ", Style::default().fg(Color::Green).add_modifier(Modifier::BOLD))
    };

    let title_line = Line::from(vec![
        Span::styled(" ⛓  BLOCKCHAIN TUI MONITOR ", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
        paused_status,
        Span::raw(" | "),
        Span::styled(format!("Hauteur: #{} ", current_height), Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
        Span::raw("| "),
        Span::styled(format!("Volume Émis: {:.2} BTC ", state.total_volume), Style::default().fg(Color::Yellow)),
        Span::raw("| "),
        Span::styled(format!("Total Tx: {} ", state.total_transactions_count), Style::default().fg(Color::LightMagenta)),
        Span::raw("| "),
        Span::styled(format!("Mempool: {} tx ", state.mempool.len()), Style::default().fg(Color::LightCyan)),
    ]);

    let header_widget = Paragraph::new(title_line)
        .alignment(Alignment::Center)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .border_style(Style::default().fg(Color::Cyan)),
        );

    f.render_widget(header_widget, area);
}

fn render_mining_bar(f: &mut Frame, area: Rect, state: &BlockchainState) {
    let next_height = state.blocks.last().map(|b| b.index + 1).unwrap_or(1);
    let label = format!(
        "Minage du Bloc #{} en cours... ({:.0}%)",
        next_height,
        state.mining_progress * 100.0
    );

    let gauge = Gauge::default()
        .block(
            Block::default()
                .title(" Statut Minage PoW ")
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .border_style(Style::default().fg(Color::DarkGray)),
        )
        .gauge_style(
            Style::default()
                .fg(Color::LightGreen)
                .bg(Color::Black)
                .add_modifier(Modifier::BOLD),
        )
        .ratio(state.mining_progress.clamp(0.0, 1.0))
        .label(label);

    f.render_widget(gauge, area);
}

fn render_blocks_table(f: &mut Frame, area: Rect, app: &mut App, state: &BlockchainState) {
    let is_focused = app.active_panel == ActivePanel::Blocks;
    let border_color = if is_focused { Color::LightGreen } else { Color::DarkGray };

    let header_cells = ["Index", "Hash", "Txs", "Mineur", "Frais (BTC)", "Date"]
        .iter()
        .map(|h| Cell::from(*h).style(Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)));
    let header = Row::new(header_cells).height(1).bottom_margin(1);

    // Les blocs sont affichés du plus récent au plus ancien
    let rows: Vec<Row> = state
        .blocks
        .iter()
        .rev()
        .map(|block| {
            let hash_short = if block.hash.len() >= 12 {
                format!("{}...", &block.hash[..12])
            } else {
                block.hash.clone()
            };

            let cells = vec![
                Cell::from(format!("#{}", block.index)).style(Style::default().fg(Color::White)),
                Cell::from(hash_short).style(Style::default().fg(Color::LightCyan)),
                Cell::from(block.transactions.len().to_string()).style(Style::default().fg(Color::LightGreen)),
                Cell::from(block.miner.clone()).style(Style::default().fg(Color::Magenta)),
                Cell::from(format!("{:.4}", block.total_fees)).style(Style::default().fg(Color::Yellow)),
                Cell::from(block.timestamp.format("%H:%M:%S").to_string()).style(Style::default().fg(Color::Gray)),
            ];
            Row::new(cells).height(1)
        })
        .collect();

    let widths = [
        Constraint::Length(8),
        Constraint::Length(16),
        Constraint::Length(6),
        Constraint::Length(10),
        Constraint::Length(12),
        Constraint::Min(8),
    ];

    let table = Table::new(rows, widths)
        .header(header)
        .block(
            Block::default()
                .title(" Derniers Blocs Confirmés ")
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .border_style(Style::default().fg(border_color)),
        )
        .row_highlight_style(
            Style::default()
                .bg(Color::DarkGray)
                .fg(Color::White)
                .add_modifier(Modifier::BOLD),
        )
        .highlight_symbol("▶ ");

    f.render_stateful_widget(table, area, &mut app.blocks_table_state);
}

fn render_mempool(f: &mut Frame, area: Rect, app: &mut App, state: &BlockchainState) {
    let is_focused = app.active_panel == ActivePanel::Mempool;
    let border_color = if is_focused { Color::LightGreen } else { Color::DarkGray };

    let items: Vec<ListItem> = state
        .mempool
        .iter()
        .map(|tx| {
            let content = format!(
                "Tx [{}] {} -> {} | {:.2} BTC (Frais: {:.4})",
