            );
            ListItem::new(content).style(Style::default().fg(Color::LightYellow))
        })
        .collect();

    let list = List::new(items)
        .block(
            Block::default()
                .title(format!(" Mempool ({}) ", state.mempool.len()))
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .border_style(Style::default().fg(border_color)),
        )
        .highlight_style(
            Style::default()
                .bg(Color::DarkGray)
                .fg(Color::Yellow)
                .add_modifier(Modifier::BOLD),
        )
        .highlight_symbol("▶ ");

    f.render_stateful_widget(list, area, &mut app.mempool_list_state);
}

fn render_details(f: &mut Frame, area: Rect, app: &App, state: &BlockchainState) {
    let is_focused = app.active_panel == ActivePanel::Details;
    let border_color = if is_focused { Color::LightGreen } else { Color::DarkGray };

    let selected_block = if !state.blocks.is_empty() {
        let rev_idx = app.blocks_table_state.selected().unwrap_or(0);
        let real_idx = (state.blocks.len() - 1).saturating_sub(rev_idx);
        state.blocks.get(real_idx)
    } else {
        None
    };

    let text = if let Some(b) = selected_block {
        let tx_sample: Vec<String> = b
            .transactions
            .iter()
            .take(4)
            .map(|t| {
                format!(
                    "  • {} -> {}: {:.2} BTC",
                    t.sender, t.recipient, t.amount
                )
            })
            .collect();

        let mut lines = vec![
            Line::from(vec![
                Span::styled("Bloc Numéro: ", Style::default().fg(Color::Cyan)),
                Span::raw(format!("#{}", b.index)),
            ]),
            Line::from(vec![
                Span::styled("Hash: ", Style::default().fg(Color::Cyan)),
                Span::styled(&b.hash, Style::default().fg(Color::LightCyan)),
            ]),
            Line::from(vec![
                Span::styled("Prev Hash: ", Style::default().fg(Color::Cyan)),
                Span::raw(&b.previous_hash),
            ]),
            Line::from(vec![
                Span::styled("Nonce: ", Style::default().fg(Color::Cyan)),
                Span::raw(format!("{} (Difficulté: {})", b.nonce, b.difficulty)),
            ]),
            Line::from(vec![
                Span::styled("Mineur: ", Style::default().fg(Color::Cyan)),
                Span::raw(format!("{} | Total Frais: {:.4} BTC", b.miner, b.total_fees)),
            ]),
            Line::from(Span::styled("Transactions incluses:", Style::default().fg(Color::Yellow))),
        ];

        for tx_str in tx_sample {
            lines.push(Line::from(tx_str));
        }
        if b.transactions.len() > 4 {
            lines.push(Line::from(format!(
                "  ... et {} autres transactions",
                b.transactions.len() - 4
            )));
        }

        lines
    } else {
        vec![Line::from("Aucun bloc sélectionné.")]
    };

    let paragraph = Paragraph::new(text).block(
        Block::default()
            .title(" Inspecteur de Bloc ")
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .border_style(Style::default().fg(border_color)),
    );

    f.render_widget(paragraph, area);
}

fn render_logs(f: &mut Frame, area: Rect, state: &BlockchainState) {
    let logs: Vec<ListItem> = state
        .logs
        .iter()
        .rev()
        .take(6)
        .map(|log| ListItem::new(log.as_str()).style(Style::default().fg(Color::LightBlue)))
        .collect();

    let logs_list = List::new(logs).block(
        Block::default()
            .title(" Journal des Événements & Consensus ")
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .border_style(Style::default().fg(Color::DarkGray)),
    );

    f.render_widget(logs_list, area);
}

fn render_footer(f: &mut Frame, area: Rect, _app: &App, _state: &BlockchainState) {
    let help_line = Line::from(vec![
        Span::styled(" [q/Esc]", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
