    pub relative_path: String,
    /// Taille du fichier en octets
    pub file_size: u64,
    /// Hachage direct du contenu du fichier
    pub content_hash: String,
    /// Hachage de la feuille (avec domaine et chemin)
    pub leaf_hash: String,
}

/// Preuve d'inclusion d'une feuille spécifique.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MerkleProof {
    pub relative_path: String,
    pub leaf_hash: String,
    pub siblings: Vec<SiblingStep>,
    pub expected_root: String,
}

/// Étape dans le chemin d'authentification de la preuve de Merkle.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SiblingStep {
    pub hash: String,
    pub is_right: bool,
}

/// Structure complète d'un manifeste d'arbre de Merkle sauvegardé.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MerkleManifest {
    pub root_hash: String,
    pub leaf_count: usize,
    pub leaves: Vec<LeafNode>,
}

/// Arbre de Merkle complet en mémoire.
#[derive(Debug, Clone)]
pub struct MerkleTree {
    pub leaves: Vec<LeafNode>,
    /// Niveaux successifs de l'arbre, du bas (feuilles) vers le haut (racine).
    pub levels: Vec<Vec<Hash32>>,
}

impl MerkleTree {
    /// Construit l'arbre de Merkle à partir de la liste triée de feuilles.
    pub fn build(leaves: Vec<LeafNode>) -> Result<Self> {
        if leaves.is_empty() {
            return Err(anyhow!("Impossible de construire un arbre de Merkle à partir d'une collection vide."));
        }

        let mut current_level: Vec<Hash32> = leaves
            .iter()
            .map(|leaf| {
                let bytes = hex::decode(&leaf.leaf_hash)
                    .map_err(|e| anyhow!("Hachage de feuille hexadécimal invalide: {e}"))?;
                bytes
                    .try_into()
                    .map_err(|_| anyhow!("Taille invalide pour le hachage de feuille"))
            })
            .collect::<Result<Vec<Hash32>>>()?;

        let mut levels = Vec::new();
        levels.push(current_level.clone());

        while current_level.len() > 1 {
            let next_level: Vec<Hash32> = current_level
                .par_chunks(2)
                .map(|pair| {
                    let mut hasher = Sha256::new();
                    hasher.update([NODE_DOMAIN_BYTE]);
                    hasher.update(&pair[0]);
                    if pair.len() == 2 {
                        hasher.update(&pair[1]);
                    } else {
                        // Règle canonique : duplication de la feuille impaire restante
                        hasher.update(&pair[0]);
                    }
                    hasher.finalize().into()
                })
                .collect();

            levels.push(next_level.clone());
            current_level = next_level;
        }

        Ok(Self { leaves, levels })
    }

    /// Récupère la racine de l'arbre en hexadécimal.
    pub fn root_hex(&self) -> String {
        if let Some(top) = self.levels.last().and_then(|lvl| lvl.first()) {
            hex::encode(top)
        } else {
            String::new()
        }
    }

    /// Génère une preuve d'inclusion pour un chemin relatif donné.
    pub fn generate_proof(&self, relative_path: &str) -> Result<MerkleProof> {
        let leaf_idx = self
            .leaves
            .iter()
            .position(|l| l.relative_path == relative_path)
            .ok_or_else(|| anyhow!("Fichier '{}' non trouvé dans l'arbre.", relative_path))?;

        let leaf_hash = self.leaves[leaf_idx].leaf_hash.clone();
        let mut siblings = Vec::new();
        let mut idx = leaf_idx;

        for level in &self.levels[0..self.levels.len() - 1] {
            let is_right_sibling = idx % 2 == 0;
            let sibling_idx = if is_right_sibling {
                if idx + 1 < level.len() {
                    idx + 1
                } else {
                    idx
                }
            } else {
                idx - 1
            };

            siblings.push(SiblingStep {
                hash: hex::encode(level[sibling_idx]),
                is_right: is_right_sibling,
            });

            idx /= 2;
        }

        Ok(MerkleProof {
            relative_path: relative_path.to_string(),
            leaf_hash,
            siblings,
            expected_root: self.root_hex(),
        })
    }
}

/// Vérifie une preuve d'inclusion indépendamment de l'arbre d'origine.
pub fn verify_merkle_proof(proof: &MerkleProof) -> Result<bool> {
    let mut current_hash: Hash32 = hex::decode(&proof.leaf_hash)
        .context("Hachage de feuille invalide dans la preuve")?
        .try_into()
        .map_err(|_| anyhow!("Longueur de hachage invalide"))?;

    for step in &proof.siblings {
        let sibling_hash: Hash32 = hex::decode(&step.hash)
            .context("Hachage de frère (sibling) invalide dans la preuve")?
            .try_into()
            .map_err(|_| anyhow!("Longueur de hachage invalide pour le frère"))?;

        let mut hasher = Sha256::new();
        hasher.update([NODE_DOMAIN_BYTE]);
        if step.is_right {
            hasher.update(&current_hash);
            hasher.update(&sibling_hash);
        } else {
            hasher.update(&sibling_hash);
            hasher.update(&current_hash);
        }
        current_hash = hasher.finalize().into();
    }

    let calculated_root = hex::encode(current_hash);
    Ok(calculated_root.eq_ignore_ascii_case(&proof.expected_root))
}

/// Calcule le SHA-256 du contenu d'un fichier en utilisant un mmap si possible, sinon un flux tamponné.
fn hash_file_content(path: &Path, metadata: &std::fs::Metadata) -> Result<Hash32> {
    let file = File::open(path).with_context(|| format!("Impossible d'ouvrir le fichier {}", path.display()))?;
    let file_len = metadata.len();

    // Utilisation de mmap si fichier suffisamment grand et non nul
    if file_len >= MMAP_THRESHOLD_BYTES {
        // En cas d'erreur de mmap (ex: restriction d'accès ou système spécifique), fallback sur le flux de lecture
        if let Ok(mmap) = unsafe { Mmap::map(&file) } {
            let mut hasher = Sha256::new();
            hasher.update(&mmap[..]);
            return Ok(hasher.finalize().into());
        }
    }

    // Fallback lecture par morceaux
    let mut reader = BufReader::new(file);
    let mut hasher = Sha256::new();
    let mut buffer = [0u8; 64 * 1024];

    loop {
        let count = reader
            .read(&mut buffer)
            .with_context(|| format!("Erreur de lecture du fichier {}", path.display()))?;
        if count == 0 {
            break;
        }
        hasher.update(&buffer[..count]);
    }

    Ok(hasher.finalize().into())
}

/// Calcule le hachage d'une feuille combinant le domaine, le chemin normalisé et le contenu.
fn compute_leaf_node(base_dir: &Path, entry_path: &Path) -> Result<LeafNode> {
    let metadata = std::fs::symlink_metadata(entry_path)
        .with_context(|| format!("Impossible de lire les métadonnées de {}", entry_path.display()))?;

    if !metadata.is_file() {
        return Err(anyhow!("Le chemin n'est pas un fichier régulier"));
    }

    let rel_path = entry_path
        .strip_prefix(base_dir)
        .with_context(|| format!("Impossible d'extraire le chemin relatif de {}", entry_path.display()))?;

    // Normalisation du chemin avec slash unix pour le déterminisme inter-plateformes
    let rel_path_str = rel_path
        .components()
        .map(|c| c.as_os_str().to_string_lossy())
        .collect::<Vec<_>>()
        .join("/");

    let content_hash_bytes = hash_file_content(entry_path, &metadata)?;
    let content_hash_hex = hex::encode(content_hash_bytes);

    // Calcul de la feuille : SHA256(0x00 || path || 0x00 || content_hash)
    let mut leaf_hasher = Sha256::new();
    leaf_hasher.update([LEAF_DOMAIN_BYTE]);
    leaf_hasher.update(rel_path_str.as_bytes());
    leaf_hasher.update([0x00]);
    leaf_hasher.update(&content_hash_bytes);
    let leaf_hash_bytes: Hash32 = leaf_hasher.finalize().into();

    Ok(LeafNode {
        relative_path: rel_path_str,
        file_size: metadata.len(),
        content_hash: content_hash_hex,
        leaf_hash: hex::encode(leaf_hash_bytes),
    })
}

/// Scanne et hache en parallèle tous les fichiers réguliers sous le répertoire spécifié.
pub fn scan_and_hash_directory(dir: &Path, show_progress: bool) -> Result<Vec<LeafNode>> {
    let mut file_paths = Vec::new();

    for entry in WalkDir::new(dir).follow_links(false).into_iter() {
        let entry = entry.with_context(|| "Erreur lors du parcours du répertoire")?;
        if entry.file_type().is_file() {
            file_paths.push(entry.into_path());
        }
    }

    // Tri pour garantir un ordre initial prédictible
    file_paths.sort();

    if file_paths.is_empty() {
        return Err(anyhow!("Aucun fichier régulier trouvé dans '{}'", dir.display()));
    }

    let progress_bar = if show_progress {
        let pb = ProgressBar::new(file_paths.len() as u64);
        pb.set_style(
            ProgressStyle::default_bar()
                .template("[{elapsed_precise}] [{bar:40.cyan/blue}] {pos}/{len} fichiers ({eta})")
                .map_err(|e| anyhow!("Erreur de style ProgressBar: {e}"))?
                .progress_chars("#>-"),
        );
        Some(pb)
    } else {
        None
    };

    let leaves_res: Result<Vec<LeafNode>> = if let Some(ref pb) = progress_bar {
        file_paths
            .par_iter()
            .progress_with(pb.clone())
            .map(|path| compute_leaf_node(dir, path))
            .collect()
    } else {
        file_paths
            .par_iter()
            .map(|path| compute_leaf_node(dir, path))
            .collect()
    };

    let mut leaves = leaves_res?;
    // Tri canonique strict selon le chemin relatif
    leaves.par_sort_unstable_by(|a, b| a.relative_path.cmp(&b.relative_path));

    Ok(leaves)
}

#[derive(Parser)]
#[command(
    name = "merkle-vault",
    version,
    about = "Calcul et vérification d'intégrité de larges collections de fichiers via Arbres de Merkle",
    long_about = None
)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Construit l'arbre de Merkle pour un répertoire donné
    Build(BuildArgs),
    /// Vérifie l'intégrité d'un répertoire par rapport à une racine ou un manifeste
    Verify(VerifyArgs),
    /// Génère une preuve d'inclusion pour un fichier particulier
    Proof(ProofArgs),
    /// Vérifie la validité d'une preuve d'inclusion sans recalculer tout l'arbre
    VerifyProof(VerifyProofArgs),
}

#[derive(Args)]
struct BuildArgs {
    /// Répertoire source à inspecter
    #[arg(short, long, value_parser)]
    dir: PathBuf,

    /// Chemin de sortie pour enregistrer le manifeste JSON
    #[arg(short, long, value_parser)]
    output: Option<PathBuf>,

    /// Masquer la barre de progression
    #[arg(long, default_value_t = false)]
    quiet: bool,
}

#[derive(Args)]
struct VerifyArgs {
    /// Répertoire source actuel à vérifier
    #[arg(short, long, value_parser)]
    dir: PathBuf,

    /// Chemin vers le fichier de manifeste JSON existant
    #[arg(short, long, value_parser)]
    manifest: Option<PathBuf>,

    /// Racine Merkle attendue en hexadécimal (alternative au manifeste complet)
    #[arg(short, long)]
    expected_root: Option<String>,

    /// Masquer la barre de progression
    #[arg(long, default_value_t = false)]
    quiet: bool,
}

#[derive(Args)]
struct ProofArgs {
    /// Répertoire contenant les fichiers
    #[arg(short, long, value_parser)]
    dir: PathBuf,

    /// Chemin relatif du fichier ciblé
    #[arg(short, long)]
    file: String,

    /// Fichier de sortie optionnel pour sauvegarder la preuve JSON
    #[arg(short, long, value_parser)]
    output: Option<PathBuf>,
}

#[derive(Args)]
struct VerifyProofArgs {
    /// Chemin vers le fichier de preuve au format JSON
    #[arg(short, long, value_parser)]
    proof: PathBuf,
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Build(args) => handle_build(args),
        Commands::Verify(args) => handle_verify(args),
        Commands::Proof(args) => handle_proof(args),
        Commands::VerifyProof(args) => handle_verify_proof(args),
    }
}

fn handle_build(args: BuildArgs) -> Result<()> {
    if !args.dir.is_dir() {
        return Err(anyhow!("Le chemin '{}' n'est pas un répertoire valide.", args.dir.display()));
    }

    println!("Analyse et calcul de l'arbre pour : {}", args.dir.display());
    let leaves = scan_and_hash_directory(&args.dir, !args.quiet)?;
    let tree = MerkleTree::build(leaves.clone())?;
    let root = tree.root_hex();

    println!("\n✅ Calcul terminé avec succès !");
    println!("Nombre de fichiers traités : {}", leaves.len());
    println!("Merkle Root                : {}", root);

    if let Some(out_path) = args.output {
        let manifest = MerkleManifest {
            root_hash: root,
            leaf_count: leaves.len(),
            leaves,
        };
        let file = File::create(&out_path)
            .with_context(|| format!("Impossible de créer le fichier {}", out_path.display()))?;
        serde_json::to_writer_pretty(file, &manifest)
            .with_context(|| "Erreur lors de la sérialisation du manifeste")?;
        println!("Manifeste sauvegardé dans  : {}", out_path.display());
    }

    Ok(())
}

fn handle_verify(args: VerifyArgs) -> Result<()> {
    if !args.dir.is_dir() {
        return Err(anyhow!("Le chemin '{}' n'est pas un répertoire valide.", args.dir.display()));
    }

    if let Some(manifest_path) = args.manifest {
        let file = File::open(&manifest_path)
            .with_context(|| format!("Impossible d'ouvrir le manifeste {}", manifest_path.display()))?;
        let manifest: MerkleManifest = serde_json::from_reader(file)
            .with_context(|| "Format de manifeste JSON invalide")?;

        println!("Scan du répertoire actuel pour audit complet...");
        let current_leaves = scan_and_hash_directory(&args.dir, !args.quiet)?;
        let current_tree = MerkleTree::build(current_leaves.clone())?;
        let current_root = current_tree.root_hex();

        if current_root.eq_ignore_ascii_case(&manifest.root_hash) {
            println!("\n✅ INTÉGRITÉ VALIDÉE : La racine correspond parfaitement ({})", current_root);
            println!("Nombre de fichiers validés : {}", current_leaves.len());
            return Ok(());
        }

        println!("\n❌ ÉCHEC D'INTÉGRITÉ : Divergence détectée !");
        println!("  Attendu : {}", manifest.root_hash);
        println!("  Actuel  : {}", current_root);

        // Audit détaillé des différences
        use std::collections::HashMap;
        let manifest_map: HashMap<&str, &LeafNode> = manifest.leaves.iter().map(|l| (l.relative_path.as_str(), l)).collect();
        let current_map: HashMap<&str, &LeafNode> = current_leaves.iter().map(|l| (l.relative_path.as_str(), l)).collect();

        let mut modified = 0;
        let mut deleted = 0;
        let mut added = 0;

        for (path, m_leaf) in &manifest_map {
            match current_map.get(path) {
                Some(c_leaf) => {
                    if m_leaf.leaf_hash != c_leaf.leaf_hash {
                        println!("  [MODIFIÉ] {}", path);
                        modified += 1;
                    }
                }
                None => {
                    println!("  [SUPPRIMÉ] {}", path);
                    deleted += 1;
                }
            }
        }

        for path in current_map.keys() {
            if !manifest_map.contains_key(path) {
                println!("  [AJOUTÉ] {}", path);
                added += 1;
            }
        }

        println!("\nRésumé : {} modifiés, {} supprimés, {} ajoutés.", modified, deleted, added);
        Err(anyhow!("Le répertoire ne correspond pas au manifeste."))
    } else if let Some(expected) = args.expected_root {
        println!("Calcul de l'arbre pour validation de la racine...");
        let current_leaves = scan_and_hash_directory(&args.dir, !args.quiet)?;
        let current_tree = MerkleTree::build(current_leaves)?;
        let current_root = current_tree.root_hex();

        if current_root.eq_ignore_ascii_case(&expected) {
            println!("\n✅ INTÉGRITÉ VALIDÉE : La racine calculée correspond à la racine attendue ({})", current_root);
            Ok(())
        } else {
            println!("\n❌ ÉCHEC D'INTÉGRITÉ :");
            println!("  Attendu : {}", expected);
            println!("  Actuel  : {}", current_root);
            Err(anyhow!("La racine calculée ne correspond pas."))
        }
    } else {
        Err(anyhow!("Veuillez spécifier soit --manifest (-m), soit --expected-root (-e)."))
    }
}

fn handle_proof(args: ProofArgs) -> Result<()> {
    if !args.dir.is_dir() {
        return Err(anyhow!("Le chemin '{}' n'est pas un répertoire valide.", args.dir.display()));
    }

    // Normalisation du chemin passé en argument pour la recherche
    let normalized_file = args.file.replace('\\', "/");
    let normalized_file = normalized_file.trim_start_matches('/');

    let leaves = scan_and_hash_directory(&args.dir, false)?;
    let tree = MerkleTree::build(leaves)?;
    let proof = tree.generate_proof(normalized_file)?;

    println!("✅ Preuve générée avec succès pour '{}'", normalized_file);
    println!("Racine Merkle : {}", proof.expected_root);
    println!("Nombre d'étapes (siblings) : {}", proof.siblings.len());

    if let Some(out_path) = args.output {
        let file = File::create(&out_path)
            .with_context(|| format!("Impossible de créer le fichier {}", out_path.display()))?;
        serde_json::to_writer_pretty(file, &proof)
            .with_context(|| "Erreur lors de la sauvegarde de la preuve")?;
        println!("Preuve sauvegardée dans : {}", out_path.display());
    } else {
        let json_str = serde_json::to_string_pretty(&proof)
            .with_context(|| "Erreur de sérialisation JSON")?;
        println!("\n{}", json_str);
    }

    Ok(())
}

fn handle_verify_proof(args: VerifyProofArgs) -> Result<()> {
    let file = File::open(&args.proof)
        .with_context(|| format!("Impossible d'ouvrir le fichier de preuve {}", args.proof.display()))?;
    let proof: MerkleProof = serde_json::from_reader(file)
        .with_context(|| "Format de preuve JSON invalide")?;

    let valid = verify_merkle_proof(&proof)?;

    if valid {
        println!("✅ PREUVE VALIDE : Le fichier '{}' est bien inclus dans la racine {}", proof.relative_path, proof.expected_root);
        Ok(())
    } else {
        println!("❌ PREUVE INVALIDE pour le fichier '{}'", proof.relative_path);
        Err(anyhow!("Échec de vérification cryptographique de la preuve."))
    }
}

