// src/main.rs
use clap::{Args, Parser, Subcommand};
use colored::*;
use rand::rngs::OsRng;
use rand::seq::SliceRandom;
use rand::Rng;
use std::collections::HashSet;
use std::fmt;

const UPPERCASE_CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZ";
const LOWERCASE_CHARS: &[u8] = b"abcdefghijklmnopqrstuvwxyz";
const NUMBER_CHARS: &[u8] = b"0123456789";
const SYMBOL_CHARS: &[u8] = b"!@#$%^&*()_+-=[]{}|;:,.<>?";
const AMBIGUOUS_CHARS: &[u8] = b"Il1O0o";

/// CLI pour la génération et l'analyse de mots de passe sécurisés.
#[derive(Parser, Debug)]
#[command(name = "passforge", author, version, about, long_about = None)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Génère un ou plusieurs mots de passe sécurisés selon des contraintes
    Generate(GenerateArgs),
    /// Analyse la force, l'entropie et la vulnérabilité d'un mot de passe
    Check(CheckArgs),
}

#[derive(Args, Debug, Clone)]
struct GenerateArgs {
    /// Longueur souhaitée du mot de passe
    #[arg(short = 'l', long, default_value_t = 16)]
    length: usize,

    /// Inclure des majuscules (A-Z)
    #[arg(short = 'u', long, default_value_t = true, action = clap::ArgAction::Set)]
    uppercase: bool,

    /// Inclure des minuscules (a-z)
    #[arg(short = 'm', long, default_value_t = true, action = clap::ArgAction::Set)]
    lowercase: bool,

    /// Inclure des chiffres (0-9)
    #[arg(short = 'n', long, default_value_t = true, action = clap::ArgAction::Set)]
    numbers: bool,

    /// Inclure des symboles
    #[arg(short = 's', long, default_value_t = true, action = clap::ArgAction::Set)]
    symbols: bool,

    /// Exclure les caractères visuellement ambigus (ex: l, 1, I, o, 0, O)
    #[arg(short = 'e', long, default_value_t = false)]
    exclude_ambiguous: bool,

    /// Nombre de mots de passe à générer
    #[arg(short = 'c', long, default_value_t = 1)]
    count: usize,
}

#[derive(Args, Debug)]
struct CheckArgs {
    /// Mot de passe à analyser
    password: Option<String>,
}

#[derive(Debug)]
enum GeneratorError {
    NoCharacterSetSelected,
    LengthTooShort { min_required: usize, requested: usize },
}

impl fmt::Display for GeneratorError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            GeneratorError::NoCharacterSetSelected => {
                write!(f, "Erreur : Au moins un ensemble de caractères doit être activé.")
            }
            GeneratorError::LengthTooShort { min_required, requested } => {
                write!(
                    f,
                    "Erreur : La longueur demandée ({requested}) est inférieure au nombre de catégories obligatoires ({min_required})."
                )
            }
        }
    }
}

impl std::error::Error for GeneratorError {}

/// Configuration pour la génération du mot de passe
struct PasswordGenerator;

impl PasswordGenerator {
    fn generate(args: &GenerateArgs) -> Result<String, GeneratorError> {
        let filter_ambiguous = |pool: &[u8]| -> Vec<u8> {
            if args.exclude_ambiguous {
                pool.iter()
                    .copied()
                    .filter(|b| !AMBIGUOUS_CHARS.contains(b))
                    .collect()
            } else {
                pool.to_vec()
            }
        };

        let mut mandatory_sets: Vec<Vec<u8>> = Vec::new();

        if args.uppercase {
            let pool = filter_ambiguous(UPPERCASE_CHARS);
            if !pool.is_empty() {
                mandatory_sets.push(pool);
            }
        }
        if args.lowercase {
            let pool = filter_ambiguous(LOWERCASE_CHARS);
            if !pool.is_empty() {
                mandatory_sets.push(pool);
            }
        }
        if args.numbers {
            let pool = filter_ambiguous(NUMBER_CHARS);
            if !pool.is_empty() {
                mandatory_sets.push(pool);
            }
        }
        if args.symbols {
            let pool = filter_ambiguous(SYMBOL_CHARS);
            if !pool.is_empty() {
                mandatory_sets.push(pool);
            }
        }

        if mandatory_sets.is_empty() {
            return Err(GeneratorError::NoCharacterSetSelected);
        }

        if args.length < mandatory_sets.len() {
            return Err(GeneratorError::LengthTooShort {
                min_required: mandatory_sets.len(),
                requested: args.length,
            });
        }

        let mut rng = OsRng;
        let mut password_bytes: Vec<u8> = Vec::with_capacity(args.length);

        // 1. Garantir au moins un caractère de chaque groupe sélectionné
        for set in &mandatory_sets {
            let idx = rng.gen_range(0..set.len());
            password_bytes.push(set[idx]);
        }

        // 2. Créer l'ensemble global combiné pour le reste des caractères
        let combined_pool: Vec<u8> = mandatory_sets.iter().flat_map(|s| s.clone()).collect();

        // 3. Compléter jusqu'à la longueur souhaitée
        while password_bytes.len() < args.length {
            let idx = rng.gen_range(0..combined_pool.len());
            password_bytes.push(combined_pool[idx]);
        }

        // 4. Mélanger pour éliminer l'ordre prédictible des caractères obligatoires
        password_bytes.shuffle(&mut rng);

        // Tous les caractères étant ASCII contrôlés, from_utf8 est garanti valide
        Ok(String::from_utf8(password_bytes).unwrap_or_else(|_| String::new()))
    }
}

/// Résultats d'analyse de robustesse
#[derive(Debug)]
struct PasswordAnalysis {
    length: usize,
    charset_size: usize,
    entropy_bits: f64,
    has_uppercase: bool,
    has_lowercase: bool,
    has_numbers: bool,
    has_symbols: bool,
    has_repeating_chars: bool,
    has_sequential_chars: bool,
    score: u8, // Sur 100
    strength_label: &'static str,
}

struct PasswordAnalyzer;

impl PasswordAnalyzer {
    fn analyze(password: &str) -> PasswordAnalysis {
        let length = password.chars().count();
        if length == 0 {
            return PasswordAnalysis {
                length: 0,
                charset_size: 0,
                entropy_bits: 0.0,
                has_uppercase: false,
                has_lowercase: false,
                has_numbers: false,
                has_symbols: false,
                has_repeating_chars: false,
                has_sequential_chars: false,
                score: 0,
                strength_label: "Invalide (Vide)",
            };
        }

        let mut has_upper = false;
        let mut has_lower = false;
        let mut has_digit = false;
        let mut has_symbol = false;

        let mut unique_chars = HashSet::new();

        for c in password.chars() {
            unique_chars.insert(c);
            if c.is_ascii_uppercase() {
                has_upper = true;
            } else if c.is_ascii_lowercase() {
                has_lower = true;
            } else if c.is_ascii_digit() {
                has_digit = true;
            } else {
                has_symbol = true;
            }
        }

        let mut pool_size = 0usize;
        if has_upper {
            pool_size += 26;
        }
        if has_lower {
            pool_size += 26;
        }
        if has_digit {
            pool_size += 10;
        }
        if has_symbol {
            pool_size += 32;
        }

        let entropy_bits = if pool_size > 0 {
            (length as f64) * (pool_size as f64).log2()
        } else {
            0.0
        };

        let has_repeating = Self::check_repeated_chars(password);
        let has_sequential = Self::check_sequential_patterns(password);

        let mut score: i32 = 0;

        // Longueur
        if length >= 16 {
            score += 40;
        } else if length >= 12 {
            score += 30;
        } else if length >= 8 {
            score += 15;
        } else {
            score += 5;
        }

        // Variété des catégories
        let categories_count = [has_upper, has_lower, has_digit, has_symbol]
            .iter()
            .filter(|&&b| b)
            .count();
        score += (categories_count as i32) * 10;

        // Bonus d'entropie
        if entropy_bits > 80.0 {
            score += 20;
        } else if entropy_bits > 60.0 {
            score += 10;
        }

        // Pénalités de sécurité
        if has_repeating {
            score -= 15;
        }
        if has_sequential {
            score -= 15;
        }
        if length < 8 {
            score = score.min(25);
        }

        let score = score.clamp(0, 100) as u8;

        let label = match score {
            0..=25 => "Très faible",
            26..=50 => "Faible",
            51..=70 => "Moyen",
            71..=85 => "Fort",
            _ => "Très fort",
        };

        PasswordAnalysis {
            length,
            charset_size: pool_size,
            entropy_bits,
            has_uppercase: has_upper,
            has_lowercase: has_lower,
            has_numbers: has_digit,
            has_symbols: has_symbol,
            has_repeating_chars: has_repeating,
            has_sequential_chars: has_sequential,
            score,
            strength_label: label,
        }
    }

    /// Détecte les répétitions consécutives (ex: "aaa", "111")
    fn check_repeated_chars(pwd: &str) -> bool {
        let chars: Vec<char> = pwd.chars().collect();
        if chars.len() < 3 {
            return false;
        }
        for window in chars.windows(3) {
            if window[0] == window[1] && window[1] == window[2] {
                return true;
            }
        }
        false
    }

    /// Détecte les séquences ascendantes ou descendantes (ex: "123", "abc", "cba")
    fn check_sequential_patterns(pwd: &str) -> bool {
        let chars: Vec<char> = pwd.chars().collect();
        if chars.len() < 3 {
            return false;
        }
        for window in chars.windows(3) {
            let u0 = window[0] as i32;
            let u1 = window[1] as i32;
            let u2 = window[2] as i32;

            if (u1 == u0 + 1 && u2 == u1 + 1) || (u1 == u0 - 1 && u2 == u1 - 1) {
                return true;
            }
        }
        false
    }

    /// Estimation théorique du temps de crackage hors-ligne à 10 milliards de hash/s
    fn estimate_crack_time(entropy_bits: f64) -> String {
        if entropy_bits <= 0.0 {
            return "instantané".to_string();
        }

        // Combinaisons moyennes = 2^(entropie - 1)
        let combinations = (2.0f64).powf(entropy_bits - 1.0);
        let tests_per_sec = 10_000_000_000.0f64; // 10 Giga tests/s (GPU cluster)
        let seconds = combinations / tests_per_sec;

        if seconds < 1.0 {
            "Instantané (< 1 seconde)".to_string()
        } else if seconds < 60.0 {
            format!("{:.1} secondes", seconds)
        } else if seconds < 3600.0 {
            format!("{:.1} minutes", seconds / 60.0)
        } else if seconds < 86400.0 {
            format!("{:.1} heures", seconds / 3600.0)
        } else if seconds < 31_536_000.0 {
            format!("{:.1} jours", seconds / 86400.0)
        } else if seconds < 31_536_000_000.0 {
            format!("{:.1} années", seconds / 31_536_000.0)
        } else {
            "Plusieurs siècles / Infaisable".to_string()
        }
    }
}

fn print_analysis(pwd: &str) {
    let analysis = PasswordAnalyzer::analyze(pwd);

    let score_color = match analysis.score {
