    );
    println!(
        " • Séquences (123)  : {}",
        if analysis.has_sequential_chars { "Détecté (-15 pts)".red() } else { "Aucune".green() }
    );

    println!("\n{}", "--- Recommandations ---".underline());
    if analysis.length < 12 {
        println!(" - {}", "Privilégiez une longueur d'au moins 12 à 16 caractères.".yellow());
    }
    if !analysis.has_symbols || !analysis.has_numbers || !analysis.has_uppercase || !analysis.has_lowercase {
        println!(" - {}", "Mélangez majuscules, minuscules, chiffres et caractères spéciaux.".yellow());
    }
    if analysis.has_repeating_chars || analysis.has_sequential_chars {
        println!(" - {}", "Évitez les séries de caractères prédictibles et les répétitions.".yellow());
    }
