fn main() {
    let cli = Cli::parse();

    match cli.command {
        Commands::Generate(args) => {
            println!(
                "{}",
                format!("Génération de {} mot(s) de passe (longueur: {})...", args.count, args.length)
                    .bold()
            );

            for i in 1..=args.count {
                match PasswordGenerator::generate(&args) {
                    Ok(password) => {
                        let analysis = PasswordAnalyzer::analyze(&password);
                        if args.count == 1 {
                            println!("\n{} {}", "Mot de passe généré :".bold(), password.green().bold());
                            print_analysis(&password);
                        } else {
                            println!(
                                "{:2}. {}  [Entropie: {:.1} bits | Score: {}/100]",
                                i,
                                password.green().bold(),
                                analysis.entropy_bits,
                                analysis.score
                            );
                        }
                    }
                    Err(e) => {
                        eprintln!("{}", e.to_string().red());
                        std::process::exit(1);
                    }
                }
            }
        }
        Commands::Check(args) => {
            let password = match args.password {
                Some(pwd) => pwd,
                None => {
                    println!("{}", "Entrez le mot de passe à tester :".cyan());
                    let mut input = String::new();
                    if std::io::stdin().read_line(&mut input).is_err() {
                        eprintln!("{}", "Erreur lors de la lecture de l'entrée standard.".red());
                        std::process::exit(1);
                    }
                    input.trim_end_matches(&['\r', '\n'][..]).to_string()
                }
            };

            print_analysis(&password);
        }
    }
