        26..=50 => "yellow",
        51..=70 => "bright yellow",
        71..=85 => "green",
        _ => "bright green",
    };

    println!("\n{}", "=== RAPPORT D'ANALYSE DU MOT DE PASSE ===".bold());
    println!("Longueur            : {} caractères", analysis.length);
    println!("Alphabet théorique  : {} symboles", analysis.charset_size);
    println!("Entropie brute      : {:.2} bits", analysis.entropy_bits);
    println!(
        "Évaluation globale  : {} ({}/100)",
        analysis.strength_label.color(score_color).bold(),
        analysis.score
    );
    println!(
        "Temps estimé (GPU)  : {}",
        PasswordAnalyzer::estimate_crack_time(analysis.entropy_bits).cyan()
    );

    println!("\n{}", "--- Composition & Détection ---".underline());
    println!(
        " • Minuscules       : {}",
        if analysis.has_lowercase { "✓".green() } else { "✗".red() }
    );
    println!(
        " • Majuscules       : {}",
        if analysis.has_uppercase { "✓".green() } else { "✗".red() }
    );
    println!(
        " • Chiffres         : {}",
        if analysis.has_numbers { "✓".green() } else { "✗".red() }
    );
    println!(
        " • Symboles         : {}",
        if analysis.has_symbols { "✓".green() } else { "✗".red() }
    );
    println!(
        " • Répétitions (aaa): {}",
        if analysis.has_repeating_chars { "Détecté (-15 pts)".red() } else { "Aucune".green() }
    );
    println!(
        " • Séquences (123)  : {}",
        if analysis.has_sequential_chars { "Détecté (-15 pts)".red() } else { "Aucune".green() }
    );

    println!("\n{}", "--- Recommandations ---".underline());
    if analysis.length < 12 {
        println!(" - {}", "Privilégiez une longueur d'au moins 12 à 16 caractères.".yellow());
    }
    if !analysis.has_symbols || !analysis.has_numbers || !analysis.has_uppercase || !analysis.has_lowercase {
        println!(" - {}", "Mélangez majuscules, minuscules, chiffres et caractères spéciaux.".yellow());
    }
    if analysis.has_repeating_chars || analysis.has_sequential_chars {
        println!(" - {}", "Évitez les séries de caractères prédictibles et les répétitions.".yellow());
    }
    if analysis.score >= 80 {
        println!(" - {}", "Excellent mot de passe ! Conforme aux meilleures pratiques.".green());
    }
}

fn main() {
    let cli = Cli::parse();

    match cli.command {
        Commands::Generate(args) => {
            println!(
                "{}",
                format!("Génération de {} mot(s) de passe (longueur: {})...", args.count, args.length)
                    .bold()
            );

            for i in 1..=args.count {
                match PasswordGenerator::generate(&args) {
                    Ok(password) => {
                        let analysis = PasswordAnalyzer::analyze(&password);
                        if args.count == 1 {
                            println!("\n{} {}", "Mot de passe généré :".bold(), password.green().bold());
                            print_analysis(&password);
                        } else {
                            println!(
                                "{:2}. {}  [Entropie: {:.1} bits | Score: {}/100]",
                                i,
                                password.green().bold(),
                                analysis.entropy_bits,
                                analysis.score
                            );
                        }
                    }
                    Err(e) => {
                        eprintln!("{}", e.to_string().red());
                        std::process::exit(1);
                    }
                }
            }
        }
        Commands::Check(args) => {
            let password = match args.password {
                Some(pwd) => pwd,
                None => {
                    println!("{}", "Entrez le mot de passe à tester :".cyan());
                    let mut input = String::new();
                    if std::io::stdin().read_line(&mut input).is_err() {
                        eprintln!("{}", "Erreur lors de la lecture de l'entrée standard.".red());
                        std::process::exit(1);
                    }
                    input.trim_end_matches(&['\r', '\n'][..]).to_string()
                }
            };

            print_analysis(&password);
        }
    }
