    name = "secrypt",
    about = "Outil CLI sécurisé de chiffrement symétrique de fichiers par blocs (ChaCha20-Poly1305 / AES-256-GCM)",
    version
)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Chiffrer un fichier
    Encrypt {
        /// Fichier source à chiffrer
        #[arg(short, long)]
        input: PathBuf,

        /// Fichier de sortie chiffré
        #[arg(short, long)]
        output: PathBuf,

        /// Algorithme de chiffrement AEAD
        #[arg(short, long, value_enum, default_value = "chacha20-poly1305")]
        cipher: CipherChoice,

        /// Taille d'un bloc en clair en octets
        #[arg(short, long, default_value_t = DEFAULT_BLOCK_SIZE)]
        block_size: usize,

        /// Mot de passe (optionnel, demandé interactivement si omis)
        #[arg(long)]
        password: Option<String>,
    },
    /// Déchiffrer un fichier
    Decrypt {
        /// Fichier chiffré à déchiffrer
        #[arg(short, long)]
        input: PathBuf,

        /// Fichier de sortie déchiffré
        #[arg(short, long)]
        output: PathBuf,

        /// Mot de passe (optionnel, demandé interactivement si omis)
        #[arg(long)]
        password: Option<String>,
    },
}

enum SymmetricCipher {
    ChaCha(ChaCha20Poly1305),
    Aes(Aes256Gcm),
}

impl SymmetricCipher {
    fn new(cipher_choice: CipherChoice, key: &[u8; 32]) -> Result<Self> {
        match cipher_choice {
            CipherChoice::ChaCha20Poly1305 => {
                let key_arr = GenericArray::from_slice(key);
                let cipher = ChaCha20Poly1305::new(key_arr);
                Ok(Self::ChaCha(cipher))
            }
            CipherChoice::Aes256Gcm => {
                let key_arr = GenericArray::from_slice(key);
                let cipher = Aes256Gcm::new(key_arr);
                Ok(Self::Aes(cipher))
            }
        }
    }

    fn encrypt_chunk(&self, nonce: &[u8; NONCE_LEN], aad: &[u8], plaintext: &[u8]) -> Result<Vec<u8>> {
        let nonce_ga = GenericArray::from_slice(nonce);
        let payload = Payload {
            msg: plaintext,
            aad,
        };
        match self {
            Self::ChaCha(c) => c
                .encrypt(nonce_ga, payload)
                .map_err(|e| anyhow::anyhow!("Erreur lors du chiffrement du bloc: {e}")),
            Self::Aes(c) => c
                .encrypt(nonce_ga, payload)
                .map_err(|e| anyhow::anyhow!("Erreur lors du chiffrement du bloc: {e}")),
        }
    }

    fn decrypt_chunk(&self, nonce: &[u8; NONCE_LEN], aad: &[u8], ciphertext: &[u8]) -> Result<Vec<u8>> {
        let nonce_ga = GenericArray::from_slice(nonce);
        let payload = Payload {
            msg: ciphertext,
            aad,
        };
        match self {
            Self::ChaCha(c) => c
                .decrypt(nonce_ga, payload)
                .map_err(|_| anyhow::anyhow!("Échec d'authentification ou données corrompues sur le bloc")),
            Self::Aes(c) => c
                .decrypt(nonce_ga, payload)
                .map_err(|_| anyhow::anyhow!("Échec d'authentification ou données corrompues sur le bloc")),
        }
    }
}

fn derive_key(password: &str, salt: &[u8; SALT_LEN]) -> Result<Zeroizing<[u8; 32]>> {
    let params = Params::new(64 * 1024, 3, 4, Some(32))
        .map_err(|e| anyhow::anyhow!("Paramètres Argon2 invalides: {e}"))?;
    let argon2 = Argon2::new(Algorithm::Argon2id, Version::V0x13, params);

    let mut key = [0u8; 32];
    argon2
        .hash_password_into(password.as_bytes(), salt, &mut key)
        .map_err(|e| anyhow::anyhow!("Erreur de dérivation de clé avec Argon2: {e}"))?;

    Ok(Zeroizing::new(key))
}

fn compute_chunk_nonce(base_nonce: &[u8; NONCE_LEN], chunk_index: u64) -> [u8; NONCE_LEN] {
    let mut nonce = *base_nonce;
    let index_bytes = chunk_index.to_be_bytes();
    for (i, &b) in index_bytes.iter().enumerate() {
        nonce[i] ^= b;
    }
    nonce
}

fn construct_aad(chunk_index: u64, is_last: bool) -> [u8; 9] {
    let mut aad = [0u8; 9];
    aad[..8].copy_from_slice(&chunk_index.to_be_bytes());
    aad[8] = if is_last { 1 } else { 0 };
    aad
}

fn prompt_password(confirm: bool) -> Result<Zeroizing<String>> {
    let mut pwd = rpassword::prompt_password("Entrez le mot de passe : ")
        .context("Échec de lecture du mot de passe")?;
    if confirm {
        let mut confirm_pwd = rpassword::prompt_password("Confirmez le mot de passe : ")
            .context("Échec de lecture de la confirmation")?;
        if pwd != confirm_pwd {
            pwd.zeroize();
            confirm_pwd.zeroize();
            bail!("Les mots de passe ne correspondent pas !");
        }
        confirm_pwd.zeroize();
    }
    Ok(Zeroizing::new(pwd))
}

fn encrypt_file(
    input_path: &Path,
    output_path: &Path,
    cipher_choice: CipherChoice,
    block_size: usize,
    password: &str,
) -> Result<()> {
    if block_size == 0 {
        bail!("La taille du bloc ne peut pas être égale à 0");
    }

    let input_file = File::open(input_path)
        .with_context(|| format!("Impossible d'ouvrir le fichier source : {}", input_path.display()))?;
    let mut reader = BufReader::new(input_file);

    let output_file = File::create(output_path)
        .with_context(|| format!("Impossible de créer le fichier de destination : {}", output_path.display()))?;
    let mut writer = BufWriter::new(output_file);

    let mut salt = [0u8; SALT_LEN];
    OsRng.fill_bytes(&mut salt);

    let mut base_nonce = [0u8; NONCE_LEN];
    OsRng.fill_bytes(&mut base_nonce);

    let key = derive_key(password, &salt)?;
    let cipher = SymmetricCipher::new(cipher_choice, &key)?;

    // Écriture du header
    writer.write_all(MAGIC_BYTES)?;
    writer.write_all(&[FORMAT_VERSION])?;
    writer.write_all(&[cipher_choice.to_byte()])?;
    writer.write_all(&(block_size as u32).to_be_bytes())?;
    writer.write_all(&salt)?;
    writer.write_all(&base_nonce)?;

    let mut current_buf = vec![0u8; block_size];
    let mut next_buf = vec![0u8; block_size];

    let mut current_len = reader.read(&mut current_buf)?;
    let mut chunk_index: u64 = 0;

    loop {
        let next_len = reader.read(&mut next_buf)?;
        let is_last = next_len == 0;

        let aad = construct_aad(chunk_index, is_last);
        let nonce = compute_chunk_nonce(&base_nonce, chunk_index);

        let encrypted = cipher.encrypt_chunk(&nonce, &aad, &current_buf[..current_len])?;

        let chunk_len = u32::try_from(encrypted.len())
            .context("Taille du bloc chiffré trop grande pour être représentée en 32 bits")?;

        writer.write_all(&chunk_len.to_be_bytes())?;
        writer.write_all(&[if is_last { 1 } else { 0 }])?;
        writer.write_all(&encrypted)?;

        if is_last {
            break;
        }

        std::mem::swap(&mut current_buf, &mut next_buf);
        current_len = next_len;
        chunk_index = chunk_index
            .checked_add(1)
            .context("Dépassement du nombre maximal de blocs (u64 overflow)")?;
    }

    writer.flush().context("Erreur lors de la finalisation du fichier chiffré")?;
    Ok(())
}

fn decrypt_file(input_path: &Path, output_path: &Path, password: &str) -> Result<()> {
    let input_file = File::open(input_path)
        .with_context(|| format!("Impossible d'ouvrir le fichier chiffré : {}", input_path.display()))?;
    let mut reader = BufReader::new(input_file);

    let output_file = File::create(output_path)
        .with_context(|| format!("Impossible de créer le fichier en clair : {}", output_path.display()))?;
    let mut writer = BufWriter::new(output_file);

    // Lecture de l'en-tête
    let mut magic = [0u8; 4];
    reader
        .read_exact(&mut magic)
        .context("Format de fichier invalide (impossible de lire le magic number)")?;
    if &magic != MAGIC_BYTES {
        bail!("Fichier invalide : signature magique 'SECR' absente");
    }

    let mut version = [0u8; 1];
    reader.read_exact(&mut version).context("Lecture de la version échouée")?;
    if version[0] != FORMAT_VERSION {
        bail!("Version de format non prise en charge : {}", version[0]);
    }

    let mut cipher_byte = [0u8; 1];
    reader
        .read_exact(&mut cipher_byte)
        .context("Lecture de l'identifiant cipher échouée")?;
    let cipher_choice = CipherChoice::from_byte(cipher_byte[0])?;

    let mut block_size_bytes = [0u8; 4];
    reader
        .read_exact(&mut block_size_bytes)
        .context("Lecture de la taille de bloc échouée")?;
    let block_size = u32::from_be_bytes(block_size_bytes) as usize;
    if block_size == 0 {
        bail!("Taille de bloc invalide dans l'en-tête");
    }

    let mut salt = [0u8; SALT_LEN];
    reader
        .read_exact(&mut salt)
        .context("Lecture du sel Argon2 échouée")?;

    let mut base_nonce = [0u8; NONCE_LEN];
    reader
        .read_exact(&mut base_nonce)
        .context("Lecture du nonce de base échouée")?;

    let key = derive_key(password, &salt)?;
    let cipher = SymmetricCipher::new(cipher_choice, &key)?;

    let mut chunk_index: u64 = 0;
    let mut saw_last = false;

    // Buffer réutilisable pour les données chiffrées
    let mut ciphertext_buf = Vec::new();

    while !saw_last {
        let mut len_bytes = [0u8; 4];
        match reader.read_exact(&mut len_bytes) {
            Ok(()) => {}
            Err(e) if e.kind() == io::ErrorKind::UnexpectedEof => {
                bail!("Fin de fichier inattendue : fichier tronqué avant le bloc de terminaison");
            }
            Err(e) => return Err(e).context("Erreur de lecture de l'en-tête de bloc"),
        }

        let chunk_len = u32::from_be_bytes(len_bytes) as usize;
        let mut flag_byte = [0u8; 1];
        reader
            .read_exact(&mut flag_byte)
            .context("Erreur lors de la lecture du drapeau de bloc")?;

        let is_last = flag_byte[0] == 1;
        if is_last {
            saw_last = true;
        }

        ciphertext_buf.resize(chunk_len, 0);
        reader
            .read_exact(&mut ciphertext_buf)
            .context("Erreur de lecture du contenu chiffré du bloc")?;

        let aad = construct_aad(chunk_index, is_last);
        let nonce = compute_chunk_nonce(&base_nonce, chunk_index);

        let plaintext = cipher
            .decrypt_chunk(&nonce, &aad, &ciphertext_buf)
            .with_context(|| format!("Échec du déchiffrement pour le bloc {chunk_index} (mauvais mot de passe ou altération)"))?;

        writer.write_all(&plaintext)?;

        chunk_index = chunk_index
            .checked_add(1)
            .context("Dépassement du nombre maximal de blocs (u64 overflow)")?;
    }

    let mut remaining = [0u8; 1];
    if reader.read(&mut remaining)? != 0 {
        bail!("Données superflues non authentifiées détectées après le dernier bloc");
    }

    writer.flush().context("Erreur lors de l'écriture du fichier déchiffré")?;
    Ok(())
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Encrypt {
            input,
            output,
            cipher,
            block_size,
            password,
        } => {
            let pwd = match password {
                Some(p) => Zeroizing::new(p),
                None => prompt_password(true)?,
            };

            println!(
                "Chiffrement de '{}' vers '{}' avec {:?} (taille de bloc: {} octets)...",
                input.display(),
                output.display(),
                cipher,
                block_size
            );

            encrypt_file(&input, &output, cipher, block_size, &pwd)?;
            println!("Chiffrement réussi avec succès !");
        }
        Commands::Decrypt {
            input,
            output,
            password,
        } => {
            let pwd = match password {
                Some(p) => Zeroizing::new(p),
                None => prompt_password(false)?,
            };

            println!(
                "Déchiffrement de '{}' vers '{}'...",
                input.display(),
                output.display()
            );

            decrypt_file(&input, &output, &pwd)?;
            println!("Déchiffrement réussi avec succès !");
        }
    }

    Ok(())
}

