```rust
// src/main.rs
use std::collections::HashMap;
use base64::engine::general_purpose::URL_SAFE_NO_PAD;
use base64::Engine;
use chrono::Utc;
use hmac::{Hmac, Mac};
use serde::{Deserialize, Serialize};
use sha2::{Sha256, Sha384, Sha512};
use subtle::ConstantTimeEq;
use thiserror::Error;

type HmacSha256 = Hmac<Sha256>;
type HmacSha384 = Hmac<Sha384>;
type HmacSha512 = Hmac<Sha512>;

/// Algorithmes HMAC supportés pour la validation du JWT.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum Algorithm {
    HS256,
    HS384,
    HS512,
}

impl Algorithm {
    pub fn as_str(&self) -> &'static str {
        match self {
            Algorithm::HS256 => "HS256",
            Algorithm::HS384 => "HS384",
            Algorithm::HS512 => "HS512",
        }
    }
}

/// En-tête standard d'un JSON Web Token.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Header {
    pub alg: Algorithm,
    #[serde(default = "default_typ")]
    pub typ: String,
}

fn default_typ() -> String {
    "JWT".to_string()
}

/// Charge utile (Claims) standard avec support de champs dynamiques additionnels.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Claims {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub sub: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub iss: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub aud: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub exp: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub nbf: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub iat: Option<i64>,
    #[serde(flatten)]
    pub extra: HashMap<String, serde_json::Value>,
}

/// Représentation structurée d'un JWT décodé.
#[derive(Debug, Clone)]
pub struct Jwt {
    pub header: Header,
    pub claims: Claims,
}

/// Erreurs possibles lors du décodage et de la validation.
#[derive(Error, Debug)]
pub enum JwtError {
    #[error("Format de jeton invalide (attendu: 3 segments séparés par des points)")]
    InvalidFormat,
    #[error("Erreur de décodage Base64URL : {0}")]
    Base64Decode(#[from] base64::DecodeError),
    #[error("Erreur de désérialisation JSON : {0}")]
    Json(#[from] serde_json::Error),
    #[error("Signature cryptographique invalide")]
    InvalidSignature,
    #[error("Clé secrète invalide pour HMAC : {0}")]
    InvalidKey(String),
    #[error("Le jeton a expiré (exp={exp}, actuel={now})")]
    TokenExpired { exp: i64, now: i64 },
    #[error("Le jeton n'est pas encore actif (nbf={nbf}, actuel={now})")]
    TokenNotYetValid { nbf: i64, now: i64 },
    #[error("L'émetteur (iss) ne correspond pas à l'attendu")]
    InvalidIssuer,
    #[error("L'audience (aud) ne correspond pas à l'attendue")]
    InvalidAudience,
    #[error("Algorithme non autorisé ou non attendu : attendu={expected:?}, reçu={received:?}")]
    AlgorithmMismatch {
        expected: Algorithm,
        received: Algorithm,
    },
}

/// Options de configuration pour la validation d'un JWT.
#[derive(Debug, Clone)]
pub struct ValidationOptions {
    pub expected_algorithm: Option<Algorithm>,
    pub expected_issuer: Option<String>,
    pub expected_audience: Option<String>,
    pub leeway_seconds: i64,
    pub require_exp: bool,
}

impl Default for ValidationOptions {
    fn default() -> Self {
        Self {
            expected_algorithm: Some(Algorithm::HS256),
            expected_issuer: None,
            expected_audience: None,
            leeway_seconds: 0,
            require_exp: true,
        }
    }
}

/// Calcule la signature HMAC pour des données données selon l'algorithme choisi.
fn compute_hmac(alg: Algorithm, key: &[u8], data: &[u8]) -> Result<Vec<u8>, JwtError> {
    match alg {
        Algorithm::HS256 => {
            let mut mac = HmacSha256::new_from_slice(key)
                .map_err(|e| JwtError::InvalidKey(e.to_string()))?;
            mac.update(data);
            Ok(mac.finalize().into_bytes().to_vec())
        }
        Algorithm::HS384 => {
            let mut mac = HmacSha384::new_from_slice(key)
                .map_err(|e| JwtError::InvalidKey(e.to_string()))?;
            mac.update(data);
            Ok(mac.finalize().into_bytes().to_vec())
        }
        Algorithm::HS512 => {
            let mut mac = HmacSha512::new_from_slice(key)
                .map_err(|e| JwtError::InvalidKey(e.to_string()))?;
            mac.update(data);
            Ok(mac.finalize().into_bytes().to_vec())
        }
    }
}

/// Encode un JWT à partir d'un Header, de Claims et d'une clé secrète HMAC.
pub fn encode_jwt(header: &Header, claims: &Claims, secret: &[u8]) -> Result<String, JwtError> {
    let header_json = serde_json::to_vec(header)?;
    let claims_json = serde_json::to_vec(claims)?;

    let header_b64 = URL_SAFE_NO_PAD.encode(header_json);
    let claims_b64 = URL_SAFE_NO_PAD.encode(claims_json);

    let signing_input = format!("{header_b64}.{claims_b64}");
    let signature = compute_hmac(header.alg, secret, signing_input.as_bytes())?;
    let signature_b64 = URL_SAFE_NO_PAD.encode(signature);

    Ok(format!("{signing_input}.{signature_b64}"))
}

/// Valide et décode un jeton JWT en vérifiant la signature HMAC et les contraintes temporelles.
pub fn validate_jwt(
    token: &str,
    secret: &[u8],
    options: &ValidationOptions,
) -> Result<Jwt, JwtError> {
    let parts: Vec<&str> = token.split('.').collect();
    if parts.len() != 3 {
        return Err(JwtError::InvalidFormat);
    }

    let header_b64 = parts[0];
    let claims_b64 = parts[1];
    let signature_b64 = parts[2];

    // 1. Décodage du Header
    let header_bytes = URL_SAFE_NO_PAD.decode(header_b64)?;
    let header: Header = serde_json::from_slice(&header_bytes)?;

    // Vérification de l'algorithme attendu
    if let Some(expected_alg) = options.expected_algorithm {
        if header.alg != expected_alg {
            return Err(JwtError::AlgorithmMismatch {
                expected: expected_alg,
                received: header.alg,
            });
        }
    }

    // 2. Décodage de la signature
    let signature_bytes = URL_SAFE_NO_PAD.decode(signature_b64)?;

    // 3. Vérification de la signature HMAC (comparaison en temps constant)
    let signing_input = format!("{header_b64}.{claims_b64}");
    let expected_sig = compute_hmac(header.alg, secret, signing_input.as_bytes())?;

    if signature_bytes.ct_eq(&expected_sig).unwrap_u8() != 1 {
        return Err(JwtError::InvalidSignature);
    }

    // 4. Décodage des Claims
    let claims_bytes = URL_SAFE_NO_PAD.decode(claims_b64)?;
    let claims: Claims = serde_json::from_slice(&claims_bytes)?;

    // 5. Vérification des contraintes temporelles
    let now = Utc::now().timestamp();

    if let Some(exp) = claims.exp {
        if now > exp + options.leeway_seconds {
            return Err(JwtError::TokenExpired { exp, now });
        }
    } else if options.require_exp {
        return Err(JwtError::TokenExpired { exp: 0, now });
    }

    if let Some(nbf) = claims.nbf {
        if now < nbf - options.leeway_seconds {
            return Err(JwtError::TokenNotYetValid { nbf, now });
        }
    }

    // 6. Vérifications facultatives d'émetteur et d'audience
    if let Some(expected_iss) = &options.expected_issuer {
        match &claims.iss {
            Some(iss) if iss == expected_iss => {}
            _ => return Err(JwtError::InvalidIssuer),
        }
    }

    if let Some(expected_aud) = &options.expected_audience {
        match &claims.aud {
            Some(aud) if aud == expected_aud => {}
            _ => return Err(JwtError::InvalidAudience),
        }
    }

    Ok(Jwt { header, claims })
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("=== DÉMONSTRATION DU VALIDATEUR JWT HMAC EN RUST ===");

    let secret_key = b"super-secret-cle-de-securite-robuste-2026!";
    let now = Utc::now().timestamp();

    // 1. Création d'un jeton valide (expire dans 1 heure)
    let header = Header {
        alg: Algorithm::HS256,
        typ: "JWT".to_string(),
    };

    let mut extra = HashMap::new();
    extra.insert("role".to_string(), serde_json::json!("administrateur"));
    extra.insert("email".to_string(), serde_json::json!("admin@domaine.fr"));

    let valid_claims = Claims {
        sub: Some("user_12345".to_string()),
        iss: Some("auth-service".to_string()),
        aud: Some("api-gateway".to_string()),
        exp: Some(now + 3600),
        nbf: Some(now - 10),
        iat: Some(now),
        extra,
    };

    let valid_token = encode_jwt(&header, &valid_claims, secret_key)?;
    println!("\n[1] Jeton généré :\n{}", valid_token);

    let options = ValidationOptions {
        expected_algorithm: Some(Algorithm::HS256),
        expected_issuer: Some("auth-service".to_string()),
        expected_audience: Some("api-gateway".to_string()),
        leeway_seconds: 5,
        require_exp: true,
    };

    match validate_jwt(&valid_token, secret_key, &options) {
        Ok(jwt) => {
            println!("\n  ✓ Validation réussie !");
            println!("  - Sujet : {:?}", jwt.claims.sub.as_deref().unwrap_or(""));
            println!("  - Rôle : {:?}", jwt.claims.extra.get("role"));
            println!("  - Expiration : {:?}", jwt.claims.exp);
        }
        Err(e) => println!("  ✗ Échec inattendu : {e}"),
    }

    // 2. Test avec une signature altérée
    println!("\n[2] Test : Jeton avec signature falsifiée...");
    let corrupted_token = format!("{}tampered", valid_token);
    match validate_jwt(&corrupted_token, secret_key, &options) {
        Ok(_) => println!("  ✗ Erreur : le jeton corrompu a été accepté !"),
        Err(e) => println!("  ✓ Rejet conforme attendu : {e}"),
