// src/main.rs
use std::collections::HashMap;
use std::fs::File;
use std::io::{BufReader, Read};
use std::path::{Path, PathBuf};

use anyhow::{Context, Result};
use clap::Parser;
use rayon::prelude::*;
use serde::Serialize;
use sha2::{Digest, Sha256};
use walkdir::{DirEntry, WalkDir};

/// CLI de détection de doublons de fichiers à deux niveaux (taille puis SHA-256)
#[derive(Parser, Debug)]
#[command(author, version, about, long_about = None)]
struct Cli {
    /// Chemin du répertoire à analyser
    #[arg(default_value = ".")]
    path: PathBuf,

    /// Taille minimale des fichiers à prendre en compte (en octets)
    #[arg(short = 'm', long = "min-size", default_value_t = 1)]
    min_size: u64,

    /// Inclure les fichiers et dossiers cachés (commençant par '.')
    #[arg(short = 'a', long = "all")]
    include_hidden: bool,

    /// Suivre les liens symboliques
    #[arg(short = 'L', long = "follow-links")]
    follow_links: bool,

    /// Sortie au format JSON
    #[arg(short = 'j', long = "json")]
    json: bool,

    /// Mode verbeux (affiche les erreurs de lecture et les étapes)
    #[arg(short = 'v', long = "verbose")]
    verbose: bool,
}

/// Groupe de doublons détectés
#[derive(Debug, Serialize)]
struct DuplicateGroup {
    size_bytes: u64,
    sha256_hash: String,
    files: Vec<PathBuf>,
}

/// Résumé global de l'analyse
#[derive(Debug, Serialize)]
struct ScanReport {
    scanned_directory: PathBuf,
    total_files_scanned: usize,
    candidate_size_groups: usize,
    duplicate_groups_count: usize,
    wasted_bytes: u64,
    duplicate_groups: Vec<DuplicateGroup>,
}

fn is_hidden(entry: &DirEntry) -> bool {
    entry
        .file_name()
        .to_str()
        .map(|s| s.starts_with('.') && s != "." && s != "..")
        .unwrap_or(false)
}

/// Calcule l'empreinte SHA-256 d'un fichier en flux continu (bufferisé)
fn compute_sha256(path: &Path) -> Result<String> {
    let file = File::open(path).with_context(|| format!("Impossible d'ouvrir {:?}", path))?;
    let mut reader = BufReader::with_capacity(128 * 1024, file);
    let mut hasher = Sha256::new();
    let mut buffer = [0u8; 64 * 1024];

    loop {
        let bytes_read = reader
            .read(&mut buffer)
            .with_context(|| format!("Erreur lors de la lecture de {:?}", path))?;
        if bytes_read == 0 {
            break;
        }
        hasher.update(&buffer[..bytes_read]);
    }

    Ok(hex::encode(hasher.finalize()))
}

/// Étape 1 : Indexation par taille de fichier
fn scan_and_group_by_size(
    root: &Path,
    min_size: u64,
    include_hidden: bool,
    follow_links: bool,
    verbose: bool,
) -> (HashMap<u64, Vec<PathBuf>>, usize) {
    let mut size_map: HashMap<u64, Vec<PathBuf>> = HashMap::new();
    let mut total_files_scanned = 0usize;

    let walker = WalkDir::new(root)
        .follow_links(follow_links)
        .into_iter()
        .filter_entry(|e| include_hidden || !is_hidden(e));

    for entry_result in walker {
        let entry = match entry_result {
            Ok(e) => e,
            Err(err) => {
                if verbose {
                    eprintln!("Avertissement : impossible d'accéder à l'entrée : {err}");
                }
                continue;
            }
        };

        if !entry.file_type().is_file() {
            continue;
        }

        total_files_scanned += 1;

        let metadata = match entry.metadata() {
            Ok(meta) => meta,
            Err(err) => {
                if verbose {
                    eprintln!(
                        "Avertissement : impossible de lire les métadonnées de {:?} : {err}",
                        entry.path()
                    );
                }
                continue;
            }
        };

        let file_size = metadata.len();
        if file_size >= min_size {
            size_map.entry(file_size).or_default().push(entry.into_path());
        }
    }

    (size_map, total_files_scanned)
}

/// Étape 2 : Confirmation par empreinte SHA-256 sur les groupes de même taille
fn find_duplicates_by_hash(
    candidates_by_size: HashMap<u64, Vec<PathBuf>>,
    verbose: bool,
) -> Vec<DuplicateGroup> {
    // Ne conserver que les groupes de taille contenant au moins 2 fichiers
    let filtered_candidates: Vec<(u64, Vec<PathBuf>)> = candidates_by_size
        .into_iter()
        .filter(|(_, files)| files.len() > 1)
        .collect();

    // Traitement parallèle des groupes de candidats
    filtered_candidates
        .into_par_iter()
        .flat_map(|(size_bytes, files)| {
            // Hacher les fichiers du groupe
            let hashed_files: Vec<(PathBuf, Option<String>)> = files
                .into_par_iter()
                .map(|path| match compute_sha256(&path) {
                    Ok(hash) => (path, Some(hash)),
                    Err(err) => {
                        if verbose {
                            eprintln!("Avertissement : hachage échoué pour {path:?} : {err}");
                        }
                        (path, None)
                    }
                })
                .collect();

            // Regrouper par empreinte SHA-256
            let mut hash_map: HashMap<String, Vec<PathBuf>> = HashMap::new();
            for (path, hash_opt) in hashed_files {
                if let Some(hash) = hash_opt {
                    hash_map.entry(hash).or_default().push(path);
                }
            }

            // Conserver uniquement les empreintes partagées par au moins 2 fichiers
            let duplicates: Vec<DuplicateGroup> = hash_map
                .into_iter()
                .filter(|(_, file_list)| file_list.len() > 1)
                .map(|(sha256_hash, mut files)| {
                    files.sort();
                    DuplicateGroup {
                        size_bytes,
                        sha256_hash,
                        files,
                    }
                })
                .collect();

            duplicates
        })
        .collect()
}

fn format_bytes(bytes: u64) -> String {
    const KIB: u64 = 1024;
    const MIB: u64 = KIB * 1024;
    const GIB: u64 = MIB * 1024;

    if bytes >= GIB {
        format!("{:.2} GiB", bytes as f64 / GIB as f64)
    } else if bytes >= MIB {
        format!("{:.2} MiB", bytes as f64 / MIB as f64)
    } else if bytes >= KIB {
        format!("{:.2} KiB", bytes as f64 / KIB as f64)
    } else {
        format!("{bytes} B")
    }
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    if !cli.path.exists() {
        anyhow::bail!("Le chemin spécifié n'existe pas : {:?}", cli.path);
    }

    if cli.verbose && !cli.json {
        eprintln!(
            "Phase 1 : Analyse de l'arborescence et groupement par taille ({:?})...",
            cli.path
        );
    }

    let (size_map, total_scanned) = scan_and_group_by_size(
        &cli.path,
        cli.min_size,
        cli.include_hidden,
        cli.follow_links,
        cli.verbose,
    );

    let candidate_groups_count = size_map.values().filter(|v| v.len() > 1).count();

    if cli.verbose && !cli.json {
        eprintln!(
            "Fichiers scannés : {total_scanned}. Groupes candidats de même taille : {candidate_groups_count}."
        );
        eprintln!("Phase 2 : Calcul des empreintes SHA-256 pour vérification des doublons...");
    }

    let mut duplicate_groups = find_duplicates_by_hash(size_map, cli.verbose);

    // Tri pour un affichage stable et ordonné (du plus volumineux au plus petit)
    duplicate_groups.sort_by(|a, b| {
        b.size_bytes
            .cmp(&a.size_bytes)
            .then_with(|| a.sha256_hash.cmp(&b.sha256_hash))
    });

    // Calcul de l'espace gaspillé (somme de (nb_copies - 1) * taille)
    let wasted_bytes: u64 = duplicate_groups
        .iter()
        .map(|g| (g.files.len() as u64 - 1) * g.size_bytes)
        .sum();

    let report = ScanReport {
        scanned_directory: cli.path.clone(),
        total_files_scanned: total_scanned,
        candidate_size_groups: candidate_groups_count,
        duplicate_groups_count: duplicate_groups.len(),
        wasted_bytes,
        duplicate_groups,
    };

    if cli.json {
        let json_output = serde_json::to_string_pretty(&report)
            .context("Erreur lors de la sérialisation JSON")?;
        println!("{json_output}");
    } else {
        println!("============================================================");
        println!("             RÉSULTAT DE LA DÉTECTION DE DOUBLONS           ");
        println!("============================================================");
        println!("Dossier analysé        : {:?}", report.scanned_directory);
        println!("Fichiers éligibles vus : {}", report.total_files_scanned);
        println!("Groupes candidats      : {}", report.candidate_size_groups);
        println!("Groupes de doublons    : {}", report.duplicate_groups_count);
        println!("Espace gaspillé estimé : {}", format_bytes(report.wasted_bytes));
        println!("------------------------------------------------------------\n");

        if report.duplicate_groups.is_empty() {
            println!("Aucun fichier doublon trouvé.");
        } else {
            for (idx, group) in report.duplicate_groups.iter().enumerate() {
                println!(
                    "[{}] Taille: {} ({} octets) | SHA-256: {}",
                    idx + 1,
                    format_bytes(group.size_bytes),
                    group.size_bytes,
                    group.sha256_hash
                );
                for file in &group.files {
                    println!("  -> {}", file.display());
                }
                println!();
            }
        }
    }

    Ok(())
}

