// src/main.rs
use clap::{Args, Parser, Subcommand, ValueEnum};
use data_encoding::BASE32_NOPAD;
use hmac::{Hmac, Mac};
use rand::rngs::OsRng;
use rand::RngCore;
use sha1::Sha1;
use sha2::{Sha256, Sha512};
use std::fmt;
use std::time::{SystemTime, UNIX_EPOCH};
use subtle::ConstantTimeEq;
use thiserror::Error;

type HmacSha1 = Hmac<Sha1>;
type HmacSha256 = Hmac<Sha256>;
type HmacSha512 = Hmac<Sha512>;

#[derive(Error, Debug)]
pub enum OtpError {
    #[error("Erreur de décodage Base32 : {0}")]
    Base32DecodeError(#[from] data_encoding::DecodeError),

    #[error("Secret vide ou invalide pour l'initialisation HMAC")]
    InvalidSecret,

    #[error("Erreur d'horloge système (timestamp antérieur à l'époque Unix)")]
    SystemTimeError,

    #[error("Nombre de chiffres invalide : {0} (doit être compris entre 6 et 8)")]
    InvalidDigits(u32),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
pub enum Algorithm {
    Sha1,
    Sha256,
    Sha512,
}

impl Algorithm {
    pub fn as_str(&self) -> &'static str {
        match self {
            Algorithm::Sha1 => "SHA1",
            Algorithm::Sha256 => "SHA256",
            Algorithm::Sha512 => "SHA512",
        }
    }
}

impl fmt::Display for Algorithm {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.as_str())
    }
}

#[derive(Debug, Clone)]
pub struct Totp {
    secret: Vec<u8>,
    algorithm: Algorithm,
    digits: u32,
    period: u64,
}

impl Totp {
    pub fn new(secret_bytes: Vec<u8>, algorithm: Algorithm, digits: u32, period: u64) -> Result<Self, OtpError> {
        if !(6..=8).contains(&digits) {
            return Err(OtpError::InvalidDigits(digits));
        }
        if secret_bytes.is_empty() {
            return Err(OtpError::InvalidSecret);
        }
        Ok(Self {
            secret: secret_bytes,
            algorithm,
            digits,
            period,
        })
    }

    pub fn from_base32(
        secret_b32: &str,
        algorithm: Algorithm,
        digits: u32,
        period: u64,
    ) -> Result<Self, OtpError> {
        let clean_secret: String = secret_b32
            .chars()
            .filter(|c| !c.is_whitespace() && *c != '=')
            .collect::<String>()
            .to_ascii_uppercase();

        let secret_bytes = BASE32_NOPAD.decode(clean_secret.as_bytes())?;
        Self::new(secret_bytes, algorithm, digits, period)
    }

    pub fn generate_secret_b32(length: usize) -> String {
        let mut bytes = vec![0u8; length];
        OsRng.fill_bytes(&mut bytes);
        BASE32_NOPAD.encode(&bytes)
    }

    fn compute_hmac(&self, counter: u64) -> Vec<u8> {
        let counter_bytes = counter.to_be_bytes();
        match self.algorithm {
            Algorithm::Sha1 => {
                let mut mac = HmacSha1::new_from_slice(&self.secret)
                    .unwrap_or_else(|_| HmacSha1::new_from_slice(&[0u8]).expect("HMAC-SHA1 init"));
                mac.update(&counter_bytes);
                mac.finalize().into_bytes().to_vec()
            }
            Algorithm::Sha256 => {
                let mut mac = HmacSha256::new_from_slice(&self.secret)
                    .unwrap_or_else(|_| HmacSha256::new_from_slice(&[0u8]).expect("HMAC-SHA256 init"));
                mac.update(&counter_bytes);
                mac.finalize().into_bytes().to_vec()
            }
            Algorithm::Sha512 => {
                let mut mac = HmacSha512::new_from_slice(&self.secret)
                    .unwrap_or_else(|_| HmacSha512::new_from_slice(&[0u8]).expect("HMAC-SHA512 init"));
                mac.update(&counter_bytes);
                mac.finalize().into_bytes().to_vec()
            }
        }
    }

    pub fn hotp(&self, counter: u64) -> String {
        let digest = self.compute_hmac(counter);
        let offset = (digest.last().copied().unwrap_or(0) & 0x0f) as usize;

        let code = ((u32::from(digest[offset] & 0x7f) << 24)
            | (u32::from(digest[offset + 1]) << 16)
            | (u32::from(digest[offset + 2]) << 8)
            | u32::from(digest[offset + 3]))
            % 10u32.pow(self.digits);

        format!("{:0width$}", code, width = self.digits as usize)
    }

    pub fn generate_at_timestamp(&self, timestamp: u64) -> String {
        let counter = timestamp / self.period;
        self.hotp(counter)
    }

    pub fn generate_now(&self) -> Result<(String, u64), OtpError> {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map_err(|_| OtpError::SystemTimeError)?
            .as_secs();

        let token = self.generate_at_timestamp(now);
        let remaining_seconds = self.period - (now % self.period);
        Ok((token, remaining_seconds))
    }

    pub fn verify(&self, token: &str, timestamp: u64, tolerance_windows: u64) -> bool {
        let current_step = timestamp / self.period;
        let token_bytes = token.trim().as_bytes();

        let start = current_step.saturating_sub(tolerance_windows);
        let end = current_step.saturating_add(tolerance_windows);

        for step in start..=end {
            let expected = self.hotp(step);
            if expected.as_bytes().ct_eq(token_bytes).into() {
                return true;
            }
        }
        false
    }

    pub fn verify_now(&self, token: &str, tolerance_windows: u64) -> Result<bool, OtpError> {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map_err(|_| OtpError::SystemTimeError)?
            .as_secs();

        Ok(self.verify(token, now, tolerance_windows))
    }

    pub fn to_key_uri(&self, label: &str, issuer: &str) -> String {
        let secret_b32 = BASE32_NOPAD.encode(&self.secret);
        let encoded_label = urlencoding::encode(label);
        let encoded_issuer = urlencoding::encode(issuer);

        format!(
            "otpauth://totp/{}?secret={}&issuer={}&algorithm={}&digits={}&period={}",
            encoded_label, secret_b32, encoded_issuer, self.algorithm, self.digits, self.period
        )
    }
}

