fn run_demo() -> Result<(), Box<dyn std::error::Error>> {
    println!("=== DÉMONSTRATION TOTP RFC 6238 ===");

    // 1. Vecteur de test officiel RFC 6238 avec SHA1 (8 chiffres)
    // Secret standard RFC 6238 : "12345678901234567890" en ASCII
    let rfc_secret = b"12345678901234567890".to_vec();
    let rfc_totp = Totp::new(rfc_secret.clone(), Algorithm::Sha1, 8, 30)?;

    println!("\n1. Test de conformité aux vecteurs officiels RFC 6238 (SHA1, 8 chiffres) :");
    let test_cases: &[(u64, &str)] = &[
        (59, "94287082"),
        (1111111109, "07081804"),
        (1111111111, "14050471"),
        (1234567890, "89005924"),
        (2000000000, "69279037"),
    ];

    for (ts, expected) in test_cases {
        let code = rfc_totp.generate_at_timestamp(*ts);
        assert_eq!(&code, expected, "Vérification RFC pour T={ts}");
        println!(" - Timestamp {}s -> Code: {} [CONFORME]", ts, code);
    }

    // 2. Génération de secret aléatoire
    println!("\n2. Génération d'une nouvelle clé secrète aléatoire :");
    let new_secret = Totp::generate_secret_b32(20);
    println!(" - Secret généré (Base32) : {}", new_secret);

    // 3. Instanciation et génération TOTP
    let user_totp = Totp::from_base32(&new_secret, Algorithm::Sha1, 6, 30)?;
    let (token, remaining) = user_totp.generate_now()?;
    println!(" - Jeton 6 chiffres généré : {}", token);
    println!(" - Valide pour encore : {}s", remaining);

    // 4. Validation immédiate (temps constant)
    let is_valid = user_totp.verify_now(&token, 1)?;
    println!(" - Vérification du jeton : {}", if is_valid { "SUCCÈS" } else { "ÉCHEC" });

    // 5. Test avec mauvais code
    let is_bad_valid = user_totp.verify_now("000000", 1)?;
    println!(" - Vérification faux jeton ('000000') : {}", if !is_bad_valid { "REJETÉ (Correct)" } else { "ACCEPTÉ (Erreur)" });

    // 6. URI QR Code
    let uri = user_totp.to_key_uri("ServiceSecurise:alice@example.com", "ServiceSecurise");
    println!("\n3. URI Key Format pour QR Code :");
    println!(" - {}", uri);

    println!("\nDémonstration terminée avec succès !");
    Ok(())
}

