        let secret = b"1234567890123456789012345678901234567890123456789012345678901234".to_vec();
        let totp = Totp::new(secret, Algorithm::Sha512, 8, 30).expect("Initialisation valide");

        assert_eq!(totp.generate_at_timestamp(59), "90693936");
        assert_eq!(totp.generate_at_timestamp(1111111109), "25091201");
        assert_eq!(totp.generate_at_timestamp(1111111111), "99943326");
        assert_eq!(totp.generate_at_timestamp(1234567890), "93441116");
        assert_eq!(totp.generate_at_timestamp(2000000000), "38618901");
        assert_eq!(totp.generate_at_timestamp(20000000000), "47863826");
    }

    #[test]
    fn test_tolerance_window_verification() {
        let secret = b"12345678901234567890".to_vec();
        let totp = Totp::new(secret, Algorithm::Sha1, 6, 30).expect("Initialisation");

        // Utilisons un début exact de période pour tester clairement la fenêtre
        let base_ts = 990u64; // 990 / 30 = 33
        let token = totp.generate_at_timestamp(base_ts);

        // Dans la même fenêtre (33)
        assert!(totp.verify(&token, base_ts, 0));
        assert!(totp.verify(&token, base_ts + 29, 0)); // 1019 / 30 = 33 -> ok

        // Fenêtre suivante (34)
        assert!(!totp.verify(&token, base_ts + 30, 0)); // 1020 / 30 = 34 -> échoue avec tolérance 0
        assert!(totp.verify(&token, base_ts + 30, 1));  // réussit avec tolérance 1

        // Fenêtre précédente (32)
        assert!(!totp.verify(&token, base_ts.saturating_sub(1), 0)); // 989 / 30 = 32
        assert!(totp.verify(&token, base_ts.saturating_sub(1), 1));
    }

    #[test]
    fn test_invalid_digits() {
        let secret = b"12345678901234567890".to_vec();
        assert!(Totp::new(secret.clone(), Algorithm::Sha1, 5, 30).is_err());
        assert!(Totp::new(secret, Algorithm::Sha1, 9, 30).is_err());
    }
}

