        let secret = b"12345678901234567890".to_vec();
        let totp = Totp::new(secret, Algorithm::Sha1, 6, 30).expect("Initialisation");

        // Utilisons un début exact de période pour tester clairement la fenêtre
        let base_ts = 990u64; // 990 / 30 = 33
        let token = totp.generate_at_timestamp(base_ts);

        // Dans la même fenêtre (33)
        assert!(totp.verify(&token, base_ts, 0));
        assert!(totp.verify(&token, base_ts + 29, 0)); // 1019 / 30 = 33 -> ok

        // Fenêtre suivante (34)
        assert!(!totp.verify(&token, base_ts + 30, 0)); // 1020 / 30 = 34 -> échoue avec tolérance 0
        assert!(totp.verify(&token, base_ts + 30, 1));  // réussit avec tolérance 1

