// src/main.rs
use std::io::{self, Write};
use clap::{Parser, Subcommand, ValueEnum};
use anyhow::{bail, Context, Result};
use argon2::{
    password_hash::{
        rand_core::OsRng,
        PasswordHash, PasswordHasher, PasswordVerifier, SaltString,
    },
    Argon2, Params as Argon2Params, Algorithm, Version,
};
use pbkdf2::Pbkdf2;

#[derive(Parser, Debug)]
#[command(
    name = "passhash",
    author = "Damien",
    version = "0.1.0",
    about = "Outil CLI de hachage et vérification de mots de passe avec Argon2id et PBKDF2"
)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Hache un mot de passe avec un sel cryptographique aléatoire
    Hash {
        /// Algorithme à utiliser
        #[arg(short, long, value_enum, default_value_t = HashAlgorithm::Argon2id)]
        algorithm: HashAlgorithm,

        /// Mot de passe (si non fourni, une saisie interactive masquée sera demandée)
        #[arg(short, long)]
        password: Option<String>,

        /// Coût mémoire Argon2 en KiB (défaut : 65536 KiB = 64 MiB)
        #[arg(long, default_value_t = 65536)]
        argon_m_cost: u32,

        /// Coût temporel Argon2 (itérations, défaut : 3)
        #[arg(long, default_value_t = 3)]
        argon_t_cost: u32,

        /// Parallélisme Argon2 (threads/lanes, défaut : 4)
        #[arg(long, default_value_t = 4)]
        argon_p_cost: u32,

        /// Nombre d'itérations pour PBKDF2-HMAC-SHA256 (défaut : 600 000)
        #[arg(long, default_value_t = 600_000)]
        pbkdf2_rounds: u32,
    },

    /// Vérifie la correspondance d'un mot de passe avec un hash au format standard PHC
    Verify {
        /// Hash au format standard PHC ($argon2id$... ou $pbkdf2-sha256$...)
        #[arg(short = 'H', long)]
        hash: String,

        /// Mot de passe à vérifier (si non fourni, une saisie interactive masquée sera demandée)
        #[arg(short, long)]
        password: Option<String>,
    },
}

#[derive(Copy, Clone, PartialEq, Eq, PartialOrd, Ord, ValueEnum, Debug)]
enum HashAlgorithm {
    /// Argon2id (Recommandé par l'OWASP, résistant GPU/ASIC)
    Argon2id,
    /// PBKDF2 avec HMAC-SHA256 (Standard FIPS/RFC 2898)
    Pbkdf2,
}

fn acquire_password(provided: Option<String>, prompt: &str) -> Result<String> {
    if let Some(pwd) = provided {
        return Ok(pwd);
    }

    print!("{}", prompt);
    io::stdout().flush().context("Échec du flush de stdout")?;
    let secret = rpassword::read_password().context("Échec de la lecture sécurisée du mot de passe")?;
    if secret.is_empty() {
        bail!("Le mot de passe saisi ne peut pas être vide.");
    }
    Ok(secret)
}

fn execute_hash(
    algo: HashAlgorithm,
    password: &str,
    argon_m_cost: u32,
    argon_t_cost: u32,
    argon_p_cost: u32,
    pbkdf2_rounds: u32,
) -> Result<String> {
    // Sel cryptographiquement sûr généré via le CSPRNG du système (OsRng)
    let salt = SaltString::generate(&mut OsRng);

    match algo {
        HashAlgorithm::Argon2id => {
            let params = Argon2Params::new(
                argon_m_cost,
                argon_t_cost,
                argon_p_cost,
                Some(Argon2Params::DEFAULT_OUTPUT_LEN),
            )
            .map_err(|e| anyhow::anyhow!("Paramètres Argon2 invalides : {}", e))?;

            let argon2 = Argon2::new(Algorithm::Argon2id, Version::V0x13, params);
            let password_hash = argon2
                .hash_password(password.as_bytes(), &salt)
                .map_err(|e| anyhow::anyhow!("Échec du hachage Argon2 : {}", e))?;

            Ok(password_hash.to_string())
        }
        HashAlgorithm::Pbkdf2 => {
            let params = pbkdf2::Params {
                rounds: pbkdf2_rounds,
                output_length: 32,
            };

            let password_hash = Pbkdf2
                .hash_password_customized(
                    password.as_bytes(),
                    Some(pbkdf2::Algorithm::Pbkdf2Sha256.ident()),
                    None,
                    params,
                    &salt,
                )
                .map_err(|e| anyhow::anyhow!("Échec du hachage PBKDF2 : {}", e))?;

            Ok(password_hash.to_string())
        }
    }
}

fn execute_verify(hash_str: &str, password: &str) -> Result<bool> {
    let parsed_hash = PasswordHash::new(hash_str)
        .map_err(|e| anyhow::anyhow!("Format de hash PHC invalide : {}", e))?;

    let algorithm_id = parsed_hash.algorithm.as_str();

    match algorithm_id {
        "argon2id" | "argon2i" | "argon2d" => {
            let argon2 = Argon2::default();
            match argon2.verify_password(password.as_bytes(), &parsed_hash) {
                Ok(()) => Ok(true),
                Err(password_hash::Error::Password) => Ok(false),
                Err(err) => Err(anyhow::anyhow!("Erreur lors de la vérification Argon2 : {}", err)),
            }
        }
        "pbkdf2-sha256" | "pbkdf2" => {
            match Pbkdf2.verify_password(password.as_bytes(), &parsed_hash) {
                Ok(()) => Ok(true),
                Err(password_hash::Error::Password) => Ok(false),
                Err(err) => Err(anyhow::anyhow!("Erreur lors de la vérification PBKDF2 : {}", err)),
            }
        }
        other => {
            bail!("Algorithme de hachage non pris en charge : '{}'", other);
        }
    }
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Hash {
            algorithm,
            password,
            argon_m_cost,
            argon_t_cost,
            argon_p_cost,
            pbkdf2_rounds,
        } => {
            let pwd = acquire_password(password, "Entrez le mot de passe à hacher : ")?;
            let hash = execute_hash(
                algorithm,
                &pwd,
                argon_m_cost,
                argon_t_cost,
                argon_p_cost,
                pbkdf2_rounds,
            )?;

            println!("Algorithme : {:?}", algorithm);
            println!("Hash (PHC) : {}", hash);
        }
        Commands::Verify { hash, password } => {
            let pwd = acquire_password(password, "Entrez le mot de passe à vérifier : ")?;
            let is_valid = execute_verify(&hash, &pwd)?;

            if is_valid {
                println!("OK : Le mot de passe correspond au hash.");
            } else {
                eprintln!("ERREUR : Le mot de passe ne correspond PAS au hash.");
                std::process::exit(1);
            }
        }
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_argon2_hash_and_verify() {
        let password = "UltraSecurePassword42!";
        // Paramètres réduits pour les tests unitaires rapides
        let hash = execute_hash(HashAlgorithm::Argon2id, password, 4096, 1, 1, 1000)
            .expect("Le hachage Argon2 doit réussir");

        assert!(hash.starts_with("$argon2id$"));

        let valid = execute_verify(&hash, password).expect("La vérification doit réussir");
        assert!(valid, "Le mot de passe correct doit être validé");

        let invalid = execute_verify(&hash, "WrongPassword").expect("La vérification doit s'exécuter");
        assert!(!invalid, "Un mauvais mot de passe doit échouer");
    }

    #[test]
    fn test_pbkdf2_hash_and_verify() {
        let password = "AnotherComplexPassphrase!123";
        let hash = execute_hash(HashAlgorithm::Pbkdf2, password, 4096, 1, 1, 10_000)
            .expect("Le hachage PBKDF2 doit réussir");

        assert!(hash.starts_with("$pbkdf2-sha256$"));

        let valid = execute_verify(&hash, password).expect("La vérification doit réussir");
        assert!(valid, "Le mot de passe correct doit être validé");

        let invalid = execute_verify(&hash, "WrongPassword").expect("La vérification doit s'exécuter");
        assert!(!invalid, "Un mauvais mot de passe doit échouer");
    }
}

