// src/main.rs
use std::fs::File;
use std::io::{self, BufRead, BufReader, BufWriter, Read, Write};
use std::path::{Path, PathBuf};

use anyhow::{Context, Result};
use clap::{Parser, ValueEnum};
use flate2::read::GzDecoder;
use flate2::write::GzEncoder;
use flate2::Compression;
use rayon::prelude::*;
use regex::{Captures, Regex};
use sha2::{Digest, Sha256};

/// Modes d'anonymisation disponibles
#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
pub enum MaskingMode {
    /// Remplacement fixe par étiquette ([REDACTED_EMAIL], etc.)
    Redact,
    /// Remplacement par un hash SHA-256 tronqué avec sel
    Hash,
    /// Masquage partiel conservant un aperçu (ex: ex***@domain.com, ****-****-****-1234)
    Partial,
}

#[derive(Parser, Debug)]
#[command(
    name = "log-masker",
    author = "Damien",
    version = "0.1.0",
    about = "Outil de masquage et d'anonymisation de données sensibles dans des fichiers de logs avant archivage."
)]
pub struct Cli {
    /// Fichier source d'entrée (si non spécifié, utilise l'entrée standard stdin)
    #[arg(short = 'i', long = "input")]
    pub input: Option<PathBuf>,

    /// Fichier de destination (si non spécifié, utilise la sortie standard stdout)
    #[arg(short = 'o', long = "output")]
    pub output: Option<PathBuf>,

    /// Mode d'anonymisation : redact, hash ou partial
    #[arg(short = 'm', long = "mode", value_enum, default_value_t = MaskingMode::Redact)]
    pub mode: MaskingMode,

    /// Sel cryptographique pour le mode hash
    #[arg(long = "salt", default_value = "log-masker-default-salt")]
    pub salt: String,

    /// Compresser automatiquement la sortie en Gzip (.gz)
    #[arg(long = "gzip")]
    pub gzip_output: bool,

    /// Traitement par lot : répertoire source contenant les fichiers de log
    #[arg(long = "batch-dir")]
    pub batch_dir: Option<PathBuf>,

    /// Répertoire de sortie pour le mode batch
    #[arg(long = "output-dir")]
    pub output_dir: Option<PathBuf>,
}

/// Définition d'une règle d'anonymisation
pub struct AnonymizationRule {
    pub name: &'static str,
    pub regex: Regex,
    pub tag: &'static str,
    pub partial_fn: Option<fn(&str) -> String>,
}

/// Moteur principal gérant l'application des règles
pub struct LogMaskerEngine {
    rules: Vec<AnonymizationRule>,
    mode: MaskingMode,
    salt: String,
}

impl LogMaskerEngine {
    pub fn new(mode: MaskingMode, salt: String) -> Result<Self> {
        let rules = vec![
            // Cartes de crédit (PAN 16 chiffres avec ou sans délimiteur)
            AnonymizationRule {
                name: "credit_card",
                regex: Regex::new(r"\b(?:\d{4}[- ]?){3}\d{4}\b")
                    .context("Échec compilation regex carte de crédit")?,
                tag: "[REDACTED_CARD]",
                partial_fn: Some(|raw| {
                    let digits: String = raw.chars().filter(|c| c.is_ascii_digit()).collect();
                    if digits.len() >= 4 {
                        let last4 = &digits[digits.len() - 4..];
                        format!("****-****-****-{last4}")
                    } else {
                        "[REDACTED_CARD]".to_string()
                    }
                }),
            },
            // Adresses email
            AnonymizationRule {
                name: "email",
                regex: Regex::new(r"\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b")
                    .context("Échec compilation regex email")?,
                tag: "[REDACTED_EMAIL]",
                partial_fn: Some(|raw| {
                    if let Some((user, domain)) = raw.split_once('@') {
                        if user.len() <= 2 {
                            format!("*@{domain}")
                        } else {
                            let prefix = &user[..2];
                            format!("{prefix}***@{domain}")
                        }
                    } else {
                        "[REDACTED_EMAIL]".to_string()
                    }
                }),
            },
            // Adresses IPv4
            AnonymizationRule {
                name: "ipv4",
                regex: Regex::new(r"\b(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\b")
                    .context("Échec compilation regex ipv4")?,
                tag: "[REDACTED_IPV4]",
                partial_fn: Some(|raw| {
                    let parts: Vec<&str> = raw.split('.').collect();
                    if parts.len() == 4 {
                        format!("{}.{}.*.*", parts[0], parts[1])
                    } else {
                        "[REDACTED_IPV4]".to_string()
                    }
                }),
            },
            // Numéros de sécurité sociale / NIR français (13 ou 15 chiffres)
            AnonymizationRule {
                name: "social_security",
                regex: Regex::new(r"\b[12]\s?\d{2}\s?(?:0[1-9]|1[0-2])\s?\d{2}\s?\d{3}\s?\d{3}(?:\s?\d{2})?\b")
                    .context("Échec compilation regex sécurité sociale")?,
                tag: "[REDACTED_NIR]",
                partial_fn: Some(|_| "[REDACTED_NIR]".to_string()),
            },
            // Numéros de téléphone (formats français/internationaux courants)
            AnonymizationRule {
                name: "phone",
                regex: Regex::new(r"(?:\+?\d{1,3}[-.\s]?)?\(?\d{2,4}\)?[-.\s]?\d{2,4}[-.\s]?\d{2,4}\b")
                    .context("Échec compilation regex téléphone")?,
                tag: "[REDACTED_PHONE]",
                partial_fn: Some(|raw| {
                    let digits: String = raw.chars().filter(|c| c.is_ascii_digit()).collect();
                    if digits.len() >= 4 {
                        let end = &digits[digits.len() - 4..];
                        format!("**-**-**-{end}")
                    } else {
                        "[REDACTED_PHONE]".to_string()
                    }
                }),
            },
            // Jetons d'authentification / API Keys (Bearer tokens, api_key=..., secret=...)
            AnonymizationRule {
                name: "bearer_token",
                regex: Regex::new(r"(?i)\bBearer\s+[a-zA-Z0-9_\-\.]{16,}\b")
                    .context("Échec compilation regex bearer token")?,
                tag: "Bearer [REDACTED_TOKEN]",
                partial_fn: Some(|_| "Bearer [REDACTED_TOKEN]".to_string()),
            },
            AnonymizationRule {
                name: "api_key_param",
                regex: Regex::new(r#"(?i)(api[_-]?key|secret|password|passwd|auth[_-]?token)["':=\s]+([a-zA-Z0-9_\-\.]{8,})"#)
                    .context("Échec compilation regex clé api / secret")?,
                tag: "$1=[REDACTED_SECRET]",
                partial_fn: Some(|raw| {
                    if let Some((k, _)) = raw.split_once('=') {
                        format!("{k}=[REDACTED_SECRET]")
                    } else if let Some((k, _)) = raw.split_once(':') {
                        format!("{k}: [REDACTED_SECRET]")
                    } else {
                        "[REDACTED_SECRET]".to_string()
                    }
                }),
            },
        ];

        Ok(Self { rules, mode, salt })
    }

    /// Calcule le hachage salé et tronqué pour un texte donné
    fn hash_sensitive(&self, value: &str) -> String {
        let mut hasher = Sha256::new();
        hasher.update(self.salt.as_bytes());
        hasher.update(b":");
        hasher.update(value.as_bytes());
        let result = hasher.finalize();
        let hex_res = hex::encode(result);
        format!("[HASH:{}]", &hex_res[..12])
    }

    /// Applique l'anonymisation sur une ligne de log
    pub fn sanitize_line(&self, line: &str) -> String {
        let mut current = line.to_string();

        for rule in &self.rules {
            let replaced = match self.mode {
                MaskingMode::Redact => {
                    rule.regex.replace_all(&current, rule.tag).into_owned()
                }
                MaskingMode::Hash => {
                    rule.regex
                        .replace_all(&current, |caps: &Captures| {
                            let matched = caps.get(0).map_or("", |m| m.as_str());
                            self.hash_sensitive(matched)
                        })
                        .into_owned()
                }
                MaskingMode::Partial => {
                    rule.regex
                        .replace_all(&current, |caps: &Captures| {
                            let matched = caps.get(0).map_or("", |m| m.as_str());
                            if let Some(partial_fn) = rule.partial_fn {
                                partial_fn(matched)
                            } else {
                                rule.tag.to_string()
                            }
                        })
                        .into_owned()
                }
            };
            current = replaced;
        }

        current
    }

    /// Traite un flux d'entrée vers un flux de sortie
    pub fn process_stream<R: Read, W: Write>(&self, reader: R, mut writer: W) -> Result<usize> {
        let buf_reader = BufReader::new(reader);
        let mut count = 0;

        for line_res in buf_reader.lines() {
            let line = line_res.context("Erreur lors de la lecture d'une ligne du flux")?;
            let sanitized = self.sanitize_line(&line);
            writeln!(writer, "{sanitized}").context("Erreur d'écriture dans le flux de destination")?;
            count += 1;
        }

        writer.flush().context("Erreur de synchronisation du flux de sortie")?;
        Ok(count)
    }

    /// Traite un fichier donné vers un fichier de destination
    pub fn process_file(&self, in_path: &Path, out_path: &Path, force_gzip: bool) -> Result<usize> {
        let in_file = File::open(in_path)
            .with_context(|| format!("Impossible d'ouvrir le fichier source : {}", in_path.display()))?;

        // Détection format GZIP en entrée (extension .gz)
        let is_input_gz = in_path.extension().is_some_and(|ext| ext.eq_ignore_ascii_case("gz"));
        let reader: Box<dyn Read> = if is_input_gz {
            Box::new(GzDecoder::new(in_file))
        } else {
            Box::new(in_file)
        };

        if let Some(parent) = out_path.parent() {
            std::fs::create_dir_all(parent)
                .with_context(|| format!("Impossible de créer le répertoire parent : {}", parent.display()))?;
        }

        let out_file = File::create(out_path)
            .with_context(|| format!("Impossible de créer le fichier de destination : {}", out_path.display()))?;

        // Détection sortie GZIP demandée ou extension .gz
        let is_output_gz = force_gzip || out_path.extension().is_some_and(|ext| ext.eq_ignore_ascii_case("gz"));
        let writer: Box<dyn Write> = if is_output_gz {
            Box::new(GzEncoder::new(out_file, Compression::default()))
        } else {
            Box::new(BufWriter::new(out_file))
        };

        self.process_stream(reader, writer)
    }
}

/// Traite un répertoire de fichiers en parallèle avec Rayon
fn process_batch(engine: &LogMaskerEngine, input_dir: &Path, output_dir: &Path, gzip: bool) -> Result<()> {
    if !input_dir.is_dir() {
        anyhow::bail!("Le chemin source {} n'est pas un répertoire valide", input_dir.display());
    }

    let entries: Vec<PathBuf> = std::fs::read_dir(input_dir)
        .with_context(|| format!("Impossible de parcourir le répertoire : {}", input_dir.display()))?
        .filter_map(|e| e.ok())
        .map(|e| e.path())
        .filter(|p| p.is_file())
        .collect();

    if entries.is_empty() {
        println!("Aucun fichier trouvé dans {}", input_dir.display());
        return Ok(());
    }

    println!("Traitement par lot de {} fichier(s)...", entries.len());

    entries.par_iter().try_for_each(|file_path| -> Result<()> {
        let file_name = file_path
            .file_name()
            .ok_or_else(|| anyhow::anyhow!("Nom de fichier invalide : {}", file_path.display()))?;

        let mut out_file_name = file_name.to_os_string();
        if gzip && !file_path.extension().is_some_and(|ext| ext.eq_ignore_ascii_case("gz")) {
            out_file_name.push(".gz");
        }

        let destination = output_dir.join(out_file_name);
        let lines = engine.process_file(file_path, &destination, gzip)?;
        println!("✓ {} -> {} ({} lignes)", file_path.display(), destination.display(), lines);
        Ok(())
    })?;

    println!("Traitement par lot terminé avec succès.");
    Ok(())
}

fn main() -> Result<()> {
    let cli = Cli::parse();
    let engine = LogMaskerEngine::new(cli.mode, cli.salt)?;

    // Traitement par lot si spécifié
    if let (Some(b_in), Some(b_out)) = (cli.batch_dir, cli.output_dir) {
        return process_batch(&engine, &b_in, &b_out, cli.gzip_output);
    }

    // Traitement d'un fichier d'entrée vers un fichier de sortie
    if let Some(in_path) = cli.input {
        let out_path = cli.output.unwrap_or_else(|| {
            let mut name = in_path.as_os_str().to_os_string();
            name.push(".masked");
            if cli.gzip_output && !in_path.extension().is_some_and(|ext| ext.eq_ignore_ascii_case("gz")) {
                name.push(".gz");
            }
            PathBuf::from(name)
        });

        let line_count = engine.process_file(&in_path, &out_path, cli.gzip_output)?;
        eprintln!(
            "Succès : {} ligne(s) traitée(s) et sauvegardée(s) dans {}",
            line_count,
            out_path.display()
        );
        return Ok(());
    }

    // Traitement interactif ou pipeline standard (stdin -> stdout)
    let stdin = io::stdin();
    let stdout = io::stdout();

    let writer: Box<dyn Write> = if cli.gzip_output {
        Box::new(GzEncoder::new(stdout.lock(), Compression::default()))
    } else {
        Box::new(BufWriter::new(stdout.lock()))
    };

    engine.process_stream(stdin.lock(), writer)?;

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_email_redaction() {
        let engine = LogMaskerEngine::new(MaskingMode::Redact, "test".to_string()).unwrap();
        let log = "User login failed for admin@corp.internal from 10.0.0.1";
        let res = engine.sanitize_line(log);
        assert!(res.contains("[REDACTED_EMAIL]"));
        assert!(!res.contains("admin@corp.internal"));
    }

    #[test]
    fn test_email_partial() {
        let engine = LogMaskerEngine::new(MaskingMode::Partial, "test".to_string()).unwrap();
        let log = "Notification sent to john.doe@example.com";
        let res = engine.sanitize_line(log);
        assert!(res.contains("jo***@example.com"));
        assert!(!res.contains("john.doe@example.com"));
    }

    #[test]
    fn test_hash_deterministic() {
        let engine1 = LogMaskerEngine::new(MaskingMode::Hash, "secret_salt".to_string()).unwrap();
        let engine2 = LogMaskerEngine::new(MaskingMode::Hash, "secret_salt".to_string()).unwrap();
        let log = "Client 192.168.1.50 disconnected";
        let res1 = engine1.sanitize_line(log);
        let res2 = engine2.sanitize_line(log);
        assert_eq!(res1, res2);
        assert!(res1.contains("[HASH:"));
        assert!(!res1.contains("192.168.1.50"));
    }

    #[test]
    fn test_credit_card_masking() {
        let engine = LogMaskerEngine::new(MaskingMode::Partial, "test".to_string()).unwrap();
        let log = "Transaction with card 4111-2222-3333-4444 approved";
        let res = engine.sanitize_line(log);
        assert!(res.contains("****-****-****-4444"));
        assert!(!res.contains("4111-2222-3333"));
    }

    #[test]
    fn test_bearer_token() {
        let engine = LogMaskerEngine::new(MaskingMode::Redact, "test".to_string()).unwrap();
        let log = "Authorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9";
        let res = engine.sanitize_line(log);
