                }),
            },
            // Jetons d'authentification / API Keys (Bearer tokens, api_key=..., secret=...)
            AnonymizationRule {
                name: "bearer_token",
                regex: Regex::new(r"(?i)\bBearer\s+[a-zA-Z0-9_\-\.]{16,}\b")
                    .context("Échec compilation regex bearer token")?,
                tag: "Bearer [REDACTED_TOKEN]",
                partial_fn: Some(|_| "Bearer [REDACTED_TOKEN]".to_string()),
            },
            AnonymizationRule {
                name: "api_key_param",
                regex: Regex::new(r#"(?i)(api[_-]?key|secret|password|passwd|auth[_-]?token)["':=\s]+([a-zA-Z0-9_\-\.]{8,})"#)
                    .context("Échec compilation regex clé api / secret")?,
                tag: "$1=[REDACTED_SECRET]",
                partial_fn: Some(|raw| {
                    if let Some((k, _)) = raw.split_once('=') {
                        format!("{k}=[REDACTED_SECRET]")
                    } else if let Some((k, _)) = raw.split_once(':') {
                        format!("{k}: [REDACTED_SECRET]")
                    } else {
                        "[REDACTED_SECRET]".to_string()
                    }
                }),
            },
        ];

        Ok(Self { rules, mode, salt })
    }

    /// Calcule le hachage salé et tronqué pour un texte donné
    fn hash_sensitive(&self, value: &str) -> String {
        let mut hasher = Sha256::new();
        hasher.update(self.salt.as_bytes());
        hasher.update(b":");
        hasher.update(value.as_bytes());
        let result = hasher.finalize();
        let hex_res = hex::encode(result);
        format!("[HASH:{}]", &hex_res[..12])
    }

    /// Applique l'anonymisation sur une ligne de log
    pub fn sanitize_line(&self, line: &str) -> String {
        let mut current = line.to_string();

        for rule in &self.rules {
            let replaced = match self.mode {
                MaskingMode::Redact => {
                    rule.regex.replace_all(&current, rule.tag).into_owned()
                }
                MaskingMode::Hash => {
                    rule.regex
                        .replace_all(&current, |caps: &Captures| {
                            let matched = caps.get(0).map_or("", |m| m.as_str());
                            self.hash_sensitive(matched)
                        })
                        .into_owned()
                }
                MaskingMode::Partial => {
                    rule.regex
                        .replace_all(&current, |caps: &Captures| {
                            let matched = caps.get(0).map_or("", |m| m.as_str());
                            if let Some(partial_fn) = rule.partial_fn {
                                partial_fn(matched)
                            } else {
                                rule.tag.to_string()
                            }
                        })
                        .into_owned()
                }
            };
            current = replaced;
        }

        current
    }

    /// Traite un flux d'entrée vers un flux de sortie
    pub fn process_stream<R: Read, W: Write>(&self, reader: R, mut writer: W) -> Result<usize> {
        let buf_reader = BufReader::new(reader);
        let mut count = 0;

        for line_res in buf_reader.lines() {
            let line = line_res.context("Erreur lors de la lecture d'une ligne du flux")?;
            let sanitized = self.sanitize_line(&line);
            writeln!(writer, "{sanitized}").context("Erreur d'écriture dans le flux de destination")?;
            count += 1;
        }

        writer.flush().context("Erreur de synchronisation du flux de sortie")?;
        Ok(count)
    }

    /// Traite un fichier donné vers un fichier de destination
    pub fn process_file(&self, in_path: &Path, out_path: &Path, force_gzip: bool) -> Result<usize> {
        let in_file = File::open(in_path)
            .with_context(|| format!("Impossible d'ouvrir le fichier source : {}", in_path.display()))?;

        // Détection format GZIP en entrée (extension .gz)
        let is_input_gz = in_path.extension().is_some_and(|ext| ext.eq_ignore_ascii_case("gz"));
        let reader: Box<dyn Read> = if is_input_gz {
            Box::new(GzDecoder::new(in_file))
        } else {
            Box::new(in_file)
        };

        if let Some(parent) = out_path.parent() {
            std::fs::create_dir_all(parent)
                .with_context(|| format!("Impossible de créer le répertoire parent : {}", parent.display()))?;
        }

        let out_file = File::create(out_path)
            .with_context(|| format!("Impossible de créer le fichier de destination : {}", out_path.display()))?;

        // Détection sortie GZIP demandée ou extension .gz
        let is_output_gz = force_gzip || out_path.extension().is_some_and(|ext| ext.eq_ignore_ascii_case("gz"));
        let writer: Box<dyn Write> = if is_output_gz {
            Box::new(GzEncoder::new(out_file, Compression::default()))
        } else {
            Box::new(BufWriter::new(out_file))
        };

        self.process_stream(reader, writer)
    }
}

/// Traite un répertoire de fichiers en parallèle avec Rayon
fn process_batch(engine: &LogMaskerEngine, input_dir: &Path, output_dir: &Path, gzip: bool) -> Result<()> {
    if !input_dir.is_dir() {
        anyhow::bail!("Le chemin source {} n'est pas un répertoire valide", input_dir.display());
    }

    let entries: Vec<PathBuf> = std::fs::read_dir(input_dir)
        .with_context(|| format!("Impossible de parcourir le répertoire : {}", input_dir.display()))?
        .filter_map(|e| e.ok())
        .map(|e| e.path())
        .filter(|p| p.is_file())
        .collect();

    if entries.is_empty() {
        println!("Aucun fichier trouvé dans {}", input_dir.display());
        return Ok(());
    }

    println!("Traitement par lot de {} fichier(s)...", entries.len());

    entries.par_iter().try_for_each(|file_path| -> Result<()> {
        let file_name = file_path
            .file_name()
            .ok_or_else(|| anyhow::anyhow!("Nom de fichier invalide : {}", file_path.display()))?;

        let mut out_file_name = file_name.to_os_string();
        if gzip && !file_path.extension().is_some_and(|ext| ext.eq_ignore_ascii_case("gz")) {
            out_file_name.push(".gz");
        }

        let destination = output_dir.join(out_file_name);
        let lines = engine.process_file(file_path, &destination, gzip)?;
        println!("✓ {} -> {} ({} lignes)", file_path.display(), destination.display(), lines);
        Ok(())
    })?;

    println!("Traitement par lot terminé avec succès.");
    Ok(())
}

fn main() -> Result<()> {
    let cli = Cli::parse();
    let engine = LogMaskerEngine::new(cli.mode, cli.salt)?;

    // Traitement par lot si spécifié
    if let (Some(b_in), Some(b_out)) = (cli.batch_dir, cli.output_dir) {
        return process_batch(&engine, &b_in, &b_out, cli.gzip_output);
    }

    // Traitement d'un fichier d'entrée vers un fichier de sortie
    if let Some(in_path) = cli.input {
        let out_path = cli.output.unwrap_or_else(|| {
            let mut name = in_path.as_os_str().to_os_string();
            name.push(".masked");
            if cli.gzip_output && !in_path.extension().is_some_and(|ext| ext.eq_ignore_ascii_case("gz")) {
                name.push(".gz");
            }
            PathBuf::from(name)
        });

        let line_count = engine.process_file(&in_path, &out_path, cli.gzip_output)?;
        eprintln!(
            "Succès : {} ligne(s) traitée(s) et sauvegardée(s) dans {}",
            line_count,
            out_path.display()
        );
        return Ok(());
    }

    // Traitement interactif ou pipeline standard (stdin -> stdout)
    let stdin = io::stdin();
    let stdout = io::stdout();

    let writer: Box<dyn Write> = if cli.gzip_output {
        Box::new(GzEncoder::new(stdout.lock(), Compression::default()))
    } else {
        Box::new(BufWriter::new(stdout.lock()))
    };

    engine.process_stream(stdin.lock(), writer)?;

    Ok(())
}

