// src/main.rs
use std::collections::{BTreeMap, HashSet};
use std::fs::{self, File};
use std::io::Read;
use std::path::{Path, PathBuf};

use anyhow::{bail, Context, Result};
use chrono::{DateTime, Utc};
use clap::{Parser, Subcommand};
use ed25519_dalek::{
    Signature, Signer, SigningKey, Verifier, VerifyingKey,
};
use rand::rngs::OsRng;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use walkdir::WalkDir;

/// Utilitaire CLI de vérification d'intégrité de dossiers avec manifeste SHA-256 signé Ed25519
#[derive(Parser, Debug)]
#[command(name = "file-integrity-verifier")]
#[command(author, version, about = "Vérifie l'intégrité de dossiers via un manifeste SHA-256 signé", long_about = None)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Génère une paire de clés Ed25519 (privée et publique au format hexadécimal)
    Keygen {
        /// Dossier de destination pour enregistrer les clés
        #[arg(short, long, default_value = ".")]
        output_dir: PathBuf,
    },
    /// Scanne une arborescence, calcule les empreintes SHA-256 et génère un manifeste signé
    Generate {
        /// Répertoire racine à indexer
        #[arg(short, long)]
        dir: PathBuf,
        /// Fichier contenant la clé privée Ed25519 (hexadécimale)
        #[arg(short, long)]
        key: PathBuf,
        /// Fichier manifeste de sortie (ex: manifest.json)
        #[arg(short, long, default_value = "manifest.json")]
        output: PathBuf,
    },
    /// Vérifie la signature du manifeste et l'intégrité de l'arborescence physique
    Verify {
        /// Répertoire racine à inspecter
        #[arg(short, long)]
        dir: PathBuf,
        /// Fichier manifeste à valider
        #[arg(short, long, default_value = "manifest.json")]
        manifest: PathBuf,
        /// Fichier contenant la clé publique de confiance (optionnel, sinon lit celle du manifeste)
        #[arg(short, long)]
        key: Option<PathBuf>,
    },
}

/// Métadonnées d'une entrée de fichier dans le manifeste
#[derive(Serialize, Deserialize, Debug, Clone, PartialEq, Eq)]
struct FileRecord {
    /// Chemin relatif normalisé (séparateur '/')
    path: String,
    /// Taille en octets
    size: u64,
    /// Hachage SHA-256 encodé en hexadécimal
    sha256: String,
}

/// Contenu authentifié du manifeste (soumis à signature)
#[derive(Serialize, Deserialize, Debug, Clone)]
struct ManifestPayload {
    version: u32,
    created_at: DateTime<Utc>,
    root_name: String,
    files: BTreeMap<String, FileRecord>,
}

/// Manifeste complet sérialisé incluant la signature et la clé publique
#[derive(Serialize, Deserialize, Debug, Clone)]
struct SignedManifest {
    payload: ManifestPayload,
    public_key: String,
    signature: String,
}

/// Calcule l'empreinte SHA-256 et la taille d'un fichier en flux mémoire constant (chunked)
fn compute_sha256_and_size(path: &Path) -> Result<(String, u64)> {
    let mut file = File::open(path)
        .with_context(|| format!("Impossible d'ouvrir le fichier : {}", path.display()))?;

    let mut hasher = Sha256::new();
    let mut buffer = [0u8; 64 * 1024]; // Tampon de 64 Ko
    let mut total_size: u64 = 0;

    loop {
        let bytes_read = file
            .read(&mut buffer)
            .with_context(|| format!("Erreur lors de la lecture du fichier : {}", path.display()))?;
        if bytes_read == 0 {
            break;
        }
        hasher.update(&buffer[..bytes_read]);
        total_size += bytes_read as u64;
    }

    let result = hasher.finalize();
    Ok((hex::encode(result), total_size))
}

/// Normalise un chemin relatif sous la convention POSIX /
fn normalize_path(path: &Path) -> Result<String> {
    let mut components = Vec::new();
    for comp in path.components() {
        match comp {
            std::path::Component::Normal(c) => {
                let s = c
                    .to_str()
                    .with_context(|| format!("Nom de fichier invalide UTF-8 : {:?}", c))?;
                components.push(s);
            }
            std::path::Component::CurDir => {}
            _ => {
                bail!(
                    "Composant de chemin non supporté ou dangereux dans {:?} : {:?}",
                    path,
                    comp
                );
            }
        }
    }
    Ok(components.join("/"))
}

/// Lit une clé privée Ed25519 depuis un fichier hexadécimal (32 octets / 64 caractères)
fn load_signing_key(path: &Path) -> Result<SigningKey> {
    let raw = fs::read_to_string(path)
        .with_context(|| format!("Échec de lecture de la clé privée : {}", path.display()))?;
    let trimmed = raw.trim();
    let bytes = hex::decode(trimmed)
        .with_context(|| "Format hexadécimal invalide pour la clé privée")?;

    if bytes.len() != 32 {
        bail!(
            "Longueur invalide pour la clé privée Ed25519 (attendu 32 octets, obtenu {})",
            bytes.len()
        );
    }

    let mut key_bytes = [0u8; 32];
    key_bytes.copy_from_slice(&bytes);
    Ok(SigningKey::from_bytes(&key_bytes))
}

/// Lit une clé publique Ed25519 depuis un fichier hexadécimal
fn load_verifying_key(path: &Path) -> Result<VerifyingKey> {
    let raw = fs::read_to_string(path)
        .with_context(|| format!("Échec de lecture de la clé publique : {}", path.display()))?;
    parse_verifying_key(raw.trim())
}

/// Parse une chaîne hexadécimale en VerifyingKey Ed25519
fn parse_verifying_key(hex_str: &str) -> Result<VerifyingKey> {
    let bytes = hex::decode(hex_str)
        .with_context(|| "Format hexadécimal invalide pour la clé publique")?;

    if bytes.len() != 32 {
        bail!(
            "Longueur de clé publique Ed25519 invalide (attendu 32 octets, obtenu {})",
            bytes.len()
        );
    }

    let mut key_bytes = [0u8; 32];
    key_bytes.copy_from_slice(&bytes);
    VerifyingKey::from_bytes(&key_bytes)
        .with_context(|| "Point de courbe Ed25519 invalide pour la clé publique")
}

/// Exécute la sous-commande `keygen`
fn handle_keygen(output_dir: &Path) -> Result<()> {
    if !output_dir.exists() {
        fs::create_dir_all(output_dir)
            .with_context(|| format!("Impossible de créer le dossier : {}", output_dir.display()))?;
    }

    let mut csprng = OsRng;
    let signing_key = SigningKey::generate(&mut csprng);
    let verifying_key = signing_key.verifying_key();

    let priv_hex = hex::encode(signing_key.to_bytes());
    let pub_hex = hex::encode(verifying_key.to_bytes());

    let priv_path = output_dir.join("private_key.hex");
    let pub_path = output_dir.join("public_key.hex");

    fs::write(&priv_path, priv_hex)
        .with_context(|| format!("Échec d'écriture : {}", priv_path.display()))?;
    fs::write(&pub_path, pub_hex)
        .with_context(|| format!("Échec d'écriture : {}", pub_path.display()))?;

    println!("✓ Paire de clés Ed25519 générée avec succès :");
    println!("  - Clé privée  : {}", priv_path.display());
    println!("  - Clé publique: {}", pub_path.display());

    Ok(())
}

/// Exécute la sous-commande `generate`
fn handle_generate(dir: &Path, key_path: &Path, output_path: &Path) -> Result<()> {
    if !dir.is_dir() {
        bail!("Le chemin source n'est pas un répertoire valide : {}", dir.display());
    }

    let canonical_root = dir
        .canonicalize()
        .with_context(|| format!("Résolution du chemin impossible : {}", dir.display()))?;

    let signing_key = load_signing_key(key_path)?;
    let verifying_key = signing_key.verifying_key();

    println!("Indexation du répertoire : {}", canonical_root.display());

    let mut files = BTreeMap::new();
    let canonical_output = output_path.canonicalize().ok();

    for entry in WalkDir::new(&canonical_root).into_iter() {
        let entry = entry.with_context(|| "Erreur lors du parcours de répertoire")?;
        let path = entry.path();

        // Ignorer les répertoires et les liens symboliques pointant vers des dossiers
        if !entry.file_type().is_file() {
            continue;
        }

        // Si le fichier manifeste est généré à l'intérieur du dossier scanné, on l'ignore
        if let Some(ref out) = canonical_output {
            if path == out {
                continue;
            }
        }

        let rel_path = path.strip_prefix(&canonical_root)
            .with_context(|| "Erreur de calcul du chemin relatif")?;
        let normalized = normalize_path(rel_path)?;

        let (sha256, size) = compute_sha256_and_size(path)?;
        files.insert(
            normalized.clone(),
            FileRecord {
                path: normalized,
                size,
                sha256,
            },
        );
    }

    let root_name = canonical_root
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_else(|| "root".to_string());

    let payload = ManifestPayload {
        version: 1,
        created_at: Utc::now(),
        root_name,
        files,
    };

    let serialized_payload = serde_json::to_vec(&payload)
        .with_context(|| "Erreur lors de la sérialisation canonique du payload")?;

    let signature = signing_key.sign(&serialized_payload);

    let manifest = SignedManifest {
        payload,
        public_key: hex::encode(verifying_key.to_bytes()),
        signature: hex::encode(signature.to_bytes()),
    };

    let formatted_json = serde_json::to_string_pretty(&manifest)
        .with_context(|| "Erreur lors du formatage JSON du manifeste")?;

    if let Some(parent) = output_path.parent() {
        if !parent.as_os_str().is_empty() && !parent.exists() {
            fs::create_dir_all(parent)
                .with_context(|| format!("Impossible de créer le dossier : {}", parent.display()))?;
        }
    }

    fs::write(output_path, formatted_json)
        .with_context(|| format!("Impossible d'écrire le manifeste : {}", output_path.display()))?;

    println!("✓ Manifeste signé généré avec succès !");
    println!("  - Fichier : {}", output_path.display());
    println!("  - Fichiers indexés : {}", manifest.payload.files.len());
    println!("  - Clé publique : {}", manifest.public_key);

    Ok(())
}

/// Résultat de la vérification d'intégrité
#[derive(Default, Debug)]
struct VerificationReport {
    verified_files: usize,
    modified_files: Vec<String>,
    missing_files: Vec<String>,
    untracked_files: Vec<String>,
}

impl VerificationReport {
    fn is_clean(&self) -> bool {
        self.modified_files.is_empty()
            && self.missing_files.is_empty()
            && self.untracked_files.is_empty()
    }
}

/// Exécute la sous-commande `verify`
fn handle_verify(dir: &Path, manifest_path: &Path, key_path: Option<&Path>) -> Result<()> {
    if !dir.is_dir() {
        bail!("Le chemin cible n'est pas un répertoire valide : {}", dir.display());
    }

    let manifest_bytes = fs::read(manifest_path)
        .with_context(|| format!("Impossible de lire le manifeste : {}", manifest_path.display()))?;

    let manifest: SignedManifest = serde_json::from_slice(&manifest_bytes)
        .with_context(|| "Format JSON de manifeste invalide")?;

    // 1. Détermination et validation de la clé publique
    let verifying_key = match key_path {
        Some(path) => {
            let trusted_key = load_verifying_key(path)?;
            if hex::encode(trusted_key.to_bytes()) != manifest.public_key {
                bail!(
                    "Avertissement critique : la clé publique du manifeste ({}) ne correspond pas à la clé de confiance fournie ({}) !",
                    manifest.public_key,
                    hex::encode(trusted_key.to_bytes())
                );
            }
            trusted_key
        }
        None => parse_verifying_key(&manifest.public_key)?,
    };

    // 2. Vérification de la signature cryptographique du payload
    let canonical_payload_bytes = serde_json::to_vec(&manifest.payload)
        .with_context(|| "Impossible de resérialiser le payload pour vérification")?;

    let sig_bytes = hex::decode(&manifest.signature)
        .with_context(|| "Format hexadécimal de la signature invalide")?;

    if sig_bytes.len() != 64 {
        bail!("Taille de signature Ed25519 invalide : {} octets", sig_bytes.len());
    }

    let mut sig_arr = [0u8; 64];
    sig_arr.copy_from_slice(&sig_bytes);
    let signature = Signature::from_bytes(&sig_arr);

    verifying_key
        .verify(&canonical_payload_bytes, &signature)
        .with_context(|| "ÉCHEC : Signature cryptographique invalide ! Le manifeste a été altéré.")?;

    println!("✓ Signature cryptographique Ed25519 authentique et valide.");
    println!("  Horodatage du manifeste : {}", manifest.payload.created_at);

    // 3. Comparaison physique de l'arborescence
    let canonical_root = dir
        .canonicalize()
        .with_context(|| format!("Impossible de résoudre le répertoire : {}", dir.display()))?;
    let canonical_manifest = manifest_path.canonicalize().ok();

    let mut report = VerificationReport::default();
    let mut disk_files = HashSet::new();

    for entry in WalkDir::new(&canonical_root).into_iter() {
        let entry = entry.with_context(|| "Erreur lors du scan du répertoire")?;
        let path = entry.path();

        if !entry.file_type().is_file() {
            continue;
        }

        if let Some(ref m_path) = canonical_manifest {
            if path == m_path {
                continue;
            }
        }

        let rel_path = path.strip_prefix(&canonical_root)
            .with_context(|| "Erreur de stripping de préfixe")?;
        let normalized = normalize_path(rel_path)?;
        disk_files.insert(normalized);
    }

    // Vérifier les fichiers déclarés dans le manifeste
    for (rel_path, expected_record) in &manifest.payload.files {
        let full_path = canonical_root.join(rel_path);
        if !full_path.exists() {
            report.missing_files.push(rel_path.clone());
            continue;
        }

        let (current_hash, current_size) = compute_sha256_and_size(&full_path)?;
        if current_hash != expected_record.sha256 || current_size != expected_record.size {
            report.modified_files.push(format!(
                "{} (attendu: [taille: {}, sha256: {}], obtenu: [taille: {}, sha256: {}])",
                rel_path, expected_record.size, expected_record.sha256, current_size, current_hash
            ));
        } else {
            report.verified_files += 1;
        }
    }

    // Identifier les fichiers orphelins / non répertoriés
    for disk_file in disk_files {
        if !manifest.payload.files.contains_key(&disk_file) {
            report.untracked_files.push(disk_file);
        }
    }

    // Affichage des résultats
    println!("\nRésultats de l'audit d'intégrité :");
    println!("  - Fichiers intacts : {}", report.verified_files);

    if !report.missing_files.is_empty() {
        println!("\n[!] Fichiers manquants ({}) :", report.missing_files.len());
        for f in &report.missing_files {
            println!("    - {}", f);
        }
    }

    if !report.modified_files.is_empty() {
        println!("\n[!] Fichiers modifiés ou corrompus ({}) :", report.modified_files.len());
        for f in &report.modified_files {
            println!("    - {}", f);
        }
    }

    if !report.untracked_files.is_empty() {
        println!("\n[!] Fichiers orphelins non déclarés ({}) :", report.untracked_files.len());
        for f in &report.untracked_files {
            println!("    - {}", f);
        }
    }

    if report.is_clean() {
        println!("\n✓ INTÉGRITÉ PARFAITE : Tous les fichiers correspondent exactement au manifeste.");
        Ok(())
    } else {
        bail!("Échec du contrôle d'intégrité : des anomalies ont été détectées sur le disque.");
    }
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Keygen { output_dir } => handle_keygen(&output_dir),
        Commands::Generate { dir, key, output } => handle_generate(&dir, &key, &output),
        Commands::Verify {
            dir,
            manifest,
            key,
        } => handle_verify(&dir, &manifest, key.as_deref()),
    }
}

