// src/main.rs
use std::path::PathBuf;
use clap::{Parser, Subcommand};
use image::{ImageReader, RgbImage};
use thiserror::Error;

/// Erreurs métier spécifiques à la stéganographie
#[derive(Debug, Error)]
pub enum StegoError {
    #[error("Erreur I/O ou traitement d'image : {0}")]
    Image(#[from] image::ImageError),

    #[error("Message trop volumineux : requis {required_bytes} octets (capacité disponible : {available_bytes} octets)")]
    PayloadTooLarge {
        required_bytes: usize,
        available_bytes: usize,
    },

    #[error("Image insuffisante : l'en-tête de 32 bits requiert au moins 32 composantes de couleur, trouvé {found}")]
    ImageTooSmallForHeader { found: usize },

    #[error("La longueur déclarée dans l'en-tête ({length} octets) excède la capacité de l'image ({max_capacity} octets)")]
    InvalidDeclaredLength {
        length: usize,
        max_capacity: usize,
    },

    #[error("Le contenu extrait n'est pas une chaîne UTF-8 valide : {0}")]
    Utf8(#[from] std::string::FromUtf8Error),
}

/// CLI de stéganographie LSB pour images Bitmap (BMP)
#[derive(Parser, Debug)]
#[command(name = "stego_bmp", version, about = "Encode et décode du texte caché dans une image BMP")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Cache un message texte dans une image BMP
    Encode {
        /// Image BMP d'entrée
        #[arg(short, long)]
        input: PathBuf,

        /// Image BMP de sortie
        #[arg(short, long)]
        output: PathBuf,

        /// Message texte à dissimuler
        #[arg(short, long)]
        message: String,
    },
    /// Récupère un message texte caché dans une image BMP
    Decode {
        /// Image BMP d'entrée contenant le message dissimulé
        #[arg(short, long)]
        input: PathBuf,
    },
}

/// Encode un message UTF-8 dans un buffer RGB selon la méthode LSB avec préfixe de taille 32-bit Big-Endian.
fn encode_lsb(image: &mut RgbImage, message: &str) -> Result<(), StegoError> {
    let payload_bytes = message.as_bytes();
    let payload_len = payload_bytes.len();

    // 4 octets pour stocker la longueur en u32 big-endian
    let total_bytes_needed = 4 + payload_len;
    let total_bits_needed = total_bytes_needed * 8;
    let available_bits = image.len(); // RgbImage contient width * height * 3 octets de couleur

    if total_bits_needed > available_bits {
        return Err(StegoError::PayloadTooLarge {
            required_bytes: total_bytes_needed,
            available_bytes: available_bits / 8,
        });
    }

    // Préparer le flux complet de données (taille u32 BE + payload)
    let len_prefix = (payload_len as u32).to_be_bytes();
    let mut data_stream = Vec::with_capacity(total_bytes_needed);
    data_stream.extend_from_slice(&len_prefix);
    data_stream.extend_from_slice(payload_bytes);

    let raw_bytes = image.as_mut();
    let mut bit_index = 0;

    for &byte in &data_stream {
        for bit_pos in (0..8).rev() {
            let bit = (byte >> bit_pos) & 1;
            // Modifie uniquement le bit de poids faible
            raw_bytes[bit_index] = (raw_bytes[bit_index] & 0xFE) | bit;
            bit_index += 1;
        }
    }

    Ok(())
}

/// Décode un message caché dans une image RGB encodée par LSB.
fn decode_lsb(image: &RgbImage) -> Result<String, StegoError> {
    let raw_bytes = image.as_raw();
    let available_bits = raw_bytes.len();

    // On a besoin d'au moins 32 bits (4 octets) pour lire la taille
    if available_bits < 32 {
        return Err(StegoError::ImageTooSmallForHeader {
            found: available_bits,
        });
    }

    // Extraction des 32 premiers bits pour reconstruire la longueur (u32 BE)
    let mut length_bytes = [0u8; 4];
    for byte_idx in 0..4 {
        let mut byte_val = 0u8;
        for bit_idx in 0..8 {
            let sample_idx = byte_idx * 8 + bit_idx;
            let bit = raw_bytes[sample_idx] & 1;
            byte_val = (byte_val << 1) | bit;
        }
        length_bytes[byte_idx] = byte_val;
    }

    let payload_len = u32::from_be_bytes(length_bytes) as usize;
    let max_possible_payload = (available_bits - 32) / 8;

    if payload_len > max_possible_payload {
        return Err(StegoError::InvalidDeclaredLength {
            length: payload_len,
            max_capacity: max_possible_payload,
        });
    }

    // Extraction des octets du message
    let mut payload = Vec::with_capacity(payload_len);
    let start_bit = 32;

    for i in 0..payload_len {
        let mut byte_val = 0u8;
        for bit_idx in 0..8 {
            let sample_idx = start_bit + i * 8 + bit_idx;
            let bit = raw_bytes[sample_idx] & 1;
            byte_val = (byte_val << 1) | bit;
        }
        payload.push(byte_val);
    }

    let message = String::from_utf8(payload)?;
    Ok(message)
}

fn main() -> anyhow::Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Encode {
            input,
            output,
            message,
        } => {
            let img = ImageReader::open(&input)
                .map_err(|e| anyhow::anyhow!("Impossible d'ouvrir l'image source {:?}: {e}", input))?
                .decode()
                .map_err(|e| anyhow::anyhow!("Échec du décodage de l'image {:?}: {e}", input))?;

            let mut rgb_img = img.to_rgb8();

            encode_lsb(&mut rgb_img, &message)
                .map_err(|e| anyhow::anyhow!("Erreur lors de l'encodage du message: {e}"))?;

            rgb_img
                .save_with_format(&output, image::ImageFormat::Bmp)
                .map_err(|e| anyhow::anyhow!("Erreur lors de la sauvegarde du fichier {:?}: {e}", output))?;

            println!(
                "Succès : Le message ({} octets) a été dissimulé dans {:?}",
                message.len(),
                output
            );
        }
        Commands::Decode { input } => {
            let img = ImageReader::open(&input)
                .map_err(|e| anyhow::anyhow!("Impossible d'ouvrir l'image {:?}: {e}", input))?
                .decode()
                .map_err(|e| anyhow::anyhow!("Échec du décodage de l'image {:?}: {e}", input))?;

            let rgb_img = img.to_rgb8();

            let message = decode_lsb(&rgb_img)
                .map_err(|e| anyhow::anyhow!("Erreur lors du décodage du message: {e}"))?;

            println!("Message extrait avec succès :\n{}", message);
        }
    }

    Ok(())
}

