        let mut image = RgbImage::new(10, 10); // 100 pixels * 3 = 300 octets -> ~37 octets de capacité totale
        let secret = "Hello Rust steganography! 🦀";

        encode_lsb(&mut image, secret).expect("Encoding should succeed");
        let decoded = decode_lsb(&image).expect("Decoding should succeed");

        assert_eq!(secret, decoded);
    }

    #[test]
    fn test_payload_too_large() {
        let mut image = RgbImage::new(2, 2); // 4 pixels * 3 = 12 octets -> 12 bits -> 1 octet (ne peut même pas contenir l'en-tête de 4 octets)
        let secret = "Trop long";

        let result = encode_lsb(&mut image, secret);
        assert!(matches!(result, Err(StegoError::PayloadTooLarge { .. })));
    }
