```rust
// src/main.rs
use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result, bail};
use clap::{Parser, Subcommand, ValueEnum};
use ed25519_dalek::{
    Signature, Signer, SigningKey, Verifier, VerifyingKey,
};
use rand::rngs::OsRng;

#[derive(Parser, Debug)]
#[command(
    name = "ed25519-tool",
    author,
    version,
    about = "Génération de clés Ed25519, signature et vérification de documents",
    long_about = None
)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(ValueEnum, Clone, Copy, Debug, PartialEq, Eq)]
enum KeyEncoding {
    Hex,
    Binary,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Génère une nouvelle paire de clés Ed25519
    Keygen {
        /// Chemin de sortie pour la clé privée
        #[arg(short = 's', long = "secret", default_value = "ed25519_key")]
        secret_out: PathBuf,

        /// Chemin de sortie pour la clé publique
        #[arg(short = 'p', long = "public", default_value = "ed25519_key.pub")]
        public_out: PathBuf,

        /// Format d'encodage des fichiers de clés (hex ou binary)
        #[arg(short = 'e', long = "encoding", default_value = "hex")]
        encoding: KeyEncoding,
    },

    /// Signe un fichier de données à l'aide d'une clé privée
    Sign {
        /// Chemin vers la clé privée
        #[arg(short = 's', long = "secret")]
        secret_key: PathBuf,

        /// Fichier à signer
        #[arg(short = 'f', long = "file")]
        file: PathBuf,

        /// Fichier de sortie pour la signature (par défaut: <fichier>.sig)
        #[arg(short = 'o', long = "out")]
        signature_out: Option<PathBuf>,

        /// Format d'encodage de la clé privée (hex ou binary)
        #[arg(short = 'e', long = "encoding", default_value = "hex")]
        encoding: KeyEncoding,
    },

    /// Vérifie la signature d'un fichier avec une clé publique
    Verify {
        /// Chemin vers la clé publique
        #[arg(short = 'p', long = "public")]
        public_key: PathBuf,

        /// Fichier dont la signature doit être vérifiée
        #[arg(short = 'f', long = "file")]
        file: PathBuf,

        /// Fichier contenant la signature (par défaut: <fichier>.sig)
        #[arg(short = 's', long = "signature")]
        signature_file: Option<PathBuf>,

        /// Format d'encodage de la clé publique (hex ou binary)
        #[arg(short = 'e', long = "encoding", default_value = "hex")]
        encoding: KeyEncoding,
    },
}

fn load_secret_key(path: &Path, encoding: KeyEncoding) -> Result<SigningKey> {
    let raw = fs::read(path).with_context(|| format!("Impossible de lire la clé privée: {:?}", path))?;
    let key_bytes: [u8; 32] = match encoding {
        KeyEncoding::Binary => {
            if raw.len() != 32 {
                bail!(
                    "Taille invalide pour la clé privée binaire (attendu: 32 octets, reçu: {} octets)",
                    raw.len()
                );
            }
            let mut arr = [0u8; 32];
            arr.copy_from_slice(&raw);
            arr
        }
        KeyEncoding::Hex => {
            let s = std::str::from_utf8(&raw)
                .with_context(|| "Le fichier de clé privée n'est pas une chaîne UTF-8 valide")?
                .trim();
            let decoded = hex::decode(s)
                .with_context(|| "Échec du décodage hexadécimal de la clé privée")?;
            if decoded.len() != 32 {
                bail!(
                    "Taille invalide pour la clé privée hexadécimale (attendu: 32 octets / 64 caractères, reçu: {} octets)",
                    decoded.len()
                );
            }
            let mut arr = [0u8; 32];
            arr.copy_from_slice(&decoded);
            arr
        }
    };
    Ok(SigningKey::from_bytes(&key_bytes))
}

fn load_verifying_key(path: &Path, encoding: KeyEncoding) -> Result<VerifyingKey> {
    let raw = fs::read(path).with_context(|| format!("Impossible de lire la clé publique: {:?}", path))?;
    let key_bytes: [u8; 32] = match encoding {
        KeyEncoding::Binary => {
            if raw.len() != 32 {
                bail!(
                    "Taille invalide pour la clé publique binaire (attendu: 32 octets, reçu: {} octets)",
                    raw.len()
                );
            }
            let mut arr = [0u8; 32];
            arr.copy_from_slice(&raw);
            arr
        }
        KeyEncoding::Hex => {
            let s = std::str::from_utf8(&raw)
                .with_context(|| "Le fichier de clé publique n'est pas une chaîne UTF-8 valide")?
                .trim();
            let decoded = hex::decode(s)
                .with_context(|| "Échec du décodage hexadécimal de la clé publique")?;
            if decoded.len() != 32 {
                bail!(
                    "Taille invalide pour la clé publique hexadécimale (attendu: 32 octets / 64 caractères, reçu: {} octets)",
                    decoded.len()
                );
            }
            let mut arr = [0u8; 32];
            arr.copy_from_slice(&decoded);
            arr
        }
    };

    VerifyingKey::from_bytes(&key_bytes)
        .with_context(|| "Format de clé publique Ed25519 invalide")
}

fn load_signature(path: &Path) -> Result<Signature> {
    let raw = fs::read(path).with_context(|| format!("Impossible de lire le fichier de signature: {:?}", path))?;
    let trimmed = std::str::from_utf8(&raw)
        .map(str::trim)
        .ok();

    if let Some(hex_str) = trimmed {
        if let Ok(decoded) = hex::decode(hex_str) {
            if decoded.len() == 64 {
                let mut bytes = [0u8; 64];
                bytes.copy_from_slice(&decoded);
                return Ok(Signature::from_bytes(&bytes));
            }
        }
    }

    if raw.len() == 64 {
        let mut bytes = [0u8; 64];
        bytes.copy_from_slice(&raw);
        return Ok(Signature::from_bytes(&bytes));
    }

    bail!(
        "Format de signature invalide dans {:?}. Attendu: 64 octets binaires ou 128 caractères hexadécimaux.",
        path
    )
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Keygen {
            secret_out,
            public_out,
            encoding,
        } => {
            let mut csprng = OsRng;
            let signing_key = SigningKey::generate(&mut csprng);
            let verifying_key = signing_key.verifying_key();

            match encoding {
                KeyEncoding::Hex => {
                    let secret_hex = hex::encode(signing_key.to_bytes());
                    let public_hex = hex::encode(verifying_key.to_bytes());

                    fs::write(&secret_out, format!("{}\n", secret_hex))
                        .with_context(|| format!("Impossible d'écrire la clé secrète: {:?}", secret_out))?;
                    fs::write(&public_out, format!("{}\n", public_hex))
                        .with_context(|| format!("Impossible d'écrire la clé publique: {:?}", public_out))?;
                }
                KeyEncoding::Binary => {
                    fs::write(&secret_out, signing_key.to_bytes())
                        .with_context(|| format!("Impossible d'écrire la clé secrète: {:?}", secret_out))?;
                    fs::write(&public_out, verifying_key.to_bytes())
                        .with_context(|| format!("Impossible d'écrire la clé publique: {:?}", public_out))?;
                }
            }

            println!("Paire de clés Ed25519 générée avec succès.");
            println!("  Clé privée : {:?}", secret_out);
            println!("  Clé publique: {:?}", public_out);
            println!("  Encodage   : {:?}", encoding);
        }

        Commands::Sign {
            secret_key,
            file,
            signature_out,
            encoding,
        } => {
            let signing_key = load_secret_key(&secret_key, encoding)?;
            let content = fs::read(&file)
                .with_context(|| format!("Impossible de lire le fichier à signer: {:?}", file))?;

            let signature = signing_key.sign(&content);
            let hex_sig = hex::encode(signature.to_bytes());

            let sig_path = signature_out.unwrap_or_else(|| {
                let mut p = file.clone();
                let current_ext = p.extension().and_then(|s| s.to_str()).unwrap_or("");
                let new_ext = if current_ext.is_empty() {
                    "sig".to_string()
                } else {
                    format!("{}.sig", current_ext)
                };
                p.set_extension(new_ext);
                p
            });

            fs::write(&sig_path, format!("{}\n", hex_sig))
                .with_context(|| format!("Impossible d'écrire la signature dans: {:?}", sig_path))?;

            println!("Fichier signé avec succès.");
            println!("  Document : {:?}", file);
            println!("  Signature: {:?}", sig_path);
            println!("  Empreinte: {}", hex_sig);
        }

        Commands::Verify {
            public_key,
            file,
            signature_file,
            encoding,
        } => {
            let verifying_key = load_verifying_key(&public_key, encoding)?;
            let content = fs::read(&file)
                .with_context(|| format!("Impossible de lire le fichier à vérifier: {:?}", file))?;

            let sig_path = signature_file.unwrap_or_else(|| {
                let mut p = file.clone();
                let current_ext = p.extension().and_then(|s| s.to_str()).unwrap_or("");
                let new_ext = if current_ext.is_empty() {
                    "sig".to_string()
                } else {
                    format!("{}.sig", current_ext)
                };
                p.set_extension(new_ext);
                p
            });

            let signature = load_signature(&sig_path)?;

            match verifying_key.verify(&content, &signature) {
                Ok(()) => {
                    println!("VALIDATION RÉUSSIE: La signature est valide pour le document {:?}", file);
                }
                Err(err) => {
                    bail!("VALIDATION ÉCHOUÉE: La signature est invalide ({})", err);
                }
            }
        }
    }

    Ok(())
}

