```rust
// src/main.rs
use std::fs::{self, File};
use std::io::{BufRead, BufReader};
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use clap::{Parser, ValueEnum};
use colored::*;
use serde::{Deserialize, Serialize};

#[derive(Parser, Debug)]
#[command(
    name = "linux-perms-scanner",
    author = "Damien",
    version = "0.1.0",
    about = "Scanner de vulnérabilités passif vérifiant les permissions des fichiers critiques Linux"
)]
pub struct Cli {
    /// Répertoire racine à inspecter (par défaut: /)
    #[arg(short, long, default_value = "/")]
    pub root: PathBuf,

    /// Format de sortie en JSON pour l'intégration CI/CD ou SIEM
    #[arg(short, long)]
    pub json: bool,

    /// Niveau minimal de sévérité à afficher
    #[arg(short, long, value_enum, default_value_t = SeverityLevel::Low)]
    pub min_severity: SeverityLevel,

    /// Activer le mode verbeux (affiche également les fichiers conformes inspectés)
    #[arg(short, long)]
    pub verbose: bool,

    /// Quitter avec un code de retour d'erreur (exit code 1) en cas d'anomalie critique ou haute
    #[arg(long)]
    pub fail_on_findings: bool,
}

#[derive(Copy, Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize, ValueEnum)]
#[serde(rename_all = "UPPERCASE")]
pub enum SeverityLevel {
    Info = 0,
    Low = 1,
    Medium = 2,
    High = 3,
    Critical = 4,
}

impl std::fmt::Display for SeverityLevel {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Info => write!(f, "INFO"),
            Self::Low => write!(f, "LOW"),
            Self::Medium => write!(f, "MEDIUM"),
            Self::High => write!(f, "HIGH"),
            Self::Critical => write!(f, "CRITICAL"),
        }
    }
}

#[derive(Serialize, Deserialize, Debug, Clone)]
pub struct VulnerabilityFinding {
    pub path: String,
    pub severity: SeverityLevel,
    pub title: String,
    pub description: String,
    pub current_mode: String,
    pub expected_mode: String,
    pub current_uid: u32,
    pub expected_uid: Option<u32>,
    pub remediation: String,
}

#[derive(Serialize, Deserialize, Debug, Clone)]
pub struct ValidFileRecord {
    pub path: String,
    pub mode: String,
    pub uid: u32,
}

#[derive(Serialize, Deserialize, Debug, Default)]
pub struct AuditReport {
    pub timestamp: String,
    pub scanned_files_count: usize,
    pub findings_count: usize,
    pub critical_count: usize,
    pub high_count: usize,
    pub medium_count: usize,
    pub low_count: usize,
    pub findings: Vec<VulnerabilityFinding>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub compliant_files: Vec<ValidFileRecord>,
}

#[derive(Clone, Debug)]
pub struct ExpectedRule {
    pub max_mode: u32,
    pub disallow_bits: u32,
    pub expected_uid: Option<u32>,
    pub title: &'static str,
    pub description: &'static str,
    pub severity_if_broken: SeverityLevel,
    pub remediation_cmd: &'static str,
}

pub fn format_mode(mode: u32) -> String {
    format!("{:04o}", mode & 0o7777)
}

pub fn check_permission_bits(
    mode: u32,
    uid: u32,
    rule: &ExpectedRule,
) -> Option<(SeverityLevel, Vec<String>)> {
    let standard_perm = mode & 0o777;
    let mut violations = Vec::new();
    let mut severity = rule.severity_if_broken;

    // Vérification des bits strictement interdits
    if (mode & rule.disallow_bits) != 0 {
        let bad_bits = mode & rule.disallow_bits;
        violations.push(format!("Bits non autorisés actifs ({:04o})", bad_bits));
        if (bad_bits & 0o002) != 0 {
            // Écriture ouverte à tous (world-writable) sur un fichier sensible -> Critique
            severity = SeverityLevel::Critical;
        }
    }

    // Vérification du mode maximum autorisé
    if standard_perm > rule.max_mode {
        violations.push(format!(
            "Permissions trop permissives ({:04o} > {:04o})",
            standard_perm, rule.max_mode
        ));
    }

    // Vérification du propriétaire attendu (UID)
    if let Some(expected_uid) = rule.expected_uid {
        if uid != expected_uid {
            violations.push(format!(
                "Propriétaire UID invalide (actuel: {}, attendu: {})",
                uid, expected_uid
            ));
            if expected_uid == 0 && severity < SeverityLevel::High {
                severity = SeverityLevel::High;
            }
        }
    }

    if violations.is_empty() {
        None
    } else {
        Some((severity, violations))
    }
}

pub fn is_ssh_private_key(path: &Path) -> bool {
    let file_name = match path.file_name().and_then(|s| s.to_str()) {
        Some(name) => name,
        None => return false,
    };

    if file_name.ends_with(".pub") {
        return false;
    }

    let is_named_like_key = file_name.starts_with("id_")
        || file_name == "identity"
        || (file_name.starts_with("ssh_host_") && file_name.ends_with("_key"));

    if is_named_like_key {
        return true;
    }

    // Analyse passive du header du fichier si lisible localement
    if let Ok(file) = File::open(path) {
        let mut reader = BufReader::new(file);
        let mut first_line = String::new();
        if reader.read_line(&mut first_line).is_ok()
            && first_line.contains("BEGIN")
            && first_line.contains("PRIVATE KEY")
        {
            return true;
        }
    }

    false
}

pub fn audit_file(path: &Path, rule: &ExpectedRule, report: &mut AuditReport, record_compliant: bool) {
    if !path.exists() {
        return;
    }

    report.scanned_files_count += 1;

    match fs::symlink_metadata(path) {
        Ok(metadata) => {
            let mode = metadata.mode() & 0o7777;
            let uid = metadata.uid();

            if let Some((severity, violations)) = check_permission_bits(mode, uid, rule) {
                match severity {
                    SeverityLevel::Critical => report.critical_count += 1,
                    SeverityLevel::High => report.high_count += 1,
                    SeverityLevel::Medium => report.medium_count += 1,
                    SeverityLevel::Low => report.low_count += 1,
                    SeverityLevel::Info => {}
                }
                report.findings.push(VulnerabilityFinding {
                    path: path.display().to_string(),
                    severity,
                    title: rule.title.to_string(),
                    description: format!("{}. Détails: {}", rule.description, violations.join(", ")),
                    current_mode: format_mode(mode),
                    expected_mode: format_mode(rule.max_mode),
                    current_uid: uid,
                    expected_uid: rule.expected_uid,
                    remediation: rule.remediation_cmd.replace("{path}", &path.display().to_string()),
                });
            } else if record_compliant {
                report.compliant_files.push(ValidFileRecord {
                    path: path.display().to_string(),
                    mode: format_mode(mode),
                    uid,
                });
            }
        }
        Err(err) => {
            if err.kind() == std::io::ErrorKind::PermissionDenied {
                report.findings.push(VulnerabilityFinding {
                    path: path.display().to_string(),
                    severity: SeverityLevel::Info,
                    title: "Accès restreint lors de la lecture des métadonnées".to_string(),
                    description: "Droits insuffisants pour lire les métadonnées de ce fichier système protégé.".to_string(),
                    current_mode: "Inaccessible".to_string(),
                    expected_mode: format_mode(rule.max_mode),
                    current_uid: 0,
                    expected_uid: rule.expected_uid,
                    remediation: format!("# Vérifier avec privilèges root : sudo ls -ld {}", path.display()),
                });
            }
        }
    }
}

pub fn scan_system_files(root: &Path, report: &mut AuditReport, record_compliant: bool) {
    let system_rules: Vec<(&str, ExpectedRule)> = vec![
        (
            "etc/passwd",
            ExpectedRule {
                max_mode: 0o644,
                disallow_bits: 0o022,
                expected_uid: Some(0),
                title: "Permissions /etc/passwd",
                description: "Le fichier des comptes doit être en lecture publique mais modifiable uniquement par root",
                severity_if_broken: SeverityLevel::Critical,
                remediation_cmd: "chmod 644 {path} && chown root:root {path}",
            },
        ),
        (
            "etc/shadow",
            ExpectedRule {
                max_mode: 0o640,
                disallow_bits: 0o027,
                expected_uid: Some(0),
                title: "Permissions /etc/shadow",
                description: "Les empreintes de mots de passe ne doivent jamais être lisibles par les utilisateurs ordinaires",
                severity_if_broken: SeverityLevel::Critical,
                remediation_cmd: "chmod 640 {path} && chown root:shadow {path}",
            },
        ),
        (
            "etc/gshadow",
            ExpectedRule {
                max_mode: 0o640,
                disallow_bits: 0o027,
                expected_uid: Some(0),
                title: "Permissions /etc/gshadow",
                description: "Les empreintes de mots de passe de groupe doivent être protégées",
                severity_if_broken: SeverityLevel::Critical,
                remediation_cmd: "chmod 640 {path} && chown root:shadow {path}",
            },
        ),
        (
            "etc/group",
            ExpectedRule {
                max_mode: 0o644,
                disallow_bits: 0o022,
                expected_uid: Some(0),
                title: "Permissions /etc/group",
                description: "Le fichier des groupes doit être modifiable uniquement par root",
                severity_if_broken: SeverityLevel::High,
                remediation_cmd: "chmod 644 {path} && chown root:root {path}",
            },
        ),
        (
            "etc/sudoers",
            ExpectedRule {
                max_mode: 0o440,
                disallow_bits: 0o037,
                expected_uid: Some(0),
                title: "Permissions /etc/sudoers",
                description: "Le fichier sudoers doit avoir les permissions strictes 0440 et appartenir à root",
                severity_if_broken: SeverityLevel::Critical,
                remediation_cmd: "chmod 0440 {path} && chown root:root {path}",
            },
        ),
        (
            "etc/ssh/sshd_config",
            ExpectedRule {
                max_mode: 0o600,
                disallow_bits: 0o077,
                expected_uid: Some(0),
                title: "Configuration du démon SSH (/etc/ssh/sshd_config)",
                description: "La configuration SSH ne doit pas être altérable par des tiers",
                severity_if_broken: SeverityLevel::High,
                remediation_cmd: "chmod 600 {path} && chown root:root {path}",
            },
        ),
        (
            "etc/crontab",
            ExpectedRule {
                max_mode: 0o644,
                disallow_bits: 0o022,
                expected_uid: Some(0),
                title: "Permissions /etc/crontab",
                description: "Le crontab système doit être modifiable uniquement par root",
                severity_if_broken: SeverityLevel::Critical,
                remediation_cmd: "chmod 644 {path} && chown root:root {path}",
            },
        ),
    ];

    for (rel_path, rule) in system_rules {
        let full_path = root.join(rel_path);
        audit_file(&full_path, &rule, report, record_compliant);
    }

    // Inspection de /etc/sudoers.d/
    let sudoers_d = root.join("etc/sudoers.d");
    if sudoers_d.is_dir() {
        if let Ok(entries) = fs::read_dir(&sudoers_d) {
            for entry in entries.flatten() {
                let path = entry.path();
                if path.is_file() {
                    let rule = ExpectedRule {
                        max_mode: 0o440,
                        disallow_bits: 0o037,
                        expected_uid: Some(0),
                        title: "Fichier de configuration /etc/sudoers.d/*",
                        description: "Les inclusions sudoers doivent être en lecture seule pour root",
                        severity_if_broken: SeverityLevel::Critical,
                        remediation_cmd: "chmod 0440 {path} && chown root:root {path}",
                    };
                    audit_file(&path, &rule, report, record_compliant);
                }
            }
        }
    }

    // Inspection des clés hôtes du serveur SSH (/etc/ssh/ssh_host_*_key)
    let ssh_dir = root.join("etc/ssh");
    if ssh_dir.is_dir() {
        if let Ok(entries) = fs::read_dir(&ssh_dir) {
            for entry in entries.flatten() {
                let path = entry.path();
                if path.is_file() && is_ssh_private_key(&path) {
                    let rule = ExpectedRule {
                        max_mode: 0o600,
                        disallow_bits: 0o077,
                        expected_uid: Some(0),
                        title: "Clé privée hôte SSH",
                        description: "Une clé privée d'hôte SSH doit être strictement protégée (0600)",
                        severity_if_broken: SeverityLevel::Critical,
                        remediation_cmd: "chmod 600 {path} && chown root:root {path}",
                    };
                    audit_file(&path, &rule, report, record_compliant);
                }
            }
        }
    }
}

pub fn scan_user_ssh_directories(root: &Path, report: &mut AuditReport, record_compliant: bool) {
    let mut candidate_ssh_dirs = Vec::new();

    let root_ssh = root.join("root/.ssh");
    if root_ssh.is_dir() {
        candidate_ssh_dirs.push(root_ssh);
    }

    let home_dir = root.join("home");
    if home_dir.is_dir() {
        if let Ok(user_entries) = fs::read_dir(&home_dir) {
            for user_entry in user_entries.flatten() {
                let user_path = user_entry.path();
                if user_path.is_dir() {
                    let user_ssh = user_path.join(".ssh");
                    if user_ssh.is_dir() {
                        candidate_ssh_dirs.push(user_ssh);
                    }
                }
            }
        }
    }

    for ssh_dir in candidate_ssh_dirs {
        let dir_meta = match fs::symlink_metadata(&ssh_dir) {
            Ok(m) => m,
            Err(_) => continue,
        };

        let owner_uid = dir_meta.uid();

        // 1. Audit du répertoire .ssh (0700)
        let dir_rule = ExpectedRule {
            max_mode: 0o700,
            disallow_bits: 0o077,
            expected_uid: Some(owner_uid),
            title: "Répertoire ~/.ssh de l'utilisateur",
            description: "Le répertoire .ssh doit être accessible exclusivement par son propriétaire (0700)",
            severity_if_broken: SeverityLevel::High,
            remediation_cmd: "chmod 700 {path}",
        };
        audit_file(&ssh_dir, &dir_rule, report, record_compliant);

        // 2. Audit des fichiers dans .ssh
        let entries = match fs::read_dir(&ssh_dir) {
            Ok(e) => e,
            Err(_) => continue,
        };

        for entry in entries.flatten() {
            let file_path = entry.path();
            if !file_path.is_file() {
                continue;
            }

            let file_name = match file_path.file_name().and_then(|n| n.to_str()) {
                Some(name) => name,
                None => continue,
            };

            if is_ssh_private_key(&file_path) {
                let priv_key_rule = ExpectedRule {
                    max_mode: 0o600,
                    disallow_bits: 0o077,
                    expected_uid: Some(owner_uid),
                    title: "Clé privée SSH utilisateur",
                    description: "Une clé privée SSH ne doit jamais être accessible par autrui (0600)",
                    severity_if_broken: SeverityLevel::Critical,
                    remediation_cmd: "chmod 600 {path}",
                };
                audit_file(&file_path, &priv_key_rule, report, record_compliant);
            } else if file_name == "authorized_keys" {
                let auth_keys_rule = ExpectedRule {
                    max_mode: 0o600,
                    disallow_bits: 0o022,
                    expected_uid: Some(owner_uid),
                    title: "Fichier SSH authorized_keys",
                    description: "Si authorized_keys est altérable par un tiers, une compromission directe est possible",
                    severity_if_broken: SeverityLevel::Critical,
                    remediation_cmd: "chmod 600 {path}",
                };
                audit_file(&file_path, &auth_keys_rule, report, record_compliant);
            } else if file_name == "known_hosts" || file_name == "config" {
                let conf_rule = ExpectedRule {
                    max_mode: 0o644,
                    disallow_bits: 0o022,
                    expected_uid: Some(owner_uid),
                    title: "Fichier de configuration / known_hosts SSH",
                    description: "Les fichiers de configuration SSH ne doivent pas être modifiables par des tiers",
                    severity_if_broken: SeverityLevel::Medium,
                    remediation_cmd: "chmod 644 {path}",
                };
                audit_file(&file_path, &conf_rule, report, record_compliant);
            }
        }
    }
}

pub fn print_text_report(report: &AuditReport, min_severity: SeverityLevel, verbose: bool) {
    println!("{}", "==========================================================".bold().blue());
    println!("{}", "   RAPPORT D'AUDIT PASSIF DES PERMISSIONS CRITIQUES LINUX   ".bold().cyan());
    println!("{}", "==========================================================".bold().blue());
    println!("Fichiers inspectés : {}", report.scanned_files_count);
    println!(
        "Vulnérabilités détectées : {} (Critiques: {}, Hautes: {}, Moyennes: {}, Faibles: {})\n",
        report.findings_count,
        report.critical_count.to_string().red().bold(),
        report.high_count.to_string().magenta().bold(),
        report.medium_count.to_string().yellow(),
        report.low_count.to_string().cyan()
    );

    if verbose && !report.compliant_files.is_empty() {
        println!("{}", "--- FICHIERS CONFORMES ---".bold().green());
        for compliant in &report.compliant_files {
            println!("  [OK] {} (mode: {}, uid: {})", compliant.path, compliant.mode.green(), compliant.uid);
        }
        println!();
    }

    let filtered_findings: Vec<&VulnerabilityFinding> = report
        .findings
        .iter()
        .filter(|f| f.severity >= min_severity)
        .collect();

    if filtered_findings.is_empty() {
        println!("{}", "✓ Aucun problème de permission détecté pour ce filtre.".green().bold());
        return;
    }

    for (index, finding) in filtered_findings.iter().enumerate() {
        let badge = match finding.severity {
            SeverityLevel::Critical => "[CRITIQUE]".white().on_red().bold(),
            SeverityLevel::High => "[HAUTE]   ".black().on_magenta().bold(),
            SeverityLevel::Medium => "[MOYENNE] ".black().on_yellow().bold(),
            SeverityLevel::Low => "[FAIBLE]  ".black().on_cyan().bold(),
            SeverityLevel::Info => "[INFO]    ".black().on_white(),
        };

        println!("{} #{} {}", badge, index + 1, finding.title.bold());
        println!("   Fichier      : {}", finding.path.yellow());
        println!(
            "   Permissions  : Actuel: {} (Attendu: <= {})",
            finding.current_mode.red(),
            finding.expected_mode.green()
        );
        if let Some(exp_uid) = finding.expected_uid {
            println!("   Propriétaire : UID Actuel: {} (Attendu: UID {})", finding.current_uid, exp_uid);
        }
        println!("   Problème     : {}", finding.description);
        println!("   Remédiation  : {}\n", finding.remediation.bold().bright_black());
    }
}

fn main() -> anyhow::Result<()> {
    let cli = Cli::parse();

    let mut report = AuditReport {
        timestamp: std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs().to_string())
            .unwrap_or_else(|_| "0".to_string()),
        ..Default::default()
    };

    scan_system_files(&cli.root, &mut report, cli.verbose);
    scan_user_ssh_directories(&cli.root, &mut report, cli.verbose);

    report.findings_count = report.findings.len();

    if cli.json {
        let json_output = serde_json::to_string_pretty(&report)?;
        println!("{}", json_output);
    } else {
        print_text_report(&report, cli.min_severity, cli.verbose);
    }

    if cli.fail_on_findings && (report.critical_count > 0 || report.high_count > 0) {
        std::process::exit(1);
    }

    Ok(())
}

