        )
        .green()
        .bold()
    );

    Ok(())
}

fn handle_verify(
    db_path: &Path,
    table_filter: Option<String>,
    checksum_col: &str,
    output_json: bool,
) -> Result<()> {
    if !db_path.exists() {
        bail!("Fichier de base de données introuvable : {:?}", db_path);
    }

    let conn = Connection::open_with_flags(db_path, OpenFlags::SQLITE_OPEN_READ_ONLY)?;

    let target_tables = if let Some(tbl) = table_filter {
        vec![tbl]
    } else {
        let detected = discover_auditable_tables(&conn, checksum_col)?;
        if detected.is_empty() {
            bail!(
                "Aucune table contenant la colonne de checksum '{}' n'a été détectée.",
                checksum_col
            );
        }
        detected
    };

    let mut total_records = 0u64;
    let mut valid_records = 0u64;
    let mut corrupted_records = 0u64;
    let mut issues = Vec::new();

    for table in &target_tables {
        let columns = get_table_columns(&conn, table)?;
        let pk_col = get_table_pk_col(&conn, table)?;

        // Filtrer les colonnes qui entrent dans le calcul du checksum (exclure le checksum lui-même et id si auto-incrémenté optionnellement, ici on garde id ou toutes données)
        let data_columns: Vec<String> = columns
            .into_iter()
            .filter(|c| !c.eq_ignore_ascii_case(checksum_col))
            .collect();

        let count_query = format!("SELECT COUNT(*) FROM \"{}\"", table);
        let row_count: u64 = conn.query_row(&count_query, [], |r| r.get(0))?;

        if !output_json {
            println!(
                "{} Table `{}` ({} enregistrements)",
                "==> Audit en cours :".cyan().bold(),
                table.yellow(),
                row_count
            );
        }

        let pb = if !output_json {
            let p = ProgressBar::new(row_count);
            p.set_style(
                ProgressStyle::default_bar()
                    .template("[{elapsed_precise}] [{bar:40.cyan/blue}] {pos}/{len} ({eta})")
                    .context("Template indicatif invalide")?
                    .progress_chars("#>-"),
            );
            Some(p)
        } else {
            None
        };

        let select_cols = format!(
            "\"{}\", \"{}\", {}",
            pk_col,
            checksum_col,
            data_columns
                .iter()
                .map(|c| format!("\"{}\"", c))
                .collect::<Vec<_>>()
                .join(", ")
        );

        let query = format!("SELECT {} FROM \"{}\"", select_cols, table);
        let mut stmt = conn.prepare(&query)?;
        let mut rows = stmt.query([])?;

        while let Some(row) = rows.next()? {
            total_records += 1;
            let row_pk: String = match row.get_ref(0)? {
                ValueRef::Integer(v) => v.to_string(),
                ValueRef::Text(t) => String::from_utf8_lossy(t).to_string(),
                _ => "<unknown>".to_string(),
            };

            let stored_checksum = match row.get_ref(1)? {
                ValueRef::Text(t) => String::from_utf8_lossy(t).to_string(),
                ValueRef::Null => "<NULL>".to_string(),
                _ => "<INVALID_FORMAT>".to_string(),
            };

            let row_values: Vec<(&str, ValueRef)> = data_columns
                .iter()
                .enumerate()
                .map(|(idx, col_name)| {
                    let val = row.get_ref(idx + 2).unwrap_or(ValueRef::Null);
                    (col_name.as_str(), val)
                })
                .collect();

            let computed = compute_row_checksum(row_values);

            if stored_checksum.eq_ignore_ascii_case(&computed) {
                valid_records += 1;
            } else {
                corrupted_records += 1;
                issues.push(RowIssue {
                    table: table.clone(),
                    row_identifier: row_pk,
                    expected_checksum: stored_checksum,
                    computed_checksum: computed,
                    detail: "Le checksum persisté ne correspond pas aux données calculées de la ligne".to_string(),
                });
            }

            if let Some(ref p) = pb {
                p.inc(1);
            }
        }

        if let Some(p) = pb {
            p.finish_and_clear();
        }
    }

    let summary = AuditSummary {
        database: db_path.to_string_lossy().to_string(),
        total_records,
        valid_records,
        corrupted_records,
        issues,
    };

    if output_json {
        let json_str = serde_json::to_string_pretty(&summary)?;
        println!("{}", json_str);
    } else {
        println!("\n{}", "================ RÉSUMÉ DE L'AUDIT ================".bold());
        println!("Base auditée        : {}", summary.database);
        println!("Total enregistrements : {}", summary.total_records);
        println!("Enregistrements sains : {}", summary.valid_records.to_string().green());
        println!(
            "Altérations détectées : {}",
            if summary.corrupted_records == 0 {
                summary.corrupted_records.to_string().green()
            } else {
                summary.corrupted_records.to_string().red().bold()
            }
        );

        if !summary.issues.is_empty() {
            println!("\n{}", "Détail des anomalies :".red().bold());
            for issue in &summary.issues {
                println!(
                    " - [{}] {} ID {}:",
                    "CORRUPTION".red().bold(),
                    issue.table.yellow(),
                    issue.row_identifier.cyan()
                );
                println!("     Attendu  : {}", issue.expected_checksum.dimmed());
                println!("     Calculé  : {}", issue.computed_checksum.red());
            }
            println!();
            bail!("Échec de l'audit : {} corruption(s) d'intégrité détectée(s).", summary.corrupted_records);
        } else {
            println!("\n{}", "✔ Intégrité vérifiée avec succès : 100% des checksums sont valides.".green().bold());
        }
    }

    if summary.corrupted_records > 0 && output_json {
        std::process::exit(1);
    }

    Ok(())
}

fn handle_rehash(db_path: &Path, table: &str, checksum_col: &str) -> Result<()> {
    if !db_path.exists() {
        bail!("Fichier de base de données introuvable : {:?}", db_path);
    }

    let mut conn = Connection::open(db_path)?;
    let columns = get_table_columns(&conn, table)?;
    let pk_col = get_table_pk_col(&conn, table)?;

    if !columns.iter().any(|c| c.eq_ignore_ascii_case(checksum_col)) {
        bail!(
            "La table '{}' ne possède pas la colonne '{}'.",
            table,
            checksum_col
        );
    }

    let data_columns: Vec<String> = columns
        .into_iter()
        .filter(|c| !c.eq_ignore_ascii_case(checksum_col))
        .collect();

    let count_query = format!("SELECT COUNT(*) FROM \"{}\"", table);
    let total_rows: u64 = conn.query_row(&count_query, [], |r| r.get(0))?;

    println!(
        "{} Table `{}` ({} enregistrements)",
        "==> Recalcul des empreintes pour la table :".cyan().bold(),
        table.yellow(),
        total_rows
    );

    let pb = ProgressBar::new(total_rows);
    pb.set_style(
        ProgressStyle::default_bar()
            .template("[{elapsed_precise}] [{bar:40.green/blue}] {pos}/{len} ({eta})")
            .context("Template indicatif invalide")?
            .progress_chars("#>-"),
    );

    let select_cols = format!(
        "\"{}\", {}",
        pk_col,
        data_columns
            .iter()
            .map(|c| format!("\"{}\"", c))
            .collect::<Vec<_>>()
            .join(", ")
    );

    let query = format!("SELECT {} FROM \"{}\"", select_cols, table);
    let mut stmt = conn.prepare(&query)?;
    let mut rows = stmt.query([])?;

    let mut updates: Vec<(String, String)> = Vec::new();

    while let Some(row) = rows.next()? {
        let row_pk: String = match row.get_ref(0)? {
            ValueRef::Integer(v) => v.to_string(),
            ValueRef::Text(t) => String::from_utf8_lossy(t).to_string(),
            _ => bail!("Type de clé primaire non supporté pour rehash"),
        };

        let row_values: Vec<(&str, ValueRef)> = data_columns
            .iter()
            .enumerate()
            .map(|(idx, col_name)| {
                let val = row.get_ref(idx + 1).unwrap_or(ValueRef::Null);
                (col_name.as_str(), val)
            })
            .collect();

        let new_hash = compute_row_checksum(row_values);
        updates.push((row_pk, new_hash));
        pb.inc(1);
    }
    pb.finish_and_clear();

    drop(rows);
    drop(stmt);

    let tx = conn.transaction()?;
    let update_sql = format!(
        "UPDATE \"{}\" SET \"{}\" = ?1 WHERE \"{}\" = ?2",
        table, checksum_col, pk_col
    );
    let mut update_stmt = tx.prepare(&update_sql)?;

    for (pk, hash) in updates {
        update_stmt.execute(rusqlite::params![hash, pk])?;
    }
    drop(update_stmt);
    tx.commit()?;

    println!(
        "{}",
        format!("✔ Recalcul et mise à jour terminés avec succès pour '{}'.", table)
            .green()
            .bold()
    );

    Ok(())
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::InitDemo {
            db_path,
            records,
            corruptions,
        } => handle_init_demo(&db_path, records, corruptions),
        Commands::Verify {
            db_path,
            table,
            checksum_col,
            json,
        } => handle_verify(&db_path, table, &checksum_col, json),
        Commands::Rehash {
            db_path,
            table,
            checksum_col,
        } => handle_rehash(&db_path, &table, &checksum_col),
    }
}

