use ed25519_dalek::{Signature, Signer, SigningKey, Verifier, VerifyingKey};
use rand::rngs::OsRng;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use thiserror::Error;

#[derive(Error, Debug)]
pub enum AppError {
    #[error("Erreur I/O : {0}")]
    Io(#[from] io::Error),

    #[error("Erreur de décodage hexadécimal : {0}")]
    HexDecode(#[from] hex::FromHexError),

    #[error("Erreur de décodage base64 : {0}")]
    Base64Decode(#[from] base64::DecodeError),

    #[error("Format de clé cryptographique invalide ({expected} octets attendus, {got} obtenus)")]
    InvalidKeyLength { expected: usize, got: usize },

    #[error("Erreur cryptographique : {0}")]
    Crypto(#[from] ed25519_dalek::SignatureError),

    #[error("Erreur de sérialisation JSON : {0}")]
    Json(#[from] serde_json::Error),

    #[error("Échec de vérification : la signature numérique ne correspond pas au contenu du binaire.")]
    VerificationFailed,

    #[error("Paramètre manquant : {0}")]
    MissingParameter(String),

    #[error("Erreur d'encodage non reconnu : {0}")]
    InvalidEncoding(String),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, ValueEnum)]
#[serde(rename_all = "lowercase")]
pub enum EncodingFormat {
    Hex,
    Base64,
}

impl FromStr for EncodingFormat {
    type Err = AppError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s.to_ascii_lowercase().as_str() {
            "hex" => Ok(EncodingFormat::Hex),
            "base64" | "b64" => Ok(EncodingFormat::Base64),
            _ => Err(AppError::InvalidEncoding(s.to_string())),
        }
    }
}

impl EncodingFormat {
    pub fn encode(&self, bytes: &[u8]) -> String {
        match self {
            EncodingFormat::Hex => hex::encode(bytes),
            EncodingFormat::Base64 => B64.encode(bytes),
        }
    }

    pub fn decode(&self, text: &str) -> Result<Vec<u8>, AppError> {
        let trimmed = text.trim();
        match self {
            EncodingFormat::Hex => Ok(hex::decode(trimmed)?),
            EncodingFormat::Base64 => Ok(B64.decode(trimmed)?),
        }
    }
}

/// Manifeste complet de signature numérique détachée au format JSON
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DetachedSignatureManifest {
    pub target_file: String,
    pub file_size: u64,
    pub sha256: String,
    pub encoding: EncodingFormat,
    pub public_key: String,
    pub signature: String,
}

#[derive(Parser, Debug)]
#[command(
    name = "bin-detached-signer",
    version = "0.1.0",
    about = "Générateur et vérificateur de signatures numériques détachées pour binaires (Hex & Base64)",
    long_about = None
)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Génère une paire de clés Ed25519 (privée et publique)
    Keygen(KeygenArgs),

    /// Signe un fichier binaire et produit une signature détachée
    Sign(SignArgs),

    /// Vérifie la signature détachée d'un fichier binaire
    Verify(VerifyArgs),
}

#[derive(Args, Debug)]
struct KeygenArgs {
    /// Chemin du fichier de destination pour la clé privée
    #[arg(short = 's', long = "secret-key", default_value = "private.key")]
    secret_key_file: PathBuf,

    /// Chemin du fichier de destination pour la clé publique
    #[arg(short = 'p', long = "public-key", default_value = "public.key")]
    public_key_file: PathBuf,

    /// Format d'encodage des clés sauvegardées
    #[arg(short = 'e', long = "encoding", default_value = "hex")]
    encoding: EncodingFormat,
}

#[derive(Args, Debug)]
struct SignArgs {
    /// Chemin vers le fichier binaire à signer
    #[arg(short = 'f', long = "file")]
    file: PathBuf,

    /// Chemin vers le fichier de la clé privée de signature
    #[arg(short = 'k', long = "key")]
    key_file: PathBuf,

    /// Format d'encodage de la clé privée (détecté ou spécifié)
    #[arg(long = "key-encoding", default_value = "hex")]
    key_encoding: EncodingFormat,

    /// Format d'encodage de la signature générée
    #[arg(short = 'e', long = "encoding", default_value = "hex")]
    encoding: EncodingFormat,

    /// Chemin du fichier de sortie pour la signature détachée (stdout si non spécifié)
    #[arg(short = 'o', long = "output")]
    output_file: Option<PathBuf>,

    /// Exporter uniquement la chaîne brute de la signature au lieu du manifeste JSON
    #[arg(long = "raw")]
    raw: bool,
}

#[derive(Args, Debug)]
struct VerifyArgs {
    /// Chemin vers le fichier binaire à vérifier
    #[arg(short = 'f', long = "file")]
    file: PathBuf,

    /// Fichier de manifeste contenant la signature détachée au format JSON
    #[arg(short = 'm', long = "manifest")]
    manifest_file: Option<PathBuf>,

    /// Chemin vers le fichier de clé publique (requis si aucun manifeste n'est fourni)
    #[arg(short = 'p', long = "public-key")]
    public_key_file: Option<PathBuf>,

    /// Fichier contenant la signature brute
    #[arg(short = 's', long = "signature-file")]
    signature_file: Option<PathBuf>,

    /// Chaîne de signature brute fournie en ligne de commande
    #[arg(long = "sig")]
    signature_str: Option<String>,

    /// Encodage de la signature et de la clé publique (requis pour la vérification manuelle)
    #[arg(short = 'e', long = "encoding", default_value = "hex")]
    encoding: EncodingFormat,
}

/// Lit entièrement un fichier binaire pour calculer son SHA256 et signer/vérifier ses données
fn read_and_hash_file(path: &Path) -> Result<(Vec<u8>, String, u64), AppError> {
    let file = File::open(path)?;
    let metadata = file.metadata()?;
    let file_size = metadata.len();

    let mut reader = BufReader::new(file);
    let mut data = Vec::with_capacity(file_size as usize);
    reader.read_to_end(&mut data)?;

    let mut hasher = Sha256::new();
    hasher.update(&data);
    let digest = hasher.finalize();
    let sha256_hex = hex::encode(digest);

    Ok((data, sha256_hex, file_size))
}

fn load_signing_key(path: &Path, encoding: EncodingFormat) -> Result<SigningKey, AppError> {
    let content = fs::read_to_string(path)?;
    let bytes = encoding.decode(&content)?;
    if bytes.len() != 32 {
        return Err(AppError::InvalidKeyLength {
            expected: 32,
            got: bytes.len(),
        });
    }

    let mut key_bytes = [0u8; 32];
    key_bytes.copy_from_slice(&bytes);
    Ok(SigningKey::from_bytes(&key_bytes))
}

fn load_verifying_key(path: &Path, encoding: EncodingFormat) -> Result<VerifyingKey, AppError> {
    let content = fs::read_to_string(path)?;
    parse_verifying_key(&content, encoding)
}

fn parse_verifying_key(key_str: &str, encoding: EncodingFormat) -> Result<VerifyingKey, AppError> {
    let bytes = encoding.decode(key_str)?;
    if bytes.len() != 32 {
        return Err(AppError::InvalidKeyLength {
            expected: 32,
            got: bytes.len(),
        });
    }

    let mut key_bytes = [0u8; 32];
    key_bytes.copy_from_slice(&bytes);
    VerifyingKey::from_bytes(&key_bytes).map_err(AppError::Crypto)
}

fn parse_signature(sig_str: &str, encoding: EncodingFormat) -> Result<Signature, AppError> {
    let bytes = encoding.decode(sig_str)?;
    if bytes.len() != 64 {
        return Err(AppError::InvalidKeyLength {
            expected: 64,
            got: bytes.len(),
        });
    }

    let mut sig_bytes = [0u8; 64];
    sig_bytes.copy_from_slice(&bytes);
    Ok(Signature::from_bytes(&sig_bytes))
}

fn run_keygen(args: KeygenArgs) -> Result<(), AppError> {
    let mut csprng = OsRng;
    let signing_key = SigningKey::generate(&mut csprng);
    let verifying_key = signing_key.verifying_key();

    let secret_encoded = args.encoding.encode(&signing_key.to_bytes());
    let public_encoded = args.encoding.encode(verifying_key.as_bytes());

    fs::write(&args.secret_key_file, format!("{}\n", secret_encoded))?;
    fs::write(&args.public_key_file, format!("{}\n", public_encoded))?;

    println!("✓ Paire de clés générée avec succès ({:?}) :", args.encoding);
    println!("  - Clé privée sauvegardée dans : {}", args.secret_key_file.display());
    println!("  - Clé publique sauvegardée dans : {}", args.public_key_file.display());
    println!("  - Clé publique : {}", public_encoded);

    Ok(())
}

fn run_sign(args: SignArgs) -> Result<(), AppError> {
    let signing_key = load_signing_key(&args.key_file, args.key_encoding)?;
    let verifying_key = signing_key.verifying_key();

    let (file_data, sha256_hex, file_size) = read_and_hash_file(&args.file)?;

    // Signature cryptographique détachée
    let signature = signing_key.sign(&file_data);
    let sig_encoded = args.encoding.encode(&signature.to_bytes());
    let pubkey_encoded = args.encoding.encode(verifying_key.as_bytes());

    let file_name = args
        .file
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("unknown")
        .to_string();

    let output_text = if args.raw {
        sig_encoded.clone()
    } else {
        let manifest = DetachedSignatureManifest {
            target_file: file_name,
            file_size,
            sha256: sha256_hex.clone(),
            encoding: args.encoding,
            public_key: pubkey_encoded,
            signature: sig_encoded.clone(),
        };
        serde_json::to_string_pretty(&manifest)?
    };

    if let Some(ref out_path) = args.output_file {
        fs::write(out_path, format!("{}\n", output_text))?;
        println!("✓ Signature détachée enregistrée dans : {}", out_path.display());
        println!("  - Fichier binaire : {}", args.file.display());
        println!("  - SHA-256 : {}", sha256_hex);
        println!("  - Format : {:?}", args.encoding);
    } else {
        println!("{}", output_text);
    }

    Ok(())
}

fn run_verify(args: VerifyArgs) -> Result<(), AppError> {
    let (file_data, sha256_hex, _) = read_and_hash_file(&args.file)?;

    let (verifying_key, signature, encoding_used) = if let Some(ref manifest_path) = args.manifest_file {
        let content = fs::read_to_string(manifest_path)?;
        let manifest: DetachedSignatureManifest = serde_json::from_str(&content)?;

        // Contrôle facultatif du SHA-256 consigné dans le manifeste
        if !manifest.sha256.is_empty() && !manifest.sha256.eq_ignore_ascii_case(&sha256_hex) {
            eprintln!(
                "AVERTISSEMENT : Le hash SHA-256 calculé ({}) diffère de celui du manifeste ({}).",
                sha256_hex, manifest.sha256
            );
        }

        let vk = parse_verifying_key(&manifest.public_key, manifest.encoding)?;
        let sig = parse_signature(&manifest.signature, manifest.encoding)?;
        (vk, sig, manifest.encoding)
    } else {
        // Mode direct avec clé publique et signature spécifiées
        let pubkey_file = args.public_key_file.ok_or_else(|| {
            AppError::MissingParameter(
                "Le chemin vers la clé publique (--public-key) ou le fichier manifeste (--manifest) est requis.".to_string(),
            )
        })?;
        let vk = load_verifying_key(&pubkey_file, args.encoding)?;

        let sig_str = if let Some(raw_sig) = args.signature_str {
            raw_sig
        } else if let Some(sig_file) = args.signature_file {
            fs::read_to_string(sig_file)?
        } else {
            return Err(AppError::MissingParameter(
                "La signature (--sig ou --signature-file) est obligatoire.".to_string(),
            ));
        };

        let sig = parse_signature(&sig_str, args.encoding)?;
        (vk, sig, args.encoding)
    };

    // Vérification cryptographique
    match verifying_key.verify(&file_data, &signature) {
        Ok(()) => {
            println!("✓ SUCCÈS : La signature numérique détachée est VALIDE.");
            println!("  - Binaire vérifié : {}", args.file.display());
            println!("  - Empreinte SHA256 : {}", sha256_hex);
            println!("  - Encodage : {:?}", encoding_used);
            Ok(())
        }
        Err(_) => Err(AppError::VerificationFailed),
    }
}

fn main() {
    let cli = Cli::parse();

    let result = match cli.command {
        Commands::Keygen(args) => run_keygen(args),
        Commands::Sign(args) => run_sign(args),
        Commands::Verify(args) => run_verify(args),
    };

    if let Err(err) = result {
        eprintln!("ERREUR : {}", err);
        std::process::exit(1);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_encoding_hex_and_base64() {
        let sample = b"Test payload bytes for detached signing";

        let hex_encoded = EncodingFormat::Hex.encode(sample);
        let hex_decoded = EncodingFormat::Hex.decode(&hex_encoded).unwrap();
        assert_eq!(sample.as_slice(), hex_decoded.as_slice());

        let b64_encoded = EncodingFormat::Base64.encode(sample);
        let b64_decoded = EncodingFormat::Base64.decode(&b64_encoded).unwrap();
        assert_eq!(sample.as_slice(), b64_decoded.as_slice());
    }

    #[test]
    fn test_signature_roundtrip() {
        let mut csprng = OsRng;
        let signing_key = SigningKey::generate(&mut csprng);
        let verifying_key = signing_key.verifying_key();
        let payload = b"Hello world detached binary content";

        let signature = signing_key.sign(payload);

        // Test hex roundtrip
        let sig_hex = EncodingFormat::Hex.encode(&signature.to_bytes());
        let parsed_sig = parse_signature(&sig_hex, EncodingFormat::Hex).unwrap();
        assert!(verifying_key.verify(payload, &parsed_sig).is_ok());

        // Test base64 roundtrip
        let sig_b64 = EncodingFormat::Base64.encode(&signature.to_bytes());
        let parsed_sig_b64 = parse_signature(&sig_b64, EncodingFormat::Base64).unwrap();
        assert!(verifying_key.verify(payload, &parsed_sig_b64).is_ok());
    }
}

