#[derive(Error, Debug)]
pub enum AppError {
    #[error("Erreur I/O : {0}")]
    Io(#[from] io::Error),

    #[error("Erreur de décodage hexadécimal : {0}")]
    HexDecode(#[from] hex::FromHexError),

    #[error("Erreur de décodage base64 : {0}")]
    Base64Decode(#[from] base64::DecodeError),

    #[error("Format de clé cryptographique invalide ({expected} octets attendus, {got} obtenus)")]
    InvalidKeyLength { expected: usize, got: usize },

    #[error("Erreur cryptographique : {0}")]
    Crypto(#[from] ed25519_dalek::SignatureError),

    #[error("Erreur de sérialisation JSON : {0}")]
    Json(#[from] serde_json::Error),

    #[error("Échec de vérification : la signature numérique ne correspond pas au contenu du binaire.")]
    VerificationFailed,

    #[error("Paramètre manquant : {0}")]
    MissingParameter(String),

    #[error("Erreur d'encodage non reconnu : {0}")]
    InvalidEncoding(String),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, ValueEnum)]
#[serde(rename_all = "lowercase")]
pub enum EncodingFormat {
    Hex,
    Base64,
}

impl FromStr for EncodingFormat {
    type Err = AppError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s.to_ascii_lowercase().as_str() {
            "hex" => Ok(EncodingFormat::Hex),
            "base64" | "b64" => Ok(EncodingFormat::Base64),
            _ => Err(AppError::InvalidEncoding(s.to_string())),
        }
    }
}

impl EncodingFormat {
    pub fn encode(&self, bytes: &[u8]) -> String {
        match self {
            EncodingFormat::Hex => hex::encode(bytes),
            EncodingFormat::Base64 => B64.encode(bytes),
        }
    }

    pub fn decode(&self, text: &str) -> Result<Vec<u8>, AppError> {
        let trimmed = text.trim();
        match self {
            EncodingFormat::Hex => Ok(hex::decode(trimmed)?),
            EncodingFormat::Base64 => Ok(B64.decode(trimmed)?),
        }
    }
}

