// src/main.rs
use anyhow::{bail, Context, Result};
use clap::{Parser, Subcommand};
use sha2::{Digest, Sha512};
use std::net::SocketAddr;
use std::path::PathBuf;
use tokio::fs::File;
use tokio::io::{AsyncRead, AsyncReadExt, AsyncWrite, AsyncWriteExt};
use tokio::net::{TcpListener, TcpStream};

const BUFFER_SIZE: usize = 64 * 1024; // 64 KiB buffer pour le streaming

#[derive(Parser, Debug)]
#[command(
    name = "stream-sha-guard",
    author = "Damien",
    version = "0.1.0",
    about = "Sécurise et valide des transferts réseau avec empreinte SHA-512 tronquée",
    long_about = "Outil en ligne de commande pour streamer des données via TCP ou depuis stdin/fichier, en calculant et vérifiant à la volée une empreinte SHA-512 tronquée."
)]
struct Cli {
    #[command(subcommand)]
    command: Commands,

    /// Nombre d'octets de l'empreinte SHA-512 à conserver (entre 1 et 64, défaut 32 pour 256 bits)
    #[arg(short = 't', long, default_value_t = 32, global = true)]
    truncate_bytes: usize,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Envoie des données via TCP vers une adresse cible et calcule l'empreinte
    Send {
        /// Adresse cible (ex: 127.0.0.1:8080)
        #[arg(short, long)]
        target: SocketAddr,

        /// Fichier source (si absent, lit depuis l'entrée standard)
        #[arg(short, long)]
        input: Option<PathBuf>,
    },

    /// Écoute sur un port TCP, reçoit un flux de données et valide l'empreinte
    Recv {
        /// Adresse d'écoute (ex: 0.0.0.0:8080)
        #[arg(short, long)]
        bind: SocketAddr,

        /// Fichier de sortie optionnel pour enregistrer le flux reçu
        #[arg(short, long)]
        output: Option<PathBuf>,

        /// Empreinte hexadécimale attendue pour validation d'intégrité
        #[arg(short, long)]
        expected: Option<String>,
    },

    /// Calcule l'empreinte SHA-512 tronquée sur un fichier local ou stdin sans transfert réseau
    Hash {
        /// Fichier à analyser (si absent, lit depuis stdin)
        #[arg(short, long)]
        file: Option<PathBuf>,

        /// Empreinte hexadécimale attendue à comparer
        #[arg(short, long)]
        expected: Option<String>,
    },
}

/// Extrait et formate l'empreinte tronquée à partir d'un hasher SHA-512
fn finalize_truncated_hash(hasher: Sha512, truncate_bytes: usize) -> (Vec<u8>, String) {
    let result = hasher.finalize();
    let truncated_bytes = result[..truncate_bytes].to_vec();
    let hex_repr = hex::encode(&truncated_bytes);
    (truncated_bytes, hex_repr)
}

/// Lit depuis `reader`, met à jour le hasher SHA-512 et redirige vers `writer` si présent
async fn process_stream<R, W>(
    mut reader: R,
    mut writer: Option<W>,
    truncate_bytes: usize,
) -> Result<(u64, String)>
where
    R: AsyncRead + Unpin,
    W: AsyncWrite + Unpin,
{
    let mut hasher = Sha512::new();
    let mut buffer = vec![0u8; BUFFER_SIZE];
    let mut total_bytes: u64 = 0;

    loop {
        let bytes_read = reader
            .read(&mut buffer)
            .await
            .context("Erreur lors de la lecture du flux")?;

        if bytes_read == 0 {
            break;
        }

        hasher.update(&buffer[..bytes_read]);
        total_bytes += bytes_read as u64;

        if let Some(ref mut w) = writer {
            w.write_all(&buffer[..bytes_read])
                .await
                .context("Erreur lors de l'écriture du flux")?;
        }
    }

    if let Some(ref mut w) = writer {
        w.flush().await.context("Erreur lors du flush de l'écriture")?;
    }

    let (_, hex_hash) = finalize_truncated_hash(hasher, truncate_bytes);
    Ok((total_bytes, hex_hash))
}

fn verify_hash(computed: &str, expected: &Option<String>) -> Result<()> {
    if let Some(exp) = expected {
        let clean_expected = exp.trim().to_lowercase();
        let clean_computed = computed.trim().to_lowercase();
        if clean_expected != clean_computed {
            eprintln!("\n❌ ÉCHEC D'INTÉGRITÉ :");
            eprintln!("   Empreinte calculée : {}", clean_computed);
            eprintln!("   Empreinte attendue : {}", clean_expected);
            bail!("Discordance de l'empreinte SHA-512 tronquée : flux altéré ou incorrect.");
        } else {
            println!("✅ Empreinte validée avec succès : concordance parfaite.");
        }
    }
    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();

    if cli.truncate_bytes == 0 || cli.truncate_bytes > 64 {
        bail!("La troncature doit être comprise entre 1 et 64 octets (reçu: {})", cli.truncate_bytes);
    }

    match cli.command {
        Commands::Send { target, input } => {
            println!("Tentative de connexion vers {}...", target);
            let tcp_stream = TcpStream::connect(target)
                .await
                .with_context(|| format!("Impossible de se connecter à {}", target))?;
            println!("Connexion établie avec succès.");

            let (total_bytes, hash_str) = match input {
                Some(path) => {
                    let file = File::open(&path)
                        .await
                        .with_context(|| format!("Impossible d'ouvrir le fichier source {:?}", path))?;
                    println!("Transmission en cours depuis le fichier {:?}...", path);
                    process_stream(file, Some(tcp_stream), cli.truncate_bytes).await?
                }
                None => {
                    println!("Transmission en cours depuis l'entrée standard (stdin)...");
                    let stdin = tokio::io::stdin();
                    process_stream(stdin, Some(tcp_stream), cli.truncate_bytes).await?
                }
            };

            println!("Transfert terminé.");
            println!("Octets envoyés : {}", total_bytes);
            println!(
                "Empreinte SHA-512 tronquée ({} octets) : {}",
                cli.truncate_bytes, hash_str
            );
        }

        Commands::Recv {
            bind,
            output,
            expected,
        } => {
            let listener = TcpListener::bind(bind)
                .await
                .with_context(|| format!("Impossible d'écouter sur {}", bind))?;
            println!("En attente d'une connexion entrante sur {}...", bind);

            let (stream, peer_addr) = listener
                .accept()
                .await
                .context("Erreur lors de l'acceptation de la connexion")?;
            println!("Connexion acceptée depuis {}", peer_addr);

            let (total_bytes, computed_hash) = match output {
                Some(out_path) => {
                    let out_file = File::create(&out_path)
                        .await
                        .with_context(|| format!("Impossible de créer le fichier {:?}", out_path))?;
                    println!("Réception et écriture vers {:?}...", out_path);
                    process_stream(stream, Some(out_file), cli.truncate_bytes).await?
                }
                None => {
                    println!("Réception en cours (aucun fichier de sortie, hachage seul)...");
                    let none_sink: Option<tokio::io::Sink> = None;
                    process_stream(stream, none_sink, cli.truncate_bytes).await?
                }
            };

            println!("Réception terminée.");
            println!("Octets reçus : {}", total_bytes);
            println!(
                "Empreinte SHA-512 tronquée ({} octets) : {}",
                cli.truncate_bytes, computed_hash
            );

            verify_hash(&computed_hash, &expected)?;
        }

        Commands::Hash { file, expected } => {
            let (total_bytes, hash_str) = match file {
                Some(path) => {
                    let f = File::open(&path)
                        .await
                        .with_context(|| format!("Impossible d'ouvrir le fichier {:?}", path))?;
                    let none_sink: Option<tokio::io::Sink> = None;
                    process_stream(f, none_sink, cli.truncate_bytes).await?
                }
                None => {
                    let stdin = tokio::io::stdin();
                    let none_sink: Option<tokio::io::Sink> = None;
                    process_stream(stdin, none_sink, cli.truncate_bytes).await?
                }
            };

            println!("Taille traitée : {} octets", total_bytes);
            println!(
                "Empreinte SHA-512 tronquée ({} octets) : {}",
                cli.truncate_bytes, hash_str
            );

            verify_hash(&hash_str, &expected)?;
        }
    }

    Ok(())
}

