```rust
// src/main.rs
use num_bigint::{BigUint, RandBigInt};
use num_traits::One;
use rand::rngs::ThreadRng;
use sha2::{Digest, Sha256};
use std::fmt;

/// Erreurs possibles lors des opérations du protocole Diffie-Hellman.
#[derive(Debug, PartialEq, Eq)]
pub enum DhError {
    InvalidGroupParameters(&'static str),
    InvalidPublicKey(&'static str),
    HexParsingError(String),
}

impl fmt::Display for DhError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            DhError::InvalidGroupParameters(msg) => write!(f, "Paramètres de groupe invalides : {msg}"),
            DhError::InvalidPublicKey(msg) => write!(f, "Clé publique invalide : {msg}"),
            DhError::HexParsingError(msg) => write!(f, "Erreur de conversion hexadécimale : {msg}"),
        }
    }
}

impl std::error::Error for DhError {}

/// Groupe cyclique pour Diffie-Hellman défini par (p, g).
#[derive(Clone, Debug)]
pub struct DhGroup {
    name: String,
    p: BigUint,
    g: BigUint,
}

impl DhGroup {
    /// Construit un groupe personnalisé en validant les contraintes de base.
    pub fn new(name: impl Into<String>, p: BigUint, g: BigUint) -> Result<Self, DhError> {
        let three = BigUint::from(3u32);
        if p <= three {
            return Err(DhError::InvalidGroupParameters("Le modulo p doit être supérieur à 3"));
        }
        if g <= BigUint::one() || g >= p {
            return Err(DhError::InvalidGroupParameters(
                "Le générateur g doit satisfaire 1 < g < p",
            ));
        }

        Ok(Self {
            name: name.into(),
            p,
            g,
        })
    }

    /// Groupe pédagogique 256-bit (safe prime certifié pour démonstrations rapides).
    pub fn educational_256() -> Result<Self, DhError> {
        // Premier sûr p = 2q + 1 de 256 bits
        let p_256_hex = "FFFFFFFFFFFFFFFFC90FDAA22168C234C4C6628B80DC1CD129024E088A67CC74";
        let p = BigUint::parse_bytes(p_256_hex.as_bytes(), 16)
            .ok_or_else(|| DhError::HexParsingError("Échec du décodage du premier 256 bits".into()))?;
        let g = BigUint::from(2u32);

        Self::new("Pédagogique MODP 256-bit", p, g)
    }

    /// Groupe standard RFC 3526 MODP 2048-bit (recommandé pour les applications réelles).
    pub fn rfc3526_modp_2048() -> Result<Self, DhError> {
        let p_hex = concat!(
            "FFFFFFFFFFFFFFFFC90FDAA22168C234C4C6628B80DC1CD1",
            "29024E088A67CC74020BBEA63B139B22514A08798E3404DD",
