/// Paire de clés pour une session Diffie-Hellman.
#[derive(Clone)]
pub struct DhKeyPair {
    private_key: BigUint,
    public_key: BigUint,
}

impl DhKeyPair {
    /// Génère une paire de clés aléatoires conformes au groupe spécifié.
    pub fn generate(group: &DhGroup, rng: &mut ThreadRng) -> Self {
        let two = BigUint::from(2u32);
        let max_private = group.modulus() - &two;

        // Choix uniforme du secret x dans l'intervalle [2, p - 2]
        let private_key = rng.gen_biguint_range(&two, &max_private);

        // A = g^x mod p
        let public_key = group.generator().modpow(&private_key, group.modulus());

        Self {
            private_key,
            public_key,
        }
    }

    pub fn public_key(&self) -> &BigUint {
        &self.public_key
    }

    /// Calcule le secret partagé brut S = (Y_peer)^x mod p.
    pub fn compute_shared_secret(
        &self,
        group: &DhGroup,
        peer_public_key: &BigUint,
    ) -> Result<BigUint, DhError> {
        group.validate_public_key(peer_public_key)?;
        let shared_secret = peer_public_key.modpow(&self.private_key, group.modulus());
        Ok(shared_secret)
    }
}

/// Acteur communicant au protocole Diffie-Hellman.
pub struct DhParty {
    name: String,
    group: DhGroup,
    keypair: DhKeyPair,
}

impl DhParty {
    pub fn new(name: impl Into<String>, group: DhGroup, rng: &mut ThreadRng) -> Self {
        let keypair = DhKeyPair::generate(&group, rng);
        Self {
            name: name.into(),
            group,
            keypair,
        }
    }

    pub fn name(&self) -> &str {
        &self.name
    }

    pub fn public_key(&self) -> &BigUint {
        self.keypair.public_key()
    }

    /// Dérive le secret partagé et génère une clé de session symétrique via SHA-256.
    pub fn derive_session_key(&self, peer_pub_key: &BigUint) -> Result<[u8; 32], DhError> {
        let secret = self.keypair.compute_shared_secret(&self.group, peer_pub_key)?;
        let secret_bytes = secret.to_bytes_be();

        let mut hasher = Sha256::new();
        hasher.update(&secret_bytes);
        let digest = hasher.finalize();

        let mut key = [0u8; 32];
        key.copy_from_slice(&digest);
        Ok(key)
    }
}

