/// Scénario 1 : Échange légitime entre Alice et Bob sur un groupe 2048-bit.
fn run_legitimate_exchange(group: &DhGroup, rng: &mut ThreadRng) -> Result<(), DhError> {
    println!("\n========================================================");
    println!("  SCÉNARIO 1 : Échange de clés légitime (Alice & Bob)");
    println!("  Groupe utilisé : {}", group.name());
    println!("  Modulo p       : {}", format_bigint_abbrev(group.modulus()));
    println!("  Générateur g   : {}", group.generator());
    println!("========================================================");

    let alice = DhParty::new("Alice", group.clone(), rng);
    let bob = DhParty::new("Bob", group.clone(), rng);

    println!("[1] Génération des clés éphémères :");
    println!("    Clé publique Alice (A) : {}", format_bigint_abbrev(alice.public_key()));
    println!("    Clé publique Bob   (B) : {}", format_bigint_abbrev(bob.public_key()));

    println!("\n[2] Échange sur canal public & calcul du secret partagé :");
    let alice_session_key = alice.derive_session_key(bob.public_key())?;
    let bob_session_key = bob.derive_session_key(alice.public_key())?;

    println!("    Clé dérivée Alice (SHA-256) : {}", format_bytes_hex(&alice_session_key));
    println!("    Clé dérivée Bob   (SHA-256) : {}", format_bytes_hex(&bob_session_key));

    assert_eq!(
        alice_session_key, bob_session_key,
        "Les clés de session doivent être strictement identiques !"
    );
    println!("\n[✓] SUCCÈS : Accord parfait des secrets entre Alice et Bob !");
    Ok(())
}

/// Scénario 2 : Analyse d'écoute passive (Eve) interceptant les valeurs publiques.
fn run_passive_eavesdropper(group: &DhGroup, rng: &mut ThreadRng) -> Result<(), DhError> {
    println!("\n========================================================");
    println!("  SCÉNARIO 2 : Analyse d'écoute passive (Eve)");
    println!("========================================================");

    let alice = DhParty::new("Alice", group.clone(), rng);
    let bob = DhParty::new("Bob", group.clone(), rng);

    let alice_pub = alice.public_key();
    let bob_pub = bob.public_key();

    println!("[1] Données interceptées par Eve sur le réseau :");
    println!("    Modulo p capturé : {}", format_bigint_abbrev(group.modulus()));
    println!("    Générateur g     : {}", group.generator());
    println!("    Clé A d'Alice    : {}", format_bigint_abbrev(alice_pub));
    println!("    Clé B de Bob     : {}", format_bigint_abbrev(bob_pub));

    println!("\n[2] Défi pour Eve :");
    println!("    Pour dériver S = g^(ab) mod p, Eve doit trouver a ou b.");
    println!("    Cela revient à résoudre le problème du logarithme discret (DLP) :");
    println!("    Trouver x tel que g^x ≡ Y mod p pour un grand entier de {} bits.", group.modulus().bits());
    println!("    Sur 2048 bits, la complexité calculatoire avec GNFS est hors de portée des supercalculateurs.");

    let secret_alice = alice.derive_session_key(bob.public_key())?;
    println!("    Clé réelle partagée : {}", format_bytes_hex(&secret_alice));
    println!("[✓] RÉSISTANCE CONFIRMÉE : Eve ne peut pas déduire le secret sans résoudre DLP.");
    Ok(())
}

/// Scénario 3 : Attaque active Man-in-the-Middle (Mallory).
fn run_man_in_the_middle(group: &DhGroup, rng: &mut ThreadRng) -> Result<(), DhError> {
    println!("\n========================================================");
    println!("  SCÉNARIO 3 : Attaque active Man-in-the-Middle (Mallory)");
    println!("========================================================");

    let alice = DhParty::new("Alice", group.clone(), rng);
    let bob = DhParty::new("Bob", group.clone(), rng);
    let mallory_for_alice = DhParty::new("Mallory-vers-Alice", group.clone(), rng);
    let mallory_for_bob = DhParty::new("Mallory-vers-Bob", group.clone(), rng);

    println!("[1] Alice envoie sa clé publique à Bob, mais Mallory intercepte.");
    println!("    Alice envoie A : {}", format_bigint_abbrev(alice.public_key()));
    println!("    Mallory substitue sa propre clé M_A vers Bob : {}", format_bigint_abbrev(mallory_for_bob.public_key()));

    println!("\n[2] Bob envoie sa clé publique à Alice, mais Mallory intercepte.");
    println!("    Bob envoie B   : {}", format_bigint_abbrev(bob.public_key()));
    println!("    Mallory substitue sa propre clé M_B vers Alice : {}", format_bigint_abbrev(mallory_for_alice.public_key()));

    println!("\n[3] Dérivation des clés de session :");
    let key_alice = alice.derive_session_key(mallory_for_alice.public_key())?;
    let key_mallory_alice = mallory_for_alice.derive_session_key(alice.public_key())?;

    let key_bob = bob.derive_session_key(mallory_for_bob.public_key())?;
    let key_mallory_bob = mallory_for_bob.derive_session_key(bob.public_key())?;

    println!("    Clé session Alice               : {}", format_bytes_hex(&key_alice));
    println!("    Clé session Mallory (pour Alice): {}", format_bytes_hex(&key_mallory_alice));
    println!("    Clé session Bob                 : {}", format_bytes_hex(&key_bob));
    println!("    Clé session Mallory (pour Bob)  : {}", format_bytes_hex(&key_mallory_bob));

    assert_eq!(key_alice, key_mallory_alice);
    assert_eq!(key_bob, key_mallory_bob);
    assert_ne!(key_alice, key_bob);

    println!("\n[!] DÉMONSTRATION DE VULNÉRABILITÉ :");
    println!("    Alice et Bob croient communiquer ensemble, mais Mallory déchiffre");
    println!("    et ré-encrypte l'intégralité du trafic sans détection.");
    println!("    Conclusion : Diffie-Hellman seul n'offre pas d'authentification");
    println!("    (nécessite des signatures numériques ou des certificats de clés publiques).");
    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("========================================================");
    println!("   SIMULATEUR DE PROTOCOLE DIFFIE-HELLMAN (RUST)");
    println!("========================================================");

    let mut rng = rand::thread_rng();

    // 1. Initialisation avec le groupe standard RFC 3526 2048-bit
    let group_2048 = DhGroup::rfc3526_modp_2048()?;

    // 2. Démonstrations et simulations
    run_legitimate_exchange(&group_2048, &mut rng)?;
    run_passive_eavesdropper(&group_2048, &mut rng)?;
    run_man_in_the_middle(&group_2048, &mut rng)?;

    println!("\n========================================================");
    println!("  Fin des simulations avec succès.");
    println!("========================================================");

    Ok(())
}

