// src/main.rs
use std::fs::{self, File, OpenOptions};
use std::io::{Seek, SeekFrom, Write};
use std::path::{Path, PathBuf};

use anyhow::{bail, Context, Result};
use clap::Parser;
use indicatif::{ProgressBar, ProgressStyle};
use rand::distributions::Alphanumeric;
use rand::{thread_rng, Rng, RngCore};

/// Taille du tampon d'écriture (64 KiB)
const BUFFER_SIZE: usize = 64 * 1024;

/// Mode d'écrasement pour une passe
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FillPattern {
    Random,
    Zero,
}

#[derive(Parser, Debug)]
#[command(
    name = "secure-shred",
    author = "Damien",
    version = "0.1.0",
    about = "Outil de nettoyage sécurisé écrasant les données d'un fichier avec des octets aléatoires avant suppression."
)]
struct Cli {
    /// Chemin du fichier à détruire de manière sécurisée
    #[arg(value_name = "FILE")]
    target: PathBuf,

    /// Nombre de passes d'écrasement avec des octets aléatoires
    #[arg(short = 'n', long = "iterations", default_value_t = 3)]
    iterations: usize,

    /// Ajouter une passe finale d'écrasement avec des zéros (0x00)
    #[arg(short = 'z', long = "zero")]
    zero_final_pass: bool,

    /// Conserver le fichier après l'avoir écrasé (ne pas le supprimer)
    #[arg(short = 'k', long = "keep", default_value_t = false)]
    keep: bool,

    /// Mode silencieux (masque les barres de progression)
    #[arg(short = 'q', long = "quiet", default_value_t = false)]
    quiet: bool,
}

/// Écrase le contenu du fichier avec un motif spécifique
fn overwrite_pass(
    file: &mut File,
    file_size: u64,
    pattern: FillPattern,
    progress: Option<&ProgressBar>,
) -> Result<()> {
    file.seek(SeekFrom::Start(0))
        .context("Impossible de rembobiner au début du fichier")?;

    let mut rng = thread_rng();
    let mut buffer = vec![0u8; BUFFER_SIZE];
    let mut remaining = file_size;

    while remaining > 0 {
        let chunk_size = std::cmp::min(remaining, BUFFER_SIZE as u64) as usize;
        let chunk = &mut buffer[..chunk_size];

        match pattern {
            FillPattern::Random => {
                rng.fill_bytes(chunk);
            }
            FillPattern::Zero => {
                chunk.fill(0);
            }
        }

        file.write_all(chunk)
            .context("Erreur lors de l'écriture des données d'écrasement")?;

        if let Some(pb) = progress {
            pb.inc(chunk_size as u64);
        }

        remaining -= chunk_size as u64;
    }

    // Force la purge des tampons d'E/S et la synchronisation matérielle avec le stockage
    file.flush()
        .context("Échec du flush du fichier après la passe")?;
    file.sync_all()
        .context("Échec de la synchronisation matérielle (sync_all) du fichier")?;

    Ok(())
}

/// Renomme le fichier avec un nom aléatoire temporaire avant sa suppression définitive
fn obliterate_metadata_and_remove(target_path: &Path, quiet: bool) -> Result<()> {
    let parent = target_path
        .parent()
        .unwrap_or_else(|| Path::new("."));

    let random_name: String = thread_rng()
        .sample_iter(&Alphanumeric)
        .take(16)
        .map(char::from)
        .collect();

    let obfuscated_path = parent.join(format!(".shred_tmp_{}", random_name));

    // Renommer pour masquer l'ancien nom de fichier
    fs::rename(target_path, &obfuscated_path)
        .context("Échec du renommage temporaire pour obfusquer les métadonnées")?;

    // Supprimer le fichier
    fs::remove_file(&obfuscated_path)
        .context("Échec de la suppression définitive du fichier")?;

    if !quiet {
        println!("Fichier supprimé définitivement.");
    }

    Ok(())
}

fn shred_file(cli: &Cli) -> Result<()> {
    let path = &cli.target;

    if !path.exists() {
        bail!("Le fichier spécifié n'existe pas : {}", path.display());
    }

    let metadata = fs::symlink_metadata(path)
        .with_context(|| format!("Impossible de lire les métadonnées de {}", path.display()))?;

    if metadata.is_dir() {
        bail!(
            "La cible '{}' est un répertoire. Seuls les fichiers réguliers sont pris en charge.",
            path.display()
        );
    }

    if metadata.file_type().is_symlink() {
        bail!(
            "La cible '{}' est un lien symbolique. Opération annulée pour éviter d'endommager la cible réelle.",
            path.display()
        );
    }

    let file_size = metadata.len();

    let mut file = OpenOptions::new()
        .write(true)
        .read(false)
        .open(path)
        .with_context(|| format!("Impossible d'ouvrir '{}' en écriture", path.display()))?;

    let total_passes = cli.iterations + if cli.zero_final_pass { 1 } else { 0 };

    if !cli.quiet {
        println!(
            "Déchiquetage de '{}' (Taille: {} octets, Passes: {})",
            path.display(),
            file_size,
            total_passes
        );
    }

    let total_bytes = file_size * total_passes as u64;
    let pb = if !cli.quiet && total_bytes > 0 {
        let bar = ProgressBar::new(total_bytes);
        bar.set_style(
            ProgressStyle::default_bar()
                .template(
                    "{spinner:.green} [{elapsed_precise}] [{bar:40.cyan/blue}] {bytes}/{total_bytes} ({eta}) - {msg}",
                )
                .context("Erreur de configuration du style de barre de progression")?
                .progress_chars("#>-"),
        );
        Some(bar)
    } else {
        None
    };

    // Passes aléatoires
    for pass in 1..=cli.iterations {
        if let Some(ref bar) = pb {
            bar.set_message(format!("Passe {}/{} (Aléatoire)", pass, total_passes));
        }
        overwrite_pass(&mut file, file_size, FillPattern::Random, pb.as_ref())
            .with_context(|| format!("Échec de la passe aléatoire {}/{}", pass, total_passes))?;
    }

    // Passe finale avec zéros si demandée
    if cli.zero_final_pass {
        if let Some(ref bar) = pb {
            bar.set_message(format!("Passe {}/{} (Mise à zéro)", total_passes, total_passes));
        }
        overwrite_pass(&mut file, file_size, FillPattern::Zero, pb.as_ref())
            .with_context(|| format!("Échec de la passe finale de mise à zéro"))?;
    }

    if let Some(ref bar) = pb {
        bar.finish_with_message("Écrasement terminé avec succès.");
    }

    // Fermeture explicite du descripteur de fichier avant suppression
    drop(file);

    // Suppression sécurisée
    if !cli.keep {
        obliterate_metadata_and_remove(path, cli.quiet)?;
    } else if !cli.quiet {
        println!("Fichier conservé selon l'option demandée (--keep).");
    }

    Ok(())
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    if cli.iterations == 0 && !cli.zero_final_pass {
        bail!("Au moins une passe d'écrasement (aléatoire ou zéro) doit être effectuée.");
    }

    shred_file(&cli)?;

    Ok(())
}

