// src/main.rs
use anyhow::{Context, Result};
use clap::Parser;
use serde::Serialize;
use std::fs::File;
use std::io::{BufReader, Read};
use std::path::{Path, PathBuf};

/// CLI d'analyse d'entropie de Shannon sur des fichiers suspects pour détecter du code obfusqué ou compressé.
#[derive(Parser, Debug)]
#[command(author, version, about, long_about = None)]
struct Cli {
    /// Chemins des fichiers ou répertoires à analyser
    #[arg(required = true)]
    paths: Vec<PathBuf>,

    /// Taille des blocs d'analyse glissante / segmentée en octets (défaut : 4096)
    #[arg(short = 'b', long = "block-size", default_value_t = 4096)]
    block_size: usize,

    /// Seuil d'entropie (0.0 à 8.0) au-delà duquel un bloc est considéré suspect
    #[arg(short = 't', long = "threshold", default_value_t = 7.2)]
    threshold: f64,

    /// Activer le parcours récursif si un répertoire est passé en argument
    #[arg(short = 'r', long = "recursive")]
    recursive: bool,

    /// Afficher le détail des segments suspects identifiés
    #[arg(short = 'd', long = "details")]
    show_details: bool,

    /// Formater la sortie au format JSON pour l'automatisation
    #[arg(short = 'j', long = "json")]
    json: bool,
}

/// Niveau de suspicion basé sur l'entropie
#[derive(Debug, Clone, Serialize, PartialEq)]
#[serde(rename_all = "snake_case")]
enum SuspicionLevel {
    Low,
    Moderate,
    Suspicious,
    Critical,
}

impl SuspicionLevel {
    fn from_entropy(entropy: f64, threshold: f64) -> Self {
        if entropy >= threshold || entropy >= 7.5 {
            SuspicionLevel::Critical
        } else if entropy >= 7.0 {
            SuspicionLevel::Suspicious
        } else if entropy >= 5.0 {
            SuspicionLevel::Moderate
        } else {
            SuspicionLevel::Low
        }
    }

    fn label(&self) -> &'static str {
        match self {
            SuspicionLevel::Low => "Faible (texte clair / données simples)",
            SuspicionLevel::Moderate => "Modéré (binaire standard / code machine)",
            SuspicionLevel::Suspicious => "Suspect (obfuscation ou compression probable)",
            SuspicionLevel::Critical => "Critique (chiffrement, packing ou compression forte)",
        }
    }
}

/// Plage suspecte continue dans le fichier
#[derive(Debug, Clone, Serialize)]
struct SuspiciousRange {
    start_offset: u64,
    end_offset: u64,
    length: u64,
    average_entropy: f64,
    max_entropy: f64,
}

/// Rapport d'analyse pour un fichier
#[derive(Debug, Clone, Serialize)]
struct FileReport {
    path: String,
    size_bytes: u64,
    total_blocks: usize,
    overall_entropy: f64,
    max_block_entropy: f64,
    min_block_entropy: f64,
    suspicious_blocks_count: usize,
    suspicious_percentage: f64,
    verdict: SuspicionLevel,
    sparkline: String,
    suspicious_ranges: Vec<SuspiciousRange>,
}

/// Calcule l'entropie de Shannon pour un flux d'octets donné
pub fn calculate_shannon_entropy(data: &[u8]) -> f64 {
    if data.is_empty() {
        return 0.0;
    }

    let mut counts = [0usize; 256];
    for &byte in data {
        counts[byte as usize] += 1;
    }

    let len = data.len() as f64;
    let mut entropy = 0.0f64;

    for &count in &counts {
        if count > 0 {
            let p = count as f64 / len;
            entropy -= p * p.log2();
        }
    }

    entropy
}

/// Convertit une liste de valeurs d'entropie en sparkline ASCII/Unicode (8 niveaux)
fn generate_sparkline(values: &[f64]) -> String {
    if values.is_empty() {
        return String::new();
    }
    const TICKS: [char; 8] = [' ', '▂', '▃', '▄', '▅', '▆', '▇', '█'];
    values
        .iter()
        .map(|&val| {
            // Normalisation sur l'échelle 0.0..=8.0 bits
            let clamped = val.clamp(0.0, 8.0);
            let idx = ((clamped / 8.0) * 7.99).floor() as usize;
            TICKS[idx]
        })
        .collect()
}

/// Analyse un fichier individuel par fenêtrage de blocs
fn analyze_file(path: &Path, block_size: usize, threshold: f64) -> Result<FileReport> {
    let file = File::open(path)
        .with_context(|| format!("Impossible d'ouvrir le fichier : {}", path.display()))?;
    let metadata = file
        .metadata()
        .with_context(|| format!("Impossible de lire les métadonnées : {}", path.display()))?;
    let size_bytes = metadata.len();

    let mut reader = BufReader::new(file);
    let mut global_counts = [0usize; 256];
    let mut buffer = vec![0u8; block_size];

    let mut block_entropies: Vec<f64> = Vec::new();
    let mut current_offset: u64 = 0;

    let mut in_suspicious_run = false;
    let mut run_start_offset = 0u64;
    let mut run_entropies = Vec::new();
    let mut suspicious_ranges = Vec::new();

    loop {
        let bytes_read = reader
            .read(&mut buffer)
            .with_context(|| format!("Erreur de lecture sur {}", path.display()))?;

        if bytes_read == 0 {
            break;
        }

        let slice = &buffer[..bytes_read];

        for &b in slice {
            global_counts[b as usize] += 1;
        }

        let block_ent = calculate_shannon_entropy(slice);
        block_entropies.push(block_ent);

        let is_block_suspicious = block_ent >= threshold;

        if is_block_suspicious {
            if !in_suspicious_run {
                in_suspicious_run = true;
                run_start_offset = current_offset;
                run_entropies.clear();
            }
            run_entropies.push(block_ent);
        } else if in_suspicious_run {
            // Clôture du segment suspect
            let avg: f64 = run_entropies.iter().sum::<f64>() / run_entropies.len() as f64;
            let max: f64 = run_entropies.iter().copied().fold(0.0, f64::max);
            suspicious_ranges.push(SuspiciousRange {
                start_offset: run_start_offset,
                end_offset: current_offset,
                length: current_offset - run_start_offset,
                average_entropy: avg,
                max_entropy: max,
            });
            in_suspicious_run = false;
        }

        current_offset += bytes_read as u64;
    }

    if in_suspicious_run {
        let avg: f64 = run_entropies.iter().sum::<f64>() / run_entropies.len() as f64;
        let max: f64 = run_entropies.iter().copied().fold(0.0, f64::max);
        suspicious_ranges.push(SuspiciousRange {
            start_offset: run_start_offset,
            end_offset: current_offset,
            length: current_offset - run_start_offset,
            average_entropy: avg,
            max_entropy: max,
        });
    }

    // Calcul de l'entropie globale
    let overall_entropy = if size_bytes == 0 {
        0.0
    } else {
        let len_f64 = size_bytes as f64;
        let mut h = 0.0f64;
        for &count in &global_counts {
            if count > 0 {
                let p = count as f64 / len_f64;
                h -= p * p.log2();
            }
        }
        h
    };

    let total_blocks = block_entropies.len();
    let max_block_entropy = block_entropies
        .iter()
        .copied()
        .fold(0.0, f64::max);
    let min_block_entropy = block_entropies
        .iter()
        .copied()
        .fold(8.0, f64::min);
    let suspicious_blocks_count = block_entropies
        .iter()
        .filter(|&&e| e >= threshold)
        .count();

    let suspicious_percentage = if total_blocks == 0 {
        0.0
    } else {
        (suspicious_blocks_count as f64 / total_blocks as f64) * 100.0
    };

    let verdict = if max_block_entropy >= threshold && overall_entropy >= 6.8 {
        SuspicionLevel::Critical
    } else if max_block_entropy >= threshold || overall_entropy >= 6.8 {
        SuspicionLevel::Suspicious
    } else {
        SuspicionLevel::from_entropy(overall_entropy, threshold)
    };

    // Sparkline condensée (max 48 barres si trop de blocs)
    let condensed_entropies = if block_entropies.len() > 48 {
        let chunk_size = (block_entropies.len() as f64 / 48.0).ceil() as usize;
        block_entropies
            .chunks(chunk_size)
            .map(|chunk| chunk.iter().copied().fold(0.0, f64::max))
            .collect::<Vec<_>>()
    } else {
        block_entropies.clone()
    };
    let sparkline = generate_sparkline(&condensed_entropies);

    Ok(FileReport {
        path: path.display().to_string(),
        size_bytes,
        total_blocks,
        overall_entropy,
        max_block_entropy: if total_blocks == 0 { 0.0 } else { max_block_entropy },
        min_block_entropy: if total_blocks == 0 { 0.0 } else { min_block_entropy },
        suspicious_blocks_count,
        suspicious_percentage,
        verdict,
        sparkline,
        suspicious_ranges,
    })
}

/// Collecte les fichiers cibles en gérant la récursivité
fn collect_files(target_path: &Path, recursive: bool, files: &mut Vec<PathBuf>) -> Result<()> {
    if target_path.is_file() {
        files.push(target_path.to_path_buf());
    } else if target_path.is_dir() {
        let entries = std::fs::read_dir(target_path)
            .with_context(|| format!("Lecture du répertoire impossible : {}", target_path.display()))?;

        for entry in entries {
            let entry = entry?;
            let path = entry.path();
            if path.is_file() {
                files.push(path);
            } else if path.is_dir() && recursive {
                collect_files(&path, recursive, files)?;
            }
        }
    } else {
        anyhow::bail!("Chemin introuvable ou inaccessible : {}", target_path.display());
    }
    Ok(())
}

fn print_text_report(report: &FileReport, show_details: bool) {
    println!("------------------------------------------------------------");
    println!("Fichier          : {}", report.path);
    println!("Taille           : {} octets ({:.2} Ko)", report.size_bytes, report.size_bytes as f64 / 1024.0);
    println!("Entropie globale : {:.4} / 8.0000", report.overall_entropy);
    println!("Entropie max/min : {:.4} / {:.4}", report.max_block_entropy, report.min_block_entropy);
    println!(
        "Blocs suspects   : {} / {} ({:.1}%)",
        report.suspicious_blocks_count, report.total_blocks, report.suspicious_percentage
    );
    if !report.sparkline.is_empty() {
        println!("Profil entropie  : [{}]", report.sparkline);
    }
    println!("Diagnostic       : {}", report.verdict.label());

    if show_details && !report.suspicious_ranges.is_empty() {
        println!("\n  Segments suspects détectés :");
        for (i, r) in report.suspicious_ranges.iter().enumerate() {
            println!(
                "  [{:02}] Offset 0x{:08X} - 0x{:08X} ({} octets) | Entropie Moyenne : {:.3} | Max : {:.3}",
                i + 1,
                r.start_offset,
                r.end_offset,
                r.length,
                r.average_entropy,
                r.max_entropy
            );
        }
    }
    println!("------------------------------------------------------------");
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    if cli.block_size == 0 {
        anyhow::bail!("La taille de bloc (--block-size) doit être strictement supérieure à 0.");
    }
    if !(0.0..=8.0).contains(&cli.threshold) {
        anyhow::bail!("Le seuil d'entropie (--threshold) doit être compris entre 0.0 et 8.0.");
    }

    let mut targets = Vec::new();
    for p in &cli.paths {
        collect_files(p, cli.recursive, &mut targets)?;
    }

    if targets.is_empty() {
        eprintln!("Aucun fichier trouvé à analyser.");
        return Ok(());
    }

    let mut reports = Vec::new();
    let mut any_suspicious = false;

    for path in &targets {
        match analyze_file(path, cli.block_size, cli.threshold) {
            Ok(rep) => {
                if rep.verdict == SuspicionLevel::Suspicious || rep.verdict == SuspicionLevel::Critical {
                    any_suspicious = true;
                }
                reports.push(rep);
            }
            Err(e) => {
                eprintln!("Erreur lors de l'analyse de {} : {:#}", path.display(), e);
            }
        }
    }

    if cli.json {
        let json_str = serde_json::to_string_pretty(&reports)
            .context("Erreur de sérialisation JSON")?;
        println!("{}", json_str);
    } else {
        println!("\n=== RAPPORT D'ANALYSE D'ENTROPIE DE SHANNON ===");
        println!("Fichiers analysés : {} | Seuil d'alerte : {:.2} | Taille de bloc : {} octets\n",
            reports.len(), cli.threshold, cli.block_size
        );

        for report in &reports {
            print_text_report(report, cli.show_details);
        }

        if any_suspicious {
            println!("\n[ALERTE] Un ou plusieurs fichiers présentent des caractéristiques de code obfusqué ou compressé.");
        } else {
            println!("\n[OK] Aucun fichier ne dépasse le seuil critique d'entropie.");
        }
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty_entropy() {
        let data = [];
        assert_eq!(calculate_shannon_entropy(&data), 0.0);
    }

    #[test]
    fn test_zero_entropy_single_repeated_byte() {
        let data = [0x41u8; 1024]; // 'A' répété
        let entropy = calculate_shannon_entropy(&data);
        assert_eq!(entropy, 0.0);
    }

    #[test]
    fn test_max_entropy_uniform_distribution() {
        // 256 octets contenant chacun une valeur différente (0..=255)
        let mut data = Vec::with_capacity(256);
        for i in 0..=255u8 {
            data.push(i);
        }
        let entropy = calculate_shannon_entropy(&data);
        // Doit être exactement 8.0 bits
        assert!((entropy - 8.0).abs() < 1e-6);
    }

    #[test]
    fn test_standard_ascii_text_entropy() {
        let text = b"Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.";
        let entropy = calculate_shannon_entropy(text);
        // Le texte ASCII typique a une entropie modérée (environ 3.5 à 4.6 bits)
        assert!(entropy > 3.0 && entropy < 5.0, "Entropie mesurée : {}", entropy);
    }

    #[test]
    fn test_sparkline_generation() {
        let values = [0.0, 2.0, 4.0, 6.0, 8.0];
        let sparkline = generate_sparkline(&values);
        assert_eq!(sparkline.chars().count(), 5);
        assert_eq!(sparkline.chars().next().unwrap(), ' ');
        assert_eq!(sparkline.chars().last().unwrap(), '█');
    }
}

