enum SuspicionLevel {
    Low,
    Moderate,
    Suspicious,
    Critical,
}

impl SuspicionLevel {
    fn from_entropy(entropy: f64, threshold: f64) -> Self {
        if entropy >= threshold || entropy >= 7.5 {
            SuspicionLevel::Critical
        } else if entropy >= 7.0 {
            SuspicionLevel::Suspicious
        } else if entropy >= 5.0 {
            SuspicionLevel::Moderate
        } else {
            SuspicionLevel::Low
        }
    }

    fn label(&self) -> &'static str {
        match self {
            SuspicionLevel::Low => "Faible (texte clair / données simples)",
            SuspicionLevel::Moderate => "Modéré (binaire standard / code machine)",
            SuspicionLevel::Suspicious => "Suspect (obfuscation ou compression probable)",
            SuspicionLevel::Critical => "Critique (chiffrement, packing ou compression forte)",
