                r.end_offset,
                r.length,
                r.average_entropy,
                r.max_entropy
            );
        }
    }
    println!("------------------------------------------------------------");
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    if cli.block_size == 0 {
        anyhow::bail!("La taille de bloc (--block-size) doit être strictement supérieure à 0.");
    }
    if !(0.0..=8.0).contains(&cli.threshold) {
        anyhow::bail!("Le seuil d'entropie (--threshold) doit être compris entre 0.0 et 8.0.");
    }

    let mut targets = Vec::new();
    for p in &cli.paths {
        collect_files(p, cli.recursive, &mut targets)?;
    }

    if targets.is_empty() {
        eprintln!("Aucun fichier trouvé à analyser.");
        return Ok(());
    }

    let mut reports = Vec::new();
    let mut any_suspicious = false;

    for path in &targets {
        match analyze_file(path, cli.block_size, cli.threshold) {
            Ok(rep) => {
                if rep.verdict == SuspicionLevel::Suspicious || rep.verdict == SuspicionLevel::Critical {
                    any_suspicious = true;
                }
                reports.push(rep);
            }
            Err(e) => {
                eprintln!("Erreur lors de l'analyse de {} : {:#}", path.display(), e);
            }
        }
    }

    if cli.json {
        let json_str = serde_json::to_string_pretty(&reports)
            .context("Erreur de sérialisation JSON")?;
        println!("{}", json_str);
    } else {
        println!("\n=== RAPPORT D'ANALYSE D'ENTROPIE DE SHANNON ===");
        println!("Fichiers analysés : {} | Seuil d'alerte : {:.2} | Taille de bloc : {} octets\n",
            reports.len(), cli.threshold, cli.block_size
        );

        for report in &reports {
            print_text_report(report, cli.show_details);
        }

        if any_suspicious {
            println!("\n[ALERTE] Un ou plusieurs fichiers présentent des caractéristiques de code obfusqué ou compressé.");
        } else {
            println!("\n[OK] Aucun fichier ne dépasse le seuil critique d'entropie.");
        }
    }

    Ok(())
}

