        let mut data = Vec::with_capacity(256);
        for i in 0..=255u8 {
            data.push(i);
        }
        let entropy = calculate_shannon_entropy(&data);
        // Doit être exactement 8.0 bits
        assert!((entropy - 8.0).abs() < 1e-6);
    }

