        let entropy = calculate_shannon_entropy(text);
        // Le texte ASCII typique a une entropie modérée (environ 3.5 à 4.6 bits)
        assert!(entropy > 3.0 && entropy < 5.0, "Entropie mesurée : {}", entropy);
