// src/main.rs
use axum::{
    extract::Json,
    http::StatusCode,
    response::{IntoResponse, Response},
    routing::{get, post},
    Router,
};
use base64::prelude::*;
use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::net::SocketAddr;
use tower_http::trace::TraceLayer;
use tracing::{error, info};
use x509_parser::prelude::*;

#[derive(Debug, Deserialize)]
pub struct ValidateCertificateRequest {
    /// Certificat au format PEM (ou DER encodé en base64)
    pub certificate: String,
    /// Émetteur attendu (vérifié sur le Common Name ou la chaîne DN)
    pub expected_issuer: Option<String>,
    /// Instant de vérification cible (optionnel, par défaut l'instant présent UTC)
    pub check_time: Option<DateTime<Utc>>,
}

#[derive(Debug, Serialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum ValidityPeriodStatus {
    Valid,
    NotYetValid,
    Expired,
}

#[derive(Debug, Serialize)]
pub struct TimeValidityDetails {
    pub status: ValidityPeriodStatus,
    pub not_before: DateTime<Utc>,
    pub not_after: DateTime<Utc>,
    pub seconds_remaining: i64,
    pub days_remaining: i64,
}

#[derive(Debug, Serialize)]
pub struct DistinguishedNameInfo {
    pub common_name: Option<String>,
    pub organization: Option<String>,
    pub organizational_unit: Option<String>,
    pub country: Option<String>,
    pub raw_dn: String,
}

#[derive(Debug, Serialize)]
pub struct ValidationResponse {
    pub is_valid: bool,
    pub time_validity: TimeValidityDetails,
    pub issuer: DistinguishedNameInfo,
    pub subject: DistinguishedNameInfo,
    pub is_self_signed: bool,
    pub issuer_matches_expected: Option<bool>,
    pub serial_number: String,
    pub validation_errors: Vec<String>,
}

#[derive(Debug, Serialize)]
pub struct ErrorResponse {
    pub error: String,
    pub details: Option<String>,
}

pub enum AppError {
    BadRequest(String),
    ParseError(String),
    Internal(String),
}

impl IntoResponse for AppError {
    fn into_response(self) -> Response {
        let (status, err_msg) = match self {
            AppError::BadRequest(msg) => (StatusCode::BAD_REQUEST, msg),
            AppError::ParseError(msg) => (StatusCode::UNPROCESSABLE_ENTITY, msg),
            AppError::Internal(msg) => (StatusCode::INTERNAL_SERVER_ERROR, msg),
        };

        let body = Json(ErrorResponse {
            error: err_msg,
            details: None,
        });

        (status, body).into_response()
    }
}

/// Convertit un X509Time de x509-parser en DateTime<Utc> de chrono
fn convert_asn1_time(time: &x509_parser::time::ASN1Time) -> Result<DateTime<Utc>, AppError> {
    DateTime::from_timestamp(time.timestamp(), 0)
        .ok_or_else(|| AppError::Internal("Timestamp de certificat invalide".to_string()))
}

/// Extrait les informations significatives d'un X509Name
fn extract_dn_info(name: &X509Name) -> DistinguishedNameInfo {
    let mut common_name = None;
    let mut organization = None;
    let mut organizational_unit = None;
    let mut country = None;

    for rdn in name.iter() {
        for attr in rdn.iter() {
            let value_str = attr.as_str().unwrap_or_default().to_string();
            let attr_type = attr.attr_type();
            if attr_type == &oid_registry::OID_X509_COMMON_NAME {
                common_name = Some(value_str);
            } else if attr_type == &oid_registry::OID_X509_ORGANIZATION_NAME {
                organization = Some(value_str);
            } else if attr_type == &oid_registry::OID_X509_ORGANIZATIONAL_UNIT {
                organizational_unit = Some(value_str);
            } else if attr_type == &oid_registry::OID_X509_COUNTRY_NAME {
                country = Some(value_str);
            }
        }
    }

    DistinguishedNameInfo {
        common_name,
        organization,
        organizational_unit,
        country,
        raw_dn: name.to_string(),
    }
}

/// Parse le certificat en gérant le format PEM ou DER encodé en base64
fn parse_certificate_bytes(raw_input: &str) -> Result<Vec<u8>, AppError> {
    let trimmed = raw_input.trim();
    if trimmed.contains("-----BEGIN CERTIFICATE-----") {
        if let Some(item) = Pem::iter_from_buffer(trimmed.as_bytes()).next() {
            match item {
                Ok(pem) => return Ok(pem.contents),
                Err(e) => {
                    return Err(AppError::ParseError(format!(
                        "Échec du décodage PEM: {e}"
                    )))
                }
            }
        }
        Err(AppError::BadRequest(
            "Aucun bloc certificat PEM valide trouvé".to_string(),
        ))
    } else {
        // Nettoyage et tentative de décodage base64 direct pour format DER
        let clean_b64: String = trimmed.chars().filter(|c| !c.is_whitespace()).collect();
        BASE64_STANDARD.decode(&clean_b64).map_err(|e| {
            AppError::BadRequest(format!(
                "Format de certificat invalide (ni PEM ni base64 valide): {e}"
            ))
        })
    }
}

async fn validate_certificate_handler(
    Json(payload): Json<ValidateCertificateRequest>,
) -> Result<Json<ValidationResponse>, AppError> {
    if payload.certificate.trim().is_empty() {
        return Err(AppError::BadRequest(
            "Le certificat fourni est vide".to_string(),
        ));
    }

    let der_bytes = parse_certificate_bytes(&payload.certificate)?;
    let (_, x509_cert) = X509Certificate::from_der(&der_bytes).map_err(|e| {
        AppError::ParseError(format!("Impossible de parser la structure X.509 DER: {e}"))
    })?;

    let reference_time = payload.check_time.unwrap_or_else(Utc::now);
    let not_before = convert_asn1_time(&x509_cert.validity().not_before)?;
    let not_after = convert_asn1_time(&x509_cert.validity().not_after)?;

    let (status, seconds_remaining) = if reference_time < not_before {
        (
            ValidityPeriodStatus::NotYetValid,
            (not_before - reference_time).num_seconds(),
        )
    } else if reference_time > not_after {
        (
            ValidityPeriodStatus::Expired,
            (not_after - reference_time).num_seconds(),
        )
    } else {
        (
            ValidityPeriodStatus::Valid,
            (not_after - reference_time).num_seconds(),
        )
    };

    let days_remaining = seconds_remaining / 86400;

    let issuer_info = extract_dn_info(x509_cert.issuer());
    let subject_info = extract_dn_info(x509_cert.subject());

    let is_self_signed = x509_cert.issuer() == x509_cert.subject();

    let mut validation_errors = Vec::new();

    if status != ValidityPeriodStatus::Valid {
        match status {
            ValidityPeriodStatus::NotYetValid => {
                validation_errors.push(format!(
                    "Le certificat n'est pas encore valide (actif à partir du {})",
                    not_before.to_rfc3339()
                ));
            }
            ValidityPeriodStatus::Expired => {
                validation_errors.push(format!(
                    "Le certificat a expiré depuis le {}",
                    not_after.to_rfc3339()
                ));
            }
            ValidityPeriodStatus::Valid => {}
        }
    }

    let issuer_matches_expected = payload.expected_issuer.as_ref().map(|expected| {
        let expected_lower = expected.to_lowercase();
        let matches_cn = issuer_info
            .common_name
            .as_ref()
            .map(|cn| cn.to_lowercase().contains(&expected_lower))
            .unwrap_or(false);
        let matches_dn = issuer_info.raw_dn.to_lowercase().contains(&expected_lower);
        matches_cn || matches_dn
    });

    if let Some(matches) = issuer_matches_expected {
        if !matches {
            validation_errors.push(format!(
                "L'émetteur ne correspond pas au critère attendu: '{}'",
                payload.expected_issuer.unwrap_or_default()
            ));
        }
    }

    let is_valid = validation_errors.is_empty();
    let serial_number = x509_cert.raw_serial_as_string();

    Ok(Json(ValidationResponse {
        is_valid,
        time_validity: TimeValidityDetails {
            status,
            not_before,
            not_after,
            seconds_remaining,
            days_remaining,
        },
        issuer: issuer_info,
        subject: subject_info,
        is_self_signed,
        issuer_matches_expected,
        serial_number,
        validation_errors,
    }))
}

async fn health_check() -> impl IntoResponse {
    (StatusCode::OK, Json(serde_json::json!({ "status": "ok" })))
}

pub fn create_router() -> Router {
    Router::new()
        .route("/health", get(health_check))
        .route("/api/v1/validate", post(validate_certificate_handler))
        .layer(TraceLayer::new_for_http())
}

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "x509_validation_server=info,tower_http=info".into()),
        )
        .init();

    let app = create_router();
    let addr = SocketAddr::from(([0, 0, 0, 0], 8080));

    info!("Serveur de validation X.509 démarré sur http://{}", addr);

    let listener = match tokio::net::TcpListener::bind(addr).await {
        Ok(l) => l,
        Err(err) => {
            error!("Erreur lors de la liaison du port {}: {}", addr, err);
            return;
        }
    };

    if let Err(err) = axum::serve(listener, app).await {
        error!("Erreur d'exécution du serveur HTTP: {}", err);
    }
}

