        issuer: issuer_info,
        subject: subject_info,
        is_self_signed,
        issuer_matches_expected,
        serial_number,
        validation_errors,
    }))
}

async fn health_check() -> impl IntoResponse {
    (StatusCode::OK, Json(serde_json::json!({ "status": "ok" })))
}

pub fn create_router() -> Router {
    Router::new()
        .route("/health", get(health_check))
        .route("/api/v1/validate", post(validate_certificate_handler))
        .layer(TraceLayer::new_for_http())
}

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "x509_validation_server=info,tower_http=info".into()),
        )
        .init();

    let app = create_router();
    let addr = SocketAddr::from(([0, 0, 0, 0], 8080));

    info!("Serveur de validation X.509 démarré sur http://{}", addr);

    let listener = match tokio::net::TcpListener::bind(addr).await {
        Ok(l) => l,
        Err(err) => {
            error!("Erreur lors de la liaison du port {}: {}", addr, err);
            return;
        }
    };

    if let Err(err) = axum::serve(listener, app).await {
        error!("Erreur d'exécution du serveur HTTP: {}", err);
    }
}

