// src/main.rs
use std::fs;
use std::io::{self, Read};
use std::time::{SystemTime, UNIX_EPOCH};

use anyhow::{bail, Context, Result};
use base64::engine::general_purpose::STANDARD as BASE64_STANDARD;
use base64::Engine;
use clap::{Args, Parser, Subcommand, ValueEnum};
use hmac::{Hmac, Mac};
use sha2::{Sha256, Sha512};
use subtle::ConstantTimeEq;

type HmacSha256 = Hmac<Sha256>;
type HmacSha512 = Hmac<Sha512>;

#[derive(Parser, Debug)]
#[command(
    name = "webhook-hmac",
    about = "Générateur et vérificateur de signatures HMAC pour webhooks avec horodatage anti-rejeu",
    version
)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Génère une signature HMAC avec horodatage anti-rejeu
    Sign(SignArgs),
    /// Vérifie la validité d'une signature HMAC et de son horodatage
    Verify(VerifyArgs),
}

#[derive(ValueEnum, Clone, Copy, Debug, PartialEq, Eq)]
enum HashAlgorithm {
    Sha256,
    Sha512,
}

#[derive(ValueEnum, Clone, Copy, Debug, PartialEq, Eq)]
enum OutputEncoding {
    Hex,
    Base64,
}

#[derive(Args, Debug)]
struct PayloadSourceArgs {
    /// Charge utile (payload) passée directement en argument
    #[arg(short, long)]
    payload: Option<String>,

    /// Chemin vers un fichier contenant le payload
    #[arg(short, long)]
    file: Option<String>,
}

#[derive(Args, Debug)]
struct SignArgs {
    #[command(flatten)]
    source: PayloadSourceArgs,

    /// Clé secrète partagée (peut provenir de la variable WEBHOOK_SECRET)
    #[arg(short, long, env = "WEBHOOK_SECRET")]
    secret: String,

    /// Algorithme de hachage HMAC
    #[arg(long, value_enum, default_value_t = HashAlgorithm::Sha256)]
    algo: HashAlgorithm,

    /// Encodage de la signature
    #[arg(long, value_enum, default_value_t = OutputEncoding::Hex)]
    encoding: OutputEncoding,

    /// Horodatage Unix personnalisé en secondes (par défaut : temps actuel)
    #[arg(short, long)]
    timestamp: Option<u64>,

    /// Préfixe de version du schéma de signature (ex. v1)
    #[arg(long, default_value = "v1")]
    version_tag: String,

    /// Affiche uniquement la valeur de la signature sans l'en-tête formaté
    #[arg(long)]
    raw_signature_only: bool,
}

#[derive(Args, Debug)]
struct VerifyArgs {
    #[command(flatten)]
    source: PayloadSourceArgs,

    /// Clé secrète partagée (peut provenir de la variable WEBHOOK_SECRET)
    #[arg(short, long, env = "WEBHOOK_SECRET")]
    secret: String,

    /// Algorithme de hachage HMAC attendu
    #[arg(long, value_enum, default_value_t = HashAlgorithm::Sha256)]
    algo: HashAlgorithm,

    /// En-tête de signature complet reçu (format standard : "t=<timestamp>,v1=<signature>")
    #[arg(long)]
    header: Option<String>,

    /// Horodatage Unix explicite si le header n'est pas fourni
    #[arg(short, long)]
    timestamp: Option<u64>,

    /// Signature brute explicite si le header n'est pas fourni
    #[arg(long)]
    signature: Option<String>,

    /// Préfixe de version attendu
    #[arg(long, default_value = "v1")]
    version_tag: String,

    /// Tolérance maximale en secondes pour contrer les attaques par rejeu
    #[arg(long, default_value_t = 300)]
