}

fn get_current_unix_timestamp() -> Result<u64> {
    let duration = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .context("L'horloge système est antérieure à l'époque UNIX")?;
    Ok(duration.as_secs())
}

fn read_payload(source: &PayloadSourceArgs) -> Result<Vec<u8>> {
    if let Some(ref text) = source.payload {
        return Ok(text.as_bytes().to_vec());
    }

    if let Some(ref path) = source.file {
        return fs::read(path).with_context(|| format!("Impossible de lire le fichier: {}", path));
    }

    // Lecture depuis l'entrée standard
    let mut buffer = Vec::new();
    let bytes_read = io::stdin()
        .read_to_end(&mut buffer)
        .context("Échec de la lecture depuis stdin")?;

    if bytes_read == 0 {
        bail!("Aucune donnée fournie. Spécifiez --payload, --file ou alimentez stdin.");
    }

    Ok(buffer)
}

/// Prépare le message signé : `{timestamp}.{payload}`
fn construct_signed_data(timestamp: u64, payload: &[u8]) -> Vec<u8> {
    let mut data = Vec::with_capacity(32 + payload.len());
    data.extend_from_slice(timestamp.to_string().as_bytes());
    data.push(b'.');
    data.extend_from_slice(payload);
    data
}

fn compute_hmac(algo: HashAlgorithm, secret: &[u8], data: &[u8]) -> Result<Vec<u8>> {
    match algo {
        HashAlgorithm::Sha256 => {
            let mut mac = HmacSha256::new_from_slice(secret)
                .map_err(|e| anyhow::anyhow!("Clé secrète invalide pour HMAC-SHA256: {}", e))?;
            mac.update(data);
            Ok(mac.finalize().into_bytes().to_vec())
        }
        HashAlgorithm::Sha512 => {
            let mut mac = HmacSha512::new_from_slice(secret)
                .map_err(|e| anyhow::anyhow!("Clé secrète invalide pour HMAC-SHA512: {}", e))?;
            mac.update(data);
            Ok(mac.finalize().into_bytes().to_vec())
        }
    }
}

fn encode_bytes(bytes: &[u8], encoding: OutputEncoding) -> String {
    match encoding {
        OutputEncoding::Hex => hex::encode(bytes),
        OutputEncoding::Base64 => BASE64_STANDARD.encode(bytes),
    }
}

fn decode_signature(signature_str: &str) -> Result<Vec<u8>> {
    let trimmed = signature_str.trim();
    if let Ok(decoded_hex) = hex::decode(trimmed) {
        return Ok(decoded_hex);
    }

    BASE64_STANDARD
        .decode(trimmed)
        .context("La signature fournie n'est ni au format Hex ni au format Base64 valide")
}

fn parse_signature_header(header: &str, version_tag: &str) -> Result<(u64, String)> {
    let mut timestamp = None;
    let mut signature = None;

    for part in header.split(',') {
        let mut key_val = part.trim().splitn(2, '=');
        let key = key_val.next().unwrap_or("").trim();
        let val = key_val.next().unwrap_or("").trim();

        if key.is_empty() || val.is_empty() {
            continue;
        }

        if key == "t" {
            let ts: u64 = val
                .parse()
                .with_context(|| format!("Horodatage invalide dans l'en-tête: '{}'", val))?;
            timestamp = Some(ts);
        } else if key == version_tag {
            signature = Some(val.to_string());
        }
    }

    let timestamp = timestamp.context("En-tête manquant pour l'horodatage ('t=...')")?;
    let signature = signature.with_context(|| {
        format!(
            "En-tête manquant pour la signature avec le tag de version ('{}=...')",
            version_tag
        )
    })?;

    Ok((timestamp, signature))
}

fn run_sign(args: SignArgs) -> Result<()> {
    let payload = read_payload(&args.source)?;
    let timestamp = match args.timestamp {
        Some(ts) => ts,
        None => get_current_unix_timestamp()?,
    };

    let data_to_sign = construct_signed_data(timestamp, &payload);
    let mac = compute_hmac(args.algo, args.secret.as_bytes(), &data_to_sign)?;
    let signature = encode_bytes(&mac, args.encoding);

    if args.raw_signature_only {
        println!("{}", signature);
    } else {
        println!("t={},{}={}", timestamp, args.version_tag, signature);
    }

    Ok(())
}

fn run_verify(args: VerifyArgs) -> Result<()> {
    let payload = read_payload(&args.source)?;

    let (timestamp, signature_str) = if let Some(ref header) = args.header {
        parse_signature_header(header, &args.version_tag)?
    } else if let (Some(ts), Some(sig)) = (args.timestamp, args.signature) {
        (ts, sig)
    } else {
        bail!("Veuillez fournir soit --header, soit conjointement --timestamp et --signature.");
    };

    // Vérification anti-rejeu (protection d'horodatage)
    let current_time = get_current_unix_timestamp()?;
    let diff = if current_time >= timestamp {
        current_time - timestamp
    } else {
        // En cas de léger décalage d'horloge du serveur émetteur
        timestamp - current_time
    };

    if diff > args.tolerance_sec {
        bail!(
            "Échec anti-rejeu: l'écart temporel ({}s) dépasse la tolérance maximale ({}s). Timestamp requête: {}, Serveur: {}",
            diff,
            args.tolerance_sec,
            timestamp,
            current_time
        );
    }

    // Calcul de la signature attendue
    let data_to_sign = construct_signed_data(timestamp, &payload);
    let expected_mac = compute_hmac(args.algo, args.secret.as_bytes(), &data_to_sign)?;

    // Décodage de la signature reçue
    let provided_mac = decode_signature(&signature_str)?;

    // Comparaison en temps constant pour éviter les attaques temporelles (timing attacks)
    if expected_mac.ct_eq(&provided_mac).into() {
        println!("Signature valide et horodatage vérifié avec succès.");
        Ok(())
    } else {
        bail!("Signature HMAC invalide !");
    }
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Sign(args) => run_sign(args),
        Commands::Verify(args) => run_verify(args),
    }
}

