mod tests {
    use super::*;

    #[test]
    fn test_signature_roundtrip_hex() {
        let secret = "mon_secret_ultra_securise";
        let payload = b"{\"event\":\"user.created\",\"id\":42}";
        let timestamp = 1727470000;

        let signed_data = construct_signed_data(timestamp, payload);
        let mac = compute_hmac(HashAlgorithm::Sha256, secret.as_bytes(), &signed_data).unwrap();
        let sig_hex = encode_bytes(&mac, OutputEncoding::Hex);

        let decoded = decode_signature(&sig_hex).unwrap();
        assert_eq!(mac.ct_eq(&decoded).unwrap_u8(), 1);
    }

    #[test]
    fn test_signature_roundtrip_base64() {
        let secret = "mon_secret_ultra_securise";
        let payload = b"{\"action\":\"ping\"}";
        let timestamp = 1727470050;

        let signed_data = construct_signed_data(timestamp, payload);
        let mac = compute_hmac(HashAlgorithm::Sha512, secret.as_bytes(), &signed_data).unwrap();
        let sig_b64 = encode_bytes(&mac, OutputEncoding::Base64);

        let decoded = decode_signature(&sig_b64).unwrap();
        assert_eq!(mac.ct_eq(&decoded).unwrap_u8(), 1);
    }

    #[test]
    fn test_parse_signature_header() {
        let header = "t=1727470000,v1=abcdef0123456789";
        let (ts, sig) = parse_signature_header(header, "v1").unwrap();
        assert_eq!(ts, 1727470000);
        assert_eq!(sig, "abcdef0123456789");
    }

    #[test]
    fn test_parse_signature_header_unordered() {
        let header = "v1=abcdef0123456789, t=1727470000";
        let (ts, sig) = parse_signature_header(header, "v1").unwrap();
        assert_eq!(ts, 1727470000);
        assert_eq!(sig, "abcdef0123456789");
    }

    #[test]
    fn test_tampered_payload_fails() {
        let secret = "mon_secret";
        let payload = b"{\"valid\":true}";
        let timestamp = 1727470000;

        let signed_data = construct_signed_data(timestamp, payload);
        let mac = compute_hmac(HashAlgorithm::Sha256, secret.as_bytes(), &signed_data).unwrap();

        let tampered_payload = b"{\"valid\":false}";
        let tampered_signed_data = construct_signed_data(timestamp, tampered_payload);
        let tampered_mac =
            compute_hmac(HashAlgorithm::Sha256, secret.as_bytes(), &tampered_signed_data).unwrap();

        assert_eq!(mac.ct_eq(&tampered_mac).unwrap_u8(), 0);
    }
}

