        "K9$wL#99qPz!rt2".to_string(),
    ]
}

/// Charge les mots de passe depuis un fichier ou renvoie l'échantillon par défaut
fn load_passwords(file_path: Option<&Path>) -> Result<Vec<String>> {
    match file_path {
        Some(path) => {
            let file = File::open(path)
                .with_context(|| format!("Impossible d'ouvrir le fichier {:?}", path))?;
            let reader = BufReader::new(file);
            let mut passwords = Vec::new();
            for line in reader.lines() {
                let l = line?;
                let trimmed = l.trim();
                if !trimmed.is_empty() {
                    passwords.push(trimmed.to_string());
                }
            }
            Ok(passwords)
        }
        None => Ok(get_sample_passwords()),
    }
}

/// Évalue les métriques globales d'un dictionnaire
fn evaluate_dictionary(passwords: &[String], algo: HashAlgorithm) -> DictionaryMetrics {
    let total = passwords.len();
    if total == 0 {
        return DictionaryMetrics {
            total_entries: 0,
            unique_entries: 0,
            min_length: 0,
            max_length: 0,
            avg_length: 0.0,
            avg_entropy: 0.0,
            under_8_chars: 0,
            charset_stats: CharsetStats::default(),
            estimated_rainbow_vulnerability_score: 0.0,
        };
    }

    let mut set = HashSet::with_capacity(total);
    let mut sum_len = 0usize;
    let mut sum_entropy = 0.0f64;
    let mut min_len = usize::MAX;
    let mut max_len = 0usize;
    let mut under_8 = 0usize;
    let mut charset_stats = CharsetStats::default();

    for p in passwords {
        let len = p.chars().count();
        set.insert(p.as_str());
        sum_len += len;
        min_len = min_len.min(len);
        max_len = max_len.max(len);
        if len < 8 {
            under_8 += 1;
        }
        charset_stats.record(p);
        sum_entropy += shannon_entropy(p);
    }

    let avg_len = sum_len as f64 / total as f64;
    let avg_ent = sum_entropy / total as f64;

    // Facteurs aggravants pour les tables arc-en-ciel :
    // - Longueurs courtes (< 8)
    // - Faible entropie (< 3.0 bits)
    // - Charsets étroits (ex: chiffres seuls ou minuscules seules)
    // - Algorithmes rapides non salés (MD5 > SHA1 > SHA256)
    let ratio_under_8 = (under_8 as f64) / (total as f64);
    let ratio_simple_charset =
        (charset_stats.digits_only + charset_stats.lower_alpha_only) as f64 / (total as f64);

    let algo_penalty = match algo {
        HashAlgorithm::Md5 => 1.25,
        HashAlgorithm::Sha1 => 1.10,
        HashAlgorithm::Sha256 => 0.85,
    };

    let base_vuln = (ratio_under_8 * 50.0 + ratio_simple_charset * 30.0 + (4.0 - avg_ent.min(4.0)) * 5.0) * algo_penalty;
    let score = base_vuln.clamp(0.0, 100.0);

    DictionaryMetrics {
        total_entries: total,
        unique_entries: set.len(),
        min_length: min_len,
        max_length: max_len,
        avg_length: avg_len,
        avg_entropy: avg_ent,
        under_8_chars: under_8,
        charset_stats,
        estimated_rainbow_vulnerability_score: score,
    }
}

/// Fonction de réduction arc-en-ciel paramétrée par l'indice d'étape `step`
fn reduction_function(hash: &[u8], step: usize, target_len: usize) -> String {
    const CHARSET: &[u8] = b"abcdefghijklmnopqrstuvwxyz0123456789";
    let mut val = 0u64;
    for &byte in hash.iter().take(8) {
        val = (val << 8) | (byte as u64);
    }
    // Perturbation par l'étape pour varier les fonctions R_i
    val = val.wrapping_add(step as u64);

    let mut result = String::with_capacity(target_len);
    for _ in 0..target_len {
        let idx = (val % (CHARSET.len() as u64)) as usize;
        result.push(CHARSET[idx] as char);
        val = val.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
    }
    result
}

/// Génère une chaîne arc-en-ciel : start_pwd -> H -> R1 -> H -> R2 ... -> end_pwd
fn generate_chain(
    start_pwd: &str,
    chain_len: usize,
    algo: HashAlgorithm,
    target_pwd_len: usize,
) -> String {
    let mut current = start_pwd.to_string();
    for step in 0..chain_len {
        let h = compute_hash(algo, &current);
        current = reduction_function(&h, step, target_pwd_len);
    }
    current
}

/// Simulation d'une table arc-en-ciel pour mesurer empiriquement le taux d'inversion
fn run_simulation(
    passwords: &[String],
    algo: HashAlgorithm,
    chain_len: usize,
    num_chains: usize,
) {
    println!("{}", "=== SIMULATION D'ATTAQUE PAR TABLE ARC-EN-CIEL ===".bold().cyan());
    println!("Algorithme ciblé : {}", algo.to_string().yellow());
    println!("Paramètres table : {} chaînes, longueur de chaîne = {}", num_chains, chain_len);

    // 1. Sélectionner ou synthétiser des points de départ
    let initial_points: Vec<String> = (0..num_chains)
        .map(|i| {
            if i < passwords.len() {
                passwords[i].clone()
            } else {
                format!("p{:05}", i)
            }
        })
        .collect();

    let target_len = 6; // Longueur standard pour la réduction démo

    println!("[*] Génération de la table arc-en-ciel en mémoire (calcul parallèle)...");
    // Table: end_point -> start_point
    let endpoints: Vec<(String, String)> = initial_points
        .par_iter()
        .map(|start| {
            let end = generate_chain(start, chain_len, algo, target_len);
            (end, start.clone())
        })
        .collect();

    let mut rainbow_table: HashMap<String, String> = HashMap::with_capacity(endpoints.len());
    let mut collisions = 0;
    for (end, start) in endpoints {
        if rainbow_table.insert(end, start).is_some() {
            collisions += 1;
        }
    }

    println!("[+] Table générée : {} points finaux uniques ({} collisions détectées)", 
        rainbow_table.len().to_string().green(),
        collisions.to_string().yellow()
    );

    // 2. Tester l'inversion d'un échantillon de cibles
    let test_targets: Vec<String> = passwords.iter().take(20).cloned().collect();
    println!("[*] Test d'inversion sur un échantillon de {} mots de passe...", test_targets.len());

    let mut recovered = 0;
    for target_pwd in &test_targets {
        let target_hash = compute_hash(algo, target_pwd);
        let target_hex = to_hex(&target_hash);

        // Algorithme de recherche dans la table
        let mut found = false;
        'search: for step in (0..chain_len).rev() {
            let mut curr_hash = target_hash.clone();
            let mut curr_cand = String::new();

            for s in step..chain_len {
                curr_cand = reduction_function(&curr_hash, s, target_len);
                curr_hash = compute_hash(algo, &curr_cand);
            }

            // Vérifier si curr_cand est un point final
            if let Some(start_point) = rainbow_table.get(&curr_cand) {
                // Rejouer la chaîne pour vérifier et trouver le pré-image
                let mut test_curr = start_point.clone();
                for s in 0..chain_len {
                    let h = compute_hash(algo, &test_curr);
                    if h == target_hash {
                        found = true;
                        break 'search;
                    }
                    test_curr = reduction_function(&h, s, target_len);
                }
            }
        }

        if found {
            recovered += 1;
            println!("  [CRACKÉ] '{}' (Hash: {}...)", target_pwd.red(), &target_hex[..12]);
        }
    }

    let success_rate = (recovered as f64 / test_targets.len() as f64) * 100.0;
    println!("\nRésultats de la simulation :");
    println!("- Mots de passe testés       : {}", test_targets.len());
    println!("- Inversions réussies        : {}", recovered.to_string().red());
    println!("- Taux de compromission brut : {:.1}%", success_rate);

    if success_rate > 20.0 {
        println!("{}", "[!] Alerte critique : L'absence de sel dynamique rend ce dictionnaire trivialement cassable par tables précalculées.".red().bold());
    } else {
        println!("{}", "[i] Remarque : Augmentez la couverture de la table pour observer une convergence accrue.".italic());
    }
}

/// Affichage du rapport d'analyse
fn print_analysis(metrics: &DictionaryMetrics, algo: HashAlgorithm) {
    println!("{}", "=========================================================".cyan());
    println!("{}", "    RAPPORT D'ÉVALUATION DE RÉSISTANCE AUX TABLES RAINBOW ".bold().cyan());
    println!("{}", "=========================================================".cyan());

    println!("Algorithme évalué        : {}", algo.to_string().bright_yellow());
    println!("Total mots de passe      : {}", metrics.total_entries.to_string().white());
    println!("Entrées uniques          : {}", metrics.unique_entries.to_string().white());
    println!("Longueur min / max / moy : {} / {} / {:.2}", metrics.min_length, metrics.max_length, metrics.avg_length);
    println!("Entropie moyenne de Shannon: {:.2} bits/caractère", metrics.avg_entropy);
    println!("Moins de 8 caractères    : {} ({:.1}%)", 
        metrics.under_8_chars, 
        (metrics.under_8_chars as f64 / metrics.total_entries.max(1) as f64) * 100.0
    );

    println!("\n{}", "Répartition des jeux de caractères :".bold());
    println!("  - Chiffres seuls       : {}", metrics.charset_stats.digits_only);
    println!("  - Minuscules seules    : {}", metrics.charset_stats.lower_alpha_only);
    println!("  - Alphanumériques      : {}", metrics.charset_stats.alphanumeric);
    println!("  - Avec symboles        : {}", metrics.charset_stats.with_symbols);

    println!("\n{}", "Indicateurs de vulnérabilité :".bold());
    let score = metrics.estimated_rainbow_vulnerability_score;
    let score_str = format!("{:.1} / 100", score);
    if score >= 70.0 {
        println!("  Score d'exposition aux tables : {}", score_str.bold().red());
        println!("  Niveau de risque              : {}", "CRITIQUE (Très vulnérable aux rainbow tables)".red());
    } else if score >= 40.0 {
        println!("  Score d'exposition aux tables : {}", score_str.bold().yellow());
        println!("  Niveau de risque              : {}", "MODÉRÉ (Vulnérable si hachage sans sel)".yellow());
    } else {
        println!("  Score d'exposition aux tables : {}", score_str.bold().green());
        println!("  Niveau de risque              : {}", "FAIBLE (Espace de recherche résistant)".green());
    }

    println!("\n{}", "Recommandations de sécurité :".bold().underline());
    if algo == HashAlgorithm::Md5 || algo == HashAlgorithm::Sha1 {
        println!("  1. {} : Remplacer immédiatement {} par une KDF avec sel (Argon2id, bcrypt ou PBKDF2).", "[URGENT]".red(), algo);
    } else {
        println!("  1. {} : Même avec {}, l'absence de sel unique par utilisateur permet des attaques par tables précalculées.", "[IMPORTANT]".yellow(), algo);
    }
    if metrics.under_8_chars > 0 {
        println!("  2. {} : Interdire les mots de passe de moins de 12 à 14 caractères pour pulvériser l'efficacité de stockage des tables.", "[REGLE]".cyan());
    }
    println!("  3. {} : Imposer un sel aléatoire d'au moins 128 bits pour invalider toute table générique précalculée.", "[FONDAMENTAL]".green());
    println!("{}", "=========================================================\n".cyan());
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Analyze { file, algo } => {
            let passwords = load_passwords(file.as_deref())?;
            let metrics = evaluate_dictionary(&passwords, algo);
            print_analysis(&metrics, algo);
        }
        Commands::Simulate {
            file,
            algo,
            chain_len,
            num_chains,
        } => {
            let passwords = load_passwords(file.as_deref())?;
            run_simulation(&passwords, algo, chain_len, num_chains);
        }
    }

    Ok(())
}

