            } else {
                serde_json::to_string(&json_value)?
            };

            write_output(output.as_ref(), &format!("{result}\n"))?;
        }
        Commands::Decrypt {
            input,
            output,
            pretty,
        } => {
            let raw_json = read_input(input.as_ref())?;
            let mut json_value: Value = serde_json::from_str(&raw_json)
