/// Dérive une clé AES-256 (32 octets) à partir d'un mot de passe et d'un sel via Argon2id
fn derive_key(password: &[u8], salt: &[u8]) -> Result<Zeroizing<[u8; 32]>> {
    let mut key = Zeroizing::new([0u8; 32]);
    let argon2 = Argon2::default();
    argon2
        .hash_password_into(password, salt, &mut *key)
        .map_err(|e| anyhow::anyhow!("Erreur lors de la dérivation de clé Argon2: {e}"))?;
    Ok(key)
}

/// Chiffre une valeur en AES-256-GCM et renvoie une chaîne au format `ENC[<salt>:<nonce>:<ciphertext>]`
fn encrypt_value(data: &Value, password: &[u8]) -> Result<String> {
    let serialized = serde_json::to_string(data)
        .context("Impossible de sérialiser la valeur cible pour le chiffrement")?;

    let mut salt = [0u8; SALT_LEN];
    let mut nonce_bytes = [0u8; NONCE_LEN];
    OsRng.fill_bytes(&mut salt);
    OsRng.fill_bytes(&mut nonce_bytes);

    let key = derive_key(password, &salt)?;
    let cipher = Aes256Gcm::new_from_slice(&*key)
        .map_err(|e| anyhow::anyhow!("Échec d'initialisation du chiffreur AES-256-GCM: {e}"))?;
    let nonce = Nonce::from_slice(&nonce_bytes);

    let ciphertext = cipher
        .encrypt(nonce, serialized.as_bytes())
        .map_err(|e| anyhow::anyhow!("Échec du chiffrement AES-GCM: {e}"))?;

    let salt_b64 = BASE64_STANDARD.encode(salt);
    let nonce_b64 = BASE64_STANDARD.encode(nonce_bytes);
    let cipher_b64 = BASE64_STANDARD.encode(ciphertext);

    Ok(format!("{ENC_PREFIX}{salt_b64}:{nonce_b64}:{cipher_b64}{ENC_SUFFIX}"))
}

/// Déchiffre une chaîne au format `ENC[<salt>:<nonce>:<ciphertext>]` et restaure le `Value` d'origine
fn decrypt_value(enc_str: &str, password: &[u8]) -> Result<Value> {
    if !enc_str.starts_with(ENC_PREFIX) || !enc_str.ends_with(ENC_SUFFIX) {
        bail!("Format de chaîne chiffrée non valide");
    }

    let payload = &enc_str[ENC_PREFIX.len()..enc_str.len() - ENC_SUFFIX.len()];
    let parts: Vec<&str> = payload.split(':').collect();
    if parts.len() != 3 {
        bail!("La chaîne chiffrée doit contenir 3 segments séparés par ':'");
    }

    let salt = BASE64_STANDARD
        .decode(parts[0])
        .context("Décodage base64 du sel échoué")?;
    let nonce_bytes = BASE64_STANDARD
        .decode(parts[1])
        .context("Décodage base64 du nonce échoué")?;
    let ciphertext = BASE64_STANDARD
        .decode(parts[2])
        .context("Décodage base64 du texte chiffré échoué")?;

    if nonce_bytes.len() != NONCE_LEN {
        bail!("Longueur du nonce invalide (attendu: {NONCE_LEN} octets)");
    }

    let key = derive_key(password, &salt)?;
    let cipher = Aes256Gcm::new_from_slice(&*key)
        .map_err(|e| anyhow::anyhow!("Échec d'initialisation du déchiffreur AES-256-GCM: {e}"))?;
    let nonce = Nonce::from_slice(&nonce_bytes);

    let decrypted_bytes = cipher
        .decrypt(nonce, ciphertext.as_ref())
        .map_err(|_| anyhow::anyhow!("Échec du déchiffrement (mot de passe incorrect ou données corrompues)"))?;

    let decrypted_str = std::str::from_utf8(&decrypted_bytes)
        .context("Le texte déchiffré n'est pas un flux UTF-8 valide")?;

    let val: Value = serde_json::from_str(decrypted_str)
        .context("Impossible de parser le JSON contenu dans les données déchiffrées")?;

    Ok(val)
}

/// Traite récursivement l'arbre JSON pour chiffrer les champs cibles
fn process_encrypt(value: &mut Value, targets: &HashSet<String>, password: &[u8]) -> Result<()> {
