/// Journal d'audit inviolable garantissant l'intégrité via chaînage cryptographique.
#[derive(Debug, Default, Clone, Serialize, Deserialize)]
pub struct AuditLog {
    entries: Vec<AuditEntry>,
}

impl AuditLog {
    /// Crée un nouveau journal d'audit vide en mémoire.
    pub fn new() -> Self {
        Self {
            entries: Vec::new(),
        }
    }

    /// Ajoute une nouvelle action dans le journal d'audit.
    pub fn append(
        &mut self,
        actor: impl Into<String>,
        action: impl Into<String>,
        payload: impl Into<String>,
    ) -> &AuditEntry {
        let next_index = self.entries.len() as u64;
        let prev_hash = match self.entries.last() {
            Some(last_entry) => last_entry.hash.clone(),
            None => GENESIS_PREV_HASH.to_string(),
        };

        let now = Utc::now();
        let entry = AuditEntry::new(next_index, now, actor, action, payload, prev_hash);
        self.entries.push(entry);
        self.entries.last().expect("Entrée fraîchement insérée présente")
    }

    /// Retourne la liste immuable des entrées.
    pub fn entries(&self) -> &[AuditEntry] {
        &self.entries
    }

    /// Nombre total d'entrées.
    pub fn len(&self) -> usize {
        self.entries.len()
    }

    /// Indique si le journal est vide.
    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    /// Vérifie l'intégrité complète de la chaîne d'audit :
    /// - Index séquentiels stricts (0, 1, 2, ...)
    /// - Validité du hash de chaque entrée par rapport à son contenu
    /// - Continuité du `prev_hash` pointant vers le hash de l'entrée précédente
    pub fn verify_chain(&self) -> Result<(), AuditLogError> {
        let mut expected_prev_hash = GENESIS_PREV_HASH.to_string();

        for (idx, entry) in self.entries.iter().enumerate() {
            let expected_index = idx as u64;

            // 1. Vérification de l'index
            if entry.index != expected_index {
                return Err(AuditLogError::InvalidIndex {
                    expected: expected_index,
                    found: entry.index,
                });
            }

            // 2. Vérification du chaînage prev_hash
            if idx == 0 {
                if entry.prev_hash != GENESIS_PREV_HASH {
                    return Err(AuditLogError::InvalidGenesisHash(entry.prev_hash.clone()));
                }
            } else if entry.prev_hash != expected_prev_hash {
                return Err(AuditLogError::ChainLinkBroken {
                    index: entry.index,
                    expected: expected_prev_hash,
                    found: entry.prev_hash.clone(),
                });
            }

            // 3. Vérification du hash de l'entrée elle-même
            let computed_hash = AuditEntry::compute_hash(
                entry.index,
                &entry.timestamp,
                &entry.actor,
                &entry.action,
                &entry.payload,
                &entry.prev_hash,
            );

            if entry.hash != computed_hash {
                return Err(AuditLogError::InvalidEntryHash {
                    index: entry.index,
                    computed: computed_hash,
                    recorded: entry.hash.clone(),
                });
            }

            expected_prev_hash = entry.hash.clone();
        }

        Ok(())
    }

    /// Sauvegarde le journal dans un fichier JSON.
    pub fn save_to_file<P: AsRef<Path>>(&self, path: P) -> Result<(), AuditLogError> {
        let file = OpenOptions::new()
            .write(true)
            .create(true)
            .truncate(true)
            .open(path)?;
        let mut writer = BufWriter::new(file);
        serde_json::to_writer_pretty(&mut writer, &self.entries)?;
        writer.flush()?;
        Ok(())
    }

    /// Charge un journal depuis un fichier JSON et vérifie immédiatement son intégrité.
    pub fn load_and_verify<P: AsRef<Path>>(path: P) -> Result<Self, AuditLogError> {
        let file = File::open(path)?;
        let mut reader = BufReader::new(file);
        let mut content = String::new();
        reader.read_to_string(&mut content)?;

        let entries: Vec<AuditEntry> = serde_json::from_str(&content)?;
        let log = Self { entries };
        log.verify_chain()?;
        Ok(log)
    }

    /// Méthode d'utilité pour simuler une altération malveillante (à des fins de test / démonstration).
    pub fn tamper_entry_payload_for_test(&mut self, index: usize, forged_payload: &str) {
        if let Some(entry) = self.entries.get_mut(index) {
            entry.payload = forged_payload.to_string();
        }
    }
}

