#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Protocol {
    Tcp,
    Udp,
}

impl fmt::Display for Protocol {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Protocol::Tcp => write!(f, "TCP"),
            Protocol::Udp => write!(f, "UDP"),
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SocketInfo {
    pub protocol: Protocol,
    pub local_ip: IpAddr,
    pub local_port: u16,
    pub inode: u64,
    pub pid: Option<u32>,
    pub process_name: Option<String>,
}

impl SocketInfo {
    pub fn is_loopback(&self) -> bool {
        self.local_ip.is_loopback()
    }

    pub fn is_wildcard(&self) -> bool {
        self.local_ip.is_unspecified()
    }
}

// ============================================================================
// Procfs Parsers (Linux)
// ============================================================================

mod procfs {
    use super::*;

    fn parse_ipv4_hex(hex_str: &str) -> Result<Ipv4Addr, AuditError> {
        let val = u32::from_str_radix(hex_str, 16).map_err(|e| {
            AuditError::ProcNetParse(format!("IPv4 hex invalide '{hex_str}': {e}"))
        })?;
        let bytes = val.to_le_bytes();
        Ok(Ipv4Addr::new(bytes[0], bytes[1], bytes[2], bytes[3]))
    }

    fn parse_ipv6_hex(hex_str: &str) -> Result<Ipv6Addr, AuditError> {
        if hex_str.len() != 32 {
            return Err(AuditError::ProcNetParse(format!(
                "Taille hex IPv6 invalide (attendu 32, reçu {})",
                hex_str.len()
            )));
        }

        let mut octets = [0u8; 16];
        for i in 0..4 {
            let chunk = &hex_str[i * 8..(i + 1) * 8];
            let dword = u32::from_str_radix(chunk, 16).map_err(|e| {
                AuditError::ProcNetParse(format!("Bloc IPv6 hex invalide '{chunk}': {e}"))
            })?;
            let bytes = dword.to_le_bytes();
            let dest_offset = i * 4;
            octets[dest_offset..dest_offset + 4].copy_from_slice(&bytes);
        }

        Ok(Ipv6Addr::from(octets))
    }

    fn parse_address(addr_str: &str, is_ipv6: bool) -> Result<(IpAddr, u16), AuditError> {
        let parts: Vec<&str> = addr_str.split(':').collect();
        if parts.len() != 2 {
            return Err(AuditError::ProcNetParse(format!(
                "Format d'adresse réseau invalide '{addr_str}'"
            )));
        }

        let port = u16::from_str_radix(parts[1], 16).map_err(|e| {
            AuditError::ProcNetParse(format!("Port hex invalide '{}': {e}", parts[1]))
        })?;

        let ip: IpAddr = if is_ipv6 {
            IpAddr::V6(parse_ipv6_hex(parts[0])?)
        } else {
            IpAddr::V4(parse_ipv4_hex(parts[0])?)
        };

        Ok((ip, port))
    }

    pub fn build_inode_process_map() -> HashMap<u64, (u32, String)> {
        let mut map = HashMap::new();
        let proc_dir = match fs::read_dir("/proc") {
            Ok(entries) => entries,
            Err(_) => return map,
        };

        for entry in proc_dir.flatten() {
            let file_name = entry.file_name();
            let pid_str = file_name.to_string_lossy();
            let pid: u32 = match pid_str.parse() {
                Ok(p) => p,
                Err(_) => continue,
            };

            let proc_path = entry.path();
            let comm_path = proc_path.join("comm");
            let process_name = fs::read_to_string(comm_path)
                .map(|s| s.trim().to_string())
                .unwrap_or_else(|_| "inconnu".to_string());

            let fd_dir = proc_path.join("fd");
            let fd_entries = match fs::read_dir(fd_dir) {
                Ok(entries) => entries,
                Err(_) => continue,
            };

            for fd in fd_entries.flatten() {
                if let Ok(link_target) = fs::read_link(fd.path()) {
                    let target_str = link_target.to_string_lossy();
                    if target_str.starts_with("socket:[") && target_str.ends_with(']') {
                        let inner = &target_str[8..target_str.len() - 1];
                        if let Ok(inode) = inner.parse::<u64>() {
                            map.insert(inode, (pid, process_name.clone()));
                        }
                    }
                }
            }
        }

        map
    }

    pub fn parse_proc_net_file(
        path: &str,
        protocol: Protocol,
        is_ipv6: bool,
        inode_map: &HashMap<u64, (u32, String)>,
    ) -> Result<Vec<SocketInfo>, AuditError> {
        let content = match fs::read_to_string(path) {
            Ok(c) => c,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
            Err(e) => return Err(AuditError::Io(e)),
        };

        let mut sockets = Vec::new();

        for line in content.lines().skip(1) {
            let fields: Vec<&str> = line.split_whitespace().collect();
            if fields.len() < 10 {
                continue;
            }

            let local_addr_raw = fields[1];
            let state_raw = fields[3];
            let inode_raw = fields[9];

            // Pour TCP, state '0A' = TCP_LISTEN.
            // Pour UDP, tous les sockets alloués dans /proc/net/udp écoutent ou sont liés.
            let is_listening = match protocol {
                Protocol::Tcp => state_raw.eq_ignore_ascii_case("0A"),
                Protocol::Udp => true,
            };

            if !is_listening {
                continue;
            }

            let (local_ip, local_port) = match parse_address(local_addr_raw, is_ipv6) {
                Ok(res) => res,
                Err(_) => continue,
            };

            let inode = inode_raw.parse::<u64>().unwrap_or(0);
            let (pid, process_name) = match inode_map.get(&inode) {
                Some((p, name)) => (Some(*p), Some(name.clone())),
                None => (None, None),
            };

            sockets.push(SocketInfo {
                protocol,
                local_ip,
                local_port,
                inode,
                pid,
                process_name,
            });
        }

        Ok(sockets)
    }
}

// ============================================================================
// Umask Detection and Helpers
// ============================================================================

pub struct UmaskInspector;

impl UmaskInspector {
    pub fn get_current_umask() -> Result<u32, AuditError> {
        // Méthode 1 (non invasive) : lecture dans /proc/self/status
        if let Ok(content) = fs::read_to_string("/proc/self/status") {
            for line in content.lines() {
                if let Some(rest) = line.strip_prefix("Umask:") {
                    let cleaned = rest.trim();
                    if let Ok(val) = u32::from_str_radix(cleaned, 8) {
                        return Ok(val);
                    }
                }
            }
        }

        // Méthode 2 (repli POSIX via libc) : appel libc::umask() sécurisé avec restauration
        // L'appel modifie temporairement l'umask puis le rétablit immédiatement.
        unsafe {
            let current = libc::umask(0);
            libc::umask(current);
            Ok(current as u32)
        }
    }

    pub fn inspect_login_defs() -> Option<u32> {
        let path = Path::new("/etc/login.defs");
        let content = fs::read_to_string(path).ok()?;
        for line in content.lines() {
            let line = line.trim();
            if line.starts_with('#') || line.is_empty() {
                continue;
            }
            let tokens: Vec<&str> = line.split_whitespace().collect();
            if tokens.len() >= 2 && tokens[0].eq_ignore_ascii_case("UMASK") {
                if let Ok(val) = u32::from_str_radix(tokens[1], 8) {
                    return Some(val);
                }
            }
        }
        None
    }

    pub fn format_octal(mask: u32) -> String {
        format!("{:04o}", mask)
    }

    pub fn describe_rights(mask: u32) -> String {
        let r_u = if (mask & 0o400) == 0 { "r" } else { "-" };
        let w_u = if (mask & 0o200) == 0 { "w" } else { "-" };
        let x_u = if (mask & 0o100) == 0 { "x" } else { "-" };

        let r_g = if (mask & 0o040) == 0 { "r" } else { "-" };
        let w_g = if (mask & 0o020) == 0 { "w" } else { "-" };
        let x_g = if (mask & 0o010) == 0 { "x" } else { "-" };

        let r_o = if (mask & 0o004) == 0 { "r" } else { "-" };
        let w_o = if (mask & 0o002) == 0 { "w" } else { "-" };
        let x_o = if (mask & 0o001) == 0 { "x" } else { "-" };

        format!("{r_u}{w_u}{x_u}{r_g}{w_g}{x_g}{r_o}{w_o}{x_o}")
    }
}

