#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "UPPERCASE")]
pub enum Severity {
    Pass,
    Warn,
    Fail,
}

impl fmt::Display for Severity {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Severity::Pass => write!(f, "PASS"),
            Severity::Warn => write!(f, "WARN"),
            Severity::Fail => write!(f, "FAIL"),
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AuditFinding {
    pub category: String,
    pub title: String,
    pub severity: Severity,
    pub message: String,
    pub details: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AuditSummary {
    pub total: usize,
    pub passed: usize,
    pub warnings: usize,
    pub failed: usize,
    pub is_compliant: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AuditReport {
    pub policy_name: String,
    pub policy_version: String,
    pub current_umask: String,
    pub default_file_mode: String,
    pub findings: Vec<AuditFinding>,
    pub summary: AuditSummary,
}

pub struct AuditEngine<'a> {
    policy: &'a SecurityPolicy,
}

impl<'a> AuditEngine<'a> {
    pub fn new(policy: &'a SecurityPolicy) -> Self {
        Self { policy }
    }

    pub fn run(&self) -> Result<AuditReport, AuditError> {
        let mut findings = Vec::new();

        // 1. Audit Umask
        let current_umask = UmaskInspector::get_current_umask()?;
        let required_umask = u32::from_str_radix(&self.policy.umask.min_mask, 8)
            .map_err(|_| AuditError::InvalidUmask(self.policy.umask.min_mask.clone()))?;

        let umask_str = UmaskInspector::format_octal(current_umask);
        let rights_str = UmaskInspector::describe_rights(current_umask);

        // Conformité Umask : Les bits requis dans la politique doivent être masqués dans l'umask actuel
        let satisfies_bits = (current_umask & required_umask) == required_umask;

        if satisfies_bits {
            findings.push(AuditFinding {
                category: "Umask".to_string(),
                title: "Conformité du masque de création (umask)".to_string(),
                severity: Severity::Pass,
                message: format!(
                    "L'umask actuel ({umask_str}) respecte l'exigence minimale ({:04o}).",
                    required_umask
                ),
                details: Some(format!("Droits par défaut des créations : {rights_str}")),
            });
        } else {
            let missing_bits = required_umask & !current_umask;
            findings.push(AuditFinding {
                category: "Umask".to_string(),
                title: "Conformité du masque de création (umask)".to_string(),
                severity: Severity::Fail,
                message: format!(
                    "L'umask actuel ({umask_str}) est trop permissif par rapport à l'exigence ({:04o}).",
                    required_umask
                ),
                details: Some(format!(
                    "Bits non masqués : {:04o}. Droits actuels trop ouverts : {rights_str}",
                    missing_bits
                )),
            });
        }

        // Vérification /etc/login.defs
        if self.policy.umask.check_login_defs {
            match UmaskInspector::inspect_login_defs() {
                Some(login_umask) => {
                    let login_str = UmaskInspector::format_octal(login_umask);
                    if (login_umask & required_umask) == required_umask {
                        findings.push(AuditFinding {
                            category: "Umask".to_string(),
                            title: "Configuration /etc/login.defs".to_string(),
                            severity: Severity::Pass,
                            message: format!("UMASK dans /etc/login.defs ({login_str}) est conforme."),
                            details: None,
                        });
                    } else {
                        findings.push(AuditFinding {
                            category: "Umask".to_string(),
                            title: "Configuration /etc/login.defs".to_string(),
                            severity: Severity::Warn,
                            message: format!(
                                "UMASK par défaut dans /etc/login.defs ({login_str}) est plus permissif que l'exigence ({:04o}).",
                                required_umask
                            ),
                            details: Some("Modifier la variable UMASK dans /etc/login.defs.".to_string()),
                        });
                    }
                }
                None => {
                    findings.push(AuditFinding {
                        category: "Umask".to_string(),
                        title: "Configuration /etc/login.defs".to_string(),
                        severity: Severity::Pass,
                        message: "Fichier /etc/login.defs absent ou sans directive UMASK explicite.".to_string(),
                        details: None,
                    });
                }
            }
        }

        // 2. Audit des ports réseau en écoute
        let inode_map = procfs::build_inode_process_map();
        let mut listening_sockets = Vec::new();

        listening_sockets.extend(procfs::parse_proc_net_file("/proc/net/tcp", Protocol::Tcp, false, &inode_map)?);
        listening_sockets.extend(procfs::parse_proc_net_file("/proc/net/tcp6", Protocol::Tcp, true, &inode_map)?);
        listening_sockets.extend(procfs::parse_proc_net_file("/proc/net/udp", Protocol::Udp, false, &inode_map)?);
        listening_sockets.extend(procfs::parse_proc_net_file("/proc/net/udp6", Protocol::Udp, true, &inode_map)?);

        // Dédoublonnage éventuel (ex: double écoute tcp / tcp6 selon socket options)
        for sock in &listening_sockets {
            let proc_desc = match (&sock.pid, &sock.process_name) {
                (Some(pid), Some(name)) => format!(" (PID {pid}, {name})"),
                _ => String::new(),
            };

            // Règle 1 : Est-ce un port interdit ?
            let forbidden_match = self.policy.ports.forbidden.iter().find(|rule| {
                rule.port == sock.local_port && rule.protocol.map_or(true, |proto| proto == sock.protocol)
            });

            if let Some(rule) = forbidden_match {
                findings.push(AuditFinding {
                    category: "Ports".to_string(),
                    title: format!("Port interdit détecté : {}/{} {proc_desc}", sock.local_port, sock.protocol),
                    severity: Severity::Fail,
                    message: format!(
                        "Le port {}/{} est ouvert sur {} alors qu'il est formellement interdit : {}",
                        sock.local_port, sock.protocol, sock.local_ip, rule.reason
                    ),
                    details: Some(format!("Adresse d'écoute : {}:{}", sock.local_ip, sock.local_port)),
                });
                continue;
            }

            // Règle 2 : Est-ce dans la liste blanche ?
            let allowed_match = self.policy.ports.allowed.iter().find(|rule| {
                rule.port == sock.local_port && rule.protocol == sock.protocol
            });

            if let Some(rule) = allowed_match {
                if !rule.allow_public && !sock.is_loopback() {
                    findings.push(AuditFinding {
                        category: "Ports".to_string(),
                        title: format!("Port restreint exposé publiquement : {}/{} {proc_desc}", sock.local_port, sock.protocol),
                        severity: Severity::Fail,
                        message: format!(
                            "Le port {}/{} est autorisé uniquement en local mais écoute sur une interface externe : {}",
                            sock.local_port, sock.protocol, sock.local_ip
                        ),
                        details: rule.description.clone(),
                    });
                } else {
                    findings.push(AuditFinding {
                        category: "Ports".to_string(),
                        title: format!("Port autorisé : {}/{} {proc_desc}", sock.local_port, sock.protocol),
                        severity: Severity::Pass,
                        message: format!(
                            "Le port {}/{} sur {} est conforme à la liste blanche.",
                            sock.local_port, sock.protocol, sock.local_ip
                        ),
                        details: rule.description.clone(),
                    });
                }
                continue;
            }

            // Règle 3 : Port non répertorié
            if sock.is_loopback() && self.policy.ports.allow_localhost_by_default {
                findings.push(AuditFinding {
                    category: "Ports".to_string(),
                    title: format!("Port local non répertorié : {}/{} {proc_desc}", sock.local_port, sock.protocol),
                    severity: Severity::Pass,
                    message: format!(
                        "Le port {}/{} écoute sur l'interface de bouclage ({}) (autorisé par défaut).",
                        sock.local_port, sock.protocol, sock.local_ip
                    ),
                    details: None,
                });
            } else if self.policy.ports.allow_unknown_ports {
                findings.push(AuditFinding {
                    category: "Ports".to_string(),
                    title: format!("Port non répertorié en écoute : {}/{} {proc_desc}", sock.local_port, sock.protocol),
                    severity: Severity::Warn,
                    message: format!(
                        "Le port {}/{} écoute sur {} sans être listé dans la politique.",
                        sock.local_port, sock.protocol, sock.local_ip
                    ),
                    details: Some("Toléré par la directive allow_unknown_ports.".to_string()),
                });
            } else {
                findings.push(AuditFinding {
                    category: "Ports".to_string(),
                    title: format!("Port non autorisé détecté : {}/{} {proc_desc}", sock.local_port, sock.protocol),
                    severity: Severity::Fail,
                    message: format!(
                        "Le port {}/{} écoute sur {} mais n'est pas autorisé par la politique.",
                        sock.local_port, sock.protocol, sock.local_ip
                    ),
                    details: Some("Ajoutez ce port à la liste blanche ou fermez le service associé.".to_string()),
                });
            }
        }

        // Synthèse
        let mut passed = 0;
        let mut warnings = 0;
        let mut failed = 0;

        for f in &findings {
            match f.severity {
                Severity::Pass => passed += 1,
                Severity::Warn => warnings += 1,
                Severity::Fail => failed += 1,
            }
        }

        let total = findings.len();
        let is_compliant = failed == 0;

        Ok(AuditReport {
            policy_name: self.policy.meta.name.clone(),
            policy_version: self.policy.meta.version.clone(),
            current_umask: umask_str,
            default_file_mode: rights_str,
            findings,
            summary: AuditSummary {
                total,
                passed,
                warnings,
                failed,
                is_compliant,
            },
        })
    }
}

// ============================================================================
// CLI Formatting & Presentation
// ============================================================================

pub struct ReportPrinter;

impl ReportPrinter {
    pub fn print_terminal(report: &AuditReport) {
        println!("{}", "════════════════════════════════════════════════════════════════════".cyan().bold());
        println!(
            " {} : {} (v{})",
            "RAPPORT D'AUDIT DE SÉCURITÉ SYSTÈME".bold(),
            report.policy_name.yellow(),
            report.policy_version
        );
        println!(
            " Umask Actuel : {} | Droits résultants : {}",
            report.current_umask.green().bold(),
            report.default_file_mode.cyan()
        );
        println!("{}", "════════════════════════════════════════════════════════════════════".cyan().bold());
        println!();

        for finding in &report.findings {
            let badge = match finding.severity {
                Severity::Pass => "[ PASS ]".green().bold(),
                Severity::Warn => "[ WARN ]".yellow().bold(),
                Severity::Fail => "[ FAIL ]".red().bold(),
            };

            println!("{badge} [{}] {}", finding.category.bold(), finding.title);
            println!("         {}", finding.message);
            if let Some(details) = &finding.details {
                println!("         -> {}", details.dimmed());
            }
            println!();
        }

        println!("{}", "────────────────────────────────────────────────────────────────────".cyan());
        println!(" {} :", "SYNTHÈSE DE CONFORMITÉ".bold());
        println!(
            " Total vérifications : {} | Succès : {} | Avertissements : {} | Échecs : {}",
            report.summary.total,
            report.summary.passed.to_string().green().bold(),
            report.summary.warnings.to_string().yellow().bold(),
            report.summary.failed.to_string().red().bold()
        );

        if report.summary.is_compliant {
            println!(
                "\n Résultat : {}",
                "SYSTÈME CONFORME À LA POLITIQUE DE SÉCURITÉ".green().bold()
            );
        } else {
            println!(
                "\n Résultat : {}",
                "NON-CONFORMITÉS DÉTECTÉES SUR LE SYSTÈME".red().bold()
            );
        }
        println!("{}", "════════════════════════════════════════════════════════════════════".cyan().bold());
    }

    pub fn print_json(report: &AuditReport) -> Result<(), AuditError> {
        let json = serde_json::to_string_pretty(report)?;
        println!("{json}");
        Ok(())
    }
}

// ============================================================================
// Command Line Interface (Clap)
// ============================================================================

#[derive(Parser)]
#[command(
    name = "sec-audit",
    author = "Security Engineering Team",
    version = "0.1.0",
    about = "Validation automatisée de politiques de sécurité système (umask, ports d'écoute)"
)]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,

    #[command(flatten)]
    audit_opts: AuditArgs,
}

#[derive(Subcommand)]
enum Commands {
    /// Exécute l'audit complet du système selon la politique (par défaut)
    Audit(AuditArgs),
    /// Inspecte l'état actuel (umask, ports ouverts) sans validation de politique
    Inspect,
    /// Génère un fichier modèle de politique de sécurité TOML
    GeneratePolicy {
        /// Chemin où sauvegarder le fichier modèle (affiche sur stdout si omis)
        #[arg(short, long)]
        output: Option<PathBuf>,
    },
}

#[derive(Args, Clone)]
struct AuditArgs {
    /// Chemin du fichier de politique de sécurité TOML
    #[arg(short, long)]
    config: Option<PathBuf>,

    /// Format de restitution des résultats
    #[arg(short, long, value_enum, default_value_t = OutputFormat::Text)]
    format: OutputFormat,

    /// Échouer immédiatement (code retour 1) si au moins une non-conformité ou avertissement survient
    #[arg(long)]
    strict: bool,

    /// Surcharge temporaire de l'umask minimal requis (ex: 0027)
    #[arg(long)]
    min_umask: Option<String>,
}

#[derive(Copy, Clone, PartialEq, Eq, PartialOrd, Ord, ValueEnum)]
enum OutputFormat {
    Text,
    Json,
}

// ============================================================================
// Main Entrypoint
// ============================================================================

fn main() -> ExitCode {
    let cli = Cli::parse();

    match cli.command {
        Some(Commands::Audit(args)) => execute_audit(args),
        Some(Commands::Inspect) => execute_inspect(),
        Some(Commands::GeneratePolicy { output }) => execute_generate_policy(output),
        None => execute_audit(cli.audit_opts),
    }
}

fn execute_audit(args: AuditArgs) -> ExitCode {
    let mut policy = match args.config {
        Some(path) => match fs::read_to_string(&path) {
            Ok(content) => match toml::from_str::<SecurityPolicy>(&content) {
                Ok(pol) => pol,
                Err(err) => {
                    eprintln!("{} Erreur de syntaxe dans la politique {}: {err}", "ERREUR:".red().bold(), path.display());
                    return ExitCode::from(2);
                }
            },
            Err(err) => {
                eprintln!("{} Impossible de lire {}: {err}", "ERREUR:".red().bold(), path.display());
                return ExitCode::from(2);
            }
        },
        None => SecurityPolicy::default(),
    };

    if let Some(override_umask) = args.min_umask {
        policy.umask.min_mask = override_umask;
    }

    let engine = AuditEngine::new(&policy);
    let report = match engine.run() {
        Ok(r) => r,
        Err(err) => {
            eprintln!("{} Échec lors de l'exécution de l'audit: {err}", "ERREUR:".red().bold());
            return ExitCode::from(2);
        }
    };

    match args.format {
        OutputFormat::Text => ReportPrinter::print_terminal(&report),
        OutputFormat::Json => {
            if let Err(err) = ReportPrinter::print_json(&report) {
                eprintln!("{} Échec du formatage JSON: {err}", "ERREUR:".red().bold());
                return ExitCode::from(2);
            }
        }
    }

    if args.strict {
        if report.summary.failed > 0 || report.summary.warnings > 0 {
            return ExitCode::from(1);
        }
    } else if report.summary.failed > 0 {
        return ExitCode::from(1);
    }

    ExitCode::SUCCESS
}

fn execute_inspect() -> ExitCode {
    println!("{}", "=== INSPECTION DE SÉCURITÉ SYSTÈME LOCALE ===".cyan().bold());

    // 1. Umask
    match UmaskInspector::get_current_umask() {
        Ok(mask) => {
            let octal = UmaskInspector::format_octal(mask);
            let rights = UmaskInspector::describe_rights(mask);
            println!("  [Umask Processus] : {} (Droits autorisés : {})", octal.green().bold(), rights.cyan());
        }
        Err(err) => {
            println!("  [Umask Processus] : {} ({err})", "ERREUR".red().bold());
        }
    }

    if let Some(defs_mask) = UmaskInspector::inspect_login_defs() {
        let octal = UmaskInspector::format_octal(defs_mask);
        println!("  [/etc/login.defs] : UMASK {}", octal.yellow());
    }

    // 2. Ports en écoute
    println!("\n=== SOCKETS RÉSEAU LOCAUX EN ÉCOUTE ===");
    let inode_map = procfs::build_inode_process_map();
    let mut sockets = Vec::new();

    let _ = procfs::parse_proc_net_file("/proc/net/tcp", Protocol::Tcp, false, &inode_map).map(|s| sockets.extend(s));
    let _ = procfs::parse_proc_net_file("/proc/net/tcp6", Protocol::Tcp, true, &inode_map).map(|s| sockets.extend(s));
    let _ = procfs::parse_proc_net_file("/proc/net/udp", Protocol::Udp, false, &inode_map).map(|s| sockets.extend(s));
    let _ = procfs::parse_proc_net_file("/proc/net/udp6", Protocol::Udp, true, &inode_map).map(|s| sockets.extend(s));

    if sockets.is_empty() {
        println!("  Aucun socket en écoute détecté.");
    } else {
        println!(
            "  {:<6} {:<38} {:<10} {:<10} {}",
            "PROTO".bold(),
            "ADRESSE LOCALE".bold(),
            "PORT".bold(),
            "PID".bold(),
            "PROCESSUS".bold()
        );
        for s in sockets {
            let pid_str = s.pid.map(|p| p.to_string()).unwrap_or_else(|| "-".to_string());
            let name_str = s.process_name.unwrap_or_else(|| "-".to_string());
            let addr_str = format!("{}", s.local_ip);
            println!(
                "  {:<6} {:<38} {:<10} {:<10} {}",
                s.protocol.to_string().cyan(),
                addr_str,
                s.local_port.to_string().yellow().bold(),
                pid_str,
                name_str
            );
        }
    }

    ExitCode::SUCCESS
}

fn execute_generate_policy(output: Option<PathBuf>) -> ExitCode {
    let sample = toml::to_string_pretty(&SecurityPolicy::default())
        .expect("La politique par défaut doit être sérialisable en TOML");

    let header = "# ====================================================================\n\
                  # POLITIQUE DE SÉCURITÉ SYSTÈME POUR SEC-AUDIT\n\
                  # ====================================================================\n\n";
    let full_content = format!("{header}{sample}");

    match output {
        Some(path) => match fs::write(&path, full_content) {
            Ok(_) => {
                println!("{} Modèle de politique généré avec succès dans {}", "OK:".green().bold(), path.display());
                ExitCode::SUCCESS
            }
            Err(err) => {
                eprintln!("{} Impossible d'écrire dans {}: {err}", "ERREUR:".red().bold(), path.display());
                ExitCode::from(2)
            }
        },
        None => {
            println!("{full_content}");
            ExitCode::SUCCESS
        }
    }
}

