#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PolicyMeta {
    pub name: String,
    pub version: String,
    #[serde(default)]
    pub description: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UmaskPolicy {
    /// Masque octal minimal requis (ex: "0027")
    pub min_mask: String,
    /// Si true, les bits spécifiés doivent impérativement être masqués
    #[serde(default = "default_true")]
    pub enforce_all_bits: bool,
    /// Vérifier également le fichier /etc/login.defs si accessible
    #[serde(default = "default_true")]
    pub check_login_defs: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AllowedPortRule {
    pub port: u16,
    pub protocol: Protocol,
    #[serde(default)]
    pub description: Option<String>,
    #[serde(default = "default_false")]
    pub allow_public: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ForbiddenPortRule {
    pub port: u16,
    pub protocol: Option<Protocol>,
    pub reason: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PortsPolicy {
    /// Tolérer implicitement les ports écoutant uniquement sur l'interface locale (127.0.0.1 ou ::1)
    #[serde(default = "default_true")]
    pub allow_localhost_by_default: bool,
    /// Autoriser ou rejeter les ports inconnus
    #[serde(default = "default_false")]
    pub allow_unknown_ports: bool,
    /// Liste blanche
    #[serde(default)]
    pub allowed: Vec<AllowedPortRule>,
    /// Liste noire
    #[serde(default)]
    pub forbidden: Vec<ForbiddenPortRule>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SecurityPolicy {
    pub meta: PolicyMeta,
    pub umask: UmaskPolicy,
    pub ports: PortsPolicy,
}

fn default_true() -> bool {
    true
}

fn default_false() -> bool {
