use anyhow::{Context, Result};
use clap::{Args, Parser, Subcommand};
use rcgen::{
    BasicConstraints, CertificateParams, DistinguishedName, DnType, Ia5String, IsCa, KeyPair,
    KeyUsagePurpose, SanType,
};
use time::{Duration, OffsetDateTime};

#[derive(Parser, Debug)]
#[command(
    name = "local-cert-gen",
    version,
    about = "Générateur de certificats auto-signés simplifiés pour tests d'infrastructures locales"
)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Générer une Autorité de Certification (CA) racine locale
    Ca(CaArgs),
    /// Générer un certificat serveur/client auto-signé ou signé par une CA
    Server(ServerArgs),
}

#[derive(Args, Debug)]
struct CaArgs {
    /// Nom commun (Common Name) de l'autorité racine
    #[arg(short, long, default_value = "Local Development Root CA")]
    common_name: String,

    /// Organisation
    #[arg(long, default_value = "Local Dev Org")]
    organization: String,

    /// Durée de validité en jours
    #[arg(short, long, default_value_t = 3650)]
    days: i64,

    /// Répertoire de sortie pour les fichiers générés
    #[arg(short, long, default_value = "./certs")]
    output_dir: PathBuf,

    /// Préfixe du nom des fichiers générés (`prefix.crt` et `prefix.key`)
    #[arg(short, long, default_value = "ca")]
    prefix: String,
}

#[derive(Args, Debug)]
struct ServerArgs {
    /// Nom commun (Common Name / nom principal de domaine)
    #[arg(short, long, default_value = "localhost")]
    common_name: String,

    /// Noms alternatifs du sujet (SAN : DNS ou IP, ex: localhost, 127.0.0.1, api.local)
    #[arg(short, long, value_delimiter = ',', default_values_t = vec!["localhost".to_string(), "127.0.0.1".to_string(), "::1".to_string()])]
    sans: Vec<String>,

    /// Durée de validité en jours
    #[arg(short, long, default_value_t = 365)]
    days: i64,

    /// Répertoire de sortie pour les fichiers générés
    #[arg(short, long, default_value = "./certs")]
    output_dir: PathBuf,

    /// Préfixe du nom des fichiers générés (`prefix.crt` et `prefix.key`)
    #[arg(short, long, default_value = "server")]
    prefix: String,

    /// Chemin optionnel vers le certificat de l'autorité CA pour signer ce certificat
    #[arg(long)]
    ca_cert: Option<PathBuf>,

    /// Chemin optionnel vers la clé privée de l'autorité CA pour signer ce certificat
    #[arg(long)]
    ca_key: Option<PathBuf>,
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Ca(args) => generate_ca(&args),
        Commands::Server(args) => generate_server(&args),
    }
}

fn write_secure_file(path: &Path, content: &[u8], is_private_key: bool) -> Result<()> {
    let mut options = OpenOptions::new();
    options.write(true).create(true).truncate(true);

    #[cfg(unix)]
    if is_private_key {
        options.mode(0o600);
    }

    let mut file = options
        .open(path)
        .with_context(|| format!("Impossible d'ouvrir/créer le fichier : {}", path.display()))?;

    file.write_all(content)
        .with_context(|| format!("Échec d'écriture dans : {}", path.display()))?;

    Ok(())
}

fn generate_ca(args: &CaArgs) -> Result<()> {
    fs::create_dir_all(&args.output_dir).with_context(|| {
        format!(
            "Impossible de créer le dossier de sortie : {}",
            args.output_dir.display()
        )
    })?;

    let mut params = CertificateParams::default();

    let mut dn = DistinguishedName::new();
    dn.push(DnType::CommonName, &args.common_name);
    dn.push(DnType::OrganizationName, &args.organization);
    params.distinguished_name = dn;

    params.is_ca = IsCa::Ca(BasicConstraints::Unconstrained);
    params.key_usages = vec![KeyUsagePurpose::KeyCertSign, KeyUsagePurpose::CrlSign];

    let now = OffsetDateTime::now_utc();
    params.not_before = now;
    params.not_after = now + Duration::days(args.days);

    let keypair = KeyPair::generate().context("Échec de la génération de la paire de clés CA")?;
    let cert = params
        .self_signed(&keypair)
        .context("Échec de la génération du certificat CA auto-signé")?;

    let cert_pem = cert.pem();
    let key_pem = keypair.serialize_pem();

    let cert_path = args.output_dir.join(format!("{}.crt", args.prefix));
    let key_path = args.output_dir.join(format!("{}.key", args.prefix));

    write_secure_file(&cert_path, cert_pem.as_bytes(), false)?;
    write_secure_file(&key_path, key_pem.as_bytes(), true)?;

    println!("✓ Autorité de certification (CA) générée avec succès !");
    println!("  Certificat CA : {}", cert_path.display());
    println!("  Clé privée CA : {}", key_path.display());
    println!("  Validité      : {} jours", args.days);

    Ok(())
}

fn generate_server(args: &ServerArgs) -> Result<()> {
    fs::create_dir_all(&args.output_dir).with_context(|| {
        format!(
            "Impossible de créer le dossier de sortie : {}",
            args.output_dir.display()
        )
    })?;

    let mut params = CertificateParams::default();

    let mut dn = DistinguishedName::new();
    dn.push(DnType::CommonName, &args.common_name);
    params.distinguished_name = dn;

    for san in &args.sans {
        let trimmed = san.trim();
        if trimmed.is_empty() {
            continue;
        }

        if let Ok(ip) = IpAddr::from_str(trimmed) {
            params.subject_alt_names.push(SanType::IpAddress(ip));
        } else {
            let ia5 = Ia5String::try_from(trimmed)
                .map_err(|e| anyhow::anyhow!("Nom de domaine SAN invalide '{trimmed}': {e}"))?;
            params.subject_alt_names.push(SanType::DnsName(ia5));
        }
    }

    params.is_ca = IsCa::NoCa;
    params.key_usages = vec![
        KeyUsagePurpose::DigitalSignature,
        KeyUsagePurpose::KeyEncipherment,
    ];

    let now = OffsetDateTime::now_utc();
    params.not_before = now;
    params.not_after = now + Duration::days(args.days);

    let keypair =
        KeyPair::generate().context("Échec de la génération de la paire de clés serveur")?;

    let cert_path = args.output_dir.join(format!("{}.crt", args.prefix));
    let key_path = args.output_dir.join(format!("{}.key", args.prefix));

    let cert_pem = match (&args.ca_cert, &args.ca_key) {
        (Some(ca_cert_path), Some(ca_key_path)) => {
            let ca_cert_content = fs::read_to_string(ca_cert_path).with_context(|| {
                format!(
                    "Impossible de lire le certificat CA : {}",
                    ca_cert_path.display()
                )
            })?;
            let ca_key_content = fs::read_to_string(ca_key_path).with_context(|| {
                format!("Impossible de lire la clé CA : {}", ca_key_path.display())
            })?;

            let ca_keypair = KeyPair::from_pem(&ca_key_content)
                .context("Impossible de parser la clé privée CA")?;
            let ca_params = CertificateParams::from_ca_cert_pem(&ca_cert_content)
                .context("Impossible de parser le certificat CA")?;
            let ca_cert = ca_params
                .self_signed(&ca_keypair)
                .context("Impossible de recharger la CA")?;

            let signed_cert = params
                .signed_by(&keypair, &ca_cert, &ca_keypair)
                .context("Échec de la signature du certificat par la CA")?;

            signed_cert.pem()
        }
        (None, None) => {
            let self_signed = params
                .self_signed(&keypair)
                .context("Échec de la génération du certificat auto-signé")?;
            self_signed.pem()
        }
        _ => {
            anyhow::bail!(
                "Pour signer avec une CA, les deux arguments --ca-cert et --ca-key doivent être fournis ensemble."
            );
        }
    };

    let key_pem = keypair.serialize_pem();

    write_secure_file(&cert_path, cert_pem.as_bytes(), false)?;
    write_secure_file(&key_path, key_pem.as_bytes(), true)?;

    let mode_str = if args.ca_cert.is_some() {
        "Signé par CA"
    } else {
        "Auto-signé"
    };

    println!("✓ Certificat serveur généré avec succès ({}) !", mode_str);
    println!("  Certificat : {}", cert_path.display());
    println!("  Clé privée : {}", key_path.display());
    println!("  SANs       : {:?}", args.sans);
    println!("  Validité   : {} jours", args.days);

    Ok(())
}

