```rust
// src/main.rs
use anyhow::{Context, Result};
use clap::{Parser, Subcommand, ValueEnum};
use colored::*;
use indicatif::{ProgressBar, ProgressStyle};
use md5::Md5;
use sha1::Sha1;
use sha2::{Digest, Sha256};
use std::fs::File;
use std::io::{BufRead, BufReader, Read};
use std::path::{Path, PathBuf};

/// Algorithmes de hachage supportés
#[derive(Copy, Clone, PartialEq, Eq, PartialOrd, Ord, ValueEnum, Debug)]
pub enum HashAlgorithm {
    Md5,
    Sha1,
    Sha256,
    Blake3,
}

impl HashAlgorithm {
    pub fn name(&self) -> &'static str {
        match self {
            HashAlgorithm::Md5 => "MD5",
            HashAlgorithm::Sha1 => "SHA1",
            HashAlgorithm::Sha256 => "SHA256",
            HashAlgorithm::Blake3 => "BLAKE3",
        }
    }
}

/// Structure contenant le résultat du calcul des empreintes d'un fichier
#[derive(Debug, Default, Clone)]
pub struct FileChecksums {
    pub md5: Option<String>,
    pub sha1: Option<String>,
    pub sha256: Option<String>,
    pub blake3: Option<String>,
}

impl FileChecksums {
    pub fn get(&self, algo: HashAlgorithm) -> Option<&str> {
        match algo {
            HashAlgorithm::Md5 => self.md5.as_deref(),
            HashAlgorithm::Sha1 => self.sha1.as_deref(),
            HashAlgorithm::Sha256 => self.sha256.as_deref(),
            HashAlgorithm::Blake3 => self.blake3.as_deref(),
        }
    }
}

/// CLI d'inspection et validation simultanée de sommes de contrôle multiples
#[derive(Parser, Debug)]
#[command(name = "multicheck", author, version, about, long_about = None)]
pub struct Cli {
    #[command(subcommand)]
    pub command: Commands,
}

#[derive(Subcommand, Debug)]
pub enum Commands {
    /// Calcule simultanément les sommes de contrôle pour un ou plusieurs fichiers
    Inspect {
        /// Fichiers cibles à analyser
        #[arg(required = true)]
        files: Vec<PathBuf>,

        /// Filtrer sur des algorithmes spécifiques (par défaut tous: md5, sha1, sha256, blake3)
        #[arg(short, long, value_enum)]
        algo: Vec<HashAlgorithm>,

        /// Mode silencieux (affiche uniquement les hachages bruts)
        #[arg(short, long)]
        quiet: bool,
    },

    /// Valide un fichier contre une empreinte attendue ou un fichier de vérification
    Check {
        /// Fichier à vérifier
        #[arg(required = true)]
        file: PathBuf,

        /// Empreinte attendue (la détection d'algorithme est automatique ou guidée par --algo)
        #[arg(short = 'e', long)]
        expected: Option<String>,

        /// Fichier de checksums au format standard (ex: `<hash>  <fichier>`)
        #[arg(short = 'c', long)]
        checksum_file: Option<PathBuf>,

        /// Algorithme forcé pour l'empreinte fournie
        #[arg(short, long, value_enum)]
        algo: Option<HashAlgorithm>,
    },
}

/// Moteur de hachage simultané en une seule passe de lecture
pub fn compute_checksums<P: AsRef<Path>>(
    path: P,
    algorithms: &[HashAlgorithm],
    show_progress: bool,
) -> Result<FileChecksums> {
    let path = path.as_ref();
    let file = File::open(path)
        .with_context(|| format!("Impossible d'ouvrir le fichier '{}'", path.display()))?;

    let file_len = file.metadata().map(|m| m.len()).unwrap_or(0);
    let mut reader = BufReader::with_capacity(128 * 1024, file);

    let want_md5 = algorithms.is_empty() || algorithms.contains(&HashAlgorithm::Md5);
    let want_sha1 = algorithms.is_empty() || algorithms.contains(&HashAlgorithm::Sha1);
    let want_sha256 = algorithms.is_empty() || algorithms.contains(&HashAlgorithm::Sha256);
    let want_blake3 = algorithms.is_empty() || algorithms.contains(&HashAlgorithm::Blake3);

    let mut md5_hasher = if want_md5 { Some(Md5::new()) } else { None };
    let mut sha1_hasher = if want_sha1 { Some(Sha1::new()) } else { None };
    let mut sha256_hasher = if want_sha256 { Some(Sha256::new()) } else { None };
    let mut blake3_hasher = if want_blake3 { Some(blake3::Hasher::new()) } else { None };

    let pb = if show_progress && file_len > 10 * 1024 * 1024 {
        let bar = ProgressBar::new(file_len);
        bar.set_style(
            ProgressStyle::default_bar()
                .template("[{elapsed_precise}] [{bar:40.cyan/blue}] {bytes}/{total_bytes} ({eta})")
                .unwrap_or_else(|_| ProgressStyle::default_bar())
                .progress_chars("#>-"),
        );
        Some(bar)
    } else {
        None
    };

    let mut buffer = [0u8; 64 * 1024];
    loop {
        let n = reader
            .read(&mut buffer)
            .with_context(|| format!("Erreur lors de la lecture de '{}'", path.display()))?;
        if n == 0 {
            break;
        }

        let chunk = &buffer[..n];
        if let Some(ref mut h) = md5_hasher {
            h.update(chunk);
        }
        if let Some(ref mut h) = sha1_hasher {
            h.update(chunk);
        }
        if let Some(ref mut h) = sha256_hasher {
            h.update(chunk);
        }
        if let Some(ref mut h) = blake3_hasher {
            h.update(chunk);
        }

        if let Some(ref bar) = pb {
            bar.inc(n as u64);
        }
    }

    if let Some(bar) = pb {
        bar.finish_and_clear();
    }

    Ok(FileChecksums {
        md5: md5_hasher.map(|h| hex::encode(h.finalize())),
        sha1: sha1_hasher.map(|h| hex::encode(h.finalize())),
        sha256: sha256_hasher.map(|h| hex::encode(h.finalize())),
        blake3: blake3_hasher.map(|h| h.finalize().to_hex().to_string()),
    })
