        for line_res in reader.lines() {
            let line = line_res?;
            let trimmed = line.trim();
            if trimmed.is_empty() || trimmed.starts_with('#') {
                continue;
            }
            let parts: Vec<&str> = trimmed.split_whitespace().collect();
            if parts.len() >= 2 {
                let candidate_path = parts[1].trim_start_matches('*');
                if candidate_path == file_name || candidate_path == file.to_string_lossy() {
                    let hash = parts[0].to_lowercase();
                    let algo = forced_algo
                        .or_else(|| infer_algorithm_from_hex_len(&hash))
                        .with_context(|| "Impossible de déterminer l'algorithme du hachage lu.")?;
                    found = Some((hash, algo));
                    break;
                }
            }
        }

        found.with_context(|| {
            format!(
                "Aucune entrée pour '{}' trouvée dans '{}'",
                file_name,
                cs_path.display()
            )
        })?
    } else {
