    println!("  Attendu : {}", target_hash);
    println!("  Calculé : {}", actual_hash);

    if actual_hash.eq_ignore_ascii_case(&target_hash) {
        println!("{}", "✔ Somme de contrôle VALIDE".green().bold());
        Ok(())
    } else {
        eprintln!("{}", "✖ ÉCHEC : Les sommes de contrôle ne correspondent pas !".red().bold());
        std::process::exit(1);
    }
}

fn main() -> Result<()> {
    let cli = Cli::parse();

