```rust
// src/main.rs
use anyhow::{Context, Result};
use clap::{Parser, ValueEnum};
use colored::Colorize;
use ignore::WalkBuilder;
use regex::Regex;
use serde::Serialize;
use std::collections::HashMap;
use std::fs;
use std::io::Read;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

/// Formats d'affichage disponibles pour le rapport
#[derive(Debug, Clone, Copy, ValueEnum)]
enum OutputFormat {
    Text,
    Json,
}

/// Niveaux de sévérité pour les alertes
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize)]
#[serde(rename_all = "UPPERCASE")]
#[allow(dead_code)]
enum Severity {
    Info,
    Warning,
    Critical,
}

/// Description d'un secret détecté
#[derive(Debug, Clone, Serialize)]
struct SecretFinding {
    pub rule_name: String,
    pub file_path: String,
    pub line_number: usize,
    pub column: usize,
    pub masked_value: String,
    pub entropy: f64,
    pub severity: Severity,
}

/// Résultat d'analyse de licence pour un fichier ou le projet
#[derive(Debug, Clone, Serialize)]
struct LicenseFinding {
    pub file_path: String,
    pub detected_license: String,
    pub is_allowed: bool,
    pub details: String,
}

/// Rapport complet généré par le scanner
#[derive(Debug, Default, Serialize)]
struct ScanReport {
    pub files_scanned: usize,
    pub secrets_found: usize,
    pub license_violations: usize,
    pub project_licenses: Vec<String>,
    pub secret_findings: Vec<SecretFinding>,
    pub license_findings: Vec<LicenseFinding>,
}

/// Règle de détection de secret par expression régulière
struct SecretRule {
    pub name: &'static str,
    pub pattern: Regex,
    pub severity: Severity,
    pub min_entropy: Option<f64>,
}

/// Configuration et exécution du scanner
struct Scanner {
    secret_rules: Vec<SecretRule>,
    spdx_regex: Regex,
    allowed_licenses: Vec<String>,
    denied_licenses: Vec<String>,
    min_entropy_threshold: f64,
    require_license: bool,
}

impl Scanner {
    pub fn new(
        allowed_licenses: Vec<String>,
        denied_licenses: Vec<String>,
        min_entropy_threshold: f64,
        require_license: bool,
    ) -> Result<Self> {
        let secret_rules = vec![
            SecretRule {
                name: "Clé AWS Access Key ID",
                pattern: Regex::new(r"\b(AKIA|ABIA|ACCA|ASIA)[0-9A-Z]{16}\b")
                    .context("Échec de compilation du pattern AWS")?,
                severity: Severity::Critical,
                min_entropy: None,
            },
            SecretRule {
                name: "Token GitHub Personnel",
                pattern: Regex::new(r"\b(ghp|gho|ghu|ghs|ghr)_[A-Za-z0-9_]{36,255}\b")
                    .context("Échec de compilation du pattern GitHub")?,
                severity: Severity::Critical,
                min_entropy: None,
            },
            SecretRule {
                name: "Token Slack",
                pattern: Regex::new(r"\bxox[baprs]-[0-9a-zA-Z]{10,48}\b")
                    .context("Échec de compilation du pattern Slack")?,
                severity: Severity::Critical,
                min_entropy: None,
            },
            SecretRule {
                name: "Clé Privée RSA / SSH / Cryptographique",
                pattern: Regex::new(r"-----BEGIN (?:[A-Z0-9_-]+ )?PRIVATE KEY-----")
                    .context("Échec de compilation du pattern Private Key")?,
                severity: Severity::Critical,
                min_entropy: None,
            },
            SecretRule {
                name: "Token JWT (JSON Web Token)",
                pattern: Regex::new(r"\beyJ[A-Za-z0-9_-]{10,}\.eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\b")
                    .context("Échec de compilation du pattern JWT")?,
                severity: Severity::Warning,
                min_entropy: Some(3.5),
            },
            SecretRule {
                name: "Affectation suspecte de Secret/API Key",
                pattern: Regex::new(r#"(?i)(?:api_key|apikey|secret|token|password|passwd|auth_token)\s*[:=]\s*["']([A-Za-z0-9_\-+/=]{16,})["']"#)
                    .context("Échec de compilation du pattern affectation générique")?,
                severity: Severity::Critical,
                min_entropy: Some(3.0),
            },
        ];

        let spdx_regex = Regex::new(r"(?i)SPDX-License-Identifier:\s*([A-Za-z0-9.\-+]+)")
            .context("Échec de compilation du pattern SPDX")?;

        Ok(Self {
            secret_rules,
            spdx_regex,
            allowed_licenses: allowed_licenses.into_iter().map(|s| s.to_uppercase()).collect(),
            denied_licenses: denied_licenses.into_iter().map(|s| s.to_uppercase()).collect(),
            min_entropy_threshold,
            require_license,
        })
    }

    /// Calcule l'entropie de Shannon d'une chaîne
    pub fn shannon_entropy(data: &str) -> f64 {
        if data.is_empty() {
            return 0.0;
        }

        let mut frequencies = HashMap::new();
        for ch in data.chars() {
            *frequencies.entry(ch).or_insert(0usize) += 1;
        }

        let len = data.chars().count() as f64;
        let mut entropy = 0.0;

        for count in frequencies.values() {
            let p = *count as f64 / len;
            entropy -= p * p.log2();
        }

        entropy
    }

    /// Masque les caractères sensibles d'un secret pour affichage sécurisé
    pub fn mask_secret(secret: &str) -> String {
        let len = secret.len();
        if len <= 8 {
            return "*".repeat(len);
        }
        let prefix_len = 4.min(len / 4);
        let suffix_len = 4.min(len / 4);
        let masked_middle = "*".repeat(len.saturating_sub(prefix_len + suffix_len));
        format!(
            "{}{}{}",
            &secret[..prefix_len],
            masked_middle,
            &secret[len - suffix_len..]
        )
    }

    /// Analyse du texte de licence pour détecter les termes types
    pub fn identify_license_text(content: &str) -> Option<String> {
        let upper = content.to_uppercase();

        if upper.contains("MIT LICENSE") || upper.contains("PERMISSION IS HEREBY GRANTED, FREE OF CHARGE") {
            Some("MIT".to_string())
        } else if upper.contains("APACHE LICENSE") && upper.contains("VERSION 2.0") {
            Some("Apache-2.0".to_string())
        } else if upper.contains("GNU GENERAL PUBLIC LICENSE") {
            if upper.contains("VERSION 3") {
                Some("GPL-3.0".to_string())
            } else if upper.contains("VERSION 2") {
                Some("GPL-2.0".to_string())
            } else {
                Some("GPL".to_string())
            }
        } else if upper.contains("GNU AFFERO GENERAL PUBLIC LICENSE") {
            Some("AGPL-3.0".to_string())
        } else if upper.contains("BSD 3-CLAUSE") || upper.contains("REDISTRIBUTION AND USE IN SOURCE AND BINARY FORMS") {
            Some("BSD-3-Clause".to_string())
        } else if upper.contains("BSD 2-CLAUSE") {
            Some("BSD-2-Clause".to_string())
        } else if upper.contains("MOZILLA PUBLIC LICENSE") && upper.contains("2.0") {
            Some("MPL-2.0".to_string())
        } else if upper.contains("UNLICENSE") {
            Some("Unlicense".to_string())
        } else {
            None
        }
    }

    /// Vérifie si une licence respecte la politique configurée
    pub fn evaluate_license(&self, license: &str) -> (bool, String) {
        let lic_upper = license.to_uppercase();

        // 1. Vérification de la liste noire explicite
        if self.denied_licenses.iter().any(|d| d == &lic_upper) {
            return (
                false,
                format!("Licence '{}' formellement interdite par la politique de sécurité", license),
            );
        }

        // 2. Vérification de la liste blanche (si non vide)
        if !self.allowed_licenses.is_empty() {
            if self.allowed_licenses.iter().any(|a| a == &lic_upper) {
                (true, format!("Licence '{}' autorisée", license))
            } else {
                (
                    false,
                    format!("Licence '{}' non présente dans la liste blanche autorisée", license),
                )
            }
        } else {
            (true, format!("Licence '{}' acceptée (politique par défaut)", license))
        }
    }

    /// Vérifie si un buffer ressemble à du contenu binaire
    fn is_binary_buffer(buffer: &[u8]) -> bool {
        // Détecte la présence de null bytes dans les premiers 1024 octets
        let check_len = buffer.len().min(1024);
        buffer[..check_len].contains(&0)
    }

    /// Exécute l'analyse sur un chemin cible
    pub fn scan_path(&self, target_path: &Path) -> Result<ScanReport> {
        let mut report = ScanReport::default();
        let mut checked_license_files = false;

        // Étape 1 : Vérifier la présence de fichiers de licence racine
        if target_path.is_dir() {
            let license_candidates = ["LICENSE", "LICENSE.md", "LICENSE.txt", "COPYING", "UNLICENSE"];
            for candidate in &license_candidates {
                let lic_file = target_path.join(candidate);
                if lic_file.is_file() {
                    checked_license_files = true;
                    if let Ok(content) = fs::read_to_string(&lic_file) {
                        let detected = Self::identify_license_text(&content).unwrap_or_else(|| "Propriétaire / Inconnue".to_string());
                        let (is_allowed, details) = self.evaluate_license(&detected);

                        if !is_allowed {
                            report.license_violations += 1;
                        }

                        report.project_licenses.push(detected.clone());
                        report.license_findings.push(LicenseFinding {
                            file_path: lic_file.display().to_string(),
                            detected_license: detected,
                            is_allowed,
                            details,
                        });
                    }
                }
            }
        }

        // Si aucune licence racine n'est trouvée et qu'elle est requise
        if self.require_license && !checked_license_files && report.project_licenses.is_empty() {
            report.license_violations += 1;
            report.license_findings.push(LicenseFinding {
                file_path: target_path.display().to_string(),
                detected_license: "Absente".to_string(),
                is_allowed: false,
                details: "Aucun fichier de licence racine (LICENSE, COPYING) trouvé alors que l'exigence --require-license est active".to_string(),
            });
        }

        // Étape 2 : Parcourir récursivement les fichiers avec respect de .gitignore
        let walker = WalkBuilder::new(target_path)
            .hidden(true)
            .parents(true)
            .ignore(true)
            .git_ignore(true)
            .git_global(true)
            .filter_entry(|entry| {
                let file_name = entry.file_name().to_string_lossy();
                file_name != "target" && file_name != ".git" && file_name != "node_modules"
            })
            .build();

        for entry in walker {
            let entry = match entry {
                Ok(e) => e,
                Err(err) => {
                    eprintln!("{}: {}", "Avertissement d'accès au fichier".yellow(), err);
                    continue;
                }
            };

            let path = entry.path();
            if !path.is_file() {
                continue;
            }

            // Ignorer les fichiers trop volumineux (> 5 Mo)
            if let Ok(metadata) = entry.metadata() {
                if metadata.len() > 5 * 1024 * 1024 {
                    continue;
                }
            }

            // Lire le fichier
            let mut file = match fs::File::open(path) {
                Ok(f) => f,
                Err(_) => continue,
            };

            let mut buffer = Vec::new();
            if file.read_to_end(&mut buffer).is_err() {
                continue;
            }

            // Ignorer les binaires
            if Self::is_binary_buffer(&buffer) {
                continue;
            }

            let content = match String::from_utf8(buffer) {
                Ok(c) => c,
                Err(_) => continue, // Ignorer les encodages non UTF-8
            };

            report.files_scanned += 1;
            let display_path = path.display().to_string();

            // Analyse ligne par ligne pour les secrets et tags SPDX
            for (line_idx, line) in content.lines().enumerate() {
                let line_num = line_idx + 1;

                // 2.a Détection d'en-tête SPDX
                if let Some(captures) = self.spdx_regex.captures(line) {
                    if let Some(lic_match) = captures.get(1) {
                        let spdx_id = lic_match.as_str().trim();
                        let (is_allowed, details) = self.evaluate_license(spdx_id);
                        if !is_allowed {
                            report.license_violations += 1;
                        }
                        report.license_findings.push(LicenseFinding {
                            file_path: format!("{}:{}", display_path, line_num),
                            detected_license: spdx_id.to_string(),
                            is_allowed,
                            details,
                        });
                    }
                }

                // 2.b Détection des secrets via expressions régulières et entropie
                for rule in &self.secret_rules {
                    for mat in rule.pattern.find_iter(line) {
                        let candidate_raw = mat.as_str();

                        // Extraction de valeur nettoyée si sous-groupe d'affectation
                        let value_to_check = if let Some(caps) = rule.pattern.captures(candidate_raw) {
                            caps.get(1).map(|m| m.as_str()).unwrap_or(candidate_raw)
                        } else {
                            candidate_raw
                        };

                        let entropy = Self::shannon_entropy(value_to_check);

                        // Si la règle spécifie une entropie minimale
                        if let Some(min_ent) = rule.min_entropy {
                            if entropy < min_ent {
                                continue;
                            }
                        } else if entropy < self.min_entropy_threshold {
                            // Filtre global basse entropie
                            continue;
                        }

                        let masked = Self::mask_secret(value_to_check);
                        report.secrets_found += 1;
                        report.secret_findings.push(SecretFinding {
                            rule_name: rule.name.to_string(),
                            file_path: display_path.clone(),
                            line_number: line_num,
                            column: mat.start() + 1,
                            masked_value: masked,
                            entropy,
                            severity: rule.severity,
                        });
                    }
                }
            }
        }

        Ok(report)
    }
}

/// Interface de ligne de commande pour l'outil de sécurité
#[derive(Parser, Debug)]
#[command(
    name = "licsec",
    author = "Damien",
    version = "0.1.0",
    about = "Vérificateur de conformité des licences et détecteur de secrets codés en dur",
    long_about = "Outil d'analyse statique (SAST) permettant d'inspecter une base de code source pour détecter les clés d'API, jetons, secrets à haute entropie et contrôler la conformité des licences logicielles."
)]
struct Cli {
    /// Chemin du fichier ou répertoire à analyser
    #[arg(short = 'p', long = "path", default_value = ".")]
    path: PathBuf,

    /// Licences autorisées (séparées par une virgule, ex: MIT,Apache-2.0,BSD-3-Clause)
    #[arg(short = 'a', long = "allow", value_delimiter = ',')]
    allowed_licenses: Vec<String>,

    /// Licences expressément interdites (séparées par une virgule, ex: GPL-3.0,AGPL-3.0)
    #[arg(short = 'd', long = "deny", value_delimiter = ',')]
    denied_licenses: Vec<String>,

    /// Exiger la présence explicite d'une licence pour valider le scan
    #[arg(long = "require-license", default_value_t = false)]
    require_license: bool,

    /// Seuil minimal d'entropie de Shannon (entre 0.0 et 8.0) pour filtrer les faux positifs
    #[arg(long = "min-entropy", default_value_t = 2.5)]
    min_entropy: f64,

    /// Format de restitution du rapport
    #[arg(short = 'f', long = "format", value_enum, default_value_t = OutputFormat::Text)]
    format: OutputFormat,
}

fn print_text_report(report: &ScanReport) {
    println!("\n{}", "============================================================".blue());
    println!("{}", "             RAPPORT D'ANALYSE DE SÉCURITÉ & LICENCES        ".bold().cyan());
    println!("{}\n", "============================================================".blue());

    println!("{} Fichiers analysés : {}", "•".cyan(), report.files_scanned.to_string().bold());
    println!(
        "{} Licences projet détectées : {}",
        "•".cyan(),
        if report.project_licenses.is_empty() {
            "Aucune licence racine".yellow().to_string()
        } else {
            report.project_licenses.join(", ").green().bold().to_string()
        }
    );

    // Section Secrets
    println!("\n{}", "--- [ DÉTECTION DES SECRETS & JETONS ] ---".bold());
    if report.secret_findings.is_empty() {
        println!("{} Aucun secret codé en dur n'a été détecté.", "✔".green().bold());
    } else {
        println!(
            "{} {} secret(s) potentiel(s) détecté(s) :",
            "✖".red().bold(),
            report.secret_findings.len().to_string().bold().red()
        );
        for finding in &report.secret_findings {
            let sev_tag = match finding.severity {
                Severity::Critical => "[CRITIQUE]".red().bold(),
                Severity::Warning => "[ATTENTION]".yellow().bold(),
                Severity::Info => "[INFO]".blue().bold(),
            };
            println!(
                "  {} {} ({})",
                sev_tag,
                finding.rule_name.bold(),
                format!("{}:{}:{}", finding.file_path, finding.line_number, finding.column).underline()
            );
            println!(
                "     Valeur masquée : {} | Entropie: {:.2}",
                finding.masked_value.magenta(),
                finding.entropy
            );
        }
    }

    // Section Licences
    println!("\n{}", "--- [ CONFORMITÉ DES LICENCES ] ---".bold());
    if report.license_violations == 0 {
        println!("{} Toutes les licences détectées sont conformes.", "✔".green().bold());
    } else {
        println!(
            "{} {} non-conformité(s) de licence détectée(s) :",
            "✖".red().bold(),
            report.license_violations.to_string().bold().red()
        );
    }

    for lic in &report.license_findings {
        let status = if lic.is_allowed {
            "✔".green().bold()
        } else {
            "✖".red().bold()
        };
        println!("  {} {} -> {}", status, lic.file_path, lic.details);
    }

    // Synthèse finale
    println!("\n{}", "============================================================".blue());
    if report.secrets_found == 0 && report.license_violations == 0 {
        println!("{}", "RÉSULTAT GLOBAL : VALIDÉ (Aucune menace ni violation)".green().bold());
    } else {
        println!(
            "{}",
            format!(
                "RÉSULTAT GLOBAL : ÉCHEC ({} secret(s), {} violation(s) de licence)",
                report.secrets_found, report.license_violations
            )
            .red()
            .bold()
        );
    }
    println!("{}\n", "============================================================".blue());
}

fn main() -> Result<ExitCode> {
    let cli = Cli::parse();

    let scanner = Scanner::new(
        cli.allowed_licenses,
        cli.denied_licenses,
        cli.min_entropy,
        cli.require_license,
    )?;

    if !cli.path.exists() {
        eprintln!(
            "{} Le chemin spécifié n'existe pas : {}",
            "Erreur:".red().bold(),
            cli.path.display()
        );
        return Ok(ExitCode::from(2));
    }

    let report = scanner.scan_path(&cli.path)?;

    match cli.format {
        OutputFormat::Json => {
            let json_out = serde_json::to_string_pretty(&report)
                .context("Impossible de sérialiser le rapport en JSON")?;
            println!("{}", json_out);
        }
        OutputFormat::Text => {
            print_text_report(&report);
        }
    }

    if report.secrets_found > 0 || report.license_violations > 0 {
        Ok(ExitCode::FAILURE)
    } else {
        Ok(ExitCode::SUCCESS)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_shannon_entropy() {
        // Chaîne uniforme -> entropie 0
        assert_eq!(Scanner::shannon_entropy("aaaaaaaa"), 0.0);

        // Chaîne aléatoire base64 / token -> entropie élevée
        let entropy = Scanner::shannon_entropy("wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY");
        assert!(entropy > 4.0);
    }

    #[test]
    fn test_mask_secret() {
        assert_eq!(Scanner::mask_secret("1234"), "****");
        let masked = Scanner::mask_secret("AKIAIOSFODNN7EXAMPLE");
        assert!(masked.starts_with("AKIA"));
        assert!(masked.ends_with("MPLE"));
        assert!(masked.contains("********"));
    }

    #[test]
    fn test_identify_license_text() {
        let mit_sample = "Permission is hereby granted, free of charge, to any person obtaining a copy...";
        assert_eq!(Scanner::identify_license_text(mit_sample), Some("MIT".to_string()));

        let apache_sample = "Apache License\nVersion 2.0, January 2004\nhttp://www.apache.org/licenses/";
        assert_eq!(Scanner::identify_license_text(apache_sample), Some("Apache-2.0".to_string()));
    }

    #[test]
    fn test_license_policies() {
        let scanner = Scanner::new(
            vec!["MIT".to_string(), "Apache-2.0".to_string()],
            vec!["GPL-3.0".to_string()],
            2.5,
            false,
        )
        .expect("Scanner initialization should succeed");

        let (allowed, _) = scanner.evaluate_license("MIT");
        assert!(allowed);

        let (denied_gpl, _) = scanner.evaluate_license("GPL-3.0");
        assert!(!denied_gpl);

        let (unapproved, _) = scanner.evaluate_license("BSD-3-Clause");
        assert!(!unapproved);
    }
