// src/main.rs
use anyhow::{bail, Context, Result};
use ed25519_dalek::{
    Signature, Signer, SigningKey, Verifier, VerifyingKey,
};
use rand::rngs::OsRng;
use rand::RngCore;
use serde::{Deserialize, Serialize};
use std::collections::HashSet;
use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream};
use std::sync::Arc;
use std::thread;
use std::time::Duration;
use thiserror::Error;

#[derive(Error, Debug)]
pub enum AuthError {
    #[error("Erreur I/O: {0}")]
    Io(#[from] std::io::Error),
    #[error("Erreur de décodage bincode: {0}")]
    Serialization(#[from] bincode::Error),
    #[error("Clé publique non autorisée")]
    UnauthorizedKey,
    #[error("Signature cryptographique invalide: {0}")]
    InvalidSignature(String),
    #[error("Échec de l'authentification: {0}")]
    AuthFailed(String),
    #[error("Message inattendu reçu lors de la négociation")]
    UnexpectedMessage,
}

/// Messages échangés lors de la négociation d'authentification mutuelle
#[derive(Serialize, Deserialize, Debug, Clone)]
pub enum Message {
    /// Étape 1 : Le client envoie sa clé publique et un nonce aléatoire (challenge pour le serveur)
    ClientHello {
        client_pk: [u8; 32],
        client_nonce: [u8; 32],
    },
    /// Étape 2 : Le serveur renvoie sa clé publique, son nonce (challenge pour le client),
    /// et sa signature attestant du challenge client
    ServerResponse {
        server_pk: [u8; 32],
        server_nonce: [u8; 32],
        signed_client_nonce: Vec<u8>,
    },
    /// Étape 3 : Le client envoie sa signature attestant du challenge serveur
    ClientAuth {
        signed_server_nonce: Vec<u8>,
    },
    /// Étape 4 : Statut final de la session
    AuthStatus {
        success: bool,
        message: String,
    },
}

/// Encodage réseau préfixé par la longueur en 4 octets big-endian
fn send_msg(stream: &mut TcpStream, msg: &Message) -> Result<()> {
    let payload = bincode::serialize(msg).context("Échec de sérialisation du message")?;
    let len = (payload.len() as u32).to_be_bytes();
    stream.write_all(&len).context("Échec d'écriture de la longueur")?;
    stream.write_all(&payload).context("Échec d'écriture du corps du message")?;
    stream.flush().context("Échec du flush du flux réseau")?;
    Ok(())
}

/// Décodage réseau avec contrôle de la taille maximale (limite anti DoS de 64 Ko)
fn recv_msg(stream: &mut TcpStream) -> Result<Message> {
    let mut len_buf = [0u8; 4];
    stream.read_exact(&mut len_buf).context("Échec de lecture de la taille du message")?;
    let len = u32::from_be_bytes(len_buf) as usize;

    const MAX_ALLOWED_LEN: usize = 65_536;
    if len > MAX_ALLOWED_LEN {
        bail!("Message trop volumineux ({len} octets) refusé");
    }

    let mut payload = vec![0u8; len];
    stream.read_exact(&mut payload).context("Échec de lecture du corps du message")?;
    let msg: Message = bincode::deserialize(&payload).context("Échec de désérialisation bincode")?;
    Ok(msg)
}

/// Génère 32 octets aléatoires cryptographiques (nonce)
fn generate_nonce() -> [u8; 32] {
    let mut nonce = [0u8; 32];
    OsRng.fill_bytes(&mut nonce);
    nonce
}

/// Gestion de l'authentification côté Serveur pour un client connecté
fn handle_server_client(
    mut stream: TcpStream,
    server_signing_key: &SigningKey,
    allowed_clients: &HashSet<[u8; 32]>,
) -> Result<()> {
    let peer_addr = stream.peer_addr().context("Impossible d'obtenir l'adresse du pair")?;
    println!("[Serveur] Connexion entrante depuis {peer_addr}");

    // 1. Attente du message ClientHello
    let client_hello = match recv_msg(&mut stream)? {
        Message::ClientHello { client_pk, client_nonce } => (client_pk, client_nonce),
        _ => {
            let err = AuthError::UnexpectedMessage;
            send_msg(&mut stream, &Message::AuthStatus {
                success: false,
                message: err.to_string(),
            })?;
            return Err(err.into());
        }
    };
    let (client_pk_bytes, client_nonce) = client_hello;

    // Vérifier si le client est autorisé
    if !allowed_clients.contains(&client_pk_bytes) {
        println!("[Serveur] Clé publique client non autorisée : {client_pk_bytes:?}");
        send_msg(&mut stream, &Message::AuthStatus {
            success: false,
            message: "Clé publique cliente rejetée".to_string(),
        })?;
        return Err(AuthError::UnauthorizedKey.into());
    }

    let client_verifying_key = VerifyingKey::from_bytes(&client_pk_bytes)
        .map_err(|e| AuthError::InvalidSignature(e.to_string()))?;

    // Le serveur signe le challenge du client
    let server_sig_for_client = server_signing_key.sign(&client_nonce);
    let server_nonce = generate_nonce();
    let server_pk_bytes = server_signing_key.verifying_key().to_bytes();

    // 2. Répondre avec ServerResponse
    send_msg(&mut stream, &Message::ServerResponse {
        server_pk: server_pk_bytes,
        server_nonce,
        signed_client_nonce: server_sig_for_client.to_bytes().to_vec(),
    })?;

    // 3. Attente de la signature du challenge serveur par le client (ClientAuth)
    let client_sig_bytes = match recv_msg(&mut stream)? {
        Message::ClientAuth { signed_server_nonce } => signed_server_nonce,
        _ => {
            let err = AuthError::UnexpectedMessage;
            send_msg(&mut stream, &Message::AuthStatus {
                success: false,
                message: err.to_string(),
            })?;
            return Err(err.into());
        }
    };

    let client_signature = Signature::from_slice(&client_sig_bytes)
        .map_err(|e| AuthError::InvalidSignature(e.to_string()))?;
    if let Err(e) = client_verifying_key.verify(&server_nonce, &client_signature) {
        println!("[Serveur] Signature client erronée : {e}");
        send_msg(&mut stream, &Message::AuthStatus {
            success: false,
            message: "Signature du challenge serveur invalide".to_string(),
        })?;
        return Err(AuthError::InvalidSignature(e.to_string()).into());
    }

    // 4. Succès de l'authentification mutuelle
    send_msg(&mut stream, &Message::AuthStatus {
        success: true,
        message: "Authentification mutuelle réussie avec succès !".to_string(),
    })?;

    println!("[Serveur] Authentification mutuelle validée avec succès pour {peer_addr}");
    Ok(())
}

/// Déroulement de l'authentification côté Client
fn run_client(
    addr: &str,
    client_signing_key: &SigningKey,
    expected_server_pk: &[u8; 32],
) -> Result<()> {
    println!("[Client] Connexion au serveur sur {addr}...");
    let mut stream = TcpStream::connect(addr).context("Échec de connexion au serveur")?;

    let client_pk_bytes = client_signing_key.verifying_key().to_bytes();
    let client_nonce = generate_nonce();

    // 1. Envoi ClientHello
    println!("[Client] Envoi du challenge client (ClientHello)...");
    send_msg(&mut stream, &Message::ClientHello {
        client_pk: client_pk_bytes,
        client_nonce,
    })?;

    // 2. Réception ServerResponse
    let (server_pk_bytes, server_nonce, signed_client_nonce) = match recv_msg(&mut stream)? {
        Message::ServerResponse {
            server_pk,
            server_nonce,
            signed_client_nonce,
        } => (server_pk, server_nonce, signed_client_nonce),
        Message::AuthStatus { success: _, message } => {
            bail!("Rejet par le serveur : {message}");
        }
        _ => return Err(AuthError::UnexpectedMessage.into()),
    };

    // Vérifier la clé publique du serveur
    if &server_pk_bytes != expected_server_pk {
        bail!("Clé publique du serveur reçue ne correspond pas à la clé attendue !");
    }

    let server_verifying_key = VerifyingKey::from_bytes(&server_pk_bytes)
        .map_err(|e| AuthError::InvalidSignature(e.to_string()))?;

    // Vérifier que le serveur a bien signé notre nonce
    let server_signature = Signature::from_slice(&signed_client_nonce)
        .map_err(|e| AuthError::InvalidSignature(e.to_string()))?;
    server_verifying_key
        .verify(&client_nonce, &server_signature)
        .map_err(|e| AuthError::InvalidSignature(format!("Signature serveur invalide: {e}")))?;

    println!("[Client] Challenge serveur et signature du serveur validés avec succès.");

    // 3. Signature du challenge serveur par le client et envoi ClientAuth
    let client_sig_for_server = client_signing_key.sign(&server_nonce);
    println!("[Client] Envoi de la signature du challenge serveur (ClientAuth)...");
    send_msg(&mut stream, &Message::ClientAuth {
        signed_server_nonce: client_sig_for_server.to_bytes().to_vec(),
    })?;

    // 4. Réception du statut final
    match recv_msg(&mut stream)? {
        Message::AuthStatus { success, message } => {
            if success {
                println!("[Client] Félicitations : {message}");
                Ok(())
            } else {
                bail!("Échec de l'authentification finale : {message}");
            }
        }
        _ => Err(AuthError::UnexpectedMessage.into()),
    }
}

