```rust
// src/main.rs
use std::collections::HashSet;
use std::fs;
use std::io::{self, BufRead};
use std::path::PathBuf;
use std::str::FromStr;

use clap::{Args, Parser, Subcommand};
use rand::{rngs::OsRng, RngCore};
use thiserror::Error;

/// Représentation des erreurs du domaine Shamir Secret Sharing et de la CLI.
#[derive(Debug, Error)]
pub enum ShamirError {
    #[error("Le seuil (threshold = {threshold}) doit être au moins égal à 2")]
    ThresholdTooSmall { threshold: u8 },

    #[error("Le nombre total de parts (shares = {shares}) doit être supérieur ou égal au seuil (threshold = {threshold})")]
    ThresholdGreaterThanShares { threshold: u8, shares: u8 },

    #[error("Le nombre de parts fournies ({received}) est insuffisant (seuil minimal requis: {threshold})")]
    InsufficientShares { received: usize, threshold: usize },

    #[error("Le secret ne peut pas être vide")]
    EmptySecret,

    #[error("Toutes les parts doivent avoir la même longueur de données")]
    InconsistentShareLengths,

    #[error("L'index de part x=0 est invalide (doit être compris entre 1 et 255)")]
    InvalidZeroIndex,

    #[error("Index de part dupliqué détecté : x = {0}")]
    DuplicateShareIndex(u8),

    #[error("Format de part invalide: attendu '<x_hex>-<données_hex>', reçu '{0}'")]
    InvalidShareFormat(String),

    #[error("Échec du décodage hexadécimal : {0}")]
    HexDecodeError(#[from] hex::FromHexError),

    #[error("Erreur d'entrée/sortie : {0}")]
    IoError(#[from] io::Error),
}

/// Arithmétique dans GF(2^8) avec le polynôme irréductible standard AES (0x11b = x^8 + x^4 + x^3 + x + 1).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Gf256(pub u8);

impl Gf256 {
    pub const ZERO: Self = Self(0);
    pub const ONE: Self = Self(1);

    /// Addition dans GF(2^8) (opération XOR).
    #[inline]
    pub fn add(self, other: Self) -> Self {
        Self(self.0 ^ other.0)
    }

    /// Soustraction dans GF(2^8) (identique à l'addition).
    #[inline]
    pub fn sub(self, other: Self) -> Self {
        self.add(other)
    }

    /// Multiplication dans GF(2^8) via multiplication de Galois standard (algorithme "Russian Peasant").
    pub fn mul(self, other: Self) -> Self {
        let mut a = self.0;
        let mut b = other.0;
        let mut p = 0u8;

        for _ in 0..8 {
            if (b & 1) != 0 {
                p ^= a;
            }
            let carry = (a & 0x80) != 0;
            a <<= 1;
            if carry {
                a ^= 0x1b; // x^8 + x^4 + x^3 + x + 1 modulo x^8
            }
            b >>= 1;
        }

        Self(p)
    }

    /// Inverse multiplicatif dans GF(2^8) via l'exposant (a^254 car a^255 = 1 pour tout a != 0).
    pub fn inv(self) -> Option<Self> {
        if self.0 == 0 {
            return None;
        }

        // a^(254) dans GF(2^8)
        let mut result = Self::ONE;
        let mut base = self;
        let mut exp = 254u8;

        while exp > 0 {
            if (exp & 1) != 0 {
                result = result.mul(base);
            }
            base = base.mul(base);
            exp >>= 1;
        }

        Some(result)
    }

    /// Division dans GF(2^8).
    pub fn div(self, other: Self) -> Option<Self> {
        other.inv().map(|inv| self.mul(inv))
    }
}

/// Évalue un polynôme P(x) = sum_{i=0..len} coeffs[i] * x^i dans GF(2^8) en utilisant la règle de Horner.
fn evaluate_polynomial(coeffs: &[Gf256], x: Gf256) -> Gf256 {
    let mut acc = Gf256::ZERO;
    for &coeff in coeffs.iter().rev() {
        acc = acc.mul(x).add(coeff);
    }
    acc
}

/// Représentation d'une part de secret de Shamir.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Share {
    pub x: u8,
    pub data: Vec<u8>,
}

impl Share {
    pub fn new(x: u8, data: Vec<u8>) -> Result<Self, ShamirError> {
        if x == 0 {
            return Err(ShamirError::InvalidZeroIndex);
        }
        Ok(Self { x, data })
    }
}

impl ToString for Share {
    fn to_string(&self) -> String {
        format!("{:02x}-{}", self.x, hex::encode(&self.data))
    }
}

impl FromStr for Share {
    type Err = ShamirError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let parts: Vec<&str> = s.trim().splitn(2, '-').collect();
        if parts.len() != 2 {
            return Err(ShamirError::InvalidShareFormat(s.to_string()));
        }

        let x_bytes = hex::decode(parts[0])?;
        if x_bytes.len() != 1 {
            return Err(ShamirError::InvalidShareFormat(s.to_string()));
        }
        let x = x_bytes[0];
        if x == 0 {
            return Err(ShamirError::InvalidZeroIndex);
        }

        let data = hex::decode(parts[1])?;
        Ok(Self { x, data })
    }
}

/// Découpe un secret selon l'algorithme de Shamir.
///
/// - `secret`: octets du secret à protéger
/// - `shares_count`: nombre total de parts à générer (N)
/// - `threshold`: seuil minimal pour la reconstruction (K)
pub fn split_secret(secret: &[u8], shares_count: u8, threshold: u8) -> Result<Vec<Share>, ShamirError> {
    if secret.is_empty() {
        return Err(ShamirError::EmptySecret);
    }
    if threshold < 2 {
        return Err(ShamirError::ThresholdTooSmall { threshold });
    }
    if threshold > shares_count {
        return Err(ShamirError::ThresholdGreaterThanShares {
            threshold,
            shares: shares_count,
        });
    }

    let mut shares: Vec<Vec<u8>> = (0..shares_count)
        .map(|_| Vec::with_capacity(secret.len()))
        .collect();

    let mut coeffs = vec![Gf256::ZERO; threshold as usize];

    for &byte in secret {
        coeffs[0] = Gf256(byte);
        for coeff in coeffs.iter_mut().skip(1) {
            let mut rand_buf = [0u8; 1];
            OsRng.fill_bytes(&mut rand_buf);
            *coeff = Gf256(rand_buf[0]);
        }

        for (idx, share_vec) in shares.iter_mut().enumerate() {
            let x = Gf256((idx + 1) as u8);
            let y = evaluate_polynomial(&coeffs, x);
            share_vec.push(y.0);
        }
    }

    shares
        .into_iter()
        .enumerate()
        .map(|(idx, data)| Share::new((idx + 1) as u8, data))
        .collect()
}

/// Reconstruit le secret d'origine à partir des parts en appliquant l'interpolation de Lagrange en x=0.
pub fn combine_shares(shares: &[Share]) -> Result<Vec<u8>, ShamirError> {
    if shares.len() < 2 {
        return Err(ShamirError::InsufficientShares {
            received: shares.len(),
            threshold: 2,
        });
    }

    let share_len = shares[0].data.len();
    if share_len == 0 {
        return Err(ShamirError::EmptySecret);
    }

    let mut seen_indices = HashSet::new();
    for share in shares {
        if share.x == 0 {
            return Err(ShamirError::InvalidZeroIndex);
        }
        if !seen_indices.insert(share.x) {
            return Err(ShamirError::DuplicateShareIndex(share.x));
        }
        if share.data.len() != share_len {
            return Err(ShamirError::InconsistentShareLengths);
        }
    }

    let k = shares.len();
    let mut secret = Vec::with_capacity(share_len);

    // Calcul des poids de base de Lagrange l_i(0) = prod_{j != i} (0 - x_j) / (x_i - x_j)
    let mut lagrange_coeffs = Vec::with_capacity(k);
    for i in 0..k {
        let xi = Gf256(shares[i].x);
        let mut li = Gf256::ONE;

        for j in 0..k {
            if i == j {
                continue;
            }
            let xj = Gf256(shares[j].x);
            // (0 - xj) = xj dans GF(2^8)
            // (xi - xj) = xi ^ xj
            let denom = xi.sub(xj);
            let num = xj;

            let factor = num
                .div(denom)
                .ok_or(ShamirError::DuplicateShareIndex(shares[i].x))?;
            li = li.mul(factor);
        }
        lagrange_coeffs.push(li);
    }

    for byte_idx in 0..share_len {
        let mut value = Gf256::ZERO;
        for (i, share) in shares.iter().enumerate() {
            let y = Gf256(share.data[byte_idx]);
            value = value.add(y.mul(lagrange_coeffs[i]));
        }
        secret.push(value.0);
    }

    Ok(secret)
}

#[derive(Parser)]
#[command(
    name = "shamir-cli",
    version,
    about = "Outil en ligne de commande pour le partage de secrets selon Shamir (GF(256))",
    long_about = "Permet de fragmenter un secret textuel ou binaire en N parts avec un seuil de reconstruction K, et de reconstituer le secret original."
)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Fragmenter un secret en N parts avec un seuil K
    Split(SplitArgs),
    /// Reconstituer un secret à partir d'au moins K parts
    Combine(CombineArgs),
}

#[derive(Args)]
struct SplitArgs {
    /// Nombre total de parts à générer (2 <= N <= 255)
    #[arg(short = 's', long = "shares", default_value_t = 5)]
    shares: u8,

    /// Seuil minimal de parts requises pour reconstituer le secret (2 <= K <= N)
    #[arg(short = 't', long = "threshold", default_value_t = 3)]
    threshold: u8,

    /// Chaîne de caractères à fragmenter
    #[arg(long = "secret", conflicts_with = "file")]
    secret: Option<String>,

    /// Chemin vers un fichier contenant le secret à fragmenter
    #[arg(short = 'f', long = "file", conflicts_with = "secret")]
    file: Option<PathBuf>,
}

#[derive(Args)]
struct CombineArgs {
    /// Part(s) au format '<x_hex>-<payload_hex>'
    #[arg(short = 's', long = "share")]
    shares: Vec<String>,

    /// Fichier contenant des parts (une part par ligne)
    #[arg(short = 'f', long = "shares-file")]
    shares_file: Option<PathBuf>,

    /// Fichier de sortie où écrire le secret reconstitué
    #[arg(short = 'o', long = "output")]
    output: Option<PathBuf>,
}

fn run() -> Result<(), ShamirError> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Split(args) => {
            let secret_bytes = match (args.secret, args.file) {
                (Some(s), None) => s.into_bytes(),
                (None, Some(path)) => fs::read(&path)?,
                (None, None) => {
                    eprintln!("Veuillez spécifier le secret via --secret ou un fichier avec -f/--file.");
                    std::process::exit(1);
                }
                (Some(_), Some(_)) => unreachable!(),
            };

            let generated_shares = split_secret(&secret_bytes, args.shares, args.threshold)?;

            eprintln!(
                "Secret fragmenté en {} parts (seuil de reconstruction : {}) :",
                args.shares, args.threshold
            );
            for share in generated_shares {
                println!("{}", share.to_string());
            }
        }
        Commands::Combine(args) => {
            let mut raw_shares = args.shares;

            if let Some(file_path) = args.shares_file {
                let file = fs::File::open(file_path)?;
                let reader = io::BufReader::new(file);
                for line in reader.lines() {
                    let line = line?;
                    let trimmed = line.trim();
                    if !trimmed.is_empty() && !trimmed.starts_with('#') {
                        raw_shares.push(trimmed.to_string());
                    }
                }
            }

            if raw_shares.is_empty() {
                eprintln!("Aucune part fournie. Utilisez -s/--share ou -f/--shares-file.");
                std::process::exit(1);
            }

            let parsed_shares: Vec<Share> = raw_shares
                .iter()
                .map(|s| s.parse::<Share>())
                .collect::<Result<_, _>>()?;

            let secret = combine_shares(&parsed_shares)?;

            if let Some(out_path) = args.output {
                fs::write(&out_path, &secret)?;
                println!(
                    "Secret reconstitué avec succès et enregistré dans {}",
                    out_path.display()
                );
            } else {
                match String::from_utf8(secret.clone()) {
                    Ok(text) => {
                        println!("Secret reconstitué (UTF-8) :");
                        println!("{}", text);
                    }
                    Err(_) => {
                        println!("Secret binaire reconstitué (Hex) :");
                        println!("{}", hex::encode(&secret));
                    }
                }
            }
        }
    }

    Ok(())
}

fn main() {
    if let Err(err) = run() {
        eprintln!("Erreur: {err}");
        std::process::exit(1);
    }
}

