        let shares = split_secret(secret, n, k).expect("Le découpage doit réussir");
        assert_eq!(shares.len(), 5);

        // Reconstitution avec exactement k parts (0, 2, 4)
        let subset = vec![shares[0].clone(), shares[2].clone(), shares[4].clone()];
        let reconstructed = combine_shares(&subset).expect("La reconstitution doit réussir");
        assert_eq!(reconstructed, secret);
    }

    #[test]
    fn test_split_and_combine_different_subsets() {
        let secret = b"Clef_Privee_2026";
        let shares = split_secret(secret, 6, 4).expect("Découpage");

        // Tout sous-ensemble de taille >= 4 doit fonctionner
        let subset1 = vec![shares[0].clone(), shares[1].clone(), shares[2].clone(), shares[3].clone()];
        let subset2 = vec![shares[1].clone(), shares[3].clone(), shares[4].clone(), shares[5].clone()];

        assert_eq!(combine_shares(&subset1).unwrap(), secret);
        assert_eq!(combine_shares(&subset2).unwrap(), secret);
    }

    #[test]
    fn test_duplicate_share_detection() {
        let secret = b"Test";
        let shares = split_secret(secret, 4, 2).expect("Découpage");
        let duplicate_subset = vec![shares[0].clone(), shares[0].clone()];

        let result = combine_shares(&duplicate_subset);
        assert!(matches!(result, Err(ShamirError::DuplicateShareIndex(_))));
    }

    #[test]
    fn test_share_parsing() {
        let share = Share::new(1, vec![0xde, 0xad, 0xbe, 0xef]).unwrap();
        let serialized = share.to_string();
        assert_eq!(serialized, "01-deadbeef");

        let parsed: Share = serialized.parse().unwrap();
        assert_eq!(parsed, share);
    }
}

