        let resolved_roles: Vec<String> = self.policy.resolve_roles(roles).into_iter().collect();
        let permissions = self.policy.resolve_permissions(roles);

        let mut matched_allow = false;
        let mut allow_reason = String::new();

        for rule in permissions {
            if Self::pattern_matches(&rule.action, action)
                && Self::pattern_matches(&rule.resource, resource)
            {
                match rule.effect {
                    Effect::Deny => {
                        return DecisionResult {
                            allowed: false,
                            reason: format!(
                                "Interdiction explicite (Deny) par la règle [action: '{}', ressource: '{}']",
                                rule.action, rule.resource
                            ),
                            evaluated_roles: resolved_roles,
                        };
                    }
                    Effect::Allow => {
                        matched_allow = true;
                        allow_reason = format!(
                            "Autorisé (Allow) par la règle [action: '{}', ressource: '{}']",
                            rule.action, rule.resource
                        );
                    }
                }
            }
        }

        if matched_allow {
            DecisionResult {
                allowed: true,
                reason: allow_reason,
                evaluated_roles: resolved_roles,
            }
        } else {
            DecisionResult {
                allowed: false,
                reason: "Aucune règle 'Allow' applicable trouvée (Deny par défaut)".to_string(),
                evaluated_roles: resolved_roles,
            }
        }
    }

    /// Évalue l'autorisation pour un utilisateur identifié
    pub fn evaluate_user(&self, user: &str, action: &str, resource: &str) -> DecisionResult {
        let empty_roles = Vec::new();
        let roles = self
            .policy
            .user_assignments
            .get(user)
            .unwrap_or(&empty_roles);

        if roles.is_empty() {
            return DecisionResult {
                allowed: false,
                reason: format!("L'utilisateur '{}' n'a aucun rôle assigné", user),
                evaluated_roles: Vec::new(),
            };
        }

        self.evaluate_roles(roles, action, resource)
    }
}

/// Définition de l'interface en ligne de commande (CLI)
#[derive(Parser, Debug)]
#[command(
    name = "rbac-json",
    version,
    about = "Moteur et outil CLI de contrôle d'accès basé sur les rôles (RBAC) avec politiques JSON"
)]
struct Cli {
    #[arg(
        short,
        long,
        global = true,
        help = "Chemin vers le fichier de politique JSON",
        default_value = "policy.json"
    )]
    policy: PathBuf,

    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Valide la structure sémantique d'un fichier de politique
    Validate,

    /// Teste une demande d'accès pour un utilisateur ou des rôles
    Check(CheckArgs),

    /// Affiche les rôles résolus et permissions effectives d'un utilisateur ou rôle
    Inspect(InspectArgs),
}

#[derive(Args, Debug)]
struct CheckArgs {
    /// Nom de l'utilisateur (optionnel si des rôles sont fournis directement)
    #[arg(short, long)]
    user: Option<String>,

    /// Rôle(s) à tester manuellement
    #[arg(short, long, value_delimiter = ',')]
    roles: Vec<String>,

    /// Action demandée (ex: "read", "write", "delete")
    #[arg(short, long)]
    action: String,

    /// Ressource ciblée (ex: "documents:finance", "database:users")
    #[arg(long)]
    resource: String,

    /// Format de sortie en JSON
    #[arg(long, default_value_t = false)]
    json: bool,
}

#[derive(Args, Debug)]
struct InspectArgs {
    /// Utilisateur à inspecter
    #[arg(short, long)]
    user: Option<String>,

    /// Rôle à inspecter
    #[arg(short, long)]
    role: Option<String>,
}

fn main() -> anyhow::Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Validate => {
            let policy = Policy::load_from_file(&cli.policy)?;
            println!("Configuration RBAC valide dans '{}'.", cli.policy.display());
            println!("  - {} rôle(s) défini(s)", policy.roles.len());
            println!("  - {} assignation(s) utilisateur", policy.user_assignments.len());
        }

        Commands::Check(args) => {
            let policy = Policy::load_from_file(&cli.policy)?;
            let engine = RbacEngine::new(policy);

            let decision = if let Some(ref user) = args.user {
                engine.evaluate_user(user, &args.action, &args.resource)
            } else if !args.roles.is_empty() {
                engine.evaluate_roles(&args.roles, &args.action, &args.resource)
            } else {
                eprintln!("Erreur: Vous devez spécifier au moins un utilisateur (--user) ou un rôle (--roles).");
                std::process::exit(1);
            };

            if args.json {
                println!("{}", serde_json::to_string_pretty(&decision)?);
            } else {
                println!("--- Résultat de l'Évaluation RBAC ---");
                println!("Décision : {}", if decision.allowed { "ACCORDÉ (ALLOW)" } else { "REFUSÉ (DENY)" });
                println!("Motif    : {}", decision.reason);
                println!("Rôles pris en compte : [{}]", decision.evaluated_roles.join(", "));
            }

            if !decision.allowed {
                std::process::exit(2);
            }
        }

        Commands::Inspect(args) => {
            let policy = Policy::load_from_file(&cli.policy)?;

            if let Some(user) = args.user {
                println!("Inspection pour l'utilisateur: {}", user);
                if let Some(roles) = policy.user_assignments.get(&user) {
                    println!("Rôles directs : {:?}", roles);
                    let resolved = policy.resolve_roles(roles);
                    println!("Rôles effectifs (héritage inclus) : {:?}", resolved);
                    let perms = policy.resolve_permissions(roles);
                    println!("Permissions accordées/refusées :");
                    for p in perms {
                        println!("  - [{:?}] Action: '{}' -> Ressource: '{}'", p.effect, p.action, p.resource);
                    }
                } else {
                    println!("Aucune affectation trouvée pour l'utilisateur '{}'.", user);
                }
            } else if let Some(role) = args.role {
                println!("Inspection pour le rôle: {}", role);
                if policy.roles.contains_key(&role) {
                    let single_role_list = vec![role.clone()];
                    let resolved = policy.resolve_roles(&single_role_list);
                    println!("Rôles effectifs (héritage) : {:?}", resolved);
                    let perms = policy.resolve_permissions(&single_role_list);
                    println!("Permissions :");
                    for p in perms {
                        println!("  - [{:?}] Action: '{}' -> Ressource: '{}'", p.effect, p.action, p.resource);
                    }
                } else {
                    println!("Le rôle '{}' n'existe pas dans la politique.", role);
                }
            } else {
                eprintln!("Spécifiez --user ou --role à inspecter.");
            }
        }
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample_policy() -> Policy {
        let json = r#"
        {
            "roles": {
                "guest": {
                    "inherits": [],
                    "permissions": [
                        { "action": "read", "resource": "public/*", "effect": "allow" }
                    ]
                },
                "editor": {
                    "inherits": ["guest"],
                    "permissions": [
                        { "action": "write", "resource": "articles/*", "effect": "allow" },
                        { "action": "read", "resource": "articles/*", "effect": "allow" }
                    ]
                },
                "admin": {
                    "inherits": ["editor"],
                    "permissions": [
                        { "action": "*", "resource": "*", "effect": "allow" },
                        { "action": "delete", "resource": "system/audit_logs", "effect": "deny" }
                    ]
                }
            },
            "user_assignments": {
                "alice": ["editor"],
                "bob": ["admin"],
                "charlie": ["guest"]
            }
        }
        "#;
        serde_json::from_str(json).expect("Sample policy JSON should be valid")
    }

    #[test]
    fn test_pattern_matching() {
        assert!(RbacEngine::pattern_matches("*", "anything"));
        assert!(RbacEngine::pattern_matches("read", "read"));
        assert!(!RbacEngine::pattern_matches("read", "write"));
        assert!(RbacEngine::pattern_matches("documents/*", "documents/doc1"));
        assert!(RbacEngine::pattern_matches("*.log", "error.log"));
    }

    #[test]
    fn test_role_inheritance_and_permissions() {
        let policy = sample_policy();
        let engine = RbacEngine::new(policy);

        // Charlie (guest) can read public, but cannot write articles
        let r1 = engine.evaluate_user("charlie", "read", "public/readme.txt");
        assert!(r1.allowed);

        let r2 = engine.evaluate_user("charlie", "write", "articles/post1");
        assert!(!r2.allowed);

        // Alice (editor) inherits guest read public, plus can write articles
        let r3 = engine.evaluate_user("alice", "read", "public/readme.txt");
        assert!(r3.allowed);

        let r4 = engine.evaluate_user("alice", "write", "articles/post1");
        assert!(r4.allowed);

        let r5 = engine.evaluate_user("alice", "delete", "articles/post1");
        assert!(!r5.allowed);
    }

    #[test]
    fn test_deny_overrides_allow() {
        let policy = sample_policy();
        let engine = RbacEngine::new(policy);

        // Bob (admin) has wildcard allow, but audit_logs delete is explicit deny
        let r_allowed = engine.evaluate_user("bob", "delete", "articles/post1");
        assert!(r_allowed.allowed);

        let r_denied = engine.evaluate_user("bob", "delete", "system/audit_logs");
        assert!(!r_denied.allowed);
    }

    #[test]
    fn test_cycle_detection() {
        let cyclic_json = r#"
        {
            "roles": {
                "a": { "inherits": ["b"], "permissions": [] },
                "b": { "inherits": ["a"], "permissions": [] }
            },
            "user_assignments": {}
        }
        "#;
        let policy: Result<Policy, _> = serde_json::from_str(cyclic_json);
        assert!(policy.is_ok());
        let validation = policy.unwrap().validate();
        assert!(validation.is_err());
    }
}

