// src/main.rs
//! Générateur CSPRNG avec batterie de tests statistiques de distribution.

use anyhow::{bail, Context, Result};
use clap::Parser;
use rand_chacha::rand_core::{RngCore, SeedableRng};
use rand_chacha::ChaCha20Rng;
use statrs::distribution::{ChiSquared, ContinuousCDF, Normal};
use std::fs::File;
use std::io::Write;
use std::path::PathBuf;

/// Paramètres en ligne de commande.
#[derive(Parser, Debug)]
#[command(
    name = "csprng_stat_eval",
    author = "Damien",
    version = "0.1.0",
    about = "Générateur CSPRNG ChaCha20 et suite de tests statistiques"
)]
struct Cli {
    /// Nombre d'octets à générer et évaluer
    #[arg(short, long, default_value_t = 1_000_000)]
    samples: usize,

    /// Seuil de significativité alpha pour le test statistique (ex: 0.01 ou 0.05)
    #[arg(short, long, default_value_t = 0.01)]
    alpha: f64,

    /// Graine de 32 octets sous forme hexadécimale (64 caractères hex)
    #[arg(long)]
    seed: Option<String>,

    /// Fichier optionnel pour sauvegarder le flux d'octets bruts
    #[arg(short, long)]
    dump: Option<PathBuf>,
}

/// Résultat unitaire d'un test statistique.
#[derive(Debug)]
struct TestResult {
    test_name: &'static str,
    statistic_name: &'static str,
    statistic_value: f64,
    p_value: Option<f64>,
    passed: bool,
    details: String,
}

/// Initialise le générateur CSPRNG ChaCha20.
fn init_rng(seed_hex: Option<&str>) -> Result<ChaCha20Rng> {
    match seed_hex {
        Some(hex_str) => {
            let cleaned = hex_str.trim();
            if cleaned.len() != 64 {
                bail!("La graine hexadécimale doit contenir exactement 64 caractères (32 octets). Reçu : {} caractères.", cleaned.len());
            }

            let mut seed = [0u8; 32];
            for (i, chunk) in cleaned.as_bytes().chunks(2).enumerate() {
                let chunk_str = std::str::from_utf8(chunk)
                    .context("Caractères non UTF-8 dans la chaîne hexadécimale")?;
                seed[i] = u8::from_str_radix(chunk_str, 16)
                    .with_context(|| format!("Octet hexadécimal invalide : '{chunk_str}'"))?;
            }

            Ok(ChaCha20Rng::from_seed(seed))
        }
        None => {
            // Initialisation cryptographiquement sûre depuis l'OS
            let rng = ChaCha20Rng::from_entropy();
            Ok(rng)
        }
    }
}

/// Test 1: Uniformité des octets via le test du Chi-carré (255 degrés de liberté).
fn chi_squared_uniformity_test(data: &[u8], alpha: f64) -> Result<TestResult> {
    if data.is_empty() {
        bail!("Aucune donnée fournie pour le test du Chi-carré.");
    }

    let mut byte_counts = [0usize; 256];
    for &b in data {
        byte_counts[b as usize] += 1;
    }

    let expected = data.len() as f64 / 256.0;
    let mut chi_square_stat = 0.0;
    for &count in &byte_counts {
        let diff = count as f64 - expected;
        chi_square_stat += (diff * diff) / expected;
    }

    let degrees_of_freedom = 255.0;
    let chi_dist = ChiSquared::new(degrees_of_freedom)
        .context("Échec de création de la distribution Chi-carré")?;

    // La p-valeur correspond à P(X >= chi_square_stat) = 1 - CDF(chi_square_stat)
    let cdf_val = chi_dist.cdf(chi_square_stat);
    let p_value = (1.0 - cdf_val).clamp(0.0, 1.0);
    let passed = p_value >= alpha;

    Ok(TestResult {
        test_name: "Chi-carré d'uniformité des octets",
        statistic_name: "χ²",
        statistic_value: chi_square_stat,
        p_value: Some(p_value),
        passed,
        details: format!(
            "Degrés de liberté = 255, Effectif attendu/classe = {:.2}",
            expected
        ),
    })
}

/// Test 2: Fréquence binaire (Monobit Test).
fn monobit_frequency_test(data: &[u8], alpha: f64) -> Result<TestResult> {
    let total_bits = (data.len() * 8) as f64;
    if total_bits == 0.0 {
        bail!("Flux vide pour le test monobit.");
    }

    let mut ones_count: u64 = 0;
    for &b in data {
        ones_count += b.count_ones() as u64;
    }
    let zeros_count = (data.len() * 8) as u64 - ones_count;

    // Statistique S_n = |nb_uns - nb_zeros|
    let s_n = (ones_count as f64 - zeros_count as f64).abs();
    let s_obs = s_n / total_bits.sqrt();

    // Loi normale standard : p-valeur = 2 * (1 - Phi(s_obs)) (ou erfc(s_obs / sqrt(2)))
    let normal_dist = Normal::new(0.0, 1.0).map_err(|e| anyhow::anyhow!("{e}"))?;
    let raw_p: f64 = 2.0 * (1.0 - normal_dist.cdf(s_obs));
    let p_value = raw_p.clamp(0.0, 1.0);
    let passed = p_value >= alpha;

    Ok(TestResult {
        test_name: "Test Monobit (Fréquence binaire)",
        statistic_name: "S_obs",
        statistic_value: s_obs,
        p_value: Some(p_value),
        passed,
        details: format!(
            "Total bits: {:.0} | '1': {} ({:.3}%) | '0': {} ({:.3}%)",
            total_bits,
            ones_count,
            (ones_count as f64 / total_bits) * 100.0,
            zeros_count,
            (zeros_count as f64 / total_bits) * 100.0
        ),
    })
}

/// Test 3: Test des Runs (Alternance des séries de bits identiques).
fn runs_test(data: &[u8], alpha: f64) -> Result<TestResult> {
    let n = (data.len() * 8) as f64;
    if n < 100.0 {
        bail!("Échantillon trop faible pour le test des runs (minimum 100 bits requis).");
    }

    let mut ones_count: u64 = 0;
    for &b in data {
        ones_count += b.count_ones() as u64;
    }
    let pi = ones_count as f64 / n;

    // Condition préliminaire recommandée par le NIST : |pi - 0.5| < 2 / sqrt(n)
    let threshold = 2.0 / n.sqrt();
    if (pi - 0.5).abs() >= threshold {
        return Ok(TestResult {
            test_name: "Test des Runs (Suites consécutives)",
            statistic_name: "V_n",
            statistic_value: 0.0,
            p_value: Some(0.0),
            passed: false,
            details: format!(
                "Échec du critère préliminaire de fréquence : |π - 0.5| = {:.6} >= {:.6}",
                (pi - 0.5).abs(),
                threshold
            ),
        });
    }

    // Calcul du nombre de runs (transitions + 1)
    let mut v_obs = 1.0;
    let mut prev_bit: Option<u8> = None;

    for &byte in data {
        for bit_idx in (0..8).rev() {
            let current_bit = (byte >> bit_idx) & 1;
            if let Some(prev) = prev_bit {
                if current_bit != prev {
                    v_obs += 1.0;
                }
            }
            prev_bit = Some(current_bit);
        }
    }

    // P-valeur via la loi normale approchée
    let numerator = (v_obs - (2.0 * n * pi * (1.0 - pi))).abs();
    let denominator = 2.0 * (2.0 * n).sqrt() * pi * (1.0 - pi);
    let p_value = if denominator > 0.0 {
        let z = numerator / denominator;
        let normal = Normal::new(0.0, 1.0).map_err(|e| anyhow::anyhow!("{e}"))?;
        let raw_p: f64 = 2.0 * (1.0 - normal.cdf(z));
        raw_p.clamp(0.0, 1.0)
    } else {
        0.0
    };

    let passed = p_value >= alpha;

    Ok(TestResult {
        test_name: "Test des Runs (Suites consécutives)",
        statistic_name: "V_obs",
        statistic_value: v_obs,
        p_value: Some(p_value),
        passed,
        details: format!(
            "Total runs observés = {:.0}, Proportion π = {:.6}",
            v_obs, pi
        ),
    })
}

/// Test 4: Calcul de l'entropie de Shannon empirique.
fn shannon_entropy(data: &[u8]) -> Result<TestResult> {
    if data.is_empty() {
        bail!("Données vides pour le calcul d'entropie.");
    }

    let mut byte_counts = [0usize; 256];
    for &b in data {
        byte_counts[b as usize] += 1;
    }

    let total = data.len() as f64;
    let mut entropy = 0.0;

    for &count in &byte_counts {
        if count > 0 {
            let p = count as f64 / total;
            entropy -= p * p.log2();
        }
    }

    // Pour un flux aléatoire uniforme de 256 symboles, l'entropie max théorique est 8.0 bits/octet
    // On valide si l'entropie est très proche du maximum théorique (ex: > 7.99 bits pour >= 100_000 octets)
    let min_acceptable_entropy = if total >= 100_000.0 {
        7.99
    } else if total >= 10_000.0 {
        7.95
    } else {
        7.50
    };

    let passed = entropy >= min_acceptable_entropy;

    Ok(TestResult {
        test_name: "Entropie de Shannon",
        statistic_name: "H (bits/octet)",
        statistic_value: entropy,
        p_value: None,
        passed,
        details: format!(
            "Entropie = {:.6} / 8.000000 (Seuil requis : {:.2})",
            entropy, min_acceptable_entropy
        ),
    })
}

fn print_results(results: &[TestResult], alpha: f64) {
    println!("\n================================================================================");
    println!("                   RÉSULTATS DE L'ÉVALUATION STATISTIQUE");
    println!("================================================================================");
    println!("Seuil de significativité global (alpha) : {:.4}\n", alpha);

    let mut all_passed = true;

    for res in results {
        let status = if res.passed {
            "[\x1b[32mVALIDÉ\x1b[0m]"
        } else {
            all_passed = false;
            "[\x1b[31mREJETÉ\x1b[0m]"
        };

        println!("{:<40} {}", res.test_name, status);
        println!(
            "  -> Statistique ({}) : {:.6}",
            res.statistic_name, res.statistic_value
        );

        if let Some(p) = res.p_value {
            println!("  -> P-valeur         : {:.6} (seuil: {:.4})", p, alpha);
        }
        println!("  -> Détails          : {}", res.details);
        println!("--------------------------------------------------------------------------------");
    }

    if all_passed {
        println!("\x1b[32mConclusion : Le générateur satisfait tous les critères statistiques d'aléa testés.\x1b[0m");
    } else {
        println!("\x1b[31mConclusion : Le générateur présente des anomalies de distribution statistique.\x1b[0m");
    }
    println!("================================================================================\n");
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    println!("Générateur CSPRNG ChaCha20 - Évaluation statistique");
    println!("Nombre d'échantillons demandés : {} octets", cli.samples);

    // Initialisation du CSPRNG
    let mut rng = init_rng(cli.seed.as_deref())
        .context("Erreur lors de l'initialisation du générateur CSPRNG")?;

    // Génération du flux cryptographique
    let mut buffer = vec![0u8; cli.samples];
    rng.fill_bytes(&mut buffer);

    // Sauvegarde optionnelle dans un fichier binaire
    if let Some(dump_path) = &cli.dump {
        let mut file = File::create(dump_path)
            .with_context(|| format!("Impossible de créer le fichier {}", dump_path.display()))?;
        file.write_all(&buffer)
            .with_context(|| format!("Erreur d'écriture dans {}", dump_path.display()))?;
        println!("Flux binaire sauvegardé avec succès dans : {}", dump_path.display());
    }

    // Exécution des tests statistiques
    let results = vec![
        chi_squared_uniformity_test(&buffer, cli.alpha)?,
        monobit_frequency_test(&buffer, cli.alpha)?,
        runs_test(&buffer, cli.alpha)?,
        shannon_entropy(&buffer)?,
    ];

    // Affichage synthétique des résultats
    print_results(&results, cli.alpha);

    Ok(())
}

