#[derive(ValueEnum, Clone, Copy, Debug, PartialEq, Eq)]
enum OutputFormat {
    Table,
    Json,
    Markdown,
    Summary,
}

#[derive(ValueEnum, Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
enum Severity {
    Informational,
    Low,
    Medium,
    High,
    Critical,
}

impl fmt::Display for Severity {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Severity::Informational => write!(f, "INFO"),
            Severity::Low => write!(f, "LOW"),
            Severity::Medium => write!(f, "MEDIUM"),
            Severity::High => write!(f, "HIGH"),
            Severity::Critical => write!(f, "CRITICAL"),
        }
    }
}

#[derive(ValueEnum, Clone, Copy, Debug, PartialEq, Eq)]
enum FailLevel {
    None,
    Low,
    Medium,
    High,
    Critical,
}

impl FailLevel {
    fn should_fail_for(&self, severity: Severity) -> bool {
        match self {
            FailLevel::None => false,
            FailLevel::Low => severity >= Severity::Low,
            FailLevel::Medium => severity >= Severity::Medium,
            FailLevel::High => severity >= Severity::High,
            FailLevel::Critical => severity >= Severity::Critical,
        }
    }
}

