    vulnerabilities_count: usize,
    deprecated_count: usize,
    untrusted_source_count: usize,
}

impl AuditSummary {
    fn update_with_finding(&mut self, finding: &AuditFinding) {
        match finding.severity {
            Severity::Critical => self.critical_count += 1,
            Severity::High => self.high_count += 1,
            Severity::Medium => self.medium_count += 1,
            Severity::Low => self.low_count += 1,
            Severity::Informational => self.info_count += 1,
        }

        match &finding.detail {
            FindingDetail::SecurityVulnerability { .. } => self.vulnerabilities_count += 1,
            FindingDetail::DependencyDuplicate { .. } => self.duplicate_crates_count += 1,
            FindingDetail::DeprecatedPackage { .. } => self.deprecated_count += 1,
            FindingDetail::SuspiciousSource { .. } | FindingDetail::MissingChecksum => {
                self.untrusted_source_count += 1
            }
        }
    }
