            description: "Symlink follow attack on Windows allows arbitrary directory deletion.".to_string(),
            severity: Severity::High,
            affected_version_req: "< 0.8.2".to_string(),
            patched_versions: vec![">= 0.8.2".to_string()],
            reference_url: "https://rustsec.org/advisories/RUSTSEC-2022-0013.html".to_string(),
        },
        SecurityAdvisory {
            id: "RUSTSEC-2024-0336".to_string(),
            package: "serde_yaml".to_string(),
            title: "serde_yaml is unmaintained and susceptible to denial of service".to_string(),
            description: "serde_yaml is officially unmaintained and parser recursion limits can cause stack overflow crashes.".to_string(),
            severity: Severity::Medium,
            affected_version_req: "*".to_string(),
            patched_versions: vec!["None (Migrate to alternative like serde_yml)".to_string()],
            reference_url: "https://rustsec.org/advisories/RUSTSEC-2024-0336.html".to_string(),
        },
    ]
}

fn embedded_deprecated_rules() -> Vec<DeprecatedCrateRule> {
    vec![
        DeprecatedCrateRule {
            package: "lazy_static".to_string(),
            reason: "Crate en maintenance minimale. Remplacé par std::sync::LazyLock dans la stdlib (Rust >= 1.80) ou once_cell.".to_string(),
            suggested_alternative: "std::sync::LazyLock ou once_cell".to_string(),
            severity: Severity::Informational,
        },
        DeprecatedCrateRule {
            package: "tempdir".to_string(),
            reason: "Crate dépréciée et non maintenue. Risques d'insécurité sur la création des fichiers temporaires.".to_string(),
            suggested_alternative: "tempfile".to_string(),
            severity: Severity::Medium,
        },
        DeprecatedCrateRule {
            package: "net2".to_string(),
            reason: "Crate abandonnée et dépréciée depuis 2020.".to_string(),
            suggested_alternative: "socket2".to_string(),
            severity: Severity::Medium,
        },
        DeprecatedCrateRule {
            package: "rustc-serialize".to_string(),
            reason: "Ancienne bibliothèque de sérialisation remplacée par Serde depuis de nombreuses années.".to_string(),
            suggested_alternative: "serde et serde_json".to_string(),
            severity: Severity::Medium,
        },
        DeprecatedCrateRule {
            package: "time".to_string(),
            reason: "Les versions antérieures à 0.2 (notamment 0.1) sont non sécurisées (RUSTSEC-2020-0071).".to_string(),
            suggested_alternative: "time >= 0.3".to_string(),
            severity: Severity::High,
        },
    ]
}

// ==========================================
// Logique d'analyse & Moteur d'audit
// ==========================================

fn parse_cargo_lock<P: AsRef<Path>>(path: P) -> Result<CargoLock, anyhow::Error> {
    let content = fs::read_to_string(path.as_ref())
        .map_err(|e| anyhow::anyhow!("Impossible de lire '{}' : {}", path.as_ref().display(), e))?;

    let lock: CargoLock = toml::from_str(&content).map_err(|e| {
        anyhow::anyhow!(
            "Format Cargo.lock invalide dans '{}' : {}",
            path.as_ref().display(),
            e
        )
    })?;

    Ok(lock)
}

fn load_advisories(custom_path: Option<&Path>) -> Result<Vec<SecurityAdvisory>, anyhow::Error> {
    let mut advisories = embedded_advisories();

    if let Some(path) = custom_path {
        let content = fs::read_to_string(path).map_err(|e| {
            anyhow::anyhow!(
                "Échec de lecture des advisories '{}' : {}",
                path.display(),
                e
            )
        })?;
        let custom: Vec<SecurityAdvisory> = serde_json::from_str(&content)
            .map_err(|e| anyhow::anyhow!("JSON invalide pour le fichier d'advisories : {}", e))?;
        advisories.extend(custom);
    }

    Ok(advisories)
}

fn run_audit(lock: &CargoLock, cli: &Cli, advisories: &[SecurityAdvisory]) -> AuditReport {
    let mut findings = Vec::new();
    let deprecated_rules = embedded_deprecated_rules();

    // 1. Dépouillement des versions et comptage par paquet
    let mut package_versions: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    for pkg in &lock.packages {
        package_versions
            .entry(pkg.name.clone())
            .or_default()
            .insert(pkg.version.clone());
    }

    let total_packages_count = lock.packages.len();
    let unique_packages_count = package_versions.len();

    // 2. Détection des duplications de dépendances
    if !cli.ignore_duplicates {
        for (name, versions) in &package_versions {
            if versions.len() > 1 && !cli.allow_duplicates.contains(name) {
                let versions_list: Vec<String> = versions.iter().cloned().collect();
                findings.push(AuditFinding {
                    package: name.clone(),
                    version: versions_list.join(", "),
                    severity: Severity::Low,
                    title: format!(
                        "Dépendance dupliquée : {} versions concurrentes détectées",
                        versions.len()
                    ),
                    detail: FindingDetail::DependencyDuplicate {
                        total_instances: versions.len(),
                        detected_versions: versions_list,
                    },
                });
            }
        }
    }

    // 3. Analyse détaillée paquet par paquet
    for pkg in &lock.packages {
        let pkg_version = Version::parse(&pkg.version).ok();

        // 3.1 Vérification des vulnérabilités de sécurité
        for adv in advisories {
            if adv.package == pkg.name {
                if cli.ignore_ids.contains(&adv.id) {
                    continue;
                }

                let matches_vuln = if adv.affected_version_req == "*" {
                    true
                } else if let Some(ref parsed_ver) = pkg_version {
                    match VersionReq::parse(&adv.affected_version_req) {
                        Ok(req) => req.matches(parsed_ver),
                        Err(_) => false,
                    }
                } else {
                    false
                };

                if matches_vuln {
                    findings.push(AuditFinding {
                        package: pkg.name.clone(),
                        version: pkg.version.clone(),
                        severity: adv.severity,
                        title: format!("[{}] {}", adv.id, adv.title),
                        detail: FindingDetail::SecurityVulnerability {
                            advisory_id: adv.id.clone(),
                            title: adv.title.clone(),
                            affected_req: adv.affected_version_req.clone(),
                            patched_versions: adv.patched_versions.clone(),
                            reference_url: adv.reference_url.clone(),
                        },
                    });
                }
            }
        }

        // 3.2 Vérification des bibliothèques dépréciées
        if !cli.ignore_deprecated {
            for dep in &deprecated_rules {
                if dep.package == pkg.name {
                    // Vérification spéciale pour time : < 0.2
                    let is_deprecated = if dep.package == "time" {
                        if let Some(ref v) = pkg_version {
                            v.major == 0 && v.minor < 2
                        } else {
                            false
                        }
                    } else {
                        true
                    };

                    if is_deprecated {
                        findings.push(AuditFinding {
                            package: pkg.name.clone(),
                            version: pkg.version.clone(),
                            severity: dep.severity,
                            title: format!("Paquet déprécié ou déconseillé : {}", dep.package),
                            detail: FindingDetail::DeprecatedPackage {
                                reason: dep.reason.clone(),
                                suggested_alternative: dep.suggested_alternative.clone(),
                            },
                        });
                    }
                }
            }
        }

        // 3.3 Vérification des sources suspectes et intégrité
        if !cli.ignore_sources {
            if let Some(ref source) = pkg.source {
                if source.starts_with("git+") {
                    let is_commit_pinned = source.contains('#')
                        && source
                            .split('#')
                            .next_back()
                            .is_some_and(|rev| rev.len() == 40);
                    if !is_commit_pinned {
                        findings.push(AuditFinding {
                            package: pkg.name.clone(),
                            version: pkg.version.clone(),
                            severity: Severity::Medium,
                            title: "Source Git non épinglée sur un hash de commit immuable".to_string(),
                            detail: FindingDetail::SuspiciousSource {
                                source: source.clone(),
                                reason: "Une dépendance Git sans commit hash complet expose à des modifications non contrôlées du code source.".to_string(),
                            },
                        });
                    }
                } else if source.starts_with("http://") {
                    findings.push(AuditFinding {
                        package: pkg.name.clone(),
                        version: pkg.version.clone(),
                        severity: Severity::High,
                        title: "Source HTTP non chiffrée détectée".to_string(),
                        detail: FindingDetail::SuspiciousSource {
                            source: source.clone(),
                            reason: "Téléchargement en clair susceptible d'attaques de type Man-in-the-Middle (MitM).".to_string(),
                        },
                    });
                }
            } else if pkg.checksum.is_none() && pkg.source.is_none() {
                // Dépendance locale / workspace membre : acceptable, pas d'alerte checksum
            }

            // Manque de checksum sur un paquet tiers
            if pkg.source.is_some() && pkg.checksum.is_none() {
                findings.push(AuditFinding {
                    package: pkg.name.clone(),
                    version: pkg.version.clone(),
                    severity: Severity::Medium,
                    title: "Empreinte cryptographique (checksum) manquante".to_string(),
                    detail: FindingDetail::MissingChecksum,
                });
            }
        }
    }

    // Tri des constatations : Sévérité décroissante puis Nom de paquet
    findings.sort_by(|a, b| {
        b.severity
            .cmp(&a.severity)
            .then_with(|| a.package.cmp(&b.package))
    });

    let mut summary = AuditSummary::default();
    for finding in &findings {
        summary.update_with_finding(finding);
    }

    AuditReport {
        target_lockfile: cli.lockfile.display().to_string(),
        cargo_lock_version: lock.version,
        total_packages_count,
        unique_packages_count,
        findings,
        summary,
    }
}

// ==========================================
// Formats d'affichage et de restitution
// ==========================================

fn render_table(report: &AuditReport, verbose: bool) {
    println!(
        "\n{} {}",
        "==> Audit de sécurité Cargo.lock :".bold().cyan(),
        report.target_lockfile.bold()
    );

    if report.findings.is_empty() {
        println!(
            "\n{}",
            "✔ Aucune vulnérabilité ni anomalie détectée dans les dépendances."
                .bold()
                .green()
        );
    } else {
        println!(
            "\n{}",
            format!(
                "Trouvé {} problème(s) potentiel(s) :",
                report.findings.len()
            )
            .bold()
            .yellow()
        );

        let mut table = Table::new();
        table.load_preset(UTF8_FULL);
        table.apply_modifier(UTF8_ROUND_CORNERS);
        table.set_header(vec![
            Cell::new("Sévérité").set_alignment(CellAlignment::Center),
            Cell::new("Paquet"),
            Cell::new("Version"),
            Cell::new("Constat & Recommandation"),
        ]);

        for f in &report.findings {
            let (sev_str, color) = match f.severity {
                Severity::Critical => (f.severity.to_string(), Color::DarkRed),
                Severity::High => (f.severity.to_string(), Color::Red),
                Severity::Medium => (f.severity.to_string(), Color::Yellow),
                Severity::Low => (f.severity.to_string(), Color::Blue),
                Severity::Informational => (f.severity.to_string(), Color::Cyan),
            };

            let recommendation = match &f.detail {
                FindingDetail::SecurityVulnerability {
                    affected_req,
                    patched_versions,
                    reference_url,
                    ..
                } => {
                    let patches = if patched_versions.is_empty() {
                        "Aucun correctif disponible".to_string()
                    } else {
                        patched_versions.join(", ")
                    };
                    format!(
                        "{}\nAffecte : {}\nCorrectif : {}\nRéf : {}",
                        f.title, affected_req, patches, reference_url
                    )
                }
                FindingDetail::DependencyDuplicate {
                    total_instances: _,
                    detected_versions,
                } => {
                    format!(
                        "{}\nVersions : {}\nAction : Unifier les spécifications de dépendances dans Cargo.toml",
                        f.title,
                        detected_versions.join(", ")
                    )
                }
                FindingDetail::SuspiciousSource { source, reason } => {
                    format!("{}\nSource : {}\nDanger : {}", f.title, source, reason)
                }
                FindingDetail::MissingChecksum => {
                    "Absence de hachage SHA-256 dans Cargo.lock. Régénérez avec 'cargo update'."
                        .to_string()
                }
                FindingDetail::DeprecatedPackage {
                    reason,
                    suggested_alternative,
                } => {
                    format!(
                        "{}\nRaison : {}\nAlternative recommandée : {}",
                        f.title, reason, suggested_alternative
                    )
                }
            };

            table.add_row(Row::from(vec![
                Cell::new(sev_str).fg(color),
                Cell::new(&f.package).set_alignment(CellAlignment::Left),
                Cell::new(&f.version),
                Cell::new(recommendation),
            ]));
        }

        println!("{table}");
    }

    render_summary_block(
        &report.summary,
        report.total_packages_count,
        report.unique_packages_count,
    );

    if verbose {
        println!("\n{}", "--- Détails de l'environnement ---".dimmed());
        println!("Fichier analysé : {}", report.target_lockfile);
        println!(
            "Version de structure Cargo.lock : {}",
            report
                .cargo_lock_version
                .map_or("Automatique (V1-V4)".to_string(), |v| v.to_string())
        );
    }
}

fn render_summary_block(summary: &AuditSummary, total: usize, unique: usize) {
    let mut table = Table::new();
    table.load_preset(UTF8_FULL);
    table.apply_modifier(UTF8_ROUND_CORNERS);
    table.set_header(vec![
        Cell::new("Métrique d'Audit").set_alignment(CellAlignment::Left),
        Cell::new("Valeur").set_alignment(CellAlignment::Center),
    ]);

    table.add_row(Row::from(vec![
        Cell::new("Total de paquets audités"),
        Cell::new(total.to_string()),
    ]));
    table.add_row(Row::from(vec![
        Cell::new("Paquets uniques"),
        Cell::new(unique.to_string()),
    ]));
    table.add_row(Row::from(vec![
        Cell::new("Vulnérabilités de sécurité"),
        Cell::new(summary.vulnerabilities_count.to_string()).fg(
            if summary.vulnerabilities_count > 0 {
                Color::Red
            } else {
                Color::Green
            },
        ),
    ]));
    table.add_row(Row::from(vec![
        Cell::new("  - Critiques"),
        Cell::new(summary.critical_count.to_string()).fg(if summary.critical_count > 0 {
            Color::DarkRed
        } else {
            Color::Reset
        }),
    ]));
    table.add_row(Row::from(vec![
        Cell::new("  - Élevées (High)"),
        Cell::new(summary.high_count.to_string()).fg(if summary.high_count > 0 {
            Color::Red
        } else {
            Color::Reset
        }),
    ]));
    table.add_row(Row::from(vec![
        Cell::new("  - Moyennes (Medium)"),
        Cell::new(summary.medium_count.to_string()).fg(if summary.medium_count > 0 {
            Color::Yellow
        } else {
            Color::Reset
        }),
    ]));
    table.add_row(Row::from(vec![
        Cell::new("  - Faibles (Low)"),
        Cell::new(summary.low_count.to_string()),
    ]));
    table.add_row(Row::from(vec![
        Cell::new("  - Informatif (Info)"),
        Cell::new(summary.info_count.to_string()),
    ]));
    table.add_row(Row::from(vec![
        Cell::new("Dépendances dupliquées"),
        Cell::new(summary.duplicate_crates_count.to_string()),
    ]));
    table.add_row(Row::from(vec![
        Cell::new("Paquets dépréciés"),
        Cell::new(summary.deprecated_count.to_string()),
    ]));
    table.add_row(Row::from(vec![
        Cell::new("Sources suspectes ou non sécurisées"),
        Cell::new(summary.untrusted_source_count.to_string()),
    ]));

    println!("\n{}", "Synthèse globale de l'audit :".bold());
    println!("{table}");
}

fn render_markdown(report: &AuditReport) {
    println!("# Rapport d'audit de sécurité des dépendances Rust\n");
    println!("- **Fichier audité :** `{}`", report.target_lockfile);
    println!("- **Total des paquets :** {}", report.total_packages_count);
    println!("- **Paquets uniques :** {}", report.unique_packages_count);
    println!("- **Total des alertes :** {}\n", report.findings.len());

    println!("## Synthèse des vulnérabilités\n");
    println!("| Sévérité | Nombre |");
    println!("| :--- | :---: |");
    println!("| **Critical** | {} |", report.summary.critical_count);
    println!("| **High** | {} |", report.summary.high_count);
    println!("| **Medium** | {} |", report.summary.medium_count);
    println!("| **Low** | {} |", report.summary.low_count);
    println!("| **Info** | {} |\n", report.summary.info_count);

    if report.findings.is_empty() {
        println!("> ✅ **Statut : Succès.** Aucune vulnérabilité ni anomalie détectée.");
        return;
    }

    println!("## Liste détaillée des constatations\n");
    println!("| Sévérité | Paquet | Version | Problème | Recommandation |");
    println!("| :--- | :--- | :--- | :--- | :--- |");

    for f in &report.findings {
        let (problem, reco) = match &f.detail {
            FindingDetail::SecurityVulnerability {
                advisory_id,
                title,
                affected_req,
                patched_versions,
                reference_url,
            } => {
                let p = format!("[{advisory_id}] {title} (Affecte: `{affected_req}`)");
                let r = format!(
                    "Mettre à jour vers: {} ([Consulter l'avis]({}))",
                    patched_versions.join(", "),
                    reference_url
                );
                (p, r)
            }
            FindingDetail::DependencyDuplicate {
                total_instances,
                detected_versions,
            } => (
                format!("{total_instances} versions concurrentes dans l'arbre"),
                format!("Harmoniser: `{}`", detected_versions.join(", ")),
            ),
            FindingDetail::SuspiciousSource { source, reason } => {
                (format!("Source non sécurisée: `{source}`"), reason.clone())
            }
            FindingDetail::MissingChecksum => (
                "Checksum SHA-256 manquant".to_string(),
                "Exécuter `cargo update` pour rafraîchir le lockfile".to_string(),
            ),
            FindingDetail::DeprecatedPackage {
                reason,
                suggested_alternative,
            } => (
                format!("Déprécié: {reason}"),
                format!("Remplacer par: `{suggested_alternative}`"),
            ),
        };

        println!(
            "| **{}** | `{}` | `{}` | {} | {} |",
            f.severity, f.package, f.version, problem, reco
        );
    }
}

// ==========================================
// Point d'entrée principal
// ==========================================

fn main() -> ExitCode {
    let cli = Cli::parse();

    if !cli.lockfile.exists() {
        eprintln!(
            "{} Le fichier '{}' est introuvable.",
            "ERREUR :".bold().red(),
            cli.lockfile.display()
        );
        eprintln!("Indiquez un chemin valide avec l'option --lockfile <FILE>.");
        return ExitCode::from(2);
    }

    let lock = match parse_cargo_lock(&cli.lockfile) {
        Ok(l) => l,
        Err(e) => {
            eprintln!("{} {}", "ERREUR :".bold().red(), e);
            return ExitCode::from(2);
        }
    };

    let advisories = match load_advisories(cli.custom_advisories.as_deref()) {
        Ok(adv) => adv,
        Err(e) => {
            eprintln!("{} {}", "ERREUR :".bold().red(), e);
            return ExitCode::from(2);
        }
    };

    let report = run_audit(&lock, &cli, &advisories);

    match cli.format {
        OutputFormat::Table => render_table(&report, cli.verbose),
        OutputFormat::Json => match serde_json::to_string_pretty(&report) {
            Ok(json) => println!("{json}"),
            Err(e) => {
                eprintln!("Erreur de sérialisation JSON : {e}");
                return ExitCode::from(2);
            }
        },
        OutputFormat::Markdown => render_markdown(&report),
        OutputFormat::Summary => {
            render_summary_block(
                &report.summary,
                report.total_packages_count,
                report.unique_packages_count,
            );
        }
    }

    // Détermination de l'échec selon le niveau de tolérance configuré
    let mut should_fail = false;
    for finding in &report.findings {
        if cli.fail_level.should_fail_for(finding.severity) {
            should_fail = true;
            break;
        }
    }

    if should_fail {
        eprintln!(
            "\n{} Des constatations atteignant ou dépassant le seuil '{:?}' ont été détectées.",
            "ÉCHEC CI/CD :".bold().red(),
            cli.fail_level
        );
        ExitCode::from(1)
    } else {
        ExitCode::SUCCESS
    }
}

