/// CLI d'audit de sécurité des dépendances Rust analysant le fichier Cargo.lock.
#[derive(Parser, Debug)]
#[command(
    name = "cargo-lock-audit",
    author = "Security Engineering Team",
    version,
    about = "Audit de sécurité statique et analyse d'hygiène des dépendances pour Cargo.lock",
    long_about = "Analyse le fichier Cargo.lock d'un projet Rust pour identifier les vulnérabilités de sécurité connues,\n\
les duplications de dépendances, les sources non sécurisées et les bibliothèques obsolètes/dépréciées."
)]
struct Cli {
    /// Chemin vers le fichier Cargo.lock à auditer
    #[arg(
        short = 'l',
        long = "lockfile",
        default_value = "Cargo.lock",
        value_name = "FILE"
    )]
    lockfile: PathBuf,

    /// Format de sortie des résultats
    #[arg(
        short = 'f',
        long = "format",
        value_enum,
        default_value_t = OutputFormat::Table
    )]
    format: OutputFormat,

    /// Niveau de sévérité minimal entraînant un code de sortie d'échec (CI/CD)
    #[arg(
        long = "fail-level",
        value_enum,
        default_value_t = FailLevel::High
    )]
    fail_level: FailLevel,

    /// Chemin optionnel vers une base de données d'advisories au format JSON
    #[arg(long = "advisories", value_name = "JSON_FILE")]
    custom_advisories: Option<PathBuf>,

    /// Ignorer les duplications de dépendances dans le rapport
    #[arg(long = "ignore-duplicates")]
    ignore_duplicates: bool,

    /// Ignorer les vérifications de paquets dépréciés
    #[arg(long = "ignore-deprecated")]
    ignore_deprecated: bool,

    /// Ignorer les vérifications de sources suspectes (git/http/path non sécurisés)
    #[arg(long = "ignore-sources")]
    ignore_sources: bool,

    /// Liste d'identifiants d'avis de sécurité à ignorer (ex: RUSTSEC-2020-0071)
    #[arg(long = "ignore-id", value_name = "ID")]
    ignore_ids: Vec<String>,

    /// Autoriser la duplication pour certains paquets spécifiques
    #[arg(long = "allow-duplicate", value_name = "CRATE")]
    allow_duplicates: Vec<String>,

    /// Mode verbeux affichant le détail complet des paquets analysés
    #[arg(short = 'v', long = "verbose")]
    verbose: bool,
}

#[derive(ValueEnum, Clone, Copy, Debug, PartialEq, Eq)]
enum OutputFormat {
    Table,
    Json,
    Markdown,
    Summary,
}

#[derive(ValueEnum, Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
enum Severity {
    Informational,
    Low,
    Medium,
    High,
    Critical,
}

impl fmt::Display for Severity {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Severity::Informational => write!(f, "INFO"),
            Severity::Low => write!(f, "LOW"),
            Severity::Medium => write!(f, "MEDIUM"),
            Severity::High => write!(f, "HIGH"),
            Severity::Critical => write!(f, "CRITICAL"),
        }
    }
}

#[derive(ValueEnum, Clone, Copy, Debug, PartialEq, Eq)]
enum FailLevel {
    None,
    Low,
    Medium,
    High,
    Critical,
}

impl FailLevel {
    fn should_fail_for(&self, severity: Severity) -> bool {
        match self {
            FailLevel::None => false,
            FailLevel::Low => severity >= Severity::Low,
            FailLevel::Medium => severity >= Severity::Medium,
            FailLevel::High => severity >= Severity::High,
            FailLevel::Critical => severity >= Severity::Critical,
        }
    }
}

