#[derive(Debug, Clone, Serialize, Deserialize)]
struct SecurityAdvisory {
    id: String,
    package: String,
    title: String,
    description: String,
    severity: Severity,
    affected_version_req: String,
    patched_versions: Vec<String>,
    reference_url: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DeprecatedCrateRule {
