}

// ==========================================
// Diagnostic & Rapport
// ==========================================

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "category", rename_all = "snake_case")]
enum FindingDetail {
    SecurityVulnerability {
        advisory_id: String,
        title: String,
        affected_req: String,
        patched_versions: Vec<String>,
        reference_url: String,
    },
    DependencyDuplicate {
        total_instances: usize,
        detected_versions: Vec<String>,
    },
    SuspiciousSource {
        source: String,
        reason: String,
    },
    MissingChecksum,
    DeprecatedPackage {
        reason: String,
        suggested_alternative: String,
    },
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct AuditFinding {
    package: String,
    version: String,
    severity: Severity,
    title: String,
    detail: FindingDetail,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct AuditReport {
    target_lockfile: String,
    cargo_lock_version: Option<u32>,
    total_packages_count: usize,
    unique_packages_count: usize,
    findings: Vec<AuditFinding>,
    summary: AuditSummary,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
struct AuditSummary {
    critical_count: usize,
    high_count: usize,
    medium_count: usize,
    low_count: usize,
    info_count: usize,
    duplicate_crates_count: usize,
    vulnerabilities_count: usize,
    deprecated_count: usize,
    untrusted_source_count: usize,
}

impl AuditSummary {
    fn update_with_finding(&mut self, finding: &AuditFinding) {
        match finding.severity {
            Severity::Critical => self.critical_count += 1,
            Severity::High => self.high_count += 1,
            Severity::Medium => self.medium_count += 1,
            Severity::Low => self.low_count += 1,
            Severity::Informational => self.info_count += 1,
        }

        match &finding.detail {
            FindingDetail::SecurityVulnerability { .. } => self.vulnerabilities_count += 1,
            FindingDetail::DependencyDuplicate { .. } => self.duplicate_crates_count += 1,
            FindingDetail::DeprecatedPackage { .. } => self.deprecated_count += 1,
            FindingDetail::SuspiciousSource { .. } | FindingDetail::MissingChecksum => {
                self.untrusted_source_count += 1
            }
        }
    }
}

