// ==========================================
// Logique d'analyse & Moteur d'audit
// ==========================================

fn parse_cargo_lock<P: AsRef<Path>>(path: P) -> Result<CargoLock, anyhow::Error> {
    let content = fs::read_to_string(path.as_ref())
        .map_err(|e| anyhow::anyhow!("Impossible de lire '{}' : {}", path.as_ref().display(), e))?;

    let lock: CargoLock = toml::from_str(&content).map_err(|e| {
        anyhow::anyhow!(
            "Format Cargo.lock invalide dans '{}' : {}",
            path.as_ref().display(),
            e
        )
    })?;

    Ok(lock)
}

fn load_advisories(custom_path: Option<&Path>) -> Result<Vec<SecurityAdvisory>, anyhow::Error> {
    let mut advisories = embedded_advisories();

    if let Some(path) = custom_path {
        let content = fs::read_to_string(path).map_err(|e| {
            anyhow::anyhow!(
                "Échec de lecture des advisories '{}' : {}",
                path.display(),
                e
            )
        })?;
        let custom: Vec<SecurityAdvisory> = serde_json::from_str(&content)
            .map_err(|e| anyhow::anyhow!("JSON invalide pour le fichier d'advisories : {}", e))?;
        advisories.extend(custom);
    }

    Ok(advisories)
}

fn run_audit(lock: &CargoLock, cli: &Cli, advisories: &[SecurityAdvisory]) -> AuditReport {
    let mut findings = Vec::new();
    let deprecated_rules = embedded_deprecated_rules();

    // 1. Dépouillement des versions et comptage par paquet
    let mut package_versions: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    for pkg in &lock.packages {
        package_versions
            .entry(pkg.name.clone())
            .or_default()
            .insert(pkg.version.clone());
    }

    let total_packages_count = lock.packages.len();
    let unique_packages_count = package_versions.len();

    // 2. Détection des duplications de dépendances
    if !cli.ignore_duplicates {
        for (name, versions) in &package_versions {
            if versions.len() > 1 && !cli.allow_duplicates.contains(name) {
                let versions_list: Vec<String> = versions.iter().cloned().collect();
                findings.push(AuditFinding {
                    package: name.clone(),
                    version: versions_list.join(", "),
                    severity: Severity::Low,
                    title: format!(
                        "Dépendance dupliquée : {} versions concurrentes détectées",
                        versions.len()
                    ),
                    detail: FindingDetail::DependencyDuplicate {
                        total_instances: versions.len(),
                        detected_versions: versions_list,
                    },
                });
            }
        }
    }

    // 3. Analyse détaillée paquet par paquet
    for pkg in &lock.packages {
        let pkg_version = Version::parse(&pkg.version).ok();

        // 3.1 Vérification des vulnérabilités de sécurité
        for adv in advisories {
            if adv.package == pkg.name {
                if cli.ignore_ids.contains(&adv.id) {
                    continue;
                }

                let matches_vuln = if adv.affected_version_req == "*" {
                    true
                } else if let Some(ref parsed_ver) = pkg_version {
                    match VersionReq::parse(&adv.affected_version_req) {
                        Ok(req) => req.matches(parsed_ver),
                        Err(_) => false,
                    }
                } else {
                    false
                };

                if matches_vuln {
                    findings.push(AuditFinding {
                        package: pkg.name.clone(),
                        version: pkg.version.clone(),
                        severity: adv.severity,
                        title: format!("[{}] {}", adv.id, adv.title),
                        detail: FindingDetail::SecurityVulnerability {
                            advisory_id: adv.id.clone(),
                            title: adv.title.clone(),
                            affected_req: adv.affected_version_req.clone(),
                            patched_versions: adv.patched_versions.clone(),
                            reference_url: adv.reference_url.clone(),
                        },
                    });
                }
            }
        }

        // 3.2 Vérification des bibliothèques dépréciées
        if !cli.ignore_deprecated {
            for dep in &deprecated_rules {
                if dep.package == pkg.name {
                    // Vérification spéciale pour time : < 0.2
                    let is_deprecated = if dep.package == "time" {
                        if let Some(ref v) = pkg_version {
                            v.major == 0 && v.minor < 2
                        } else {
                            false
                        }
                    } else {
                        true
                    };

                    if is_deprecated {
                        findings.push(AuditFinding {
                            package: pkg.name.clone(),
                            version: pkg.version.clone(),
                            severity: dep.severity,
                            title: format!("Paquet déprécié ou déconseillé : {}", dep.package),
                            detail: FindingDetail::DeprecatedPackage {
                                reason: dep.reason.clone(),
                                suggested_alternative: dep.suggested_alternative.clone(),
                            },
                        });
                    }
                }
            }
        }

        // 3.3 Vérification des sources suspectes et intégrité
        if !cli.ignore_sources {
            if let Some(ref source) = pkg.source {
                if source.starts_with("git+") {
                    let is_commit_pinned = source.contains('#')
                        && source
                            .split('#')
                            .next_back()
                            .is_some_and(|rev| rev.len() == 40);
                    if !is_commit_pinned {
                        findings.push(AuditFinding {
                            package: pkg.name.clone(),
                            version: pkg.version.clone(),
                            severity: Severity::Medium,
                            title: "Source Git non épinglée sur un hash de commit immuable".to_string(),
                            detail: FindingDetail::SuspiciousSource {
                                source: source.clone(),
                                reason: "Une dépendance Git sans commit hash complet expose à des modifications non contrôlées du code source.".to_string(),
                            },
                        });
                    }
                } else if source.starts_with("http://") {
                    findings.push(AuditFinding {
                        package: pkg.name.clone(),
                        version: pkg.version.clone(),
                        severity: Severity::High,
                        title: "Source HTTP non chiffrée détectée".to_string(),
                        detail: FindingDetail::SuspiciousSource {
                            source: source.clone(),
                            reason: "Téléchargement en clair susceptible d'attaques de type Man-in-the-Middle (MitM).".to_string(),
                        },
                    });
                }
            } else if pkg.checksum.is_none() && pkg.source.is_none() {
                // Dépendance locale / workspace membre : acceptable, pas d'alerte checksum
            }

            // Manque de checksum sur un paquet tiers
            if pkg.source.is_some() && pkg.checksum.is_none() {
                findings.push(AuditFinding {
                    package: pkg.name.clone(),
                    version: pkg.version.clone(),
                    severity: Severity::Medium,
                    title: "Empreinte cryptographique (checksum) manquante".to_string(),
                    detail: FindingDetail::MissingChecksum,
                });
            }
        }
    }

    // Tri des constatations : Sévérité décroissante puis Nom de paquet
    findings.sort_by(|a, b| {
        b.severity
            .cmp(&a.severity)
            .then_with(|| a.package.cmp(&b.package))
    });

    let mut summary = AuditSummary::default();
    for finding in &findings {
        summary.update_with_finding(finding);
    }

    AuditReport {
        target_lockfile: cli.lockfile.display().to_string(),
        cargo_lock_version: lock.version,
        total_packages_count,
        unique_packages_count,
        findings,
        summary,
    }
}

