// Formats d'affichage et de restitution
// ==========================================

fn render_table(report: &AuditReport, verbose: bool) {
    println!(
        "\n{} {}",
        "==> Audit de sécurité Cargo.lock :".bold().cyan(),
        report.target_lockfile.bold()
    );

    if report.findings.is_empty() {
        println!(
            "\n{}",
            "✔ Aucune vulnérabilité ni anomalie détectée dans les dépendances."
                .bold()
                .green()
        );
    } else {
        println!(
            "\n{}",
            format!(
                "Trouvé {} problème(s) potentiel(s) :",
                report.findings.len()
            )
            .bold()
            .yellow()
        );

        let mut table = Table::new();
        table.load_preset(UTF8_FULL);
        table.apply_modifier(UTF8_ROUND_CORNERS);
        table.set_header(vec![
            Cell::new("Sévérité").set_alignment(CellAlignment::Center),
            Cell::new("Paquet"),
            Cell::new("Version"),
            Cell::new("Constat & Recommandation"),
        ]);

        for f in &report.findings {
            let (sev_str, color) = match f.severity {
                Severity::Critical => (f.severity.to_string(), Color::DarkRed),
                Severity::High => (f.severity.to_string(), Color::Red),
                Severity::Medium => (f.severity.to_string(), Color::Yellow),
                Severity::Low => (f.severity.to_string(), Color::Blue),
                Severity::Informational => (f.severity.to_string(), Color::Cyan),
            };

            let recommendation = match &f.detail {
                FindingDetail::SecurityVulnerability {
                    affected_req,
                    patched_versions,
                    reference_url,
                    ..
                } => {
                    let patches = if patched_versions.is_empty() {
                        "Aucun correctif disponible".to_string()
                    } else {
                        patched_versions.join(", ")
                    };
                    format!(
                        "{}\nAffecte : {}\nCorrectif : {}\nRéf : {}",
                        f.title, affected_req, patches, reference_url
                    )
                }
                FindingDetail::DependencyDuplicate {
                    total_instances: _,
                    detected_versions,
                } => {
                    format!(
                        "{}\nVersions : {}\nAction : Unifier les spécifications de dépendances dans Cargo.toml",
                        f.title,
                        detected_versions.join(", ")
                    )
                }
                FindingDetail::SuspiciousSource { source, reason } => {
                    format!("{}\nSource : {}\nDanger : {}", f.title, source, reason)
                }
                FindingDetail::MissingChecksum => {
                    "Absence de hachage SHA-256 dans Cargo.lock. Régénérez avec 'cargo update'."
                        .to_string()
                }
                FindingDetail::DeprecatedPackage {
                    reason,
                    suggested_alternative,
                } => {
                    format!(
                        "{}\nRaison : {}\nAlternative recommandée : {}",
                        f.title, reason, suggested_alternative
                    )
                }
            };

            table.add_row(Row::from(vec![
                Cell::new(sev_str).fg(color),
                Cell::new(&f.package).set_alignment(CellAlignment::Left),
                Cell::new(&f.version),
                Cell::new(recommendation),
            ]));
        }

        println!("{table}");
    }

    render_summary_block(
        &report.summary,
        report.total_packages_count,
        report.unique_packages_count,
    );

    if verbose {
        println!("\n{}", "--- Détails de l'environnement ---".dimmed());
        println!("Fichier analysé : {}", report.target_lockfile);
        println!(
            "Version de structure Cargo.lock : {}",
            report
                .cargo_lock_version
                .map_or("Automatique (V1-V4)".to_string(), |v| v.to_string())
        );
    }
}

fn render_summary_block(summary: &AuditSummary, total: usize, unique: usize) {
    let mut table = Table::new();
    table.load_preset(UTF8_FULL);
    table.apply_modifier(UTF8_ROUND_CORNERS);
    table.set_header(vec![
        Cell::new("Métrique d'Audit").set_alignment(CellAlignment::Left),
        Cell::new("Valeur").set_alignment(CellAlignment::Center),
    ]);

    table.add_row(Row::from(vec![
        Cell::new("Total de paquets audités"),
        Cell::new(total.to_string()),
    ]));
    table.add_row(Row::from(vec![
        Cell::new("Paquets uniques"),
        Cell::new(unique.to_string()),
    ]));
    table.add_row(Row::from(vec![
        Cell::new("Vulnérabilités de sécurité"),
        Cell::new(summary.vulnerabilities_count.to_string()).fg(
            if summary.vulnerabilities_count > 0 {
                Color::Red
            } else {
                Color::Green
            },
        ),
    ]));
    table.add_row(Row::from(vec![
        Cell::new("  - Critiques"),
        Cell::new(summary.critical_count.to_string()).fg(if summary.critical_count > 0 {
            Color::DarkRed
        } else {
            Color::Reset
        }),
    ]));
    table.add_row(Row::from(vec![
        Cell::new("  - Élevées (High)"),
        Cell::new(summary.high_count.to_string()).fg(if summary.high_count > 0 {
            Color::Red
        } else {
            Color::Reset
        }),
    ]));
    table.add_row(Row::from(vec![
        Cell::new("  - Moyennes (Medium)"),
        Cell::new(summary.medium_count.to_string()).fg(if summary.medium_count > 0 {
            Color::Yellow
        } else {
            Color::Reset
        }),
    ]));
    table.add_row(Row::from(vec![
        Cell::new("  - Faibles (Low)"),
        Cell::new(summary.low_count.to_string()),
    ]));
    table.add_row(Row::from(vec![
        Cell::new("  - Informatif (Info)"),
        Cell::new(summary.info_count.to_string()),
    ]));
    table.add_row(Row::from(vec![
        Cell::new("Dépendances dupliquées"),
        Cell::new(summary.duplicate_crates_count.to_string()),
    ]));
    table.add_row(Row::from(vec![
        Cell::new("Paquets dépréciés"),
        Cell::new(summary.deprecated_count.to_string()),
    ]));
    table.add_row(Row::from(vec![
        Cell::new("Sources suspectes ou non sécurisées"),
        Cell::new(summary.untrusted_source_count.to_string()),
    ]));

    println!("\n{}", "Synthèse globale de l'audit :".bold());
    println!("{table}");
}

fn render_markdown(report: &AuditReport) {
    println!("# Rapport d'audit de sécurité des dépendances Rust\n");
    println!("- **Fichier audité :** `{}`", report.target_lockfile);
    println!("- **Total des paquets :** {}", report.total_packages_count);
    println!("- **Paquets uniques :** {}", report.unique_packages_count);
    println!("- **Total des alertes :** {}\n", report.findings.len());

    println!("## Synthèse des vulnérabilités\n");
    println!("| Sévérité | Nombre |");
    println!("| :--- | :---: |");
    println!("| **Critical** | {} |", report.summary.critical_count);
    println!("| **High** | {} |", report.summary.high_count);
    println!("| **Medium** | {} |", report.summary.medium_count);
    println!("| **Low** | {} |", report.summary.low_count);
    println!("| **Info** | {} |\n", report.summary.info_count);

    if report.findings.is_empty() {
        println!("> ✅ **Statut : Succès.** Aucune vulnérabilité ni anomalie détectée.");
        return;
    }

    println!("## Liste détaillée des constatations\n");
    println!("| Sévérité | Paquet | Version | Problème | Recommandation |");
    println!("| :--- | :--- | :--- | :--- | :--- |");

    for f in &report.findings {
        let (problem, reco) = match &f.detail {
            FindingDetail::SecurityVulnerability {
                advisory_id,
                title,
                affected_req,
                patched_versions,
                reference_url,
            } => {
                let p = format!("[{advisory_id}] {title} (Affecte: `{affected_req}`)");
                let r = format!(
                    "Mettre à jour vers: {} ([Consulter l'avis]({}))",
                    patched_versions.join(", "),
                    reference_url
                );
                (p, r)
            }
            FindingDetail::DependencyDuplicate {
                total_instances,
                detected_versions,
            } => (
                format!("{total_instances} versions concurrentes dans l'arbre"),
                format!("Harmoniser: `{}`", detected_versions.join(", ")),
            ),
            FindingDetail::SuspiciousSource { source, reason } => {
                (format!("Source non sécurisée: `{source}`"), reason.clone())
            }
            FindingDetail::MissingChecksum => (
                "Checksum SHA-256 manquant".to_string(),
                "Exécuter `cargo update` pour rafraîchir le lockfile".to_string(),
            ),
            FindingDetail::DeprecatedPackage {
                reason,
                suggested_alternative,
            } => (
                format!("Déprécié: {reason}"),
                format!("Remplacer par: `{suggested_alternative}`"),
            ),
        };

        println!(
            "| **{}** | `{}` | `{}` | {} | {} |",
            f.severity, f.package, f.version, problem, reco
        );
    }
}

// ==========================================
// Point d'entrée principal
// ==========================================

fn main() -> ExitCode {
    let cli = Cli::parse();

    if !cli.lockfile.exists() {
        eprintln!(
            "{} Le fichier '{}' est introuvable.",
            "ERREUR :".bold().red(),
            cli.lockfile.display()
        );
        eprintln!("Indiquez un chemin valide avec l'option --lockfile <FILE>.");
        return ExitCode::from(2);
    }

    let lock = match parse_cargo_lock(&cli.lockfile) {
        Ok(l) => l,
        Err(e) => {
            eprintln!("{} {}", "ERREUR :".bold().red(), e);
            return ExitCode::from(2);
        }
    };

    let advisories = match load_advisories(cli.custom_advisories.as_deref()) {
        Ok(adv) => adv,
        Err(e) => {
            eprintln!("{} {}", "ERREUR :".bold().red(), e);
            return ExitCode::from(2);
        }
    };

    let report = run_audit(&lock, &cli, &advisories);

    match cli.format {
        OutputFormat::Table => render_table(&report, cli.verbose),
        OutputFormat::Json => match serde_json::to_string_pretty(&report) {
            Ok(json) => println!("{json}"),
            Err(e) => {
                eprintln!("Erreur de sérialisation JSON : {e}");
                return ExitCode::from(2);
            }
        },
        OutputFormat::Markdown => render_markdown(&report),
        OutputFormat::Summary => {
            render_summary_block(
                &report.summary,
                report.total_packages_count,
                report.unique_packages_count,
            );
        }
    }

    // Détermination de l'échec selon le niveau de tolérance configuré
    let mut should_fail = false;
    for finding in &report.findings {
        if cli.fail_level.should_fail_for(finding.severity) {
            should_fail = true;
            break;
        }
    }

    if should_fail {
        eprintln!(
            "\n{} Des constatations atteignant ou dépassant le seuil '{:?}' ont été détectées.",
            "ÉCHEC CI/CD :".bold().red(),
            cli.fail_level
        );
        ExitCode::from(1)
    } else {
        ExitCode::SUCCESS
    }
}

