// src/main.rs
use std::collections::HashMap;
use std::fs::{self, File};
use std::io::{BufReader, BufWriter, Read, Write};
use std::path::{Component, Path, PathBuf};

use anyhow::{bail, Context, Result};
use clap::{Parser, Subcommand, ValueEnum};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

/// Types de compression supportés pour les conteneurs d'archives TAR
#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
pub enum CompressionFormat {
    Auto,
    None,
    Gzip,
    Bzip2,
    Xz,
}

/// Sortie formatée pour les rapports d'intégrité
#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
pub enum OutputFormat {
    Sha256sum,
    Json,
}

/// Résultat d'hachage pour une entrée de fichier dans l'archive
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct FileEntryChecksum {
    pub path: String,
    pub size: u64,
    pub sha256: String,
}

/// Rapport complet généré après extraction ou inspection
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct IntegrityReport {
    pub archive: String,
    pub extracted_files: usize,
    pub total_bytes: u64,
    pub entries: Vec<FileEntryChecksum>,
}

#[derive(Parser, Debug)]
#[command(
    name = "tar-integrity-checker",
    author = "Damien",
    version = "0.1.0",
    about = "Vérificateur d'intégrité de conteneurs d'archives TAR calculant les empreintes de chaque fichier extrait",
    long_about = None
)]
pub struct Cli {
    #[command(subcommand)]
    pub command: Commands,
}

#[derive(Subcommand, Debug)]
pub enum Commands {
    /// Extrait les fichiers d'une archive TAR et calcule leurs empreintes SHA-256
    Extract {
        /// Chemin vers le fichier d'archive TAR (ou compressé .tar.gz, .tar.bz2, .tar.xz)
        #[arg(short, long)]
        archive: PathBuf,

        /// Répertoire cible pour l'extraction
        #[arg(short, long)]
        destination: PathBuf,

        /// Algorithme ou détection de compression
        #[arg(short, long, default_value = "auto")]
        compression: CompressionFormat,

        /// Format d'affichage du résultat
        #[arg(short, long, default_value = "sha256sum")]
        format: OutputFormat,

        /// Enregistrer également le manifeste généré dans un fichier
        #[arg(short, long)]
        output_manifest: Option<PathBuf>,
    },

    /// Inspecte l'archive et calcule les empreintes en streaming sans écriture sur disque
    Inspect {
        /// Chemin vers le fichier d'archive TAR
        #[arg(short, long)]
        archive: PathBuf,

        /// Algorithme ou détection de compression
        #[arg(short, long, default_value = "auto")]
        compression: CompressionFormat,

        /// Format d'affichage du résultat
        #[arg(short, long, default_value = "sha256sum")]
        format: OutputFormat,
    },

    /// Vérifie le contenu d'une archive contre un fichier manifeste existant (format sha256sum ou JSON)
    Verify {
        /// Chemin vers le fichier d'archive TAR
        #[arg(short, long)]
        archive: PathBuf,

        /// Fichier manifeste de référence (format sha256sum standard ou rapport JSON)
        #[arg(short, long)]
        manifest: PathBuf,

        /// Algorithme ou détection de compression
        #[arg(short, long, default_value = "auto")]
        compression: CompressionFormat,
    },
}

/// Détecte le type de compression à partir des octets magiques ou de l'extension
fn detect_compression(path: &Path, requested: CompressionFormat) -> Result<CompressionFormat> {
    if requested != CompressionFormat::Auto {
        return Ok(requested);
    }

    let mut file = File::open(path)
        .with_context(|| format!("Impossible d'ouvrir le fichier '{}' pour analyse", path.display()))?;
    let mut magic = [0u8; 6];
    let n = file.read(&mut magic).unwrap_or(0);

    if n >= 2 && magic[0] == 0x1f && magic[1] == 0x8b {
        return Ok(CompressionFormat::Gzip);
    }
    if n >= 3 && magic[0] == 0x42 && magic[1] == 0x5a && magic[2] == 0x68 {
        return Ok(CompressionFormat::Bzip2);
    }
    if n >= 6 && magic == [0xfd, 0x37, 0x7a, 0x58, 0x5a, 0x00] {
        return Ok(CompressionFormat::Xz);
    }

    // Détection de secours par extension
    let filename = path.file_name().and_then(|f| f.to_str()).unwrap_or("");
    if filename.ends_with(".tar.gz") || filename.ends_with(".tgz") {
        Ok(CompressionFormat::Gzip)
    } else if filename.ends_with(".tar.bz2") || filename.ends_with(".tbz2") {
        Ok(CompressionFormat::Bzip2)
    } else if filename.ends_with(".tar.xz") || filename.ends_with(".txz") {
        Ok(CompressionFormat::Xz)
    } else {
        Ok(CompressionFormat::None)
    }
}

/// Ouvre un lecteur de flux d'archive décompressé
fn open_archive_reader(path: &Path, compression: CompressionFormat) -> Result<Box<dyn Read>> {
    let file = File::open(path)
        .with_context(|| format!("Échec d'ouverture du fichier archive '{}'", path.display()))?;
    let buf_reader = BufReader::new(file);

    let reader: Box<dyn Read> = match compression {
        CompressionFormat::Auto => unreachable!("CompressionFormat::Auto doit être résolu au préalable"),
        CompressionFormat::None => Box::new(buf_reader),
        CompressionFormat::Gzip => Box::new(flate2::read::GzDecoder::new(buf_reader)),
        CompressionFormat::Bzip2 => Box::new(bzip2::read::BzDecoder::new(buf_reader)),
        CompressionFormat::Xz => Box::new(xz2::read::XzDecoder::new(buf_reader)),
    };

    Ok(reader)
}

/// Valide qu'un chemin relatif au sein d'une archive est sûr contre les attaques par traversée de répertoires
fn validate_safe_relative_path(entry_path: &Path) -> Result<PathBuf> {
    for comp in entry_path.components() {
        match comp {
            Component::ParentDir => {
                bail!(
                    "Traversée de répertoire détectée ('..') dans l'entrée : {}",
                    entry_path.display()
                );
            }
            Component::RootDir | Component::Prefix(_) => {
                bail!(
                    "Chemin absolu non autorisé dans l'entrée d'archive : {}",
                    entry_path.display()
                );
            }
            Component::Normal(_) | Component::CurDir => {}
        }
    }

    let sanitized: PathBuf = entry_path
        .components()
        .filter(|c| matches!(c, Component::Normal(_)))
        .collect();

    if sanitized.as_os_str().is_empty() {
        bail!("Chemin d'entrée de fichier vide ou non valide");
    }

    Ok(sanitized)
}

/// Extrait une archive et calcule l'empreinte SHA-256 de chaque fichier extrait
pub fn extract_and_hash(
    archive_path: &Path,
    dest_dir: &Path,
    compression: CompressionFormat,
) -> Result<IntegrityReport> {
    let resolved_compression = detect_compression(archive_path, compression)?;
    let reader = open_archive_reader(archive_path, resolved_compression)?;
    let mut archive = tar::Archive::new(reader);

    fs::create_dir_all(dest_dir).with_context(|| {
        format!(
            "Impossible de créer le répertoire de destination '{}'",
            dest_dir.display()
        )
    })?;

    let canonical_dest = dest_dir.canonicalize().with_context(|| {
        format!(
            "Impossible de canonicaliser le répertoire destination '{}'",
            dest_dir.display()
        )
    })?;

    let mut entries_report = Vec::new();
    let mut total_bytes = 0u64;

    let entries = archive
        .entries()
        .with_context(|| "Impossible d'itérer sur les entrées de l'archive TAR")?;

    for entry_result in entries {
        let mut entry = entry_result.with_context(|| "Entrée corrompue dans l'archive")?;
        let entry_type = entry.header().entry_type();
        let raw_path = entry.path().with_context(|| "Nom de fichier invalide dans l'archive")?.to_path_buf();
        let safe_rel_path = validate_safe_relative_path(&raw_path)?;

        let full_dest_path = canonical_dest.join(&safe_rel_path);

        if entry_type.is_dir() {
            fs::create_dir_all(&full_dest_path).with_context(|| {
                format!(
                    "Impossible de créer le sous-dossier '{}'",
                    full_dest_path.display()
                )
            })?;
            continue;
        }

        if entry_type.is_file() {
            if let Some(parent) = full_dest_path.parent() {
                fs::create_dir_all(parent).with_context(|| {
                    format!(
                        "Échec de création du dossier parent pour '{}'",
                        full_dest_path.display()
                    )
                })?;
            }

            let mut out_file = BufWriter::new(
                File::create(&full_dest_path).with_context(|| {
                    format!(
                        "Impossible de créer le fichier extrait '{}'",
                        full_dest_path.display()
                    )
                })?,
            );

            let mut hasher = Sha256::new();
            let mut buffer = [0u8; 32 * 1024];
            let mut file_bytes = 0u64;

            loop {
                let n = entry
                    .read(&mut buffer)
                    .with_context(|| format!("Erreur lors de la lecture de '{}'", raw_path.display()))?;
                if n == 0 {
                    break;
                }
                hasher.update(&buffer[..n]);
                out_file
                    .write_all(&buffer[..n])
                    .with_context(|| format!("Erreur d'écriture dans '{}'", full_dest_path.display()))?;
                file_bytes += n as u64;
            }

            out_file
                .flush()
                .with_context(|| format!("Erreur lors du flush de '{}'", full_dest_path.display()))?;

            let hash_hex = hex::encode(hasher.finalize());
            total_bytes += file_bytes;

            entries_report.push(FileEntryChecksum {
                path: safe_rel_path.to_string_lossy().into_owned(),
                size: file_bytes,
                sha256: hash_hex,
            });
        }
    }

    Ok(IntegrityReport {
        archive: archive_path.to_string_lossy().into_owned(),
        extracted_files: entries_report.len(),
        total_bytes,
        entries: entries_report,
    })
}

/// Inspecte une archive sans extraction sur disque et calcule les empreintes SHA-256 en streaming
pub fn inspect_and_hash(
    archive_path: &Path,
    compression: CompressionFormat,
) -> Result<IntegrityReport> {
    let resolved_compression = detect_compression(archive_path, compression)?;
    let reader = open_archive_reader(archive_path, resolved_compression)?;
    let mut archive = tar::Archive::new(reader);

    let mut entries_report = Vec::new();
    let mut total_bytes = 0u64;

    let entries = archive
        .entries()
        .with_context(|| "Impossible d'itérer sur les entrées de l'archive TAR")?;

    for entry_result in entries {
        let mut entry = entry_result.with_context(|| "Entrée corrompue dans l'archive")?;
        let entry_type = entry.header().entry_type();
        let raw_path = entry.path().with_context(|| "Nom de fichier invalide dans l'archive")?.to_path_buf();
        let safe_rel_path = validate_safe_relative_path(&raw_path)?;

        if entry_type.is_file() {
            let mut hasher = Sha256::new();
            let mut buffer = [0u8; 32 * 1024];
            let mut file_bytes = 0u64;

            loop {
                let n = entry
                    .read(&mut buffer)
                    .with_context(|| format!("Erreur lors de la lecture de '{}'", raw_path.display()))?;
                if n == 0 {
                    break;
                }
                hasher.update(&buffer[..n]);
                file_bytes += n as u64;
            }

            let hash_hex = hex::encode(hasher.finalize());
            total_bytes += file_bytes;

            entries_report.push(FileEntryChecksum {
                path: safe_rel_path.to_string_lossy().into_owned(),
                size: file_bytes,
                sha256: hash_hex,
            });
        }
    }

    Ok(IntegrityReport {
        archive: archive_path.to_string_lossy().into_owned(),
        extracted_files: entries_report.len(),
        total_bytes,
        entries: entries_report,
    })
}

/// Charge un fichier de référence soit au format JSON (`IntegrityReport`), soit au format standard sha256sum
fn load_reference_manifest(manifest_path: &Path) -> Result<HashMap<String, String>> {
    let content = fs::read_to_string(manifest_path)
        .with_context(|| format!("Impossible de lire le manifeste '{}'", manifest_path.display()))?;

    // Tentative 1 : Format JSON
    if let Ok(report) = serde_json::from_str::<IntegrityReport>(&content) {
        let map = report
            .entries
            .into_iter()
            .map(|e| (e.path, e.sha256.to_lowercase()))
            .collect();
        return Ok(map);
    }

    // Tentative 2 : Format sha256sum classique
    let mut map = HashMap::new();
    for (line_idx, line) in content.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }

        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() < 2 {
            bail!(
                "Ligne {} non reconnue dans le manifeste '{}' : {}",
                line_idx + 1,
                manifest_path.display(),
                line
            );
        }

        let hash = parts[0].to_lowercase();
        // Concaténation sécurisée si le chemin comporte des espaces
        let path = parts[1..].join(" ");
        let cleaned_path = path.trim_start_matches("./").trim_start_matches('*');
        map.insert(cleaned_path.to_string(), hash);
    }

    if map.is_empty() {
        bail!(
            "Aucune empreinte valide n'a pu être extraite du manifeste '{}'",
            manifest_path.display()
        );
    }

    Ok(map)
}

/// Affiche un rapport d'intégrité selon le format demandé
fn render_report(report: &IntegrityReport, format: OutputFormat) -> Result<String> {
    match format {
        OutputFormat::Json => {
            serde_json::to_string_pretty(report).context("Échec de sérialisation JSON")
        }
        OutputFormat::Sha256sum => {
            let mut out = String::new();
            for entry in &report.entries {
                out.push_str(&format!("{}  {}\n", entry.sha256, entry.path));
            }
            Ok(out)
        }
    }
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Extract {
            archive,
            destination,
            compression,
            format,
            output_manifest,
        } => {
            let report = extract_and_hash(&archive, &destination, compression)?;
            let rendered = render_report(&report, format)?;
            print!("{}", rendered);

            if let Some(manifest_file) = output_manifest {
                fs::write(&manifest_file, &rendered).with_context(|| {
                    format!(
                        "Impossible d'écrire le manifeste vers '{}'",
                        manifest_file.display()
                    )
                })?;
                eprintln!(
                    "\n[SUCCÈS] Manifeste écrit dans : {}",
                    manifest_file.display()
                );
            }
            eprintln!(
                "[INFO] {} fichier(s) extrait(s) et vérifié(s) (total: {} octets) vers '{}'.",
                report.extracted_files,
                report.total_bytes,
                destination.display()
            );
        }

        Commands::Inspect {
            archive,
            compression,
            format,
        } => {
            let report = inspect_and_hash(&archive, compression)?;
            let rendered = render_report(&report, format)?;
            print!("{}", rendered);
            eprintln!(
                "[INFO] Inspection terminée: {} fichier(s), {} octets.",
                report.extracted_files, report.total_bytes
            );
        }

        Commands::Verify {
            archive,
            manifest,
            compression,
        } => {
            let expected_hashes = load_reference_manifest(&manifest)?;
            let report = inspect_and_hash(&archive, compression)?;

            let mut actual_map = HashMap::new();
            for item in report.entries {
                actual_map.insert(item.path, item.sha256.to_lowercase());
            }

            let mut all_match = true;
            let mut checked_count = 0;

            for (expected_path, expected_hash) in &expected_hashes {
                checked_count += 1;
                match actual_map.get(expected_path) {
                    Some(actual_hash) => {
                        if actual_hash == expected_hash {
                            println!("{}: RÉUSSI", expected_path);
                        } else {
                            eprintln!(
                                "{}: ÉCHEC (attendu: {}, calculé: {})",
                                expected_path, expected_hash, actual_hash
                            );
                            all_match = false;
                        }
                    }
                    None => {
                        eprintln!("{}: MANQUANT dans l'archive", expected_path);
                        all_match = false;
                    }
                }
            }

            for actual_path in actual_map.keys() {
                if !expected_hashes.contains_key(actual_path) {
                    eprintln!("{}: NON RÉPERTORIÉ dans le manifeste", actual_path);
                    all_match = false;
                }
            }

            if !all_match {
                bail!("L'intégrité de l'archive n'a pas pu être validée par rapport au manifeste.");
            }

            println!("\n[SUCCÈS] Tous les {} fichiers correspondent à leur empreinte de référence !", checked_count);
        }
    }

    Ok(())
}

