/// Détecte le type de compression à partir des octets magiques ou de l'extension
fn detect_compression(path: &Path, requested: CompressionFormat) -> Result<CompressionFormat> {
    if requested != CompressionFormat::Auto {
        return Ok(requested);
    }

    let mut file = File::open(path)
        .with_context(|| format!("Impossible d'ouvrir le fichier '{}' pour analyse", path.display()))?;
    let mut magic = [0u8; 6];
    let n = file.read(&mut magic).unwrap_or(0);

    if n >= 2 && magic[0] == 0x1f && magic[1] == 0x8b {
        return Ok(CompressionFormat::Gzip);
    }
    if n >= 3 && magic[0] == 0x42 && magic[1] == 0x5a && magic[2] == 0x68 {
        return Ok(CompressionFormat::Bzip2);
    }
    if n >= 6 && magic == [0xfd, 0x37, 0x7a, 0x58, 0x5a, 0x00] {
        return Ok(CompressionFormat::Xz);
    }

    // Détection de secours par extension
    let filename = path.file_name().and_then(|f| f.to_str()).unwrap_or("");
    if filename.ends_with(".tar.gz") || filename.ends_with(".tgz") {
        Ok(CompressionFormat::Gzip)
    } else if filename.ends_with(".tar.bz2") || filename.ends_with(".tbz2") {
        Ok(CompressionFormat::Bzip2)
    } else if filename.ends_with(".tar.xz") || filename.ends_with(".txz") {
        Ok(CompressionFormat::Xz)
    } else {
        Ok(CompressionFormat::None)
    }
}

/// Ouvre un lecteur de flux d'archive décompressé
fn open_archive_reader(path: &Path, compression: CompressionFormat) -> Result<Box<dyn Read>> {
    let file = File::open(path)
        .with_context(|| format!("Échec d'ouverture du fichier archive '{}'", path.display()))?;
    let buf_reader = BufReader::new(file);

    let reader: Box<dyn Read> = match compression {
        CompressionFormat::Auto => unreachable!("CompressionFormat::Auto doit être résolu au préalable"),
        CompressionFormat::None => Box::new(buf_reader),
        CompressionFormat::Gzip => Box::new(flate2::read::GzDecoder::new(buf_reader)),
        CompressionFormat::Bzip2 => Box::new(bzip2::read::BzDecoder::new(buf_reader)),
        CompressionFormat::Xz => Box::new(xz2::read::XzDecoder::new(buf_reader)),
    };

    Ok(reader)
}

/// Valide qu'un chemin relatif au sein d'une archive est sûr contre les attaques par traversée de répertoires
fn validate_safe_relative_path(entry_path: &Path) -> Result<PathBuf> {
    for comp in entry_path.components() {
        match comp {
            Component::ParentDir => {
                bail!(
                    "Traversée de répertoire détectée ('..') dans l'entrée : {}",
                    entry_path.display()
                );
            }
            Component::RootDir | Component::Prefix(_) => {
                bail!(
                    "Chemin absolu non autorisé dans l'entrée d'archive : {}",
                    entry_path.display()
                );
            }
            Component::Normal(_) | Component::CurDir => {}
        }
    }

    let sanitized: PathBuf = entry_path
        .components()
        .filter(|c| matches!(c, Component::Normal(_)))
        .collect();

    if sanitized.as_os_str().is_empty() {
        bail!("Chemin d'entrée de fichier vide ou non valide");
    }

    Ok(sanitized)
}

/// Extrait une archive et calcule l'empreinte SHA-256 de chaque fichier extrait
pub fn extract_and_hash(
    archive_path: &Path,
    dest_dir: &Path,
    compression: CompressionFormat,
) -> Result<IntegrityReport> {
    let resolved_compression = detect_compression(archive_path, compression)?;
    let reader = open_archive_reader(archive_path, resolved_compression)?;
    let mut archive = tar::Archive::new(reader);

    fs::create_dir_all(dest_dir).with_context(|| {
        format!(
            "Impossible de créer le répertoire de destination '{}'",
            dest_dir.display()
        )
    })?;

    let canonical_dest = dest_dir.canonicalize().with_context(|| {
        format!(
            "Impossible de canonicaliser le répertoire destination '{}'",
            dest_dir.display()
        )
    })?;

    let mut entries_report = Vec::new();
    let mut total_bytes = 0u64;

    let entries = archive
        .entries()
        .with_context(|| "Impossible d'itérer sur les entrées de l'archive TAR")?;

    for entry_result in entries {
        let mut entry = entry_result.with_context(|| "Entrée corrompue dans l'archive")?;
        let entry_type = entry.header().entry_type();
        let raw_path = entry.path().with_context(|| "Nom de fichier invalide dans l'archive")?.to_path_buf();
        let safe_rel_path = validate_safe_relative_path(&raw_path)?;

        let full_dest_path = canonical_dest.join(&safe_rel_path);

        if entry_type.is_dir() {
            fs::create_dir_all(&full_dest_path).with_context(|| {
                format!(
                    "Impossible de créer le sous-dossier '{}'",
                    full_dest_path.display()
                )
            })?;
            continue;
        }

        if entry_type.is_file() {
            if let Some(parent) = full_dest_path.parent() {
                fs::create_dir_all(parent).with_context(|| {
                    format!(
                        "Échec de création du dossier parent pour '{}'",
                        full_dest_path.display()
                    )
                })?;
            }

            let mut out_file = BufWriter::new(
                File::create(&full_dest_path).with_context(|| {
                    format!(
                        "Impossible de créer le fichier extrait '{}'",
                        full_dest_path.display()
                    )
                })?,
            );

            let mut hasher = Sha256::new();
            let mut buffer = [0u8; 32 * 1024];
            let mut file_bytes = 0u64;

            loop {
                let n = entry
                    .read(&mut buffer)
                    .with_context(|| format!("Erreur lors de la lecture de '{}'", raw_path.display()))?;
                if n == 0 {
                    break;
                }
                hasher.update(&buffer[..n]);
                out_file
                    .write_all(&buffer[..n])
                    .with_context(|| format!("Erreur d'écriture dans '{}'", full_dest_path.display()))?;
                file_bytes += n as u64;
            }

            out_file
                .flush()
                .with_context(|| format!("Erreur lors du flush de '{}'", full_dest_path.display()))?;

            let hash_hex = hex::encode(hasher.finalize());
            total_bytes += file_bytes;

            entries_report.push(FileEntryChecksum {
                path: safe_rel_path.to_string_lossy().into_owned(),
                size: file_bytes,
                sha256: hash_hex,
            });
        }
    }

    Ok(IntegrityReport {
        archive: archive_path.to_string_lossy().into_owned(),
        extracted_files: entries_report.len(),
        total_bytes,
        entries: entries_report,
    })
}

/// Inspecte une archive sans extraction sur disque et calcule les empreintes SHA-256 en streaming
pub fn inspect_and_hash(
    archive_path: &Path,
