        let mut entry = entry_result.with_context(|| "Entrée corrompue dans l'archive")?;
        let entry_type = entry.header().entry_type();
        let raw_path = entry.path().with_context(|| "Nom de fichier invalide dans l'archive")?.to_path_buf();
        let safe_rel_path = validate_safe_relative_path(&raw_path)?;

        if entry_type.is_file() {
            let mut hasher = Sha256::new();
            let mut buffer = [0u8; 32 * 1024];
            let mut file_bytes = 0u64;

            loop {
                let n = entry
                    .read(&mut buffer)
                    .with_context(|| format!("Erreur lors de la lecture de '{}'", raw_path.display()))?;
                if n == 0 {
                    break;
                }
                hasher.update(&buffer[..n]);
                file_bytes += n as u64;
            }

            let hash_hex = hex::encode(hasher.finalize());
            total_bytes += file_bytes;

            entries_report.push(FileEntryChecksum {
                path: safe_rel_path.to_string_lossy().into_owned(),
                size: file_bytes,
                sha256: hash_hex,
            });
        }
    }

    Ok(IntegrityReport {
        archive: archive_path.to_string_lossy().into_owned(),
        extracted_files: entries_report.len(),
        total_bytes,
        entries: entries_report,
    })
}

/// Charge un fichier de référence soit au format JSON (`IntegrityReport`), soit au format standard sha256sum
fn load_reference_manifest(manifest_path: &Path) -> Result<HashMap<String, String>> {
    let content = fs::read_to_string(manifest_path)
