    Ok(map)
}

/// Affiche un rapport d'intégrité selon le format demandé
fn render_report(report: &IntegrityReport, format: OutputFormat) -> Result<String> {
    match format {
        OutputFormat::Json => {
            serde_json::to_string_pretty(report).context("Échec de sérialisation JSON")
        }
