            compression,
        } => {
            let expected_hashes = load_reference_manifest(&manifest)?;
            let report = inspect_and_hash(&archive, compression)?;

            let mut actual_map = HashMap::new();
            for item in report.entries {
                actual_map.insert(item.path, item.sha256.to_lowercase());
            }

            let mut all_match = true;
            let mut checked_count = 0;

            for (expected_path, expected_hash) in &expected_hashes {
                checked_count += 1;
                match actual_map.get(expected_path) {
                    Some(actual_hash) => {
                        if actual_hash == expected_hash {
                            println!("{}: RÉUSSI", expected_path);
                        } else {
                            eprintln!(
                                "{}: ÉCHEC (attendu: {}, calculé: {})",
                                expected_path, expected_hash, actual_hash
                            );
                            all_match = false;
                        }
                    }
                    None => {
                        eprintln!("{}: MANQUANT dans l'archive", expected_path);
                        all_match = false;
                    }
                }
            }

            for actual_path in actual_map.keys() {
                if !expected_hashes.contains_key(actual_path) {
                    eprintln!("{}: NON RÉPERTORIÉ dans le manifeste", actual_path);
                    all_match = false;
                }
            }

            if !all_match {
                bail!("L'intégrité de l'archive n'a pas pu être validée par rapport au manifeste.");
            }

            println!("\n[SUCCÈS] Tous les {} fichiers correspondent à leur empreinte de référence !", checked_count);
        }
    }

    Ok(())
}

#[cfg(test)]
mod tests {
