    use tempfile::tempdir;

    fn create_sample_tar_file(path: &Path) -> Result<()> {
        let file = File::create(path)?;
        let mut builder = tar::Builder::new(file);

        let data1 = b"Bonjour le monde! Rust integrity test.";
        let mut header1 = tar::Header::new_gnu();
        header1.set_size(data1.len() as u64);
        header1.set_mode(0o644);
        header1.set_cksum();
        builder.append_data(&mut header1, "hello.txt", &data1[..])?;

        let data2 = b"Contenu du sous dossier.";
        let mut header2 = tar::Header::new_gnu();
        header2.set_size(data2.len() as u64);
        header2.set_mode(0o644);
        header2.set_cksum();
        builder.append_data(&mut header2, "sub/nested.txt", &data2[..])?;

        builder.finish()?;
        Ok(())
    }

    #[test]
    fn test_extract_and_hash_roundtrip() -> Result<()> {
        let dir = tempdir()?;
        let archive_path = dir.path().join("test.tar");
        let dest_dir = dir.path().join("extracted");

        create_sample_tar_file(&archive_path)?;

        let report = extract_and_hash(&archive_path, &dest_dir, CompressionFormat::None)?;
        assert_eq!(report.extracted_files, 2);

