        assert!(file1_extracted.exists());
        let content1 = fs::read(&file1_extracted)?;
        assert_eq!(content1, b"Bonjour le monde! Rust integrity test.");

        let file2_extracted = dest_dir.join("sub/nested.txt");
        assert!(file2_extracted.exists());

        // Calcul indépendant du sha256 de hello.txt
        let mut hasher = Sha256::new();
        hasher.update(b"Bonjour le monde! Rust integrity test.");
        let expected_hash = hex::encode(hasher.finalize());

        let entry = report.entries.iter().find(|e| e.path == "hello.txt").unwrap();
        assert_eq!(entry.sha256, expected_hash);

        Ok(())
    }

