        let malicious_path = Path::new("../evil.txt");
        assert!(validate_safe_relative_path(malicious_path).is_err());

        let absolute_path = Path::new("/etc/passwd");
        assert!(validate_safe_relative_path(absolute_path).is_err());

        let valid_path = Path::new("sub/folder/file.txt");
        assert!(validate_safe_relative_path(valid_path).is_ok());
    }
