}

/// Chiffre un message en clair avec un nonce aléatoire
fn encrypt_payload(key: &Key, plaintext: &[u8]) -> Result<(Nonce, Vec<u8>), IpcCipherError> {
    let cipher = ChaCha20Poly1305::new(key);
    let mut nonce_bytes = [0u8; NONCE_SIZE];
    rand::thread_rng().fill_bytes(&mut nonce_bytes);
    let nonce = Nonce::from_slice(&nonce_bytes);

    let ciphertext = cipher
        .encrypt(nonce, plaintext)
        .map_err(|_| IpcCipherError::DecryptionFailed)?;

    Ok((*nonce, ciphertext))
}

/// Déchiffre un ciphertext avec un nonce et une clé
fn decrypt_payload(key: &Key, nonce_bytes: &[u8], ciphertext: &[u8]) -> Result<Vec<u8>, IpcCipherError> {
    if nonce_bytes.len() != NONCE_SIZE {
        return Err(IpcCipherError::FramingError);
    }
    let cipher = ChaCha20Poly1305::new(key);
    let nonce = Nonce::from_slice(nonce_bytes);

    cipher
        .decrypt(nonce, ciphertext)
        .map_err(|_| IpcCipherError::DecryptionFailed)
}

/// Écoute sur un socket de domaine Unix et déchiffre les trames
async fn run_uds_listen(socket_path: &Path, key: &Key) -> Result<(), IpcCipherError> {
    if socket_path.exists() {
        let _ = std::fs::remove_file(socket_path);
    }

    let listener = UnixListener::bind(socket_path)?;
    info!("Écoute UDS démarrée sur {:?}", socket_path);

    loop {
        match listener.accept().await {
            Ok((mut stream, _)) => {
                let key_clone = *key;
                tokio::spawn(async move {
                    if let Err(e) = handle_uds_client(&mut stream, &key_clone).await {
                        warn!("Erreur lors du traitement d'une connexion UDS: {}", e);
                    }
                });
            }
            Err(e) => {
                error!("Erreur d'acceptation UDS: {}", e);
                break;
            }
        }
    }

    Ok(())
}

/// Traite un client UDS connecté : lit la trame [Nonce:12][Len:4][Ciphertext:Len]
async fn handle_uds_client(stream: &mut UnixStream, key: &Key) -> Result<(), IpcCipherError> {
    let mut nonce = [0u8; NONCE_SIZE];
    if stream.read_exact(&mut nonce).await.is_err() {
        return Ok(());
    }

    let mut len_bytes = [0u8; 4];
    stream.read_exact(&mut len_bytes).await?;
    let payload_len = u32::from_be_bytes(len_bytes) as usize;

    if payload_len < TAG_SIZE || payload_len > 16 * 1024 * 1024 {
        return Err(IpcCipherError::FramingError);
    }

    let mut ciphertext = vec![0u8; payload_len];
    stream.read_exact(&mut ciphertext).await?;

    let plaintext = decrypt_payload(key, &nonce, &ciphertext)?;
    let decoded_str = String::from_utf8_lossy(&plaintext);
    println!("[UDS RECV] Message déchiffré: {}", decoded_str);

    // Envoi d'un accusé de réception optionnel
    stream.write_all(b"ACK\n").await?;
    stream.flush().await?;
    Ok(())
}

/// Envoie un message chiffré sur un socket Unix
async fn run_uds_send(socket_path: &Path, key: &Key, message: &str) -> Result<(), IpcCipherError> {
    let mut stream = UnixStream::connect(socket_path).await?;
    let (nonce, ciphertext) = encrypt_payload(key, message.as_bytes())?;

    let len_bytes = (ciphertext.len() as u32).to_be_bytes();

    stream.write_all(nonce.as_slice()).await?;
    stream.write_all(&len_bytes).await?;
    stream.write_all(&ciphertext).await?;
    stream.flush().await?;

    let mut response = [0u8; 4];
    if let Ok(n) = stream.read(&mut response).await {
        if n > 0 {
            let resp = String::from_utf8_lossy(&response[..n]);
            info!("Réponse du récepteur: {}", resp.trim());
        }
    }

    println!("[UDS SENT] Trame chiffrée émise avec succès.");
    Ok(())
}

/// Initialise ou étend un fichier de mémoire partagée
fn prepare_shm_file(path: &Path, min_size: usize) -> Result<MmapMut, IpcCipherError> {
    let file = OpenOptions::new()
        .read(true)
        .write(true)
        .create(true)
        .open(path)?;

    let current_len = file.metadata()?.len();
    if current_len < min_size as u64 {
        file.set_len(min_size as u64)?;
    }

    let mmap = unsafe { MmapMut::map_mut(&file)? };
    Ok(mmap)
}

/// Écrit des données chiffrées dans un segment SHM
fn run_shm_write(path: &Path, key: &Key, message: &str) -> Result<(), IpcCipherError> {
    let (nonce, ciphertext) = encrypt_payload(key, message.as_bytes())?;
    let required_size = HEADER_SIZE + ciphertext.len();
    let total_size = DEFAULT_SHM_SIZE.max(required_size);

    let mut mmap = prepare_shm_file(path, total_size)?;

    if required_size > mmap.len() {
        return Err(IpcCipherError::ShmBufferOverflow);
    }

    // Écriture du buffer :
    // Header : [status=0x00][pad:3][nonce:12][payload_len:4]
    mmap[0] = STATUS_EMPTY; // Marqué temporairement vide pendant l'écriture
    mmap[1..4].copy_from_slice(&[0u8; 3]);
    mmap[4..16].copy_from_slice(nonce.as_slice());

    let len_be = (ciphertext.len() as u32).to_be_bytes();
    mmap[16..20].copy_from_slice(&len_be);

    // Payload
    mmap[HEADER_SIZE..HEADER_SIZE + ciphertext.len()].copy_from_slice(&ciphertext);

    // Publication : passer le flag à READY
    mmap[0] = STATUS_READY;
    mmap.flush()?;

    println!("[SHM WRITE] {} octets chiffrés écrits dans {:?}", ciphertext.len(), path);
    Ok(())
}

/// Lit et déchiffre les données depuis un segment SHM
fn run_shm_read(path: &Path, key: &Key, timeout_ms: u64) -> Result<(), IpcCipherError> {
    let mut mmap = prepare_shm_file(path, HEADER_SIZE)?;
    let start = std::time::Instant::now();
    let timeout = Duration::from_millis(timeout_ms);

    loop {
        let status = mmap[0];
        if status == STATUS_READY {
            let nonce_bytes = &mmap[4..16];
            let payload_len = u32::from_be_bytes(mmap[16..20].try_into().unwrap_or([0; 4])) as usize;

            if HEADER_SIZE + payload_len > mmap.len() {
                return Err(IpcCipherError::FramingError);
            }

            let ciphertext = &mmap[HEADER_SIZE..HEADER_SIZE + payload_len];
            let plaintext = decrypt_payload(key, nonce_bytes, ciphertext)?;

            println!("[SHM READ] Message déchiffré: {}", String::from_utf8_lossy(&plaintext));

            // Marquer comme lu
            mmap[0] = STATUS_READ;
            mmap.flush()?;
            return Ok(());
        }

        if timeout_ms == 0 || start.elapsed() >= timeout {
            return Err(IpcCipherError::Timeout);
        }

        std::thread::sleep(Duration::from_millis(20));
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    tracing_subscriber::fmt::init();
    let cli = Cli::parse();

    match cli.command {
        Commands::Keygen => {
            let mut key_bytes = [0u8; 32];
            rand::thread_rng().fill_bytes(&mut key_bytes);
            println!("{}", hex::encode(key_bytes));
        }
        Commands::Uds(uds_args) => match uds_args.mode {
            UdsMode::Listen { socket, key } => {
                let parsed_key = parse_key(&key)?;
                run_uds_listen(&socket, &parsed_key).await?;
            }
            UdsMode::Send { socket, key, message } => {
                let parsed_key = parse_key(&key)?;
                run_uds_send(&socket, &parsed_key, &message).await?;
            }
        },
        Commands::Shm(shm_args) => match shm_args.mode {
            ShmMode::Write { path, key, message } => {
                let parsed_key = parse_key(&key)?;
                run_shm_write(&path, &parsed_key, &message)?;
            }
            ShmMode::Read { path, key, timeout_ms } => {
                let parsed_key = parse_key(&key)?;
                run_shm_read(&path, &parsed_key, timeout_ms)?;
            }
        },
    }

    Ok(())
}

