// src/main.rs
use anyhow::{Context, Result};
use clap::{Parser, Subcommand, ValueEnum};
use image::imageops::FilterType;
use rayon::prelude::*;
use serde::Serialize;
use std::f64::consts::PI;
use std::fmt;
use std::path::{Path, PathBuf};
use walkdir::WalkDir;

/// Type d'algorithme de hachage perceptuel disponible.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, ValueEnum, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum HashAlgorithm {
    /// Average Hash : rapide, basé sur la moyenne globale des intensités.
    Ahash,
    /// Difference Hash : basé sur le gradient horizontal entre pixels adjacents.
    Dhash,
    /// Perceptual Hash : basé sur la DCT (Discrete Cosine Transform) 2D basse fréquence.
    Phash,
}

impl fmt::Display for HashAlgorithm {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Ahash => write!(f, "ahash"),
            Self::Dhash => write!(f, "dhash"),
            Self::Phash => write!(f, "phash"),
        }
    }
}

/// Empreinte perceptuelle 64 bits.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize)]
pub struct ImageHash {
    pub value: u64,
    pub algorithm: HashAlgorithm,
}

impl ImageHash {
    pub fn new(value: u64, algorithm: HashAlgorithm) -> Self {
        Self { value, algorithm }
    }

    /// Calcule la distance de Hamming (nombre de bits différents).
    pub fn hamming_distance(&self, other: &Self) -> u32 {
        (self.value ^ other.value).count_ones()
    }

    /// Calcule un ratio de similarité visuelle normalisé entre 0.0 et 1.0 (ou 0% à 100%).
    pub fn similarity(&self, other: &Self) -> f64 {
        let dist = self.hamming_distance(other);
        1.0 - (dist as f64 / 64.0)
    }

    /// Formate l'empreinte en chaîne hexadécimale 16 caractères.
    pub fn to_hex(&self) -> String {
        format!("{:016x}", self.value)
    }
}

impl fmt::Display for ImageHash {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{:016x}", self.value)
    }
}

// ----------------------------------------------------------------------------
// Implémentation des algorithmes de hachage
// ----------------------------------------------------------------------------

/// Calcule le hachage d'une image selon l'algorithme choisi.
pub fn compute_hash(img: &image::DynamicImage, algorithm: HashAlgorithm) -> ImageHash {
    let value = match algorithm {
        HashAlgorithm::Ahash => compute_ahash(img),
        HashAlgorithm::Dhash => compute_dhash(img),
        HashAlgorithm::Phash => compute_phash(img),
    };
    ImageHash::new(value, algorithm)
}

/// aHash (Average Hash):
/// 1. Réduit à 8x8 en niveaux de gris.
/// 2. Calcule la moyenne des intensités de pixels.
/// 3. Met le bit à 1 si >= moyenne, sinon 0.
fn compute_ahash(img: &image::DynamicImage) -> u64 {
    let resized = img.resize_exact(8, 8, FilterType::Lanczos3).to_luma8();
    let sum: u32 = resized.iter().map(|&p| p as u32).sum();
    let mean = (sum / 64) as u8;

    let mut hash: u64 = 0;
    for &p in resized.iter() {
        hash = (hash << 1) | if p >= mean { 1 } else { 0 };
    }
    hash
}

/// dHash (Difference Hash / Gradient):
/// 1. Réduit à 9x8 en niveaux de gris.
/// 2. Compare chaque pixel avec son voisin de droite (8 colonnes de différences sur 8 lignes = 64 bits).
fn compute_dhash(img: &image::DynamicImage) -> u64 {
    let resized = img.resize_exact(9, 8, FilterType::Lanczos3).to_luma8();
    let mut hash: u64 = 0;

    for y in 0..8 {
        for x in 0..8 {
            let left = resized.get_pixel(x, y)[0];
            let right = resized.get_pixel(x + 1, y)[0];
            hash = (hash << 1) | if left > right { 1 } else { 0 };
        }
    }
    hash
}

/// pHash (Perceptual Hash via Discrete Cosine Transform):
/// 1. Réduit à 32x32 en niveaux de gris.
/// 2. Calcule la DCT-II 2D.
/// 3. Extrait le sous-bloc basse fréquence 8x8 (excluant le terme DC [0,0]).
/// 4. Seuil par rapport à la médiane du sous-bloc.
fn compute_phash(img: &image::DynamicImage) -> u64 {
    const N: usize = 32;
    let resized = img.resize_exact(N as u32, N as u32, FilterType::Lanczos3).to_luma8();

    // 1. Matrice des intensités en virgule flottante
    let mut grid = [[0.0f64; N]; N];
    for y in 0..N {
        for x in 0..N {
            grid[y][x] = resized.get_pixel(x as u32, y as u32)[0] as f64;
        }
    }

    // 2. DCT-II 2D séparable (lignes puis colonnes)
    let mut dct_rows = [[0.0f64; N]; N];
    let c = |u: usize| -> f64 {
        if u == 0 {
            1.0 / (2.0f64).sqrt()
        } else {
            1.0
        }
    };

    // DCT sur chaque ligne
    for y in 0..N {
        for u in 0..N {
            let mut sum = 0.0;
            for x in 0..N {
                let angle = ((2 * x + 1) as f64 * u as f64 * PI) / (2.0 * N as f64);
                sum += grid[y][x] * angle.cos();
            }
            dct_rows[y][u] = 0.5 * c(u) * sum;
        }
    }

    // DCT sur chaque colonne du résultat
    let mut dct = [[0.0f64; 8]; 8];
    for v in 0..8 {
        for u in 0..8 {
            let mut sum = 0.0;
            for y in 0..N {
                let angle = ((2 * y + 1) as f64 * v as f64 * PI) / (2.0 * N as f64);
                sum += dct_rows[y][u] * angle.cos();
            }
            dct[v][u] = 0.5 * c(v) * sum;
        }
    }

    // 3. Extraire le bloc basse fréquence 8x8 (excluant le coefficient DC dct[0][0])
    let mut low_freq = Vec::with_capacity(64);
    for v in 0..8 {
        for u in 0..8 {
            low_freq.push(dct[v][u]);
        }
    }

    // Calcul de la médiane sans le coefficient DC (low_freq[0])
    let mut vals: Vec<f64> = low_freq[1..].to_vec();
    vals.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let median = if vals.len() % 2 == 0 {
        (vals[vals.len() / 2 - 1] + vals[vals.len() / 2]) / 2.0
    } else {
        vals[vals.len() / 2]
    };

    // 4. Générer le hash 64 bits
    let mut hash: u64 = 0;
    for &val in &low_freq {
        hash = (hash << 1) | if val > median { 1 } else { 0 };
    }
    hash
}

// ----------------------------------------------------------------------------
// Types de résultats CLI & Sérialisation
// ----------------------------------------------------------------------------

#[derive(Serialize)]
struct HashOutput {
    path: String,
    algorithm: HashAlgorithm,
    hash: String,
    hash_u64: u64,
}

#[derive(Serialize)]
struct CompareOutput {
    image1: String,
    image2: String,
    algorithm: HashAlgorithm,
    hash1: String,
    hash2: String,
    hamming_distance: u32,
    similarity_percent: f64,
    is_match: bool,
}

#[derive(Serialize)]
struct DuplicateGroup {
    primary: String,
    primary_hash: String,
    matches: Vec<DuplicateMatch>,
}

#[derive(Serialize)]
struct DuplicateMatch {
    path: String,
    hash: String,
    distance: u32,
    similarity_percent: f64,
}

// ----------------------------------------------------------------------------
// CLI Arguments
// ----------------------------------------------------------------------------

#[derive(Parser, Debug)]
#[command(
    name = "img-phash",
    about = "CLI performant de calcul d'empreintes perceptuelles (Perceptual Hashing) pour images.",
    version
)]
struct Cli {
    #[arg(short, long, value_enum, default_value = "phash", global = true)]
    algo: HashAlgorithm,

    #[arg(short, long, global = true, help = "Format de sortie en JSON")]
    json: bool,

    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Calcule et affiche l'empreinte perceptuelle d'une ou plusieurs images.
    Hash {
        #[arg(required = true, num_args = 1.., help = "Chemins des images à hacher")]
        paths: Vec<PathBuf>,
    },

    /// Compare visuellement deux images et affiche leur distance de Hamming et similarité.
    Compare {
        #[arg(help = "Chemin de la première image")]
        image1: PathBuf,

        #[arg(help = "Chemin de la seconde image")]
        image2: PathBuf,

        #[arg(
            short,
            long,
            default_value_t = 10,
            help = "Distance de Hamming maximale pour considérer les images comme similaires (0-64)"
        )]
        threshold: u32,
    },

    /// Analyse récursivement un dossier pour détecter les doublons ou images visuellement proches.
    Scan {
        #[arg(help = "Dossier racine à analyser")]
        dir: PathBuf,

        #[arg(
            short,
            long,
            default_value_t = 10,
            help = "Distance de Hamming maximale pour regrouper les doublons (0-64)"
        )]
        threshold: u32,
    },
}

// ----------------------------------------------------------------------------
// Fonctions utilitaires
// ----------------------------------------------------------------------------

fn is_supported_image(path: &Path) -> bool {
    let ext = match path.extension().and_then(|e| e.to_str()) {
        Some(e) => e.to_ascii_lowercase(),
        None => return false,
    };
    matches!(
        ext.as_str(),
        "jpg" | "jpeg" | "png" | "webp" | "bmp" | "gif" | "tiff" | "tif"
    )
}

fn open_and_hash(path: &Path, algo: HashAlgorithm) -> Result<ImageHash> {
    let img = image::open(path)
        .with_context(|| format!("Impossible de charger l'image : {}", path.display()))?;
    Ok(compute_hash(&img, algo))
}

// ----------------------------------------------------------------------------
// Traitement des commandes
// ----------------------------------------------------------------------------

fn handle_hash(paths: &[PathBuf], algo: HashAlgorithm, json: bool) -> Result<()> {
    let mut outputs = Vec::new();

    for path in paths {
        match open_and_hash(path, algo) {
            Ok(hash) => {
                let out = HashOutput {
                    path: path.display().to_string(),
                    algorithm: algo,
                    hash: hash.to_hex(),
                    hash_u64: hash.value,
                };
                if !json {
                    println!("{:<16}  {}", out.hash, out.path);
                }
                outputs.push(out);
            }
            Err(e) => {
                eprintln!("Erreur pour '{}': {:#}", path.display(), e);
            }
        }
    }

    if json {
        let json_str = serde_json::to_string_pretty(&outputs)?;
        println!("{}", json_str);
    }

    Ok(())
}

fn handle_compare(
    img1: &Path,
    img2: &Path,
    algo: HashAlgorithm,
    threshold: u32,
    json: bool,
) -> Result<()> {
    let hash1 = open_and_hash(img1, algo)?;
    let hash2 = open_and_hash(img2, algo)?;

    let dist = hash1.hamming_distance(&hash2);
    let sim = hash1.similarity(&hash2) * 100.0;
    let is_match = dist <= threshold;

    let out = CompareOutput {
        image1: img1.display().to_string(),
        image2: img2.display().to_string(),
        algorithm: algo,
        hash1: hash1.to_hex(),
        hash2: hash2.to_hex(),
        hamming_distance: dist,
        similarity_percent: sim,
        is_match,
    };

    if json {
        println!("{}", serde_json::to_string_pretty(&out)?);
    } else {
        println!("Algorithme           : {}", algo);
        println!("Image 1              : {} ({})", out.image1, out.hash1);
        println!("Image 2              : {} ({})", out.image2, out.hash2);
        println!("Distance de Hamming  : {} / 64", dist);
        println!("Similarité visuelle  : {:.2}%", sim);
        println!(
            "Correspondance       : {}",
            if is_match {
                "OUI (Visuellement similaire)"
            } else {
                "NON (Images différentes)"
            }
        );
    }

    Ok(())
}

fn handle_scan(dir: &Path, algo: HashAlgorithm, threshold: u32, json: bool) -> Result<()> {
    if !dir.is_dir() {
        anyhow::bail!("Le chemin '{}' n'est pas un dossier valide", dir.display());
    }

    // Collecte des chemins d'images valides
    let entries: Vec<PathBuf> = WalkDir::new(dir)
        .into_iter()
        .filter_map(|e| e.ok())
        .filter(|e| e.file_type().is_file() && is_supported_image(e.path()))
        .map(|e| e.path().to_path_buf())
        .collect();

    if entries.is_empty() {
        if json {
            println!("[]");
        } else {
            println!("Aucune image trouvée dans '{}'", dir.display());
        }
        return Ok(());
    }

    if !json {
        println!(
            "Calcul des empreintes ({}) pour {} images...",
            algo,
            entries.len()
        );
    }

    // Calcul multithreadé avec rayon
    let hashed_images: Vec<(PathBuf, ImageHash)> = entries
        .par_iter()
        .filter_map(|path| match open_and_hash(path, algo) {
            Ok(hash) => Some((path.clone(), hash)),
            Err(e) => {
                eprintln!("Avertissement [{}]: {:#}", path.display(), e);
                None
            }
        })
        .collect();

    // Détection des clusters / quasi-doublons
    let mut visited = vec![false; hashed_images.len()];
    let mut duplicate_groups = Vec::new();

    for i in 0..hashed_images.len() {
        if visited[i] {
            continue;
        }

        let mut matches = Vec::new();
        let (ref path1, hash1) = hashed_images[i];

        for j in (i + 1)..hashed_images.len() {
            if visited[j] {
                continue;
            }

            let (ref path2, hash2) = hashed_images[j];
            let dist = hash1.hamming_distance(&hash2);

            if dist <= threshold {
                visited[j] = true;
                matches.push(DuplicateMatch {
                    path: path2.display().to_string(),
                    hash: hash2.to_hex(),
                    distance: dist,
                    similarity_percent: hash1.similarity(&hash2) * 100.0,
                });
            }
        }

        if !matches.is_empty() {
            visited[i] = true;
            duplicate_groups.push(DuplicateGroup {
                primary: path1.display().to_string(),
                primary_hash: hash1.to_hex(),
                matches,
            });
        }
    }

    if json {
        println!("{}", serde_json::to_string_pretty(&duplicate_groups)?);
    } else if duplicate_groups.is_empty() {
        println!(
            "Aucun quasi-doublon détecté avec un seuil de Hamming <= {}.",
            threshold
        );
    } else {
        println!(
            "\n=== Groupes d'images similaires trouvés : {} ===",
            duplicate_groups.len()
        );
        for (idx, group) in duplicate_groups.iter().enumerate() {
            println!(
                "\nGroupe #{} [Hash: {}] :",
                idx + 1,
                group.primary_hash
            );
            println!("  [Origine] {}", group.primary);
            for m in &group.matches {
                println!(
                    "  [Similaire] {} (dist: {}, similarité: {:.1}%)",
                    m.path, m.distance, m.similarity_percent
                );
            }
        }
    }

    Ok(())
}

// ----------------------------------------------------------------------------
// Entrée principale
// ----------------------------------------------------------------------------

fn main() -> Result<()> {
    let cli = Cli::parse();

    match &cli.command {
        Commands::Hash { paths } => handle_hash(paths, cli.algo, cli.json)?,
        Commands::Compare {
            image1,
            image2,
            threshold,
        } => handle_compare(image1, image2, cli.algo, *threshold, cli.json)?,
        Commands::Scan { dir, threshold } => {
            handle_scan(dir, cli.algo, *threshold, cli.json)?
        }
    }

    Ok(())
}

