    primary_hash: String,
    matches: Vec<DuplicateMatch>,
}

#[derive(Serialize)]
struct DuplicateMatch {
    path: String,
    hash: String,
    distance: u32,
    similarity_percent: f64,
}

// ----------------------------------------------------------------------------
// CLI Arguments
