#[derive(Parser, Debug)]
#[command(
    name = "img-phash",
    about = "CLI performant de calcul d'empreintes perceptuelles (Perceptual Hashing) pour images.",
    version
)]
struct Cli {
    #[arg(short, long, value_enum, default_value = "phash", global = true)]
    algo: HashAlgorithm,

    #[arg(short, long, global = true, help = "Format de sortie en JSON")]
    json: bool,

    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Calcule et affiche l'empreinte perceptuelle d'une ou plusieurs images.
    Hash {
        #[arg(required = true, num_args = 1.., help = "Chemins des images à hacher")]
        paths: Vec<PathBuf>,
    },

    /// Compare visuellement deux images et affiche leur distance de Hamming et similarité.
    Compare {
        #[arg(help = "Chemin de la première image")]
        image1: PathBuf,

        #[arg(help = "Chemin de la seconde image")]
        image2: PathBuf,

        #[arg(
            short,
            long,
            default_value_t = 10,
            help = "Distance de Hamming maximale pour considérer les images comme similaires (0-64)"
        )]
        threshold: u32,
    },

    /// Analyse récursivement un dossier pour détecter les doublons ou images visuellement proches.
    Scan {
        #[arg(help = "Dossier racine à analyser")]
        dir: PathBuf,

        #[arg(
            short,
            long,
            default_value_t = 10,
            help = "Distance de Hamming maximale pour regrouper les doublons (0-64)"
        )]
        threshold: u32,
    },
}

// ----------------------------------------------------------------------------
// Fonctions utilitaires
// ----------------------------------------------------------------------------

fn is_supported_image(path: &Path) -> bool {
    let ext = match path.extension().and_then(|e| e.to_str()) {
        Some(e) => e.to_ascii_lowercase(),
        None => return false,
    };
    matches!(
        ext.as_str(),
        "jpg" | "jpeg" | "png" | "webp" | "bmp" | "gif" | "tiff" | "tif"
    )
}

fn open_and_hash(path: &Path, algo: HashAlgorithm) -> Result<ImageHash> {
    let img = image::open(path)
        .with_context(|| format!("Impossible de charger l'image : {}", path.display()))?;
    Ok(compute_hash(&img, algo))
}

// ----------------------------------------------------------------------------
// Traitement des commandes
// ----------------------------------------------------------------------------

fn handle_hash(paths: &[PathBuf], algo: HashAlgorithm, json: bool) -> Result<()> {
    let mut outputs = Vec::new();

    for path in paths {
        match open_and_hash(path, algo) {
            Ok(hash) => {
                let out = HashOutput {
                    path: path.display().to_string(),
                    algorithm: algo,
                    hash: hash.to_hex(),
                    hash_u64: hash.value,
                };
                if !json {
                    println!("{:<16}  {}", out.hash, out.path);
                }
                outputs.push(out);
            }
            Err(e) => {
                eprintln!("Erreur pour '{}': {:#}", path.display(), e);
            }
        }
    }

    if json {
        let json_str = serde_json::to_string_pretty(&outputs)?;
        println!("{}", json_str);
    }

    Ok(())
}

fn handle_compare(
    img1: &Path,
    img2: &Path,
    algo: HashAlgorithm,
    threshold: u32,
    json: bool,
) -> Result<()> {
    let hash1 = open_and_hash(img1, algo)?;
    let hash2 = open_and_hash(img2, algo)?;

    let dist = hash1.hamming_distance(&hash2);
    let sim = hash1.similarity(&hash2) * 100.0;
    let is_match = dist <= threshold;

    let out = CompareOutput {
        image1: img1.display().to_string(),
        image2: img2.display().to_string(),
        algorithm: algo,
        hash1: hash1.to_hex(),
        hash2: hash2.to_hex(),
        hamming_distance: dist,
        similarity_percent: sim,
        is_match,
    };

    if json {
        println!("{}", serde_json::to_string_pretty(&out)?);
    } else {
        println!("Algorithme           : {}", algo);
        println!("Image 1              : {} ({})", out.image1, out.hash1);
        println!("Image 2              : {} ({})", out.image2, out.hash2);
        println!("Distance de Hamming  : {} / 64", dist);
        println!("Similarité visuelle  : {:.2}%", sim);
        println!(
            "Correspondance       : {}",
            if is_match {
                "OUI (Visuellement similaire)"
            } else {
                "NON (Images différentes)"
            }
        );
    }

    Ok(())
}

fn handle_scan(dir: &Path, algo: HashAlgorithm, threshold: u32, json: bool) -> Result<()> {
    if !dir.is_dir() {
        anyhow::bail!("Le chemin '{}' n'est pas un dossier valide", dir.display());
    }

    // Collecte des chemins d'images valides
    let entries: Vec<PathBuf> = WalkDir::new(dir)
        .into_iter()
        .filter_map(|e| e.ok())
        .filter(|e| e.file_type().is_file() && is_supported_image(e.path()))
        .map(|e| e.path().to_path_buf())
        .collect();

    if entries.is_empty() {
        if json {
            println!("[]");
        } else {
            println!("Aucune image trouvée dans '{}'", dir.display());
        }
        return Ok(());
    }

    if !json {
        println!(
            "Calcul des empreintes ({}) pour {} images...",
            algo,
            entries.len()
        );
    }

    // Calcul multithreadé avec rayon
    let hashed_images: Vec<(PathBuf, ImageHash)> = entries
        .par_iter()
        .filter_map(|path| match open_and_hash(path, algo) {
            Ok(hash) => Some((path.clone(), hash)),
            Err(e) => {
                eprintln!("Avertissement [{}]: {:#}", path.display(), e);
                None
            }
        })
        .collect();

    // Détection des clusters / quasi-doublons
    let mut visited = vec![false; hashed_images.len()];
    let mut duplicate_groups = Vec::new();

    for i in 0..hashed_images.len() {
        if visited[i] {
            continue;
        }

        let mut matches = Vec::new();
        let (ref path1, hash1) = hashed_images[i];

        for j in (i + 1)..hashed_images.len() {
            if visited[j] {
                continue;
            }

            let (ref path2, hash2) = hashed_images[j];
            let dist = hash1.hamming_distance(&hash2);

            if dist <= threshold {
                visited[j] = true;
                matches.push(DuplicateMatch {
                    path: path2.display().to_string(),
                    hash: hash2.to_hex(),
                    distance: dist,
                    similarity_percent: hash1.similarity(&hash2) * 100.0,
                });
            }
        }

        if !matches.is_empty() {
            visited[i] = true;
            duplicate_groups.push(DuplicateGroup {
                primary: path1.display().to_string(),
                primary_hash: hash1.to_hex(),
                matches,
            });
        }
    }

    if json {
        println!("{}", serde_json::to_string_pretty(&duplicate_groups)?);
    } else if duplicate_groups.is_empty() {
        println!(
            "Aucun quasi-doublon détecté avec un seuil de Hamming <= {}.",
            threshold
        );
    } else {
        println!(
            "\n=== Groupes d'images similaires trouvés : {} ===",
            duplicate_groups.len()
        );
        for (idx, group) in duplicate_groups.iter().enumerate() {
            println!(
                "\nGroupe #{} [Hash: {}] :",
                idx + 1,
                group.primary_hash
            );
            println!("  [Origine] {}", group.primary);
            for m in &group.matches {
                println!(
                    "  [Similaire] {} (dist: {}, similarité: {:.1}%)",
                    m.path, m.distance, m.similarity_percent
                );
            }
        }
    }

    Ok(())
}

// ----------------------------------------------------------------------------
// Entrée principale
// ----------------------------------------------------------------------------

fn main() -> Result<()> {
    let cli = Cli::parse();

    match &cli.command {
        Commands::Hash { paths } => handle_hash(paths, cli.algo, cli.json)?,
        Commands::Compare {
            image1,
            image2,
            threshold,
        } => handle_compare(image1, image2, cli.algo, *threshold, cli.json)?,
        Commands::Scan { dir, threshold } => {
            handle_scan(dir, cli.algo, *threshold, cli.json)?
        }
    }

    Ok(())
}

