    about = "Orchestre la sauvegarde compressée et la restauration sécurisée de répertoires",
    long_about = None
)]
pub struct Cli {
    #[arg(short, long, value_enum, default_value_t = Verbosity::Info, global = true)]
    pub verbosity: Verbosity,

    #[command(subcommand)]
    pub command: Commands,
}

#[derive(Subcommand, Debug)]
pub enum Commands {
    /// Crée une sauvegarde compressée (.tar.gz) d'un répertoire source
    Backup(BackupArgs),

    /// Restaure le contenu d'une archive (.tar.gz) vers un répertoire de destination
    Restore(RestoreArgs),

    /// Liste les fichiers et dossiers contenus dans une archive existante
    List(ListArgs),

    /// Vérifie l'intégrité d'une archive par empreinte SHA-256
    Verify(VerifyArgs),
}

#[derive(Args, Debug)]
pub struct BackupArgs {
    /// Chemin du répertoire source à sauvegarder
    #[arg(short, long)]
    pub source: PathBuf,

    /// Répertoire de sortie (ou chemin du fichier .tar.gz complet)
    #[arg(short, long)]
    pub output: PathBuf,

    /// Nom personnalisé de l'archive (sans extension si un dossier de sortie est spécifié)
    #[arg(short, long)]
    pub name: Option<String>,

    /// Calcule et génère un fichier de contrôle .sha256 à côté de l'archive
    #[arg(long, default_value_t = true)]
    pub checksum: bool,

    /// Simule la sauvegarde sans écrire sur le disque
    #[arg(long, default_value_t = false)]
    pub dry_run: bool,
}

#[derive(Args, Debug)]
pub struct RestoreArgs {
    /// Chemin de l'archive .tar.gz à restaurer
    #[arg(short, long)]
    pub archive: PathBuf,

    /// Répertoire cible où décompresser les données
    #[arg(short, long)]
    pub target: PathBuf,

    /// Vérifie l'intégrité SHA-256 avant la décompression si un fichier .sha256 existe
    #[arg(long, default_value_t = true)]
    pub verify: bool,

    /// Écrase les fichiers existants sans prompt
    #[arg(long, default_value_t = false)]
    pub overwrite: bool,

    /// Simule la restauration et liste les fichiers qui seraient extraits
    #[arg(long, default_value_t = false)]
    pub dry_run: bool,
}

#[derive(Args, Debug)]
pub struct ListArgs {
    /// Chemin de l'archive .tar.gz à inspecter
    #[arg(short, long)]
    pub archive: PathBuf,

    /// Affiche des détails étendus (tailles en octets, type d'entrée)
    #[arg(short, long, default_value_t = false)]
    pub verbose: bool,
}

#[derive(Args, Debug)]
pub struct VerifyArgs {
    /// Chemin de l'archive .tar.gz à vérifier
    #[arg(short, long)]
    pub archive: PathBuf,

    /// Fichier contenant l'empreinte SHA-256 attendue (par défaut: <archive>.sha256)
    #[arg(short, long)]
    pub checksum_file: Option<PathBuf>,
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    init_logging(cli.verbosity);

    let result = match cli.command {
        Commands::Backup(args) => handle_backup(args),
        Commands::Restore(args) => handle_restore(args),
        Commands::List(args) => handle_list(args),
        Commands::Verify(args) => handle_verify(args),
    };

    if let Err(ref err) = result {
        error!("Échec de l'opération : {:#}", err);
    }

    result
}

fn init_logging(verbosity: Verbosity) {
    let filter = match verbosity {
        Verbosity::Quiet => "warn",
        Verbosity::Info => "info",
        Verbosity::Debug => "debug",
    };

    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new(filter)))
        .with_target(false)
        .init();
}

fn handle_backup(args: BackupArgs) -> Result<()> {
    if !args.source.exists() {
        bail!("Le répertoire source spécifié n'existe pas : {:?}", args.source);
    }

    if !args.source.is_dir() {
        bail!("La source doit être un répertoire : {:?}", args.source);
    }

    let archive_path = resolve_backup_destination(&args.output, args.name.as_deref())?;

    info!(
        "Démarrage de la sauvegarde de {:?} vers {:?}",
        args.source, archive_path
    );

    if args.dry_run {
        info!("[DRY-RUN] Simulation de la sauvegarde. Fichiers parcourus :");
        let mut count = 0;
        for entry in WalkDir::new(&args.source) {
            let entry = entry.context("Erreur lors de la traversée de fichier")?;
            if entry.path() != args.source {
                count += 1;
                println!("  + {}", entry.path().display());
            }
        }
        info!("[DRY-RUN] {} entrées simulées avec succès.", count);
        return Ok(());
    }

    if let Some(parent) = archive_path.parent() {
        if !parent.exists() {
            fs::create_dir_all(parent).with_context(|| {
                format!("Impossible de créer le dossier parent : {:?}", parent)
            })?;
        }
    }

    let file = File::create(&archive_path).with_context(|| {
        format!("Impossible de créer le fichier d'archive : {:?}", archive_path)
    })?;
    let enc = GzEncoder::new(file, Compression::default());
    let mut tar = Builder::new(enc);

    let base_name = args
        .source
        .file_name()
        .context("Impossible d'extraire le nom de base du répertoire source")?;

    tar.append_dir_all(base_name, &args.source)
        .with_context(|| format!("Erreur lors de l'archivage de {:?}", args.source))?;

    let enc = tar.into_inner().context("Erreur lors de la finalisation de l'archive TAR")?;
    enc.finish().context("Erreur lors de la compression GZIP")?;

    info!("Sauvegarde créée avec succès : {:?}", archive_path);

    if args.checksum {
        let checksum = compute_file_sha256(&archive_path)?;
        let checksum_path = archive_path.with_extension("tar.gz.sha256");
        let content = format!("{}  {}\n", checksum, archive_path.file_name().unwrap_or_default().to_string_lossy());
        fs::write(&checksum_path, content).with_context(|| {
            format!("Impossible d'écrire le fichier d'empreinte : {:?}", checksum_path)
        })?;
        info!("Empreinte SHA-256 générée ({}) : {:?}", checksum, checksum_path);
    }

    Ok(())
}

fn handle_restore(args: RestoreArgs) -> Result<()> {
    if !args.archive.exists() {
        bail!("Le fichier archive spécifié n'existe pas : {:?}", args.archive);
    }

    if args.verify {
        let checksum_path = args.archive.with_extension("tar.gz.sha256");
        if checksum_path.exists() {
            info!("Vérification d'intégrité via {:?}", checksum_path);
            verify_archive_integrity(&args.archive, &checksum_path)?;
            info!("Vérification de l'archive réussie.");
        } else {
            warn!(
                "Fichier de contrôle introuvable ({:?}), étape de vérification ignorée.",
                checksum_path
            );
        }
    }

    info!("Restauration de {:?} vers {:?}", args.archive, args.target);

    let file = File::open(&args.archive)
        .with_context(|| format!("Ouverture impossible de l'archive : {:?}", args.archive))?;
    let gz = GzDecoder::new(file);
    let mut archive = Archive::new(gz);

    if args.dry_run {
        info!("[DRY-RUN] Contenu qui serait extrait :");
        let entries = archive.entries().context("Lecture des entrées d'archive")?;
        for entry in entries {
            let entry = entry.context("Entrée d'archive invalide")?;
            let path = entry.path().context("Chemin invalide dans l'archive")?;
            println!("  -> {}", path.display());
        }
        info!("[DRY-RUN] Simulation terminée.");
        return Ok(());
    }

    if !args.target.exists() {
        fs::create_dir_all(&args.target).with_context(|| {
            format!("Création impossible du dossier cible : {:?}", args.target)
        })?;
    }

    let entries = archive.entries().context("Erreur lors de la lecture des entrées")?;
    for entry in entries {
        let mut entry = entry.context("Entrée corrompue dans l'archive")?;
        let rel_path = entry.path().context("Chemin invalide dans l'archive")?;

        // Sécurité contre les attaques Path Traversal (Zip Slip)
        if rel_path.starts_with("..") || rel_path.is_absolute() {
            bail!("Chemin non sécurisé détecté dans l'archive : {:?}", rel_path);
        }

        let dest_path = args.target.join(rel_path);

        if dest_path.exists() && !args.overwrite && dest_path.is_file() {
            warn!(
                "Fichier existant ignoré (utiliser --overwrite pour écraser) : {:?}",
                dest_path
            );
            continue;
        }

        entry.unpack_in(&args.target).with_context(|| {
            format!("Erreur lors de l'extraction de {:?}", dest_path)
        })?;
    }

    info!("Restauration terminée avec succès dans {:?}", args.target);
    Ok(())
}

fn handle_list(args: ListArgs) -> Result<()> {
    if !args.archive.exists() {
        bail!("Archive introuvable : {:?}", args.archive);
    }

    let file = File::open(&args.archive)
        .with_context(|| format!("Ouverture impossible : {:?}", args.archive))?;
    let gz = GzDecoder::new(file);
    let mut archive = Archive::new(gz);

    println!("{:<10} {:<12} {}", "TYPE", "TAILLE (o)", "CHEMIN");
    println!("{:-<10} {:-<12} {:-<40}", "", "", "");

    let entries = archive.entries().context("Lecture du catalogue de l'archive")?;
    let mut total_files = 0;
    let mut total_size = 0u64;

    for entry in entries {
        let entry = entry.context("Entrée invalide")?;
        let path = entry.path().context("Chemin illisible")?;
        let header = entry.header();
        let size = header.size().unwrap_or(0);
        let entry_type = if header.entry_type().is_dir() {
            "DIR"
        } else if header.entry_type().is_file() {
            "FILE"
        } else if header.entry_type().is_symlink() {
            "SYMLINK"
        } else {
            "OTHER"
        };

        if args.verbose {
            let mode = header.mode().unwrap_or(0);
            println!("{:<10} {:<12} {} (mode: {:o})", entry_type, size, path.display(), mode);
        } else {
            println!("{:<10} {:<12} {}", entry_type, size, path.display());
        }

        total_files += 1;
        total_size += size;
    }

    println!("{:-<10} {:-<12} {:-<40}", "", "", "");
    println!("Total : {} entrées, {} octets décompressés.", total_files, total_size);

    Ok(())
}

fn handle_verify(args: VerifyArgs) -> Result<()> {
    if !args.archive.exists() {
        bail!("Archive introuvable : {:?}", args.archive);
    }

    let checksum_path = match args.checksum_file {
        Some(path) => path,
        None => args.archive.with_extension("tar.gz.sha256"),
    };

    if !checksum_path.exists() {
        bail!(
            "Fichier d'empreinte introuvable à {:?}. Spécifiez-en un avec --checksum-file.",
            checksum_path
        );
    }

    verify_archive_integrity(&args.archive, &checksum_path)?;
    println!("L'archive {:?} est intègre et correspond à son empreinte SHA-256.", args.archive);
    Ok(())
}

fn resolve_backup_destination(output: &Path, custom_name: Option<&str>) -> Result<PathBuf> {
    if output.is_dir() || !output.to_string_lossy().ends_with(".tar.gz") {
        let timestamp = Local::now().format("%Y%m%d_%H%M%S");
        let file_name = match custom_name {
            Some(name) => {
                if name.ends_with(".tar.gz") {
                    name.to_string()
                } else {
                    format!("{}.tar.gz", name)
                }
            }
            None => format!("backup_{}.tar.gz", timestamp),
        };
        Ok(output.join(file_name))
    } else {
        Ok(output.to_path_buf())
    }
}

fn compute_file_sha256(path: &Path) -> Result<String> {
    let file = File::open(path)
        .with_context(|| format!("Impossible d'ouvrir le fichier pour SHA-256 : {:?}", path))?;
    let mut reader = BufReader::new(file);
    let mut hasher = Sha256::new();
    let mut buffer = [0u8; 8192];

    loop {
        let bytes_read = reader
            .read(&mut buffer)
            .context("Erreur lors de la lecture du flux pour SHA-256")?;
        if bytes_read == 0 {
            break;
        }
        hasher.update(&buffer[..bytes_read]);
    }

    let digest = hasher.finalize();
    Ok(hex::encode(digest))
}

fn verify_archive_integrity(archive_path: &Path, checksum_path: &Path) -> Result<()> {
    let content = fs::read_to_string(checksum_path)
        .with_context(|| format!("Lecture du fichier d'empreinte impossible : {:?}", checksum_path))?;

    let expected_hash = content
        .split_whitespace()
        .next()
        .context("Format de fichier d'empreinte invalide")?
        .trim();

    let computed_hash = compute_file_sha256(archive_path)?;

    if !expected_hash.eq_ignore_ascii_case(&computed_hash) {
        bail!(
            "Altération détectée ! Empreinte attendue: {}, calculée: {}",
            expected_hash,
            computed_hash
        );
    }

    Ok(())
}

