        bail!("Archive introuvable : {:?}", args.archive);
    }

    let file = File::open(&args.archive)
        .with_context(|| format!("Ouverture impossible : {:?}", args.archive))?;
    let gz = GzDecoder::new(file);
    let mut archive = Archive::new(gz);

    println!("{:<10} {:<12} {}", "TYPE", "TAILLE (o)", "CHEMIN");
    println!("{:-<10} {:-<12} {:-<40}", "", "", "");

    let entries = archive.entries().context("Lecture du catalogue de l'archive")?;
    let mut total_files = 0;
    let mut total_size = 0u64;

    for entry in entries {
        let entry = entry.context("Entrée invalide")?;
        let path = entry.path().context("Chemin illisible")?;
        let header = entry.header();
        let size = header.size().unwrap_or(0);
        let entry_type = if header.entry_type().is_dir() {
            "DIR"
        } else if header.entry_type().is_file() {
            "FILE"
        } else if header.entry_type().is_symlink() {
            "SYMLINK"
        } else {
            "OTHER"
        };

        if args.verbose {
            let mode = header.mode().unwrap_or(0);
            println!("{:<10} {:<12} {} (mode: {:o})", entry_type, size, path.display(), mode);
        } else {
            println!("{:<10} {:<12} {}", entry_type, size, path.display());
        }

        total_files += 1;
        total_size += size;
    }

    println!("{:-<10} {:-<12} {:-<40}", "", "", "");
    println!("Total : {} entrées, {} octets décompressés.", total_files, total_size);

    Ok(())
}

fn handle_verify(args: VerifyArgs) -> Result<()> {
    if !args.archive.exists() {
        bail!("Archive introuvable : {:?}", args.archive);
    }

    let checksum_path = match args.checksum_file {
        Some(path) => path,
        None => args.archive.with_extension("tar.gz.sha256"),
    };

    if !checksum_path.exists() {
        bail!(
            "Fichier d'empreinte introuvable à {:?}. Spécifiez-en un avec --checksum-file.",
            checksum_path
        );
    }

    verify_archive_integrity(&args.archive, &checksum_path)?;
    println!("L'archive {:?} est intègre et correspond à son empreinte SHA-256.", args.archive);
    Ok(())
}

fn resolve_backup_destination(output: &Path, custom_name: Option<&str>) -> Result<PathBuf> {
    if output.is_dir() || !output.to_string_lossy().ends_with(".tar.gz") {
        let timestamp = Local::now().format("%Y%m%d_%H%M%S");
        let file_name = match custom_name {
            Some(name) => {
                if name.ends_with(".tar.gz") {
                    name.to_string()
                } else {
                    format!("{}.tar.gz", name)
                }
            }
            None => format!("backup_{}.tar.gz", timestamp),
        };
        Ok(output.join(file_name))
    } else {
        Ok(output.to_path_buf())
    }
}

fn compute_file_sha256(path: &Path) -> Result<String> {
    let file = File::open(path)
        .with_context(|| format!("Impossible d'ouvrir le fichier pour SHA-256 : {:?}", path))?;
    let mut reader = BufReader::new(file);
    let mut hasher = Sha256::new();
    let mut buffer = [0u8; 8192];

    loop {
        let bytes_read = reader
            .read(&mut buffer)
            .context("Erreur lors de la lecture du flux pour SHA-256")?;
        if bytes_read == 0 {
            break;
        }
        hasher.update(&buffer[..bytes_read]);
    }

    let digest = hasher.finalize();
    Ok(hex::encode(digest))
}

fn verify_archive_integrity(archive_path: &Path, checksum_path: &Path) -> Result<()> {
    let content = fs::read_to_string(checksum_path)
        .with_context(|| format!("Lecture du fichier d'empreinte impossible : {:?}", checksum_path))?;

    let expected_hash = content
        .split_whitespace()
        .next()
        .context("Format de fichier d'empreinte invalide")?
        .trim();

    let computed_hash = compute_file_sha256(archive_path)?;

    if !expected_hash.eq_ignore_ascii_case(&computed_hash) {
        bail!(
            "Altération détectée ! Empreinte attendue: {}, calculée: {}",
            expected_hash,
            computed_hash
        );
    }

    Ok(())
}

