use std::collections::HashSet;
use std::fs::{self, File};
use std::io::{BufReader, Read};
use std::path::{Path, PathBuf};
use tracing::{debug, error, info, warn};
use tracing_subscriber::EnvFilter;
use walkdir::WalkDir;

/// Outil CLI de synchronisation miroir unidirectionnelle entre deux répertoires locaux.
#[derive(Parser, Debug)]
#[command(name = "mirror_sync")]
#[command(author, version, about = "Synchroniseur miroir unidirectionnel local avec détection fine des modifications", long_about = None)]
