    /// Compare le contenu des fichiers via l'empreinte BLAKE3 au lieu des métadonnées seules
    #[arg(short, long)]
    checksum: bool,

    /// Affiche les actions prévues sans modifier les fichiers
    #[arg(short = 'n', long)]
    dry_run: bool,

    /// Active les messages détaillés
    #[arg(short, long)]
    verbose: bool,

    /// Réduit au minimum les sorties console
    #[arg(short, long)]
    quiet: bool,
}

/// Statistiques de synchronisation
#[derive(Default, Debug)]
struct SyncStats {
    dirs_created: usize,
    files_copied: usize,
    files_updated: usize,
    files_deleted: usize,
    dirs_deleted: usize,
    bytes_transferred: u64,
}

fn main() -> Result<()> {
    let args = Cli::parse();
    setup_logging(&args)?;

    info!(
        "Démarrage de la synchronisation : {:?} -> {:?}",
        args.source, args.destination
    );

    if !args.source.exists() {
        anyhow::bail!(
            "Le répertoire source n'existe pas : {}",
            args.source.display()
        );
    }
    if !args.source.is_dir() {
        anyhow::bail!(
            "La source spécifiée n'est pas un dossier : {}",
            args.source.display()
        );
    }

    let source = args
        .source
        .canonicalize()
        .with_context(|| format!("Impossible de résoudre le chemin source: {:?}", args.source))?;

    // Crée le dossier de destination si inexistant
    if !args.destination.exists() {
        if args.dry_run {
            info!("[DRY-RUN] Création du dossier cible racine : {:?}", args.destination);
        } else {
            fs::create_dir_all(&args.destination).with_context(|| {
                format!(
                    "Impossible de créer le dossier cible : {:?}",
                    args.destination
                )
            })?;
        }
    }

    let destination = if args.destination.exists() {
        args.destination
            .canonicalize()
            .with_context(|| format!("Impossible de résoudre le chemin destination: {:?}", args.destination))?
    } else {
        args.destination.clone()
    };

    if source == destination {
        anyhow::bail!("La source et la destination pointent vers le même répertoire physique.");
    }

    let mut stats = SyncStats::default();

    // 1. Synchronisation Source -> Destination
    let source_entries = sync_forward(&source, &destination, &args, &mut stats)?;

    // 2. Nettoyage miroir des fichiers/dossiers orphelins dans Destination
    purge_orphans(&destination, &source_entries, &args, &mut stats)?;

    display_summary(&stats, args.dry_run);

    Ok(())
}

fn setup_logging(args: &Cli) -> Result<()> {
    let filter = if args.quiet {
        "warn"
    } else if args.verbose {
        "debug"
    } else {
        "info"
    };

    let env_filter = EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new(filter));

    tracing_subscriber::fmt()
        .with_env_filter(env_filter)
        .with_target(false)
        .try_init()
        .map_err(|e| anyhow::anyhow!("Erreur lors de l'initialisation du logger: {}", e))?;

    Ok(())
}

/// Parcourt la source et synchronise vers la destination
fn sync_forward(
    source: &Path,
    destination: &Path,
    args: &Cli,
    stats: &mut SyncStats,
) -> Result<HashSet<PathBuf>> {
    let mut seen_relative_paths = HashSet::new();

    for entry_res in WalkDir::new(source).min_depth(1) {
        let entry = match entry_res {
            Ok(e) => e,
            Err(err) => {
                warn!("Impossible de lire une entrée source : {}", err);
                continue;
            }
        };

        let src_path = entry.path();
        let rel_path = match src_path.strip_prefix(source) {
            Ok(p) => p.to_path_buf(),
            Err(err) => {
                warn!("Erreur lors du calcul du chemin relatif pour {:?} : {}", src_path, err);
                continue;
            }
        };

        seen_relative_paths.insert(rel_path.clone());
        let dest_path = destination.join(&rel_path);
        let file_type = entry.file_type();

        if file_type.is_dir() {
            if !dest_path.exists() {
                if args.dry_run {
                    info!("[DRY-RUN] Dossier à créer : {:?}", rel_path);
                } else {
                    debug!("Création du sous-dossier : {:?}", dest_path);
                    fs::create_dir_all(&dest_path).with_context(|| {
                        format!("Erreur lors de la création du dossier {:?}", dest_path)
                    })?;
                }
                stats.dirs_created += 1;
            }
        } else if file_type.is_file() {
            match needs_update(src_path, &dest_path, args.checksum) {
                Ok(Some(is_new)) => {
                    let file_size = entry.metadata().map(|m| m.len()).unwrap_or(0);
                    if args.dry_run {
                        if is_new {
                            info!("[DRY-RUN] Nouveau fichier à copier : {:?}", rel_path);
                        } else {
                            info!("[DRY-RUN] Fichier modifié à actualiser : {:?}", rel_path);
                        }
                    } else {
                        copy_and_preserve(src_path, &dest_path)?;
                    }

                    if is_new {
                        stats.files_copied += 1;
                    } else {
                        stats.files_updated += 1;
                    }
                    stats.bytes_transferred += file_size;
                }
                Ok(None) => {
                    debug!("Fichier déjà synchronisé : {:?}", rel_path);
                }
                Err(err) => {
                    error!(
                        "Erreur lors de l'évaluation de synchronisation pour {:?} : {}",
                        src_path, err
                    );
                }
            }
        }
    }

    Ok(seen_relative_paths)
}

/// Vérifie si un fichier doit être mis à jour.
/// Retourne `Ok(Some(true))` si nouveau, `Ok(Some(false))` si modifié, `Ok(None)` si identique.
fn needs_update(src: &Path, dest: &Path, force_checksum: bool) -> Result<Option<bool>> {
    if !dest.exists() {
        return Ok(Some(true));
    }

    let src_meta = fs::metadata(src)
        .with_context(|| format!("Impossible de lire les métadonnées source : {:?}", src))?;
    let dest_meta = fs::metadata(dest)
        .with_context(|| format!("Impossible de lire les métadonnées cible : {:?}", dest))?;

    // Différence de taille => mise à jour requise
    if src_meta.len() != dest_meta.len() {
        return Ok(Some(false));
    }

    let src_mtime = FileTime::from_last_modification_time(&src_meta);
    let dest_mtime = FileTime::from_last_modification_time(&dest_meta);

    if force_checksum {
        let src_hash = compute_hash(src)?;
        let dest_hash = compute_hash(dest)?;
        if src_hash != dest_hash {
            return Ok(Some(false));
        }
    } else if src_mtime != dest_mtime {
        // En cas de mtimes différents mais taille égale, vérifie le checksum pour s'assurer d'un changement effectif
        let src_hash = compute_hash(src)?;
        let dest_hash = compute_hash(dest)?;
        if src_hash != dest_hash {
            return Ok(Some(false));
        }
    }

    Ok(None)
}

/// Calcule le hachage BLAKE3 d'un fichier via un buffer de lecture
fn compute_hash(path: &Path) -> Result<blake3::Hash> {
    let file = File::open(path)
        .with_context(|| format!("Impossible d'ouvrir pour hachage : {:?}", path))?;
    let mut reader = BufReader::with_capacity(64 * 1024, file);
    let mut hasher = blake3::Hasher::new();
    let mut buffer = [0u8; 64 * 1024];

    loop {
        let bytes_read = reader
            .read(&mut buffer)
            .with_context(|| format!("Erreur de lecture lors du hachage : {:?}", path))?;
        if bytes_read == 0 {
            break;
        }
        hasher.update(&buffer[..bytes_read]);
    }

    Ok(hasher.finalize())
}

/// Copie le fichier et applique les horodatages source sur la destination
fn copy_and_preserve(src: &Path, dest: &Path) -> Result<()> {
    if let Some(parent) = dest.parent() {
        if !parent.exists() {
            fs::create_dir_all(parent)
                .with_context(|| format!("Échec création répertoire parent : {:?}", parent))?;
        }
    }

    fs::copy(src, dest)
        .with_context(|| format!("Échec de copie de {:?} vers {:?}", src, dest))?;

    let src_meta = fs::metadata(src)
        .with_context(|| format!("Impossible de lire les métadonnées source : {:?}", src))?;
    let mtime = FileTime::from_last_modification_time(&src_meta);
    set_file_mtime(dest, mtime)
        .with_context(|| format!("Échec de mise à jour du mtime pour : {:?}", dest))?;

    Ok(())
}

/// Supprime les fichiers et dossiers dans Destination qui ne figurent plus dans Source
fn purge_orphans(
    destination: &Path,
    source_entries: &HashSet<PathBuf>,
    args: &Cli,
    stats: &mut SyncStats,
) -> Result<()> {
    if !destination.exists() {
        return Ok(());
    }

    // Récupérer et trier toutes les entrées par profondeur descendante pour supprimer les enfants avant les parents
    let mut dest_entries = Vec::new();
    for entry_res in WalkDir::new(destination).min_depth(1) {
        match entry_res {
            Ok(e) => dest_entries.push(e),
            Err(err) => {
                warn!("Impossible d'inspecter l'arborescence cible : {}", err);
            }
        }
    }

    // Trier de manière à traiter les chemins les plus profonds d'abord
    dest_entries.sort_by(|a, b| b.depth().cmp(&a.depth()));

    for entry in dest_entries {
        let path = entry.path();
        let rel_path = match path.strip_prefix(destination) {
            Ok(p) => p.to_path_buf(),
            Err(_) => continue,
        };

        if !source_entries.contains(&rel_path) {
            let file_type = entry.file_type();
            if file_type.is_dir() {
                if args.dry_run {
                    info!("[DRY-RUN] Dossier orphelin à supprimer : {:?}", rel_path);
                } else {
                    debug!("Suppression dossier orphelin : {:?}", path);
                    if let Err(e) = fs::remove_dir(path) {
                        warn!("Impossible de supprimer le dossier {:?} : {}", path, e);
                    }
                }
                stats.dirs_deleted += 1;
            } else {
                if args.dry_run {
                    info!("[DRY-RUN] Fichier orphelin à supprimer : {:?}", rel_path);
                } else {
                    debug!("Suppression fichier orphelin : {:?}", path);
                    if let Err(e) = fs::remove_file(path) {
                        warn!("Impossible de supprimer le fichier {:?} : {}", path, e);
                    }
                }
                stats.files_deleted += 1;
            }
        }
    }

    Ok(())
}

fn display_summary(stats: &SyncStats, dry_run: bool) {
    let mode_str = if dry_run { " [SIMULATION]" } else { "" };
    info!("--- Résumé de la synchronisation{} ---", mode_str);
    info!("Dossiers créés    : {}", stats.dirs_created);
    info!("Fichiers copiés   : {}", stats.files_copied);
    info!("Fichiers modifiés : {}", stats.files_updated);
    info!("Fichiers orphelins supprimés : {}", stats.files_deleted);
    info!("Dossiers orphelins supprimés : {}", stats.dirs_deleted);
    info!(
        "Volume transféré  : {:.2} Mo",
        stats.bytes_transferred as f64 / (1024.0 * 1024.0)
    );
}

