    #[arg(short, long)]
    pub author: Option<String>,

    /// Dossier de destination (par défaut : répertoire courant / nom du projet)
    #[arg(short, long)]
    pub output_dir: Option<PathBuf>,

    /// Inclure la dépendance clap pour les CLI
    #[arg(long)]
    pub with_cli: bool,

    /// Inclure la dépendance serde et serde_json
    #[arg(long)]
    pub with_serde: bool,

    /// Écraser le répertoire de destination s'il existe déjà
    #[arg(short, long)]
    pub force: bool,
}

fn validate_name(name: &str) -> Result<String, String> {
    if name.is_empty() {
        return Err("Le nom du projet ne peut pas être vide".to_string());
    }
    let is_valid = name
        .chars()
        .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-');
    if !is_valid {
        return Err(
            "Le nom du projet ne doit contenir que des caractères alphanumériques, '-' ou '_'."
                .to_string(),
        );
    }
    Ok(name.to_string())
}

#[derive(Debug, Clone)]
pub struct ProjectGenerator {
    config: Cli,
}

impl ProjectGenerator {
    pub fn new(config: Cli) -> Self {
        Self { config }
    }

    pub fn destination_path(&self) -> PathBuf {
        if let Some(ref dir) = self.config.output_dir {
            dir.clone()
        } else {
            PathBuf::from(&self.config.name)
        }
    }

    pub fn generate(&self) -> Result<PathBuf, ScaffoldError> {
        let dest = self.destination_path();

        if dest.exists() {
            if self.config.force {
                fs::remove_dir_all(&dest)?;
            } else {
                return Err(ScaffoldError::DirectoryAlreadyExists(dest));
            }
        }

        let src_dir = dest.join("src");
        let tests_dir = dest.join("tests");

        fs::create_dir_all(&src_dir)?;
        fs::create_dir_all(&tests_dir)?;

        self.write_cargo_toml(&dest)?;
        self.write_source_file(&src_dir)?;
        self.write_integration_test(&tests_dir)?;
        self.write_gitignore(&dest)?;
        self.write_readme(&dest)?;

        Ok(dest)
    }

    fn write_cargo_toml(&self, root: &Path) -> Result<(), ScaffoldError> {
        let cargo_toml_path = root.join("Cargo.toml");

        let mut package = toml::Table::new();
        package.insert("name".to_string(), toml::Value::String(self.config.name.clone()));
        package.insert("version".to_string(), toml::Value::String("0.1.0".to_string()));
        package.insert("edition".to_string(), toml::Value::String(self.config.edition.clone()));
        package.insert(
            "description".to_string(),
            toml::Value::String(self.config.description.clone()),
        );

        if let Some(ref author) = self.config.author {
            package.insert(
                "authors".to_string(),
                toml::Value::Array(vec![toml::Value::String(author.clone())]),
            );
        }

        let mut dependencies = toml::Table::new();
        if self.config.with_cli {
            let mut clap_table = toml::Table::new();
            clap_table.insert("version".to_string(), toml::Value::String("4.5".to_string()));
            clap_table.insert(
                "features".to_string(),
                toml::Value::Array(vec![toml::Value::String("derive".to_string())]),
            );
            dependencies.insert("clap".to_string(), toml::Value::Table(clap_table));
        }

        if self.config.with_serde {
            let mut serde_table = toml::Table::new();
            serde_table.insert("version".to_string(), toml::Value::String("1.0".to_string()));
            serde_table.insert(
                "features".to_string(),
                toml::Value::Array(vec![toml::Value::String("derive".to_string())]),
            );
            dependencies.insert("serde".to_string(), toml::Value::Table(serde_table));
            dependencies.insert(
                "serde_json".to_string(),
                toml::Value::String("1.0".to_string()),
            );
        }

        let mut doc = toml::Table::new();
        doc.insert("package".to_string(), toml::Value::Table(package));
        doc.insert("dependencies".to_string(), toml::Value::Table(dependencies));

        let toml_string = toml::to_string_pretty(&doc)?;
        fs::write(cargo_toml_path, toml_string)?;
        Ok(())
    }

    fn write_source_file(&self, src_dir: &Path) -> Result<(), ScaffoldError> {
        match self.config.project_type {
            ProjectType::Bin => {
                let file_path = src_dir.join("main.rs");
                let content = self.build_main_content();
                fs::write(file_path, content)?;
            }
            ProjectType::Lib => {
                let file_path = src_dir.join("lib.rs");
                let content = self.build_lib_content();
                fs::write(file_path, content)?;
            }
        }
        Ok(())
    }

    fn build_main_content(&self) -> String {
        let mut content = String::new();
        content.push_str("/// Point d'entrée principal de l'application.\n");

        if self.config.with_cli {
            content.push_str("use clap::Parser;\n\n");
            content.push_str("/// CLI générée par rust-scaffold\n");
            content.push_str("#[derive(Parser, Debug)]\n");
            content.push_str("#[command(version, about, long_about = None)]\n");
            content.push_str("struct Args {\n");
            content.push_str("    /// Message de bienvenue personnalisé\n");
            content.push_str("    #[arg(short, long, default_value = \"Monde\")]\n");
            content.push_str("    name: String,\n");
            content.push_str("}\n\n");
        }

        content.push_str("fn main() -> Result<(), Box<dyn std::error::Error>> {\n");
        if self.config.with_cli {
            content.push_str("    let args = Args::parse();\n");
            content.push_str("    println!(\"{}\", greet(&args.name));\n");
        } else {
            content.push_str("    println!(\"{}\", greet(\"Monde\"));\n");
        }
        content.push_str("    Ok(())\n");
        content.push_str("}\n\n");

        content.push_str("/// Génère un message de salutation.\n");
        content.push_str("pub fn greet(target: &str) -> String {\n");
        content.push_str("    format!(\"Bonjour, {} !\", target)\n");
        content.push_str("}\n\n");

        content.push_str("#[cfg(test)]\n");
        content.push_str("mod tests {\n");
        content.push_str("    use super::*;\n\n");
        content.push_str("    #[test]\n");
        content.push_str("    fn test_greet() {\n");
        content.push_str("        let result = greet(\"Rustacean\");\n");
        content.push_str("        assert_eq!(result, \"Bonjour, Rustacean !\");\n");
        content.push_str("    }\n");
        content.push_str("}\n");

        content
    }

    fn build_lib_content(&self) -> String {
        let mut content = String::new();
        content.push_str("/// Bibliothèque standard générée par rust-scaffold.\n\n");
        content.push_str("/// Calcule l'addition de deux entiers.\n");
        content.push_str("pub fn add(left: u64, right: u64) -> u64 {\n");
        content.push_str("    left + right\n");
        content.push_str("}\n\n");
        content.push_str("#[cfg(test)]\n");
        content.push_str("mod tests {\n");
        content.push_str("    use super::*;\n\n");
        content.push_str("    #[test]\n");
        content.push_str("    fn it_works() {\n");
        content.push_str("        let result = add(2, 2);\n");
        content.push_str("        assert_eq!(result, 4);\n");
        content.push_str("    }\n");
        content.push_str("}\n");

        content
    }

    fn write_integration_test(&self, tests_dir: &Path) -> Result<(), ScaffoldError> {
        let test_file = tests_dir.join("integration_test.rs");
        let content = r#"#[test]
fn test_standard_execution() {
    assert_eq!(2 + 2, 4);
}
"#;
        fs::write(test_file, content)?;
        Ok(())
    }

    fn write_gitignore(&self, root: &Path) -> Result<(), ScaffoldError> {
        let gitignore = root.join(".gitignore");
        let content = r#"/target
**/*.rs.bk
Cargo.lock
"#;
        fs::write(gitignore, content)?;
        Ok(())
    }

    fn write_readme(&self, root: &Path) -> Result<(), ScaffoldError> {
        let readme = root.join("README.md");
        let content = format!(
            "# {}\n\n{}\n\n## Commandes courantes\n\n```bash\ncargo check\ncargo test\ncargo run\n```\n",
            self.config.name, self.config.description
        );
        fs::write(readme, content)?;
        Ok(())
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Cli::parse();
    let generator = ProjectGenerator::new(args);
    let target = generator.generate()?;
    println!("✅ Squelette de projet Rust généré avec succès dans : {}", target.display());
    Ok(())
}

