// src/main.rs
use anyhow::{bail, Context, Result};
use clap::Parser;
use colored::*;
use regex::Regex;
use std::collections::{HashMap, HashSet};
use std::fs;
use std::path::{Path, PathBuf};

/// CLI de renommage par lots de fichiers avec regex, numérotation séquentielle et prévisualisation.
#[derive(Parser, Debug)]
#[command(name = "batch-rename", version, about, long_about = None)]
struct Args {
    /// Fichiers ou motifs globaux à renommer
    #[arg(required = true)]
    files: Vec<String>,

    /// Motif Regex à rechercher dans le nom de fichier
    #[arg(short = 'p', long = "pattern", required = true)]
    pattern: String,

    /// Chaîne de remplacement (supporte les groupes regex $1, $2... et le tag séquentiel {seq})
    #[arg(short = 'r', long = "replacement", required = true)]
    replacement: String,

    /// Valeur de départ pour la numérotation séquentielle {seq}
    #[arg(short = 's', long = "start", default_value_t = 1)]
    start: usize,

    /// Pas d'incrémentation pour {seq}
    #[arg(long = "step", default_value_t = 1)]
    step: usize,

    /// Rembourrage par des zéros pour {seq} (largeur minimale en chiffres)
    #[arg(long = "pad", default_value_t = 1)]
    pad: usize,

    /// Mode prévisualisation (simule les renommages sans modifier le disque)
    #[arg(short = 'n', long = "dry-run")]
    dry_run: bool,

    /// Applique réellement les renommages
    #[arg(short = 'x', long = "execute")]
    execute: bool,
}

#[derive(Debug, Clone)]
struct RenamePlan {
    source: PathBuf,
    destination: PathBuf,
    has_changed: bool,
}

fn main() -> Result<()> {
    let args = Args::parse();

    // Par défaut, si --execute n'est pas fourni, nous restons en mode prévisualisation sécurisé.
    let is_dry_run = args.dry_run || !args.execute;

    let regex = Regex::new(&args.pattern)
        .with_context(|| format!("Motif regex invalide : '{}'", args.pattern))?;

    let file_paths = collect_files(&args.files)?;
    if file_paths.is_empty() {
        println!("{}", "Aucun fichier correspondant trouvé.".yellow());
        return Ok(());
    }

    let plan = build_rename_plan(
        &file_paths,
        &regex,
        &args.replacement,
        args.start,
        args.step,
        args.pad,
    )?;

    if plan.is_empty() {
        println!("{}", "Aucun fichier sélectionné.".yellow());
        return Ok(());
    }

    print_preview(&plan, is_dry_run);

    if is_dry_run {
        println!(
            "\n{}",
            "Mode prévisualisation activé. Aucun fichier n'a été modifié."
                .cyan()
                .bold()
        );
        println!(
            "Pour appliquer les modifications réelles, ajoutez le drapeau '{}' ou '{}'.",
            "-x".green(),
            "--execute".green()
        );
        return Ok(());
    }

    execute_renames(&plan)?;
    println!("\n{}", "✓ Renommage terminé avec succès.".green().bold());

    Ok(())
}

/// Collecte et résout tous les chemins de fichiers passés en argument ou via motif glob.
fn collect_files(inputs: &[String]) -> Result<Vec<PathBuf>> {
    let mut resolved_paths = HashSet::new();

    for input in inputs {
        let mut matches_found = false;
        if let Ok(entries) = glob::glob(input) {
            for entry in entries.flatten() {
                if entry.is_file() {
                    resolved_paths.insert(entry);
                    matches_found = true;
                }
            }
        }

        if !matches_found {
            let path = PathBuf::from(input);
            if path.is_file() {
                resolved_paths.insert(path);
            }
        }
    }

    let mut sorted_list: Vec<PathBuf> = resolved_paths.into_iter().collect();
    sorted_list.sort();
    Ok(sorted_list)
}

/// Construit et valide l'ensemble du plan de renommage en vérifiant les collisions et écrasements.
fn build_rename_plan(
    files: &[PathBuf],
    regex: &Regex,
    replacement_template: &str,
    start: usize,
    step: usize,
    pad: usize,
) -> Result<Vec<RenamePlan>> {
    let mut plans = Vec::with_capacity(files.len());
    let mut current_seq = start;
    let mut destination_counts: HashMap<PathBuf, Vec<PathBuf>> = HashMap::new();

    for source in files {
        let parent = source.parent().unwrap_or_else(|| Path::new(""));
        let original_name = source
            .file_name()
            .and_then(|n| n.to_str())
            .with_context(|| format!("Nom de fichier invalide (non-UTF8) : {:?}", source))?;

        if !regex.is_match(original_name) {
            // Le motif ne correspond pas, le fichier est ignoré ou conservé inchangé
            continue;
        }

        // Remplacement du motif séquentiel {seq}
        let seq_str = format!("{:0>width$}", current_seq, width = pad);
        let expanded_template = replacement_template.replace("{seq}", &seq_str);

        // Application de l'expression régulière (supporte $1, $2, etc.)
        let new_name = regex
            .replace_all(original_name, expanded_template.as_str())
            .to_string();

        let destination = if parent.as_os_str().is_empty() {
            PathBuf::from(&new_name)
        } else {
            parent.join(&new_name)
        };

        let has_changed = destination != *source;

        if has_changed {
            destination_counts
                .entry(destination.clone())
                .or_default()
                .push(source.clone());
            current_seq = current_seq.saturating_add(step);
        }

        plans.push(RenamePlan {
            source: source.clone(),
            destination,
            has_changed,
        });
    }

    // Détection des collisions internes (deux fichiers sources vers la même cible)
    for (dest, sources) in &destination_counts {
        if sources.len() > 1 {
            let sources_str = sources
                .iter()
                .map(|p| p.display().to_string())
                .collect::<Vec<_>>()
                .join(", ");
            bail!(
                "Collision détectée : plusieurs fichiers sources mènent vers '{}' : [{}]",
                dest.display(),
                sources_str
            );
        }
    }

    // Détection d'écrasement de fichiers déjà présents sur le disque
    let all_sources: HashSet<&PathBuf> = files.iter().collect();
    for plan in &plans {
        if plan.has_changed && plan.destination.exists() && !all_sources.contains(&plan.destination)
        {
            bail!(
                "Conflit de destination : la cible '{}' existe déjà sur le disque et serait écrasée.",
                plan.destination.display()
            );
        }
    }

    Ok(plans)
}

/// Affiche un résumé colorisé du plan de renommage.
fn print_preview(plan: &[RenamePlan], is_dry_run: bool) {
    let mode_str = if is_dry_run {
        "[DRY-RUN]".yellow().bold()
    } else {
        "[EXECUTE]".green().bold()
    };

    println!("\n{} Plan d'action pour {} fichier(s) :", mode_str, plan.len());

    let mut changed_count = 0;
    for item in plan {
        if item.has_changed {
            changed_count += 1;
            println!(
                "  {} {} {}",
                item.source.display().to_string().red(),
                "->".bold(),
                item.destination.display().to_string().green()
            );
        } else {
            println!(
                "  {} (aucun changement)",
                item.source.display().to_string().dimmed()
            );
        }
    }

    println!(
        "\nTotal : {} modifié(s), {} inchangé(s)",
        changed_count.to_string().green().bold(),
        (plan.len() - changed_count).to_string().dimmed()
    );
}

/// Applique les renommages de manière ordonnée et sécurisée.
fn execute_renames(plan: &[RenamePlan]) -> Result<()> {
    for item in plan {
        if item.has_changed {
            fs::rename(&item.source, &item.destination).with_context(|| {
                format!(
                    "Échec du renommage de '{}' vers '{}'",
                    item.source.display(),
                    item.destination.display()
                )
            })?;
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_sequential_padding_and_replacement() {
        let files = vec![
            PathBuf::from("img_a.png"),
            PathBuf::from("img_b.png"),
            PathBuf::from("img_c.png"),
        ];
        let regex = Regex::new(r"img_([a-z])\.png").unwrap();
        let plan = build_rename_plan(&files, &regex, "photo_{seq}_$1.png", 1, 2, 3).unwrap();

        assert_eq!(plan.len(), 3);
        assert_eq!(plan[0].destination, PathBuf::from("photo_001_a.png"));
        assert_eq!(plan[1].destination, PathBuf::from("photo_003_b.png"));
        assert_eq!(plan[2].destination, PathBuf::from("photo_005_c.png"));
    }

    #[test]
    fn test_internal_collision_detection() {
        let files = vec![
            PathBuf::from("file1.txt"),
            PathBuf::from("file2.txt"),
        ];
        let regex = Regex::new(r"file\d\.txt").unwrap();
        // Les deux sources produiraient le même nom fixe sans {seq}
        let result = build_rename_plan(&files, &regex, "constant.txt", 1, 1, 1);
        assert!(result.is_err());
        assert!(result.unwrap_err().to_string().contains("Collision"));
    }
}

