/// Rapport complet sérialisable
#[derive(Debug, Clone, Serialize)]
pub struct BenchmarkReport {
    pub total_commands: usize,
    pub target_runs_per_command: usize,
    pub warmup_runs: usize,
    pub results: Vec<BenchmarkStats>,
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    if cli.runs == 0 {
        bail!("L'option --runs doit être supérieure ou égale à 1.");
    }
    if cli.commands.is_empty() {
        bail!("Aucune commande n'a été spécifiée pour le benchmark.");
    }

    let default_shell = if cfg!(target_os = "windows") {
        vec!["cmd".to_string(), "/C".to_string()]
    } else {
        vec!["sh".to_string(), "-c".to_string()]
    };

    let shell_cmd = match &cli.custom_shell {
        Some(s) => s.split_whitespace().map(|x| x.to_string()).collect(),
        None => default_shell,
    };

    if shell_cmd.is_empty() {
        bail!("Le shell spécifié est vide.");
    }

    eprintln!(
        "{} Lancement du benchmark pour {} commande(s) (chauffe: {}, mesures: {} par commande)...\n",
        "==>".bold().green(),
        cli.commands.len(),
        cli.warmup,
        cli.runs
    );

    let progress_bar = ProgressBar::new((cli.commands.len() * (cli.warmup + cli.runs)) as u64);
    progress_bar.set_style(
        ProgressStyle::default_bar()
            .template("{spinner:.green} [{elapsed_precise}] [{bar:40.cyan/blue}] {pos}/{len} {msg}")
            .with_context(|| "Erreur lors de la configuration du template indicatif")?
            .progress_chars("#>-"),
    );

    let mut command_stats = Vec::new();

    for cmd_str in &cli.commands {
        // Phases de warmup
        for i in 0..cli.warmup {
            progress_bar.set_message(format!(
                "Chauffe {}/{} : {}",
                i + 1,
                cli.warmup,
                truncate_cmd(cmd_str, 25)
            ));
            let _ = execute_monitored_command(cmd_str, &shell_cmd, cli.show_output);
            progress_bar.inc(1);
        }

        // Phases de mesures
        let mut samples = Vec::with_capacity(cli.runs);
        for i in 0..cli.runs {
            progress_bar.set_message(format!(
                "Mesure {}/{} : {}",
                i + 1,
                cli.runs,
                truncate_cmd(cmd_str, 25)
            ));
            let sample = execute_monitored_command(cmd_str, &shell_cmd, cli.show_output)
                .with_context(|| format!("Erreur lors de l'exécution de: {}", cmd_str))?;

            if !sample.success && !cli.ignore_errors {
                progress_bar.finish_and_clear();
                bail!(
                    "La commande '{}' a échoué avec le code de sortie {}. Utilisez --ignore-errors pour continuer malgré tout.",
                    cmd_str,
                    sample.exit_code
                );
            }

            samples.push(sample);
            progress_bar.inc(1);
        }

        let stats = compute_statistics(cmd_str.clone(), &samples);
        command_stats.push(stats);
    }

    progress_bar.finish_and_clear();

    // Calcul des ratios relatifs
    calculate_relative_metrics(&mut command_stats);

    let report = BenchmarkReport {
        total_commands: command_stats.len(),
        target_runs_per_command: cli.runs,
        warmup_runs: cli.warmup,
        results: command_stats,
    };

    let rendered_output = match cli.format {
        OutputFormat::Table => render_table(&report),
        OutputFormat::Markdown => render_markdown(&report),
        OutputFormat::Json => {
            serde_json::to_string_pretty(&report).context("Erreur de sérialisation JSON")?
        }
        OutputFormat::Csv => render_csv(&report),
    };

    println!("{}", rendered_output);

    if let Some(path) = cli.output_file {
        let mut file = File::create(&path)
            .with_context(|| format!("Impossible de créer le fichier {}", path.display()))?;
        file.write_all(rendered_output.as_bytes())
            .with_context(|| format!("Impossible d'écrire dans le fichier {}", path.display()))?;
        eprintln!(
            "\n{} Rapport de benchmark exporté avec succès dans: {}",
            "✓".bold().green(),
            path.display()
        );
    }

    Ok(())
}

/// Tronque une chaîne pour l'affichage de progression
fn truncate_cmd(cmd: &str, max_len: usize) -> String {
    if cmd.len() > max_len {
        format!("{}...", &cmd[..max_len.saturating_sub(3)])
    } else {
        cmd.to_string()
    }
}

/// Exécute une commande shell et mesure la durée et le pic mémoire
#[cfg(unix)]
fn execute_monitored_command(
    cmd_str: &str,
    shell: &[String],
    show_output: bool,
) -> Result<RunSample> {
    let mut command = Command::new(&shell[0]);
    if shell.len() > 1 {
        command.args(&shell[1..]);
    }
    command.arg(cmd_str);

    if !show_output {
        command.stdout(Stdio::null());
        command.stderr(Stdio::null());
    }

    let start_time = Instant::now();
    let child = command
        .spawn()
        .with_context(|| format!("Échec du spawn du processus: {:?}", shell))?;

    let pid = child.id() as libc::pid_t;
    let mut status: libc::c_int = 0;
    let mut usage: libc::rusage = unsafe { std::mem::zeroed() };

    let mut wait_res;
    loop {
        wait_res = unsafe { libc::wait4(pid, &mut status, 0, &mut usage) };
        if wait_res == -1 {
            let err = std::io::Error::last_os_error();
            if err.raw_os_error() == Some(libc::EINTR) {
                continue;
            }
            return Err(err).context("Erreur lors de l'appel système wait4");
        }
        break;
    }

    let duration = start_time.elapsed();
    let duration_seconds = duration.as_secs_f64();

    let exit_code = if libc::WIFEXITED(status) {
        libc::WEXITSTATUS(status)
    } else if libc::WIFSIGNALED(status) {
        128 + libc::WTERMSIG(status)
    } else {
        -1
    };

    // Conversion du RSS en octets
    // Sur Linux: ru_maxrss est exprimé en Kilooctets (KiB)
    // Sur macOS/Darwin: ru_maxrss est exprimé en Octets
    let max_rss_bytes = if cfg!(target_os = "macos") {
        usage.ru_maxrss as u64
    } else {
        (usage.ru_maxrss as u64).saturating_mul(1024)
    };

    Ok(RunSample {
        duration_seconds,
        max_rss_bytes,
        exit_code,
        success: exit_code == 0,
    })
}

/// Fallback pour les plateformes non-Unix
#[cfg(not(unix))]
fn execute_monitored_command(
    cmd_str: &str,
    shell: &[String],
    show_output: bool,
) -> Result<RunSample> {
    let mut command = Command::new(&shell[0]);
    if shell.len() > 1 {
        command.args(&shell[1..]);
    }
    command.arg(cmd_str);

    if !show_output {
        command.stdout(Stdio::null());
        command.stderr(Stdio::null());
    }

    let start_time = Instant::now();
    let mut child = command.spawn().context("Échec du spawn du processus")?;
    let exit_status = child.wait().context("Échec lors de l'attente du processus")?;
    let duration = start_time.elapsed();

    let exit_code = exit_status.code().unwrap_or(-1);

    Ok(RunSample {
        duration_seconds: duration.as_secs_f64(),
        max_rss_bytes: 0,
        exit_code,
        success: exit_status.success(),
    })
}

/// Calcule les statistiques descriptives à partir des échantillons collectés
fn compute_statistics(command: String, samples: &[RunSample]) -> BenchmarkStats {
    let runs = samples.len();
    let successful_runs = samples.iter().filter(|s| s.success).count();
    let failed_runs = runs.saturating_sub(successful_runs);

    let mut durations: Vec<f64> = samples.iter().map(|s| s.duration_seconds).collect();
    let mut mem_usages: Vec<f64> = samples.iter().map(|s| s.max_rss_bytes as f64).collect();

    durations.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    mem_usages.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));

    let min_duration_sec = durations.first().copied().unwrap_or(0.0);
    let max_duration_sec = durations.last().copied().unwrap_or(0.0);
    let median_duration_sec = calculate_median(&durations);

    let mean_duration_sec = if runs > 0 {
        durations.iter().sum::<f64>() / runs as f64
    } else {
        0.0
    };

    let stddev_duration_sec = if runs > 1 {
        let variance = durations
            .iter()
            .map(|&d| (d - mean_duration_sec).powi(2))
            .sum::<f64>()
            / (runs - 1) as f64;
        variance.sqrt()
    } else {
        0.0
    };

    let min_rss_bytes = mem_usages.first().map(|&v| v as u64).unwrap_or(0);
    let max_rss_bytes = mem_usages.last().map(|&v| v as u64).unwrap_or(0);
    let median_rss_bytes = calculate_median(&mem_usages);

    let mean_rss_bytes = if runs > 0 {
        mem_usages.iter().sum::<f64>() / runs as f64
    } else {
        0.0
    };

    let stddev_rss_bytes = if runs > 1 {
        let variance = mem_usages
            .iter()
            .map(|&m| (m - mean_rss_bytes).powi(2))
            .sum::<f64>()
            / (runs - 1) as f64;
        variance.sqrt()
    } else {
        0.0
    };

    BenchmarkStats {
        command,
        runs,
        successful_runs,
        failed_runs,
        mean_duration_sec,
        stddev_duration_sec,
        min_duration_sec,
        max_duration_sec,
        median_duration_sec,
        mean_rss_bytes,
        stddev_rss_bytes,
        min_rss_bytes,
        max_rss_bytes,
        median_rss_bytes,
        relative_time: None,
        relative_memory: None,
    }
}

/// Calcule la médiane d'une liste ordonnée
fn calculate_median(sorted: &[f64]) -> f64 {
    let len = sorted.len();
    if len == 0 {
        return 0.0;
    }
    if len % 2 == 1 {
        sorted[len / 2]
    } else {
        (sorted[(len / 2) - 1] + sorted[len / 2]) / 2.0
    }
}

/// Normalise les métriques par rapport à la commande la plus rapide / sobre
fn calculate_relative_metrics(stats: &mut [BenchmarkStats]) {
    let min_mean_time = stats
        .iter()
        .map(|s| s.mean_duration_sec)
        .filter(|&t| t > 0.0)
        .fold(f64::INFINITY, f64::min);

    let min_mean_mem = stats
        .iter()
        .map(|s| s.mean_rss_bytes)
        .filter(|&m| m > 0.0)
        .fold(f64::INFINITY, f64::min);

    for s in stats.iter_mut() {
        if min_mean_time.is_finite() && min_mean_time > 0.0 {
            s.relative_time = Some(s.mean_duration_sec / min_mean_time);
        }
        if min_mean_mem.is_finite() && min_mean_mem > 0.0 {
            s.relative_memory = Some(s.mean_rss_bytes / min_mean_mem);
        }
    }
}

/// Formate une durée en chaîne lisible
fn format_duration(seconds: f64) -> String {
    let d = Duration::from_secs_f64(seconds);
    if d.as_secs() >= 60 {
        let mins = d.as_secs() / 60;
        let secs = seconds - (mins as f64 * 60.0);
        format!("{}m {:.2}s", mins, secs)
    } else if d.as_secs() >= 1 {
        format!("{:.3} s", seconds)
    } else if d.as_millis() >= 1 {
        format!("{:.2} ms", seconds * 1000.0)
    } else {
        format!("{:.2} µs", seconds * 1_000_000.0)
    }
}

/// Formate une taille en octets en unité intelligible (B, KiB, MiB, GiB)
fn format_bytes(bytes: f64) -> String {
    const KIB: f64 = 1024.0;
    const MIB: f64 = 1024.0 * 1024.0;
    const GIB: f64 = 1024.0 * 1024.0 * 1024.0;

    if bytes >= GIB {
        format!("{:.2} GiB", bytes / GIB)
    } else if bytes >= MIB {
        format!("{:.2} MiB", bytes / MIB)
    } else if bytes >= KIB {
        format!("{:.2} KiB", bytes / KIB)
    } else {
        format!("{:.0} B", bytes)
    }
}

/// Rendu du tableau terminal via comfy-table
fn render_table(report: &BenchmarkReport) -> String {
    let mut table = Table::new();
    table
        .load_preset(UTF8_FULL)
        .apply_modifier(UTF8_ROUND_CORNERS)
        .set_content_arrangement(ContentArrangement::Dynamic);

    table.set_header(vec![
        Cell::new("Commande").set_alignment(CellAlignment::Left),
        Cell::new("Temps (Moyenne ± σ)").set_alignment(CellAlignment::Right),
        Cell::new("Min … Max").set_alignment(CellAlignment::Right),
        Cell::new("Ratio Temps").set_alignment(CellAlignment::Center),
        Cell::new("Mémoire RSS (Pic Moy)").set_alignment(CellAlignment::Right),
        Cell::new("Pic Min … Max").set_alignment(CellAlignment::Right),
        Cell::new("Ratio Mém").set_alignment(CellAlignment::Center),
        Cell::new("Succès").set_alignment(CellAlignment::Center),
    ]);

    for s in &report.results {
        let time_str = format!(
            "{} ± {}",
            format_duration(s.mean_duration_sec),
            format_duration(s.stddev_duration_sec)
        );
        let time_range = format!(
            "{} … {}",
            format_duration(s.min_duration_sec),
            format_duration(s.max_duration_sec)
        );
        let rel_time_str = match s.relative_time {
            Some(r) if (r - 1.0).abs() < 0.001 => "1.00x (base)".to_string(),
            Some(r) => format!("{:.2}x", r),
            None => "-".to_string(),
        };

        let mem_str = format_bytes(s.mean_rss_bytes);
        let mem_range = format!(
            "{} … {}",
            format_bytes(s.min_rss_bytes as f64),
            format_bytes(s.max_rss_bytes as f64)
        );
        let rel_mem_str = match s.relative_memory {
            Some(r) if (r - 1.0).abs() < 0.001 => "1.00x (base)".to_string(),
            Some(r) => format!("{:.2}x", r),
            None => "-".to_string(),
        };

        let success_rate = format!("{}/{}", s.successful_runs, s.runs);

        table.add_row(Row::from(vec![
            Cell::new(&s.command),
            Cell::new(time_str).set_alignment(CellAlignment::Right),
            Cell::new(time_range).set_alignment(CellAlignment::Right),
            Cell::new(rel_time_str).set_alignment(CellAlignment::Center),
            Cell::new(mem_str).set_alignment(CellAlignment::Right),
            Cell::new(mem_range).set_alignment(CellAlignment::Right),
            Cell::new(rel_mem_str).set_alignment(CellAlignment::Center),
            Cell::new(success_rate).set_alignment(CellAlignment::Center),
        ]));
    }

    table.to_string()
}

/// Rendu au format Markdown
fn render_markdown(report: &BenchmarkReport) -> String {
    let mut out = String::new();
    out.push_str("# Résultat du Benchmark\n\n");
    out.push_str(&format!(
        "- **Itérations par commande** : {}\n",
        report.target_runs_per_command
    ));
    out.push_str(&format!(
        "- **Itérations de chauffe (warmup)** : {}\n\n",
        report.warmup_runs
    ));

    out.push_str("| Commande | Temps (Moy ± Ect) | Min … Max | Ratio Tps | Pic RSS Moy | Min … Max | Ratio Mém | Succès |\n");
    out.push_str("| :--- | ---: | ---: | :---: | ---: | ---: | :---: | :---: |\n");

    for s in &report.results {
        let time_str = format!(
            "{} ± {}",
            format_duration(s.mean_duration_sec),
            format_duration(s.stddev_duration_sec)
        );
        let time_range = format!(
            "{} … {}",
            format_duration(s.min_duration_sec),
            format_duration(s.max_duration_sec)
        );
        let rel_time = s
            .relative_time
            .map(|r| format!("{:.2}x", r))
            .unwrap_or_else(|| "-".to_string());
        let mem_str = format_bytes(s.mean_rss_bytes);
        let mem_range = format!(
            "{} … {}",
            format_bytes(s.min_rss_bytes as f64),
            format_bytes(s.max_rss_bytes as f64)
        );
        let rel_mem = s
            .relative_memory
            .map(|r| format!("{:.2}x", r))
            .unwrap_or_else(|| "-".to_string());
        let success = format!("{}/{}", s.successful_runs, s.runs);

        out.push_str(&format!(
            "| `{}` | {} | {} | {} | {} | {} | {} | {} |\n",
            s.command.replace('|', "\\|"),
            time_str,
            time_range,
            rel_time,
            mem_str,
            mem_range,
            rel_mem,
            success
        ));
    }

    out
}

/// Rendu au format CSV
fn render_csv(report: &BenchmarkReport) -> String {
    let mut out = String::new();
    out.push_str("command,runs,successful_runs,failed_runs,mean_duration_sec,stddev_duration_sec,min_duration_sec,max_duration_sec,median_duration_sec,mean_rss_bytes,stddev_rss_bytes,min_rss_bytes,max_rss_bytes,median_rss_bytes,relative_time,relative_memory\n");

    for s in &report.results {
        out.push_str(&format!(
            "\"{}\",{},{},{},{:.6},{:.6},{:.6},{:.6},{:.6},{:.0},{:.0},{},{},{:.0},{},{}\n",
            s.command.replace('"', "\"\""),
            s.runs,
            s.successful_runs,
            s.failed_runs,
            s.mean_duration_sec,
            s.stddev_duration_sec,
            s.min_duration_sec,
            s.max_duration_sec,
            s.median_duration_sec,
            s.mean_rss_bytes,
            s.stddev_rss_bytes,
            s.min_rss_bytes,
            s.max_rss_bytes,
            s.median_rss_bytes,
            s.relative_time
                .map(|r| format!("{:.4}", r))
                .unwrap_or_default(),
            s.relative_memory
                .map(|r| format!("{:.4}", r))
                .unwrap_or_default()
        ));
    }

    out
}

