// src/main.rs
use std::fs::{self, File};
use std::io::{self, BufReader, BufWriter, Read, Write};
use std::path::{Path, PathBuf};
use std::time::SystemTime;

use anyhow::{Context, Result};
use chrono::{DateTime, Utc};
use clap::{Args, Parser, Subcommand};
use flate2::read::GzDecoder;
use flate2::write::GzEncoder;
use flate2::Compression;
use tracing::{info, warn};
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt, EnvFilter};
use walkdir::WalkDir;

#[derive(Parser, Debug)]
#[command(name = "log-rotator")]
#[command(author, version, about = "CLI d'agrégation, rotation et purge de logs avec compression Gzip", long_about = None)]
struct Cli {
    #[command(subcommand)]
    command: Commands,

    /// Activer le mode verbeux (logs DEBUG)
    #[arg(short, long, global = true)]
    verbose: bool,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Compresser les fichiers de logs inactifs en .gz
    Rotate(RotateArgs),

    /// Purger les archives .gz dépassant un seuil d'âge en jours
    Purge(PurgeArgs),

    /// Agréger plusieurs fichiers de logs dans une archive Gzip consolidée
    Aggregate(AggregateArgs),

    /// Pipeline complet : rotation (compression) des logs puis purge des anciennes archives
    Run(RunArgs),
}

#[derive(Args, Debug)]
struct RotateArgs {
    /// Répertoire contenant les fichiers de log
    #[arg(short, long, default_value = ".")]
    dir: PathBuf,

    /// Extension cible des logs bruts à compresser (ex: log)
    #[arg(short, long, default_value = "log")]
    extension: String,

    /// Âge minimal en jours d'inactivité avant compression (0 = tous les fichiers non compressés)
    #[arg(short, long, default_value_t = 0)]
    min_age_days: u64,

    /// Supprimer le fichier source après compression réussie
    #[arg(long, default_value_t = true)]
    remove_source: bool,

    /// Niveau de compression Gzip de 1 (rapide) à 9 (meilleur)
    #[arg(long, default_value_t = 6)]
    compression_level: u32,

    /// Simuler les opérations sans modifier le disque
    #[arg(long)]
    dry_run: bool,
}

#[derive(Args, Debug)]
struct PurgeArgs {
    /// Répertoire contenant les archives de log
    #[arg(short, long, default_value = ".")]
    dir: PathBuf,

    /// Âge maximal de rétention en jours au-delà duquel les fichiers sont supprimés
    #[arg(short = 'm', long)]
    max_age_days: u64,

    /// Extension ciblée pour la purge (ex: gz)
    #[arg(short, long, default_value = "gz")]
    extension: String,

    /// Simuler la suppression sans modifier le disque
    #[arg(long)]
    dry_run: bool,
}

#[derive(Args, Debug)]
struct AggregateArgs {
    /// Répertoire contenant les fichiers de log à agréger
    #[arg(short, long, default_value = ".")]
    dir: PathBuf,

    /// Extension des fichiers de log à agréger
    #[arg(short, long, default_value = "log")]
    extension: String,

    /// Chemin du fichier d'archive compressée résultant (ex: logs_agreges.log.gz)
    #[arg(short, long)]
    output: PathBuf,

    /// Supprimer les fichiers sources après une agrégation réussie
    #[arg(long)]
    remove_source: bool,

    /// Simuler l'agrégation sans modifier le disque
    #[arg(long)]
    dry_run: bool,
}

#[derive(Args, Debug)]
struct RunArgs {
    /// Répertoire contenant les logs
    #[arg(short, long, default_value = ".")]
    dir: PathBuf,

    /// Extension des logs bruts à compresser
    #[arg(short, long, default_value = "log")]
    extension: String,

    /// Âge minimal en jours pour la rotation/compression
    #[arg(long, default_value_t = 1)]
    rotate_age_days: u64,

    /// Âge maximal de rétention en jours avant purge définitive
    #[arg(short = 'm', long, default_value_t = 30)]
    max_age_days: u64,

    /// Simuler sans modifier le disque
    #[arg(long)]
