}

fn main() -> Result<()> {
    let cli = Cli::parse();

    init_logging(cli.verbose)?;

    match cli.command {
        Commands::Rotate(args) => handle_rotate(args)?,
        Commands::Purge(args) => handle_purge(args)?,
        Commands::Aggregate(args) => handle_aggregate(args)?,
        Commands::Run(args) => {
            info!("--- Étape 1 : Rotation et compression ---");
            let rotate_args = RotateArgs {
                dir: args.dir.clone(),
                extension: args.extension,
                min_age_days: args.rotate_age_days,
                remove_source: true,
                compression_level: 6,
                dry_run: args.dry_run,
            };
            handle_rotate(rotate_args)?;

            info!("--- Étape 2 : Purge des logs expirés ---");
            let purge_args = PurgeArgs {
                dir: args.dir,
                max_age_days: args.max_age_days,
                extension: "gz".to_string(),
                dry_run: args.dry_run,
            };
            handle_purge(purge_args)?;
        }
    }

    Ok(())
}

fn init_logging(verbose: bool) -> Result<()> {
    let filter = if verbose {
        EnvFilter::new("debug")
    } else {
        EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info"))
    };

    tracing_subscriber::registry()
        .with(filter)
        .with(tracing_subscriber::fmt::layer())
        .try_init()
        .map_err(|e| anyhow::anyhow!("Impossible d'initialiser le logger: {e}"))?;

    Ok(())
}

/// Calcule l'âge d'un fichier en jours basé sur sa date de modification (mtime).
fn get_file_age_days(metadata: &fs::Metadata) -> Option<u64> {
    let modified = metadata.modified().ok()?;
    let now = SystemTime::now();

    if let Ok(duration) = now.duration_since(modified) {
        Some(duration.as_secs() / 86400)
    } else {
        None
    }
}

/// Compresse un fichier unique avec Gzip et préserve l'intégrité par écriture atomique (via .tmp).
fn compress_file(source: &Path, destination: &Path, level: Compression) -> Result<()> {
    let temp_dest = destination.with_extension("tmp");

    let input_file = File::open(source)
        .with_context(|| format!("Impossible d'ouvrir le fichier source '{}'", source.display()))?;
    let mut reader = BufReader::new(input_file);

    let output_file = File::create(&temp_dest).with_context(|| {
        format!(
            "Impossible de créer le fichier temporaire '{}'",
            temp_dest.display()
        )
    })?;
    let writer = BufWriter::new(output_file);
    let mut encoder = GzEncoder::new(writer, level);

    io::copy(&mut reader, &mut encoder).with_context(|| {
        format!(
            "Erreur lors de la compression de '{}' vers '{}'",
            source.display(),
            temp_dest.display()
        )
    })?;

    let mut writer = encoder.finish().context("Erreur lors de la finalisation du flux Gzip")?;
    writer.flush().context("Erreur lors du vidage du tampon d'écriture")?;

    fs::rename(&temp_dest, destination).with_context(|| {
        format!(
            "Impossible de renommer '{}' vers '{}'",
            temp_dest.display(),
            destination.display()
        )
    })?;

    Ok(())
}

fn handle_rotate(args: RotateArgs) -> Result<()> {
    info!(
        directory = %args.dir.display(),
        extension = %args.extension,
        min_age_days = args.min_age_days,
        dry_run = args.dry_run,
        "Démarrage de la rotation/compression des logs"
    );

    let target_ext = args.extension.trim_start_matches('.');
    let mut processed_count = 0usize;

    for entry in WalkDir::new(&args.dir).into_iter().filter_map(|e| e.ok()) {
        let path = entry.path();
        if !path.is_file() {
            continue;
        }

        // Ignorer les fichiers déjà compressés
        if let Some(ext) = path.extension().and_then(|s| s.to_str()) {
            if ext.eq_ignore_ascii_case("gz") {
                continue;
            }
            if !ext.eq_ignore_ascii_case(target_ext) {
                continue;
            }
        } else {
            continue;
        }

        let metadata = match fs::metadata(path) {
            Ok(m) => m,
            Err(e) => {
                warn!(path = %path.display(), error = %e, "Impossible de lire les métadonnées");
                continue;
            }
        };

        let age_days = get_file_age_days(&metadata).unwrap_or(0);
        if age_days < args.min_age_days {
            continue;
        }

        let dest_filename = format!(
            "{}.gz",
            path.file_name()
                .and_then(|n| n.to_str())
                .unwrap_or("log_archive")
        );
        let dest_path = path.with_file_name(dest_filename);

        info!(
            source = %path.display(),
            destination = %dest_path.display(),
            age_days = age_days,
            "Compression du fichier journal"
        );

        if !args.dry_run {
            let compression = Compression::new(args.compression_level.clamp(1, 9));
            compress_file(path, &dest_path, compression)?;

            if args.remove_source {
                fs::remove_file(path).with_context(|| {
                    format!("Impossible de supprimer le fichier source '{}'", path.display())
                })?;
            }
        }

        processed_count += 1;
    }

    info!(total = processed_count, "Rotation terminée avec succès");
    Ok(())
}

fn handle_purge(args: PurgeArgs) -> Result<()> {
    info!(
        directory = %args.dir.display(),
        max_age_days = args.max_age_days,
        extension = %args.extension,
        dry_run = args.dry_run,
        "Démarrage de la purge des archives obsolètes"
    );

    let target_ext = args.extension.trim_start_matches('.');
    let mut deleted_count = 0usize;

    for entry in WalkDir::new(&args.dir).into_iter().filter_map(|e| e.ok()) {
        let path = entry.path();
        if !path.is_file() {
            continue;
        }

        let is_target = path
            .extension()
            .and_then(|s| s.to_str())
            .map(|ext| ext.eq_ignore_ascii_case(target_ext))
            .unwrap_or(false);

        if !is_target {
            continue;
        }

        let metadata = match fs::metadata(path) {
            Ok(m) => m,
            Err(e) => {
                warn!(path = %path.display(), error = %e, "Impossible de lire les métadonnées");
                continue;
            }
        };

        if let Some(age_days) = get_file_age_days(&metadata) {
            if age_days >= args.max_age_days {
                info!(
                    path = %path.display(),
                    age_days = age_days,
                    max_age = args.max_age_days,
                    "Purge du fichier expiré"
                );

                if !args.dry_run {
                    fs::remove_file(path).with_context(|| {
                        format!("Échec de la suppression de '{}'", path.display())
                    })?;
                }
                deleted_count += 1;
            }
        }
    }

    info!(total_purged = deleted_count, "Purge terminée avec succès");
    Ok(())
}

fn handle_aggregate(args: AggregateArgs) -> Result<()> {
    info!(
        directory = %args.dir.display(),
        target_extension = %args.extension,
        output = %args.output.display(),
        dry_run = args.dry_run,
        "Démarrage de l'agrégation des fichiers de logs"
    );

    let target_ext = args.extension.trim_start_matches('.');
    let mut files_to_aggregate = Vec::new();

    for entry in WalkDir::new(&args.dir).into_iter().filter_map(|e| e.ok()) {
        let path = entry.path();
        if !path.is_file() {
            continue;
        }

        // Éviter d'agréger le fichier de sortie s'il se trouve dans le même dossier
        if path == args.output {
            continue;
        }

        let matches = path
            .extension()
            .and_then(|s| s.to_str())
            .map(|ext| ext.eq_ignore_ascii_case(target_ext))
            .unwrap_or(false);

        if matches {
            files_to_aggregate.push(path.to_path_buf());
        }
    }

    // Tri pour un ordre déterministe
    files_to_aggregate.sort();

    info!(
        count = files_to_aggregate.len(),
        "Fichiers identifiés pour l'agrégation"
    );

    if files_to_aggregate.is_empty() {
        warn!("Aucun fichier correspondant trouvé à agréger");
        return Ok(());
    }

    if args.dry_run {
        for file in &files_to_aggregate {
            info!(path = %file.display(), "[Dry-Run] Fichier à concaténer dans l'archive");
        }
        return Ok(());
    }

    if let Some(parent) = args.output.parent() {
        if !parent.as_os_str().is_empty() {
            fs::create_dir_all(parent).with_context(|| {
                format!(
                    "Impossible de créer le répertoire parent '{}'",
                    parent.display()
                )
            })?;
        }
    }

    let temp_output = args.output.with_extension("tmp");
    let out_file = File::create(&temp_output).with_context(|| {
        format!(
            "Impossible de créer le fichier d'archive temporaire '{}'",
            temp_output.display()
        )
    })?;
    let mut encoder = GzEncoder::new(BufWriter::new(out_file), Compression::default());

    let mut buffer = [0u8; 64 * 1024];

    for file_path in &files_to_aggregate {
        info!(path = %file_path.display(), "Agrégation du fichier");

        // Écriture d'un en-tête délimitant chaque fichier agrégé
        let header = format!(
            "\n--- DEBUT DU JOURNAL: {} ({}) ---\n",
            file_path.file_name().unwrap_or_default().to_string_lossy(),
            DateTime::<Utc>::from(
                fs::metadata(file_path)
                    .and_then(|m| m.modified())
                    .unwrap_or_else(|_| SystemTime::now())
            )
            .to_rfc3339()
        );
        encoder
            .write_all(header.as_bytes())
            .context("Erreur d'écriture de l'en-tête de délimitation dans l'archive")?;

        let is_gz = file_path
            .extension()
            .and_then(|s| s.to_str())
            .map(|ext| ext.eq_ignore_ascii_case("gz"))
            .unwrap_or(false);

        let file = File::open(file_path).with_context(|| {
            format!("Erreur lors de l'ouverture de '{}'", file_path.display())
        })?;

        if is_gz {
            let mut decoder = GzDecoder::new(BufReader::new(file));
            loop {
                let bytes_read = decoder
                    .read(&mut buffer)
                    .with_context(|| format!("Erreur de décompression de '{}'", file_path.display()))?;
                if bytes_read == 0 {
                    break;
                }
                encoder
                    .write_all(&buffer[..bytes_read])
                    .context("Erreur d'écriture du contenu décompressé dans l'archive")?;
            }
        } else {
            let mut reader = BufReader::new(file);
            loop {
                let bytes_read = reader
                    .read(&mut buffer)
                    .with_context(|| format!("Erreur de lecture de '{}'", file_path.display()))?;
                if bytes_read == 0 {
                    break;
                }
                encoder
                    .write_all(&buffer[..bytes_read])
                    .context("Erreur d'écriture dans l'archive consolidée")?;
            }
        }
    }

    let mut writer = encoder
        .finish()
        .context("Échec de la clôture de compression Gzip de l'archive consolidée")?;
    writer.flush().context("Échec du vidage du tampon d'archive")?;

    fs::rename(&temp_output, &args.output).with_context(|| {
        format!(
            "Impossible de déplacer le fichier temporaire '{}' vers '{}'",
            temp_output.display(),
            args.output.display()
        )
    })?;

    if args.remove_source {
        for file_path in &files_to_aggregate {
            fs::remove_file(file_path).with_context(|| {
                format!(
                    "Impossible de supprimer le fichier source consolidé '{}'",
                    file_path.display()
                )
            })?;
        }
    }

    info!(
        output = %args.output.display(),
        total_files = files_to_aggregate.len(),
        "Agrégation compressée terminée avec succès"
    );
    Ok(())
}

