fn determine_next_version(
    current: &Version,
    target: &BumpTarget,
    commits: &[CommitInfo],
) -> Result<Version> {
    match target {
        BumpTarget::Exact(v) => {
            if v <= current {
                bail!(
                    "La nouvelle version demandée ({}) doit être strictement supérieure à la version actuelle ({})",
                    v,
                    current
                );
            }
            Ok(v.clone())
        }
        BumpTarget::Level(level) => {
            let actual_level = match level {
                BumpLevel::Major => BumpLevel::Major,
                BumpLevel::Minor => BumpLevel::Minor,
                BumpLevel::Patch => BumpLevel::Patch,
                BumpLevel::Auto => {
                    let has_breaking = commits.iter().any(|c| c.is_breaking);
                    let has_feat = commits.iter().any(|c| c.commit_type.as_deref() == Some("feat"));

                    if has_breaking {
                        BumpLevel::Major
                    } else if has_feat {
                        BumpLevel::Minor
                    } else {
                        BumpLevel::Patch
                    }
                }
            };

            let mut next = current.clone();
            match actual_level {
                BumpLevel::Major => {
                    next.major += 1;
                    next.minor = 0;
                    next.patch = 0;
                }
                BumpLevel::Minor => {
                    next.minor += 1;
                    next.patch = 0;
                }
                BumpLevel::Patch => {
                    next.patch += 1;
                }
                BumpLevel::Auto => unreachable!(),
            }
            Ok(next)
        }
    }
}

fn generate_release_notes(version_tag: &str, commits: &[CommitInfo]) -> String {
    let today = Local::now().format("%Y-%m-%d").to_string();
    let mut notes = String::new();

    notes.push_str(&format!("## [{version_tag}] - {today}\n\n"));

    let mut breaking = Vec::new();
    let mut features = Vec::new();
    let mut fixes = Vec::new();
    let mut performance = Vec::new();
    let mut docs = Vec::new();
    let mut others = Vec::new();

    for c in commits {
        let short_hash = if c.hash.len() >= 7 { &c.hash[..7] } else { &c.hash };
        let entry = match &c.scope {
            Some(scope) => format!("- **{scope}**: {} ({short_hash})\n", c.summary),
            None => format!("- {} ({short_hash})\n", c.summary),
        };

        if c.is_breaking {
            breaking.push(entry.clone());
        }

        match c.commit_type.as_deref() {
            Some("feat") => features.push(entry),
            Some("fix") => fixes.push(entry),
            Some("perf") => performance.push(entry),
            Some("docs") => docs.push(entry),
            _ => others.push(entry),
        }
    }

    if !breaking.is_empty() {
        notes.push_str("### ⚠ BREAKING CHANGES\n");
        for item in breaking {
            notes.push_str(&item);
        }
        notes.push('\n');
    }

    let mut sections: BTreeMap<&str, Vec<String>> = BTreeMap::new();
    if !features.is_empty() {
        sections.insert("### Features", features);
    }
    if !fixes.is_empty() {
        sections.insert("### Bug Fixes", fixes);
    }
    if !performance.is_empty() {
        sections.insert("### Performance Improvements", performance);
    }
    if !docs.is_empty() {
        sections.insert("### Documentation", docs);
    }
    if !others.is_empty() {
        sections.insert("### Other Changes", others);
    }

    if sections.is_empty() {
        notes.push_str("- Aucune modification significative listée.\n\n");
    } else {
        for (title, items) in sections {
            notes.push_str(title);
            notes.push('\n');
            for item in items {
                notes.push_str(&item);
            }
            notes.push('\n');
        }
    }

    notes
}

fn update_changelog(changelog_path: &Path, new_content: &str) -> Result<()> {
    let header = "# Changelog\n\nTous les changements notables de ce projet seront documentés dans ce fichier.\n\n";

    let existing = if changelog_path.exists() {
        fs::read_to_string(changelog_path)
            .with_context(|| format!("Impossible de lire {:?}", changelog_path))?
    } else {
        String::new()
    };

    let final_content = if existing.is_empty() {
        format!("{header}{new_content}")
    } else if let Some(stripped) = existing.strip_prefix(header) {
        format!("{header}{new_content}{stripped}")
    } else {
        format!("{new_content}\n{existing}")
    };

    fs::write(changelog_path, final_content)
        .with_context(|| format!("Impossible d'écrire dans {:?}", changelog_path))?;

    Ok(())
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    println!("🔍 Initialisation de l'automatisation de release...");

    if !cli.allow_dirty && !cli.dry_run {
        GitRunner::ensure_clean_worktree()?;
    }

    let (doc, current_version) = read_cargo_version(&cli.manifest_path)?;
    println!("📦 Version actuelle dans Cargo.toml : {current_version}");

    let latest_tag = GitRunner::get_latest_tag()?;
    match &latest_tag {
        Some(tag) => println!("🏷️  Dernier tag Git détecté : {tag}"),
        None => println!("ℹ️  Aucun tag Git existant, prise en compte de tout l'historique"),
    }

    let commits = GitRunner::get_commits_since(latest_tag.as_deref())?;
    println!("📝 Commits trouvés depuis le dernier tag : {}", commits.len());

    let next_version = determine_next_version(&current_version, &cli.target, &commits)?;
    let tag_name = format!("{}{next_version}", cli.tag_prefix);
    println!("🚀 Version cible : {next_version} (Tag: {tag_name})");

    let release_notes = generate_release_notes(&tag_name, &commits);

    if cli.dry_run {
        println!("\n--- [MODE DRY-RUN ACTIVÉ : AUCUNE MODIFICATION NE SERA APPLIQUÉE] ---");
        println!("\n[1/3] Mise à jour de {}", cli.manifest_path.display());
        println!("      package.version: {} -> {}", current_version, next_version);

        if !cli.no_changelog {
            println!("\n[2/3] Insertion dans {} :", cli.changelog_path.display());
            println!("{release_notes}");
        }

        if !cli.no_commit {
            println!("\n[3/3] Git commit et tag :");
            println!("      Commit message: chore(release): {tag_name}");
            if !cli.no_tag {
                println!("      Tag: {tag_name} (signé: {})", cli.sign);
            }
        }
        println!("----------------------------------------------------------------------\n");
        println!("✨ Simulation terminée avec succès.");
        return Ok(());
    }

    // 1. Incrémentation dans Cargo.toml
    println!("✍️  Mise à jour de {}...", cli.manifest_path.display());
    write_cargo_version(&cli.manifest_path, doc, &next_version)?;
    GitRunner::stage_file(&cli.manifest_path)?;

    // Vérifier si Cargo.lock existe et le mettre à jour si nécessaire
    let lock_path = cli.manifest_path.with_file_name("Cargo.lock");
    if lock_path.exists() {
        let _ = Command::new("cargo")
            .arg("check")
            .arg("--manifest-path")
            .arg(&cli.manifest_path)
            .output();
        let _ = GitRunner::stage_file(&lock_path);
    }

    // 2. Génération / mise à jour du Changelog
    if !cli.no_changelog {
        println!("📰 Mise à jour de {}...", cli.changelog_path.display());
        update_changelog(&cli.changelog_path, &release_notes)?;
        GitRunner::stage_file(&cli.changelog_path)?;
    }

    // 3. Commit Git
    let commit_message = format!("chore(release): {tag_name}");
    if !cli.no_commit {
        println!("💾 Création du commit de release : '{commit_message}'...");
        GitRunner::commit(&commit_message)?;
    }

    // 4. Tag Git
    if !cli.no_tag {
        println!("🏷️  Création du tag Git '{tag_name}'...");
        let tag_annotation = format!("Release {tag_name}");
        GitRunner::create_tag(&tag_name, &tag_annotation, cli.sign)?;
    }

    println!("🎉 Release {tag_name} effectuée avec succès !");
    Ok(())
}

