        assert_eq!(extract_h1(md), Some("Mon Super Titre".to_string()));

        let md_without_h1 = "## Sous-titre\nTexte seulement.";
        assert_eq!(extract_h1(md_without_h1), None);
    }

    #[test]
    fn test_markdown_to_html() {
        let md = "# Titre\n\n- [x] Tâche terminée\n- [ ] Tâche à faire";
        let html = markdown_to_html(md);
        assert!(html.contains("<h1>Titre</h1>"));
        assert!(html.contains("type=\"checkbox\""));
    }

    #[test]
    fn test_build_standalone_html() {
        let title = "Test & Co <3>";
        let css = "body { margin: 0; }";
        let body = "<p>Contenu</p>";
        let result = build_standalone_html(title, css, body);

        assert!(result.contains("<title>Test &amp; Co &lt;3&gt;</title>"));
        assert!(result.contains("<style>\nbody { margin: 0; }\n    </style>"));
        assert!(result.contains("<body>\n<p>Contenu</p>\n</body>"));
    }

    #[test]
    fn test_determine_output_path() {
        let input = Path::new("docs/readme.md");
        let auto_output = determine_output_path(input, None);
        assert_eq!(auto_output, PathBuf::from("docs/readme.html"));

        let custom_output = determine_output_path(input, Some(PathBuf::from("dist/index.html")));
        assert_eq!(custom_output, PathBuf::from("dist/index.html"));
    }
}

