fn markdown_to_html(markdown_input: &str) -> String {
    let mut options = Options::empty();
    options.insert(Options::ENABLE_TABLES);
    options.insert(Options::ENABLE_FOOTNOTES);
    options.insert(Options::ENABLE_STRIKETHROUGH);
    options.insert(Options::ENABLE_TASKLISTS);
    options.insert(Options::ENABLE_HEADING_ATTRIBUTES);

    let parser = MarkdownParser::new_ext(markdown_input, options);
    let mut html_output = String::new();
    html::push_html(&mut html_output, parser);
    html_output
}

/// Assemble le document HTML autonome avec les styles CSS injectés.
fn build_standalone_html(title: &str, css_content: &str, body_content: &str) -> String {
    format!(
        r#"<!DOCTYPE html>
<html lang="fr">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>{}</title>
    <style>
{}
    </style>
</head>
<body>
{}
</body>
</html>
"#,
        escape_html_title(title),
        css_content.trim(),
        body_content.trim()
    )
}

/// Détermine le chemin de sortie par défaut si non fourni.
fn determine_output_path(input_path: &Path, output_arg: Option<PathBuf>) -> PathBuf {
    match output_arg {
        Some(path) => path,
        None => {
            let mut path = input_path.to_path_buf();
            path.set_extension("html");
            path
        }
    }
}

fn run() -> Result<()> {
    let args = Args::parse();

    let input_path = &args.input;
    let markdown_content = fs::read_to_string(input_path)
        .with_context(|| format!("Impossible de lire le fichier source Markdown : {:?}", input_path))?;

    // Résolution du CSS
    let css_content = match &args.css {
        Some(css_path) => fs::read_to_string(css_path)
            .with_context(|| format!("Impossible de lire le fichier CSS fourni : {:?}", css_path))?,
        None => DEFAULT_CSS.to_string(),
    };

    // Résolution du titre du document
    let title = match args.title {
        Some(t) => t,
        None => extract_h1(&markdown_content).unwrap_or_else(|| {
            input_path
                .file_stem()
                .and_then(|s| s.to_str())
                .unwrap_or("Documentation")
                .to_string()
        }),
    };

    // Conversion et assemblage
    let body_html = markdown_to_html(&markdown_content);
    let complete_html = build_standalone_html(&title, &css_content, &body_html);

    // Détermination et écriture dans le fichier de sortie
    let output_path = determine_output_path(input_path, args.output);
    if let Some(parent) = output_path.parent() {
        if !parent.as_os_str().is_empty() {
            fs::create_dir_all(parent).with_context(|| {
                format!(
                    "Impossible de créer le répertoire de destination : {:?}",
                    parent
                )
            })?;
        }
    }

    fs::write(&output_path, complete_html)
        .with_context(|| format!("Impossible d'écrire le fichier HTML généré : {:?}", output_path))?;

    println!("Document autonome généré avec succès : {}", output_path.display());

    Ok(())
}

fn main() {
    if let Err(err) = run() {
        eprintln!("Erreur : {:#}", err);
        std::process::exit(1);
    }
}

#[cfg(test)]
mod tests {
