    #[test]
    fn test_extract_h1() {
        let md = "Intro\n\n# Mon Super Titre\n\nDu texte.";
        assert_eq!(extract_h1(md), Some("Mon Super Titre".to_string()));

        let md_without_h1 = "## Sous-titre\nTexte seulement.";
        assert_eq!(extract_h1(md_without_h1), None);
