// src/main.rs
use std::{
    net::{IpAddr, ToSocketAddrs},
    time::Duration,
};

use chrono::{DateTime, Utc};
use clap::Parser;
use serde::Serialize;
use surge_ping::{Client, Config, PingIdentifier, PingSequence};
use thiserror::Error;
use tracing::{error, info, warn};
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt, EnvFilter};

#[derive(Error, Debug)]
pub enum MonitorError {
    #[error("Échec de résolution DNS pour l'hôte: {0}")]
    DnsResolution(String),

    #[error("Erreur de requête HTTP vers le webhook: {0}")]
    WebhookRequest(#[from] reqwest::Error),

    #[error("Erreur d'initialisation du client ICMP ping: {0}")]
    PingClientInit(#[from] surge_ping::SurgeError),

    #[error("Erreur E/S ou signal: {0}")]
    Io(#[from] std::io::Error),
}

#[derive(Parser, Debug, Clone)]
#[command(
    name = "net-pulse-monitor",
    author = "Damien",
    version = "0.1.0",
    about = "Surveille la disponibilité réseau périodiquement via ICMP et déclenche des alertes webhook."
)]
pub struct CliArgs {
    /// Cible réseau à surveiller (adresse IP ou nom d'hôte).
    #[arg(short, long, default_value = "1.1.1.1")]
    pub target: String,

    /// Intervalle entre deux requêtes ping consécutives en secondes.
    #[arg(short, long, default_value_t = 3)]
    pub interval_secs: u64,

    /// Délai d'attente maximum d'un ping en secondes.
    #[arg(long, default_value_t = 2)]
    pub timeout_secs: u64,

    /// Nombre d'échecs consécutifs nécessaires pour déclarer une panne.
    #[arg(long, default_value_t = 3)]
    pub failure_threshold: u32,

    /// Nombre de succès consécutifs nécessaires pour déclarer le rétablissement.
    #[arg(long, default_value_t = 2)]
    pub recovery_threshold: u32,

    /// URL du webhook HTTP(S) vers lequel envoyer les alertes JSON.
    #[arg(long)]
    pub webhook_url: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub enum HealthStatus {
    Up,
    Down,
}

#[derive(Debug, Serialize)]
pub struct WebhookPayload {
    pub event_type: HealthStatus,
    pub target: String,
    pub timestamp: DateTime<Utc>,
    pub consecutive_failures: u32,
    pub latency_ms: Option<f64>,
    pub message: String,
    /// Champ texte pratique pour compatibilité immédiate avec Slack / Discord
    pub text: String,
}

pub struct WebhookNotifier {
    client: reqwest::Client,
    url: Option<String>,
}

impl WebhookNotifier {
    pub fn new(url: Option<String>) -> Self {
        let client = reqwest::Client::builder()
            .timeout(Duration::from_secs(5))
            .build()
            .unwrap_or_else(|err| {
                warn!("Impossible de configurer le client HTTP personnalisé ({err}), fallback standard.");
                reqwest::Client::new()
            });

        Self { client, url }
    }

    pub async fn send_alert(&self, payload: &WebhookPayload) {
        let url = match &self.url {
            Some(u) => u,
            None => {
                info!(
                    target = %payload.target,
                    status = ?payload.event_type,
                    "Notification ignorée car aucune URL de webhook n'est configurée."
                );
                return;
            }
        };

        info!(
            webhook_url = %url,
            event = ?payload.event_type,
            "Expédition de la notification webhook en cours..."
        );

        match self.client.post(url).json(payload).send().await {
            Ok(resp) => {
                if resp.status().is_success() {
                    info!("Notification webhook délivrée avec succès (Status: {}).", resp.status());
                } else {
                    warn!(
                        "Échec de livraison du webhook: le serveur a renvoyé le statut HTTP {}.",
                        resp.status()
                    );
                }
            }
            Err(err) => {
                error!("Erreur réseau lors de l'envoi du webhook: {err}");
            }
        }
    }
}

pub struct Monitor {
    target_host: String,
    target_ip: IpAddr,
    interval: Duration,
    timeout: Duration,
    failure_threshold: u32,
    recovery_threshold: u32,
    status: HealthStatus,
    consecutive_failures: u32,
    consecutive_successes: u32,
    notifier: WebhookNotifier,
    ping_client: Client,
}

impl Monitor {
    pub async fn initialize(args: CliArgs) -> Result<Self, MonitorError> {
        let target_ip = resolve_target(&args.target)?;
        let ping_client = Client::new(&Config::default())?;
        let notifier = WebhookNotifier::new(args.webhook_url);

        Ok(Self {
            target_host: args.target,
            target_ip,
            interval: Duration::from_secs(args.interval_secs),
            timeout: Duration::from_secs(args.timeout_secs),
            failure_threshold: args.failure_threshold.max(1),
            recovery_threshold: args.recovery_threshold.max(1),
            status: HealthStatus::Up,
            consecutive_failures: 0,
            consecutive_successes: 0,
            notifier,
            ping_client,
        })
    }

    pub async fn run(&mut self) {
        info!(
            target = %self.target_host,
            ip = %self.target_ip,
            interval_secs = ?self.interval.as_secs(),
            "Démarrage du moniteur de disponibilité réseau."
        );

        let mut ticker = tokio::time::interval(self.interval);
        ticker.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);

        let mut sequence: u16 = 0;

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    sequence = sequence.wrapping_add(1);
                    self.execute_probe(sequence).await;
                }
                _ = tokio::signal::ctrl_c() => {
                    info!("Signal d'interruption (Ctrl+C) reçu. Arrêt propre du moniteur.");
                    break;
                }
            }
        }
    }

    async fn execute_probe(&mut self, seq: u16) {
        let ident = PingIdentifier(0x1234);
        let mut pinger = self.ping_client.pinger(self.target_ip, ident).await;

        let payload = [0u8; 24];
        let ping_future = pinger.ping(PingSequence(seq), &payload);

        let probe_result = match tokio::time::timeout(self.timeout, ping_future).await {
            Ok(Ok((_, dur))) => Ok(dur),
            Ok(Err(err)) => Err(format!("Échec ICMP: {err}")),
            Err(_) => Err(format!("Dépassement de délai (timeout > {}s)", self.timeout.as_secs())),
        };

        match probe_result {
            Ok(duration) => {
                let ms = duration.as_secs_f64() * 1000.0;
                info!(target = %self.target_host, seq = %seq, latency = format!("{:.2}ms", ms), "Ping réussi.");
                self.handle_success(ms).await;
            }
            Err(reason) => {
                warn!(target = %self.target_host, seq = %seq, reason = %reason, "Ping échoué.");
                self.handle_failure().await;
            }
        }
    }

    async fn handle_success(&mut self, latency_ms: f64) {
        self.consecutive_failures = 0;
        self.consecutive_successes += 1;

        if self.status == HealthStatus::Down && self.consecutive_successes >= self.recovery_threshold {
            self.status = HealthStatus::Up;
            let msg = format!(
                "Rétablissement: La cible {} est redevenue accessible (latence: {:.2}ms).",
                self.target_host, latency_ms
            );
            error!(target = %self.target_host, "{}", msg);

            let payload = WebhookPayload {
                event_type: HealthStatus::Up,
                target: self.target_host.clone(),
                timestamp: Utc::now(),
                consecutive_failures: 0,
                latency_ms: Some(latency_ms),
                message: msg.clone(),
                text: format!("🟢 [RECOVERED] {}", msg),
            };
            self.notifier.send_alert(&payload).await;
        }
    }

    async fn handle_failure(&mut self) {
        self.consecutive_successes = 0;
        self.consecutive_failures += 1;

        if self.status == HealthStatus::Up && self.consecutive_failures >= self.failure_threshold {
            self.status = HealthStatus::Down;
            let msg = format!(
                "Alerte Panne: La cible {} ne répond plus après {} tentatives infructueuses consécutives.",
                self.target_host, self.consecutive_failures
            );
            error!(target = %self.target_host, "{}", msg);

            let payload = WebhookPayload {
                event_type: HealthStatus::Down,
                target: self.target_host.clone(),
                timestamp: Utc::now(),
                consecutive_failures: self.consecutive_failures,
                latency_ms: None,
                message: msg.clone(),
                text: format!("🔴 [ALERT DOWN] {}", msg),
            };
            self.notifier.send_alert(&payload).await;
        }
    }
}

fn resolve_target(target: &str) -> Result<IpAddr, MonitorError> {
    if let Ok(ip) = target.parse::<IpAddr>() {
        return Ok(ip);
    }

    let socket_query = format!("{}:0", target);
    let resolved = socket_query
        .to_socket_addrs()
        .map_err(|_| MonitorError::DnsResolution(target.to_string()))?
        .next()
        .map(|socket_addr| socket_addr.ip())
        .ok_or_else(|| MonitorError::DnsResolution(target.to_string()))?;

    Ok(resolved)
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    tracing_subscriber::registry()
        .with(EnvFilter::try_from_default_env().unwrap_or_else(|_| "info".into()))
        .with(tracing_subscriber::fmt::layer())
        .init();

    let args = CliArgs::parse();

    let mut monitor = match Monitor::initialize(args).await {
        Ok(m) => m,
        Err(err) => {
            error!("Erreur fatale à l'initialisation du moniteur: {err}");
            std::process::exit(1);
        }
    };

    monitor.run().await;

    Ok(())
}

