// src/main.rs
use anyhow::{bail, Context, Result};
use clap::{Parser, ValueEnum};
use regex::Regex;
use std::collections::{BTreeMap, BTreeSet};
use std::fs::File;
use std::io::{self, BufRead, BufReader, BufWriter, Write};
use std::path::PathBuf;
use std::sync::OnceLock;
use std::time::Instant;

/// CLI de parsing et d'extraction de logs système semi-structurés vers CSV.
#[derive(Parser, Debug)]
#[command(
    name = "log-extractor",
    author = "Damien",
    version = "0.1.0",
    about = "Parse et extrait des données semi-structurées de logs système vers un fichier CSV"
)]
struct Cli {
    /// Fichier de log d'entrée (utilise l'entrée standard stdin par défaut)
    #[arg(short, long, value_name = "FILE")]
    input: Option<PathBuf>,

    /// Fichier CSV de sortie (utilise la sortie standard stdout par défaut)
    #[arg(short, long, value_name = "FILE")]
    output: Option<PathBuf>,

    /// Format de log attendu
    #[arg(short, long, value_enum, default_value_t = LogFormat::Auto)]
    format: LogFormat,

    /// Expression régulière personnalisée avec groupes nommés (ex: '(?P<timestamp>\\S+) (?P<level>\\w+) (?P<message>.*)')
    #[arg(long, value_name = "REGEX")]
    regex_pattern: Option<String>,

    /// Extraire automatiquement les paires clé=valeur (ex: 'user=admin status=200') présentes dans le message
    #[arg(long, default_value_t = true, action = clap::ArgAction::Set)]
    extract_kv: bool,

    /// Liste ordonnée des colonnes à exporter (séparées par des virgules).
    /// Par défaut, génère les colonnes standard et les attributs clé-valeur détectés.
    #[arg(short, long, value_delimiter = ',')]
    columns: Option<Vec<String>>,

    /// Caractère délimiteur pour le fichier CSV
    #[arg(short, long, default_value_t = ',')]
    delimiter: char,

    /// Mode strict : interrompt l'exécution en cas de ligne malformée au lieu de l'ignorer
    #[arg(long, default_value_t = false)]
    strict: bool,

    /// Afficher les statistiques de parsing sur stderr à la fin du traitement
    #[arg(long, default_value_t = false)]
    stats: bool,
}

#[derive(ValueEnum, Clone, Copy, Debug, PartialEq, Eq)]
enum LogFormat {
    /// Détection automatique (RFC 5424, BSD RFC 3164, ou clé-valeur)
    Auto,
    /// Format BSD Syslog standard (RFC 3164)
    SyslogBsd,
    /// Format moderne Syslog IETF (RFC 5424)
    SyslogRfc5424,
    /// Lignes composées de paires clé=valeur
    KeyValue,
    /// Expression régulière personnalisée avec groupes nommés
    Regex,
}

/// Enregistrement extrait contenant les champs normalisés et les paires clé-valeur additionnelles.
#[derive(Debug, Clone, Default)]
struct LogRecord {
    fields: BTreeMap<String, String>,
}

impl LogRecord {
    fn new() -> Self {
        Self {
            fields: BTreeMap::new(),
        }
    }

    fn insert(&mut self, key: impl Into<String>, val: impl Into<String>) {
        let val = val.into().trim().to_string();
        if !val.is_empty() {
            self.fields.insert(key.into(), val);
        }
    }

    fn get(&self, key: &str) -> &str {
        self.fields.get(key).map(|s| s.as_str()).unwrap_or("")
    }
}

// Regex partagées compilées une seule fois
static KV_REGEX: OnceLock<Regex> = OnceLock::new();
static RFC3164_REGEX: OnceLock<Regex> = OnceLock::new();
static RFC5424_REGEX: OnceLock<Regex> = OnceLock::new();

fn get_kv_regex() -> &'static Regex {
    KV_REGEX.get_or_init(|| {
        Regex::new(r#"(?P<key>[a-zA-Z0-9_\-\.]+)=(?:"(?P<qval>[^"\\]*(?:\\.[^"\\]*)*)"|(?P<val>[^\s,;]+))"#)
            .expect("Regex KV valide")
    })
}

fn get_rfc3164_regex() -> &'static Regex {
    RFC3164_REGEX.get_or_init(|| {
        // Ex: <34>Oct 11 22:14:15 myhost systemd[123]: Message de log
        // ou: Oct 11 22:14:15 myhost kernel: Message
        Regex::new(r#"^(?:<(?P<pri>\d{1,3})>)?(?P<timestamp>[A-Z][a-z]{2}\s+\d{1,2}\s+\d{2}:\d{2}:\d{2})\s+(?P<hostname>\S+)\s+(?P<tag>[a-zA-Z0-9_\-\.\(\)]+?)(?:\[(?P<pid>\d+)\])?:\s+(?P<message>.*)$"#)
            .expect("Regex RFC3164 valide")
    })
}

fn get_rfc5424_regex() -> &'static Regex {
    RFC5424_REGEX.get_or_init(|| {
        // Ex: <165>1 2003-10-11T22:14:15.003Z mymachine.example.com evntslog 5432 ID47 [exampleSDID@32473 iut="3"] Message
        Regex::new(r#"^<(?P<pri>\d{1,3})>(?P<version>\d+)\s+(?P<timestamp>\S+)\s+(?P<hostname>\S+)\s+(?P<app_name>\S+)\s+(?P<procid>\S+)\s+(?P<msgid>\S+)\s+(?P<structured_data>-(?:\[.*?\])*|\[.*?\])\s*(?P<message>.*)$"#)
            .expect("Regex RFC5424 valide")
    })
}

/// Convertit un code PRI Syslog en (facility, severity).
fn decode_pri(pri_str: &str) -> Option<(String, String)> {
    let pri: u32 = pri_str.parse().ok()?;
    let facility_code = pri >> 3;
    let severity_code = pri & 0x07;

    let facility = match facility_code {
        0 => "kern",
        1 => "user",
        2 => "mail",
        3 => "daemon",
        4 => "auth",
        5 => "syslog",
        6 => "lpr",
        7 => "news",
        8 => "uucp",
        9 => "cron",
        10 => "authpriv",
        11 => "ftp",
        16..=23 => "local",
        _ => "unknown",
    };

    let severity = match severity_code {
        0 => "EMERGENCY",
        1 => "ALERT",
        2 => "CRITICAL",
        3 => "ERROR",
        4 => "WARNING",
        5 => "NOTICE",
        6 => "INFO",
        7 => "DEBUG",
        _ => "UNKNOWN",
    };

    Some((facility.to_string(), severity.to_string()))
}

/// Extrait les paires clé=valeur d'une chaîne de caractères.
fn extract_key_values(text: &str, record: &mut LogRecord) {
    let re = get_kv_regex();
    for cap in re.captures_iter(text) {
        if let Some(key_match) = cap.name("key") {
            let key = key_match.as_str().to_lowercase();
            let value = if let Some(qval) = cap.name("qval") {
                qval.as_str().replace(r#"\""#, "\"")
            } else if let Some(val) = cap.name("val") {
                val.as_str().to_string()
            } else {
                continue;
            };
            record.insert(key, value);
        }
    }
}

/// Tente de parser selon le format RFC 5424.
fn parse_rfc5424(line: &str, extract_kv: bool) -> Option<LogRecord> {
    let re = get_rfc5424_regex();
    let caps = re.captures(line)?;

    let mut record = LogRecord::new();
    if let Some(pri) = caps.name("pri") {
        record.insert("pri", pri.as_str());
        if let Some((fac, sev)) = decode_pri(pri.as_str()) {
            record.insert("facility", fac);
            record.insert("severity", sev);
        }
    }

    if let Some(ts) = caps.name("timestamp") {
        if ts.as_str() != "-" {
            record.insert("timestamp", ts.as_str());
        }
    }
    if let Some(host) = caps.name("hostname") {
        if host.as_str() != "-" {
            record.insert("hostname", host.as_str());
        }
    }
    if let Some(app) = caps.name("app_name") {
        if app.as_str() != "-" {
            record.insert("app_name", app.as_str());
        }
    }
    if let Some(procid) = caps.name("procid") {
        if procid.as_str() != "-" {
            record.insert("pid", procid.as_str());
        }
    }
    if let Some(msgid) = caps.name("msgid") {
        if msgid.as_str() != "-" {
            record.insert("msgid", msgid.as_str());
        }
    }

    if let Some(sd) = caps.name("structured_data") {
        let sd_val = sd.as_str();
        if sd_val != "-" {
            record.insert("structured_data", sd_val);
            if extract_kv {
                extract_key_values(sd_val, &mut record);
            }
        }
    }

    let message = caps.name("message").map(|m| m.as_str()).unwrap_or("");
    record.insert("message", message);

    if extract_kv && !message.is_empty() {
        extract_key_values(message, &mut record);
    }

    Some(record)
}

/// Tente de parser selon le format RFC 3164 (BSD Syslog).
fn parse_rfc3164(line: &str, extract_kv: bool) -> Option<LogRecord> {
    let re = get_rfc3164_regex();
    let caps = re.captures(line)?;

    let mut record = LogRecord::new();
    if let Some(pri) = caps.name("pri") {
        record.insert("pri", pri.as_str());
        if let Some((fac, sev)) = decode_pri(pri.as_str()) {
            record.insert("facility", fac);
            record.insert("severity", sev);
        }
    }

    if let Some(ts) = caps.name("timestamp") {
        record.insert("timestamp", ts.as_str());
    }
    if let Some(host) = caps.name("hostname") {
        record.insert("hostname", host.as_str());
    }
    if let Some(tag) = caps.name("tag") {
        record.insert("app_name", tag.as_str());
    }
    if let Some(pid) = caps.name("pid") {
        record.insert("pid", pid.as_str());
    }

    let message = caps.name("message").map(|m| m.as_str()).unwrap_or("");
    record.insert("message", message);

    if extract_kv && !message.is_empty() {
        extract_key_values(message, &mut record);
    }

    Some(record)
}

/// Parse une ligne entièrement basée sur clé=valeur.
fn parse_key_value(line: &str) -> Option<LogRecord> {
    let mut record = LogRecord::new();
    extract_key_values(line, &mut record);

    if record.fields.is_empty() {
        None
    } else {
        Some(record)
    }
}

/// Parse une ligne via un regex personnalisé fourni par l'utilisateur.
fn parse_custom_regex(line: &str, re: &Regex, extract_kv: bool) -> Option<LogRecord> {
    let caps = re.captures(line)?;
    let mut record = LogRecord::new();

    for name in re.capture_names().flatten() {
        if let Some(m) = caps.name(name) {
            record.insert(name, m.as_str());
        }
    }

    if extract_kv {
        if let Some(msg) = record.fields.get("message") {
            let msg_clone = msg.clone();
            extract_key_values(&msg_clone, &mut record);
        } else {
            extract_key_values(line, &mut record);
        }
    }

    Some(record)
}

/// Parseur automatique multi-formats.
fn parse_auto(line: &str, extract_kv: bool) -> Option<LogRecord> {
    if let Some(rec) = parse_rfc5424(line, extract_kv) {
        return Some(rec);
    }
    if let Some(rec) = parse_rfc3164(line, extract_kv) {
        return Some(rec);
    }
    if let Some(rec) = parse_key_value(line) {
        return Some(rec);
    }
    None
}

/// Structure de statistiques d'exécution
#[derive(Default, Debug)]
struct ExecutionStats {
    total_lines: usize,
    parsed_lines: usize,
    failed_lines: usize,
}

fn determine_columns(
    user_columns: Option<&Vec<String>>,
    sample_records: &[LogRecord],
) -> Vec<String> {
    if let Some(cols) = user_columns {
        return cols.clone();
    }

    let default_order = [
        "timestamp",
        "facility",
        "severity",
        "hostname",
        "app_name",
        "pid",
        "msgid",
        "message",
    ];

    let mut present_defaults = Vec::new();
    let mut extra_keys = BTreeSet::new();

    for key in default_order {
        let is_present = sample_records.iter().any(|r| r.fields.contains_key(key));
        if is_present {
            present_defaults.push(key.to_string());
        }
    }

    for r in sample_records {
        for k in r.fields.keys() {
            if !default_order.contains(&k.as_str()) && k != "pri" && k != "structured_data" {
                extra_keys.insert(k.clone());
            }
        }
    }

    let mut final_cols = present_defaults;
    final_cols.extend(extra_keys);

    if final_cols.is_empty() {
        vec!["message".to_string()]
    } else {
        final_cols
    }
}

fn run_pipeline(cli: &Cli) -> Result<ExecutionStats> {
    let custom_regex = if let Some(pattern) = &cli.regex_pattern {
        Some(
            Regex::new(pattern)
                .with_context(|| format!("Regex personnalisé invalide: '{pattern}'"))?,
        )
    } else if cli.format == LogFormat::Regex {
        bail!("L'option --regex-pattern est requise lorsque le format est 'regex'");
    } else {
        None
    };

    // Configuration de la source de lecture
    let reader: Box<dyn BufRead> = match &cli.input {
        Some(path) => {
            let file = File::open(path)
                .with_context(|| format!("Impossible d'ouvrir le fichier de log: {:?}", path))?;
            Box::new(BufReader::new(file))
        }
        None => Box::new(BufReader::new(io::stdin())),
    };

    // Configuration de la destination d'écriture
    let writer: Box<dyn Write> = match &cli.output {
        Some(path) => {
            let file = File::create(path)
                .with_context(|| format!("Impossible de créer le fichier de sortie: {:?}", path))?;
            Box::new(BufWriter::new(file))
        }
        None => Box::new(BufWriter::new(io::stdout())),
    };

    let delimiter_byte = u8::try_from(cli.delimiter)
        .with_context(|| format!("Délimiteur non ASCII invalide: '{}'", cli.delimiter))?;

    let mut csv_writer = csv::WriterBuilder::new()
        .delimiter(delimiter_byte)
        .has_headers(true)
        .from_writer(writer);

    let mut stats = ExecutionStats::default();

    let parse_line = |line: &str| -> Option<LogRecord> {
        match cli.format {
            LogFormat::Auto => parse_auto(line, cli.extract_kv),
            LogFormat::SyslogBsd => parse_rfc3164(line, cli.extract_kv),
            LogFormat::SyslogRfc5424 => parse_rfc5424(line, cli.extract_kv),
            LogFormat::KeyValue => parse_key_value(line),
            LogFormat::Regex => {
                let re = custom_regex.as_ref()?;
                parse_custom_regex(line, re, cli.extract_kv)
            }
        }
    };

    // Si les colonnes ne sont pas explicitées, on accumule les premières lignes (ou toutes) pour dériver les colonnes
    if let Some(specified_columns) = &cli.columns {
        csv_writer
            .write_record(specified_columns)
            .context("Échec d'écriture des en-têtes CSV")?;

        for (idx, line_res) in reader.lines().enumerate() {
            let line = line_res.with_context(|| format!("Erreur de lecture à la ligne {}", idx + 1))?;
            let trimmed = line.trim();
            if trimmed.is_empty() {
                continue;
            }

            stats.total_lines += 1;
            if let Some(record) = parse_line(trimmed) {
                stats.parsed_lines += 1;
                let row: Vec<&str> = specified_columns.iter().map(|col| record.get(col)).collect();
                csv_writer
                    .write_record(&row)
                    .with_context(|| format!("Échec d'écriture de la ligne CSV {}", idx + 1))?;
            } else {
                stats.failed_lines += 1;
                if cli.strict {
                    bail!(
                        "Erreur de parsing en mode strict à la ligne {} : '{}'",
                        idx + 1,
                        trimmed
                    );
                } else {
                    eprintln!("Avertissement: ligne {} non reconnue ignorée.", idx + 1);
                }
            }
        }
    } else {
        // Collecte dynamique des enregistrements pour déduire les en-têtes CSV
        let mut records = Vec::new();
        for (idx, line_res) in reader.lines().enumerate() {
            let line = line_res.with_context(|| format!("Erreur de lecture à la ligne {}", idx + 1))?;
            let trimmed = line.trim();
            if trimmed.is_empty() {
                continue;
            }

            stats.total_lines += 1;
            if let Some(record) = parse_line(trimmed) {
                stats.parsed_lines += 1;
                records.push(record);
            } else {
                stats.failed_lines += 1;
                if cli.strict {
                    bail!(
                        "Erreur de parsing en mode strict à la ligne {} : '{}'",
                        idx + 1,
                        trimmed
                    );
                } else {
                    eprintln!("Avertissement: ligne {} non reconnue ignorée.", idx + 1);
                }
            }
        }

        let headers = determine_columns(None, &records);
        csv_writer
            .write_record(&headers)
            .context("Échec d'écriture des en-têtes CSV")?;

        for record in records {
            let row: Vec<&str> = headers.iter().map(|col| record.get(col)).collect();
            csv_writer
                .write_record(&row)
                .context("Échec d'écriture d'un enregistrement CSV")?;
        }
    }

    csv_writer.flush().context("Échec lors du vidage du tampon CSV")?;
    Ok(stats)
}

fn main() -> Result<()> {
    let start_time = Instant::now();
    let cli = Cli::parse();

    let is_stats_requested = cli.stats;
    let stats = run_pipeline(&cli)?;

    if is_stats_requested {
        let elapsed = start_time.elapsed();
        eprintln!("--- Statistiques d'extraction ---");
        eprintln!("Lignes lues         : {}", stats.total_lines);
        eprintln!("Lignes converties   : {}", stats.parsed_lines);
        eprintln!("Lignes ignorées     : {}", stats.failed_lines);
        eprintln!("Temps d'exécution   : {:.2?}", elapsed);
        if stats.total_lines > 0 {
            let rate = (stats.parsed_lines as f64 / stats.total_lines as f64) * 100.0;
            eprintln!("Taux de succès      : {:.1}%", rate);
        }
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_rfc3164() {
        let line = "Oct 11 22:14:15 srv-app-01 nginx[2341]: GET /index.html 200 user=john ip=192.168.1.50";
        let rec = parse_rfc3164(line, true).expect("Doit parser RFC3164");
        assert_eq!(rec.get("timestamp"), "Oct 11 22:14:15");
        assert_eq!(rec.get("hostname"), "srv-app-01");
        assert_eq!(rec.get("app_name"), "nginx");
        assert_eq!(rec.get("pid"), "2341");
        assert_eq!(rec.get("user"), "john");
        assert_eq!(rec.get("ip"), "192.168.1.50");
    }

    #[test]
    fn test_parse_rfc5424() {
        let line = r#"<165>1 2026-09-28T07:15:00Z webhost auth-service 4096 ID101 [meta client="curl"] User authenticated user_id=123 status=success"#;
        let rec = parse_rfc5424(line, true).expect("Doit parser RFC5424");
        assert_eq!(rec.get("severity"), "NOTICE");
        assert_eq!(rec.get("facility"), "local");
        assert_eq!(rec.get("timestamp"), "2026-09-28T07:15:00Z");
        assert_eq!(rec.get("hostname"), "webhost");
        assert_eq!(rec.get("app_name"), "auth-service");
        assert_eq!(rec.get("pid"), "4096");
        assert_eq!(rec.get("client"), "curl");
        assert_eq!(rec.get("user_id"), "123");
        assert_eq!(rec.get("status"), "success");
    }

    #[test]
    fn test_parse_key_value() {
        let line = r#"time="2026-09-28T07:20:00Z" level=error msg="Database timeout" db="postgres_primary" duration=500ms"#;
        let rec = parse_key_value(line).expect("Doit parser KeyValue");
        assert_eq!(rec.get("time"), "2026-09-28T07:20:00Z");
        assert_eq!(rec.get("level"), "error");
        assert_eq!(rec.get("msg"), "Database timeout");
        assert_eq!(rec.get("db"), "postgres_primary");
        assert_eq!(rec.get("duration"), "500ms");
    }

    #[test]
    fn test_custom_regex() {
        let pattern = r#"^(?P<time>\S+) \[(?P<level>[A-Z]+)\] (?P<service>\S+): (?P<message>.*)$"#;
        let re = Regex::new(pattern).unwrap();
        let line = "2026-09-28 [WARN] worker: Job failed retries=3 reason=\"network error\"";
        let rec = parse_custom_regex(line, &re, true).expect("Doit parser Regex personnalisé");
        assert_eq!(rec.get("time"), "2026-09-28");
        assert_eq!(rec.get("level"), "WARN");
        assert_eq!(rec.get("service"), "worker");
        assert_eq!(rec.get("retries"), "3");
        assert_eq!(rec.get("reason"), "network error");
    }
}

