// src/main.rs
use std::path::{Path, PathBuf};
use std::process::ExitCode;
use std::thread;
use std::time::Duration;

use chrono::Local;
use clap::Parser;
use colored::*;
use sysinfo::Disks;

/// Niveaux de sévérité d'alerte pour l'espace disque.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum AlertLevel {
    Normal,
    Warning,
    Critical,
}

/// Structure d'analyse d'un système de fichiers / point de montage.
#[derive(Debug, Clone)]
pub struct DiskUsageReport {
    pub name: String,
    pub mount_point: PathBuf,
    pub file_system: String,
    pub total_bytes: u64,
    pub available_bytes: u64,
    pub used_bytes: u64,
    pub usage_percentage: f64,
    pub alert_level: AlertLevel,
}

impl DiskUsageReport {
    /// Évalue l'état d'un disque en fonction des seuils configurés.
    pub fn new(
        name: &str,
        mount_point: &Path,
        file_system: &str,
        total_bytes: u64,
        available_bytes: u64,
        warning_threshold: f64,
        critical_threshold: f64,
    ) -> Self {
        let used_bytes = total_bytes.saturating_sub(available_bytes);
        let usage_percentage = if total_bytes > 0 {
            (used_bytes as f64 / total_bytes as f64) * 100.0
        } else {
            0.0
        };

        let alert_level = if usage_percentage >= critical_threshold {
            AlertLevel::Critical
        } else if usage_percentage >= warning_threshold {
            AlertLevel::Warning
        } else {
            AlertLevel::Normal
        };

        Self {
            name: name.to_string(),
            mount_point: mount_point.to_path_buf(),
            file_system: file_system.to_string(),
            total_bytes,
            available_bytes,
            used_bytes,
            usage_percentage,
            alert_level,
        }
    }
}

/// Formate un volume d'octets en chaîne lisible (B, KiB, MiB, GiB, TiB).
pub fn format_bytes(bytes: u64) -> String {
    const KIB: f64 = 1024.0;
    const MIB: f64 = 1024.0 * KIB;
    const GIB: f64 = 1024.0 * MIB;
    const TIB: f64 = 1024.0 * GIB;

    let b = bytes as f64;
    if b >= TIB {
        format!("{:.2} TiB", b / TIB)
    } else if b >= GIB {
        format!("{:.2} GiB", b / GIB)
    } else if b >= MIB {
        format!("{:.2} MiB", b / MIB)
    } else if b >= KIB {
        format!("{:.2} KiB", b / KIB)
    } else {
        format!("{} B", bytes)
    }
}

/// Génère une barre visuelle ASCII colorée pour représenter le taux d'occupation.
pub fn generate_progress_bar(percentage: f64, width: usize) -> String {
    let clamped = percentage.clamp(0.0, 100.0);
    let filled_slots = ((clamped / 100.0) * width as f64).round() as usize;
    let empty_slots = width.saturating_sub(filled_slots);

    let bar = format!(
        "[{}{}]",
        "█".repeat(filled_slots),
        "░".repeat(empty_slots)
    );

    if clamped >= 90.0 {
        bar.red().bold().to_string()
    } else if clamped >= 80.0 {
        bar.yellow().bold().to_string()
    } else {
        bar.green().to_string()
    }
}

