#[derive(Parser, Debug)]
#[command(
    name = "disk-quota-monitor",
    version,
    about = "Surveillance de l'espace et des quotas disques avec alertes console en temps réel.",
    author
)]
pub struct CliArgs {
    /// Seuil critique en pourcentage déclenchant une alerte majeure (défaut: 90.0%).
    #[arg(short = 'c', long = "critical", default_value_t = 90.0)]
    pub critical_threshold: f64,

    /// Seuil d'avertissement en pourcentage déclenchant un avertissement (défaut: 80.0%).
    #[arg(short = 'w', long = "warning", default_value_t = 80.0)]
    pub warning_threshold: f64,

    /// Filtre sur un point de montage spécifique (ex: / ou /home).
    #[arg(short = 'm', long = "mount")]
    pub target_mount: Option<PathBuf>,

