    #[arg(short = 'i', long = "interval", visible_alias = "watch")]
    pub watch_interval: Option<u64>,

    /// Quota personnalisé spécifique à surveiller pour le point de montage cible (ex: 50GiB).
    /// Si spécifié, le calcul d'alerte s'effectuera sur ce quota maximum alloué au lieu de la taille totale du disque.
    #[arg(short = 'q', long = "quota-gib")]
    pub quota_gib: Option<f64>,
}

/// Analyse et collecte les rapports sur tous les disques ou sur la cible filtrée.
pub fn collect_reports(args: &CliArgs) -> Vec<DiskUsageReport> {
    let disks = Disks::new_with_refreshed_list();
    let mut reports = Vec::new();

    for disk in disks.list() {
        let mount_point = disk.mount_point();

        if let Some(ref target) = args.target_mount {
            if mount_point != target.as_path() {
                continue;
            }
        }

        let name = disk.name().to_string_lossy().to_string();
        let fs = disk.file_system().to_string_lossy().to_string();

        let (total_bytes, available_bytes) = if let Some(quota_gib) = args.quota_gib {
            let quota_bytes = (quota_gib * 1024.0 * 1024.0 * 1024.0) as u64;
            let current_used = disk.total_space().saturating_sub(disk.available_space());
            let quota_available = quota_bytes.saturating_sub(current_used);
            (quota_bytes, quota_available)
        } else {
            (disk.total_space(), disk.available_space())
        };

        let report = DiskUsageReport::new(
            &name,
            mount_point,
            &fs,
            total_bytes,
            available_bytes,
            args.warning_threshold,
            args.critical_threshold,
        );

        reports.push(report);
    }

    reports
}

/// Affiche un cycle de rapport complet avec notifications d'alerte console.
pub fn render_report(reports: &[DiskUsageReport], args: &CliArgs) -> bool {
    let timestamp = Local::now().format("%Y-%m-%d %H:%M:%S").to_string();
    println!(
        "\n{} {}",
        "=== RAPPORT D'ÉTAT DES DISQUES ===".blue().bold(),
        format!("[{}]", timestamp).dimmed()
    );
    println!(
        "Seuils configurés : {} (≥ {:.1}%) | {} (≥ {:.1}%)\n",
        "ATTENTION".yellow().bold(),
        args.warning_threshold,
        "CRITIQUE".red().bold(),
        args.critical_threshold
    );

    let mut has_critical = false;
    let mut alert_notifications: Vec<String> = Vec::new();

    for report in reports {
        let bar = generate_progress_bar(report.usage_percentage, 20);
        let status_badge = match report.alert_level {
            AlertLevel::Normal => " OK ".on_green().bold().white(),
            AlertLevel::Warning => " WARN ".on_yellow().bold().black(),
            AlertLevel::Critical => {
                has_critical = true;
                " CRIT ".on_red().bold().white()
            }
        };

        println!(
            "{:<6} {:<24} {:<10} {:>10} / {:<10} ({:>5.1}%) {}",
            status_badge,
            report.mount_point.display().to_string().cyan(),
            report.file_system.dimmed(),
            format_bytes(report.used_bytes),
            format_bytes(report.total_bytes),
            report.usage_percentage,
            bar
        );

        match report.alert_level {
            AlertLevel::Critical => {
                let msg = format!(
                    "🚨 [ALERTE CRITIQUE] Point de montage '{}' : espace utilisé à {:.2}% (Libre: {} sur {})",
                    report.mount_point.display(),
                    report.usage_percentage,
                    format_bytes(report.available_bytes),
                    format_bytes(report.total_bytes)
                );
                alert_notifications.push(msg.red().bold().to_string());
            }
            AlertLevel::Warning => {
                let msg = format!(
                    "⚠️  [AVERTISSEMENT] Point de montage '{}' : espace utilisé à {:.2}% (Libre: {} sur {})",
                    report.mount_point.display(),
                    report.usage_percentage,
                    format_bytes(report.available_bytes),
                    format_bytes(report.total_bytes)
                );
                alert_notifications.push(msg.yellow().bold().to_string());
            }
            AlertLevel::Normal => {}
        }
    }

    if !alert_notifications.is_empty() {
        println!("\n{}", "─".repeat(70).dimmed());
        println!("{}", "NOTIFICATIONS D'ALERTES :".bold().underline());
        for notif in alert_notifications {
            eprintln!("{}", notif);
        }
        println!("{}", "─".repeat(70).dimmed());
    } else {
        println!("\n{}", "✓ Tous les volumes respectent les quotas alloués.".green());
    }

    has_critical
}

fn main() -> ExitCode {
    let args = CliArgs::parse();

    if args.warning_threshold >= args.critical_threshold {
        eprintln!(
            "{}",
            "Erreur de configuration : le seuil d'avertissement (-w) doit être inférieur au seuil critique (-c)."
                .red()
                .bold()
        );
        return ExitCode::from(2);
    }

    if let Some(interval) = args.watch_interval {
        println!(
            "Démarrage de la surveillance active (intervalle: {}s)... Appuyez sur Ctrl+C pour quitter.",
            interval
        );
        loop {
            let reports = collect_reports(&args);
            if reports.is_empty() {
                eprintln!("{}", "Aucun point de montage trouvé correspondant aux critères.".yellow());
            } else {
                render_report(&reports, &args);
            }
            thread::sleep(Duration::from_secs(interval));
        }
    } else {
        let reports = collect_reports(&args);
        if reports.is_empty() {
            eprintln!("{}", "Aucun point de montage trouvé correspondant aux critères.".yellow());
            return ExitCode::from(1);
        }

        let has_critical = render_report(&reports, &args);
        if has_critical {
            ExitCode::from(1)
        } else {
            ExitCode::SUCCESS
        }
    }
}

