// src/main.rs
#![forbid(unsafe_code)]

use clap::{Parser, ValueEnum};
use colored::*;
use comfy_table::presets::UTF8_FULL;
use comfy_table::{Cell, CellAlignment, Color, ContentArrangement, Table};
use indicatif::{ProgressBar, ProgressStyle};
use rand::{Rng, SeedableRng};
use std::fmt;
use std::time::{Duration, Instant};

#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
enum Algorithm {
    QuickSort,
    MergeSort,
    TimSort,
    HeapSort,
    StdUnstable,
}

impl fmt::Display for Algorithm {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Algorithm::QuickSort => write!(f, "QuickSort (Pivot médian)"),
            Algorithm::MergeSort => write!(f, "MergeSort (Diviser-pour-régner)"),
            Algorithm::TimSort => write!(f, "TimSort (std::slice::sort)"),
            Algorithm::HeapSort => write!(f, "HeapSort (Tri par tas)"),
            Algorithm::StdUnstable => write!(f, "pdqsort (std::slice::sort_unstable)"),
        }
    }
}

impl Algorithm {
    fn sort<T: Ord + Clone>(&self, slice: &mut [T]) {
        match self {
            Algorithm::QuickSort => quick_sort(slice),
            Algorithm::MergeSort => merge_sort(slice),
            Algorithm::TimSort => tim_sort(slice),
            Algorithm::HeapSort => heap_sort(slice),
            Algorithm::StdUnstable => slice.sort_unstable(),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
enum Distribution {
    Random,
    Sorted,
    Reversed,
    NearlySorted,
    Duplicates,
}

impl fmt::Display for Distribution {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Distribution::Random => write!(f, "Aléatoire"),
            Distribution::Sorted => write!(f, "Déjà trié"),
            Distribution::Reversed => write!(f, "Inversé"),
            Distribution::NearlySorted => write!(f, "Presque trié (~5% perm.)"),
            Distribution::Duplicates => write!(f, "Forte duplication (1..10)"),
        }
    }
}

