        value_enum,
        default_values_t = vec![
            Algorithm::QuickSort,
            Algorithm::MergeSort,
            Algorithm::TimSort,
            Algorithm::HeapSort
        ]
    )]
    algorithms: Vec<Algorithm>,

    /// Distributions des données à tester
