// ============================================================================
// Implémentations des Algorithmes de Tri
// ============================================================================

/// QuickSort in-place avec pivot médian-de-trois et partitionnement robuste
pub fn quick_sort<T: Ord>(slice: &mut [T]) {
    let len = slice.len();
    if len <= 1 {
        return;
    }

    if len <= 16 {
        insertion_sort(slice);
        return;
    }

    let p_idx = partition(slice);
    let (left, right) = slice.split_at_mut(p_idx);
    quick_sort(left);
    if right.len() > 1 {
        quick_sort(&mut right[1..]);
    }
}

fn partition<T: Ord>(slice: &mut [T]) -> usize {
    let len = slice.len();
    let mid = len / 2;

    // Médian de trois : premier, milieu, dernier
    if slice[0] > slice[mid] {
        slice.swap(0, mid);
    }
    if slice[0] > slice[len - 1] {
        slice.swap(0, len - 1);
    }
    if slice[mid] > slice[len - 1] {
        slice.swap(mid, len - 1);
    }

    // Place le pivot à l'avant-dernière position
    slice.swap(mid, len - 1);

    let mut i = 0;
    for j in 0..len - 1 {
        if slice[j] <= slice[len - 1] {
            slice.swap(i, j);
            i += 1;
        }
    }
    slice.swap(i, len - 1);
    i
}

/// Tri par insertion (efficace pour les petites tranches)
fn insertion_sort<T: Ord>(slice: &mut [T]) {
    for i in 1..slice.len() {
        let mut j = i;
        while j > 0 && slice[j - 1] > slice[j] {
            slice.swap(j - 1, j);
            j -= 1;
        }
    }
}

/// MergeSort out-of-place (allocation de buffer de fusion)
pub fn merge_sort<T: Ord + Clone>(slice: &mut [T]) {
    let len = slice.len();
    if len <= 1 {
        return;
    }
    if len <= 16 {
        insertion_sort(slice);
        return;
    }

    let mid = len / 2;
    merge_sort(&mut slice[..mid]);
    merge_sort(&mut slice[mid..]);

    let mut merged = Vec::with_capacity(len);
    let mut i = 0;
    let mut j = mid;

    while i < mid && j < len {
        if slice[i] <= slice[j] {
            merged.push(slice[i].clone());
            i += 1;
        } else {
            merged.push(slice[j].clone());
            j += 1;
        }
    }

    while i < mid {
        merged.push(slice[i].clone());
        i += 1;
    }
    while j < len {
        merged.push(slice[j].clone());
        j += 1;
    }

    slice.clone_from_slice(&merged);
}

/// TimSort : tri adaptatif par excellence
/// Dans la bibliothèque standard Rust, `slice::sort` est une variante de TimSort
/// combinant MergeSort et insertion sur blocs ordonnés.
pub fn tim_sort<T: Ord>(slice: &mut [T]) {
    slice.sort();
}

/// HeapSort in-place complet (complexité garantie O(n log n))
pub fn heap_sort<T: Ord>(slice: &mut [T]) {
    let len = slice.len();
    if len <= 1 {
        return;
    }

    // Construction du tas max
    for i in (0..len / 2).rev() {
        sift_down(slice, i, len);
    }

    // Extraction des éléments
    for end in (1..len).rev() {
        slice.swap(0, end);
        sift_down(slice, 0, end);
    }
}

fn sift_down<T: Ord>(slice: &mut [T], mut root: usize, end: usize) {
    loop {
        let mut largest = root;
        let left = 2 * root + 1;
        let right = 2 * root + 2;

        if left < end && slice[left] > slice[largest] {
            largest = left;
        }
        if right < end && slice[right] > slice[largest] {
            largest = right;
        }

        if largest != root {
            slice.swap(root, largest);
            root = largest;
        } else {
            break;
        }
    }
}

