// Génération des jeux de données
// ============================================================================

fn generate_data(distribution: Distribution, size: usize, seed: Option<u64>) -> Vec<i64> {
    let mut rng: Box<dyn rand::RngCore> = match seed {
        Some(s) => Box::new(rand::rngs::StdRng::seed_from_u64(s)),
        None => Box::new(rand::rngs::StdRng::from_entropy()),
    };

    match distribution {
        Distribution::Random => (0..size).map(|_| rng.gen_range(-1_000_000..=1_000_000)).collect(),
        Distribution::Sorted => (0..size).map(|i| i as i64).collect(),
        Distribution::Reversed => (0..size).rev().map(|i| i as i64).collect(),
        Distribution::NearlySorted => {
            let mut vec: Vec<i64> = (0..size).map(|i| i as i64).collect();
            let swaps = (size / 20).max(1);
            for _ in 0..swaps {
                let idx1 = rng.gen_range(0..size);
                let idx2 = rng.gen_range(0..size);
                vec.swap(idx1, idx2);
            }
            vec
        }
        Distribution::Duplicates => (0..size).map(|_| rng.gen_range(1..=10)).collect(),
    }
}

