#[derive(Debug, Clone)]
struct BenchmarkResult {
    algorithm: Algorithm,
    distribution: Distribution,
    size: usize,
    mean_duration: Duration,
    std_dev_duration: Duration,
    ops_per_second: f64,
    verified: bool,
}

fn run_benchmark(
    cli: &Cli,
    alg: Algorithm,
    dist: Distribution,
    size: usize,
) -> Result<BenchmarkResult, String> {
    let mut durations = Vec::with_capacity(cli.runs);
    let mut is_sorted_ok = true;

    for run_idx in 0..cli.runs {
        // Variation déterministe de la graine par run si fournie
        let run_seed = cli.seed.map(|s| s.wrapping_add(run_idx as u64));
        let mut sample = generate_data(dist, size, run_seed);

        let start = Instant::now();
        alg.sort(&mut sample);
        let elapsed = start.elapsed();
        durations.push(elapsed);

        if cli.verify && !sample.windows(2).all(|w| w[0] <= w[1]) {
            is_sorted_ok = false;
        }
    }

    let runs_count = durations.len().max(1);
    let total_nanos: u128 = durations.iter().map(|d| d.as_nanos()).sum();
    let mean_nanos = (total_nanos as f64) / (runs_count as f64);

    let variance_nanos = durations
        .iter()
        .map(|d| {
            let diff = d.as_nanos() as f64 - mean_nanos;
            diff * diff
        })
        .sum::<f64>()
        / (runs_count as f64);

    let std_dev_nanos = variance_nanos.sqrt();
    let mean_duration = Duration::from_nanos(mean_nanos as u64);
    let std_dev_duration = Duration::from_nanos(std_dev_nanos as u64);

    let mean_secs = mean_duration.as_secs_f64();
    let ops_per_second = if mean_secs > 0.0 {
        (size as f64) / mean_secs
    } else {
        0.0
    };

    Ok(BenchmarkResult {
        algorithm: alg,
        distribution: dist,
        size,
        mean_duration,
        std_dev_duration,
        ops_per_second,
        verified: is_sorted_ok,
    })
}

fn format_duration(duration: &Duration) -> String {
    let micros = duration.as_micros();
    if micros < 1_000 {
        format!("{} µs", micros)
    } else if micros < 1_000_000 {
        format!("{:.2} ms", (micros as f64) / 1_000.0)
    } else {
        format!("{:.3} s", duration.as_secs_f64())
    }
}

fn format_throughput(ops_per_sec: f64) -> String {
    if ops_per_sec >= 1_000_000.0 {
        format!("{:.2} M élém/s", ops_per_sec / 1_000_000.0)
    } else if ops_per_sec >= 1_000.0 {
        format!("{:.1} k élém/s", ops_per_sec / 1_000.0)
    } else {
        format!("{:.0} élém/s", ops_per_sec)
    }
}

// ============================================================================
// Affichage des Résultats
// ============================================================================

fn display_results(results: &[BenchmarkResult]) {
    println!("\n{}", "=== RÉSULTATS DU BENCHMARK COMPARATIF ===".bold().cyan());

    let mut table = Table::new();
    table
        .load_preset(UTF8_FULL)
        .set_content_arrangement(ContentArrangement::Dynamic)
        .set_header(vec![
            Cell::new("Distribution").set_alignment(CellAlignment::Center),
            Cell::new("Taille").set_alignment(CellAlignment::Right),
            Cell::new("Algorithme").set_alignment(CellAlignment::Left),
            Cell::new("Temps Moyen").set_alignment(CellAlignment::Right),
            Cell::new("Écart-type").set_alignment(CellAlignment::Right),
            Cell::new("Débit").set_alignment(CellAlignment::Right),
            Cell::new("Statut").set_alignment(CellAlignment::Center),
        ]);

    // Regrouper par (Distribution, Taille) pour identifier le gagnant
    let mut dist_size_groups: std::collections::BTreeMap<(String, usize), Vec<&BenchmarkResult>> =
        std::collections::BTreeMap::new();

    for r in results {
        let key = (r.distribution.to_string(), r.size);
        dist_size_groups.entry(key).or_default().push(r);
    }

    for ((dist_name, _size), group) in dist_size_groups {
        let min_duration = group.iter().map(|r| r.mean_duration).min();

        for (idx, res) in group.iter().enumerate() {
            let is_best = Some(res.mean_duration) == min_duration && group.len() > 1;

            let time_str = format_duration(&res.mean_duration);
            let time_cell = if is_best {
                Cell::new(format!("★ {}", time_str))
                    .fg(Color::Green)
                    .set_alignment(CellAlignment::Right)
            } else {
                Cell::new(time_str).set_alignment(CellAlignment::Right)
            };

            let status_cell = if res.verified {
                Cell::new("OK").fg(Color::Green).set_alignment(CellAlignment::Center)
            } else {
                Cell::new("ÉCHEC").fg(Color::Red).set_alignment(CellAlignment::Center)
            };

            let dist_cell = if idx == 0 {
                Cell::new(&dist_name)
            } else {
                Cell::new("")
            };

            let size_cell = if idx == 0 {
                Cell::new(res.size.to_string()).set_alignment(CellAlignment::Right)
            } else {
                Cell::new("")
            };

            table.add_row(vec![
                dist_cell,
                size_cell,
                Cell::new(res.algorithm.to_string()),
                time_cell,
                Cell::new(format_duration(&res.std_dev_duration)).set_alignment(CellAlignment::Right),
                Cell::new(format_throughput(res.ops_per_second)).set_alignment(CellAlignment::Right),
                status_cell,
            ]);
        }
    }

    println!("{table}");
    println!("{}", "★ = Meilleur temps d'exécution pour le groupe taille / distribution.".dimmed());
}

fn main() {
    let cli = Cli::parse();

    println!("{}", "=========================================================".bold().blue());
    println!("{}", "    CLI de Comparaison de Performances de Tris (Rust)     ".bold().white());
    println!("{}", "=========================================================".bold().blue());
    println!("Algorithmes : {:?}", cli.algorithms);
    println!("Distributions: {:?}", cli.distributions);
    println!("Tailles      : {:?}", cli.sizes);
    println!("Répétitions  : {} par mesure", cli.runs);
    println!("Vérification : {}", if cli.verify { "Activée" } else { "Désactivée" });
    println!();

    let total_benchmarks = cli.distributions.len() * cli.sizes.len() * cli.algorithms.len();
    let pb = ProgressBar::new(total_benchmarks as u64);
    pb.set_style(
        ProgressStyle::default_bar()
            .template("{spinner:.green} [{elapsed_precise}] [{bar:40.cyan/blue}] {pos}/{len} ({eta}) {msg}")
            .unwrap_or_else(|_| ProgressStyle::default_bar())
            .progress_chars("#>-"),
    );

    let mut all_results = Vec::with_capacity(total_benchmarks);

    for dist in &cli.distributions {
        for size in &cli.sizes {
            for alg in &cli.algorithms {
                pb.set_message(format!("{alg} sur {dist} ({size} éléments)"));
                match run_benchmark(&cli, *alg, *dist, *size) {
                    Ok(result) => {
                        all_results.push(result);
                    }
                    Err(e) => {
                        eprintln!("\n{} {e}", "Erreur:".red().bold());
                    }
                }
                pb.inc(1);
            }
        }
    }

    pb.finish_with_message("Benchmark terminé avec succès !");

    display_results(&all_results);
}

