// src/main.rs
use std::collections::HashSet;
use std::fmt;
use std::fs;
use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime};

use anyhow::{Context, Result};
use clap::{Parser, ValueEnum};
use dialoguer::Confirm;
use tracing::{error, info, warn};
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt, EnvFilter};
use walkdir::WalkDir;

/// Cible de nettoyage disponible
#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
pub enum TargetCategory {
    /// Répertoires et fichiers temporaires système/utilisateur
    Temp,
    /// Caches et artefacts de compilation (Rust target, Node node_modules, Python __pycache__, etc.)
    Build,
    /// Fichiers orphelins (liens symboliques cassés, résidus temporaires)
    Orphans,
    /// Toutes les catégories réunies
    All,
}

/// Type de nœud système détecté pour la purge
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ItemKind {
    File,
    Directory,
    BrokenSymlink,
}

impl fmt::Display for ItemKind {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::File => write!(f, "Fichier"),
            Self::Directory => write!(f, "Dossier"),
            Self::BrokenSymlink => write!(f, "Lien cassé"),
        }
    }
}

/// Entité candidate à la purge
#[derive(Debug, Clone)]
pub struct PurgeItem {
    pub path: PathBuf,
    pub kind: ItemKind,
    pub category: TargetCategory,
    pub size_bytes: u64,
    pub reason: String,
}

/// Options de configuration issues de la ligne de commande
#[derive(Parser, Debug)]
#[command(
    name = "dystil-clean",
    author = "Damien <damien@example.com>",
    version,
    about = "Outil automatisé et sécurisé de nettoyage des répertoires temporaires, caches de build et fichiers orphelins.",
    long_about = "dystil-clean analyse le système de fichiers pour identifier et supprimer les résidus temporaires, \
les caches de compilation volumineux et les liens symboliques brisés, avec des garde-fous stricts contre les suppressions accidentelles."
)]
pub struct CliArgs {
    /// Catégories de purge à activer
    #[arg(short = 'c', long = "category", value_enum, default_value = "all")]
    pub category: TargetCategory,

    /// Chemins racines personnalisés à analyser (défaut : répertoire courant et caches par défaut)
    #[arg(short = 'p', long = "path")]
    pub paths: Vec<PathBuf>,

    /// Mode simulation : liste les suppressions prévues sans modifier le disque
    #[arg(short = 'n', long = "dry-run")]
    pub dry_run: bool,

    /// Supprime sans demander de confirmation interactive
    #[arg(short = 'y', long = "yes")]
    pub auto_confirm: bool,

    /// Ne purger que les éléments non modifiés depuis cette durée (ex: '7d', '24h', '30m')
    #[arg(long = "older-than", value_parser = humantime::parse_duration)]
    pub older_than: Option<Duration>,

    /// Filtrer les fichiers/dossiers dont la taille minimale dépasse ce seuil en octets
    #[arg(long = "min-size", default_value_t = 0)]
    pub min_size: u64,

    /// Niveau de verbosité détaillé (active les logs DEBUG)
    #[arg(short = 'v', long = "verbose")]
    pub verbose: bool,
}

/// Statistiques de purge agrégées
#[derive(Default, Debug)]
pub struct PurgeStats {
    pub total_scanned: usize,
    pub total_candidates: usize,
    pub items_deleted: usize,
    pub bytes_reclaimed: u64,
    pub errors_count: usize,
}

/// Liste de répertoires critiques protégés contre toute tentative de suppression
const PROTECTED_ROOTS: &[&str] = &[
    "/",
    "/bin",
    "/boot",
    "/dev",
    "/etc",
    "/home",
    "/lib",
    "/lib64",
    "/proc",
    "/root",
    "/sbin",
    "/sys",
    "/usr",
    "/var",
];

/// Valide si un chemin est sûr et ne cible pas un répertoire système protégé
pub fn is_safe_path(path: &Path) -> bool {
    let canonical = match path.canonicalize() {
        Ok(c) => c,
        Err(_) => path.to_path_buf(),
    };

    let path_str = canonical.to_string_lossy();

    for protected in PROTECTED_ROOTS {
        if path_str == *protected {
            return false;
        }
    }

    if let Some(home) = dirs::home_dir() {
        if canonical == home {
            return false;
        }
    }

    true
}

/// Formate un volume d'octets en chaîne lisible (B, KiB, MiB, GiB)
pub fn format_bytes(bytes: u64) -> String {
    const KIB: u64 = 1024;
    const MIB: u64 = KIB * 1024;
    const GIB: u64 = MIB * 1024;

    if bytes >= GIB {
        format!("{:.2} GiB", bytes as f64 / GIB as f64)
    } else if bytes >= MIB {
        format!("{:.2} MiB", bytes as f64 / MIB as f64)
    } else if bytes >= KIB {
        format!("{:.2} KiB", bytes as f64 / KIB as f64)
    } else {
        format!("{} B", bytes)
    }
}

/// Calcule récursivement la taille d'un fichier ou d'un répertoire
pub fn compute_size(path: &Path) -> u64 {
    let Ok(metadata) = fs::symlink_metadata(path) else {
        return 0;
    };

    if metadata.is_symlink() || metadata.is_file() {
        return metadata.len();
    }

    if metadata.is_dir() {
        let mut total = 0;
        for entry in WalkDir::new(path).into_iter().filter_map(|e| e.ok()) {
            if let Ok(entry_meta) = entry.metadata() {
                if entry_meta.is_file() {
                    total += entry_meta.len();
                }
            }
        }
        return total;
    }

    0
}

/// Détermine si un élément répond au critère d'ancienneté
fn matches_age_criterion(path: &Path, older_than: Option<Duration>) -> bool {
    let Some(cutoff) = older_than else {
        return true;
    };

    let Ok(metadata) = fs::symlink_metadata(path) else {
        return false;
    };

    let Ok(modified) = metadata.modified() else {
        return false;
    };

    match SystemTime::now().duration_since(modified) {
        Ok(elapsed) => elapsed >= cutoff,
        Err(_) => false,
    }
}

/// Identifie si un dossier correspond à une signature connue de cache de compilation
fn identify_build_cache(path: &Path) -> Option<(&'static str, TargetCategory)> {
    let file_name = path.file_name()?.to_str()?;

    match file_name {
        "target" => {
            let parent = path.parent()?;
            if parent.join("Cargo.toml").exists() {
                Some(("Cache de compilation Cargo/Rust", TargetCategory::Build))
            } else {
                None
            }
        }
        "node_modules" => {
            let parent = path.parent()?;
            if parent.join("package.json").exists() {
                Some(("Dépendances Node.js", TargetCategory::Build))
            } else {
                None
            }
        }
        "__pycache__" | ".pytest_cache" | ".mypy_cache" | ".ruff_cache" => {
            Some(("Cache Python / Bytecode", TargetCategory::Build))
        }
        ".next" | ".nuxt" | ".turbo" | ".parcel-cache" => {
            Some(("Cache de build Frontend Web", TargetCategory::Build))
        }
        _ => None,
    }
}

/// Analyse et collecte les candidats pour les répertoires temporaires
pub fn scan_temp_dirs(older_than: Option<Duration>, min_size: u64) -> Vec<PurgeItem> {
    let mut candidates = Vec::new();
    let mut search_dirs = Vec::new();

    search_dirs.push(std::env::temp_dir());
    if let Some(cache_dir) = dirs::cache_dir() {
        search_dirs.push(cache_dir);
    }

    let default_temp_threshold = older_than.unwrap_or_else(|| Duration::from_secs(3 * 86400));

    for base in search_dirs {
        if !base.exists() || !base.is_dir() {
            continue;
        }

        let read_dir = match fs::read_dir(&base) {
            Ok(rd) => rd,
            Err(err) => {
                warn!("Impossible de lire le dossier temporaire {:?}: {}", base, err);
                continue;
            }
        };

        for entry in read_dir.flatten() {
            let entry_path = entry.path();
            if !is_safe_path(&entry_path) {
                continue;
            }

            if !matches_age_criterion(&entry_path, Some(default_temp_threshold)) {
                continue;
            }

            let size = compute_size(&entry_path);
            if size < min_size {
                continue;
            }

            let kind = if entry_path.is_dir() {
                ItemKind::Directory
            } else {
                ItemKind::File
            };

            candidates.push(PurgeItem {
                path: entry_path,
                kind,
                category: TargetCategory::Temp,
                size_bytes: size,
                reason: format!("Résidu temporaire (> {:?})", default_temp_threshold),
            });
        }
    }

    candidates
}

/// Analyse récursivement une racine pour détecter les caches de build et liens orphelins
pub fn scan_path(
    root: &Path,
    category: TargetCategory,
    older_than: Option<Duration>,
    min_size: u64,
) -> Vec<PurgeItem> {
    let mut candidates = Vec::new();

    if !root.exists() {
        warn!("Le chemin spécifié n'existe pas : {:?}", root);
        return candidates;
    }

    let check_build = matches!(category, TargetCategory::Build | TargetCategory::All);
    let check_orphans = matches!(category, TargetCategory::Orphans | TargetCategory::All);

    let mut it = WalkDir::new(root).follow_links(false).into_iter();

    while let Some(Ok(entry)) = it.next() {
        let entry_path = entry.path();

        if !is_safe_path(entry_path) {
            continue;
        }

        let symlink_meta = match entry_path.symlink_metadata() {
            Ok(m) => m,
            Err(_) => continue,
        };

        // 1. Détection des liens symboliques cassés (fichiers orphelins)
        if symlink_meta.is_symlink() && check_orphans {
            let is_broken = match fs::read_link(entry_path) {
                Ok(target) => {
                    let resolved = if target.is_relative() {
                        entry_path.parent().map(|p| p.join(&target)).unwrap_or(target)
                    } else {
                        target
                    };
                    !resolved.exists()
                }
                Err(_) => true,
            };

            if is_broken {
                candidates.push(PurgeItem {
                    path: entry_path.to_path_buf(),
                    kind: ItemKind::BrokenSymlink,
                    category: TargetCategory::Orphans,
                    size_bytes: 0,
                    reason: "Lien symbolique orphelin (cible introuvable)".to_string(),
                });
                continue;
            }
        }

        // 2. Détection des dossiers de caches de build
        if entry_path.is_dir() && check_build {
            if let Some((desc, cat)) = identify_build_cache(entry_path) {
                if matches_age_criterion(entry_path, older_than) {
                    let size = compute_size(entry_path);
                    if size >= min_size {
                        candidates.push(PurgeItem {
                            path: entry_path.to_path_buf(),
                            kind: ItemKind::Directory,
                            category: cat,
                            size_bytes: size,
                            reason: desc.to_string(),
                        });
                    }
                }
                it.skip_current_dir();
                continue;
            }
        }

        // 3. Détection des fichiers temporaires ou orphelins résiduels
        if entry_path.is_file() && check_orphans {
            if let Some(file_name) = entry_path.file_name().and_then(|f| f.to_str()) {
                let is_orphan_file = file_name.ends_with(".tmp")
                    || file_name.ends_with(".part")
                    || file_name.ends_with('~')
                    || file_name == ".DS_Store";

                if is_orphan_file && matches_age_criterion(entry_path, older_than) {
                    let size = compute_size(entry_path);
                    if size >= min_size {
                        candidates.push(PurgeItem {
                            path: entry_path.to_path_buf(),
                            kind: ItemKind::File,
                            category: TargetCategory::Orphans,
                            size_bytes: size,
                            reason: format!("Fichier temporaire orphelin ({})", file_name),
                        });
                    }
                }
            }
        }
    }

    candidates
}

/// Effectue la collecte complète de tous les éléments à purger selon la configuration
pub fn collect_candidates(args: &CliArgs) -> Vec<PurgeItem> {
    let mut items = Vec::new();
    let mut seen_paths = HashSet::new();

    // 1. Scan des répertoires temporaires système
    if matches!(args.category, TargetCategory::Temp | TargetCategory::All) {
        info!("Analyse des dossiers temporaires et caches utilisateur...");
        for item in scan_temp_dirs(args.older_than, args.min_size) {
            if seen_paths.insert(item.path.clone()) {
                items.push(item);
            }
        }
    }

    // 2. Scan des chemins cibles demandés ou du répertoire courant
    let scan_roots = if args.paths.is_empty() {
        vec![std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."))]
    } else {
        args.paths.clone()
    };

    for root in &scan_roots {
        info!("Analyse du chemin : {:?}", root);
        for item in scan_path(root, args.category, args.older_than, args.min_size) {
            if seen_paths.insert(item.path.clone()) {
                items.push(item);
            }
        }
    }

    items
}

/// Exécute la suppression effective ou simulée des éléments
pub fn execute_purge(candidates: &[PurgeItem], dry_run: bool) -> PurgeStats {
    let mut stats = PurgeStats {
        total_scanned: candidates.len(),
        total_candidates: candidates.len(),
        ..Default::default()
    };

    for item in candidates {
        if !is_safe_path(&item.path) {
            warn!("Protection déclenchée : chemin protégé ignoré : {:?}", item.path);
            continue;
        }

        if dry_run {
            info!(
                "[DRY-RUN] À supprimer : [{}] {:?} ({}) - Raison : {}",
                item.kind,
                item.path,
                format_bytes(item.size_bytes),
                item.reason
            );
            stats.items_deleted += 1;
            stats.bytes_reclaimed += item.size_bytes;
            continue;
        }

        let deletion_result = match item.kind {
            ItemKind::Directory => {
                info!("Suppression récursive du dossier : {:?}", item.path);
                fs::remove_dir_all(&item.path)
            }
            ItemKind::File | ItemKind::BrokenSymlink => {
                info!("Suppression du fichier / lien : {:?}", item.path);
                fs::remove_file(&item.path)
            }
        };

        match deletion_result {
            Ok(_) => {
                stats.items_deleted += 1;
                stats.bytes_reclaimed += item.size_bytes;
            }
            Err(err) => {
                error!("Erreur lors de la suppression de {:?}: {}", item.path, err);
                stats.errors_count += 1;
            }
        }
    }

    stats
}

fn init_tracing(verbose: bool) {
    let default_level = if verbose { "debug" } else { "info" };
    let env_filter =
        EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new(default_level));

    tracing_subscriber::registry()
        .with(env_filter)
        .with(tracing_subscriber::fmt::layer().with_target(false))
        .init();
}

fn main() -> Result<()> {
    let args = CliArgs::parse();
    init_tracing(args.verbose);

    println!("============================================================");
    println!("       dystil-clean - Nettoyeur Automatisé de Fichiers      ");
    println!("============================================================");

    if args.dry_run {
        println!("* Mode SIMULATION actif (--dry-run). Aucune modification.");
    }
    if let Some(dur) = args.older_than {
        println!("* Filtre d'inactivité : éléments antérieurs à {:?}", dur);
    }
    if args.min_size > 0 {
        println!("* Seuil de taille minimale : {}", format_bytes(args.min_size));
    }
    println!();

    let candidates = collect_candidates(&args);

    if candidates.is_empty() {
        println!("Aucun élément orphelin, temporaire ou cache éligible trouvé.");
        return Ok(());
    }

    let total_reclaimable: u64 = candidates.iter().map(|item| item.size_bytes).sum();

    println!("\nÉléments identifiés pour nettoyage :");
    println!("------------------------------------------------------------");
    for (idx, item) in candidates.iter().enumerate() {
        println!(
            "{:>3}. [{:^10}] {:<45} | {:>10} ({})",
            idx + 1,
            item.kind.to_string(),
            item.path.to_string_lossy(),
            format_bytes(item.size_bytes),
            item.reason
        );
    }
    println!("------------------------------------------------------------");
    println!(
        "Total : {} éléments candidats | Espace récupérable estimé : {}\n",
        candidates.len(),
        format_bytes(total_reclaimable)
    );

    if !args.dry_run && !args.auto_confirm {
        let confirmed = Confirm::new()
            .with_prompt("Confirmez-vous la purge définitive de ces éléments ?")
            .default(false)
            .interact()
            .context("Échec lors de l'interaction de confirmation")?;

        if !confirmed {
            println!("Opération annulée par l'utilisateur.");
            return Ok(());
        }
    }

    let start_time = std::time::Instant::now();
    let stats = execute_purge(&candidates, args.dry_run);
    let duration = start_time.elapsed();

    println!("\n=================== RAPPORT D'EXÉCUTION ===================");
    println!("Statut             : {}", if args.dry_run { "SIMULÉ" } else { "PURGÉ" });
    println!("Éléments traités   : {} / {}", stats.items_deleted, stats.total_candidates);
    println!("Espace libéré      : {}", format_bytes(stats.bytes_reclaimed));
    println!("Erreurs relevées   : {}", stats.errors_count);
    println!("Durée d'exécution  : {:.2?}", duration);
    println!("============================================================");

    Ok(())
}

