        {
            let path = entry.path();
            if forced_format.is_some() || Format::from_path(path).is_some() {
                files_to_lint.push(path.to_path_buf());
            }
        }
    } else {
        return Err(ConfigError::Io(
            target.to_path_buf(),
            std::io::Error::new(
                std::io::ErrorKind::NotFound,
                "Chemin cible inexistant ou inaccessible",
            ),
        ));
    }

    if files_to_lint.is_empty() {
        println!("{}", "Aucun fichier de configuration compatible trouvé.".yellow());
        return Ok(false);
    }

    let mut diagnostics = Vec::new();
    let mut parsed_count = 0;

    for file_path in &files_to_lint {
        let fmt = match forced_format.or_else(|| Format::from_path(file_path)) {
            Some(f) => f,
            None => continue,
        };

        // 1. Vérification des permissions Unix de sécurité
        lint_file_permissions(file_path, &mut diagnostics);

        // 2. Lecture et parsing syntaxique
        let content = match fs::read_to_string(file_path) {
            Ok(c) => c,
            Err(e) => {
                diagnostics.push(LintDiagnostic {
                    file: file_path.clone(),
                    path: "<fs>".to_string(),
                    severity: Severity::Error,
                    message: format!("Impossible de lire le fichier: {e}"),
                });
                continue;
            }
        };

        match parse_content(&content, fmt, file_path) {
            Ok(root_val) => {
                parsed_count += 1;
                lint_ast(&root_val, "", file_path, &mut diagnostics);
            }
            Err(e) => {
                diagnostics.push(LintDiagnostic {
                    file: file_path.clone(),
                    path: "<syntax>".to_string(),
                    severity: Severity::Error,
                    message: format!("Erreur de syntaxe: {e}"),
                });
            }
        }
    }

    let has_error = diagnostics.iter().any(|d| d.severity == Severity::Error);
    let has_warning = diagnostics.iter().any(|d| d.severity == Severity::Warning);

    println!(
        "\n{} {} fichier(s) détecté(s), {} parsé(s) avec succès, {} problème(s) relevé(s).\n",
        "=== RAPPORT D'ANALYSE ===".bold().blue(),
        files_to_lint.len(),
        parsed_count,
        diagnostics.len()
    );

    for d in &diagnostics {
        let badge = match d.severity {
            Severity::Info => "[INFO]".cyan().bold(),
            Severity::Warning => "[WARN]".yellow().bold(),
            Severity::Error => "[FAIL]".red().bold(),
        };

        println!(
            "{} {}:{} - {}",
            badge,
            d.file.display().to_string().magenta(),
            d.path.bold(),
            d.message
        );
    }

    if diagnostics.is_empty() {
        println!("{}", "✓ Toutes les vérifications ont réussi sans anomalie.".green().bold());
    }

    let failure = has_error || (strict && has_warning);
    Ok(failure)
}

fn parse_content(content: &str, format: Format, file_path: &Path) -> Result<Value, ConfigError> {
    match format {
        Format::Json => serde_json::from_str(content).map_err(|e| {
            ConfigError::ParseError(file_path.display().to_string(), e.to_string())
        }),
        Format::Toml => {
            let toml_val: toml::Value = toml::from_str(content).map_err(|e| {
                ConfigError::ParseError(file_path.display().to_string(), e.to_string())
            })?;
            serde_json::to_value(toml_val).map_err(|e| {
                ConfigError::ParseError(file_path.display().to_string(), e.to_string())
            })
        }
        Format::Yaml => serde_yaml::from_str(content).map_err(|e| {
            ConfigError::ParseError(file_path.display().to_string(), e.to_string())
        }),
        Format::Ini => {
            let conf = ini::Ini::load_from_str(content).map_err(|e| {
                ConfigError::ParseError(file_path.display().to_string(), e.to_string())
            })?;
            let mut map = BTreeMap::new();
            for (sec, prop) in &conf {
                let mut sec_map = BTreeMap::new();
                for (k, v) in prop.iter() {
                    sec_map.insert(k.to_string(), Value::String(v.to_string()));
                }
                let section_name = sec.map(str::to_string).unwrap_or_else(|| "default".to_string());
                map.insert(section_name, Value::Object(sec_map.into_iter().collect()));
            }
            Ok(Value::Object(map.into_iter().collect()))
        }
    }
}

fn query_value<'a>(value: &'a Value, path: &str) -> Option<&'a Value> {
    if path.is_empty() {
        return Some(value);
    }

    let mut current = value;
    for segment in path.split('.') {
        if segment.is_empty() {
            continue;
        }

        if let Ok(idx) = segment.parse::<usize>() {
            if let Value::Array(arr) = current {
                current = arr.get(idx)?;
                continue;
            }
        }

        match current {
            Value::Object(map) => {
                current = map.get(segment)?;
            }
            _ => return None,
        }
    }
    Some(current)
}

fn lint_file_permissions(path: &Path, diagnostics: &mut Vec<LintDiagnostic>) {
    if let Ok(metadata) = fs::metadata(path) {
        let mode = metadata.permissions().mode();
        let other_write = (mode & 0o002) != 0;
        let other_read = (mode & 0o004) != 0;

        let filename = path
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or_default()
            .to_lowercase();

        if other_write {
            diagnostics.push(LintDiagnostic {
                file: path.to_path_buf(),
                path: "<permissions>".to_string(),
                severity: Severity::Error,
                message: format!(
                    "Permissions dangereuses (mode octal: {:o}): le fichier est modifiable par tous (world-writable).",
                    mode & 0o777
                ),
            });
        }

        let is_sensitive_file = filename.contains("secret")
            || filename.contains("key")
            || filename.contains("cred")
            || filename.contains("token")
            || filename.contains("passwd");

        if is_sensitive_file && other_read {
            diagnostics.push(LintDiagnostic {
                file: path.to_path_buf(),
                path: "<permissions>".to_string(),
                severity: Severity::Warning,
                message: format!(
                    "Fichier sensible lisible par tous (world-readable, mode octal: {:o}). Recommandé: 0600.",
                    mode & 0o777
                ),
            });
        }
    }
}

fn lint_ast(
    value: &Value,
    current_path: &str,
    file_path: &Path,
    diagnostics: &mut Vec<LintDiagnostic>,
) {
    let sensitive_key_regex = Regex::new(r"(?i)(password|secret|api_key|token|private_key)").expect("Regex invalide");
    let ip_listen_all_regex = Regex::new(r"^(0\.0\.0\.0|::|\[::\])$").expect("Regex invalide");

    match value {
        Value::Object(map) => {
            for (key, val) in map {
                let next_path = if current_path.is_empty() {
                    key.clone()
                } else {
                    format!("{current_path}.{key}")
                };

                // Règle 1: Détection de secrets ou mots de passe stockés en clair
                if sensitive_key_regex.is_match(key) {
                    if let Value::String(s) = val {
                        if !s.trim().is_empty() && !s.starts_with("${") && !s.starts_with("env(") {
                            diagnostics.push(LintDiagnostic {
                                file: file_path.to_path_buf(),
                                path: next_path.clone(),
                                severity: Severity::Warning,
                                message: "Valeur sensible (mot de passe/clé) stockée en texte brut. Envisagez l'utilisation de variables d'environnement.".to_string(),
                            });
                        }
                    }
                }

                // Règle 2: Validation des numéros de port réseau
                if key.to_lowercase().contains("port") {
                    if let Some(port_num) = val.as_i64() {
                        if !(1..=65535).contains(&port_num) {
                            diagnostics.push(LintDiagnostic {
                                file: file_path.to_path_buf(),
                                path: next_path.clone(),
                                severity: Severity::Error,
                                message: format!("Port réseau invalide: {port_num}. Un port valide doit être compris entre 1 et 65535."),
                            });
                        } else if port_num < 1024 {
                            diagnostics.push(LintDiagnostic {
                                file: file_path.to_path_buf(),
                                path: next_path.clone(),
                                severity: Severity::Info,
                                message: format!("Le port {port_num} est un port privilégié (< 1024), nécessitant des privilèges root/admin."),
                            });
                        }
                    }
                }

                // Règle 3: Détection d'écoute réseau non restreinte
                if key.to_lowercase().contains("host") || key.to_lowercase().contains("bind") || key.to_lowercase().contains("address") {
                    if let Value::String(addr) = val {
                        if ip_listen_all_regex.is_match(addr.trim()) {
                            diagnostics.push(LintDiagnostic {
                                file: file_path.to_path_buf(),
                                path: next_path.clone(),
                                severity: Severity::Warning,
                                message: format!("Écoute sur toutes les interfaces réseau ('{addr}')."),
                            });
                        }
                    }
                }

                // Règle 4: Détection des valeurs vides
                if let Value::String(s) = val {
                    if s.trim().is_empty() {
                        diagnostics.push(LintDiagnostic {
                            file: file_path.to_path_buf(),
                            path: next_path.clone(),
                            severity: Severity::Info,
                            message: "Valeur de chaîne vide détectée.".to_string(),
                        });
                    }
                }

                lint_ast(val, &next_path, file_path, diagnostics);
            }
        }
        Value::Array(arr) => {
            for (idx, val) in arr.iter().enumerate() {
                let next_path = format!("{current_path}[{idx}]");
                lint_ast(val, &next_path, file_path, diagnostics);
            }
        }
        _ => {}
    }
}

