// src/main.rs
use clap::Parser;
use serde::Deserialize;
use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write as _;
use std::fs;
use std::path::{Path, PathBuf};

/// Types de dépendances supportés dans Cargo.toml
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum DependencyKind {
    Normal,
    Dev,
    Build,
}

impl DependencyKind {
    pub fn label(self) -> &'static str {
        match self {
            Self::Normal => "normal",
            Self::Dev => "dev",
            Self::Build => "build",
        }
    }

    pub fn color(self) -> &'static str {
        match self {
            Self::Normal => "#2563eb", // Bleu
            Self::Dev => "#16a34a",    // Vert
            Self::Build => "#ea580c",  // Orange
        }
    }

    pub fn style(self) -> &'static str {
        match self {
            Self::Normal => "solid",
            Self::Dev => "dashed",
            Self::Build => "dotted",
        }
    }
}

/// Représentation brute d'une entrée de dépendance dans Cargo.toml
#[derive(Debug, Deserialize)]
#[serde(untagged)]
enum RawDepValue {
    Version(String),
    Detailed(RawDetailedDep),
}

#[derive(Debug, Deserialize)]
struct RawDetailedDep {
    version: Option<String>,
    path: Option<String>,
    git: Option<String>,
    optional: Option<bool>,
    features: Option<Vec<String>>,
}

/// Structure minimale pour parser le Cargo.toml
#[derive(Debug, Deserialize)]
struct RawCargoToml {
    package: Option<RawPackage>,
    workspace: Option<RawWorkspace>,
    #[serde(default)]
    dependencies: BTreeMap<String, RawDepValue>,
    #[serde(rename = "dev-dependencies", default)]
    dev_dependencies: BTreeMap<String, RawDepValue>,
    #[serde(rename = "build-dependencies", default)]
    build_dependencies: BTreeMap<String, RawDepValue>,
}

#[derive(Debug, Deserialize)]
struct RawPackage {
    name: String,
    version: Option<String>,
}

#[derive(Debug, Deserialize)]
struct RawWorkspace {
    #[allow(dead_code)]
    members: Option<Vec<String>>,
}

/// Description unifiée d'une dépendance
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DependencyInfo {
    pub name: String,
    pub kind: DependencyKind,
    pub version: Option<String>,
    pub is_path: bool,
    pub is_git: bool,
    pub is_optional: bool,
    pub features: Vec<String>,
}

/// Arbre ou graphe analysé
#[derive(Debug, Default)]
pub struct PackageGraph {
    pub package_name: String,
    pub package_version: Option<String>,
    pub dependencies: Vec<DependencyInfo>,
}

impl PackageGraph {
    /// Analyse un fichier Cargo.toml donné
    pub fn parse_from_file(path: &Path) -> Result<Self, anyhow::Error> {
        let content = fs::read_to_string(path)
            .map_err(|e| anyhow::anyhow!("Impossible de lire le fichier '{}': {}", path.display(), e))?;

        let parsed: RawCargoToml = toml::from_str(&content)
            .map_err(|e| anyhow::anyhow!("Erreur de syntaxe TOML dans '{}': {}", path.display(), e))?;

        let (package_name, package_version) = if let Some(pkg) = parsed.package {
            (pkg.name, pkg.version)
        } else if parsed.workspace.is_some() {
            (
                path.parent()
                    .and_then(|p| p.file_name())
                    .map(|n| n.to_string_lossy().to_string())
                    .unwrap_or_else(|| "workspace".to_string()),
                None,
            )
        } else {
            ("unknown_package".to_string(), None)
        };

        let mut dependencies = Vec::new();

        Self::collect_deps(&parsed.dependencies, DependencyKind::Normal, &mut dependencies);
        Self::collect_deps(&parsed.dev_dependencies, DependencyKind::Dev, &mut dependencies);
        Self::collect_deps(&parsed.build_dependencies, DependencyKind::Build, &mut dependencies);

        Ok(Self {
            package_name,
            package_version,
            dependencies,
        })
    }

    fn collect_deps(
        map: &BTreeMap<String, RawDepValue>,
        kind: DependencyKind,
        target: &mut Vec<DependencyInfo>,
    ) {
        for (name, val) in map {
            let (version, is_path, is_git, is_optional, features) = match val {
                RawDepValue::Version(v) => (Some(v.clone()), false, false, false, Vec::new()),
                RawDepValue::Detailed(d) => (
                    d.version.clone(),
                    d.path.is_some(),
                    d.git.is_some(),
                    d.optional.unwrap_or(false),
                    d.features.clone().unwrap_or_default(),
                ),
            };

            target.push(DependencyInfo {
                name: name.clone(),
                kind,
                version,
                is_path,
                is_git,
                is_optional,
                features,
            });
        }
    }

    /// Exporte le graphe sous la forme d'un script DOT Graphviz
    pub fn to_dot(&self, options: &DotOptions) -> String {
        let mut dot = String::new();
        writeln!(&mut dot, "digraph Dependencies {{").unwrap();
        writeln!(&mut dot, "    graph [rankdir={}, concentrate=true, fontname=\"Helvetica,Arial,sans-serif\"];", options.rankdir).unwrap();
        writeln!(&mut dot, "    node [fontname=\"Helvetica,Arial,sans-serif\", fontsize=10, shape=box, style=\"rounded,filled\", fillcolor=\"#f8fafc\", color=\"#64748b\"];").unwrap();
        writeln!(&mut dot, "    edge [fontname=\"Helvetica,Arial,sans-serif\", fontsize=9];").unwrap();
        writeln!(&mut dot).unwrap();

        // Racine
        let root_id = sanitize_identifier(&self.package_name);
        let root_label = match &self.package_version {
            Some(v) => format!("{}\\n(v{})", self.package_name, v),
            None => self.package_name.clone(),
        };
        writeln!(
            &mut dot,
            "    \"{}\" [label=\"{}\", fillcolor=\"#dbeafe\", color=\"#1d4ed8\", penwidth=2.0];",
            root_id, root_label
        )
        .unwrap();

        let mut declared_nodes = BTreeSet::new();
        declared_nodes.insert(self.package_name.clone());

        for dep in &self.dependencies {
            if !options.include_dev && dep.kind == DependencyKind::Dev {
                continue;
            }
            if !options.include_build && dep.kind == DependencyKind::Build {
                continue;
            }

            let dep_id = sanitize_identifier(&dep.name);

            // Déclaration du nœud s'il n'est pas encore présent
            if declared_nodes.insert(dep.name.clone()) {
                let mut label = dep.name.clone();
                if let Some(v) = &dep.version {
                    let _ = write!(&mut label, "\\nv{}", v);
                }
                if dep.is_path {
                    label.push_str(" [path]");
                }
                if dep.is_git {
                    label.push_str(" [git]");
                }
                if dep.is_optional {
                    label.push_str(" [optional]");
                }
                if options.show_features && !dep.features.is_empty() {
                    let _ = write!(&mut label, "\\n+{}", dep.features.join(", "));
                }

                writeln!(&mut dot, "    \"{}\" [label=\"{}\"];", dep_id, label).unwrap();
            }

            // Arête
            let edge_label = if options.show_kind_labels {
                format!(" [label=\"{}\", color=\"{}\", style=\"{}\"]", dep.kind.label(), dep.kind.color(), dep.kind.style())
            } else {
                format!(" [color=\"{}\", style=\"{}\"]", dep.kind.color(), dep.kind.style())
            };

            writeln!(&mut dot, "    \"{}\" -> \"{}\"{};", root_id, dep_id, edge_label).unwrap();
        }

        writeln!(&mut dot, "}}").unwrap();
        dot
    }
}

/// Options de génération DOT
#[derive(Debug, Clone)]
pub struct DotOptions {
    pub rankdir: String,
    pub include_dev: bool,
    pub include_build: bool,
    pub show_features: bool,
    pub show_kind_labels: bool,
}

fn sanitize_identifier(s: &str) -> String {
    s.replace('-', "_")
}

#[derive(Parser, Debug)]
#[command(
    name = "cargo-dep-graphviz",
    author = "Damien",
    version = "0.1.0",
    about = "Analyse Cargo.toml et génère un diagramme de dépendances au format DOT Graphviz."
)]
struct Cli {
    /// Chemin vers le fichier Cargo.toml (défaut: Cargo.toml dans le répertoire courant)
    #[arg(short, long, default_value = "Cargo.toml")]
    manifest_path: PathBuf,

    /// Chemin du fichier DOT de sortie (affiche sur stdout si non spécifié)
    #[arg(short, long)]
    output: Option<PathBuf>,

    /// Inclure les dépendances de développement (dev-dependencies)
    #[arg(long, default_value_t = true)]
    dev: bool,

    /// Inclure les dépendances de compilation (build-dependencies)
    #[arg(long, default_value_t = true)]
    build: bool,

    /// Direction de disposition du graphe (LR pour gauche-droite, TB pour haut-bas)
    #[arg(long, default_value = "LR")]
    rankdir: String,

    /// Afficher les features activées dans le nœud
    #[arg(long, default_value_t = true)]
    features: bool,

    /// Afficher explicitement l'étiquette de type (normal, dev, build) sur les liens
    #[arg(long, default_value_t = false)]
    edge_labels: bool,
}

fn main() -> Result<(), anyhow::Error> {
    let cli = Cli::parse();

    if !cli.manifest_path.exists() {
        eprintln!(
            "Erreur: Le fichier manifest '{}' n'existe pas.",
            cli.manifest_path.display()
        );
        std::process::exit(1);
    }

    let graph = PackageGraph::parse_from_file(&cli.manifest_path)?;

    let dot_options = DotOptions {
        rankdir: cli.rankdir,
        include_dev: cli.dev,
        include_build: cli.build,
        show_features: cli.features,
        show_kind_labels: cli.edge_labels,
    };

    let dot_output = graph.to_dot(&dot_options);

    if let Some(output_path) = cli.output {
        fs::write(&output_path, dot_output).map_err(|e| {
            anyhow::anyhow!(
                "Impossible d'écrire le résultat dans '{}': {}",
                output_path.display(),
                e
            )
        })?;
        eprintln!("Fichier DOT généré avec succès dans '{}'", output_path.display());
    } else {
        print!("{}", dot_output);
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_dependencies() {
        let sample_toml = r#"
            [package]
            name = "mon-super-projet"
            version = "1.2.3"

            [dependencies]
            serde = "1.0"
            clap = { version = "4.0", features = ["derive"] }
            local_lib = { path = "../local_lib", optional = true }

            [dev-dependencies]
            tempfile = "3.8"

            [build-dependencies]
            cc = "1.0"
        "#;

        let parsed: RawCargoToml = toml::from_str(sample_toml).expect("parsing toml failed");
        assert_eq!(parsed.package.as_ref().unwrap().name, "mon-super-projet");

        let mut deps = Vec::new();
        PackageGraph::collect_deps(&parsed.dependencies, DependencyKind::Normal, &mut deps);
        PackageGraph::collect_deps(&parsed.dev_dependencies, DependencyKind::Dev, &mut deps);
        PackageGraph::collect_deps(&parsed.build_dependencies, DependencyKind::Build, &mut deps);

        assert_eq!(deps.len(), 5);

        let clap_dep = deps.iter().find(|d| d.name == "clap").unwrap();
        assert_eq!(clap_dep.kind, DependencyKind::Normal);
        assert_eq!(clap_dep.version.as_deref(), Some("4.0"));
        assert_eq!(clap_dep.features, vec!["derive"]);

        let local_dep = deps.iter().find(|d| d.name == "local_lib").unwrap();
        assert!(local_dep.is_path);
        assert!(local_dep.is_optional);

        let dev_dep = deps.iter().find(|d| d.name == "tempfile").unwrap();
        assert_eq!(dev_dep.kind, DependencyKind::Dev);

        let build_dep = deps.iter().find(|d| d.name == "cc").unwrap();
        assert_eq!(build_dep.kind, DependencyKind::Build);
    }

    #[test]
    fn test_dot_generation() {
        let graph = PackageGraph {
            package_name: "test-pkg".to_string(),
            package_version: Some("0.1.0".to_string()),
            dependencies: vec![
                DependencyInfo {
                    name: "serde".to_string(),
                    kind: DependencyKind::Normal,
                    version: Some("1.0".to_string()),
                    is_path: false,
                    is_git: false,
                    is_optional: false,
                    features: vec![],
                },
            ],
        };

        let dot = graph.to_dot(&DotOptions {
            rankdir: "LR".to_string(),
            include_dev: true,
            include_build: true,
            show_features: true,
            show_kind_labels: false,
        });

        assert!(dot.contains("digraph Dependencies"));
        assert!(dot.contains("\"test_pkg\" -> \"serde\""));
    }
}

