// src/main.rs
use std::collections::{HashMap, HashSet};
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::Duration;

use anyhow::{Context, Result};
use clap::{Parser, ValueEnum};
use colored::*;
use pulldown_cmark::{Event, Parser as MarkdownParser, Tag};
use reqwest::Client;
use serde::Serialize;
use tokio::sync::{Mutex, Semaphore};
use walkdir::WalkDir;

#[derive(Debug, Clone, Copy, ValueEnum, PartialEq, Eq, Serialize)]
#[serde(rename_all = "lowercase")]
enum OutputFormat {
    Text,
    Json,
}

/// CLI de vérification de liens hypertextes (broken links) dans les fichiers Markdown.
#[derive(Parser, Debug)]
#[command(author, version, about, long_about = None)]
struct Cli {
    /// Chemin vers le fichier ou dossier Markdown à analyser
    #[arg(default_value = ".")]
    path: PathBuf,

    /// Concurrence maximale pour les requêtes HTTP distantes
    #[arg(short = 'c', long, default_value_t = 16)]
    concurrency: usize,

    /// Délai d'attente (timeout) en secondes par requête HTTP
    #[arg(short = 't', long, default_value_t = 10)]
    timeout_secs: u64,

    /// Ignorer la vérification des liens HTTP/HTTPS distants
    #[arg(long)]
    offline: bool,

    /// Format de sortie
    #[arg(short = 'f', long, value_enum, default_value_t = OutputFormat::Text)]
    format: OutputFormat,

    /// Afficher également les liens valides dans le rapport texte
    #[arg(short = 'v', long)]
    verbose: bool,
}

#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize)]
enum LinkTarget {
    Remote(String),
    Local(PathBuf),
    Unsupported(String),
}

#[derive(Debug, Clone, Serialize)]
struct LinkOccurrence {
    source_file: PathBuf,
    target: String,
    parsed_target: LinkTarget,
}

#[derive(Debug, Clone, Serialize)]
struct CheckResult {
    target: String,
    is_valid: bool,
    status_code: Option<u16>,
    error_message: Option<String>,
}

#[derive(Debug, Serialize)]
struct FullReport {
    total_files_scanned: usize,
    total_links_found: usize,
    unique_links_checked: usize,
    broken_links_count: usize,
    broken_occurrences: Vec<BrokenOccurrenceReport>,
}

#[derive(Debug, Serialize)]
struct BrokenOccurrenceReport {
    file: String,
    target: String,
    error: String,
}

/// Identifie et classe la cible d'un lien en local ou distant
fn parse_target(base_dir: &Path, raw_link: &str) -> LinkTarget {
    let clean_link = raw_link.trim();
    if clean_link.is_empty() || clean_link.starts_with('#') {
        return LinkTarget::Unsupported("Ancre locale ou lien vide".to_string());
    }

    if clean_link.starts_with("mailto:") || clean_link.starts_with("javascript:") {
        return LinkTarget::Unsupported("Protocole non géré".to_string());
    }

    if clean_link.starts_with("http://") || clean_link.starts_with("https://") {
        return LinkTarget::Remote(clean_link.to_string());
    }

    // Lien relatif local : retirer l'ancre éventuelle (#...) et les paramètres de requête (?...)
    let path_part = clean_link
        .split('#')
        .next()
        .unwrap_or(clean_link)
        .split('?')
        .next()
        .unwrap_or(clean_link);

    let resolved = if path_part.starts_with('/') {
        PathBuf::from(path_part)
    } else {
        base_dir.join(path_part)
    };

    LinkTarget::Local(resolved)
}

/// Extrait les liens d'un fichier Markdown donné
fn extract_links_from_file(file_path: &Path) -> Result<Vec<LinkOccurrence>> {
    let content = fs::read_to_string(file_path)
        .with_context(|| format!("Impossible de lire le fichier {}", file_path.display()))?;

    let base_dir = file_path.parent().unwrap_or_else(|| Path::new("."));
    let mut links = Vec::new();
    let parser = MarkdownParser::new(&content);

    for event in parser {
        match event {
            Event::Start(Tag::Link { dest_url, .. }) | Event::Start(Tag::Image { dest_url, .. }) => {
                let target = dest_url.to_string();
                let parsed = parse_target(base_dir, &target);
                links.push(LinkOccurrence {
                    source_file: file_path.to_path_buf(),
                    target,
                    parsed_target: parsed,
                });
            }
            _ => {}
        }
    }

    Ok(links)
}

/// Collecte les fichiers markdown ciblés
fn collect_markdown_files(root: &Path) -> Vec<PathBuf> {
    if root.is_file() {
        return vec![root.to_path_buf()];
    }

    let mut files = Vec::new();
    for entry in WalkDir::new(root)
        .into_iter()
        .filter_entry(|e| {
            let name = e.file_name().to_string_lossy();
            !name.starts_with('.') && name != "target" && name != "node_modules"
        })
        .filter_map(|e| e.ok())
    {
        if entry.file_type().is_file() {
            if let Some(ext) = entry.path().extension() {
                if ext == "md" || ext == "markdown" {
                    files.push(entry.path().to_path_buf());
                }
            }
        }
    }
    files
}

/// Vérifie un lien distant avec repli sur GET si HEAD échoue
async fn check_remote_url(client: &Client, url: &str) -> CheckResult {
    // Essai initial avec requête HEAD
    let head_res = client.head(url).send().await;

    match head_res {
        Ok(resp) => {
            let status = resp.status();
            if status.is_success() {
                return CheckResult {
                    target: url.to_string(),
                    is_valid: true,
                    status_code: Some(status.as_u16()),
                    error_message: None,
                };
            }

            // Certains serveurs refusent HEAD (405 Method Not Allowed) ou 403
            if status.as_u16() == 405 || status.as_u16() == 403 {
                let get_res = client.get(url).send().await;
                match get_res {
                    Ok(get_resp) => {
                        let get_status = get_resp.status();
                        let is_valid = get_status.is_success() || get_status.is_redirection();
                        return CheckResult {
                            target: url.to_string(),
                            is_valid,
                            status_code: Some(get_status.as_u16()),
                            error_message: if is_valid {
                                None
                            } else {
                                Some(format!("Statut HTTP non valide: {}", get_status))
                            },
                        };
                    }
                    Err(e) => {
                        return CheckResult {
                            target: url.to_string(),
                            is_valid: false,
                            status_code: None,
                            error_message: Some(e.to_string()),
                        };
                    }
                }
            }

            CheckResult {
                target: url.to_string(),
                is_valid: status.is_redirection(),
                status_code: Some(status.as_u16()),
                error_message: Some(format!("Statut HTTP: {}", status)),
            }
        }
        Err(_) => {
            // Repli sur GET en cas d'erreur de négociation HEAD
            match client.get(url).send().await {
                Ok(resp) => {
                    let status = resp.status();
                    let is_valid = status.is_success() || status.is_redirection();
                    CheckResult {
                        target: url.to_string(),
                        is_valid,
                        status_code: Some(status.as_u16()),
                        error_message: if is_valid {
                            None
                        } else {
                            Some(format!("Statut HTTP: {}", status))
                        },
                    }
                }
                Err(e) => CheckResult {
                    target: url.to_string(),
                    is_valid: false,
                    status_code: None,
                    error_message: Some(e.to_string()),
                },
            }
        }
    }
}

/// Vérifie un lien local sur le système de fichiers
fn check_local_path(path: &Path) -> CheckResult {
    let exists = path.exists();
    CheckResult {
        target: path.display().to_string(),
        is_valid: exists,
        status_code: None,
        error_message: if exists {
            None
        } else {
            Some("Fichier ou dossier introuvable".to_string())
        },
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();

    if !cli.path.exists() {
        eprintln!(
            "{} Le chemin spécifié n'existe pas : {}",
            "Erreur:".red().bold(),
            cli.path.display()
        );
        std::process::exit(2);
    }

    let files = collect_markdown_files(&cli.path);
    if files.is_empty() {
        if cli.format == OutputFormat::Text {
            println!("{}", "Aucun fichier Markdown trouvé.".yellow());
        } else {
            let empty_report = FullReport {
                total_files_scanned: 0,
                total_links_found: 0,
                unique_links_checked: 0,
                broken_links_count: 0,
                broken_occurrences: Vec::new(),
            };
            println!("{}", serde_json::to_string_pretty(&empty_report)?);
        }
        return Ok(());
    }

    // Extraction de l'ensemble des liens
    let mut all_occurrences = Vec::new();
    for file in &files {
        match extract_links_from_file(file) {
            Ok(links) => all_occurrences.extend(links),
            Err(e) => {
                eprintln!(
                    "{} Impossible d'analyser {}: {}",
                    "Attention:".yellow().bold(),
                    file.display(),
                    e
                );
            }
        }
    }

    // Dédoublonnage des cibles uniques à vérifier
    let mut unique_targets = HashSet::new();
    for occ in &all_occurrences {
        unique_targets.insert(occ.parsed_target.clone());
    }

    // Préparation du client HTTP
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(cli.timeout_secs))
        .user_agent("Mozilla/5.0 (compatible; md-link-checker/0.1; +https://github.com/rust-lang)")
        .build()
        .context("Échec de l'initialisation du client HTTP")?;

    let results = Arc::new(Mutex::new(HashMap::<LinkTarget, CheckResult>::new()));
    let semaphore = Arc::new(Semaphore::new(cli.concurrency));

    let mut tasks = Vec::new();

    for target in unique_targets {
        let results_ref = Arc::clone(&results);
        let client_ref = client.clone();
        let sem = Arc::clone(&semaphore);
        let offline = cli.offline;

        tasks.push(tokio::spawn(async move {
            let res = match &target {
                LinkTarget::Unsupported(_) => CheckResult {
                    target: String::new(),
                    is_valid: true,
                    status_code: None,
                    error_message: None,
                },
                LinkTarget::Local(path) => check_local_path(path),
                LinkTarget::Remote(url) => {
                    if offline {
                        CheckResult {
                            target: url.clone(),
                            is_valid: true,
                            status_code: None,
                            error_message: None,
                        }
                    } else {
                        let _permit = sem.acquire().await.ok();
                        check_remote_url(&client_ref, url).await
                    }
                }
            };

            let mut map = results_ref.lock().await;
            map.insert(target, res);
        }));
    }

    for task in tasks {
        let _ = task.await;
    }

    let final_results = results.lock().await;

    // Détection des occurrences brisées
    let mut broken_occurrences = Vec::new();
    for occ in &all_occurrences {
        if let Some(res) = final_results.get(&occ.parsed_target) {
            if !res.is_valid {
                broken_occurrences.push(BrokenOccurrenceReport {
                    file: occ.source_file.display().to_string(),
                    target: occ.target.clone(),
                    error: res
                        .error_message
                        .clone()
                        .unwrap_or_else(|| "Échec de validation inconnu".to_string()),
                });
            }
        }
    }

    // Affichage des résultats
    let total_links = all_occurrences.len();
    let broken_count = broken_occurrences.len();

    match cli.format {
        OutputFormat::Json => {
            let report = FullReport {
                total_files_scanned: files.len(),
                total_links_found: total_links,
                unique_links_checked: final_results.len(),
                broken_links_count: broken_count,
                broken_occurrences,
            };
            println!("{}", serde_json::to_string_pretty(&report)?);
        }
        OutputFormat::Text => {
            println!("{}", "=== Rapport de Vérification Markdown ===".bold());
            println!(
                "Fichiers scannés : {} | Liens trouvés : {}",
                files.len(),
                total_links
            );
            println!();

            if cli.verbose {
                for occ in &all_occurrences {
                    if let Some(res) = final_results.get(&occ.parsed_target) {
                        if res.is_valid {
                            println!(
                                "{} [{}] -> {}",
                                "[OK]".green().bold(),
                                occ.source_file.display(),
                                occ.target
                            );
                        }
                    }
                }
            }

            if broken_count > 0 {
                println!(
                    "{}",
                    format!("{} liens brisés détectés :", broken_count)
                        .red()
                        .bold()
                );
                for broken in &broken_occurrences {
                    println!(
                        "{} [{}] -> {} ({})",
                        "[ERR]".red().bold(),
                        broken.file,
                        broken.target.yellow(),
                        broken.error
                    );
                }
                println!();
                std::process::exit(1);
            } else {
                println!("{}", "Tous les liens vérifiés sont valides !".green().bold());
            }
        }
    }

    Ok(())
}

