```rust
// src/main.rs
use anyhow::{Context, Result};
use clap::Parser;
use notify_debouncer_mini::{new_debouncer, DebounceEventResult};
use std::path::PathBuf;
use std::sync::mpsc;
use std::time::Duration;
use tokio::process::Child;
use tracing::{error, info, warn};
use tracing_subscriber::EnvFilter;

/// Outil CLI de surveillance de fichiers avec déclenchement de commandes.
#[derive(Parser, Debug)]
#[command(name = "watchexec-mini", author, version, about, long_about = None)]
struct Cli {
    /// Chemins des dossiers ou fichiers à surveiller
    #[arg(short = 'p', long = "path", default_value = ".")]
    paths: Vec<PathBuf>,

    /// Délai d'anti-rebond (debouncing) en millisecondes
    #[arg(short = 'd', long = "debounce-ms", default_value_t = 300)]
    debounce_ms: u64,

    /// Extensions de fichiers à surveiller (séparées par une virgule, ex: rs,toml)
    #[arg(short = 'e', long = "extensions", value_delimiter = ',')]
    extensions: Vec<String>,

    /// Exécute la commande immédiatement au démarrage
    #[arg(short = 'i', long = "initial-run")]
    initial_run: bool,

    /// Interrompt le processus en cours d'exécution si un nouveau changement arrive
    #[arg(short = 'r', long = "restart", default_value_t = true)]
    restart: bool,

    /// Commande à exécuter et ses arguments
    #[arg(required = true, last = true)]
    command: Vec<String>,
}

/// Vérifie si l'événement concerne au moins un fichier correspondant aux extensions requises.
fn matches_extensions(paths: &[PathBuf], extensions: &[String]) -> bool {
    if extensions.is_empty() {
        return true;
    }

    paths.iter().any(|p| {
        p.extension()
            .and_then(|ext| ext.to_str())
            .map(|ext| {
                extensions
                    .iter()
                    .any(|target_ext| target_ext.trim_start_matches('.').eq_ignore_ascii_case(ext))
            })
            .unwrap_or(false)
    })
}

/// Démarre l'exécution de la commande utilisateur sous forme de processus asynchrone.
fn spawn_command(command: &[String]) -> Result<Child> {
    if command.is_empty() {
        anyhow::bail!("Aucune commande spécifiée pour l'exécution.");
    }

    let program = &command[0];
    let args = &command[1..];

    #[cfg(target_os = "windows")]
    let mut cmd = {
        let mut c = tokio::process::Command::new("cmd");
        c.arg("/C").arg(command.join(" "));
        c
    };

    #[cfg(not(target_os = "windows"))]
    let mut cmd = {
        if command.len() == 1 {
            let mut c = tokio::process::Command::new("sh");
            c.arg("-c").arg(program);
            c
        } else {
            let mut c = tokio::process::Command::new(program);
            c.args(args);
            c
        }
    };

    let child = cmd
        .spawn()
        .with_context(|| format!("Échec du lancement de la commande: '{}'", command.join(" ")))?;

    Ok(child)
}

/// Termine proprement ou force l'arrêt du processus enfant actif.
async fn terminate_child(mut child: Child) {
    if let Err(e) = child.kill().await {
        warn!("Impossible d'arrêter le processus enfant en cours : {:#}", e);
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")),
        )
        .init();

    let cli = Cli::parse();

    info!(
        "Démarrage du watcher sur {:?} (debounce: {} ms)",
        cli.paths, cli.debounce_ms
    );
    if !cli.extensions.is_empty() {
        info!("Filtrage sur les extensions : {:?}", cli.extensions);
    }
    info!("Commande configurée : {:?}", cli.command.join(" "));

    let (sync_tx, sync_rx) = mpsc::channel();
    let debounce_duration = Duration::from_millis(cli.debounce_ms);

    let mut debouncer = new_debouncer(debounce_duration, move |res: DebounceEventResult| {
        let _ = sync_tx.send(res);
    })
    .context("Impossible d'initialiser le gestionnaire d'événements de fichiers.")?;

    for path in &cli.paths {
        if !path.exists() {
            warn!("Le chemin spécifié n'existe pas : {}", path.display());
        }
        debouncer
            .watcher()
            .watch(path, notify::RecursiveMode::Recursive)
            .with_context(|| format!("Échec de la surveillance du chemin : {}", path.display()))?;
    }

    let (async_tx, mut async_rx) = tokio::sync::mpsc::channel::<Vec<PathBuf>>(100);

    // Tâche dédiée pour transférer les événements depuis le canal sync notify vers Tokio
    std::thread::spawn(move || {
        while let Ok(event_res) = sync_rx.recv() {
            match event_res {
                Ok(events) => {
                    let changed_paths: Vec<PathBuf> = events.into_iter().map(|e| e.path).collect();
                    if async_tx.blocking_send(changed_paths).is_err() {
                        break;
                    }
                }
                Err(err) => {
                    warn!("Erreur lors de la capture d'un événement fichier : {:#}", err);
                }
            }
        }
    });

    let mut active_child: Option<Child> = None;

    if cli.initial_run {
        info!("Exécution initiale de la commande...");
        match spawn_command(&cli.command) {
            Ok(child) => active_child = Some(child),
            Err(e) => error!("Erreur lors du lancement initial : {:#}", e),
        }
    }

    loop {
        tokio::select! {
            // Signal d'arrêt Ctrl+C
            _ = tokio::signal::ctrl_c() => {
                info!("Signal d'interruption (Ctrl+C) reçu. Arrêt du file watcher.");
                if let Some(child) = active_child.take() {
                    terminate_child(child).await;
                }
                break;
            }

            // Surveillance de la terminaison du processus enfant s'il existe
            status = async {
                match active_child.as_mut() {
                    Some(child) => child.wait().await,
                    None => std::future::pending().await,
                }
            } => {
                active_child = None;
                match status {
                    Ok(exit_status) => {
                        if exit_status.success() {
                            info!("Commande terminée avec succès ({exit_status}).");
                        } else {
                            warn!("Commande terminée avec un code d'erreur ({exit_status}).");
                        }
                    }
                    Err(e) => {
                        error!("Erreur lors de l'attente de la fin de la commande : {:#}", e);
                    }
                }
            }

            // Réception d'événements de modifications de fichiers
            Some(paths) = async_rx.recv() => {
                if !matches_extensions(&paths, &cli.extensions) {
                    continue;
                }

                info!("Modification détectée sur {} fichier(s).", paths.len());

                if let Some(child) = active_child.take() {
                    if cli.restart {
                        info!("Interruption du processus actif pour redémarrage...");
