// src/main.rs
use std::collections::HashMap;
use std::path::PathBuf;

use anyhow::{Context, Result};
use chrono::{NaiveDate, TimeZone, Utc};
use clap::{Parser, ValueEnum};
use comfy_table::{presets::UTF8_FULL, Cell, CellAlignment, ContentArrangement, Table};
use git2::{Commit, DiffOptions, Repository, Revwalk};
use serde::Serialize;

#[derive(Parser, Debug)]
#[command(
    name = "git-activity-reporter",
    author,
    version,
    about = "Génère des rapports d'activité Git détaillés par auteur",
    long_about = "Analyse un dépôt Git local pour calculer les statistiques d'activité par contributeur (commits, lignes ajoutées/supprimées)."
)]
struct Cli {
    /// Chemin du dépôt Git à analyser
    #[arg(short, long, default_value = ".")]
    path: PathBuf,

    /// Révision ou nom de branche (ex: HEAD, main, origin/master)
    #[arg(short, long, default_value = "HEAD")]
    branch: String,

    /// Date minimale des commits à inclure (format YYYY-MM-DD)
    #[arg(long)]
    since: Option<NaiveDate>,

    /// Date maximale des commits à inclure (format YYYY-MM-DD)
    #[arg(long)]
    until: Option<NaiveDate>,

    /// Format de restitution du rapport
    #[arg(short, long, value_enum, default_value_t = OutputFormat::Table)]
    format: OutputFormat,

    /// Critère de tri du classement
    #[arg(short, long, value_enum, default_value_t = SortCriteria::Commits)]
    sort: SortCriteria,
}

#[derive(Copy, Clone, Debug, PartialEq, Eq, ValueEnum)]
enum OutputFormat {
    Table,
    Json,
}

#[derive(Copy, Clone, Debug, PartialEq, Eq, ValueEnum)]
enum SortCriteria {
    Commits,
    Added,
    Deleted,
    Net,
}

#[derive(Debug, Clone, Serialize)]
struct AuthorStats {
    name: String,
    email: String,
    commits: usize,
    lines_added: usize,
    lines_deleted: usize,
    net_lines: i64,
}

#[derive(Debug, Serialize)]
struct ReportSummary {
    total_authors: usize,
    total_commits: usize,
    total_lines_added: usize,
    total_lines_deleted: usize,
    total_net_lines: i64,
}

#[derive(Debug, Serialize)]
struct ActivityReport {
    summary: ReportSummary,
    authors: Vec<AuthorStats>,
}

fn collect_commit_stats(repo: &Repository, commit: &Commit) -> Result<(usize, usize)> {
    let mut added = 0;
    let mut deleted = 0;

    let current_tree = commit.tree().context("Impossible de charger l'arborescence du commit")?;
    let parent_count = commit.parent_count();

    let mut diff_opts = DiffOptions::new();

    if parent_count == 0 {
        // Premier commit du dépôt (root commit)
        let diff = repo
            .diff_tree_to_tree(None, Some(&current_tree), Some(&mut diff_opts))
            .context("Erreur lors de la génération du diff pour le commit racine")?;
        let stats = diff.stats().context("Erreur d'extraction des statistiques du diff")?;
        added += stats.insertions();
        deleted += stats.deletions();
    } else {
        // Compare avec le premier parent (approche standard pour les contributions)
        let parent_commit = commit.parent(0).context("Impossible de charger le parent du commit")?;
        let parent_tree = parent_commit
            .tree()
            .context("Impossible de charger l'arborescence du commit parent")?;
        let diff = repo
            .diff_tree_to_tree(Some(&parent_tree), Some(&current_tree), Some(&mut diff_opts))
            .context("Erreur lors de la génération du diff entre commits")?;
        let stats = diff.stats().context("Erreur d'extraction des statistiques du diff")?;
        added += stats.insertions();
        deleted += stats.deletions();
    }

    Ok((added, deleted))
}

fn analyze_repository(cli: &Cli) -> Result<ActivityReport> {
    let repo = Repository::discover(&cli.path).with_context(|| {
        format!(
            "Dépôt Git introuvable à partir du chemin : {}",
            cli.path.display()
        )
    })?;

    let target_obj = repo
        .revparse_single(&cli.branch)
        .with_context(|| format!("Référence introuvable : '{}'", cli.branch))?;
    let target_commit = target_obj
        .as_commit()
        .with_context(|| format!("La référence '{}' ne pointe pas vers un commit", cli.branch))?;

    let mut revwalk: Revwalk = repo.revwalk().context("Échec d'initialisation du revwalk")?;
    revwalk
        .push(target_commit.id())
        .context("Échec d'attachement de la référence au parcours")?;
    revwalk.set_sorting(git2::Sort::TIME)?;

    // Table d'agrégation : (Nom, Email) -> (commits, added, deleted)
    let mut aggregated: HashMap<(String, String), (usize, usize, usize)> = HashMap::new();

    for oid_result in revwalk {
        let oid = oid_result.context("Erreur lors de l'itération des commits")?;
        let commit = match repo.find_commit(oid) {
            Ok(c) => c,
            Err(_) => continue,
        };

        let commit_timestamp = commit.time().seconds();
        let commit_date = Utc
            .timestamp_opt(commit_timestamp, 0)
            .single()
            .map(|dt| dt.date_naive());

        if let Some(date) = commit_date {
            if let Some(since) = cli.since {
                if date < since {
                    continue;
                }
            }
            if let Some(until) = cli.until {
                if date > until {
                    continue;
                }
            }
        }

        let author = commit.author();
        let name = author.name().unwrap_or("Inconnu").trim().to_string();
        let email = author.email().unwrap_or("inconnu@local").trim().to_string();

        let (added, deleted) = collect_commit_stats(&repo, &commit)?;

        let entry = aggregated.entry((name, email)).or_insert((0, 0, 0));
        entry.0 += 1;
        entry.1 += added;
        entry.2 += deleted;
    }

    let mut authors: Vec<AuthorStats> = aggregated
        .into_iter()
        .map(|((name, email), (commits, added, deleted))| {
            let net = (added as i64) - (deleted as i64);
            AuthorStats {
                name,
                email,
                commits,
                lines_added: added,
                lines_deleted: deleted,
                net_lines: net,
            }
        })
        .collect();

    match cli.sort {
        SortCriteria::Commits => authors.sort_by(|a, b| b.commits.cmp(&a.commits)),
        SortCriteria::Added => authors.sort_by(|a, b| b.lines_added.cmp(&a.lines_added)),
        SortCriteria::Deleted => authors.sort_by(|a, b| b.lines_deleted.cmp(&a.lines_deleted)),
        SortCriteria::Net => authors.sort_by(|a, b| b.net_lines.cmp(&a.net_lines)),
    }

    let total_authors = authors.len();
    let total_commits = authors.iter().map(|a| a.commits).sum();
    let total_lines_added = authors.iter().map(|a| a.lines_added).sum();
    let total_lines_deleted = authors.iter().map(|a| a.lines_deleted).sum();
    let total_net_lines = (total_lines_added as i64) - (total_lines_deleted as i64);

    Ok(ActivityReport {
        summary: ReportSummary {
            total_authors,
            total_commits,
            total_lines_added,
            total_lines_deleted,
            total_net_lines,
        },
        authors,
    })
}

fn print_table_report(report: &ActivityReport) {
    if report.authors.is_empty() {
        println!("Aucun commit trouvé pour les critères spécifiés.");
        return;
    }

    let mut table = Table::new();
    table
        .load_preset(UTF8_FULL)
        .set_content_arrangement(ContentArrangement::Dynamic)
        .set_header(vec![
            Cell::new("Auteur"),
            Cell::new("Email"),
            Cell::new("Commits").set_alignment(CellAlignment::Right),
            Cell::new("+ Ajouts").set_alignment(CellAlignment::Right),
            Cell::new("- Suppr.").set_alignment(CellAlignment::Right),
            Cell::new("Net").set_alignment(CellAlignment::Right),
        ]);

    for author in &report.authors {
        let net_display = if author.net_lines >= 0 {
            format!("+{}", author.net_lines)
        } else {
            format!("{}", author.net_lines)
        };

        table.add_row(vec![
            Cell::new(&author.name),
            Cell::new(&author.email),
            Cell::new(author.commits).set_alignment(CellAlignment::Right),
            Cell::new(author.lines_added).set_alignment(CellAlignment::Right),
            Cell::new(author.lines_deleted).set_alignment(CellAlignment::Right),
            Cell::new(net_display).set_alignment(CellAlignment::Right),
        ]);
    }

    let total_net_display = if report.summary.total_net_lines >= 0 {
        format!("+{}", report.summary.total_net_lines)
    } else {
        format!("{}", report.summary.total_net_lines)
    };

    table.add_row(vec![
        Cell::new("TOTAL"),
        Cell::new(format!("{} auteurs", report.summary.total_authors)),
        Cell::new(report.summary.total_commits).set_alignment(CellAlignment::Right),
        Cell::new(report.summary.total_lines_added).set_alignment(CellAlignment::Right),
        Cell::new(report.summary.total_lines_deleted).set_alignment(CellAlignment::Right),
        Cell::new(total_net_display).set_alignment(CellAlignment::Right),
    ]);

    println!("{table}");
}

fn main() -> Result<()> {
    let cli = Cli::parse();
    let report = analyze_repository(&cli)?;

    match cli.format {
        OutputFormat::Table => print_table_report(&report),
        OutputFormat::Json => {
            let json_output = serde_json::to_string_pretty(&report)
                .context("Erreur lors de la sérialisation en JSON")?;
            println!("{json_output}");
        }
    }

    Ok(())
}

