use std::path::{Path, PathBuf};
use std::time::Instant;

use anyhow::{bail, Context, Result};
use clap::Parser;
use colored::*;
use image::{DynamicImage, GenericImageView, ImageFormat, Rgb, RgbImage};

/// Arguments de ligne de commande pour PaletteOpt
#[derive(Parser, Debug)]
#[command(
    name = "palette_opt",
    author,
    version,
    about = "Optimiseur d'images bitmap par réduction de palette de couleurs avec rapport de gain de poids."
)]
struct Cli {
    /// Chemin de l'image source à optimiser
    #[arg(short, long)]
    input: PathBuf,

    /// Chemin du fichier de sortie (optionnel, par défaut: <nom>_optimized.<ext>)
    #[arg(short, long)]
    output: Option<PathBuf>,

    /// Nombre maximal de couleurs dans la palette réduite (entre 2 et 256)
    #[arg(short = 'c', long = "colors", default_value_t = 16)]
    colors: usize,

    /// Activer le tramage (Floyd-Steinberg dithering)
    #[arg(short = 'd', long = "dither", default_value_t = false)]
    dither: bool,
}

/// Représentation interne d'une couleur RVB pour les calculs de quantification
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct Color {
    r: u8,
    g: u8,
    b: u8,
}

impl Color {
    fn new(r: u8, g: u8, b: u8) -> Self {
        Self { r, g, b }
    }

    /// Calcule la distance quadratique dans l'espace RVB
    fn distance_sq(&self, other: &Color) -> i64 {
        let dr = self.r as i64 - other.r as i64;
        let dg = self.g as i64 - other.g as i64;
        let db = self.b as i64 - other.b as i64;
        dr * dr + dg * dg + db * db
    }

    /// Trouve la couleur la plus proche dans une palette
    fn find_closest(&self, palette: &[Color]) -> Color {
        palette
            .iter()
            .min_by_key(|c| self.distance_sq(c))
            .copied()
            .unwrap_or(*self)
    }
}

/// Boîte englobante pour l'algorithme Median-Cut
#[derive(Debug, Clone)]
struct ColorBox {
    colors: Vec<Color>,
}

impl ColorBox {
    fn new(colors: Vec<Color>) -> Self {
        Self { colors }
    }

    /// Détermine la dimension (R, G ou B) avec la plus grande variance / étendue
    fn longest_axis(&self) -> usize {
        let mut min_r = 255u8;
        let mut max_r = 0u8;
        let mut min_g = 255u8;
        let mut max_g = 0u8;
        let mut min_b = 255u8;
        let mut max_b = 0u8;

        for c in &self.colors {
            min_r = min_r.min(c.r);
            max_r = max_r.max(c.r);
            min_g = min_g.min(c.g);
            max_g = max_g.max(c.g);
            min_b = min_b.min(c.b);
            max_b = max_b.max(c.b);
        }

        let diff_r = max_r - min_r;
        let diff_g = max_g - min_g;
        let diff_b = max_b - min_b;

        if diff_r >= diff_g && diff_r >= diff_b {
            0 // Axe Rouge
        } else if diff_g >= diff_r && diff_g >= diff_b {
            1 // Axe Vert
        } else {
            2 // Axe Bleu
        }
    }

    /// Divise la boîte le long de son axe dominant selon la médiane
    fn split(mut self) -> (ColorBox, Option<ColorBox>) {
        if self.colors.len() <= 1 {
            return (self, None);
        }

        let axis = self.longest_axis();
        match axis {
            0 => self.colors.sort_unstable_by_key(|c| c.r),
            1 => self.colors.sort_unstable_by_key(|c| c.g),
            _ => self.colors.sort_unstable_by_key(|c| c.b),
        }

        let mid = self.colors.len() / 2;
        let right_colors = self.colors.split_off(mid);
        (ColorBox::new(self.colors), Some(ColorBox::new(right_colors)))
    }

    /// Calcule la couleur moyenne représentative de la boîte
    fn average_color(&self) -> Color {
        if self.colors.is_empty() {
            return Color::new(0, 0, 0);
        }

        let (sum_r, sum_g, sum_b) = self.colors.iter().fold((0u64, 0u64, 0u64), |acc, c| {
            (acc.0 + c.r as u64, acc.1 + c.g as u64, acc.2 + c.b as u64)
        });

        let count = self.colors.len() as u64;
        Color::new(
            (sum_r / count) as u8,
            (sum_g / count) as u8,
            (sum_b / count) as u8,
        )
    }
}

/// Génère une palette de `max_colors` couleurs à l'aide de Median Cut
fn generate_palette(pixels: &[Color], max_colors: usize) -> Vec<Color> {
    if pixels.is_empty() {
        return Vec::new();
    }

    let mut boxes = vec![ColorBox::new(pixels.to_vec())];

    while boxes.len() < max_colors {
        // Recherche de la boîte contenant le plus de pixels pour la diviser en priorité
        let (max_idx, max_box_len) = boxes
            .iter()
            .enumerate()
            .map(|(i, b)| (i, b.colors.len()))
            .max_by_key(|&(_, len)| len)
            .unwrap_or((0, 0));

        if max_box_len <= 1 {
            break; // Impossible de subdiviser davantage
        }

        let box_to_split = boxes.swap_remove(max_idx);
        let (box_a, box_b) = box_to_split.split();
        boxes.push(box_a);
        if let Some(b) = box_b {
            boxes.push(b);
        }
    }

    boxes.into_iter().map(|b| b.average_color()).collect()
}

/// Applique la quantification sans tramage
fn quantize_direct(img: &RgbImage, palette: &[Color]) -> RgbImage {
    let (width, height) = img.dimensions();
    let mut out = RgbImage::new(width, height);

    for (x, y, pixel) in img.enumerate_pixels() {
        let current = Color::new(pixel[0], pixel[1], pixel[2]);
        let closest = current.find_closest(palette);
        out.put_pixel(x, y, Rgb([closest.r, closest.g, closest.b]));
    }

    out
}

/// Applique la quantification avec tramage d'erreur de Floyd-Steinberg
fn quantize_floyd_steinberg(img: &RgbImage, palette: &[Color]) -> RgbImage {
    let (width, height) = img.dimensions();
    let w = width as usize;
    let h = height as usize;

    // Buffer d'erreur en virgule flottante pour chaque canal
    let mut buffer: Vec<[f32; 3]> = img
        .pixels()
        .map(|p| [p[0] as f32, p[1] as f32, p[2] as f32])
        .collect();

    let mut out = RgbImage::new(width, height);

    for y in 0..h {
        for x in 0..w {
            let idx = y * w + x;
            let current_rgb = buffer[idx];

            let clamped_r = current_rgb[0].clamp(0.0, 255.0).round() as u8;
            let clamped_g = current_rgb[1].clamp(0.0, 255.0).round() as u8;
            let clamped_b = current_rgb[2].clamp(0.0, 255.0).round() as u8;

            let source_color = Color::new(clamped_r, clamped_g, clamped_b);
            let closest = source_color.find_closest(palette);

            out.put_pixel(x as u32, y as u32, Rgb([closest.r, closest.g, closest.b]));

            // Calcul de l'erreur résiduelle
            let err_r = current_rgb[0] - closest.r as f32;
            let err_g = current_rgb[1] - closest.g as f32;
            let err_b = current_rgb[2] - closest.b as f32;
            let err = [err_r, err_g, err_b];

            // Diffusion de l'erreur selon le noyau de Floyd-Steinberg :
            //            [ * ]   7/16
            //    3/16    5/16    1/16
            let spread_error = |buf: &mut Vec<[f32; 3]>, nx: usize, ny: usize, factor: f32| {
                if nx < w && ny < h {
                    let n_idx = ny * w + nx;
                    buf[n_idx][0] += err[0] * factor;
                    buf[n_idx][1] += err[1] * factor;
                    buf[n_idx][2] += err[2] * factor;
                }
            };

            spread_error(&mut buffer, x + 1, y, 7.0 / 16.0);
            if x > 0 {
                spread_error(&mut buffer, x - 1, y + 1, 3.0 / 16.0);
            }
            spread_error(&mut buffer, x, y + 1, 5.0 / 16.0);
            spread_error(&mut buffer, x + 1, y + 1, 1.0 / 16.0);
        }
    }

    out
}

/// Dénombre les couleurs distinctes dans une image RVB
fn count_unique_colors(img: &RgbImage) -> usize {
    let mut set = HashSet::new();
    for p in img.pixels() {
        set.insert((p[0], p[1], p[2]));
    }
    set.len()
}

/// Formatage lisible de la taille en octets
fn format_file_size(bytes: u64) -> String {
    const KB: f64 = 1024.0;
    const MB: f64 = KB * 1024.0;
    let b = bytes as f64;

    if b >= MB {
        format!("{:.2} Mo", b / MB)
    } else if b >= KB {
        format!("{:.2} Ko", b / KB)
    } else {
        format!("{} octets", bytes)
    }
}

fn determine_output_path(input: &Path, user_output: Option<PathBuf>) -> PathBuf {
    if let Some(out) = user_output {
        return out;
    }

    let stem = input
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("image");

    let ext = input
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or("png");

    let parent = input.parent().unwrap_or_else(|| Path::new("."));
    parent.join(format!("{}_optimized.{}", stem, ext))
}

fn main() -> Result<()> {
    let start_total = Instant::now();
    let cli = Cli::parse();

    if cli.colors < 2 || cli.colors > 256 {
        bail!("Le nombre de couleurs doit être compris entre 2 et 256 (valeur demandée: {}).", cli.colors);
    }

    if !cli.input.exists() {
        bail!("Le fichier source n'existe pas : {}", cli.input.display());
    }

    let output_path = determine_output_path(&cli.input, cli.output);

    println!("{}", "=== Optimiseur d'Images & Réducteur de Palette ===".bold().cyan());
    println!("Fichier source : {}", cli.input.display().to_string().yellow());
    println!("Fichier cible  : {}", output_path.display().to_string().yellow());
    println!("Couleurs cibles: {}", cli.colors.to_string().green());
    println!("Dithering      : {}", if cli.dither { "Activé (Floyd-Steinberg)".green() } else { "Désactivé".normal() });
    println!();

    // 1. Chargement de l'image
    let load_start = Instant::now();
    let original_dyn = image::open(&cli.input)
        .with_context(|| format!("Impossible d'ouvrir l'image '{}'", cli.input.display()))?;
    let (width, height) = original_dyn.dimensions();
    let original_rgb = original_dyn.to_rgb8();
    let initial_unique_colors = count_unique_colors(&original_rgb);
    let original_size = fs::metadata(&cli.input)
        .with_context(|| format!("Impossible de lire les métadonnées de '{}'", cli.input.display()))?
        .len();
    let load_duration = load_start.elapsed();

    println!(
        "Image chargée : {}x{} px, {} couleurs uniques trouvées (en {:.2?})",
        width, height, initial_unique_colors, load_duration
    );

    // 2. Génération de la palette (Median Cut)
    let quant_start = Instant::now();
    let pixels: Vec<Color> = original_rgb
        .pixels()
        .map(|p| Color::new(p[0], p[1], p[2]))
        .collect();

    let palette = generate_palette(&pixels, cli.colors);
    println!("Palette de {} nuances générée.", palette.len().to_string().cyan());

    // 3. Application de la palette avec ou sans dithering
    let optimized_rgb = if cli.dither {
        quantize_floyd_steinberg(&original_rgb, &palette)
    } else {
        quantize_direct(&original_rgb, &palette)
    };
    let quant_duration = quant_start.elapsed();

    // 4. Sauvegarde de l'image optimisée
    let save_start = Instant::now();
    // Conserver le format source ou déduire de l'extension de sortie
    let format = ImageFormat::from_path(&output_path)
        .unwrap_or(ImageFormat::Png);

    DynamicImage::ImageRgb8(optimized_rgb.clone())
        .save_with_format(&output_path, format)
        .with_context(|| format!("Échec lors de l'enregistrement de l'image vers '{}'", output_path.display()))?;

    let save_duration = save_start.elapsed();
    let optimized_size = fs::metadata(&output_path)
        .with_context(|| format!("Impossible de lire les métadonnées du fichier généré '{}'", output_path.display()))?
        .len();

    let final_unique_colors = count_unique_colors(&optimized_rgb);
    let total_duration = start_total.elapsed();

    // 5. Rapport de performance et gain de poids
    println!("\n{}", "=== RAPPORT D'OPTIMISATION ===".bold().green());
    println!("{:<28} : {}", "Taille initiale", format_file_size(original_size));
    println!("{:<28} : {}", "Taille optimisée", format_file_size(optimized_size));

    let diff = original_size as i64 - optimized_size as i64;
    let ratio = if original_size > 0 {
        (diff as f64 / original_size as f64) * 100.0
    } else {
        0.0
    };

    if diff >= 0 {
        let gain_str = format!("-{} ({:.2}%)", format_file_size(diff as u64), ratio);
        println!("{:<28} : {}", "Gain d'espace", gain_str.bold().green());
    } else {
        let loss_str = format!("+{} (+{:.2}%)", format_file_size((-diff) as u64), -ratio);
        println!("{:<28} : {}", "Variation d'espace", loss_str.bold().yellow());
    }

    println!("{:<28} : {} -> {}", "Couleurs uniques", initial_unique_colors, final_unique_colors);
    println!("{:<28} : {:.2?}", "Temps de quantification", quant_duration);
    println!("{:<28} : {:.2?}", "Temps d'encodage", save_duration);
    println!("{:<28} : {:.2?}", "Temps total d'exécution", total_duration);
    println!("{}", "==============================\n".bold().green());

    Ok(())
}

