/// Représentation interne d'une couleur RVB pour les calculs de quantification
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct Color {
    r: u8,
    g: u8,
    b: u8,
}

impl Color {
    fn new(r: u8, g: u8, b: u8) -> Self {
        Self { r, g, b }
    }

    /// Calcule la distance quadratique dans l'espace RVB
    fn distance_sq(&self, other: &Color) -> i64 {
        let dr = self.r as i64 - other.r as i64;
        let dg = self.g as i64 - other.g as i64;
        let db = self.b as i64 - other.b as i64;
        dr * dr + dg * dg + db * db
    }

    /// Trouve la couleur la plus proche dans une palette
    fn find_closest(&self, palette: &[Color]) -> Color {
        palette
            .iter()
            .min_by_key(|c| self.distance_sq(c))
            .copied()
            .unwrap_or(*self)
    }
}

/// Boîte englobante pour l'algorithme Median-Cut
#[derive(Debug, Clone)]
struct ColorBox {
    colors: Vec<Color>,
}

impl ColorBox {
    fn new(colors: Vec<Color>) -> Self {
        Self { colors }
    }

    /// Détermine la dimension (R, G ou B) avec la plus grande variance / étendue
    fn longest_axis(&self) -> usize {
        let mut min_r = 255u8;
        let mut max_r = 0u8;
        let mut min_g = 255u8;
        let mut max_g = 0u8;
        let mut min_b = 255u8;
        let mut max_b = 0u8;

        for c in &self.colors {
            min_r = min_r.min(c.r);
            max_r = max_r.max(c.r);
            min_g = min_g.min(c.g);
            max_g = max_g.max(c.g);
            min_b = min_b.min(c.b);
            max_b = max_b.max(c.b);
        }

        let diff_r = max_r - min_r;
        let diff_g = max_g - min_g;
        let diff_b = max_b - min_b;

        if diff_r >= diff_g && diff_r >= diff_b {
            0 // Axe Rouge
        } else if diff_g >= diff_r && diff_g >= diff_b {
            1 // Axe Vert
        } else {
            2 // Axe Bleu
        }
    }

    /// Divise la boîte le long de son axe dominant selon la médiane
    fn split(mut self) -> (ColorBox, Option<ColorBox>) {
        if self.colors.len() <= 1 {
            return (self, None);
        }

        let axis = self.longest_axis();
        match axis {
            0 => self.colors.sort_unstable_by_key(|c| c.r),
            1 => self.colors.sort_unstable_by_key(|c| c.g),
            _ => self.colors.sort_unstable_by_key(|c| c.b),
        }

        let mid = self.colors.len() / 2;
        let right_colors = self.colors.split_off(mid);
        (ColorBox::new(self.colors), Some(ColorBox::new(right_colors)))
    }

    /// Calcule la couleur moyenne représentative de la boîte
    fn average_color(&self) -> Color {
        if self.colors.is_empty() {
            return Color::new(0, 0, 0);
        }

        let (sum_r, sum_g, sum_b) = self.colors.iter().fold((0u64, 0u64, 0u64), |acc, c| {
            (acc.0 + c.r as u64, acc.1 + c.g as u64, acc.2 + c.b as u64)
        });

        let count = self.colors.len() as u64;
        Color::new(
            (sum_r / count) as u8,
            (sum_g / count) as u8,
            (sum_b / count) as u8,
        )
    }
}

/// Génère une palette de `max_colors` couleurs à l'aide de Median Cut
fn generate_palette(pixels: &[Color], max_colors: usize) -> Vec<Color> {
    if pixels.is_empty() {
