    println!("Fichier cible  : {}", output_path.display().to_string().yellow());
    println!("Couleurs cibles: {}", cli.colors.to_string().green());
    println!("Dithering      : {}", if cli.dither { "Activé (Floyd-Steinberg)".green() } else { "Désactivé".normal() });
    println!();

    // 1. Chargement de l'image
    let load_start = Instant::now();
    let original_dyn = image::open(&cli.input)
        .with_context(|| format!("Impossible d'ouvrir l'image '{}'", cli.input.display()))?;
    let (width, height) = original_dyn.dimensions();
    let original_rgb = original_dyn.to_rgb8();
    let initial_unique_colors = count_unique_colors(&original_rgb);
    let original_size = fs::metadata(&cli.input)
        .with_context(|| format!("Impossible de lire les métadonnées de '{}'", cli.input.display()))?
        .len();
    let load_duration = load_start.elapsed();

    println!(
        "Image chargée : {}x{} px, {} couleurs uniques trouvées (en {:.2?})",
        width, height, initial_unique_colors, load_duration
    );

    // 2. Génération de la palette (Median Cut)
    let quant_start = Instant::now();
    let pixels: Vec<Color> = original_rgb
        .pixels()
        .map(|p| Color::new(p[0], p[1], p[2]))
        .collect();

    let palette = generate_palette(&pixels, cli.colors);
    println!("Palette de {} nuances générée.", palette.len().to_string().cyan());

    // 3. Application de la palette avec ou sans dithering
    let optimized_rgb = if cli.dither {
        quantize_floyd_steinberg(&original_rgb, &palette)
    } else {
        quantize_direct(&original_rgb, &palette)
    };
    let quant_duration = quant_start.elapsed();

    // 4. Sauvegarde de l'image optimisée
    let save_start = Instant::now();
    // Conserver le format source ou déduire de l'extension de sortie
    let format = ImageFormat::from_path(&output_path)
        .unwrap_or(ImageFormat::Png);

    DynamicImage::ImageRgb8(optimized_rgb.clone())
        .save_with_format(&output_path, format)
        .with_context(|| format!("Échec lors de l'enregistrement de l'image vers '{}'", output_path.display()))?;

    let save_duration = save_start.elapsed();
    let optimized_size = fs::metadata(&output_path)
        .with_context(|| format!("Impossible de lire les métadonnées du fichier généré '{}'", output_path.display()))?
        .len();

    let final_unique_colors = count_unique_colors(&optimized_rgb);
    let total_duration = start_total.elapsed();

    // 5. Rapport de performance et gain de poids
    println!("\n{}", "=== RAPPORT D'OPTIMISATION ===".bold().green());
    println!("{:<28} : {}", "Taille initiale", format_file_size(original_size));
    println!("{:<28} : {}", "Taille optimisée", format_file_size(optimized_size));

    let diff = original_size as i64 - optimized_size as i64;
    let ratio = if original_size > 0 {
        (diff as f64 / original_size as f64) * 100.0
    } else {
        0.0
    };

    if diff >= 0 {
        let gain_str = format!("-{} ({:.2}%)", format_file_size(diff as u64), ratio);
        println!("{:<28} : {}", "Gain d'espace", gain_str.bold().green());
    } else {
        let loss_str = format!("+{} (+{:.2}%)", format_file_size((-diff) as u64), -ratio);
        println!("{:<28} : {}", "Variation d'espace", loss_str.bold().yellow());
    }

    println!("{:<28} : {} -> {}", "Couleurs uniques", initial_unique_colors, final_unique_colors);
    println!("{:<28} : {:.2?}", "Temps de quantification", quant_duration);
    println!("{:<28} : {:.2?}", "Temps d'encodage", save_duration);
    println!("{:<28} : {:.2?}", "Temps total d'exécution", total_duration);
    println!("{}", "==============================\n".bold().green());

    Ok(())
}

