// src/main.rs
use std::collections::HashMap;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::time::{Duration, Instant};

use anyhow::{Context, Result};
use clap::Parser;
use hdrhistogram::Histogram;
use indicatif::{ProgressBar, ProgressStyle};
use reqwest::{Client, Method};
use tokio::sync::{Mutex, Semaphore};
use url::Url;

/// CLI de simulation de charge HTTP concurrente et mesure de latence p99.
#[derive(Parser, Debug)]
#[command(name = "http-load-bench")]
#[command(version = "0.1.0")]
#[command(about = "Simule une charge de requêtes HTTP concurrentes et calcule les percentiles de latence (p50, p90, p99, etc.)")]
struct Cli {
    /// URL cible à interroger
    #[arg(short = 'u', long = "url")]
    url: String,

    /// Nombre total de requêtes à envoyer
    #[arg(short = 'n', long = "requests", default_value_t = 1000)]
    requests: usize,

    /// Nombre maximal de requêtes concurrentes en parallèle
    #[arg(short = 'c', long = "concurrency", default_value_t = 50)]
    concurrency: usize,

    /// Timeout individuel par requête en secondes
    #[arg(short = 't', long = "timeout", default_value_t = 10)]
    timeout_secs: u64,

    /// Méthode HTTP utilisée (GET, POST, PUT, DELETE, HEAD)
    #[arg(short = 'm', long = "method", default_value = "GET")]
    method: String,
}

struct BenchmarkMetrics {
    histogram: Mutex<Histogram<u64>>,
    status_codes: Mutex<HashMap<u16, usize>>,
    errors: AtomicUsize,
    successes: AtomicUsize,
}

#[tokio::main]
async fn main() -> Result<()> {
    let args = Cli::parse();

    // Validation de l'URL cible
    let target_url = Url::parse(&args.url).context("Format d'URL invalide fourni en argument")?;

    // Validation de la méthode HTTP
    let http_method = args
        .method
        .to_uppercase()
        .parse::<Method>()
        .with_context(|| format!("Méthode HTTP invalide: '{}'", args.method))?;

    if args.requests == 0 {
        anyhow::bail!("Le nombre total de requêtes doit être supérieur à zéro.");
    }
    if args.concurrency == 0 {
        anyhow::bail!("Le niveau de concurrence doit être au minimum de 1.");
    }

    println!("============================================================");
    println!(" Démarrage du benchmark HTTP");
    println!(" Cible         : {}", target_url);
    println!(" Méthode       : {}", http_method);
    println!(" Total reqs    : {}", args.requests);
    println!(" Concurrence   : {}", args.concurrency);
    println!(" Timeout       : {}s", args.timeout_secs);
    println!("============================================================");

    // Initialisation du client HTTP reqwest
    let client = Client::builder()
        .timeout(Duration::from_secs(args.timeout_secs))
        .pool_max_idle_per_host(args.concurrency)
        .tcp_nodelay(true)
        .build()
        .context("Échec de l'initialisation du client HTTP")?;

    // Histogramme dynamique : suivi des latences de 1 microseconde (1 µs) à 60 secondes avec 3 chiffres significatifs
    let initial_hist = Histogram::<u64>::new_with_bounds(1, 60_000_000, 3)
        .context("Impossible de créer l'histogramme de latence")?;

    let metrics = Arc::new(BenchmarkMetrics {
        histogram: Mutex::new(initial_hist),
        status_codes: Mutex::new(HashMap::new()),
        errors: AtomicUsize::new(0),
        successes: AtomicUsize::new(0),
    });

    let semaphore = Arc::new(Semaphore::new(args.concurrency));

    let progress_bar = ProgressBar::new(args.requests as u64);
    progress_bar.set_style(
        ProgressStyle::default_bar()
            .template("{spinner:.green} [{elapsed_precise}] [{bar:40.cyan/blue}] {pos}/{len} ({percent}%) [ETA: {eta}] - {msg}")
            .context("Erreur de gabarit pour la barre de progression")?
            .progress_chars("#>-"),
    );

    let start_total = Instant::now();
    let mut handles = Vec::with_capacity(args.requests);

    for _ in 0..args.requests {
        let permit = semaphore
            .clone()
            .acquire_owned()
            .await
            .context("Échec lors de l'acquisition du sémaphore de concurrence")?;

        let client = client.clone();
        let url = target_url.clone();
        let method = http_method.clone();
        let metrics = metrics.clone();
        let pb = progress_bar.clone();

        let handle = tokio::spawn(async move {
            let start_req = Instant::now();
            let response_result = client.request(method, url).send().await;
            let elapsed_micros = start_req.elapsed().as_micros() as u64;

            drop(permit);

            match response_result {
                Ok(response) => {
                    let status = response.status().as_u16();

                    // Tentative d'enregistrement dans l'histogramme
                    let mut hist = metrics.histogram.lock().await;
                    let clamped_duration = elapsed_micros.clamp(1, 60_000_000);
                    let _ = hist.record(clamped_duration);

                    let mut codes = metrics.status_codes.lock().await;
                    *codes.entry(status).or_insert(0) += 1;

                    metrics.successes.fetch_add(1, Ordering::Relaxed);
                }
                Err(_) => {
                    metrics.errors.fetch_add(1, Ordering::Relaxed);
                }
            }

            pb.inc(1);
        });

        handles.push(handle);
    }

    // Attente de toutes les requêtes
    for handle in handles {
        if let Err(e) = handle.await {
            eprintln!("Erreur lors de l'exécution d'une tâche de requête : {e}");
        }
    }

    let total_duration = start_total.elapsed();
    progress_bar.finish_with_message("Terminé !");

    let successes = metrics.successes.load(Ordering::Relaxed);
    let errors = metrics.errors.load(Ordering::Relaxed);
    let total_executed = successes + errors;
    let rps = if total_duration.as_secs_f64() > 0.0 {
        total_executed as f64 / total_duration.as_secs_f64()
    } else {
        0.0
    };

    println!("\n=================== RÉSULTATS DU BENCHMARK ===================");
    println!("Durée totale écoulée       : {:.3?}", total_duration);
    println!("Requêtes exécutées         : {}", total_executed);
    println!("Requêtes réussies          : {}", successes);
    println!("Requêtes échouées          : {}", errors);
    println!("Débit moyen (RPS)          : {:.2} req/sec", rps);

    let codes = metrics.status_codes.lock().await;
    if !codes.is_empty() {
        println!("\n--- Distribution des statuts HTTP ---");
        let mut sorted_codes: Vec<_> = codes.iter().collect();
        sorted_codes.sort_by_key(|(k, _)| *k);
        for (code, count) in sorted_codes {
            println!("  HTTP {} : {} réponse(s)", code, count);
        }
    }

    let hist = metrics.histogram.lock().await;
    if hist.len() > 0 {
        let to_ms = |val: u64| (val as f64) / 1000.0;

        println!("\n--- Distribution des Latences ---");
        println!("  Minimum (min)            : {:>9.2} ms", to_ms(hist.min()));
        println!("  Moyenne (mean)           : {:>9.2} ms", hist.mean() / 1000.0);
        println!("  Médiane (p50)            : {:>9.2} ms", to_ms(hist.value_at_quantile(0.50)));
        println!("  Percentile 90 (p90)      : {:>9.2} ms", to_ms(hist.value_at_quantile(0.90)));
        println!("  Percentile 95 (p95)      : {:>9.2} ms", to_ms(hist.value_at_quantile(0.95)));
        println!("  Percentile 99 (p99)      : {:>9.2} ms", to_ms(hist.value_at_quantile(0.99)));
        println!("  Percentile 99.9 (p99.9)  : {:>9.2} ms", to_ms(hist.value_at_quantile(0.999)));
        println!("  Maximum (max)            : {:>9.2} ms", to_ms(hist.max()));
        println!("  Écart-type               : {:>9.2} ms", hist.stdev() / 1000.0);
    } else {
        println!("\nAucune latence enregistrée (toutes les requêtes ont échoué).");
    }
    println!("==============================================================");

    Ok(())
}

