    pub input: PathBuf,

    /// Chemin du fichier de catalogue JSON de sortie
    #[arg(short = 'o', long = "output")]
    pub output: PathBuf,

    /// Extensions des fichiers cibles séparées par des virgules (ex: "rs,js,ts,vue,html")
    #[arg(
        short = 'e',
        long = "extensions",
        default_value = "rs,js,ts,jsx,tsx,vue,html"
    )]
    pub extensions: String,

    /// Format du catalogue produit
    #[arg(short = 'f', long = "format", value_enum, default_value_t = CatalogFormat::Flat)]
    pub format: CatalogFormat,

    /// Conserve les clés existantes dans le catalogue qui ne sont plus détectées dans le code source
    #[arg(long = "keep-obsolete")]
    pub keep_obsolete: bool,

    /// Affiche les statistiques et le résultat sans écrire sur le disque
    #[arg(long = "dry-run")]
    pub dry_run: bool,

    /// Active les logs d'informations détaillées
    #[arg(short = 'v', long = "verbose")]
    pub verbose: bool,
}

/// Détail d'une entrée dans le mode détaillé
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct DetailedEntry {
    /// Traduction ou valeur de secours
    pub translation: String,
    /// Liste des occurrences détectées (fichier:ligne)
    pub locations: Vec<String>,
}

/// Occurrence détectée dans le code source
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ExtractedString {
    pub key: String,
    pub file_path: String,
    pub line_number: usize,
}

/// Analyseur et extracteur de chaînes i18n
pub struct Extractor {
    patterns: Vec<Regex>,
    allowed_extensions: BTreeSet<String>,
}

impl Extractor {
    /// Initialise un extracteur avec les extensions autorisées et les motifs par défaut
    pub fn new(extensions: &[&str]) -> Result<Self> {
        let patterns = vec![
            // Reconnaît t("clé") ou t('clé')
            Regex::new(r#"(?:^|[^a-zA-Z0-9_])t\(\s*["']([^"']+)["']\s*\)"#)
                .context("Erreur de compilation du regex pour t(...)")?,
            // Reconnaît tr!("clé") ou tr!('clé') (Rust)
            Regex::new(r#"(?:^|[^a-zA-Z0-9_])tr!\(\s*["']([^"']+)["']\s*\)"#)
                .context("Erreur de compilation du regex pour tr!(...)")?,
            // Reconnaît i18n.t("clé") ou $t("clé")
            Regex::new(r#"(?:^|[^a-zA-Z0-9_])(?:i18n\.t|\$t)\(\s*["']([^"']+)["']\s*\)"#)
                .context("Erreur de compilation du regex pour i18n.t(...)")?,
        ];

        let allowed_extensions = extensions
            .iter()
            .map(|ext| ext.trim().trim_start_matches('.').to_lowercase())
            .filter(|ext| !ext.is_empty())
            .collect();

        Ok(Self {
            patterns,
            allowed_extensions,
        })
    }

    /// Vérifie si un chemin de fichier possède l'une des extensions acceptées
    fn is_file_eligible(&self, path: &Path) -> bool {
        if !path.is_file() {
            return false;
        }

        path.extension()
            .and_then(|ext| ext.to_str())
            .map(|ext| self.allowed_extensions.contains(&ext.to_lowercase()))
            .unwrap_or(false)
    }

    /// Parcourt récursivement le répertoire d'entrée et extrait les chaînes traduisibles
    pub fn scan_path(&self, root_path: &Path) -> Result<Vec<ExtractedString>> {
        let mut results = Vec::new();

        for entry in WalkDir::new(root_path)
            .into_iter()
            .filter_entry(|e| !is_ignored(e.path()))
        {
            let entry = match entry {
                Ok(e) => e,
                Err(err) => {
                    warn!("Impossible d'accéder au chemin : {}", err);
                    continue;
                }
            };

            let path = entry.path();
            if self.is_file_eligible(path) {
                match self.scan_file(path) {
                    Ok(mut extracted) => results.append(&mut extracted),
                    Err(err) => {
                        warn!("Erreur lors de la lecture du fichier {}: {}", path.display(), err);
                    }
                }
            }
        }

        Ok(results)
    }

    /// Extrait les chaînes d'un fichier source donné
    pub fn scan_file(&self, path: &Path) -> Result<Vec<ExtractedString>> {
        let file = File::open(path)
            .with_context(|| format!("Impossible d'ouvrir le fichier {}", path.display()))?;
        let reader = BufReader::new(file);
        let path_str = path.display().to_string();

        let mut matches = Vec::new();

        for (index, line_result) in reader.lines().enumerate() {
            let line_number = index + 1;
            let line = match line_result {
                Ok(l) => l,
                Err(_) => {
                    // Ignore les lignes contenant des caractères binaires ou non-UTF-8 invalides
                    continue;
                }
            };

            for pattern in &self.patterns {
                for capture in pattern.captures_iter(&line) {
                    if let Some(key_match) = capture.get(1) {
                        matches.push(ExtractedString {
                            key: key_match.as_str().to_string(),
                            file_path: path_str.clone(),
                            line_number,
                        });
                    }
                }
            }
        }

        Ok(matches)
    }
}

/// Détermine si un dossier ou fichier doit être ignoré lors du parcours récursif
fn is_ignored(path: &Path) -> bool {
    if let Some(file_name) = path.file_name().and_then(|f| f.to_str()) {
        let ignored_names = [
            ".git",
            "target",
            "node_modules",
            "dist",
            "build",
            ".idea",
            ".vscode",
        ];
        if ignored_names.contains(&file_name) {
            return true;
        }
    }
    false
}

/// Fusionne les nouvelles chaînes extraites avec un catalogue plat existant
pub fn merge_flat_catalog(
    existing: BTreeMap<String, String>,
    extracted: &[ExtractedString],
    keep_obsolete: bool,
) -> (BTreeMap<String, String>, usize, usize) {
    let mut current_keys = BTreeSet::new();
    let mut updated_catalog = BTreeMap::new();
    let mut new_keys_count = 0;

    for item in extracted {
        current_keys.insert(item.key.clone());
        if !updated_catalog.contains_key(&item.key) {
            let translation = existing
                .get(&item.key)
                .cloned()
                .unwrap_or_else(|| {
                    new_keys_count += 1;
                    item.key.clone()
                });
            updated_catalog.insert(item.key.clone(), translation);
        }
    }

    let mut obsolete_keys_count = 0;
    if keep_obsolete {
        for (key, val) in existing {
            if !current_keys.contains(&key) {
                obsolete_keys_count += 1;
                updated_catalog.insert(key, val);
            }
        }
    } else {
        for key in existing.keys() {
            if !current_keys.contains(key) {
                obsolete_keys_count += 1;
            }
        }
    }

    (updated_catalog, new_keys_count, obsolete_keys_count)
}

/// Fusionne les nouvelles chaînes extraites avec un catalogue détaillé existant
pub fn merge_detailed_catalog(
    existing: BTreeMap<String, DetailedEntry>,
    extracted: &[ExtractedString],
    keep_obsolete: bool,
) -> (BTreeMap<String, DetailedEntry>, usize, usize) {
    let mut current_keys = BTreeSet::new();
    let mut locations_map: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();

    for item in extracted {
        current_keys.insert(item.key.clone());
        let loc = format!("{}:{}", item.file_path, item.line_number);
        locations_map.entry(item.key.clone()).or_default().insert(loc);
    }

    let mut updated_catalog = BTreeMap::new();
    let mut new_keys_count = 0;

    for (key, loc_set) in locations_map {
        let locations: Vec<String> = loc_set.into_iter().collect();
        let translation = if let Some(existing_entry) = existing.get(&key) {
            existing_entry.translation.clone()
        } else {
            new_keys_count += 1;
            key.clone()
        };

        updated_catalog.insert(
            key,
            DetailedEntry {
                translation,
                locations,
            },
        );
    }

    let mut obsolete_keys_count = 0;
    if keep_obsolete {
        for (key, mut entry) in existing {
            if !current_keys.contains(&key) {
                obsolete_keys_count += 1;
                entry.locations.clear(); // Plus d'occurrence courante
                updated_catalog.insert(key, entry);
            }
        }
    } else {
        for key in existing.keys() {
            if !current_keys.contains(key) {
                obsolete_keys_count += 1;
            }
        }
    }

    (updated_catalog, new_keys_count, obsolete_keys_count)
}

/// Charge un catalogue JSON plat existant ou renvoie une table vide
pub fn load_flat_catalog(path: &Path) -> Result<BTreeMap<String, String>> {
    if !path.exists() {
        return Ok(BTreeMap::new());
    }
    let file = File::open(path)
        .with_context(|| format!("Échec d'ouverture du fichier {}", path.display()))?;
    let reader = BufReader::new(file);
    let catalog = serde_json::from_reader(reader)
        .with_context(|| format!("Format JSON invalide dans {}", path.display()))?;
    Ok(catalog)
}

/// Charge un catalogue JSON détaillé existant ou renvoie une table vide
pub fn load_detailed_catalog(path: &Path) -> Result<BTreeMap<String, DetailedEntry>> {
    if !path.exists() {
        return Ok(BTreeMap::new());
    }
    let file = File::open(path)
        .with_context(|| format!("Échec d'ouverture du fichier {}", path.display()))?;
    let reader = BufReader::new(file);
    let catalog = serde_json::from_reader(reader)
        .with_context(|| format!("Format JSON invalide dans {}", path.display()))?;
    Ok(catalog)
}

/// Enregistre les données sérialisables dans un fichier JSON avec indentation
pub fn save_json<T: Serialize>(path: &Path, data: &T) -> Result<()> {
    if let Some(parent) = path.parent() {
        if !parent.exists() {
            fs::create_dir_all(parent).with_context(|| {
                format!(
                    "Impossible de créer le répertoire parent {}",
                    parent.display()
                )
            })?;
        }
    }

    let file = File::create(path)
        .with_context(|| format!("Impossible de créer le fichier {}", path.display()))?;
    let writer = BufWriter::new(file);
    serde_json::to_writer_pretty(writer, data)
        .with_context(|| format!("Erreur d'écriture JSON dans {}", path.display()))?;

    Ok(())
}

fn main() -> Result<()> {
    let args = CliArgs::parse();

    // Configuration des logs
    let filter = if args.verbose { "debug" } else { "info" };
    tracing_subscriber::fmt()
        .with_env_filter(filter)
        .init();

    info!("Démarrage de l'extraction depuis : {}", args.input.display());

    let extensions: Vec<&str> = args.extensions.split(',').collect();
    let extractor = Extractor::new(&extensions)
        .context("Échec d'initialisation de l'extracteur")?;

    let extracted_items = extractor
        .scan_path(&args.input)
        .context("Erreur lors de l'analyse des fichiers sources")?;

    info!(
        "Scan terminé : {} occurrence(s) trouvée(s)",
        extracted_items.len()
    );

    match args.format {
        CatalogFormat::Flat => {
            let existing_catalog = load_flat_catalog(&args.output)
                .unwrap_or_else(|err| {
                    warn!(
                        "Catalogue existant non trouvé ou invalide ({}), création d'un nouveau",
                        err
                    );
                    BTreeMap::new()
                });

            let (merged, new_count, obsolete_count) =
                merge_flat_catalog(existing_catalog, &extracted_items, args.keep_obsolete);

            println!("--- Résumé de l'extraction ---");
            println!("Total de clés uniques  : {}", merged.len());
            println!("Nouvelles clés ajoutées: {}", new_count);
            println!(
                "Clés obsolètes         : {} ({})",
                obsolete_count,
                if args.keep_obsolete { "conservées" } else { "supprimées" }
            );

            if !args.dry_run {
                save_json(&args.output, &merged)
                    .with_context(|| format!("Impossible de sauvegarder {}", args.output.display()))?;
                println!("Fichier écrit avec succès dans : {}", args.output.display());
            } else {
                println!("[Mode Dry-Run] Aucune modification écrite sur le disque.");
            }
        }
        CatalogFormat::Detailed => {
            let existing_catalog = load_detailed_catalog(&args.output)
                .unwrap_or_else(|err| {
                    warn!(
                        "Catalogue existant non trouvé ou invalide ({}), création d'un nouveau",
                        err
                    );
                    BTreeMap::new()
                });

            let (merged, new_count, obsolete_count) =
                merge_detailed_catalog(existing_catalog, &extracted_items, args.keep_obsolete);

            println!("--- Résumé de l'extraction (Mode Détaillé) ---");
            println!("Total de clés uniques  : {}", merged.len());
            println!("Nouvelles clés ajoutées: {}", new_count);
            println!(
                "Clés obsolètes         : {} ({})",
                obsolete_count,
                if args.keep_obsolete { "conservées" } else { "supprimées" }
            );

            if !args.dry_run {
                save_json(&args.output, &merged)
                    .with_context(|| format!("Impossible de sauvegarder {}", args.output.display()))?;
                println!("Fichier écrit avec succès dans : {}", args.output.display());
            } else {
                println!("[Mode Dry-Run] Aucune modification écrite sur le disque.");
            }
        }
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_regex_extraction() {
        let extractor = Extractor::new(&["rs", "js"]).expect("Initialisation réussie");
        let content = r#"
            let msg = t("hello.world");
            let second = tr!("save.button");
            let ignored = "not an i18n string";
            let vue = $t("app.title");
            let complex = i18n.t("nav.home");
        "#;

        let mut matches = Vec::new();
        for pattern in &extractor.patterns {
            for cap in pattern.captures_iter(content) {
                if let Some(m) = cap.get(1) {
                    matches.push(m.as_str().to_string());
                }
            }
        }

        assert!(matches.contains(&"hello.world".to_string()));
        assert!(matches.contains(&"save.button".to_string()));
        assert!(matches.contains(&"app.title".to_string()));
        assert!(matches.contains(&"nav.home".to_string()));
        assert!(!matches.contains(&"not an i18n string".to_string()));
    }

    #[test]
    fn test_merge_flat_preserve_existing() {
        let mut existing = BTreeMap::new();
        existing.insert("auth.login".to_string(), "Connexion".to_string());
        existing.insert("auth.logout".to_string(), "Déconnexion".to_string());

        let extracted = vec![
            ExtractedString {
                key: "auth.login".to_string(),
                file_path: "src/auth.rs".to_string(),
                line_number: 10,
            },
            ExtractedString {
                key: "auth.signup".to_string(),
                file_path: "src/auth.rs".to_string(),
                line_number: 25,
            },
        ];

        let (merged, new_count, obsolete_count) = merge_flat_catalog(existing, &extracted, false);

        assert_eq!(new_count, 1);
        assert_eq!(obsolete_count, 1);
        assert_eq!(merged.get("auth.login"), Some(&"Connexion".to_string()));
        assert_eq!(merged.get("auth.signup"), Some(&"auth.signup".to_string()));
        assert!(!merged.contains_key("auth.logout"));
    }
}

