// src/main.rs
use std::fs;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use anyhow::{bail, Context, Result};
use clap::{Parser, ValueEnum};
use colored::Colorize;
use dialoguer::Select;
use serde_json::Value;

#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
pub enum Strategy {
    /// Utilise les valeurs de la source (écrase la base).
    Theirs,
    /// Conserve les valeurs de la base (ignore la source en cas de conflit).
    Ours,
    /// Demande interactivement pour chaque conflit.
    Interactive,
    /// Échoue immédiatement dès qu'un conflit survient.
    Error,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
pub enum ArrayMode {
    /// Remplace le tableau existant par le nouveau.
    Replace,
    /// Concatène les éléments du nouveau tableau à la fin.
    Append,
    /// Concatène et retire les doublons consécutifs ou identiques.
    Union,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
pub enum ConfigFormat {
    Json,
    Yaml,
    Toml,
}

#[derive(Parser, Debug)]
#[command(
    name = "cfgmerge",
    author,
    version,
    about = "Fusion intelligente de fichiers de configuration avec gestion des conflits et écrasement sélectif"
)]
pub struct Cli {
    /// Fichier de base (cible qui sera mise à jour).
    #[arg(short = 'b', long = "base", value_name = "BASE_FILE")]
    pub base: PathBuf,

    /// Fichier source contenant les modifications à intégrer.
    #[arg(short = 's', long = "source", value_name = "SOURCE_FILE")]
    pub source: PathBuf,

    /// Fichier de sortie (si omis, met à jour le fichier base sur place).
    #[arg(short = 'o', long = "output", value_name = "OUTPUT_FILE")]
    pub output: Option<PathBuf>,

    /// Stratégie de résolution générale en cas de conflit scalaire.
    #[arg(long = "strategy", value_enum, default_value_t = Strategy::Theirs)]
    pub strategy: Strategy,

    /// Mode de fusion des tableaux.
    #[arg(long = "array-mode", value_enum, default_value_t = ArrayMode::Replace)]
    pub array_mode: ArrayMode,

    /// Chemins de clés à écraser inconditionnellement (priorité source), ex: "server.port" ou "db.*".
    #[arg(long = "overwrite-path", value_name = "KEY_PATH")]
    pub overwrite_paths: Vec<String>,

    /// Chemins de clés à conserver inconditionnellement (priorité base), ex: "auth.secret".
    #[arg(long = "keep-path", value_name = "KEY_PATH")]
    pub keep_paths: Vec<String>,

    /// Force le format des configurations au lieu de se baser sur l'extension.
    #[arg(long = "format", value_enum)]
    pub format: Option<ConfigFormat>,

    /// Mode simulation : n'écrit aucun fichier, affiche le résultat fusionné sur stdout.
    #[arg(long = "dry-run")]
    pub dry_run: bool,

    /// Crée une sauvegarde (.bak) avant d'écraser le fichier de base.
    #[arg(long = "backup")]
    pub backup: bool,
}

impl ConfigFormat {
    pub fn from_path(path: &Path) -> Result<Self> {
        let ext = path
            .extension()
            .and_then(|e| e.to_str())
            .unwrap_or("")
            .to_ascii_lowercase();

        match ext.as_str() {
            "json" => Ok(ConfigFormat::Json),
            "yaml" | "yml" => Ok(ConfigFormat::Yaml),
            "toml" => Ok(ConfigFormat::Toml),
            _ => bail!(
                "Impossible de déduire le format pour '{}'. Utilisez --format pour le spécifier.",
                path.display()
            ),
        }
    }
}

pub struct Merger {
    pub strategy: Strategy,
    pub array_mode: ArrayMode,
    pub overwrite_paths: Vec<String>,
    pub keep_paths: Vec<String>,
}

impl Merger {
    pub fn new(
        strategy: Strategy,
        array_mode: ArrayMode,
        overwrite_paths: Vec<String>,
        keep_paths: Vec<String>,
    ) -> Self {
        Self {
            strategy,
            array_mode,
            overwrite_paths,
            keep_paths,
        }
    }

    fn matches_pattern(pattern: &str, path: &str) -> bool {
        if pattern == path {
            return true;
        }
        if let Some(prefix) = pattern.strip_suffix(".*") {
            if path.starts_with(prefix) && (path.len() == prefix.len() || path[prefix.len()..].starts_with('.')) {
                return true;
            }
        }
        false
    }

    fn is_forced_overwrite(&self, path: &str) -> bool {
        self.overwrite_paths
            .iter()
            .any(|p| Self::matches_pattern(p, path))
    }

    fn is_forced_keep(&self, path: &str) -> bool {
        self.keep_paths
            .iter()
            .any(|p| Self::matches_pattern(p, path))
    }

    pub fn merge_values(&self, base: Value, source: Value, current_path: &str) -> Result<Value> {
        let clean_path = current_path.trim_start_matches('.');

        // 1. Priorité aux filtres sélectifs
        if !clean_path.is_empty() {
            if self.is_forced_keep(clean_path) {
                return Ok(base);
            }
            if self.is_forced_overwrite(clean_path) {
                return Ok(source);
            }
        }

        match (base, source) {
            // Fusion récursive des dictionnaires / tables / objets
            (Value::Object(mut base_map), Value::Object(source_map)) => {
                for (key, src_val) in source_map {
                    let sub_path = if current_path.is_empty() {
                        key.clone()
                    } else {
                        format!("{current_path}.{key}")
                    };

                    if let Some(base_val) = base_map.remove(&key) {
                        let merged = self.merge_values(base_val, src_val, &sub_path)?;
                        base_map.insert(key, merged);
                    } else {
                        base_map.insert(key, src_val);
                    }
                }
                Ok(Value::Object(base_map))
            }

            // Fusion des tableaux selon la politique choisie
            (Value::Array(mut base_arr), Value::Array(source_arr)) => match self.array_mode {
                ArrayMode::Replace => Ok(Value::Array(source_arr)),
                ArrayMode::Append => {
                    base_arr.extend(source_arr);
                    Ok(Value::Array(base_arr))
                }
                ArrayMode::Union => {
                    for item in source_arr {
                        if !base_arr.contains(&item) {
                            base_arr.push(item);
                        }
                    }
                    Ok(Value::Array(base_arr))
                }
            },

            // Même valeur : aucun conflit
            (b, s) if b == s => Ok(b),

            // Conflit entre valeurs différentes
            (b, s) => self.resolve_conflict(clean_path, b, s),
        }
    }

    fn resolve_conflict(&self, path: &str, base: Value, source: Value) -> Result<Value> {
        match self.strategy {
            Strategy::Theirs => Ok(source),
            Strategy::Ours => Ok(base),
            Strategy::Error => {
                bail!(
                    "Conflit non résolu pour la clé '{}': base={:?}, source={:?}",
                    path,
                    base,
                    source
                );
            }
            Strategy::Interactive => {
                println!(
                    "\n{} Conflit détecté sur '{}'",
                    "⚠".yellow().bold(),
                    path.bold()
                );
                println!("  Base (existant) : {}", serde_json::to_string(&base)?.red());
                println!("  Source (nouveau): {}", serde_json::to_string(&source)?.green());

                let options = vec![
                    "Conserver la valeur de la Base",
                    "Écraser avec la valeur Source",
                ];

                let selection = Select::new()
                    .with_prompt("Quelle valeur souhaitez-vous retenir ?")
                    .items(&options)
                    .default(0)
                    .interact()
                    .context("Échec de la saisie utilisateur")?;

                if selection == 0 {
                    Ok(base)
                } else {
                    Ok(source)
                }
            }
        }
    }
}

fn parse_file(path: &Path, forced_fmt: Option<ConfigFormat>) -> Result<Value> {
    let content = fs::read_to_string(path)
        .with_context(|| format!("Impossible de lire le fichier: {}", path.display()))?;

    let format = match forced_fmt {
        Some(f) => f,
        None => ConfigFormat::from_path(path)?,
    };

    match format {
        ConfigFormat::Json => serde_json::from_str(&content)
            .with_context(|| format!("Erreur de désérialisation JSON pour '{}'", path.display())),
        ConfigFormat::Yaml => serde_yaml::from_str(&content)
            .with_context(|| format!("Erreur de désérialisation YAML pour '{}'", path.display())),
        ConfigFormat::Toml => {
            let toml_val: toml::Value = toml::from_str(&content).with_context(|| {
                format!("Erreur de désérialisation TOML pour '{}'", path.display())
            })?;
            // Convertit toml::Value vers serde_json::Value
            serde_json::to_value(toml_val).context("Erreur de conversion TOML vers AST canonique")
        }
    }
}

fn serialize_to_string(val: &Value, format: ConfigFormat) -> Result<String> {
    match format {
        ConfigFormat::Json => {
            serde_json::to_string_pretty(val).context("Erreur de sérialisation JSON")
        }
        ConfigFormat::Yaml => {
            serde_yaml::to_string(val).context("Erreur de sérialisation YAML")
        }
        ConfigFormat::Toml => {
            let toml_val: toml::Value = serde_json::from_value(val.clone())
                .context("Erreur de conversion AST canonique vers structure TOML")?;
            toml::to_string_pretty(&toml_val).context("Erreur de sérialisation TOML")
        }
    }
}

fn run() -> Result<()> {
    let cli = Cli::parse();

    if !cli.base.exists() {
        bail!("Le fichier base '{}' n'existe pas.", cli.base.display());
    }
    if !cli.source.exists() {
        bail!("Le fichier source '{}' n'existe pas.", cli.source.display());
    }

    let output_target = cli.output.as_ref().unwrap_or(&cli.base);
    let output_format = match cli.format {
        Some(f) => f,
        None => ConfigFormat::from_path(output_target)?,
    };

    let base_val = parse_file(&cli.base, cli.format)?;
    let source_val = parse_file(&cli.source, cli.format)?;

    let merger = Merger::new(
        cli.strategy,
        cli.array_mode,
        cli.overwrite_paths,
        cli.keep_paths,
    );

    let merged_val = merger.merge_values(base_val, source_val, "")?;
    let serialized = serialize_to_string(&merged_val, output_format)?;

    if cli.dry_run {
        println!("{}", "--- RÉSULTAT DE FUSION (DRY-RUN) ---".cyan().bold());
        println!("{serialized}");
        return Ok(());
    }

    if cli.backup && output_target.exists() {
        let backup_path = output_target.with_extension(format!(
            "{}.bak",
            output_target
                .extension()
                .and_then(|s| s.to_str())
                .unwrap_or("")
        ));
        fs::copy(output_target, &backup_path).with_context(|| {
            format!(
                "Impossible de créer la sauvegarde dans '{}'",
                backup_path.display()
            )
        })?;
        println!(
            "{} Sauvegarde créée : {}",
            "✓".green(),
            backup_path.display()
        );
    }

    fs::write(output_target, serialized).with_context(|| {
        format!(
            "Impossible d'écrire le résultat dans '{}'",
            output_target.display()
        )
    })?;

    println!(
        "{} Fusion appliquée avec succès dans '{}'",
        "✓".green().bold(),
        output_target.display()
    );

    Ok(())
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("{} {:#}", "Erreur :".red().bold(), err);
            ExitCode::FAILURE
        }
    }
}

