    use serde_json::json;

    #[test]
    fn test_merge_shallow_theirs() {
        let merger = Merger::new(Strategy::Theirs, ArrayMode::Replace, vec![], vec![]);
        let base = json!({"host": "localhost", "port": 8080});
        let src = json!({"port": 9000, "debug": true});

        let res = merger.merge_values(base, src, "").unwrap();
        assert_eq!(
