        let base = json!({ "tags": ["rust", "cli"] });
        let src = json!({ "tags": ["cli", "json", "config"] });

        let res = merger.merge_values(base, src, "").unwrap();
        assert_eq!(res["tags"], json!(["rust", "cli", "json", "config"]));
    }
