#[derive(Debug, Clone)]
pub struct ArtifactMetadata {
    pub path: PathBuf,
    pub size_bytes: u64,
    pub sha256_hex: String,
}

impl ArtifactMetadata {
    pub fn inspect(path: &Path) -> Result<Self> {
        if !path.exists() {
            bail!("Le fichier artefact '{}' est introuvable.", path.display());
        }

        let metadata = std::fs::metadata(path)
            .with_context(|| format!("Impossible de lire les métadonnées de '{}'", path.display()))?;

        if !metadata.is_file() {
            bail!("Le chemin '{}' n'est pas un fichier régulier.", path.display());
        }

        let mut file = File::open(path)
            .with_context(|| format!("Erreur d'ouverture de '{}'", path.display()))?;

        let mut hasher = Sha256::new();
        let mut buffer = [0u8; 8192];
        loop {
            let n = file.read(&mut buffer)?;
            if n == 0 {
                break;
            }
            hasher.update(&buffer[..n]);
        }
        let result = hasher.finalize();
        let sha256_hex = hex::encode(result);

        Ok(Self {
            path: path.to_path_buf(),
            size_bytes: metadata.len(),
            sha256_hex,
        })
    }
}

// ============================================================================
// Moteur de Transport et Exécution Distante SSH/SCP (Simulé et extensible)
// ============================================================================

pub struct SimulatedSshClient {
    pub target: ServerTarget,
    pub latency_ms: u64,
    pub dry_run: bool,
}

impl SimulatedSshClient {
    pub fn new(target: ServerTarget, latency_ms: u64, dry_run: bool) -> Self {
        Self {
            target,
            latency_ms,
            dry_run,
        }
    }

    pub async fn connect(&self) -> Result<(), DeployError> {
        sleep(Duration::from_millis(self.latency_ms * 2)).await;

        if self.target.port == 0 {
            return Err(DeployError::NetworkError(
                self.target.name.clone(),
                "Numéro de port invalide (0)".to_string(),
            ));
        }

        // Authentification simulée
        if self.target.user.is_empty() {
            return Err(DeployError::AuthenticationFailed(
                self.target.name.clone(),
                "Utilisateur vide non autorisé".to_string(),
            ));
        }

        Ok(())
    }

    pub async fn scp_upload(
        &self,
        local_file: &ArtifactMetadata,
        remote_dest: &str,
        progress: Option<&ProgressBar>,
    ) -> Result<(), DeployError> {
        let chunk_size: u64 = 64 * 1024; // 64 KiB chunks
        let total_bytes = local_file.size_bytes;
        let mut transferred = 0u64;

        if let Some(pb) = progress {
            pb.set_length(total_bytes);
            pb.set_message(format!("{}: Envoi SCP", self.target.name));
        }

        while transferred < total_bytes {
            let next_chunk = (total_bytes - transferred).min(chunk_size);
            sleep(Duration::from_millis(self.latency_ms)).await;
            transferred += next_chunk;

            if let Some(pb) = progress {
                pb.set_position(transferred);
            }
        }

        // Vérification de parité d'intégrité simulée sur le serveur distant
        let remote_sha = self.compute_remote_checksum(remote_dest, &local_file.sha256_hex).await?;
        if remote_sha != local_file.sha256_hex {
            return Err(DeployError::ChecksumMismatch(
                self.target.name.clone(),
                local_file.sha256_hex.clone(),
                remote_sha,
            ));
        }

        if let Some(pb) = progress {
            pb.finish_with_message(format!("{}: Transfert terminé avec succès", self.target.name));
        }

        Ok(())
    }

    pub async fn compute_remote_checksum(
        &self,
        _remote_path: &str,
        expected: &str,
    ) -> Result<String, DeployError> {
        sleep(Duration::from_millis(self.latency_ms)).await;
        // En mode simulé, renvoie le digest calculé
        Ok(expected.to_string())
    }

    pub async fn execute_remote_command(&self, cmd: &str) -> Result<String, DeployError> {
        sleep(Duration::from_millis(self.latency_ms * 3)).await;

        if cmd.contains("fail_simulation") {
            return Err(DeployError::RemoteCommandFailed(
                cmd.to_string(),
                self.target.name.clone(),
            ));
        }

        Ok(format!("exit_code: 0, out: ok for '{}'", cmd))
    }

    pub async fn rollback(&self, remote_path: &str) -> Result<(), DeployError> {
        let backup_path = format!("{}.bak", remote_path);
        let cmd = format!("mv {} {}", backup_path, remote_path);
        self.execute_remote_command(&cmd).await?;
        Ok(())
    }
}

// ============================================================================
// Orchestrateur de Déploiement
// ============================================================================

pub struct DeploymentOrchestrator {
    config: DeploymentConfig,
    multi_progress: MultiProgress,
}

impl DeploymentOrchestrator {
    pub fn new(config: DeploymentConfig) -> Self {
        Self {
            config,
            multi_progress: MultiProgress::new(),
        }
    }

    pub async fn run_deployment(
        &self,
        artifact: &ArtifactMetadata,
        env_filter: Option<Environment>,
        target_name_filter: Option<String>,
        dry_run: bool,
        concurrency: usize,
        no_rollback: bool,
    ) -> Result<()> {
        let targets: Vec<ServerTarget> = self
            .config
            .targets
            .iter()
            .filter(|t| {
                if let Some(ref env) = env_filter {
                    if &t.environment != env {
                        return false;
                    }
                }
                if let Some(ref name) = target_name_filter {
                    if &t.name != name {
                        return false;
                    }
                }
                true
            })
            .cloned()
            .collect();

        if targets.is_empty() {
            bail!("Aucune cible de déploiement ne correspond aux critères fournis.");
        }

        println!(
            "\n{} Démarrage du déploiement vers {} machine(s)...",
            "[DEPLOY]".bold().cyan(),
            targets.len()
        );
        println!(
            "{} Artefact: {} (Taille: {} octets, SHA256: {})",
            "[INFO]".cyan(),
            artifact.path.display().to_string().yellow(),
            artifact.size_bytes.to_string().green(),
            &artifact.sha256_hex[..12].magenta()
        );

        if dry_run {
            println!(
                "{}",
                "[MODE DRY-RUN] Simulation activée: aucun changement d'état distant ne sera effectué."
                    .yellow()
                    .bold()
            );
        }

        let semaphore = Arc::new(Semaphore::new(concurrency));
        let mut tasks = Vec::new();

        for target in targets {
            let sem = Arc::clone(&semaphore);
            let art = artifact.clone();
            let latency = self.config.simulated_latency_ms;
            let mp = self.multi_progress.clone();

            let task = tokio::spawn(async move {
                let _permit = match sem.acquire().await {
                    Ok(p) => p,
                    Err(e) => {
                        return Err(anyhow::anyhow!("Échec d'acquisition du sémaphore: {}", e));
                    }
                };

                let pb = mp.add(ProgressBar::new(art.size_bytes));
                pb.set_style(
                    ProgressStyle::default_bar()
                        .template(
                            "{prefix:.bold} [{elapsed_precise}] [{bar:40.cyan/blue}] {bytes}/{total_bytes} ({eta}) - {msg}"
                        )
                        .unwrap_or_else(|_| ProgressStyle::default_bar())
                        .progress_chars("#>-"),
                );
                pb.set_prefix(format!("[{}]", target.name));

                let client = SimulatedSshClient::new(target.clone(), latency, dry_run);

                // Étape 1 : Connexion SSH
                pb.set_message("Connexion SSH...");
                client.connect().await?;

                // Étape 2 : Sauvegarde (backup) si demandée
                if target.backup_existing && !dry_run {
                    pb.set_message("Création backup...");
                    let backup_cmd = format!("cp {} {}.bak", target.target_path, target.target_path);
                    let _ = client.execute_remote_command(&backup_cmd).await;
                }

                // Étape 3 : Transfert SCP du binaire
                pb.set_message("Transfert binaire via SCP...");
                if !dry_run {
                    client.scp_upload(&art, &target.target_path, Some(&pb)).await?;
                } else {
                    sleep(Duration::from_millis(150)).await;
                    pb.set_position(art.size_bytes);
                    pb.finish_with_message("Dry-run complété avec succès");
                }

                // Étape 4 : Exécution des scripts post-déploiement
                if !dry_run {
                    for cmd_template in &target.post_deploy_commands {
                        let final_cmd = cmd_template.replace("{{target_path}}", &target.target_path);
                        pb.set_message(format!("Exécution: {}", final_cmd));
                        if let Err(err) = client.execute_remote_command(&final_cmd).await {
                            if !no_rollback && target.backup_existing {
                                warn!("Échec détecté sur {}, exécution du rollback...", target.name);
                                let _ = client.rollback(&target.target_path).await;
                            }
                            return Err(err.into());
                        }
                    }
                }

                pb.finish_with_message(format!("Déploiement réussi sur {}", target.name));
                Ok(target.name)
            });

            tasks.push(task);
        }

        let mut succeeded = Vec::new();
        let mut failed: HashMap<String, String> = HashMap::new();

        for res in futures::future::join_all(tasks).await {
            match res {
                Ok(Ok(target_name)) => succeeded.push(target_name),
                Ok(Err(err)) => {
                    let err_str = err.to_string();
                    failed.insert("Erreur cible".to_string(), err_str);
                }
                Err(join_err) => {
                    failed.insert("Erreur interne d'orchestration".to_string(), join_err.to_string());
                }
            }
        }

        println!("\n{}", "=== Rapport de Déploiement ===".bold());
        println!(
            "Succès : {}/{}",
            succeeded.len().to_string().green().bold(),
            (succeeded.len() + failed.len())
        );

        for target in &succeeded {
            println!("  {} {}", "✓".green(), target.bold());
        }

        if !failed.is_empty() {
            println!("\nÉchecs :");
            for (key, err) in &failed {
                println!("  {} {}: {}", "✗".red(), key.bold(), err);
            }
            bail!("Le déploiement s'est achevé avec des erreurs sur certaines cibles.");
        }

        println!(
            "\n{}",
            "Tous les déploiements ont été synchronisés avec succès !"
                .green()
                .bold()
        );
        Ok(())
    }
}

// ============================================================================
// Chargement de la Configuration
// ============================================================================

fn load_configuration(path_opt: Option<&Path>) -> Result<DeploymentConfig> {
    if let Some(path) = path_opt {
        if !path.exists() {
            bail!(
                "Le fichier de configuration spécifié '{}' n'existe pas.",
                path.display()
            );
        }
        let content = std::fs::read_to_string(path)
            .with_context(|| format!("Lecture impossible du fichier '{}'", path.display()))?;

        if path.extension().and_then(|ext| ext.to_str()) == Some("json") {
            let cfg: DeploymentConfig = serde_json::from_str(&content)
                .with_context(|| "Format JSON invalide dans le fichier de configuration")?;
            return Ok(cfg);
        }

        let cfg: DeploymentConfig = toml::from_str(&content)
            .with_context(|| "Format TOML invalide dans le fichier de configuration")?;
        return Ok(cfg);
    }

    // Recherche automatique d'un fichier standard
    let default_files = ["deploy.toml", "deploy.json"];
    for default_path in &default_files {
        let p = Path::new(default_path);
        if p.exists() {
            return load_configuration(Some(p));
        }
    }

    // Utilise la configuration par défaut avec des cibles de démonstration
    info!("Aucun fichier 'deploy.toml' trouvé. Utilisation de la configuration par défaut.");
    Ok(DeploymentConfig::default())
}

// ============================================================================
// Point d'entrée principal
// ============================================================================

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();

    // Initialisation du logging
    let filter = if cli.verbose { "debug" } else { "info" };
    let _ = tracing_subscriber::fmt()
        .with_env_filter(filter)
        .without_time()
        .try_init();

    match cli.command {
        Commands::Deploy(args) => {
            let config = load_configuration(cli.config.as_deref())?;
            let artifact_meta = ArtifactMetadata::inspect(&args.artifact)?;

            let orchestrator = DeploymentOrchestrator::new(config);
            orchestrator
                .run_deployment(
                    &artifact_meta,
                    args.env,
                    args.target,
                    args.dry_run,
                    args.concurrency,
                    args.no_rollback,
                )
                .await?;
        }

        Commands::Check(args) => {
            println!("{}", "=== Contrôle d'Intégrité de l'Artefact ===".bold().cyan());
            let meta = ArtifactMetadata::inspect(&args.artifact)?;
            println!("Chemin     : {}", meta.path.display().to_string().yellow());
            println!("Taille     : {} octets", meta.size_bytes.to_string().green());
            println!("SHA-256    : {}", meta.sha256_hex.bold().cyan());
            println!("{}", "Empreinte cryptographique valide.".green());
        }

        Commands::InitConfig(args) => {
            let default_cfg = DeploymentConfig::default();
            let toml_string = toml::to_string_pretty(&default_cfg)
                .context("Erreur lors de la sérialisation en TOML")?;

            if args.output.exists() {
                bail!(
                    "Le fichier '{}' existe déjà. Veuillez spécifier un autre nom ou le supprimer.",
                    args.output.display()
                );
            }

            std::fs::write(&args.output, toml_string)
                .with_context(|| format!("Écriture impossible dans '{}'", args.output.display()))?;

            println!(
                "{} Modèle de configuration généré dans '{}'",
                "✓".green(),
                args.output.display().to_string().bold()
            );
        }

        Commands::ListTargets(args) => {
            let config = load_configuration(cli.config.as_deref())?;
            println!("{}", "=== Cibles de Déploiement ===".bold().cyan());

            let mut count = 0;
            for t in &config.targets {
                if let Some(ref env) = args.env {
                    if &t.environment != env {
                        continue;
                    }
                }
                count += 1;
                println!(
                    "• {} [{:?}] -> {}@{}:{} (Dest: {})",
                    t.name.bold(),
                    t.environment,
                    t.user.yellow(),
                    t.host.cyan(),
                    t.port,
                    t.target_path.magenta()
                );
            }

            if count == 0 {
                println!("Aucune cible trouvée correspondant au filtre.");
            }
        }
    }

    Ok(())
}

