```rust
// src/main.rs
use std::fs::{self, File};
use std::io::{BufReader, BufWriter, Read, Write};
use std::path::{Path, PathBuf};

use anyhow::{bail, Context, Result};
use clap::{Parser, Subcommand};
use indicatif::{ProgressBar, ProgressStyle};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

const BUFFER_CAPACITY: usize = 256 * 1024; // 256 KiB I/O buffer

/// Manifeste stocké au format JSON pour enregistrer les métadonnées et hashes des blocs.
#[derive(Debug, Serialize, Deserialize)]
pub struct Manifest {
    pub original_name: String,
    pub original_size: u64,
    pub original_sha256: String,
    pub chunk_size: u64,
    pub chunks: Vec<ChunkInfo>,
}

/// Informations sur chaque fragment généré.
#[derive(Debug, Serialize, Deserialize)]
pub struct ChunkInfo {
    pub index: usize,
    pub filename: String,
    pub size: u64,
    pub sha256: String,
}

#[derive(Parser, Debug)]
#[command(name = "chunker", author, version, about = "Outil de découpage et réassemblage avec contrôle d'intégrité par bloc et barre de progression.")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Découpe un fichier volumineux en plusieurs blocs avec contrôle SHA-256
    Split {
        /// Chemin du fichier source à découper
        #[arg(short, long)]
        input: PathBuf,

        /// Taille de chaque bloc (ex: 64M, 500K, 1G ou en octets)
        #[arg(short, long, default_value = "64M")]
        chunk_size: String,

        /// Dossier de destination pour les fragments et le manifeste (par défaut : répertoire courant)
        #[arg(short, long)]
        output_dir: Option<PathBuf>,
    },

    /// Réassemble les blocs à partir du fichier manifeste JSON
    Join {
        /// Chemin du fichier manifeste JSON
        #[arg(short, long)]
        manifest: PathBuf,

        /// Fichier de sortie (par défaut : nom d'origine dans le dossier spécifié ou courant)
        #[arg(short, long)]
        output: Option<PathBuf>,

        /// Écraser le fichier de sortie s'il existe déjà
        #[arg(short, long, default_value_t = false)]
        force: bool,
    },

    /// Vérifie l'intégrité de tous les fragments déclarés dans un manifeste
    Check {
        /// Chemin du fichier manifeste JSON
        #[arg(short, long)]
        manifest: PathBuf,
    },
}

/// Analyse une chaîne de caractères représentant une taille (ex: "64M", "500K", "1G", "1048576")
fn parse_size(size_str: &str) -> Result<u64> {
    let s = size_str.trim();
    if s.is_empty() {
        bail!("La taille de bloc fournie est vide");
    }

    let (num_part, multiplier) = match s.chars().last() {
        Some('k' | 'K') => (&s[..s.len() - 1], 1024u64),
        Some('m' | 'M') => (&s[..s.len() - 1], 1024 * 1024u64),
        Some('g' | 'G') => (&s[..s.len() - 1], 1024 * 1024 * 1024u64),
        Some('b' | 'B') => (&s[..s.len() - 1], 1u64),
        _ => (s, 1u64),
    };

    let value: u64 = num_part
        .trim()
        .parse()
        .with_context(|| format!("Impossible de convertir '{size_str}' en taille d'octets valide"))?;

    let total = value
        .checked_mul(multiplier)
        .context("Dépassement de capacité arithmétique pour la taille de bloc")?;

    if total == 0 {
        bail!("La taille d'un bloc doit être supérieure à zéro");
    }

    Ok(total)
}

fn create_progress_bar(total_bytes: u64, message: &'static str) -> ProgressBar {
    let pb = ProgressBar::new(total_bytes);
    pb.set_style(
        ProgressStyle::default_bar()
            .template("{msg}\n[{elapsed_precise}] [{bar:40.cyan/blue}] {bytes}/{total_bytes} ({bytes_per_sec}, ETA {eta})")
            .unwrap_or_else(|_| ProgressStyle::default_bar())
            .progress_chars("#>-"),
    );
    pb.set_message(message);
    pb
}

fn execute_split(input: &Path, chunk_size_str: &str, output_dir: Option<&Path>) -> Result<()> {
    if !input.is_file() {
        bail!("Le fichier source '{:?}' n'existe pas ou n'est pas un fichier régulier", input);
    }

    let chunk_size = parse_size(chunk_size_str)?;
    let target_dir = match output_dir {
        Some(dir) => {
            fs::create_dir_all(dir).with_context(|| format!("Échec de création du dossier {:?}", dir))?;
            dir.to_path_buf()
        }
        None => input.parent().unwrap_or_else(|| Path::new(".")).to_path_buf(),
    };

    let metadata = fs::metadata(input).with_context(|| format!("Impossible de lire les métadonnées de {:?}", input))?;
    let total_size = metadata.len();

    let orig_file_name = input
        .file_name()
        .and_then(|n| n.to_str())
        .context("Nom de fichier source non valide en UTF-8")?
        .to_string();

    println!("-> Découpage de '{}' ({} octets) en blocs de {} octets", orig_file_name, total_size, chunk_size);

    let file = File::open(input).with_context(|| format!("Impossible d'ouvrir le fichier {:?}", input))?;
    let mut reader = BufReader::with_capacity(BUFFER_CAPACITY, file);

    let pb = create_progress_bar(total_size, "Partitionnement en cours");

    let mut global_hasher = Sha256::new();
    let mut chunks = Vec::new();
    let mut buffer = vec![0u8; BUFFER_CAPACITY];
    let mut chunk_index = 1usize;
    let mut total_bytes_read = 0u64;

    while total_bytes_read < total_size {
        let chunk_file_name = format!("{}.part{:04}", orig_file_name, chunk_index);
        let chunk_path = target_dir.join(&chunk_file_name);

        let chunk_file = File::create(&chunk_path)
            .with_context(|| format!("Impossible de créer le fragment {:?}", chunk_path))?;
        let mut writer = BufWriter::with_capacity(BUFFER_CAPACITY, chunk_file);

        let mut chunk_hasher = Sha256::new();
        let mut current_chunk_written = 0u64;

        while current_chunk_written < chunk_size && total_bytes_read < total_size {
            let to_read = (chunk_size - current_chunk_written)
                .min(buffer.len() as u64)
                .min(total_size - total_bytes_read) as usize;

            let bytes_read = reader
                .read(&mut buffer[..to_read])
                .with_context(|| format!("Erreur de lecture depuis {:?}", input))?;

            if bytes_read == 0 {
                break;
            }

            let slice = &buffer[..bytes_read];
            writer
                .write_all(slice)
                .with_context(|| format!("Erreur d'écriture dans {:?}", chunk_path))?;

            chunk_hasher.update(slice);
            global_hasher.update(slice);

            current_chunk_written += bytes_read as u64;
            total_bytes_read += bytes_read as u64;
            pb.inc(bytes_read as u64);
        }

        writer.flush().with_context(|| format!("Erreur lors du flush de {:?}", chunk_path))?;

        let chunk_hash_hex = hex::encode(chunk_hasher.finalize());
        chunks.push(ChunkInfo {
            index: chunk_index,
            filename: chunk_file_name,
            size: current_chunk_written,
            sha256: chunk_hash_hex,
        });

        chunk_index += 1;
    }

    pb.finish_with_message("Partitionnement terminé avec succès !");

    let global_hash_hex = hex::encode(global_hasher.finalize());
    let manifest = Manifest {
        original_name: orig_file_name.clone(),
        original_size: total_size,
        original_sha256: global_hash_hex.clone(),
        chunk_size,
        chunks,
    };

    let manifest_path = target_dir.join(format!("{}.manifest.json", orig_file_name));
    let manifest_file = File::create(&manifest_path)
        .with_context(|| format!("Impossible de créer le fichier manifeste {:?}", manifest_path))?;
    serde_json::to_writer_pretty(manifest_file, &manifest)
        .with_context(|| "Impossible d'écrire le contenu du manifeste JSON")?;

    println!("\nRésultats :");
    println!("  - Manifeste : {:?}", manifest_path);
    println!("  - Fragments créés : {}", manifest.chunks.len());
    println!("  - SHA-256 global  : {}", global_hash_hex);

    Ok(())
}

fn execute_check(manifest_path: &Path) -> Result<Manifest> {
    if !manifest_path.is_file() {
        bail!("Fichier manifeste introuvable : {:?}", manifest_path);
    }

    let base_dir = manifest_path.parent().unwrap_or_else(|| Path::new("."));
    let file = File::open(manifest_path).with_context(|| format!("Impossible d'ouvrir le manifeste {:?}", manifest_path))?;
    let manifest: Manifest = serde_json::from_reader(file)
        .with_context(|| format!("Format de manifeste JSON invalide pour {:?}", manifest_path))?;

    println!("-> Vérification de l'intégrité des blocs pour '{}'...", manifest.original_name);
    let pb = create_progress_bar(manifest.original_size, "Contrôle d'intégrité");

    let mut buffer = vec![0u8; BUFFER_CAPACITY];
    let mut verified_bytes = 0u64;

    for chunk in &manifest.chunks {
        let chunk_path = base_dir.join(&chunk.filename);
        if !chunk_path.is_file() {
            bail!("Fragment manquant : {:?}", chunk_path);
        }

        let chunk_file = File::open(&chunk_path).with_context(|| format!("Impossible de lire le fragment {:?}", chunk_path))?;
        let meta = chunk_file.metadata().with_context(|| format!("Impossible de lire les métadonnées de {:?}", chunk_path))?;

        if meta.len() != chunk.size {
            bail!(
                "Incohérence de taille pour le fragment {:?} : attendu {} octets, trouvé {} octets",
                chunk.filename,
                chunk.size,
                meta.len()
            );
        }

        let mut reader = BufReader::with_capacity(BUFFER_CAPACITY, chunk_file);
        let mut hasher = Sha256::new();

        loop {
            let bytes_read = reader
                .read(&mut buffer)
                .with_context(|| format!("Erreur de lecture lors de la vérification de {:?}", chunk_path))?;
            if bytes_read == 0 {
                break;
            }
            hasher.update(&buffer[..bytes_read]);
            pb.inc(bytes_read as u64);
            verified_bytes += bytes_read as u64;
        }

        let computed_hash = hex::encode(hasher.finalize());
        if computed_hash != chunk.sha256 {
            bail!(
                "Intégrité CORROMPUE pour le bloc {:?} !\n  Attendu : {}\n  Trouvé  : {}",
                chunk.filename,
                chunk.sha256,
                computed_hash
            );
        }
    }

    pb.finish_with_message("Vérification terminée : tous les blocs sont intègres !");
    println!("Intégrité validée avec succès pour l'ensemble des {} fragments ({} octets).", manifest.chunks.len(), verified_bytes);

    Ok(manifest)
}

fn execute_join(manifest_path: &Path, output: Option<&Path>, force: bool) -> Result<()> {
    let manifest = execute_check(manifest_path).context("Échec de la pré-vérification des fragments")?;
    let base_dir = manifest_path.parent().unwrap_or_else(|| Path::new("."));

    let output_path = match output {
        Some(p) => p.to_path_buf(),
        None => base_dir.join(&manifest.original_name),
    };

    if output_path.exists() && !force {
        bail!(
            "Le fichier de destination {:?} existe déjà. Utilisez l'option --force pour l'écraser.",
            output_path
        );
    }

    println!("\n-> Réassemblage vers {:?}", output_path);
    let out_file = File::create(&output_path)
        .with_context(|| format!("Impossible de créer le fichier réassemblé {:?}", output_path))?;
    let mut writer = BufWriter::with_capacity(BUFFER_CAPACITY, out_file);

    let pb = create_progress_bar(manifest.original_size, "Réassemblage en cours");

    let mut global_hasher = Sha256::new();
    let mut buffer = vec![0u8; BUFFER_CAPACITY];

    for chunk in &manifest.chunks {
        let chunk_path = base_dir.join(&chunk.filename);
        let chunk_file = File::open(&chunk_path)
            .with_context(|| format!("Impossible d'ouvrir le fragment {:?}", chunk_path))?;
        let mut reader = BufReader::with_capacity(BUFFER_CAPACITY, chunk_file);

        loop {
            let bytes_read = reader
                .read(&mut buffer)
                .with_context(|| format!("Erreur d'I/O lors de la lecture de {:?}", chunk_path))?;
            if bytes_read == 0 {
                break;
            }
            let slice = &buffer[..bytes_read];
            writer
                .write_all(slice)
                .with_context(|| format!("Erreur d'écriture dans {:?}", output_path))?;
            global_hasher.update(slice);
            pb.inc(bytes_read as u64);
        }
    }

    writer.flush().with_context(|| format!("Impossible de finaliser l'écriture de {:?}", output_path))?;
    pb.finish_with_message("Réassemblage terminé avec succès !");

    let final_hash = hex::encode(global_hasher.finalize());
    if final_hash != manifest.original_sha256 {
        bail!(
            "Corruption lors de l'assemblage global !\n  Attendu : {}\n  Généré  : {}",
            manifest.original_sha256,
            final_hash
        );
    }

    println!("Opération terminée : fichier reconstitué fidèle au fichier d'origine.");
    println!("  - Chemin : {:?}", output_path);
    println!("  - SHA-256 : {}", final_hash);

    Ok(())
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match &cli.command {
        Commands::Split {
            input,
            chunk_size,
            output_dir,
        } => execute_split(input, chunk_size, output_dir.as_deref())?,
        Commands::Join {
            manifest,
            output,
            force,
        } => execute_join(manifest, output.as_deref(), *force)?,
        Commands::Check { manifest } => {
            execute_check(manifest)?;
        }
    }

    Ok(())
}

