```rust
// src/main.rs
use anyhow::{bail, Context, Result};
use clap::Parser;
use human_repr::HumanThroughput;
use indicatif::{ProgressBar, ProgressStyle};
use rand::rngs::SmallRng;
use rand::{Rng, RngCore, SeedableRng};
use std::fs::{self, OpenOptions};
use std::io::{Seek, SeekFrom, Write};
use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};

/// CLI de diagnostic des performances d'écriture disque mesurant les débits séquentiels et aléatoires par blocs.
#[derive(Parser, Debug)]
#[command(
    name = "disk-perf-cli",
    version,
    about = "Mesure les performances d'écriture séquentielle et aléatoire par blocs sur un volume de stockage."
)]
struct Args {
    /// Répertoire cible où créer le fichier de test.
    #[arg(short, long, default_value = ".")]
    target_dir: PathBuf,

    /// Taille totale des données à écrire pour le test en mébioctets (MiB).
    #[arg(short = 's', long, default_value_t = 128)]
    file_size_mib: usize,

    /// Taille d'un bloc d'écriture en kibioctets (KiB).
    #[arg(short = 'b', long, default_value_t = 64)]
    block_size_kib: usize,

    /// Forcer la synchronisation disque (fsync) après chaque bloc écrit (mesure la latence unitaire).
    #[arg(long, default_value_t = false)]
    fsync_each_block: bool,

    /// Conserver le fichier de benchmark après l'exécution.
    #[arg(long, default_value_t = false)]
    keep_file: bool,
}

#[derive(Debug, Clone)]
struct BenchmarkResult {
    name: &'static str,
    bytes_written: u64,
    total_duration: Duration,
    sync_duration: Duration,
    iops: f64,
    throughput_bytes_per_sec: f64,
    avg_block_latency: Duration,
    min_block_latency: Duration,
    max_block_latency: Duration,
}

fn create_progress_bar(total_blocks: u64, label: &'static str) -> ProgressBar {
    let pb = ProgressBar::new(total_blocks);
    pb.set_style(
        ProgressStyle::default_bar()
            .template("{prefix:.bold} [{elapsed_precise}] [{bar:40.cyan/blue}] {pos}/{len} blocs ({percent}%)")
            .unwrap_or_else(|_| ProgressStyle::default_bar())
            .progress_chars("#>-"),
    );
    pb.set_prefix(label);
    pb
}

fn run_sequential_benchmark(
    file_path: &Path,
    total_bytes: u64,
    block_size: usize,
    fsync_each: bool,
    buffer: &[u8],
) -> Result<BenchmarkResult> {
    let mut file = OpenOptions::new()
        .create(true)
        .write(true)
        .truncate(true)
        .open(file_path)
        .with_context(|| format!("Impossible d'ouvrir le fichier {}", file_path.display()))?;

    let total_blocks = total_bytes / block_size as u64;
    let pb = create_progress_bar(total_blocks, "Écriture séquentielle");

    let mut min_latency = Duration::MAX;
    let mut max_latency = Duration::ZERO;
    let mut sum_latency = Duration::ZERO;

    let start_all = Instant::now();

    for _ in 0..total_blocks {
        let block_start = Instant::now();
        file.write_all(buffer)
            .context("Erreur lors de l'écriture séquentielle du bloc")?;

        if fsync_each {
            file.sync_data()
                .context("Erreur lors de sync_data par bloc")?;
        }

        let elapsed = block_start.elapsed();
        if elapsed < min_latency {
            min_latency = elapsed;
        }
        if elapsed > max_latency {
            max_latency = elapsed;
        }
        sum_latency += elapsed;

        pb.inc(1);
    }

    let sync_start = Instant::now();
    file.sync_all()
        .context("Erreur lors de la synchronisation finale (fsync)")?;
    let sync_duration = sync_start.elapsed();
    let total_duration = start_all.elapsed();

    pb.finish_with_message("Terminé");

    let seconds = total_duration.as_secs_f64();
    let throughput = if seconds > 0.0 {
        total_bytes as f64 / seconds
    } else {
        0.0
    };
    let iops = if seconds > 0.0 {
        total_blocks as f64 / seconds
    } else {
        0.0
    };
    let avg_latency = if total_blocks > 0 {
        sum_latency / total_blocks as u32
    } else {
        Duration::ZERO
    };

    Ok(BenchmarkResult {
        name: "Séquentiel",
        bytes_written: total_bytes,
        total_duration,
        sync_duration,
        iops,
        throughput_bytes_per_sec: throughput,
        avg_block_latency: avg_latency,
        min_block_latency: if min_latency == Duration::MAX {
            Duration::ZERO
        } else {
            min_latency
        },
        max_block_latency: max_latency,
    })
}

fn run_random_benchmark(
    file_path: &Path,
    total_bytes: u64,
    block_size: usize,
    fsync_each: bool,
    buffer: &[u8],
) -> Result<BenchmarkResult> {
    let mut file = OpenOptions::new()
        .write(true)
        .open(file_path)
        .with_context(|| format!("Impossible d'ouvrir le fichier {}", file_path.display()))?;

    let total_blocks = total_bytes / block_size as u64;
    let pb = create_progress_bar(total_blocks, "Écriture aléatoire  ");

    let mut min_latency = Duration::MAX;
