```rust
// src/main.rs
use std::fs;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use anyhow::{Context, Result};
use clap::{Parser, ValueEnum};
use colored::Colorize;
use convert_case::{Case, Casing};
use serde::Serialize;
use syn::visit::Visit;
use walkdir::WalkDir;

/// Format de sortie des résultats d'audit.
#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
enum OutputFormat {
    Text,
    Json,
}

/// Niveaux de sévérité d'une constatation d'audit.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
enum Severity {
    Warning,
    #[allow(dead_code)]
    Error,
}

/// Type de violation détectée.
#[derive(Debug, Clone, Serialize)]
enum ViolationKind {
    NamingConvention {
        expected_case: String,
        actual_name: String,
    },
    MissingDocumentation,
}

/// Représente un constat d'audit unitaire sur un élément de code.
#[derive(Debug, Clone, Serialize)]
struct Finding {
    file: String,
    line: usize,
    column: usize,
    element_kind: String,
    identifier: String,
    severity: Severity,
    violation: ViolationKind,
    message: String,
}

/// Options en ligne de commande pour l'outil d'audit.
#[derive(Parser, Debug)]
#[command(
    name = "rust-audit-lint",
    author,
    version,
    about = "Outil d'audit de conformité de code Rust (nommage et documentation)"
)]
struct Cli {
    /// Chemin du fichier ou répertoire à auditer
    #[arg(default_value = ".")]
    path: PathBuf,

    /// Format de restitution des résultats
    #[arg(short, long, value_enum, default_value_t = OutputFormat::Text)]
    format: OutputFormat,

    /// Retourne un code d'erreur non nul si des violations sont détectées
    #[arg(long, default_value_t = false)]
    deny_warnings: bool,

    /// Vérifie la documentation uniquement sur les éléments publics
    #[arg(long, default_value_t = true)]
    public_only_docs: bool,
}

/// Visiteur AST Syn pour inspecter la syntaxe Rust.
struct CodeAuditor<'a> {
    file_path: &'a Path,
    public_only_docs: bool,
    findings: Vec<Finding>,
}

impl<'a> CodeAuditor<'a> {
    fn new(file_path: &'a Path, public_only_docs: bool) -> Self {
        Self {
            file_path,
            public_only_docs,
            findings: Vec::new(),
        }
    }

    fn has_doc_comments(attrs: &[syn::Attribute]) -> bool {
        attrs.iter().any(|attr| {
            if attr.path().is_ident("doc") {
                if let syn::Meta::NameValue(meta_nv) = &attr.meta {
                    if let syn::Expr::Lit(expr_lit) = &meta_nv.value {
                        if let syn::Lit::Str(doc_str) = &expr_lit.lit {
                            return !doc_str.value().trim().is_empty();
                        }
                    }
                }
            }
            false
        })
    }

    fn check_naming(
        &mut self,
        ident: &syn::Ident,
        element_kind: &str,
        expected_case: Case,
        case_name: &str,
    ) {
        let name = ident.to_string();
        // Ignore les variables et fonctions commençant par '_' (intentionnellement non utilisées ou internes)
        if name.starts_with('_') && name.trim_start_matches('_').is_empty() {
            return;
        }

        let clean_name = name.trim_start_matches('_');
        let converted = clean_name.to_case(expected_case);

        if clean_name != converted {
            let span = ident.span();
            let start = span.start();
            self.findings.push(Finding {
                file: self.file_path.display().to_string(),
                line: start.line,
                column: start.column + 1,
                element_kind: element_kind.to_string(),
                identifier: name.clone(),
                severity: Severity::Warning,
                violation: ViolationKind::NamingConvention {
                    expected_case: case_name.to_string(),
                    actual_name: name.clone(),
                },
                message: format!(
                    "{} `{}` ne respecte pas la convention `{}` (attendu : `{}`)",
                    element_kind, clean_name, case_name, converted
                ),
            });
        }
    }

    fn check_docs(
        &mut self,
        ident: &syn::Ident,
        vis: &syn::Visibility,
        attrs: &[syn::Attribute],
        element_kind: &str,
    ) {
        let is_public = !matches!(vis, syn::Visibility::Inherited);
        if self.public_only_docs && !is_public {
            return;
        }

        if !Self::has_doc_comments(attrs) {
            let span = ident.span();
            let start = span.start();
            self.findings.push(Finding {
                file: self.file_path.display().to_string(),
                line: start.line,
                column: start.column + 1,
                element_kind: element_kind.to_string(),
                identifier: ident.to_string(),
                severity: Severity::Warning,
                violation: ViolationKind::MissingDocumentation,
                message: format!(
                    "{} public `{}` est dépourvu de commentaire de documentation",
                    element_kind, ident
                ),
            });
        }
    }
}

impl<'ast, 'a> Visit<'ast> for CodeAuditor<'a> {
    fn visit_item_fn(&mut self, node: &'ast syn::ItemFn) {
        self.check_naming(&node.sig.ident, "Fonction", Case::Snake, "snake_case");
        self.check_docs(&node.sig.ident, &node.vis, &node.attrs, "Fonction");
        syn::visit::visit_item_fn(self, node);
    }

    fn visit_item_struct(&mut self, node: &'ast syn::ItemStruct) {
