/// Visiteur AST Syn pour inspecter la syntaxe Rust.
struct CodeAuditor<'a> {
    file_path: &'a Path,
    public_only_docs: bool,
    findings: Vec<Finding>,
}

impl<'a> CodeAuditor<'a> {
    fn new(file_path: &'a Path, public_only_docs: bool) -> Self {
        Self {
            file_path,
            public_only_docs,
            findings: Vec::new(),
        }
    }

    fn has_doc_comments(attrs: &[syn::Attribute]) -> bool {
        attrs.iter().any(|attr| {
            if attr.path().is_ident("doc") {
                if let syn::Meta::NameValue(meta_nv) = &attr.meta {
                    if let syn::Expr::Lit(expr_lit) = &meta_nv.value {
                        if let syn::Lit::Str(doc_str) = &expr_lit.lit {
                            return !doc_str.value().trim().is_empty();
                        }
                    }
                }
            }
            false
        })
    }

    fn check_naming(
        &mut self,
        ident: &syn::Ident,
        element_kind: &str,
        expected_case: Case,
        case_name: &str,
    ) {
        let name = ident.to_string();
        // Ignore les variables et fonctions commençant par '_' (intentionnellement non utilisées ou internes)
        if name.starts_with('_') && name.trim_start_matches('_').is_empty() {
            return;
        }

        let clean_name = name.trim_start_matches('_');
        let converted = clean_name.to_case(expected_case);

        if clean_name != converted {
            let span = ident.span();
            let start = span.start();
            self.findings.push(Finding {
                file: self.file_path.display().to_string(),
                line: start.line,
                column: start.column + 1,
                element_kind: element_kind.to_string(),
                identifier: name.clone(),
                severity: Severity::Warning,
                violation: ViolationKind::NamingConvention {
                    expected_case: case_name.to_string(),
                    actual_name: name.clone(),
                },
                message: format!(
                    "{} `{}` ne respecte pas la convention `{}` (attendu : `{}`)",
                    element_kind, clean_name, case_name, converted
                ),
            });
        }
    }

    fn check_docs(
        &mut self,
        ident: &syn::Ident,
        vis: &syn::Visibility,
        attrs: &[syn::Attribute],
        element_kind: &str,
    ) {
        let is_public = !matches!(vis, syn::Visibility::Inherited);
        if self.public_only_docs && !is_public {
            return;
        }

        if !Self::has_doc_comments(attrs) {
            let span = ident.span();
            let start = span.start();
            self.findings.push(Finding {
                file: self.file_path.display().to_string(),
                line: start.line,
                column: start.column + 1,
                element_kind: element_kind.to_string(),
                identifier: ident.to_string(),
                severity: Severity::Warning,
                violation: ViolationKind::MissingDocumentation,
                message: format!(
                    "{} public `{}` est dépourvu de commentaire de documentation",
                    element_kind, ident
                ),
            });
        }
    }
}

