/// Nom du fichier de configuration global par défaut
const DEFAULT_CONFIG_FILE: &str = "config.toml";
/// Nom du fichier de contexte local optionnel
const LOCAL_CONTEXT_FILE: &str = ".envswitch";

#[derive(Error, Debug)]
pub enum EnvSwitchError {
    #[error("Le profil '{0}' n'existe pas.")]
    ProfileNotFound(String),

    #[error("Le profil '{0}' existe déjà.")]
    ProfileAlreadyExists(String),

    #[error("Format variable invalide '{0}'. Format attendu: CLE=VALEUR")]
    InvalidVariableFormat(String),

    #[error("Clé de variable d'environnement non valide: '{0}'")]
    InvalidKeyName(String),

    #[error("Cycle d'héritage détecté impliquant le profil '{0}'.")]
    InheritanceCycle(String),

    #[error("Aucun profil actif ou détecté pour le contexte actuel.")]
    NoActiveProfile,

