    EmptyCommand,

    #[error("Erreur d'entrée/sortie: {0}")]
    Io(#[from] io::Error),

    #[error("Erreur de sérialisation / désérialisation TOML: {0}")]
    Toml(#[from] toml::ser::Error),

    #[error("Erreur de parsing TOML: {0}")]
    TomlDe(#[from] toml::de::Error),

    #[error("Règle introuvable pour le chemin '{0}'.")]
    RuleNotFound(String),
}

/// Type de shell supporté pour la génération de commandes d'exportation
#[derive(Copy, Clone, PartialEq, Eq, PartialOrd, Ord, ValueEnum, Debug, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ShellType {
    Bash,
    Zsh,
    Fish,
    Powershell,
}

impl fmt::Display for ShellType {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ShellType::Bash => write!(f, "bash"),
            ShellType::Zsh => write!(f, "zsh"),
            ShellType::Fish => write!(f, "fish"),
            ShellType::Powershell => write!(f, "powershell"),
        }
    }
}

impl FromStr for ShellType {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s.to_lowercase().as_str() {
            "bash" => Ok(ShellType::Bash),
            "zsh" => Ok(ShellType::Zsh),
            "fish" => Ok(ShellType::Fish),
            "powershell" | "pwsh" => Ok(ShellType::Powershell),
            _ => Err(format!("Shell non supporté: {s}. Choix: bash, zsh, fish, powershell")),
        }
    }
}

/// Profil d'environnement regroupant des paires clé/valeur
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct Profile {
    #[serde(default)]
    pub description: Option<String>,
    #[serde(default)]
    pub inherit: Option<String>,
    #[serde(default)]
    pub vars: BTreeMap<String, String>,
}

impl Profile {
    pub fn new(description: Option<String>, inherit: Option<String>) -> Self {
        Self {
            description,
            inherit,
            vars: BTreeMap::new(),
        }
    }
}

/// Règle liant un chemin de dossier à un profil spécifique
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct ContextRule {
    pub path: PathBuf,
    pub profile: String,
}

/// Configuration globale de l'application
#[derive(Debug, Clone, Serialize, Deserialize, Default, PartialEq, Eq)]
pub struct AppConfig {
    pub default_profile: Option<String>,
    #[serde(default)]
    pub profiles: BTreeMap<String, Profile>,
    #[serde(default)]
    pub rules: Vec<ContextRule>,
}

impl AppConfig {
    /// Résout la liste complète des variables d'un profil en appliquant l'héritage
    pub fn resolve_profile_vars(&self, profile_name: &str) -> Result<BTreeMap<String, String>, EnvSwitchError> {
        let mut visited = HashSet::new();
        let mut hierarchy = Vec::new();
        let mut current_name = profile_name.to_string();

        while !current_name.is_empty() {
            if !visited.insert(current_name.clone()) {
                return Err(EnvSwitchError::InheritanceCycle(current_name));
            }

            let prof = self
                .profiles
                .get(&current_name)
                .ok_or_else(|| EnvSwitchError::ProfileNotFound(current_name.clone()))?;

            hierarchy.push(prof);

            match &prof.inherit {
                Some(parent) if !parent.trim().is_empty() => {
                    current_name = parent.clone();
                }
                _ => break,
            }
        }

        // Appliquer du parent le plus éloigné vers l'enfant pour respecter la surcharge
        let mut resolved = BTreeMap::new();
        for prof in hierarchy.into_iter().rev() {
            for (k, v) in &prof.vars {
                resolved.insert(k.clone(), v.clone());
            }
        }

        Ok(resolved)
    }

    /// Détermine le profil actif selon le contexte actuel (règles de dossier, fichier local, ou profil par défaut)
    pub fn detect_profile(&self, current_dir: &Path) -> Option<String> {
        // 1. Recherche d'un fichier .envswitch local dans le dossier courant ou ses parents
        let mut probe = Some(current_dir);
        while let Some(dir) = probe {
            let candidate = dir.join(LOCAL_CONTEXT_FILE);
            if candidate.is_file() {
                if let Ok(content) = fs::read_to_string(&candidate) {
                    let name = content.trim();
                    if !name.is_empty() && self.profiles.contains_key(name) {
                        return Some(name.to_string());
                    }
                }
            }
            probe = dir.parent();
        }

        // 2. Recherche par correspondance de préfixe dans les règles configurées (le chemin le plus spécifique gagne)
        let canonical_dir = dunce::canonicalize(current_dir).unwrap_or_else(|_| current_dir.to_path_buf());
        let mut best_match: Option<(&ContextRule, usize)> = None;

        for rule in &self.rules {
            let rule_path = dunce::canonicalize(&rule.path).unwrap_or_else(|_| rule.path.clone());
            if canonical_dir.starts_with(&rule_path) {
                let depth = rule_path.components().count();
                match best_match {
                    Some((_, best_depth)) if depth > best_depth => {
                        best_match = Some((rule, depth));
                    }
                    None => {
                        best_match = Some((rule, depth));
                    }
                    _ => {}
                }
            }
        }

        if let Some((matched_rule, _)) = best_match {
            if self.profiles.contains_key(&matched_rule.profile) {
                return Some(matched_rule.profile.clone());
            }
        }

        // 3. Fallback sur le profil par défaut configuré
        self.default_profile.clone()
    }
}

/// Dépôt de configuration responsable du chargement et de la persistance
pub struct ConfigManager {
    custom_path: Option<PathBuf>,
}

impl ConfigManager {
    pub fn new(custom_path: Option<PathBuf>) -> Self {
        Self { custom_path }
    }

    /// Renvoie le chemin effectif du fichier de configuration
    pub fn config_path(&self) -> Result<PathBuf, EnvSwitchError> {
        if let Some(ref path) = self.custom_path {
            return Ok(path.clone());
        }

        let base_dir = dirs::config_dir()
            .ok_or_else(|| io::Error::new(io::ErrorKind::NotFound, "Impossible de déterminer le répertoire de configuration utilisateur"))?;
        let app_dir = base_dir.join("envswitch");
        Ok(app_dir.join(DEFAULT_CONFIG_FILE))
    }

    /// Charge la configuration depuis le disque ou initialise une configuration vierge si absente
    pub fn load(&self) -> Result<AppConfig, EnvSwitchError> {
        let path = self.config_path()?;
        if !path.exists() {
            return Ok(AppConfig::default());
        }

        let content = fs::read_to_string(&path)?;
        let config: AppConfig = toml::from_str(&content)?;
        Ok(config)
    }

    /// Sauvegarde la configuration sur le disque avec création atomique des dossiers parents
    pub fn save(&self, config: &AppConfig) -> Result<(), EnvSwitchError> {
        let path = self.config_path()?;
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }

        let serialized = toml::to_string_pretty(config)?;
        fs::write(&path, serialized)?;
        Ok(())
    }
}

