/// Valide le format d'une clé de variable d'environnement (POSIX-compatible: [a-zA-Z_][a-zA-Z0-9_]*)
fn validate_env_key(key: &str) -> Result<(), EnvSwitchError> {
    if key.is_empty() {
        return Err(EnvSwitchError::InvalidKeyName(key.to_string()));
    }
    let mut chars = key.chars();
    let first = chars.next().unwrap_or('_');
    if !(first.is_ascii_alphabetic() || first == '_') {
        return Err(EnvSwitchError::InvalidKeyName(key.to_string()));
    }
    if !chars.all(|c| c.is_ascii_alphanumeric() || c == '_') {
        return Err(EnvSwitchError::InvalidKeyName(key.to_string()));
    }
    Ok(())
}

/// Découpe une chaîne "CLE=VALEUR" en paire (clé, valeur)
fn parse_key_value(input: &str) -> Result<(String, String), EnvSwitchError> {
    if let Some((k, v)) = input.split_once('=') {
        validate_env_key(k)?;
        Ok((k.trim().to_string(), v.to_string()))
    } else {
        Err(EnvSwitchError::InvalidVariableFormat(input.to_string()))
    }
}

/// Échappe les valeurs pour l'insertion sécurisée dans un script shell
fn escape_shell_value(val: &str) -> String {
    val.replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('$', "\\$")
        .replace('`', "\\`")
}

/// Exécute la logique métier de l'application
pub fn run() -> anyhow::Result<()> {
    let cli = Cli::parse();
    let manager = ConfigManager::new(cli.config);
    let mut config = manager.load().context("Échec du chargement de la configuration")?;
    let cwd = std::env::current_dir().context("Impossible de déterminer le répertoire de travail courant")?;

    match cli.command {
        Commands::List => {
            let active = config.detect_profile(&cwd);
            println!("{}", "Profils d'environnement disponibles :".bold().underline());

            if config.profiles.is_empty() {
                println!("  {}", "Aucun profil configuré. Utilisez 'envswitch create <nom>'.".italic());
            } else {
                for (name, prof) in &config.profiles {
                    let is_active = active.as_deref() == Some(name.as_str());
                    let is_default = config.default_profile.as_deref() == Some(name.as_str());

                    let marker = if is_active {
                        " * ".green().bold()
                    } else {
                        "   ".normal()
                    };

                    let title = if is_active {
                        name.green().bold()
                    } else {
                        name.cyan().bold()
                    };

                    let mut flags = Vec::new();
                    if is_active {
                        flags.push("actif".green().to_string());
                    }
                    if is_default {
                        flags.push("défaut".yellow().to_string());
                    }

                    let flag_str = if flags.is_empty() {
                        String::new()
                    } else {
                        format!(" [{}]", flags.join(", "))
                    };

                    let desc_str = prof
                        .description
                        .as_deref()
                        .map(|d| format!(" - {}", d))
                        .unwrap_or_default();

                    let inherit_str = prof
                        .inherit
                        .as_deref()
                        .map(|inh| format!(" (hérite de {})", inh.blue()))
                        .unwrap_or_default();

                    let var_count = prof.vars.len();
                    println!(
                        "{}{}{}{} ({} var{}){}",
                        marker,
                        title,
                        flag_str,
                        inherit_str,
                        var_count,
                        if var_count > 1 { "s" } else { "" },
                        desc_str
                    );
                }
            }
        }

        Commands::Current => {
            if let Some(prof) = config.detect_profile(&cwd) {
                println!("{prof}");
            } else {
                eprintln!("{}", "Aucun profil actif pour le répertoire courant.".yellow());
                std::process::exit(1);
            }
        }

        Commands::Show { profile, raw } => {
            let prof_name = match profile {
                Some(p) => p,
                None => config
                    .detect_profile(&cwd)
                    .ok_or(EnvSwitchError::NoActiveProfile)?,
            };

            let vars = config.resolve_profile_vars(&prof_name)?;

            if raw {
                for (k, v) in vars {
                    println!("{k}={v}");
                }
            } else {
                let prof_meta = config.profiles.get(&prof_name).ok_or_else(|| EnvSwitchError::ProfileNotFound(prof_name.clone()))?;
                println!("{} {}", "Profil:".bold(), prof_name.green().bold());
                if let Some(ref desc) = prof_meta.description {
                    println!("{} {}", "Description:".bold(), desc);
                }
                if let Some(ref inh) = prof_meta.inherit {
                    println!("{} {}", "Hérite de:".bold(), inh.blue());
                }
                println!("{}", "Variables résolues :".bold().underline());
                if vars.is_empty() {
                    println!("  {}", "(aucune variable définie)".italic());
                } else {
                    for (k, v) in vars {
                        println!("  {} = {}", k.yellow().bold(), v);
                    }
                }
            }
        }

        Commands::Create {
            name,
            description,
            inherit,
        } => {
            if config.profiles.contains_key(&name) {
                return Err(EnvSwitchError::ProfileAlreadyExists(name).into());
            }

            if let Some(ref parent) = inherit {
                if !config.profiles.contains_key(parent) {
                    return Err(EnvSwitchError::ProfileNotFound(parent.clone()).into());
                }
            }

            let profile = Profile::new(description, inherit);
            config.profiles.insert(name.clone(), profile);

            // Si c'est le tout premier profil créé, le marquer par défaut
            if config.profiles.len() == 1 {
                config.default_profile = Some(name.clone());
            }

            manager.save(&config)?;
            println!("{} Profil '{}' créé avec succès.", "✔".green(), name.bold());
        }

        Commands::Delete { name } => {
            if config.profiles.remove(&name).is_none() {
                return Err(EnvSwitchError::ProfileNotFound(name).into());
            }

            if config.default_profile.as_deref() == Some(name.as_str()) {
                config.default_profile = None;
            }

            // Nettoyer les règles ciblant ce profil
            config.rules.retain(|r| r.profile != name);

            manager.save(&config)?;
            println!("{} Profil '{}' supprimé avec succès.", "✔".green(), name.bold());
        }

        Commands::Set {
            profile,
            assignments,
        } => {
            let prof = config
                .profiles
                .get_mut(&profile)
                .ok_or_else(|| EnvSwitchError::ProfileNotFound(profile.clone()))?;

            let mut count = 0;
            for assign in assignments {
                let (key, value) = parse_key_value(&assign)?;
                prof.vars.insert(key, value);
                count += 1;
            }

            manager.save(&config)?;
            println!(
                "{} {} variable(s) enregistrée(s) dans le profil '{}'.",
                "✔".green(),
                count,
                profile.bold()
            );
        }

        Commands::Unset { profile, keys } => {
            let prof = config
                .profiles
                .get_mut(&profile)
                .ok_or_else(|| EnvSwitchError::ProfileNotFound(profile.clone()))?;

            let mut count = 0;
            for k in &keys {
                if prof.vars.remove(k).is_some() {
                    count += 1;
                }
            }

            manager.save(&config)?;
            println!(
                "{} {} variable(s) supprimée(s) du profil '{}'.",
                "✔".green(),
                count,
                profile.bold()
            );
        }

        Commands::Default { profile } => {
            match profile {
                Some(name) => {
                    if !config.profiles.contains_key(&name) {
                        return Err(EnvSwitchError::ProfileNotFound(name).into());
                    }
                    config.default_profile = Some(name.clone());
                    println!("{} Profil par défaut configuré sur '{}'.", "✔".green(), name.bold());
                }
                None => {
                    config.default_profile = None;
                    println!("{} Profil par défaut désactivé.", "✔".green());
                }
            }
            manager.save(&config)?;
        }

        Commands::Export { profile, shell } => {
            let target_profile = match profile {
                Some(p) => p,
                None => config
                    .detect_profile(&cwd)
                    .ok_or(EnvSwitchError::NoActiveProfile)?,
            };

            let vars = config.resolve_profile_vars(&target_profile)?;

            for (k, v) in vars {
                let escaped = escape_shell_value(&v);
                match shell {
                    ShellType::Bash | ShellType::Zsh => {
                        println!("export {k}=\"{escaped}\"");
                    }
                    ShellType::Fish => {
                        println!("set -gx {k} \"{escaped}\";");
                    }
                    ShellType::Powershell => {
                        println!("$env:{k} = \"{escaped}\"");
                    }
                }
            }
        }

        Commands::Exec {
            profile,
            target,
            command,
        } => {
            if command.is_empty() {
                return Err(EnvSwitchError::EmptyCommand.into());
            }

            let target_profile = match profile.or(target) {
                Some(p) => p,
                None => config
                    .detect_profile(&cwd)
                    .ok_or(EnvSwitchError::NoActiveProfile)?,
            };

            let vars = config.resolve_profile_vars(&target_profile)?;

            let prog = &command[0];
            let args = &command[1..];

            let mut child = Command::new(prog);
            child.args(args);
            for (k, v) in vars {
                child.env(k, v);
            }

            let status: ExitStatus = child
                .status()
                .with_context(|| format!("Impossible d'exécuter la commande '{prog}'"))?;

            if let Some(code) = status.code() {
                std::process::exit(code);
            }
        }

        Commands::Rule(rule_args) => match rule_args.action {
            RuleSubcommands::Add { path, profile } => {
                if !config.profiles.contains_key(&profile) {
                    return Err(EnvSwitchError::ProfileNotFound(profile).into());
                }

                let target_path = path.unwrap_or(cwd);
                let canonical = dunce::canonicalize(&target_path).unwrap_or(target_path);

                // Éviter les doublons sur le même chemin
                config.rules.retain(|r| {
                    let r_canon = dunce::canonicalize(&r.path).unwrap_or_else(|_| r.path.clone());
                    r_canon != canonical
                });

                config.rules.push(ContextRule {
                    path: canonical.clone(),
                    profile: profile.clone(),
                });

                manager.save(&config)?;
                println!(
                    "{} Association enregistrée: {} -> '{}'",
                    "✔".green(),
                    canonical.display().to_string().bold(),
                    profile.cyan().bold()
                );
            }

            RuleSubcommands::List => {
                println!("{}", "Règles d'association de dossiers :".bold().underline());
                if config.rules.is_empty() {
                    println!("  {}", "Aucune règle définie. Utilisez 'envswitch rule add <dossier> <profil>'.".italic());
                } else {
                    for r in &config.rules {
                        println!("  {} -> {}", r.path.display().to_string().bold(), r.profile.cyan());
                    }
                }
            }

            RuleSubcommands::Remove { path } => {
                let canonical = dunce::canonicalize(&path).unwrap_or(path);
                let initial_len = config.rules.len();
                config.rules.retain(|r| {
                    let r_canon = dunce::canonicalize(&r.path).unwrap_or_else(|_| r.path.clone());
                    r_canon != canonical
                });

                if config.rules.len() == initial_len {
                    return Err(EnvSwitchError::RuleNotFound(canonical.display().to_string()).into());
                }

                manager.save(&config)?;
                println!("{} Règle supprimée pour {}.", "✔".green(), canonical.display());
            }
        },

        Commands::Hook { shell } => {
            match shell {
                ShellType::Bash => {
                    println!(
                        r#"# Intégration envswitch pour Bash
_envswitch_hook() {{
    local prof
    prof="$(envswitch current 2>/dev/null)"
    if [ -n "$prof" ] && [ "$prof" != "$ENVSWITCH_CURRENT" ]; then
        export ENVSWITCH_CURRENT="$prof"
        eval "$(envswitch export 2>/dev/null)"
    fi
}}
if [[ ! "$PROMPT_COMMAND" =~ _envswitch_hook ]]; then
    PROMPT_COMMAND="_envswitch_hook;${{PROMPT_COMMAND:-}}"
fi"#
                    );
                }
                ShellType::Zsh => {
                    println!(
                        r#"# Intégration envswitch pour Zsh
_envswitch_hook() {{
    local prof
    prof="$(envswitch current 2>/dev/null)"
    if [ -n "$prof" ] && [ "$prof" != "$ENVSWITCH_CURRENT" ]; then
        export ENVSWITCH_CURRENT="$prof"
        eval "$(envswitch export 2>/dev/null)"
    fi
}}
autoload -U add-zsh-hook
add-zsh-hook chpwd _envswitch_hook
_envswitch_hook"#
                    );
                }
                ShellType::Fish => {
                    println!(
                        r#"# Intégration envswitch pour Fish
function __envswitch_hook --on-variable PWD
    set -l prof (envswitch current 2>/dev/null)
    if test -n "$prof" -a "$prof" != "$ENVSWITCH_CURRENT"
        set -gx ENVSWITCH_CURRENT "$prof"
        eval (envswitch export --shell fish 2>/dev/null)
    end
end
__envswitch_hook"#
                    );
                }
                ShellType::Powershell => {
                    println!(
                        r#"# Intégration envswitch pour PowerShell
function Prompt {{
    $prof = envswitch current 2>$null
    if ($prof -and $prof -ne $env:ENVSWITCH_CURRENT) {{
        $env:ENVSWITCH_CURRENT = $prof
        Invoke-Expression (envswitch export --shell powershell 2>$null)
    }}
    "PS $($executionContext.SessionState.Path.CurrentLocation)$('>' * ($nestedPromptLevel + 1)) "
}}"#
                    );
                }
            }
        }
    }

    Ok(())
}

fn main() {
    if let Err(err) = run() {
        eprintln!("{}: {err:?}", "Erreur".red().bold());
        std::process::exit(1);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_key_value_valid() {
        let (k, v) = parse_key_value("DATABASE_URL=postgres://localhost/db").unwrap();
        assert_eq!(k, "DATABASE_URL");
        assert_eq!(v, "postgres://localhost/db");

        let (k, v) = parse_key_value("FOO=").unwrap();
        assert_eq!(k, "FOO");
        assert_eq!(v, "");

        let (k, v) = parse_key_value("_PRIVATE_KEY=secret_value_with=equals=").unwrap();
        assert_eq!(k, "_PRIVATE_KEY");
        assert_eq!(v, "secret_value_with=equals=");
    }

    #[test]
    fn test_parse_key_value_invalid() {
        assert!(parse_key_value("WITHOUT_EQUALS").is_err());
        assert!(parse_key_value("123INVALID_START=val").is_err());
        assert!(parse_key_value("INVALID-KEY=val").is_err());
    }

    #[test]
    fn test_inheritance_and_override() {
        let mut config = AppConfig::default();

        let mut base = Profile::new(Some("Profil de base".into()), None);
        base.vars.insert("SHARED_VAR".into(), "base_val".into());
        base.vars.insert("OVERRIDDEN_VAR".into(), "base_orig".into());
        config.profiles.insert("base".into(), base);

        let mut dev = Profile::new(Some("Profil dev hérité".into()), Some("base".into()));
        dev.vars.insert("DEV_SPECIFIC".into(), "dev_val".into());
        dev.vars.insert("OVERRIDDEN_VAR".into(), "overridden_by_dev".into());
        config.profiles.insert("dev".into(), dev);

        let resolved = config.resolve_profile_vars("dev").unwrap();

        assert_eq!(resolved.get("SHARED_VAR").map(|s| s.as_str()), Some("base_val"));
        assert_eq!(resolved.get("DEV_SPECIFIC").map(|s| s.as_str()), Some("dev_val"));
        assert_eq!(
            resolved.get("OVERRIDDEN_VAR").map(|s| s.as_str()),
            Some("overridden_by_dev")
        );
    }

    #[test]
    fn test_cycle_detection() {
        let mut config = AppConfig::default();

        let p1 = Profile::new(None, Some("p2".into()));
        let p2 = Profile::new(None, Some("p1".into()));

        config.profiles.insert("p1".into(), p1);
        config.profiles.insert("p2".into(), p2);

        let result = config.resolve_profile_vars("p1");
        assert!(matches!(result, Err(EnvSwitchError::InheritanceCycle(_))));
    }

    #[test]
    fn test_rule_detection_specificity() {
        let mut config = AppConfig::default();
        config.profiles.insert("root_prof".into(), Profile::new(None, None));
        config.profiles.insert("sub_prof".into(), Profile::new(None, None));

        let root_path = PathBuf::from("/workspace/project");
        let sub_path = PathBuf::from("/workspace/project/backend");

        config.rules.push(ContextRule {
            path: root_path,
            profile: "root_prof".into(),
        });
        config.rules.push(ContextRule {
            path: sub_path,
            profile: "sub_prof".into(),
        });

        // Test dans le sous-dossier: la règle la plus spécifique doit l'emporter
        let test_target = Path::new("/workspace/project/backend/src");
        assert_eq!(config.detect_profile(test_target), Some("sub_prof".into()));

        // Test dans le dossier racine
        let test_root = Path::new("/workspace/project/docs");
        assert_eq!(config.detect_profile(test_root), Some("root_prof".into()));
    }
}

