// src/main.rs
use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::time::Duration;

use anyhow::{Context, Result};
use chrono::{DateTime, Utc};
use clap::{Parser, ValueEnum};
use rand::distributions::Distribution;
use rand::rngs::SmallRng;
use rand::{Rng, SeedableRng};
use rand_distr::Normal;
use serde::{Deserialize, Serialize};
use tokio::io::AsyncWriteExt;
use tokio::sync::mpsc;
use tokio_util::sync::CancellationToken;
use tracing::{debug, error, info};
use tracing_subscriber::EnvFilter;
use uuid::Uuid;

/// CLI de simulation de capteurs IoT générant un flux continu d'événements de télémétrie horodatés.
#[derive(Parser, Debug, Clone)]
#[command(name = "iot-sensor-simulator", version, author, about)]
pub struct CliArgs {
    /// Nombre de capteurs concurrents à simuler
    #[arg(short = 's', long, default_value_t = 5)]
    pub sensors: usize,

    /// Intervalle d'échantillonnage moyen par capteur en millisecondes
    #[arg(short = 'f', long, default_value_t = 1000)]
    pub frequency_ms: u64,

    /// Jitter aléatoire sur la fréquence en millisecondes (+/- delta)
    #[arg(short = 'j', long, default_value_t = 150)]
    pub jitter_ms: u64,

    /// Taux d'injection d'anomalies (probabilité entre 0.0 et 1.0)
    #[arg(short = 'a', long, default_value_t = 0.02)]
    pub anomaly_rate: f64,

    /// Durée d'exécution maximale de la simulation en secondes (optionnel, infini si omis)
    #[arg(short = 'd', long)]
    pub duration_secs: Option<u64>,

    /// Nombre total maximal d'événements à émettre (optionnel, infini si omis)
    #[arg(short = 'm', long)]
    pub max_events: Option<u64>,

    /// Type de capteur spécifique à émuler (ou tous par défaut)
    #[arg(short = 't', long)]
    pub sensor_type: Option<SensorType>,

    /// Chemin du fichier de sortie (écrit sur stdout si non spécifié)
    #[arg(short = 'o', long)]
    pub output: Option<PathBuf>,

    /// Formater le flux JSON avec indentation
    #[arg(long, default_value_t = false)]
    pub pretty: bool,

    /// Mode silencieux (désactive les logs de tracing sur stderr)
    #[arg(short = 'q', long, default_value_t = false)]
    pub quiet: bool,
}

/// Types de capteurs pris en charge avec métriques associées
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, ValueEnum)]
#[serde(rename_all = "snake_case")]
pub enum SensorType {
    Temperature,
    Humidity,
    Pressure,
    Vibration,
    PowerConsumption,
    Co2Level,
}

impl SensorType {
    pub const ALL: [SensorType; 6] = [
        SensorType::Temperature,
        SensorType::Humidity,
        SensorType::Pressure,
        SensorType::Vibration,
        SensorType::PowerConsumption,
        SensorType::Co2Level,
    ];

    pub fn unit(&self) -> &'static str {
        match self {
            SensorType::Temperature => "°C",
            SensorType::Humidity => "%",
            SensorType::Pressure => "hPa",
            SensorType::Vibration => "mm/s",
            SensorType::PowerConsumption => "W",
            SensorType::Co2Level => "ppm",
        }
    }

    pub fn nominal_range(&self) -> (f64, f64) {
        match self {
            SensorType::Temperature => (18.0, 26.0),
            SensorType::Humidity => (35.0, 65.0),
            SensorType::Pressure => (990.0, 1030.0),
            SensorType::Vibration => (0.1, 2.5),
            SensorType::PowerConsumption => (45.0, 350.0),
            SensorType::Co2Level => (400.0, 950.0),
        }
    }

    pub fn typical_std_dev(&self) -> f64 {
        match self {
            SensorType::Temperature => 0.35,
            SensorType::Humidity => 0.8,
            SensorType::Pressure => 0.4,
            SensorType::Vibration => 0.15,
            SensorType::PowerConsumption => 3.5,
            SensorType::Co2Level => 15.0,
        }
    }

    pub fn generate_anomaly_multiplier(&self, rng: &mut impl Rng) -> f64 {
        match self {
            SensorType::Temperature => {
                if rng.gen_bool(0.5) {
                    rng.gen_range(1.6..2.5)
                } else {
                    rng.gen_range(0.2..0.5)
                }
            }
            SensorType::Humidity => rng.gen_range(1.4..1.8),
            SensorType::Pressure => {
                if rng.gen_bool(0.5) {
                    rng.gen_range(1.1..1.25)
                } else {
                    rng.gen_range(0.85..0.92)
                }
            }
            SensorType::Vibration => rng.gen_range(4.0..8.5),
            SensorType::PowerConsumption => rng.gen_range(2.0..3.8),
            SensorType::Co2Level => rng.gen_range(2.0..4.0),
        }
    }
}

/// Statut d'état du capteur
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "UPPERCASE")]
pub enum HealthStatus {
    Nominal,
    Warning,
    Critical,
}

/// Événement de télémétrie horodaté émis par un capteur IoT
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TelemetryEvent {
    pub event_id: Uuid,
    pub device_id: String,
    pub sensor_type: SensorType,
    pub location: String,
    pub timestamp: DateTime<Utc>,
    pub value: f64,
    pub unit: String,
    pub status: HealthStatus,
    pub battery_pct: f64,
    pub metadata: HashMap<String, serde_json::Value>,
}

/// Modèle d'état interne d'un capteur simulé
struct SensorSimulator {
    device_id: String,
    sensor_type: SensorType,
    location: String,
    current_value: f64,
    min_nominal: f64,
    max_nominal: f64,
    std_dev: f64,
    battery_pct: f64,
    battery_decay_rate: f64,
    sequence: u64,
    firmware_version: String,
    rng: SmallRng,
}

impl SensorSimulator {
    fn new(index: usize, sensor_type: SensorType, seed: u64) -> Self {
        let mut rng = SmallRng::seed_from_u64(seed);
        let (min_nominal, max_nominal) = sensor_type.nominal_range();
        let current_value = rng.gen_range(min_nominal..max_nominal);
        let std_dev = sensor_type.typical_std_dev();
        let battery_pct = rng.gen_range(88.0..100.0);
        let battery_decay_rate = rng.gen_range(0.0005..0.002);
        let zones = ["zone-alpha", "zone-bravo", "warehouse-1", "datacenter-b", "assembly-line-2"];
        let location = zones[index % zones.len()].to_string();

        Self {
            device_id: format!("iot-{}-{:04}", sensor_type.to_possible_value().map(|v| v.get_name().to_string()).unwrap_or_else(|| "dev".to_string()), index + 1),
            sensor_type,
            location,
            current_value,
            min_nominal,
            max_nominal,
            std_dev,
            battery_pct,
            battery_decay_rate,
            sequence: 0,
            firmware_version: format!("v{}.{}.0", 1 + (index % 3), index % 8),
            rng,
        }
    }

    fn generate_event(&mut self, anomaly_rate: f64) -> TelemetryEvent {
        self.sequence = self.sequence.saturating_add(1);

        // Dérive par marche aléatoire avec force de rappel vers la moyenne nominale
        let center = (self.min_nominal + self.max_nominal) / 2.0;
        let mean_reversion_strength = 0.08;
        let drift = (center - self.current_value) * mean_reversion_strength;

        let normal = Normal::new(0.0, self.std_dev).unwrap_or_else(|_| Normal::new(0.0, 1.0).unwrap());
        let noise = normal.sample(&mut self.rng);
        self.current_value += drift + noise;

        let is_anomaly = self.rng.gen_bool(anomaly_rate.clamp(0.0, 1.0));
        let reported_value = if is_anomaly {
            let mult = self.sensor_type.generate_anomaly_multiplier(&mut self.rng);
            self.current_value * mult
        } else {
            self.current_value
        };

        // Arrondi à deux décimales pour la télémétrie
        let formatted_value = (reported_value * 100.0).round() / 100.0;

        // Détermination du statut de santé
        let status = if formatted_value < self.min_nominal * 0.85 || formatted_value > self.max_nominal * 1.15 {
            HealthStatus::Critical
        } else if formatted_value < self.min_nominal || formatted_value > self.max_nominal {
            HealthStatus::Warning
        } else {
            HealthStatus::Nominal
        };

        // Dépréciation progressive de la batterie
        self.battery_pct = (self.battery_pct - self.battery_decay_rate).max(0.0);
        let rounded_battery = (self.battery_pct * 10.0).round() / 10.0;

        let mut metadata = HashMap::new();
        metadata.insert("sequence".to_string(), serde_json::json!(self.sequence));
        metadata.insert("firmware".to_string(), serde_json::json!(self.firmware_version));
        if is_anomaly {
            metadata.insert("anomaly_flag".to_string(), serde_json::json!(true));
        }

        TelemetryEvent {
            event_id: Uuid::new_v4(),
            device_id: self.device_id.clone(),
            sensor_type: self.sensor_type,
            location: self.location.clone(),
            timestamp: Utc::now(),
            value: formatted_value,
            unit: self.sensor_type.unit().to_string(),
            status,
            battery_pct: rounded_battery,
            metadata,
        }
    }
}

/// Tâche d'arrière-plan simulant un capteur individuel
async fn run_sensor_worker(
    mut simulator: SensorSimulator,
    frequency_ms: u64,
    jitter_ms: u64,
    anomaly_rate: f64,
    tx: mpsc::Sender<TelemetryEvent>,
    cancel_token: CancellationToken,
) {
    let mut rng = SmallRng::from_entropy();

    debug!(device_id = %simulator.device_id, "Démarrage de la boucle du capteur");

    while !cancel_token.is_cancelled() {
        let event = simulator.generate_event(anomaly_rate);

        if tx.send(event).await.is_err() {
            // Canal fermé (le consommateur s'est arrêté)
            break;
        }

        let jitter_offset = if jitter_ms > 0 {
            rng.gen_range(0..=(jitter_ms * 2)) as i64 - (jitter_ms as i64)
        } else {
            0
        };

        let sleep_duration_ms = ((frequency_ms as i64) + jitter_offset).max(10) as u64;

        tokio::select! {
            _ = tokio::time::sleep(Duration::from_millis(sleep_duration_ms)) => {},
            _ = cancel_token.cancelled() => {
                break;
            }
        }
    }

    debug!(device_id = %simulator.device_id, "Arrêt du capteur");
}

/// Écrivain asynchrone pour la sortie (stdout ou fichier)
async fn run_output_writer(
    mut rx: mpsc::Receiver<TelemetryEvent>,
    output_path: Option<PathBuf>,
    pretty: bool,
    max_events: Option<u64>,
    total_counter: Arc<AtomicU64>,
    cancel_token: CancellationToken,
) -> Result<()> {
    let mut writer: Box<dyn tokio::io::AsyncWrite + Unpin + Send> = match output_path {
        Some(path) => {
            let file = tokio::fs::OpenOptions::new()
                .create(true)
                .write(true)
                .truncate(true)
                .open(&path)
                .await
                .with_context(|| format!("Impossible d'ouvrir le fichier de sortie: {}", path.display()))?;
            Box::new(tokio::io::BufWriter::new(file))
        }
        None => Box::new(tokio::io::BufWriter::new(tokio::io::stdout())),
    };

    let mut count = 0u64;

    while let Some(event) = rx.recv().await {
        let serialized = if pretty {
            serde_json::to_string_pretty(&event)?
        } else {
            serde_json::to_string(&event)?
        };

        writer.write_all(serialized.as_bytes()).await?;
        writer.write_all(b"\n").await?;
        writer.flush().await?;

        count += 1;
        total_counter.fetch_add(1, Ordering::Relaxed);

        if let Some(max) = max_events {
            if count >= max {
                info!(total_emitted = count, "Limite max d'événements atteinte");
                cancel_token.cancel();
                break;
            }
        }
    }

    writer.flush().await?;
    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    let args = CliArgs::parse();

    // Configuration des logs avec formatage stderr pour préserver la propreté de stdout
    if !args.quiet {
        let env_filter = EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info"));
        tracing_subscriber::fmt()
            .with_env_filter(env_filter)
            .with_writer(std::io::stderr)
            .init();
    }

    info!(
        sensors_count = args.sensors,
        frequency_ms = args.frequency_ms,
        jitter_ms = args.jitter_ms,
        anomaly_rate = args.anomaly_rate,
        "Démarrage du simulateur de télémétrie IoT"
    );

    let cancel_token = CancellationToken::new();
    let total_counter = Arc::new(AtomicU64::new(0));

    // Gestion de l'interruption Ctrl+C
    let cancel_for_signal = cancel_token.clone();
    tokio::spawn(async move {
        if tokio::signal::ctrl_c().await.is_ok() {
            info!("Signal d'interruption reçu (SIGINT), arrêt gracieux en cours...");
            cancel_for_signal.cancel();
        }
    });

    // Gestion du timer de durée limite si spécifié
    if let Some(duration_secs) = args.duration_secs {
        let cancel_for_timer = cancel_token.clone();
        tokio::spawn(async move {
            tokio::time::sleep(Duration::from_secs(duration_secs)).await;
            info!(duration_secs, "Durée limite atteinte, arrêt de la simulation");
            cancel_for_timer.cancel();
        });
    }

    let (tx, rx) = mpsc::channel::<TelemetryEvent>(args.sensors.max(1) * 4);

    // Démarrage de la tâche de sortie
    let writer_token = cancel_token.clone();
    let writer_total_counter = Arc::clone(&total_counter);
    let output_handle = tokio::spawn(run_output_writer(
        rx,
        args.output.clone(),
        args.pretty,
        args.max_events,
        writer_total_counter,
        writer_token,
    ));

    // Instanciation et démarrage des capteurs
    let mut sensor_handles = Vec::with_capacity(args.sensors);
    let mut seed_rng = SmallRng::from_entropy();

    for i in 0..args.sensors {
        let sensor_type = args.sensor_type.unwrap_or_else(|| {
            SensorType::ALL[i % SensorType::ALL.len()]
        });
        let sensor_seed = seed_rng.gen::<u64>();
        let simulator = SensorSimulator::new(i, sensor_type, sensor_seed);
        let worker_tx = tx.clone();
        let worker_token = cancel_token.clone();

        let handle = tokio::spawn(run_sensor_worker(
            simulator,
            args.frequency_ms,
            args.jitter_ms,
            args.anomaly_rate,
            worker_tx,
            worker_token,
        ));
        sensor_handles.push(handle);
    }

    // Libération de la copie principale du sender pour permettre la fermeture du channel
    drop(tx);

    // Attente de l'annulation (Ctrl+C, limite atteinte, etc.)
    cancel_token.cancelled().await;

    // Attente de l'arrêt des workers capteurs
    for handle in sensor_handles {
        let _ = handle.await;
    }

    // Attente de la vidange du flux de sortie
    if let Err(e) = output_handle.await? {
        error!(error = %e, "Erreur dans le flux d'écriture");
        return Err(e);
    }

    let total = total_counter.load(Ordering::Relaxed);
    info!(total_events = total, "Simulation terminée avec succès");

    Ok(())
}

