// src/main.rs
use anyhow::{Context, Result};
use clap::{Parser, Subcommand};
use colored::*;
use std::collections::{BTreeMap, BTreeSet};
use std::fs::{self, File};
use std::io::{BufRead, BufReader};
use std::os::unix::io::AsRawFd;
use std::path::{Path, PathBuf};
use std::thread;
use std::time::Duration;

/// Types de descripteurs identifiés
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FdType {
    RegularFile,
    Directory,
    Socket,
    Pipe,
    AnonInode(String),
    CharacterDevice,
    BlockDevice,
    Unknown(String),
}

impl FdType {
    pub fn from_target(target: &str) -> Self {
        if target.starts_with("socket:[") {
            FdType::Socket
        } else if target.starts_with("pipe:[") {
            FdType::Pipe
        } else if target.starts_with("anon_inode:") {
            let detail = target.trim_start_matches("anon_inode:").to_string();
            FdType::AnonInode(detail)
        } else if target.starts_with("/dev/pts/") || target.starts_with("/dev/tty") {
            FdType::CharacterDevice
        } else if target.starts_with("/dev/") {
            FdType::CharacterDevice
        } else {
            match fs::metadata(target) {
                Ok(meta) => {
                    use std::os::unix::fs::FileTypeExt;
                    let ft = meta.file_type();
                    if ft.is_dir() {
                        FdType::Directory
                    } else if ft.is_file() {
                        FdType::RegularFile
                    } else if ft.is_char_device() {
                        FdType::CharacterDevice
                    } else if ft.is_block_device() {
                        FdType::BlockDevice
                    } else if ft.is_fifo() {
                        FdType::Pipe
                    } else if ft.is_socket() {
                        FdType::Socket
                    } else {
                        FdType::Unknown(target.to_string())
                    }
                }
                Err(_) => {
                    if target.contains("(deleted)") {
                        FdType::RegularFile
                    } else {
                        FdType::Unknown(target.to_string())
                    }
                }
            }
        }
    }

    pub fn badge(&self) -> ColoredString {
        match self {
            FdType::RegularFile => "FILE".green(),
            FdType::Directory => "DIR".blue(),
            FdType::Socket => "SOCK".magenta(),
            FdType::Pipe => "PIPE".yellow(),
            FdType::AnonInode(name) => format!("ANON({})", name).cyan(),
            FdType::CharacterDevice => "CHR".white().bold(),
            FdType::BlockDevice => "BLK".white().bold(),
            FdType::Unknown(_) => "UNKNOWN".dimmed(),
        }
    }
}

/// Métadonnées supplémentaires issues de /proc/[pid]/fdinfo/[fd]
#[derive(Debug, Clone, Default)]
pub struct FdDetails {
    pub pos: Option<u64>,
    pub flags: Option<u32>,
    pub mnt_id: Option<u64>,
}

/// Représentation complète d'un descripteur de fichier
#[derive(Debug, Clone)]
pub struct FdEntry {
    pub fd: i32,
    pub target: String,
    pub fd_type: FdType,
    pub details: FdDetails,
}

impl FdEntry {
    pub fn display_row(&self) -> String {
        let flags_str = self
            .details
            .flags
            .map(|f| format!("0o{:o}", f))
            .unwrap_or_else(|| "-".to_string());

        let pos_str = self
            .details
            .pos
            .map(|p| p.to_string())
            .unwrap_or_else(|| "-".to_string());

        format!(
            "{:>4} | {:<16} | {:>8} | {:>8} | {}",
            self.fd,
            self.fd_type.badge(),
            pos_str,
            flags_str,
            self.target.bright_white()
        )
    }
}

/// Cliché instantané des descripteurs ouverts
#[derive(Debug, Clone)]
pub struct FdSnapshot {
    pub pid: String,
    pub entries: BTreeMap<i32, FdEntry>,
}

impl FdSnapshot {
    /// Capture les descripteurs de fichiers pour un PID donné ("self" par défaut)
    pub fn capture(target_pid: Option<u32>) -> Result<Self> {
        let pid_str = target_pid
            .map(|p| p.to_string())
            .unwrap_or_else(|| "self".to_string());

        let proc_fd_dir = PathBuf::from(format!("/proc/{}/fd", pid_str));
        let proc_fdinfo_dir = PathBuf::from(format!("/proc/{}/fdinfo", pid_str));

        if !proc_fd_dir.exists() {
            anyhow::bail!(
                "Le répertoire {} n'existe pas ou le processus n'est pas accessible.",
                proc_fd_dir.display()
            );
        }

        let dir_reader = fs::read_dir(&proc_fd_dir)
            .with_context(|| format!("Impossible de lire {}", proc_fd_dir.display()))?;

        // Afin d'éviter de reporter le FD ouvert par fs::read_dir() sur /proc/self/fd,
        // on identifie le descripteur pointant vers le dossier proc lui-même si applicable.
        let mut entries = BTreeMap::new();
        let mut dir_fds_to_ignore = BTreeSet::new();

        for entry_res in dir_reader {
            let entry = match entry_res {
                Ok(e) => e,
                Err(_) => continue, // Le FD a pu être fermé entre-temps (concurrence)
            };

            let file_name = entry.file_name();
            let fd_str = match file_name.to_str() {
                Some(s) => s,
                None => continue,
            };

            let fd: i32 = match fd_str.parse() {
                Ok(num) => num,
                Err(_) => continue,
            };

            let link_path = entry.path();
            let target_path = match fs::read_link(&link_path) {
                Ok(path) => path.to_string_lossy().to_string(),
                Err(_) => continue, // Descripteur possiblement fermé de façon asynchrone
            };

            // Filtrer le descripteur propre à l'énumération de /proc/[pid]/fd
            if target_path.ends_with("/fd") || target_path.ends_with("/fd/") {
                dir_fds_to_ignore.insert(fd);
                continue;
            }

            // Récupération des informations fdinfo
            let fdinfo_path = proc_fdinfo_dir.join(fd_str);
            let details = parse_fdinfo(&fdinfo_path);
            let fd_type = FdType::from_target(&target_path);

            entries.insert(
                fd,
                FdEntry {
                    fd,
                    target: target_path,
                    fd_type,
                    details,
                },
            );
        }

        // Nettoie tout résidu de scan
        for ignored_fd in dir_fds_to_ignore {
            entries.remove(&ignored_fd);
        }

        Ok(Self {
            pid: pid_str,
            entries,
        })
    }

    /// Calcule le différentiel entre le snapshot actuel et un snapshot précédent
    pub fn diff(&self, baseline: &FdSnapshot) -> FdDiff {
        let mut leaked_or_opened = Vec::new();
        let mut closed = Vec::new();
        let mut retained = Vec::new();

        for (&fd, entry) in &self.entries {
            if !baseline.entries.contains_key(&fd) {
                leaked_or_opened.push(entry.clone());
            } else {
                retained.push(entry.clone());
            }
        }

        for (&fd, entry) in &baseline.entries {
            if !self.entries.contains_key(&fd) {
                closed.push(entry.clone());
            }
        }

        FdDiff {
            opened: leaked_or_opened,
            closed,
            retained,
        }
    }
}

/// Analyse les champs textuels de /proc/[pid]/fdinfo/[fd]
fn parse_fdinfo(path: &Path) -> FdDetails {
    let mut details = FdDetails::default();
    let file = match File::open(path) {
        Ok(f) => f,
        Err(_) => return details,
    };

    let reader = BufReader::new(file);
    for line_res in reader.lines() {
        let line = match line_res {
            Ok(l) => l,
            Err(_) => break,
        };

        let mut parts = line.split_whitespace();
        if let (Some(key), Some(value)) = (parts.next(), parts.next()) {
            match key {
                "pos:" => {
                    details.pos = value.parse::<u64>().ok();
                }
                "flags:" => {
                    details.flags = u32::from_str_radix(value.trim_start_matches("0"), 8).ok();
                }
                "mnt_id:" => {
                    details.mnt_id = value.parse::<u64>().ok();
                }
                _ => {}
            }
        }
    }

    details
}

