/// Gestionnaire RAII pour détecter automatiquement les fuites dans un bloc de code
pub struct FdLeakGuard {
    baseline: FdSnapshot,
    allowed_whitelist: BTreeSet<i32>,
    name: String,
}

impl FdLeakGuard {
    pub fn new(name: impl Into<String>) -> Result<Self> {
        let baseline = FdSnapshot::capture(None)?;
        Ok(Self {
            baseline,
            allowed_whitelist: BTreeSet::new(),
            name: name.into(),
        })
