    }

    /// Vérifie et retourne le résultat de détection des fuites
    pub fn check(self) -> Result<FdDiff> {
        let current = FdSnapshot::capture(None)?;
        let mut diff = current.diff(&self.baseline);

        // Exclut les descripteurs whitelistés
        diff.opened.retain(|entry| !self.allowed_whitelist.contains(&entry.fd));

        if diff.has_leaks() {
