    }
}

/// Démonstration didactique de détection de fuites
fn run_demonstration() -> Result<()> {
    println!("{}", "=== Démonstration du Détecteur de Fuites de FD ===".cyan().bold());

    // 1. Initialisation de la surveillance
    let guard_normal = FdLeakGuard::new("Scénario RAII Sain")?;
    println!("\n1. Exécution d'un traitement normal avec libération automatique...");
    {
        let tmp_file = tempfile_leak_helper("healthy_test.tmp")?;
        println!("   Fichier temporaire ouvert via FD {}", tmp_file.as_raw_fd());
        // tmp_file sort du scope ici et se ferme automatiquement via Drop
    }
    let diff_normal = guard_normal.check()?;
    assert!(!diff_normal.has_leaks(), "Le scénario sain ne doit pas signaler de fuite.");

    // 2. Scénario avec fuite volontaire
    println!("\n2. Exécution d'un scénario avec fuite volontaire (std::mem::forget)...");
    let guard_leaky = FdLeakGuard::new("Scénario Fuite Volontaire")?;

    // On simule une fuite en omettant le drop avec mem::forget
    let leaked_file = tempfile_leak_helper("leaked_demo.tmp")?;
    let leaked_fd = leaked_file.as_raw_fd();
    std::mem::forget(leaked_file); // Déclenche la fuite explicite

    // On simule une deuxième fuite : création d'un pipe anonyme non fermé
    let mut pipe_fds = [0i32; 2];
    let res = unsafe { libc::pipe(pipe_fds.as_mut_ptr()) };
    if res != 0 {
        return Err(anyhow::anyhow!("Échec de création du pipe POSIX"));
    }
    let (pipe_read, pipe_write) = (pipe_fds[0], pipe_fds[1]);

    println!("   Descripteur fuité (fichier) : FD {}", leaked_fd);
    println!("   Descripteurs fuité (pipe)   : FD {}, FD {}", pipe_read, pipe_write);

    let diff_leaky = guard_leaky.check()?;

    println!("\n=== Détails des descripteurs non libérés (Diff) ===");
    print_table_header();
    for entry in &diff_leaky.opened {
        println!("{}", entry.display_row());
    }

    // Nettoyage manuel des fuites de démonstration
    unsafe {
        libc::close(leaked_fd);
        libc::close(pipe_read);
        libc::close(pipe_write);
    }
    println!("\nNettoyage manuel post-démonstration effectué.");
    Ok(())
}

fn tempfile_leak_helper(name: &str) -> Result<File> {
    let path = std::env::temp_dir().join(name);
    File::options()
        .read(true)
        .write(true)
        .create(true)
        .truncate(true)
        .open(path)
        .context("Création du fichier temporaire échouée")
}

fn print_table_header() {
    println!(
