    println!("   Descripteurs fuité (pipe)   : FD {}, FD {}", pipe_read, pipe_write);

    let diff_leaky = guard_leaky.check()?;

    println!("\n=== Détails des descripteurs non libérés (Diff) ===");
    print_table_header();
    for entry in &diff_leaky.opened {
        println!("{}", entry.display_row());
    }

    // Nettoyage manuel des fuites de démonstration
    unsafe {
        libc::close(leaked_fd);
        libc::close(pipe_read);
        libc::close(pipe_write);
    }
    println!("\nNettoyage manuel post-démonstration effectué.");
    Ok(())
}

fn tempfile_leak_helper(name: &str) -> Result<File> {
    let path = std::env::temp_dir().join(name);
    File::options()
        .read(true)
        .write(true)
        .create(true)
        .truncate(true)
        .open(path)
        .context("Création du fichier temporaire échouée")
}

fn print_table_header() {
    println!(
        "{}",
        format!(
            "{:>4} | {:<16} | {:>8} | {:>8} | {}",
            "FD", "TYPE", "OFFSET", "FLAGS", "TARGET / CHEMIN"
        )
        .dimmed()
    );
    println!("{}", "-".repeat(78).dimmed());
}

/// Affiche l'inventaire complet des FD
fn inspect_process(pid: Option<u32>) -> Result<()> {
    let snapshot = FdSnapshot::capture(pid)?;
    let target_label = pid
        .map(|p| format!("PID {}", p))
        .unwrap_or_else(|| "processus courant (self)".to_string());

    println!(
        "{}",
        format!("=== Descripteurs ouverts pour {} ===", target_label)
            .cyan()
            .bold()
    );
    println!("Nombre total de descripteurs : {}\n", snapshot.entries.len());

    print_table_header();
    for entry in snapshot.entries.values() {
        println!("{}", entry.display_row());
    }

    Ok(())
}

/// Surveillance continue d'un processus pour observer la dérive des FDs
fn monitor_process(pid: Option<u32>, interval_sec: u64, limit: Option<usize>) -> Result<()> {
    let pid_label = pid
        .map(|p| format!("PID {}", p))
        .unwrap_or_else(|| "self".to_string());

    println!(
        "{}",
        format!(
            "Démarrage de la surveillance continue ({}) toutes les {}s...",
            pid_label, interval_sec
        )
        .cyan()
        .bold()
    );

    let mut baseline = FdSnapshot::capture(pid)?;
    let mut iteration = 0;

    loop {
        thread::sleep(Duration::from_secs(interval_sec));
        iteration += 1;

        let current = match FdSnapshot::capture(pid) {
            Ok(s) => s,
            Err(e) => {
                eprintln!("Processus introuvable ou terminé: {}", e);
                break;
            }
        };

        let diff = current.diff(&baseline);
        let timestamp = chrono_now_string();

        if diff.opened.is_empty() && diff.closed.is_empty() {
            println!(
                "[{}] Stable - Total: {} FD(s)",
                timestamp.dimmed(),
                current.entries.len()
            );
        } else {
            println!(
                "[{}] ÉVOLUTION DÉTECTÉE : +{} ouverts, -{} fermés | Total: {}",
                timestamp.yellow().bold(),
                diff.opened.len().to_string().red(),
                diff.closed.len().to_string().green(),
                current.entries.len()
            );

            for opened in &diff.opened {
                println!("  {} FD {}: {}", "+ NOUVEAU".red().bold(), opened.fd, opened.target);
            }
            for closed in &diff.closed {
                println!("  {} FD {}: {}", "- FERMÉ".green().bold(), closed.fd, closed.target);
            }
        }

        baseline = current;

        if let Some(max_iter) = limit {
            if iteration >= max_iter {
                println!("Limite d'itérations atteinte ({}/{}). Fin de surveillance.", iteration, max_iter);
                break;
            }
        }
    }

    Ok(())
}

fn chrono_now_string() -> String {
    // Horodatage simplifié sans dépendance lourde
    let now = std::time::SystemTime::now();
    let duration = now
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default();
    let secs = duration.as_secs();
    let hours = (secs / 3600) % 24;
    let minutes = (secs / 60) % 60;
    let seconds = secs % 60;
    format!("{:02}:{:02}:{:02}", hours, minutes, seconds)
}

#[derive(Parser, Debug)]
#[command(
    name = "fd-leak-detector",
    about = "Détecteur et analyseur de fuites de descripteurs de fichiers sous Linux via /proc/self/fd",
    version = "0.1.0"
)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
