        let snapshot = FdSnapshot::capture(None).expect("La capture de /proc/self/fd doit réussir");
        assert!(!snapshot.entries.is_empty());
        assert!(snapshot.entries.contains_key(&0) || snapshot.entries.contains_key(&1));
