        let baseline = FdSnapshot::capture(None).expect("Capture baseline");

        let tmp = tempfile_leak_helper("unit_test_leak.tmp").expect("Fichier temporaire créé");
        let raw_fd = tmp.as_raw_fd();

        let intermediate = FdSnapshot::capture(None).expect("Capture intermédiaire");
        let diff = intermediate.diff(&baseline);

        assert!(
            diff.opened.iter().any(|e| e.fd == raw_fd),
            "Le nouveau FD doit être détecté dans le diff"
        );

        drop(tmp);
        let final_snapshot = FdSnapshot::capture(None).expect("Capture finale");
        let diff_after_drop = final_snapshot.diff(&baseline);
        assert!(
            !diff_after_drop.opened.iter().any(|e| e.fd == raw_fd),
            "Le FD libéré ne doit plus être dans opened"
        );
    }
}

