// src/main.rs
use anyhow::{bail, Context, Result};
use clap::{Parser, Subcommand};
use std::fs::{self, File};
use std::io::{Read, Write};
use std::path::{Path, PathBuf};
use walkdir::WalkDir;
use zip::write::SimpleFileOptions;
use zip::{CompressionMethod, ZipArchive, ZipWriter};

#[derive(Parser, Debug)]
#[command(
    name = "zipcli",
    version,
    about = "Outil CLI de compression/décompression ZIP avec filtrage par extension et préservation des permissions Unix."
)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Compresser un fichier ou dossier dans une archive ZIP
    Compress {
        /// Chemin source (fichier ou répertoire à archiver)
        #[arg(short, long)]
        source: PathBuf,

        /// Fichier ZIP de sortie
        #[arg(short, long)]
        output: PathBuf,

        /// Extensions à inclure (ex: --include-ext rs --include-ext toml)
        #[arg(long = "include-ext")]
        include_extensions: Vec<String>,

        /// Extensions à exclure (ex: --exclude-ext log --exclude-ext tmp)
        #[arg(long = "exclude-ext")]
        exclude_extensions: Vec<String>,
    },

    /// Décompresser une archive ZIP
    Decompress {
        /// Archive ZIP source
        #[arg(short, long)]
        archive: PathBuf,

        /// Répertoire de destination
        #[arg(short, long)]
        target: PathBuf,

        /// Extensions à inclure (ex: --include-ext rs)
        #[arg(long = "include-ext")]
        include_extensions: Vec<String>,

        /// Extensions à exclure (ex: --exclude-ext exe)
        #[arg(long = "exclude-ext")]
        exclude_extensions: Vec<String>,
    },
}

/// Normalise une liste d'extensions en minuscules et sans point initial
fn sanitize_extensions(exts: &[String]) -> Vec<String> {
    exts.iter()
        .map(|e| e.trim().trim_start_matches('.').to_lowercase())
        .filter(|e| !e.is_empty())
        .collect()
}

/// Détermine si un chemin est éligible selon les filtres d'extensions
fn should_process_path(
    path: &Path,
    is_dir: bool,
    include_exts: &[String],
    exclude_exts: &[String],
) -> bool {
    // Les répertoires sont toujours inclus pour conserver l'arborescence
    if is_dir {
        return true;
    }

    let ext = path
        .extension()
        .and_then(|s| s.to_str())
        .map(|s| s.to_lowercase())
        .unwrap_or_default();

    if !exclude_exts.is_empty() && exclude_exts.iter().any(|excluded| excluded == &ext) {
        return false;
    }

    if !include_exts.is_empty() && !include_exts.iter().any(|included| included == &ext) {
        return false;
    }

    true
}

fn compress(
    source: &Path,
    output: &Path,
    include_exts: &[String],
    exclude_exts: &[String],
) -> Result<()> {
    if !source.exists() {
        bail!("Le chemin source n'existe pas : {}", source.display());
    }

    if let Some(parent) = output.parent() {
        if !parent.as_os_str().is_empty() && !parent.exists() {
            fs::create_dir_all(parent)
                .with_context(|| format!("Impossible de créer le dossier {}", parent.display()))?;
        }
    }

    let file = File::create(output)
        .with_context(|| format!("Impossible de créer l'archive {}", output.display()))?;
    let mut zip = ZipWriter::new(file);

    let prefix = if source.is_dir() {
        source
    } else {
        source
            .parent()
            .unwrap_or_else(|| Path::new(""))
    };

    let mut count = 0usize;

    for entry in WalkDir::new(source).into_iter().filter_map(|e| e.ok()) {
        let path = entry.path();
        let is_dir = entry.file_type().is_dir();

        if !should_process_path(path, is_dir, include_exts, exclude_exts) {
            continue;
        }

        let rel_path = match path.strip_prefix(prefix) {
            Ok(p) => p,
            Err(_) => path,
        };

        let mut name = rel_path
            .components()
            .map(|c| c.as_os_str().to_string_lossy())
            .collect::<Vec<_>>()
            .join("/");

        if name.is_empty() {
            continue;
        }

        #[allow(unused_mut)]
        let mut options = SimpleFileOptions::default()
            .compression_method(CompressionMethod::Deflated);

        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            if let Ok(metadata) = entry.metadata() {
                let permissions = metadata.permissions().mode();
                options = options.unix_permissions(permissions);
            }
        }

        if is_dir {
            if !name.ends_with('/') {
                name.push('/');
            }
            zip.add_directory(&name, options)
                .with_context(|| format!("Impossible d'ajouter le dossier '{}'", name))?;
        } else {
            zip.start_file(&name, options)
                .with_context(|| format!("Impossible de créer le fichier '{}' dans l'archive", name))?;
            let mut f = File::open(path)
                .with_context(|| format!("Impossible de lire le fichier {}", path.display()))?;
            let mut buffer = Vec::new();
            f.read_to_end(&mut buffer)?;
            zip.write_all(&buffer)?;
            count += 1;
        }
    }

    zip.finish()
        .with_context(|| "Erreur lors de la finalisation de l'archive ZIP")?;

    println!(
        "Compression terminée avec succès : {} fichier(s) archivé(s) dans {}",
        count,
        output.display()
    );

    Ok(())
}

fn decompress(
    archive_path: &Path,
    target: &Path,
    include_exts: &[String],
    exclude_exts: &[String],
) -> Result<()> {
    if !archive_path.exists() {
        bail!("L'archive source n'existe pas : {}", archive_path.display());
    }

    let file = File::open(archive_path)
        .with_context(|| format!("Impossible d'ouvrir l'archive {}", archive_path.display()))?;
    let mut archive = ZipArchive::new(file)
        .with_context(|| "Impossible de lire la structure de l'archive ZIP")?;

    if !target.exists() {
        fs::create_dir_all(target)
            .with_context(|| format!("Impossible de créer le dossier cible {}", target.display()))?;
    }

    let mut count = 0usize;

    for i in 0..archive.len() {
        let mut file = archive
            .by_index(i)
            .with_context(|| format!("Erreur lors de l'accès au fichier d'index {}", i))?;

        let enclosed_path = match file.enclosed_name() {
            Some(path) => path.to_owned(),
            None => {
                // Protection contre les failles 'Zip Slip' (chemins avec ../ ou absolus hors cible)
                continue;
            }
        };

        let outpath = target.join(&enclosed_path);
        let is_dir = file.is_dir();

        if !should_process_path(&enclosed_path, is_dir, include_exts, exclude_exts) {
            continue;
        }

        if is_dir {
            fs::create_dir_all(&outpath)
                .with_context(|| format!("Impossible de créer le dossier {}", outpath.display()))?;
        } else {
            if let Some(parent) = outpath.parent() {
                if !parent.exists() {
                    fs::create_dir_all(parent).with_context(|| {
                        format!("Impossible de créer le dossier parent {}", parent.display())
                    })?;
                }
            }

            let mut outfile = File::create(&outpath)
                .with_context(|| format!("Impossible d'extraire {}", outpath.display()))?;
            std::io::copy(&mut file, &mut outfile)
                .with_context(|| format!("Erreur lors de l'écriture de {}", outpath.display()))?;
            count += 1;
        }

        // Restauration des permissions sous Unix
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            if let Some(mode) = file.unix_mode() {
                // On applique uniquement les bits d'accès standard (permissions utilisateur/groupe/autres)
                let permissions = fs::Permissions::from_mode(mode & 0o777);
                let _ = fs::set_permissions(&outpath, permissions);
            }
        }
    }

    println!(
        "Décompression terminée avec succès : {} fichier(s) extrait(s) vers {}",
        count,
        target.display()
    );

    Ok(())
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Compress {
            source,
            output,
            include_extensions,
            exclude_extensions,
        } => {
            let includes = sanitize_extensions(&include_extensions);
            let excludes = sanitize_extensions(&exclude_extensions);
            compress(&source, &output, &includes, &excludes)?;
        }
        Commands::Decompress {
            archive,
            target,
            include_extensions,
            exclude_extensions,
        } => {
            let includes = sanitize_extensions(&include_extensions);
            let excludes = sanitize_extensions(&exclude_extensions);
            decompress(&archive, &target, &includes, &excludes)?;
        }
    }

    Ok(())
}

