// src/main.rs
use std::fs;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use anyhow::{Context, Result};
use clap::Parser;
use colored::Colorize;
use syn::visit::{self, Visit};
use syn::{BinOp, Expr, File, ImplItemFn, ItemFn};
use walkdir::WalkDir;

/// Outil d'analyse de complexité cyclomatique pour code source Rust.
#[derive(Parser, Debug)]
#[command(
    name = "rust-cyclomatic-complexity",
    author = "Damien",
    version = "0.1.0",
    about = "Mesure la complexité cyclomatique (embranchements, boucles, opérateurs logiques) des fonctions Rust"
)]
struct Cli {
    /// Chemin du fichier ou répertoire à analyser
    #[arg(short, long, default_value = ".")]
    path: PathBuf,

    /// Seuil de complexité déclenchant un avertissement (défaut: 10)
    #[arg(short, long, default_value_t = 10)]
    threshold: usize,

    /// Renvoie un code de sortie d'erreur si une fonction dépasse le seuil
    #[arg(long, default_value_t = false)]
    fail_on_threshold: bool,

    /// Afficher uniquement les fonctions dépassant le seuil
    #[arg(short, long, default_value_t = false)]
    only_warnings: bool,
}

/// Résultat d'analyse pour une fonction ou méthode
#[derive(Debug, Clone)]
struct FunctionMetrics {
    name: String,
    file_path: PathBuf,
    line: usize,
    complexity: usize,
}

/// Visiteur AST pour dénombrer les points de décision au sein d'un corps de fonction
#[derive(Default)]
struct ComplexityCalculator {
    decisions: usize,
}

impl<'ast> Visit<'ast> for ComplexityCalculator {
    fn visit_expr(&mut self, node: &'ast Expr) {
        match node {
            // Conditions : if, if let
            Expr::If(_) => {
                self.decisions += 1;
            }
            // Boucles : while, while let
            Expr::While(_) => {
                self.decisions += 1;
            }
            // Boucles : for
            Expr::ForLoop(_) => {
                self.decisions += 1;
            }
            // Boucles inconditionnelles : loop
            Expr::Loop(_) => {
                self.decisions += 1;
            }
            // Opérateur de propagation d'erreur '?'
            Expr::Try(_) => {
                self.decisions += 1;
            }
            // Opérateurs binaires logiques avec court-circuit (&&, ||)
            Expr::Binary(expr_binary) => match expr_binary.op {
                BinOp::And(_) | BinOp::Or(_) => {
                    self.decisions += 1;
                }
                _ => {}
            },
            // Bras de match : chaque bras supplémentaire ou garde conditionnelle
            Expr::Match(expr_match) => {
                // Pour n bras, il y a max(0, n - 1) embranchements alternatifs
                if expr_match.arms.len() > 1 {
                    self.decisions += expr_match.arms.len() - 1;
                }
                // Si un bras a un garde `if <expr>`, cela constitue un point de décision supplémentaire
                for arm in &expr_match.arms {
                    if arm.guard.is_some() {
                        self.decisions += 1;
                    }
                }
            }
            // Fermetures / fonctions imbriquées : ne pas les inclure directement dans la complexité de la fonction englobante
            Expr::Closure(_) => {
                return;
            }
            _ => {}
        }

        // Poursuivre la visite des sous-expressions
        visit::visit_expr(self, node);
    }
}

/// Visiteur de premier niveau extrayant toutes les fonctions et méthodes
struct FunctionExtractor<'p> {
    file_path: &'p Path,
    metrics: Vec<FunctionMetrics>,
}

impl<'p> FunctionExtractor<'p> {
    fn new(file_path: &'p Path) -> Self {
        Self {
            file_path,
            metrics: Vec::new(),
        }
    }

    fn analyze_block(&mut self, name: String, line: usize, block: &syn::Block) {
        let mut calc = ComplexityCalculator::default();
        calc.visit_block(block);
        // La complexité cyclomatique de McCabe est 1 + nb_decisions
        let complexity = 1 + calc.decisions;

        self.metrics.push(FunctionMetrics {
            name,
            file_path: self.file_path.to_path_buf(),
            line,
            complexity,
        });
    }
}

impl<'ast, 'p> Visit<'ast> for FunctionExtractor<'p> {
    // Fonctions libres (fn)
    fn visit_item_fn(&mut self, item: &'ast ItemFn) {
        let name = item.sig.ident.to_string();
        let line = item.sig.ident.span().start().line;
        self.analyze_block(name, line, &item.block);

        visit::visit_item_fn(self, item);
    }

    // Méthodes de blocs impl
    fn visit_impl_item_fn(&mut self, item: &'ast ImplItemFn) {
        let name = item.sig.ident.to_string();
        let line = item.sig.ident.span().start().line;
        self.analyze_block(name, line, &item.block);

        visit::visit_impl_item_fn(self, item);
    }
}

/// Analyse un fichier source Rust individuel
fn analyze_file(path: &Path) -> Result<Vec<FunctionMetrics>> {
    let content = fs::read_to_string(path)
        .with_context(|| format!("Impossible de lire le fichier: {}", path.display()))?;

    let ast: File = syn::parse_file(&content)
        .with_context(|| format!("Échec du parsing Rust pour: {}", path.display()))?;

    let mut extractor = FunctionExtractor::new(path);
    extractor.visit_file(&ast);

    Ok(extractor.metrics)
}

/// Collecte récursivement tous les fichiers `.rs`
fn collect_rust_files(root: &Path) -> Vec<PathBuf> {
    if root.is_file() {
        if root.extension().and_then(|e| e.to_str()) == Some("rs") {
            return vec![root.to_path_buf()];
        }
        return Vec::new();
    }

    WalkDir::new(root)
        .into_iter()
        .filter_map(|entry| entry.ok())
        .map(|entry| entry.into_path())
        .filter(|path| path.is_file() && path.extension().and_then(|e| e.to_str()) == Some("rs"))
        .collect()
}

fn main() -> ExitCode {
    let args = Cli::parse();

    let files = collect_rust_files(&args.path);
    if files.is_empty() {
        eprintln!(
            "{}",
            format!("Aucun fichier .rs trouvé dans '{}'", args.path.display()).yellow()
        );
        return ExitCode::SUCCESS;
    }

    let mut all_metrics = Vec::new();
    let mut parse_errors = 0usize;

    for file in &files {
        match analyze_file(file) {
            Ok(metrics) => all_metrics.extend(metrics),
            Err(err) => {
                eprintln!("{}: {}", "Erreur".red().bold(), err);
                parse_errors += 1;
            }
        }
    }

    // Tri par complexité décroissante
    all_metrics.sort_by(|a, b| b.complexity.cmp(&a.complexity));

    println!(
        "\n{:<45} {:<8} {:<10} {}",
        "FONCTION / MÉTHODE".bold(),
        "LIGNE".bold(),
        "COMPLEXITÉ".bold(),
        "FICHIER".bold()
    );
    println!("{}", "-".repeat(95));

    let mut threshold_exceeded_count = 0usize;

    for metric in &all_metrics {
        let is_warning = metric.complexity > args.threshold;
        if is_warning {
            threshold_exceeded_count += 1;
        }

        if args.only_warnings && !is_warning {
            continue;
        }

        let complexity_str = if metric.complexity <= 5 {
            format!("{:<10}", metric.complexity).green()
        } else if metric.complexity <= args.threshold {
            format!("{:<10}", metric.complexity).yellow()
        } else {
            format!("{:<10}", metric.complexity).red().bold()
        };

        println!(
            "{:<45} {:<8} {} {}",
            metric.name.cyan(),
            metric.line,
            complexity_str,
            metric.file_path.display()
        );
    }

    println!("{}", "-".repeat(95));
    println!(
        "Total analysé : {} fonction(s) dans {} fichier(s).",
        all_metrics.len(),
        files.len()
    );

    if threshold_exceeded_count > 0 {
        eprintln!(
            "{}",
            format!(
                "Attention : {} fonction(s) dépassent le seuil de complexité ({}).",
                threshold_exceeded_count, args.threshold
            )
            .red()
            .bold()
        );

        if args.fail_on_threshold {
            return ExitCode::FAILURE;
        }
    } else {
        println!(
            "{}",
            format!(
                "Toutes les fonctions respectent le seuil de complexité (<= {}).",
                args.threshold
            )
            .green()
        );
    }

    if parse_errors > 0 {
        ExitCode::FAILURE
    } else {
        ExitCode::SUCCESS
    }
}

