    #[test]
    fn test_simple_function() {
        let code = "fn simple() { println!(\"Hello\"); }";
        let ast = syn::parse_file(code).expect("Parsing valide");
        let mut extractor = FunctionExtractor::new(Path::new("test.rs"));
        extractor.visit_file(&ast);

        assert_eq!(extractor.metrics.len(), 1);
        assert_eq!(extractor.metrics[0].complexity, 1);
    }

    #[test]
    fn test_branches_and_loops() {
        let code = r#"
        fn complex_fn(x: i32) -> Result<i32, ()> {
            if x > 10 && x < 20 {
                for i in 0..x {
                    while i > 2 {
                        let _ = x?;
                    }
                }
            } else if x == 0 {
                loop { break; }
            }
            Ok(x)
        }
        "#;
        let ast = syn::parse_file(code).expect("Parsing valide");
        let mut extractor = FunctionExtractor::new(Path::new("test.rs"));
        extractor.visit_file(&ast);

        assert_eq!(extractor.metrics.len(), 1);
        // Base: 1
        // if x > 10 (+1)
        // && x < 20 (+1)
        // for (+1)
        // while (+1)
        // ? (+1)
        // else if (+1)
        // loop (+1)
        // Total = 1 + 7 = 8
        assert_eq!(extractor.metrics[0].complexity, 8);
    }

    #[test]
    fn test_match_arms() {
        let code = r#"
        fn test_match(x: i32) {
            match x {
                1 => {},
                2 if true => {},
                _ => {},
            }
        }
        "#;
        let ast = syn::parse_file(code).expect("Parsing valide");
        let mut extractor = FunctionExtractor::new(Path::new("test.rs"));
        extractor.visit_file(&ast);

        assert_eq!(extractor.metrics.len(), 1);
        // Base: 1
        // 3 bras => 3 - 1 = +2
        // 1 garde `if true` => +1
        // Total = 1 + 2 + 1 = 4
        assert_eq!(extractor.metrics[0].complexity, 4);
    }
}

