// src/main.rs
use std::collections::HashMap;
use std::fmt;
use std::path::{Path, PathBuf};
use std::process::Stdio;
use std::sync::Arc;
use std::time::Duration;

use anyhow::{Context, Result};
use clap::{Parser, Subcommand};
use colored::Colorize;
use comfy_table::{modifiers::UTF8_ROUND_CORNERS, Table};
use serde::{Deserialize, Serialize};
use tokio::process::Command;
use tokio::sync::Mutex;
use tracing::{error, info, warn};

/// État d'exécution d'un service supervisé
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum ServiceStatus {
    Running,
    Stopped,
    Failed,
    Unknown,
}

impl fmt::Display for ServiceStatus {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ServiceStatus::Running => write!(f, "{}", "RUNNING".green().bold()),
            ServiceStatus::Stopped => write!(f, "{}", "STOPPED".yellow().bold()),
            ServiceStatus::Failed => write!(f, "{}", "FAILED".red().bold()),
            ServiceStatus::Unknown => write!(f, "{}", "UNKNOWN".dimmed()),
        }
    }
}

/// Type de fournisseur de supervision
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum ProviderKind {
    /// Utilise systemctl (`systemctl is-active <nom>`)
    Systemd,
    /// Utilise des commandes shell personnalisées
    Custom {
        status_cmd: String,
        restart_cmd: String,
    },
}

impl Default for ProviderKind {
    fn default() -> Self {
        ProviderKind::Systemd
    }
}

/// Définition d'un service à superviser
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ServiceConfig {
    pub name: String,
    #[serde(default)]
    pub provider: ProviderKind,
    #[serde(default = "default_auto_restart")]
    pub auto_restart: bool,
    #[serde(default = "default_max_retries")]
    pub max_retries: u32,
}

fn default_auto_restart() -> bool {
    true
}

fn default_max_retries() -> u32 {
    3
}

/// Configuration globale du superviseur
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AppConfig {
    #[serde(default = "default_check_interval")]
    pub check_interval_secs: u64,
    pub services: Vec<ServiceConfig>,
}

fn default_check_interval() -> u64 {
    10
}

impl Default for AppConfig {
    fn default() -> Self {
        Self {
            check_interval_secs: 10,
            services: vec![
                ServiceConfig {
                    name: "cron".to_string(),
                    provider: ProviderKind::Systemd,
                    auto_restart: true,
                    max_retries: 3,
                },
                ServiceConfig {
                    name: "ssh".to_string(),
                    provider: ProviderKind::Systemd,
                    auto_restart: true,
                    max_retries: 3,
                },
            ],
        }
    }
}

/// Gestionnaire d'exécution des services
pub struct Supervisor {
    config: AppConfig,
    retry_counters: Arc<Mutex<HashMap<String, u32>>>,
}

impl Supervisor {
    pub fn new(config: AppConfig) -> Self {
        Self {
            config,
            retry_counters: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    /// Charge ou initialise un fichier de configuration
    pub async fn load_or_create_config(path: &Path) -> Result<AppConfig> {
        if path.exists() {
            let content = tokio::fs::read_to_string(path)
                .await
                .with_context(|| format!("Impossible de lire le fichier {:?}", path))?;
            let config: AppConfig = serde_yaml::from_str(&content)
                .with_context(|| format!("Format YAML invalide dans {:?}", path))?;
            Ok(config)
        } else {
            let default_config = AppConfig::default();
            let yaml_str = serde_yaml::to_string(&default_config)
                .context("Impossible de sérialiser la configuration par défaut")?;
            if let Some(parent) = path.parent() {
                if !parent.as_os_str().is_empty() {
                    tokio::fs::create_dir_all(parent).await?;
                }
            }
            tokio::fs::write(path, yaml_str)
                .await
                .with_context(|| format!("Échec de création du fichier {:?}", path))?;
            info!("Fichier de configuration créé avec succès : {:?}", path);
            Ok(default_config)
        }
    }

    /// Vérifie l'état d'un service
    pub async fn check_service(service: &ServiceConfig) -> ServiceStatus {
        match &service.provider {
            ProviderKind::Systemd => {
                let output = Command::new("systemctl")
                    .arg("is-active")
                    .arg(&service.name)
                    .stdout(Stdio::piped())
                    .stderr(Stdio::null())
                    .output()
                    .await;

                match output {
                    Ok(out) => {
                        let status_str = String::from_utf8_lossy(&out.stdout).trim().to_lowercase();
                        match status_str.as_str() {
                            "active" => ServiceStatus::Running,
                            "inactive" => ServiceStatus::Stopped,
                            "failed" => ServiceStatus::Failed,
                            _ => {
                                if out.status.success() {
                                    ServiceStatus::Running
                                } else {
                                    ServiceStatus::Stopped
                                }
                            }
                        }
                    }
                    Err(e) => {
                        warn!("Erreur lors de l'appel à systemctl pour {}: {}", service.name, e);
                        ServiceStatus::Unknown
                    }
                }
            }
            ProviderKind::Custom { status_cmd, .. } => {
                let output = Command::new("sh")
                    .arg("-c")
                    .arg(status_cmd)
                    .stdout(Stdio::null())
                    .stderr(Stdio::null())
                    .status()
                    .await;

                match output {
                    Ok(exit_status) => {
                        if exit_status.success() {
                            ServiceStatus::Running
                        } else {
                            ServiceStatus::Stopped
                        }
                    }
                    Err(e) => {
                        warn!("Erreur lors du check custom pour {}: {}", service.name, e);
                        ServiceStatus::Unknown
                    }
                }
            }
        }
    }

    /// Redémarre un service
    pub async fn restart_service(service: &ServiceConfig) -> Result<()> {
        info!("Tentative de redémarrage pour le service '{}'...", service.name);
        match &service.provider {
            ProviderKind::Systemd => {
                let status = Command::new("systemctl")
                    .arg("restart")
                    .arg(&service.name)
                    .status()
                    .await
                    .with_context(|| format!("Échec du lancement de systemctl pour {}", service.name))?;

                if status.success() {
                    info!("Service '{}' redémarré avec succès.", service.name);
                    Ok(())
                } else {
                    anyhow::bail!("systemctl restart a échoué avec le code {:?}", status.code());
                }
            }
            ProviderKind::Custom { restart_cmd, .. } => {
                let status = Command::new("sh")
                    .arg("-c")
                    .arg(restart_cmd)
                    .status()
                    .await
                    .with_context(|| format!("Échec du lancement de la commande pour {}", service.name))?;

                if status.success() {
                    info!("Commande personnalisée exécutée avec succès pour '{}'.", service.name);
                    Ok(())
                } else {
                    anyhow::bail!("La commande de redémarrage a échoué avec le code {:?}", status.code());
                }
            }
        }
    }

    /// Affiche un instantané d'état de tous les services
    pub async fn show_status(&self) -> Result<()> {
        let mut table = Table::new();
        table.apply_modifier(UTF8_ROUND_CORNERS);
        table.set_header(vec!["Service", "Fournisseur", "Auto-Restart", "État"]);

        for s in &self.config.services {
            let status = Self::check_service(s).await;
            let provider_label = match &s.provider {
                ProviderKind::Systemd => "systemd",
                ProviderKind::Custom { .. } => "custom",
            };
            let auto_label = if s.auto_restart {
                "Oui".green()
            } else {
                "Non".yellow()
            };
            table.add_row(vec![
                s.name.clone().bold().to_string(),
                provider_label.to_string(),
                auto_label.to_string(),
                status.to_string(),
            ]);
        }

        println!("\n{}\n", table);
        Ok(())
    }

    /// Cycle de vérification et redémarrage automatique
    pub async fn run_check_cycle(&self, auto_restart: bool) -> Result<bool> {
        let mut all_healthy = true;
        let mut counters = self.retry_counters.lock().await;

        for s in &self.config.services {
            let status = Self::check_service(s).await;
            match status {
                ServiceStatus::Running => {
                    // Réinitialisation du compteur de retry si le service est opérationnel
                    counters.insert(s.name.clone(), 0);
                }
                ServiceStatus::Stopped | ServiceStatus::Failed => {
                    all_healthy = false;
                    warn!(
                        "Le service '{}' est dans un état anormal ({}) !",
                        s.name, status
                    );

                    if auto_restart && s.auto_restart {
                        let retries = counters.entry(s.name.clone()).or_insert(0);
                        if *retries < s.max_retries {
                            *retries += 1;
                            warn!(
                                "Tentative {}/{} de redémarrage pour '{}'...",
                                *retries, s.max_retries, s.name
                            );
                            if let Err(e) = Self::restart_service(s).await {
                                error!("Impossible de redémarrer '{}' : {}", s.name, e);
                            } else {
                                // Petite temporisation de stabilisation
                                tokio::time::sleep(Duration::from_millis(500)).await;
                                let new_status = Self::check_service(s).await;
                                if new_status == ServiceStatus::Running {
                                    info!("Le service '{}' est de nouveau opérationnel.", s.name);
                                    *retries = 0;
                                } else {
                                    warn!("Le service '{}' est toujours {}", s.name, new_status);
                                }
                            }
                        } else {
                            error!(
                                "Nombre maximum de tentatives ({}) atteint pour '{}'. Abandon.",
                                s.max_retries, s.name
                            );
                        }
                    }
                }
                ServiceStatus::Unknown => {
                    warn!("État indéterminé pour le service '{}'.", s.name);
                }
            }
        }

        Ok(all_healthy)
    }

    /// Boucle de surveillance continue
    pub async fn watch(&self, interval: Duration, auto_restart: bool) -> Result<()> {
        info!(
            "Démarrage de la boucle de supervision (intervalle: {:?}, auto_restart: {})...",
            interval, auto_restart
        );
        println!(
            "{}",
            "Appuyez sur Ctrl+C pour arrêter le superviseur.".dimmed()
        );

        loop {
            tokio::select! {
                _ = tokio::signal::ctrl_c() => {
                    info!("Signal d'interruption reçu. Arrêt du superviseur.");
                    break;
                }
                _ = tokio::time::sleep(interval) => {
                    if let Err(e) = self.run_check_cycle(auto_restart).await {
                        error!("Erreur durant le cycle de supervision : {}", e);
                    }
                }
            }
        }

        Ok(())
    }
}

/// Interface CLI avec Clap
#[derive(Parser, Debug)]
#[command(
    name = "syswatch",
    version,
    about = "CLI de supervision de services système locaux avec auto-redémarrage",
    long_about = None
)]
pub struct Cli {
    /// Chemin vers le fichier de configuration (YAML)
    #[arg(short, long, default_value = "syswatch.yaml")]
    config: PathBuf,

    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
pub enum Commands {
    /// Affiche l'état instantané de tous les services supervisés
    Status,
    /// Effectue une vérification ponctuelle avec option de redémarrage
    Check {
        /// Active le redémarrage automatique en cas de service inactif/défaillant
        #[arg(long, default_value_t = false)]
        auto_restart: bool,
    },
    /// Lance la boucle de surveillance périodique
    Watch {
        /// Intervalle en secondes entre deux vérifications (écrase la configuration)
        #[arg(short, long)]
        interval: Option<u64>,
        /// Désactive l'auto-redémarrage pendant la surveillance
        #[arg(long, default_value_t = false)]
        no_restart: bool,
    },
    /// Déclenche le redémarrage manuel d'un service
    Restart {
        /// Nom du service à redémarrer
        service: String,
    },
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    let cli = Cli::parse();
    let config = Supervisor::load_or_create_config(&cli.config).await?;
    let supervisor = Supervisor::new(config);

    match cli.command {
        Commands::Status => {
            supervisor.show_status().await?;
        }
        Commands::Check { auto_restart } => {
            let ok = supervisor.run_check_cycle(auto_restart).await?;
            if !ok {
                std::process::exit(1);
            }
        }
        Commands::Watch { interval, no_restart } => {
            let interval_secs = interval.unwrap_or(supervisor.config.check_interval_secs);
            supervisor
                .watch(Duration::from_secs(interval_secs), !no_restart)
                .await?;
        }
        Commands::Restart { service } => {
            let service_entry = supervisor
                .config
                .services
                .iter()
                .find(|s| s.name == service);

            match service_entry {
                Some(entry) => {
                    Supervisor::restart_service(entry).await?;
                }
                None => {
                    // Fallback par défaut sur systemd si non présent explicitement dans le fichier
                    let default_service = ServiceConfig {
                        name: service.clone(),
                        provider: ProviderKind::Systemd,
                        auto_restart: true,
                        max_retries: 1,
                    };
                    info!(
                        "Service '{}' non répertorié dans la config, utilisation du provider systemd par défaut.",
                        service
                    );
                    Supervisor::restart_service(&default_service).await?;
                }
            }
        }
    }

    Ok(())
}

