                }
                ServiceStatus::Stopped | ServiceStatus::Failed => {
                    all_healthy = false;
                    warn!(
                        "Le service '{}' est dans un état anormal ({}) !",
                        s.name, status
                    );

                    if auto_restart && s.auto_restart {
                        let retries = counters.entry(s.name.clone()).or_insert(0);
                        if *retries < s.max_retries {
                            *retries += 1;
                            warn!(
                                "Tentative {}/{} de redémarrage pour '{}'...",
                                *retries, s.max_retries, s.name
                            );
                            if let Err(e) = Self::restart_service(s).await {
                                error!("Impossible de redémarrer '{}' : {}", s.name, e);
                            } else {
                                // Petite temporisation de stabilisation
                                tokio::time::sleep(Duration::from_millis(500)).await;
                                let new_status = Self::check_service(s).await;
                                if new_status == ServiceStatus::Running {
                                    info!("Le service '{}' est de nouveau opérationnel.", s.name);
                                    *retries = 0;
                                } else {
                                    warn!("Le service '{}' est toujours {}", s.name, new_status);
                                }
                            }
                        } else {
                            error!(
                                "Nombre maximum de tentatives ({}) atteint pour '{}'. Abandon.",
                                s.max_retries, s.name
                            );
                        }
                    }
                }
                ServiceStatus::Unknown => {
                    warn!("État indéterminé pour le service '{}'.", s.name);
                }
            }
        }

        Ok(all_healthy)
    }

    /// Boucle de surveillance continue
    pub async fn watch(&self, interval: Duration, auto_restart: bool) -> Result<()> {
        info!(
            "Démarrage de la boucle de supervision (intervalle: {:?}, auto_restart: {})...",
            interval, auto_restart
        );
        println!(
            "{}",
            "Appuyez sur Ctrl+C pour arrêter le superviseur.".dimmed()
        );

        loop {
            tokio::select! {
                _ = tokio::signal::ctrl_c() => {
                    info!("Signal d'interruption reçu. Arrêt du superviseur.");
                    break;
                }
                _ = tokio::time::sleep(interval) => {
                    if let Err(e) = self.run_check_cycle(auto_restart).await {
                        error!("Erreur durant le cycle de supervision : {}", e);
                    }
                }
            }
        }

        Ok(())
    }
}

/// Interface CLI avec Clap
#[derive(Parser, Debug)]
#[command(
    name = "syswatch",
    version,
    about = "CLI de supervision de services système locaux avec auto-redémarrage",
    long_about = None
)]
pub struct Cli {
    /// Chemin vers le fichier de configuration (YAML)
    #[arg(short, long, default_value = "syswatch.yaml")]
    config: PathBuf,

    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
pub enum Commands {
    /// Affiche l'état instantané de tous les services supervisés
    Status,
    /// Effectue une vérification ponctuelle avec option de redémarrage
    Check {
        /// Active le redémarrage automatique en cas de service inactif/défaillant
        #[arg(long, default_value_t = false)]
        auto_restart: bool,
    },
    /// Lance la boucle de surveillance périodique
    Watch {
        /// Intervalle en secondes entre deux vérifications (écrase la configuration)
        #[arg(short, long)]
        interval: Option<u64>,
        /// Désactive l'auto-redémarrage pendant la surveillance
        #[arg(long, default_value_t = false)]
        no_restart: bool,
    },
    /// Déclenche le redémarrage manuel d'un service
    Restart {
        /// Nom du service à redémarrer
        service: String,
    },
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    let cli = Cli::parse();
    let config = Supervisor::load_or_create_config(&cli.config).await?;
    let supervisor = Supervisor::new(config);

    match cli.command {
        Commands::Status => {
            supervisor.show_status().await?;
        }
        Commands::Check { auto_restart } => {
            let ok = supervisor.run_check_cycle(auto_restart).await?;
            if !ok {
                std::process::exit(1);
            }
        }
        Commands::Watch { interval, no_restart } => {
            let interval_secs = interval.unwrap_or(supervisor.config.check_interval_secs);
            supervisor
                .watch(Duration::from_secs(interval_secs), !no_restart)
                .await?;
        }
        Commands::Restart { service } => {
            let service_entry = supervisor
                .config
                .services
                .iter()
                .find(|s| s.name == service);

            match service_entry {
                Some(entry) => {
                    Supervisor::restart_service(entry).await?;
                }
                None => {
                    // Fallback par défaut sur systemd si non présent explicitement dans le fichier
                    let default_service = ServiceConfig {
                        name: service.clone(),
                        provider: ProviderKind::Systemd,
                        auto_restart: true,
                        max_retries: 1,
                    };
                    info!(
                        "Service '{}' non répertorié dans la config, utilisation du provider systemd par défaut.",
                        service
                    );
                    Supervisor::restart_service(&default_service).await?;
                }
            }
        }
    }

    Ok(())
}

