// src/main.rs
use std::io::{self, Read};
use clap::Parser;
use serde_json::Value;
use thiserror::Error;

/// Erreurs possibles pendant l'analyse lexicale, syntaxique ou l'évaluation.
#[derive(Debug, Error)]
pub enum QueryError {
    #[error("Erreur de syntaxe à la position {pos}: {message}")]
    SyntaxError { pos: usize, message: String },

    #[error("Erreur d'exécution: {0}")]
    ExecutionError(String),

    #[error("Erreur I/O: {0}")]
    IoError(#[from] io::Error),

    #[error("Erreur JSON: {0}")]
    JsonError(#[from] serde_json::Error),
}

/// Tokens reconnus par le lexer.
#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    Dot,                // .
    Pipe,               // |
    OpenBracket,        // [
    CloseBracket,       // ]
    OpenParen,          // (
    CloseParen,         // )
    Comma,              // ,
    Equal,              // ==
    NotEqual,           // !=
    GreaterThan,        // >
    GreaterThanOrEqual, // >=
    LessThan,           // <
    LessThanOrEqual,    // <=
    Select,             // select
    Ident(String),      // nom_champ
    StringLiteral(String), // "valeur"
    NumberLiteral(f64),    // 123, -4
    BoolLiteral(bool),     // true, false
    NullLiteral,           // null
}

#[derive(Debug, Clone)]
pub struct SpannedToken {
    pub token: Token,
    pub pos: usize,
}

/// Lexer / Tokenizer pour le langage de requêtes.
pub struct Lexer {
    chars: Vec<(usize, char)>,
    idx: usize,
}

impl Lexer {
    pub fn new(input: &str) -> Self {
        Self {
            chars: input.char_indices().collect(),
            idx: 0,
        }
    }

    fn peek(&self) -> Option<(usize, char)> {
        self.chars.get(self.idx).copied()
    }

    fn advance(&mut self) -> Option<(usize, char)> {
        let current = self.peek();
        if current.is_some() {
            self.idx += 1;
        }
        current
    }

    fn skip_whitespace(&mut self) {
        while let Some((_, ch)) = self.peek() {
            if ch.is_whitespace() {
                self.advance();
            } else {
                break;
            }
        }
    }

    pub fn tokenize(&mut self) -> Result<Vec<SpannedToken>, QueryError> {
        let mut tokens = Vec::new();

        while let Some((pos, ch)) = self.peek() {
            if ch.is_whitespace() {
                self.skip_whitespace();
                continue;
            }

            match ch {
                '.' => {
                    self.advance();
                    tokens.push(SpannedToken { token: Token::Dot, pos });
                }
                '|' => {
                    self.advance();
                    tokens.push(SpannedToken { token: Token::Pipe, pos });
                }
                '[' => {
                    self.advance();
                    tokens.push(SpannedToken { token: Token::OpenBracket, pos });
                }
                ']' => {
                    self.advance();
                    tokens.push(SpannedToken { token: Token::CloseBracket, pos });
                }
                '(' => {
                    self.advance();
                    tokens.push(SpannedToken { token: Token::OpenParen, pos });
                }
                ')' => {
                    self.advance();
                    tokens.push(SpannedToken { token: Token::CloseParen, pos });
                }
                ',' => {
                    self.advance();
                    tokens.push(SpannedToken { token: Token::Comma, pos });
                }
                '=' => {
                    self.advance();
                    if let Some((_, '=')) = self.peek() {
                        self.advance();
                        tokens.push(SpannedToken { token: Token::Equal, pos });
                    } else {
                        return Err(QueryError::SyntaxError {
                            pos,
                            message: "Symbole '=' inattendu. Attendiez-vous '==' ?".to_string(),
                        });
                    }
                }
                '!' => {
                    self.advance();
                    if let Some((_, '=')) = self.peek() {
                        self.advance();
                        tokens.push(SpannedToken { token: Token::NotEqual, pos });
                    } else {
                        return Err(QueryError::SyntaxError {
                            pos,
                            message: "Symbole '!' inattendu. Attendiez-vous '!=' ?".to_string(),
                        });
                    }
                }
                '>' => {
                    self.advance();
                    if let Some((_, '=')) = self.peek() {
                        self.advance();
                        tokens.push(SpannedToken { token: Token::GreaterThanOrEqual, pos });
                    } else {
                        tokens.push(SpannedToken { token: Token::GreaterThan, pos });
                    }
                }
                '<' => {
                    self.advance();
                    if let Some((_, '=')) = self.peek() {
                        self.advance();
                        tokens.push(SpannedToken { token: Token::LessThanOrEqual, pos });
                    } else {
                        tokens.push(SpannedToken { token: Token::LessThan, pos });
                    }
                }
                '"' => {
                    let str_literal = self.read_string(pos)?;
                    tokens.push(SpannedToken {
                        token: Token::StringLiteral(str_literal),
                        pos,
                    });
                }
                '-' | '0'..='9' => {
                    let num = self.read_number(pos)?;
                    tokens.push(SpannedToken {
                        token: Token::NumberLiteral(num),
                        pos,
                    });
                }
                ch if ch.is_alphabetic() || ch == '_' => {
                    let ident = self.read_identifier();
                    let tok = match ident.as_str() {
                        "select" => Token::Select,
                        "true" => Token::BoolLiteral(true),
                        "false" => Token::BoolLiteral(false),
                        "null" => Token::NullLiteral,
                        _ => Token::Ident(ident),
                    };
                    tokens.push(SpannedToken { token: tok, pos });
                }
                other => {
                    return Err(QueryError::SyntaxError {
                        pos,
                        message: format!("Caractère non reconnu '{}'", other),
                    });
                }
            }
        }

        Ok(tokens)
    }

    fn read_string(&mut self, start_pos: usize) -> Result<String, QueryError> {
        self.advance(); // Consomme les guillemets ouvrants
        let mut result = String::new();
        let mut escaped = false;

        while let Some((pos, ch)) = self.advance() {
            if escaped {
                match ch {
                    'n' => result.push('\n'),
                    't' => result.push('\t'),
                    'r' => result.push('\r'),
                    '\\' => result.push('\\'),
                    '"' => result.push('"'),
                    other => {
                        return Err(QueryError::SyntaxError {
                            pos,
                            message: format!("Séquence d'échappement non supportée '\\{}'", other),
                        });
                    }
                }
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '"' {
                return Ok(result);
            } else {
                result.push(ch);
            }
        }

        Err(QueryError::SyntaxError {
            pos: start_pos,
            message: "Chaîne de caractères non terminée (guillemet manquant)".to_string(),
        })
    }

    fn read_number(&mut self, start_pos: usize) -> Result<f64, QueryError> {
        let mut num_str = String::new();
        if let Some((_, '-')) = self.peek() {
            num_str.push('-');
            self.advance();
        }

        let mut has_digits = false;
        let mut has_dot = false;

        while let Some((_, ch)) = self.peek() {
            if ch.is_ascii_digit() {
                num_str.push(ch);
                has_digits = true;
                self.advance();
            } else if ch == '.' && !has_dot {
                // Vérifie si le point est suivi d'un chiffre pour éviter de consommer un accesseur '.field'
                if let Some((_, next_ch)) = self.chars.get(self.idx + 1) {
                    if next_ch.is_ascii_digit() {
                        num_str.push('.');
                        has_dot = true;
                        self.advance();
                        continue;
                    }
                }
                break;
            } else {
                break;
            }
        }

        if !has_digits {
            return Err(QueryError::SyntaxError {
                pos: start_pos,
                message: "Format de nombre invalide".to_string(),
            });
        }

        num_str.parse::<f64>().map_err(|e| QueryError::SyntaxError {
            pos: start_pos,
            message: format!("Impossible d'analyser le nombre '{}': {}", num_str, e),
        })
    }

    fn read_identifier(&mut self) -> String {
        let mut ident = String::new();
        while let Some((_, ch)) = self.peek() {
            if ch.is_alphanumeric() || ch == '_' {
                ident.push(ch);
                self.advance();
            } else {
                break;
            }
        }
        ident
    }
}

/// Opérateurs binaires de comparaison.
#[derive(Debug, Clone, PartialEq)]
pub enum BinaryOp {
    Equal,
    NotEqual,
    GreaterThan,
    GreaterThanOrEqual,
    LessThan,
    LessThanOrEqual,
}

/// Éléments d'accès dans un chemin JSON.
#[derive(Debug, Clone, PartialEq)]
pub enum PathSegment {
    /// Accès par nom de champ: `.nom` ou `."nom avec espace"`
    Field(String),
    /// Indexation directe: `[0]`, `[-1]`
    Index(i64),
    /// Itération sur tous les éléments: `[]`
    Iterate,
}

/// Expression de l'AST de requête.
#[derive(Debug, Clone, PartialEq)]
pub enum Expr {
    /// Identité : `.`
    Identity,
    /// Chemin composé d'un ou plusieurs segments : `.field`, `.[0]`, `.field[]`
    Path(Vec<PathSegment>),
    /// Pipeline : `expr1 | expr2`
    Pipe(Box<Expr>, Box<Expr>),
    /// Filtrage conditionnel : `select(condition)`
    Select(Box<ConditionExpr>),
}

/// Conditions évaluables dans `select(...)`.
#[derive(Debug, Clone, PartialEq)]
pub enum ConditionExpr {
    /// Test de véracité sur une sous-expression
    Truthy(Expr),
    /// Comparaison binaire : `expr op valeur/expr`
    Comparison {
        left: Box<Expr>,
        op: BinaryOp,
        right: Box<ValueExpr>,
    },
}

/// Valeur ou expression en membre droit d'une comparaison.
#[derive(Debug, Clone, PartialEq)]
pub enum ValueExpr {
    Literal(Value),
    SubExpr(Expr),
}

/// Parser syntaxique à descente récursive.
pub struct ParserState {
    tokens: Vec<SpannedToken>,
    cursor: usize,
}

impl ParserState {
    pub fn new(tokens: Vec<SpannedToken>) -> Self {
        Self { tokens, cursor: 0 }
    }

    fn peek(&self) -> Option<&SpannedToken> {
        self.tokens.get(self.cursor)
    }

    fn advance(&mut self) -> Option<&SpannedToken> {
        let cur = self.tokens.get(self.cursor);
        if cur.is_some() {
            self.cursor += 1;
        }
        cur
    }

    fn current_pos(&self) -> usize {
        self.peek().map(|t| t.pos).unwrap_or_else(|| {
            self.tokens.last().map(|t| t.pos + 1).unwrap_or(0)
        })
    }

    pub fn parse_query(&mut self) -> Result<Expr, QueryError> {
        let left = self.parse_single_expr()?;

        if let Some(SpannedToken { token: Token::Pipe, .. }) = self.peek() {
            self.advance(); // consomme '|'
            let right = self.parse_query()?;
            Ok(Expr::Pipe(Box::new(left), Box::new(right)))
        } else {
            Ok(left)
        }
    }

    fn parse_single_expr(&mut self) -> Result<Expr, QueryError> {
        let token_spanned = match self.peek() {
            Some(t) => t.clone(),
            None => {
                return Err(QueryError::SyntaxError {
                    pos: self.current_pos(),
                    message: "Expression inattendue : fin de flux atteinte".to_string(),
                });
            }
        };

        match &token_spanned.token {
            Token::Select => {
                self.advance();
                self.parse_select()
            }
            Token::Dot => {
                self.advance();
                self.parse_dot_expression(token_spanned.pos)
            }
            Token::OpenBracket => {
                self.parse_bracket_segments(Vec::new())
            }
            other => Err(QueryError::SyntaxError {
                pos: token_spanned.pos,
                message: format!("Expression invalide débutant par '{:?}'", other),
            }),
        }
    }

    fn parse_dot_expression(&mut self, dot_pos: usize) -> Result<Expr, QueryError> {
        let mut segments = Vec::new();

        // Vérifie si c'est seulement '.' sans segment suivant ou s'il y a un champ/index immédiat
        if let Some(tok) = self.peek() {
            match &tok.token {
                Token::Ident(name) => {
                    let field = name.clone();
                    self.advance();
                    segments.push(PathSegment::Field(field));
                }
                Token::StringLiteral(name) => {
                    let field = name.clone();
                    self.advance();
                    segments.push(PathSegment::Field(field));
                }
                Token::OpenBracket => {
                    // C'est de la forme .[...]
                }
                Token::Pipe | Token::CloseParen | Token::Comma => {
                    // Fin de l'expression identité
                    return Ok(Expr::Identity);
                }
                _ => {
                    return Err(QueryError::SyntaxError {
                        pos: tok.pos,
                        message: "Nom de champ ou crochet attendu après '.'".to_string(),
                    });
                }
            }
        } else {
            // Un simple '.'
            return Ok(Expr::Identity);
        }

        self.parse_chained_path_segments(segments, dot_pos)
    }

    fn parse_bracket_segments(&mut self, mut segments: Vec<PathSegment>) -> Result<Expr, QueryError> {
        let open_pos = self.current_pos();
        self.advance(); // Consomme '['

        match self.peek() {
            Some(SpannedToken { token: Token::CloseBracket, .. }) => {
                self.advance();
                segments.push(PathSegment::Iterate);
            }
            Some(SpannedToken { token: Token::NumberLiteral(n), .. }) => {
                let idx = *n as i64;
                self.advance();
                match self.peek() {
                    Some(SpannedToken { token: Token::CloseBracket, .. }) => {
                        self.advance();
                        segments.push(PathSegment::Index(idx));
                    }
                    _ => {
                        return Err(QueryError::SyntaxError {
                            pos: self.current_pos(),
                            message: "Crochet fermant ']' attendu après l'index numérique".to_string(),
                        });
                    }
                }
            }
            Some(SpannedToken { token: Token::StringLiteral(s), .. }) => {
                let field = s.clone();
                self.advance();
                match self.peek() {
                    Some(SpannedToken { token: Token::CloseBracket, .. }) => {
                        self.advance();
                        segments.push(PathSegment::Field(field));
                    }
                    _ => {
                        return Err(QueryError::SyntaxError {
                            pos: self.current_pos(),
                            message: "Crochet fermant ']' attendu après la clé de champ".to_string(),
                        });
                    }
                }
            }
            _ => {
                return Err(QueryError::SyntaxError {
                    pos: open_pos,
                    message: "Index ou crochet fermant ']' attendu dans '[]'".to_string(),
                });
            }
        }

        self.parse_chained_path_segments(segments, open_pos)
    }

    fn parse_chained_path_segments(
        &mut self,
        mut segments: Vec<PathSegment>,
        _start_pos: usize,
    ) -> Result<Expr, QueryError> {
        loop {
            match self.peek() {
                Some(SpannedToken { token: Token::Dot, .. }) => {
                    self.advance();
                    match self.peek() {
                        Some(SpannedToken { token: Token::Ident(name), .. }) => {
                            segments.push(PathSegment::Field(name.clone()));
                            self.advance();
                        }
                        Some(SpannedToken { token: Token::StringLiteral(name), .. }) => {
                            segments.push(PathSegment::Field(name.clone()));
                            self.advance();
                        }
                        Some(SpannedToken { token: Token::OpenBracket, .. }) => {
                            // Enchaîne avec .[index]
                            self.advance();
                            self.consume_bracket_interior(&mut segments)?;
                        }
                        _ => {
                            return Err(QueryError::SyntaxError {
                                pos: self.current_pos(),
                                message: "Champ attendu après le point '.'".to_string(),
                            });
                        }
                    }
                }
                Some(SpannedToken { token: Token::OpenBracket, .. }) => {
                    self.advance();
                    self.consume_bracket_interior(&mut segments)?;
                }
                _ => break,
            }
        }

        if segments.is_empty() {
            Ok(Expr::Identity)
        } else {
            Ok(Expr::Path(segments))
        }
    }

    fn consume_bracket_interior(&mut self, segments: &mut Vec<PathSegment>) -> Result<(), QueryError> {
        let pos = self.current_pos();
        match self.peek() {
            Some(SpannedToken { token: Token::CloseBracket, .. }) => {
                self.advance();
                segments.push(PathSegment::Iterate);
                Ok(())
            }
            Some(SpannedToken { token: Token::NumberLiteral(n), .. }) => {
                let idx = *n as i64;
                self.advance();
                match self.peek() {
                    Some(SpannedToken { token: Token::CloseBracket, .. }) => {
                        self.advance();
                        segments.push(PathSegment::Index(idx));
                        Ok(())
                    }
                    _ => Err(QueryError::SyntaxError {
                        pos: self.current_pos(),
                        message: "']' attendu après l'index".to_string(),
                    }),
                }
            }
            Some(SpannedToken { token: Token::StringLiteral(s), .. }) => {
                let field = s.clone();
                self.advance();
                match self.peek() {
                    Some(SpannedToken { token: Token::CloseBracket, .. }) => {
                        self.advance();
                        segments.push(PathSegment::Field(field));
                        Ok(())
                    }
                    _ => Err(QueryError::SyntaxError {
                        pos: self.current_pos(),
                        message: "']' attendu après la clé".to_string(),
                    }),
                }
            }
            _ => Err(QueryError::SyntaxError {
                pos,
                message: "Contenu de crochet inattendu".to_string(),
            }),
        }
    }

    fn parse_select(&mut self) -> Result<Expr, QueryError> {
        let pos = self.current_pos();
        match self.peek() {
            Some(SpannedToken { token: Token::OpenParen, .. }) => {
                self.advance();
            }
            _ => {
                return Err(QueryError::SyntaxError {
                    pos,
                    message: "'(' attendu après 'select'".to_string(),
                });
            }
        }

        let cond = self.parse_condition()?;

        match self.peek() {
            Some(SpannedToken { token: Token::CloseParen, .. }) => {
                self.advance();
                Ok(Expr::Select(Box::new(cond)))
            }
            _ => Err(QueryError::SyntaxError {
                pos: self.current_pos(),
                message: "')' attendu pour fermer l'appel à 'select'".to_string(),
            }),
        }
    }

    fn parse_condition(&mut self) -> Result<ConditionExpr, QueryError> {
        let left_expr = self.parse_query()?;

        if let Some(tok) = self.peek() {
            let op = match &tok.token {
                Token::Equal => Some(BinaryOp::Equal),
                Token::NotEqual => Some(BinaryOp::NotEqual),
                Token::GreaterThan => Some(BinaryOp::GreaterThan),
                Token::GreaterThanOrEqual => Some(BinaryOp::GreaterThanOrEqual),
                Token::LessThan => Some(BinaryOp::LessThan),
                Token::LessThanOrEqual => Some(BinaryOp::LessThanOrEqual),
                _ => None,
            };

            if let Some(bin_op) = op {
                self.advance();
                let right_val = self.parse_value_expr()?;
                return Ok(ConditionExpr::Comparison {
                    left: Box::new(left_expr),
                    op: bin_op,
                    right: Box::new(right_val),
                });
            }
        }

        Ok(ConditionExpr::Truthy(left_expr))
    }

    fn parse_value_expr(&mut self) -> Result<ValueExpr, QueryError> {
        let tok = match self.peek() {
            Some(t) => t.clone(),
            None => {
                return Err(QueryError::SyntaxError {
                    pos: self.current_pos(),
                    message: "Valeur attendue après l'opérateur de comparaison".to_string(),
                });
            }
        };

        match tok.token {
            Token::StringLiteral(s) => {
                self.advance();
                Ok(ValueExpr::Literal(Value::String(s)))
            }
            Token::NumberLiteral(n) => {
                self.advance();
                let num_val = if n.fract() == 0.0 && n >= i64::MIN as f64 && n <= i64::MAX as f64 {
                    serde_json::Number::from(n as i64)
                } else {
                    serde_json::Number::from_f64(n).unwrap_or(serde_json::Number::from(0))
                };
                Ok(ValueExpr::Literal(Value::Number(num_val)))
            }
            Token::BoolLiteral(b) => {
                self.advance();
                Ok(ValueExpr::Literal(Value::Bool(b)))
            }
            Token::NullLiteral => {
                self.advance();
                Ok(ValueExpr::Literal(Value::Null))
            }
            Token::Dot => {
                let expr = self.parse_query()?;
                Ok(ValueExpr::SubExpr(expr))
            }
            other => Err(QueryError::SyntaxError {
                pos: tok.pos,
                message: format!("Valeur littérale ou expression attendue, trouvé: {:?}", other),
            }),
        }
    }
}

/// Évaluateur de requêtes sur des valeurs JSON.
pub struct Evaluator;

impl Evaluator {
    pub fn evaluate(expr: &Expr, input: &Value) -> Result<Vec<Value>, QueryError> {
        match expr {
            Expr::Identity => Ok(vec![input.clone()]),
            Expr::Path(segments) => Self::eval_path(segments, input),
            Expr::Pipe(left, right) => {
                let intermediate_results = Self::evaluate(left, input)?;
                let mut final_results = Vec::new();
                for item in &intermediate_results {
                    let mut evaluated = Self::evaluate(right, item)?;
                    final_results.append(&mut evaluated);
                }
                Ok(final_results)
            }
            Expr::Select(condition) => {
                if Self::eval_condition(condition, input)? {
                    Ok(vec![input.clone()])
                } else {
                    Ok(Vec::new())
                }
            }
        }
    }

    fn eval_path(segments: &[PathSegment], input: &Value) -> Result<Vec<Value>, QueryError> {
        let mut current_items = vec![input.clone()];

        for segment in segments {
            let mut next_items = Vec::new();

            for item in &current_items {
                match segment {
                    PathSegment::Field(name) => {
                        if let Value::Object(map) = item {
                            if let Some(val) = map.get(name) {
                                next_items.push(val.clone());
                            } else {
                                next_items.push(Value::Null);
                            }
                        } else {
                            next_items.push(Value::Null);
                        }
                    }
                    PathSegment::Index(idx) => {
                        if let Value::Array(arr) = item {
                            let resolved_index = if *idx < 0 {
                                let len = arr.len() as i64;
                                let pos = len + *idx;
                                if pos >= 0 {
                                    Some(pos as usize)
                                } else {
                                    None
                                }
                            } else {
                                Some(*idx as usize)
                            };

                            if let Some(i) = resolved_index {
                                if let Some(val) = arr.get(i) {
                                    next_items.push(val.clone());
                                } else {
                                    next_items.push(Value::Null);
                                }
                            } else {
                                next_items.push(Value::Null);
                            }
                        } else {
                            next_items.push(Value::Null);
                        }
                    }
                    PathSegment::Iterate => match item {
                        Value::Array(arr) => {
                            for elem in arr {
                                next_items.push(elem.clone());
                            }
                        }
                        Value::Object(map) => {
                            for val in map.values() {
                                next_items.push(val.clone());
                            }
                        }
                        _ => {
                            // Ignoré pour les scalaires
                        }
                    },
                }
            }

            current_items = next_items;
        }

        Ok(current_items)
    }

    fn eval_condition(condition: &ConditionExpr, input: &Value) -> Result<bool, QueryError> {
        match condition {
            ConditionExpr::Truthy(expr) => {
                let results = Self::evaluate(expr, input)?;
                let is_truthy = results.into_iter().any(|v| match v {
                    Value::Null => false,
                    Value::Bool(b) => b,
                    _ => true,
                });
                Ok(is_truthy)
            }
            ConditionExpr::Comparison { left, op, right } => {
                let left_vals = Self::evaluate(left, input)?;
                let right_vals = match right.as_ref() {
                    ValueExpr::Literal(val) => vec![val.clone()],
                    ValueExpr::SubExpr(expr) => Self::evaluate(expr, input)?,
                };

                for l in &left_vals {
                    for r in &right_vals {
                        if Self::compare_values(l, op, r) {
                            return Ok(true);
                        }
                    }
                }

                Ok(false)
            }
        }
    }

    fn compare_values(left: &Value, op: &BinaryOp, right: &Value) -> bool {
        match op {
            BinaryOp::Equal => left == right,
            BinaryOp::NotEqual => left != right,
            BinaryOp::GreaterThan => Self::compare_numbers_or_strings(left, right, |cmp| cmp > 0),
            BinaryOp::GreaterThanOrEqual => Self::compare_numbers_or_strings(left, right, |cmp| cmp >= 0),
            BinaryOp::LessThan => Self::compare_numbers_or_strings(left, right, |cmp| cmp < 0),
            BinaryOp::LessThanOrEqual => Self::compare_numbers_or_strings(left, right, |cmp| cmp <= 0),
        }
    }

    fn compare_numbers_or_strings<F>(left: &Value, right: &Value, predicate: F) -> bool
    where
        F: FnOnce(i32) -> bool,
    {
        match (left, right) {
            (Value::Number(a), Value::Number(b)) => {
                if let (Some(fa), Some(fb)) = (a.as_f64(), b.as_f64()) {
                    let cmp = fa.partial_cmp(&fb);
                    match cmp {
                        Some(std::cmp::Ordering::Less) => predicate(-1),
                        Some(std::cmp::Ordering::Equal) => predicate(0),
                        Some(std::cmp::Ordering::Greater) => predicate(1),
                        None => false,
                    }
                } else {
                    false
                }
            }
            (Value::String(a), Value::String(b)) => {
                let cmp = a.cmp(b);
                match cmp {
                    std::cmp::Ordering::Less => predicate(-1),
                    std::cmp::Ordering::Equal => predicate(0),
                    std::cmp::Ordering::Greater => predicate(1),
                }
            }
            _ => false,
        }
    }
}

/// Parse et exécute une requête sur une chaîne JSON.
pub fn run_query(query_str: &str, json_str: &str) -> Result<Vec<Value>, QueryError> {
    let mut lexer = Lexer::new(query_str);
    let tokens = lexer.tokenize()?;

    let mut parser = ParserState::new(tokens);
    let ast = parser.parse_query()?;

    let input_value: Value = serde_json::from_str(json_str)?;
    Evaluator::evaluate(&ast, &input_value)
}

/// CLI parser avec clap
#[derive(Parser, Debug)]
#[command(
    name = "mini-jq",
    author = "Damien",
    version = "0.1.0",
    about = "Interpréteur de langage de requêtes de filtrage pour JSON imbriqué",
    long_about = "mini-jq permet d'extraire, filtrer et naviguer dans des structures JSON imbriquées avec une syntaxe proche de jq."
)]
struct Cli {
    /// Expression de requête de filtrage (ex: .items[0].name, .users[] | select(.active == true))
    #[arg(default_value = ".")]
    filter: String,

    /// Chaîne JSON en entrée (si non spécifié, stdin est lu)
    #[arg(short = 'j', long = "json")]
    json: Option<String>,

    /// Sortie au format compact (une ligne par résultat)
    #[arg(short = 'c', long = "compact")]
    compact: bool,
}

fn main() {
    let cli = Cli::parse();

    let json_input = match cli.json {
        Some(content) => content,
        None => {
            let mut buffer = String::new();
            if let Err(e) = io::stdin().read_to_string(&mut buffer) {
                eprintln!("Erreur lors de la lecture de stdin: {}", e);
                std::process::exit(1);
            }
            buffer
        }
    };

    if json_input.trim().is_empty() {
        eprintln!("Erreur : aucune donnée JSON reçue en entrée.");
        std::process::exit(1);
    }

    match run_query(&cli.filter, &json_input) {
        Ok(results) => {
            for val in results {
                let output = if cli.compact {
                    serde_json::to_string(&val)
                } else {
                    serde_json::to_string_pretty(&val)
                };

                match output {
                    Ok(rendered) => println!("{}", rendered),
                    Err(e) => {
                        eprintln!("Erreur lors de la sérialisation JSON: {}", e);
                        std::process::exit(1);
                    }
                }
            }
        }
        Err(e) => {
            eprintln!("Erreur: {}", e);
            std::process::exit(1);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_identity() {
        let json = r#"{"name": "Alice", "age": 30}"#;
        let res = run_query(".", json).expect("Failed query");
        assert_eq!(res.len(), 1);
        assert_eq!(res[0]["name"], "Alice");
    }

    #[test]
    fn test_nested_field() {
        let json = r#"{"user": {"profile": {"address": {"city": "Paris"}}}}"#;
        let res = run_query(".user.profile.address.city", json).expect("Failed query");
        assert_eq!(res.len(), 1);
        assert_eq!(res[0], "Paris");
    }

    #[test]
    fn test_array_indexing() {
        let json = r#"{"items": ["pomme", "banane", "orange"]}"#;
        let res = run_query(".items[1]", json).expect("Failed query");
        assert_eq!(res.len(), 1);
        assert_eq!(res[0], "banane");

        let res_last = run_query(".items[-1]", json).expect("Failed query");
        assert_eq!(res_last.len(), 1);
        assert_eq!(res_last[0], "orange");
    }

    #[test]
    fn test_array_iteration() {
        let json = r#"{"users": [{"id": 1}, {"id": 2}, {"id": 3}]}"#;
        let res = run_query(".users[] | .id", json).expect("Failed query");
        assert_eq!(res.len(), 3);
        assert_eq!(res[0], 1);
        assert_eq!(res[1], 2);
        assert_eq!(res[2], 3);
    }

    #[test]
    fn test_select_filtering() {
        let json = r#"[
            {"name": "Alice", "age": 25, "active": true},
            {"name": "Bob", "age": 17, "active": false},
            {"name": "Charlie", "age": 32, "active": true}
        ]"#;

        let res = run_query(".[] | select(.age >= 18) | .name", json).expect("Failed query");
        assert_eq!(res.len(), 2);
        assert_eq!(res[0], "Alice");
        assert_eq!(res[1], "Charlie");

        let res_active = run_query(".[] | select(.active == true) | .name", json).expect("Failed query");
        assert_eq!(res_active.len(), 2);
        assert_eq!(res_active[0], "Alice");
        assert_eq!(res_active[1], "Charlie");
    }

