        let json = r#"{"user-data": {"full name": "Damien"}}"#;
        let res = run_query(r#"."user-data"."full name""#, json).expect("Failed query");
        assert_eq!(res.len(), 1);
        assert_eq!(res[0], "Damien");
    }
