// src/main.rs
use std::collections::HashMap;
use std::fmt;
use thiserror::Error;

/// Erreurs lexicales, syntaxiques et d'évaluation du moteur.
#[derive(Debug, Error, PartialEq, Eq)]
pub enum EngineError {
    #[error("Caractère inattendu '{0}' à la position {1}")]
    UnexpectedCharacter(char, usize),

    #[error("Jeton inattendu '{found}' à la position {pos}, attendu: {expected}")]
    UnexpectedToken {
        expected: String,
        found: String,
        pos: usize,
    },

    #[error("Fin de saisie inattendue")]
    UnexpectedEof,

    #[error("Parenthèse fermante ')' manquante")]
    UnclosedParenthesis,

    #[error("Variable indéfinie dans le contexte : '{0}'")]
    UndefinedVariable(String),
}

/// Types de jetons produits par l'analyseur lexical (Lexer).
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum TokenKind {
    True,
    False,
    Ident(String),
    Not,
    And,
    Or,
    LParen,
    RParen,
    Eof,
}

impl fmt::Display for TokenKind {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            TokenKind::True => write!(f, "true"),
            TokenKind::False => write!(f, "false"),
            TokenKind::Ident(id) => write!(f, "identifiant('{id}')"),
            TokenKind::Not => write!(f, "NOT"),
            TokenKind::And => write!(f, "AND"),
            TokenKind::Or => write!(f, "OR"),
            TokenKind::LParen => write!(f, "("),
            TokenKind::RParen => write!(f, ")"),
            TokenKind::Eof => write!(f, "<EOF>"),
        }
    }
}

/// Jeton avec métadonnées de position pour les diagnostics.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Token {
    pub kind: TokenKind,
    pub pos: usize,
}

/// Analyseur lexical transformant une chaîne de caractères en flux de jetons.
pub struct Lexer<'a> {
    chars: Vec<(usize, char)>,
    index: usize,
    _marker: std::marker::PhantomData<&'a str>,
}

impl<'a> Lexer<'a> {
    pub fn new(input: &'a str) -> Self {
        Self {
            chars: input.char_indices().collect(),
            index: 0,
            _marker: std::marker::PhantomData,
        }
    }

    fn peek(&self) -> Option<(usize, char)> {
        self.chars.get(self.index).copied()
    }

    fn advance(&mut self) -> Option<(usize, char)> {
        let current = self.peek();
        if current.is_some() {
            self.index += 1;
        }
        current
    }

    pub fn tokenize(mut self) -> Result<Vec<Token>, EngineError> {
        let mut tokens = Vec::new();

        while let Some((pos, ch)) = self.peek() {
            match ch {
                c if c.is_whitespace() => {
                    self.advance();
                }
                '(' => {
                    self.advance();
                    tokens.push(Token {
                        kind: TokenKind::LParen,
                        pos,
                    });
                }
                ')' => {
                    self.advance();
                    tokens.push(Token {
                        kind: TokenKind::RParen,
                        pos,
                    });
                }
                '!' => {
                    self.advance();
                    tokens.push(Token {
                        kind: TokenKind::Not,
                        pos,
                    });
                }
                '&' => {
                    self.advance();
                    if let Some((_, '&')) = self.peek() {
                        self.advance();
                    }
                    tokens.push(Token {
                        kind: TokenKind::And,
                        pos,
                    });
                }
                '|' => {
                    self.advance();
                    if let Some((_, '|')) = self.peek() {
                        self.advance();
                    }
                    tokens.push(Token {
                        kind: TokenKind::Or,
                        pos,
                    });
                }
                '0' => {
                    self.advance();
                    tokens.push(Token {
                        kind: TokenKind::False,
                        pos,
                    });
                }
                '1' => {
                    self.advance();
                    tokens.push(Token {
                        kind: TokenKind::True,
                        pos,
                    });
                }
                c if c.is_alphabetic() || c == '_' => {
                    let start_pos = pos;
                    let mut ident = String::new();
                    while let Some((_, next_char)) = self.peek() {
                        if next_char.is_alphanumeric() || next_char == '_' {
                            ident.push(next_char);
                            self.advance();
                        } else {
                            break;
                        }
                    }

                    let kind = match ident.to_lowercase().as_str() {
                        "true" => TokenKind::True,
                        "false" => TokenKind::False,
                        "not" => TokenKind::Not,
                        "and" => TokenKind::And,
                        "or" => TokenKind::Or,
                        _ => TokenKind::Ident(ident),
                    };

                    tokens.push(Token {
                        kind,
                        pos: start_pos,
                    });
                }
                invalid => {
                    return Err(EngineError::UnexpectedCharacter(invalid, pos));
                }
            }
        }

        let eof_pos = self.chars.last().map(|(p, _)| *p + 1).unwrap_or(0);
        tokens.push(Token {
            kind: TokenKind::Eof,
            pos: eof_pos,
        });

        Ok(tokens)
    }
}

/// Arbre Syntaxique Abstrait (AST) pour les expressions logiques.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Expr {
    Literal(bool),
    Variable(String),
    Not(Box<Expr>),
    And(Box<Expr>, Box<Expr>),
    Or(Box<Expr>, Box<Expr>),
}

impl Expr {
    /// Évalue l'expression en utilisant les valeurs de variables fournies.
    /// Implémente le court-circuitage logique (short-circuit evaluation).
    pub fn eval(&self, context: &HashMap<String, bool>) -> Result<bool, EngineError> {
        match self {
            Expr::Literal(val) => Ok(*val),
            Expr::Variable(name) => context
                .get(name)
                .copied()
                .ok_or_else(|| EngineError::UndefinedVariable(name.clone())),
            Expr::Not(inner) => {
                let val = inner.eval(context)?;
                Ok(!val)
            }
            Expr::And(left, right) => {
                let left_val = left.eval(context)?;
                if !left_val {
                    Ok(false)
                } else {
                    right.eval(context)
                }
            }
            Expr::Or(left, right) => {
                let left_val = left.eval(context)?;
                if left_val {
                    Ok(true)
                } else {
                    right.eval(context)
                }
            }
        }
    }
}

impl fmt::Display for Expr {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Expr::Literal(val) => write!(f, "{val}"),
            Expr::Variable(var) => write!(f, "{var}"),
            Expr::Not(inner) => write!(f, "(NOT {inner})"),
            Expr::And(left, right) => write!(f, "({left} AND {right})"),
            Expr::Or(left, right) => write!(f, "({left} OR {right})"),
        }
    }
}

/// Analyseur syntaxique construisant un AST à partir de la séquence de jetons.
pub struct Parser {
    tokens: Vec<Token>,
    cursor: usize,
}

impl Parser {
    pub fn new(tokens: Vec<Token>) -> Self {
        Self { tokens, cursor: 0 }
    }

    fn peek(&self) -> &Token {
        &self.tokens[self.cursor]
    }

    fn advance(&mut self) -> &Token {
        let tok = &self.tokens[self.cursor];
        if self.cursor + 1 < self.tokens.len() {
            self.cursor += 1;
        }
        tok
    }

    pub fn parse(&mut self) -> Result<Expr, EngineError> {
        let expr = self.parse_or()?;
        if self.peek().kind != TokenKind::Eof {
            return Err(EngineError::UnexpectedToken {
                expected: "Fin de l'expression".to_string(),
                found: self.peek().kind.to_string(),
                pos: self.peek().pos,
            });
        }
        Ok(expr)
    }

    // <OrExpr> ::= <AndExpr> ( ("OR" | "||") <AndExpr> )*
    fn parse_or(&mut self) -> Result<Expr, EngineError> {
        let mut left = self.parse_and()?;

        while self.peek().kind == TokenKind::Or {
            self.advance();
            let right = self.parse_and()?;
            left = Expr::Or(Box::new(left), Box::new(right));
        }

        Ok(left)
    }

    // <AndExpr> ::= <UnaryExpr> ( ("AND" | "&&") <UnaryExpr> )*
    fn parse_and(&mut self) -> Result<Expr, EngineError> {
        let mut left = self.parse_unary()?;

        while self.peek().kind == TokenKind::And {
            self.advance();
            let right = self.parse_unary()?;
            left = Expr::And(Box::new(left), Box::new(right));
        }

        Ok(left)
    }

    // <UnaryExpr> ::= ( ("NOT" | "!") )* <PrimaryExpr>
    fn parse_unary(&mut self) -> Result<Expr, EngineError> {
        if self.peek().kind == TokenKind::Not {
            self.advance();
            let operand = self.parse_unary()?;
            Ok(Expr::Not(Box::new(operand)))
        } else {
            self.parse_primary()
        }
    }

    // <PrimaryExpr> ::= <Boolean> | <Ident> | "(" <Expression> ")"
    fn parse_primary(&mut self) -> Result<Expr, EngineError> {
        let token = self.peek().clone();

        match token.kind {
            TokenKind::True => {
                self.advance();
                Ok(Expr::Literal(true))
            }
            TokenKind::False => {
                self.advance();
                Ok(Expr::Literal(false))
            }
            TokenKind::Ident(name) => {
                self.advance();
                Ok(Expr::Variable(name))
            }
            TokenKind::LParen => {
                self.advance();
                let inner = self.parse_or()?;
                if self.peek().kind != TokenKind::RParen {
                    return Err(EngineError::UnclosedParenthesis);
                }
                self.advance();
                Ok(inner)
            }
            TokenKind::Eof => Err(EngineError::UnexpectedEof),
            _ => Err(EngineError::UnexpectedToken {
                expected: "Valeur booléenne, identifiant ou parenthèse ouvrante".to_string(),
                found: token.kind.to_string(),
                pos: token.pos,
            }),
        }
    }
}

/// Compile et évalue une chaîne logique en une étape.
pub fn evaluate(input: &str, context: &HashMap<String, bool>) -> Result<bool, EngineError> {
    let tokens = Lexer::new(input).tokenize()?;
    let mut parser = Parser::new(tokens);
    let ast = parser.parse()?;
    ast.eval(context)
}

fn main() {
