                            Err(err) => eprintln!("Erreur d'évaluation : {err}"),
                        }
                    }
                    Err(err) => eprintln!("Erreur d'analyse syntaxique : {err}"),
                }
            }
            Err(err) => eprintln!("Erreur d'analyse lexicale : {err}"),
        }
