                )
            }
            BlockchainError::ProofOfWorkFailed { hash, difficulty } => {
                write!(
                    f,
                    "Preuve de travail insuffisante. Hash '{}' ne respecte pas la difficulté de {} zéros.",
                    hash, difficulty
                )
            }
            BlockchainError::InvalidTimestamp { prev, current } => {
                write!(
                    f,
                    "Incohérence temporelle : Horodatage actuel ({}) antérieur au précédent ({}).",
                    current, prev
                )
            }
