/// Structure représentant un bloc de la chaîne.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct Block {
    pub index: u64,
    pub timestamp: i64,
    pub data: String,
    pub previous_hash: String,
    pub hash: String,
    pub nonce: u64,
    pub difficulty: usize,
}

impl Block {
    /// Calcule l'empreinte SHA-256 canonique pour un ensemble d'attributs de bloc.
    pub fn calculate_hash(
        index: u64,
        timestamp: i64,
        data: &str,
        previous_hash: &str,
        nonce: u64,
        difficulty: usize,
    ) -> String {
        let mut hasher = Sha256::new();
        let payload = format!(
            "{}:{}:{}:{}:{}:{}",
            index, timestamp, data, previous_hash, nonce, difficulty
        );
        hasher.update(payload.as_bytes());
        hex::encode(hasher.finalize())
    }

    /// Vérifie si un hash respecte le critère de difficulté (préfixe de zéros).
    pub fn is_valid_hash(hash: &str, difficulty: usize) -> bool {
        let prefix = "0".repeat(difficulty);
        hash.starts_with(&prefix)
    }

    /// Effectue le minage de bloc (recherche de la preuve de travail).
    pub fn mine(
        index: u64,
        data: String,
        previous_hash: String,
        difficulty: usize,
    ) -> (Self, u64, std::time::Duration) {
        let timestamp = Utc::now().timestamp_millis();
        let mut nonce = 0u64;
        let start_time = Instant::now();

        loop {
            let hash = Self::calculate_hash(
                index,
                timestamp,
                &data,
                &previous_hash,
                nonce,
                difficulty,
            );

            if Self::is_valid_hash(&hash, difficulty) {
                let duration = start_time.elapsed();
                let block = Block {
                    index,
                    timestamp,
                    data,
                    previous_hash,
                    hash,
                    nonce,
                    difficulty,
                };
                return (block, nonce + 1, duration);
            }

            nonce = nonce.wrapping_add(1);
        }
    }
}

/// Simulateur de registre distribué Blockchain avec ajustement dynamique de difficulté.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Blockchain {
    pub chain: Vec<Block>,
    pub difficulty: usize,
    pub target_block_time_ms: u64,
    pub difficulty_adjustment_interval: u64,
}

impl Blockchain {
    /// Initialise une nouvelle chaîne avec le bloc Genesis.
    pub fn new(
        initial_difficulty: usize,
        target_block_time_ms: u64,
        difficulty_adjustment_interval: u64,
    ) -> Self {
        let genesis_block = Self::create_genesis_block(initial_difficulty);
        Self {
            chain: vec![genesis_block],
            difficulty: initial_difficulty,
            target_block_time_ms,
            difficulty_adjustment_interval,
        }
    }

    /// Crée et mine le bloc Genesis initial.
    fn create_genesis_block(difficulty: usize) -> Block {
        let (genesis, _, _) = Block::mine(
            0,
            "Bloc Genesis : Consensus Proof of Work initialisé".to_string(),
            "0".repeat(64),
            difficulty,
        );
        genesis
    }

    /// Renvoie une référence vers le dernier bloc de la chaîne.
    pub fn latest_block(&self) -> Result<&Block, BlockchainError> {
        self.chain.last().ok_or(BlockchainError::EmptyChain)
    }

    /// Ajuste la difficulté dynamiquement en fonction du temps écoulé sur la dernière fenêtre.
    pub fn adjust_difficulty(&self) -> usize {
        let chain_len = self.chain.len() as u64;

        if chain_len <= self.difficulty_adjustment_interval {
            return self.difficulty;
        }

        let current_index = (chain_len - 1) as usize;
        let start_index = current_index - self.difficulty_adjustment_interval as usize;

        let latest_block = &self.chain[current_index];
        let base_block = &self.chain[start_index];

        let actual_time_taken = (latest_block.timestamp - base_block.timestamp).max(1) as u64;
        let expected_time = self.target_block_time_ms * self.difficulty_adjustment_interval;

        println!(
            "\n[RÉAJUSTEMENT DE DIFFICULTÉ] Fenêtre de {} blocs analysée :",
            self.difficulty_adjustment_interval
        );
        println!("  - Temps effectif constaté  : {} ms", actual_time_taken);
        println!("  - Temps cible théorique     : {} ms", expected_time);

        // Amortissement : Tolérance de facteur 2 pour éviter les oscillations brutales
        if actual_time_taken < expected_time / 2 {
            let new_diff = self.difficulty.saturating_add(1);
            println!(
                "  -> Minage trop rapide. Augmentation de la difficulté : {} -> {}",
                self.difficulty, new_diff
            );
            new_diff
        } else if actual_time_taken > expected_time * 2 {
            let new_diff = self.difficulty.saturating_sub(1).max(1);
            println!(
                "  -> Minage trop lent. Diminution de la difficulté : {} -> {}",
                self.difficulty, new_diff
            );
            new_diff
        } else {
            println!(
                "  -> Rythme optimal. Difficulté maintenue à {}",
                self.difficulty
            );
            self.difficulty
        }
    }

    /// Mine et ajoute un nouveau bloc de données à la chaîne.
    pub fn mine_and_add_block(&mut self, data: String) -> Result<Block, BlockchainError> {
        let (next_index, prev_hash) = {
            let last = self.latest_block()?;
            (last.index + 1, last.hash.clone())
        };

        // Recalcul périodique de la difficulté
        if next_index > 0 && next_index % self.difficulty_adjustment_interval == 0 {
            self.difficulty = self.adjust_difficulty();
        }

        let difficulty = self.difficulty;
        println!(
            "\n--- Minage du Bloc #{} [Difficulté: {} zéros] ---",
            next_index, difficulty
        );

        let (new_block, attempts, duration) =
            Block::mine(next_index, data, prev_hash, difficulty);

        let duration_ms = duration.as_millis().max(1);
        let hashrate = (attempts as f64) / (duration.as_secs_f64().max(0.0001));

        println!("  Hash validé  : {}", new_block.hash);
        println!("  Nonce trouvé : {}", new_block.nonce);
        println!("  Tentatives   : {}", attempts);
        println!("  Durée minage : {} ms ({:.2} kH/s)", duration_ms, hashrate / 1000.0);

        self.validate_block_addition(&new_block)?;
        self.chain.push(new_block.clone());

        Ok(new_block)
    }

    /// Valide individuellement les contraintes d'ajout d'un bloc.
    pub fn validate_block_addition(&self, block: &Block) -> Result<(), BlockchainError> {
        let last = self.latest_block()?;

        if block.index != last.index + 1 {
            return Err(BlockchainError::InvalidIndex {
                expected: last.index + 1,
                found: block.index,
            });
        }

        if block.previous_hash != last.hash {
            return Err(BlockchainError::InvalidPreviousHash {
                expected: last.hash.clone(),
                found: block.previous_hash.clone(),
            });
        }

        if block.timestamp < last.timestamp {
            return Err(BlockchainError::InvalidTimestamp {
                prev: last.timestamp,
                current: block.timestamp,
            });
        }

        let recalculated = Block::calculate_hash(
            block.index,
            block.timestamp,
            &block.data,
            &block.previous_hash,
            block.nonce,
            block.difficulty,
        );

        if block.hash != recalculated {
            return Err(BlockchainError::InvalidHash {
                calculated: recalculated,
                stored: block.hash.clone(),
            });
        }

        if !Block::is_valid_hash(&block.hash, block.difficulty) {
            return Err(BlockchainError::ProofOfWorkFailed {
                hash: block.hash.clone(),
                difficulty: block.difficulty,
            });
        }

        Ok(())
    }

    /// Parcourt l'ensemble de la chaîne et vérifie l'intégrité globale du registre.
    pub fn validate_chain(&self) -> Result<(), BlockchainError> {
        if self.chain.is_empty() {
            return Err(BlockchainError::EmptyChain);
        }

        let genesis = &self.chain[0];
        if genesis.index != 0 {
            return Err(BlockchainError::GenesisCorrupted);
        }

        let genesis_recalculated = Block::calculate_hash(
            genesis.index,
            genesis.timestamp,
            &genesis.data,
            &genesis.previous_hash,
            genesis.nonce,
            genesis.difficulty,
        );

        if genesis.hash != genesis_recalculated {
            return Err(BlockchainError::InvalidHash {
                calculated: genesis_recalculated,
                stored: genesis.hash.clone(),
            });
        }

        if !Block::is_valid_hash(&genesis.hash, genesis.difficulty) {
            return Err(BlockchainError::ProofOfWorkFailed {
                hash: genesis.hash.clone(),
                difficulty: genesis.difficulty,
            });
        }

        for window in self.chain.windows(2) {
            let prev = &window[0];
            let current = &window[1];

            if current.index != prev.index + 1 {
                return Err(BlockchainError::InvalidIndex {
                    expected: prev.index + 1,
                    found: current.index,
                });
            }

            if current.previous_hash != prev.hash {
                return Err(BlockchainError::InvalidPreviousHash {
                    expected: prev.hash.clone(),
                    found: current.previous_hash.clone(),
                });
            }

            if current.timestamp < prev.timestamp {
                return Err(BlockchainError::InvalidTimestamp {
                    prev: prev.timestamp,
                    current: current.timestamp,
                });
            }

            let recalculated = Block::calculate_hash(
                current.index,
                current.timestamp,
                &current.data,
                &current.previous_hash,
                current.nonce,
                current.difficulty,
            );

            if current.hash != recalculated {
                return Err(BlockchainError::InvalidHash {
                    calculated: recalculated,
                    stored: current.hash.clone(),
                });
            }

            if !Block::is_valid_hash(&current.hash, current.difficulty) {
                return Err(BlockchainError::ProofOfWorkFailed {
                    hash: current.hash.clone(),
                    difficulty: current.difficulty,
                });
            }
        }

        Ok(())
    }
}

