        Ok(new_block)
    }

    /// Valide individuellement les contraintes d'ajout d'un bloc.
    pub fn validate_block_addition(&self, block: &Block) -> Result<(), BlockchainError> {
        let last = self.latest_block()?;

        if block.index != last.index + 1 {
            return Err(BlockchainError::InvalidIndex {
                expected: last.index + 1,
                found: block.index,
            });
        }

        if block.previous_hash != last.hash {
            return Err(BlockchainError::InvalidPreviousHash {
                expected: last.hash.clone(),
                found: block.previous_hash.clone(),
            });
        }

        if block.timestamp < last.timestamp {
            return Err(BlockchainError::InvalidTimestamp {
                prev: last.timestamp,
                current: block.timestamp,
            });
        }

        let recalculated = Block::calculate_hash(
            block.index,
            block.timestamp,
            &block.data,
            &block.previous_hash,
            block.nonce,
            block.difficulty,
        );

        if block.hash != recalculated {
            return Err(BlockchainError::InvalidHash {
                calculated: recalculated,
                stored: block.hash.clone(),
            });
        }

        if !Block::is_valid_hash(&block.hash, block.difficulty) {
            return Err(BlockchainError::ProofOfWorkFailed {
                hash: block.hash.clone(),
                difficulty: block.difficulty,
            });
        }

        Ok(())
    }

    /// Parcourt l'ensemble de la chaîne et vérifie l'intégrité globale du registre.
    pub fn validate_chain(&self) -> Result<(), BlockchainError> {
        if self.chain.is_empty() {
            return Err(BlockchainError::EmptyChain);
        }

        let genesis = &self.chain[0];
        if genesis.index != 0 {
            return Err(BlockchainError::GenesisCorrupted);
        }

        let genesis_recalculated = Block::calculate_hash(
            genesis.index,
            genesis.timestamp,
            &genesis.data,
            &genesis.previous_hash,
            genesis.nonce,
            genesis.difficulty,
        );

        if genesis.hash != genesis_recalculated {
            return Err(BlockchainError::InvalidHash {
                calculated: genesis_recalculated,
                stored: genesis.hash.clone(),
            });
        }

        if !Block::is_valid_hash(&genesis.hash, genesis.difficulty) {
            return Err(BlockchainError::ProofOfWorkFailed {
                hash: genesis.hash.clone(),
                difficulty: genesis.difficulty,
            });
        }

        for window in self.chain.windows(2) {
            let prev = &window[0];
            let current = &window[1];

            if current.index != prev.index + 1 {
                return Err(BlockchainError::InvalidIndex {
                    expected: prev.index + 1,
                    found: current.index,
                });
            }

            if current.previous_hash != prev.hash {
                return Err(BlockchainError::InvalidPreviousHash {
                    expected: prev.hash.clone(),
                    found: current.previous_hash.clone(),
                });
            }

            if current.timestamp < prev.timestamp {
                return Err(BlockchainError::InvalidTimestamp {
                    prev: prev.timestamp,
                    current: current.timestamp,
                });
            }

            let recalculated = Block::calculate_hash(
                current.index,
                current.timestamp,
                &current.data,
                &current.previous_hash,
                current.nonce,
                current.difficulty,
            );

            if current.hash != recalculated {
                return Err(BlockchainError::InvalidHash {
                    calculated: recalculated,
                    stored: current.hash.clone(),
                });
            }

            if !Block::is_valid_hash(&current.hash, current.difficulty) {
                return Err(BlockchainError::ProofOfWorkFailed {
                    hash: current.hash.clone(),
                    difficulty: current.difficulty,
                });
            }
        }

        Ok(())
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("=============================================================");
    println!("     SIMULATEUR DE CONSENSUS PROOF OF WORK (PoW) EN RUST     ");
    println!("=============================================================");

    let initial_difficulty = 3; // Nombre de zéros hexadécimaux requis
    let target_block_time_ms = 400; // Cible de 400 ms pour la démonstration
    let adjustment_interval = 4; // Ajustement tous les 4 blocs

    println!("Paramètres initiaux :");
    println!("  - Difficulté initiale       : {} zéros", initial_difficulty);
    println!("  - Temps cible par bloc      : {} ms", target_block_time_ms);
    println!("  - Fréquence de réajustement : tous les {} blocs", adjustment_interval);

    let mut blockchain = Blockchain::new(
        initial_difficulty,
        target_block_time_ms,
        adjustment_interval,
    );

    let genesis = blockchain.latest_block()?;
    println!("\n[GENESIS] Bloc initial généré avec succès :");
    println!("  Index: {}, Hash: {}", genesis.index, genesis.hash);

    let sample_transactions = vec![
        "Alice -> Bob : 10 BTC",
        "Bob -> Charlie : 2.5 BTC",
        "Charlie -> Dave : 0.8 BTC",
        "Dave -> Eve : 1.2 BTC",
        "Eve -> Frank : 4.0 BTC",
        "Frank -> Grace : 0.1 BTC",
        "Grace -> Heidi : 5.5 BTC",
        "Heidi -> Ivan : 3.3 BTC",
    ];

    for (i, tx) in sample_transactions.into_iter().enumerate() {
        let block_data = format!("Transaction #{}: {}", i + 1, tx);
        match blockchain.mine_and_add_block(block_data) {
            Ok(b) => {
                println!("  Statut: Bloc #{} intégré au registre.", b.index);
            }
            Err(e) => {
                eprintln!("  Erreur critique lors de l'ajout : {}", e);
                return Err(Box::new(e));
            }
        }
    }

    println!("\n=============================================================");
    println!("                  VÉRIFICATION DE L'INTÉGRITÉ                ");
    println!("=============================================================");

    match blockchain.validate_chain() {
        Ok(_) => {
            println!("SUCCÈS : L'ensemble de la chaîne est cryptographiquement valide !");
            println!("Nombre total de blocs minés : {}", blockchain.chain.len());
        }
        Err(err) => {
            eprintln!("ÉCHEC : Blockchain corrompue : {}", err);
            return Err(Box::new(err));
        }
    }

    println!("\n=============================================================");
    println!("              SIMULATION D'UNE TENTATIVE DE FRAUDE           ");
    println!("=============================================================");

    if blockchain.chain.len() > 2 {
        println!("Attaque par modification du contenu du Bloc #2...");
        blockchain.chain[2].data = "Alice -> Malory (PIRATÉ) : 1000 BTC".to_string();

        match blockchain.validate_chain() {
            Ok(_) => {
                eprintln!("ALERTE CRITIQUE : La blockchain a validé une transaction altérée !");
            }
            Err(err) => {
                println!("DÉTECTION RÉUSSIE : L'altération a été interceptée par le protocole.");
                println!("Raison du rejet : {}", err);
            }
        }
    }

    println!("\nSimulation terminée avec succès.");
    Ok(())
}

