        let mut order = sample_order(dec!(120.00), 3, sample_customer(CustomerTier::Silver, "FR", 150));
        order.applied_coupons = coupons;

        let rule = Rule {
            id: "R-OR".to_string(),
            name: "Coupon OR VIP".to_string(),
            description: None,
            priority: 50,
            condition: Condition::Any {
                conditions: vec![
                    Condition::CustomerTierIn {
                        tiers: vec![CustomerTier::Gold, CustomerTier::Platinum],
                    },
                    Condition::CouponRequired {
                        coupon: "PROMO20".to_string(),
                    },
                ],
            },
            effect: EligibilityEffect::DiscountPercentage(dec!(20)),
        };

        let engine = RuleEngine::new(RuleSet {
            version: "1.0".to_string(),
            rules: vec![rule],
        });

        let report = engine.evaluate_order(&order);
        assert_eq!(report.matched_rules.len(), 1);
        assert_eq!(
            report.applicable_effects,
            vec![EligibilityEffect::DiscountPercentage(dec!(20))]
        );
    }

    #[test]
    fn test_negation_not() {
        let rule = Rule {
            id: "R-NOT".to_string(),
            name: "Not restricted".to_string(),
            description: None,
            priority: 10,
            condition: Condition::Not {
                condition: Box::new(Condition::CountryIn {
                    countries: vec!["US".to_string()],
                }),
            },
            effect: EligibilityEffect::FreeShipping,
        };

        let engine = RuleEngine::new(RuleSet {
            version: "1.0".to_string(),
            rules: vec![rule],
        });

        let order_fr = sample_order(dec!(10.0), 1, sample_customer(CustomerTier::Standard, "FR", 0));
        assert_eq!(engine.evaluate_order(&order_fr).matched_rules.len(), 1);

        let order_us = sample_order(dec!(10.0), 1, sample_customer(CustomerTier::Standard, "US", 0));
        assert_eq!(engine.evaluate_order(&order_us).matched_rules.len(), 0);
    }
