// src/main.rs
use chrono::{DateTime, Utc};
use rust_decimal::Decimal;
use serde::{Deserialize, Serialize};
use std::collections::HashSet;
use std::env;
use std::fs;
use std::path::Path;
use thiserror::Error;

/// Erreurs potentielles rencontrées lors de l'évaluation ou du chargement des règles.
#[derive(Debug, Error)]
pub enum EngineError {
    #[error("Erreur d'entrée/sortie sur le fichier '{path}': {source}")]
    IoError {
        path: String,
        #[source]
        source: std::io::Error,
    },
    #[error("Erreur de désérialisation JSON ({context}): {source}")]
    JsonError {
        context: String,
        #[source]
        source: serde_json::Error,
    },
    #[error("Configuration invalide du moteur: {0}")]
    InvalidConfiguration(String),
}

/// Niveaux de fidélité client possibles.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum CustomerTier {
    Standard,
    Silver,
    Gold,
    Platinum,
}

/// Informations relatives au client ayant passé commande.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Customer {
    pub id: String,
    pub tier: CustomerTier,
    pub loyalty_points: u32,
    pub country_code: String,
}

/// Article individuel présent dans le panier d'achat.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OrderItem {
    pub sku: String,
    pub name: String,
    pub category: String,
    pub unit_price: Decimal,
    pub quantity: u32,
    #[serde(default)]
    pub tags: HashSet<String>,
}

/// Contexte complet d'une commande e-commerce soumis à l'évaluation.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OrderContext {
    pub order_id: String,
    pub created_at: DateTime<Utc>,
    pub customer: Customer,
    pub items: Vec<OrderItem>,
    #[serde(default)]
    pub applied_coupons: HashSet<String>,
    #[serde(default)]
    pub shipping_method: Option<String>,
}

impl OrderContext {
    /// Calcule le montant brut total de la commande sans réduction.
    pub fn compute_subtotal(&self) -> Decimal {
        self.items
            .iter()
            .map(|item| item.unit_price * Decimal::from(item.quantity))
            .sum()
    }

    /// Calcule le nombre total d'articles physiques commandés.
    pub fn total_item_count(&self) -> u32 {
        self.items.iter().map(|item| item.quantity).sum()
    }

    /// Vérifie la présence d'au moins un article appartenant à la catégorie donnée.
    pub fn has_category(&self, category: &str) -> bool {
        self.items
            .iter()
            .any(|item| item.category.eq_ignore_ascii_case(category))
    }

    /// Vérifie si l'article possède le tag renseigné.
    pub fn has_tag(&self, tag: &str) -> bool {
        self.items.iter().any(|item| item.tags.contains(tag))
    }
}

/// Effet ou bénéfice accordé si la règle est satisfaite.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", content = "value", rename_all = "SCREAMING_SNAKE_CASE")]
pub enum EligibilityEffect {
    FreeShipping,
    DiscountPercentage(Decimal),
    DiscountFixedAmount(Decimal),
    VipGift { gift_sku: String },
    RestrictedOrder { reason: String },
}

/// Conditions arborescentes et prédicats métier évaluables par le moteur.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "operator", rename_all = "SCREAMING_SNAKE_CASE")]
pub enum Condition {
    // Opérateurs logiques
    All { conditions: Vec<Condition> },
    Any { conditions: Vec<Condition> },
    Not { condition: Box<Condition> },

    // Prédicats sur le montant et la quantité
    MinAmount { min: Decimal },
    MaxAmount { max: Decimal },
    MinItemCount { min: u32 },

    // Prédicats sur le profil client
    CustomerTierIn { tiers: Vec<CustomerTier> },
    MinLoyaltyPoints { min: u32 },
    CountryIn { countries: Vec<String> },
    CountryNotIn { countries: Vec<String> },

    // Prédicats sur les articles et codes
    CategoryPresent { category: String },
    TagPresent { tag: String },
    CouponRequired { coupon: String },
}

/// Règle métier unique déclarée en JSON.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Rule {
    pub id: String,
    pub name: String,
    pub description: Option<String>,
    #[serde(default = "default_priority")]
    pub priority: u32,
    pub condition: Condition,
    pub effect: EligibilityEffect,
}

fn default_priority() -> u32 {
    100
}

/// Ensemble de règles métier regroupées dans un document JSON.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RuleSet {
    pub version: String,
    pub rules: Vec<Rule>,
}

/// Résultat d'évaluation d'une condition élémentaire ou composée.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ConditionEvaluation {
    pub is_satisfied: bool,
    pub description: String,
}

/// Résultat détaillé d'évaluation d'une règle sur une commande.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RuleEvaluationResult {
    pub rule_id: String,
    pub rule_name: String,
    pub priority: u32,
    pub is_eligible: bool,
    pub effect: Option<EligibilityEffect>,
    pub details: Vec<String>,
}

/// Bilan complet de l'évaluation du RuleSet sur une commande e-commerce.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EvaluationReport {
    pub order_id: String,
    pub evaluated_at: DateTime<Utc>,
    pub subtotal: Decimal,
    pub total_items: u32,
    pub matched_rules: Vec<RuleEvaluationResult>,
    pub unmatched_rules: Vec<RuleEvaluationResult>,
    pub applicable_effects: Vec<EligibilityEffect>,
}

/// Moteur principal d'évaluation des règles d'éligibilité.
pub struct RuleEngine {
    rules: Vec<Rule>,
}

impl RuleEngine {
    /// Construit un moteur à partir d'un ensemble de règles (RuleSet).
    pub fn new(mut rule_set: RuleSet) -> Self {
        // Trie par priorité décroissante (plus la valeur est élevée, plus la règle est prioritaire)
        rule_set.rules.sort_by_key(|r| std::cmp::Reverse(r.priority));
        Self {
            rules: rule_set.rules,
        }
    }

    /// Charge un RuleSet depuis un fichier JSON sur le disque.
    pub fn from_file<P: AsRef<Path>>(path: P) -> Result<Self, EngineError> {
        let path_ref = path.as_ref();
        let content = fs::read_to_string(path_ref).map_err(|e| EngineError::IoError {
            path: path_ref.display().to_string(),
            source: e,
        })?;

        let rule_set: RuleSet =
            serde_json::from_str(&content).map_err(|e| EngineError::JsonError {
                context: format!("Chargement du ruleset '{}'", path_ref.display()),
                source: e,
            })?;

        Ok(Self::new(rule_set))
    }

    /// Évalue une condition récursivement contre le contexte de commande.
    pub fn evaluate_condition(
        condition: &Condition,
        order: &OrderContext,
        subtotal: Decimal,
        total_items: u32,
    ) -> ConditionEvaluation {
        match condition {
            Condition::All { conditions } => {
                if conditions.is_empty() {
                    return ConditionEvaluation {
                        is_satisfied: true,
                        description: "ALL: aucune condition requise".to_string(),
                    };
                }
                let mut all_satisfied = true;
                let mut explanations = Vec::new();

                for c in conditions {
                    let sub = Self::evaluate_condition(c, order, subtotal, total_items);
                    if !sub.is_satisfied {
                        all_satisfied = false;
                    }
                    explanations.push(sub.description);
                }

                ConditionEvaluation {
                    is_satisfied: all_satisfied,
                    description: format!(
                        "ALL [{}]: ({})",
                        if all_satisfied { "SUCCÈS" } else { "ÉCHEC" },
                        explanations.join(" ET ")
                    ),
                }
            }
            Condition::Any { conditions } => {
                if conditions.is_empty() {
                    return ConditionEvaluation {
                        is_satisfied: false,
                        description: "ANY: vide (non satisfait)".to_string(),
                    };
                }
                let mut any_satisfied = false;
                let mut explanations = Vec::new();

                for c in conditions {
                    let sub = Self::evaluate_condition(c, order, subtotal, total_items);
                    if sub.is_satisfied {
                        any_satisfied = true;
                    }
                    explanations.push(sub.description);
                }

                ConditionEvaluation {
                    is_satisfied: any_satisfied,
                    description: format!(
                        "ANY [{}]: ({})",
                        if any_satisfied { "SUCCÈS" } else { "ÉCHEC" },
                        explanations.join(" OU ")
                    ),
                }
            }
            Condition::Not { condition } => {
                let sub = Self::evaluate_condition(condition, order, subtotal, total_items);
                let satisfied = !sub.is_satisfied;
                ConditionEvaluation {
                    is_satisfied: satisfied,
                    description: format!("NON [{}] ({})", satisfied, sub.description),
                }
            }
            Condition::MinAmount { min } => {
                let satisfied = subtotal >= *min;
                ConditionEvaluation {
                    is_satisfied: satisfied,
                    description: format!(
                        "Montant min {} (actuel: {}, satisfaisant: {})",
                        min, subtotal, satisfied
                    ),
                }
            }
            Condition::MaxAmount { max } => {
                let satisfied = subtotal <= *max;
                ConditionEvaluation {
                    is_satisfied: satisfied,
                    description: format!(
                        "Montant max {} (actuel: {}, satisfaisant: {})",
                        max, subtotal, satisfied
                    ),
                }
            }
            Condition::MinItemCount { min } => {
                let satisfied = total_items >= *min;
                ConditionEvaluation {
                    is_satisfied: satisfied,
                    description: format!(
                        "Nombre minimum d'articles {} (actuel: {}, satisfaisant: {})",
                        min, total_items, satisfied
                    ),
                }
            }
            Condition::CustomerTierIn { tiers } => {
                let satisfied = tiers.contains(&order.customer.tier);
                ConditionEvaluation {
                    is_satisfied: satisfied,
                    description: format!(
                        "Niveau client dans {:?} (actuel: {:?}, satisfaisant: {})",
                        tiers, order.customer.tier, satisfied
                    ),
                }
            }
            Condition::MinLoyaltyPoints { min } => {
                let satisfied = order.customer.loyalty_points >= *min;
                ConditionEvaluation {
                    is_satisfied: satisfied,
                    description: format!(
                        "Points de fidélité min {} (actuel: {}, satisfaisant: {})",
                        min, order.customer.loyalty_points, satisfied
                    ),
                }
            }
            Condition::CountryIn { countries } => {
                let satisfied = countries
                    .iter()
                    .any(|c| c.eq_ignore_ascii_case(&order.customer.country_code));
                ConditionEvaluation {
                    is_satisfied: satisfied,
                    description: format!(
                        "Pays dans {:?} (actuel: {}, satisfaisant: {})",
                        countries, order.customer.country_code, satisfied
                    ),
                }
            }
            Condition::CountryNotIn { countries } => {
                let excluded = countries
                    .iter()
                    .any(|c| c.eq_ignore_ascii_case(&order.customer.country_code));
                ConditionEvaluation {
                    is_satisfied: !excluded,
                    description: format!(
                        "Pays exclu parmi {:?} (actuel: {}, non-exclu: {})",
                        countries,
                        order.customer.country_code,
                        !excluded
                    ),
                }
            }
            Condition::CategoryPresent { category } => {
                let satisfied = order.has_category(category);
                ConditionEvaluation {
                    is_satisfied: satisfied,
                    description: format!(
                        "Catégorie requise '{}' présente: {}",
                        category, satisfied
                    ),
                }
            }
            Condition::TagPresent { tag } => {
                let satisfied = order.has_tag(tag);
                ConditionEvaluation {
                    is_satisfied: satisfied,
                    description: format!("Tag requis '{}' présent: {}", tag, satisfied),
                }
            }
            Condition::CouponRequired { coupon } => {
                let satisfied = order.applied_coupons.contains(coupon);
                ConditionEvaluation {
                    is_satisfied: satisfied,
                    description: format!(
                        "Coupon requis '{}' appliqué: {}",
                        coupon, satisfied
                    ),
                }
            }
        }
    }

    /// Évalue l'ensemble des règles pour une commande donnée.
    pub fn evaluate_order(&self, order: &OrderContext) -> EvaluationReport {
        let subtotal = order.compute_subtotal();
        let total_items = order.total_item_count();

        let mut matched_rules = Vec::new();
        let mut unmatched_rules = Vec::new();
        let mut applicable_effects = Vec::new();

        for rule in &self.rules {
            let eval = Self::evaluate_condition(&rule.condition, order, subtotal, total_items);
            let result = RuleEvaluationResult {
                rule_id: rule.id.clone(),
                rule_name: rule.name.clone(),
                priority: rule.priority,
                is_eligible: eval.is_satisfied,
                effect: if eval.is_satisfied {
                    Some(rule.effect.clone())
                } else {
                    None
                },
                details: vec![eval.description],
            };

            if eval.is_satisfied {
                applicable_effects.push(rule.effect.clone());
                matched_rules.push(result);
            } else {
                unmatched_rules.push(result);
            }
        }

        EvaluationReport {
            order_id: order.order_id.clone(),
            evaluated_at: Utc::now(),
            subtotal,
            total_items,
            matched_rules,
            unmatched_rules,
            applicable_effects,
        }
    }
}

