    }"#;

    (sample_rules, sample_order)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = env::args().collect();

    let (rule_set, order): (RuleSet, OrderContext) = if args.len() >= 3 {
        let rules_path = &args[1];
        let order_path = &args[2];

        println!("Chargement des règles depuis: {}", rules_path);
        let rules_str = fs::read_to_string(rules_path)?;
        let parsed_rules: RuleSet = serde_json::from_str(&rules_str)?;

        println!("Chargement de la commande depuis: {}", order_path);
        let order_str = fs::read_to_string(order_path)?;
        let parsed_order: OrderContext = serde_json::from_str(&order_str)?;

        (parsed_rules, parsed_order)
    } else {
        println!("ℹ️  Aucun fichier JSON fourni en argument.");
        println!("   Usage optionnel: cargo run -- <chemin_rules.json> <chemin_order.json>");
        println!("   Exécution avec le jeu de données e-commerce de démonstration...\n");

        let (sample_rules, sample_order) = get_sample_data();
        let parsed_rules: RuleSet = serde_json::from_str(sample_rules)?;
        let parsed_order: OrderContext = serde_json::from_str(sample_order)?;
        (parsed_rules, parsed_order)
    };

    let engine = RuleEngine::new(rule_set);
    let report = engine.evaluate_order(&order);

    println!("============================================================");
    println!("     RAPPORT D'ÉVALUATION DES RÈGLES D'ÉLIGIBILITÉ");
    println!("============================================================");
    println!("ID Commande       : {}", report.order_id);
    println!("Client ID         : {}", order.customer.id);
    println!("Segment Client    : {:?}", order.customer.tier);
    println!("Pays Expédition   : {}", order.customer.country_code);
    println!("Total Panier      : {} €", report.subtotal);
    println!("Nombre d'articles : {}", report.total_items);
    println!("Date Évaluation   : {}", report.evaluated_at);
    println!("------------------------------------------------------------");

    println!("✅ RÈGLES APPLICABLES / ÉLIGIBLES ({}) :", report.matched_rules.len());
    for matched in &report.matched_rules {
        println!("  - [{}] {} (priorité: {})", matched.rule_id, matched.rule_name, matched.priority);
        if let Some(effect) = &matched.effect {
            println!("    Effet accordé : {:?}", effect);
        }
        for d in &matched.details {
            println!("    Détails       : {}", d);
        }
    }

    if !report.unmatched_rules.is_empty() {
        println!("\n❌ RÈGLES NON ÉLIGIBLES ({}) :", report.unmatched_rules.len());
        for unmatched in &report.unmatched_rules {
            println!("  - [{}] {}", unmatched.rule_id, unmatched.rule_name);
            for d in &unmatched.details {
                println!("    Raison : {}", d);
            }
        }
    }

    println!("------------------------------------------------------------");
    println!("EFFETS ACCORDÉS CUMULÉS :");
    for eff in &report.applicable_effects {
        println!("  • {:?}", eff);
    }
    println!("============================================================");

    // Sérialisation du rapport final au format JSON structuré
    let json_report = serde_json::to_string_pretty(&report)?;
    println!("\nRapport JSON généré avec succès ({} octets).", json_report.len());

    Ok(())
}

