        };

        let engine = RuleEngine::new(RuleSet {
            version: "1.0".to_string(),
            rules: vec![rule],
        });

        // Cas 1 : Panier de 60€ en France -> Éligible
        let order_ok = sample_order(dec!(60.00), 2, sample_customer(CustomerTier::Standard, "FR", 10));
        let rep1 = engine.evaluate_order(&order_ok);
        assert_eq!(rep1.matched_rules.len(), 1);
        assert_eq!(rep1.applicable_effects, vec![EligibilityEffect::FreeShipping]);

        // Cas 2 : Panier de 40€ en France -> Non éligible (montant insuffisant)
        let order_low = sample_order(dec!(40.00), 1, sample_customer(CustomerTier::Standard, "FR", 10));
        let rep2 = engine.evaluate_order(&order_low);
        assert_eq!(rep2.matched_rules.len(), 0);

        // Cas 3 : Panier de 100€ en Allemagne (DE) -> Non éligible (pays exclu)
        let order_de = sample_order(dec!(100.00), 1, sample_customer(CustomerTier::Standard, "DE", 10));
        let rep3 = engine.evaluate_order(&order_de);
        assert_eq!(rep3.matched_rules.len(), 0);
    }

