// src/main.rs
use anyhow::{bail, Context, Result};
use clap::{Parser, ValueEnum};
use std::fmt;
use std::fs::File;
use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
pub enum SubtitleFormat {
    Srt,
    Vtt,
}

impl SubtitleFormat {
    pub fn from_path(path: &Path) -> Option<Self> {
        match path.extension().and_then(|ext| ext.to_str()) {
            Some(ext) if ext.eq_ignore_ascii_case("srt") => Some(Self::Srt),
            Some(ext) if ext.eq_ignore_ascii_case("vtt") => Some(Self::Vtt),
            _ => None,
        }
    }
}

/// Représente un instant absolu en millisecondes depuis le début du média.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Default)]
pub struct Timestamp {
    total_ms: u64,
}

impl Timestamp {
    pub fn from_ms(ms: u64) -> Self {
        Self { total_ms: ms }
    }

    pub fn total_ms(&self) -> u64 {
        self.total_ms
    }

    /// Parse un timestamp SRT : `HH:MM:SS,mmm`
    pub fn parse_srt(s: &str) -> Result<Self> {
        let parts: Vec<&str> = s.trim().split(',').collect();
        if parts.len() != 2 {
            bail!("Format SRT invalide pour '{}' (séparateur virgule manquant)", s);
        }

        let millis: u64 = parts[1].parse().context("Millisecondes invalides")?;
        let hms: Vec<&str> = parts[0].split(':').collect();
        if hms.len() != 3 {
            bail!("Format SRT HH:MM:SS invalide pour '{}'", parts[0]);
        }

        let hours: u64 = hms[0].parse().context("Heures invalides")?;
        let minutes: u64 = hms[1].parse().context("Minutes invalides")?;
        let seconds: u64 = hms[2].parse().context("Secondes invalides")?;

        let total_ms = (hours * 3_600_000) + (minutes * 60_000) + (seconds * 1_000) + millis;
        Ok(Self { total_ms })
    }

    /// Parse un timestamp VTT : `HH:MM:SS.mmm` ou `MM:SS.mmm`
    pub fn parse_vtt(s: &str) -> Result<Self> {
        let parts: Vec<&str> = s.trim().split('.').collect();
        if parts.len() != 2 {
            bail!("Format VTT invalide pour '{}' (séparateur point manquant)", s);
        }

        let millis: u64 = parts[1].parse().context("Millisecondes invalides")?;
        let time_parts: Vec<&str> = parts[0].split(':').collect();

        let (hours, minutes, seconds) = match time_parts.len() {
            2 => {
                let m: u64 = time_parts[0].parse().context("Minutes invalides")?;
                let s: u64 = time_parts[1].parse().context("Secondes invalides")?;
                (0, m, s)
            }
            3 => {
                let h: u64 = time_parts[0].parse().context("Heures invalides")?;
                let m: u64 = time_parts[1].parse().context("Minutes invalides")?;
                let s: u64 = time_parts[2].parse().context("Secondes invalides")?;
                (h, m, s)
            }
            _ => bail!("Segments temporels VTT invalides pour '{}'", parts[0]),
        };

        let total_ms = (hours * 3_600_000) + (minutes * 60_000) + (seconds * 1_000) + millis;
        Ok(Self { total_ms })
    }

    /// Applique un décalage en millisecondes en bornant à 0
    pub fn shift(&self, shift_ms: i64) -> Self {
        let current = self.total_ms as i64;
        let new_val = (current + shift_ms).max(0) as u64;
        Self { total_ms: new_val }
    }

    pub fn to_srt_string(&self) -> String {
        let ms = self.total_ms % 1_000;
        let total_seconds = self.total_ms / 1_000;
        let sec = total_seconds % 60;
        let total_min = total_seconds / 60;
        let min = total_min % 60;
        let hours = total_min / 60;
        format!("{:02}:{:02}:{:02},{:03}", hours, min, sec, ms)
    }

    pub fn to_vtt_string(&self) -> String {
        let ms = self.total_ms % 1_000;
        let total_seconds = self.total_ms / 1_000;
        let sec = total_seconds % 60;
        let total_min = total_seconds / 60;
        let min = total_min % 60;
        let hours = total_min / 60;
        format!("{:02}:{:02}:{:02}.{:03}", hours, min, sec, ms)
    }
}

impl fmt::Display for Timestamp {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.to_srt_string())
    }
}

/// Représente un bloc de sous-titre individuel
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SubtitleCue {
    pub id: Option<String>,
    pub start: Timestamp,
    pub end: Timestamp,
    pub settings: Option<String>,
    pub lines: Vec<String>,
}

impl SubtitleCue {
    pub fn shift(&mut self, shift_ms: i64) {
        self.start = self.start.shift(shift_ms);
        self.end = self.end.shift(shift_ms);
    }
}

/// Modèle global d'un fichier de sous-titres
#[derive(Debug, Clone, Default)]
pub struct SubtitleDocument {
    pub format: Option<SubtitleFormat>,
    pub header_comments: Vec<String>,
    pub cues: Vec<SubtitleCue>,
}

impl SubtitleDocument {
    pub fn shift_all(&mut self, shift_ms: i64) {
        for cue in &mut self.cues {
            cue.shift(shift_ms);
        }
    }

    pub fn parse(content: &str, forced_format: Option<SubtitleFormat>) -> Result<Self> {
        let detected = forced_format.unwrap_or_else(|| {
            if content.trim_start().starts_with("WEBVTT") {
                SubtitleFormat::Vtt
            } else {
                SubtitleFormat::Srt
            }
        });

        match detected {
            SubtitleFormat::Srt => Self::parse_srt(content),
            SubtitleFormat::Vtt => Self::parse_vtt(content),
        }
    }

    fn parse_srt(content: &str) -> Result<Self> {
        let mut cues = Vec::new();
        let lines: Vec<&str> = content.lines().collect();
        let mut idx = 0;

        while idx < lines.len() {
            let line = lines[idx].trim();
            if line.is_empty() {
                idx += 1;
                continue;
            }

            // Identification optionnelle ou obligatoire du numéro d'index
            let mut cue_id = None;
            let mut timing_line = line;

            if !line.contains("-->") {
                cue_id = Some(line.to_string());
                idx += 1;
                if idx >= lines.len() {
                    break;
                }
                timing_line = lines[idx].trim();
            }

            if !timing_line.contains("-->") {
                idx += 1;
                continue;
            }

            let parts: Vec<&str> = timing_line.split("-->").collect();
            if parts.len() != 2 {
                bail!("Ligne de timing SRT corrompue: '{}'", timing_line);
            }

            let start = Timestamp::parse_srt(parts[0].trim())?;
            let end = Timestamp::parse_srt(parts[1].trim())?;

            idx += 1;
            let mut text_lines = Vec::new();
            while idx < lines.len() && !lines[idx].trim().is_empty() {
                text_lines.push(lines[idx].trim_end().to_string());
                idx += 1;
            }

            cues.push(SubtitleCue {
                id: cue_id,
                start,
                end,
                settings: None,
                lines: text_lines,
            });
        }

        Ok(Self {
            format: Some(SubtitleFormat::Srt),
            header_comments: Vec::new(),
            cues,
        })
    }

    fn parse_vtt(content: &str) -> Result<Self> {
        let mut cues = Vec::new();
        let mut header_comments = Vec::new();
        let lines: Vec<&str> = content.lines().collect();
        let mut idx = 0;

        // Skip UTF-8 BOM si présent et validation de l'en-tête WEBVTT
        if idx < lines.len() {
            let first = lines[idx].trim_start_matches('\u{feff}').trim();
            if !first.starts_with("WEBVTT") {
                bail!("Fichier WebVTT invalide : doit commencer par 'WEBVTT'");
            }
            idx += 1;
        }

        // Lecture des en-têtes ou commentaires initiaux avant le premier cue
        while idx < lines.len() {
            let line = lines[idx].trim();
            if line.contains("-->") {
                break;
            }
            if !line.is_empty() && (idx + 1 < lines.len() && lines[idx + 1].contains("-->")) {
                break;
            }
            if !line.is_empty() {
                header_comments.push(line.to_string());
            }
            idx += 1;
        }

        while idx < lines.len() {
            let line = lines[idx].trim();
            if line.is_empty() {
                idx += 1;
                continue;
            }

            let mut cue_id = None;
            let mut timing_line = line;

            if !line.contains("-->") {
                cue_id = Some(line.to_string());
                idx += 1;
                if idx >= lines.len() {
                    break;
                }
                timing_line = lines[idx].trim();
            }

            if !timing_line.contains("-->") {
                idx += 1;
                continue;
            }

            let parts: Vec<&str> = timing_line.split("-->").collect();
            if parts.len() != 2 {
                bail!("Ligne de timing VTT corrompue: '{}'", timing_line);
            }

            let start_str = parts[0].trim();
            let end_and_settings = parts[1].trim();

            let (end_str, settings) = match end_and_settings.find(char::is_whitespace) {
                Some(pos) => {
                    let end_part = &end_and_settings[..pos];
                    let set_part = end_and_settings[pos..].trim();
                    (end_part, if set_part.is_empty() { None } else { Some(set_part.to_string()) })
                }
                None => (end_and_settings, None),
            };

            let start = Timestamp::parse_vtt(start_str)?;
            let end = Timestamp::parse_vtt(end_str)?;

            idx += 1;
            let mut text_lines = Vec::new();
            while idx < lines.len() && !lines[idx].trim().is_empty() {
                text_lines.push(lines[idx].trim_end().to_string());
                idx += 1;
            }

            cues.push(SubtitleCue {
                id: cue_id,
                start,
                end,
                settings,
                lines: text_lines,
            });
        }

        Ok(Self {
            format: Some(SubtitleFormat::Vtt),
            header_comments,
            cues,
        })
    }

    pub fn export_srt(&self) -> String {
        let mut out = String::new();
        for (i, cue) in self.cues.iter().enumerate() {
            let id = (i + 1).to_string();
            out.push_str(&id);
            out.push('\n');
            out.push_str(&format!(
                "{} --> {}\n",
                cue.start.to_srt_string(),
                cue.end.to_srt_string()
            ));
            for line in &cue.lines {
                out.push_str(line);
                out.push('\n');
            }
            out.push('\n');
        }
        out
    }

    pub fn export_vtt(&self) -> String {
        let mut out = String::new();
        out.push_str("WEBVTT\n");
        if !self.header_comments.is_empty() {
            for comment in &self.header_comments {
                out.push_str(comment);
                out.push('\n');
            }
        }
        out.push('\n');

        for (i, cue) in self.cues.iter().enumerate() {
            if let Some(ref id) = cue.id {
                out.push_str(id);
                out.push('\n');
            } else {
                out.push_str(&(i + 1).to_string());
                out.push('\n');
            }

            let settings_str = match &cue.settings {
                Some(s) if !s.is_empty() => format!(" {}", s),
                _ => String::new(),
            };

            out.push_str(&format!(
                "{} --> {}{}\n",
                cue.start.to_vtt_string(),
                cue.end.to_vtt_string(),
                settings_str
            ));

            for line in &cue.lines {
                out.push_str(line);
                out.push('\n');
            }
            out.push('\n');
        }
        out
    }

    pub fn write_to_file(&self, path: &Path, format: SubtitleFormat) -> Result<()> {
        let content = match format {
            SubtitleFormat::Srt => self.export_srt(),
            SubtitleFormat::Vtt => self.export_vtt(),
        };

        let mut file = File::create(path)
            .with_context(|| format!("Impossible de créer le fichier {}", path.display()))?;
        file.write_all(content.as_bytes())
            .with_context(|| format!("Impossible d'écrire dans {}", path.display()))?;
        Ok(())
    }
}

#[derive(Parser, Debug)]
#[command(
    name = "subtitle-shifter",
    version = "0.1.0",
    about = "Outil de décalage temporel et de conversion pour sous-titres SRT / VTT"
)]
struct Args {
    /// Fichier de sous-titres source
    #[arg(short, long)]
    input: PathBuf,

    /// Fichier cible de réexport
    #[arg(short, long)]
    output: PathBuf,

    /// Décalage temporel en millisecondes (peut être négatif, ex: -1500 ou 2000)
    #[arg(short, long, default_value_t = 0)]
    shift_ms: i64,

    /// Format forcé pour la sortie (déduit automatiquement de l'extension de sortie sinon)
    #[arg(short, long, value_enum)]
    format: Option<SubtitleFormat>,
}

fn main() -> Result<()> {
    let args = Args::parse();

    if !args.input.exists() {
        bail!("Le fichier d'entrée n'existe pas : {}", args.input.display());
    }

    let input_format = SubtitleFormat::from_path(&args.input);
    let target_format = args
        .format
        .or_else(|| SubtitleFormat::from_path(&args.output))
        .or(input_format)
        .unwrap_or(SubtitleFormat::Srt);

    let file = File::open(&args.input)
        .with_context(|| format!("Impossible d'ouvrir {}", args.input.display()))?;
    let mut reader = BufReader::new(file);
    let mut content = String::new();
    reader
        .read_line(&mut content)
        .with_context(|| "Impossible de lire le fichier source")?;
    // Lire le reste du fichier
    let mut full_content = content;
    std::io::Read::read_to_string(&mut reader, &mut full_content)
        .with_context(|| "Impossible de lire la suite du fichier")?;

    let mut doc = SubtitleDocument::parse(&full_content, input_format)
        .with_context(|| format!("Erreur lors du parsing du fichier {}", args.input.display()))?;

    println!(
        "Chargé : {} sous-titre(s) depuis '{}'",
        doc.cues.len(),
        args.input.display()
    );

    if args.shift_ms != 0 {
        println!("Application du décalage : {} ms", args.shift_ms);
        doc.shift_all(args.shift_ms);
    }

    doc.write_to_file(&args.output, target_format)?;

    println!(
        "Succès : Fichier exporté avec succès vers '{}' (Format: {:?})",
        args.output.display(),
        target_format
    );

    Ok(())
}

