/// Paramètres cinétiques régissant l'évolution du modèle de Lotka-Volterra.
#[derive(Debug, Clone, Copy)]
pub struct ModelParams {
    pub alpha: f64,
    pub beta: f64,
    pub gamma: f64,
    pub delta: f64,
}

/// État instantané des populations au sein de l'écosystème.
#[derive(Debug, Clone, Copy)]
pub struct PopulationState {
    pub prey: f64,
    pub predator: f64,
}

impl PopulationState {
    pub fn new(prey: f64, predator: f64) -> Self {
        Self {
            prey: prey.max(0.0),
            predator: predator.max(0.0),
        }
    }
}

/// Moteur de simulation numérique appliquant la méthode de Runge-Kutta d'ordre 4 (RK4).
pub struct EcosystemSimulator {
    pub params: ModelParams,
    pub state: PopulationState,
    pub initial_state: PopulationState,
    pub time: f64,
    pub step: u64,
    pub dt: f64,
    pub history: VecDeque<PopulationState>,
    pub max_history: usize,
}

impl EcosystemSimulator {
    pub fn new(
        params: ModelParams,
        initial_state: PopulationState,
        dt: f64,
        max_history: usize,
    ) -> Self {
        let mut history = VecDeque::with_capacity(max_history);
        history.push_back(initial_state);

        Self {
            params,
            state: initial_state,
            initial_state,
            time: 0.0,
            step: 0,
            dt,
            history,
            max_history,
        }
    }

    /// Calcule les dérivées temporelles (dx/dt, dy/dt) selon les équations différentielles :
    /// dx/dt = alpha * x - beta * x * y
    /// dy/dt = delta * x * y - gamma * y
    #[inline]
    fn derivatives(&self, state: PopulationState) -> (f64, f64) {
        let x = state.prey;
        let y = state.predator;

        let d_prey = self.params.alpha * x - self.params.beta * x * y;
        let d_pred = self.params.delta * x * y - self.params.gamma * y;

        (d_prey, d_pred)
    }

    /// Avance la simulation d'un pas de temps `dt` en utilisant l'intégrateur RK4.
    pub fn step(&mut self) {
        let dt = self.dt;
        let s0 = self.state;

        // Étape 1
        let (k1_x, k1_y) = self.derivatives(s0);

        // Étape 2
        let s1 = PopulationState::new(s0.prey + 0.5 * dt * k1_x, s0.predator + 0.5 * dt * k1_y);
        let (k2_x, k2_y) = self.derivatives(s1);

        // Étape 3
        let s2 = PopulationState::new(s0.prey + 0.5 * dt * k2_x, s0.predator + 0.5 * dt * k2_y);
        let (k3_x, k3_y) = self.derivatives(s2);

        // Étape 4
        let s3 = PopulationState::new(s0.prey + dt * k3_x, s0.predator + dt * k3_y);
        let (k4_x, k4_y) = self.derivatives(s3);

        // Combinaison RK4 pondérée
        let next_prey = s0.prey + (dt / 6.0) * (k1_x + 2.0 * k2_x + 2.0 * k3_x + k4_x);
        let next_pred = s0.predator + (dt / 6.0) * (k1_y + 2.0 * k2_y + 2.0 * k3_y + k4_y);

        self.state = PopulationState::new(next_prey, next_pred);
        self.time += dt;
        self.step += 1;

        if self.history.len() >= self.max_history {
            self.history.pop_front();
        }
        self.history.push_back(self.state);
    }

    /// Réinitialise l'écosystème à son état initial.
    pub fn reset(&mut self) {
        self.state = self.initial_state;
        self.time = 0.0;
        self.step = 0;
        self.history.clear();
        self.history.push_back(self.initial_state);
    }
}

