            (col_idx * (plot_width - 1)) / (history_len - 1)
        };

        // Projection Y (0 en bas, plot_height - 1 en haut)
        let prey_y = ((state.prey / max_val) * (plot_height - 1) as f64).round() as usize;
        let prey_row = (plot_height - 1).saturating_sub(prey_y.min(plot_height - 1));

        let pred_y = ((state.predator / max_val) * (plot_height - 1) as f64).round() as usize;
        let pred_row = (plot_height - 1).saturating_sub(pred_y.min(plot_height - 1));

        if prey_row == pred_row {
            grid[prey_row][screen_x] = 'X'; // Superposition
        } else {
            grid[prey_row][screen_x] = 'O'; // Proies
            grid[pred_row][screen_x] = '*'; // Prédateurs
        }
    }

    let mut lines = Vec::with_capacity(plot_height);
    for (row_idx, row_chars) in grid.iter().enumerate() {
        let y_val = max_val * (1.0 - (row_idx as f64 / (plot_height - 1).max(1) as f64));
        let content: String = row_chars.iter().collect();
        lines.push(format!("{:>5.1} |{}", y_val, content));
    }

    lines
}

/// Boucle principale en mode interactif avec rendu plein écran dans le terminal.
fn run_interactive(args: CliArgs) -> io::Result<()> {
    let _session = TerminalSession::enter()?;
    let mut stdout_handle = stdout();

    let params = ModelParams {
        alpha: args.alpha,
        beta: args.beta,
        gamma: args.gamma,
        delta: args.delta,
    };
    let initial_state = PopulationState::new(args.prey_init, args.pred_init);
    let mut sim = EcosystemSimulator::new(params, initial_state, args.dt, 100);

    let frame_interval = Duration::from_micros(1_000_000 / args.fps.max(1));
    let mut is_paused = false;

    loop {
        let frame_start = Instant::now();

        // 1. Gestion des événements clavier non-bloquants
        while event::poll(Duration::from_millis(0))? {
            if let Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press {
                    match key.code {
                        KeyCode::Char('q') | KeyCode::Esc => return Ok(()),
                        KeyCode::Char(' ') => is_paused = !is_paused,
                        KeyCode::Char('s') => {
                            if is_paused {
                                sim.step();
                            }
                        }
                        KeyCode::Char('r') => sim.reset(),
                        KeyCode::Char('+') | KeyCode::Up => {
                            sim.dt = (sim.dt * 1.25).min(0.5);
                        }
                        KeyCode::Char('-') | KeyCode::Down => {
                            sim.dt = (sim.dt * 0.8).max(0.001);
                        }
                        _ => {}
                    }
                }
            }
        }

        // 2. Progression temporelle si non en pause
        if !is_paused {
            sim.step();
        }

        // Vérification de la condition d'arrêt par étape maximale
        if let Some(max_s) = args.max_steps {
            if sim.step >= max_s {
                return Ok(());
            }
        }

        // 3. Rendu de l'interface
        execute!(stdout_handle, MoveTo(0, 0))?;

        // En-tête
        execute!(
            stdout_handle,
            SetForegroundColor(Color::Cyan),
            Print("╔══════════════════════════════════════════════════════════════════════════════╗\n\r"),
            Print("║          SIMULATEUR D'ÉCOSYSTÈME PROIES-PRÉDATEURS (LOTKA-VOLTERRA)          ║\n\r"),
            Print("╚══════════════════════════════════════════════════════════════════════════════╝\n\r"),
            ResetColor
        )?;

        // Métriques instantanées
        let status_str = if is_paused { "EN PAUSE" } else { "ACTIF" };
        let status_color = if is_paused {
            Color::Yellow
        } else {
            Color::Green
        };

        print!("État : ");
        execute!(
            stdout_handle,
            SetForegroundColor(status_color),
            Print(status_str),
            ResetColor
        )?;
        println!(
            "  |  Étape : {:<8} | Temps sim : {:>7.2}s | dt : {:>6.4}s",
            sim.step, sim.time, sim.dt
        );
        print!("\r");

        println!(
            "Paramètres : α={:.2} (proie+), β={:.3} (prédation), γ={:.2} (préd-), δ={:.3} (préd+)\r",
            sim.params.alpha, sim.params.beta, sim.params.gamma, sim.params.delta
        );
        println!(
            "--------------------------------------------------------------------------------\r"
        );

        // Jauges dynamiques
        let gauge_max = (sim.state.prey.max(sim.state.predator) * 1.5).max(50.0);
        let prey_gauge = render_gauge("Proies (O)", sim.state.prey, gauge_max, 40);
        let pred_gauge = render_gauge("Prédateurs (*)", sim.state.predator, gauge_max, 40);

        execute!(
            stdout_handle,
            SetForegroundColor(Color::Green),
            Print(prey_gauge),
            ResetColor,
            Print("\n\r")
        )?;
        execute!(
            stdout_handle,
            SetForegroundColor(Color::Red),
            Print(pred_gauge),
            ResetColor,
            Print("\n\r")
        )?;
        println!(
            "--------------------------------------------------------------------------------\r"
        );

        // Graphique temporel ASCII
        println!(
            "Historique temporel des populations (O: Proies, *: Prédateurs, X: Croisement) :\r"
        );
        let chart_lines = draw_ascii_chart(&sim.history, 65, 12);
        for line in chart_lines {
            println!("{}\r", line);
        }
        println!("      └{}", "─".repeat(66));
        println!("      Temps écoulé ────────────────────────────────────────────────────────►\r");

        println!(
            "--------------------------------------------------------------------------------\r"
        );
        execute!(
            stdout_handle,
            SetForegroundColor(Color::DarkGrey),
            Print("Contrôles : [ESPACE] Pause/Reprise  [S] Pas à pas  [+] Accélérer  [-] Décélérer\n\r"),
            Print("            [R] Réinitialiser       [Q / Echap] Quitter\n\r"),
            ResetColor
        )?;

        stdout_handle.flush()?;

        // 4. Régulation de la cadence (FPS)
        let elapsed = frame_start.elapsed();
        if elapsed < frame_interval {
            std::thread::sleep(frame_interval - elapsed);
        }
    }
}

/// Boucle en mode headless : affiche les métriques sous forme de flux tabulaire CSV/texte.
fn run_headless(args: CliArgs) -> io::Result<()> {
    let params = ModelParams {
        alpha: args.alpha,
        beta: args.beta,
        gamma: args.gamma,
        delta: args.delta,
    };
    let initial_state = PopulationState::new(args.prey_init, args.pred_init);
    let mut sim = EcosystemSimulator::new(params, initial_state, args.dt, 10);

    let max_steps = args.max_steps.unwrap_or(200);

    println!("# Écosystème Lotka-Volterra - Mode Headless");
    println!(
        "# Paramètres: alpha={}, beta={}, gamma={}, delta={}, dt={}",
        params.alpha, params.beta, params.gamma, params.delta, sim.dt
    );
    println!("step\ttime\tprey\tpredator");

    for _ in 0..max_steps {
        println!(
            "{}\t{:.4}\t{:.4}\t{:.4}",
            sim.step, sim.time, sim.state.prey, sim.state.predator
        );
        sim.step();
    }

    Ok(())
}

fn main() -> io::Result<()> {
    let args = CliArgs::parse();

    if args.headless {
        run_headless(args)
    } else {
        run_interactive(args)
    }
}

