// src/main.rs
use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::process;

/// Erreurs possibles lors de la compilation ou de l'exécution Brainfuck.
#[derive(Debug)]
pub enum BrainfuckError {
    UnmatchedOpenBracket(usize),
    UnmatchedCloseBracket(usize),
    Io(io::Error),
}

impl std::fmt::Display for BrainfuckError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::UnmatchedOpenBracket(pos) => {
                write!(f, "Erreur de syntaxe: crochet ouvrant '[' sans fermeture à la position {}", pos)
            }
            Self::UnmatchedCloseBracket(pos) => {
                write!(f, "Erreur de syntaxe: crochet fermant ']' inattendu à la position {}", pos)
            }
            Self::Io(err) => write!(f, "Erreur I/O: {}", err),
        }
    }
}

impl std::error::Error for BrainfuckError {}

impl From<io::Error> for BrainfuckError {
    fn from(err: io::Error) -> Self {
        Self::Io(err)
    }
}

/// Instructions de la Représentation Intermédiaire (IR) avec fusions et idiomes optimisés.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Instruction {
    /// Additionne une valeur modulo 256 à la cellule courante.
    Add(u8),
    /// Déplace le pointeur mémoire d'un décalage relatif.
    Move(isize),
    /// Affiche la valeur de la cellule courante N fois.
    Output(usize),
    /// Lit un octet depuis l'entrée standard et l'écrit dans la cellule courante.
    Input,
    /// Optimisation `[-]` ou `[+]` : remet la cellule courante à zéro en O(1).
    Clear,
    /// Optimisation `[->+<]` ou `[->+++<]` : ajoute `cellule_courante * facteur` aux cellules cibles relatives en O(1).
    MulAdd {
        /// Clé: décalage relatif, Valeur: multiplicateur modulo 256.
        targets: Vec<(isize, u8)>,
    },
    /// Optimisation `[>]` ou `[<]` : avance jusqu'à trouver une cellule nulle.
    Scan(isize),
    /// Boucle générique contenant un bloc d'instructions.
    Loop(Vec<Instruction>),
}

/// Ruban mémoire infini bidirectionnel indexé sur Z (négatif et positif).
#[derive(Debug, Default, Clone)]
pub struct Tape {
    positive: Vec<u8>,
    negative: Vec<u8>,
    pointer: isize,
}

impl Tape {
    /// Crée un ruban initialisé avec une cellule à zéro à l'origine.
    #[must_use]
    pub fn new() -> Self {
        Self {
            positive: vec![0],
            negative: Vec::new(),
            pointer: 0,
        }
    }

    /// Déplace la tête de lecture/écriture.
    pub fn shift(&mut self, offset: isize) {
        self.pointer = self.pointer.saturating_add(offset);
    }

    /// Récupère la valeur de la cellule courante.
    #[must_use]
    pub fn get(&mut self) -> u8 {
        self.get_at(self.pointer)
    }

    /// Définit la valeur de la cellule courante.
    pub fn set(&mut self, val: u8) {
        self.set_at(self.pointer, val);
    }

    /// Modifie la valeur de la cellule courante par addition modulaire.
    pub fn add(&mut self, delta: u8) {
        let current = self.get();
        self.set(current.wrapping_add(delta));
    }

    /// Récupère la valeur à une position absolue donnée (auto-extensible).
    pub fn get_at(&mut self, index: isize) -> u8 {
        if index >= 0 {
            let idx = index as usize;
            if idx >= self.positive.len() {
                self.positive.resize(idx + 1, 0);
            }
            self.positive[idx]
        } else {
            let idx = (-index - 1) as usize;
            if idx >= self.negative.len() {
                self.negative.resize(idx + 1, 0);
            }
            self.negative[idx]
        }
    }

    /// Modifie la valeur à une position absolue donnée (auto-extensible).
    pub fn set_at(&mut self, index: isize, val: u8) {
        if index >= 0 {
            let idx = index as usize;
            if idx >= self.positive.len() {
                self.positive.resize(idx + 1, 0);
            }
            self.positive[idx] = val;
        } else {
            let idx = (-index - 1) as usize;
            if idx >= self.negative.len() {
                self.negative.resize(idx + 1, 0);
            }
            self.negative[idx] = val;
        }
    }

    /// Modifie la valeur à une position relative par rapport au pointeur courant.
    pub fn add_at_offset(&mut self, offset: isize, delta: u8) {
        let target_idx = self.pointer.saturating_add(offset);
        let current = self.get_at(target_idx);
        self.set_at(target_idx, current.wrapping_add(delta));
    }

    /// Scanne dans une direction donnée jusqu'à atteindre une cellule nulle.
    pub fn scan_to_zero(&mut self, step: isize) {
        if step == 0 {
            return;
        }
        while self.get() != 0 {
            self.shift(step);
        }
    }
}

/// Analyseur et compilateur IR avec optimiseur de boucles.
pub struct Compiler;

impl Compiler {
    /// Compile une chaîne de code source Brainfuck en instructions IR optimisées.
    pub fn compile(source: &str) -> Result<Vec<Instruction>, BrainfuckError> {
        let mut loop_stack: Vec<(usize, Vec<Instruction>)> = Vec::new();
        let mut current_block: Vec<Instruction> = Vec::new();

        let chars: Vec<char> = source.chars().collect();
        let mut i = 0;

        while i < chars.len() {
            match chars[i] {
                '+' | '-' => {
                    let mut delta: u8 = 0;
                    while i < chars.len() && (chars[i] == '+' || chars[i] == '-') {
                        if chars[i] == '+' {
                            delta = delta.wrapping_add(1);
                        } else {
                            delta = delta.wrapping_sub(1);
                        }
                        i += 1;
                    }
                    if delta != 0 {
                        Self::push_add(&mut current_block, delta);
                    }
                    continue;
                }
                '>' | '<' => {
                    let mut offset: isize = 0;
                    while i < chars.len() && (chars[i] == '>' || chars[i] == '<') {
                        if chars[i] == '>' {
                            offset = offset.saturating_add(1);
                        } else {
                            offset = offset.saturating_sub(1);
                        }
                        i += 1;
                    }
                    if offset != 0 {
                        Self::push_move(&mut current_block, offset);
                    }
                    continue;
                }
                '.' => {
                    let mut count = 0;
                    while i < chars.len() && chars[i] == '.' {
                        count += 1;
                        i += 1;
                    }
                    current_block.push(Instruction::Output(count));
                    continue;
                }
                ',' => {
                    current_block.push(Instruction::Input);
                }
                '[' => {
                    loop_stack.push((i, current_block));
                    current_block = Vec::new();
                }
                ']' => {
                    if let Some((_open_pos, mut parent_block)) = loop_stack.pop() {
                        let optimized = Self::optimize_loop(current_block);
                        parent_block.push(optimized);
                        current_block = parent_block;
                    } else {
                        return Err(BrainfuckError::UnmatchedCloseBracket(i));
                    }
                }
                _ => {
                    // Les caractères hors alphabet Brainfuck sont traités comme commentaires.
                }
            }
            i += 1;
        }

        if let Some((open_pos, _)) = loop_stack.pop() {
            return Err(BrainfuckError::UnmatchedOpenBracket(open_pos));
        }

        Ok(current_block)
    }

    fn push_add(block: &mut Vec<Instruction>, delta: u8) {
        if let Some(Instruction::Add(prev)) = block.last_mut() {
            *prev = prev.wrapping_add(delta);
            if *prev == 0 {
                block.pop();
            }
        } else {
            block.push(Instruction::Add(delta));
        }
    }

    fn push_move(block: &mut Vec<Instruction>, offset: isize) {
        if let Some(Instruction::Move(prev)) = block.last_mut() {
            *prev = prev.saturating_add(offset);
            if *prev == 0 {
                block.pop();
            }
        } else {
            block.push(Instruction::Move(offset));
        }
    }

    /// Optimise les boucles simples reconnues (Clear, MulAdd, Scan).
    fn optimize_loop(instructions: Vec<Instruction>) -> Instruction {
        // 1. Idiome Clear : `[-]` ou `[+]` -> Instruction::Clear
        if instructions.len() == 1 {
            match instructions[0] {
                Instruction::Add(d) if d % 2 == 1 => return Instruction::Clear,
                Instruction::Scan(step) => return Instruction::Scan(step),
                Instruction::Move(step) => return Instruction::Scan(step),
                _ => {}
            }
        }

        // 2. Idiome Scan : boucle contenant uniquement des déplacements
        // Exemple: `[>]` ou `[<<<]`
        if instructions.iter().all(|instr| matches!(instr, Instruction::Move(_))) {
            let total_move: isize = instructions
                .iter()
                .filter_map(|instr| if let Instruction::Move(m) = instr { Some(*m) } else { None })
                .sum();
            if total_move != 0 {
                return Instruction::Scan(total_move);
            }
        }

        // 3. Idiome Multiplication / Déplacement linéaire :
        // Exemple: `[->++<]` ou `[->+>+++<<]`
        // Conditions :
        // - Contient uniquement des Add et Move
        // - Le déplacement net total est 0 (revient à la case de départ)
        // - La cellule de départ (offset 0) est décrémentée de 1 au total (`-1` ou `255`)
        let mut net_move: isize = 0;
        let mut changes: HashMap<isize, u8> = HashMap::new();
        let mut is_linear = true;

        for instr in &instructions {
            match instr {
                Instruction::Add(delta) => {
                    let entry = changes.entry(net_move).or_insert(0);
                    *entry = entry.wrapping_add(*delta);
                }
                Instruction::Move(delta) => {
                    net_move = net_move.saturating_add(*delta);
                }
                _ => {
                    is_linear = false;
                    break;
                }
            }
        }

        if is_linear && net_move == 0 {
            if let Some(&origin_change) = changes.get(&0) {
                // Décrément unitaire de la cellule de boucle (255 modulo 256)
                if origin_change == 255 {
                    let mut targets = Vec::new();
                    for (offset, factor) in changes {
                        if offset != 0 && factor != 0 {
                            targets.push((offset, factor));
                        }
                    }
                    targets.sort_by_key(|t| t.0);
                    return Instruction::MulAdd { targets };
                }
            }
        }

        Instruction::Loop(instructions)
    }
}

/// Machine virtuelle d'exécution Brainfuck.
pub struct Interpreter<R, W> {
    tape: Tape,
    reader: R,
    writer: W,
}

impl<R: Read, W: Write> Interpreter<R, W> {
    /// Crée un interpréteur avec les flux I/O donnés.
    pub fn new(reader: R, writer: W) -> Self {
        Self {
            tape: Tape::new(),
            reader,
            writer,
        }
    }

    /// Exécute un ensemble d'instructions Brainfuck.
    pub fn run(&mut self, instructions: &[Instruction]) -> Result<(), BrainfuckError> {
        for instr in instructions {
            match instr {
                Instruction::Add(delta) => {
                    self.tape.add(*delta);
                }
                Instruction::Move(offset) => {
                    self.tape.shift(*offset);
                }
                Instruction::Output(count) => {
                    let val = self.tape.get();
                    let buf = vec![val; *count];
                    self.writer.write_all(&buf)?;
                }
                Instruction::Input => {
                    let mut buf = [0u8; 1];
                    match self.reader.read(&mut buf) {
                        Ok(1) => self.tape.set(buf[0]),
                        Ok(0) => {
                            // EOF standard : conserve la valeur actuelle ou 0 selon convention courante (0 ici).
                            self.tape.set(0);
                        }
                        Ok(_) => unreachable!(),
                        Err(e) if e.kind() == io::ErrorKind::Interrupted => {
                            // En cas d'interruption temporaire, réessaie une lecture unitaire.
                            let mut single = [0u8; 1];
                            if self.reader.read_exact(&mut single).is_ok() {
                                self.tape.set(single[0]);
                            } else {
                                self.tape.set(0);
                            }
                        }
                        Err(e) => return Err(BrainfuckError::Io(e)),
                    }
                }
                Instruction::Clear => {
                    self.tape.set(0);
                }
                Instruction::MulAdd { targets } => {
                    let current = self.tape.get();
                    if current != 0 {
                        for &(offset, factor) in targets {
                            let product = current.wrapping_mul(factor);
                            self.tape.add_at_offset(offset, product);
                        }
                        self.tape.set(0);
                    }
                }
                Instruction::Scan(step) => {
                    self.tape.scan_to_zero(*step);
                }
                Instruction::Loop(body) => {
                    while self.tape.get() != 0 {
                        self.run(body)?;
                    }
                }
            }
        }
        self.writer.flush()?;
        Ok(())
    }

    /// Retourne une référence vers le ruban interne (utile pour les tests et l'inspection).
    #[must_use]
    pub fn tape(&self) -> &Tape {
        &self.tape
    }
}

fn print_usage(program_name: &str) {
    eprintln!("Usage: {} [OPTIONS] <fichier.bf>", program_name);
    eprintln!("Interpréteur Brainfuck hautement optimisé.");
    eprintln!();
    eprintln!("Options:");
    eprintln!("  -e, --eval <code>   Exécute directement la chaîne de code fournie");
    eprintln!("  -h, --help          Affiche cette aide");
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let program_name = args.first().map(String::as_str).unwrap_or("brainfuck");

    if args.len() < 2 {
        print_usage(program_name);
        process::exit(1);
    }

    let code = match args[1].as_str() {
        "-h" | "--help" => {
            print_usage(program_name);
            return;
        }
        "-e" | "--eval" => {
            if args.len() < 3 {
                eprintln!("Erreur: option -e requiert une chaîne de code Brainfuck.");
                process::exit(1);
            }
            args[2].clone()
        }
        filename => match fs::read_to_string(filename) {
            Ok(content) => content,
            Err(e) => {
                eprintln!("Erreur lors de la lecture du fichier '{}': {}", filename, e);
                process::exit(1);
            }
        },
    };

    let instructions = match Compiler::compile(&code) {
        Ok(instrs) => instrs,
        Err(err) => {
            eprintln!("{}", err);
            process::exit(1);
        }
    };

    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut interpreter = Interpreter::new(stdin.lock(), stdout.lock());

    if let Err(err) = interpreter.run(&instructions) {
        eprintln!("Erreur d'exécution: {}", err);
        process::exit(1);
    }
}

