/// Conteneur générique thread-safe pour les valeurs produites par les tâches.
#[derive(Clone)]
pub struct TaskValue(Arc<dyn Any + Send + Sync>);

impl TaskValue {
    pub fn new<T: Any + Send + Sync>(val: T) -> Self {
        Self(Arc::new(val))
    }

    pub fn downcast<T: Any + Send + Sync>(&self) -> Option<&T> {
