#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_topological_sort_linear() {
        let mut graph = TaskGraph::new();
        graph
            .add_task("A", vec![], |_| async { Ok(TaskValue::new(1)) })
            .unwrap();
        graph
            .add_task("B", vec![TaskId::new("A")], |_| async { Ok(TaskValue::new(2)) })
            .unwrap();
        graph
            .add_task("C", vec![TaskId::new("B")], |_| async { Ok(TaskValue::new(3)) })
            .unwrap();

        let order = graph.topological_sort().unwrap();
        let names: Vec<String> = order.iter().map(|id| id.0.clone()).collect();
        assert_eq!(names, vec!["A", "B", "C"]);
    }

    #[test]
    fn test_cycle_detection() {
        let mut graph = TaskGraph::new();
        graph
            .add_task("A", vec![TaskId::new("B")], |_| async { Ok(TaskValue::new(1)) })
            .unwrap();
        graph
            .add_task("B", vec![TaskId::new("A")], |_| async { Ok(TaskValue::new(2)) })
            .unwrap();

        let result = graph.topological_sort();
        assert!(matches!(result, Err(GraphError::CycleDetected(_))));
    }

    #[test]
    fn test_missing_dependency() {
        let mut graph = TaskGraph::new();
        graph
            .add_task("A", vec![TaskId::new("Z")], |_| async { Ok(TaskValue::new(1)) })
            .unwrap();

        let result = graph.topological_sort();
        assert!(matches!(result, Err(GraphError::MissingDependency { .. })));
    }

    #[tokio::test]
    async fn test_diamond_execution_flow() {
        let mut graph = TaskGraph::new();

        graph
            .add_task("start", vec![], |_| async { Ok(TaskValue::new(10)) })
            .unwrap();

        graph
            .add_task("left", vec![TaskId::new("start")], |ctx| async move {
                let v = ctx.get::<i32>(&TaskId::new("start")).await.unwrap();
                Ok(TaskValue::new(v * 2))
            })
            .unwrap();

        graph
            .add_task("right", vec![TaskId::new("start")], |ctx| async move {
                let v = ctx.get::<i32>(&TaskId::new("start")).await.unwrap();
                Ok(TaskValue::new(v + 5))
            })
            .unwrap();

        graph
            .add_task("end", vec![TaskId::new("left"), TaskId::new("right")], |ctx| async move {
                let l = ctx.get::<i32>(&TaskId::new("left")).await.unwrap();
                let r = ctx.get::<i32>(&TaskId::new("right")).await.unwrap();
                Ok(TaskValue::new(l + r))
            })
            .unwrap();

        let executor = GraphExecutor::new(2);
        let ctx = executor.execute(graph).await.unwrap();

        let end_val = ctx.get::<i32>(&TaskId::new("end")).await.unwrap();
        // start = 10, left = 20, right = 15, end = 35
        assert_eq!(end_val, 35);
    }

    #[tokio::test]
    async fn test_failure_propagation() {
        let mut graph = TaskGraph::new();

        graph
            .add_task("fail_source", vec![], |_| async {
                Err("Erreur irrécupérable de connexion".to_string())
            })
            .unwrap();

        graph
            .add_task("dependent_child", vec![TaskId::new("fail_source")], |_| async {
                Ok(TaskValue::new(42))
            })
            .unwrap();

        let executor = GraphExecutor::new(2);
        let result = executor.execute(graph).await;

        assert!(matches!(result, Err(GraphError::TaskExecutionFailed { .. })));
    }
