    }
}

/// Erreurs possibles lors de la construction, validation et exécution du graphe.
#[derive(Error, Debug, Clone)]
pub enum GraphError {
    #[error("Dépendance manquante : la tâche '{task}' requiert '{dependency}', qui n'existe pas")]
    MissingDependency { task: TaskId, dependency: TaskId },

    #[error("Cycle détecté dans le graphe impliquant les tâches : {0:?}")]
    CycleDetected(Vec<TaskId>),

    #[error("Tâche introuvable : '{0}'")]
    TaskNotFound(TaskId),

    #[error("Échec de la tâche '{task}' : {reason}")]
    TaskExecutionFailed { task: TaskId, reason: String },

    #[error("La tâche '{task}' a été annulée car sa dépendance '{dependency}' a échoué")]
    DependencyFailed { task: TaskId, dependency: TaskId },

    #[error("Conflit : la tâche '{0}' existe déjà dans le graphe")]
    DuplicateTask(TaskId),
}

/// Contexte partagé accessible en lecture par chaque tâche lors de son exécution.
#[derive(Default)]
pub struct ExecutionContext {
    outputs: RwLock<HashMap<TaskId, TaskValue>>,
}

impl ExecutionContext {
    pub fn new() -> Self {
        Self {
            outputs: RwLock::new(HashMap::new()),
        }
    }

    /// Récupère la valeur produite par une tâche parente.
    pub async fn get<T: Any + Send + Sync>(&self, task_id: &TaskId) -> Option<T>
    where
        T: Clone,
    {
        let guard = self.outputs.read().await;
        guard.get(task_id).and_then(|val| val.downcast::<T>().cloned())
    }

    /// Enregistre le résultat produit par une tâche.
    pub async fn insert(&self, task_id: TaskId, value: TaskValue) {
        let mut guard = self.outputs.write().await;
        guard.insert(task_id, value);
    }
}

pub type TaskFuture = Pin<Box<dyn Future<Output = Result<TaskValue, String>> + Send>>;
pub type TaskAction = Box<dyn Fn(Arc<ExecutionContext>) -> TaskFuture + Send + Sync>;

/// Représentation d'une unité de travail au sein du graphe.
pub struct Task {
    pub id: TaskId,
    pub dependencies: Vec<TaskId>,
    pub action: TaskAction,
}

// ============================================================================
// Graphe de Tâches & Validation Topologique
// ============================================================================

/// Constructeur et conteneur du graphe de tâches acyclique.
pub struct TaskGraph {
    tasks: HashMap<TaskId, Task>,
}

impl Default for TaskGraph {
    fn default() -> Self {
        Self::new()
    }
}

impl TaskGraph {
    pub fn new() -> Self {
        Self {
            tasks: HashMap::new(),
        }
    }

    /// Ajoute une tâche et ses dépendances au graphe.
    pub fn add_task<F, Fut>(&mut self, id: impl Into<TaskId>, dependencies: Vec<TaskId>, action: F) -> Result<(), GraphError>
    where
        F: Fn(Arc<ExecutionContext>) -> Fut + Send + Sync + 'static,
        Fut: Future<Output = Result<TaskValue, String>> + Send + 'static,
    {
        let task_id = id.into();
        if self.tasks.contains_key(&task_id) {
            return Err(GraphError::DuplicateTask(task_id));
        }

        let boxed_action: TaskAction = Box::new(move |ctx| Box::pin(action(ctx)));

        self.tasks.insert(
            task_id.clone(),
            Task {
                id: task_id,
                dependencies,
                action: boxed_action,
            },
        );

        Ok(())
    }

    /// Valide l'intégrité du graphe et retourne l'ordre topologique via l'algorithme de Kahn.
    pub fn topological_sort(&self) -> Result<Vec<TaskId>, GraphError> {
        let mut in_degree: HashMap<&TaskId, usize> = HashMap::new();
        let mut dependents: HashMap<&TaskId, Vec<&TaskId>> = HashMap::new();

        for (id, task) in &self.tasks {
            in_degree.entry(id).or_insert(0);
            for dep in &task.dependencies {
                if !self.tasks.contains_key(dep) {
                    return Err(GraphError::MissingDependency {
                        task: id.clone(),
                        dependency: dep.clone(),
                    });
                }
                dependents.entry(dep).or_default().push(id);
                *in_degree.entry(id).or_insert(0) += 1;
            }
        }

        let mut queue: VecDeque<&TaskId> = in_degree
            .iter()
            .filter_map(|(id, &deg)| if deg == 0 { Some(*id) } else { None })
            .collect();

        let mut sorted = Vec::new();

        while let Some(current) = queue.pop_front() {
            sorted.push(current.clone());

            if let Some(children) = dependents.get(current) {
                for child in children {
                    if let Some(deg) = in_degree.get_mut(child) {
                        *deg -= 1;
                        if *deg == 0 {
                            queue.push_back(child);
                        }
                    }
                }
            }
        }

        if sorted.len() != self.tasks.len() {
            let cyclic_tasks: Vec<TaskId> = in_degree
                .into_iter()
                .filter_map(|(id, deg)| if deg > 0 { Some(id.clone()) } else { None })
                .collect();
            return Err(GraphError::CycleDetected(cyclic_tasks));
        }

        Ok(sorted)
    }

    /// Regroupe les tâches par niveaux topologiques parallèles (tiers).
    pub fn topological_tiers(&self) -> Result<Vec<Vec<TaskId>>, GraphError> {
        // Validation des dépendances et détection préalable de cycles
        self.topological_sort()?;

        let mut levels: HashMap<TaskId, usize> = HashMap::new();
        let mut dependents: HashMap<TaskId, Vec<TaskId>> = HashMap::new();
        let mut in_degree: HashMap<TaskId, usize> = HashMap::new();

        for (id, task) in &self.tasks {
            in_degree.insert(id.clone(), task.dependencies.len());
            for dep in &task.dependencies {
                dependents.entry(dep.clone()).or_default().push(id.clone());
            }
        }

        let mut queue: VecDeque<TaskId> = in_degree
            .iter()
            .filter_map(|(id, &deg)| if deg == 0 { Some(id.clone()) } else { None })
            .collect();

        for root in &queue {
            levels.insert(root.clone(), 0);
        }

        while let Some(current) = queue.pop_front() {
            let current_level = levels.get(&current).copied().unwrap_or(0);
            if let Some(children) = dependents.get(&current) {
                for child in children {
                    let child_level = levels.entry(child.clone()).or_insert(0);
                    *child_level = (*child_level).max(current_level + 1);

                    if let Some(deg) = in_degree.get_mut(child) {
                        *deg -= 1;
                        if *deg == 0 {
                            queue.push_back(child.clone());
                        }
                    }
                }
            }
        }

        let mut max_level = 0;
        for &lvl in levels.values() {
            if lvl > max_level {
                max_level = lvl;
            }
        }

        let mut tiers = vec![Vec::new(); max_level + 1];
        for (id, lvl) in levels {
            tiers[lvl].push(id);
        }

        for tier in &mut tiers {
            tier.sort();
        }

        Ok(tiers)
    }
}

// ============================================================================
// Moteur d'Exécution Réactif et Concurrente
// ============================================================================

/// Moteur responsable de l'orchestration des tâches asynchrones.
pub struct GraphExecutor {
    max_concurrency: usize,
}

impl GraphExecutor {
    pub fn new(max_concurrency: usize) -> Self {
        Self {
            max_concurrency: max_concurrency.max(1),
        }
    }

    /// Exécute l'intégralité du graphe en respectant les dépendances avec parallélisme dynamique.
    pub async fn execute(self, graph: TaskGraph) -> Result<Arc<ExecutionContext>, GraphError> {
        // Valide l'absence de cycles et dépendances inconnues
        graph.topological_sort()?;

        let context = Arc::new(ExecutionContext::new());
        let semaphore = Arc::new(Semaphore::new(self.max_concurrency));

        // Structures de contrôle d'état
        let mut dependents: HashMap<TaskId, Vec<TaskId>> = HashMap::new();
        let mut remaining_dependencies: HashMap<TaskId, usize> = HashMap::new();

        for (id, task) in &graph.tasks {
            remaining_dependencies.insert(id.clone(), task.dependencies.len());
            for dep in &task.dependencies {
                dependents.entry(dep.clone()).or_default().push(id.clone());
            }
        }

        let tasks = Arc::new(graph.tasks);
        let (tx, mut rx) = tokio::sync::mpsc::channel::<(TaskId, Result<TaskValue, String>)>(tasks.len());

        let mut ready_tasks = Vec::new();
        for (id, &count) in &remaining_dependencies {
            if count == 0 {
                ready_tasks.push(id.clone());
            }
        }

        let mut completed_count = 0;
        let mut failed_tasks: HashMap<TaskId, String> = HashMap::new();
        let mut skipped_tasks: HashSet<TaskId> = HashSet::new();
        let total_tasks = tasks.len();

        // Lancement des tâches racines
        for task_id in ready_tasks {
            self.spawn_task(&task_id, &tasks, &context, &semaphore, tx.clone());
        }

        // Boucle réactive de résolution d'événements
        while completed_count < total_tasks {
            if let Some((task_id, result)) = rx.recv().await {
                completed_count += 1;

                match result {
                    Ok(val) => {
                        info!("Tâche terminée avec succès : [{task_id}]");
                        context.insert(task_id.clone(), val).await;

                        // Vérification des dépendants libérés
                        if let Some(children) = dependents.get(&task_id) {
                            for child in children {
                                if skipped_tasks.contains(child) {
                                    continue;
                                }

                                if let Some(rem) = remaining_dependencies.get_mut(child) {
                                    *rem -= 1;
                                    if *rem == 0 {
                                        self.spawn_task(child, &tasks, &context, &semaphore, tx.clone());
                                    }
                                }
                            }
                        }
                    }
                    Err(reason) => {
                        error!("Tâche en échec : [{task_id}] -> {reason}");
                        failed_tasks.insert(task_id.clone(), reason);

                        // Annulation en cascade des dépendants
                        let mut cascade_queue = VecDeque::new();
                        cascade_queue.push_back(task_id.clone());

                        while let Some(parent) = cascade_queue.pop_front() {
                            if let Some(children) = dependents.get(&parent) {
                                for child in children {
                                    if skipped_tasks.insert(child.clone()) {
                                        warn!("Tâche [{child}] annulée suite à l'échec de la dépendance [{parent}]");
                                        cascade_queue.push_back(child.clone());
                                        completed_count += 1;
                                    }
                                }
                            }
                        }
                    }
                }
            } else {
                break;
            }
        }

        if let Some((failed_id, reason)) = failed_tasks.into_iter().next() {
            return Err(GraphError::TaskExecutionFailed {
                task: failed_id,
                reason,
            });
        }

        Ok(context)
    }

    fn spawn_task(
        &self,
        task_id: &TaskId,
        tasks: &Arc<HashMap<TaskId, Task>>,
        context: &Arc<ExecutionContext>,
        semaphore: &Arc<Semaphore>,
        tx: tokio::sync::mpsc::Sender<(TaskId, Result<TaskValue, String>)>,
    ) {
        let task_id = task_id.clone();
        let tasks = Arc::clone(tasks);
        let context = Arc::clone(context);
        let sem = Arc::clone(semaphore);

        tokio::spawn(async move {
            let _permit = match sem.acquire().await {
                Ok(permit) => permit,
                Err(e) => {
                    let _ = tx.send((task_id, Err(format!("Sémaphore fermé: {e}")))).await;
                    return;
                }
            };

            info!("Démarrage de la tâche : [{task_id}]");

            let task = match tasks.get(&task_id) {
                Some(t) => t,
                None => {
                    let _ = tx.send((task_id.clone(), Err(format!("Tâche introuvable : {task_id}")))).await;
                    return;
                }
            };

            let result = (task.action)(context).await;
            let _ = tx.send((task_id, result)).await;
        });
    }
}

