#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    info!("=== Initialisation du moteur d'exécution de graphes de tâches ===");

    let mut graph = TaskGraph::new();

    // 1. Tâches sources (indépendantes)
    graph.add_task("fetch_users", vec![], |_ctx| async {
        info!("Récupération des utilisateurs depuis l'API...");
        tokio::time::sleep(Duration::from_millis(150)).await;
        let users = vec!["Alice", "Bob", "Charlie"];
        Ok(TaskValue::new(users))
    })?;

    graph.add_task("fetch_orders", vec![], |_ctx| async {
        info!("Extraction des commandes depuis la base SQL...");
        tokio::time::sleep(Duration::from_millis(200)).await;
        let orders = vec![101, 102, 103, 104];
        Ok(TaskValue::new(orders))
    })?;

    // 2. Tâches intermédiaires (dépendent des sources)
    graph.add_task("validate_users", vec![TaskId::new("fetch_users")], |ctx| async move {
        let users = ctx
            .get::<Vec<&'static str>>(&TaskId::new("fetch_users"))
            .await
            .ok_or_else(|| "Données 'fetch_users' absentes du contexte".to_string())?;

        info!("Validation de {} profils utilisateurs...", users.len());
        tokio::time::sleep(Duration::from_millis(100)).await;
        Ok(TaskValue::new(users.len()))
    })?;

    graph.add_task("compute_metrics", vec![TaskId::new("fetch_orders")], |ctx| async move {
        let orders = ctx
            .get::<Vec<i32>>(&TaskId::new("fetch_orders"))
            .await
            .ok_or_else(|| "Données 'fetch_orders' absentes du contexte".to_string())?;

        let total_sum: i32 = orders.iter().sum();
        info!("Calcul du chiffre d'affaires cumulé : {total_sum}€");
        tokio::time::sleep(Duration::from_millis(120)).await;
        Ok(TaskValue::new(total_sum))
    })?;

    // 3. Tâche finale d'agrégation (dépend de validate_users et compute_metrics)
    graph.add_task(
        "generate_report",
        vec![TaskId::new("validate_users"), TaskId::new("compute_metrics")],
        |ctx| async move {
            let user_count = ctx
                .get::<usize>(&TaskId::new("validate_users"))
                .await
                .ok_or_else(|| "Données 'validate_users' absentes".to_string())?;

            let total_revenue = ctx
                .get::<i32>(&TaskId::new("compute_metrics"))
                .await
                .ok_or_else(|| "Données 'compute_metrics' absentes".to_string())?;

            let report = format!(
                "Rapport Final : {} clients actifs validés, total commandes traitées = {}€",
                user_count, total_revenue
            );

            info!("Finalisation du rapport exécutif...");
            tokio::time::sleep(Duration::from_millis(80)).await;
            Ok(TaskValue::new(report))
        },
    )?;

    // Inspection des paliers topologiques
    let tiers = graph.topological_tiers()?;
    info!("--- Ordre d'exécution topologique par paliers ---");
    for (i, tier) in tiers.iter().enumerate() {
        let names: Vec<String> = tier.iter().map(|t| t.to_string()).collect();
        info!("Palier {i} : [{}]", names.join(", "));
    }

    // Exécution avec limite de concurrence de 4 tâches simultanées
    let executor = GraphExecutor::new(4);
    let context = executor.execute(graph).await?;

    let final_report = context
        .get::<String>(&TaskId::new("generate_report"))
        .await
        .ok_or_else(|| "Rapport final non trouvé dans le contexte")?;

    info!("Résultat : {final_report}");
    info!("=== Pipeline de graphe de tâches exécuté avec succès ===");

    Ok(())
}

