// 3. ARBRE DE SYNTAXE ABSTRAITE (AST) & PARSER DE FORMULES
// ==============================================================================

#[derive(Debug, Clone, PartialEq)]
pub enum BinaryOp {
    Add,
    Sub,
    Mul,
    Div,
    Eq,
    NotEq,
    Lt,
    Lte,
    Gt,
    Gte,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Expr {
    Literal(CellValue),
    Cell(CellCoord),
    Range(CellRange),
    Binary {
        op: BinaryOp,
        left: Box<Expr>,
        right: Box<Expr>,
    },
    UnaryNeg(Box<Expr>),
    Function {
        name: String,
        args: Vec<Expr>,
    },
}

impl Expr {
    /// Récupère toutes les cellules dont dépend cette expression
    pub fn collect_dependencies(&self, out: &mut HashSet<CellCoord>) {
        match self {
            Expr::Literal(_) => {}
            Expr::Cell(coord) => {
                out.insert(*coord);
            }
            Expr::Range(range) => {
                for c in range.cells() {
                    out.insert(c);
                }
            }
            Expr::Binary { left, right, .. } => {
                left.collect_dependencies(out);
                right.collect_dependencies(out);
            }
            Expr::UnaryNeg(sub) => {
                sub.collect_dependencies(out);
            }
            Expr::Function { args, .. } => {
                for arg in args {
                    arg.collect_dependencies(out);
                }
            }
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
enum Token {
    Number(f64),
    StringLiteral(String),
    Ident(String),
    Plus,
    Minus,
    Star,
    Slash,
    Equal,
    NotEqual,
    LessThan,
    LessOrEqual,
    GreaterThan,
    GreaterOrEqual,
    Colon,
    Comma,
    LParen,
    RParen,
}

struct Lexer<'a> {
    chars: std::iter::Peekable<std::str::Chars<'a>>,
}

impl<'a> Lexer<'a> {
    fn new(input: &'a str) -> Self {
        Self {
            chars: input.chars().peekable(),
        }
    }

    fn tokenize(&mut self) -> Result<Vec<Token>, SpreadsheetError> {
        let mut tokens = Vec::new();
        while let Some(&ch) = self.chars.peek() {
            if ch.is_whitespace() {
                self.chars.next();
                continue;
            }

            match ch {
                '+' => {
                    self.chars.next();
                    tokens.push(Token::Plus);
                }
                '-' => {
                    self.chars.next();
                    tokens.push(Token::Minus);
                }
                '*' => {
                    self.chars.next();
                    tokens.push(Token::Star);
                }
                '/' => {
                    self.chars.next();
                    tokens.push(Token::Slash);
                }
                '(' => {
                    self.chars.next();
                    tokens.push(Token::LParen);
                }
                ')' => {
                    self.chars.next();
                    tokens.push(Token::RParen);
                }
                ',' | ';' => {
                    self.chars.next();
                    tokens.push(Token::Comma);
                }
                ':' => {
                    self.chars.next();
                    tokens.push(Token::Colon);
                }
                '=' => {
                    self.chars.next();
                    tokens.push(Token::Equal);
                }
                '<' => {
                    self.chars.next();
                    if let Some(&'>') = self.chars.peek() {
                        self.chars.next();
                        tokens.push(Token::NotEqual);
                    } else if let Some(&'=') = self.chars.peek() {
                        self.chars.next();
                        tokens.push(Token::LessOrEqual);
                    } else {
                        tokens.push(Token::LessThan);
                    }
                }
                '>' => {
                    self.chars.next();
                    if let Some(&'=') = self.chars.peek() {
                        self.chars.next();
                        tokens.push(Token::GreaterOrEqual);
                    } else {
                        tokens.push(Token::GreaterThan);
                    }
                }
                '"' => {
                    self.chars.next();
                    let mut s = String::new();
                    let mut closed = false;
                    while let Some(c) = self.chars.next() {
                        if c == '"' {
                            closed = true;
                            break;
                        }
                        s.push(c);
                    }
                    if !closed {
                        return Err(SpreadsheetError::ParseError("Chaîne littérale non fermée".to_string()));
                    }
                    tokens.push(Token::StringLiteral(s));
                }
                '0'..='9' | '.' => {
                    let mut num_str = String::new();
                    while let Some(&c) = self.chars.peek() {
                        if c.is_ascii_digit() || c == '.' {
                            num_str.push(c);
                            self.chars.next();
                        } else {
                            break;
                        }
                    }
                    let val = num_str.parse::<f64>().map_err(|_| {
                        SpreadsheetError::ParseError(format!("Nombre invalide: {}", num_str))
                    })?;
                    tokens.push(Token::Number(val));
                }
                _ if ch.is_alphabetic() || ch == '_' => {
                    let mut ident = String::new();
                    while let Some(&c) = self.chars.peek() {
                        if c.is_alphanumeric() || c == '_' {
                            ident.push(c);
                            self.chars.next();
                        } else {
                            break;
                        }
                    }
                    tokens.push(Token::Ident(ident));
                }
                _ => {
                    return Err(SpreadsheetError::ParseError(format!(
                        "Caractère inattendu: {}",
                        ch
                    )));
                }
            }
        }
        Ok(tokens)
    }
}

pub struct FormulaParser<'a> {
    tokens: &'a [Token],
    pos: usize,
}

impl<'a> FormulaParser<'a> {
    pub fn parse(input: &str) -> Result<Expr, SpreadsheetError> {
        let trimmed = input.trim();
        let formula = if let Some(stripped) = trimmed.strip_prefix('=') {
            stripped
        } else {
            trimmed
        };

        let mut lexer = Lexer::new(formula);
        let tokens = lexer.tokenize()?;
        let mut parser = FormulaParser {
            tokens: &tokens,
            pos: 0,
        };
        let expr = parser.parse_expression()?;
        if parser.pos < parser.tokens.len() {
            return Err(SpreadsheetError::ParseError(
                "Jetons supplémentaires en fin de formule".to_string(),
            ));
        }
        Ok(expr)
    }

    fn peek(&self) -> Option<&Token> {
        self.tokens.get(self.pos)
    }

    fn next_token(&mut self) -> Option<Token> {
        let tok = self.tokens.get(self.pos).cloned();
        if tok.is_some() {
            self.pos += 1;
        }
        tok
    }

    fn parse_expression(&mut self) -> Result<Expr, SpreadsheetError> {
        self.parse_comparison()
    }

    fn parse_comparison(&mut self) -> Result<Expr, SpreadsheetError> {
        let mut left = self.parse_additive()?;

        while let Some(tok) = self.peek() {
            let op = match tok {
                Token::Equal => BinaryOp::Eq,
                Token::NotEqual => BinaryOp::NotEq,
                Token::LessThan => BinaryOp::Lt,
                Token::LessOrEqual => BinaryOp::Lte,
                Token::GreaterThan => BinaryOp::Gt,
                Token::GreaterOrEqual => BinaryOp::Gte,
                _ => break,
            };
            self.next_token();
            let right = self.parse_additive()?;
            left = Expr::Binary {
                op,
                left: Box::new(left),
                right: Box::new(right),
            };
        }
        Ok(left)
    }

    fn parse_additive(&mut self) -> Result<Expr, SpreadsheetError> {
        let mut left = self.parse_multiplicative()?;

        while let Some(tok) = self.peek() {
            let op = match tok {
                Token::Plus => BinaryOp::Add,
                Token::Minus => BinaryOp::Sub,
                _ => break,
            };
            self.next_token();
            let right = self.parse_multiplicative()?;
            left = Expr::Binary {
                op,
                left: Box::new(left),
                right: Box::new(right),
            };
        }
        Ok(left)
    }

    fn parse_multiplicative(&mut self) -> Result<Expr, SpreadsheetError> {
        let mut left = self.parse_unary()?;

        while let Some(tok) = self.peek() {
            let op = match tok {
                Token::Star => BinaryOp::Mul,
                Token::Slash => BinaryOp::Div,
                _ => break,
            };
            self.next_token();
            let right = self.parse_unary()?;
            left = Expr::Binary {
                op,
                left: Box::new(left),
                right: Box::new(right),
            };
        }
        Ok(left)
    }

    fn parse_unary(&mut self) -> Result<Expr, SpreadsheetError> {
        if let Some(Token::Minus) = self.peek() {
            self.next_token();
            let sub = self.parse_primary()?;
            Ok(Expr::UnaryNeg(Box::new(sub)))
        } else if let Some(Token::Plus) = self.peek() {
            self.next_token();
            self.parse_primary()
        } else {
            self.parse_primary()
        }
    }

    fn parse_primary(&mut self) -> Result<Expr, SpreadsheetError> {
        match self.next_token() {
            Some(Token::Number(n)) => Ok(Expr::Literal(CellValue::Number(n))),
            Some(Token::StringLiteral(s)) => Ok(Expr::Literal(CellValue::Text(s))),
            Some(Token::LParen) => {
                let inner = self.parse_expression()?;
                match self.next_token() {
                    Some(Token::RParen) => Ok(inner),
                    _ => Err(SpreadsheetError::ParseError("Parenthèse fermante ')' manquante".to_string())),
                }
            }
            Some(Token::Ident(name)) => {
                let upper_name = name.to_uppercase();

                // Appel de fonction : ex SOMME(...)
                if let Some(Token::LParen) = self.peek() {
                    self.next_token(); // consume '('
                    let mut args = Vec::new();
                    if let Some(Token::RParen) = self.peek() {
                        self.next_token();
                        return Ok(Expr::Function {
                            name: upper_name,
                            args,
                        });
                    }

                    loop {
                        args.push(self.parse_expression()?);
                        match self.peek() {
                            Some(Token::Comma) => {
                                self.next_token();
                            }
                            Some(Token::RParen) => {
                                self.next_token();
                                break;
                            }
                            _ => {
                                return Err(SpreadsheetError::ParseError(
                                    "Attendu ',' ou ')' dans la liste d'arguments".to_string(),
                                ));
                            }
                        }
                    }
                    Ok(Expr::Function {
                        name: upper_name,
                        args,
                    })
                } else if let Ok(first_coord) = CellCoord::from_str(&upper_name) {
                    // Référence de cellule ou plage de cellules : A1 ou A1:B5
                    if let Some(Token::Colon) = self.peek() {
                        self.next_token(); // consume ':'
                        match self.next_token() {
                            Some(Token::Ident(second_ident)) => {
                                let second_coord = CellCoord::from_str(&second_ident.to_uppercase())?;
                                Ok(Expr::Range(CellRange::new(first_coord, second_coord)))
                            }
                            _ => Err(SpreadsheetError::ParseError(
                                "Attendu coordonnées de cellule après ':'".to_string(),
                            )),
                        }
                    } else {
                        Ok(Expr::Cell(first_coord))
                    }
                } else {
                    // Littéraux booléens
                    match upper_name.as_str() {
                        "VRAI" | "TRUE" => Ok(Expr::Literal(CellValue::Boolean(true))),
                        "FAUX" | "FALSE" => Ok(Expr::Literal(CellValue::Boolean(false))),
                        _ => Err(SpreadsheetError::ParseError(format!(
                            "Identifiant non reconnu: {}",
                            name
                        ))),
                    }
                }
            }
            Some(tok) => Err(SpreadsheetError::ParseError(format!(
                "Jeton inattendu: {:?}",
                tok
            ))),
            None => Err(SpreadsheetError::ParseError("Fin inattendue de l'expression".to_string())),
        }
    }
}

// ==============================================================================
// 4. GRAPHE DE DÉPENDANCES & FEUILLE DE CALCUL
// ==============================================================================

#[derive(Debug, Clone)]
pub enum CellContent {
    Raw(CellValue),
    Formula { raw: String, ast: Expr },
}

pub struct Spreadsheet {
    cells: HashMap<CellCoord, CellContent>,
    evaluated_values: HashMap<CellCoord, CellValue>,
}

impl Spreadsheet {
    pub fn new() -> Self {
        Self {
            cells: HashMap::new(),
            evaluated_values: HashMap::new(),
        }
    }

    /// Définit le contenu textuel d'une cellule (valeur directe ou formule précédée de '=')
    pub fn set_cell(&mut self, coord_str: &str, input: &str) -> Result<CellCoord, SpreadsheetError> {
        let coord = CellCoord::from_str(coord_str)?;
        let trimmed = input.trim();

        if trimmed.starts_with('=') {
            let ast = FormulaParser::parse(trimmed)?;
            self.cells.insert(
                coord,
                CellContent::Formula {
                    raw: trimmed.to_string(),
                    ast,
                },
            );
        } else if trimmed.is_empty() {
            self.cells.remove(&coord);
            self.evaluated_values.remove(&coord);
        } else if let Ok(num) = trimmed.parse::<f64>() {
            self.cells.insert(coord, CellContent::Raw(CellValue::Number(num)));
        } else if trimmed.eq_ignore_ascii_case("VRAI") || trimmed.eq_ignore_ascii_case("TRUE") {
            self.cells.insert(coord, CellContent::Raw(CellValue::Boolean(true)));
        } else if trimmed.eq_ignore_ascii_case("FAUX") || trimmed.eq_ignore_ascii_case("FALSE") {
            self.cells.insert(coord, CellContent::Raw(CellValue::Boolean(false)));
        } else {
            self.cells.insert(
                coord,
                CellContent::Raw(CellValue::Text(trimmed.to_string())),
            );
        }

        self.recalculate();
        Ok(coord)
    }

    pub fn get_value(&self, coord: CellCoord) -> CellValue {
        self.evaluated_values
            .get(&coord)
            .cloned()
            .unwrap_or(CellValue::Empty)
    }

    /// Construit le graphe de dépendances et recalcule les cellules dans l'ordre topologique.
    /// Détecte immédiatement les dépendances circulaires.
    pub fn recalculate(&mut self) {
        // Graphe orienté : A -> B (A dépend de B, c-à-d B doit être calculé avant A)
        // Pour l'ordre d'évaluation, nous utilisons:
        // depends_on: Cellule -> ensemble des cellules dont elle a besoin
        // dependents: Cellule -> ensemble des cellules qui ont besoin d'elle
        let mut depends_on: HashMap<CellCoord, HashSet<CellCoord>> = HashMap::new();
        let mut dependents: HashMap<CellCoord, HashSet<CellCoord>> = HashMap::new();

        // Récupérer toutes les cellules déclarées
        let all_coords: HashSet<CellCoord> = self.cells.keys().cloned().collect();

        for &coord in &all_coords {
            depends_on.entry(coord).or_default();
            dependents.entry(coord).or_default();

            if let Some(CellContent::Formula { ast, .. }) = self.cells.get(&coord) {
                let mut deps = HashSet::new();
                ast.collect_dependencies(&mut deps);
                for dep in deps {
                    depends_on.entry(coord).or_default().insert(dep);
                    dependents.entry(dep).or_default().insert(coord);
                }
            }
        }

        // Détection de cycles via algorithme de Kahn (Tri Topologique)
        // in_degree = nombre de dépendances non encore résolues
        let mut in_degree: HashMap<CellCoord, usize> = HashMap::new();
        for (node, deps) in &depends_on {
            in_degree.insert(*node, deps.len());
        }

        let mut queue = VecDeque::new();
        for (&node, &deg) in &in_degree {
            if deg == 0 {
                queue.push_back(node);
            }
        }

        let mut eval_order = Vec::new();
        while let Some(node) = queue.pop_front() {
            eval_order.push(node);
            if let Some(outgoing) = dependents.get(&node) {
                for &neighbor in outgoing {
                    if let Some(deg) = in_degree.get_mut(&neighbor) {
                        *deg = deg.saturating_sub(1);
                        if *deg == 0 {
                            queue.push_back(neighbor);
                        }
                    }
                }
            }
        }

        // Cellules faisant partie d'un cycle (in_degree > 0)
        let mut cycle_cells = HashSet::new();
        for (&node, &deg) in &in_degree {
            if deg > 0 {
                cycle_cells.insert(node);
            }
        }

        // Propagation de l'état d'erreur de cycle pour toutes les cellules en dépendant
        let mut cycle_propagated = cycle_cells.clone();
        let mut cycle_queue: VecDeque<CellCoord> = cycle_cells.iter().cloned().collect();
        while let Some(c) = cycle_queue.pop_front() {
            if let Some(deps) = dependents.get(&c) {
                for &d in deps {
                    if cycle_propagated.insert(d) {
                        cycle_queue.push_back(d);
                    }
                }
            }
        }

        // Nettoyage et recalcul séquentiel selon l'ordre topologique
        self.evaluated_values.clear();

        for coord in eval_order {
            if cycle_propagated.contains(&coord) {
                self.evaluated_values
                    .insert(coord, CellValue::Error(SpreadsheetError::CircularDependency));
                continue;
            }

            let val = match self.cells.get(&coord) {
                Some(CellContent::Raw(raw_val)) => raw_val.clone(),
                Some(CellContent::Formula { ast, .. }) => self.evaluate_ast(ast),
                None => CellValue::Empty,
            };
            self.evaluated_values.insert(coord, val);
        }

        // Affectation des erreurs de cycles résiduels
        for coord in cycle_propagated {
            self.evaluated_values
                .insert(coord, CellValue::Error(SpreadsheetError::CircularDependency));
        }
    }

    fn evaluate_ast(&self, expr: &Expr) -> CellValue {
        match expr {
            Expr::Literal(val) => val.clone(),
            Expr::Cell(coord) => self.get_value(*coord),
            Expr::Range(_) => CellValue::Error(SpreadsheetError::Value), // Une plage brute ne peut être évaluée comme scalaire
            Expr::UnaryNeg(sub) => match self.evaluate_ast(sub).as_number() {
                Ok(num) => CellValue::Number(-num),
                Err(e) => CellValue::Error(e),
            },
            Expr::Binary { op, left, right } => {
                let left_val = self.evaluate_ast(left);
                let right_val = self.evaluate_ast(right);

                match op {
                    BinaryOp::Add => match (left_val.as_number(), right_val.as_number()) {
                        (Ok(l), Ok(r)) => CellValue::Number(l + r),
                        (Err(e), _) | (_, Err(e)) => CellValue::Error(e),
                    },
                    BinaryOp::Sub => match (left_val.as_number(), right_val.as_number()) {
                        (Ok(l), Ok(r)) => CellValue::Number(l - r),
                        (Err(e), _) | (_, Err(e)) => CellValue::Error(e),
                    },
                    BinaryOp::Mul => match (left_val.as_number(), right_val.as_number()) {
                        (Ok(l), Ok(r)) => CellValue::Number(l * r),
                        (Err(e), _) | (_, Err(e)) => CellValue::Error(e),
                    },
                    BinaryOp::Div => match (left_val.as_number(), right_val.as_number()) {
                        (Ok(_), Ok(r)) if r == 0.0 => CellValue::Error(SpreadsheetError::DivisionByZero),
                        (Ok(l), Ok(r)) => CellValue::Number(l / r),
                        (Err(e), _) | (_, Err(e)) => CellValue::Error(e),
                    },
                    BinaryOp::Eq => CellValue::Boolean(left_val == right_val),
                    BinaryOp::NotEq => CellValue::Boolean(left_val != right_val),
                    BinaryOp::Lt => match (left_val.as_number(), right_val.as_number()) {
                        (Ok(l), Ok(r)) => CellValue::Boolean(l < r),
                        (Err(e), _) | (_, Err(e)) => CellValue::Error(e),
                    },
                    BinaryOp::Lte => match (left_val.as_number(), right_val.as_number()) {
                        (Ok(l), Ok(r)) => CellValue::Boolean(l <= r),
                        (Err(e), _) | (_, Err(e)) => CellValue::Error(e),
                    },
                    BinaryOp::Gt => match (left_val.as_number(), right_val.as_number()) {
                        (Ok(l), Ok(r)) => CellValue::Boolean(l > r),
                        (Err(e), _) | (_, Err(e)) => CellValue::Error(e),
                    },
                    BinaryOp::Gte => match (left_val.as_number(), right_val.as_number()) {
                        (Ok(l), Ok(r)) => CellValue::Boolean(l >= r),
                        (Err(e), _) | (_, Err(e)) => CellValue::Error(e),
                    },
                }
            }
            Expr::Function { name, args } => self.evaluate_function(name, args),
        }
    }

    fn evaluate_function(&self, name: &str, args: &[Expr]) -> CellValue {
        match name {
            "SOMME" | "SUM" => {
                let mut sum = 0.0;
                for arg in args {
                    for val in self.flatten_arg_values(arg) {
                        match val.as_number() {
                            Ok(num) => sum += num,
                            Err(e) => return CellValue::Error(e),
                        }
                    }
                }
                CellValue::Number(sum)
            }
            "MOYENNE" | "AVERAGE" => {
                let mut sum = 0.0;
                let mut count = 0usize;
                for arg in args {
                    for val in self.flatten_arg_values(arg) {
                        match val.as_number() {
                            Ok(num) => {
                                sum += num;
                                count += 1;
                            }
                            Err(e) => return CellValue::Error(e),
                        }
                    }
                }
                if count == 0 {
                    CellValue::Error(SpreadsheetError::DivisionByZero)
                } else {
                    CellValue::Number(sum / count as f64)
                }
            }
            "MIN" => {
                let mut min = f64::INFINITY;
                let mut found = false;
                for arg in args {
                    for val in self.flatten_arg_values(arg) {
                        match val.as_number() {
                            Ok(num) => {
                                if num < min {
                                    min = num;
                                }
                                found = true;
                            }
                            Err(e) => return CellValue::Error(e),
                        }
                    }
                }
                if found {
                    CellValue::Number(min)
                } else {
                    CellValue::Number(0.0)
                }
            }
            "MAX" => {
                let mut max = f64::NEG_INFINITY;
                let mut found = false;
                for arg in args {
                    for val in self.flatten_arg_values(arg) {
                        match val.as_number() {
                            Ok(num) => {
                                if num > max {
                                    max = num;
                                }
                                found = true;
                            }
                            Err(e) => return CellValue::Error(e),
                        }
                    }
                }
                if found {
                    CellValue::Number(max)
                } else {
                    CellValue::Number(0.0)
                }
            }
            "NB" | "COUNT" => {
                let mut count = 0usize;
                for arg in args {
                    for val in self.flatten_arg_values(arg) {
                        if val.as_number().is_ok() {
                            count += 1;
                        }
                    }
                }
                CellValue::Number(count as f64)
            }
            "SI" | "IF" => {
                if args.len() < 2 || args.len() > 3 {
                    return CellValue::Error(SpreadsheetError::Value);
                }
                let condition = match self.evaluate_ast(&args[0]).as_bool() {
                    Ok(b) => b,
                    Err(e) => return CellValue::Error(e),
                };

                if condition {
                    self.evaluate_ast(&args[1])
                } else if args.len() == 3 {
                    self.evaluate_ast(&args[2])
                } else {
                    CellValue::Boolean(false)
                }
            }
            unknown => CellValue::Error(SpreadsheetError::UnknownFunction(unknown.to_string())),
        }
    }

    /// Récupère la liste de cellules ou valeurs issues d'un argument (gère les plages A1:B3)
    fn flatten_arg_values(&self, expr: &Expr) -> Vec<CellValue> {
        match expr {
            Expr::Range(range) => range
                .cells()
                .into_iter()
                .map(|coord| self.get_value(coord))
                .collect(),
            Expr::Cell(coord) => vec![self.get_value(*coord)],
            other => vec![self.evaluate_ast(other)],
        }
    }
}

impl Default for Spreadsheet {
    fn default() -> Self {
        Self::new()
    }
}

