fn main() {
    println!("=== Démarrage du moteur de tableur Rust ===");

    let mut sheet = Spreadsheet::new();

    // 1. Définition des valeurs de base
    println!("\n[1] Initialisation de données dans la plage A1:B3");
    let initial_data = [
        ("A1", "10"),
        ("A2", "20"),
        ("A3", "30"),
        ("B1", "5"),
        ("B2", "15"),
        ("B3", "25"),
    ];

    for (cell, val) in initial_data {
        if let Err(e) = sheet.set_cell(cell, val) {
            eprintln!("Erreur lors de l'assignation de {} = {}: {}", cell, val, e);
            return;
        }
        println!("  {} = {}", cell, val);
    }

    // 2. Définition de formules avec fonctions & plages
    println!("\n[2] Ajout de formules (SOMME, MOYENNE, MIN, MAX, expressions arithmétiques)");
    let formulas = [
        ("C1", "=SOMME(A1:B3)"),              // Somme globale = 10+20+30+5+15+25 = 105
        ("C2", "=MOYENNE(A1:A3)"),            // Moyenne (10, 20, 30) = 20
        ("C3", "=MIN(A1:B3) + MAX(A1:B3)"),    // 5 + 30 = 35
        ("D1", "=C1 * 2 + B1"),               // 105 * 2 + 5 = 215
        ("D2", "=SI(C2 >= 20, \"VALIDE\", \"RECALÉ\")"),
    ];

    for (cell, formula) in formulas {
        match sheet.set_cell(cell, formula) {
            Ok(coord) => println!("  {} := {}  ==>  {}", cell, formula, sheet.get_value(coord)),
            Err(e) => eprintln!("  Erreur formule {} : {}", cell, e),
        }
    }

    // 3. Mise à jour d'une dépendance et vérification de la cascade de recalcul
    println!("\n[3] Modification de A1 (10 -> 50) : Vérification du recalcul en cascade");
    if let Err(e) = sheet.set_cell("A1", "50") {
        eprintln!("Erreur: {}", e);
        return;
    }
    println!("  Nouvelle valeur de A1 = {}", sheet.get_value(CellCoord::from_str("A1").unwrap_or(CellCoord::new(0,0))));
    println!("  C1 (SOMME(A1:B3)) recalculé = {}", sheet.get_value(CellCoord::from_str("C1").unwrap_or(CellCoord::new(0,0))));
    println!("  C2 (MOYENNE(A1:A3)) recalculé = {}", sheet.get_value(CellCoord::from_str("C2").unwrap_or(CellCoord::new(0,0))));
    println!("  D1 (C1 * 2 + B1) recalculé = {}", sheet.get_value(CellCoord::from_str("D1").unwrap_or(CellCoord::new(0,0))));

    // 4. Test et détection de dépendances circulaires
    println!("\n[4] Détection de dépendance circulaire (E1 <-> E2)");
