// src/main.rs
use std::collections::{HashMap, HashSet, VecDeque};
use std::fmt;
use std::str::FromStr;

// ==============================================================================
// 1. ERREURS & TYPES DE BASE
// ==============================================================================

#[derive(Debug, Clone, PartialEq, Eq, Hash, thiserror::Error)]
pub enum SpreadsheetError {
    #[error("#DIV/0!")]
    DivisionByZero,
    #[error("#VALUE!")]
    Value,
    #[error("#REF!")]
    InvalidReference,
    #[error("#NAME?")]
    UnknownFunction(String),
    #[error("#CYCLE!")]
    CircularDependency,
    #[error("#PARSE_ERR: {0}")]
    ParseError(String),
}

#[derive(Debug, Clone, PartialEq)]
pub enum CellValue {
    Empty,
    Number(f64),
    Text(String),
    Boolean(bool),
    Error(SpreadsheetError),
}

impl CellValue {
    pub fn as_number(&self) -> Result<f64, SpreadsheetError> {
        match self {
            CellValue::Number(n) => Ok(*n),
            CellValue::Boolean(b) => Ok(if *b { 1.0 } else { 0.0 }),
            CellValue::Empty => Ok(0.0),
            CellValue::Text(s) => s.trim().parse::<f64>().map_err(|_| SpreadsheetError::Value),
            CellValue::Error(e) => Err(e.clone()),
        }
    }

    pub fn as_bool(&self) -> Result<bool, SpreadsheetError> {
        match self {
            CellValue::Boolean(b) => Ok(*b),
            CellValue::Number(n) => Ok(*n != 0.0),
            CellValue::Empty => Ok(false),
            CellValue::Text(s) => match s.trim().to_uppercase().as_str() {
                "VRAI" | "TRUE" | "1" => Ok(true),
                "FAUX" | "FALSE" | "0" => Ok(false),
                _ => Err(SpreadsheetError::Value),
            },
            CellValue::Error(e) => Err(e.clone()),
        }
    }
}

impl fmt::Display for CellValue {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CellValue::Empty => write!(f, ""),
            CellValue::Number(n) => {
                if n.fract() == 0.0 {
                    write!(f, "{:.0}", n)
                } else {
                    write!(f, "{}", n)
                }
            }
            CellValue::Text(s) => write!(f, "{}", s),
            CellValue::Boolean(b) => write!(f, "{}", if *b { "VRAI" } else { "FAUX" }),
            CellValue::Error(e) => write!(f, "{}", e),
        }
    }
}

// ==============================================================================
// 2. COORDONNÉES DE CELLULES & PLAGES (A1, B2:C5)
// ==============================================================================

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct CellCoord {
    pub col: u32, // 0-indexé : A=0, B=1, ...
    pub row: u32, // 0-indexé : 1=0, 2=1, ...
}

impl CellCoord {
    pub fn new(col: u32, row: u32) -> Self {
        Self { col, row }
    }
}

impl fmt::Display for CellCoord {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut col_str = String::new();
        let mut c = self.col;
        loop {
            let rem = (c % 26) as u8;
            col_str.insert(0, (b'A' + rem) as char);
            if c < 26 {
                break;
            }
            c = (c / 26) - 1;
        }
        write!(f, "{}{}", col_str, self.row + 1)
    }
}

impl FromStr for CellCoord {
    type Err = SpreadsheetError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let s = s.trim();
        let col_end = s
            .find(|c: char| c.is_ascii_digit())
            .ok_or_else(|| SpreadsheetError::ParseError(format!("Format de cellule invalide: {}", s)))?;

        let (col_part, row_part) = s.split_at(col_end);
        if col_part.is_empty() || row_part.is_empty() {
            return Err(SpreadsheetError::ParseError(format!("Format de cellule invalide: {}", s)));
        }

        let mut col: u32 = 0;
        for ch in col_part.chars() {
            if !ch.is_ascii_alphabetic() {
                return Err(SpreadsheetError::ParseError(format!("Colonne invalide: {}", col_part)));
            }
            let val = (ch.to_ascii_uppercase() as u32) - ('A' as u32);
            col = col * 26 + (val + 1);
        }
        col -= 1;

        let row_num = row_part
            .parse::<u32>()
            .map_err(|_| SpreadsheetError::ParseError(format!("Ligne invalide: {}", row_part)))?;
        if row_num == 0 {
            return Err(SpreadsheetError::ParseError("La ligne doit être >= 1".to_string()));
        }

        Ok(CellCoord {
            col,
            row: row_num - 1,
        })
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct CellRange {
    pub start: CellCoord,
    pub end: CellCoord,
}

impl CellRange {
    pub fn new(start: CellCoord, end: CellCoord) -> Self {
        let min_col = start.col.min(end.col);
        let max_col = start.col.max(end.col);
        let min_row = start.row.min(end.row);
        let max_row = start.row.max(end.row);
        Self {
            start: CellCoord::new(min_col, min_row),
            end: CellCoord::new(max_col, max_row),
        }
    }

    pub fn cells(&self) -> Vec<CellCoord> {
        let mut list = Vec::new();
        for r in self.start.row..=self.end.row {
            for c in self.start.col..=self.end.col {
                list.push(CellCoord::new(c, r));
            }
        }
        list
    }
}

impl fmt::Display for CellRange {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}:{}", self.start, self.end)
    }
}

