// src/main.rs
use std::collections::{BTreeMap, HashMap};
use std::net::SocketAddr;
use std::sync::Arc;
use std::time::{Duration, Instant};

use bytes::{Buf, BufMut, BytesMut};
use clap::Parser;
use rand::Rng;
use thiserror::Error;
use tokio::net::UdpSocket;
use tokio::sync::mpsc;
use tracing::{debug, error, info, warn};

const MAGIC_BYTE: u8 = 0xA5;
const HEADER_SIZE: usize = 16;
const MAX_PAYLOAD_SIZE: usize = 1024;
const DEFAULT_RTO_MS: u64 = 250;
const DEFAULT_WINDOW_SIZE: usize = 5;

#[derive(Debug, Error)]
pub enum ProtocolError {
    #[error("I/O error: {0}")]
    Io(#[from] std::io::Error),
    #[error("Packet is too short: {0} bytes")]
    TooShort(usize),
    #[error("Invalid magic byte: {0:#04x}")]
    InvalidMagic(u8),
    #[error("Invalid packet type: {0:#04x}")]
    InvalidType(u8),
    #[error("Corrupted packet: expected checksum {expected:#010x}, calculated {calculated:#010x}")]
    ChecksumMismatch { expected: u32, calculated: u32 },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum PacketType {
    Data = 0x01,
    Ack = 0x02,
    Fin = 0x03,
}

impl TryFrom<u8> for PacketType {
    type Error = ProtocolError;

    fn try_from(value: u8) -> Result<Self, Self::Error> {
        match value {
            0x01 => Ok(PacketType::Data),
            0x02 => Ok(PacketType::Ack),
            0x03 => Ok(PacketType::Fin),
            other => Err(ProtocolError::InvalidType(other)),
        }
    }
}

/// Simple CRC32 / Adler-like checksum implementation for demonstration
fn compute_checksum(data: &[u8]) -> u32 {
    let mut sum1: u32 = 0xffff;
    let mut sum2: u32 = 0xffff;

    for &byte in data {
        sum1 = (sum1 + byte as u32) % 65521;
        sum2 = (sum2 + sum1) % 65521;
    }

    (sum2 << 16) | sum1
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Packet {
    pub packet_type: PacketType,
    pub seq_num: u32,
    pub ack_num: u32,
    pub payload: Vec<u8>,
}

impl Packet {
    pub fn new_data(seq_num: u32, payload: Vec<u8>) -> Self {
        Self {
            packet_type: PacketType::Data,
            seq_num,
            ack_num: 0,
            payload,
        }
    }

    pub fn new_ack(ack_num: u32) -> Self {
        Self {
            packet_type: PacketType::Ack,
            seq_num: 0,
            ack_num,
            payload: Vec::new(),
        }
    }

    pub fn new_fin(seq_num: u32) -> Self {
        Self {
            packet_type: PacketType::Fin,
            seq_num,
            ack_num: 0,
            payload: Vec::new(),
        }
    }

    pub fn serialize(&self) -> Vec<u8> {
        let mut buf = BytesMut::with_capacity(HEADER_SIZE + self.payload.len());
        buf.put_u8(MAGIC_BYTE);
        buf.put_u8(self.packet_type as u8);
        buf.put_u32(self.seq_num);
        buf.put_u32(self.ack_num);
        buf.put_u16(self.payload.len() as u16);

        // Pre-compute checksum over header (without checksum field) + payload
        let mut check_data = Vec::with_capacity(12 + self.payload.len());
        check_data.extend_from_slice(&buf[..12]);
        check_data.extend_from_slice(&self.payload);
        let checksum = compute_checksum(&check_data);

        buf.put_u32(checksum);
        buf.put_slice(&self.payload);
        buf.to_vec()
    }

    pub fn deserialize(raw: &[u8]) -> Result<Self, ProtocolError> {
        if raw.len() < HEADER_SIZE {
            return Err(ProtocolError::TooShort(raw.len()));
        }

        let mut buf = &raw[..];
        let magic = buf.get_u8();
        if magic != MAGIC_BYTE {
            return Err(ProtocolError::InvalidMagic(magic));
        }

        let ptype_byte = buf.get_u8();
        let packet_type = PacketType::try_from(ptype_byte)?;

        let seq_num = buf.get_u32();
        let ack_num = buf.get_u32();
        let payload_len = buf.get_u16() as usize;
        let expected_checksum = buf.get_u32();

        if raw.len() < HEADER_SIZE + payload_len {
            return Err(ProtocolError::TooShort(raw.len()));
        }

        let payload = raw[HEADER_SIZE..HEADER_SIZE + payload_len].to_vec();

        // Checksum verification
        let mut check_data = Vec::with_capacity(12 + payload.len());
        check_data.extend_from_slice(&raw[..12]);
        check_data.extend_from_slice(&payload);
        let calculated = compute_checksum(&check_data);

        if calculated != expected_checksum {
            return Err(ProtocolError::ChecksumMismatch {
                expected: expected_checksum,
                calculated,
            });
        }

        Ok(Packet {
            packet_type,
            seq_num,
            ack_num,
            payload,
        })
    }
}

/// Simulated lossy channel configuration
#[derive(Debug, Clone)]
pub struct ChannelConfig {
    pub loss_rate: f64,
    pub corruption_rate: f64,
    pub min_latency_ms: u64,
    pub max_latency_ms: u64,
}

impl Default for ChannelConfig {
    fn default() -> Self {
        Self {
            loss_rate: 0.20,
            corruption_rate: 0.05,
            min_latency_ms: 10,
            max_latency_ms: 50,
        }
    }
}

/// Lossy forwarder / network proxy simulating real-world transmission impairments
pub struct LossyChannel {
    socket: Arc<UdpSocket>,
    config: ChannelConfig,
}

impl LossyChannel {
    pub fn new(socket: Arc<UdpSocket>, config: ChannelConfig) -> Self {
        Self { socket, config }
    }

    pub async fn send_to(&self, data: &[u8], target: SocketAddr) -> Result<(), std::io::Error> {
        let mut rng = rand::thread_rng();

        // 1. Simuler la perte
        if rng.gen_bool(self.config.loss_rate) {
            debug!("⚠️ [CANAL] Paquet perdu délibérément vers {}", target);
            return Ok(());
        }

        // 2. Simuler la corruption
        let mut packet_data = data.to_vec();
        if !packet_data.is_empty() && rng.gen_bool(self.config.corruption_rate) {
            let idx = rng.gen_range(0..packet_data.len());
            packet_data[idx] ^= 0xFF;
            debug!("⚡ [CANAL] Paquet corrompu délibérément vers {}", target);
        }

        // 3. Simuler la latence
        let delay_ms = rng.gen_range(self.config.min_latency_ms..=self.config.max_latency_ms);
        let socket = self.socket.clone();

        tokio::spawn(async move {
            tokio::time::sleep(Duration::from_millis(delay_ms)).await;
            if let Err(e) = socket.send_to(&packet_data, target).await {
                error!("Erreur lors de l'envoi différé dans le canal: {}", e);
            }
        });

        Ok(())
    }
}

/// Émetteur fiable (Sliding Window avec Selective Repeat / Retransmission)
pub struct ReliableSender {
    channel: Arc<LossyChannel>,
    receiver_addr: SocketAddr,
    window_size: usize,
    rto: Duration,
}

impl ReliableSender {
    pub fn new(
        channel: Arc<LossyChannel>,
        receiver_addr: SocketAddr,
        window_size: usize,
        rto: Duration,
    ) -> Self {
        Self {
            channel,
            receiver_addr,
            window_size,
            rto,
        }
    }

    pub async fn transmit_stream(
        &self,
        data: &[u8],
        mut ack_rx: mpsc::Receiver<u32>,
    ) -> Result<(), ProtocolError> {
        // Découpage en blocs de données
        let chunks: Vec<Vec<u8>> = data
            .chunks(MAX_PAYLOAD_SIZE)
            .map(|c| c.to_vec())
            .collect();
        let total_packets = chunks.len();
        info!(
            "🚀 [SENDER] Début de transmission : {} octets en {} paquets (Fenêtre: {}, RTO: {}ms)",
            data.len(),
            total_packets,
            self.window_size,
            self.rto.as_millis()
        );

        let mut base: usize = 0;
        let mut next_seq: usize = 0;
        let mut in_flight: HashMap<u32, (Packet, Instant)> = HashMap::new();
        let mut timer = tokio::time::interval(Duration::from_millis(20));

        while base < total_packets {
            // Envoyer jusqu'à concurrence de la taille de fenêtre
            while next_seq < total_packets && (next_seq - base) < self.window_size {
                let pkt = Packet::new_data(next_seq as u32, chunks[next_seq].clone());
                debug!("📤 [SENDER] Envoi seq_num={}", next_seq);
                self.channel
                    .send_to(&pkt.serialize(), self.receiver_addr)
                    .await?;
                in_flight.insert(next_seq as u32, (pkt, Instant::now()));
                next_seq += 1;
            }

            tokio::select! {
                // Réception des acquittements
                Some(ack_num) = ack_rx.recv() => {
                    if in_flight.remove(&ack_num).is_some() {
                        debug!("✅ [SENDER] Reçu ACK pour seq_num={}", ack_num);
                        // Avancer la base de la fenêtre si c'est le paquet le plus bas
                        while base < total_packets && !in_flight.contains_key(&(base as u32)) && base < next_seq {
                            base += 1;
                        }
                    }
                }
                // Vérification périodique des timeouts (Retransmissions)
                _ = timer.tick() => {
                    let now = Instant::now();
                    for (&seq, (pkt, sent_time)) in in_flight.iter_mut() {
                        if now.duration_since(*sent_time) >= self.rto {
                            warn!("⏱️ [SENDER] Timeout pour seq_num={}, retransmission !", seq);
                            let _ = self.channel.send_to(&pkt.serialize(), self.receiver_addr).await;
                            *sent_time = now;
                        }
                    }
                }
            }
        }

        // Envoi du FIN avec garantie de fin de transmission
        info!("🏁 [SENDER] Tous les paquets DATA acquittés. Envoi de FIN...");
        let fin_seq = total_packets as u32;
        let fin_pkt = Packet::new_fin(fin_seq);

        for _ in 0..5 {
            self.channel
                .send_to(&fin_pkt.serialize(), self.receiver_addr)
                .await?;
            tokio::time::sleep(Duration::from_millis(50)).await;
        }

        info!("🎉 [SENDER] Transmission terminée avec succès !");
        Ok(())
    }
}

/// Récepteur fiable avec gestion de réordonnancement (Out-of-order buffer)
pub struct ReliableReceiver {
    channel: Arc<LossyChannel>,
}

impl ReliableReceiver {
    pub fn new(channel: Arc<LossyChannel>) -> Self {
        Self { channel }
    }

    pub async fn run(
        &self,
        mut packet_rx: mpsc::Receiver<(Packet, SocketAddr)>,
    ) -> Result<Vec<u8>, ProtocolError> {
        let mut expected_seq: u32 = 0;
        let mut received_buffer: BTreeMap<u32, Vec<u8>> = BTreeMap::new();
        let mut assembled_data: Vec<u8> = Vec::new();

        while let Some((packet, sender_addr)) = packet_rx.recv().await {
            match packet.packet_type {
                PacketType::Data => {
                    let seq = packet.seq_num;
                    debug!("📥 [RECEIVER] Reçu seq_num={}, en attente={}", seq, expected_seq);

                    // Envoyer un ACK systématique
                    let ack = Packet::new_ack(seq);
                    let _ = self.channel.send_to(&ack.serialize(), sender_addr).await;

                    if seq >= expected_seq {
                        received_buffer.insert(seq, packet.payload);
                    }

                    // Assembler tout paquet contigu
                    while let Some(payload) = received_buffer.remove(&expected_seq) {
                        assembled_data.extend_from_slice(&payload);
                        expected_seq += 1;
                    }
                }
                PacketType::Fin => {
                    info!("🛑 [RECEIVER] Signal FIN reçu, finalisation de la réception");
                    let ack = Packet::new_ack(packet.seq_num);
                    let _ = self.channel.send_to(&ack.serialize(), sender_addr).await;
                    break;
                }
                PacketType::Ack => {
                    // Les ACKs ne sont pas traités par le récepteur dans ce flux unidirectionnel
                }
            }
        }

        Ok(assembled_data)
    }
}

