// src/main.rs
use std::collections::{BTreeMap, HashMap};
use std::net::SocketAddr;
use std::sync::Arc;
use std::time::{Duration, Instant};

use bytes::{Buf, BufMut, BytesMut};
use clap::Parser;
use rand::Rng;
use thiserror::Error;
use tokio::net::UdpSocket;
use tokio::sync::mpsc;
use tracing::{debug, error, info, warn};

const MAGIC_BYTE: u8 = 0xA5;
const HEADER_SIZE: usize = 16;
const MAX_PAYLOAD_SIZE: usize = 1024;
const DEFAULT_RTO_MS: u64 = 250;
const DEFAULT_WINDOW_SIZE: usize = 5;

#[derive(Debug, Error)]
pub enum ProtocolError {
    #[error("I/O error: {0}")]
    Io(#[from] std::io::Error),
    #[error("Packet is too short: {0} bytes")]
    TooShort(usize),
    #[error("Invalid magic byte: {0:#04x}")]
    InvalidMagic(u8),
    #[error("Invalid packet type: {0:#04x}")]
    InvalidType(u8),
    #[error("Corrupted packet: expected checksum {expected:#010x}, calculated {calculated:#010x}")]
    ChecksumMismatch { expected: u32, calculated: u32 },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum PacketType {
    Data = 0x01,
    Ack = 0x02,
    Fin = 0x03,
}

impl TryFrom<u8> for PacketType {
    type Error = ProtocolError;

    fn try_from(value: u8) -> Result<Self, Self::Error> {
        match value {
            0x01 => Ok(PacketType::Data),
            0x02 => Ok(PacketType::Ack),
            0x03 => Ok(PacketType::Fin),
            other => Err(ProtocolError::InvalidType(other)),
        }
    }
}

/// Simple CRC32 / Adler-like checksum implementation for demonstration
fn compute_checksum(data: &[u8]) -> u32 {
    let mut sum1: u32 = 0xffff;
    let mut sum2: u32 = 0xffff;

    for &byte in data {
        sum1 = (sum1 + byte as u32) % 65521;
        sum2 = (sum2 + sum1) % 65521;
    }

    (sum2 << 16) | sum1
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Packet {
    pub packet_type: PacketType,
    pub seq_num: u32,
    pub ack_num: u32,
    pub payload: Vec<u8>,
}

impl Packet {
    pub fn new_data(seq_num: u32, payload: Vec<u8>) -> Self {
        Self {
            packet_type: PacketType::Data,
            seq_num,
            ack_num: 0,
            payload,
        }
    }

    pub fn new_ack(ack_num: u32) -> Self {
        Self {
            packet_type: PacketType::Ack,
            seq_num: 0,
            ack_num,
            payload: Vec::new(),
        }
    }

    pub fn new_fin(seq_num: u32) -> Self {
        Self {
            packet_type: PacketType::Fin,
            seq_num,
            ack_num: 0,
            payload: Vec::new(),
        }
    }

    pub fn serialize(&self) -> Vec<u8> {
        let mut buf = BytesMut::with_capacity(HEADER_SIZE + self.payload.len());
        buf.put_u8(MAGIC_BYTE);
        buf.put_u8(self.packet_type as u8);
        buf.put_u32(self.seq_num);
        buf.put_u32(self.ack_num);
        buf.put_u16(self.payload.len() as u16);

        // Pre-compute checksum over header (without checksum field) + payload
        let mut check_data = Vec::with_capacity(12 + self.payload.len());
        check_data.extend_from_slice(&buf[..12]);
        check_data.extend_from_slice(&self.payload);
        let checksum = compute_checksum(&check_data);

        buf.put_u32(checksum);
        buf.put_slice(&self.payload);
        buf.to_vec()
    }

    pub fn deserialize(raw: &[u8]) -> Result<Self, ProtocolError> {
        if raw.len() < HEADER_SIZE {
            return Err(ProtocolError::TooShort(raw.len()));
        }

        let mut buf = &raw[..];
        let magic = buf.get_u8();
        if magic != MAGIC_BYTE {
            return Err(ProtocolError::InvalidMagic(magic));
        }

        let ptype_byte = buf.get_u8();
        let packet_type = PacketType::try_from(ptype_byte)?;

        let seq_num = buf.get_u32();
        let ack_num = buf.get_u32();
        let payload_len = buf.get_u16() as usize;
        let expected_checksum = buf.get_u32();

        if raw.len() < HEADER_SIZE + payload_len {
            return Err(ProtocolError::TooShort(raw.len()));
        }

        let payload = raw[HEADER_SIZE..HEADER_SIZE + payload_len].to_vec();

        // Checksum verification
        let mut check_data = Vec::with_capacity(12 + payload.len());
        check_data.extend_from_slice(&raw[..12]);
        check_data.extend_from_slice(&payload);
        let calculated = compute_checksum(&check_data);

        if calculated != expected_checksum {
            return Err(ProtocolError::ChecksumMismatch {
                expected: expected_checksum,
                calculated,
            });
        }

        Ok(Packet {
            packet_type,
            seq_num,
            ack_num,
            payload,
        })
    }
}

