/// Lossy forwarder / network proxy simulating real-world transmission impairments
pub struct LossyChannel {
    socket: Arc<UdpSocket>,
    config: ChannelConfig,
}

impl LossyChannel {
    pub fn new(socket: Arc<UdpSocket>, config: ChannelConfig) -> Self {
        Self { socket, config }
    }

    pub async fn send_to(&self, data: &[u8], target: SocketAddr) -> Result<(), std::io::Error> {
        let mut rng = rand::thread_rng();

        // 1. Simuler la perte
        if rng.gen_bool(self.config.loss_rate) {
            debug!("⚠️ [CANAL] Paquet perdu délibérément vers {}", target);
            return Ok(());
        }

        // 2. Simuler la corruption
        let mut packet_data = data.to_vec();
        if !packet_data.is_empty() && rng.gen_bool(self.config.corruption_rate) {
            let idx = rng.gen_range(0..packet_data.len());
            packet_data[idx] ^= 0xFF;
            debug!("⚡ [CANAL] Paquet corrompu délibérément vers {}", target);
        }

        // 3. Simuler la latence
        let delay_ms = rng.gen_range(self.config.min_latency_ms..=self.config.max_latency_ms);
        let socket = self.socket.clone();

        tokio::spawn(async move {
            tokio::time::sleep(Duration::from_millis(delay_ms)).await;
            if let Err(e) = socket.send_to(&packet_data, target).await {
                error!("Erreur lors de l'envoi différé dans le canal: {}", e);
            }
        });

        Ok(())
    }
}

