    println!(" - Taux de perte de paquets : {:.1}%", args.loss_rate * 100.0);
    println!(" - Taux de corruption       : {:.1}%", args.corruption_rate * 100.0);
    println!(" - Taille de la fenêtre     : {} paquets", args.window_size);
    println!(" - Timeout RTO              : {} ms", args.rto_ms);
    println!("------------------------------------------------------------");

    // Sockets UDP pour l'émetteur et le récepteur
    let sender_socket = Arc::new(UdpSocket::bind("127.0.0.1:0").await?);
    let receiver_socket = Arc::new(UdpSocket::bind("127.0.0.1:0").await?);

    let sender_addr = sender_socket.local_addr()?;
    let receiver_addr = receiver_socket.local_addr()?;

    info!("Émetteur lié sur {}", sender_addr);
    info!("Récepteur lié sur {}", receiver_addr);

    let channel_config = ChannelConfig {
        loss_rate: args.loss_rate,
        corruption_rate: args.corruption_rate,
        min_latency_ms: 10,
        max_latency_ms: 40,
    };

    let sender_channel = Arc::new(LossyChannel::new(sender_socket.clone(), channel_config.clone()));
    let receiver_channel = Arc::new(LossyChannel::new(receiver_socket.clone(), channel_config));

    // Canaux de communication internes pour router les paquets validés
    let (ack_tx, ack_rx) = mpsc::channel::<u32>(100);
    let (data_tx, data_rx) = mpsc::channel::<(Packet, SocketAddr)>(100);

    // Boucle d'écoute pour le Sender (écoute des ACKs)
    let s_sock = sender_socket.clone();
    let ack_producer = ack_tx.clone();
    tokio::spawn(async move {
        let mut buf = vec![0u8; 2048];
        loop {
            match s_sock.recv_from(&mut buf).await {
                Ok((len, _addr)) => {
                    match Packet::deserialize(&buf[..len]) {
                        Ok(pkt) if pkt.packet_type == PacketType::Ack => {
                            let _ = ack_producer.send(pkt.ack_num).await;
                        }
                        Ok(_) => {}
                        Err(e) => {
                            debug!("Sender a ignoré un paquet invalide : {}", e);
                        }
                    }
                }
                Err(e) => {
                    error!("Erreur lecture socket émetteur: {}", e);
                    break;
                }
            }
        }
    });

    // Boucle d'écoute pour le Receiver (écoute des DATA et FIN)
    let r_sock = receiver_socket.clone();
    let data_producer = data_tx.clone();
    tokio::spawn(async move {
        let mut buf = vec![0u8; 2048];
        loop {
            match r_sock.recv_from(&mut buf).await {
                Ok((len, addr)) => {
                    match Packet::deserialize(&buf[..len]) {
                        Ok(pkt) => {
                            let _ = data_producer.send((pkt, addr)).await;
                        }
                        Err(e) => {
                            debug!("Receiver a ignoré un paquet corrompu/invalide: {}", e);
                        }
                    }
                }
                Err(e) => {
                    error!("Erreur lecture socket récepteur: {}", e);
                    break;
                }
            }
        }
    });

    // Message de test volumineux (> plusieurs fenêtres et segments)
    let test_message = (0..25)
        .map(|i| format!("Segment de données #{} : [Lorem ipsum dolor sit amet, consectetur adipiscing elit. Aliquam nec diam eget leo porta vulputate.]\n", i))
        .collect::<Vec<String>>()
        .join("");

    let payload_bytes = test_message.into_bytes();
    let original_checksum = compute_checksum(&payload_bytes);
    let original_len = payload_bytes.len();

    let receiver = ReliableReceiver::new(receiver_channel);
    let receiver_handle = tokio::spawn(async move {
        receiver.run(data_rx).await
    });

    let sender = ReliableSender::new(
        sender_channel,
        receiver_addr,
        args.window_size,
        Duration::from_millis(args.rto_ms),
    );

    let start_time = Instant::now();
    sender.transmit_stream(&payload_bytes, ack_rx).await?;

    let received_bytes = receiver_handle.await??;
    let elapsed = start_time.elapsed();
    let received_checksum = compute_checksum(&received_bytes);

    println!("\n============================================================");
    println!("                   BILAN DU TRANSFERT                       ");
    println!("============================================================");
    println!("Octets émis      : {} octets", original_len);
    println!("Octets reçus     : {} octets", received_bytes.len());
    println!("Somme émise      : {:#010x}", original_checksum);
    println!("Somme reçue      : {:#010x}", received_checksum);
    println!("Temps total      : {:.2?}", elapsed);

    if original_checksum == received_checksum && original_len == received_bytes.len() {
        println!("Statut           : ✅ SUCCÈS - Intégrité des données vérifiée à 100% !");
    } else {
        println!("Statut           : ❌ ÉCHEC - Données corrompues ou incomplètes.");
    }
    println!("============================================================\n");

    Ok(())
}

