```rust
// src/main.rs
use anyhow::{Context, Result};
use clap::Parser;
use colored::Colorize;
use proc_macro2::LineColumn;
use serde::Serialize;
use std::collections::HashSet;
use std::fs;
use std::path::{Path, PathBuf};
use syn::spanned::Spanned;
use syn::visit::{self, Visit};
use walkdir::WalkDir;

#[derive(Parser, Debug)]
#[command(
    name = "rust-static-analyzer",
    author = "Damien",
    version = "0.1.0",
    about = "Analyseur statique détectant les blocs/fonctions unsafe et les méthodes dépréciées dans un projet Rust."
)]
struct Cli {
    /// Chemin du fichier ou dossier racine du projet à analyser
    #[arg(default_value = ".")]
    path: PathBuf,

    /// Échoue avec un code de retour non-nul si du code unsafe est détecté
    #[arg(long)]
    deny_unsafe: bool,

    /// Échoue avec un code de retour non-nul si du code déprécié est détecté
    #[arg(long)]
    deny_deprecated: bool,

    /// Sortie au format JSON pour l'intégration CI/CD
    #[arg(long)]
    json: bool,

    /// Ignore les modules et répertoires de tests (ex: tests/, #[cfg(test)])
    #[arg(long)]
    ignore_tests: bool,
}

#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum IssueKind {
    UnsafeBlock,
    UnsafeFunction,
    UnsafeTrait,
    UnsafeImpl,
    DeprecatedDeclaration,
    DeprecatedCall,
}

#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
pub struct SourceLocation {
    pub file: String,
    pub start_line: usize,
    pub start_col: usize,
    pub end_line: usize,
    pub end_col: usize,
}

impl SourceLocation {
    pub fn from_span(file: &str, start: LineColumn, end: LineColumn) -> Self {
        Self {
            file: file.to_string(),
            start_line: start.line,
            start_col: start.column + 1,
            end_line: end.line,
            end_col: end.column + 1,
        }
    }
}

#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
pub struct AnalysisIssue {
    pub kind: IssueKind,
    pub message: String,
    pub location: SourceLocation,
    pub details: Option<String>,
}

#[derive(Debug, Default, Serialize)]
pub struct AnalysisReport {
    pub scanned_files: usize,
    pub total_issues: usize,
    pub unsafe_count: usize,
    pub deprecated_count: usize,
    pub issues: Vec<AnalysisIssue>,
}

/// Première passe : collecte des méthodes et fonctions marquées avec `#[deprecated]`
#[derive(Default)]
struct DeprecationCollector {
    pub deprecated_identifiers: HashSet<String>,
}

impl<'ast> Visit<'ast> for DeprecationCollector {
    fn visit_item_fn(&mut self, item: &'ast syn::ItemFn) {
        if has_deprecated_attr(&item.attrs) {
            self.deprecated_identifiers.insert(item.sig.ident.to_string());
        }
        visit::visit_item_fn(self, item);
    }

    fn visit_impl_item_fn(&mut self, item: &'ast syn::ImplItemFn) {
        if has_deprecated_attr(&item.attrs) {
            self.deprecated_identifiers.insert(item.sig.ident.to_string());
        }
        visit::visit_impl_item_fn(self, item);
    }

    fn visit_trait_item_fn(&mut self, item: &'ast syn::TraitItemFn) {
        if has_deprecated_attr(&item.attrs) {
            self.deprecated_identifiers.insert(item.sig.ident.to_string());
        }
        visit::visit_trait_item_fn(self, item);
    }
}

/// Deuxième passe : détection approfondie de tout le code unsafe et des dépréciations
struct AstAnalyzer<'a> {
    file_path: &'a str,
    known_deprecated: &'a HashSet<String>,
    issues: Vec<AnalysisIssue>,
}

impl<'a> AstAnalyzer<'a> {
    fn new(file_path: &'a str, known_deprecated: &'a HashSet<String>) -> Self {
        Self {
            file_path,
            known_deprecated,
            issues: Vec::new(),
        }
    }

    fn add_issue(&mut self, kind: IssueKind, message: String, span: proc_macro2::Span, details: Option<String>) {
        let location = SourceLocation::from_span(self.file_path, span.start(), span.end());
        self.issues.push(AnalysisIssue {
            kind,
            message,
            location,
            details,
        });
    }
}

impl<'a, 'ast> Visit<'ast> for AstAnalyzer<'a> {
    // 1. Détection des blocs unsafe
    fn visit_expr_unsafe(&mut self, expr: &'ast syn::ExprUnsafe) {
        self.add_issue(
            IssueKind::UnsafeBlock,
            "Utilisation d'un bloc `unsafe`".to_string(),
            expr.unsafe_token.span(),
            None,
        );
        visit::visit_expr_unsafe(self, expr);
    }

    // 2. Détection des fonctions unsafe et déclarations dépréciées
    fn visit_item_fn(&mut self, item: &'ast syn::ItemFn) {
        let fn_name = item.sig.ident.to_string();

        if item.sig.unsafety.is_some() {
            self.add_issue(
                IssueKind::UnsafeFunction,
                format!("Déclaration d'une fonction unsafe : `{fn_name}`"),
                item.sig.fn_token.span(),
                None,
            );
        }

        if let Some(reason) = extract_deprecation_info(&item.attrs) {
            self.add_issue(
                IssueKind::DeprecatedDeclaration,
                format!("Fonction dépréciée déclarée : `{fn_name}`"),
                item.sig.ident.span(),
                Some(reason),
            );
        }

        visit::visit_item_fn(self, item);
    }

    // 3. Détection des méthodes d'implémentation unsafe et dépréciées
    fn visit_impl_item_fn(&mut self, item: &'ast syn::ImplItemFn) {
        let method_name = item.sig.ident.to_string();

        if item.sig.unsafety.is_some() {
            self.add_issue(
                IssueKind::UnsafeFunction,
                format!("Déclaration d'une méthode unsafe : `{method_name}`"),
                item.sig.fn_token.span(),
                None,
            );
        }

        if let Some(reason) = extract_deprecation_info(&item.attrs) {
            self.add_issue(
                IssueKind::DeprecatedDeclaration,
                format!("Méthode dépréciée déclarée : `{method_name}`"),
                item.sig.ident.span(),
                Some(reason),
            );
        }

        visit::visit_impl_item_fn(self, item);
    }

    // 4. Détection des méthodes de traits unsafe et dépréciées
    fn visit_trait_item_fn(&mut self, item: &'ast syn::TraitItemFn) {
        let method_name = item.sig.ident.to_string();

        if item.sig.unsafety.is_some() {
            self.add_issue(
                IssueKind::UnsafeFunction,
                format!("Déclaration d'une méthode de trait unsafe : `{method_name}`"),
                item.sig.fn_token.span(),
                None,
            );
        }

        if let Some(reason) = extract_deprecation_info(&item.attrs) {
            self.add_issue(
                IssueKind::DeprecatedDeclaration,
                format!("Méthode de trait dépréciée déclarée : `{method_name}`"),
                item.sig.ident.span(),
                Some(reason),
            );
        }

        visit::visit_trait_item_fn(self, item);
    }

    // 5. Détection des traits unsafe
    fn visit_item_trait(&mut self, item: &'ast syn::ItemTrait) {
        if item.unsafety.is_some() {
            let trait_name = item.ident.to_string();
            self.add_issue(
                IssueKind::UnsafeTrait,
                format!("Déclaration d'un trait unsafe : `{trait_name}`"),
                item.trait_token.span(),
                None,
            );
        }

        if let Some(reason) = extract_deprecation_info(&item.attrs) {
            self.add_issue(
                IssueKind::DeprecatedDeclaration,
                format!("Trait déprécié déclaré : `{}`", item.ident),
                item.ident.span(),
                Some(reason),
            );
        }

        visit::visit_item_trait(self, item);
    }

    // 6. Détection des implémentations unsafe
    fn visit_item_impl(&mut self, item: &'ast syn::ItemImpl) {
        if item.unsafety.is_some() {
            let target = match &item.trait_ {
                Some((_, path, _)) => path
                    .segments
                    .last()
                    .map(|seg| seg.ident.to_string())
                    .unwrap_or_else(|| "Trait inconnu".to_string()),
                None => "Impl bloc".to_string(),
            };
            self.add_issue(
                IssueKind::UnsafeImpl,
                format!("Implémentation `unsafe` pour `{target}`"),
                item.impl_token.span(),
                None,
            );
        }

        if let Some(reason) = extract_deprecation_info(&item.attrs) {
            self.add_issue(
                IssueKind::DeprecatedDeclaration,
                "Bloc d'implémentation déprécié".to_string(),
                item.impl_token.span(),
                Some(reason),
            );
        }

        visit::visit_item_impl(self, item);
    }

    // 7. Détection des appels de méthodes dépréciées (ex: object.old_method())
    fn visit_expr_method_call(&mut self, expr: &'ast syn::ExprMethodCall) {
        let method_name = expr.method.to_string();
        if self.known_deprecated.contains(&method_name) {
            self.add_issue(
                IssueKind::DeprecatedCall,
                format!("Appel de la méthode dépréciée : `{method_name}`"),
                expr.method.span(),
                None,
            );
        }
        visit::visit_expr_method_call(self, expr);
    }

    // 8. Détection des appels de fonctions dépréciées (ex: old_function())
    fn visit_expr_call(&mut self, expr: &'ast syn::ExprCall) {
        if let syn::Expr::Path(path_expr) = &*expr.func {
            if let Some(ident) = path_expr.path.segments.last().map(|s| &s.ident) {
                let func_name = ident.to_string();
                if self.known_deprecated.contains(&func_name) {
                    self.add_issue(
                        IssueKind::DeprecatedCall,
                        format!("Appel de la fonction dépréciée : `{func_name}`"),
                        ident.span(),
                        None,
                    );
                }
            }
        }
        visit::visit_expr_call(self, expr);
    }
}

/// Vérifie si une liste d'attributs contient `#[deprecated]`
fn has_deprecated_attr(attrs: &[syn::Attribute]) -> bool {
    attrs.iter().any(|attr| attr.path().is_ident("deprecated"))
}

/// Extrait la raison ou les métadonnées de l'attribut `#[deprecated]`
fn extract_deprecation_info(attrs: &[syn::Attribute]) -> Option<String> {
    for attr in attrs {
        if !attr.path().is_ident("deprecated") {
            continue;
        }

        // Cas simple: #[deprecated]
        if let syn::Meta::Path(_) = &attr.meta {
            return Some("Déprécié sans note additionnelle".to_string());
        }

        // Cas avec texte direct: #[deprecated = "..."]
        if let syn::Meta::NameValue(nv) = &attr.meta {
            if let syn::Expr::Lit(lit) = &nv.value {
                if let syn::Lit::Str(s) = &lit.lit {
                    return Some(s.value());
                }
            }
        }

        // Cas structuré: #[deprecated(since = "...", note = "...")]
        if let syn::Meta::List(list) = &attr.meta {
            let tokens_str = list.tokens.to_string();
            if !tokens_str.is_empty() {
                return Some(tokens_str);
            }
            return Some("Déprécié".to_string());
        }
    }
    None
}

/// Découvre récursivement tous les fichiers Rust valides
fn collect_rust_files(root: &Path, ignore_tests: bool) -> Vec<PathBuf> {
    let mut files = Vec::new();

    if root.is_file() {
        if root.extension().is_some_and(|ext| ext == "rs") {
            files.push(root.to_path_buf());
        }
        return files;
    }

    for entry in WalkDir::new(root)
        .into_iter()
        .filter_map(Result::ok)
        .filter(|e| e.file_type().is_file())
    {
        let path = entry.path();
        if path.extension().is_some_and(|ext| ext == "rs") {
            if ignore_tests {
                let path_str = path.to_string_lossy();
                if path_str.contains("/tests/") || path_str.contains("\\tests\\") {
                    continue;
                }
            }
            files.push(path.to_path_buf());
        }
    }
    files.sort();
    files
}

/// Lit et parse un fichier source Rust en AST `syn::File`
fn parse_rust_file(path: &Path) -> Result<(String, syn::File)> {
    let content = fs::read_to_string(path)
        .with_context(|| format!("Impossible de lire le fichier : {}", path.display()))?;

    let syntax = syn::parse_file(&content)
        .with_context(|| format!("Erreur lors du parsing syntaxique de : {}", path.display()))?;

    Ok((content, syntax))
}

/// Exécute l'analyse statique complète sur un ensemble de fichiers
pub fn run_analysis(
    target_path: &Path,
    ignore_tests: bool,
) -> Result<AnalysisReport> {
    let files = collect_rust_files(target_path, ignore_tests);
    let mut parsed_files = Vec::with_capacity(files.len());

    // Étape 1 : Lecture et parsing
    for path in &files {
        match parse_rust_file(path) {
            Ok((content, ast)) => parsed_files.push((path.clone(), content, ast)),
            Err(err) => eprintln!("{}: {}", "Avertissement".yellow().bold(), err),
        }
    }

    // Étape 2 : Collecte des identifiants dépréciés déclarés dans le projet
    let mut collector = DeprecationCollector::default();
    for (_path, _content, ast) in &parsed_files {
        collector.visit_file(ast);
    }

    let mut report = AnalysisReport {
        scanned_files: parsed_files.len(),
        ..Default::default()
    };

    // Étape 3 : Analyse approfondie avec recherche d'unsafe et d'appels dépréciés
    for (path, _content, ast) in &parsed_files {
        let file_path_str = path.to_string_lossy();
        let mut analyzer = AstAnalyzer::new(&file_path_str, &collector.deprecated_identifiers);
        analyzer.visit_file(ast);

        for issue in analyzer.issues {
            match issue.kind {
                IssueKind::UnsafeBlock
                | IssueKind::UnsafeFunction
                | IssueKind::UnsafeTrait
                | IssueKind::UnsafeImpl => report.unsafe_count += 1,
                IssueKind::DeprecatedDeclaration | IssueKind::DeprecatedCall => {
                    report.deprecated_count += 1
                }
            }
            report.total_issues += 1;
            report.issues.push(issue);
        }
    }

    Ok(report)
}

/// Présente les résultats de manière lisible et colorée dans la console
fn display_console_report(report: &AnalysisReport) {
    println!("{}", "=================================================".bold().blue());
    println!("{}", "   Rapport d'Analyse Statique de Code Rust".bold().white());
    println!("{}", "=================================================".bold().blue());
    println!(
        "Fichiers scannés : {}\nProblèmes trouvés : {} (Unsafe: {}, Dépréciés: {})\n",
        report.scanned_files.to_string().cyan(),
        report.total_issues.to_string().yellow().bold(),
        report.unsafe_count.to_string().red().bold(),
        report.deprecated_count.to_string().yellow().bold()
    );

    if report.issues.is_empty() {
        println!(
            "{}",
            "✔ Aucun bloc unsafe ni élément déprécié détecté. Code sain !"
                .green()
                .bold()
        );
        return;
    }

    for issue in &report.issues {
        let (tag, color_prefix) = match issue.kind {
            IssueKind::UnsafeBlock => ("UNSAFE BLOCK", "red"),
            IssueKind::UnsafeFunction => ("UNSAFE FN", "red"),
            IssueKind::UnsafeTrait => ("UNSAFE TRAIT", "red"),
            IssueKind::UnsafeImpl => ("UNSAFE IMPL", "red"),
            IssueKind::DeprecatedDeclaration => ("DEPRECATED DECL", "yellow"),
            IssueKind::DeprecatedCall => ("DEPRECATED CALL", "yellow"),
        };

        let badge = match color_prefix {
            "red" => format!("[{tag}]").red().bold(),
            _ => format!("[{tag}]").yellow().bold(),
        };

        println!(
            "{} {}:{}:{}",
            badge,
            issue.location.file.bold(),
            issue.location.start_line.to_string().cyan(),
            issue.location.start_col.to_string().cyan()
        );
        println!("  └── {}", issue.message);

        if let Some(details) = &issue.details {
            println!("      Détails : {}", details.italic().dimmed());
        }
        println!();
    }
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    let report = run_analysis(&cli.path, cli.ignore_tests)
        .with_context(|| format!("Échec de l'analyse pour le chemin : {}", cli.path.display()))?;

    if cli.json {
        let json_output = serde_json::to_string_pretty(&report)
            .context("Erreur de sérialisation JSON du rapport")?;
        println!("{json_output}");
    } else {
        display_console_report(&report);
    }

    let mut has_failure = false;
    if cli.deny_unsafe && report.unsafe_count > 0 {
        eprintln!(
            "{}",
            "Erreur : Le seuil de tolérance pour le code unsafe est dépassé (--deny-unsafe)."
                .red()
                .bold()
        );
        has_failure = true;
    }

    if cli.deny_deprecated && report.deprecated_count > 0 {
        eprintln!(
            "{}",
            "Erreur : Le seuil de tolérance pour les éléments dépréciés est dépassé (--deny-deprecated)."
                .red()
                .bold()
        );
        has_failure = true;
    }

    if has_failure {
        std::process::exit(1);
    }

    Ok(())
}

