        }
    }

    pub fn crossing_delay_ms(&self) -> u64 {
        match self {
            VehicleType::Motorcycle => 250,
            VehicleType::Car => 450,
            VehicleType::Bus => 900,
        }
    }
}

#[derive(Debug, Clone)]
pub struct Vehicle {
    pub id: u64,
    pub vehicle_type: VehicleType,
    pub direction: Direction,
    pub entered_queue_at: Instant,
}

#[derive(Default)]
pub struct SimulationStats {
    pub total_spawned: AtomicUsize,
    pub total_crossed: AtomicUsize,
    pub cumulative_wait_time_ms: AtomicU64,
}

impl SimulationStats {
    pub fn record_crossing(&self, wait_time: Duration) {
        self.total_crossed.fetch_add(1, Ordering::Relaxed);
        self.cumulative_wait_time_ms
            .fetch_add(wait_time.as_millis() as u64, Ordering::Relaxed);
    }

    pub fn average_wait_time_ms(&self) -> f64 {
        let crossed = self.total_crossed.load(Ordering::Relaxed);
        if crossed == 0 {
            0.0
        } else {
            self.cumulative_wait_time_ms.load(Ordering::Relaxed) as f64 / crossed as f64
        }
    }
}

pub struct TrafficLightController {
    pub active_direction: RwLock<Direction>,
    pub light_state: RwLock<LightColor>,
    pub green_duration: Duration,
    pub orange_duration: Duration,
    pub red_clearance_duration: Duration,
}

impl TrafficLightController {
    pub fn new(green_sec: u64, orange_sec: u64, red_clearance_sec: u64) -> Self {
        Self {
            active_direction: RwLock::new(Direction::NorthSouth),
            light_state: RwLock::new(LightColor::Green),
            green_duration: Duration::from_secs(green_sec),
            orange_duration: Duration::from_secs(orange_sec),
            red_clearance_duration: Duration::from_secs(red_clearance_sec),
        }
    }

    pub async fn can_pass(&self, dir: Direction) -> bool {
        let active = *self.active_direction.read().await;
        let light = *self.light_state.read().await;
        active == dir && light == LightColor::Green
    }
}

pub struct Intersection {
    pub name: String,
    pub controller: Arc<TrafficLightController>,
    pub queue_ns: Mutex<VecDeque<Vehicle>>,
    pub queue_ew: Mutex<VecDeque<Vehicle>>,
    pub stats: Arc<SimulationStats>,
}

impl Intersection {
    pub fn new(name: &str, stats: Arc<SimulationStats>) -> Arc<Self> {
        Arc::new(Self {
            name: name.to_string(),
            controller: Arc::new(TrafficLightController::new(4, 1, 1)),
            queue_ns: Mutex::new(VecDeque::new()),
            queue_ew: Mutex::new(VecDeque::new()),
            stats,
        })
    }

    pub async fn push_vehicle(&self, vehicle: Vehicle) {
        match vehicle.direction {
            Direction::NorthSouth => {
                let mut q = self.queue_ns.lock().await;
                q.push_back(vehicle);
            }
            Direction::EastWest => {
                let mut q = self.queue_ew.lock().await;
                q.push_back(vehicle);
            }
        }
    }

    pub async fn get_queue_len(&self, dir: Direction) -> usize {
        match dir {
            Direction::NorthSouth => self.queue_ns.lock().await.len(),
            Direction::EastWest => self.queue_ew.lock().await.len(),
        }
    }
}

pub async fn run_traffic_light_cycle(
    intersection_name: String,
    controller: Arc<TrafficLightController>,
    mut shutdown: broadcast::Receiver<()>,
) {
    loop {
        // 1. Feu Vert
        {
            let mut light = controller.light_state.write().await;
            *light = LightColor::Green;
        }
        let active_dir = *controller.active_direction.read().await;
        tracing::info!(
            "[{}] Axe {} passe au {}",
            intersection_name,
            active_dir.as_str().cyan(),
            LightColor::Green.badge()
        );

        tokio::select! {
            _ = tokio::time::sleep(controller.green_duration) => {}
            _ = shutdown.recv() => break,
        }

        // 2. Feu Orange
        {
            let mut light = controller.light_state.write().await;
            *light = LightColor::Orange;
        }
        tracing::info!(
            "[{}] Axe {} passe au {}",
            intersection_name,
            active_dir.as_str().cyan(),
            LightColor::Orange.badge()
        );

        tokio::select! {
            _ = tokio::time::sleep(controller.orange_duration) => {}
            _ = shutdown.recv() => break,
        }

        // 3. Feu Rouge général (dégagement de l'intersection)
        {
            let mut light = controller.light_state.write().await;
            *light = LightColor::Red;
        }
        tracing::info!(
            "[{}] Dégagement : Tous les axes au {}",
            intersection_name,
            LightColor::Red.badge()
        );

        tokio::select! {
            _ = tokio::time::sleep(controller.red_clearance_duration) => {}
            _ = shutdown.recv() => break,
        }

        // 4. Inversion de l'axe actif
        {
            let mut active = controller.active_direction.write().await;
            *active = active.opposite();
        }
    }
}

pub async fn run_intersection_processor(
    intersection: Arc<Intersection>,
    mut shutdown: broadcast::Receiver<()>,
) {
    let mut ticker = tokio::time::interval(Duration::from_millis(100));

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                let active_dir = *intersection.controller.active_direction.read().await;
                let is_green = intersection.controller.can_pass(active_dir).await;

                if is_green {
                    let maybe_vehicle = match active_dir {
                        Direction::NorthSouth => {
                            let mut q = intersection.queue_ns.lock().await;
                            q.pop_front()
                        }
                        Direction::EastWest => {
                            let mut q = intersection.queue_ew.lock().await;
                            q.pop_front()
                        }
                    };

                    if let Some(vehicle) = maybe_vehicle {
                        let wait_time = vehicle.entered_queue_at.elapsed();
                        intersection.stats.record_crossing(wait_time);

                        tracing::info!(
                            "[{}] Traversée : {} #{} ({}) | Attente: {:.2}s",
                            intersection.name,
                            vehicle.vehicle_type.name().bold(),
                            vehicle.id,
                            vehicle.direction.as_str(),
                            wait_time.as_secs_f32()
                        );

                        // Temps de franchissement physique du carrefour
                        tokio::time::sleep(Duration::from_millis(vehicle.vehicle_type.crossing_delay_ms())).await;
                    }
                }
            }
            _ = shutdown.recv() => break,
        }
    }
}

pub async fn run_vehicle_spawner(
    intersection: Arc<Intersection>,
    direction: Direction,
    next_id: Arc<AtomicU64>,
    stats: Arc<SimulationStats>,
    is_running: Arc<AtomicBool>,
    mut shutdown: broadcast::Receiver<()>,
) {
    while is_running.load(Ordering::Relaxed) {
        let delay_ms = {
            let mut rng = rand::thread_rng();
            rng.gen_range(600..1800)
        };

        tokio::select! {
            _ = tokio::time::sleep(Duration::from_millis(delay_ms)) => {
                let id = next_id.fetch_add(1, Ordering::Relaxed);
                let vtype = {
                    let mut rng = rand::thread_rng();
                    match rng.gen_range(0..10) {
                        0..=6 => VehicleType::Car,
                        7..=8 => VehicleType::Motorcycle,
                        _ => VehicleType::Bus,
                    }
                };

                let vehicle = Vehicle {
                    id,
                    vehicle_type: vtype,
                    direction,
                    entered_queue_at: Instant::now(),
                };

                stats.total_spawned.fetch_add(1, Ordering::Relaxed);
                intersection.push_vehicle(vehicle).await;
            }
            _ = shutdown.recv() => break,
        }
    }
}

pub async fn run_dashboard(
    intersection: Arc<Intersection>,
    stats: Arc<SimulationStats>,
    mut shutdown: broadcast::Receiver<()>,
) {
    let mut ticker = tokio::time::interval(Duration::from_secs(2));

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                let q_ns = intersection.get_queue_len(Direction::NorthSouth).await;
                let q_ew = intersection.get_queue_len(Direction::EastWest).await;
                let active = *intersection.controller.active_direction.read().await;
                let light = *intersection.controller.light_state.read().await;

                let spawned = stats.total_spawned.load(Ordering::Relaxed);
                let crossed = stats.total_crossed.load(Ordering::Relaxed);
                let avg_wait = stats.average_wait_time_ms();

                println!("\n{}", "==================== ÉTAT DU RÉSEAU URBAIN ====================".magenta().bold());
                println!("  Carrefour : {}", intersection.name.bold());
                println!("  Axe actif : {} | Feu : {}", active.as_str().cyan().bold(), light.badge());
                println!("  Files d'attente :");
                println!("    * [Nord-Sud] : {} véhicules en file", q_ns.to_string().yellow());
                println!("    * [Est-Ouest] : {} véhicules en file", q_ew.to_string().yellow());
                println!("  Statistiques globales :");
                println!("    * Véhicules générés : {}", spawned.to_string().bold());
                println!("    * Véhicules ayant franchi : {}", crossed.to_string().green().bold());
                println!("    * Temps d'attente moyen : {:.2} ms", avg_wait);
                println!("{}\n", "===============================================================".magenta().bold());
            }
            _ = shutdown.recv() => break,
        }
    }
}

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    println!("{}", "=== Démarrage du Simulateur de Réseau Routier Urbain ===".green().bold());
    println!("Appuyez sur Ctrl+C pour arrêter proprement la simulation à tout moment.\n");

    let stats = Arc::new(SimulationStats::default());
    let intersection = Intersection::new("Place de l'Étoile", Arc::clone(&stats));

    let (shutdown_tx, _) = broadcast::channel::<()>(16);
    let next_vehicle_id = Arc::new(AtomicU64::new(1));
    let is_running = Arc::new(AtomicBool::new(true));

    // Lancement du contrôleur de feux
    let light_handle = tokio::spawn(run_traffic_light_cycle(
        intersection.name.clone(),
        Arc::clone(&intersection.controller),
        shutdown_tx.subscribe(),
    ));

    // Lancement du processeur de traversée
    let processor_handle = tokio::spawn(run_intersection_processor(
        Arc::clone(&intersection),
        shutdown_tx.subscribe(),
    ));

    // Lancement des générateurs de trafic pour les deux axes
    let spawner_ns = tokio::spawn(run_vehicle_spawner(
        Arc::clone(&intersection),
        Direction::NorthSouth,
        Arc::clone(&next_vehicle_id),
        Arc::clone(&stats),
        Arc::clone(&is_running),
        shutdown_tx.subscribe(),
    ));

    let spawner_ew = tokio::spawn(run_vehicle_spawner(
        Arc::clone(&intersection),
        Direction::EastWest,
        Arc::clone(&next_vehicle_id),
        Arc::clone(&stats),
        Arc::clone(&is_running),
        shutdown_tx.subscribe(),
    ));

    // Lancement du moniteur de statistiques (Dashboard)
    let dashboard_handle = tokio::spawn(run_dashboard(
        Arc::clone(&intersection),
        Arc::clone(&stats),
        shutdown_tx.subscribe(),
    ));

    // Attente du signal d'interruption (Ctrl+C) ou minuterie de démo si exécuté en non-interactif
    tokio::select! {
        res = tokio::signal::ctrl_c() => {
            match res {
                Ok(()) => println!("\n{}", "Signal d'arrêt reçu (Ctrl+C)...".yellow().bold()),
                Err(err) => eprintln!("Erreur lors de l'écoute du signal: {err}"),
            }
        }
        _ = tokio::time::sleep(Duration::from_secs(12)) => {
            println!("\n{}", "Fin du cycle de démonstration initiale (12s)...".cyan().bold());
        }
    }

    // Déclenchement de l'arrêt gracieux
    is_running.store(false, Ordering::Relaxed);
    let _ = shutdown_tx.send(());

    println!("{}", "Arrêt ordonné des coroutines Tokio en cours...".italic());

    let _ = tokio::join!(
        light_handle,
        processor_handle,
        spawner_ns,
        spawner_ew,
        dashboard_handle,
    );

    println!("{}", "=== Simulation terminée avec succès ===".green().bold());
    println!("Bilan final :");
    println!("  - Véhicules créés : {}", stats.total_spawned.load(Ordering::Relaxed));
    println!("  - Véhicules sortis : {}", stats.total_crossed.load(Ordering::Relaxed));
    println!("  - Temps moyen en file : {:.2} ms", stats.average_wait_time_ms());
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_traffic_light_controller_cycle() {
        let controller = TrafficLightController::new(1, 1, 1);
        assert!(controller.can_pass(Direction::NorthSouth).await);
        assert!(!controller.can_pass(Direction::EastWest).await);

        // Changement d'état vers Orange
        {
            let mut light = controller.light_state.write().await;
            *light = LightColor::Orange;
        }
        assert!(!controller.can_pass(Direction::NorthSouth).await);

        // Changement vers Rouge
        {
            let mut light = controller.light_state.write().await;
            *light = LightColor::Red;
        }
        assert!(!controller.can_pass(Direction::NorthSouth).await);

        // Changement vers l'axe opposé au Vert
        {
            let mut active = controller.active_direction.write().await;
            *active = Direction::EastWest;
            let mut light = controller.light_state.write().await;
            *light = LightColor::Green;
        }
        assert!(controller.can_pass(Direction::EastWest).await);
        assert!(!controller.can_pass(Direction::NorthSouth).await);
    }

    #[tokio::test]
    async fn test_vehicle_queue_and_crossing() {
        let stats = Arc::new(SimulationStats::default());
        let intersection = Intersection::new("Carrefour Test", Arc::clone(&stats));

        let v1 = Vehicle {
            id: 1,
            vehicle_type: VehicleType::Car,
            direction: Direction::NorthSouth,
            entered_queue_at: Instant::now(),
        };

        intersection.push_vehicle(v1).await;
        assert_eq!(intersection.get_queue_len(Direction::NorthSouth).await, 1);
        assert_eq!(intersection.get_queue_len(Direction::EastWest).await, 0);

        stats.record_crossing(Duration::from_millis(150));
        assert_eq!(stats.total_crossed.load(Ordering::Relaxed), 1);
        assert!((stats.average_wait_time_ms() - 150.0).abs() < f64::EPSILON);
    }
}

