                stats.total_spawned.fetch_add(1, Ordering::Relaxed);
                intersection.push_vehicle(vehicle).await;
            }
            _ = shutdown.recv() => break,
        }
    }
}

pub async fn run_dashboard(
    intersection: Arc<Intersection>,
    stats: Arc<SimulationStats>,
    mut shutdown: broadcast::Receiver<()>,
) {
    let mut ticker = tokio::time::interval(Duration::from_secs(2));

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                let q_ns = intersection.get_queue_len(Direction::NorthSouth).await;
                let q_ew = intersection.get_queue_len(Direction::EastWest).await;
                let active = *intersection.controller.active_direction.read().await;
                let light = *intersection.controller.light_state.read().await;

                let spawned = stats.total_spawned.load(Ordering::Relaxed);
                let crossed = stats.total_crossed.load(Ordering::Relaxed);
                let avg_wait = stats.average_wait_time_ms();

                println!("\n{}", "==================== ÉTAT DU RÉSEAU URBAIN ====================".magenta().bold());
                println!("  Carrefour : {}", intersection.name.bold());
                println!("  Axe actif : {} | Feu : {}", active.as_str().cyan().bold(), light.badge());
                println!("  Files d'attente :");
                println!("    * [Nord-Sud] : {} véhicules en file", q_ns.to_string().yellow());
                println!("    * [Est-Ouest] : {} véhicules en file", q_ew.to_string().yellow());
                println!("  Statistiques globales :");
                println!("    * Véhicules générés : {}", spawned.to_string().bold());
                println!("    * Véhicules ayant franchi : {}", crossed.to_string().green().bold());
                println!("    * Temps d'attente moyen : {:.2} ms", avg_wait);
                println!("{}\n", "===============================================================".magenta().bold());
            }
            _ = shutdown.recv() => break,
        }
    }
}

