    let (shutdown_tx, _) = broadcast::channel::<()>(16);
    let next_vehicle_id = Arc::new(AtomicU64::new(1));
    let is_running = Arc::new(AtomicBool::new(true));

    // Lancement du contrôleur de feux
    let light_handle = tokio::spawn(run_traffic_light_cycle(
        intersection.name.clone(),
        Arc::clone(&intersection.controller),
        shutdown_tx.subscribe(),
    ));

    // Lancement du processeur de traversée
    let processor_handle = tokio::spawn(run_intersection_processor(
        Arc::clone(&intersection),
        shutdown_tx.subscribe(),
    ));

    // Lancement des générateurs de trafic pour les deux axes
    let spawner_ns = tokio::spawn(run_vehicle_spawner(
        Arc::clone(&intersection),
        Direction::NorthSouth,
        Arc::clone(&next_vehicle_id),
        Arc::clone(&stats),
        Arc::clone(&is_running),
