// src/main.rs
use std::cmp::Ordering;
use std::collections::{BinaryHeap, HashMap};
use std::error::Error;
use std::fmt;

/// Erreurs possibles lors des opérations de compression et décompression.
#[derive(Debug, PartialEq, Eq)]
pub enum HuffmanError {
    EmptyInput,
    CorruptedHeader(String),
    CorruptedBitstream(String),
    Utf8Error(String),
}

impl fmt::Display for HuffmanError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            HuffmanError::EmptyInput => write!(f, "L'entrée à compresser est vide."),
            HuffmanError::CorruptedHeader(msg) => write!(f, "En-tête corrompu : {}", msg),
            HuffmanError::CorruptedBitstream(msg) => write!(f, "Flux binaire corrompu : {}", msg),
            HuffmanError::Utf8Error(msg) => write!(f, "Erreur de décodage UTF-8 : {}", msg),
        }
    }
}

impl Error for HuffmanError {}

/// Nœud de l'arbre de Huffman.
#[derive(Debug, Clone, Eq, PartialEq)]
pub enum HuffmanNode {
    Leaf {
        frequency: usize,
        symbol: u8,
    },
    Internal {
        frequency: usize,
        min_symbol: u8,
        left: Box<HuffmanNode>,
        right: Box<HuffmanNode>,
    },
}

impl HuffmanNode {
    pub fn frequency(&self) -> usize {
        match self {
            HuffmanNode::Leaf { frequency, .. } => *frequency,
            HuffmanNode::Internal { frequency, .. } => *frequency,
        }
    }

    pub fn min_symbol(&self) -> u8 {
        match self {
            HuffmanNode::Leaf { symbol, .. } => *symbol,
            HuffmanNode::Internal { min_symbol, .. } => *min_symbol,
        }
    }
}

// Implémentation déterministe de Ord et PartialOrd pour utiliser BinaryHeap comme Min-Heap.
impl Ord for HuffmanNode {
    fn cmp(&self, other: &Self) -> Ordering {
        // Priorité d'abord sur la plus petite fréquence.
        // En cas d'égalité, départage strict sur le plus petit symbole pour garantir
        // un arbre 100% reproductible entre compression et décompression.
        other
            .frequency()
            .cmp(&self.frequency())
            .then_with(|| other.min_symbol().cmp(&self.min_symbol()))
    }
}

impl PartialOrd for HuffmanNode {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

/// Gestionnaire d'écriture bit par bit dans un tampon d'octets.
#[derive(Default, Debug)]
pub struct BitWriter {
    buffer: Vec<u8>,
    current_byte: u8,
    bit_count: u8, // de 0 à 7
    total_bits: usize,
}

impl BitWriter {
    pub fn new() -> Self {
        Self::default()
    }

    /// Écrit un bit unique (booléen : true = 1, false = 0).
    pub fn write_bit(&mut self, bit: bool) {
        if bit {
            self.current_byte |= 1 << (7 - self.bit_count);
        }
        self.bit_count += 1;
        self.total_bits += 1;

        if self.bit_count == 8 {
            self.buffer.push(self.current_byte);
            self.current_byte = 0;
            self.bit_count = 0;
        }
    }

    /// Écrit une séquence de bits représentée par une slice de booléens.
    pub fn write_bits(&mut self, bits: &[bool]) {
        for &bit in bits {
            self.write_bit(bit);
        }
    }

    /// Finalise l'écriture en vidant le reste éventuel dans le buffer et retourne l'ensemble d'octets et le total de bits.
    pub fn finalize(mut self) -> (Vec<u8>, usize) {
        let total = self.total_bits;
        if self.bit_count > 0 {
            self.buffer.push(self.current_byte);
        }
        (self.buffer, total)
    }
}

/// Gestionnaire de lecture bit par bit à partir d'une tranche d'octets.
pub struct BitReader<'a> {
    data: &'a [u8],
    byte_index: usize,
    bit_index: u8, // de 0 à 7
    total_bits: usize,
    read_bits: usize,
}

impl<'a> BitReader<'a> {
    pub fn new(data: &'a [u8], total_bits: usize) -> Self {
        Self {
            data,
            byte_index: 0,
            bit_index: 0,
            total_bits,
            read_bits: 0,
        }
    }

    /// Lit le prochain bit s'il en reste à lire.
    pub fn read_bit(&mut self) -> Option<bool> {
        if self.read_bits >= self.total_bits || self.byte_index >= self.data.len() {
            return None;
        }

        let byte = self.data[self.byte_index];
        let bit = (byte & (1 << (7 - self.bit_index))) != 0;

        self.bit_index += 1;
        self.read_bits += 1;

        if self.bit_index == 8 {
            self.bit_index = 0;
            self.byte_index += 1;
        }

        Some(bit)
    }
}

/// Moteur de compression / décompression Huffman.
pub struct HuffmanCodec;

impl HuffmanCodec {
    /// Construit l'arbre de Huffman à partir des fréquences des symboles.
    pub fn build_tree(frequencies: &HashMap<u8, usize>) -> Result<HuffmanNode, HuffmanError> {
        if frequencies.is_empty() {
            return Err(HuffmanError::EmptyInput);
        }

        let mut heap = BinaryHeap::new();
        for (&symbol, &freq) in frequencies {
            heap.push(HuffmanNode::Leaf {
                frequency: freq,
                symbol,
            });
        }

        // Cas particulier : un seul symbole distinct
        if heap.len() == 1 {
            let only_node = heap.pop().expect("Tas non vide garanti");
            let min_symbol = only_node.min_symbol();
            return Ok(HuffmanNode::Internal {
                frequency: only_node.frequency(),
                min_symbol,
                left: Box::new(only_node.clone()),
                right: Box::new(only_node),
            });
        }

        while heap.len() > 1 {
            let left = heap.pop().expect("Tas contenant au moins 2 éléments");
            let right = heap.pop().expect("Tas contenant au moins 2 éléments");
            let merged_freq = left.frequency() + right.frequency();
            let min_symbol = left.min_symbol().min(right.min_symbol());

            heap.push(HuffmanNode::Internal {
                frequency: merged_freq,
                min_symbol,
                left: Box::new(left),
                right: Box::new(right),
            });
        }

        heap.pop().ok_or(HuffmanError::EmptyInput)
    }

    /// Génère la table de correspondance symbole -> séquence binaire.
    pub fn generate_codes(root: &HuffmanNode) -> HashMap<u8, Vec<bool>> {
        let mut codes = HashMap::new();
        let mut current_path = Vec::new();
        Self::traverse_codes(root, &mut current_path, &mut codes);
        codes
    }

    fn traverse_codes(
        node: &HuffmanNode,
        current_path: &mut Vec<bool>,
        codes: &mut HashMap<u8, Vec<bool>>,
    ) {
        match node {
            HuffmanNode::Leaf { symbol, .. } => {
                // Si l'arbre a été artificiellement dupliqué pour un seul symbole unique,
                // un code de longueur 1 ([false]) suffit.
                if current_path.is_empty() {
                    codes.insert(*symbol, vec![false]);
                } else {
                    codes.insert(*symbol, current_path.clone());
                }
            }
            HuffmanNode::Internal { left, right, .. } => {
                current_path.push(false);
                Self::traverse_codes(left, current_path, codes);
                current_path.pop();

                current_path.push(true);
                Self::traverse_codes(right, current_path, codes);
                current_path.pop();
            }
        }
    }

    /// Compresse des données brutes en un flux d'octets contenant l'en-tête et les données codées.
    pub fn compress(input: &[u8]) -> Result<Vec<u8>, HuffmanError> {
        if input.is_empty() {
            return Err(HuffmanError::EmptyInput);
        }

        // 1. Table des fréquences
        let mut frequencies = HashMap::new();
        for &byte in input {
            *frequencies.entry(byte).or_insert(0) += 1;
        }

        // 2. Construction de l'arbre et des codes
        let root = Self::build_tree(&frequencies)?;
        let code_map = Self::generate_codes(&root);

        // 3. Encodage des données
        let mut bit_writer = BitWriter::new();
        for byte in input {
            let bits = code_map
                .get(byte)
                .ok_or_else(|| HuffmanError::CorruptedBitstream(format!("Symbole non indexé: {}", byte)))?;
            bit_writer.write_bits(bits);
        }
        let (encoded_data, total_bits) = bit_writer.finalize();

        // 4. Construction du binaire final (En-tête + Données)
        // En-tête :
        // - 2 octets : nombre d'entrées dans la table des fréquences (u16)
        // - Pour chaque entrée : 1 octet (symbole) + 8 octets (fréquence en u64 little endian)
        // - 8 octets : nombre total de bits utiles (u64 little endian)
        let mut output = Vec::new();

        let num_entries = frequencies.len() as u16;
        output.extend_from_slice(&num_entries.to_le_bytes());

        for (&sym, &freq) in &frequencies {
            output.push(sym);
            output.extend_from_slice(&(freq as u64).to_le_bytes());
        }

        output.extend_from_slice(&(total_bits as u64).to_le_bytes());
        output.extend_from_slice(&encoded_data);

        Ok(output)
    }

    /// Décompresse un flux d'octets généré par `compress` et restitue les données d'origine.
    pub fn decompress(compressed: &[u8]) -> Result<Vec<u8>, HuffmanError> {
        let mut cursor = 0;

        if compressed.len() < 2 {
            return Err(HuffmanError::CorruptedHeader("Fichier trop court pour l'en-tête".into()));
        }

        let num_entries = u16::from_le_bytes([compressed[0], compressed[1]]) as usize;
        cursor += 2;

        let entry_size = 1 + 8;
        let required_header_size = cursor + num_entries * entry_size + 8;
        if compressed.len() < required_header_size {
            return Err(HuffmanError::CorruptedHeader("Taille des données insuffisante pour les fréquences".into()));
        }

        let mut frequencies = HashMap::with_capacity(num_entries);
        for _ in 0..num_entries {
            let symbol = compressed[cursor];
            cursor += 1;

            let mut freq_bytes = [0u8; 8];
            freq_bytes.copy_from_slice(&compressed[cursor..cursor + 8]);
            cursor += 8;

            let freq = u64::from_le_bytes(freq_bytes) as usize;
            frequencies.insert(symbol, freq);
        }

        let mut total_bits_bytes = [0u8; 8];
        total_bits_bytes.copy_from_slice(&compressed[cursor..cursor + 8]);
        cursor += 8;
        let total_bits = u64::from_le_bytes(total_bits_bytes) as usize;

        let payload = &compressed[cursor..];
        let root = Self::build_tree(&frequencies)?;

        let mut reader = BitReader::new(payload, total_bits);
        let mut decompressed = Vec::new();
        let mut current_node = &root;

        while let Some(bit) = reader.read_bit() {
            current_node = match current_node {
                HuffmanNode::Internal { left, right, .. } => {
                    if bit {
                        right.as_ref()
                    } else {
                        left.as_ref()
                    }
                }
                HuffmanNode::Leaf { .. } => {
                    return Err(HuffmanError::CorruptedBitstream(
                        "Arbre invalide lors de la traversée".into(),
                    ));
                }
            };

            if let HuffmanNode::Leaf { symbol, .. } = current_node {
                decompressed.push(*symbol);
                current_node = &root;
            }
        }

        // Si le nœud actuel n'est pas revenu à la racine, il manque des bits
        if !matches!(current_node, HuffmanNode::Internal { .. } if std::ptr::eq(current_node, &root))
            && current_node != &root
        {
            return Err(HuffmanError::CorruptedBitstream("Flux incomplet".into()));
        }

        Ok(decompressed)
    }
}

fn main() -> Result<(), Box<dyn Error>> {
    println!("=== Moteur de compression textuelle basé sur l'algorithme de Huffman ===\n");

    let sample_texts = vec![
        "L'algorithme de Huffman est un algorithme de compression de données sans perte.",
        "aaaaabbbbcccdde",
        "Une phrase répétitive : compression, compression, décompression, décompression !",
        "X",
    ];

    for (i, text) in sample_texts.into_iter().enumerate() {
        println!("Test #{} :", i + 1);
        println!("Texte original : {:?}", text);

        let input_bytes = text.as_bytes();
        let compressed = HuffmanCodec::compress(input_bytes)?;
        let decompressed_bytes = HuffmanCodec::decompress(&compressed)?;
        let decompressed_text = String::from_utf8(decompressed_bytes)
            .map_err(|e| HuffmanError::Utf8Error(e.to_string()))?;

        println!("  Taille originale   : {} octets", input_bytes.len());
        println!("  Taille compressée  : {} octets (avec en-tête complet)", compressed.len());

        let ratio = (compressed.len() as f64 / input_bytes.len() as f64) * 100.0;
        println!("  Ratio de taille    : {:.2}%", ratio);

        assert_eq!(text, decompressed_text);
        println!("  Intégrité          : Vérifiée avec succès !\n");
    }

    println!("Tous les tests de compression et décompression se sont déroulés avec succès.");
    Ok(())
}

