fn display_stats(track_name: &str, stats: &TrackStats, as_json: bool) {
    if as_json {
        let json_output = serde_json::json!({
            "track_name": track_name,
            "metrics": stats,
        });
        println!("{}", serde_json::to_string_pretty(&json_output).unwrap_or_default());
    } else {
        println!("============================================================");
        println!(" Trace : {}", track_name);
        println!("------------------------------------------------------------");
        println!(" Nombre de points    : {}", stats.total_points);
        println!(" Distance totale     : {:.2} km ({:.0} m)", stats.distance_meters / 1000.0, stats.distance_meters);
        println!(" Dénivelé positif D+ : +{:.1} m", stats.elevation_gain);
        println!(" Dénivelé négatif D- : -{:.1} m", stats.elevation_loss);
        if let (Some(min), Some(max)) = (stats.min_elevation, stats.max_elevation) {
            println!(" Altitude min / max  : {:.1} m / {:.1} m", min, max);
        }
        if let Some(dur) = stats.duration_seconds {
            let hours = dur / 3600;
            let minutes = (dur % 3600) / 60;
            let seconds = dur % 60;
            println!(" Durée               : {:02}h {:02}m {:02}s", hours, minutes, seconds);
            if dur > 0 {
                let speed_kmh = (stats.distance_meters / 1000.0) / (dur as f64 / 3600.0);
                println!(" Vitesse moyenne     : {:.2} km/h", speed_kmh);
            }
        }
        println!("============================================================\n");
    }
}

