        run_demo(cli.threshold, cli.json)?;
        return Ok(());
    }

    let file_path = cli.file.as_ref().ok_or("Chemin du fichier manquant")?;
    let tracks = parse_file(file_path, cli.format)?;

    if tracks.is_empty() {
        eprintln!("Avertissement : Aucune trace GPS trouvée dans le fichier.");
        return Ok(());
    }

    for trk in &tracks {
        let stats = trk.compute_stats(cli.threshold);
        let name = trk.name.as_deref().unwrap_or("Trace sans titre");
        display_stats(name, &stats, cli.json);
    }

    Ok(())
}

