/// Erreurs possibles lors de la manipulation et du parsing des fichiers GPS
#[derive(Debug, Error)]
pub enum GeoError {
    #[error("Erreur I/O: {0}")]
    Io(#[from] std::io::Error),

    #[error("Erreur lors du parsing XML: {0}")]
    Xml(#[from] quick_xml::Error),

    #[error("Format non supporté ou indéterminable pour le fichier: {0}")]
    UnsupportedFormat(String),

    #[error("Données de coordonnées invalides: {0}")]
    InvalidCoordinates(String),

    #[error("Erreur de format de date: {0}")]
    InvalidDate(#[from] chrono::ParseError),
}

/// Point GPS WGS-84 standardisé
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GeoPoint {
    pub latitude: f64,
    pub longitude: f64,
    pub elevation: Option<f64>,
    pub time: Option<DateTime<Utc>>,
}

impl GeoPoint {
    pub fn new(latitude: f64, longitude: f64, elevation: Option<f64>, time: Option<DateTime<Utc>>) -> Self {
        Self {
            latitude,
            longitude,
            elevation,
            time,
        }
    }

    /// Calcule la distance 2D (au sol) en mètres par rapport à un autre point via la formule Haversine
    pub fn distance_to(&self, other: &GeoPoint) -> f64 {
        const EARTH_RADIUS_METERS: f64 = 6_371_000.0;

        let lat1_rad = self.latitude.to_radians();
        let lat2_rad = other.latitude.to_radians();
        let delta_lat = (other.latitude - self.latitude).to_radians();
        let delta_lon = (other.longitude - self.longitude).to_radians();

        let a = (delta_lat / 2.0).sin().powi(2)
            + lat1_rad.cos() * lat2_rad.cos() * (delta_lon / 2.0).sin().powi(2);
        let c = 2.0 * a.sqrt().atan2((1.0 - a).sqrt());

        EARTH_RADIUS_METERS * c
    }

    /// Calcule la distance 3D tenant compte de l'élévation si disponible
    pub fn distance_3d_to(&self, other: &GeoPoint) -> f64 {
        let dist_2d = self.distance_to(other);
        match (self.elevation, other.elevation) {
            (Some(e1), Some(e2)) => {
                let delta_ele = e2 - e1;
                (dist_2d.powi(2) + delta_ele.powi(2)).sqrt()
            }
            _ => dist_2d,
        }
    }
}

/// Segment de trace GPS composé d'une suite de points
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct TrackSegment {
    pub points: Vec<GeoPoint>,
}

/// Trace GPS complète
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct Track {
    pub name: Option<String>,
    pub segments: Vec<TrackSegment>,
}

/// Statistiques et analyse d'une trace GPS
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TrackStats {
    pub total_points: usize,
    pub distance_meters: f64,
    pub elevation_gain: f64,   // Dénivelé positif cumulé (D+)
    pub elevation_loss: f64,   // Dénivelé négatif cumulé (D-)
    pub min_elevation: Option<f64>,
    pub max_elevation: Option<f64>,
    pub duration_seconds: Option<i64>,
}

impl Track {
    /// Calcule l'ensemble des métriques topographiques et cinématiques
    /// `elevation_threshold` permet de filtrer le bruit barométrique/GPS (ex: 1.0 m)
    pub fn compute_stats(&self, elevation_threshold: f64) -> TrackStats {
        let mut total_points = 0;
        let mut distance_meters = 0.0;
        let mut elevation_gain = 0.0;
        let mut elevation_loss = 0.0;
        let mut min_elevation: Option<f64> = None;
        let mut max_elevation: Option<f64> = None;
        let mut first_timestamp: Option<DateTime<Utc>> = None;
        let mut last_timestamp: Option<DateTime<Utc>> = None;

        for segment in &self.segments {
            total_points += segment.points.len();

            let mut prev_point: Option<&GeoPoint> = None;
            for pt in &segment.points {
                if first_timestamp.is_none() && pt.time.is_some() {
                    first_timestamp = pt.time;
                }
                if pt.time.is_some() {
                    last_timestamp = pt.time;
                }

                if let Some(ele) = pt.elevation {
                    min_elevation = Some(min_elevation.map_or(ele, |current| current.min(ele)));
                    max_elevation = Some(max_elevation.map_or(ele, |current| current.max(ele)));
                }

                if let Some(prev) = prev_point {
                    distance_meters += prev.distance_3d_to(pt);

                    if let (Some(prev_ele), Some(cur_ele)) = (prev.elevation, pt.elevation) {
                        let diff = cur_ele - prev_ele;
                        if diff > elevation_threshold {
                            elevation_gain += diff;
                        } else if diff < -elevation_threshold {
                            elevation_loss += diff.abs();
                        }
                    }
                }
                prev_point = Some(pt);
            }
        }

        let duration_seconds = match (first_timestamp, last_timestamp) {
            (Some(start), Some(end)) if end >= start => Some((end - start).num_seconds()),
            _ => None,
        };

        TrackStats {
            total_points,
            distance_meters,
            elevation_gain,
            elevation_loss,
            min_elevation,
            max_elevation,
            duration_seconds,
        }
    }
}

/// Formats supportés
#[derive(Debug, Clone, Copy, ValueEnum)]
pub enum FileFormat {
    Gpx,
    Kml,
    Auto,
}

/// Parser GPX basé sur `quick-xml`
pub struct GpxParser;

impl GpxParser {
    pub fn parse<R: std::io::BufRead>(reader: R) -> Result<Vec<Track>, GeoError> {
        let mut xml_reader = Reader::from_reader(reader);
        xml_reader.config_mut().trim_text(true);

        let mut buf = Vec::new();
        let mut tracks = Vec::new();
        let mut current_track: Option<Track> = None;
        let mut current_segment: Option<TrackSegment> = None;

        let mut current_lat: Option<f64> = None;
        let mut current_lon: Option<f64> = None;
        let mut current_ele: Option<f64> = None;
        let mut current_time: Option<DateTime<Utc>> = None;
        let mut current_tag = String::new();

        loop {
            match xml_reader.read_event_into(&mut buf)? {
                Event::Start(ref e) => {
                    let name = String::from_utf8_lossy(e.name().as_ref()).to_string();
                    current_tag = name.clone();

                    match name.as_str() {
                        "trk" => {
                            current_track = Some(Track::default());
                        }
                        "trkseg" => {
                            current_segment = Some(TrackSegment::default());
                        }
                        "trkpt" => {
                            current_lat = None;
                            current_lon = None;
                            current_ele = None;
                            current_time = None;

                            for attr in e.attributes().flatten() {
                                let key = String::from_utf8_lossy(attr.key.as_ref());
                                let val = String::from_utf8_lossy(&attr.value);
                                if key == "lat" {
                                    current_lat = val.parse::<f64>().ok();
                                } else if key == "lon" {
                                    current_lon = val.parse::<f64>().ok();
                                }
                            }
                        }
                        _ => {}
                    }
                }
                Event::Text(e) => {
                    let text = e.unescape().unwrap_or_default().to_string();
                    match current_tag.as_str() {
                        "ele" => {
                            if let Ok(ele) = text.parse::<f64>() {
                                current_ele = Some(ele);
                            }
                        }
                        "time" => {
                            if let Ok(parsed_time) = DateTime::parse_from_rfc3339(&text) {
                                current_time = Some(parsed_time.with_timezone(&Utc));
                            }
                        }
                        "name" => {
                            if let Some(ref mut trk) = current_track {
                                if trk.name.is_none() {
                                    trk.name = Some(text);
                                }
                            }
                        }
                        _ => {}
                    }
                }
                Event::End(ref e) => {
                    let name = String::from_utf8_lossy(e.name().as_ref()).to_string();
                    current_tag.clear();

                    match name.as_str() {
                        "trkpt" => {
                            if let (Some(lat), Some(lon)) = (current_lat, current_lon) {
                                let point = GeoPoint::new(lat, lon, current_ele, current_time);
                                if let Some(ref mut seg) = current_segment {
                                    seg.points.push(point);
                                }
                            }
                        }
                        "trkseg" => {
                            if let Some(seg) = current_segment.take() {
                                if let Some(ref mut trk) = current_track {
                                    trk.segments.push(seg);
                                }
                            }
                        }
                        "trk" => {
                            if let Some(trk) = current_track.take() {
                                tracks.push(trk);
                            }
                        }
                        _ => {}
                    }
                }
                Event::Eof => break,
                _ => {}
            }
            buf.clear();
        }

        Ok(tracks)
    }
}

/// Parser KML pour extraire les coordonnées des balises `<coordinates>`
pub struct KmlParser;

impl KmlParser {
    pub fn parse<R: std::io::BufRead>(reader: R) -> Result<Vec<Track>, GeoError> {
        let mut xml_reader = Reader::from_reader(reader);
        xml_reader.config_mut().trim_text(true);

        let mut buf = Vec::new();
        let mut tracks = Vec::new();
        let mut current_name: Option<String> = None;
        let mut in_placemark = false;
        let mut current_tag = String::new();

        loop {
            match xml_reader.read_event_into(&mut buf)? {
                Event::Start(ref e) => {
                    let tag_name = String::from_utf8_lossy(e.name().as_ref()).to_string();
                    current_tag = tag_name.clone();

                    if tag_name.ends_with("Placemark") {
                        in_placemark = true;
                        current_name = None;
                    }
                }
                Event::Text(e) => {
                    let text = e.unescape().unwrap_or_default().to_string();
                    if in_placemark && current_tag.ends_with("name") && current_name.is_none() {
                        current_name = Some(text.clone());
                    } else if current_tag.ends_with("coordinates") {
                        // Les coordonnées KML sont de la forme: lon,lat[,altitude] séparées par des espaces ou retours à la ligne
                        let mut segment = TrackSegment::default();
                        for token in text.split_whitespace() {
                            let parts: Vec<&str> = token.split(',').collect();
                            if parts.len() >= 2 {
                                if let (Ok(lon), Ok(lat)) = (parts[0].parse::<f64>(), parts[1].parse::<f64>()) {
                                    let ele = if parts.len() >= 3 {
                                        parts[2].parse::<f64>().ok()
                                    } else {
                                        None
                                    };
                                    segment.points.push(GeoPoint::new(lat, lon, ele, None));
                                }
                            }
                        }

                        if !segment.points.is_empty() {
                            let track = Track {
                                name: current_name.clone().or_else(|| Some("Trace KML".to_string())),
                                segments: vec![segment],
                            };
                            tracks.push(track);
                        }
                    }
                }
                Event::End(ref e) => {
                    let tag_name = String::from_utf8_lossy(e.name().as_ref()).to_string();
                    if tag_name.ends_with("Placemark") {
                        in_placemark = false;
                        current_name = None;
                    }
                    current_tag.clear();
                }
                Event::Eof => break,
                _ => {}
            }
            buf.clear();
        }

        Ok(tracks)
    }
}

/// Parseur universel avec détection de format
pub fn parse_file(path: &Path, format: FileFormat) -> Result<Vec<Track>, GeoError> {
    let file = File::open(path)?;
    let reader = BufReader::new(file);

    let effective_format = match format {
        FileFormat::Auto => {
            match path.extension().and_then(|s| s.to_str()).map(|s| s.to_lowercase()).as_deref() {
                Some("gpx") => FileFormat::Gpx,
                Some("kml") => FileFormat::Kml,
                _ => {
                    return Err(GeoError::UnsupportedFormat(
                        path.to_string_lossy().to_string(),
                    ));
                }
            }
        }
        f => f,
    };

    match effective_format {
        FileFormat::Gpx => GpxParser::parse(reader),
        FileFormat::Kml => KmlParser::parse(reader),
        FileFormat::Auto => unreachable!(),
    }
}

