// src/main.rs
use std::collections::HashMap;
use std::fmt;
use std::str::FromStr;
use thiserror::Error;

/// Erreurs possibles lors de l'analyse lexicale/syntaxique ou de l'exécution.
#[derive(Debug, Error, PartialEq, Eq)]
pub enum AsmError {
    #[error("Erreur de syntaxe à la ligne {line}: {message}")]
    SyntaxError { line: usize, message: String },

    #[error("Registre inconnu : '{0}'")]
    UnknownRegister(String),

    #[error("Étiquette non définie : '{0}'")]
    UndefinedLabel(String),

    #[error("Étiquette dupliquée : '{0}' à la ligne {1}")]
    DuplicateLabel(String, usize),

    #[error("Accès mémoire invalide à l'adresse {address} (taille mémoire: {memory_size})")]
    MemoryOutOfBounds { address: usize, memory_size: usize },

    #[error("Débordement de pile (Stack Overflow) : SP={sp}")]
    StackOverflow { sp: usize },

    #[error("Dépassement inférieur de pile (Stack Underflow) : SP={sp}")]
    StackUnderflow { sp: usize },

    #[error("Division ou modulo par zéro à l'instruction {pc}")]
    DivisionByZero { pc: usize },

    #[error("Dépassement du nombre maximal d'instructions autorisées ({0})")]
    MaxCyclesExceeded(usize),

    #[error("Tentative d'exécution au-delà des bornes du programme (PC: {pc})")]
    PcOutOfBounds { pc: usize },
}

/// Identifiants des registres disponibles dans la machine virtuelle.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Register {
    R0,
    R1,
    R2,
    R3,
    R4,
    R5,
    R6,
    R7,
    SP,
}

impl Register {
    pub const ALL: [Register; 9] = [
        Register::R0,
        Register::R1,
        Register::R2,
        Register::R3,
        Register::R4,
        Register::R5,
        Register::R6,
        Register::R7,
        Register::SP,
    ];

    pub fn index(self) -> usize {
        match self {
            Register::R0 => 0,
            Register::R1 => 1,
            Register::R2 => 2,
            Register::R3 => 3,
            Register::R4 => 4,
            Register::R5 => 5,
            Register::R6 => 6,
            Register::R7 => 7,
            Register::SP => 8,
        }
    }
}

impl FromStr for Register {
    type Err = AsmError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s.trim().to_uppercase().as_str() {
            "R0" => Ok(Register::R0),
            "R1" => Ok(Register::R1),
            "R2" => Ok(Register::R2),
            "R3" => Ok(Register::R3),
            "R4" => Ok(Register::R4),
            "R5" => Ok(Register::R5),
            "R6" => Ok(Register::R6),
            "R7" => Ok(Register::R7),
            "SP" => Ok(Register::SP),
            other => Err(AsmError::UnknownRegister(other.to_string())),
        }
    }
}

impl fmt::Display for Register {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let name = match self {
            Register::R0 => "R0",
            Register::R1 => "R1",
            Register::R2 => "R2",
            Register::R3 => "R3",
            Register::R4 => "R4",
            Register::R5 => "R5",
            Register::R6 => "R6",
            Register::R7 => "R7",
            Register::SP => "SP",
        };
        write!(f, "{name}")
    }
}

/// Opérande source ou destination.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Operand {
    /// Valeur immédiate (ex: 42, -5)
    Immediate(i64),
    /// Registre direct (ex: R0, SP)
    Reg(Register),
    /// Emplacement mémoire indirect (ex: [100], [R0])
    Memory(AddressMode),
}

/// Mode d'adressage mémoire.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AddressMode {
    Immediate(usize),
    Register(Register),
}

/// Condition de saut.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum JumpCondition {
    Always, // JMP
    Equal,  // JE / JZ
    NotEqual, // JNE / JNZ
    Greater, // JG
    GreaterOrEqual, // JGE
    Less, // JL
    LessOrEqual, // JLE
}

/// Cible d'un saut ou d'un appel.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum JumpTarget {
    Label(String),
    Address(usize),
}

/// Jeu d'instructions de l'assembleur.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Instruction {
    Mov(Register, Operand),
    Load(Register, AddressMode),
    Store(AddressMode, Operand),
    Add(Register, Operand),
    Sub(Register, Operand),
    Mul(Register, Operand),
    Div(Register, Operand),
    Mod(Register, Operand),
    Cmp(Operand, Operand),
    Jmp(JumpCondition, JumpTarget),
    Push(Operand),
    Pop(Register),
    Call(JumpTarget),
    Ret,
    Prn(Operand),
    Hlt,
}

/// Drapeaux de calcul arithmétique et de comparaison.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct Flags {
    pub zero: bool,
    pub sign: bool,
    pub overflow: bool,
}

/// État complet de la machine virtuelle.
pub struct Vm {
    pub registers: [i64; 9],
    pub memory: Vec<i64>,
    pub pc: usize,
    pub flags: Flags,
    pub halted: bool,
    pub total_cycles: usize,
    pub output_log: Vec<i64>,
}

impl Vm {
    pub const DEFAULT_MEMORY_SIZE: usize = 4096;

    pub fn new(memory_size: usize) -> Self {
        let mut vm = Self {
            registers: [0; 9],
            memory: vec![0; memory_size],
            pc: 0,
            flags: Flags::default(),
            halted: false,
            total_cycles: 0,
            output_log: Vec::new(),
        };
        // Initialise SP en haut de la mémoire
        vm.registers[Register::SP.index()] = memory_size as i64;
        vm
    }

    pub fn reset(&mut self) {
        self.registers.fill(0);
        self.memory.fill(0);
        self.pc = 0;
        self.flags = Flags::default();
        self.halted = false;
        self.total_cycles = 0;
        self.output_log.clear();
        self.registers[Register::SP.index()] = self.memory.len() as i64;
    }

    pub fn get_reg(&self, reg: Register) -> i64 {
        self.registers[reg.index()]
    }

    pub fn set_reg(&mut self, reg: Register, val: i64) {
        self.registers[reg.index()] = val;
    }

    fn resolve_address(&self, mode: &AddressMode) -> Result<usize, AsmError> {
        let addr = match mode {
            AddressMode::Immediate(imm) => *imm,
            AddressMode::Register(reg) => {
                let val = self.get_reg(*reg);
                if val < 0 {
                    return Err(AsmError::MemoryOutOfBounds {
                        address: val as usize,
                        memory_size: self.memory.len(),
                    });
                }
                val as usize
            }
        };

        if addr >= self.memory.len() {
            Err(AsmError::MemoryOutOfBounds {
                address: addr,
                memory_size: self.memory.len(),
            })
        } else {
            Ok(addr)
        }
    }

    fn eval_operand(&self, op: &Operand) -> Result<i64, AsmError> {
        match op {
            Operand::Immediate(val) => Ok(*val),
            Operand::Reg(reg) => Ok(self.get_reg(*reg)),
            Operand::Memory(mode) => {
                let addr = self.resolve_address(mode)?;
                Ok(self.memory[addr])
            }
        }
    }

    fn update_flags(&mut self, result: i64, overflow: bool) {
        self.flags.zero = result == 0;
        self.flags.sign = result < 0;
        self.flags.overflow = overflow;
    }

    fn condition_met(&self, cond: JumpCondition) -> bool {
        match cond {
            JumpCondition::Always => true,
            JumpCondition::Equal => self.flags.zero,
            JumpCondition::NotEqual => !self.flags.zero,
            JumpCondition::Greater => !self.flags.zero && (self.flags.sign == self.flags.overflow),
            JumpCondition::GreaterOrEqual => self.flags.sign == self.flags.overflow,
            JumpCondition::Less => self.flags.sign != self.flags.overflow,
            JumpCondition::LessOrEqual => self.flags.zero || (self.flags.sign != self.flags.overflow),
        }
    }

    /// Exécute une seule instruction.
    pub fn step(&mut self, program: &[Instruction]) -> Result<bool, AsmError> {
        if self.halted {
            return Ok(false);
        }

        if self.pc >= program.len() {
            return Err(AsmError::PcOutOfBounds { pc: self.pc });
        }

        let instruction = &program[self.pc];
        let mut next_pc = self.pc + 1;

        match instruction {
            Instruction::Mov(dest, src) => {
                let val = self.eval_operand(src)?;
                self.set_reg(*dest, val);
            }
            Instruction::Load(dest, mode) => {
                let addr = self.resolve_address(mode)?;
                let val = self.memory[addr];
                self.set_reg(*dest, val);
            }
            Instruction::Store(mode, src) => {
                let addr = self.resolve_address(mode)?;
                let val = self.eval_operand(src)?;
                self.memory[addr] = val;
            }
            Instruction::Add(dest, src) => {
                let left = self.get_reg(*dest);
                let right = self.eval_operand(src)?;
                let (res, overflow) = left.overflowing_add(right);
                self.set_reg(*dest, res);
                self.update_flags(res, overflow);
            }
            Instruction::Sub(dest, src) => {
                let left = self.get_reg(*dest);
                let right = self.eval_operand(src)?;
                let (res, overflow) = left.overflowing_sub(right);
                self.set_reg(*dest, res);
                self.update_flags(res, overflow);
            }
            Instruction::Mul(dest, src) => {
                let left = self.get_reg(*dest);
                let right = self.eval_operand(src)?;
                let (res, overflow) = left.overflowing_mul(right);
                self.set_reg(*dest, res);
                self.update_flags(res, overflow);
            }
            Instruction::Div(dest, src) => {
                let left = self.get_reg(*dest);
                let right = self.eval_operand(src)?;
                if right == 0 {
                    return Err(AsmError::DivisionByZero { pc: self.pc });
                }
                let (res, overflow) = left.overflowing_div(right);
                self.set_reg(*dest, res);
                self.update_flags(res, overflow);
            }
            Instruction::Mod(dest, src) => {
                let left = self.get_reg(*dest);
                let right = self.eval_operand(src)?;
                if right == 0 {
                    return Err(AsmError::DivisionByZero { pc: self.pc });
                }
                let (res, overflow) = left.overflowing_rem(right);
                self.set_reg(*dest, res);
                self.update_flags(res, overflow);
            }
            Instruction::Cmp(left_op, right_op) => {
                let left = self.eval_operand(left_op)?;
                let right = self.eval_operand(right_op)?;
                let (res, overflow) = left.overflowing_sub(right);
                self.update_flags(res, overflow);
            }
            Instruction::Jmp(cond, target) => {
                if self.condition_met(*cond) {
                    let target_pc = match target {
                        JumpTarget::Address(addr) => *addr,
                        JumpTarget::Label(name) => return Err(AsmError::UndefinedLabel(name.clone())),
                    };
                    next_pc = target_pc;
                }
            }
            Instruction::Push(src) => {
                let val = self.eval_operand(src)?;
                let sp = self.get_reg(Register::SP);
                if sp <= 0 {
                    return Err(AsmError::StackOverflow { sp: sp.max(0) as usize });
                }
                let new_sp = (sp - 1) as usize;
                if new_sp >= self.memory.len() {
                    return Err(AsmError::MemoryOutOfBounds {
                        address: new_sp,
                        memory_size: self.memory.len(),
                    });
                }
                self.memory[new_sp] = val;
                self.set_reg(Register::SP, new_sp as i64);
            }
            Instruction::Pop(dest) => {
                let sp = self.get_reg(Register::SP) as usize;
                if sp >= self.memory.len() {
                    return Err(AsmError::StackUnderflow { sp });
                }
                let val = self.memory[sp];
                self.set_reg(*dest, val);
                self.set_reg(Register::SP, (sp + 1) as i64);
            }
            Instruction::Call(target) => {
                let target_pc = match target {
                    JumpTarget::Address(addr) => *addr,
                    JumpTarget::Label(name) => return Err(AsmError::UndefinedLabel(name.clone())),
                };
                let ret_addr = next_pc as i64;
                let sp = self.get_reg(Register::SP);
                if sp <= 0 {
                    return Err(AsmError::StackOverflow { sp: sp.max(0) as usize });
                }
                let new_sp = (sp - 1) as usize;
                if new_sp >= self.memory.len() {
                    return Err(AsmError::MemoryOutOfBounds {
                        address: new_sp,
                        memory_size: self.memory.len(),
                    });
                }
                self.memory[new_sp] = ret_addr;
                self.set_reg(Register::SP, new_sp as i64);
                next_pc = target_pc;
            }
            Instruction::Ret => {
                let sp = self.get_reg(Register::SP) as usize;
                if sp >= self.memory.len() {
                    return Err(AsmError::StackUnderflow { sp });
                }
                let return_addr = self.memory[sp];
                self.set_reg(Register::SP, (sp + 1) as i64);
                if return_addr < 0 {
                    return Err(AsmError::PcOutOfBounds { pc: return_addr as usize });
                }
                next_pc = return_addr as usize;
            }
            Instruction::Prn(op) => {
                let val = self.eval_operand(op)?;
                println!("[VM OUT] {val}");
                self.output_log.push(val);
            }
            Instruction::Hlt => {
                self.halted = true;
                return Ok(false);
            }
        }

        self.pc = next_pc;
        self.total_cycles += 1;
        Ok(!self.halted)
    }

    /// Exécute un programme jusqu'à son arrêt (HLT) ou l'atteinte d'un quota d'instructions.
    pub fn run(&mut self, program: &[Instruction], max_cycles: usize) -> Result<(), AsmError> {
        while !self.halted && self.pc < program.len() {
            if self.total_cycles >= max_cycles {
                return Err(AsmError::MaxCyclesExceeded(max_cycles));
            }
            self.step(program)?;
        }
        Ok(())
    }

    /// Affiche un dump complet des registres et de l'état des drapeaux.
    pub fn dump_state(&self) {
        println!("+------------------------------------------------------+");
        println!("|                    ÉTAT DE LA VM                     |");
        println!("+------------------------------------------------------+");
        println!(
            "| R0: {:10} | R1: {:10} | R2: {:10} |",
            self.registers[0], self.registers[1], self.registers[2]
        );
        println!(
            "| R3: {:10} | R4: {:10} | R5: {:10} |",
            self.registers[3], self.registers[4], self.registers[5]
        );
        println!(
            "| R6: {:10} | R7: {:10} | SP: {:10} |",
            self.registers[6], self.registers[7], self.registers[8]
        );
        println!(
            "| PC: {:10} | Cycles: {:6} | Halted: {:5}    |",
            self.pc, self.total_cycles, self.halted
        );
        println!(
            "| ZF: {:5}      | SF: {:5}      | OF: {:5}       |",
            self.flags.zero, self.flags.sign, self.flags.overflow
        );
        println!("+------------------------------------------------------+");
    }
}

/// Analyseur syntaxique (Parser) de code assembleur.
pub struct Assembler;

impl Assembler {
    fn clean_line(line: &str) -> &str {
        let code = match line.find(|c| c == ';' || c == '#') {
            Some(idx) => &line[..idx],
            None => line,
        };
        code.trim()
    }

    fn parse_address_mode(raw: &str, line_no: usize) -> Result<AddressMode, AsmError> {
        let trimmed = raw.trim();
        if !trimmed.starts_with('[') || !trimmed.ends_with(']') {
            return Err(AsmError::SyntaxError {
                line: line_no,
                message: format!("Format d'adresse mémoire attendu [addr], reçu : '{trimmed}'"),
            });
        }
        let inner = trimmed[1..trimmed.len() - 1].trim();
        if let Ok(reg) = Register::from_str(inner) {
            Ok(AddressMode::Register(reg))
        } else if let Ok(imm) = inner.parse::<usize>() {
            Ok(AddressMode::Immediate(imm))
        } else {
            Err(AsmError::SyntaxError {
                line: line_no,
                message: format!("Opérande mémoire invalide: '{inner}'"),
            })
        }
    }

    fn parse_operand(raw: &str, line_no: usize) -> Result<Operand, AsmError> {
        let trimmed = raw.trim();
        if trimmed.starts_with('[') && trimmed.ends_with(']') {
            let mode = Self::parse_address_mode(trimmed, line_no)?;
            Ok(Operand::Memory(mode))
        } else if let Ok(reg) = Register::from_str(trimmed) {
            Ok(Operand::Reg(reg))
        } else if let Ok(imm) = trimmed.parse::<i64>() {
            Ok(Operand::Immediate(imm))
        } else {
            Err(AsmError::SyntaxError {
                line: line_no,
                message: format!("Opérande invalide : '{trimmed}'"),
            })
        }
    }

    fn parse_jump_target(raw: &str) -> JumpTarget {
        let trimmed = raw.trim();
        if let Ok(addr) = trimmed.parse::<usize>() {
            JumpTarget::Address(addr)
        } else {
            JumpTarget::Label(trimmed.to_string())
        }
    }

    /// Assemble le code source en un vecteur d'instructions exécutables.
    pub fn assemble(source: &str) -> Result<Vec<Instruction>, AsmError> {
        let mut labels: HashMap<String, usize> = HashMap::new();
        let mut raw_instructions: Vec<(usize, String, Vec<String>)> = Vec::new();
        let mut current_instruction_index = 0;

        // Passe 1 : Récupération des étiquettes et découpage des instructions
        for (line_idx, raw_line) in source.lines().enumerate() {
            let line_no = line_idx + 1;
            let mut line = Self::clean_line(raw_line);
            if line.is_empty() {
                continue;
            }

            // Détection des étiquettes (ex: "loop:", "start: mov r0, 1")
            if let Some(colon_pos) = line.find(':') {
                let label = line[..colon_pos].trim();
                if label.is_empty() || label.contains(' ') {
                    return Err(AsmError::SyntaxError {
                        line: line_no,
                        message: format!("Nom d'étiquette invalide : '{label}'"),
                    });
                }
                if labels.contains_key(label) {
                    return Err(AsmError::DuplicateLabel(label.to_string(), line_no));
                }
                labels.insert(label.to_string(), current_instruction_index);
                line = line[colon_pos + 1..].trim();
                if line.is_empty() {
                    continue;
                }
            }

            // Mnémonique et opérandes
            let mut parts = line.splitn(2, |c: char| c.is_whitespace());
            let mnemonic = match parts.next() {
                Some(m) if !m.is_empty() => m.trim().to_uppercase(),
                _ => continue,
            };

            let operands_str = parts.next().unwrap_or("").trim();
            let operands: Vec<String> = if operands_str.is_empty() {
                Vec::new()
            } else {
                operands_str.split(',').map(|s| s.trim().to_string()).collect()
            };

            raw_instructions.push((line_no, mnemonic, operands));
            current_instruction_index += 1;
        }

        // Passe 2 : Traduction et résolution des cibles de saut
        let mut program: Vec<Instruction> = Vec::with_capacity(raw_instructions.len());

        for (line_no, mnemonic, operands) in raw_instructions {
            let resolve_target = |target: &JumpTarget| -> Result<JumpTarget, AsmError> {
                match target {
                    JumpTarget::Label(lbl) => match labels.get(lbl) {
                        Some(&addr) => Ok(JumpTarget::Address(addr)),
                        None => Err(AsmError::UndefinedLabel(lbl.clone())),
                    },
                    JumpTarget::Address(addr) => Ok(JumpTarget::Address(*addr)),
                }
            };

            let instr = match mnemonic.as_str() {
                "MOV" => {
                    if operands.len() != 2 {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: "MOV attend 2 opérandes: MOV dest_reg, src".into(),
                        });
                    }
                    let dest = Register::from_str(&operands[0])?;
                    let src = Self::parse_operand(&operands[1], line_no)?;
                    Instruction::Mov(dest, src)
                }
                "LOAD" => {
                    if operands.len() != 2 {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: "LOAD attend 2 opérandes: LOAD dest_reg, [addr]".into(),
                        });
                    }
                    let dest = Register::from_str(&operands[0])?;
                    let mode = Self::parse_address_mode(&operands[1], line_no)?;
                    Instruction::Load(dest, mode)
                }
                "STORE" => {
                    if operands.len() != 2 {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: "STORE attend 2 opérandes: STORE [addr], src".into(),
                        });
                    }
                    let mode = Self::parse_address_mode(&operands[0], line_no)?;
                    let src = Self::parse_operand(&operands[1], line_no)?;
                    Instruction::Store(mode, src)
                }
                "ADD" => {
                    if operands.len() != 2 {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: "ADD attend 2 opérandes: ADD dest_reg, src".into(),
                        });
                    }
                    let dest = Register::from_str(&operands[0])?;
                    let src = Self::parse_operand(&operands[1], line_no)?;
                    Instruction::Add(dest, src)
                }
                "SUB" => {
                    if operands.len() != 2 {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: "SUB attend 2 opérandes: SUB dest_reg, src".into(),
                        });
                    }
                    let dest = Register::from_str(&operands[0])?;
                    let src = Self::parse_operand(&operands[1], line_no)?;
                    Instruction::Sub(dest, src)
                }
                "MUL" => {
                    if operands.len() != 2 {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: "MUL attend 2 opérandes: MUL dest_reg, src".into(),
                        });
                    }
                    let dest = Register::from_str(&operands[0])?;
                    let src = Self::parse_operand(&operands[1], line_no)?;
                    Instruction::Mul(dest, src)
                }
                "DIV" => {
                    if operands.len() != 2 {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: "DIV attend 2 opérandes: DIV dest_reg, src".into(),
                        });
                    }
                    let dest = Register::from_str(&operands[0])?;
                    let src = Self::parse_operand(&operands[1], line_no)?;
                    Instruction::Div(dest, src)
                }
                "MOD" => {
                    if operands.len() != 2 {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: "MOD attend 2 opérandes: MOD dest_reg, src".into(),
                        });
                    }
                    let dest = Register::from_str(&operands[0])?;
                    let src = Self::parse_operand(&operands[1], line_no)?;
                    Instruction::Mod(dest, src)
                }
                "CMP" => {
                    if operands.len() != 2 {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: "CMP attend 2 opérandes: CMP op1, op2".into(),
                        });
                    }
                    let left = Self::parse_operand(&operands[0], line_no)?;
                    let right = Self::parse_operand(&operands[1], line_no)?;
                    Instruction::Cmp(left, right)
                }
                "JMP" => {
                    if operands.len() != 1 {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: "JMP attend 1 opérande cible".into(),
                        });
                    }
                    let target = resolve_target(&Self::parse_jump_target(&operands[0]))?;
                    Instruction::Jmp(JumpCondition::Always, target)
                }
                "JE" | "JZ" => {
                    if operands.len() != 1 {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: format!("{mnemonic} attend 1 opérande cible"),
                        });
                    }
                    let target = resolve_target(&Self::parse_jump_target(&operands[0]))?;
                    Instruction::Jmp(JumpCondition::Equal, target)
                }
                "JNE" | "JNZ" => {
                    if operands.len() != 1 {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: format!("{mnemonic} attend 1 opérande cible"),
                        });
                    }
                    let target = resolve_target(&Self::parse_jump_target(&operands[0]))?;
                    Instruction::Jmp(JumpCondition::NotEqual, target)
                }
                "JG" => {
                    if operands.len() != 1 {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: "JG attend 1 opérande cible".into(),
                        });
                    }
                    let target = resolve_target(&Self::parse_jump_target(&operands[0]))?;
                    Instruction::Jmp(JumpCondition::Greater, target)
                }
                "JGE" => {
                    if operands.len() != 1 {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: "JGE attend 1 opérande cible".into(),
                        });
                    }
                    let target = resolve_target(&Self::parse_jump_target(&operands[0]))?;
                    Instruction::Jmp(JumpCondition::GreaterOrEqual, target)
                }
                "JL" => {
                    if operands.len() != 1 {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: "JL attend 1 opérande cible".into(),
                        });
                    }
                    let target = resolve_target(&Self::parse_jump_target(&operands[0]))?;
                    Instruction::Jmp(JumpCondition::Less, target)
                }
                "JLE" => {
                    if operands.len() != 1 {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: "JLE attend 1 opérande cible".into(),
                        });
                    }
                    let target = resolve_target(&Self::parse_jump_target(&operands[0]))?;
                    Instruction::Jmp(JumpCondition::LessOrEqual, target)
                }
                "PUSH" => {
                    if operands.len() != 1 {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: "PUSH attend 1 opérande source".into(),
                        });
                    }
                    let src = Self::parse_operand(&operands[0], line_no)?;
                    Instruction::Push(src)
                }
                "POP" => {
                    if operands.len() != 1 {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: "POP attend 1 registre de destination".into(),
                        });
                    }
                    let dest = Register::from_str(&operands[0])?;
                    Instruction::Pop(dest)
                }
                "CALL" => {
                    if operands.len() != 1 {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: "CALL attend 1 opérande cible".into(),
                        });
                    }
                    let target = resolve_target(&Self::parse_jump_target(&operands[0]))?;
                    Instruction::Call(target)
                }
                "RET" => {
                    if !operands.is_empty() {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: "RET n'attend aucun opérande".into(),
                        });
                    }
                    Instruction::Ret
                }
                "PRN" => {
                    if operands.len() != 1 {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: "PRN attend 1 opérande".into(),
                        });
                    }
                    let op = Self::parse_operand(&operands[0], line_no)?;
                    Instruction::Prn(op)
                }
                "HLT" => {
                    if !operands.is_empty() {
                        return Err(AsmError::SyntaxError {
                            line: line_no,
                            message: "HLT n'attend aucun opérande".into(),
                        });
                    }
                    Instruction::Hlt
                }
                unknown => {
                    return Err(AsmError::SyntaxError {
                        line: line_no,
                        message: format!("Instruction inconnue : '{unknown}'"),
                    });
                }
            };

            program.push(instr);
        }

        Ok(program)
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("=== Interpréteur Assembleur Virtuel ===");

    // Programme de démonstration :
    // 1. Calcul itératif de factorielle de 5 (5! = 120) stocké dans R0
    // 2. Sauvegarde en mémoire à l'adresse 10
    // 3. Appel de sous-routine pour doubler la valeur (120 * 2 = 240)
    // 4. Affichage et arrêt
    let demo_code = r#"
        ; Initialisation du calcul de factorielle de 5
        MOV R0, 1        ; Résultat
        MOV R1, 5        ; Compteur n

    fact_loop:
        CMP R1, 1
        JLE fact_done
        MUL R0, R1
        SUB R1, 1
        JMP fact_loop

    fact_done:
        PRN R0           ; Affiche 120
        STORE [10], R0   ; Sauvegarde en mémoire à l'adresse 10

        ; Appel de la fonction de doublement
        CALL double_routine
        PRN R0           ; Affiche 240
        HLT

    double_routine:
        LOAD R2, [10]
        ADD R0, R2
        RET
    "#;

    println!("Assemblage du programme de démonstration...");
    let program = match Assembler::assemble(demo_code) {
        Ok(prog) => prog,
        Err(e) => {
            eprintln!("Erreur lors de l'assemblage : {e}");
            return Err(e.into());
        }
    };

    println!("Exécution sur la machine virtuelle...");
    let mut vm = Vm::new(Vm::DEFAULT_MEMORY_SIZE);
    if let Err(e) = vm.run(&program, 10_000) {
        eprintln!("Erreur lors de l'exécution : {e}");
        return Err(e.into());
    }

    println!("\nExécution terminée avec succès !");
    vm.dump_state();

    assert_eq!(vm.get_reg(Register::R0), 240);
    assert_eq!(vm.memory[10], 120);
    assert_eq!(vm.output_log, vec![120, 240]);
    println!("Vérification des assertions : OK (R0 = 240, RAM[10] = 120).");

    Ok(())
}

