        let mut vm = Vm::new(256);
        let result = vm.run(&program, 1000);
        assert!(matches!(result, Err(AsmError::DivisionByZero { .. })));
    }

    #[test]
    fn test_undefined_label_error() {
        let code = r#"
            JMP non_existent_label
        "#;
        let result = Assembler::assemble(code);
        assert!(matches!(result, Err(AsmError::UndefinedLabel(_))));
    }

    #[test]
    fn test_memory_out_of_bounds_error() {
        let code = r#"
            LOAD R0, [500]
        "#;
        let program = Assembler::assemble(code).expect("Échec d'assemblage");
        let mut vm = Vm::new(128); // Mémoire de taille 128
        let result = vm.run(&program, 1000);
        assert!(matches!(result, Err(AsmError::MemoryOutOfBounds { .. })));
    }
