// src/main.rs
//! Moteur de détection d'anomalies statistiques sur flux temps réel.
//! Implémentation du calcul d'écart-type glissant en O(1) basé sur l'algorithme de Welford étendu.

use chrono::{DateTime, Utc};
use rand_distr::{Distribution, Normal};
use serde::{Deserialize, Serialize};
use std::collections::{HashMap, VecDeque};
use std::time::Duration;
use thiserror::Error;
use tokio::sync::mpsc;
use tracing::{error, info, warn};

/// Erreurs potentielles rencontrées par le moteur de détection.
#[derive(Debug, Error)]
pub enum AnomalyDetectionError {
    #[error("La taille de fenêtre spécifiée doit être au moins de 2 (reçu: {0})")]
    InvalidWindowSize(usize),

    #[error("Le seuil z-score doit être strictement positif (reçu: {0})")]
    InvalidThreshold(f64),

    #[error("Échec d'envoi dans le canal de données: {0}")]
    ChannelSendError(String),
}

/// Échantillon élémentaire transitant sur le flux de données.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DataPoint {
    pub metric_id: String,
    pub timestamp: DateTime<Utc>,
    pub value: f64,
}

/// Alerte levée lorsqu'une valeur dévie au-delà du seuil statistique.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AnomalyAlert {
    pub metric_id: String,
    pub timestamp: DateTime<Utc>,
    pub value: f64,
    pub mean: f64,
    pub std_dev: f64,
    pub z_score: f64,
    pub threshold: f64,
}

/// Structure maintenant les statistiques d'une fenêtre glissante en O(1).
///
/// Utilise une variante de l'algorithme de Welford adaptée au retrait du plus
/// ancien élément d'une FIFO.
#[derive(Debug, Clone)]
pub struct SlidingWindowStats {
    window_capacity: usize,
    buffer: VecDeque<f64>,
    mean: f64,
    m2: f64, // Somme des carrés des écarts à la moyenne : sum((x - mean)^2)
}

impl SlidingWindowStats {
    /// Initialise une nouvelle fenêtre glissante avec la capacité spécifiée.
    pub fn new(capacity: usize) -> Result<Self, AnomalyDetectionError> {
        if capacity < 2 {
            return Err(AnomalyDetectionError::InvalidWindowSize(capacity));
        }
        Ok(Self {
            window_capacity: capacity,
            buffer: VecDeque::with_capacity(capacity),
            mean: 0.0,
            m2: 0.0,
        })
    }

    /// Nombre actuel d'éléments dans la fenêtre.
    #[inline]
    pub fn count(&self) -> usize {
        self.buffer.len()
    }

    /// Moyenne courante.
    #[inline]
    pub fn mean(&self) -> f64 {
        self.mean
    }

    /// Variance d'échantillon (degrés de liberté: N - 1).
    pub fn variance(&self) -> f64 {
        let n = self.buffer.len();
        if n < 2 {
            return 0.0;
        }
        // m2 peut être très légèrement négatif à cause des imprécisions numériques IEEE 754
        (self.m2 / (n - 1) as f64).max(0.0)
    }

    /// Écart-type d'échantillon.
    #[inline]
    pub fn std_dev(&self) -> f64 {
        self.variance().sqrt()
    }

    /// Ajoute une valeur et met à jour les moments statistiques en O(1).
    pub fn push(&mut self, new_val: f64) {
        if self.buffer.len() < self.window_capacity {
            // Phase d'expansion de la fenêtre : Welford standard
            self.buffer.push_back(new_val);
            let n = self.buffer.len() as f64;
            let delta = new_val - self.mean;
            self.mean += delta / n;
            let delta2 = new_val - self.mean;
            self.m2 += delta * delta2;
        } else if let Some(old_val) = self.buffer.pop_front() {
            // Fenêtre à pleine capacité : remplacement d'un élément par le nouvel entrant
            self.buffer.push_back(new_val);
            let n = self.window_capacity as f64;

            let old_mean = self.mean;
            // Mise à jour de la moyenne : mean_new = mean_old + (new_val - old_val) / N
            let mean_diff = (new_val - old_val) / n;
            let new_mean = old_mean + mean_diff;
            self.mean = new_mean;

            // Mise à jour de M2 : M2_new = M2_old + (new_val - old_val) * (new_val - new_mean + old_val - old_mean)
            self.m2 += (new_val - old_val) * (new_val - new_mean + old_val - old_mean);

            // Pour éviter l'accumulation d'erreurs d'arrondi sur de très longues séries :
            if self.m2 < 0.0 {
                self.m2 = 0.0;
            }
        }
    }
}

/// Configuration du moteur de détection.
#[derive(Debug, Clone)]
pub struct DetectorConfig {
    pub window_size: usize,
    pub min_warmup_samples: usize,
    pub z_score_threshold: f64,
}

impl Default for DetectorConfig {
    fn default() -> Self {
        Self {
            window_size: 50,
            min_warmup_samples: 10,
            z_score_threshold: 3.0,
        }
    }
}

/// Moteur de détection multi-séries.
pub struct AnomalyDetector {
    config: DetectorConfig,
    trackers: HashMap<String, SlidingWindowStats>,
}

impl AnomalyDetector {
    /// Construit un détecteur avec une configuration validée.
    pub fn new(config: DetectorConfig) -> Result<Self, AnomalyDetectionError> {
        if config.window_size < 2 {
            return Err(AnomalyDetectionError::InvalidWindowSize(config.window_size));
        }
        if config.z_score_threshold <= 0.0 {
            return Err(AnomalyDetectionError::InvalidThreshold(
                config.z_score_threshold,
            ));
        }
        Ok(Self {
            config,
            trackers: HashMap::new(),
        })
    }

    /// Traite un point de données et retourne une alerte si une anomalie est détectée.
    pub fn process(&mut self, point: &DataPoint) -> Result<Option<AnomalyAlert>, AnomalyDetectionError> {
        let window_size = self.config.window_size;
        let stats = match self.trackers.get_mut(&point.metric_id) {
            Some(existing) => existing,
            None => {
                let new_tracker = SlidingWindowStats::new(window_size)?;
                self.trackers.insert(point.metric_id.clone(), new_tracker);
                // L'insertion vient de réussir, unwrap_or n'est pas nécessaire mais on évite unwrap()
                match self.trackers.get_mut(&point.metric_id) {
                    Some(tracker) => tracker,
                    None => unreachable!("La clé vient d'être insérée"),
                }
            }
        };

        let mut alert = None;

        // Évaluation de l'anomalie par rapport à l'état statistique avant ou incluant le warmup
        if stats.count() >= self.config.min_warmup_samples {
            let std_dev = stats.std_dev();
            let mean = stats.mean();

            // Vérification de variance non nulle pour éviter la division par zéro
            if std_dev > 1e-9 {
                let z_score = (point.value - mean) / std_dev;
                if z_score.abs() >= self.config.z_score_threshold {
                    alert = Some(AnomalyAlert {
                        metric_id: point.metric_id.clone(),
                        timestamp: point.timestamp,
                        value: point.value,
                        mean,
                        std_dev,
                        z_score,
                        threshold: self.config.z_score_threshold,
                    });
                }
            }
        }

        // Intégration de la nouvelle observation dans la fenêtre glissante
        stats.push(point.value);

        Ok(alert)
    }
}

/// Simulateur asynchrone émettant des points de données avec anomalies aléatoires.
async fn simulate_sensor_stream(
    sender: mpsc::Sender<DataPoint>,
    metric_id: String,
    sample_count: usize,
) -> Result<(), AnomalyDetectionError> {
    let normal_dist = match Normal::new(100.0, 5.0) {
        Ok(dist) => dist,
        Err(e) => {
            return Err(AnomalyDetectionError::ChannelSendError(format!(
                "Erreur d'initialisation de distribution: {e}"
            )))
        }
    };

    for i in 1..=sample_count {
        let is_anomaly = i == 25 || i == 60 || i == 85;
        // Obtenir la valeur aléatoire dans un bloc délimité pour libérer ThreadRng avant l'await
        let value = {
            let mut rng = rand::thread_rng();
            let base_value = normal_dist.sample(&mut rng);
            if is_anomaly {
                // Injection artificielle d'anomalie (spike positif ou négatif franc)
                if i % 2 == 0 {
                    base_value + 35.0
                } else {
                    base_value - 30.0
                }
            } else {
                base_value
            }
        };

        let point = DataPoint {
            metric_id: metric_id.clone(),
            timestamp: Utc::now(),
            value,
        };

        if let Err(e) = sender.send(point).await {
            return Err(AnomalyDetectionError::ChannelSendError(e.to_string()));
        }

        tokio::time::sleep(Duration::from_millis(20)).await;
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialisation du système de logs structurés
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    info!("Démarrage du moteur de détection d'anomalies en temps réel");

    let config = DetectorConfig {
        window_size: 30,
        min_warmup_samples: 15,
        z_score_threshold: 3.0,
    };

    let mut detector = AnomalyDetector::new(config)?;
    let (tx, mut rx) = mpsc::channel::<DataPoint>(100);

    // Démarrage de générateurs asynchrones pour deux flux distincts
    let tx_cpu = tx.clone();
    let producer_cpu = tokio::spawn(async move {
        if let Err(err) = simulate_sensor_stream(tx_cpu, "cpu_usage_pct".to_string(), 100).await {
            error!("Erreur producteur cpu_usage_pct: {err}");
        }
    });

    let tx_temp = tx.clone();
    let producer_temp = tokio::spawn(async move {
        if let Err(err) = simulate_sensor_stream(tx_temp, "temperature_celsius".to_string(), 100).await {
            error!("Erreur producteur temperature_celsius: {err}");
        }
    });

    // Fermeture du canal maître original pour permettre la fin de lecture lorsque tous les producteurs ont terminé
    drop(tx);

    let mut anomaly_count = 0usize;
    let mut total_points = 0usize;

    // Boucle d'ingestion et de détection en continu
    while let Some(point) = rx.recv().await {
        total_points += 1;
        match detector.process(&point) {
            Ok(Some(alert)) => {
                anomaly_count += 1;
                warn!(
                    target: "anomaly_engine",
                    metric = %alert.metric_id,
                    timestamp = %alert.timestamp.to_rfc3339(),
                    value = format_args!("{:.2}", alert.value),
                    mean = format_args!("{:.2}", alert.mean),
                    std_dev = format_args!("{:.2}", alert.std_dev),
                    z_score = format_args!("{:.2}", alert.z_score),
                    threshold = alert.threshold,
                    "⚠️ Anomalie détectée !"
                );
            }
            Ok(None) => {
                // Événement nominal, traçage au niveau debug/trace si nécessaire
            }
            Err(e) => {
                error!("Erreur lors de l'évaluation du point: {e}");
            }
        }
    }

    // Attente des tâches de production
    let _ = tokio::join!(producer_cpu, producer_temp);

    info!(
        total_points_processed = total_points,
        total_anomalies_detected = anomaly_count,
        "Traitement du flux terminé avec succès."
    );

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_sliding_window_welford_accuracy() {
        let mut window = SlidingWindowStats::new(5).expect("Création valide");
        let values = [10.0, 12.0, 23.0, 23.0, 16.0, 23.0, 21.0, 16.0];

        for &v in &values {
            window.push(v);
        }

        // Les 5 dernières valeurs sont : [23.0, 16.0, 23.0, 21.0, 16.0]
        let slice = [23.0, 16.0, 23.0, 21.0, 16.0];
        let expected_mean: f64 = slice.iter().sum::<f64>() / 5.0;
        let expected_var: f64 = slice.iter().map(|x| (x - expected_mean).powi(2)).sum::<f64>() / 4.0;
        let expected_std = expected_var.sqrt();

        assert!((window.mean() - expected_mean).abs() < 1e-6);
        assert!((window.variance() - expected_var).abs() < 1e-6);
        assert!((window.std_dev() - expected_std).abs() < 1e-6);
    }

    #[test]
    fn test_anomaly_detection_trigger() {
        let config = DetectorConfig {
            window_size: 10,
            min_warmup_samples: 5,
            z_score_threshold: 2.5,
        };
        let mut detector = AnomalyDetector::new(config).expect("Config valide");

        // Remplissage avec des données stables autour de 50.0
        for _ in 0..8 {
            let res = detector
                .process(&DataPoint {
                    metric_id: "test_sensor".to_string(),
                    timestamp: Utc::now(),
                    value: 50.0,
                })
                .expect("Traitement sans erreur");
            assert!(res.is_none());
        }

        // Injection d'une valeur extrême
        let alert_zero_var = detector
            .process(&DataPoint {
                metric_id: "test_sensor".to_string(),
                timestamp: Utc::now(),
                value: 200.0,
            })
            .expect("Traitement sans erreur");
        // Avec une variance quasi-nulle, aucune division par zéro n'a lieu et aucune fausse alerte non calculable n'est émise
        assert!(alert_zero_var.is_none());

        // Comme la variance est nulle avec 50.0 partout, nous testons avec de la variabilité
        let config_noisy = DetectorConfig {
            window_size: 10,
            min_warmup_samples: 5,
            z_score_threshold: 2.0,
        };
        let mut detector_noisy = AnomalyDetector::new(config_noisy).expect("Config valide");
        let initial_vals = [50.0, 52.0, 48.0, 51.0, 49.0, 50.0];
        for v in initial_vals {
            let res = detector_noisy
                .process(&DataPoint {
                    metric_id: "sensor_noisy".to_string(),
                    timestamp: Utc::now(),
                    value: v,
                })
                .expect("Traitement nominal");
            assert!(res.is_none());
        }

        let spike = detector_noisy
            .process(&DataPoint {
                metric_id: "sensor_noisy".to_string(),
                timestamp: Utc::now(),
                value: 80.0,
            })
            .expect("Traitement nominal");

        assert!(spike.is_some());
        let a = spike.unwrap();
        assert_eq!(a.metric_id, "sensor_noisy");
        assert!(a.z_score > 2.0);
    }

    #[test]
    fn test_invalid_parameters() {
        assert!(SlidingWindowStats::new(0).is_err());
        assert!(SlidingWindowStats::new(1).is_err());
        assert!(AnomalyDetector::new(DetectorConfig {
            window_size: 1,
            ..Default::default()
        })
        .is_err());
        assert!(AnomalyDetector::new(DetectorConfig {
            z_score_threshold: -1.0,
            ..Default::default()
        })
        .is_err());
    }
}

