    metric_id: String,
    sample_count: usize,
) -> Result<(), AnomalyDetectionError> {
    let normal_dist = match Normal::new(100.0, 5.0) {
        Ok(dist) => dist,
        Err(e) => {
            return Err(AnomalyDetectionError::ChannelSendError(format!(
                "Erreur d'initialisation de distribution: {e}"
            )))
        }
    };

    for i in 1..=sample_count {
        let is_anomaly = i == 25 || i == 60 || i == 85;
        // Obtenir la valeur aléatoire dans un bloc délimité pour libérer ThreadRng avant l'await
        let value = {
            let mut rng = rand::thread_rng();
            let base_value = normal_dist.sample(&mut rng);
            if is_anomaly {
                // Injection artificielle d'anomalie (spike positif ou négatif franc)
                if i % 2 == 0 {
                    base_value + 35.0
                } else {
                    base_value - 30.0
                }
            } else {
                base_value
            }
        };

        let point = DataPoint {
            metric_id: metric_id.clone(),
            timestamp: Utc::now(),
            value,
        };

        if let Err(e) = sender.send(point).await {
            return Err(AnomalyDetectionError::ChannelSendError(e.to_string()));
        }

        tokio::time::sleep(Duration::from_millis(20)).await;
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialisation du système de logs structurés
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    info!("Démarrage du moteur de détection d'anomalies en temps réel");

    let config = DetectorConfig {
        window_size: 30,
        min_warmup_samples: 15,
        z_score_threshold: 3.0,
    };

    let mut detector = AnomalyDetector::new(config)?;
    let (tx, mut rx) = mpsc::channel::<DataPoint>(100);

    // Démarrage de générateurs asynchrones pour deux flux distincts
    let tx_cpu = tx.clone();
    let producer_cpu = tokio::spawn(async move {
        if let Err(err) = simulate_sensor_stream(tx_cpu, "cpu_usage_pct".to_string(), 100).await {
            error!("Erreur producteur cpu_usage_pct: {err}");
        }
    });

    let tx_temp = tx.clone();
    let producer_temp = tokio::spawn(async move {
        if let Err(err) = simulate_sensor_stream(tx_temp, "temperature_celsius".to_string(), 100).await {
            error!("Erreur producteur temperature_celsius: {err}");
        }
    });

    // Fermeture du canal maître original pour permettre la fin de lecture lorsque tous les producteurs ont terminé
    drop(tx);

    let mut anomaly_count = 0usize;
    let mut total_points = 0usize;

    // Boucle d'ingestion et de détection en continu
    while let Some(point) = rx.recv().await {
        total_points += 1;
        match detector.process(&point) {
            Ok(Some(alert)) => {
                anomaly_count += 1;
                warn!(
                    target: "anomaly_engine",
                    metric = %alert.metric_id,
                    timestamp = %alert.timestamp.to_rfc3339(),
                    value = format_args!("{:.2}", alert.value),
                    mean = format_args!("{:.2}", alert.mean),
                    std_dev = format_args!("{:.2}", alert.std_dev),
                    z_score = format_args!("{:.2}", alert.z_score),
                    threshold = alert.threshold,
                    "⚠️ Anomalie détectée !"
                );
            }
            Ok(None) => {
                // Événement nominal, traçage au niveau debug/trace si nécessaire
            }
            Err(e) => {
                error!("Erreur lors de l'évaluation du point: {e}");
            }
        }
    }

    // Attente des tâches de production
    let _ = tokio::join!(producer_cpu, producer_temp);

    info!(
        total_points_processed = total_points,
        total_anomalies_detected = anomaly_count,
        "Traitement du flux terminé avec succès."
    );

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_sliding_window_welford_accuracy() {
        let mut window = SlidingWindowStats::new(5).expect("Création valide");
        let values = [10.0, 12.0, 23.0, 23.0, 16.0, 23.0, 21.0, 16.0];

        for &v in &values {
            window.push(v);
        }

        // Les 5 dernières valeurs sont : [23.0, 16.0, 23.0, 21.0, 16.0]
        let slice = [23.0, 16.0, 23.0, 21.0, 16.0];
        let expected_mean: f64 = slice.iter().sum::<f64>() / 5.0;
        let expected_var: f64 = slice.iter().map(|x| (x - expected_mean).powi(2)).sum::<f64>() / 4.0;
        let expected_std = expected_var.sqrt();

        assert!((window.mean() - expected_mean).abs() < 1e-6);
        assert!((window.variance() - expected_var).abs() < 1e-6);
        assert!((window.std_dev() - expected_std).abs() < 1e-6);
    }

    #[test]
    fn test_anomaly_detection_trigger() {
        let config = DetectorConfig {
            window_size: 10,
            min_warmup_samples: 5,
            z_score_threshold: 2.5,
        };
        let mut detector = AnomalyDetector::new(config).expect("Config valide");

        // Remplissage avec des données stables autour de 50.0
        for _ in 0..8 {
            let res = detector
                .process(&DataPoint {
                    metric_id: "test_sensor".to_string(),
                    timestamp: Utc::now(),
                    value: 50.0,
                })
                .expect("Traitement sans erreur");
            assert!(res.is_none());
        }

        // Injection d'une valeur extrême
        let alert_zero_var = detector
            .process(&DataPoint {
                metric_id: "test_sensor".to_string(),
                timestamp: Utc::now(),
                value: 200.0,
            })
            .expect("Traitement sans erreur");
        // Avec une variance quasi-nulle, aucune division par zéro n'a lieu et aucune fausse alerte non calculable n'est émise
        assert!(alert_zero_var.is_none());

        // Comme la variance est nulle avec 50.0 partout, nous testons avec de la variabilité
        let config_noisy = DetectorConfig {
            window_size: 10,
            min_warmup_samples: 5,
            z_score_threshold: 2.0,
        };
        let mut detector_noisy = AnomalyDetector::new(config_noisy).expect("Config valide");
        let initial_vals = [50.0, 52.0, 48.0, 51.0, 49.0, 50.0];
        for v in initial_vals {
            let res = detector_noisy
                .process(&DataPoint {
                    metric_id: "sensor_noisy".to_string(),
                    timestamp: Utc::now(),
                    value: v,
                })
                .expect("Traitement nominal");
            assert!(res.is_none());
        }

        let spike = detector_noisy
            .process(&DataPoint {
                metric_id: "sensor_noisy".to_string(),
                timestamp: Utc::now(),
                value: 80.0,
            })
            .expect("Traitement nominal");

        assert!(spike.is_some());
        let a = spike.unwrap();
        assert_eq!(a.metric_id, "sensor_noisy");
        assert!(a.z_score > 2.0);
    }

    #[test]
    fn test_invalid_parameters() {
        assert!(SlidingWindowStats::new(0).is_err());
        assert!(SlidingWindowStats::new(1).is_err());
        assert!(AnomalyDetector::new(DetectorConfig {
            window_size: 1,
            ..Default::default()
        })
        .is_err());
        assert!(AnomalyDetector::new(DetectorConfig {
            z_score_threshold: -1.0,
            ..Default::default()
        })
        .is_err());
    }
}

