// src/main.rs
use std::cmp::Ordering;
use std::collections::{BinaryHeap, VecDeque};

use clap::Parser;
use rand::rngs::StdRng;
use rand::SeedableRng;
use rand_distr::{Distribution, Exp};

/// Simulateur de file d'attente M/M/1 à événements discrets.
#[derive(Parser, Debug)]
#[command(author, version, about, long_about = None)]
pub struct CliArgs {
    /// Taux moyen d'arrivée (lambda > 0)
    #[arg(short = 'l', long = "lambda", default_value_t = 3.0)]
    pub lambda: f64,

    /// Taux moyen de service (mu > lambda)
    #[arg(short = 'm', long = "mu", default_value_t = 5.0)]
    pub mu: f64,

    /// Nombre total de clients servis à simuler
    #[arg(short = 'n', long = "num-customers", default_value_t = 200_000)]
    pub num_customers: usize,

    /// Nombre de clients écartés pour la période de chauffe (warm-up)
    #[arg(short = 'w', long = "warmup", default_value_t = 20_000)]
    pub warmup: usize,

    /// Graine pour le générateur pseudo-aléatoire (optionnel)
    #[arg(short = 's', long = "seed")]
    pub seed: Option<u64>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EventKind {
    Arrival,
    Departure,
}

#[derive(Debug, Clone)]
pub struct Event {
    pub time: f64,
    pub kind: EventKind,
    pub customer_id: usize,
}

impl PartialEq for Event {
    fn eq(&self, other: &Self) -> bool {
        self.time == other.time
    }
}

impl Eq for Event {}

impl PartialOrd for Event {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for Event {
    fn cmp(&self, other: &Self) -> Ordering {
        // Inversion pour obtenir un Min-Heap dans BinaryHeap
        other
            .time
            .partial_cmp(&self.time)
            .unwrap_or(Ordering::Equal)
    }
}

#[derive(Debug, Clone, Copy)]
pub struct Customer {
    pub id: usize,
    pub arrival_time: f64,
}

#[derive(Debug)]
pub struct TheoreticalMetrics {
    pub rho: f64,
    pub avg_waiting_time_queue: f64,
    pub avg_system_time: f64,
    pub avg_customers_queue: f64,
    pub avg_customers_system: f64,
}

impl TheoreticalMetrics {
    pub fn compute(lambda: f64, mu: f64) -> Result<Self, &'static str> {
        if lambda <= 0.0 {
            return Err("Le taux d'arrivée lambda doit être strictement positif.");
        }
        if mu <= 0.0 {
            return Err("Le taux de service mu doit être strictement positif.");
        }
        if lambda >= mu {
            return Err("Condition de stabilité violée : lambda doit être strictement inférieur à mu (rho < 1).");
        }

        let rho = lambda / mu;
        let avg_system_time = 1.0 / (mu - lambda);
        let avg_waiting_time_queue = rho / (mu - lambda);
        let avg_customers_system = rho / (1.0 - rho);
        let avg_customers_queue = (rho * rho) / (1.0 - rho);

        Ok(Self {
            rho,
            avg_waiting_time_queue,
            avg_system_time,
            avg_customers_queue,
            avg_customers_system,
        })
    }
}

#[derive(Debug, Default)]
pub struct SimulationMetrics {
    pub total_simulated_time: f64,
    pub sampled_customers: usize,
    pub server_busy_time: f64,
    pub avg_waiting_time_queue: f64,
    pub avg_system_time: f64,
    pub avg_customers_queue: f64,
    pub avg_customers_system: f64,
    pub server_utilization: f64,
}

pub struct Mm1Simulator {
    lambda: f64,
    mu: f64,
    total_customers: usize,
    warmup: usize,
    rng: StdRng,
}

impl Mm1Simulator {
    pub fn new(lambda: f64, mu: f64, total_customers: usize, warmup: usize, seed: Option<u64>) -> Self {
        let rng = match seed {
            Some(s) => StdRng::seed_from_u64(s),
            None => StdRng::from_entropy(),
        };

        Self {
            lambda,
            mu,
            total_customers,
            warmup,
            rng,
        }
    }

    pub fn run(&mut self) -> Result<SimulationMetrics, String> {
        let exp_arrival = Exp::new(self.lambda).map_err(|e| format!("Erreur loi arrivée: {e}"))?;
        let exp_service = Exp::new(self.mu).map_err(|e| format!("Erreur loi service: {e}"))?;

        let mut event_queue: BinaryHeap<Event> = BinaryHeap::new();
        let mut waiting_queue: VecDeque<Customer> = VecDeque::new();
        let mut current_server_customer: Option<Customer> = None;

        let mut current_time = 0.0;
        let mut next_customer_id = 0usize;

        // Première arrivée à t = Exp(lambda)
        let first_arrival_time = exp_arrival.sample(&mut self.rng);
        event_queue.push(Event {
            time: first_arrival_time,
            kind: EventKind::Arrival,
            customer_id: next_customer_id,
        });
        next_customer_id += 1;

        // Suivi temporel pour intégration
        let mut last_event_time = 0.0;
        let mut warmup_start_time = 0.0;
        let mut warmup_completed = false;

        // Accumulateurs d'intégration temporelle (post warm-up)
        let mut area_queue = 0.0;
        let mut area_system = 0.0;
        let mut area_server_busy = 0.0;

        // Métriques par client (post warm-up)
        let mut sum_waiting_time = 0.0;
        let mut sum_system_time = 0.0;
        let mut completed_customers_count = 0usize;
        let mut post_warmup_departures = 0usize;

        while let Some(event) = event_queue.pop() {
            let delta = event.time - last_event_time;
            current_time = event.time;

            if warmup_completed {
                let queue_len = waiting_queue.len() as f64;
                let server_occupancy = if current_server_customer.is_some() { 1.0 } else { 0.0 };
                let system_len = queue_len + server_occupancy;

                area_queue += queue_len * delta;
                area_system += system_len * delta;
                area_server_busy += server_occupancy * delta;
            }

            last_event_time = current_time;

            match event.kind {
                EventKind::Arrival => {
                    let customer = Customer {
                        id: event.customer_id,
                        arrival_time: current_time,
                    };

                    if current_server_customer.is_none() {
                        current_server_customer = Some(customer);
                        let service_duration = exp_service.sample(&mut self.rng);
                        event_queue.push(Event {
                            time: current_time + service_duration,
                            kind: EventKind::Departure,
                            customer_id: customer.id,
                        });
                    } else {
                        waiting_queue.push_back(customer);
                    }

                    // Planifie la prochaine arrivée si la limite n'est pas atteinte
                    if next_customer_id < self.total_customers {
                        let inter_arrival = exp_arrival.sample(&mut self.rng);
                        event_queue.push(Event {
                            time: current_time + inter_arrival,
                            kind: EventKind::Arrival,
                            customer_id: next_customer_id,
                        });
                        next_customer_id += 1;
                    }
                }
                EventKind::Departure => {
                    if let Some(serviced_customer) = current_server_customer.take() {
                        completed_customers_count += 1;

                        if completed_customers_count == self.warmup && !warmup_completed {
                            warmup_completed = true;
                            warmup_start_time = current_time;
                        } else if warmup_completed {
                            let system_time = current_time - serviced_customer.arrival_time;
                            let waiting_time = system_time.max(0.0); // Le temps d'attente est déduit plus bas
                            sum_system_time += system_time;
                            post_warmup_departures += 1;
                            // Enregistrement de la métrique
                            let _ = waiting_time;
                        }

                        // Servir le prochain client dans la file d'attente s'il y en a un
                        if let Some(next_customer) = waiting_queue.pop_front() {
                            let wait_in_queue = current_time - next_customer.arrival_time;
                            if warmup_completed {
                                sum_waiting_time += wait_in_queue;
                            }

                            current_server_customer = Some(next_customer);
                            let service_duration = exp_service.sample(&mut self.rng);
                            event_queue.push(Event {
                                time: current_time + service_duration,
                                kind: EventKind::Departure,
                                customer_id: next_customer.id,
                            });
                        }
                    }
                }
            }

            if completed_customers_count >= self.total_customers && current_server_customer.is_none() {
                break;
            }
        }

        let effective_duration = (current_time - warmup_start_time).max(1e-9);
        let sampled_customers = post_warmup_departures;

        if sampled_customers == 0 {
            return Err("Aucun client échantillonné après la période de chauffe.".to_string());
        }

        Ok(SimulationMetrics {
            total_simulated_time: effective_duration,
            sampled_customers,
            server_busy_time: area_server_busy,
            avg_waiting_time_queue: sum_waiting_time / (sampled_customers as f64),
            avg_system_time: sum_system_time / (sampled_customers as f64),
            avg_customers_queue: area_queue / effective_duration,
            avg_customers_system: area_system / effective_duration,
            server_utilization: area_server_busy / effective_duration,
        })
    }
}

fn print_results(args: &CliArgs, theoretical: &TheoreticalMetrics, simulated: &SimulationMetrics) {
    println!("\n================================================================================");
    println!("               RÉSULTATS DE LA SIMULATION FILE D'ATTENTE M/M/1                  ");
    println!("================================================================================");
    println!(" Paramètres d'entrée :");
    println!("   • Taux d'arrivée (λ)            : {:.4}", args.lambda);
    println!("   • Taux de service (μ)            : {:.4}", args.mu);
    println!("   • Clients simulés au total       : {}", args.num_customers);
    println!("   • Période de chauffe (écartés)   : {}", args.warmup);
    println!("   • Échantillons mesurés           : {}", simulated.sampled_customers);
    println!("   • Durée analysée post-chauffe    : {:.2} unités temporelles", simulated.total_simulated_time);
    println!("--------------------------------------------------------------------------------");
    println!("{:<32} | {:<12} | {:<12} | {:<10}", "Métrique", "Empirique", "Théorique", "Écart rel.");
    println!("--------------------------------------------------------------------------------");

    let metrics_to_display = [
        (
            "Taux d'utilisation (ρ)",
            simulated.server_utilization,
            theoretical.rho,
        ),
        (
            "Temps moyen en file (Wq)",
            simulated.avg_waiting_time_queue,
            theoretical.avg_waiting_time_queue,
        ),
        (
            "Temps moyen de séjour (W)",
            simulated.avg_system_time,
            theoretical.avg_system_time,
        ),
        (
            "Nombre moyen en file (Lq)",
            simulated.avg_customers_queue,
            theoretical.avg_customers_queue,
        ),
        (
            "Nombre moyen en système (L)",
            simulated.avg_customers_system,
            theoretical.avg_customers_system,
        ),
    ];

    for (label, emp, theo) in metrics_to_display {
        let rel_error_pct = if theo != 0.0 {
            ((emp - theo).abs() / theo) * 100.0
        } else {
            0.0
        };
        println!("{:<32} | {:<12.5} | {:<12.5} | {:<8.2}%", label, emp, theo, rel_error_pct);
    }
    println!("================================================================================\n");
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = CliArgs::parse();

    if args.warmup >= args.num_customers {
        eprintln!(
            "Erreur : Le nombre de clients de chauffe ({}) doit être inférieur au total des clients ({}).",
            args.warmup, args.num_customers
        );
        std::process::exit(1);
    }

    let theoretical = match TheoreticalMetrics::compute(args.lambda, args.mu) {
        Ok(t) => t,
        Err(err) => {
            eprintln!("Erreur de configuration : {err}");
            std::process::exit(1);
        }
    };

    let mut simulator = Mm1Simulator::new(
        args.lambda,
        args.mu,
        args.num_customers,
        args.warmup,
        args.seed,
    );

    let simulated = simulator.run().map_err(|e| format!("Erreur d'exécution: {e}"))?;

    print_results(&args, &theoretical, &simulated);

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_theoretical_metrics_valid() {
        let metrics = TheoreticalMetrics::compute(3.0, 5.0).expect("Doit être valide");
        assert!((metrics.rho - 0.6).abs() < 1e-6);
        assert!((metrics.avg_system_time - 0.5).abs() < 1e-6);
        assert!((metrics.avg_waiting_time_queue - 0.3).abs() < 1e-6);
        assert!((metrics.avg_customers_system - 1.5).abs() < 1e-6);
        assert!((metrics.avg_customers_queue - 0.9).abs() < 1e-6);
    }

    #[test]
    fn test_theoretical_metrics_unstable() {
        let result = TheoreticalMetrics::compute(5.0, 3.0);
        assert!(result.is_err());
    }

    #[test]
    fn test_simulation_convergence() {
        let lambda = 2.0;
        let mu = 4.0;
        let total = 50_000;
        let warmup = 5_000;
        let seed = Some(42);

        let theo = TheoreticalMetrics::compute(lambda, mu).unwrap();
        let mut sim = Mm1Simulator::new(lambda, mu, total, warmup, seed);
        let res = sim.run().unwrap();

        // Vérification de la cohérence empirique vs théorique à +/- 5%
        let rel_err_wq = (res.avg_waiting_time_queue - theo.avg_waiting_time_queue).abs() / theo.avg_waiting_time_queue;
        assert!(rel_err_wq < 0.05, "Erreur Wq trop élevée: {:.2}%", rel_err_wq * 100.0);

        let rel_err_w = (res.avg_system_time - theo.avg_system_time).abs() / theo.avg_system_time;
        assert!(rel_err_w < 0.05, "Erreur W trop élevée: {:.2}%", rel_err_w * 100.0);
    }
}

