/// Calcule le checksum XOR d'une tranche d'octets.
#[must_use]
pub fn calculate_checksum(payload: &[u8]) -> u8 {
    payload.iter().fold(0u8, |acc, &byte| acc ^ byte)
}

/// Valide le checksum d'une trame brute et extrait le payload ainsi que le talker/type.
pub fn validate_and_extract_payload(raw_line: &str) -> Result<&str, NmeaError> {
    let trimmed = raw_line.trim();
    if trimmed.is_empty() {
        return Err(NmeaError::EmptySentence);
    }

    if !trimmed.starts_with('$') && !trimmed.starts_with('!') {
        return Err(NmeaError::MissingStartDelimiter);
    }

    let without_prefix = &trimmed[1..];
    let mut parts = without_prefix.split('*');

    let payload = parts.next().unwrap_or_default();
    let checksum_str = parts.next().ok_or(NmeaError::MissingChecksumDelimiter)?;

    if checksum_str.len() < 2 {
        return Err(NmeaError::InvalidChecksumHex(checksum_str.to_string()));
    }

    // Le checksum NMEA est exactement sur 2 caractères hexadécimaux
    let hex_part = &checksum_str[..2];
    let expected_checksum = u8::from_str_radix(hex_part, 16)
        .map_err(|_| NmeaError::InvalidChecksumHex(hex_part.to_string()))?;

    let actual_checksum = calculate_checksum(payload.as_bytes());
    if actual_checksum != expected_checksum {
        return Err(NmeaError::ChecksumMismatch {
            expected: expected_checksum,
            actual: actual_checksum,
        });
    }

    Ok(payload)
}

/// Parse une coordonnée NMEA (ddmm.mmmm ou dddmm.mmmm) avec son orientation (N/S/E/W)
/// et la convertit en degrés décimaux signés.
pub fn parse_coordinate(coord_str: &str, dir_str: &str, is_latitude: bool) -> Result<Option<f64>, NmeaError> {
    let coord_str = coord_str.trim();
    let dir_str = dir_str.trim();

    if coord_str.is_empty() || dir_str.is_empty() {
        return Ok(None);
    }

    let deg_len = if is_latitude { 2 } else { 3 };
    if coord_str.len() <= deg_len {
        return Err(NmeaError::InvalidField {
            field: if is_latitude { "latitude" } else { "longitude" },
            detail: format!("Format de coordonnée trop court: '{coord_str}'"),
        });
    }

    let (degrees_str, minutes_str) = coord_str.split_at(deg_len);
    let degrees: f64 = degrees_str.parse().map_err(|e| NmeaError::InvalidField {
        field: if is_latitude { "latitude_degrees" } else { "longitude_degrees" },
        detail: format!("{e}"),
    })?;

    let minutes: f64 = minutes_str.parse().map_err(|e| NmeaError::InvalidField {
        field: if is_latitude { "latitude_minutes" } else { "longitude_minutes" },
        detail: format!("{e}"),
    })?;

    let mut decimal_degrees = degrees + (minutes / 60.0);

    match dir_str {
        "N" | "E" => {}
        "S" | "W" => decimal_degrees = -decimal_degrees,
        other => {
            return Err(NmeaError::InvalidField {
                field: if is_latitude { "latitude_direction" } else { "longitude_direction" },
                detail: format!("Direction invalide '{other}', attendu N/S/E/W"),
            });
        }
    }

    Ok(Some(decimal_degrees))
}

/// Parse une heure NMEA sous le format `hhmmss` ou `hhmmss.sss`.
pub fn parse_time(time_str: &str) -> Result<Option<NaiveTime>, NmeaError> {
    let s = time_str.trim();
    if s.is_empty() {
        return Ok(None);
    }

    if s.len() < 6 {
        return Err(NmeaError::InvalidField {
            field: "time",
            detail: format!("Format heure trop court: '{s}'"),
        });
    }

    let hours: u32 = s[0..2].parse().map_err(|e| NmeaError::InvalidField {
        field: "hours",
        detail: format!("{e}"),
    })?;

    let minutes: u32 = s[2..4].parse().map_err(|e| NmeaError::InvalidField {
        field: "minutes",
        detail: format!("{e}"),
    })?;

    let seconds: u32 = s[4..6].parse().map_err(|e| NmeaError::InvalidField {
        field: "seconds",
        detail: format!("{e}"),
    })?;

    let millis: u32 = if s.len() > 6 && s.as_bytes()[6] == b'.' {
        let frac_str = &s[7..];
        let frac_digits = frac_str.chars().take(3).collect::<String>();
        match frac_digits.len() {
            1 => frac_digits.parse::<u32>().unwrap_or(0) * 100,
            2 => frac_digits.parse::<u32>().unwrap_or(0) * 10,
            3 => frac_digits.parse::<u32>().unwrap_or(0),
            _ => 0,
        }
    } else {
        0
    };

    let time = NaiveTime::from_hms_milli_opt(hours, minutes, seconds, millis).ok_or_else(|| {
        NmeaError::InvalidField {
            field: "time",
            detail: format!("Heure hors bornes: {hours}:{minutes}:{seconds}.{millis}"),
        }
    })?;

    Ok(Some(time))
}

/// Parse une date NMEA sous le format `ddmmyy`.
pub fn parse_date(date_str: &str) -> Result<Option<NaiveDate>, NmeaError> {
    let s = date_str.trim();
    if s.is_empty() {
        return Ok(None);
    }

    if s.len() != 6 {
        return Err(NmeaError::InvalidField {
            field: "date",
            detail: format!("Format ddmmyy attendu (longueur 6), reçu '{s}'"),
        });
    }

    let day: u32 = s[0..2].parse().map_err(|e| NmeaError::InvalidField {
        field: "day",
        detail: format!("{e}"),
    })?;

    let month: u32 = s[2..4].parse().map_err(|e| NmeaError::InvalidField {
        field: "month",
        detail: format!("{e}"),
    })?;

    let year_suffix: i32 = s[4..6].parse().map_err(|e| NmeaError::InvalidField {
        field: "year",
        detail: format!("{e}"),
    })?;

    // Année 2000+ si < 80 sinon 1900+ (convention NMEA standard)
    let full_year = if year_suffix < 80 {
        2000 + year_suffix
    } else {
        1900 + year_suffix
    };

    let date = NaiveDate::from_ymd_opt(full_year, month, day).ok_or_else(|| {
        NmeaError::InvalidField {
            field: "date",
            detail: format!("Date invalide: {day:02}/{month:02}/{full_year}"),
        }
    })?;

    Ok(Some(date))
}

fn parse_optional_f64(field_val: &str, field_name: &'static str) -> Result<Option<f64>, NmeaError> {
    let s = field_val.trim();
    if s.is_empty() {
        Ok(None)
    } else {
        s.parse::<f64>().map(Some).map_err(|e| NmeaError::InvalidField {
            field: field_name,
            detail: format!("{e} pour la valeur '{s}'"),
        })
    }
}

/// Parseur principal pour une ligne NMEA complète.
pub fn parse_nmea_sentence(raw_line: &str) -> Result<NmeaSentence, NmeaError> {
    let payload = validate_and_extract_payload(raw_line)?;
    let fields: Vec<&str> = payload.split(',').collect();

    if fields.is_empty() || fields[0].is_empty() {
        return Err(NmeaError::InvalidIdentifier);
    }

    let sentence_id = fields[0];
    if sentence_id.len() < 3 {
        return Err(NmeaError::InvalidIdentifier);
    }

    let (talker, sentence_type) = if sentence_id.len() >= 5 {
        sentence_id.split_at(2)
    } else {
        ("", sentence_id)
    };

    match sentence_type {
        "RMC" => {
            if fields.len() < 10 {
                return Err(NmeaError::MissingField {
                    sentence: "RMC",
                    index: fields.len(),
                });
            }

            let time = parse_time(fields[1])?;
            let status = match fields[2] {
                "A" => NavigationStatus::Active,
                "V" => NavigationStatus::Void,
                other => {
                    return Err(NmeaError::InvalidField {
                        field: "status",
                        detail: format!("Statut navigation inattendu: '{other}'"),
                    })
                }
            };

            let latitude = parse_coordinate(fields[3], fields[4], true)?;
            let longitude = parse_coordinate(fields[5], fields[6], false)?;
            let speed_knots = parse_optional_f64(fields[7], "speed_knots")?;
            let track_degrees = parse_optional_f64(fields[8], "track_degrees")?;
            let date = parse_date(fields[9])?;

            let magnetic_variation = if fields.len() > 11 && !fields[10].is_empty() {
                let mag = parse_optional_f64(fields[10], "magnetic_variation")?;
                match (mag, fields.get(11)) {
                    (Some(val), Some(&"W")) => Some(-val),
                    (Some(val), _) => Some(val),
                    _ => None,
                }
            } else {
                None
            };

            Ok(NmeaSentence::Rmc {
                talker: talker.to_string(),
                data: RmcData {
                    time,
                    status,
                    latitude,
                    longitude,
                    speed_knots,
                    track_degrees,
                    date,
                    magnetic_variation,
                },
            })
        }
        "GGA" => {
            if fields.len() < 10 {
                return Err(NmeaError::MissingField {
                    sentence: "GGA",
                    index: fields.len(),
                });
            }

            let time = parse_time(fields[1])?;
            let latitude = parse_coordinate(fields[2], fields[3], true)?;
            let longitude = parse_coordinate(fields[4], fields[5], false)?;

            let fix_quality = fields[6]
                .trim()
                .parse::<u8>()
                .map(GpsFixQuality::from)
                .unwrap_or(GpsFixQuality::Invalid);

            let satellites_tracked = fields[7].trim().parse::<u32>().unwrap_or(0);
            let hdop = parse_optional_f64(fields[8], "hdop")?;
            let altitude_msl = parse_optional_f64(fields[9], "altitude_msl")?;

            let geoid_separation = if fields.len() > 11 {
                parse_optional_f64(fields[11], "geoid_separation")?
            } else {
                None
            };

            Ok(NmeaSentence::Gga {
                talker: talker.to_string(),
                data: GgaData {
                    time,
                    latitude,
                    longitude,
                    fix_quality,
                    satellites_tracked,
                    hdop,
                    altitude_msl,
                    geoid_separation,
                },
            })
        }
        "VTG" => {
            if fields.len() < 8 {
                return Err(NmeaError::MissingField {
                    sentence: "VTG",
                    index: fields.len(),
                });
            }

            let true_track_degrees = parse_optional_f64(fields[1], "true_track_degrees")?;
            let magnetic_track_degrees = parse_optional_f64(fields[3], "magnetic_track_degrees")?;
            let speed_knots = parse_optional_f64(fields[5], "speed_knots")?;
            let speed_kmh = parse_optional_f64(fields[7], "speed_kmh")?;

            Ok(NmeaSentence::Vtg {
                talker: talker.to_string(),
                data: VtgData {
                    true_track_degrees,
                    magnetic_track_degrees,
                    speed_knots,
                    speed_kmh,
                },
            })
        }
        "GLL" => {
            if fields.len() < 7 {
                return Err(NmeaError::MissingField {
                    sentence: "GLL",
                    index: fields.len(),
                });
            }

            let latitude = parse_coordinate(fields[1], fields[2], true)?;
            let longitude = parse_coordinate(fields[3], fields[4], false)?;
            let time = parse_time(fields[5])?;
            let status = match fields[6] {
                "A" => NavigationStatus::Active,
                "V" => NavigationStatus::Void,
                other => {
                    return Err(NmeaError::InvalidField {
                        field: "gll_status",
                        detail: format!("Statut GLL inattendu: '{other}'"),
                    })
                }
            };

            Ok(NmeaSentence::Gll {
                talker: talker.to_string(),
                data: GllData {
                    latitude,
                    longitude,
                    time,
                    status,
                },
            })
        }
        _ => Err(NmeaError::UnsupportedSentenceType(sentence_id.to_string())),
    }
}

fn main() {
    println!("=== Parser de Trames Télémétriques NMEA-0183 ===");

    let sample_frames = [
        "$GPRMC,083559.00,A,4717.11437,N,00833.91522,E,0.004,77.52,091218,,,A*5C",
        "$GPGGA,092750.000,5321.6802,N,00630.3372,W,1,8,1.03,61.7,M,55.2,M,,*76",
        "$GPVTG,054.7,T,034.4,M,005.5,N,010.2,K*48",
        "$GPGLL,4916.45,N,12311.12,W,225444,A,*1D",
        // Cas d'erreur pour démonstration : checksum altéré
        "$GPRMC,083559.00,A,4717.11437,N,00833.91522,E,0.004,77.52,091218,,,A*00",
    ];

    for frame in &sample_frames {
        println!("\nTraitement: {frame}");
        match parse_nmea_sentence(frame) {
            Ok(parsed) => {
                println!("  [OK] Résultat: {parsed}");
            }
            Err(err) => {
                eprintln!("  [ERREUR] Rejet de la trame: {err}");
            }
        }
    }
}

