        let sentence = parse_nmea_sentence(frame).expect("La trame RMC devrait être valide");

        match sentence {
            NmeaSentence::Rmc { talker, data } => {
                assert_eq!(talker, "GP");
                assert_eq!(data.status, NavigationStatus::Active);
                let lat = data.latitude.expect("Latitude attendue");
