// src/main.rs
use chrono::{NaiveDate, NaiveTime};
use std::fmt;
use thiserror::Error;

/// Erreurs possibles lors du parsing d'une trame NMEA-0183.
#[derive(Debug, Error, PartialEq)]
pub enum NmeaError {
    #[error("Trame vide")]
    EmptySentence,

    #[error("Délimiteur de début manquant ('$' ou '!')")]
    MissingStartDelimiter,

    #[error("Délimiteur de checksum manquant ('*')")]
    MissingChecksumDelimiter,

    #[error("Format hexadécimal du checksum invalide: {0}")]
    InvalidChecksumHex(String),

    #[error("Checksum invalide: attendu 0x{expected:02X}, calculé 0x{actual:02X}")]
    ChecksumMismatch { expected: u8, actual: u8 },

    #[error("Identifiant de trame manquant ou trop court")]
    InvalidIdentifier,

    #[error("Type de trame non supporté: {0}")]
    UnsupportedSentenceType(String),

    #[error("Champ manquant à l'index {index} pour la trame {sentence}")]
    MissingField {
        sentence: &'static str,
        index: usize,
    },

    #[error("Format invalide pour le champ '{field}': {detail}")]
    InvalidField {
        field: &'static str,
        detail: String,
    },
}

/// Indicateur de qualité du fix GNSS (Trame GGA).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum GpsFixQuality {
    Invalid = 0,
    GpsFix = 1,
    DgpsFix = 2,
    PpsFix = 3,
    Rtk = 4,
    FloatRtk = 5,
    Estimated = 6,
    ManualInput = 7,
    Simulation = 8,
    Unknown,
}

impl From<u8> for GpsFixQuality {
    fn from(val: u8) -> Self {
        match val {
            0 => GpsFixQuality::Invalid,
            1 => GpsFixQuality::GpsFix,
            2 => GpsFixQuality::DgpsFix,
            3 => GpsFixQuality::PpsFix,
            4 => GpsFixQuality::Rtk,
            5 => GpsFixQuality::FloatRtk,
            6 => GpsFixQuality::Estimated,
            7 => GpsFixQuality::ManualInput,
            8 => GpsFixQuality::Simulation,
            _ => GpsFixQuality::Unknown,
        }
    }
}

/// Statut de navigation (ex: RMC, GLL).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NavigationStatus {
    Active,
    Void,
}

/// Données décodées pour une trame RMC (Recommended Minimum Navigation Information).
#[derive(Debug, Clone, PartialEq)]
pub struct RmcData {
    pub time: Option<NaiveTime>,
    pub status: NavigationStatus,
    pub latitude: Option<f64>,
    pub longitude: Option<f64>,
    pub speed_knots: Option<f64>,
    pub track_degrees: Option<f64>,
    pub date: Option<NaiveDate>,
    pub magnetic_variation: Option<f64>,
}

/// Données décodées pour une trame GGA (Global Positioning System Fix Data).
#[derive(Debug, Clone, PartialEq)]
pub struct GgaData {
    pub time: Option<NaiveTime>,
    pub latitude: Option<f64>,
    pub longitude: Option<f64>,
    pub fix_quality: GpsFixQuality,
    pub satellites_tracked: u32,
    pub hdop: Option<f64>,
    pub altitude_msl: Option<f64>,
    pub geoid_separation: Option<f64>,
}

/// Données décodées pour une trame VTG (Track Made Good and Ground Speed).
#[derive(Debug, Clone, PartialEq)]
pub struct VtgData {
