    pub speed_knots: Option<f64>,
    pub speed_kmh: Option<f64>,
}

/// Données décodées pour une trame GLL (Geographic Position - Latitude/Longitude).
#[derive(Debug, Clone, PartialEq)]
pub struct GllData {
