// src/main.rs
use clap::{Parser, Subcommand};
use colored::*;
use fuzzy_search_engine::{FuzzyConfig, FuzzyEngine, MatchHighlighter};
use std::fs;
use std::io::{self, BufRead};
use std::path::{Path, PathBuf};

#[derive(Parser, Debug)]
#[command(
    name = "fuzzy-search",
    author = "Damien",
    version,
    about = "Moteur de recherche floue haute performance basé sur l'alignement de sous-séquences",
    long_about = "Moteur de recherche floue (Fuzzy Search) implémentant la programmation dynamique avec pénalités de saut affines et bonus contextuels (frontières de mots, camelCase, etc.)."
)]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,

    /// Requête de recherche rapide (si aucun sous-ordre n'est fourni)
    #[arg(short = 'q', long = "query")]
    query: Option<String>,

    /// Recherche sensible à la casse
    #[arg(short = 'c', long = "case-sensitive", default_value_t = false)]
    case_sensitive: bool,

    /// Nombre maximum de résultats à afficher
    #[arg(short = 'n', long = "limit", default_value_t = 15)]
    limit: usize,

    /// Seuil de score minimal pour filtrer les résultats
    #[arg(short = 's', long = "min-score")]
    min_score: Option<i32>,

    /// Active l'exécution parallèle avec Rayon
    #[arg(short = 'p', long = "parallel", default_value_t = false)]
    parallel: bool,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Lance une démonstration interactive illustrant les capacités du moteur
    Demo,

    /// Recherche dans une liste d'éléments passés en argument ou via stdin
    Search {
        /// Chaîne de recherche (motif)
        query: String,

        /// Liste explicite de candidats (si absent, lit depuis stdin)
        #[arg(trailing_var_arg = true)]
        candidates: Vec<String>,
    },

    /// Recherche récursive de fichiers dans un répertoire
    Files {
        /// Motif recherché dans les chemins de fichiers
        query: String,

        /// Répertoire racine de départ
        #[arg(short = 'd', long = "dir", default_value = ".")]
        dir: PathBuf,
    },
}

/// Collecte récursivement les fichiers d'un dossier sans paniquer en cas d'erreur de permission.
fn collect_files_recursively(dir: &Path, file_paths: &mut Vec<String>) -> io::Result<()> {
    if dir.is_dir() {
        let entries = match fs::read_dir(dir) {
            Ok(entries) => entries,
            Err(e) => {
                eprintln!("{}: Impossible de lire le dossier {:?} ({})", "Attention".yellow(), dir, e);
                return Ok(());
            }
        };

        for entry in entries.flatten() {
            let path = entry.path();
            // Ignorer les dossiers cachés comme .git
            if let Some(file_name) = path.file_name().and_then(|n| n.to_str()) {
                if file_name.starts_with('.') && file_name != "." {
                    continue;
                }
            }

            if path.is_dir() {
                let _ = collect_files_recursively(&path, file_paths);
            } else if let Some(path_str) = path.to_str() {
                file_paths.push(path_str.to_string());
            }
        }
    }
    Ok(())
}

/// Exécute la recherche et affiche les résultats formatés avec coloration ANSI.
fn execute_and_display(
    engine: &FuzzyEngine,
    query: &str,
    candidates: &[String],
    limit: usize,
    min_score: Option<i32>,
    parallel: bool,
) {
    let start_time = std::time::Instant::now();

    let mut results = if parallel {
        engine.search_parallel(query, candidates, |s| s.as_str())
    } else {
        engine.search(query, candidates, |s| s.as_str())
    };

    if let Some(threshold) = min_score {
        results.retain(|r| r.score >= threshold);
    }

    let elapsed = start_time.elapsed();
    let total_matched = results.len();
    let display_count = total_matched.min(limit);

    println!(
        "\n{} \"{}\" parmi {} candidats (trouvé {} en {:.2?}):",
        "Recherche pour".bold().cyan(),
        query.bold().white(),
        candidates.len().to_string().yellow(),
        total_matched.to_string().green(),
        elapsed
    );
    println!("{}", "=".repeat(70).dimmed());

    if display_count == 0 {
        println!("{}", "Aucun résultat correspondant trouvé.".italic().bright_black());
    } else {
        for (rank, result) in results.iter().take(display_count).enumerate() {
            let highlighted = MatchHighlighter::highlight_ansi(result.item, &result.matched_indices);
            println!(
                " {:>2}. [{:>5} pts]  {}",
                rank + 1,
                result.score.to_string().bright_magenta().bold(),
                highlighted
            );
        }
    }

    if total_matched > display_count {
        println!(
            "{}",
            format!("... et {} autre(s) résultat(s) masqué(s) (utiliser --limit pour en voir plus).", total_matched - display_count).dimmed()
        );
    }
    println!("{}", "=".repeat(70).dimmed());
}

/// Démonstration guidée des forces de l'alignement flou
