fn main() -> Result<(), Box<dyn std::error::Error>> {
    let cli = Cli::parse();

    let config = FuzzyConfig {
        case_sensitive: cli.case_sensitive,
        ..Default::default()
    };
    let engine = FuzzyEngine::new(config);

    match cli.command {
        Some(Commands::Demo) => {
            run_demonstration(&engine);
        }
        Some(Commands::Search { query, candidates }) => {
            let pool: Vec<String> = if !candidates.is_empty() {
                candidates
            } else {
                let stdin = io::stdin();
                let lines: Result<Vec<String>, _> = stdin.lock().lines().collect();
                match lines {
                    Ok(l) => l,
                    Err(e) => {
                        eprintln!("{}: Erreur lors de la lecture de stdin : {}", "Erreur".red(), e);
                        return Ok(());
                    }
                }
            };
            execute_and_display(&engine, &query, &pool, cli.limit, cli.min_score, cli.parallel);
        }
        Some(Commands::Files { query, dir }) => {
            let mut file_paths = Vec::new();
            if let Err(e) = collect_files_recursively(&dir, &mut file_paths) {
                eprintln!("{}: Erreur lors du parcours du dossier {:?} : {}", "Erreur".red(), dir, e);
                return Ok(());
            }
            execute_and_display(&engine, &query, &file_paths, cli.limit, cli.min_score, cli.parallel);
        }
        None => {
            if let Some(query) = cli.query {
                // Lecture automatique depuis stdin si une requête sans sous-commande est spécifiée
                let stdin = io::stdin();
                let lines: Result<Vec<String>, _> = stdin.lock().lines().collect();
                let pool = match lines {
                    Ok(l) => l,
                    Err(e) => {
                        eprintln!("{}: Erreur lors de la lecture de stdin : {}", "Erreur".red(), e);
                        return Ok(());
                    }
                };
                execute_and_display(&engine, &query, &pool, cli.limit, cli.min_score, cli.parallel);
            } else {
                // Par défaut, proposer la démo interactive si aucun argument n'est fourni
                println!("{}", "Aucun argument spécifique fourni. Lancement du mode démonstration :".italic().cyan());
                run_demonstration(&engine);
            }
        }
    }

    Ok(())
}

