// src/main.rs
use clap::{Parser, Subcommand};
use colored::*;
use fuzzy_search_engine::{FuzzyConfig, FuzzyEngine, MatchHighlighter};
use std::fs;
use std::io::{self, BufRead};
use std::path::{Path, PathBuf};

#[derive(Parser, Debug)]
#[command(
    name = "fuzzy-search",
    author = "Damien",
    version,
    about = "Moteur de recherche floue haute performance basé sur l'alignement de sous-séquences",
    long_about = "Moteur de recherche floue (Fuzzy Search) implémentant la programmation dynamique avec pénalités de saut affines et bonus contextuels (frontières de mots, camelCase, etc.)."
)]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,

    /// Requête de recherche rapide (si aucun sous-ordre n'est fourni)
    #[arg(short = 'q', long = "query")]
    query: Option<String>,

    /// Recherche sensible à la casse
    #[arg(short = 'c', long = "case-sensitive", default_value_t = false)]
    case_sensitive: bool,

    /// Nombre maximum de résultats à afficher
    #[arg(short = 'n', long = "limit", default_value_t = 15)]
    limit: usize,

    /// Seuil de score minimal pour filtrer les résultats
    #[arg(short = 's', long = "min-score")]
    min_score: Option<i32>,

    /// Active l'exécution parallèle avec Rayon
    #[arg(short = 'p', long = "parallel", default_value_t = false)]
    parallel: bool,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Lance une démonstration interactive illustrant les capacités du moteur
    Demo,

    /// Recherche dans une liste d'éléments passés en argument ou via stdin
    Search {
        /// Chaîne de recherche (motif)
        query: String,

        /// Liste explicite de candidats (si absent, lit depuis stdin)
        #[arg(trailing_var_arg = true)]
        candidates: Vec<String>,
    },

    /// Recherche récursive de fichiers dans un répertoire
    Files {
        /// Motif recherché dans les chemins de fichiers
        query: String,

        /// Répertoire racine de départ
        #[arg(short = 'd', long = "dir", default_value = ".")]
        dir: PathBuf,
    },
}

/// Collecte récursivement les fichiers d'un dossier sans paniquer en cas d'erreur de permission.
fn collect_files_recursively(dir: &Path, file_paths: &mut Vec<String>) -> io::Result<()> {
    if dir.is_dir() {
        let entries = match fs::read_dir(dir) {
            Ok(entries) => entries,
            Err(e) => {
                eprintln!("{}: Impossible de lire le dossier {:?} ({})", "Attention".yellow(), dir, e);
                return Ok(());
            }
        };

        for entry in entries.flatten() {
            let path = entry.path();
            // Ignorer les dossiers cachés comme .git
            if let Some(file_name) = path.file_name().and_then(|n| n.to_str()) {
                if file_name.starts_with('.') && file_name != "." {
                    continue;
                }
            }

            if path.is_dir() {
                let _ = collect_files_recursively(&path, file_paths);
            } else if let Some(path_str) = path.to_str() {
                file_paths.push(path_str.to_string());
            }
        }
    }
    Ok(())
}

/// Exécute la recherche et affiche les résultats formatés avec coloration ANSI.
fn execute_and_display(
    engine: &FuzzyEngine,
    query: &str,
    candidates: &[String],
    limit: usize,
    min_score: Option<i32>,
    parallel: bool,
) {
    let start_time = std::time::Instant::now();

    let mut results = if parallel {
        engine.search_parallel(query, candidates, |s| s.as_str())
    } else {
        engine.search(query, candidates, |s| s.as_str())
    };

    if let Some(threshold) = min_score {
        results.retain(|r| r.score >= threshold);
    }

    let elapsed = start_time.elapsed();
    let total_matched = results.len();
    let display_count = total_matched.min(limit);

    println!(
        "\n{} \"{}\" parmi {} candidats (trouvé {} en {:.2?}):",
        "Recherche pour".bold().cyan(),
        query.bold().white(),
        candidates.len().to_string().yellow(),
        total_matched.to_string().green(),
        elapsed
    );
    println!("{}", "=".repeat(70).dimmed());

    if display_count == 0 {
        println!("{}", "Aucun résultat correspondant trouvé.".italic().bright_black());
    } else {
        for (rank, result) in results.iter().take(display_count).enumerate() {
            let highlighted = MatchHighlighter::highlight_ansi(result.item, &result.matched_indices);
            println!(
                " {:>2}. [{:>5} pts]  {}",
                rank + 1,
                result.score.to_string().bright_magenta().bold(),
                highlighted
            );
        }
    }

    if total_matched > display_count {
        println!(
            "{}",
            format!("... et {} autre(s) résultat(s) masqué(s) (utiliser --limit pour en voir plus).", total_matched - display_count).dimmed()
        );
    }
    println!("{}", "=".repeat(70).dimmed());
}

/// Démonstration guidée des forces de l'alignement flou
fn run_demonstration(engine: &FuzzyEngine) {
    println!("{}", "======================================================================".bold().blue());
    println!("{}", "  Démonstration du Moteur de Recherche Floue (Fuzzy Alignment)".bold().green());
    println!("{}", "======================================================================".bold().blue());
    println!("Caractéristiques illustrées :");
    println!("  • Détection et bonus des frontières de mots (snake_case, kebab-case, /)");
    println!("  • Reconnaissance de la convention camelCase");
    println!("  • Priorisation des correspondances consécutives et des préfixes");
    println!("  • Tolérance aux sauts (gaps) avec pénalités affines");

    let file_corpus = vec![
        "src/core/fuzzy_engine.rs".to_string(),
        "src/algorithms/subsequence.rs".to_string(),
        "src/algorithms/needleman_wunsch.rs".to_string(),
        "src/models/scoring_matrix.rs".to_string(),
        "src/utils/file_scanner.rs".to_string(),
        "src/utils/string_formatter.rs".to_string(),
        "tests/integration_search_test.rs".to_string(),
        "tests/fixtures/sample_data.json".to_string(),
        "Cargo.toml".to_string(),
        "CAHIER_DES_CHARGES.md".to_string(),
        "README.md".to_string(),
    ];

    let demo_queries = [
        ("fe", "Recherche par acronyme / frontière de mots ('fe' -> fuzzy_engine)"),
        ("subseq", "Recherche de sous-séquence consécutive ('subseq' -> subsequence.rs)"),
        ("nw", "Recherche d'initiales d'algorithme ('nw' -> needleman_wunsch.rs)"),
        ("cahier", "Recherche de document de spécification ('cahier' -> CAHIER_DES_CHARGES.md)"),
        ("test", "Recherche générique avec plusieurs candidats qualifiés"),
    ];

    for (query, explanation) in demo_queries {
        println!("\n▶ Démo : {}", explanation.bold().yellow());
        execute_and_display(engine, query, &file_corpus, 5, None, false);
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let cli = Cli::parse();

    let config = FuzzyConfig {
        case_sensitive: cli.case_sensitive,
        ..Default::default()
    };
    let engine = FuzzyEngine::new(config);

    match cli.command {
        Some(Commands::Demo) => {
            run_demonstration(&engine);
        }
        Some(Commands::Search { query, candidates }) => {
            let pool: Vec<String> = if !candidates.is_empty() {
                candidates
            } else {
                let stdin = io::stdin();
                let lines: Result<Vec<String>, _> = stdin.lock().lines().collect();
                match lines {
                    Ok(l) => l,
                    Err(e) => {
                        eprintln!("{}: Erreur lors de la lecture de stdin : {}", "Erreur".red(), e);
                        return Ok(());
                    }
                }
            };
            execute_and_display(&engine, &query, &pool, cli.limit, cli.min_score, cli.parallel);
        }
        Some(Commands::Files { query, dir }) => {
            let mut file_paths = Vec::new();
            if let Err(e) = collect_files_recursively(&dir, &mut file_paths) {
                eprintln!("{}: Erreur lors du parcours du dossier {:?} : {}", "Erreur".red(), dir, e);
                return Ok(());
            }
            execute_and_display(&engine, &query, &file_paths, cli.limit, cli.min_score, cli.parallel);
        }
        None => {
            if let Some(query) = cli.query {
                // Lecture automatique depuis stdin si une requête sans sous-commande est spécifiée
                let stdin = io::stdin();
                let lines: Result<Vec<String>, _> = stdin.lock().lines().collect();
                let pool = match lines {
                    Ok(l) => l,
                    Err(e) => {
                        eprintln!("{}: Erreur lors de la lecture de stdin : {}", "Erreur".red(), e);
                        return Ok(());
                    }
                };
                execute_and_display(&engine, &query, &pool, cli.limit, cli.min_score, cli.parallel);
            } else {
                // Par défaut, proposer la démo interactive si aucun argument n'est fourni
                println!("{}", "Aucun argument spécifique fourni. Lancement du mode démonstration :".italic().cyan());
                run_demonstration(&engine);
            }
        }
    }

    Ok(())
}

