    }
}

/// Simulateur de Jeu de la Vie de Conway sur tore.
/// Optimisé pour n'évaluer que les cellules vivantes et leur voisinage immédiat.
pub struct TorusLife {
    width: u32,
    height: u32,
    alive_cells: FxHashSet<Coord>,
    next_alive_cells: FxHashSet<Coord>,
    neighbor_counts: FxHashMap<Coord, u8>,
    generation: u64,
}

impl TorusLife {
    /// Initialise un nouveau monde torique de dimensions `width` x `height`.
    pub fn new(width: u32, height: u32) -> Self {
        let capacity_hint = ((width * height) / 10).max(128) as usize;
        Self {
            width: width.max(3),
            height: height.max(3),
            alive_cells: FxHashSet::with_capacity_and_hasher(capacity_hint, Default::default()),
            next_alive_cells: FxHashSet::with_capacity_and_hasher(capacity_hint, Default::default()),
            neighbor_counts: FxHashMap::with_capacity_and_hasher(capacity_hint * 4, Default::default()),
            generation: 0,
        }
    }

    pub fn width(&self) -> u32 {
        self.width
    }

    pub fn height(&self) -> u32 {
        self.height
    }

    pub fn generation(&self) -> u64 {
        self.generation
    }

    pub fn alive_count(&self) -> usize {
        self.alive_cells.len()
    }

    pub fn is_alive(&self, coord: Coord) -> bool {
        self.alive_cells.contains(&coord)
    }

    pub fn clear(&mut self) {
        self.alive_cells.clear();
        self.next_alive_cells.clear();
        self.neighbor_counts.clear();
        self.generation = 0;
    }

    /// Active une cellule avec coordonnées enroulées sur le tore.
    pub fn set_alive(&mut self, x: i32, y: i32) {
        let wrapped_x = x.rem_euclid(self.width as i32) as u32;
        let wrapped_y = y.rem_euclid(self.height as i32) as u32;
        self.alive_cells.insert(Coord::new(wrapped_x, wrapped_y));
    }

    /// Remplissage aléatoire simple (densité configurable en pourcentage [0; 100]).
    pub fn randomize(&mut self, density_percent: u32) {
        self.clear();
        // Générateur pseudo-aléatoire simple Xorshift32 pour éviter les dépendances lourdes.
        let mut rng_state: u32 = 0x853c49e6 ^ (self.width * 31 + self.height);
        let threshold = (density_percent.min(100) as u64 * (u32::MAX as u64)) / 100;

        for y in 0..self.height {
            for x in 0..self.width {
                rng_state ^= rng_state << 13;
                rng_state ^= rng_state >> 17;
                rng_state ^= rng_state << 5;
                if (rng_state as u64) < threshold {
                    self.alive_cells.insert(Coord::new(x, y));
                }
            }
        }
    }

    /// Injecte le canon à planeurs de Gosper (Gosper Glider Gun).
    pub fn insert_gosper_glider_gun(&mut self, offset_x: i32, offset_y: i32) {
        const PATTERN: &[(i32, i32)] = &[
            (1, 5), (1, 6), (2, 5), (2, 6),
            (11, 5), (11, 6), (11, 7),
            (12, 4), (12, 8),
            (13, 3), (13, 9),
            (14, 3), (14, 9),
            (15, 6),
            (16, 4), (16, 8),
            (17, 5), (17, 6), (17, 7),
            (18, 6),
            (21, 3), (21, 4), (21, 5),
            (22, 3), (22, 4), (22, 5),
            (23, 2), (23, 6),
            (25, 1), (25, 2), (25, 6), (25, 7),
            (35, 3), (35, 4),
            (36, 3), (36, 4),
        ];

        for &(px, py) in PATTERN {
            self.set_alive(offset_x + px, offset_y + py);
        }
    }

    /// Avance la simulation d'un pas de génération selon les règles de Conway.
    /// Complexité O(N_alive) grâce à l'accumulation ciblée sur les 8 voisins toriques.
    pub fn step(&mut self) {
        self.neighbor_counts.clear();

        let w = self.width;
        let h = self.height;

        // Voisinage de Moore torique précalculé sous forme de déplacements
        for &cell in &self.alive_cells {
            let left = if cell.x == 0 { w - 1 } else { cell.x - 1 };
            let right = if cell.x + 1 == w { 0 } else { cell.x + 1 };
            let up = if cell.y == 0 { h - 1 } else { cell.y - 1 };
            let down = if cell.y + 1 == h { 0 } else { cell.y + 1 };

            let neighbors = [
                Coord::new(left, up),
                Coord::new(cell.x, up),
                Coord::new(right, up),
                Coord::new(left, cell.y),
                Coord::new(right, cell.y),
                Coord::new(left, down),
                Coord::new(cell.x, down),
                Coord::new(right, down),
            ];

            for neighbor in neighbors {
                *self.neighbor_counts.entry(neighbor).or_insert(0) += 1;
            }
        }

        self.next_alive_cells.clear();

        // Règles de Conway :
        // 1. Toute cellule vivante avec 2 ou 3 voisines survit.
        // 2. Toute cellule morte avec exactement 3 voisines naît.
        for (&coord, &count) in &self.neighbor_counts {
            if count == 3 || (count == 2 && self.alive_cells.contains(&coord)) {
                self.next_alive_cells.insert(coord);
            }
        }

        std::mem::swap(&mut self.alive_cells, &mut self.next_alive_cells);
        self.generation = self.generation.saturating_add(1);
    }
}

/// Gestionnaire d'affichage Terminal (TUI)
struct TerminalView {
    stdout: Stdout,
}

impl TerminalView {
    fn new() -> io::Result<Self> {
        let mut stdout = stdout();
        terminal::enable_raw_mode()?;
        execute!(stdout, terminal::EnterAlternateScreen, cursor::Hide)?;
        Ok(Self { stdout })
    }

    fn render(&mut self, sim: &TorusLife, paused: bool, tick_millis: u64) -> io::Result<()> {
        queue!(
            self.stdout,
            cursor::MoveTo(0, 0),
            Clear(ClearType::FromCursorDown)
        )?;

        // En-tête des informations
        queue!(
            self.stdout,
            SetForegroundColor(Color::Cyan),
            Print(format!(
                "┌─ Jeu de la Vie (Tore {}x{}) ── Génération: {:<6} ── Cellules vivantes: {:<6} ── Vitesse: {:<4}ms ── État: {} ─┐\r\n",
                sim.width(),
                sim.height(),
                sim.generation(),
                sim.alive_count(),
                tick_millis,
                if paused { "PAUSE" } else { "ACTIF" }
            )),
            ResetColor
        )?;

        // Rendu des lignes de la grille
        for y in 0..sim.height() {
            queue!(self.stdout, SetForegroundColor(Color::DarkGrey), Print("│"), ResetColor)?;
            for x in 0..sim.width() {
                if sim.is_alive(Coord::new(x, y)) {
                    queue!(self.stdout, SetForegroundColor(Color::Green), Print("■"), ResetColor)?;
                } else {
                    queue!(self.stdout, Print(" "))?;
                }
            }
            queue!(self.stdout, SetForegroundColor(Color::DarkGrey), Print("│\r\n"), ResetColor)?;
        }

        // Bas de cadre et raccourcis
        queue!(
            self.stdout,
            SetForegroundColor(Color::DarkGrey),
            Print(format!("└{}┘\r\n", "─".repeat(sim.width() as usize))),
            SetForegroundColor(Color::Yellow),
            Print(" Commandes : [Espace] Pause/Reprendre | [n] Pas à pas | [+] Accélérer | [-] Ralentir | [r] Aléatoire | [g] Glider Gun | [c] Vider | [q] Quitter\r\n"),
            ResetColor
        )?;

        self.stdout.flush()
    }
}

impl Drop for TerminalView {
    fn drop(&mut self) {
        let _ = execute!(self.stdout, cursor::Show, terminal::LeaveAlternateScreen);
        let _ = terminal::disable_raw_mode();
    }
}

fn main() -> io::Result<()> {
    let (term_cols, term_rows) = terminal::size().unwrap_or((80, 24));

    // Ajustement de la taille de grille torique pour tenir confortablement dans la console
    let grid_w = (term_cols.saturating_sub(4)).max(20) as u32;
    let grid_h = (term_rows.saturating_sub(6)).max(15) as u32;

    let mut sim = TorusLife::new(grid_w, grid_h);

    // Initialiser avec Gosper Glider Gun s'il y a assez d'espace, sinon aléatoire
    if grid_w >= 40 && grid_h >= 20 {
        sim.insert_gosper_glider_gun(2, 2);
    } else {
        sim.randomize(20);
    }

    let mut view = TerminalView::new()?;
    let mut paused = false;
    let mut tick_duration = Duration::from_millis(60);
    let mut last_tick = Instant::now();

    view.render(&sim, paused, tick_duration.as_millis() as u64)?;

    loop {
        let timeout = tick_duration
            .checked_sub(last_tick.elapsed())
            .unwrap_or(Duration::from_millis(0));

        if event::poll(timeout)? {
            if let Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press {
                    match key.code {
                        KeyCode::Char('q') | KeyCode::Esc => break,
                        KeyCode::Char(' ') => paused = !paused,
                        KeyCode::Char('n') => {
                            if paused {
                                sim.step();
                            }
                        }
                        KeyCode::Char('+') | KeyCode::Char('=') => {
                            let ms = tick_duration.as_millis() as u64;
                            tick_duration = Duration::from_millis(ms.saturating_sub(10).max(10));
                        }
                        KeyCode::Char('-') => {
                            let ms = tick_duration.as_millis() as u64;
                            tick_duration = Duration::from_millis(ms.saturating_add(10).min(500));
                        }
                        KeyCode::Char('r') => {
                            sim.randomize(20);
                        }
                        KeyCode::Char('c') => {
                            sim.clear();
                        }
                        KeyCode::Char('g') => {
                            sim.clear();
                            sim.insert_gosper_glider_gun(2, 2);
                        }
                        _ => {}
                    }
                    view.render(&sim, paused, tick_duration.as_millis() as u64)?;
                }
            }
        }

        if !paused && last_tick.elapsed() >= tick_duration {
            sim.step();
            last_tick = Instant::now();
            view.render(&sim, paused, tick_duration.as_millis() as u64)?;
        }
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_torus_wrapping_neighbors() {
        let mut sim = TorusLife::new(5, 5);
        // Placer un clignotant (blinker) à cheval sur le bord droit/gauche
        // (4, 2), (0, 2), (1, 2)
        sim.set_alive(4, 2);
        sim.set_alive(0, 2);
        sim.set_alive(1, 2);

        assert_eq!(sim.alive_count(), 3);
        sim.step();

        // Le clignotant horizontal devient vertical en (0, 1), (0, 2), (0, 3)
        assert_eq!(sim.alive_count(), 3);
        assert!(sim.is_alive(Coord::new(0, 1)));
        assert!(sim.is_alive(Coord::new(0, 2)));
        assert!(sim.is_alive(Coord::new(0, 3)));
    }

    #[test]
    fn test_underpopulation_and_overpopulation() {
        let mut sim = TorusLife::new(10, 10);
        // Cellule isolée
        sim.set_alive(5, 5);
        sim.step();
        assert_eq!(sim.alive_count(), 0);

        // Surpopulation (croix dense de 5 cellules : le centre a 4 voisins vivants)
        sim.clear();
        sim.set_alive(5, 5);
        sim.set_alive(5, 4);
        sim.set_alive(5, 6);
        sim.set_alive(4, 5);
        sim.set_alive(6, 5);
        sim.step();
        assert!(!sim.is_alive(Coord::new(5, 5)));
    }

    #[test]
    fn test_still_life_block() {
        let mut sim = TorusLife::new(10, 10);
        // Bloc 2x2
        sim.set_alive(1, 1);
        sim.set_alive(1, 2);
        sim.set_alive(2, 1);
        sim.set_alive(2, 2);

        sim.step();
        assert_eq!(sim.alive_count(), 4);
        assert!(sim.is_alive(Coord::new(1, 1)));
        assert!(sim.is_alive(Coord::new(1, 2)));
        assert!(sim.is_alive(Coord::new(2, 1)));
        assert!(sim.is_alive(Coord::new(2, 2)));
    }
}

