// src/main.rs
use chrono::{DateTime, NaiveDateTime, Utc};
use std::collections::HashMap;
use std::fmt;
use std::str::FromStr;
use thiserror::Error;

/// Caractère de séparation standard du protocole FIX (ASCII SOH 0x01).
pub const SOH: char = '\x01';

// ============================================================================
// GESTION DES ERREURS
// ============================================================================

#[derive(Debug, Error, PartialEq)]
pub enum FixError {
    #[error("Message vide")]
    EmptyMessage,

    #[error("Format invalide pour la paire tag-valeur : '{0}'")]
    InvalidTagValue(String),

    #[error("Tag non numérique ou invalide : '{0}'")]
    InvalidTagNumber(String),

    #[error("Tag obligatoire manquant : {0}")]
    MissingRequiredTag(u32),

    #[error("Le premier tag doit être BeginString (8), trouvé : {0}")]
    InvalidHeaderBeginString(u32),

    #[error("Le deuxième tag doit être BodyLength (9), trouvé : {0}")]
    InvalidHeaderBodyLength(u32),

    #[error("Le troisième tag doit être MsgType (35), trouvé : {0}")]
    InvalidHeaderMsgType(u32),

    #[error("Le dernier tag doit être CheckSum (10), trouvé : {0}")]
    InvalidTrailerCheckSum(u32),

    #[error("BodyLength erroné : attendu {expected}, calculé {actual}")]
    BodyLengthMismatch { expected: usize, actual: usize },

    #[error("Checksum FIX invalide : attendu '{expected}', calculé '{actual}'")]
    CheckSumMismatch { expected: String, actual: String },

    #[error("Erreur de conversion de type pour le tag {tag} ({field_name}) : '{raw_value}'")]
    TypeConversionError {
        tag: u32,
        field_name: &'static str,
        raw_value: String,
    },

    #[error("Valeur enum inattendue pour le champ '{0}' : '{1}'")]
    InvalidEnumValue(&'static str, String),
}

// ============================================================================
// ÉNUMÉRATIONS ET TYPES MÉTIER FIX COURANTS
// ============================================================================

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MsgType {
    Heartbeat,
    Logon,
    NewOrderSingle,
    OrderCancelRequest,
    ExecutionReport,
    Unknown,
}

impl MsgType {
    pub fn from_fix_code(code: &str) -> Self {
        match code {
            "0" => MsgType::Heartbeat,
            "A" => MsgType::Logon,
            "D" => MsgType::NewOrderSingle,
            "F" => MsgType::OrderCancelRequest,
            "8" => MsgType::ExecutionReport,
            _ => MsgType::Unknown,
        }
    }

    pub fn as_str(&self) -> &'static str {
        match self {
            MsgType::Heartbeat => "0",
            MsgType::Logon => "A",
            MsgType::NewOrderSingle => "D",
            MsgType::OrderCancelRequest => "F",
            MsgType::ExecutionReport => "8",
            MsgType::Unknown => "?",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Side {
    Buy,
    Sell,
    SellShort,
}

impl TryFrom<char> for Side {
    type Error = FixError;

    fn try_from(c: char) -> Result<Self, Self::Error> {
        match c {
            '1' => Ok(Side::Buy),
            '2' => Ok(Side::Sell),
            '5' => Ok(Side::SellShort),
            _ => Err(FixError::InvalidEnumValue("Side (54)", c.to_string())),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OrdType {
    Market,
    Limit,
    Stop,
    StopLimit,
}

impl TryFrom<char> for OrdType {
    type Error = FixError;

    fn try_from(c: char) -> Result<Self, Self::Error> {
        match c {
            '1' => Ok(OrdType::Market),
            '2' => Ok(OrdType::Limit),
            '3' => Ok(OrdType::Stop),
            '4' => Ok(OrdType::StopLimit),
            _ => Err(FixError::InvalidEnumValue("OrdType (40)", c.to_string())),
        }
    }
}

// ============================================================================
// STRUCTURES DU PARSER FIX
// ============================================================================

/// Représente une paire tag-valeur individuelle
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FixField {
    pub tag: u32,
    pub value: String,
}

/// Message FIX décodé avec accès indexé
#[derive(Debug, Clone, PartialEq)]
pub struct FixMessage {
    pub begin_string: String,
    pub body_length: usize,
    pub msg_type: String,
    pub checksum: String,
    pub fields: Vec<FixField>,
    tag_map: HashMap<u32, usize>,
}

impl FixMessage {
    /// Obtient la valeur brute sous forme de slice pour un tag donné
    pub fn get_raw(&self, tag: u32) -> Option<&str> {
        self.tag_map
            .get(&tag)
            .and_then(|&idx| self.fields.get(idx))
            .map(|f| f.value.as_str())
    }

    /// Extrait et valide une valeur de type chaîne
    pub fn get_string(&self, tag: u32, _field_name: &'static str) -> Result<String, FixError> {
        self.get_raw(tag)
            .map(|s| s.to_string())
            .ok_or(FixError::MissingRequiredTag(tag))
    }

    /// Extrait et valide une valeur entière signée (i64)
    pub fn get_i64(&self, tag: u32, field_name: &'static str) -> Result<i64, FixError> {
        let val = self.get_raw(tag).ok_or(FixError::MissingRequiredTag(tag))?;
        val.parse::<i64>().map_err(|_| FixError::TypeConversionError {
            tag,
            field_name,
            raw_value: val.to_string(),
        })
    }

    /// Extrait et valide une valeur entière non signée (u64)
    pub fn get_u64(&self, tag: u32, field_name: &'static str) -> Result<u64, FixError> {
        let val = self.get_raw(tag).ok_or(FixError::MissingRequiredTag(tag))?;
        val.parse::<u64>().map_err(|_| FixError::TypeConversionError {
            tag,
            field_name,
            raw_value: val.to_string(),
        })
    }

    /// Extrait et valide un nombre flottant (ex: Price)
    pub fn get_f64(&self, tag: u32, field_name: &'static str) -> Result<f64, FixError> {
        let val = self.get_raw(tag).ok_or(FixError::MissingRequiredTag(tag))?;
        val.parse::<f64>().map_err(|_| FixError::TypeConversionError {
            tag,
            field_name,
            raw_value: val.to_string(),
        })
    }

    /// Extrait et valide un caractère unique
    pub fn get_char(&self, tag: u32, field_name: &'static str) -> Result<char, FixError> {
        let val = self.get_raw(tag).ok_or(FixError::MissingRequiredTag(tag))?;
        if val.len() == 1 {
            Ok(val.chars().next().unwrap_or_default())
        } else {
            Err(FixError::TypeConversionError {
                tag,
                field_name,
                raw_value: val.to_string(),
            })
        }
    }

    /// Extrait et valide un horodatage FIX UTCTimestamp
    /// Formats acceptés : `YYYYMMDD-HH:MM:SS` ou `YYYYMMDD-HH:MM:SS.3f`
    pub fn get_timestamp(
        &self,
        tag: u32,
        field_name: &'static str,
    ) -> Result<DateTime<Utc>, FixError> {
        let val = self.get_raw(tag).ok_or(FixError::MissingRequiredTag(tag))?;

        let naive = NaiveDateTime::parse_from_str(val, "%Y%m%d-%H:%M:%S%.f")
            .or_else(|_| NaiveDateTime::parse_from_str(val, "%Y%m%d-%H:%M:%S"))
            .map_err(|_| FixError::TypeConversionError {
                tag,
                field_name,
                raw_value: val.to_string(),
            })?;

        Ok(DateTime::<Utc>::from_naive_utc_and_offset(naive, Utc))
    }
}

impl fmt::Display for FixMessage {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "FIX [{}] Type: {} ({} fields)",
            self.begin_string,
            self.msg_type,
            self.fields.len()
        )
    }
}

// ============================================================================
// PARSER ET VALIDATEUR DU PROTOCOLE FIX
// ============================================================================

pub struct FixParser;

impl FixParser {
    /// Calcule le Checksum FIX standard (somme modulo 256 des octets)
    pub fn calculate_checksum(bytes: &[u8]) -> u32 {
        let sum: u32 = bytes.iter().map(|&b| b as u32).sum();
        sum % 256
    }

    /// Décode un message FIX brut représenté par une chaîne ou un flux d'octets.
    /// Accepte soit le délimiteur standard SOH (\x01), soit le pipe '|' pour faciliter les tests.
    pub fn parse(raw_input: &str) -> Result<FixMessage, FixError> {
        let trimmed = raw_input.trim();
        if trimmed.is_empty() {
            return Err(FixError::EmptyMessage);
        }

        // Détection du délimiteur utilisé (SOH ou |)
        let delimiter = if trimmed.contains(SOH) {
            SOH
        } else if trimmed.contains('|') {
            '|'
        } else {
            return Err(FixError::InvalidTagValue(trimmed.to_string()));
        };

        // Normalisation en bytes pour validation stricte du checksum et body length
        let delim_byte = delimiter as u8;
        let bytes = trimmed.as_bytes();

        // 1. Découpage tag=valeur
        let parts: Vec<&str> = trimmed
            .split(delimiter)
            .filter(|part| !part.is_empty())
            .collect();

        if parts.is_empty() {
            return Err(FixError::EmptyMessage);
        }

        let mut raw_fields = Vec::with_capacity(parts.len());
        for part in parts {
            let mut kv = part.splitn(2, '=');
            let tag_str = kv.next().ok_or_else(|| FixError::InvalidTagValue(part.to_string()))?;
            let val_str = kv.next().ok_or_else(|| FixError::InvalidTagValue(part.to_string()))?;

            let tag = u32::from_str(tag_str)
                .map_err(|_| FixError::InvalidTagNumber(tag_str.to_string()))?;

            raw_fields.push(FixField {
                tag,
                value: val_str.to_string(),
            });
        }

        if raw_fields.len() < 4 {
            return Err(FixError::MissingRequiredTag(35));
        }

        // 2. Validation de la séquence obligatoire de l'en-tête (Tags 8, 9, 35)
        if raw_fields[0].tag != 8 {
            return Err(FixError::InvalidHeaderBeginString(raw_fields[0].tag));
        }
        if raw_fields[1].tag != 9 {
            return Err(FixError::InvalidHeaderBodyLength(raw_fields[1].tag));
        }
        if raw_fields[2].tag != 35 {
            return Err(FixError::InvalidHeaderMsgType(raw_fields[2].tag));
        }

        // 3. Validation de la remorque (Dernier Tag = 10)
        let last_field = raw_fields.last().ok_or(FixError::EmptyMessage)?;
        if last_field.tag != 10 {
            return Err(FixError::InvalidTrailerCheckSum(last_field.tag));
        }

        let begin_string = raw_fields[0].value.clone();
        let body_length = usize::from_str(&raw_fields[1].value).map_err(|_| {
            FixError::TypeConversionError {
                tag: 9,
                field_name: "BodyLength",
                raw_value: raw_fields[1].value.clone(),
            }
        })?;
        let msg_type = raw_fields[2].value.clone();
        let expected_checksum = last_field.value.clone();

        // 4. Validation du Checksum (sur les octets précédant le tag 10)
        let tag10_pattern = format!("10={}", expected_checksum);
        if let Some(pos) = trimmed.rfind(&tag10_pattern) {
            let checksum_payload = &bytes[..pos];
            let actual_checksum = Self::calculate_checksum(checksum_payload);
            let actual_checksum_str = format!("{:03}", actual_checksum);

            if actual_checksum_str != expected_checksum {
                return Err(FixError::CheckSumMismatch {
                    expected: expected_checksum,
                    actual: actual_checksum_str,
                });
            }
        } else {
            return Err(FixError::MissingRequiredTag(10));
        }

        // 5. Validation du BodyLength (octets entre la fin du tag 9 et le début du tag 10)
        // Format: "8=...<delim>9=...<delim>[BODY]<delim>10=..."
        if let Some(first_delim) = bytes.iter().position(|&b| b == delim_byte) {
            let after_tag8 = &bytes[first_delim + 1..];
            if let Some(second_delim) = after_tag8.iter().position(|&b| b == delim_byte) {
                let body_start = first_delim + 1 + second_delim + 1;
                if let Some(checksum_pos) = trimmed.rfind(&tag10_pattern) {
                    let actual_body_len = checksum_pos.saturating_sub(body_start);
                    if actual_body_len != body_length {
                        return Err(FixError::BodyLengthMismatch {
                            expected: body_length,
                            actual: actual_body_len,
                        });
                    }
                }
            }
        }

        // Indexation des champs pour recherche O(1)
        let mut tag_map = HashMap::with_capacity(raw_fields.len());
        for (idx, field) in raw_fields.iter().enumerate() {
            tag_map.insert(field.tag, idx);
        }

        Ok(FixMessage {
            begin_string,
            body_length,
            msg_type,
            checksum: expected_checksum,
            fields: raw_fields,
            tag_map,
        })
    }
}

