#[derive(Debug, PartialEq)]
pub struct NewOrderSingle {
    pub cl_ord_id: String,
    pub symbol: String,
    pub side: Side,
    pub order_qty: u64,
    pub ord_type: OrdType,
    pub price: Option<f64>,
    pub transact_time: DateTime<Utc>,
}

impl TryFrom<&FixMessage> for NewOrderSingle {
    type Error = FixError;

    fn try_from(msg: &FixMessage) -> Result<Self, Self::Error> {
        if msg.msg_type != "D" {
            return Err(FixError::InvalidEnumValue(
                "MsgType for NewOrderSingle",
                msg.msg_type.clone(),
            ));
        }

        let cl_ord_id = msg.get_string(11, "ClOrdID")?;
        let symbol = msg.get_string(55, "Symbol")?;
        let side_char = msg.get_char(54, "Side")?;
        let side = Side::try_from(side_char)?;
        let order_qty = msg.get_u64(38, "OrderQty")?;
        let ord_type_char = msg.get_char(40, "OrdType")?;
        let ord_type = OrdType::try_from(ord_type_char)?;
        let transact_time = msg.get_timestamp(60, "TransactTime")?;

        let price = match ord_type {
            OrdType::Limit | OrdType::StopLimit => Some(msg.get_f64(44, "Price")?),
            OrdType::Market | OrdType::Stop => msg.get_f64(44, "Price").ok(),
        };

        Ok(NewOrderSingle {
            cl_ord_id,
            symbol,
            side,
            order_qty,
            ord_type,
            price,
            transact_time,
        })
    }
}

