#[cfg(test)]
mod tests {
    use super::*;


    #[test]
    fn test_valid_new_order_single_parsing() {
        // Tag 8, 9, 35 ... 10
        // Construit un message avec body length calculé correctement
        let body = "35=D|49=CLIENT|56=BROKER|34=101|52=20260928-10:00:00|11=ORD-999|55=EUR/USD|54=1|38=50000|40=2|44=1.0850|60=20260928-10:00:00|";
        let body_len = body.len();
        let header = format!("8=FIX.4.2|9={}|", body_len);
        let full_pre = format!("{}{}", header, body);
        let checksum = FixParser::calculate_checksum(full_pre.as_bytes());
        let raw = format!("{}10={:03}|", full_pre, checksum);

        let parsed = FixParser::parse(&raw).expect("Le parsing doit réussir");
        assert_eq!(parsed.begin_string, "FIX.4.2");
        assert_eq!(parsed.msg_type, "D");
        assert_eq!(parsed.get_string(11, "ClOrdID").unwrap(), "ORD-999");
        assert_eq!(parsed.get_u64(38, "OrderQty").unwrap(), 50000);
        assert_eq!(parsed.get_f64(44, "Price").unwrap(), 1.0850);

        let nos = NewOrderSingle::try_from(&parsed).expect("Conversion métier réussie");
        assert_eq!(nos.cl_ord_id, "ORD-999");
        assert_eq!(nos.symbol, "EUR/USD");
        assert_eq!(nos.side, Side::Buy);
        assert_eq!(nos.ord_type, OrdType::Limit);
        assert_eq!(nos.price, Some(1.0850));
    }

