    fn test_checksum_mismatch() {
        let raw = "8=FIX.4.2|9=12|35=0|34=1|49=A|56=B|10=000|";
        let res = FixParser::parse(raw);
        assert!(matches!(res, Err(FixError::CheckSumMismatch { .. })));
    }

    #[test]
    fn test_body_length_mismatch() {
        let body = "35=0|34=1|49=A|56=B|";
        let fake_body_len = 999;
        let header = format!("8=FIX.4.2|9={}|", fake_body_len);
        let full_pre = format!("{}{}", header, body);
        let checksum = FixParser::calculate_checksum(full_pre.as_bytes());
        let raw = format!("{}10={:03}|", full_pre, checksum);

        let res = FixParser::parse(&raw);
        assert!(matches!(res, Err(FixError::BodyLengthMismatch { .. })));
    }

    #[test]
    fn test_invalid_header_sequence() {
        let raw = "9=10|8=FIX.4.2|35=0|10=100|";
