// src/main.rs
use bm25_engine::{Bm25Error, Bm25Index, Bm25Params, Document};
use std::error::Error;

fn main() -> Result<(), Box<dyn Error>> {
    println!("============================================================");
    println!("   MOTEUR DE SCORING DOCUMENTAIRE BM25 (IN-MEMORY RUST)     ");
    println!("============================================================\n");

    // 1. Initialisation des paramètres de scoring (k1=1.2, b=0.75)
    let params = match Bm25Params::new(1.2, 0.75) {
        Ok(p) => p,
        Err(err) => {
            eprintln!("Erreur de configuration BM25: {}", err);
            return Err(Box::new(err));
        }
    };

    let mut index = Bm25Index::with_params(params);

    // 2. Préparation d'un corpus technique de démonstration
    let corpus = vec![
        Document::new(
            1,
            "Rust et la Sécurité Mémoire",
            "Rust élimine les bugs d'accès mémoire et les data races grâce à son système de possession (ownership) et d'emprunt (borrowing), sans nécessiter de garbage collector.",
        ),
        Document::new(
            2,
            "Programmation Concurrente Haute Performance",
            "La programmation concurrente en Rust permet d'exécuter plusieurs threads en toute sécurité. Les abstractions à coût nul (zero-cost abstractions) garantissent des performances optimales.",
        ),
        Document::new(
            3,
            "Recherche d'Information et Moteurs d'Indexation",
            "Les algorithmes TF-IDF et Okapi BM25 sont des références incontournables pour évaluer la pertinence documentaire dans les moteurs de recherche modernes.",
        ),
        Document::new(
            4,
            "Calcul Haute Performance en C++ et Rust",
            "C++ et Rust se disputent le domaine du calcul intensif et de l'ingénierie système, avec des fonctionnalités avancées d'optimisation mémoire et de vectorisation SIMD.",
        ),
        Document::new(
            5,
            "Architecture des Index Inversés",
            "Un index inversé associe chaque terme présent dans le corpus documentaire à la liste de ses occurrences et fréquences (postings), accélérant ainsi les requêtes de recherche.",
        ),
    ];

    // 3. Indexation des documents dans l'index en mémoire
    println!("[+] Indexation de {} documents en mémoire...", corpus.len());
    for doc in corpus {
        if let Err(e) = index.add_document(doc) {
            match e {
                Bm25Error::DuplicateDocument(id) => {
                    eprintln!("Avertissement: document {} ignoré car déjà présent.", id);
                }
                other => return Err(Box::new(other)),
            }
        }
    }

    println!("[✔] Indexation terminée.");
    println!("    - Total documents : {}", index.total_documents());
    println!("    - Longueur moyenne (avgdl) : {:.2} mots\n", index.avg_doc_length());

    // 4. Scénarios de recherche de test
    let test_queries = [
        "sécurité mémoire rust",
        "index inversé recherche",
        "concurrence threads haute performance",
        "terme_inexistant",
    ];

    for (i, query) in test_queries.iter().enumerate() {
        println!("------------------------------------------------------------");
        println!("Requête #{}: \"{}\"", i + 1, query);
        println!("------------------------------------------------------------");

        let results = index.search(query, 3);

        if results.is_empty() {
            println!("  [i] Aucun document correspondant trouvé.\n");
            continue;
        }

        for (rank, res) in results.iter().enumerate() {
            println!(
                "  #{:<2} [Score: {:>6.4}] [Doc ID: {}] {}",
                rank + 1,
                res.score,
                res.doc_id,
                res.title
            );
            println!("      Termes concordants : {:?}", res.matched_terms);
            println!("      Extrait            : {}\n", res.snippet);
        }

        // Explication détaillée du score pour le premier résultat
        if let Some(top_result) = results.first() {
            if let Ok(explanation) = index.explain(query, top_result.doc_id) {
                println!("  [Détails du score pour le document #{}]", top_result.doc_id);
                println!(
                    "  Longueur doc: {} mots | avgdl: {:.2} mots | Score total: {:.4}",
                    explanation.doc_length, explanation.avg_doc_length, explanation.total_score
                );
                for term_exp in &explanation.terms {
                    if term_exp.term_frequency > 0 {
                        println!(
                            "    - Terme '{}' : TF = {}, IDF = {:.4} => Contribution = {:.4}",
                            term_exp.term,
                            term_exp.term_frequency,
                            term_exp.idf,
                            term_exp.score_contribution
                        );
                    }
                }
                println!();
            }
        }
    }

    println!("============================================================");
    println!("   Démonstration terminée avec succès.                      ");
    println!("============================================================");

    Ok(())
}

