```rust
// src/main.rs
use std::fmt;
use thiserror::Error;

/// Nombre de registres généraux dans le banc de registres.
pub const NUM_REGISTERS: usize = 8;
/// Taille de la mémoire adressable en mots de 16 bits.
pub const MEMORY_SIZE: usize = 4096;

/// Erreurs possibles lors de l'exécution du processeur RISC.
#[derive(Debug, Error, PartialEq, Eq)]
pub enum CpuError {
    #[error("Adresse mémoire hors limites : 0x{0:04X}")]
    MemoryOutOfBounds(usize),
    #[error("Numéro de registre invalide : {0}")]
    InvalidRegister(u8),
    #[error("Opcode inconnu ou non supporté : 0x{0:X}")]
    UnknownOpcode(u8),
    #[error("Instruction invalide : {0}")]
    InvalidInstruction(String),
    #[error("Le CPU est déjà arrêté (HALT)")]
    Halted,
}

/// Identifiant d'un registre général (R0 à R7).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RegId(pub u8);

impl RegId {
    pub fn new(index: u8) -> Result<Self, CpuError> {
        if (index as usize) < NUM_REGISTERS {
            Ok(Self(index))
        } else {
            Err(CpuError::InvalidRegister(index))
        }
    }

    pub fn index(self) -> usize {
        self.0 as usize
    }
}

impl fmt::Display for RegId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "R{}", self.0)
    }
}

/// Drapeaux d'état du CPU (Flags).
#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub struct Flags {
    /// Drapeau Zéro : mis à 1 si le résultat de l'opération vaut 0.
    pub zero: bool,
    /// Drapeau Retenue (Carry) : mis à 1 en cas de dépassement d'entier non signé.
    pub carry: bool,
    /// Drapeau Négatif : mis à 1 si le bit de poids fort du résultat est 1.
    pub negative: bool,
}

impl fmt::Display for Flags {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "[Z: {}, C: {}, N: {}]",
            if self.zero { "1" } else { "0" },
            if self.carry { "1" } else { "0" },
            if self.negative { "1" } else { "0" }
        )
    }
}

/// Banc de registres (Register File).
#[derive(Debug, Clone)]
pub struct RegisterFile {
    /// R0 est câblé à zéro de manière matérielle.
    regs: [u16; NUM_REGISTERS],
}

impl Default for RegisterFile {
    fn default() -> Self {
        Self {
            regs: [0; NUM_REGISTERS],
        }
    }
}

impl RegisterFile {
    pub fn new() -> Self {
        Self::default()
    }

    /// Lit la valeur d'un registre. R0 retourne toujours 0.
    pub fn read(&self, reg: RegId) -> u16 {
        if reg.0 == 0 {
            0
        } else {
            self.regs[reg.index()]
        }
    }

    /// Écrit une valeur dans un registre. Les écritures dans R0 sont ignorées.
    pub fn write(&mut self, reg: RegId, val: u16) {
        if reg.0 != 0 {
            self.regs[reg.index()] = val;
        }
    }
}

/// Jeu d'instructions décodé du processeur RISC.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Instruction {
    /// Ne fait rien.
    Nop,
    /// LOADI Rd, Imm9 : Charge une valeur immédiate de 9 bits dans Rd.
    Loadi { rd: RegId, imm: u16 },
    /// ADD Rd, Rs1, Rs2 : Rd = Rs1 + Rs2
    Add { rd: RegId, rs1: RegId, rs2: RegId },
    /// SUB Rd, Rs1, Rs2 : Rd = Rs1 - Rs2
    Sub { rd: RegId, rs1: RegId, rs2: RegId },
    /// AND Rd, Rs1, Rs2 : Rd = Rs1 & Rs2
    And { rd: RegId, rs1: RegId, rs2: RegId },
    /// OR Rd, Rs1, Rs2 : Rd = Rs1 | Rs2
    Or { rd: RegId, rs1: RegId, rs2: RegId },
    /// XOR Rd, Rs1, Rs2 : Rd = Rs1 ^ Rs2
    Xor { rd: RegId, rs1: RegId, rs2: RegId },
    /// LOAD Rd, [Rs1] : Charge la valeur en mémoire pointée par Rs1 dans Rd.
    Load { rd: RegId, rs_addr: RegId },
    /// STORE [Rs1], Rs2 : Écrit la valeur Rs2 à l'adresse mémoire pointée par Rs1.
    Store { rs_addr: RegId, rs_val: RegId },
    /// JMP Rs1 : Saut inconditionnel à l'adresse contenue dans Rs1.
    Jmp { rs_target: RegId },
    /// JZ Imm9 : Saut à l'adresse immédiate absolue si le flag Zero est actif.
    Jz { target: u16 },
    /// HALT : Arrête le processeur.
    Halt,
}

impl Instruction {
    /// Encode une instruction en mot machine 16 bits.
    pub fn encode(self) -> u16 {
        match self {
            Instruction::Nop => 0x0000,
            Instruction::Loadi { rd, imm } => {
                0x1000 | ((rd.0 as u16 & 0x7) << 9) | (imm & 0x01FF)
            }
            Instruction::Add { rd, rs1, rs2 } => {
                0x2000 | ((rd.0 as u16 & 0x7) << 9) | ((rs1.0 as u16 & 0x7) << 6) | ((rs2.0 as u16 & 0x7) << 3)
            }
            Instruction::Sub { rd, rs1, rs2 } => {
                0x3000 | ((rd.0 as u16 & 0x7) << 9) | ((rs1.0 as u16 & 0x7) << 6) | ((rs2.0 as u16 & 0x7) << 3)
            }
            Instruction::And { rd, rs1, rs2 } => {
                0x4000 | ((rd.0 as u16 & 0x7) << 9) | ((rs1.0 as u16 & 0x7) << 6) | ((rs2.0 as u16 & 0x7) << 3)
            }
            Instruction::Or { rd, rs1, rs2 } => {
                0x5000 | ((rd.0 as u16 & 0x7) << 9) | ((rs1.0 as u16 & 0x7) << 6) | ((rs2.0 as u16 & 0x7) << 3)
            }
            Instruction::Xor { rd, rs1, rs2 } => {
                0x6000 | ((rd.0 as u16 & 0x7) << 9) | ((rs1.0 as u16 & 0x7) << 6) | ((rs2.0 as u16 & 0x7) << 3)
            }
            Instruction::Load { rd, rs_addr } => {
                0x7000 | ((rd.0 as u16 & 0x7) << 9) | ((rs_addr.0 as u16 & 0x7) << 6)
            }
            Instruction::Store { rs_addr, rs_val } => {
                0x8000 | ((rs_addr.0 as u16 & 0x7) << 6) | ((rs_val.0 as u16 & 0x7) << 3)
            }
            Instruction::Jmp { rs_target } => {
                0x9000 | ((rs_target.0 as u16 & 0x7) << 6)
            }
            Instruction::Jz { target } => {
                0xA000 | (target & 0x01FF)
            }
            Instruction::Halt => 0xF000,
        }
    }
}

impl fmt::Display for Instruction {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Instruction::Nop => write!(f, "NOP"),
            Instruction::Loadi { rd, imm } => write!(f, "LOADI {}, #0x{:03X}", rd, imm),
            Instruction::Add { rd, rs1, rs2 } => write!(f, "ADD {}, {}, {}", rd, rs1, rs2),
            Instruction::Sub { rd, rs1, rs2 } => write!(f, "SUB {}, {}, {}", rd, rs1, rs2),
            Instruction::And { rd, rs1, rs2 } => write!(f, "AND {}, {}, {}", rd, rs1, rs2),
            Instruction::Or { rd, rs1, rs2 } => write!(f, "OR {}, {}, {}", rd, rs1, rs2),
            Instruction::Xor { rd, rs1, rs2 } => write!(f, "XOR {}, {}, {}", rd, rs1, rs2),
            Instruction::Load { rd, rs_addr } => write!(f, "LOAD {}, [{}]", rd, rs_addr),
            Instruction::Store { rs_addr, rs_val } => write!(f, "STORE [{}], {}", rs_addr, rs_val),
            Instruction::Jmp { rs_target } => write!(f, "JMP {}", rs_target),
            Instruction::Jz { target } => write!(f, "JZ 0x{:03X}", target),
            Instruction::Halt => write!(f, "HALT"),
        }
    }
}

/// Mémoire du système (tableau de mots 16 bits).
pub struct Memory {
    cells: [u16; MEMORY_SIZE],
}

impl Default for Memory {
    fn default() -> Self {
        Self {
            cells: [0; MEMORY_SIZE],
        }
    }
}

impl Memory {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn read(&self, addr: usize) -> Result<u16, CpuError> {
        self.cells
            .get(addr)
            .copied()
            .ok_or(CpuError::MemoryOutOfBounds(addr))
    }

    pub fn write(&mut self, addr: usize, value: u16) -> Result<(), CpuError> {
        let cell = self
            .cells
            .get_mut(addr)
            .ok_or(CpuError::MemoryOutOfBounds(addr))?;
        *cell = value;
        Ok(())
    }

    pub fn load_program(&mut self, start_addr: usize, program: &[u16]) -> Result<(), CpuError> {
        if start_addr + program.len() > MEMORY_SIZE {
            return Err(CpuError::MemoryOutOfBounds(start_addr + program.len()));
        }
        for (i, &word) in program.iter().enumerate() {
            self.cells[start_addr + i] = word;
        }
        Ok(())
    }
}

/// Simulateur de Processeur RISC avec cycle Fetch-Decode-Execute.
pub struct Cpu {
    pub registers: RegisterFile,
    pub pc: u16,
    pub flags: Flags,
    pub memory: Memory,
    pub is_halted: bool,
    pub cycle_count: u64,
}

impl Default for Cpu {
    fn default() -> Self {
        Self {
            registers: RegisterFile::new(),
            pc: 0,
            flags: Flags::default(),
            memory: Memory::new(),
            is_halted: false,
            cycle_count: 0,
        }
    }
}

impl Cpu {
    pub fn new() -> Self {
        Self::default()
    }

    /// Charge un programme binaire en mémoire à l'adresse de départ donnée.
    pub fn load_program(&mut self, start_addr: u16, program: &[u16]) -> Result<(), CpuError> {
        self.memory.load_program(start_addr as usize, program)?;
        self.pc = start_addr;
        self.is_halted = false;
        Ok(())
    }

    /// Étape 1 : FETCH
    /// Récupère le mot d'instruction à l'adresse pointée par le Program Counter (PC)
    /// et incrémente le PC.
    pub fn fetch(&mut self) -> Result<u16, CpuError> {
        if self.is_halted {
            return Err(CpuError::Halted);
        }
        let word = self.memory.read(self.pc as usize)?;
        self.pc = self.pc.wrapping_add(1);
        Ok(word)
    }

    /// Étape 2 : DECODE
    /// Décompose le mot 16 bits en opcodes et opérandes pour instancier une `Instruction`.
    pub fn decode(&self, raw: u16) -> Result<Instruction, CpuError> {
        let opcode = ((raw >> 12) & 0xF) as u8;
        let rd_idx = ((raw >> 9) & 0x7) as u8;
        let rs1_idx = ((raw >> 6) & 0x7) as u8;
        let rs2_idx = ((raw >> 3) & 0x7) as u8;
        let imm9 = raw & 0x01FF;

        match opcode {
            0x0 => Ok(Instruction::Nop),
            0x1 => Ok(Instruction::Loadi {
                rd: RegId::new(rd_idx)?,
                imm: imm9,
            }),
            0x2 => Ok(Instruction::Add {
                rd: RegId::new(rd_idx)?,
                rs1: RegId::new(rs1_idx)?,
                rs2: RegId::new(rs2_idx)?,
            }),
            0x3 => Ok(Instruction::Sub {
                rd: RegId::new(rd_idx)?,
                rs1: RegId::new(rs1_idx)?,
                rs2: RegId::new(rs2_idx)?,
            }),
            0x4 => Ok(Instruction::And {
                rd: RegId::new(rd_idx)?,
                rs1: RegId::new(rs1_idx)?,
                rs2: RegId::new(rs2_idx)?,
            }),
            0x5 => Ok(Instruction::Or {
                rd: RegId::new(rd_idx)?,
                rs1: RegId::new(rs1_idx)?,
                rs2: RegId::new(rs2_idx)?,
            }),
            0x6 => Ok(Instruction::Xor {
                rd: RegId::new(rd_idx)?,
                rs1: RegId::new(rs1_idx)?,
                rs2: RegId::new(rs2_idx)?,
            }),
            0x7 => Ok(Instruction::Load {
                rd: RegId::new(rd_idx)?,
                rs_addr: RegId::new(rs1_idx)?,
            }),
            0x8 => Ok(Instruction::Store {
                rs_addr: RegId::new(rs1_idx)?,
                rs_val: RegId::new(rs2_idx)?,
            }),
            0x9 => Ok(Instruction::Jmp {
                rs_target: RegId::new(rs1_idx)?,
            }),
            0xA => Ok(Instruction::Jz { target: imm9 }),
            0xF => Ok(Instruction::Halt),
            other => Err(CpuError::UnknownOpcode(other)),
        }
    }

    /// Étape 3 : EXECUTE
    /// Exécute l'instruction décodée, met à jour les registres, la mémoire et les flags.
    pub fn execute(&mut self, instr: Instruction) -> Result<(), CpuError> {
        match instr {
            Instruction::Nop => {}
            Instruction::Loadi { rd, imm } => {
                self.registers.write(rd, imm);
            }
            Instruction::Add { rd, rs1, rs2 } => {
                let v1 = self.registers.read(rs1);
                let v2 = self.registers.read(rs2);
                let (res, carry) = v1.overflowing_add(v2);
                self.update_flags(res, carry);
                self.registers.write(rd, res);
            }
            Instruction::Sub { rd, rs1, rs2 } => {
                let v1 = self.registers.read(rs1);
                let v2 = self.registers.read(rs2);
                let (res, borrow) = v1.overflowing_sub(v2);
                self.update_flags(res, borrow);
                self.registers.write(rd, res);
            }
            Instruction::And { rd, rs1, rs2 } => {
                let res = self.registers.read(rs1) & self.registers.read(rs2);
                self.update_flags(res, false);
                self.registers.write(rd, res);
            }
            Instruction::Or { rd, rs1, rs2 } => {
                let res = self.registers.read(rs1) | self.registers.read(rs2);
                self.update_flags(res, false);
                self.registers.write(rd, res);
            }
            Instruction::Xor { rd, rs1, rs2 } => {
                let res = self.registers.read(rs1) ^ self.registers.read(rs2);
                self.update_flags(res, false);
                self.registers.write(rd, res);
            }
            Instruction::Load { rd, rs_addr } => {
                let addr = self.registers.read(rs_addr) as usize;
                let val = self.memory.read(addr)?;
                self.registers.write(rd, val);
            }
            Instruction::Store { rs_addr, rs_val } => {
                let addr = self.registers.read(rs_addr) as usize;
                let val = self.registers.read(rs_val);
                self.memory.write(addr, val)?;
            }
            Instruction::Jmp { rs_target } => {
                self.pc = self.registers.read(rs_target);
            }
            Instruction::Jz { target } => {
                if self.flags.zero {
                    self.pc = target;
                }
            }
            Instruction::Halt => {
                self.is_halted = true;
            }
        }
        self.cycle_count += 1;
        Ok(())
    }

    /// Exécute un cycle complet : Fetch -> Decode -> Execute.
    pub fn step(&mut self) -> Result<Option<Instruction>, CpuError> {
        if self.is_halted {
            return Ok(None);
        }
        let raw = self.fetch()?;
        let instr = self.decode(raw)?;
        self.execute(instr)?;
        Ok(Some(instr))
    }

    /// Exécute le CPU jusqu'à l'arrêt (HALT) ou jusqu'à atteindre un nombre maximal d'instructions.
    pub fn run(&mut self, max_cycles: u64) -> Result<u64, CpuError> {
        let mut count = 0;
        while !self.is_halted && count < max_cycles {
            self.step()?;
            count += 1;
        }
        Ok(count)
    }

    fn update_flags(&mut self, result: u16, carry: bool) {
        self.flags.zero = result == 0;
        self.flags.carry = carry;
        self.flags.negative = (result & 0x8000) != 0;
    }

    /// Affiche un état lisible du banc de registres et des flags.
    pub fn dump_state(&self) {
        println!("┌──────────────────────────────────────────────────────────┐");
        println!(
            "│ PC: 0x{:04X} | Cycles: {:<6} | Flags: {:<17} │",
            self.pc, self.cycle_count, self.flags
        );
        println!("├──────────────────────────────────────────────────────────┤");
        print!("│ ");
        for i in 0..NUM_REGISTERS {
            let reg = RegId(i as u8);
            print!("{}: 0x{:04X} ", reg, self.registers.read(reg));
            if i == 3 {
                print!("│\n│ ");
            }
        }
        println!("│");
        println!("└──────────────────────────────────────────────────────────┘");
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("=== Simulateur de Processeur RISC Simplifié ===");
    println!("Initialisation du CPU et chargement du programme de démonstration...\n");

    let mut cpu = Cpu::new();

    // Démonstration : calcul de la somme 5 + 4 + 3 + 2 + 1 (somme arithmétique / boucle à rebours)
    //
    // Registres utilisés :
    // R1 = accumulateur (somme, commence à 0)
    // R2 = compteur décrémenté (initialisé à 5)
    // R3 = constante 1 pour décrémenter
    // R4 = adresse pour stocker le résultat final en mémoire (0x0080)
    //
    // Programme :
    // [0x00] LOADI R1, #0        ; somme = 0
    // [0x01] LOADI R2, #5        ; compteur = 5
    // [0x02] LOADI R3, #1        ; un = 1
    // [0x03] LOADI R4, #0x080    ; adresse mémoire de sortie
    // Boucle:
    // [0x04] ADD   R1, R1, R2    ; somme = somme + compteur
    // [0x05] SUB   R2, R2, R3    ; compteur = compteur - 1 (met à jour le flag Zero quand R2 devient 0)
    // [0x06] JZ    0x008         ; si compteur == 0, saute à Fin
    // [0x07] LOADI R5, #0x004    ; adresse de début de boucle
    //        (R0 câblé à 0 permet aussi des sauts relatifs, ici saut direct via registre)
    //        JMP   R5
    // Fin:
    // [0x08] STORE [R4], R1      ; écriture du résultat à l'adresse 0x0080
    // [0x09] HALT                ; arrêt du CPU

    let reg = |idx: u8| -> RegId { RegId::new(idx).expect("Registre statique valide") };

    let program: Vec<Instruction> = vec![
        Instruction::Loadi { rd: reg(1), imm: 0 },
        Instruction::Loadi { rd: reg(2), imm: 5 },
        Instruction::Loadi { rd: reg(3), imm: 1 },
        Instruction::Loadi { rd: reg(4), imm: 0x080 },
        Instruction::Add   { rd: reg(1), rs1: reg(1), rs2: reg(2) },
        Instruction::Sub   { rd: reg(2), rs1: reg(2), rs2: reg(3) },
        Instruction::Jz    { target: 0x009 },
        Instruction::Loadi { rd: reg(5), imm: 0x004 },
        Instruction::Jmp   { rs_target: reg(5) },
        Instruction::Store { rs_addr: reg(4), rs_val: reg(1) },
        Instruction::Halt,
    ];

    let binary: Vec<u16> = program.iter().map(|inst| inst.encode()).collect();

    // Chargement du binaire à l'adresse 0x0000
    cpu.load_program(0x0000, &binary)?;

    println!("Programme assemblé chargé en mémoire (longueur : {} mots) :", binary.len());
    for (i, (instr, code)) in program.iter().zip(&binary).enumerate() {
        println!("  [0x{:04X}]  0x{:04X}  => {}", i, code, instr);
    }
    println!("\n--- Début de l'exécution pas-à-pas ---");

    while !cpu.is_halted {
        let current_pc = cpu.pc;
        match cpu.step()? {
            Some(instr) => {
                println!("\nCycle #{:<3} | Exécuté à 0x{:04X}: {}", cpu.cycle_count, current_pc, instr);
                cpu.dump_state();
            }
            None => break,
        }
    }

    println!("\n=== Exécution terminée avec succès ===");
    println!("Total cycles CPU : {}", cpu.cycle_count);

    // Vérification du résultat en mémoire
    let res_mem = cpu.memory.read(0x0080)?;
    let res_r1 = cpu.registers.read(reg(1));
    println!("Résultat final attendu dans R1 : 15 (0x{:04X})", res_r1);
    println!("Valeur persistée en mémoire [0x0080] : 0x{:04X}", res_mem);

    assert_eq!(res_r1, 15, "Le calcul de R1 doit valoir 15");
    assert_eq!(res_mem, 15, "La valeur en mémoire à l'adresse 0x0080 doit valoir 15");

    println!("\nTests de cohérence validés !");
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_register_zero_is_hardwired() {
        let mut rf = RegisterFile::new();
        let r0 = RegId::new(0).unwrap();
        let r1 = RegId::new(1).unwrap();

        assert_eq!(rf.read(r0), 0);
        rf.write(r0, 0x1234);
        assert_eq!(rf.read(r0), 0, "R0 doit toujours rester à 0");

        rf.write(r1, 0x4321);
        assert_eq!(rf.read(r1), 0x4321);
    }

    #[test]
    fn test_fetch_decode_execute_add() {
        let mut cpu = Cpu::new();
        let r1 = RegId::new(1).unwrap();
        let r2 = RegId::new(2).unwrap();
        let r3 = RegId::new(3).unwrap();

        let program = vec![
            Instruction::Loadi { rd: r1, imm: 10 }.encode(),
            Instruction::Loadi { rd: r2, imm: 25 }.encode(),
            Instruction::Add { rd: r3, rs1: r1, rs2: r2 }.encode(),
            Instruction::Halt.encode(),
        ];

        cpu.load_program(0, &program).unwrap();
        cpu.run(100).unwrap();

        assert_eq!(cpu.registers.read(r3), 35);
        assert!(!cpu.flags.zero);
        assert!(!cpu.flags.carry);
    }

    #[test]
    fn test_sub_and_zero_flag() {
        let mut cpu = Cpu::new();
        let r1 = RegId::new(1).unwrap();
        let r2 = RegId::new(2).unwrap();

        let program = vec![
            Instruction::Loadi { rd: r1, imm: 42 }.encode(),
            Instruction::Loadi { rd: r2, imm: 42 }.encode(),
            Instruction::Sub { rd: r1, rs1: r1, rs2: r2 }.encode(),
            Instruction::Halt.encode(),
        ];

        cpu.load_program(0, &program).unwrap();
        cpu.run(10).unwrap();

        assert_eq!(cpu.registers.read(r1), 0);
        assert!(cpu.flags.zero);
    }

    #[test]
    fn test_memory_load_store() {
        let mut cpu = Cpu::new();
        let r1 = RegId::new(1).unwrap();
        let r2 = RegId::new(2).unwrap();
        let r3 = RegId::new(3).unwrap();

        let program = vec![
            Instruction::Loadi { rd: r1, imm: 0x0100 }.encode(), // Adresse
            Instruction::Loadi { rd: r2, imm: 0x00FF }.encode(), // Donnée
            Instruction::Store { rs_addr: r1, rs_val: r2 }.encode(),
            Instruction::Load { rd: r3, rs_addr: r1 }.encode(),
            Instruction::Halt.encode(),
        ];

        cpu.load_program(0, &program).unwrap();
        cpu.run(10).unwrap();

        assert_eq!(cpu.memory.read(0x0100).unwrap(), 0x00FF);
        assert_eq!(cpu.registers.read(r3), 0x00FF);
    }
}

