    #[test]
    fn test_endianness_and_records() {
        let schema = LogSchema {
            name: "TestSchema".to_string(),
            version: 1,
            endianness: Endianness::Little,
            header: None,
            record: vec![
                FieldDef {
                    name: "id".to_string(),
                    data_type: FieldType::U32,
                },
                FieldDef {
                    name: "val".to_string(),
                    data_type: FieldType::F32,
                },
                FieldDef {
                    name: "flag".to_string(),
                    data_type: FieldType::Bool,
                },
            ],
        };

        let mut buffer = Vec::new();
        buffer.write_u32::<LittleEndian>(42).expect("write u32");
        buffer.write_f32::<LittleEndian>(3.14).expect("write f32");
        buffer.write_u8(1).expect("write bool");

        let mut reader = BinaryLogReader::new(Cursor::new(buffer), schema);
        let rec = reader.next_record().expect("read").expect("must exist");

        match rec.get("id").unwrap() {
            ParsedValue::U64(v) => assert_eq!(*v, 42),
            _ => panic!("Expected U64"),
        }
        match rec.get("flag").unwrap() {
            ParsedValue::Bool(b) => assert_eq!(*b, true),
            _ => panic!("Expected Bool"),
        }
    }
}

