```rust
// src/main.rs
use std::collections::BTreeMap;
use std::fs::File;
use std::io::{self, BufReader, BufWriter, Read, Write};
use std::path::{Path, PathBuf};

use byteorder::{BigEndian, LittleEndian, ReadBytesExt, WriteBytesExt};
use chrono::{DateTime, Utc};
use clap::{Parser, Subcommand};
use serde::{Deserialize, Serialize};
use thiserror::Error;

/// Erreurs spécifiques au parseur de logs binaires
#[derive(Debug, Error)]
pub enum ParserError {
    #[error("Erreur I/O: {0}")]
    Io(#[from] io::Error),

    #[error("Erreur de désérialisation du schéma: {0}")]
    SchemaError(String),

    #[error("Nombre magique invalide. Attendu: {expected:02X?}, Trouvé: {actual:02X?}")]
    InvalidMagic {
        expected: Vec<u8>,
        actual: Vec<u8>,
    },

    #[error("Type de données non supporté pour la lecture: {0}")]
    UnsupportedType(String),

    #[error("Erreur de chaîne UTF-8 invalide: {0}")]
    Utf8Error(#[from] std::string::FromUtf8Error),

    #[error("Fin de fichier inattendue lors de la lecture du champ '{field}' (offset ~{offset})")]
    UnexpectedEof { field: String, offset: u64 },
}

/// Endianness supportée
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Endianness {
    Little,
    Big,
}

/// Type de préfixe de taille pour les chaînes dynamiques
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum LengthPrefix {
    U8,
    U16,
    U32,
}

/// Définition d'un type de champ dans le schéma
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum FieldType {
    U8,
    U16,
    U32,
    U64,
    I8,
    I16,
    I32,
    I64,
    F32,
    F64,
    Bool,
    FixedString { length: usize },
    PrefixString { prefix: LengthPrefix },
    NullTerminatedString { max_len: Option<usize> },
    FixedBytes { length: usize },
    TimestampMs,
    TimestampSec,
}

/// Définition d'un champ
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FieldDef {
    pub name: String,
    #[serde(flatten)]
    pub data_type: FieldType,
}

/// En-tête optionnel de fichier binaire
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct HeaderDef {
    /// Nombre magique hexadécimal (ex: "4C4F4731" pour "LOG1")
    pub magic: Option<String>,
    #[serde(default)]
    pub fields: Vec<FieldDef>,
}

/// Schéma complet du format de journal binaire
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LogSchema {
    pub name: String,
    pub version: u32,
    pub endianness: Endianness,
    #[serde(default)]
    pub header: Option<HeaderDef>,
    pub record: Vec<FieldDef>,
}

impl LogSchema {
    /// Charge un schéma à partir d'un fichier YAML ou JSON
    pub fn load_from_file<P: AsRef<Path>>(path: P) -> Result<Self, ParserError> {
        let content = std::fs::read_to_string(path.as_ref())?;
        let ext = path
            .as_ref()
            .extension()
            .and_then(|s| s.to_str())
            .unwrap_or("");

        if ext.eq_ignore_ascii_case("json") {
            serde_json::from_str(&content)
                .map_err(|e| ParserError::SchemaError(format!("JSON: {e}")))
        } else {
            // Par défaut, parser en YAML
            serde_yaml::from_str(&content)
                .map_err(|e| ParserError::SchemaError(format!("YAML: {e}")))
        }
    }
}

/// Valeur parsée d'un champ
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(untagged)]
pub enum ParsedValue {
    U64(u64),
    I64(i64),
    F64(f64),
    Bool(bool),
    String(String),
    Bytes(Vec<u8>),
    DateTime(String),
}

/// Enregistrement binaire décodé sous forme de dictionnaire clé-valeur
pub type Record = BTreeMap<String, ParsedValue>;

/// Lecteur de log binaire basé sur un schéma
pub struct BinaryLogReader<R: Read> {
    reader: R,
    schema: LogSchema,
    bytes_read: u64,
}

impl<R: Read> BinaryLogReader<R> {
    pub fn new(reader: R, schema: LogSchema) -> Self {
        Self {
            reader,
            schema,
            bytes_read: 0,
        }
    }

    /// Lit et valide l'en-tête de fichier si défini dans le schéma
    pub fn read_header(&mut self) -> Result<Option<Record>, ParserError> {
        let header_def = match &self.schema.header {
            Some(h) => h,
            None => return Ok(None),
        };

        // 1. Validation du magic number
        if let Some(magic_hex) = &header_def.magic {
            let clean_hex = magic_hex.trim_start_matches("0x").replace(' ', "");
            let expected_bytes = hex_decode(&clean_hex).map_err(|e| {
                ParserError::SchemaError(format!("Magic number hex invalide: {e}"))
            })?;

            let mut actual_bytes = vec![0u8; expected_bytes.len()];
            self.reader.read_exact(&mut actual_bytes)?;
            self.bytes_read += actual_bytes.len() as u64;

            if actual_bytes != expected_bytes {
                return Err(ParserError::InvalidMagic {
                    expected: expected_bytes,
                    actual: actual_bytes,
                });
            }
        }

        // 2. Décodage des champs de l'en-tête
        if header_def.fields.is_empty() {
            return Ok(None);
        }

        let mut header_data = BTreeMap::new();
        for field in &header_def.fields {
            let val = Self::read_field_data(&mut self.reader, &mut self.bytes_read, self.schema.endianness, field)?;
            header_data.insert(field.name.clone(), val);
        }

        Ok(Some(header_data))
    }

    /// Tente de lire le prochain enregistrement. Renvoie Ok(None) à la fin propre du flux.
    pub fn next_record(&mut self) -> Result<Option<Record>, ParserError> {
        if self.schema.record.is_empty() {
            return Ok(None);
        }

        let mut record = BTreeMap::new();
        let mut first = true;

        for field in &self.schema.record {
            let res = Self::read_field_data(&mut self.reader, &mut self.bytes_read, self.schema.endianness, field);
            match res {
                Ok(val) => {
                    first = false;
                    record.insert(field.name.clone(), val);
                }
                Err(ParserError::Io(ref e)) if e.kind() == io::ErrorKind::UnexpectedEof => {
                    // Si on rencontre EOF avant le premier champ d'un enregistrement, c'est une fin propre
                    if first {
                        return Ok(None);
                    } else {
                        return Err(ParserError::UnexpectedEof {
                            field: field.name.clone(),
                            offset: self.bytes_read,
                        });
                    }
                }
                Err(e) => return Err(e),
            }
        }

        Ok(Some(record))
    }

    fn read_field_data(
        reader: &mut R,
        bytes_read: &mut u64,
        endian: Endianness,
        field: &FieldDef,
    ) -> Result<ParsedValue, ParserError> {
        let value = match &field.data_type {
            FieldType::U8 => {
                let v = reader.read_u8()?;
                *bytes_read += 1;
                ParsedValue::U64(v as u64)
            }
            FieldType::U16 => {
                let v = match endian {
                    Endianness::Little => reader.read_u16::<LittleEndian>()?,
                    Endianness::Big => reader.read_u16::<BigEndian>()?,
                };
                *bytes_read += 2;
                ParsedValue::U64(v as u64)
            }
            FieldType::U32 => {
                let v = match endian {
                    Endianness::Little => reader.read_u32::<LittleEndian>()?,
                    Endianness::Big => reader.read_u32::<BigEndian>()?,
                };
                *bytes_read += 4;
                ParsedValue::U64(v as u64)
            }
            FieldType::U64 => {
                let v = match endian {
                    Endianness::Little => reader.read_u64::<LittleEndian>()?,
                    Endianness::Big => reader.read_u64::<BigEndian>()?,
                };
                *bytes_read += 8;
                ParsedValue::U64(v)
            }
            FieldType::I8 => {
                let v = reader.read_i8()?;
                *bytes_read += 1;
                ParsedValue::I64(v as i64)
            }
            FieldType::I16 => {
                let v = match endian {
                    Endianness::Little => reader.read_i16::<LittleEndian>()?,
                    Endianness::Big => reader.read_i16::<BigEndian>()?,
                };
                *bytes_read += 2;
                ParsedValue::I64(v as i64)
            }
            FieldType::I32 => {
                let v = match endian {
                    Endianness::Little => reader.read_i32::<LittleEndian>()?,
                    Endianness::Big => reader.read_i32::<BigEndian>()?,
                };
                *bytes_read += 4;
                ParsedValue::I64(v as i64)
            }
            FieldType::I64 => {
                let v = match endian {
                    Endianness::Little => reader.read_i64::<LittleEndian>()?,
                    Endianness::Big => reader.read_i64::<BigEndian>()?,
                };
                *bytes_read += 8;
                ParsedValue::I64(v)
            }
            FieldType::F32 => {
                let v = match endian {
                    Endianness::Little => reader.read_f32::<LittleEndian>()?,
                    Endianness::Big => reader.read_f32::<BigEndian>()?,
                };
                *bytes_read += 4;
                ParsedValue::F64(v as f64)
            }
            FieldType::F64 => {
                let v = match endian {
                    Endianness::Little => reader.read_f64::<LittleEndian>()?,
                    Endianness::Big => reader.read_f64::<BigEndian>()?,
                };
                *bytes_read += 8;
                ParsedValue::F64(v)
            }
            FieldType::Bool => {
                let b = reader.read_u8()?;
                *bytes_read += 1;
                ParsedValue::Bool(b != 0)
            }
            FieldType::FixedString { length } => {
                let mut buf = vec![0u8; *length];
                reader.read_exact(&mut buf)?;
                *bytes_read += *length as u64;
                // Retire les trailing 0s éventuels
                let end = buf.iter().position(|&c| c == 0).unwrap_or(buf.len());
                let s = String::from_utf8_lossy(&buf[..end]).into_owned();
                ParsedValue::String(s)
            }
            FieldType::PrefixString { prefix } => {
                let len = match prefix {
                    LengthPrefix::U8 => reader.read_u8()? as usize,
                    LengthPrefix::U16 => match endian {
                        Endianness::Little => reader.read_u16::<LittleEndian>()? as usize,
                        Endianness::Big => reader.read_u16::<BigEndian>()? as usize,
                    },
                    LengthPrefix::U32 => match endian {
                        Endianness::Little => reader.read_u32::<LittleEndian>()? as usize,
                        Endianness::Big => reader.read_u32::<BigEndian>()? as usize,
                    },
                };
                *bytes_read += match prefix {
                    LengthPrefix::U8 => 1,
                    LengthPrefix::U16 => 2,
                    LengthPrefix::U32 => 4,
                };
                let mut buf = vec![0u8; len];
                reader.read_exact(&mut buf)?;
                *bytes_read += len as u64;
                let s = String::from_utf8(buf)?;
                ParsedValue::String(s)
            }
            FieldType::NullTerminatedString { max_len } => {
                let limit = max_len.unwrap_or(4096);
                let mut buf = Vec::new();
                let mut count = 0;
                loop {
                    let b = reader.read_u8()?;
                    *bytes_read += 1;
                    count += 1;
                    if b == 0 {
                        break;
                    }
                    buf.push(b);
                    if count >= limit {
                        break;
                    }
                }
                let s = String::from_utf8_lossy(&buf).into_owned();
                ParsedValue::String(s)
            }
            FieldType::FixedBytes { length } => {
                let mut buf = vec![0u8; *length];
                reader.read_exact(&mut buf)?;
                *bytes_read += *length as u64;
                ParsedValue::Bytes(buf)
            }
            FieldType::TimestampMs => {
                let ms = match endian {
                    Endianness::Little => reader.read_i64::<LittleEndian>()?,
                    Endianness::Big => reader.read_i64::<BigEndian>()?,
                };
                *bytes_read += 8;
                let dt = DateTime::from_timestamp_millis(ms)
                    .unwrap_or_else(|| DateTime::<Utc>::from(std::time::SystemTime::UNIX_EPOCH));
                ParsedValue::DateTime(dt.to_rfc3339())
            }
            FieldType::TimestampSec => {
                let sec = match endian {
                    Endianness::Little => reader.read_i64::<LittleEndian>()?,
                    Endianness::Big => reader.read_i64::<BigEndian>()?,
                };
                *bytes_read += 8;
                let dt = DateTime::from_timestamp_secs(sec)
                    .unwrap_or_else(|| DateTime::<Utc>::from(std::time::SystemTime::UNIX_EPOCH));
                ParsedValue::DateTime(dt.to_rfc3339())
            }
        };

        Ok(value)
    }
}

/// Décodeur hexadécimal simple
fn hex_decode(s: &str) -> Result<Vec<u8>, String> {
    if s.len() % 2 != 0 {
        return Err("La longueur hexadécimale doit être paire".to_string());
    }
    let mut bytes = Vec::with_capacity(s.len() / 2);
    for i in (0..s.len()).step_by(2) {
        let byte = u8::from_str_radix(&s[i..i + 2], 16)
            .map_err(|e| format!("Erreur décodage octet '{}': {}", &s[i..i + 2], e))?;
        bytes.push(byte);
    }
    Ok(bytes)
}

/// Interface CLI avec Clap
#[derive(Parser, Debug)]
#[command(name = "binlog-dynamic-parser")]
#[command(about = "Parser dynamique de fichiers de journaux binaires selon un schéma", long_about = None)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Parse un fichier journal binaire et affiche les enregistrements en JSON/NDJSON
    Parse {
        /// Chemin vers le fichier de schéma (YAML ou JSON)
        #[arg(short, long)]
        schema: PathBuf,

        /// Fichier binaire source
        #[arg(short, long)]
        input: PathBuf,

        /// Fichier de sortie (Optionnel, écrit sur stdout si omis)
        #[arg(short, long)]
        output: Option<PathBuf>,

        /// Sortie au format JSON Pretty-printed au lieu de JSON Lines
        #[arg(long, default_value_t = false)]
        pretty: bool,
    },

    /// Génère un schéma d'exemple et un fichier binaire de test correspondant
    GenerateSample {
        /// Chemin du schéma à créer (ex: sample_schema.yaml)
        #[arg(short, long, default_value = "sample_schema.yaml")]
        schema: PathBuf,

        /// Chemin du binaire de test à créer (ex: sample.bin)
        #[arg(short, long, default_value = "sample.bin")]
        output: PathBuf,
    },
}

fn generate_sample_data(schema_path: &Path, bin_path: &Path) -> Result<(), anyhow::Error> {
    // 1. Créer le schéma d'exemple
    let sample_schema = LogSchema {
        name: "ServeurTransactionLogs".to_string(),
        version: 1,
        endianness: Endianness::Little,
        header: Some(HeaderDef {
            magic: Some("4C4F4731".to_string()), // "LOG1"
            fields: vec![
                FieldDef {
                    name: "version".to_string(),
                    data_type: FieldType::U16,
                },
                FieldDef {
                    name: "cluster_id".to_string(),
                    data_type: FieldType::U32,
                },
            ],
        }),
        record: vec![
            FieldDef {
                name: "timestamp".to_string(),
                data_type: FieldType::TimestampMs,
            },
            FieldDef {
                name: "event_id".to_string(),
                data_type: FieldType::U64,
            },
            FieldDef {
                name: "service_name".to_string(),
                data_type: FieldType::FixedString { length: 12 },
            },
            FieldDef {
                name: "status_code".to_string(),
                data_type: FieldType::U16,
            },
            FieldDef {
                name: "latency_ms".to_string(),
                data_type: FieldType::F32,
            },
            FieldDef {
                name: "is_error".to_string(),
                data_type: FieldType::Bool,
            },
            FieldDef {
                name: "message".to_string(),
                data_type: FieldType::PrefixString {
                    prefix: LengthPrefix::U16,
                },
            },
        ],
    };

    let yaml_content = serde_yaml::to_string(&sample_schema)?;
    std::fs::write(schema_path, yaml_content)?;
    eprintln!("Schéma généré: {}", schema_path.display());

    // 2. Écrire le binaire de test
    let file = File::create(bin_path)?;
    let mut writer = BufWriter::new(file);

    // Écriture de l'en-tête: Magic "LOG1" (0x4C, 0x4F, 0x47, 0x31)
    writer.write_all(b"LOG1")?;
    // version = 1 (u16)
    writer.write_u16::<LittleEndian>(1)?;
    // cluster_id = 4200 (u32)
    writer.write_u32::<LittleEndian>(4200)?;

    // Données de test (3 enregistrements)
    let records_data = vec![
        (
            1710000000000i64, // 2024-03-09
            1001u64,
            "auth-srv",
            200u16,
            12.5f32,
            false,
            "Authentification token valide généré",
        ),
        (
            1710000001500i64,
            1002u64,
            "payment-srv",
            500u16,
            245.8f32,
            true,
            "Délai d'attente de la passerelle dépassé",
        ),
        (
            1710000002100i64,
            1003u64,
            "db-proxy",
            200u16,
            2.1f32,
            false,
            "Requête exécutée avec succès",
        ),
    ];

    for (ts, ev_id, srv, status, lat, is_err, msg) in records_data {
        writer.write_i64::<LittleEndian>(ts)?;
        writer.write_u64::<LittleEndian>(ev_id)?;

        let mut srv_bytes = [0u8; 12];
        let bytes = srv.as_bytes();
        let copy_len = bytes.len().min(12);
        srv_bytes[..copy_len].copy_from_slice(&bytes[..copy_len]);
        writer.write_all(&srv_bytes)?;

        writer.write_u16::<LittleEndian>(status)?;
        writer.write_f32::<LittleEndian>(lat)?;
        writer.write_u8(if is_err { 1 } else { 0 })?;

        // Message prefixé par u16
        let msg_bytes = msg.as_bytes();
        writer.write_u16::<LittleEndian>(msg_bytes.len() as u16)?;
        writer.write_all(msg_bytes)?;
    }

    writer.flush()?;
    eprintln!("Binaire de test généré: {}", bin_path.display());
    Ok(())
}

fn run_parser(
    schema_path: &Path,
    input_path: &Path,
    output_path: Option<&Path>,
    pretty: bool,
) -> Result<(), anyhow::Error> {
    let schema = LogSchema::load_from_file(schema_path)?;
    let input_file = File::open(input_path)?;
    let reader = BufReader::new(input_file);

    let mut log_reader = BinaryLogReader::new(reader, schema);

    // Lecture de l'en-tête si présent
    if let Some(header_fields) = log_reader.read_header()? {
        eprintln!(
            "[INFO] En-tête décodé: {}",
            serde_json::to_string(&header_fields)?
        );
    }

    let mut out_writer: Box<dyn Write> = match output_path {
        Some(path) => Box::new(BufWriter::new(File::create(path)?)),
        None => Box::new(io::stdout().lock()),
    };

    let mut count = 0;
    let mut records_list = Vec::new();

    while let Some(record) = log_reader.next_record()? {
        count += 1;
        if pretty {
            records_list.push(record);
        } else {
            let json_line = serde_json::to_string(&record)?;
            writeln!(out_writer, "{}", json_line)?;
        }
    }

    if pretty {
        let json_pretty = serde_json::to_string_pretty(&records_list)?;
        writeln!(out_writer, "{}", json_pretty)?;
    }

    out_writer.flush()?;
    eprintln!("[INFO] Décodage terminé avec succès : {} enregistrements traités.", count);
    Ok(())
}

fn main() -> Result<(), anyhow::Error> {
    let cli = Cli::parse();

    match &cli.command {
        Commands::Parse {
            schema,
            input,
            output,
            pretty,
        } => {
            run_parser(schema, input, output.as_deref(), *pretty)?;
        }
        Commands::GenerateSample { schema, output } => {
            generate_sample_data(schema, output)?;
        }
    }

    Ok(())
}

