// src/main.rs
use expert_engine::{
    Condition, EngineConfig, Fact, FactExplanation, InferenceEngine, Rule,
};
use std::error::Error;

/// Fonction utilitaire récursive pour afficher l'arbre d'explication d'un fait.
fn print_explanation(explanation: &FactExplanation, indent: usize) {
    let padding = "  ".repeat(indent);
    if let Some(rule_id) = &explanation.deduced_by_rule {
        let cycle = explanation.cycle.unwrap_or(0);
        println!(
            "{}├─ [FAIT DÉDUIT] {} = {} (par règle '{}', cycle {})",
            padding, explanation.fact_name, explanation.value, rule_id, cycle
        );
    } else {
        println!(
            "{}└─ [FAIT INITIAL] {} = {}",
            padding, explanation.fact_name, explanation.value
        );
    }

    for child in &explanation.premises {
        print_explanation(child, indent + 1);
    }
}

fn main() -> Result<(), Box<dyn Error>> {
    println!("================================================================================");
    println!("   SYSTÈME EXPERT À CHAÎNAGE AVANT (FORWARD CHAINING) AVEC MÉTA-RÈGLES EN RUST");
    println!("================================================================================\n");

    let mut engine = InferenceEngine::with_config(EngineConfig {
        max_cycles: 50,
        strategy: expert_engine::ConflictResolutionStrategy::SalienceThenSpecificity,
        verbose: true,
    });

    // 1. Initialisation des faits (Télémétrie d'un centre de calcul / installation critique)
    println!(">> 1. Chargement des faits initiaux dans la mémoire de travail...");
    engine.add_fact(Fact::new("temperature_cpu_celsius", 88.5));
    engine.add_fact(Fact::new("debit_pompe_refroidissement_lpm", 12.0));
    engine.add_fact(Fact::new("mode_exploitation", "datacenter_haute_densite"));
    engine.add_fact(Fact::new("presence_technicien_salle", false));
    engine.add_fact(Fact::new("charge_calcul_pourcent", 95.0));

    // 2. Définition des règles initiales
    println!(">> 2. Enregistrement de la base de règles initiale (Règles métier & Méta-règles)...");

    // Règle 1 : Détection d'anomalie thermique
    let r1 = Rule::builder("R_SURCHAUFFE_DETECTEE")
        .description("Signale une surchauffe si la température dépasse 80°C")
        .salience(20)
        .when(Condition::GreaterThan(
            "temperature_cpu_celsius".into(),
            80.0.into(),
        ))
        .then_assert_fact("anomalie_thermique", true)
        .then_log("Anomalie thermique identifiée sur les processeurs.")
        .build();

    // Règle 2 : Détection d'insuffisance de refroidissement
    let r2 = Rule::builder("R_REFROIDISSEMENT_DEFAILLANT")
        .description("Détecte une pompe sous-dimensionnée (< 15 L/min)")
        .salience(20)
        .when(Condition::LessThan(
            "debit_pompe_refroidissement_lpm".into(),
            15.0.into(),
        ))
        .then_assert_fact("defaut_pompe_primaire", true)
        .then_log("Débit de liquide caloporteur insuffisant.")
        .build();

    // Règle 3 : Diagnostic combiné
    let r3 = Rule::builder("R_DIAGNOSTIC_RISQUE_THERMIQUE")
        .description("Confirme le risque d'emballement thermique")
        .salience(30)
        .when(Condition::Equals("anomalie_thermique".into(), true.into()))
        .when(Condition::Equals("defaut_pompe_primaire".into(), true.into()))
        .then_assert_fact("risque_emballement_thermique", true)
        .then_log("Risque d'emballement thermique sévère confirmé par corrélation.")
        .build();

    // RÈGLE 4 : MÉTA-RÈGLE (DÉDUCTION DYNAMIQUE DE NOUVELLES RÈGLES)
    // En cas de risque d'emballement dans un datacenter sans technicien sur place,
    // le système déduit et injecte dynamiquement une NOUVELLE RÈGLE de coupure automatisée !
    let meta_rule = Rule::builder("META_INDUCTION_REGLE_CONFINEMENT")
        .description("Méta-règle induisant une règle de délestage d'urgence adaptée au contexte")
        .salience(40)
        .when(Condition::Equals(
            "risque_emballement_thermique".into(),
            true.into(),
        ))
        .when(Condition::Equals(
            "presence_technicien_salle".into(),
            false.into(),
        ))
        .then_assert_rule(
            Rule::builder("R_DEDUTIE_ARRET_CHARGE_CRITIQUE")
                .description("Règle synthétisée dynamiquement : déleste la charge si > 80%")
                .salience(100) // Priorité absolue
                .when(Condition::GreaterThan(
                    "charge_calcul_pourcent".into(),
                    80.0.into(),
                ))
                .then_assert_fact("delestage_charge_calcul", true)
                .then_assert_fact("declenchement_climatisation_secours", true)
                .then_log("DÉLESTAGE IMMÉDIAT ET ACTIVATION SECOURS ORDONNÉS !")
                .build(),
        )
        .then_assert_fact("protocole_autonome_engage", true)
        .then_log("MÉTA-SYNTHÈSE : Nouvelle règle 'R_DEDUTIE_ARRET_CHARGE_CRITIQUE' générée.")
        .build();

    engine.add_rule(r1)?;
    engine.add_rule(r2)?;
    engine.add_rule(r3)?;
    engine.add_rule(meta_rule)?;

    // 3. Exécution du cycle d'inférence
    println!("\n>> 3. Lancement du moteur d'inférence (Chaînage avant)...");
    let report = engine.run()?;

    println!("\n================================================================================");
    println!("   RÉSULTATS DE L'EXÉCUTION DU MOTEUR D'INFÉRENCE");
    println!("================================================================================");
    println!("• Cycles d'inférence exécutés   : {}", report.total_cycles);
    println!("• Faits initiaux               : {}", report.initial_facts_count);
    println!("• Faits finaux                 : {}", report.final_facts_count);
    println!("• Nouvelles règles déduites    : {}", report.deduced_rules_count);
    println!("• Total de règles dans la base : {}", report.total_rules_count);

    // 4. Affichage de la base de faits finale
    println!("\n>> 4. État final de la base de faits :");
    for fact in engine.facts().iter() {
        println!("   - {}", fact);
    }

    // 5. Affichage des règles déduites dynamiquement
    println!("\n>> 5. Détail des règles déduites dynamiquement par méta-inférence :");
    let mut found_deduced = false;
    for rule in engine.rules() {
        if let Some(prov) = &rule.provenance {
            found_deduced = true;
            println!("   ★ ID Règle        : {}", rule.id);
            println!("     Description     : {}", rule.description);
            println!("     Méta-règle mère : {}", prov.parent_rule_id);
            println!("     Cycle de genèse : {}", prov.cycle);
            println!("     Prémisses mère  : {:?}", prov.premise_facts);
        }
    }
    if !found_deduced {
        println!("   (Aucune règle dynamique déduite)");
    }

    // 6. Arbre d'explication et justification d'un fait critique
    println!("\n>> 6. Arbre de justification causale pour 'delestage_charge_calcul' :");
