fn print_separator(title: &str) {
    println!("\n================================================================================");
    println!("  {title}");
    println!("================================================================================");
}

fn print_results(strategy_name: &str, stats: &SimulationStats, initial_sum: Amount, final_sum: Amount) {
    println!("\n  [Résultats : {strategy_name}]");
    println!("  - Transactions demandées     : {}", stats.total_requested);
    println!("  - Transactions validées      : {}", stats.successful_transfers);
    println!("  - Rejets (fonds insuffisants): {}", stats.failed_insufficient_funds);
    println!("  - Deadlocks détectés/résolus : {}", stats.deadlocks_detected_and_resolved);
    println!("  - Nombre total de tentatives : {}", stats.total_attempts);
    println!("  - Temps d'exécution          : {:.2?}", stats.elapsed);
    println!("  - Débit transactionnel       : {:.1} tx/sec", stats.throughput());
    println!("  - Invariant monétaire initial: {} ¢", initial_sum);
    println!("  - Invariant monétaire final  : {} ¢", final_sum);

    let invariant_ok = initial_sum == final_sum;
    if invariant_ok {
        println!("  - Intégrité monétaire        : [CONSERVÉE STRICTEMENT]");
    } else {
        println!("  - Intégrité monétaire        : [VIOLÉE ! Perte ou création de monnaie]");
    }
    assert!(invariant_ok, "Invariant monétaire rompu dans {strategy_name}");
}

