    println!("  - Total de transactions / test   : {}", num_threads * transfers_per_thread);

    // ------------------------------------------------------------------------
    // SCÉNARIO 1 : Prévention par ordonnancement total des verrous (Resource Hierarchy)
    // ------------------------------------------------------------------------
    print_separator("1. PRÉVENTION PAR ORDONNANCEMENT STRICT (Resource Hierarchy)");
    println!("Principe : min(id_from, id_to) puis max(id_from, id_to).");
    println!("Garantie mathématique : Bris de la condition d'attente circulaire de Coffman.");

    let bank1 = Bank::new(num_accounts, initial_balance);
