```rust
// src/main.rs
//! Simulateur de transactions bancaires concurrentes avec détection
//! et prévention de situations d'interblocage (deadlocks).
//!
//! Ce programme démontre :
//! 1. La prévention formelle par ordonnancement strict des verrous (Resource Hierarchy).
//! 2. La prévention dynamique par Try-Lock avec backoff exponentiel et gigue (Jitter).
//! 3. La détection et résolution dynamique par Graphe d'Attente (Wait-For Graph - WFG) et DFS de cycles.
//! 4. La conservation stricte des invariants monétaires (somme totale invariante).

use parking_lot::{Mutex, MutexGuard};
use rand::Rng;
use std::collections::{HashMap, HashSet};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};
use thiserror::Error;

/// Type pour les identifiants de compte.
pub type AccountId = u64;

/// Type pour les identifiants de transaction.
pub type TxId = u64;

/// Montants financiers exprimés en centimes pour proscrire toute dérive flottante.
pub type Amount = u64;

/// Erreurs métier et de concurrence du système bancaire.
#[derive(Debug, Error, Clone, PartialEq, Eq)]
pub enum BankError {
    #[error("Compte #{0} introuvable dans le registre")]
    AccountNotFound(AccountId),

    #[error("Solde insuffisant sur le compte #{0}: solde disponible={1}¢, requis={2}¢")]
    InsufficientFunds(AccountId, Amount, Amount),

    #[error("Virement impossible: le compte source et destination sont identiques (#{0})")]
    SelfTransfer(AccountId),

    #[error("Interblocage détecté pour la transaction #{0} (comptes #{1} -> #{2})")]
    DeadlockDetected(TxId, AccountId, AccountId),

    #[error("Délai d'attente d'acquisition dépassé (Timeout / Conflit d'accès)")]
    LockTimeout,

    #[error("Nombre maximal de tentatives ({0}) atteint")]
    MaxRetriesExceeded(usize),
}

/// Représentation interne d'un compte bancaire.
#[derive(Debug)]
pub struct AccountInner {
    pub id: AccountId,
    pub balance: Amount,
}

/// Compte bancaire thread-safe protégé par un Mutex de haute performance.
#[derive(Debug)]
pub struct Account {
    pub id: AccountId,
    inner: Mutex<AccountInner>,
}

impl Account {
    pub fn new(id: AccountId, initial_balance: Amount) -> Self {
        Self {
            id,
            inner: Mutex::new(AccountInner {
                id,
                balance: initial_balance,
            }),
        }
    }

    pub fn balance(&self) -> Amount {
        self.inner.lock().balance
    }

    pub fn lock(&self) -> MutexGuard<'_, AccountInner> {
        self.inner.lock()
    }

    pub fn try_lock_for(&self, timeout: Duration) -> Option<MutexGuard<'_, AccountInner>> {
        self.inner.try_lock_for(timeout)
    }
}

/// Registre bancaire centralisé.
#[derive(Clone)]
pub struct Bank {
    accounts: Arc<HashMap<AccountId, Arc<Account>>>,
}

impl Bank {
    /// Initialise une banque avec `num_accounts` comptes dotés chacun de `initial_balance_each`.
    pub fn new(num_accounts: usize, initial_balance_each: Amount) -> Self {
        let mut map = HashMap::with_capacity(num_accounts);
        for id in 1..=num_accounts as u64 {
            map.insert(id, Arc::new(Account::new(id, initial_balance_each)));
        }
        Self {
            accounts: Arc::new(map),
        }
    }

    pub fn get_account(&self, id: AccountId) -> Result<Arc<Account>, BankError> {
        self.accounts
            .get(&id)
            .cloned()
            .ok_or(BankError::AccountNotFound(id))
    }

    /// Calcule la somme globale de tous les comptes (audit d'invariance).
    pub fn total_balance(&self) -> Amount {
        // Pour un audit exact, on verrouille tous les comptes dans l'ordre strict de leurs IDs
        let mut sorted_ids: Vec<AccountId> = self.accounts.keys().copied().collect();
        sorted_ids.sort_unstable();

        let guards: Vec<_> = sorted_ids
            .iter()
            .filter_map(|id| self.accounts.get(id))
            .map(|acc| acc.lock())
            .collect();

        guards.iter().map(|g| g.balance).sum()
    }
}

// ============================================================================
// STRATÉGIE 1 : PRÉVENTION PAR ORDONNANCEMENT STRICT (RESOURCE HIERARCHY)
// ============================================================================

/// Moteur de virement prévenant les deadlocks par ordonnancement total des ressources.
///
/// Brise formellement la 4ème condition de Coffman (attente circulaire) :
/// Les verrous sont systématiquement acquis selon `min(source, destination)`
/// puis `max(source, destination)`.
pub struct OrderedLockEngine;

impl OrderedLockEngine {
    pub fn transfer(
        bank: &Bank,
        from_id: AccountId,
        to_id: AccountId,
        amount: Amount,
    ) -> Result<(), BankError> {
        if from_id == to_id {
            return Err(BankError::SelfTransfer(from_id));
        }

        let acc_from = bank.get_account(from_id)?;
        let acc_to = bank.get_account(to_id)?;

        // Règle d'ordonnancement total : acquisition selon l'ordre strict des identifiants
        let (mut from_guard, mut to_guard) = if from_id < to_id {
            let g_from = acc_from.lock();
            let g_to = acc_to.lock();
            (g_from, g_to)
        } else {
            let g_to = acc_to.lock();
            let g_from = acc_from.lock();
            (g_from, g_to)
        };

        if from_guard.balance < amount {
            return Err(BankError::InsufficientFunds(from_id, from_guard.balance, amount));
        }

        from_guard.balance -= amount;
        to_guard.balance += amount;

        Ok(())
    }
}

// ============================================================================
// STRATÉGIE 2 : PRÉVENTION DYNAMIQUE PAR TRY-LOCK AVEC BACKOFF ET JITTER
// ============================================================================

/// Moteur de virement avec bris de la condition "Hold and Wait" (Rétention et attente).
///
/// Si le second verrou ne peut être acquis immédiatement, le premier est relâché,
/// et un délai aléatoire avec gigue (jitter) est appliqué avant de retenter.
pub struct TryLockBackoffEngine;

impl TryLockBackoffEngine {
    pub fn transfer(
        bank: &Bank,
        from_id: AccountId,
        to_id: AccountId,
        amount: Amount,
        max_retries: usize,
    ) -> Result<usize, BankError> {
        if from_id == to_id {
            return Err(BankError::SelfTransfer(from_id));
        }

        let acc_from = bank.get_account(from_id)?;
        let acc_to = bank.get_account(to_id)?;

        let mut rng = rand::thread_rng();

        for attempt in 1..=max_retries {
            // Tente de verrouiller le compte source
            if let Some(mut from_guard) = acc_from.try_lock_for(Duration::from_millis(5)) {
                if from_guard.balance < amount {
                    return Err(BankError::InsufficientFunds(from_id, from_guard.balance, amount));
                }

                // Tente de verrouiller le compte destination
                if let Some(mut to_guard) = acc_to.try_lock_for(Duration::from_millis(5)) {
                    from_guard.balance -= amount;
                    to_guard.balance += amount;
                    return Ok(attempt);
                }
                // Si acc_to n'est pas disponible, from_guard est relâché dès la fin de ce bloc
            }

            // Backoff aléatoire (gigue entre 1ms et 10ms exponentiel)
            let base_delay = 2u64.pow(attempt.min(5) as u32);
            let jitter = rng.gen_range(1..=5);
            thread::sleep(Duration::from_millis(base_delay + jitter));
        }

        Err(BankError::MaxRetriesExceeded(max_retries))
    }
}

// ============================================================================
// STRATÉGIE 3 : DÉTECTION ET RÉSOLUTION DYNAMIQUE PAR WAIT-FOR GRAPH (WFG)
// ============================================================================

/// État partagé du graphe d'attente (WFG).
/// Permet de modéliser les dépendances de type :
/// - Une transaction détient un compte (`holding: AccountId -> TxId`).
/// - Une transaction attend un compte (`waiting: TxId -> AccountId`).
#[derive(Default)]
struct WfgState {
    holding: HashMap<AccountId, TxId>,
    waiting: HashMap<TxId, AccountId>,
}

/// Graphe d'attente concurrent avec détection de cycle par DFS.
#[derive(Clone, Default)]
pub struct WaitForGraph {
    state: Arc<Mutex<WfgState>>,
}

impl WaitForGraph {
    pub fn new() -> Self {
        Self::default()
    }

    /// Déclare qu'une transaction détient un verrou sur un compte.
    pub fn register_holding(&self, tx: TxId, account: AccountId) {
        let mut s = self.state.lock();
        s.holding.insert(account, tx);
    }

    /// Déclare qu'une transaction attend un verrou sur un compte.
    pub fn register_waiting(&self, tx: TxId, account: AccountId) {
        let mut s = self.state.lock();
        s.waiting.insert(tx, account);
    }

    /// Libère l'attente d'une transaction.
    pub fn clear_waiting(&self, tx: TxId) {
        let mut s = self.state.lock();
        s.waiting.remove(&tx);
    }

    /// Libère les ressources détenues et attendues par une transaction.
    pub fn clear_transaction(&self, tx: TxId) {
        let mut s = self.state.lock();
        s.waiting.remove(&tx);
        s.holding.retain(|_, holding_tx| *holding_tx != tx);
    }

    /// Vérifie si l'ajout d'une dépendance crée un cycle d'interblocage (cycle dans le WFG).
    /// Si un cycle est trouvé, retourne le cycle de transactions impliqué.
    pub fn detect_cycle_from(&self, start_tx: TxId) -> Option<Vec<TxId>> {
        let s = self.state.lock();

        let mut visited = HashSet::new();
        let mut path = Vec::new();
        let mut current = start_tx;

        while visited.insert(current) {
            path.push(current);
            // Vérifier quel compte 'current' attend
            if let Some(&wanted_account) = s.waiting.get(&current) {
                // Vérifier quelle transaction détient ce compte
                if let Some(&holder_tx) = s.holding.get(&wanted_account) {
                    if holder_tx == start_tx {
                        // Cycle fermé identifié !
                        return Some(path);
                    }
                    current = holder_tx;
                } else {
                    break;
                }
            } else {
                break;
            }
        }

        None
    }
}

/// Moteur transactionnel avec détection active de cycle et résolution par victime.
pub struct WfgDetectionEngine {
    wfg: WaitForGraph,
    tx_counter: AtomicU64,
}

impl WfgDetectionEngine {
    pub fn new() -> Self {
        Self {
            wfg: WaitForGraph::new(),
            tx_counter: AtomicU64::new(1),
        }
    }

    /// Exécute un virement en ordre arbitraire non sécurisé (provoquant des deadlocks potentiels),
    /// mais surveillé par le WFG. En cas de cycle détecté, la transaction s'annule immédiatement,
    /// relâche ses ressources, et réessaie après un délai d'apaisement.
    pub fn transfer(
        &self,
        bank: &Bank,
        from_id: AccountId,
        to_id: AccountId,
        amount: Amount,
        max_retries: usize,
    ) -> Result<(usize, usize), BankError> {
        if from_id == to_id {
            return Err(BankError::SelfTransfer(from_id));
        }

        let acc_from = bank.get_account(from_id)?;
        let acc_to = bank.get_account(to_id)?;

        let mut deadlocks_encountered = 0;
        let mut rng = rand::thread_rng();

        for attempt in 1..=max_retries {
            let tx_id = self.tx_counter.fetch_add(1, Ordering::Relaxed);

            // Phase 1 : Acquisition du premier compte (source)
            let from_guard = acc_from.lock();
            self.wfg.register_holding(tx_id, from_id);

            if from_guard.balance < amount {
                self.wfg.clear_transaction(tx_id);
                return Err(BankError::InsufficientFunds(from_id, from_guard.balance, amount));
            }

            // Phase 2 : Enregistrement de la volonté d'acquérir le second compte
            self.wfg.register_waiting(tx_id, to_id);

            // Vérification proactive de cycle avant blocage indéfini
            if let Some(_cycle) = self.wfg.detect_cycle_from(tx_id) {
                // Deadlock confirmé ! La transaction courante se désigne comme victime
                deadlocks_encountered += 1;
                self.wfg.clear_transaction(tx_id);
                drop(from_guard); // Libération du verrou pour casser l'attente

                // Backoff avec gigue aléatoire pour désynchroniser les compétiteurs
                let jitter = rng.gen_range(5..=25);
                thread::sleep(Duration::from_millis(jitter));
                continue;
            }

            // Tentative d'acquisition du second verrou avec un timeout de sécurité
            if let Some(mut to_guard) = acc_to.try_lock_for(Duration::from_millis(15)) {
                self.wfg.clear_waiting(tx_id);
                self.wfg.register_holding(tx_id, to_id);

                let mut from_guard = from_guard;
                from_guard.balance -= amount;
                to_guard.balance += amount;

                // Libération et nettoyage
                drop(to_guard);
                drop(from_guard);
                self.wfg.clear_transaction(tx_id);

                return Ok((attempt, deadlocks_encountered));
            } else {
                // Échec d'acquisition rapide : revérification du WFG
                let is_cycle = self.wfg.detect_cycle_from(tx_id).is_some();
                self.wfg.clear_transaction(tx_id);
                drop(from_guard);

                if is_cycle {
                    deadlocks_encountered += 1;
                }

                let jitter = rng.gen_range(5..=20);
                thread::sleep(Duration::from_millis(jitter));
            }
        }

        Err(BankError::MaxRetriesExceeded(max_retries))
    }
}

