fn print_separator(title: &str) {
    println!("\n================================================================================");
    println!("  {title}");
    println!("================================================================================");
}

fn print_results(strategy_name: &str, stats: &SimulationStats, initial_sum: Amount, final_sum: Amount) {
    println!("\n  [Résultats : {strategy_name}]");
    println!("  - Transactions demandées     : {}", stats.total_requested);
    println!("  - Transactions validées      : {}", stats.successful_transfers);
    println!("  - Rejets (fonds insuffisants): {}", stats.failed_insufficient_funds);
    println!("  - Deadlocks détectés/résolus : {}", stats.deadlocks_detected_and_resolved);
    println!("  - Nombre total de tentatives : {}", stats.total_attempts);
    println!("  - Temps d'exécution          : {:.2?}", stats.elapsed);
    println!("  - Débit transactionnel       : {:.1} tx/sec", stats.throughput());
    println!("  - Invariant monétaire initial: {} ¢", initial_sum);
    println!("  - Invariant monétaire final  : {} ¢", final_sum);

    let invariant_ok = initial_sum == final_sum;
    if invariant_ok {
        println!("  - Intégrité monétaire        : [CONSERVÉE STRICTEMENT]");
    } else {
        println!("  - Intégrité monétaire        : [VIOLÉE ! Perte ou création de monnaie]");
    }
    assert!(invariant_ok, "Invariant monétaire rompu dans {strategy_name}");
}

fn main() {
    print_separator("SIMULATEUR DE TRANSACTIONS BANCAIRES CONCURRENTES");
    println!("Configuration de simulation :");
    let num_accounts = 10;
    let initial_balance = 100_000; // 1 000,00 € en centimes par compte
    let num_threads = 8;
    let transfers_per_thread = 500;

    println!("  - Nombre de comptes concurrents  : {num_accounts}");
    println!("  - Solde unitaire initial         : {initial_balance} ¢ (Total: {} ¢)", num_accounts as u64 * initial_balance);
    println!("  - Threads exécutants             : {num_threads}");
    println!("  - Virements par thread           : {transfers_per_thread}");
    println!("  - Total de transactions / test   : {}", num_threads * transfers_per_thread);

    // ------------------------------------------------------------------------
    // SCÉNARIO 1 : Prévention par ordonnancement total des verrous (Resource Hierarchy)
    // ------------------------------------------------------------------------
    print_separator("1. PRÉVENTION PAR ORDONNANCEMENT STRICT (Resource Hierarchy)");
    println!("Principe : min(id_from, id_to) puis max(id_from, id_to).");
    println!("Garantie mathématique : Bris de la condition d'attente circulaire de Coffman.");

    let bank1 = Bank::new(num_accounts, initial_balance);
    let initial_sum1 = bank1.total_balance();
    let stats1 = run_scenario_prevention_ordered(&bank1, num_threads, transfers_per_thread, num_accounts);
    let final_sum1 = bank1.total_balance();
    print_results("Ordonnancement strict des verrous", &stats1, initial_sum1, final_sum1);

    // ------------------------------------------------------------------------
    // SCÉNARIO 2 : Prévention dynamique par Try-Lock avec backoff exponentiel
    // ------------------------------------------------------------------------
    print_separator("2. PRÉVENTION DYNAMIQUE PAR TRY-LOCK ET BACKOFF");
    println!("Principe : Si le 2nd verrou n'est pas obtenu, le 1er est relâché (Hold & Wait brisé).");

    let bank2 = Bank::new(num_accounts, initial_balance);
    let initial_sum2 = bank2.total_balance();
    let stats2 = run_scenario_prevention_try_lock(&bank2, num_threads, transfers_per_thread, num_accounts);
    let final_sum2 = bank2.total_balance();
    print_results("Try-Lock & Backoff exponentiel", &stats2, initial_sum2, final_sum2);

    // ------------------------------------------------------------------------
    // SCÉNARIO 3 : Détection et résolution active par Graphe d'Attente (WFG)
    // ------------------------------------------------------------------------
    print_separator("3. DÉTECTION & RÉSOLUTION ACTIVE PAR WAIT-FOR GRAPH (WFG)");
    println!("Principe : Ordre d'acquisition libre. Détection de cycle par DFS et sacrifice d'une victime.");

    // Contention accrue : 4 comptes seulement pour provoquer des cycles récurrents
    let high_contention_accounts = 4;
    let bank3 = Bank::new(high_contention_accounts, initial_balance);
    let initial_sum3 = bank3.total_balance();
    let stats3 = run_scenario_detection_wfg(&bank3, num_threads, transfers_per_thread, high_contention_accounts);
    let final_sum3 = bank3.total_balance();
    print_results("WFG & Résolution par victime", &stats3, initial_sum3, final_sum3);

    print_separator("RÉSUMÉ ET VALIDATION FINALE");
    println!("Tous les scénarios ont validé leurs invariants avec succès sans interblocage fatal.");
    println!("Démonstration de concurrence terminée avec succès.\n");
}

