```rust
// src/main.rs
//! Parser et reconstructeur d'arborescences de documents HTML mal formés.
//! Tolère les balises non fermées, balises orphelines, attributs sans guillemets,
//! et éléments vides HTML5.



/// Représente un identifiant unique de nœud dans l'arène du DOM.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct NodeId(pub usize);

/// Type de nœud dans l'arborescence HTML.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum NodeData {
    /// Nœud racine invisible servant de point d'entrée au document.
    Document,
    /// Déclaration Doctype (ex: `<!DOCTYPE html>`).
    Doctype { name: String },
    /// Élément HTML avec nom de balise et attributs.
    Element {
        tag_name: String,
        attributes: Vec<(String, String)>,
    },
    /// Fragment de texte brut.
    Text(String),
    /// Commentaire HTML (ex: `<!-- contenu -->`).
    Comment(String),
}

/// Nœud stocké au sein de l'arène (`DomArena`).
#[derive(Debug, Clone)]
pub struct Node {
    pub id: NodeId,
    pub parent: Option<NodeId>,
    pub children: Vec<NodeId>,
    pub data: NodeData,
}

impl Node {
    fn new(id: NodeId, data: NodeData) -> Self {
        Self {
            id,
            parent: None,
            children: Vec::new(),
            data,
        }
    }
}

/// Structure d'arène garantissant une gestion de mémoire sûre et sans pointeurs cycliques.
#[derive(Debug, Clone)]
pub struct DomTree {
    nodes: Vec<Node>,
    root_id: NodeId,
}

impl DomTree {
    /// Initialise un nouvel arbre DOM avec un nœud racine Document.
    pub fn new() -> Self {
        let root = Node::new(NodeId(0), NodeData::Document);
        Self {
            nodes: vec![root],
            root_id: NodeId(0),
        }
    }

    /// Récupère l'identifiant du nœud racine du document.
    pub fn root(&self) -> NodeId {
        self.root_id
    }

    /// Ajoute un nouveau nœud dans l'arène sans parent.
    fn allocate(&mut self, data: NodeData) -> NodeId {
        let id = NodeId(self.nodes.len());
        self.nodes.push(Node::new(id, data));
        id
    }

    /// Attache un nœud enfant à un nœud parent.
    pub fn append_child(&mut self, parent_id: NodeId, child_id: NodeId) {
        if let Some(child_node) = self.nodes.get_mut(child_id.0) {
            child_node.parent = Some(parent_id);
        }
        if let Some(parent_node) = self.nodes.get_mut(parent_id.0) {
            parent_node.children.push(child_id);
        }
    }

    /// Récupère une référence vers un nœud par son identifiant.
    pub fn get(&self, id: NodeId) -> Option<&Node> {
        self.nodes.get(id.0)
    }

    /// Récupère une référence mutable vers un nœud par son identifiant.
    pub fn get_mut(&mut self, id: NodeId) -> Option<&mut Node> {
        self.nodes.get_mut(id.0)
    }

    /// Nombre total de nœuds alloués.
    pub fn len(&self) -> usize {
        self.nodes.len()
    }

    /// Vérifie si l'arbre est vide (contient uniquement la racine invisible).
    pub fn is_empty(&self) -> bool {
        self.nodes.len() <= 1
    }
}

impl Default for DomTree {
    fn default() -> Self {
        Self::new()
    }
}

/// Liste standard des éléments vides HTML5 ("void elements") qui ne possèdent jamais d'enfants.
pub fn is_void_element(tag: &str) -> bool {
    matches!(
        tag.to_ascii_lowercase().as_str(),
        "area"
            | "base"
            | "br"
            | "col"
            | "embed"
            | "hr"
            | "img"
            | "input"
            | "link"
            | "meta"
            | "param"
            | "source"
            | "track"
            | "wbr"
    )
}

/// Éléments de bloc dont l'ouverture ferme implicitement le précédent élément identique.
fn should_auto_close_parent(parent_tag: &str, new_tag: &str) -> bool {
    let p = parent_tag.to_ascii_lowercase();
    let n = new_tag.to_ascii_lowercase();
    match p.as_str() {
        "p" => matches!(
            n.as_str(),
            "p" | "div" | "ul" | "ol" | "li" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6" | "table"
        ),
        "li" => n == "li",
        "dt" | "dd" => n == "dt" || n == "dd",
        "tr" => n == "tr",
        "td" | "th" => n == "td" || n == "th" || n == "tr",
        _ => false,
    }
}

/// Token brut émis par l'analyseur lexical.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Token {
    Doctype(String),
    StartTag {
        name: String,
        attributes: Vec<(String, String)>,
        self_closing: bool,
    },
    EndTag {
        name: String,
    },
    Comment(String),
    Text(String),
}

/// Analyseur lexical résilient pour flux HTML.
pub struct Tokenizer<'a> {
    chars: std::iter::Peekable<std::str::CharIndices<'a>>,
    input: &'a str,
}

impl<'a> Tokenizer<'a> {
    pub fn new(input: &'a str) -> Self {
        Self {
            chars: input.char_indices().peekable(),
            input,
        }
    }

    fn skip_whitespace(&mut self) {
        while let Some(&(_, ch)) = self.chars.peek() {
            if ch.is_whitespace() {
                self.chars.next();
            } else {
                break;
            }
        }
    }

    fn consume_until(&mut self, delimiter: &str) -> String {
        let mut output = String::new();
        while let Some((_, ch)) = self.chars.next() {
            output.push(ch);
            if output.ends_with(delimiter) {
                output.truncate(output.len() - delimiter.len());
                break;
            }
        }
        output
    }

    fn parse_tag(&mut self) -> Option<Token> {
        // Déjà après le '<'
        let mut is_closing = false;
        if let Some(&(_, '/')) = self.chars.peek() {
            self.chars.next();
            is_closing = true;
        }

        // Lecture du nom de balise
        let mut tag_name = String::new();
        while let Some(&(_, ch)) = self.chars.peek() {
            if ch.is_alphanumeric() || ch == '-' || ch == '_' || ch == ':' {
                tag_name.push(ch);
                self.chars.next();
            } else {
                break;
            }
        }

        if tag_name.is_empty() {
            // Fausse balise ou caractère isolé '<', on traite comme texte
            return Some(Token::Text("<".to_string()));
        }

        if is_closing {
            // On ignore les espaces et d'éventuels attributs farfelus dans la balise fermante
            while let Some((_, ch)) = self.chars.next() {
                if ch == '>' {
                    break;
                }
            }
            return Some(Token::EndTag { name: tag_name });
        }

        // Balise ouvrante : lecture des attributs
        let mut attributes = Vec::new();
        let mut self_closing = false;

        loop {
            self.skip_whitespace();
            match self.chars.peek() {
                None => break,
                Some(&(_, '>')) => {
                    self.chars.next();
                    break;
                }
                Some(&(_, '/')) => {
                    self.chars.next();
                    self.skip_whitespace();
                    if let Some(&(_, '>')) = self.chars.peek() {
                        self.chars.next();
                        self_closing = true;
                    }
                    break;
                }
                Some(&(_, ch)) if ch.is_alphanumeric() || ch == '-' || ch == '_' || ch == '@' || ch == ':' => {
                    let mut attr_name = String::new();
                    while let Some(&(_, c)) = self.chars.peek() {
                        if c.is_alphanumeric() || c == '-' || c == '_' || c == '@' || c == ':' || c == '.' {
                            attr_name.push(c);
                            self.chars.next();
                        } else {
                            break;
                        }
                    }

                    self.skip_whitespace();
                    let mut attr_value = String::new();

                    if let Some(&(_, '=')) = self.chars.peek() {
                        self.chars.next();
                        self.skip_whitespace();

                        if let Some(&(_, quote @ ('"' | '\''))) = self.chars.peek() {
                            self.chars.next();
                            while let Some((_, c)) = self.chars.next() {
                                if c == quote {
                                    break;
                                }
                                attr_value.push(c);
                            }
                        } else {
                            // Attribut non entouré de guillemets
                            while let Some(&(_, c)) = self.chars.peek() {
                                if c.is_whitespace() || c == '>' || c == '/' {
                                    break;
                                }
                                attr_value.push(c);
                                self.chars.next();
                            }
                        }
                    }
                    attributes.push((attr_name, attr_value));
                }
                _ => {
                    // Caractère inattendu, on l'avance pour éviter la boucle infinie
                    self.chars.next();
                }
            }
        }

        Some(Token::StartTag {
            name: tag_name,
            attributes,
            self_closing,
        })
    }
}

impl<'a> Iterator for Tokenizer<'a> {
    type Item = Token;

    fn next(&mut self) -> Option<Self::Item> {
        let (start_idx, ch) = match self.chars.peek() {
            Some(&(idx, ch)) => (idx, ch),
            None => return None,
        };

        if ch == '<' {
            self.chars.next(); // consomer '<'

            // Détection de commentaire ou DOCTYPE
            let remaining = &self.input[start_idx..];
            if remaining.starts_with("<!--") {
                // Consommer "!--"
                for _ in 0..3 {
                    self.chars.next();
                }
                let comment_text = self.consume_until("-->");
                return Some(Token::Comment(comment_text));
            } else if remaining.to_ascii_uppercase().starts_with("<!DOCTYPE") {
                for _ in 0..8 {
                    self.chars.next();
                }
                let doctype_content = self.consume_until(">");
                return Some(Token::Doctype(doctype_content.trim().to_string()));
            }

            self.parse_tag()
        } else {
            // Lecture du fragment de texte jusqu'au prochain '<'
            let mut text = String::new();
            while let Some(&(_, c)) = self.chars.peek() {
                if c == '<' {
                    break;
                }
                text.push(c);
                self.chars.next();
            }
            if text.is_empty() {
                None
            } else {
                Some(Token::Text(text))
            }
        }
    }
}

/// Parseur tolérant construisant un `DomTree` à partir de HTML brut.
pub struct HtmlParser;

impl HtmlParser {
    /// Analyse une chaîne de caractères HTML même gravement mal formée.
    pub fn parse(input: &str) -> DomTree {
        let mut tree = DomTree::new();
        let mut open_elements: Vec<NodeId> = vec![tree.root()];
        let tokenizer = Tokenizer::new(input);

        for token in tokenizer {
            match token {
                Token::Doctype(name) => {
                    let doc_node = tree.allocate(NodeData::Doctype { name });
                    tree.append_child(tree.root(), doc_node);
                }
                Token::Comment(comment) => {
                    let comment_node = tree.allocate(NodeData::Comment(comment));
                    let current_parent = *open_elements.last().unwrap_or(&tree.root());
                    tree.append_child(current_parent, comment_node);
                }
                Token::Text(text) => {
                    let current_parent = *open_elements.last().unwrap_or(&tree.root());
                    let mut merged = false;
                    if let Some(parent_node) = tree.get(current_parent) {
                        if let Some(&last_child_id) = parent_node.children.last() {
                            if let Some(last_child) = tree.get_mut(last_child_id) {
                                if let NodeData::Text(ref mut existing) = last_child.data {
                                    existing.push_str(&text);
                                    merged = true;
                                }
                            }
                        }
                    }
                    if !merged {
                        let text_node = tree.allocate(NodeData::Text(text));
                        tree.append_child(current_parent, text_node);
                    }
                }
                Token::StartTag {
                    name,
                    attributes,
                    self_closing,
                } => {
                    let is_void = is_void_element(&name);

                    // Vérification de fermeture implicite de balises sœurs (ex: <p>...</p>)
                    loop {
                        if let Some(&top_id) = open_elements.last() {
                            if top_id == tree.root() {
                                break;
                            }
                            if let Some(top_node) = tree.get(top_id) {
                                if let NodeData::Element {
                                    tag_name: ref parent_tag,
                                    ..
                                } = top_node.data
                                {
                                    if should_auto_close_parent(parent_tag, &name) {
                                        open_elements.pop();
                                        continue;
                                    }
                                }
                            }
                        }
                        break;
                    }

                    let elem_node = tree.allocate(NodeData::Element {
                        tag_name: name.clone(),
                        attributes,
                    });

                    let parent = *open_elements.last().unwrap_or(&tree.root());
                    tree.append_child(parent, elem_node);

                    // Si ce n'est ni un élément auto-fermant ni un élément vide standard HTML5,
                    // on l'empile dans les éléments ouverts.
                    if !self_closing && !is_void {
                        open_elements.push(elem_node);
                    }
                }
                Token::EndTag { name } => {
                    let target_tag = name.to_ascii_lowercase();

                    // Recherche ascendante dans la pile pour trouver l'élément ouvrant correspondant
                    let mut found_index = None;
                    for (i, &open_id) in open_elements.iter().enumerate().rev() {
                        if open_id == tree.root() {
                            continue;
                        }
                        if let Some(node) = tree.get(open_id) {
                            if let NodeData::Element { ref tag_name, .. } = node.data {
                                if tag_name.to_ascii_lowercase() == target_tag {
                                    found_index = Some(i);
                                    break;
                                }
                            }
                        }
                    }

                    if let Some(idx) = found_index {
                        // Tolérance d'imbrication : ferme cet élément et tous les éléments internes non fermés
                        open_elements.truncate(idx);
                    } else {
                        // Balise fermante orpheline (aucun ouvrant correspondant dans la pile) :
                        // Résilience : on ignore silencieusement pour ne pas corrompre l'arbre
                    }
                }
            }
        }

        // Tolérance aux balises non fermées : toutes les balises encore dans la pile
        // sont automatiquement fermées à la fin du document en vidant la pile.
        tree
    }
}

/// Options de sérialisation du reconstructeur d'arbre HTML.
#[derive(Debug, Clone)]
pub struct SerializerOptions {
    pub indent_size: usize,
    pub pretty: bool,
}

impl Default for SerializerOptions {
    fn default() -> Self {
        Self {
            indent_size: 2,
            pretty: true,
        }
    }
}

/// Reconstructeur sérialisant un `DomTree` en code HTML standardisé et propre.
pub struct HtmlSerializer {
    options: SerializerOptions,
}

impl HtmlSerializer {
    pub fn new(options: SerializerOptions) -> Self {
        Self { options }
    }

    /// Sérialise l'ensemble de l'arbre DOM.
    pub fn serialize(&self, tree: &DomTree) -> String {
        let mut output = String::new();
        for &child_id in tree.get(tree.root()).map(|n| n.children.as_slice()).unwrap_or(&[]) {
            self.serialize_node(tree, child_id, 0, &mut output);
        }
        output
    }

    fn serialize_node(&self, tree: &DomTree, node_id: NodeId, depth: usize, out: &mut String) {
        let node = match tree.get(node_id) {
            Some(n) => n,
            None => return,
        };

        let indent = if self.options.pretty {
            " ".repeat(depth * self.options.indent_size)
        } else {
            String::new()
        };

        match &node.data {
            NodeData::Document => {
                for &child in &node.children {
                    self.serialize_node(tree, child, depth, out);
                }
            }
            NodeData::Doctype { name } => {
                out.push_str(&indent);
                out.push_str("<!DOCTYPE ");
                out.push_str(name);
                out.push('>');
                if self.options.pretty {
                    out.push('\n');
                }
            }
            NodeData::Comment(comment) => {
                out.push_str(&indent);
                out.push_str("<!--");
                out.push_str(comment);
                out.push_str("-->");
                if self.options.pretty {
                    out.push('\n');
                }
            }
            NodeData::Text(text) => {
                if self.options.pretty {
                    let trimmed = text.trim();
                    if !trimmed.is_empty() {
                        out.push_str(&indent);
                        out.push_str(trimmed);
                        out.push('\n');
                    }
                } else {
                    out.push_str(text);
                }
            }
            NodeData::Element {
                tag_name,
                attributes,
            } => {
                let tag_lower = tag_name.to_ascii_lowercase();
                out.push_str(&indent);
                out.push('<');
                out.push_str(&tag_lower);

                for (key, val) in attributes {
                    out.push(' ');
                    out.push_str(key);
                    if !val.is_empty() {
                        out.push_str("=\"");
                        out.push_str(&escape_attribute(val));
                        out.push('"');
                    }
                }

                if is_void_element(&tag_lower) {
                    out.push_str(" />");
                    if self.options.pretty {
                        out.push('\n');
                    }
                } else {
                    out.push('>');

                    let has_children = !node.children.is_empty();
                    let single_text_child = if node.children.len() == 1 {
                        tree.get(node.children[0])
                            .map(|c| matches!(c.data, NodeData::Text(_)))
                            .unwrap_or(false)
                    } else {
                        false
                    };

                    if has_children {
                        if single_text_child && self.options.pretty {
                            // Rendu compact sur une seule ligne pour <p>Texte</p>
                            if let Some(child_node) = tree.get(node.children[0]) {
                                if let NodeData::Text(ref t) = child_node.data {
                                    let clean_text = t.trim();
                                    // Supprimer le retour chariot potentiel déjà écrit
                                    out.push_str(clean_text);
                                }
                            }
                            out.push_str("</");
                            out.push_str(&tag_lower);
                            out.push('>');
                            out.push('\n');
                            return;
                        }

                        if self.options.pretty {
                            out.push('\n');
                        }

                        for &child in &node.children {
                            self.serialize_node(tree, child, depth + 1, out);
                        }

                        out.push_str(&indent);
                    }

                    out.push_str("</");
                    out.push_str(&tag_lower);
                    out.push('>');
                    if self.options.pretty {
                        out.push('\n');
                    }
                }
            }
        }
    }
}

fn escape_attribute(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for ch in input.chars() {
        match ch {
            '"' => out.push_str("&quot;"),
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            _ => out.push(ch),
        }
    }
    out
}

fn main() {
    println!("=== DÉMONSTRATION : PARSER & RECONSTRUCTEUR HTML TOLÉRANT ===\n");

    // Exemple de HTML corrompu :
    // 1. DOCTYPE en minuscule
    // 2. Balise <div> non fermée
    // 3. Balise <p> fermée implicitement par une autre balise <p>
    // 4. Balises <b> et <i> mal imbriquées (croisées)
    // 5. Balise orpheline fermante </span> sans ouvrant
    // 6. Void element <img> non fermé avec attribut sans guillemets
    // 7. Balises <section> et <body> oubliées à la fermeture
    let malformed_html = r#"
        <!doctype html>
        <html>
        <head>
            <meta charset="utf-8">
            <title>Test Page
        </head>
        <body>
            <div class=container id="main">
                <p>Premier paragraphe sans balise fermante
                <p>Deuxième paragraphe avec <b>texte <i>croisé</b> mal fermé</i> !
                <img src=avatar.png alt=Utilisateur>
                <hr>
                </span> <!-- Balise fermante orpheline -->
                <ul>
                    <li>Item 1
                    <li>Item 2
                    <li>Item 3
                <!-- Fin abrupte sans fermeture de <ul>, <div>, <body>, <html> -->
    "#;

    println!("--- [1] Code HTML brut d'entrée (gravement mal formé) ---");
    println!("{}", malformed_html.trim());
    println!("\n--- [2] Analyse et réparation de l'arbre en cours... ---");

    let dom = HtmlParser::parse(malformed_html);
    println!("Total de nœuds générés dans l'arène DOM : {}", dom.len());

    let serializer = HtmlSerializer::new(SerializerOptions {
        indent_size: 2,
        pretty: true,
    });
    let reconstructed_html = serializer.serialize(&dom);

    println!("\n--- [3] Document HTML nettoyé et restructuré ---");
    println!("{}", reconstructed_html);

    println!("Validation de la reconstruction terminée avec succès !");
}

