        let html = "<div><img src=\"test.jpg\"><p>Paragraphe</p></div>";
        let tree = HtmlParser::parse(html);
        let serializer = HtmlSerializer::new(SerializerOptions {
            indent_size: 2,
            pretty: false,
        });
        let result = serializer.serialize(&tree);
        assert_eq!(
            result,
            "<div><img src=\"test.jpg\" /><p>Paragraphe</p></div>"
        );
    }

    #[test]
    fn test_crossed_tags_recovery() {
        let html = "<p>A <b>B <i>C</b> D</i> E</p>";
        let tree = HtmlParser::parse(html);
        let serializer = HtmlSerializer::new(SerializerOptions {
            indent_size: 2,
            pretty: false,
        });
        let result = serializer.serialize(&tree);
        // La fermeture de </b> doit dépiler <i> proprement
        assert!(result.contains("<b>"));
        assert!(result.contains("</b>"));
    }

    #[test]
    fn test_orphan_closing_tag_ignored() {
        let html = "<div>Texte</span> valide</div>";
        let tree = HtmlParser::parse(html);
        let serializer = HtmlSerializer::new(SerializerOptions {
            indent_size: 2,
            pretty: false,
        });
        let result = serializer.serialize(&tree);
        assert_eq!(result, "<div>Texte valide</div>");
    }

    #[test]
    fn test_implicit_paragraph_closing() {
        let html = "<div><p>Premier<p>Second</div>";
        let tree = HtmlParser::parse(html);
        let root = tree.root();
        let doc_children = &tree.get(root).unwrap().children;
        let div = tree.get(doc_children[0]).unwrap();
        // Le div doit avoir 2 enfants <p>, le premier ne doit pas contenir le second
        assert_eq!(div.children.len(), 2);
    }
}

