#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty_grid_straight_path() {
        let grid = Grid::new(10, 10).expect("Grille 10x10 valide");
        let solver = MultithreadedBidirectionalAStar::new(&grid, MovementMode::FourWay);

        let start = Coord::new(0, 0);
        let goal = Coord::new(0, 5);

        let result = solver.find_path(start, goal).expect("Chemin direct trouvé");
        assert_eq!(result.total_cost, 50);
        assert_eq!(result.path.len(), 6);
        assert_eq!(result.path.first(), Some(&start));
        assert_eq!(result.path.last(), Some(&goal));
    }

    #[test]
    fn test_same_start_and_goal() {
        let grid = Grid::new(5, 5).expect("Grille valide");
        let solver = MultithreadedBidirectionalAStar::new(&grid, MovementMode::FourWay);

        let point = Coord::new(2, 2);
        let result = solver.find_path(point, point).expect("Même point");
        assert_eq!(result.total_cost, 0);
        assert_eq!(result.path, vec![point]);
    }

    #[test]
    fn test_obstacle_detour() {
        // Mur vertical bloquant entre x=1, y=0..3
        let mut grid = Grid::new(5, 5).expect("Grille valide");
        grid.set_obstacle(Coord::new(1, 0), true);
        grid.set_obstacle(Coord::new(1, 1), true);
        grid.set_obstacle(Coord::new(1, 2), true);

        let solver = MultithreadedBidirectionalAStar::new(&grid, MovementMode::FourWay);
        let start = Coord::new(0, 0);
        let goal = Coord::new(2, 0);

        let result = solver.find_path(start, goal).expect("Détour trouvé");
        // Doit descendre en y=3 puis remonter : (0,0)->(0,1)->(0,2)->(0,3)->(1,3)->(2,3)->(2,2)->(2,1)->(2,0)
        assert_eq!(result.total_cost, 80);
        assert_eq!(result.path.first(), Some(&start));
        assert_eq!(result.path.last(), Some(&goal));
    }

    #[test]
    fn test_unreachable_goal() {
        let mut grid = Grid::new(5, 5).expect("Grille valide");
        // Encercle l'arrivée (4, 4)
        grid.set_obstacle(Coord::new(3, 4), true);
        grid.set_obstacle(Coord::new(4, 3), true);
        grid.set_obstacle(Coord::new(3, 3), true);

        let solver = MultithreadedBidirectionalAStar::new(&grid, MovementMode::EightWay);
        let start = Coord::new(0, 0);
        let goal = Coord::new(4, 4);

        let err = solver.find_path(start, goal).unwrap_err();
        assert_eq!(err, PathfindingError::NoPathFound);
    }

    #[test]
    fn test_out_of_bounds() {
        let grid = Grid::new(5, 5).expect("Grille valide");
        let solver = MultithreadedBidirectionalAStar::new(&grid, MovementMode::FourWay);

        let err = solver.find_path(Coord::new(10, 0), Coord::new(0, 0)).unwrap_err();
        assert_eq!(err, PathfindingError::StartOutOfBounds(10, 0));

        let err2 = solver.find_path(Coord::new(0, 0), Coord::new(0, 10)).unwrap_err();
        assert_eq!(err2, PathfindingError::GoalOutOfBounds(0, 10));
    }

    #[test]
    fn test_start_or_goal_is_obstacle() {
        let mut grid = Grid::new(5, 5).expect("Grille valide");
        grid.set_obstacle(Coord::new(0, 0), true);
        grid.set_obstacle(Coord::new(4, 4), true);

        let solver = MultithreadedBidirectionalAStar::new(&grid, MovementMode::FourWay);

        let err = solver.find_path(Coord::new(0, 0), Coord::new(2, 2)).unwrap_err();
        assert_eq!(err, PathfindingError::StartIsObstacle(0, 0));

        let err2 = solver.find_path(Coord::new(1, 1), Coord::new(4, 4)).unwrap_err();
        assert_eq!(err2, PathfindingError::GoalIsObstacle(4, 4));
    }

    #[test]
    fn test_diagonal_octile_movement() {
        let grid = Grid::new(10, 10).expect("Grille valide");
        let solver = MultithreadedBidirectionalAStar::new(&grid, MovementMode::EightWay);

        let start = Coord::new(0, 0);
        let goal = Coord::new(3, 3);

        let result = solver.find_path(start, goal).expect("Chemin diagonal");
        // 3 pas diagonaux à 14 chacun = 42
        assert_eq!(result.total_cost, 42);
        assert_eq!(result.path.len(), 4);
    }
