// src/main.rs
use std::cmp::Ordering as CmpOrdering;
use std::collections::BinaryHeap;
use std::fmt;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::Instant;

use parking_lot::Mutex;
use thiserror::Error;

/// Erreurs possibles lors de la recherche de chemin.
#[derive(Debug, Error, PartialEq, Eq)]
pub enum PathfindingError {
    #[error("La grille est vide ou de dimensions invalides.")]
    InvalidGridDimensions,

    #[error("Le point de départ ({0}, {1}) est en dehors des limites de la grille.")]
    StartOutOfBounds(usize, usize),

    #[error("Le point d'arrivée ({0}, {1}) est en dehors des limites de la grille.")]
    GoalOutOfBounds(usize, usize),

    #[error("Le point de départ ({0}, {1}) est situé sur un obstacle.")]
    StartIsObstacle(usize, usize),

    #[error("Le point d'arrivée ({0}, {1}) est situé sur un obstacle.")]
    GoalIsObstacle(usize, usize),

    #[error("Aucun chemin valide n'a pu être trouvé entre le départ et l'arrivée.")]
    NoPathFound,
}

/// Coordonnées 2D sur la grille matricielle.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Coord {
    pub x: usize,
    pub y: usize,
}

impl Coord {
    #[inline]
    pub const fn new(x: usize, y: usize) -> Self {
        Self { x, y }
    }
}

impl fmt::Display for Coord {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "({}, {})", self.x, self.y)
    }
}

/// Mode de déplacement autorisé sur la grille.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MovementMode {
    /// 4 directions cardinales (coût unitaire 10).
    FourWay,
    /// 8 directions avec diagonales (cardinaux: 10, diagonaux: 14).
    EightWay,
}

/// Grille matricielle 2D stockée de manière contiguë en mémoire.
#[derive(Debug, Clone)]
pub struct Grid {
    width: usize,
    height: usize,
    /// Stockage plat : true = obstacle, false = franchissable.
    obstacles: Vec<bool>,
}

impl Grid {
    /// Crée une nouvelle grille vide sans obstacle.
    pub fn new(width: usize, height: usize) -> Result<Self, PathfindingError> {
        if width == 0 || height == 0 {
            return Err(PathfindingError::InvalidGridDimensions);
        }
        let total_cells = width.checked_mul(height).ok_or(PathfindingError::InvalidGridDimensions)?;
        Ok(Self {
            width,
            height,
            obstacles: vec![false; total_cells],
        })
    }

    /// Construit une grille à partir d'une représentation textuelle ASCII.
    /// '#' représente un obstacle, '.' ou ' ' représente un espace libre.
    pub fn from_ascii(ascii_map: &str) -> Result<Self, PathfindingError> {
        let lines: Vec<&str> = ascii_map.lines().map(str::trim).filter(|l| !l.is_empty()).collect();
        if lines.is_empty() {
            return Err(PathfindingError::InvalidGridDimensions);
        }
        let height = lines.len();
        let width = lines[0].len();

        let mut grid = Self::new(width, height)?;
        for (y, line) in lines.iter().enumerate() {
            for (x, ch) in line.chars().enumerate() {
                if x < width && (ch == '#' || ch == 'X') {
                    grid.set_obstacle(Coord::new(x, y), true);
                }
            }
        }
        Ok(grid)
    }

    #[inline]
    pub fn width(&self) -> usize {
        self.width
    }

    #[inline]
    pub fn height(&self) -> usize {
        self.height
    }

    #[inline]
    pub fn total_cells(&self) -> usize {
        self.width * self.height
    }

    #[inline]
    pub fn is_in_bounds(&self, coord: Coord) -> bool {
        coord.x < self.width && coord.y < self.height
    }

    #[inline]
    pub fn to_index(&self, coord: Coord) -> usize {
        coord.y * self.width + coord.x
    }

    #[inline]
    pub fn to_coord(&self, index: usize) -> Coord {
        Coord::new(index % self.width, index / self.width)
    }

    pub fn set_obstacle(&mut self, coord: Coord, is_obstacle: bool) {
        if self.is_in_bounds(coord) {
            let idx = self.to_index(coord);
            self.obstacles[idx] = is_obstacle;
        }
    }

    #[inline]
    pub fn is_obstacle(&self, coord: Coord) -> bool {
        if !self.is_in_bounds(coord) {
            return true;
        }
        self.obstacles[self.to_index(coord)]
    }

    #[inline]
    pub fn is_obstacle_by_index(&self, index: usize) -> bool {
        if index >= self.obstacles.len() {
            return true;
        }
        self.obstacles[index]
    }

    /// Retourne les voisins valides et le coût de transition associé.
    pub fn neighbors(&self, coord: Coord, mode: MovementMode) -> Vec<(Coord, u64)> {
        let mut result = Vec::with_capacity(8);
        let x = coord.x as isize;
        let y = coord.y as isize;

        // Déplacements orthogonaux (coût 10)
        let orthogonal_offsets = [(0, -1), (0, 1), (-1, 0), (1, 0)];
        for (dx, dy) in orthogonal_offsets {
            let nx = x + dx;
            let ny = y + dy;
            if nx >= 0 && nx < self.width as isize && ny >= 0 && ny < self.height as isize {
                let ncoord = Coord::new(nx as usize, ny as usize);
                if !self.is_obstacle(ncoord) {
                    result.push((ncoord, 10));
                }
            }
        }

        // Déplacements diagonaux (coût 14 ≈ 10 * √2)
        if mode == MovementMode::EightWay {
            let diagonal_offsets = [(-1, -1), (1, -1), (-1, 1), (1, 1)];
            for (dx, dy) in diagonal_offsets {
                let nx = x + dx;
                let ny = y + dy;
                if nx >= 0 && nx < self.width as isize && ny >= 0 && ny < self.height as isize {
                    let ncoord = Coord::new(nx as usize, ny as usize);
                    // Règle stricte anti-coupe-coin : les deux cellules adjacentes orthogonales doivent être libres
                    let corner_a = Coord::new(nx as usize, y as usize);
                    let corner_b = Coord::new(x as usize, ny as usize);
                    if !self.is_obstacle(ncoord)
                        && !self.is_obstacle(corner_a)
                        && !self.is_obstacle(corner_b)
                    {
                        result.push((ncoord, 14));
                    }
                }
            }
        }

        result
    }
}

/// Nœud stocké dans la file de priorité du A*.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct SearchNode {
    index: usize,
    f_score: u64,
    g_score: u64,
}

impl Ord for SearchNode {
    fn cmp(&self, other: &Self) -> CmpOrdering {
        // Ordre inversé pour Min-Heap (f_score le plus bas prioritaire)
        other
            .f_score
            .cmp(&self.f_score)
            .then_with(|| other.g_score.cmp(&self.g_score))
    }
}

impl PartialOrd for SearchNode {
    fn partial_cmp(&self, other: &Self) -> Option<CmpOrdering> {
        Some(self.cmp(other))
    }
}

/// Estimation heuristique admissible et cohérente.
fn heuristic(a: Coord, b: Coord, mode: MovementMode) -> u64 {
    let dx = (a.x as isize - b.x as isize).unsigned_abs() as u64;
    let dy = (a.y as isize - b.y as isize).unsigned_abs() as u64;

    match mode {
        MovementMode::FourWay => 10 * (dx + dy),
        MovementMode::EightWay => {
            let min_d = dx.min(dy);
            let max_d = dx.max(dy);
            // Octile distance : 14 * min(dx, dy) + 10 * (max(dx, dy) - min(dx, dy))
            14 * min_d + 10 * (max_d - min_d)
        }
    }
}

/// Statistiques de recherche multithreadée.
#[derive(Debug, Clone)]
pub struct SearchStatistics {
    pub forward_nodes_expanded: usize,
    pub backward_nodes_expanded: usize,
    pub elapsed_microseconds: u128,
}

/// Résultat du calcul de chemin.
#[derive(Debug, Clone)]
pub struct PathResult {
    pub path: Vec<Coord>,
    pub total_cost: u64,
    pub statistics: SearchStatistics,
}

/// Moteur de calcul de plus court chemin A* bidirectionnel multithreadé.
pub struct MultithreadedBidirectionalAStar<'a> {
    grid: &'a Grid,
    mode: MovementMode,
}

impl<'a> MultithreadedBidirectionalAStar<'a> {
    pub fn new(grid: &'a Grid, mode: MovementMode) -> Self {
        Self { grid, mode }
    }

    /// Exécute la recherche de plus court chemin en parallèle avec deux threads.
    pub fn find_path(
        &self,
        start: Coord,
        goal: Coord,
    ) -> Result<PathResult, PathfindingError> {
        let timer = Instant::now();

        // 1. Validation rigoureuse des entrées
        if !self.grid.is_in_bounds(start) {
            return Err(PathfindingError::StartOutOfBounds(start.x, start.y));
        }
        if !self.grid.is_in_bounds(goal) {
            return Err(PathfindingError::GoalOutOfBounds(goal.x, goal.y));
        }
        if self.grid.is_obstacle(start) {
            return Err(PathfindingError::StartIsObstacle(start.x, start.y));
        }
        if self.grid.is_obstacle(goal) {
            return Err(PathfindingError::GoalIsObstacle(goal.x, goal.y));
        }

        // Cas trivial : départ = arrivée
        if start == goal {
            return Ok(PathResult {
                path: vec![start],
                total_cost: 0,
                statistics: SearchStatistics {
                    forward_nodes_expanded: 0,
                    backward_nodes_expanded: 0,
                    elapsed_microseconds: timer.elapsed().as_micros(),
                },
            });
        }

        let total_cells = self.grid.total_cells();
        let start_idx = self.grid.to_index(start);
        let goal_idx = self.grid.to_index(goal);

        // 2. Structures d'états partagées entre les deux threads
        let forward_g: Arc<Vec<AtomicU64>> = Arc::new(
            (0..total_cells).map(|_| AtomicU64::new(u64::MAX)).collect(),
        );
        let backward_g: Arc<Vec<AtomicU64>> = Arc::new(
            (0..total_cells).map(|_| AtomicU64::new(u64::MAX)).collect(),
        );

        let best_cost = Arc::new(AtomicU64::new(u64::MAX));
        let meeting_node = Arc::new(Mutex::new(None::<usize>));
        let stop_signal = Arc::new(AtomicBool::new(false));

        let forward_min_f = Arc::new(AtomicU64::new(0));
        let backward_min_f = Arc::new(AtomicU64::new(0));

        forward_g[start_idx].store(0, Ordering::Release);
        backward_g[goal_idx].store(0, Ordering::Release);

        // 3. Exécution concurrente via std::thread::scope
        let (forward_result, backward_result) = thread::scope(|s| {
            // Worker 1 : Forward (Start -> Goal)
            let f_forward_g = Arc::clone(&forward_g);
            let f_backward_g = Arc::clone(&backward_g);
            let f_best_cost = Arc::clone(&best_cost);
            let f_meeting_node = Arc::clone(&meeting_node);
            let f_stop_signal = Arc::clone(&stop_signal);
            let f_forward_min_f = Arc::clone(&forward_min_f);
            let f_backward_min_f = Arc::clone(&backward_min_f);

            let forward_handle = s.spawn(move || {
                let mut open_set = BinaryHeap::new();
                let mut came_from = vec![None; total_cells];
                let mut expanded_count = 0usize;

                let h_start = heuristic(start, goal, self.mode);
                open_set.push(SearchNode {
                    index: start_idx,
                    f_score: h_start,
                    g_score: 0,
                });

                while let Some(current) = open_set.pop() {
                    if f_stop_signal.load(Ordering::Relaxed) {
                        break;
                    }

                    let curr_g = f_forward_g[current.index].load(Ordering::Acquire);
                    if current.g_score > curr_g {
                        continue;
                    }

                    expanded_count += 1;
                    f_forward_min_f.store(current.f_score, Ordering::Release);

                    // Vérification de la rencontre avec le front opposé
                    let opp_g = f_backward_g[current.index].load(Ordering::Acquire);
                    if opp_g != u64::MAX {
                        let potential_cost = current.g_score.saturating_add(opp_g);
                        let mut current_best = f_best_cost.load(Ordering::Acquire);
                        while potential_cost < current_best {
                            match f_best_cost.compare_exchange_weak(
                                current_best,
                                potential_cost,
                                Ordering::Release,
                                Ordering::Acquire,
                            ) {
                                Ok(_) => {
                                    let mut m = f_meeting_node.lock();
                                    *m = Some(current.index);
                                    break;
                                }
                                Err(actual) => current_best = actual,
                            }
                        }
                    }

                    // Condition d'arrêt pour l'optimalité
                    let curr_best = f_best_cost.load(Ordering::Acquire);
                    let opp_min_f = f_backward_min_f.load(Ordering::Acquire);
                    if curr_best != u64::MAX
                        && (current.f_score >= curr_best && opp_min_f >= curr_best
                            || current.f_score.saturating_add(opp_min_f) >= curr_best)
                    {
                        f_stop_signal.store(true, Ordering::Release);
                        break;
                    }

                    let curr_coord = self.grid.to_coord(current.index);
                    for (next_coord, move_cost) in self.grid.neighbors(curr_coord, self.mode) {
                        let next_idx = self.grid.to_index(next_coord);
                        let tentative_g = current.g_score.saturating_add(move_cost);

                        let mut existing_g = f_forward_g[next_idx].load(Ordering::Acquire);
                        if tentative_g < existing_g {
                            let mut updated = false;
                            while tentative_g < existing_g {
                                match f_forward_g[next_idx].compare_exchange_weak(
                                    existing_g,
                                    tentative_g,
                                    Ordering::Release,
                                    Ordering::Acquire,
                                ) {
                                    Ok(_) => {
                                        came_from[next_idx] = Some(current.index);
                                        updated = true;
                                        break;
                                    }
                                    Err(actual) => existing_g = actual,
                                }
                            }

                            if updated {
                                let h = heuristic(next_coord, goal, self.mode);
                                open_set.push(SearchNode {
                                    index: next_idx,
                                    f_score: tentative_g.saturating_add(h),
                                    g_score: tentative_g,
                                });
                            }
                        }
                    }
                }

                (came_from, expanded_count)
            });

            // Worker 2 : Backward (Goal -> Start)
            let b_forward_g = Arc::clone(&forward_g);
            let b_backward_g = Arc::clone(&backward_g);
            let b_best_cost = Arc::clone(&best_cost);
            let b_meeting_node = Arc::clone(&meeting_node);
            let b_stop_signal = Arc::clone(&stop_signal);
            let b_forward_min_f = Arc::clone(&forward_min_f);
            let b_backward_min_f = Arc::clone(&backward_min_f);

            let backward_handle = s.spawn(move || {
                let mut open_set = BinaryHeap::new();
                let mut came_from = vec![None; total_cells];
                let mut expanded_count = 0usize;

                let h_goal = heuristic(goal, start, self.mode);
                open_set.push(SearchNode {
                    index: goal_idx,
                    f_score: h_goal,
                    g_score: 0,
                });

                while let Some(current) = open_set.pop() {
                    if b_stop_signal.load(Ordering::Relaxed) {
                        break;
                    }

                    let curr_g = b_backward_g[current.index].load(Ordering::Acquire);
                    if current.g_score > curr_g {
                        continue;
                    }

                    expanded_count += 1;
                    b_backward_min_f.store(current.f_score, Ordering::Release);

                    // Vérification de la rencontre avec le front forward
                    let opp_g = b_forward_g[current.index].load(Ordering::Acquire);
                    if opp_g != u64::MAX {
                        let potential_cost = current.g_score.saturating_add(opp_g);
                        let mut current_best = b_best_cost.load(Ordering::Acquire);
                        while potential_cost < current_best {
                            match b_best_cost.compare_exchange_weak(
                                current_best,
                                potential_cost,
                                Ordering::Release,
                                Ordering::Acquire,
                            ) {
                                Ok(_) => {
                                    let mut m = b_meeting_node.lock();
                                    *m = Some(current.index);
                                    break;
                                }
                                Err(actual) => current_best = actual,
                            }
                        }
                    }

                    // Condition d'arrêt pour l'optimalité
                    let curr_best = b_best_cost.load(Ordering::Acquire);
                    let opp_min_f = b_forward_min_f.load(Ordering::Acquire);
                    if curr_best != u64::MAX
                        && (current.f_score >= curr_best && opp_min_f >= curr_best
                            || current.f_score.saturating_add(opp_min_f) >= curr_best)
                    {
                        b_stop_signal.store(true, Ordering::Release);
                        break;
                    }

                    let curr_coord = self.grid.to_coord(current.index);
                    for (next_coord, move_cost) in self.grid.neighbors(curr_coord, self.mode) {
                        let next_idx = self.grid.to_index(next_coord);
                        let tentative_g = current.g_score.saturating_add(move_cost);

                        let mut existing_g = b_backward_g[next_idx].load(Ordering::Acquire);
                        if tentative_g < existing_g {
                            let mut updated = false;
                            while tentative_g < existing_g {
                                match b_backward_g[next_idx].compare_exchange_weak(
                                    existing_g,
                                    tentative_g,
                                    Ordering::Release,
                                    Ordering::Acquire,
                                ) {
                                    Ok(_) => {
                                        came_from[next_idx] = Some(current.index);
                                        updated = true;
                                        break;
                                    }
                                    Err(actual) => existing_g = actual,
                                }
                            }

                            if updated {
                                let h = heuristic(next_coord, start, self.mode);
                                open_set.push(SearchNode {
                                    index: next_idx,
                                    f_score: tentative_g.saturating_add(h),
                                    g_score: tentative_g,
                                });
                            }
                        }
                    }
                }

                (came_from, expanded_count)
            });

            (forward_handle.join(), backward_handle.join())
        });

        let (forward_came_from, forward_expanded) = match forward_result {
            Ok(res) => res,
            Err(_) => return Err(PathfindingError::NoPathFound),
        };

        let (backward_came_from, backward_expanded) = match backward_result {
            Ok(res) => res,
            Err(_) => return Err(PathfindingError::NoPathFound),
        };

        // 4. Reconstitution du chemin
        let final_best_cost = best_cost.load(Ordering::Acquire);
        let meeting_idx_opt = *meeting_node.lock();

        let meeting_idx = match (final_best_cost, meeting_idx_opt) {
            (c, Some(idx)) if c != u64::MAX => idx,
            _ => return Err(PathfindingError::NoPathFound),
        };

        // Reconstitution côté Forward : meeting_idx -> start
        let mut forward_path = Vec::new();
        let mut curr = meeting_idx;
        forward_path.push(self.grid.to_coord(curr));
        while curr != start_idx {
            if let Some(parent) = forward_came_from[curr] {
                curr = parent;
                forward_path.push(self.grid.to_coord(curr));
            } else {
                break;
            }
        }
        forward_path.reverse();

        // Reconstitution côté Backward : meeting_idx -> goal
        let mut backward_path = Vec::new();
        let mut curr_b = meeting_idx;
        while curr_b != goal_idx {
            if let Some(parent) = backward_came_from[curr_b] {
                curr_b = parent;
                backward_path.push(self.grid.to_coord(curr_b));
            } else {
                break;
            }
        }

        // Concaténation complète du chemin optimal (Start -> M -> Goal)
        forward_path.extend(backward_path);

        Ok(PathResult {
            path: forward_path,
            total_cost: final_best_cost,
            statistics: SearchStatistics {
                forward_nodes_expanded: forward_expanded,
                backward_nodes_expanded: backward_expanded,
                elapsed_microseconds: timer.elapsed().as_micros(),
            },
        })
    }
}

/// Affiche la carte ASCII enrichie du chemin trouvé.
pub fn render_ascii_map(grid: &Grid, start: Coord, goal: Coord, path: &[Coord]) -> String {
    let mut display_chars = vec![vec!['.'; grid.width()]; grid.height()];

    for (y, row) in display_chars.iter_mut().enumerate() {
        for (x, ch) in row.iter_mut().enumerate() {
            if grid.is_obstacle(Coord::new(x, y)) {
                *ch = '#';
            }
        }
    }

    for coord in path {
        if grid.is_in_bounds(*coord) {
            display_chars[coord.y][coord.x] = '*';
        }
    }

    display_chars[start.y][start.x] = 'S';
    display_chars[goal.y][goal.x] = 'G';

    let mut output = String::new();
    for row in display_chars {
        output.extend(row);
        output.push('\n');
    }
    output
}

