// src/main.rs
use rand::seq::SliceRandom;
use rand::Rng;
use std::fmt;

/// Erreurs spécifiques liées à la configuration et l'exécution du réseau de neurones.
#[derive(Debug, PartialEq, Eq)]
pub enum NetError {
    DimensionMismatch { expected: usize, found: usize },
    EmptyNetwork,
    InvalidArchitecture(String),
    EmptyDataset,
}

impl fmt::Display for NetError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::DimensionMismatch { expected, found } => {
                write!(f, "Incompatibilité de dimensions : attendu {expected}, reçu {found}")
            }
            Self::EmptyNetwork => write!(f, "Le réseau ne contient aucune couche"),
            Self::InvalidArchitecture(msg) => write!(f, "Architecture invalide : {msg}"),
            Self::EmptyDataset => write!(f, "Le jeu de données est vide"),
        }
    }
}

impl std::error::Error for NetError {}

/// Fonctions d'activation disponibles pour les couches.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Activation {
    Sigmoid,
    Tanh,
    ReLU,
}

impl Activation {
    /// Applique la fonction d'activation sur un scalaire.
    #[inline]
    pub fn apply(&self, x: f64) -> f64 {
        match self {
            Self::Sigmoid => 1.0 / (1.0 + (-x).exp()),
            Self::Tanh => x.tanh(),
            Self::ReLU => {
                if x > 0.0 {
                    x
                } else {
                    0.0
                }
            }
        }
    }

    /// Calcule la dérivée par rapport à l'entrée pré-activation `z`,
    /// avec la valeur post-activation `a` fournie pour optimiser le calcul si possible.
    #[inline]
    pub fn derivative(&self, z: f64, a: f64) -> f64 {
        match self {
            Self::Sigmoid => a * (1.0 - a),
            Self::Tanh => 1.0 - a * a,
            Self::ReLU => {
                if z > 0.0 {
                    1.0
                } else {
                    0.0
                }
            }
        }
    }
}

/// Une couche dense (entièrement connectée).
#[derive(Debug, Clone)]
pub struct Layer {
    pub input_dim: usize,
    pub output_dim: usize,
    /// Poids ordonnés par ligne : taille = output_dim * input_dim.
    /// Le poids reliant l'entrée j au neurone i se situe à l'index `i * input_dim + j`.
    pub weights: Vec<f64>,
    /// Biais : taille = output_dim.
    pub biases: Vec<f64>,
    pub activation: Activation,
}

impl Layer {
    /// Crée une nouvelle couche initialisée selon He (pour ReLU) ou Xavier/Glorot (pour Sigmoid/Tanh).
    pub fn new<R: Rng>(
        input_dim: usize,
        output_dim: usize,
        activation: Activation,
        rng: &mut R,
    ) -> Result<Self, NetError> {
        if input_dim == 0 || output_dim == 0 {
            return Err(NetError::InvalidArchitecture(
                "Les dimensions d'entrée et de sortie d'une couche doivent être strictement positives."
                    .to_string(),
            ));
        }

        let bound = match activation {
            Activation::ReLU => (2.0 / input_dim as f64).sqrt(),
            Activation::Sigmoid | Activation::Tanh => {
                (6.0 / (input_dim + output_dim) as f64).sqrt()
            }
        };

        let weights_count = output_dim * input_dim;
        let mut weights = Vec::with_capacity(weights_count);
        for _ in 0..weights_count {
            weights.push(rng.gen_range(-bound..=bound));
        }

        let biases = vec![0.0; output_dim];

        Ok(Self {
            input_dim,
            output_dim,
            weights,
            biases,
            activation,
        })
    }

    /// Propagation avant d'un vecteur d'entrée à travers la couche.
    /// Retourne `(z, a)` où `z = W * x + b` et `a = activation(z)`.
    pub fn forward(&self, input: &[f64]) -> Result<(Vec<f64>, Vec<f64>), NetError> {
        if input.len() != self.input_dim {
            return Err(NetError::DimensionMismatch {
                expected: self.input_dim,
                found: input.len(),
            });
        }

        let mut z = Vec::with_capacity(self.output_dim);
        let mut a = Vec::with_capacity(self.output_dim);

        for (i, &bias) in self.biases.iter().enumerate() {
            let row_offset = i * self.input_dim;
            let dot_product: f64 = self.weights[row_offset..row_offset + self.input_dim]
                .iter()
                .zip(input.iter())
                .map(|(&w, &x)| w * x)
                .sum();

            let z_val = dot_product + bias;
            z.push(z_val);
            a.push(self.activation.apply(z_val));
        }

        Ok((z, a))
    }
}

/// Réseau de neurones multicouche séquentiel.
#[derive(Debug, Clone)]
pub struct NeuralNetwork {
    pub layers: Vec<Layer>,
}

impl NeuralNetwork {
    /// Construit et valide le réseau séquentiel.
    pub fn new(layers: Vec<Layer>) -> Result<Self, NetError> {
        if layers.is_empty() {
            return Err(NetError::EmptyNetwork);
        }

        for i in 0..layers.len() - 1 {
            if layers[i].output_dim != layers[i + 1].input_dim {
                return Err(NetError::InvalidArchitecture(format!(
                    "Incohérence entre la couche {i} (sortie {}) et la couche {} (entrée {})",
                    layers[i].output_dim,
                    i + 1,
                    layers[i + 1].input_dim
                )));
            }
        }

        // Pour la classification binaire avec la BCE simplifiée, la couche finale doit être scalaire et sigmoïde
        let last_layer = &layers[layers.len() - 1];
        if last_layer.output_dim != 1 {
            return Err(NetError::InvalidArchitecture(
                "La dernière couche doit avoir exactement 1 neurone de sortie pour la classification binaire."
                    .to_string(),
            ));
        }
        if last_layer.activation != Activation::Sigmoid {
            return Err(NetError::InvalidArchitecture(
                "La dernière couche doit impérativement utiliser l'activation Sigmoïde."
                    .to_string(),
            ));
        }

        Ok(Self { layers })
    }

    /// Effectue la propagation avant complète en conservant les états intermédiaires `(z, a)`.
    pub fn forward_trace(
        &self,
        input: &[f64],
    ) -> Result<(Vec<Vec<f64>>, Vec<Vec<f64>>), NetError> {
        let mut all_z = Vec::with_capacity(self.layers.len());
        let mut all_a = Vec::with_capacity(self.layers.len() + 1);

        all_a.push(input.to_vec());

        let mut current_input = input;
        for layer in &self.layers {
            let (z, a) = layer.forward(current_input)?;
            all_z.push(z);
            all_a.push(a);
            current_input = all_a.last().map(|v| v.as_slice()).unwrap_or(&[]);
        }

        Ok((all_z, all_a))
    }

    /// Prédit la probabilité $\hat{y} \in ]0, 1[$ pour une entrée donnée.
    pub fn predict(&self, input: &[f64]) -> Result<f64, NetError> {
        let (_, all_a) = self.forward_trace(input)?;
        match all_a.last().and_then(|out| out.first()) {
            Some(&y_hat) => Ok(y_hat),
            None => Err(NetError::EmptyNetwork),
        }
    }

    /// Calcule la fonction de coût d'entropie croisée binaire (Binary Cross-Entropy).
    #[inline]
    pub fn binary_cross_entropy(y_true: f64, y_pred: f64) -> f64 {
        const EPSILON: f64 = 1e-15;
        let p = y_pred.clamp(EPSILON, 1.0 - EPSILON);
        -(y_true * p.ln() + (1.0 - y_true) * (1.0 - p).ln())
    }

    /// Entraîne le réseau de neurones via la descente de gradient par mini-lots.
    pub fn train<R: Rng>(
        &mut self,
        dataset: &[(Vec<f64>, f64)],
        epochs: usize,
        batch_size: usize,
        learning_rate: f64,
        rng: &mut R,
    ) -> Result<Vec<f64>, NetError> {
        if dataset.is_empty() {
            return Err(NetError::EmptyDataset);
        }
        if batch_size == 0 {
            return Err(NetError::InvalidArchitecture(
                "La taille du mini-lot doit être supérieure à 0.".to_string(),
            ));
        }

        let mut indices: Vec<usize> = (0..dataset.len()).collect();
        let mut loss_history = Vec::with_capacity(epochs);

        for _ in 0..epochs {
            indices.shuffle(rng);
            let mut epoch_loss = 0.0;

            for chunk in indices.chunks(batch_size) {
                // Accumulateurs de gradients pour le batch
                let mut weight_grads: Vec<Vec<f64>> = self
                    .layers
                    .iter()
                    .map(|l| vec![0.0; l.weights.len()])
                    .collect();
                let mut bias_grads: Vec<Vec<f64>> = self
                    .layers
                    .iter()
                    .map(|l| vec![0.0; l.biases.len()])
                    .collect();

                let current_batch_size = chunk.len() as f64;

                for &idx in chunk {
                    let (x, y) = &dataset[idx];
                    let (all_z, all_a) = self.forward_trace(x)?;
                    let y_pred = all_a[all_a.len() - 1][0];
                    epoch_loss += Self::binary_cross_entropy(*y, y_pred);

                    // Backpropagation pour l'échantillon
                    // Pour Sigmoïde + BCE : delta_sortie = y_pred - y
                    let mut delta = vec![y_pred - y];

                    for l in (0..self.layers.len()).rev() {
                        let layer = &self.layers[l];
                        let a_prev = &all_a[l];

                        // Gradient par rapport aux poids : dW = delta * a_prev^T
                        for i in 0..layer.output_dim {
                            let d_i = delta[i];
                            let row_offset = i * layer.input_dim;
                            for j in 0..layer.input_dim {
                                weight_grads[l][row_offset + j] += d_i * a_prev[j];
                            }
                            bias_grads[l][i] += d_i;
                        }

                        // Propagation du delta vers la couche précédente si ce n'est pas la première
                        if l > 0 {
                            let prev_layer = &self.layers[l - 1];
                            let mut prev_delta = vec![0.0; layer.input_dim];

                            for j in 0..layer.input_dim {
                                let mut sum = 0.0;
                                for i in 0..layer.output_dim {
                                    sum += self.layers[l].weights[i * layer.input_dim + j] * delta[i];
                                }
                                let z_prev = all_z[l - 1][j];
                                let a_prev_val = all_a[l][j];
                                let f_prime = prev_layer.activation.derivative(z_prev, a_prev_val);
                                prev_delta[j] = sum * f_prime;
                            }
                            delta = prev_delta;
                        }
                    }
                }

                // Mise à jour des poids et des biais (SGD avec moyenne sur le mini-lot)
                let factor = learning_rate / current_batch_size;
                for (l, layer) in self.layers.iter_mut().enumerate() {
                    for (w, &gw) in layer.weights.iter_mut().zip(&weight_grads[l]) {
                        *w -= factor * gw;
                    }
                    for (b, &gb) in layer.biases.iter_mut().zip(&bias_grads[l]) {
                        *b -= factor * gb;
                    }
                }
            }

            loss_history.push(epoch_loss / dataset.len() as f64);
        }

        Ok(loss_history)
    }

    /// Évalue les performances du réseau sur un jeu de données.
    pub fn evaluate(
        &self,
        dataset: &[(Vec<f64>, f64)],
        threshold: f64,
    ) -> Result<EvaluationMetrics, NetError> {
        if dataset.is_empty() {
            return Err(NetError::EmptyDataset);
        }

        let mut total_loss = 0.0;
        let mut tp = 0;
        let mut fp = 0;
        let mut tn = 0;
        let mut fn_count = 0;

        for (x, y) in dataset {
            let y_pred = self.predict(x)?;
            total_loss += Self::binary_cross_entropy(*y, y_pred);

            let predicted_class = if y_pred >= threshold { 1.0 } else { 0.0 };
            match (*y >= 0.5, predicted_class >= 0.5) {
                (true, true) => tp += 1,
                (false, true) => fp += 1,
                (false, false) => tn += 1,
                (true, false) => fn_count += 1,
            }
        }

        let total = dataset.len() as f64;
        let accuracy = (tp + tn) as f64 / total;
        let precision = if tp + fp > 0 {
            tp as f64 / (tp + fp) as f64
        } else {
            0.0
        };
        let recall = if tp + fn_count > 0 {
            tp as f64 / (tp + fn_count) as f64
        } else {
            0.0
        };
        let f1 = if precision + recall > 0.0 {
            2.0 * precision * recall / (precision + recall)
        } else {
            0.0
        };

        Ok(EvaluationMetrics {
            loss: total_loss / total,
            accuracy,
            precision,
            recall,
            f1_score: f1,
            true_positives: tp,
            false_positives: fp,
            true_negatives: tn,
            false_negatives: fn_count,
        })
    }
}

/// Métriques de performance et matrice de confusion.
#[derive(Debug, Clone)]
pub struct EvaluationMetrics {
    pub loss: f64,
    pub accuracy: f64,
    pub precision: f64,
    pub recall: f64,
    pub f1_score: f64,
    pub true_positives: usize,
    pub false_positives: usize,
    pub true_negatives: usize,
    pub false_negatives: usize,
}

impl fmt::Display for EvaluationMetrics {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        writeln!(f, "  Perte moyenne (BCE) : {:.5}", self.loss)?;
        writeln!(f, "  Exactitude (Accuracy): {:.2}%", self.accuracy * 100.0)?;
        writeln!(f, "  Précision            : {:.2}%", self.precision * 100.0)?;
        writeln!(f, "  Rappel (Recall)      : {:.2}%", self.recall * 100.0)?;
        writeln!(f, "  F1-Score             : {:.4}", self.f1_score)?;
        writeln!(f, "  Matrice de confusion :")?;
        writeln!(
            f,
            "    ┌─────────────────┬─────────────────┐\n    │ VP: {:<12}│ FP: {:<12}│\n    ├─────────────────┼─────────────────┤\n    │ FN: {:<12}│ VN: {:<12}│\n    └─────────────────┴─────────────────┘",
            self.true_positives, self.false_positives, self.false_negatives, self.true_negatives
        )
    }
}

/// Génère un jeu de données 2D synthétique : deux cercles concentriques.
/// Classe 1 si le point est dans le cercle intérieur, Classe 0 s'il est dans la couronne extérieure.
pub fn generate_concentric_circles<R: Rng>(
    samples_per_class: usize,
    noise: f64,
    rng: &mut R,
) -> Vec<(Vec<f64>, f64)> {
    let mut data = Vec::with_capacity(samples_per_class * 2);

    // Classe 1 : cercle intérieur (rayon ~ 0.5)
    for _ in 0..samples_per_class {
        let r = 0.5 * (rng.gen::<f64>()).sqrt();
        let theta = rng.gen_range(0.0..std::f64::consts::TAU);
        let x = r * theta.cos() + rng.gen_range(-noise..=noise);
        let y = r * theta.sin() + rng.gen_range(-noise..=noise);
        data.push((vec![x, y], 1.0));
    }

    // Classe 0 : anneau extérieur (rayon ~ 1.0)
    for _ in 0..samples_per_class {
        let r = 0.85 + 0.35 * (rng.gen::<f64>()).sqrt();
        let theta = rng.gen_range(0.0..std::f64::consts::TAU);
        let x = r * theta.cos() + rng.gen_range(-noise..=noise);
        let y = r * theta.sin() + rng.gen_range(-noise..=noise);
        data.push((vec![x, y], 0.0));
    }

    data
}

/// Affiche une carte ASCII de la frontière de décision sur la grille [-1.3, 1.3] x [-1.3, 1.3].
pub fn render_decision_boundary(net: &NeuralNetwork, resolution: usize) {
    println!("\n--- Frontière de décision apprise dans l'espace 2D (ASCII) ---");
    println!("Légende : '#' = Classe 1 (Prédit > 0.5), '.' = Classe 0 (Prédit <= 0.5)\n");

    let min_val = -1.3;
    let max_val = 1.3;
    let step = (max_val - min_val) / (resolution as f64);

    for row in 0..resolution {
        let y = max_val - (row as f64) * step;
        let mut line = String::with_capacity(resolution);
        for col in 0..resolution {
            let x = min_val + (col as f64) * step;
            match net.predict(&[x, y]) {
                Ok(prob) => {
                    if prob >= 0.5 {
                        line.push('#');
                    } else {
                        line.push('.');
                    }
                }
                Err(_) => line.push('?'),
            }
        }
        println!("{line}");
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut rng = rand::thread_rng();

    println!("=================================================================");
    println!("  Simulateur de Réseau de Neurones Multicouche (MLP From Scratch)");
    println!("  Classification Binaire - Sans Crate de Deep Learning");
    println!("=================================================================\n");

    // 1. Génération des jeux de données d'entraînement et de test
    println!("[1/4] Génération des données synthétiques (cercles concentriques 2D)...");
    let train_data = generate_concentric_circles(300, 0.05, &mut rng);
    let test_data = generate_concentric_circles(100, 0.05, &mut rng);
    println!(
        "      Jeu d'entraînement : {} échantillons ({} positifs, {} négatifs)",
        train_data.len(),
        train_data.iter().filter(|(_, y)| *y > 0.5).count(),
        train_data.iter().filter(|(_, y)| *y <= 0.5).count()
    );
    println!(
        "      Jeu de test         : {} échantillons",
        test_data.len()
    );

    // 2. Construction de l'architecture MLP
    // Architecture : 2 -> 8 (ReLU) -> 4 (Tanh) -> 1 (Sigmoid)
    println!("\n[2/4] Initialisation du réseau de neurones multicouche...");
    let layer1 = Layer::new(2, 8, Activation::ReLU, &mut rng)?;
    let layer2 = Layer::new(8, 4, Activation::Tanh, &mut rng)?;
    let layer3 = Layer::new(4, 1, Activation::Sigmoid, &mut rng)?;

    let mut model = NeuralNetwork::new(vec![layer1, layer2, layer3])?;
    println!("      Architecture : [2] -(ReLU)-> [8] -(Tanh)-> [4] -(Sigmoïde)-> [1]");

    // Évaluation avant entraînement
    let initial_metrics = model.evaluate(&test_data, 0.5)?;
    println!("\n--- Métriques initiales (poids aléatoires) ---");
    println!("{initial_metrics}");

    // 3. Entraînement
    let epochs = 500;
    let batch_size = 32;
    let learning_rate = 0.15;

    println!(
        "[3/4] Démarrage de l'entraînement (Epochs: {epochs}, Batch size: {batch_size}, LR: {learning_rate})..."
    );
    let loss_history = model.train(&train_data, epochs, batch_size, learning_rate, &mut rng)?;

    println!("      Perte au début (Epoch 1)    : {:.5}", loss_history[0]);
    println!(
        "      Perte à mi-parcours (Epoch {}) : {:.5}",
        epochs / 2,
        loss_history[epochs / 2 - 1]
    );
    println!(
        "      Perte finale (Epoch {epochs})     : {:.5}",
        loss_history[epochs - 1]
    );

    // 4. Évaluation sur l'ensemble de test
    println!("\n[4/4] Évaluation finale sur l'ensemble de test...");
    let final_metrics = model.evaluate(&test_data, 0.5)?;
    println!("{final_metrics}");

    // Affichage de la carte de décision
    render_decision_boundary(&model, 25);

    println!("\nSimulation terminée avec succès !");
    Ok(())
}

