```rust
// src/main.rs
use std::env;
use std::f64::consts::{E, PI, TAU};
use std::fmt;
use thiserror::Error;

/// Erreurs possibles lors de l'analyse et de l'évaluation RPN.
#[derive(Debug, Error, Clone, PartialEq)]
pub enum RpnError {
    #[error("Sous-dépassement de pile pour l'opération '{op}' : requis {required}, disponible {actual}")]
    StackUnderflow {
        required: usize,
        actual: usize,
        op: &'static str,
    },

    #[error("Division par zéro")]
    DivisionByZero,

    #[error("Erreur de domaine mathématique pour '{op}' avec l'argument {arg} : {reason}")]
    DomainError {
        op: &'static str,
        arg: f64,
        reason: &'static str,
    },

    #[error("Jeton invalide ou non reconnu : '{0}'")]
    InvalidToken(String),

    #[error("Expression vide")]
    EmptyExpression,
}

/// Entrée d'historique conservant la commande évaluée et l'état de la pile résultante.
#[derive(Debug, Clone, PartialEq)]
pub struct HistoryEntry {
    pub id: usize,
    pub input: String,
    pub result: Result<Vec<f64>, RpnError>,
}

impl fmt::Display for HistoryEntry {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match &self.result {
            Ok(stack) => write!(
                f,
                "[{:>3}] {:<25} => pile: {:?}",
                self.id, self.input, stack
            ),
            Err(err) => write!(
                f,
                "[{:>3}] {:<25} => ERREUR: {}",
                self.id, self.input, err
            ),
        }
    }
}

/// Moteur de calcul en notation polonaise inverse (RPN).
#[derive(Debug, Default, Clone)]
pub struct RpnEngine {
    stack: Vec<f64>,
    history: Vec<HistoryEntry>,
}

impl RpnEngine {
    /// Crée une nouvelle instance de moteur RPN vide.
    pub fn new() -> Self {
        Self {
            stack: Vec::new(),
            history: Vec::new(),
        }
    }

    /// Retourne une référence vers la pile d'opérandes courante.
    pub fn stack(&self) -> &[f64] {
        &self.stack
    }

    /// Retourne l'historique des évaluations.
    pub fn history(&self) -> &[HistoryEntry] {
        &self.history
    }

    /// Réinitialise la pile d'opérandes.
    pub fn clear_stack(&mut self) {
        self.stack.clear();
    }

    /// Réinitialise l'historique des calculs.
    pub fn clear_history(&mut self) {
        self.history.clear();
    }

    /// Évalue une ligne d'entrée contenant des jetons RPN ou des commandes internes.
    /// Retourne la valeur au sommet de la pile si disponible.
    pub fn eval_line(&mut self, input: &str) -> Result<Option<f64>, RpnError> {
        let trimmed = input.trim();
        if trimmed.is_empty() {
            return Err(RpnError::EmptyExpression);
        }

        // Sauvegarde de l'état en cas d'erreur pour rollback transactionnel de la ligne
        let saved_stack = self.stack.clone();
        let eval_result = self.execute_tokens(trimmed);

        let next_id = self.history.len() + 1;
        match &eval_result {
            Ok(_) => {
                self.history.push(HistoryEntry {
                    id: next_id,
                    input: trimmed.to_string(),
                    result: Ok(self.stack.clone()),
                });
                Ok(self.stack.last().copied())
            }
            Err(err) => {
                // Restauration de l'état de la pile avant l'expression fautive
                self.stack = saved_stack;
                self.history.push(HistoryEntry {
                    id: next_id,
                    input: trimmed.to_string(),
                    result: Err(err.clone()),
                });
                Err(err.clone())
            }
        }
    }

    /// Traite séquentiellement les jetons d'une expression.
    fn execute_tokens(&mut self, input: &str) -> Result<(), RpnError> {
        for token in input.split_whitespace() {
            self.execute_token(token)?;
        }
        Ok(())
    }

    /// Traite un jeton individuel (nombre, constante, opérateur ou fonction).
    fn execute_token(&mut self, token: &str) -> Result<(), RpnError> {
        let token_lower = token.to_lowercase();

        // 1. Tenter la conversion en nombre flottant
        if let Ok(value) = token.parse::<f64>() {
            self.stack.push(value);
            return Ok(());
        }

        // 2. Constantes mathématiques
        match token_lower.as_str() {
            "pi" => {
                self.stack.push(PI);
                return Ok(());
            }
            "e" => {
                self.stack.push(E);
                return Ok(());
            }
            "tau" => {
                self.stack.push(TAU);
                return Ok(());
            }
            _ => {}
        }

        // 3. Opérations sur la pile
        match token_lower.as_str() {
            "dup" => {
                let val = self.pop("dup")?;
                self.stack.push(val);
                self.stack.push(val);
                return Ok(());
            }
            "drop" | "pop" => {
                let _ = self.pop("drop")?;
                return Ok(());
            }
            "swap" => {
                let b = self.pop("swap")?;
                let a = self.pop("swap")?;
                self.stack.push(b);
                self.stack.push(a);
                return Ok(());
            }
            "rot" => {
                // Fait remonter le 3e élément au sommet: a b c -> b c a
                if self.stack.len() < 3 {
                    return Err(RpnError::StackUnderflow {
                        required: 3,
                        actual: self.stack.len(),
                        op: "rot",
                    });
                }
                let len = self.stack.len();
                let item = self.stack.remove(len - 3);
                self.stack.push(item);
                return Ok(());
            }
            "clear" => {
                self.clear_stack();
                return Ok(());
            }
            _ => {}
        }

        // 4. Opérations arithmétiques binaires
        match token_lower.as_str() {
            "+" => {
                let (a, b) = self.pop2("+")?;
                self.stack.push(a + b);
                return Ok(());
            }
            "-" => {
                let (a, b) = self.pop2("-")?;
                self.stack.push(a - b);
                return Ok(());
            }
            "*" => {
                let (a, b) = self.pop2("*")?;
                self.stack.push(a * b);
                return Ok(());
            }
            "/" => {
                let (a, b) = self.pop2("/")?;
                if b == 0.0 {
                    return Err(RpnError::DivisionByZero);
                }
                self.stack.push(a / b);
                return Ok(());
            }
            "%" | "mod" => {
                let (a, b) = self.pop2("%")?;
                if b == 0.0 {
                    return Err(RpnError::DivisionByZero);
                }
                self.stack.push(a % b);
                return Ok(());
            }
            "^" | "pow" => {
                let (a, b) = self.pop2("^")?;
                let res = a.powf(b);
                if res.is_nan() {
                    return Err(RpnError::DomainError {
                        op: "pow",
                        arg: a,
                        reason: "Résultat indéfini pour cette base et cet exposant",
                    });
                }
                self.stack.push(res);
                return Ok(());
            }
            "atan2" => {
                let (y, x) = self.pop2("atan2")?;
                self.stack.push(y.atan2(x));
                return Ok(());
            }
            _ => {}
        }

        // 5. Fonctions mathématiques unaires & trigonométriques
        match token_lower.as_str() {
            // Arithmétique / Unaire
            "neg" | "chs" => {
                let a = self.pop("neg")?;
                self.stack.push(-a);
                Ok(())
            }
            "abs" => {
                let a = self.pop("abs")?;
                self.stack.push(a.abs());
                Ok(())
            }
            "inv" => {
                let a = self.pop("inv")?;
                if a == 0.0 {
                    return Err(RpnError::DivisionByZero);
                }
                self.stack.push(1.0 / a);
                Ok(())
            }
            "sqrt" => {
                let a = self.pop("sqrt")?;
                if a < 0.0 {
                    return Err(RpnError::DomainError {
                        op: "sqrt",
                        arg: a,
                        reason: "L'argument doit être positif ou nul",
                    });
                }
                self.stack.push(a.sqrt());
                Ok(())
            }
            "ln" => {
                let a = self.pop("ln")?;
                if a <= 0.0 {
                    return Err(RpnError::DomainError {
                        op: "ln",
                        arg: a,
                        reason: "L'argument doit être strictement positif",
                    });
                }
                self.stack.push(a.ln());
                Ok(())
            }
            "log10" => {
                let a = self.pop("log10")?;
                if a <= 0.0 {
                    return Err(RpnError::DomainError {
                        op: "log10",
                        arg: a,
                        reason: "L'argument doit être strictement positif",
                    });
                }
                self.stack.push(a.log10());
                Ok(())
            }
            "exp" => {
                let a = self.pop("exp")?;
                self.stack.push(a.exp());
                Ok(())
            }

            // Trigonométrie directe
            "sin" => {
                let a = self.pop("sin")?;
                self.stack.push(a.sin());
                Ok(())
            }
            "cos" => {
                let a = self.pop("cos")?;
                self.stack.push(a.cos());
                Ok(())
            }
            "tan" => {
                let a = self.pop("tan")?;
                let cos_val = a.cos();
                if cos_val.abs() < 1e-15 {
                    return Err(RpnError::DomainError {
                        op: "tan",
                        arg: a,
                        reason: "Tangente indéfinie (cosinus nul)",
                    });
                }
                self.stack.push(a.tan());
                Ok(())
            }

            // Trigonométrie réciproque
            "asin" => {
                let a = self.pop("asin")?;
                if !(-1.0..=1.0).contains(&a) {
                    return Err(RpnError::DomainError {
                        op: "asin",
                        arg: a,
                        reason: "L'argument doit être dans l'intervalle [-1.0, 1.0]",
                    });
                }
                self.stack.push(a.asin());
                Ok(())
            }
            "acos" => {
                let a = self.pop("acos")?;
                if !(-1.0..=1.0).contains(&a) {
                    return Err(RpnError::DomainError {
                        op: "acos",
                        arg: a,
                        reason: "L'argument doit être dans l'intervalle [-1.0, 1.0]",
                    });
                }
                self.stack.push(a.acos());
                Ok(())
            }
            "atan" => {
                let a = self.pop("atan")?;
                self.stack.push(a.atan());
                Ok(())
            }

            // Trigonométrie hyperbolique
            "sinh" => {
                let a = self.pop("sinh")?;
                self.stack.push(a.sinh());
                Ok(())
            }
            "cosh" => {
                let a = self.pop("cosh")?;
                self.stack.push(a.cosh());
                Ok(())
            }
            "tanh" => {
                let a = self.pop("tanh")?;
                self.stack.push(a.tanh());
                Ok(())
            }

            // Conversions d'angles
            "deg" | "rad2deg" => {
                let a = self.pop("rad2deg")?;
                self.stack.push(a.to_degrees());
                Ok(())
            }
            "rad" | "deg2rad" => {
                let a = self.pop("deg2rad")?;
                self.stack.push(a.to_radians());
                Ok(())
            }

            // Jeton inconnu
            _ => Err(RpnError::InvalidToken(token.to_string())),
        }
    }

    /// Extrait un élément du sommet de la pile.
    fn pop(&mut self, op: &'static str) -> Result<f64, RpnError> {
        self.stack.pop().ok_or(RpnError::StackUnderflow {
            required: 1,
            actual: self.stack.len(),
            op,
        })
    }

    /// Extrait deux éléments du sommet de la pile (a puis b tel que a op b).
    fn pop2(&mut self, op: &'static str) -> Result<(f64, f64), RpnError> {
        if self.stack.len() < 2 {
            return Err(RpnError::StackUnderflow {
                required: 2,
                actual: self.stack.len(),
                op,
            });
        }
        let b = self.stack.pop().unwrap_or(0.0);
        let a = self.stack.pop().unwrap_or(0.0);
        Ok((a, b))
    }
}

/// Affiche l'aide utilisateur dans la console.
fn print_help() {
    println!("\n=== Aide de l'Interpréteur RPN ===");
    println!("Constantes : pi, e, tau");
    println!("Arithmétique : +, -, *, /, %, ^ (ou pow), neg (ou chs), abs, sqrt, inv");
    println!("Trigonométrie : sin, cos, tan, asin, acos, atan, atan2, sinh, cosh, tanh");
    println!("Conversions : rad, deg (rad2deg, deg2rad)");
    println!("Exponentielle/Log : exp, ln, log10");
    println!("Gestion pile : dup, drop (pop), swap, rot, clear, stack");
    println!("Historique : history, clear-history");
    println!("Commandes système : help, exit, quit\n");
}

/// Affiche la pile d'opérandes avec l'index de chaque niveau.
fn print_stack(stack: &[f64]) {
    if stack.is_empty() {
        println!("Pile : [vide]");
    } else {
        println!("--- Pile (taille: {}) ---", stack.len());
        for (i, val) in stack.iter().enumerate() {
            println!("  [{:>2}] : {}", i, val);
        }
        println!("-------------------------");
    }
}

/// Affiche l'historique complet des évaluations.
fn print_history(history: &[HistoryEntry]) {
    if history.is_empty() {
        println!("Historique vide.");
    } else {
        println!("\n=== Historique des calculs ===");
        for entry in history {
            println!("{}", entry);
        }
        println!("==============================\n");
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut engine = RpnEngine::new();
    let args: Vec<String> = env::args().skip(1).collect();

    // Mode non-interactif si des arguments sont fournis en ligne de commande
    if !args.is_empty() {
        let input_expr = args.join(" ");
        match engine.eval_line(&input_expr) {
            Ok(Some(res)) => {
                println!("{}", res);
                return Ok(());
            }
            Ok(None) => {
                println!("OK (pile vide)");
                return Ok(());
            }
            Err(e) => {
                eprintln!("Erreur : {}", e);
                std::process::exit(1);
            }
        }
    }

    // Mode interactif (REPL) avec rustyline
    println!("============================================================");
    println!(" Interpréteur RPN interactif (Rust)");
    println!(" Tapez 'help' pour la documentation ou 'exit' pour quitter.");
    println!("============================================================");

    let mut rl = rustyline::DefaultEditor::new()?;

    loop {
        let readline = rl.readline("rpn> ");
        match readline {
            Ok(line) => {
                let trimmed = line.trim();
                if trimmed.is_empty() {
                    continue;
                }

                // Ajout à l'historique de saisie de la ligne de commande
                let _ = rl.add_history_entry(trimmed);

                match trimmed {
                    "exit" | "quit" | "q" => {
                        println!("Fermeture de l'interpréteur.");
                        break;
                    }
                    "help" | "?" => {
                        print_help();
                    }
                    "stack" => {
                        print_stack(engine.stack());
                    }
                    "history" => {
                        print_history(engine.history());
                    }
                    "clear-history" => {
                        engine.clear_history();
                        println!("Historique effacé.");
                    }
                    expr => match engine.eval_line(expr) {
                        Ok(Some(val)) => {
                            println!("=> {}", val);
                            print_stack(engine.stack());
                        }
                        Ok(None) => {
                            println!("=> Pile vide");
                        }
                        Err(err) => {
                            eprintln!("Erreur : {}", err);
                        }
                    },
                }
            }
            Err(rustyline::error::ReadlineError::Interrupted) => {
                println!("Interruption (^C). Tapez 'exit' pour quitter.");
            }
            Err(rustyline::error::ReadlineError::Eof) => {
                println!("Au revoir (^D).");
                break;
            }
            Err(err) => {
                eprintln!("Erreur de saisie : {}", err);
                break;
            }
        }
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_arithmetic() {
        let mut engine = RpnEngine::new();
        assert_eq!(engine.eval_line("3 4 +").unwrap(), Some(7.0));
        assert_eq!(engine.eval_line("2 *").unwrap(), Some(14.0));
        assert_eq!(engine.eval_line("4 -").unwrap(), Some(10.0));
        assert_eq!(engine.eval_line("2 /").unwrap(), Some(5.0));
        assert_eq!(engine.eval_line("2 %").unwrap(), Some(1.0));
    }

    #[test]
    fn test_constants_and_trigonometry() {
        let mut engine = RpnEngine::new();

        // sin(pi / 2) == 1.0
        let res = engine.eval_line("pi 2 / sin").unwrap().unwrap();
        assert!((res - 1.0).abs() < 1e-12);

        // cos(pi) == -1.0
        let res_cos = engine.eval_line("pi cos").unwrap().unwrap();
        assert!((res_cos - (-1.0)).abs() < 1e-12);

        // Conversion 180 deg en rad -> pi rad
        engine.clear_stack();
        let rad = engine.eval_line("180 rad").unwrap().unwrap();
        assert!((rad - PI).abs() < 1e-12);

        // atan(1.0) * 4 == pi
        engine.clear_stack();
        let res_atan = engine.eval_line("1 atan 4 *").unwrap().unwrap();
        assert!((res_atan - PI).abs() < 1e-12);
    }

    #[test]
    fn test_stack_operations() {
        let mut engine = RpnEngine::new();
        engine.eval_line("5 dup *").unwrap();
        assert_eq!(engine.stack(), &[25.0]);

        engine.eval_line("10 swap").unwrap();
        assert_eq!(engine.stack(), &[10.0, 25.0]);

        engine.eval_line("drop").unwrap();
        assert_eq!(engine.stack(), &[10.0]);

        engine.eval_line("clear").unwrap();
        assert!(engine.stack().is_empty());

        // Test rot : 1 2 3 rot -> 2 3 1
        engine.eval_line("1 2 3 rot").unwrap();
        assert_eq!(engine.stack(), &[2.0, 3.0, 1.0]);
    }

    #[test]
    fn test_error_handling_and_rollback() {
        let mut engine = RpnEngine::new();
        engine.eval_line("42").unwrap();

        // Division par zéro -> erreur & rollback à l'état [42.0]
        let err = engine.eval_line("0 /").unwrap_err();
        assert_eq!(err, RpnError::DivisionByZero);
        assert_eq!(engine.stack(), &[42.0]);

        // Stack underflow
        let err_uf = engine.eval_line("+").unwrap_err();
        match err_uf {
            RpnError::StackUnderflow { required, actual, .. } => {
                assert_eq!(required, 2);
                assert_eq!(actual, 1);
            }
            _ => panic!("Type d'erreur inattendu"),
        }

        // Domain error sqrt(-1)
        let err_sqrt = engine.eval_line("-1 sqrt").unwrap_err();
        match err_sqrt {
            RpnError::DomainError { op, .. } => assert_eq!(op, "sqrt"),
            _ => panic!("Type d'erreur inattendu"),
        }

        // Invalid token
        let err_tok = engine.eval_line("inconnu").unwrap_err();
        assert_eq!(err_tok, RpnError::InvalidToken("inconnu".to_string()));
    }

    #[test]
    fn test_history_tracking() {
        let mut engine = RpnEngine::new();
        engine.eval_line("10 20 +").unwrap();
        engine.eval_line("5 *").unwrap();
        let _ = engine.eval_line("0 /"); // Fails

        let hist = engine.history();
        assert_eq!(hist.len(), 3);
        assert_eq!(hist[0].input, "10 20 +");
        assert_eq!(hist[0].result, Ok(vec![30.0]));
        assert_eq!(hist[1].input, "5 *");
        assert_eq!(hist[1].result, Ok(vec![150.0]));
        assert_eq!(hist[2].input, "0 /");
        assert_eq!(hist[2].result, Err(RpnError::DivisionByZero));

        engine.clear_history();
        assert!(engine.history().is_empty());
    }

    #[test]
    fn test_advanced_math() {
        let mut engine = RpnEngine::new();
        let res = engine.eval_line("e ln").unwrap().unwrap();
        assert!((res - 1.0).abs() < 1e-12);

        let res_pow = engine.eval_line("2 3 ^").unwrap().unwrap();
        assert_eq!(res_pow, 8.0);

        let res_inv = engine.eval_line("4 inv").unwrap().unwrap();
        assert_eq!(res_inv, 0.25);
    }
}

