mod tests {
    use super::*;

    #[test]
    fn test_exact_ip_matching() -> Result<(), Box<dyn std::error::Error>> {
        let ip = IpAddr::from_str("192.168.1.10")?;
        let matcher = IpMatcher::Exact(ip);

        assert!(matcher.matches(&ip));
        assert!(!matcher.matches(&IpAddr::from_str("192.168.1.11")?));
        Ok(())
    }

    #[test]
    fn test_subnet_matching_ipv4_and_ipv6() -> Result<(), Box<dyn std::error::Error>> {
        let subnet_v4 = IpMatcher::Subnet(IpNet::from_str("10.0.0.0/24")?);
        assert!(subnet_v4.matches(&IpAddr::from_str("10.0.0.1")?));
        assert!(subnet_v4.matches(&IpAddr::from_str("10.0.0.254")?));
        assert!(!subnet_v4.matches(&IpAddr::from_str("10.0.1.1")?));

        let subnet_v6 = IpMatcher::Subnet(IpNet::from_str("2001:db8::/32")?);
        assert!(subnet_v6.matches(&IpAddr::from_str("2001:db8:ffff::1")?));
        assert!(!subnet_v6.matches(&IpAddr::from_str("2001:db9::1")?));
        Ok(())
    }

    #[test]
    fn test_port_matcher_variations() -> Result<(), Box<dyn std::error::Error>> {
        let exact = PortMatcher::Exact(80);
        assert!(exact.matches(80));
        assert!(!exact.matches(443));

        let range = PortMatcher::Range {
            min: 8000,
            max: 8080,
        };
        range.validate()?;
        assert!(range.matches(8000));
        assert!(range.matches(8042));
        assert!(range.matches(8080));
        assert!(!range.matches(7999));
        assert!(!range.matches(8081));

        let list = PortMatcher::List(vec![22, 80, 443]);
        assert!(list.matches(22));
        assert!(list.matches(443));
        assert!(!list.matches(8080));

        let invalid_range = PortMatcher::Range {
            min: 9000,
            max: 8000,
        };
        assert!(invalid_range.validate().is_err());

        Ok(())
    }

    #[test]
    fn test_first_match_priority_behavior() -> Result<(), Box<dyn std::error::Error>> {
        let mut engine = FirewallEngine::new(Action::Drop);

        // Règle 1 : priorité 10 autorise
        let r1 = Rule::new(
            1,
            "Permit Bastion",
            10,
            IpMatcher::Exact(IpAddr::from_str("10.0.0.1")?),
            PortMatcher::Exact(22),
            Protocol::Tcp,
            Action::Allow,
        )?;

        // Règle 2 : priorité 20 rejette tout le sous-réseau
        let r2 = Rule::new(
            2,
            "Block Subnet",
            20,
            IpMatcher::Subnet(IpNet::from_str("10.0.0.0/24")?),
            PortMatcher::Exact(22),
            Protocol::Tcp,
            Action::Drop,
        )?;

        // Insertion dans l'ordre inverse pour vérifier le tri par priorité
        engine.add_rule(r2)?;
        engine.add_rule(r1)?;

        let pkt_bastion = NetworkPacket::new(1, IpAddr::from_str("10.0.0.1")?, 22, Protocol::Tcp);
        let verdict_bastion = engine.evaluate(&pkt_bastion);
        assert_eq!(verdict_bastion.action, Action::Allow);
        assert_eq!(verdict_bastion.matched_rule_id, Some(1));

        let pkt_other = NetworkPacket::new(2, IpAddr::from_str("10.0.0.2")?, 22, Protocol::Tcp);
        let verdict_other = engine.evaluate(&pkt_other);
        assert_eq!(verdict_other.action, Action::Drop);
        assert_eq!(verdict_other.matched_rule_id, Some(2));

        let pkt_external =
            NetworkPacket::new(3, IpAddr::from_str("192.168.1.1")?, 22, Protocol::Tcp);
        let verdict_external = engine.evaluate(&pkt_external);
        assert_eq!(verdict_external.action, Action::Drop);
        assert_eq!(verdict_external.matched_rule_id, None);

        assert_eq!(engine.get_hits(Some(1)), 1);
        assert_eq!(engine.get_hits(Some(2)), 1);
        assert_eq!(engine.get_hits(None), 1);

        Ok(())
    }

