// src/main.rs
use std::collections::HashMap;
use std::fmt;
use std::net::IpAddr;
use std::str::FromStr;

use ipnet::IpNet;
use serde::{Deserialize, Serialize};
use thiserror::Error;

/// Erreurs potentielles rencontrées par le moteur de pare-feu.
#[derive(Debug, Error)]
pub enum FirewallError {
    #[error("Erreur d'analyse d'adresse ou masque IP : {0}")]
    InvalidIp(#[from] ipnet::AddrParseError),

    #[error("Erreur d'analyse de bloc CIDR : {0}")]
    InvalidCidr(#[from] ipnet::PrefixLenError),

    #[error("Plage de ports invalide : min ({min}) > max ({max})")]
    InvalidPortRange { min: u16, max: u16 },

    #[error("Règle avec ID dupliqué détectée : {0}")]
    DuplicateRuleId(u32),

    #[error("Erreur de désérialisation JSON : {0}")]
    SerializationError(#[from] serde_json::Error),
}

/// Protocoles réseau supportés pour le filtrage applicatif.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "UPPERCASE")]
pub enum Protocol {
    Tcp,
    Udp,
    Icmp,
    Any,
    #[serde(untagged)]
    Other(u8),
}

impl Protocol {
    /// Vérifie la correspondance entre le protocole d'une règle et celui d'un paquet.
    #[must_use]
    pub fn matches(&self, packet_proto: &Protocol) -> bool {
        match (self, packet_proto) {
            (Protocol::Any, _) => true,
            (Protocol::Tcp, Protocol::Tcp) => true,
            (Protocol::Udp, Protocol::Udp) => true,
            (Protocol::Icmp, Protocol::Icmp) => true,
            (Protocol::Other(a), Protocol::Other(b)) => a == b,
            _ => false,
        }
    }
}

impl fmt::Display for Protocol {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Protocol::Tcp => write!(f, "TCP"),
            Protocol::Udp => write!(f, "UDP"),
            Protocol::Icmp => write!(f, "ICMP"),
            Protocol::Any => write!(f, "ANY"),
            Protocol::Other(code) => write!(f, "PROTO_{code}"),
        }
    }
}

/// Critères de correspondance pour l'adresse IP source.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "type", content = "value")]
pub enum IpMatcher {
    /// Accepte n'importe quelle adresse IP.
    Any,
    /// Correspondance stricte sur une adresse IPv4 ou IPv6.
    Exact(IpAddr),
    /// Correspondance sur un sous-réseau au format CIDR (ex: 192.168.1.0/24 ou 2001:db8::/32).
    Subnet(IpNet),
}

impl IpMatcher {
    /// Vérifie si une adresse IP source correspond au critère.
    #[must_use]
    pub fn matches(&self, ip: &IpAddr) -> bool {
        match self {
            IpMatcher::Any => true,
            IpMatcher::Exact(exact_ip) => exact_ip == ip,
            IpMatcher::Subnet(net) => net.contains(ip),
        }
    }
}

impl fmt::Display for IpMatcher {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            IpMatcher::Any => write!(f, "*"),
            IpMatcher::Exact(ip) => write!(f, "{ip}"),
            IpMatcher::Subnet(net) => write!(f, "{net}"),
        }
    }
}

/// Critères de correspondance pour les ports réseau (destination ou applicatif).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "type", content = "value")]
pub enum PortMatcher {
    /// Accepte tous les ports.
    Any,
    /// Port exact unique.
    Exact(u16),
    /// Plage inclusive de ports [min, max].
    Range { min: u16, max: u16 },
    /// Liste explicite de ports.
    List(Vec<u16>),
}

impl PortMatcher {
    /// Valide la cohérence interne du critère (ex: min <= max).
    pub fn validate(&self) -> Result<(), FirewallError> {
        if let PortMatcher::Range { min, max } = self {
            if min > max {
                return Err(FirewallError::InvalidPortRange {
                    min: *min,
                    max: *max,
                });
            }
        }
        Ok(())
    }

    /// Vérifie si un port donné correspond au critère.
    #[must_use]
    pub fn matches(&self, port: u16) -> bool {
        match self {
            PortMatcher::Any => true,
            PortMatcher::Exact(target) => *target == port,
            PortMatcher::Range { min, max } => port >= *min && port <= *max,
            PortMatcher::List(list) => list.contains(&port),
        }
    }
}

impl fmt::Display for PortMatcher {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            PortMatcher::Any => write!(f, "*"),
            PortMatcher::Exact(p) => write!(f, "{p}"),
            PortMatcher::Range { min, max } => write!(f, "{min}-{max}"),
            PortMatcher::List(list) => {
                let s = list
                    .iter()
                    .map(|p| p.to_string())
                    .collect::<Vec<_>>()
                    .join(",");
                write!(f, "[{s}]")
            }
        }
    }
}

/// Décision prise par le pare-feu.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub enum Action {
    Allow,
    #[default]
    Drop,
    Reject {
        reason: String,
    },
}

impl fmt::Display for Action {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Action::Allow => write!(f, "ALLOW"),
            Action::Drop => write!(f, "DROP"),
            Action::Reject { reason } => write!(f, "REJECT ({reason})"),
        }
    }
}

/// Définition complète d'une règle de filtrage.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Rule {
    pub id: u32,
    pub description: String,
    pub priority: u32,
    pub src_ip: IpMatcher,
    pub port: PortMatcher,
    pub protocol: Protocol,
    pub action: Action,
}

impl Rule {
    /// Constructeur avec validation des contraintes.
    pub fn new(
        id: u32,
        description: impl Into<String>,
        priority: u32,
        src_ip: IpMatcher,
        port: PortMatcher,
        protocol: Protocol,
        action: Action,
    ) -> Result<Self, FirewallError> {
        port.validate()?;
        Ok(Self {
            id,
            description: description.into(),
            priority,
            src_ip,
            port,
            protocol,
            action,
        })
    }

    /// Détermine si un paquet correspond à tous les critères de la règle.
    #[must_use]
    pub fn matches(&self, packet: &NetworkPacket) -> bool {
        self.protocol.matches(&packet.protocol)
            && self.src_ip.matches(&packet.src_ip)
            && self.port.matches(packet.port)
    }
}

/// Représentation d'un paquet réseau inspecté.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct NetworkPacket {
    pub id: u64,
    pub src_ip: IpAddr,
    pub port: u16,
    pub protocol: Protocol,
}

impl NetworkPacket {
    #[must_use]
    pub fn new(id: u64, src_ip: IpAddr, port: u16, protocol: Protocol) -> Self {
        Self {
            id,
            src_ip,
            port,
            protocol,
        }
    }
}

impl fmt::Display for NetworkPacket {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "#{} [src: {}, port: {}, proto: {}]",
            self.id, self.src_ip, self.port, self.protocol
        )
    }
}

/// Résultat de l'évaluation d'un paquet par le moteur de pare-feu.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Verdict {
    pub packet_id: u64,
    pub action: Action,
    pub matched_rule_id: Option<u32>,
    pub explanation: String,
}

impl fmt::Display for Verdict {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let rule_str = match self.matched_rule_id {
            Some(id) => format!("Règle #{id}"),
            None => "Politique par défaut".to_string(),
        };
        write!(
            f,
            "Paquet #{} => {} [{}] - {}",
            self.packet_id, self.action, rule_str, self.explanation
        )
    }
}

/// Moteur principal de règles de pare-feu applicatif.
#[derive(Debug, Default)]
pub struct FirewallEngine {
    rules: Vec<Rule>,
    default_action: Action,
    hit_counts: HashMap<Option<u32>, u64>,
}

impl FirewallEngine {
    /// Crée un nouveau moteur avec la politique de repli par défaut.
    #[must_use]
    pub fn new(default_action: Action) -> Self {
        Self {
            rules: Vec::new(),
            default_action,
            hit_counts: HashMap::new(),
        }
    }

    /// Ajoute une règle au moteur tout en garantissant l'unicité de l'identifiant
    /// et le maintien du tri par priorité croissante.
    pub fn add_rule(&mut self, rule: Rule) -> Result<(), FirewallError> {
        rule.port.validate()?;

        if self.rules.iter().any(|r| r.id == rule.id) {
            return Err(FirewallError::DuplicateRuleId(rule.id));
        }

        self.rules.push(rule);
        // Tri stable par ordre croissant de priorité (1 est prioritaire sur 10)
        self.rules.sort_by_key(|r| r.priority);
        Ok(())
    }

    /// Évalue un paquet réseau en appliquant la stratégie First-Match.
    pub fn evaluate(&mut self, packet: &NetworkPacket) -> Verdict {
        for rule in &self.rules {
            if rule.matches(packet) {
                *self.hit_counts.entry(Some(rule.id)).or_insert(0) += 1;
                return Verdict {
                    packet_id: packet.id,
                    action: rule.action.clone(),
                    matched_rule_id: Some(rule.id),
                    explanation: format!("Correspondance règle '{}'", rule.description),
                };
            }
        }

        // Aucune règle n'a correspondu, application de la politique par défaut.
        *self.hit_counts.entry(None).or_insert(0) += 1;
        Verdict {
            packet_id: packet.id,
            action: self.default_action.clone(),
            matched_rule_id: None,
            explanation: "Aucune règle correspondante, application de la politique de repli"
                .to_string(),
        }
    }

    /// Retourne le nombre d'occurrences (hits) pour une règle spécifique ou pour la politique de repli.
    #[must_use]
    pub fn get_hits(&self, rule_id: Option<u32>) -> u64 {
        self.hit_counts.get(&rule_id).copied().unwrap_or(0)
    }

    /// Retourne les statistiques globales sous forme de référence immuable.
    #[must_use]
    pub fn all_hits(&self) -> &HashMap<Option<u32>, u64> {
        &self.hit_counts
    }

    /// Retourne la liste des règles actuellement chargées.
    #[must_use]
    pub fn rules(&self) -> &[Rule] {
        &self.rules
    }
}

