        self.heading += self.angular_speed * dt;
        self.position.x += self.linear_speed * self.heading.cos() * dt;
        self.position.y += self.linear_speed * self.heading.sin() * dt;

        // Consommation proportionnelle au travail mécanique
        let drain = 0.05 + (self.linear_speed.abs() * 0.25) + (self.angular_speed.abs() * 0.1);
        self.battery_level = (self.battery_level - drain * dt).clamp(0.0, 100.0);
    }

    pub fn steer_towards(&mut self, target: Vector2, desired_speed: f64, dt: f64) {
        let desired_heading = self.position.direction_to(&target);
        let mut diff = desired_heading - self.heading;

        // Normalisation dans [-pi, pi]
        while diff > std::f64::consts::PI {
            diff -= 2.0 * std::f64::consts::PI;
        }
        while diff < -std::f64::consts::PI {
            diff += 2.0 * std::f64::consts::PI;
        }

        self.angular_speed = (diff * 2.0).clamp(-2.5, 2.5);
        if diff.abs() < 0.6 {
            self.linear_speed = (self.linear_speed + 1.0 * dt).min(desired_speed);
        } else {
            self.linear_speed = (self.linear_speed - 1.5 * dt).max(0.2);
        }
    }

    pub fn stop_motion(&mut self) {
        self.linear_speed = 0.0;
        self.angular_speed = 0.0;
    }
}

// =========================================================================
// Sous-États du super-état "Operational" (Micro-comportements)
// =========================================================================

#[derive(Debug, Clone, PartialEq)]
pub enum OperationalSubState {
    Patrolling { waypoint_timer: f64, current_waypoint: Vector2 },
    NavigatingToTarget { target: Vector2 },
    Interacting { remaining_time: f64 },
}

impl fmt::Display for OperationalSubState {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Patrolling { .. } => write!(f, "Patrolling"),
            Self::NavigatingToTarget { .. } => write!(f, "NavigatingToTarget"),
            Self::Interacting { remaining_time } => write!(f, "Interacting({:.1}s)", remaining_time),
        }
    }
}

// =========================================================================
// Hiérarchie Principale : Super-États
// =========================================================================

#[derive(Debug, Clone, PartialEq)]
pub enum State {
    Operational(OperationalSubState),
    ReturningHome,
    Charging,
    EmergencyStop { reason: String },
}

impl fmt::Display for State {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Operational(sub) => write!(f, "Operational::{}", sub),
            Self::ReturningHome => write!(f, "ReturningHome"),
            Self::Charging => write!(f, "Charging"),
            Self::EmergencyStop { reason } => write!(f, "EmergencyStop({})", reason),
        }
    }
}

/// Résultat d'une étape de l'automate.
pub enum StepResult {
    KeepState,
    Transition(State),
}

/// Machine à états finis hiérarchique.
pub struct HierarchicalStateMachine {
    current_state: State,
}

impl HierarchicalStateMachine {
    pub fn new() -> Self {
        let initial_sub = OperationalSubState::Patrolling {
            waypoint_timer: 0.0,
            current_waypoint: Vector2::new(5.0, 5.0),
        };
        let fsm = Self {
            current_state: State::Operational(initial_sub),
        };
        fsm.on_enter(&fsm.current_state.clone());
        fsm
    }

    pub fn current_state(&self) -> &State {
        &self.current_state
    }

    fn on_enter(&self, state: &State) {
        log::info!("[HFSM ENTER] -> {}", state);
    }

    fn on_exit(&self, state: &State) {
        log::info!("[HFSM EXIT] <- {}", state);
    }

    pub fn transition_to(&mut self, next_state: State) {
        if self.current_state != next_state {
            self.on_exit(&self.current_state);
            self.current_state = next_state.clone();
            self.on_enter(&self.current_state);
        }
    }

    /// Dispatch de l'événement et mise à jour hiérarchique.
    pub fn update(&mut self, event: &Event, ctx: &mut RobotContext) {
        // 1. Vérification des transitions globales de niveau supérieur (Haute priorité)
        if let Some(global_transition) = self.check_superstate_guards(event, ctx) {
            self.transition_to(global_transition);
            return;
        }

        // 2. Traitement spécifique à l'état actif
        let result = match &mut self.current_state {
            State::Operational(sub_state) => Self::update_operational(sub_state, event, ctx),
            State::ReturningHome => Self::update_returning_home(event, ctx),
            State::Charging => Self::update_charging(event, ctx),
            State::EmergencyStop { reason } => Self::update_emergency(reason, event, ctx),
        };

        if let StepResult::Transition(next_state) = result {
            self.transition_to(next_state);
        }
    }

    /// Gardes globales applicables quel que soit le sous-état.
    fn check_superstate_guards(&self, event: &Event, ctx: &RobotContext) -> Option<State> {
        // Évitement collision immédiat prioritaire
        if let Event::ObstacleDetected { distance } = event {
            if *distance < 0.6 && !matches!(self.current_state, State::EmergencyStop { .. }) {
                return Some(State::EmergencyStop {
                    reason: format!("Obstacle trop proche ({:.2}m)", distance),
                });
            }
        }

        // Batterie critique déclenche le retour base sauf si déjà en charge ou en arrêt d'urgence
        if ctx.battery_level < 20.0
            && !matches!(self.current_state, State::ReturningHome | State::Charging | State::EmergencyStop { .. })
        {
            log::warn!("Niveau de batterie faible ({:.1}%), retour à la base déclenché.", ctx.battery_level);
            return Some(State::ReturningHome);
        }

        None
    }

    fn update_operational(
        sub_state: &mut OperationalSubState,
        event: &Event,
        ctx: &mut RobotContext,
    ) -> StepResult {
        match sub_state {
            OperationalSubState::Patrolling { waypoint_timer, current_waypoint } => {
                match event {
                    Event::Tick(dt) => {
                        *waypoint_timer += dt;
                        let dist = ctx.position.distance_to(current_waypoint);

                        if dist < 0.8 || *waypoint_timer > 10.0 {
                            let mut rng = rand::thread_rng();
                            let nx = rng.gen_range(-15.0..15.0);
                            let ny = rng.gen_range(-15.0..15.0);
                            *current_waypoint = Vector2::new(nx, ny);
                            *waypoint_timer = 0.0;
                            log::info!("Nouveau waypoint de patrouille : ({:.1}, {:.1})", nx, ny);
                        }

                        ctx.steer_towards(*current_waypoint, 1.8, *dt);
                        StepResult::KeepState
                    }
                    Event::TargetFound { position } => {
                        log::info!("Cible repérée en ({:.1}, {:.1}) ! Transition vers l'approche.", position.x, position.y);
                        StepResult::Transition(State::Operational(OperationalSubState::NavigatingToTarget {
                            target: *position,
                        }))
                    }
                    _ => StepResult::KeepState,
                }
            }

            OperationalSubState::NavigatingToTarget { target } => {
                match event {
                    Event::Tick(dt) => {
                        let dist = ctx.position.distance_to(target);
                        if dist < 0.4 {
                            ctx.stop_motion();
                            log::info!("Cible atteinte. Début de l'interaction / collecte.");
                            StepResult::Transition(State::Operational(OperationalSubState::Interacting {
                                remaining_time: 3.0,
                            }))
                        } else {
                            ctx.steer_towards(*target, 2.2, *dt);
                            StepResult::KeepState
                        }
                    }
                    _ => StepResult::KeepState,
                }
            }

            OperationalSubState::Interacting { remaining_time } => {
                match event {
                    Event::Tick(dt) => {
                        ctx.stop_motion();
                        *remaining_time -= dt;
                        if *remaining_time <= 0.0 {
                            ctx.samples_collected += 1;
                            log::info!(
                                "Échantillon collecté avec succès ! Total : {}",
                                ctx.samples_collected
                            );
                            let next_sub = OperationalSubState::Patrolling {
                                waypoint_timer: 0.0,
                                current_waypoint: Vector2::new(0.0, 0.0),
                            };
                            StepResult::Transition(State::Operational(next_sub))
                        } else {
                            StepResult::KeepState
                        }
                    }
                    _ => StepResult::KeepState,
                }
            }
        }
    }

    fn update_returning_home(event: &Event, ctx: &mut RobotContext) -> StepResult {
        match event {
            Event::Tick(dt) => {
                let dist_to_station = ctx.position.distance_to(&ctx.charging_station);
                if dist_to_station < 0.5 {
                    ctx.stop_motion();
                    log::info!("Station de recharge atteinte. Début du cycle de recharge.");
                    StepResult::Transition(State::Charging)
                } else {
                    ctx.steer_towards(ctx.charging_station, 2.0, *dt);
                    StepResult::KeepState
                }
            }
            _ => StepResult::KeepState,
        }
    }

    fn update_charging(event: &Event, ctx: &mut RobotContext) -> StepResult {
        match event {
            Event::Tick(dt) => {
                ctx.stop_motion();
                // Taux de recharge rapide
                ctx.battery_level = (ctx.battery_level + 15.0 * dt).min(100.0);
                if ctx.battery_level >= 100.0 {
                    log::info!("Batterie pleine (100%). Reprise des opérations.");
                    let initial_sub = OperationalSubState::Patrolling {
                        waypoint_timer: 0.0,
                        current_waypoint: Vector2::new(5.0, 5.0),
                    };
                    StepResult::Transition(State::Operational(initial_sub))
                } else {
                    StepResult::KeepState
                }
            }
            _ => StepResult::KeepState,
        }
    }

    fn update_emergency(_reason: &str, event: &Event, ctx: &mut RobotContext) -> StepResult {
        ctx.stop_motion();
        match event {
            Event::ObstacleCleared => {
                log::info!("Obstacle écarté. Sortie de l'arrêt d'urgence.");
                let resume_sub = OperationalSubState::Patrolling {
                    waypoint_timer: 0.0,
                    current_waypoint: ctx.position,
                };
                StepResult::Transition(State::Operational(resume_sub))
            }
            _ => StepResult::KeepState,
        }
    }
}

// =========================================================================
// Point d'entrée et Scénario de Simulation
// =========================================================================

fn main() {
    // Initialisation du logger
    env_logger::Builder::from_default_env()
        .filter_level(log::LevelFilter::Info)
        .init();

    println!("============================================================");
    println!("   SIMULATEUR DE ROBOT AUTONOME - HFSM RUST EN COURS       ");
    println!("============================================================");

    let start_pos = Vector2::new(0.0, 0.0);
    let charging_station = Vector2::new(0.0, 0.0);
    let mut context = RobotContext::new(start_pos, charging_station);
    let mut fsm = HierarchicalStateMachine::new();

    let dt = 0.2; // pas de temps de 200ms
    let total_steps = 120; // 24 secondes simulées

    for step in 1..=total_steps {
        let simulated_time = step as f64 * dt;

        // Génération d'événements environnementaux scénarisés
        if step == 15 {
            let sample_target = Vector2::new(8.0, 4.0);
            log::info!("[ENV] Événement environnemental : Balise cible identifiée à ({:.1}, {:.1})", sample_target.x, sample_target.y);
            fsm.update(&Event::TargetFound { position: sample_target }, &mut context);
        }

        if step == 45 {
            log::warn!("[ENV] Événement imprévu : Obstacle soudain détecté à 0.45m !");
            context.nearest_obstacle_distance = 0.45;
            fsm.update(&Event::ObstacleDetected { distance: context.nearest_obstacle_distance }, &mut context);
        }

        if step == 55 {
            log::info!("[ENV] L'obstacle a été dégagé par l'opérateur.");
            context.nearest_obstacle_distance = 10.0;
            fsm.update(&Event::ObstacleCleared, &mut context);
        }

        // Simuler une décharge accélérée pour tester le ralliement automatique
        if (60..80).contains(&step) {
            context.battery_level = (context.battery_level - 3.5).max(10.0);
        }

        // Tick régulier de la boucle de contrôle
        fsm.update(&Event::Tick(dt), &mut context);
        context.step_physics(dt);

        // Télémétrie périodique toutes les 10 itérations (2s)
        if step % 10 == 0 {
            println!(
                "[T={:4.1}s] État: {:<32} | Pos: ({:5.2}, {:5.2}) | Bat: {:5.1}% | Vitesse: {:4.2}m/s | Échantillons: {}",
                simulated_time,
                fsm.current_state().to_string(),
                context.position.x,
                context.position.y,
                context.battery_level,
                context.linear_speed,
                context.samples_collected
            );
        }
    }

    println!("============================================================");
    println!("                  SIMULATION TERMINÉE                       ");
    println!("  Échantillons collectés : {}", context.samples_collected);
    println!("  Position finale        : ({:.2}, {:.2})", context.position.x, context.position.y);
    println!("  Batterie restante      : {:.1}%", context.battery_level);
    println!("  État final             : {}", fsm.current_state());
    println!("============================================================");
}

