```rust
// src/main.rs
use clap::Parser;
use colored::Colorize;
use petgraph::algo::tarjan_scc;
use petgraph::graph::{DiGraph, NodeIndex};
use petgraph::visit::EdgeRef;
use petgraph::Direction;
use serde::{Deserialize, Serialize};
use std::collections::{HashMap, HashSet, VecDeque};
use std::fs;
use std::path::{Path, PathBuf};
use thiserror::Error;

/// Format de définition d'un nœud dans la spécification du workflow.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct NodeDef {
    pub id: String,
    #[serde(default)]
    pub label: Option<String>,
}

/// Format de définition d'une transition orientée entre nœuds.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TransitionDef {
    pub from: String,
    pub to: String,
    #[serde(default)]
    pub condition: Option<String>,
}

/// Spécification complète d'un graphe de flux de travail (workflow).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct WorkflowSpec {
    pub id: String,
    #[serde(default)]
    pub initial_nodes: Vec<String>,
    #[serde(default)]
    pub terminal_nodes: Vec<String>,
    pub nodes: Vec<NodeDef>,
    pub transitions: Vec<TransitionDef>,
}

/// Erreurs de chargement et d'analyse syntaxique.
#[derive(Debug, Error)]
pub enum WorkflowLoadError {
    #[error("Erreur d'accès au fichier '{path}': {source}")]
    Io {
        path: PathBuf,
        #[source]
        source: std::io::Error,
    },
    #[error("Erreur de désérialisation JSON: {0}")]
    Json(#[from] serde_json::Error),
    #[error("Erreur de désérialisation YAML: {0}")]
    Yaml(#[from] serde_yaml::Error),
    #[error("Format de fichier non supporté: '{0}'. Utilisez .json, .yaml ou .yml.")]
    UnsupportedFormat(String),
}

/// Niveaux de sévérité d'un diagnostic formel.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum DiagnosticLevel {
    Error,
    Warning,
}

/// Diagnostic résultant de l'analyse formelle.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Diagnostic {
    pub level: DiagnosticLevel,
    pub code: String,
    pub message: String,
    #[serde(skip_serializing_if = "Vec::is_empty", default)]
    pub nodes: Vec<String>,
}

/// Rapport complet d'analyse formelle.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ValidationReport {
    pub workflow_id: String,
    pub is_valid: bool,
    pub node_count: usize,
    pub edge_count: usize,
    pub diagnostics: Vec<Diagnostic>,
}

impl ValidationReport {
    pub fn new(workflow_id: String, node_count: usize, edge_count: usize) -> Self {
        Self {
            workflow_id,
            is_valid: true,
            node_count,
            edge_count,
            diagnostics: Vec::new(),
        }
    }

    pub fn add_diagnostic(&mut self, diag: Diagnostic) {
        if diag.level == DiagnosticLevel::Error {
            self.is_valid = false;
        }
        self.diagnostics.push(diag);
    }
}

/// Moteur de validation formelle de workflow.
pub struct FormalValidator<'a> {
    spec: &'a WorkflowSpec,
    graph: DiGraph<String, Option<String>>,
    node_indices: HashMap<String, NodeIndex>,
    strict_dag: bool,
}

impl<'a> FormalValidator<'a> {
    pub fn new(spec: &'a WorkflowSpec, strict_dag: bool) -> Self {
        Self {
            spec,
            graph: DiGraph::new(),
            node_indices: HashMap::new(),
            strict_dag,
        }
    }

    /// Construit le graphe et valide l'intégrité structurelle.
    pub fn validate(mut self) -> ValidationReport {
        let mut report = ValidationReport::new(
            self.spec.id.clone(),
            self.spec.nodes.len(),
            self.spec.transitions.len(),
        );

        // 1. Enregistrement des nœuds
        for node in &self.spec.nodes {
            if self.node_indices.contains_key(&node.id) {
                report.add_diagnostic(Diagnostic {
                    level: DiagnosticLevel::Error,
                    code: "DUPLICATE_NODE".to_string(),
                    message: format!("Le nœud identifié par '{}' est déclaré en double.", node.id),
                    nodes: vec![node.id.clone()],
                });
            } else {
                let idx = self.graph.add_node(node.id.clone());
                self.node_indices.insert(node.id.clone(), idx);
            }
        }

        // 2. Vérification de l'existence des nœuds initiaux
        if self.spec.initial_nodes.is_empty() {
            report.add_diagnostic(Diagnostic {
                level: DiagnosticLevel::Error,
                code: "MISSING_INITIAL_NODE".to_string(),
                message: "Aucun nœud initial n'est défini pour ce workflow.".to_string(),
                nodes: Vec::new(),
            });
        }

        let mut valid_initial_indices = Vec::new();
        for init in &self.spec.initial_nodes {
            match self.node_indices.get(init) {
                Some(&idx) => valid_initial_indices.push(idx),
                None => {
                    report.add_diagnostic(Diagnostic {
                        level: DiagnosticLevel::Error,
                        code: "UNDEFINED_INITIAL_NODE".to_string(),
                        message: format!("Le nœud initial '{}' n'est pas déclaré dans 'nodes'.", init),
                        nodes: vec![init.clone()],
                    });
                }
            }
        }

        // 3. Vérification de l'existence des nœuds terminaux
        if self.spec.terminal_nodes.is_empty() {
            report.add_diagnostic(Diagnostic {
                level: DiagnosticLevel::Error,
                code: "MISSING_TERMINAL_NODE".to_string(),
                message: "Aucun nœud terminal n'est défini pour ce workflow.".to_string(),
                nodes: Vec::new(),
            });
        }

        let mut valid_terminal_indices = HashSet::new();
        for term in &self.spec.terminal_nodes {
            match self.node_indices.get(term) {
                Some(&idx) => {
                    valid_terminal_indices.insert(idx);
                }
                None => {
                    report.add_diagnostic(Diagnostic {
                        level: DiagnosticLevel::Error,
                        code: "UNDEFINED_TERMINAL_NODE".to_string(),
                        message: format!("Le nœud terminal '{}' n'est pas déclaré dans 'nodes'.", term),
                        nodes: vec![term.clone()],
                    });
                }
            }
        }

        // 4. Enregistrement des transitions orientées
        for (i, trans) in self.spec.transitions.iter().enumerate() {
            let from_idx = self.node_indices.get(&trans.from).copied();
            let to_idx = self.node_indices.get(&trans.to).copied();

            match (from_idx, to_idx) {
                (Some(u), Some(v)) => {
                    self.graph.add_edge(u, v, trans.condition.clone());
                }
                (None, _) | (_, None) => {
                    let mut missing = Vec::new();
                    if from_idx.is_none() {
                        missing.push(trans.from.clone());
                    }
                    if to_idx.is_none() {
                        missing.push(trans.to.clone());
                    }
                    report.add_diagnostic(Diagnostic {
                        level: DiagnosticLevel::Error,
                        code: "UNDEFINED_TRANSITION_TARGET".to_string(),
                        message: format!(
                            "Transition n°{} ({}) référence des nœuds inexistants: {}.",
                            i + 1,
                            format!("{} -> {}", trans.from, trans.to),
                            missing.join(", ")
                        ),
                        nodes: missing,
                    });
                }
            }
        }

        // Si la structure de base contient des nœuds non résolus, on ne peut pas poursuivre l'analyse de connectivité
        if !report.is_valid {
            return report;
        }

        // 5. Accessibilité depuis les états initiaux (Reachability)
        let mut reachable_from_initial = HashSet::new();
        let mut queue = VecDeque::new();

        for &init_idx in &valid_initial_indices {
            if reachable_from_initial.insert(init_idx) {
                queue.push_back(init_idx);
            }
        }

        while let Some(current) = queue.pop_front() {
            for edge in self.graph.edges_directed(current, Direction::Outgoing) {
                let target = edge.target();
                if reachable_from_initial.insert(target) {
                    queue.push_back(target);
                }
            }
        }

        for (id, &idx) in &self.node_indices {
            if !reachable_from_initial.contains(&idx) {
                report.add_diagnostic(Diagnostic {
                    level: DiagnosticLevel::Warning,
                    code: "UNREACHABLE_NODE".to_string(),
                    message: format!(
                        "Nœud orphelin : '{}' n'est accessible depuis aucun nœud initial.",
                        id
                    ),
                    nodes: vec![id.clone()],
                });
            }
        }

        // 6. Co-accessibilité vers les états terminaux (Absence de cul-de-sac / Dead-end)
        // Rétro-propagation depuis les terminaux via les arêtes entrantes
        let mut can_reach_terminal = HashSet::new();
        let mut rev_queue = VecDeque::new();

        for &term_idx in &valid_terminal_indices {
            if can_reach_terminal.insert(term_idx) {
                rev_queue.push_back(term_idx);
            }
        }

        while let Some(current) = rev_queue.pop_front() {
            for edge in self.graph.edges_directed(current, Direction::Incoming) {
                let source = edge.source();
                if can_reach_terminal.insert(source) {
                    rev_queue.push_back(source);
                }
            }
        }

        // Nœuds qui ne peuvent jamais atteindre d'état terminal
        let mut dead_ends = Vec::new();
        for (id, &idx) in &self.node_indices {
            // On signale prioritairement les nœuds accessibles pour éviter les faux bruits
            if reachable_from_initial.contains(&idx) && !can_reach_terminal.contains(&idx) {
                dead_ends.push(id.clone());
            }
        }

        if !dead_ends.is_empty() {
            dead_ends.sort();
            for dead_node in &dead_ends {
                report.add_diagnostic(Diagnostic {
                    level: DiagnosticLevel::Error,
                    code: "CUL_DE_SAC".to_string(),
                    message: format!(
                        "Cul-de-sac détecté : le nœud '{}' ne possède aucun chemin menant à un nœud terminal.",
                        dead_node
                    ),
                    nodes: vec![dead_node.clone()],
                });
            }
        }

        // Détection spécifique des nœuds puits (sans sortie) qui ne sont pas terminaux
        for (id, &idx) in &self.node_indices {
            if reachable_from_initial.contains(&idx)
                && !valid_terminal_indices.contains(&idx)
                && self.graph.edges_directed(idx, Direction::Outgoing).count() == 0
            {
                report.add_diagnostic(Diagnostic {
                    level: DiagnosticLevel::Error,
                    code: "ILLEGAL_SINK".to_string(),
                    message: format!(
                        "Nœud puits illégal : '{}' n'a aucun successeur mais n'est pas déclaré comme terminal.",
                        id
                    ),
                    nodes: vec![id.clone()],
                });
            }
        }

        // 7. Analyse des composantes fortement connexes (SCC) et boucles infinies (Cycles & Livelocks)
        let sccs = tarjan_scc(&self.graph);

        for scc in sccs {
            // Une SCC de taille > 1 ou de taille 1 avec auto-boucle représente un cycle
            let is_cycle = if scc.len() > 1 {
                true
            } else if scc.len() == 1 {
                let node_idx = scc[0];
                self.graph
                    .edges_directed(node_idx, Direction::Outgoing)
                    .any(|e| e.target() == node_idx)
            } else {
                false
            };

            if is_cycle {
                let cycle_node_ids: Vec<String> = scc
                    .iter()
                    .map(|idx| self.graph[*idx].clone())
                    .collect();

                // Vérification si au moins un des nœuds du cycle est accessible depuis l'entrée
                let scc_is_reachable = scc.iter().any(|idx| reachable_from_initial.contains(idx));

                if scc_is_reachable {
                    // Vérification : est-il possible de sortir du cycle pour atteindre un terminal ?
                    let can_escape_to_terminal = scc.iter().any(|idx| can_reach_terminal.contains(idx));

                    if !can_escape_to_terminal {
                        // Boucle infinie critique (Livelock / cycle fermé sans sortie)
                        report.add_diagnostic(Diagnostic {
                            level: DiagnosticLevel::Error,
                            code: "INFINITE_LOOP_NO_ESCAPE".to_string(),
                            message: format!(
                                "Boucle infinie sans échappatoire (livelock) : le cycle [{}] est un piège duquel aucun état terminal n'est atteignable.",
                                cycle_node_ids.join(" -> ")
                            ),
                            nodes: cycle_node_ids.clone(),
                        });
                    } else if self.strict_dag {
                        // En mode strict DAG, tout cycle est formellement interdit
                        report.add_diagnostic(Diagnostic {
                            level: DiagnosticLevel::Error,
                            code: "STRICT_DAG_CYCLE_FORBIDDEN".to_string(),
                            message: format!(
                                "Cycle interdit en mode DAG strict détecté entre les nœuds : [{}].",
                                cycle_node_ids.join(" -> ")
                            ),
                            nodes: cycle_node_ids.clone(),
                        });
                    } else {
                        // Cycle avec échappatoire possible vers un terminal
                        report.add_diagnostic(Diagnostic {
                            level: DiagnosticLevel::Warning,
                            code: "CYCLIC_PATH_WARNING".to_string(),
                            message: format!(
                                "Cycle réentrant détecté [{}]. Assurez-vous qu'une condition de terminaison vérifiable garantit la progression vers la sortie.",
                                cycle_node_ids.join(" -> ")
                            ),
                            nodes: cycle_node_ids,
                        });
                    }
                }
            }
        }

        report
    }
}

/// Charge et désérialise un fichier JSON ou YAML.
pub fn load_workflow_from_file<P: AsRef<Path>>(path: P) -> Result<WorkflowSpec, WorkflowLoadError> {
    let p = path.as_ref();
    let content = fs::read_to_string(p).map_err(|e| WorkflowLoadError::Io {
        path: p.to_path_buf(),
        source: e,
    })?;

    let ext = p
        .extension()
        .and_then(|e| e.to_str())
        .map(|e| e.to_lowercase())
        .unwrap_or_default();

    match ext.as_str() {
        "json" => serde_json::from_str(&content).map_err(WorkflowLoadError::Json),
        "yaml" | "yml" => serde_yaml::from_str(&content).map_err(WorkflowLoadError::Yaml),
        _ => {
            // Tentative automatique JSON puis YAML si extension inconnue
            serde_json::from_str(&content).or_else(|_| {
                serde_yaml::from_str(&content).map_err(|_| {
                    WorkflowLoadError::UnsupportedFormat(
                        p.to_string_lossy().to_string(),
                    )
                })
            })
        }
    }
}

/// Arguments en ligne de commande.
#[derive(Parser, Debug)]
#[command(
    name = "workflow-validator",
    version,
    about = "CLI de validation formelle de flux de travail (workflows) vérifiant l'absence de cul-de-sac ou boucles infinies."
)]
struct Cli {
    /// Chemin du fichier de workflow à analyser (.json, .yaml, .yml)
    #[arg(short, long)]
    file: PathBuf,

    /// Mode strict : interdire catégoriquement tout cycle (DAG strict)
    #[arg(short, long, default_value_t = false)]
    strict_dag: bool,

    /// Exporter le rapport formel complet au format JSON
    #[arg(long, default_value_t = false)]
    json_report: bool,
}

fn main() {
    let args = Cli::parse();

    let workflow = match load_workflow_from_file(&args.file) {
        Ok(w) => w,
        Err(err) => {
            eprintln!("{} {}", "Erreur de chargement:".red().bold(), err);
            std::process::exit(2);
        }
    };

    let validator = FormalValidator::new(&workflow, args.strict_dag);
    let report = validator.validate();

    if args.json_report {
        match serde_json::to_string_pretty(&report) {
            Ok(json) => println!("{}", json),
            Err(e) => eprintln!("Erreur lors de la sérialisation du rapport: {}", e),
        }
    } else {
        println!("{}", "==================================================".bold());
        println!(
            "{} {}",
            "Validation Formelle du Workflow :".bold(),
            report.workflow_id.cyan().bold()
        );
        println!("{}", "==================================================".bold());
        println!("Nœuds recensés       : {}", report.node_count);
        println!("Transitions recensées : {}", report.edge_count);
        println!(
            "Mode strict DAG       : {}",
            if args.strict_dag { "Activé".yellow() } else { "Désactivé".normal() }
        );
        println!("--------------------------------------------------");

        if report.diagnostics.is_empty() {
            println!(
                "{}",
                "✓ Aucun problème détecté. Le graphe est bien formé, exempt de cul-de-sac et termine correctement."
                    .green()
                    .bold()
            );
        } else {
            for diag in &report.diagnostics {
                let badge = match diag.level {
                    DiagnosticLevel::Error => "[ERREUR]".red().bold(),
                    DiagnosticLevel::Warning => "[AVERTISSEMENT]".yellow().bold(),
                };
                println!("{} [{}] {}", badge, diag.code.bold(), diag.message);
                if !diag.nodes.is_empty() {
                    println!("       ↳ Nœud(s) impacté(s) : {}", diag.nodes.join(", ").dimmed());
                }
            }
        }

        println!("--------------------------------------------------");
        if report.is_valid {
            println!(
                "{}",
                "RÉSULTAT : WORKFLOW CONFORME (VALIDÉ)".green().bold()
            );
        } else {
            println!(
                "{}",
                "RÉSULTAT : WORKFLOW NON CONFORME (REJETÉ)".red().bold()
            );
        }
    }

    if !report.is_valid {
        std::process::exit(1);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn create_test_spec(
        initial: &[&str],
        terminal: &[&str],
        nodes: &[&str],
        transitions: &[(&str, &str)],
    ) -> WorkflowSpec {
        WorkflowSpec {
            id: "test-workflow".to_string(),
            initial_nodes: initial.iter().map(|s| s.to_string()).collect(),
            terminal_nodes: terminal.iter().map(|s| s.to_string()).collect(),
            nodes: nodes
                .iter()
                .map(|id| NodeDef {
                    id: id.to_string(),
                    label: None,
                })
                .collect(),
            transitions: transitions
                .iter()
                .map(|(from, to)| TransitionDef {
                    from: from.to_string(),
                    to: to.to_string(),
                    condition: None,
                })
                .collect(),
        }
    }

    #[test]
    fn test_valid_dag_workflow() {
        let spec = create_test_spec(
            &["start"],
            &["end"],
            &["start", "step1", "end"],
            &[("start", "step1"), ("step1", "end")],
        );
        let validator = FormalValidator::new(&spec, true);
        let report = validator.validate();
        assert!(report.is_valid);
        assert_eq!(report.diagnostics.len(), 0);
    }

    #[test]
    fn test_detect_cul_de_sac() {
        let spec = create_test_spec(
            &["start"],
            &["end"],
            &["start", "dead_end", "step1", "end"],
            &[
                ("start", "dead_end"),
                ("start", "step1"),
                ("step1", "end"),
            ],
        );
        let validator = FormalValidator::new(&spec, false);
        let report = validator.validate();
        assert!(!report.is_valid);
        assert!(report
            .diagnostics
            .iter()
            .any(|d| d.code == "CUL_DE_SAC" && d.nodes.contains(&"dead_end".to_string())));
    }

    #[test]
    fn test_detect_infinite_loop_without_escape() {
        let spec = create_test_spec(
            &["start"],
            &["end"],
            &["start", "loop_a", "loop_b", "end"],
            &[
                ("start", "loop_a"),
                ("loop_a", "loop_b"),
                ("loop_b", "loop_a"), // Livelock cycle sans transition vers 'end'
            ],
        );
        let validator = FormalValidator::new(&spec, false);
        let report = validator.validate();
        assert!(!report.is_valid);
        assert!(report
            .diagnostics
            .iter()
            .any(|d| d.code == "INFINITE_LOOP_NO_ESCAPE"));
    }

    #[test]
    fn test_loop_with_escape_is_allowed_in_standard_mode() {
        let spec = create_test_spec(
            &["start"],
            &["end"],
            &["start", "retry", "end"],
            &[
                ("start", "retry"),
                ("retry", "retry"), // Auto-boucle de réessai
                ("retry", "end"),   // Sortie possible
            ],
        );
        let validator = FormalValidator::new(&spec, false);
        let report = validator.validate();
        assert!(report.is_valid); // Valide mais avec un avertissement
        assert!(report
            .diagnostics
            .iter()
            .any(|d| d.level == DiagnosticLevel::Warning && d.code == "CYCLIC_PATH_WARNING"));
    }

    #[test]
    fn test_loop_forbidden_in_strict_dag_mode() {
        let spec = create_test_spec(
            &["start"],
            &["end"],
            &["start", "retry", "end"],
            &[
                ("start", "retry"),
                ("retry", "retry"),
                ("retry", "end"),
            ],
        );
        let validator = FormalValidator::new(&spec, true);
        let report = validator.validate();
        assert!(!report.is_valid);
        assert!(report
            .diagnostics
            .iter()
            .any(|d| d.code == "STRICT_DAG_CYCLE_FORBIDDEN"));
    }
}

